CREATE TABLE `customer_contact` (
  `coid` int NOT NULL AUTO_INCREMENT,
  `firstName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `lastName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `primaryPhoneNumber` varchar(20) DEFAULT NULL,
  `phoneNumber` varchar(1000) DEFAULT NULL,
  `primaryEmail` varchar(150) DEFAULT NULL,
  `email` varchar(1500) DEFAULT '[]',
  `accountNumber` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `tags` varchar(750) DEFAULT '[]',
  `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `address` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `country` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `state` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `postalCode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `facebook` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `instagram` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `whatsapp` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `twitter` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `voiceBiometric` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `domainId` int DEFAULT NULL,
  `mergeCustomer` int DEFAULT '0',
  `blockCustomer` int DEFAULT '0',
  `doNotDisturb` int DEFAULT '0',
  `blockCustomerReq` int DEFAULT '0',
  `doNotDisturbReq` int DEFAULT '0',
  `type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `currentCustomerNumber` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `customerType` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `Timezone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `blockedBy` int DEFAULT NULL,
  `doNotDisturbBy` int DEFAULT NULL,
  `blockedReqBy` int DEFAULT NULL,
  `doNotDisturbReqBy` int DEFAULT NULL,
  `Reason` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `cookiesId` varchar(150) DEFAULT NULL,
  `Source` varchar(250) DEFAULT NULL,
  `attachments` json DEFAULT NULL,
  `CustomerUniqueId` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`coid`),
  KEY `idx_customer_contact_1` (`coid`,`domainId`),
  KEY `idx_customer_contact_3` (`blockCustomer`,`domainId`),
  KEY `idx_customer_contact_4` (`doNotDisturb`,`domainId`),
  KEY `idx_customer_contact_5` (`primaryPhoneNumber`,`domainId`)
) /*!50100 TABLESPACE `innodb_system` */ ENGINE=InnoDB AUTO_INCREMENT=162014 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
