DROP TABLE IF EXISTS `prompt_library`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prompt_library` (
  `uuid` int NOT NULL AUTO_INCREMENT,
  `fieldname` varchar(100) DEFAULT NULL,
  `encoding` varchar(100) DEFAULT NULL,
  `mimetype` varchar(100) DEFAULT NULL,
  `filename` varchar(150) DEFAULT NULL,
  `path` longtext,
  `size` int DEFAULT NULL,
  `type` varchar(100) DEFAULT NULL,
  `promptType` int DEFAULT NULL,
  `url` longtext,
  `name` varchar(100) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `domainId` int DEFAULT NULL,
  `companyId` int DEFAULT NULL,
  `message` varchar(3000) DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `updateddAt` datetime DEFAULT NULL,
  `promptStatus` varchar(25) DEFAULT NULL,
  `queueId` int DEFAULT NULL,
  PRIMARY KEY (`uuid`),
  KEY `idx_prompt_library_1` (`uuid`,`domainId`)
) ENGINE=InnoDB AUTO_INCREMENT=7589 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
