CREATE TABLE `tb_EmailHistory` (
  `EmailHistoryId` bigint NOT NULL AUTO_INCREMENT,
  `SessionId` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `SessionStartTime` bigint DEFAULT NULL,
  `SessionEndTime` bigint DEFAULT NULL,
  `FromEmail` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `ToEmail` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `EmailSubject` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `EmailFlowSourceId` int DEFAULT NULL,
  `CompanyId` int DEFAULT NULL,
  `DomainId` int DEFAULT NULL,
  `DispositionId` int DEFAULT NULL,
  `dispositionSubject` varchar(250) DEFAULT NULL,
  `Summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `IsInBound` tinyint DEFAULT NULL,
  `AssignedTo` bigint DEFAULT NULL,
  `AssignedBy` bigint DEFAULT NULL,
  `AssignedOn` bigint DEFAULT NULL,
  `waitDuration` bigint DEFAULT NULL,
  `AfterEmailWorkTime` int DEFAULT NULL,
  `Istransferred` int DEFAULT NULL,
  `transferredTo` bigint DEFAULT NULL,
  `dispositionUpdatedBy` bigint DEFAULT NULL,
  `immediateParentId` bigint DEFAULT NULL,
  `rootParentId` bigint DEFAULT NULL,
  `TransferredTypeId` int DEFAULT NULL,
  `transferredDate` datetime DEFAULT NULL,
  `IsSessionClosed` tinyint DEFAULT NULL,
  `CustomerId` int DEFAULT NULL,
  `TicketId` bigint DEFAULT NULL,
  `SupervisorName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `repliedDate` datetime DEFAULT NULL,
  `discardedDate` datetime DEFAULT NULL,
  `CreatedAt` datetime DEFAULT NULL,
  `UpdatedAt` datetime DEFAULT NULL,
  `SentimentalScore` float DEFAULT NULL,
  `sentimentalScoreCustomer` float DEFAULT NULL,
  `sentimentalScoreAgent` float DEFAULT NULL,
  `isOpened` tinyint DEFAULT '0',
  `replyChannelType` varchar(50) DEFAULT NULL,
  `responseHistoryId` int DEFAULT NULL,
  `threadMessageId` varchar(1000) DEFAULT NULL,
  `graphMessageId` varchar(2500) DEFAULT NULL,
  `conversationId` varchar(2500) DEFAULT NULL,
  `tags` json DEFAULT NULL,
  PRIMARY KEY (`EmailHistoryId`)
) /*!50100 TABLESPACE `innodb_system` */ ENGINE=InnoDB AUTO_INCREMENT=9147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
