DROP TABLE IF EXISTS `tb_business_hours_json_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_business_hours_json_info` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fk_businessId` int DEFAULT NULL,
  `domainId` int DEFAULT NULL,
  `day_name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isHoliday` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `startTimeStamp` bigint DEFAULT NULL,
  `endTimeStamp` bigint DEFAULT NULL,
  `startTime` time DEFAULT NULL,
  `endTime` time DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `updatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_custom_hours_cid` (`fk_businessId`),
  CONSTRAINT `fk_custom_hours_cid` FOREIGN KEY (`fk_businessId`) REFERENCES `custom_hours` (`cid`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1224 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

