--
-- Table structure for table `tb_callBlast`
--

DROP TABLE IF EXISTS `tb_callBlast`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_callBlast` (
  `cid` int NOT NULL AUTO_INCREMENT,
  `campaignType` tinyint NOT NULL,
  `domainId` int DEFAULT NULL,
  `blastName` varchar(500) DEFAULT NULL,
  `blastDescription` text,
  `triggerType` tinyint DEFAULT NULL,
  `triggerDailyFile` json DEFAULT NULL,
  `triggerCustomFile` json DEFAULT NULL,
  `timeZone` varchar(500) DEFAULT NULL,
  `outboundNumber` varchar(100) DEFAULT NULL,
  `campaignMessageType` tinyint DEFAULT NULL,
  `campaignMessage` json DEFAULT NULL,
  `textSpeechFile` text,
  `promptMessage` json DEFAULT NULL,
  `connectingAudio` json DEFAULT NULL,
  `agentUnavailable` json DEFAULT NULL,
  `agentReject` json DEFAULT NULL,
  `maxDuration` int DEFAULT '0',
  `blastStatus` tinyint DEFAULT '1',
  `createdBy` int DEFAULT NULL,
  `callerId` varchar(50) DEFAULT NULL,
  `contactType` tinyint DEFAULT NULL,
  `companyName` varchar(250) DEFAULT NULL,
  `forceStop` tinyint DEFAULT '0',
  `pause` tinyint DEFAULT '0',
  `completed` int DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `updatedAt` datetime DEFAULT NULL,
  `fk_campDraftId` int DEFAULT NULL,
  PRIMARY KEY (`cid`),
