INSERT INTO `tb_outbound_campaign_draft` VALUES (1,'87946555-37bf-4ed4-b4cd-f3aad725328a',7848,'Acknowledgement','[\"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771826164777}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771826385198}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771826523725}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771826746763}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771827142418}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771827356261}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771827629425}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828056362}\", \"{\\\"message\\\":\\\"<p>Hello! How can I assist you today?</p><p>Would you like to create a new outbound campaign or update an existing one?</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828056360}\", \"{\\\"message\\\":\\\"i want to create a campaign\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828113095}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828490494}\", \"{\\\"message\\\":\\\"<p>Hello! 👋 How can I assist you today with your outbound campaign? You can create a new campaign, update an existing one, or ask any questions you have.</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828490491}\", \"{\\\"message\\\":\\\"i want to create a campaign\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828514174}\", \"{\\\"message\\\":\\\"<p>Great! Let\'s start by giving your campaign a name. Please provide a name using only letters (no numbers). It should be unique as there are no other active campaigns right now.</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828514171}\", \"{\\\"message\\\":\\\"New tools campaign\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828558031}\", \"{\\\"message\\\":\\\"<p>Could you provide a short description for the campaign? This is optional; you can skip if you prefer.</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828558029}\", \"{\\\"message\\\":\\\"skip\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828567733}\", \"{\\\"message\\\":\\\"<p>What type of trigger would you like for this campaign? Please choose one of the following options:<br>• <strong>Immediate</strong> – the campaign will start right away.<br>• <strong>Daily</strong> – schedule the campaign to run on specific days.<br>• <strong>Only Once</strong> – schedule a one‑time call.<br>Enter <em>immediate</em>, <em>daily</em>, or <em>only once</em>.</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828567731}\", \"{\\\"message\\\":\\\"immediate\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828587656}\", \"{\\\"message\\\":\\\"hii\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828764883}\", \"{\\\"message\\\":\\\"<p>Hello! How can I assist you today? Would you like to create a new outbound campaign or update an existing one?</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828764881}\", \"{\\\"message\\\":\\\"create a new one\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828967867}\", \"{\\\"message\\\":\\\"<p>Great! Let\'s start with the campaign name. Please provide a name for your campaign (letters only, no numbers).</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828967865}\", \"{\\\"message\\\":\\\"New tool campaign\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828981302}\", \"{\\\"message\\\":\\\"<p>Thanks for the name \\\\\\\"New tool campaign\\\\\\\".</p><p>Could you provide a short description for this campaign? (You can skip this if you prefer.)</p>\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"isBot\\\":1,\\\"messageId\\\":1771828981300}\", \"{\\\"message\\\":\\\"skip\\\",\\\"sessionId\\\":\\\"87946555-37bf-4ed4-b4cd-f3aad725328a\\\",\\\"uploadUrl\\\":null,\\\"isBot\\\":0,\\\"messageId\\\":1771828991245}\", \"{\\\"message\\\":\\\"<p>Got it! You’d like to skip the description.</p><p>Please let me know the trigger type for this campaign. Would you like it to start <strong>immediately</strong>, be scheduled <strong>daily</strong>, or run <strong>only once</stron