  startTmpstmp bigint,endTmpstmp bigint,domainId int,type int,ext int) RETURNS int
    DETERMINISTIC
Begin
         
         	declare v_output_value bigint;
         	
             
         	if type = 1 then 
            
  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  				select count(ifnull(a.sessionStartTime,0)) into v_output_value
  				FROM sessionHistory a
  				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)
  				and a.callType is not null and (a.agentDetails = ext or ifnull(ext,0)=0)
  				and a.sessionStartTime <> 0 and a.domainId = domainId and a.channelType = 'Call';
  				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
         	end if;
            
             
         	if type = 2 then
            
  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  				select count(ifnull(a.sessionStartTime,0)) into v_output_value
  				FROM sessionHistory a
  				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0) 
  				and a.callType = 'inbound' and channelType is not null
  				and a.callType is not null and (a.agentDetails = ext or ifnull(ext,0)=0)
  				and a.sessionStartTime <> 0 and a.domainId = domainId and a.channelType = 'Call'; 	
  				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
         	end if;
             
             
         	if type = 3 then
            
  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  				select count(ifnull(a.sessionStartTime,0)) into v_output_value
  				FROM sessionHistory a
  				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0) 
  				and a.callType = 'outbound' 
  				and a.callType is not null and (a.agentDetails = ext or ifnull(ext,0)=0)
  				and a.sessionStartTime <> 0 and a.domainId = domainId and a.channelType = 'Call';    
  				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
         	end if;
             
             
         	if type = 4 then
            
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
         	
 				select ifnull(count(a.shid),0)  into v_output_value from 
 				sessionHistory a
 				where a.dialDuration between 1 and 30000 
 				and a.queueName = queueName and a.agentName = agentName 
 				and a.domainId = domainId and a.dialDuration is not null 
 				and a.callType is not null and a.channelType  is not null 
 				and a.sessionStartTime <> 0 and (a.agentDetails = ext or ifnull(ext,0)=0)
 				and (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0); 
               
   			          			              
                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
         	end if;    
             
              
         	if type = 5 then
            
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 				select sum(a.agentDisconnectTime - a.agentConnectTime)/1000 into v_output_value 
 				FROM sessionHistory a
 				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0) 		
 				and dialDuration > 0 and (a.agentDetails = ext or ifnull(ext,0)=0)
 				and a.callType is not null and a.channelType is not null 
 				and a.agentConnectTime <> 0 and a.agentDisconnectTime <> 0 
 				and a.sessionStartTime <> 0 and a.domainId = domainId; 
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
         	end if;
         	
             
             if type = 6 then
             
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  			
 				select sum(a.logOutTimestamp - a.logInTimestamp)/1000 into v_output_value 
 				FROM logInSessionHistory a   			
 				where (a.logInTimestamp = startTmpstmp and a.logOutTimestamp = endTmpstmp or ifnull(endTmpstmp,0)=0)			 			
 				and a.logInTimestamp <> 0 and a.logOutTimestamp <> 0 and a.domainId = domainId; 
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
         	end if;
            
             
              
        	if type = 7 then
                 
  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  			select count(ifnull(a.sessionStartTime,0)) into v_output_value
  			FROM sessionHistory a
  			where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)              
  			and a.callType = 'inbound' and a.callType is not null and (a.agentDetails = ext or ifnull(ext,0)=0)
  			and status not in ('connected','Agent on Hold','hold') and status is not null 
  			and a.sessionStartTime <> 0 and a.domainId = domainId and a.channelType = 'Call'; 			
  			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
        
        	end if;      
                
        	
                
        	if type = 8 then
                 
        			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
        			select count(ifnull(a.sessionStartTime,0)) into v_output_value
        			FROM sessionHistory a
        			where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)              
        			and a.callType = 'inbound' and a.callType is not null and (a.agentDetails = ext or ifnull(ext,0)=0)
        			and disposition in ('abandoned') and disposition is not null 
        			and a.sessionStartTime <> 0 and a.domainId = domainId and a.channelType = 'Call'; 			
        			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
                     
        	end if;      
            
        	
                
        	if type = 9 then
                 
         			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
         			select count(ifnull(a.transferred,0)) into v_output_value
         			FROM sessionHistory a
     				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)  			
         			and a.transferred <> 0 and a.transferred is not null and a.callType = 'inbound'
 					and (a.agentDetails = ext or ifnull(ext,0)=0)
         			and a.domainId = domainId and a.channelType = 'Call'; 
         			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
                     
        	end if;      
                
        	
                
            if type = 10 then		
                  
  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;       			
 				select sum(ifnull(a.afterCallWorkTime/1000,0)) into v_output_value
        			FROM sessionHistory a
        			where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)                      
        			and a.afterCallWorkTime is not null and a.agentConnectTime is not null
  				and (a.agentDetails = ext or ifnull(ext,0)=0)
        			and a.domainId = domainId and a.channelType is not null;           			
        			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                
                        
            End if;    
                
             
             
         	if type = 11 then 
            
  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    			
  				select count(ifnull(a.agentConnectTime,0)) into v_output_value            
  				FROM sessionHistory a 
  				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)  
  				and a.callType is not null and a.channelType is not null
  				and (a.agentDetails = ext or ifnull(ext,0)=0)				
  				and a.sessionStartTime <> 0 and a.agentConnectTime <> 0 
  				and a.domainId = domainId;
  				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
         	end if;    
                
             
             
        		if type = 12 then
        			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  				select sum(ifnull(a.agentHoldDuration/1000,0)) into v_output_value
  				FROM sessionHistory a
  				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)                      
  				and a.agentHoldDuration <> 0 and (a.agentDetails = ext or ifnull(ext,0)=0)
  				and a.domainId = domainId and a.channelType = 'Call';           			
        			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        		End if;    
                
               
             
        		if type = 13 then
        			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
        			select sum(ifnull(a.callDuration/1000,0)) into v_output_value
        			FROM sessionHistory a
  				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)                      
        			and a.callDuration <> 0 and a.callType is not null 
  				and (a.agentDetails = ext or ifnull(ext,0)=0)
        			and a.domainId = domainId and a.channelType = 'Call';           			
        			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        		End if;      
               
               
               
               if type = 14 then              
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 				select sum(ifnull(a.stateDuration/1000,0)) into v_output_value
 				from state_timer a where a.state  not in ('Not Ready','Away','Offline')				
 				and (a.ext = ext or ifnull(ext,0)=0) and a.domainId = domainId; 
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              end if; 
               
               
               
               if type = 15 
               then            
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
 				select count(json_length(ifnull(a.queueList,0))) into v_output_value
 				from queueWeighTime a
 				where a.domainId = domainId and a.queueType is not null 
 				group by a.domainid;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              end if; 
             
               
               
               
               if type = 16 
               then            
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
 				select ifnull(sum(a.dialDuration)/1000,0) into v_output_value
 				from  sessionHistory a
 				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)                      
 				and (a.agentDetails = ext or ifnull(ext,0)=0) and a.domainId = domainId 
 				and a.dialDuration is not null and a.channelType is not null; 
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              end if; 
              
               
              
   			if type = 17 
               then            
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
 				select ifnull(sum(a.waitDuration)/1000,0)  into v_output_value
 				from  sessionHistory a
 				where (a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp or ifnull(endTmpstmp,0)=0)                      
 				and (a.agentDetails = ext or ifnull(ext,0)=0) and a.domainId = domainId 
 				and a.waitDuration is not null and a.channelType is not null; 
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              end if; 
             
             return if(v_output_value=0,null,v_output_value);
             
         End ;;
DELIMITER ;
