CREATE DEFINER=`dbdev`@`%` PROCEDURE `auto_kill_blocking_callhistoryqueries`()
Begin
	declare v_cnt int;
	declare v_tcnt int;
	declare v_PROCESSLIST_ID int;

	drop temporary table if exists tt_OWNER_THREAD_ID ;
	create temporary table tt_OWNER_THREAD_ID 
	(
	id int auto_increment primary key,
	PROCESSLIST_ID bigint unsigned 
	);

	insert into tt_OWNER_THREAD_ID(PROCESSLIST_ID)
	SELECT PROCESSLIST_ID 
	FROM performance_schema.threads 
	WHERE THREAD_ID in(SELECT OWNER_THREAD_ID FROM performance_schema.metadata_locks where OBJECT_NAME = 'tb_CallHistory'); 

	set v_cnt = 1;
	select count(*) into v_tcnt from tt_OWNER_THREAD_ID;

	while v_cnt <= v_tcnt do 

		select PROCESSLIST_ID into v_PROCESSLIST_ID from tt_OWNER_THREAD_ID where id = v_cnt;

		SET @sql = CONCAT('KILL ', v_PROCESSLIST_ID);
			PREPARE stmt FROM @sql;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;

		set v_cnt = v_cnt + 1 ;
	End while;
    
    
End ;;
DELIMITER ;
