CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_delete_BroadCastAgentDtl`(
	p_domainId INT,
	p_bcGroupName VARCHAR(150),
    p_bcMembers	VARCHAR(200)
)
BEGIN
	
    DECLARE v_errMsg	VARCHAR(100) DEFAULT "Failed";
    DECLARE v_errCode	INT DEFAULT 0;
    DECLARE v_MemberDtl	VARCHAR(200);
    
    SELECT bcMembers INTO v_MemberDtl FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcGroupName = BINARY p_bcGroupName;
    
    CALL split(v_MemberDtl, ",");
    
    DROP TEMPORARY TABLE IF EXISTS tt_UserDtl;
    CREATE TEMPORARY TABLE tt_UserDtl(UserId INT);
    
    INSERT INTO tt_UserDtl(UserId)
    SELECT items FROM tt_Split_temptable WHERE items NOT LIKE CONCAT("%",p_bcMembers,"%");
    
    SELECT GROUP_CONCAT(UserId SEPARATOR ',') INTO v_MemberDtl FROM tt_UserDtl;
    
    UPDATE tb_BroadcastHistory_dtl
    SET bcMembers = v_MemberDtl
	 WHERE domainId = p_domainId AND bcGroupName = BINARY p_bcGroupName;
     
     IF ROW_COUNT() > 0 THEN
		SET v_errCode = 2;
        SET v_errMsg = "Deleted Successfully";
	END IF;
    
    SELECT  v_errCode AS errCode, v_errMsg AS errMsg;
END ;;
DELIMITER ;
