CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_delete_BroadCastExpiredMessage`()
BEGIN
		DELETE FROM  tb_BroadcastDurationhistory_dtl
        WHERE expiryDate < now();
        
END ;;
