CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `bc_delete_BroadCastGroupMessage`(
 	p_bcDurationHistoryId   INT,
     p_bcHistoryId			INT,
     p_domainId				INT
 )
BEGIN
	DECLARE v_errMsg		VARCHAR(100) DEFAULT "Failed";
	DECLARE v_errCode		INT DEFAULT 0;
	DECLARE v_flag_1		TINYINT DEFAULT 0;
                         
	DELETE FROM tb_BroadcastChatParticipant WHERE bcDurationHistoryId = p_bcDurationHistoryId;

	DELETE FROM tb_BroadcastDurationhistory_dtl WHERE bcDurationHistoryId = p_bcDurationHistoryId;

	IF ROW_COUNT() > 0 
    THEN
		SET v_errCode = 3;
		SET v_errMsg = "Deleted Successfully";
	END IF;         
         
	SELECT v_errCode AS errCode, v_errMsg AS errMsg;
 END ;;
DELIMITER ;
