DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `bc_get_AllGroupDtl`(
 	p_domain INT,
	p_userId INT				
 )
SP:BEGIN
	DROP TEMPORARY TABLE IF EXISTS tt_Group;
	CREATE TEMPORARY TABLE tt_Group(
		bcHistoryId				INT
        ,bcGroupName			VARCHAR(150)
        ,LastUpdated			DATETIME
        ,bcDurationHistoryId	INT
        ,UnReadCount			SMALLINT DEFAULT 0
    );
 
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	IF p_userId IS NOT NULL 
    THEN
		INSERT INTO tt_Group(
			bcHistoryId			
			,bcGroupName		
			,LastUpdated		
			,bcDurationHistoryId
            ,UnReadCount
        )
		SELECT 	H.bcHistoryId
			, 	H.bcGroupName     
            ,	MAX(IFNULL(DH.updatedOn,DH.createdOn))	AS LastUpdated
            ,	MAX(DH.bcDurationHistoryId)				AS bcDurationHistoryId	
            ,	SUM(CASE WHEN CP.msgStatus <> 2 THEN 1 ELSE 0 END)	AS UnReadCount
        FROM 	tb_BroadcastHistory_dtl			H
        JOIN 	tb_BroadcastDurationhistory_dtl	DH	ON DH.bcHistoryId 			= H.bcHistoryId
        JOIN 	tb_BroadcastChatParticipant 	CP	ON CP.bcDurationHistoryId	= DH.bcDurationHistoryId
        WHERE 	CP.agentId	= p_userId
        AND		H.domainId	= p_domain
        GROUP BY H.bcHistoryId,	H.bcGroupName;
        
		UPDATE 	tt_Group						H
		JOIN 	tb_BroadcastDurationhistory_dtl	DH	ON DH.bcHistoryId 			= H.bcHistoryId
		JOIN 	tb_BroadcastChatParticipant 	CP	ON CP.bcDurationHistoryId	= DH.bcDurationHistoryId
		SET		CP.msgStatus	= 1
			,	CP.updatedAt	= NOW()
		WHERE 	CP.agentId		= p_userId		
		AND		CP.msgStatus	= 0;        
        
        DROP TEMPORARY TABLE IF EXISTS tt_Group1;        
        CREATE TEMPORARY TABLE tt_Group1 SELECT * FROM tt_Group;
        
        INSERT INTO tt_Group(
			bcHistoryId			
			,bcGroupName		
			,LastUpdated					
        )
        SELECT 	H.bcHistoryId
			, 	H.bcGroupName     
            ,	IFNULL(H.updatedOn,H.createDate)	AS LastUpdated            
        FROM 	tb_BroadcastHistory_dtl	H
        LEFT JOIN tt_Group1				G	ON G.bcHistoryId = H.bcHistoryId
        WHERE 	H.domainId		= p_domain   
        AND  	FIND_IN_SET(p_userId,H.bcMembers) > 0
        AND 	G.bcHistoryId 	IS NULL;
	ELSE
		INSERT INTO tt_Group(
			bcHistoryId			
			,bcGroupName		
			,LastUpdated		
			,bcDurationHistoryId        
        )
        SELECT 	H.bcHistoryId
			, 	H.bcGroupName     
            ,	MAX(COALESCE(DH.updatedOn,DH.createdOn,H.updatedOn,H.createDate))	AS LastUpdated
            ,	MAX(DH.bcDurationHistoryId)				AS bcDurationHistoryId	
        FROM 	tb_BroadcastHistory_dtl			H
        LEFT JOIN 	tb_BroadcastDurationhistory_dtl	DH	ON DH.bcHistoryId = H.bcHistoryId        
        WHERE 	H.domainId	= p_domain
        GROUP BY H.bcHistoryId,	H.bcGroupName;		
    END IF;
    
    SELECT 	G.bcHistoryId, G.bcGroupName, DH.message, G.LastUpdated, G.UnReadCount
    FROM 	tt_Group G
    LEFT JOIN tb_BroadcastDurationhistory_dtl DH ON DH.bcDurationHistoryId = G.bcDurationHistoryId
    ORDER BY LastUpdated DESC;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
 END ;;
DELIMITER ;
