CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_get_BroadCastAgentDtl`(
	p_domainId INT,
	p_bcGroupName VARCHAR(150),
    p_bcMembers	INT

)
BEGIN
		DECLARE v_bcMembers VARCHAR(200);
        DECLARE v_bcHistoryId INT;
        DECLARE v_UserCount INT;
        
		IF EXISTS (SELECT 1 FROM tb_BroadcastHistory_dtl WHERE domainId = domainId AND bcGroupName = BINARY p_bcGroupName) THEN
				
                SELECT bcHistoryId INTO v_bcHistoryId FROM tb_BroadcastHistory_dtl WHERE domainId = domainId AND bcGroupName = BINARY p_bcGroupName;
                
               
                
                SELECT bcMembers INTO v_bcMembers FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcHistoryId = v_bcHistoryId;
                
              
    
		DROP TEMPORARY TABLE IF EXISTS tt_UserDtl;
		CREATE TEMPORARY TABLE tt_UserDtl(UserId INT, domainId INT, UserName VARCHAR(150));
    
		CALL Split(v_bcMembers,',');
    
		INSERT INTO tt_UserDtl(UserId, domainId, UserName)
		SELECT t1.items, p_domainId, t2.UserName 
			FROM tt_Split_temptable t1
			JOIN tb_User t2 ON t2.domainId = p_domainId AND t1.items = t2.UserID
            WHERE (items = p_bcMembers OR IFNULL(p_bcMembers,'')='');
            
		SELECT COUNT(*) INTO v_UserCount  FROM tt_UserDtl; 
                
                SELECT 
                
					t1.bcHistoryId,
                    t1.bcGroupName,
                    t1.domainId,
                    GROUP_CONCAT(CONCAT(t2.bcDurationHistoryId,":",t2.message)) AS message,
                    (SELECT GROUP_CONCAT( CONCAT(UserId ,":", UserName) separator ",") FROM tt_UserDtl) AS agentIds,
                    v_UserCount as UserCount
                    
                    
                    
                   
                    
				FROM tb_BroadcastHistory_dtl 			AS t1
                LEFT JOIN tb_BroadcastDurationhistory_dtl	AS t2 ON t1.bcHistoryId = t2.bcHistoryId
                LEFT JOIN tb_BroadcastChatParticipant		AS t3 ON t2.bcDurationHistoryId = t3.bcDurationHistoryId
                WHERE t1.domainId = p_domainId AND t1.bcHistoryId = v_bcHistoryId
                GROUP BY t1.bcHistoryId,t1.bcGroupName,t1.domainId
                ;
					
				
    
        
        ELSE
			
            SELECT null AS "result";
			
        END IF;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
