CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `bc_get_broadCastGroupMessageDtl`(
	p_domainId 			INT,
	p_bcHistoryId 		INT,
	p_agentId			INT
 )
BEGIN 		
	IF p_agentId IS NOT NULL THEN
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		SELECT  BCP.agentId , BDH.bcDurationHistoryId, BDH.message
		FROM 	tb_BroadcastDurationhistory_dtl AS BDH
		JOIN 	tb_BroadcastChatParticipant 	AS BCP ON BDH.bcDurationHistoryId = BCP.bcDurationHistoryId
		WHERE 	BDH.bcHistoryId = p_bcHistoryId 
        AND 	BDH.domainId 	= p_domainId 
        AND 	BCP.agentId 	= p_agentId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
        UPDATE 	tb_BroadcastDurationhistory_dtl AS BDH
		JOIN 	tb_BroadcastChatParticipant 	AS BCP ON BDH.bcDurationHistoryId = BCP.bcDurationHistoryId
        SET 	BCP.msgStatus	= 2
		WHERE 	BDH.bcHistoryId = p_bcHistoryId 
        AND 	BDH.domainId 	= p_domainId 
        AND 	BCP.agentId 	= p_agentId
        AND 	BCP.msgStatus	<> 2;
	ELSE
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		SELECT 	BDH.bcDurationHistoryId, BDH.message
			,	(CASE 	WHEN EXISTS(SELECT 1 FROM tb_BroadcastChatParticipant InP WHERE InP.bcDurationHistoryId = BDH.bcDurationHistoryId	AND InP.msgStatus = 0) THEN 0
						WHEN EXISTS(SELECT 1 FROM tb_BroadcastChatParticipant InP WHERE InP.bcDurationHistoryId = BDH.bcDurationHistoryId	AND InP.msgStatus = 1) THEN 1
                        WHEN EXISTS(SELECT 1 FROM tb_BroadcastChatParticipant InP WHERE InP.bcDurationHistoryId = BDH.bcDurationHistoryId	AND InP.msgStatus = 2) THEN 2 END) AS msgStatus
		FROM 	tb_BroadcastDurationhistory_dtl 	AS BDH
		WHERE 	BDH.bcHistoryId	= p_bcHistoryId 
        AND 	BDH.domainId 	= p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
	END IF;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
