CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_get_broadCastGroupSearchAgentName`(
	p_bcMembers		VARCHAR(200),
    p_bcHistoryId		INT,
    p_domainId		INT
)
BEGIN
	
    DECLARE v_AgentId varchar(200) ;
    
    SELECT bcMembers INTO v_AgentId FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcHistoryId = p_bcHistoryId;
    
    call split(v_AgentId,",");
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SELECT t2.UserName
    FROM tt_Split_temptable as t1
    JOIN tb_User AS t2 
    ON t1.items = t2.myAccUserId
    WHERE t2.domainId = p_domainId AND t2.UserName LIKE CONCAT("%",IFNULL(p_bcMembers,''),"%");
    
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
END ;;
