CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_insert_BroadCastGroupMessage`(
    p_bcHistoryId		INT,
    p_domainId			INT,
	p_message 			JSON,
    p_AgentId			VARCHAR(200),
    p_expiryDate		DATETIME,
    p_sendTimestamp		BIGINT
)
BEGIN
		DECLARE v_errMsg varchar(100) DEFAULT "Failed";
        DECLARE v_errCode INT DEFAULT 0;
        DECLARE v_insertId	INT DEFAULT -1;
        DECLARE v_flag	TINYINT DEFAULT 0;
        DECLARE v_AgentIds	VARCHAR(200);
    
IF EXISTS(SELECt 1 FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcHistoryId = p_bcHistoryId) THEN

  SELECT bcMembers INTO v_AgentIds FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcHistoryId = p_bcHistoryId;
  
    INSERT INTO tb_BroadcastDurationhistory_dtl
		( bcHistoryId, message, expiryDate, domainId, sendTimestamp)
    VALUES( p_bcHistoryId, p_message, p_expiryDate, p_domainId, p_sendTimestamp);
    
    IF ROW_COUNT() > 0 THEN 
		SET v_errMsg = "Inserted";
        SET v_errCode = "1";
        SET v_insertId = last_insert_id();
        SET v_flag = v_flag+1;
	END IF;
    END IF;
    IF v_AgentIds IS NOT NULL THEN 
    
		DROP temporary TABLE IF EXISTS tt_UserId;
		CREATE temporary TABLE  tt_UserId(UserId int);
		
        call Split(v_AgentIds , ",");
        
        INSERT INTO tt_UserId(UserId)
        SELECT items FROM tt_Split_temptable;
        
        INSERT INTO tb_BroadcastChatParticipant(bcDurationHistoryId, agentId)
        SELECT v_insertId, UserId FROM tt_UserId;
        
        IF row_count() > 0 THEN 
			SET v_flag = v_flag+1;
        END IF;
	END IF;
    
    IF v_flag = 2 THEN 
		SELECT v_errCode AS errCode, v_errMsg AS errMsg, v_insertId AS bcDurationHistoryId;
	ELSE
		SELECT 0 AS errCode, "Failed" AS errMsg, -1 AS bcDurationHistoryId;
	END IF;
  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
