CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_insert_createBroadCastGroup`(
p_domainId INT,
p_bcHistoryId INT,
p_bcGroupName VARCHAR(150),
p_bcMembers TEXT,
p_createBy INT
)
BEGIN
	DECLARE v_errMsg	VARCHAR(100) DEFAULT "Failed";
    DECLARE v_errCode	INT DEFAULT 0;
    DECLARE v_ex_bcMembers	VARCHAR(200);
    
    IF (p_bcHistoryId IS NULL) THEN
		IF NOT EXISTS(SELECT 1 FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcGroupName = p_bcGroupName) THEN
			
            INSERT INTO tb_BroadcastHistory_dtl (domainId, bcGroupName, bcMembers, createBy) 
			VALUES( p_domainId, p_bcGroupName, p_bcMembers, p_createBy);
    
		IF row_count() > 0 THEN 
    
			SET v_errMsg = "Inserted Successfully";
			SET v_errCode = 1;
        
		END IF;
    END IF;
    
    ELSEIF EXISTS(SELECT 1 FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcHistoryId = p_bcHistoryId) THEN
			
            SELECT bcMembers INTO v_ex_bcMembers FROM tb_BroadcastHistory_dtl WHERE domainId = p_domainId AND bcHistoryId = p_bcHistoryId;
            
            IF v_ex_bcMembers IS NULL THEN 
				UPDATE tb_BroadcastHistory_dtl 
					SET bcMembers = p_bcMembers
                    WHERE domainId = p_domainId AND bcHistoryId = p_bcHistoryId;
                    
                    IF row_count() > 0 THEN
						SET v_errCode = 2;
                        SET v_errMsg = "Updated Successfuly";
					END IF;
			ELSE 
				UPDATE tb_BroadcastHistory_dtl 
					SET bcMembers = CONCAT(v_ex_bcMembers,",",P_bcMembers)
                    WHERE domainId = P_domainId AND bcHistoryId = p_bcHistoryId;
                    
                    IF row_count() > 0 THEN
						SET v_errCode = 2;
                        SET v_errMsg = "Updated Successfuly";
					END IF;
                    
			END IF;
    
    END IF;
    
    
    SELECT v_errCode AS errCode, v_errMsg AS errMsg;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
