CREATE DEFINER=`dbdev`@`%` PROCEDURE `bc_update_addAgentInExistingGroup`(
	P_bcMembers 		VARCHAR(200),
    P_domainId			INT,
    p_bcHistoryId		INT
)
BEGIN
		DECLARE v_errCode		INT DEFAULT 0;
        DECLARE v_errMsg		VARCHAR(100) DEFAULT "Failed";
        DECLARE v_ex_bcMembers	VARCHAR(200);
        
        SELECT bcMembers INTO v_ex_bcMembers FROM tb_BroadcastHistory_dtl WHERE domainId = P_domainId AND  bcHistoryId = p_bcHistoryId;
        
        IF v_ex_bcMembers IS NULL THEN 
				UPDATE tb_BroadcastHistory_dtl 
					SET bcMembers = P_bcMembers
