		ELSE 
				UPDATE tb_BroadcastHistory_dtl 
					SET bcMembers = CONCAT(v_ex_bcMembers,",",P_bcMembers)
                    WHERE domainId = P_domainId AND  bcHistoryId = p_bcHistoryId;
                    
                    IF row_count() > 0 THEN
						SET v_errCode = 2;
                        SET v_errMsg = "Updated Successfuly";
					END IF;
		END IF;
        
        SELECT v_errCode AS "errCode", v_errMsg AS "errMsg";
END ;;
