CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `CallTypeUpdate`(
  IN p_domainId 			INT,
  IN	p_ext 				INT,
  IN p_callType 			VARCHAR(50)
  )
BEGIN
   DECLARE v_CurDate 	DATETIME;
   DECLARE v_errcode 	INT          DEFAULT -1;
   DECLARE v_errmsg  	VARCHAR(100) DEFAULT 'No Update';
   DECLARE v_callTypeId	INT;
   
   set v_CurDate = now();
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   
 	SELECT 	TypeCodeID INTO v_callTypeId
     FROM 	TypeCode
     WHERE 	TypeCode = p_callType
     and     TypeGroupID = 1120;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      UPDATE tb_User
      SET  callTypeId 			= IFNULL(v_callTypeId,callTypeId)
 		, updatedAt 			= v_CurDate
      WHERE ext 					= p_ext
      and   domainId				= p_domainId;
      
      IF ROW_COUNT() > 0
      THEN
 		 SET v_errcode = 0;
          SET v_errmsg = 'Updated Successfully';
      END IF;
      
      SELECT v_errcode errcode,  v_errmsg errmsg; 
  END ;;
DELIMITER ;
