CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaasAi_get_data_and_privacy_set`(
 		p_domainId						INT,
 		p_companyId						INT,
 		p_userId						INT
 )
BEGIN
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 
 				SELECT 
 						privacy_id
 						,domainId
 						,companyId
 						,userId
