CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaasAi_insert_update_data_and_privacy_set`(	p_domainId						INT,
    p_companyId						INT,
    p_userId						INT,
    p_isWorktualDestopApp			TINYINT  ,			
    p_isContentAnalysis				TINYINT  ,			
    p_isConnectedApps				TINYINT 			
    )
BEGIN
		
        DECLARE v_errCode		TINYINT DEFAULT -1;
        DECLARE v_errMsg		varchar(50) DEFAULT "Failed";
		
        IF NOT EXISTS(SELECT 1 FROM ccaas_tb_data_privacy_settings WHERE domainId = p_domainId AND companyId = p_companyId AND userId = p_userId ) THEN
        
			INSERT INTO ccaas_tb_data_privacy_settings(domainId, companyId	, userId	, isWorktualDestopApp , isContentAnalysis, isConnectedApps, createdOn)
            VALUES( p_domainId, p_companyId	, p_userId	, p_isWorktualDestopApp , p_isContentAnalysis, p_isConnectedApps, now());
            
            IF ROW_COUNT() > 0 THEN
				SET v_errCode = 0;
                SET v_errMsg = "Inserted Successfully";
			END IF;
        
        ELSE
			
            UPDATE ccaas_tb_data_privacy_settings
				SET
                    isWorktualDestopApp				= 	IFNULL(p_isWorktualDestopApp, isWorktualDestopApp),
					isContentAnalysis				= 	IFNULL(p_isContentAnalysis, isContentAnalysis),
					isConnectedApps					= 	IFNULL(p_isConnectedApps, isConnectedApps)
            WHERE  	domainId  = 	p_domainId  AND companyId =	p_companyId AND  userId	= 	p_userId;
				
                IF ROW_COUNT() > 0 THEN
					SET v_errCode = 1;
					SET v_errMsg = "Updated Successfully";
				END IF;
            
        END IF;
		
		SELECT v_errCode AS errCode, v_errMsg AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
