CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaass_get_chat_sessionid_dao`(p_ChatHistoryId		BIGINT	)
BEGIN
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
			SELECT 
						ChatHistoryId,
						sessionId,
						sessionStartTime,
						sessionEndTime,
						chatFlowSourceId,
						companyId,
						domainId,
						IsInBound,
						IsMissed,
						dialDuration,
						disconnectedBy,
						queueDuration,
						assignedTo,
						assignedBy,
						assignedOn,
						discardedDate,
						repliedDate,
						CustomerId,
						Browser,
						IPAdress,
						ChatSubject,
						Location,
						DeviceType,
						createdAt,
						updatedAt,
						CallBackStatus,
						chatWidgetId,
						chatUniqIdentifier,
						CallBackChatHistoryId,
                        null AS dispositionId 
            FROM tb_ChatHistory WHERE ChatHistoryId = p_ChatHistoryId;
            
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
            
            
END ;;
