DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_customer_overall_callback_inner_sp`(	
       	p_domainId 			INT
)
BEGIN

			drop temporary table if exists temp_getcallback_list;
			create temporary table temp_getcallback_list
			(	
				 id_col 				INT AUTO_INCREMENT PRIMARY KEY 
				,domainId 				INT 
				,CustomerId 			INT 
                ,customerNumber			VARCHAR(20)
				,channelType 			VARCHAR(100) 
				,HistoryId 				INT 
				,DurationHistoryId 		INT 
                ,isAnswered				TINYINT
				,CallBackStatus 		TINYINT					
				,IsMissed 				TINYINT
                ,createdAt				DATETIME
                ,rn						INT
			);

			ALTER TABLE temp_getcallback_list
			ADD INDEX idx_domain (domainId),
			ADD INDEX idx_customerid (CustomerId),
            ADD INDEX idx_customernumber (customerNumber),
			ADD INDEX idx_History (HistoryId),
			ADD INDEX idx_DurationHistoryId (DurationHistoryId),
			ADD INDEX idx_createdAt(createdAt);

			INSERT IGNORE INTO temp_getcallback_list(domainId, CustomerId,channelType,HistoryId,DurationHistoryId,isAnswered,CallBackStatus,IsMissed,createdAt, rn)
			SELECT  cth.domainId, cth.CustomerId, 'Chat', cdh.ChatHistoryId, cdh.ChatDurationHistoryId, CASE WHEN cdh.Duration > 0 THEN 1 ELSE 0 END ,cth.CallBackStatus, cdh.IsMissed, cdh.createdAt , row_number() over(partition by cth.CustomerId order by cdh.ChatDurationHistoryId desc)
			FROM 	tb_ChatHistory 						cth
			JOIN 	tb_ChatDurationHistory				cdh 	ON cdh.ChatHistoryId 	= cth.ChatHistoryId
			WHERE 	cth.domainId = p_domainId
            AND 	cdh.AgentId is not null
            AND 	IFNULL(cth.CustomerId,0) <> 0
            ORDER BY cdh.ChatDurationHistoryId DESC; 
         	                             						  
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
            
            DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_call;
            CREATE TEMPORARY TABLE temp_getcallback_list_call LIKE temp_getcallback_list;
            
			INSERT IGNORE INTO temp_getcallback_list_call(domainId, CustomerId, customerNumber, channelType, HistoryId, DurationHistoryId, isAnswered, CallBackStatus, IsMissed, createdAt)
			SELECT 	clh.domainId, clh.CustomerId, clh.customerNumber, 'Call', cdh.CallHistoryId, cdh.CallDurationHistoryId, CASE WHEN cdh.Duration > 0 THEN 1 ELSE 0 END, clh.callBack, cdh.IsMissedCall, cdh.createdAt
			FROM tb_CallHistory 				clh
			JOIN tb_CallDurationHistory			cdh ON clh.CallHistoryId = cdh.CallHistoryId
			WHERE 	clh.domainId 	= p_domainId
            AND cdh.AgentId is not null;
			            
			UPDATE 	temp_getcallback_list_call		H
			JOIN customer_contact					CC	ON H.customerNumber = CC.primaryPhoneNumber AND H.domainId = CC.domainId				
			SET H.CustomerId = IFNULL(H.CustomerId,CC.coid);
			            
            INSERT IGNORE INTO temp_getcallback_list(domainId, CustomerId,channelType,HistoryId,DurationHistoryId,isAnswered,CallBackStatus,IsMissed,createdAt, rn)
            SELECT domainId, CustomerId, channelType, HistoryId, DurationHistoryId, isAnswered, CallBackStatus, IsMissed, createdAt, row_number() over(partition by CustomerId order by DurationHistoryId desc)
            FROM temp_getcallback_list_call
            WHERE  IFNULL(CustomerId,0) <> 0;
            					 
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                                                                                        
			INSERT INTO temp_getcallback_list(domainId, CustomerId,channelType,HistoryId,DurationHistoryId,isAnswered,CallBackStatus,IsMissed,createdAt, rn)
			SELECT 	wh.domainId, wh.customerId, 'Whatsapp', wd.WhatsappHistoryId, wd.WhatsappDurationHistoryId, CASE WHEN wd.Duration > 0 THEN 1 ELSE 0 END, wh.isCallback, wd.IsMissed, wd.createdAt, row_number() over(partition by wh.CustomerId order by wd.WhatsappDurationHistoryId desc)
			FROM tb_WhatsappHistory 			wh
			JOIN tb_WhatsappDurationHistory 	wd ON wh.WhatsappHistoryId = wd.WhatsappHistoryId
			WHERE wh.domainId = p_domainId
            AND  IFNULL(wh.CustomerId,0) <> 0
            AND wd.AgentId is not null;
            													
			INSERT INTO temp_getcallback_list(domainId, CustomerId,channelType,HistoryId,DurationHistoryId,isAnswered,CallBackStatus,IsMissed,createdAt, rn)
			SELECT 	fb.domainId, fb.customerId, 'Facebook', fb.FacebookHistoryId, fb.FacebookHistoryId, CASE WHEN fb.Duration > 0 THEN 1 ELSE 0 END, fb.isCallback, fb.IsMissed, fb.createdAt, row_number() over(partition by fb.CustomerId order by fb.FacebookHistoryId desc)
			FROM tb_FacebookHistory 	fb
			WHERE fb.domainId = p_domainId
			AND  IFNULL(fb.CustomerId,0) <> 0
            AND fb.AgentId is not null;
                         
			INSERT INTO temp_getcallback_list(domainId, CustomerId,channelType,HistoryId,DurationHistoryId,isAnswered,CallBackStatus,IsMissed,createdAt, rn)
			SELECT 	fb.domainId, fb.customerId, 'Instagram', fb.InstagramHistoryId, fb.InstagramHistoryId, CASE WHEN fb.Duration > 0 THEN 1 ELSE 0 END, fb.isCallback, fb.IsMissed, fb.createdAt, row_number() over(partition by fb.CustomerId order by fb.InstagramHistoryId desc)
			FROM tb_InstagramHistory  fb
			WHERE fb.domainId = p_domainId
			AND  IFNULL(fb.CustomerId,0) <> 0
            AND fb.AgentId is not null;
                        
            DROP TEMPORARY TABLE IF EXISTS tt_final_result;
            CREATE TEMPORARY TABLE tt_final_result AS
            SELECT domainId, CustomerId, customerNumber, channelType, HistoryId, DurationHistoryId, isAnswered, CallBackStatus, IsMissed, createdAt,  row_number() over(partition by CustomerId order by createdAt desc) AS ff_rn
            FROM temp_getcallback_list
            WHERE rn = 1;
             
			DROP TEMPORARY TABLE IF EXISTS temp_final_result;
			CREATE TEMPORARY TABLE temp_final_result
			(
				domainId 				INT
				, CustomerId			INT
				, customerNumber		VARCHAR(20)
				, channelType			VARCHAR(100)
				, HistoryId				INT
				, DurationHistoryId		INT
				, isAnswered			TINYINT
				, CallBackStatus		TINYINT
				, IsMissed				TINYINT
				, createdAt				DATETIME
			);

				ALTER TABLE temp_final_result
				ADD INDEX idx_domain (domainId),
				ADD INDEX idx_customerid (CustomerId),
				ADD INDEX idx_customernumber (customerNumber),
				ADD INDEX idx_History (HistoryId),
				ADD INDEX idx_DurationHistoryId (DurationHistoryId),
				ADD INDEX idx_createdAt(createdAt); 
             
             INSERT INTO temp_final_result(domainId, CustomerId, customerNumber, channelType, HistoryId, DurationHistoryId, isAnswered, CallBackStatus, IsMissed, createdAt)
             SELECT domainId, CustomerId, customerNumber, channelType, HistoryId, DurationHistoryId, isAnswered, CallBackStatus, IsMissed, createdAt
             FROM tt_final_result
             WHERE ff_rn = 1
             AND isAnswered = 1;
             
	end ;;
DELIMITER ;
