DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_customer_overall_callback_interactio`(	
       	p_domainId 			INT,
        p_userId			INT,
       	p_offset 			INT,
       	p_limit 			INT
)
sp_return: BEGIN
			DECLARE v_offset 	INT;
   			DECLARE v_limit 	INT;
   			DECLARE v_search 	INT;
   			DECLARE v_roleid 	INT;
   			DECLARE v_p_assigned_ext_no_email_chltype int;
                                          
                       		SET v_offset = p_offset * p_limit;
                       		                            	
                       		drop temporary table if exists temp_getcallback_list;
                       		create temporary table temp_getcallback_list
                       		(	id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber VARCHAR(20)						
                       			,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
                       			,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
                       			,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred tinyint default null		,transferredTypeId int default null			,markAsRead tinyint default null
                       			,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
                       			,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
                       			,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
                       			,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
                       			,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
                       			,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
                       			,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
                       			,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null 						,FacebookHistoryId	bigint				,afterFacebookWorkTime	int					,NextFlowNode	varchar(150)
                       			,transferredTo	bigint						,transferredDate	datetime				,dispositionUpdatedBy	bigint					,immediateParentId	bigint				,rootParentId	bigint						,discardedDate	datetime
                       			,repliedDate	datetime					,markAsReadSupervisor	tinyint				,markAsReadAgent	tinyint						,customerFacebookId	varchar(100)		,agentFacebookId	varchar(100)			,AgentStartTime	bigint
                       			,AgentEndTime	bigint						,SentimentalScore	float					,afterInstagramWorkTime int						,customerInstagramId bigint				,agentInstagramId	bigint					,InstagramCommunicationTypeId int
               					,InstagramHistoryId	bigint					,widgetId	INT								,isThresholdTimeExceeded		TINYINT			,remainingThresholdTime	VARCHAR(20)		,CallBackStatus		TINYINT					,emailconfigsupervisorName varchar(50)
                                 ,threadMessageId varchar(1000)
                                  
                       		);
                            
							ALTER TABLE temp_getcallback_list
							ADD INDEX idx_domain (domainId),
							ADD INDEX idx_session_time (sessionStartTime),
							ADD INDEX idx_customerid (CustomerId),
							ADD INDEX idx_customernumber (customerNumber),
							ADD INDEX idx_callhistory (CallHistoryId),
							ADD INDEX idx_chathistory (ChatHistoryId),
							ADD INDEX idx_queue (QueueId),
							ADD INDEX idx_disposition (dispositionId);
                                      
							SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
							 insert ignore into temp_getcallback_list(sessionId, sessionStartTime, sessionEndTime, chatFlowSourceId, companyId, domainId, dispositionId, Summary, IsInBound, dialDuration, disconnectedBy, 
									queueDuration, assignedTo, assignedBy, assignedOn, waitDuration, afterChatWorkTime, Istransferred, transferredTypeId, markAsRead, CustomerId, ticketId, CallBackDatetime, 
									Browser, IPAdress, ChatSubject, createdAt,updatedAt,  StartTime, EndTime, Duration, AgentId, AgentSkillId, IsBot, BotId, 
									transferredTime, QueueId, Message,channelType,ChatHistoryId,widgetId,
									   isThresholdTimeExceeded, remainingThresholdTime,CallBackStatus,SentimentalScore)
							select  cth.sessionId, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, NULL AS dispositionId, NULL AS Summary, cth.IsInBound, cth.dialDuration, cth.disconnectedBy, 
									cth.queueDuration, cth.assignedTo, cth.assignedBy, cth.assignedOn, 0 AS waitDuration, NULL AS afterChatWorkTime, NULL AS Istransferred, NULL AS transferredTypeId, NULL AS markAsRead, cth.CustomerId, 
									 Null AS ticketId, Null AS CallBackDatetime, cth.Browser, cth.IPAdress, cth.ChatSubject, cdh.createdAt, cdh.updatedAt, Null AS StartTime, Null AS EndTime, Null AS Duration, Null AS AgentId, Null AS AgentSkillId, 
									 Null AS IsBot, Null AS BotId, Null AS transferredTime, Null AS QueueId, Null AS Message,'Chat',cth.ChatHistoryId, cth.chatWidgetId, 
									 CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),cth.createdAt),'%H.%i') >= thresholdTime THEN 1 ELSE 0 END, timediff(NOW(),cth.createdAt), cth.CallBackStatus, cdh.SentimentalScore
							from 	tb_ChatHistory 						cth
                             JOIN 	tb_ChatDurationHistory				cdh 	ON cdh.ChatHistoryId 	= cth.ChatHistoryId
							JOIN 	chat_configuration_primary_form		PF		ON PF.aid				= cth.chatWidgetId 
							where 	cth.domainId = p_domainId
							and 	(cth.CallBackStatus	= 1 OR cdh.IsMissed = 1 OR cdh.IsAbandoned = 1)
							order by cth.ChatHistoryId desc; 
                                            
						UPDATE 	temp_getcallback_list 	t_CB
						JOIN 	tb_ChatDurationHistory 	CTDH 	ON 	t_CB.ChatHistoryId 	= CTDH.ChatHistoryId
																AND CTDH.ChatDurationHistoryId = (	SELECT 	MAX(ChatDurationHistoryId)
																								FROM 	tb_ChatDurationHistory 	InCDH
																								WHERE 	InCDH.ChatHistoryId = CTDH.ChatHistoryId)
						 SET 	t_CB.dispositionId		= CTDH.dispositionId		
							,	t_CB.Summary			= CTDH.Summary			
							,	t_CB.afterChatWorkTime	= CTDH.afterChatWorkTime	
							,	t_CB.Istransferred		= CTDH.Istransferred		
							 ,	t_CB.markAsRead			= CTDH.markAsRead			
							 ,	t_CB.ticketId			= CTDH.ticketId			
							 ,	t_CB.StartTime			= CTDH.StartTime			
							 , 	t_CB.EndTime			= CTDH.EndTime			
							 , 	t_CB.Duration			= CTDH.Duration			
							 , 	t_CB.AgentId			= CTDH.AgentId			
							 , 	t_CB.AgentSkillId		= CTDH.AgentSkillId		
							 , 	t_CB.IsBot				= CTDH.IsBot				
							 , 	t_CB.BotId				= CTDH.BotId				
							 , 	t_CB.transferredTime	= CTDH.transferredTime	
							 , 	t_CB.QueueId			= CTDH.QueueId;			
                             
							SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
						  
						  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;                             						 
								insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,dispositionId,UMNStatus,IsInBound,dialDuration, 
										disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,transferredTypeId,markAsRead, 
										CustomerId,voicemailUrl,ticketId,callDuration,summary,subject,createdAt,updatedAt,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
										transferredTime,recordingDuration,QueueId,Message,channelType,CallHistoryId,callBack,isThresholdTimeExceeded,remainingThresholdTime,SentimentalScore)
								select 	clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber,clh.domainId, null dispositionId, null UMNStatus, clh.IsInBound, null dialDuration, 
										clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, null afterCallWorkTime, clh.recordingTypeId, null transferredTypeId
									   ,null markAsRead, clh.CustomerId, clh.voicemailUrl, NULL AS ticketId, clh.callDuration, null summary, null subject,cdh.createdAt, cdh.updatedAt, null StartTime, null  EndTime,  null  Duration
									   ,null AgentHoldDuration, null AgentId, null AgentSkillId, null IsBot, null BotId, null RecordingUrl
									   ,null transferredTime, null recordingDuration, NULL AS QueueId, Null AS Message,'Call',clh.CallHistoryId,clh.callBack
									   ,CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),clh.createdAt),'%H.%i') >= CC.threshold THEN 1 ELSE 0 END	isThresholdTimeExceeded
									   ,TIMEDIFF(NOW(),clh.createdAt) AS remainingThresholdTime ,cdh.SentimentalScore                                                
								from tb_CallHistory 						clh
                                left join tb_CallDurationHistory			cdh ON clh.CallHistoryId = cdh.CallHistoryId
								LEFT JOIN  call_configuration				CC	ON CC.contactCenterNumber = clh.calledNumber
								where 	clh.domainId 	= p_domainId
								AND 	(clh.callBack = 1 OR cdh.IsMissedCall = 1 OR (cdh.IsAbandoned = 1 OR clh.IsAbandoned = 1))
								order by clh.CallHistoryId desc;
																
								 UPDATE 	temp_getcallback_list 	t_CB
								 JOIN 	tb_CallDurationHistory	CDH		ON CDH.CallHistoryId = t_CB.CallHistoryId
								 SET 	t_CB.QueueId	= CDH.QueueId;   
                                 
						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                                                                                        
						insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,WhatsappFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
								afterWhatsappWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
								AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,WhatsappHistoryId,CallBackStatus, customerId,SentimentalScore)
						select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
								wh.afterWhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wd.createdAt, wd.updatedAt, 
								wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId, Null AS Message,'Whatsapp',wh.WhatsappHistoryId,wh.isCallback, wh.customerId,wh.SentimentalScore
						from tb_WhatsappHistory 				wh
						left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId = wd.WhatsappHistoryId
						where wh.domainId = p_domainId
						and  ((wh.isCallback		= 1 and wh.callbackDraft = 0) or IsMissed = 1)
						order by wh.WhatsappHistoryId desc;
													
						insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterFacebookWorkTime,NextFlowNode
						,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
						,markAsReadAgent,IsSessionClosed,customerFacebookId,agentFacebookId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
						,createdAt,updatedAt,Message,channelType,FacebookHistoryId, customerId, QueueId,CallBackStatus)
						select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterFacebookWorkTime,fb.NextFlowNode
						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerFacebookId,fb.agentFacebookId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
						,fb.createdAt,fb.updatedAt, Null AS Message,'Facebook',fb.FacebookHistoryId,fb.customerId, fb.queueId,fb.isCallback
						from tb_FacebookHistory 				fb
						where fb.domainId = p_domainId
						 and  ((fb.isCallback		= 1 and fb.callbackDraft = 0) OR fb.IsMissed = 1)
						order by fb.FacebookHistoryId desc;
                                              
						insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterInstagramWorkTime,NextFlowNode
						,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
						,markAsReadAgent,IsSessionClosed,customerInstagramId,agentInstagramId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
						,createdAt,updatedAt,Message,channelType,InstagramHistoryId, customerId, QueueId,CallBackStatus)
						select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterInstagramWorkTime,fb.NextFlowNode
						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerInstagramId,fb.agentInstagramId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
						,fb.createdAt,fb.updatedAt, Null AS Message,'Instagram',fb.InstagramHistoryId, fb.customerId, fb.queueId,fb.isCallback
						from tb_InstagramHistory 				fb
						where fb.domainId = p_domainId
						and  ((fb.isCallback = 1 and fb.callbackDraft = 0) OR fb.IsMissed)
						order by fb.InstagramHistoryId desc;
                                      
						DROP TEMPORARY TABLE IF EXISTS temp_channeltype;  
									  
						DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_2;
						CREATE TEMPORARY TABLE temp_getcallback_list_2
						SELECT * FROM temp_getcallback_list WHERE 1 = 2;
						  
						ALTER TABLE temp_getcallback_list_2 
						ADD COLUMN AssignedToUserName	VARCHAR(250),
