                        FROM temp_getcallback_list_1 a
                        WHERE CustomerId IS NOT NULL;
                        
                        SELECT  id_col, sessionId, sessionStartTime, sessionEndTime, customerNumber, companyId, domainId, dispositionId, UMNStatus, IsInBound, dialDuration, disconnectedBy, queueDuration, assignedTo, assignedBy, assignedOn, calledNumber, waitDuration, afterCallWorkTime, recordingTypeId, Istransferred, transferredTypeId, markAsRead, CustomerId, voicemailUrl, ticketId, callDuration, summary, subject, createdAt, updatedAt, chatFlowSourceId, afterChatWorkTime, CallBackDatetime, Browser, IPAdress, ChatSubject, FromEmail, ToEmail, EmailSubject, EmailFlowSourceId, AfterEmailWorkTime, IsSessionClosed, SupervisorName, StartTime, EndTime, Duration, AgentHoldDuration, AgentId, AgentSkillId, IsBot, BotId, RecordingUrl, transferredTime, recordingDuration, QueueId, Message, channelType, SMSFlowSourceId, afterSMSWorkTime, EmailHistoryId, ChatHistoryId, CallHistoryId, SMSHistoryId, WhatsappFlowSourceId, afterWhatsappWorkTime, WhatsappHistoryId, callBack, FacebookHistoryId, afterFacebookWorkTime, NextFlowNode, transferredTo, transferredDate, dispositionUpdatedBy, immediateParentId, rootParentId, discardedDate, repliedDate, markAsReadSupervisor, markAsReadAgent, customerFacebookId, agentFacebookId, AgentStartTime, AgentEndTime, SentimentalScore, afterInstagramWorkTime, customerInstagramId, agentInstagramId, InstagramCommunicationTypeId, InstagramHistoryId, widgetId, isThresholdTimeExceeded, remainingThresholdTime, CallBackStatus, emailconfigsupervisorName, threadMessageId, AssignedToUserName, AssignedByUserName, AssignedToExt, dispositionName, queueName, CustomerName
