						ALTER TABLE temp_getcallback_list_2 
						ADD COLUMN AssignedToUserName	VARCHAR(250),
						ADD COLUMN AssignedByUserName	VARCHAR(250),
						ADD COLUMN AssignedToExt		INT;
						
						DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1;
						CREATE TEMPORARY TABLE temp_getcallback_list_1
						SELECT * FROM temp_getcallback_list_2 WHERE 1 = 2;       
    
    						
                                                                      
						INSERT INTO temp_getcallback_list_2
						select temp.*, tu.UserName as AssignedToUserName,tuu.UserName as AssignedByUserName,tu.ext as AssignedToExt
						from temp_getcallback_list temp
						left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
						left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 
						left join email_config 				ec	ON	ec.emailAddress	= temp.ToEmail
																AND	ec.domainId 	= temp.domainId;
																

						insert into temp_getcallback_list_1
						select * from temp_getcallback_list_2
						ORDER BY sessionStartTime DESC ;  
       
						SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
						
				

						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                             
                                            
						SELECT 	COUNT(1) INTO v_count
						FROM 	temp_getcallback_list_1;

						ALTER TABLE temp_getcallback_list_1 ADD COLUMN dispositionName VARCHAR(100), ADD COLUMN queueName varchar(255), ADD COLUMN CustomerName VARCHAR(150);

						UPDATE 	temp_getcallback_list_1		H
						LEFT JOIN customer_contact		CC	ON H.CustomerId 	= CC.coid AND H.domainId = CC.domainId				
						LEFT JOIN disposition_status		ds 	ON ds.did			= H.dispositionId and H.domainId = ds.domainId 					
						LEFT JOIN queue 					qu 	ON H.QueueId 		= qu.qid
						SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))
						,		H.dispositionName	= ds.dispositionName
						,		H.queueName			= qu.`name`;       

						update temp_getcallback_list_1 set CustomerName = '' where ifnull(LTRIM(RTRIM(CustomerId)),'')='';

				


						UPDATE 	temp_getcallback_list_1		H
						LEFT JOIN customer_contact		CC	ON H.customerNumber = CC.primaryPhoneNumber	AND H.domainId = CC.domainId	
						SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))
                        ,	H.CustomerId = IFNULL(H.CustomerId,CC.coid)
						WHERE IFNULL(H.CustomerName,'') = ''; 

					
						                        
