/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_customer_overall_interaction`(
 		p_domainId			INT
         ,p_offset			INT 
         ,p_limit			INT
         ,p_isQualifiedUser	INT
         ,p_AgentId			INT
         ,p_fromDate		DATE 
         ,p_toDate			DATE 
         ,p_agentName		VARCHAR(150)
         ,p_dispositionName	VARCHAR(150)
         ,p_customerName	VARCHAR(150)
         ,p_isBot			TINYINT
         ,p_isInbound 		TINYINT
         ,p_isMissed 		TINYINT
         ,p_isAbonded		TINYINT
         ,p_channelName		VARCHAR(1500)
     )
BEGIN
 
 		DECLARE v_offset INT;
         
         SET v_offset = p_offset * p_limit;
         
         DROP TEMPORARY TABLE IF EXISTS tt_channelType;	CREATE TEMPORARY TABLE tt_channelType(channel_name VARCHAR(100));
     	CALL split(p_channelName,',');	INSERT INTO tt_channelType(channel_name) SELECT Items FROM tt_Split_temptable;
            
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 
 			DROP TEMPORARY TABLE IF EXISTS tt_customer_details;
 			CREATE TEMPORARY TABLE tt_customer_details
             (
 				cid 					INT AUTO_INCREMENT PRIMARY KEY
                 ,tt_customerId			INT
 				,tt_ChannelType			VARCHAR(100)
                 ,tt_createdAt			DATETIME
                 ,tt_duration			INT 
                 ,tt_IsInBound			TINYINT 
                 ,tt_summary			VARCHAR(2500)
                 ,tt_SentimentalScore	FLOAT
                 ,tt_customerNumber		VARCHAR(20)
                 ,tt_FromEmail			VARCHAR(100)
                 ,tt_IsMissedCall		TINYINT
                 ,tt_Isabonded			TINYINT
                 ,tt_agentId			INT
                 ,tt_isAgentAbonded		INT
                 ,tt_IsBot				TINYINT(1)
				 ,tt_DispositionId 		INT
             );
             
