             SELECT cid,tt_customerId AS customer_id,tt_ChannelType AS channel_name
             ,tt_createdAt AS created_date,tt_duration AS total_duration,tt_IsInBound AS is_inbound,tt_summary AS summary
             ,ROW_NUMBER() OVER(PARTITION BY tt_customerId ORDER BY tt_createdAt DESC) AS RN
             ,tt_SentimentalScore	AS SentimentalScore,tt_customerNumber AS customerNumber,tt_FromEmail AS FromEmail,tt_IsMissedCall AS IsMissedCall,tt_agentId AS AgentId, tt_IsBot AS IsBot,tt_DispositionId as dispositionId
             ,tt_Isabonded AS Isabonded,tt_isAgentAbonded AS isAgentAbonded
             FROM tt_customer_details;
              
             DROP TEMPORARY TABLE IF EXISTS tt_customer_channel_count;
             CREATE TEMPORARY TABLE tt_customer_channel_count
             AS
             SELECT count(customer_id) AS total_history,customer_id
             FROM tt_customer_detail_result
             WHERE IFNULL(customer_id,0) <> 0
             GROUP BY customer_id;
 			
             DROP TEMPORARY TABLE IF EXISTS tt_customer_detail_final_result;
             CREATE TEMPORARY TABLE tt_customer_detail_final_result
             AS
 			SELECT concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) AS customer_name,CNT.total_history AS total_history_cnt,CD.channel_name
             ,CD.created_date,CD.total_duration,CD.is_inbound,CD.summary,CC.primaryEmail,CC.primaryPhoneNumber,CD.SentimentalScore,CD.customer_id AS coid,CD.customerNumber,CD.FromEmail, CD.IsMissedCall
             , U.UserName, CD.IsBot,CD.dispositionId,CD.Isabonded,CD.isAgentAbonded
 			FROM tt_customer_detail_result 	CD 
 			JOIN tt_customer_channel_count 	CNT ON CD.customer_id = CNT.customer_id
 			JOIN customer_contact 			CC ON CC.coid = CD.customer_id
			LEFT JOIN tb_User 				U  ON U.UserID = CD.AgentId
 			WHERE RN = 1
           --   AND IFNULL(CD.IsMissedCall,0) <> 1
             ORDER BY CD.created_date DESC;
             
 			SELECT customer_name, total_history_cnt, channel_name, created_date, total_duration, is_inbound, summary, primaryEmail, primaryPhoneNumber, SentimentalScore, coid ,customerNumber, FromEmail
             ,UserName , IsBot,DS.dispositionName
             FROM tt_customer_detail_final_result CD
			 LEFT JOIN disposition_status DS ON DS.did = CD.dispositionId
             WHERE case p_isQualifiedUser when 1 then (customer_name like ' %%') when 2 then (customer_name is not null AND customer_name not like ' %%') ELSE 1=1 END
             AND (customer_name LIKE CONCAT('%',p_customerName,'%') OR p_customerName IS NULL)
             AND (UserName LIKE CONCAT('%',p_agentName,'%') OR p_agentName IS NULL)
             AND (dispositionName LIKE CONCAT('%',p_dispositionName,'%') OR p_dispositionName IS NULL)
