             AND (IsBot = p_isBot OR p_isBot IS NULL)
             AND (IsMissedCall = p_isMissed OR p_isMissed IS NULL)
             AND ((Isabonded = p_isAbonded OR isAgentAbonded = p_isAbonded ) OR p_isAbonded IS NULL)
             AND (UserName LIKE CONCAT('%',p_agentName,'%') OR p_agentName IS NULL)
             LIMIT v_offset,p_limit;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    END ;;
