CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_multi_user_details`(
	p_domainId	INT
	,p_UserID	VARCHAR(250)
)
begin

		DROP TEMPORARY TABLE IF EXISTS tt_user_id;
        CREATE TEMPORARY TABLE tt_user_id 
        (
			tt_userId	INT
        );

		CALL split(p_UserID,',');
        INSERT INTO tt_user_id(tt_userId)
        SELECT Items FROM tt_Split_temptable;

		SELECT U.UserID, U.UserName, U.emailId, U.ext, U.domainId
		FROM tb_User U
        JOIN tt_user_id TU ON U.UserID = TU.tt_userId
		WHERE domainId = p_domainId;

end ;;
