CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_overall_voice_mail`(
		p_domainId	INT
    )
BEGIN
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  	
 		SELECT  CH.voicemailUrl, concat(IFNULL(firstName,''),' ',IFNULL(lastName,'')) AS customerName,CH.sessionId,CH.domainId
        FROM tb_CallHistory CH 
        
        LEFT JOIN customer_contact CC ON CC.coid = CH.CustomerId 
        WHERE CH.domainId = p_domainId
        AND (IFNULL(voicemailUrl,0) <> 0 OR voicemailUrl <> '0');

      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
   END ;;
