CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_particular_user_detail`(
	p_domainId	INT
	,p_UserID	INT
)
begin

	SELECT UserID
			,myAccUserId
			,UserName
			,emailId
			,directNumber
			,address
			,routing_profile_id
			,report_to_UserID
			,sipLoginId
			,companyId
			,domainId
			,ext
			,isActive
			,callTypeId
			,inboundCall
			,outboundCampaignCall
			,roleid
			,localization
			,currentSession
			,isVoice
			,isVoiceCallTransfer
			,isAvailableForVoice
			,isChat
			,isChatTransfer
			,isEmail
			,isEmailTransfer
			,StatusID
			,isSms
			,isSocialMedia
			,companyName
			,addSkill
			,voice
			,chat
			,email
			,sms
			,socialMedia
            ,recording
            ,knowledgeBase
			,chatLimit
			,createdAt
			,updatedAt
			,stateTimer
			,AssignedTime
			,chatFlag
			,ProfileImage
			,emp_id 
    FROM tb_User 
    WHERE UserID = p_UserID
    AND domainId = p_domainId;

end ;;
