CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_particular_user_detail_test`(
	 p_domainId	INT
	,p_roleId	INT
	,p_UserID	INT
)
begin

	SELECT U.UserID
			,U.UserName
			,U.emailId
			,U.domainId
			,U.ext
			,U.roleid
			,U.voice
			,U.chat
			,U.email
			,U.sms
			,U.socialMedia
            ,U.recording
            ,U.knowledgeBase
			,U.ProfileImage
			,U.emp_id 
            ,P.is_agent_monitor
            ,P.is_knowledge_base
            ,P.is_queue_management
            ,P.is_reporting_dashboard
    FROM tb_User U
    LEFT JOIN tb_my_plan_role_permission P ON U.domainId = P.domainId AND U.roleid = P.role_id
    WHERE (U.UserID = p_UserID OR ifnull(p_UserID,'') = '')
    AND U.domainId = p_domainId
    AND (P.role_id = p_roleId OR ifnull(p_roleId,'') = '');

end ;;
DELIMITER ;
