CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_get_user_details`(
	p_domainId	INT
    ,p_UserID	INT
)
begin

	SELECT UserName,ext,emailId,UserID 
    FROM tb_User 
    WHERE (IFNULL(p_UserID,0) = 0 OR UserID = p_UserID)
    AND domainId = p_domainId;

end ;;
