CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_ai_insert_update_outbound_campaign_draft`(
  p_sessionId				VARCHAR(150),
  p_domainId				INT,
  p_title					VARCHAR(100),
  p_campaignMessage			JSON,
  p_cid						INT
  )
BEGIN
 	DECLARE v_errcode 			INT;
 	DECLARE v_errmsg 			VARCHAR(200);  
 	DECLARE v_now 				DATETIME default now();
 	DECLARE v_campDraftId 		INT;
 	DECLARE v_fk_campDraftId 	INT;
            
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
      
      SELECT campDraftId INTO v_campDraftId
      FROM 	tb_outbound_campaign_draft
      WHERE SessionId 	= p_sessionId
      AND 	domainId	= p_domainId; 
      
      SELECT fk_campDraftId 
      INTO 	v_fk_campDraftId	
      FROM 	tb_callBlast
      WHERE cid	= p_cid;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      
      IF v_campDraftId IS NULL
      THEN		
		INSERT INTO tb_outbound_campaign_draft(sessionId,domainId,title,campaignMessage,createdAt,updatedAt)
		VALUES(p_sessionId,p_domainId,p_title,p_campaignMessage,v_now,v_now);    
          
          SET 	v_campDraftId 	= last_insert_id();
          SET	v_errcode		= 0
            , 	v_errmsg 		= 'Added chat successfully';
  	ELSE                
  		UPDATE 	tb_outbound_campaign_draft
          SET 	title				= IFNULL(p_Title,title)
  			,	campaignMessage 	= if(campaignMessage is null,p_campaignMessage,JSON_ARRAY_APPEND(campaignMessage, '$', p_campaignMessage))
  			,	UpdatedAt 			= v_now
  		WHERE 	campDraftId 		= v_campDraftId;
              
  		SET		v_errcode	= 1
            , 	v_errmsg 	= 'Updated chat successfully';
      END IF;
      
      IF v_fk_campDraftId IS NULL AND p_cid IS NOT NULL
      THEN
  		UPDATE 	tb_callBlast
          SET 	fk_campDraftId		= v_campDraftId        
          WHERE  cid	= p_cid;
      END IF;    
  
  	SELECT v_campDraftId AS campDraftId, v_errcode AS errcode, v_errmsg AS errmsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
