/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_analytics_interaction_overview_trend_chat`(
 p_startTmpstmp 	BIGINT,
  p_endTmpstmp 		BIGINT,
  p_domainId 		INT
)
BEGIN
		DECLARE v_StartTmpstmp 	BIGINT;
  		DECLARE v_endTmp	BIGINT;
        DECLARE v_Resolved INT;
        
        IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_StartTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_StartTmpstmp = p_startTmpstmp;  END IF; 
		IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmp = p_endTmpstmp; END IF;  	      
    
	SELECT  `status` INTO v_Resolved
    FROM 	disposition_status 
    WHERE 	domainId		= p_domainId
    AND 	dispositionName LIKE 'Resolved'
    AND 	type			= 'Default';
    
    DROP TEMPORARY TABLE IF EXISTS tmp_botInteractiontrend;
    CREATE TEMPORARY TABLE tmp_botInteractiontrend
    SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) as time_range
			,CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END	AS Sessions
        ,	CASE WHEN v_Resolved IS NOT NULL THEN 1 ELSE 0 END AS handledSession
    FROM 	tb_ChatHistory			H
    JOIN 	tb_ChatDurationHistory	DH	ON DH.ChatHistoryId = H.ChatHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1
    GROUP BY H.sessionStartTime,H.sessionEndTime;
        
    INSERT INTO tmp_botInteractiontrend
    SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) as time_range
		,	CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END			AS Sessions
        ,	CASE WHEN v_Resolved IS NOT NULL THEN 1 ELSE 0 END AS handledSession
    FROM 	tb_CallHistory			H
    JOIN 	tb_CallDurationHistory	DH	ON DH.CallHistoryId = H.CallHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1 
    GROUP BY H.sessionStartTime,H.sessionEndTime;  
    
    INSERT INTO tmp_botInteractiontrend
    SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) as time_range	
		,	CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END				AS Sessions
        ,	CASE WHEN v_Resolved IS NOT NULL THEN 1 ELSE 0 END AS handledSession
    FROM 	tb_SMSHistory			H
    JOIN 	tb_SMSDurationHistory	DH	ON DH.SMSHistoryId = H.SMSHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1 
    GROUP BY H.sessionStartTime,H.sessionEndTime;      

    INSERT INTO tmp_botInteractiontrend
    SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) as time_range
		,	CASE WHEN H.SessionStartTime IS NOT NULL THEN 1 ELSE 0 END			AS Sessions
        ,	CASE WHEN v_Resolved IS NOT NULL THEN 1 ELSE 0 END AS handledSession
    FROM 	tb_EmailHistory			H
    JOIN 	tb_EmailDurationHistory	DH	ON DH.EmailHistoryId = H.EmailHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1 
    GROUP BY H.sessionStartTime,H.sessionEndTime;      
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
    SELECT 	date_format(time_range,'%y-%m-%d %H:%i')  AS time_range
		,	SUM(Sessions) 							AS sessions
        ,	(SUM(handledSession) / COUNT(1)) * 100 	AS agentEngagementRate 
    FROM 	tmp_botInteractiontrend
    GROUP BY time_range;
    
    SELECT 	SUM(Sessions) 							AS totalSessions
        ,	(SUM(handledSession) / COUNT(1)) * 100 	AS agentEngagementRate
    FROM 	tmp_botInteractiontrend;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
