CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_APICreateOAuth_Client_info`(
	p_oauthId int,
    p_domain_id int,
	p_oauthName varchar(150),
	p_oauthGrandType int,
	p_oauthClientId varchar(150),
	p_oauthClientSecret varchar(150),
	p_oauthAuthorizeURL varchar(150),
	p_oauthRedirectURL varchar(150),
	p_oauthScopes varchar(150),
    processtype int		
)
Begin

	declare v_errcode int default -1;
    declare v_errmsg varchar(150) default 'Failure';
    declare v_oauthId int;
    
    sp_exit:Begin
		if processtype = 1 then
			if exists (select 1 from ccaas_API_OAuth_Client_info where oauthName = p_oauthName and domain_id = p_domain_id limit 1) then
				set v_errcode = -1;
				set v_errmsg = 'Client Name already exists';
				leave sp_exit;
			End if;
            
            insert into ccaas_API_OAuth_Client_info(oauthId, domain_id, oauthName, oauthGrandType, oauthClientId, oauthClientSecret, oauthAuthorizeURL, oauthRedirectURL, oauthScopes, createdAt)
            values(p_oauthId, p_domain_id, p_oauthName, p_oauthGrandType, p_oauthClientId, p_oauthClientSecret, p_oauthAuthorizeURL, p_oauthRedirectURL, p_oauthScopes, current_timestamp);
            
            set v_oauthId = last_insert_id();
            
            if row_count()>0 then
				set v_errcode = 0;
				set v_errmsg = 'Success : Inserted';
				leave sp_exit;
            End if;       
		End if;
        
        if processtype = 2 then
			if exists (select 1 from ccaas_API_OAuth_Client_info where oauthClientId = p_oauthClientId and oauthId <> p_oauthId limit 1) then
				set v_errcode = -1;
				set v_errmsg = 'ClientID already exists';
				leave sp_exit;
			End if;
            
			update ccaas_API_OAuth_Client_info
            set oauthClientId = p_oauthClientId, 
				oauthClientSecret = p_oauthClientSecret,
                updatedAt = current_timestamp
            where oauthId = p_oauthId and domain_id = p_domain_id;
            
				set v_errcode = 0;
				set v_errmsg = 'Success : Updated';
            
        End if;
        
        if processtype = 3 then
			if not exists (select 1 from ccaas_API_OAuth_Client_info where oauthId = p_oauthId limit 1) then
				set v_errcode = -1;
				set v_errmsg = 'Client Id not exists';
				leave sp_exit;
			End if;
            
            delete from ccaas_API_OAuth_Client_info where oauthId = p_oauthId and domain_id = p_domain_id;
            
			set v_errcode = 0;
			set v_errmsg = 'Success : Deleted';
       
        End if;
     
	End;
    select v_errcode as errcode, v_errmsg as errmsg,ifnull(v_oauthId,0) as oauthId;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_APIDeleteDomain_details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_APIDeleteDomain_details`(
 	p_apidomainId int,
 	p_domain_id int
)
Begin

	declare v_errcode int default -1;
	declare v_errmsg varchar(150) default 'Failure';
    
	delete from ccaas_API_Domain_details where apidomainId = p_apidomainId and domain_id = p_domain_id;
	
		if row_count()>0 then
			set v_errcode = 0;
			set v_errmsg = 'Success : Deleted';
		End if; 
        select v_errcode as errcode,v_errmsg as errmsg;

End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
