CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_APIGetDomain_details`(
p_domain_id int,
p_apidomainId int
)
Begin
	select b.oauthName,a.* from ccaas_API_Domain_details a
    left join ccaas_API_OAuth_Client_info b on a.oauthId = b.oauthId and a.domain_id = b.domain_id
    where a.domain_id = p_domain_id and (apidomainId = p_apidomainId or ifnull(p_apidomainId,0)=0);
End ;;
