CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_APIInsertDomain_details`(
   	p_domain_id int,
   	p_domainName varchar(150),
   	p_domaindesc varchar(150),
   	p_authtype varchar(150),
   	p_header varchar(150),
   	p_headerValue varchar(150),
   	p_userName varchar(150),
   	p_password varchar(150),
   	p_oauthId int,
   	p_domainURL varchar(150)
   	
    )
Begin
    
    	declare v_errcode int default -1;
        declare v_errmsg varchar(150) default 'Failure';
        declare v_apidomainId int; 
        
        sp_exit:Begin

    			if exists (select 1 from ccaas_API_Domain_details where domainName = p_domainName and domain_id = p_domain_id limit 1) then
    				set v_errcode = -1;
    				set v_errmsg = 'Domain Name already exists';
    				leave sp_exit;
    			End if;
                
                insert into ccaas_API_Domain_details(domain_id, domainName, domainDesc, authtype, header, headerValue, userName, password, oauthId, domainURL, createdAt)
                values(p_domain_id, p_domainName, p_domainDesc, p_authtype, p_header, p_headerValue, p_userName, p_password, p_oauthId, p_domainURL, current_timestamp);
         
                set v_apidomainId = last_insert_id();
                
                if row_count()>0 then
    				set v_errcode = 0;
    				set v_errmsg = 'Success : Inserted';
    				leave sp_exit;
                End if;       
      
       
      
    	End;
        select v_errcode as errcode, v_errmsg as errmsg,ifnull(v_apidomainId,0) as apidomainId;
    End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
