CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_APIUpdateDomain_details`(
	p_apidomainId int,
	p_domain_id int,
	p_header varchar(150),
	p_headerValue JSON,
	p_userName varchar(150),
	p_password varchar(150),
	p_oauthId int,
	p_domainURL varchar(150),
    p_token text
 )
Begin
 
     	declare v_errcode int default -1;
         declare v_errmsg varchar(150) default 'Failure';
 
 		sp_exit:Begin
 		if not exists (select 1 from ccaas_API_Domain_details where apidomainId = p_apidomainId limit 1) then
 			set v_errcode = -1;
 			set v_errmsg = 'Domain not exists';
 			leave sp_exit;
 		End if;  
                 
     			update ccaas_API_Domain_details
                 set header = ifnull(p_headerValue,headerValue) 
     				,headerValue = ifnull(p_headerValue,headerValue)
                     ,userName = ifnull(p_userName,userName)
                     ,password = ifnull(p_password,password)
                     ,oauthId = ifnull(p_oauthId,oauthId)
                     ,updatedAt = current_timestamp
                      ,token = ifnull(p_token,token)
                 where apidomainId = p_apidomainId and domain_id = p_domain_id;
                 
     				set v_errcode = 0;
     				set v_errmsg = 'Success : Updated';
 		End ;
         
         select v_errcode as errcode, v_errmsg as errmsg;
         
 End ;;
DELIMITER ;
