CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_appointment_update_emailId`(
	 p_historyId 	BIGINT
    ,p_domainId 	INT
    ,p_emailId		VARCHAR(250)
    ,p_channelType	VARCHAR(50)
    ,p_companyNumber VARCHAR(50)
)
begin

	DECLARE v_id 		INT;
	DECLARE v_errcode 	INT;
	DECLARE v_errmsg 	VARCHAR(100);

	SELECT id INTO v_id
    FROM ccaas_appointment_flow_tracking_dtl
    WHERE 	domainId 	= p_domainId
    AND		historyId 	= p_historyId;
    
	 IF v_id IS NOT NULL
	 THEN
		UPDATE ccaas_appointment_flow_tracking_dtl
		SET emailId = p_emailId
		WHERE id = v_id ;
		
		SET v_errcode = 0;
		SET v_errmsg = 'Appointment updated successfully';
	ELSE 
		INSERT INTO ccaas_appointment_flow_tracking_dtl(channelType,historyId,domainId,companyNumber,emailId)
        VALUES(p_channelType,p_historyId,p_domainId,p_companyNumber,p_emailId);
        
        SET v_errcode = 1;
		SET v_errmsg = 'Appointment inserted successfully';
	END IF;

	SELECT v_errcode as errcode , v_errmsg as errmsg;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_appointment_update_name` */;
