CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_call_arrival_dashboard_rate_details`(
     startTmpstmp bigint,
     endTmpstmp bigint,
     timeZone varchar(200),
     domainId int,
     ext int)
begin
  
  
  
      
     drop temporary table if exists tt_analy_report ;
     create temporary table tt_analy_report
     (
     id int auto_increment primary key,hours int,totalcalls int,totalchats int
     );
     
     
 		insert into tt_analy_report(totalcalls,hours)
 		select count(ifnull(a.sessionStartTime,0)),HOUR(a.createdAt) 
 		FROM sessionHistory a
 		where a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp 
 		and a.callType = 'inbound' and channelType is not null
 		and a.callType is not null and (a.agentDetails = ext or ifnull(ext,0)=0)
 		and a.queueName is not null and a.queueName <> '' 
 		and a.sessionStartTime <> 0 and a.domainId = domainId and a.channelType = 'Call'
 		group by hour(a.createdAt);		
        
        insert into tt_analy_report(totalchats,hours)
  		select count(ifnull(a.sessionStartTime,0)),HOUR(a.createdAt) 
  		FROM sessionHistory a
  		where a.sessionStartTime BETWEEN startTmpstmp and endTmpstmp   		
  		and a.channelType = 'Chat' and a.callType is not null 
        and a.sessionStartTime <> 0 and a.domainId = domainId 
        and (a.agentDetails = ext or ifnull(ext,0)=0)  		  		
  		group by hour(a.createdAt);		
 		
 		select case when a.hours is null then b.hours else a.hours end as Time,
				ifnull(a.totalcalls,0) as totalcalls,ifnull(a.totalchats,0) as totalchats			
 		from tt_analy_report a Right join tt_hour_list b on a.hours = b.hours;  
  
 end ;;
DELIMITER ;
