CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_call_create_message_details_bot`(
 		p_domainId 		int, 
 		p_sessionId 	varchar(250), 
 		p_Message 		json,
 		p_agentextn 	int,
 		p_isBot		tinyint
     )
Begin
     
     		declare v_errcode int;
     		declare v_errmsg varchar(100);
             declare v_AgentId bigint;
             declare v_CallHistoryId bigint;
             declare v_CallDurationHistoryId bigint;
             declare v_prev_Message json;
             declare v_merged_msg json;
             
            
 			DECLARE EXIT HANDLER FOR SQLEXCEPTION 
 			BEGIN
 				ROLLBACK;
 				SELECT -1 AS errcode, 'Unexpected SQL error occurred' AS errmsg, v_CallHistoryId AS CallHistoryId;
 			END;
 
 			DECLARE EXIT HANDLER FOR SQLWARNING 
 			BEGIN
 				ROLLBACK;
 				SELECT -2 AS errcode, 'SQL warning occurred' AS errmsg, v_CallHistoryId AS CallHistoryId;
 			END; 
 
 			START TRANSACTION;
               if p_agentextn is not null then
      			select  UserID into v_AgentId from tb_User where domainId = p_domainId and ext = p_agentextn limit 1;
              End if;
            
     		sp_exit:Begin
     			if p_domainId is null or p_domainId=0 then
     				set v_errcode = -1;
     				set v_errmsg = 'DomainId should not be empty';
     				leave sp_exit;
     			End if;
               
               if ((p_agentextn is null or p_agentextn=0) and p_isBot = 0) then
     				set v_errcode = -1;
     				set v_errmsg = 'Agentextn should not be empty or null';
     				leave sp_exit;
     			End if;
     	
     			if not exists (select 1 from tb_CallHistory a where a.sessionId collate utf8mb4_unicode_ci = p_sessionId limit 1) then
     				set v_errcode = -1;
     				set v_errmsg = 'Call details not available';
     				leave sp_exit;
     			End if;
                 
  			select CallHistoryId into v_CallHistoryId from tb_CallHistory where sessionId collate utf8mb4_unicode_ci = p_sessionId limit 1;
              
              IF v_AgentId IS NOT NULL
              THEN
  				select CallDurationHistoryId into v_CallDurationHistoryId from tb_CallDurationHistory where CallHistoryId = v_CallHistoryId and AgentId = v_AgentId limit 1;                      
			  ELSEIF p_isBot = 1
              THEN
  				select CallDurationHistoryId into v_CallDurationHistoryId from tb_CallDurationHistory where CallHistoryId = v_CallHistoryId and IsBot = p_isBot limit 1;                      
              END IF;
              
              IF v_CallDurationHistoryId IS NULL
              THEN
  				SET v_errcode = -1;
     				SET v_errmsg = 'Given Agent did not attend this call';
     				LEAVE sp_exit;
              END IF;
  
				if not exists(select 1 from tb_CallMessage where CallHistoryId = v_CallHistoryId limit 1)then
					insert into tb_CallMessage(CallHistoryId,Message,createdAt,CallDurationHistoryId)
					values(v_CallHistoryId,p_Message,now(),v_CallDurationHistoryId);
                     
				else if exists(select 1 from tb_CallMessage where CallHistoryId = v_CallHistoryId and CallDurationHistoryId = v_CallDurationHistoryId limit 1)then
					update tb_CallMessage a
					set a.Message = if(a.Message is null,p_Message,JSON_ARRAY_APPEND(a.Message, '$', p_Message)),a.updatedAt = now()
					where a.CallHistoryId = v_CallHistoryId and CallDurationHistoryId = v_CallDurationHistoryId;
				else
						
					select Message into v_prev_Message from tb_CallMessage where CallHistoryId = v_CallHistoryId order by ifnull(updatedAt,createdAt) desc limit 1;
		 
					set v_merged_msg =  JSON_ARRAY_APPEND(v_prev_Message, '$', p_Message);
					insert into tb_CallMessage(CallHistoryId,Message,createdAt,CallDurationHistoryId)
					values(v_CallHistoryId,v_merged_msg,now(),v_CallDurationHistoryId);
				End if;    
                 End if;
 
     			if row_count() > 0 then
     				set v_errcode = 0;
     				set v_errmsg = 'inserted successfully';
     				leave sp_exit;
     			end if;
     		End;
 		COMMIT;
     		select v_errcode as errcode, v_errmsg as errmsg,v_CallHistoryId as CallHistoryId;
     End ;;
DELIMITER ;
