/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_call_create_message_details_bot_test`(
    p_domainId INT,
    p_sessionId VARCHAR(250),
    p_Message JSON,
    p_agentextn INT,
    p_isBot TINYINT
)
proc_block:   
BEGIN
    DECLARE v_errcode INT DEFAULT 0;
    DECLARE v_errmsg VARCHAR(255) DEFAULT '';
    DECLARE v_AgentId BIGINT DEFAULT NULL;
    DECLARE v_CallHistoryId BIGINT DEFAULT NULL;
    DECLARE v_CallDurationHistoryId BIGINT DEFAULT NULL;

    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT -1 AS errcode, 'Unexpected SQL error occurred' AS errmsg, v_CallHistoryId AS CallHistoryId;
    END;

    DECLARE EXIT HANDLER FOR SQLWARNING
    BEGIN
        ROLLBACK;
        SELECT -2 AS errcode, 'SQL warning occurred' AS errmsg, v_CallHistoryId AS CallHistoryId;
    END;

    
    IF p_domainId IS NULL OR p_domainId = 0 THEN
        SELECT -1 AS errcode, 'DomainId should not be empty' AS errmsg, NULL AS CallHistoryId;
        LEAVE proc_block;   
    END IF;

    IF ((p_agentextn IS NULL OR p_agentextn = 0) AND p_isBot = 0) THEN
        SELECT -1 AS errcode, 'Agentextn should not be empty or null' AS errmsg, NULL AS CallHistoryId;
        LEAVE proc_block;
    END IF;

    
    IF p_agentextn IS NOT NULL THEN
        SELECT UserID
        INTO v_AgentId
        FROM tb_User
        WHERE domainId = p_domainId AND ext = p_agentextn
        LIMIT 1;
    END IF;

    
    IF NOT EXISTS (SELECT 1 FROM tb_CallHistory a WHERE a.sessionId COLLATE utf8mb4_unicode_ci = p_sessionId LIMIT 1) THEN
        SELECT -1 AS errcode, 'Call details not available' AS errmsg, NULL AS CallHistoryId;
        LEAVE proc_block;
    END IF;

    SELECT CallHistoryId
    INTO v_CallHistoryId
    FROM tb_CallHistory
    WHERE sessionId COLLATE utf8mb4_unicode_ci = p_sessionId
    LIMIT 1;

    
    IF v_AgentId IS NOT NULL THEN
        SELECT CallDurationHistoryId
        INTO v_CallDurationHistoryId
        FROM tb_CallDurationHistory
        WHERE CallHistoryId = v_CallHistoryId AND AgentId = v_AgentId
        LIMIT 1;
    ELSEIF p_isBot = 1 THEN
        SELECT CallDurationHistoryId
        INTO v_CallDurationHistoryId
        FROM tb_CallDurationHistory
        WHERE CallHistoryId = v_CallHistoryId AND IsBot = p_isBot
        LIMIT 1;
    END IF;

    IF v_CallDurationHistoryId IS NULL THEN
        SELECT -1 AS errcode, 'Given Agent did not attend this call' AS errmsg, v_CallHistoryId AS CallHistoryId;
        LEAVE proc_block;
    END IF;

    
    START TRANSACTION;

    INSERT INTO tb_CallMessage (CallHistoryId, CallDurationHistoryId, Message, createdAt)
    VALUES (v_CallHistoryId, v_CallDurationHistoryId, JSON_ARRAY(p_Message), NOW())
    ON DUPLICATE KEY UPDATE
        Message = CASE
                    WHEN JSON_TYPE(Message) = 'ARRAY'
                        THEN JSON_ARRAY_APPEND(Message, '$', p_Message)
                    WHEN JSON_TYPE(Message) = 'NULL'
                        THEN JSON_ARRAY(p_Message)
                    ELSE JSON_ARRAY(Message, p_Message)
                  END,
        updatedAt = NOW();

    COMMIT;

    
    SELECT 0 AS errcode, 'inserted successfully' AS errmsg, v_CallHistoryId AS CallHistoryId;

END proc_block ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
