CREATE DEFINER=`root`@`%` PROCEDURE `ccaas_call_Flow_details`(
  	cfid varchar(255),
  	templateName varchar(255),
  	nodes longtext, 
  	edges longtext,
  	`version` varchar(55),
  	`type` varchar(100),
  	createDate bigint,
  	lastModifiedDate bigint,
  	`status` int,
  	companyId int,
  	domainId int,
  	`description`  varchar(255),
  	publish_data longtext,
  	p_callFlowId int
  )
begin
  		declare errcode int; 
  		declare errmsg varchar(255);
            
    	
    	insert into callFlow_insert_update_log(log_insert_date,cfid,templateName,nodes,edges,`version`,`type`,createDate,lastModifiedDate ,`status`,companyId,domainId ,`description`,publish_data,callFlowId)
    	values(current_timestamp,cfid,templateName,nodes,edges,`version`,`type`,createDate,lastModifiedDate ,`status`,companyId,domainId ,`description`,publish_data,p_callFlowId);
      
    	sp_exit : begin        
            if exists (select 1 from callFlow a where a.callFlowId = p_callFlowId and a.domainId = domainId limit 1)
            then
   			update callFlow a 
   			set a.templateName = ifnull(templateName,a.templateName),
  				a.nodes = ifnull(nodes,a.nodes),
  				a.edges = ifnull(edges,a.edges),
  				a.`version` = ifnull(`version`,a.`version`),
  				a.`type` = ifnull(`type`,a.`type`),
  
  				a.lastModifiedDate = ifnull(lastModifiedDate,a.lastModifiedDate),        
  				a.`status` = ifnull(`status`,a.`status`),
  				a.companyId = ifnull(companyId,a.companyId),
  				a.`description` = ifnull(`description`,a.`description`),
  				a.publishData = ifnull(publish_data,a.publishData)
   			where a.callFlowId = p_callFlowId ;
               
            	if found_rows()>0  
                Then  
                      set errcode = 0;  
                      set errmsg = 'Updated successfuly';  
                      leave sp_exit;  
                End if;  
            
            else
            
            	insert into callFlow (templateName,nodes,edges,`version`,`type`,createDate,lastModifiedDate ,`status`,cfid,companyId,domainId ,`description`,publishData,createdAt,updatedAt)
            				values (templateName,nodes,edges,`version`,`type`,createDate,lastModifiedDate ,`status`,cfid,companyId,domainId ,`description`,publish_data,now(),now());
                            
 			set p_callFlowId   = last_insert_id();
         
            	if row_count()>0  
                Then  
                      set errcode = 0;  
                      set errmsg = 'Inserted successfuly';  
                      leave sp_exit;  
                 End if; 
              
              end if;
              
              end sp_exit;        
                   
              select errcode as errcode, errmsg as errmsg,ifnull(p_callFlowId,0) as callFlowId;     
    End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
