CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_call_update_callMap_sourceid_details`(p_sourceId varchar(255),p_domainId int, p_callFlowId varchar(255))
Begin
  
  	declare v_errcode int default -1;
      declare v_errmsg varchar(20) default 'Failure';
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	if exists(SELECT * FROM callMap WHERE sourceId = p_sourceId AND domainId = p_domainId limit 1) then
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  		update callMap SET callFlowId = p_callFlowId, updatedAt=now()
          where sourceId = p_sourceId and domainId = p_domainId;
          
          if row_Count() > 0 then
  			set v_errcode = 0 ;
              set v_errmsg = 'Success : Inserted' ;
          End if;
          
  	else
  		insert into callMap(sourceId,createdAt,domainId,callFlowId)
          values(p_sourceId,now(),p_domainId,p_callFlowId);
          
          if row_Count() > 0 then
  			set v_errcode = 0 ;
              set v_errmsg = 'Success : updated' ;
          End if;
          
      End if;
  
  	select v_errcode as errcode, v_errmsg as errmsg;
  End ;;
DELIMITER ;
