/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_CategoryArticleDetails`(
	  p_domainId				INT
	 ,p_knowledgeBaseType		INT
 )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 
			WITH ChatCategoryWithCounts AS (
			SELECT 
				kbc.CategoryId,
				kbc.CategoryName,
				kbc.CategoryDescription,
				COUNT(kba.ArticleId) AS fileCount,
				kbc.knowledgeBaseType,
                u.UserName,
                kbc.UpdatedDate,
                kb.kid
			FROM tb_KnowledgeBaseDtl 			kb
			JOIN tb_KnowledgeBaseCategory 		kbc ON kb.kid = kbc.fk_kid
			LEFT JOIN tb_KnowledgeBaseArticleDtl kba ON kba.categoryId = kbc.CategoryId
            JOIN tb_User u ON u.UserID = kbc.createdBy
			WHERE kb.domainId 	= p_domainId
			AND kbc.knowledgeBaseType 	= p_knowledgeBaseType
			GROUP BY kbc.CategoryId, kbc.CategoryName, kbc.CategoryDescription, kbc.knowledgeBaseType, u.UserName, kbc.UpdatedDate, kb.kid
		)
		SELECT 
			JSON_ARRAYAGG(
				JSON_OBJECT(
					"CategoryId", CategoryId,
					"CategoryName", CategoryName,
					"CategoryDescription", CategoryDescription,
					"fileCount", fileCount,
					"knowledgeBaseType",knowledgeBaseType,
                    "createdBy",UserName,
                    "updatedAt",DATE_FORMAT(UpdatedDate,'%d/%m/%Y'),
                    "kid",kid
				)
			) AS ChatCategory
		FROM ChatCategoryWithCounts;
			
		SELECT 	 JSON_ARRAYAGG(JSON_OBJECT("ArticleId",kba.ArticleId
										 ,"articlePath",kba.articlePath
										 ,"articleLanguage",kba.articleLanguage
                                         ,"createdBy",u.UserName
                                         ,"updatedAt",DATE_FORMAT(kba.updatedAt,'%d/%m/%Y')
                                         ,"kid",kb.kid))  		as ChatArticle   
		FROM tb_KnowledgeBaseDtl 			kb
		LEFT JOIN tb_KnowledgeBaseArticleDtl kba ON kba.fk_kid = kb.kid
        JOIN tb_User u ON u.UserID = kba.createdBy
		WHERE 	kb.domainId 	= p_domainId
		AND 	kba.knowledgeBaseType 	= p_knowledgeBaseType
		AND kba.categoryId IS NULL
		AND webPageUrl IS NULL;	

		SELECT 	kba.fk_kid as kid,kba.ArticleId,kba.webPageUrl                                 
		FROM tb_KnowledgeBaseDtl 			kb
		JOIN tb_KnowledgeBaseArticleDtl kba ON kba.fk_kid = kb.kid
		WHERE 	kb.domainId 	= p_domainId
		AND 	kba.knowledgeBaseType 	= p_knowledgeBaseType
		AND kba.categoryId IS NULL
		AND articlePath IS NULL;	
        
		WITH ArticleCounts AS (
        SELECT 
            KBA.knowledgeBaseType,
            COUNT(KBA.ArticleId) AS ArticleCount
        FROM tb_KnowledgeBaseDtl KB
        JOIN tb_KnowledgeBaseArticleDtl KBA ON KB.kid = KBA.fk_kid
        WHERE KB.domainId = p_domainId
        AND webPageUrl IS NULL
		AND KBA.knowledgeBaseType IN (2007001,2007002)
        GROUP BY KBA.knowledgeBaseType
		),
		CategoryCounts AS (
			SELECT 
				KBC.knowledgeBaseType,
				COUNT(KBC.CategoryId) AS CategoryCount
			FROM tb_KnowledgeBaseDtl KB
			JOIN tb_KnowledgeBaseCategory KBC ON KB.kid = KBC.fk_kid
			WHERE KB.domainId = p_domainId
			AND KBC.knowledgeBaseType IN (2007001,2007002)
			GROUP BY KBC.knowledgeBaseType
		)  SELECT 
			JSON_ARRAYAGG(
				JSON_OBJECT(
					"knowledgeBaseType", TC.TypeCodeName,
					"ArticleCount", COALESCE(A.ArticleCount, 0),
					"CategoryCount", COALESCE(C.CategoryCount, 0)
				)
			) AS CategoryArticleCount
		FROM TypeCode TC
		LEFT JOIN ArticleCounts A ON TC.TypeCodeID = A.knowledgeBaseType
		LEFT JOIN CategoryCounts C ON TC.TypeCodeID = C.knowledgeBaseType
		WHERE TC.TypeCodeID IN (2007001,2007002);
    
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                 
                 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
