CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_chatFlow_add_language_info`(
	p_domainId int,
  	p_chatFlowId int,
  	p_addonId int,
  	p_isEnabled tinyint,
	p_translatedText json,
    p_addonName varchar(150)
   )
Begin
  	Declare v_errcode int;
	Declare v_errmsg varchar(50);
	Declare v_id int;
      
      
      if not exists(select 1 from tb_chatFlow_secondary_language_info where domainId = p_domainId and chatFlowId = p_chatFlowId and addonId = p_addonId limit 1) then
  		insert into tb_chatFlow_secondary_language_info(domainId, chatFlowId, addonId, isEnabled ,translatedText, addonName)
		values(p_domainId, p_chatFlowId, p_addonId, p_isEnabled, p_translatedText, p_addonName);
          
          set v_id = last_insert_id();
          
          if row_count()>0 then
  			set v_errcode = 0;
              set v_errmsg = 'Inserted';
          End if;
      else
  		update tb_chatFlow_secondary_language_info
          set 	updatedDate = current_timestamp(),
				isEnabled = ifnull(p_isEnabled,isEnabled),
				translatedText = ifnull(p_translatedText,translatedText)
          where domainId = p_domainId and chatFlowId = p_chatFlowId and addonId = p_addonId;
          
          set v_errcode = 0;
  		set v_errmsg = 'Updated';
          
      End if;
      
      select v_errcode as errcode, v_errmsg as errmsg;
   End ;;
DELIMITER ;
