CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_chatFlow_set_language_settings`(
	p_domainId int,
	p_chatFlowId int,
    p_isEnabled tinyint
 )
Begin
		Declare v_errcode int;
		Declare v_errmsg varchar(50);
        
        if exists(select 1 from chatFlowHistory where domainId = p_domainId and chatFlowId = p_chatFlowId limit 1) then
			update chatFlowHistory 
            set isLangEnabled = ifnull(p_isEnabled,isLangEnabled)
            where domainId = p_domainId and chatFlowId = p_chatFlowId;
            
            set v_errcode = 0;
			set v_errmsg = 'Updated';
            
        Else
			set v_errcode = -1;
			set v_errmsg = 'Record not found';
        End if;
        
        select v_errcode as errcode, v_errmsg as errmsg; 
 End ;;
