CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_check_email_domain_name`(
		p_domainId		int
	,	p_domainName	varchar(550)
)
begin
	
    declare v_errcode int;
    declare v_errmsg varchar(100);
    
sp_exit:begin
    
	if exists(select 1 from ccaas_email_domain_configuration 
				where domainName = p_domainName 
				AND domainId = p_domainId limit 1)
    then
		set v_errcode 	= -2;
        set v_errmsg	= 'Domain name already exists';
		leave sp_exit;
	end if;
end ;    
    select v_errcode as errcode,v_errmsg as errmsg;
end ;;
