				LEFT JOIN 	temp_ChatHistory_cal_final CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;  
		ELSEIF p_columnNameCompare = 'Average chat wait time'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(SUM(averageChatWaitTime),0) AS 'Average chat wait time'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_ChatHistory_cal_final CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;   
		ELSEIF p_columnNameCompare = 'Average chat reply time'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(SUM(averageChatReplyTime),0) AS 'Average chat reply time'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_ChatHistory_cal_final CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;
     ELSEIF p_columnNameCompare = 'Total e-mail'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(SUM(totalEmails),0) AS 'Total e-mail'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_EmailHistory_cal_final CH	ON CH.SessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;
	ELSEIF p_columnName = 'Total SMS'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(SUM(totalSMS),0) AS 'Total SMS'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_SMSHistory_cal_final CH ON CH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;
	ELSEIF p_columnName = 'Total social media'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(IFNULL(SUM(totalWhatsapp),0) +
						IFNULL(SUM(totalFacebook),0) +
						IFNULL(SUM(totalInstagram),0),0) AS 'Total social media'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_WhatsappHistory_cal_final WH ON WH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_FacebookHistory_cal_final FH ON FH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_InstagramHistory_cal_final IH ON IH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;
	ELSEIF p_columnName = 'Total chat'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(IFNULL(SUM(totalWhatsapp),0) +
						IFNULL(SUM(totalFacebook),0) +
						IFNULL(SUM(totalInstagram),0) +
                        IFNULL(SUM(totalWebChats),0),0) AS 'Total chat'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_WhatsappHistory_cal_final WH ON WH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_FacebookHistory_cal_final FH ON FH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_InstagramHistory_cal_final IH ON IH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
                LEFT JOIN 	temp_ChatHistory_cal_final CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;
	ELSEIF p_columnName = 'Service level'
			 THEN
				INSERT INTO tmp_resultCompare
                SELECT 	'Result2'
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	IFNULL(IFNULL(SUM(answeredDurationCall),0) +
						IFNULL(SUM(answeredDurationChat),0) +
						IFNULL(SUM(answeredDurationWhatsapp),0) +
						IFNULL(SUM(answeredDurationInsta),0) +
                        IFNULL(SUM(answeredDurationFacebook),0),0) AS 'Service level'
				FROM 	tmp_timings		t_T	
				LEFT JOIN 	temp_WhatsappHistory_cal_final WH ON WH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_FacebookHistory_cal_final FH ON FH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_InstagramHistory_cal_final IH ON IH.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
				LEFT JOIN 	temp_CallHistory_cal_final CC ON CC.SessionStartTime BETWEEN t_T.startTimestamp AND t_T.endTimestamp
                LEFT JOIN 	temp_ChatHistory_cal_final CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
				GROUP BY t_T.startDateTime, t_T.endDateTime;
     END IF;  
SELECT * FROM tmp_resultCompare;
	 
    
    

end ;;
DELIMITER ;
