CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_create_call_init_details`(
p_sessionId varchar(250), p_domainId int, p_QueueId int, p_IsInBound tinyint, p_customerNumber bigint, p_calledNumber bigint 
)
Begin

		declare v_errcode int;
		declare v_errmsg varchar(55);
        declare v_CallHistoryId bigint;

		sp_exit:Begin
			if p_domainId is null or p_domainId=0 then
				set v_errcode = -1;
				set v_errmsg = 'DomainId should not be empty';
				leave sp_exit;
			End if;
	
			if exists (select 1 from tb_CallHistory a where a.sessionId = p_sessionId limit 1) then
				set v_errcode = -1;
				set v_errmsg = 'Call details already inserted';
				leave sp_exit;
			End if;
        
			insert into tb_CallHistory(sessionId,domainId,IsInBound,customerNumber,calledNumber,createdAt)
			values(p_sessionId,p_domainId,p_IsInBound,p_customerNumber,p_calledNumber,now());
            
            set v_CallHistoryId = last_insert_id();
                
				if v_CallHistoryId <> 0 or v_CallHistoryId is not null then
					insert into tb_CallDurationHistory(CallHistoryId,QueueId,createdAt)
					values(v_CallHistoryId,p_QueueId,now());
				end if;    
                
				if row_count() > 0 then
					set v_errcode = 0;
					set v_errmsg = 'inserted successfully';
					leave sp_exit;
				end if;
		End;
			
		select v_errcode as errcode, v_errmsg as errmsg,v_CallHistoryId as CallHistoryId;
End ;;
DELIMITER ;
