CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_create_call_session_history_details`(
         	p_sessionId 		varchar(250),
         	p_sessionStartTime 	bigint,
         	p_sessionEndTime 	bigint, 
         	p_customerNumber 	VARCHAR(30),
         	p_domainId 			int,
         	p_dispositionId 	int,  
         	p_UMNStatus 		int,  
         	p_IsInBound 		tinyint, 
         	p_dialDuration 		bigint,  
         	p_disconnectedBy 	bigint,  
         	p_queueDuration 	bigint,  
         	p_assignedTo 		bigint,  
         	p_assignedBy 		bigint,  
         	p_assignedOn 		bigint,  
         	p_calledNumber 		bigint, 
         	p_waitDuration 		bigint,
         	p_afterCallWorkTime int,
         	p_recordingTypeId 	int,
         	p_Istransferred 	tinyint,
         	p_transferredTypeId int,
         	p_markAsRead 		tinyint,
         	p_CustomerId 		int,
         	p_voicemailUrl 		varchar(500),
         	p_ticketId 			bigint,
         	p_StartTime 		bigint,
         	p_EndTime 			bigint,
         	p_Duration 			bigint,
         	p_AgentHoldDuration bigint,
         	p_AgentId 			bigint,
         	p_AgentSkillId 		int,
         	p_IsBot 			tinyint,
         	p_BotId 			int,
         	p_RecordingUrl 		varchar(500),
         	p_transferredTime 	bigint,
         	p_recordingDuration bigint,
         	p_QueueId 			int,
         	p_Message 			json,
         	p_CallHistoryId 	bigint,
         	p_callDuration 		bigint,
         	p_callCost			DECIMAL(20,2),
         	p_IsAbandoned		TINYINT,
         	p_transferedBy		BIGINT,
         	p_transferedTo 		BIGINT,
         	p_businessStartTime bigint,
         	p_businessEndTime 	bigint,
         	P_IsMissedCall		TINYINT,
         	p_isListen 			TINYINT,
         	p_isWhisper 		TINYINT,
         	p_isBarge 			TINYINT,
         	p_IsOutOfBussinessHour	TINYINT,
            p_isOutboundCampaign 	TINYINT
          )
sp : BEGIN              
      		DECLARE v_errcode 						INT;
      		DECLARE v_errmsg 						varchar(155);
      		DECLARE v_CallHistoryId 				bigint;
      		DECLARE v_curDate						datetime;
      		DECLARE v_LoginDate						datetime;
      		DECLARE v_AgentId						int;
      		DECLARE v_transferedBy					BIGINT;
      		DECLARE v_transferedTo 					BIGINT;
      		DECLARE v_CallDurationHistoryId			BIGINT;
      		DECLARE v_CallDurationHistoryId_1		BIGINT;
      		DECLARE v_SourceCallDurationHistoryId	BIGINT;            
      		DECLARE v_LastAgentId					BIGINT;
      		DECLARE v_LastUMNStatus 				INT;   
      		DECLARE v_LastCallDurationHistoryId		BIGINT;
      		DECLARE v_coid							INT;
      		DECLARE v_callAgentDispositionId		INT;
  			DECLARE v_IsBot 						TINYINT;
  			DECLARE v_sessionstartime			datetime;
              
              DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
  			BEGIN
  				GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
  				SET v_errmsg = CONCAT(@st, ' : ', @p2); 		
  				SELECT -1 AS errcode, v_errmsg AS errmsg;
					insert into callsessionstartendlog(domainId,sessionId,starttime,errcode,errmsg)
					values(p_domainId,p_sessionId,v_sessionstartime,v_errcode,v_errmsg);
  				ROLLBACK;
  			END; 
              
  			SET v_sessionstartime = current_timestamp();
            
				if exists(SELECT 1 FROM performance_schema.metadata_locks 
							where OBJECT_NAME = 'tb_CallHistory' and LOCK_TYPE = 'SHARED_READ' and LOCK_STATUS = 'GRANTED' limit 1) then
					call auto_kill_blocking_callhistoryqueries();
				End if;
            
			
			
            
               
      		DROP TEMPORARY TABLE IF EXISTS temp_User;
      		CREATE TEMPORARY TABLE temp_User    
      		select 	UserID 
      			,	ext     
      		from 	tb_User 
      		where 	ext 		IN  (p_AgentId,p_transferedBy,p_transferedTo)
      		and 	domainId 	= p_domainId;
              
      		select coid into v_coid 
      		from customer_contact 
      		where domainId = p_domainId 
      		and primaryPhoneNumber = p_customerNumber collate utf8mb4_unicode_ci limit 1;
              
              IF p_dispositionId IN (1121001,1121002,1121004,1121003,1121005) 
         		THEN
         			SELECT 	DS.did
                     INTO 	v_callAgentDispositionId  
                     FROM 	disposition_status	DS
                     JOIN 	TypeCode			TY	ON TY.TypeCodeName	collate utf8mb4_unicode_ci = DS.dispositionName
                     WHERE 	TY.TypeCodeID 	= p_dispositionId
                     AND 	DS.domainId		= p_domainId;
         		ELSE
         			SET v_callAgentDispositionId = CASE WHEN p_dispositionId = 0 THEN NULL ELSE p_dispositionId END;        
        		END IF;        
      
              	SELECT 	UserID INTO v_transferedTo 	FROM temp_User WHERE ext = p_transferedTo;
              	SELECT 	UserID INTO v_transferedBy 	FROM temp_User WHERE ext = p_transferedBy;
              	SELECT 	UserID INTO v_AgentId 		FROM temp_User WHERE ext = p_AgentId;
      
              	SET v_curDate = NOW();
              	SET v_LoginDate = CAST(v_curDate AS DATE);
                                             
              	START TRANSACTION;      				
              	  sp_exit : begin
              		if p_domainId is null or p_domainId=0 then
              			set v_errcode = -1;
              			set v_errmsg = 'DomainId should not be empty';
              			leave sp_exit;
              		End if;
              		  
              		SELECT 	CallHistoryId INTO v_CallHistoryId
              		FROM 	tb_CallHistory
              		WHERE	sessionId	= p_sessionId collate utf8mb4_unicode_ci; 
      
              		SELECT 	AgentId, UMNStatus, CallDurationHistoryId 
              		INTO 	v_LastAgentId, v_LastUMNStatus, v_LastCallDurationHistoryId 
              		FROM 	tb_CallDurationHistory 	DH
              		WHERE	CallHistoryId = v_CallHistoryId
              		ORDER BY CallDurationHistoryId DESC LIMIT 1;
      
              		IF NOT EXISTS (	SELECT 	1 
              						FROM 	tb_AgentBusinessHour
              						WHERE	AgentId 	= v_AgentId
              						AND 	DateOfLogin	= v_LoginDate) 
             		AND IFNULL(v_AgentId,0) <> 0
              		THEN
              			INSERT INTO tb_AgentBusinessHour
              			 (	agentId				
              				 ,DateOfLogin		
              				 ,businessStartTime 	
              				 ,businessEndTime 
              				 ,createDate
              			 )
              			 VALUES
              			 (	v_AgentId
              				,v_LoginDate
           				,p_businessStartTime
              				,p_businessEndTime
              				,v_curDate             
              			 );	                
              		 END IF;
                                    
     			  IF v_CallHistoryId IS NOT NULL 
     			  THEN				
              			UPDATE tb_CallHistory 
              			SET 
              			sessionStartTime 		= ifnull(p_sessionStartTime,sessionStartTime)
              			,sessionEndTime	 		= ifnull(p_sessionEndTime,sessionEndTime)
              			,customerNumber 		= ifnull(p_customerNumber,customerNumber)
              			,domainId 				= ifnull(p_domainId,domainId)			
              			,IsInBound 				= ifnull(p_IsInBound,IsInBound)
              			,dialDuration 			= ifnull(p_dialDuration,dialDuration)
              			,disconnectedBy 		= ifnull(p_disconnectedBy,disconnectedBy)
              			,queueDuration 			= ifnull(p_queueDuration,queueDuration)
              			,assignedTo 			= ifnull(p_assignedTo,assignedTo)
              			,assignedBy 			= ifnull(p_assignedBy,assignedBy)
              			,assignedOn 			= ifnull(p_assignedOn,assignedOn)
              			,calledNumber			= ifnull(p_calledNumber,calledNumber)
              			,waitDuration 			= ifnull(p_waitDuration,waitDuration)
              			,recordingTypeId 		= ifnull(p_recordingTypeId,recordingTypeId)
              			,CustomerId 			= CASE WHEN p_CustomerId = 0 THEN v_coid ELSE p_CustomerId END
              			,voicemailUrl 			= ifnull(p_voicemailUrl,voicemailUrl)
              			,callDuration			= ifnull(p_callDuration,callDuration) 			
              			,callCost				= ifnull(p_callCost,callCost)
              			,IsAbandoned			= ifnull(p_IsAbandoned,IsAbandoned)
         				,IsOutOfBussinessHour	= IFNULL(p_IsOutOfBussinessHour,IsOutOfBussinessHour)                 
              			
              			,updatedAt 				= v_curDate
              			where CallHistoryId 	= v_CallHistoryId;
      
   				
                        
      				IF p_QueueId IS NOT NULL OR v_callAgentDispositionId IS NOT NULL
      				THEN
      					UPDATE 	tb_CallDurationHistory b 
      					SET 	b.QueueId 		= IFNULL(p_QueueId,b.QueueId)
      					,		b.dispositionId	= IFNULL(v_callAgentDispositionId,b.dispositionId)
      					WHERE 	b.CallHistoryId = v_CallHistoryId 
      				   AND 	AgentId 		IS NULL 
      				   AND 	IsBot			= 0;	
      				END IF;
                                
      				IF v_AgentId IS NOT NULL 
           			THEN
      					SET v_CallDurationHistoryId_1 = NULL;
                          
           				
                           SELECT CallDurationHistoryId 
                           INTO 	v_CallDurationHistoryId_1 
                           FROM 	tb_CallDurationHistory 
                           WHERE 	CallHistoryId 	= v_CallHistoryId 
                           AND 	AgentId 		IS NULL 
                           AND 	IsBot			= 0 LIMIT 1;
                           
              				
                           IF v_CallDurationHistoryId_1  IS NULL AND IFNULL(p_disconnectedBy,0) <> 0
                           THEN
           					SELECT 	CallDurationHistoryId 
           					INTO 	v_CallDurationHistoryId_1 
           					FROM 	tb_CallDurationHistory 
           					WHERE 	CallHistoryId 	= v_CallHistoryId 
           					AND 	AgentId 		= v_AgentId
      						ORDER BY CallDurationHistoryId DESC LIMIT 1;
                           END IF;
                                      
              				IF v_CallDurationHistoryId_1 IS NOT NULL
              				 then
              					update tb_CallDurationHistory b 
              					set  b.StartTime 			= ifnull(p_StartTime,b.StartTime)
              						,b.EndTime 				= ifnull(p_EndTime,b.EndTime)
              						,b.Duration 			= ifnull(p_Duration,b.Duration)
              						,b.AgentHoldDuration 	= ifnull(p_AgentHoldDuration,b.AgentHoldDuration)
              						,b.AgentId 				= ifnull(v_AgentId,b.AgentId)
              						,b.AgentSkillId 		= ifnull(p_AgentSkillId,b.AgentSkillId)
              						,b.IsBot 				= ifnull(p_IsBot,b.IsBot)
              						,b.BotId 				= ifnull(p_BotId,b.BotId)
              						,b.RecordingUrl 		= ifnull(p_RecordingUrl,b.RecordingUrl)
              						,b.transferredTime 		= ifnull(p_transferredTime,b.transferredTime)
              						,b.recordingDuration 	= ifnull(p_recordingDuration,b.recordingDuration)
              						,b.dialDuration 		= ifnull(p_dialDuration,b.dialDuration)
              						,b.transferredTypeId 	= ifnull(p_transferredTypeId,b.transferredTypeId)
              						,b.QueueId 				= ifnull(p_QueueId,b.QueueId)
              						,b.dispositionId		= IFNULL(v_callAgentDispositionId,b.dispositionId)
              						,b.UMNStatus 			= IFNULL(p_UMNStatus,b.UMNStatus)
              						,b.transferedBy 		= IFNULL(v_transferedBy,b.transferedBy)
              						,b.transferedTo 		= IFNULL(v_transferedTo,b.transferedTo)   
              						,b.ticketId 			= ifnull(p_ticketId,b.ticketId)
         							,b.IsMissedCall			= ifnull(p_IsMissedCall,b.IsMissedCall)
         							,b.isListen 			= ifnull(p_isListen,b.isListen)
         							,b.isWhisper 			= ifnull(p_isWhisper,b.isWhisper)
         							,b.isBarge 				= ifnull(p_isBarge,b.isBarge)
              						,b.updatedAt 			= v_curDate
              					where CallDurationHistoryId	= v_CallDurationHistoryId_1;			
              				
              			  ELSEIF (p_UMNStatus IN (3,4) OR IFNULL(v_LastAgentId,0) <> v_AgentId OR v_LastUMNStatus IN (3,4))
              			  THEN
              				insert into tb_CallDurationHistory
              					(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime
              					,recordingDuration,QueueId,createdAt,dialDuration,transferredTypeId,dispositionId,UMNStatus,transferedBy 
              					,transferedTo,ticketId,IsMissedCall,isListen,isWhisper,isBarge,updatedAt)
              					values(v_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,v_AgentId,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime
              					,p_recordingDuration,p_QueueId,v_curDate,p_dialDuration,p_transferredTypeId,v_callAgentDispositionId,p_UMNStatus,v_transferedBy
              					,v_transferedTo,p_ticketId,p_IsMissedCall,p_isListen,p_isWhisper,p_isBarge,v_curDate);
              				   
              				   SET v_CallDurationHistoryId = last_insert_id();						
              
              				ELSE IF v_LastCallDurationHistoryId IS NOT NULL	
              				 then
              					update tb_CallDurationHistory b 
              					set  b.StartTime 		= ifnull(p_StartTime,b.StartTime)
              						,b.EndTime 				= ifnull(p_EndTime,b.EndTime)
              						,b.Duration 			= ifnull(p_Duration,b.Duration)
              						,b.AgentHoldDuration 	= ifnull(p_AgentHoldDuration,b.AgentHoldDuration)					
              						,b.AgentSkillId 		= ifnull(p_AgentSkillId,b.AgentSkillId)
              						,b.IsBot 				= ifnull(p_IsBot,b.IsBot)
              						,b.BotId 				= ifnull(p_BotId,b.BotId)
              						,b.RecordingUrl 		= ifnull(p_RecordingUrl,b.RecordingUrl)
              						,b.transferredTime 		= ifnull(p_transferredTime,b.transferredTime)
              						,b.recordingDuration 	= ifnull(p_recordingDuration,b.recordingDuration)
              						,b.dialDuration 		= ifnull(p_dialDuration,b.dialDuration)
              						,b.transferredTypeId 	= ifnull(p_transferredTypeId,b.transferredTypeId)
              						,b.QueueId 				= ifnull(p_QueueId,b.QueueId)
              						,b.dispositionId		= IFNULL(v_callAgentDispositionId,b.dispositionId)
              						,b.UMNStatus 			= IFNULL(p_UMNStatus,b.UMNStatus)
              						,b.transferedBy 		= IFNULL(v_transferedBy,b.transferedBy)
              						,b.transferedTo 		= IFNULL(v_transferedTo,b.transferedTo)
              						,b.ticketId 			= ifnull(p_ticketId,b.ticketId)
              						,b.IsMissedCall			= ifnull(p_IsMissedCall,b.IsMissedCall)
              						,b.isListen 			= ifnull(p_isListen,b.isListen)
              						,b.isWhisper 			= ifnull(p_isWhisper,b.isWhisper)
              						,b.isBarge 				= ifnull(p_isBarge,b.isBarge)
              						,b.updatedAt 			= v_curDate
              					where CallDurationHistoryId = v_LastCallDurationHistoryId;
              				
              				
              				else
              					insert into tb_CallDurationHistory
              					(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime
              					,recordingDuration,QueueId,createdAt,dialDuration,transferredTypeId,dispositionId,UMNStatus,transferedBy 
              					,transferedTo,ticketId,IsMissedCall,isListen,isWhisper,isBarge,updatedAt)
              					values(v_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,v_AgentId,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime
              					,p_recordingDuration,p_QueueId,v_curDate,p_dialDuration,p_transferredTypeId,v_callAgentDispositionId,p_UMNStatus,v_transferedBy
              					,v_transferedTo,p_ticketId,p_IsMissedCall,p_isListen,p_isWhisper,p_isBarge,v_curDate);
              				   
              				   SET v_CallDurationHistoryId = last_insert_id();
              				End if; 
              			End if;	
              		End if; 
                           				
              			if found_rows()>0 then
              				set v_errcode = 0;
              				set v_errmsg = 'updated successfully';
              				leave sp_exit;
              			end if;         
              		else
                    if not exists(select 1 from tb_CallHistory where sessionId = p_sessionId limit 1) then
                    
              			insert into tb_CallHistory(	sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,IsInBound,dialDuration,disconnectedBy,queueDuration,
              			assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,recordingTypeId,CustomerId,voicemailUrl,createdAt,callBack,updatedAt
              			,callCost,IsAbandoned,IsOutOfBussinessHour ,isOutboundCampaign)
              			values(p_sessionId,p_sessionStartTime,p_sessionEndTime,p_customerNumber,p_domainId,p_IsInBound,p_dialDuration,p_disconnectedBy,p_queueDuration,
              			p_assignedTo,p_assignedBy,p_assignedOn,p_calledNumber,p_waitDuration,p_recordingTypeId,p_CustomerId,p_voicemailUrl,v_curDate,3  ,v_curDate
              			,p_callCost,p_IsAbandoned,p_IsOutOfBussinessHour ,p_isOutboundCampaign);
                        
                        set v_CallHistoryId = last_insert_id();  
                        
					else
							select CallHistoryId into v_CallHistoryId from tb_CallHistory where sessionId = p_sessionId limit 1;
                    End if;
                              				    
              
              			insert into tb_CallDurationHistory
              			(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime,recordingDuration
              			,QueueId,createdAt,dialDuration,transferredTypeId,dispositionId,UMNStatus,transferedBy,transferedTo,ticketId,IsMissedCall,isListen,isWhisper,isBarge,updatedAt)
              			values
              			(v_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,v_AgentId,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime,p_recordingDuration
              			,p_QueueId,v_curDate,p_dialDuration,p_transferredTypeId,v_callAgentDispositionId,p_UMNStatus,v_transferedBy,v_transferedTo,p_ticketId,p_IsMissedCall,p_isListen,p_isWhisper,p_isBarge,v_curDate);
              
              			SET v_CallDurationHistoryId = last_insert_id();   
                                                                
              	   
              		End if;
              	
              		if row_count() > 0 then
              			set v_errcode = 0;
              			set v_errmsg = 'inserted successfully';
              			leave sp_exit;
              		end if;
              		end sp_exit;       
                               
              		IF p_transferedBy IS NOT NULL
              		THEN
              			SELECT 	CallDurationHistoryId INTO v_SourceCallDurationHistoryId		
              			FROM 	tb_CallDurationHistory
              			WHERE 	CallHistoryId	= v_CallHistoryId
              			AND 	AgentId			= p_transferedBy;	
              			
              			IF v_SourceCallDurationHistoryId IS NOT NULL AND v_CallDurationHistoryId IS NOT NULL
              			THEN 
              				CALL up_TransaferCallMessage(v_SourceCallDurationHistoryId,v_CallDurationHistoryId);
              			END IF;
              		END IF;
              											
              		SELECT JSON_OBJECT('sessionId',p_sessionId,'errcode',v_errcode,'errmsg',v_errmsg,'CallHistoryId',v_CallHistoryId) AS jsoncol ; 					   
                   
						insert into callsessionstartendlog(domainId,sessionId,starttime,errcode,errmsg)
						values(p_domainId,p_sessionId,v_sessionstartime,v_errcode,v_errmsg);                   
              	COMMIT;
               
               End ;;
DELIMITER ;
