DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_create_call_session_history_detailsYYY`(
         	p_sessionId varchar(250),
         	p_sessionStartTime bigint,
         	p_sessionEndTime bigint, 
         	p_customerNumber bigint,
         	p_callFlowSourceId int,
         	p_companyId int,  
         	p_domainId int,
         	p_dispositionId int,  
         	p_UMNStatus int,  
         	p_IsInBound tinyint, 
         	p_dialDuration bigint,  
         	p_disconnectedBy bigint,  
         	p_queueDuration bigint,  
         	p_assignedTo bigint,  
         	p_assignedBy bigint,  
         	p_assignedOn bigint,  
         	p_calledNumber bigint, 
         	p_waitDuration bigint,
         	p_afterCallWorkTime int,
         	p_recordingTypeId int,
         	p_Istransferred tinyint,
         	p_transferredTypeId int,
         	p_markAsRead tinyint,
         	p_CustomerId int,
         	p_voicemailUrl varchar(500),
         	p_ticketId bigint,
         	p_StartTime bigint,
         	p_EndTime bigint,
         	p_Duration bigint,
         	p_AgentHoldDuration bigint,
         	p_AgentId bigint,
         	p_AgentSkillId int,
         	p_IsBot tinyint,
         	p_BotId int,
         	p_RecordingUrl varchar(500),
         	p_transferredTime bigint,
         	p_recordingDuration bigint,
         	p_QueueId int,
         	p_Message json,
             p_CallHistoryId bigint,
             p_callDuration bigint,
             p_callBack int
         )
SPreturn : BEGIN

		declare v_errcode int;
		declare v_errmsg varchar(55);
        declare v_CallHistoryId bigint;

			DECLARE EXIT HANDLER FOR SQLEXCEPTION
			BEGIN
				ROLLBACK;
				SET v_errcode = -1;
				SET v_errmsg = CONCAT('Error: '); 
			END;
		 
			DECLARE EXIT HANDLER FOR SQLWARNING
			BEGIN
				ROLLBACK;
				SET v_errcode = -1;
				SET v_errmsg = 'SQL Warning';
			END;
		 
			START TRANSACTION;
			SET v_errcode = 0;
			SET v_errmsg = '';
		 
			
			do GET_LOCK(CONCAT('ccaas_lock_', p_sessionId), 10); 
		 
			
			IF IS_USED_LOCK(CONCAT('ccaas_lock_', p_sessionId)) = 0 THEN
				SET v_errcode = -1;
				SET v_errmsg = 'Failed to acquire lock';
				ROLLBACK;
				LEAVE SPreturn;
			END IF;

		
                  
         	sp_exit : begin     
            
        		if p_domainId is null or p_domainId=0 then
        			set v_errcode = -1;
                    set v_errmsg = 'DomainId should not be empty';
                    leave sp_exit;
                End if;
                
			select CallHistoryId  into v_CallHistoryId
            from tb_CallHistory
            where 	sessionId= p_sessionId;
            
             if v_CallHistoryId is not null
             then
         		update tb_CallHistory a
                 set 
         			a.sessionStartTime 	= ifnull(p_sessionStartTime,a.sessionStartTime)
         			,a.sessionEndTime	 	= ifnull(p_sessionEndTime,a.sessionEndTime)
         			,a.customerNumber 		= ifnull(p_customerNumber,a.customerNumber)
         			,a.callFlowSourceId 	= ifnull(p_callFlowSourceId,a.callFlowSourceId)
         			,a.companyId 			= ifnull(p_companyId,a.companyId)
         			,a.domainId 			= ifnull(p_domainId,a.domainId)
         			,a.dispositionId 		= ifnull(p_dispositionId,a.dispositionId)
         			,a.UMNStatus 			= ifnull(p_UMNStatus,a.UMNStatus)
         			,a.IsInBound 			= ifnull(p_IsInBound,a.IsInBound)
         			,a.dialDuration 		= ifnull(p_dialDuration,a.dialDuration)
         			,a.disconnectedBy 		= ifnull(p_disconnectedBy,a.disconnectedBy)
         			,a.queueDuration 		= ifnull(p_queueDuration,a.queueDuration)
         			,a.assignedTo 			= ifnull(p_assignedTo,a.assignedTo)
         			,a.assignedBy 			= ifnull(p_assignedBy,a.assignedBy)
         			,a.assignedOn 			= ifnull(p_assignedOn,a.assignedOn)
         			,a.calledNumber			= ifnull(p_calledNumber,a.calledNumber)
         			,a.waitDuration 		= ifnull(p_waitDuration,a.waitDuration)
         			,a.afterCallWorkTime 	= ifnull(p_afterCallWorkTime,a.afterCallWorkTime)
         			,a.recordingTypeId 		= ifnull(p_recordingTypeId,a.recordingTypeId)
         			,a.Istransferred 		= ifnull(p_Istransferred,a.Istransferred)
         			,a.transferredTypeId 	= ifnull(p_transferredTypeId,a.transferredTypeId)
         			,a.markAsRead 			= ifnull(p_markAsRead,a.markAsRead)
         			,a.CustomerId 			= ifnull(p_CustomerId,a.CustomerId)
         			,a.voicemailUrl 		= ifnull(p_voicemailUrl,a.voicemailUrl)
         			,a.ticketId 			= ifnull(p_ticketId,a.ticketId)
         			,a.callDuration			= ifnull(p_callDuration,a.callDuration)
                   ,a.callBack				= ifnull(p_callBack,a.callBack)
         			,a.updatedAt 			= now()
                 where a.sessionId collate utf8mb4_unicode_ci  = p_sessionId;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                 select CDH.CallHistoryId into p_CallHistoryId from tb_CallHistory CDH where CDH.sessionId collate utf8mb4_unicode_ci = p_sessionId limit 1;
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
                 update tb_CallDurationHistory b 
                 set  b.StartTime 			= ifnull(p_StartTime,b.StartTime)
         			,b.EndTime 				= ifnull(p_EndTime,b.EndTime)
         			,b.Duration 			= ifnull(p_Duration,b.Duration)
         			,b.AgentHoldDuration 	= ifnull(p_AgentHoldDuration,b.AgentHoldDuration)
         			,b.AgentId 				= ifnull(p_AgentId,b.AgentId)
         			,b.AgentSkillId 		= ifnull(p_AgentSkillId,b.AgentSkillId)
         			,b.IsBot 				= ifnull(p_IsBot,b.IsBot)
         			,b.BotId 				= ifnull(p_BotId,b.BotId)
         			,b.RecordingUrl 		= ifnull(p_RecordingUrl,b.RecordingUrl)
         			,b.transferredTime 		= ifnull(p_transferredTime,b.transferredTime)
         			,b.recordingDuration 	= ifnull(p_recordingDuration,b.recordingDuration)
         			,b.QueueId 				= ifnull(p_QueueId,b.QueueId)
         			,b.updatedAt 			= now()
                 where b.CallHistoryId = v_CallHistoryId;
         
         		if p_Message is not null then
         			update tb_CallMessage a
         				set a.Message = if(a.Message is null,p_Message,JSON_ARRAY_APPEND(a.Message, '$', p_Message))
         					,a.updatedAt = now()
         			where a.CallHistoryId = v_CallHistoryId;
         		End if;
         
         		if found_rows()>0 then
         			set v_errcode = 0;
         			set v_errmsg = 'updated successfully';
         			leave sp_exit;
         		end if;
         
             else
             
                     insert into tb_CallHistory(sessionId,sessionStartTime,sessionEndTime,customerNumber,callFlowSourceId,companyId,domainId,dispositionId,UMNStatus,IsInBound,dialDuration,
         				disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,Istransferred,
         				transferredTypeId,markAsRead,CustomerId,voicemailUrl,ticketId,createdAt,callBack)
                     values(p_sessionId,p_sessionStartTime,p_sessionEndTime,p_customerNumber,p_callFlowSourceId,p_companyId,p_domainId,p_dispositionId,p_UMNStatus,p_IsInBound,p_dialDuration,
         				p_disconnectedBy,p_queueDuration,p_assignedTo,p_assignedBy,p_assignedOn,p_calledNumber,p_waitDuration,p_afterCallWorkTime,p_recordingTypeId,p_Istransferred,
         				p_transferredTypeId,p_markAsRead,p_CustomerId,p_voicemailUrl,p_ticketId,now(),p_callBack);
                     
                     set v_CallHistoryId = last_insert_id();       
                     
         			if p_CallHistoryId <> 0 or p_CallHistoryId is not null then
         				insert into tb_CallDurationHistory(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime,recordingDuration,QueueId,createdAt)
                         values(p_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,p_AgentId,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime,p_recordingDuration,p_QueueId,now());
                     
         				insert into tb_CallMessage(CallHistoryId,Message,createdAt)
                         values(p_CallHistoryId,p_Message,now());
                        
                     End if;
                 
         		if row_count() > 0 then
         			set v_errcode = 0;
         			set v_errmsg = 'inserted successfully';
         			leave sp_exit;
         		end if;
         	end if;
             
         	end sp_exit;
        
               	select RELEASE_LOCK(CONCAT('ccaas_lock_', p_sessionId))as rls,v_errcode as errcode, v_errmsg as errmsg,v_CallHistoryId as CallHistoryId;
                

    
    COMMIT;
                           
         End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_create_call_session_history_details_2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_create_call_session_history_details_2`(
    	p_sessionId 		varchar(250),
    	p_sessionStartTime 	bigint,
    	p_sessionEndTime 	bigint, 
    	p_customerNumber 	bigint,
    	p_domainId 			int,
    	p_dispositionId 	int,  
    	p_UMNStatus 		int,  
    	p_IsInBound 		tinyint, 
    	p_dialDuration 		bigint,  
    	p_disconnectedBy 	bigint,  
    	p_queueDuration 	bigint,  
    	p_assignedTo 		bigint,  
    	p_assignedBy 		bigint,  
    	p_assignedOn 		bigint,  
    	p_calledNumber 		bigint, 
    	p_waitDuration 		bigint,
    	p_afterCallWorkTime int,
    	p_recordingTypeId 	int,
    	p_Istransferred 	tinyint,
    	p_transferredTypeId int,
    	p_markAsRead 		tinyint,
    	p_CustomerId 		int,
    	p_voicemailUrl 		varchar(500),
    	p_ticketId 			bigint,
    	p_StartTime 		bigint,
    	p_EndTime 			bigint,
    	p_Duration 			bigint,
    	p_AgentHoldDuration bigint,
    	p_AgentId 			bigint,
    	p_AgentSkillId 		int,
    	p_IsBot 			tinyint,
    	p_BotId 			int,
    	p_RecordingUrl 		varchar(500),
    	p_transferredTime 	bigint,
    	p_recordingDuration bigint,
    	p_QueueId 			int,
    	p_Message 			json,
    	p_CallHistoryId 	bigint,
    	p_callDuration 		bigint,
		p_callCost			DECIMAL(20,2),
		p_IsAbandoned		TINYINT,
		p_transferedBy		INT,
		p_transferedTo 		INT,
		p_businessStartTime bigint,
		p_businessEndTime 	bigint,
		P_IsMissedCall		TINYINT
     )
Begin              
		declare v_errcode 			int;
		declare v_errmsg 			varchar(55);
		declare v_CallHistoryId 	bigint;
		declare v_curDate			datetime;
		declare v_AgentId			int;
		declare v_transferedBy		BIGINT;
		declare v_transferedTo 		BIGINT;
        declare v_IsBot				TINYINT;
       
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
		DROP TEMPORARY TABLE IF EXISTS temp_User;
		CREATE TEMPORARY TABLE temp_User    
    	select 	UserID 
			,	ext     
       from 	tb_User 
       where 	ext 		IN  (p_AgentId,p_transferedBy,p_transferedTo)
       and 	domainId 	= p_domainId;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       
       SELECT 	UserID INTO v_transferedTo 	FROM temp_User WHERE ext = p_transferedTo;
       SELECT 	UserID INTO v_transferedBy 	FROM temp_User WHERE ext = p_transferedBy;
       SELECT 	UserID INTO v_AgentId 		FROM temp_User WHERE ext = p_AgentId;
    		 
    	set v_curDate = now();
                     
    	START TRANSACTION;      				
        sp_exit : begin
    		if p_domainId is null or p_domainId=0 then
    			set v_errcode = -1;
    			set v_errmsg = 'DomainId should not be empty';
    			leave sp_exit;
    		End if;
            
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;            
    		SELECT 	CallHistoryId into v_CallHistoryId
    		FROM 	tb_CallHistory
    		WHERE	sessionId	= p_sessionId;
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
            
            IF v_CallHistoryId IS NULL
            THEN
				insert into tb_CallHistory(	sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,IsInBound,dialDuration,disconnectedBy,queueDuration,
				assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,recordingTypeId,CustomerId,voicemailUrl,createdAt,callBack
				,callCost,IsAbandoned,businessStartTime,businessEndTime)
				values(p_sessionId,p_sessionStartTime,p_sessionEndTime,p_customerNumber,p_domainId,p_IsInBound,p_dialDuration,p_disconnectedBy,p_queueDuration,
				p_assignedTo,p_assignedBy,p_assignedOn,p_calledNumber,p_waitDuration,p_recordingTypeId,p_CustomerId,p_voicemailUrl,v_curDate,3 
				,p_callCost,p_IsAbandoned,p_businessStartTime,p_businessEndTime);

				set v_CallHistoryId = last_insert_id();       

				INSERT INTO tb_CallDurationHistory
				(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime,recordingDuration
				,QueueId,createdAt,dialDuration,transferredTypeId,dispositionId,UMNStatus,transferedBy,transferedTo,ticketId,IsMissedCall)
				VALUES
				(v_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,v_AgentId,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime,p_recordingDuration
				,p_QueueId,v_curDate,p_dialDuration,p_transferredTypeId,p_dispositionId,p_UMNStatus,v_transferedBy,v_transferedTo,p_ticketId,p_IsMissedCall);
                
				set v_errcode = 0;
				set v_errmsg = 'inserted successfully';		                
                leave sp_exit;
            END IF;
            
            IF v_CallHistoryId IS NOT NULL 
            THEN
    			UPDATE tb_CallHistory 
    			SET 
    			sessionStartTime 		= ifnull(p_sessionStartTime,sessionStartTime)
    			,sessionEndTime	 		= ifnull(p_sessionEndTime,sessionEndTime)
    			,customerNumber 		= ifnull(p_customerNumber,customerNumber)
    			,domainId 				= ifnull(p_domainId,domainId)			
    			,IsInBound 				= ifnull(p_IsInBound,IsInBound)
    			,dialDuration 			= ifnull(p_dialDuration,dialDuration)
    			,disconnectedBy 		= ifnull(p_disconnectedBy,disconnectedBy)
    			,queueDuration 			= ifnull(p_queueDuration,queueDuration)
    			,assignedTo 			= ifnull(p_assignedTo,assignedTo)
    			,assignedBy 			= ifnull(p_assignedBy,assignedBy)
    			,assignedOn 			= ifnull(p_assignedOn,assignedOn)
    			,calledNumber			= ifnull(p_calledNumber,calledNumber)
    			,waitDuration 			= ifnull(p_waitDuration,waitDuration)
    			,recordingTypeId 		= ifnull(p_recordingTypeId,recordingTypeId)
    			,CustomerId 			= ifnull(p_CustomerId,CustomerId)
    			,voicemailUrl 			= ifnull(p_voicemailUrl,voicemailUrl)
    			,callDuration			= ifnull(p_callDuration,callDuration) 			
				,callCost				= ifnull(p_callCost,callCost)
				,businessStartTime   	= ifnull(p_businessStartTime,businessStartTime)
				,businessEndTime   		= ifnull(p_businessEndTime,businessEndTime)
				,IsAbandoned			= ifnull(p_IsAbandoned,IsAbandoned)
    			,updatedAt 				= v_curDate
   			WHERE CallHistoryId 		= v_CallHistoryId;
    
			IF p_QueueId IS NOT NULL 
   			THEN
   				UPDATE 	tb_CallDurationHistory b 
				SET 	b.QueueId 				= ifnull(p_QueueId,b.QueueId)
    			WHERE 	b.CallHistoryId 		= v_CallHistoryId 
                AND 	AgentId IS NULL 
                AND 	IsBot	= 0;	
			END IF;
                  SET v_AgentId = NULL;        
   			IF v_AgentId IS NOT NULL 
			THEN
   				
   				IF EXISTS(SELECT 1 FROM tb_CallDurationHistory WHERE CallHistoryId = v_CallHistoryId AND AgentId IS NULL AND IsBot = 0 LIMIT 1) 
				then
   					UPDATE tb_CallDurationHistory b 
   					SET  b.StartTime 			= ifnull(p_StartTime,b.StartTime)
   						,b.EndTime 				= ifnull(p_EndTime,b.EndTime)
   						,b.Duration 			= ifnull(p_Duration,b.Duration)
   						,b.AgentHoldDuration 	= ifnull(p_AgentHoldDuration,b.AgentHoldDuration)
   						,b.AgentId 				= ifnull(v_AgentId,b.AgentId)
   						,b.AgentSkillId 		= ifnull(p_AgentSkillId,b.AgentSkillId)
   						,b.IsBot 				= ifnull(p_IsBot,b.IsBot)
   						,b.BotId 				= ifnull(p_BotId,b.BotId)
   						,b.RecordingUrl 		= ifnull(p_RecordingUrl,b.RecordingUrl)
   						,b.transferredTime 		= ifnull(p_transferredTime,b.transferredTime)
   						,b.recordingDuration 	= ifnull(p_recordingDuration,b.recordingDuration)
   						,b.dialDuration 		= ifnull(p_dialDuration,b.dialDuration)
   						,b.transferredTypeId 	= ifnull(p_transferredTypeId,b.transferredTypeId)
   						,b.QueueId 				= ifnull(p_QueueId,b.QueueId)
   						,b.dispositionId		= IFNULL(p_dispositionId,b.dispositionId)
   						,b.UMNStatus 			= IFNULL(p_UMNStatus,b.UMNStatus)
   						,b.transferedBy 		= IFNULL(v_transferedBy,b.transferedBy)
   						,b.transferedTo 		= IFNULL(v_transferedTo,b.transferedTo)   
  						,ticketId 				= ifnull(p_ticketId,ticketId)
 						,IsMissedCall			= ifnull(p_IsMissedCall,IsMissedCall)
   						,b.updatedAt 			= v_curDate
 				   WHERE 	b.CallHistoryId 	= v_CallHistoryId 
                   AND 		AgentId IS NULL 
                   AND 		IsBot				= 0;			
   				
   				ELSEIF EXISTS(SELECT 1 FROM tb_CallDurationHistory WHERE CallHistoryId = v_CallHistoryId AND AgentId = v_AgentId LIMIT 1) 
                   then
   					update tb_CallDurationHistory b 
   					set  b.StartTime 		= ifnull(p_StartTime,b.StartTime)
   						,b.EndTime 				= ifnull(p_EndTime,b.EndTime)
   						,b.Duration 			= ifnull(p_Duration,b.Duration)
   						,b.AgentHoldDuration 	= ifnull(p_AgentHoldDuration,b.AgentHoldDuration)					
   						,b.AgentSkillId 		= ifnull(p_AgentSkillId,b.AgentSkillId)
   						,b.IsBot 				= ifnull(p_IsBot,b.IsBot)
   						,b.BotId 				= ifnull(p_BotId,b.BotId)
   						,b.RecordingUrl 		= ifnull(p_RecordingUrl,b.RecordingUrl)
   						,b.transferredTime 		= ifnull(p_transferredTime,b.transferredTime)
   						,b.recordingDuration 	= ifnull(p_recordingDuration,b.recordingDuration)
   						,b.dialDuration 		= ifnull(p_dialDuration,b.dialDuration)
   						,b.transferredTypeId 	= ifnull(p_transferredTypeId,b.transferredTypeId)
   						,b.QueueId 				= ifnull(p_QueueId,b.QueueId)
   						,b.dispositionId		= IFNULL(p_dispositionId,b.dispositionId)
   						,b.UMNStatus 			= IFNULL(p_UMNStatus,b.UMNStatus)
   						,b.transferedBy 		= IFNULL(v_transferedBy,b.transferedBy)
   						,b.transferedTo 		= IFNULL(v_transferedTo,b.transferedTo)
 						,b.ticketId 			= ifnull(p_ticketId,ticketId)
 						,b.IsMissedCall			= ifnull(p_IsMissedCall,b.IsMissedCall)
   						,b.updatedAt 			= v_curDate
   					where 	b.CallHistoryId = v_CallHistoryId 
   					and 		b.AgentId 		= v_AgentId;								
   				
   				else
   					insert into tb_CallDurationHistory
   					(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime
   					,recordingDuration,QueueId,createdAt,dialDuration,transferredTypeId,dispositionId,UMNStatus,transferedBy 
   					,transferedTo,ticketId,IsMissedCall,updatedAt)
   					values(v_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,v_AgentId,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime
   					,p_recordingDuration,p_QueueId,v_curDate,p_dialDuration,p_transferredTypeId,p_dispositionId,p_UMNStatus,v_transferedBy
   					,v_transferedTo,p_ticketId,p_IsMissedCall,v_curDate);
   				End if; 
   			End if;	
            
			IF v_AgentId IS NULL 
			THEN
				SELECT 	AgentId, IsBot
                INTO 	v_AgentId, v_IsBot                
                FROM 	tb_CallDurationHistory 
                WHERE 	CallHistoryId = v_CallHistoryId                 
                ORDER BY CallDurationHistoryId DESC 
                LIMIT 1;
                
   				IF v_AgentId IS NOT NULL OR v_IsBot = 1 
				THEN
					INSERT INTO tb_CallDurationHistory
   					(CallHistoryId,StartTime,EndTime,Duration,AgentHoldDuration,AgentSkillId,IsBot,BotId,RecordingUrl,transferredTime
   					,recordingDuration,QueueId,createdAt,dialDuration,transferredTypeId,dispositionId,UMNStatus,transferedBy 
   					,transferedTo,ticketId,IsMissedCall,updatedAt)
   					values(v_CallHistoryId,p_StartTime,p_EndTime,p_Duration,p_AgentHoldDuration,p_AgentSkillId,p_IsBot,p_BotId,p_RecordingUrl,p_transferredTime
   					,p_recordingDuration,p_QueueId,v_curDate,p_dialDuration,p_transferredTypeId,p_dispositionId,p_UMNStatus,v_transferedBy
   					,v_transferedTo,p_ticketId,p_IsMissedCall,v_curDate);
                    
                    
					SET v_errcode = 0;
					SET v_errmsg = 'inserted successfully';
					LEAVE sp_exit;
				END IF;	
			END IF; 
   		End if; 
   				
			if found_rows()>0 then
				set v_errcode = 0;
				set v_errmsg = 'updated successfully';
				leave sp_exit;
			end if;	  
   		end sp_exit;       
           
   		select v_errcode as errcode, v_errmsg as errmsg,v_CallHistoryId as CallHistoryId;
                         
   	COMMIT;
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
