CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_create_ecom_purchaseflow_log`(
 p_channelType varchar(20),
 p_storeName varchar(30),
 p_historyId bigint, 
 p_domainId int,
 p_isPurchased tinyint,
 p_productDtl json,
