 )
Begin
  
 	declare v_errcode int default -1;
     declare v_errmsg varchar(30) default 'Failure';
     declare v_uuid varchar(100);
     
     set v_uuid:= uuid();
      
 	insert into ccaas_ecom_purchaseflow_log(channelType,tokenId,storeName,historyId,domainId,isPurchased,productDtl,phoneNumber,errcode,errmsg,createAt,companyNumber)
 	values(p_channelType,v_uuid,p_storeName,p_historyId,p_domainId,p_isPurchased,p_productDtl,p_phoneNumber,p_errcode,p_errmsg,current_timestamp(),p_companyNumber);
      
      if row_count()>0 then
  		set v_errcode = 0;
          set v_errmsg = 'Inserted';
