CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_create_email_config_details`(
     p_EmailConfigId		int,
     emailAddress 			varchar(250),
     aliasName 				varchar(25),
     supervisorName 		varchar(50), 
     emailThreshold 		int,
     isEmail 				int,
     domainId 				int,
     primaryEmail 			int,
     p_isBot				int,
     p_knowledgeBasedId  	int,
     p_autoAssignAgent		tinyint,
     p_serverType			tinyint,
     p_productId			tinyint,
     p_emailtype			tinyint,
     p_domainName 			varchar(250) ,
     p_forwardEmail			varchar(250)
     )
begin
  	DECLARE v_EmailConfigId	INT;
   	declare errcode 		INT default -1;
   	declare errmsg 			VARCHAR(255) default 'Email Configuration Failed';    
   	declare v_eid 			INT;
    declare v_EmailConfig	INT;
   
  	sp_exit : begin 
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT 	EmailConfigId INTO v_EmailConfigId 
  		FROM 	email_config a 
  		WHERE 	a.EmailConfigId = p_EmailConfigId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  		IF v_EmailConfigId IS NULL 
  		THEN
              IF EXISTS (	SELECT 	1
  						FROM 	email_config e_c
  						WHERE 	e_c.domainId		= domainId
  						AND 	e_c.emailAddress 	= emailAddress)
  			THEN
  				SET errcode = -1;
  				SET errmsg = 'Email Address is duplicating';
                  LEAVE sp_exit;
              END IF;
              
  			insert into email_config(emailAddress,aliasName,supervisorName,emailThreshold,isEmail,domainId,createdAt,primaryEmail,isBot,knowledgeBasedId,autoAssignAgent,serverType,product_id,emailtype,domainName,forwardEmail)
  			values (emailAddress,aliasName,supervisorName,emailThreshold,isEmail,domainId,now(3),primaryEmail,p_isBot,p_knowledgeBasedId,p_autoAssignAgent,p_serverType,(case when (p_productId is not null or p_productId <>0) then p_productId else product_id end),p_emailtype,p_domainName,p_forwardEmail);
			
  				if row_count()>0 then
  					set errcode = 0;
  					   set errmsg = 'inserted successfully';
  					   leave sp_exit;
  				end if;	
                
			SET v_EmailConfig = last_insert_id();
            
  		ELSE
  			IF EXISTS(	SELECT 	1
  						FROM 	email_config e_c
  						WHERE 	e_c.domainId		= domainId
  						AND 	e_c.emailAddress 	= emailAddress
  						AND 	e_c.EmailConfigId	<> v_EmailConfigId)
  			THEN
  				SET errcode = -1;
  				SET errmsg = 'Email Address is duplicating';
  				LEAVE sp_exit;
  			END IF;
  		  
  			update email_config a
  			set 	a.emailAddress		= ifnull(emailAddress,a.emailAddress),
  					a.aliasName			= ifnull(aliasName,a.aliasName),
  					a.supervisorName	= ifnull(supervisorName,a.supervisorName),
  					a.emailThreshold	= ifnull(emailThreshold,a.emailThreshold),
  					a.isEmail			= ifnull(isEmail,a.isEmail),
  					a.domainId			= ifnull(domainId,a.domainId),
  					a.updatedAt			= now(3),
  					a.primaryEmail		= ifnull(primaryEmail,a.primaryEmail),
					a.isBot				= ifnull(p_isBot,a.isBot),
					a.knowledgeBasedId  = ifnull(p_knowledgeBasedId,a.knowledgeBasedId),
					a.autoAssignAgent   = ifnull(p_autoAssignAgent,a.autoAssignAgent),
					a.emailtype   		= ifnull(p_emailtype,a.emailtype),
					a.serverType   		= ifnull(p_serverType,a.serverType),
					a.domainName   		= ifnull(p_domainName,a.domainName),
					a.forwardEmail   	= ifnull(p_forwardEmail,a.forwardEmail)
  			where 	a.EmailConfigId 	= v_EmailConfigId;
  				  
  			if found_rows()>0
  			then
  				set errcode = 0;
  				set errmsg = 'updated successfully';
  				leave sp_exit;
  			end if;		  
  	   
  		end if; 
  	end sp_exit;
      
  	select errcode as errcode,errmsg as errmsg,v_EmailConfig as EmailConfigId;                
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_create_email_config_details_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_create_email_config_details_1`(
  p_EmailConfigId	int,
  emailAddress varchar(50),
  aliasName varchar(25),
  supervisorName varchar(50), 
  emailThreshold int,
  isEmail int,
  domainId int,
  primaryEmail int)
begin
  
	declare errcode int; 
	declare errmsg varchar(255); 
	

  
  
  

    if not exists(select 1 from email_config a where a.EmailConfigId = p_EmailConfigId limit 1) then
  
		insert into email_config(emailAddress,aliasName,supervisorName,emailThreshold,isEmail,domainId,createdAt,primaryEmail)
		values (emailAddress,aliasName,supervisorName,emailThreshold,isEmail,domainId,now(3),primaryEmail);

			IF ROW_COUNT() > 0 THEN
            SET errcode = 0;
            SET errmsg = 'inserted successfully';
        END IF;                    
              
     ELSE
     
		update email_config a
		set 	a.emailAddress		= ifnull(emailAddress,a.emailAddress),
				a.aliasName			= ifnull(aliasName,a.aliasName),
				a.supervisorName	= ifnull(supervisorName,a.supervisorName),
				a.emailThreshold	= ifnull(emailThreshold,a.emailThreshold),
				a.isEmail			= ifnull(isEmail,a.isEmail),
				a.domainId			= ifnull(domainId,a.domainId),
				a.updatedAt			= now(3),
				a.primaryEmail		= ifnull(primaryEmail,a.primaryEmail)
		where a.EmailConfigId 		= p_EmailConfigId;
             
 IF row_count() > 0
      THEN
  		SET errcode 	= 0;
          SET errmsg 	= 'Updated Successfully';
      END IF;
      		  
  	end if;
  	select errcode as errcode,errmsg as errmsg;         
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_create_flow_otp_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_create_flow_otp_dtl`(
		domainId int,
        input VARCHAR(250),
		expiry_time int
        )
Begin
        
           DECLARE verify_code VARCHAR(10);
           DECLARE errcode INT default -1; 
           DECLARE errmsg VARCHAR(250) default '';
        
           sp_exit:
           BEGIN
        
              
        
              SET verify_code = right(FORMAT(RAND(),7),6);
        
              if exists(select * from tb_ccaas_flow_otp_verfication_dtl a  where a.input collate utf8mb4_0900_ai_ci = input and a.domainId = domainId LIMIT 1) then
        		
                 UPDATE tb_ccaas_flow_otp_verfication_dtl a 
                 set a.verify_code = verify_code, a.created_date = now(), a.expiry_time = expiry_time
                 where a.input  collate utf8mb4_0900_ai_ci = input  and a.domainId = domainId;
                 
                 if ROW_COUNT() > 0 then
                    set errcode = 0;
                    set errmsg = 'success';
                    LEAVE sp_exit;
                 end if;
              end if;
              
              if not exists(select * from tb_ccaas_flow_otp_verfication_dtl a where a.input  collate utf8mb4_0900_ai_ci = input and a.domainId = domainId LIMIT 1) then
        		
        			insert into tb_ccaas_flow_otp_verfication_dtl(domainId,input,verify_code,created_date,expiry_time)
        			values(domainId,input,verify_code,now(),expiry_time);
        			
                 if ROW_COUNT() > 0 then
                    set errcode = 0;
                    set errmsg = 'success to generate pin';
                 end if;
              end if;
           END;
      
           select errcode as errcode,errmsg as errmsg, IFNULL(verify_code,0) as verify_code;
        
        End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_create_tpi_token_by_provider` */;
