/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_create_tpi_token_by_provider`(
p_company_id int,
p_user_id int,
p_token varchar(150),
p_provider varchar(100)
)
begin

	declare v_errcode int default -1;
	declare v_errmsg varchar(50) default 'Failure';
    
    sp_exit:begin
		if exists(select 1 from ccaas_tpi_token_by_provider where company_id = p_company_id and user_id = p_user_id and token = p_token limit 1)then
			set v_errcode = -1;
            set v_errmsg = 'Token already exists';
			leave sp_exit;
        end if;
        
        insert into ccaas_tpi_token_by_provider(company_id, user_id, token, provider, createdate)
        values(p_company_id, p_user_id, p_token, p_provider, current_timestamp);
        
		set v_errcode = 0;
		set v_errmsg = 'Inserted';
        
    End;
    
	select v_errcode as errcode, v_errmsg as errmsg;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
