DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_create_videomeet_session_history_details`(
          
		p_sessionId 						varchar(500)
 		,p_sessionStartTime 				bigint 
 		,p_sessionEndTime 					bigint 
 		,p_customerNumber 					varchar(20) 
 		,p_domainId 						int 
 		,p_IsInBound 						tinyint 
 		,p_dialDuration 					bigint 
 		,p_disconnectedBy 					bigint 
 		,p_queueDuration 					bigint 
 		,p_calledNumber 					bigint 
 		,p_waitDuration 					bigint 
 		,p_recordingTypeId 					int 
 		,p_CustomerId 						int 
 		,p_videoDuration 					bigint 
 		,p_IsAbandoned 						tinyint 
 		,p_businessStartTime 				bigint 
 		,p_businessEndTime 					bigint
 		,p_meetingId						text
         
 		,p_AgentId 							bigint 
 		,p_QueueId 							int 
 		,p_dispositionId 					int 
                 
              )
Begin              
  			DECLARE v_errcode 					int default -1;
  			DECLARE v_errmsg 					varchar(55) default 'Video inserted failed';
  			DECLARE v_VideoHistory 				bigint;
  			DECLARE v_VideoDurationHistoryId 	bigint;
  			DECLARE v_curDate					datetime;
  			DECLARE v_UserID					int;
  			DECLARE v_VideoHistoryId			int;
 		    
             SET v_curDate = NOW();
               
                 sp_exit : begin
             		if p_domainId is null or p_domainId = 0 then
             			set v_errcode = -1;
             			set v_errmsg = 'DomainId should not be empty';
             			leave sp_exit;
             		End if;
 
 				select UserID into v_UserID 
                 from tb_User 
                 where domainId = p_domainId
                 and ext = p_AgentId;
 	 
 				SELECT 	VideoHistoryId INTO v_VideoHistoryId
 				FROM 	tb_VideoHistory
 				WHERE	sessionId	= p_sessionId;
           
                 IF v_VideoHistoryId IS NOT NULL 
 					THEN
              			UPDATE tb_VideoHistory 
              			SET 
              			sessionStartTime		=IFNULL(p_sessionStartTime,sessionStartTime)
 						,sessionEndTime			=IFNULL(p_sessionEndTime,sessionEndTime)
 						,customerNumber			=IFNULL(p_customerNumber,customerNumber)
 						,domainId				=IFNULL(p_domainId,domainId)
 						,IsInBound				=IFNULL(p_IsInBound,IsInBound)
 						,dialDuration			=IFNULL(p_dialDuration,dialDuration)
 						,disconnectedBy			=IFNULL(p_disconnectedBy,disconnectedBy)
 						,queueDuration			=IFNULL(p_queueDuration,queueDuration)
 						,calledNumber			=IFNULL(p_calledNumber,calledNumber)
 						,waitDuration			=IFNULL(p_waitDuration,waitDuration)
 						,recordingTypeId		=IFNULL(p_recordingTypeId,recordingTypeId)
 						,CustomerId				=IFNULL(p_CustomerId,CustomerId)
 						,videoDuration			=IFNULL(p_videoDuration,videoDuration)
 						,IsAbandoned			=IFNULL(p_IsAbandoned,IsAbandoned)
                         ,updatedAt				= v_curDate
             			where VideoHistoryId 	= v_VideoHistoryId;
                         
 				update tb_VideoDurationHistory  
 				set AgentId							= v_UserID
 					,QueueId						=IFNULL(p_QueueId,QueueId)
 					,dispositionId					=IFNULL(IF(p_dispositionId=0,dispositionId,p_dispositionId),dispositionId)
 					,updatedAt						= v_curDate
                     where VideoHistoryId 	= v_VideoHistoryId;
                     
                     if row_count() > 0 then
 					set v_errcode = 0;
 					set v_errmsg = 'Video updated successfully';
 				end if;
                 
 			ELSE
                 
 				insert into tb_VideoHistory(sessionId,sessionStartTime ,sessionEndTime,customerNumber,domainId,IsInBound,dialDuration,disconnectedBy,queueDuration,calledNumber
 				,waitDuration,recordingTypeId,CustomerId,videoDuration,IsAbandoned,businessStartTime,businessEndTime,meetingId,createdAt,updatedAt )
 				values(p_sessionId,p_sessionStartTime ,p_sessionEndTime,p_customerNumber,p_domainId,p_IsInBound,p_dialDuration,p_disconnectedBy,p_queueDuration,p_calledNumber
 				,p_waitDuration,p_recordingTypeId,p_CustomerId,p_videoDuration,p_IsAbandoned,p_businessStartTime,p_businessEndTime,p_meetingId,v_curDate,v_curDate);
               				   
 				set v_VideoHistory = last_insert_id();       
 
 				insert into tb_VideoDurationHistory (VideoHistoryId,AgentId,QueueId,dispositionId,createdAt,updatedAt)
 				values (v_VideoHistory,v_UserID,p_QueueId,p_dispositionId,v_curDate,v_curDate);
                  
 				if row_count() > 0 then
 					set v_errcode = 0;
 					set v_errmsg = 'Video inserted successfully';
 					leave sp_exit;
 				end if;
 		end if;
 	end;	
    				SELECT v_errcode as errcode, v_errmsg as errmsg;
 	End ;;
DELIMITER ;
