CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_create_videomeet_session_history_details_logic`(
    p_sessionId              VARCHAR(500),
    p_sessionStartTime        BIGINT, 
    p_sessionEndTime          BIGINT, 
    p_customerNumber          VARCHAR(20), 
    p_domainId                INT, 
    p_IsInBound               TINYINT, 
    p_dialDuration            BIGINT, 
    p_disconnectedBy          BIGINT, 
    p_queueDuration           BIGINT, 
    p_calledNumber            BIGINT, 
    p_waitDuration            BIGINT, 
    p_recordingTypeId         INT, 
    p_CustomerId              INT, 
    p_videoDuration           BIGINT, 
    p_IsAbandoned             TINYINT, 
    p_businessStartTime       BIGINT, 
    p_businessEndTime         BIGINT,
    p_meetingId               TEXT,
    p_AgentId                 BIGINT, 
    p_QueueId                 INT, 
    p_dispositionId           INT,
    p_UMNStatus               INT,
    p_StartTime               BIGINT,
    p_EndTime                 BIGINT,
    p_agentDuration           BIGINT,
	p_transferredTime			BIGINT,
    p_IsMissedCall				TINYINT,
    p_transferedBy				INT,
    p_transferedTo				INT
)
BEGIN
    DECLARE v_errcode              INT DEFAULT -1;
    DECLARE v_errmsg               VARCHAR(55) DEFAULT 'Video inserted failed';
    DECLARE v_VideoHistoryId       BIGINT;
    DECLARE v_LastAgentId          BIGINT;
    DECLARE v_LastUMNStatus        INT;   
    DECLARE v_LastVideoDurationHistoryId BIGINT;
    DECLARE v_AgentId              BIGINT;
    DECLARE v_curDate              DATETIME DEFAULT NOW();
    DECLARE v_transferedBy			BIGINT;
	DECLARE v_transferedTo 			BIGINT;
    DECLARE v_SourceVideoDurationHistoryId	BIGINT;
    DECLARE v_VideoDurationHistoryId	INT;
    DECLARE v_VideoLastDurationHistoryId	INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET v_errcode = -1;
        SET v_errmsg = 'Transaction failed';
    END;

    START TRANSACTION;

    sp_exit: BEGIN

		DROP TEMPORARY TABLE IF EXISTS temp_User;
		CREATE TEMPORARY TABLE temp_User    
		select 	UserID 
		,		ext     
		from 	tb_User 
		where 	ext 		IN  (p_AgentId,p_transferedBy,p_transferedTo)
		and 	domainId 	= p_domainId;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

		SELECT 	UserID INTO v_transferedTo 	FROM temp_User WHERE ext = p_transferedTo;
		SELECT 	UserID INTO v_transferedBy 	FROM temp_User WHERE ext = p_transferedBy;
		SELECT 	UserID INTO v_AgentId 		FROM temp_User WHERE ext = p_AgentId;

        IF p_domainId IS NULL OR p_domainId = 0 THEN
            SET v_errcode = -1;
            SET v_errmsg = 'DomainId should not be empty';
            ROLLBACK;
            LEAVE sp_exit;
        END IF;

        SELECT VideoHistoryId INTO v_VideoHistoryId
        FROM tb_VideoHistory
        WHERE meetingId = p_meetingId
        LIMIT 1;
	
        IF v_VideoHistoryId IS NOT NULL THEN
            SELECT AgentId, UMNStatus, VideoDurationHistoryId INTO v_LastAgentId, v_LastUMNStatus, v_LastVideoDurationHistoryId
            FROM tb_VideoDurationHistory
            WHERE VideoHistoryId = v_VideoHistoryId
            ORDER BY VideoDurationHistoryId DESC
            LIMIT 1;

            UPDATE tb_VideoHistory
            SET 
                sessionStartTime = IFNULL(p_sessionStartTime, sessionStartTime),
                sessionEndTime = IFNULL(p_sessionEndTime, sessionEndTime),
                customerNumber = IFNULL(p_customerNumber, customerNumber),
                domainId = IFNULL(p_domainId, domainId),
                IsInBound = IFNULL(p_IsInBound, IsInBound),
                dialDuration = IFNULL(p_dialDuration, dialDuration),
                disconnectedBy = IFNULL(p_disconnectedBy, disconnectedBy),
                queueDuration = IFNULL(p_queueDuration, queueDuration),
                calledNumber = IFNULL(p_calledNumber, calledNumber),
                waitDuration = IFNULL(p_waitDuration, waitDuration),
                recordingTypeId = IFNULL(p_recordingTypeId, recordingTypeId),
                CustomerId = IFNULL(p_CustomerId, CustomerId),
                videoDuration = IFNULL(p_videoDuration, videoDuration),
                IsAbandoned = IFNULL(p_IsAbandoned, IsAbandoned),
                updatedAt = v_curDate
            WHERE VideoHistoryId = v_VideoHistoryId;

            IF v_AgentId IS NOT NULL 
            THEN
                IF EXISTS(SELECT 1 FROM tb_VideoDurationHistory WHERE VideoHistoryId = v_VideoHistoryId AND AgentId IS NULL LIMIT 1) THEN
                    UPDATE tb_VideoDurationHistory
                    SET
                        StartTime 			= IFNULL(p_StartTime, StartTime),
                        EndTime 			= IFNULL(p_EndTime, EndTime),
                        agentDuration 		= IFNULL(p_agentDuration, agentDuration),
                        AgentId 			= IFNULL(v_AgentId, AgentId),
                        QueueId 			= IFNULL(p_QueueId, QueueId),
                        dispositionId 		= IFNULL(p_dispositionId, dispositionId),
                        UMNStatus 			= IFNULL(p_UMNStatus, UMNStatus),
                        transferredTime 	= IFNULL(p_transferredTime,transferredTime),
                        IsMissedCall		= IFNULL(p_IsMissedCall,IsMissedCall),
                        dialDuration 		= ifnull(p_dialDuration,dialDuration),
                        transferedBy 		= IFNULL(v_transferedBy,transferedBy),
                        transferedTo 		= IFNULL(v_transferedTo,transferedTo),
                        updatedAt = v_curDate
                    WHERE VideoHistoryId = v_VideoHistoryId AND AgentId IS NULL;
                                        
                ELSEIF (p_UMNStatus IN (3, 4) OR IFNULL(v_LastAgentId, 0) <> v_AgentId OR v_LastUMNStatus IN (3, 4)) 
                THEN
                    INSERT INTO tb_VideoDurationHistory ( VideoHistoryId, StartTime, EndTime, agentDuration, AgentId,QueueId, dispositionId, UMNStatus, updatedAt,transferredTime,IsMissedCall,transferedBy,transferedTo,dialDuration) 
                    VALUES(v_VideoHistoryId, p_StartTime, p_EndTime, p_agentDuration, v_AgentId, p_QueueId, p_dispositionId, p_UMNStatus, v_curDate,p_transferredTime,p_IsMissedCall,v_transferedBy,v_transferedTo,p_dialDuration);
                    
                     SET v_VideoLastDurationHistoryId = last_insert_id();	
                                
                ELSE
                    UPDATE tb_VideoDurationHistory
                    SET
                        StartTime	 		= IFNULL(p_StartTime, StartTime),
                        EndTime 			= IF(p_EndTime = 0, EndTime, p_EndTime),
                        agentDuration 		= IFNULL(p_agentDuration, agentDuration),
                        AgentId 			= IFNULL(v_AgentId, AgentId),
                        QueueId 			= IFNULL(p_QueueId, QueueId),
                        dispositionId 		= IF(p_dispositionId = 0, dispositionId, p_dispositionId),
                        UMNStatus 			= IFNULL(p_UMNStatus, UMNStatus),
                        transferredTime 	= IF(p_transferredTime = 0, transferredTime, p_transferredTime),
                        IsMissedCall		= IFNULL(p_IsMissedCall,IsMissedCall),
                        dialDuration 		= ifnull(p_dialDuration,dialDuration),
                        transferedBy 		= IFNULL(v_transferedBy,transferedBy),
                        transferedTo 		= IFNULL(v_transferedTo,transferedTo),
                        updatedAt = v_curDate
                    WHERE VideoDurationHistoryId = v_LastVideoDurationHistoryId;
                    
                END IF;
            END IF;
            
			if found_rows()>0 then
				set v_errcode = 0;
				set v_errmsg = 'updated successfully';
				leave sp_exit;
			end if;
        ELSE
            INSERT INTO tb_VideoHistory (
                sessionId, sessionStartTime, sessionEndTime, customerNumber, domainId, IsInBound, dialDuration, disconnectedBy, 
                queueDuration, calledNumber, waitDuration, recordingTypeId, CustomerId, videoDuration, IsAbandoned, 
                businessStartTime, businessEndTime, meetingId, createdAt, updatedAt
            ) VALUES (
                p_sessionId, p_sessionStartTime, p_sessionEndTime, p_customerNumber, p_domainId, p_IsInBound, p_dialDuration, 
                p_disconnectedBy, p_queueDuration, p_calledNumber, p_waitDuration, p_recordingTypeId, p_CustomerId, 
                p_videoDuration, p_IsAbandoned, p_businessStartTime, p_businessEndTime, p_meetingId, v_curDate, v_curDate
            );

            SET v_VideoHistoryId = LAST_INSERT_ID();

            INSERT INTO tb_VideoDurationHistory (VideoHistoryId, StartTime, EndTime, agentDuration, AgentId, QueueId, dispositionId, UMNStatus, createdAt, updatedAt,transferredTime,IsMissedCall,transferedBy,transferedTo,dialDuration)
            VALUES (v_VideoHistoryId, p_StartTime, p_EndTime, p_agentDuration, v_AgentId, p_QueueId, p_dispositionId, p_UMNStatus, v_curDate, v_curDate,p_transferredTime,p_IsMissedCall,v_transferedBy,v_transferedTo,p_dialDuration);
            
             SET v_VideoDurationHistoryId = last_insert_id();
             
        END IF;

		if row_count() > 0 then
			set v_errcode = 0;
			set v_errmsg = 'inserted successfully';
			leave sp_exit;
		end if;

    END sp_exit;  
    
			IF p_transferedBy IS NOT NULL
    				THEN
    					SELECT 	VideoDurationHistoryId INTO v_SourceVideoDurationHistoryId		
    					FROM 	tb_VideoDurationHistory
    					WHERE 	VideoHistoryId	= v_VideoHistoryId
    					AND 	AgentId			= p_transferedBy;	
    					
    					IF v_SourceVideoDurationHistoryId IS NOT NULL AND v_VideoDurationHistoryId IS NOT NULL
    					THEN 
    						CALL up_TransaferVideoMessage(v_SourceVideoDurationHistoryId,v_VideoDurationHistoryId);
    					END IF;
    				END IF;

    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

    COMMIT;
END ;;
