CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_crm_create_email_config_details`(
        p_EmailConfigId		int,
        emailAddress 		varchar(250),
        aliasName 			varchar(50),
        supervisorName 		varchar(50), 
        emailThreshold 		int,
        isEmail 			int,
        domainId 			int,
        primaryEmail 		int,
        p_isBot				int,
        p_knowledgeBasedId  VARCHAR(150),
        p_autoAssignAgent	tinyint,
        p_product_id		int,
        p_is_smtp			tinyint,
        p_smtp_json			json,
        p_emailtype			int,
        p_isRepliedEmail	tinyint,
        p_repliedEmail		varchar(250)
        )
begin
     	DECLARE v_EmailConfigId	INT;
      	declare errcode 		INT default -1;
      	declare errmsg 			VARCHAR(255) default 'Email Configuration Failed';    
      	declare v_eid 			INT;
      
     	sp_exit : begin 
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		SELECT 	EmailConfigId INTO v_EmailConfigId 
     		FROM 	email_config a 
     		WHERE 	a.EmailConfigId = p_EmailConfigId and product_id = p_product_id;
      
     		IF v_EmailConfigId IS NULL 
     		THEN
                 IF EXISTS (	SELECT 	1
     						FROM 	email_config e_c
     						WHERE 	e_c.domainId		= domainId
     						AND 	e_c.emailAddress 	= emailAddress)
     			THEN
     				SET errcode = -1;
     				SET errmsg = 'Email Address is duplicating';
                     LEAVE sp_exit;
                 END IF;
                 
     			insert into email_config(emailAddress,aliasName,supervisorName,emailThreshold,isEmail,domainId,createdAt,primaryEmail,isBot,knowledgeBasedId,autoAssignAgent,is_smtp,smtp_json,product_id,emailtype)
     			values (emailAddress,aliasName,supervisorName,emailThreshold,isEmail,domainId,now(3),primaryEmail,p_isBot,p_knowledgeBasedId,1,p_is_smtp,p_smtp_json,p_product_id,p_emailtype);
         
         
     				if row_count()>0 then
     					set errcode = 0;
     					   set errmsg = 'inserted successfully';
     					   leave sp_exit;
     				end if;		
     		ELSE
     			IF EXISTS(	SELECT 	1
     						FROM 	email_config e_c
     						WHERE 	e_c.domainId		= domainId
     						AND 	e_c.emailAddress 	= emailAddress
     						AND 	e_c.EmailConfigId	<> v_EmailConfigId)
     			THEN
     				SET errcode = -1;
     				SET errmsg = 'Email Address is duplicating';
     				LEAVE sp_exit;
                   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     			END IF;
     		  
 				update email_config a
 				set 	a.emailAddress		= ifnull(emailAddress,a.emailAddress),
 						a.aliasName			= ifnull(aliasName,a.aliasName),
 						a.supervisorName	= ifnull(supervisorName,a.supervisorName),
 						a.emailThreshold	= ifnull(emailThreshold,a.emailThreshold),
 						a.isEmail			= ifnull(isEmail,a.isEmail),
 						a.domainId			= ifnull(domainId,a.domainId),
 						a.updatedAt			= now(3),
 						a.primaryEmail		= ifnull(primaryEmail,a.primaryEmail),
 						a.isBot				= ifnull(p_isBot,a.isBot),
 						a.knowledgeBasedId  = ifnull(p_knowledgeBasedId,a.knowledgeBasedId),
 						a.autoAssignAgent   = ifnull(p_autoAssignAgent,a.autoAssignAgent),
 						a.is_smtp			= ifnull(p_is_smtp,a.is_smtp),
 						a.smtp_json			= ifnull(p_smtp_json,a.smtp_json),
 						a.product_id		= ifnull(p_product_id,a.product_id),
 						a.emailtype		 	= ifnull(p_emailtype,a.emailtype),
 						a.isRepliedEmail	= ifnull(p_isRepliedEmail,a.isRepliedEmail),
 						a.repliedEmail		= ifnull(p_repliedEmail,a.repliedEmail)
 				where 	a.EmailConfigId 	= v_EmailConfigId;
     				  
     			if found_rows()>0
     			then
     				set errcode = 0;
     				set errmsg = 'updated successfully';
     				leave sp_exit;
     			end if;		  
     	   
     		end if; 
     	end sp_exit;
         
     	select errcode as errcode,errmsg as errmsg;                
     end ;;
DELIMITER ;
