CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_deleteCustomerContact`(
	p_coid 		INT,
	p_domainId 	INT
)
begin
	
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(150) DEFAULT 'Delete failed';
    DECLARE v_coid INT;

	SELECT coid INTO v_coid
    FROM customer_contact
    WHERE coid = p_coid AND domainId = p_domainId;

	IF v_coid IS NOT NULL 
    THEN
    
		INSERT INTO tb_customer_contact_deleted_log(deleted_coid,firstName,lastName,primaryPhoneNumber,phoneNumber,primaryEmail,email,accountNumber
		,tags,location,address,country,state,city,postalCode,facebook,instagram,whatsapp,twitter,createdAt,updatedAt,voiceBiometric,domainId,mergeCustomer
		,blockCustomer,doNotDisturb,blockCustomerReq,doNotDisturbReq,type,currentCustomerNumber,customerType,Timezone,blockedBy,doNotDisturbBy
		,blockedReqBy,doNotDisturbReqBy,Reason,cookiesId,Source,attachments,CustomerUniqueId,is_deleted_date)
		SELECT coid,firstName,lastName,primaryPhoneNumber,phoneNumber,primaryEmail,email,accountNumber
		,tags,location,address,country,state,city,postalCode,facebook,instagram,whatsapp,twitter,createdAt,updatedAt,voiceBiometric,domainId,mergeCustomer
		,blockCustomer,doNotDisturb,blockCustomerReq,doNotDisturbReq,type,currentCustomerNumber,customerType,Timezone,blockedBy,doNotDisturbBy
		,blockedReqBy,doNotDisturbReqBy,Reason,cookiesId,Source,attachments,CustomerUniqueId,unix_timestamp(current_timestamp())*1000
        FROM customer_contact
		WHERE coid = v_coid;

		DELETE FROM customer_contact WHERE coid = v_coid;
        
        SET v_errcode = 0;
        SET v_errmsg = 'coid deleted successfully';
        
	END IF;
		SELECT v_errcode AS errcode,v_errmsg AS errmsg;
end ;;
