CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_DeleteScraper`( 
      p_web_id    INT
  )
BEGIN
      DECLARE v_web_id   INT;
      DECLARE v_ErrCode  INT;
      DECLARE v_ErrMsg   VARCHAR(250);
  
      SP_Logic: BEGIN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		SELECT web_id INTO v_web_id
		FROM websiteScraper
		WHERE web_id = p_web_id;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
        
          IF v_web_id IS NULL THEN
              SET v_ErrCode = -1;
              SET v_ErrMsg = 'Not Found: Deleted';
              LEAVE SP_Logic;
          END IF;
  
		IF EXISTS (	SELECT 	1 
					FROM 	websiteScraper					AS WS
					JOIN  	chat_configuration_primary_form	AS PF 	ON  WS.domainId 	= PF.domainId
																	AND PF.websiteId	LIKE CONCAT('%',WS.websiteId,'%')
					WHERE 	WS.web_id = p_web_id AND PF.isDeleted = 0) 
                    OR      (	SELECT 	1 
					FROM 	websiteScraper					AS WS
					JOIN  	tb_WhatsappConfiguration		AS PF 	ON  WS.domainId 	= PF.domainId
																	AND PF.knowledgeBaseId	LIKE CONCAT('%',WS.websiteId,'%')
					WHERE 	WS.web_id = p_web_id)
                    OR (	SELECT 	1 
					FROM 	websiteScraper					AS WS
					JOIN  	tb_FacebookConfiguration		AS PF 	ON  WS.domainId 	= PF.domainId
																	AND PF.knowledgeBaseId	LIKE CONCAT('%',WS.websiteId,'%')
					WHERE 	WS.web_id = p_web_id)
                    OR (	SELECT 	1 
					FROM 	websiteScraper					AS WS
					JOIN  	tb_InstagramConfiguration		AS PF 	ON  WS.domainId 	= PF.domainId
																	AND PF.knowledgeBaseId	LIKE CONCAT('%',WS.websiteId,'%')
					WHERE 	WS.web_id = p_web_id)
		THEN
			SET v_ErrCode = -2;
			SET v_ErrMsg = 'WebId is in use,it cannot be deleted';
			LEAVE SP_Logic;
        END IF;
          
          DELETE FROM tb_ChatArticle WHERE web_id = v_web_id;
          DELETE FROM tb_ChatCategory WHERE web_id = v_web_id;
          DELETE FROM websiteScraper WHERE web_id = v_web_id;
  
          SET v_ErrCode = 0;
          SET v_ErrMsg = 'Deleted Successfully';
  
      END SP_Logic;
      
      SELECT v_ErrCode as errCode, v_ErrMsg as errMsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
