CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_deleteUser`(
  p_domainId 	 INT
  ,p_ext		 VARCHAR(100)
)
BEGIN
		DECLARE v_errcode 		INT DEFAULT 1;
		DECLARE v_errmsg 		VARCHAR(50) DEFAULT 'No:Delete';
        DECLARE v_initial_count INT;
        DECLARE v_table_count 	INT;

		call Split(p_ext,','); drop temporary table if exists tt_ext; create temporary table tt_ext (id int auto_increment primary key,exts int,domainId int,userId int);
		insert into tt_ext(exts,domainId) select items,p_domainId from tt_Split_temptable;
		
        set v_initial_count = 1;
        
        select count(*) into v_table_count from tt_ext;
		
        while v_table_count >= v_initial_count
        do
			update tt_ext e
            join tb_User u on e.exts = u.ext and e.domainId = u.domainId
            set e.userId = u.UserID
            where e.id = v_initial_count;
            
            set v_initial_count = v_initial_count + 1;
		end while; 
		        
        DELETE FROM skillMapping WHERE usid in (select userId from tt_ext) AND domainId = p_domainId;
        
		DELETE FROM tb_User WHERE ext in (select exts from tt_ext) AND domainId = p_domainId;

		IF ROW_COUNT() > 0 
        THEN
			SET v_errcode = 0;
			SET v_errmsg = 'Deleted: Success';
		END IF;

		SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
