CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_delete_conversation_triggers`(
p_triggerid int,
p_domainId int
)
Begin
	declare v_errcode int;
    declare v_errmsg varchar(50);
    declare v_triggerid int;
    
     select id into v_triggerid 
     from ccaas_conversation_triggers 
     where id = p_triggerid
     and domainId = p_domainId;
     
	if v_triggerid is not null 
    then
		delete from ccaas_conversation_triggers 
        where id = v_triggerid;
        
		if row_count() > 0 then
			set v_errcode = 0;
			set v_errmsg = 'Deleted';
		End if;
    else
		set v_errcode = 0;
		set v_errmsg = 'Data not found';
    End if;
    
	select v_errcode as errcode, v_errmsg as errmsg;
