   p_domainId int
  )
sp_return:Begin
  	declare v_errcode int;
      declare v_errmsg varchar(40);
      
  	START TRANSACTION;
      
  		if not exists(select 1 from tb_cookie_session_conservation_v2 where (mobileno collate utf8mb4_unicode_ci = p_input or email collate utf8mb4_unicode_ci = p_input or webcookie_id collate utf8mb4_unicode_ci = p_input) limit 1) then
