          End if;
      
  		delete from tb_cookie_session_conservation_v2 where (mobileno collate utf8mb4_unicode_ci = p_input or email collate utf8mb4_unicode_ci = p_input or webcookie_id collate utf8mb4_unicode_ci = p_input) and domainId  = p_domainId ;
          
          if row_count()>0 then
  			set v_errcode = 0;
              set v_errmsg = 'Record deleted';
          End if;
      
      commit;
      select v_errcode as errcode, v_errmsg as errmsg;
  End ;;
