CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_delete_disposition`(	
	p_did			INT 
	,p_domainId		INT 
)
begin
	
		DECLARE v_errcode TINYINT DEFAULT -1;
		DECLARE v_errmsg  VARCHAR(150) DEFAULT 'Disposition status delete fail';	
        DECLARE v_did	  INT;
		
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
			SELECT did INTO v_did
			FROM disposition_status
			WHERE did 			= p_did
			AND domainId 		= p_domainId;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
       IF v_did IS NOT NULL
       THEN
			DELETE FROM disposition_status 
			WHERE did = v_did;
		
			SET v_errcode = 1;
			SET v_errmsg  = 'Disposition status deleted successfully.';
        
		END IF;
    
		SELECT v_errcode AS errcode,v_errmsg AS errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_delete_disposition_status` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
