CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_delete_knowledgeBase`(
	 p_kid			INT
    ,p_categoryId	INT 
    ,p_articleId	VARCHAR(1000) 
)
begin
	
    DECLARE v_errcode TINYINT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(150) DEFAULT 'KnowledgeBase Delete Failed';
    DECLARE v_cid INT;

	SELECT CategoryId INTO v_cid
    FROM tb_KnowledgeBaseCategory
    WHERE fk_kid = p_kid
    AND CategoryId = p_categoryId;
    
    DROP TEMPORARY TABLE IF EXISTS temp_article_details;
    CREATE TEMPORARY TABLE temp_article_details(arid INT);
    
    CALL split(p_articleId,',');
    INSERT INTO temp_article_details(arid)
    SELECT Items FROM tt_Split_temptable; 
    
    IF v_cid IS NOT NULL
    THEN 
		DELETE FROM tb_KnowledgeBaseCategory 
        WHERE CategoryId = v_cid;
        
        DELETE FROM tb_KnowledgeBaseArticleDtl 
        WHERE categoryId = v_cid
        AND fk_kid = p_kid;
        
        SET v_errcode 	= 0;
        SET v_errmsg	= 'KnowledgeBase Category Deleted Succssfully';
     
     ELSE
		DELETE FROM tb_KnowledgeBaseArticleDtl 
        WHERE ArticleId IN (SELECT arid FROM temp_article_details);
        
        SET v_errcode 	= 0;
        SET v_errmsg	= 'KnowledgeBase Article Deleted Succssfully';
	END IF;
		
        SELECT v_errcode AS errcode,v_errmsg AS errmsg;

end ;;
DELIMITER ;
