CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_delete_predictiveDialler_dtl`(
	 p_blastId 	INT
	,p_domainId INT
)
begin
	
    DECLARE v_cid INT;
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'callBlast delete fail';
    
    SELECT 	cid INTO v_cid 
    FROM 	tb_predictiveDialler
    WHERE 	cid = p_blastId
    AND		domainId = p_domainId
    AND		blastStatus = 0;
    
	IF v_cid IS NOT NULL
	THEN
		DELETE FROM tb_predictiveDialler_timeToTrigger_info
        WHERE fk_cid = v_cid;
        
        DELETE FROM tb_predictiveDialler_dailyTrigger_json_dtl
        WHERE fk_cid = v_cid;
        
        DELETE FROM tb_predictiveDialler_dailyTrigger_dtl
        WHERE fk_cid = v_cid;
        
		DELETE FROM tb_predictiveDialler
		WHERE 	cid = v_cid;
        
        SET v_errcode = 0;
        SET v_errmsg = 'callBlast deleted successfully';
	END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
    
end ;;
DELIMITER ;
