CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_delete_Prompt_library`(
p_uuid			INT
,p_domainId		INT
)
BEGIN
	DECLARE v_errCode	TINYINT DEFAULT -1;
    DECLARE v_errMsg	VARCHAR(200) DEFAULT 'Delete Prompt library failed';
    
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN		
		SELECT v_errCode AS errCode, v_errMsg AS errMsg;
		ROLLBACK;
	END;
	START TRANSACTION;	
		DELETE 	FROM prompt_library 
        WHERE 	uuid 		= p_uuid 
        AND 	domainId 	= p_domainId;
        
        SELECT 1 AS errCode, 'Deleted Prompt library successfully' AS errMsg;
    COMMIT;
END ;;
