CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_didNumberEdit`(
    p_pid 				INT,
    p_domainId 			INT,
    p_aliasName 		VARCHAR(40),
    p_outboundSms 		TINYINT,
    p_queueName 		VARCHAR(40),
    p_smsThreshold 		INT,
    p_supervisorName 	VARCHAR(200),
    p_knowledgeBasedId 	VARCHAR(150),
    p_isBot 			TINYINT,
    p_autoAssignAgent 	TINYINT
)
BEGIN
    DECLARE v_updatedAt DATETIME;
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(55) DEFAULT 'Updated : Failed';

    SET v_updatedAt = NOW();

    UPDATE did_purchase
    SET aliasName 			= IFNULL(p_aliasName, aliasName),
        outboundSms 		= IFNULL(p_outboundSms, outboundSms),
        queueName 			= IFNULL(p_queueName, queueName),
        smsThreshold 		= IFNULL(p_smsThreshold, smsThreshold),
        updatedAt 			= v_updatedAt,
        supervisorName 		= IFNULL(p_supervisorName, supervisorName),
        knowledgeBasedId 	= IFNULL(p_knowledgeBasedId, knowledgeBasedId),
        isBot 				= IFNULL(p_isBot, isBot),
        autoAssignAgent		= IFNULL(p_autoAssignAgent,autoAssignAgent)
    WHERE pid = p_pid AND domainId = p_domainId;

    IF ROW_COUNT() > 0 THEN
        SET v_errcode = 0;
        SET v_errmsg = 'Updated successfully';
        
    END IF;

    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
