/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_dyanamic_dashboard_chat`(
	p_domainId			INT
    ,p_start_timestamp	BIGINT
    ,p_end_timestamp	BIGINT
    ,p_start_datetime	DATETIME
    ,p_end_datetime		DATETIME
)
BEGIN
	DECLARE v_new_customers 	INT;
    
	SELECT 	COUNT(1) INTO v_new_customers
    FROM 	customer_contact
    WHERE 	domainId 	= p_domainId
    AND 	createdAt	BETWEEN	p_start_datetime AND p_end_datetime;

	SELECT 	COUNT(1)			AS total_chat
		,	SUM(CASE WHEN DH.answeredDuration BETWEEN  1 AND 30 THEN 1 ELSE 0 END) AS SLA        
        ,	ROUND(sum(queueDuration) / COUNT(1) / 60000)	AS average_Speed_of_Answer
        ,	v_new_customers		AS new_customers
    FROM 	tb_ChatHistory  		H
    JOIN 	tb_ChatDurationHistory 	DH ON H.ChatHistoryId	= DH.ChatHistoryId
	WHERE 	H.domainId		= p_domainId
    AND 	sessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_dyanamic_dashboard_email` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_dyanamic_dashboard_email`(
		p_domainId					INT
		,p_start_timestamp			BIGINT
		,p_end_timestamp			BIGINT
		,p_start_datetime			DATETIME
		,p_end_datetime				DATETIME
)
BEGIN
			
            
            DROP TEMPORARY TABLE IF EXISTS tt_dynamic_email;
            CREATE TEMPORARY TABLE tt_dynamic_email 
            
            SELECT 
					EH.IsInBound,
                    EH.AssignedTo ,
					EC.emailThreshold,
                    D.dispositionName,
                  
                  
                  
                    EH.isOpened,
                 
                    EDH.IsBot,
                    EH.DispositionId,
                    TIMESTAMPDIFF(HOUR, from_unixtime(IFNULL(EH.AssignedOn, EH.SessionStartTime)/1000) , EH.repliedDate) AS replyDuration,
                     CASE WHEN TIMESTAMPDIFF(MINUTE, EH.CreatedAt, NOW()) >= EC.emailThreshold THEN 1 ELSE 0 END				AS	isThresholdTimeExceeded
            FROM tb_EmailHistory  					AS EH
				JOIN tb_EmailDurationHistory 		AS EDH				ON EH.EmailHistoryId = EDH.EmailHistoryId 
                LEFT JOIN email_config				AS EC				ON EC.domainId = EH.DomainId AND EC.emailAddress = EH.ToEmail
                LEFT JOIN disposition_status		AS D				ON D.did = EH.DispositionId		AND D.domainId = EH.DomainId
                WHERE EH.DomainId = p_domainId AND EH.SessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp ;
                
     
                ALTER table tt_dynamic_email ADD COLUMN InteractionWithin30Secs 				INT;
										
            
				UPDATE tt_dynamic_email AS t1 
					SET  InteractionWithin30Secs = CASE WHEN (replyDuration < emailThreshold AND IsInBound = 1 AND dispositionName <> 'Transferred') THEN 1 ELSE 0 END;
            
    
   SELECT 
					 SUM(CASE WHEN IsInBound = 1 				THEN 1 ELSE 0 END) 													AS total_inbound_email
                    ,SUM(CASE WHEN IsInBound = 0				THEN 1 ELSE 0 END) 													AS total_outbound_email
					,SUM(CASE WHEN AssignedTo IS NOT NULL 		THEN 1 ELSE 0 END) 													AS total_email_assigned
					,SUM(CASE WHEN AssignedTo IS NULL AND dispositionId IS NULL AND isBot = 0	THEN 1 ELSE 0 END) 					AS total_email_unassigned
					,IFNULL(SUM(InteractionWithin30Secs)/SUM(IsInBound)*100,0) 														AS service_level 
                    ,SUM(case when isOpened = 1 				THEN 1 ELSE 0 END)													AS opened_email
                    ,SUM( CASE WHEN IFNULL(isThresholdTimeExceeded,0) = 1 and dispositionName IS NULL THEN 1 ELSE 0 END ) 			AS OverDue    	
            FROM tt_dynamic_email;


            
           
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
