/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_dyanamic_dashboard_facebook`(
		p_domainId					INT
		,p_start_timestamp			BIGINT
		,p_end_timestamp			BIGINT
		,p_start_datetime			DATETIME
		,p_end_datetime				DATETIME
)
BEGIN
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
            
            drop temporary table if exists tt_dyanamic_dashboard_facebook_data;
            create temporary table tt_dyanamic_dashboard_facebook_data
				SELECT 
						FacebookHistoryId,
						IsInBound,
                        isCallback,
                        IsMissed,
                        Duration,
                        dialDuration,
                        CASE WHEN IFNULL(dialDuration,0) > 0 THEN 1 ELSE 0 END 					AS InteractionWithin30Secs,
                        CASE WHEN IFNULL(IsInBound,0) = 1 THEN 1 ELSE 0	END						AS inbound
                FROM tb_FacebookHistory WHERE domainId =  p_domainId
					AND sessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp;
            
				
               
                
             SELECT SUM(CASE WHEN IFNULL(IsInBound,0) = 1 THEN 1 ELSE 0 END) 			AS total_inbound,
					SUM(case when IFNULL(isCallback, 0) = 1 THEN 1 ELSE 0 END)  		AS callback_request,
					IFNULL((SUM(InteractionWithin30Secs)/SUM(InBound)) * 100,0) 		AS ServiceLevel, 
                    SUM(Duration)/count(FacebookHistoryId)								AS averageSpeedOfAnswer,
					SUM(CASE WHEN IFNULL(IsMissed, 0)	= 1 THEN 1 ELSE 0 END)			AS missed_chat
             from tt_dyanamic_dashboard_facebook_data;
            
            
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
			
            
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
