CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_dynamic_dashboard_call`(
	p_domainId			INT
    ,p_start_timestamp	BIGINT
    ,p_end_timestamp	BIGINT
    ,p_start_datetime	DATETIME
    ,p_end_datetime		DATETIME
)
BEGIN	
	DECLARE v_queue_length		SMALLINT;
    
    SELECT 	SUM(JSON_LENGTH(queueList, "$"))
    INTO 	v_queue_length
    FROM 	queueWeighTime
    WHERE 	domainId 	= p_domainId
    AND 	queueType	= 'call';
	
	SELECT 	COUNT(1)			AS total_call
		,	SUM(CASE WHEN DH.answeredDuration BETWEEN  1 AND 30 THEN 1 ELSE 0 END) AS SLA        
        ,	ROUND(SUM(queueDuration) / COUNT(1) / 60000)	AS average_Speed_of_Answer
        ,	SUM(CallCost)		AS call_cost
        ,	v_queue_length		AS queue_length
    FROM 	tb_CallHistory  		H
    JOIN 	tb_CallDurationHistory 	DH ON H.CallHistoryId	= DH.CallHistoryId
	WHERE 	H.domainId		= p_domainId
    AND 	H.sessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
