/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_dynamic_dashboard_call_history`( 
 	p_domainId 			INT 	
	,p_start_timestamp	BIGINT
    ,p_end_timestamp	BIGINT
    ,p_start_datetime	DATETIME
    ,p_end_datetime		DATETIME
 	,p_AgentId			INT
 	,p_offset 			INT
 	,p_limit 			INT 	 	
  )
spreturn:BEGIN  
	DECLARE v_CurDate	DATETIME;	
	DECLARE v_offset 	INT;
    DECLARE v_roleid	INT;		

	SET v_CurDate = NOW();
	SET v_offset = p_offset * p_limit;

	DROP TEMPORARY TABLE IF EXISTS temp_userid; CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT, key `temp_userid_UserId`(UserId));
            				   
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT, KEY `idx_temp_AvailableUser_UserId` (`UserId`));    
	INSERT INTO temp_AvailableUser
	(	UserId
	   ,UserName
	   ,roleid
	)
	SELECT  UserID
		,	UserName
		,	roleid
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	roleid		IN (6,5,3);     
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

	SELECT 	roleid 	INTO v_roleid
	FROM 	temp_AvailableUser
	WHERE 	UserId = p_AgentId;

	IF IFNULL(p_AgentId,0) = 0 OR v_roleid in (3,5) 
	THEN
		INSERT INTO temp_userid
		(	UserId )
		SELECT  UserID
		FROM 	temp_AvailableUser;		
	ELSE		
		INSERT INTO temp_userid
		(	UserId )
		SELECT  p_AgentId;
	END IF;
            																		
	DROP TEMPORARY TABLE IF EXISTS temp_History; 
	CREATE TEMPORARY TABLE temp_History 
	(
	id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint				,sessionEndTime bigint					
	,dispositionId int default null				,IsInBound tinyint default null				,dialDuration bigint default null		,disconnectedBy bigint default null			
	,queueDuration bigint default null			,assignedTo bigint default null				,assignedBy bigint default null			,assignedByName varchar(150) 				
    ,assignedOn bigint default null				,Istransferred bigint default null			,markAsRead tinyint default null		,CustomerId int default null				
    ,ticketId bigint default null				,createdAt datetime default null			,updatedAt datetime default null		,calledNumber bigint default null
    ,afterCallWorkTime int default null			,Browser varchar(250) default null			,IPAdress varchar(250) default null		,CallSubject varchar(250) default null		
	,StartTime bigint  default null				,EndTime bigint  default null				,Duration bigint  default null			,AgentId bigint default null				
    ,AgentSkillId bigint  default null			,IsBot int   default null					,BotId int  default null				,transferredTime bigint  default null		
    ,QueueId int  default null			        ,dispositionName varchar(100) default null	,transferredTo bigint default null		,transferred int default null 
	,SentimentalScore float default null		,transferredToName	varchar(150)			,queueName	varchar(255)				,AgentStartTime	bigint	
    ,AgentEndTime	bigint						,transferedBy bigint default null			,CallBackStatus	tinyint					,customerNumber varchar(40)
    ,UMNStatus 		INT DEFAULT NULL			,waitDuration bigint default null			,recordingTypeId int default null		,transferredTypeId int default null
    ,voicemailUrl varchar(500) default null		,callDuration bigint default null			,AgentHoldDuration bigint default null	,RecordingUrl varchar(500) default null
    ,recordingDuration bigint default null		,callBack  	TINYINT default null			,agentRecordingUrl varchar(500) 		,agentDuration			BIGINT
    ,isVMCallBackCompleted	tinyint				,IsMissed 	TINYINT							,IsAbandoned	TINYINT					,IsOutOfBussinessHour 	TINYINT
    ,isOutboundCampaign		TINYINT				,CallHistoryId INT
	); 
        
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;                                   
	INSERT INTO temp_History(CallHistoryId,sessionId,sessionStartTime,sessionEndTime,customerNumber,dispositionId,UMNStatus,IsInBound,dialDuration, 
			disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,transferredTypeId,markAsRead, 
			CustomerId,voicemailUrl,ticketId,callDuration,CallSubject,createdAt,updatedAt,AgentStartTime,AgentEndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
			transferredTime,recordingDuration,QueueId,callBack,SentimentalScore,queueName,transferredTo, 
			agentRecordingUrl,Istransferred,agentDuration,transferedBy,isVMCallBackCompleted,IsMissed,IsAbandoned,IsOutOfBussinessHour,isOutboundCampaign)
	select 	clh.CallHistoryId,clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber, cld.dispositionId, cld.UMNStatus, clh.IsInBound, cld.dialDuration, 
			clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, cld.afterCallWorkTime, clh.recordingTypeId, cld.transferredTypeId, cld.markAsRead, 
			clh.CustomerId AS CustomerId, clh.voicemailUrl, cld.ticketId, IFNULL(cld.Duration,0) + IFNULL((cld.afterCallWorkTime * 1000),0), cld.subject,clh.createdAt, cld.updatedAt, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, cld.AgentSkillId, cld.IsBot, cld.BotId, cld.RecordingUrl, 
			cld.transferredTime, cld.recordingDuration, cld.QueueId,clh.callBack,cld.SentimentalScore,q.name,cld.transferedTo,  
			cld.RecordingUrl, CASE WHEN cld.transferedTo IS NOT NULL THEN 1 ELSE 0 END, (IFNULL(cld.Duration,0) - IFNULL(cld.AgentHoldDuration,0)) agentDuration,
		   cld.transferedBy, clh.isVMCallBackCompleted,cld.IsMissedCall,clh.IsAbandoned,clh.IsOutOfBussinessHour,clh.isOutboundCampaign
	FROM 	tb_CallHistory 				clh
	JOIN 	tb_CallDurationHistory 		cld ON clh.CallHistoryId 	= cld.CallHistoryId  
	LEFT JOIN temp_userid				U	ON cld.AgentId			= U.UserId				
	LEFT JOIN queue						q	ON cld.QueueId			= q.qid
 	WHERE 	clh.domainId 			= p_domainId            					
 	AND		clh.sessionStartTime	BETWEEN p_start_timestamp AND p_end_timestamp
 	AND 	clh.callBack 		NOT IN (1,0,2) 
    AND     (cld.isListen 		<> 1 and  cld.isWhisper <> 1 and cld.isBarge <> 1)
    AND 	((clh.isVMCallBackCompleted = 1  AND clh.voicemailUrl like '%voicemail%') OR (clh.isVMCallBackCompleted = 0  AND (clh.voicemailUrl is null or clh.voicemailUrl = '0')))
 	AND 	((p_AgentId IS NOT NULL AND U.UserId IS NOT NULL) OR (p_AgentId IS NULL))
 	ORDER BY clh.updatedAt DESC LIMIT v_offset, p_limit; 
						  
	UPDATE 	temp_History			t_H
	JOIN 	tb_CallDurationHistory	t_H1 	ON 	t_H.CallHistoryId 	= t_H1.CallHistoryId
											AND t_H.AgentId			= t_H1.transferedTo
	SET 	t_H.queueDuration	= NULL;                          
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;    
    CREATE TEMPORARY TABLE temp_customer_contact
	WITH CTE_Customer AS (
		SELECT 	DISTINCT CustomerId
        FROM 	temp_History
    )	
	SELECT 	CC.coid
			,CC.primaryPhoneNumber
			,CC.firstName
			,CC.lastName      
	FROM 	customer_contact 	CC
    JOIN 	CTE_Customer		C	ON C.CustomerId = CC.coid
	WHERE 	CC.domainId = p_domainId;       
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                                                
								   
	ALTER TABLE temp_History ADD COLUMN CustomerName	VARCHAR(150), ADD COLUMN agentName VARCHAR(150), ADD colorCode VARCHAR(50)
	,ADD COLUMN transferredByName VARCHAR(150);

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; 
	CREATE TEMPORARY TABLE temp_AvailableUser1
	SELECT * FROM temp_AvailableUser;

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser2; 
	CREATE TEMPORARY TABLE temp_AvailableUser2
	SELECT * FROM temp_AvailableUser;
	  
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser3; 
	CREATE TEMPORARY TABLE temp_AvailableUser3
	SELECT * FROM temp_AvailableUser;      

	 DROP TEMPORARY TABLE IF EXISTS tmp_disposition; 
	CREATE TEMPORARY TABLE tmp_disposition
	  SELECT did 
		,	dispositionName
		,	colorCode
	  FROM 	disposition_status
	  WHERE	domainId	= p_domainId;
	  
	  INSERT INTO tmp_disposition
	  SELECT TypeCodeID		AS did
		,	TypeCodeName	AS dispositionName
		,	Null			AS colorCode
	  FROM 	TypeCode 	
	  WHERE TypeGroupID = 1121;	              

	UPDATE 	temp_History		H
	LEFT JOIN 	temp_AvailableUser	AB	ON H.assignedBy			= AB.UserId        
	LEFT JOIN 	temp_AvailableUser1	ATU	ON H.AgentId			= ATU.UserId        
	LEFT JOIN 	temp_AvailableUser2	TU	ON H.transferredTo    	= TU.UserId	
	LEFT JOIN 	temp_AvailableUser3	TL	ON H.transferedBy    	= TL.UserId	
	LEFT JOIN 	tmp_disposition		DS	ON H.dispositionId		= DS.did
	SET 	H.assignedByName	= AB.UserName 
		,	H.dispositionName	= DS.dispositionName
		,	H.colorCode			= DS.colorCode
		,	H.agentName			= ATU.UserName
		,	H.transferredToName	= TU.UserName
		,   H.transferredByName = TL.UserName
		,	H.CustomerId		= IFNULL(H.CustomerId,0); 

	UPDATE 	temp_History		H
	JOIN 	customer_contact	CC 	ON H.CustomerId = CC.coid 
	SET 	H.CustomerName	= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),ifnull(CC.lastName,''));     
    
	UPDATE 	temp_History			H
	JOIN 	temp_customer_contact	CC 	ON H.customerNumber COLLATE utf8mb4_0900_ai_ci = CC.primaryPhoneNumber
	SET 	H.CustomerName	= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),IFNULL(CC.lastName,''))
	WHERE 	H.CustomerId 	= 0; 

	SELECT 	*
	FROM 	temp_History a 	
	ORDER BY updatedAt DESC;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_dynamic_dashboard_chat_history` */;
