CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_dynamic_dashboard_customer_count_month_wise`(
	p_domainId    	INT
	,p_year			SMALLINT
)
BEGIN
	WITH CTE_Month AS (
		SELECT 'Jan' `Month`, CONCAT(p_year,'-01','-01') AS startDate, CONCAT(p_year,'-02','-01') AS endDate
        UNION
        SELECT 'Feb' , CONCAT(p_year,'-02','-01'), CONCAT(p_year,'-03','-01') 
        UNION
        SELECT 'Mar' , CONCAT(p_year,'-03','-01'), CONCAT(p_year,'-04','-01')
		UNION
        SELECT 'Apr' , CONCAT(p_year,'-04','-01'), CONCAT(p_year,'-05','-01')
        UNION
        SELECT 'May' , CONCAT(p_year,'-05','-01'), CONCAT(p_year,'-06','-01')
        UNION
        SELECT 'Jun' , CONCAT(p_year,'-06','-01'), CONCAT(p_year,'-07','-01')
        UNION
        SELECT 'Jul' , CONCAT(p_year,'-07','-01'), CONCAT(p_year,'-08','-01')
        UNION
        SELECT 'Aug' , CONCAT(p_year,'-08','-01'), CONCAT(p_year,'-09','-01')
        UNION
        SELECT 'Sep' , CONCAT(p_year,'-09','-01'), CONCAT(p_year,'-10','-01')
        UNION
        SELECT 'Oct' , CONCAT(p_year,'-10','-01'), CONCAT(p_year,'-11','-01')
        UNION
        SELECT 'Nov' , CONCAT(p_year,'-11','-01'), CONCAT(p_year,'-12','-01')
        UNION
        SELECT 'Dec' , CONCAT(p_year,'-12','-01'), CONCAT((p_year + 1),'-01','-01')        
    )    
    SELECT 	 M.`Month`
		,	SUM(CASE WHEN CC.coid IS NOT NULL THEN 1 ELSE 0 END) AS no_of_customer
    FROM 	CTE_Month			M	
    LEFT JOIN customer_contact 	CC	ON 	CC.createdAt >= M.startDate
									AND	CC.createdAt < M.endDate
	GROUP BY M.`Month`;
END ;;
DELIMITER ;
