CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_dynamic_dashboard_instagram_history`( 
 	p_domainId 			INT 	
	,p_start_timestamp	BIGINT
    ,p_end_timestamp	BIGINT
    ,p_start_datetime	DATETIME
    ,p_end_datetime		DATETIME
 	,p_AgentId			INT
 	,p_offset 			INT
 	,p_limit 			INT 	 	
  )
spreturn:BEGIN  
	DECLARE v_CurDate	DATETIME;	
	DECLARE v_offset 	INT;
    DECLARE v_roleid	INT;		

	SET v_CurDate = NOW();
	SET v_offset = p_offset * p_limit;

	DROP TEMPORARY TABLE IF EXISTS temp_userid; CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT, key `temp_userid_UserId`(UserId));
            				   
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT, KEY `idx_temp_AvailableUser_UserId` (`UserId`));    
	INSERT INTO temp_AvailableUser
	(	UserId
	   ,UserName
	   ,roleid
	)
	SELECT  UserID
		,	UserName
		,	roleid
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	roleid		IN (6,5,3);     
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

	SELECT 	roleid 	INTO v_roleid
	FROM 	temp_AvailableUser
	WHERE 	UserId = p_AgentId;

	IF IFNULL(p_AgentId,0) = 0 OR v_roleid in (3,5) 
	THEN
		INSERT INTO temp_userid
		(	UserId )
		SELECT  UserID
		FROM 	temp_AvailableUser;		
	ELSE		
		INSERT INTO temp_userid
		(	UserId )
		SELECT  p_AgentId;
	END IF;
            																		
	DROP TEMPORARY TABLE IF EXISTS temp_History; 
	CREATE TEMPORARY TABLE temp_History 
	(
		id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber varchar(40)						
		,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
		,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
		,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred bigint default null		,transferredTypeId int default null			,markAsRead tinyint default null
		,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
		,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
		,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
		,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
		,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
		,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
		,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
		,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null						,queueName varchar(150) default null	,assignedByName varchar(150) default null	,dispositionName varchar(100) default null
		,agentStatus varchar(100) default null		,transferredTo bigint default null			,agentRecordingUrl varchar(500) default null	,transferred int default null			,callType varchar(25) default null			
		,SentimentalScore float default null		,transferredToName	varchar(150)			 ,name	varchar(255)							,FacebookHistoryId	bigint				,afterFacebookWorkTime	int					,NextFlowNode	varchar(150)
		,transferredDate	datetime				,dispositionUpdatedBy	bigint				,immediateParentId	bigint						,rootParentId	bigint					,discardedDate	datetime					,repliedDate	datetime					
		,markAsReadSupervisor	tinyint				,markAsReadAgent	tinyint					,customerFacebookId	varchar(100)				,agentFacebookId	varchar(100)		,AgentStartTime	bigint						,AgentEndTime	bigint
		,InstagramHistoryId	bigint					,afterInstagramWorkTime	int					,customerInstagramId	bigint					,agentInstagramId	bigint				,InstagramCommunicationTypeId	int			,isOutboundCampaign	tinyint
		,ChatDurationHistoryId int default null		,DurationHistoryId		bigint				,agentDuration			BIGINT					,CallBackStatus		int					,IsAbandoned tinyint						,IsOutOfBussinessHour tinyint
	   ,transferedBy bigint default null			,isVMCallBackCompleted	tinyint				,IsMissed	tinyint								,meetingId varchar(50)					,recordUrl text								,recordingSessionId text
	); 
        
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	insert into temp_History
	(	sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterInstagramWorkTime,NextFlowNode
		,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
		,markAsReadAgent,IsSessionClosed,customerInstagramId,agentInstagramId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
		,createdAt,updatedAt, channelType,InstagramHistoryId,DurationHistoryId,IsMissed,QueueId,CustomerId)
	select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterInstagramWorkTime,fb.NextFlowNode
		,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
		,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerInstagramId,fb.agentInstagramId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
		,fb.createdAt,fb.updatedAt,'Instagram',fb.InstagramHistoryId,fb.InstagramHistoryId,fb.IsMissed, fb.queueId, fb.CustomerId
	from 	tb_InstagramHistory 	fb	
	LEFT JOIN 	temp_userid			U	ON fb.AgentId			= U.UserId
	where 	fb.domainId 		= p_domainId	
    AND		fb.sessionStartTime	BETWEEN p_start_timestamp AND p_end_timestamp
	AND 	(fb.IsSessionClosed = 1 ) 
	AND 	(IFNULL(p_AgentId,0) = 0 OR (p_AgentId IS NOT NULL AND U.UserId IS NOT NULL))	
	order by fb.updatedAt desc LIMIT v_offset, p_limit;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
						  
	UPDATE 	temp_History			t_H
	JOIN 	tb_CallDurationHistory	t_H1 	ON 	t_H.CallHistoryId 	= t_H1.CallHistoryId
											AND t_H.AgentId			= t_H1.transferedTo
	SET 	t_H.queueDuration	= NULL;                          
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;    
    CREATE TEMPORARY TABLE temp_customer_contact
	WITH CTE_Customer AS (
		SELECT 	DISTINCT CustomerId
        FROM 	temp_History
    )	
	SELECT 	CC.coid
			,CC.primaryPhoneNumber
			,CC.firstName
			,CC.lastName      
	FROM 	customer_contact 	CC
    JOIN 	CTE_Customer		C	ON C.CustomerId = CC.coid
	WHERE 	CC.domainId = p_domainId;       
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                                                
								   
	ALTER TABLE temp_History ADD COLUMN CustomerName	VARCHAR(150), ADD COLUMN agentName VARCHAR(150), ADD colorCode VARCHAR(50)
	,ADD COLUMN transferredByName VARCHAR(150);

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; 
	CREATE TEMPORARY TABLE temp_AvailableUser1
	SELECT * FROM temp_AvailableUser;

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser2; 
	CREATE TEMPORARY TABLE temp_AvailableUser2
	SELECT * FROM temp_AvailableUser;
	  
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser3; 
	CREATE TEMPORARY TABLE temp_AvailableUser3
	SELECT * FROM temp_AvailableUser;      

	 DROP TEMPORARY TABLE IF EXISTS tmp_disposition; 
	CREATE TEMPORARY TABLE tmp_disposition
	  SELECT did 
		,	dispositionName
		,	colorCode
	  FROM 	disposition_status
	  WHERE	domainId	= p_domainId;
	  
	  INSERT INTO tmp_disposition
	  SELECT TypeCodeID		AS did
		,	TypeCodeName	AS dispositionName
		,	Null			AS colorCode
	  FROM 	TypeCode 	
	  WHERE TypeGroupID = 1121;	              

	UPDATE 	temp_History		H
	LEFT JOIN 	temp_AvailableUser	AB	ON H.assignedBy			= AB.UserId        
	LEFT JOIN 	temp_AvailableUser1	ATU	ON H.AgentId			= ATU.UserId        
	LEFT JOIN 	temp_AvailableUser2	TU	ON H.transferredTo    	= TU.UserId	
	LEFT JOIN 	temp_AvailableUser3	TL	ON H.transferedBy    	= TL.UserId	
	LEFT JOIN 	tmp_disposition		DS	ON H.dispositionId		= DS.did
	SET 	H.assignedByName	= AB.UserName 
		,	H.dispositionName	= DS.dispositionName
		,	H.colorCode			= DS.colorCode
		,	H.agentName			= ATU.UserName
		,	H.transferredToName	= TU.UserName
		,   H.transferredByName = TL.UserName
		,	H.CustomerId		= IFNULL(H.CustomerId,0); 

	UPDATE 	temp_History		H
	JOIN 	customer_contact	CC 	ON H.CustomerId = CC.coid 
	SET 	H.CustomerName	= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),ifnull(CC.lastName,''));     
    
	SELECT 	sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterInstagramWorkTime,NextFlowNode
			,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
			,markAsReadAgent,IsSessionClosed,customerInstagramId,agentInstagramId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
			,createdAt,updatedAt, channelType,InstagramHistoryId,DurationHistoryId,IsMissed,QueueId,CustomerId
            ,CustomerName,agentName , colorCode, transferredByName
	FROM 	temp_History a 	
	ORDER BY updatedAt DESC;
 END ;;
DELIMITER ;
