CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_FacebookIsBotUpdate`(
 p_FacebookHistoryId INT
 )
begin
 
 	DECLARE v_errcode INT;
 	DECLARE v_errmsg  VARCHAR(50);
 
 	Update 	tb_FacebookHistory 
 	SET 	IsBot = 1
 	WHERE	FacebookHistoryId = p_FacebookHistoryId;
 
 	IF ROW_COUNT()>0
 	THEN 
 		SET v_errcode = 0 ;
 		SET v_errmsg  = 'Updated Successfully';
 	ELSE
 		SET v_errcode = -1;
 		SET v_errmsg  = 'Not Updated';
 	END IF;
 
 SELECT v_errcode as errcode , v_errmsg as errmsg;
 
 end ;;
DELIMITER ;
