CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_fallback_message`(
 p_domainId 			INT,
 p_uuid				VARCHAR(100),
 p_fallbackMessage	TEXT,
 p_mapId				VARCHAR(255)
 )
begin
 DECLARE errcode int;
 DECLARE errmsg varchar(50);
 
 sp_exit:begin
 
 if exists(select 1 from fallback_message where uuid=p_uuid limit 1)
 then
 	update fallback_message
     set 
 		uuid				= ifnull(p_uuid,uuid),
         fallbackMessage		= ifnull(p_fallbackMessage,fallbackMessage),
 		mapId				= ifnull(p_mapId,mapId)
 	where uuid=p_uuid;
     
       IF ROW_COUNT() > 0 THEN
             SET errcode = 0;
             SET errmsg = 'Updated successfully';
         ELSE
             SET errcode = 1;
             SET errmsg = 'Update failed';
         END IF;
 	else
     
 		insert into fallback_message(uuid,domainId,fallbackMessage,mapId)
         values(p_uuid,p_domainId,p_fallbackMessage,p_mapId);
         
         IF ROW_COUNT() > 0 THEN
             SET errcode = 0;
             SET errmsg = 'Inserted successfully';
         ELSE
             SET errcode = 1;
             SET errmsg = 'Insert failed';
         END IF;
     END IF;
     
     end sp_exit;        
             
        select errcode as errcode, errmsg as errmsg;
               
      End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
