/*!50003 DROP PROCEDURE IF EXISTS `ccaas_flow_otp_validation_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_flow_otp_validation_dtl`(
	domainId int,
	input VARCHAR(250),
	verify_code VARCHAR(10)
)
Begin
       
          DECLARE errcode INT; 
          DECLARE errmsg VARCHAR(250);
          Declare Timediff int; 
          Declare v_expiry_time int; 
          Declare v_create_time datetime(3);
          
          sp_exit:
          BEGIN
             set errcode = -1;
             set errmsg = '';
             
             if not exists(select * from tb_ccaas_flow_otp_verfication_dtl a where a.input = input LIMIT 1) then
                set errcode = -1;
                set errmsg = 'Incorrect input address';
                LEAVE sp_exit;
             end if;
            
             if exists(select * from tb_ccaas_flow_otp_verfication_dtl a where a.input = input and a.verify_code <> verify_code order by id desc LIMIT 1) then
                set errcode = -1;
                set errmsg = 'Invalid OTP';
                LEAVE sp_exit;
             end if;
             
             if exists(select * from tb_ccaas_flow_otp_verfication_dtl a where a.input = input and a.verify_code = verify_code order by id desc LIMIT 1) then
             
     			select a.expiry_time, a.created_date into v_expiry_time, v_create_time
     			from tb_ccaas_flow_otp_verfication_dtl a where a.input = input and a.verify_code = verify_code  
     			order by id desc limit 1;
     
     			set Timediff = timestampdiff(second,v_create_time,NOW(3));  
     
     			if v_expiry_time <  Timediff Then  
     				set errcode = -1;  
     				set errmsg = 'OTP Expired';  
     				leave sp_exit;
     			End if;  
                 
                set errcode = 0;
                set errmsg = 'Success : input verified';
                
                UPDATE tb_ccaas_flow_otp_verfication_dtl a set a.is_verified = 1
                where a.input = input and a.verify_code = verify_code;
                LEAVE sp_exit;
             end if;
             
          END;
          select errcode as errcode,errmsg as errmsg; 
       
       End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
