CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentAssist`(
   p_domainId INT,
   p_channelType VARCHAR(10),
   p_channelId VARCHAR(100)
 )
BEGIN
   IF p_channelType LIKE '%Sms%' 
   THEN
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT knowledgeBasedId, websiteId
     FROM did_purchase a
     LEFT JOIN websiteScraper b ON a.domainId = b.domainId AND a.knowledgeBasedId = b.web_id
     WHERE your_number = p_channelId AND a.domainId = p_domainId;
   END IF;
   
   IF p_channelType LIKE '%Email%' 
   THEN
     SELECT websiteId, baseName, a.*
     FROM email_config a
     LEFT JOIN websiteScraper b ON a.domainId = b.domainId AND a.knowledgeBasedId = b.web_id
     WHERE emailAddress = p_channelId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END IF;
 END ;;
DELIMITER ;
