/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentCallSummaryReport` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getAgentCallSummaryReport`( 
	p_startTmpstmp	BIGINT,
	p_endTmpstmp	BIGINT,
	p_domainId		INT,
	p_agentId		TEXT,
	P_routingId		TEXT,
	p_customerId	TEXT,
	p_Limit			INT,
	p_Offset		INT
)
begin
 			DECLARE v_offset 		INT;
 			DECLARE v_Total_Count 	INT;
 			DECLARE v_startTmpstmp 	BIGINT;
 			DECLARE v_endTmpstmp 	BIGINT;
 		  
 			SET v_offset = p_Limit * p_offset; 
 
 				  
 			IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
 			IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
 			
 			  DROP TEMPORARY TABLE IF EXISTS temp_agentId; 	CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100)); 
 			  DROP TEMPORARY TABLE IF EXISTS temp_routingId;	CREATE TEMPORARY TABLE temp_routingId(routingId VARCHAR(100));
 			  
 			  CALL split(p_agentId,','); 	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
 			  CALL split(P_routingId,','); INSERT INTO temp_routingId(routingId) SELECT Items FROM tt_Split_temptable;
 			  
 			  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 			  DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
 			  CREATE TEMPORARY TABLE temp_AllagentId 
 			  select UserID,UserName,routing_profile_id from tb_User where domainId = p_domainId;
 			  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 				  
 			  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			  DROP TEMPORARY TABLE IF EXISTS temp_AllroutingId;
 			  CREATE TEMPORARY TABLE temp_AllroutingId
 			  select rid,name from routing_profile where domainId = p_domainId;
 			  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
 			CREATE TEMPORARY TABLE tt_temp_sessionHistory  		AS
 				SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(CH.sessionStartTime /1000) AS DATE))*1000 as SessionDate
 				,AA.UserName												AS AgentName
 				,AA.UserID
 				,AR.name													AS RoutingProfile
 				,CDH.transferredTypeId
 				,CH.callDuration											AS agentDuration
 				,CH.IsInBound
 				,CDH.AgentHoldDuration										AS agentHoldDuration
 				,CDH.afterCallWorkTime										AS afterCallWorkTime
 				,CH.CallHistoryId
                ,CDH.Duration												AS CallHandlingTime
                ,CDH.UMNStatus
                ,CDH.transferedTo
 				FROM 	tb_CallHistory 				CH
 				JOIN 	tb_CallDurationHistory		CDH	ON CH.CallHistoryId = CDH.CallHistoryId
 				JOIN 	temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
 				JOIN 	temp_AllroutingId			AR	ON AR.rid	 		= AA.routing_profile_id
 				WHERE 	CH.domainId 			= p_domainId 		
 				AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 				AND 	(IFNULL(p_agentId,'') 	= '' OR CDH.AgentId IN (SELECT agentId FROM temp_agentId));
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                       
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
 				DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory_1; 
 				CREATE TEMPORARY TABLE tt_temp_sessionHistory_1 AS   
 				SELECT 
 					distinct(CallHistoryId) as CallHistoryId,UserID,AgentName, RoutingProfile, CallHandlingTime
                    , transferredTypeId, agentDuration, IsInBound, agentHoldDuration, afterCallWorkTime,UMNStatus,transferedTo
 					FROM tt_temp_sessionHistory;
                      
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 				DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
 				CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
 				SELECT 	 
 					 SH.UserID  				                  
 					,SH.agentName 
 					,SH.RoutingProfile
 					,(CASE WHEN SH.CallHandlingTime> 0 and SH.IsInBound = 1  THEN sum(SH.CallHandlingTime/1000)  ELSE 0 END)	    AS TotalAmountOfTimeInbound
 					,(CASE WHEN SH.UMNStatus = 1 and SH.IsInBound = 0  THEN sum(SH.CallHandlingTime/1000)  ELSE 0 END) 	        	AS TotalAmountOfTimeOutbound
 					,sum(CASE WHEN UMNStatus = 1 AND  SH.CallHandlingTime > 0 AND SH.IsInBound = 0 THEN 1 ELSE 0 END ) 				AS outboundAnsweredCall
 					,sum(CASE WHEN SH.CallHandlingTime > 0 AND SH.IsInBound = 1 THEN 1 ELSE 0 END ) 							AS inboundAnsweredCall
 					,SUM(CASE WHEN SH.transferredTypeId > 0 AND SH.transferedTo IS NOT NULL THEN 1 ELSE 0 END)					AS	NoOfCallTransferred 
 					
 					,(sum(CASE WHEN UMNStatus = 1 AND  CallHandlingTime > 0 AND IsInBound = 0 THEN CallHandlingTime ELSE 0 END )
					+ sum(CASE WHEN CallHandlingTime > 0 AND IsInBound = 1 THEN CallHandlingTime ELSE 0 END ) ) 				AS totalTalktime
 					,SUM(CASE WHEN SH.CallHandlingTime > 0 THEN SH.CallHandlingTime ELSE 0 END) 								AS callHandlingTime
 					,SUM(CASE WHEN SH.IsInBound = 1 THEN 1 ELSE 0 END) 															AS receivedCall
 					,SUM(CASE WHEN SH.IsInBound = 0 THEN 1 ELSE 0 END) 															AS outboundCall
 					,SUM(CASE WHEN SH.agentHoldDuration > 0 THEN 1 ELSE 0 END)													AS noOfCallHoldCount
 					,SUM(SH.agentHoldDuration)																					AS callHoldTime
 					
                    ,((CASE WHEN SH.CallHandlingTime> 0 and SH.IsInBound = 1  THEN sum(SH.afterCallWorkTime)  ELSE 0 END)  +
 					(CASE WHEN SH.UMNStatus = 1 and SH.IsInBound = 0  THEN sum(SH.afterCallWorkTime)  ELSE 0 END)) AS NoOfAfterCallWorkTime
 				FROM 	tt_temp_sessionHistory_1 SH
 				GROUP BY SH.UserID, SH.agentName, SH.RoutingProfile,SH.CallHandlingTime,SH.IsInBound,SH.UMNStatus,SH.transferredTypeId,SH.transferedTo;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
                SELECT * FROM temp_AllagentId;
  
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 				DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc_1; 
 				CREATE TEMPORARY TABLE tt_sessionHistory_calc_1 AS
 				SELECT 
 					a.UserID 																													AS UserID,
 					a.agentName 																												AS agentName,
 					a.RoutingProfile																											AS routingProfile,
 					SUM(a.TotalAmountOfTimeInbound) 																							AS inboundTime,
 					SUM(a.receivedCall) 																										AS inboundCalls,
 					SUM(a.TotalAmountOfTimeOutbound) 																							AS outboundTime,
 					SUM(a.outboundCall) 																										AS outboundCalls,
 					SUM(a.NoOfCallTransferred) 																									AS transferredCalls,
 					SUM(a.totalTalktime + (IFNULL(a.NoOfAfterCallWorkTime,0)*1000)) 															AS totalCallHandlingTime,
 					CASE WHEN SUM(a.outboundAnsweredCall + a.inboundAnsweredCall ) = 0 THEN 0
 					ELSE SUM(a.totalTalktime + (IFNULL(a.NoOfAfterCallWorkTime,0)*1000)) / SUM(a.outboundAnsweredCall + a.inboundAnsweredCall) 
 					END 																														AS averageCallHandlingTime,
 					SUM(a.totalTalktime) / 1000 																								AS totalTalkTime,
 					CASE WHEN SUM(a.receivedCall + a.outboundCall) = 0 THEN 0
 					ELSE (SUM(a.totalTalktime) / SUM(a.receivedCall + a.outboundCall)) / 1000 
 					END 																														AS averageTalkTime,
 					SUM(a.NoOfAfterCallWorkTime) 																								AS TotalACWTime,
 					CASE 
 					WHEN SUM(CASE WHEN a.receivedCall < 1 THEN a.outboundCall ELSE a.receivedCall END) = 0 THEN 0
 					ELSE SUM(a.NoOfAfterCallWorkTime) / SUM(CASE WHEN a.receivedCall < 1 THEN a.outboundCall ELSE a.receivedCall END) 
 					END 																														AS averageACW,
 					SUM(a.callHoldTime) / 1000 																									AS totalHoldTime,
 					CASE 
 					WHEN SUM(a.outboundAnsweredCall + a.inboundAnsweredCall) = 0 THEN 0
 					ELSE SUM(a.callHoldTime) / SUM(a.outboundAnsweredCall + a.inboundAnsweredCall) / 1000 
 					END 																														AS averageHoldTime
 				FROM tt_sessionHistory_calc a
 				GROUP BY a.UserID, a.agentName, a.RoutingProfile;
        
 				SELECT 	COUNT(1) v_Total_Count
 				FROM 	tt_sessionHistory_calc_1 a;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 				select 
 					agentName,
 					routingProfile, 
 					inboundTime, 
 					inboundCalls, 
 					outboundTime as outboundtime, 
 					outboundcalls, 
 					transferredcalls, 
 					totalCallHandlingTime/1000   								as totalcallhandlingtime, 
 					averageCallHandlingTime/1000 								as averageCallhandlingtime,
 					totalTalkTime           								AS totalTalktime, 
 					averageTalkTime											AS averagetalktime, 
 					TotalACWTime,
 					averageACW, 
 					totalHoldTime, 
 					averageHoldTime
 				from tt_sessionHistory_calc_1;
 
               end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
