CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentDetails`(
   p_domainId  INT,
   p_UserID 	INT
   )
begin
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   SELECT * FROM tb_User tu
   Join agent_status     ags ON ags.aid = tu.StatusID
   WHERE tu.UserID = p_UserID  AND tu.domainId = p_domainId AND tu.voice = 1  AND ags.isVoice = 1;
   
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
