CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentListChat`(p_domainId int, p_qid int, p_ext int)
begin

	declare v_rqmid  varchar(250);
    
	SELECT group_concat(rqmid) into v_rqmid
    FROM routingqueueprofilemapping WHERE qid =p_qid;
    
    call up_GetAgentListChat(p_domainId,v_rqmid,p_ext);
End ;;
