/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentList_byEmail`(
        p_domainId         INT
        ,p_emailId          varchar(100)
        
        
        )
BEGIN
        
  		
  		
          
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  			SELECT 	b.statusName,a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.ext, 
  					a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession, a.isVoice, a.isVoiceCallTransfer, a.isChat, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
  					a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer,group_concat(qid) as quId 
  			FROM tb_User a 
  			JOIN agent_status b 				on a.StatusID 			= b.aid
  			JOIN routingqueueprofilemapping r 	on a.routing_profile_id	= r.rqmid and a.domainId = r.domainId
  			WHERE a.domainId =  p_domainId 
  			and  a.emailId COLLATE utf8mb4_unicode_ci = p_emailId  
  			and  a.roleid	= 6 
  			GROUP BY b.statusName,a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.ext, 
  			a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession, a.isVoice, a.isVoiceCallTransfer, a.isChat, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
  			a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer;
  			
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 	         
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
