/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentList_info`(
     p_domainId         INT,
     p_ext              INT,
     p_offset 			INT,
     p_Limit 			INT	)
BEGIN
     
 	DECLARE v_offset 					INT;	
	SET v_offset =  p_Limit * p_offset; 
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	b.statusName,a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.ext, 
   			a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession, a.isVoice, a.isVoiceCallTransfer, a.isChat, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
   			a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer,group_concat(qid) as quId 
   	FROM tb_User a 
   	JOIN agent_status b 				on a.StatusID 			= b.aid
   	JOIN routingqueueprofilemapping r 	on a.routing_profile_id	= r.rqmid and a.domainId = r.domainId
   	WHERE a.domainId =  p_domainId 
	and  (IFNULL(p_ext,0)=0 or a.ext = p_ext) 
    and  a.roleid	= 6 
   	GROUP BY b.statusName,a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.ext, 
   			a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession, a.isVoice, a.isVoiceCallTransfer, a.isChat, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
   			a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer
 			LIMIT 	 v_offset, p_Limit; 
   	     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 	         
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentLoginLogoutReport` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getAgentLoginLogoutReport`(
       p_startTmpstmp  BIGINT,
       p_endTmpstmp    BIGINT,
       p_timeZone      VARCHAR(200),
       p_domainId      INT,
       p_agentId       TEXT,
       p_Limit         INT,
       p_Offset        INT
  )
BEGIN
      DECLARE v_offset INT DEFAULT p_Limit * p_Offset;
      DECLARE v_startTmpstmp BIGINT;
      DECLARE v_endTmpstmp BIGINT;
	  DECLARE v_startTmpstmp1 datetime;
      DECLARE v_endTmpstmp1 datetime;
      DECLARE v_Total_Count 	INT;
      DECLARE v_timeZone_Hour	VARCHAR(200);
      DECLARE v_timeZone_Minute	VARCHAR(200);
      DECLARE v_timeZone_Sign	VARCHAR(200);
      DECLARE v_endTimeformate	DATETIME;
      
      DECLARE v_todaydate	DATETIME;
      
      SET v_endTimeformate = CAST(from_unixtime(p_endTmpstmp/1000) as datetime);
      
      set v_todaydate = CONVERT_TZ(now(), '+00:00', "+05:30");
      
    
  
      
	  

	IF p_timeZone IS NOT NULL THEN
      
      SET v_timeZone_Hour = REGEXP_REPLACE(SUBSTRING_INDEX(SUBSTRING_INDEX(p_timeZone, 'GMT ', -1), ':', 1), '^[+-]', '') * 60;
      SET v_timeZone_Minute = SUBSTRING_INDEX(SUBSTRING_INDEX(p_timeZone, ':', -1), ' ', 1) ;
      SET v_timeZone_Sign = SUBSTRING(SUBSTRING_INDEX(p_timeZone, 'GMT', -1), 2, 1);
      
     
      
      
      SET v_startTmpstmp1 = ( CONVERT(from_unixtime(p_startTmpstmp/1000), DATETIME) + INTERVAL v_timeZone_Hour MINUTE + INTERVAL v_timeZone_Minute MINUTE);
      SET v_endTmpstmp1 = ( CONVERT(from_unixtime(p_endTmpstmp/1000), DATETIME)+ INTERVAL v_timeZone_Hour MINUTE + INTERVAL v_timeZone_Minute MINUTE);
     
      SET v_startTmpstmp = unix_timestamp(v_startTmpstmp1)*1000;
      SET v_endTmpstmp = unix_timestamp(v_endTmpstmp1)*1000;
  
  
    


		ELSE 
        
        SET v_startTmpstmp = p_startTmpstmp;
        SET v_endTmpstmp = p_endTmpstmp;
        
        END IF;
  
	DROP TEMPORARY TABLE IF EXISTS temp_agentId;
	CREATE TEMPORARY TABLE IF NOT EXISTS temp_agentId(agentId VARCHAR(100)); 
      CALL split(p_agentId,',');
	
    INSERT INTO temp_agentId(agentId)
  	SELECT Items FROM tt_Split_temptable;
  
  	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
	CREATE TEMPORARY TABLE IF NOT EXISTS temp_AllagentId AS
  	SELECT UserName, ext, domainId FROM tb_User WHERE domainId = p_domainId;
      
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
	CREATE TEMPORARY TABLE temp_AvailableState AS
			SELECT   
			  CASE 
				  WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
				  WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) AND(isChat = 0) AND(isEmail=0)  ) THEN 2
				  ELSE 3 
			  END AS tt_Time,
			  CASE WHEN a.statusName IN ('Ready','Not Ready','Transfer Only','Away','Busy', 'Offline') THEN 0 ELSE ST.stateDuration END AS tt_stateDuration,    
			  ST.ext,
			  ST.domainId,
			  Cast(from_unixtime(ST.startTimestamp/1000)as datetime) as startDateTime,
			  ST.stateDuration as SD,      
			  DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d') AS startDate
			FROM     state_timer ST 
  	JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
  	WHERE    ST.domainId = p_domainId
  	AND 	 ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp; 
    
    
    
      
      DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory;
      CREATE TEMPORARY TABLE IF NOT EXISTS tt_logInSessionHistory AS
  	SELECT 
               DATE_FORMAT(LSH.createdAt, '%Y-%m-%d') AS SessionDate,
              U.UserName,
              LSH.ext,
            
              LSH.domainId,
             cast( FROM_UNIXTIME(LSH.logInTimestamp / 1000) + INTERVAL IFNULL(v_timeZone_Hour,0) MINUTE + INTERVAL IFNULL(v_timeZone_Minute,0) MINUTE AS DATETIME) AS LoginTime,
              cast(FROM_UNIXTIME(LSH.logOutTimestamp / 1000) + INTERVAL IFNULL(v_timeZone_Hour,0) MINUTE + INTERVAL IFNULL(v_timeZone_Minute,0) MINUTE AS DATETIME)AS LogOut,
              FROM_UNIXTIME(LSH.logInTimestamp / 1000) AS LoginDateTime,
              FROM_UNIXTIME(LSH.logOutTimestamp / 1000) AS LogOutDateTime,
              LSH.createdAt
      FROM logInSessionHistory LSH
   
    
      JOIN tb_User U ON U.ext = LSH.ext AND U.domainId = LSH.domainId
      WHERE LSH.domainId = p_domainId 
      AND UNIX_TIMESTAMP(LSH.createdAt)*1000 BETWEEN v_startTmpstmp AND v_endTmpstmp
      GROUP BY LSH.createdAt, U.UserName, LSH.ext, 
      
      LSH.domainId, LSH.logInTimestamp, LSH.logOutTimestamp;
      
      DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory1; 
      CREATE TEMPORARY TABLE tt_logInSessionHistory1 AS 
		with cte as(
				SELECT SessionDate, UserName, ext, domainId, LoginTime, LogOut, 
                LEAD(LoginTime)OVER (partition by UserName, ext, SessionDate order by LoginTime) AS logOut1,
                LEAD(SessionDate)OVER (partition by UserName, ext order by LoginTime) AS SessionDate1,
                createdAt
				 FROM tt_logInSessionHistory order by ext, LoginTime , LogOut
				)
             ,
 cte1 as(
 				
                 SELECT   SessionDate, UserName, ext, domainId,LoginTime, logOut AS logOutreal, logOut1, SessionDate1,
							CASE WHEN LogOut IS NOT NULL THEN LogOut 
							 WHEN (LogOut IS NULL AND logOut1 IS NOT NULL) AND (SessionDate = SessionDate1)  THEN logOut1
                            WHEN (LogOut IS NULL AND logOut1 IS NULL) AND (SessionDate != SessionDate1)  THEN DATE_SUB(DATE_ADD(CAST(SessionDate AS DATETIME),interval 24 hour), interval 1 second)
                           WHEN (LogOut IS NULL AND logOut1 IS NULL) AND (SessionDate1 is null)  AND (SessionDate = DATE(v_todaydate))THEN v_todaydate
                            WHEN (LogOut IS NULL AND logOut1 IS NULL) AND (SessionDate1 is null)  AND (SessionDate != DATE(v_todaydate))THEN CAST(CONCAT(SessionDate," 23:59:59") AS DATETIME)
						END AS LogOut
		FROM cte
        )
			SELECT  SessionDate, UserName, ext, domainId,MIN(LoginTime) as LoginTime, MAX(LogOut) as LogOut
        FROM cte1 group by SessionDate, UserName, ext, domainId;
        
  
      DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory_cal; 
      CREATE TEMPORARY TABLE tt_logInSessionHistory_cal AS 
      SELECT  tt_LSH.SessionDate,
              tt_LSH.UserName AS AgentName,
              MIN(tt_LSH.LoginTime) AS LoginTime,
              MAX(tt_LSH.LogOut) AS LogOut,
              tt_LSH.ext,
              tt_LSH.domainId,
          
          TIME_TO_SEC( TIMEDIFF(MAX(IFNULL(tt_LSH.LogOut, v_todaydate)), MIN(tt_LSH.LoginTime)) ) AS LoggedinDuration,
              SUM(CASE WHEN tt_AV.tt_Time = 1 THEN tt_AV.SD END) AS availableTime
			,SUM(CASE WHEN tt_AV.tt_Time = 2 THEN tt_AV.SD END) AS unAvailableTime
      FROM tt_logInSessionHistory1 tt_LSH
      JOIN temp_AvailableState tt_AV ON tt_LSH.ext = tt_AV.ext AND tt_AV.domainId = tt_LSH.domainId 
      WHERE (tt_AV.startDateTime >= tt_LSH.LoginTime AND tt_AV.startDateTime <  tt_LSH.LogOut)
      GROUP BY tt_LSH.UserName, tt_LSH.ext, tt_LSH.domainId,tt_LSH.SessionDate;
      
  
      SELECT * FROM temp_AllagentId;
  
      SELECT 	COUNT(1) v_Total_Count
  	FROM 	tt_logInSessionHistory_cal a;
      
	DROP TEMPORARY TABLE IF EXISTS tt2_availability_cal;
	CREATE TEMPORARY TABLE tt2_availability_cal AS 
	SELECT  ext, startDate, SUM(tt_stateDuration) AS custom
	FROM temp_AvailableState 
	GROUP BY ext,startDate;
  
    SELECT DISTINCT 
			  t1.SessionDate 													AS date,
              t1.AgentName								 						AS agentName,
              t1.LoginTime 														AS loginTime,
              CASE WHEN t1.LogOut = v_todaydate THEN NULL ELSE 	t1.LogOut END	AS logoutTime,
              t1.LoggedinDuration												AS loggedInDuration,
              IFNULL(ROUND(t1.availableTime/1000),0) 							AS availableTime,
             
			  t1.LoggedinDuration - IFNULL(ROUND(t1.availableTime/1000),0)  	AS unavailabletime,
			  ROUND(t2.custom) 													AS customTime
      FROM tt_logInSessionHistory_cal 	AS t1
      JOIN tt2_availability_cal 		AS t2 ON t2.ext = t1.ext
       AND t1.SessionDate =  t2.startDate;
      
  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentLoginLogoutReport_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentLoginLogoutReport_1`(
            p_startTmpstmp  BIGINT,
            p_endTmpstmp    BIGINT,
            p_timeZone 	 VARCHAR(200),
            p_domainId      INT,
            p_agentId       TEXT,
            p_Limit         INT,
            p_Offset        INT
        )
BEGIN
        		    DECLARE v_offset 		INT;
               	DECLARE v_Total_Count 	INT;
               	DECLARE v_startTmpstmp 	BIGINT;
               	DECLARE v_endTmpstmp 	BIGINT;
                
                   SET v_offset = p_Limit * p_offset; 
        
                
   			SET v_startTmpstmp = ROUND(UNIX_TIMESTAMP(DATE_SUB(FROM_UNIXTIME(p_startTmpstmp / 1000), INTERVAL 1 DAY)) * 1000); 
        		SET v_endTmpstmp 	= ROUND(UNIX_TIMESTAMP(DATE_SUB(FROM_UNIXTIME(p_endTmpstmp / 1000), INTERVAL 1 DAY)) * 1000); 
        		
        		DROP TEMPORARY TABLE IF EXISTS temp_agentId; 	CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100)); 
                
                CALL split(p_agentId,','); 	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
                
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
                CREATE TEMPORARY TABLE temp_AllagentId 
                select UserID,UserName,ext,sipLoginId from tb_User where domainId = p_domainId;
                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
              	CREATE TEMPORARY TABLE temp_AvailableState 
        		(    ext 				INT
        			
        			,AgentCategory		TINYINT
                 ,domainId			INT
        		); 
              	INSERT INTO temp_AvailableState 
              	SELECT 	ext 			ext
              	
             		,	CASE	
                                WHEN timerStatusId IN (1,3,6) THEN 1
                                WHEN timerStatusId IN (2,4,5)   THEN 2
        						ELSE 3
               			END 	AgentCategory
 					,domainId
              	FROM 	state_timer
              	WHERE 	domainId	= p_domainId;
                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
                CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
     		SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(LSH.logInTimestamp /1000) AS DATE))*1000 as SessionDate
     		,AA.UserName			as AgentName
     		,LSH.logInTimestamp		as LoginTime
     		,LSH.logOutTimestamp	as LogOut
     		,ST.stateDuration   
             ,CH.businessStartTime
 			,CH.businessEndTime
     		,CASE WHEN AgentCategory = 1 THEN stateDuration ELSE 0 END as AvailableTime 
     		,CASE WHEN AgentCategory = 2 THEN stateDuration ELSE 0 END as UnAvailableTime  
     		FROM logInSessionHistory 		LSH 
     		LEFT JOIN temp_AvailableState	AV	ON LSH.ext = AV.ext and AV.domainId = LSH.domainId
             LEFT JOIN tb_User 				UR 	ON UR.ext = LSH.ext	and UR.domainId = LSH.domainId
             LEFT JOIN tb_CallDurationHistory CD ON CD.AgentId = UR.UserID
             LEFT JOIN tb_CallHistory		CH 	ON CH.CallHistoryId = CD.CallHistoryId
 			LEFT JOIN temp_AllagentId 		AA	ON AA.UserID = CD.AgentId
 			LEFT JOIN temp_agentId 			t_A ON AA.UserID = t_A.agentId
     		LEFT JOIN state_timer			ST	ON ST.domainId = LSH.domainId AND ST.ext = LSH.ext
     		WHERE 	LSH.domainId 			= p_domainId 		
     	 	
 			AND 	LSH.logInTimestamp		BETWEEN v_startTmpstmp and v_endTmpstmp 
     		AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));
        		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
          SELECT * FROM tt_temp_sessionHistory;
 
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 				DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
 				CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
 				SELECT 	
 				SH.SessionDate,
                 SH.agentName,
 				SH.LoginTime,
 				SH.LogOut,
 				
 				
 				(SH.LogOut - SH.LoginTime) as LoggedinDuration,
                 (SH.LoginTime - SH.businessStartTime) as LBLT,
       			(SH.LogOut - SH.businessEndTime) as LOALT,
 				SUM(SH.AvailableTime) as AvailableTime,
 				SUM(SH.UnAvailableTime) as UnAvailableTime
        		FROM tt_temp_sessionHistory SH
        		GROUP BY SH.AgentName,SH.SessionDate, LoginTime, LogOut, LoggedinDuration, LBLT, LOALT;
        		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                        
        				SELECT * from temp_AllagentId;
                        
        				SELECT 	COUNT(1) v_Total_Count
        				FROM 	tt_sessionHistory_calc a;
                        
        				SELECT 	a.SessionDate						    		as `dateTime`
 							,a.agentName 									as agentName
 							,a.LoginTime                                   as loginTime
 							,a.LogOut                                      as logoutTime
 							,a.LBLT                                        as agentLoginDetails
 							,a.LOALT                                       as agentLogoutDetails
 							,a.LoggedinDuration/1000                       as loggedInDuration   
 							,a.AvailableTime                               as availableTime
 							,a.UnAvailableTime                             as unavailabletime
                        FROM 	tt_sessionHistory_calc a
        				ORDER BY a.SessionDate DESC
        				LIMIT v_offset, p_limit;               
                        
        end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentLoginLogoutReport_kms` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentLoginLogoutReport_kms`(
        p_startTmpstmp  BIGINT,
        p_endTmpstmp    BIGINT,
        p_timeZone      VARCHAR(200),
        p_domainId      INT,
        p_agentId       TEXT,
        p_Limit         INT,
        p_Offset        INT
   )
BEGIN
       DECLARE v_offset INT DEFAULT p_Limit * p_Offset;
       DECLARE v_startTmpstmp BIGINT;
       DECLARE v_endTmpstmp BIGINT;
       DECLARE v_Total_Count 	INT;
   
       SET v_startTmpstmp = p_startTmpstmp; 
       SET v_endTmpstmp   = p_endTmpstmp; 
   
       DROP TEMPORARY TABLE IF EXISTS temp_agentId;
       CREATE TEMPORARY TABLE IF NOT EXISTS temp_agentId(agentId VARCHAR(100)); 
       CALL split(p_agentId,',');
       INSERT INTO temp_agentId(agentId)
	   SELECT Items FROM tt_Split_temptable;
   
	   DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
       CREATE TEMPORARY TABLE IF NOT EXISTS temp_AllagentId AS
	   SELECT UserName, ext, domainId FROM tb_User WHERE domainId = p_domainId;
       
       DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
       CREATE TEMPORARY TABLE temp_AvailableState AS
   	SELECT   
   	CASE 
           WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
           WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) or (isChat = 0) or (isEmail=0)  ) THEN 2
           ELSE 3 
 	END AS tt_Time,
 	 CASE WHEN a.statusName IN ('Ready','Not Ready','Transfer Only','Away','Busy') THEN 0 ELSE ST.stateDuration END AS tt_stateDuration,    
       ST.ext,
       ST.domainId,
       from_unixtime(ST.startTimestamp/1000),
       ST.stateDuration as SD,      
       DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d') AS startDate
   	FROM     state_timer ST 
   	JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
   	WHERE    ST.domainId = p_domainId
   	AND 	 ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp; 
       
       DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory;
       CREATE TEMPORARY TABLE IF NOT EXISTS tt_logInSessionHistory AS
   	SELECT 
               DATE_FORMAT(LSH.createdAt, '%d %b %Y') AS SessionDate,
               U.UserName,
               LSH.ext,
               U.UserID		AgentId,
               LSH.domainId,
               TIME_FORMAT(FROM_UNIXTIME(LSH.logInTimestamp / 1000), '%H:%i:%s') AS LoginTime,
               TIME_FORMAT(FROM_UNIXTIME(LSH.logOutTimestamp / 1000), '%H:%i:%s') AS LogOut,
               FROM_UNIXTIME(LSH.logInTimestamp / 1000) AS LoginDateTime,
               FROM_UNIXTIME(LSH.logOutTimestamp / 1000) AS LogOutDateTime,
               LSH.logInTimestamp,
               LSH.createdAt
       FROM logInSessionHistory LSH
 
       JOIN tb_User U ON U.ext = LSH.ext AND U.domainId = LSH.domainId
       WHERE LSH.domainId = p_domainId

		AND  	LSH.logInTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;
       
   
       DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory_cal; 
       CREATE TEMPORARY TABLE tt_logInSessionHistory_cal AS 
       SELECT  tt_LSH.SessionDate,
               tt_LSH.UserName AS AgentName,
               MIN(tt_LSH.LoginTime) AS LoginTime,
               MAX(tt_LSH.LogOut) AS LogOut,
               tt_LSH.ext,
               tt_LSH.domainId,
               ROUND(TIME_TO_SEC(TIMEDIFF(MAX(tt_LSH.LogOutDateTime), MIN(tt_LSH.LoginDateTime))) * 1000) AS LoggedinDuration,
               SUM(CASE WHEN tt_AV.tt_Time = 1 THEN tt_AV.SD ELSE 0 END) AS availableTime,
               SUM(CASE WHEN tt_AV.tt_Time = 2 THEN tt_AV.SD ELSE 0 END) AS unAvailableTime
       FROM tt_logInSessionHistory tt_LSH
       JOIN temp_AvailableState tt_AV ON tt_LSH.ext = tt_AV.ext AND tt_AV.domainId = tt_LSH.domainId

		AND 	tt_LSH.logInTimestamp	BETWEEN v_startTmpstmp AND v_endTmpstmp
       GROUP BY tt_LSH.UserName, tt_LSH.ext, tt_LSH.domainId,tt_LSH.SessionDate;
       
   
       SELECT * FROM temp_AllagentId;
   
       SELECT 	COUNT(1) v_Total_Count
   	FROM 	tt_logInSessionHistory_cal a;
       
 	DROP TEMPORARY TABLE IF EXISTS tt2_availability_cal;
 	CREATE TEMPORARY TABLE tt2_availability_cal AS 
 	SELECT  ext, startDate, SUM(tt_stateDuration) AS custom
 	FROM temp_AvailableState 
 	GROUP BY ext,startDate;
   
     SELECT DISTINCT 
   			t1.SessionDate as date,
               t1.AgentName AS agentName,
               t1.LoginTime AS loginTime,
               t1.LogOut AS logoutTime,
               round(t1.LoggedinDuration / 1000) AS loggedInDuration,
               round(t1.availableTime/ 1000) AS availableTime,
               round(t1.unAvailableTime/ 1000) AS unavailabletime,
                ROUND(t2.custom/1000) AS customTime
       FROM tt_logInSessionHistory_cal 	AS t1
       join tt2_availability_cal 		AS t2 ON t2.ext = t1.ext;
   
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentLoginLogoutReport_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getAgentLoginLogoutReport_test`(
       p_startTmpstmp  BIGINT,
       p_endTmpstmp    BIGINT,
       p_timeZone      VARCHAR(200),
       p_domainId      INT,
       p_agentId       TEXT,
       p_Limit         INT,
       p_Offset        INT
  )
BEGIN
      DECLARE v_offset INT DEFAULT p_Limit * p_Offset;
      DECLARE v_startTmpstmp BIGINT;
      DECLARE v_endTmpstmp BIGINT;
	  DECLARE v_startTmpstmp1 datetime;
      DECLARE v_endTmpstmp1 datetime;
      DECLARE v_Total_Count 	INT;
      DECLARE v_timeZone_Hour	VARCHAR(200);
      DECLARE v_timeZone_Minute	VARCHAR(200);
      DECLARE v_timeZone_Sign	VARCHAR(200);
      DECLARE v_endTimeformate	DATETIME;
      
      DECLARE v_todaydate	DATETIME;
      
      SET v_endTimeformate = CAST(from_unixtime(p_endTmpstmp/1000) as datetime);
      
      set v_todaydate = CONVERT_TZ(now(), '+00:00', "+05:30");
      
    
  
      
	  

	IF p_timeZone IS NOT NULL THEN
      
      SET v_timeZone_Hour = REGEXP_REPLACE(SUBSTRING_INDEX(SUBSTRING_INDEX(p_timeZone, 'GMT ', -1), ':', 1), '^[+-]', '') * 60;
      SET v_timeZone_Minute = SUBSTRING_INDEX(SUBSTRING_INDEX(p_timeZone, ':', -1), ' ', 1) ;
      SET v_timeZone_Sign = SUBSTRING(SUBSTRING_INDEX(p_timeZone, 'GMT', -1), 2, 1);
      
     
      
      
      SET v_startTmpstmp1 = ( CONVERT(from_unixtime(p_startTmpstmp/1000), DATETIME) + INTERVAL v_timeZone_Hour MINUTE + INTERVAL v_timeZone_Minute MINUTE);
      SET v_endTmpstmp1 = ( CONVERT(from_unixtime(p_endTmpstmp/1000), DATETIME)+ INTERVAL v_timeZone_Hour MINUTE + INTERVAL v_timeZone_Minute MINUTE);
     
      SET v_startTmpstmp = unix_timestamp(v_startTmpstmp1)*1000;
      SET v_endTmpstmp = unix_timestamp(v_endTmpstmp1)*1000;
  
  
    


		ELSE 
        
        SET v_startTmpstmp = p_startTmpstmp;
        SET v_endTmpstmp = p_endTmpstmp;
        
        END IF;
  
	DROP TEMPORARY TABLE IF EXISTS temp_agentId;
	CREATE TEMPORARY TABLE IF NOT EXISTS temp_agentId(agentId VARCHAR(100)); 
      CALL split(p_agentId,',');
	
    INSERT INTO temp_agentId(agentId)
  	SELECT Items FROM tt_Split_temptable;
  
  	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
	CREATE TEMPORARY TABLE IF NOT EXISTS temp_AllagentId AS
  	SELECT UserName, ext, domainId FROM tb_User WHERE domainId = p_domainId;
      
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
	CREATE TEMPORARY TABLE temp_AvailableState AS
			SELECT   
			  CASE 
				  WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
				  WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) AND(isChat = 0) AND(isEmail=0)  ) THEN 2
				  ELSE 3 
			  END AS tt_Time,
			  CASE WHEN a.statusName IN ('Ready','Not Ready','Transfer Only','Away','Busy', 'Offline') THEN 0 ELSE ST.stateDuration END AS tt_stateDuration,    
			  ST.ext,
			  ST.domainId,
			  Cast(from_unixtime(ST.startTimestamp/1000)as datetime) as startDateTime,
			  ST.stateDuration as SD,      
			  DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d') AS startDate
			FROM     state_timer ST 
  	JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
  	WHERE    ST.domainId = p_domainId
  	AND 	 ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp; 
    
    
    
      
      DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory;
      CREATE TEMPORARY TABLE IF NOT EXISTS tt_logInSessionHistory AS
  	SELECT 
               DATE_FORMAT(LSH.createdAt, '%Y-%m-%d') AS SessionDate,
              U.UserName,
              LSH.ext,
            
              LSH.domainId,
             cast( FROM_UNIXTIME(LSH.logInTimestamp / 1000) + INTERVAL IFNULL(v_timeZone_Hour,0) MINUTE + INTERVAL IFNULL(v_timeZone_Minute,0) MINUTE AS DATETIME) AS LoginTime,
              cast(FROM_UNIXTIME(LSH.logOutTimestamp / 1000) + INTERVAL IFNULL(v_timeZone_Hour,0) MINUTE + INTERVAL IFNULL(v_timeZone_Minute,0) MINUTE AS DATETIME)AS LogOut,
              FROM_UNIXTIME(LSH.logInTimestamp / 1000) AS LoginDateTime,
              FROM_UNIXTIME(LSH.logOutTimestamp / 1000) AS LogOutDateTime,
              LSH.createdAt
      FROM logInSessionHistory LSH
   
    
      JOIN tb_User U ON U.ext = LSH.ext AND U.domainId = LSH.domainId
      WHERE LSH.domainId = p_domainId 
      AND UNIX_TIMESTAMP(LSH.createdAt)*1000 BETWEEN v_startTmpstmp AND v_endTmpstmp
      GROUP BY LSH.createdAt, U.UserName, LSH.ext, 
      
      LSH.domainId, LSH.logInTimestamp, LSH.logOutTimestamp;
      
      DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory1; 
      CREATE TEMPORARY TABLE tt_logInSessionHistory1 AS 
		with cte as(
				SELECT SessionDate, UserName, ext, domainId, LoginTime, LogOut, 
                LEAD(LoginTime)OVER (partition by UserName, ext, SessionDate order by LoginTime) AS logOut1,
                LEAD(SessionDate)OVER (partition by UserName, ext order by LoginTime) AS SessionDate1,
                createdAt
				 FROM tt_logInSessionHistory order by ext, LoginTime , LogOut
				)
             ,
 cte1 as(
 				
                 SELECT   SessionDate, UserName, ext, domainId,LoginTime, logOut AS logOutreal, logOut1, SessionDate1,
							CASE WHEN LogOut IS NOT NULL THEN LogOut 
							 WHEN (LogOut IS NULL AND logOut1 IS NOT NULL) AND (SessionDate = SessionDate1)  THEN logOut1
                            WHEN (LogOut IS NULL AND logOut1 IS NULL) AND (SessionDate != SessionDate1)  THEN DATE_SUB(DATE_ADD(CAST(SessionDate AS DATETIME),interval 24 hour), interval 1 second)
                           WHEN (LogOut IS NULL AND logOut1 IS NULL) AND (SessionDate1 is null)  AND (SessionDate = DATE(v_todaydate))THEN v_todaydate
                            WHEN (LogOut IS NULL AND logOut1 IS NULL) AND (SessionDate1 is null)  AND (SessionDate != DATE(v_todaydate))THEN CAST(CONCAT(SessionDate," 23:59:59") AS DATETIME)
						END AS LogOut
		FROM cte
        )
			SELECT  SessionDate, UserName, ext, domainId,MIN(LoginTime) as LoginTime, MAX(LogOut) as LogOut
        FROM cte1 group by SessionDate, UserName, ext, domainId;
        
  
      DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory_cal; 
      CREATE TEMPORARY TABLE tt_logInSessionHistory_cal AS 
      SELECT  tt_LSH.SessionDate,
              tt_LSH.UserName AS AgentName,
              MIN(tt_LSH.LoginTime) AS LoginTime,
              MAX(tt_LSH.LogOut) AS LogOut,
              tt_LSH.ext,
              tt_LSH.domainId,
          
          TIME_TO_SEC( TIMEDIFF(MAX(IFNULL(tt_LSH.LogOut, v_todaydate)), MIN(tt_LSH.LoginTime)) ) AS LoggedinDuration,
              SUM(CASE WHEN tt_AV.tt_Time = 1 THEN tt_AV.SD END) AS availableTime
			,SUM(CASE WHEN tt_AV.tt_Time = 2 THEN tt_AV.SD END) AS unAvailableTime
      FROM tt_logInSessionHistory1 tt_LSH
      JOIN temp_AvailableState tt_AV ON tt_LSH.ext = tt_AV.ext AND tt_AV.domainId = tt_LSH.domainId 
      WHERE (tt_AV.startDateTime >= tt_LSH.LoginTime AND tt_AV.startDateTime <  tt_LSH.LogOut)
      GROUP BY tt_LSH.UserName, tt_LSH.ext, tt_LSH.domainId,tt_LSH.SessionDate;
      
  
      SELECT * FROM temp_AllagentId;
  
      SELECT 	COUNT(1) v_Total_Count
  	FROM 	tt_logInSessionHistory_cal a;
      
	DROP TEMPORARY TABLE IF EXISTS tt2_availability_cal;
	CREATE TEMPORARY TABLE tt2_availability_cal AS 
	SELECT  ext, startDate, SUM(tt_stateDuration) AS custom
	FROM temp_AvailableState 
	GROUP BY ext,startDate;
  
    SELECT DISTINCT 
			  t1.SessionDate 													AS date,
              t1.AgentName								 						AS agentName,
              t1.LoginTime 														AS loginTime,
              CASE WHEN t1.LogOut = v_todaydate THEN NULL ELSE 	t1.LogOut END	AS logoutTime,
              t1.LoggedinDuration												AS loggedInDuration,
              IFNULL(ROUND(t1.availableTime/1000),0) 							AS availableTime,
             
			  t1.LoggedinDuration - IFNULL(ROUND(t1.availableTime/1000),0)  	AS unavailabletime,
			  ROUND(t2.custom) 													AS customTime
      FROM tt_logInSessionHistory_cal 	AS t1
      JOIN tt2_availability_cal 		AS t2 ON t2.ext = t1.ext
       AND t1.SessionDate =  t2.startDate;
      
  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentPerformanceReport` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getAgentPerformanceReport`(
 		p_startTmpstmp 	BIGINT,
 		p_endTmpstmp   	BIGINT,
 		p_timeZone 	 	VARCHAR(200),
 		p_domainId     	INT, 
 		p_agentId      	TEXT,
 		p_Limit        	INT,
 		p_Offset       	INT
 )
begin
			DECLARE v_startTmpstmp 				BIGINT;
			DECLARE v_endTmpstmp 				BIGINT;
			DECLARE v_offset 					INT;
			DECLARE v_Total_Count 				INT;
			DECLARE p_channelType 	            VARCHAR(255);
            DECLARE v_overAllavailableTime 	    BIGINT;
            DECLARE v_totalCSAT 	    		INT;

			SET v_offset = p_Limit * p_offset; 
			SET p_channelType = 'Chat,Call,Email,Sms,Whatsapp';

			IF IFNULL(p_startTmpstmp,0)=0 	THEN SET v_startTmpstmp  = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
			IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
			IF IFNULL(p_channelType,0) = 0 	THEN SET p_channelType = 'Chat,Call,Email,Sms,Whatsapp'; END IF;  
		        
			DROP TEMPORARY TABLE IF EXISTS temp_agentId; 		CREATE TEMPORARY TABLE temp_agentId(agentId INT); 
			DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));

			CALL split(p_agentId,','); 	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
			CALL split(p_channelType, ','); 	INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;        
            
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
			CREATE TEMPORARY TABLE temp_AllagentId 
			select UserID,UserName,ext,domainId from tb_User where domainId = p_domainId;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                           
		DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
		CREATE TEMPORARY TABLE temp_AvailableStates AS
		SELECT   
		CASE 
			WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
			WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) or (isChat = 0) or (isEmail=0)  ) THEN 2
			ELSE 3 
			END AS tt_Time,
            ST.ext,
			ST.domainId,
			ST.stateDuration as SD,
            from_unixtime(ST.startTimestamp/1000)
		FROM     state_timer ST 
		JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
		WHERE    ST.domainId = p_domainId
		AND      ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;    
        
        DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates_final;
		CREATE TEMPORARY TABLE temp_AvailableStates_final AS
        SELECT U.UserName
        ,SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) as availTime
        
		FROM temp_AvailableStates tt 
        JOIN tb_User U ON tt.ext = U.ext AND tt.domainId = U.domainId
        WHERE    tt.domainId = p_domainId
		GROUP BY tt.domainId,U.UserName;              
                  
  				  DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list;
  				  CREATE TEMPORARY TABLE temp_getcallback_list (
                    SessionDate        DATETIME,
                    UserID             INT,
                    agentId            INT,
                    AgentName          VARCHAR(100),
                    IsInBound          INT,
                    dispositionName    VARCHAR(100),
                    dialDuration       INT,
                    waitDuration       INT,
                    chatDuration       INT,
                    callDuration       INT,
                    SMSDuration        INT,
                    WhatsappDuration   INT,
                 
                  
                     IsMissed     		INT,
                     HistoryId        BIGINT,
                    sessionEndTime     BIGINT,
                    sessionStartTime   BIGINT,
                    SentimentalScore   INT,
                    dispositionId      INT,
                    Duration           INT,
                    availableTime      BIGINT,
                    afterCallWorkTime  INT
                );
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                 
                 IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Call' LIMIT 1) THEN
                     INSERT INTO temp_getcallback_list(
                         SessionDate, AgentId,UserID,AgentName, IsInBound, dispositionName, dialDuration, waitDuration, 
                         callDuration, HistoryId, sessionEndTime, sessionStartTime, SentimentalScore, dispositionId,Duration,afterCallWorkTime,IsMissed
                     )
                     SELECT 
                         FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate,
                         CDH.AgentId,
                         AA.UserID,
                          AA.UserName 					AS AgentName,         
                         CH.IsInBound,
                         DS.dispositionName,
                         
                         CDH.answeredDuration				AS dialDuration,  
                         CDH.answeredDuration				AS waitDuration,
                         CH.callDuration,
                         CH.CallHistoryId,
                         CH.sessionEndTime,
                         CH.sessionStartTime,
                         CDH.SentimentalScore,
                         CDH.dispositionId,
                         
                         (CASE WHEN UMNStatus = 1 AND  Duration > 0 AND IsInBound = 0 THEN Duration ELSE 0 END 
						 + CASE WHEN Duration > 0 AND IsInBound = 1 THEN Duration ELSE 0 END) as Duration
                         ,CDH.afterCallWorkTime,
                         CDH.IsMissedCall  				AS IsMissed
                     FROM 
                         tb_CallHistory CH
                         JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
                         LEFT JOIN temp_AllagentId AA ON AA.UserID = CDH.AgentId
                         LEFT JOIN temp_agentId t_A ON AA.UserID = t_A.agentId
                         LEFT JOIN disposition_status DS ON DS.did = CDH.dispositionId AND CH.domainId = DS.domainId
                         LEFT JOIN logInSessionHistory LSH ON AA.ext = LSH.ext AND LSH.domainId = CH.domainId
                     WHERE 
                         CH.domainId = p_domainId
                         AND CDH.IsBot=0
                         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                         AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL));
                 END IF;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                 
                 IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Chat' LIMIT 1) THEN
                     INSERT INTO temp_getcallback_list(
                         SessionDate,AgentId,UserID, AgentName, IsInBound, dispositionName, dialDuration, chatDuration, 
                         HistoryId, sessionEndTime, sessionStartTime, SentimentalScore, dispositionId,Duration,afterCallWorkTime,waitDuration,IsMissed
                     )
                     SELECT 
                         FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate,
                         CDH.AgentId,          
                         AA.UserID,
                         AA.UserName AS AgentName,
                         CH.IsInBound,
                         DS.dispositionName,
                         
                         CDH.answeredDuration				AS dialDuration, 
                         CDH.Duration AS chatDuration,
                         CH.ChatHistoryId,
                         CH.sessionEndTime,
                         CH.sessionStartTime,
                         CDH.SentimentalScore,
                         CDH.dispositionId,
                         CDH.Duration,
                         CDH.afterChatWorkTime,
                         CDH.answeredDuration AS waitDuration,
                         
                         CDH.IsMissed
                     FROM 
                         tb_ChatHistory CH
                         JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
                         LEFT JOIN temp_AllagentId AA ON AA.UserID = CDH.AgentId
                         LEFT JOIN temp_agentId t_A ON AA.UserID = t_A.agentId
                         LEFT JOIN disposition_status DS ON DS.did = CDH.dispositionId AND CH.domainId = DS.domainId
                         LEFT JOIN logInSessionHistory LSH ON AA.ext = LSH.ext AND LSH.domainId = CH.domainId
                     WHERE 
                         CH.domainId = p_domainId         
                         AND CDH.IsBot=0
                         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                         AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL));
                 END IF;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 		IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'SMS' LIMIT 1 )THEN
                  INSERT INTO temp_getcallback_list(SessionDate,AgentName,UserID,AgentId,IsInBound,dispositionName,waitDuration,SMSDuration,HistoryId,
 					sessionEndTime,sessionStartTime,SentimentalScore,dispositionId,Duration,afterCallWorkTime ,dialDuration)
                 
                 SELECT FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate
 						,	AA.UserName				AS AgentName
 						,AA.UserID
 						,   CDH.AgentId  
 						,	CH.IsInBound
 						,	DS.dispositionName		
 						
 						,	CH.waitDuration
 						,	CDH.Duration             AS SMSDuration
 						,	CH.SMSHistoryId
 						,	CH.sessionEndTime
 						,	CH.sessionStartTime
 						,	CH.SentimentalScore
 						,	CH.dispositionId
 						,   CDH.Duration
 						,   CH.afterSMSWorkTime
                         ,	CASE WHEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt)<= P.smsThreshold * 3600 THEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt) ELSE 0 END AS dialDuration
 				FROM tb_SMSHistory 					CH        
 				JOIN tb_SMSDurationHistory			CDH	ON 	CH.SMSHistoryId = CDH.SMSHistoryId        
 				LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId 
 				AND CH.domainId = DS.domainId        
 				LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
 				LEFT JOIN temp_agentId 				t_A ON AA.UserID 		= t_A.agentId 
 				LEFT JOIN logInSessionHistory		LSH ON AA.ext			= LSH.ext 
 				and LSH.domainId = CH.domainId
 				left JOIN 	did_purchase				P	ON 	P.your_number	= CH.calledNumber AND	P.domainId		= CH.domainId
 				WHERE 	CH.domainId 			= p_domainId 		
 				AND 	CDH.IsBot=0
 				AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 				AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));
 				End if; 
                       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                                             
                      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 		IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'EMAIL' LIMIT 1 )THEN
                         INSERT INTO temp_getcallback_list(SessionDate,AgentName,UserID,AgentId,IsInBound,dispositionName,waitDuration,SMSDuration,HistoryId,sessionEndTime,
                                           sessionStartTime,SentimentalScore,dispositionId,Duration,afterCallWorkTime ,dialDuration) 
                       
                  SELECT FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate
 						,	AA.UserName				AS AgentName
 						,    AA.UserID
 						,    CDH.AgentId
 						,	CH.IsInBound
 						,	DS.dispositionName		
 						
 						,	CH.waitDuration
 						,	CDH.Duration             AS SMSDuration
 						,	CH.EmailHistoryId
 						,	CH.sessionEndTime
 						,	CH.sessionStartTime
 						,	CH.SentimentalScore
 						,	CH.DispositionId
 						,   CDH.Duration
 						,   CH.AfterEmailWorkTime
                        ,	CASE WHEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt)<= ec.emailThreshold * 3600 AND CH.DispositionId is not null THEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt) ELSE 0 END AS dialDuration
                           FROM tb_EmailHistory 			CH        
 				JOIN tb_EmailDurationHistory			CDH	ON 	CH.EmailHistoryId = CDH.EmailHistoryId        
 				LEFT JOIN disposition_status			DS 	ON DS.did			= CH.DispositionId  and CH.domainId = DS.domainId        
 				LEFT JOIN temp_AllagentId 				AA	ON AA.UserID 		= CDH.AgentId
 				LEFT JOIN temp_agentId 					t_A ON AA.UserID 		= t_A.agentId 
 				LEFT JOIN logInSessionHistory			LSH ON AA.ext			= LSH.ext  			and LSH.domainId = CH.domainId
 				LEFT JOIN email_config 					ec	ON	ec.emailAddress		= CH.ToEmail AND	ec.domainId 		= CH.domainId   
 				WHERE 	CH.domainId 			= p_domainId 
 				AND CDH.IsBot=0
 				AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 				AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));     
                            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                 	End if;       
                 
  					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  					IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Whatsapp' LIMIT 1 )
                    THEN
						INSERT INTO temp_getcallback_list(
                        SessionDate,AgentName,UserID,IsInBound,dispositionName,waitDuration,WhatsappDuration,HistoryId,sessionEndTime,
						sessionStartTime,SentimentalScore,dispositionId,Duration,afterCallWorkTime ,dialDuration)                         
                     SELECT FROM_UNIXTIME(CH.sessionStartTime / 1000)      AS SessionDate
 							,	AA.UserName								   AS AgentName 							
 							,   CDH.AgentId
 							,	CH.IsInBound
 							,	DS.dispositionName		
 							
 							,	0                                           AS waitDuration
 							,	CDH.Duration             					AS WhatsappDuration
 							,	CH.WhatsappHistoryId
 							,	CH.sessionEndTime
 							,	CH.sessionStartTime
 							,	CH.SentimentalScore
 							,	CH.dispositionId
 							,  	CDH.Duration
 							,  	CH.afterwhatsappWorkTime
 							,	CDH.dialDuration as dialDuration
						FROM tb_WhatsappHistory 			CH        
						JOIN tb_WhatsappDurationHistory		CDH	ON 	CH.WhatsappHistoryId = CDH.WhatsappHistoryId        
						left JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
						LEFT JOIN temp_agentId 				t_A ON AA.UserID 		= t_A.agentId 
						LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId and CH.domainId = DS.domainId
						LEFT JOIN logInSessionHistory		LSH ON AA.ext			= LSH.ext 
																and LSH.domainId 	= CH.domainId
						WHERE 	CH.domainId		= p_domainId 	
						AND     CDH.IsBot		= 0
						AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
						AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));     
						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
					End if;
                                 
                                 
                                 
                        
  			UPDATE temp_getcallback_list SH_C
  			JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
  			JOIN (
  				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
  				FROM temp_AvailableStates
  				GROUP BY ext, domainId
  			) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
  			SET SH_C.availableTime = tt_AV.total_SD;
     
          				DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1; 
                		    CREATE TEMPORARY TABLE temp_getcallback_list_1 AS 
              			select distinct(HistoryId) as HistoryId,SessionDate, UserID, agentId, AgentName, IsInBound, dispositionName, dialDuration, waitDuration, chatDuration, callDuration, SMSDuration, WhatsappDuration, 
                          sessionEndTime, sessionStartTime, SentimentalScore, dispositionId, (Duration) as Duration, availableTime, afterCallWorkTime,IsMissed from temp_getcallback_list;                             
                       
                 		 DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 
                         
                           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                           DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
                 		  CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
                 		  SELECT  distinct(SH.UserID)   AS AgentId
                            
                           
                   		  ,SH.AgentName
                         
                           ,SUM(SH.waitDuration) 																										AS waitTimeAnsweredCall
                          ,SUM(CASE WHEN SH.dispositionId IS NOT NULL and SH.IsMissed =0 THEN 1 ELSE 0 END ) 											AS totalNumberOfAnswered
                      	  ,SUM(CASE WHEN SH.dialDuration BETWEEN 1 AND 30000 AND SH.dialDuration IS NOT NULL and SH.IsMissed =0 THEN 1 
 									WHEN SH.dialDuration BETWEEN 1 AND 30000 AND SH.SMSDuration IS NOT NULL and SH.IsMissed is null THEN 1 
                                     WHEN SH.dialDuration BETWEEN 1 AND 30000 AND SH.chatDuration IS NOT NULL and SH.IsMissed is null THEN 1
                                     ELSE 0  END)														AS thresholdTime
                           ,count(1) 																													AS queriesReceived
                       	  ,SUM(CASE WHEN SH.dispositionName in ('Closed','Resolved') THEN 1 ELSE 0 END) 												AS queriesResolved
                           ,SUM(CASE WHEN SH.dispositionName IS NOT NULL THEN 1 ELSE 0 END ) 															AS queriesAnswered
                           ,SUM(SH.SentimentalScore) 																									AS CSATscore
                           ,SH.availableTime																											AS availableTime
                           
                           ,sum(Duration)                                                                        						AS Duration
                           FROM temp_getcallback_list_1 SH
                           where SH.UserID is not null 
						   GROUP BY SH.UserID,SH.AgentName,SH.availableTime;
                   		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
                        
                           DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc_1; 
                 		    CREATE TEMPORARY TABLE tt_sessionHistory_calc_1 AS 
               			select distinct(AgentId)as AgentId, AgentName, waitTimeAnsweredCall, totalNumberOfAnswered, thresholdTime, queriesReceived, 
               			queriesResolved, queriesAnswered, CSATscore, availableTime, Duration from tt_sessionHistory_calc;               
  			
  				SELECT * from temp_AllagentId;
                                   
				SELECT 	COUNT(1) v_Total_Count
				FROM 	tt_sessionHistory_calc a;
				
				SELECT SUM(IFNULL(satisfactionRate,0)) INTO v_totalCSAT
				FROM tb_customerFeedback
				WHERE domainId = p_domainId
				AND	IFNULL(updatedDate,createdDate) BETWEEN DATE_FORMAT(FROM_UNIXTIME(v_startTmpstmp/1000),'%Y-%m-%d %H:%i:%s') AND  DATE_FORMAT(FROM_UNIXTIME(v_endTmpstmp/1000),'%Y-%m-%d %H:%i:%s')
				AND (IFNULL(p_agentId,0)=0 OR AgentId = p_agentId);
           
           IF((p_limit IS NOT NULL)AND (p_Offset IS NOT NULL)) THEN
				
                SELECT  
				 a.AgentName																AS agentName                   
			  
			   ,sum(a.waitTimeAnsweredCall/a.queriesAnswered)								AS averagespeedofanswer
			   ,sum((a.thresholdTime/a.queriesReceived)*100)								AS serviceLevel
			   ,sum((Duration/availTime)*100)												AS occupancyrate
			   ,sum((a.queriesResolved/a.queriesAnswered)*100)								AS resolvedqueries
			   ,sum(v_totalCSAT/a.queriesAnswered)											AS CSATscore
			
			   FROM 	tt_sessionHistory_calc a
               join temp_AvailableStates_final f on a.AgentName collate utf8mb4_unicode_ci = f.UserName
			   GROUP BY a.AgentName 
			  LIMIT v_offset, p_limit;    
           
           ELSE
           
					SELECT  
				 a.AgentName																AS agentName                   
			  
			   ,sum(a.waitTimeAnsweredCall/a.queriesAnswered)								AS averagespeedofanswer
			   ,sum((a.thresholdTime/a.queriesReceived)*100)								AS serviceLevel
			   ,sum((Duration/availTime)*100)												AS occupancyrate
			   ,sum((a.queriesResolved/a.queriesAnswered)*100)								AS resolvedqueries
			   ,sum(v_totalCSAT/a.queriesAnswered)											AS CSATscore
			
			   FROM 	tt_sessionHistory_calc a
               join temp_AvailableStates_final f on a.AgentName collate utf8mb4_unicode_ci = f.UserName
			   GROUP BY a.AgentName 
			 ;
           
           END IF;
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getAgentStatusReport` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getAgentStatusReport`(
     p_startTmpstmp  BIGINT,
     p_endTmpstmp    BIGINT,
     p_timeZone      VARCHAR(200),
     p_domainId      INT,
     p_agentId       TEXT,
     p_Limit         INT,
     p_Offset        INT
 )
BEGIN
     DECLARE v_offset        INT;
     DECLARE v_Total_Count   INT;
     DECLARE v_startTmpstmp  BIGINT;
     DECLARE v_endTmpstmp    BIGINT;
     
     DECLARE v_CurrentTimestamp BIGINT;
     
     SET v_CurrentTimestamp =  unix_timestamp(now())*1000;
     
 
     SET v_offset = p_Limit * p_Offset; 
 
     SET v_startTmpstmp 	= p_startTmpstmp; 
 	SET v_endTmpstmp 	= p_endTmpstmp; 
 
     DROP TEMPORARY TABLE IF EXISTS temp_agentId;
     CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100)); 
     CALL split(p_agentId, ','); 
     INSERT INTO temp_agentId(agentId) 
     SELECT Items FROM tt_Split_temptable;
 
     DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
     CREATE TEMPORARY TABLE IF NOT EXISTS temp_AllagentId AS
     SELECT UserName,UserID, ext, domainId FROM tb_User WHERE domainId = p_domainId;
 
     DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
     CREATE TEMPORARY TABLE temp_AvailableState AS
     SELECT  
         ST.ext,
         ST.domainId,
         CASE 
				WHEN a.statusName = 'Ready' THEN 1
				WHEN a.statusName = 'Not Ready' THEN 2
				WHEN a.statusName = 'Transfer Only' THEN 3
				WHEN a.statusName = 'Away' THEN 4
				WHEN a.statusName = 'Busy' THEN 5
				WHEN a.statusName = 'Offline' THEN 6
             ELSE 7 
         END AS tt_Time,
          IFNULL( ROUND(ST.stateDuration/1000) , ROUND((v_CurrentTimestamp - ST.startTimestamp)/1000)) as SD,
         DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d') AS startTimestamp
     FROM state_timer ST 
     JOIN agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
		WHERE ST.domainId = p_domainId AND ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;
       
       
     
     DROP TEMPORARY TABLE IF EXISTS tt_availability_cal;
     CREATE TEMPORARY TABLE tt_availability_cal AS 
     SELECT  
 		ext,
         startTimestamp,
         SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS ready,
         SUM(CASE WHEN tt_Time = 2 THEN SD ELSE 0 END) AS notReady,
         SUM(CASE WHEN tt_Time = 3 THEN SD ELSE 0 END) AS transferOnly,
         SUM(CASE WHEN tt_Time = 4 THEN SD ELSE 0 END) AS away,
         SUM(CASE WHEN tt_Time = 5 THEN SD ELSE 0 END) AS busyTime,
		 SUM(CASE WHEN tt_Time = 7 THEN SD ELSE 0 END) AS custom,
         SUM(CASE WHEN tt_Time IN(1,2,3,4,5,6,7) THEN SD ELSE 0 END) AS totalLoggedInDuration,
         domainId
     FROM temp_AvailableState 
     GROUP BY ext,startTimestamp,domainId;
     
     
     
     
     DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory_cal_final;
     CREATE TEMPORARY TABLE tt_logInSessionHistory_cal_final AS
     SELECT AC.startTimestamp AS createdAt,
         U.UserName AS AgentName,
         U.UserID AS AgentId,
         AC.ext,
         AC.totalLoggedInDuration AS LoggedinDuration,
         AC.startTimestamp,
         AC.ready,
         AC.notReady,
         AC.transferOnly,
         AC.away,
         AC.busyTime,
         AC.custom
     FROM  tt_availability_cal 	AC
     JOIN  tb_User 				U ON U.ext = AC.ext AND U.domainId = AC.domainId
     WHERE (IFNULL(p_agentId,'')='' OR U.UserID IN (SELECT agentId FROM temp_agentId));
     
     
     
 	SELECT * FROM temp_AllagentId;
 
     SELECT 	COUNT(1) v_Total_Count
		FROM 	tt_logInSessionHistory_cal_final a;
 	
	IF ((p_Offset IS NOT NULL )AND(p_limit IS NOT NULL))THEN

     SELECT 
         createdAt 														AS date
			,AgentName 													AS agentName
			,AgentId
			,LoggedinDuration											AS totalLoggedinTime
			,ready 														AS ready
			,ROUND((ready/ LoggedinDuration) * 100) 					AS readyper
			,notReady													AS notReady
			,ROUND((notReady / LoggedinDuration) * 100) 				AS notReadyper
			,transferOnly												AS transferOnly
			,ROUND((transferOnly / LoggedinDuration) * 100) 			AS transferOnlyper
			,away														AS away
			,ROUND((away / LoggedinDuration) * 100) 					AS awayper
			,busyTime													AS busyTime
			,ROUND((busyTime / LoggedinDuration) * 100) 				AS busyTimeper
			,custom														AS customState
			,ROUND((custom / LoggedinDuration) * 100) 					AS customStateper
     FROM tt_logInSessionHistory_cal_final
     ORDER BY createdAt DESC
     LIMIT v_offset, p_limit;
     
     ELSE
		
       SELECT 
         createdAt 														AS date
			,AgentName 													AS agentName
			,AgentId
			,LoggedinDuration											AS totalLoggedinTime
			,ready 														AS ready
			,ROUND((ready/ LoggedinDuration) * 100) 					AS readyper
			,notReady													AS notReady
			,ROUND((notReady / LoggedinDuration) * 100) 				AS notReadyper
			,transferOnly												AS transferOnly
			,ROUND((transferOnly / LoggedinDuration) * 100) 			AS transferOnlyper
			,away														AS away
			,ROUND((away / LoggedinDuration) * 100) 					AS awayper
			,busyTime													AS busyTime
			,ROUND((busyTime / LoggedinDuration) * 100) 				AS busyTimeper
			,custom														AS customState
			,ROUND((custom / LoggedinDuration) * 100) 					AS customStateper
     FROM tt_logInSessionHistory_cal_final
		ORDER BY createdAt DESC;
        
	END IF;
 
 END ;;
DELIMITER ;
