CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentStatusTracker`( p_sessionId varchar(250)
 ,p_domainId int
 )
begin 
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    
    DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
	CREATE TEMPORARY TABLE temp_customer_contact
    SELECT 	coid,phoneNumber,firstName,lastName      
    FROM 	customer_contact 
    WHERE 	domainId = p_domainId;
    
	select   q.name 								as queueName
			 ,u.UserName 							as agentName
			 ,	CASE WHEN c.coid IS NOT NULL THEN CONCAT(c.firstName,' ',c.lastName) 
					 ELSE (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT( '%',a.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)	
				END AS customerName
			 ,a.domainId
			 ,b.AgentId
			 ,b.QueueId
			 ,b.transferredTypeId
			 ,b.transferedBy
			 ,b.transferedTo  
	FROM tb_CallHistory 		a 
	JOIN tb_CallDurationHistory b ON a.CallHistoryId = b.CallHistoryId 
	JOIN queue 					q ON b.QueueId 	= q.qid
	JOIN tb_User 				u ON u.UserID 	= b.AgentId
	LEFT JOIN customer_contact 	c ON c.primaryPhoneNumber LIKE a.customerNumber 
								 and a.domainId = c.domainId
	WHERE 	sessionId 	= p_sessionId
	AND 	a.domainId	= p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
