CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getAgentStatusView`(
     p_domainId INT
 )
BEGIN
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
	CREATE TEMPORARY TABLE temp_customer_contact
    SELECT 	coid,phoneNumber,firstName,lastName      
    FROM 	customer_contact 
    WHERE 	domainId = p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
 
	 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     DROP TEMPORARY TABLE IF EXISTS tt_grpcall_1; 
     CREATE TEMPORARY TABLE tt_grpcall_1 AS
     SELECT
         u.UserName,
         q.name,
		 CASE 	WHEN c.coid IS NOT NULL THEN CONCAT(c.firstName,' ',c.lastName) 
				ELSE (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT( '%',a.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)	
		 END AS customerName,         
         aa.statusName,
         a.sessionStartTime,
         aa.statusName AS agentStatus,
         u.ext
     FROM tb_CallHistory a
     JOIN tb_CallDurationHistory b ON a.CallHistoryId = b.CallHistoryId
     JOIN queue q ON b.QueueId = q.qid
     JOIN tb_User u ON u.UserID = b.AgentId
     LEFT JOIN customer_contact c ON c.phoneNumber LIKE CONCAT('%', a.customerNumber, '%')
     JOIN agent_status aa ON aa.aid = u.StatusID
     WHERE a.domainId = p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
 
     WITH CTE AS ( SELECT
             UserName AS agentName,
             name AS queueName,
             customerName,
             (CASE WHEN statusName = 'Busy' THEN sessionStartTime ELSE null END ) AS sessionStartTime,
             statusName,
             ext,
             ROW_NUMBER() OVER (PARTITION BY UserName ORDER BY (sessionStartTime) DESC) AS RNK1
         FROM  tt_grpcall_1 )
 
     SELECT * FROM CTE WHERE RNK1 = 1;
 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
