CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getAllUserList_info`(p_domainId int,p_ext int)
Begin
        declare v_routing_profile_id int;
        declare v_quId varchar(250);
        
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	select 	b.statusName,a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.sipLoginId, a.companyId, a.domainId, a.ext
 			,a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession, 
 			
 			b.isVoice
 			,a.isVoiceCallTransfer, b.isChat, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
 			a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer,group_concat(qid) as quId,
 			b.isVoiceCallTransfer AS isVoiceCallTransfer_AgentStatus, b.isChatTransfer AS isChatTransfer_AgentStatus, b.isEmailTransfer AS isEmailTransfer_AgentStatus,
 			case 	when rp.routingMethod = 'Skill Based Routing' then 2 
 					when rp.routingMethod = 'Long wait time Based Routing' then 1 END as routingMethod
      	from tb_User 						a 
      	join agent_status 					b 	on a.StatusID 				= b.aid
      	left join routingqueueprofilemapping 	r 	on a.routing_profile_id		= r.rqmid 	and a.domainId = r.domainId
		left JOIN routing_profile 				rp	ON a.routing_profile_id 	= rp.rid 	and a.domainId = rp.domainId
      	where a.domainId =  p_domainId 
        and roleid in (3,5,6)
      	group by b.statusName,a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.sipLoginId, a.companyId, a.domainId, a.ext, 
    	a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession, a.isVoice, a.isVoiceCallTransfer, b.isChat, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
    	a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer,rp.routingMethod;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 	 
    End ;;
DELIMITER ;
