CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_GetblockCustomerReqCustomerDetails_info`(
   p_domainId int
)
Begin
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	select b.UserName as UserName
 		,	a.coid
 		,	a.firstName
 		,	a.lastName				
 		,	JSON_ARRAY_INSERT(a.phoneNumber,'$[0]',a.primaryPhoneNumber)	phoneNumber				
 		,	JSON_ARRAY_INSERT(a.email,'$[0]',a.primaryEmail)				email
 		,	a.accountNumber
 		,	a.tags
 		,	a.location
 		,	a.address
 		,	a.country
 		,	a.state
 		,	a.city
 		,	a.postalCode
 		,	a.facebook
 		,	a.instagram
 		,	a.whatsapp
 		,	a.twitter
 		,	a.createdAt
 		,	a.updatedAt
 		,	a.voiceBiometric
 		,	a.domainId
 		,	a.mergeCustomer
 		,	a.blockCustomer
 		,	a.doNotDisturb
 		,	a.blockCustomerReq
 		,	a.doNotDisturbReq
 		,	a.`type`
 		,	a.currentCustomerNumber
 		,	a.customerType
 		,	a.Timezone
 		,	a.blockedBy
 		,	a.doNotDisturbBy
 		,	a.blockedReqBy
 		,	a.doNotDisturbReqBy
 		,	a.Reason
 		,	a.cookiesId
 		,	a.`Source`
        ,	b.ext
     from customer_contact a 
     join tb_User b on a.blockedReqBy = b.UserID and a.domainId = b.domainId
     WHERE blockCustomerReq = 1 AND a.domainId = p_domainId
	 AND 	JSON_VALID(a.phoneNumber) = 1
	 AND 	JSON_VALID(a.email) = 1;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 End ;;
