CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getBotAction`(
	 p_pageId		VARCHAR(100)
    ,p_channelName 	VARCHAR(100)
)
begin
		IF p_channelName = 'Instagram'
        THEN
			SELECT isActive FROM tb_InstagramConfiguration  WHERE InstagramPageId = p_pageId;
		ELSEIF p_channelName = 'Facebook'
        THEN
			SELECT isActive FROM tb_FacebookConfiguration  WHERE FacebookPageId = p_pageId;
		ELSE 
			SELECT isDisabled FROM tb_WhatsappConfiguration  WHERE whatsappNumber = p_pageId;
		END IF;
end ;;
DELIMITER ;
