CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getcsatAgentFeedbackReport`(	
 p_startTmpstmp  		BIGINT,
 p_endTmpstmp    		BIGINT,
 p_timeZone 	  			VARCHAR(200),
 p_domainId      		INT,
 p_agentId       		TEXT,
 p_Limit         		INT,
 p_Offset        		INT
 
 )
Begin
 	declare p_customerFeedbackId	bigint;
     
     set p_customerFeedbackId = 0;
   	   
        set p_timeZone = '+05:30';
       
   			IF p_agentId IS NOT NULL  THEN
   				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
   				CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
   			ELSE
   				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
   				CREATE TEMPORARY TABLE temp_agentIds
   				select  UserID as agentId from tb_User where domainId = p_domainId;  
   			END IF;
       
       drop temporary table if exists tt_cust_feedback; 
       create temporary table tt_cust_feedback as
       select 
 				 `customerFeedbackId`, `historyId` , `channelTypeId` , `ratingType`, `satisfactionRate` ,
 				`domainId` , `AgentId` , `feedbackQuestionAnswer` , `createdDate` , `updatedDate`
       from tb_customerFeedback where createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000) and domainId = p_domainId;  
       
 	drop temporary table if exists tt_feedback_report; 
 	create temporary table tt_feedback_report
 	(
 		id int auto_increment primary key,
         customerFeedbackId bigint,
 		historyId BIGINT,
 		`Datetime` DATETIME,
 		channel VARCHAR(20),
 		customerName VARCHAR(150),
 		agentName VARCHAR(150),
 		UserID INT,
 		CSATQuestion JSON,
 		CSATscore INT,
         ratingType	int
 	);
       
   		INSERT INTO  tt_feedback_report (customerFeedbackId,historyId,`Datetime`,channel,customerName,agentName,UserID,CSATQuestion,CSATscore,ratingType)
   		SELECT 		CF.customerFeedbackId
 				,	CF.historyId
   				,	CF.createdDate AS `Datetime`
   				,	'Call' AS channel
   				,	CONCAT(CC.firstName,' ',CC.lastName) AS customerName
   				,	TU.UserName AS agentName
 				,	TU.UserID
   				,	feedbackQuestionAnswer AS CSATQuestion
   				,	satisfactionRate AS CSATscore
                 ,	CF.ratingType
   		FROM 	tt_cust_feedback 					CF 
   		LEFT JOIN 	tb_CallHistory 					CH ON CF.historyId		= CH.CallHistoryId 	AND CF.domainId = CH.domainId 
   		LEFT JOIN 	tb_CallDurationHistory			CD ON CH.CallHistoryId 	= CD.CallHistoryId     
   		LEFT JOIN 	customer_contact 				CC ON CC.domainId 		= CH.domainId 		AND CC.coid = CH.CustomerId 
   		LEFT JOIN 	tb_User							TU ON TU.UserID 		= CD.agentId 		AND TU.domainId = CH.domainId   
   		WHERE 	CH.domainId = p_domainId
   		AND 	CF.channelTypeId = '2003001';
       
   		INSERT INTO  tt_feedback_report (customerFeedbackId,historyId,`Datetime`,channel,customerName,agentName,UserID,CSATQuestion,CSATscore,ratingType)
   		SELECT 		CF.customerFeedbackId
 				,	CF.historyId
   				,	CF.createdDate AS `Datetime`
   				,	'Chat' AS channel
   				,	CONCAT(CC.firstName,' ',CC.lastName) AS customerName
   				,	TU.UserName AS agentName
 				,	TU.UserID
   				,	feedbackQuestionAnswer AS CSATQuestion
   				,	satisfactionRate AS CSATscore
                 ,	CF.ratingType
   		FROM 	tt_cust_feedback 					CF 
   		LEFT JOIN 	tb_ChatHistory 					CH ON CF.historyId		= CH.ChatHistoryId 	AND CF.domainId = CH.domainId 
   		LEFT JOIN 	tb_ChatDurationHistory			CD ON CH.ChatHistoryId 	= CD.ChatHistoryId     
   		LEFT JOIN 	customer_contact 				CC ON CC.domainId 		= CH.domainId 		AND CC.coid 	= CH.CustomerId 
   		LEFT JOIN 	tb_User							TU ON TU.UserID 		= CD.AgentId 		AND TU.domainId = CH.domainId   
   		WHERE 	CH.domainId = p_domainId
   		AND 	CF.channelTypeId = '2003002';
           
   		INSERT INTO  tt_feedback_report (customerFeedbackId,historyId,`Datetime`,channel,customerName,agentName,UserID,CSATQuestion,CSATscore,ratingType)
   		SELECT 	CF.customerFeedbackId
 				,	CF.historyId
   				,	CF.createdDate AS `Datetime`
   				,	'Email' AS channel
   				,	CONCAT(CC.firstName,' ',CC.lastName) AS customerName
   				,	TU.UserName AS agentName
 				,	TU.UserID
   				,	feedbackQuestionAnswer AS CSATQuestion
   				,	satisfactionRate AS CSATscore
                 ,	CF.ratingType
