   		LEFT JOIN 	tb_User							TU ON TU.UserID 		= CD.AgentId 			AND TU.domainId = CH.domainId   
   		WHERE 	CH.domainId = p_domainId
   		AND 	CF.channelTypeId = '2003004';
   
   		INSERT INTO  tt_feedback_report (customerFeedbackId,historyId,`Datetime`,channel,customerName,agentName,UserID,CSATQuestion,CSATscore,ratingType)
