   		LEFT JOIN 	customer_contact 					CC ON CC.domainId 		= CH.domainId 				AND CC.Instagram 	= CH.customerInstagramId 
   		LEFT JOIN 	tb_User								TU ON TU.UserID 		= CH.AgentId 				AND TU.domainId = CH.domainId   
   		WHERE 	CH.domainId = p_domainId
   		AND 	CF.channelTypeId = '2003007';
           
   		INSERT INTO  tt_feedback_report (customerFeedbackId,historyId,`Datetime`,channel,customerName,agentName,UserID,CSATQuestion,CSATscore,ratingType)
   		 SELECT 	CF.customerFeedbackId
 				,	CF.historyId
   				,	CF.createdDate AS `Datetime`
   				,	'Videomeet' AS channel
   				,	CONCAT(CC.firstName,' ',CC.lastName) AS customerName
   				,	TU.UserName AS agentName
 				,	TU.UserID
   				,	feedbackQuestionAnswer AS CSATQuestion
   				,	satisfactionRate AS CSATscore
                 ,	CF.ratingType
   		FROM 	tt_cust_feedback 						CF 
   		LEFT JOIN 	tb_VideoHistory 					CH ON CF.historyId		= CH.VideoHistoryId 		AND CF.domainId = CH.domainId 
   		LEFT JOIN 	tb_VideoDurationHistory				CD ON CH.VideoHistoryId = CD.VideoHistoryId     
   		LEFT JOIN 	customer_contact 					CC ON CC.domainId 		= CH.domainId 				AND CC.primaryPhoneNumber 	= CH.customerNumber 
   		LEFT JOIN 	tb_User								TU ON TU.UserID 		= CD.AgentId 				AND TU.domainId = CH.domainId   
   		WHERE 	CH.domainId = p_domainId
   		AND 	CF.channelTypeId = '2003008';
           
           select customerFeedbackId,historyId,`Datetime` as dateTime,channel,TRIM(if(customerName='',null,customerName)) as customerName ,agentName,UserID,CSATQuestion,CSATscore , ratingType
           from tt_feedback_report
           where	(UserID in (select Distinct agentId from temp_agentIds) or ifnull(p_agentId,'')='')
           AND (customerFeedbackId = p_customerFeedbackId or ifnull(p_customerFeedbackId,0)=0);
       
       
   End ;;
