		LEFT JOIN 	tb_WhatsappHistory 					CH ON CF.historyId		= CH.WhatsappHistoryId 		AND CF.domainId = CH.domainId 
		LEFT JOIN 	tb_WhatsappDurationHistory			CD ON CH.WhatsappHistoryId 	= CD.WhatsappHistoryId     
