CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomerConatct`(	
      	p_domainId 			INT
      	,p_newCustomer		TINYINT
      	,p_limit			INT
      	,p_offset			INT
      	,p_search			VARCHAR(250)
      	,p_customerType  	VARCHAR(1500)
		,p_dynamicColumns	VARCHAR(1000)	
      	)
SP : BEGIN  	
      	DECLARE v_DB				VARCHAR(20);	
      	DECLARE v_Date				DATE;
      	DECLARE v_offset			INT;
      	DECLARE v_limit				INT;
      	DECLARE v_Tcount			INT;
      	DECLARE v_TCondCount		INT;
      	DECLARE v_search			VARCHAR(260);
      	DECLARE v_customerType		VARCHAR(1500);
      	DECLARE v_dynamicSearch		VARCHAR(265);
  		DECLARE v_dynamicColumns	TEXT;
          
        SET v_Tcount = (SELECT COUNT(coid) FROM customer_contact WHERE domainId = p_domainId);     
          
      	IF p_limit IS NULL THEN 
      		SET v_limit = 1000; 
      	ELSE 
      		SET v_limit = p_limit;
      	END IF;
      	 
      	SET v_offset =  v_limit * p_offset;   
          
      	IF p_search IS NULL THEN
      		SET v_search = "%";
      	 ELSE 
      		SET v_search = CONCAT("%",p_search,"%");
      	 END IF;    
      	 
      	 SET v_dynamicSearch = CONCAT("'",v_search,"'");
          
