CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getCustomerConatctDetails`(
       p_coid 	INT,
       p_domainId  INT
       )
sp_return : begin
 		DECLARE v_DB	VARCHAR(20);	
        
 		SET v_DB = DATABASE();
        
    	if p_coid is null or p_domainId is null 
        then 
    		select -1 as errcode, 'coid or domainId should not be null' as errmsg;
    		leave sp_return;
    	End if;    
        
    	IF EXISTS(SELECT 1 FROM information_schema.tables where TABLE_SCHEMA = v_DB and TABLE_NAME = concat('customer_contact_',p_domainid) limit 1) 
        THEN
    		SET @Q =  CONCAT("SELECT firstName,	lastName ,IF(IFNULL(primaryPhoneNumber,'')='',phoneNumber,JSON_ARRAY_INSERT(phoneNumber,'$[0]',primaryPhoneNumber)) phoneNumber
  						,IF(IFNULL(primaryEmail,'')='',email,JSON_ARRAY_INSERT(email,'$[0]',primaryEmail)) email,accountNumber,tags,location,address,country,state,city,postalCode
 						,facebook,instagram,whatsapp,twitter,voiceBiometric,A.domainId,mergeCustomer,blockCustomer,doNotDisturb,blockCustomerReq,doNotDisturbReq,type
                         ,currentCustomerNumber,customerType,Timezone,blockedBy,doNotDisturbBy,blockedReqBy,doNotDisturbReqBy
    						,Reason,cookiesId,Source,A.attachments,B.*,A.coid FROM customer_contact A LEFT JOIN customer_contact_",p_domainId," B ON A.coid = B.coid 
                         where A.coid = ",p_coid," AND A.domainId = ",p_domainId," AND JSON_VALID(A.phoneNumber) = 1 AND JSON_VALID(A.email) = 1 order by A.coid desc;");
            
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    		PREPARE Q FROM @Q;
    		EXECUTE Q;
    		DEALLOCATE PREPARE Q;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    	ELSE 
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		SELECT 	coid
    				,firstName
    				,lastName				
    				,IF(IFNULL(primaryPhoneNumber,'')='',phoneNumber, JSON_ARRAY_INSERT(phoneNumber,'$[0]',primaryPhoneNumber))	phoneNumber				
    				,IF(IFNULL(primaryEmail,'')='',email,JSON_ARRAY_INSERT(email,'$[0]',primaryEmail))							email
    				,accountNumber
    				,tags
    				,location
    				,address
    				,country
    				,state
    				,city
    				,postalCode
    				,facebook
    				,instagram
    				,whatsapp
    				,twitter
    				,createdAt
    				,updatedAt
    				,voiceBiometric
    				,domainId
    				,mergeCustomer
    				,blockCustomer
    				,doNotDisturb
    				,blockCustomerReq
    				,doNotDisturbReq
    				,type
    				,currentCustomerNumber
    				,customerType
    				,Timezone
    				,blockedBy
    				,doNotDisturbBy
    				,blockedReqBy
    				,doNotDisturbReqBy
    				,Reason
    				,cookiesId
    				,Source
                    ,attachments
    		FROM 	customer_contact 
    		WHERE 	coid 		= p_coid 
    		AND 	domainId 	= p_domainId
         AND 	JSON_VALID(phoneNumber) 	= 1
 		AND 	JSON_VALID(email) 			= 1;
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    	END IF; 
     end ;;
