/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomerConatct_filter_v2`(	
   	p_domainId 		INT
   	,p_newCustomer	TINYINT
    ,p_search		VARCHAR(500)
    ,p_customerTag	VARCHAR(150)
    ,p_limit 		INT
    ,p_offset		INT
   )
BEGIN  	
      DECLARE v_DB		VARCHAR(20);	
      DECLARE v_Date	DATETIME;
      DECLARE v_offset	INT;
      
      SET v_offset = p_limit * p_offset;
	
      SET v_DB 	= DATABASE();   
      SET v_Date = DATE_SUB(NOW(), INTERVAL 30 DAY);
      
      DROP TEMPORARY TABLE IF EXISTS temp_CustomerContact;
      CREATE TEMPORARY TABLE temp_CustomerContact(coid	BIGINT PRIMARY KEY);
      
      IF p_newCustomer = 1
      THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   		INSERT INTO temp_CustomerContact
   		SELECT 	CC.coid	 
   		FROM 	customer_contact CC
   		WHERE 	CC.domainId 	= p_domainId
   		AND 	CC.createdAt	> v_Date
 		AND 	IFNULL(CC.blockCustomer,0)	= 0
        AND 	JSON_VALID(phoneNumber) 	= 1
		AND 	JSON_VALID(email) 			= 1;
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 	ELSEIF p_newCustomer = 0
 	THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   		INSERT INTO temp_CustomerContact
   		SELECT 	CC.coid	 
   		FROM 	customer_contact CC
   		WHERE 	CC.domainId 	= p_domainId
   		AND 	CC.createdAt	< v_Date
 		AND 	IFNULL(CC.blockCustomer,0)	= 0
        AND 	JSON_VALID(phoneNumber) 	= 1
		AND 	JSON_VALID(email) 			= 1;
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       ELSEIF p_newCustomer IS NULL
       THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   		INSERT INTO temp_CustomerContact
   		SELECT 	CC.coid	 
   		FROM 	customer_contact CC
   		WHERE 	CC.domainId 			= p_domainId
         AND 	JSON_VALID(phoneNumber) = 1
		AND 	JSON_VALID(email) 		= 1
        AND		CC.blockCustomer = 0 
        AND		CC.doNotDisturb = 0;
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       END IF;   
       
       SET @record_count = 0;
       
 		IF EXISTS(SELECT 1 FROM information_schema.tables where TABLE_SCHEMA = v_DB and TABLE_NAME = concat('customer_contact_',p_domainid) limit 1) 
 		THEN

      		SET @Q = CONCAT(" 
				SELECT 
					A.firstName, A.lastName, 
					A.primaryPhoneNumber AS phoneNumber, 
					A.primaryEmail AS email, 
					A.accountNumber, A.tags, A.location, A.address, 
					A.country, A.state, A.city, A.postalCode, 
					A.facebook, A.instagram, A.whatsapp, A.twitter, 
					A.voiceBiometric, A.domainId, A.mergeCustomer, A.blockCustomer,
					A.doNotDisturb, A.blockCustomerReq, A.doNotDisturbReq, 
					A.type, A.currentCustomerNumber, A.customerType, 
					A.Timezone, A.blockedBy, A.doNotDisturbBy, 
					A.blockedReqBy, A.doNotDisturbReqBy, A.Reason, 
					A.cookiesId, A.Source, B.*, t_CC.coid 
				FROM temp_CustomerContact t_CC 
				JOIN customer_contact A ON t_CC.coid = A.coid 
				LEFT JOIN customer_contact_", p_domainId, " B ON A.coid = B.coid 
				WHERE ('",p_search,"' = '' 
					OR A.firstName LIKE CONCAT('%', '",p_search,"', '%') 
					OR A.lastName LIKE CONCAT('%', '",p_search,"', '%') 
					OR A.primaryPhoneNumber LIKE CONCAT('%', '",p_search,"', '%') 
					OR A.primaryEmail LIKE CONCAT('%', '",p_search,"', '%'))
                AND (customerType LIKE '%", REPLACE(p_customerTag, ',', "%' OR customerType LIKE '%"), "%')
				ORDER BY A.coid DESC
				LIMIT ",v_offset,",",p_limit,";");

     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
      		PREPARE Q FROM @Q;
      		EXECUTE Q;
      		DEALLOCATE PREPARE Q;
            
			SET @Q = CONCAT("
				SELECT COUNT(*) INTO @record_count 
				FROM temp_CustomerContact t_CC 
				JOIN customer_contact A ON t_CC.coid = A.coid 
				LEFT JOIN customer_contact_", p_domainId, " B ON A.coid = B.coid 
				WHERE ('",p_search,"' = '' 
					OR A.firstName LIKE CONCAT('%', '",p_search,"', '%') 
					OR A.lastName LIKE CONCAT('%', '",p_search,"', '%') 
					OR A.primaryPhoneNumber LIKE CONCAT('%', '",p_search,"', '%') 
					OR A.primaryEmail LIKE CONCAT('%', '",p_search,"', '%'))
				AND (customerType LIKE '%", REPLACE(p_customerTag, ',', "%' OR customerType LIKE '%"), "%')
			");

			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
			PREPARE Q FROM @Q;
			EXECUTE Q;
			DEALLOCATE PREPARE Q; 
            
   		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      	ELSE 
      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            
      		SELECT 	t_CC.coid
     				,firstName
     				,lastName				
      				
      				
                    ,A.primaryPhoneNumber as phoneNumber
                    ,A.primaryEmail as email
     				,accountNumber
     				,tags
     				,location
     				,address
     				,country
     				,state
     				,city
     				,postalCode
     				,facebook
     				,instagram
     				,whatsapp
     				,twitter
     				,createdAt
     				,updatedAt
     				,voiceBiometric
     				,domainId
     				,mergeCustomer
     				,blockCustomer
     				,doNotDisturb
     				,blockCustomerReq
     				,doNotDisturbReq
     				,type
     				,currentCustomerNumber
     				,customerType
     				,Timezone
     				,blockedBy
     				,doNotDisturbBy
     				,blockedReqBy
     				,doNotDisturbReqBy
     				,Reason
     				,cookiesId
     				,Source
 			FROM 	temp_CustomerContact 	t_CC 
 			JOIN 	customer_contact 		A 		ON t_CC.coid = A.coid 
 			WHERE 	domainId = p_domainId 
            AND 	JSON_VALID(phoneNumber) 	= 1
			AND 	JSON_VALID(email) 			= 1
            
            AND 	(p_search = '' 
					OR A.firstName LIKE CONCAT('%', p_search, '%') 
					OR A.lastName LIKE CONCAT('%', p_search, '%') 
					OR A.primaryPhoneNumber LIKE CONCAT('%', p_search, '%') 
					OR A.primaryEmail LIKE CONCAT('%', p_search, '%'))
			AND (IFNULL(p_customerTag,'')='' OR A.tags like CONCAT('%',p_customerTag,'%'))
 			ORDER BY coid DESC
            LIMIT v_offset,p_limit;
            
            SELECT 	COUNT(*) INTO @record_count
 			FROM 	temp_CustomerContact 	t_CC 
 			JOIN 	customer_contact 		A 		ON t_CC.coid = A.coid 
 			WHERE 	domainId = p_domainId 
            AND 	JSON_VALID(phoneNumber) 	= 1
			AND 	JSON_VALID(email) 			= 1
            
            AND 	(p_search = '' 
					OR A.firstName LIKE CONCAT('%', p_search, '%') 
					OR A.lastName LIKE CONCAT('%', p_search, '%') 
					OR A.primaryPhoneNumber LIKE CONCAT('%', p_search, '%') 
					OR A.primaryEmail LIKE CONCAT('%', p_search, '%'))
			AND (IFNULL(p_customerTag,'')='' OR A.tags like CONCAT('%',p_customerTag,'%')); 
      	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      	END IF;
               
		select id,domainId,customerTypeName,description,isStatus,createdAt,updatedAt,FieldType
		from tb_ccaas_customer_type_dtl 
		where domainId = p_domainId
		order by FieldType desc;
        
        SELECT @record_count AS totalCount;
        
	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomerContactPhoneNumber_info` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getCustomerContactPhoneNumber_info`(
   p_phoneNumber varchar(150),
   p_domainId int
   )
Begin
 	DECLARE v_coid		BIGINT;
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
 	CREATE TEMPORARY TABLE temp_customer_contact
     SELECT 	coid, primaryPhoneNumber, phoneNumber, primaryEmail, email
     FROM 	customer_contact 
     WHERE 	domainId = p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
     SELECT 	coid INTO v_coid
     FROM 	temp_customer_contact
     WHERE 	primaryPhoneNumber 	= p_phoneNumber 
     OR 		primaryEmail		= p_phoneNumber
     ORDER BY coid LIMIT 1;
     
     IF v_coid IS NULL
     THEN
 		SELECT 	coid INTO v_coid
 		FROM 	temp_customer_contact
 		WHERE 	(phoneNumber LIKE concat('%',p_phoneNumber,'%') OR email like concat('%',p_phoneNumber,'%'))
         ORDER BY coid LIMIT 1;
     END IF;
     
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	a.coid
 		,	a.firstName
 		,	a.lastName				
 		,	JSON_ARRAY_INSERT(a.phoneNumber,'$[0]',a.primaryPhoneNumber)	phoneNumber				
 		,	JSON_ARRAY_INSERT(a.email,'$[0]',a.primaryEmail)				email
 		,	a.accountNumber
 		,	a.tags
 		,	a.location
 		,	a.address
 		,	a.country
 		,	a.state
 		,	a.city
 		,	a.postalCode
 		,	a.facebook
 		,	a.instagram
 		,	a.whatsapp
 		,	a.twitter
 		,	a.createdAt
 		,	a.updatedAt
 		,	a.voiceBiometric
 		,	a.domainId
 		,	a.mergeCustomer
 		,	a.blockCustomer
 		,	a.doNotDisturb
 		,	a.blockCustomerReq
 		,	a.doNotDisturbReq
 		,	a.`type`
 		,	a.currentCustomerNumber
 		,	a.customerType
 		,	a.Timezone
 		,	a.blockedBy
 		,	a.doNotDisturbBy
 		,	a.blockedReqBy
 		,	a.doNotDisturbReqBy
 		,	a.Reason
 		,	a.cookiesId
 		,	a.`Source` 
 	FROM 	customer_contact a
    WHERE 	coid = v_coid
    AND 	JSON_VALID(phoneNumber) 	= 1
	AND 	JSON_VALID(email) 			= 1;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomerLastIntraction` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomerLastIntraction`(
     p_CustomerId INT,
     p_domainId   INT
)
BEGIN
    SELECT historyId,
           sessionId,
           chanelType,
           IF(isBot = 1, 'Automatic', agentName) AS agentName,
           lastUpdatedAt,
           message
    FROM (
        
        SELECT CH.CallHistoryId AS historyId,
               CH.sessionId,
               'Call' AS chanelType,
               CM.updatedAt AS lastUpdatedAt,
               CM.Message AS message,
               U.UserName AS agentName,
               CDH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'Call' ORDER BY CM.CallDurationHistoryId DESC) AS rn
        FROM tb_CallHistory CH
        JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
        JOIN tb_CallMessage CM ON CH.CallHistoryId = CM.CallHistoryId
        LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId

        UNION ALL
        
        SELECT CH.ChatHistoryId,
               CH.sessionId,
               'Chat',
               CM.updatedAt,
               CM.Message,
               U.UserName,
               CDH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'Chat' ORDER BY CM.ChatDurationHistoryId DESC)
        FROM tb_ChatHistory CH
        JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
        JOIN tb_ChatMessage CM ON CH.ChatHistoryId = CM.ChatHistoryId
        LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId

        UNION ALL
        
        SELECT CH.EmailHistoryId,
               CH.sessionId,
               'Email',
               CM.updatedAt,
               CM.Message,
               U.UserName,
               CDH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'Email' ORDER BY CM.updatedAt DESC)
        FROM tb_EmailHistory CH
        JOIN tb_EmailDurationHistory CDH ON CH.EmailHistoryId = CDH.EmailHistoryId
        JOIN tb_EmailMessage CM ON CH.EmailHistoryId = CM.EmailHistoryId
        LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId

        UNION ALL
        
        SELECT CH.SMSHistoryId,
               CH.sessionId,
               'SMS',
               CM.updatedAt,
               CM.Message,
               U.UserName,
               CDH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'SMS' ORDER BY CM.updatedAt DESC)
        FROM tb_SMSHistory CH
        JOIN tb_SMSDurationHistory CDH ON CH.SMSHistoryId = CDH.SMSHistoryId
        JOIN tb_SMSMessage CM ON CH.SMSHistoryId = CM.SMSHistoryId
        LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId

        UNION ALL
        
        SELECT CH.WhatsappHistoryId,
               CH.sessionId,
               'Whatsapp',
               CM.updatedAt,
               CM.Message,
               U.UserName,
               CDH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'Whatsapp' ORDER BY CM.updatedAt DESC)
        FROM tb_WhatsappHistory CH
        JOIN tb_WhatsappDurationHistory CDH ON CH.WhatsappHistoryId = CDH.WhatsappHistoryId
        JOIN tb_WhatsappMessage CM ON CH.WhatsappHistoryId = CM.WhatsappHistoryId
        LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId

        UNION ALL
        
        SELECT CH.FacebookHistoryId,
               CH.sessionId,
               'Facebook',
               CM.updatedAt,
               CM.Message,
               U.UserName,
               CH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'Facebook' ORDER BY CM.updatedAt DESC)
        FROM tb_FacebookHistory CH
        JOIN tb_FacebookMessage CM ON CH.FacebookHistoryId = CM.FacebookHistoryId
        LEFT JOIN tb_User U ON U.UserID = CH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId

        UNION ALL
        
        SELECT CH.InstagramHistoryId,
               CH.sessionId,
               'Instagram',
               CM.updatedAt,
               CM.Message,
               U.UserName,
               CH.IsBot,
               ROW_NUMBER() OVER (PARTITION BY 'Instagram' ORDER BY CM.updatedAt DESC)
        FROM tb_InstagramHistory CH
        JOIN tb_InstagramMessage CM ON CH.InstagramHistoryId = CM.InstagramHistoryId
        LEFT JOIN tb_User U ON U.UserID = CH.AgentId
        WHERE CH.domainId = p_domainId
		AND CH.CustomerId = p_CustomerId
    ) AS all_channels
    WHERE rn = 1
    ORDER BY lastUpdatedAt DESC
    LIMIT 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomReport_Agent` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomReport_Agent`( 
	p_startTmpstmp	BIGINT,
	p_endTmpstmp	BIGINT,
	p_domainId		INT,
    p_timeZone 	  	VARCHAR(200),
    p_agentId      	TEXT,
    p_columnName	TEXT,
	p_Limit			INT,
	p_Offset		INT,
    p_lastIsertId	INT
)
begin
 			DECLARE v_offset 					INT;
			DECLARE v_startTmpstmp 				BIGINT;
			DECLARE v_endTmpstmp 				BIGINT;
			DECLARE p_channelType 	            VARCHAR(255);
            DECLARE v_overAllavailableTime 	    BIGINT;
            DECLARE v_totalCSAT 	    		INT;
            
                DECLARE json_result TEXT;

                        
			SET p_channelType = 'Chat,Call,Email,Sms,Whatsapp';
 		  
 			SET v_offset = p_Limit * p_offset; 
 
 			IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
 			IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
 			  
 			 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
			CREATE TEMPORARY TABLE temp_AllagentId 
			select UserID,UserName,ext,domainId from tb_User where domainId = p_domainId;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 				  
 			  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			  DROP TEMPORARY TABLE IF EXISTS temp_AllroutingId;
 			  CREATE TEMPORARY TABLE temp_AllroutingId
 			  select rid,name from routing_profile where domainId = p_domainId;
 			  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 				  
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
 			CREATE TEMPORARY TABLE tt_temp_sessionHistory  		AS
 				SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(CH.sessionStartTime /1000) AS DATE))*1000 as SessionDate
 				,AA.UserName												AS AgentName
 				,AA.UserID
 				,AR.name													AS RoutingProfile
 				
                ,((CDH.EndTime - CDH.StartTime) - CDH.AgentHoldDuration) 	AS CallHandlingTime
 				,CDH.StartTime												AS AnsweredCall
 				,CDH.transferredTypeId										AS transferredTypeId
 				,CH.callDuration											AS agentDuration
 				,CH.IsInBound
 				,CDH.AgentHoldDuration										AS agentHoldDuration
 				,CDH.afterCallWorkTime										AS afterCallWorkTime
 				,CH.CallHistoryId
 				,CDH.transferedBy											AS transferedBy
 				FROM 	tb_CallHistory CH
 				JOIN 	tb_CallDurationHistory	CDH	ON CH.CallHistoryId = CDH.CallHistoryId
 				JOIN 	tb_User					U	ON U.domainId	= CH.domainId
 													AND U.UserID = CDH.AgentId                 
 				LEFT JOIN temp_AllagentId 		AA	ON AA.UserID = CDH.AgentId
 				LEFT JOIN temp_AllroutingId		AR	ON AR.rid	 = U.routing_profile_id
 				WHERE 	CH.domainId 			= p_domainId 		
 				AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp ;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                       
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
 				DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory_1; 
 				CREATE TEMPORARY TABLE tt_temp_sessionHistory_1 AS   
 				SELECT 
 					distinct(CallHistoryId) as CallHistoryId,UserID,
 					AgentName, RoutingProfile, CallHandlingTime, AnsweredCall, transferredTypeId, agentDuration, IsInBound, agentHoldDuration, afterCallWorkTime,transferedBy
 					FROM tt_temp_sessionHistory;
                 
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 				DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
 				CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
 				SELECT 	 
 					SH.UserID  				                  
 					,SH.agentName 
 					,SH.RoutingProfile
 					,(CASE WHEN SH.CallHandlingTime>0 and SH.IsInBound = 1  THEN sum((SH.CallHandlingTime/1000 +SH.agentHoldDuration/1000)+SH.afterCallWorkTime)  ELSE 0 END)	            AS TotalAmountOfTimeInbound
 					,(CASE WHEN SH.CallHandlingTime>0 and SH.IsInBound = 0  THEN sum((SH.CallHandlingTime/1000 +SH.agentHoldDuration/1000) +SH.afterCallWorkTime)  ELSE 0 END) 	        AS TotalAmountOfTimeOutbound
 					,sum(CASE WHEN SH.AnsweredCall>0 THEN 1 ELSE 0 END ) 													AS AnsweredCall
 					                 
 					,SUM(CASE WHEN SH.transferedBy > 0 THEN 1 ELSE 0 END)														AS	NoOfCallTransferred 
 					,SUM(CASE WHEN SH.CallHandlingTime > 0 THEN SH.CallHandlingTime ELSE 0 END) 								AS totalTalktime
 					,SUM(CASE WHEN SH.CallHandlingTime > 0 THEN SH.CallHandlingTime ELSE 0 END) 								AS callHandlingTime
 					,SUM(CASE WHEN SH.IsInBound = 1 THEN 1 ELSE 0 END) 															AS receivedCall
 					,SUM(CASE WHEN SH.IsInBound = 0 THEN 1 ELSE 0 END) 															AS outboundCall
 					,SUM(CASE WHEN SH.agentHoldDuration > 0 THEN 1 ELSE 0 END)													AS noOfCallHoldCount
 					,SUM(SH.agentHoldDuration)																					AS callHoldTime
 					,SUM(SH.afterCallWorkTime) 																					AS NoOfAfterCallWorkTime
 				FROM 	tt_temp_sessionHistory_1 SH
 				GROUP BY SH.UserID, SH.agentName, SH.RoutingProfile,SH.CallHandlingTime,SH.IsInBound;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 				DROP TEMPORARY TABLE IF EXISTS tt_temp_result_1; 
 				CREATE TEMPORARY TABLE tt_temp_result_1(
					UserID	bigint
					,agentName	varchar(255)
					,routingProfile	varchar(255)
					,inboundTime	decimal(65,4)
					,inboundCalls	decimal(45,0)
					,outboundTime	decimal(65,4)
					,outboundCalls	decimal(45,0)
					,transferredCalls	decimal(45,0)
					,totalCallHandlingTime	decimal(65,4)
					,averageCallHandlingTime	decimal(65,8)
					,totalTalkTime	decimal(65,4)
					,averageTalkTime	decimal(65,8)
					,TotalACWTime	decimal(54,0)
					,averageACW	decimal(58,4)
					,totalHoldTime	decimal(65,4)
					,averageHoldTime	decimal(65,8)
			);
 				INSERT INTO tt_temp_result_1(UserID,agentName,routingProfile,inboundTime,inboundCalls,outboundTime,outboundCalls,transferredCalls,totalCallHandlingTime,averageCallHandlingTime,totalTalkTime
				,averageTalkTime,TotalACWTime,averageACW,totalHoldTime,averageHoldTime)
                SELECT 
 					a.UserID 																													AS UserID,
 					a.agentName 																												AS agentName,
 					a.RoutingProfile																											AS routingProfile,
 					SUM(a.TotalAmountOfTimeInbound) 																							AS inboundTime,
 					SUM(a.receivedCall) 																										AS inboundCalls,
 					SUM(a.TotalAmountOfTimeOutbound) 																							AS outboundTime,
 					SUM(a.outboundCall) 																										AS outboundCalls,
 					SUM(a.NoOfCallTransferred) 																									AS transferredCalls,
 					SUM(a.TotalAmountOfTimeInbound + a.TotalAmountOfTimeOutbound) 																AS totalCallHandlingTime,
 					CASE WHEN SUM(a.AnsweredCall) = 0 THEN 0
 					ELSE SUM(a.TotalAmountOfTimeInbound + a.TotalAmountOfTimeOutbound) / SUM(a.AnsweredCall) 
 					END 																														AS averageCallHandlingTime,
 					SUM(a.totalTalktime) / 1000 																								AS totalTalkTime,
 					CASE WHEN SUM(CASE WHEN a.receivedCall < 1 THEN a.outboundCall ELSE a.receivedCall END) = 0 THEN 0
 					ELSE SUM(a.totalTalktime) / SUM(CASE WHEN a.receivedCall < 1 THEN a.outboundCall ELSE a.receivedCall END) / 1000 
 					END 																														AS averageTalkTime,
 					SUM(a.NoOfAfterCallWorkTime) 																								AS TotalACWTime,
 					CASE 
 					WHEN SUM(CASE WHEN a.receivedCall < 1 THEN a.outboundCall ELSE a.receivedCall END) = 0 THEN 0
 					ELSE SUM(a.NoOfAfterCallWorkTime) / SUM(CASE WHEN a.receivedCall < 1 THEN a.outboundCall ELSE a.receivedCall END) 
 					END 																														AS averageACW,
 					SUM(a.callHoldTime) / 1000 																									AS totalHoldTime,
 					CASE 
 					WHEN SUM(a.AnsweredCall) = 0 THEN 0
 					ELSE SUM(a.callHoldTime) / SUM(a.AnsweredCall) / 1000 
 					END 																														AS averageHoldTime
 				FROM tt_sessionHistory_calc a
 				GROUP BY a.UserID, a.agentName, a.RoutingProfile;

			IF IFNULL(p_channelType,0) = 0 	THEN SET p_channelType = 'Chat,Call,Email,Sms,Whatsapp'; END IF;  
		        
			DROP TEMPORARY TABLE IF EXISTS temp_agentId; 		CREATE TEMPORARY TABLE temp_agentId(agentId INT); 
			DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));

			CALL split(p_agentId,','); 	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
			CALL split(p_channelType, ','); 	INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;        
            
             
		DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
		CREATE TEMPORARY TABLE temp_AvailableStates AS
		SELECT   
		CASE 
			WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
			WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) or (isChat = 0) or (isEmail=0)  ) THEN 2
			ELSE 3 
			END AS tt_Time,
            ST.ext,
			ST.domainId,
			ST.stateDuration as SD,
            from_unixtime(ST.startTimestamp/1000)
		FROM     state_timer ST 
		JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
		WHERE    ST.domainId = p_domainId
		AND      ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;    
         
        SELECT SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END)
        INTO v_overAllavailableTime
		FROM temp_AvailableStates
        WHERE    domainId = p_domainId
		GROUP BY domainId;              
              
  				  DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list;
  				  CREATE TEMPORARY TABLE temp_getcallback_list (
                    SessionDate        DATETIME,
                    UserID             INT,
                    agentId            INT,
                    AgentName          VARCHAR(100),
                    IsInBound          INT,
                    dispositionName    VARCHAR(100),
                    dialDuration       INT,
                    waitDuration       INT,
                    chatDuration       INT,
                    callDuration       INT,
                    SMSDuration        INT,
                    WhatsappDuration   INT,
                 
                  
                     IsMissed     		INT,
                     HistoryId        BIGINT,
                    sessionEndTime     BIGINT,
                    sessionStartTime   BIGINT,
                    SentimentalScore   INT,
                    dispositionId      INT,
                    Duration           INT,
                    availableTime      BIGINT,
                    afterCallWorkTime  INT
                );

                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                 
                 IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Call' LIMIT 1) THEN
                     INSERT INTO temp_getcallback_list(
                         SessionDate, AgentId,UserID,AgentName, IsInBound, dispositionName, dialDuration, waitDuration, 
                         callDuration, HistoryId, sessionEndTime, sessionStartTime, SentimentalScore, dispositionId,Duration,afterCallWorkTime,IsMissed
                     )
                     SELECT 
                         FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate,
                         CDH.AgentId,
                         AA.UserID,
                          AA.UserName 					AS AgentName,         
                         CH.IsInBound,
                         DS.dispositionName,
                         
                         CDH.answeredDuration				AS dialDuration,  
                         CDH.answeredDuration				AS waitDuration,
                         CH.callDuration,
                         CH.CallHistoryId,
                         CH.sessionEndTime,
                         CH.sessionStartTime,
                         CDH.SentimentalScore,
                         CDH.dispositionId,
                         CDH.Duration,
                         CDH.afterCallWorkTime,
                         CDH.IsMissedCall  				AS IsMissed
                     FROM 
                         tb_CallHistory CH
                         JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
                         LEFT JOIN temp_AllagentId AA ON AA.UserID = CDH.AgentId
                         LEFT JOIN temp_agentId t_A ON AA.UserID = t_A.agentId
                         LEFT JOIN disposition_status DS ON DS.did = CDH.dispositionId AND CH.domainId = DS.domainId
                         LEFT JOIN logInSessionHistory LSH ON AA.ext = LSH.ext AND LSH.domainId = CH.domainId
                     WHERE 
                         CH.domainId = p_domainId
                         AND CDH.IsBot=0
                         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                         AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL));
                 END IF;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                 
                 IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Chat' LIMIT 1) THEN
                     INSERT INTO temp_getcallback_list(
                         SessionDate,AgentId,UserID, AgentName, IsInBound, dispositionName, dialDuration, chatDuration, 
                         HistoryId, sessionEndTime, sessionStartTime, SentimentalScore, dispositionId,Duration,afterCallWorkTime,waitDuration,IsMissed
                     )
                     SELECT 
                         FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate,
                         CDH.AgentId,          
                         AA.UserID,
                         AA.UserName AS AgentName,
                         CH.IsInBound,
                         DS.dispositionName,
                         
                         CDH.answeredDuration				AS dialDuration, 
                         CDH.Duration AS chatDuration,
                         CH.ChatHistoryId,
                         CH.sessionEndTime,
                         CH.sessionStartTime,
                         CDH.SentimentalScore,
                         CDH.dispositionId,
                         CDH.Duration,
                         CDH.afterChatWorkTime,
                         CDH.answeredDuration AS waitDuration,
                         
                         CDH.IsMissed
                     FROM 
                         tb_ChatHistory CH
                         JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
                         LEFT JOIN temp_AllagentId AA ON AA.UserID = CDH.AgentId
                         LEFT JOIN temp_agentId t_A ON AA.UserID = t_A.agentId
                         LEFT JOIN disposition_status DS ON DS.did = CDH.dispositionId AND CH.domainId = DS.domainId
                         LEFT JOIN logInSessionHistory LSH ON AA.ext = LSH.ext AND LSH.domainId = CH.domainId
                     WHERE 
                         CH.domainId = p_domainId         
                         AND CDH.IsBot=0
                         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                         AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL));
                 END IF;
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
               
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 		IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'SMS' LIMIT 1 )THEN
                  INSERT INTO temp_getcallback_list(SessionDate,AgentName,UserID,AgentId,IsInBound,dispositionName,waitDuration,SMSDuration,HistoryId,
 					sessionEndTime,sessionStartTime,SentimentalScore,dispositionId,Duration,afterCallWorkTime ,dialDuration)
                 SELECT FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate
 						,	AA.UserName				AS AgentName
 						,AA.UserID
 						,   CDH.AgentId  
 						,	CH.IsInBound
 						,	DS.dispositionName		
 						
 						,	CH.waitDuration
 						,	CDH.Duration             AS SMSDuration
 						,	CH.SMSHistoryId
 						,	CH.sessionEndTime
 						,	CH.sessionStartTime
 						,	CH.SentimentalScore
 						,	CH.dispositionId
 						,   CDH.Duration
 						,   CH.afterSMSWorkTime
                         ,	CASE WHEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt)<= P.smsThreshold * 3600 THEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt) ELSE 0 END AS dialDuration
 				FROM tb_SMSHistory 					CH        
 				JOIN tb_SMSDurationHistory			CDH	ON 	CH.SMSHistoryId = CDH.SMSHistoryId        
 				LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId 
 				AND CH.domainId = DS.domainId        
 				LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
 				LEFT JOIN temp_agentId 				t_A ON AA.UserID 		= t_A.agentId 
 				LEFT JOIN logInSessionHistory		LSH ON AA.ext			= LSH.ext 
 				and LSH.domainId = CH.domainId
 				left JOIN 	did_purchase				P	ON 	P.your_number	= CH.calledNumber AND	P.domainId		= CH.domainId
 				WHERE 	CH.domainId 			= p_domainId 		
 				AND 	CDH.IsBot=0
 				AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 				AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));
 				End if; 
                       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                                             
                      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 		IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'EMAIL' LIMIT 1 )THEN
                         INSERT INTO temp_getcallback_list(SessionDate,AgentName,UserID,AgentId,IsInBound,dispositionName,waitDuration,SMSDuration,HistoryId,sessionEndTime,
                                           sessionStartTime,SentimentalScore,dispositionId,Duration,afterCallWorkTime ,dialDuration) 
                       
                  SELECT FROM_UNIXTIME(CH.sessionStartTime / 1000) AS SessionDate
 						,	AA.UserName				AS AgentName
 						,    AA.UserID
 						,    CDH.AgentId
 						,	CH.IsInBound
 						,	DS.dispositionName		
 						
 						,	CH.waitDuration
 						,	CDH.Duration             AS SMSDuration
 						,	CH.EmailHistoryId
 						,	CH.sessionEndTime
 						,	CH.sessionStartTime
 						,	CH.SentimentalScore
 						,	CH.DispositionId
 						,   CDH.Duration
 						,   CH.AfterEmailWorkTime
                        ,	CASE WHEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt)<= ec.emailThreshold * 3600 AND CH.DispositionId is not null THEN TIMESTAMPDIFF(SECOND,CH.createdAt,CH.updatedAt) ELSE 0 END AS dialDuration
                           FROM tb_EmailHistory 			CH        
 				JOIN tb_EmailDurationHistory			CDH	ON 	CH.EmailHistoryId = CDH.EmailHistoryId        
 				LEFT JOIN disposition_status			DS 	ON DS.did			= CH.DispositionId  and CH.domainId = DS.domainId        
 				LEFT JOIN temp_AllagentId 				AA	ON AA.UserID 		= CDH.AgentId
 				LEFT JOIN temp_agentId 					t_A ON AA.UserID 		= t_A.agentId 
 				LEFT JOIN logInSessionHistory			LSH ON AA.ext			= LSH.ext  			and LSH.domainId = CH.domainId
 				LEFT JOIN email_config 					ec	ON	ec.emailAddress		= CH.ToEmail AND	ec.domainId 		= CH.domainId   
 				WHERE 	CH.domainId 			= p_domainId 
 				AND CDH.IsBot=0
 				AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 				AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));     
                            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                 	End if;       
                 
  					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  					IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Whatsapp' LIMIT 1 )
                    THEN
						INSERT INTO temp_getcallback_list(
                        SessionDate,AgentName,UserID,IsInBound,dispositionName,waitDuration,WhatsappDuration,HistoryId,sessionEndTime,
						sessionStartTime,SentimentalScore,dispositionId,Duration,afterCallWorkTime ,dialDuration)                         
                     SELECT FROM_UNIXTIME(CH.sessionStartTime / 1000)      AS SessionDate
 							,	AA.UserName								   AS AgentName 							
 							,   CDH.AgentId
 							,	CH.IsInBound
 							,	DS.dispositionName		
 							
 							,	0                                           AS waitDuration
 							,	CDH.Duration             					AS WhatsappDuration
 							,	CH.WhatsappHistoryId
 							,	CH.sessionEndTime
 							,	CH.sessionStartTime
 							,	CH.SentimentalScore
 							,	CH.dispositionId
 							,  	CDH.Duration
 							,  	CH.afterwhatsappWorkTime
 							,	CDH.dialDuration as dialDuration
						FROM tb_WhatsappHistory 			CH        
						JOIN tb_WhatsappDurationHistory		CDH	ON 	CH.WhatsappHistoryId = CDH.WhatsappHistoryId        
						left JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
						LEFT JOIN temp_agentId 				t_A ON AA.UserID 		= t_A.agentId 
						LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId and CH.domainId = DS.domainId
						LEFT JOIN logInSessionHistory		LSH ON AA.ext			= LSH.ext 
																and LSH.domainId 	= CH.domainId
						WHERE 	CH.domainId		= p_domainId 	
						AND     CDH.IsBot		= 0
						AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
						AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));     
						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
					End if;
                                 
                                 
                                 
  			UPDATE temp_getcallback_list SH_C
  			JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
  			JOIN (
  				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
  				FROM temp_AvailableStates
  				GROUP BY ext, domainId
  			) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
  			SET SH_C.availableTime = tt_AV.total_SD;

          				DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1; 
                		    CREATE TEMPORARY TABLE temp_getcallback_list_1 AS 
              			select distinct(HistoryId) as HistoryId,SessionDate, UserID, agentId, AgentName, IsInBound, dispositionName, dialDuration, waitDuration, chatDuration, callDuration, SMSDuration, WhatsappDuration, 
                          sessionEndTime, sessionStartTime, SentimentalScore, dispositionId, (Duration) as Duration, availableTime, afterCallWorkTime,IsMissed from temp_getcallback_list;                             
                       
                 		 DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 
                         
                           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                           DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
                 		  CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
                 		  SELECT  distinct(SH.UserID)   AS AgentId
                            
                           
                   		  ,SH.AgentName
                         
                           ,SUM(SH.waitDuration) 																										AS waitTimeAnsweredCall
                          ,SUM(CASE WHEN SH.dispositionId IS NOT NULL and SH.IsMissed =0 THEN 1 ELSE 0 END ) 											AS totalNumberOfAnswered
                      	  ,SUM(CASE WHEN SH.dialDuration BETWEEN 1 AND 30000 AND SH.dialDuration IS NOT NULL and SH.IsMissed =0 THEN 1 
 									WHEN SH.dialDuration BETWEEN 1 AND 30000 AND SH.SMSDuration IS NOT NULL and SH.IsMissed is null THEN 1 
                                     WHEN SH.dialDuration BETWEEN 1 AND 30000 AND SH.chatDuration IS NOT NULL and SH.IsMissed is null THEN 1
                                     ELSE 0  END)														AS thresholdTime
                           ,count(1) 																													AS queriesReceived
                       	  ,SUM(CASE WHEN SH.dispositionName in ('Closed','Resolved') THEN 1 ELSE 0 END) 												AS queriesResolved
                           ,SUM(CASE WHEN SH.dispositionName IS NOT NULL THEN 1 ELSE 0 END ) 															AS queriesAnswered
                           ,SUM(SH.SentimentalScore) 																									AS CSATscore
                           ,SH.availableTime																											AS availableTime
                           ,sum(Duration+afterCallWorkTime)                                                                        						AS Duration
                           FROM temp_getcallback_list_1 SH
                           where SH.UserID is not null 
						   GROUP BY SH.UserID,SH.AgentName,SH.availableTime;
                   		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
                        
                           DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc_1; 
                 		    CREATE TEMPORARY TABLE tt_sessionHistory_calc_1 AS 
               			select distinct(AgentId)as AgentId, AgentName, waitTimeAnsweredCall, totalNumberOfAnswered, thresholdTime, queriesReceived, 
               			queriesResolved, queriesAnswered, CSATscore, availableTime, Duration from tt_sessionHistory_calc;               
		
				SELECT SUM(IFNULL(satisfactionRate,0)) INTO v_totalCSAT
				FROM tb_customerFeedback
				WHERE domainId = p_domainId
				AND	IFNULL(updatedDate,createdDate) BETWEEN DATE_FORMAT(FROM_UNIXTIME(v_startTmpstmp/1000),'%Y-%m-%d %H:%i:%s') AND  DATE_FORMAT(FROM_UNIXTIME(v_endTmpstmp/1000),'%Y-%m-%d %H:%i:%s')
				AND (IFNULL(p_agentId,0)=0 OR AgentId = p_agentId);
          
                DROP TEMPORARY TABLE IF EXISTS tt_temp_result_2;
                CREATE TEMPORARY TABLE tt_temp_result_2(
					agentName				varchar(100)
					,averagespeedofanswer	decimal(58,4)
					,serviceLevel			decimal(52,4)
					,occupancyrate			decimal(62,4)
					,resolvedqueries		decimal(52,4)
					,CSATscore				decimal(36,4)
                );
                INSERT INTO tt_temp_result_2(agentName,averagespeedofanswer	,serviceLevel,occupancyrate,resolvedqueries,CSATscore)
			SELECT  
			a.AgentName AS agentName,                   
			
			SUM(CASE WHEN a.queriesAnswered != 0 THEN a.waitTimeAnsweredCall / a.queriesAnswered ELSE 0 END) AS averagespeedofanswer,
			SUM(CASE WHEN a.queriesReceived != 0 THEN (a.thresholdTime / a.queriesReceived) * 100 ELSE 0 END) AS serviceLevel,
			SUM(CASE WHEN v_overAllavailableTime != 0 THEN (Duration / v_overAllavailableTime) * 100 ELSE 0 END) AS occupancyrate,
			SUM(CASE WHEN a.queriesAnswered != 0 THEN (a.queriesResolved / a.queriesAnswered) * 100 ELSE 0 END) AS resolvedqueries,
			SUM(CASE WHEN a.queriesAnswered != 0 THEN v_totalCSAT / a.queriesAnswered ELSE 0 END) AS CSATscore
			
			FROM     tt_sessionHistory_calc a
			GROUP BY     a.AgentName 
			LIMIT     v_offset, p_limit;
             
           	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           	DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
           	CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
           	SELECT  AA.UserName				as AgentName
           		,	CH.IsInBound			as IsInBound
           		,	CDH.Duration			as HandlingTime
           		,	CDH.afterCallWorkTime	as afterWorkTime
           		
                  ,CASE WHEN CDH.Duration>0  THEN 1 ELSE 0 END  as Answered
           		,	CDH.AgentHoldDuration	as agentHoldDuration
           		
                  ,	CDH.answeredDuration 	as waitDuration
           	FROM tb_CallHistory 			CH        
           	JOIN tb_CallDurationHistory		CDH	ON 	CH.CallHistoryId = CDH.CallHistoryId        
           	LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
           	LEFT JOIN temp_agentId 			t_A ON AA.UserID 		= t_A.agentId 
           
           	WHERE 	CH.domainId 			= p_domainId 		
             AND		CDH.IsBot				= 0
           	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp  and CDH.Duration>0 
           	AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL)); 
                     
           	Insert into tt_temp_sessionHistory(AgentName,IsInBound,HandlingTime,afterWorkTime,Answered,agentHoldDuration,waitDuration)
           	SELECT 	AA.UserName				as AgentName
           		,	CH.IsInBound			as IsInBound
           		,	CDH.Duration			as HandlingTime
           		,	CDH.afterChatWorkTime	as afterWorkTime
           		,	CASE WHEN CDH.Duration>0  THEN 1 ELSE 0 END  as Answered
           		,	CDH.AgentHoldDuration	as agentHoldDuration
           		,	CDH.answeredDuration 	as waitDuration      
           	FROM tb_ChatHistory 			CH        
           	JOIN tb_ChatDurationHistory		CDH	ON 	CH.ChatHistoryId 	= CDH.ChatHistoryId        
           	LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 			= CDH.AgentId
           	LEFT JOIN temp_agentId 			t_A ON AA.UserID 			= t_A.agentId 
           
           	WHERE 	CH.domainId 			= p_domainId 	
             AND		CDH.IsBot				= 0
           	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 			AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL)); 
                     
           	Insert into tt_temp_sessionHistory(AgentName,IsInBound,HandlingTime,afterWorkTime,Answered,agentHoldDuration,waitDuration)
           	SELECT 	AA.UserName				as AgentName
           		,	CH.IsInBound			as IsInBound
           		,	CDH.Duration			as HandlingTime
           		,	CH.AfterEmailWorkTime	as afterWorkTime
           		,	1						as Answered
           		,	CDH.AgentHoldDuration	as agentHoldDuration
           		,	CH.waitDuration			as waitDuration       
           	FROM tb_EmailHistory 			CH        
           	JOIN tb_EmailDurationHistory	CDH	ON 	CH.EmailHistoryId 	= CDH.EmailHistoryId        
           	LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 			= CDH.AgentId
           	LEFT JOIN temp_agentId 			t_A ON AA.UserID 			= t_A.agentId 
           
           	WHERE 	CH.domainId 			= p_domainId 	
              AND 	CDH.IsBot				= 0
           	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
           	AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL)); 
                     
           	Insert into tt_temp_sessionHistory(AgentName,IsInBound,HandlingTime,afterWorkTime,Answered,agentHoldDuration,waitDuration)
           	SELECT 	AA.UserName				as AgentName
           		,	CH.IsInBound			as IsInBound
           		,	CDH.Duration			as HandlingTime
           		,	CH.afterSMSWorkTime		as afterWorkTime
           		,	1						as Answered
           		,	CDH.AgentHoldDuration	as agentHoldDuration
           		,	CH.waitDuration			as waitDuration       
           	FROM tb_SMSHistory 				CH        
           	JOIN tb_SMSDurationHistory		CDH	ON 	CH.SMSHistoryId = CDH.SMSHistoryId        
           	LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
           	LEFT JOIN temp_agentId 			t_A ON AA.UserID 		= t_A.agentId 
           
           	WHERE 	CH.domainId 			= p_domainId 	
 			AND		CDH.IsBot				= 0
           	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
           	AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));           
 
           	Insert into tt_temp_sessionHistory(AgentName,IsInBound,HandlingTime,afterWorkTime,Answered,agentHoldDuration,waitDuration)
           	SELECT 	AA.UserName					as AgentName
           		,	CH.IsInBound				as IsInBound
           		,	CDH.Duration				as HandlingTime
           		,	CH.afterwhatsappWorkTime	as afterWorkTime
           		,	1							as Answered
           		,	CDH.dialDuration			as agentHoldDuration
           		,	CDH.dialDuration			as waitDuration       
           	FROM tb_WhatsappHistory 			CH        
           	JOIN tb_WhatsappDurationHistory		CDH	ON 	CH.WhatsappHistoryId = CDH.WhatsappHistoryId        
           	LEFT JOIN temp_AllagentId 			AA	ON AA.UserID 		= CDH.AgentId
           	LEFT JOIN temp_agentId 				t_A ON AA.UserID 		= t_A.agentId 
           
           	WHERE 	CH.domainId 			= p_domainId 	
 			AND		CDH.IsBot				= 0
           	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
           	AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));               
     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;           
                     
           	DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
           	CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
           	SELECT 	SH.agentName 
           			,SUM(CASE WHEN SH.IsInBound = 1 THEN 1 ELSE 0 END) 						as received
           			,SUM(CASE WHEN SH.IsInBound = 0 THEN 1 ELSE 0 END) 						as outbound
           			,SUM(CASE WHEN SH.HandlingTime > 0 THEN SH.HandlingTime ELSE 0 END) 	as HandlingTime
           			,SUM(SH.afterWorkTime) 													as NoOfAfterWorkTime
           			,SUM(CASE WHEN SH.Answered>0 THEN 1 ELSE 0 END ) 						as Answered
           			,SUM(SH.agentHoldDuration)												as HoldTime
           			,SUM(SH.waitDuration)													as waitDuration
           	FROM 	tt_temp_sessionHistory SH
           	GROUP BY SH.agentName;   		
                     
       		DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc_1; 
           	CREATE TEMPORARY TABLE tt_sessionHistory_calc_1 AS        
             select agentName, received, outbound, (HandlingTime/1000) as HandlingTime, NoOfAfterWorkTime, Answered, HoldTime, waitDuration  
             FROM tt_sessionHistory_calc;
            
            DROP TEMPORARY TABLE IF EXISTS tt_temp_result_3;
            CREATE TEMPORARY TABLE tt_temp_result_3(
				agentName  VARCHAR(255)
				,inbounds  DECIMAL(24,2)
				,outbounds  DECIMAL(24,2)
				,totalhandlingtime  DECIMAL(48,2)
				,averagehandlingtime  DECIMAL(52,2)
				,TotalACWTime  DECIMAL(33,2)
				,averageACW  DECIMAL(38,2)
				,averageSpeedofanswer  DECIMAL(47,2)
				);
		
            INSERT INTO tt_temp_result_3(agentName ,inbounds ,outbounds ,totalhandlingtime ,averagehandlingtime ,TotalACWTime ,averageACW ,averageSpeedofanswer )
           	SELECT 	a.agentName 																				as agentName
           		,	a.received																					as inbounds
           		,	a.outbound																					as outbounds
   				,	(ifnull(a.HandlingTime,0) + ifnull(a.NoOfAfterWorkTime,0))						  			as totalhandlingtime
           		,	((ifnull(a.HandlingTime,0) + ifnull(a.NoOfAfterWorkTime,0))/sum(a.received + outbound))		as averagehandlingtime
           		,	a.NoOfAfterWorkTime 																		as TotalACWTime
           		
   				,	CASE WHEN sum(a.received + outbound) = 0 THEN 0 ELSE (a.NoOfAfterWorkTime / sum(a.received + outbound)) END as averageACW 
           		,	CASE WHEN a.Answered = 0 THEN 0 ELSE (a.waitDuration/a.Answered) END 						as averageSpeedofanswer
		FROM 	tt_sessionHistory_calc_1 a
		GROUP by  	a.agentName, a.received, a.outbound,a.Answered, a.HandlingTime,a.NoOfAfterWorkTime,a.waitDuration
		ORDER BY 	a.agentName, a.received, a.outbound,a.Answered, a.HandlingTime,a.NoOfAfterWorkTime,a.waitDuration
		LIMIT v_offset, p_limit;          
   
    DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
    CREATE TEMPORARY TABLE temp_AvailableState AS
	SELECT   
	CASE 
        WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
        WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Not Ready', 'Away', 'Offline') THEN 2
        ELSE 3 
    END AS tt_Time,
    ST.ext,
    ST.domainId,
    from_unixtime(ST.startTimestamp/1000),
    ST.stateDuration as SD,
    DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d') AS startTimestamp
	FROM     state_timer ST 
	JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
	WHERE    ST.domainId = p_domainId
	AND 	 ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp; 
   
    DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory;
    CREATE TEMPORARY TABLE IF NOT EXISTS tt_logInSessionHistory AS
	SELECT 
            DATE_FORMAT(LSH.createdAt, '%d %b %d %h:%i %p') AS SessionDate,
            U.UserName,
            LSH.ext,
            U.UserID as AgentId,
            LSH.domainId,
            TIME_FORMAT(FROM_UNIXTIME(LSH.logInTimestamp / 1000), '%H:%i:%s') AS LoginTime,
            TIME_FORMAT(FROM_UNIXTIME(LSH.logOutTimestamp / 1000), '%H:%i:%s') AS LogOut,
            FROM_UNIXTIME(LSH.logInTimestamp / 1000) AS LoginDateTime,
            
            CASE WHEN LSH.logOutTimestamp IS NULL THEN FROM_UNIXTIME(
        COALESCE(
            LSH.logOutTimestamp / 1000, 
            LEAD(LSH.logInTimestamp) OVER (ORDER BY LSH.logInTimestamp) / 1000
        )
    ) ELSE FROM_UNIXTIME(LSH.logOutTimestamp / 1000) END AS LogOutDateTime,
            LSH.createdAt
    FROM logInSessionHistory LSH
    JOIN tb_User U ON U.ext = LSH.ext AND U.domainId = LSH.domainId
    WHERE LSH.domainId = p_domainId
    AND UNIX_TIMESTAMP(LSH.createdAt)*1000 BETWEEN v_startTmpstmp AND v_endTmpstmp
    GROUP BY LSH.createdAt, U.UserName,U.UserID, LSH.ext,LSH.logInTimestamp, LSH.logOutTimestamp,LSH.domainId;

    DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory_cal; 
    CREATE TEMPORARY TABLE tt_logInSessionHistory_cal AS 
    SELECT  
            tt_LSH.UserName AS AgentName,
            MIN(tt_LSH.LoginTime) AS LoginTime,
            MAX(tt_LSH.LogOut) AS LogOut,
            tt_LSH.ext,
            tt_LSH.domainId,
            
            TIMESTAMPDIFF(SECOND, MIN(tt_LSH.LoginDateTime), MAX(tt_LSH.LogOutDateTime)) AS LoggedinDuration,
            SUM(CASE WHEN tt_AV.tt_Time = 1 THEN tt_AV.SD ELSE 0 END) AS availableTime,
            SUM(CASE WHEN tt_AV.tt_Time = 2 THEN tt_AV.SD ELSE 0 END) AS unAvailableTime
    FROM tt_logInSessionHistory tt_LSH
    JOIN temp_AvailableState tt_AV ON tt_LSH.ext = tt_AV.ext AND tt_AV.domainId = tt_LSH.domainId
    GROUP BY tt_LSH.UserName, tt_LSH.ext, tt_LSH.domainId;
	
    DROP TEMPORARY TABLE IF EXISTS tt_temp_result_4;
	CREATE TEMPORARY TABLE tt_temp_result_4(
		agentName VARCHAR(255)
		,loginTime VARCHAR(13)
		,logoutTime VARCHAR(13)
		,loggedInDuration DECIMAL(22,2)
		,availableTime DECIMAL(43,2)
		,unavailabletime DECIMAL(43,2)
    );
    INSERT INTO tt_temp_result_4(agentName,loginTime,logoutTime,loggedInDuration,availableTime,unavailabletime)
    SELECT DISTINCT 
            AgentName AS agentName,
            LoginTime AS loginTime,
            LogOut AS logoutTime,
            round(LoggedinDuration / 1000) AS loggedInDuration,
            round(availableTime/ 1000) AS availableTime,
            round(unAvailableTime/ 1000) AS unavailabletime
    FROM tt_logInSessionHistory_cal;
    
    DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
    CREATE TEMPORARY TABLE temp_AvailableState AS
    SELECT  
        ST.ext,
        ST.domainId,
        CASE 
            WHEN a.statusName = 'Ready' THEN 1
            WHEN a.statusName = 'Not Ready' THEN 2
            WHEN a.statusName = 'Transfer Only' THEN 3
            WHEN a.statusName = 'Away' THEN 4
            WHEN a.statusName = 'Busy' THEN 5
            ELSE 6 
        END AS tt_Time,
        ST.stateDuration as SD,
        DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d') AS startTimestamp
    FROM state_timer ST 
    JOIN agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
    WHERE 
        ST.domainId = p_domainId
        AND ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;
  
    DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory;
    CREATE TEMPORARY TABLE IF NOT EXISTS tt_logInSessionHistory AS
    SELECT 
        
        U.UserName,
        LSH.ext,
        LSH.domainId,
        TIME_FORMAT(FROM_UNIXTIME(LSH.logInTimestamp / 1000), '%H:%i:%s') AS LoginTime,
        TIME_FORMAT(FROM_UNIXTIME(LSH.logOutTimestamp / 1000), '%H:%i:%s') AS LogOut,
        FROM_UNIXTIME(LSH.logInTimestamp / 1000) AS LoginDateTime,
        CASE WHEN LSH.logOutTimestamp IS NULL THEN FROM_UNIXTIME(
        COALESCE(
            LSH.logOutTimestamp / 1000, 
            LEAD(LSH.logInTimestamp) OVER (ORDER BY LSH.logInTimestamp) / 1000
        )
    ) ELSE FROM_UNIXTIME(LSH.logOutTimestamp / 1000) END AS LogOutDateTime,
        LSH.logInTimestamp,
        DATE_FORMAT(LSH.createdAt,'%Y-%m-%d') as createdAt
    FROM logInSessionHistory LSH
    JOIN tb_User U ON U.ext = LSH.ext AND U.domainId = LSH.domainId
    WHERE 
        LSH.domainId = p_domainId
        AND UNIX_TIMESTAMP(LSH.createdAt) * 1000 BETWEEN v_startTmpstmp AND v_endTmpstmp;
    
    DROP TEMPORARY TABLE IF EXISTS tt_logInSessionHistory_cal;
    CREATE TEMPORARY TABLE tt_logInSessionHistory_cal AS 
    SELECT  
        
        tt_LSH.UserName AS AgentName,
        MIN(tt_LSH.LoginTime) AS LoginTime,
        MAX(tt_LSH.LogOut) AS LogOut,
        tt_LSH.ext,
        tt_LSH.domainId,
        
        TIMESTAMPDIFF(SECOND, MIN(tt_LSH.LoginDateTime), MAX(tt_LSH.LogOutDateTime)) AS LoggedinDuration,
        SUM(CASE WHEN tt_AV.tt_Time = 1 THEN tt_AV.SD ELSE 0 END) AS ready,
        SUM(CASE WHEN tt_AV.tt_Time = 2 THEN tt_AV.SD ELSE 0 END) AS notReady,
        SUM(CASE WHEN tt_AV.tt_Time = 3 THEN tt_AV.SD ELSE 0 END) AS transferOnly,
        SUM(CASE WHEN tt_AV.tt_Time = 4 THEN tt_AV.SD ELSE 0 END) AS away,
        SUM(CASE WHEN tt_AV.tt_Time = 5 THEN tt_AV.SD ELSE 0 END) AS busyTime,
        SUM(CASE WHEN tt_AV.tt_Time = 6 THEN tt_AV.SD ELSE 0 END) AS custom
    FROM tt_logInSessionHistory tt_LSH
    JOIN temp_AvailableState tt_AV ON tt_LSH.ext = tt_AV.ext AND tt_AV.domainId = tt_LSH.domainId AND tt_LSH.createdAt = tt_AV.startTimestamp
    WHERE (tt_LSH.logInTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp)
    GROUP BY  tt_LSH.UserName, tt_LSH.ext, tt_LSH.domainId;

	DROP TEMPORARY TABLE IF EXISTS tt_temp_result_5;
	CREATE TEMPORARY TABLE tt_temp_result_5(
		agentName VARCHAR(255)
		,totalLoggedinTime DECIMAL(22,2)
		,ready DECIMAL(43,2)
		,readyper DECIMAL(46,2)
		,notReady DECIMAL(43,2)
		,notReadyper DECIMAL(46,2)
		,transferOnly DECIMAL(43,2)
		,transferOnlyper DECIMAL(46,2)
		,away DECIMAL(43,2)
		,awayper DECIMAL(46,2)
		,busyTime DECIMAL(43,2)
		,busyTimeper DECIMAL(46,2)
		,customState DECIMAL(43,2)
		,customStateper DECIMAL(46,2)
    );
    
    INSERT INTO tt_temp_result_5(agentName,totalLoggedinTime,ready,readyper,notReady,notReadyper,transferOnly,transferOnlyper,away,awayper,busyTime,busyTimeper,customState,customStateper)
    SELECT 
        agentName
        ,ROUND(LoggedinDuration / 1000) AS totalLoggedinTime
        ,ROUND(ready/1000) as ready
        ,ROUND((ready/ LoggedinDuration) * 100) AS readyper
        ,ROUND(notReady/1000) as notReady
        ,ROUND((notReady / LoggedinDuration) * 100) AS notReadyper
        ,ROUND(transferOnly/1000) as transferOnly
        ,ROUND((transferOnly / LoggedinDuration) * 100) AS transferOnlyper
        ,ROUND(away/1000) as away
        ,ROUND((away / LoggedinDuration) * 100) AS awayper
        ,ROUND(busyTime/1000) as busyTime
        ,ROUND((busyTime / LoggedinDuration) * 100) AS busyTimeper
        ,ROUND(custom/1000) as customState
        ,ROUND((custom / LoggedinDuration) * 100) AS customStateper
    FROM tt_logInSessionHistory_cal
    LIMIT v_offset, p_limit;
  
  set p_timeZone = '+05:30';
    
			IF p_agentId IS NOT NULL  THEN
