			,CSATscore INT
        );
        INSERT INTO tt_temp_result_6(agentName,customerName,channel,UserID,CSATQuestion,CSATscore)
		SELECT     agentName,     MIN(customerName) AS customerName,     MIN(channel) AS channel,     MIN(UserID) AS UserID, 
		MIN(CSATQuestion) AS CSATQuestion,     MIN(CSATscore) AS CSATscore 
		FROM     tt_feedback_report
		WHERE    (UserID IN (SELECT DISTINCT agentId FROM temp_agentIds)     OR IFNULL(p_agentId, '') = '')
		GROUP BY     agentName;
        
		DROP TEMPORARY TABLE IF EXISTS tt_final_result;
        CREATE TEMPORARY TABLE tt_final_result AS
        SELECT a.UserID,a.agentName,a.routingProfile,a.inboundTime,a.inboundCalls,a.outboundTime,a.outboundCalls,a.transferredCalls,a.totalCallHandlingTime
		,a.averageCallHandlingTime,a.totalTalkTime,a.averageTalkTime,a.TotalACWTime,a.averageACW,a.totalHoldTime,a.averageHoldTime
		,b.averagespeedofanswer,b.serviceLevel,b.occupancyrate,b.resolvedqueries,b.CSATscore
		,c.inbounds,c.outbounds,c.totalhandlingtime,c.averagehandlingtime
		,d.loginTime,d.logoutTime,d.loggedInDuration,d.availableTime,d.unavailabletime
		,e.totalLoggedinTime,e.ready,e.readyper,e.notReady,e.notReadyper,e.transferOnly,e.transferOnlyper,e.away,e.awayper
		,e.busyTime,e.busyTimeper,e.customState,e.customStateper
		,f.customerName,f.channel,f.CSATQuestion
		FROM tt_temp_result_1 a
		LEFT JOIN tt_temp_result_2 b ON a.agentName = b.agentName
		LEFT JOIN tt_temp_result_3 c ON b.agentName = c.agentName
		LEFT JOIN tt_temp_result_4 d ON c.agentName = d.agentName
		LEFT JOIN tt_temp_result_5 e ON d.agentName = e.agentName
		LEFT JOIN tt_temp_result_6 f ON e.agentName = f.agentName;     

	SET @columns = '';
		SET @keyValuePairs = '';
		WHILE LOCATE(',', p_columnName) > 0 DO
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										', ');
			SET p_columnName = SUBSTRING(p_columnName, LOCATE(',', p_columnName) + 1);
		END WHILE;
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_columnName,
									'\', ',
									p_columnName);

		SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM tt_final_result'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;

		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId;
			
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomReport_AI` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomReport_AI`(
	p_startTmpstmp 		BIGINT,
	p_endTmpstmp 		BIGINT,
	p_timeZone 			VARCHAR(200),
	p_domainId 			INT,
	p_queueId 			TEXT,
	p_agentId 			TEXT,  
	p_direction			TINYINT,          
	p_Limit 			INT,	   
	p_offset 			INT,
    p_columnName		TEXT,
    p_lastIsertId		INT
)
BEGIN 
			DECLARE v_offset				INT;
			DECLARE v_count 				INT; 
			DECLARE v_startTmpstmp  		BIGINT;
			DECLARE v_endTmpstmp 			BIGINT;
            DECLARE temp_result_3_used BOOLEAN DEFAULT FALSE;
          
			SET v_offset =  p_Limit * p_offset;
                  
			IF IFNULL(p_startTmpstmp,0) = 0 THEN SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
			IF IFNULL(p_endTmpstmp,0) = 0 THEN SET v_endTmpstmp =  UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  	

			DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_direction;	    CREATE TEMPORARY TABLE temp_direction(directionId 	VARCHAR(3));

			CALL split(p_queueId,',');		INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
			CALL split(p_agentId,',');		INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
          
        		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
        		CREATE TEMPORARY TABLE temp_AllqueueId
  			SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
        		
        		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
        		CREATE TEMPORARY TABLE temp_AllagentId
        		select UserID,UserName,domainId from tb_User where domainId = p_domainId;  
                
                  IF p_direction IS NULL OR p_direction IN ('0,1','1,0')
                  THEN
              		INSERT INTO temp_direction 
                      (directionId)
                      VALUES (0),(1);
              	ELSE
              		INSERT INTO temp_direction
                      (directionId)
                      SELECT p_direction;
                  END IF;        
                  
    			  DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
                  CREATE TEMPORARY TABLE temp_AlldirectionId
                  select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
          								   WHEN directionId = 1 THEN 'InBound' END AS directionName 
         								   FROM temp_direction ;   
                                           
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
      	CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
      	SELECT
				UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(CH.sessionStartTime /1000) AS DATE))*1000						as SessionDate
				,	AA.UserID																					AS agentId
				,	AA.UserName						        													AS agentName 
				,	Q.queueName					                        										AS queueName  
				,  CDH.SentimentalScore                        													AS SentimentalScore 
				,  CDH.sentimentalScoreCustomer
				,  CDH.sentimentalScoreAgent
				,	CH.customerNumber        		            												AS customerNumber    
				,  CH.calledNumber                             													AS calledNumber	
				,  CASE WHEN CH.IsInBound = 1 THEN 'Inbound'  WHEN CH.IsInBound = 0 THEN 'Outbound'  END        AS Direction          
				FROM 	 tb_CallHistory 			    CH                                 
				JOIN     tb_CallDurationHistory			CDH     ON 	CH.CallHistoryId    = CDH.CallHistoryId     
				JOIN    customer_contact                CC   	ON  CC.domainId 		= CH.domainId
																AND CC.coid			    = CH.CustomerId
				JOIN 	temp_AllqueueId					Q		ON  CDH.QueueId		    = Q.queueId
				LEFT JOIN temp_AllagentId				AA		ON  AA.UserID 		    = CDH.agentId
																AND AA.domainId         = CH.domainId   
				LEFT JOIN temp_agentId 			       	t_A     ON  AA.UserID 		    = t_A.agentId   
				LEFT JOIN temp_queueId 					t_Q 	ON  Q.queueId			    = t_Q.queueId 
				LEFT JOIN temp_direction                t_d     ON t_d.directionId      = CH.IsInBound    
				WHERE 	CH.domainId 					= p_domainId 	
      	AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
     	AND 	(IFNULL(p_queueId,'') 			= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
     	AND 	(IFNULL(p_agentId,'') 			= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
        AND      (IFNULL(p_direction,'')        = '' OR (IFNULL(p_direction,'') <> ''AND t_d.directionId IS NOT NULL));           
                
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
			DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
				CREATE TEMPORARY TABLE tt_sessionHistory_calc AS   
				SELECT  SH.SessionDate,
						SH.agentName,
						SH.queueName, 
						SH.SentimentalScore,
						SH.sentimentalScoreCustomer,
						SH.sentimentalScoreAgent,
						SH.customerNumber,
						SH.Direction,
						SH.calledNumber
				FROM 	tt_temp_sessionHistory SH;

			DROP TEMPORARY TABLE IF EXISTS tt_temp_result_1;
			CREATE TEMPORARY TABLE tt_temp_result_1(
			dateTime					DATE
			,agentName					VARCHAR(255)
			,queueName					VARCHAR(255)
			,contactCenterNumber		BIGINT
			,customerNumber				VARCHAR(20)
			,direction					VARCHAR(8)
			,callQualityScore			INT
			,customerSentimentalScore	INT
			,agentSentimentalScore		INT
			,overallInteractionScore	INT
		);

                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
				INSERT INTO tt_temp_result_1(dateTime,agentName,queueName,contactCenterNumber,customerNumber,direction,callQualityScore,customerSentimentalScore,agentSentimentalScore,overallInteractionScore)
				SELECT 	FROM_UNIXTIME(a.SessionDate/1000) 					AS `dateTime`
						,a.agentName 					AS agentName
						,a.queueName 					AS queueName
						,a.calledNumber 				AS contactCenterNumber
						,a.customerNumber 				AS customerNumber
						,a.Direction					AS direction
						,a.SentimentalScore				AS callQualityScore 
						,a.sentimentalScoreCustomer	 	AS customerSentimentalScore 
						,a.sentimentalScoreAgent	 	AS agentSentimentalScore
						,a.SentimentalScore			 	AS overallInteractionScore   
				FROM 	tt_sessionHistory_calc a
				ORDER BY a.SessionDate DESC
				LIMIT v_offset, p_limit;   
                     
     DROP TEMPORARY TABLE IF EXISTS temp_agentId;
     CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
     CALL split(p_agentId,',');    
     INSERT INTO temp_agentId(agentId)
     SELECT Items FROM tt_Split_temptable;
    
     DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;    
     CREATE TEMPORARY TABLE temp_AllagentId
     SELECT UserID, UserName, domainId FROM tb_User WHERE domainId = p_domainId;          
    
     DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     CREATE TEMPORARY TABLE temp_AvailableDisposition 
     (   
         DispositionId          INT,
         DispositionStatus      VARCHAR(100),
         DispositionCategory    TINYINT
     ); 
     INSERT INTO temp_AvailableDisposition 
     SELECT
         did                 DispositionId,
         dispositionName     DispositionStatus,
         CASE 
             WHEN dispositionName = 'Opened' THEN 2
             WHEN dispositionName IN ('Resolved', 'Unresolved', 'Closed', 'Follow-up', 'Disconnected', 'Transferred') THEN 3
             WHEN dispositionName = 'Discarded' THEN 4
             WHEN dispositionName = 'Resolved' THEN 5
             WHEN dispositionName = 'Closed' THEN 6
         END                 DispositionCategory
     FROM disposition_status
     WHERE domainId = p_domainId;
    
     DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;    
     CREATE TEMPORARY TABLE temp_AllagentId
     SELECT UserID, UserName, ext FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (5, 3);

     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     
     DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
     CREATE TEMPORARY TABLE temp_chatHistory AS
     SELECT
         DISTINCT CH.ChatHistoryId,
         CAST(FROM_UNIXTIME(CH.sessionStartTime / 1000) AS DATE) 							AS SessionDate,
         DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime / 1000), '%Y-%m-%d %H:00:00') 		AS HourlyInterval,
         SUM(CASE WHEN CDH.IsBot = 1 AND t_D.DispositionCategory = 6 THEN 1 ELSE 0 END) 		AS resolvedChat,
         SUM(CASE WHEN CDH.IsAbandoned = 1 THEN 1 ELSE 0 END) 								AS abandonedChat,         
         SUM(CASE WHEN CDH.IsBot = 0 THEN 1 ELSE 0 END) 										AS transferredToAgent,
         SUM((CDH.Duration / 1000) + CDH.afterChatWorkTime) 									AS ResponsesTime,
         MIN(CH.sessionEndTime) - MIN(CH.sessionStartTime) 									AS resolutionTime,
         CDH.SentimentalScore
     FROM
         tb_ChatHistory CH
         JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
         LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
         LEFT JOIN temp_agentId t_A ON U.UserID = t_A.agentId
         LEFT JOIN temp_AvailableDisposition t_D ON CDH.dispositionId = t_D.DispositionId
     WHERE
         CH.domainId = p_domainId
         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
         AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
     GROUP BY HourlyInterval, CDH.SentimentalScore, CH.ChatHistoryId;
    
     DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_1; 
     CREATE TEMPORARY TABLE temp_ChatHistory_1 AS    
     SELECT 
         DISTINCT ChatHistoryId,
         COUNT(1) AS handledChat,
         HourlyInterval,
         resolvedChat,
         abandonedChat,
         transferredToAgent,
         ResponsesTime,
         resolutionTime,
         SentimentalScore
     FROM temp_chatHistory 
     GROUP BY ChatHistoryId, HourlyInterval, resolvedChat, abandonedChat, transferredToAgent, ResponsesTime, resolutionTime, SentimentalScore
     ORDER BY HourlyInterval DESC 
     LIMIT v_offset, p_Limit;
   
   
	DROP TEMPORARY TABLE IF EXISTS tt_temp_result_2;
	CREATE TEMPORARY TABLE tt_temp_result_2
	(	
		dateTime				DATE
		,handledChat			INT
		,resolvedChat			INT
		,abandonedChat			INT
		,autoClosedByBot		INT
		,deflectedByBot			INT
		,transferredToAgent		INT
		,averageResponsesTime	DECIMAL(50,2)
		,averageResolutionTime	DECIMAL(50,2)
	);
    
    INSERT INTO tt_temp_result_2(dateTime,handledChat,resolvedChat,abandonedChat,autoClosedByBot,deflectedByBot,transferredToAgent,averageResponsesTime,averageResolutionTime)
     SELECT
         distinct(a.HourlyInterval) 			AS dateTime,
         sum(a.handledChat) 					as handledChat,
         sum(a.resolvedChat)  				as resolvedChat,
         sum(a.abandonedChat)  				as abandonedChat,
         0 									AS autoClosedByBot,
         0 									AS deflectedByBot,
         sum(a.transferredToAgent)			as transferredToAgent,
         sum(a.ResponsesTime) 				AS averageResponsesTime,
         sum(a.resolutionTime) 				AS averageResolutionTime
     FROM 
         temp_ChatHistory_1 a
         group by a.HourlyInterval; 
		
	DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));

	 
	CALL split(p_queueId,',');		INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
	CALL split(p_agentId,',');		INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
	 
		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
		CREATE TEMPORARY TABLE temp_AllqueueId
		SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
		
		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
		CREATE TEMPORARY TABLE temp_AllagentId
		select UserID,UserName,domainId from tb_User where domainId = p_domainId;     
				  
			  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
			  DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
				 CREATE TEMPORARY TABLE temp_chatHistory as
	SELECT
	DISTINCT(CM.ChatHistoryId) 																						AS ChatHistoryId,
	FROM_UNIXTIME(CH.sessionStartTime / 1000) 																		AS SessionDate,
	
	CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
	TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 									AS customerName,               
	IFNULL(GREATEST(SUM(CM.botMsgCount), 0), 0) 																		AS BotInteraction,              
	IFNULL(GREATEST(SUM(CM.agentMsgCount), 0), 0) 																	AS agentInteractionCount,
	IFNULL(sum(CASE WHEN CDH.isbot =1 THEN  CDH.EndTime - CDH.StartTime	END),0)  									AS botSessionDuration,
	IFNULL(sum(CASE WHEN CDH.isbot =0 THEN  CDH.EndTime - CDH.StartTime 	END),0) 									AS agentSessionDuration
	FROM
	tb_ChatHistory CH
	JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
	LEFT	JOIN    customer_contact        CC    ON  CC.domainId 		= CH.domainId
											  AND CC.coid			= CH.CustomerId
	LEFT JOIN  tb_ChatMessage 			CM    ON  CM.ChatHistoryId  = CH.ChatHistoryId  
											  AND CM.ChatDurationHistoryId =CDH.ChatDurationHistoryId
	LEFT JOIN queue						Q	  ON  CDH.queueId		= Q.qid
	LEFT JOIN tb_User						U	  ON  U.UserID			= CDH.AgentId
	LEFT JOIN temp_agentId 			   t_A 	  ON U.UserID 			= t_A.agentId       
	LEFT JOIN temp_queueId 			    t_Q   ON  Q.qid				= t_Q.queueId
	WHERE
		CH.domainId = p_domainId
	AND CH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
	AND 	(IFNULL(p_queueId,'') 			= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
	AND 	(IFNULL(p_agentId,'') 			= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))  
	GROUP BY CM.ChatHistoryId,SessionDate,customerName;
          
			
          
          
                    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        			DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
        			CREATE TEMPORARY TABLE tt_sessionHistory_calc AS
                    SELECT
                    SH.SessionDate,
                    SH.customerName,
                    SH.BotInteraction												AS BotInteractionCount,               
                    SH.agentInteractionCount										AS agentInteractionCount,
                    SH.BotInteraction+SH.agentInteractionCount                         AS TotalInteractionCount,
                    SH.botSessionDuration											AS botSessionDuration,
                    SH.agentSessionDuration										    AS agentSessionDuration,								
                    SH.botSessionDuration+SH.agentSessionDuration					AS TotalSessionDuration
                    FROM temp_chatHistory SH;
                    
					DROP TEMPORARY TABLE IF EXISTS tt_temp_result_3;
					CREATE TEMPORARY TABLE tt_temp_result_3(
							dateTime				DATE
							,customerName			VARCHAR(201)
							,BotInteractionCount	INT
							,agentInteractionCount	INT
							,TotalInteractionCount	INT
							,botSessionDuration		INT
							,agentSessionDuration	INT
							,TotalSessionDuration	INT
                    );
                   
                   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
					INSERT INTO tt_temp_result_3(dateTime,customerName,BotInteractionCount,agentInteractionCount,TotalInteractionCount,botSessionDuration,agentSessionDuration,TotalSessionDuration)
					SELECT 	  CAST(a.SessionDate AS DATE)	 																AS `dateTime`   
       					 ,a.customerName																					AS customerName                               
       					 ,SUM(a.BotInteractionCount)																		AS BotInteractionCount
       					 ,SUM(a.agentInteractionCount)																		AS agentInteractionCount
      					 ,SUM(a.TotalInteractionCount)                     													AS TotalInteractionCount
       					 ,SUM(a.botSessionDuration)														    				AS botSessionDuration
       					 ,SUM(a.agentSessionDuration)																		AS agentSessionDuration
      					 ,SUM(a.botSessionDuration+a.agentSessionDuration) 													AS TotalSessionDuration
                    	FROM 	tt_sessionHistory_calc a
						GROUP BY a.SessionDate,a.customerName 
						ORDER BY a.SessionDate DESC
                    	LIMIT v_offset, p_limit; 
            
		SET temp_result_3_used = 
        (LOCATE('dateTime', p_columnName) > 0) OR
        (LOCATE('agentName', p_columnName) > 0) OR
        (LOCATE('queueName', p_columnName) > 0) OR
        (LOCATE('contactCenterNumber', p_columnName) > 0) OR
        (LOCATE('customerNumber', p_columnName) > 0) OR
        (LOCATE('direction', p_columnName) > 0) OR
        (LOCATE('callQualityScore', p_columnName) > 0) OR
        (LOCATE('customerSentimentalScore', p_columnName) > 0) OR
        (LOCATE('agentSentimentalScore', p_columnName) > 0) OR
        (LOCATE('overallInteractionScore', p_columnName) > 0);

	 DROP TEMPORARY TABLE IF EXISTS tt_final_result;

	IF temp_result_3_used THEN
        CREATE TEMPORARY TABLE tt_final_result AS
        SELECT 	a.dateTime,a.agentName,a.queueName,a.contactCenterNumber,a.customerNumber,a.direction,a.callQualityScore,a.customerSentimentalScore,a.agentSentimentalScore,a.overallInteractionScore
				,b.handledChat,b.resolvedChat,b.abandonedChat,b.autoClosedByBot,b.deflectedByBot,b.transferredToAgent,b.averageResponsesTime,b.averageResolutionTime
				,c.customerName,c.BotInteractionCount,c.agentInteractionCount,c.TotalInteractionCount,c.botSessionDuration,c.agentSessionDuration,c.TotalSessionDuration
        FROM tt_temp_result_1 a
        LEFT JOIN tt_temp_result_2 b ON a.dateTime = b.dateTime
        LEFT JOIN tt_temp_result_3 c ON b.dateTime = c.dateTime;
	ELSE 
		CREATE TEMPORARY TABLE tt_final_result AS
        SELECT 	 b.handledChat,b.resolvedChat,b.abandonedChat,b.autoClosedByBot,b.deflectedByBot,b.transferredToAgent,b.averageResponsesTime,b.averageResolutionTime
				,c.customerName,c.BotInteractionCount,c.agentInteractionCount,c.TotalInteractionCount,c.botSessionDuration,c.agentSessionDuration,c.TotalSessionDuration
        FROM 	 tt_temp_result_2 b 
        LEFT JOIN tt_temp_result_3 c ON b.dateTime = c.dateTime;
	END IF;
			
		SET @columns = '';
			SET @keyValuePairs = '';
			WHILE LOCATE(',', p_columnName) > 0 DO
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
									', ');
			SET p_columnName = SUBSTRING(p_columnName, LOCATE(',', p_columnName) + 1);
			END WHILE;
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_columnName,
									'\', ',
									p_columnName);

			SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM tt_final_result'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;

		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId;
        

       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomReport_Chat` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomReport_Chat`(
		p_custom_column 	TEXT, 
		p_domainId 			INT, 
        p_startTmpstmp 		BIGINT, 
	    p_endTmpstmp 		BIGINT,
        p_lastIsertId		INT
	)
BEGIN


    DECLARE v_startTmpstmp						BIGINT;
    DECLARE v_endTmpstmp						BIGINT;
    DECLARE v_defaultQueue						VARCHAR(255);
    DECLARE v_count								INT;                 
	
	DECLARE columnNamePresent 					TEXT;
	DECLARE v_columnMissing 					TINYINT DEFAULT 0;
    DECLARE v_errcode							TINYINT DEFAULT -1 ;
    DECLARE v_errmsg							VARCHAR(50) DEFAULT "Failed";
    
 	IF IFNULL(p_startTmpstmp,0)	= 0 
		THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; 
		ELSE SET v_startTmpstmp = p_startTmpstmp;  
     END IF; 	
	
     IF IFNULL(p_endTmpstmp ,0)	= 0 
 		THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; 
		ELSE SET v_endTmpstmp = p_endTmpstmp; 
     END IF;  

    DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
	CREATE TEMPORARY TABLE temp_AvailableDisposition 
      		(    DispositionId 			INT
      			,DispositionStatus 		VARCHAR(100)
      			,DispositionCategory	TINYINT
      		); 
              
	INSERT INTO temp_AvailableDisposition 
		SELECT 	did 			AS DispositionId
			,	dispositionName	AS DispositionStatus
			,	CASE 
				WHEN dispositionName = 'Opened'	THEN 2
				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
				WHEN dispositionName = 'Discarded' THEN 4
				END 			DispositionCategory
		FROM 	disposition_status
		WHERE 	domainId	= p_domainId;
		
		
        DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
		CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid,name as queueName, type from queue where domainId = p_domainId;
			
		SELECT 	queueName INTO v_defaultQueue	
			FROM 	temp_AllqueueId 
			WHERE 	`type`	= 'Default' LIMIT 1;
    
		SET columnNamePresent = "Date,AgentName,Queue,CustomerName,ChatStartTime,ChatEndTime,Duration,Source,ActiveChatTime,ResponseTime,Disposition,ACWtime,CSATScore,TotalReceivedChats,TotalHandledChats,TotalTransferredChats,TotalMissedChat,TotalActiveChatTime,AverageResponseTime,AverageActiveChatTime,TotalInteractions,TotalACWTime";
	

		SET v_count = (LENGTH(p_custom_column)-LENGTH(REPLACE(p_custom_column, ',', ''))+1);

DROP TEMPORARY TABLE IF EXISTS result_hold;
CREATE TEMPORARY TABLE result_hold
	WITH RECURSIVE check_column(count_no) AS 
    (
		SELECT 1 AS count_no
        UNION ALL
        SELECT count_no +1 FROM check_column
        WHERE count_no < v_count
    )
    SELECT 
         FIND_IN_SET( SUBSTRING_index(SUBSTRING_index(p_custom_column, ',', count_no),',', -1) ,  columnNamePresent) AS temp_Result
    FROM check_column ;
    
    SELECT 1 INTO v_columnMissing FROM result_hold WHERE temp_Result = 0;
    
    
	DROP TEMPORARY TABLE IF EXISTS result_01;
	CREATE TEMPORARY TABLE result_01
     SELECT CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 								AS 	'Date',
            U. UserName											  								AS 	'AgentName',
			IFNULL(Q.name,v_defaultQueue)														AS 	'queueName',
            CASE WHEN coid IS NOT NULL AND (c_c.firstName IS NOT NULL OR c_c.lastName IS NOT NULL) THEN 
				TRIM(CONCAT(IFNULL(c_c.firstName, ''), ' ',IFNULL(c_c.lastName, '')))ELSE NULL END AS 'customerName',
            CDH.StartTime																		AS  'ChatStartTime',
            CDH.EndTime																			AS 	'ChatEndTime',
            CDH.Duration																		AS 	'Duration',
			CH.Browser                                              							AS	'Source', 
			 ABS((CDH.EndTime-CDH.StartTime)/1000)												AS 	'ActiveChattime',
            CH.dialDuration																		AS  'ResponseTime',
            temp_AD.DispositionStatus															AS	'Disposition',
            CDH.afterChatWorkTime														    	AS  'ACWtime', 
			CDH.SentimentalScore																AS 	'CSATscore',
            CASE WHEN temp_AD.DispositionCategory = 3 THEN 1 ELSE 0 END							AS 	'totalHandledChats',
			CASE WHEN temp_AD.DispositionStatus ='Transferred' THEN 1 ELSE 0 END 			    AS 	'totalTransferredChat',	
            CASE WHEN temp_AD.DispositionCategory IS NULL THEN 1 ELSE 0 END						AS  'totalMissedChat',
			CDH.EndTime - CDH.StartTime	 														AS 	'chatHandlingTime',
            CDH.afterChatWorkTime																AS  'ACW'
						FROM tb_ChatHistory 				AS CH
						JOIN tb_ChatDurationHistory 		AS CDH  		ON CH.ChatHistoryId = CDH.ChatHistoryId
						JOIN tb_User 						AS U			ON U.UserID				= CDH.AgentId
                        JOIN temp_AvailableDisposition 		AS temp_AD   	ON CDH.dispositionId	= temp_AD.DispositionId
						LEFT JOIN 		queue					Q	ON CDH.queueId			= Q.qid
						LEFT JOIN customer_contact			c_c	ON 	c_c.coid			= CH.CustomerId  AND	c_c.domainId		= p_domainId
                        WHERE 	CH.domainId 		= p_domainId
                        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp; 
                        
    
    DROP TEMPORARY TABLE IF EXISTS result_02;
    CREATE temporary table result_02
	SELECT  	`Date`												AS Session_date,
 				AgentName											AS Ag_name,
 				queueName											AS Q_name
                ,COUNT(1)											AS totalReceived  
                ,COUNT(1)											AS totalInteraction
				,SUM(totalHandledChats) 							AS TotalHandledChats
				,SUM(totalTransferredChat)							AS TotalTransferredChat
				,SUM(totalMissedChat)								AS TotalMissedChat
              ,  SUM((Duration)+(ACWtime*1000))		    			AS TotalActiveChatTime
              ,  SUM(responseTime)/COUNT(1)							AS AverageResponseTime
              ,  SUM(chatHandlingTime)/COUNT(1)						AS AverageActiveChatTime
              ,  SUM(ACW)											AS TotalACWTIme
              ,  SUM(ACW)/COUNT(1)				                    AS AverageACWTime
 		FROM result_01
         GROUP BY  `Date`, AgentName, queueName
        ;
        
  
  DROP TEMPORARY TABLE IF EXISTS result_03;
  CREATE temporary table result_03
	SELECT t1.`date`  								AS "Date",
            t1.AgentName 							AS "AgentName",
			t1.queueName 							AS "Queue",
			t1.customerName 						AS "CustomerName",
			t1.ChatStartTime 						AS "ChatStartTime",
            t1.ChatEndTime 							AS "ChatEndTime",
            t1.Duration 							AS "Duration",
			t1.`Source` 							AS "Source", 
			t1.ActiveChattime 						AS "ActiveChatTime",
            t1.ResponseTime 						AS "ResponseTime",
            t1.Disposition							AS "Disposition",
            t1.ACWtime 								AS "ACWtime", 
			t1.CSATscore 							AS "CSATScore",
            t2.totalReceived						AS "TotalReceivedChats",
            t2.TotalHandledChats 					AS "TotalHandledChats",
            t2.TotalTransferredChat 				AS "TotalTransferredChats",
            t1.totalMissedChat 						AS "TotalMissedChat",
			t2.TotalActiveChatTime  				AS "TotalActiveChatTime",
			t2.AverageResponseTime 					AS "AverageResponseTime",
            t2.AverageActiveChatTime  				AS "AverageActiveChatTime",
            t2.TotalInteraction						AS "TotalInteractions",
			t2.TotalACWTIme 						AS "TotalACWTIme",
			t2.AverageACWTime 						AS "AverageACWTime"

              FROM result_01 AS t1
              INNER JOIN result_02 As t2
              ON t1.`date` = t2.Session_date AND t1.`AgentName` = t2.Ag_name AND t1.queueName = t2.Q_name
              ;

	
     
	IF v_columnMissing = 0 THEN
	
    
    
    
		SET @columns = '';
		SET @keyValuePairs = '';
		WHILE LOCATE(',', p_custom_column) > 0 DO
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_custom_column, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_custom_column, ',', 1)),
										', ');
		SET p_custom_column = SUBSTRING(p_custom_column, LOCATE(',', p_custom_column) + 1);
		END WHILE;
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_custom_column,
									'\', ',
									p_custom_column);

		SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM result_03'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;
        
		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId; 
    
		SET v_errcode = 1;
		SET v_errmsg = "Success";
    END IF ;  
    
   
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomReport_Email` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomReport_Email`(
                 	p_startTmpstmp 		bigint,
                 	p_endTmpstmp 		bigint,
                 	p_timeZone 			varchar(200),
                 	p_domainId 			int,        
                 	p_queueIds	 		VARCHAR(250),
                 	p_agentIds 			VARCHAR(250),
                    p_dispositionIds	VARCHAR(250),
         			p_offset 			INT,
                 	p_Limit 			INT,
                    p_columnName		TEXT,
                    p_lastIsertId		INT
                 )
BEGIN 
      		DECLARE v_offset 		INT;  	
      		DECLARE v_startTmpstmp 	BIGINT;
      		DECLARE v_endTmpstmp 	BIGINT;
              	
         		SET v_offset = p_offset * p_Limit;
                
      		IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
      		IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
                   	
      		DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
      		DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
      	
      		CALL split(p_queueIds,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
      		CALL split(p_agentIds,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
              
      	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
      	CREATE TEMPORARY TABLE temp_AllqueueId
      	select qid,name as queueName from queue where domainId = p_domainId;
      	
      	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
      	CREATE TEMPORARY TABLE temp_AllagentId
      	select UserID,UserName from tb_User where domainId = p_domainId;  
                
            	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
            	CREATE TEMPORARY TABLE temp_AvailableDisposition 
      		(   DispositionId 			INT
      			,DispositionStatus 		VARCHAR(100)
      			,DispositionCategory	TINYINT
      		); 
            	INSERT INTO temp_AvailableDisposition 
            	SELECT 	did 			DispositionId
            		,	dispositionName	DispositionStatus
           		,	CASE	
      						WHEN dispositionName = 'Transferred' THEN 1
                              WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
                              WHEN dispositionName = 'Discarded' THEN 4
                              ELSE 2
             			END 			DispositionCategory
            	FROM 	disposition_status
            	WHERE 	domainId	= p_domainId;
            	
      	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory; 
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	CREATE TEMPORARY TABLE temp_EmailHistory AS 	
      	SELECT 	
      		UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE))      AS SessionDate
      	 ,	U.UserName				    												AS agentName
           ,	U.UserID																AS agentId
           ,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 					AS Opened
      	 ,	CASE WHEN DispositionCategory = 1 THEN 1 ELSE 0 END 						AS Transferred  
      	 ,	CASE WHEN DispositionCategory = 3 THEN 1 ELSE 0 END 						AS Handled
      	 ,	CASE WHEN DispositionCategory = 4 THEN 1 ELSE 0 END 						AS Discarded
      	 
          , SDH.Duration    															AS EmailHandlingTime
          , SH.AfterEmailWorkTime*1000													AS AfterEmailWorkTime
      	FROM 	tb_EmailHistory 				SH
      	JOIN 	tb_EmailDurationHistory		SDH	ON SH.EmailHistoryId 	= SDH.EmailHistoryId
      	LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
      	LEFT JOIN tb_User					U	ON U.UserID			= SDH.AgentId
      	LEFT JOIN temp_agentId 				t_A ON U.UserID 		= t_A.agentId       
      	WHERE 	SH.domainId 		= p_domainId 		
      	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
      	AND		SH.IsInBound		= 1	
    	AND U.UserName IS NOT NULL
      	AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
      	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
               
      	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_1; 	
      	CREATE TEMPORARY TABLE temp_EmailHistory_1 AS 	     
      	SELECT 	t_SH.SessionDate 																				AS sessionDate
      		,	t_SH.agentName					
      		,	t_SH.agentId					
      		,	COUNT(1)																						AS totalReceived        
      		,	SUM(t_SH.Opened)																				AS totalOpened
      		,	SUM(t_SH.Handled)																				AS totalHandled
      		,	SUM(t_SH.Transferred)																			AS totalTransferred
      		,	SUM(t_SH.Discarded)																				AS totalDiscarded
  		    ,   SUM(t_SH.EmailHandlingTime+t_SH.AfterEmailWorkTime)	 								   			AS totalEmailHandlingTime
   		    ,   (SUM(t_SH.EmailHandlingTime+t_SH.AfterEmailWorkTime)/COUNT(1))								    AS averageEmailHandlingTime    
      	  FROM 	temp_EmailHistory t_SH
      	  GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.agentId;

		DROP TEMPORARY TABLE IF EXISTS tt_temp_result_1;
		CREATE TEMPORARY TABLE tt_temp_result_1(
				sessionDate 				DATE
				,agentName 					VARCHAR(255)
				,agentId 					BIGINT
				,totalReceived 				BIGINT
				,totalOpened 				INT
				,totalHandled 				INT
				,totalTransferred 			INT
				,totalDiscarded 			INT
				,totalEmailHandlingTime 	DECIMAL(43,2)
				,averageEmailHandlingTime 	DECIMAL(48,2)
				);
                    
		  INSERT INTO tt_temp_result_1(sessionDate,agentName,agentId,totalReceived,totalOpened,totalHandled,totalTransferred,totalDiscarded,totalEmailHandlingTime,averageEmailHandlingTime)
      	  SELECT from_unixtime(sessionDate),agentName,agentId,totalReceived,totalOpened,totalHandled,totalTransferred,totalDiscarded,totalEmailHandlingTime,averageEmailHandlingTime
      	  FROM 	temp_EmailHistory_1
      	  ORDER BY v_offset, p_Limit;  
                    
          	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;		CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
          	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
          
          	CALL split(p_agentIDs,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
          	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
              
   		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   		CREATE TEMPORARY TABLE temp_AllagentId
   		SELECT UserID,UserName from tb_User where domainId = p_domainId ;  
            
          	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
          	CREATE TEMPORARY TABLE temp_AvailableDisposition 
          	(	dispositionId 		INT,
          		DispositionStatus 	VARCHAR(100)
          	);
            
          	INSERT INTO temp_AvailableDisposition 
          	SELECT 	did 			dispositionId
          		,	dispositionName	DispositionStatus
          	FROM 	disposition_status
          	WHERE 	domainId	= p_domainId ;
          
            	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory; 
          	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          	CREATE TEMPORARY TABLE temp_EmailHistory AS 	
          	SELECT 	FROM_UNIXTIME(SH.sessionStartTime/1000) as `dateTime`			
          			,	SH.FromEmail		
          			,	U.UserName				as agentName  		
          			,	SH.createdAt			as receivedOn
          			,	SH.assignedOn          
          			,	SH.repliedDate			as repliedOn
      				,	CASE WHEN SH.Istransferred = 1 THEN SH.transferredDate	ELSE null END	as transferredOn 
          			,	SH.discardedDate		as discardedOn
          			, 	SH.dispositionId
                     ,	SH.EmailSubject			as `subject`
          	FROM 	tb_EmailHistory 			SH
          	JOIN 	tb_EmailDurationHistory		SDH		ON SH.EmailHistoryId 	= SDH.EmailHistoryId
          	LEFT JOIN 	temp_AllagentId			U		ON U.UserID				= SDH.AgentId
          	LEFT JOIN temp_agentIDs 			t_A 	ON U.UserID  			= t_A.agentId       
          	LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
          	WHERE 	SH.domainId 			= p_domainId 	
            AND		SDH.IsBot = 0
          	AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
          	AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
          	AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));    
          	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          	
                
		DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_1; 	
		CREATE TEMPORARY TABLE temp_EmailHistory_1 AS 	    
   		SELECT 	*
   		FROM 	temp_EmailHistory
   		ORDER BY `dateTime` DESC 
   		LIMIT v_offset, p_Limit;    
               
   		DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
   		CREATE TEMPORARY TABLE temp_customer_contact
   		SELECT 	coid,primaryEmail,email,firstName,lastName      
   		FROM 	customer_contact 
   		WHERE 	domainId = p_domainId;
   
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;      
		DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_2;
   		CREATE TEMPORARY TABLE temp_EmailHistory_2
          	SELECT 	SH.`dateTime`
          		,	SH.agentName
          		,	SH.FromEmail		as customerEmailId
          		,	SH.receivedOn
          		,	SH.assignedOn
          		,	SH.repliedOn						
          		,	SH.transferredOn
          		,	SH.discardedOn
          		,	CASE WHEN t_A.DispositionStatus = 'Discarded' THEN 'Yes' ELSE 'No' END  as discarded
          		,	t_A.DispositionStatus					as disposition
   			,	SH.`subject`
          	FROM 	temp_EmailHistory_1			SH
          	LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId;
                                                   
   		ALTER TABLE temp_EmailHistory_2 ADD COLUMN customerName VARCHAR(150);        
           
           UPDATE 	temp_EmailHistory_2		EH
           JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryEmail	LIKE  EH.customerEmailId											
           SET 	customerName	= CONCAT(c_c.firstName, ' ',c_c.lastName);
           
           UPDATE 	temp_EmailHistory_2		EH        
           SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.email LIKE CONCAT('%',EH.customerEmailId,'%') ORDER BY InTC.coid LIMIT 1)
           WHERE 	IFNULL(customerName,'') = '';        
           
           UPDATE 	temp_EmailHistory_2		EH        
           SET 	customerName	= 'New Customer'
           WHERE 	IFNULL(customerName,'') = '';       
           
           DROP TEMPORARY TABLE IF EXISTS tt_temp_result_2;
		CREATE TEMPORARY TABLE tt_temp_result_2(
				dateTime 			DATE
				,agentName 			VARCHAR(255)
				,customerEmailId 	VARCHAR(100)
				,receivedOn 		DATETIME
				,assignedOn 		BIGINT
				,repliedOn 			DATETIME
				,transferredOn 		DATETIME
				,discardedOn 		DATETIME
				,discarded 			VARCHAR(3)
				,disposition 		VARCHAR(100)
				,subject 			VARCHAR(250)
				,customerName 		VARCHAR(150)
				);
                      
		   INSERT INTO tt_temp_result_2(dateTime,agentName,customerEmailId ,receivedOn,assignedOn,repliedOn,transferredOn,discardedOn,discarded,disposition,subject,customerName)
           SELECT DATE_FORMAT(dateTime,'%Y-%m-%d') as dateTime,agentName,customerEmailId ,receivedOn,assignedOn,repliedOn,transferredOn,discardedOn,discarded,disposition,subject,customerName
           FROM temp_EmailHistory_2;
          
			DROP TEMPORARY TABLE IF EXISTS tt_final_result;
			CREATE TEMPORARY TABLE tt_final_result AS
            SELECT a.sessionDate,a.agentName,a.agentId,a.totalReceived,a.totalOpened,a.totalHandled,a.totalTransferred,a.totalDiscarded,a.totalEmailHandlingTime
			,a.averageEmailHandlingTime,b.dateTime,b.customerEmailId,b.receivedOn,b.assignedOn,b.repliedOn,b.transferredOn,b.discardedOn,b.discarded
			,b.disposition,b.subject,b.customerName
			FROM tt_temp_result_1 a
			LEFT JOIN tt_temp_result_2 b ON a.agentName = b.agentName AND a.sessionDate = b.dateTime;
			                      
            SET @columns = '';
			SET @keyValuePairs = '';
			WHILE LOCATE(',', p_columnName) > 0 DO
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
									', ');
			SET p_columnName = SUBSTRING(p_columnName, LOCATE(',', p_columnName) + 1);
			END WHILE;
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_columnName,
									'\', ',
									p_columnName);

			SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM tt_final_result'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;

		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId;
          
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomReport_SMS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomReport_SMS`(
         	p_startTmpstmp 		BIGINT,
         	p_endTmpstmp 		BIGINT,
         	p_timeZone 			VARCHAR(200),
         	p_domainId 			INT,        
         	p_queueIDs	 		VARCHAR(250),
         	p_agentIDs 			VARCHAR(250),
         	p_dispositionIds	VARCHAR(250),
            p_direction			TINYINT,
         	p_offset 			INT,
         	p_Limit 			INT,
            p_columnName		TEXT,
            p_lastIsertId		INT
         )
BEGIN 
       	DECLARE v_offset 		INT;  	
       	DECLARE v_startTmpstmp 	BIGINT;
       	DECLARE v_endTmpstmp 	BIGINT;
       
       	SET v_offset = p_offset * p_Limit;
       
       	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
       	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									

       	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;		CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
       	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
               
       	CALL split(p_agentIDs,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
       	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
                 
  		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
  		CREATE TEMPORARY TABLE temp_AvailableDisposition 
  		(	dispositionId 		INT,
  			DispositionStatus 	VARCHAR(100)
  		);
    	 
  		INSERT INTO temp_AvailableDisposition 
  		SELECT 	did 			dispositionId
  			,	dispositionName	DispositionStatus
  		FROM 	disposition_status
  		WHERE 	domainId	= p_domainId;

    	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
    	CREATE TEMPORARY TABLE temp_AllagentId
    	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId ;
                 
			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			CREATE TEMPORARY TABLE temp_SMSHistory AS 		
			SELECT 	
			SH.sessionStartTime 	    AS `dateTime`			
			,	SH.customerNumber		
			,	SDH.AgentId 			AS agentId
			,	U.UserName				AS agentName
			,	SH.createdAt			AS receivedOn
			,	SH.assignedOn          
			,	SH.repliedDate			AS repliedOn
			,	CASE WHEN SH.Istransferred = 1 THEN SH.transferredDate	ELSE null END	AS transferredOn 
			,	SH.discardedDate		AS discardedOn
			, 	SH.dispositionId					
			FROM 	tb_SMSHistory 				SH
			JOIN 	tb_SMSDurationHistory		SDH		ON SH.SMSHistoryId 		= SDH.SMSHistoryId
			LEFT JOIN temp_AllagentId			U		ON U.UserID				= SDH.AgentId   
			LEFT JOIN temp_agentIDs 			t_A 	ON U.UserID  			= t_A.agentId       
			LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
			WHERE 	SH.domainId 			= p_domainId 	
			AND		SDH.IsBot=0
			AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp    
			AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
			AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                 
			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 	
			CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	    
			SELECT 	*
			FROM 	temp_SMSHistory
			ORDER BY `dateTime` DESC 
			LIMIT v_offset, p_Limit;
              
  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
  			DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
  			CREATE TEMPORARY TABLE temp_customer_contact
  			SELECT 	coid,primaryPhoneNumber,phoneNumber,firstName,lastName      
  			FROM 	customer_contact 
  			WHERE 	domainId = p_domainId;       
  			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
                 
  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
  			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_2;	
  			CREATE TEMPORARY TABLE temp_SMSHistory_2           
  		   SELECT 	SH.`dateTime`
  			
  				,	SH.customerNumber		
  				,	SH.agentId
  				,	SH.agentName
  				,	SH.receivedOn
  				,	SH.repliedOn
  				,	SH.assignedOn
  				,	SH.transferredOn
  				,	SH.discardedOn
  				,	t_A.DispositionStatus	disposition
  				,	SH.dispositionId
  		   FROM 	temp_SMSHistory_1			SH
  		   LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId;
  
  			ALTER TABLE temp_SMSHistory_2 ADD COLUMN customerName VARCHAR(150);        			
  			
  			UPDATE 	temp_SMSHistory_2		SH
  			JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryPhoneNumber	LIKE SH.customerNumber											
  			SET 	customerName	= CONCAT(c_c.firstName, ' ',c_c.lastName);
  
  			UPDATE 	temp_SMSHistory_2		SH        
  			SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT('%',SH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)				
  			WHERE 	IFNULL(SH.customerName,'') = '';        
  			
  			UPDATE 	temp_SMSHistory_2		SH        
  			SET 	customerName	= 'New Customer'
  			WHERE 	IFNULL(SH.customerName,'') = '';  
              
			DROP TEMPORARY TABLE IF EXISTS tt_temp_result_1;
			CREATE TEMPORARY TABLE tt_temp_result_1(
				 dateTime 		DATE
				,customerNumber BIGINT
				,agentId 		BIGINT
				,agentName 		VARCHAR(255)
				,receivedOn 	DATETIME
				,repliedOn 		DATETIME
				,assignedOn 	BIGINT
				,transferredOn 	DATETIME
				,discardedOn 	DATETIME
				,disposition 	VARCHAR(100)
				,dispositionId 	INT
				,customerName 	VARCHAR(150)
            );
            
			  INSERT INTO tt_temp_result_1(dateTime,customerNumber,agentId,agentName,receivedOn,repliedOn,assignedOn,transferredOn,discardedOn,disposition,dispositionId,customerName)
              SELECT CAST(FROM_UNIXTIME(dateTime/1000) AS DATE) AS dateTime,customerNumber,agentId,agentName,receivedOn,repliedOn,assignedOn,transferredOn,discardedOn,disposition,dispositionId,customerName
              FROM temp_SMSHistory_2 a;
                            
            	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId BIGINT);
            
            	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
               
				DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
				CREATE TEMPORARY TABLE temp_AllagentId
				select UserID,UserName from tb_User where domainId = p_domainId;

				DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
				CREATE TEMPORARY TABLE temp_AvailableDisposition 
				(   DispositionId 			INT
				  ,DispositionStatus 		VARCHAR(100)
				,DispositionCategory	TINYINT
				); 
				INSERT INTO temp_AvailableDisposition 
				SELECT 	did 			DispositionId
				,	dispositionName	DispositionStatus
				,	CASE	
						WHEN dispositionName = 'Transferred' THEN 1
						   WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
						   WHEN dispositionName = 'Discarded' THEN 4
						   ELSE 2
					END 			DispositionCategory
				FROM 	disposition_status
				WHERE 	domainId	= p_domainId;
				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

				DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
				CREATE TEMPORARY TABLE temp_SMSHistory AS 	
				SELECT 	
				UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE)) 					AS SessionDate
				,	U.UserName																				AS agentName   
				,	U.UserID																				AS agentId
				,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 									AS Opened
				,	CASE WHEN DispositionCategory = 1 THEN 1 ELSE 0 END 									AS Transferred  
				,	CASE WHEN DispositionCategory = 3 THEN 1 ELSE 0 END 									AS Handled
				,	CASE WHEN DispositionCategory = 4 THEN 1 ELSE 0 END 									AS Discarded

				,  SDH.Duration																			AS SMSHandlingTime             
				,  SH.afterSMSWorkTime*1000																AS afterSMSWorkTime
				FROM 	tb_SMSHistory 					SH
				JOIN 	tb_SMSDurationHistory			SDH	ON SH.SMSHistoryId 	= SDH.SMSHistoryId
				LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
				JOIN tb_User							U	ON U.UserID			= SDH.AgentId
				LEFT JOIN temp_agentId 					t_A ON U.UserID 		= t_A.agentId       
				WHERE 	SH.domainId 		= p_domainId 		
				AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
				AND		SH.IsInBound		= 1	
				AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
				DROP TEMPORARY TABLE IF EXISTS temp_agentId;
				DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;

			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
            
          	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_3;        	
          	CREATE TEMPORARY TABLE temp_SMSHistory_3 AS 	     
          	SELECT 	t_SH.SessionDate 															AS sessionDate
         		,	t_SH.agentName										
         		,	COUNT(1)																	AS totalReceived        
         		,	SUM(t_SH.Opened)															AS totalOpened
         		,	SUM(t_SH.Handled)															AS totalHandled
         		,	SUM(t_SH.Transferred)														AS totalTransferred
         		,	SUM(t_SH.Discarded)															AS totalDiscarded
         		,	round(SUM(t_SH.SMSHandlingTime+t_SH.afterSMSWorkTime))						AS totalSmsHandlingTime
         		,	round((SUM(t_SH.SMSHandlingTime+t_SH.afterSMSWorkTime)/COUNT(1)))   		AS averageSMSHandlingTime
   	   FROM 	temp_SMSHistory t_SH
   	   GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.agentId;   
   	   
		DROP TEMPORARY TABLE IF EXISTS tt_temp_result_2;
		CREATE TEMPORARY TABLE tt_temp_result_2(
			sessionDate 			DATE
			,agentName 				VARCHAR(255)
			,totalReceived 			BIGINT
			,totalOpened 			DECIMAL(33,2)
			,totalHandled 			DECIMAL(33,2)
			,totalTransferred 		DECIMAL(33,2)
			,totalDiscarded 		DECIMAL(33,2)
			,totalSmsHandlingTime 	DECIMAL(44,2)
			,averageSMSHandlingTime DECIMAL(44,2)
        );
        
        INSERT INTO tt_temp_result_2(sessionDate,agentName,totalReceived,totalOpened,totalHandled,totalTransferred,totalDiscarded,totalSmsHandlingTime,averageSMSHandlingTime)
		SELECT 	CAST(FROM_UNIXTIME(sessionDate) AS DATE) AS sessionDate,agentName,totalReceived,totalOpened,totalHandled,totalTransferred,totalDiscarded,totalSmsHandlingTime,averageSMSHandlingTime
		FROM 	temp_SMSHistory_3 a
		ORDER BY v_offset, p_Limit;  
          
 		DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId 		VARCHAR(100));
 		DROP TEMPORARY TABLE IF EXISTS temp_direction;	CREATE TEMPORARY TABLE temp_direction(directionId 	TINYINT);
 		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
         
 		CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;	
         CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
          
  		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  		CREATE TEMPORARY TABLE temp_AllagentId
  		select UserID,UserName from tb_User where domainId = p_domainId ; 
          
          IF p_direction IS NULL
          THEN
      		INSERT INTO temp_direction 
              (directionId)
              VALUES (0),(1);
      	ELSE
      		INSERT INTO temp_direction
              (directionId)
              SELECT p_direction;
          END IF;
          
          DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
          CREATE TEMPORARY TABLE temp_AlldirectionId
          select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
  								WHEN directionId = 1 THEN 'InBound' END AS directionName 
                                  FROM temp_direction ;
           
           DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
           CREATE TEMPORARY TABLE temp_AvailableDisposition 
           (	dispositionId 		INT,
              DispositionStatus 	VARCHAR(100)
           );
           
       	INSERT INTO temp_AvailableDisposition 
       	SELECT 	did 			dispositionId
       		,	dispositionName	DispositionStatus
       	FROM 	disposition_status
       	WHERE 	domainId	= p_domainId;
  
       	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	CREATE TEMPORARY TABLE temp_SMSHistory AS 	    	
      	
  			  SELECT 	
                 
                    FROM_UNIXTIME(SH.sessionStartTime/1000) as `timeFormat` 
                 ,	SH.customerNumber		           
                 ,	U.UserName				as agentName
				 ,	SH.IsInBound            as isInBound
                 ,	SH.sessionEndTime - SH.sessionStartTime	as totalDuration
                 ,	SH.dispositionId
                  ,	SH.afterSMSWorkTime		as ACWtime
       	    FROM 	tb_SMSHistory 				SH
        	JOIN 	tb_SMSDurationHistory		SDH		ON SH.SMSHistoryId 		= SDH.SMSHistoryId
            JOIN 	temp_direction				t_DIR	ON t_DIR.directionId	= SH.IsInBound
         	LEFT JOIN temp_AllagentId			U		ON U.UserID				= SDH.AgentId
         	LEFT JOIN temp_agentId	 			t_A 	ON U.UserID  			= t_A.agentId       
            LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
        	WHERE 	SH.domainId 			= p_domainId 		
        	AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
         	AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
            AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
        	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
          
      	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_4; 	
       	CREATE TEMPORARY TABLE temp_SMSHistory_4 AS 	    
      	SELECT 	*
      	FROM 	temp_SMSHistory
  		ORDER BY `timeFormat` DESC 
      	LIMIT v_offset, p_Limit; 
         
 		DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
 		CREATE TEMPORARY TABLE temp_customer_contact
 		SELECT 	coid,primaryPhoneNumber,phoneNumber,firstName,lastName      
 		FROM 	customer_contact 
 		WHERE 	domainId = p_domainId;        
          
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_2;
 		CREATE TEMPORARY TABLE temp_SMSHistory_2         
           SELECT SH.`timeFormat` as `dateTime`
      		
      		,	SH.customerNumber		
      		,	SH.agentName
 			,	CASE 	WHEN SH.IsInBound = 1 THEN 'InBound'
      					WHEN SH.IsInBound = 0 THEN 'OutBound'
      			END		as direction
      		,	round(SH.totalDuration/1000  )  as totalDuration    
			,	SH.ACWtime
      		,	t_A.DispositionStatus		disposition
           FROM 	temp_SMSHistory_4				SH
           LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId;
          
                                                     
 		ALTER TABLE temp_SMSHistory_2 ADD COLUMN customerName VARCHAR(150);      
                                                     
 		 UPDATE 	temp_SMSHistory_2		EH
         JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryPhoneNumber	LIKE  EH.customerNumber									
         SET 	EH.customerName	= CONCAT(c_c.firstName, ' ',c_c.lastName);
         
         UPDATE 	temp_SMSHistory_2		EH        
         SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT('%',EH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)
         WHERE 	IFNULL(EH.customerName,'') = '';        
         
         UPDATE 	temp_SMSHistory_2		EH        
         SET 	customerName	= 'New Customer'
         WHERE 	IFNULL(customerName,'') = '';         
         
         DROP TEMPORARY TABLE IF EXISTS tt_temp_result_3;
		 CREATE TEMPORARY TABLE tt_temp_result_3(
				dateTime 			DATE
				,customerNumber 	BIGINT
				,customerName 		VARCHAR(150)
				,agentName 			VARCHAR(255)
				,direction 			VARCHAR(8)
				,totalDuration 		DECIMAL
				,disposition 		VARCHAR(100)
				,ACWtime 			INT
         );
         
         INSERT INTO tt_temp_result_3(dateTime,customerNumber,customerName,agentName,direction,totalDuration,disposition,ACWtime)
         SELECT  DATE_FORMAT(dateTime,'%Y-%m-%d') AS dateTime,customerNumber,customerName,agentName,direction,totalDuration,disposition,ACWtime
         FROM temp_SMSHistory_2;
           
        DROP TEMPORARY TABLE IF EXISTS tt_final_result;
		CREATE TEMPORARY TABLE tt_final_result AS
        SELECT a.dateTime,a.customerNumber,a.agentName,a.receivedOn,a.repliedOn,a.assignedOn,a.transferredOn,a.discardedOn,a.disposition,a.dispositionId
        ,b.sessionDate,b.totalReceived,b.totalOpened,b.totalHandled,b.totalTransferred,b.totalDiscarded,b.totalSmsHandlingTime,b.averageSMSHandlingTime 
        ,c.customerName,c.direction,c.totalDuration,c.ACWtime
        FROM tt_temp_result_1 a
        LEFT JOIN tt_temp_result_2 b ON a.agentName = b.agentName 
        LEFT JOIN tt_temp_result_3 c ON b.agentName = c.agentName ;   
                   
        SET @columns = '';
			SET @keyValuePairs = '';
			WHILE LOCATE(',', p_columnName) > 0 DO
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
									', ');
			SET p_columnName = SUBSTRING(p_columnName, LOCATE(',', p_columnName) + 1);
			END WHILE;
			SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_columnName,
									'\', ',
									p_columnName);

			SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM tt_final_result'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;

		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId;
           
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     

  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getCustomReport_Voice` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getCustomReport_Voice`( 
	p_startTmpstmp 		BIGINT,
	p_endTmpstmp 		BIGINT,
	p_timeZone 			VARCHAR(200),
	p_domainId 			INT,
	p_queueIds	 		VARCHAR(250),
	p_agentIds 			VARCHAR(250),
    p_DispositionIds 	VARCHAR(250),
	p_TransferedId    	VARCHAR(250),
    p_voiceMail			VARCHAR(10),
    p_queueId 			TEXT,
    p_agentId 			TEXT,
    p_direction			TINYINT,
    p_columnName		TEXT,
	p_Limit 			INT,
	p_offset 			INT,
    p_lastIsertId		INT
)
BEGIN
                         		DECLARE v_offset 				INT;
                         		DECLARE v_Total_Count 			INT; 
                         		DECLARE v_startTmpstmp 			BIGINT;
                         		DECLARE v_endTmpstmp 			BIGINT;
     							Declare v_currentTmpstmp		BIGINT;
                                DECLARE v_voiceMail 	TINYINT;
 		
                         		SET v_offset 		 = p_Limit * p_offset; 
								SET v_currentTmpstmp = unix_timestamp(now(3))*1000;
                              
								IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
                         		IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  		
                                
                         		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId BIGINT);
                         		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
                         
                         		CALL split(p_agentIDs,',');	INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
                         		CALL split(p_queueIds,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable;
                           
                         		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
                         		CREATE TEMPORARY TABLE temp_AllqueueId
                         		SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
                         
                         		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                         		CREATE TEMPORARY TABLE temp_AllagentId
                         		SELECT UserID,UserName,ext, domainId FROM tb_User WHERE domainId = p_domainId ;
                         
                         		DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
                         		CREATE TEMPORARY TABLE tt_temp_sessionHistory AS 
                           		SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(CH.sessionStartTime/1000) AS DATE))*1000	AS SessionDate 
             						,CH.CallHistoryId
             						,CDH.CallDurationHistoryId
                         			,CDH.QueueId												AS queueId
                         			,CDH.AgentId												AS agentId
                         			,CH.IsInBound												AS IsInBound	
                         			,CDH.StartTime												AS agentconnecttime
                         			,CDH.EndTime												AS agentDisconnectTime
                         			,CH.callDuration											AS agentDuration
                         			,CDH.Duration												AS callDuration
                         			,CDH.AgentHoldDuration										AS agentHoldDuration
                         			,CDH.afterCallWorkTime										AS afterCallWorkTime
                         			
                                     ,CDH.transferedTo											AS transferedTo                        
                         			,CDH.UMNStatus												AS UMNStatus
                         			,CH.queueDuration											AS queueDuration
                                     ,CH.businessEndTime-CH.businessStartTime   				AS businessStartEndTime
                         		FROM 		tb_CallHistory 			CH
                         		JOIN 		tb_CallDurationHistory	CDH	ON CH.CallHistoryId = CDH.CallHistoryId        
                         		LEFT JOIN 	temp_queueIds 			t_Q ON CDH.QueueId		= t_Q.queueId  
                         		LEFT JOIN 	temp_agentIds 			t_A ON CDH.AgentId 		= t_A.agentId   
                                 LEFT JOIN 	tb_User				U	ON U.UserID			= CDH.AgentId
                         		WHERE 	CH.domainId 	= p_domainId 
                         		AND		CH.IsInBound	=	1   
                     			AND 	CDH.UMNStatus 	IN (1,2,3,4,5)
                         		AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
                         		AND 	(IFNULL(p_queueIds,'') 	= '' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL))
                         		AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
                                 
                         		DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
                         		CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
                         		SELECT 	SH.SessionDate,
                         				SH.queueId, 
                         				SH.agentId 
                                       ,sum(SH.callDuration)															    callDuration
                                         ,SUM(businessStartEndTime)                                                        businessStartEndTime     
                         				,SUM(CASE WHEN SH.IsInBound = 1 THEN 1 ELSE 0 END)									receivedCall
                         				,SUM(CASE WHEN SH.IsInBound = 1 AND SH.agentconnecttime > 0  THEN 1 ELSE 0 END) 	answeredCall
                         				,SUM(SH.callDuration-SH.agentHoldDuration)											totalTalktime
                               		
                         				,SUM(CASE WHEN SH.agentHoldDuration > 0 THEN 1 ELSE 0 END)							noOfCallHoldCount
                         				,SUM(SH.agentHoldDuration)															callHoldTime
                         				,SUM(SH.afterCallWorkTime) 															afterCallWorkTime
                         				
                                         ,SUM(CASE WHEN SH.transferedTo > 0 THEN 1 ELSE 0 END)								NoOfCallTransferred                            
                         		FROM 	tt_temp_sessionHistory SH
                         		GROUP BY SH.agentId,SH.queueId,SH.SessionDate; 
                                
    				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
  				CREATE TEMPORARY TABLE temp_AvailableStates AS
  				SELECT   
  						CASE 
  							WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
  							ELSE 2 
  						END AS tt_Time,
  						ST.ext,
  						ST.domainId,
  						from_unixtime(ST.startTimestamp/1000),
  						ST.stateDuration as SD
  				FROM     state_timer ST 
  				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
  				WHERE    ST.domainId = p_domainId
  				AND 	 ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;                              
                                

                                ALTER TABLE tt_sessionHistory_calc ADD COLUMN availableTime		BIGINT;
                                ALTER TABLE tt_sessionHistory_calc ADD COLUMN agentName			VARCHAR(150);        
                                                  
                              			UPDATE tt_sessionHistory_calc SH_C
 										JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
 										JOIN (
 											SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
 											FROM temp_AvailableStates
 											GROUP BY ext, domainId
 										) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
 										SET SH_C.availableTime 	= tt_AV.total_SD
                                         , 	agentName			= t_A.UserName;                                
 																									
				DROP TEMPORARY TABLE IF EXISTS tt_temp_result_1;
				CREATE TEMPORARY TABLE tt_temp_result_1(
						date DATE
						,queueName VARCHAR(255)
						,agentName VARCHAR(150)
						,receivedCall INT
						,answeredCall INT
						,answeredCallPer INT
						,totalTalktime DECIMAL(48,2)
						,averageTalktime DECIMAL(52,2)
						,averageHold DECIMAL(51,2)
						,totalACWtime DECIMAL(33,2)
						,averageACW DECIMAL(38,2)
						,AHT DECIMAL(54,2)
						,transferred DECIMAL(24,2)
						,transferper DECIMAL(28,2)
						,occupancyrate DECIMAL(51,2)
                );

            INSERT INTO tt_temp_result_1(date,queueName,agentName,receivedCall,answeredCall,answeredCallPer,totalTalktime,averageTalktime,averageHold
            ,totalACWtime,averageACW,AHT,transferred,transferper,occupancyrate)                    
			SELECT 	CAST(FROM_UNIXTIME(a.SessionDate/1000) AS DATE) AS `date`,
					t_Q.queueName AS queueName,
					a.agentName AS agentName,
					a.receivedCall AS receivedCall,
					a.answeredCall AS answeredCall,
					(a.answeredCall / NULLIF(a.receivedCall, 0)) * 100 AS answeredCallPer,
					(a.totalTalktime / 1000) AS totalTalktime,
					((a.totalTalktime / NULLIF(a.answeredCall, 0)) / 1000) AS averageTalktime,
					(a.callHoldTime / NULLIF(a.answeredCall, 0)) / 1000 AS averageHold,
					a.afterCallWorkTime AS totalACWtime,
					(a.afterCallWorkTime / NULLIF(a.answeredCall, 0)) AS averageACW,
					((a.totalTalktime + a.callHoldTime + (a.afterCallWorkTime * 1000)) / NULLIF(a.answeredCall, 0)) / 1000 AS AHT,
					a.NoOfCallTransferred AS transferred,
					ROUND((a.NoOfCallTransferred / NULLIF(a.answeredCall, 0)) * 100) AS transferper,
					((a.callDuration + (a.afterCallWorkTime * 1000)) / NULLIF(a.availableTime, 0)) * 100 AS occupancyrate
			FROM 	tt_sessionHistory_calc 	a
			JOIN 	temp_AllqueueId			t_Q	ON t_Q.qid = a.queueId
			ORDER BY a.SessionDate DESC;
			
            
			DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
        	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
         
        	CALL split(p_queueIds,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
        	CALL split(p_agentIds,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;    
            
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
            
    		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
            CREATE TEMPORARY TABLE temp_AllqueueId
            SELECT qid,name as queueName FROM queue WHERE domainId = p_domainId ;
            
            DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
            CREATE TEMPORARY TABLE temp_AllagentId
			SELECT  UserID,UserName FROM tb_User WHERE domainId = p_domainId; 
         	DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
         	CREATE TEMPORARY TABLE temp_sessionHistory as 
        	SELECT 	CH.sessionStartTime
    				,Q.qid																									AS queueId
        			,Q.`name`																								AS queueName
                    ,CDH.AgentId																							AS agentId
        			,U.UserName																								AS agentName	 		
        			,CH.customerNumber     
                    ,CASE WHEN trim(CONCAT(C_C.firstName, ' ',C_C.lastName)) <> ''  THEN CONCAT(C_C.firstName, ' ',C_C.lastName)	ELSE 'New Customer' END  AS customerName                            
        			,CH.queueDuration		
        	FROM 	tb_CallHistory 			CH
        	JOIN 	tb_CallDurationHistory	CDH	    ON CH.CallHistoryId = CDH.CallHistoryId
    		LEFT JOIN 	tb_User				U	    ON U.UserID			= CDH.AgentId
    		LEFT JOIN 	queue				Q	    ON CDH.QueueId		= Q.qid
			LEFT JOIN customer_contact		C_C	    ON C_C.coid			= CH.CustomerId
			LEFT JOIN temp_queueIDs 		t_Q     ON Q.qid			= t_Q.queueId 
			LEFT JOIN temp_agentIDs 		t_A     ON U.UserID 		= t_A.agentId   
    		WHERE 	CH.domainId 			= p_domainId 		
    		 AND 	CH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp 
    		 AND 	(IFNULL(p_queueIds,'') 	= '' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL))
    		 AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL))
    		 AND 	CDH.IsMissedCall		= 1;
          	
            DROP TEMPORARY TABLE IF EXISTS tt_temp_result_2;
			CREATE TEMPORARY TABLE tt_temp_result_2(
				dateTime		DATE
				,agentName		VARCHAR(255)
				,customerNumber	VARCHAR(20)
				,customerName	VARCHAR(201)
				,queueName		VARCHAR(255)
				,queueWaitingtime DECIMAL(25,2)

            );
            
            INSERT INTO tt_temp_result_2(dateTime,agentName,customerNumber,customerName,queueName,queueWaitingtime )
         	SELECT 	CAST(FROM_UNIXTIME(e.sessionStartTime/1000) AS DATE)  AS 	`dateTime`
      		  , e.agentName 		
      		  ,	e.customerNumber   
              ,	e.customerName
      		  ,	e.queueName 		
      		  ,	e.queueDuration/1000    AS queueWaitingtime
         	FROM temp_sessionHistory e
      	    ORDER BY e.sessionStartTime DESC ;
        
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
          
    		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory;
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;
    		DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;
           
          
           	DROP TEMPORARY TABLE IF EXISTS      temp_queueIds; 	    CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
           	DROP TEMPORARY TABLE IF EXISTS 		temp_agentIds;       CREATE TEMPORARY TABLE temp_agentIds(agentId VARCHAR(100));
           	DROP TEMPORARY TABLE IF EXISTS 		temp_DispositionId;	CREATE TEMPORARY TABLE temp_DispositionId(DispositionId VARCHAR(100));
           	DROP TEMPORARY TABLE IF EXISTS 		temp_TransferedId;	CREATE TEMPORARY TABLE temp_TransferedId(TransferedId VARCHAR(100));      
           
           	CALL split(p_queueIds,',');			INSERT INTO temp_queueIds(queueId) 				SELECT items FROM tt_Split_temptable;
           	CALL split(p_agentIds,','); 		INSERT INTO temp_agentIds(agentId) 				SELECT items FROM tt_Split_temptable;
           	CALL split(p_DispositionIds,','); 	INSERT INTO temp_DispositionId(DispositionId) 	SELECT items FROM tt_Split_temptable;
           	CALL split(p_TransferedId,','); 	INSERT INTO temp_TransferedId(TransferedId) 	SELECT items FROM tt_Split_temptable;
                    
           	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
           	CREATE TEMPORARY TABLE temp_AllqueueId 
           	SELECT qid,`name` as queueName from queue where domainId = p_domainId;
           
           	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
           	CREATE TEMPORARY TABLE temp_AllagentId
           	SELECT UserID , UserName  from tb_User where domainId = p_domainId ;
           
           	DROP TEMPORARY TABLE IF EXISTS temp_AllTransferedTypeId;
           	CREATE TEMPORARY TABLE temp_AllTransferedTypeId	
           	SELECT TypeCodeID,TypeCodeName FROM TypeCode WHERE TypeGroupID = 2002;
         
   		DROP TEMPORARY TABLE IF EXISTS temp_CallHistoryIds;
   		CREATE TEMPORARY TABLE temp_CallHistoryIds   
		SELECT 	CH.CallHistoryId		  				
		FROM 	tb_CallHistory 			CH		
		JOIN	tb_CallDurationHistory	CDH	ON CDH.CallHistoryId 	= CH.CallHistoryId    		
		LEFT JOIN temp_queueIds 		t_Q			ON CDH.QueueId			= t_Q.queueId 
		LEFT JOIN temp_agentIds 		t_A			ON CDH.AgentId 			= t_A.agentId   
		LEFT JOIN temp_TransferedId    	t_T 	ON CDH.transferredTypeId= t_T.TransferedId
		WHERE 	CH.domainId 				= p_domainId 
		AND 	CH.sessionStartTime 		BETWEEN v_startTmpstmp and v_endTmpstmp 
 		AND		EXISTS (SELECT 1 FROM tb_CallDurationHistory InCDH
   						WHERE 	InCDH.CallHistoryId = CDH.CallHistoryId 
 						AND 	InCDH.transferredTypeId 	= 2002002  )		
           AND 	(IFNULL(p_queueIds,'') 		= '' OR (IFNULL(p_queueIds,'') 		<> '' AND t_Q.queueId IS NOT NULL))
           AND 	(IFNULL(p_agentIds,'') 		= '' OR (IFNULL(p_agentIds,'') 		<> '' AND t_A.agentId IS NOT NULL))
           AND 	(IFNULL(p_TransferedId,'') 	= '' OR (IFNULL(p_TransferedId,'') 	<> '' AND t_T.TransferedId IS NOT NULL)) 
   		  GROUP BY CH.CallHistoryId;
             
             DROP TEMPORARY TABLE IF EXISTS temp_CallHistoryIdsWithAgent;
             CREATE TEMPORARY TABLE temp_CallHistoryIdsWithAgent
       		SELECT 	CH.CallHistoryId                                         
   				,	CDH.agentId
       		FROM 	temp_CallHistoryIds			CH		
           	JOIN	tb_CallDurationHistory	    CDH		ON CDH.CallHistoryId 	= CH.CallHistoryId
			GROUP BY CH.CallHistoryId, CDH.agentId;
            
           	DROP TEMPORARY TABLE IF EXISTS temp_TransferCallAgentDetails;
           	CREATE TEMPORARY TABLE temp_TransferCallAgentDetails	
           	SELECT 	CH.CallHistoryId
           		,	CH.sessionStartTime 												     		    
   				,	ROW_NUMBER() OVER (partition by CallHistoryId ORDER BY CDH.CallDurationHistoryId )	AgentOrder        
           		,	CH.Callduration
   				,	CH.CustomerId
   				,	CDH.AgentId
   				,	CDH.QueueId
           		,	CDH.transferedTo
           		,	CDH.AgentHoldDuration
           		,	CDH.afterCallWorkTime
           		,	CDH.Duration      
           	FROM 	temp_CallHistoryIdsWithAgent	CHs
   			JOIN 	tb_CallHistory 					CH	ON 	CHs.CallHistoryId	= CH.CallHistoryId
           	JOIN	tb_CallDurationHistory			CDH	ON 	CDH.CallHistoryId 	= CH.CallHistoryId
   														AND CDH.AgentId			= CHs.AgentId;
       
          	DROP TEMPORARY TABLE IF EXISTS temp_queueId; 
         	DROP TEMPORARY TABLE IF EXISTS temp_agentId; 
         	DROP TEMPORARY TABLE IF EXISTS temp_TransferedId;     
         
         	DROP TEMPORARY TABLE IF EXISTS temp_AgentOrder;
           	CREATE TEMPORARY TABLE temp_AgentOrder 
         	SELECT 	InTAD.CallHistoryId
         	,		MAX(InTAD.AgentOrder) LastestAgentOrder
         	FROM 	temp_TransferCallAgentDetails InTAD  
         	GROUP BY InTAD.CallHistoryId;
             
            
           	DROP TEMPORARY TABLE IF EXISTS temp_TransferCall;
           	CREATE TEMPORARY TABLE temp_TransferCall	
    		SELECT  TCA.CallHistoryId			
    			,	TCA.sessionStartTime 												     		            						
    			,	TCA.Callduration
    			,	LastestAgentOrder
    		FROM 	temp_TransferCallAgentDetails 	TCA
    		JOIN 	temp_AgentOrder					AO	ON AO.CallHistoryId	= TCA.CallHistoryId
    		WHERE 	AgentOrder	= 1
    		ORDER BY TCA.sessionStartTime DESC;
    		
           	DROP TEMPORARY TABLE IF EXISTS temp_AgentOrder;             
    		
           	DROP TEMPORARY TABLE IF EXISTS temp_TransferCallAgentDetails1;
           	CREATE TEMPORARY TABLE temp_TransferCallAgentDetails1    
         	SELECT 	TCA.CallHistoryId
           		  ,	TCA.Duration         
           		  ,	TCA.AgentHoldDuration
           		  ,	TCA.afterCallWorkTime
           		  ,	TCA.AgentId
           		  ,	TQ.queueName
           		  ,	TU.UserName		AS AgentName	
           		  , TCA.AgentOrder
            FROM 	temp_TransferCall				TC
            JOIN 	temp_TransferCallAgentDetails	TCA ON 	TC.CallHistoryId	= TCA.CallHistoryId
    												
    		JOIN 	temp_AllqueueId		    		TQ	ON 	TCA.QueueId			= TQ.qid
   		JOIN 	temp_AllagentId					TU	ON 	TCA.AgentId			= TU.UserID; 
            
         	DROP TEMPORARY TABLE IF EXISTS temp_TransferCallAgentDetails; 
          
         	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId; 
         	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId; 
         	DROP TEMPORARY TABLE IF EXISTS temp_AllTransferedTypeId; 
            
         	DROP TEMPORARY TABLE IF EXISTS temp_LastAgentDetails; 
   		CREATE TEMPORARY TABLE temp_LastAgentDetails 
   		SELECT 	TAD.CallHistoryId
   			,	queueName 
   			,	AgentId
   			,	AgentName
   			,	Duration
   			,	afterCallWorkTime
   		FROM 	temp_TransferCallAgentDetails1 	TAD 
   		JOIN 	temp_TransferCall				TC	ON 	TAD.CallHistoryId 	= TC.CallHistoryId
   													AND TAD.AgentOrder		= TC.LastestAgentOrder
   		WHERE 	TAD.CallHistoryId = TC.CallHistoryId; 	
               
         	DROP TEMPORARY TABLE IF EXISTS temp_AgentTimings; 
         	CREATE TEMPORARY TABLE temp_AgentTimings 
         	SELECT 	TAD.CallHistoryId
         		,	SUM(Duration)			TotalDuration
         		,	SUM(afterCallWorkTime)	TotalafterCallWorkTime  
         		,	SUM(AgentHoldDuration)	TotalAgentHoldDuration
         	FROM 	temp_TransferCallAgentDetails1 	TAD 
         	GROUP by TAD.CallHistoryId;
           
            DROP TEMPORARY TABLE IF EXISTS tt_temp_result_3;
			CREATE TEMPORARY TABLE tt_temp_result_3(
					dateTime				DATE
					,primaryQueue			VARCHAR(255)
					,primaryAgent			VARCHAR(255)
					,lastTransferredAgent	VARCHAR(255)
					,agentId				INT
					,totalHoldTime			DECIMAL(47,2)
            );
           
           
			INSERT INTO tt_temp_result_3(dateTime,primaryQueue,primaryAgent,lastTransferredAgent,agentId,totalHoldTime )   
               WITH CTE_PrimaryAgentDetails AS
           	(		SELECT 	CallHistoryId
    					   ,	queueName 
                           ,	AgentId
                           ,	AgentName
                           ,	Duration
                           ,	afterCallWorkTime
           			FROM 	temp_TransferCallAgentDetails1 InTAD   
         			WHERE 	InTAD.AgentOrder 	= 1
                  )
               SELECT 	
     				CAST(FROM_UNIXTIME(TC.sessionStartTime/1000) AS DATE) 	AS `dateTime`,	
                    PD.queueName											AS primaryQueue,
                    PD.AgentName											AS primaryAgent,
                    LD.AgentName		 					                AS lastTransferredAgent,
           			PD.AgentId												AS agentId,
           			AGT.TotalAgentHoldDuration/1000				            AS totalHoldTime
               FROM 	temp_TransferCall 		TC
               JOIN 	CTE_PrimaryAgentDetails	PD	ON TC.CallHistoryId = PD.CallHistoryId 
               JOIN 	temp_LastAgentDetails	LD	ON TC.CallHistoryId = LD.CallHistoryId
               JOIN 	temp_AgentTimings		AGT	ON TC.CallHistoryId = AGT.CallHistoryId;   
         
 		DROP TEMPORARY TABLE IF EXISTS temp_queueId; CREATE TEMPORARY TABLE temp_queueId(queueId INT);
 		DROP TEMPORARY TABLE IF EXISTS temp_agentId; CREATE TEMPORARY TABLE temp_agentId(agentId INT);

 		SET v_voiceMail	= 	CASE 	WHEN p_voiceMail LIKE '%Yes%' AND p_voiceMail LIKE '%No%' THEN 0 
 									WHEN IFNULL(p_voiceMail,'') LIKE '' 		THEN 0 
 									WHEN p_voiceMail LIKE '%Yes%' 	THEN 1
 									WHEN p_voiceMail LIKE '%No%' 	THEN 2
 							END;
       
 			CALL split(p_queueIds,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
 			CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
            
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;     
 			DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
 			CREATE TEMPORARY TABLE temp_AllqueueId
 			SELECT qid,name as queueName FROM queue WHERE domainId = p_domainId ;
                        
 			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
 			CREATE TEMPORARY TABLE temp_AllagentId
 			SELECT  UserID,UserName FROM tb_User WHERE domainId = p_domainId ; 
                        
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
 			DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
 			CREATE TEMPORARY TABLE temp_customer_contact
 			SELECT 	coid
 					,primaryPhoneNumber
 					,primaryEmail
 					,phoneNumber
 					,email
 					,facebook
 					,instagram
 					,firstName
 					,lastName      
 			FROM 	customer_contact 
 			WHERE 	domainId = p_domainId;       
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                      
    
 			DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
 			CREATE TEMPORARY TABLE tt_temp_sessionHistory as 
 			SELECT  
 					FROM_UNIXTIME(CH.sessionStartTime/1000)  as dateTime		  
 					, AB_U.UserName																													AS callDistributor
 					, case when CH.voicemailUrl is not null and CH.voicemailUrl<> '0' then 'yes' else 'No' end										AS voicemail
 					, CH.voiceMailDuration																											AS voicemailDuration
 					, CH.createdAt																													AS requestDateandtime
 					, Q.name																														AS queueName
 					, time_format(SEC_TO_TIME(CH.queueDuration / 1000),'%H:%i:%s')																	AS queueWaitingtime
 					, AT_U.UserName	        																									    AS agentName
 					, CASE WHEN CH.callBack= 1 THEN 'InCompleted'  WHEN  CH.callBack = 2 THEN 'Completed' ELSE  0 END  								AS callbackStatus
 					, CASE WHEN CH.callback= 2 AND CH.CallBackCallHistoryId IS NOT NULL Then CH.updatedAt Else null END								AS callbackDateandtime
 					, CH.customerNumber																												AS callbackphoneNumber
 					, CASE WHEN CH.callBack = 2	THEN CH.calledNumber ELSE '' END																	AS callbackQueuephoneNumber                  
 					, CDHY.Duration/1000   																											AS callBackduration
 					, CDHY.afterCallWorkTime																										AS afterCallWorkTime
 					, CH.callBack
 					, CH.CustomerId
 					, CH.customerNumber
                    , CDH.QueueId
                    , CDH.AgentId
                    , CH.voicemailUrl
 			FROM 	tb_CallHistory 				CH
 			LEFT JOIN	tb_CallHistory 			CC 		ON CC.CallHistoryId = CH.CallBackCallHistoryId
 			LEFT JOIN 	tb_CallDurationHistory	CDHY	ON CC.CallHistoryId = CDHY.CallHistoryId 
 			LEFT JOIN 	tb_CallDurationHistory	CDH		ON CH.CallHistoryId = CDH.CallHistoryId
 			LEFT JOIN 	queue					Q		ON CDH.QueueId		= Q.qid
 			LEFT JOIN 	customer_contact	   	C_C		ON C_C.coid 		= CH.CustomerId 
 			LEFT JOIN 	tb_User					AB_U	ON AB_U.UserID		= CH.assignedBy
 			LEFT JOIN 	tb_User			    	AT_U	ON AT_U.UserID		= CDH.AgentId    
 			WHERE 	CH.domainId 			= p_domainId 
 			AND 	CH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp            
			AND 	((CDH.QueueId in (select queueId from temp_queueId)) OR  (ifnull(p_queueIds,'')=''))
			AND 	((CDH.AgentId in (select agentId from temp_agentId)) OR  (ifnull(p_agentIds,'')=''));
    
 			UPDATE tt_temp_sessionHistory	SH 	
 			JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryPhoneNumber	= SH.customerNumber	
 			SET 	SH.CustomerId	= c_c.coid
 			WHERE IFNULL(SH.CustomerId,0)	= 0;   
            
 			ALTER TABLE tt_temp_sessionHistory ADD COLUMN CustomerName	VARCHAR(150);        
 			UPDATE 	tt_temp_sessionHistory		H 
 			LEFT JOIN 	customer_contact	    CC	ON H.CustomerId 		= CC.coid
 			SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''));
            
            DROP TEMPORARY TABLE IF EXISTS tt_temp_result_4;
			CREATE TEMPORARY TABLE tt_temp_result_4(
				DATE DATE
				,agentName VARCHAR(255)
				,callDistributor VARCHAR(255)
				,voicemail VARCHAR(3)
				,voicemailDuration BIGINT
				,requestDateandtime DATETIME
				,callbackDateandtime DATETIME
				,callbackStatus VARCHAR(11)
				,callbackphoneNumber VARCHAR(20)
				,callbackQueuephoneNumber VARCHAR(20)
				,callBackduration DECIMAL(26,2)
            );
            
            
            INSERT INTO tt_temp_result_4(DATE,agentName,callDistributor,voicemail,voicemailDuration,requestDateandtime ,callbackDateandtime,callbackStatus,callbackphoneNumber
			,callbackQueuephoneNumber,callBackduration)
 			SELECT 	
 					CAST(dateTime AS DATE) AS DATE, 
                    agentName,
 					callDistributor, 
 					voicemail, 
 					voicemailDuration,
 					requestDateandtime, 
                    callbackDateandtime, 
 					callbackStatus, 
 					callbackphoneNumber, 
 					callbackQueuephoneNumber,
 					callBackduration + afterCallWorkTime                              AS callBackduration
 			FROM 	tt_temp_sessionHistory
            where (voicemail COLLATE utf8mb4_0900_ai_ci = p_voiceMail or ifnull(p_voiceMail,'')='')
 			ORDER BY  dateTime ;
			        
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
          
			DROP TEMPORARY TABLE IF EXISTS temp_queueId;  				CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_agentId;				CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
            DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_direction;				CREATE TEMPORARY TABLE temp_direction(directionId 	TINYINT);
			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; 	CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
          
            CALL split(p_queueId,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
			CALL split(p_agentId,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
            CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) 	SELECT Items FROM tt_Split_temptable;
          
        		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
        		CREATE TEMPORARY TABLE temp_AllqueueId
				SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
        		
        		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
        		CREATE TEMPORARY TABLE temp_AllagentId
        		select UserID,UserName from tb_User where domainId = p_domainId;  
              
      	IF p_direction IS NULL
               THEN
           		INSERT INTO temp_direction 
                   (directionId)
                   VALUES (0),(1);
           	ELSE
           		INSERT INTO temp_direction
                   (directionId)
                   SELECT p_direction;
               END IF;
                 DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
               CREATE TEMPORARY TABLE temp_AlldirectionId
               select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
       								   WHEN directionId = 1 THEN 'InBound' END AS directionName 
      								   FROM temp_direction ;      
               INSERT INTO temp_AvailableDisposition 
         		SELECT 	did 			dispositionId
         			,	dispositionName	DispositionStatus
         		FROM 	disposition_status
         		WHERE 	domainId	= p_domainId;              
              
              
         		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
         		CREATE TEMPORARY TABLE temp_sessionHistory AS 
				SELECT 	CH.sessionStartTime
					, 	CH.customerNumber
					,	CH.CustomerId
					,	Q.queueName							queueName
					,	U.UserName						    agentName
					, 	CH.callDuration
					, 	CASE WHEN IFNULL(c_c.firstName,'') = '' THEN 'New Customer' ELSE CONCAT(c_c.firstName,' ' ,c_c.lastName) END 				as customerName
					, 	CDH.afterCallWorkTime
					, 	DS.dispositionName  			    AS disposition
                    ,	CDH.QueueId
                    ,	CDH.AgentId
                    ,	CDH.dispositionId
				FROM tb_CallHistory		 			CH 
				JOIN tb_CallDurationHistory			CDH		ON CH.CallHistoryId = CDH.CallHistoryId
				LEFT JOIN temp_AllqueueId			Q		ON CDH.QueueId		= Q.queueId
				LEFT JOIN temp_AllagentId			U		ON U.UserID			= CDH.AgentId   
				JOIN customer_contact		   		c_c		ON c_c.coid 		= CH.CustomerId  
				LEFT JOIN disposition_status        DS   	ON DS.domainId 		= CH.domainId				AND CDH.dispositionId	= DS.did  
				WHERE 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp 
				AND 	CH.IsInBound			= 0
				AND 	CH.domainId 			= p_domainId 	
                AND 	((CDH.QueueId in (select queueId from temp_queueId)) OR  (ifnull(p_queueId,'')=''))
                AND 	((CDH.AgentId in (select agentId from temp_agentId)) OR  (ifnull(p_agentId,'')=''))
                AND 	((CDH.dispositionId in (select dispositionId from temp_dispositionIds)) OR  (ifnull(p_dispositionIds,'')=''))
				ORDER BY sessionStartTime DESC ;
                
                DROP TEMPORARY TABLE IF EXISTS tt_temp_result_5;
				CREATE TEMPORARY TABLE tt_temp_result_5(
					date				DATE
					,callDuration		BIGINT
					,disposition		VARCHAR(100)
					,totalDuration		BIGINT
					,agentName			VARCHAR(250)
                );
                
                INSERT INTO tt_temp_result_5(date,callDuration,disposition,totalDuration,agentName)
         		SELECT  CAST(FROM_UNIXTIME(e.sessionStartTime/1000) AS DATE) 						as `date`
					,  	e.callDuration 							as callDuration
                    ,   e.disposition
                    ,	e.callDuration  						as totalDuration 
         		 	,	e.agentName 							as agentName
         		 FROM  	temp_sessionHistory 		e; 
			
			 
            
			DROP TEMPORARY TABLE IF EXISTS tt_final_result;
			CREATE TEMPORARY TABLE tt_final_result AS
            SELECT a.date,a.queueName,a.agentName,a.receivedCall,a.answeredCall,a.answeredCallPer,a.totalTalktime,a.averageTalktime,a.averageHold,a.totalACWtime,a.averageACW
				,a.AHT,a.transferred,a.transferper,a.occupancyrate
				,b.dateTime,b.customerNumber,b.customerName,b.queueWaitingtime
				,c.primaryQueue,c.primaryAgent,c.lastTransferredAgent,c.agentId,c.totalHoldTime
				,d.callDistributor,d.voicemail,d.voicemailDuration,d.requestDateandtime,d.callbackDateandtime,d.callbackStatus,d.callbackphoneNumber,d.callbackQueuephoneNumber,d.callBackduration
				,e.callDuration,e.disposition,e.totalDuration FROM tt_temp_result_1 a
			LEFT JOIN tt_temp_result_2 b ON a.agentName = b.agentName AND a.date = b.dateTime
			LEFT JOIN tt_temp_result_3 c ON b.agentName = c.primaryAgent AND b.dateTime = c.dateTime
			LEFT JOIN tt_temp_result_4 d ON c.primaryAgent = d.agentName AND c.dateTime = d.DATE
			LEFT JOIN tt_temp_result_5 e ON d.agentName = e.agentName AND d.DATE = e.date;
            
		SET @columns = '';
		SET @keyValuePairs = '';
		WHILE LOCATE(',', p_columnName) > 0 DO
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_columnName, ',', 1)),
										', ');
		SET p_columnName = SUBSTRING(p_columnName, LOCATE(',', p_columnName) + 1);
		END WHILE;
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_columnName,
									'\', ',
									p_columnName);

		SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM tt_final_result'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;

		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId;
END ;;
DELIMITER ;
