CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getDidNumberbyCallFlowId`(
     p_domainId          INT,
     p_MainTrunkNumber   VARCHAR(255)
 )
BEGIN
     DECLARE v_errcode INT;
     DECLARE v_errmsg VARCHAR(50);
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     IF EXISTS (
         SELECT 1
         FROM callMap 
         WHERE domainId = p_domainId AND sourceId = p_MainTrunkNumber COLLATE utf8mb4_unicode_ci
     )
     
     THEN
         SET v_errcode = -1;
         SET v_errmsg = 'Number Mapped';
     ELSE
         SET v_errcode = 0;
         SET v_errmsg = 'Number Not Mapped';
     END IF;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
