CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getDidPurchaseByDomainID`(
  p_domainId	 INT
  )
begin
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 select web_id,baseName,websiteId,a.* from did_purchase a 
 left join websiteScraper b on a.domainId = b.domainId and a.knowledgeBasedId = b.web_id
 where a.domainId = p_domainId order by createdAt desc;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  end ;;
