DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_GetdoNotDisturbCustomerDetails_info`(
   p_domainId int
   )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	b.UserName as UserName
 		,	a.coid
 		,	a.firstName
 		,	a.lastName				
 		,	JSON_ARRAY_INSERT(a.phoneNumber,'$[0]',a.primaryPhoneNumber)	phoneNumber				
 		,	JSON_ARRAY_INSERT(a.email,'$[0]',a.primaryEmail)				email
 		,	a.accountNumber
 		,	a.tags
 		,	a.location
 		,	a.address
 		,	a.country
 		,	a.state
 		,	a.city
 		,	a.postalCode
 		,	a.facebook
 		,	a.instagram
 		,	a.whatsapp
 		,	a.twitter
 		,	a.createdAt
 		,	a.updatedAt
 		,	a.voiceBiometric
 		,	a.domainId
 		,	a.mergeCustomer
 		,	a.blockCustomer
 		,	a.doNotDisturb
 		,	a.blockCustomerReq
 		,	a.doNotDisturbReq
 		,	a.`type`
 		,	a.currentCustomerNumber
 		,	a.customerType
 		,	a.Timezone
 		,	a.blockedBy
 		,	a.doNotDisturbBy
 		,	a.blockedReqBy
 		,	a.doNotDisturbReqBy
 		,	a.Reason
 		,	a.cookiesId
 		,	a.`Source`  
     FROM 	customer_contact 	a 
     join 	tb_User 			b 	on 	a.doNotDisturbBy = b.UserID 
 									and a.domainId = b.domainId
 	WHERE 	doNotDisturb 			= 1 
    AND 	JSON_VALID(a.phoneNumber) = 1
	AND 	JSON_VALID(a.email) 		= 1
    AND 	a.domainId 				= p_domainId;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
