CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getIsBot`(
   p_yourNumber VARCHAR(255),
   p_domainId	 INT
   )
begin
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	select isBot,knowledgeBasedId,websiteId,autoAssignAgent 
    from 	did_purchase 		a
	LEFT JOIN 	websiteScraper 	b 	on 	a.domainId 			= b.domainId 
									and a.knowledgeBasedId 	= b.web_id
	where your_number = p_yourNumber and a.domainId = p_domainId;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
end ;;
