CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getknowledgeBasedIdByEmailId`(
     p_emailid varchar(100)
     )
begin
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	web_id,websiteId,baseName,websiteId,a.* 
            ,(	SELECT 	group_concat(U.ext)
				FROM 	tb_User U
                WHERE 	a.supervisorName like concat('%',U.UserID,'%')
                )	ext
	FROM 	email_config 		a
 	LEFT JOIN websiteScraper 	b 	ON 	a.domainId 		= b.domainId 
									AND a.knowledgeBasedId = b.web_id
 	where emailAddress = p_emailid;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 end ;;
