/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getparticularAgentStatusReport`(
     p_startTmpstmp  BIGINT,
     p_endTmpstmp    BIGINT,
     p_domainId      INT,
     p_agentId       TEXT,
     p_statusName	 VARCHAR(250),
     p_Limit         INT,
     p_Offset        INT
 )
BEGIN
     DECLARE v_offset        				INT;
     DECLARE v_Total_Count   				INT;
     DECLARE v_startTmpstmp  				BIGINT;
     DECLARE v_endTmpstmp    				BIGINT;
     DECLARE v_ext    						INT;
     DECLARE v_totalLoginDuration    		BIGINT;
 
     SET v_offset = p_Limit * p_Offset; 
 
	SET v_startTmpstmp 	= p_startTmpstmp; 
	SET v_endTmpstmp 	= p_endTmpstmp; 
	
    SELECT ext INTO v_ext 
    FROM tb_User 
    WHERE domainId = p_domainId
    AND UserID = p_agentId;
 
     DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
     CREATE TEMPORARY TABLE temp_AvailableState AS
     SELECT  
		U.UserName,
		a.statusName,
		IFNULL(ST.stateDuration,TIMESTAMPDIFF(SECOND,FROM_UNIXTIME(ST.startTimestamp/1000),(NOW())) * 1000) as LoginDuration,
		DATE_FORMAT(FROM_UNIXTIME(ST.startTimestamp/1000),'%Y-%m-%d %H:%i:%s') AS startDateTime,
		IFNULL(DATE_FORMAT(FROM_UNIXTIME(ST.endTimestamp/1000),'%Y-%m-%d %H:%i:%s'),DATE_FORMAT(NOW(),'%Y-%m-%d %H:%i:%s')) AS endDateTime
	FROM 	state_timer ST 
	JOIN 	agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
    JOIN 	tb_User U ON U.ext = ST.ext AND U.domainId = a.domainId
	WHERE 	ST.domainId = p_domainId
    AND	 	ST.ext = v_ext
	AND 	ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;
    
     SELECT ROUND(SUM(LoginDuration)) INTO v_totalLoginDuration
     FROM temp_AvailableState;
     
	SELECT UserName,statusName,LoginDuration,startDateTime,endDateTime 
    FROM temp_AvailableState
    WHERE (IFNULL(p_statusName,'') = '' OR statusName collate utf8mb4_0900_ai_ci = p_statusName)
    ORDER BY startDateTime DESC; 
          
		SET SESSION group_concat_max_len = 1000000;

		SELECT 
			GROUP_CONCAT(
				DISTINCT 
				CONCAT(
					'SUM(CASE WHEN statusName = ''',
					statusName,
					''' THEN ROUND(LoginDuration) ELSE 0 END) AS `',
					statusName,
					'`'
				)
			) INTO @sql_columns
		FROM temp_AvailableState;

		IF @sql_columns IS NOT NULL THEN

			SET @sql = CONCAT(
				'SELECT ',
				@sql_columns,
				', ROUND(SUM(LoginDuration)) AS TotalLoginDuration ',
				'FROM temp_AvailableState;'
			);

			PREPARE stmt FROM @sql;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;

		ELSE
			SELECT '-1' AS errcode ,'No data found' AS errmsg;
		END IF;

		select statusName from agent_status where domainId = p_domainId;
    
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
