/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getPersonalDetails`( 	
		p_email 	VARCHAR(100)
    	,p_domainId	INT	
  )
BEGIN
  	DECLARE v_coid 	BIGINT;
      
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	coid INTO v_coid
	FROM 	customer_contact
    WHERE 	primaryEmail	= p_email
    AND 	domainId		= p_domainId
    AND 	JSON_VALID(phoneNumber) = 1
	AND 	JSON_VALID(email) 		= 1;    
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      IF v_coid IS NULL
      THEN
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT 	coid INTO v_coid
  		FROM 	customer_contact
  		WHERE 	email 		LIKE CONCAT('%',p_email,'%')
  		AND 	domainId	= p_domainId
        AND 	JSON_VALID(phoneNumber) = 1
		AND 	JSON_VALID(email) 		= 1
		ORDER BY coid LIMIT 1;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      END IF;
      
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	a.coid
  		,	a.firstName
  		,	a.lastName				
 		,	IF(IFNULL(a.primaryPhoneNumber,'')='',a.phoneNumber, JSON_ARRAY_INSERT(a.phoneNumber,'$[0]',a.primaryPhoneNumber))	phoneNumber				
 		,	IF(IFNULL(a.primaryEmail,'')='',a.email,JSON_ARRAY_INSERT(a.email,'$[0]',a.primaryEmail))							email        
  		,	a.accountNumber
  		,	a.tags
  		,	a.location
  		,	a.address
  		,	a.country
  		,	a.state
  		,	a.city
  		,	a.postalCode
  		,	a.facebook
  		,	a.instagram
  		,	a.whatsapp
  		,	a.twitter
  		,	a.createdAt
  		,	a.updatedAt
  		,	a.voiceBiometric
  		,	a.domainId
  		,	a.mergeCustomer
  		,	a.blockCustomer
  		,	a.doNotDisturb
  		,	a.blockCustomerReq
  		,	a.doNotDisturbReq
  		,	a.`type`
  		,	a.currentCustomerNumber
  		,	a.customerType
  		,	a.Timezone
  		,	a.blockedBy
  		,	a.doNotDisturbBy
  		,	a.blockedReqBy
  		,	a.doNotDisturbReqBy
  		,	a.Reason
  		,	a.cookiesId
  		,	a.`Source` 
  	FROM 	customer_contact a
  	WHERE 	a.coid 					= v_coid
    AND 	JSON_VALID(phoneNumber) = 1
	AND 	JSON_VALID(email) 		= 1;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;       
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
