/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getProfileInformation`(
 p_ext 		int
,p_domainId int
)
BEGIN

SELECT
    u.UserName AS agentName,
    a.statusName,
    r.name AS routingProfile,
    group_concat(sk.skill_name separator ',') AS Skills,
    CONCAT(
        CASE WHEN u.voice = 1 THEN 'Voice' ELSE '' END,
        CASE WHEN u.chat = 1 THEN CONCAT(',', 'Chat') ELSE '' END,
        CASE WHEN u.email = 1 THEN CONCAT(',', 'Email') ELSE '' END,
        CASE WHEN u.sms = 1 THEN CONCAT(',', 'SMS') ELSE '' END,
        CASE WHEN u.socialMedia = 1 THEN CONCAT(',', 'Social Media') ELSE '' END
    ) AS tag,
    s.UserName AS ReportingTo,
    u.directNumber AS DIDNumber,
    u.emailId AS EmailAddress,
    u.ext AS Extension
FROM
    tb_User u
JOIN routing_profile r 	ON u.routing_profile_id = r.rid
JOIN tb_User 		 s 	ON s.UserID 			= u.report_to_UserID
JOIN skills 		 sk ON sk.domainId 			= u.domainId
JOIN agent_status    a	ON a.aid				= u.StatusID

WHERE   u.ext = p_ext
AND 	u.domainId = p_domainId
group by u.UserName,a.statusName,r.name,s.UserName,u.directNumber,u.emailId,u.ext,u.voice,u.chat,u.email,u.sms,u.socialMedia;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
