CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getRoleIdList_info`(
 p_domainId int,
 p_report_to int
 )
Begin
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT * from tb_User where domainId = p_domainId AND report_to_UserID = p_report_to;
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
 End ;;
