CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getRoutingProfileListInfo`(
   p_domainId                                       INT,
   p_rid   											INT,   
   p_offset                                         INT, 
   p_Limit                                          INT
   )
Begin
   
	 DECLARE v_offset 				INT;	
      SET v_offset =  p_Limit * p_offset;
     
   
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         	SELECT rid, name, description, default_outbound_queue, No_of_linked_queues, status,routingMethod, concurrentChat, type
             FROM routing_profile
             WHERE domainId=p_domainId
          
             AND  (IFNULL(p_rid,0)=0 or rid = p_rid)
             ORDER BY rid DESC
 			LIMIT 	 v_offset, p_Limit; 
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
