DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getSearchList_info`(
 p_domainId int
 )
Begin
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	select a.rid,a.name as routing_prof_name,a.No_of_linked_queues as No_of_linkedqueue,a.status,a.description,a.default_outbound_queue,a.routingMethod,a.createdAt,a.updatedAt,a.domainId,
 a.type, (select count(b.routing_profile_id) from tb_User b where b.routing_profile_id=a.rid and b.domainId=a.domainId) as no_of_agent 
 from routing_profile a  where a.domainId=p_domainId group by a.rid,a.name order by a.rid desc;
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
 end ;;
DELIMITER ;
