CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getTokenByConId`(
 	p_conid INT
     
 )
begin
 
 	SELECT   a.connectorChildId,a.conid,a.domainId,a.connection,a.contactSyncDetails,a.syncStatus,a.syncTime,a.contactSyncType
 	,a.isConnected,a.createdDate,a.updatedDate,b.token, b.connector_name FROM  tb_ConnectorChild a
 	JOIN ccaas_crm_connector_token_info b ON a.domainId = b.domainId AND a.conId = b.conId  
 	WHERE  a.conId = p_conid
 	AND a.isConnected = 1 AND b.isConnected = 1
 	AND a.syncStatus  = 1 AND b.syncStatus = 1;
     
 end ;;
DELIMITER ;
