CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_GetUserAvaiableStatus`(
 p_domainId int
 )
Begin
 	declare v_found int;
     declare v_status varchar(20);
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	select count(*) into v_found from agent_status a join tb_User b on a.aid = b.StatusID and a.domainId = b.domainId
 	where b.domainId = p_domainId and a.statusName in ('Ready','Transfer Only','Busy','Away','vacation');
     
     if v_found = 0 then
 		set v_status = 'Unavailable';
 	Else
 		set v_status = 'Busy';
     End if;
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 	select v_status as userStatus;
 
 End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
