CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_getUserDetailsEmail_info`(
  p_domainId int,
  p_emailId varchar(50)
  )
Begin
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		SELECT u.* ,ual.pri_language,ual.sec_language
		FROM tb_User u
		LEFT JOIN tb_userAddonLanguageInfo ual ON u.UserID = ual.userId
		WHERE u.domainId = p_domainId 
		AND (u.emailId = p_emailId or emp_id = p_emailId);
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  End ;;
