DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getUserDetailsList_info`(
    p_domainId int,
    p_UserID int 
    )
Begin
    
		declare v_reporting_to_name varchar(100);
		declare v_reporting_to_userid int;
        
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        
		select report_to_UserID into v_reporting_to_userid from tb_User where domainId = p_domainId and UserID = p_UserID;

		select UserName into v_reporting_to_name from tb_User where domainId = p_domainId and UserID = v_reporting_to_userid;
      
       SELECT v_reporting_to_name as reporting_to_name,b.name as routing_profile_name
		,ual.pri_language as primaryLanguage,ual.sec_language as secondaryLanguage
		,a.UserID,a.UserName,a.emailId,a.directNumber,a.address,a.routing_profile_id,a.report_to_UserID,a.sipLoginId,a.companyId
		,a.domainId,a.ext,a.isActive,a.callTypeId,a.inboundCall,a.outboundCampaignCall,a.roleid,a.localization,a.currentSession
		,a.isVoice,a.isVoiceCallTransfer,a.isAvailableForVoice,a.isChat,a.isChatTransfer,a.isEmail,a.isEmailTransfer,a.StatusID
		,a.isSms,a.isSocialMedia,a.companyName
        ,(SELECT JSON_ARRAYAGG(
        JSON_OBJECT(
            'skid', sk.sid,
            'value', sk.skill_name,
            'type', sk.type
				)
			)
		FROM skills sk
		JOIN skillMapping sm ON sk.sid = sm.skid
		WHERE sk.domainId = a.domainId
		AND sm.usid = a.UserID) AS addSkill
        ,a.voice,a.chat,a.email,a.sms,a.socialMedia,a.chatLimit,a.createdAt,a.updatedAt
		,a.stateTimer,a.AssignedTime,a.chatFlag,a.ProfileImage,a.emp_id,a.queueId
       FROM tb_User a 
       LEFT JOIN routing_profile b on b.rid = a.routing_profile_id and a.domainId = b.domainId
       LEFT JOIN tb_userAddonLanguageInfo ual on a.UserID = ual.userId
       WHERE a.domainId = p_domainId AND a.UserID = p_UserID;
       
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_getUserId` */;
