DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getUserListByRoleHandler`(
            p_domainId INT,
            p_roleId 	VARCHAR(25) 
       )
BEGIN     
            
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            SELECT tu.UserID
       		,	tu.UserName
       		,	tu.emailId
       		,	tu.directNumber
       		,	tu.address
       		,	tu.routing_profile_id
       		,	tu.report_to_UserID
       		,	tu.sipLoginId
       		,	tu.companyId
       		,	tu.domainId
       		,	tu.ext
       		,	tu.isActive
       		,	tu.callTypeId
       		,	tu.roleid
       		,	tu.localization
       		,	tu.currentSession		
       		,	tu.isVoiceCallTransfer
       		,	tu.isAvailableForVoice
       		,	ag.isChat
       		,	tu.isChatTransfer
       		,	tu.isEmail
       		,	tu.isEmailTransfer
       		,	tu.StatusID
       		,	tu.isSms
       		,	tu.isSocialMedia
       		,	tu.companyName
       		,	tu.addSkill
       		,	tu.voice
       		,	tu.chat
       		,	tu.email
       		,	tu.sms
       		,	tu.socialMedia
       		,	tu.chatLimit 
       		,	tu.stateTimer
       		,	tu.AssignedTime
       		,	tu.chatFlag
       		,	'' 				AS routing_profile_name
       		,	tus.UserName 			AS report_to_name
       		, 	statusName
       		,	tus.chatLimit
       		, 	ag.isVoiceCallTransfer 	AS isVoiceCallTransfer_AgentStatus
       		, 	ag.isChatTransfer      	AS isChatTransfer_AgentStatus
       		, 	ag.isEmailTransfer     	AS isEmailTransfer_AgentStatus
       		, 	ag.isVoice
			,	'' as routingMethod
  			,(	SELECT GROUP_CONCAT(InG.GroupName)
      				FROM 	tb_TicketGroup				InG
      				JOIN 	tb_TicketGroupUserMapping 	InGU	ON 	InG.TicketGroupId 	= InGU.TicketGroupId
      															AND	InGU.UserId			= tu.UserID
    			WHERE InG.IsDeleted = 0) as GroupName
			,tu.ProfileImage as ProfileImage
			,ual.pri_language as primaryLanguage,ual.sec_language as secondaryLanguage
			,tu.inboundCall
			,tu.outboundCampaignCall
			,	group_concat(tu.queueId) as quId
            FROM tb_User 				tu			
            LEFT JOIN agent_status 		ag  ON ag.aid					= tu.StatusID
            LEFT JOIN tb_User			tus ON tus.UserID 				= tu.report_to_UserID 
            LEFT JOIN tb_userAddonLanguageInfo ual ON tu.UserID = ual.userId AND ual.ext = tu.ext
            WHERE  tu.domainId = p_domainId
            AND (tu.roleid in (3,5,6))
            GROUP BY tu.UserID ,	tu.UserName,	tu.emailId,	tu.directNumber,	tu.address,	tu.routing_profile_id,	tu.report_to_UserID,	tu.sipLoginId,	tu.companyId,	tu.domainId
 			,	tu.ext,	tu.isActive,	tu.callTypeId,	tu.roleid,	tu.localization,	tu.currentSession		,	tu.isVoiceCallTransfer,	tu.isAvailableForVoice,	ag.isChat,	tu.isChatTransfer
 			,	tu.isEmail,	tu.isEmailTransfer,	tu.StatusID,	tu.isSms,	tu.isSocialMedia,	tu.companyName,	tu.addSkill,	tu.voice,	tu.chat,	tu.email,	tu.sms,	tu.socialMedia,	tu.chatLimit 
 			,	tu.stateTimer,	tu.AssignedTime,	tu.chatFlag,		tus.UserName, 	statusName,	tus.chatLimit, 	ag.isVoiceCallTransfer , 	ag.isChatTransfer, 	ag.isEmailTransfer, 	ag.isVoice
             ,	tu.ProfileImage,	ual.pri_language,	ual.sec_language,	tu.inboundCall,	tu.outboundCampaignCall;
            
       	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
        end ;;
DELIMITER ;
