CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getUserListByRoleId`(
    IN p_domainId INT,
    IN p_roleId VARCHAR(25),
    IN p_DynamicColumns VARCHAR(2000)
)
BEGIN
    DECLARE v_roleId VARCHAR(25);
    DECLARE v_DynamicColumns VARCHAR(2000);
    DECLARE v_DB VARCHAR(50);
    DECLARE v_allRollId	 VARCHAR(100);

    SET v_roleId = IFNULL(p_roleId, 'roleid');
    
    IF p_roleId IS NULL THEN 
		SET v_allRollId = (SELECT group_concat(distinct(roleid) separator ',') FROM tb_User WHERE domainId = p_domainId);
	END IF;
    
    
    IF p_DynamicColumns IS NOT NULL THEN
        SET v_DynamicColumns = CONCAT('roleid,', p_DynamicColumns);
    ELSE
        SET v_DB = DATABASE();
        SELECT GROUP_CONCAT(COLUMN_NAME)
        INTO v_DynamicColumns
        FROM information_schema.columns
        WHERE TABLE_NAME = 'tb_User'
            AND TABLE_SCHEMA = v_DB
            AND COLUMN_NAME NOT IN ('companyId', 'sipLoginId', 'domainId', 'roleid');
    END IF;

    SET @Query = CONCAT(
        'SELECT ', v_DynamicColumns, ' FROM tb_User WHERE domainId = ', p_domainId,
        ' AND roleid IN(', IFNULL(p_roleId, v_allRollId), ') ORDER BY roleid DESC'
    );

    PREPARE stmt FROM @Query;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
