CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_getWhatsappBot`(	
	p_yourNumber bigint,
 	p_domainId	 INT
 )
begin
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	select 	a.isBot
 		,	a.isBotPurchased
         ,	a.planId
         ,	a.purchasedat
         ,  a.whatsappFlowId
         ,  a.callBackToggle
 		
 		
         
