CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_addon_language_dtl`(
	p_domainId	int
)
begin

	DECLARE v_id INT;
   
   SELECT 1 INTO v_id
   FROM tb_company_purchased_addon_list
	WHERE domainId = p_domainId
    AND addonName LIKE '%Multilingual%' LIMIT 1;
   
	SELECT 1 AS addonId,'English' AS addonName
	WHERE v_id = 1
	UNION
	SELECT distinct addonId,
	  REPLACE(
		SUBSTRING_INDEX(SUBSTRING_INDEX(addonName, '(', -1), ')', 1),
		')',
		''
	  ) AS addonName
	FROM tb_company_purchased_addon_list
	WHERE domainId = p_domainId
	AND addonName LIKE '%Multilingual%';

end ;;
