CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_AgentAssist_analytics_trend_chart_info`(
      p_startTmpstmp  BIGINT,
      p_endTmpstmp 	BIGINT,
      p_domainId 		INT
  )
BEGIN
  	DECLARE v_StartTmpstmp 		BIGINT;
  	DECLARE v_EndTmpstmp		BIGINT;
	DECLARE v_Resolved 			INT;
  
     IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
    	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_EndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_EndTmpstmp = p_endTmpstmp; END IF; 
       
  			DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
       		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                   	
  								SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
                           		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                       		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                       		(    DispositionId 			INT
                       			,DispositionStatus 		VARCHAR(100)
                       			,DispositionCategory	TINYINT
                       		); 
                               
                       		INSERT INTO temp_AvailableDisposition 
                       		SELECT 	did 			DispositionId
                       			,	dispositionName	DispositionStatus
                       			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                       				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                       				WHEN dispositionName = 'Discarded'     THEN 4
                					    WHEN dispositionName = 'Resolved'      THEN 5
                       				END 			DispositionCategory
                       		FROM 	disposition_status
                       		WHERE 	domainId	= p_domainId;  
       

       
      DROP TEMPORARY TABLE IF EXISTS tmp_AgentAssisttrend;
      CREATE TEMPORARY TABLE tmp_AgentAssisttrend 
  SELECT 
     H.ChatHistoryId																	AS HistoryId,
     FROM_UNIXTIME(H.sessionStartTime/1000) 											AS time_range,
     TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn) 	AS waitDuration,
     SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 				AS queriesAnswered,
 	2003002																			AS channelType		
 FROM tb_ChatHistory H
 JOIN tb_ChatDurationHistory DH  ON DH.ChatHistoryId = H.ChatHistoryId
 LEFT JOIN disposition_status DS ON DS.did = DH.dispositionId AND H.domainId = DS.domainId
 WHERE 
     H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
     AND H.domainId = p_domainId
     AND DH.IsBot = 1
 GROUP BY FROM_UNIXTIME(H.sessionStartTime/1000), TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn), H.ChatHistoryId;
 
 
 
      INSERT INTO tmp_AgentAssisttrend ( HistoryId,
                                         time_range,
 										waitDuration,
 										queriesAnswered,
 										channelType)
                                         
      SELECT     H.CallHistoryId   																AS HistoryId,
      FROM_UNIXTIME(H.sessionStartTime/1000) 											        AS time_range,
     TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn) 				AS waitDuration,
     SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 							AS queriesAnswered,
 	2003001																						AS channelType		
      FROM tb_CallHistory H
      JOIN tb_CallDurationHistory DH ON DH.CallHistoryId = H.CallHistoryId
      LEFT JOIN disposition_status DS ON DS.did = DH.dispositionId AND H.domainId = DS.domainId
      WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
        AND H.domainId = p_domainId
        AND DH.IsBot = 1
      GROUP BY FROM_UNIXTIME(H.sessionStartTime/1000), TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn),H.CallHistoryId;
  
      INSERT INTO tmp_AgentAssisttrend (HistoryId,
 										time_range, 
 									    waitDuration, 
 									    queriesAnswered
                                         ,channelType)
      SELECT     H.EmailHistoryId     															AS HistoryId,
      FROM_UNIXTIME(H.sessionStartTime/1000) 													AS time_range,
     TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn) 				AS waitDuration,
     SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 							AS queriesAnswered,
 	  2003007																						AS channelType		
      FROM tb_EmailHistory H
      JOIN tb_EmailDurationHistory DH ON DH.EmailHistoryId = H.EmailHistoryId
      LEFT JOIN disposition_status DS ON DS.did = H.dispositionId AND H.domainId = DS.domainId
      WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
        AND H.domainId = p_domainId
        AND DH.IsBot = 1
      GROUP BY FROM_UNIXTIME(H.sessionStartTime/1000), TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn),H.EmailHistoryId;
  
      INSERT INTO tmp_AgentAssisttrend (HistoryId,
                                        time_range, 
 									    waitDuration,
 									    queriesAnswered
                                         ,channelType)
      SELECT     H.SMSHistoryId    AS HistoryId,
      FROM_UNIXTIME(H.sessionStartTime/1000) 													AS time_range,
     TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn) 				AS waitDuration,
     SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 							AS queriesAnswered,
 	2003008																						AS channelType		
      FROM tb_SMSHistory H
      JOIN tb_SMSDurationHistory DH ON DH.SMSHistoryId = H.SMSHistoryId
      LEFT JOIN disposition_status DS ON DS.did = H.dispositionId AND H.domainId = DS.domainId
      WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
        AND H.domainId = p_domainId
        AND DH.IsBot = 1
     GROUP BY FROM_UNIXTIME(H.sessionStartTime/1000), TIMESTAMPDIFF(SECOND, FROM_UNIXTIME(H.sessionStartTime/1000), H.assignedOn),H.SMSHistoryId;
  
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 

       DROP TEMPORARY TABLE IF EXISTS tmp_botHistory;
       CREATE TEMPORARY TABLE tmp_botHistory
 SELECT    HistoryId,
           MAX(time_range)                         AS time_range,
           MAX(waitDuration)                       AS waitDuration,
           MAX(queriesAnswered)                    AS queriesAnswered,
           MIN(channelType)						  AS channelType
 	  FROM 	tmp_AgentAssisttrend
       GROUP BY HistoryId;
 
 WITH CTE_BotAgentAssistChannel AS ( 
   	SELECT 	MAX(time_range)                                 AS time_range,
            COUNT(HistoryId)								AS totalSession
   		,	SUM(waitDuration/queriesAnswered)/1000       	AS totalAverageSpeedOfResponse
   		,	null							                AS responseRate	
 		,	channelType        
       FROM 	tmp_botHistory	H  
       GROUP BY channelType
       )
 
 select time_range,totalSession,totalAverageSpeedOfResponse,responseRate 
 FROM CTE_BotAgentAssistChannel H
 JOIN 	TypeCode			C	ON H.channelType	= C.TypeCodeID;     
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_AgentAssist_analytics_trend_chart_info1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_AgentAssist_analytics_trend_chart_info1`(
     p_startTmpstmp  BIGINT,
     p_endTmpstmp 	BIGINT,
     p_domainId 		INT
 )
BEGIN
 	DECLARE v_StartTmpstmp 		BIGINT;
 	DECLARE v_EndTmpstmp		BIGINT;
     DECLARE v_Resolved 			INT;
 
    IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
   	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_EndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_EndTmpstmp = p_endTmpstmp; END IF; 
      
 			DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
      		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                  	
 								SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
                          		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                      		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                      		(    DispositionId 			INT
                      			,DispositionStatus 		VARCHAR(100)
                      			,DispositionCategory	TINYINT
                      		); 
                              
                      		INSERT INTO temp_AvailableDisposition 
                      		SELECT 	did 			DispositionId
                      			,	dispositionName	DispositionStatus
                      			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                      				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                      				WHEN dispositionName = 'Discarded'     THEN 4
               					    WHEN dispositionName = 'Resolved'      THEN 5
                      				END 			DispositionCategory
                      		FROM 	disposition_status
                      		WHERE 	domainId	= p_domainId;  
      
     DROP TEMPORARY TABLE IF EXISTS tmp_AgentAssisttrend;
     CREATE TEMPORARY TABLE tmp_AgentAssisttrend (
         time_range 				DATETIME,
         Sessions 				INT,
         duration 				BIGINT,
         waitDuration 			BIGINT,
         queriesAnswered 		INT
     );
 
     INSERT INTO tmp_AgentAssisttrend (time_range, Sessions, duration, waitDuration, queriesAnswered)
     SELECT FROM_UNIXTIME(H.sessionStartTime/1000)                                                							AS time_range,
            CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END 														AS Sessions,
            CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 					AS duration,
            TIMESTAMPDIFF(SECOND, sessionStartTime, H.assignedOn) 															AS waitDuration,
            SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 													AS queriesAnswered
     FROM tb_ChatHistory H
     JOIN tb_ChatDurationHistory DH ON DH.ChatHistoryId = H.ChatHistoryId
     LEFT JOIN disposition_status DS ON DS.did = DH.dispositionId AND H.domainId = DS.domainId
     WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
       AND H.domainId = p_domainId
       AND DH.IsBot = 1
     GROUP BY H.sessionStartTime, H.sessionEndTime,H.assignedOn;
 
     INSERT INTO tmp_AgentAssisttrend (time_range, Sessions, duration, waitDuration, queriesAnswered)
     SELECT FROM_UNIXTIME(H.sessionStartTime/1000) 												 				AS time_range,
            CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END							 				AS Sessions,
            CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END   	AS duration,
            TIMESTAMPDIFF(SECOND, sessionStartTime, H.assignedOn) 												AS waitDuration,
            SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 										AS queriesAnswered
     FROM tb_CallHistory H
     JOIN tb_CallDurationHistory DH ON DH.CallHistoryId = H.CallHistoryId
     LEFT JOIN disposition_status DS ON DS.did = DH.dispositionId AND H.domainId = DS.domainId
     WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
       AND H.domainId = p_domainId
       AND DH.IsBot = 1
     GROUP BY H.sessionStartTime, H.sessionEndTime,H.assignedOn;
 
     INSERT INTO tmp_AgentAssisttrend (time_range, Sessions, duration, waitDuration, queriesAnswered)
     SELECT FROM_UNIXTIME(H.sessionStartTime/1000) 																AS time_range,
            CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END 											AS Sessions,
            CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 		AS duration,
            H.waitDuration 																						AS waitDuration,
            SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 										AS queriesAnswered
     FROM tb_EmailHistory H
     JOIN tb_EmailDurationHistory DH ON DH.EmailHistoryId = H.EmailHistoryId
     LEFT JOIN disposition_status DS ON DS.did = H.dispositionId AND H.domainId = DS.domainId
     WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
       AND H.domainId = p_domainId
       AND DH.IsBot = 1
     GROUP BY H.sessionStartTime, H.sessionEndTime,H.waitDuration;
 
     INSERT INTO tmp_AgentAssisttrend (time_range, Sessions, duration, waitDuration, queriesAnswered)
     SELECT FROM_UNIXTIME(H.sessionStartTime/1000) 																AS time_range,
            CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END 											AS Sessions,
            CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 		AS duration,
            H.waitDuration 																						AS waitDuration,
            SUM(CASE WHEN DS.dispositionName IS NOT NULL THEN 1 ELSE 0 END) 										AS queriesAnswered
     FROM tb_SMSHistory H
     JOIN tb_SMSDurationHistory DH ON DH.SMSHistoryId = H.SMSHistoryId
     LEFT JOIN disposition_status DS ON DS.did = H.dispositionId AND H.domainId = DS.domainId
     WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmpstmp
       AND H.domainId = p_domainId
       AND DH.IsBot = 1
     GROUP BY H.sessionStartTime, H.sessionEndTime,H.waitDuration;
 
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
SELECT 
    IFNULL(DATE_FORMAT(time_range, '%y-%m-%d %H:%i:%s'), '0') AS time_range,
    IFNULL(SUM(waitDuration / queriesAnswered) / 1000, 0) AS averageSpeedOfResponse,
    NULL AS responseRate
FROM 
    tmp_AgentAssisttrend
GROUP BY 
    DATE_FORMAT(time_range, '%y-%m-%d %H:%i:%s');

     
       SELECT 	
          	SUM(waitDuration/queriesAnswered)/1000                           				AS totalAverageSpeedOfResponse
          ,  null                                                            				AS responseRate
      FROM 	tmp_AgentAssisttrend;   
 END ;;
DELIMITER ;
