CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_AgentAssist_EngagementRate_trend_chart_info_1`(
    p_startTmpstmp 	BIGINT,
    p_endTmpstmp 	BIGINT,
    p_domainId 		INT
  )
BEGIN

        DECLARE v_startTmpstmp 					BIGINT;
        DECLARE v_endTmpstmp 					BIGINT;
        DECLARE v_startTime	 				    DATETIME;
        DECLARE v_endTime	 					DATETIME;
		DECLARE v_interval						INT;
		DECLARE v_TmpstmpInterval			    BIGINT;	
		DECLARE v_startDateTime 				DATETIME;
		DECLARE v_endDateTime 					DATETIME;
        DECLARE v_Time                          DATETIME;
            
 	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY)) * 1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
   	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_endTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  
      
  	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                    	
   								SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
                            		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                        		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
 
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                        				WHEN dispositionName = 'Discarded'     THEN 4
 									WHEN dispositionName = 'Resolved'      THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;  

    			    DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
          			CREATE TEMPORARY TABLE temp_Intervals (
          			starttime DATETIME,
          			endtime   DATETIME
          			);
                         
          			SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day),from_unixtime(p_startTmpstmp/1000));
					SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
                      
                      IF DATEDIFF(v_endDateTime,v_startDateTime) > 29
                      THEN
          				SET v_interval = 86400; 
          			ELSEIF DATEDIFF(v_endDateTime,v_startDateTime) > 1
                      THEN
          				SET v_interval = 3600; 
                      ELSE
                     
                        SET v_interval = 900; 
                      END IF;
                           
						SET v_startTime = v_startDateTime;
          			    SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
                           
            			 WHILE v_startTime < v_endDateTime 
            			 DO      
          				 INSERT INTO temp_Intervals (starttime, endtime)
          				 VALUES (v_startTime, v_endTime);
                           
          				SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval second));
          				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval second));
          			END WHILE;

					DROP TEMPORARY TABLE IF EXISTS temp_voiceHistory;
          			CREATE TEMPORARY TABLE temp_voiceHistory
          			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
          			FROM 	tb_CallHistory H 
          			WHERE 	H.domainId = p_domainId
          			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
          			GROUP BY H.sessionStartTime;   
                    
          			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
          			CREATE TEMPORARY TABLE temp_Intervals_1
          			SELECT t_I.endtime 	AS `Time`     
						,	count(1)	AS `NoofreceivedSMSCount`
          			FROM temp_Intervals t_I
          			JOIN temp_voiceHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
          			GROUP BY t_I.endtime;
              
      			SELECT  (t_I.endtime) 						AS `Articles`
       				    FROM 		temp_Intervals t_I 
            			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;   
                                
	  DROP TEMPORARY TABLE IF EXISTS tmp_botAgentKnowledgeBase;
      CREATE TEMPORARY TABLE tmp_botAgentKnowledgeBase
     SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 																										AS time_range
 		 ,CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END																						AS Sessions
  		 , 	CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END  												AS duration 
 		 ,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId  is not null AND 
         sts.timerStatus	not in ('connected','Agent on Hold','hold') and sts.timerStatus	 is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)    AS Percentage
         ,H.sessionEndTime
      FROM 	tb_ChatHistory			H
      JOIN 	tb_ChatDurationHistory	DH		ON DH.ChatHistoryId = H.ChatHistoryId
 LEFT JOIN state_timer               st  	ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts		ON 	sts.timerStatusId = st.timerStatusId
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId 
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmpstmp
 		AND    	H.domainId			= p_domainId
         AND 	DH.IsBot			= 1
      GROUP BY H.sessionStartTime,H.sessionEndTime;  
      
 INSERT INTO tmp_botAgentKnowledgeBase
       SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 																						AS time_range
  		,	CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END																		AS Sessions
  		, 	CASE WHEN H.sessionEndTime IS NOT NULL THEN H.callDuration ELSE 0 END 															AS duration 
 		,   COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId is not null  AND 
           sts.timerStatus not in ('connected','Agent on Hold','hold') and sts.timerStatus is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)   AS Percentage
        ,H.sessionEndTime   
      FROM 	tb_CallHistory			H
      JOIN 	tb_CallDurationHistory	DH	ON DH.CallHistoryId = H.CallHistoryId
 LEFT JOIN state_timer               st  ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts	ON 	sts.timerStatusId = st.timerStatusId     
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId 
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmpstmp
 		AND    	H.domainId			= p_domainId
        AND 	DH.IsBot			= 1 
 	GROUP BY H.sessionStartTime,H.sessionEndTime,H.callDuration; 
      
      INSERT INTO tmp_botAgentKnowledgeBase
  SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 															    AS time_range	
  		,	CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END											AS Sessions
  		, 	CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 		AS duration 
 		,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId is not null  AND 
           sts.timerStatus not in ('connected','Agent on Hold','hold') and sts.timerStatus is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)   AS Percentage
           ,H.sessionEndTime
      FROM 	tb_SMSHistory			H
      JOIN 	tb_SMSDurationHistory	DH	ON DH.SMSHistoryId = H.SMSHistoryId 
 LEFT JOIN state_timer               st  ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts	ON 	sts.timerStatusId = st.timerStatusId     
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId      
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmpstmp
 	 AND    	H.domainId		= p_domainId
      AND 	   DH.IsBot			= 1 
      GROUP BY H.sessionStartTime,H.sessionEndTime;     
  
      INSERT INTO tmp_botAgentKnowledgeBase
  SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 															   											AS time_range
  		,	CASE WHEN H.SessionStartTime IS NOT NULL THEN 1 ELSE 0 END																					AS Sessions
  		, 	CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 												AS duration 
 		,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId is not null  AND 
           sts.timerStatus not in ('connected','Agent on Hold','hold') and sts.timerStatus is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)   AS Percentage
           ,H.sessionEndTime
      FROM 	tb_EmailHistory			H
      JOIN 	tb_EmailDurationHistory	DH	ON DH.EmailHistoryId = H.EmailHistoryId
 LEFT JOIN state_timer               st  ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts	ON 	sts.timerStatusId = st.timerStatusId     
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId     
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmpstmp
 	  AND    	H.domainId		= p_domainId
      AND 	DH.IsBot			= 1 
      GROUP BY H.sessionStartTime,H.sessionEndTime;  
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
      
        SELECT 	
           Time																           AS Articles
 		,  IFNULL(SUM(H.Percentage)/count(1) ,0)                                       AS Percentage
      FROM 	tmp_botAgentKnowledgeBase H
      join temp_Intervals ON H.sessionEndTime = t_I.Time; 
  END ;;
