CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_agent_id_sentimental_score`(
	p_domainId	INT
)
begin

	DROP TEMPORARY TABLE IF EXISTS tt_agent_sentiment;
    CREATE TEMPORARY TABLE tt_agent_sentiment(
    ChannelType		VARCHAR(100)
    ,Score			INT
    ,AgentId		INT
    ,createdAt		DATETIME
    );
    
    INSERT INTO tt_agent_sentiment
	SELECT 'Call' AS ChannelType,CDH.SentimentalScore,CDH.AgentId,CH.createdAt
	FROM tb_CallHistory CH
	JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
	WHERE CH.domainId = p_domainId
    AND CAST(CH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;

	INSERT INTO tt_agent_sentiment
	SELECT 'Chat' AS ChannelType,CDH.SentimentalScore,CDH.AgentId,CH.createdAt 
	FROM tb_ChatHistory CH
	JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
	WHERE CH.domainId = p_domainId
    AND CAST(CH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;

	INSERT INTO tt_agent_sentiment
	SELECT 'Email' AS ChannelType,EH.SentimentalScore,EDH.AgentId,EH.createdAt
	FROM tb_EmailHistory EH
	JOIN tb_EmailDurationHistory EDH ON EH.EmailHistoryId = EDH.EmailHistoryId
	WHERE EH.domainId = p_domainId
    AND CAST(EH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;
	
    INSERT INTO tt_agent_sentiment
	SELECT 'SMS' AS ChannelType,SH.SentimentalScore,SDH.AgentId,SH.createdAt 
	FROM tb_SMSHistory SH
	JOIN tb_SMSDurationHistory SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
	WHERE SH.domainId = p_domainId
    AND CAST(SH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;
	
    INSERT INTO tt_agent_sentiment
	SELECT 'Whatsapp' AS ChannelType,WH.SentimentalScore,WDH.AgentId,WH.createdAt 
	FROM tb_WhatsappHistory WH
	JOIN tb_WhatsappDurationHistory WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
	LEFT JOIN tb_WhatsappMessage WM ON WDH.WhatsappHistoryId = WM.WhatsappHistoryId
	WHERE WH.domainId = p_domainId
    AND CAST(WH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;
	
    INSERT INTO tt_agent_sentiment
	SELECT 'Facebook' AS ChannelType,FH.SentimentalScore,FH.AgentId,FH.createdAt  
	FROM tb_FacebookHistory FH
	WHERE FH.domainId = p_domainId
    AND CAST(FH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;

	INSERT INTO tt_agent_sentiment
	SELECT 'Instagram' AS ChannelType,IH.SentimentalScore,IH.AgentId,IH.createdAt 
	FROM tb_InstagramHistory IH
	WHERE IH.domainId = p_domainId
    AND CAST(IH.createdAt AS DATE) > (CURDATE() - INTERVAL 7 DAY)
    AND AgentId IS NOT NULL
    AND SentimentalScore IS NOT NULL;

	SELECT * FROM tt_agent_sentiment ORDER BY createdAt;

end ;;
DELIMITER ;
