CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_agent_list`(
	p_qid		INT
)
begin
	
    DECLARE v_domainId 	INT;
    DECLARE v_rqmid 	INT;
    
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		SELECT domainId INTO v_domainId
		FROM queue WHERE qid = p_qid;
		
		SELECT rqmid INTO v_rqmid 
		FROM routingqueueprofilemapping 
		WHERE qid = p_qid;

		SELECT UserID, myAccUserId, UserName, emailId, directNumber, address, routing_profile_id, report_to_UserID, sipLoginId, ext, isActive
		, callTypeId, inboundCall, outboundCampaignCall, roleid, localization, currentSession, isVoice, isVoiceCallTransfer, isAvailableForVoice
		, isChat, isChatTransfer, isEmail, isEmailTransfer, StatusID, isSms, isSocialMedia, companyName, addSkill, voice, chat, email, sms
		, socialMedia, chatLimit, createdAt, updatedAt, stateTimer, AssignedTime, chatFlag, ProfileImage, emp_id 
		FROM tb_User 
		WHERE routing_profile = v_rqmid
		AND state = 1 AND domainId = v_domainId
		ORDER BY stateTimer;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
end ;;
DELIMITER ;
