DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_agent_lists`(
 p_qid int,
 p_domainId int,
 p_calledNumber varchar(30)
 )
Begin
 
 		declare v_rqmid text;
 
 		SELECT group_concat(rqmid) into v_rqmid FROM routingqueueprofilemapping where domainId = p_domainId and qid = p_qid;
 
 		if p_calledNumber!='436889116888' then
 			SELECT UserID, myAccUserId, UserName, emailId, directNumber, address, routing_profile_id, report_to_UserID, sipLoginId, companyId, domainId, ext, isActive, callTypeId, inboundCall, outboundCampaignCall, roleid, localization, currentSession, isVoice, isVoiceCallTransfer, isAvailableForVoice, isChat, isChatTransfer, isEmail, isEmailTransfer, StatusID, isSms, isSocialMedia, companyName, addSkill, voice, chat, email, sms, socialMedia, chatLimit, createdAt, updatedAt, stateTimer, AssignedTime, chatFlag, ProfileImage, emp_id 
             FROM tb_User WHERE routing_profile_id IN (v_rqmid) AND isActive = 1 AND domainId = p_domainId AND ext <> 225 order by stateTimer limit 1;
 		else
 			if exists(SELECT 1 FROM tb_User WHERE routing_profile_id IN (v_rqmid) AND isActive = 1 AND domainId = p_domainId AND ext= 225 limit 1) then
 				SELECT UserID, myAccUserId, UserName, emailId, directNumber, address, routing_profile_id, report_to_UserID, sipLoginId, companyId, domainId, ext, isActive, callTypeId, inboundCall, outboundCampaignCall, roleid, localization, currentSession, isVoice, isVoiceCallTransfer, isAvailableForVoice, isChat, isChatTransfer, isEmail, isEmailTransfer, StatusID, isSms, isSocialMedia, companyName, addSkill, voice, chat, email, sms, socialMedia, chatLimit, createdAt, updatedAt, stateTimer, AssignedTime, chatFlag, ProfileImage, emp_id
                 FROM tb_User WHERE routing_profile_id IN (v_rqmid) AND isActive = 1 AND domainId = p_domainId AND ext= 225 order by stateTimer limit 1;
             End if;
 				SELECT UserID, myAccUserId, UserName, emailId, directNumber, address, routing_profile_id, report_to_UserID, sipLoginId, companyId, domainId, ext, isActive, callTypeId, inboundCall, outboundCampaignCall, roleid, localization, currentSession, isVoice, isVoiceCallTransfer, isAvailableForVoice, isChat, isChatTransfer, isEmail, isEmailTransfer, StatusID, isSms, isSocialMedia, companyName, addSkill, voice, chat, email, sms, socialMedia, chatLimit, createdAt, updatedAt, stateTimer, AssignedTime, chatFlag, ProfileImage, emp_id
                 FROM tb_User WHERE routing_profile_id IN (v_rqmid) AND isActive = 1 AND domainId = p_domainId order by stateTimer limit 1;
         End if;
 
 End ;;
DELIMITER ;
