CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_agent_list_chat`(
p_qid int,
p_domainId int,
p_Ext int
)
Begin

	declare v_rqmid varchar(100);
    declare v_tcnt int;
    declare v_cnt int;
    declare v_p_rqmid int;
    
    set v_cnt = 1;

	SELECT group_concat(rqmid) into v_rqmid
    FROM routingqueueprofilemapping WHERE qid = p_qid;
    
    call Split(v_rqmid,',');
    
    drop temporary table if exists tt_rqmid;
    create temporary table tt_rqmid (    id int auto_increment primary key,    rqmid int    );
    
    insert into tt_rqmid(rqmid)
    select items from tt_Split_temptable;
    
    select count(*) into v_tcnt from tt_rqmid;
    
    while v_cnt<=v_tcnt do		
		select rqmid into v_p_rqmid from tt_rqmid where id = v_cnt;
		
		call up_GetAgentListChat(p_domainId,v_p_rqmid,p_Ext);

		set v_cnt = v_cnt + 1;
    end while;
    
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
