/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_agent_report_nlp`(
 		p_startTmpstmp 	BIGINT,
 		p_endTmpstmp   	BIGINT,
 		p_domainId     	INT
 )
begin
			DECLARE v_startTmpstmp 				BIGINT;
			DECLARE v_endTmpstmp 				BIGINT;
			DECLARE v_Total_Count 				INT;

			IF IFNULL(p_startTmpstmp,0)=0 	THEN SET v_startTmpstmp  = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
			IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
		                    
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
			CREATE TEMPORARY TABLE temp_AllagentId 
			select UserID,UserName,ext,domainId from tb_User where domainId = p_domainId;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                               
  				  DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list;
  				  CREATE TEMPORARY TABLE temp_getcallback_list (
						SessionDate        	DATE,
						channelName			VARCHAR(50),
						agentId            	INT,
						AgentName          	VARCHAR(100),
						dispositionName    	VARCHAR(100),
						HistoryId        	BIGINT,
						isAnswered         	INT,
						isResolved         	INT,
                        satisfactionRate	INT
                );
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                 
                     INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
                     SELECT 
							DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
                            'Call',
							CDH.AgentId,
							AA.UserName 					AS AgentName,         
							DS.dispositionName,
							CH.CallHistoryId,
							CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
							CASE WHEN CDH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                            CF.satisfactionRate
					FROM tb_CallHistory CH
					JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
					JOIN temp_AllagentId AA ON AA.UserID = CDH.AgentId
					LEFT JOIN disposition_status DS ON DS.did = CDH.dispositionId AND CH.domainId = DS.domainId
                    LEFT JOIN tb_customerFeedback CF ON CF.AgentId = CDH.AgentId
                     WHERE CH.domainId = p_domainId
					 AND CDH.IsBot = 0
					 AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                     AND CDH.AgentId IS NOT NULL;
                                  
                     INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
                     SELECT DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
							'Chat',
							CDH.AgentId,
							AA.UserName 					AS AgentName,         
							DS.dispositionName,
							CH.ChatHistoryId,
							CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
							CASE WHEN CDH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                            CF.satisfactionRate
					FROM tb_ChatHistory CH
					JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
					JOIN temp_AllagentId AA ON AA.UserID = CDH.AgentId
					LEFT JOIN disposition_status DS ON DS.did = CDH.dispositionId AND CH.domainId = DS.domainId
                    LEFT JOIN tb_customerFeedback CF ON CF.AgentId = CDH.AgentId
					WHERE CH.domainId = p_domainId         
					AND CDH.IsBot=0
					AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                    AND CDH.AgentId IS NOT NULL;
                                 
                     INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
                     SELECT DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
							'SMS',
							CDH.AgentId,
							AA.UserName 					AS AgentName,         
							DS.dispositionName,
							CH.SMSHistoryId,
							CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
							CASE WHEN CDH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                            CF.satisfactionRate
					FROM tb_SMSHistory 						CH        
					JOIN tb_SMSDurationHistory				CDH	ON 	CH.SMSHistoryId = CDH.SMSHistoryId
					JOIN temp_AllagentId 					AA ON AA.UserID = CDH.AgentId
					LEFT JOIN disposition_status 			DS ON DS.did = CH.dispositionId AND CH.domainId = DS.domainId
                    LEFT JOIN tb_customerFeedback 			CF ON CF.AgentId = CDH.AgentId
					WHERE CH.domainId = p_domainId         
					AND CDH.IsBot=0
					AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                    AND CDH.AgentId IS NOT NULL;
                                              
					INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
					SELECT DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
						'Email',
						CDH.AgentId,
						AA.UserName 					AS AgentName,         
						DS.dispositionName,
						CH.EmailHistoryId,
						CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
						CASE WHEN CDH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                        CF.satisfactionRate
					FROM tb_EmailHistory 					CH        
					JOIN tb_EmailDurationHistory			CDH	ON 	CH.EmailHistoryId = CDH.EmailHistoryId        
					LEFT JOIN disposition_status			DS 	ON DS.did			= CH.DispositionId  and CH.domainId = DS.domainId        
                    LEFT JOIN tb_customerFeedback 			CF ON CF.AgentId 	= CDH.AgentId
					JOIN temp_AllagentId 					AA	ON AA.UserID 		= CDH.AgentId
					WHERE 	CH.domainId 			= p_domainId 
					AND 	CDH.IsBot=0
					AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
                    AND CDH.AgentId IS NOT NULL;
                                                      
				INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
				SELECT DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
						'Whatsapp',
						CDH.AgentId,
						AA.UserName 					AS AgentName,         
						DS.dispositionName,
						CH.WhatsappHistoryId,
						CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
						CASE WHEN CDH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                        CF.satisfactionRate
						FROM tb_WhatsappHistory 			CH        
						JOIN tb_WhatsappDurationHistory		CDH	ON 	CH.WhatsappHistoryId = CDH.WhatsappHistoryId        
						JOIN temp_AllagentId 				AA	ON AA.UserID 		= CDH.AgentId
						LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId and CH.domainId = DS.domainId
                        LEFT JOIN tb_customerFeedback 		CF 	ON CF.AgentId = CDH.AgentId
						WHERE 	CH.domainId		= p_domainId 	
						AND     CDH.IsBot		= 0
						AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp
                        AND CDH.AgentId IS NOT NULL;     
                        
				INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
				SELECT DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
						'Instagram',
						CH.AgentId,
						AA.UserName 					AS AgentName,         
						DS.dispositionName,
						CH.InstagramHistoryId,
						CASE WHEN CH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
						CASE WHEN CH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                        CF.satisfactionRate
						FROM tb_InstagramHistory 			CH        
						JOIN temp_AllagentId 				AA	ON AA.UserID 		= CH.AgentId
						LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId and CH.domainId = DS.domainId
                        LEFT JOIN tb_customerFeedback 		CF 	ON CF.AgentId = CH.AgentId
						WHERE 	CH.domainId		= p_domainId 	
						AND     CH.IsBot		= 0
						AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp
                        AND CH.AgentId IS NOT NULL;   
			
            INSERT INTO temp_getcallback_list(SessionDate,channelName,AgentId,AgentName,dispositionName,HistoryId,isAnswered,isResolved,satisfactionRate)
			SELECT DATE(FROM_UNIXTIME(CH.sessionStartTime / 1000)) AS SessionDate,
						'Facebook',
						CH.AgentId,
						AA.UserName 					AS AgentName,         
						DS.dispositionName,
						CH.FacebookHistoryId,
						CASE WHEN CH.Duration > 0 THEN 1 ELSE 0 END AS isAnswered,
						CASE WHEN CH.Duration > 0 AND DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END AS isResolved,
                        CF.satisfactionRate
						FROM tb_FacebookHistory 			CH        
						JOIN temp_AllagentId 				AA	ON AA.UserID 		= CH.AgentId
						LEFT JOIN disposition_status		DS 	ON DS.did			= CH.dispositionId and CH.domainId = DS.domainId
                        LEFT JOIN tb_customerFeedback 		CF 	ON CF.AgentId = CH.AgentId
						WHERE 	CH.domainId		= p_domainId 	
						AND     CH.IsBot		= 0
						AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp
                        AND CH.AgentId IS NOT NULL;   
                            
            SELECT SessionDate
				,channelName
				,agentId
				,AgentName
				,COUNT(HistoryId) AS totalReceived
				,SUM(isAnswered) AS totalAnswered
				,SUM(isResolved) AS totalResolved
                ,IFNULL(AVG(satisfactionRate),0) AS CSAT
            FROM temp_getcallback_list
            GROUP BY SessionDate,channelName,agentId,AgentName;                     
                        
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
