CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_agent_status_by_aid`(
	p_aid 			INT
	,p_domainId 	INT
    
)
begin

	SELECT aid, statusName, type, description, channels, createdAt, updatedAt, domainId, status, isDeleted, isVoice, isVoiceCallTransfer
	, isChat, isChatTransfer, isEmail, isEmailTransfer, colorCode
	FROM agent_status  
	WHERE aid = p_aid AND domainId = p_domainId;

end ;;
DELIMITER ;
