CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_agent_status_statusName_availability_check`(
	 p_statusName 	VARCHAR(100)
    ,p_domainId 	INT
)
begin

	DECLARE v_errcode 	INT;
    DECLARE v_errmsg 	VARCHAR(100);
    DECLARE v_aid 		INT;

	sp_return:BEGIN

	SELECT aid INTO v_aid
	FROM agent_status 
	WHERE statusName	= p_statusName
	AND domainId 		= p_domainId
	AND isDeleted 		= 0;
    
	IF v_aid IS NOT NULL
		THEN
			SET v_errcode = 0;
			SET v_errmsg = 'statusName already exists';
			LEAVE sp_return;
		ELSE 
			SET v_errcode = 1;
			SET v_errmsg = 'statusName available';
			LEAVE sp_return;
		END IF;
	END;
		SELECT v_errcode as flag,v_errmsg as errmsg;
end ;;
DELIMITER ;
