CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_ai_agent_status`(
	p_domainId		INT
    ,p_agentId		INT
)
BEGIN


	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;

	SELECT U.UserID,U.UserName,U.emailId,U.ext,U.StatusID,AG.statusName
	FROM tb_User U 
	JOIN agent_status AG ON U.StatusID = AG.aid
	WHERE U.domainId = p_domainId
    AND( IFNULL(p_agentId,'') = '' OR U.UserID = p_agentId)
    AND U.roleid IN (3,5,6);

	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	

END ;;
DELIMITER ;
