/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_Get_All_Channel_Message_NLP`( 
		 p_domainId 			INT
   )
BEGIN

		DECLARE v_startTime BIGINT;
        DECLARE v_endTime 	BIGINT;
        DECLARE v_curDate	DATETIME DEFAULT NOW();
 
        SET v_startTime 	= UNIX_TIMESTAMP(CAST(v_curDate AS DATE)) * 1000; 
        SET v_endTime 		= UNIX_TIMESTAMP(DATE_ADD(DATE_ADD(CAST(v_curDate AS DATE),INTERVAL 1 DAY),INTERVAL -1 MINUTE)) * 1000;
		
        DROP TEMPORARY TABLE IF EXISTS tt_message;
        CREATE TEMPORARY TABLE tt_message
        (
			 channelType VARCHAR(100)
             ,msg TEXT
        );
  
		INSERT INTO tt_message(channelType,msg)
 		SELECT 	'Chat',a.Message   
 		FROM 	tb_ChatMessage 			a
 		JOIN 	tb_ChatDurationHistory 	b 	ON 	a.ChatDurationHistoryId = b.ChatDurationHistoryId 
		JOIN 	tb_ChatHistory 			c 	ON 	c.ChatHistoryId			= b.ChatHistoryId 
 											AND c.domainId				= p_domainId
		AND c.sessionStartTime BETWEEN v_startTime AND v_endTime;
                     
		INSERT INTO tt_message(channelType,msg)
   		SELECT 	'Call',a.Message
   		FROM 	tb_CallMessage 			a
   		JOIN 	tb_CallDurationHistory 	b ON a.CallHistoryId = b.CallHistoryId 
   		JOIN 	tb_CallHistory 			c ON b.CallHistoryId = c.CallHistoryId 
   		WHERE 	c.domainId = p_domainId
        AND c.sessionStartTime BETWEEN v_startTime AND v_endTime;                                                     

		INSERT INTO tt_message(channelType,msg)
		SELECT 'Email',Message
        FROM tb_EmailMessage em 
		JOIN tb_EmailHistory eh ON em.EmailHistoryId = eh.EmailHistoryId
		WHERE eh.DomainId = p_domainId
        AND eh.SessionStartTime BETWEEN v_startTime AND v_endTime; 

		INSERT INTO tt_message(channelType,msg)
		SELECT 'SMS',Message
        FROM tb_SMSMessage sm
		JOIN tb_SMSHistory sh ON sm.SMSHistoryId = sh.SMSHistoryId
		WHERE  sh.domainId 	= p_domainId
        AND sh.sessionStartTime BETWEEN v_startTime AND v_endTime; 

		INSERT INTO tt_message(channelType,msg)
		SELECT 'Whatsapp',Message
        FROM tb_WhatsappMessage wm
		JOIN tb_WhatsappHistory wh ON wm.WhatsappHistoryId = wh.WhatsappHistoryId
		WHERE wh.domainId = p_domainId
        AND wh.sessionStartTime BETWEEN v_startTime AND v_endTime; 

		INSERT INTO tt_message(channelType,msg)
		SELECT 'Facebook',Message
        FROM tb_FacebookMessage fm
		JOIN tb_FacebookHistory fh ON fm.FacebookHistoryId = fh.FacebookHistoryId
		WHERE  fh.domainId = p_domainId
        AND fh.sessionStartTime BETWEEN v_startTime AND v_endTime; 
		
        INSERT INTO tt_message(channelType,msg)
		SELECT 'Instagram',Message
        FROM tb_InstagramMessage fm
		JOIN tb_InstagramHistory fh ON fm.InstagramHistoryId = fh.InstagramHistoryId
		WHERE fh.domainId = p_domainId
        AND fh.sessionStartTime BETWEEN v_startTime AND v_endTime; 

		SELECT channelType,msg as Message FROM tt_message;
        
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
