CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_all_question_answer`(
	p_domainId 	int
    ,p_limit 	int
    ,p_offset	int
)
begin

	declare v_offset int;
    
    set v_offset = p_limit * p_offset;
		
	SELECT questionId, domainId, uuid, question, answer, mapFlow, language, intent, keywords, status, version, createdAt, updatedAt
    , sent, helpfull, notHelpfull, chatFlowId, embedding, websiteId, discription, websiteUrl, baseName 
    FROM question_answer 
    WHERE domainId = p_domainId 
    ORDER BY questionId DESC LIMIT v_offset,p_limit;
    
    SELECT COUNT(*) as count 
    FROM question_answer 
    WHERE domainId = p_domainId;
     
end ;;
