CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_all_user_details_by_domain`(
	p_domainId INT
 )
Begin
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		select a.UserID,UserName,a.emailId,directNumber,address,routing_profile_id,report_to_UserID,sipLoginId,companyId
		,a.domainId,a.ext,isActive,callTypeId,inboundCall,outboundCampaignCall,roleid,localization,currentSession,isVoice
		,isVoiceCallTransfer,isAvailableForVoice,isChat,isChatTransfer,isEmail,isEmailTransfer,StatusID,isSms,isSocialMedia
		,companyName
        ,(SELECT JSON_ARRAYAGG(
        JSON_OBJECT(
            'skid', sk.sid,
            'value', sk.skill_name,
            'type', sk.type
				)
			)
		FROM skills sk
		JOIN skillMapping sm ON sk.sid = sm.skid
		WHERE sk.domainId = a.domainId
		AND sm.usid = a.UserID) AS addSkill
        ,voice,chat,email,sms,socialMedia,chatLimit,a.createdAt,a.updatedAt,stateTimer,AssignedTime,chatFlag
		,ProfileImage,emp_id,queueId,ual.pri_language,ual.sec_language 
        FROM tb_User a 
        LEFT JOIN tb_userAddonLanguageInfo ual on a.UserID = ual.userId and ual.domainId = a.domainId
        WHERE a.domainId = p_domainId
        AND roleid IN (3,5,6);
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
