CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_analytics_AgentAssist_trend_chart_info`(
    p_startTmpstmp BIGINT,
    p_endTmpstmp   BIGINT,
    p_domainId     INT
)
BEGIN
    DECLARE v_StartTmpstmp BIGINT;
    DECLARE v_EndTmpstmp BIGINT;
    DECLARE v_Resolved INT;

    IF IFNULL(p_startTmpstmp, 0) = 0 THEN 
        SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; 
    ELSE 
        SET v_StartTmpstmp = p_startTmpstmp; 
    END IF;

    IF IFNULL(p_endTmpstmp, 0) = 0 THEN 
        SET v_EndTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; 
    ELSE 
        SET v_EndTmpstmp = p_endTmpstmp; 
    END IF;

    DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;
    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);

    DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;
    CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);

    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
    CREATE TEMPORARY TABLE temp_AvailableDisposition (
        DispositionId INT,
        DispositionStatus VARCHAR(100),
        DispositionCategory TINYINT
    );

    INSERT INTO temp_AvailableDisposition 
    SELECT
        did AS DispositionId,
        dispositionName AS DispositionStatus,
        CASE 
            WHEN dispositionName = 'Opened' THEN 2
            WHEN dispositionName IN ('Resolved', 'Unresolved', 'Closed', 'Follow-up', 'Disconnected', 'Transferred') THEN 3
            WHEN dispositionName = 'Discarded' THEN 4
            WHEN dispositionName = 'Resolved' THEN 5
        END AS DispositionCategory
    FROM disposition_status
    WHERE domainId = p_domainId;

    DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
    CREATE TEMPORARY TABLE temp_AllagentId
    SELECT UserID, UserName, ext FROM tb_User WHERE domainId = p_domainId;

    DROP TEMPORARY TABLE IF EXISTS tmp_botInteraction;
    CREATE TEMPORARY TABLE tmp_botInteraction AS
SELECT  
    (SUM(CASE WHEN H.assignedBy = 1 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN H.assignedOn = 1 THEN 1 ELSE 0 END), 0)) * 100        											AS usageRate,
    0																																										AS accuracyRate,
    (SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END) / NULLIF(sum(CASE WHEN DH.IsBot = 0 THEN 1 END), 0)) 															AS FirstCallResolution,
    ((SUM(CASE WHEN DH.IsBot = 1 THEN 1 ELSE 0 END) - SUM(CASE WHEN DH.IsAbandoned = 1 THEN 1 ELSE 0 END)) / NULLIF(SUM(CASE WHEN DH.BotId = 1 THEN 1 ELSE 0 END), 0)) * 100 	AS Churn_Prevention_Rate,
    FROM_UNIXTIME(H.sessionStartTime / 1000) 																																	AS time_range,
    CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 																				AS duration 
	FROM tb_ChatHistory H
	JOIN tb_ChatDurationHistory DH ON DH.ChatHistoryId = H.ChatHistoryId
	LEFT JOIN temp_AvailableDisposition t_D ON DH.dispositionId = t_D.DispositionId 
	WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_EndTmpstmp
	AND H.domainId = p_domainId
	AND DH.IsBot = 1
	GROUP BY 
		FROM_UNIXTIME(H.sessionStartTime / 1000),
		FROM_UNIXTIME(H.sessionEndTime / 1000), H.sessionEndTime, H.sessionStartTime,
		t_D.DispositionCategory
	LIMIT 1;
    INSERT INTO tmp_botInteraction 
    SELECT
	(SUM(CASE WHEN H.assignedBy = 1 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN H.assignedOn = 1 THEN 1 ELSE 0 END), 0)) * 100        									                	AS usageRate,
    0 																																										        	AS accuracyRate,
    (SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END) / NULLIF(sum(CASE WHEN DH.IsBot = 0 THEN 1 END), 0)) 															        	AS FirstCallResolution,
    ((SUM(CASE WHEN DH.IsBot = 1 THEN 1 ELSE 0 END) - SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END)) / NULLIF(SUM(CASE WHEN DH.BotId = 1 THEN 1 ELSE 0 END), 0)) * 100 		AS Churn_Prevention_Rate,
    FROM_UNIXTIME(H.sessionStartTime / 1000) 																																	        	AS time_range,
    CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 																				        	AS duration 
    FROM tb_CallHistory H
    JOIN tb_CallDurationHistory DH ON DH.CallHistoryId = H.CallHistoryId
    LEFT JOIN temp_AvailableDisposition t_D ON DH.dispositionId = t_D.DispositionId
    WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND H.domainId = p_domainId
    AND DH.IsBot = 1
    GROUP BY H.sessionStartTime, H.sessionEndTime, t_D.DispositionCategory, H.callDuration
    LIMIT 1;

    INSERT INTO tmp_botInteraction
    SELECT 
	(SUM(CASE WHEN H.assignedBy = 1 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN H.assignedOn = 1 THEN 1 ELSE 0 END), 0)) * 100        									                	AS usageRate,
    0 																																										        	AS accuracyRate,
    (SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END) / NULLIF(sum(CASE WHEN DH.IsBot = 0 THEN 1 END), 0)) 															        	AS FirstCallResolution,
    ((SUM(CASE WHEN DH.IsBot = 1 THEN 1 ELSE 0 END) - SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END)) / NULLIF(SUM(CASE WHEN DH.BotId = 1 THEN 1 ELSE 0 END), 0)) * 100 		AS Churn_Prevention_Rate,
    FROM_UNIXTIME(H.sessionStartTime / 1000) 																																	        	AS time_range,
    CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 																				        	AS duration 
    FROM tb_EmailHistory H
    JOIN tb_EmailDurationHistory DH ON DH.EmailHistoryId = H.EmailHistoryId
    LEFT JOIN temp_AvailableDisposition t_D ON H.dispositionId = t_D.DispositionId
    WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND H.domainId = p_domainId
    AND DH.IsBot = 1
    GROUP BY H.sessionStartTime, H.sessionEndTime, t_D.DispositionCategory
    LIMIT 1;

    INSERT INTO tmp_botInteraction 
    SELECT
(SUM(CASE WHEN H.assignedBy = 1 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN H.assignedOn = 1 THEN 1 ELSE 0 END), 0)) * 100        									                		AS usageRate,
    0																																									        	AS accuracyRate,
    (SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END) / NULLIF(sum(CASE WHEN DH.IsBot = 0 THEN 1 END), 0)) 															        	AS FirstCallResolution,
    ((SUM(CASE WHEN DH.IsBot = 1 THEN 1 ELSE 0 END) - SUM(CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END)) / NULLIF(SUM(CASE WHEN DH.BotId = 1 THEN 1 ELSE 0 END), 0)) * 100 		AS Churn_Prevention_Rate,
    FROM_UNIXTIME(H.sessionStartTime / 1000) 																																	        	AS time_range,
    CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END 																				        	AS duration 
    FROM tb_SMSHistory H
    JOIN tb_SMSDurationHistory DH ON DH.SMSHistoryId = H.SMSHistoryId
    LEFT JOIN temp_AvailableDisposition t_D ON H.dispositionId = t_D.DispositionId
    WHERE H.sessionStartTime BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND H.domainId = p_domainId
    AND DH.IsBot = 1
    GROUP BY H.sessionStartTime, H.sessionEndTime, t_D.DispositionCategory, DH.Duration
    LIMIT 1;

    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    SELECT 
        DATE_FORMAT(time_range, '%y-%m-%d %H:%i:%s') 	AS time_range,
        SUM(duration) 									AS duration,
        (SUM(FirstCallResolution) / COUNT(1)) * 100 	AS completionRate
    FROM tmp_botInteraction
    GROUP BY time_range;

SELECT 
    IFNULL(usageRate, 0) 												AS usageRate,
    IFNULL(accuracyRate, 0) 											AS accuracyRate,
    IFNULL(SUM(FirstCallResolution), 0)					 				AS FirstCallResolution,
    IFNULL(Churn_Prevention_Rate, 0) 									AS Churn_Prevention_Rate,
    IFNULL(SUM(duration), 0) 											AS totalDuration,
    IFNULL((SUM(FirstCallResolution) / NULLIF(COUNT(1), 0)) * 100, 0)   AS totalCompletionRate
FROM 
    tmp_botInteraction
GROUP BY 
usageRate,accuracyRate,Churn_Prevention_Rate;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_analytics_NLUPerformences_Top_Intent_Distribution` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
