CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_analytics_NLUPerformences_Top_Intent_Distribution`(
     p_domainId 		INT
   )
BEGIN

		DECLARE v_count 		INT; 
			

					DROP TEMPORARY TABLE IF EXISTS tmp_botNLUPerformences;
					CREATE TEMPORARY TABLE tmp_botNLUPerformences                                                 
					SELECT MAX(IntentCount) AS IntentCount,IntentName,ChatFlowId,count(IntentName) as IntentNameCount  from tb_ChatIntent
                    WHERE domainId =p_domainId
					GROUP BY IntentName,ChatFlowId ORDER BY max(IntentCount) 
                    DESC LIMIT 10;      

  SELECT
  IntentName 																AS Intent, 
  IntentCount 																AS Count,
  ChatFlowId                                								AS ChatFlowId,
  (IntentCount/sum(IntentNameCount))*100 									AS  Percentage
  FROM tmp_botNLUPerformences
  group by IntentName,IntentCount,ChatFlowId;
  
  END ;;
DELIMITER ;
