CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_api_list`(
	p_fk_conid			INT,
	p_fk_modid			INT,
    p_fk_submodid		INT
)
BEGIN
		
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
        
        SELECT 
				id
				,fk_conid
				,fk_modid
				,fk_submodid
				,ApiName
				,descript
				,method
				,ApiURL
				,Payload
				,keyword
				,createAt
        FROM ccaas_connector_api_details_list 
        WHERE fk_conid= p_fk_conid AND fk_modid = p_fk_modid and fk_submodid = p_fk_submodid; 
		

		        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
						

END ;;
DELIMITER ;
