CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_appointment_flow_tracking_info`(
  p_channelType varchar(20),
  p_historyId bigint,
  p_domainId int
  )
Begin
    
	if p_channelType = 'Facebook' then
		select f.customerId,
				CASE WHEN a.phoneNumber IS NULL THEN c.primaryPhoneNumber ELSE a.phoneNumber END as phoneNumber,
				CASE WHEN a.emailId IS NULL THEN c.primaryEmail ELSE a.emailId END as emailId
                ,a.id,a.channelType,a.historyId,a.companyId,a.domainId,a.appId,a.userId,a.companyNumber,a.serviceId,a.processflow,a.processDate
				,a.processDuration,a.createDate,a.updateDate,a.processTime,a.consultant,a.categoryId,a.firstName,a.lastName
		FROM    ccaas_appointment_flow_tracking_dtl a 
        LEFT JOIN 	tb_FacebookHistory f ON a.historyId = f.FacebookHistoryId
		left JOIN    customer_contact c ON f.customerId = c.coid
		where a.channelType = 'Facebook' and a.domainId = p_domainId
        and a.historyId = p_historyId;
	End if; 

	if p_channelType = 'Instagram' then
		select f.customerId,
				c.primaryPhoneNumber as phoneNumber,
				c.primaryEmail as emailId ,a.*
		FROM    ccaas_appointment_flow_tracking_dtl a 
        LEFT JOIN 	tb_InstagramHistory f   ON a.historyId = f.InstagramHistoryId  
		LEFT JOIN     customer_contact c ON f.customerId = c.coid
		where a.channelType = 'Instagram' and a.domainId = p_domainId
        and a.historyId = p_historyId;
	End if;

	if p_channelType = 'Whatsapp' then
		select f.customerId,
			c.primaryPhoneNumber as phoneNumber,
			c.primaryEmail as emailId ,a.*
		FROM    ccaas_appointment_flow_tracking_dtl a
        LEFT JOIN tb_WhatsappHistory f     ON a.historyId = f.WhatsappHistoryId  
		JOIN     customer_contact c ON f.customerId = c.coid
		where a.channelType = 'Whatsapp' and a.domainId = p_domainId
        and a.historyId = p_historyId;
	End if;
    
  
   
  End ;;
DELIMITER ;
