CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_audio_prompt_library`(
		p_domainId			INT
)
BEGIN
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
            
            SELECT 
					uuid,
					fieldname,
					encoding,
					mimetype,
					filename,
					`path`,
					size,
					`type`,
					promptType,
					url,
					`name`,
					`description`,
					domainId,
					companyId,
					message,
					createdAt,
					updateddAt,
					promptStatus,
                    queueId
            FROM prompt_library 
            WHERE domainId = p_domainId ORDER BY uuid DESC;
            
            
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
            
            
END ;;
