CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_blockedCustomerContact`(
       IN p_domainId INT,
       IN p_email LONGTEXT
   )
BEGIN
 	DECLARE v_coid 	BIGINT;
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	 SELECT coid INTO v_coid
     FROM 	customer_contact
     WHERE 	primaryEmail	= p_email
     AND 	domainId		= p_domainId;    
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
     IF v_coid IS NULL
     THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 	coid INTO v_coid
 		FROM 	customer_contact
 		WHERE 	email 		LIKE CONCAT('%',p_email,'%')
 		AND 	domainId	= p_domainId
         ORDER BY coid LIMIT 1;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END IF;
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	blockCustomer, doNotDisturb
 	FROM 	customer_contact
 	WHERE 	coid = v_coid
    limit 1;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
