      IN p_domainId INT,
      IN p_phoneNumber LONGTEXT
  )
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      SELECT blockCustomer, doNotDisturb
  	FROM customer_contact
	WHERE 	domainId = p_domainId 
	AND 	(phoneNumber LIKE CONCAT('%', p_phoneNumber, '%')
			or primaryPhoneNumber LIKE p_phoneNumber);
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
