CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_businessHolidays`(
	 p_fkBusinessId			INT
     ,p_holidayId			INT
     ,p_domainId			INT 
)
begin

	SELECT hid,holidayName,startDate,endDate,isStatus,holidayDesc,holidayPrompt,holidayMessage
    FROM tb_Business_Holidays
    WHERE (IFNULL(p_fkBusinessId,0) = 0 OR fk_businessId = p_fkBusinessId) AND domainId = p_domainId AND (IFNULL(p_holidayId,0) = 0 OR hid = p_holidayId) 
    AND date(from_unixtime(startDate/1000)) >= curdate() ;

end ;;
