/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_businessHoursValidation`(
	p_businessHoursId	INT 
)
begin
		DECLARE v_curDate 						DATE;
        DECLARE v_holidayStartDate 				DATE;
        DECLARE v_holidayEndDate 				DATE;
        DECLARE v_holidayStatus 				TINYINT;
        DECLARE v_isHoliday						TINYINT DEFAULT 0;
        DECLARE v_timezoneTime					INT;
        DECLARE v_extractedSign					VARCHAR(5);
        DECLARE v_Business_Hours_Holiday_Flag 	VARCHAR(10);
        DECLARE v_Business_Hours_startTime 		TIME;
        DECLARE v_Business_Hours_endTime 		TIME;
        DECLARE v_currentDayObject				JSON;
        DECLARE v_timeZone						VARCHAR(150);
        DECLARE v_currentTime					TIME;
		DECLARE v_inx							INT;
		DECLARE v_idx							INT;
        DECLARE v_isBusinessHours				TINYINT DEFAULT 0;
       
       sp_return:begin
       
		SET v_curDate = CURDATE();
        
        SELECT JSON_EXTRACT(jt.json_obj, '$'),timeZone INTO v_currentDayObject,v_timeZone 
		FROM custom_hours,
			 JSON_TABLE(
				 custom_hours.hours,
				 '$[*]' COLUMNS (
					 json_obj JSON PATH '$',
					 day_name VARCHAR(10) PATH '$.day'
				 )
			 ) AS jt
		WHERE jt.day_name = DAYNAME(v_curDate)
        AND cid = p_businessHoursId;
                
        DROP TEMPORARY TABLE IF EXISTS tt_Business_Hours_Details;
		CREATE TEMPORARY TABLE tt_Business_Hours_Details 
		AS
        SELECT v_timeZone AS timeZone,
			JSON_UNQUOTE(JSON_EXTRACT(v_currentDayObject, '$.entry[0].startTime')) 	AS startTime,
			JSON_UNQUOTE(JSON_EXTRACT(v_currentDayObject, '$.entry[0].endTime')) 	AS endTime,
			JSON_UNQUOTE(JSON_EXTRACT(v_currentDayObject, '$.isHoliday')) 			AS isHoliday;
                        
        SELECT 	(REGEXP_REPLACE(SUBSTRING_INDEX(SUBSTRING_INDEX(timeZone, 'GMT ', -1), ':', 1), '^[+-]', '') * 60) + 
				(SUBSTRING_INDEX(SUBSTRING_INDEX(timeZone, ':', -1), ' ', 1)) 
		,SUBSTRING(SUBSTRING_INDEX(timeZone, 'GMT', -1), 2, 1) 
        INTO v_timezoneTime,v_extractedSign		
        FROM tt_Business_Hours_Details;

		DROP TEMPORARY TABLE IF EXISTS tt_Business_Holidays_Info; 
        CREATE TEMPORARY TABLE tt_Business_Holidays_Info
        (
			 idx 		INT AUTO_INCREMENT PRIMARY KEY
            ,startDate 	DATE
            ,endDate	DATE
            ,isStatus	TINYINT
        );
        
		INSERT INTO tt_Business_Holidays_Info(startDate,endDate,isStatus)
		SELECT 	DATE(FROM_UNIXTIME(startDate / 1000) + INTERVAL v_timezoneTime MINUTE) AS startDate,
				DATE(FROM_UNIXTIME(endDate / 1000) + INTERVAL v_timezoneTime MINUTE) AS endDate,
				isStatus 
		FROM tb_Business_Holidays 
		WHERE fk_businessId = p_businessHoursId;
		         		
        SELECT count(*) INTO v_idx FROM tt_Business_Holidays_Info; 
        
        SET v_inx = 1;
        
        WHILE (v_inx <= v_idx)
        DO                
				SELECT startDate,IFNULL(endDate,startDate),isStatus 
				INTO v_holidayStartDate,v_holidayEndDate,v_holidayStatus
				FROM tt_Business_Holidays_Info WHERE idx = v_inx;
						
				IF v_curDate BETWEEN v_holidayStartDate AND v_holidayEndDate 
				THEN
					SET v_isHoliday = 1;
				END IF;
				
				SET v_inx = v_inx + 1;
         
		END WHILE;	 
        
			SELECT isHoliday,startTime,endTime
			INTO v_Business_Hours_Holiday_Flag,v_Business_Hours_startTime,v_Business_Hours_endTime
			FROM tt_Business_Hours_Details;

        SELECT 	DATE_FORMAT((NOW() + INTERVAL v_timezoneTime MINUTE),'%H:%i') INTO v_currentTime; 
        
        IF v_currentTime BETWEEN v_Business_Hours_startTime AND v_Business_Hours_endTime 
        THEN
			SET v_isBusinessHours = 1;
		END IF;
       
	end;
    
		SELECT CASE WHEN (v_isHoliday = 1 OR v_Business_Hours_Holiday_Flag = 'true')
        THEN 0 ELSE v_isBusinessHours END AS isBusinessHours;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_businessHoursValidation_InnerSP` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
