		WHERE fk_businessId = p_businessHoursId;
		
        SELECT 'tt_Business_Holidays_Info',a.* FROM tt_Business_Holidays_Info a;
        
        SELECT count(*) INTO v_idx FROM tt_Business_Holidays_Info; 
        
        SET v_inx = 1;
        
        WHILE (v_inx <= v_idx)
        DO                
				SELECT startDate,IFNULL(endDate,startDate),isStatus,holidayPrompt
				INTO v_holidayStartDate,v_holidayEndDate,v_holidayStatus,v_holidayPrompt
				FROM tt_Business_Holidays_Info WHERE idx = v_inx;
						
				IF v_curDate BETWEEN v_holidayStartDate AND v_holidayEndDate 
				THEN
					SET v_isHoliday = 1;
