				SET v_inx = v_inx + 1;
         
		END WHILE;	 
        
        SELECT 'tt_Business_Hours_Details',a.* FROM tt_Business_Hours_Details a;
        
		SELECT isHoliday
		INTO v_Business_Hours_Holiday_Flag
		FROM tt_Business_Hours_Details;

		IF v_Business_Hours_Holiday_Flag <> 'true'
		THEN
        
			SELECT '21254567456454';
			SELECT startTime,endTime
