         SELECT 'v_Business_Hours_startTime AND v_Business_Hours_endTime ',v_currentTime, v_Business_Hours_startTime , v_Business_Hours_endTime ,v_Business_Hours_Holiday_Flag;  
           
        IF v_currentTime BETWEEN v_Business_Hours_startTime AND v_Business_Hours_endTime 
