CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_business_hours_list_by_name`(
	p_name		VARCHAR(250) 
    ,p_domainId	INT 
)
begin

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		
        IF IFNULL(p_name,'') <> ''
        THEN
			SELECT cid, name, description, hours, createdAt, updatedAt, domainId, timeZone, default_hours, timeZoneValue, type
			FROM custom_hours
			WHERE domainId = p_domainId and name like concat('%',p_name,'%');
		ELSE    
			SELECT cid, name, description, hours, createdAt, updatedAt, domainId, timeZone, default_hours, timeZoneValue, type
			FROM custom_hours
			WHERE domainId = p_domainId;
		END IF;

	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
end ;;
