CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_cutomerContact_dropDown_info`(
		p_domainId 	INT
)
begin

		SELECT DISTINCT customerType
		FROM customer_contact 
		WHERE domainId = p_domainId
        AND IFNULL(customerType,'')<>'';
        
        SELECT DISTINCT jt.tag_value AS tag
		FROM customer_contact
		JOIN JSON_TABLE(tags, '$[*]' COLUMNS (tag_value VARCHAR(255) PATH '$')) AS jt
		WHERE domainId = p_domainId
		AND tags IS NOT NULL 
		AND tags <> ''
		AND JSON_VALID(tags) = 1;
       
        SELECT DISTINCT `Source`
		FROM customer_contact 
		WHERE domainId = p_domainId
        AND IFNULL(`Source`,'')<>'';
        
        SELECT DISTINCT `country`
		FROM customer_contact 
		WHERE domainId = p_domainId
        AND IFNULL(`country`,'')<>'';
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
