/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_cutomerContact_dtl`(
	 p_domainId 	INT
    ,p_doNotDisturb TINYINT 
    ,p_customerType VARCHAR(100) 
    ,p_search		VARCHAR(500)
    ,p_customerTag	VARCHAR(100) 
    ,p_source		VARCHAR(150) 
    ,p_country		VARCHAR(500)
    ,p_offset		INT
    ,p_limit		INT
)
begin
		DECLARE v_offset INT;
        
        SET v_offset = p_limit * p_offset;
        
		SELECT coid
        ,IFNULL(firstName,'') AS FirstName
        ,IFNULL(lastName,'') AS LastName
        ,primaryPhoneNumber AS PhoneNumber
        ,doNotDisturb
        ,primaryEmail
        ,IFNULL(customerType,'') as customerType
        ,`Source` as contactSource
        ,country
        ,tags
        ,IFNULL(CustomerUniqueId,'') AS CustomerUniqueId
		FROM customer_contact 
		WHERE domainId = p_domainId 
		AND IFNULL(primaryPhoneNumber,0) > 0 
		AND primaryPhoneNumber REGEXP '^[0-9]+$'
        AND (IFNULL(p_doNotDisturb,'')='' OR doNotDisturb = p_doNotDisturb)
        AND	((customerType collate utf8mb4_0900_ai_ci = p_customerType) OR IFNULL(p_customerType,'')='')
        AND (IFNULL(p_search,'')='' OR (firstName collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_search,'%') OR lastName collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_search,'%')))
        AND (IFNULL(p_source,'')='' OR `Source` collate utf8mb4_0900_ai_ci = p_source)
        AND (IFNULL(p_country,'')='' OR `country` collate utf8mb4_0900_ai_ci = p_country)
        AND (IFNULL(p_customerTag,'')='' OR tags collate utf8mb4_0900_ai_ci like CONCAT('%',p_customerTag,'%'));
       
	end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
