CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_dashboard_barChat_test`(
     p_domainId        	INT,
     p_datetype        	INT,
     p_startDateTime   	DATETIME,
     p_endDateTime     	DATETIME,
     p_blastId			INT,
     p_campaignType		TINYINT, 
	 p_triggerType		TINYINT, 
	 p_createdBy		INT, 	 
     p_Status			TINYINT  
)
BEGIN
    DECLARE v_startDateTime   DATETIME;
    DECLARE v_endDateTime     DATETIME;
    DECLARE v_curDate         DATETIME DEFAULT NOW();
	
    IF p_datetype = 1 THEN
        SET v_startDateTime = DATE(v_curDate);
        SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime, INTERVAL 1 DAY), INTERVAL -1 MINUTE);
    ELSEIF p_datetype = 2 THEN
        SET v_startDateTime = DATE(DATE_ADD(v_curDate, INTERVAL -1 DAY));
        SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime, INTERVAL 1 DAY), INTERVAL -1 MINUTE);
    ELSEIF p_datetype = 3 OR p_datetype = 4 THEN
        SET v_startDateTime = p_startDateTime;
        SET v_endDateTime = DATE_ADD(DATE(p_endDateTime), INTERVAL '23:59:59' HOUR_SECOND);
    END IF;
    
    IF p_datetype IS NULL 
    THEN
		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
		CREATE TEMPORARY TABLE tmp_timings(startDateTime DATETIME,endDateTime DATETIME);
	END IF;
    
    IF p_datetype IN (1,2)
         THEN 
			DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
			CREATE TEMPORARY TABLE tmp_timings(startDateTime DATETIME,endDateTime DATETIME)
				WITH RECURSIVE CTE_TIMINGS AS (
				SELECT v_startDateTime AS startDateTime, DATE_ADD(v_startDateTime, INTERVAL 59 MINUTE) AS endDateTime
					UNION ALL
				SELECT DATE_ADD(startDateTime, INTERVAL 1 HOUR), DATE_ADD(endDateTime, INTERVAL 1 HOUR)
				FROM CTE_TIMINGS
				WHERE DATE_ADD(endDateTime, INTERVAL 1 HOUR) <= v_endDateTime
				)
				SELECT * FROM CTE_TIMINGS;
     	ELSEIF p_datetype IN (3,4)
         THEN 
			DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
			CREATE TEMPORARY TABLE tmp_timings(startDateTime DATETIME,endDateTime DATETIME)
				WITH recursive CTE_TIMINGS AS (
     			SELECT 	v_startDateTime AS startDateTime, DATE_ADD(v_startDateTime,INTERVAL 1439 MINUTE ) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	DATE(startDateTime) < DATE(v_endDateTime)
     		)
     		SELECT * FROM CTE_TIMINGS;	
         END IF;  

    DROP TEMPORARY TABLE IF EXISTS tt_timeInterval;
    CREATE TEMPORARY TABLE tt_timeInterval AS
    SELECT 
        DATE_FORMAT(startDateTime,'%Y-%m-%d %H:%i') AS startDateTime,
        DATE_FORMAT(endDateTime,'%Y-%m-%d %H:%i') AS endDateTime
    FROM tmp_timings;

    

    DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;
    CREATE TEMPORARY TABLE tmp_CallHistory AS
    SELECT 
        ctc.callStatus,
        DATE_FORMAT(DATE_ADD(ctc.createdAt,INTERVAL 330 MINUTE),'%Y-%m-%d %H:%i') AS createdAt
    FROM tb_callBlast_triggered_customer_call_json_dtl ctc
    JOIN tb_callBlast cb ON ctc.blastId = cb.cid AND ctc.domainId = cb.domainId
    WHERE ctc.domainId = p_domainId
	AND ctc.createdAt BETWEEN v_startDateTime AND v_endDateTime
    AND (ctc.blastId = p_blastId OR IFNULL(p_blastId,0)=0)
    AND	(cb.campaignType = p_campaignType OR IFNULL(p_campaignType,0)=0)
    AND	(cb.triggerType = p_triggerType OR IFNULL(p_triggerType,0)=0)
    AND	(cb.createdBy = p_createdBy OR IFNULL(p_createdBy,0)=0)
	AND (IFNULL(p_Status, 0) = 0
        OR (p_Status = 1 AND IFNULL(cb.completed, 0) = 1)
        OR (p_Status = 2 AND cb.blastStatus = 0)
        OR (p_Status = 3 AND cb.forceStop = 1));

    

    DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory_cal;
    CREATE TEMPORARY TABLE tmp_CallHistory_cal AS
    SELECT 
        CASE WHEN callStatus = 'answered' THEN 1 ELSE 0 END AS answeredCall,
        CASE WHEN callStatus = 'unanswered' THEN 1 ELSE 0 END AS unansweredCall,
        CASE WHEN callStatus = 'busy' THEN 1 ELSE 0 END AS busyCall,
        CASE WHEN callStatus = 'agent_unavailable' THEN 1 ELSE 0 END AS agentUnavailableCall,
        CASE WHEN callStatus = 'abandoned' THEN 1 ELSE 0 END AS abandonedCall,
        CASE WHEN callStatus = 'not_reachable' THEN 1 ELSE 0 END AS notReachableCall,
        CASE WHEN callStatus = 'agent_rejected' THEN 1 ELSE 0 END AS agentRejectedCall,
        CASE WHEN callStatus = 'Not Triggered' THEN 1 ELSE 0 END AS notTriggeredCall,
        createdAt
    FROM tmp_CallHistory;

    

    DROP TEMPORARY TABLE IF EXISTS tmp_result;
    CREATE TEMPORARY TABLE tmp_result (
        startDateTime 		DATETIME,
        endDateTime 		DATETIME,
        totalAttempted 		INT,
        totalConnected 		INT,
        totalFailed 		INT,
        notTriggeredCall 	INT
    );

    INSERT INTO tmp_result
    SELECT 
        t_T.startDateTime,
        t_T.endDateTime,
		IFNULL(SUM(answeredCall + unansweredCall + busyCall + agentUnavailableCall + abandonedCall + notReachableCall + agentRejectedCall + notTriggeredCall),0) AS 'totalAttempted',
		IFNULL(SUM(answeredCall),0) AS 'totalConnected',
		IFNULL(SUM(unansweredCall + busyCall + agentUnavailableCall + abandonedCall + notReachableCall + agentRejectedCall + notTriggeredCall),0) AS 'totalFailed',
        IFNULL(SUM(notTriggeredCall),0) AS 'notTriggeredCall'
    FROM tt_timeInterval t_T
    LEFT JOIN tmp_CallHistory_cal CH ON CH.createdAt BETWEEN t_T.startDateTime AND t_T.endDateTime
    GROUP BY t_T.startDateTime, t_T.endDateTime;

    SELECT startDateTime,endDateTime,totalAttempted,totalConnected,totalFailed,notTriggeredCall FROM tmp_result;
    
    DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
    DROP TEMPORARY TABLE IF EXISTS tt_timeInterval;
    DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;
    DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory_cal;
    DROP TEMPORARY TABLE IF EXISTS tmp_result;

END ;;
