/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_dashboard_info`(
 	p_domainId			INT 
     ,p_startDate		DATE 
     ,p_endDate			DATE
     ,p_blastId			INT
     ,p_campaignType	TINYINT 
     ,p_triggerType		TINYINT 
     ,p_createdBy		INT 	
     ,p_Status			TINYINT 
 )
begin 
 	DECLARE v_countOfCampaign 	INT;    
    DECLARE v_startDate			DATETIME;
    DECLARE v_endDate			DATETIME;
    DECLARE v_blastId			INT;
    DECLARE v_campaignType		TINYINT; 
    DECLARE v_triggerType		TINYINT; 
    DECLARE v_createdBy			INT;
    DECLARE v_Status			TINYINT;
    
    SET v_startDate		= p_startDate;
    SET v_endDate		= DATE_ADD(p_endDate, INTERVAL 1 DAY);
    SET v_blastId		= IFNULL(p_blastId,0);
    SET v_campaignType	= IFNULL(p_campaignType,0);
    SET v_triggerType	= IFNULL(p_triggerType,0);
    SET v_createdBy		= IFNULL(p_createdBy,0);
    SET v_Status 		= IFNULL(p_Status,0);
    

     
     IF p_blastId IS NOT NULL 
     THEN
			DROP TEMPORARY TABLE IF EXISTS tt_callBlast_triggered;
			CREATE TEMPORARY TABLE tt_callBlast_triggered
			SELECT 	ctc.tid, ctc.blastId,ctc.sessionId, ctc.callStatus
			from 	tb_callBlast_triggered_customer_call_json_dtl ctc
			WHERE 	ctc.domainId 	= 	p_domainId
			AND 	ctc.blastId = 	p_blastId;
        ELSE 
			DROP TEMPORARY TABLE IF EXISTS tt_callBlast_triggered;
		CREATE TEMPORARY TABLE tt_callBlast_triggered
		SELECT 	ctc.tid, ctc.blastId,ctc.sessionId, ctc.callStatus
		from 	tb_callBlast_triggered_customer_call_json_dtl ctc
		WHERE 	ctc.domainId 	= 	p_domainId
		AND 	ctc.createdAt 	>= 	v_startDate
		AND 	ctc.createdAt 	<	v_endDate;
	END IF;

		CREATE INDEX ix_tt_callBlast_triggered_blastId_sessionId on tt_callBlast_triggered (blastId,sessionId);

		DROP TEMPORARY TABLE IF EXISTS tt_callHistory;
		CREATE TEMPORARY TABLE tt_callHistory 
		SELECT 	ctc.tid,ctc.blastId,(IFNULL(cdh.Duration,0)/1000) AS duration,ctc.callStatus, cdh.dispositionId, cuc.totalUploadedContact
			,	cb.cid, cb.blastName
		FROM tt_callBlast_triggered 		ctc
		JOIN tb_callBlast 					cb 	ON 	ctc.blastId 	= cb.cid 
		JOIN tb_callBlast_uploadContact 	cuc ON 	cuc.fk_cid	 	= cb.cid
		LEFT JOIN tb_CallHistory 			ch 	ON 	ch.domainId		= p_domainId
												AND ch.sessionId 	= ctc.sessionId
		LEFT JOIN tb_CallDurationHistory 	cdh ON ch.CallHistoryId = cdh.CallHistoryId AND isListen = 0 AND isBarge = 0 AND isWhisper = 0
        WHERE 	(ctc.blastId = v_blastId 			OR v_blastId 		= 0)
		AND		(cb.campaignType = v_campaignType 	OR v_campaignType 	= 0)
		AND		(cb.triggerType = v_triggerType 	OR v_triggerType 	= 0)
		AND		(cb.createdBy = v_createdBy 		OR v_createdBy		= 0)
		AND 	(	v_Status = 0
				OR (v_Status = 1 AND cb.completed = 1)
				OR (v_Status = 2 AND cb.blastStatus = 0)
				OR (v_Status = 3 AND cb.forceStop = 1));  
    
 	 DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal;
     CREATE TEMPORARY TABLE tt_callHistory_cal 
     AS SELECT ch.tid,ch.blastId,FLOOR(ch.duration) AS duration,ch.callStatus
     ,ds.dispositionName
     ,ch.totalUploadedContact,ROW_NUMBER() OVER (PARTITION BY blastId ORDER BY tid DESC) AS row_num
 	FROM tt_callHistory ch 
     LEFT JOIN disposition_status ds ON ch.dispositionId = ds.did;

     SELECT count(distinct blastId) INTO v_countOfCampaign
     FROM tt_callHistory;
  
     DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_1;
     CREATE TEMPORARY TABLE tt_callHistory_cal_1 
     AS SELECT
         CASE WHEN callStatus = 'answered' THEN 1 ELSE 0 END 			AS answeredCall
         ,CASE WHEN callStatus = 'answered' THEN duration ELSE 0 END 	AS answeredCallDuration
         ,CASE WHEN callStatus = 'unanswered' THEN 1 ELSE 0 END 			AS unansweredCall
         ,CASE WHEN callStatus = 'busy' THEN 1 ELSE 0 END 				AS busyCall
         ,CASE WHEN callStatus = 'agent_unavailable' THEN 1 ELSE 0 END 	AS agentUnavailableCall
         ,CASE WHEN callStatus = 'abandoned' THEN 1 ELSE 0 END 			AS abandonedCall
         ,CASE WHEN callStatus = 'not_reachable' THEN 1 ELSE 0 END 		AS notReachableCall
         ,CASE WHEN callStatus = 'agent_rejected' THEN 1 ELSE 0 END 		AS agentRejectedCall
         ,CASE WHEN callStatus = 'Not Triggered' THEN 1 ELSE 0 END 		AS notTriggeredCall
         ,CASE WHEN dispositionName = 'Resolved' THEN 1 ELSE 0 END 		AS ResolvedCall
         ,CASE WHEN dispositionName in ('Closed','Unresolved','Follow-up','Do not contact','Auto Triggered'
         ,'Caller Disconnected','Transferred') THEN 1 ELSE 0 END 		AS connectedCall
         ,CASE WHEN blastId IS NOT NULL AND row_num = 1 THEN totalUploadedContact ELSE 0 END AS totalUploadedContact
 	FROM tt_callHistory_cal;
         
     DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final;
     CREATE TEMPORARY TABLE tt_callHistory_cal_final
     AS SELECT 
 		COUNT(answeredCall+unansweredCall+busyCall+agentUnavailableCall+abandonedCall+notReachableCall+agentRejectedCall+notTriggeredCall)				AS totalCalls
 		,SUM(answeredCall)			AS answeredCall
 		,SUM(unansweredCall)		AS unansweredCall
 		,SUM(busyCall)				AS busyCall
 		,SUM(agentUnavailableCall)	AS agentUnavailableCall
 		,SUM(abandonedCall)			AS abandonedCall
 		,SUM(notReachableCall)		AS notReachableCall
 		,SUM(agentRejectedCall)		AS agentRejectedCall
 		,SUM(notTriggeredCall)		AS notTriggeredCall
 		,SUM(answeredCallDuration)	AS answeredCallDuration
         ,SUM(ResolvedCall)			AS ResolvedCall
 		,SUM(connectedCall)			AS connectedCall
         ,SUM(totalUploadedContact)  AS totalUploadedContact
     FROM tt_callHistory_cal_1;
       
     DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final_result;
     CREATE TEMPORARY TABLE tt_callHistory_cal_final_result
     AS SELECT 
 		 totalUploadedContact as totalScheduledCalls
 		,totalCalls 
         ,answeredCall
         ,unansweredCall
 		,busyCall
         ,agentUnavailableCall
         ,abandonedCall
         ,notReachableCall
         ,agentRejectedCall
         ,notTriggeredCall
         ,(answeredCallDuration * 1000) AS answeredCallDuration
         ,(totalCalls - answeredCall) AS failedCalls
         ,CASE WHEN (totalCalls - notTriggeredCall) = 0 THEN 0 ELSE (answeredCall / (totalCalls - notTriggeredCall)) * 100 END AS successRate
 		,CASE WHEN answeredCall = 0 THEN 0 ELSE ((answeredCallDuration * 1000) / answeredCall) END AS averageCallDuration
 		,CASE WHEN (totalCalls - notTriggeredCall) = 0 THEN 0 ELSE ((unansweredCall + busyCall + agentUnavailableCall + abandonedCall + notReachableCall + agentRejectedCall) / (totalCalls - notTriggeredCall)) * 100 END AS droppedCalls
         
         ,(totalCalls - notTriggeredCall) AS noOfAttempt
         ,answeredCall AS noOfConnected
         
         ,(unansweredCall + busyCall + agentUnavailableCall + abandonedCall + notReachableCall + agentRejectedCall) AS noOfFailed
 	FROM tt_callHistory_cal_final;
     
 	SELECT v_countOfCampaign as totalCampaign,tt.* FROM tt_callHistory_cal_final_result tt;
     
     SELECT DISTINCT campaignType as CampaignId, CASE WHEN campaignType = 1 THEN 'Agentless Dialling' WHEN campaignType = 2 THEN 'Predictive Dialling' END as CampaignName
     FROM   	tb_callBlast
     WHERE 	domainId = p_domainId;
     
     SELECT DISTINCT u.UserName as creatorName,u.ext
     FROM   	tb_callBlast cb
     JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
     JOIN	tb_User u ON cb.createdBy = u.ext AND cb.domainId = u.domainId
     WHERE 	cb.domainId = p_domainId;
     
     SELECT null AS cid,'Overall Dashboard' AS blastName
     UNION ALL
     SELECT distinct cid,blastName
     FROM   	tt_callHistory;
     
	SELECT 	COUNT(1) AS count,dispositionName
	FROM 	tt_callHistory_cal
	WHERE 	dispositionName IS NOT NULL
	GROUP By dispositionName;
     
     SELECT distinct dispositionName
     FROM disposition_status
     WHERE domainId = p_domainId;
     
	DROP TEMPORARY TABLE IF EXISTS tt_callHistory;   
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal;
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_1;    
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final;    
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final_result; 
 
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_callBlast_dashboard_info_NLP` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_dashboard_info_NLP`(
 	p_domainId			INT 
     ,p_startDate		DATE 
     ,p_endDate			DATE
     ,p_blastId			INT
     ,p_campaignType	TINYINT 
     ,p_triggerType		TINYINT 
     ,p_createdBy		INT 	
     ,p_Status			TINYINT 
 )
begin 
 	DECLARE v_countOfCampaign 	INT;    
    DECLARE v_startDate			DATETIME;
    DECLARE v_endDate			DATETIME;
    DECLARE v_blastId			INT;
    DECLARE v_campaignType		TINYINT; 
    DECLARE v_triggerType		TINYINT; 
    DECLARE v_createdBy			INT;
    DECLARE v_Status			TINYINT;
    
    SET v_startDate		= p_startDate;
    SET v_endDate		= DATE_ADD(p_endDate, INTERVAL 1 DAY);
    SET v_blastId		= IFNULL(p_blastId,0);
    SET v_campaignType	= IFNULL(p_campaignType,0);
    SET v_triggerType	= IFNULL(p_triggerType,0);
    SET v_createdBy		= IFNULL(p_createdBy,0);
    SET v_Status 		= IFNULL(p_Status,0);
    

     
     IF p_blastId IS NOT NULL 
     THEN
			DROP TEMPORARY TABLE IF EXISTS tt_callBlast_triggered;
			CREATE TEMPORARY TABLE tt_callBlast_triggered
			SELECT 	ctc.tid, ctc.blastId,ctc.sessionId, ctc.callStatus
			from 	tb_callBlast_triggered_customer_call_json_dtl ctc
			WHERE 	ctc.domainId 	= 	p_domainId
			AND 	ctc.blastId = 	p_blastId;
        ELSE 
			DROP TEMPORARY TABLE IF EXISTS tt_callBlast_triggered;
		CREATE TEMPORARY TABLE tt_callBlast_triggered
		SELECT 	ctc.tid, ctc.blastId,ctc.sessionId, ctc.callStatus
		from 	tb_callBlast_triggered_customer_call_json_dtl ctc
		WHERE 	ctc.domainId 	= 	p_domainId
		AND 	ctc.createdAt 	>= 	v_startDate
		AND 	ctc.createdAt 	<	v_endDate;
	END IF;

		CREATE INDEX ix_tt_callBlast_triggered_blastId_sessionId on tt_callBlast_triggered (blastId,sessionId);

		DROP TEMPORARY TABLE IF EXISTS tt_callHistory;
		CREATE TEMPORARY TABLE tt_callHistory 
		SELECT 	ctc.tid,ctc.blastId,(IFNULL(cdh.Duration,0)/1000) AS duration,ctc.callStatus, cdh.dispositionId, cuc.totalUploadedContact
			,	cb.cid, cb.blastName
		FROM tt_callBlast_triggered 		ctc
		JOIN tb_callBlast 					cb 	ON 	ctc.blastId 	= cb.cid 
		JOIN tb_callBlast_uploadContact 	cuc ON 	cuc.fk_cid	 	= cb.cid
		LEFT JOIN tb_CallHistory 			ch 	ON 	ch.domainId		= p_domainId
												AND ch.sessionId 	= ctc.sessionId
		LEFT JOIN tb_CallDurationHistory 	cdh ON ch.CallHistoryId = cdh.CallHistoryId AND isListen = 0 AND isBarge = 0 AND isWhisper = 0
        WHERE 	(ctc.blastId = v_blastId 			OR v_blastId 		= 0)
		AND		(cb.campaignType = v_campaignType 	OR v_campaignType 	= 0)
		AND		(cb.triggerType = v_triggerType 	OR v_triggerType 	= 0)
		AND		(cb.createdBy = v_createdBy 		OR v_createdBy		= 0)
		AND 	(	v_Status = 0
				OR (v_Status = 1 AND cb.completed = 1)
				OR (v_Status = 2 AND cb.blastStatus = 0)
				OR (v_Status = 3 AND cb.forceStop = 1));  
        
 	 DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal;
     CREATE TEMPORARY TABLE tt_callHistory_cal 
     AS SELECT ch.tid,ch.blastId,ch.blastName,FLOOR(ch.duration) AS duration,ch.callStatus
     ,ds.dispositionName
     ,ch.totalUploadedContact,ROW_NUMBER() OVER (PARTITION BY blastId ORDER BY tid DESC) AS row_num
 	FROM tt_callHistory ch 
     LEFT JOIN disposition_status ds ON ch.dispositionId = ds.did;

     SELECT count(distinct blastId) INTO v_countOfCampaign
     FROM tt_callHistory;
  
     DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_1;
     CREATE TEMPORARY TABLE tt_callHistory_cal_1 
     AS SELECT
		 blastId
         ,blastName
         ,CASE WHEN callStatus = 'answered' THEN 1 ELSE 0 END 			AS answeredCall
         ,CASE WHEN callStatus = 'answered' THEN duration ELSE 0 END 	AS answeredCallDuration
         ,CASE WHEN callStatus = 'unanswered' THEN 1 ELSE 0 END 			AS unansweredCall
         ,CASE WHEN callStatus = 'busy' THEN 1 ELSE 0 END 				AS busyCall
         ,CASE WHEN callStatus = 'agent_unavailable' THEN 1 ELSE 0 END 	AS agentUnavailableCall
         ,CASE WHEN callStatus = 'abandoned' THEN 1 ELSE 0 END 			AS abandonedCall
         ,CASE WHEN callStatus = 'not_reachable' THEN 1 ELSE 0 END 		AS notReachableCall
         ,CASE WHEN callStatus = 'agent_rejected' THEN 1 ELSE 0 END 		AS agentRejectedCall
         ,CASE WHEN callStatus = 'Not Triggered' THEN 1 ELSE 0 END 		AS notTriggeredCall
         ,CASE WHEN dispositionName = 'Resolved' THEN 1 ELSE 0 END 		AS ResolvedCall
         ,CASE WHEN dispositionName in ('Closed','Unresolved','Follow-up','Do not contact','Auto Triggered'
         ,'Caller Disconnected','Transferred') THEN 1 ELSE 0 END 		AS connectedCall
         ,CASE WHEN blastId IS NOT NULL AND row_num = 1 THEN totalUploadedContact ELSE 0 END AS totalUploadedContact
 	FROM tt_callHistory_cal;
            
     DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final;
     CREATE TEMPORARY TABLE tt_callHistory_cal_final
     AS SELECT 
		 blastId
        ,blastName
 		,COUNT(answeredCall+unansweredCall+busyCall+agentUnavailableCall+abandonedCall+notReachableCall+agentRejectedCall+notTriggeredCall)				AS totalCalls
 		,SUM(answeredCall)			AS answeredCall
 		,SUM(unansweredCall)		AS unansweredCall
 		,SUM(busyCall)				AS busyCall
 		,SUM(agentUnavailableCall)	AS agentUnavailableCall
 		,SUM(abandonedCall)			AS abandonedCall
 		,SUM(notReachableCall)		AS notReachableCall
 		,SUM(agentRejectedCall)		AS agentRejectedCall
 		,SUM(notTriggeredCall)		AS notTriggeredCall
 		,SUM(answeredCallDuration)	AS answeredCallDuration
         ,SUM(ResolvedCall)			AS ResolvedCall
 		,SUM(connectedCall)			AS connectedCall
         ,SUM(totalUploadedContact)  AS totalUploadedContact
     FROM tt_callHistory_cal_1
     GROUP BY blastId,blastName;
           
     DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final_result;
     CREATE TEMPORARY TABLE tt_callHistory_cal_final_result
     AS SELECT 
		blastId
        ,blastName
		,totalUploadedContact as totalScheduledCalls
		,totalCalls 
		,answeredCall
		,unansweredCall
		,busyCall
		,agentUnavailableCall
		,abandonedCall
		,notReachableCall
		,agentRejectedCall
		,notTriggeredCall
		,(answeredCallDuration * 1000) AS answeredCallDuration
		,(totalCalls - answeredCall) AS failedCalls
		,CASE WHEN (totalCalls - notTriggeredCall) = 0 THEN 0 ELSE (answeredCall / (totalCalls - notTriggeredCall)) * 100 END AS successRate
		,CASE WHEN answeredCall = 0 THEN 0 ELSE ((answeredCallDuration * 1000) / answeredCall) END AS averageCallDuration
		,CASE WHEN (totalCalls - notTriggeredCall) = 0 THEN 0 ELSE ((unansweredCall + busyCall + agentUnavailableCall + abandonedCall + notReachableCall + agentRejectedCall) / (totalCalls - notTriggeredCall)) * 100 END AS droppedCalls
		,(totalCalls - notTriggeredCall) AS noOfAttempt
		,answeredCall AS noOfConnected
		,(unansweredCall + busyCall + agentUnavailableCall + abandonedCall + notReachableCall + agentRejectedCall) AS noOfFailed
 	FROM tt_callHistory_cal_final;
          
 	SELECT v_countOfCampaign as totalCampaign,tt.* FROM tt_callHistory_cal_final_result tt;
     
	DROP TEMPORARY TABLE IF EXISTS tt_callHistory;   
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal;
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_1;    
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final;    
 	DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final_result; 
 
 end ;;
DELIMITER ;
