CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_info`(
)
begin		
		
        DROP TEMPORARY TABLE IF EXISTS tt_timeConvert;
        CREATE TEMPORARY TABLE tt_timeConvert AS
		select ttt.ttid,ttt.fk_cid,ttt.startTime,ttt.endTime,ttt.working_day,cb.timeZone 
        ,REGEXP_REPLACE(SUBSTRING_INDEX(SUBSTRING_INDEX(timeZone, 'GMT ', -1), ':', 1), '^[+-]', '') * 60 as timezone_hour_extracted
        
        ,SUBSTRING_INDEX(SUBSTRING_INDEX(timeZone, ':', -1), ')', 1) AS timezone_minute_extracted
		,SUBSTRING(SUBSTRING_INDEX(timeZone, 'GMT', -1), 2, 1) as extracted_sign
        ,cb.outboundNumber,cb.campaignMessageType,cb.campaignMessage,cb.textSpeechFile,cuc.contact,cuc.importContact,cuc.importContactFile
        ,cb.domainId,cb.companyName,cb.triggerType,cb.campaignType,cuc.addContact,cb.promptMessage,dt.frequency
        ,cb.contactType,cb.connectingAudio,cb.agentUnavailable,cb.agentReject,cb.blastName,dt.endDate
        from tb_callBlast_timeToTrigger_info ttt 
        join tb_callBlast_dailyTrigger_dtl dt on ttt.fk_cid = dt.fk_cid
        join tb_callBlast cb on cb.cid = dt.fk_cid
        join tb_callBlast_uploadContact cuc on cuc.fk_cid = cb.cid
        where curdate() between startDate and endDate
        and ttt.working_day = dayname(curdate())
        and cb.blastStatus = 1
        and isSend = 0;
                
		DROP TEMPORARY TABLE IF EXISTS tt_timeConvert_final;
        CREATE TEMPORARY TABLE tt_timeConvert_final AS
        SELECT tt.ttid,tt.fk_cid,tt.startTime,tt.endTime,tt.working_day,tt.timeZone,tt.outboundNumber,tt.campaignMessageType,tt.campaignMessage,tt.textSpeechFile
        ,tt.contact,tt.importContact,tt.importContactFile
        ,(CURRENT_TIME() + INTERVAL tt.timezone_hour_extracted MINUTE + INTERVAL tt.timezone_minute_extracted MINUTE) as currentTime_to_trigger
        
        ,tt.startTime  as time_to_trigger,tt.domainId,tt.companyName,tt.triggerType,tt.campaignType,tt.addContact,tt.promptMessage,tt.frequency
        ,JSON_OBJECT("tt_startTime",time_format(tt.startTime,'%H:%i')
					,"tt_endTime",time_format(tt.endTime,'%H:%i')
					,"timeZone",SUBSTRING_INDEX(tt.timeZone, '(', 1)) AS Working_businessHours
        ,tt.contactType,tt.connectingAudio,tt.agentUnavailable,tt.agentReject,tt.blastName,tt.endDate
		FROM tt_timeConvert tt;
                
        SELECT ttid as triggeredId,fk_cid as blastId,startTime,working_day,timeZone,outboundNumber,campaignMessageType,campaignMessage,textSpeechFile,contact,importContact,importContactFile
        ,domainId,companyName,triggerType,campaignType,addContact,promptMessage,frequency
        ,Working_businessHours
        ,contactType,connectingAudio,agentUnavailable,agentReject,blastName,endDate
		FROM tt_timeConvert_final 
        WHERE TIME_FORMAT(time_to_trigger,'%H:%i') =  TIME_FORMAT(currentTime_to_trigger,'%H:%i');
        
        DROP TEMPORARY TABLE IF EXISTS tt_triggerId;
        CREATE TEMPORARY TABLE tt_triggerId AS
        SELECT ttid 
		FROM tt_timeConvert_final 
        WHERE TIME_FORMAT(time_to_trigger,'%H:%i') =  TIME_FORMAT(currentTime_to_trigger,'%H:%i');
                
        UPDATE tb_callBlast_timeToTrigger_info
        SET isSend = 1
        WHERE ttid IN (SELECT ttid FROM tt_triggerId);
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
