/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_leaderBoard_info_test`(
	p_domainId		INT 
    ,p_startDate	DATE 
    ,p_endDate		DATE
    ,p_blastId		INT
)
begin

	DECLARE v_countOfCampaign INT;
	
    DROP TEMPORARY TABLE IF EXISTS tt_callHistory;
    CREATE TEMPORARY TABLE tt_callHistory 
    AS SELECT ctc.tid,ctc.blastId,ctc.fk_triggeredId,ctc.agentExtn,ctc.agentName,(IFNULL(cdh.Duration,0)/1000) AS duration,ctc.callStatus,ctc.startTime
    ,ctc.phoneNumber,ctc.customerType,ctc.customerFirstName,ctc.customerLastName,ctc.createdAt,cdh.dispositionId,cdh.AgentId
	FROM tb_callBlast_triggered_customer_call_json_dtl ctc
    JOIN tb_callBlast cb ON ctc.blastId = cb.cid AND ctc.domainId = cb.domainId
    LEFT JOIN tb_CallHistory ch on ctc.sessionId = ch.sessionId
    LEFT JOIN tb_CallDurationHistory cdh on ch.CallHistoryId = cdh.CallHistoryId AND isListen = 0 AND isBarge = 0 AND isWhisper = 0
	WHERE ctc.domainId = p_domainId
    AND CAST(ctc.createdAt AS DATE) BETWEEN p_startDate AND p_endDate
    AND (ctc.agentName IS NOT NULL OR ctc.agentName <> '')
    AND (IFNULL(p_blastId,0) = 0 OR p_blastId = ctc.blastId);
        
    DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal;
    CREATE TEMPORARY TABLE tt_callHistory_cal 
    AS SELECT ch.tid,ch.blastId,ch.fk_triggeredId,ch.agentExtn,FLOOR(ch.duration) AS duration,ch.callStatus,ch.startTime
    ,ch.phoneNumber,ch.customerType,ch.customerFirstName,ch.customerLastName,ch.createdAt,ds.dispositionName,ch.agentName,ch.AgentId
	FROM tt_callHistory ch 
    LEFT JOIN disposition_status ds ON ch.dispositionId = ds.did;
	      
    SELECT count(distinct blastId) INTO v_countOfCampaign
    FROM tt_callHistory;

    DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_1;
    CREATE TEMPORARY TABLE tt_callHistory_cal_1
    AS SELECT
		AgentId
        ,CASE WHEN callStatus = 'answered' THEN 1 ELSE 0 END 			AS answeredCall
        ,CASE WHEN callStatus = 'answered' THEN duration ELSE 0 END 	AS answeredCallDuration
        ,CASE WHEN callStatus = 'unanswered' THEN 1 ELSE 0 END 			AS unansweredCall
        ,CASE WHEN callStatus = 'busy' THEN 1 ELSE 0 END 				AS busyCall
        ,CASE WHEN callStatus = 'agent_unavailable' THEN 1 ELSE 0 END 	AS agentUnavailableCall
        ,CASE WHEN callStatus = 'abandoned' THEN 1 ELSE 0 END 			AS abandonedCall
        ,CASE WHEN callStatus = 'not_reachable' THEN 1 ELSE 0 END 		AS notReachableCall
        ,CASE WHEN callStatus = 'agent_rejected' THEN 1 ELSE 0 END 		AS agentRejectedCall
        ,CASE WHEN callStatus = 'Not Triggered' THEN 1 ELSE 0 END 		AS notTriggeredCall
        ,CASE WHEN dispositionName = 'Resolved' THEN 1 ELSE 0 END 		AS ResolvedCall
        ,CASE WHEN dispositionName in ('Closed','Unresolved','Follow-up','Do not contact','Auto Triggered'
        ,'Caller Disconnected','Transferred') THEN 1 ELSE 0 END 		AS connectedCall
	FROM tt_callHistory_cal;
         
    DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final;
    CREATE TEMPORARY TABLE tt_callHistory_cal_final
    AS SELECT 
		AgentId
		,COUNT(answeredCall+unansweredCall+busyCall+agentUnavailableCall+abandonedCall+notReachableCall+agentRejectedCall+notTriggeredCall)				AS totalCalls
		,SUM(answeredCall)			AS answeredCall
		,SUM(ResolvedCall)			AS ResolvedCall
		,SUM(connectedCall)			AS connectedCall
		,SUM(answeredCallDuration)	AS answeredCallDuration
		,SUM(notTriggeredCall)		AS notTriggeredCall
    FROM tt_callHistory_cal_1
    GROUP BY AgentId;
    
    DROP TEMPORARY TABLE IF EXISTS tt_callHistory_cal_final_result;
    CREATE TEMPORARY TABLE tt_callHistory_cal_final_result
    AS SELECT 
        AgentId
		,CASE WHEN (totalCalls - notTriggeredCall) = 0 THEN 0 ELSE (answeredCall / (totalCalls - notTriggeredCall)) * 100 END AS connectedCallRate
		
		,CASE WHEN (totalCalls - notTriggeredCall) = 0 THEN 0 ELSE (answeredCall / (totalCalls - notTriggeredCall)) * 100 END AS successRate
		,CASE WHEN answeredCall = 0 THEN 0 ELSE ((answeredCallDuration) / answeredCall) END AS averageCallDuration
	FROM tt_callHistory_cal_final;

    SET @rownum := 0;
		
			DROP TEMPORARY TABLE IF EXISTS temp_final_result;
			CREATE TEMPORARY TABLE temp_final_result AS 
			SELECT  
				@rownum := @rownum + 1 AS number,
				subquery.AgentName,
				subquery.performance_score,
				subquery.Role,
				subquery.AgentId
			FROM (
				SELECT  
					u.UserName AS AgentName,
					u.userID AS AgentId,
					IFNULL(ROUND(
						(0.40 * SUM(connectedCallRate)) +
						(0.40 * SUM(successRate)) +
						(0.20 * SUM(averageCallDuration))
					, 0), 0) AS performance_score,
					CASE 
						WHEN u.roleid = 6 THEN 'Agent' 
						WHEN u.roleid = 3 THEN 'Admin' 
						WHEN u.roleid = 5 THEN 'Supervisor'  
					END AS Role
				FROM tt_callHistory_cal_final_result a
				JOIN tb_User u ON a.AgentId = u.UserID
				GROUP BY u.UserName, u.userID, u.roleid
				ORDER BY performance_score DESC, u.UserName
			) AS subquery;
            
            SELECT * FROM temp_final_result;
    
end ;;
DELIMITER ;
