DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_overAll_Campaigns`(
		p_blastId 			INT
		,p_domainId 		INT
		,p_campaignName 	VARCHAR(100)
		,p_campaignType		TINYINT
		,p_createdBy		VARCHAR(1000)
		,p_timeZone			TEXT
		,p_offset			INT
		,p_limit			INT 
		,p_statusName		varchar(150) 
  )
begin
  
		DECLARE v_offset INT;

		SET v_offset = p_limit * p_offset;

		DROP TEMPORARY TABLE IF EXISTS temp_createdBy;
		CREATE TEMPORARY TABLE temp_createdBy(tt_creatorName VARCHAR(100));

		DROP TEMPORARY TABLE IF EXISTS temp_timeZone;
		CREATE TEMPORARY TABLE temp_timeZone(tt_timeZone VARCHAR(100));

		DROP TEMPORARY TABLE IF EXISTS temp_statusName;
		CREATE TEMPORARY TABLE temp_statusName(statusName VARCHAR(50));

		CALL split(p_createdBy,','); INSERT INTO temp_createdBy(tt_creatorName) SELECT Items FROM tt_Split_temptable;
		CALL split(p_timeZone,','); INSERT INTO temp_timeZone(tt_timeZone) SELECT Items FROM tt_Split_temptable;
		CALL split(p_statusName,','); INSERT INTO temp_statusName(statusName) SELECT Items FROM tt_Split_temptable;

		DROP TEMPORARY TABLE IF EXISTS tt_overall_dtl;
		CREATE TEMPORARY TABLE tt_overall_dtl AS 
		SELECT cb.cid,cb.domainId,cb.blastName,cb.blastDescription,cb.triggerType,cb.timeZone,cb.outboundNumber,cb.campaignMessageType
		,cb.blastStatus,cb.createdBy,cb.callerId,cb.createdAt,cb.updatedAt,ctd.startDate,ctd.endDate,ctd.selectedDays,u.UserName as creatorName
        ,cb.campaignType,case when cb.triggerType = 2 then (CONCAT(CASE WHEN ctd.startDate >= CURDATE() THEN ctd.startDate ELSE CURDATE() END,' ',dj.StartTime,' ', dj.StartTimeFormat))
		when cb.triggerType = 1 then date_format(now(),'%Y-%m-%d %h:%i %p') 
		when cb.triggerType = 3 then  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(triggerCustomFile, '$.triggerDate')), ' '
			,CONCAT(JSON_UNQUOTE(JSON_EXTRACT(triggerCustomFile, '$.triggerTime')), ' ',
			JSON_UNQUOTE(JSON_EXTRACT(triggerCustomFile, '$.timeFormat'))))
		end as occurrenceTime
		,row_number() over (partition by cid) as rr
		,IFNULL(JSON_LENGTH(customerContact),0) AS countOfTriggerContact 
		,cuc.totalUploadedContact AS countOfContact
		,CASE WHEN cb.blastStatus = 0 THEN 'Deactivated' 
			WHEN cb.pause = 1 THEN 'Pause' 
			WHEN CONCAT(ctd.startDate,' ',ttt.startTime) <= CONCAT(CURDATE(),' ',ttt.startTime)
            THEN 'In Progress'
			ELSE 'Created'
		END as triggerStatus,cb.forceStop,cb.pause,cd.sessionId
		FROM  	tb_callBlast 								cb
		JOIN 	tb_callBlast_dailyTrigger_dtl 				ctd ON cb.cid = ctd.fk_cid
		JOIN	tb_User 									u 	ON cb.createdBy = u.ext AND cb.domainId = u.domainId
		LEFT JOIN tb_callBlast_dailyTrigger_json_dtl 		dj 	ON dj.fk_cid =  cb.cid AND dj.working_day collate utf8mb4_unicode_ci = dayname(CURDATE())
		LEFT JOIN tb_callBlast_triggered_customer_call_dtl 	tcc ON tcc.fk_cid = cb.cid
		LEFT JOIN tb_callBlast_timeToTrigger_info 			ttt ON ttt.fk_cid = cb.cid
        JOIN tb_callBlast_uploadContact 					cuc ON cuc.fk_cid = cb.cid
        JOIN tb_outbound_campaign_draft						cd	ON cd.campDraftId = cb.fk_campDraftId
		WHERE 	cb.domainId = p_domainId
		AND 	cb.completed IS NULL
		AND 	cb.forceStop = 0
		AND		(IFNULL(p_blastId,'')='' 		OR cb.cid = p_blastId)
		AND		(IFNULL(p_campaignName,'')='' 	OR cb.blastName  collate utf8mb4_unicode_ci  LIKE CONCAT('%',p_campaignName,'%'))
		AND		(IFNULL(p_campaignType,'')='' 	OR cb.campaignType  collate utf8mb4_unicode_ci  = p_campaignType)
		AND		(IFNULL(p_timeZone,'')='' 		OR cb.timeZone collate utf8mb4_unicode_ci in (SELECT tt_timeZone FROM temp_timeZone))	
		AND		(IFNULL(p_createdBy,'')='' 		OR u.UserName collate utf8mb4_unicode_ci in (SELECT tt_creatorName FROM temp_createdBy))
		AND		CASE WHEN triggerType = 2 THEN ctd.endDate >= CURDATE() ELSE ctd.endDate IS NOT NULL END;

		SELECT cid,domainId,blastName,blastDescription,triggerType,timeZone
			,outboundNumber,campaignMessageType,blastStatus,createdBy,callerId
			,createdAt,updatedAt,startDate,endDate
			,selectedDays,creatorName,campaignType
			,CASE WHEN triggerType = 2 THEN date_format(occurrenceTime,'%Y-%m-%d %h:%i %p') ELSE occurrenceTime END as occurrenceTime
			,countOfTriggerContact,countOfContact,triggerStatus
			,pause,forceStop,sessionId
		FROM tt_overall_dtl 
		WHERE rr = 1 
		AND ((triggerStatus collate utf8mb4_unicode_ci in (select statusName from temp_statusName)) or ifnull(p_statusName,'')='')
		AND CASE WHEN triggerType <> 2 THEN countOfContact <> countOfTriggerContact ELSE countOfTriggerContact IS NOT NULL END
		LIMIT v_offset,p_limit;

		SELECT DISTINCT campaignType as CampaignId, CASE WHEN campaignType = 1 THEN 'Agentless Dialling' WHEN campaignType = 2 THEN 'Predictive Dialling' END as CampaignName
		FROM   	tb_callBlast
		WHERE 	domainId = p_domainId;

		SELECT DISTINCT timeZone
		FROM   	tb_callBlast
		WHERE 	domainId = p_domainId;

		SELECT DISTINCT u.UserName as creatorName
		FROM   	tb_callBlast cb
		JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
		JOIN	tb_User u ON cb.createdBy = u.ext AND cb.domainId = u.domainId
		WHERE 	cb.domainId = p_domainId;

		SELECT COUNT(1) AS Count FROM tt_overall_dtl 
		where rr = 1
		AND CASE WHEN triggerType <> 2 THEN countOfContact <> countOfTriggerContact ELSE countOfTriggerContact IS NOT NULL END;

		drop temporary table if exists tt_sts;
		create temporary table tt_sts as 
		SELECT 
        DISTINCT CASE WHEN cb.blastStatus = 0 THEN 'Deactivated' 
			WHEN cb.pause = 1 THEN 'Pause' 
			WHEN CONCAT(ctd.startDate,' ',ttt.startTime) <= CONCAT(CURDATE(),' ',ttt.startTime) AND completed IS NULL
            THEN 'In Progress'
			ELSE 'Created'
		END as triggerStatus
		FROM   	tb_callBlast 								cb
		JOIN 	tb_callBlast_dailyTrigger_dtl 				ctd ON cb.cid = ctd.fk_cid
        LEFT JOIN tb_callBlast_timeToTrigger_info 			ttt ON ttt.fk_cid = cb.cid
		WHERE 	domainId = p_domainId;
     
		select * from tt_sts
		where (triggerStatus collate utf8mb4_unicode_ci in (select statusName from temp_statusName) or (ifnull(p_statusName,'')=''))   ;
  	
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_callBlast_overAll_dtl` */;
