/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_overAll_history_dtl`(	
 	 p_blastId 			INT
 	 ,p_domainId 		INT
     ,p_campaignName 	VARCHAR(100)
     ,p_campaignType	TINYINT
     ,p_createdBy		VARCHAR(1000)
     ,p_timeZone		TEXT
     ,p_startDate		BIGINT
     ,p_endDate			BIGINT
     ,p_statusName		varchar(1000)
     ,p_offset			INT
     ,p_limit			INT 
 )
begin
 
 	DECLARE v_offset INT;
    DECLARE v_Count INT;
     
     SET v_offset = p_limit * p_offset;
     
     DROP TEMPORARY TABLE IF EXISTS temp_createdBy;
     CREATE TEMPORARY TABLE temp_createdBy(tt_creatorName VARCHAR(100));
     
     DROP TEMPORARY TABLE IF EXISTS temp_timeZone;
     CREATE TEMPORARY TABLE temp_timeZone(tt_timeZone VARCHAR(100));
     
     DROP TEMPORARY TABLE IF EXISTS temp_get_history;
     CREATE TEMPORARY TABLE temp_get_history SELECT * FROM tb_callBlast_Deactivate_History;
     
	DROP TEMPORARY TABLE IF EXISTS temp_statusName;
	CREATE TEMPORARY TABLE temp_statusName(statusName VARCHAR(50));
 
     CALL split(p_createdBy,','); 
     INSERT INTO temp_createdBy(tt_creatorName) SELECT Items FROM tt_Split_temptable;
     CALL split(p_timeZone,',');
     
     INSERT INTO temp_timeZone(tt_timeZone) SELECT Items FROM tt_Split_temptable;
      
	 CALL split(p_statusName,','); 
     INSERT INTO temp_statusName(statusName) SELECT Items FROM tt_Split_temptable;
            
     IF (p_offset IS NULL AND p_limit IS NULL) 
     THEN
		 SELECT COUNT(1) INTO v_Count
		 FROM tb_callBlast cb
		 JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
		 LEFT JOIN	tb_callBlast_triggered_customer_call_dtl tcc ON tcc.fk_cid = cb.cid
		 WHERE cb.domainId = p_domainId
		 AND ctd.startDate <= CURDATE();
         
         SET p_offset = 0,p_limit = v_Count;
     END IF;

	INSERT INTO temp_get_history (`cid` , `domainId` , `blastName` , `blastDescription` , `triggerType` , `triggerDailyFile`, 
	`triggerCustomFile` , `timeZone`,  `outboundNumber`, `campaignMessageType`, `campaignMessage` , `textSpeechFile`, `blastStatus`,
	`createdBy` , `callerId` , `contactType`, `contact`, `importContact`, `importContactFile` , `createdAt`,  `updatedAt` , `startDate`,
	`endDate` , `selectedDays`, `noOfRecall` , `recallInterval`, `dailyHour`, `creatorName` , `companyName`, `addContact` ,`promptMessage` ,
	`campaignType` ,  `occurrenceTime` , `TypeName` , `Campaignstatus` ,`fk_triggeredId` ) SELECT 
	cb.cid, cb.domainId, cb.blastName, cb.blastDescription, cb.triggerType, cb.triggerDailyFile, cb.triggerCustomFile, cb.timeZone,
	cb.outboundNumber, cb.campaignMessageType, cb.campaignMessage, cb.textSpeechFile, cb.blastStatus, cb.createdBy, cb.callerId,
	cb.contactType, cuc.contact, cuc.importContact, cuc.importContactFile, cb.createdAt, cb.updatedAt, ctd.startDate, ctd.endDate,
	ctd.selectedDays, ctd.noOfRecall, ctd.recallInterval, ctd.dailyHour, u.UserName as creatorName, cb.companyName,cuc.addContact,
	cb.promptMessage,cb.campaignType
    ,CONCAT(
     DATE_FORMAT(tcc.createdAt, '%Y-%m-%d'), ' ',
     TIME_FORMAT(CONVERT_TZ(tcc.createdAt, '+00:00', '+05:30'), '%h:%i %p')
 	)
		,case when cb.triggerType = 2 then 'Daily' when cb.triggerType = 1 then 'Immediate' when cb.triggerType = 3 then 'Only Once' end as TypeName
		,CASE 	WHEN cb.blastStatus = 0 THEN 'Deactivated' 
			WHEN cb.pause = 1 THEN 'Pause' 
			WHEN cb.forceStop = 1 THEN 'Force Stopped' 
			WHEN CONCAT(ctd.startDate,' ',ttt.startTime) <= CONCAT(CURDATE(),' ',ttt.startTime)
            THEN 'In Progress'
			ELSE 'Completed'
		END as Campaignstatus
		,tcc.fk_triggeredId
		FROM  	tb_callBlast 								cb
		JOIN 	tb_callBlast_dailyTrigger_dtl 				ctd ON cb.cid = ctd.fk_cid
		JOIN	tb_User 									u 	ON cb.createdBy = u.ext AND cb.domainId = u.domainId
		LEFT JOIN tb_callBlast_dailyTrigger_json_dtl 		dj 	ON dj.fk_cid =  cb.cid 	AND dj.working_day = dayname(CURDATE())
		LEFT JOIN tb_callBlast_triggered_customer_call_dtl 	tcc ON tcc.fk_cid = cb.cid
        LEFT JOIN tb_callBlast_timeToTrigger_info 			ttt ON ttt.fk_cid = cb.cid
        JOIN tb_callBlast_uploadContact 					cuc ON cuc.fk_cid = cb.cid
		WHERE cb.domainId = p_domainId
		AND JSON_SEARCH(ctd.selectedDays, 'one', dayname(now()))
		AND CURDATE() between ctd.startDate AND ctd.endDate
		AND str_to_date(CONCAT(dj.StartTime,' ',dj.StartTimeFormat), '%h:%i:%s %p') <= time(convert_tz(time(now()), '+00:00','+05:30'))
		AND  cb.triggerType  in (2 , 3)
		AND	cb.blastStatus = 0;

    DROP TEMPORARY TABLE IF EXISTS tt_overall_dtl;
    CREATE TEMPORARY TABLE tt_overall_dtl AS
	SELECT 
		`cid` , `domainId` , `blastName` , `blastDescription` , `triggerType` , `triggerDailyFile`, 
		`triggerCustomFile` , `timeZone`,  `outboundNumber`, `campaignMessageType`, `campaignMessage` , `textSpeechFile`, `blastStatus`,
		`createdBy` , `callerId` , `contactType`, `contact`, `importContact`, `importContactFile` , `createdAt`,  `updatedAt` , `startDate`,
		`endDate` , `selectedDays`, `noOfRecall` , `recallInterval`, `dailyHour`, creatorName, `companyName`, `addContact` ,`promptMessage` ,
		`campaignType` ,  `occurrenceTime` , `TypeName` , `Campaignstatus` ,`fk_triggeredId`
		FROM temp_get_history where domainId = p_domainId
	UNION 
		SELECT cb.cid,cb.domainId,cb.blastName,cb.blastDescription,cb.triggerType,cb.triggerDailyFile,cb.triggerCustomFile,cb.timeZone,cb.outboundNumber,cb.campaignMessageType
		,cb.campaignMessage,cb.textSpeechFile,cb.blastStatus,cb.createdBy,cb.callerId,cb.contactType,cuc.contact,cuc.importContact,cuc.importContactFile,cb.createdAt,cb.updatedAt
		,ctd.startDate,ctd.endDate,ctd.selectedDays,ctd.noOfRecall,ctd.recallInterval,ctd.dailyHour
		,u.UserName COLLATE utf8mb4_general_ci as creatorName,cb.companyName,cuc.addContact,cb.promptMessage,cb.campaignType,
		CONCAT(
		DATE_FORMAT(tcc.createdAt, '%Y-%m-%d'), ' ',
		TIME_FORMAT(CONVERT_TZ(tcc.createdAt, '+00:00', '+05:30'), '%h:%i %p')
		)
		,case when cb.triggerType = 2 then 'Daily' when cb.triggerType = 1 then 'Immediate' when cb.triggerType = 3 then 'Only Once' end as TypeName
		,CASE 	WHEN cb.blastStatus = 0 THEN 'Deactivated' 
			WHEN cb.pause = 1 THEN 'Pause' 
			WHEN cb.forceStop = 1 THEN 'Force Stopped' 
			WHEN CONCAT(ctd.startDate,' ',ttt.startTime) <= CONCAT(CURDATE(),' ',ttt.startTime)
            THEN 'In Progress'
			ELSE 'Completed'
		END as Campaignstatus,tcc.fk_triggeredId
		FROM  	tb_callBlast cb
		JOIN 	tb_callBlast_dailyTrigger_dtl 				ctd ON cb.cid = ctd.fk_cid
		JOIN	tb_User 									u 	ON cb.createdBy = u.ext AND cb.domainId = u.domainId
		LEFT JOIN tb_callBlast_dailyTrigger_json_dtl 		dj 	ON dj.fk_cid =  cb.cid 	AND dj.working_day collate utf8mb4_0900_ai_ci = dayname(CURDATE())
		JOIN 	tb_callBlast_triggered_customer_call_dtl 	tcc ON tcc.fk_cid = cb.cid
        LEFT JOIN tb_callBlast_timeToTrigger_info 			ttt ON ttt.fk_cid = cb.cid
        JOIN tb_callBlast_uploadContact 					cuc ON cuc.fk_cid = cb.cid
		WHERE 	cb.domainId = p_domainId
		AND		(IFNULL(p_blastId,'')='' 		OR cb.cid = p_blastId)
		AND		(IFNULL(p_campaignName,'')='' 	OR cb.blastName collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_campaignName,'%'))
		AND		(IFNULL(p_campaignType,'')='' 	OR cb.campaignType collate utf8mb4_0900_ai_ci = p_campaignType)
		AND		(IFNULL(p_timeZone,'')='' 		OR cb.timeZone collate utf8mb4_0900_ai_ci in (SELECT tt_timeZone FROM temp_timeZone))	
		AND		(IFNULL(p_createdBy,'')='' 		OR u.UserName COLLATE utf8mb4_general_ci in (SELECT tt_creatorName FROM temp_createdBy))
		AND		ctd.startDate <= CURDATE()
		ORDER BY cid DESC,fk_triggeredId DESC
	LIMIT v_offset,p_limit;

	SELECT cid , domainId , blastName , blastDescription , triggerType , triggerDailyFile, 
		triggerCustomFile , timeZone,  outboundNumber, campaignMessageType, campaignMessage , textSpeechFile, blastStatus,
		createdBy , callerId , contactType, contact, importContact, importContactFile , createdAt,  updatedAt , startDate,
		endDate , selectedDays, noOfRecall , recallInterval, dailyHour, creatorName, companyName, addContact ,promptMessage ,
		campaignType ,  occurrenceTime , TypeName , Campaignstatus ,fk_triggeredId
	FROM 	tt_overall_dtl
    where 	((Campaignstatus collate utf8mb4_0900_ai_ci in (select statusName from temp_statusName)) or ifnull(p_statusName,'')='')
    AND 	CAST(createdAt AS DATE) BETWEEN DATE_FORMAT(FROM_UNIXTIME(p_startDate/1000),'%Y-%m-%d') AND DATE_FORMAT(FROM_UNIXTIME(p_endDate/1000),'%Y-%m-%d');

     SELECT DISTINCT campaignType as CampaignId, CASE WHEN campaignType = 1 THEN 'Agentless Dialling' WHEN campaignType = 2 THEN 'Predictive Dialling' END as CampaignName
     FROM   	tb_callBlast
     WHERE 	domainId = p_domainId;
     
     SELECT DISTINCT timeZone
     FROM   	tb_callBlast
     WHERE 	domainId = p_domainId;
     
     SELECT DISTINCT u.UserName as creatorName
     FROM   	tb_callBlast cb
     JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
     JOIN	tb_User u ON cb.createdBy = u.ext AND cb.domainId = u.domainId
     WHERE 	cb.domainId = p_domainId;
     
     SELECT COUNT(1) AS Count
     FROM tb_callBlast cb
     JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
     LEFT JOIN	tb_callBlast_triggered_customer_call_dtl tcc ON tcc.fk_cid = cb.cid
     WHERE cb.domainId = p_domainId
     AND ctd.startDate <= CURDATE()
     
     AND 	CAST(cb.createdAt AS DATE) BETWEEN DATE_FORMAT(FROM_UNIXTIME(p_startDate/1000),'%Y-%m-%d') AND DATE_FORMAT(FROM_UNIXTIME(p_endDate/1000),'%Y-%m-%d');
     
     SELECT distinct case when cb.blastStatus = 1 then 'Active' when cb.blastStatus = 0 then 'Deactivated' end as Campaignstatus
     FROM tb_callBlast cb
     JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
     LEFT JOIN	tb_callBlast_triggered_customer_call_dtl tcc ON tcc.fk_cid = cb.cid
     WHERE cb.domainId = p_domainId
     AND ctd.startDate <= CURDATE();
     
     truncate tb_callBlast_Deactivate_History;
     
     INSERT INTO tb_callBlast_Deactivate_History( `cid` , `domainId` , `blastName` , `blastDescription` , `triggerType` , `triggerDailyFile`, 
	  `triggerCustomFile` , `timeZone`,  `outboundNumber`, `campaignMessageType`, `campaignMessage` , `textSpeechFile`, `blastStatus`,
	  `createdBy` , `callerId` , `contactType`, `contact`, `importContact`, `importContactFile` , `createdAt`,  `updatedAt` , `startDate`,
	 `endDate` , `selectedDays`, `noOfRecall` , `recallInterval`, `dailyHour`, `creatorName` , `companyName`, `addContact` ,`promptMessage` ,
	 `campaignType` ,  `occurrenceTime` , `TypeName` , `Campaignstatus` ,`fk_triggeredId`) SELECT `cid` , `domainId` , `blastName` , `blastDescription` , `triggerType` , `triggerDailyFile`, 
	  `triggerCustomFile` , `timeZone`,  `outboundNumber`, `campaignMessageType`, `campaignMessage` , `textSpeechFile`, `blastStatus`,
	  `createdBy` , `callerId` , `contactType`, `contact`, `importContact`, `importContactFile` , `createdAt`,  `updatedAt` , `startDate`,
	 `endDate` , `selectedDays`, `noOfRecall` , `recallInterval`, `dailyHour`, `creatorName` , `companyName`, `addContact` ,`promptMessage` ,
	 `campaignType` ,  occurrenceTime, `TypeName` , `Campaignstatus` ,`fk_triggeredId` 
	 FROM temp_get_history
	 GROUP BY   `cid` , `domainId` , `blastName` , `blastDescription` , `triggerType` , `triggerDailyFile`, 
	  `triggerCustomFile` , `timeZone`,  `outboundNumber`, `campaignMessageType`, `campaignMessage` , `textSpeechFile`, `blastStatus`,
	  `createdBy` , `callerId` , `contactType`, `contact`, `importContact`, `importContactFile` , `createdAt`,  `updatedAt` , `startDate`,
	 `endDate` , `selectedDays`, `noOfRecall` , `recallInterval`, `dailyHour`, `creatorName` , `companyName`, `addContact` ,`promptMessage` ,
	 `campaignType` ,  `occurrenceTime` , `TypeName` , `Campaignstatus` ,`fk_triggeredId`;
	 
 
 end ;;
DELIMITER ;
