/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_callBlast_timeSplit` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_timeSplit`(
	 p_duration int
    , p_blastId INT
    )
sp_Ret:Begin

	declare v_StartTime time;
	declare v_EndTime time;
	declare cnt int;
	declare tcnt int;
    declare v_working_day varchar(10);

    	select min(dtid) into cnt from tb_callBlast_dailyTrigger_json_dtl WHERE fk_cid = p_blastId;
        
		DROP TEMPORARY TABLE IF EXISTS tt_chkkkk;
		CREATE TEMPORARY TABLE IF NOT EXISTS tt_chkkkk (
			id INT ,
			start_interval 	TIME,
			end_interval 	TIME,
            blastId			INT,
            working_day		VARCHAR(10)
		);

	select max(dtid) into tcnt from tb_callBlast_dailyTrigger_json_dtl WHERE fk_cid = p_blastId;

	while cnt<=tcnt do

		SELECT STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
        STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
        working_day
        into v_StartTime,v_EndTime,v_working_day from tb_callBlast_dailyTrigger_json_dtl where dtid = cnt;
		        
		insert into tt_chkkkk(id, start_interval, end_interval, blastId,working_day)
		WITH RECURSIVE CTE_TIMINGS AS (
		SELECT 	1 as id,v_StartTime AS start_interval, DATE_ADD(DATE_ADD(v_StartTime,INTERVAL p_duration MINUTE),INTERVAL 00 SECOND) AS end_interval,p_blastId as cId,v_working_day as working_day
		UNION ALL
		SELECT 	id+1 as id,end_interval as startDateTime,DATE_ADD(DATE_ADD(end_interval,INTERVAL p_duration MINUTE),INTERVAL 00 SECOND) AS end_interval,cId,working_day
		FROM 	CTE_TIMINGS
		WHERE 	end_interval < v_EndTime
		)
		select * from CTE_TIMINGS;

		set cnt = cnt +1;
	end while;

        
        INSERT INTO tb_callBlast_nextoccurrence_info(fk_cid,startTime,endTime,working_day)
        SELECT blastId,start_interval, end_interval, working_day
		FROM tt_chkkkk;

End ;;
DELIMITER ;
