DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_callBlast_triggered_call_history_dtl`(
       p_blastId 		INT,
       p_triggeredId 	INT,
       p_customerName 	VARCHAR(100),
       p_callStatus 	VARCHAR(50),
       p_agentName 		VARCHAR(50),
       p_phoneNumber	VARCHAR(50),
       p_limit			INT,
       p_offset			INT,
       p_disposition	INT
  )
BEGIN
  	
      DECLARE v_customerContact 	JSON;
      DECLARE v_JLength_json 		INT;
      DECLARE v_blastId 			INT;
      DECLARE v_triggeredId 		INT;
      DECLARE v_offset				INT;
      DECLARE v_Tcount				INT DEFAULT 0;
      DECLARE v_DomainID			INT;
      DECLARE v_blastName			VARCHAR(500);
      
      SET SESSION cte_max_recursion_depth = 10000;
      
      
      SET v_DomainID = (SELECT domainId FROM tb_callBlast_triggered_customer_call_json_dtl WHERE blastId = p_blastId limit 1);
      
      SET v_offset = p_limit * p_offset;
  	
	SELECT t1.customerContact, t1.fk_cid, t1.fk_triggeredId, t2.blastName INTO v_customerContact,v_blastId,v_triggeredId, v_blastName
	FROM tb_callBlast_triggered_customer_call_dtl 			t1
    JOIN tb_callBlast										t2		ON t1.fk_cid = t2.cid
	WHERE fk_cid = p_blastId AND fk_triggeredId = p_triggeredId;

      SET v_JLength_json = JSON_LENGTH(v_customerContact, "$");
  					 
  	DROP TEMPORARY TABLE IF EXISTS tt_json_extract;
  	CREATE TEMPORARY TABLE tt_json_extract AS
  	WITH RECURSIVE CTE_JsonCount AS (
  		SELECT 0 SlNo
  		UNION ALL
  		SELECT SlNo + 1 SlNo
  		FROM CTE_JsonCount
  		WHERE SlNo < v_JLength_json - 1
  	)
  	SELECT 
 		
  		TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].firstName')))) AS tt_firstName,
  		TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].lastName')))) AS tt_lastName,
  		TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].callStatus')))) AS tt_callStatus,
  		TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].phoneNumber')))) AS tt_phoneNumber,
          TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].duration')))) AS tt_duration,
  		TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].startTime')))) AS tt_startTime,
  		TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].customerType')))) AS tt_customerType,
         TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].agentName')))) AS tt_agentName,
         TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].agentExtn')))) AS tt_agentExtn,  
         TRIM(BOTH '"' FROM (json_extract(v_customerContact, CONCAT('$[', SlNo, '].sessionId')))) AS tt_sessionId 
  	FROM CTE_JsonCount;
  
      DROP TEMPORARY TABLE IF EXISTS tt_json_extract_dtl;
      CREATE TEMPORARY TABLE tt_json_extract_dtl 
      (
		SNo					INT  auto_increment primary key,
		firstName			VARCHAR(150)
		,lastName			VARCHAR(150)
		,callStatus 		VARCHAR(50)
		,phoneNumber		VARCHAR(50)
		,customerType		VARCHAR(50)
		,duration			INT
		,startTime			BIGINT 
		,agentName    		VARCHAR(50)
		,agentExtn   		VARCHAR(5)
		,sessionId   		VARCHAR(500)
      );
  							
  	insert into tt_json_extract_dtl(firstName,lastName,callStatus,phoneNumber,customerType,duration,startTime,agentName,agentExtn,sessionId)
  	select distinct 
     CASE WHEN tt_firstName ='' THEN 'New' ELSE tt_firstName END,
     CASE WHEN tt_lastName ='' AND (tt_firstName ='New' OR tt_firstName ='') THEN 'Customer' ELSE tt_lastName END,
 	tt_callStatus,tt_phoneNumber,tt_customerType,tt_duration,tt_startTime,tt_agentName,tt_agentExtn,tt_sessionId
  	from tt_json_extract;

     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     
	if p_limit IS NOT NULL AND p_offset IS NOT NULL then 
			DROP TEMPORARY TABLE IF EXISTS tt_final_result;
			CREATE TEMPORARY TABLE tt_final_result AS 
		SELECT 
			DISTINCT SNo 
			,firstName
			,lastName
			,callStatus
			,phoneNumber
			,customerType
			,v_blastId as p_blastId
			,v_triggeredId as p_triggeredId
			,duration
			,startTime
			,agentName
			,agentExtn
			,sessionId
            ,v_blastName as blastName
      FROM tt_json_extract_dtl 
      WHERE phoneNumber IS NOT NULL
      AND CONCAT(firstName," ", lastName) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT("%",IFNULL(p_customerName,''),"%")
      AND (callStatus = p_callStatus OR IFNULL(p_callStatus , '')= '')
      AND agentName COLLATE utf8mb4_0900_ai_ci LIKE CONCAT("%",IFNULL(p_agentName,''),"%")
      AND phoneNumber COLLATE utf8mb4_0900_ai_ci LIKE CONCAT("%",IFNULL(p_phoneNumber,''),"%")
      LIMIT  p_limit OFFSET v_offset;
  
	ELSE 								
		DROP TEMPORARY TABLE IF EXISTS tt_final_result;
			CREATE TEMPORARY TABLE tt_final_result AS 
		SELECT 
			DISTINCT SNo 
			,firstName
			,lastName
			,callStatus
			,phoneNumber
			,customerType
			,v_blastId as p_blastId
			,v_triggeredId as p_triggeredId
			,duration
			,startTime
			,agentName
			,agentExtn
			,sessionId
            ,v_blastName as blastName
      FROM tt_json_extract_dtl 
      WHERE phoneNumber IS NOT NULL
      AND CONCAT(firstName," ", lastName) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT("%",IFNULL(p_customerName,''),"%")
      AND (callStatus = p_callStatus OR IFNULL(p_callStatus , '')= '')
      AND agentName COLLATE utf8mb4_0900_ai_ci LIKE CONCAT("%",IFNULL(p_agentName,''),"%")
      AND phoneNumber COLLATE utf8mb4_0900_ai_ci LIKE CONCAT("%",IFNULL(p_phoneNumber,''),"%");
	END IF;
  
  
  
 	DROP TEMPORARY TABLE IF EXISTS tt_final_result_cal;
     CREATE TEMPORARY TABLE tt_final_result_cal AS 
      SELECT 
      fr.SNo
      ,fr.firstName
      ,fr.lastName
      ,fr.callStatus
      ,fr.phoneNumber
      ,fr.customerType
      ,fr.p_blastId
      ,fr.p_triggeredId
      ,fr.duration
      ,fr.startTime
      ,fr.agentName
      ,fr.agentExtn
      ,fr.sessionId
      ,ch.CallHistoryId
      ,ds.dispositionName
      ,ds.colorCode
      ,ds.type as colorCodeType
      ,fr.blastName
	FROM tt_final_result fr
	LEFT JOIN tb_CallHistory 			ch  ON fr.sessionId COLLATE utf8mb4_0900_ai_ci = ch.sessionId
	LEFT JOIN tb_CallDurationHistory 	cdh ON ch.CallHistoryId = cdh.CallHistoryId AND isListen = 0 AND isBarge = 0 AND isWhisper = 0
    LEFT JOIN disposition_status		ds  ON ds.did = cdh.dispositionId
    
    WHERE  (ifnull(p_disposition,'') = '' OR  cdh.dispositionId = p_disposition);
 
	DROP TEMPORARY TABLE IF EXISTS tt_final_result_calculation;
	CREATE TEMPORARY TABLE tt_final_result_calculation AS
      select 
      fr.SNo
      ,fr.firstName
      ,fr.lastName
      ,fr.callStatus
      ,fr.phoneNumber
      ,fr.customerType
      ,fr.p_blastId
      ,fr.p_triggeredId
      ,fr.duration
      ,fr.startTime
      ,fr.agentName
      ,fr.agentExtn
      ,i.notes
      ,fr.dispositionName
      ,fr.colorCode
      ,fr.colorCodeType
     , fr.blastName
      from tt_final_result_cal fr
      left join tb_interaction_notes_info i on i.historyId = fr.CallHistoryId
      ORDER BY SNo;
      
      SELECT SNo ,firstName ,lastName ,callStatus ,phoneNumber ,customerType ,p_blastId ,p_triggeredId
			,duration ,startTime ,agentName ,agentExtn ,notes ,dispositionName ,colorCode ,colorCodeType, blastName
      FROM tt_final_result_calculation;
      
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      SELECT COUNT(*) INTO v_Tcount
      FROM tt_final_result_calculation;
   
      SELECT v_Tcount AS TotalCount;
      
 		SELECT DISTINCT callStatus FROM tb_callBlast_triggered_customer_call_json_dtl WHERE domainId = v_DomainID;
      
          SELECT UserName  AS "agentName" FROM tb_User  WHERE domainId = v_DomainID;
 
  END ;;
DELIMITER ;
