CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_Get_Channel_Message`( 
		p_HistoryId 				BIGINT,
		p_ChatDurationHistoryId		BIGINT,
		p_channelType 				VARCHAR(255),
		p_domainId 					INT,
		p_ext 						INT)
BEGIN
 	DECLARE v_UserID INT;
 
 	IF p_channelType IS NULL OR p_channelType = '' THEN SET p_channelType = 'Call,Chat,Email,Sms,Whatsapp,Facebook,Instagram,Video'; END IF;
    
    IF p_channelType LIKE '%Chat%' 
    THEN  
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		SELECT 	a.Message   
		FROM 	tb_ChatMessage 			a
		JOIN 	tb_ChatDurationHistory 	b 	ON 	a.ChatDurationHistoryId = b.ChatDurationHistoryId 
        JOIN 	tb_ChatHistory 			c 	ON 	c.ChatHistoryId			= b.ChatHistoryId 
											AND c.domainId				= p_domainId
		WHERE 	a.ChatDurationHistoryId = p_ChatDurationHistoryId
        AND		b.ChatHistoryId			= p_HistoryId; 
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF;
    
  	IF p_channelType LIKE '%Call%' 
      THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT UserID into v_UserID from tb_User WHERE domainId = p_domainId AND ext =p_ext; 
          
  		SELECT 	a.Message   
  		FROM 	tb_CallMessage a
  		JOIN 	tb_CallDurationHistory b ON a.CallHistoryId = b.CallHistoryId 
  		WHERE 	a.CallHistoryId = p_HistoryId
  		AND 	b.AgentId = v_UserID;                                                     
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  	END IF;
    
    IF p_channelType LIKE '%Email%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT Message FROM tb_EmailMessage em 
  		JOIN tb_EmailHistory eh ON em.EmailHistoryId = eh.EmailHistoryId
  		WHERE em.EmailHistoryId = p_HistoryId
  		AND eh.DomainId = p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF;
    
    IF p_channelType LIKE '%Sms%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT Message FROM tb_SMSMessage sm
        JOIN tb_SMSHistory sh ON sm.SMSHistoryId = sh.SMSHistoryId
        WHERE  sm.SMSHistoryId = p_HistoryId
        AND 	sh.domainId 	= p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF;
    
    IF p_channelType LIKE '%Whatsapp%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT Message FROM tb_WhatsappMessage wm
        JOIN tb_WhatsappHistory wh ON wm.WhatsappHistoryId = wh.WhatsappHistoryId
 		WHERE  wm.WhatsappHistoryId = p_HistoryId
 		AND  wh.domainId = p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF;
    
    IF p_channelType LIKE '%Facebook%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT Message FROM tb_FacebookMessage fm
        JOIN tb_FacebookHistory fh ON fm.FacebookHistoryId = fh.FacebookHistoryId
 		WHERE  fm.FacebookHistoryId = p_HistoryId
 		AND  fh.domainId = p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF;
 
    IF p_channelType LIKE '%Instagram%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT Message FROM tb_InstagramMessage fm
        JOIN tb_InstagramHistory fh ON fm.InstagramHistoryId = fh.InstagramHistoryId
 		WHERE  fm.InstagramHistoryId = p_HistoryId
 		AND  fh.domainId = p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF;   
    
    IF p_channelType LIKE '%Video%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT 	Message 
        FROM 	tb_VideoMessage VM
        JOIN 	tb_VideoHistory VH ON VM.VideoHistoryId = VH.VideoHistoryId
 		WHERE  	VM.VideoHistoryId = p_HistoryId
 		AND  	VH.domainId = p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF; 
 END ;;
DELIMITER ;
