/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_Get_Channel_Message_NLP`( 
		IN p_HistoryId 				BIGINT,
		IN p_ChatDurationHistoryId	BIGINT,
		IN p_channelType 			VARCHAR(255),
		IN p_domainId 				INT,
		IN p_ext 					INT
   )
BEGIN
  	DECLARE v_UserID INT;
  
  	IF p_channelType IS NULL OR p_channelType = 'All' THEN SET p_channelType = 'Call,Chat,Email,Sms,Whatsapp,Facebook,Instagram,Video'; END IF;
     
     IF p_channelType LIKE '%Chat%' 
     THEN  
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 	a.Message,
				c.ChatHistoryId,
				c.sessionId,
				a.updatedAt  AS lastUpdatedAt,
				U.UserName  AS agentName,
				b.IsBot   
		FROM 	tb_ChatMessage 			a
		JOIN 	tb_ChatDurationHistory 	b 	ON 	a.ChatDurationHistoryId = b.ChatDurationHistoryId 
		JOIN 	tb_ChatHistory 			c 	ON 	c.ChatHistoryId			= b.ChatHistoryId 
											AND c.domainId				= p_domainId
		LEFT JOIN tb_User 				U	ON U.UserID = b.AgentId
		
		WHERE 	b.ChatHistoryId			= p_HistoryId; 
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     END IF;
     
   	IF p_channelType LIKE '%Call%' 
       THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		SELECT UserID into v_UserID from tb_User WHERE domainId = p_domainId AND ext =p_ext; 
           
			SELECT 	a.Message,   
					c.CallHistoryId,
					c.sessionId,
					a.updatedAt AS lastUpdatedAt,
					U.UserName AS agentName,
					b.IsBot
			FROM 	tb_CallMessage a
			JOIN 	tb_CallDurationHistory  b ON a.CallHistoryId = b.CallHistoryId 
            JOIN 	tb_CallHistory			c ON c.CallHistoryId = b.CallHistoryId
            LEFT JOIN tb_User 				U ON U.UserID = b.AgentId
			WHERE 	c.domainId = p_domainId
            AND		a.CallHistoryId = p_HistoryId
			AND 	b.AgentId = v_UserID;                                                     
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
   	END IF;
     
     IF p_channelType LIKE '%Email%' THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT Message ,
					eh.EmailHistoryId,
					eh.sessionId,
					em.updatedAt  AS lastUpdatedAt,
					U.UserName AS agentName,
					edh.IsBot
			FROM tb_EmailMessage 			em 
			JOIN tb_EmailHistory 			eh  ON em.EmailHistoryId = eh.EmailHistoryId
            JOIN tb_EmailDurationHistory 	edh ON eh.EmailHistoryId = edh.EmailHistoryId
            LEFT JOIN tb_User 				U 	ON U.UserID = edh.AgentId
			WHERE em.EmailHistoryId = p_HistoryId
			AND eh.DomainId = p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     END IF;
     
     IF p_channelType LIKE '%Sms%' THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT Message, 
					sh.SMSHistoryId,
					sh.sessionId,
					sm.updatedAt AS lastUpdatedAt,
					U.UserName AS agentName,
					sdh.IsBot
			FROM tb_SMSMessage 			sm
			JOIN tb_SMSHistory 			sh 	ON sm.SMSHistoryId = sh.SMSHistoryId
			JOIN tb_SMSDurationHistory 	sdh ON sh.SMSHistoryId = sdh.SMSHistoryId
			LEFT JOIN tb_User 			U 	ON U.UserID = sdh.AgentId
			WHERE   sm.SMSHistoryId = p_HistoryId
			AND 	sh.domainId 	= p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     END IF;
     
     IF p_channelType LIKE '%Whatsapp%' THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT wh.WhatsappHistoryId,
					wh.sessionId,
					wm.updatedAt AS lastUpdatedAt,
					U.UserName AS agentName,
					wdh.IsBot,
                    Message
			FROM tb_WhatsappMessage 		wm
			JOIN tb_WhatsappHistory 		wh 	ON wm.WhatsappHistoryId = wh.WhatsappHistoryId
			JOIN tb_WhatsappDurationHistory wdh	ON wh.WhatsappHistoryId = wdh.WhatsappHistoryId
            LEFT JOIN tb_User 				U 	ON U.UserID = wdh.AgentId
			WHERE  wm.WhatsappHistoryId = p_HistoryId
			AND  wh.domainId = p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     END IF;
     
     IF p_channelType LIKE '%Facebook%' THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT Message ,
					fh.FacebookHistoryId,
					fh.sessionId,
					fm.updatedAt AS lastUpdatedAt,
					U.UserName AS agentName,
					fh.IsBot
			FROM tb_FacebookMessage 	fm
			JOIN tb_FacebookHistory 	fh 	ON fm.FacebookHistoryId = fh.FacebookHistoryId
            LEFT JOIN tb_User 			U 	ON U.UserID = fh.AgentId
			WHERE  fm.FacebookHistoryId = p_HistoryId
			AND  fh.domainId = p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     END IF;
  
     IF p_channelType LIKE '%Instagram%' THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT Message ,
				fh.InstagramHistoryId,
				fh.sessionId,
				fm.updatedAt AS lastUpdatedAt,
				U.UserName AS agentName,
				fh.IsBot
			FROM tb_InstagramMessage fm
			JOIN tb_InstagramHistory fh ON fm.InstagramHistoryId = fh.InstagramHistoryId
            LEFT JOIN tb_User		 U 	ON U.UserID = fh.AgentId
			WHERE  fm.InstagramHistoryId = p_HistoryId
			AND  fh.domainId = p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     END IF;  
     
     IF p_channelType LIKE '%Video%' THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT 	Message ,
				VH.VideoHistoryId,
				VH.sessionId,
				VM.updatedAt AS lastUpdatedAt,
				U.UserName AS agentName			
			FROM 	tb_VideoMessage 		VM
			JOIN 	tb_VideoHistory 		VH 	ON VM.VideoHistoryId = VH.VideoHistoryId
			JOIN 	tb_VideoDurationHistory VDH ON VH.VideoHistoryId = VDH.VideoHistoryId
            LEFT JOIN tb_User		 		U 	ON U.UserID = VDH.AgentId
			WHERE  	VM.VideoHistoryId = p_HistoryId
			AND  	VH.domainId = p_domainId;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    END IF; 
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_Get_Channel_Message_NLP_v2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_Get_Channel_Message_NLP_v2`( 
  		IN p_HistoryId 				BIGINT,
  		IN p_DurationHistoryId	BIGINT,
  		IN p_channelType 			VARCHAR(255),
  		IN p_domainId 				INT,
  		IN p_ext 					INT
     )
BEGIN
    	DECLARE v_UserID INT;
    
    	IF p_channelType IS NULL OR p_channelType = 'All' THEN SET p_channelType = 'Call,Chat,Email,Sms,Whatsapp,Facebook,Instagram,Video'; END IF;
       
       IF p_channelType LIKE '%Chat%' 
       THEN  
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		SELECT 	a.Message,b.StartTime,b.EndTime,b.AgentId,u.UserName,u.queueId,b.Duration ,d.dispositionName,c.sessionId,q.name as QueueName
 				,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
		FROM 	tb_ChatMessage 			a
		JOIN 	tb_ChatDurationHistory 	b 	ON 	a.ChatDurationHistoryId = b.ChatDurationHistoryId  and a.ChatHistoryId	= b.ChatHistoryId 
		JOIN 	tb_ChatHistory 			c 	ON 	c.ChatHistoryId			= b.ChatHistoryId  AND c.domainId				= p_domainId
		LEFT JOIN tb_User				u	ON	u.UserID				= b.AgentId
		LEFT JOIN disposition_status	d	ON	d.did					= b.dispositionId
		LEFT JOIN queue					q	ON	q.qid					= u.queueId
		WHERE 	a.ChatDurationHistoryId = p_DurationHistoryId
		AND		b.ChatHistoryId		= p_HistoryId; 
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END IF;
       
     	IF p_channelType LIKE '%Call%' 
         THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		
             
     		SELECT 	a.Message,b.StartTime,b.EndTime,b.AgentId,u.UserName,b.QueueId,b.Duration ,d.dispositionName,c.sessionId,q.name as QueueName
 					,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
     		FROM 	tb_CallMessage 			a
     		JOIN 	tb_CallDurationHistory 	b 	ON 	a.CallDurationHistoryId = b.CallDurationHistoryId and a.CallHistoryId	= b.CallHistoryId 
             JOIN 	tb_CallHistory 			c 	ON 	c.CallHistoryId			= b.CallHistoryId 		AND c.domainId			= p_domainId
             LEFT JOIN tb_User				u	ON	u.UserID				= b.AgentId
 			LEFT JOIN disposition_status	d	ON	d.did					= b.dispositionId
             LEFT JOIN queue					q	ON	q.qid					= b.QueueId
     		WHERE 	a.CallDurationHistoryId = p_DurationHistoryId
             and 	a.CallHistoryId 		= p_HistoryId;
     		
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     	END IF;
         
       IF p_channelType LIKE '%Email%' THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		SELECT em.Message ,eh.SessionStartTime as StartTime,eh.SessionEndTime as EndTime,edh.AgentId,u.UserName,edh.QueueId,edh.Duration,d.dispositionName,eh.sessionId ,q.name as QueueName 
 					,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
             FROM tb_EmailMessage 			em 
     		JOIN tb_EmailHistory 			eh	ON em.EmailHistoryId = eh.EmailHistoryId AND eh.domainId 	= p_domainId
             JOIN tb_EmailDurationHistory 	edh	ON em.EmailHistoryId = edh.EmailHistoryId
             LEFT JOIN tb_User				u	ON	u.UserID				= edh.AgentId
 			LEFT JOIN disposition_status	d	ON	d.did					= eh.DispositionId
             LEFT JOIN queue					q	ON	q.qid					= edh.QueueId
     		WHERE em.EmailHistoryId = p_HistoryId
     		AND eh.DomainId = p_domainId;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END IF;
                   
 
       IF p_channelType LIKE '%Sms%' THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			SELECT Message ,sh.SessionStartTime as StartTime,sh.SessionEndTime as EndTime,edh.AgentId,u.UserName,edh.QueueId,edh.Duration,d.dispositionName,sh.sessionId  ,q.name as QueueName
 				,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
 			FROM tb_SMSMessage 				sm
 			JOIN tb_SMSHistory 				sh 	ON sm.SMSHistoryId = sh.SMSHistoryId AND sh.domainId 	= p_domainId
 			JOIN tb_SMSDurationHistory 		edh	ON sm.SMSHistoryId = edh.SMSHistoryId
 			LEFT JOIN tb_User				u	ON	u.UserID				= edh.AgentId
 			LEFT JOIN disposition_status	d	ON	d.did					= sh.DispositionId
             LEFT JOIN queue					q	ON	q.qid					= edh.QueueId
 			WHERE  sm.SMSHistoryId = p_HistoryId
 			AND		sh.domainId 	= p_domainId;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END IF;
       
       IF p_channelType LIKE '%Whatsapp%' THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			SELECT Message ,sh.SessionStartTime as StartTime,sh.SessionEndTime as EndTime,edh.AgentId,u.UserName,edh.QueueId,edh.Duration,d.dispositionName,sh.sessionId  ,q.name as QueueName
 					,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
 			FROM tb_WhatsappMessage 		sm
 			JOIN tb_WhatsappHistory 		sh 	ON sm.WhatsappHistoryId = sh.WhatsappHistoryId AND sh.domainId 	= p_domainId
 			JOIN tb_WhatsappDurationHistory edh	ON sm.WhatsappHistoryId = edh.WhatsappHistoryId
 			LEFT JOIN tb_User				u	ON	u.UserID				= edh.AgentId
 			LEFT JOIN disposition_status	d	ON	d.did					= sh.DispositionId
             LEFT JOIN queue					q	ON	q.qid					= edh.QueueId
 			WHERE  sm.WhatsappHistoryId = p_HistoryId
 			AND		sh.domainId 	= p_domainId;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END IF;
            
       IF p_channelType LIKE '%Facebook%' THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           SELECT Message ,sh.SessionStartTime as StartTime,sh.SessionEndTime as EndTime,sh.AgentId,u.UserName,sh.QueueId,sh.Duration,d.dispositionName,sh.sessionId  ,q.name as QueueName
 				,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent
 			FROM tb_FacebookMessage 		sm
 			JOIN tb_FacebookHistory 		sh 	ON sm.FacebookHistoryId = sh.FacebookHistoryId AND sh.domainId 	= p_domainId
 			LEFT JOIN tb_User				u	ON	u.UserID				= sh.AgentId
 			LEFT JOIN disposition_status	d	ON	d.did					= sh.DispositionId
             LEFT JOIN queue					q	ON	q.qid					= sh.QueueId
             WHERE  sm.FacebookHistoryId = p_HistoryId
 			AND		sh.domainId 	= p_domainId;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END IF;
  
 	IF p_channelType LIKE '%Instagram%' THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           SELECT Message ,sh.SessionStartTime as StartTime,sh.SessionEndTime as EndTime,sh.AgentId,u.UserName,sh.QueueId,sh.Duration,d.dispositionName,sh.sessionId  ,q.name as QueueName
 				,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
 			FROM tb_InstagramMessage 				sm
 			JOIN tb_InstagramHistory 				sh 	ON sm.InstagramHistoryId = sh.InstagramHistoryId AND sh.domainId 	= p_domainId
 			LEFT JOIN tb_User				u	ON	u.UserID				= sh.AgentId
 			LEFT JOIN disposition_status	d	ON	d.did					= sh.DispositionId
             LEFT JOIN queue					q	ON	q.qid					= sh.QueueId
             WHERE  sm.InstagramHistoryId = p_HistoryId
 			AND		sh.domainId 	= p_domainId;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END IF;  
      
       IF p_channelType LIKE '%Video%' THEN
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          SELECT Message ,sh.SessionStartTime as StartTime,sh.SessionEndTime as EndTime,edh.AgentId,u.UserName,edh.QueueId,edh.agentDuration as Duration,d.dispositionName,sh.sessionId  ,q.name as QueueName
 				,SentimentalScore,sentimentalScoreCustomer,sentimentalScoreAgent,Summary
 		FROM tb_VideoMessage 				sm
 		JOIN tb_VideoHistory 				sh 	ON sm.VideoHistoryId = sh.VideoHistoryId AND sh.domainId 	= p_domainId
 		JOIN tb_VideoDurationHistory 		edh	ON sm.VideoHistoryId = edh.VideoHistoryId
 		LEFT JOIN tb_User				u	ON	u.UserID				= edh.AgentId
 		LEFT JOIN disposition_status	d	ON	d.did					= edh.DispositionId
         LEFT JOIN queue					q	ON	q.qid					= edh.QueueId
   		WHERE  	sm.VideoHistoryId = p_HistoryId
   		AND  	sh.domainId = p_domainId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
      END IF; 
    END ;;
DELIMITER ;
