CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_ChatArticleDetails`(
 	p_ChatCategoryId INT,
     p_web_id		 INT
  )
begin
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 
 			ChatArticleId,
             DomainId,
             web_id,
             ChatCategoryId,
             FilePath,
             ArticleLanguage,
             CreatedBy,
             CreatedDate,
             UpdatedBy,
             UpdatedDate
             FROM tb_ChatArticle 
             WHERE 	ChatCategoryId 	= p_ChatCategoryId
             AND 	web_id 			= p_web_id;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 
  end ;;
