CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_chatFlowHistory_dtl`(
 p_domainId int,
 p_chatFlowId int
 )
Begin
 	select nodes, isLangEnabled from chatFlowHistory where domainId = p_domainId and (chatFlowId = p_chatFlowId or ifnull(p_chatFlowId,0)=0);
 End ;;
