CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_chatflow_details`(
	p_chatFlowId	INT
    ,p_domainId		INT
)
begin
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
        
		SELECT 	chatFlowId,templateName,nodes,edges,language,version,type,status,description,createdAt
				,updateAt,publishData,action,category,channelType 
		FROM chatFlowHistory 
		WHERE (IFNULL(p_chatFlowId,'')='' OR chatFlowId = p_chatFlowId)
		AND domainId = p_domainId
        ORDER BY chatFlowId DESC;
        
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
end ;;
DELIMITER ;
