/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_chat_dashboard`(
			p_startTmpstmp bigint,
			p_endTmpstmp   bigint,
			p_domainId     int,
			p_ext          int
		)
begin 
     	DECLARE v_Total						INT;		DECLARE v_Inbound				INT;		DECLARE v_Service_level			INT;		DECLARE v_Queued_customers		INT;		DECLARE v_Resolved				INT;
     	DECLARE v_Unresolved				INT;		DECLARE v_Abandoned				INT;		DECLARE v_Transferred			INT;		DECLARE v_Callback_requested	INT;		DECLARE v_MissedAgent			INT;
     	DECLARE v_InteractionWithin30Secs 	INT;		DECLARE v_startTmpstmp			BIGINT;		DECLARE v_endTmpstmp			BIGINT;		DECLARE v_QueuedCustomers		INT;		DECLARE v_roleid				TINYINT;
     	DECLARE v_MissedChat				INT;		DECLARE v_ThresholdCount 		INT;		DECLARE v_TransferredCount		INT;
                    
  	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
 	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  	      
             
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
    	SELECT 	roleid INTO v_roleid
    	FROM 	tb_User U
    	WHERE	U.domainId	= p_domainId
    	AND 	U.ext		= IFNULL(p_ext,200)
    	LIMIT 1;
   
  	DROP TEMPORARY TABLE IF EXISTS temp_ChatDurationHistory;
  	CREATE TEMPORARY TABLE temp_ChatDurationHistory	
  	SELECT 	cth.ChatHistoryId
  		,	ctd.ChatDurationHistoryId	
  		,	cth.sessionStartTime
  		,	cth.IsInBound
  		,	cth.dialDuration
  		,	ctd.Istransferred   
        ,	ctd.answeredDuration
  		,	ds.dispositionName
  		,	tu.ext 					AS UserExt
  		,	cth.CallBackStatus
  		,	cth.IsMissed				AS IsMissedChat
  		,	ctd.IsMissed				AS IsMissedAgent
  		,	ctd.IsAbandoned
        ,	ctd.IsBot
        ,	ctd.dispositionId
  	FROM tb_ChatHistory 				cth
  	LEFT JOIN tb_ChatDurationHistory 	ctd on cth.ChatHistoryId 	= ctd.ChatHistoryId	
  	LEFT JOIN disposition_status		ds 	on ds.did				= ctd.dispositionId and cth.domainId = ds.domainId 
  	LEFT JOIN tb_User					tu 	on tu.UserID 			= ctd.AgentId 		and cth.domainId = tu.domainId  
  	WHERE 	cth.domainId = p_domainId 
  	AND 	cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp
  	AND 	(tu.ext = p_ext OR v_roleid IN (3,5));     
     
    
    
    SELECT SUM(case when IFNULL(answeredDuration, 0) > 0 then 1 else 0 end) 
	INTO v_ThresholdCount
	FROM (SELECT DISTINCT ChatHistoryId, answeredDuration FROM temp_ChatDurationHistory WHERE dispositionName <> 'Transferred') AS subquery;
    
	SELECT 	sum(case when dispositionName = 'Transferred' then 1 else 0 end) INTO v_TransferredCount
    FROM temp_ChatDurationHistory
    WHERE IsBot = 0;
     
  	SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
  	FROM 	queueWeighTimeChat QWT
  	WHERE 	QWT.domainId = p_domainId;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
  	CREATE TEMPORARY TABLE temp_ChatHistory	
  	SELECT 	DISTINCT ChatHistoryId, IsInBound, sessionStartTime, IsMissedChat, dialDuration,CallBackStatus
  	FROM 	temp_ChatDurationHistory;
        
  	SELECT 	SUM(CASE WHEN sessionStartTime <> 0 THEN 1 ELSE 0 END)      
  		,	SUM(CASE WHEN IsInBound = 1 AND sessionStartTime <> 0  THEN 1 ELSE 0 END)
  		,	SUM(IsMissedChat)
  		,	v_ThresholdCount
 		,	SUM(CallBackStatus)
  	INTO 	v_Total
  		,	v_Inbound		
  		,	v_MissedChat
  		,	v_InteractionWithin30Secs
 		,   v_Callback_requested        
  	FROM 	temp_ChatHistory;    
       
        	SELECT 	SUM(CASE WHEN a.dispositionName = 'Resolved' THEN 1 ELSE 0 END)
          		,	SUM(CASE WHEN a.dispositionName = 'Unresolved' THEN 1 ELSE 0 END)
    			, 	SUM(IsAbandoned)
          		,	SUM(CASE WHEN a.IsInBound = 1 AND a.Istransferred = 1  THEN 1 ELSE 0 END)     		
          		,	SUM(IsMissedAgent)
           	
        	INTO 	v_Resolved
        			,v_Unresolved
        			,v_Abandoned
        			,v_Transferred   			
        			,v_MissedAgent
        		
        	FROM temp_ChatDurationHistory a ;
				
        	SET v_InteractionWithin30Secs =  IF(v_InteractionWithin30Secs = 0, 0, v_InteractionWithin30Secs / v_Total * 100);
        	 
        	SELECT  IFNULL(v_Total,0)					AS Total
        		,	IFNULL(v_Inbound,0)					AS Inbound
        		,	IFNULL(v_Resolved,0)				AS Resolved
        		,	IFNULL(v_Unresolved,0)				AS Unresolved
        		,	IFNULL(v_Abandoned,0)				AS Abandoned
        		,	IFNULL(v_TransferredCount,0)		AS Transferred
        		,	v_InteractionWithin30Secs			AS servicelevel
        		,	CASE WHEN v_roleid IN (3,5) THEN IFNULL(v_MissedAgent,0) ELSE IFNULL(v_MissedChat,0) END AS Missed 
        		
        		,	IFNULL(v_QueuedCustomers,0)			AS QueuedCustomers
        		,	IFNULL(v_Callback_requested,0)		AS Callback_requested;
              
              IF p_ext IS NULL
              THEN
              select ext from tb_User where domainId = p_domainId and roleid in (3,5);
  			END IF;
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_chat_duration_dao` */;
