CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_chat_duration_dao`(p_ChatHistoryId			BIGINT)
BEGIN

		 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
         
			SELECT ChatDurationHistoryId,
					ChatHistoryId,
					StartTime,
					EndTime,
					Duration,
					AgentHoldDuration,
					AgentId,
					AgentSkillId,
					IsBot,
					BotId,
					QueueId,
					createdAt,
					updatedAt,
					transferredTime,
					dispositionId,
					transferedBy,
					transferedTo,
					ticketId,
					Summary,
					SentimentalScore,
					sentimentalScoreCustomer,
					sentimentalScoreAgent,
					markAsRead,
					answeredDuration,
					afterChatWorkTime,
					Istransferred,
					IsMissed,
					IsAbandoned,
					chatDeflection,
					isTrigger
                    FROM tb_ChatDurationHistory	WHERE ChatHistoryId = p_ChatHistoryId;
                    
                    
                    
                    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                    
                    

END ;;
