CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_chat_widget_name_validation`(
	 p_title_name		VARCHAR(250)
    ,p_domainId			INT 
)
begin

	DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(150) DEFAULT 'Name already exists';

	IF NOT EXISTS(SELECT 1 
    FROM chat_configuration_primary_form 
    WHERE domainId = p_domainId
    AND title = p_title_name)
    THEN
		SET v_errcode  	= 0;
        SET v_errmsg	= 'Name available';
	END IF;
		
	SELECT v_errcode AS errcode,v_errmsg AS errmsg;
end ;;
DELIMITER ;
