CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_check_is_disposition_name`(
	p_dispositionName	VARCHAR(100)
	,p_domainId			INT
)
begin

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		SELECT did,dispositionName,type,description,status,createdAt,updatedAt,domainId,colorCode,accessType
		FROM disposition_status 
		WHERE dispositionName collate utf8mb4_0900_ai_ci = p_dispositionName 
		AND domainId = p_domainId;
    
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
end ;;
