CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_coid_by_customerId`(
 p_customerId 		varchar(50)
,p_domainId 		int
,p_channelType      varchar(20)
)
begin
	 IF p_channelType = 'Facebook'
	 THEN
		SELECT coid,firstName,lastName,primaryPhoneNumber,primaryEmail
		FROM customer_contact
		WHERE domainId 			= p_domainId
		AND facebook            collate utf8mb4_0900_ai_ci = p_customerId;
	ELSEIF p_channelType = 'Instagram'
    THEN
		SELECT coid,firstName,lastName,primaryPhoneNumber,primaryEmail 
		FROM customer_contact
		WHERE domainId 			= p_domainId
		AND   instagram         collate utf8mb4_0900_ai_ci = p_customerId;
	END IF;
end ;;
DELIMITER ;
