CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_connector_domain_token`(
	p_conId					INT,
    p_domainId				INT	
)
BEGIN

		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		SELECT 
					idcol
					,domainId
					,roleId
					,connector_name
					,token
					,contactSyncDetails
					,syncStatus
					,syncTime
					,contactSyncType
					,conId
					,isConnected
					,createAt
					,updateAt
							
        FROM ccaas_crm_connector_token_info WHERE conId= p_conId and domainId=  p_domainId;
		
        
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

END ;;
