CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_connector_token_info`(
	p_domainId INT
)
begin

	SELECT idcol,domainId,roleId,connector_name,token,createAt,updateAt,contactSyncDetails,syncStatus
	,conId,syncTime,contactSyncType,isConnected 
