CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_conversation_List`(
 p_sessionId		VARCHAR(255)
 ,p_domainId		INT
 )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
 	SELECT 	CH.conId
 		,	CH.sessionId
 		,	CH.from
 		,	CH.to
 		,	CH.messageType
 		,	CH.message
 		,	CH.id
 		,	CH.timeStamp
 		,	CH.agentState
 		,	CH.customerState
 		,	CH.botDetails
 		,	CH.domainId
 		,	CH.companyId
 		,	CH.isBot
 		,	CH.createdAT
     FROM  	conversationHistory CH
     WHERE 	sessionId collate utf8mb4_0900_ai_ci	= p_sessionId
     AND 	domainId 	= p_domainId;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
 END ;;
DELIMITER ;
