CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_conversation_triggers`(
 p_triggerid int,
 p_domainId int
 )
Begin
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 	SELECT 	CT.id
		,  	CT.domainId
		,  	CT.triggerName
		,	CT.`description`
		,	CT.keywords
		,	CT.createAt
		,	CT.updatedAt
    FROM 	ccaas_conversation_triggers CT
	WHERE 	CT.domainId = p_domainId 
    AND 	(CT.id = p_triggerid OR IFNULL(p_triggerid,0)=0)
    ORDER BY CT.id DESC;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 End ;;
DELIMITER ;
