CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_crm_connector_token`(
        p_domainId int 
        )
Begin
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	select 	domainId, roleId 
		,	REPLACE(connector_name,'_',' ')	AS connector_name
		, 	token, contactSyncDetails, syncStatus, conId,syncTime,contactSyncType
	from 	ccaas_crm_connector_token_info 
	where 	domainId = p_domainId
	AND      isConnected = 1;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 End ;;
