CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_CRM_ContactSyncDetails1`(
  IN p_csid INT,
  IN p_domainId INT,
  IN p_roleId INT,
  IN p_connectorId INT,
  IN p_connectorName VARCHAR(50),
  IN p_moduleName VARCHAR(50),
  IN p_refreshTime BIGINT,
  IN p_primaryParameter VARCHAR(50),
  IN p_syncParameterArray JSON
)
BEGIN
  DECLARE v_csid INT;
  DECLARE v_errcode INT;
  DECLARE v_errmsg VARCHAR(50);

  SELECT csid INTO v_csid
  FROM tb_CRM_ContactSyncDetails
  WHERE domainId = p_domainId;

  IF v_csid IS NULL THEN
    INSERT INTO tb_CRM_ContactSyncDetails (
      domainId,
      roleId,
      connectorId,
      connectorName,
      moduleName,
      refreshTime,
      primaryParameter,
      syncParameterArray
    ) VALUES (
      p_domainId,
      p_roleId,
      p_connectorId,
      p_connectorName,
      p_moduleName,
      p_refreshTime,
      p_primaryParameter,
      p_syncParameterArray
    );

    IF ROW_COUNT() > 0 THEN
      SET v_errcode = 0;
      SET v_errmsg = 'Inserted Successfully';
    END IF;
  ELSE
    UPDATE tb_CRM_ContactSyncDetails
    SET
      roleId = IFNULL(p_roleId, roleId),
      connectorId = IFNULL(p_connectorId, connectorId),
      connectorName = IFNULL(p_connectorName, connectorName),
      moduleName = IFNULL(p_moduleName, moduleName),
      refreshTime = IFNULL(p_refreshTime, refreshTime),
      primaryParameter = IFNULL(p_primaryParameter, primaryParameter),
      syncParameterArray = IFNULL(p_syncParameterArray, syncParameterArray)
    WHERE csid = v_csid;

    IF ROW_COUNT() > 0 THEN
      SET v_errcode = 1;
      SET v_errmsg = 'Updated Successfully';
    END IF;
  END IF;

  SELECT v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
