CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_customer_conatct_phone_number`(
   p_domainId int
   ,p_firstName	varchar(100)
   ,p_lastName	varchar(100)
   ,p_phoneNumber	varchar(750)
   ,p_email	varchar(1500)
   ,p_accountNumber	varchar(100)
   ,p_tags	varchar(750)
   ,p_location	varchar(100)
   ,p_address	varchar(225)
   ,p_country	varchar(100)
   ,p_state	varchar(100)
   ,p_city	varchar(100)
   ,p_postalCode	varchar(100)
   ,p_facebook	varchar(100)
   ,p_instagram	varchar(100)
   ,p_whatsapp	varchar(100)
   ,p_twitter	varchar(100)
   ,p_customerType varchar(255)
   ,p_voiceBiometric	varchar(100)
   ,p_emailPhoneNo varchar(100)
   )
sp_return: begin
   
   	declare v_errcode int default -1;
 	declare v_errmsg text default 'Failure';
     
     DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
 	BEGIN
 		GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
 		set v_errmsg =  CONCAT(@st, ' : ', @p2);
 		set  @st='';
 		select -1 as v_errcode, v_errmsg as errmsg;
 		ROLLBACK;
 	END; 
 
   	START TRANSACTION;
   	if not exists(SELECT 1 FROM customer_contact WHERE (phoneNumber collate utf8mb4_0900_ai_ci = p_phoneNumber OR email collate utf8mb4_0900_ai_ci = p_phoneNumber) AND domainId =p_domainId) then
   		INSERT INTO customer_contact (firstName,lastName,phoneNumber,email,accountNumber,tags,location,address,country,state,city,postalCode,facebook,instagram,whatsapp,twitter,
               domainId,createdAt,voiceBiometric,customerType) 
   		VALUES (p_firstName,p_lastName,p_phoneNumber,p_email,p_accountNumber,p_tags,p_location,p_address,p_country,p_state,p_city,p_postalCode,p_facebook,p_instagram,p_whatsapp,p_twitter,
   			p_domainId,current_timestamp(),p_voiceBiometric,p_customerType);
   	End if;
    
 	COMMIT;    
    
           SELECT  coid,firstName, lastName, primaryPhoneNumber, phoneNumber, primaryEmail, email, accountNumber, tags, location, address, country, state, city, postalCode, facebook, instagram, whatsapp, twitter, createdAt, updatedAt, voiceBiometric, domainId, mergeCustomer, blockCustomer, doNotDisturb, blockCustomerReq, doNotDisturbReq, type, currentCustomerNumber, customerType, Timezone, blockedBy, doNotDisturbBy, blockedReqBy, doNotDisturbReqBy, Reason, cookiesId, Source, attachments 
           FROM customer_contact WHERE domainId = p_domainId and (phoneNumber collate utf8mb4_0900_ai_ci = p_phoneNumber OR email collate utf8mb4_0900_ai_ci  = p_phoneNumber);

   
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
