CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_customer_conatct_source_list`(	
      	p_domainId 			INT
      	)
BEGIN  	
		
        DROP TEMPORARY TABLE IF EXISTS temp_CustomerContact;
        CREATE TEMPORARY TABLE temp_CustomerContact AS 
      	SELECT distinct Source FROM customer_contact WHERE domainId = p_domainId;
	
		SELECT case when Source is null then 'Native' else `Source` end as `Source` 
        FROM temp_CustomerContact;
 
END ;;
DELIMITER ;
