CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_customer_contact`(
	p_coid 		INT
    ,p_domainId	INT
)
Begin
	SELECT 
			 coid
			,firstName
			,lastName
			,primaryPhoneNumber
			,phoneNumber
			,primaryEmail
			,email
			,accountNumber
			,tags
			,location
			,address
			,country
			,state
			,city
			,postalCode
			,facebook
			,instagram
			,whatsapp
			,twitter
			,createdAt
			,updatedAt
			,voiceBiometric
			,domainId
			,mergeCustomer
			,blockCustomer
			,doNotDisturb
			,blockCustomerReq
			,doNotDisturbReq
			,type
			,currentCustomerNumber
			,customerType
			,Timezone
			,blockedBy
			,doNotDisturbBy
			,blockedReqBy
			,doNotDisturbReqBy
			,Reason
			,cookiesId
			,Source
			,attachments
			,CustomerUniqueId
            ,CASE WHEN CAST(createdAt AS DATE) >= (NOW() - INTERVAL 7 DAY) THEN 1 ELSE 0 END AS is_new_customer
    FROM customer_contact 
    WHERE coid = p_coid
    AND domainId = p_domainId;
End ;;
DELIMITER ;
