CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_customer_contact_NLP`(
 p_SessionId 		VARCHAR(250)
,p_domainId			INT
,p_channelType		VARCHAR(50)
)
Begin

		DECLARE v_CustomerId	INT;
	
		IF p_channelType = 'Call'
        THEN
			SELECT CustomerId INTO v_CustomerId
			FROM tb_CallHistory
			WHERE domainId = p_domainId 
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;
            
		ELSEIF p_channelType = 'Chat'
		THEN
			SELECT CustomerId INTO v_CustomerId
			FROM tb_ChatHistory 
			WHERE domainId = p_domainId 
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;
            
		ELSEIF p_channelType = 'Email'
		THEN
			SELECT CustomerId INTO v_CustomerId
			FROM tb_EmailHistory
			WHERE domainId = p_domainId 
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;
            
		ELSEIF p_channelType = 'SMS'
		THEN
			SELECT customerId INTO v_CustomerId
			FROM tb_SMSHistory
			WHERE domainId = p_domainId 
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;
            
		ELSEIF p_channelType = 'Whatsapp'
		THEN
			SELECT customerId INTO v_CustomerId
			FROM tb_WhatsappHistory
			WHERE domainId = p_domainId
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;

		ELSEIF p_channelType = 'Facebook'
		THEN
			SELECT customerId INTO v_CustomerId
			FROM tb_FacebookHistory
			WHERE domainId = p_domainId
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;
            
		ELSEIF p_channelType = 'Instagram'
		THEN
			SELECT customerId INTO v_CustomerId
			FROM tb_InstagramHistory
			WHERE domainId = p_domainId
			AND sessionId = p_SessionId
            AND CustomerId IS NOT NULL
            LIMIT 1;
		END IF;

	SELECT 
			 coid
			,firstName
			,lastName
			,primaryPhoneNumber
			,phoneNumber
			,primaryEmail
			,email
			,accountNumber
			,tags
			,location
			,address
			,country
			,state
			,city
			,postalCode
			,facebook
			,instagram
			,whatsapp
			,twitter
			,createdAt
			,updatedAt
			,voiceBiometric
			,domainId
			,mergeCustomer
			,blockCustomer
			,doNotDisturb
			,blockCustomerReq
			,doNotDisturbReq
			,type
			,currentCustomerNumber
			,customerType
			,Timezone
			,blockedBy
			,doNotDisturbBy
			,blockedReqBy
			,doNotDisturbReqBy
			,Reason
			,cookiesId
			,Source
			,attachments
			,CustomerUniqueId
            ,CASE WHEN CAST(createdAt AS DATE) >= (NOW() - INTERVAL 7 DAY) THEN 1 ELSE 0 END AS is_new_customer
    FROM customer_contact 
    WHERE coid = v_CustomerId
    AND domainId = p_domainId;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
