/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_customer_count_for_year`(
     p_domainId INT
)
BEGIN
    WITH RECURSIVE months AS (
        SELECT DATE_FORMAT(CURDATE(), '%Y-01-01') AS month_start
        UNION ALL
        SELECT month_start + INTERVAL 1 MONTH
        FROM months
        WHERE month_start < DATE_FORMAT(CURDATE(), '%Y-12-01')
    ),
    customer_counts AS (
        SELECT MONTH(createdAt) AS month_num, COUNT(*) AS ct
        FROM customer_contact
        WHERE domainId = p_domainId
		AND createdAt BETWEEN DATE_FORMAT(CURDATE(), '%Y-01-01') AND DATE_FORMAT(CURDATE(), '%Y-12-31')
        GROUP BY MONTH(createdAt)
    )
    SELECT MONTHNAME(m.month_start) AS MonthName,COALESCE(c.ct, 0) AS count_of_customer
    FROM months m
    LEFT JOIN customer_counts c ON MONTH(m.month_start) = c.month_num
    ORDER BY m.month_start;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
