CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_customer_details_by_phoneNumber`(
    phoneNumber varchar(30)
    )
Begin
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	SELECT * 
	FROM customer_contact a 
	WHERE COALESCE(a.firstName, '') <> '' 
	AND COALESCE(a.lastName, '') <> '' 
	AND (a.primaryPhoneNumber LIKE CONCAT('%', phoneNumber, '%')
	OR a.phoneNumber LIKE CONCAT('%', phoneNumber, '%'))
	ORDER BY coid DESC 
	LIMIT 1;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    End ;;
DELIMITER ;
