CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_customer_details_by_phoneNumber_test1`(
     phoneNumber varchar(30)
    ,p_domainId	 int
    )
Begin

	DECLARE v_coid INT;
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    
    SELECT coid INTO v_coid
    WHERE (a.primaryPhoneNumber LIKE CONCAT('%', phoneNumber, '%')
	OR a.phoneNumber LIKE CONCAT('%', phoneNumber, '%'))
    AND domainId = p_domainId;
    
    IF v_coid IS NULL
    THEN
		SELECT coid INTO v_coid
		WHERE (phoneNumber LIKE CONCAT('%',a.primaryPhoneNumber,'%')
		OR phoneNumber LIKE CONCAT('%',a.phoneNumber,'%'))
		AND domainId = p_domainId;
	END IF;
    
    SELECT v_coid;
    
	SELECT coid, firstName, lastName, primaryPhoneNumber, phoneNumber, primaryEmail, email, accountNumber, tags, location, address, country, state, city, postalCode, facebook, instagram, whatsapp
    , twitter, createdAt, updatedAt, voiceBiometric, domainId, mergeCustomer, blockCustomer, doNotDisturb, blockCustomerReq, doNotDisturbReq, type, currentCustomerNumber, customerType, Timezone
    , blockedBy, doNotDisturbBy, blockedReqBy, doNotDisturbReqBy, Reason, cookiesId, Source, attachments, CustomerUniqueId 
	FROM customer_contact a 
	WHERE coid = p_domainId
	ORDER BY coid DESC 
	LIMIT 1;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    End ;;
