CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_customer_message_by_coid`(
	p_domainId	INT
    ,p_coid		INT
)
begin

SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;

	select CH.ChatHistoryId,CH.CustomerId,CONCAT(ifnull(CC.firstName,''),ifnull(CC.lastName,'')) AS customer_name,CM.Message,CC.createdAt
	FROM tb_ChatHistory 			CH
	JOIN tb_ChatMessage 			CM ON CH.ChatHistoryId = CM.ChatHistoryId
	JOIN customer_contact 			CC ON CC.coid = CH.CustomerId
	WHERE CH.domainId = p_domainId
	AND CH.CustomerId = p_coid
    AND CAST(CH.createdAt AS DATE) = CURDATE();
    
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	


end ;;
