DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_custom_shared_report`(
	p_domainId int
	,p_agentId int
)
Begin
    SELECT reportId, reportCategory, reportName, u.UserName, DATE_FORMAT(cr.updatedAt, '%Y/%m/%d') AS ReceivedOn,
    CASE WHEN cr.expireDate IS NULL THEN '-' ELSE DATE_FORMAT(cr.expireDate, '%Y/%m/%d') END AS expireDate,isPassword,password
	FROM tb_custom_report_dtl cr 
	JOIN tb_User u ON cr.createdBy = u.UserID
	WHERE cr.domainId = p_domainId 
    AND FIND_IN_SET(p_agentId, cr.agentId) > 0
    AND ( cr.isExpired = 0 OR (cr.isExpired = 1 AND cr.expireDate >= CURDATE()) );
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
