/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_call_piechart`(
        p_startTmpstmp bigint, 
        p_endTmpstmp bigint, 
        p_Timezone varchar(55), 
        p_domainId int,
        p_ext int
        
        )
BEGIN           
 		
 	DECLARE  	v_totalResolved INT;
 	DECLARE		v_totalUnresolved INT;
     DECLARE     v_totalAbandoned INT;
     DECLARE     v_totalTransferred INT;
     DECLARE     v_totalMissed INT;
          	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		select IFNULL(COUNT(dispositionName),0) INTO v_totalResolved  
         from disposition_status ds 
 		JOIN tb_CallHistory 	tc  	ON tc.dispositionId 	= ds.did  and tc.domainId = ds.domainId 
 		where ds.domainId = p_domainId 	and ds.dispositionName	= 'Resolved' group by ds.domainId;
        
 		select IFNULL(COUNT(dispositionName),0) INTO v_totalUnresolved
         from disposition_status ds 
 		JOIN tb_CallHistory 	tc  	ON tc.dispositionId 	= ds.did  and tc.domainId = ds.domainId 
 		where ds.domainId = p_domainId 	and ds.dispositionName	= 'Unresolved' group by ds.domainId;
 
 		select IFNULL(COUNT(dispositionName),0) INTO v_totalAbandoned 
         from disposition_status ds 
 		JOIN tb_CallHistory 	tc  	ON tc.dispositionId 	= ds.did  and tc.domainId = ds.domainId 
 		where ds.domainId = p_domainId 	and ds.dispositionName	= 'Abandoned' group by ds.domainId;
         
 		select IFNULL(COUNT(dispositionName),0) INTO v_totalTransferred 
         from disposition_status ds 
 		JOIN tb_CallHistory 	tc  	ON tc.dispositionId 	= ds.did  and tc.domainId = ds.domainId 
 		where ds.domainId = p_domainId 	and ds.dispositionName	= 'Transferred' group by ds.domainId;
 
 		select IFNULL(COUNT(dispositionName),0) INTO v_totalMissed 
         from disposition_status ds 
 		JOIN tb_CallHistory 	tc  	ON tc.dispositionId 	= ds.did  and tc.domainId = ds.domainId 
 		where ds.domainId = p_domainId 	and ds.dispositionName	= 'Missed' group by ds.domainId;
         
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
         SELECT  IFNULL(v_totalResolved,0)							AS TotalResolved
  		,		IFNULL(v_totalUnresolved,0)							AS TotalUnresolved
 		,		IFNULL(v_totalAbandoned,0)							AS TotalAbandoned
 		,		IFNULL(v_totalTransferred,0)						AS TotalTransferred
 		,		IFNULL(v_totalMissed,0)								AS TotalMissed ;
 
     
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_call_piechart_feautre_details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dashboard_call_piechart_feautre_details`(
                 	p_startTmpstmp BIGINT, 
                 	p_endTmpstmp   BIGINT, 
                 	p_Timezone     VARCHAR(55), 
                 	p_domainId     INT,
                 	p_ext          INT 
                 )
sp_return: BEGIN 
                				DECLARE v_TotalCalls				INT;		DECLARE	v_TotalInboundCalls			INT;		DECLARE v_OutboundCalls 			INT;		DECLARE v_TotalCallback 			INT;
                				DECLARE v_TotalVoicemail 			INT;        DECLARE v_CostPerCall  				decimal(20,2);		DECLARE v_CallAbandonRate 			INT;		DECLARE v_CallsTransferRate 		INT;             		
                				DECLARE v_AverageWrapUpTime 		INT;		DECLARE v_Averageholddurationtime 	INT;		DECLARE v_AverageCallsPerMinute 	INT;		DECLARE v_unresolved				INT;
                				DECLARE v_agent_answered_call		INT;		DECLARE v_Resolved					INT;    	DECLARE v_startTmpstmp				BIGINT;		DECLARE v_endTmpstmp				BIGINT;
                				DECLARE v_InteractionWithin30Secs	INT;    	DECLARE v_Missed					INT;   		DECLARE v_QueuedCustomers			INT;		DECLARE v_Total_Answered_Sessions	INT;
                				DECLARE v_roleid					INT;
                                
                                declare v_isOutboundCampaign		INT;		
                            
                			
                              
                              
                 	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY)) * 1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
       				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_endTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;                      
                                   
       				DROP TEMPORARY TABLE IF EXISTS temp_userid; 		CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT);
       				DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT,ext INT);    
                                   
                     			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                       			INSERT INTO temp_AvailableUser
                       			(	UserId
                       				,UserName
                       				,roleid
               						,ext
                       			)
                       			SELECT  UserID
                       				,	UserName
                       				,	roleid
               						,	ext
                       			FROM 	tb_User
                       			WHERE 	domainId 	= p_domainId
                       			AND 	roleid		IN (6,5,3)  ;
                       			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                                    
                       			SELECT 	roleid 	INTO v_roleid
                       			FROM 	temp_AvailableUser
                       			WHERE 	ext = p_ext; 	
                                  
                                  SET v_roleid = IFNULL(v_roleid,3);
                     			
                       			IF v_roleid in (3,5) 
                       			THEN
                       				INSERT INTO temp_userid
                       				(	UserId )
                       				SELECT  UserID
                       				FROM 	temp_AvailableUser ;
                       			ELSE		
                       				INSERT INTO temp_userid
                       				(	UserId )
                       				SELECT  UserID
                                       FROM 	temp_AvailableUser 
                                       WHERE 	ext = p_ext;
                       			END IF;            
      							
                                  DROP TEMPORARY TABLE IF EXISTS temp_userid1; 		
                                  CREATE TEMPORARY TABLE temp_userid1
   							   SELECT * FROM temp_userid;
                       			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                           		DROP temporary TABLE IF EXISTS tt_temp_CallHistory;
                           		CREATE TEMPORARY TABLE tt_temp_CallHistory 
                           		SELECT 	clh.CallHistoryId, clh.sessionStartTime, clh.sessionEndTime, cld.dispositionId , cld.UMNStatus, IFNULL(clh.IsInBound,1) IsInBound, clh.dialDuration, 
                           				clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.waitDuration, cld.afterCallWorkTime, CASE WHEN transferedTo IS NULL THEN 0 else 1 END Istransferred, 
                           				clh.callDuration, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, 
                           				cld.QueueId, 'Call' as channelType,ds.dispositionName,tu.UserID, IFNULL(cld.IsMissedCall,0) IsMissedCall, callCost, callBack
                                           
										,cld.answeredDuration,clh.voicemailUrl, 
                                        isOutboundCampaign						
                           		FROM tb_CallHistory 			clh
                           		JOIN tb_CallDurationHistory 	cld ON clh.CallHistoryId 	= cld.CallHistoryId    		
       							left JOIN temp_userid			tu	ON cld.AgentId			= tu.UserId  
								left JOIN temp_userid1			ASS	ON clh.assignedTo		= ASS.UserId  
               					LEFT JOIN disposition_status	ds 	ON ds.did				= cld.dispositionId
       																AND clh.domainId 		= ds.domainId  
                           		WHERE 	clh.domainId = p_domainId 
                           		AND	 	clh.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp
                                   AND 	(tu.UserId is not null	or v_roleid in (3,5));
               					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;					
      
     							if p_ext = 200 then
               					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;                     
     								DROP TEMPORARY TABLE IF EXISTS tt_temp_CallHistory_1;
     								CREATE TEMPORARY TABLE tt_temp_CallHistory_1 
     								AS
  									SELECT    DISTINCT(CallHistoryId) as CallHistoryId,IsInBound ,case when callBack = 1 then 1 else 0 end as callBack ,case when IsInBound = 0 then 1 else 0 end as outbound FROM tt_temp_CallHistory ;     
               					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                                 else
     								SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;                     
     								DROP TEMPORARY TABLE IF EXISTS tt_temp_CallHistory_1;
     								CREATE TEMPORARY TABLE tt_temp_CallHistory_1 
     								AS
     								
                                    SELECT DISTINCT CallHistoryId,
										   CASE WHEN callBack = 3 AND IsInBound = 1 THEN 1 ELSE 0 END AS IsInBound,
										   CASE WHEN IsInBound = 0 THEN 1 ELSE 0 END AS outbound,
										   MAX(IsMissedCall) OVER (PARTITION BY CallHistoryId) AS IsMissedCall,
										   CASE WHEN callBack = 1 THEN 1 ELSE 0 END AS callBack
									FROM tt_temp_CallHistory;
                                    
               					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                                 end if;
                           
                           		select 	 SUM(CASE WHEN IFNULL(a.callDuration,0) > 0 THEN 1 ELSE 0 END)
 										,SUM(CASE WHEN a.dispositionName = 'Unresolved' THEN 1 ELSE 0 END)
 										,SUM(CASE WHEN a.dispositionName = 'Resolved' THEN 1 ELSE 0 END)
 										,SUM(IsMissedCall)
 										,SUM(case when IFNULL(answeredDuration,0) > 0 and dispositionName <> 'Transferred' then 1 else 0 end)
                                        
              							,SUM(CASE WHEN voicemailUrl <> '0' AND voicemailUrl LIKE 'http%' AND StartTime = 0 THEN 1 ELSE 0 END )
              							,sum(callCost) / COUNT(1)
              							,SUM(CASE WHEN IsInBound = 1 AND dispositionName = 'Caller Disconnected' THEN 1 ELSE 0 END)
              							,SUM(IFNULL(a.Istransferred,0))
              							,SUM(case when a.afterCallWorkTime is not null and a.afterCallWorkTime <> 0 and a.StartTime is not null then a.afterCallWorkTime/1000 else 0 end)
              							,SUM(CASE WHEN ifnull(a.StartTime,0) > 0 THEN 1 ELSE 0 END)
              							,SUM(CASE WHEN a.AgentHoldDuration <> 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL THEN ifnull(a.AgentHoldDuration/1000,0) ELSE 0 END)
              							,SUM(CASE WHEN a.callDuration <> 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL THEN ifnull(a.callDuration/1000,0) ELSE 0 END)
                                        ,SUM(IFNULL(isOutboundCampaign,0)) 
                           		into 	v_agent_answered_call, 
                           				v_unresolved, 
                           				v_Resolved, 
                           			 	v_Missed, 
                           				v_InteractionWithin30Secs
   										,v_TotalVoicemail
   										,v_CostPerCall
                       					,v_CallAbandonRate
                       					,v_CallsTransferRate
                       					,v_AverageWrapUpTime
                       					,v_Total_Answered_Sessions
                       					,v_Averageholddurationtime
                       					,v_AverageCallsPerMinute,
                                        v_isOutboundCampaign		
                           		from tt_temp_CallHistory a;
                                
                				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                              
              				 SELECT     SUM(IsInBound)
               					   ,	SUM(outbound)
                                   
                                    , SUM(IsInBound)+SUM(outbound)
        						       ,  SUM(callBack)
                               INTO 	v_TotalInboundCalls
               					   ,	v_OutboundCalls
                                    ,  v_TotalCalls
                                    ,  v_TotalCallback
                               FROM 	tt_temp_CallHistory_1;     
                    
                            
                                  
                                  
							SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                        		SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
                            	FROM 	queueWeighTime QWT
                            	WHERE 	QWT.domainId = p_domainId and QWT.queueType = 'call';
							SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                               
                               if v_TotalInboundCalls =  0 		then set v_TotalInboundCalls = NULL; end if;
                               if v_Total_Answered_Sessions =  0 	then set v_Total_Answered_Sessions = NULL; end if;
                               if v_TotalCalls =  0 				then set v_TotalCalls = NULL; end if;
                           
                
                
                           	set v_AverageWrapUpTime = v_AverageWrapUpTime/v_Total_Answered_Sessions*100;
                               set v_Averageholddurationtime = v_Averageholddurationtime/v_TotalCalls;
                               set v_AverageCallsPerMinute = v_AverageCallsPerMinute/v_TotalCalls;
                                                
                              	SELECT  
                                        IFNULL(v_TotalCalls,0)												    AS TotalCalls
                              		,	IFNULL(v_TotalInboundCalls,0)											AS InboundCalls
                              		,	IFNULL(v_OutboundCalls,0) 												AS OutboundCalls
                              		,	IFNULL(v_TotalCallback,0) 												AS TotalCallback
                              		,	IFNULL(v_TotalVoicemail,0) 												AS TotalVoicemail	
                              		,	IFNULL(v_CostPerCall,0)  												AS CostPerCall
                              		,	IFNULL(v_CallAbandonRate,0) 											AS CallAbandonRate
                              		,	IFNULL(v_CallsTransferRate,0)	 										AS CallsTransferRate       
                              		,	IFNULL(v_AverageWrapUpTime,0) 											AS AverageWrapUpTime
                              		,	IFNULL(v_Averageholddurationtime,0) 									AS Averageholddurationtime
                              		,	IFNULL(v_AverageCallsPerMinute,0) 										AS AverageCallsPerMinute
                              		,	IFNULL(v_unresolved,0)													AS unresolved
                              		,	IFNULL(v_agent_answered_call,0)											AS agent_answered_call
                              		,	IFNULL(v_Resolved,0)													AS Resolved
                              		,	IFNULL(v_Missed,0)														AS Missed
                              		,	IFNULL(v_QueuedCustomers,0)												AS QueuedCustomers
                              		,	ROUND(IFNULL((v_InteractionWithin30Secs/v_TotalInboundCalls),0) * 100)	AS servicelevel
                                    ,	CASE WHEN ROUND(IFNULL((v_InteractionWithin30Secs/v_TotalInboundCalls),0) * 100) > 100 THEN 100 ELSE ROUND(IFNULL((v_InteractionWithin30Secs/v_TotalInboundCalls),0) * 100) END	AS servicelevel
                                    ,   IFNULL(v_isOutboundCampaign, 0)											AS isOutboundCampaign;
                                    
                         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_call_piechart_feautre_details1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_call_piechart_feautre_details1`(
    	startTmpstmp bigint, 
    	endTmpstmp bigint, 
    	Timezone varchar(55), 
    	domainId int,
    	ext int 
    )
sp_return: BEGIN
     
    		DECLARE v_TotalCalls				INT;		DECLARE	v_TotalInboundCalls			INT;		DECLARE v_OutboundCalls 			INT;		DECLARE v_TotalCallback 			INT;
    		DECLARE v_TotalVoicemail 			INT;        DECLARE v_CostPerCall  				INT;		DECLARE v_CallAbandonRate 			INT;		DECLARE v_CallsTransferRate 		INT;             		
    		DECLARE v_AverageWrapUpTime 		INT;		DECLARE v_Averageholddurationtime 	INT;		DECLARE v_AverageCallsPerMinute 	INT;		DECLARE v_unresolved				INT;
    		DECLARE v_agent_answered_call		INT;		DECLARE v_Resolved					INT;    	DECLARE v_startTmpstmp				BIGINT;		DECLARE v_endTmpstmp				BIGINT;
    		DECLARE v_InteractionWithin30Secs	INT;    	DECLARE v_Missed					INT;   		DECLARE v_QueuedCustomers			INT;		DECLARE v_Total_Answered_Sessions	INT;
    
    		SET v_startTmpstmp	= IF(startTmpstmp=0,1,startTmpstmp);
    		SET v_endTmpstmp 	= IF(endTmpstmp=0, UNIX_TIMESTAMP(NOW()) * 1000,endTmpstmp); 
            
   		DROP temporary TABLE IF EXISTS tt_temp_CallHistory;
   		CREATE TEMPORARY TABLE tt_temp_CallHistory 
   		select 	clh.CallHistoryId,clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber, clh.callFlowSourceId, clh.companyId, clh.domainId, clh.dispositionId, clh.UMNStatus, clh.IsInBound, clh.dialDuration, 
   				clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, clh.afterCallWorkTime, clh.recordingTypeId, clh.Istransferred, clh.transferredTypeId, clh.markAsRead, 
   				clh.CustomerId, clh.voicemailUrl, clh.ticketId, clh.callDuration, clh.summary, clh.subject,clh.createdAt, clh.updatedAt, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, cld.AgentSkillId, cld.IsBot, cld.BotId, cld.RecordingUrl, 
   				cld.transferredTime, cld.recordingDuration, cld.QueueId, clm.Message,'Call' as channelType,ds.dispositionName,ds.colorCode as dispositionColorCode,tu.ext as UserExt
   		from tb_CallHistory 			clh
   		join tb_CallDurationHistory 	cld on clh.CallHistoryId 	= cld.CallHistoryId
   		join tb_CallMessage				clm on clh.CallHistoryId 	= clm.CallHistoryId
   		left join disposition_status	ds on ds.did				= clh.dispositionId and clh.domainId = ds.domainId 
   		left join tb_User				tu on tu.UserID 			= clh.AssignedTo and clh.domainId = tu.domainId  
   		where clh.domainId = domainId 
   		and clh.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp
   		and (tu.ext = ext or ifnull(ext,0)=0);
   		
           
   		select 	 COUNT(CASE WHEN IFNULL(a.callDuration,0) > 0 THEN 1 ELSE 0 END)
   				,COUNT(CASE WHEN a.dispositionId is null THEN 1 ELSE 0 END)
   				,COUNT(CASE WHEN a.dispositionName in ('Closed','Resolved') THEN 1 ELSE 0 END)
   				,COUNT(CASE WHEN a.dispositionName in ('Missed') THEN 1 ELSE 0 END)
   				,SUM(CASE WHEN a.IsInBound = 1 then 1 ELSE 0 END)
   				,COUNT(CASE WHEN a.dialDuration BETWEEN 1 AND 30000 AND a.dialDuration IS NOT NULL THEN 1 ELSE 0 END) 
                   ,COUNT(CASE WHEN a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END)
                   ,COUNT(CASE WHEN IsInBound = 1 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                   ,COUNT(CASE WHEN IsInBound = 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                   ,0,0,0
                   ,COUNT(CASE WHEN IsInBound = 1 AND dispositionName = 'abandoned' AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                   ,COUNT(CASE WHEN IsInBound = 1 AND a.Istransferred = 1 AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                   ,SUM(case when a.afterCallWorkTime is not null and a.afterCallWorkTime <> 0 and a.StartTime is not null then a.afterCallWorkTime/1000 else 0 end)
                   ,COUNT(CASE WHEN ifnull(a.StartTime,0) AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                   ,SUM(CASE WHEN a.AgentHoldDuration <> 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN ifnull(a.AgentHoldDuration/1000,0) ELSE 0 END)
                   ,SUM(CASE WHEN a.callDuration <> 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN ifnull(a.callDuration/1000,0) ELSE 0 END)
   		into 	v_agent_answered_call, 
   				v_unresolved, 
   				v_Resolved, 
   				v_Missed, 
   				v_TotalInboundCalls,
   				v_InteractionWithin30Secs
				,v_TotalCalls
				,v_TotalInboundCalls
				,v_OutboundCalls
				,v_TotalCallback,v_TotalVoicemail,v_CostPerCall
				,v_CallAbandonRate
				,v_CallsTransferRate
				,v_AverageWrapUpTime
				,v_Total_Answered_Sessions
				,v_Averageholddurationtime
				,v_AverageCallsPerMinute
   		from tt_temp_CallHistory a;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    
          
          
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
    	FROM 	queueWeighTime QWT
    	WHERE 	QWT.domainId = domainId;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       if v_TotalInboundCalls =  0 		then set v_TotalInboundCalls = 1; end if;
       if v_Total_Answered_Sessions =  0 	then set v_Total_Answered_Sessions = 1; end if;
       if v_TotalCalls =  0 				then set v_TotalCalls = 1; end if;
   
   	set v_CallAbandonRate = v_CallAbandonRate/v_TotalInboundCalls*100;
       set v_CallsTransferRate = v_CallsTransferRate/v_TotalInboundCalls*100;
   	set v_AverageWrapUpTime = v_AverageWrapUpTime/v_Total_Answered_Sessions*100;
       set v_Averageholddurationtime = v_Averageholddurationtime/v_TotalCalls;
       set v_AverageCallsPerMinute = v_AverageCallsPerMinute/v_TotalCalls;
                        
      	SELECT  IFNULL(v_TotalCalls,0)									AS TotalCalls
      		,	IFNULL(v_TotalInboundCalls,0)							AS InboundCalls
      		,	IFNULL(v_OutboundCalls,0) 								AS OutboundCalls
      		,	IFNULL(v_TotalCallback,0) 								AS TotalCallback
      		,	IFNULL(v_TotalVoicemail,0) 								AS TotalVoicemail	
      		,	IFNULL(v_CostPerCall,0)  								AS CostPerCall
      		,	CONCAT(IFNULL(v_CallAbandonRate,0)) 				AS CallAbandonRate
      		,	CONCAT(IFNULL(v_CallsTransferRate,0)) 				AS CallsTransferRate       
      		,	IFNULL(v_AverageWrapUpTime,0) 							AS AverageWrapUpTime
      		,	IFNULL(v_Averageholddurationtime,0) 					AS Averageholddurationtime
      		,	IFNULL(v_AverageCallsPerMinute,0) 						AS AverageCallsPerMinute
      		,	v_unresolved											AS unresolved
      		,	v_agent_answered_call 									AS agent_answered_call
      		,	v_Resolved												AS Resolved
      		,	v_Missed												AS Missed
      		,	v_QueuedCustomers										AS QueuedCustomers
      		,	(v_InteractionWithin30Secs/v_TotalInboundCalls) * 100 	AS servicelevel;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_call_piechart_feautre_details_testing` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
