/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_call_piechart_feautre_details_testing`(
    	startTmpstmp bigint, 
    	endTmpstmp bigint, 
    	Timezone varchar(55), 
    	domainId int,
    	ext int 
    )
sp_return: BEGIN
   	DECLARE v_AgentId			INT;
     DECLARE v_roleid			INT;
     DECLARE v_QueuedCustomers	INT;
  
 	SELECT 	UserID , roleid   
 	INTO	v_AgentId, v_roleid 		
 	FROM 	tb_User
 	WHERE 	domainId 	= domainId
 	AND 	ext			= ext
    and isActive=1 
    limit 1;
     
  	DROP TEMPORARY TABLE IF EXISTS temp_CallHistory;
 	CREATE TEMPORARY TABLE temp_CallHistory
     (	dispositionId				INT	 
 		,dispositionName			VARCHAR(100)	
 		,IsInBound					TINYINT
 		,assignedTo					BIGINT        	        
         ,AssignedDate				DATETIME
         ,repliedDate				DATETIME
         ,Istransferred				TINYINT
         ,dialDuration				BIGINT       
         ,IsMissedcall				TINYINT
         ,IsCallBack					TINYINT        
     );
     
     IF v_roleid = 6 
     THEN    
 		INSERT INTO temp_CallHistory
         (	dispositionId		            
             ,IsInBound			
             ,assignedTo			
             ,AssignedDate		            
             ,Istransferred
             ,IsCallBack
             ,dialDuration
             ,IsMissedcall            
         )
 		SELECT 	EH.dispositionId			 
 			 ,	EH.IsInBound     
 			 ,	EH.assignedTo			 
 			 ,	from_unixtime(EH.AssignedOn/1000) 						AS AssignedDate			 
 			 ,	EH.Istransferred  
              ,	CASE WHEN EH.callBack IS NOT NULL THEN 1 ELSE 0 END 	AS IsCallBack
              ,  dialDuration/1000										AS dialDuration
              ,	CASE WHEN EH.UMNStatus = 3 THEN 1 ELSE 0 END 			AS IsMissedcall
 		FROM 	tb_CallHistory 			EH
         JOIN 	tb_CallDurationHistory 	EDH	ON 	EDH.SMSHistoryId 	= EH.SMSHistoryId
 											AND EDH.AgentId			= v_AgentId
 		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
 		AND 	EH.domainId 		= domainId;   
 	ELSE
 		INSERT INTO temp_CallHistory
 		(	dispositionId		            
 			,IsInBound			
 			,assignedTo			
 			,AssignedDate					
 			,Istransferred
             ,IsCallBack
             ,dialDuration
             ,IsMissedcall
 		)
 		SELECT 	EH.dispositionId
 			,	EH.IsInBound     
 			 ,	EH.assignedTo			 
 			 ,	from_unixtime(EH.AssignedOn/1000) 						AS AssignedDate			 
 			 ,	EH.Istransferred         
              ,	CASE WHEN EH.callBack IS NOT NULL THEN 1 ELSE 0 END 	AS IsCallBack
              ,  dialDuration/1000										AS dialDuration
              ,	CASE WHEN EH.UMNStatus = 3 THEN 1 ELSE 0 END 			AS IsMissedcall
 		FROM 	tb_CallHistory EH
 		WHERE 	EH.sessionStartTime BETWEEN startTmpstmp and endTmpstmp 	 	
 		AND 	EH.domainId 		= domainId;       
 	END IF;	   
    
     
     UPDATE 		temp_CallHistory	EH 
     LEFT JOIN 	disposition_status 	DS	ON 	EH.dispositionId 	= DS.did
 										AND DS.domainId			= domainId
     SET 		EH.dispositionName	= DS.dispositionName;    
         
 	
    	SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
    	FROM 	queueWeighTime QWT
    	WHERE 	QWT.domainId = domainId;        
         
  	DROP TEMPORARY TABLE IF EXISTS temp_CallDetail;
  	CREATE TEMPORARY TABLE temp_CallDetail
  	SELECT 	IsInBound																InBound		
  		,	CASE WHEN IsInBound = 1 THEN 0 ELSE 1 END								Outbound	                
         ,	CASE WHEN dispositionName IN ('Closed','Resolved') THEN 1 ELSE 0 END  	Resolved
  		,	CASE WHEN dispositionName IN ('Closed','Resolved') THEN 0 ELSE 1 END	UnResolved
         ,	CASE WHEN dispositionName = 'Abandoned' THEN 1 ELSE 0 END				Abandoned
 		,	Istransferred															Transferred
         ,	IsCallBack																CallBack
         ,	IsMissedcall															Missedcall
         ,	CASE WHEN dialDuration < 30 THEN 1 ELSE 0 END 							InteractionWithin30Secs
 
 
 
 
  	FROM 	temp_CallHistory;    
     
 	SELECT 	COUNT(1)					TotalCalls     
 		,	IFNULL(SUM(InBound),0)		InboundCalls
 		,	IFNULL(SUM(Outbound),0)		OutboundCalls
 		,	IFNULL(SUM(InteractionWithin30Secs),0) 	as servicelevel 
         ,	IFNULL(v_QueuedCustomers,0)									as QueuedCustomers        
 		,	IFNULL(SUM(Resolved),0)		Resolved
 		,	IFNULL(SUM(UnResolved),0)	unresolved
         ,	IFNULL(SUM(Abandoned),0)	CallAbandonRate
 		,	IFNULL(SUM(Transferred),0)	CallsTransferRate  
         ,	IFNULL(SUM(CallBack),0)		TotalCallback
         ,	IFNULL(SUM(Missedcall),0)	Missed
 
 	FROM 	temp_CallDetail
    GROUP BY v_QueuedCustomers ;               
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_call_piechart_feautre_details_v2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dashboard_call_piechart_feautre_details_v2`(
 	startTmpstmp bigint, 
 	endTmpstmp bigint, 
 	Timezone varchar(55), 
 	domainId int,
 	ext int 
 )
sp_return: BEGIN
  
 		DECLARE v_TotalCalls				INT;		DECLARE	v_TotalInboundCalls			INT;		DECLARE v_OutboundCalls 			INT;		DECLARE v_TotalCallback 			INT;
 		DECLARE v_TotalVoicemail 			INT;        DECLARE v_CostPerCall  				INT;		DECLARE v_CallAbandonRate 			INT;		DECLARE v_CallsTransferRate 		INT;             		
 		DECLARE v_AverageWrapUpTime 		INT;		DECLARE v_Averageholddurationtime 	INT;		DECLARE v_AverageCallsPerMinute 	INT;		DECLARE v_unresolved				INT;
 		DECLARE v_agent_answered_call		INT;		DECLARE v_Resolved					INT;    	DECLARE v_startTmpstmp				BIGINT;		DECLARE v_endTmpstmp				BIGINT;
 		DECLARE v_InteractionWithin30Secs	INT;    	DECLARE v_Missed					INT;   		DECLARE v_QueuedCustomers			INT;		DECLARE v_Total_Answered_Sessions	INT;
 
 		SET v_startTmpstmp	= IF(startTmpstmp=0,1,startTmpstmp);
 		SET v_endTmpstmp 	= IF(endTmpstmp=0, UNIX_TIMESTAMP(NOW()) * 1000,endTmpstmp); 
         
		DROP temporary TABLE IF EXISTS tt_temp_CallHistory;
		CREATE TEMPORARY TABLE tt_temp_CallHistory 
		select 	clh.CallHistoryId,clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber, clh.callFlowSourceId, clh.companyId, clh.domainId, clh.dispositionId, clh.UMNStatus, clh.IsInBound, clh.dialDuration, 
				clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, clh.afterCallWorkTime, clh.recordingTypeId, clh.Istransferred, clh.transferredTypeId, clh.markAsRead, 
				clh.CustomerId, clh.voicemailUrl, clh.ticketId, clh.callDuration, clh.summary, clh.subject,clh.createdAt, clh.updatedAt, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, cld.AgentSkillId, cld.IsBot, cld.BotId, cld.RecordingUrl, 
				cld.transferredTime, cld.recordingDuration, cld.QueueId, clm.Message,'Call' as channelType,ds.dispositionName,ds.colorCode as dispositionColorCode
		from tb_CallHistory 			clh
		join tb_CallDurationHistory 	cld on clh.CallHistoryId 	= cld.CallHistoryId
		join tb_CallMessage				clm on clh.CallHistoryId 	= clm.CallHistoryId
		left join disposition_status	ds on ds.did				= clh.dispositionId and clh.domainId = ds.domainId 
		left join tb_User				tu on tu.UserID 			= clh.AssignedTo and clh.domainId = tu.domainId  
		where clh.domainId = domainId 
		and clh.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp
		and (clh.assignedTo = ext or ifnull(ext,0)=0);
		
        
		select 	 COUNT(CASE WHEN IFNULL(a.callDuration,0) > 0 THEN 1 ELSE 0 END)
				,COUNT(CASE WHEN a.dispositionId is null THEN 1 ELSE 0 END)
				,COUNT(CASE WHEN a.dispositionName in ('Closed','Resolved') THEN 1 ELSE 0 END)
				,COUNT(CASE WHEN a.dispositionName in ('Missed') THEN 1 ELSE 0 END)
				,SUM(CASE WHEN a.IsInBound = 1 then 1 ELSE 0 END)
				,COUNT(CASE WHEN a.dialDuration BETWEEN 1 AND 30000 AND a.dialDuration IS NOT NULL THEN 1 ELSE 0 END) 
                ,COUNT(CASE WHEN a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END)
                ,COUNT(CASE WHEN IsInBound = 1 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                ,COUNT(CASE WHEN IsInBound = 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                ,0,0,0
                ,COUNT(CASE WHEN IsInBound = 1 AND dispositionName = 'abandoned' AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                ,COUNT(CASE WHEN IsInBound = 1 AND a.Istransferred = 1 AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                ,SUM(case when a.afterCallWorkTime is not null and a.afterCallWorkTime <> 0 and a.StartTime is not null then a.afterCallWorkTime/1000 else 0 end)
                ,COUNT(CASE WHEN ifnull(a.StartTime,0) AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
                ,SUM(CASE WHEN a.AgentHoldDuration <> 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN ifnull(a.AgentHoldDuration/1000,0) ELSE 0 END)
                ,SUM(CASE WHEN a.callDuration <> 0 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.assignedTo = ext or ifnull(ext,0)=0) THEN ifnull(a.callDuration/1000,0) ELSE 0 END)
		into 	v_agent_answered_call, 
				v_unresolved, 
				v_Resolved, 
				v_Missed, 
				v_TotalInboundCalls,
				v_InteractionWithin30Secs
                ,v_TotalCalls
                ,v_TotalInboundCalls
                ,v_OutboundCalls
                ,v_TotalCallback,v_TotalVoicemail,v_CostPerCall
                ,v_CallAbandonRate
                ,v_CallsTransferRate
                ,v_AverageWrapUpTime
                ,v_Total_Answered_Sessions
                ,v_Averageholddurationtime
                ,v_AverageCallsPerMinute
		from tt_temp_CallHistory a;
         
 
       
 	SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
 	FROM 	queueWeighTime QWT
 	WHERE 	QWT.domainId = domainId;
    
    if v_TotalInboundCalls =  0 		then set v_TotalInboundCalls = 1; end if;
    if v_Total_Answered_Sessions =  0 	then set v_Total_Answered_Sessions = 1; end if;
    if v_TotalCalls =  0 				then set v_TotalCalls = 1; end if;

	set v_CallAbandonRate = v_CallAbandonRate/v_TotalInboundCalls*100;
    set v_CallsTransferRate = v_CallsTransferRate/v_TotalInboundCalls*100;
	set v_AverageWrapUpTime = v_AverageWrapUpTime/v_Total_Answered_Sessions*100;
    set v_Averageholddurationtime = v_Averageholddurationtime/v_TotalCalls;
    set v_AverageCallsPerMinute = v_AverageCallsPerMinute/v_TotalCalls;
                     
   	SELECT  IFNULL(v_TotalCalls,0)									AS TotalCalls
   		,	IFNULL(v_TotalInboundCalls,0)							AS InboundCalls
   		,	IFNULL(v_OutboundCalls,0) 								AS OutboundCalls
   		,	IFNULL(v_TotalCallback,0) 								AS TotalCallback
   		,	IFNULL(v_TotalVoicemail,0) 								AS TotalVoicemail	
   		,	IFNULL(v_CostPerCall,0)  								AS CostPerCall
   		,	CONCAT(IFNULL(v_CallAbandonRate,0),'%') 				AS CallAbandonRate
   		,	CONCAT(IFNULL(v_CallsTransferRate,0),'%') 				AS CallsTransferRate       
   		,	IFNULL(v_AverageWrapUpTime,0) 							AS AverageWrapUpTime
   		,	IFNULL(v_Averageholddurationtime,0) 					AS Averageholddurationtime
   		,	IFNULL(v_AverageCallsPerMinute,0) 						AS AverageCallsPerMinute
   		,	v_unresolved											AS unresolved
   		,	v_agent_answered_call 									AS agent_answered_call
   		,	v_Resolved												AS Resolved
   		,	v_Missed												AS Missed
   		,	v_QueuedCustomers										AS QueuedCustomers
   		,	(v_InteractionWithin30Secs/v_TotalInboundCalls) * 100 	AS servicelevel;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_chat_piechart_feautre_details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_chat_piechart_feautre_details`(startTmpstmp bigint, endTmpstmp bigint, Timezone varchar(55), domainId int,ext int)
begin 
     	DECLARE v_Total						INT;		DECLARE v_Inbound				INT;		DECLARE v_Service_level			INT;		DECLARE v_Queued_customers		INT;		DECLARE v_Resolved				INT;
     	DECLARE v_Unresolved				INT;		DECLARE v_Abandoned				INT;		DECLARE v_Transferred			INT;		DECLARE v_Callback_requested	INT;		DECLARE v_Missed				INT;
		DECLARE v_InteractionWithin30Secs 	INT;		DECLARE v_startTmpstmp			BIGINT;		DECLARE v_endTmpstmp			BIGINT;		DECLARE v_QueuedCustomers		INT;
          
     	SET v_startTmpstmp	= IF(startTmpstmp=0,1,startTmpstmp);
     	SET v_endTmpstmp 	= IF(endTmpstmp=0, UNIX_TIMESTAMP(NOW()) * 1000,endTmpstmp);
         
   	IF IFNULL(startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = startTmpstmp;  END IF; 	
	IF IFNULL(endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = endTmpstmp; END IF;  	      
     
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_ChatHistory;
   	CREATE TEMPORARY TABLE tt_temp_ChatHistory	
   	SELECT 	cth.sessionStartTime
			,cth.IsInBound

			,ctd.answeredDuration
			,ctd.Istransferred            
			,ds.dispositionName
			,tu.ext 			as UserExt
   	from tb_ChatHistory 				cth
	left join tb_ChatDurationHistory 	ctd on cth.ChatHistoryId 	= ctd.ChatHistoryId	
   	left join disposition_status		ds on ds.did				= ctd.dispositionId and cth.domainId = ds.domainId 
   	left join tb_User					tu on tu.UserID 			= cth.AssignedTo 	and cth.domainId = tu.domainId  
   	where cth.domainId = domainId 
   	and cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
     	
         
   	SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
   	FROM 	queueWeighTime QWT
   	WHERE 	QWT.domainId = domainId;
         
     SELECT SUM(CASE WHEN a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END)      		
  		,	SUM(CASE WHEN IsInBound = 1 AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN a.dispositionName = 'Resolved' THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN a.dispositionName = 'Unresolved' THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN a.IsInBound = 1 AND a.dispositionName = 'abandoned' AND a.sessionStartTime <> 0 AND a.sessionStartTime IS NOT NULL AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN a.IsInBound = 1 AND a.Istransferred = 1 AND (a.UserExt = ext or ifnull(ext,0)=0) THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN a.answeredDuration BETWEEN 1 AND 30000 THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN a.dispositionName ='missed' THEN 1 ELSE 0 END)
  		,	0        
     	INTO 	v_Total				
     			,v_Inbound
     			,v_Resolved
     			,v_Unresolved
     			,v_Abandoned
     			,v_Transferred
     			,v_InteractionWithin30Secs
     			,v_Missed
				,v_Callback_requested                
   	FROM 	tt_temp_ChatHistory a ;
         
      select  IFNULL(v_Total,0)					AS Total
   		,	ifnull(v_Inbound,0)					AS Inbound
   		,	ifnull(v_Resolved,0)				AS Resolved
   		,	ifnull(v_Unresolved,0)				AS Unresolved
   		,	ifnull(v_Abandoned,0)				AS Abandoned
   		,	ifnull(v_Transferred,0)				AS Transferred
   		,	ifnull(v_InteractionWithin30Secs,0) AS servicelevel
   		,	ifnull(v_Missed,0)					AS Missed
   		,	ifnull(v_QueuedCustomers,0)			AS QueuedCustomers
   		,	ifnull(v_Callback_requested,0)		AS Callback_requested;
     
     		 
             
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
