/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dashboard_Email_piechart_feautre_details`(
                      p_startTmpstmp 	BIGINT,
                      p_endTmpstmp 	BIGINT,
                      p_domainId 		INT,  
                      p_timezone		VARCHAR(30),
                      p_ext 			INT
                      )
BEGIN
               	DECLARE v_AgentId			INT;
          		DECLARE v_roleid			INT;
				DECLARE v_emailThreshold	INT;                          
                   
			   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			   SELECT UserID , roleid   
			   INTO	 v_AgentId, v_roleid 		
			   FROM  tb_User
			   WHERE domainId 	= p_domainId
			   AND 	ext			= p_ext;
			   
			   SELECT emailThreshold
			   INTO 	v_emailThreshold
			   FROM 	email_config 
			   WHERE 	domainId = p_domainId
			   ORDER BY primaryEmail DESC LIMIT 1;
			   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

				DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory;
               	CREATE TEMPORARY TABLE temp_EmailHistory
          		(	     dispositionId		    		INT	 
						,dispositionName				VARCHAR(100)	
						,IsInBound						TINYINT
						,assignedTo						BIGINT        	        
						,AssignedDate					DATETIME
						,repliedDate					DATETIME
						,Istransferred					TINYINT
						,replyDuration					INT  
						,emailThreshold					INT
						,IsSessionClosed   			    INT
                        ,Outbound          				TINYINT   
                        ,isThresholdTimeExceeded		TINYINT
                        ,isOpened						TINYINT
                        ,isBot							TINYINT
                  );

                   IF v_roleid = 6 
                   THEN    
               		INSERT INTO temp_EmailHistory
                       (   dispositionId		            
          				,IsInBound			
          				,assignedTo			
          				,AssignedDate		
          				,repliedDate		
          				,Istransferred                
          				,emailThreshold
						,IsSessionClosed  
   					    ,Outbound
                        ,isThresholdTimeExceeded
                        ,isOpened
                        ,isBot
                       )
               		SELECT 	EH.dispositionId			                		
						 ,	CASE WHEN EH.IsInBound = 1 THEN 1 ELSE 0 END	            AS 	IsInBound                        
               			 ,	EH.assignedTo			 
               			 ,	FROM_UNIXTIME(IFNULL(EH.AssignedOn,SessionStartTime)/1000)     AssignedDate
               			 ,	EH.repliedDate   
               		 	 ,	EH.Istransferred   
   						,	EC.emailThreshold
   						,  	EH.IsSessionClosed  
   						,  	CASE WHEN EH.IsInBound = 0 THEN 1 ELSE 0 END	                    as Outbound  
                        
                        , 	CASE WHEN TIMESTAMPDIFF(MINUTE, EH.createdAt, NOW()) >= EC.emailThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded
                        ,	EH.isOpened
                        ,	EDH.isBot
               		FROM 	tb_EmailHistory 		EH
                    JOIN 	tb_EmailDurationHistory EDH	ON 	EDH.EmailHistoryId 	= EH.EmailHistoryId
               											AND EDH.AgentId			= v_AgentId
          			LEFT JOIN email_config 			EC	ON 	EC.domainId			= EH.domainId
          												AND	EC.emailAddress		= EH.ToEmail	    
               		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
               		AND 	EH.domainId 		= p_domainId;
   
               	ELSE
               		INSERT INTO temp_EmailHistory
               		(	dispositionId		            
               			,IsInBound			
               			,assignedTo			
               			,AssignedDate		
               			,repliedDate		
               			,Istransferred
   						,emailThreshold
 						,IsSessionClosed
 						,Outbound           
 						,isThresholdTimeExceeded
                        ,isOpened
                        ,isBot
               		)
               		SELECT 	EH.dispositionId               		
						,	CASE WHEN EH.IsInBound = 1 AND IFNULL(EH.Istransferred,0) <> 1 THEN 1 ELSE 0 END	as IsInBound                    
						,	EH.assignedTo			 
						,	from_unixtime(IFNULL(EH.AssignedOn,SessionStartTime)/1000)          AssignedDate
						,	EH.repliedDate         
						,	EH.Istransferred 
						,	EC.emailThreshold
						,  	EH.IsSessionClosed
						,	CASE WHEN EH.IsInBound = 0 THEN 1 ELSE 0 END	                    	AS Outbound  
						
                        ,	CASE WHEN TIMESTAMPDIFF(MINUTE, EH.createdAt, NOW()) >= EC.emailThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded
						,	EH.isOpened
						,	EDH.isBot
               		FROM 	tb_EmailHistory 		EH
                    JOIN 	tb_EmailDurationHistory EDH	ON 	EDH.EmailHistoryId 	= EH.EmailHistoryId
					LEFT JOIN email_config 			EC	ON 	EC.domainId			= EH.domainId
														AND	EC.emailAddress		= EH.ToEmail	
               		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
               		AND 	EH.domainId 		= p_domainId;
       	
               	END IF;		    
                   
          		UPDATE 	temp_EmailHistory	EH 
          		LEFT JOIN disposition_status 	DS	ON 	EH.dispositionId 	= DS.did
          										AND DS.domainId			= p_domainId
          		SET 		EH.dispositionName	= DS.dispositionName
                     ,		EH.replyDuration	= TIMESTAMPDIFF(HOUR, AssignedDate, repliedDate);
                  
			DROP TEMPORARY TABLE IF EXISTS tt_EmailDetail;
        	CREATE TEMPORARY TABLE tt_EmailDetail
        	SELECT 	IsInBound																			InBound		
        		,	CASE WHEN IsInBound = 1 THEN 0 ELSE 1 END											Outbound		
        		,	CASE WHEN dispositionName = 'UnResolved' THEN 1 ELSE 0 END							UnResolved
				,	Istransferred																		Transferred	
        		,	CASE WHEN dispositionName = 'Resolved' THEN 1 ELSE 0 END  							Resolved
				,	0 																					Abandoned        

				,	CASE WHEN (assignedTo IS NULL and dispositionId IS NULL and isBot = 0) THEN 1 ELSE 0 END AS UnAssigned	
				,	CASE WHEN assignedTo IS NOT NULL THEN 1 ELSE 0 END 									Assigned	
				,   CASE WHEN isThresholdTimeExceeded = 1 and dispositionName IS NULL THEN 1 ELSE 0 END OverDue    		
				,	0																					Dsicarded        
				,	case when isOpened =1 and dispositionName IS NULL THEN 1 ELSE 0 END     			Opened
 				,	CASE WHEN (replyDuration < emailThreshold AND IsInBound = 1 AND dispositionName <> 'Transferred') THEN 1 ELSE 0 END 		InteractionWithin30Secs                
			FROM 	temp_EmailHistory;        
  
       	SELECT 	COUNT(1)						Total     
       		,	IFNULL(SUM(InBound),0)			InBound
       		,	IFNULL(SUM(Outbound),0)			Outbound
       		,	IFNULL(SUM(InteractionWithin30Secs)/SUM(InBound+Outbound)*100,0) ServiceLevel 

       		,	IFNULL(SUM(UnAssigned),0) 		UnAssigned
   			,	IFNULL(SUM(Assigned),0)			Assigned
       		,	IFNULL(SUM(Abandoned),0)		Abandoned
       		,	IFNULL(SUM(Resolved),0)			Resolved
       		,	IFNULL(SUM(UnResolved),0)		UnResolved
       		,	IFNULL(SUM(Transferred),0)		Transferred
       		,	IFNULL(SUM(OverDue),0)			OverDue
       		,	IFNULL(SUM(Dsicarded),0)    	Dsicarded  
   			,	IFNULL(SUM(Opened),0)    		Opened 
   			,	0								Suspended            
       	FROM 	tt_EmailDetail;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_piechart_agent_status_details` */;
