/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_piechart_agent_status_details`(
  p_startTmpstmp 	BIGINT,
  p_endTmpstmp		BIGINT,
  p_Timezone       VARCHAR(55),
  p_domainId       INT,
  p_ext            INT)
BEGIN
   	DECLARE v_startTmpstmp 	BIGINT;
	DECLARE v_endTmpstmp 	BIGINT;
 
	IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +31 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
	select 	a.stid, a.ext, a.domainId, a.createdAt, a.updatedAt, a.startTimestamp, a.endTimestamp, a.timerStatusId, a.stateDuration 
    FROM 	state_timer a
	where timestamp  BETWEEN p_startTmpstmp and p_endTmpstmp 
	AND a.domainId = p_domainId AND (a.ext = p_ext OR ifnull(p_ext,0)=0)   ;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_piechart_agent_status_details1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_piechart_agent_status_details1`(
  p_startTmpstmp 	BIGINT,
  p_endTmpstmp		BIGINT,
  p_Timezone       VARCHAR(55),
  p_domainId       INT,
  p_agentId     	TEXT,
  p_Limit         INT,
p_Offset        INT)
BEGIN
      	    DECLARE v_offset 		INT;
        	DECLARE v_Total_Count 	INT;
        	DECLARE v_startTmpstmp 	BIGINT;
        	DECLARE v_endTmpstmp 	BIGINT;
 
IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +31 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						

    DROP TEMPORARY TABLE IF EXISTS temp_agentId; 	CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100)); 
         
        CALL split(p_agentId,','); 	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
         
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
         CREATE TEMPORARY TABLE temp_AllagentId 
         SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
		DROP TEMPORARY TABLE IF EXISTS temp_AvailableStateStatus;
       	CREATE TEMPORARY TABLE temp_AvailableStateStatus 
 		(    domainId 				INT
 			,AgentStatus 		VARCHAR(100)
 			,AgentCategory		TINYINT
 		); 
       	INSERT INTO temp_AvailableStateStatus 
       	SELECT 	domainId 		    domainId
       		,	statusName			AgentStatus
 			,CASE
 				WHEN statusName = 'Ready'         THEN 1
 				WHEN statusName = 'Not Ready'     THEN 2
 				WHEN statusName = 'Away'          THEN 3
 				WHEN statusName = 'Transfer Only' THEN 4
 				WHEN statusName = 'Busy'          THEN 5
                when statusName = 'Offline'       THEN 6
 				ELSE 7
 			END AS AgentCategory
       	FROM 	agent_status
       	WHERE 	domainId	= p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
        DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;  
       	CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS    
 		SELECT LSH.createdAt 	as SessionDate
         
         ,LSH.logInTimestamp		as LoginTime
         ,LSH.logOutTimestamp	    as LogOut
         ,ST.statusName
          , (CASE when AgentCategory = 1  THEN 1 ELSE 0 END)             AS 'Ready'         
         , (CASE when AgentCategory = 2 THEN 1 ELSE 0 END)               AS 'NotReady'
         , (CASE when AgentCategory = 3 THEN 1 ELSE 0 END)               AS 'Away'          
         , (CASE when AgentCategory = 4 THEN 1 ELSE 0 END)               AS 'TransferOnly' 
         , (CASE when AgentCategory = 5 THEN 1 ELSE 0 END)               AS 'Busy' 
         , (CASE when AgentCategory = 6 THEN 1 ELSE 0 END)               AS 'Offline' 
         FROM logInSessionHistory 		LSH 
         LEFT JOIN temp_AvailableStateStatus	AV	ON LSH.domainId = AV.domainId
         LEFT JOIN tb_User 				U	ON U.domainId  = LSH.domainId AND U.ext  = LSH.ext
         JOIN  agent_status				ST	ON ST.domainId = LSH.domainId 
       	WHERE 	LSH.domainId 			= p_domainId 		
       	AND 	LSH.createdAt			BETWEEN v_startTmpstmp and v_endTmpstmp ; 

        select * from tt_temp_sessionHistory;
 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 		DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
        	CREATE TEMPORARY TABLE tt_sessionHistory_calc AS 
 		SELECT 	
 			  SH.SessionDate
 			,(SH.LogOut - SH.LoginTime)     AS LoggedinDuration
             ,SUM(NotReady)                 AS NotReady
             ,SUM(Ready) 				    AS Ready
             ,SUM(Away) 					AS Away
             ,SUM(TransferOnly) 			AS TransferOnly
             ,SUM(Busy) 					AS Busy
			,SUM('Offline')  			    AS 'Offline'
         FROM tt_temp_sessionHistory SH
 		GROUP BY SH.SessionDate,SH.LogOut,SH.LoginTime ;
         
         SELECT * from temp_AllagentId;
 		
 		SELECT 	COUNT(1) v_Total_Count
 		FROM 	tt_sessionHistory_calc a;
         
         SELECT   a.SessionDate						    as `date`
                 ,a.LoggedinDuration/1000			    as totalLoggedInDuration
                 ,LoggedinDuration
                 ,Ready
 				 ,Away
 				 ,TransferOnly
                 ,Busy
 				 ,'Offline'
                 
 		FROM 	tt_sessionHistory_calc a
 				ORDER BY a.SessionDate DESC
 				LIMIT v_offset, p_limit;               
		DROP TEMPORARY TABLE IF EXISTS temp_AvailableStateStatus;

 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dashboard_SMS_piechart_feautre_details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dashboard_SMS_piechart_feautre_details`(
                     p_startTmpstmp 		BIGINT,
                     p_endTmpstmp 		BIGINT,
                     p_domainId 			INT,  
                     p_timezone			VARCHAR(30),
                     p_ext 			    INT
                     )
BEGIN
               	DECLARE v_AgentId		INT;
           		DECLARE v_roleid		INT;
                 
                  
                  SELECT UserID , roleid   
                  INTO	v_AgentId, v_roleid 		
                  FROM 	tb_User
                  WHERE domainId 	= p_domainId
                  AND 	ext			= p_ext;
        
           		DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory;
           		CREATE TEMPORARY TABLE temp_SMSHistory
           		(	SMSHistoryId		BIGINT
					,dispositionId		INT	 
					,dispositionName	VARCHAR(100)	
					,IsInBound			TINYINT
					,assignedTo			BIGINT        	        
					,AssignedDate		DATETIME
					,repliedDate		DATETIME
					,Istransferred		TINYINT
					,replyDuration		INT 
					,smsThreshold		INT	
					,IsSessionClosed    INT
					,Outbound           TINYINT
					,isThresholdTimeExceeded		TINYINT
					,isOpened			TINYINT
					,isBot				TINYINT
                  );       
                  
                  IF v_roleid = 6 
                  THEN    
         			INSERT INTO temp_SMSHistory
         			 (	 dispositionId		            
         				 ,IsInBound			
         				 ,assignedTo			
         				 ,AssignedDate		
         				 ,repliedDate		
         				 ,Istransferred
         				 ,smsThreshold
         				 ,IsSessionClosed
                         ,Outbound
                         ,isThresholdTimeExceeded
                         ,isOpened
                         ,isBot
         			 )
              		SELECT 	EH.dispositionId			              			 
 						 ,	CASE WHEN EH.IsInBound = 1 THEN 1 ELSE 0 END	               as IsInBound
              			 ,	EH.assignedTo			 
              			 ,	from_unixtime(IFNULL(EH.AssignedOn,EH.SessionStartTime)/1000) AssignedDate
              			 ,	EH.repliedDate         
              			 ,	EH.Istransferred         
          				 ,	DP.smsThreshold
 						 , 	EH.IsSessionClosed
                         ,	CASE WHEN EH.IsInBound = 0 THEN 1 ELSE 0 END	                  as Outbound
                         
                         ,	CASE WHEN TIMESTAMPDIFF(MINUTE, EH.createdAt, NOW()) >= DP.smsThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded
                         ,	EH.isOpened
                         ,	EDH.IsBot
              		FROM 	tb_SMSHistory 			EH
         			JOIN 	tb_SMSDurationHistory 	EDH	ON 	EDH.SMSHistoryId 	= EH.SMSHistoryId
              											AND EDH.AgentId			= v_AgentId
         			LEFT JOIN did_purchase 			DP	ON 	DP.domainId 		= EH.domainId
         												AND DP.your_number		= EH.calledNumber
              		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
              		AND 	EH.domainId 		= p_domainId;   
              	ELSE
              		INSERT INTO temp_SMSHistory
              		(	dispositionId		            
						,IsInBound			
						,assignedTo			
						,AssignedDate		
						,repliedDate		
						,Istransferred
						,smsThreshold
						,IsSessionClosed
						,Outbound
						,isThresholdTimeExceeded
						,isOpened
						,isBot
              		)
              		SELECT 	EH.dispositionId             			 
						,CASE WHEN EH.IsInBound = 1 AND IFNULL(EH.Istransferred,0) <> 1 THEN 1 ELSE 0 END	as IsInBound
						,	EH.assignedTo			 
						,	FROM_UNIXTIME(IFNULL(EH.AssignedOn,EH.SessionStartTime)/1000) 		AS AssignedDate
						,	EH.repliedDate         
						,	EH.Istransferred 
						,	DP.smsThreshold
						,   EH.IsSessionClosed
						,	CASE WHEN EH.IsInBound = 0 THEN 1 ELSE 0 END	                    	AS Outbound
						
                        ,	CASE WHEN TIMESTAMPDIFF(MINUTE, EH.createdAt, NOW()) >= DP.smsThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded
						,	EH.isOpened
						,	EDH.IsBot
				FROM 	tb_SMSHistory 			EH
				JOIN 	tb_SMSDurationHistory 	EDH	ON 	EDH.SMSHistoryId 	= EH.SMSHistoryId
				LEFT JOIN did_purchase 			DP	ON 	DP.domainId 		= EH.domainId
													AND DP.your_number		= EH.calledNumber
				WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
				AND 	EH.domainId 		= p_domainId;
              	END IF;		    
            
              UPDATE 	temp_SMSHistory	EH 
              LEFT JOIN disposition_status 	DS	ON 	EH.dispositionId 	= DS.did
           										AND DS.domainId			= p_domainId
              SET 		EH.dispositionName	= DS.dispositionName
         		,		EH.replyDuration	= TIMESTAMPDIFF(HOUR, AssignedDate, repliedDate);
                  		
           	DROP TEMPORARY TABLE IF EXISTS tt_SMSDetail;
           	CREATE TEMPORARY TABLE tt_SMSDetail
           	SELECT 	
				IsInBound																														    InBound		   
				,   Outbound																															Outbound
				,	CASE WHEN dispositionName = 'UnResolved' THEN 1 ELSE 0 END																			UnResolved
				,	Istransferred																														Transferred	
				,	CASE WHEN dispositionName = 'Resolved'	THEN 1 ELSE 0 END  																			Resolved                
				,	case when isOpened = 1 and dispositionName IS NULL THEN 1 ELSE 0 END   				  												Opened
				
				,	CASE WHEN (assignedTo IS NULL and IFNULL(IsSessionClosed,0) = 0 and dispositionId IS NULL and isBot = 0) THEN 1 ELSE 0 END 			UnAssigned
				,	CASE WHEN assignedTo IS NOT NULL and IFNULL(IsSessionClosed,0) = 0 and dispositionId is null  THEN 1 ELSE 0 END 		    	    Assigned    
				,   CASE WHEN isThresholdTimeExceeded = 1 and dispositionName IS NULL THEN 1 ELSE 0 END 												OverDue 
				,	0																																	Dsicarded        
				,	CASE WHEN replyDuration < smsThreshold and dispositionName <> 'Transferred' THEN 1 ELSE 0 END 																			InteractionWithin30Secs
           	                   
           	FROM 	temp_SMSHistory;        
             
         	SELECT 	
                    SUM(InBound+Outbound)		Total  
           		,	IFNULL(SUM(InBound),0)		InBound
           		,	IFNULL(SUM(Outbound),0)		Outbound
           		,	IFNULL(SUM(InteractionWithin30Secs)/SUM(InBound+Outbound) * 100,0) ServiceLevel 
           		,	IFNULL(SUM(UnAssigned),0) 	UnAssigned
           		,	IFNULL(SUM(Assigned	),0) 	Assigned	
           		,	IFNULL(SUM(Opened),0)		Opened
           		,	IFNULL(SUM(Resolved),0)		Resolved
           		,	IFNULL(SUM(UnResolved),0)	UnResolved
           		,	IFNULL(SUM(Transferred),0)	Transferred
           		,	IFNULL(SUM(OverDue),0)		OverDue
           		,	IFNULL(SUM(Dsicarded),0)    Dsicarded  
         	FROM 	tt_SMSDetail;
               
              
               END ;;
DELIMITER ;
