/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dashboard_SocialMedia_piechart_feautre_details`(
              p_startTmpstmp 		bigint,
              p_endTmpstmp 			bigint,
              p_domainId 			int,  
              p_timezone			VARCHAR(30),
              p_ext 				int,
              p_channelType			varchar(100)
              )
BEGIN
   	DECLARE v_AgentId			INT;
   	DECLARE v_roleid			INT;
   	DECLARE v_QueuedCustomers	INT;
       
   	DROP TEMPORARY TABLE IF EXISTS temp_userid; 		CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT);
   	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT,ext INT);    
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	INSERT INTO temp_AvailableUser(	UserId,UserName,roleid,ext)
   	SELECT  UserID,	UserName,	roleid,	ext
   	FROM 	tb_User
   	WHERE 	domainId 	= p_domainId
   	AND 	roleid		IN (6,5,3)  ;
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   
   	SELECT 	roleid 	INTO v_roleid
       FROM 	temp_AvailableUser
   	WHERE 	ext = p_ext;
       
   		SET v_roleid = IFNULL(v_roleid,3);
   
   		IF v_roleid in (3,5) 
   		THEN
   			INSERT INTO temp_userid(UserId)
   			SELECT  UserID FROM temp_AvailableUser;
   		ELSE		
   			INSERT INTO temp_userid (UserId)
   			SELECT  UserID FROM temp_AvailableUser WHERE ext = p_ext;
   		END IF;            
   
		DROP TEMPORARY TABLE IF EXISTS temp_userid1; 
		CREATE TEMPORARY TABLE temp_userid1 
		SELECT * FROM temp_userid;
   
      
             
        	DROP TEMPORARY TABLE IF EXISTS temp_SocialMediaHistory;
       	CREATE TEMPORARY TABLE temp_SocialMediaHistory
   		(	dispositionId		INT	 
   			,dispositionName	VARCHAR(100)	
   			,IsInBound			TINYINT
   			,assignedTo			BIGINT        	        
   			,AssignedDate		DATETIME
   			,repliedDate		DATETIME
   			,Istransferred		TINYINT
   			,replyDuration		INT 
   			,IsMissed			TINYINT
			,isCallback			TINYINT
            ,dialDuration		INT
           );
           
           
      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		        
		IF (p_channelType = 'All' OR p_channelType = 'Whatsapp')
        THEN
		
       		INSERT INTO temp_SocialMediaHistory
               (	dispositionId		            
                   ,IsInBound			
                   ,assignedTo			
                   ,AssignedDate		
                   ,repliedDate		
                   ,Istransferred
                   ,IsMissed
                   ,isCallback
                   ,dialDuration
               )
       		SELECT 	EH.dispositionId			 
       			 ,	EH.IsInBound     
       			 ,	EH.assignedTo			 
       			 ,	from_unixtime(EH.AssignedOn/1000) AssignedDate
       			 ,	EH.repliedDate         
       			 ,	EH.Istransferred
				,	EDH.IsMissed
				,	case when EH.isCallback =1 and EH.callbackDraft=0 then 1 else 0 End isCallback
                ,	dialDuration
       		FROM 	tb_WhatsappHistory 			EH
 			JOIN 	tb_WhatsappDurationHistory 	EDH	ON 	EDH.WhatsappHistoryId 	= EH.WhatsappHistoryId 
   			JOIN 	temp_userid1				tu	ON 	EDH.AgentId			= tu.UserId  
       		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
       		AND 	EH.domainId 		= p_domainId;
            
		END IF;
		IF (p_channelType = 'All' OR p_channelType = 'Facebook')
        THEN  
            INSERT INTO temp_SocialMediaHistory
               (	dispositionId		            
                   ,IsInBound			
                   ,assignedTo			
                   ,AssignedDate		
                   ,repliedDate		
                   ,Istransferred
                   ,IsMissed
                   ,isCallback
                   ,dialDuration
               )
       		SELECT 	FH.dispositionId			 
				,	FH.IsInBound     
				,	FH.assignedTo			 
				,	from_unixtime(FH.AssignedOn/1000) AssignedDate
				,	FH.repliedDate         
				,	FH.Istransferred
				,	FH.IsMissed
				,	case when FH.isCallback =1 and FH.callbackDraft = 0 then 1 else 0 End isCallback
				,	FH.dialDuration
       		FROM 	tb_FacebookHistory 	FH
   			JOIN 	temp_userid1		TU	ON 	FH.AgentId			= TU.UserId  
       		WHERE 	FH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
       		AND 	FH.domainId 		= p_domainId; 
            
        END IF;    
		IF (p_channelType = 'All' OR p_channelType = 'Instagram')
        THEN
            INSERT INTO temp_SocialMediaHistory
               (	dispositionId		            
                   ,IsInBound			
                   ,assignedTo			
                   ,AssignedDate		
                   ,repliedDate		
                   ,Istransferred
                   ,IsMissed
                   ,isCallback
                   ,dialDuration
               )
       		SELECT 	IH.dispositionId			 
				,	IH.IsInBound     
				,	IH.assignedTo			 
				,	from_unixtime(IH.assignedOn/1000) AssignedDate
				,	IH.repliedDate         
				,	IH.Istransferred
				,	IH.IsMissed
				,	case when IH.isCallback =1 and IH.callbackDraft = 0 then 1 else 0 End isCallback
				,	IH.dialDuration
       		FROM 	tb_InstagramHistory 	IH
   			JOIN 	temp_userid1			TU	ON 	IH.AgentId			= TU.UserId  
       		WHERE 	IH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
       		AND 	IH.domainId 		= p_domainId;    
            
         END IF;     
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
   
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
      	FROM 	queueWeighTime QWT
      	WHERE 	QWT.domainId = p_domainId and QWT.queueType = 'SocialMedia';
      	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
           
      	UPDATE 		temp_SocialMediaHistory	EH 
      	LEFT JOIN 	disposition_status 		DS	ON 	EH.dispositionId 	= DS.did
      											AND DS.domainId			= p_domainId
      	SET 		EH.dispositionName	= DS.dispositionName
      		,		EH.replyDuration	= TIMESTAMPDIFF(SECOND, AssignedDate, repliedDate);
             
        	DROP TEMPORARY TABLE IF EXISTS tt_SocialMediaDetail;
        	CREATE TEMPORARY TABLE tt_SocialMediaDetail
        	SELECT 	IsInBound																InBound		
				,	CASE WHEN IsInBound = 1 THEN 0 ELSE 1 END								Outbound		
				,	CASE WHEN dispositionName IN ('Unresolved') THEN 1 ELSE 0 END			UnResolved
				,	Istransferred															Transferred	
				,	CASE WHEN dispositionName IN ('Resolved') THEN 1 ELSE 0 END  			Resolved
				,	CASE WHEN dispositionName IN ('Caller Disconnected') THEN 1 ELSE 0 END	Abandoned                 
				
				,	CASE WHEN IFNULL(dialDuration,0) > 0 THEN 1 ELSE 0 END 					InteractionWithin30Secs
				,	CASE WHEN IsMissed =1 THEN 1 ELSE 0 END									Missed
				,	isCallback 																as Callback														
        	FROM 	temp_SocialMediaHistory;        
                
       	SELECT 	COUNT(1)					Total     
       		,	IFNULL(SUM(InBound),0)		InBound
       		,	IFNULL(SUM(Outbound),0)		Outbound
       		,	IFNULL((SUM(InteractionWithin30Secs)/SUM(InBound)) * 100,0) ServiceLevel 
   			,	IFNULL(v_QueuedCustomers,0)	QueuedCustomers
   			,	IFNULL(SUM(Resolved),0)		Resolved
       		,	IFNULL(SUM(UnResolved),0)	UnResolved
       		,	IFNULL(SUM(Abandoned),0)	Abandoned
       		,	IFNULL(SUM(Transferred),0)	Transferred
   			,	IFNULL(SUM(Callback),0)		Callback
       		,	IFNULL(SUM(Missed),0)		Missed
       	FROM 	tt_SocialMediaDetail;
      END ;;
DELIMITER ;
