CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_dashboard_SocialMedia_piechart_feautre_details_1`(
           p_startTmpstmp 		bigint,
           p_endTmpstmp 		bigint,
           p_domainId 			int,  
           p_timezone			VARCHAR(30),
           p_ext 				int
           )
BEGIN
	DECLARE v_AgentId			INT;
	DECLARE v_roleid			INT;
	DECLARE v_QueuedCustomers	INT;
        
   	SELECT 	UserID , roleid   
   	INTO	v_AgentId, v_roleid 		
   	FROM 	tb_User
   	WHERE 	domainId 	= p_domainId
   	AND 	ext			= p_ext;
          
	DROP TEMPORARY TABLE IF EXISTS temp_SocialMediaHistory;
	CREATE TEMPORARY TABLE temp_SocialMediaHistory
	(	dispositionId		INT	 
		,dispositionName	VARCHAR(100)	
		,IsInBound			TINYINT
		,assignedTo			BIGINT        	        
		,AssignedDate		DATETIME
		,repliedDate		DATETIME
		,Istransferred		TINYINT
		,replyDuration		INT        
	);
        
        IF v_roleid = 6 
        THEN    
			select 'kms1';
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		INSERT INTO temp_SocialMediaHistory
            (	dispositionId		            
                ,IsInBound			
                ,assignedTo			
                ,AssignedDate		
                ,repliedDate		
                ,Istransferred
            )
    		SELECT 	EH.dispositionId			 
    			 ,	EH.IsInBound     
    			 ,	EH.assignedTo			 
    			 ,	from_unixtime(EH.AssignedOn/1000) AssignedDate
    			 ,	EH.repliedDate         
    			 ,	EH.Istransferred         
    		FROM 	tb_WhatsappHistory 			EH
            JOIN 	tb_WhatsappDurationHistory 	EDH	ON 	EDH.WhatsappHistoryId 	= EH.WhatsappHistoryId
   												AND EDH.AgentId				= v_AgentId
    		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
    		AND 	EH.domainId 		= p_domainId;  
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
    	ELSE
			select 'kms2';
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		INSERT INTO temp_SocialMediaHistory
            (	dispositionId		            
                ,IsInBound			
                ,assignedTo			
                ,AssignedDate		
                ,repliedDate		
                ,Istransferred
            )
    		SELECT 	EH.dispositionId			 
    			 ,	EH.IsInBound     
    			 ,	EH.assignedTo			 
    			 ,	from_unixtime(EH.AssignedOn/1000) AssignedDate
    			 ,	EH.repliedDate         
    			 ,	EH.Istransferred         
    		FROM 	tb_WhatsappHistory 			EH
            JOIN 	tb_WhatsappDurationHistory 	EDH	ON 	EDH.WhatsappHistoryId 	= EH.WhatsappHistoryId   												
    		WHERE 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
    		AND 	EH.domainId 		= p_domainId;     
            
            
            
             
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
    	END IF;		    
        
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	SUM(JSON_LENGTH(queueList,'$')) INTO v_QueuedCustomers 
   	FROM 	queueWeighTime QWT
   	WHERE 	QWT.domainId = p_domainId and QWT.queueType = 'SocialMedia';
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
        
   	UPDATE 		temp_SocialMediaHistory	EH 
   	LEFT JOIN 	disposition_status 		DS	ON 	EH.dispositionId 	= DS.did
   											AND DS.domainId			= p_domainId
   	SET 		EH.dispositionName	= DS.dispositionName
   		,		EH.replyDuration	= TIMESTAMPDIFF(HOUR, AssignedDate, repliedDate);
        
	select 'kms',smh.* from temp_SocialMediaHistory smh;        
          
     	DROP TEMPORARY TABLE IF EXISTS tt_SocialMediaDetail;
     	CREATE TEMPORARY TABLE tt_SocialMediaDetail
     	SELECT 	IsInBound																InBound		
     		,	CASE WHEN IsInBound = 1 THEN 0 ELSE 1 END								Outbound		
     		,	CASE WHEN dispositionName IN ('Closed','Resolved') THEN 0 ELSE 1 END	UnResolved
    		,	Istransferred															Transferred	
     		,	CASE WHEN dispositionName IN ('Closed','Resolved') THEN 1 ELSE 0 END  	Resolved
      		,	0 																		Abandoned                 
   		,	CASE WHEN replyDuration < 24 THEN 1 ELSE 0 END 							InteractionWithin30Secs
           ,	CASE WHEN dispositionName IN ('Missed') THEN 1 ELSE 0 END				Missed
     	FROM 	temp_SocialMediaHistory;        
     
		SELECT 	'kms-4'
			,	SUM(InteractionWithin30Secs)
			,	sum(InBound) 
    	FROM 	tt_SocialMediaDetail;
        
    	SELECT 	COUNT(1)					Total     
    		,	IFNULL(SUM(InBound),0)		InBound
    		,	IFNULL(SUM(Outbound),0)		Outbound
    		,	IFNULL(SUM(InteractionWithin30Secs/InBound) * 100,0) ServiceLevel 
         ,	IFNULL(v_QueuedCustomers,0)	QueuedCustomers
   		,	IFNULL(SUM(Resolved),0)		Resolved
    		,	IFNULL(SUM(UnResolved),0)	UnResolved
    		,	IFNULL(SUM(Abandoned),0)	Abandoned
    		,	IFNULL(SUM(Transferred),0)	Transferred
 		,	0							Callback
    		,	IFNULL(SUM(Missed),0)		Missed
    	FROM 	tt_SocialMediaDetail;
   END ;;
DELIMITER ;
