CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dashboard_video_call_details`(
               p_startTmpstmp 		bigint,
               p_endTmpstmp 		bigint,
               p_domainId 			int,  
               p_timezone			VARCHAR(30),
               p_ext 				int
	)
BEGIN
    	DECLARE v_AgentId			INT;
    	DECLARE v_roleid			INT;
    	DECLARE v_QueuedCustomers	INT;
        
    	DROP TEMPORARY TABLE IF EXISTS temp_userid; 		CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT);
    	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT,ext INT);    
        
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    	INSERT INTO temp_AvailableUser(	UserId,UserName,roleid,ext)
    	SELECT  UserID,	UserName,	roleid,	ext
    	FROM 	tb_User
    	WHERE 	domainId 	= p_domainId
    	AND 	roleid		IN (6,5,3)  ;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    	SELECT 	roleid 	INTO v_roleid
        FROM 	temp_AvailableUser
    	WHERE 	ext = p_ext;
        
    		SET v_roleid = IFNULL(v_roleid,3);
    
    		IF v_roleid in (3,5) 
    		THEN
    			INSERT INTO temp_userid(UserId)
    			SELECT  UserID FROM temp_AvailableUser;
    		ELSE		
    			INSERT INTO temp_userid (UserId)
    			SELECT  UserID FROM temp_AvailableUser WHERE ext = p_ext;
    		END IF;            
    
 		DROP TEMPORARY TABLE IF EXISTS temp_userid1; 
 		CREATE TEMPORARY TABLE temp_userid1 
 		SELECT * FROM temp_userid;
              
			DROP TEMPORARY TABLE IF EXISTS temp_VideoHistory;
			CREATE TEMPORARY TABLE temp_VideoHistory AS
        		SELECT 	
						VH.VideoHistoryId
                        ,(VDH.agentDuration / 1000) 	AS agentDuration
                        ,CASE WHEN VDH.agentDuration > 0 THEN 1 ELSE 0 END AS AnsweredCount
                        ,CASE WHEN DS.dispositionName IN ('Closed','Resolved','Caller Disconnected') THEN 1 ELSE 0 END AS resolvedCount
                        ,ROW_NUMBER() OVER(PARTITION BY VDH.VideoHistoryId ORDER BY VideoDurationHistoryId DESC) AS RN
                        ,CASE WHEN IFNULL(transferredTime,0) <> 0 THEN 1 ELSE 0 END as isTransfer
        		FROM 	tb_VideoHistory 			VH
				JOIN 	tb_VideoDurationHistory 	VDH	ON 	VH.VideoHistoryId 	= VDH.VideoHistoryId
                LEFT JOIN disposition_status		DS  ON  DS.did 				= VDH.dispositionId
    			JOIN 	temp_userid1				tu	ON 	VDH.AgentId			= tu.UserId  
        		WHERE 	VH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp 	 	
        		AND 	VH.domainId 		= p_domainId;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
        
		DROP TEMPORARY TABLE IF EXISTS tt_VideoHistory;
		CREATE TEMPORARY TABLE tt_VideoHistory AS
		SELECT 	
				COUNT(VideoHistoryId)													totalAttempt		
			,	SUM(agentDuration)														ansDuration		
			,	SUM(AnsweredCount)														AnsweredCount
			,	SUM(CASE WHEN resolvedCount = 1 AND RN = 1 AND isTransfer = 0 THEN 1 ELSE 0 END)			firstResolvedCount
		FROM 	temp_VideoHistory;        
		
        DROP TEMPORARY TABLE IF EXISTS tt_VideoHistory_final;
		CREATE TEMPORARY TABLE tt_VideoHistory_final AS
		SELECT 	totalAttempt												videoCallVolume     
			,	(ansDuration / AnsweredCount)								avgCallDuraion
			,	(AnsweredCount / totalAttempt) * 100						successRate
            ,	(( totalAttempt - AnsweredCount) / totalAttempt ) * 100 	dropRate
			,	(firstResolvedCount / AnsweredCount) * 100					firstCallResolution
		FROM 	tt_VideoHistory;
        
        SELECT 
			videoCallVolume
            ,round(avgCallDuraion)		AS avgCallDuraion
            ,round(successRate) 		AS successRate
            ,round(dropRate) 			AS dropRate
            ,round(firstCallResolution) AS firstCallResolution
        FROM tt_VideoHistory_final;
	END ;;
DELIMITER ;
