CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_default_business_hours`(
		 p_domainId			int
)
begin
		SELECT hours
        FROM custom_hours
        WHERE domainId = p_domainId
        AND type = 'Default';
end ;;
