CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_DID_List`(
	  p_domainId		INT
	 ,p_search			VARCHAR(150)
     ,p_numberType		VARCHAR(250)
     ,p_capability		TINYINT		
     ,p_offset			INT
     ,p_limit 			INT 
    
)
begin
		DECLARE v_offset 	INT;
        DECLARE v_limit		INT;
        DECLARE v_total_did INT;
        
        SET v_offset = p_Limit * p_offset; 
        SET v_limit  = p_Limit;
        
        SELECT COUNT(*) INTO v_total_did
		FROM did_purchase 
		WHERE domainId = p_domainId;
        
        IF (p_offset IS NULL AND p_limit IS NULL)
			THEN 
				SET v_offset = 0,v_limit = v_total_did;
			
		END IF;
		
        DROP TEMPORARY TABLE IF EXISTS tt_type;
        CREATE TEMPORARY TABLE tt_type(numberType VARCHAR(150));
        
        CALL split(p_numberType,',');
        INSERT INTO tt_type
        SELECT Items FROM tt_Split_temptable;
                
		DROP TEMPORARY TABLE IF EXISTS tt_purchase;
        CREATE TEMPORARY TABLE tt_purchase AS
		SELECT     pid, user_id, type, city, your_number, createdAt, updatedAt, domainId,
			callFlowId, recording, isCall, isSms, queueName, aliasName, outboundSms,
			smsThreshold, status, callFlowName, defaultUpdated, supervisorName,
			isCallIn, isCallOut, isSmsOut, isSmsIn, queueId, country, isBot,
			isBotPurchased, knowledgeBasedId, autoAssignAgent
		FROM     did_purchase dd
		WHERE     domainId = p_domainId
		AND ( p_numberType IS NULL OR type collate utf8mb4_0900_ai_ci IN ( SELECT numberType FROM tt_type ))    
		AND ( p_search collate utf8mb4_0900_ai_ci IS NULL OR your_number collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_search, '%') )
		AND ( p_capability IS NULL OR ( (p_capability = 1 AND (isCallIn = 1 OR isCallOut = 1)) OR (p_capability = 2 AND (isCallIn = 1 OR isCallOut = 1 OR isSmsOut = 1 OR isSmsIn = 1)) ) )
		ORDER BY createdAt DESC, updatedAt DESC;
		 
		SELECT * FROM tt_purchase
        LIMIT v_offset, v_limit;

		SELECT COUNT(*) AS total_did
        FROM tt_purchase;
        
        SELECT DISTINCT type AS numberType
        FROM did_purchase
		WHERE domainId = p_domainId
        AND IFNULL(type,'') <> '';

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
