CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_did_purchase_list`(
	p_domain_Id			INT,	
    p_searchBy 			VARCHAR(20),
    p_searchByValue		VARCHAR(200),
    p_offset			smallint,
    p_limit				INT
)
BEGIN
	DECLARE v_offset		INT;    
    DECLARE v_searchByValue	VARCHAR(202);
    
    SET v_offset = p_offset * p_limit;
    SET v_searchByValue = CONCAT('%',p_searchByValue,'%');
		
    DROP TEMPORARY TABLE IF EXISTS tt_did_purchase;
	CREATE TEMPORARY TABLE tt_did_purchase(
		pid					int
		,user_id			int
		,`type`				varchar(255)
		,city				varchar(255)
		,your_number		varchar(255)
		,createdAt			datetime
		,updatedAt			datetime
		,domainId			int
		,callFlowId			varchar(100)
		,recording			int
		,isCall				tinyint
		,isSms				tinyint
		,queueName			varchar(40)
		,aliasName			varchar(40)
		,outboundSms		tinyint
		,smsThreshold		int
		,`status`			int
		,callFlowName		varchar(100)
		,defaultUpdated		int
		,supervisorName		varchar(200)
		,isCallIn			tinyint
		,isCallOut			tinyint
		,isSmsOut			tinyint
		,isSmsIn			tinyint
		,queueId			int
		,country			varchar(100)
		,isBot				tinyint
		,isBotPurchased		tinyint
		,knowledgeBasedId	varchar(150)
		,autoAssignAgent	tinyint
    );
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	IF p_searchBy IS NOT NULL AND p_searchByValue IS NOT NULL
    THEN
		IF p_searchBy = 'All'
        THEN
			INSERT INTO tt_did_purchase
            SELECT pid					
                   ,user_id			
                   ,`type`				
                   ,city				
                   ,your_number		
                   ,createdAt			
                   ,updatedAt			
                   ,domainId			
                   ,callFlowId			
                   ,recording			
                   ,isCall				
                   ,isSms				
                   ,queueName			
                   ,aliasName			
                   ,outboundSms		
                   ,smsThreshold		
                   ,`status`			
                   ,callFlowName		
                   ,defaultUpdated		
                   ,supervisorName		
                   ,isCallIn			
                   ,isCallOut			
                   ,isSmsOut			
                   ,isSmsIn			
                   ,queueId			
                   ,country			
                   ,isBot				
                   ,isBotPurchased		
                   ,knowledgeBasedId	
                   ,autoAssignAgent	
			FROM 	did_purchase
			WHERE 	domainId 	= p_domain_Id
			AND 	(`type`		LIKE v_searchByValue OR city LIKE v_searchByValue)
            ORDER BY createdAt DESC, updatedAt DESC
            LIMIT 	v_offset, p_limit;
		ELSE  
			INSERT INTO tt_did_purchase
			SELECT pid					
				   ,user_id			
				   ,`type`				
				   ,city				
				   ,your_number		
				   ,createdAt			
				   ,updatedAt			
				   ,domainId			
				   ,callFlowId			
				   ,recording			
				   ,isCall				
				   ,isSms				
				   ,queueName			
				   ,aliasName			
				   ,outboundSms		
				   ,smsThreshold		
				   ,`status`			
				   ,callFlowName		
				   ,defaultUpdated		
				   ,supervisorName		
				   ,isCallIn			
				   ,isCallOut			
				   ,isSmsOut			
				   ,isSmsIn			
				   ,queueId			
				   ,country			
				   ,isBot				
				   ,isBotPurchased		
				   ,knowledgeBasedId	
				   ,autoAssignAgent	
			FROM did_purchase
			WHERE 	domainId 	= p_domain_Id
			AND (	(p_searchBy = 'type' AND `type`	LIKE v_searchByValue)
				OR 	(p_searchBy = 'city' AND `city`	LIKE v_searchByValue))
			ORDER BY createdAt DESC, updatedAt DESC
            LIMIT 	v_offset, p_limit;		
		END IF;
	ELSE
		INSERT INTO tt_did_purchase
		SELECT pid					
			   ,user_id			
			   ,`type`				
			   ,city				
			   ,your_number		
			   ,createdAt			
			   ,updatedAt			
			   ,domainId			
			   ,callFlowId			
			   ,recording			
			   ,isCall				
			   ,isSms				
			   ,queueName			
			   ,aliasName			
			   ,outboundSms		
			   ,smsThreshold		
			   ,`status`			
			   ,callFlowName		
			   ,defaultUpdated		
			   ,supervisorName		
			   ,isCallIn			
			   ,isCallOut			
			   ,isSmsOut			
			   ,isSmsIn			
			   ,queueId			
			   ,country			
			   ,isBot				
			   ,isBotPurchased		
			   ,knowledgeBasedId	
			   ,autoAssignAgent	
		FROM 	did_purchase
		WHERE 	domainId = p_domain_Id;
    END IF; 
    
    SELECT pid					
			   ,user_id			
			   ,`type`				
			   ,city				
			   ,your_number		
			   ,createdAt			
			   ,updatedAt			
			   ,domainId			
			   ,callFlowId			
			   ,recording			
			   ,isCall				
			   ,isSms				
			   ,queueName			
			   ,aliasName			
			   ,outboundSms		
			   ,smsThreshold		
			   ,`status`			
			   ,callFlowName		
			   ,defaultUpdated		
			   ,supervisorName		
			   ,isCallIn			
			   ,isCallOut			
			   ,isSmsOut			
			   ,isSmsIn			
			   ,queueId			
			   ,country			
			   ,isBot				
			   ,isBotPurchased		
			   ,knowledgeBasedId	
			   ,autoAssignAgent 
		FROM tt_did_purchase ORDER BY createdAt DESC, updatedAt DESC;
        
	SELECT 	COUNT(1) AS TotalCount
	FROM 	tt_did_purchase;    
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
