CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_disposition_list`(
 	p_domainId INT,
    p_Id  int,
    p_Offset int,
    p_limit int
 )
begin
		declare v_offset int;
 
	     SET v_offset =  p_limit * p_Offset; 
 
 	SELECT did as id, dispositionName, type, description, status, createdAt, updatedAt, colorCode
     FROM disposition_status
     WHERE domainId = p_domainId
     AND (did = p_Id or ifnull(p_Id,0)=0)
     AND status = 1 AND accessType = 1
     order by did asc
     LIMIT 	 v_offset, p_limit;  
 
 end ;;
DELIMITER ;
