CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_DND_customer_dtl`(
 	 p_domainId			INT 
     ,p_customerNumber	VARCHAR(50)
 
 )
begin
 	
     DECLARE v_doNotDisturb TINYINT;
     
 	SELECT doNotDisturb INTO v_doNotDisturb FROM customer_contact WHERE domainId = p_domainId and primaryPhoneNumber collate utf8mb4_0900_ai_ci = p_customerNumber limit 1;
 	
     SELECT IFNULL(v_doNotDisturb,0) AS doNotDisturb;
     
 end ;;
