CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_domainLevel_knowledgeBaseId`(	
	 p_domainId 				INT
 	,p_channelType 				VARCHAR(50)
 )
BEGIN
 	 
     
     IF p_channelType = 'Whatsapp'
     THEN
 		 SELECT knowledgeBaseId 
         FROM tb_WhatsappConfiguration 
         WHERE 	domainId = p_domainId;    
     ELSEIF p_channelType = 'Facebook'
     THEN
		 SELECT knowledgeBaseId 
         FROM tb_FacebookConfiguration 
         WHERE 	domainId = p_domainId;
	ELSEIF p_channelType = 'Instagram'
     THEN
		 SELECT knowledgeBaseId 
         FROM tb_InstagramConfiguration 
         WHERE 	domainId = p_domainId;
	END IF;
 END ;;
