CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_domain_user_skills`(
    p_domainId int
    )
Begin
    
	
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        
       SELECT 
		a.UserID,a.UserName,a.emailId,a.ext
        ,(SELECT JSON_ARRAYAGG(
        JSON_OBJECT(
            'skid', sk.sid,
            'value', sk.skill_name,
            'type', sk.type
				)
			)
		FROM skills sk
		JOIN skillMapping sm ON sk.sid = sm.skid
		WHERE sk.domainId = a.domainId
		AND sm.usid = a.UserID) AS addSkill
       FROM tb_User a 
       WHERE a.domainId = p_domainId ;
       
end ;;
DELIMITER ;
