CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dynamic_dashboard_facebook_history`(
		p_domainId 			INT 	
		,p_start_timestamp	BIGINT
		,p_end_timestamp	BIGINT
		,p_start_datetime	DATETIME
		,p_end_datetime		DATETIME
		,p_AgentId			INT
		,p_offset 			INT
		,p_limit 			INT 	 	
)
spreturn:BEGIN  
	DECLARE v_CurDate	DATETIME;	
	DECLARE v_offset 	INT;
    DECLARE v_roleid	INT;		

	SET v_CurDate = NOW();
	SET v_offset = p_offset * p_limit;

	DROP TEMPORARY TABLE IF EXISTS temp_userid; CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT, key `temp_userid_UserId`(UserId));
            				   
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	
    CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT, KEY `idx_temp_AvailableUser_UserId` (`UserId`));    
	INSERT INTO temp_AvailableUser
	(	UserId
	   ,UserName
	   ,roleid
	)
	SELECT  UserID
		,	UserName
		,	roleid
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	roleid		IN (6,5,3);     
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

	SELECT 	roleid 	INTO v_roleid
	FROM 	temp_AvailableUser
	WHERE 	UserId = p_AgentId;

	IF IFNULL(p_AgentId,0) = 0 OR v_roleid in (3,5) 
	THEN
		INSERT INTO temp_userid
		(	UserId )
		SELECT  UserID
		FROM 	temp_AvailableUser;		
	ELSE		
		INSERT INTO temp_userid
		(	UserId )
		SELECT  p_AgentId;
	END IF;
    
						DROP TEMPORARY TABLE IF EXISTS temp_History; 
            					CREATE TEMPORARY TABLE temp_History 
            					(
            						id_col int auto_increment primary key ,sessionId varchar(250), sessionStartTime bigint, sessionEndTime bigint, domainId int default null, summary text default null
                                    ,dispositionId int default null	,IsInBound tinyint default null	,assignedTo bigint default null	,assignedBy bigint default null,assignedOn bigint default null, afterFacebookWorkTime	int
                                    ,NextFlowNode	varchar(150), Istransferred bigint default null, transferredTo bigint default null ,transferredTypeId int default null,transferredDate	datetime, dispositionUpdatedBy	bigint			
                                    ,immediateParentId	bigint ,rootParentId	bigint, discardedDate	datetime	,repliedDate	datetime, markAsReadSupervisor	tinyint, markAsReadAgent	tinyint, IsSessionClosed tinyint default null
                                    ,customerFacebookId	varchar(100), agentFacebookId	varchar(100),ticketId bigint default null, AgentId bigint default null, IsBot int   default null, BotId int  default null
                                    ,AgentStartTime	bigint	,AgentEndTime	bigint, Duration bigint  default null, SentimentalScore float default null, createdAt datetime default null,updatedAt datetime default null,channelType VARCHAR(255) default null	
                                    ,FacebookHistoryId	bigint, DurationHistoryId		bigint	,IsMissed	tinyint	,QueueId int  default null	,name	varchar(255), CustomerId int default null ,assignedByName varchar(150) default null			
                                    ,transferedBy bigint default null, dispositionName varchar(100) default null,transferredToName	varchar(150)		
                                    
                                    
                                    
                                    
 


















            					); 
                                
                                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
            					insert into temp_History(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,
                                IsInBound
                                ,assignedTo
                                ,assignedBy
                                ,assignedOn
                                ,afterFacebookWorkTime
                                ,NextFlowNode
                                ,Istransferred
                                ,transferredTo
                                ,transferredTypeId
                                ,transferredDate
                                ,dispositionUpdatedBy
                                ,immediateParentId
                                ,rootParentId
                                ,discardedDate
                                ,repliedDate
                                ,markAsReadSupervisor
            					,markAsReadAgent	
                                ,IsSessionClosed
                                ,customerFacebookId
                                ,agentFacebookId
                                ,ticketId
                                ,AgentId
                                ,IsBot
                                ,BotId
                                ,AgentStartTime
                                ,AgentEndTime
                                ,Duration
                                ,SentimentalScore
                                ,createdAt
            					,updatedAt	
            					, channelType	
								,FacebookHistoryId   
                                ,DurationHistoryId
                                ,IsMissed
                                ,QueueId
                                ,name
								,CustomerId)
            					SELECT 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterFacebookWorkTime,fb.NextFlowNode
            						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
            						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerFacebookId,fb.agentFacebookId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
            						,fb.createdAt,fb.updatedAt,'Facebook',fb.FacebookHistoryId,fb.FacebookHistoryId,fb.IsMissed, fb.queueId,q.name,fb.CustomerId
            					FROM 	tb_FacebookHistory 		fb
								LEFT JOIN 	temp_userid			U	ON fb.AgentId			= U.UserId
							
								left join 	queue				q	ON fb.queueId			= q.qid
								WHERE 	fb.domainId 		= p_domainId
							
							
                           
								AND 	CAST(fb.updatedAt AS DATE) BETWEEN p_start_datetime AND p_end_datetime
								AND 	(fb.IsSessionClosed = 1 ) 
                                
								AND 	(IFNULL(p_AgentId,0) = 0 OR (p_AgentId IS NOT NULL AND U.UserId IS NOT NULL))
							
								ORDER BY fb.updatedAt DESC 
                                LIMIT v_offset, p_limit;
								SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                                
                                
                      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;    
    CREATE TEMPORARY TABLE temp_customer_contact
	WITH CTE_Customer AS (
		SELECT 	DISTINCT CustomerId
        FROM 	temp_History
    )	
	SELECT 	CC.coid
			,CC.primaryPhoneNumber
			,CC.firstName
			,CC.lastName      
	FROM 	customer_contact 	CC
    JOIN 	CTE_Customer		C	ON C.CustomerId = CC.coid
	WHERE 	CC.domainId = p_domainId;       
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
                                      

								   
	ALTER TABLE temp_History ADD COLUMN CustomerName	VARCHAR(150), ADD COLUMN agentName VARCHAR(150), ADD colorCode VARCHAR(50)
	,ADD COLUMN transferredByName VARCHAR(150);

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; 
	CREATE TEMPORARY TABLE temp_AvailableUser1
	SELECT * FROM temp_AvailableUser;

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser2; 
	CREATE TEMPORARY TABLE temp_AvailableUser2
	SELECT * FROM temp_AvailableUser;
	  
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser3; 
	CREATE TEMPORARY TABLE temp_AvailableUser3
	SELECT * FROM temp_AvailableUser;      

	 DROP TEMPORARY TABLE IF EXISTS tmp_disposition; 
	CREATE TEMPORARY TABLE tmp_disposition
	  SELECT did 
		,	dispositionName
		,	colorCode
	  FROM 	disposition_status
	  WHERE	domainId	= p_domainId;
	  
	  INSERT INTO tmp_disposition
	  SELECT TypeCodeID		AS did
		,	TypeCodeName	AS dispositionName
		,	Null			AS colorCode
	  FROM 	TypeCode 	
	  WHERE TypeGroupID = 1121;	              

	UPDATE 	temp_History		H
	LEFT JOIN 	temp_AvailableUser	AB	ON H.assignedBy			= AB.UserId        
	LEFT JOIN 	temp_AvailableUser1	ATU	ON H.AgentId			= ATU.UserId        
	LEFT JOIN 	temp_AvailableUser2	TU	ON H.transferredTo    	= TU.UserId	
	LEFT JOIN 	temp_AvailableUser3	TL	ON H.transferedBy    	= TL.UserId	
	LEFT JOIN 	tmp_disposition		DS	ON H.dispositionId		= DS.did
	SET 	H.assignedByName	= AB.UserName 
		,	H.dispositionName	= DS.dispositionName
		,	H.colorCode			= DS.colorCode
		,	H.agentName			= ATU.UserName
		,	H.transferredToName	= TU.UserName
		,   H.transferredByName = TL.UserName
		,	H.CustomerId		= IFNULL(H.CustomerId,0); 

	UPDATE 	temp_History		H
	JOIN 	customer_contact	CC 	ON H.CustomerId = CC.coid 
	SET 	H.CustomerName	= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),ifnull(CC.lastName,''));     

	SELECT 	*
	FROM 	temp_History a 	
	ORDER BY updatedAt DESC;

    
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dynamic_dashboard_instagram` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dynamic_dashboard_instagram`(
		p_domainId					INT
		,p_start_timestamp			BIGINT
		,p_end_timestamp			BIGINT
		,p_start_datetime			DATETIME
		,p_end_datetime				DATETIME
	
 )
BEGIN
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
					
			DROP TEMPORARY TABLE IF EXISTS tt_dynamic_dashboard_instagram;
            CREATE TEMPORARY TABLE tt_dynamic_dashboard_instagram
              SELECT
					InstagramHistoryId,
					CASE WHEN IsInBound = 1 THEN 1 ELSE 0 END 							AS InBound,
				    CASE WHEN isCallback =1 AND callbackDraft = 0 THEN 1 ELSE 0 END  				AS isCallback,
				    CASE WHEN IFNULL(dialDuration,0) > 0 THEN 1 ELSE 0 END 							AS InteractionWithin30Secs,
				    Duration,
				    IsMissed 																		AS Missed
              FROM tb_InstagramHistory
              WHERE domainId = p_domainId  AND sessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp;      
              
            
            SELECT 	
					 SUM(InBound)														AS 			total_inbound
					,SUM(isCallback)													AS 			callback_request
					,IFNULL((SUM(InteractionWithin30Secs)/SUM(InBound)) * 100,0) 		AS			ServiceLevel
                    ,IFNULL(SUM(Duration)/count(InstagramHistoryId), 0)					AS 			averageSpeedOfAnswer
					,SUM(IFNULL(Missed, 0))												AS			missed_chat					
            FROM tt_dynamic_dashboard_instagram;
            
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
			
            
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_dynamic_dashboard_sms` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dynamic_dashboard_sms`(
		 p_domainId					INT
		,p_start_timestamp			BIGINT
		,p_end_timestamp			BIGINT
		,p_start_datetime			DATETIME
		,p_end_datetime				DATETIME
)
BEGIN
			DROP TEMPORARY TABLE IF EXISTS tt_dynamic_dashboard_sms;
			CREATE TEMPORARY TABLE tt_dynamic_dashboard_sms		
            SELECT 
					IFNULL(SH.IsInBound, 0)																						 	AS IsInBound,
                    SH.dispositionId,
                    SDH.IsBot,
                    SH.IsSessionClosed,
                    DS.dispositionName,
                    SH.assignedOn,
                    SH.sessionStartTime,
                    SH.repliedDate,
                    DP.smsThreshold,
                    SH.assignedTo,
                    SH.isOpened,
                    FROM_UNIXTIME(IFNULL(SH.AssignedOn,SH.SessionStartTime)/1000) 													AS AssignedDate,
                    CASE WHEN TIMESTAMPDIFF(MINUTE, SH.createdAt, NOW()) >= DP.smsThreshold THEN 1 ELSE 0 END 						AS isThresholdTimeExceeded,
                    TIMESTAMPDIFF(HOUR, FROM_UNIXTIME(IFNULL(SH.AssignedOn,SH.SessionStartTime)/1000), SH.repliedDate)				AS replyDuration
                    
            FROM tb_SMSHistory SH JOIN tb_SMSDurationHistory SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
							LEFT JOIN  disposition_status	DS	ON SH.dispositionId = DS.did
                            LEFT JOIN did_purchase 			DP	ON 	DP.domainId = SH.domainId	AND DP.your_number = SH.calledNumber
            WHERE SH.domainId = p_domainId	AND  SH.sessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp;
            
            
            
			ALTER TABLE tt_dynamic_dashboard_sms 
            
				ADD COLUMN InteractionWithin30Secs		INT;
            
          
            
            UPDATE tt_dynamic_dashboard_sms SET	InteractionWithin30Secs = CASE WHEN replyDuration < smsThreshold and dispositionName <> 'Transferred' THEN 1 ELSE 0 END; 	
            
	
            
            SELECT 
					SUM(CASE WHEN  IsInBound = 1 THEN 1 ELSE 0 END) 																			AS in_bound,
                    SUM(CASE WHEN  IsInBound = 0 THEN 1 ELSE 0 END) 																			AS out_bound,
                    SUM(CASE WHEN assignedTo IS NOT NULL AND IFNULL(IsSessionClosed,0) = 0 AND dispositionId IS NULL  THEN 1 ELSE 0 END) 		AS Assigned
                  ,SUM(CASE WHEN (assignedTo IS NULL AND IFNULL(IsSessionClosed,0) = 0 AND dispositionId IS NULL AND isBot = 0) 
                    THEN 1 ELSE 0 END) 																											AS UnAssigned
                     ,IFNULL(SUM(InteractionWithin30Secs)/COUNT(IsInBound) * 100,0)																AS ServiceLevel
                    ,SUM(CASE WHEN isThresholdTimeExceeded = 1 and dispositionName IS NULL THEN 1 ELSE 0 END) 									AS OverDue 
                     ,SUM(case when isOpened = 1 and dispositionName IS NULL THEN 1 ELSE 0 END)													AS Opened
            FROM tt_dynamic_dashboard_sms;
            
            
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
