/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dynamic_dashboard_video`(	 	p_domainId					INT
		,p_start_timestamp			BIGINT
		,p_end_timestamp			BIGINT
		,p_start_datetime			DATETIME
		,p_end_datetime				DATETIME
)
BEGIN

			DECLARE v_total_attempt				INT DEFAULT 0;
            DECLARE v_answer_duration			FLOAT;
            DECLARE v_answered_count			INT;
            DECLARE v_first_resolved_count		INT;
            
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		DROP TEMPORARY TABLE IF EXISTS tt_video_history_details;
        CREATE TEMPORARY TABLE tt_video_history_details
		SELECT 
					VH.VideoHistoryId				
					,(VDH.agentDuration / 1000) 	AS agentDuration
					,CASE WHEN VDH.agentDuration > 0 THEN 1 ELSE 0 END AS AnsweredCount
					,CASE WHEN DS.dispositionName IN ('Closed','Resolved','Caller Disconnected') THEN 1 ELSE 0 END AS resolvedCount
					,ROW_NUMBER() OVER(PARTITION BY VDH.VideoHistoryId ORDER BY VideoDurationHistoryId DESC) AS RN
					,CASE WHEN IFNULL(transferredTime,0) <> 0 THEN 1 ELSE 0 END as isTransfer
        FROM tb_VideoHistory AS VH 
			JOIN tb_VideoDurationHistory	AS VDH ON VH.VideoHistoryId = VDH.VideoHistoryId
			LEFT JOIN disposition_status		DS  ON  DS.did 				= VDH.dispositionId	
            WHERE VH.sessionStartTime BETWEEN p_start_timestamp and p_end_timestamp
            AND 	VH.domainId 		= p_domainId;
            
            
           
            
          SELECT 	
				COUNT(VideoHistoryId)			
			,	SUM(agentDuration)				
			,	SUM(AnsweredCount)		
			,	SUM(CASE WHEN resolvedCount = 1 AND RN = 1 AND isTransfer = 0 THEN 1 ELSE 0 END)			
					INTO v_total_attempt, v_answer_duration, v_answered_count, v_first_resolved_count
		FROM 	tt_video_history_details;   
        
       
        
        
        	SELECT 	v_total_attempt													 		AS		videoCallVolume     
			,	ROUND((v_answer_duration / v_answered_count))						 		AS		avgCallDuraion
			,	ROUND((v_answered_count / v_total_attempt) * 100)						 	AS		successRate
            ,	ROUND((( v_total_attempt - v_answered_count) / v_total_attempt ) * 100) 	AS 		dropRate
			,	ROUND((v_first_resolved_count / v_answered_count) * 100)					AS		firstCallResolution;
            
            
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
