CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dynamic_dashboard_video_history`(
		p_domainId 			INT 	
		,p_start_timestamp	BIGINT
		,p_end_timestamp	BIGINT
		,p_start_datetime	DATETIME
		,p_end_datetime		DATETIME
		,p_AgentId			INT
		,p_offset 			INT
		,p_limit 			INT 	 
)
spreturn:BEGIN  
	DECLARE v_CurDate	DATETIME;	
	DECLARE v_offset 	INT;
    DECLARE v_roleid	INT;		

	SET v_CurDate = NOW();
	SET v_offset = p_offset * p_limit;

	DROP TEMPORARY TABLE IF EXISTS temp_userid; CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT, key `temp_userid_UserId`(UserId));
            				   
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	
    CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT, KEY `idx_temp_AvailableUser_UserId` (`UserId`));    
	INSERT INTO temp_AvailableUser
	(	UserId
	   ,UserName
	   ,roleid
	)
	SELECT  UserID
		,	UserName
		,	roleid
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	roleid		IN (6,5,3);     
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

	SELECT 	roleid 	INTO v_roleid
	FROM 	temp_AvailableUser
	WHERE 	UserId = p_AgentId;

	IF IFNULL(p_AgentId,0) = 0 OR v_roleid in (3,5) 
	THEN
		INSERT INTO temp_userid
		(	UserId )
		SELECT  UserID
		FROM 	temp_AvailableUser;		
	ELSE		
		INSERT INTO temp_userid
		(	UserId )
		SELECT  p_AgentId;
	END IF;
    
				DROP TEMPORARY TABLE IF EXISTS temp_History; 
            					CREATE TEMPORARY TABLE temp_History 
            					(
            						id_col int auto_increment primary key		,sessionId varchar(250)	,sessionStartTime bigint	,sessionEndTime bigint	,customerNumber varchar(40)		
                                    ,domainId int default null, dispositionId int default null, IsInBound tinyint default null	,dialDuration bigint default null
                                    ,disconnectedBy bigint default null	,queueDuration bigint default null, calledNumber bigint default null, waitDuration bigint default null
                                    ,recordingTypeId int default null, CustomerId int default null, callDuration bigint default null, createdAt datetime default null,updatedAt datetime default null
                                    ,AgentId bigint default null, QueueId int  default null,channelType VARCHAR(255) default null, CallHistoryId int default null, DurationHistoryId		bigint	,meetingId varchar(50)	
                                    ,name	varchar(255),summary text default null, subject text default null,afterCallWorkTime int default null, SentimentalScore float default null, recordUrl text		
                                    	,recordingSessionId text, Istransferred bigint default null	,transferedBy bigint default null,transferredTo bigint default null	,assignedBy bigint default null	,assignedByName varchar(150) default null								
                                          ,dispositionName varchar(100) default null  ,transferredToName	varchar(150)                                        
                                                                                    
            						

















            					); 
                                
                       
                       
                       drop temporary table if exists tt_recordUrl;
               			create temporary table tt_recordUrl
               			with CTE as (
               				select VR.recordUrl,VH.meetingId,VR.sessionId as recordingSessionId,
               				row_number() over(partition by VR.meetingId order by VR.sessionId desc) as RN
               				from tb_VideoHistory 				VH 
               				join tb_videomeet_user_record_info 	VR ON VH.meetingId = VR.meetingId
               			WHERE VH.domainId = p_domainId
               			)
               			select * from CTE where RN = 1;
                                   
                  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;                                   
                  					insert into temp_History(sessionId,sessionStartTime,sessionEndTime, customerNumber ,domainId, dispositionId, IsInBound
                                    ,dialDuration, disconnectedBy, queueDuration,calledNumber ,waitDuration, recordingTypeId, CustomerId, callDuration, createdAt,updatedAt
                                    ,AgentId, QueueId, channelType,CallHistoryId, DurationHistoryId,meetingId, name, summary, subject, afterCallWorkTime, SentimentalScore
                                    ,recordUrl,recordingSessionId,Istransferred)
                                   
                  					select 	VH.sessionId, VDH.StartTime, VDH.EndTime, VH.customerNumber, VH.domainId, VDH.dispositionId, VH.IsInBound, VH.dialDuration,
                  							VH.disconnectedBy, VH.queueDuration, VH.calledNumber, VH.waitDuration, VH.recordingTypeId, 
                  							VH.CustomerId,VDH.agentDuration + (VDH.afterVideoWorkTime * 1000),VH.createdAt, VDH.updatedAt, VDH.AgentId,    
                  							VDH.QueueId,'Video',VH.VideoHistoryId,
                  							VDH.VideoDurationHistoryId,VH.meetingId,q.name,VDH.summary,VDH.subject,VDH.afterVideoWorkTime,VDH.SentimentalScore,
                                           VR.recordUrl,VR.recordingSessionId, CASE WHEN VDH.transferedTo IS NOT NULL THEN 1 ELSE 0 END
                  					FROM 	tb_VideoHistory 				VH
                  					JOIN 	tb_VideoDurationHistory 		VDH ON VH.VideoHistoryId 	= VDH.VideoHistoryId  								
                                   
                  					LEFT JOIN queue							q	ON VDH.QueueId			= q.qid
              						LEFT JOIN tt_recordUrl 					VR 	ON VR.meetingId			= VH.meetingId
                  					WHERE 	VH.domainId 		= p_domainId
                  					
                                 
                  					
                  					AND 	CAST(VH.updatedAt AS DATE) BETWEEN p_start_timestamp AND p_end_timestamp
                                 
                  					ORDER BY VH.updatedAt desc LIMIT v_offset, p_limit;     
                                      
                  					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                       
                       
                       
                       
					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;    
    CREATE TEMPORARY TABLE temp_customer_contact
	WITH CTE_Customer AS (
		SELECT 	DISTINCT CustomerId
        FROM 	temp_History
    )	
	SELECT 	CC.coid
			,CC.primaryPhoneNumber
			,CC.firstName
			,CC.lastName      
	FROM 	customer_contact 	CC
    JOIN 	CTE_Customer		C	ON C.CustomerId = CC.coid
	WHERE 	CC.domainId = p_domainId;       
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
                                      

								   
	ALTER TABLE temp_History ADD COLUMN CustomerName	VARCHAR(150), ADD COLUMN agentName VARCHAR(150), ADD colorCode VARCHAR(50)
	,ADD COLUMN transferredByName VARCHAR(150);

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; 
	CREATE TEMPORARY TABLE temp_AvailableUser1
	SELECT * FROM temp_AvailableUser;

	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser2; 
	CREATE TEMPORARY TABLE temp_AvailableUser2
	SELECT * FROM temp_AvailableUser;
	  
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser3; 
	CREATE TEMPORARY TABLE temp_AvailableUser3
	SELECT * FROM temp_AvailableUser;      

	 DROP TEMPORARY TABLE IF EXISTS tmp_disposition; 
	CREATE TEMPORARY TABLE tmp_disposition
	  SELECT did 
		,	dispositionName
		,	colorCode
	  FROM 	disposition_status
	  WHERE	domainId	= p_domainId;
	  
	  INSERT INTO tmp_disposition
	  SELECT TypeCodeID		AS did
		,	TypeCodeName	AS dispositionName
		,	Null			AS colorCode
	  FROM 	TypeCode 	
	  WHERE TypeGroupID = 1121;	              

	UPDATE 	temp_History		H
	LEFT JOIN 	temp_AvailableUser	AB	ON H.assignedBy			= AB.UserId        
	LEFT JOIN 	temp_AvailableUser1	ATU	ON H.AgentId			= ATU.UserId        
	LEFT JOIN 	temp_AvailableUser2	TU	ON H.transferredTo    	= TU.UserId	
	LEFT JOIN 	temp_AvailableUser3	TL	ON H.transferedBy    	= TL.UserId	
	LEFT JOIN 	tmp_disposition		DS	ON H.dispositionId		= DS.did
	SET 	H.assignedByName	= AB.UserName 
		,	H.dispositionName	= DS.dispositionName
		,	H.colorCode			= DS.colorCode
		,	H.agentName			= ATU.UserName
		,	H.transferredToName	= TU.UserName
		,   H.transferredByName = TL.UserName
		,	H.CustomerId		= IFNULL(H.CustomerId,0); 

	UPDATE 	temp_History		H
	JOIN 	customer_contact	CC 	ON H.CustomerId = CC.coid 
	SET 	H.CustomerName	= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),ifnull(CC.lastName,''));     

	SELECT 	*
	FROM 	temp_History a 	
	ORDER BY updatedAt DESC;

end ;;
DELIMITER ;
