CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_dynamic_dashboard_whatsapp`(
		p_domainId					INT
		,p_start_timestamp			BIGINT
		,p_end_timestamp			BIGINT
		,p_start_datetime			DATETIME
		,p_end_datetime				DATETIME
 )
BEGIN
			
            DROP TEMPORARY TABLE IF EXISTS tt_dynamic_dashboard_whatsapp;
            CREATE TEMPORARY TABLE tt_dynamic_dashboard_whatsapp
				SELECT	wh.WhatsappHistoryId 	
				   , 	wh.IsInBound
				   ,	IFNULL(wh.isCallback, 0)  													AS isCallback
                   ,	CASE WHEN IFNULL(wdh.dialDuration,0) > 0 THEN 1 ELSE 0 END 					AS InteractionWithin30Secs
                   , 	IFNULL(wdh.Duration, 0)														AS Duration																
                   , 	wdh.IsMissed
            FROM tb_WhatsappHistory  wh JOIN tb_WhatsappDurationHistory wdh	ON wh.WhatsappHistoryId = wdh.WhatsappHistoryId
			WHERE wh.domainId = p_domainId	AND wh.sessionStartTime BETWEEN p_start_timestamp AND p_end_timestamp;

			
            
            
				
			select 
					SUM(IFNULL(IsInBound, 0))													AS 	total_inbound,
					SUM(isCallback)																AS 	callback_request,
                    IFNULL((SUM(InteractionWithin30Secs)/SUM(IsInBound)) * 100,0) 				AS	service_level
                    ,IFNULL(SUM(Duration)/count(WhatsappHistoryId), 0)							AS 	average_speed_of_answer
                    ,SUM(IFNULL(IsMissed, 0))													AS	missed_chat					
                    
            FROM tt_dynamic_dashboard_whatsapp;
            
				
			
			
 END ;;
DELIMITER ;
