	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 	select 	PF.id, PF.channelType, PF.tokenId, PF.storeName, PF.historyId, PF.domainId, PF.isPurchased, PF.productDtl, PF.phoneNumber, PF.companyNumber, PF.errcode, PF.errmsg, PF.createAt 
