CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_email_subscription_check`(
	p_fromEmail	VARCHAR(250)
    ,p_toEmail	VARCHAR(250)
)
begin

	SELECT toEmail as unSubscribedEmail,isUnSubscribed 
