CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_facebook_client_config_v2`(
	p_display_phone_number varchar(100)
)
Begin
	declare v_found 			int ;
	declare v_domainId 			int ;
	declare v_ccaas_domainId 	int ;
    
    select 1,domainId into v_found,v_domainId from ccaas_ai.tb_FacebookClientConfiguration where  whatsappNumber = p_display_phone_number limit 1; 
    
    if v_found is null then
		select 2,domainId into v_found,v_ccaas_domainId from ccaas2023.tb_FacebookClientConfiguration where  whatsappNumber = p_display_phone_number limit 1; 
    End if;
    
    select ifnull(v_found,0) as recfound,IFNULL(v_domainId,v_ccaas_domainId) as domainId;
    
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
