CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_facebook_instagram_client_config_check`(
	p_display_phone_number VARCHAR(100)
    ,p_channelType			VARCHAR(50)
)
Begin
	declare v_found 			int ;
	declare v_domainId 			int ;
	declare v_ccaas_domainId 	int ;
    
    IF p_channelType = 'Facebook'
    THEN
    
		select 1,domainId into v_found,v_domainId from ccaas_ai.tb_FacebookClientConfiguration where  pageId = p_display_phone_number limit 1; 
		
		if v_found is null then
			select 2,domainId into v_found,v_ccaas_domainId from ccaas2023.tb_FacebookClientConfiguration where  pageId = p_display_phone_number limit 1; 
		End if;
		
    ELSEIF p_channelType = 'Instagram'
    THEN
    
		select 1,domainId into v_found,v_domainId from ccaas_ai.tb_FacebookClientConfiguration where  instagramId = p_display_phone_number limit 1; 
		
		if v_found is null then
			select 2,domainId into v_found,v_ccaas_domainId from ccaas2023.tb_FacebookClientConfiguration where  instagramId collate utf8mb4_unicode_ci = p_display_phone_number limit 1; 
		End if;
    
	END IF;
    select ifnull(v_found,0) as recfound,IFNULL(v_domainId,v_ccaas_domainId) as domainId;
    
End ;;
DELIMITER ;
