CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_FIFO_queue`(
	p_ext		INT 
    ,p_domainId	INT
)
begin
		DECLARE v_routing_profile_id INT;

		SELECT routing_profile_id INTO v_routing_profile_id
		FROM tb_User 
		WHERE ext = p_ext AND domainId = p_domainId;

		DROP TEMPORARY TABLE IF EXISTS tt_get_qid;
		CREATE TEMPORARY TABLE tt_get_qid AS
		SELECT qid
		FROM routingqueueprofilemapping 
		WHERE rqmid = v_routing_profile_id
		ORDER BY priority;

		SELECT q.qwtId,q.qid,q.queueName,q.queueType,q.queueList,q.createdAt,q.updatedAt
		FROM queueWeighTime q
		JOIN tt_get_qid t ON q.qid = t.qid;

end ;;
DELIMITER ;
