CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_filter_values_chat_dao`(
p_domainId int,
p_startTmpstmp bigint,
p_endTmpstmp bigint
)
Begin

	if p_endTmpstmp = 0 then
		SELECT DISTINCT queueName, agentName, skillName, callType, dispositionName
        FROM sessionHistory where channelType = 'Chat' AND domainId=p_domainId AND queueName is not NULL  AND agentName is not NULL;
	Else
		SELECT DISTINCT queueName, agentName, skillName, callType, dispositionName
        FROM sessionHistory where sessionStartTime between p_startTmpstmp
        AND p_endTmpstmp AND channelType = 'Chat' AND domainId=p_domainId AND queueName is not NULL  AND agentName is not NULL;
    End if;
	
end ;;
DELIMITER ;
