p_endTmpstmp bigint
)
Begin

	if p_endTmpstmp = 0 then
		SELECT DISTINCT queueName, agentName, skillName, callType, dispositionName,transferredType 
		FROM sessionHistory where channelType='Call' AND domainId = p_domainId;
	Else
		SELECT DISTINCT queueName, agentName, skillName, callType, dispositionName,transferredType
        FROM sessionHistory where sessionStartTime between p_startTmpstmp AND p_endTmpstmp 
        AND channelType='Call' AND domainId = p_domainId;
    End if;
	
end ;;
