CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_find_agent_by_email`(p_qid int, domainId int,emailId varchar(50))
Begin
	declare v_uid int;
    declare v_stateTimer varchar(50);
	SELECT UserID,stateTimer into v_uid,v_stateTimer FROM tb_User WHERE domainId = domainId AND emailId = emailId;
    
    UPDATE tb_User SET statusName = 'Busy', stateTimer = unix_timestamp() where uid = v_uid;
    
    
End ;;
