CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_hours`(
p_qid int
)
Begin


	DECLARE v_hoursOfOperatioId INT;

	SELECT hoursOfOperatioId INTO v_hoursOfOperatioId
    FROM queue WHERE qid = p_qid;


	SELECT JSON_EXTRACT(jt.json_obj, '$') AS hours
		FROM custom_hours,
			 JSON_TABLE(
				 custom_hours.hours,
				 '$[*]' COLUMNS (
					 json_obj JSON PATH '$',
					 day_name VARCHAR(10) PATH '$.day'
				 )
			 ) AS jt
		WHERE jt.day_name = DAYNAME(curdate())
        AND cid = v_hoursOfOperatioId;

    
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
