/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_interaction_details`(	
   		p_domainId 				INT				
   		,p_emailId 				TEXT
   		,p_phoneNumber  		TEXT
   		,p_CustomerId 			VARCHAR(100)
   		,p_customerFacebookId	VARCHAR(100)
   		,p_customerInstagramId	bigint
   		,p_startTmpstmp			BIGINT
   		,p_endTmpstmp			BIGINT
         )
sp_return: Begin
 		DECLARE v_errcode 			INT DEFAULT -1;
 		DECLARE v_errmsg 			VARCHAR(150) DEFAULT 'Failure';
 		DECLARE v_coid 				INT;
 		DECLARE v_startTmpstmp 		BIGINT;
 		DECLARE v_endTmpstmp 		BIGINT;
              
 		DROP TEMPORARY TABLE IF EXISTS temp_email_ids; CREATE TEMPORARY TABLE temp_email_ids (email VARCHAR(255));
 		DROP TEMPORARY TABLE IF EXISTS temp_phnum_ids; CREATE TEMPORARY TABLE temp_phnum_ids (phnum VARCHAR(255));
   
 		SET v_startTmpstmp = IFNULL(p_startTmpstmp,UNIX_TIMESTAMP('2000-01-01')*1000);
 		SET v_endTmpstmp = IFNULL(p_endTmpstmp,UNIX_TIMESTAMP(DATE_ADD(NOW(),INTERVAL 2 DAY))*1000);        
         	
                 
   			if p_emailId is null and (p_customerFacebookId is not null or p_customerInstagramId is not null) 
               then
   				select primaryEmail,GROUP_CONCAT(primaryPhoneNumber,',',replace(replace(REGEXP_REPLACE(phoneNumber, '["]',''),'[',''),']','')),facebook,instagram
   				into p_emailId, p_phoneNumber,p_customerFacebookId,p_customerInstagramId
   				from customer_contact where (facebook = p_customerFacebookId or instagram = p_customerInstagramId) and domainId = p_domainId
   				group by primaryEmail,facebook,instagram;
   			elseIf p_CustomerId is not null and p_emailId is null 
               then
   				select primaryEmail,group_concat(primaryPhoneNumber,',',replace(replace(REGEXP_REPLACE(phoneNumber, '["]',''),'[',''),']','')),facebook, NULLIF(instagram, '')
   				into p_emailId, p_phoneNumber,p_customerFacebookId,p_customerInstagramId from customer_contact where domainId = p_domainId and coid = p_CustomerId
   				group by primaryEmail,facebook,instagram;   
  			else
  				select primaryEmail,group_concat(primaryPhoneNumber,',',replace(replace(REGEXP_REPLACE(phoneNumber, '["]',''),'[',''),']','')),facebook, NULLIF(instagram, '')
   				into p_emailId, p_phoneNumber,p_customerFacebookId,p_customerInstagramId from customer_contact where domainId = p_domainId and coid = p_CustomerId
   				group by primaryEmail,facebook,instagram;   
   			End if;
            
   			call Split(p_emailId,','); INSERT INTO temp_email_ids (email) select TRIM(items) from tt_Split_temptable;
   			call Split(p_phoneNumber,','); INSERT INTO temp_phnum_ids (phnum) select TRIM(items) from tt_Split_temptable;
                  
              	drop temporary table if exists temp_getinteraction_list;
              	create temporary table temp_getinteraction_list
              	(
 				id_col int auto_increment primary key			,customerNumber varchar(50)  default null	,channelType VARCHAR(255) default null	,emailId VARCHAR(255) default null	,dispositionName VARCHAR(255) default null	
              	,dispositionSummary TEXT default null			,sessionStartTime bigint default null		,sessionId varchar(250)	 default null	,EmailHistoryId int default null	,ChatHistoryId int default null				
              	,CallHistoryId int default null					,SMSHistoryId int default null				,WhatsappHistoryId int default null		,colorCode varchar(50) default null	,updatedAt datetime
              	,CustomerId int default null					,ChatDurationHistoryId	BIGINT				,notes json								,AgentId INT						,agentName	varchar(250)
				,RecordingUrl	varchar(500) DEFAULT NULL		,SentimentalScore	float					,Duration	INT
               );

              	if p_emailId is not null and p_emailId <> '' 
                  then 
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 					insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,EmailHistoryId,colorCode,updatedAt,notes,AgentId,agentName,SentimentalScore,Duration)					
 					select 	'Email' channelType,'' customerNumber,eh.FromEmail as emailId,ds.dispositionName as dispositionName,eh.Summary as dispositionSummary,eh.SessionStartTime as sessionStartTime,
 							eh.SessionId as sessionId,eh.EmailHistoryId as historyId,ds.colorCode,eh.updatedAt,n.notes,ed.AgentId,u.UserName,eh.SentimentalScore,ed.Duration
 					from tb_EmailHistory 			eh
 					join tb_EmailDurationHistory 	ed on eh.EmailHistoryId = ed.EmailHistoryId and IsBot=0         				
 					join disposition_status			ds on eh.DispositionId	= ds.did
 					left join tb_interaction_notes_info n on n.historyId  = eh.EmailHistoryId
 					left join tb_User				u on u.UserID = ed.AgentId
 					where 	eh.domainId = p_domainId 
 					AND 	((eh.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null))
 					
 					and 	EXISTS (SELECT 1 FROM temp_email_ids WHERE FromEmail collate utf8mb4_unicode_ci = email);    		
              		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
              	End if;

          		IF (p_CustomerId is not null AND p_CustomerId <> '')
          		then
                    insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,CustomerId,ChatDurationHistoryId,notes,AgentId,agentName,SentimentalScore,Duration)
              		select  'Chat' channelType,cth.AssignedTo customerNumber,'' emailId,ds.dispositionName as dispositionName,ctdh.Summary as dispositionSummary,
              				cth.SessionStartTime as sessionStartTime,cth.SessionId as sessionId,cth.ChatHistoryId as historyId,ds.colorCode ,cth.updatedAt,cth.CustomerId,ctdh.ChatDurationHistoryId,n.notes
                           ,ctdh.AgentId,u.UserName,ctdh.SentimentalScore,ctdh.Duration
              		from tb_ChatHistory 			cth
              		join tb_ChatDurationHistory 	ctdh 	ON cth.ChatHistoryId	= ctdh.ChatHistoryId and IsBot = 0						
              		join disposition_status			ds 		ON ctdh.DispositionId	= ds.did
                   left join tb_interaction_notes_info n 	ON n.historyId  		= cth.ChatHistoryId
                   left join tb_User				u 		ON u.UserID 			= ctdh.AgentId
              	 where 	cth.domainId = p_domainId    
                  AND 	((cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp ) or (v_startTmpstmp is null or v_endTmpstmp is null))
                  
          			and		cth.CustomerId = p_CustomerId;         
          		ELSE 
          		if (p_phoneNumber is not null and p_phoneNumber <> '') or (p_emailId is not null and p_emailId <> '') 
              	THEN      						
              		DROP TEMPORARY TABLE IF EXISTS temp_CustomerContact; 
              		CREATE TEMPORARY TABLE temp_CustomerContact (CustomerId INT);
              
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
              		INSERT INTO temp_CustomerContact(CustomerId)
              		select 	CC.coid
              		from 	customer_contact CC 
              		where 	(	(IFNULL(p_phoneNumber,'') <> '' AND (CC.primaryPhoneNumber LIKE p_phoneNumber OR CC.primaryPhoneNumber like CONCAT('%', p_phoneNumber, '%')))								
          				OR 		(IFNULL(p_emailId,'') <> '' 	AND (CC.primaryEmail LIKE p_emailId OR CC.email LIKE CONCAT('%', p_emailId, '%'))))
              		AND 	CC.domainId = p_domainId;                                                
              
              		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,ChatDurationHistoryId,colorCode,updatedAt,CustomerId,notes,AgentId,agentName,SentimentalScore,Duration)
              		select  'Chat' channelType,cth.AssignedTo customerNumber,'' emailId,ds.dispositionName as dispositionName,ctdh.Summary as dispositionSummary,
              				cth.SessionStartTime as sessionStartTime,cth.SessionId as sessionId,cth.ChatHistoryId as historyId, ctdh.ChatDurationHistoryId,ds.colorCode ,cth.updatedAt,cth.CustomerId,n.notes
                           ,ctdh.AgentId,u.UserName,ctdh.SentimentalScore,ctdh.Duration
              		from tb_ChatHistory 			cth
              		join tb_ChatDurationHistory 	ctdh 	ON cth.ChatHistoryId	= ctdh.ChatHistoryId and IsBot = 0						
              		JOIN temp_CustomerContact		CC		ON CC.CustomerId		= cth.CustomerId
              		join disposition_status			ds 		ON ctdh.DispositionId	= ds.did
 					left join tb_interaction_notes_info n 	ON n.historyId  		= cth.ChatHistoryId
 					left join tb_User				u 		ON u.UserID 			= ctdh.AgentId
              		where 	cth.domainId = p_domainId
 					AND 	((cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null));
 					
          		end if;
          	  end if;
            		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 

            		if p_phoneNumber is not null and p_phoneNumber <> 0 
            		then
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
              		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,notes,AgentId,agentName, RecordingUrl,SentimentalScore,Duration)
              		select  'Call' channelType,clh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,cld.Summary as dispositionSummary,
              				clh.SessionStartTime as sessionStartTime,clh.SessionId as sessionId,clh.CallHistoryId as historyId,ds.colorCode ,clh.updatedAt,n.notes
                           ,cld.AgentId,u.UserName, cld.RecordingUrl,cld.SentimentalScore,cld.Duration
              		from tb_CallHistory 			clh
              		join tb_CallDurationHistory 	cld 	ON clh.CallHistoryId 		= cld.CallHistoryId and IsBot=0         				
              		join disposition_status			ds 		ON cld.DispositionId		= ds.did
                   left join tb_interaction_notes_info n 	ON n.historyId  			= clh.CallHistoryId
                   left join tb_User				u 		ON u.UserID 				= cld.AgentId
 				  where 	clh.domainId = p_domainId 
 				  AND 	((clh.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null))
 					
 					AND  	EXISTS (SELECT phnum FROM temp_phnum_ids where clh.customerNumber collate utf8mb4_unicode_ci = phnum);    		 
          			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     	 
              	End if;
                         
              	if p_phoneNumber is not null and p_phoneNumber <> 0 
                  then
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
              		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,notes,AgentId,agentName,SentimentalScore,Duration)
              		select  'Sms' channelType,sh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,sh.Summary as dispositionSummary,
              		sh.SessionStartTime as sessionStartTime,sh.SessionId as sessionId,sh.SMSHistoryId as historyId,ds.colorCode ,sh.updatedAt,n.notes
 					,sd.AgentId,u.UserName,sh.SentimentalScore,sd.Duration
              		from tb_SMSHistory 					sh
              		join tb_SMSDurationHistory 			sd 		ON sh.SMSHistoryId 	= sd.SMSHistoryId and IsBot=0          				
              		join disposition_status				ds 		ON sh.DispositionId	= ds.did
                   left join tb_interaction_notes_info n 		ON n.historyId  	= sh.SMSHistoryId
                   left join tb_User					u 		ON u.UserID 		= sd.AgentId
 				  where sh.domainId = p_domainId
                   AND 	((sh.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null))
 					
 					AND 	EXISTS (SELECT phnum FROM temp_phnum_ids WHERE sh.customerNumber collate utf8mb4_unicode_ci = phnum);            
 					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     	
 				End if;
                         
              	if p_phoneNumber is not null and p_phoneNumber <> 0 
                  then  
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
              		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,notes,AgentId,agentName,SentimentalScore,Duration)
              		select  'Whatsapp' channelType,wh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,wh.Summary as dispositionSummary,
              		 wh.SessionStartTime as sessionStartTime,wh.SessionId as sessionId,wh.WhatsappHistoryId as historyId,ds.colorCode ,wh.updatedAt,n.notes
  					,wd.AgentId,u.UserName,wh.SentimentalScore,wd.Duration
  					from tb_WhatsappHistory 			wh
  					join tb_WhatsappDurationHistory 	wd ON wh.WhatsappHistoryId 	= wd.WhatsappHistoryId 
  					join disposition_status				ds ON wh.DispositionId		= ds.did
  					left join tb_interaction_notes_info n  ON n.historyId  			= wh.WhatsappHistoryId
  					left join tb_User					u 	ON u.UserID 			= wd.AgentId
  					where 	wh.domainId = p_domainId
  					AND 	((wh.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null))
  					
  					and 	EXISTS (SELECT 1 FROM temp_phnum_ids where wh.customerNumber collate utf8mb4_unicode_ci = phnum);    		 		
  					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     	
  					End if;
 
              	 
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
              		 insert into temp_getinteraction_list
          			 (channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,notes,AgentId,agentName,SentimentalScore,Duration)
              		select  'Facebook' channelType,IH.customerFacebookId customerNumber,'' emailId,ds.dispositionName as dispositionName,IH.Summary as dispositionSummary,
              		IH.SessionStartTime as sessionStartTime,IH.SessionId as sessionId,IH.FacebookHistoryId as historyId,ds.colorCode ,IH.updatedAt,n.notes
                      ,IH.AgentId,u.UserName,IH.SentimentalScore,IH.Duration
  					from tb_FacebookHistory 			IH 
  					join disposition_status				ds 	ON 	IH.DispositionId	= ds.did
  					left join customer_contact			CC 	ON 	CC.domainId			= IH.domainId
 															AND CC.facebook collate utf8mb4_0900_ai_ci = IH.customerFacebookId 
  					left join tb_interaction_notes_info n  	ON 	n.historyId  		= IH.FacebookHistoryId
  					left join tb_User					u 	ON 	u.UserID 			= IH.AgentId
  					where 	IH.domainId = p_domainId and (primaryEmail collate utf8mb4_0900_ai_ci in (select M.email from temp_email_ids M) or ifnull(p_emailId,'') collate utf8mb4_0900_ai_ci  ='')
  					 AND  	(IH.customerFacebookId collate utf8mb4_0900_ai_ci = p_customerFacebookId or ifnull(p_customerFacebookId,0)=0)
  					 AND 	((IH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null))
  					AND 	CC.facebook IS NOT NULL
                    AND		CC.coid = p_CustomerId 
  					AND 	((CC.primaryPhoneNumber collate utf8mb4_0900_ai_ci in (select N.phnum from temp_phnum_ids N) OR IFNULL(p_phoneNumber,'')='') or (replace(replace(REGEXP_REPLACE(CC.phoneNumber, '["]',''),'[',''),']',''))); 
              		 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     	
              	                  
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
              		insert into temp_getinteraction_list
          			(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,notes,AgentId,agentName,SentimentalScore,Duration)
  					select  'Instagram' channelType,IH.customerInstagramId customerNumber,'' emailId,ds.dispositionName as dispositionName,IH.Summary as dispositionSummary,
  					IH.SessionStartTime as sessionStartTime,IH.SessionId as sessionId,IH.InstagramHistoryId as historyId,ds.colorCode ,IH.updatedAt,n.notes
  					,IH.AgentId,u.UserName,IH.SentimentalScore,IH.Duration
  					from 	tb_InstagramHistory 	IH 
  					join 	disposition_status		ds 		ON IH.DispositionId			= ds.did
  					left join 	customer_contact	CC 		ON 	CC.domainId				= IH.domainId
 															AND CC.instagram 			= IH.customerInstagramId 
  					left join tb_interaction_notes_info n  	ON n.historyId  			= IH.InstagramHistoryId
  					left join tb_User					u 	ON u.UserID 				= IH.AgentId
  					where 	IH.domainId = p_domainId  and (primaryEmail collate utf8mb4_0900_ai_ci in (p_emailId) or ifnull(p_emailId,'')='')
  					AND  	(IH.customerInstagramId = p_customerInstagramId or ifnull(p_customerInstagramId,0)=0)
  					AND 	((IH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp) or (v_startTmpstmp is null or v_endTmpstmp is null))
 					
  					and CC.instagram is not null
                    AND		CC.coid = p_CustomerId 
					
                    AND 	((CC.primaryPhoneNumber collate utf8mb4_0900_ai_ci in (select N.phnum from temp_phnum_ids N) OR IFNULL(p_phoneNumber,'')='') or (replace(replace(REGEXP_REPLACE(CC.phoneNumber, '["]',''),'[',''),']',''))); 
          
              		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     	
              	 
 
 				select 	id_col, customerNumber ,channelType,emailId as FromEmail,dispositionName,dispositionSummary
 					,sessionStartTime,sessionId,EmailHistoryId ,ChatHistoryId,ChatDurationHistoryId 
 					,CallHistoryId,SMSHistoryId ,WhatsappHistoryId ,colorCode ,updatedAt,CustomerId,notes,AgentId,agentName, RecordingUrl,SentimentalScore,Duration
 				from temp_getinteraction_list
 				order by updatedAt desc; 
              
              SELECT DISTINCT(dispositionName) AS dispositionName FROM disposition_status WHERE domainId = p_domainId;
              
          End ;;
DELIMITER ;
