CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_interaction_details1`(
        p_domainId int
        ,p_emailId text
        ,p_phoneNumber  text
        
        )
Begin 
        
        		declare v_errcode int default -1;
        		declare v_errmsg varchar(150) default 'Failure';
                declare v_CustomerId int ;
                
				SELECT CustomerId into v_CustomerId
				FROM tb_ChatHistory   CH 
				JOIN customer_contact CC 
				ON CC.coid = CH.CustomerId
				WHERE 	phoneNumber LIKE CONCAT('%', p_phoneNumber, '%') 
				OR  	email 		LIKE CONCAT('%', p_emailId, '%')
				AND (IFNULL(p_phoneNumber,'') 	= null OR (IFNULL(p_phoneNumber,'') <> '') OR p_phoneNumber IS NOT NULL)
				AND (IFNULL(p_emailId,'') 		= null OR (IFNULL(p_emailId,'') <> '')OR p_emailId IS NOT NULL) LIMIT 1;
              
  			DROP TEMPORARY TABLE IF EXISTS temp_email_ids; CREATE TEMPORARY TABLE temp_email_ids (email VARCHAR(255));
              DROP TEMPORARY TABLE IF EXISTS temp_phnum_ids; CREATE TEMPORARY TABLE temp_phnum_ids (phnum VARCHAR(255));
              
              call Split(p_emailId,','); INSERT INTO temp_email_ids (email) select items from tt_Split_temptable;
              call Split(p_phoneNumber,','); INSERT INTO temp_phnum_ids (phnum) select items from tt_Split_temptable;
            
     				drop temporary table if exists temp_getinteraction_list;
              		create temporary table temp_getinteraction_list
              		(
   					id_col int auto_increment primary key			,customerNumber varchar(50)  default null	,channelType VARCHAR(255) default null	,emailId VARCHAR(255) default null	,dispositionName VARCHAR(255) default null	
					,dispositionSummary VARCHAR(255) default null	,sessionStartTime bigint default null		,sessionId varchar(250)	 default null	,EmailHistoryId int default null	,ChatHistoryId int default null				
       				,CallHistoryId int default null					,SMSHistoryId int default null				,WhatsappHistoryId int default null		,colorCode varchar(50) default null	,updatedAt datetime
                    ,CustomerId int default null
                    
              		);
         
              		if p_emailId is not null and p_emailId <> '' then 
        				insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,EmailHistoryId,colorCode,updatedAt)
 		
        				select 'Email' channelType,'' customerNumber,eh.FromEmail as emailId,ds.dispositionName as dispositionName,eh.Summary as dispositionSummary,
        						eh.SessionStartTime as sessionStartTime,eh.SessionId as sessionId,eh.EmailHistoryId as historyId,ds.colorCode,eh.updatedAt
        				from tb_EmailHistory 				eh
        				left join tb_EmailDurationHistory 	ed on eh.EmailHistoryId = ed.EmailHistoryId and IsBot=0
        				left join tb_EmailMessage			em on eh.EmailHistoryId = em.EmailHistoryId
        				left join disposition_status		ds on eh.DispositionId	=  ds.did
        				where eh.domainId = p_domainId 
                      and FromEmail collate utf8mb4_unicode_ci IN (SELECT email FROM temp_email_ids); 
        			End if;
                  
  
     
        			if (p_phoneNumber is not null and p_phoneNumber <> '') or (p_emailId is not null and p_emailId <> '') then      
        				insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt,CustomerId)
        				select  'Chat' channelType,cth.AssignedTo customerNumber,'' emailId,ds.dispositionName as dispositionName,cth.Summary as dispositionSummary,
        						cth.SessionStartTime as sessionStartTime,cth.SessionId as sessionId,cth.ChatHistoryId as historyId,ds.colorCode ,cth.updatedAt,cth.CustomerId
						from tb_ChatHistory 			cth
        				join tb_ChatDurationHistory 	ctdh on cth.ChatHistoryId	= ctdh.ChatHistoryId and IsBot=0
        				join tb_ChatMessage				ctm on cth.ChatHistoryId 	= ctm.ChatHistoryId
        				left join disposition_status	ds on cth.DispositionId		= ds.did
						WHERE cth.domainId = p_domainId AND cth.CustomerId = v_CustomerId;
                            

                            
   			END IF;
     
                    if p_phoneNumber is not null and p_phoneNumber <> 0 then      
        				insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt)
        				select  'Call' channelType,clh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,clh.Summary as dispositionSummary,
        						clh.SessionStartTime as sessionStartTime,clh.SessionId as sessionId,clh.CallHistoryId as historyId,ds.colorCode ,clh.updatedAt
        				from tb_CallHistory 			clh
        				join tb_CallDurationHistory 	cld on clh.CallHistoryId 	= cld.CallHistoryId and IsBot=0
        				join tb_CallMessage				clm on clh.CallHistoryId 	= clm.CallHistoryId
        				left join disposition_status	ds on clh.DispositionId		= ds.did
        				where clh.domainId = p_domainId and clh.customerNumber collate utf8mb4_unicode_ci in (SELECT phnum FROM temp_phnum_ids);
                      
        			End if;
                    
                     if p_phoneNumber is not null and p_phoneNumber <> 0 then      
        				insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt)
        				select  'Sms' channelType,sh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,sh.Summary as dispositionSummary,
        						sh.SessionStartTime as sessionStartTime,sh.SessionId as sessionId,sh.SMSHistoryId as historyId,ds.colorCode ,sh.updatedAt
        				from tb_SMSHistory 					sh
         				left join tb_SMSDurationHistory 	sd on sh.SMSHistoryId 	= sd.SMSHistoryId and IsBot=0
         				join tb_SMSMessage					sm on sh.SMSHistoryId 	= sm.SMSHistoryId
        				left join disposition_status		ds on sh.DispositionId	= ds.did
        				where sh.domainId = p_domainId and sh.customerNumber collate utf8mb4_unicode_ci in (SELECT phnum FROM temp_phnum_ids);
  	
                      
        			End if;
                    
                     if p_phoneNumber is not null and p_phoneNumber <> 0 then      
        				insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,colorCode,updatedAt)
        				select  'Whatsapp' channelType,wh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,wh.Summary as dispositionSummary,
        						wh.SessionStartTime as sessionStartTime,wh.SessionId as sessionId,wh.WhatsappHistoryId as historyId,ds.colorCode ,wh.updatedAt
        				from tb_WhatsappHistory 				wh
         				left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId 	= wd.WhatsappHistoryId and IsBot=0
         				join tb_WhatsappMessage					wm on wh.WhatsappHistoryId 	= wm.WhatsappHistoryId
        				left join disposition_status			ds on wh.DispositionId		= ds.did
        				where wh.domainId = p_domainId and wh.customerNumber collate utf8mb4_unicode_ci in (SELECT phnum FROM temp_phnum_ids);
                      
        			End if;
        	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;            
        			select * from temp_getinteraction_list
                   order by updatedAt desc;        
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 

        End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_interaction_details_view` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_interaction_details_view`( 
   	p_domainId 					INT
   	,p_emailId 					TEXT
   	,p_phoneNumber  			TEXT
    ,p_CustomerId 				VARCHAR(100)
   	,p_customerFacebookId		VARCHAR(100)
   	,p_customerInstagramId		BIGINT
   	,p_interactionId 			int
	,p_TicketId					BIGINT
    )
sp_return:Begin      
                      	declare v_errcode int default -1;
                      	declare v_errmsg varchar(150) default 'Failure';
                        declare v_customerInstagramId varchar(100);
                        
                        set v_customerInstagramId = p_customerInstagramId;
                      
                      	DROP TEMPORARY TABLE IF EXISTS temp_email_ids; CREATE TEMPORARY TABLE temp_email_ids (email VARCHAR(255));
                      	DROP TEMPORARY TABLE IF EXISTS temp_phnum_ids; CREATE TEMPORARY TABLE temp_phnum_ids (phnum VARCHAR(255));
                                           
        				if p_emailId is null and (p_customerFacebookId is not null or v_customerInstagramId is not null) then
        					select primaryEmail,group_concat(primaryPhoneNumber,',',replace(replace(REGEXP_REPLACE(phoneNumber, '["]',''),'[',''),']','')),
      							facebook,instagram
                            into p_emailId, p_phoneNumber,p_customerFacebookId,v_customerInstagramId
                            from customer_contact where (facebook collate utf8mb4_0900_ai_ci = p_customerFacebookId 
															or instagram collate utf8mb4_0900_ai_ci = v_customerInstagramId) and domainId = p_domainId
                            group by primaryEmail,facebook,instagram;
  
        				 elseIf p_CustomerId is not null and p_emailId is null then
        					select primaryEmail,group_concat(primaryPhoneNumber,',',replace(replace(REGEXP_REPLACE(phoneNumber, '["]',''),'[',''),']','')),
      							facebook,instagram
                            into p_emailId, p_phoneNumber,p_customerFacebookId,v_customerInstagramId from customer_contact 
                            where domainId = p_domainId and coid  = p_CustomerId
                            group by primaryEmail,facebook,instagram;
   
						Else
                            select primaryEmail,group_concat(primaryPhoneNumber,',',replace(replace(REGEXP_REPLACE(phoneNumber, '["]',''),'[',''),']','')),
      							facebook,instagram
                            into p_emailId, p_phoneNumber,p_customerFacebookId,v_customerInstagramId from customer_contact 
                            where domainId = p_domainId and coid = p_CustomerId
                            group by primaryEmail,facebook,instagram;
 
        				End if;
                        
                        call Split(p_emailId,','); INSERT INTO temp_email_ids (email) select TRIM(items) from tt_Split_temptable;
                        call Split(p_phoneNumber,','); INSERT INTO temp_phnum_ids (phnum) select TRIM(items) from tt_Split_temptable;

                      	drop temporary table if exists temp_getinteraction_list;
                      	create temporary table temp_getinteraction_list
                      	(	id_col int auto_increment primary key			,customerNumber varchar(50)  default null	,channelType VARCHAR(255) default null	,emailId VARCHAR(255) default null			,dispositionName VARCHAR(255) default null	
                      		,dispositionSummary TEXT default null			,sessionStartTime bigint default null		,sessionId varchar(250)	 default null	,EmailHistoryId int default null			,ChatHistoryId int default null				
                      		,CallHistoryId int default null					,SMSHistoryId int default null				,WhatsappHistoryId int default null		,colorCode varchar(50) default null			,updatedAt datetime
                      		,CustomerId int default null					,Message	json default null				,UserName	varchar(255) default null	,AssignedTo	bigint default null				,IsBot	INT
                      		,dispositionUpdatedBy	varchar(100)			,InstagramHistoryId	int default null		,FacebookHistoryId	int default null	,ChatDurationHistoryId int default null		,AgentName varchar(500)
              				,transferedBy   VARCHAR(255) default null		,transferedTo VARCHAR(255) default null		,videoSessionDtl	JSON				,SentimentalScore	float					,Tags	json
                      	); 
            
                      	if p_emailId is not null and p_emailId <> '' 
                          then 
                      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                      		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,EmailHistoryId,colorCode,updatedAt,Message,UserName,AssignedTo,IsBot,dispositionUpdatedBy,AgentName,SentimentalScore,Tags)					
                      		select 'Email' channelType,'' customerNumber,eh.FromEmail as emailId,ds.dispositionName as dispositionName,eh.Summary as dispositionSummary,
                      				eh.SessionStartTime as sessionStartTime,eh.SessionId as sessionId,eh.EmailHistoryId as historyId,ds.colorCode,eh.updatedAt,em.Message,u.UserName,eh.AssignedTo,ed.IsBot
                                      ,ifnull(au.UserName,'') as dispositionUpdatedBy,ua.UserName as agentName,eh.SentimentalScore, eh.tags
                      		from tb_EmailHistory 				eh 
                      		left join tb_EmailDurationHistory 	ed on eh.EmailHistoryId = ed.EmailHistoryId
                      		join tb_EmailMessage				em on em.EmailHistoryId = eh.EmailHistoryId
                      		left join tb_User 					u  on u.UserID			= eh.AssignedTo
                      		left join tb_User					au on au.UserID			= eh.dispositionUpdatedBy	
              				left join tb_User 					ua on ua.UserID			= ed.AgentId
                      		left join disposition_status		ds on eh.DispositionId	=  ds.did
                      		where eh.domainId = p_domainId
                      		
                      		and FromEmail collate utf8mb4_unicode_ci IN (SELECT email FROM temp_email_ids)
                             AND eh.EmailHistoryId = p_interactionId; 
                      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                      	End if;        
                                            
                        	if (p_phoneNumber is not null and p_phoneNumber <> '') or (p_emailId is not null and p_emailId <> '') 
                      	THEN      						
                      		DROP TEMPORARY TABLE IF EXISTS temp_CustomerContact; 
                      		CREATE TEMPORARY TABLE temp_CustomerContact (CustomerId INT);
                      
                      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                        		INSERT INTO temp_CustomerContact(CustomerId)
                        		select 	CC.coid
                        		from 	customer_contact CC 
                        		where 	(	(IFNULL(p_phoneNumber,'') <> '' AND (CC.primaryPhoneNumber collate utf8mb4_0900_ai_ci LIKE p_phoneNumber OR CC.primaryPhoneNumber collate utf8mb4_0900_ai_ci like CONCAT('%', p_phoneNumber, '%')))								
                    				OR 		(IFNULL(p_emailId,'') <> '' 	AND (CC.primaryEmail collate utf8mb4_0900_ai_ci LIKE p_emailId OR CC.email collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_emailId, '%'))))
                        		AND 	CC.domainId = p_domainId
                             GROUP BY CC.coid;             
                      
                   		INSERT INTO temp_getinteraction_list
                           (channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,ChatDurationHistoryId
                              ,colorCode,updatedAt,CustomerId,Message,IsBot,AssignedTo,AgentName,SentimentalScore,Tags)
                      		select  'Chat' channelType,cth.AssignedTo customerNumber,'' emailId,ds.dispositionName as dispositionName,ctdh.Summary as dispositionSummary,
                      		cth.SessionStartTime as sessionStartTime,cth.SessionId as sessionId,cth.ChatHistoryId as historyId,ctdh.ChatDurationHistoryId,ds.colorCode ,cth.updatedAt,cth.CustomerId,cl.Message,ctdh.IsBot,cth.assignedTo
              				,ua.UserName as agentName,ctdh.SentimentalScore,ctdh.tags
                      		from tb_ChatHistory 			cth 
                      		join tb_ChatDurationHistory 	ctdh on cth.ChatHistoryId	= ctdh.ChatHistoryId
                      		join tb_ChatMessage				cl	on	cl.ChatDurationHistoryId	= ctdh.ChatDurationHistoryId
                      		left join tb_User 				u   on u.UserID				= cth.assignedTo
							left join tb_User 				ua  on ua.UserID			= ctdh.AgentId
                      		JOIN temp_CustomerContact	CC	on CC.CustomerId		= cth.CustomerId
                      		left join disposition_status	ds 	on ctdh.DispositionId	= ds.did  
                      		where cth.domainId = p_domainId
                             AND cth.ChatHistoryId = p_interactionId; 
                      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                      	End if;
                              
                     	if (p_phoneNumber is null or p_phoneNumber = '') OR (p_emailId is null or p_emailId = '') 
                      	THEN      						                                               
                              SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;                    
                      		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,ChatHistoryId,ChatDurationHistoryId
                  												,colorCode,updatedAt,CustomerId,Message,IsBot,AssignedTo,AgentName,SentimentalScore,Tags)
                      		select  'Chat' channelType,cth.AssignedTo customerNumber,'' emailId,ds.dispositionName as dispositionName,ctdh.Summary as dispositionSummary,
                      				cth.SessionStartTime as sessionStartTime,cth.SessionId as sessionId,cth.ChatHistoryId as historyId,ctdh.ChatDurationHistoryId,ds.colorCode ,cth.updatedAt,cth.CustomerId,cl.Message,ctdh.IsBot,cth.assignedTo
                                   ,ua.UserName as agentName,ctdh.SentimentalScore,ctdh.tags
                      		from tb_ChatHistory 			cth 
                      		join tb_ChatDurationHistory 	ctdh 	on cth.ChatHistoryId			= ctdh.ChatHistoryId
                      		join tb_ChatMessage				cl		on	cl.ChatDurationHistoryId	= ctdh.ChatDurationHistoryId
                      		left join tb_User 				u   	on 	u.UserID					= cth.assignedTo
                             left join tb_User 				ua  	on ua.UserID					= ctdh.AgentId
                      		left join disposition_status	ds 		on ctdh.DispositionId			= ds.did  
                      		where 	cth.domainId 	= p_domainId
                      		and   	cth.CustomerId 	= p_CustomerId	
                             AND 	cth.ChatHistoryId = p_interactionId; 
                      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                      	End if; 
    
                      	if p_phoneNumber is not null and p_phoneNumber <> 0 
                          then  
                      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                      		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,CallHistoryId,colorCode,updatedAt,Message,IsBot,AssignedTo,AgentName,transferedBy, transferedTo,SentimentalScore,Tags)
                      		select  'Call' channelType,clh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,cld.Summary as dispositionSummary,
                      				clh.SessionStartTime as sessionStartTime,clh.SessionId as sessionId,clh.CallHistoryId as historyId,ds.colorCode ,clh.updatedAt,cm.Message,clh.assignedTo,cld.IsBot
                                   ,ua.UserName as agentName
                                   ,ut.UserName  as transferedBy
                                   ,uto.UserName as transferedTo
                                   ,cld.SentimentalScore
                                   ,cld.tags
							from tb_CallHistory 			clh
							join tb_CallDurationHistory 	cld on clh.CallHistoryId 			= cld.CallHistoryId 
							left join tb_CallMessage		cm	on cm.CallDurationHistoryId		= cld.CallDurationHistoryId 
							left join tb_User 				u   on u.UserID						= clh.assignedTo
							left join tb_User 				ua  on ua.UserID					= cld.AgentId
							left Join tb_User 				ut  on ut.UserID					= cld.transferedBy
							left Join tb_User 				uto on uto.UserID					= cld.transferedTo                
							left join disposition_status	ds on cld.DispositionId				= ds.did
                            LEFT JOIN temp_phnum_ids 		ph ON ph.phnum						= clh.customerNumber
							where 	clh.domainId = p_domainId 
							AND 	clh.CallHistoryId = p_interactionId;
                      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 

                      	End if;
                                         
                          if p_phoneNumber is not null and p_phoneNumber <> 0 
                          then      
                      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                      		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,CallHistoryId,colorCode,updatedAt,Message,IsBot,AssignedTo,AgentName,transferedBy, transferedTo,videoSessionDtl,SentimentalScore)
         					SELECT DISTINCT    'Video' AS channelType,    clh.customerNumber AS customerNumber,    '' AS emailId,    ds.dispositionName AS dispositionName,
         					cld.summary AS dispositionSummary,    clh.sessionStartTime AS sessionStartTime,    clh.sessionId AS sessionId,    clh.VideoHistoryId AS historyId,
         					ds.colorCode,    clh.updatedAt,    cm.Message,    NULL,    NULL,    ua.UserName AS agentName,    NULL AS transferedBy,    NULL AS transferedTo
                             ,(
         					SELECT DISTINCT JSON_ARRAYAGG(JSON_OBJECT("sessionId", ur.sessionId, "recordUrl", ur.recordUrl))
         					FROM tb_VideoHistory vh
         					JOIN tb_videomeet_user_record_info ur ON ur.meetingId = vh.meetingId AND ur.domainId = vh.domainId
         					WHERE vh.VideoHistoryId = clh.VideoHistoryId
         					) AS videoSessionDtl
                            ,cld.SentimentalScore
         					FROM    tb_VideoHistory clh
         					JOIN    tb_VideoDurationHistory cld ON clh.VideoHistoryId = cld.VideoHistoryId
         					LEFT JOIN    tb_VideoMessage cm ON cm.VideoHistoryId = clh.VideoHistoryId
         					LEFT JOIN    tb_videomeet_user_record_info ur ON ur.meetingId collate utf8mb4_0900_ai_ci = clh.meetingId
         					LEFT JOIN    tb_User ua ON ua.UserID = cld.AgentId
         					LEFT JOIN    disposition_status ds ON cld.dispositionId = ds.did
         					WHERE    	clh.domainId = p_domainId
         					AND clh.customerNumber COLLATE utf8mb4_unicode_ci IN (SELECT phnum FROM temp_phnum_ids)
                             AND 	clh.VideoHistoryId = p_interactionId;
                      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                      	
                      	End if;
                                              
                      	if p_phoneNumber is not null and p_phoneNumber <> 0 then
                      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                      		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,SMSHistoryId,colorCode,updatedAt,Message,assignedTo,UserName,IsBot,dispositionUpdatedBy,AgentName,SentimentalScore,Tags)
                      		select  'Sms' channelType,sh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,sh.Summary as dispositionSummary,
                      		sh.SessionStartTime as sessionStartTime,sh.SessionId as sessionId,sh.SMSHistoryId as historyId,ds.colorCode ,sh.updatedAt,sm.Message,sh.assignedTo,u.UserName,sd.IsBot,ifnull(au.UserName,'') as dispositionUpdatedBy
                           ,ua.UserName as agentName,sh.SentimentalScore,sh.tags
                      		from tb_SMSHistory 					sh
                      		left join tb_SMSDurationHistory 	sd on sh.SMSHistoryId 	= sd.SMSHistoryId    
                      		join tb_SMSMessage					sm on sm.SMSHistoryId	= sh.SMSHistoryId 
                      		left join tb_User 					u  on u.UserID			= sh.assignedTo
                      		left join tb_User 					au on au.UserID			= sh.dispositionUpdatedBy
                           left join tb_User 					ua  on ua.UserID		= sd.AgentId
                      		left join disposition_status		ds on sh.DispositionId	= ds.did
                      		where 	sh.domainId = p_domainId 
                      		and 	EXISTS (SELECT 1 FROM temp_phnum_ids WHERE sh.customerNumber collate utf8mb4_unicode_ci = phnum)
                      		
                             AND 	sh.SMSHistoryId = p_interactionId;
                      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 

                      	End if;
                                              
                     	  if p_phoneNumber is not null and p_phoneNumber <> 0 then  
                     	   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                     		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,WhatsappHistoryId,colorCode,updatedAt,Message,assignedTo,UserName,IsBot,dispositionUpdatedBy,AgentName,SentimentalScore,Tags)
                     		select  'Whatsapp' channelType,wh.customerNumber customerNumber,'' emailId,ds.dispositionName as dispositionName,wh.Summary as dispositionSummary,
                     				 wh.SessionStartTime as sessionStartTime,wh.SessionId as sessionId,wh.WhatsappHistoryId as historyId,ds.colorCode ,wh.updatedAt,wm.Message,wh.assignedTo,u.UserName,wd.IsBot,ifnull(au.UserName,'') as dispositionUpdatedBy
                                   ,ua.UserName as agentName,wh.SentimentalScore,wh.tags
                     		from tb_WhatsappHistory 				wh
                     		left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId 	= wd.WhatsappHistoryId
                     		join tb_WhatsappMessage					wm on wm.WhatsappHistoryId	= wh.WhatsappHistoryId 
                     	    left join tb_User 						u  on u.UserID				= wh.assignedTo 
                     	    left join tb_User 						au on au.UserID				= wh.dispositionUpdatedBy	
                           left join tb_User 						ua on ua.UserID				= wd.AgentId
                     		left join disposition_status			ds on wh.DispositionId		= ds.did
                     		where 	wh.domainId = p_domainId 
                     		 and 	EXISTS (SELECT 1 FROM temp_phnum_ids WHERE wh.customerNumber collate utf8mb4_unicode_ci = phnum)
                     		
                              AND 	wh.WhatsappHistoryId = p_interactionId;
                     	   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                     	   
                     	End if;

                     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                     		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,InstagramHistoryId,colorCode,updatedAt,Message,assignedTo,UserName,IsBot,dispositionUpdatedBy,AgentName,SentimentalScore,Tags)
                     		select  'Instagram' channelType,wh.customerInstagramId as customerNumber,'' emailId,ds.dispositionName as dispositionName,wh.Summary as dispositionSummary,
                     				 wh.SessionStartTime as sessionStartTime,wh.SessionId as sessionId,wh.InstagramHistoryId as historyId,ds.colorCode ,wh.updatedAt,wm.Message,wh.assignedTo,u.UserName,wh.IsBot,ifnull(au.UserName,'') as dispositionUpdatedBy
                                   ,ua.UserName as agentName,wh.SentimentalScore,wh.tags
                     		from tb_InstagramHistory 				wh
                     		join tb_InstagramMessage				wm on wm.InstagramHistoryId	= wh.InstagramHistoryId 
                     		left join tb_User 						u  on u.UserID				= wh.assignedTo 
                     		left join tb_User 						au on au.UserID				= wh.dispositionUpdatedBy	
     						left join tb_User 						ua on ua.UserID				= wh.AgentId
                     		left join disposition_status			ds on wh.DispositionId		= ds.did
     						left join 	customer_contact	CC on CC.instagram = wh.customerInstagramId AND CC.domainId = wh.domainId
                     		where 	wh.domainId = p_domainId 
     						and 	(primaryEmail collate utf8mb4_0900_ai_ci = p_emailId or ifnull(p_emailId,'')='')
                     		and 	(wh.customerInstagramId collate utf8mb4_0900_ai_ci = v_customerInstagramId or ifnull(v_customerInstagramId,0)=0)
                     		
                             AND 	wm.InstagramHistoryId = p_interactionId;
                     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                     	
                     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                     		insert into temp_getinteraction_list(channelType,customerNumber,emailId,dispositionName,dispositionSummary,sessionStartTime,sessionId,FacebookHistoryId,colorCode,updatedAt,Message,assignedTo,UserName,IsBot,dispositionUpdatedBy,AgentName,SentimentalScore,Tags)
                     		select  'Facebook' channelType,wh.customerFacebookId as customerNumber,'' emailId,ds.dispositionName as dispositionName,wh.Summary as dispositionSummary,
                     				 wh.SessionStartTime as sessionStartTime,wh.SessionId as sessionId,wh.FacebookHistoryId as historyId,ds.colorCode ,wh.updatedAt,wm.Message,wh.assignedTo,u.UserName,wh.IsBot,ifnull(au.UserName,'') as dispositionUpdatedBy
                                   ,ua.UserName as agentName,wh.SentimentalScore,wh.tags
                     		from tb_FacebookHistory 				wh
                     		join tb_FacebookMessage					wm on wm.FacebookHistoryId	= wh.FacebookHistoryId 
                     		left join tb_User 						u  on u.UserID				= wh.assignedTo 
                     		left join tb_User 						au on au.UserID				= wh.dispositionUpdatedBy
     						left join tb_User 						ua on ua.UserID				= wh.AgentId
                     		left join disposition_status			ds on wh.DispositionId		= ds.did
     						left join customer_contact	CC on CC.facebook  COLLATE utf8mb4_0900_ai_ci = wh.customerFacebookId AND CC.domainId = wh.domainId
                     		where 	wh.domainId = p_domainId 
     						and 	(primaryEmail COLLATE utf8mb4_0900_ai_ci = p_emailId or ifnull(p_emailId,'')='')
                     		and 	(wh.customerFacebookId COLLATE utf8mb4_0900_ai_ci = p_customerFacebookId or  ifnull(p_customerFacebookId,0)=0)
                             AND 	wm.FacebookHistoryId = p_interactionId;
                     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                               
   			select 	id_col,customerNumber,channelType,emailId,IFNULL(dispositionName,'') as dispositionName,dispositionSummary,sessionStartTime,sessionId,EmailHistoryId,
   					ChatHistoryId,ChatDurationHistoryId,CallHistoryId,SMSHistoryId,WhatsappHistoryId,InstagramHistoryId,FacebookHistoryId,colorCode,updatedAt,CustomerId,Message,UserName,AssignedTo,IsBot,
   					dispositionUpdatedBy,AgentName,transferedBy,transferedTo,videoSessionDtl,SentimentalScore,Tags as tags
   			from temp_getinteraction_list
   			order by updatedAt desc;        
               
               SELECT 	T.TicketId
   				,	S.StatusName
                   ,	fn_getTypeCodeName(T.PriorityId)	AS Priority
                   ,	U.UserName							AS Requester
                   ,	CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),IFNULL(CC.LastName,''))		AS TicketAssociateCustContactName
                   ,	T.TicketSubject
                   ,	T.CreatedDate
               FROM 	tb_TicketDetails 		T
               LEFT JOIN tb_TicketStatus		S	ON S.StatusId	= T.TicketStatusId
               LEFT JOIN tb_TicketUser			U 	ON U.UserId		= T.RequestorId  
               LEFT JOIN customer_contact		CC	ON CC.coid		= T.TicketAssociateCustContact	
               WHERE 	TicketId = p_TicketId;
                      
    End ;;
DELIMITER ;
