CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_is_valid_custom_hours_name`(
p_name  			VARCHAR(255),
p_domainId			INT
)
BEGIN
		
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		SELECT cid
			,name
			,description
			,hours
			,createdAt
			,updatedAt
			,domainId
			,timeZone
			,default_hours
			,timeZoneValue
			,type
		from custom_hours WHERE name collate utf8mb4_0900_ai_ci = p_name and  domainId = p_domainId;
        
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
