CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_is_valid_queue_name`(
p_name  			VARCHAR(255),
p_domainId			INT
)
BEGIN
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

		SELECT 
					qid
					,name
					,description
					,domainId
					,createdAt
					,updatedAt
					,settingAudio
					,announcement
					,maximumCallers
					,maximumWaitTime
					,OutboundCallerId
					,outBoundNumber
					,maxCallHandlingTimeMM
					,maxCallHandlingTimeSS
					,callWrapUpTime
					,outBoundCallStatus
					,hoursOfOperatioId
					,hours_of_operation
					,outOfBusinessHours
					,status
					,type
        FROM queue WHERE name collate utf8mb4_0900_ai_ci = p_name AND domainId = p_domainId ;
		
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
	
END ;;
