CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_KB_question_answer_data`(
	p_domainId 		int
    ,p_websiteId 	varchar(100)
)
begin

	SELECT questionId, domainId, uuid, question, answer, mapFlow, language, intent, keywords, status, version, createdAt
    , updatedAt, sent, helpfull, notHelpfull, chatFlowId, embedding, websiteId, discription, websiteUrl, baseName FROM question_answer 
    WHERE domainId = p_domainId 
    AND websiteId collate utf8mb4_0900_ai_ci = p_websiteId;
 
end ;;
