CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_knowledgeBaseArticleDetails`(
 	p_categoryId 				INT,
    p_knowledgeBaseType		 	INT
  )
begin
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 
 			JSON_ARRAYAGG(
            JSON_OBJECT("ArticleId",ArticleId,
             "kid",fk_kid,
             "createType",createType,
             "CategoryId",categoryId,
             "articlePath",articlePath,
            
             "articleLanguage",articleLanguage,
             "articleStatus",articleStatus,
             "metaDesc",metaDesc,
             "relatedpages",relatedpages,
             "createdBy",createdBy)) AS kb
             FROM tb_KnowledgeBaseArticleDtl 
             WHERE 	categoryId 			= p_categoryId
             AND 	knowledgeBaseType 	= p_knowledgeBaseType;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 
  end ;;
DELIMITER ;
