/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_KnowledgeBase_AverageBaseResponsePerDay_info`(
     p_startTmpstmp 	BIGINT,
     p_endTmpstmp 	BIGINT,
     p_domainId 		INT
   )
BEGIN
   		DECLARE v_StartTmpstmp 	    BIGINT;
 		DECLARE v_endTmp		    BIGINT;
  
  	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY)) * 1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
    	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_endTmp = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_endTmp = p_endTmpstmp; END IF;  
       
   	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
      DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                     	
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
     		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
  	    CREATE TEMPORARY TABLE temp_AvailableDisposition 
  	(    DispositionId 			INT
  		,DispositionStatus 		VARCHAR(100)
  		,DispositionCategory	TINYINT
  	); 
         
  	INSERT INTO temp_AvailableDisposition 
  	SELECT 	did 			DispositionId
  		,	dispositionName	DispositionStatus
  		,	CASE WHEN dispositionName = 'Opened'	THEN 2
  			WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
  			WHEN dispositionName = 'Discarded'     THEN 4
  			WHEN dispositionName = 'Resolved'      THEN 5
  			END 			DispositionCategory
  	FROM 	disposition_status
  	WHERE 	domainId	= p_domainId;  
     
     
  DROP TEMPORARY TABLE IF EXISTS tmp_botKnowledgeBasetrend;
  CREATE TEMPORARY TABLE tmp_botKnowledgeBasetrend
  SELECT 
      FROM_UNIXTIME(H.sessionStartTime/1000) 																				AS time_range,
      CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END 															AS Sessions,
      CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END                         AS duration,
      CASE WHEN sum(H.repliedDate - H.createdAt)	IS NOT NULL THEN 1	ELSE 0 END 						    	   			    AS responseTime
  FROM tb_ChatHistory H
  JOIN tb_ChatDurationHistory DH ON DH.ChatHistoryId = H.ChatHistoryId
  LEFT JOIN state_timer st ON H.domainId = st.domainId
  LEFT JOIN tb_stateTimerStatus sts ON sts.timerStatusId = st.timerStatusId
  LEFT JOIN tb_User tu ON tu.UserID = H.AssignedTo AND H.domainId = tu.domainId
  WHERE
      H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmp
      AND H.domainId = p_domainId
      AND DH.IsBot = 1
  GROUP BY
      H.sessionStartTime,H.sessionEndTime,H.repliedDate , H.createdAt;
  
  
  INSERT INTO tmp_botKnowledgeBasetrend
  SELECT 
      FROM_UNIXTIME(H.sessionStartTime/1000) 																				AS time_range,
      CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END 															AS Sessions,
      CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END                         AS duration,
      CASE WHEN sum(H.repliedDate - H.createdAt)	IS NOT NULL THEN 1	ELSE 0 END 						    	   			 AS responseTime
  FROM tb_SMSHistory H
  JOIN tb_SMSDurationHistory DH ON DH.SMSHistoryId = H.SMSHistoryId
  LEFT JOIN state_timer st ON H.domainId = st.domainId
  LEFT JOIN tb_stateTimerStatus sts ON sts.timerStatusId = st.timerStatusId
  LEFT JOIN tb_User tu ON tu.UserID = H.AssignedTo AND H.domainId = tu.domainId
  WHERE
      H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmp
      AND H.domainId = p_domainId
      AND DH.IsBot = 1
  GROUP BY
      H.sessionStartTime,H.sessionEndTime,H.repliedDate , H.createdAt;
  
  INSERT INTO tmp_botKnowledgeBasetrend
  SELECT 
      FROM_UNIXTIME(H.sessionStartTime/1000) 																				AS time_range,
      CASE WHEN H.sessionStartTime IS NOT NULL THEN 1 ELSE 0 END 															AS Sessions,
      CASE WHEN H.sessionEndTime IS NOT NULL THEN (H.sessionEndTime - H.sessionStartTime) ELSE 0 END                        AS duration,
      CASE WHEN sum(H.repliedDate - H.createdAt)	IS NOT NULL THEN 1	ELSE 0 END 						    	   			AS responseTime
  FROM tb_EmailHistory H
  JOIN tb_EmailDurationHistory DH ON DH.EmailHistoryId = H.EmailHistoryId
  LEFT JOIN state_timer st ON H.domainId = st.domainId
  LEFT JOIN tb_stateTimerStatus sts ON sts.timerStatusId = st.timerStatusId
  LEFT JOIN tb_User tu ON tu.UserID = H.AssignedTo AND H.domainId = tu.domainId
  WHERE
      H.sessionStartTime BETWEEN v_StartTmpstmp AND v_endTmp
      AND H.domainId = p_domainId
      AND DH.IsBot = 1
  GROUP BY
      H.sessionStartTime,H.sessionEndTime,H.repliedDate , H.createdAt;
  
  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       SELECT 
        (responseTime/count(1)* 100)                       AS AverageResponseTimePerDay
       FROM tmp_botKnowledgeBasetrend
  GROUP BY responseTime;
  
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_KnowledgeBase_Utilization_trend_chart_info` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_KnowledgeBase_Utilization_trend_chart_info`(
    p_startTmpstmp 	BIGINT,
    p_endTmpstmp 	BIGINT,
    p_domainId 		INT
  )
BEGIN
  		DECLARE v_StartTmpstmp 	BIGINT;
		DECLARE v_endTmp	BIGINT;
 
            
 	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY)) * 1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
   	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_endTmp = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_endTmp = p_endTmpstmp; END IF;  
      
  	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                    	
   								SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
                            		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                        		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
                                
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                        				WHEN dispositionName = 'Discarded'     THEN 4
 									WHEN dispositionName = 'Resolved'      THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;  
                                
                                
      DROP TEMPORARY TABLE IF EXISTS tmp_botKnowledgeBasetrend;
      CREATE TEMPORARY TABLE tmp_botKnowledgeBasetrend
      SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 																							AS time_range
          ,	0                              																										AS UtilizationRate
 		 ,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId  is not null AND 
 sts.timerStatus	not in ('connected','Agent on Hold','hold') and sts.timerStatus	 is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)    AS Percentage
      FROM 	tb_ChatHistory			H
      JOIN 	tb_ChatDurationHistory	DH		ON DH.ChatHistoryId = H.ChatHistoryId
 LEFT JOIN state_timer               st  	ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts		ON 	sts.timerStatusId = st.timerStatusId
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId 
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
 		AND    	H.domainId			= p_domainId
         AND 	DH.IsBot			= 1
      GROUP BY H.sessionStartTime,H.sessionEndTime;
          
      INSERT INTO tmp_botKnowledgeBasetrend
       SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 																						AS time_range
 		,	0                              																									AS UtilizationRate
 		,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId is not null  AND 
           sts.timerStatus not in ('connected','Agent on Hold','hold') and sts.timerStatus is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)   AS Percentage
      FROM 	tb_CallHistory			H
      JOIN 	tb_CallDurationHistory	DH	ON DH.CallHistoryId = H.CallHistoryId
 LEFT JOIN state_timer               st  ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts	ON 	sts.timerStatusId = st.timerStatusId     
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId 
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
 		AND    	H.domainId			= p_domainId
      AND 	DH.IsBot			= 1 
 	GROUP BY H.sessionStartTime,H.sessionEndTime,H.callDuration; 
      
      INSERT INTO tmp_botKnowledgeBasetrend
  SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 																										AS time_range	 
 		,	0                              																												AS UtilizationRate
 		,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId is not null  AND 
           sts.timerStatus not in ('connected','Agent on Hold','hold') and sts.timerStatus is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)   AS Percentage
      FROM 	tb_SMSHistory			H
      JOIN 	tb_SMSDurationHistory	DH	ON DH.SMSHistoryId = H.SMSHistoryId 
 LEFT JOIN state_timer               st  ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts	ON 	sts.timerStatusId = st.timerStatusId     
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId      
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
 	 AND    	H.domainId		= p_domainId
      AND 	   DH.IsBot			= 1 
      GROUP BY H.sessionStartTime,H.sessionEndTime;     
  
      INSERT INTO tmp_botKnowledgeBasetrend
  SELECT 	FROM_UNIXTIME(H.sessionStartTime/1000) 															   											AS time_range
         ,	0                              																												AS UtilizationRate
 		,COUNT(CASE when  tu.callTypeId = 'inbound' and tu.callTypeId is not null  AND 
           sts.timerStatus not in ('connected','Agent on Hold','hold') and sts.timerStatus is not null and H.sessionStartTime <> 0  THEN 1 ELSE 0 END)   AS Percentage
      FROM 	tb_EmailHistory			H
      JOIN 	tb_EmailDurationHistory	DH	ON DH.EmailHistoryId = H.EmailHistoryId
 LEFT JOIN state_timer               st  ON  H.domainId = st.domainId
 LEFT JOIN tb_stateTimerStatus		sts	ON 	sts.timerStatusId = st.timerStatusId     
 LEFT JOIN tb_User                   tu  ON   tu.UserID = H.AssignedTo and H.domainId = tu.domainId     
       WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_endTmp
 	 AND    	H.domainId		= p_domainId
      AND 	DH.IsBot			= 1 
      GROUP BY H.sessionStartTime,H.sessionEndTime;  
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;       
      
	 SELECT 	date_format(time_range,'%y-%m-%d %H:%i:%s')  				AS time_range
		,      (Percentage)                                                 AS Percentage
 		,   SUM(UtilizationRate)                                            AS UtilizationRate
      FROM 	tmp_botKnowledgeBasetrend
      GROUP BY time_range,Percentage;
      

  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_leaderBoard_agent_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_leaderBoard_agent_dtl`(
	p_agentId 		INT 
	,p_domainId 	INT
   )
sp_return: begin
   
	DECLARE v_ext 				INT;
	DECLARE v_roleid 			VARCHAR(50);
	DECLARE v_timerStatusId 	INT;
	DECLARE v_statusName 		VARCHAR(100);
	DECLARE v_startTime 		BIGINT;
	DECLARE v_endTime 			BIGINT;
	DECLARE v_currentEndTime 	BIGINT;
	DECLARE v_loginDuration 	BIGINT;
	DECLARE v_emailId 			VARCHAR(250);
   
   	DECLARE v_startTmpstmp 		BIGINT;
   	DECLARE v_endTmpstmp 		BIGINT;
   	DECLARE v_curDate			DATETIME DEFAULT CURRENT_DATE();
       
	DECLARE v_overAllavailableTime 			BIGINT;
   	DECLARE v_totalSocialMedia 				INT;
   	DECLARE v_totalChats 					INT;
   	
   	DECLARE v_blockCustomer 			INT;
   	DECLARE v_totalCustomer 			INT;
   	DECLARE v_totalTime 				INT;
   	
   	DECLARE v_queueDuration				INT;
   	DECLARE v_totalSessions 			INT;
   	DECLARE v_firstResponseTime 		BIGINT;
   	DECLARE v_totalDuration 			BIGINT;
   	DECLARE v_totalAnsweredCount 		BIGINT;
   	DECLARE v_avgSpeedOfAnswer 			BIGINT;
   	DECLARE v_avgHandlingTime 			BIGINT;
   	DECLARE v_totalACW 					BIGINT;
   	DECLARE v_totalCount 				BIGINT;
   	DECLARE v_occupancyRate 			BIGINT;
   	DECLARE v_noOfIsMissed 				BIGINT;
   	DECLARE v_overUnAllavailableTime 	BIGINT;
   	DECLARE v_noOfDeclined 				INT;
   	DECLARE v_totalTransaferInteraction 	INT;
       
   	DECLARE v_UserName 			VARCHAR(150);
   	DECLARE v_isVoice 			TINYINT;
   	DECLARE v_isChat 			TINYINT;
   	DECLARE v_isEmail 			TINYINT;
   	DECLARE v_isSms 			TINYINT;
   	DECLARE v_isSocialMedia 	TINYINT;
       DECLARE v_totalThresholdTime 		BIGINT;
   	DECLARE v_serviceLevel 				INT;
   	DECLARE v_totalChatCount 			INT;
   	DECLARE v_AnsDuration 				INT;
   
   	SET v_startTmpstmp 		= UNIX_TIMESTAMP(CAST(v_curDate AS DATE)) * 1000; 
   	SET v_endTmpstmp 		= UNIX_TIMESTAMP(DATE_ADD(DATE_ADD(CAST(v_curDate AS DATE),INTERVAL 1 DAY),INTERVAL -1 MINUTE)) * 1000;
   
   	SELECT ext,CASE WHEN roleid = 5 THEN 'Supervisor' WHEN roleid = 3 THEN 'Admin' WHEN roleid = 6 THEN 'Agent' END as roleId
       ,UserName,voice,chat,email,sms,socialMedia,emailId
   	INTO v_ext,v_roleid,v_UserName,v_isVoice,v_isChat,v_isEmail,v_isSms,v_isSocialMedia,v_emailId
       FROM tb_User 
       WHERE UserID = p_agentId
       AND domainId = p_domainId;
       
       SELECT timerStatusId INTO v_timerStatusId
       FROM state_timer
       WHERE ext = v_ext AND domainId = p_domainId
       AND CAST(createdAt AS DATE) = v_curDate
       ORDER BY stid DESC LIMIT 1;
       
		SELECT statusName INTO v_statusName
       FROM agent_status 
       WHERE aid = v_timerStatusId;
   	
       SELECT min(startTimestamp),max(endTimestamp)
       INTO v_startTime,v_endTime
       FROM state_timer 
       WHERE ext = v_ext AND domainId = p_domainId 
       AND CAST(createdAt AS DATE) = v_curDate
       GROUP BY ext;
       
       SELECT IFNULL(endTimestamp,(unix_timestamp()*1000))
       INTO v_currentEndTime
       FROM state_timer 
       WHERE ext = v_ext AND domainId = p_domainId 
       AND CAST(createdAt AS DATE) = v_curDate
       AND endTimestamp IS NULL
       order by stid desc limit 1;
       
       DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
   		CREATE TEMPORARY TABLE temp_AvailableState AS
   		SELECT   
   		CASE 
   			WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
   			WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) or (isChat = 0) or (isEmail=0)  ) THEN 2
   			ELSE 3 
   			END AS tt_Time,
   			ST.domainId,
   			ST.stateDuration as SD,
               from_unixtime(ST.startTimestamp/1000)
   		FROM     state_timer ST 
   		JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
   		WHERE    ST.domainId = p_domainId
  		AND		 ST.ext = v_ext 
   		AND      ST.startTimestamp BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
   		SELECT SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) 
   		INTO v_overAllavailableTime
   		FROM temp_AvailableState
           WHERE    domainId = p_domainId
   		GROUP BY domainId;
           
           SELECT SUM(CASE WHEN tt_Time = 2 THEN SD ELSE 0 END) 
   		INTO v_overUnAllavailableTime
   		FROM temp_AvailableState
           WHERE    domainId = p_domainId
   		GROUP BY domainId;
           
       SELECT TIMESTAMPDIFF(SECOND,FROM_UNIXTIME(v_startTime / 1000),FROM_UNIXTIME(CASE WHEN v_currentEndTime IS NULL THEN v_endTime ELSE v_currentEndTime END / 1000))
       INTO v_loginDuration;
   	    
       DROP TEMPORARY TABLE IF EXISTS temp_CallHistory;
   		CREATE TEMPORARY TABLE temp_CallHistory AS
   		SELECT 
   				CH.CallHistoryId
   				,CH.sessionStartTime
   				,CH.sessionEndTime
   				,CH.domainId
   				,CH.IsInBound
   				,CH.waitDuration
   				,CH.CustomerId
   				,CH.voicemailUrl
   				,CH.callBack
   				,CDH.CallDurationHistoryId
   				,CDH.Duration
   				,CDH.AgentId
   				,CDH.dispositionId
   				,CDH.afterCallWorkTime
                   ,CH.callCost
                   ,CDH.AgentHoldDuration
                   ,CDH.IsBot
                   ,CH.queueDuration
                   ,CDH.IsMissedCall
                   ,CH.IsAbandoned
                   ,CDH.answeredDuration
   		FROM 	tb_CallHistory 	CH
   		JOIN 	tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId
   		WHERE 	CH.domainId = p_domainId
  		AND		CDH.AgentId = p_agentId
   		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
   		DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
   		CREATE TEMPORARY TABLE temp_ChatHistory AS
   		SELECT
   				CH.ChatHistoryId
   				,CH.sessionStartTime
   				,CH.sessionEndTime
   				,CH.chatFlowSourceId
   				,CH.domainId
   				,CH.IsInBound
   				,CH.CustomerId
   				,CH.CallBackStatus
   				,CDH.ChatDurationHistoryId
   				,CDH.Duration
   				,CDH.AgentId
   				,CDH.dispositionId
   				,CDH.afterChatWorkTime
				,CDH.IsBot
				,CH.queueDuration
				,CDH.IsMissed
				,CDH.IsAbandoned
				,CDH.answeredDuration
   		FROM 	tb_ChatHistory 	CH
   		JOIN 	tb_ChatDurationHistory 	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId 
   		WHERE 	CH.domainId = p_domainId
		AND 	CDH.AgentId = p_agentId
   		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;   
        
   		DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory;
   		CREATE TEMPORARY TABLE temp_EmailHistory AS
   		SELECT
   				EH.EmailHistoryId
   				,EH.SessionStartTime
   				,EH.SessionEndTime
   				,EH.DomainId
   				,EH.DispositionId
   				,EH.IsInBound
   				,EH.AfterEmailWorkTime
   				,EH.IsSessionClosed
   				,EH.CustomerId
   				,EDH.EmailDurationHistoryId
   				,EDH.Duration
   				,EDH.AgentId
                   ,EDH.IsBot
                   ,EC.emailThreshold
   		FROM 	tb_EmailHistory EH
   		JOIN 	tb_EmailDurationHistory EDH ON EH.EmailHistoryId = EDH.EmailHistoryId 
           JOIN 	email_config EC ON EC.domainId = EH.DomainId
   		WHERE 	EH.domainId = p_domainId
           AND		EDH.AgentId = p_agentId
   		AND 	EH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
   
   		DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory;
   		CREATE TEMPORARY TABLE temp_SMSHistory AS
   		SELECT
   				SH.SMSHistoryId
   				,SH.sessionStartTime
   				,SH.sessionEndTime
   				,SH.domainId
   				,SH.dispositionId
   				,SH.IsInBound
   				,SH.afterSMSWorkTime
   				,SH.IsSessionClosed
   				,SH.customerNumber
   				,SH.calledNumber
   				,SDH.SMSDurationHistoryId
   				,SDH.Duration
   				,SDH.AgentId
                   ,SDH.IsBot
   		FROM 	tb_SMSHistory 	SH
   		JOIN 	tb_SMSDurationHistory 	SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
   		WHERE 	SH.domainId = p_domainId
           AND		SDH.AgentId = p_agentId
   		AND 	SH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
   		DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory;
   		CREATE TEMPORARY TABLE temp_WhatsappHistory AS
   		SELECT
   				WH.WhatsappHistoryId
   				,WH.sessionStartTime
   				,WH.sessionEndTime
   				,WH.domainId
   				,WH.dispositionId
   				,WH.IsInBound
   				,WH.afterwhatsappWorkTime
   				,WH.IsSessionClosed
   				,WH.isCallback
   				,WDH.WhatsappDurationHistoryId
   				,WDH.AgentId
   				,WDH.Duration
   				,WDH.dialDuration
                   ,WDH.IsBot
                   ,WDH.IsMissed
   		FROM 	tb_WhatsappHistory 	WH
   		JOIN 	tb_WhatsappDurationHistory 	WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
   		WHERE 	WH.domainId = p_domainId
           AND 	WDH.AgentId = p_agentId
   		AND 	WH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
   		DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory;
   		CREATE TEMPORARY TABLE temp_FacebookHistory AS
   		SELECT
   				FacebookHistoryId
   				,sessionStartTime
   				,sessionEndTime
   				,domainId
   				,dispositionId
   				,IsInBound
   				,afterFacebookWorkTime
   				,IsSessionClosed
   				,AgentId
   				,Duration
   				,isCallback
                   ,IsBot
                   ,IsMissed
                   ,dialDuration
   		FROM 	tb_FacebookHistory 
   		WHERE 	domainId = p_domainId
           AND		AgentId  = p_agentId
   		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
   		DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory;
   		CREATE TEMPORARY TABLE temp_InstagramHistory AS
   		SELECT
   				
   				InstagramHistoryId
   				,sessionStartTime
   				,sessionEndTime
   				,domainId
   				,dispositionId
   				,IsInBound
   				,afterInstagramWorkTime
   				,IsSessionClosed
   				,AgentId
   				,Duration
                   ,IsMissed
                   ,dialDuration
   		FROM 	tb_InstagramHistory
   		WHERE 	domainId = p_domainId
           AND		AgentId = p_agentId
   		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
   
  
   
   		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal;
   		CREATE TEMPORARY TABLE temp_CallHistory_cal AS
   		SELECT 
   				 count(CallHistoryId) as totalCalls
   				,sum(case when IsInBound  = 1 then 1 else 0 end) as totalInboundCalls
                   ,sum(case when IsInBound  = 0 then 1 else 0 end) as totalOutboundCalls
                   ,sum(case when callBack = 1 then 1 else 0 end) as callCallBack
                   ,sum(case when voicemailUrl IS NOT NULL AND voicemailUrl like '%voicemail%' then 1 else 0 end) as totalVoiceMail
                   ,sum(case when DS.dispositionName = 'Caller Disconnected' then 1 else 0 end) as totalAbandonCalls
                   ,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredCalls
                   ,sum(case when DS.dispositionName = 'Transferred' then 1 else 0 end) as totalCallTransferCount
  				,sum(case when IFNULL(Duration,0) > 0 then Duration	else 0 end) as totalCallDurationAnswered 
                   ,sum(case when IFNULL(Duration,0) > 0 then afterCallWorkTime else 0 end) as totalCallACWTimeAnswered
                   ,sum(case when IFNULL(Duration,0) > 0 then AgentHoldDuration else 0 end) as totalCallHoldTime
                   ,sum(case when IFNULL(callCost,0) > 0 then callCost else 0 end) as totalCallCost
   				,sum(queueDuration) as queueDuration
   				,sum(AgentHoldDuration) as AgentHoldDuration
                   ,sum(case when IFNULL(IsMissedCall,0)  = 1 then 1 else 0 end) as isMissed
                   ,sum(case when IFNULL(IsAbandoned,0)   = 1 then 1 else 0 end) as IsAbandoned
                   ,sum(case when IFNULL(answeredDuration,0) > 0 then answeredDuration else 0 end) as answeredDurationCall
   		FROM 		temp_CallHistory CH
           LEFT JOIN 	disposition_status		DS 	ON DS.did = CH.dispositionId
   		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           SELECT 	COUNT(DISTINCT ChatHistoryId) INTO v_totalChatCount
   		FROM 	temp_ChatHistory;
           
           DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal;
   		CREATE TEMPORARY TABLE temp_ChatHistory_cal AS
   		SELECT 
   				 count(ChatHistoryId) as totalWebChats
                   ,sum(case when CallBackStatus = 1 then 1 else 0 end) as chatCallBack
                   ,sum(case when dispositionId is null then 1 else 0 end) as nonCompleteChat
                   ,sum(case when DS.dispositionName = 'Caller Disconnected' then 1 else 0 end) as totalAbandonChats
                   ,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredChats
                   ,sum(case when IFNULL(Duration,0) > 0 AND DS.dispositionName = 'Transferred' then 1 else 0 end) as totalChatTransferCount
                   ,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalChatDurationAnswered
                   ,sum(case when IFNULL(Duration,0) > 0 then afterChatWorkTime else 0 end) as totalChatACWTimeAnswered
 					,sum(queueDuration) as queueDuration	
                   ,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
                   ,sum(case when IFNULL(IsAbandoned,0)   = 1 then 1 else 0 end) as IsAbandoned
                   ,sum(case when IFNULL(answeredDuration,0) > 0 then 1 else 0 end) as answeredDurationChat
   		FROM 		temp_ChatHistory CH
           LEFT JOIN 	disposition_status		DS 	ON DS.did = CH.dispositionId
   		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_cal;
   		CREATE TEMPORARY TABLE temp_EmailHistory_cal AS
   		SELECT   count(EmailHistoryId) as totalEmails
           ,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredEmails
           ,sum(case when IFNULL(Duration,0) > 0 then AfterEmailWorkTime else 0 end) as totalEmailACWTimeAnswered
   		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalEmailDurationAnswered
          
           ,sum(case when (emailThreshold <= 24) then 1 else 0 end) as answeredDurationEmail
           FROM 		temp_EmailHistory EH
   		WHERE 	SessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_cal;
   		CREATE TEMPORARY TABLE temp_SMSHistory_cal AS
   		SELECT   count(*) as totalSMS
           ,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredSMS
           ,sum(case when IFNULL(Duration,0) > 0 then afterSMSWorkTime else 0 end) as totalSMSACWTimeAnswered
   		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalSMSDurationAnswered
           FROM 		temp_SMSHistory SH
   		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_cal;
   		CREATE TEMPORARY TABLE temp_WhatsappHistory_cal AS
   		SELECT   count(*) as totalWhatsapp
           ,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredWhatsapp
           ,sum(case when IFNULL(Duration,0) > 0 then afterwhatsappWorkTime else 0 end) as totalWhatsappACWTimeAnswered
   		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalWhatsappDurationAnswered
           ,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
           ,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationWhatsapp
           FROM 		temp_WhatsappHistory WH
   		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_cal;
   		CREATE TEMPORARY TABLE temp_FacebookHistory_cal AS
   		SELECT   count(FacebookHistoryId) as totalFacebook
           ,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationFacebook
           ,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredFacebook
           ,sum(case when IFNULL(Duration,0) > 0 then afterFacebookWorkTime else 0 end) as totalFacebookACWTimeAnswered
           ,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalFacebookDurationAnswered
           FROM 		temp_FacebookHistory FH
   		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_cal;
   		CREATE TEMPORARY TABLE temp_InstagramHistory_cal AS
   		SELECT   count(InstagramHistoryId) as totalInstagram
           ,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationInsta
           ,sum(case when IFNULL(Duration,0) > 0 then afterInstagramWorkTime else 0 end) as totalInstagramACWTimeAnswered
           ,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredInstagram
           ,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalInstagramDurationAnswered
           FROM 		temp_InstagramHistory FH
   		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
           
           
           DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_CallHistory_cal_final AS
   		SELECT 
   				 totalCalls as totalCalls
   				,totalInboundCalls as totalInboundCalls
                   ,totalOutboundCalls as totalOutboundCalls
                   ,callCallBack
                   ,totalVoiceMail as totalVoiceMail
                   ,totalAnsweredCalls
                   ,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalAbandonCalls / totalAnsweredCalls) * 100 END as callAbandonRates
                   ,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalCallCost / totalAnsweredCalls) END  as costPerCall
                   ,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalCallTransferCount / totalAnsweredCalls) * 100 END  as callsTransferRate
                   ,(totalCallDurationAnswered+(totalCallACWTimeAnswered*1000)) as overallCallAnsweredDuration
                   ,AgentHoldDuration
                   ,totalCallDurationAnswered
                   ,CASE WHEN v_totalTime = 0 THEN 0 ELSE floor(totalInboundCalls/v_totalTime) END as callArrivalRate
                   ,totalCallACWTimeAnswered
                   ,queueDuration			 
                   ,CASE WHEN totalCalls = 0 THEN 0 ELSE (totalCallHoldTime/totalCalls) END as avgHoldTime
                   ,isMissed AS callIsMissed
                   ,IsAbandoned AS callIsAbandoned
                   ,answeredDurationCall
                   ,totalCallTransferCount
   		FROM temp_CallHistory_cal;
           
            DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_ChatHistory_cal_final AS
   		SELECT 
   				 totalWebChats as totalWebChats
   				,chatCallBack as chatCallBack
                   ,nonCompleteChat as nonCompleteChat
                   ,totalAbandonChats
                   ,totalAnsweredChats as totalAnsweredChats
                   ,totalChatTransferCount
                   ,totalChatDurationAnswered
                   ,totalChatACWTimeAnswered
                   ,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalAbandonChats / totalAnsweredChats) * 100 END as chatAbandonRates
                   ,CASE WHEN totalWebChats = 0 THEN 0 ELSE (totalAnsweredChats / totalWebChats) * 100 END as chatCompletionRates
                   ,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalChatTransferCount / totalAnsweredChats) * 100 END  as chatsTransferRate
                   ,(totalChatDurationAnswered+(totalChatACWTimeAnswered*1000)) as overallChatAnsweredDuration
                   ,CASE WHEN totalWebChats = 0 THEN 0 ELSE (totalChatDurationAnswered/totalWebChats) END as averageChatDuration 
                   ,CASE WHEN totalWebChats = 0 THEN 0 ELSE IFNULL((queueDuration/totalWebChats),0) END as averageChatWaitTime  
                   ,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalChatDurationAnswered/totalAnsweredChats) END as averageChatReplyTime   
   				,IFNULL(queueDuration,0) as queueDuration
                   ,isMissed as chatIsMissed
                   ,IsAbandoned as chatIsAbandoned
                   ,answeredDurationChat
   		FROM temp_ChatHistory_cal;
           
   		DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_EmailHistory_cal_final AS
   		SELECT 
   			totalEmails
               ,totalAnsweredEmails
               ,answeredDurationEmail
   			,(totalEmailDurationAnswered+(totalEmailACWTimeAnswered*1000)) as overallEmailAnsweredDuration
               ,totalEmailACWTimeAnswered
               ,totalEmailDurationAnswered
               
           FROM temp_EmailHistory_cal;
           
           DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_SMSHistory_cal_final AS
   		SELECT 
   			totalSMS
               ,totalAnsweredSMS
   			,(totalSMSDurationAnswered+(totalSMSACWTimeAnswered*1000)) as overallSMSAnsweredDuration
   			,totalSMSACWTimeAnswered
               ,totalSMSDurationAnswered
           FROM temp_SMSHistory_cal;
           
           DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_WhatsappHistory_cal_final AS
   		SELECT 
   			totalWhatsapp
               ,totalAnsweredWhatsapp
   			,(totalWhatsappDurationAnswered+(totalWhatsappACWTimeAnswered*1000)) as overallWhatsappAnsweredDuration
               ,totalWhatsappACWTimeAnswered
               ,isMissed as whatsappIsMissed
               ,answeredDurationWhatsapp
               ,totalWhatsappDurationAnswered
           FROM temp_WhatsappHistory_cal;
           
   		DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_FacebookHistory_cal_final AS
   		SELECT 
   			 totalFacebook
                ,totalAnsweredFacebook
                ,answeredDurationFacebook
                ,totalFacebookACWTimeAnswered
                ,(totalFacebookDurationAnswered+(totalFacebookACWTimeAnswered*1000)) as overallFacebookAnsweredDuration
                ,totalFacebookDurationAnswered
           FROM temp_FacebookHistory_cal;
           
           DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_cal_final;
   		CREATE TEMPORARY TABLE temp_InstagramHistory_cal_final AS
   		SELECT 
   			 totalInstagram
                ,totalAnsweredInstagram
                ,answeredDurationInsta
                ,totalInstagramACWTimeAnswered
                ,totalInstagramDurationAnswered
                ,(totalInstagramDurationAnswered+(totalInstagramACWTimeAnswered*1000)) as overallInstagramAnsweredDuration
           FROM temp_InstagramHistory_cal;
   
    
    
   		 SELECT 	(SELECT COUNT(WhatsappHistoryId) FROM temp_WhatsappHistory) +
   		(SELECT COUNT(FacebookHistoryId) FROM temp_FacebookHistory) +
   		(SELECT COUNT(InstagramHistoryId) FROM temp_InstagramHistory) INTO v_totalSocialMedia;
                   
   		SELECT (SELECT COALESCE(SUM(queueDuration), 0) FROM temp_CallHistory_cal_final) +
   		(SELECT COALESCE(SUM(queueDuration), 0) FROM temp_ChatHistory_cal_final) 	INTO v_queueDuration;
           
           SELECT (SELECT COALESCE(SUM(totalCalls), 0) FROM temp_CallHistory_cal_final) +
   		(SELECT COALESCE(SUM(totalWebChats), 0) FROM temp_ChatHistory_cal_final) +
   		(SELECT COALESCE(SUM(totalEmails), 0) FROM temp_EmailHistory_cal_final) +
   		(SELECT COALESCE(SUM(totalSMS), 0) FROM temp_SMSHistory_cal_final) +
   		(SELECT COALESCE(SUM(totalWhatsapp), 0) FROM temp_WhatsappHistory_cal_final) +
   		(SELECT COALESCE(SUM(totalFacebook), 0) FROM temp_FacebookHistory_cal_final) +
   		(SELECT COALESCE(SUM(totalInstagram), 0) FROM temp_InstagramHistory_cal_final) 
           INTO v_totalSessions;			
            
		SET v_queueDuration = v_queueDuration / 1000;
		SELECT CASE WHEN v_totalSessions = 0 THEN 0 ELSE (v_queueDuration/v_totalSessions) END INTO v_firstResponseTime;
   
   	  SELECT  (COALESCE((SELECT SUM(overallCallAnsweredDuration) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(overallChatAnsweredDuration) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(overallEmailAnsweredDuration) FROM temp_EmailHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(overallFacebookAnsweredDuration) FROM temp_FacebookHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(overallInstagramAnsweredDuration) FROM temp_InstagramHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(overallSMSAnsweredDuration) FROM temp_SMSHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(overallWhatsappAnsweredDuration) FROM temp_WhatsappHistory_cal_final), 0)) 
   	INTO v_totalDuration;
   
   	SELECT  (COALESCE((SELECT SUM(totalCallDurationAnswered) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalChatDurationAnswered) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalEmailDurationAnswered) FROM temp_EmailHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalFacebookDurationAnswered) FROM temp_FacebookHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalInstagramDurationAnswered) FROM temp_InstagramHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalSMSDurationAnswered) FROM temp_SMSHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalWhatsappDurationAnswered) FROM temp_WhatsappHistory_cal_final), 0)) 
   	INTO v_AnsDuration;	
           
   	  SELECT  (COALESCE((SELECT SUM(totalAnsweredCalls) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalAnsweredChats) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalAnsweredEmails) FROM temp_EmailHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalAnsweredSMS) FROM temp_SMSHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalAnsweredFacebook) FROM temp_FacebookHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalAnsweredInstagram) FROM temp_InstagramHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalAnsweredWhatsapp) FROM temp_WhatsappHistory_cal_final), 0))
   	INTO v_totalAnsweredCount;
   
   	   SELECT (COALESCE((SELECT SUM(totalCallACWTimeAnswered) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalChatACWTimeAnswered) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalEmailACWTimeAnswered) FROM temp_EmailHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalSMSACWTimeAnswered) FROM temp_SMSHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalWhatsappACWTimeAnswered) FROM temp_WhatsappHistory_cal_final), 0)) 
   	INTO v_totalACW;
   		 
        SELECT  (COALESCE((SELECT SUM(totalCalls) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalWebChats) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalEmails) FROM temp_EmailHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalSMS) FROM temp_SMSHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(totalWhatsapp) FROM temp_WhatsappHistory_cal_final), 0))
   	INTO v_totalCount;
       
       SELECT  (COALESCE((SELECT SUM(answeredDurationCall) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(answeredDurationChat) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(answeredDurationWhatsapp) FROM temp_WhatsappHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(answeredDurationFacebook) FROM temp_FacebookHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(answeredDurationEmail) FROM temp_EmailHistory_cal), 0) +
   		 COALESCE((SELECT SUM(answeredDurationInsta) FROM temp_InstagramHistory_cal_final), 0))
   	INTO v_totalThresholdTime;
           
       SELECT  (COALESCE((SELECT SUM(callIsMissed) FROM temp_CallHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(chatIsMissed) FROM temp_ChatHistory_cal_final), 0) +
   		 COALESCE((SELECT SUM(whatsappIsMissed) FROM temp_WhatsappHistory_cal_final), 0)) 
   	INTO v_noOfIsMissed;
       
   	SELECT  (COALESCE((SELECT SUM(callIsAbandoned) FROM temp_CallHistory_cal_final), 0) +
   			 COALESCE((SELECT SUM(chatIsAbandoned) FROM temp_ChatHistory_cal_final), 0)) 
   		INTO v_noOfDeclined;
           
   	SELECT  (COALESCE((SELECT SUM(totalCallTransferCount) FROM temp_CallHistory_cal_final), 0) +
   			 COALESCE((SELECT SUM(totalChatTransferCount) FROM temp_ChatHistory_cal_final), 0)) 
   		INTO v_totalTransaferInteraction;
          
  
   	 
 	SET v_avgSpeedOfAnswer = CASE WHEN v_totalAnsweredCount = 0 THEN 0 ELSE (v_totalThresholdTime/v_totalAnsweredCount) END;
   	SET v_avgHandlingTime = CASE WHEN v_totalAnsweredCount = 0 THEN 0 ELSE ((v_totalDuration+(COALESCE((SELECT SUM(AgentHoldDuration) FROM temp_CallHistory_cal_final), 0)))/v_totalAnsweredCount) END;
  	SET v_occupancyRate = CASE WHEN v_overAllavailableTime = 0 THEN 0 ELSE ((v_totalDuration / v_overAllavailableTime)* 100) END  ;
   	SET v_serviceLevel 		= CASE WHEN v_totalSessions = 0 THEN 0 ELSE ((v_totalThresholdTime / v_totalSessions)* 100) END  ;
           
   	SELECT v_ext as ext,v_roleid as role,v_statusName as status,v_loginDuration as loginDuration
       ,v_UserName as agentName,v_isVoice as isCall,v_isChat as isChat,v_isEmail as isMail,v_isSms as isSms,v_isSocialMedia as isSocialMedia,v_emailId as emailId;
       
   
       SELECT 
   			totalCalls,totalWebChats,totalEmails,totalSMS,v_totalSocialMedia as totalSocialMedia,ROUND((v_firstResponseTime),0) AS firstResponseTime
               ,v_totalACW as totalWrapUpTime,v_serviceLevel as serviceLevel ,v_totalTransaferInteraction AS totalTransaferInteraction
               ,v_noOfIsMissed AS noOfIsMissed,v_noOfDeclined as noOfDeclined,v_occupancyRate as occupancyRate
               ,ROUND(v_avgSpeedOfAnswer) as avgSpeedOfAnswer,callAbandonRates as abandonRates,v_loginDuration as totalOnlineTime, ROUND(v_overAllavailableTime/1000) as totalAvailable
               ,ROUND(v_avgHandlingTime/1000) as avgHandlingTime,ROUND(v_overUnAllavailableTime/1000) as totalAwayTime,ROUND(v_totalDuration/1000) as totalTalkTime,IFNULL(ROUND(AgentHoldDuration/1000),0) as totalHoldTime
   
   		FROM 
   			temp_CallHistory_cal_final,
   			temp_ChatHistory_cal_final,
   			temp_EmailHistory_cal_final,
   			temp_SMSHistory_cal_final,
   			(SELECT v_totalChats,v_totalSocialMedia,v_occupancyRate,v_loginDuration,v_firstResponseTime,v_avgSpeedOfAnswer,v_totalTransaferInteraction
               ,v_avgHandlingTime,v_totalACW,v_noOfIsMissed,v_noOfDeclined,v_totalDuration,v_overAllavailableTime,v_overUnAllavailableTime) AS other_metrics;
   end ;;
DELIMITER ;
