/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_leaderBoard_agent_recent_answered_info`(
	
     p_agentId 		INT 
    ,p_domainId 	INT

)
begin
		DECLARE v_startTmpstmp 		BIGINT;
		DECLARE v_endTmpstmp 		BIGINT;
        DECLARE v_curDate			DATETIME DEFAULT CURRENT_DATE();
	
		SET v_startTmpstmp 		= UNIX_TIMESTAMP(CAST(v_curDate AS DATE)) * 1000; 
		SET v_endTmpstmp 		= UNIX_TIMESTAMP(DATE_ADD(DATE_ADD(CAST(v_curDate AS DATE),INTERVAL 1 DAY),INTERVAL -1 MINUTE)) * 1000;

		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory;
		CREATE TEMPORARY TABLE temp_CallHistory AS
		SELECT 
				CH.CallHistoryId
				,CH.sessionStartTime
				,CH.sessionEndTime
				,CH.domainId
				,CH.IsInBound
				,CH.CustomerId
				,CDH.CallDurationHistoryId
				,CDH.Duration
				,CDH.AgentId
				,CDH.dispositionId
				,CDH.afterCallWorkTime
                ,CDH.AgentHoldDuration
                ,CDH.IsBot
                ,CH.queueDuration
                ,CDH.IsMissedCall
                ,CH.IsAbandoned
		FROM 	tb_CallHistory 	CH
		JOIN 	tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId
		WHERE 	CH.domainId = p_domainId
        AND		CDH.AgentId = p_agentId
		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;

		DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
		CREATE TEMPORARY TABLE temp_ChatHistory AS
		SELECT
				CH.ChatHistoryId
				,CH.sessionStartTime
				,CH.sessionEndTime
				,CH.chatFlowSourceId
				,CH.domainId
				,CH.IsInBound
				,CH.CustomerId
				,CH.CallBackStatus
				,CDH.ChatDurationHistoryId
				,CDH.Duration
				,CDH.AgentId
				,CDH.dispositionId
				,CDH.afterChatWorkTime
                ,CDH.IsBot
                ,CH.queueDuration
                ,CDH.IsMissed
                ,CDH.IsAbandoned
		FROM 	tb_ChatHistory 	CH
		JOIN 	tb_ChatDurationHistory 	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId 
		WHERE 	CH.domainId = p_domainId
        AND 	CDH.AgentId = p_agentId
		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;


		DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory;
		CREATE TEMPORARY TABLE temp_EmailHistory AS
		SELECT
				EH.EmailHistoryId
				,EH.SessionStartTime
				,EH.SessionEndTime
				,EH.DomainId
				,EH.DispositionId
				,EH.IsInBound
				,EH.AfterEmailWorkTime
				,EH.IsSessionClosed
				,EH.CustomerId
				,EDH.EmailDurationHistoryId
				,EDH.Duration
				,EDH.AgentId
                ,EDH.IsBot
		FROM 	tb_EmailHistory EH
		JOIN 	tb_EmailDurationHistory EDH ON EH.EmailHistoryId = EDH.EmailHistoryId 
		WHERE 	EH.domainId = p_domainId
        AND		EDH.AgentId = p_agentId
		AND 	EH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;


		DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory;
		CREATE TEMPORARY TABLE temp_SMSHistory AS
		SELECT
				SH.SMSHistoryId
				,SH.CustomerId
				,SH.sessionStartTime
				,SH.sessionEndTime
				,SH.domainId
				,SH.dispositionId
				,SH.IsInBound
				,SH.afterSMSWorkTime
				,SH.IsSessionClosed
				,SH.customerNumber
				,SH.calledNumber
				,SDH.SMSDurationHistoryId
				,SDH.Duration
				,SDH.AgentId
                ,SDH.IsBot
		FROM 	tb_SMSHistory 	SH
		JOIN 	tb_SMSDurationHistory 	SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
		WHERE 	SH.domainId = p_domainId
        AND		SDH.AgentId = p_agentId
		AND 	SH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;

		DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory;
		CREATE TEMPORARY TABLE temp_WhatsappHistory AS
		SELECT
				WH.WhatsappHistoryId
				,WH.sessionStartTime
				,WH.sessionEndTime
				,WH.CustomerId
				,WH.domainId
				,WH.dispositionId
				,WH.IsInBound
				,WH.afterwhatsappWorkTime
				,WH.IsSessionClosed
				,WH.isCallback
				,WDH.WhatsappDurationHistoryId
				,WDH.AgentId
				,WDH.Duration
				,WDH.dialDuration
                ,WDH.IsBot
                ,WDH.IsMissed
		FROM 	tb_WhatsappHistory 	WH
		JOIN 	tb_WhatsappDurationHistory 	WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
		WHERE 	WH.domainId = p_domainId
        AND 	WDH.AgentId = p_agentId
		AND 	WH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;

		DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory;
		CREATE TEMPORARY TABLE temp_FacebookHistory AS
		SELECT
				FacebookHistoryId
				,sessionStartTime
				,CustomerId
				,sessionEndTime
				,domainId
				,dispositionId
				,IsInBound
				,afterFacebookWorkTime
				,IsSessionClosed
				,AgentId
				,Duration
				,isCallback
                ,IsBot
                ,IsMissed
		FROM 	tb_FacebookHistory 
		WHERE 	domainId = p_domainId
        AND		AgentId  = p_agentId
		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;

		DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory;
		CREATE TEMPORARY TABLE temp_InstagramHistory AS
		SELECT
				
				InstagramHistoryId
				,sessionStartTime
				,sessionEndTime
				,CustomerId
				,domainId
				,dispositionId
				,IsInBound
				,afterInstagramWorkTime
				,IsSessionClosed
				,AgentId
				,Duration
                ,IsMissed
		FROM 	tb_InstagramHistory
		WHERE 	domainId = p_domainId
        AND		AgentId = p_agentId
		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;

	DROP TEMPORARY TABLE IF EXISTS tt_agent_attend_queries;
	CREATE TEMPORARY TABLE tt_agent_attend_queries
    (
		channelType VARCHAR(50)
        ,customerName VARCHAR(250)
        ,customerContact VARCHAR(50)
        ,Direction VARCHAR(20)
        ,Duration INT
        ,dispositionName VARCHAR(150)
        ,coid BIGINT
        ,AnsweredDateTime VARCHAR(25)
        ,DispositionColorCode VARCHAR(15)
    );

	INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
	SELECT 	'Call'as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_CallHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
    
    INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
    SELECT 	'Chat' as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_ChatHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
    
    INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
    SELECT 	'Email' as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_EmailHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
	
    INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
     SELECT 	'SMS' as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_SMSHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
    
    INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
     SELECT 	'Whatsapp' as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_WhatsappHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
    
    INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
    SELECT 	'Facebook' as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_FacebookHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
    
    INSERT INTO tt_agent_attend_queries(channelType,customerName,customerContact,Direction,Duration,dispositionName,coid,AnsweredDateTime,DispositionColorCode)
     SELECT 	'Instagram' as chennelType,concat(IFNULL(CC.firstName,''),' ',IFNULL(CC.lastName,'')) as customerName
			,CC.primaryPhoneNumber as customerContact
			,CASE WHEN tt.IsInBound = 1 THEN 'Inbound' WHEN  tt.IsInBound = 0 THEN 'Outbound' END as Direction
            ,tt.Duration
            ,DS.dispositionName
            ,CC.coid
            ,DATE_FORMAT(FROM_UNIXTIME(tt.sessionStartTime/1000),'%Y-%m-%d %H:%i:%s') as AnsweredDateTime
            ,DS.colorCode
    FROM 	temp_InstagramHistory 	tt
    JOIN 	disposition_status 	DS ON tt.dispositionId = DS.did
	JOIN 	customer_contact 	CC ON CC.coid = tt.CustomerId;
    
    select channelType,customerName,customerContact,Direction,ROUND(Duration/1000) as Duration,dispositionName,AnsweredDateTime,DispositionColorCode
    from tt_agent_attend_queries
    order by AnsweredDateTime desc limit 10;
end ;;
DELIMITER ;
