CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_libary_details`(
	p_name					VARCHAR(100),	
	p_domainId				INT
)
BEGIN
			
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
        
				SELECT uuid,
						fieldname,
						encoding,
						mimetype,
						filename,
						`path`,
						size,
						`type`,
						promptType,
						url,
						`name`,
						`description`,
						domainId,
						companyId,
						message,
						createdAt,
						updateddAt,
						promptStatus
				FROM prompt_library WHERE `name` collate utf8mb4_0900_ai_ci= p_name AND domainId = p_domainId;
                    
                    
        
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
            
		

END ;;
