/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_live_interaction_ai`(
	p_domainId			INT
)
BEGIN
		DECLARE v_past_60_sec DATETIME;

SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		
        SELECT (NOW() - INTERVAL 60 SECOND) INTO v_past_60_sec;
        
        DROP TEMPORARY TABLE IF EXISTS tt_Call;
        CREATE TEMPORARY TABLE tt_Call
        AS
		SELECT 'Call' AS 'Channel',COUNT(1) AS totalCall,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_CallHistory CH
        JOIN tb_CallDurationHistory	CDH ON CH.CallHistoryId = CDH.CallHistoryId
		WHERE CH.domainId = p_domainId
        AND  ((CH.createdAt  >= v_past_60_sec)  OR  (CDH.dispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;
        
        DROP TEMPORARY TABLE IF EXISTS tt_Chat;
        CREATE TEMPORARY TABLE tt_Chat
        AS
		SELECT 'Chat' AS 'Channel',COUNT(1) AS totalChat,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_ChatHistory CH
        JOIN tb_ChatDurationHistory	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
		WHERE CH.domainId = p_domainId
        AND ((CH.createdAt >= v_past_60_sec)  OR  (CDH.dispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;
		
        DROP TEMPORARY TABLE IF EXISTS tt_Email;
        CREATE TEMPORARY TABLE tt_Email
        AS
		SELECT 'Email' AS 'Channel',COUNT(1) AS totalEmail,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_EmailHistory CH
        JOIN tb_EmailDurationHistory	CDH ON CH.EmailHistoryId = CDH.EmailHistoryId
		WHERE CH.domainId = p_domainId
        AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;

        DROP TEMPORARY TABLE IF EXISTS tt_SMS;
        CREATE TEMPORARY TABLE tt_SMS
        AS
		SELECT 'SMS' AS 'Channel',COUNT(1) AS totalSMS,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_SMSHistory CH
        JOIN tb_SMSDurationHistory	CDH ON CH.SMSHistoryId = CDH.SMSHistoryId
		WHERE CH.domainId = p_domainId
        AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;
        
        DROP TEMPORARY TABLE IF EXISTS tt_Whatsapp;
        CREATE TEMPORARY TABLE tt_Whatsapp
        AS
        SELECT 'Whatsapp' AS 'Channel',COUNT(1) AS totalWhatsapp,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_WhatsappHistory CH
        JOIN tb_WhatsappDurationHistory	CDH ON CH.WhatsappHistoryId = CDH.WhatsappHistoryId
		WHERE CH.domainId = p_domainId
        AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;

        DROP TEMPORARY TABLE IF EXISTS tt_Facebook;
        CREATE TEMPORARY TABLE tt_Facebook
        AS
        SELECT 'Facebook' AS 'Channel',COUNT(1) AS totalFacebook,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_FacebookHistory CH
		WHERE CH.domainId = p_domainId
        AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;
        
        DROP TEMPORARY TABLE IF EXISTS tt_Instagram;
        CREATE TEMPORARY TABLE tt_Instagram
        AS
        SELECT 'Instagram' AS 'Channel',COUNT(1) AS totalInstagram,DATE_FORMAT(FROM_UNIXTIME(CH.sessionStartTime/1000),'%H:%i:%s') AS ST_TIME
		FROM tb_InstagramHistory CH
		WHERE CH.domainId = p_domainId
        AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		GROUP BY ST_TIME
        ORDER BY ST_TIME;

		SELECT
			(
				SELECT COUNT(*) FROM tb_CallHistory CH
                JOIN tb_CallDurationHistory	CDH ON CH.CallHistoryId = CDH.CallHistoryId
				WHERE CH.domainId = p_domainId
				AND ((CH.createdAt  >= v_past_60_sec)  OR  (CDH.dispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
			)
		  + (
				SELECT COUNT(*) FROM tb_ChatHistory CH 
                JOIN tb_ChatDurationHistory	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
				WHERE CH.domainId = p_domainId
				AND ((CH.createdAt >= v_past_60_sec)  OR  (CDH.dispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
			)
		  + (
				SELECT COUNT(*) FROM tb_EmailHistory CH
				JOIN tb_EmailDurationHistory	CDH ON CH.EmailHistoryId = CDH.EmailHistoryId
				WHERE CH.domainId = p_domainId
				AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
			)
		  + (
				SELECT COUNT(*) FROM tb_SMSHistory CH 
                JOIN tb_SMSDurationHistory	CDH ON CH.SMSHistoryId = CDH.SMSHistoryId
				WHERE CH.domainId = p_domainId
				AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
			)
		  + (
				SELECT COUNT(*) FROM tb_WhatsappHistory CH
				JOIN tb_WhatsappDurationHistory	CDH ON CH.WhatsappHistoryId = CDH.WhatsappHistoryId
				WHERE CH.domainId = p_domainId
				AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CDH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
			)
		  + (
				SELECT COUNT(*) FROM tb_FacebookHistory CH 
				WHERE domainId = p_domainId
				AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
			)
		  + (
				SELECT COUNT(*) FROM tb_InstagramHistory CH
				WHERE domainId = p_domainId
				AND ((CH.createdAt >= v_past_60_sec) OR (CH.DispositionId IS NULL AND DATE(CH.createdAt) = CURDATE() AND CH.AgentId IS NOT NULL AND CH.createdAt  < v_past_60_sec))
		) AS totalCount;

        SELECT * FROM tt_Call;
        SELECT * FROM tt_Chat;
        SELECT * FROM tt_Email;
        SELECT * FROM tt_SMS;
        SELECT * FROM tt_Whatsapp;
        SELECT * FROM tt_Facebook;
        SELECT * FROM tt_Instagram;

SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_live_interaction_dashboardCount` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
