/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_live_interaction_dashboardCount`(
p_domainId			INT
)
BEGIN
		DECLARE v_AgentOccupancy  		INT DEFAULT 0;
        DECLARE v_BotOccupancy 		    INT DEFAULT 0;
        DECLARE v_CustomersWaiting		INT DEFAULT 0;
        DECLARE v_CallBackRequest		INT DEFAULT 0;

SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

	SELECT SUM(MediaCount) INTO v_AgentOccupancy FROM (

			SELECT COUNT(1) AS MediaCount
			FROM tb_CallHistory CH
			JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
			WHERE  CH.domainId = p_domainId AND  IFNULL(CDH.EndTime,0) = 0 AND CDH.AgentId IS NOT NULL AND DATE(CDH.createdAt) = DATE(NOW())
		UNION ALL
			SELECT COUNT(1) AS MediaCount 
			FROM tb_ChatHistory CH
			JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
			WHERE  CH.domainId = p_domainId AND IFNULL(CDH.EndTime,0) =0 AND CDH.AgentId IS NOT NULL AND DATE(CDH.createdAt) = DATE(NOW())
		UNION ALL
			SELECT COUNT(1) AS MediaCount
			FROM tb_EmailHistory EH 
			JOIN tb_EmailDurationHistory EDH	ON EH.EmailHistoryId = EDH.EmailHistoryId
			WHERE EH.DomainId = p_domainId  AND IFNULL(EH.SessionEndTime, 0) = 0 AND EDH.AgentId IS NOT NULL AND DATE(EH.CreatedAt) = DATE(now())
		UNION ALL
			SELECT COUNT(1) AS MediaCount
			FROM tb_WhatsappHistory AS WH
			JOIN tb_WhatsappDurationHistory AS WDH	ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
			WHERE WH.domainId = p_domainId AND IFNULL(WH.sessionEndTime, 0) = 0 AND WDH.AgentId IS NOT NULL AND DATE(WH.createdAt) = DATE(now())
		UNION ALL
			SELECT COUNT(1) AS MediaCount 
			FROM tb_FacebookHistory 
			WHERE domainId = p_domainId AND IFNULL(sessionEndTime, 0) = 0 AND AgentId IS NOT NULL AND DATE(createdAt) = DATE(now())
		UNION ALL
			SELECT COUNT(1) AS MediaCount
			FROM tb_InstagramHistory 
			WHERE domainId = p_domainId AND IFNULL(sessionEndTime, 0) = 0 AND AgentId IS NOT NULL AND DATE(createdAt) = DATE(now())
		
		) AS AgentOccupancy;
        
        
		SELECT SUM(BotCount) INTO v_BotOccupancy  FROM (

			SELECT COUNT(1) AS BotCount
			FROM tb_CallHistory CH
			JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
			WHERE  CH.domainId = p_domainId AND  IFNULL(CDH.EndTime,0) = 0 AND CDH.AgentId IS NULL AND IFNULL(CDH.IsBot,0) = 1 AND DATE(CDH.createdAt) = DATE(NOW())
		UNION ALL
			SELECT COUNT(1) AS BotCount 
			FROM tb_ChatHistory CH
			JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
			WHERE  CH.domainId = p_domainId AND IFNULL(CDH.EndTime,0) = 0 AND CDH.AgentId IS NULL AND IFNULL(CDH.IsBot,0) = 1 AND DATE(CDH.createdAt) = DATE(NOW())
		UNION ALL
			SELECT COUNT(1) AS BotCount
			FROM tb_EmailHistory EH 
			JOIN tb_EmailDurationHistory EDH	ON EH.EmailHistoryId = EDH.EmailHistoryId
			WHERE EH.DomainId = p_domainId  AND IFNULL(EH.SessionEndTime, 0) = 0 AND EDH.AgentId IS NULL AND IFNULL(EDH.IsBot, 0) = 1 AND DATE(EH.CreatedAt) = DATE(now())
		UNION ALL
			SELECT COUNT(1) AS BotCount
			FROM tb_WhatsappHistory AS WH
			JOIN tb_WhatsappDurationHistory AS WDH	ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
			WHERE WH.domainId = p_domainId AND IFNULL(WH.sessionEndTime, 0) = 0 AND WDH.AgentId IS NULL AND IFNULL(WDH.IsBot,0) = 1 AND DATE(WH.createdAt) = DATE(now())
		UNION ALL
			SELECT COUNT(1) AS BotCount 
			FROM tb_FacebookHistory 
			WHERE domainId = p_domainId AND IFNULL(sessionEndTime, 0) = 0 AND AgentId IS NULL AND IFNULL(IsBot,0) = 1  AND DATE(createdAt) = DATE(now())
		UNION ALL
			SELECT COUNT(1) AS BotCount
			FROM tb_InstagramHistory 
			WHERE domainId = p_domainId AND IFNULL(sessionEndTime, 0) = 0 AND AgentId IS NULL AND IFnULL(IsBot,0) = 1 AND DATE(createdAt) = DATE(now())
			
		) AS BotOccupancy;

        
        SELECT COUNT(b1.`sessionId`) INTO v_CustomersWaiting FROM queueWeighTime, 
        JSON_TABLE(queueList, '$[*]' columns(`sessionId` varchar(100) path '$.sessionId')
				)as b1
		WHERE domainId = p_domainId ; 
 
        
        SELECT SUM(CallBackCount) INTO v_CallBackRequest FROM 
        (
			SELECT COUNT(callBack) AS CallBackCount 
			FROM tb_CallHistory
			WHERE domainId = p_domainId 
			AND callBack = 1
		UNION ALL
			SELECT COUNT(1) AS CallBackCount
			FROM tb_ChatHistory 				ch
			LEFT JOIN tb_ChatDurationHistory 	chd ON ch.ChatHistoryId 	= chd.ChatHistoryId	
			WHERE ch.domainId = p_domainId 
			AND ch.CallBackStatus	= 1    
        UNION ALL
			SELECT COUNT(1) AS CallBackCount
			FROM  tb_WhatsappHistory
			WHERE domainId = p_domainId 
			AND isCallback = 1 AND callbackDraft = 0
		UNION ALL
			SELECT COUNT(1) AS CallBackCount
			FROM tb_InstagramHistory
			WHERE domainId = p_domainId 
			AND isCallback = 1 AND callbackDraft = 0
		UNION ALL
			SELECT COUNT(1) AS CallBackCount
            FROM tb_FacebookHistory
            WHERE domainId = p_domainId 
            AND isCallback = 1 AND callbackDraft = 0
        ) AS CallBackRequest;
 
	SELECT v_AgentOccupancy AS AgentOccupancy, v_BotOccupancy AS BotOccupancy, v_CustomersWaiting AS CustomersWaiting, v_CallBackRequest AS CallBackRequest;

SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
