CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_my_plan_queue_permission`(
	 p_qid		INT 
    ,p_domainId	INT 
)
begin
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		SELECT Q.qid,Q.name,Q.description,QP.agentMonitoring,QP.addOrRemove,QP.reportingDashboard,QP.createdAt,QP.updatedAt
		FROM queue Q
        JOIN tb_queue_permission QP ON QP.fk_qid = Q.qid
		WHERE QP.fk_qid = p_qid AND QP.domainId = p_domainId;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
end ;;
