CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_nodes_data`(
		p_domainId			INT,
        p_cfid		VARCHAR(255)
)
BEGIN
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    
	SELECT nodes FROM callFlow WHERE cfid collate utf8mb4_0900_ai_ci = p_cfid AND domainId = p_domainId;
	
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    END ;;
