CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_notification`(
	p_ext varchar(10),
	p_domainId int,
	p_timestamp bigint,
    p_limit  int,
    p_offset int
)
Begin

	DECLARE V_offset int;
	set V_offset = p_offset * p_limit;
    
	
		SELECT a.*
        
        ,ifnull(b.firstName,'New Customer') as customerName
        ,b.primaryPhoneNumber 
      FROM notification a 
      left join customer_contact b on a.coid = b.coid
      WHERE a.domainId = p_domainId AND a.toExt = p_ext and a.timestamp order by a.nId desc
      limit V_offset,p_limit 
      ;
      
      
      SELECT a.*
      
      ,ifnull(b.firstName,'New Customer') as customerName
      ,b.primaryPhoneNumber 
      FROM notification a 
      left join customer_contact b on a.coid = b.coid
      WHERE a.domainId = p_domainId AND a.toExt = p_ext and markAsRead = 0 and a.timestamp order by a.nId desc
      limit V_offset,p_limit ;
	
      select count(*) as unReadCount from notification where domainId = p_domainId AND toExt = p_ext and markAsRead = 0;
     
     
      select count(*) as totalCount from notification where domainId = p_domainId AND toExt = p_ext;
      
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
