CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_outbound_campaign_draft_chats`(
		p_domainId			INT,		
		p_offset			INT,
		p_limit				INT
    )
BEGIN

		DECLARE v_offset INT;
        
        SET v_offset = p_offset * p_limit;
        
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  	
 		SELECT 	OC.campDraftId,OC.sessionId,OC.domainId,OC.title,OC.campaignMessage,OC.createdAt,OC.updatedAt
 		FROM 	tb_outbound_campaign_draft	OC     
 		LEFT JOIN tb_callBlast				CB ON OC.campDraftId = CB.fk_campDraftId
 		WHERE 	OC.domainId 	= p_domainId
 		AND 	CB.fk_campDraftId IS NULL
		ORDER BY OC.updatedAt DESC LIMIT v_offset,p_limit;

      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
