CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_overall_agent_task`(
	 p_domainId			INT
    ,p_agentId			INT
)
BEGIN

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;

		SELECT rid, domainId, agentId, ext, reminderDate, reminderTime, timezone, notes, isSent, createdAt, updatedAt
		FROM tb_ccaas_ai_task_reminder
		WHERE domainId 	= p_domainId
		AND agentId 	= p_agentId
        AND isClosed = 0;

	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	

END ;;
