/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_overall_sla_ai`(
	 p_domainId				INT
	,p_startTmpstmp 		BIGINT
	,p_endTmpstmp 			BIGINT
)
begin

		DECLARE v_totalCall 		INT;
		DECLARE v_closedCall 		INT;
		DECLARE v_totalChat 		INT;
		DECLARE v_closedChat 		INT;
		DECLARE v_totalEmail 		INT;
		DECLARE v_closedEmail 		INT;
		DECLARE v_totalWhatsapp 	INT;
		DECLARE v_closedWhatsapp 	INT;
        
		DECLARE v_avgCallSLA 		INT;
		DECLARE v_avgChatSLA 		INT;
		DECLARE v_avgEmailSLA 		INT;
		DECLARE v_avgWhatsappSLA 	INT;
        
		DECLARE v_totalSMS 			INT;
		DECLARE v_closedSMS 		INT;
		DECLARE v_avgSMSSLA 		INT;
        
		DECLARE v_totalFacebook 	INT;
		DECLARE v_closedFacebook  	INT;
		DECLARE v_avgFacebookSLA  	INT;
        
		DECLARE v_totalInstagram  	INT;
		DECLARE v_closedInstagram  	INT;
		DECLARE v_avgInstagramSLA  	INT;
        
		DECLARE v_totalVideo  		INT;
		DECLARE v_closedVideo  		INT;
		DECLARE v_avgVideoSLA  		INT;
        
		DECLARE v_OverAllSLA 			INT;
		
        DROP TEMPORARY TABLE IF EXISTS tt_Call;
        CREATE TEMPORARY TABLE tt_Call
        AS
		SELECT CH.CallHistoryId
		,CASE WHEN  IFNULL(CDH.EndTime,0) > 0 AND CDH.Duration > 0 AND IFNULL(answeredDuration,0) < 30 THEN 1 ELSE 0 END	closedCallSLA 
		FROM tb_CallHistory CH
		JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
		WHERE CH.domainId = p_domainId
		AND CDH.AgentId IS NOT NULL
		AND CH.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
		
        DROP TEMPORARY TABLE IF EXISTS tt_Chat;
        CREATE TEMPORARY TABLE tt_Chat
        AS
		SELECT CH.ChatHistoryId
		,CASE WHEN IFNULL(CDH.EndTime,0) > 0 AND CDH.Duration > 0 AND IFNULL(answeredDuration,0) < 30 THEN 1 ELSE 0 END	closedChatSLA  
		FROM tb_ChatHistory 					CH
		JOIN tb_ChatDurationHistory 			CDH ON  CH.ChatHistoryId = CDH.ChatHistoryId
		
		WHERE CH.domainId = p_domainId
		AND CDH.AgentId IS NOT NULL
		AND CH.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;

        DROP TEMPORARY TABLE IF EXISTS tt_Email;
        CREATE TEMPORARY TABLE tt_Email
        AS
		SELECT 	SH.EmailHistoryId
		,CASE WHEN  ifnull(SH.IsSessionClosed,0) = 1  and TIME_FORMAT(TIMEDIFF(FROM_UNIXTIME(SessionEndTime/1000),FROM_UNIXTIME(SessionStartTime/1000)),'%H') <= ec.emailThreshold THEN 1 ELSE 0 END	closedEmailSLA
		FROM tb_EmailHistory SH
		JOIN tb_EmailDurationHistory SDH ON SH.EmailHistoryId = SDH.EmailHistoryId
		JOIN email_config 				ec	ON	ec.emailAddress = SH.ToEmail AND ec.domainId = SH.domainId                     
		WHERE SH.domainId = p_domainId
		AND SDH.AgentId IS NOT NULL
		AND SH.SessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
                
        DROP TEMPORARY TABLE IF EXISTS tt_SMS;
        CREATE TEMPORARY TABLE tt_SMS
        AS
		SELECT 	SH.SMSHistoryId
		,CASE WHEN  ifnull(SH.IsSessionClosed,0) = 1  and TIME_FORMAT(TIMEDIFF(FROM_UNIXTIME(SessionEndTime/1000),FROM_UNIXTIME(SessionStartTime/1000)),'%H') <= 24 THEN 1 ELSE 0 END	closedSMSSLA
		FROM tb_SMSHistory SH
		JOIN tb_SMSDurationHistory SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
		WHERE SH.domainId = p_domainId
		AND SDH.AgentId IS NOT NULL
		AND SH.SessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
        
        DROP TEMPORARY TABLE IF EXISTS tt_Whatsapp;
		CREATE TEMPORARY TABLE tt_Whatsapp
		AS
		SELECT WH.WhatsappHistoryId
		,CASE WHEN IFNULL(WH.IsSessionClosed, 0) = 1 AND WH.SessionEndTime IS NOT NULL AND WH.SessionStartTime IS NOT NULL AND (WH.SessionEndTime - WH.SessionStartTime) BETWEEN 0 AND (24 * 60 * 60 * 1000) THEN 1 ELSE 0 END AS closedWhatsappSLA
		FROM tb_WhatsappHistory WH
		JOIN tb_WhatsappDurationHistory WDH    ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
		WHERE WH.domainId = p_domainId
		AND WDH.AgentId IS NOT NULL
		AND WH.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
        
        DROP TEMPORARY TABLE IF EXISTS tt_Facebook;
        CREATE TEMPORARY TABLE tt_Facebook
        AS
		SELECT F.FacebookHistoryId
        
        ,CASE WHEN IFNULL(IsSessionClosed, 0) = 1 AND SessionEndTime IS NOT NULL AND SessionStartTime IS NOT NULL AND (SessionEndTime - SessionStartTime) BETWEEN 0 AND (24 * 60 * 60 * 1000) THEN 1 ELSE 0 END AS closedFacebookSLA
		FROM tb_FacebookHistory F
		WHERE F.domainId = p_domainId
		AND F.AgentId IS NOT NULL
		AND F.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
                
        DROP TEMPORARY TABLE IF EXISTS tt_Instagram;
        CREATE TEMPORARY TABLE tt_Instagram
        AS
		SELECT F.InstagramHistoryId
		
        ,CASE WHEN IFNULL(IsSessionClosed, 0) = 1 AND SessionEndTime IS NOT NULL AND SessionStartTime IS NOT NULL AND (SessionEndTime - SessionStartTime) BETWEEN 0 AND (24 * 60 * 60 * 1000) THEN 1 ELSE 0 END AS closedInstagramkSLA
		FROM tb_InstagramHistory F
		WHERE F.domainId = p_domainId
		AND F.AgentId IS NOT NULL
		AND F.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
                
		DROP TEMPORARY TABLE IF EXISTS tt_Video;
        CREATE TEMPORARY TABLE tt_Video
        AS
		SELECT VH.VideoHistoryId
		,CASE WHEN IFNULL(VH.sessionEndTime,0) > 0 AND VDH.agentDuration > 0 THEN 1 ELSE 0 END AS closedVideoSLA 
		FROM tb_VideoHistory VH
        JOIN tb_VideoDurationHistory VDH ON VH.VideoHistoryId = VDH.VideoHistoryId
		WHERE VH.domainId = p_domainId
		AND VDH.AgentId IS NOT NULL
		AND VH.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
        
        SELECT count(1),SUM(closedCallSLA) INTO v_totalCall,v_closedCall FROM tt_Call;
        SELECT count(1),SUM(closedChatSLA) INTO v_totalChat,v_closedChat FROM tt_Chat;
        SELECT count(1),SUM(closedEmailSLA) INTO v_totalEmail,v_closedEmail FROM tt_Email;
        SELECT count(1),SUM(closedSMSSLA) INTO v_totalSMS,v_closedSMS FROM tt_SMS;
        SELECT count(1),SUM(closedWhatsappSLA) INTO v_totalWhatsapp,v_closedWhatsapp FROM tt_Whatsapp;
        SELECT count(1),SUM(closedFacebookSLA) INTO v_totalFacebook,v_closedFacebook FROM tt_Facebook;
        SELECT count(1),SUM(closedInstagramkSLA) INTO v_totalInstagram,v_closedInstagram FROM tt_Instagram;
        SELECT count(1),SUM(closedVideoSLA) INTO v_totalVideo,v_closedVideo FROM tt_Video;
                
        SELECT CASE WHEN IFNULL(v_totalCall,0) = 0 THEN 0 ELSE (IFNULL(v_closedCall,0)/v_totalCall) * 100 END INTO v_avgCallSLA;
        SELECT CASE WHEN IFNULL(v_totalChat,0) = 0 THEN 0 ELSE (IFNULL(v_closedChat,0)/v_totalChat) * 100 END INTO v_avgChatSLA;
        SELECT CASE WHEN IFNULL(v_totalEmail,0) = 0 THEN 0 ELSE (IFNULL(v_closedEmail,0)/v_totalEmail) * 100 END INTO v_avgEmailSLA;
        SELECT CASE WHEN IFNULL(v_totalSMS,0) = 0 THEN 0 ELSE (IFNULL(v_closedSMS,0)/v_totalSMS) * 100 END INTO v_avgSMSSLA;
        SELECT CASE WHEN IFNULL(v_totalWhatsapp,0) = 0 THEN 0 ELSE (IFNULL(v_closedWhatsapp,0)/v_totalWhatsapp) * 100 END INTO v_avgWhatsappSLA;
        SELECT CASE WHEN IFNULL(v_totalFacebook,0) = 0 THEN 0 ELSE (IFNULL(v_closedFacebook,0)/v_totalFacebook) * 100 END INTO v_avgFacebookSLA;
        SELECT CASE WHEN IFNULL(v_totalInstagram,0) = 0 THEN 0 ELSE (IFNULL(v_closedInstagram,0)/v_totalInstagram) * 100 END INTO v_avgInstagramSLA;
        SELECT CASE WHEN IFNULL(v_totalVideo,0) = 0 THEN 0 ELSE (IFNULL(v_closedVideo,0)/v_totalVideo) * 100 END INTO v_avgVideoSLA;
        
        SELECT v_avgCallSLA AS avgCallSLA,v_avgChatSLA AS avgChatSLA,v_avgWhatsappSLA AS avgWhatsappSLA,v_avgEmailSLA AS avgEmailSLA,v_avgSMSSLA AS avgSMSSLA,v_avgFacebookSLA AS avgFacebookSLA,v_avgInstagramSLA AS avgInstagramSLA,v_avgVideoSLA AS avgVideoSLA;
        
        SELECT (SUM(v_avgCallSLA + v_avgChatSLA + v_avgWhatsappSLA + v_avgEmailSLA + v_avgSMSSLA + v_avgFacebookSLA + v_avgInstagramSLA + v_avgVideoSLA) / 8) INTO v_OverAllSLA;
        
        SELECT v_OverAllSLA AS OverAllSLA;
        
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_predictiveDialler` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_predictiveDialler`(
 	p_domainId INT
  )
BEGIN
	START TRANSACTION;
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT concat('[',GROUP_CONCAT(JSON_OBJECT 
        ("agent_extn",U.ext			
         					, 	"agent_name",U.UserName		
         					,	'userId',CAST(U.UserID as CHAR(50))
         					,	"email",U.emailId
         					, 	"agent_status",A_S.statusName	
         					,	"agent_statusId",A_S.aid
         					,	"isVoice",U.isVoice
         					,	"isVoiceCallTransfer",A_S.isVoiceCallTransfer
                            ,	"roleid",U.roleid
         					)  ORDER BY U.roleid DESC, U.updatedAt ASC
        ),']') AgentDetails	
         	FROM 	tb_User						U        
         	JOIN 	agent_status				A_S		ON 	A_S.aid			= U.StatusID
         												AND	A_S.domainId	= U.domainId
         												AND A_S.aid   		= U.StatusID
    		WHERE 	U.domainId				= p_DomainId
 		AND 	U.roleid 				IN (3,5,6)  
 		AND 	U.voice					= 1 
 		AND 	A_S.isVoice 			= 1
 		AND 	A_S.isVoiceCallTransfer = 0
  		AND		U.isAvailableForVoice	= 1
         AND 	U.outboundCampaignCall	= 1
  		ORDER BY U.roleid DESC,U.updatedAt ASC;                                           
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
	COMMIT;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_predictiveDialler_cutomerContact_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_predictiveDialler_cutomerContact_dtl`(
	 p_domainId 	INT
    ,p_doNotDisturb TINYINT 
    ,p_customerType VARCHAR(100) 
    ,p_search		VARCHAR(500)
    ,p_offset		INT
    ,p_limit		INT
)
begin
		DECLARE v_offset INT;
        
        SET v_offset = p_limit * p_offset;
        
		SELECT DISTINCT customerType
		FROM customer_contact 
		WHERE domainId = p_domainId
        AND IFNULL(customerType,'')<>'';
        
		SELECT coid,concat(IFNULL(firstName,''),' ',IFNULL(lastName,'')) as customerName,primaryPhoneNumber,doNotDisturb,primaryEmail,IFNULL(customerType,'') as customerType
		FROM customer_contact 
		WHERE domainId = p_domainId 
		AND IFNULL(primaryPhoneNumber,0) > 0 
		AND primaryPhoneNumber REGEXP '^[0-9]+$'
        AND (IFNULL(p_doNotDisturb,'')='' OR doNotDisturb = p_doNotDisturb)
        AND	((customerType = p_customerType) OR IFNULL(p_customerType,'')='')
        AND (IFNULL(p_search,'')='' OR (firstName LIKE CONCAT('%',p_search,'%') OR lastName LIKE CONCAT('%',p_search,'%')));
       
	end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_predictiveDialler_info` */;
