/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_predictiveDialler_info`(
)
begin		
		
        DROP TEMPORARY TABLE IF EXISTS tt_timeConvert;
        CREATE TEMPORARY TABLE tt_timeConvert AS
		select ttt.ttid,ttt.fk_cid,ttt.startTime,ttt.working_day,cb.timeZone 
        ,REGEXP_REPLACE(SUBSTRING_INDEX(SUBSTRING_INDEX(timeZone, 'GMT ', -1), ':', 1), '^[+-]', '') * 60 as timezone_hour_extracted
        ,SUBSTRING_INDEX(SUBSTRING_INDEX(timeZone, ':', -1), ' ', 1) as timezone_minute_extracted
		,SUBSTRING(SUBSTRING_INDEX(timeZone, 'GMT', -1), 2, 1) as extracted_sign
        ,cb.outboundNumber,cb.campaignMessageType,cb.campaignMessage,cb.textSpeechFile,cb.contact,cb.importContact,cb.importContactFile
        ,cb.domainId,cb.companyName,cb.triggerType
        from tb_predictiveDialler_timeToTrigger_info ttt 
        join tb_predictiveDialler_dailyTrigger_dtl dt on ttt.fk_cid = dt.fk_cid
        join tb_predictiveDialler cb on cb.cid = dt.fk_cid
        where curdate() between startDate and endDate
        and ttt.working_day = dayname(curdate());
        
		DROP TEMPORARY TABLE IF EXISTS tt_timeConvert_final;
        CREATE TEMPORARY TABLE tt_timeConvert_final AS
        SELECT tt.ttid,tt.fk_cid,tt.startTime,tt.working_day,tt.timeZone,tt.outboundNumber,tt.campaignMessageType,tt.campaignMessage,tt.textSpeechFile
        ,tt.contact,tt.importContact,tt.importContactFile
        ,(CURRENT_TIME() + INTERVAL tt.timezone_hour_extracted MINUTE + INTERVAL tt.timezone_minute_extracted MINUTE) as currentTime_to_trigger
        
        ,tt.startTime  as time_to_trigger,tt.domainId,tt.companyName,tt.triggerType
		FROM tt_timeConvert tt;
        
        SELECT ttid as triggeredId,fk_cid as blastId,startTime,working_day,timeZone,outboundNumber,campaignMessageType,campaignMessage,textSpeechFile,contact,importContact,importContactFile
        ,domainId,companyName,triggerType
		FROM tt_timeConvert_final 
        WHERE TIME_FORMAT(time_to_trigger,'%H:%i') =  TIME_FORMAT(currentTime_to_trigger,'%H:%i');

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
