CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_predictiveDialler_overAll_dtl`(	
	p_blastId 	INT
	,p_domainId INT
)
begin

	SELECT cb.cid,cb.domainId,cb.blastName,cb.blastDescription,cb.triggerType,cb.triggerDailyFile,cb.triggerCustomFile,cb.timeZone,cb.outboundNumber,cb.campaignMessageType
	,cb.campaignMessage,cb.textSpeechFile,cb.blastStatus,cb.createdBy,cb.blastId,cb.contactType,cb.contact,cb.importContact,cb.importContactFile,cb.createdAt,cb.updatedAt
    ,ctd.startDate,ctd.endDate,ctd.selectedDays,ctd.noOfRecall,ctd.recallInterval,ctd.dailyHour
    ,u.UserName as creatorName,cb.companyName
	FROM  	tb_predictiveDialler cb
    JOIN 	tb_predictiveDialler_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
    JOIN	tb_User u ON cb.createdBy = u.ext AND cb.domainId = u.domainId
    WHERE 	cb.domainId = p_domainId
    AND		(IFNULL(p_blastId,'')='' OR cb.cid = p_blastId);
    

end ;;
DELIMITER ;
