CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_predictive_analytics_trending_support`(
p_domainId int,
p_startTmpstmp BIGINT, 
p_endTmpstmp BIGINT
)
Begin

		drop temporary table if exists tt_trend_support ;
    	create temporary table tt_trend_support
        (
        id int auto_increment primary key,
        ChannelType varchar(30),
        QueueId int,
        customerNumber varchar(50)
        );
	
    insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Call',CD.QueueId,CH.customerNumber
	from tb_CallDurationHistory CD
	join tb_CallHistory CH on CD.CallHistoryId = CH.CallHistoryId
	where CH.domainId = p_domainId and CH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Chat',CD.QueueId,CH.CustomerId
	from tb_ChatDurationHistory CD
	join tb_ChatHistory CH on CD.ChatHistoryId = CH.ChatHistoryId
	where CH.domainId = p_domainId and CH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'SMS',SD.QueueId,SH.customerNumber
	from tb_SMSHistory  SH
	JOIN tb_SMSDurationHistory SD on SH.SMSHistoryId = SD.SMSHistoryId
	where SH.domainId = p_domainId and SH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Email',ED.QueueId,EH.CustomerId
	from tb_EmailHistory  EH
	JOIN tb_EmailDurationHistory ED on EH.EmailHistoryId = ED.EmailHistoryId
	where EH.domainId = p_domainId and EH.CreatedAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Whatsapp',WD.QueueId,WH.customerNumber
	from tb_WhatsappHistory  WH
	join tb_WhatsappDurationHistory WD on WD.WhatsappHistoryId = WH.WhatsappHistoryId
	where WH.domainId = p_domainId and WH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Facebook',FH.QueueId,FH.customerFacebookId
	from tb_FacebookHistory  FH
	where FH.domainId = p_domainId and FH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Instagram',IH.queueId,IH.customerInstagramId
	from tb_InstagramHistory  IH
	where IH.domainId = p_domainId and IH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);

	insert into tt_trend_support(ChannelType,QueueId, customerNumber)
	select Distinct 'Videomeet',VD.QueueId,VH.customerNumber
	from tb_VideoDurationHistory  VD
	join tb_VideoHistory VH on VH.VideoHistoryId = VD.VideoHistoryId
	where VH.domainId = p_domainId and VD.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);
    
    select ChannelType,TS.QueueId,QU.name,count(*) as cnt
    from tt_trend_support TS
	LEFT join queue QU on TS.QueueId = QU.qid
    GROUP BY ChannelType,TS.QueueId,QU.name;
    
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
