CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_profile_mapping_priority_by_qid`(
	p_domainId int,
	p_qid int
)
Begin
	select RM.rqid,RM.qid,RM.chat,RM.priority,
		 RM.rqmid,RM.delay_in_seconds ,RM.domainId
		,CASE WHEN  RP.routingMethod = 'Skill Based Routing' THEN 2
		WHEN RP.routingMethod = 'Long wait time Based Routing' THEN 1 
		ELSE 0 END AS routingMethod
    from routingqueueprofilemapping 	RM 
    join routing_profile 				RP ON RP.rid = RM.rqmid
    join tb_User						U  ON U.routing_profile_id = RM.rqmid	
    where RM.qid = p_qid 
    and RM.domainId  =  p_domainId
    order by priority asc
    limit 1;
End ;;
DELIMITER ;
