CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_question_ans`(
	p_domainId			INT,
	p_chatFlowId		INT,
    p_intent			TEXT
)
BEGIN
			
		SELECT mapFlow 
			FROM question_answer 
			WHERE domainId = p_domainId 
				AND chatFlowId = p_chatFlowId
				AND intent COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%',p_intent,'%') 
                AND IFNULL(mapFlow,'') COLLATE utf8mb4_0900_ai_ci != '' 
			ORDER BY questionId DESC;
            
		
END ;;
