DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_QueueSettingsCustomTypeInfo`(
    p_qid int,
    p_domainId int,
    p_cli varchar(250)
    )
Begin
	DECLARE v_delay_in_seconds		SMALLINT;
    DECLARE v_routingMethod			TINYINT;
    DECLARE v_businessHourId		INT;
    DECLARE v_isBusinessHoursResult	TINYINT;
    DECLARE v_holidayPrompt			TEXT;
    
	select hoursOfOperatioId into v_businessHourId
	from queue b where qid = p_qid and domainId = p_domainId;
                    
	call ccaas_get_businessHoursValidation_InnerSP(v_businessHourId);
    
	/* Determine whether today is a holiday, within business hours, or outside business hours. from the above inner sp
	isHoliday:
		0 = Not a holiday
		1 = Current date is a holiday
	Business_Hours_Holiday_Flag:
		0 = Current date is a holiday
		1 = Not a holiday
	isBusinessHours:
		0 = Current time is outside business hours
		1 = Current time is within business hours
		2 = Current day is a holiday
	holidayPrompt:
		If isBusinessHours = 2, display the holiday prompt.
	*/
		        
	 SELECT CASE WHEN Business_Hours_Holiday_Flag = 'true'
	 THEN 0 ELSE isBusinessHours END INTO v_isBusinessHoursResult
	 FROM tt_businessHourLogic; 
     
     SELECT CASE WHEN isHoliday = 1
	 THEN 2 ELSE isBusinessHours END,holidayPrompt INTO v_isBusinessHoursResult,v_holidayPrompt
	 FROM tt_businessHourLogic; 
                   
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
		SELECT  RM.delay_in_seconds,
				CASE WHEN  RP.routingMethod = 'Skill Based Routing' THEN 2
			WHEN RP.routingMethod = 'Long wait time Based Routing' THEN 1 
			ELSE 0 END 
			INTO v_delay_in_seconds,v_routingMethod 
		 from routingqueueprofilemapping 	RM 
		 join routing_profile 				RP ON RP.rid = RM.rqmid
		 join tb_User						U  ON U.routing_profile_id = RM.rqmid	
		 where RM.qid = p_qid 
		 and RM.domainId  =  p_domainId
		 order by priority asc
		 limit 1;
		 
			select JSON_OBJECT("routingProfile",JSON_OBJECT("delay_in_seconds",v_delay_in_seconds,"routingMethod",v_routingMethod),
			"queueSettings",JSON_OBJECT
					(
						"qid",b.qid
						,"name",b.name
						,"domainId",b.domainId
						,"settingAudio",b.settingAudio
						,"announcement",b.announcement
						,"maximumCallers",b.maximumCallers
						,"maximumWaitTime",b.maximumWaitTime
						,"OutboundCallerId",b.OutboundCallerId
						,"outBoundNumber",b.outBoundNumber
						,"maxCallHandlingTimeMM",b.maxCallHandlingTimeMM
						,"maxCallHandlingTimeSS",b.maxCallHandlingTimeSS
						,"callWrapUpTime",b.callWrapUpTime
						,"outBoundCallStatus",b.outBoundCallStatus
						,"hoursOfOperatioId",b.hoursOfOperatioId
						,"hours_of_operation",b.hours_of_operation
						,"outOfBusinessHours",b.outOfBusinessHours
						,"status",b.status
						,"type",b.type
						,"hoursOfOperation",v_isBusinessHoursResult
                        ,"holidayPrompt",IFNULL(v_holidayPrompt,'')
						,"agentCount",(	select count(*) 
										from tb_User U 
										where U.domainId = p_domainId and U.routing_profile_id in ( select qm.rqmid from routingqueueprofilemapping qm 
										  where qm.qid in (select qb.qid from queue qb where qb.domainId = p_domainId and qb.qid = p_qid)and qm.domainId = p_domainId))
						)
					)  jsoncol
		  from queue b where qid = p_qid and domainId = p_domainId;
          
		 DROP TEMPORARY TABLE IF EXISTS tt_businessHourLogic;
                   
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      
    
    End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_queue_detailed_view_for_myplan` */;
