/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_queue_detailed_view_for_myplan`(
		p_qid		INT 
		,p_domainId	INT 
)
begin

	DECLARE v_reporting_user_name VARCHAR(1500);

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
			
            
            SELECT DISTINCT GROUP_CONCAT(ru.UserName) INTO v_reporting_user_name 
			FROM queue q
			JOIN tb_User u ON q.qid = u.queueId
			LEFT JOIN tb_User ru ON ru.UserID = u.report_to_UserID
			WHERE q.domainId = p_domainId
			AND q.qid = p_qid
            AND ru.UserName IS NOT NULL
            AND u.roleid IN (3,5,6)
            GROUP BY u.UserName;
            
            SELECT description,updatedAt,v_reporting_user_name AS reporting_user_name,name
			FROM queue
            WHERE domainId = p_domainId
			AND qid = p_qid;
            
			SELECT
				u.UserName,
				u.isActive AS user_active_status,
				u.createdAt AS user_created_date,
				q.qid,
				q.name,
				q.description,
				q.updatedAt			
			FROM queue q
			JOIN tb_User u ON q.qid = u.queueId
			WHERE q.domainId = p_domainId
			AND q.qid = p_qid
            AND u.roleid IN (3,5,6);

	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
