CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_queue_user_login_log`(
p_domainId	INT 
,p_queueId	INT
)
begin

	WITH CTE AS(
	SELECT U.UserID,U.UserName,Q.name AS queueName,LT.createdAt 
	,U.isActive,LT.ext,U.ProfileImage,U.roleid
	FROM tb_User U
	JOIN logInSessionHistory LT ON U.ext = LT.ext AND U.domainId = LT.domainId
	JOIN queue Q ON Q.qid = U.queueId
	WHERE U.domainId = p_domainId
	AND U.queueId = p_queueId
	AND CAST(LT.createdAt AS DATE) = CURDATE()
	) SELECT UserID, UserName, queueName, createdAt AS login_date, isActive, ext, ProfileImage, roleid, 'Login Successfull' AS 'errmsg'
	FROM CTE
    ORDER BY login_date DESC;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
