CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_queue_voice_callback_report`(
	p_startTmpstmp 	BIGINT,
	p_endTmpstmp 	BIGINT,
	p_domainId 		INT,    	
	p_queueId		VARCHAR(250),	
	p_offset 		INT,
	p_Limit 		INT	
     )
sp_return: BEGIN  

		DECLARE v_offset 					INT;
		DECLARE v_Total_Count 				INT; 

		DECLARE v_CurrentStartTmpstmp 		BIGINT;
		DECLARE v_CurrentEndTmpstmp 		BIGINT;
		DECLARE v_PrevStartTmpstmp 			BIGINT;
		DECLARE v_PrevEndTmpstmp 			BIGINT; 
		DECLARE v_TmpstmpInterval			BIGINT;	
		DECLARE v_callBackReceived 			INT;
		DECLARE v_callBackReturend 			INT;
		DECLARE v_callBackanswered 			INT;
		DECLARE v_callBackUnanswered 		INT;
		DECLARE v_prevCallBackReceived 		INT;
		DECLARE v_prevCallBackReturend 		INT;
		DECLARE v_prevcallBackanswered 		INT;
		DECLARE v_prevCallBackUnanswered 	INT;
		DECLARE v_callAbandoned				INT;
		DECLARE v_prevcallAbandoned			INT;
		DECLARE v_Duration 					INT;
		DECLARE v_maxHandlingTime 			INT;
		DECLARE v_prevDuration 				INT;
		DECLARE v_prevmaxHandlingTime 		INT;
    		  
    	SET v_offset = p_offset *p_Limit;
       
       IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_CurrentStartTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp;  END IF; 	
    	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_CurrentEndTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  								
    	  
       SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
       SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
       
  		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
  		CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
              
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
		CREATE TEMPORARY TABLE temp_AllqueueId
		SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

		DROP TEMPORARY TABLE IF EXISTS temp_callHistory; 
		CREATE TEMPORARY TABLE temp_callHistory AS
		SELECT 	CH.CallHistoryId
			,	CH.callBack
			,	CH.CallBackCallHistoryId
			,	CH.domainId
			,	CASE WHEN CH.callBack = 2 THEN 1 ELSE 0 END answeredCalls
            ,	CH.IsAbandoned as callAbandoned
            ,	CH.sessionStartTime
            ,	CDH.QueueId
            ,	AQ.queueName
		FROM 	tb_CallHistory 			CH
        JOIN 	tb_CallDurationHistory	CDH ON CDH.CallHistoryId = CH.CallHistoryId
        LEFT JOIN temp_AllqueueId 		AQ 	ON CDH.QueueId = AQ.qid
		
		WHERE 	CH.domainId 			= p_domainId 
		AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
		AND 	CH.callBack				IN (1,2)  
		AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <>''));
        

		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
		CREATE TEMPORARY TABLE temp_callDurationHistory AS
		SELECT 	t_A.CallHistoryId 	
			,	t_A.CallBackCallHistoryId
            ,	t_A.sessionStartTime
			,	SUM(IFNULL(CDH.Duration,0)) 	AS Duration
			,	t_A.QueueId as queueId
            ,	t_A.callAbandoned
		FROM 	temp_callHistory 			t_A
        JOIN 	tb_CallDurationHistory		CDH ON CDH.CallHistoryId = t_A.CallBackCallHistoryId
        LEFT JOIN 	temp_queueIds			QU	ON QU.queueId = CDH.QueueId
		WHERE 	t_A.domainId = p_domainId
		GROUP BY t_A.sessionStartTime,t_A.CallHistoryId,t_A.CallBackCallHistoryId, t_A.QueueId, t_A.callAbandoned; 

		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory_calc; 
		CREATE TEMPORARY TABLE temp_callDurationHistory_calc AS
		SELECT 	t_A.queueName			AS queueName
			,	t_DH.queueId
			,	t_DH.sessionStartTime
			,	COUNT(1)  				AS callBackReceived
			,	SUM(answeredCalls)		AS callBackReturend
			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 0 ELSE 1 END) AS callBackAnswered
			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 1 ELSE 0 END) AS callBackUnanswered
			,	t_H.callAbandoned		AS callAbandoned	
			,	SUM(t_DH.Duration)		AS Duration	
			,	MAX(Duration)			AS maxHandlingTime
		FROM 	temp_callHistory 			t_H		
		LEFT JOIN temp_callDurationHistory 	t_DH	ON t_DH.CallHistoryId	= t_H.CallHistoryId
        LEFT JOIN temp_AllqueueId			t_A		ON t_A.qid				= t_DH.queueId
		GROUP BY t_A.queueName,t_DH.queueId, t_DH.sessionStartTime, t_H.callAbandoned;
        
   
       SELECT SUM(callBackReceived),SUM(callBackReturend),SUM(callBackUnanswered),sum(callBackAnswered),SUM(callAbandoned) , SUM(Duration), sum(maxHandlingTime)
       INTO v_callBackReceived,v_callBackReturend,v_callBackUnanswered, v_callBackanswered, v_callAbandoned, v_Duration, v_maxHandlingTime
       FROM temp_callDurationHistory_calc
       WHERE sessionStartTime between v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;
       
       SELECT SUM(callBackReceived),SUM(callBackReturend),SUM(callBackUnanswered),sum(callBackAnswered),SUM(callAbandoned)  , SUM(Duration), sum(maxHandlingTime)
       INTO v_prevCallBackReceived,v_prevCallBackReturend,v_prevCallBackUnanswered, v_prevcallBackanswered, v_prevcallAbandoned, v_prevDuration, v_prevmaxHandlingTime
       FROM temp_callDurationHistory_calc
       WHERE sessionStartTime between v_PrevStartTmpstmp and v_PrevEndTmpstmp;

   	
       SELECT * FROM temp_AllqueueId;
       
		SELECT	v_callBackReceived 												as TotalCount
			,	IFNULL((v_callBackReceived-v_prevCallBackReceived)*100,0) 		as DiffTotalPercent
			,	IFNULL(v_callBackReturend,0) 									as TotalCallBackReturend
			,	IFNULL((v_callBackReturend-v_prevCallBackReturend)*100,0) 		as DiffCallBackReturend
			,	IFNULL(v_callBackUnanswered,0) 									as TotalcallBackUnanswered
			,	IFNULL((v_callBackUnanswered-v_prevCallBackUnanswered)*100,0) 	as DiffCallBackUnanswered;
            
  
  
    
   SELECT 'All Queue'																					as queueName
   		,IFNULL(v_callBackReceived,0) 																	as callBackReceived
   		,IFNULL(v_callBackReturend,0) 																	as callBackReturend
   		,IFNULL(v_callBackanswered,0) 																	as callBackAnswered
   		,IFNULL(v_callBackUnanswered,0)  																as callBackUnanswered
   		,IFNULL(v_prevcallAbandoned,0) 																	as abandonedCallback
   		,IFNULL(v_Duration,0) 																			as callBackDuration
   		,ROUND(IFNULL(((v_Duration/1000)/IF(IFNULL(v_callBackanswered,0)=0,1,v_callBackanswered))*100,0),2) 		as avgHandlingTime
   		,IFNULL(v_maxHandlingTime,0) 																	as maxHandlingTime
   		,ROUND(IFNULL((v_callBackReturend/IF(IFNULL(v_callBackReceived,0)=0,1,v_callBackReceived))*100,0),2)		as overallConversationRate
   		,ROUND(IFNULL((v_callBackanswered/IF(IFNULL(v_callBackReceived,0)=0,1,v_callBackReceived))*100,0),2)		as callbackSuccessRate
     
   UNION ALL
    	SELECT queueName																				as queueName
   		 ,SUM(IFNULL(callBackReceived,0))																	as callBackReceived
   		 ,SUM(IFNULL(callBackReturend,0))																	as callBackReturend
   		 ,SUM(IFNULL(callBackAnswered,0)) 																	as callBackAnswered
   		 ,SUM(IFNULL(callBackUnanswered,0)) 																	as callBackUnanswered
   		 ,SUM(IFNULL(callAbandoned,0)) 																		as abandonedCallback
   		 ,SUM(IFNULL(Duration,0))																			as callBackDuration
   		 ,ROUND(IFNULL(((SUM(Duration)/1000)/IF(IFNULL(SUM(callBackAnswered),0)=0,1,SUM(callBackAnswered)))*100,0),2)	as avgHandlingTime
   		 ,SUM(IFNULL(maxHandlingTime,0))																		as maxHandlingTime
   		 ,ROUND(IFNULL((SUM(callBackReturend)/IF(IFNULL(SUM(callBackReceived),0)=0,1,SUM(callBackReceived)))*100,0),2)	as overallConversationRate
   		 ,ROUND(IFNULL((SUM(callBackAnswered)/IF(IFNULL(SUM(callBackReceived),0)=0,1,SUM(callBackReceived)))*100,0),2)	as callbackSuccessRate
   	FROM  temp_callDurationHistory_calc 
    WHERE sessionStartTime between v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
    GROUP BY queueName;

     end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
