CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_routing_queue_profile_mapping_info`(
  p_qid int,
  p_domain_id int
  )
Begin
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT UserID,ext,UserName,  p_qid as qid,
     a.domainId 
     FROM tb_User a 
     join agent_status b on a.domainId = b.domainId and a.StatusID = b.aid
     WHERE a.domainId = p_domain_id
  	AND routing_profile_id IN (SELECT c.rqmid FROM routingqueueprofilemapping c WHERE c.qid = p_qid and c.domainId = p_domain_id)
  	AND b.statusName IN ('Ready', 'Transfer Only') 
  	AND a.isVoice = 1 AND a.roleid IN (5,6);
 
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
