CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_schedule_report_info`(
	p_domainId int
)
begin

IF p_domainId IS NOT NULL THEN 
select  uid,domainId,reportName,recurrence,rrule,isRecurr,timezone,isSetPassword,setPassword,fileType,toAddr,subject,message,createDate,nextOccurrence, StartDataRange, EndDataRange
from tb_schedule_report_master_dtl where domainId = p_domainId ;
ELSE
