/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_search_list_queue`(
	p_name		VARCHAR(250) 
    ,p_domainId	INT 
)
begin

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		
        IF IFNULL(p_name,'') <> ''
        THEN
			SELECT q.qid,q.name,q.description,q.domainId,q.createdAt,q.updatedAt,q.settingAudio,q.announcement,q.maximumCallers,q.maximumWaitTime
			,q.OutboundCallerId,q.outBoundNumber,q.maxCallHandlingTimeMM,q.maxCallHandlingTimeSS,q.callWrapUpTime,q.outBoundCallStatus
			,q.hoursOfOperatioId,q.hours_of_operation,q.outOfBusinessHours,q.status,q.type,c.name AS businessName
            FROM queue q
            LEFT JOIN custom_hours c ON c.cid = q.hoursOfOperatioId
			WHERE q.domainId = p_domainId and q.name collate utf8mb4_0900_ai_ci like concat('%',p_name,'%');
		ELSE    
			SELECT q.qid,q.name,q.description,q.domainId,q.createdAt,q.updatedAt,q.settingAudio,q.announcement,q.maximumCallers,q.maximumWaitTime
			,q.OutboundCallerId,q.outBoundNumber,q.maxCallHandlingTimeMM,q.maxCallHandlingTimeSS,q.callWrapUpTime,q.outBoundCallStatus
			,q.hoursOfOperatioId,q.hours_of_operation,q.outOfBusinessHours,q.status,q.type,c.name AS businessName
            FROM queue q
            LEFT JOIN custom_hours c ON c.cid = q.hoursOfOperatioId
			WHERE q.domainId = p_domainId;
		END IF;

	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
