/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_search_question_answer`(
	p_domainId 			int
    ,p_searchByValue 	varchar(255)
    ,p_chatFlowId 		int
    ,p_offset			int
	,p_limit 			int 
)
begin

		DECLARE v_offset 	INT;
		DECLARE v_limit		INT;
        
        SET v_offset = p_Limit * p_offset; 
        SET v_limit  = p_Limit;
		
        DROP TEMPORARY TABLE IF EXISTS tt_result;
        CREATE TEMPORARY TABLE tt_result AS
		SELECT questionId, domainId, uuid, question, answer, mapFlow, language, intent, keywords, status, version
		, createdAt, updatedAt, sent, helpfull, notHelpfull, chatFlowId, embedding, websiteId, discription, websiteUrl, baseName 
		FROM question_answer 
		WHERE (question collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_searchByValue,'%')) 
		AND  domainId = p_domainId
		AND chatFlowId = p_chatFlowId
		LIMIT v_offset,p_Limit;
		
        SELECT questionId, domainId, uuid, question, answer, mapFlow, language, intent, keywords, status, version
		, createdAt, updatedAt, sent, helpfull, notHelpfull, chatFlowId, embedding, websiteId, discription, websiteUrl, baseName 
        FROM tt_result;
        
		SELECT COUNT(*) as count 
		FROM tt_result ;
    
		DROP TEMPORARY TABLE IF EXISTS tt_result;
    
end ;;
DELIMITER ;
