CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_session_conservation`(
    p_domainId int,
    p_sessionId varchar(150),
    p_channelType varchar(20)
    )
Begin
    
  	if p_channelType = 'Chat' then
  		select a.ChatDurationHistoryId,a.ChatHistoryId,a.Message,a.createdAt,a.updatedAt 
  		from tb_ChatMessage a where a.ChatHistoryId in (select b.ChatHistoryId from tb_ChatHistory b where b.sessionId collate utf8mb4_unicode_ci =  p_sessionId and b.domainId = p_domainId);
  	Elseif p_channelType = 'Call' then
  		select CM.CallDurationHistoryId,CM.CallHistoryId,CM.Message,CM.createdAt,CM.updatedAt 
  		from tb_CallMessage CM join tb_CallDurationHistory CDH on CM.CallDurationHistoryId  = CDH.CallDurationHistoryId        
		where CM.CallHistoryId in (select CH.CallHistoryId from tb_CallHistory CH where CH.sessionId collate utf8mb4_unicode_ci =  p_sessionId and CH.domainId = p_domainId)
        and CDH.IsBot = 1;
	Elseif p_channelType = 'Email' then
		select CM.EmailHistoryId,CM.Message,CM.CreatedAt,CM.UpdatedAt 
  		from tb_EmailMessage CM 
        join tb_EmailDurationHistory CDH on CM.EmailHistoryId  = CDH.EmailHistoryId
        join tb_EmailHistory CH on CM.EmailHistoryId = CH.EmailHistoryId
		where CH.SessionId collate utf8mb4_unicode_ci = p_sessionId and CH.DomainId = p_domainId
        and CDH.IsBot = 1;
	Elseif p_channelType = 'Whatsapp' then
		select CM.WhatsappHistoryId,CM.Message,CM.CreatedAt,CM.UpdatedAt 
		from tb_WhatsappMessage CM 
		join tb_WhatsappDurationHistory CDH on CM.WhatsappHistoryId  = CDH.WhatsappHistoryId
		join tb_WhatsappHistory CH on CM.WhatsappHistoryId = CH.WhatsappHistoryId
		where CH.SessionId collate utf8mb4_unicode_ci = p_sessionId and CH.DomainId = p_domainId;
		

	ELSEif p_channelType = "Instagram" then											
		select t1.InstagramHistoryId, t1.Message, t1.createdAt, t1.updatedAt  
		FROM tb_InstagramMessage t1
		JOIN  tb_InstagramHistory  t2  ON t1.InstagramHistoryId = t2.InstagramHistoryId 
		WHERE t2.SessionId = p_sessionId and t2.domainId = p_domainId;
        
	ELSEIF  p_channelType = "Facebook" then 										
		select t1.FacebookHistoryId, t1.Message, t1.createdAt, t1.updatedAt  
		FROM tb_FacebookMessage t1
		JOIN  tb_FacebookHistory  t2  ON t1.FacebookHistoryId = t2.FacebookHistoryId 
		WHERE t2.sessionId = p_sessionId and t2.domainId = p_domainId;
    
  	End if;
      
      
    End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
