DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_session_queue_agent_info`(
      p_domainId int,
      p_sessionId varchar(250)
      )
Begin
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      	SELECT sessionId,'Call' as channelType,d.name as queueName 
          FROM tb_CallHistory a 
          left join tb_CallDurationHistory b on a.CallHistoryId=b.CallHistoryId
         
          left join queue d on d.qid = b.QueueId
          WHERE sessionId COLLATE utf8mb4_unicode_ci = p_sessionId AND a.domainId = p_domainId
          ORDER BY b.CallDurationHistoryId DESC limit 1;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
