/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_sesssion_history_dashboard_feautres_testing`(
   p_startTmpstmp bigint, 
   p_endTmpstmp bigint, 
   p_Timezone varchar(55), 
   p_domainId int, 
   p_ext int,
   p_qid int)
begin 
 			DECLARE v_AgentId		                   INT;
             DECLARE v_roleid		                   INT;
          	DECLARE v_Total			    	           INT;		
             DECLARE v_Service_level			           INT;	
             DECLARE v_Queued_customers		           INT;	
             DECLARE v_Resolved				          INT;
 			DECLARE v_Unresolved			          INT;	
 			DECLARE v_Abandoned				          INT;	
 			DECLARE v_Transferred			          INT;		
 			DECLARE v_Callback_requested	          INT;	
 			DECLARE v_Missed				          INT;	
 			DECLARE v_startTmpstmp			          BIGINT;	
 			DECLARE v_endTmpstmp			          BIGINT;	
             DECLARE v_domainid                        INT;
             DECLARE v_ext                             INT;
 			DECLARE v_QueuedCustomers			       INT;	
             DECLARE v_output_value                     TEXT;
             DECLARE  v_InteractionWithin30Secs           INT;
 			DECLARE	 v_Inbound                           INT;
 			DECLARE  v_Totaltimespenthandlingcustomer    INT;
 			DECLARE  v_Userlogintime                    INT;
 			DECLARE  v_foroccupancyratestateduration    INT;
 			DECLARE  v_Percentageofcallblocked          INT;
 			DECLARE  v_incomingsessionsqueue            INT;
 			DECLARE  v_totalfirstresponsetime          INT;
 			DECLARE  v_totalwaitdurationtime           INT;
 			DECLARE  v_Totalcallduration              INT;
 			DECLARE  v_Totalholdduration              INT;
 			DECLARE  v_aftercallworktime              INT;
             DECLARE  v_Total_call                     INT;
 			DECLARE	 v_qid                            INT;
 
      SET v_domainId = p_domainId;
      SET v_ext		= p_ext;
      SET v_qid      = p_qid;
      
 	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
  	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;   
    
 	DROP TEMPORARY TABLE IF EXISTS tt_call_list;
  	CREATE TEMPORARY TABLE tt_call_list	
	select  cth.IsInBound,
			cth.Istransferred,
			cth.sessionStartTime,
			tu.ext as UserExt,
			cth.dialDuration,
			cth.waitDuration,
			cth.callDuration,
			cth.afterCallWorkTime,
			tu.UserName as agentDetails,
			tu.callTypeId as callType,
			'Call' as channelType,
			ctd.StartTime as agentConnectTime,
			ctd.EndTime as agentDisconnectTime,
			ctd.AgentHoldDuration,
			lsh.logInTimestamp,
			lsh.logOutTimestamp ,		

			sts.timerStatus		state,
			cth.domainId                 
        FROM tb_CallHistory                 cth 
       LEFT JOIN logInSessionHistory       	lsh     ON  cth.domainId = lsh.domainId 
       LEFT JOIN state_timer               	st      ON  cth.domainId = st.domainId
       LEFT JOIN tb_stateTimerStatus		sts		ON 	sts.timerStatusId = st.timerStatusId
        
       LEFT JOIN tb_User                   tu         ON   tu.UserID = cth.AssignedTo and cth.domainId = tu.domainId   
       LEFT JOIN tb_CallDurationHistory    ctd        ON  cth.CallHistoryId = ctd.CallHistoryId
 	  where cth.domainId = v_domainId 
 	  and cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
   
      
    
 		SELECT 	UserID , roleid 
 	 	INTO	v_AgentId, v_roleid 
 		FROM 	tb_User
 		WHERE 	domainId 	= v_domainId
 		AND 	ext			= v_ext
 	    and 	isActive	= 1 
 		limit 1;
       
     select count(json_length(ifnull(a.queueList,0)))   into v_incomingsessionsqueue
 				from  queueWeighTime a
  				where a.queueType  = 'call'
                 and a.domainId = v_domainId
                 and a.qid      = v_qid
                 limit 1; 
        
       
             select 
 			 
             CASE WHEN dialDuration < 30 THEN 1 ELSE 0 END 
             ,count(IsInBound)  
 			,COUNT(CASE WHEN dialDuration > 0 and (a.UserExt = v_ext or ifnull(v_ext,0)=0)and a.callType is not null and a.channelType is not null and a.agentConnectTime <> 0 and a.agentDisconnectTime <> 0 and a.sessionStartTime <> 0  THEN 1 ELSE 0 END) 	                     
 			,COUNT(CASE WHEN a.logInTimestamp = v_startTmpstmp and a.logOutTimestamp = v_endTmpstmp or ifnull(v_endTmpstmp,0)=0 and a.logInTimestamp <> 0 and a.logOutTimestamp <> 0  THEN 1 ELSE 0 END)                                                                             
 			,COUNT(CASE WHEN a.state  not in ('Not Ready','Away','Offline') AND (a.UserExt = v_ext or ifnull(v_ext,0)=0)  THEN 1 ELSE 0 END )                                                                                                                                         
             ,COUNT(CASE when  a.callType = 'inbound' and a.callType is not null and (a.UserExt = v_ext or ifnull(v_ext,0)=0) AND  a.state not in ('connected','Agent on Hold','hold') and a.state is not null and a.sessionStartTime <> 0  and a.channelType = 'Call'THEN 1 ELSE 0 END) 
             ,count(CASE WHEN (a.agentDetails = v_ext or ifnull(v_ext,0)=0) and a.dialDuration is not null and a.channelType is not null THEN 1 ELSE 0 END)         
             ,COUNT(CASE WHEN (a.agentDetails = v_ext or ifnull(v_ext,0)=0)  and a.waitDuration is not null and a.channelType is not null THEN 1 ELSE 0 END)        
             ,COUNT(CASE WHEN a.callDuration <> 0 and a.callType is not null and (UserExt = v_ext or ifnull(v_ext,0)=0)and a.domainId = v_domainId  THEN 1 ELSE 0 END)       
 			,count(CASE when  a.agentHoldDuration <> 0 and (a.agentDetails = v_ext or ifnull(v_ext,0)=0)THEN 1 ELSE 0 END)                                              
            ,sum(ifnull(a.afterCallWorkTime/1000,0))
          
              ,count(CASE when a.callType is not null AND (a.UserExt = v_ext or ifnull(v_ext,0)=0) AND a.channelType = 'Call'THEN 1 ELSE 0 END )
 
             INTO	          v_InteractionWithin30Secs
 						     ,v_Inbound
 						     ,v_Totaltimespenthandlingcustomer
 							 ,v_Userlogintime
 							 ,v_foroccupancyratestateduration
 							 ,v_Percentageofcallblocked
 							 
 							 ,v_totalfirstresponsetime
 							 ,v_totalwaitdurationtime
 							 ,v_Totalcallduration 
 							 ,v_Totalholdduration
 							 ,v_aftercallworktime
                              ,v_Total_call 
                      
              FROM
              tt_call_list     a
             group by v_InteractionWithin30Secs;
            
            select              v_InteractionWithin30Secs
 						     ,v_Inbound
 						     ,v_Totaltimespenthandlingcustomer
 							 ,v_Userlogintime
 							 ,v_foroccupancyratestateduration
 							 ,v_Percentageofcallblocked
 							 ,v_totalfirstresponsetime
 							 ,v_totalwaitdurationtime
 							 ,v_Totalcallduration 
 							 ,v_Totalholdduration
 							 ,v_aftercallworktime
                              ,v_Total_call ;
            
            
       end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
