CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_skill_details`(
 	 p_domainId			INT 
     ,p_search			VARCHAR(1000)
     ,p_limit			INT 
     ,p_offset			INT 
 )
begin
 		DECLARE v_offset		INT;
		DECLARE v_limit			INT;
		DECLARE v_total_skill 	INT;
        
        SET v_offset = p_Limit * p_offset; 
        SET v_limit  = p_Limit;
        
         SELECT COUNT(*) INTO v_total_skill
		FROM skills 
		WHERE domainId = p_domainId;
        
        IF (p_offset IS NULL AND p_limit IS NULL)
			THEN 
				SET v_offset = 0,v_limit = v_total_skill;
		END IF;
         
         SELECT a.sid,a.skill_name,a.skill_description,a.domainId,a.status,a.type
         ,(select count(b.usid) FROM skillMapping b JOIN tb_User u ON b.usid = u.UserID WHERE b.skid=a.sid AND a.domainId = b.domainId) AS no_of_agnt_sk 
         ,a.createdAt
 		FROM skills a 
 		WHERE a.domainId = p_domainId
         AND (IFNULL(p_search,'') = '' OR (skill_name collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_search,'%') OR skill_description collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_search,'%')) )
         GROUP BY a.sid,a.skill_name ORDER BY a.sid DESC
         LIMIT v_offset,v_limit;
 
 		SELECT COUNT(*) AS total_count
 		FROM skills 
 		WHERE (IFNULL(p_search,'') = '' OR (skill_name collate utf8mb4_0900_ai_ci  LIKE CONCAT('%',p_search,'%') OR skill_description collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_search,'%')) )
 		AND domainId = p_domainId ORDER BY createdAt DESC, updatedAt DESC 
 		LIMIT v_offset,v_limit;
 
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_skill_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
