CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_social_media_configuration_check`(
	 p_domainId			INT 
    ,p_channel_name		VARCHAR(50)
)
begin

	DECLARE v_errcode 	INT DEFAULT 0;

	IF p_channel_name = 'Whatsapp'
    THEN

		if exists(select 1 from tb_WhatsappConfiguration where domainId = p_domainId limit 1)
        then
			set v_errcode = 1;
		end if;
	END IF;
    
	IF p_channel_name = 'Facebook'
    THEN
		if exists(select 1 from tb_FacebookConfiguration where domainId = p_domainId and FacebookPageId IS NOT NULL limit 1)
        then
			set v_errcode = 1;
		end if;
	END IF;
	
    IF p_channel_name = 'Instagram'
    THEN
		if exists(select 1 from tb_InstagramConfiguration where domainId = p_domainId and InstagramPageId IS NOT NULL limit 1)
        then
			set v_errcode = 1;
		end if;
    END IF;
		
        SELECT v_errcode AS isCompleted;
        
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
