/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_task_reminder`(
)
begin		
		
        DROP TEMPORARY TABLE IF EXISTS tt_timeConvert;
        CREATE TEMPORARY TABLE tt_timeConvert AS
        select rid,domainId,agentId,reminderDate,reminderTime,timezone,notes,isSent,createdAt,updatedAt
        
        
		,SUBSTRING(SUBSTRING_INDEX(timezone, 'GMT', -1), 2, 1) as extracted_sign
        ,ABS(
			(REPLACE(SUBSTRING_INDEX(SUBSTRING_INDEX(timezone, 'GMT ', -1), ':', 1), '−', '-') * 60) +
			SUBSTRING_INDEX(SUBSTRING_INDEX(timezone, ':', -1), ' ', 1)
		) AS extracted_time_minute
        ,ext
        from tb_ccaas_ai_task_reminder
        where isSent = 0
        and isClosed = 0;
                            
		DROP TEMPORARY TABLE IF EXISTS tt_timeConvert_final;
        CREATE TEMPORARY TABLE tt_timeConvert_final AS
        SELECT rid,domainId,agentId,reminderDate,reminderTime,timezone,notes,isSent,createdAt,updatedAt
        
        
        ,extracted_sign
        ,CASE 
			WHEN extracted_sign = '+'
				 THEN DATE_ADD(CURRENT_TIME(), INTERVAL extracted_time_minute MINUTE)
			ELSE DATE_SUB(NOW(), INTERVAL extracted_time_minute MINUTE)
		END AS currentTime_to_trigger
        ,ext
        ,CONCAT(reminderDate,' ',reminderTime) AS reminder_date_time
		FROM tt_timeConvert tt;
                          
		SELECT rid,domainId,agentId,reminderDate,reminderTime,timezone,notes,isSent,createdAt,updatedAt,ext
		FROM tt_timeConvert_final 
        WHERE DATE_FORMAT(reminder_date_time,'%Y-%m-%d %H:%i') =  DATE_FORMAT(currentTime_to_trigger,'%Y-%m-%d %H:%i');
        
        DROP TEMPORARY TABLE IF EXISTS tt_triggerId;
        CREATE TEMPORARY TABLE tt_triggerId AS
        SELECT rid 
		FROM tt_timeConvert_final 
        WHERE DATE_FORMAT(reminder_date_time,'%Y-%m-%d %H:%i') =  DATE_FORMAT(currentTime_to_trigger,'%Y-%m-%d %H:%i');
                      
		UPDATE tb_ccaas_ai_task_reminder
        SET isSent = 1
        WHERE rid IN (SELECT rid FROM tt_triggerId); 
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
