CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_unclosed_session_conservation_info`(
   p_channelType varchar(20)
   ,p_domainId	int
   )
Begin
   
 	if p_channelType = 'Whatsapp' then
 		select 'Whatsapp' as channelType,c.Message,a.sessionId,a.customerNumber 
         from tb_WhatsappHistory a join tb_WhatsappDurationHistory b on a.WhatsappHistoryId = b.WhatsappHistoryId
 		join tb_WhatsappMessage c on a.WhatsappHistoryId = c.WhatsappHistoryId  
 		where 
         a.domainId= p_domainId
 		and a.IsSessionClosed = 0 ;
         
 	Elseif p_channelType = 'Facebook' then
     
 		select 'Facebook' as channelType,c.Message,a.sessionId,a. customerFacebookId as customerNumber 
         from tb_FacebookHistory a 
 		join tb_FacebookMessage c on a.FacebookHistoryId = c.FacebookHistoryId 
 		where 
         a.domainId= p_domainId
 		and a.IsSessionClosed = 0 ;
         
 	Elseif p_channelType = 'Instagram' then
     
 		select 'Instagram' as channelType,c.Message,a.sessionId,a. customerinstagramId as customerNumber 
         from tb_InstagramHistory a 
 		join tb_InstagramMessage c on a.instagramHistoryId = c.instagramHistoryId 
 		where 
         a.domainId= p_domainId
 		and a.IsSessionClosed = 0 ;
         
 	End if;
     
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
