CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_updateAgentState`(	
 	p_domainId int,  	
     p_ext int,	
     p_isVoice int,  	
     p_isVoiceCallTransfer int,	
     p_isChat int, 	
     p_isChatTransfer int,
 	p_isEmail int, 
 	p_isEmailTransfer int,	
     P_statusName VARCHAR(20)
   )
Begin
   
 	declare v_errcode int default -1;
 	declare v_errmsg varchar(55) default 'Not updated'; 
     declare v_statusid int;
     
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     select aid into v_statusid from agent_status where domainId = p_domainId and statusName = P_statusName limit 1;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 	if exists(select 1 from tb_User where domainId = p_domainId AND ext = p_ext limit 1) then  
     
 		UPDATE tb_User 
 		SET updatedAt = now(),
 			isVoice = p_isVoice, 
 			isVoiceCallTransfer = p_isVoiceCallTransfer, 
 			isChat = p_isChat,
 			isChatTransfer = p_isChatTransfer,
 			isEmail = p_isEmail,
 			isEmailTransfer = p_isEmailTransfer,
 			statusName= v_statusid
 		WHERE domainId = p_domainId AND ext = p_ext;
         
         if found_rows()>0 then
    				set v_errcode = 0;
    				set v_errmsg = 'updated successfully';
    			end if;    
 	end if;
     
     select v_errcode as errcode, v_errmsg as errmsg;
     
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
