CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_user_details_by_role`(
     p_roleId   INT,
     p_domainId INT
)
BEGIN
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    SELECT  
        U.UserID,
        U.UserName,
        U.emailId,
        U.report_to_UserID,
        RU.UserName AS report_to_UserName,
        U.ext,
        U.isActive,
        U.createdAt,
        U.updatedAt,
        U.stateTimer,
        U.AssignedTime,
        U.chatFlag,
        U.ProfileImage,
        U.emp_id,
        Q.name AS queueName
    FROM tb_User U
    LEFT JOIN tb_User RU ON RU.domainId = U.domainId AND RU.UserID = U.report_to_UserID 
    JOIN queue Q ON Q.qid = U.queueId
    WHERE U.roleid = p_roleId
	AND U.domainId = p_domainId;

    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
DELIMITER ;
