CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_user_language`(
	 p_domainId 			int
    ,p_ext					int
    ,p_contactCenterNumber 	bigint
)
begin
	
	DECLARE v_sec_language JSON;
	DECLARE v_primaryLanguage VARCHAR(100);
	DECLARE v_secondaryLanguage VARCHAR(1000);
	DECLARE v_isMultilingualStatus TINYINT;
	
	SELECT isMultilingualStatus INTO v_isMultilingualStatus 
    FROM call_configuration
    WHERE domainId = p_domainId
    AND contactCenterNumber = p_contactCenterNumber;
  
	SELECT
        SUBSTRING_INDEX(
			SUBSTRING_INDEX(pri_language, '"addonName":"', -1),
			'"',
			1
		  ) INTO v_primaryLanguage
		 FROM tb_userAddonLanguageInfo
		WHERE domainId = p_domainId AND ext = p_ext;
        
		SELECT sec_language INTO v_sec_language
		FROM tb_userAddonLanguageInfo
        WHERE domainId = p_domainId AND ext = p_ext;
                
        SELECT GROUP_CONCAT(name) INTO v_secondaryLanguage
		FROM JSON_TABLE(
			v_sec_language,
			'$[*]' COLUMNS (
				name VARCHAR(100) PATH '$.addonName'
			)
		) AS jt;
        
        SELECT v_primaryLanguage as primaryLanguage,v_secondaryLanguage as secondaryLanguage
        ,(CASE WHEN v_isMultilingualStatus = 1 THEN 1 ELSE 0 END ) as isLanguageAddon;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
