/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_user_login_log`(
p_domainId	INT 
,p_UserID	INT
)
begin

	WITH CTE AS(
	SELECT U.UserID,U.UserName,LT.createdAt 
	,U.isActive,LT.ext,U.ProfileImage,U.roleid
	FROM tb_User U
	JOIN logInSessionHistory LT ON U.ext = LT.ext AND U.domainId = LT.domainId
	WHERE U.domainId = p_domainId
	AND U.UserID = p_UserID
	AND CAST(LT.createdAt AS DATE) = CURDATE()
	) SELECT UserID, UserName, createdAt AS login_date, isActive, ext, ProfileImage, roleid, 'Login Successfull' AS 'errmsg'
	FROM CTE
    ORDER BY login_date DESC;

end ;;
DELIMITER ;
