CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_user_queue_list`(
	p_domainId 	int
	, p_ext 	int
)
Begin
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		select JSON_ARRAYAGG(JSON_OBJECT("qid",CAST(a.queueId AS UNSIGNED)
										,"priority",1
										,"delay",0
										,"routingMethod",null
										,"agent_skills", (select JSON_ARRAYAGG(JSON_OBJECT("Skid",Skid,"value",ss.skill_name))AA 
											from skillMapping SK 
											join skills ss on ss.sid = SK.Skid and ss.domainId = SK.domainId
											and  SK.usid = a.UserID where SK.domainId = p_domainId )
                                              ))  jsoncol
		from tb_User a 
		where a.domainId = p_domainId and a.ext = p_ext
		and a.isVoice = 1 
		and a.isActive = 1
        and a.roleid in (3,5,6);
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
end ;;
DELIMITER ;
