CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_user_queue_weigh_time_details`(
 p_ext int,
 p_domainId int
 )
Begin
 
 	declare v_routing_profile_id int;
     declare v_qid int;
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT routing_profile_id into v_routing_profile_id FROM tb_User WHERE ext = p_ext AND domainId = p_domainId;
     
     SELECT qid into v_qid FROM routingqueueprofilemapping WHERE rqmid = v_routing_profile_id AND domainId = p_domainId order by priority asc;
 
 	SELECT * FROM queueWeighTime WHERE qid = v_qid AND domainId = p_domainId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 End ;;
DELIMITER ;
