CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_user_status_details`(
	p_domainId 	INT
)
Begin
 
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		select 	b.statusName,
			a.UserID, a.UserName, a.emailId, a.directNumber, a.address, a.routing_profile_id, a.report_to_UserID, a.sipLoginId, a.companyId, a.domainId, a.ext
			,a.isActive, a.callTypeId, a.roleid, a.localization, a.currentSession
			,b.isVoice,a.isVoiceCallTransfer
			,b.isChat
			, a.isChatTransfer, a.isEmail, a.isEmailTransfer, 
			a.StatusID, a.isSms, a.isSocialMedia, a.companyName, a.addSkill, a.voice, a.chat, a.email, a.sms, a.socialMedia, a.stateTimer
			,b.isVoiceCallTransfer AS isVoiceCallTransfer_AgentStatus, b.isChatTransfer AS isChatTransfer_AgentStatus, b.isEmailTransfer AS isEmailTransfer_AgentStatus
			,a.queueId AS quId
		from tb_User 							a 
		join agent_status 					b 	on a.StatusID 				= b.aid
		where a.domainId =  p_domainId
		and b.statusName = 'Ready'; 
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 	 
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
