CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_user_status_details_UMN`(
         	 p_domainId int    
          )
Begin  	
 
				SELECT 
					JSON_ARRAYAGG(
						JSON_OBJECT(
							'statusName', b.statusName,
							'UserID', a.UserID,
							'UserName', a.UserName,
							'emailId', a.emailId,
							'directNumber', a.directNumber,
							'domainId', a.domainId,
							'ext', a.ext,
							'isActive', a.isActive,
							'callTypeId', a.callTypeId,
							'roleid', a.roleid,
							'currentSession', a.currentSession,
							'isVoice', b.isVoice,
							'isVoiceCallTransfer', a.isVoiceCallTransfer,
							'StatusID', a.StatusID,
							'voice', a.voice,
							'isVoiceCallTransfer_AgentStatus', b.isVoiceCallTransfer,
							'quId', a.queueId
						)
					) AS jsoncol
				FROM tb_User a
				JOIN agent_status b ON a.StatusID = b.aid
				WHERE a.domainId = p_domainId
				AND b.statusName = 'Ready';
       
        End ;;
DELIMITER ;
