CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_videomeet_session_history_details`(
    p_domainId	INT
)
begin

	SELECT  VH.VideoHistoryId,VH.sessionStartTime,VH.sessionEndTime,VH.customerNumber,VH.domainId,VH.IsInBound,VH.dialDuration,VH.disconnectedBy
			,VH.queueDuration,VH.calledNumber,VH.waitDuration,VH.recordingTypeId,VH.CustomerId,VH.videoDuration,VH.createdAt,VH.updatedAt,VH.IsAbandoned
			,VH.businessStartTime,VH.businessEndTime,VH.meetingId,VH.sessionId
			,VDH.VideoDurationHistoryId,VDH.AgentId,VDH.QueueId,VDH.dispositionId,VDH.summary,VDH.subject,VDH.afterVideoWorkTime,VDH.SentimentalScore
			,VDH.sentimentalScoreCustomer,VDH.sentimentalScoreAgent,VDH.ticketId
			,VM.Message
	FROM tb_VideoHistory 			VH
	JOIN tb_VideoDurationHistory	VDH	ON VH.VideoHistoryId 	= VDH.VideoHistoryId
	JOIN tb_VideoMessage			VM	ON VDH.VideoHistoryId = VM.VideoHistoryId
	WHERE VH.domainId = p_domainId;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
