CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_get_video_history_by_sessionId`(
  p_sessionId			varchar(250),
  p_domainId			INT
  )
BEGIN
  
  	DECLARE v_emailAddress		varchar(200);
  	DECLARE v_your_number		varchar(255);
      
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
      
  	SELECT 	emailAddress INTO v_emailAddress
  	FROM 	email_config 
  	WHERE 	domainId = p_domainId
  	LIMIT 1;
  
  	SELECT 	your_number	INTO v_your_number
  	FROM 	did_purchase 
  	WHERE 	domainId	= p_domainId
  	AND 	isSmsIn 	= 1 
  	AND 	isSmsOut 	= 1 LIMIT 1;   
      
  	SELECT 'Video' AS 'channeltype'
      ,v_emailAddress AS companyEmailAddress, v_your_number AS companySMSNumber
  	,C.* 
  	FROM 	tb_VideoHistory C
  	WHERE 	sessionId 	collate utf8mb4_0900_ai_ci = p_sessionId
 	AND 	domainId	= p_domainId; 
     
 	
     
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_get_video_history_id_by_meeting_id` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_video_history_id_by_meeting_id`(
	p_domainId			INT
    ,p_meetingId		VARCHAR(255)
	,p_AgentId			INT
)
begin

WITH video_details AS(
SELECT VH.VideoHistoryId,VDH.VideoDurationHistoryId,ROW_NUMBER() OVER(PARTITION BY VDH.VideoHistoryId ORDER BY VDH.VideoDurationHistoryId DESC) AS RN
FROM tb_VideoHistory VH 
JOIN tb_VideoDurationHistory VDH ON VH.VideoHistoryId = VDH.VideoHistoryId
WHERE VH.meetingId collate utf8mb4_0900_ai_ci= p_meetingId
AND VH.domainId	= p_domainId 
AND VDH.AgentId = p_AgentId
)SELECT VideoHistoryId,VideoDurationHistoryId
FROM video_details
WHERE RN = 1;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
