/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_get_voice_callback_report`(
 	p_startTmpstmp 	BIGINT,
 	p_endTmpstmp 	BIGINT,
 	p_domainId 		INT,
 	p_agentId		VARCHAR(250),
 	p_offset 		INT,
 	p_Limit 		INT	
 )
BEGIN  
  
 	DECLARE v_offset 		INT;
 	DECLARE v_Total_Count 	INT; 
 
 	DECLARE v_CurrentStartTmpstmp 		BIGINT;
 	DECLARE v_CurrentEndTmpstmp 		BIGINT;
 	DECLARE v_PrevStartTmpstmp 			BIGINT;
 	DECLARE v_PrevEndTmpstmp 			BIGINT; 
 	DECLARE v_TmpstmpInterval			BIGINT;	
 	DECLARE v_callBackReceived 			INT;
 	DECLARE v_callBackReturend 			INT;
 	DECLARE v_callBackUnanswered 		INT;
 	DECLARE v_prevCallBackReceived 		INT;
 	DECLARE v_prevCallBackReturend 		INT;
 	DECLARE v_prevCallBackUnanswered 	INT;
     		  
 	SET v_offset = p_offset *p_Limit;
 
 	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_CurrentStartTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp;  END IF; 	
 	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_CurrentEndTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  								
 
 	SET v_TmpstmpInterval 	= v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
 	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
 	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
        
     	DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId BIGINT);
     
     	CALL split(p_agentId,',');	INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
               
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
     	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
     	CREATE TEMPORARY TABLE temp_AllagentId
     	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId;
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
              
     	DROP TEMPORARY TABLE IF EXISTS temp_callHistory; 
     	CREATE TEMPORARY TABLE temp_callHistory AS
 		SELECT 		CH.CallHistoryId
 				,	CH.callBack
 				,	CH.CallBackCallHistoryId
 				,	CH.domainId
 				,	CASE WHEN CH.callBack = 2 THEN 1 ELSE 0 END answeredCalls
                 ,	CDH.agentId as agentId
 				
                 
 		FROM 		tb_CallHistory 			CH
         JOIN 		tb_CallDurationHistory	CDH ON	CH.CallHistoryId = CDH.CallHistoryId
 		LEFT JOIN 	temp_agentIds			t_A	ON t_A.agentId = CH.assignedTo
 		WHERE 		CH.domainId 			= p_domainId 
 		AND 		CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
 		AND 		CH.callBack				IN (1,2) 
 		AND 		(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <>''));
        
 		DROP TEMPORARY TABLE IF EXISTS temp_callHistory_diff; 
 		CREATE TEMPORARY TABLE temp_callHistory_diff AS
 		SELECT 	CH.CallHistoryId
 			,	CH.callBack
 			,	CH.CallBackCallHistoryId
 			,	CH.domainId
 			,	CASE WHEN CH.callBack = 2 THEN 1 ELSE 0 END answeredCalls
             ,	CDH.agentId as agentId
 			
             
 		FROM 	tb_CallHistory 			CH
         JOIN 		tb_CallDurationHistory	CDH ON	CH.CallHistoryId = CDH.CallHistoryId
 		LEFT	JOIN 	temp_agentIds			t_A	ON t_A.agentId = CH.assignedTo
 		WHERE 	CH.domainId 			= p_domainId 
 		AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp 
 		AND 	CH.callBack				IN (1,2) 
 		AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <>''));
    
 		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
 		CREATE TEMPORARY TABLE temp_callDurationHistory AS
 		SELECT 	t_A.CallHistoryId 		 		
 			,	SUM(CDH.Duration) 	AS Duration
 			,	t_A.agentId
 		FROM 	temp_callHistory 			t_A
 		LEFT	JOIN 	tb_CallDurationHistory		CDH	    ON CDH.CallHistoryId 	= t_A.CallBackCallHistoryId    
 		WHERE 	t_A.domainId = p_domainId
 		GROUP BY t_A.CallHistoryId, t_A.agentId; 
        
 		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory_diff; 
 		CREATE TEMPORARY TABLE temp_callDurationHistory_diff AS
 		SELECT 	t_A.CallHistoryId 		 		
 			,	SUM(CDH.Duration) 	AS Duration
 			,	t_A.agentId
 		FROM 	temp_callHistory_diff 		t_A
 		LEFT	JOIN 	tb_CallDurationHistory		CDH	    ON CDH.CallHistoryId 	= t_A.CallBackCallHistoryId    
 		WHERE 	t_A.domainId = p_domainId
 		GROUP BY t_A.CallHistoryId, t_A.agentId; 
        
 		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory_calc; 
 		CREATE TEMPORARY TABLE temp_callDurationHistory_calc AS
 		SELECT 	t_A.UserName			AS agentName
 			,	COUNT(1)  				AS callBackReceived
 			,	SUM(answeredCalls)		AS callBackReturend
 			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 0 ELSE 1 END) AS callBackAnswered
 			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 1 ELSE 0 END) AS callBackUnanswered
 			,	0						AS callAbandoned	
 			,	SUM(t_DH.Duration)		AS Duration	
 			,	MAX(Duration)			AS maxHandlingTime
 		FROM 	temp_callHistory 			t_H
 		LEFT JOIN 	temp_AllagentId				t_A		ON t_A.UserID			= t_H.agentId
 		LEFT JOIN temp_callDurationHistory 	t_DH	ON t_DH.CallHistoryId	= t_H.CallHistoryId
 		GROUP BY t_A.UserName;
    
 		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory_calc1; 
 		CREATE TEMPORARY TABLE temp_callDurationHistory_calc1 AS
 		SELECT 	
 			COUNT(1)  				AS 	callBackReceived
 			,	SUM(answeredCalls)		AS callBackReturend
 			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 0 ELSE 1 END) AS callBackAnswered
 			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 1 ELSE 0 END) AS callBackUnanswered
 			,	0						AS callAbandoned	
 			,	SUM(t_DH.Duration)		AS Duration	
 			,	MAX(Duration)			AS maxHandlingTime
 		FROM 	temp_callHistory 			t_H
 		LEFT  JOIN 	temp_AllagentId				t_A		ON t_A.UserID			= t_H.agentId
 		LEFT JOIN temp_callDurationHistory 	t_DH	ON t_DH.CallHistoryId	= t_H.CallHistoryId;
    
 		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory_calc_diff; 
 		CREATE TEMPORARY TABLE temp_callDurationHistory_calc_diff AS
 		SELECT 	t_A.UserName			AS agentName
 			,	COUNT(1)  				AS callBackReceived
 			,	SUM(answeredCalls)		AS callBackReturend
 			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 0 ELSE 1 END) AS callBackAnswered
 			,	SUM(CASE WHEN IFNULL(t_DH.Duration,0) = 0 THEN 1 ELSE 0 END) AS callBackUnanswered
 		FROM 	temp_callHistory_diff 				t_H
 		LEFT  JOIN 	temp_AllagentId						t_A		ON t_A.UserID			= t_H.agentId
 		LEFT JOIN temp_callDurationHistory_diff 	t_DH	ON t_DH.CallHistoryId	= t_H.CallHistoryId
 		GROUP BY t_A.UserName;
        
        SELECT SUM(callBackReceived) as callBackReceived,SUM(callBackReturend) as callBackReturend,SUM(callBackUnanswered) as callBackUnanswered INTO v_callBackReceived,v_callBackReturend,v_callBackUnanswered
        FROM temp_callDurationHistory_calc1;
        
        SELECT SUM(callBackReceived) as callBackReceived,SUM(callBackReturend) as callBackReturend,SUM(callBackUnanswered) as callBackUnanswered INTO v_prevCallBackReceived,v_prevCallBackReturend,v_prevCallBackUnanswered
        FROM temp_callDurationHistory_calc_diff;
    	
        SELECT * FROM temp_AllagentId;
        
 		SELECT 		v_callBackReceived as TotalCount
 				,	IFNULL((v_callBackReceived-v_prevCallBackReceived)*100,0) as DiffTotalPercent
 				,	IFNULL(v_callBackReturend,0) as TotalCallBackReturend
 				,	IFNULL((v_callBackReturend-v_prevCallBackReturend)*100,0) as DiffCallBackReturend
 				,	IFNULL(v_callBackUnanswered,0) as TotalcallBackUnanswered
 				,	IFNULL((v_callBackUnanswered-v_prevCallBackUnanswered)*100,0) as DiffCallBackUnanswered;
   
        
    	SELECT 'All agents' 								as agentName
    		,IFNULL(callBackReceived,0) 					as callBackReceived
    		,IFNULL(callBackReturend,0) 					as callBackReturend
    		,IFNULL(callBackAnswered,0) 					as callBackAnswered
    		,IFNULL(callBackUnanswered,0)  					as callBackUnanswered
    		,IFNULL(callAbandoned,0) 						as abandonedCall
    		,IFNULL(Duration,0) 							as callBackDuration
    		,IFNULL((Duration/callBackAnswered)*100,0) 		as avgHandlingTime
    		,IFNULL(maxHandlingTime,0) 						as maxHandlingTime
    		,IFNULL((callBackReturend/callBackReceived)*100,0) as overallConversationRate
    		,IFNULL((callBackAnswered/callBackReceived)*100,0) as callbackSuccessRate
 	FROM temp_callDurationHistory_calc1
    UNION ALL
     	SELECT agentName
    		 ,IFNULL(callBackReceived,0)							as callBackReceived
    		 ,IFNULL(callBackReturend,0)							as callBackReturend
    		 ,IFNULL(callBackAnswered,0) 							as callBackAnswered
    		 ,IFNULL(callBackUnanswered,0) 							as callBackUnanswered
    		 ,IFNULL(callAbandoned,0) 								as abandonedCall
    		 ,IFNULL(Duration,0)									as callBackDuration
    		 ,IFNULL((Duration/callBackAnswered)*100,0)				as avgHandlingTime
    		 ,IFNULL(maxHandlingTime,0)								as maxHandlingTime
    		 ,IFNULL((callBackReturend/callBackReceived)*100,0) 	as overallConversationRate
    		 ,IFNULL((callBackAnswered/callBackReceived)*100,0)		as callbackSuccessRate
    	FROM  temp_callDurationHistory_calc;
     
      end ;;
DELIMITER ;
