CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertCompanyPurchasedAddon`(
p_companyId int,
p_domainId int,
p_planId int,
p_productId int,
p_addonId int,
p_addonName varchar(150),
p_addonprice float,
p_addonqty int
)
Begin
	declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'Failure';
    
    insert into tb_company_purchased_addon_list(companyId, domainId, planId, productId, addonId, addonName, addonprice, addonqty, createAt)
