CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertCustomerConatctPhoneNumber_info`(	p_firstName 				varchar(100) 
  	,p_lastName 				varchar(100) 
  	,p_phoneNumber 				json 
  	,p_email 					varchar(100) 
  	,p_accountNumber 			varchar(100) 
  	,p_tags 					varchar(100) 
  	,p_location 				varchar(100) 
  	,p_address 					varchar(225) 
  	,p_country 					varchar(100) 
  	,p_state 					varchar(100) 
  	,p_city 					varchar(100) 
  	,p_postalCode 				varchar(100) 
  	,p_facebook 				varchar(100) 
  	,p_instagram 				varchar(100) 
  	,p_whatsapp 				varchar(100) 
  	,p_twitter 					varchar(100) 
  	,p_createdAt 				datetime 
  	,p_updatedAt 				datetime 
  	,p_voiceBiometric 			varchar(100) 
  	,p_domainId 				int 
  	,p_mergeCustomer 			int 
  	,p_blockCustomer 			int 
  	,p_doNotDisturb 			int 
  	,p_blockCustomerReq 		int 
  	,p_doNotDisturbReq 			int 
  	,p_type 					varchar(40) 
  	,p_currentCustomerNumber 	varchar(20) 
  	,p_customerType 			varchar(100)
     ,p_primaryPhoneNumber		VARCHAR(20)
   	,p_primaryEmail				VARCHAR(150)
  )
Begin 	
		declare v_errcode int default -1;
		declare v_errmsg varchar(50) default 'Error : Not inserted';
	  
      Logic_Block: BEGIN
		IF JSON_VALID(p_phoneNumber) = 0
        THEN
			SET v_errcode 	= -1
			,	v_errmsg	= 'Phone Number is not in valid Json format';
            
            LEAVE Logic_Block;
        ELSEIF JSON_VALID(p_email) = 0
        THEN
			SET v_errcode 	= -1
			,	v_errmsg	= 'Email is not in valid Json format';
            
            LEAVE Logic_Block;
        END IF;
        
		INSERT INTO customer_contact (firstName, lastName, primaryPhoneNumber,phoneNumber,p_primaryEmail,email,accountNumber,tags,location,address,country,state,city, postalCode, facebook, instagram, whatsapp, twitter, createdAt, updatedAt, voiceBiometric, domainId,
		mergeCustomer,blockCustomer,doNotDisturb,blockCustomerReq,doNotDisturbReq,type,currentCustomerNumber,customerType) 
		VALUES (p_firstName,p_lastName,p_primaryPhoneNumber,p_phoneNumber,p_primaryEmail,p_email,p_accountNumber,p_tags,p_location,p_address,p_country,p_state,p_city,	p_postalCode,p_facebook,p_instagram,p_whatsapp,p_twitter,now(),now(),p_voiceBiometric,p_domainId,
				p_mergeCustomer,p_blockCustomer,p_doNotDisturb,p_blockCustomerReq,p_doNotDisturbReq,p_type,p_currentCustomerNumber,p_customerType); 
		
		if row_count() >0 then
			set v_errcode=0;
			set v_errmsg='Success : Inserted';
		end if;
	END; 
    
  select v_errcode as errcode, v_errmsg as errmsg;
  
 End ;;
DELIMITER ;
