CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insertCustomerContact2`(   
      p_coid              INT,
      p_firstName         VARCHAR(100),
      p_lastName          VARCHAR(100),
      p_phoneNumber       LONGTEXT,
      p_email             VARCHAR(100),
      p_accountNumber     VARCHAR(100),
      p_tags              LONGTEXT,
      p_location          VARCHAR(100),
      p_address           VARCHAR(225),
      p_country           VARCHAR(100),
      p_state             VARCHAR(100),
      p_city              VARCHAR(100),
      p_postalCode        VARCHAR(100),
      p_facebook          VARCHAR(100),
      p_instagram         VARCHAR(100),
      p_twitter           VARCHAR(100),
      p_whatsapp          VARCHAR(100),
      p_domainId          INT,     
      p_voiceBiometric    VARCHAR(100),
      p_customerType      VARCHAR(255),
      p_mergeCustomer     INT,
      p_blockCustomer     INT,
      p_doNotDisturb      INT,
      p_blockCustomerReq  INT,
      p_doNotDisturbReq   INT
  )
BEGIN
      DECLARE v_curdate DATETIME;
      DECLARE v_errcode INT;
      DECLARE v_errmsg  VARCHAR(50);
      DECLARE existing_id INT;
      
      SET v_curdate = NOW();
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT coid INTO existing_id
      FROM customer_contact
      WHERE (phoneNumber COLLATE utf8mb4_unicode_ci = p_phoneNumber COLLATE utf8mb4_unicode_ci
 	 or email COLLATE utf8mb4_unicode_ci = p_email COLLATE utf8mb4_unicode_ci) and domainId = p_domainId
      LIMIT 1;
      
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 
      
      IF existing_id IS NULL THEN
      
      INSERT INTO customer_contact
          (
              firstName,
              lastName,
              phoneNumber,
              email,
              accountNumber,
              tags,
              location,
              address,
              country,
              state,
              city,
              postalCode,
              facebook,
              instagram,
              twitter,
              whatsapp,
              domainId,
              createdAt,
              voiceBiometric,
              customerType,
              blockCustomer,
              doNotDisturb,
              blockCustomerReq,
              doNotDisturbReq
          )
          VALUES (
              p_firstName,
              p_lastName,
              p_phoneNumber,
              p_email,
              p_accountNumber,
              p_tags,
              p_location,
              p_address,
              p_country,
              p_state,
              p_city,
              p_postalCode,
              p_facebook,
              p_instagram,
              p_twitter,
              p_whatsapp,
              p_domainId,
              v_curdate,
              p_voiceBiometric,
              p_customerType,
              p_blockCustomer,
              p_doNotDisturb,
              p_blockCustomerReq,
              p_doNotDisturbReq
          );
          
          IF ROW_COUNT() > 0 THEN
              SET v_errcode = 0;
              SET v_errmsg = 'Inserted Successfully';
          END IF;
      
      ELSE
      
          UPDATE customer_contact 
          SET firstName = ifnull(p_firstName, firstName),
              lastName = ifnull(p_lastName, lastName),
              phoneNumber = ifnull(p_phoneNumber, phoneNumber),
              email = ifnull(p_email, email),
              accountNumber = ifnull(p_accountNumber, accountNumber),
              tags = ifnull(p_tags, tags),
              location = ifnull(p_location, location),
              address = ifnull(p_address, address),
              country = ifnull(p_country, country),
              state = ifnull(p_state, state),
              city = ifnull(p_city, city),
              postalCode = ifnull(p_postalCode, postalCode),
              facebook = ifnull(p_facebook, facebook),
              instagram = ifnull(p_instagram, instagram),
              whatsapp = ifnull(p_whatsapp, whatsapp),
              twitter = ifnull(p_twitter, twitter),
              voiceBiometric = ifnull(p_voiceBiometric, voiceBiometric),
              mergeCustomer = ifnull(p_mergeCustomer, mergeCustomer),
              blockCustomer = ifnull(p_blockCustomer, blockCustomer),
              doNotDisturb = ifnull(p_doNotDisturb, doNotDisturb),
              blockCustomerReq = ifnull(p_blockCustomerReq, blockCustomerReq),
              doNotDisturbReq = ifnull(p_doNotDisturbReq, doNotDisturbReq),
              updatedAt = v_curdate,
              customerType = ifnull(p_customerType, customerType)
          WHERE id = existing_id AND domainId = p_domainId;
          
          IF ROW_COUNT() > 0 THEN
              SET v_errcode = 0;
              SET v_errmsg = 'Updated Successfully';
          END IF;
       
      END IF;
      
      SELECT v_errcode AS errcode, v_errmsg AS errmsg;
      
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
