CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertloginSessionHistory_info`(
  p_logInSessionId varchar(100),
  p_logInTimestamp bigint,
  
  p_sipLoginId int,
  p_domainId int,
  p_companyId int, 
  p_ext int 
  )
Begin 
	DECLARE v_logInTimestamp	BIGINT;
	declare v_errcode int default -1;
	declare v_errmsg varchar(100) default 'Failure';
    
    SET v_logInTimestamp = unix_timestamp(NOW())*1000;
  
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	if not exists(select 1 from logInSessionHistory where logInSessionId collate utf8mb4_unicode_ci = p_logInSessionId limit 1)
     then
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  		INSERT INTO logInSessionHistory (logInSessionId,logInTimestamp,logOutTimestamp,sipLoginId,domainId,companyId,ext,createdAt) 
  		VALUES(p_logInSessionId,v_logInTimestamp,null,p_sipLoginId,p_domainId,p_companyId,p_ext,now());  	
  	End if;
  
  	if row_count()>0 then
  		set v_errcode = 0;
          set v_errmsg = 'Success: Inserted';
      End if;
      
      select v_errcode as errcode, v_errmsg as errmsg;
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
