CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_InsertUpdateAgentStateTimer`(
	p_domainId 				INT,
	p_startTimestamp 		BIGINT,
	
	p_ext 					INT
)
sp_return:Begin 
	DECLARE v_errcode 			INT DEFAULT -1;
	DECLARE v_errmsg 			VARCHAR(100) DEFAULT 'Failure';
	DECLARE v_stid				INT;
	DECLARE v_timerStatusId		INT;
	DECLARE v_CurDate			DATETIME DEFAULT NOW();
	DECLARE v_endTimestamp		BIGINT;
	DECLARE v_offlineStatusId	INT;
       
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
		SELECT stid, timerStatusId  INTO v_stid, v_timerStatusId
		FROM state_timer 
		WHERE ext = p_ext AND domainId = p_domainId AND endTimestamp IS NULL
		ORDER BY stid DESC LIMIT 1;
        
        SELECT aid INTO v_offlineStatusId
        FROM  agent_status 
		WHERE domainId = p_domainId 
        AND statusName = 'Offline';
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   	
   		SET v_endTimestamp = p_startTimestamp - 1;
				   
		UPDATE 	state_timer 
		SET 	endTimestamp	= v_endTimestamp
			,	stateDuration 	= v_endTimestamp - startTimestamp
			,	updatedAt		= v_CurDate
		WHERE 	stid 			= v_stid;
           
		INSERT INTO state_timer(ext,domainId,startTimestamp,timerStatusId,createdAt,updatedAt)
		VALUES(p_ext,p_domainId,p_startTimestamp,v_offlineStatusId,v_CurDate,v_CurDate);    
           
   		SET v_stid = last_insert_id();
   		SET v_errcode = 0;
   		SET v_errmsg = 'User presence changed successfully ';              
           
       select v_errcode as errcode, v_errmsg as errmsg, ifnull(v_stid,0) as stid;    
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
