  		DECLARE v_ExistEmail 		VARCHAR(1500);     
           
    		SET v_curdate = now();
   		    SET v_coid	= p_coid;        
            
  
                  
    	   sp_exit : Begin   
    	   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
               
     
            IF v_coid IS NULL
            THEN
    	SELECT 	coid
    	INTO 	v_coid_basedOnPhone
    	FROM 	customer_contact 
    	WHERE 	domainId 			= p_domainId 
    	AND		primaryPhoneNumber	= p_primaryPhoneNumber;	
    
    	SET v_coid = v_coid_basedOnPhone;
    
    	IF v_coid_basedOnPhone IS NULL
    	THEN
    		SELECT 	coid
    		INTO 	v_coid_basedOnEmail
    		FROM 	customer_contact 
