    		AND		primaryEmail	= p_primaryEmail;	
    		
    		SET v_coid = v_coid_basedOnEmail;
    	END IF;	        
            
           
			IF v_coid IS NULL AND v_coid_basedOnPhone IS NULL AND v_coid_basedOnEmail IS NULL
            THEN
    			
    			INSERT INTO customer_contact (
