    			);                  
                        
    			SET v_coid = last_insert_id();	
                     
    			IF IFNULL(p_CustomField,'') <> '' AND IFNULL(p_CustomValues,'') <> ''
    			THEN
    				SET v_CustomField	 	= REPLACE(p_CustomField,'|',',');
    				SET v_CustomValues	= REPLACE(p_CustomValues,'|',',');                  
    
