          					  lastName 		= ifnull(p_lastName,lastName),
          					  phoneNumber 	= IF(p_primaryPhoneNumber IS NOT NULL AND p_primaryPhoneNumber <> primaryPhoneNumber, JSON_ARRAY_APPEND(p_phoneNumber,'$',p_primaryPhoneNumber), p_phoneNumber),
          					  email 		= IF(p_primaryEmail IS NOT NULL AND p_primaryEmail <> primaryEmail,JSON_ARRAY_APPEND(p_email,'$',p_primaryEmail),p_email),	
          					  accountNumber = ifnull(p_accountNumber,accountNumber),
          					  tags 			=  ifnull(p_tags,tags),
