    	p_location 				VARCHAR(100),
    	p_address 				VARCHAR(225),
    	p_country 				VARCHAR(100),
    	p_state 				VARCHAR(100),
    	p_city 					VARCHAR(100),
    	p_postalCode 			VARCHAR(100),
    	p_facebook 				VARCHAR(100),
    	p_instagram 			VARCHAR(100),
    	p_whatsapp 				VARCHAR(100),
    	p_twitter 				VARCHAR(100),
    	p_voiceBiometric 		VARCHAR(100),
    	p_domainId 				INT,
    	p_mergeCustomer 		INT,
    	p_blockCustomer 		INT,
    	p_doNotDisturb 			INT,
    	p_blockCustomerReq 		INT,
    	p_doNotDisturbReq 		INT,
    	p_type 					VARCHAR(40),
    	p_currentCustomerNumber VARCHAR(20),
    	p_customerType 			VARCHAR(255),
    	p_timeZone				VARCHAR(100),
    	p_cookiesId 			varchar(150),          
    	p_Source				VARCHAR(250),
    	p_CustomField			TEXT,
    	p_CustomValues			TEXT,
    	p_primaryPhoneNumber	VARCHAR(20),
    	p_primaryEmail			VARCHAR(150)
    )
BEGIN
    	DECLARE v_coid 					BIGINT;    	
    	DECLARE v_firstName 			VARCHAR(100);
    	DECLARE v_lastName 				VARCHAR(100);
    	DECLARE v_phoneNumber 			VARCHAR(750);
    	DECLARE v_email 				VARCHAR(1500);
    	DECLARE v_accountNumber 		VARCHAR(100);
    	DECLARE v_tags 					VARCHAR(750);
    	DECLARE v_location 				VARCHAR(100);
    	DECLARE v_address 				VARCHAR(225);
    	DECLARE v_country 				VARCHAR(100);
    	DECLARE v_state 				VARCHAR(100);
    	DECLARE v_city 					VARCHAR(100);
    	DECLARE v_postalCode 			VARCHAR(100);
    	DECLARE v_facebook 				VARCHAR(100);
    	DECLARE v_instagram 			VARCHAR(100);
    	DECLARE v_whatsapp 				VARCHAR(100);
    	DECLARE v_twitter 				VARCHAR(100);
    	DECLARE v_voiceBiometric 		VARCHAR(100);
    	DECLARE v_domainId 				INT;
    	DECLARE v_mergeCustomer 		INT;
    	DECLARE v_blockCustomer 		INT;
    	DECLARE v_doNotDisturb 			INT;
    	DECLARE v_blockCustomerReq 		INT;
    	DECLARE v_doNotDisturbReq 		INT;
    	DECLARE v_type 					VARCHAR(40);
    	DECLARE v_currentCustomerNumber VARCHAR(20);
    	DECLARE v_customerType 			VARCHAR(255);
    	DECLARE v_timeZone				VARCHAR(100);
    	DECLARE v_cookiesId 			Varchar(150);          
    	DECLARE v_Source				VARCHAR(250);	
    	DECLARE v_CustomField			TEXT;
    	DECLARE v_CustomValues			TEXT;
     
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 	SET v_coid = p_coid;
      
    	IF IFNULL(v_coid,0) = 0     
    	THEN
    		SELECT 	coid
    		INTO 	v_coid
    		FROM 	customer_contact 
    		WHERE 	domainId 			= p_domainId 
    		AND		primaryPhoneNumber	= p_primaryPhoneNumber;	
    	   
    		IF v_coid IS NULL
    		THEN
    			SELECT 	coid
    			INTO 	v_coid
    			FROM 	customer_contact 
    			WHERE 	domainId 		= p_domainId 
    			AND		primaryEmail	= p_primaryEmail;	
    		END IF;	       
    	END IF;  
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 
 	Logic_Block : BEGIN
 	IF JSON_VALID(p_phoneNumber) = 0
 	THEN
 		SELECT v_coid AS coid, -3 AS errcode ,'Phone Number is not in valid Json format' AS errmsg,v_blockCustomer AS blockCustomer;
         
 		LEAVE Logic_Block;
 	ELSEIF JSON_VALID(p_email) = 0
 	THEN
 		SELECT v_coid AS coid, -4 AS errcode ,'Email is not in valid Json format' AS errmsg,v_blockCustomer AS blockCustomer;
 		
 		LEAVE Logic_Block;
 	END IF;   
        
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    	SELECT 	firstName, 			lastName, 				phoneNumber,		email,			accountNumber, 		    
                tags,				location,				address,			country,		state, 				    
                city,				postalCode,				facebook,			instagram,		whatsapp, 				
                twitter,			voiceBiometric,			domainId,			mergeCustomer,	blockCustomer, 		    
                doNotDisturb,		blockCustomerReq,		doNotDisturbReq,	type,			currentCustomerNumber,   
                customerType,		timeZone,				cookiesId,			Source		
    	INTO 	  v_firstName, 		v_lastName, 			v_phoneNumber,		v_email,		v_accountNumber, 		    
                v_tags,			v_location,				v_address,			v_country,		v_state, 				    
                v_city,			v_postalCode,			v_facebook,			v_instagram,	v_whatsapp, 				
                v_twitter,		v_voiceBiometric,		v_domainId,			v_mergeCustomer,v_blockCustomer, 		    
                v_doNotDisturb,	v_blockCustomerReq,		v_doNotDisturbReq,	v_type,			v_currentCustomerNumber,   
                v_customerType,	v_timeZone,				v_cookiesId,		v_Source
    	FROM 	customer_contact
   	WHERE 	coid =  v_coid;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       
 	IF v_blockCustomer = 1
   	THEN
   		SELECT v_coid AS coid,-2 AS errcode ,'Customer is bocked' AS errmsg,v_blockCustomer AS blockCustomer;
 	ELSE 
   		SET v_firstName 				= IFNULL(p_firstName,v_firstName) 				
   			,v_lastName 				= IFNULL(p_lastName,v_lastName) 				
   			,v_phoneNumber 			   	= IFNULL(p_phoneNumber,v_phoneNumber) 			
   			,v_email 				   	= IFNULL(p_email,v_email) 				
   			,v_accountNumber 		   	= IFNULL(p_accountNumber,v_accountNumber) 		
   			,v_tags 					= IFNULL(p_tags,v_tags) 					
   			,v_location 				= IFNULL(p_location,v_location) 				
   			,v_address 				   	= IFNULL(p_address,v_address) 				
   			,v_country 				   	= IFNULL(p_country,v_country) 				
   			,v_state 				   	= IFNULL(p_state,v_state) 				
   			,v_city 					= IFNULL(p_city,v_city) 					
   			,v_postalCode 			   	= IFNULL(p_postalCode,v_postalCode) 			
   			,v_facebook 				= IFNULL(p_facebook,v_facebook)
   			,v_instagram 			   	= IFNULL(p_instagram,v_instagram) 			
   			,v_whatsapp 				= IFNULL(p_whatsapp,v_whatsapp)				
   			,v_twitter 				   	= IFNULL(p_twitter,v_twitter) 				
   			,v_voiceBiometric 		   	= IFNULL(p_voiceBiometric,v_voiceBiometric) 		
   			,v_domainId 				= IFNULL(p_domainId,v_domainId) 				
   			,v_mergeCustomer 		   	= IFNULL(p_mergeCustomer,v_mergeCustomer) 		
   			,v_blockCustomer 		   	= IFNULL(p_blockCustomer,v_blockCustomer) 		
   			,v_doNotDisturb 			= IFNULL(p_doNotDisturb,v_doNotDisturb) 			
   			,v_blockCustomerReq 		= IFNULL(p_blockCustomerReq,v_blockCustomerReq) 		
   			,v_doNotDisturbReq 		   	= IFNULL(p_doNotDisturbReq,v_doNotDisturbReq) 		
   			,v_type 					= IFNULL(p_type,v_type) 					
   			,v_currentCustomerNumber   	= IFNULL(p_currentCustomerNumber,v_currentCustomerNumber) 
   			,v_customerType 			= IFNULL(p_customerType,v_customerType) 			
   			,v_timeZone				   	= IFNULL(p_timeZone,v_timeZone)				
   			,v_cookiesId 			   	= IFNULL(p_cookiesId,v_cookiesId) 			
   			,v_Source				   	= IFNULL(p_Source,v_Source)				
   			,v_CustomField			   	= p_CustomField
   			,v_CustomValues			   	= p_CustomValues;
   			 
             SELECT 'KMS',v_coid,v_firstName,v_lastName,v_phoneNumber,v_email,v_accountNumber,v_tags,v_location,v_address,v_country,v_state,v_city,v_postalCode,v_facebook,v_instagram,v_whatsapp,v_twitter,v_voiceBiometric,v_domainId,
   			 v_mergeCustomer,v_blockCustomer,v_doNotDisturb,v_blockCustomerReq,v_doNotDisturbReq,v_type,v_currentCustomerNumber,v_customerType,v_timeZone,v_cookiesId,v_Source,v_CustomField,v_CustomValues,
   			 p_primaryPhoneNumber,p_primaryEmail;
             
   			 CALL ccaas_insertUpdateCustomerContact
   			 (v_coid,v_firstName,v_lastName,v_phoneNumber,v_email,v_accountNumber,v_tags,v_location,v_address,v_country,v_state,v_city,v_postalCode,v_facebook,v_instagram,v_whatsapp,v_twitter,v_voiceBiometric,v_domainId,
   			 v_mergeCustomer,v_blockCustomer,v_doNotDisturb,v_blockCustomerReq,v_doNotDisturbReq,v_type,v_currentCustomerNumber,v_customerType,v_timeZone,v_cookiesId,v_Source,v_CustomField,v_CustomValues,
   			 p_primaryPhoneNumber,p_primaryEmail);
   	END IF;
     END;
 END ;;
DELIMITER ;
