/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insertUpdateCustomerContact_test`(		
      			IN p_coid 					INT,
              	IN p_firstName 				VARCHAR(250),
              	IN p_lastName 				VARCHAR(250),
              	IN p_phoneNumber 			VARCHAR(750),
              	IN p_email 					VARCHAR(1500),
              	IN p_accountNumber 			VARCHAR(100),
              	IN p_tags 					VARCHAR(750),
              	IN p_location 				VARCHAR(100),
              	IN p_address 				VARCHAR(225),
              	IN p_country 				VARCHAR(100),
              	IN p_state 					VARCHAR(100),
              	IN p_city 					VARCHAR(100),
              	IN p_postalCode 			VARCHAR(100),
              	IN p_facebook 				VARCHAR(100),
              	IN p_instagram 				VARCHAR(100),
              	IN p_whatsapp 				VARCHAR(100),
              	IN p_twitter 				VARCHAR(100),
              	IN p_voiceBiometric 		VARCHAR(100),
              	IN p_domainId 				INT,
              	IN p_mergeCustomer 			INT,
              	IN p_blockCustomer 			INT,
              	IN p_doNotDisturb 			INT,
              	IN p_blockCustomerReq 		INT,
              	IN p_doNotDisturbReq 		INT,
              	IN p_type 					VARCHAR(40),
              	IN p_currentCustomerNumber 	VARCHAR(20),
              	IN p_customerType 			VARCHAR(255),
              	IN p_timeZone				VARCHAR(100),
              	IN p_cookiesId 				varchar(150),          
              	IN p_Source					VARCHAR(250),
              	IN p_CustomField			TEXT,
              	IN p_CustomValues			TEXT,
              	IN p_primaryPhoneNumber		VARCHAR(20),
              	IN p_primaryEmail			VARCHAR(150)
              )
sp_return:BEGIN
          		DECLARE existingId 			INT;
          		DECLARE v_errcode  			INT;
          		DECLARE v_errmsg   			VARCHAR(200);
          		DECLARE v_curdate  			DATETIME;
          		DECLARE v_split_phone_num 	text;
          		DECLARE v_split_email 		text;
          		DECLARE v_coid_basedOnPhone int;
          		DECLARE v_coid_basedOnEmail int;
          		DECLARE v_coid				int;
          		DECLARE v_CustomField		TEXT;
          		DECLARE v_CustomValues		TEXT;
          		DECLARE v_UpdateQuery		TEXT;        
          		DECLARE v_ExistPhoneNumber 	VARCHAR(1500);
          		DECLARE v_ExistEmail 		VARCHAR(1500); 
                DECLARE v_blockCustomer		INT;
                     
          		SET v_curdate = now();
                 
      			sp_exit : Begin   
       			IF JSON_VALID(p_phoneNumber) = 0
       			THEN
       				SET v_errcode 	= -1
       				,	v_errmsg	= 'Phone Number is not in valid Json format';
       				
       				LEAVE sp_exit;
       			ELSEIF JSON_VALID(p_email) = 0
       			THEN
       				SET v_errcode 	= -1
       				,	v_errmsg	= 'Email is not in valid Json format';
       				
       				LEAVE sp_exit;
       			END IF;
                
                IF IFNULL(p_domainId,0) = 0
       			THEN
       				SET v_errcode 	= -1
       				,	v_errmsg	= 'domainId should not be null';
       				LEAVE sp_exit;
				END IF;
                  
              	   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;

           		SELECT 	coid
           		INTO 	v_coid_basedOnPhone
           		FROM 	customer_contact 
           		WHERE 	domainId 			= p_domainId 
           		AND		(primaryPhoneNumber	collate utf8mb4_0900_ai_ci = p_primaryPhoneNumber OR p_primaryPhoneNumber collate utf8mb4_0900_ai_ci like CONCAT('%',primaryPhoneNumber,'%')) LIMIT 1;	
                
                SELECT 'v_coid_basedOnPhone',v_coid_basedOnPhone;
                
                IF v_coid_basedOnPhone IS NULL
                THEN
					SELECT 	coid
					INTO 	v_coid_basedOnPhone
					FROM 	customer_contact 
					WHERE 	domainId 			= p_domainId 
					AND		(phoneNumber collate utf8mb4_0900_ai_ci like CONCAT('%',p_primaryPhoneNumber,'%')) LIMIT 1;
				END IF;
                
           		SET v_coid = v_coid_basedOnPhone;
           	   
           		IF v_coid_basedOnPhone IS NULL
           		THEN
           			SELECT 	coid
           			INTO 	v_coid_basedOnEmail
           			FROM 	customer_contact 
           			WHERE 	domainId 		= p_domainId 
           			AND		primaryEmail	collate utf8mb4_0900_ai_ci = p_primaryEmail LIMIT 1;	
			
           			SET v_coid = v_coid_basedOnEmail;
           		END IF;	       
      
      			IF IFNULL(p_coid,0) <> 0 
                  THEN
      				IF IFNULL(v_coid,0) <> 0 
      				THEN
      					IF v_coid <> p_coid
                          THEN 
      						DELETE FROM customer_contact WHERE coid = p_coid;
                          END IF;  
      				ELSE
      					SET v_coid = p_coid;
      				END IF; 
                  END IF; 

					SELECT 'v_coid',v_coid;

                      IF IFNULL(v_coid,0) = 0 and v_coid_basedOnPhone is null and v_coid_basedOnEmail is null
                      then
              			
              			INSERT INTO customer_contact (
              				  firstName, lastName, primaryPhoneNumber, phoneNumber, 
              				  primaryEmail, email, accountNumber, tags,
              				  location, address, country, state, city, postalCode,
              				  facebook, instagram, whatsapp, twitter, voiceBiometric,
              				  domainId, mergeCustomer, blockCustomer, doNotDisturb,
              				  blockCustomerReq, doNotDisturbReq, type,
              				  currentCustomerNumber, customerType,timeZone,cookiesId,`Source`, createdAt, updatedAt
              			)
              			VALUES (
              				  p_firstName, p_lastName, p_primaryPhoneNumber, IFNULL(p_phoneNumber,'[]'), 
              				  p_primaryEmail, IFNULL(p_email,'[]'), p_accountNumber, p_tags,
              				  p_location, p_address, p_country, p_state, p_city, p_postalCode,
              				  p_facebook, p_instagram, p_whatsapp, p_twitter, p_voiceBiometric,
              				  p_domainId, p_mergeCustomer, 0, p_doNotDisturb,
              				  p_blockCustomerReq, p_doNotDisturbReq, p_type,
              				  p_currentCustomerNumber, p_customerType,p_timeZone,p_cookiesId, p_Source,v_curdate, v_curdate
              			);                  
                                  
              			SET v_coid = last_insert_id();	
                               
              			IF IFNULL(p_CustomField,'') <> '' AND IFNULL(p_CustomValues,'') <> ''
              			THEN
              				SET v_CustomField	 	= REPLACE(p_CustomField,'|',',');
              				SET v_CustomValues	= REPLACE(p_CustomValues,'|',',');                  
              
              				SET @Q = CONCAT('INSERT INTO customer_contact_',p_domainId,'(coid,createdAt,',v_CustomField,')',' VALUES(',v_coid,',"',v_curdate,'",',v_CustomValues,')');
              
              				PREPARE Q FROM @Q;
              				EXECUTE Q;
              				DEALLOCATE PREPARE Q;
              			END IF;
                   				
         				set v_errcode=0;
         				set v_errmsg='Success : Inserted';
         				Leave sp_exit;
                 
                            ELSE 
  							  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
								SELECT phoneNumber, email
								INTO 	v_ExistPhoneNumber, v_ExistEmail 		
								FROM 	customer_contact
								WHERE coid = v_coid LIMIT 1;
                             
                                set @emailcheck = if(v_ExistEmail like concat('%',p_primaryEmail,'%'),1,0);
  
                                SET v_ExistPhoneNumber	= IF(p_phoneNumber='[]',v_ExistPhoneNumber,IFNULL(p_phoneNumber,'[]'));
                                SET v_ExistEmail 			= IF(p_email = '[]',v_ExistEmail,IFNULL(p_email,'[]'));  
                                
								if @emailcheck = 0 then
									UPDATE customer_contact
									SET email = IF(p_primaryEmail IS NOT NULL AND p_primaryEmail collate utf8mb4_0900_ai_ci <> IFNULL(primaryEmail,''),JSON_ARRAY_APPEND(v_ExistEmail,'$',p_primaryEmail),v_ExistEmail)
									WHERE coid = v_coid;	
								End if;
                                
                    				  UPDATE customer_contact
                    				  SET
                    					firstName 	= ifnull(p_firstName,firstName),
                    					lastName 		= ifnull(p_lastName,lastName),
    									primaryPhoneNumber = IFNULL(primaryPhoneNumber,p_primaryPhoneNumber),
                    					phoneNumber 	= IF(p_primaryPhoneNumber IS NOT NULL AND p_primaryPhoneNumber collate utf8mb4_0900_ai_ci <> IFNULL(primaryPhoneNumber,''), JSON_ARRAY_APPEND(v_ExistPhoneNumber,'$',p_primaryPhoneNumber), v_ExistPhoneNumber),
    									primaryEmail	= IFNULL(primaryEmail,p_primaryEmail),
                    					  
                    					  accountNumber = ifnull(p_accountNumber,accountNumber),
                    					  tags 			=  ifnull(p_tags,tags),
                    					  location 		=  ifnull(p_location,location),
                    					  address 		=  ifnull(p_address,address),
                    					  country 		=  ifnull(p_country,country),
                    					  state 		=  ifnull(p_state,state),
                    					  city 			=  ifnull(p_city,city),
                    					  postalCode 	=  ifnull(p_postalCode,postalCode),
                    					  facebook 		=  ifnull(p_facebook,facebook),
                    					  instagram 	=  ifnull(p_instagram,instagram),
                    					  whatsapp 		=  ifnull(p_whatsapp,whatsapp),
                    					  twitter 		= ifnull(p_twitter,twitter),
                    					  voiceBiometric=  ifnull(p_voiceBiometric,voiceBiometric),
                    					  mergeCustomer =  ifnull(p_mergeCustomer,mergeCustomer),
                    					
                    					  doNotDisturb 	=  ifnull(p_doNotDisturb,doNotDisturb),
                    					  blockCustomerReq =  ifnull(p_blockCustomerReq,blockCustomerReq),
                    					  doNotDisturbReq =  ifnull(p_doNotDisturbReq,doNotDisturbReq),
                    					 
                    					  currentCustomerNumber =  ifnull(p_currentCustomerNumber,currentCustomerNumber),
                    					  customerType =  ifnull(p_customerType,customerType),
                    					  timeZone  = ifnull(p_timeZone,timeZone),
                						  cookiesId = ifnull(p_cookiesId,cookiesId),
                						  `Source`	= IFNULL(p_Source,`Source`),
                    					  updatedAt = v_curdate
                    				  WHERE coid = v_coid;	
                                    
                                    IF IFNULL(p_CustomField,'') <> '' AND IFNULL(p_CustomValues,'') <> ''
                                    THEN
                						CALL SplitWithSlNo(p_CustomField,"|");                    
                						DROP TEMPORARY TABLE IF EXISTS temp_CustomField; 
                						CREATE TEMPORARY TABLE temp_CustomField 
                						SELECT * FROM tt_Split_temptable;
                
                						CALL SplitWithSlNo(p_CustomValues,"|");
                						DROP TEMPORARY TABLE IF EXISTS temp_CustomValues; 
                						CREATE TEMPORARY TABLE temp_CustomValues 					
                						SELECT * FROM tt_Split_temptable; 
                						
                						SELECT 	GROUP_CONCAT(CONCAT(CF.items,' = ', CV.items)) 
                						INTO 	v_UpdateQuery
                						FROM 	temp_CustomField	CF
                						JOIN 	temp_CustomValues	CV	ON CV.SlNo = CF.SlNo;
                
                						SET @Q = CONCAT("UPDATE customer_contact_",p_domainId," SET ",v_UpdateQuery," WHERE coid = ",   v_coid);                     
                						
                						PREPARE Q FROM @Q;
                						EXECUTE Q;
                						DEALLOCATE PREPARE Q;
                					END IF;
                    				  
                    				  if row_count() >0 then
                    					set v_errcode=1;
                    					set v_errmsg='Success : Updated';
                    				end if;          
                    
                            END IF;
                     END;     

                    SELECT IFNULL(a.blockCustomer,0) INTO v_blockCustomer from customer_contact a WHERE coid = v_coid; 
                        
					SELECT v_coid coid,v_errcode as errcode , v_errmsg as errmsg, v_blockCustomer AS blockCustomer;

                          
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_insertUpdateCustomerContact_ttttt` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
