CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdateCustomReport`(
			 p_CustomReportId     INT ,
			p_ReportName       VARCHAR(255), 
			p_Description      VARCHAR(255), 
			p_StartDate        BIGINT ,
			p_EndDate          BIGINT ,
            p_Type             TINYINT,
			p_TimeZone         VARCHAR(200) ,
			p_TimeFormat       VARCHAR(20) ,
			p_CustomQuery       TEXT)
BEGIN
		  DECLARE v_curdate    DATETIME;
          DECLARE v_errcode    INT             DEFAULT -1;
          DECLARE v_errmsg     VARCHAR(100)    DEFAULT 'Failure';
          SET v_curdate = NOW();
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      	  IF EXISTS(SELECT 1 FROM tb_CustomReport WHERE CustomReportId = p_CustomReportId  LIMIT 1) THEN
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
          UPDATE tb_CustomReport SET ReportName=p_ReportName,`Description`=p_Description,StartDate=p_StartDate,EndDate=p_EndDate,`Type`=p_Type,`TimeZone`=`p_TimeZone`,TimeFormat=p_TimeFormat,CustomQuery=p_CustomQuery,CreatedDate=v_curdate,UpdatedDate=v_curdate
          WHERE CustomReportId=p_CustomReportId;
                            IF ROW_COUNT()>0
 				 THEN
      			 SET v_errcode = 0;
                  SET v_errmsg = 'Updated successfully';
                  END IF;
              ELSE
          INSERT INTO tb_CustomReport (
                                      ReportName,
                                      `Description`,
                                      StartDate,
                                      EndDate,
                                      `Type`,
                                      `TimeZone`,
                                      `TimeFormat`,
                                      CustomQuery,
                                      CreatedDate,
                                      UpdatedDate) 
		  VALUES (
				  p_ReportName,
                  p_Description,
                  p_StartDate,
			      p_EndDate,
                  p_Type,
                  p_TimeZone,
                  p_TimeFormat,
                  p_CustomQuery,
                  v_curdate,
                  v_curdate);
              
 			SET p_CustomReportId = last_insert_id();
  			SET v_errcode = 0;
  			SET v_errmsg = 'Inserted successfully';
              
              
              
              
          END IF;
              SELECT v_errcode as errcode, v_errmsg as errmsg;
          END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
