CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdateFacebookClientConfiguration`(
 	p_pageId		VARCHAR(50),
 	p_domainId		INT,
 	p_appId			VARCHAR(255),
 	p_email			VARCHAR(255),
 	p_pageName		VARCHAR(255),
 	p_authToken		TEXT,
 	p_instagramId	VARCHAR(50),
 	p_appSecret		Varchar(255)
 )
BEGIN 
      
               DECLARE v_curdate    DATETIME;
               DECLARE v_errcode    INT             DEFAULT -1;
               DECLARE v_errmsg     VARCHAR(100)    DEFAULT 'Insert Update Facebook Configuration is Failured';
               DECLARE v_domainId     INT;
               
               SET v_curdate = NOW();
               
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 				SELECT domainId INTO v_domainId 
 				FROM tb_FacebookClientConfiguration 
 				
                 WHERE appId = p_appId  ;
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
              
 			IF v_domainId IS NOT NULL THEN
    			UPDATE tb_FacebookClientConfiguration 
                SET authToken=p_authToken,
                    pageId=p_pageId,
                    instagramId=p_instagramId,
                    pageName=p_pageName,
                    appSecret = p_appSecret,
                    UpdatedDate=v_curdate      
               WHERE domainId =v_domainId;   
 				
 				SET v_errcode = 0;
 				SET v_errmsg = 'Facebook Configuration Updated successfully';
                      
 			ELSE
 				INSERT INTO tb_FacebookClientConfiguration (domainId, appId,instagramId ,authToken, email, pageName, CreatedDate, UpdatedDate, appSecret) 
 				VALUES (p_domainId, p_appId,p_instagramId, p_authToken, p_email, p_pageName, v_curdate,v_curdate, p_appSecret); 
                 
 				SET p_domainId = last_insert_id();
 				SET v_errcode = 0;
 				SET v_errmsg = 'Facebook Configuration Inserted successfully';
                   
 			END IF;  
             
 				SELECT v_errcode as errcode, v_errmsg as errmsg;
 	END ;;
DELIMITER ;
