CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdateLeadGeneration`(
  p_LeadId           INT ,
  p_Method           VARCHAR (255),
  p_connector        VARCHAR (255),
  p_Email            VARCHAR(255),
  p_ScheduleType     INT,
  p_domainId         INT,
  p_dayStatus        INT,
  p_weekStatus       INT,
  p_Time             BIGINT,
  p_lastUpdatedDate  BIGINT,
  p_timeZone         VARCHAR(255),
  p_HourlyTime       TINYINT,
  p_MinuteTime       TINYINT,
  p_cronId           VARCHAR(255))
BEGIN
          DECLARE v_curdate    DATETIME;
          DECLARE v_errcode    INT             DEFAULT -1;
          DECLARE v_errmsg     VARCHAR(100)    DEFAULT 'Failure';
         
           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      	IF EXISTS(SELECT 1 FROM tb_LeadGeneration WHERE LeadId = p_LeadId or domainId = p_domainId LIMIT 1) THEN
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
          UPDATE tb_LeadGeneration 
          SET Method  	= IFNULL(p_Method,Method)
          ,connector		= IFNULL(p_connector,connector)
          ,Email			=IFNULL(p_Email,Email)
          ,ScheduleType	=IFNULL(p_ScheduleType,ScheduleType)
          ,weekStatus	=IFNULL(p_weekStatus,weekStatus)
          ,dayStatus		=IFNULL(p_dayStatus,dayStatus)
          ,`Time`		=IFNULL(p_Time,`Time`)
          , lastUpdatedDate = IFNULL(p_lastUpdatedDate,lastUpdatedDate)
          ,timeZone = IFNULL(p_timeZone,timeZone)
          ,HourlyTime = IFNULL(p_HourlyTime, HourlyTime)
          ,MinuteTime = IFNULL(p_MinuteTime, MinuteTime)
          ,cronId = IFNULL(p_cronId, cronId)
 		WHERE LeadId = p_LeadId or domainId = p_domainId;
                  IF ROW_COUNT()>0
 				 THEN
      			 SET v_errcode = 0;
                  SET v_errmsg = 'Updated successfully';
                  END IF;
              
          ELSE
      		 INSERT INTO tb_LeadGeneration (LeadId,Method,connector,Email,ScheduleType,domainId,weekStatus,dayStatus,`Time`,lastUpdatedDate,timeZone,HourlyTime,MinuteTime,cronId) 
              VALUES (p_LeadId,p_Method,p_connector,p_Email,p_ScheduleType,p_domainId,p_weekStatus,p_dayStatus,p_Time,p_lastUpdatedDate,p_timeZone,p_HourlyTime,p_MinuteTime,p_cronId);
              
 			SET p_LeadId = last_insert_id();
  			SET v_errcode = 0;
  			SET v_errmsg = 'Inserted successfully';
              
          END IF;
              SELECT v_errcode as errcode, v_errmsg as errmsg;
          END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
