CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdateLeadUserDetails`(
p_leadUserId INT,
p_name       VARCHAR(255),
p_email      VARCHAR(255),
p_phoneNumber BIGINT,
p_address      TEXT,
p_ipAddress    VARCHAR(100),
p_domainId     INT

)
BEGIN
         DECLARE v_curdate    DATETIME;
         DECLARE v_errcode    INT             DEFAULT -1;
         DECLARE v_errmsg     VARCHAR(100)    DEFAULT 'Failure';
          SET    v_curdate = now();
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
     	IF EXISTS(SELECT 1 FROM lead_User_Details WHERE leadUserId = p_leadUserId LIMIT 1) THEN
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         UPDATE lead_User_Details SET name=p_name,email=p_email,phoneNumber=p_phoneNumber,address=p_address,ipAddress=p_ipAddress,updatedAt=v_curdate,domainId=p_domainId
     		WHERE leadUserId = p_leadUserId ;
                 IF ROW_COUNT()>0
				 THEN
     			 SET v_errcode = 0;
                 SET v_errmsg = 'Updated successfully';
                 END IF;
             
         ELSE
     		 INSERT INTO lead_User_Details (leadUserId,`name`,email,phoneNumber,address,ipAddress,updatedAt,domainId) 
             VALUES (p_leadUserId,p_name,p_email,p_phoneNumber,p_address,p_ipAddress,v_curdate,p_domainId);
             
			SET p_leadUserId = last_insert_id();
 			SET v_errcode = 0;
 			SET v_errmsg = 'Inserted successfully';
             
         END IF;
             SELECT v_errcode AS errcode, v_errmsg AS errmsg;
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
