/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdatePrivateApp`(
      IN p_privateAppId INT,
      IN p_name         VARCHAR(255),
      IN p_description  VARCHAR(255),
      IN p_token        VARCHAR(255),
      IN p_adminEmail   VARCHAR(255),
      IN p_logo         VARCHAR(255),
      IN p_domainId     INT,
      IN p_scopeId      TEXT
  )
BEGIN
      DECLARE v_curdate DATETIME;
      DECLARE v_errcode INT DEFAULT -1;
      DECLARE v_errmsg VARCHAR(100) DEFAULT 'Insert PrivateApp is Failed';
      DECLARE v_row_count INT;
      DECLARE v_existing_privateAppId INT;
  
      SET v_curdate = NOW();
  
      sp_exit: BEGIN
      
              SELECT privateAppId INTO v_existing_privateAppId FROM tb_privateApp WHERE privateAppId = p_privateAppId;
              
              IF ( p_privateAppId IS NULL OR p_privateAppId = 0 )
              THEN
                  IF EXISTS (SELECT 1 FROM tb_privateApp WHERE domainId = p_domainId AND name = p_name LIMIT 1) THEN
                      SET v_errcode = -1;
                      SET v_errmsg = 'Name already exists for this Admin Email';
                      LEAVE sp_exit;
                  END IF;
  			END IF;
  
          IF p_privateAppId IS NOT NULL THEN
              UPDATE tb_privateApp
              SET
                  name = p_name,
                  description = p_description,
                
                  adminEmail = p_adminEmail,
                  logo = p_logo,
                
                  updatedAt = v_curdate
              WHERE privateAppId = v_existing_privateAppId;
              SET v_errcode = 1;
              SET v_errmsg = 'Updated Successfully';
              
          ELSE
              INSERT INTO tb_privateApp (
                  name,
                  description,
                  token,
                  adminEmail,
                  logo,
                  domainId,
                  createdAt,
                  updatedAt
              )
              VALUES (
                  p_name,
                  p_description,
                  p_token,
                  p_adminEmail,
                  p_logo,
                  p_domainId,
                  v_curdate,
                  v_curdate
              );
              
              SET p_privateAppId = LAST_INSERT_ID();
              SET v_errcode = 0;
              SET v_errmsg = 'Inserted successfully';
          END IF;
  
          DROP TEMPORARY TABLE IF EXISTS tt_temp_scopeId;
          CREATE TEMPORARY TABLE tt_temp_scopeId (scopeId BIGINT);
          CALL split(p_scopeId, ',');
          INSERT INTO tt_temp_scopeId (scopeId) SELECT Items FROM tt_Split_temptable;
  
          IF v_existing_privateAppId IS NOT NULL THEN
			IF p_scopeId IS NOT NULL AND p_scopeId <> '' THEN
             
              
              DELETE FROM tb_privateAppScope WHERE privateAppId = v_existing_privateAppId AND domainId = p_domainId;
              
              INSERT INTO tb_privateAppScope (privateAppId, scopeId, domainId, createdAt, updatedAt)
              SELECT p_privateAppId, scopeId, p_domainId, v_curdate, v_curdate
              FROM tt_temp_scopeId;
              
              SET v_errcode = 1;
              SET v_errmsg = 'Updated successfully';
			END IF;
          ELSE
              INSERT INTO tb_privateAppScope (privateAppId, scopeId, domainId, createdAt, updatedAt)
              SELECT p_privateAppId, scopeId, p_domainId, v_curdate, v_curdate
              FROM tt_temp_scopeId;
              
  			SET v_errcode = 0;
              SET v_errmsg = 'Inserted successfully';
          END IF;
  END;
      SELECT v_errcode AS errcode, v_errmsg AS errmsg;
  END ;;
DELIMITER ;
