CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insertUpdateQuestionAnswer`(	p_questionId            bigint
 	,p_domainId             int
 	,p_uuid                 varchar(45)
 	,p_question             text
 	,p_answer               text
 	,p_mapFlow              varchar(45)
 	,p_language             VARCHAR(100)
 	,p_intent               text
 	,p_keywords             text
 	,p_status               int
 	,p_version              varchar(45)
 	,p_sent                 int
 	,p_helpfull             int
 	,p_notHelpfull          int
 	,p_chatFlowId           int
 	,p_embedding            longtext
 	,p_websiteId            varchar(100)
 	,p_discription          varchar(255)
 	,p_websiteUrl           varchar(255)
 	,p_baseName             varchar(55)
 )
BEGIN
 	DECLARE v_CurDate		DATETIME;	
 	DECLARE v_questionId	BIGINT;
     DECLARE v_errMsg		VARCHAR(150) DEFAULT 'Question and Answer Failed';
     DECLARE v_errCode		INT DEFAULT -1;
     
     SET v_CurDate = NOW();
     
     SELECT 	questionId	
 	INTO 	v_questionId
     FROM 	question_answer
     WHERE 	questionId = p_questionId;
     
     IF v_questionId IS NULL
     THEN
 		INSERT INTO question_answer
         (	domainId
 			,uuid
 			,question
 			,answer
 			,mapFlow
 			,`language`
 			,intent
 			,keywords
 			,`status`
 			,version			
 			,sent
 			,helpfull
 			,notHelpfull
 			,chatFlowId
 			,embedding
 			,websiteId
 			,discription
 			,websiteUrl
 			,baseName
             ,createdAt
 			,updatedAt
         )
         VALUES
         (	p_domainId    
             ,p_uuid        
             ,p_question    
             ,p_answer      
             ,p_mapFlow     
             ,p_language    
             ,p_intent      
             ,p_keywords    
             ,p_status      
             ,p_version     
             ,p_sent        
             ,p_helpfull    
             ,p_notHelpfull 
             ,p_chatFlowId  
             ,p_embedding   
             ,p_websiteId   
             ,p_discription 
             ,p_websiteUrl  
             ,p_baseName    
 			,v_CurDate
             ,v_CurDate);
             
 		SET v_questionId 	= last_insert_id();
         SET v_errMsg		= 'Question and Answer added successfully'
 		, 	v_errCode		= 0;
 	ELSE
 		UPDATE 	question_answer
         SET  question		= p_question    
 			,answer			= p_answer      
 			,mapFlow		= p_mapFlow     
 			,`language`		= p_language    
 			,intent			= p_intent      
 			,keywords		= p_keywords    
 			,`status`		= p_status      
 			,version		= p_version     
 			,sent			= p_sent        
 			,helpfull		= p_helpfull    
 			,notHelpfull	= p_notHelpfull 
 			,chatFlowId		= p_chatFlowId  
 			,embedding		= p_embedding   
 			,websiteId		= p_websiteId   
 			,discription	= p_discription 
 			,websiteUrl		= p_websiteUrl  
 			,baseName		= p_baseName               
 			,updatedAt		= v_CurDate
         WHERE questionId 	= v_questionId; 
         
 		SET v_errMsg		= 'Question and Answer added successfully'
 		, 	v_errCode		= 0;
     END IF;
         
 	SELECT v_questionId	AS questionId, v_errCode AS errCode, v_errMsg  AS errMsg; 
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
