CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insertUpdateSyncCallBlastContacts`(
     p_domainId INT
)
BEGIN
     DECLARE v_curDate	DATETIME DEFAULT NOW();
     
    CREATE INDEX ix_tt_importContactFile_PN on tt_importContactFile(j_PhoneNumber);
    
	update 	customer_contact 		CC
    JOIN 	tt_importContactFile	t_CC ON t_CC.j_PhoneNumber 	collate utf8mb4_unicode_ci = CC.primaryPhoneNumber
										AND	CC.domainId 		= p_domainId
    SET 	firstName 			= IFNULL(j_FirstName,firstName)
		, 	lastName 			= IFNULL(j_LastName,lastName)
		, 	CustomerUniqueId 	= IFNULL(j_CustomerUniqueId,CustomerUniqueId)
		,  	updatedAt 	= v_curDate;

    INSERT INTO customer_contact (firstName, lastName, primaryPhoneNumber,CustomerUniqueId,email,domainId,createdAt,updatedAt)
    SELECT 	t_CC.j_FirstName, t_CC.j_LastName, t_CC.j_PhoneNumber,t_CC.j_CustomerUniqueId,'[]',p_domainId,v_curDate,v_curDate 
    FROM 	tt_importContactFile	t_CC 
    LEFT JOIN customer_contact 		CC		ON 	t_CC.j_PhoneNumber 	collate utf8mb4_unicode_ci = CC.primaryPhoneNumber
											AND CC.domainId			= p_domainId
	WHERE 	CC.coid	IS NULL;
     
END ;;
DELIMITER ;
