CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insertUpdateSyncCallBlastContacts_test`(
     IN p_domainId INT
)
BEGIN
    UPDATE customer_contact c
    JOIN tt_importContactFile t ON c.primaryPhoneNumber = t.j_PhoneNumber AND c.domainId = p_domainId
    SET
        c.firstName = IFNULL(t.j_FirstName, c.firstName),
        c.lastName = IFNULL(t.j_LastName, c.lastName),
        c.updatedAt = NOW();

    INSERT INTO customer_contact (firstName, lastName, primaryPhoneNumber, email, domainId, createdAt, updatedAt)
    SELECT        t.j_FirstName,t.j_LastName,t.j_PhoneNumber,'[]',p_domainId,NOW(),NOW()
    FROM tt_importContactFile t
    LEFT JOIN customer_contact c ON c.primaryPhoneNumber = t.j_PhoneNumber AND c.domainId = p_domainId
    WHERE c.primaryPhoneNumber IS NULL;
END ;;
