CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdateWhatsappDocument`(
     IN p_documentId VARCHAR(250),
     IN p_isSent     tinyint,
     IN p_isSigned   tinyint,
     IN p_isRejected tinyint,
     IN p_domainId   INT
 )
BEGIN
     DECLARE v_curdate DATETIME;
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(100) DEFAULT 'Insert Whatsapp Document is Failed';
     DECLARE v_row_count INT;
     DECLARE v_documentId VARCHAR(250);
 
     SET v_curdate = NOW();
 
     BEGIN
         SELECT documentId INTO v_documentId FROM tb_WhatsappDocument WHERE documentId = p_documentId;
         IF v_documentId IS NULL THEN
             INSERT INTO tb_WhatsappDocument (
                 documentId,
                 isSent,
                 isSigned,
                 isRejected,
                 domainId,
                 createdDate,
                 updatedDate
             ) VALUES (
                 p_documentId,
                 p_isSent,
                 p_isSigned,
                 p_isRejected,
                 p_domainId,
                 v_curdate,
				 v_curdate
             );
 
             SET v_documentId = LAST_INSERT_ID();
             SET v_errcode = 0;
             SET v_errmsg = 'Inserted Successfully';
         ELSE
             UPDATE tb_WhatsappDocument
             SET
                 isSigned = p_isSigned,
                 isRejected = p_isRejected,
                 updatedDate =v_curdate
             WHERE
                 documentId = v_documentId;
 
             SET v_errcode = 0;
             SET v_errmsg = 'Updated Successfully';
         END IF;
 
         SELECT v_errcode AS 'errcode', v_errmsg AS 'errmsg';
     END;
 END ;;
DELIMITER ;
