CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdateworktualApp`(
             IN p_appId                 INT,
             IN p_name         VARCHAR(255),
             IN p_description  VARCHAR(255),
             IN p_token        VARCHAR(255),
             IN p_adminEmail   VARCHAR(255),
             IN p_logo         VARCHAR(255),
             IN p_domainId     INT,
             IN p_scopeId      TEXT,
             IN p_clientId     VARCHAR(100),
             IN p_clientSecret VARCHAR(100),
             IN p_redirectUrl  VARCHAR(255),
             IN p_isPublicApp  TINYINT,
             IN p_siploginid   INT,
             IN p_ext          INT,
             IN p_productType  VARCHAR(50)
         )
BEGIN
             DECLARE v_curdate DATETIME;
             DECLARE v_errcode INT DEFAULT -1;
             DECLARE v_errmsg VARCHAR(100) DEFAULT 'Insert WorktualApp is Failed';
             DECLARE v_row_count INT;
             DECLARE v_existing_worktualAppId INT;
         
             SET v_curdate = NOW();
         
             sp_exit: BEGIN
             
                     SELECT appId INTO v_existing_worktualAppId FROM tb_worktualApp WHERE appId = p_appId;
                     
                     IF ( p_appId IS NULL OR p_appId = 0 and  p_siploginid is null)
                     THEN
                         IF EXISTS (SELECT 1 FROM tb_worktualApp WHERE domainId = p_domainId AND name = p_name and productType = p_productType and isDelete is null LIMIT 1) THEN  
                             SET v_errcode = -1;
                             SET v_errmsg = 'Name already exists for this Email';
                             LEAVE sp_exit;
                         END IF;
                         elseif( p_appId IS  NULL OR p_appId = 0 and  p_siploginid is not null)
                           THEN
                           IF EXISTS (SELECT 1 FROM tb_worktualApp WHERE domainId = p_domainId AND name = p_name and siploginid= p_siploginid and  productType = p_productType and isDelete is null  LIMIT 1) THEN  
                             SET v_errcode = -1;
                             SET v_errmsg = 'Name already exists for this Email';
                             LEAVE sp_exit;                          
   						END IF;
   					    END IF;
 
 
                 IF p_appId IS NOT NULL THEN
                     UPDATE tb_worktualApp              
                     SET
                         name = p_name,
                         description = p_description,
                       
                         adminEmail = p_adminEmail,
                         logo = p_logo,
    					 redirectUrl=p_redirectUrl,  
                         updatedAt = v_curdate
                     WHERE appId = v_existing_worktualAppId;
                     SET v_errcode = 1;
                     SET v_errmsg = 'Updated Successfully';
                     
                 ELSE
                     INSERT INTO tb_worktualApp (
                         name,
                         description,
                         token,
                         adminEmail,
                         logo,
                         domainId,
    					 clientId,
    					 clientSecret,
    					 redirectUrl,
    					 isPublicApp,
                         siploginid,
                         ext,
                         productType,
                         createdAt,
                         updatedAt
                     )
                     VALUES (
                         p_name,
                         p_description,
                         p_token,
                         p_adminEmail,
                         p_logo,
                         p_domainId,
      				     p_clientId,
                         p_clientSecret,
                         p_redirectUrl,
                         p_isPublicApp,
                         p_siploginid,
                         p_ext,
                         p_productType,                        
                         v_curdate,
                         v_curdate
                     );
                     
                     SET p_appId = LAST_INSERT_ID();
                     SET v_errcode = 0;
                     SET v_errmsg = 'Inserted successfully';
                 END IF;
         
                 DROP TEMPORARY TABLE IF EXISTS tt_temp_scopeId;
                 CREATE TEMPORARY TABLE tt_temp_scopeId (scopeId BIGINT);
                 CALL split(p_scopeId, ',');
                 INSERT INTO tt_temp_scopeId (scopeId) SELECT Items FROM tt_Split_temptable;
         
                 IF v_existing_worktualAppId IS NOT NULL THEN
       			IF p_scopeId IS NOT NULL AND p_scopeId <> '' THEN
                    
                     
                     DELETE FROM tb_worktualAppScope WHERE appId = v_existing_worktualAppId AND domainId = p_domainId;
                     
                     INSERT INTO tb_worktualAppScope (appId, scopeId, domainId, createdAt, updatedAt)
                     SELECT p_appId, scopeId, p_domainId, v_curdate, v_curdate
                     FROM tt_temp_scopeId;
                     
                     SET v_errcode = 1;
                     SET v_errmsg = 'Updated successfully';
       			END IF;
                 ELSE
                     INSERT INTO tb_worktualAppScope (appId, scopeId, domainId, createdAt, updatedAt)
                     SELECT p_appId, scopeId, p_domainId, v_curdate, v_curdate
                     FROM tt_temp_scopeId;
                     
         			SET v_errcode = 0;
                     SET v_errmsg = 'Inserted successfully';
                 END IF;
         END;
             SELECT v_errcode AS errcode, v_errmsg AS errmsg;
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
