CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertUpdate_CRM_ContactSyncDetails`(
p_csid					int,
p_domainId				int,
p_roleId				int,
p_connectorId 			int,
p_connectorName 		varchar(50),
p_refreshTime			bigint,
p_syncParameterArray	json ,
p_primaryParameter 		varchar(50)
)
BEGIN
		DECLARE v_errcode  		INT ;
    	DECLARE v_errmsg   		VARCHAR(55);
		DECLARE v_csid			INT;
        DECLARE v_curdate		DATETIME;
        
        SET v_curdate = now();
        
        
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
		SELECT 	csid INTO v_csid
		FROM 	tb_CRM_ContactSyncDetails
		WHERE 	csid 		= p_csid
		AND		domainId 	= p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     IF v_csid IS NULL
     THEN
 		insert into tb_CRM_ContactSyncDetails(domainId,
										roleId,
										connectorId,
										connectorName,
										refreshTime,
										syncParameterArray,
                                        primaryParameter,
                                        createdAt
										)
								values(p_domainId,
										p_roleId,
										p_connectorId,
										p_connectorName,
										p_refreshTime,
										p_syncParameterArray,
                                        p_primaryParameter,
                                        v_curdate
										);
         
         SET v_csid 	= last_insert_id();       
         SET v_errcode	= 0;
         SET v_errmsg 	= 'Inserted Successfully';
 	ELSE
 		UPDATE tb_CRM_ContactSyncDetails
		SET 
		roleId				=  IFNULL(p_roleId			  ,roleId			),	
		connectorId 		=  IFNULL(p_connectorId		  ,connectorId 		),
		connectorName 		=  IFNULL(p_connectorName	  ,connectorName 	),	
		refreshTime			=  IFNULL(p_refreshTime		  ,refreshTime		),	
		syncParameterArray	=  IFNULL(p_syncParameterArray,syncParameterArray),
        primaryParameter	=  IFNULL(p_primaryParameter  ,primaryParameter)
         WHERE csid 	= v_csid;
         
         SET v_errcode	= 0;
         SET v_errmsg 	= 'Updated Successfully';
     END IF;
     
     SELECT v_errcode  'errcode', v_errmsg 'errmsg';
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
