CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insertupdate_custom_report`(
	p_reportId 			INT
	,p_domainId 		INT
	,p_reportName 		VARCHAR(150)
	,p_reportDesc 		TEXT
	,p_startdate 		DATETIME
	,p_enddate 			DATETIME
	,p_reportType 		INT
	,p_timeZone 		VARCHAR(150)
	,p_timeFormat 		VARCHAR(20)
    ,p_reportColumn 	TEXT
    ,p_reportCategory 	VARCHAR(100)
    ,p_startTmpstmp		BIGINT
	,p_endTmpstmp		BIGINT
    ,p_createdBy		INT
)
Begin
	declare v_errcode 	int default -1;
    declare v_errmsg 	varchar(50) default 'Failure';
    declare v_reportId 	int;
    declare v_lastId 	int;
    
    
    select reportId into v_reportId from tb_custom_report_dtl where reportId = p_reportId limit 1;
    
	if v_reportId is null then 
		insert into tb_custom_report_dtl(reportId,domainId, reportName, reportDesc, startdate, enddate, reportType, timeZone, timeFormat, reportColumn,reportCategory,createdBy)
		values(p_reportId,p_domainId, p_reportName, p_reportDesc, p_startdate, p_enddate, p_reportType, p_timeZone, p_timeFormat, p_reportColumn,p_reportCategory,p_createdBy);
        
        SET v_lastId = last_insert_id();
        
        IF p_reportCategory = 'Agent'
        THEN
			CALL ccaas_getCustomReport_Agent(p_startTmpstmp,p_endTmpstmp,p_domainId,null,null,p_reportColumn,1000,0,v_lastId);
		ELSEIF p_reportCategory = 'Voice'
		THEN	
			CALL ccaas_getCustomReport_Voice(p_startTmpstmp,p_endTmpstmp,null,p_domainId,null,null,null,null,null,null,null,null,p_reportColumn,1000,0,v_lastId);
		ELSEIF p_reportCategory = 'Email'
		THEN	
			CALL ccaas_getCustomReport_Email(p_startTmpstmp,p_endTmpstmp,null,p_domainId,null,null,null,1000,0,p_reportColumn,v_lastId);
		ELSEIF p_reportCategory = 'SMS'
		THEN	
			CALL ccaas_getCustomReport_SMS(p_startTmpstmp,p_endTmpstmp,null,p_domainId,null,null,null,null,0,1000,p_reportColumn,v_lastId);
		ELSEIF p_reportCategory = 'Chat'
		THEN	
			CALL ccaas_getCustomReport_Chat(p_reportColumn,p_domainId,p_startTmpstmp,p_endTmpstmp,v_lastId);
		ELSEIF p_reportCategory = 'AI'
		THEN	
			CALL ccaas_getCustomReport_AI(p_startTmpstmp,p_endTmpstmp,null,p_domainId,null,null,null,1000,0,p_reportColumn,v_lastId);
		ELSEIF p_reportCategory = 'Whatsapp'
        THEN	
			CALL get_WhatsappCustomReports(p_reportColumn,p_domainId,p_startTmpstmp,p_endTmpstmp,v_lastId);
		ELSEIF p_reportCategory = 'Facebook'
        THEN	
			CALL get_FacebookCustomReports(p_reportColumn,p_domainId,p_startTmpstmp,p_endTmpstmp,v_lastId);
		ELSEIF p_reportCategory = 'Instagram'
        THEN	
			CALL get_InstagramCustomReports(p_reportColumn,p_domainId,p_startTmpstmp,p_endTmpstmp,v_lastId);
		
		END IF;
        
			set v_errcode = 0;
            set v_errmsg = 'Inserted';

	else
        update tb_custom_report_dtl a
        set reportName = ifnull(p_reportName, reportName)
			,reportDesc = ifnull(p_reportDesc, reportDesc)
            ,startdate = ifnull(p_startdate, startdate) 
            ,enddate = ifnull(p_enddate, enddate) 
            ,reportType = ifnull(p_reportType, reportType)
            ,timeZone = ifnull(p_timeZone, timeZone)
            ,timeFormat = ifnull(p_timeFormat, timeFormat)
            ,reportColumn = ifnull(p_reportColumn,reportColumn)
            ,reportCategory = ifnull(p_reportCategory,reportCategory)
        where reportId = p_reportId ;
        
        if row_count()>0 then
			set v_errcode = 0;
            set v_errmsg = 'Updated';
        End if;
        
    End if;
    
    select v_errcode as errcode, v_errmsg as errmsg, ifnull(v_reportId,v_lastId) as reportId;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
