CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insertUpdate_interactionNotes`(
	 p_domainId				INT 
    ,p_historyId			INT
    ,p_coid					INT
    ,p_agentId				INT
    ,p_channelType			VARCHAR(20)
    ,p_notes				JSON
)
begin

	DECLARE v_nid INT;
	DECLARE v_errcode INT DEFAULT -1;
	DECLARE v_errmsg VARCHAR(100) DEFAULT 'Notes Insert/Update Fail';

	SELECT 	nid INTO v_nid
    FROM 	tb_interaction_notes_info
    WHERE 	domainId = p_domainId
    AND 	historyId = p_historyId;
    
    IF v_nid IS NULL
    THEN
		INSERT INTO tb_interaction_notes_info(domainId,historyId,coid,agentId,channelType,notes,createdAt,updatedAt)
		VALUES(p_domainId,p_historyId,p_coid,p_agentId,p_channelType,p_notes,now(),now());
        
        SET v_errcode = 0;
        SET v_errmsg = 'Note Insert Successfully';
	
    ELSE
    
		UPDATE tb_interaction_notes_info
        SET notes = IFNULL(p_notes,notes)
        WHERE nid = v_nid;
        
        SET v_errcode = 1;
        SET v_errmsg = 'Note Updated Successfully';
   
   END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;

end ;;
DELIMITER ;
