CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insertUpdate_TriggerMessage`(
 p_tmid 				bigint,
 p_Field 			longtext,
 p_message 			longtext,
 p_callbackMessage 	longtext,
 p_domainId 			int
 )
begin
 
 	DECLARE v_errcode  int;
     DECLARE v_errmsg   varchar(50);
SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 if exists(Select 1 from tb_triggerMessages where tmid = p_tmid limit 1)

 then
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 update tb_triggerMessages
 set Field 				= IFNULL(p_Field,Field)	,
 	message 			= IFNULL(p_message,message)	,
 	callbackMessage 	= IFNULL(p_callbackMessage,callbackMessage)	
     where tmid = p_tmid ;
     
 if row_count()>0
 then
 set v_errcode   = 0;
 set v_errmsg 	= 'Updated Successfully';
 end if;
 
 else 
 
 insert into tb_triggerMessages(Field,message,callbackMessage,domainId)
 						values(p_Field,p_message,p_callbackMessage,p_domainId);
 
 if row_count()>0
 then
 set v_errcode   = 1;
 set v_errmsg 	= 'Inserted Successfully';
 end if;
 
 end if;
 
 select v_errcode as errcode , v_errmsg as errmsg;
 
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
