CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InsertVistorInsights`(
      p_vistorId    INT,
      p_location    VARCHAR(255),
      p_deviceType  VARCHAR(100),
      p_domainId    INT,
      p_ipAddress   VARCHAR(255),
      p_browser     VARCHAR(255),
      p_language    VARCHAR(255),
      p_duration    BIGINT,
      p_inTime      DATETIME,
      p_outTime     DATETIME,
      p_entryPage   VARCHAR(255),
      p_exitPage    VARCHAR(255),
      p_totalPageView INT,
      p_originURL    TEXT
 )
BEGIN
     DECLARE v_curdate DATETIME;
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg  VARCHAR(100) DEFAULT 'Insert Vistor Insights is Failed';
     DECLARE v_vistorId INT;
     
     SET v_curdate = NOW();
     INSERT INTO tb_VistorInsights (
         vistorId,
         location,
         deviceType,
         domainId,
         ipAddress,
         browser,
         language,
         duration,
         inTime,
         outTime,
         entryPage,
         exitPage,
         totalPageView,
         originURL,
         createdAt,
         updatedAt
     )
     VALUES (
         p_vistorId,
         p_location,
         p_deviceType,
         p_domainId,
         p_ipAddress,
         p_browser,
         p_language,
         p_duration,
         p_inTime,
         p_outTime,
         p_entryPage,
         p_exitPage,
         p_totalPageView,
         p_originURL,
         v_curdate,
         v_curdate
     );
     SET v_vistorId = LAST_INSERT_ID();
     SET v_errcode = 0;
     SET v_errmsg = 'Vistor Insights Inserted successfully';
 
     SELECT v_vistorId as vistorId ,v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
