CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_agent_skill`(
      p_domainId INT,
      p_userId INT,
      p_addSkill JSON
)
BEGIN
    DECLARE v_userId INT;
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(150) DEFAULT 'Failed';
    DECLARE v_curDate DATETIME DEFAULT NOW();

    
    SELECT UserID INTO v_userId
    FROM tb_User
    WHERE domainId = p_domainId
      AND UserID = p_userId;

    IF v_userId IS NOT NULL THEN
    
        
        DROP TEMPORARY TABLE IF EXISTS tt_addSkill;
        CREATE TEMPORARY TABLE tt_addSkill (
            idnt INT AUTO_INCREMENT PRIMARY KEY,
            j_type VARCHAR(250),
            j_value VARCHAR(250)
        );

        
        INSERT INTO tt_addSkill (j_type, j_value)
        SELECT type, value
        FROM JSON_TABLE(
            p_addSkill,
            "$[*]" COLUMNS(
                type VARCHAR(250) PATH "$.type",
                value VARCHAR(250) PATH "$.value"
            )
        ) AS parsed_json;

        
        INSERT INTO skills (skill_name, skill_description, domainId, createdAt, updatedAt, status, type)
        SELECT 
            t.j_value, 
            t.j_value, 
            p_domainId, 
            v_curDate, 
            v_curDate, 
            1, 
            t.j_type
        FROM tt_addSkill t
        LEFT JOIN skills s ON s.skill_name = t.j_value
              AND s.domainId = p_domainId
        WHERE s.skill_name IS NULL;

        
        DROP TEMPORARY TABLE IF EXISTS tt_finalSkillIds;
        CREATE TEMPORARY TABLE tt_finalSkillIds (sid INT PRIMARY KEY);

        INSERT INTO tt_finalSkillIds (sid)
        SELECT s.sid
        FROM skills s
        JOIN tt_addSkill t ON s.skill_name = t.j_value
            AND s.domainId = p_domainId;

        
        UPDATE tb_User
        SET addSkill = IFNULL(p_addSkill, addSkill)
        WHERE UserID = v_userId;
        
        IF v_userId IS NOT NULL
        THEN
			DELETE FROM skillMapping
			WHERE usid = v_userId
			AND domainId = p_domainId;
			
			
			INSERT INTO skillMapping (skid, usid, domainId, createdAt, updateddAt)
			SELECT f.sid, v_userId, p_domainId, NOW(), NOW()
			FROM tt_finalSkillIds f
			LEFT JOIN skillMapping sm ON sm.skid = f.sid
				  AND sm.usid = v_userId
				  AND sm.domainId = p_domainId
			WHERE sm.skid IS NULL;
		END IF;
        SET v_errcode = 0;
        SET v_errmsg = 'Skills inserted/mapped successfully';

    ELSE
        SET v_errcode = -1;
        SET v_errmsg = 'User not found';
    END IF;

    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
