CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_cookie_session_conservation_v2`(
 	p_domainId int,
 	p_mobileno varchar(50),
 	p_email varchar(100),
 	p_webcookie_id varchar(50),
 	p_sessionId varchar(100),
 	p_facebook_id bigint,
 	p_instagram_id bigint,
 	p_email_summary json,
 	p_whatsapp_summary json,
 	p_facebook_summary json,
 	p_instagram_summary json,
 	p_webchat_Summary json,
 	p_call_summary json,
 	p_sms_summary json,
     p_customerName varchar(50),
     p_ticketSummary json
     )
Begin
     
     	declare v_errcode int default -1;
         declare v_errmsg varchar(50) default 'Failure';
         
         START TRANSACTION;
         
         if not exists(select 1 from tb_cookie_session_conservation_v2 where domainId = p_domainId and (mobileno collate utf8mb4_unicode_ci = p_mobileno 
 					or email collate utf8mb4_unicode_ci = p_email or webcookie_id collate utf8mb4_unicode_ci = p_webcookie_id or facebook_id = p_facebook_id or instagram_id = p_instagram_id)) then
 		
 			insert into tb_cookie_session_conservation_v2(domainId, mobileno, email, webcookie_id, sessionId, facebook_id, instagram_id, 
 					email_summary, whatsapp_summary, facebook_summary, instagram_summary, webchat_Summary, call_summary, sms_summary, customerName, ticketSummary)
 			values(p_domainId, p_mobileno, p_email, p_webcookie_id, p_sessionId, p_facebook_id, p_instagram_id, 
 					p_email_summary, p_whatsapp_summary, p_facebook_summary, p_instagram_summary, p_webchat_Summary, p_call_summary, p_sms_summary, p_customerName, p_ticketSummary);
 			
             if row_count()>0 then
 				set v_errcode = 0;
                 set v_errmsg = 'Inserted';
             End if;
         Else
 			update tb_cookie_session_conservation_v2 
             set webcookie_id = ifnull(p_webcookie_id, webcookie_id)
 				,facebook_id = ifnull(p_facebook_id,facebook_id)
 				,instagram_id = ifnull(p_instagram_id,instagram_id)
 				,email_summary = ifnull(p_email_summary,email_summary)
 				,whatsapp_summary = ifnull(p_whatsapp_summary,whatsapp_summary)
                 ,facebook_summary = ifnull(p_facebook_summary,facebook_summary)
                 ,instagram_summary = ifnull(p_instagram_summary,instagram_summary)
                 ,webchat_Summary = ifnull(p_webchat_Summary,webchat_Summary)
                 ,call_summary = ifnull(p_call_summary,call_summary)
                 ,sms_summary = ifnull(p_sms_summary,sms_summary)
                 ,customerName = ifnull(p_customerName,customerName)
                 ,ticketSummary = ifnull(p_ticketSummary,ticketSummary)
 			where domainId = p_domainId and 
             (mobileno collate utf8mb4_unicode_ci = p_mobileno or email collate utf8mb4_unicode_ci = p_email or webcookie_id collate utf8mb4_unicode_ci = p_webcookie_id or facebook_id = p_facebook_id or instagram_id = p_instagram_id);
             
             if row_count()>0 then
 				set v_errcode = 0;
                 set v_errmsg = 'Updated';
             End if;
         
         End if;
 
         COMMIT;
 			select v_errcode as errcode, v_errmsg as errmsg;
     	 
     End ;;
DELIMITER ;
