CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insert_customer_contact`(
 p_domainId int
 ,p_firstName	varchar(100)
 ,p_lastName	varchar(100)
 ,p_phoneNumber	varchar(750)
 ,p_email	varchar(1500)
 ,p_accountNumber	varchar(100)
 ,p_tags	varchar(750)
 ,p_location	varchar(100)
 ,p_address	varchar(225)
 ,p_country	varchar(100)
 ,p_state	varchar(100)
 ,p_city	varchar(100)
 ,p_postalCode	varchar(100)
 ,p_facebook	varchar(100)
 ,p_instagram	varchar(100)
 ,p_whatsapp	varchar(100)
 ,p_twitter	varchar(100)
 ,p_customerType varchar(255)
 ,p_voiceBiometric	varchar(100)
 )
begin
 
 	declare v_errcode int default -1;
     declare v_errmsg varchar(20) default 'Failure';
 
 	
 	if not exists(SELECT 1 FROM customer_contact WHERE (phoneNumber collate utf8mb4_0900_ai_ci  LIKE concat('%',p_phoneNumber,'%') OR email collate utf8mb4_0900_ai_ci  = p_email) AND domainId =p_domainId) then
 		INSERT INTO customer_contact (firstName,lastName,phoneNumber,email,accountNumber,tags,location,address,country,state,city,postalCode,facebook,instagram,whatsapp,twitter,
             domainId,createdAt,voiceBiometric,customerType) 
 		VALUES (p_firstName,p_lastName,p_phoneNumber,p_email,p_accountNumber,p_tags,p_location,p_address,p_country,p_state,p_city,p_postalCode,p_facebook,p_instagram,p_whatsapp,p_twitter,
 			p_domainId,current_timestamp(),p_voiceBiometric,p_customerType);
		
         select 0 as errcode, 'Inserted' as errmsg;
    Else
		select 1 as errcode, 'Record found' as errmsg;
	
 	End if;
      
      
 
 End ;;
DELIMITER ;
