CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_email_domain_configuration`(
		p_domainId		int
	,	p_companyId		int
	,	p_domainName	varchar(550)
	,	p_status		varchar(150)
	,	p_remarks		text
	,	p_host1			text
	,	p_value1		text
	,	p_host2			text
	,	p_value2		text
	,	p_host3			text
	,	p_value3		text
)
begin
	
