CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_email_subscription`(
	 p_fromEmail	VARCHAR(250)
    ,p_toEmail		VARCHAR(250)
    ,p_isSubscribed	TINYINT
)
begin

	DECLARE v_eid 		INT;
	DECLARE v_errcode 	INT;
	DECLARE v_errmsg 	VARCHAR(100);

	select eid into v_eid 
    from tb_email_subscription_dtl
    where fromEmail = p_fromEmail
    and toEmail = p_toEmail;
    
    IF v_eid IS NULL 
    THEN 
		INSERT INTO tb_email_subscription_dtl(fromEmail,toEmail,isUnSubscribed,createdAt,updatedAt)
        VALUES(p_fromEmail,p_toEmail,p_isSubscribed,now(),now());
        
        SET v_errcode = 0;
        SET v_errmsg = 'Email subscription inserted successfully';
        
	END IF;
	
	SELECT v_errcode as errcode,v_errmsg as errmsg;

end ;;
