CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_facebook_callback_status`(
 	 p_domainId 			INT
     ,p_sessionId			varchar(500)
     ,p_IsInBound			tinyint
     ,p_customerFacebookId	varchar(100)
     ,p_agentFacebookId		varchar(100)
     ,p_FacebookHistoryId	bigint
 )
begin
 
 		DECLARE v_errcode 				INT DEFAULT -1;
 		DECLARE v_errmsg  				VARCHAR(100) DEFAULT 'Facebook callback status insert fail';
 		DECLARE v_FacebookHistory 	INT;
        DECLARE v_customerId INT;
 
 		UPDATE tb_FacebookHistory
 		SET IsBot = 1
 		WHERE FacebookHistoryId = p_FacebookHistoryId; 
        
        select coid INTO v_customerId
        FROM customer_contact
        WHERE domainId = p_domainId 
        AND facebook = p_customerFacebookId
        ORDER BY 1 DESC;
 
 		INSERT INTO tb_FacebookHistory(sessionId,sessionStartTime,sessionEndTime,domainId,IsInBound,noOfRepeats,IsSessionClosed,customerFacebookId,agentFacebookId,createdAt,updatedAt,isCallback,callbackDraft, customerId)
         VALUES(p_sessionId,(unix_timestamp()*1000),0,p_domainId,p_IsInBound,0,0,p_customerFacebookId,p_agentFacebookId,now(),now(),1,0, v_customerId);
 		
         SET v_FacebookHistory = last_insert_id();
     
 		INSERT INTO tb_FacebookMessage(FacebookHistoryId,Message,createdAt,updatedAt)
         VALUES(v_FacebookHistory,null,now(),now());
     
     SET v_errcode = 0;
     SET v_errmsg  = 'Facebook callback status inserted successfully';
 
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
     
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
