CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insert_facebook_message_flow_break_bot`(
	p_facebookHistoryId	int
    ,p_domainId			int
    ,p_message 			text
    ,p_customerNumber	bigint
)
begin
	declare v_errcode 	int default -1;
	declare v_errmsg  	varchar(100) default 'facebook msg updated failed';
    DECLARE v_mid		int;
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
    select mid INTO v_mid from tb_facebook_message_flow_break_bot where facebookHistoryId = p_facebookHistoryId and domainId = p_domainId limit 1;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    if v_mid IS NULL
    then    
		insert into tb_facebook_message_flow_break_bot(facebookHistoryId, domainId, message, customerNumber, createdAt)
		values(p_facebookHistoryId ,p_domainId ,p_message ,p_customerNumber,now());
		
		if row_count() > 0
		then
			set v_errcode = 0;
			set v_errmsg  = 'facebook msg updated successfully';
		end if;      
	end if; 

	select v_errcode as errcode, v_errmsg as errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
