CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_KnowledgeBase`(	
	p_domainId				INT,
	p_website_UUID			VARCHAR(500),
	p_knowledgeBaseType 	INT,
	p_createType			TINYINT,
	p_categoryId			INT,
	p_articlePath 			JSON,
	p_webPageUrl 			VARCHAR(2000),
	p_articleLanguage 		VARCHAR(50), 
	p_articleStatus			VARCHAR(50),
	p_metaDesc				TEXT,
	p_relatedpages			VARCHAR(500),
	p_CategoryName 			VARCHAR(150),
	p_CategoryDescription 	VARCHAR(500),
	p_createdBy				INT
)
BEGIN
	DECLARE v_kid 			INT DEFAULT NULL;
	DECLARE v_curDate 		DATETIME DEFAULT NOW();
	DECLARE v_catId 		INT DEFAULT NULL;
	DECLARE v_errcode		TINYINT DEFAULT -1;
	DECLARE v_errmsg		VARCHAR(150) DEFAULT 'Knowledge Base Insert Failed';
	DECLARE v_ArticleId 	INT DEFAULT NULL;

	SELECT kid INTO v_kid
	FROM tb_KnowledgeBaseDtl
	WHERE domainId = p_domainId;

	IF v_kid IS NULL THEN
		INSERT INTO tb_KnowledgeBaseDtl(domainId, website_UUID, createdAt, updatedAt)
		VALUES (p_domainId, p_website_UUID, v_curDate, v_curDate);
		SET v_kid = LAST_INSERT_ID();
	END IF;

	IF p_CategoryName IS NOT NULL THEN
		INSERT INTO tb_KnowledgeBaseCategory(fk_kid, CategoryName, CategoryDescription, knowledgeBaseType, createdBy, CreatedDate, UpdatedDate)
		VALUES (v_kid, p_CategoryName, p_CategoryDescription, p_knowledgeBaseType, p_createdBy, v_curDate, v_curDate);
		SET v_catId = LAST_INSERT_ID();
		SET v_errcode = 0;
		SET v_errmsg  = 'KnowledgeBase Category Created Successfully';
	END IF;

	SELECT KBA.ArticleId INTO v_ArticleId
	FROM tb_KnowledgeBaseDtl KB
	JOIN tb_KnowledgeBaseArticleDtl KBA ON KB.kid = KBA.fk_kid
	WHERE KB.domainId = p_domainId
	AND KBA.knowledgeBaseType = p_knowledgeBaseType
	AND KBA.webPageUrl IS NOT NULL
    AND p_webPageUrl IS NOT NULL
	LIMIT 1;

	IF v_ArticleId IS NOT NULL THEN
		UPDATE tb_KnowledgeBaseArticleDtl
		SET webPageUrl = IFNULL(p_webPageUrl, webPageUrl),
			updatedAt  = v_curDate
		WHERE ArticleId = v_ArticleId;

		SET v_errcode = 0;
		SET v_errmsg  = 'KnowledgeBase WebPage Updated Successfully';

	ELSEIF (p_articlePath IS NOT NULL OR p_webPageUrl IS NOT NULL )
    THEN
		INSERT INTO tb_KnowledgeBaseArticleDtl(fk_kid, knowledgeBaseType, createType, categoryId, articlePath, webPageUrl, articleLanguage, articleStatus, metaDesc, relatedpages, createdBy, createdAt, updatedAt)
		VALUES (v_kid, p_knowledgeBaseType, p_createType, IFNULL(p_categoryId, v_catId), p_articlePath, p_webPageUrl, p_articleLanguage, p_articleStatus, p_metaDesc, p_relatedpages, p_createdBy, v_curDate, v_curDate);

		SET v_errcode = 0;
		SET v_errmsg  = 'KnowledgeBase Created Successfully';
	END IF;

	SELECT v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
