CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_prompt_text`(
 		 p_fieldname 		VARCHAR(100),
 		  p_encoding 		VARCHAR(100) ,
 		  p_mimetype 		VARCHAR(100),
 		  p_filename 		VARCHAR(150) ,
 		  p_path 			LONGTEXT,
 		  p_size 			INT,
 		  p_type 			VARCHAR(100),
 		  p_promptType 		INT ,
 		  p_url 			LONGTEXT,
 		  p_name 			VARCHAR(100),
 		  p_description 	VARCHAR(255) ,
 		  p_domainId 		INT ,
 		  p_companyId 		INT ,
 		  p_message 		VARCHAR(3000) ,
 		  p_promptStatus 	VARCHAR(25),
          p_queueId			INT,
          p_uuid			INT		
 )
BEGIN					

			DECLARE  v_errCode			SMALLINT  	default -1;
			DECLARE  v_errMsg			VARCHAR(30)  default "Failed";
            DECLARE v_uuid				INT;
            DECLARE  v_insertId			INT			 default -1;
		
        SELECT uuid INTO v_uuid
        FROM prompt_library 
        WHERE uuid = p_uuid
        AND domainId = p_domainId;
		
        IF v_uuid IS NULL
        THEN
			INSERT INTO prompt_library (fieldname , encoding, mimetype, filename, `path`, size, `type`, promptType, url, `name` , `description`  , domainId , companyId , message , promptStatus, createdAt, queueId)
			VALUES(p_fieldname , p_encoding, p_mimetype, p_filename, p_path, p_size, p_type, p_promptType, p_url , p_name , p_description  , p_domainId , p_companyId , p_message , p_promptStatus, now(), p_queueId);
              
            SET	v_insertId  = last_insert_id();   
              
			SET v_errCode 	= 0;
			SET v_errMsg	=  "Inserted Successfully";
        ELSE
			UPDATE prompt_library 
            SET fieldname 		= ifnull(p_fieldname,fieldname)
				,encoding 		= ifnull(p_encoding,encoding)
				,mimetype 		= ifnull(p_mimetype,mimetype)
				,filename 		= ifnull(p_filename,filename)
				,path 			= ifnull(p_path,path)
				,size 			= ifnull(p_size,size)
				,type 			= ifnull(p_type,type)
				,promptType 	= ifnull(p_promptType,promptType)
				,url 			= ifnull(p_url,url)
				,name 			= ifnull(p_name,name)
				,description 	= ifnull(p_description,description)
				,message 		= ifnull(p_message,message)
				,promptStatus 	= ifnull(p_promptStatus,promptStatus)
				,queueId 		= ifnull(p_queueId,queueId)
            WHERE  uuid = v_uuid;
            
				SET v_errCode 	= 0;
				SET v_errMsg	=  "Updated Successfully";
            
        End if;
			SELECT v_errCode as errCode, v_errMsg AS errMsg, v_insertId as Id;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
