CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_survey_feedback`(
	p_feedbackId		bigint
	,p_domainId			int
	,p_questionType		int
	,p_question_details	text
	,p_uuid				varchar(255)
	,p_status			int
	,p_version			varchar(45)
)
begin
     
	declare v_feedbackId int;
	declare v_errcode int default -1;
	declare v_errmsg varchar(50) default 'Failure';
    
    select feedbackId into v_feedbackId
	from survey_feedbacks
	where feedbackId = p_feedbackId;
	
    IF v_feedbackId IS NULL
	THEN 
		  INSERT INTO survey_feedbacks (domainId,questionType,question_details,createdAt,updatedAt,uuid,status,version) 
		  VALUES (p_domainId,p_questionType,p_question_details,NOW(),NOW(),p_uuid,p_status,p_version);
		  
          SET v_feedbackId = last_insert_id();
          
		  SELECT feedbackId, domainId, questionType, question_details, createdAt, updatedAt, uuid, status, version, isActive
          FROM survey_feedbacks WHERE feedbackId = v_feedbackId;
		
		SET v_errcode = 0;
		SET v_errmsg = 'Inserted';
	END IF;
           select v_errcode as errcode, v_errmsg as errmsg,v_feedbackId as feedbackId; 
   
end ;;
DELIMITER ;
