CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_task_reminder`(
	 p_domainId			INT
	,p_agentId			INT
	,p_reminderDate		DATE
	,p_reminderTime		TIME
	,p_timezone			VARCHAR(250)
	,p_notes			TEXT
    ,p_ext				INT 
)
BEGIN

    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg  VARCHAR(150) DEFAULT 'Insert / Update Failed';

sp_return:begin

	IF (IFNULL(p_agentId,'') = '' OR IFNULL(p_timezone,'') = '' OR IFNULL(p_domainId,'') = '')
    THEN
		SET v_errcode = -1;
        SET v_errmsg  = 'agentId / timezone / domainId should not be empty';
        leave sp_return;
	END IF;

		INSERT INTO tb_ccaas_ai_task_reminder(domainId,agentId,reminderDate,reminderTime,timezone,notes,ext,isSent,createdAt,updatedAt)
        VALUES(p_domainId,p_agentId,p_reminderDate,p_reminderTime,p_timezone,p_notes,p_ext,0,NOW(),NOW());

        SET v_errcode = 0;
        SET v_errmsg  = 'Inserted successfully';

end;
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
