CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_agent_status`(	
	p_aid					INT
	,p_statusName			varchar(100)
	,p_type					varchar(255)
	,p_description			varchar(250)
	,p_channels				varchar(100)
    ,p_status				int
    ,p_domainId				int
	,p_isDeleted			tinyint
	,p_isVoice				int
	,p_isVoiceCallTransfer	int
	,p_isChat				int
	,p_isChatTransfer		int
	,p_isEmail				int
	,p_isEmailTransfer		int
	,p_colorCode			varchar(50)

)
begin

	DECLARE v_aid INT;
	DECLARE v_errcode INT DEFAULT -1;
	DECLARE v_errmsg VARCHAR(100) DEFAULT 'Agent status insert / update fail';
	DECLARE v_agentStatusId INT;
    
	SELECT aid INTO v_aid
    FROM agent_status
    WHERE aid = p_aid
    AND domainId = p_domainId;
    
    IF v_aid IS NULL 
    THEN
		INSERT INTO agent_status (statusName,type,description,channels,status,domainId,createdAt,isVoice,isVoiceCallTransfer,isChat,isChatTransfer,isEmail,isEmailTransfer, colorCode,isDeleted) 
		VALUES (p_statusName,p_type,p_description,p_channels,p_status,p_domainId,now(),p_isVoice,p_isVoiceCallTransfer,p_isChat,p_isChatTransfer,p_isEmail,p_isEmailTransfer,p_colorCode,p_isDeleted);
		
        SET v_agentStatusId = last_insert_id();
        
		SET v_errcode = 0;
		SET v_errmsg = 'Agent status inserted successfully';
	ELSE 
		UPDATE agent_status
        SET 	statusName			= IFNULL(p_statusName	,	statusName	),
				type				= IFNULL(p_type	,	type	),
				description			= IFNULL(p_description	,	description	),
				channels			= IFNULL(p_channels	,	channels	),
				status				= IFNULL(p_status	,	status	),
				isDeleted			= IFNULL(p_isDeleted	,	isDeleted	),
				isVoice				= IFNULL(p_isVoice	,	isVoice	),
				isVoiceCallTransfer	= IFNULL(p_isVoiceCallTransfer	,	isVoiceCallTransfer	),
				isChat				= IFNULL(p_isChat	,	isChat	),
				isChatTransfer		= IFNULL(p_isChatTransfer	,	isChatTransfer	),
				isEmail				= IFNULL(p_isEmail	,	isEmail	),
				isEmailTransfer		= IFNULL(p_isEmailTransfer	,	isEmailTransfer	),
				colorCode			= IFNULL(p_colorCode	,	colorCode	),
				updatedAt			= NOW()
		WHERE aid = v_aid;
			
		SET v_errcode = 1;
		SET v_errmsg = 'Agent status updated successfully';
    END IF;
  SELECT v_errcode as errcode,v_errmsg as errmsg,IFNULL(v_agentStatusId,v_aid) as aid;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
