CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_ai_conservation_overview`(
p_sessionId varchar(50),
p_domainId int,
p_conversationInfo json
)
Begin
	declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'Not found';
    
    if not exists(select 1 from tb_ccaas_ai_conservation_overview where sessionId = p_sessionId and domainId = p_domainId limit 1 ) then
		insert into tb_ccaas_ai_conservation_overview (sessionId, domainId, conversationInfo)
        values(p_sessionId, p_domainId, p_conversationInfo);
        
        if row_Count()>0 then
			set v_errcode = 0;
            set v_errmsg = 'Ai conversation Inserted';
        End if;
        
    else
		update tb_ccaas_ai_conservation_overview 
        set conversationInfo = ifnull(p_conversationInfo, p_conversationInfo)
			,	updatedDate = current_timestamp()
        where sessionId = p_sessionId and domainId = p_domainId;
        
        if row_Count()>0 then
			set v_errcode = 0;
            set v_errmsg = 'Ai conversation Updated';
        End if;
    End if;
    
    select v_errcode as errcode, v_errmsg as errmsg;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
