CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_appointment_flow_tracking_info`(
   p_channelType varchar(20),
   p_historyId bigint,
   p_domainId int,
   p_companyNumber varchar(30),
   p_phoneNumber varchar(30),
   p_processflow varchar(100),
   p_companyId int,
   p_appId int,
   p_userId int,
   p_serviceId text,
   p_processDate varchar(10),
   p_processDuration varchar(10),
   p_processTime varchar(10),
   p_consultant varchar(100),
   p_categoryId	varchar(10)
   )
Begin
   	declare v_errcode int;
       declare v_errmsg varchar(50);
       declare v_id int;
       
       select id into v_id from ccaas_appointment_flow_tracking_dtl where channelType = p_channelType and historyId = p_historyId and domainId = p_domainId limit 1;
       
       if v_id is null then
   		insert into ccaas_appointment_flow_tracking_dtl(channelType, historyId, domainId, companyNumber, phoneNumber, processflow, createDate, companyId, appId, userId, serviceId,  processDate, processDuration, processTime,consultant,categoryId)
           values(p_channelType, p_historyId, p_domainId, p_companyNumber, p_phoneNumber, p_processflow, now(), p_companyId ,p_appId, p_userId, p_serviceId, p_processDate, p_processDuration, p_processTime,p_consultant,p_categoryId);
           
           if row_count() > 0 then
   			set v_errcode = 0;
               set v_errmsg = 'Inserted';
           End if;
           
   	else 
   		update ccaas_appointment_flow_tracking_dtl a 
   		set a.companyNumber = ifnull(p_companyNumber, a.companyNumber),
   			a.phoneNumber = ifnull(p_phoneNumber, a.phoneNumber),
             a.serviceId = ifnull(p_serviceId,a.serviceId),
               a.processflow = ifnull(p_processflow,a.processflow), 
               a.processDate = ifnull(p_processDate,a.processDate), 
               a.processDuration = ifnull(p_processDuration,a.processDuration),
               a.processTime = ifnull(p_processTime,a.processTime),
               a.consultant = ifnull(p_consultant,a.consultant),
               a.categoryId = ifnull(p_categoryId,a.categoryId),
               a.companyId = ifnull(p_companyId,a.companyId),
               a.appId = ifnull(p_appId,a.appId),
               a.userId = ifnull(p_userId,a.userId)
           where a.channelType = p_channelType and a.historyId = p_historyId and a.domainId = p_domainId;
           
           set v_errcode = 0;
   		set v_errmsg = 'Updated';
           
       End if;
       
   	select v_errcode as errcode, v_errmsg as errmsg;
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
