CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_businessHolidays`(
	 p_holidayId		INT
    ,p_domainId			INT 
    ,p_fkBusinessId		INT 
    ,p_holidayName		VARCHAR(1000)
    ,p_startDate		BIGINT 
    ,p_endDate			BIGINT 
    ,p_holidayDesc		TEXT
)
begin

	DECLARE v_errcode 	INT DEFAULT -1;
	DECLARE v_errmsg 	VARCHAR(60) DEFAULT 'Holiday Insert/Update Failed';
    DECLARE v_HolidayId INT;
    DECLARE v_curdate 	DATETIME;
    
    SET v_curdate = NOW();
    
    SELECT 	hid INTO v_HolidayId
    FROM 	tb_Business_Holidays
    WHERE 	hid = p_holidayId
    AND		fk_businessId = p_fkBusinessId
    AND 	domainId = p_domainId;
    
    IF v_HolidayId IS NULL 
    THEN 
		INSERT INTO tb_Business_Holidays(domainId,fk_businessId,holidayName,startDate,endDate,holidayDesc,createdAt,updatedAt)
        VALUES(p_domainId,p_fkBusinessId,p_holidayName,p_startDate,p_endDate,p_holidayDesc,v_curdate,v_curdate);
        
        SET v_errcode = 0;
        SET v_errmsg = 'Business holiday inserted successfully';
	ELSE 
		UPDATE tb_Business_Holidays
        SET holidayName		= IFNULL(p_holidayName,holidayName)
			,startDate		= IFNULL(p_startDate,startDate)
			,endDate		= IFNULL(p_endDate,endDate)
			,holidayDesc	= IFNULL(p_holidayDesc,holidayDesc)
			,updatedAt		= v_curdate
		WHERE hid = v_HolidayId;
        
        SET v_errcode = 1;
        SET v_errmsg = 'Business holiday updated successfully';
	END IF;
    
    SELECT v_errcode AS errcode,v_errmsg AS errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
