CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_callBlast`(	
		p_cid					int
		,p_campaignType    		tinyint 
		,p_domainId				int
		,p_blastName			varchar(500)
		,p_blastDescription 	text
		,p_triggerType 			smallint 
		,p_triggerDailyFile 	json
		,p_triggerCustomFile 	json
		,p_timeZone				varchar(500)
		,p_outboundNumber 		varchar(100)
		,p_callerId				varchar(50) 
		,p_campaignMessageType	smallint	
		,p_campaignMessage		json
		,p_textSpeechFile		text
		,p_promptMessage		json
		,p_createdBy			int
		,p_contactType			smallint 	
		,p_contact				json
		,p_importContact		json
		,p_importContactFile	json
		,p_addContact			json 
		,p_companyName			varchar(250)
		,p_connectingAudio		json 
		,p_agentUnavailable		json
		,p_agentReject			json
        ,p_maxDuration			int 
        ,p_sessionId			varchar(150)
 )
begin
 	
		DECLARE v_cid 							INT;
		DECLARE v_errcode 						INT DEFAULT -1;
		DECLARE v_errmsg 						VARCHAR(50) DEFAULT 'callBlast insert fail';
		DECLARE v_curDate 						DATETIME DEFAULT NOW();
		DECLARE v_JLength_json 					INT;
		DECLARE v_blastId 						INT;
		DECLARE v_triggerDailyFile 				INT;
		DECLARE v_tt_hours 						JSON;
		DECLARE v_currentDate 					DATE;
		DECLARE v_curTime 						TIME;
		DECLARE v_curTimeFormat 				VARCHAR(3);
		DECLARE v_JLength_importContact 		INT;
		DECLARE v_JLength_addContact 			INT;
		DECLARE v_totalExcelUploadedContact 	INT DEFAULT 0;
		DECLARE v_totalContactUploadedContact 	INT DEFAULT 0;
		DECLARE v_totalPhoneNoUploadedContact 	INT DEFAULT 0;
		DECLARE v_campDraftId					INT;
        
 		SET v_currentDate = CURDATE();
 		SET v_curTime = time_format(CURTIME(),'%h:%i');
 		SET v_curTimeFormat = time_format(CURTIME(),'%p');
         
          sp_return:BEGIN
      
 		IF(p_timeZone IS NULL OR p_timeZone = '')
         THEN
 			SET v_errcode = -1;
 			SET v_errmsg  = 'p_timeZone should not be null'; 
 			LEAVE sp_return;
 		END IF;
        
        IF(p_sessionId IS NULL OR p_sessionId = '')
         THEN
 			SET v_errcode = -1;
 			SET v_errmsg  = 'p_sessionId should not be null'; 
 			LEAVE sp_return;
 		END IF;
         
 		SELECT 	cid INTO v_cid
 		FROM 	tb_callBlast 
 		WHERE 	cid = p_cid;
 		
        IF p_cid IS NULL AND p_sessionId IS NOT NULL
		THEN
			SELECT 	campDraftId
			INTO 	v_campDraftId
			FROM 	tb_outbound_campaign_draft
			WHERE 	SessionId 	= p_sessionId
            AND 	domainId	= p_domainId;
        END IF;
        
         IF p_importContactFile IS NOT NULL 
         THEN
 			SET v_JLength_importContact = JSON_LENGTH(p_importContactFile,"$");
 			
 			DROP TEMPORARY TABLE IF EXISTS tt_importContactFile;
 			CREATE TEMPORARY TABLE tt_importContactFile
            (
				idnt			INT AUTO_INCREMENT PRIMARY KEY,
				j_FirstName  	VARCHAR(250),
				j_LastName  	VARCHAR(250),
				j_PhoneNumber  	VARCHAR(250),
                j_CustomerUniqueId	VARCHAR(150)
            );
            
            INSERT INTO tt_importContactFile(j_FirstName,j_LastName,j_PhoneNumber,j_CustomerUniqueId)
			SELECT * FROM JSON_TABLE(
			 p_importContactFile,
			 "$[*]" COLUMNS(
				  FirstName 			VARCHAR(250) PATH "$.FirstName",
				  LastName   			VARCHAR(250) PATH "$.LastName",
				  PhoneNumber   		VARCHAR(250) PATH "$.PhoneNumber",
				  CustomerUniqueId   	VARCHAR(150) PATH "$.CustomerUniqueId"
			 )) AS  AAA;
            
            select count(idnt) into v_totalExcelUploadedContact from tt_importContactFile; 
                        
			call ccaas_insertUpdateSyncCallBlastContacts(p_domainId);
         
         END IF;
         
         IF p_addContact IS NOT NULL
         THEN
 			
            
            SELECT JSON_LENGTH(p_addContact) INTO v_totalPhoneNoUploadedContact; 
            
            
		END IF;
        
         IF p_contact IS NOT NULL 
         THEN 
			
            SELECT JSON_LENGTH(p_contact) INTO v_totalContactUploadedContact; 

         END IF;
      
 		IF v_cid IS NULL
 		THEN
 			INSERT INTO tb_callBlast(campaignType,domainId,blastName,blastDescription,triggerType,triggerDailyFile,triggerCustomFile,timeZone,outboundNumber,callerId,campaignMessageType,campaignMessage,textSpeechFile,promptMessage,connectingAudio,agentUnavailable,agentReject,blastStatus,createdBy,contactType,companyName,maxDuration,fk_campDraftId,createdAt,updatedAt)
 			VALUES(p_campaignType,p_domainId,p_blastName,p_blastDescription,p_triggerType,p_triggerDailyFile,p_triggerCustomFile,p_timeZone,p_outboundNumber,p_callerId,p_campaignMessageType,p_campaignMessage,p_textSpeechFile,p_promptMessage,p_connectingAudio,p_agentUnavailable,p_agentReject,1,p_createdBy,p_contactType,p_companyName,p_maxDuration,v_campDraftId,v_curDate,v_curDate);
 			     
 			SET v_blastId = last_insert_id();
			
            INSERT INTO tb_callBlast_uploadContact(fk_cid,contact,importContact,importContactFile,addContact,totalUploadedContact,createdAt,updatedAt)
 			VALUES(v_blastId,p_contact,p_importContact,p_importContactFile,p_addContact,(v_totalPhoneNoUploadedContact + v_totalExcelUploadedContact + v_totalContactUploadedContact),v_curDate,v_curDate);
            
 			
 			if p_triggerType = 1
 			then
 				
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,dailyHour,createdAt)
 					select distinct v_blastId,v_currentDate,v_currentDate,concat('["',dayname(v_currentDate),'"]'),null,now();
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_blastId,v_triggerDailyFile,dayname(v_currentDate),v_curTime,v_curTimeFormat,v_curTime,v_curTimeFormat,now();
                     
                  
                 
 			  elseif p_triggerDailyFile is not null and p_triggerType = 2
 			  then
               
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
 				CREATE TEMPORARY TABLE tt_triggerDailyFile AS
                 SELECT JSON_EXTRACT(p_triggerDailyFile,"$.startDate") AS tt_startDate,
 					JSON_EXTRACT(p_triggerDailyFile,"$.endDate") AS tt_endDate,
                     JSON_EXTRACT(p_triggerDailyFile,"$.selectedDays") AS tt_selectedDays,
                     JSON_EXTRACT(p_triggerDailyFile,"$.frequency") AS tt_frequency,
                     JSON_EXTRACT(p_triggerDailyFile,"$.customHours") AS tt_hours;
                     
                     insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,frequency,dailyHour,createdAt)
 					select distinct v_blastId,tt_startDate
                     ,	CASE 
 						WHEN tt_endDate IS NULL OR tt_endDate = '' OR LOWER(tt_endDate) = 'null' 
 						THEN DATE_ADD(CURDATE(), INTERVAL 3 MONTH)
 						ELSE STR_TO_DATE(REPLACE(tt_endDate, '"', ''), '%Y-%m-%d')
 					END 
                     ,tt_selectedDays,tt_frequency,tt_hours,now()
 					from tt_triggerDailyFile;
  
 					SET  v_triggerDailyFile = last_insert_id();
 			
                     SELECT dailyHour INTO v_tt_hours FROM tb_callBlast_dailyTrigger_dtl WHERE tid = v_triggerDailyFile;
                                        
                     SET v_JLength_json = JSON_LENGTH(v_tt_hours, "$");
 					 
 					DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
 					CREATE TEMPORARY TABLE tt_triggerDailyFileJson AS
 					WITH RECURSIVE CTE_JsonCount AS (
 						SELECT 0 SlNo
 						UNION ALL
 						SELECT SlNo + 1 SlNo
 						FROM CTE_JsonCount
 						WHERE SlNo < v_JLength_json - 1
 					)
 					SELECT 
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].working_day')))) AS tt_working_day,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].startTime')))) AS tt_StartTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].StartTimeFormat')))) AS tt_StartTimeFormat,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].endTime')))) AS tt_EndTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].EndTimeFormat')))) AS tt_EndTimeFormat
 					FROM CTE_JsonCount;
                     
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_blastId,v_triggerDailyFile,tt_working_day,tt_StartTime,tt_StartTimeFormat,tt_EndTime,tt_EndTimeFormat,now()
 					from tt_triggerDailyFileJson;
                     
 					INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
 					SELECT v_blastId,STR_TO_DATE(CONCAT(TIME_FORMAT(tt_StartTime, '%h:%i'), ' ', tt_StartTimeFormat), '%h:%i %p')
 					, STR_TO_DATE(CONCAT(TIME_FORMAT(tt_EndTime, '%h:%i'), ' ', tt_EndTimeFormat), '%h:%i %p'), tt_working_day
 					FROM tt_triggerDailyFileJson;
 				                
 			   elseif p_triggerCustomFile is not null and p_triggerType = 3
 			   then
 			   
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
 				CREATE TEMPORARY TABLE tt_triggerCustomFile AS
                 SELECT JSON_EXTRACT(p_triggerCustomFile,"$.triggerDate") AS tt_triggerDate,
 						JSON_EXTRACT(p_triggerCustomFile,"$.triggerTime") AS tt_triggerTime,
 						JSON_UNQUOTE(JSON_EXTRACT(p_triggerCustomFile,"$.timeFormat")) AS tt_timeFormat;
 
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,dailyHour,createdAt)
 					select distinct v_blastId,tt_triggerDate,tt_triggerDate,concat('["',dayname(tt_triggerDate),'"]'),null,now()
 					from tt_triggerCustomFile;
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_blastId,v_triggerDailyFile,dayname(tt_triggerDate),tt_triggerTime,tt_timeFormat,tt_triggerTime,tt_timeFormat,now()
 					from tt_triggerCustomFile;
                     
                     INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                     SELECT v_blastId,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
 					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
 					working_day
 					from tb_callBlast_dailyTrigger_json_dtl where fk_cid = v_blastId;
                     
 			  end if;       
             
 			
             
             SET v_errcode = 0;
 			SET v_errmsg  = 'callBlast inserted successfully';
             
     ELSE 
 			UPDATE tb_callBlast 
             SET  campaignType		=IFNULL(p_campaignType,campaignType)
 				,blastName			=IFNULL(p_blastName,blastName)
 				,blastDescription	=IFNULL(p_blastDescription ,blastDescription)
 				,triggerType		=IFNULL(p_triggerType ,triggerType)
 				,triggerDailyFile	=IFNULL(p_triggerDailyFile ,triggerDailyFile)
 				,triggerCustomFile	=IFNULL(p_triggerCustomFile ,triggerCustomFile)
 				,timeZone			=IFNULL(p_timeZone,timeZone)
 				,outboundNumber		=IFNULL(p_outboundNumber ,outboundNumber)
 				,campaignMessageType=IFNULL(p_campaignMessageType,campaignMessageType)
 				,campaignMessage	=IFNULL(p_campaignMessage,campaignMessage)
 				,textSpeechFile		=IFNULL(p_textSpeechFile,textSpeechFile)
 				,promptMessage		=IFNULL(p_promptMessage,promptMessage)
 				,connectingAudio	=IFNULL(p_connectingAudio,connectingAudio)
 				,agentUnavailable	=IFNULL(p_agentUnavailable,agentUnavailable)
 				,agentReject		=IFNULL(p_agentReject,agentReject)
 				,createdBy			=IFNULL(p_createdBy,createdBy)
 				,callerId			=IFNULL(p_callerId,callerId)
 				,contactType		=IFNULL(p_contactType,contactType)
 				,companyName		=IFNULL(p_companyName,companyName)
 				,maxDuration		=IFNULL(p_maxDuration,maxDuration)
 				,updatedAt			=NOW()
 			WHERE cid = v_cid;
            
			UPDATE tb_callBlast_uploadContact	
			SET  contact			= p_contact
 				,importContact		= p_importContact
 				,importContactFile	= p_importContactFile
 				,addContact			= p_addContact
                ,updatedAt			=NOW()
			WHERE fk_cid = v_cid;
             
             DELETE FROM tb_callBlast_timeToTrigger_info 
 			WHERE fk_cid = v_cid;
             
             DELETE FROM tb_callBlast_dailyTrigger_json_dtl 
 			WHERE fk_cid = v_cid;
             
 			DELETE FROM tb_callBlast_dailyTrigger_dtl 
 			WHERE fk_cid = v_cid;
 
         if p_triggerType = 1
 			then
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,dailyHour,createdAt)
 					select distinct v_cid,v_currentDate,v_currentDate,concat('["',dayname(v_currentDate),'"]'),null,now();
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_cid,v_triggerDailyFile,dayname(v_currentDate),v_curTime,v_curTimeFormat,v_curTime,v_curTimeFormat,now();
                     
                     
                 
 			  elseif p_triggerDailyFile is not null and p_triggerType = 2
 			  then
               
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
 				CREATE TEMPORARY TABLE tt_triggerDailyFile AS
                 SELECT JSON_EXTRACT(p_triggerDailyFile,"$.startDate") AS tt_startDate,
 					JSON_EXTRACT(p_triggerDailyFile,"$.endDate") AS tt_endDate,
                     JSON_EXTRACT(p_triggerDailyFile,"$.selectedDays") AS tt_selectedDays,
                     JSON_EXTRACT(p_triggerDailyFile,"$.frequency") AS tt_frequency,
                     JSON_EXTRACT(p_triggerDailyFile,"$.customHours") AS tt_hours;
                                         
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,frequency,dailyHour,createdAt)
 					select distinct v_cid,tt_startDate
                    
 					,	CASE 
 						WHEN tt_endDate IS NULL OR tt_endDate = '' OR LOWER(tt_endDate) = 'null' 
 						THEN DATE_ADD(CURDATE(), INTERVAL 3 MONTH)
 						ELSE STR_TO_DATE(REPLACE(tt_endDate, '"', ''), '%Y-%m-%d')
 					END 
                     ,tt_selectedDays,tt_frequency,tt_hours,now()
 					from tt_triggerDailyFile;
 					                    
 					SET  v_triggerDailyFile = last_insert_id();
 			
                     SELECT dailyHour INTO v_tt_hours FROM tb_callBlast_dailyTrigger_dtl WHERE tid = v_triggerDailyFile;
                                        
                     SET v_JLength_json = JSON_LENGTH(v_tt_hours, "$");
 					 
 					DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
 					CREATE TEMPORARY TABLE tt_triggerDailyFileJson AS
 					WITH RECURSIVE CTE_JsonCount AS (
 						SELECT 0 SlNo
 						UNION ALL
 						SELECT SlNo + 1 SlNo
 						FROM CTE_JsonCount
 						WHERE SlNo < v_JLength_json - 1
 					)
 					SELECT 
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].working_day')))) AS tt_working_day,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].startTime')))) AS tt_StartTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].StartTimeFormat')))) AS tt_StartTimeFormat,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].endTime')))) AS tt_EndTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].EndTimeFormat')))) AS tt_EndTimeFormat
 					FROM CTE_JsonCount;
                     
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_cid,v_triggerDailyFile,tt_working_day,tt_StartTime,tt_StartTimeFormat,tt_EndTime,tt_EndTimeFormat,now()
 					from tt_triggerDailyFileJson;
                     
 					INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
 					SELECT v_cid,STR_TO_DATE(CONCAT(TIME_FORMAT(tt_StartTime, '%h:%i'), ' ', tt_StartTimeFormat), '%h:%i %p')
 					, STR_TO_DATE(CONCAT(TIME_FORMAT(tt_EndTime, '%h:%i'), ' ', tt_EndTimeFormat), '%h:%i %p'), tt_working_day
 					FROM tt_triggerDailyFileJson;
                 
 			   elseif p_triggerCustomFile is not null and p_triggerType = 3
 			   then
 			   
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
 				CREATE TEMPORARY TABLE tt_triggerCustomFile AS
                 SELECT JSON_EXTRACT(p_triggerCustomFile,"$.triggerDate") AS tt_triggerDate,
 						JSON_EXTRACT(p_triggerCustomFile,"$.triggerTime") AS tt_triggerTime,
 						JSON_UNQUOTE(JSON_EXTRACT(p_triggerCustomFile,"$.timeFormat")) AS tt_timeFormat;
 
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
 					select distinct v_cid,tt_triggerDate,tt_triggerDate,concat('["',dayname(tt_triggerDate),'"]'),1,1,null,now()
 					from tt_triggerCustomFile;
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_cid,v_triggerDailyFile,dayname(tt_triggerDate),tt_triggerTime,tt_timeFormat,tt_triggerTime,tt_timeFormat,now()
 					from tt_triggerCustomFile;
                     
                     INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                     SELECT v_cid,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
 					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
 					working_day
 					from tb_callBlast_dailyTrigger_json_dtl where fk_cid = v_cid;
                     
 			  end if;
               
 					SET v_errcode = 1;
 					SET v_errmsg  = 'callBlast updated successfully';
         
 	END IF;
  END;        
     SELECT v_errcode as errcode,v_errmsg as errmsg,IFNULL(v_blastId,p_cid) as blastId;
     
		DROP TEMPORARY TABLE IF EXISTS tt_importContactFile;
		DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
		DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
		DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
 	
 end ;;
