CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_callBlast_test`(	
		p_cid					int
		,p_campaignType    		tinyint 
		,p_domainId				int
		,p_blastName			varchar(500)
		,p_blastDescription 	text
		,p_triggerType 			smallint 
		,p_triggerDailyFile 	json
		,p_triggerCustomFile 	json
		,p_timeZone				varchar(500)
		,p_outboundNumber 		varchar(100)
		,p_callerId				varchar(50) 
		,p_campaignMessageType	smallint	
		,p_campaignMessage		json
		,p_textSpeechFile		text
		,p_promptMessage		json
		,p_createdBy			int
		,p_contactType			smallint 	
		,p_contact				json
		,p_importContact		json
		,p_importContactFile	json
		,p_addContact			json 
		,p_companyName			varchar(250)
		,p_connectingAudio		json 
		,p_agentUnavailable		json
		,p_agentReject			json
        ,p_maxDuration			int 
 )
begin
 	
 		DECLARE v_cid 							INT;
 		DECLARE v_errcode 						INT DEFAULT -1;
 		DECLARE v_errmsg 						VARCHAR(50) DEFAULT 'callBlast insert fail';
 		DECLARE v_curDate 						DATETIME DEFAULT NOW();
 		DECLARE v_JLength_json 					INT;
 		DECLARE v_blastId 						INT;
 		DECLARE v_triggerDailyFile 				INT;
 		DECLARE v_tt_hours 						JSON;
 		DECLARE v_currentDate 					DATE;
 		DECLARE v_curTime 						TIME;
 		DECLARE v_curTimeFormat 				VARCHAR(3);
         DECLARE v_JLength_importContact 		INT;
         DECLARE v_JLength_addContact 			INT;
         DECLARE v_totalExcelUploadedContact 	INT DEFAULT 0;
         DECLARE v_totalContactUploadedContact 	INT DEFAULT 0;
         DECLARE v_totalPhoneNoUploadedContact 	INT DEFAULT 0;
 
 		SET v_currentDate = CURDATE();
 		SET v_curTime = time_format(CURTIME(),'%h:%i');
 		SET v_curTimeFormat = time_format(CURTIME(),'%p');
         
          sp_return:BEGIN
      
 		IF(p_timeZone IS NULL OR p_timeZone = '')
         THEN
 			SET v_errcode = -1;
 			SET v_errmsg  = 'p_timeZone should not be null'; 
 			LEAVE sp_return;
 		END IF;
         
 		SELECT 	cid INTO v_cid
 		FROM 	tb_callBlast 
 		WHERE 	cid = p_cid;
 		
         IF p_importContactFile IS NOT NULL 
         THEN
 			SET v_JLength_importContact = JSON_LENGTH(p_importContactFile,"$");
 			
 			DROP TEMPORARY TABLE IF EXISTS tt_importContactFile;
 			CREATE TEMPORARY TABLE tt_importContactFile
            (
				idnt			INT AUTO_INCREMENT PRIMARY KEY,
				j_FirstName  	VARCHAR(250),
				j_LastName  	VARCHAR(250),
				j_PhoneNumber  	VARCHAR(250) 
            );
            
			ALTER TABLE tt_importContactFile ADD INDEX idx_phone (j_PhoneNumber);
            
            INSERT INTO tt_importContactFile(j_FirstName,j_LastName,j_PhoneNumber)
			SELECT * FROM JSON_TABLE(
			 p_importContactFile,
			 "$[*]" COLUMNS(
				  FirstName 	VARCHAR(250) PATH "$.FirstName",
				  LastName   	VARCHAR(250) PATH "$.LastName",
				  PhoneNumber   VARCHAR(250) PATH "$.PhoneNumber"
			 )) AS  AAA;
            
            select count(idnt) into v_totalExcelUploadedContact from tt_importContactFile; 
                        
			call ccaas_insertUpdateSyncCallBlastContacts(p_domainId);
         
			DROP TEMPORARY TABLE IF EXISTS tt_customerContact_DND_Numbers;
			CREATE TEMPORARY TABLE tt_customerContact_DND_Numbers AS
			SELECT cc.primaryPhoneNumber, cc.doNotDisturb
			FROM customer_contact cc
			JOIN tt_importContactFile imp ON cc.primaryPhoneNumber COLLATE utf8mb4_0900_ai_ci = imp.j_PhoneNumber AND cc.domainId = p_domainId
			WHERE cc.domainId = p_domainId;
 
		END IF;
         
         IF p_addContact IS NOT NULL
         THEN
 			
            
            SELECT JSON_LENGTH(p_addContact) INTO v_totalPhoneNoUploadedContact; 
            
            
		END IF;
        
         IF p_contact IS NOT NULL 
         THEN 
			
            SELECT JSON_LENGTH(p_contact) INTO v_totalContactUploadedContact; 

         END IF;
      
 		IF v_cid IS NULL
 		THEN
 			INSERT INTO tb_callBlast(campaignType,domainId,blastName,blastDescription,triggerType,triggerDailyFile,triggerCustomFile,timeZone,outboundNumber,callerId,campaignMessageType,campaignMessage,textSpeechFile,promptMessage,connectingAudio,agentUnavailable,agentReject,blastStatus,createdBy,contactType,companyName,maxDuration,createdAt,updatedAt)
 			VALUES(p_campaignType,p_domainId,p_blastName,p_blastDescription,p_triggerType,p_triggerDailyFile,p_triggerCustomFile,p_timeZone,p_outboundNumber,p_callerId,p_campaignMessageType,p_campaignMessage,p_textSpeechFile,p_promptMessage,p_connectingAudio,p_agentUnavailable,p_agentReject,1,p_createdBy,p_contactType,p_companyName,p_maxDuration,v_curDate,v_curDate);
 			     
 			SET v_blastId = last_insert_id();
			
            INSERT INTO tb_callBlast_uploadContact(fk_cid,contact,importContact,importContactFile,addContact,totalUploadedContact,createdAt,updatedAt)
 			VALUES(v_blastId,p_contact,p_importContact,p_importContactFile,p_addContact,(v_totalPhoneNoUploadedContact + v_totalExcelUploadedContact + v_totalContactUploadedContact),v_curDate,v_curDate);
            
 			
 			if p_triggerType = 1
 			then
 				
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,dailyHour,createdAt)
 					select distinct v_blastId,v_currentDate,v_currentDate,concat('["',dayname(v_currentDate),'"]'),null,now();
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_blastId,v_triggerDailyFile,dayname(v_currentDate),v_curTime,v_curTimeFormat,v_curTime,v_curTimeFormat,now();
                     
                  
                 
 			  elseif p_triggerDailyFile is not null and p_triggerType = 2
 			  then
               
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
 				CREATE TEMPORARY TABLE tt_triggerDailyFile AS
                 SELECT JSON_EXTRACT(p_triggerDailyFile,"$.startDate") AS tt_startDate,
 					JSON_EXTRACT(p_triggerDailyFile,"$.endDate") AS tt_endDate,
                     JSON_EXTRACT(p_triggerDailyFile,"$.selectedDays") AS tt_selectedDays,
                     JSON_EXTRACT(p_triggerDailyFile,"$.frequency") AS tt_frequency,
                     JSON_EXTRACT(p_triggerDailyFile,"$.customHours") AS tt_hours;
                     
                     insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,frequency,dailyHour,createdAt)
 					select distinct v_blastId,tt_startDate
                     ,	CASE 
 						WHEN tt_endDate IS NULL OR tt_endDate = '' OR LOWER(tt_endDate) = 'null' 
 						THEN DATE_ADD(CURDATE(), INTERVAL 3 MONTH)
 						ELSE STR_TO_DATE(REPLACE(tt_endDate, '"', ''), '%Y-%m-%d')
 					END 
                     ,tt_selectedDays,tt_frequency,tt_hours,now()
 					from tt_triggerDailyFile;
  
 					SET  v_triggerDailyFile = last_insert_id();
 			
                     SELECT dailyHour INTO v_tt_hours FROM tb_callBlast_dailyTrigger_dtl WHERE tid = v_triggerDailyFile;
                                        
                     SET v_JLength_json = JSON_LENGTH(v_tt_hours, "$");
 					 
 					DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
 					CREATE TEMPORARY TABLE tt_triggerDailyFileJson AS
 					WITH RECURSIVE CTE_JsonCount AS (
 						SELECT 0 SlNo
 						UNION ALL
 						SELECT SlNo + 1 SlNo
 						FROM CTE_JsonCount
 						WHERE SlNo < v_JLength_json - 1
 					)
 					SELECT 
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].working_day')))) AS tt_working_day,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].startTime')))) AS tt_StartTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].StartTimeFormat')))) AS tt_StartTimeFormat,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].endTime')))) AS tt_EndTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].EndTimeFormat')))) AS tt_EndTimeFormat
 					FROM CTE_JsonCount;
                     
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_blastId,v_triggerDailyFile,tt_working_day,tt_StartTime,tt_StartTimeFormat,tt_EndTime,tt_EndTimeFormat,now()
 					from tt_triggerDailyFileJson;
                     
 					INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
 					SELECT v_blastId,STR_TO_DATE(CONCAT(TIME_FORMAT(tt_StartTime, '%h:%i'), ' ', tt_StartTimeFormat), '%h:%i %p')
 					, STR_TO_DATE(CONCAT(TIME_FORMAT(tt_EndTime, '%h:%i'), ' ', tt_EndTimeFormat), '%h:%i %p'), tt_working_day
 					FROM tt_triggerDailyFileJson;
 				                
 			   elseif p_triggerCustomFile is not null and p_triggerType = 3
 			   then
 			   
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
 				CREATE TEMPORARY TABLE tt_triggerCustomFile AS
                 SELECT JSON_EXTRACT(p_triggerCustomFile,"$.triggerDate") AS tt_triggerDate,
 						JSON_EXTRACT(p_triggerCustomFile,"$.triggerTime") AS tt_triggerTime,
 						JSON_UNQUOTE(JSON_EXTRACT(p_triggerCustomFile,"$.timeFormat")) AS tt_timeFormat;
 
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,dailyHour,createdAt)
 					select distinct v_blastId,tt_triggerDate,tt_triggerDate,concat('["',dayname(tt_triggerDate),'"]'),null,now()
 					from tt_triggerCustomFile;
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_blastId,v_triggerDailyFile,dayname(tt_triggerDate),tt_triggerTime,tt_timeFormat,tt_triggerTime,tt_timeFormat,now()
 					from tt_triggerCustomFile;
                     
                     INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                     SELECT v_blastId,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
 					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
 					working_day
 					from tb_callBlast_dailyTrigger_json_dtl where fk_cid = v_blastId;
                     
 			  end if;       
             
 			
             
             SET v_errcode = 0;
 			SET v_errmsg  = 'callBlast inserted successfully';
             
     ELSE 
 			UPDATE tb_callBlast 
             SET  campaignType		=IFNULL(p_campaignType,campaignType)
 				,blastName			=IFNULL(p_blastName,blastName)
 				,blastDescription	=IFNULL(p_blastDescription ,blastDescription)
 				,triggerType		=IFNULL(p_triggerType ,triggerType)
 				,triggerDailyFile	=IFNULL(p_triggerDailyFile ,triggerDailyFile)
 				,triggerCustomFile	=IFNULL(p_triggerCustomFile ,triggerCustomFile)
 				,timeZone			=IFNULL(p_timeZone,timeZone)
 				,outboundNumber		=IFNULL(p_outboundNumber ,outboundNumber)
 				,campaignMessageType=IFNULL(p_campaignMessageType,campaignMessageType)
 				,campaignMessage	=IFNULL(p_campaignMessage,campaignMessage)
 				,textSpeechFile		=IFNULL(p_textSpeechFile,textSpeechFile)
 				,promptMessage		=IFNULL(p_promptMessage,promptMessage)
 				,connectingAudio	=IFNULL(p_connectingAudio,connectingAudio)
 				,agentUnavailable	=IFNULL(p_agentUnavailable,agentUnavailable)
 				,agentReject		=IFNULL(p_agentReject,agentReject)
 				,createdBy			=IFNULL(p_createdBy,createdBy)
 				,callerId			=IFNULL(p_callerId,callerId)
 				,contactType		=IFNULL(p_contactType,contactType)
 				,companyName		=IFNULL(p_companyName,companyName)
 				,maxDuration		=IFNULL(p_maxDuration,maxDuration)
 				,updatedAt			=NOW()
 			WHERE cid = v_cid;
            
			UPDATE tb_callBlast_uploadContact	
			SET  contact			= p_contact
 				,importContact		= p_importContact
 				,importContactFile	= p_importContactFile
 				,addContact			= p_addContact
                ,updatedAt			=NOW()
			WHERE fk_cid = v_cid;
             
             DELETE FROM tb_callBlast_timeToTrigger_info 
 			WHERE fk_cid = v_cid;
             
             DELETE FROM tb_callBlast_dailyTrigger_json_dtl 
 			WHERE fk_cid = v_cid;
             
 			DELETE FROM tb_callBlast_dailyTrigger_dtl 
 			WHERE fk_cid = v_cid;
 
         if p_triggerType = 1
 			then
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,dailyHour,createdAt)
 					select distinct v_cid,v_currentDate,v_currentDate,concat('["',dayname(v_currentDate),'"]'),null,now();
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_cid,v_triggerDailyFile,dayname(v_currentDate),v_curTime,v_curTimeFormat,v_curTime,v_curTimeFormat,now();
                     
                     
                 
 			  elseif p_triggerDailyFile is not null and p_triggerType = 2
 			  then
               
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
 				CREATE TEMPORARY TABLE tt_triggerDailyFile AS
                 SELECT JSON_EXTRACT(p_triggerDailyFile,"$.startDate") AS tt_startDate,
 					JSON_EXTRACT(p_triggerDailyFile,"$.endDate") AS tt_endDate,
                     JSON_EXTRACT(p_triggerDailyFile,"$.selectedDays") AS tt_selectedDays,
                     JSON_EXTRACT(p_triggerDailyFile,"$.frequency") AS tt_frequency,
                     JSON_EXTRACT(p_triggerDailyFile,"$.customHours") AS tt_hours;
                                         
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,frequency,dailyHour,createdAt)
 					select distinct v_cid,tt_startDate
                    
 					,	CASE 
 						WHEN tt_endDate IS NULL OR tt_endDate = '' OR LOWER(tt_endDate) = 'null' 
 						THEN DATE_ADD(CURDATE(), INTERVAL 3 MONTH)
 						ELSE STR_TO_DATE(REPLACE(tt_endDate, '"', ''), '%Y-%m-%d')
 					END 
                     ,tt_selectedDays,tt_frequency,tt_hours,now()
 					from tt_triggerDailyFile;
 					                    
 					SET  v_triggerDailyFile = last_insert_id();
 			
                     SELECT dailyHour INTO v_tt_hours FROM tb_callBlast_dailyTrigger_dtl WHERE tid = v_triggerDailyFile;
                                        
                     SET v_JLength_json = JSON_LENGTH(v_tt_hours, "$");
 					 
 					DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
 					CREATE TEMPORARY TABLE tt_triggerDailyFileJson AS
 					WITH RECURSIVE CTE_JsonCount AS (
 						SELECT 0 SlNo
 						UNION ALL
 						SELECT SlNo + 1 SlNo
 						FROM CTE_JsonCount
 						WHERE SlNo < v_JLength_json - 1
 					)
 					SELECT 
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].working_day')))) AS tt_working_day,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].startTime')))) AS tt_StartTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].StartTimeFormat')))) AS tt_StartTimeFormat,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].endTime')))) AS tt_EndTime,
 						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].EndTimeFormat')))) AS tt_EndTimeFormat
 					FROM CTE_JsonCount;
                     
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_cid,v_triggerDailyFile,tt_working_day,tt_StartTime,tt_StartTimeFormat,tt_EndTime,tt_EndTimeFormat,now()
 					from tt_triggerDailyFileJson;
                     
 					INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
 					SELECT v_cid,STR_TO_DATE(CONCAT(TIME_FORMAT(tt_StartTime, '%h:%i'), ' ', tt_StartTimeFormat), '%h:%i %p')
 					, STR_TO_DATE(CONCAT(TIME_FORMAT(tt_EndTime, '%h:%i'), ' ', tt_EndTimeFormat), '%h:%i %p'), tt_working_day
 					FROM tt_triggerDailyFileJson;
                 
 			   elseif p_triggerCustomFile is not null and p_triggerType = 3
 			   then
 			   
 				DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
 				CREATE TEMPORARY TABLE tt_triggerCustomFile AS
                 SELECT JSON_EXTRACT(p_triggerCustomFile,"$.triggerDate") AS tt_triggerDate,
 						JSON_EXTRACT(p_triggerCustomFile,"$.triggerTime") AS tt_triggerTime,
 						JSON_UNQUOTE(JSON_EXTRACT(p_triggerCustomFile,"$.timeFormat")) AS tt_timeFormat;
 
 					insert into tb_callBlast_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
 					select distinct v_cid,tt_triggerDate,tt_triggerDate,concat('["',dayname(tt_triggerDate),'"]'),1,1,null,now()
 					from tt_triggerCustomFile;
 					
                     SET  v_triggerDailyFile = last_insert_id();
 					                    
 					insert into tb_callBlast_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
 					select v_cid,v_triggerDailyFile,dayname(tt_triggerDate),tt_triggerTime,tt_timeFormat,tt_triggerTime,tt_timeFormat,now()
 					from tt_triggerCustomFile;
                     
                     INSERT INTO tb_callBlast_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                     SELECT v_cid,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
 					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
 					working_day
 					from tb_callBlast_dailyTrigger_json_dtl where fk_cid = v_cid;
                     
 			  end if;
               
 					SET v_errcode = 1;
 					SET v_errmsg  = 'callBlast updated successfully';
         
 	END IF;
  END;        
     SELECT v_errcode as errcode,v_errmsg as errmsg,IFNULL(v_blastId,p_cid) as blastId;
     
     SELECT primaryPhoneNumber,IFNULL(doNotDisturb,0) FROM tt_customerContact_DND_Numbers;

		DROP TEMPORARY TABLE IF EXISTS tt_importContactFile;
		DROP TEMPORARY TABLE IF EXISTS tt_customerContact_DND_Numbers;
		DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
		DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
		DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
 	
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_insert_update_callBlast_triggered_call_history_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_callBlast_triggered_call_history_dtl`(
	p_blastId 			int,
	p_triggeredId 		int,
	p_customerContact 	json
)
begin

		DECLARE v_tcid INT;
		DECLARE v_curdate DATETIME;
		DECLARE v_errcode INT DEFAULT -1;
		DECLARE v_errmsg VARCHAR(100) DEFAULT 'Callblast History insert/updated fail';
		DECLARE v_max_id INT;
		DECLARE v_domainId INT;
		
		SET v_curdate = NOW();
		
		SELECT 	tcid INTO v_tcid 
		FROM 	tb_callBlast_triggered_customer_call_dtl
		WHERE 	fk_cid = p_blastId
		AND		fk_triggeredId = p_triggeredId;
        
        SELECT domainId INTO v_domainId
        FROM 	tb_callBlast WHERE cid = p_blastId;
    
		DROP TEMPORARY TABLE IF EXISTS tt_extractCustomerContact;
		CREATE TEMPORARY TABLE tt_extractCustomerContact
		(
			tt_agentExtn  			INT,
			tt_agentName  			VARCHAR(250),
            tt_sessionId			VARCHAR(500),
			tt_duration  			INT,
			tt_callStatus  			VARCHAR(250),
			tt_startTime  			BIGINT,
			tt_phoneNumber  		VARCHAR(250),
			tt_customerType  		VARCHAR(250),
			tt_customerFirstName	VARCHAR(250),
			tt_customerLastName		VARCHAR(250)
		);
   
sp_return: begin   
   
    IF p_triggeredId =0 
    THEN
			select IFNULL(max(fk_triggeredId)+1,1) into p_triggeredId from tb_callBlast_triggered_customer_call_dtl where fk_cid = p_blastId limit 1;
    
			INSERT INTO tb_callBlast_triggered_customer_call_dtl(fk_cid,fk_triggeredId,customerContact,createdAt,updatedAt)
			VALUES(p_blastId,p_triggeredId,p_customerContact,v_curdate,v_curdate);
				
				INSERT INTO tt_extractCustomerContact(tt_agentExtn,tt_agentName,tt_sessionId,tt_duration,tt_callStatus,tt_startTime,tt_phoneNumber,tt_customerType,tt_customerFirstName,tt_customerLastName)
				SELECT * FROM JSON_TABLE(
				 p_customerContact,
				 "$[*]" COLUMNS(
					  agentExtn 	INT PATH "$.agentExtn",
					  agentName   	VARCHAR(250) PATH "$.agentName",
					  sessionId   	VARCHAR(250) PATH "$.sessionId",
					  duration   	INT PATH "$.duration",
					  callStatus   	VARCHAR(250) PATH "$.callStatus",
					  startTime   	BIGINT PATH "$.startTime",
					  phoneNumber   VARCHAR(250) PATH "$.phoneNumber",
					  customerType  VARCHAR(250) PATH "$.customerType",
					  firstName		VARCHAR(250) PATH "$.firstName",
					  lastName		VARCHAR(250) PATH "$.lastName"
				 )) AS  AAA;
			
			SET v_errcode = 0;
			SET v_errmsg = 'Callblast History inserted successfully';
        
			INSERT INTO tb_callBlast_triggered_customer_call_json_dtl (domainId, sessionId ,blastId,fk_triggeredId,agentExtn,agentName,duration,callStatus,startTime,phoneNumber,customerType,customerFirstName,customerLastName,createdAt)
			SELECT v_domainId, tt_sessionId, p_blastId, p_triggeredId, tt_agentExtn,tt_agentName,tt_duration,tt_callStatus,tt_startTime,tt_phoneNumber,tt_customerType,tt_customerFirstName,tt_customerLastName,now()
			FROM tt_extractCustomerContact; 
		LEAVE sp_return;
    END IF;
        
	IF v_tcid IS NULL
    THEN
		INSERT INTO tb_callBlast_triggered_customer_call_dtl(fk_cid,fk_triggeredId,customerContact,createdAt,updatedAt)
		VALUES(p_blastId,p_triggeredId,concat("[",p_customerContact,"]"),v_curdate,v_curdate);
        
			INSERT INTO tt_extractCustomerContact(tt_agentExtn,tt_agentName,tt_sessionId,tt_duration,tt_callStatus,tt_startTime,tt_phoneNumber,tt_customerType,tt_customerFirstName,tt_customerLastName)
			SELECT * FROM JSON_TABLE(
			 concat("[",p_customerContact,"]"),
			 "$[*]" COLUMNS(
				  agentExtn 	INT PATH "$.agentExtn",
				  agentName   	VARCHAR(250) PATH "$.agentName",
                  sessionId   	VARCHAR(250) PATH "$.sessionId",
				  duration   	INT PATH "$.duration",
				  callStatus   	VARCHAR(250) PATH "$.callStatus",
				  startTime   	BIGINT PATH "$.startTime",
				  phoneNumber   VARCHAR(250) PATH "$.phoneNumber",
				  customerType  VARCHAR(250) PATH "$.customerType",
                  firstName		VARCHAR(250) PATH "$.firstName",
				  lastName		VARCHAR(250) PATH "$.lastName"
			)) AS  AAA;
        
        SET v_errcode = 0;
        SET v_errmsg = 'Callblast History inserted successfully';
	ELSE 
			UPDATE tb_callBlast_triggered_customer_call_dtl
			SET customerContact = JSON_ARRAY_APPEND(customerContact, '$', p_customerContact)
			WHERE tcid = v_tcid ;
            
            INSERT INTO tt_extractCustomerContact(tt_agentExtn,tt_agentName,tt_sessionId,tt_duration,tt_callStatus,tt_startTime,tt_phoneNumber,tt_customerType,tt_customerFirstName,tt_customerLastName)
			SELECT * FROM JSON_TABLE(
			 concat("[",p_customerContact,"]"),
			 "$[*]" COLUMNS(
				  agentExtn 	INT PATH "$.agentExtn",
				  agentName   	VARCHAR(250) PATH "$.agentName",
                  sessionId   	VARCHAR(250) PATH "$.sessionId",
				  duration   	INT PATH "$.duration",
				  callStatus   	VARCHAR(250) PATH "$.callStatus",
				  startTime   	BIGINT PATH "$.startTime",
				  phoneNumber   VARCHAR(250) PATH "$.phoneNumber",
				  customerType  VARCHAR(250) PATH "$.customerType",
                  firstName		VARCHAR(250) PATH "$.firstName",
				  lastName		VARCHAR(250) PATH "$.lastName"
			 )) AS  AAA;
        
        SET v_errcode = 1;
        SET v_errmsg = 'Callblast History updated successfully';
	END IF;
		INSERT INTO tb_callBlast_triggered_customer_call_json_dtl (domainId,sessionId,blastId,fk_triggeredId,agentExtn,agentName,duration,callStatus,startTime,phoneNumber,customerType,customerFirstName,customerLastName,createdAt)
		SELECT v_domainId, tt_sessionId, p_blastId, p_triggeredId, tt_agentExtn,tt_agentName,tt_duration,tt_callStatus,tt_startTime,tt_phoneNumber,tt_customerType,tt_customerFirstName,tt_customerLastName,now()
		FROM tt_extractCustomerContact; 
END; 
		SELECT v_errcode as errcode,v_errmsg as errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_insert_update_conversation_triggers` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insert_update_conversation_triggers`(
p_triggerid int,
p_domainId int,
p_triggerName varchar(150),
p_description varchar(250),
p_keywords text
)
Begin
	declare v_errcode int;
    declare v_errmsg varchar(50);
    declare v_triggId int;
    
    select id into v_triggId from ccaas_conversation_triggers where id = p_triggerid;
    
    if v_triggId is null then
		insert into ccaas_conversation_triggers (domainId, triggerName, description, keywords, createAt)
        values(p_domainId, p_triggerName, p_description, p_keywords, now());
        
        set v_triggId = last_insert_id();
        
        if row_count() > 0 then
			set v_errcode = 0;
            set v_errmsg = 'Inserted';
        End if;
    Else
		update ccaas_conversation_triggers
			set triggerName = ifnull(p_triggerName, triggerName),
				description = ifnull(p_description, description),
				keywords = ifnull(p_keywords, keywords),
				updatedAt = now()
        where id = p_triggerid;
        
         if row_count() > 0 then
			set v_errcode = 0;
            set v_errmsg = 'Updated';
        End if;
        
    End if;

    select v_errcode as errcode , v_errmsg as errmsg, ifnull(v_triggId,p_triggerid) as triggerid;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_insert_update_createBusinessHours` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_createBusinessHours`(
	 p_cid				INT
	,p_name				VARCHAR(255)
	,p_description		VARCHAR(255)
	,p_hours			LONGTEXT
	,p_domainId			INT
	,p_timeZone			VARCHAR(100)
	,p_default_hours	VARCHAR(100)
	,p_timeZoneValue	VARCHAR(40)
	,p_type				VARCHAR(50)
    ,p_holiday			JSON
)
begin
	
    DECLARE v_cid INT;
    DECLARE v_curdate DATETIME;
    DECLARE v_errcode TINYINT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(150) DEFAULT 'Create Business Hours Failed';
    DECLARE v_lastId INT;
    
    SET v_curdate = NOW();
    
	IF p_timeZone = 'Asia/Kolkata (GMT+05:30)' THEN 
		SET p_timeZone = 'Asia/Kolkata (IST) GMT +05:30'; 
	END IF;
	
    SELECT cid INTO v_cid
    FROM custom_hours
    WHERE cid 		= p_cid
    AND domainId	= p_domainId;
    
		DROP TEMPORARY TABLE IF EXISTS tt_business_hours;	
		CREATE TEMPORARY TABLE tt_business_hours
		(
			tt_id				INT AUTO_INCREMENT PRIMARY KEY,
			tt_day  			VARCHAR(250),
			tt_isHoliday  		VARCHAR(250),
			tt_startTimeStamp  	BIGINT, 
			tt_endTimeStamp  	BIGINT, 
			tt_startTime  		TIME, 
			tt_endTime  		TIME 
		);

		INSERT INTO tt_business_hours(tt_day,tt_isHoliday,tt_startTimeStamp,tt_endTimeStamp,tt_startTime,tt_endTime)
		SELECT * FROM JSON_TABLE(
		p_hours,
		"$[*]"
		COLUMNS (
			day             VARCHAR(50) PATH "$.day",
			isHoliday       BOOLEAN     PATH "$.isHoliday",
			startTimeStamp  BIGINT      PATH "$.entry[0].startTimeStamp",
			endTimeStamp    BIGINT      PATH "$.entry[0].endTimeStamp",
			startTime       VARCHAR(10) PATH "$.entry[0].startTime",
			endTime         VARCHAR(10) PATH "$.entry[0].endTime"
		)
		) AS work_hours;	
        
		DROP TEMPORARY TABLE IF EXISTS tt_business_holiday;		
		CREATE TEMPORARY TABLE tt_business_holiday
		(
			tt_id				INT AUTO_INCREMENT PRIMARY KEY,
			tt_holidayName  	VARCHAR(1000),
			tt_startDate  		BIGINT,
			tt_endDate  		BIGINT, 
			tt_isStatus  		TINYINT, 
			tt_holidayDesc  	TEXT,
            tt_holidayPrompt	VARCHAR(5000),
            tt_holidayMessage	TEXT
		);

		INSERT INTO tt_business_holiday(tt_holidayName,tt_startDate,tt_endDate,tt_isStatus,tt_holidayDesc,tt_holidayPrompt,tt_holidayMessage)
		SELECT * FROM JSON_TABLE(
			p_holiday,
			"$[*]"
			COLUMNS (
				holidayName     VARCHAR(1000) 	PATH "$.holidayName",
				startDate       BIGINT     		PATH "$.startDate",
				endDate  		BIGINT      	PATH "$.endDate",
				isStatus    	TINYINT      	PATH "$.isStatus",
				holidayDesc     TEXT 			PATH "$.holidayDesc",
				holidayPrompt   TEXT 			PATH "$.holidayPrompt",
				holidayMessage  TEXT 			PATH "$.holidayMessage"
			)
		) AS work_hours;
    
    IF v_cid IS NULL
    THEN
		INSERT INTO custom_hours (name,description,timeZone,hours,domainId,default_hours,timeZoneValue,type,createdAt,updatedAt)
		VALUES (p_name,p_description,p_timeZone,p_hours,p_domainId,p_default_hours,p_timeZoneValue,p_type,v_curdate,v_curdate);
        
        SET v_lastId = last_insert_id();
        
		SET v_errcode	= 0;
		SET v_errmsg	= 'Business Hours Created Successfully!';
		
		INSERT INTO tb_business_hours_json_info(fk_businessId,domainId,day_name,isHoliday,startTimeStamp,endTimeStamp,startTime,endTime,createdAt,updatedAt)
		SELECT v_lastId,p_domainId,tt_day,tt_isHoliday,tt_startTimeStamp,tt_endTimeStamp,tt_startTime,tt_endTime,v_curdate,v_curdate
		FROM tt_business_hours;
    
			IF IFNULL(p_holiday,'') <> ''
			THEN
				INSERT INTO tb_Business_Holidays(domainId,fk_businessId,holidayName,startDate,endDate,isStatus,holidayDesc,createdAt,updatedAt,holidayPrompt,holidayMessage)
				SELECT p_domainId,v_lastId,tt_holidayName,tt_startDate,tt_endDate,tt_isStatus,tt_holidayDesc,v_curdate,v_curdate,tt_holidayPrompt,tt_holidayMessage
				FROM tt_business_holiday;
			END IF; 						
	ELSE 
		UPDATE custom_hours 
        SET name			=	IFNULL(p_name,name),
			description		=	IFNULL(p_description,description),
			hours			=	IFNULL(p_hours,hours),
			timeZone		=	IFNULL(p_timeZone,timeZone),
			default_hours	=	IFNULL(p_default_hours,default_hours),
			timeZoneValue	=	IFNULL(p_timeZoneValue,timeZoneValue),
			type			=	IFNULL(p_type,type),
			updatedAt		=	v_curdate
        WHERE cid = v_cid;

        IF EXISTS(SELECT 1 FROM tt_business_hours LIMIT 1)
        THEN
			DELETE FROM tb_business_hours_json_info
			WHERE fk_businessId = v_cid
			AND domainId = p_domainId;
			
			INSERT INTO tb_business_hours_json_info(fk_businessId,domainId,day_name,isHoliday,startTimeStamp,endTimeStamp,startTime,endTime,createdAt,updatedAt)
			SELECT v_cid,p_domainId,tt_day,tt_isHoliday,tt_startTimeStamp,tt_endTimeStamp,tt_startTime,tt_endTime,v_curdate,v_curdate
			FROM tt_business_hours;
			END IF;
        
			IF IFNULL(p_holiday,'') <> ''
				THEN
					INSERT INTO tb_Business_Holidays(domainId,fk_businessId,holidayName,startDate,endDate,isStatus,holidayDesc,createdAt,updatedAt,holidayPrompt,holidayMessage)
					SELECT p_domainId,v_cid,tt_holidayName,tt_startDate,tt_endDate,tt_isStatus,tt_holidayDesc,v_curdate,v_curdate,tt_holidayPrompt,tt_holidayMessage
					FROM tt_business_holiday;
			END IF; 
        SET v_errcode	= 1;
        SET v_errmsg	= 'Business Hours Updated Successfully';
	END IF;
    
    SELECT v_errcode AS errcode,v_errmsg AS errmsg;
    
    DROP TEMPORARY TABLE IF EXISTS tt_business_hours;
    DROP TEMPORARY TABLE IF EXISTS tt_business_holiday;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
