CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_customer_tag`(
	p_cid					int
	,p_customerTagName		varchar(100)
	,p_type					varchar(255)
	,p_description			varchar(250)
	,p_status				int
	,p_domainId				int
)
begin
			declare v_cid int;
            declare v_errcode int default -1;
			declare v_errmsg varchar(50) default 'Failure';
            
            select cid into v_cid
            from customer_tag
            where domainId = p_domainId
            and cid = p_cid;
            
	IF v_cid IS NULL
	THEN            
		INSERT INTO customer_tag (customerTagName,type,description,status,domainId,createdAt,updatedAt) 
		VALUES (p_customerTagName,p_type,p_description,p_status,p_domainId,NOW(),NOW());
		
        SET v_cid = last_insert_id();
        
		SET v_errcode = 0;
		SET v_errmsg = 'Inserted';
	ELSE 
		UPDATE customer_tag 
        SET customerTagName = p_customerTagName
        ,	type 			= p_type
        ,	description 	= p_description
        ,	status 			= p_status
        ,	updatedAt 		= NOW()
        WHERE cid = v_cid;
        
        SET v_errcode = 1;
		SET v_errmsg = 'Updated';

	END IF;
           select v_errcode as errcode, v_errmsg as errmsg,v_cid as insertId,p_customerTagName AS customerTagName,p_type AS type
           ,p_description AS description,p_status AS status,p_domainId AS domainId; 
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
