CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_customer_tag_disable`(
	p_domainId					int
    ,p_customerTag				int
)
begin
		declare v_errcode int default -1;
		declare v_errmsg varchar(50) default 'Failure';
	
		IF NOT EXISTS(SELECT 1 FROM domain_setting WHERE domainId = p_domainId)
        THEN
	  
			INSERT INTO domain_setting (customerTag,domainId,createdAt,updatedAt)
            VALUES(p_customerTag,p_domainId,NOW(),NOW());
            
			SET v_errcode = 0;
			SET v_errmsg = 'Inserted';

		ELSE 

			UPDATE domain_setting 
            SET customerTag 	= p_customerTag
            ,	updatedAt 		= NOW() 
            WHERE domainId = p_domainId;
            
			SET v_errcode = 0;
			SET v_errmsg = 'Updated';
		
        END IF;
	select v_errcode as errcode, v_errmsg as errmsg; 
end ;;
