CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_customer_type`(	
		p_id 				INT ,
		p_domainId 			INT ,
		p_customerTypeName 	VARCHAR(200) ,
		p_description 		TEXT,
		p_isStatus 			TINYINT,
        p_FieldType			VARCHAR(20)
)
begin
	
    declare v_errcode int default -1;
    declare v_errmsg varchar(100) default 'insert/update fail';
    declare v_id int;
  
	select id into v_id
    from 	tb_ccaas_customer_type_dtl 
    where 	id 			= p_id
    and 	domainId 	= p_domainId limit 1;

sp_exit:begin
		
	if exists(select 1 from tb_ccaas_customer_type_dtl 
    where id <> v_id 
    AND customerTypeName = p_customerTypeName 
    AND domainId = p_domainId limit 1)
    then
		set v_errcode 	= -2;
        set v_errmsg	= 'Customer name already exists';
	leave sp_exit;
	end if;

    IF v_id IS NULL
    THEN
    
    if exists(select 1 from tb_ccaas_customer_type_dtl 
    where customerTypeName = p_customerTypeName 
    AND domainId = p_domainId limit 1)
    then
		set v_errcode 	= -2;
        set v_errmsg	= 'Customer name already exists';
	leave sp_exit;
	end if;

		insert into tb_ccaas_customer_type_dtl(domainId ,customerTypeName ,description ,isStatus ,createdAt,FieldType )
        values(p_domainId ,p_customerTypeName ,p_description ,IFNULL(p_isStatus,1),now(),p_FieldType );
        
        set v_errcode 	= 0;
        set v_errmsg	= 'Customer Type: Inserted successfully';
	ELSE
		update tb_ccaas_customer_type_dtl
        set customerTypeName	= IFNULL(p_customerTypeName,customerTypeName)
			,description		= IFNULL(p_description,`description`)
			,isStatus			= IFNULL(p_isStatus,isStatus)
			,FieldType			= IFNULL(p_FieldType,FieldType)
            ,updatedAt			= now()
		where id = v_id;
        
        if row_count()>0
        then
			set v_errcode 	= 1;
			set v_errmsg	= 'Customer Type : updated successfully';
        end if;
        
	end if;
    end;
    select v_errcode as errcode,v_errmsg as errmsg;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
