CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insert_update_disposition_status`(	
 	 p_did				INT
 	,p_dispositionName	VARCHAR(100)
 	,p_type				VARCHAR(255)
 	,p_description		VARCHAR(250)
 	,p_status			INT
 	,p_domainId			INT
 	,p_colorCode		VARCHAR(50)			
 )
begin
 	
 		DECLARE v_errcode TINYINT DEFAULT -1;
 		DECLARE v_errmsg  VARCHAR(150) DEFAULT 'Disposition status inserted/update fail';	
         DECLARE v_did	  INT;
         DECLARE v_curDate DATETIME DEFAULT NOW();
 		
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 			SELECT did INTO v_did
 			FROM disposition_status
 			WHERE did 			= p_did
 			AND domainId 		= p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         
        IF v_did IS NULL
        THEN
         
 			INSERT INTO disposition_status (dispositionName, type, description, status, domainId, createdAt, updatedAt, colorCode) 
 			VALUES (p_dispositionName, p_type , p_description , p_status , p_domainId , v_curDate, v_curDate ,p_colorCode);
 			
             SET v_did = last_insert_id();
             
 			SET v_errcode = 0;
 			SET v_errmsg  = 'Disposition status inserted successfully';
             
 		ELSE 
         
 			UPDATE disposition_status 
 			SET dispositionName = IFNULL(p_dispositionName, dispositionName),
 				type 			= IFNULL(p_type, type),
 				description 	= IFNULL(p_description, description),
 				status 			= IFNULL(p_status, status),
 				updatedAt 		= v_curDate, 
 				colorCode 		= IFNULL(p_colorCode, colorCode)
 			WHERE did 			= v_did;
 			
             SET v_errcode = 1;
 			SET v_errmsg  = 'Disposition status updated successfully.';
 	END IF;
     
 		SELECT v_errcode AS errcode,v_errmsg AS errmsg, v_did AS did;
       
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
