CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_my_plan_role_permission`(
    p_domainId                 INT,
    p_role_id                  INT,
    p_is_agent_monitor         TINYINT,
    p_is_queue_management      TINYINT,
    p_is_reporting_dashboard   TINYINT,
    p_is_knowledge_base        TINYINT
)
BEGIN

    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg  VARCHAR(150) DEFAULT 'Insert / Update Failed';

sp_return:begin

	IF (IFNULL(p_role_id,'') = '' OR IFNULL(p_domainId,'') = '')
    THEN
		SET v_errcode = -1;
        SET v_errmsg  = 'roleId / domainId	should not be empty';
        leave sp_return;
	END IF;

    IF NOT EXISTS (SELECT 1 FROM tb_my_plan_role_permission WHERE domainId = p_domainId AND role_id = p_role_id LIMIT 1) 
    THEN
		INSERT INTO tb_my_plan_role_permission(domainId,role_id,is_agent_monitor,is_queue_management,is_reporting_dashboard,is_knowledge_base,createdAt,updated_at)
        VALUES(p_domainId,p_role_id,COALESCE(p_is_agent_monitor, 0),COALESCE(p_is_queue_management, 0),COALESCE(p_is_reporting_dashboard, 0),COALESCE(p_is_knowledge_base, 0),NOW(),NOW());

        SET v_errcode = 0;
        SET v_errmsg  = 'Inserted successfully';

    ELSE

        UPDATE tb_my_plan_role_permission
		SET
				is_agent_monitor       = IFNULL(p_is_agent_monitor, is_agent_monitor),
				is_queue_management    = IFNULL(p_is_queue_management, is_queue_management),
				is_reporting_dashboard = IFNULL(p_is_reporting_dashboard, is_reporting_dashboard),
				is_knowledge_base      = IFNULL(p_is_knowledge_base, is_knowledge_base),
				updated_at             = NOW()
		WHERE domainId = p_domainId
		AND role_id  = p_role_id;

        SET v_errcode = 1;
        SET v_errmsg  = 'Updated successfully';

    END IF;
end;
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
