/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_predictiveDialler`(	
	 p_cid					int
	,p_domainId				int
	,p_blastName			varchar(500)
    ,p_blastDescription 	text
    ,p_triggerType 			smallint 
    ,p_triggerDailyFile 	json
    ,p_triggerCustomFile 	json
    ,p_timeZone				varchar(500)
	,p_outboundNumber 		varchar(100)
	,p_campaignMessageType	smallint	
	,p_campaignMessage		json
    ,p_textSpeechFile		text
    ,p_createdBy			int
    ,p_blastId				varchar(50)
    ,p_contactType			smallint 	
    ,p_contact				json
    ,p_importContact		json
    ,p_importContactFile	json
    ,p_companyName			varchar(250)
)
begin
	
		DECLARE v_cid 		INT;
		DECLARE v_errcode 	INT DEFAULT -1;
		DECLARE v_errmsg 	VARCHAR(50) DEFAULT 'callBlast insert fail';
		DECLARE v_curDate 	DATETIME DEFAULT NOW();
		DECLARE v_JLength_json INT;
		DECLARE v_JLength_1 INT;
		DECLARE v_blastId 	INT;
		DECLARE v_triggerDailyFile INT;
		DECLARE v_triggerCustomFile INT;
		DECLARE v_time_difference_in_minutes INT;
		DECLARE v_noOfRecall INT;
		DECLARE v_recallAttemptInterval INT;
		DECLARE v_tt_hours JSON;
		DECLARE v_currentDate DATE;
		DECLARE v_curTime TIME;
		DECLARE v_curTimeFormat VARCHAR(3);

		SET v_currentDate = CURDATE();
		SET v_curTime = time_format(CURTIME(),'%h:%i');
		SET v_curTimeFormat = time_format(CURTIME(),'%p');
        
		SELECT 	cid INTO v_cid
		FROM 	tb_predictiveDialler 
		WHERE 	cid = p_cid;
		
		IF v_cid IS NULL
		THEN
			INSERT INTO tb_predictiveDialler(domainId,blastName,blastDescription,triggerType,triggerDailyFile,triggerCustomFile,timeZone,outboundNumber,campaignMessageType,campaignMessage,blastStatus,createdBy,blastId,contactType,contact,importContact,importContactFile,companyName,createdAt,updatedAt)
			VALUES(p_domainId,p_blastName,p_blastDescription,p_triggerType,p_triggerDailyFile,p_triggerCustomFile,p_timeZone,p_outboundNumber,p_campaignMessageType,p_campaignMessage,1,p_createdBy,p_blastId,p_contactType,p_contact,p_importContact,p_importContactFile,p_companyName,v_curDate,v_curDate);
			
			SET v_blastId = last_insert_id();

			
			if p_triggerType = 1
			then
				
					insert into tb_predictiveDialler_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
					select distinct v_blastId,v_currentDate,v_currentDate,concat('["',dayname(v_currentDate),'"]'),1,1,null,now();
					
                    SET  v_triggerDailyFile = last_insert_id();
					                    
					insert into tb_predictiveDialler_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
					select v_blastId,v_triggerDailyFile,dayname(v_currentDate),v_curTime,v_curTimeFormat,v_curTime,v_curTimeFormat,now();
                    
                    INSERT INTO tb_predictiveDialler_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                    SELECT v_blastId,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
					working_day
					from tb_predictiveDialler_dailyTrigger_json_dtl where fk_cid = v_blastId;
                
			  elseif p_triggerDailyFile is not null and p_triggerType = 2
			  then
              
				DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
				CREATE TEMPORARY TABLE tt_triggerDailyFile AS
                SELECT JSON_EXTRACT(p_triggerDailyFile,"$.startDate") AS tt_startDate,
					JSON_EXTRACT(p_triggerDailyFile,"$.endDate") AS tt_endDate,
                    JSON_EXTRACT(p_triggerDailyFile,"$.selectedDays") AS tt_selectedDays,
                    JSON_EXTRACT(p_triggerDailyFile,"$.noOfRecall") AS tt_noOfRecall,
                    JSON_EXTRACT(p_triggerDailyFile,"$.recallInterval") AS tt_recallInterval,
                    JSON_EXTRACT(p_triggerDailyFile,"$.customHours") AS tt_hours;
                                        
					insert into tb_predictiveDialler_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
					select distinct v_blastId,tt_startDate,tt_endDate,tt_selectedDays,tt_noOfRecall,tt_recallInterval,tt_hours,now()
					from tt_triggerDailyFile;
					                    
					SET  v_triggerDailyFile = last_insert_id();
			
                    SELECT dailyHour INTO v_tt_hours FROM tb_predictiveDialler_dailyTrigger_dtl WHERE tid = v_triggerDailyFile;
                                       
                    SET v_JLength_json = JSON_LENGTH(v_tt_hours, "$");
					 
					DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
					CREATE TEMPORARY TABLE tt_triggerDailyFileJson AS
					WITH RECURSIVE CTE_JsonCount AS (
						SELECT 0 SlNo
						UNION ALL
						SELECT SlNo + 1 SlNo
						FROM CTE_JsonCount
						WHERE SlNo < v_JLength_json - 1
					)
					SELECT 
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].working_day')))) AS tt_working_day,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].startTime')))) AS tt_StartTime,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].StartTimeFormat')))) AS tt_StartTimeFormat,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].endTime')))) AS tt_EndTime,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].EndTimeFormat')))) AS tt_EndTimeFormat
					FROM CTE_JsonCount;
                    
					insert into tb_predictiveDialler_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
					select v_blastId,v_triggerDailyFile,tt_working_day,tt_StartTime,tt_StartTimeFormat,tt_EndTime,tt_EndTimeFormat,now()
					from tt_triggerDailyFileJson;

				   SELECT noOfRecall INTO v_noOfRecall 
                   FROM tb_predictiveDialler_dailyTrigger_dtl
                   WHERE tid = v_triggerDailyFile;
             
                   SELECT 	SUM(TIMESTAMPDIFF(MINUTE, 
							STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
							STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p')
							) ) INTO v_time_difference_in_minutes
					FROM tb_predictiveDialler_dailyTrigger_json_dtl 
                    WHERE fk_tid = v_triggerDailyFile;
				   
				SELECT v_time_difference_in_minutes/v_noOfRecall INTO  v_recallAttemptInterval;
				
                call ccaas_get_predictiveDialler_timeSplit(v_recallAttemptInterval,v_blastId);
                
			   elseif p_triggerCustomFile is not null and p_triggerType = 3
			   then
			   
				DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
				CREATE TEMPORARY TABLE tt_triggerCustomFile AS
                SELECT JSON_EXTRACT(p_triggerCustomFile,"$.triggerDate") AS tt_triggerDate,
						JSON_EXTRACT(p_triggerCustomFile,"$.triggerTime") AS tt_triggerTime,
						JSON_UNQUOTE(JSON_EXTRACT(p_triggerCustomFile,"$.timeFormat")) AS tt_timeFormat;

					insert into tb_predictiveDialler_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
					select distinct v_blastId,tt_triggerDate,tt_triggerDate,concat('["',dayname(tt_triggerDate),'"]'),1,1,null,now()
					from tt_triggerCustomFile;
					
                    SET  v_triggerDailyFile = last_insert_id();
					                    
					insert into tb_predictiveDialler_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
					select v_blastId,v_triggerDailyFile,dayname(tt_triggerDate),tt_triggerTime,tt_timeFormat,tt_triggerTime,tt_timeFormat,now()
					from tt_triggerCustomFile;
                    
                    INSERT INTO tb_predictiveDialler_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                    SELECT v_blastId,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
					working_day
					from tb_predictiveDialler_dailyTrigger_json_dtl where fk_cid = v_blastId;
                    
			  end if;       
            
			
            
            SET v_errcode = 0;
			SET v_errmsg  = 'callBlast inserted successfully';
            
    ELSE 
			UPDATE tb_predictiveDialler 
            SET  blastName			=IFNULL(p_blastName,blastName)
				,blastDescription	=IFNULL(p_blastDescription ,blastDescription)
				,triggerType		=IFNULL(p_triggerType ,triggerType)
				,triggerDailyFile	=IFNULL(p_triggerDailyFile ,triggerDailyFile)
				,triggerCustomFile	=IFNULL(p_triggerCustomFile ,triggerCustomFile)
				,timeZone			=IFNULL(p_timeZone,timeZone)
				,outboundNumber		=IFNULL(p_outboundNumber ,outboundNumber)
				,campaignMessageType=IFNULL(p_campaignMessageType,campaignMessageType)
				,campaignMessage	=IFNULL(p_campaignMessage,campaignMessage)
				,textSpeechFile		=IFNULL(p_textSpeechFile,textSpeechFile)
				,createdBy			=IFNULL(p_createdBy,createdBy)
				,blastId			=IFNULL(p_blastId,blastId)
				,contactType		=IFNULL(p_contactType,contactType)
				,contact			=IFNULL(p_contact,contact)
				,importContact		=IFNULL(p_importContact,importContact)
				,importContactFile	=IFNULL(p_importContactFile,importContactFile)
				,companyName		=IFNULL(p_companyName,companyName)
				,updatedAt			=NOW()
			WHERE cid = v_cid;
            
            DELETE FROM tb_predictiveDialler_timeToTrigger_info 
			WHERE fk_cid = v_cid;
            
            DELETE FROM tb_predictiveDialler_dailyTrigger_json_dtl 
			WHERE fk_cid = v_cid;
            
			DELETE FROM tb_predictiveDialler_dailyTrigger_dtl 
			WHERE fk_cid = v_cid;

        if p_triggerType = 1
			then
					insert into tb_predictiveDialler_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
					select distinct v_cid,v_currentDate,v_currentDate,concat('["',dayname(v_currentDate),'"]'),1,1,null,now();
					
                    SET  v_triggerDailyFile = last_insert_id();
					                    
					insert into tb_predictiveDialler_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
					select v_cid,v_triggerDailyFile,dayname(v_currentDate),v_curTime,v_curTimeFormat,v_curTime,v_curTimeFormat,now();
                    
                    INSERT INTO tb_predictiveDialler_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                    SELECT v_cid,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
					working_day
					from tb_predictiveDialler_dailyTrigger_json_dtl where fk_cid = v_cid;
                
			  elseif p_triggerDailyFile is not null and p_triggerType = 2
			  then
              
				DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFile;
				CREATE TEMPORARY TABLE tt_triggerDailyFile AS
                SELECT JSON_EXTRACT(p_triggerDailyFile,"$.startDate") AS tt_startDate,
					JSON_EXTRACT(p_triggerDailyFile,"$.endDate") AS tt_endDate,
                    JSON_EXTRACT(p_triggerDailyFile,"$.selectedDays") AS tt_selectedDays,
                    JSON_EXTRACT(p_triggerDailyFile,"$.noOfRecall") AS tt_noOfRecall,
                    JSON_EXTRACT(p_triggerDailyFile,"$.recallInterval") AS tt_recallInterval,
                    JSON_EXTRACT(p_triggerDailyFile,"$.customHours") AS tt_hours;
                                        
					insert into tb_predictiveDialler_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
					select distinct v_cid,tt_startDate,tt_endDate,tt_selectedDays,tt_noOfRecall,tt_recallInterval,tt_hours,now()
					from tt_triggerDailyFile;
					                    
					SET  v_triggerDailyFile = last_insert_id();
			
                    SELECT dailyHour INTO v_tt_hours FROM tb_predictiveDialler_dailyTrigger_dtl WHERE tid = v_triggerDailyFile;
                                       
                    SET v_JLength_json = JSON_LENGTH(v_tt_hours, "$");
					 
					DROP TEMPORARY TABLE IF EXISTS tt_triggerDailyFileJson;
					CREATE TEMPORARY TABLE tt_triggerDailyFileJson AS
					WITH RECURSIVE CTE_JsonCount AS (
						SELECT 0 SlNo
						UNION ALL
						SELECT SlNo + 1 SlNo
						FROM CTE_JsonCount
						WHERE SlNo < v_JLength_json - 1
					)
					SELECT 
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].working_day')))) AS tt_working_day,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].startTime')))) AS tt_StartTime,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].StartTimeFormat')))) AS tt_StartTimeFormat,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].endTime')))) AS tt_EndTime,
						TRIM(BOTH '"' FROM (json_extract(v_tt_hours, CONCAT('$[', SlNo, '].EndTimeFormat')))) AS tt_EndTimeFormat
					FROM CTE_JsonCount;
                    
					insert into tb_predictiveDialler_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
					select v_cid,v_triggerDailyFile,tt_working_day,tt_StartTime,tt_StartTimeFormat,tt_EndTime,tt_EndTimeFormat,now()
					from tt_triggerDailyFileJson;

				   SELECT noOfRecall INTO v_noOfRecall 
                   FROM tb_predictiveDialler_dailyTrigger_dtl
                   WHERE tid = v_triggerDailyFile;
             
                   SELECT 	SUM(TIMESTAMPDIFF(MINUTE, 
							STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
							STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p')
							) ) INTO v_time_difference_in_minutes
					FROM tb_predictiveDialler_dailyTrigger_json_dtl 
                    WHERE fk_tid = v_triggerDailyFile;
				   
				SELECT v_time_difference_in_minutes/v_noOfRecall INTO  v_recallAttemptInterval;
				
                call ccaas_get_callBlast_timeSplit(v_recallAttemptInterval,v_blastId);
                
			   elseif p_triggerCustomFile is not null and p_triggerType = 3
			   then
			   
				DROP TEMPORARY TABLE IF EXISTS tt_triggerCustomFile;
				CREATE TEMPORARY TABLE tt_triggerCustomFile AS
                SELECT JSON_EXTRACT(p_triggerCustomFile,"$.triggerDate") AS tt_triggerDate,
						JSON_EXTRACT(p_triggerCustomFile,"$.triggerTime") AS tt_triggerTime,
						JSON_UNQUOTE(JSON_EXTRACT(p_triggerCustomFile,"$.timeFormat")) AS tt_timeFormat;

					insert into tb_predictiveDialler_dailyTrigger_dtl(fk_cid,startDate,endDate,selectedDays,noOfRecall,recallInterval,dailyHour,createdAt)
					select distinct v_cid,tt_triggerDate,tt_triggerDate,concat('["',dayname(tt_triggerDate),'"]'),1,1,null,now()
					from tt_triggerCustomFile;
					
                    SET  v_triggerDailyFile = last_insert_id();
					                    
					insert into tb_predictiveDialler_dailyTrigger_json_dtl(fk_cid,fk_tid,working_day,StartTime,StartTimeFormat,EndTime,EndTimeFormat,createdAt)
					select v_cid,v_triggerDailyFile,dayname(tt_triggerDate),tt_triggerTime,tt_timeFormat,tt_triggerTime,tt_timeFormat,now()
					from tt_triggerCustomFile;
                    
                    INSERT INTO tb_predictiveDialler_timeToTrigger_info(fk_cid,startTime,endTime,working_day)
                    SELECT v_cid,STR_TO_DATE(CONCAT(TIME_FORMAT(StartTime, '%h:%i'), ' ', StartTimeFormat), '%h:%i %p'),
					STR_TO_DATE(CONCAT(TIME_FORMAT(EndTime, '%h:%i'), ' ', EndTimeFormat), '%h:%i %p'),
					working_day
					from tb_predictiveDialler_dailyTrigger_json_dtl where fk_cid = v_cid;
                    
			  end if;
              
					SET v_errcode = 1;
					SET v_errmsg  = 'callBlast updated successfully';
        
	END IF;
        
    SELECT v_errcode as errcode,v_errmsg as errmsg,IFNULL(v_blastId,p_cid) as blastId;
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_insert_update_predictiveDialler_triggered_call_history_dtl` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
