/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_predictiveDialler_triggered_call_history_dtl`(
	p_blastId int,
	p_triggeredId int,
	p_customerContact json
)
begin

	DECLARE v_tcid INT;
	DECLARE v_curdate DATETIME;
	DECLARE v_errcode INT DEFAULT -1;
	DECLARE v_errmsg VARCHAR(100) DEFAULT 'Callblast History insert/updated fail';
    
    SET v_curdate = NOW();
    
	SELECT 	tcid INTO v_tcid 
    FROM 	tb_predictiveDialler_triggered_customer_call_dtl
    WHERE 	fk_cid = p_blastId
    AND		fk_triggeredId = p_triggeredId;
    
    IF v_tcid IS NULL
    THEN
		INSERT INTO tb_predictiveDialler_triggered_customer_call_dtl(fk_cid,fk_triggeredId,customerContact,createdAt,updatedAt)
		VALUES(p_blastId,p_triggeredId,p_customerContact,v_curdate,v_curdate);
        
        SET v_errcode = 0;
        SET v_errmsg = 'Callblast History inserted successfully';
        
	ELSE 
		UPDATE tb_predictiveDialler_triggered_customer_call_dtl
        SET customerContact = JSON_ARRAY_APPEND(customerContact, '$', p_customerContact);
		
        SET v_errcode = 1;
        SET v_errmsg = 'Callblast History updated successfully';
	END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
