/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_queue`(
		p_qid						int	
		,p_name						varchar(255)
		,p_description				varchar(1000)
		,p_domainId					int
		,p_settingAudio				longtext
		,p_announcement				longtext
		,p_maximumCallers			longtext
		,p_maximumWaitTime			longtext
		,p_OutboundCallerId			varchar(100)
		,p_outBoundNumber			varchar(20)
		,p_maxCallHandlingTimeMM	int
		,p_callWrapUpTime			int
		,p_outBoundCallStatus		int
		,p_hoursOfOperatioId		int
		,p_hours_of_operation		longtext
		,p_outOfBusinessHours		longtext
		,p_status					int
		,p_type						varchar(55)
)
begin
		declare v_errcode int default -1;
		declare v_errmsg varchar(50) default 'Failure';
    declare v_qid int;
    
		select qid into v_qid
		from queue
		where domainId = p_domainId
		and qid = p_qid;
      
		IF v_qid IS NULL
		THEN 
    
			INSERT INTO queue (name,description,domainId,OutboundCallerId,outBoundNumber,maxCallHandlingTimeMM,callWrapUpTime,hours_of_operation
			,outBoundCallStatus,settingAudio,announcement,maximumCallers,maximumWaitTime,hoursOfOperatioId,createdAt,updatedAt,outOfBusinessHours
			,status,type) 
			VALUES (p_name,p_description,p_domainId,p_OutboundCallerId,p_outBoundNumber,p_maxCallHandlingTimeMM,p_callWrapUpTime,p_hours_of_operation
			,p_outBoundCallStatus,p_settingAudio,p_announcement,p_maximumCallers,p_maximumWaitTime,p_hoursOfOperatioId,NOW(),NOW(),p_outOfBusinessHours
			,p_status,p_type);
			
			SET v_qid = last_insert_id(); 
            
            INSERT INTO tb_queue_permission(fk_qid,domainId,agentMonitoring,addOrRemove,reportingDashboard,createdAt,updatedAt)
            VALUES(v_qid,p_domainId,0,0,0,NOW(),NOW());
		 
			SET v_errcode = 0;
			SET v_errmsg = 'Inserted';
    ELSE 
			
      UPDATE queue
		 SET name					= IFNULL(p_name	,name	)
			,description			= IFNULL(p_description	,description	)
			,settingAudio			= IFNULL(p_settingAudio	,settingAudio	)
			,announcement			= IFNULL(p_announcement	,announcement	)
			,maximumCallers			= IFNULL(p_maximumCallers	,maximumCallers	)
			,maximumWaitTime		= IFNULL(p_maximumWaitTime	,maximumWaitTime	)
			,OutboundCallerId		= IFNULL(p_OutboundCallerId	,OutboundCallerId	)
			,outBoundNumber			= IFNULL(p_outBoundNumber	,outBoundNumber	)
			,maxCallHandlingTimeMM	= IFNULL(p_maxCallHandlingTimeMM	,maxCallHandlingTimeMM	)
			,callWrapUpTime			= IFNULL(p_callWrapUpTime	,callWrapUpTime	)
			,outBoundCallStatus		= IFNULL(p_outBoundCallStatus	,outBoundCallStatus	)
			,hoursOfOperatioId		= IFNULL(p_hoursOfOperatioId	,hoursOfOperatioId	)
			,hours_of_operation		= IFNULL(p_hours_of_operation	,hours_of_operation	)
			,outOfBusinessHours		= IFNULL(p_outOfBusinessHours	,outOfBusinessHours	)
			,status					= IFNULL(p_status	,status	)
			,type					= IFNULL(p_type	,type	)
			,updatedAt				= NOW()
		WHERE qid = v_qid;
        
	UPDATE queueWeighTime SET queueName = p_name,updatedAt = NOW()  WHERE qid = v_qid;
    
    SET v_errcode = 1;
		SET v_errmsg = 'Updated';
  
	END IF;
		select v_errcode as errcode, v_errmsg as errmsg,v_qid as qid,p_name AS name,p_description AS description,p_domainId AS domainId
,p_settingAudio AS settingAudio,p_announcement AS announcement,p_maximumCallers AS maximumCallers,p_maximumWaitTime AS maximumWaitTime
,p_OutboundCallerId AS OutboundCallerId,p_outBoundNumber AS outBoundNumber,p_maxCallHandlingTimeMM AS maxCallHandlingTimeMM
,p_callWrapUpTime AS callWrapUpTime,p_outBoundCallStatus AS outBoundCallStatus,p_hoursOfOperatioId AS hoursOfOperatioId,p_hours_of_operation AS hours_of_operation
,p_outOfBusinessHours AS outOfBusinessHours,p_status AS status,p_type AS type;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
