DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_settings_voice_video_recording`(
	 p_rid 						int 
	,p_domainId 				int
	,p_isVoice 					tinyint
	,p_isInbound 				tinyint
	,p_isOutbound 				tinyint
	,p_isVoiceConsentNotice 	tinyint
	,p_isVoiceTextToSpeech 		tinyint
	,p_voiceText 				text
	,p_isVoiceSelectPrompt 		tinyint
	,p_voicePrompt				varchar(250)
	,p_isVoiceAgentAccess 		tinyint
    ,p_isVideo 					tinyint
    ,p_isVideoConsentNotice 	tinyint
	,p_isVideoTextToSpeech 		tinyint
	,p_videoText 				text
	,p_isVideoSelectPrompt 		tinyint
	,p_videoPrompt				varchar(250)
	,p_isVideoAgentAccess 		tinyint
    ,p_voiceUrl					text
    ,p_videoUrl					text
)
begin

	DECLARE v_rid 		INT;
    DECLARE v_errcode 	INT DEFAULT -1 ;
    DECLARE v_errmsg 	VARCHAR(100) DEFAULT 'Voice video recording insert/update fail';

	SELECT rid INTO v_rid
    FROM 	ccaas_settings_voice_video_recording_dtl
    WHERE 	rid 		= p_rid
    AND 	domainId 	= p_domainId;

	IF v_rid IS NULL
    THEN 
		INSERT INTO ccaas_settings_voice_video_recording_dtl(domainId,isVoice,isInbound,isOutbound,isVoiceConsentNotice,isVoiceTextToSpeech,voiceText,isVoiceSelectPrompt,voicePrompt,isVoiceAgentAccess
		,isVideo,isVideoConsentNotice,isVideoTextToSpeech,videoText,isVideoSelectPrompt,videoPrompt,isVideoAgentAccess,createdAt,voiceUrl,videoUrl)
		VALUES(p_domainId,p_isVoice,p_isInbound,p_isOutbound,p_isVoiceConsentNotice,p_isVoiceTextToSpeech,p_voiceText,p_isVoiceSelectPrompt,p_voicePrompt,p_isVoiceAgentAccess
		,p_isVideo,p_isVideoConsentNotice,p_isVideoTextToSpeech,p_videoText,p_isVideoSelectPrompt,p_videoPrompt,p_isVideoAgentAccess,now(),p_voiceUrl,p_videoUrl);
        
        SET v_errcode = 0;
		SET v_errmsg  = 'Voice and video record setting inserted successfully';
            
    ELSE 
		UPDATE ccaas_settings_voice_video_recording_dtl
        SET isVoice 				=IFNULL(p_isVoice 				,isVoice )
			,isInbound 				=IFNULL(p_isInbound 			,isInbound )
			,isOutbound 			=IFNULL(p_isOutbound 			,isOutbound )
			,isVoiceConsentNotice	=IFNULL(p_isVoiceConsentNotice 	,isVoiceConsentNotice )
			,isVoiceTextToSpeech 	=IFNULL(p_isVoiceTextToSpeech 	,isVoiceTextToSpeech )
			,voiceText 				=IFNULL(p_voiceText 			,voiceText )
			,isVoiceSelectPrompt 	=IFNULL(p_isVoiceSelectPrompt 	,isVoiceSelectPrompt )
			,voicePrompt			=IFNULL(p_voicePrompt			,voicePrompt)
			,isVoiceAgentAccess 	=IFNULL(p_isVoiceAgentAccess 	,isVoiceAgentAccess )
			,isVideo 				=IFNULL(p_isVideo				,isVideo )
			,isVideoConsentNotice 	=IFNULL(p_isVideoConsentNotice 	,isVideoConsentNotice )
			,isVideoTextToSpeech 	=IFNULL(p_isVideoTextToSpeech 	,isVideoTextToSpeech )
			,videoText 				=IFNULL(p_videoText 			,videoText )
			,isVideoSelectPrompt 	=IFNULL(p_isVideoSelectPrompt 	,isVideoSelectPrompt )
			,videoPrompt			=IFNULL(p_videoPrompt			,videoPrompt)
			,isVideoAgentAccess 	=IFNULL(p_isVideoAgentAccess 	,isVideoAgentAccess )
			,voiceUrl 				=IFNULL(p_voiceUrl 	,voiceUrl )
			,videoUrl 				=IFNULL(p_videoUrl 	,videoUrl )
			,updatedAt				=now()
		WHERE rid = v_rid;
        
		IF ROW_COUNT()>0
        THEN 
			SET v_errcode = 1;
            SET v_errmsg  = 'Voice and video record setting updated successfully';
        END IF;
	END IF;
    
    SELECT v_errcode as errcode, v_errmsg as errmsg;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_insert_update_user_chat_tracking_log` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_insert_update_user_chat_tracking_log`(
	p_domainId 		int,
	p_chatid 		bigint,
	p_chatuserlog 	json
)
begin

	declare v_cid int;
    declare v_id int;
    declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'insert/update fail';
    
    select id into v_cid 
    from ccaas_user_chat_tracking_log
    where domainId = p_domainId
    and chatid = p_chatid limit 1;
    
    IF v_cid IS NULL
    THEN
		insert into ccaas_user_chat_tracking_log(domainId,chatid,chatuserlog,createdAt)
		values(p_domainId,p_chatid,p_chatuserlog,now());
		
        set v_id = last_insert_id();
        
		SET v_errcode = 0;
		SET v_errmsg  = 'Inserted successfully';
    
    ELSE
		
        update ccaas_user_chat_tracking_log
        set chatuserlog = p_chatuserlog
			,updatedAt = now()
        where id = v_cid;
        
		SET v_errcode = 1;
		SET v_errmsg  = 'Updated successfully';
        
	END IF;
    
    SELECT v_id as id,v_errcode as errcode,v_errmsg as errmsg;

end ;;
DELIMITER ;
