CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_update_user_onboard_settings_completion`(	
	 p_email_id				VARCHAR(150),
	 p_domainId				INT,
	 p_flow_track			JSON,
	 p_is_Completed			TINYINT,
     p_completed_channels	VARCHAR(1000)
)
BEGIN

	DECLARE v_errcode 	INT DEFAULT -1;
	DECLARE v_errmsg 	VARCHAR(100) DEFAULT 'Insert / update fail';
    
	IF NOT EXISTS(SELECT 1 FROM tb_user_onboard_setting_flow WHERE email_id = p_email_id AND domainId = p_domainId LIMIT 1)
    THEN
		INSERT INTO tb_user_onboard_setting_flow(email_id, domainId, flow_track, isCompleted, completedChannels, createdAt) 
		VALUES(p_email_id, p_domainId, p_flow_track, p_is_Completed, p_completed_channels, NOW());
		
		SET v_errcode = 0;
		SET v_errmsg = 'Inserted successfully';
		
	ELSE 
		UPDATE tb_user_onboard_setting_flow
        SET  
			flow_track			= COALESCE(p_flow_track, flow_track),
			isCompleted			= COALESCE(p_is_Completed, isCompleted),
			completedChannels	= COALESCE(p_completed_channels, completedChannels),
			updatedAt	= NOW()
		WHERE email_id = p_email_id
		AND domainId = p_domainId;
			
		SET v_errcode = 1;
		SET v_errmsg = 'Updated successfully';
		
    END IF;

    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
