CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_whatsapp_callback_status`(
	 p_domainId 			INT
    ,p_sessionId			varchar(500)
    ,p_IsInBound			tinyint
    ,p_customerNumber		bigint
    ,p_calledNumber			bigint
    ,p_whatsappHistoryId	int
)
begin

		DECLARE v_errcode 				INT DEFAULT -1;
		DECLARE v_errmsg  				VARCHAR(100) DEFAULT 'WhatsApp callback status insert fail';
		DECLARE v_WhatsappHistoryId 	INT;
		DECLARE v_customerId 			INT;

		UPDATE tb_WhatsappDurationHistory
		SET IsBot = 1
		WHERE WhatsappHistoryId = p_whatsappHistoryId; 
        
        SELECT coid
        INTO v_customerId 
        FROM customer_contact 
        WHERE domainId = p_domainId 
        AND primaryPhoneNumber = p_customerNumber ORDER BY 1 DESC;

		INSERT INTO tb_WhatsappHistory(sessionId,sessionStartTime,sessionEndTime,domainId,IsInBound,noOfRepeats,IsSessionClosed,customerNumber,calledNumber,createdAt,updatedAt,isCallback,callbackDraft,customerId)
        VALUES(p_sessionId,(unix_timestamp()*1000),0,p_domainId,p_IsInBound,0,0,p_customerNumber,p_calledNumber,now(),now(),1,0,v_customerId);
		
        SET v_WhatsappHistoryId = last_insert_id();
    
		INSERT INTO tb_WhatsappMessage(WhatsappHistoryId,Message,createdAt,updatedAt)
        VALUES(v_WhatsappHistoryId,null,now(),now());
        
        INSERT INTO tb_WhatsappDurationHistory(WhatsappHistoryId,IsBot,createdAt,updatedAt,IsMissed)
        VALUES(v_WhatsappHistoryId,0,now(),now(),0);
    
    SET v_errcode = 0;
    SET v_errmsg  = 'WhatsApp callback status inserted successfully';

   
   SELECT v_errcode as errcode,v_errmsg as errmsg;
    
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
