CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_insert_whatsapp_message_flow_break_bot`(
	p_whatsappHistoryId	int
    ,p_domainId			int
    ,p_message 			text
    ,p_customerNumber	bigint
)
begin

	declare v_errcode int;
	declare v_errmsg  varchar(100);
	
    if not exists(select 1 from tb_whatsapp_message_flow_break_bot where whatsappHistoryId = p_whatsappHistoryId and domainId = p_domainId limit 1)
    then
    
    insert into tb_whatsapp_message_flow_break_bot(whatsappHistoryId, domainId, message, customerNumber, createdAt)
	values(p_whatsappHistoryId ,p_domainId ,p_message ,p_customerNumber,now());
		
     if row_count()>0
     then
		 set v_errcode = 0;
		 set v_errmsg  = 'Whatsapp msg updated successfully';
     end if; 
     
	end if; 

	select v_errcode as errcode, v_errmsg as errmsg;

end ;;
