DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_inserUpdate_callBlast_campaignCallAutoAnswer`(
	 p_domainId		INT 
    ,p_isAutoAnswer 	TINYINT
)
begin
		DECLARE v_caid 	INT;
		DECLARE v_Id 	INT;
        DECLARE v_errcode 		INT DEFAULT -1;
		DECLARE v_errmsg 		VARCHAR(255) DEFAULT 'Campaign auto answer Failed'; 

		SELECT caid INTO v_caid 
        FROM tb_callBlast_campaignCallAutoAnswer 
        WHERE domainId = p_domainId;
        
        IF v_caid IS NULL
        THEN
			INSERT INTO tb_callBlast_campaignCallAutoAnswer(isAutoAnswer,domainId,createdAt,updatedAt)
			VALUES (p_isAutoAnswer,p_domainId,now(),now());
            
            SET v_Id = LAST_INSERT_ID();
            
				SET v_errcode = 0;
				SET v_errmsg = 'Campaign auto answer inserted successfully'; 
        ELSE
				UPDATE tb_callBlast_campaignCallAutoAnswer 
 				SET 	isAutoAnswer = p_isAutoAnswer
						,updatedAt 	= now()
 				WHERE 	caid 		= v_caid;
     				  
     				SET v_errcode = 1;
     				SET v_errmsg = 'Campaign auto answer updated successfully';
        End if;
        
		select v_errcode as errcode, v_errmsg as errmsg,ifnull(v_Id,v_caid) as Id;

end ;;
DELIMITER ;
