CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_InstagramIsBotUpdate`(
p_InstagramHistoryId INT
)
begin
			  DECLARE v_errcode INT;
              DECLARE v_errmsg  VARCHAR(50);
               UPDATE tb_InstagramHistory 
               SET         IsBot = 1
