CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_leadGenerationReports`(
  p_domainId int,
  p_timeStamp bigint
  )
begin  
  select firstName, lastName 
 		,	IF(IFNULL(primaryPhoneNumber,'')='',phoneNumber, JSON_ARRAY_INSERT(phoneNumber,'$[0]',primaryPhoneNumber))	phoneNumber				
 		,	IF(IFNULL(primaryEmail,'')='',email,JSON_ARRAY_INSERT(email,'$[0]',primaryEmail))							email              
		,	accountNumber, tags,
 		location, address, country, state, city, postalCode,
 		facebook, instagram, whatsapp, twitter, voiceBiometric,
 		domainId, mergeCustomer, blockCustomer, doNotDisturb,
 		blockCustomerReq, doNotDisturbReq, type,
 		currentCustomerNumber, customerType,timeZone,cookiesId, createdAt, updatedAt
 FROM 	customer_contact
 WHERE 	UNIX_TIMESTAMP(createdAt)*1000 > p_timeStamp 
 AND 	domainId 					= p_domainId
 AND 	JSON_VALID(phoneNumber) 	= 1
 AND 	JSON_VALID(email) 			= 1;  
end ;;
DELIMITER ;
