/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_live_dashboard_agent_assistance`(
 p_startTmpstmp BIGINT, 
 p_endTmpstmp BIGINT, 
 p_domainId INT,
 p_channel varchar(20),
 p_AgentId	INT
 )
Begin

	DECLARE v_countOfDispositionResolved INT;
    DECLARE v_channel varchar(20);
    DECLARE v_AgentId	int;
    
    SET v_AgentId = p_AgentId;
    
    IF p_channel = "ALL" THEN
		SET v_channel = null;
	ELSE 
		SET v_channel = p_channel;
	END IF;
    
     DROP temporary table IF EXISTS tt_AllHistoryId;
    CREATE temporary table tt_AllHistoryId(HistoryId int, channelType varchar(100), domainId int, AgentId int);
    
IF v_AgentId IS NOT NULL THEN 
    INSERT INTO tt_AllHistoryId(HistoryId, channelType, domainId, AgentId)
   select t1.CallHistoryId, "Call", t1.domainId, t2.AgentId FROM tb_CallHistory as t1
join tb_CallDurationHistory as t2
ON t1.CallHistoryId = t2.CallHistoryId
WHERE t1.domainId= p_domainId AND (t2.AgentId = p_AgentId OR IFNULL(p_AgentId,'')='')
UNION ALL
select t1.ChatHistoryId, "Chat", t1.domainId, t2.AgentId FROM tb_ChatHistory as t1
join tb_ChatDurationHistory as t2
ON t1.ChatHistoryId = t2.ChatHistoryId
WHERE t1.domainId= p_domainId AND (t2.AgentId = p_AgentId OR IFNULL(p_AgentId,'')='')
UNION ALL
select t1.EmailHistoryId, "Email", t1.domainId, t2.AgentId FROM tb_EmailHistory as t1
join tb_EmailDurationHistory as t2
ON t1.EmailHistoryId = t2.EmailHistoryId
WHERE t1.domainId= p_domainId AND (t2.AgentId = p_AgentId OR IFNULL(p_AgentId,'')='')
UNION ALL
select t1.SMSHistoryId, "SMS", t1.domainId, t2.AgentId FROM tb_SMSHistory as t1
join tb_SMSDurationHistory as t2
ON t1.SMSHistoryId = t2.SMSHistoryId
WHERE t1.domainId= p_domainId AND (t2.AgentId = p_AgentId OR IFNULL(p_AgentId,'')='') 
UNION ALL
select t1.WhatsappHistoryId, "Whatsapp", t1.domainId, t2.AgentId FROM tb_WhatsappHistory as t1
join tb_WhatsappDurationHistory as t2
ON t1.WhatsappHistoryId = t2.WhatsappHistoryId
WHERE t1.domainId= p_domainId AND (t2.AgentId = p_AgentId OR IFNULL(p_AgentId,'')='')
UNION ALL 
SELECT FacebookHistoryId, "Facebook", domainId, AgentId FROM tb_FacebookHistory
WHERE domainId= p_domainId AND (AgentId = p_AgentId OR IFNULL(p_AgentId,'')='')
UNION ALL 
SELECT InstagramHistoryId, "Instagram", domainId, AgentId FROM tb_InstagramHistory
WHERE domainId= p_domainId AND (AgentId = p_AgentId OR IFNULL(p_AgentId,'')='');
END IF;
	
    
    
    DROP TEMPORARY TABLE IF EXISTS temp_AgentDisposition;
    CREATE TEMPORARY TABLE temp_AgentDisposition AS
	select 
			CASE WHEN AAM.channelType='Chat' 	THEN CDH.dispositionId
				 WHEN AAM.channelType='Call' 	THEN CH.dispositionId
				 WHEN AAM.channelType='Email' 	THEN EH.DispositionId
				 WHEN AAM.channelType='Sms' 	THEN EH.dispositionId
				 WHEN AAM.channelType='WhatsApp' THEN EH.dispositionId
				 WHEN AAM.channelType='Facebook' THEN EH.dispositionId
				 WHEN AAM.channelType='Instagram' THEN EH.dispositionId
        ELSE 0 END  as dispositionId
	from tb_chatAgentAssistMessage 			AAM
    left join tb_CallDurationHistory 		CH 		on CH.CallDurationHistoryId 		= AAM.durationHistoryId
    left join tb_ChatDurationHistory 		CDH 	on CDH.ChatDurationHistoryId 		= AAM.durationHistoryId
    left join tb_EmailDurationHistory 		EDHI 	on EDHI.EmailDurationHistoryId 		= AAM.durationHistoryId
	left join tb_EmailHistory 				EH 		on EH.EmailHistoryId 				= EDHI.EmailHistoryId
	left join tb_SMSDurationHistory 		SDHI 	on SDHI.SMSDurationHistoryId 		= AAM.durationHistoryId
    left join tb_SMSHistory 				SH 		on SH.SMSHistoryId 					= SDHI.SMSHistoryId
    left join tb_WhatsappDurationHistory 	WDHI 	on WDHI.WhatsappDurationHistoryId 	= AAM.durationHistoryId
    left join tb_WhatsappHistory 			WH 		on WH.WhatsappHistoryId 			= WDHI.WhatsappHistoryId
    left join tb_FacebookHistory 			FH 		on FH.FacebookHistoryId 			= AAM.historyId
    left join tb_InstagramHistory 			IH 		on IH.InstagramHistoryId 			= AAM.historyId
    where AAM.domainId = p_domainId 
	AND AAM.createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
    AND (channelType = p_channel or ifnull(v_channel,'')='')
    AND (CDH.AgentId = p_AgentId OR IFNULL(p_AgentId, '')='')
    AND (EDHI.AgentId = p_AgentId OR IFNULL(p_AgentId, '')='')
    AND (SDHI.AgentId = p_AgentId OR IFNULL(p_AgentId, '')='')
    AND (WDHI.AgentId = p_AgentId OR IFNULL(p_AgentId, '')='')
    AND (FH.AgentId = p_AgentId OR IFNULL(p_AgentId, '')='')
    AND (IH.AgentId = p_AgentId OR IFNULL(p_AgentId, '')='');
    
   
    
      
	select SUM(CASE WHEN DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END) INTO v_countOfDispositionResolved
    from temp_AgentDisposition AD
    JOIN disposition_status DS ON AD.dispositionId = DS.did;
    
IF p_AgentId IS NULL THEN 
	DROP TEMPORARY TABLE IF EXISTS temp_AgentAssistMessage;
    CREATE TEMPORARY TABLE temp_AgentAssistMessage AS    
	 select 
		SUM(CASE WHEN IFNULL(AAM.noOfUsedAssistMsg,0) >0 THEN AAM.noOfUsedAssistMsg ELSE 0 END ) as noOfSuggestions,
		SUM(CASE WHEN IFNULL(AAM.totalNoOfassist,0) >0 THEN AAM.totalNoOfassist ELSE 0 END ) as totalNoOfassist,
 		SUM(CASE WHEN IFNULL(AAM.totalLike,0) >0 THEN AAM.totalLike ELSE 0 END ) as totalLike,
         SUM(CASE WHEN IFNULL(AAM.noOfUsedAssistMsg,0) >0 THEN 1 ELSE 0 END ) as countOfSuggestions,
 		SUM(CASE WHEN IFNULL(AAM.totalNoOfassist,0) >0 THEN 1 ELSE 0 END ) as countOfassist
     from tb_chatAgentAssistMessage 			AAM
     where AAM.domainId = p_domainId 
 	and AAM.createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
    and (channelType = v_channel or ifnull(v_channel,'')='');
ELSE
	DROP TEMPORARY TABLE IF EXISTS temp_AgentAssistMessage;
    CREATE TEMPORARY TABLE temp_AgentAssistMessage AS    
	 select 
		SUM(CASE WHEN IFNULL(AAM.noOfUsedAssistMsg,0) >0 THEN AAM.noOfUsedAssistMsg ELSE 0 END ) as noOfSuggestions,
		SUM(CASE WHEN IFNULL(AAM.totalNoOfassist,0) >0 THEN AAM.totalNoOfassist ELSE 0 END ) as totalNoOfassist,
 		SUM(CASE WHEN IFNULL(AAM.totalLike,0) >0 THEN AAM.totalLike ELSE 0 END ) as totalLike,
         SUM(CASE WHEN IFNULL(AAM.noOfUsedAssistMsg,0) >0 THEN 1 ELSE 0 END ) as countOfSuggestions,
 		SUM(CASE WHEN IFNULL(AAM.totalNoOfassist,0) >0 THEN 1 ELSE 0 END ) as countOfassist
     from tb_chatAgentAssistMessage 			AAM
     JOIN tt_AllHistoryId  tt ON AAM.historyId = tt.HistoryId AND AAM.channelType = tt.channelType
     where AAM.domainId = p_domainId 
 	and AAM.createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
    and (AAM.channelType = v_channel or ifnull(v_channel,'')='');
END IF;
    

 
    select 
    CASE WHEN totalNoOfassist = 0 THEN 0 ELSE (noOfSuggestions/totalNoOfassist)*100 END AS usageReport,
    CASE WHEN countOfassist = 0 THEN 0 ELSE (countOfSuggestions/countOfassist)*100 END AS avgHandlingTime,
    CASE WHEN totalNoOfassist = 0 THEN 0 ELSE (totalLike/totalNoOfassist)*100 END AS accuracyReport,
    CASE WHEN countOfassist = 0 THEN 0 ELSE (v_countOfDispositionResolved/countOfassist)*100 END AS FCRContributionReport
    from temp_AgentAssistMessage ASM;
    
 	
 End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_live_dashboard_agent_assistance_teeeest` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_live_dashboard_agent_assistance_teeeest`(
 p_startTmpstmp BIGINT, 
 p_endTmpstmp BIGINT, 
 p_domainId INT,
 p_channel varchar(20),
 p_AgentId	INT
 )
Begin

	DECLARE v_countOfDispositionResolved INT;
	
    DROP TEMPORARY TABLE IF EXISTS temp_AgentDisposition;
    CREATE TEMPORARY TABLE temp_AgentDisposition AS
	select 
			CASE WHEN AAM.channelType='Chat' 	THEN CDH.dispositionId
				 WHEN AAM.channelType='Call' 	THEN CH.dispositionId
				 WHEN AAM.channelType='Email' 	THEN EH.DispositionId
				 WHEN AAM.channelType='Sms' 	THEN EH.dispositionId
				 WHEN AAM.channelType='WhatsApp' THEN EH.dispositionId
				 WHEN AAM.channelType='Facebook' THEN EH.dispositionId
				 WHEN AAM.channelType='Instagram' THEN EH.dispositionId
        ELSE 0 END  as dispositionId
	from tb_chatAgentAssistMessage 			AAM
    left join tb_CallDurationHistory 		CH 		on CH.CallDurationHistoryId 		= AAM.durationHistoryId
    left join tb_ChatDurationHistory 		CDH 	on CDH.ChatDurationHistoryId 		= AAM.durationHistoryId
    left join tb_EmailDurationHistory 		EDHI 	on EDHI.EmailDurationHistoryId 		= AAM.durationHistoryId
	left join tb_EmailHistory 				EH 		on EH.EmailHistoryId 				= EDHI.EmailHistoryId
	left join tb_SMSDurationHistory 		SDHI 	on SDHI.SMSDurationHistoryId 		= AAM.durationHistoryId
    left join tb_SMSHistory 				SH 		on SH.SMSHistoryId 					= SDHI.SMSHistoryId
    left join tb_WhatsappDurationHistory 	WDHI 	on WDHI.WhatsappDurationHistoryId 	= AAM.durationHistoryId
    left join tb_WhatsappHistory 			WH 		on WH.WhatsappHistoryId 			= WDHI.WhatsappHistoryId
    left join tb_FacebookHistory 			FH 		on FH.FacebookHistoryId 			= AAM.historyId
    left join tb_InstagramHistory 			IH 		on IH.InstagramHistoryId 			= AAM.historyId
    where AAM.domainId = p_domainId 
	and AAM.createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
    and (channelType = p_channel or ifnull(p_channel,'ALL')='ALL')
    AND ((IFNULL(p_AgentId, '')='') OR (CDH.AgentId = p_AgentId OR EDHI.AgentId = p_AgentId OR SDHI.AgentId = p_AgentId OR WDHI.AgentId = p_AgentId 
    OR FH.AgentId = p_AgentId OR IH.AgentId = p_AgentId));
      
	select SUM(CASE WHEN DS.dispositionName = 'Resolved' THEN 1 ELSE 0 END) INTO v_countOfDispositionResolved
    from temp_AgentDisposition AD
    JOIN disposition_status DS ON AD.dispositionId = DS.did;
      
	DROP TEMPORARY TABLE IF EXISTS temp_AgentAssistMessage;
    CREATE TEMPORARY TABLE temp_AgentAssistMessage AS
	select 
		SUM(CASE WHEN IFNULL(AAM.noOfUsedAssistMsg,0) >0 THEN AAM.noOfUsedAssistMsg ELSE 0 END ) as noOfSuggestions,
		SUM(CASE WHEN IFNULL(AAM.totalNoOfassist,0) >0 THEN AAM.totalNoOfassist ELSE 0 END ) as totalNoOfassist,
		SUM(CASE WHEN IFNULL(AAM.totalLike,0) >0 THEN AAM.totalLike ELSE 0 END ) as totalLike,
        SUM(CASE WHEN IFNULL(AAM.noOfUsedAssistMsg,0) >0 THEN 1 ELSE 0 END ) as countOfSuggestions,
		SUM(CASE WHEN IFNULL(AAM.totalNoOfassist,0) >0 THEN 1 ELSE 0 END ) as countOfassist
    from tb_chatAgentAssistMessage 			AAM
    left join tb_CallDurationHistory 		CH 		on CH.CallDurationHistoryId 		= AAM.durationHistoryId
    left join tb_ChatDurationHistory 		CDH 	on CDH.ChatDurationHistoryId 		= AAM.durationHistoryId
    left join tb_EmailDurationHistory 		EDHI 	on EDHI.EmailDurationHistoryId 		= AAM.durationHistoryId
	left join tb_EmailHistory 				EH 		on EH.EmailHistoryId 				= EDHI.EmailHistoryId
	left join tb_SMSDurationHistory 		SDHI 	on SDHI.SMSDurationHistoryId 		= AAM.durationHistoryId
    left join tb_SMSHistory 				SH 		on SH.SMSHistoryId 					= SDHI.SMSHistoryId
    left join tb_WhatsappDurationHistory 	WDHI 	on WDHI.WhatsappDurationHistoryId 	= AAM.durationHistoryId
    left join tb_WhatsappHistory 			WH 		on WH.WhatsappHistoryId 			= WDHI.WhatsappHistoryId
    left join tb_FacebookHistory 			FH 		on FH.FacebookHistoryId 			= AAM.historyId
    left join tb_InstagramHistory 			IH 		on IH.InstagramHistoryId 			= AAM.historyId
    where AAM.domainId = p_domainId 
	and AAM.createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
    and (channelType = p_channel or ifnull(p_channel,'ALL')='ALL')
    AND ((IFNULL(p_AgentId, '')='') OR (CDH.AgentId = p_AgentId OR EDHI.AgentId = p_AgentId OR SDHI.AgentId = p_AgentId OR WDHI.AgentId = p_AgentId 
    OR FH.AgentId = p_AgentId OR IH.AgentId = p_AgentId));
    
    select 
    CASE WHEN totalNoOfassist = 0 THEN 0 ELSE (noOfSuggestions/totalNoOfassist)*100 END AS usageReport,
    CASE WHEN countOfassist = 0 THEN 0 ELSE (countOfSuggestions/countOfassist)*100 END AS avgHandlingTime,
    CASE WHEN totalNoOfassist = 0 THEN 0 ELSE (totalLike/totalNoOfassist)*100 END AS accuracyReport,
    CASE WHEN countOfassist = 0 THEN 0 ELSE (v_countOfDispositionResolved/countOfassist)*100 END AS FCRContributionReport
    from temp_AgentAssistMessage ASM;
    
 	
 End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
