/*!50003 DROP PROCEDURE IF EXISTS `ccaas_live_dashboard_customer_satisfaction` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_live_dashboard_customer_satisfaction`(
      	 p_startTmpstmp BIGINT, 
      	 p_endTmpstmp BIGINT, 
      	 p_domainId INT,
      	 p_channel varchar(20)
       )
Begin
       
       
       
	declare v_tcnt 			int;
	DECLARE v_startDate		DATETIME DEFAULT FROM_UNIXTIME(p_startTmpstmp/1000);
	DECLARE v_endDate		DATETIME DEFAULT FROM_UNIXTIME(p_endTmpstmp/1000);
       
      	drop temporary table if exists tt_score ;
      	create temporary table tt_score 
          (
          SentimentalScore varchar(30),
          cnt int
          );      
       
      	 if p_channel in ('ALL', 'Call') then
      		insert into tt_score(SentimentalScore, cnt)
    			select 	sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
    			from 	tb_CallDurationHistory 	CD
    			join 	tb_CallHistory 			CH on CD.CallHistoryId = CH.CallHistoryId
    			where 	CH.domainId = p_domainId 
 
             and 	CH.createdAt between v_startDate and v_endDate
    			and 	SentimentalScore is not null;
      	 End if;
      	 
      	  if p_channel in ('ALL','Chat') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_ChatDurationHistory  CD
              join tb_ChatHistory CH on CD.ChatHistoryId = CH.ChatHistoryId
      		where CH.domainId = p_domainId and CH.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
            
      	 End if;
      	 
      	  if p_channel in ('ALL','SMS') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_SMSHistory  
      		where domainId = p_domainId and createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
            
      	 End if;
      	 
      	 if p_channel in ('ALL', 'Email') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_EmailHistory  
      		where domainId = p_domainId and CreatedAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
      
      	 End if;
      	 
      	 if p_channel in ('ALL', 'Whatsapp') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_WhatsappHistory  
      		where domainId = p_domainId and createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
      
      	 End if;
      	 
      	 if p_channel in ('ALL','Facebook') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_FacebookHistory  
      		where domainId = p_domainId and createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
              
      	 End if;
      	 
      	  if p_channel in ('ALL', 'Instagram') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_InstagramHistory  
      		where domainId = p_domainId and createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
      
      	 End if;
      	 
      	  if p_channel in ('ALL', 'Videomeet') then
      		insert into tt_score(SentimentalScore, cnt)
      		with cte as
      		(
      		select sum(SentimentalScore) as SentimentalScore,count(1) as cnt 
              from tb_VideoDurationHistory  VD
              join tb_VideoHistory VH on VH.VideoHistoryId = VD.VideoHistoryId
      		where VH.domainId = p_domainId and VD.createdAt between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000)
      		and SentimentalScore is not null
      		)
      		select SentimentalScore,cnt from cte;
      
      	 End if; 
         
         select round(sum(SentimentalScore)/sum(cnt)) as scorePercentage from tt_score where cnt>0;
       
 		DROP temporary TABLE IF EXISTS tt_score;
    		
          
    		
          
       End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_live_dashboard_response_rating` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_live_dashboard_response_rating`(
  	p_startTmpstmp BIGINT, 
  	p_endTmpstmp 	BIGINT, 
  	p_domainId 		INT
   ,p_channelType 	VARChar(100)
  )
Begin
  	DECLARE v_tot INT;
    
    
    
     IF p_channelType = "All" THEN 
			SET p_channelType = null ; 
 	END IF;
    
  		drop temporary table if exists tt_resprating ;
  		create temporary table tt_resprating as
  		with ctee as 
  		(SELECT  
			CASE 	WHEN t1.ratingType IN (1,2,3) 	AND t1.satisfactionRate IN (1,2) 	THEN 'NegativeA'
					WHEN t1.ratingType IN (4,5) 	AND t1.satisfactionRate IN (1) 	THEN 'NegativeB'
					WHEN t1.ratingType IN (6,7) 	AND t1.satisfactionRate IN (2) 	THEN 'NegativeC'  
	  
					WHEN t1.ratingType IN (1,2,3) 	AND t1.satisfactionRate IN (3) 	THEN 'NeutralA' 
					WHEN t1.ratingType IN (4,5) 	AND t1.satisfactionRate IN (2) 	THEN 'NeutralB'
					
					WHEN t1.ratingType IN (1,2,3) 	AND t1.satisfactionRate IN (4,5) 	THEN 'PositiveA'
					WHEN t1.ratingType IN (4,5) 	AND t1.satisfactionRate IN (3) 	THEN 'PositiveB'
					WHEN t1.ratingType IN (6,7) 	AND t1.satisfactionRate IN (1) 	THEN 'PositiveC' 
					ELSE 'No vote' END vote
			FROM tb_customerFeedback as t1
			JOIN TypeCode as t2 ON t1.channelTypeId = t2.TypeCodeID 
            WHERE t1.domainId = p_domainId 
				 	AND (t2.TypeCodeName = p_channelType OR IFNULL(p_channelType, '')= '')
					AND t1.createdDate BETWEEN FROM_UNIXTIME(p_startTmpstmp/1000) AND FROM_UNIXTIME(p_endTmpstmp/1000)
  		), ctea as 
  		(	select case when vote like '%Positive%' then 'Positive' 
						when vote like '%Neutral%' then 'Neutral'
						when vote like '%Negative%' then 'Negative' End as result 
  			from ctee
  		)
		SELECT result
			, 	COUNT(1) AS ratings             
		FROM ctea
		GROUP BY result 
		ORDER BY result DESC; 
        
  		select SUM(ratings) into v_tot from tt_resprating where result is not null;
  
  		select result,ratings,ROUND((ratings/v_tot)*100) as percentage from tt_resprating where result is not null;  
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_live_dashboard_survey_response` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_live_dashboard_survey_response`(
	p_startTmpstmp BIGINT, 
	p_endTmpstmp 	BIGINT, 
	p_domainId 		INT
)
Begin

	
	
    DROP TEMPORARY TABLE IF EXISTS temp_customerFeedback;
    CREATE TEMPORARY TABLE temp_customerFeedback AS
	select COUNT(customerFeedbackId) as totalSent
        ,SUM(CASE WHEN IFNULL(satisfactionRate,0) >0 THEN 1 ELSE 0 END ) as responded
        ,SUM(CASE WHEN IFNULL(satisfactionRate,0) >0 THEN 0 ELSE 1 END ) as notResponded
    from tb_customerFeedback 
    where domainId = p_domainId and createdDate between FROM_UNIXTIME(p_startTmpstmp/1000) and FROM_UNIXTIME(p_endTmpstmp/1000);
    
    SELECT 
		totalSent
		,responded
		,notResponded
		,ROUND((responded/totalSent)*100,0) as responsePercentage
    FROM temp_customerFeedback;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
