CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_MergeCustomerContactUpdate_Info`(
 	p_domainId				int											
 	,p_coid 				int                             
 	,p_deleteCoid 			int                             
 	,p_firstName			VARCHAR(250)	                
 	,p_lastName				VARCHAR(250)                    
 	,p_phoneNumber			TEXT                            
 	,p_email				TEXT 							
 	,p_tags					TEXT 
 	,p_location				VARCHAR(100)                    
 	,p_address				VARCHAR(225)                    
 	,p_country				VARCHAR(100)                    
 	,p_state				VARCHAR(100)                    
 	,p_city					VARCHAR(100)                    
 	,p_postalCode			VARCHAR(100)                    
 	,p_facebook				VARCHAR(100)                    
 	,p_instagram			VARCHAR(100)                    
 	,p_whatsapp				VARCHAR(100)                    
 	,p_primaryPhoneNumber	VARCHAR(20)                     
 	,p_primaryEmail			VARCHAR(150)                    
     ,p_blockCustomer		INT
     ,p_blockCustomerReq	INT
 	,p_doNotDisturb			TINYINT							
 	,p_doNotDisturbReq		TINYINT
     ,p_customerType		VARCHAR(255)
 )
Begin
 	declare v_errcode 	int 			default -1;
 	declare v_errmsg 	varchar(100) 	default 'Failure';
     
         
         
 	insert into merge_contact_log
     (p_domainId,p_primarycoid,p_seccoid,p_firstName,p_lastName,p_phoneNumber,p_email,p_tags,p_location,p_address,p_country,p_state,p_city,p_postalCode,p_facebook,p_instagram,p_whatsapp
     ,p_blockCustomer,p_blockCustomerReq,p_doNotDisturb,p_doNotDisturbReq,p_customerType,merged_date)
     values(p_domainId,p_coid,p_deleteCoid,p_firstName,p_lastName,p_phoneNumber,p_email,p_tags,p_location,p_address,p_country,p_state,p_city,p_postalCode,p_facebook,p_instagram,p_whatsapp
     ,p_blockCustomer,p_blockCustomerReq,p_doNotDisturb,p_doNotDisturbReq,p_customerType,now());
         
 	sp_exit :begin
 		if p_coid = 0 or p_deleteCoid = 0 then
 			set v_errcode = -1;
 			set v_errmsg = 'coid should not be zero';
 			leave sp_exit;
 		End if;
         
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		if not exists(select 1 from customer_contact where coid = p_coid and domainId = p_domainId limit 1) then
     			set v_errcode = -1;
                 set v_errmsg = 'primary contact not exists';
                 leave sp_exit;             
     		End if;
             
             if not exists(select 1 from customer_contact where coid = p_deleteCoid and domainId = p_domainId limit 1) then
     			set v_errcode = -1;
                 set v_errmsg = 'Secondary contact not exists';
                 leave sp_exit;
     		End if;    
         
     		if exists(select 1 from tb_CallHistory where CustomerId = p_deleteCoid and domainId = p_domainId limit 1) then
     			update tb_CallHistory 
     				set CustomerId = p_coid
     			where CustomerId = p_deleteCoid;
     		End if;  
             
             if exists(select 1 from tb_ChatHistory where CustomerId = p_deleteCoid and domainId = p_domainId limit 1) then
     			update tb_ChatHistory 
     				set CustomerId = p_coid
     			where CustomerId = p_deleteCoid;
     		End if;  
             
             if exists(select 1 from tb_EmailHistory where CustomerId = p_deleteCoid and domainId = p_domainId limit 1) then
     			update tb_EmailHistory 
     				set CustomerId = p_coid
     			where CustomerId = p_deleteCoid;
     		End if;  
            
            if exists(select 1 from tb_WhatsappHistory where customerId = p_deleteCoid and domainId = p_domainId limit 1) then
     			update tb_WhatsappHistory 
     				set customerId = p_coid
     			where customerId = p_deleteCoid;
     		End if;  
 
            if exists(select 1 from tb_InstagramHistory where customerId = p_deleteCoid and domainId = p_domainId limit 1) then
     			update tb_InstagramHistory 
     				set customerId = p_coid
     			where customerId = p_deleteCoid;
     		End if;  
            
             if exists(select 1 from tb_FacebookHistory where customerId = p_deleteCoid and domainId = p_domainId limit 1) then
     			update tb_FacebookHistory 
     				set customerId = p_coid
     			where customerId = p_deleteCoid;
     		End if;  
     		
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     		
            
            delete from customer_contact where coid = p_deleteCoid and domainId = p_domainId limit 1;
            
            update customer_contact set primaryPhoneNumber = NULL,primaryEmail = NULL ,phoneNumber = null,email = null where coid = p_deleteCoid and domainId = p_domainId;
     
 			update 	customer_contact 
 			set 	firstName				= p_firstName						
 			   ,   	lastName				= p_lastName				
 			   ,    phoneNumber				= p_phoneNumber			
 			   ,    email					= p_email				
 			   ,    tags					= p_tags					
 			   ,    location				= p_location				
 			   ,    address					= p_address				
 			   ,    country					= p_country				
 			   ,    state					= p_state				
 			   ,    city					= p_city					
 			   ,    postalCode				= p_postalCode			
 			   ,    facebook				= p_facebook				
 			   ,    instagram				= p_instagram			
 			   ,    whatsapp				= p_whatsapp				
 			   ,    primaryPhoneNumber		= p_primaryPhoneNumber	
 			   ,    primaryEmail			= p_primaryEmail			
 			   ,    blockCustomer			= p_blockCustomer		
 			   ,    blockCustomerReq		= p_blockCustomerReq			
 			   ,    doNotDisturb			= p_doNotDisturb			
 			   ,    doNotDisturbReq			= p_doNotDisturbReq		
 			   ,    customerType			= p_customerType			
 			where 	coid 				= p_coid 
 			and 	domainId 			= p_domainId;
             
             if row_count()>0 then
     			set v_errcode = 0;
                 set v_errmsg = concat('Contact ',p_deleteCoid,' is merged with ',p_coid);
             End if;
     	end;
         
         select v_errcode as errcode, v_errmsg as errmsg;
         
     End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
