CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_meta_insert_update_whatsapp_company_dtl`(
	p_domainId				int
    ,p_profilePicture		varchar(500)
	,p_businessName			varchar(150)
	,p_planId				int
	,p_isBot				tinyint
	,p_isBotPurchased		tinyint
	,p_whatsappNumber		bigint
	,p_createdBy			bigint
	,p_purchasedat			int
    ,p_aboutBusiness		text
    ,p_businessAddress		varchar(2500)
    ,p_Industry				varchar(100)
    ,p_websiteURL1			varchar(150)
    ,p_websiteURL2			varchar(150)
    ,p_isRegistered			tinyint
    ,p_is2faEnabled			tinyint
    ,p_isVerifiedCode		tinyint
)
begin

	declare v_WhatsappConfigurationId int;
	declare v_errcode int default -1;
	declare v_errmsg varchar(60) default 'insert/update fail';

	select WhatsappConfigurationId into v_WhatsappConfigurationId
    from tb_WhatsappConfiguration
    where domainId = p_domainId;
    
    IF v_WhatsappConfigurationId IS NULL 
    THEN
		insert into tb_WhatsappConfiguration(domainId,profilePicture,businessName,planId,isBot,isBotPurchased,whatsappNumber,createdBy,purchasedat,aboutBusiness,businessAddress,Industry,websiteURL1,websiteURL2,isRegistered,is2faEnabled,isVerifiedCode)
		values(p_domainId,p_profilePicture,p_businessName,p_planId,p_isBot,p_isBotPurchased,p_whatsappNumber,p_createdBy,p_purchasedat,p_aboutBusiness,p_businessAddress,p_Industry,p_websiteURL1,p_websiteURL2,p_isRegistered,p_is2faEnabled,p_isVerifiedCode);
		
		SET v_errcode = 0;
		SET v_errmsg  = 'WhatsappConfiguration inserted successfully';
		
	ELSE
		update tb_WhatsappConfiguration
        set 			
			profilePicture	 	= IFNULL(p_profilePicture,profilePicture)
			,businessName		= IFNULL(p_businessName,businessName)
			,planId				= IFNULL(p_planId,planId)
			,isBot				= IFNULL(p_isBot,isBot)
			,isBotPurchased		= IFNULL(p_isBotPurchased,isBotPurchased)
			,whatsappNumber		= IFNULL(p_whatsappNumber,whatsappNumber)
			,updatedBy			= IFNULL(p_createdBy,updatedBy)
			,purchasedat		= IFNULL(p_purchasedat,purchasedat)
            ,aboutBusiness		= IFNULL(p_aboutBusiness,aboutBusiness)
			,businessAddress	= IFNULL(p_businessAddress,businessAddress)
			,Industry		 	= IFNULL(p_Industry,Industry)
			,websiteURL1		= IFNULL(p_websiteURL1,websiteURL1)
			,websiteURL2		= IFNULL(p_websiteURL2,websiteURL2)
			,isRegistered		= p_isRegistered
			,is2faEnabled		= p_is2faEnabled
			,isVerifiedCode		= p_isVerifiedCode
        WHERE  domainId = p_domainId;
        
        SET v_errcode = 1;
        SET v_errmsg  = 'WhatsappConfiguration update successfully';
	END IF;
    
    select v_errcode as errcode,v_errmsg as errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
