/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_myacc_insert_update_disposition_status`(
	p_Id 						INT,
	p_domainId 					INT,
	p_dispositionName 			VARCHAR(100),
	p_dispositionDescription 	VARCHAR(250),
    p_type						VARCHAR(255),
    p_status 					INT,
	p_colorCode 				VARCHAR(50),
    p_accessType				TINYINT
)
Begin
		declare v_errcode int default -1;
        declare v_errmsg varchar(50) default 'Failure';
        declare v_id int;
        
        sp_exit:begin
        
        if ifnull(p_domainId,0)=0 then
			set v_errcode = -1;
			set v_errmsg = 'Incorrect domainId';
			leave sp_exit;
		End if;
        
         select did into v_id  
         from disposition_status 
         where domainId = p_domainId 
         and did = p_Id limit 1;
         
        IF v_id is null then
        
			INSERT INTO disposition_status (dispositionName, type, description, status, createdAt, updatedAt, domainId, colorCode, accessType)
			VALUES (p_dispositionName, p_type, p_dispositionDescription, p_status, now(), now(), p_domainId, p_colorCode, p_accessType);
			
            set v_id	= last_insert_id();
            
				set v_errcode = 0;
				set v_errmsg = 'Inserted';
        
        Else
        
			if not exists(select 1 from disposition_status where did = p_Id) then
				set v_errcode = -1;
				set v_errmsg = 'Incorrect disposition Id';
                leave sp_exit;
            End if;
            
            if exists(select 1 from disposition_status where did <> p_Id and dispositionName COLLATE utf8mb4_unicode_ci= p_dispositionName and domainId = p_domainId) then
				set v_errcode = -1;
				set v_errmsg = 'Duplicate dispositionName';
                leave sp_exit;
            End if;
        
			update disposition_status
			set dispositionName 	= ifnull(p_dispositionName,dispositionName),
				description	 		= ifnull(p_dispositionDescription,description),
                status 				= ifnull(p_status,status),
                updatedAt 			= now(),
                colorCode 			= ifnull(p_colorCode,colorCode)
            where did 				= v_id;
            
				set v_errcode = 0;
				set v_errmsg = 'Updated';
            
        End if;
        
	End;
        select v_errcode as errcode, v_errmsg as errmsg,v_id as did,p_domainId as domainId,p_dispositionName AS dispositionName,p_dispositionDescription AS description
        ,p_type AS type,p_status AS status,p_colorCode AS colorCode,p_accessType AS accessType;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
