CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_notification_details`(
    uuid varchar(255),
    domainId int,
    toExt int,
    notificationMsg varchar(255),
    markAsRead int,
    timestamp bigint,
    type varchar(255),
    channelType varchar(255),
    coid int,
    customerValue varchar(150))
begin
    
    declare v_errcode int default -1;
    declare v_errmsg varchar(255) default 'Insert Failed';
    
		drop temporary table if exists tt_ext_info;
		create temporary table tt_ext_info
        (
			id int auto_increment primary key,
			toExt int
        );

    if toExt is null then
		insert into tt_ext_info(toExt)
		select Distinct U.ext from tb_User U where U.domainId = domainId and U.roleid in (3,5);
	Else
		insert into tt_ext_info(toExt) values(toExt);
    End if;
        
    	insert into notification (uuid,domainId,toExt,notificationMsg,markAsRead,timestamp,type,channelType,createdAt,updatedAt,coid,customerValue)
        select uuid, domainId, A.toExt, notificationMsg, markAsRead, timestamp, type, channelType, now(), now(), coid, customerValue
        from tt_ext_info A;
    	
		SET v_errcode = 0;
        SET v_errmsg = 'Inserted sucessfully';
        
		delete from notification where createdAt < now() - interval 14 DAY;
     
     select v_errcode AS errcode,v_errmsg as errmsg;
     
    end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_outbound_call_report1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_outbound_call_report1`(
    	p_startTmpstmp 		BIGINT,
    	p_endTmpstmp 		BIGINT,
    	p_timeZone 			VARCHAR(200),
    	p_domainId 			INT,
    	p_queueId 			TEXT,
    	p_agentId 			TEXT,
 	    p_Limit 			INT,	   
      	p_offset 			INT
     )
BEGIN 
     		DECLARE v_offset		INT;
     		DECLARE v_count 		INT; 
            DECLARE v_startTmpstmp BIGINT;
    		DECLARE v_endTmpstmp 	BIGINT;
     
     		SET v_offset =  p_Limit * p_offset;
             
    		IF IFNULL(p_startTmpstmp,0) = 0          
         THEN 	   			
         SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000;    		
         ELSE    			SET v_startTmpstmp = p_startTmpstmp;	           
         END IF; 
            
     		IF IFNULL(p_endTmpstmp,0) = 0 	
            THEN 	
    			SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; 
    		ELSE
    			SET v_endTmpstmp = p_endTmpstmp;
    		END IF;  							
           
   	DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
   	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
   	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
     
       CALL split(p_queueId,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
   	CALL split(p_agentId,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;           
    	    INSERT INTO temp_AvailableDisposition 
    		SELECT 	did 			dispositionId
    			,	dispositionName	DispositionStatus
    		FROM 	disposition_status
    		WHERE 	domainId	= p_domainId;
    		
     		INSERT INTO temp_AvailableDisposition 
     		SELECT 	TypeCodeID		dispositionId
     			,	TypeCodeName	DispositionStatus
     		FROM 	TypeCode
     		WHERE 	TypeGroupID = 1120;      
           
           
   		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
   		CREATE TEMPORARY TABLE temp_AllqueueId
   		
         SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
   		
   		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   		CREATE TEMPORARY TABLE temp_AllagentId
   		select UserID,UserName from tb_User where domainId = p_domainId;  
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
         
    		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
    		CREATE TEMPORARY TABLE temp_sessionHistory AS 
    		SELECT 	CH.sessionStartTime
    			, 	CH.customerNumber
                ,	CH.CustomerId
                ,	Q.queueName							queueName
                ,	U.UserName						    agentName
                , 	CH.callDuration
                ,	CONCAT(c_c.firstName, ' ',c_c.lastName) as customerName
                , 	CDH.dispositionId
                , 	CDH.afterCallWorkTime
                , 	DS.dispositionName  			    AS dispositionStatus               
    		FROM tb_CallHistory		 		CH 
    		JOIN tb_CallDurationHistory		CDH	ON CH.CallHistoryId = CDH.CallHistoryId
    		JOIN temp_AllqueueId			Q	ON CDH.QueueId		= Q.queueId
    		JOIN temp_AllagentId			U	ON U.UserID			= CDH.AgentId   
         JOIN customer_contact		   c_c	ON c_c.coid 		= CH.CustomerId  
             LEFT JOIN disposition_status        DS   ON DS.domainId 		= CH.domainId
											       AND CDH.dispositionId	= DS.did
    		LEFT JOIN temp_queueId 		t_Q ON Q.queueId	COLLATE utf8mb4_0900_ai_ci		= t_Q.queueId 
    		LEFT JOIN temp_agentId 		t_A ON U.UserId COLLATE utf8mb4_0900_ai_ci	= t_A.agentId  
    		WHERE 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp 
            AND 	CH.IsInBound			= 0
    		AND 	CH.domainId 			= p_domainId 		
    		AND 	(IFNULL(p_queueId,'') ='' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
    		AND 	(IFNULL(p_agentId,'') ='' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
    		ORDER BY sessionStartTime DESC LIMIT v_offset, p_limit;	
         
    		SELECT 	count(1) count
    		FROM	temp_sessionHistory;
 
   		SELECT * from temp_AllqueueId;
   		SELECT * from temp_AllagentId;
   		SELECT * from temp_AvailableDisposition;
           
              
    		SELECT  e.sessionStartTime 						as `date`
    			,	e.customerNumber
 		 	,	e.customerName
    	 		,	e.queueName 							as queueName
    		 	,	e.agentName 							as agentName
    		 	,  	e.callDuration 							as callDuration
    			,	e.afterCallWorkTime  					as ACW
    		 	,	e.callDuration  						as totalDuration    
                ,   e.DispositionStatus
    		FROM  	temp_sessionHistory 		e;
 		
  
    end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_outbound_call_report_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_outbound_call_report_1`(
   	p_startTmpstmp 		BIGINT,
   	p_endTmpstmp 		BIGINT,
   	p_timeZone 			VARCHAR(200),
   	p_domainId 			INT,
   	p_queueId 			TEXT,
   	p_agentId 			TEXT,
    	p_Limit 			INT	,   
  	p_offset 			INT
 
    )
BEGIN 
    		DECLARE v_offset		    INT;
    		DECLARE v_count 		    INT; 
           DECLARE v_startTmpstmp    BIGINT;
   		DECLARE v_endTmpstmp 	    BIGINT;
    
    		SET v_offset =  p_Limit * p_offset;
            
   		IF IFNULL(p_startTmpstmp,0) = 0 
           THEN 	
   			SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000; 
   		ELSE 
   			SET v_startTmpstmp = p_startTmpstmp;	
           END IF; 
           
    		IF IFNULL(p_endTmpstmp,0) = 0 	
           THEN 	
   			SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; 
   		ELSE
   			SET v_endTmpstmp = p_endTmpstmp;
   		END IF;  							
          
  	DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
  	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
  	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
    
      CALL split(p_queueId,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
  	CALL split(p_agentId,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
          
   	    INSERT INTO temp_AvailableDisposition 
   		SELECT 	did 			dispositionId
   			,	dispositionName	DispositionStatus
   		FROM 	disposition_status
   		WHERE 	domainId	= p_domainId;
   		
   		INSERT INTO temp_AvailableDisposition 
   		SELECT 	TypeCodeID		dispositionId
   			,	TypeCodeName	DispositionStatus
   		FROM 	TypeCode
   		WHERE 	TypeGroupID = 1120;      
          
          
  		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
  		CREATE TEMPORARY TABLE temp_AllqueueId
  		select qid,name as queueName from queue where domainId = p_domainId;
  		
  		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  		CREATE TEMPORARY TABLE temp_AllagentId
  		select UserID,UserName from tb_User where domainId = p_domainId;  
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;                                             
   		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
   		CREATE TEMPORARY TABLE temp_sessionHistory as 
   		SELECT 	CH.sessionStartTime
   			, 	CH.customerNumber
 			,	CH.CustomerId
 			,	Q.name							queueName
 			,	U.UserName						agentName
 			, 	CH.callDuration
 			, 	CDH.dispositionId
 			, 	CDH.afterCallWorkTime
 			 ,	t_AD.DispositionStatus
 			,	CONCAT(c_c.firstName, ' ',c_c.lastName) as customerName
   		FROM tb_CallHistory		 		CH 
   		JOIN tb_CallDurationHistory		CDH	ON CH.CallHistoryId = CDH.CallHistoryId
   		JOIN queue						Q	ON CDH.QueueId		= Q.qid
   		JOIN tb_User					U	ON U.UserID			= CDH.AgentId        
 		LEFT JOIN temp_queueId 		    t_Q ON Q.qid	COLLATE utf8mb4_0900_ai_ci		= t_Q.queueId 
 		LEFT JOIN temp_agentId 		    t_A ON U.UserId COLLATE utf8mb4_0900_ai_ci	= t_A.agentId    
 		LEFT JOIN customer_contact	    c_c	ON c_c.coid 			= CH.CustomerId  
         LEFT JOIN 	temp_AvailableDisposition	t_AD	ON t_AD.dispositionId	= CDH.dispositionId   
   		WHERE 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp 
 			AND 	CH.IsInBound			= 0
 			AND 	CH.domainId 			= p_domainId 		
 			AND 	(IFNULL(p_queueId,'') ='' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
 			AND 	(IFNULL(p_agentId,'') ='' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
 			ORDER BY sessionStartTime DESC;
 		
 
   		SELECT 	count(1) count
   		FROM	temp_sessionHistory;
          
  		SELECT * from temp_AllqueueId;
  		SELECT * from temp_AllagentId;
  		SELECT * from temp_AvailableDisposition;
   
              
   		SELECT  e.sessionStartTime 						AS `date`
   			,	e.customerNumber
 			,	e.customerName
   			,	e.queueName 							AS queueName
   			,	e.agentName 							AS agentName
   			,  	e.callDuration 							AS callDuration
 			,	e.DispositionStatus
   			,	e.afterCallWorkTime  					AS ACW
   			,	e.callDuration  						AS totalDuration          
   		FROM  	temp_sessionHistory 		e
 			  LIMIT v_offset, p_limit;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
