DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_prequery_info111`(
    	 p_cli varchar(20), 
    	 p_ddi varchar(20), 
    	 p_domain_id int    
     )
sp_return: Begin  	
		DECLARE v_jsoncol			JSON;
		DECLARE v_customerNumber	BIGINT; 
		DECLARE v_ext				SMALLINT;
		DECLARE v_autoAttendant		SMALLINT;	
		DECLARE v_greetingMessage	TEXT;
		DECLARE v_coid				BIGINT;
		DECLARE v_assistPriority	TINYINT;
		DECLARE	v_status			TINYINT;
		DECLARE	v_domainId			INT;

		DECLARE	v_isVoice 			INT;
		DECLARE	v_isInbound 		INT;
		DECLARE	v_isOutbound 		INT;
		DECLARE	v_voiceText 		TEXT;
		DECLARE	v_voiceUrl 			TEXT;
		DECLARE	v_playFormat 		INT;
        
		DECLARE v_csatstatus 		INT;
		DECLARE v_play_prompt 		TEXT;
		DECLARE v_dtmf 				VARCHAR(50);
		DECLARE v_invalid_input 	TEXT;
		DECLARE v_minimum_duration 	INT;
     
		SELECT 	domainId INTO v_domainId
		FROM 	did_purchase
		WHERE	your_number = p_ddi;

       	IF length(p_cli)  > 5 
       	THEN
       		SET v_customerNumber = p_cli;		
       	ELSE 
       		SET v_ext = p_cli;		
       		SET v_customerNumber = p_ddi;		
       	END IF;     
           
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
       SELECT 	`status` INTO v_status
       FROM 	did_purchase
       WHERE 	domainId	= p_domain_id
       AND 	your_number = p_ddi; 
               
		select 	status, greetingMessage, assistPriority  into v_autoAttendant, v_greetingMessage, v_assistPriority  
		from 	call_configuration 
		where 	contactCenterNumber = p_ddi
		AND 	domainId			= p_domain_id;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       
    	if v_autoAttendant = 1 then
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		SELECT isBot into v_autoAttendant FROM did_purchase where your_number = p_ddi;
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
        end if;
        
 	select isVoice,isInbound,isOutbound,voiceText,voiceUrl, case when isVoiceTextToSpeech = 1 and isVoiceSelectPrompt = 0 then 1 
 																 when isVoiceSelectPrompt = 1 and isVoiceTextToSpeech = 0 then 2
                                                                  else 0 end as playFormat
     into v_isVoice,v_isInbound,v_isOutbound,v_voiceText,v_voiceUrl,v_playFormat
     from ccaas_settings_voice_video_recording_dtl
 	where domainId = p_domain_id;
             
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    	SELECT 	coid INTO v_coid
    	FROM 	customer_contact
    	WHERE 	primaryPhoneNumber	= v_customerNumber
    	AND 	domainId			= p_domain_id
    	ORDER BY coid LIMIT 1;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    	IF v_coid IS NULL
    	THEN
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		SELECT 	coid INTO v_coid
    		FROM 	customer_contact
    		WHERE 	phoneNumber	LIKE CONCAT('%',v_customerNumber,'%')
    		AND 	domainId	= p_domain_id
    		ORDER BY coid LIMIT 1;
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    	END IF;
        
        select isVoice, minimumDuration, 
        case	when ratingDesignType in (1,2,3) then '[1,2,3,4,5]' 
				when ratingDesignType in (4,5) then '[1,2,3]'
                when ratingDesignType in (6,7) then '[1,2]' end, 
        case 	when ratingDesignType in (1,2,3) then 'On a scale of 1 to 5, with 1 being extremely unsatisfied and 5 being very satisfied, how would you rate your satisfaction with the service you received today? Press 1 for Extremely Unsatisfied, Press 2 for Unsatisfied, Press 3 for Neutral, Press 4 for Satisfied, Press 5 for Very Satisfied' 
				when ratingDesignType in (4,5) then 'On a scale of 1 to 3, with 1 being extremely unsatisfied and 3 being very satisfied, how would you rate your satisfaction with the service you received today? Press 1 for Unsatisfied, Press 2 for Neutral, Press 3 for Satisfied'
                when ratingDesignType in (6,7) then 'On a scale of 1 to 2, with 1 being extremely unsatisfied and 2 being very satisfied, how would you rate your satisfaction with the service you received today? Press 1 for Unsatisfied, Press 2 for Satisfied' end, 
		 case	when ratingDesignType in (1,2,3) then 'It seems like you entered an invalid option. Please try again. On a scale of 1 to 5, with 1 being extremely unsatisfied and 5 being very satisfied, how would you rate your satisfaction with the service you received today?  Press 1 for Extremely Unsatisfied, Press 2 for Unsatisfied, Press 3 for Neutral, Press 4 for Satisfied, Press 5 for Very Satisfied' 
				when ratingDesignType in (4,5) then 'It seems like you entered an invalid option. Please try again.On a scale of 1 to 3, with 1 being extremely unsatisfied and 3 being very satisfied, how would you rate your satisfaction with the service you received today? Press 1 for Unsatisfied, Press 2 for Neutral, Press 3 for Satisfied'
                when ratingDesignType in (6,7) then 'It seems like you entered an invalid option. Please try again.On a scale of 1 to 2, with 1 being extremely unsatisfied and 2 being very satisfied, how would you rate your satisfaction with the service you received today? Press 1 for Unsatisfied, Press 2 for Satisfied' end
        into v_csatstatus, v_minimum_duration, v_dtmf,v_play_prompt,v_invalid_input 
        from tb_ccaas_customerSatisfactionRatingDesign where domainId = p_domain_id;

          	SELECT 	JSON_OBJECT("cli_block",IFNULL(CUST.blockCustomer,0) ,'firstName',ifnull(CUST.firstName,''),'lastName',ifnull(CUST.lastName,'')
					,'autoAttendant',ifnull(v_autoAttendant,0),'greetingMessage',ifnull(v_greetingMessage,''), 'assistPriority',IFNULL(v_assistPriority,0)
                    ,'status',IFNULL(v_status,1),'domainId',IFNULL(v_domainId,0),'isVoice',IFNULL(v_isVoice,0)
					,'recording',(SELECT JSON_OBJECT("isInbound",IFNULL(v_isInbound,0),'isOutbound',IFNULL(v_isOutbound,0),'voiceText',IFNULL(v_voiceText,0),'voiceUrl',IFNULL(v_voiceUrl,0),'playFormat',IFNULL(v_playFormat,0)))
                    ,'csat',(SELECT JSON_OBJECT("status",IFNULL(v_csatstatus,0),'play_promt',IFNULL(v_play_prompt,0),'dtmf',IFNULL(v_dtmf,0),'invalid_input',IFNULL(v_invalid_input,0),'minimum_duration',IFNULL(v_minimum_duration,0),'Thanks Note','Thank you for your feedback. It helps us improve our service.'))
                    )
			
          	INTO 	v_jsoncol
          	FROM 	customer_contact CUST
          	WHERE 	coid = v_coid;
            
           	IF v_ext IS NOT NULL 
           	THEN
           		SET v_jsoncol = JSON_MERGE(	v_jsoncol,
           									(SELECT JSON_OBJECT("agent_name",U.UserName
           														,"userId",CAST(U.UserID as CHAR(50))
                                                                   ,"email",U.emailId) AgentDetails	    
           									FROM 	tb_User U                                    
           									WHERE  	domainId 	= p_domain_id
           									AND 	ext			= v_ext));
           	END IF;
           	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
              
        	IF v_jsoncol IS NULL
        	THEN
        		SET v_jsoncol = JSON_OBJECT("cli_block",0 ,'firstName','','lastName','','autoAttendant',ifnull(v_autoAttendant,0),'greetingMessage', ifnull(v_greetingMessage,'')
      									,'assistPriority',IFNULL(v_assistPriority,0)
                                        ,'status',IFNULL(v_status,1)
                                        ,'domainId',IFNULL(v_domainId,0)
                                        ,'isVoice',IFNULL(v_isVoice,0)
                                        ,'recording',(SELECT JSON_OBJECT("isInbound",IFNULL(v_isInbound,0),'isOutbound',IFNULL(v_isOutbound,0),'voiceText',IFNULL(v_voiceText,0),'voiceUrl',IFNULL(v_voiceUrl,0),'playFormat',IFNULL(v_playFormat,0)))
                                        ,'csat',(SELECT JSON_OBJECT("status",IFNULL(v_csatstatus,0),'play_promt',IFNULL(v_play_prompt,0),'dtmf',IFNULL(v_dtmf,0),'invalid_input',IFNULL(v_invalid_input,0),'minimum_duration',IFNULL(v_minimum_duration,0),'Thanks Note','Thank you for your feedback. It helps us improve our service.'))
                                        );
        	END IF;    
              
      	SELECT v_jsoncol AS jsoncol;
   End ;;
DELIMITER ;
