CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_queueAnalytics_outbound_voice_heatMap`(
	 p_domainId			INT
	,p_startTmpstmp 	DATE
	,p_endTmpstmp 		DATE
	,p_datetype			TINYINT 
    ,p_queueId			VARCHAR(500)
)
begin
          
        DECLARE v_startDateTime			DATETIME;
    	DECLARE v_endDateTime			DATETIME;     
         
    	DECLARE v_startTimestamp		BIGINT;
    	DECLARE v_endTimestamp			BIGINT;
                
        DROP TEMPORARY TABLE IF EXISTS tmp_result;
    	CREATE TEMPORARY TABLE tmp_result(
			DayName			VARCHAR(15)
    		,startDateTime		DATETIME
    		,endDateTime		DATETIME
    		,Count				INT
    	);   
        
        DROP TEMPORARY TABLE IF EXISTS tt_queueIdSplit;
        CREATE TEMPORARY TABLE tt_queueIdSplit (tt_queueId INT);
        CALL Split(p_queueId, ',');
        INSERT INTO tt_queueIdSplit(tt_queueId)
        SELECT items FROM tt_Split_temptable;
        
           
        
		SET v_startDateTime = p_startTmpstmp; 
		SET v_endDateTime 	= DATE_ADD(DATE_ADD(p_endTmpstmp,INTERVAL 1 DAY),INTERVAL -1 MINUTE);  
		
        SET SESSION cte_max_recursion_depth = 4000; 
        
		IF p_datetype = 1 
		THEN       
			DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
			CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
				WITH RECURSIVE CTE_TIMINGS AS (
					SELECT 	v_startDateTime AS startDateTime, DATE_ADD(v_startDateTime,INTERVAL 59 MINUTE) AS endDateTime
					UNION ALL
					SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
					FROM 	CTE_TIMINGS
					WHERE 	endDateTime < v_endDateTime
			)
			SELECT * FROM CTE_TIMINGS;	
		ELSE 	
			DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
			CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
				WITH recursive CTE_TIMINGS AS (
					SELECT 	v_startDateTime AS startDateTime, DATE_ADD(v_startDateTime,INTERVAL 1439 MINUTE ) AS endDateTime
					UNION ALL
					SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
					FROM 	CTE_TIMINGS
					WHERE 	startDateTime < v_endDateTime
				)
				SELECT * FROM CTE_TIMINGS;	
		END IF;  
      
        ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
         UPDATE tmp_timings
         SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
     		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
             
     	SET v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
    	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
                
        	

		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory;
		CREATE TEMPORARY TABLE temp_CallHistory AS
		SELECT 	CH.CallHistoryId
				,CH.sessionStartTime
				,CH.sessionEndTime
				,CH.domainId
		FROM 	tb_CallHistory 	CH
        JOIN 	tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
		WHERE 	CH.domainId = p_domainId
		AND 	CH.sessionStartTime BETWEEN v_startTimestamp AND v_endTimestamp
        AND 	((CDH.QueueId in (SELECT tt_queueId FROM tt_queueIdSplit ))OR IFNULL(p_queueId,0)=0)
        AND		CH.IsInBound = 0;

          
                
        DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal;
		CREATE TEMPORARY TABLE temp_CallHistory_cal AS
		SELECT   count(DISTINCT CallHistoryId) as totalCall
				,sessionStartTime
        FROM 	temp_CallHistory 
		WHERE 	sessionStartTime BETWEEN v_startTimestamp AND v_endTimestamp
        GROUP BY sessionStartTime;
        
        
 
		INSERT INTO tmp_result
		SELECT 	DAYNAME(t_T.startDateTime ) as DName
			,	t_T.startDateTime 
			,	t_T.endDateTime
			,	IFNULL(SUM(totalCall),0) AS 'Total Call'
		FROM 	tmp_timings		t_T	
		LEFT JOIN 	temp_CallHistory_cal CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp AND v_endTimestamp		
		GROUP BY t_T.startDateTime, t_T.endDateTime;
		
        
        
        DROP TEMPORARY TABLE IF EXISTS tt_totalDayCount; 
        CREATE TEMPORARY TABLE tt_totalDayCount AS
		SELECT count(DISTINCT DayName) AS totalCount,DayName 
        FROM tmp_result 
        GROUP BY DayName,CAST(startDateTime AS DATE);
		
		DROP TEMPORARY TABLE IF EXISTS tt_totalDayCount_cal;
		CREATE TEMPORARY TABLE tt_totalDayCount_cal (
         DayName VARCHAR(15)
        ,count INT
        );
        
        INSERT INTO tt_totalDayCount_cal (DayName, count)
		SELECT     	DayName, 
					SUM(totalCount) AS count
		FROM     	tt_totalDayCount
		GROUP BY     DayName;
         
        
		
		DROP TEMPORARY TABLE IF EXISTS tt_timeSplit; 
		CREATE TEMPORARY TABLE tt_timeSplit AS 
		SELECT DayName,DATE_FORMAT(startDateTime,'%H:%i') AS startDateTime,DATE_FORMAT(endDateTime,'%H:%i') AS endDateTime,Count 
        FROM tmp_result;
        
       DROP TEMPORARY TABLE IF EXISTS tt_timeSplit_final; 
		CREATE TEMPORARY TABLE tt_timeSplit_final AS 
        SELECT tt.DayName,startDateTime,endDateTime,SUM(CASE WHEN tt.Count > 0 THEN tt.Count ELSE 0 END) as Count,tdf.count as ttcount
        FROM tt_timeSplit tt
        JOIN tt_totalDayCount_cal tdf ON tt.DayName = tdf.DayName
        GROUP BY tt.DayName,startDateTime,endDateTime,tdf.count;

        DROP TEMPORARY TABLE IF EXISTS tt_timeSplit_final_result; 
		CREATE TEMPORARY TABLE tt_timeSplit_final_result AS 
        SELECT DayName,startDateTime,endDateTime,SUM(CASE WHEN Count > 0 THEN (Count/ttcount) ELSE 0 END) as Count
        FROM tt_timeSplit_final 
        GROUP BY DayName,startDateTime,endDateTime,ttcount;
                
        SELECT DayName,startDateTime,endDateTime,ROUND(Count) as Count FROM tt_timeSplit_final_result;
        
       SELECT 'call' AS ChannelName;
        
        SELECT Count FROM tmp_result ORDER BY Count ASC ;
        
		SELECT ROUND(Count) as Count
        FROM tt_timeSplit_final_result
		ORDER BY Count ASC ; 

end ;;
DELIMITER ;
