CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_queue_delete_by_qid`(
	p_qid					int
)
begin
			declare v_qid int;
            declare v_errcode int default -1;
			declare v_errmsg varchar(50) default 'Failure';
            
            select qid into v_qid
            from queue
            where qid = p_qid;
            
	IF v_qid IS NOT NULL
	THEN            

		DELETE FROM queue WHERE qid = v_qid;

		SET v_errcode = 0;
		SET v_errmsg = 'Deleted';
	END IF;
           select v_errcode as errcode, v_errmsg as errmsg, v_qid as qid; 
end ;;
DELIMITER ;
