CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_queue_Weigh_get_Time_details`()
begin
   	
       declare json text default '';
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   			select JSON_ARRAYAGG(json_object('qid',a.qid,
   											'queueName',a.queueName,
   											'queueType',a.queueType,
   											'domainId',a.domainId,
   											'queueList',queueList,
   											'createdAt',a.createdAt)) into json 
               from queueWeighTime a; 
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     select json; 
   
   end ;;
DELIMITER ;
