CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_queue_Weigh_Time_details`(
    qid int,
    queueName varchar(255),
    queueType varchar(255),
    domainId int,
    queueList text)
begin
    
    declare errcode int default -1;
    declare errmsg 	varchar(255) default 'failure'; 
    declare v_qwtId	int;
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    select 	qwtId
    INTO 	v_qwtId
    from 	queueWeighTime a 
    where 	a.qid 		= qid 
    and 	a.domainId 	= domainId 
    and 	a.queueType = queueType COLLATE utf8mb4_unicode_ci limit 1;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    sp_exit : begin
    if v_qwtId IS NULL 
    then  
    	insert into queueWeighTime (qid,queueName,queueType,domainId,queueList,createdAt,updatedAt)
    	values (qid,queueName,queueType,domainId,queueList,now(),now());
    
    	if row_count()>0
    	then 
   		set errcode = 0;
   		set errmsg = 'inserted successfully';
   		leave sp_exit;
    	end if;    
    else
		update 	queueWeighTime a
		set 	a.queueList = queueList COLLATE utf8mb4_unicode_ci
		where 	a.qwtId 	= v_qwtId;
  
    	if row_count()>0
    	then 
    		set errcode = 0;
    		set errmsg = 'updated successfully';
            leave sp_exit;
    	end if;	
        
    end if;
    
    end sp_exit;
    
    select errcode as errcode,errmsg as errmsg;
    
    end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
