DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_remove_custom_report_sharedContact`(
	 p_reportId		INT 
    ,p_agentId		INT

)
begin

	DECLARE v_reportId INT;
	DECLARE v_errcode INT DEFAULT -1;
	DECLARE v_errmsg VARCHAR(500) DEFAULT 'Report contact removed/add failed';
	
    SELECT reportId 
    INTO v_reportId
    FROM tb_custom_report_dtl WHERE reportId = p_reportId;
    
    IF v_reportId IS NOT NULL
    THEN
            
		UPDATE tb_custom_report_dtl
		SET agentId = TRIM(BOTH ',' FROM REGEXP_REPLACE(
			REPLACE(CONCAT(',', agentId, ','), p_agentId , ','), 
			',+', ','
		))
		WHERE FIND_IN_SET(p_agentId, agentId)
        AND reportId = v_reportId;

		SET v_errcode 	= 0;
		SET v_errmsg 	= 'Report contact removed/add successfully';
    END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;

end ;;
DELIMITER ;
