CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_schedule_report_dtl`(
		 p_sid					INT
		,p_domainId				INT 
		,p_schedule_data		JSON
		,p_isActive				TINYINT(1)
		,p_schedule_time		TIME
		,p_trigger_mail_id 		VARCHAR(1000)
		,p_trigger_type 		VARCHAR(15)
)
begin
		DECLARE v_errcode 	INT DEFAULT -1;
		DECLARE v_errmsg 	VARCHAR(50) DEFAULT 'Insert / Update Failure';
		DECLARE v_sid 		INT;
    
		SELECT sid INTO v_sid
		FROM tb_schedule_report_dtl
		WHERE domainId 	= p_domainId
		AND sid 		= p_sid;
      
	IF v_qid IS NULL
	THEN 
    
			INSERT INTO tb_schedule_report_dtl(domainId, schedule_data, isActive, schedule_time, trigger_mail_id, trigger_type, createdAt, updatedAt) 
			VALUES (p_sid,p_domainId,p_schedule_data,p_isActive,p_schedule_time,p_trigger_mail_id,p_trigger_type, NOW(), NOW())	;		
            
			SET v_errcode = 0;
			SET v_errmsg = 'Inserted successfully';
    ELSE 
			
			UPDATE tb_schedule_report_dtl
			SET schedule_data		= IFNULL(p_schedule_data,schedule_data)
			,isActive				= IFNULL(p_isActive,isActive)
			,schedule_time			= IFNULL(p_schedule_time,schedule_time)
			,trigger_mail_id		= IFNULL(p_trigger_mail_id,trigger_mail_id)
			,trigger_type			= IFNULL(p_trigger_type,trigger_type)
			,updatedAt				= NOW()
		WHERE sid = v_sid;
    
		SET v_errcode = 1;
		SET v_errmsg = 'Updated successfully';
  
	END IF;
		select v_errcode as errcode, v_errmsg as errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
