CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_siptrunkMapNumberDelete`(  
  p_domainId int,
  p_did_number varchar(20)
  )
Begin
  
  	declare v_errcode int default -1;
  	declare v_errmsg varchar(100) default 'Not found';
  	sp_exit:begin
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		if not exists(select 1 from did_purchase where domainId = p_domainId and your_number = p_did_number limit 1)
        then
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  			set v_errcode = -1;
  			set v_errmsg = 'Did number not found';
  			leave sp_exit;
  		End if;
          
          delete from did_purchase where domainId = p_domainId and your_number = p_did_number limit 1;
          
  			set v_errcode = 0;
  			set v_errmsg = 'Did number is removed';
  
  	end;
  	select v_errcode as errcode, v_errmsg as errmsg;
  End ;;
DELIMITER ;
