CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_StatusIdStateTimer`(
 p_ext INT,
 p_domainId INT,
 p_statusName VARCHAR(100),
 p_stateTimer VARCHAR(50)
 )
begin
 	DECLARE v_errcode 	INT;
     DECLARE v_errmsg	VARCHAR(50);
     DECLARE v_StatusID	INT	;
     DECLARE v_curDate   DATETIME;
     
     SET	v_curDate = now();
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;     
     select 	aid INTO v_StatusID
     from 	agent_status	
     where 	statusName		= p_statusName
     and 	domainId		= p_domainId ;
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
 	UPDATE 	tb_User 	
 	SET 	StatusID 	= v_StatusID
 		, 	stateTimer 	= p_stateTimer 
         ,	updatedAt	= v_curDate
 	where 	domainId 	= p_domainId
     and 	ext			= p_ext;
 	
 	IF ROW_COUNT() > 0 THEN
 		SET v_errcode = 0;
 		SET v_errmsg = 'updated successfully';
 	END IF; 
         
     select v_errcode as errcode, v_errmsg as errmsg; 
 
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
