CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_tpi_get_customer_conatct_details`(
       p_coid 	INT,
       p_domainId  INT
	)
begin
			SELECT	accountNumber,
					address,
					attachments,
					blockCustomer, 
					blockCustomerReq,
					blockedBy, 
					blockedReqBy, 
					city,
					coid    , 
					cookiesId, 
					country,
					createdAt, 
					currentCustomerNumber,
					customerType, 
					CustomerUniqueId, 
					doNotDisturb,
					doNotDisturbBy,
					doNotDisturbReq,
					doNotDisturbReqBy,
					email, 
					facebook, 
					firstName, 
					instagram,
					lastName, 
					location,
					mergeCustomer,
					phoneNumber,
					postalCode, 
					primaryEmail,
					primaryPhoneNumber,
