CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_updateAgentStatus`(
 	p_domainId 			INT,
 	p_ext 				INT,
 	p_currentSessionId 	VARCHAR(100)
   )
begin  
   	DECLARE v_errcode 			INT DEFAULT 0;
 	DECLARE v_errmsg			VARCHAR(50) DEFAULT 'No Update';
     DECLARE v_currentSessionId 	VARCHAR(100);
     DECLARE v_UserID			BIGINT;    
     
     START TRANSACTION;
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	currentSession, UserID INTO v_currentSessionId, v_UserID       
     FROM 	tb_User 
     WHERE 	domainId 	= p_domainId 
     AND 	ext 		= p_ext;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
       
 	IF v_currentSessionId <> p_currentSessionId 
     THEN
 		UPDATE 	tb_User 
 		SET 	currentSession = p_currentSessionId 
 		WHERE 	UserID = v_UserID;
 		
 		SET v_errcode = 0;
 		SET v_errmsg = 'updated successfully';		
 	END IF;
    
    COMMIT;
          
 	SELECT v_errcode as errcode, v_errmsg as errmsg;     
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
