CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_updateCallAnsweredDuration`(
      p_CallHistoryId          BIGINT,
      p_domainId               INT,
      p_AgentId                BIGINT,
      p_answeredDuration       BIGINT
 )
BEGIN
     DECLARE v_errcode INT;
     DECLARE v_errmsg VARCHAR(50);
 
     UPDATE tb_CallHistory CH
     JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
     SET CDH.answeredDuration = p_answeredDuration
     WHERE CDH.CallHistoryId = p_CallHistoryId
       AND CDH.AgentId = p_AgentId    
       AND CH.domainId = p_domainId;
 
 
     IF ROW_COUNT() > 0 THEN
         SET v_errcode = 0;
         SET v_errmsg = 'Updated Successfully';
     ELSE
         SET v_errcode = -1;
         SET v_errmsg = 'Not Updated';
     END IF;
 
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
