CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_updateCallConfigStatus`(
 p_contactCenterNumber bigint,
 p_domainId int,
 p_status	tinyint
 )
begin
 
 declare v_errcode int;
 declare v_errmsg varchar(50);
 
 update call_configuration
 set `status` = p_status
 where contactCenterNumber = p_contactCenterNumber
 and domainId = p_domainId;
 
 update did_purchase
 set `status` = p_status
 where your_number = p_contactCenterNumber
 and domainId = p_domainId;
 
 if row_count()
 then
 set v_errcode = 0;
 set v_errmsg = 'Updated Successfully';
 else 
 set v_errcode = -1;
 set v_errmsg = 'Not Updated';
 end if;
 select v_errcode as errcode , v_errmsg as errmsg;
 
 end ;;
DELIMITER ;
