CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_UpdateCalledPersonDetails`(
 p_coid 		int
 ,p_domaind 	int
 ,p_sessionId 	varchar(250)
)
BEGIN 
 	UPDATE 	tb_CallHistory 
    SET 	CustomerId 	= p_coid 
    WHERE 	domainId 	= p_domaind 
    AND 	sessionId 	= p_sessionId; 
END ;;
