CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_UpdateCallQueueId_info`(
	p_sessionId varchar(250),
    p_domainId int,
    p_QueueId int,
	p_extn bigint
)
Begin

		declare v_CallHistoryId bigint;
		declare v_curDate		datetime;
        declare v_errcode 		int;
		declare v_errmsg 		varchar(55);
        declare p_AgentId		bigint;
        

		set v_curDate = now();
        
        if p_extn is not null then
			select  UserID into p_AgentId from tb_User where domainId = p_domainId and ext = p_extn limit 1;
        End if;

		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;            
		SELECT 	CallHistoryId into v_CallHistoryId
		FROM 	tb_CallHistory
		WHERE	sessionId	= p_sessionId and domainId = p_domainId;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 

		update tb_CallDurationHistory b 
			   set b.QueueId 		= ifnull(p_QueueId,b.QueueId)
               ,b.updatedAt 		= v_curDate
               ,b.AgentId			= ifnull(p_AgentId,b.AgentId)
		where b.CallHistoryId 		= v_CallHistoryId;
    
		if found_rows()>0 then
			set v_errcode = 0;
			set v_errmsg = 'updated successfully';
		end if;
		
               
		select v_errcode as errcode, v_errmsg as errmsg;

End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
