DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_UpdateChatSessionDisposition_details`(
         p_ChatDurationHistoryId	BIGINT,
         p_domainId 				INT,
         p_summary 					TEXT,
         p_dispositionId 			INT,
         p_afterChatWorkTime 		INT,
         p_markAsRead 				INT,
         p_agentOccupyDetails		JSON ,
         p_subject					VARCHAR(250),
         p_tags						JSON
       )
Begin  
       	DECLARE v_errcode 		INT default -1;
       	DECLARE v_errmsg 		VARCHAR(50) DEFAULT 'Error : Not Updated';   	
       	DECLARE v_CurDate		DATETIME;
      	DECLARE v_ChatHistoryId	BIGINT;
		DECLARE v_AgentId		INT;
           
      	SET v_CurDate = NOW();
           
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
      	SELECT 	ChatHistoryId, AgentId	
         INTO 	v_ChatHistoryId, v_AgentId
      	FROM 	tb_ChatDurationHistory
      	WHERE 	ChatDurationHistoryId = p_ChatDurationHistoryId
      	LIMIT 1;  
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
         
         IF EXISTS (	SELECT 	1
  					FROM 	tb_ChatHistory
  					WHERE 	ChatHistoryId 	= v_ChatHistoryId
                     AND 	CallBackStatus	= 1)
  		THEN
  			UPDATE 	tb_ChatHistory
  			SET 	CallBackStatus	= 0
  			WHERE 	ChatHistoryId 	= v_ChatHistoryId;		
  		END IF;
     
  		UPDATE tb_ChatDurationHistory
  		SET  dispositionId 			= IFNULL(p_dispositionId ,dispositionId)
  			,Summary 			    = IFNULL(p_summary,Summary)
  			,afterChatWorkTime 		= IFNULL(p_afterChatWorkTime,afterChatWorkTime)
  			,markAsRead 			= IFNULL(p_markAsRead,markAsRead)
  			,tags 					= IFNULL(p_tags,tags)
  			,updatedAt				= v_CurDate
  		WHERE ChatDurationHistoryId = p_ChatDurationHistoryId; 
 	    
		UPDATE 	tb_ChatHistory
		SET 	ChatSubject	= p_subject
		WHERE 	ChatHistoryId 	= v_ChatHistoryId;	
        
		UPDATE 	tb_ConcurrentAgentLimit
		SET 	agentOccupyDetails	= p_agentOccupyDetails
		WHERE 	domainId			= p_domainId;
          
 		IF p_dispositionId IS NOT NULL
 		THEN			
 			UPDATE 	tb_internalChatGroup 
 			SET 	isClosed		= 1
 				,	updatedAt		= v_CurDate
 			WHERE	historyId	 	= v_ChatHistoryId
 			AND 	hostAgent		= v_AgentId
 			AND 	channelTypeId	= 2003002	
 			AND 	isClosed		= 0;  
 		END IF;
           
 		IF ROW_COUNT() > 0
 		THEN
 			SET v_errcode=0;
 			SET v_errmsg='Success : Updated';  		
 		END IF;
           
       	SELECT v_ChatHistoryId as ChatHistoryId,p_ChatDurationHistoryId as ChatDurationHistoryId,v_errcode as errcode, v_errmsg as errmsg;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
