CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_updateCustomer_Id`(
	P_customerId int,
	P_historyId int,
	P_channelType varchar(255)
)
BEGIN

	IF  P_channelType = 'Sms' 
    THEN
		UPDATE tb_SMSHistory 
		SET customerId = P_customerId   
		WHERE SMSHistoryId = P_historyId;
	END IF;
    
    IF P_channelType = "Instagram"
    THEN 
		UPDATE tb_InstagramHistory
        SET customerId  = P_customerId
        WHERE InstagramHistoryId  = P_historyId;
	END IF;
    
	IF P_channelType = "Facebook"
    THEN 
		UPDATE tb_FacebookHistory
        SET customerId = P_customerId
        WHERE FacebookHistoryId = P_historyId;
	END IF;
    
	IF P_channelType = "Email"
    THEN 
		UPDATE tb_EmailHistory
        SET customerId = P_customerId
        WHERE EmailHistoryId = P_historyId;
	END IF;
    
    IF P_channelType = "Whatsapp"
    THEN 
		UPDATE tb_WhatsappHistory
        SET customerId = P_customerId
        WHERE WhatsappHistoryId = P_historyId;
	END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
