CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_updateHoursOfOperation`(
  p_cid 				INT,
  p_hoursOfOperation 	LONGTEXT,
  p_domainId 			INT
)
BEGIN

declare v_errcode int;
declare v_errmsg  varchar(50);
	
  UPDATE queue q
  SET 	q.hours_of_operation = p_hoursOfOperation
  WHERE q.hoursOfOperatioId = p_cid
  AND 	q.domainId = p_domainId;
  
  SET v_errcode = 0;
  SET v_errmsg  = 'Updated Successfully';
  
  Select v_errcode as errcode , v_errmsg as errmsg;
  
    
END ;;
