CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_UpdateloginSessionHistory_info`(
  p_logInSessionId 		varchar(100) 
  ,p_logOutTimestamp 	bigint  
  ,p_sipLoginId 		int
  ,p_domainId 			int
  ,p_companyId 			int
  ,p_ext 				int 
  )
BEGIN 
 	DECLARE v_errcode int default -1;
	DECLARE v_errmsg varchar(100) default 'Failure';
    
	UPDATE 	logInSessionHistory 
    SET  	logOutTimestamp = unix_timestamp(NOW())*1000
		,	updatedAt 		= NOW()
	WHERE 	logInSessionId 	= p_logInSessionId;
    
	IF ROW_COUNT()>0 
    THEN
		SET v_errcode = 0;
		SET v_errmsg = 'Successfully LoggedOut';
	END IF;
      
	SELECT v_errcode as errcode, v_errmsg as errmsg;     
 END ;;
DELIMITER ;
