CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_updateSentimentalScore`(
 		IN p_HistoryId 						BIGINT,
 		IN p_DurationHistoryId				bigint,
 		IN p_channelType 					VARCHAR(255),
 		IN p_domainId 						INT,
 		IN p_SentimentalScore   			FLOAT,
 		IN p_sentimentalScoreCustomer 		FLOAT,
 		IN p_sentimentalScoreAgent    		FLOAT,
 		IN p_ext      						INT
 	  )
BEGIN
 		DECLARE v_errcode 							INT			DEFAULT -1;
 		DECLARE v_errmsg							VARCHAR(50)	DEFAULT 'Not Updated';
 		DECLARE v_ext								INT;
 		DECLARE v_HistoryId 						BIGINT;
 		DECLARE v_channelType 						VARCHAR(255);
 		DECLARE v_domainId 							INT;
 		DECLARE v_SentimentalScore 					FLOAT;
 		DECLARE v_sentimentalScoreCustomer 			FLOAT;
 		DECLARE v_sentimentalScoreAgent 			FLOAT;
 		DECLARE v_UserID							BIGINT;
 		
 	SET v_HistoryId 					= p_HistoryId;
 	SET v_channelType 					= p_channelType;
 	SET v_domainId 						= p_domainId;      
 	SET v_SentimentalScore  			= p_SentimentalScore;
 	SET v_sentimentalScoreCustomer 		= p_sentimentalScoreCustomer;
 	SET v_sentimentalScoreAgent         = p_sentimentalScoreAgent;
 		
 		IF v_channelType IS NULL OR v_channelType = '' THEN SET v_channelType = 'Call,Chat,Email,Sms,Whatsapp,Video'; END IF;
 	  
 		IF v_channelType LIKE '%Chat%' 
 	  THEN		
 		SET v_ext	= p_ext; 
 		  
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		
 		  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 		  
 		  UPDATE 	tb_ChatDurationHistory 
 		  SET 		 SentimentalScore 				= v_SentimentalScore
 					,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 					,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)
 		  WHERE 	ChatDurationHistoryId	= p_DurationHistoryId;        
 		  
 		  SET v_errcode = 0;
 		  SET v_errmsg  = 'Updated Successfully';        
 	  END IF;
 	   
 	  IF p_channelType LIKE '%Call%' THEN  
 		SET v_ext              = p_ext; 
 		SELECT UserID INTO v_UserID FROM tb_User WHERE domainId = v_domainId AND ext = v_ext;  
 		  
 		UPDATE 	tb_CallDurationHistory                    
 		  SET 	SentimentalScore 				= v_SentimentalScore
 				,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)             
 		  WHERE 	AgentId 			= v_UserID
 		  and 	CallHistoryId	 	= p_HistoryId;
    
 	   
 		  
 		SET v_errcode = 0;
 		  SET v_errmsg  = 'Updated Successfully';
 		  
 	  END IF;
 	  
 	  IF p_channelType LIKE '%Email%' 
 	  THEN
 		UPDATE 	tb_EmailHistory 
 		SET 	SentimentalScore = v_SentimentalScore
 				,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)                
 		WHERE 	EmailHistoryId = v_HistoryId;
 		  
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 		SELECT 	U.ext INTO v_ext
