 		WHERE 	EmailHistoryId = v_HistoryId limit 1;    
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 		  
 		SET v_errcode = 0;
 		SET v_errmsg  = 'Updated Successfully';      
 	  END IF;
 	  
 	  IF p_channelType LIKE '%Sms%' THEN
 		  UPDATE tb_SMSHistory 
 		  SET 	SentimentalScore = v_SentimentalScore
 				,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)                
 		  WHERE 	SMSHistoryId = v_HistoryId;
 		 
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;            
 		  SELECT 	U.ext INTO v_ext
 		  FROM 	tb_SMSDurationHistory	SDH
 		  JOIN 	tb_User					U	ON SDH.AgentId	= U.UserId
 		  WHERE 	SMSHistoryId = v_HistoryId limit 1;
 		  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
 		  
 		SET v_errcode = 0;
 		  SET v_errmsg  = 'Updated Successfully';         
 	  END IF;
 	  
 		IF v_channelType LIKE '%Whatsapp%' 
 	THEN
 			UPDATE tb_WhatsappHistory 
 			SET 	SentimentalScore = v_SentimentalScore
 				,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)                 
 			WHERE 	WhatsappHistoryId = v_HistoryId;
 	
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			SELECT 	U.ext INTO v_ext
 			FROM 	tb_WhatsappDurationHistory	WDH
 			JOIN 	tb_User					U	ON WDH.AgentId	= U.UserId
 			WHERE 	WhatsappHistoryId = v_HistoryId limit 1;
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
 	
 			SET v_errcode = 0;
 			SET v_errmsg  = 'Updated Successfully';    
 		END IF;
 	 
 		IF v_channelType LIKE '%Facebook%' 
 		THEN		
 			UPDATE 	tb_FacebookHistory 
 			SET 	SentimentalScore = v_SentimentalScore
 				,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)                 
 			WHERE 	FacebookHistoryId = v_HistoryId;
 
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			SELECT 	U.ext INTO v_ext
 			FROM 	tb_FacebookHistory	WDH
 			JOIN 	tb_User				U	ON WDH.AgentId	= U.UserId
 			WHERE 	FacebookHistoryId = v_HistoryId limit 1;
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
 
 			SET v_errcode = 0;
 			SET v_errmsg  = 'Updated Successfully';    
 		END IF;    
 	  
 		IF v_channelType LIKE '%Instagram%' 
 		THEN		
 			UPDATE 	tb_InstagramHistory 
 			SET 	SentimentalScore = v_SentimentalScore
 				,sentimentalScoreCustomer		= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,sentimentalScoreAgent			= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)                
 			WHERE 	InstagramHistoryId = v_HistoryId;
 
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			SELECT 	U.ext INTO v_ext
 			FROM 	tb_InstagramHistory	WDH
 			JOIN 	tb_User				U	ON WDH.AgentId	= U.UserId
 			WHERE 	InstagramHistoryId = v_HistoryId limit 1;
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
 
 			SET v_errcode = 0;
 			SET v_errmsg  = 'Updated Successfully';    
 		END IF;  
       
         IF v_channelType LIKE '%Video%' 
 		THEN		
 			UPDATE 	tb_VideoDurationHistory 
 			SET 	SentimentalScore 			= v_SentimentalScore
 				,	sentimentalScoreCustomer	= IFNULL(v_sentimentalScoreCustomer,sentimentalScoreCustomer)
 				,	sentimentalScoreAgent		= IFNULL(v_sentimentalScoreAgent,sentimentalScoreAgent)                
 			WHERE 	VideoHistoryId = v_HistoryId;
 
 			SET v_errcode = 0;
 			SET v_errmsg  = 'Updated Successfully';    
 		END IF;
 	  
 	SELECT v_domainId as domainId, v_ext as ext, v_errcode as errcode, v_errmsg as errmsg;
  END ;;
