CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_updateSentimentalScore1`(
    IN p_HistoryId BIGINT,
    IN p_channelType VARCHAR(255),
	IN p_domainId INT,
    IN p_SentimentalScore FLOAT
)
BEGIN
	
	DECLARE v_errcode 	int			default -1;
    DECLARE v_errmsg	varchar(50)	default 'Not Updated';
    DECLARE v_ext		int;
    
    IF p_channelType IS NULL OR p_channelType = '' THEN SET p_channelType = 'Call,Chat,Email,Sms,Whatsapp'; END IF;

IF p_channelType LIKE '%Chat%' THEN
    UPDATE 	tb_ChatHistory 
    SET 	SentimentalScore = p_SentimentalScore
    WHERE 	ChatHistoryId = p_HistoryId ;
    
    SELECT 	U.ext INTO v_ext
    FROM 	tb_ChatDurationHistory	CDH
    JOIN 	tb_User					U	ON CDH.AgentId	= U.UserId
    WHERE 	ChatHistoryId = p_HistoryId;
    
    SET v_errcode = 0;
    SET v_errmsg  = 'Updated Successfully';
    
END IF;

IF p_channelType LIKE '%Call%' THEN
	UPDATE tb_CallHistory 
    SET 	SentimentalScore = p_SentimentalScore
    WHERE 	CallHistoryId = p_HistoryId;
    
    SELECT 	U.ext INTO v_ext
    FROM 	tb_CallDurationHistory	CDH
    JOIN 	tb_User					U	ON CDH.AgentId	= U.UserId
    WHERE 	CallHistoryId = p_HistoryId;
    
	SET v_errcode = 0;
    SET v_errmsg  = 'Updated Successfully';
    
END IF;

IF p_channelType LIKE '%Email%' THEN
	UPDATE tb_EmailHistory 
    SET 	SentimentalScore = p_SentimentalScore
    WHERE 	EmailHistoryId = p_HistoryId;
    
    SELECT 	U.ext INTO v_ext
    FROM 	tb_EmailDurationHistory	EDH
    JOIN 	tb_User					U	ON EDH.AgentId	= U.UserId
    WHERE 	EmailHistoryId = p_HistoryId;
    
	SET v_errcode = 0;
    SET v_errmsg  = 'Updated Successfully';
    
END IF;

IF p_channelType LIKE '%Sms%' THEN
    UPDATE tb_SMSHistory 
    SET 	SentimentalScore = p_SentimentalScore
    WHERE 	SMSHistoryId = p_HistoryId;
    
    SELECT 	U.ext INTO v_ext
    FROM 	tb_SMSDurationHistory	SDH
    JOIN 	tb_User					U	ON SDH.AgentId	= U.UserId
    WHERE 	SMSHistoryId = p_HistoryId;
    
	SET v_errcode = 0;
    SET v_errmsg  = 'Updated Successfully';
    
END IF;

IF p_channelType LIKE '%Whatsapp%' THEN
    UPDATE tb_WhatsappHistory 
    SET 	SentimentalScore = p_SentimentalScore
    WHERE 	WhatsappHistoryId = p_HistoryId;

    SELECT 	U.ext INTO v_ext
    FROM 	tb_WhatsappDurationHistory	WDH
    JOIN 	tb_User					U	ON WDH.AgentId	= U.UserId
    WHERE 	WhatsappHistoryId = p_HistoryId;
    
	SET v_errcode = 0;
    SET v_errmsg  = 'Updated Successfully';    
END IF;

	SELECT p_domainId as domainId, v_ext as ext, v_errcode as errcode, v_errmsg as errmsg ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
