CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_UpdateSessionDisposition_details`(
            p_domainId int,
            p_sessionId varchar(100), 
            p_summary text,
            p_disposition int,
            p_afterCallWorkTime int,
            p_calledPersonDetails int,
            p_subject text,
            p_markAsRead int,
            p_agentExtn int,
            p_tags		json
            )
Begin  
			DECLARE v_errcode 			INT default -1;
			DECLARE v_errmsg 			VARCHAR(50) DEFAULT 'Error : Not Updated';   
			DECLARE v_CallHistoryId		BIGINT;
			DECLARE v_CallDurationHistoryId	BIGINT;
			DECLARE v_UserID			BIGINT;
            
           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   		select UserID into v_UserID from tb_User where ext = p_agentExtn and domainId = p_domainId limit 1;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
              
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
    		SELECT 	CallHistoryId	INTO v_CallHistoryId
    		FROM 	tb_CallHistory a 
    		WHERE 	domainId 	= p_domainId 
    		AND 	sessionId collate utf8mb4_0900_ai_ci	= p_sessionId limit 1;
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
             
    		IF v_CallHistoryId IS NOT NULL
    		THEN  		
    			UPDATE tb_CallHistory 
    			SET 
    				
    				
    				CustomerId 		= p_calledPersonDetails
    				
    				
    			WHERE CallHistoryId 	= v_CallHistoryId;  	
                    
        		if v_UserID is not null or v_UserID <> 0 
               then
   				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
   				SELECT 	CallDurationHistoryId INTO v_CallDurationHistoryId
                   FROM 	tb_CallDurationHistory
                   WHERE 	CallHistoryId 	= v_CallHistoryId 
                   AND 	AgentId 		= v_UserID
                   ORDER BY CallDurationHistoryId DESC LIMIT 1;
                   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                   
                    UPDATE tb_CallDurationHistory
                    SET 	summary 				= IFNULL(p_summary,summary),
							dispositionId 			= IFNULL(p_disposition,dispositionId),
							`subject` 				= IFNULL(p_subject,`subject`),
							afterCallWorkTime 		= IFNULL(p_afterCallWorkTime,afterCallWorkTime),
							markAsRead 				= IFNULL(p_markAsRead,markAsRead),
							tags 					= IFNULL(p_tags,tags),
							updatedAt				= NOW()
   				 WHERE 	CallDurationHistoryId 	= v_CallDurationHistoryId;            
     
    				UPDATE 	tb_internalChatGroup
    				SET 	isClosed		= 1
    				WHERE 	historyId		= v_CallHistoryId
    				AND 	domainId		= p_domainId
    				AND 	channelTypeId	= 2003001 
    				AND 	isClosed		= 0
   				AND 	hostAgent		= v_UserID;
        		END IF;  
                
          		SET v_errcode=0;
          		SET v_errmsg='Success : Updated'; 
            	
             END IF;     
          	SELECT v_CallHistoryId as CallHistoryId,v_errcode as errcode, v_errmsg as errmsg;
          End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_UpdateSessionDisposition_details_TEST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
