CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_updateTicketingId`(
	p_ticketId  	BIGINT,
	p_historyId 	INT,
	p_domainId 		INT,
	p_channelType 	VARCHAR(10),
	p_ext 			INT
)
begin
		declare v_errcode			int	default -1;
		declare v_errmsg			varchar(55)  default 'No Update';
		declare v_AgentId 			bigint;
        
        SELECT  UserID INTO v_AgentId 
        FROM 	tb_User 
        WHERE 	domainId 	= p_domainId 
        AND 	ext 		= p_ext 
        AND 	isActive 	= 1 LIMIT 1;
           
		IF p_channelType = 'Call' 
        THEN
			UPDATE 	tb_CallDurationHistory  
			SET 	ticketId 		= p_ticketId
			WHERE 	CallHistoryId 	= p_historyId    			
			AND 	AgentId  		= v_AgentId
            ORDER BY CallDurationHistoryId DESC	LIMIT 1;
		END IF;
           
		IF p_channelType = 'Chat' then 
   			UPDATE 	tb_ChatDurationHistory  
   			SET 	ticketId 		= p_ticketId
   			WHERE 	ChatHistoryId 	= p_historyId    			
			AND 	AgentId  		= v_AgentId
            ORDER BY ChatDurationHistoryId DESC LIMIT 1;
		END IF;
           
           if p_channelType = 'Whatsapp' then
   			update tb_WhatsappHistory  
   			SET ticketId = p_ticketId
   			where WhatsappHistoryId = p_historyId 
   			AND domainId = p_domainId;
           End if;
           
           if p_channelType = 'Sms' then
   			update tb_SMSHistory  
   			SET ticketId = p_ticketId
   			where SMSHistoryId = p_historyId 
   			AND domainId = p_domainId;
           End if;
           
           if p_channelType = 'Email' then
   			update tb_EmailHistory  
   			SET ticketId = p_ticketId
   			where EmailHistoryId = p_historyId 
   			AND domainId = p_domainId;
           End if;
           
           if p_channelType = 'Instagram' then
   			update tb_InstagramHistory  
   			SET ticketId = p_ticketId
   			where InstagramHistoryId = p_historyId 
   			AND domainId = p_domainId;
           End if;
 
           if p_channelType = 'Facebook' then
   			update tb_FacebookHistory  
   			SET ticketId = p_ticketId
   			where FacebookHistoryId = p_historyId 
   			AND domainId = p_domainId;
           End if;
           
   		if row_count()>0
   		 then
   			set v_errcode = 0;
   			set v_errmsg = 'Updated Successfully';
   		end if;       
         
        select v_errcode as errcode, v_errmsg as errmsg;    
    end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
