CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_agent_queue`(
      	p_domainId			INT
      	,p_userId			INT
      	,p_queueId			VARCHAR(500)
       )
BEGIN
      	DECLARE v_errcode		INT 			DEFAULT -1; 
      	DECLARE v_errmsg		VARCHAR(100) 	DEFAULT 'Failure'; 
      	DECLARE v_UserID		INT; 

		DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
			SHOW ERRORS;   
			ROLLBACK;   
		END;
                   
       START TRANSACTION;
       
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
			SELECT	UserID INTO v_UserID 
			FROM 	tb_User 
			WHERE 	domainId 	= p_DomainId 
			AND 	UserID 		= p_userId 
            LIMIT 1;
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	
      
      IF v_UserID IS NOT NULL
      THEN
			UPDATE 	tb_User
			SET 	queueId			= p_queueId
			,		updatedAt		= NOW()
			WHERE 	UserID			= v_UserID;
           
			SET v_errcode 	= 0;
			SET v_errmsg 	= 'Updated Successfully';
		END IF;
   	COMMIT;
   	SELECT v_errcode errcode, v_errmsg	errmsg;
   END ;;
