CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_article_category_move`(
	  p_ArticleId				VARCHAR(1000)
	 ,p_CategoryId				INT
 )
BEGIN

	DECLARE v_CategoryId INT;
	DECLARE v_errcode INT;
	DECLARE v_errmsg VARCHAR(50);
    
		DROP TEMPORARY TABLE IF EXISTS temp_article_details;
		CREATE TEMPORARY TABLE temp_article_details(arid INT);
		
		CALL split(p_ArticleId,',');
		INSERT INTO temp_article_details(arid)
		SELECT Items FROM tt_Split_temptable;

		SELECT CategoryId INTO v_CategoryId
		FROM  tb_KnowledgeBaseCategory
		WHERE CategoryId = p_CategoryId;
                 
     IF v_CategoryId IS NOT NULL
     THEN
		UPDATE tb_KnowledgeBaseArticleDtl KA
        JOIN temp_article_details TA ON KA.ArticleId = TA.arid
        SET KA.categoryId = v_CategoryId;
		
        SET v_errcode = 0;
        SET v_errmsg = 'Article moved successfully';
        
     END IF;
     
     SELECT v_errcode AS errcode,v_errmsg AS errmsg;
                 
 END ;;
DELIMITER ;
