CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_update_block_customer_req`( p_coid int, p_domainId int, p_blockCustomerReq int, p_blockedReqBy int, p_Reason varchar(225))
Begin
	declare v_errcode int default -1;
    declare v_errmsg varchar(20) default 'Failure';
    
    UPDATE customer_contact 
    SET blockCustomerReq = ifnull(p_blockCustomerReq,blockCustomerReq)
		,blockedReqBy = ifnull(p_blockedReqBy,blockedReqBy)
		,Reason = ifnull(p_Reason,Reason)
    WHERE coid = p_coid AND domainId = p_domainId;
    
    if row_count()>0 then
		set v_errcode = 0;
		set v_errmsg = 'Success';
	 End if;
     
     select v_errcode as errcode, v_errmsg as errmsg;
    
End ;;
