CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_businessHoliday_status`(
	  p_fkBusinessId			INT
     ,p_holidayId				INT
     ,p_status					TINYINT
)
begin
		
	DECLARE v_errcode 	INT DEFAULT -1;
	DECLARE v_errmsg 	VARCHAR(60) DEFAULT 'Holiday Status Update Failed';
    DECLARE v_HolidayId INT;
    DECLARE v_curdate 	DATETIME;
    
    SET v_curdate = NOW();
    
    SELECT 	hid INTO v_HolidayId
    FROM 	tb_Business_Holidays
    WHERE 	hid 			= p_holidayId
    AND		fk_businessId 	= p_fkBusinessId;
    
    IF v_HolidayId IS NOT NULL 
    THEN 
		UPDATE tb_Business_Holidays
        SET  isStatus		= p_status
			,updatedAt		= v_curdate
		WHERE hid = v_HolidayId;
        
        SET v_errcode = 1;
        SET v_errmsg = 'Holiday Status Updated successfully';
	END IF;
    SELECT v_errcode AS errcode,v_errmsg AS errmsg;
end ;;
