        ,p_cid						int
        ,p_qid						int	
)
begin
		declare v_errcode int default -1;
		declare v_errmsg varchar(50) default 'Failure';
		declare v_qid int;
      
		  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
				SELECT	qid into v_qid 
				FROM 	queue 
				WHERE 	domainId 	= p_domainId 
				AND 	qid	 		= p_qid 
				LIMIT 1;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
		  
		IF v_qid IS NOT NULL
		THEN 
			
			UPDATE queue 
            SET  hoursOfOperatioId = p_cid
            ,updatedAt = NOW()
            WHERE qid = v_qid;
  
			SET v_errcode = 1;
			SET v_errmsg = 'Updated';
  
		END IF;
			select v_errcode as errcode, v_errmsg as errmsg,v_qid as qid;
