CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_callBlast_complete_status`(
	 p_blastId 	INT
	,p_domainId INT
    ,p_completed  INT
)
BEGIN
		DECLARE v_cid INT;
		DECLARE v_errcode INT DEFAULT -1;
		DECLARE v_errmsg VARCHAR(100) DEFAULT 'callBlast status update fail';
        DECLARE v_endDate DATE;
    
		SELECT 	cid INTO v_cid 
		FROM 	tb_callBlast
		WHERE 	cid = p_blastId
		AND		domainId = p_domainId;
		
		SELECT ctd.endDate INTO v_endDate 
		FROM  	tb_callBlast cb
		JOIN 	tb_callBlast_dailyTrigger_dtl ctd ON cb.cid = ctd.fk_cid
		WHERE cb.domainId = p_domainId
		AND ctd.fk_cid = v_cid;
        
    IF v_cid IS NOT NULL AND (IFNULL(v_endDate,CURDATE()) <=  CURDATE())
	THEN
		UPDATE 	tb_callBlast
        SET 	completed = IFNULL(p_completed, completed)
		WHERE 	cid = v_cid;
        
        SET v_errcode = 0;
        SET v_errmsg = 'callBlast complete status update successfully';
	END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
END ;;
DELIMITER ;
