CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_callBlast_status`(
	 p_blastId 		INT
	,p_domainId 	INT
    ,p_blastStatus 	TINYINT 
    ,p_forceStop 	TINYINT
    ,p_pause 		TINYINT
)
begin
	
    DECLARE v_cid INT;
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'callBlast status update fail';
    
    SELECT 	cid INTO v_cid 
    FROM 	tb_callBlast
    WHERE 	cid = p_blastId
    AND		domainId = p_domainId;
    
	IF v_cid IS NOT NULL
	THEN
		UPDATE 	tb_callBlast
        SET 	blastStatus  	= IFNULL(p_blastStatus,blastStatus)
				,forceStop 		= IFNULL(p_forceStop,forceStop)
				,pause 			= IFNULL(p_pause,pause)
		WHERE 	cid = v_cid;
        
        SET v_errcode = 0;
        SET v_errmsg = 'callBlast status update successfully';
	END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
    
end ;;
DELIMITER ;
