CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_update_callcost_session_history_details`(
 p_sessionId 		varchar(250),
 p_callCost			DECIMAL(20,2)
 )
Begin
 
 	DECLARE v_errcode 		INT DEFAULT -1;
 	DECLARE v_errmsg		VARCHAR(55) DEFAULT 'Failure';
     DECLARE v_CallHistoryId	BIGINT;
     
     DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
 		BEGIN
 			GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
 			set v_errmsg =  CONCAT(@st, ' : ', @p2);
 			set  @st='';
 			select v_errcode as errcode, v_errmsg as errmsg;
 			ROLLBACK;
 		END;
     
     
     START transaction;
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;            
 			SELECT 	CallHistoryId INTO v_CallHistoryId
 			FROM 	tb_CallHistory
 			WHERE	sessionId	= p_sessionId limit 1;
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
         
         IF IFNULL(v_CallHistoryId,0)<>0 THEN
 			UPDATE 	tb_CallHistory 
 			SET 	callCost		= ifnull(p_callCost,callCost)
 					,updatedAt		= now()
 			where 	CallHistoryId 	= v_CallHistoryId;
             
 			if found_rows()>0 then
 				set v_errcode = 0;
 				set v_errmsg = 'Updated successfully';
 			end if;  
                     
         END IF;
         
     COMMIT;
 		select v_errcode as errcode, v_errmsg as errmsg;
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
