CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_update_chat_flow_map`(
p_domainId int
,p_channelName varchar(255)
,p_callFlowId varchar(255)
,p_sourceId varchar(255)
)
Begin

	declare v_errcode int default -1;
    declare v_errmsg varchar(20) default 'Failure';

	if not exists(SELECT 1 FROM callMap WHERE sourceId = p_sourceId AND domainId = p_domainId limit 1) then
		INSERT INTO callMap (channelName,callFlowId,domainId,sourceId,createdAt) 
        VALUES (p_channelName,p_callFlowId,p_domainId,p_sourceId,CURRENT_TIMESTAMP());
        
        if row_count()>0 then
			set v_errcode = 0;
            set v_errmsg = 'Inserted';
        End if;
    else
		UPDATE callMap SET callFlowId = p_callFlowId,updatedAt = CURRENT_TIMESTAMP()
        WHERE sourceId = p_sourceId AND domainId = p_domainId;
        
        if row_count()>0 then
			set v_errcode = 0;
            set v_errmsg = 'Updated';
        End if;
        
    End if;
    select v_errcode as errcode, v_errmsg as errmsg;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
