CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_update_customer_attachment`(
	p_domainId int,
	p_coid int,
	p_attachments json
)
Begin
	declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'Failure';
    declare v_id int;
    
    select coid into v_id from customer_contact where coid = p_coid and domainId = p_domainId;
    
    if v_id is not null then
		update customer_contact 
        set attachments = ifnull(p_attachments,attachments)
        where coid = p_coid and domainId = p_domainId;
    
		if row_count()>0 then
			set v_errcode = 0;
			set v_errmsg = 'Attachment updated';
		End if;
    
    End if;

    select v_errcode as errcode, v_errmsg as errmsg;
End ;;
DELIMITER ;
