CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_customer_callBack_status`(
	 p_domainId		INT 
    ,p_channelType	VARCHAR(50)
    ,p_historyId	INT
)
begin

	DECLARE v_errcode INT DEFAULT -1;
	DECLARE v_errmsg VARCHAR(100) DEFAULT 'callback status update failed';

	IF p_channelType = 'Whatsapp' 
    THEN
		UPDATE tb_WhatsappHistory
        SET isCallback = 0
		WHERE domainId 			= p_domainId
 		AND WhatsappHistoryId 	= p_historyId;
        
        SET v_errcode = 0;
        SET v_errmsg = 'Whatsapp callback status updates successfully';

 	ELSEIF p_channelType = 'Facebook' 
    THEN
    
		UPDATE tb_FacebookHistory
        SET isCallback = 0
		WHERE domainId 			= p_domainId
 		AND FacebookHistoryId 	= p_historyId;
        
        SET v_errcode = 0;
        SET v_errmsg = 'Facebook callback status updates successfully';
         
 	ELSEIF p_channelType = 'Instagram' 
    THEN
		
        UPDATE tb_InstagramHistory
        SET isCallback = 0
		WHERE domainId 			= p_domainId
 		AND instagramHistoryId 	= p_historyId;
        
        SET v_errcode = 0;
        SET v_errmsg = 'Instagram callback status updates successfully';
         
 	END IF;

	SELECT v_errcode AS errcode,v_errmsg AS errmsg;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
