CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_customer_contact`(
     p_coid						int
	,p_domainId					int
	,p_firstName				varchar(100)
	,p_lastName					varchar(100)
	,p_primaryPhoneNumber		varchar(20)
	,p_phoneNumber				varchar(1000)
	,p_primaryEmail				varchar(150)
	,p_email					varchar(1500)
	,p_accountNumber			varchar(100)
	,p_tags						varchar(750)
	,p_location					varchar(100)
	,p_address					varchar(225)
	,p_country					varchar(100)
	,p_state					varchar(100)
	,p_city						varchar(100)
	,p_postalCode				varchar(100)
	,p_facebook					varchar(100)
	,p_instagram				varchar(100)
	,p_whatsapp					varchar(100)
	,p_twitter					varchar(100)
	,p_voiceBiometric			varchar(100)
	,p_mergeCustomer			int
	,p_blockCustomer			int
	,p_doNotDisturb				int
	,p_blockCustomerReq			int
	,p_doNotDisturbReq			int
	,p_type						varchar(40)
	,p_currentCustomerNumber	varchar(20)
	,p_customerType				varchar(255)
	,p_Timezone					varchar(100)
	,p_blockedBy				int
	,p_doNotDisturbBy			int
	,p_blockedReqBy				int
	,p_doNotDisturbReqBy		int
	,p_Reason					varchar(225)
	,p_cookiesId				varchar(150)
	,p_Source					varchar(250)
	,p_attachments				json
	,p_CustomerUniqueId			varchar(150)
 )
BEGIN
	declare v_errcode int default -1;
	declare v_errmsg varchar(50) default 'Failure';
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
	BEGIN
		GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
		set v_errmsg =  CONCAT(@st, ' : ', @p2);
		select -1 as errcode,  v_errMsg as errmsg;
		ROLLBACK;
	END;
  
	START TRANSACTION;

	IF EXISTS (SELECT 1 FROM customer_contact WHERE coid = p_coid AND domainId = p_domainId) THEN
		UPDATE customer_contact 
		SET 
			 firstName              = IFNULL(p_firstName, firstName)
			,lastName               = IFNULL(p_lastName, lastName)
			,primaryPhoneNumber     = IFNULL(p_primaryPhoneNumber, primaryPhoneNumber)
			,phoneNumber            = IFNULL(p_phoneNumber, phoneNumber)
			,primaryEmail           = IFNULL(p_primaryEmail, primaryEmail)
			,email                  = IFNULL(p_email, email)
			,accountNumber          = IFNULL(p_accountNumber, accountNumber)
			,tags                   = IFNULL(p_tags, tags)
			,location               = IFNULL(p_location, location)
			,address                = IFNULL(p_address, address)
			,country                = IFNULL(p_country, country)
			,state                  = IFNULL(p_state, state)
			,city                   = IFNULL(p_city, city)
			,postalCode             = IFNULL(p_postalCode, postalCode)
			,facebook               = IFNULL(p_facebook, facebook)
			,instagram              = IFNULL(p_instagram, instagram)
			,whatsapp               = IFNULL(p_whatsapp, whatsapp)
			,twitter                = IFNULL(p_twitter, twitter)
			,voiceBiometric         = IFNULL(p_voiceBiometric, voiceBiometric)
			,mergeCustomer          = IFNULL(p_mergeCustomer, mergeCustomer)
			,blockCustomer          = IFNULL(p_blockCustomer, blockCustomer)
			,doNotDisturb           = IFNULL(p_doNotDisturb, doNotDisturb)
			,blockCustomerReq       = IFNULL(p_blockCustomerReq, blockCustomerReq)
			,doNotDisturbReq        = IFNULL(p_doNotDisturbReq, doNotDisturbReq)
			,type                   = IFNULL(p_type, type)
			,currentCustomerNumber  = IFNULL(p_currentCustomerNumber, currentCustomerNumber)
			,customerType           = IFNULL(p_customerType, customerType)
			,Timezone               = IFNULL(p_Timezone, Timezone)
			,blockedBy              = IFNULL(p_blockedBy, blockedBy)
			,doNotDisturbBy         = IFNULL(p_doNotDisturbBy, doNotDisturbBy)
			,blockedReqBy           = IFNULL(p_blockedReqBy, blockedReqBy)
			,doNotDisturbReqBy      = IFNULL(p_doNotDisturbReqBy, doNotDisturbReqBy)
			,Reason                 = IFNULL(p_Reason, Reason)
			,cookiesId              = IFNULL(p_cookiesId, cookiesId)
			,Source                 = IFNULL(p_Source, Source)
			,attachments            = IFNULL(p_attachments, attachments)
			,CustomerUniqueId       = IFNULL(p_CustomerUniqueId, CustomerUniqueId)
			,updatedAt              = NOW()
		WHERE coid = p_coid AND domainId = p_domainId;

		SET v_errcode = 0;
		SET v_errmsg = 'Success';
	END IF;   

	COMMIT;
	SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
