CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_update_customer_contact_tag`(
 p_coid int,
 p_domainId int,
 p_tags varchar(750)
 )
begin
	
    declare v_errcode int default -1;
    declare v_errmsg varchar(20) default 'Failure';
    
	UPDATE customer_contact SET tags = p_tags WHERE coid = p_coid AND domainId = p_domainId;
    
    if row_count()>0 then
		set v_errcode = 0;
		set v_errmsg = 'Updated';
	 End if;
    
    select v_errcode as errcode, v_errmsg as errmsg;
 end ;;
