CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_customReport_copyLink`(
	 p_reportId		INT
     ,p_isExpired	TINYINT
     ,p_expireDate	DATE
     ,p_isPassword	TINYINT
     ,p_password	VARCHAR(50)
)
begin

	DECLARE v_reportId INT;
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'Report link shared failed';
	
    SELECT reportId
    INTO v_reportId
    FROM tb_custom_report_dtl
    WHERE reportId = p_reportId;
    
    IF v_reportId IS NOT NULL 
    THEN
		UPDATE tb_custom_report_dtl
			SET isExpired 	= p_isExpired
			,expireDate = p_expireDate
			,isPassword = p_isPassword
			,password 	= p_password
            ,updatedAt	= now()
		WHERE reportId 	= v_reportId;

		SET v_errcode = 0;
		SET v_errmsg = 'Report link shared successfully';
    END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg,v_reportId as reportId,p_isExpired as isExpired,p_expireDate as expireDate,p_isPassword as isPassword,p_password as password;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
