DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_customShareReport`(
	  p_reportId 	INT
     ,p_domainId 	INT
     ,p_agentId 	VARCHAR(500)
     ,p_createdBy	INT
)
begin
	
    DECLARE v_reportId INT;
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'Report shared failed';
    
    DECLARE v_isExpired 	TINYINT;
    DECLARE v_expireDate	DATE;
    DECLARE v_isPassword	TINYINT;
    DECLARE v_password		VARCHAR(100);
	
    SELECT reportId,isExpired,expireDate,isPassword,password
    INTO v_reportId,v_isExpired,v_expireDate,v_isPassword,v_password
    FROM tb_custom_report_dtl
    WHERE reportId = p_reportId;
    
    IF v_reportId IS NOT NULL 
    THEN
		UPDATE tb_custom_report_dtl
			SET agentId = p_agentId
            ,createdBy	= p_createdBy
            ,updatedAt	= now()
		WHERE reportId 	= v_reportId;

		SET v_errcode = 0;
		SET v_errmsg = 'Report shared successfully';
    END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg,v_isExpired as isExpired,v_expireDate as expireDate,v_isPassword as isPassword,v_password as password;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
