CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_custom_hours`(
		p_cid				int	
		,p_name				varchar(255)
		,p_description		varchar(255)
		,p_hours			longtext
		,p_domainId			int
		,p_timeZone			varchar(100)
		,p_default_hours	varchar(100)
		,p_timeZoneValue	varchar(40)
		,p_type				varchar(50)
		
)
begin
		declare v_errcode int default -1;
		declare v_errmsg varchar(50) default 'Failure';
		declare v_cid int;
    
		select cid into v_cid
		from custom_hours
		where cid = p_cid
        and domainId = p_domainId;
      
		IF v_cid IS NOT NULL
		THEN 
			UPDATE custom_hours 
			SET name			=IFNULL(p_name,name),
				description		=IFNULL(p_description,description),
				hours			=IFNULL(p_hours,hours),
				updatedAt		=NOW(),
				timeZone		=IFNULL(p_timeZone,timeZone),
				default_hours	=IFNULL(p_default_hours,default_hours),
				timeZoneValue	=IFNULL(p_timeZoneValue,timeZoneValue),
				type			=IFNULL(p_type,type)
			WHERE cid = v_cid;
            
            IF EXISTS (SELECT 1 FROM queue WHERE hoursOfOperatioId = p_cid)
            THEN
				UPDATE queue
				SET hours_of_operation = IFNULL(p_hours,hours_of_operation)
				WHERE hoursOfOperatioId = v_cid;
			
            END IF;
            
			SET v_errcode = 1;
			SET v_errmsg = 'Updated';
  
		END IF;
			select v_errcode as errcode, v_errmsg as errmsg, cid,name,description,hours,createdAt,updatedAt,domainId,timeZone,default_hours,timeZoneValue,type 
         from custom_hours 
         where cid = v_cid;
end ;;
DELIMITER ;
