CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_email_domain_status`(	
		p_id 				INT ,
		p_domainId 			INT ,
		p_status 			VARCHAR(200) 
)
begin
	
    declare v_errcode int default -1;
    declare v_errmsg varchar(100) default 'Status update fail';
    declare v_id int;
    declare v_companyName varchar(250);
    
    select companyName into v_companyName 
    from tb_companyDomain
    where domainId = p_domainId;
  
	select id into v_id
    from 	ccaas_email_domain_configuration 
    where 	id 			= p_id
    and 	domainId 	= p_domainId limit 1;

    IF v_id IS NOT NULL
    THEN
	
		update ccaas_email_domain_configuration
        set  status 				= p_status
            ,updatedAt				= now()
		where id = v_id;

			set v_errcode 	= 1;
			set v_errmsg	= 'Email domain status : updated successfully';
        
	end if;

    select v_errcode as errcode,v_errmsg as errmsg,v_companyName as companyName;

end ;;
DELIMITER ;
