CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_Update_FacebookPageId`(
      p_domainId             INT,
      p_FacebookPageId       varchar(50),
      p_pageName             varchar(250)
  )
BEGIN
      DECLARE v_curdate DATETIME;
      DECLARE v_errcode INT DEFAULT -1;
      DECLARE v_errmsg VARCHAR(100) DEFAULT 'Update is Failed';
      DECLARE v_row_count INT;
      DECLARE v_FacebookConfigurationId INT;
  
      SET v_curdate = NOW();
      
      SELECT FacebookConfigurationId INTO v_FacebookConfigurationId
      FROM tb_FacebookConfiguration 
      WHERE domainId = p_domainId;
	
    IF v_FacebookConfigurationId IS NOT NULL
    THEN
      UPDATE tb_FacebookConfiguration
      SET
			FacebookPageId=p_FacebookPageId,
			facebookintegrationId=1,
			pageName    = p_pageName,  
			updatedDate = v_curdate
			WHERE FacebookConfigurationId = v_FacebookConfigurationId;
		  
			SET v_errcode = 1;
			SET v_errmsg = 'Updated Successfully';
    END IF;
      
                  SELECT v_errcode AS errcode, v_errmsg AS errmsg;
  END ;;
