CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_facebook_callback_status`(
                  p_domainId                        INT
 				,p_FacebookHistoryId               INT
 )
begin
  
	DECLARE v_errcode	INT DEFAULT -1;
	DECLARE v_errmsg	VARCHAR(100) DEFAULT 'Facebook callback status update fail';
	DECLARE v_FacebookHistoryId	INT;

	SELECT	FacebookHistoryId INTO v_FacebookHistoryId
	FROM	tb_FacebookHistory
	WHERE	FacebookHistoryId	= p_FacebookHistoryId
	AND	domainId	= p_domainId;

	IF v_FacebookHistoryId IS NOT NULL
	THEN 
	UPDATE tb_FacebookHistory
	SET isCallback = 1, callbackDraft 	= 0 , IsMissed			= 1
	WHERE FacebookHistoryId = v_FacebookHistoryId;
    
	SET v_errcode = 0;
	SET v_errmsg  = 'Facebook callback status update successfully';

	END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
     
 end ;;
DELIMITER ;
