		update tb_InstagramHistory
		set IsBot = 1
		where InstagramHistoryId = v_InstagramHistoryId;
    
    if row_count() > 0 
    then
		set v_errcode = 1;
		set v_errmsg  = 'Flow bot updated successfully';
    end if;
    
end if;

	select v_errcode as errcode,v_errmsg as errmsg;

end ;;
DELIMITER ;
