CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_instagram_callback_status`(
                  p_domainId                        INT
 				,p_InstagramHistoryId               INT
 )
begin
  
	DECLARE v_errcode	INT DEFAULT -1;
	DECLARE v_errmsg	VARCHAR(100) DEFAULT 'Instagram callback status update fail';
	DECLARE v_InstagramHistoryId	INT;

	SELECT	InstagramHistoryId INTO v_InstagramHistoryId
	FROM	tb_InstagramHistory
	WHERE	InstagramHistoryId	= p_InstagramHistoryId
	AND	domainId	= p_domainId;

	IF v_InstagramHistoryId IS NOT NULL
	THEN 
	UPDATE tb_InstagramHistory
	SET isCallback = 1, callbackDraft = 0, IsMissed = 1
	WHERE InstagramHistoryId = v_InstagramHistoryId;

	SET v_errcode = 0;
	SET v_errmsg  = 'Instagram callback status update successfully';

	END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;
     
 end ;;
