	declare v_id int;

	SELECT id INTO v_id 
    FROM ccaas_ecom_purchaseflow_log 
    WHERE domainId = p_domainId AND tokenId = p_tokenId AND channelType = p_channelType limit 1;


	IF v_id IS NOT NULL
	THEN
