CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_isTrigger`(	
	 p_durationHistoryId					BIGINT
	,p_channelType							VARCHAR(15)
	,p_isTrigger							TINYINT
)
BEGIN	
		DECLARE v_errCode				INT	DEFAULT -1;
      	DECLARE v_errMsg				VARCHAR(150) DEFAULT 'Update Failed';
      	DECLARE	v_CurDate				DATETIME;
            
		SET v_CurDate = NOW();
           
       	IF p_channelType = 'Call'
        THEN
        		UPDATE 	tb_CallDurationHistory
				SET 	isTrigger				= ifnull(p_isTrigger,isTrigger)
                ,		updatedAt				= v_CurDate
        		WHERE 	CallDurationHistoryId 	= p_durationHistoryId;	
                
                SET v_errCode	= 0;
                SET v_errMsg 	= 'IsTrigger Upadted Successfully';
       ELSEIF p_channelType = 'Email'
       THEN		
				UPDATE 	tb_EmailDurationHistory
				SET 	isTrigger				= ifnull(p_isTrigger,isTrigger)
                ,		UpdatedAt				= v_CurDate
        		WHERE 	EmailHistoryId 	= p_durationHistoryId;
                
                SET v_errCode	= 0;
                SET v_errMsg 	= 'IsTrigger Upadted Successfully';
        ELSEIF p_channelType = 'SMS'
       THEN		
				UPDATE 	tb_SMSDurationHistory
				SET 	isTrigger				= ifnull(p_isTrigger,isTrigger)
                ,		updatedAt				= v_CurDate
        		WHERE 	SMSHistoryId 	= p_durationHistoryId;
                
                SET v_errCode	= 0;
                SET v_errMsg 	= 'IsTrigger Upadted Successfully';
        ELSEIF p_channelType = 'Whatsapp'
       THEN		
				UPDATE 	tb_WhatsappDurationHistory
				SET 	isTrigger					= ifnull(p_isTrigger,isTrigger)
                ,		updatedAt					= v_CurDate
        		WHERE 	WhatsappDurationHistoryId 	= p_durationHistoryId;
                
                SET v_errCode	= 0;
                SET v_errMsg 	= 'IsTrigger Upadted Successfully';
        ELSEIF p_channelType = 'Facebook'
       THEN		
				UPDATE 	tb_FacebookHistory
				SET 	isTrigger				= ifnull(p_isTrigger,isTrigger)
                ,		updatedAt				= v_CurDate
        		WHERE 	FacebookHistoryId 	= p_durationHistoryId;
                
                SET v_errCode	= 0;
                SET v_errMsg 	= 'IsTrigger Upadted Successfully';
        ELSEIF p_channelType = 'Instagram'
       THEN		
				UPDATE 	tb_InstagramHistory
				SET 	isTrigger				= ifnull(p_isTrigger,isTrigger)
                ,		updatedAt				= v_CurDate
        		WHERE 	InstagramHistoryId 		= p_durationHistoryId;
                
        		SET v_errCode	= 0;
                SET v_errMsg 	= 'IsTrigger Upadted Successfully';
        	END IF;
        		
        	SELECT v_errCode errCode,v_errMsg 	errMsg;
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
