CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_KnowledgeBaseCategory_dtl`(
	 p_kid			INT 
    ,p_CategoryId		INT 
    ,p_CategoryName		VARCHAR(250)
    ,p_CategoryDescription	VARCHAR(500)
)
begin

		DECLARE v_errcode	INT DEFAULT -1;
 		DECLARE v_errmsg	VARCHAR(150) DEFAULT 'Knowledge Base Category Update Fail';
        DECLARE v_CategoryId INT;

		SELECT CategoryId INTO v_CategoryId
		FROM tb_KnowledgeBaseCategory
		WHERE fk_kid = p_kid
        AND CategoryId = p_CategoryId;

		IF v_CategoryId IS NOT NULL
        THEN
			UPDATE tb_KnowledgeBaseCategory 
            SET 	CategoryName 		= IFNULL(p_CategoryName,CategoryName)
				,	CategoryDescription = IFNULL(p_CategoryDescription,CategoryDescription)
            WHERE CategoryId = v_CategoryId;
            
            SET v_errcode = 0;
			SET v_errmsg  = 'Knowledge Base Category Updated Successfully'; 
		END IF;
        
        SELECT v_errcode AS errcode,v_errmsg AS errmsg;
        
end ;;
