CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_my_plan_queue_permission`(
    p_domainId                 	INT,
    p_queueId                 	INT,
    p_agentMonitoring         	TINYINT,
    p_addOrRemove      			TINYINT,
    p_reportingDashboard   		TINYINT
)
BEGIN

    DECLARE v_errcode 	INT DEFAULT -1;
    DECLARE v_errmsg  	VARCHAR(150) DEFAULT 'Insert / Update Failed';
    DECLARE v_qid 		INT;

sp_return:begin

	IF (IFNULL(p_queueId,'') = '' OR IFNULL(p_domainId,'') = '')
    THEN
		SET v_errcode = -1;
        SET v_errmsg  = 'queueId / domainId	should not be empty';
        leave sp_return;
	END IF;

    SELECT fk_qid INTO v_qid
    FROM 	tb_queue_permission 
    WHERE 	domainId 	= p_domainId 
    AND 	fk_qid 		= p_queueId 
    LIMIT 1;
    
    IF v_qid IS NOT NULL
    THEN
    
        UPDATE  tb_queue_permission
		SET		agentMonitoring       	= IFNULL(p_agentMonitoring, agentMonitoring),
				addOrRemove    			= IFNULL(p_addOrRemove, addOrRemove),
				reportingDashboard 		= IFNULL(p_reportingDashboard, reportingDashboard),
				updatedAt       = NOW()
		WHERE fk_qid  = v_qid;

        SET v_errcode = 1;
        SET v_errmsg  = 'Updated successfully';

    END IF;
end;
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_update_my_plan_user_permission` */;
