CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_my_plan_user_permission`(
    p_domainId                 	INT,
    p_userId                  	INT,
    p_voice         			TINYINT,
    p_chat      				TINYINT,
    p_recording   				TINYINT,
    p_email        				TINYINT,
    p_knowledgeBase        		TINYINT
)
BEGIN

    DECLARE v_errcode 	INT DEFAULT -1;
    DECLARE v_errmsg  	VARCHAR(150) DEFAULT 'Insert / Update Failed';
    DECLARE v_UserID 	INT;

sp_return:begin

	IF (IFNULL(p_userId,'') = '' OR IFNULL(p_domainId,'') = '')
    THEN
		SET v_errcode = -1;
        SET v_errmsg  = 'userId / domainId	should not be empty';
        leave sp_return;
	END IF;

    SELECT UserID INTO v_UserID 
    FROM tb_User 
    WHERE domainId = p_domainId 
    AND UserID = p_userId 
    LIMIT 1;
    
    
    IF v_UserID IS NOT NULL
    THEN
    
        UPDATE tb_User
		SET
				voice       	= IFNULL(p_voice, voice),
				chat    		= IFNULL(p_chat, chat),
				recording 		= IFNULL(p_recording, recording),
				email      		= IFNULL(p_email, email),
				knowledgeBase   = IFNULL(p_knowledgeBase, knowledgeBase),
				updatedAt       = NOW()
		WHERE UserID  = v_UserID;

        SET v_errcode = 1;
        SET v_errmsg  = 'Updated successfully';

    END IF;
end;
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
