CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_queue_list`(
	p_qid			INT
    ,p_sessionId	VARCHAR(500)
)
begin

	DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'Queue list update failed';
    DECLARE v_queueList JSON;
    DECLARE v_updated_json JSON;
    
    SELECT queueList INTO v_queueList 
    FROM queueWeighTime WHERE qid = p_qid
    AND queueType = 'call';
	
    IF v_queueList IS NOT NULL
    THEN
			SELECT JSON_ARRAYAGG(
				   JSON_OBJECT(
					   'from', j.from,
					   'ddi', j.ddi,
					   'firstName', j.firstName,
					   'lastName', j.lastName,
					   'duration', j.duration,
					   'sessionId', j.sessionId,
					   'queuedTime', j.queuedTime,
					   'type', j.type
				   )
			   ) INTO v_updated_json
			FROM JSON_TABLE(
				 v_queueList,
				 '$[*]' COLUMNS (
					 `from` 		VARCHAR(50) 	PATH '$.from',
					 `ddi` 			VARCHAR(50) 	PATH '$.ddi',
					 `firstName` 	VARCHAR(50) 	PATH '$.firstName',
					 `lastName` 	VARCHAR(50) 	PATH '$.lastName',
					 `duration` 	VARCHAR(50) 	PATH '$.duration',
					 `sessionId` 	VARCHAR(200) 	PATH '$.sessionId',
					 `queuedTime` 	BIGINT 			PATH '$.queuedTime',
					 `type` 		VARCHAR(50) 	PATH '$.type'
				 )
			 ) j
			WHERE j.sessionId collate utf8mb4_unicode_ci <> p_sessionId;
    
        UPDATE queueWeighTime 
        SET queueList = v_updated_json 
        WHERE qid = p_qid;
        
        SET v_errcode = 0;
        SET v_errmsg = 'Queue list update successfully';
	END IF;
      
      SELECT v_errcode as errcode,v_errmsg as errmsg;
      
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
