CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_queue_status`(
		p_qid						int	
		,p_status					int
)
begin
		declare v_errcode int default -1;
		declare v_errmsg varchar(50) default 'Failure';
		declare v_qid int;
    
		select qid into v_qid
		from queue
		where qid = p_qid;
      
		IF v_qid IS NOT NULL
		THEN 
			
			UPDATE queue SET  updatedAt = NOW(),status = p_status  
            WHERE qid = v_qid;
  
			SET v_errcode = 1;
			SET v_errmsg = 'Updated';
  
		END IF;
			select v_errcode as errcode, v_errmsg as errmsg,v_qid as qid;
end ;;
