CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_skill_info`(
     p_skillId 					INT
     ,p_domainId 				INT
     ,p_skill_name				VARCHAR(255)
     ,p_skill_description		VARCHAR(255)
     ,p_type					VARCHAR(150)
 )
BEGIN
			DECLARE v_sid INT;
			DECLARE v_errcode int default -1;
			DECLARE v_errmsg varchar(100) default 'Failure';
             
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		SELECT  sid INTO v_sid
			FROM 	skills
 			WHERE 	sid = p_skillId
 			AND 	domainId = p_domainId;
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
             
     		IF v_sid IS NOT NULL
             THEN
     			UPDATE skills 
                SET skill_name = IFNULL(p_skill_name,skill_name)
                ,skill_description = IFNULL(p_skill_description,skill_description)
                ,type = IFNULL(p_type,type)
                ,updatedAt = NOW()  
                WHERE sid = v_sid;
                
                SET v_errcode = 0;
                SET v_errmsg = 'Skill updated successfully';
  	
			END IF;   
       
	SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
