/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_socialMedia_missed_dtl`(
  	 p_domainId 			INT
  	,p_HistoryId			INT
	,p_type					VARCHAR(100)
  )
begin
  
  	DECLARE v_errcode 				INT DEFAULT -1;
  	DECLARE v_errmsg  				VARCHAR(250) DEFAULT 'SocialMedia isMissed updated fail';
  	DECLARE v_WhatsappHistoryId  	INT;
  	DECLARE v_FacebookHistoryId  	INT;
    DECLARE v_InstagramHistoryId 	INT;
    DECLARE v_missedDispositionId 	INT;
  
	SELECT did INTO v_missedDispositionId  
	FROM disposition_status 
    WHERE domainId = p_domainId
    AND dispositionName = 'Missed';
  
	if p_type = 'Whatsapp' then
		SELECT WH.WhatsappHistoryId INTO v_WhatsappHistoryId
		FROM tb_WhatsappHistory	 		WH
		JOIN tb_WhatsappDurationHistory WD ON WH.WhatsappHistoryId = WD.WhatsappHistoryId
		WHERE WH.WhatsappHistoryId 	= p_HistoryId
		AND   WH.domainId 			= p_domainId;
	end if;

	if p_type = 'Facebook' then
		SELECT FH.FacebookHistoryId INTO v_FacebookHistoryId
		FROM tb_FacebookHistory	 	FH
		WHERE FH.FacebookHistoryId 	= p_HistoryId
		AND   FH.domainId 			= p_domainId;
	end if;
    
    if p_type = 'Instagram' then
		SELECT FH.InstagramHistoryId INTO v_InstagramHistoryId
		FROM tb_InstagramHistory	 	FH
		WHERE FH.InstagramHistoryId 	= p_HistoryId
		AND   FH.domainId 			= p_domainId;
	end if;
    
      IF  v_WhatsappHistoryId IS NOT NULL AND p_type = 'Whatsapp' THEN  
  		UPDATE 	tb_WhatsappHistory
  		SET 	IsSessionClosed 	= 1
        ,dispositionId		= v_missedDispositionId
  		WHERE 	WhatsappHistoryId 	= v_WhatsappHistoryId;
  		
  		UPDATE 	tb_WhatsappDurationHistory 	WD
		JOIN 	tb_WhatsappHistory			WH ON WD.WhatsappHistoryId = WH.WhatsappHistoryId
  		SET 	WD.IsMissed 			= 1 
  		WHERE 	WD.WhatsappHistoryId 	= v_WhatsappHistoryId;
  		
  		SET v_errcode = 0;
  		SET v_errmsg = 'SocialMedia isMissed updated successfully';
          
  	ELSEIF v_FacebookHistoryId IS NOT NULL AND p_type = 'Facebook' THEN  
      
  		UPDATE 	tb_FacebookHistory
  		SET 	IsSessionClosed 	= 1
          ,		IsMissed			= 1
          ,		dispositionId		= v_missedDispositionId
  		WHERE 	FacebookHistoryId 	= v_FacebookHistoryId;
          
		SET v_errcode = 0;
		SET v_errmsg = 'SocialMedia isMissed updated successfully';
        
	ELSEIF v_InstagramHistoryId IS NOT NULL AND p_type = 'Instagram' THEN  
    
  		UPDATE 	tb_InstagramHistory
  		SET 	IsSessionClosed 	= 1
          ,		IsMissed			= 1
          ,		dispositionId		= v_missedDispositionId
  		WHERE 	InstagramHistoryId 	= v_InstagramHistoryId;
          
		SET v_errcode = 0;
		SET v_errmsg = 'SocialMedia isMissed updated successfully';

     END IF;
     
     SELECT v_errcode as errcode,v_errmsg as errmsg;
  
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
