CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_task_reminder_status`(
	 p_domainId			INT
    ,p_taskId			INT
	,p_isClosed			TINYINT(1)
)
BEGIN

    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg  VARCHAR(150) DEFAULT 'Update Failed';
    DECLARE v_rid INT;

	SELECT rid INTO v_rid
    FROM tb_ccaas_ai_task_reminder
    WHERE domainId 	= p_domainId
    AND rid 		= p_taskId;
    
    IF v_rid IS NOT NULL
    THEN
		UPDATE tb_ccaas_ai_task_reminder
        SET isClosed 	= p_isClosed
        ,updatedAt		= NOW()
        WHERE rid = v_rid;
		
        SET v_errcode = 1;
        SET v_errmsg  = 'Updated successfully';
	END IF;
    
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
