     p_ext 			INT
  )
BEGIN
      DECLARE v_errCode TINYINT DEFAULT -1;
      DECLARE v_errMsg VARCHAR(150) DEFAULT 'Update user failed';
      DECLARE v_UserID INT;
      
      SELECT UserID INTO v_UserID
      FROM tb_User
      WHERE ext = p_ext AND domainId = p_domainId;
  
