CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_user_details`(
	 p_UserID			INT
    ,p_domainId			INT 
	,p_emp_id      		VARCHAR(20) 
	,p_UserName    		VARCHAR(255)
	,p_emailId     		VARCHAR(255)
	,p_directNumber		BIGINT      
	,p_roleid      		TINYINT     
	,p_localization		VARCHAR(20) 
	,p_chatLimit   		SMALLINT    
	,p_callTypeId    	INT         
)
begin

	DECLARE v_UserID	INT;
	DECLARE v_errcode 	INT DEFAULT -1;
	DECLARE v_errmsg 	VARCHAR(100) DEFAULT 'Update Fail';

	SELECT UserID INTO v_UserId
    FROM tb_User
    WHERE domainId = p_domainId
    AND UserID = p_UserID;
    
    IF v_UserId IS NOT NULL
    THEN
		UPDATE tb_User
        SET emp_id 			=IFNULL(p_emp_id,emp_id),
			UserName 		=IFNULL(p_UserName,UserName),
			emailId 		=IFNULL(p_emailId,emailId),
			directNumber	=IFNULL(p_directNumber,directNumber),
			roleid 			=IFNULL(p_roleid,roleid),
			localization	=IFNULL(p_localization,localization),
			chatLimit 		=IFNULL(p_chatLimit,chatLimit),
			callTypeId 		=IFNULL(p_callTypeId,callTypeId)
        WHERE UserID = v_UserId;
        
        SET v_errcode = 1;
        SET v_errmsg = 'Updated Successfully';
   
   END IF;
    
    SELECT v_errcode as errcode,v_errmsg as errmsg;

end ;;
DELIMITER ;
