CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_update_user_Prompt_library`(
p_uuid			INT
,p_domainId		INT
,p_url			LONGTEXT
,p_name			VARCHAR(100)
,p_description	VARCHAR(255)
,p_type			VARCHAR(100)
,p_message		VARCHAR(3000)
)
BEGIN	
	DECLARE v_errCode	TINYINT DEFAULT -1;
    DECLARE v_errMsg	VARCHAR(200) DEFAULT 'Prompt library update failed';
    
	DECLARE exit handler for SQLEXCEPTION
	BEGIN		
		SELECT v_errCode AS errCode, v_errMsg AS errMsg;
		ROLLBACK;
	END;
	START TRANSACTION;
		UPDATE 	prompt_library 
		SET 	url 			= IFNULL(p_url,url)
			,	`name` 			= IFNULL(p_name,`name`)
			,	`description` 	= IFNULL(p_description,`description`)
			, 	`type` 			= IFNULL(p_type,`type`)
            ,	message			= IFNULL(p_message,message)
			,	updateddAt 		= NOW()
		WHERE 	uuid 			= p_uuid
        AND 	domainId		= p_domainId;
        
        IF ROW_COUNT() > 0
        THEN
			SET v_errCode 	= 1
			,	v_errMsg	= 'Prompt library updated successfully';	
        END IF;
        
        SELECT v_errCode AS errCode, v_errMsg AS errMsg;
    COMMIT;
END ;;
DELIMITER ;
