CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_voiceMail_callBack`(
	 p_sessionId		varchar(500)
    ,p_domainId			int

)
begin
		
        DECLARE v_CallHistoryId INT;
        DECLARE v_errcode 		INT DEFAULT -1;
        DECLARE v_errmsg 		VARCHAR(100) DEFAULT 'VoiceMail callBack update fail';
		
        SELECT 	CallHistoryId into v_CallHistoryId
        FROM 	tb_CallHistory
        WHERE 	sessionId 	= p_sessionId
        AND		domainId	= p_domainId;

		UPDATE 	tb_CallHistory
		SET 	isVMCallBackCompleted =	1
        ,		updatedAt = now()
		WHERE 	CallHistoryId = v_CallHistoryId;

		IF ROW_COUNT()>0
        THEN
			SET v_errcode 	= 0;
			SET v_errmsg 	= 'VoiceMail callBack update successfully';
        END IF;

		SELECT v_errcode as errcode,v_errmsg as errmsg;
end ;;
