CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_update_whatsapp_callback_status`(
	 p_domainId 			INT
    ,p_WhatsappHistoryId 	INT
)
begin

	DECLARE v_errcode 				INT DEFAULT -1;
    DECLARE v_errmsg  				VARCHAR(100) DEFAULT 'WhatsApp callback status update fail';
    DECLARE v_WhatsappHistoryId  	INT;
    
    SELECT 	WhatsappHistoryId INTO v_WhatsappHistoryId
    FROM 	tb_WhatsappHistory
    WHERE 	WhatsappHistoryId 	= p_WhatsappHistoryId
    AND		domainId 			= p_domainId;
	
	IF v_WhatsappHistoryId IS NOT NULL
    THEN 
		UPDATE tb_WhatsappHistory
		SET isCallback 		= 1
        ,	callbackDraft 	= 0
		WHERE WhatsappHistoryId = v_WhatsappHistoryId;
    
		UPDATE 	tb_WhatsappDurationHistory 	WD
		JOIN 	tb_WhatsappHistory			WH ON WD.WhatsappHistoryId = WH.WhatsappHistoryId
		SET 	WD.IsMissed 			= 1 
		WHERE 	WD.WhatsappHistoryId 	= v_WhatsappHistoryId;
    
    SET v_errcode = 0;
    SET v_errmsg  = 'WhatsApp callback status update successfully';
   
   END IF;
   
   SELECT v_errcode as errcode,v_errmsg as errmsg;
    
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
