CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_userUpdate_info`(
     p_emailId 					VARCHAR(100)
     ,p_domainId 				INT
     ,p_isVoice 				TINYINT
     ,p_isChat 					TINYINT
     ,p_isEmail 				TINYINT
     ,p_isSms 					TINYINT
     ,p_isSocialMedia 			TINYINT
     ,p_chatLimit				SMALLINT
     ,p_pri_language			VARCHAR(100)
     ,p_sec_language			VARCHAR(1000)
     ,p_inboundCall				TINYINT
     ,p_outboundCampaignCall 	TINYINT
     ,p_outboundCall			TINYINT
     ,p_role_id					INT 
     ,p_UserName				VARCHAR(150)
 )
BEGIN
			DECLARE v_errcode int default -1;
			DECLARE v_errmsg varchar(100) default 'Failure';
			DECLARE v_UserID int;
            DECLARE v_ext INT;
            DECLARE v_aid INT;
             
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		SELECT 	a.UserID,a.ext INTO v_UserID,v_ext
			FROM 	tb_User a
 			WHERE 	emailId COLLATE utf8mb4_0900_ai_ci= p_emailId
 			AND 	domainId = p_domainId;
            
            SELECT aid INTO v_aid
            FROM tb_userAddonLanguageInfo
            WHERE 	domainId = p_domainId
            AND		ext		 = v_ext
            AND		userId	 = v_UserID;
            
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;          
     
     		IF v_UserID IS NOT NULL
             THEN
     			UPDATE tb_User a
     			SET  a.voice 				= ifnull(p_isVoice,a.voice)
     				,a.isVoice 				= ifnull(p_isVoice,a.isVoice)
     				,a.chat 				= ifnull(p_isChat,a.chat)
     				,a.email 				= ifnull(p_isEmail,a.email)
     				,a.sms 					= ifnull(p_isSms,a.sms)
     				,a.socialMedia 			= ifnull(p_isSocialMedia,a.socialMedia)
 					,a.chatLimit			= IFNULL(p_chatLimit,0)
     				,a.updatedAt 			= now()  
     				,a.inboundCall 			= IFNULL(p_inboundCall,inboundCall)
     				,a.callTypeId 			= IFNULL(p_outboundCall,callTypeId)
     				,a.outboundCampaignCall = IFNULL(p_outboundCampaignCall,outboundCampaignCall) 
                    ,a.roleid				= IFNULL(p_role_id,a.roleid)
                    ,a.UserName				= IFNULL(p_UserName,a.UserName)
     			WHERE a.UserID				= v_UserID;   
                
                IF v_aid IS NOT NULL
                THEN
					UPDATE tb_userAddonLanguageInfo
					SET pri_language 		= IFNULL(p_pri_language,pri_language)
					,	sec_language 		= IFNULL(p_sec_language,sec_language)
					,	updatedAt			= now()
					WHERE userId 			= v_UserID;
				ELSE 
					INSERT INTO tb_userAddonLanguageInfo(domainId,userId,ext,pri_language,sec_language,createdAt,updatedAt)
					VALUES(p_domainId,v_UserID,v_ext,p_pri_language,p_sec_language,now(),now());
				END IF;
     			set v_errcode = 0;
     			set v_errmsg = 'Success';
       END IF;   
       
	SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
