CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_user_create_voice_record_info`(
   p_domainId		int
  ,p_sessionId		varchar(250)
  ,p_recordUrl 		text
  ,p_recordSize 	varchar(55) 
  ,p_startTime		bigint
  ,p_endTime		bigint
  ,p_duration 		varchar(255)
  ,p_isDirection	tinyint 
  ,p_agentId		int
  ,p_customerNumber	varchar(100)
  ,p_externalNumber	varchar(25)
  )
begin 
     
		DECLARE v_errcode 	INT default -1;
		DECLARE v_errmsg 	VARCHAR(255) default 'Voice record info insert failed';
        DECLARE v_UserID	INT DEFAULT 0;
        
     IF (p_agentId IS NOT NULL OR p_agentId <> 0)
     THEN
        SELECT 	UserID INTO v_UserID
        FROM 	tb_User
        WHERE 	domainId 	= p_domainId
        AND		ext			= p_agentId;
	END IF;
    
		INSERT INTO tb_user_voice_record_info(domainId,sessionId,recordUrl,recordSize,startTime,endTime,duration,isDirection,agentId,customerNumber,externalNumber,createdAt)
    	VALUES (p_domainId,p_sessionId,p_recordUrl,p_recordSize,p_startTime,p_endTime,p_duration,p_isDirection,v_UserID,p_customerNumber,p_externalNumber,now());
    				
		IF ROW_COUNT() > 0
		THEN
			SET v_errcode = 0;
			SET v_errmsg = 'Voice record info inserted successfully';
		END IF;    
                    
          SELECT v_errcode AS errcode,v_errmsg AS errmsg;          
         
     end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
