CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_user_login_check_validation`(
	p_EmailId		VARCHAR(250) 
    ,p_isAvailable	VARCHAR(50)
)
begin

	DECLARE v_errcode TINYINT DEFAULT -1;
	DECLARE v_errmsg  VARCHAR(100) DEFAULT 'User Not Available';

	IF p_isAvailable = 'AICCAAS'
    THEN
		IF EXISTS(select 1 from tb_User where emailId = p_EmailId)
        THEN
			SET v_errcode 	= 1;
			SET v_errmsg	= 'AICCAAS User Available';
		END IF;
    END IF;
    
    IF p_isAvailable = 'CCAAS'
    THEN
		
        IF EXISTS(select 1 from ccaas2023.tb_User where emailId = p_EmailId)
        THEN
			SET v_errcode 	= 1;
            SET v_errmsg	= 'CCAAS User Available';
        END IF;
	END IF;
    
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;
    
end ;;
DELIMITER ;
