CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_videomeet_user_create_record_info`(
   p_meetingId 		varchar(55) 
  ,p_domainId		int
  ,p_sessionId		varchar(250)
  ,p_recordUrl 		text
  ,p_recordFile 	text
  ,p_recordSize 	varchar(55) 
  ,p_thumbnailUrl 	text
  ,p_startTime		bigint
  ,p_endTime		bigint
  ,p_duration 		varchar(255)
  ,p_isDirection	tinyint 
  ,p_agentId		int
  ,p_customerNumber	varchar(100)
  )
begin 
     
		declare v_errcode int default -1;
		declare v_errmsg varchar(255) default 'Record info insert failed';

		insert into tb_videomeet_user_record_info(meetingId,domainId,sessionId,recordUrl,recordFile,recordSize,thumbnailUrl,startTime,endTime,duration,isDirection,agentId,customerNumber,createdAt)
    	values (p_meetingId,p_domainId,p_sessionId,p_recordUrl,p_recordFile,p_recordSize,p_thumbnailUrl,p_startTime,p_endTime,p_duration,p_isDirection,p_agentId,p_customerNumber,now());
    				
		if row_count() > 0
		then
			set v_errcode = 0;
			set v_errmsg = 'Record info inserted successfully';
		end if;    
                    
          select v_errcode as errcode,v_errmsg as errmsg;          
         
     end ;;
DELIMITER ;
