CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccaas_videomeet_user_get_record_info`(
      p_domainId     INT,
      p_search       VARCHAR(100),
      p_direction    TINYINT,    
      p_startDate    BIGINT,
      p_endDate      BIGINT,
      P_agentId		INT,
      P_offset       INT,
      P_limit		INT
 )
BEGIN
 	
     DECLARE v_StartDate BIGINT;
     DECLARE v_EndDate BIGINT;
     DECLARE v_isVideo TINYINT;
     DECLARE v_offset SMALLINT;
     
     set v_offset = P_offset * P_limit;
     
     SET SESSION sort_buffer_size = 1024 * 1024 * 4;
     
     IF p_startDate IS NULL 
     THEN
 		SELECT min(startTime),max(endTime) INTO v_StartDate,v_EndDate
 		FROM tb_videomeet_user_record_info WHERE domainId = p_domainId;
     ELSE 
 		SET v_StartDate = p_startDate;
         SET v_EndDate	= p_endDate;
 	END IF;
     
 	
 	select isVideoAgentAccess into v_isVideo
 	from ccaas_settings_voice_video_recording_dtl
 	where domainId = p_domainId;
 
     DROP TEMPORARY TABLE IF EXISTS tt_customer_contact;
     CREATE TEMPORARY TABLE tt_customer_contact AS
     SELECT 	primaryPhoneNumber,firstName,lastName
     FROM 	customer_contact
     WHERE 	domainId = p_domainId
     AND		primaryPhoneNumber IS NOT NULL;
         
     DROP TEMPORARY TABLE IF EXISTS tt_videomeet_user_record;
     CREATE TEMPORARY TABLE tt_videomeet_user_record AS
     SELECT 	UR.rid,UR.meetingId,UR.domainId,UR.sessionId,UR.recordUrl,UR.recordFile,UR.recordSize,UR.thumbnailUrl,UR.startTime
 			,UR.endTime,UR.duration,CASE WHEN UR.isDirection = 1 THEN 'Inbound' ELSE 'Outbound' END AS direction,UR.isDirection,UR.agentId,UR.customerNumber,UR.createdAt,U.UserName AS agentName,
 			CASE WHEN TRIM(CONCAT(CC.firstName, ' ', CC.lastName)) <> '' THEN CONCAT(CC.firstName, ' ', CC.lastName) ELSE 'New Customer' END AS customerName,
 			UR.videoRecordingcc
     FROM tb_videomeet_user_record_info 	UR
 	JOIN tb_User 						U 	ON UR.agentId = U.UserID AND UR.domainId = U.domainId
 	JOIN tb_VideoHistory				VH  ON VH.meetingId				= UR.meetingId
 	JOIN customer_contact				CC 	ON CC.coid 					= VH.CustomerId
     WHERE UR.domainId = p_domainId;
     
 IF P_agentId IS NOT NULL AND v_isVideo = 1
 THEN
 	SELECT count(*) as recordCount
     FROM 	tt_videomeet_user_record
     WHERE 	agentId = P_agentId
     AND		startTime BETWEEN v_StartDate AND v_EndDate
     
     AND (ifnull(agentName,'New customer') collate utf8mb4_unicode_ci LIKE concat('%',p_search,'%') OR ifnull(customerName,'New customer') collate utf8mb4_unicode_ci  LIKE  concat('%',p_search,'%') OR ifnull(p_search,'') = '')  
     AND		(isDirection collate utf8mb4_unicode_ci = p_direction OR IFNULL(p_direction,'')= '' );
     
     SELECT distinct rid,meetingId,domainId,sessionId,recordUrl,recordFile,recordSize,thumbnailUrl,startTime,endTime,duration
 	,direction,isDirection,agentId,customerNumber,createdAt,agentName,customerName,videoRecordingcc
     FROM 	tt_videomeet_user_record
     WHERE 	
     (ifnull(agentName,'New customer') collate utf8mb4_unicode_ci LIKE concat('%',p_search,'%') OR ifnull(customerName,'New customer') collate utf8mb4_unicode_ci  LIKE  concat('%',p_search,'%') OR ifnull(p_search,'') = '')  
     AND		(isDirection collate utf8mb4_unicode_ci = p_direction OR IFNULL(p_direction,'')= '' )
     AND		startTime BETWEEN v_StartDate AND v_EndDate
     AND		agentId = P_agentId
     ORDER BY createdAt DESC
     LIMIT v_offset, P_limit
     ;
     
 ELSEIF P_agentId IS NULL
 THEN    
 
 	SELECT count(*) as recordCount
     FROM 	tt_videomeet_user_record
     WHERE	startTime BETWEEN v_StartDate AND v_EndDate
     
     AND (ifnull(agentName,'New customer') collate utf8mb4_unicode_ci LIKE concat('%',p_search,'%') OR ifnull(customerName,'New customer') collate utf8mb4_unicode_ci  LIKE  concat('%',p_search,'%') OR ifnull(p_search,'') = '')  
     AND		(isDirection collate utf8mb4_unicode_ci = p_direction OR IFNULL(p_direction,'')= '' );
     
 	SELECT distinct rid,meetingId,domainId,sessionId,recordUrl,recordFile,recordSize,thumbnailUrl,startTime,endTime,duration
 	,direction,isDirection,agentId,customerNumber,createdAt,agentName,customerName,videoRecordingcc
     FROM 	tt_videomeet_user_record
     WHERE 
     (ifnull(agentName,'New customer') collate utf8mb4_unicode_ci LIKE concat('%',p_search,'%') OR ifnull(customerName,'New customer') collate utf8mb4_unicode_ci  LIKE  concat('%',p_search,'%') OR ifnull(p_search,'') = '')  
     AND		(isDirection collate utf8mb4_unicode_ci = p_direction OR IFNULL(p_direction,'')= '' )
     AND		startTime BETWEEN v_StartDate AND v_EndDate
     ORDER BY createdAt DESC
     LIMIT v_offset, P_limit
     ;
 ELSE 	
 		SELECT -1 as 'errcode' , 'No data found' as errmsg;
 END IF;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_videomeet_user_get_specific_record_info` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_videomeet_user_get_specific_record_info`(
		 p_domainId		int
        ,p_sessionId 	varchar(250)
)
begin

		SELECT UR.rid,UR.meetingId,UR.domainId,UR.sessionId,UR.recordUrl,UR.recordFile,UR.recordSize,UR.thumbnailUrl,UR.startTime,UR.endTime,UR.duration,UR.isDirection
				,UR.agentId,UR.customerNumber,UR.createdAt,U.UserName AS agentName,CASE WHEN trim(CONCAT(CC.firstName, ' ',CC.lastName)) <> ''  THEN CONCAT(CC.firstName, ' ',CC.lastName)	ELSE 'New Customer' END as customerName  
                ,UR.videoRecordingcc,VDH.SentimentalScore
		FROM 	tb_videomeet_user_record_info 	UR
        JOIN	tb_User							U	ON UR.agentId = U.UserID
        JOIN	tb_VideoHistory					VH 	ON VH.meetingId 			= UR.meetingId
        JOIN	tb_VideoDurationHistory			VDH ON VH.VideoHistoryId 		= VDH.VideoHistoryId
		JOIN 	customer_contact				CC 	ON CC.coid 					= VH.CustomerId
		WHERE 	UR.domainId 	= p_domainId
        AND		UR.sessionId 	= p_sessionId;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
