CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_voice_user_delete_record_info`(
 	 p_domainId		INT
 	,p_rid       	INT
     )
begin    
 	DECLARE v_errcode 	INT DEFAULT -1;
 	DECLARE v_errmsg 	VARCHAR(150) DEFAULT 'Recording deleted failed';
    DECLARE v_rid		INT;
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
		select rid into v_rid
		from tb_user_voice_record_info
		where domainId = p_domainId  
		and rid = p_rid;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	

	IF v_rid IS NOT NULL
    THEN
		DELETE
 		FROM 	tb_user_voice_record_info
 		WHERE 	rid 	= v_rid;
 		
 		SET v_errcode = 0 , v_errmsg = 'Recording deleted successfully';
 	END IF;
             
 	SELECT v_errcode as errcode , v_errmsg as errmsg;
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
