CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_voice_user_get_record_info`(
 	p_domainId		INT
 	,p_search       VARCHAR(100)
 	,p_direction    TINYINT    
 	,p_startDate    BIGINT
 	,p_endDate      BIGINT
 	,P_agentId		INT
 	,P_limit        INT
 	,P_offset      INT
     )
sp_exit:begin    
 	DECLARE v_StartDate DATE;
 	DECLARE v_EndDate DATE;
 	DECLARE v_isVoice TINYINT;
 	DECLARE v_Offset int;
    
    set v_Offset = P_offset * P_limit;
 
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 	IF p_startDate IS NULL 
 	THEN
 		SELECT min(DATE(FROM_UNIXTIME(startTime))),max(DATE(FROM_UNIXTIME(endTime))) INTO v_StartDate,v_EndDate
 		FROM tb_user_voice_record_info WHERE domainId = p_domainId limit 1;
 	ELSE 
 		SELECT DATE(FROM_UNIXTIME(p_startDate/1000)) INTO v_StartDate;
 		SELECT DATE(FROM_UNIXTIME(p_endDate/1000)) INTO v_EndDate;
 	END IF;
 
 	select isVoiceAgentAccess into v_isVoice
 	from ccaas_settings_voice_video_recording_dtl
 	where domainId = p_domainId  limit 1;
 	
 	SET v_isVoice = IFNULL(v_isVoice,0);
 	
 	UPDATE	tb_user_voice_record_info	V
 	JOIN 	tb_CallHistory 				C	ON 	C.sessionId	= V.sessionId
 											AND	V.domainId	= C.domainId	
 	SET		V.HistoryId	= C.CallHistoryId            
 	WHERE 	V.HistoryId IS NULL
 	AND 	V.domainId	= p_domainId;            
 			

 	DROP TEMPORARY TABLE IF EXISTS tt_CallHistoryIds;
 	CREATE TEMPORARY TABLE tt_CallHistoryIds AS
 	WITH CTE AS (
 		SELECT 	VR.rid						
 				,VR.domainId
 				,VR.recordUrl
 				,VR.recordSize
 				,VR.startTime
 				,VR.endTime
 				,VR.duration
 				,VR.isDirection
 				,VR.agentId
 				,VR.customerNumber
 				,VR.createdAt
 				,VR.HistoryId	AS		CallHistoryId
 				,CDH.CallDurationHistoryId    
 				,VR.sessionId
 				,row_number() over(partition by VR.HistoryId order by CDH.CallDurationHistoryId desc) as RN
 				,CH.CustomerId
                ,CDH.SentimentalScore
                ,CDH.subject
                ,CDH.summary
 		FROM 	tb_user_voice_record_info 	VR      
 		JOIN 	tb_CallHistory				CH	ON VR.HistoryId 	= CH.CallHistoryId 
 		JOIN 	tb_CallDurationHistory 		CDH ON CH.CallHistoryId = CDH.CallHistoryId 
 		WHERE 	VR.domainId 	= p_domainId
 		AND 	DATE(FROM_UNIXTIME(VR.startTime))	BETWEEN v_StartDate AND v_EndDate     
 		AND 	((v_isVoice = 1 AND VR.agentId = IFNULL(P_agentId,VR.agentId)) OR v_isVoice = 0)                
 		AND		(isDirection = p_direction OR p_direction IS NULL)
 	)
 	SELECT  *
 	FROM 	CTE 
 	WHERE 	RN = 1;            
          
 	DROP TEMPORARY TABLE IF EXISTS tt_voicemeet_user_record;
 	CREATE TEMPORARY TABLE tt_voicemeet_user_record AS           
 	SELECT 	t_CH.*
 			,U.UserName AS agentName
 			,CASE WHEN TRIM(CONCAT(CC.firstName, ' ',CC.lastName)) <> ''  THEN CONCAT(CC.firstName, ' ',CC.lastName) ELSE 'New Customer' END as customerName
 			,CM.Message                        
 	FROM 	tt_CallHistoryIds	t_CH	
 	JOIN 	tb_User				U	ON 	t_CH.agentId 		= U.UserID 
 									AND t_CH.domainId 		= U.domainId			
 	JOIN 	customer_contact	CC 	ON 	CC.coid				= t_CH.CustomerId 
 									AND CC.domainId 		= t_CH.domainId
 	LEFT JOIN tb_CallMessage 	CM 	ON 	t_CH.CallDurationHistoryId 	= CM.CallDurationHistoryId 	
    WHERE U.domainId = p_domainId;
 	
    
 	IF EXISTS (SELECT 1 FROM tt_voicemeet_user_record LIMIT 1)
 	THEN
 		SELECT 	COUNT(rid) as recordCount
 		FROM 	tt_voicemeet_user_record;
 		
 		SELECT 	`rid`, `domainId` , `sessionId`, `recordUrl` ,`recordSize`, `startTime`,`endTime` , `duration`, `isDirection`,
 				`agentId`, `customerNumber`, `createdAt` , `agentName` , `customerName`,`Message`,`SentimentalScore`,`subject`,`summary` 
 		FROM 	tt_voicemeet_user_record
        where (ifnull(agentName,'New customer') COLLATE utf8mb4_0900_ai_ci LIKE concat('%',p_search,'%') OR ifnull(customerName,'New customer')  COLLATE utf8mb4_unicode_ci LIKE  concat('%',p_search,'%') OR customerNumber  COLLATE utf8mb4_unicode_ci LIKE  concat('%',p_search,'%') OR ifnull(p_search,'') = '')  
        
 		ORDER BY createdAt DESC
 		LIMIT v_Offset, P_limit;
 	ELSE
 		SELECT -1 as 'errcode' , 'No data found' as errmsg;
 	END IF;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
             
 	drop temporary table if exists tt_CallHistoryIds;
 	DROP TEMPORARY TABLE IF EXISTS tt_voicemeet_user_record;
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccaas_voice_user_get_specific_record_info` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_voice_user_get_specific_record_info`(
		p_domainId		int
	 ,	p_sessionId 	varchar(250)
)
begin
		
         drop temporary table if exists tt_callMessage;
		create temporary table tt_callMessage
        with CTE as (
			select CM.Message,CH.CallHistoryId,CM.CallDurationHistoryId,CH.sessionId,
			row_number() over(partition by CallHistoryId order by CallDurationHistoryId desc) as RN
			from tb_CallHistory 			CH 
		    join tb_user_voice_record_info 	VR ON CH.sessionId = VR.sessionId
			LEFT join tb_CallMessage 			CM ON CH.CallHistoryId = CM.CallHistoryId
			WHERE CH.domainId = p_domainId
        )
        select * from CTE where RN = 1;
        


		
        DROP TEMPORARY TABLE IF EXISTS tt_voice_record;
        CREATE TEMPORARY TABLE tt_voice_record AS 
		SELECT R.rid,R.domainId,R.sessionId,R.recordUrl,R.recordSize,R.startTime,R.endTime,R.duration,R.isDirection,R.agentId,R.customerNumber
        ,R.createdAt,U.UserName AS agentName,CASE WHEN trim(CONCAT(CC.firstName, ' ',CC.lastName)) <> ''  THEN CONCAT(CC.firstName, ' ',CC.lastName)	ELSE 'New Customer' END as customerName    
        ,TT.Message
		FROM 	tb_user_voice_record_info		R
        JOIN	tb_User							U	ON R.agentId = U.UserID
        JOIN	tb_CallHistory					CH  ON CH.sessionId				= R.sessionId
        JOIN	customer_contact				CC 	ON CC.coid 					= CH.CustomerId
        JOIN 	tt_callMessage					TT  ON TT.sessionId				= R.sessionId 
		WHERE 	R.domainId 		= p_domainId
        AND		R.sessionId 	= p_sessionId;
        
        
         
        DROP TEMPORARY TABLE IF EXISTS tt_voice_record_final;
        CREATE TEMPORARY TABLE tt_voice_record_final AS  
        SELECT 	tt.rid,tt.domainId,tt.sessionId,tt.recordUrl,tt.recordSize,tt.startTime,tt.endTime,tt.duration,tt.isDirection,tt.agentId
		,tt.customerNumber,tt.createdAt,tt.agentName,tt.customerName,tt.Message,CDH.CallDurationHistoryId,CDH.subject,CH.CallHistoryId,CDH.SentimentalScore,
        row_number() over(partition by CallHistoryId order by CallDurationHistoryId desc) as RN
		FROM	tt_voice_record 			tt
        JOIN 	tb_CallHistory 				CH 	ON tt.sessionId			= CH.sessionId
        JOIN 	tb_CallDurationHistory 		CDH ON CH.CallHistoryId 	= CDH.CallHistoryId;
        
        
        
		SELECT rid,domainId,sessionId,recordUrl,recordSize,startTime,endTime,duration,isDirection,agentId
		,customerNumber,createdAt,agentName,customerName,Message,SentimentalScore,subject
        FROM tt_voice_record_final 
        WHERE RN = 1;
        
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
