CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccaas_whatsAppMasterInsert`(
p_idcol					INT,
p_requestID				VARCHAR(100),
p_agentNumber	 		VARCHAR(30),
p_customerNumber	 	VARCHAR(30),
p_enabled				VARCHAR(10),
p_status				VARCHAR(50),
p_Timestamp	 			BIGINT,
p_sentTimestamp	 		BIGINT,
p_deliveredTimestamp	BIGINT,
p_readTimetamp	 		BIGINT,
p_mediajson	 			JSON,
p_msgtype	 			VARCHAR(50),
p_conversation	 		JSON,
p_pricing	 			JSON,
p_createdAt	 			DATETIME,
p_updateAt	 			DATETIME,
p_customerName	 		VARCHAR(30),
p_msgtext	 			TEXT
)
BEGIN
	declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'Error : Not inserted';
    declare v_curdate datetime;
    
    set v_curdate=now();

INSERT INTO whatsapp_Integration_master_dtl(

		requestID,
		agentNumber,
		customerNumber,
		enabled,
		`status`,
		`Timestamp`,
		sentTimestamp,
		deliveredTimestamp,
		readTimetamp,
		mediajson,
		msgtype,
		conversation,
		pricing,
		createdAt,
		updateAt,
		customerName,
		msgtext
)
VALUES(	p_requestID,
		p_agentNumber,
		p_customerNumber,
		p_enabled,
		p_status,
		p_Timestamp,
		p_sentTimestamp,
		p_deliveredTimestamp,
		p_readTimetamp,
		p_mediajson,
		p_msgtype,
		p_conversation,
		p_pricing,
		v_curdate,
		v_curdate,
		p_customerName,
		p_msgtext
);
	if row_count() >0 then
		set v_errcode=0;
        set v_errmsg='Success : Inserted';
    end if;

select v_errcode as errcode, v_errmsg as errmsg;

end ;;
DELIMITER ;
