CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccass_create_short_cut_key_details`(
   uuid varchar(255),    
   keyValues json,
   defaultKeys json,  
   domainId int,
   ext int,
   type varchar(255))
begin
    
    declare errcode int default  -1;
    declare errmsg varchar(255) default  'failure';
    
    	if not exists (select 1 from shortCutKey a where a.uuid = uuid limit 1)
        then
    		insert into shortCutKey(uuid,keyValues,defaultKeys,domainId,ext,createdAt,type)
    					values(uuid,keyValues,defaultKeys,domainId,ext,now(),type); 
    
    		if row_count() > 0 
            then 
    			set errcode = 0;
    			set errmsg = 'inserted : successfully';
            end if;         
            
    	end if;      
    
    select errcode as errcode,errmsg as errmsg;
    
    end ;;
