/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccass_getDetailsBySessionId_bkp_2026_02_11`(
        p_domainId INT, 
        p_channelType VARCHAR(10),
        p_sessionId varchar(250)    
        )
Begin
  	DECLARE v_emailAddress		varchar(200);
  	DECLARE v_your_number		varchar(255);
  	DECLARE v_ChatHistoryId		BIGINT;
          
     	 if p_channelType = 'Email' then
     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     		select  eh.EmailHistoryId, eh.sessionId, eh.SessionStartTime, eh.SessionEndTime, eh.FromEmail, eh.ToEmail, eh.EmailSubject, eh.EmailFlowSourceId, eh.CompanyId, eh.DomainId, eh.DispositionId as dispositionId, eh.Summary, eh.IsInBound, 
     				eh.AssignedTo, eh.AssignedBy, eh.AssignedOn, eh.AfterEmailWorkTime, eh.Istransferred, eh.TransferredTypeId, eh.IsSessionClosed, eh.CustomerId, eh.TicketId, eh.SupervisorName, eh.CreatedAt, eh.UpdatedAt, ed.AgentId, 
     				ed.AgentSkillId, ed.IsBot, ed.BotId, ed.QueueId, em.Message,'Email' as channelType,ds.dispositionName,ds.colorCode as dispositionColorCode,tu.UserName as AssignedToUserName
                     ,eh.threadMessageId
     		from tb_EmailHistory 				eh
     		left join tb_EmailDurationHistory 	ed on eh.EmailHistoryId = ed.EmailHistoryId
     		left join tb_EmailMessage			em on eh.EmailHistoryId = em.EmailHistoryId
     		left join disposition_status		ds on ds.did			= eh.dispositionId 
             left join tb_User 					tu ON tu.UserID 		= eh.AssignedTo and eh.domainId = tu.domainId
     		where eh.DomainId = p_domainId and eh.SessionId = p_sessionId;
          
          update tb_EmailHistory
           set isOpened = 1
           where SessionId = p_sessionId
           and DomainId = p_domainId;
          
     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     	 End if;
                                   
     	IF p_channelType = 'Chat' 
     	THEN 
     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            SET v_ChatHistoryId = p_sessionId;
            
            
            
     		SELECT 	emailAddress INTO v_emailAddress
     		FROM 	email_config 
     		WHERE 	domainId = p_domainId
     		LIMIT 1;
             
             
     
     		SELECT 	your_number	INTO v_your_number
     		FROM 	did_purchase 
     		WHERE 	domainId	= p_domainId
     		AND 	isSmsIn 	= 1 
     		AND 	isSmsOut 	= 1
             LIMIT 1
             ;   
             
             
     
     		select  cth.ChatHistoryId,cth.sessionId, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, ctdh.dispositionId, ctdh.Summary, cth.IsInBound, ctdh.answeredDuration, cth.disconnectedBy, 
     				cth.queueDuration, cth.assignedTo as AssignedTo, cth.assignedBy, cth.assignedOn,	Null AS waitDuration, ctdh.afterChatWorkTime, ctdh.Istransferred, Null AS transferredTypeId, ctdh.markAsRead, cth.CustomerId, ctdh.ticketId, Null AS CallBackDatetime, 
     				cth.Browser, cth.IPAdress, cth.ChatSubject, cth.createdAt, cth.updatedAt, ctdh.StartTime, ctdh.EndTime, ctdh.Duration, ctdh.AgentId, ctdh.AgentSkillId, ctdh.IsBot, ctdh.BotId, 
     				ctdh.transferredTime, ctdh.QueueId, ctm.Message,'Chat' as channelType,ds.dispositionName,ds.colorCode as dispositionColorCode,cth.Location,cth.DeviceType,cc.phoneNumber,cc.email,
     				cth.CallBackStatus, v_emailAddress AS companyEmailAddress, v_your_number AS companySMSNumber, ctdh.ChatDurationHistoryId,tu.UserName as AssignedToUserName
     		from 	tb_ChatHistory 				cth
     		left join tb_ChatDurationHistory 	ctdh 	on cth.ChatHistoryId 	= ctdh.ChatHistoryId
     		left join tb_ChatMessage			ctm 	on cth.ChatHistoryId 	= ctm.ChatHistoryId
     		left join disposition_status		ds 		on ds.did				= ctdh.dispositionId 
     		left join customer_contact			cc 		on cc.coid				= cth.CustomerId
             left join tb_User 					tu 		ON tu.UserID 			= cth.assignedTo and cth.domainId = tu.domainId
     		WHERE 	cth.domainId 		= p_domainId 
            and 	cth.ChatHistoryId	= v_ChatHistoryId;	
     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     	End if;
                                   
                    	IF p_channelType = 'Call' 
                      THEN  
                      
  						SELECT 	emailAddress INTO v_emailAddress
  						FROM 	email_config 
  						WHERE 	domainId = p_domainId
  						LIMIT 1;
  
  						SELECT 	your_number	INTO v_your_number
  						FROM 	did_purchase 
  						WHERE 	domainId	= p_domainId
  						AND 	isSmsIn 	= 1 
  						AND 	isSmsOut 	= 1 LIMIT 1;
                      
         				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                    		select 	clh.CallHistoryId,clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber, Null AS callFlowSourceId, Null AS companyId, clh.domainId, cld.dispositionId, cld.UMNStatus, clh.IsInBound, cld.answeredDuration, 
                    				clh.disconnectedBy, clh.queueDuration, clh.assignedTo as AssignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, cld.afterCallWorkTime, clh.recordingTypeId, Null AS Istransferred, Null AS transferredTypeId, cld.markAsRead, 
                    				clh.CustomerId, clh.voicemailUrl, cld.ticketId, clh.callDuration, cld.summary, cld.`subject`,clh.createdAt, clh.updatedAt, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, cld.AgentSkillId, cld.IsBot, cld.BotId, cld.RecordingUrl, 
                    				cld.transferredTime, cld.recordingDuration, cld.QueueId, clm.Message,'Call' as channelType,ds.dispositionName,ds.colorCode as dispositionColorCode, q.name as queueName,clh.callBack
                                  , v_emailAddress AS companyEmailAddress, v_your_number AS companySMSNumber,tu.UserName as AssignedToUserName
                    		from tb_CallHistory 					clh
                    		left join tb_CallDurationHistory 		cld on clh.CallHistoryId 	= cld.CallHistoryId
                    		left join tb_CallMessage				clm on clh.CallHistoryId 	= clm.CallHistoryId
                    		left join disposition_status			ds 	on ds.did				= cld.dispositionId 
           				left join queue							q	on cld.QueueId			= q.qid
                         left join tb_User 						tu ON tu.UserID 			= clh.assignedTo and clh.domainId = tu.domainId
                    		where clh.domainId = p_domainId and clh.SessionId = p_sessionId;
                         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                    	End if;
                                   
                   	if p_channelType = 'Sms' then 
         				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                  		select 	sh.SMSHistoryId,sh.sessionId, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.companyId, sh.domainId, sh.dispositionId, sh.Summary, sh.IsInBound, sh.assignedTo as AssignedTo, sh.assignedBy, sh.assignedOn, 
                 				sh.afterSMSWorkTime, sh.Istransferred, sh.transferredTypeId, sh.markAsRead, sh.IsSessionClosed, sh.customerNumber,sh.calledNumber, sh.ticketId, sh.supervisorName, sh.createdAt, sh.updatedAt, 
                 				sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sd.QueueId, sm.Message,'Sms' as channelType,ds.dispositionName,ds.colorCode as dispositionColorCode,tu.UserName as AssignedToUserName
                  		from tb_SMSHistory 					sh
                  		left join tb_SMSDurationHistory 	sd on sh.SMSHistoryId 	= sd.SMSHistoryId
                  		left join tb_SMSMessage				sm on sh.SMSHistoryId 	= sm.SMSHistoryId
 						left join disposition_status		ds on ds.did			= sh.dispositionId 
                         left join tb_User 					tu ON tu.UserID 		= sh.assignedTo and sh.domainId = tu.domainId
                  		where sh.domainId = p_domainId and sh.SessionId = p_sessionId;
                          
                          UPDATE tb_SMSHistory
  						SET isOpened = 1
  						WHERE SessionId = p_sessionId
  						and DomainId = p_domainId;
                          
                         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                   	End if;
                     
                     if p_channelType = 'Whatsapp' then 
         				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                      
  					SELECT 	emailAddress INTO v_emailAddress
  					FROM 	email_config 
  					WHERE 	domainId = p_domainId
  					LIMIT 1;
  
  					SELECT 	your_number	INTO v_your_number
  					FROM 	did_purchase 
  					WHERE 	domainId	= p_domainId
  					AND 	isSmsIn 	= 1 
  					AND 	isSmsOut 	= 1 LIMIT 1;   
          
                 		select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
                 				wh.afterwhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wh.createdAt, wh.updatedAt, 
                 				wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId, wm.Message,'Whatsapp'as channelType,wh.WhatsappHistoryId,ds.dispositionName,ds.colorCode as dispositionColorCode
                              ,wh.isCallback as callBack,v_emailAddress AS companyEmailAddress,v_your_number AS companySMSNumber,WhatsappDurationHistoryId,tu.UserName as AssignedToUserName
                 		from tb_WhatsappHistory 				wh
                 		left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId 	= wd.WhatsappHistoryId
                 		left join tb_WhatsappMessage			wm on wh.WhatsappHistoryId 	= wm.WhatsappHistoryId
 						left join disposition_status			ds on ds.did				= wh.dispositionId 
                         left join tb_User 						tu ON tu.UserID 			= wh.assignedTo and wh.domainId = tu.domainId
                 		where wh.domainId = p_domainId  and wh.SessionId = p_sessionId;
         			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
                     End if;
         
         			if p_channelType = 'Facebook' then 
         				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                      
                      SELECT 	emailAddress INTO v_emailAddress
  					FROM 	email_config 
  					WHERE 	domainId = p_domainId
  					LIMIT 1;
  
  					SELECT 	your_number	INTO v_your_number
  					FROM 	did_purchase 
  					WHERE 	domainId	= p_domainId
  					AND 	isSmsIn 	= 1 
  					AND 	isSmsOut 	= 1 
                      LIMIT 1;
                      
         				select 	fh.sessionId, fh.sessionStartTime, fh.sessionEndTime, fh.domainId, fh.dispositionId, fh.Summary, fh.IsInBound, fh.assignedTo, fh.assignedBy, fh.assignedOn, 
         						 fh.afterFacebookWorkTime, fh.Istransferred, fh.transferredTypeId, fh.IsSessionClosed, CAST(fh.customerFacebookId AS CHAR) AS customerFacebookId 
                               ,CAST(fh.agentFacebookId AS CHAR) AS agentFacebookId, fh.ticketId, fh.createdAt, fh.updatedAt, 
         						 fh.AgentId, fh.IsBot, fh.BotId, wm.Message,'Facebook'as channelType,fh.FacebookHistoryId,ds.dispositionName,ds.colorCode as dispositionColorCode
                              ,fh.isCallback as callBack,v_emailAddress AS companyEmailAddress,v_your_number AS companySMSNumber,tu.UserName as AssignedToUserName
         				from tb_FacebookHistory 		fh				
         				left join tb_FacebookMessage	wm ON fh.FacebookHistoryId 	= wm.FacebookHistoryId
         				left join disposition_status	ds ON ds.did				= fh.dispositionId 
                         left join tb_User 				tu ON tu.UserID 			= fh.assignedTo and fh.domainId = tu.domainId 
         				where fh.domainId = p_domainId  and fh.SessionId = p_sessionId;
         				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
         			End if;
                    
         			if p_channelType = 'Instagram' then 
         				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                         
 					SELECT 	emailAddress INTO v_emailAddress
  					FROM 	email_config 
  					WHERE 	domainId = p_domainId
  					LIMIT 1;
  
  					SELECT 	your_number	INTO v_your_number
  					FROM 	did_purchase 
  					WHERE 	domainId	= p_domainId
  					AND 	isSmsIn 	= 1 
  					AND 	isSmsOut 	= 1 
                      LIMIT 1;
                         
 					select 	fh.sessionId, fh.sessionStartTime, fh.sessionEndTime, fh.domainId, fh.dispositionId, fh.Summary, fh.IsInBound, fh.assignedTo, fh.assignedBy, fh.assignedOn, 
 							fh.afterInstagramWorkTime, fh.Istransferred, fh.transferredTypeId, fh.IsSessionClosed, fh.customerInstagramId,fh.agentInstagramId, fh.ticketId, fh.createdAt, fh.updatedAt, 
 							fh.AgentId, fh.IsBot, fh.BotId, wm.Message,'Instagram'as channelType,fh.InstagramHistoryId,ds.dispositionName,ds.colorCode as dispositionColorCode
 							,fh.isCallback as callBack,v_emailAddress AS companyEmailAddress,v_your_number AS companySMSNumber,tu.UserName as AssignedToUserName
 					from tb_InstagramHistory 		fh				
 					left join tb_InstagramMessage	wm ON fh.InstagramHistoryId 	= wm.InstagramHistoryId
 					left join disposition_status	ds ON ds.did					= fh.dispositionId 
                     left join tb_User 				tu ON tu.UserID 				= fh.assignedTo and fh.domainId = tu.domainId 
 					where fh.domainId = p_domainId  and fh.SessionId = p_sessionId;
 					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
         			End if;                         
         end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccass_get_callback_session_history_details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccass_get_callback_session_history_details`(	
       	p_domainId 			INT,
       	p_channelType 		VARCHAR(255),
       	p_fromDate 			BIGINT,
       	p_toDate 			BIGINT,
       	p_ext 				LONGTEXT,	
       	p_assigned_ext 		BIGINT, 	
       	p_search 			LONGTEXT,
       	`offset` 			INT,
       	`limit` 			INT,
        p_queueIDs	 		VARCHAR(250)
)
sp_return: BEGIN
    
   			DECLARE v_count 	INT;
   			DECLARE v_offset 	INT;
   			DECLARE v_limit 	INT;
   			DECLARE v_search 	INT;
   			DECLARE v_roleid 	INT;
   			DECLARE v_p_assigned_ext_no_email_chltype int;
            
            DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
			
            CALL split(p_queueIds,','); 
            
            INSERT INTO temp_queueIDs(queueId) 
            SELECT Items FROM tt_Split_temptable;

       
       
       
       						select roleid into v_roleid from tb_User where domainId = p_domainId  and UserID = p_assigned_ext limit 1;
                       
                       		SET v_offset = `offset` * `limit`;
                       
                       		IF p_fromDate IS NULL OR p_fromDate = '' 	THEN 	SET p_fromDate = 0; 							END IF;
                       		IF p_toDate IS NULL OR p_toDate = '' 		THEN	SET p_toDate = 0;								END IF;        
                       		IF p_channelType = 'All' 					THEN	SET p_channelType = NULL;						END IF;                    
                       
                       		DROP TEMPORARY TABLE IF EXISTS tt_temp_userid; 		CREATE TEMPORARY TABLE tt_temp_userid (ext VARCHAR(100));
                       		DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));
                                                   	
                       		CALL split(p_ext, ',');				INSERT INTO tt_temp_userid (ext)			SELECT Items FROM tt_Split_temptable;   
                       		CALL split(p_channelType, ','); 	INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;

                       		drop temporary table if exists temp_getcallback_list;
                       		create temporary table temp_getcallback_list
                       		(	id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber VARCHAR(20)						
                       			,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
                       			,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
                       			,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred tinyint default null		,transferredTypeId int default null			,markAsRead tinyint default null
                       			,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
                       			,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
                       			,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
                       			,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
                       			,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
                       			,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
                       			,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
                       			,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null 						,FacebookHistoryId	bigint				,afterFacebookWorkTime	int					,NextFlowNode	varchar(150)
                       			,transferredTo	bigint						,transferredDate	datetime				,dispositionUpdatedBy	bigint					,immediateParentId	bigint				,rootParentId	bigint						,discardedDate	datetime
                       			,repliedDate	datetime					,markAsReadSupervisor	tinyint				,markAsReadAgent	tinyint						,customerFacebookId	varchar(100)		,agentFacebookId	varchar(100)			,AgentStartTime	bigint
                       			,AgentEndTime	bigint						,SentimentalScore	float					,afterInstagramWorkTime int						,customerInstagramId bigint				,agentInstagramId	bigint					,InstagramCommunicationTypeId int
               					,InstagramHistoryId	bigint					,widgetId	INT								,isThresholdTimeExceeded		TINYINT			,remainingThresholdTime	VARCHAR(20)		,CallBackStatus		TINYINT					,emailconfigsupervisorName varchar(50)
                                 ,threadMessageId varchar(1000)
                                  
                       		);
               
                       		if exists(select 1 from temp_channeltype where channelType = 'Email' limit 1 )then
                       			
                       			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                       				insert ignore into temp_getcallback_list(sessionId,SessionStartTime,SessionEndTime,FromEmail,ToEmail,EmailSubject,EmailFlowSourceId,CompanyId,DomainId,DispositionId,Summary,IsInBound,
                       						AssignedTo,AssignedBy,AssignedOn,AfterEmailWorkTime,Istransferred,TransferredTypeId,IsSessionClosed,CustomerId,TicketId,SupervisorName,createdAt,updatedAt,AgentId,
                       						AgentSkillId, IsBot, BotId, QueueId, Message,channelType,EmailHistoryId,isThresholdTimeExceeded,remainingThresholdTime, emailconfigsupervisorName,threadMessageId)
                       				select  eh.SessionId, eh.SessionStartTime, eh.SessionEndTime, eh.FromEmail, eh.ToEmail, eh.EmailSubject, eh.EmailFlowSourceId, eh.CompanyId, eh.DomainId, eh.DispositionId, eh.Summary, eh.IsInBound, 
                       						eh.AssignedTo, eh.AssignedBy, eh.AssignedOn, eh.AfterEmailWorkTime, eh.Istransferred, eh.TransferredTypeId, eh.IsSessionClosed, eh.CustomerId, eh.TicketId, eh.SupervisorName, eh.CreatedAt, eh.UpdatedAt, ed.AgentId, 
                       						ed.AgentSkillId, ed.IsBot, ed.BotId, ed.QueueId, Null AS Message,'Email',eh.EmailHistoryId,
               								CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),eh.createdAt),'%H.%i') >= emailThreshold THEN 1 ELSE 0 END	isThresholdTimeExceeded,
                                               TIMEDIFF(NOW(),eh.createdAt) AS remainingThresholdTime, ec.supervisorName,eh.threadMessageId
                       				from tb_EmailHistory 			eh
                       				join tb_EmailDurationHistory 	ed 	on 	eh.EmailHistoryId 	= ed.EmailHistoryId
									JOIN email_config 				ec	ON	ec.emailAddress		= eh.ToEmail
               															AND	ec.domainId 		= eh.domainId
                       				where eh.domainId = p_domainId
                       				and (eh.sessionStartTime 
                       			  BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0)
                       			  AND ifnull(eh.IsSessionClosed,0) = 0 
                       			  AND ifnull(ed.IsBot,0) = 0 
               					  order by eh.EmailHistoryId desc;
                       			  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;         
                       			End if;                            
                                                      
                       			if exists(select 1 from temp_channeltype where channelType = 'Chat' limit 1 )
                       			THEN			
                       				
                       				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                                     insert ignore into temp_getcallback_list(sessionId, sessionStartTime, sessionEndTime, chatFlowSourceId, companyId, domainId, dispositionId, Summary, IsInBound, dialDuration, disconnectedBy, 
                       						queueDuration, assignedTo, assignedBy, assignedOn, waitDuration, afterChatWorkTime, Istransferred, transferredTypeId, markAsRead, CustomerId, ticketId, CallBackDatetime, 
                       						Browser, IPAdress, ChatSubject, createdAt,updatedAt,  StartTime, EndTime, Duration, AgentId, AgentSkillId, IsBot, BotId, 
                       						transferredTime, QueueId, Message,channelType,ChatHistoryId,widgetId,
                                               isThresholdTimeExceeded, remainingThresholdTime,CallBackStatus)
                      				select  cth.sessionId, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, NULL AS dispositionId, NULL AS Summary, cth.IsInBound, cth.dialDuration, cth.disconnectedBy, 
                      						cth.queueDuration, cth.assignedTo, cth.assignedBy, cth.assignedOn, 0 AS waitDuration, NULL AS afterChatWorkTime, NULL AS Istransferred, NULL AS transferredTypeId, NULL AS markAsRead, cth.CustomerId, 
                                             Null AS ticketId, Null AS CallBackDatetime, cth.Browser, cth.IPAdress, cth.ChatSubject, cth.createdAt, cth.updatedAt, Null AS StartTime, Null AS EndTime, Null AS Duration, Null AS AgentId, Null AS AgentSkillId, 
                                             Null AS IsBot, Null AS BotId, Null AS transferredTime, Null AS QueueId, Null AS Message,'Chat',cth.ChatHistoryId, cth.chatWidgetId, 
                      						 CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),cth.createdAt),'%H.%i') >= thresholdTime THEN 1 ELSE 0 END, timediff(NOW(),cth.createdAt), cth.CallBackStatus
                       				from 	tb_ChatHistory 					cth
                       				JOIN 	chat_configuration_primary_form	PF		ON PF.aid				= cth.chatWidgetId 
                       				where 	cth.domainId = p_domainId 								
                       				and 	(cth.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0)
                       				and 	cth.CallBackStatus	= 1  
                       				order by cth.ChatHistoryId desc; 
                                     
                                  UPDATE 	temp_getcallback_list 	t_CB
             						JOIN 	tb_ChatDurationHistory 	CTDH 	ON 	t_CB.ChatHistoryId 	= CTDH.ChatHistoryId
             																AND CTDH.ChatDurationHistoryId = (	SELECT 	MAX(ChatDurationHistoryId)
             																									FROM 	tb_ChatDurationHistory 	InCDH
        																										WHERE 	InCDH.ChatHistoryId = CTDH.ChatHistoryId)
                                     SET 	t_CB.dispositionId		= CTDH.dispositionId		
             							,	t_CB.Summary			= CTDH.Summary			
             							,	t_CB.afterChatWorkTime	= CTDH.afterChatWorkTime	
             							,	t_CB.Istransferred		= CTDH.Istransferred		
                                         ,	t_CB.markAsRead			= CTDH.markAsRead			
                                         ,	t_CB.ticketId			= CTDH.ticketId			
                                         ,	t_CB.StartTime			= CTDH.StartTime			
                                         , 	t_CB.EndTime			= CTDH.EndTime			
                                         , 	t_CB.Duration			= CTDH.Duration			
                                         , 	t_CB.AgentId			= CTDH.AgentId			
                                         , 	t_CB.AgentSkillId		= CTDH.AgentSkillId		
                                         , 	t_CB.IsBot				= CTDH.IsBot				
                                         , 	t_CB.BotId				= CTDH.BotId				
                                         , 	t_CB.transferredTime	= CTDH.transferredTime	
                                         , 	t_CB.QueueId			= CTDH.QueueId;			
                      				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                       			End if;                      
                                  
													SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                             					  if exists(select 1 from temp_channeltype where channelType = 'Call' limit 1) then
                             						
                             						 
                             							insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,dispositionId,UMNStatus,IsInBound,dialDuration, 
                             									disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,transferredTypeId,markAsRead, 
                             									CustomerId,voicemailUrl,ticketId,callDuration,summary,subject,createdAt,updatedAt,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
                             									transferredTime,recordingDuration,QueueId,Message,channelType,CallHistoryId,callBack,isThresholdTimeExceeded,remainingThresholdTime)
                             							select 	clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber,clh.domainId, null dispositionId, null UMNStatus, clh.IsInBound, null dialDuration, 
                             									clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, null afterCallWorkTime, clh.recordingTypeId, null transferredTypeId
                             								   ,null markAsRead, clh.CustomerId, clh.voicemailUrl, NULL AS ticketId, clh.callDuration, null summary, null subject,clh.createdAt, clh.updatedAt, null StartTime, null  EndTime,  null  Duration
                             								   ,null AgentHoldDuration, null AgentId, null AgentSkillId, null IsBot, null BotId, null RecordingUrl
                             								   ,null transferredTime, null recordingDuration, NULL AS QueueId, Null AS Message,'Call',clh.CallHistoryId,clh.callBack
                                                               ,CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),clh.createdAt),'%H.%i') >= CC.threshold THEN 1 ELSE 0 END	isThresholdTimeExceeded
                                                               ,TIMEDIFF(NOW(),clh.createdAt) AS remainingThresholdTime                                                   
                             							from tb_CallHistory 				clh
                                                        LEFT JOIN  call_configuration		CC	ON CC.contactCenterNumber = clh.calledNumber
                             							where 	clh.domainId 	= p_domainId
             											AND 	((clh.callBack	= 1 ) OR (clh.voicemailUrl like '%voicemail%' AND clh.isVMCallBackCompleted = 0))
                             							and 	(clh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                             							order by clh.CallHistoryId desc;
                                                         
                                                         UPDATE 	temp_getcallback_list 	t_CB
                                                         JOIN 	tb_CallDurationHistory	CDH		ON CDH.CallHistoryId = t_CB.CallHistoryId
                                                         SET 	t_CB.QueueId	= CDH.QueueId;                                            
                             						End if;
                             					   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                                                    
                             					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                                          			if exists(select 1 from temp_channeltype where channelType = 'Sms' limit 1 )then
                                          				insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,SMSFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
                                          						afterSMSWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                                                  AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,SMSHistoryId,isThresholdTimeExceeded,remainingThresholdTime, customerId)
                                          				select 	sh.sessionId, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.companyId, sh.domainId, sh.dispositionId, sh.Summary, sh.IsInBound, sh.assignedTo, sh.assignedBy, sh.assignedOn, 
                                          						sh.afterSMSWorkTime, sh.Istransferred, sh.transferredTypeId, sh.markAsRead, sh.IsSessionClosed, sh.customerNumber,sh.calledNumber, sh.ticketId, sh.supervisorName, sh.createdAt, sh.updatedAt, 
                                                                  sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sd.QueueId, Null AS Message,'Sms',sh.SMSHistoryId,
                                                                  CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),sh.createdAt),'%H.%i') >= P.smsThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded,
                                                                  TIMEDIFF(NOW(),sh.createdAt)	AS remainingThresholdTime, sh.customerId
                                          				FROM 	tb_SMSHistory 				sh
                                          				LEFT JOIN tb_SMSDurationHistory 	sd 	ON sh.SMSHistoryId 	= sd.SMSHistoryId
              											JOIN 	did_purchase				P	ON 	P.your_number	= sh.calledNumber
              																					AND	P.domainId		= sh.domainId
                                          				where sh.domainId = p_domainId
                                          				and (sh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                         AND ifnull(sh.IsSessionClosed,0) = 0 
                                         				AND ifnull(sd.IsBot,0) = 0 
                                          				order by sh.SMSHistoryId desc;
                                                      
                                                      End if;
                                                      
                                          			if exists(select 1 from temp_channeltype where channelType = 'Whatsapp' limit 1 )then
                                          				insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,WhatsappFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
                                          						afterWhatsappWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                          						AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,WhatsappHistoryId,CallBackStatus, customerId)
                                          				select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
                                          						wh.afterWhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wh.createdAt, wh.updatedAt, 
                                          						wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId, Null AS Message,'Whatsapp',wh.WhatsappHistoryId,wh.isCallback, wh.customerId
                                          				from tb_WhatsappHistory 				wh
                                          				left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId = wd.WhatsappHistoryId
                                          				where wh.domainId = p_domainId
                                          				and (wh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                        and  wh.isCallback		= 1 and wh.callbackDraft = 0
                                          				order by wh.WhatsappHistoryId desc;
                                          						
                                          			End if;    
                          					if exists(select 1 from temp_channeltype where channelType = 'Facebook' limit 1 ) 
                                              then
                          						insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterFacebookWorkTime,NextFlowNode
                          						,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
                          						,markAsReadAgent,IsSessionClosed,customerFacebookId,agentFacebookId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
                          						,createdAt,updatedAt,Message,channelType,FacebookHistoryId, customerId, QueueId)
                          						select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterFacebookWorkTime,fb.NextFlowNode
                          						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
                          						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerFacebookId,fb.agentFacebookId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
                          						,fb.createdAt,fb.updatedAt, Null AS Message,'Facebook',fb.FacebookHistoryId,fb.customerId, fb.queueId
                          						from tb_FacebookHistory 				fb
                          						where fb.domainId = p_domainId
                          						and (fb.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                 and  fb.isCallback		= 1 and fb.callbackDraft = 0
                          						  order by fb.FacebookHistoryId desc;
                                                  
                          					End if; 
                                              
                          					if exists(select 1 from temp_channeltype where channelType = 'Instagram' limit 1 ) 
                          					then
                          						insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterInstagramWorkTime,NextFlowNode
                          						,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
                          						,markAsReadAgent,IsSessionClosed,customerInstagramId,agentInstagramId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
                          						,createdAt,updatedAt,Message,channelType,InstagramHistoryId, customerId, QueueId)
                          						select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterInstagramWorkTime,fb.NextFlowNode
                          						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
                          						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerInstagramId,fb.agentInstagramId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
                          						,fb.createdAt,fb.updatedAt, Null AS Message,'Instagram',fb.InstagramHistoryId, fb.customerId, fb.queueId
                          						from tb_InstagramHistory 				fb
                          						where fb.domainId = p_domainId
                          						and (fb.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                  and  fb.isCallback		= 1 and fb.callbackDraft = 0
                          						order by fb.InstagramHistoryId desc;
                          					End if;     

       								CREATE INDEX idx_temp_assignedto_domain ON temp_getcallback_list (AssignedTo, domainId);
									CREATE INDEX idx_temp_assignedby_domain	ON temp_getcallback_list (assignedBy, domainId);
                                    CREATE INDEX idx_temp_channelType	ON temp_getcallback_list (channelType);
                                                  
       								DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_2;
       								CREATE TEMPORARY TABLE temp_getcallback_list_2
       								SELECT * FROM temp_getcallback_list WHERE 1 = 2;
                                      
       							ALTER TABLE temp_getcallback_list_2 
       							ADD COLUMN AssignedToUserName	VARCHAR(250),
       							ADD COLUMN AssignedByUserName	VARCHAR(250),
       							ADD COLUMN AssignedToExt		INT;

                                if v_roleid in (3,5) then
    								set v_p_assigned_ext_no_email_chltype = 0;
    							Else
                                    set v_p_assigned_ext_no_email_chltype = p_assigned_ext;
                                End if;

    							DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1;
    							CREATE TEMPORARY TABLE temp_getcallback_list_1
    							SELECT * FROM temp_getcallback_list_2 WHERE 1 = 2; 
        
    								INSERT INTO temp_getcallback_list_2
                  					select temp.*, tu.UserName as AssignedToUserName,tuu.UserName as AssignedByUserName,tu.ext as AssignedToExt
                  					from temp_getcallback_list temp
                  					left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
                  					left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 					
                  					where 	((p_search <> '' AND (tu.UserName collate utf8mb4_0900_ai_ci  LIKE CONCAT('%',p_search,'%') 
														or (temp.Message collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_search, '%')) )) 
                                                        OR (p_search = ''))	
                                    AND 	channelType <> 'Email' and (temp.assignedTo collate utf8mb4_0900_ai_ci LIKE CONCAT('%', v_p_assigned_ext_no_email_chltype, '%') or (ifnull(v_p_assigned_ext_no_email_chltype,0)=0))	;
                                                            
									create index idx_temp_getcallback_list_assignedto_domain on temp_getcallback_list(AssignedTo, domainId);
                                    create index idx_temp_getcallback_list_assignedby_domain on temp_getcallback_list(assignedBy, domainId);
        
                                    INSERT INTO temp_getcallback_list_2
                                    select temp.*, tu.UserName as AssignedToUserName,tuu.UserName as AssignedByUserName,tu.ext as AssignedToExt
                  					from temp_getcallback_list temp
                  					left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
                  					left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 
                                    left join email_config 				ec	ON	ec.emailAddress	collate utf8mb4_0900_ai_ci = temp.ToEmail
    																		AND	ec.domainId 	= temp.domainId
                  					where channelType = 'Email' and	((p_search <> '' AND (tu.UserName collate utf8mb4_0900_ai_ci  LIKE CONCAT('%',p_search,'%') or (temp.Message collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_search, '%')) )) OR (p_search = ''))	
                                    /* and (case when v_roleid in (3,5) then FIND_IN_SET(p_assigned_ext,ec.supervisorName) 
    										ELSE (temp.assignedTo collate utf8mb4_0900_ai_ci LIKE CONCAT('%', v_p_assigned_ext_no_email_chltype, '%') or (ifnull(v_p_assigned_ext_no_email_chltype,0)=0))
    									End ) */ -- commented for ccaas testing purpose 2026-02-11
    								And FromEmail is not null;

    								insert into temp_getcallback_list_1
                                    select * from temp_getcallback_list_2
                                    ORDER BY sessionStartTime DESC LIMIT v_offset ,`limit`;  

                  					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
                  					DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
                  					CREATE TEMPORARY TABLE temp_customer_contact
                  					SELECT 	coid
       									,primaryPhoneNumber
       									,primaryEmail
       									,phoneNumber
       									,email
       									,facebook
       									,instagram
       									,firstName
       									,lastName
                  					FROM 	customer_contact 
                  					WHERE 	domainId = p_domainId;       
                  					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
                                    
									--  CREATE INDEX idx_temp_customer_contact ON temp_customer_contact(firstName(250), lastName(250), coid);
									-- CREATE INDEX idx_temp_customer_contact_01 ON temp_customer_contact(primaryPhoneNumber(200));  
																												
       						   SELECT 	COUNT(1) INTO v_count
       						   FROM 	temp_getcallback_list_1;

                                      ALTER TABLE temp_getcallback_list_1 ADD COLUMN dispositionName VARCHAR(100), ADD COLUMN queueName varchar(255), ADD COLUMN CustomerName VARCHAR(150);
   
									CREATE INDEX idx_temp_getcallback_list_1_02 ON temp_getcallback_list_1(CustomerId, dispositionId, domainId, QueueId);
                                    CREATE INDEX idx_temp_getcallback_list_1_03 ON temp_getcallback_list_1(CustomerName);   

 									UPDATE 	temp_getcallback_list_1		H
 									LEFT JOIN temp_customer_contact		CC	ON H.CustomerId 	= CC.coid					
 									LEFT JOIN disposition_status		ds 	ON ds.did			= H.dispositionId and H.domainId = ds.domainId 					
 									LEFT JOIN queue 					qu 	ON H.QueueId 		= qu.qid
 									SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))
 									,		H.dispositionName	= ds.dispositionName
 									,		H.queueName			= qu.`name`;   

                                     update temp_getcallback_list_1 set CustomerName = '' where ifnull(LTRIM(RTRIM(CustomerId)),'')='';
                                   
                                     UPDATE 	temp_getcallback_list_1		H
									LEFT JOIN temp_customer_contact		CC	ON H.customerNumber collate utf8mb4_0900_ai_ci = CC.primaryPhoneNumber					
									SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))
									WHERE IFNULL(H.CustomerName,'') collate utf8mb4_0900_ai_ci = ''; 
                                                        
									UPDATE 	temp_getcallback_list_1		H
									LEFT JOIN temp_customer_contact		CC	ON CC.phoneNumber collate utf8mb4_0900_ai_ci like concat("%",H.customerNumber,"%")					
									SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))
									WHERE IFNULL(H.CustomerName,'') collate utf8mb4_0900_ai_ci = ''; 

                                      SELECT a.*, v_count FROM temp_getcallback_list_1 a
                                      left join temp_queueIDs t_Q     ON a.QueueId			= t_Q.queueId 
                                      WHERE 	(IFNULL(p_queueIds,'') 	= '' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL))
                                      ORDER BY sessionStartTime DESC;

									DROP TEMPORARY TABLE IF EXISTS tt_temp_userid;
									DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list;
  									DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1;
 									DROP TEMPORARY TABLE IF EXISTS temp_channeltype;  
                  					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccass_get_callback_session_history_details1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccass_get_callback_session_history_details1`(
         	p_domainId INT, 
         	p_channelType VARCHAR(255),
         	p_fromDate BIGINT,
         	p_toDate BIGINT,
         	p_ext LONGTEXT,			
         	p_assigned_ext BIGINT, 	
         	p_search LONGTEXT,
         	`offset` INT,
         	`limit` INT
         )
sp_return: BEGIN
               	
                  	DECLARE v_count INT;
                   declare v_offset int;
                   declare v_limit int;
                   
                   set v_offset = `offset` * `limit`;
                  
                  	IF p_fromDate IS NULL OR p_fromDate = '' 	THEN 	SET p_fromDate = 0; 							END IF;
                  	IF p_toDate IS NULL OR p_toDate = '' 		THEN	SET p_toDate = 0;								END IF;        
              		IF p_channelType = 'All' 					THEN	SET p_channelType = NULL;						END IF;
              		
           
              
              		DROP TEMPORARY TABLE IF EXISTS tt_temp_userid; 		CREATE TEMPORARY TABLE tt_temp_userid (ext VARCHAR(100));
                      DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));
                  	
          			CALL split(p_ext, ',');				INSERT INTO tt_temp_userid (ext)			SELECT Items FROM tt_Split_temptable;   
              		CALL split(p_channelType, ','); 	INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;
                      
              		drop temporary table if exists temp_getcallback_list;
              		create temporary table temp_getcallback_list
              		(
              			id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber bigint						,callFlowSourceId int default null
              			,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
              			,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
              			,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred tinyint default null		,transferredTypeId int default null			,markAsRead tinyint default null
              			,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
              			,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
              			,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
              			,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
              			,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
              			,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
         				,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
    					,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null						,`name` varchar(255) default null
              		);
         
              		if exists(select 1 from temp_channeltype where channelType = 'Email' limit 1 )then
              			
              				insert into temp_getcallback_list(sessionId,SessionStartTime,SessionEndTime,FromEmail,ToEmail,EmailSubject,EmailFlowSourceId,CompanyId,DomainId,DispositionId,Summary,IsInBound,
              						AssignedTo,AssignedBy,AssignedOn,AfterEmailWorkTime,Istransferred,TransferredTypeId,IsSessionClosed,CustomerId,TicketId,SupervisorName,createdAt,updatedAt,AgentId,
              						AgentSkillId, IsBot, BotId, QueueId, Message,channelType,EmailHistoryId)
              				select  eh.SessionId, eh.SessionStartTime, eh.SessionEndTime, eh.FromEmail, eh.ToEmail, eh.EmailSubject, eh.EmailFlowSourceId, eh.CompanyId, eh.DomainId, eh.DispositionId, eh.Summary, eh.IsInBound, 
              						eh.AssignedTo, eh.AssignedBy, eh.AssignedOn, eh.AfterEmailWorkTime, eh.Istransferred, eh.TransferredTypeId, eh.IsSessionClosed, eh.CustomerId, eh.TicketId, eh.SupervisorName, eh.CreatedAt, eh.UpdatedAt, ed.AgentId, 
              						ed.AgentSkillId, ed.IsBot, ed.BotId, ed.QueueId, em.Message,'Email',eh.EmailHistoryId
              				from tb_EmailHistory 			eh
              				join tb_EmailDurationHistory 	ed on eh.EmailHistoryId = ed.EmailHistoryId
              				join tb_EmailMessage			em on eh.EmailHistoryId = em.EmailHistoryId
              				where eh.domainId = p_domainId
              				and (eh.sessionStartTime 
                            BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0)
                            AND ifnull(eh.IsSessionClosed,0) = 0 
                            AND ifnull(ed.IsBot,0) = 0 
              				order by eh.EmailHistoryId desc;
              			End if;
                          
                      
                      if exists(select 1 from temp_channeltype where channelType = 'Call' limit 1 )then
              			
              				insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,customerNumber,callFlowSourceId,companyId,domainId,dispositionId,UMNStatus,IsInBound,dialDuration, 
              						disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,Istransferred,transferredTypeId,markAsRead, 
              						CustomerId,voicemailUrl,ticketId,callDuration,summary,subject,createdAt,updatedAt,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
              						transferredTime,recordingDuration,QueueId,Message,channelType,CallHistoryId,callBack,`name`)
              				select 	clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber, clh.callFlowSourceId, clh.companyId, clh.domainId, clh.dispositionId, clh.UMNStatus, clh.IsInBound, clh.dialDuration, 
              						clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, clh.afterCallWorkTime, clh.recordingTypeId, clh.Istransferred, clh.transferredTypeId, clh.markAsRead, 
              						clh.CustomerId, clh.voicemailUrl, clh.ticketId, clh.callDuration, clh.summary, clh.subject,clh.createdAt, clh.updatedAt, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, cld.AgentSkillId, cld.IsBot, cld.BotId, cld.RecordingUrl, 
              						cld.transferredTime, cld.recordingDuration, cld.QueueId, clm.Message,'Call',clh.CallHistoryId,clh.callBack,q.name
              				from tb_CallHistory 			clh
              				join tb_CallDurationHistory 	cld on clh.CallHistoryId = cld.CallHistoryId
              				join tb_CallMessage				clm on clh.CallHistoryId = clm.CallHistoryId
							left join queue					q	on cld.QueueId			= q.qid
              				where 	clh.domainId 	= p_domainId
                              AND 	clh.callBack	= 1	
              				and 	(clh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
              				order by clh.CallHistoryId desc;
              			End if;
                          
     
         			if exists(select 1 from temp_channeltype where channelType = 'Sms' limit 1 )then
         				insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,SMSFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
         						afterSMSWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                 AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,SMSHistoryId)
         				select 	sh.sessionId, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.companyId, sh.domainId, sh.dispositionId, sh.Summary, sh.IsInBound, sh.assignedTo, sh.assignedBy, sh.assignedOn, 
         						sh.afterSMSWorkTime, sh.Istransferred, sh.transferredTypeId, sh.markAsRead, sh.IsSessionClosed, sh.customerNumber,sh.calledNumber, sh.ticketId, sh.supervisorName, sh.createdAt, sh.updatedAt, 
                                 sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sd.QueueId, sm.Message,'Sms',sh.SMSHistoryId
         				from tb_SMSHistory 					sh
         				left join tb_SMSDurationHistory 	sd on sh.SMSHistoryId = sd.SMSHistoryId
         				join tb_SMSMessage					sm on sh.SMSHistoryId = sm.SMSHistoryId
         				where sh.domainId = p_domainId
         				and (sh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                        AND ifnull(sh.IsSessionClosed,0) = 0 
        				AND ifnull(sd.IsBot,0) = 0 
         				order by sh.SMSHistoryId desc;
                     
                     End if;
                     
         			if exists(select 1 from temp_channeltype where channelType = 'Whatsapp' limit 1 )then
         				insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,WhatsappFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
         						afterWhatsappWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
         						AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,WhatsappHistoryId)
         				select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
         						wh.afterWhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wh.createdAt, wh.updatedAt, 
         						wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId, wm.Message,'Whatsapp',wh.WhatsappHistoryId
         				from tb_WhatsappHistory 				wh
         				left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId = wd.WhatsappHistoryId
         				join tb_WhatsappMessage					wm on wh.WhatsappHistoryId = wm.WhatsappHistoryId
         				where wh.domainId = p_domainId
         				and (wh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                        AND ifnull(wh.IsSessionClosed,0) = 0 
        				AND ifnull(wd.IsBot,0) = 0 
         				order by wh.WhatsappHistoryId desc;
         						
         			End if;         
              
               		IF p_search <> '' THEN
           				select count(*) into v_count 
           				from temp_getcallback_list temp
           				left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
                          left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 
                          left join disposition_status		ds on ds.did			= temp.dispositionId and temp.domainId = ds.domainId 
           				
           				 left join queue 					qu on temp.QueueId 		= qu.qid
           				where (tu.UserName like CONCAT('%',p_search,'%') 
                           or (temp.Message LIKE CONCAT('%', p_search, '%')) or (ifnull(p_search,'')='')) 
           				AND	 ( temp.assignedTo LIKE CONCAT('%', p_assigned_ext, '%') or (ifnull(p_assigned_ext,0)=0))
           				
           				ORDER BY temp.sessionStartTime DESC LIMIT v_offset ,`limit`;
           	   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           				select temp.*, v_count,tu.UserName as AssignedToUserName,tuu.UserName as AssignedByUserName,ds.dispositionName,tu.ext as AssignedToExt
           				from temp_getcallback_list temp
           				left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
                          left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 
                          left join disposition_status		ds on ds.did			= temp.dispositionId and temp.domainId = ds.domainId 
           				
           				left join queue 					qu on temp.QueueId 		= qu.qid
           				where (tu.UserName like CONCAT('%',p_search,'%') 
                           or (temp.Message LIKE CONCAT('%', p_search, '%')) or (ifnull(p_search,'')='')) 
           				AND	 ( temp.assignedTo LIKE CONCAT('%', p_assigned_ext, '%') or (ifnull(p_assigned_ext,0)=0))
           				
           				ORDER BY temp.sessionStartTime DESC LIMIT v_offset ,`limit`;
                                 
               		end if;
               
                  	IF p_search = '' THEN
                  		select count(*) into v_count 
              			from temp_getcallback_list temp
              			left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
                          left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 
                          left join disposition_status		ds on ds.did			= temp.dispositionId and temp.domainId = ds.domainId 
              			
              			left join queue 					qu on temp.QueueId 		= qu.qid
              			where ( temp.assignedTo LIKE CONCAT('%', p_assigned_ext, '%') or (ifnull(p_assigned_ext,0)=0))
                      
              			 ORDER BY temp.sessionStartTime DESC LIMIT v_offset ,`limit`;
             
              			select temp.*, v_count,tu.UserName as AssignedToUserName,tuu.UserName as AssignedByUserName,ds.dispositionName,tu.ext as AssignedToExt,qu.name as queueName
              			from temp_getcallback_list temp
              			left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
                          left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 
                          left join disposition_status		ds on ds.did			= temp.dispositionId and temp.domainId = ds.domainId 
              			
              			 left join queue 					qu on temp.QueueId 		= qu.qid
              			where ( temp.assignedTo LIKE CONCAT('%', p_assigned_ext, '%') or (ifnull(p_assigned_ext,0)=0))
                      
              			
                         ORDER BY temp.updatedAt DESC LIMIT v_offset ,`limit`;
                         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                  	END IF;
                  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccass_get_callback_session_history_details_live` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccass_get_callback_session_history_details_live`(	
  	p_domainId 					INT,
  	p_channelType 				VARCHAR(255),
  	p_fromDate 					BIGINT,
  	p_toDate 					BIGINT,
  	p_ext 						LONGTEXT,	
  	p_assigned_ext 				BIGINT, 	
  	p_search 					LONGTEXT,
  	`offset` 					INT,
  	`limit` 					INT
  )
sp_return: BEGIN
                  		DECLARE v_count 	INT;
                  		DECLARE v_offset 	INT;
                  		DECLARE v_limit 	INT;
                  		DECLARE v_search 	INT;
                          declare v_roleid int;
  
  						select roleid into v_roleid from tb_User where domainId = p_domainId  and UserID = p_assigned_ext limit 1;
                  
                  		SET v_offset = `offset` * `limit`;
                  
                  		IF p_fromDate IS NULL OR p_fromDate = '' 	THEN 	SET p_fromDate = 0; 							END IF;
                  		IF p_toDate IS NULL OR p_toDate = '' 		THEN	SET p_toDate = 0;								END IF;        
                  		IF p_channelType = 'All' 					THEN	SET p_channelType = NULL;						END IF;                    
                  
                  		
                  
                  		DROP TEMPORARY TABLE IF EXISTS tt_temp_userid; 		CREATE TEMPORARY TABLE tt_temp_userid (ext VARCHAR(100));
                  		DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));
                                              	
                  		CALL split(p_ext, ',');				INSERT INTO tt_temp_userid (ext)			SELECT Items FROM tt_Split_temptable;   
                  		CALL split(p_channelType, ','); 	INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;
                                                  
                  		drop temporary table if exists temp_getcallback_list;
                  		create temporary table temp_getcallback_list
                  		(	id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber VARCHAR(20)						
                  			,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
                  			,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
                  			,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred tinyint default null		,transferredTypeId int default null			,markAsRead tinyint default null
                  			,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
                  			,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
                  			,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
                  			,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
                  			,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
                  			,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
                  			,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
                  			,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null 						,FacebookHistoryId	bigint				,afterFacebookWorkTime	int					,NextFlowNode	varchar(150)
                  			,transferredTo	bigint						,transferredDate	datetime				,dispositionUpdatedBy	bigint					,immediateParentId	bigint				,rootParentId	bigint						,discardedDate	datetime
                  			,repliedDate	datetime					,markAsReadSupervisor	tinyint				,markAsReadAgent	tinyint						,customerFacebookId	varchar(100)		,agentFacebookId	varchar(100)			,AgentStartTime	bigint
                  			,AgentEndTime	bigint						,SentimentalScore	float					,afterInstagramWorkTime int						,customerInstagramId bigint				,agentInstagramId	bigint					,InstagramCommunicationTypeId int
          					,InstagramHistoryId	bigint					,widgetId	INT								,isThresholdTimeExceeded		TINYINT			,remainingThresholdTime	VARCHAR(20)		,CallBackStatus		TINYINT					,emailconfigsupervisorName varchar(50)
                             
                  		);
          
                  		if exists(select 1 from temp_channeltype where channelType = 'Email' limit 1 )then
                  			
                  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                  				insert ignore into temp_getcallback_list(sessionId,SessionStartTime,SessionEndTime,FromEmail,ToEmail,EmailSubject,EmailFlowSourceId,CompanyId,DomainId,DispositionId,Summary,IsInBound,
                  						AssignedTo,AssignedBy,AssignedOn,AfterEmailWorkTime,Istransferred,TransferredTypeId,IsSessionClosed,CustomerId,TicketId,SupervisorName,createdAt,updatedAt,AgentId,
                  						AgentSkillId, IsBot, BotId, QueueId, Message,channelType,EmailHistoryId,isThresholdTimeExceeded,remainingThresholdTime, emailconfigsupervisorName)
                  				select  eh.SessionId, eh.SessionStartTime, eh.SessionEndTime, eh.FromEmail, eh.ToEmail, eh.EmailSubject, eh.EmailFlowSourceId, eh.CompanyId, eh.DomainId, eh.DispositionId, eh.Summary, eh.IsInBound, 
                  						eh.AssignedTo, eh.AssignedBy, eh.AssignedOn, eh.AfterEmailWorkTime, eh.Istransferred, eh.TransferredTypeId, eh.IsSessionClosed, eh.CustomerId, eh.TicketId, eh.SupervisorName, eh.CreatedAt, eh.UpdatedAt, ed.AgentId, 
                  						ed.AgentSkillId, ed.IsBot, ed.BotId, ed.QueueId, Null AS Message,'Email',eh.EmailHistoryId,
          								CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),eh.createdAt),'%H.%i') >= emailThreshold THEN 1 ELSE 0 END	isThresholdTimeExceeded,
                                          TIMEDIFF(NOW(),eh.createdAt) AS remainingThresholdTime, ec.supervisorName
                  				from tb_EmailHistory 			eh
                  				join tb_EmailDurationHistory 	ed 	on 	eh.EmailHistoryId 	= ed.EmailHistoryId
                                  JOIN email_config 				ec	ON	ec.emailAddress		= eh.ToEmail
          															AND	ec.domainId 		= eh.domainId
                  
                  				where eh.domainId = p_domainId
                  				and (eh.sessionStartTime 
                  			  BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0)
                  			  AND ifnull(eh.IsSessionClosed,0) = 0 
                  			  AND ifnull(ed.IsBot,0) = 0 
          					  order by eh.EmailHistoryId desc;
                  			  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;         
                  			End if;                            
                                             
                  			if exists(select 1 from temp_channeltype where channelType = 'Chat' limit 1 )
                  			THEN			
                  				
                  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                                insert ignore into temp_getcallback_list(sessionId, sessionStartTime, sessionEndTime, chatFlowSourceId, companyId, domainId, dispositionId, Summary, IsInBound, dialDuration, disconnectedBy, 
                  						queueDuration, assignedTo, assignedBy, assignedOn, waitDuration, afterChatWorkTime, Istransferred, transferredTypeId, markAsRead, CustomerId, ticketId, CallBackDatetime, 
                  						Browser, IPAdress, ChatSubject, createdAt,updatedAt,  StartTime, EndTime, Duration, AgentId, AgentSkillId, IsBot, BotId, 
                  						transferredTime, QueueId, Message,channelType,ChatHistoryId,widgetId,
                                          isThresholdTimeExceeded, remainingThresholdTime,CallBackStatus)
                 				select  cth.sessionId, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, NULL AS dispositionId, NULL AS Summary, cth.IsInBound, cth.dialDuration, cth.disconnectedBy, 
                 						cth.queueDuration, cth.assignedTo, cth.assignedBy, cth.assignedOn, 0 AS waitDuration, NULL AS afterChatWorkTime, NULL AS Istransferred, NULL AS transferredTypeId, NULL AS markAsRead, cth.CustomerId, 
                                        Null AS ticketId, Null AS CallBackDatetime, cth.Browser, cth.IPAdress, cth.ChatSubject, cth.createdAt, cth.updatedAt, Null AS StartTime, Null AS EndTime, Null AS Duration, Null AS AgentId, Null AS AgentSkillId, 
                                        Null AS IsBot, Null AS BotId, Null AS transferredTime, Null AS QueueId, Null AS Message,'Chat',cth.ChatHistoryId, cth.chatWidgetId, 
                 						 CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),cth.createdAt),'%H.%i') >= thresholdTime THEN 1 ELSE 0 END, timediff(NOW(),cth.createdAt), cth.CallBackStatus
                  				from 	tb_ChatHistory 					cth
                  				JOIN 	chat_configuration_primary_form	PF		ON PF.aid				= cth.chatWidgetId 
                  				where 	cth.domainId = p_domainId 								
                  				and 	(cth.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0)
                  				and 	cth.CallBackStatus	= 1  
                  				order by cth.ChatHistoryId desc; 
                                
                                UPDATE 	temp_getcallback_list 	t_CB
        						JOIN 	tb_ChatDurationHistory 	CTDH 	ON 	t_CB.ChatHistoryId 	= CTDH.ChatHistoryId
        																AND CTDH.ChatDurationHistoryId = (	SELECT 	MAX(ChatDurationHistoryId)
        																									FROM 	tb_ChatDurationHistory 	InCDH
   																										WHERE 	InCDH.ChatHistoryId = CTDH.ChatHistoryId)
                                SET 	t_CB.dispositionId		= CTDH.dispositionId		
        							,	t_CB.Summary			= CTDH.Summary			
        							,	t_CB.afterChatWorkTime	= CTDH.afterChatWorkTime	
        							,	t_CB.Istransferred		= CTDH.Istransferred		
                                    ,	t_CB.markAsRead			= CTDH.markAsRead			
                                    ,	t_CB.ticketId			= CTDH.ticketId			
                                    ,	t_CB.StartTime			= CTDH.StartTime			
                                    , 	t_CB.EndTime			= CTDH.EndTime			
                                    , 	t_CB.Duration			= CTDH.Duration			
                                    , 	t_CB.AgentId			= CTDH.AgentId			
                                    , 	t_CB.AgentSkillId		= CTDH.AgentSkillId		
                                    , 	t_CB.IsBot				= CTDH.IsBot				
                                    , 	t_CB.BotId				= CTDH.BotId				
                                    , 	t_CB.transferredTime	= CTDH.transferredTime	
                                    , 	t_CB.QueueId			= CTDH.QueueId;			
                 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                  			End if;                      
                             
                        					  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                        					  if exists(select 1 from temp_channeltype where channelType = 'Call' limit 1) then
                        						
                        						 
                        							insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,dispositionId,UMNStatus,IsInBound,dialDuration, 
                        									disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,transferredTypeId,markAsRead, 
                        									CustomerId,voicemailUrl,ticketId,callDuration,summary,subject,createdAt,updatedAt,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
                        									transferredTime,recordingDuration,QueueId,Message,channelType,CallHistoryId,callBack,isThresholdTimeExceeded,remainingThresholdTime)
                        							select 	clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber,clh.domainId, null dispositionId, null UMNStatus, clh.IsInBound, null dialDuration, 
                        									clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, null afterCallWorkTime, clh.recordingTypeId, null transferredTypeId
                        								   ,null markAsRead, clh.CustomerId, clh.voicemailUrl, NULL AS ticketId, clh.callDuration, null summary, null subject,clh.createdAt, clh.updatedAt, null StartTime, null  EndTime,  null  Duration
                        								   ,null AgentHoldDuration, null AgentId, null AgentSkillId, null IsBot, null BotId, null RecordingUrl
                        								   ,null transferredTime, null recordingDuration, NULL AS QueueId, Null AS Message,'Call',clh.CallHistoryId,clh.callBack
                                                          ,CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),clh.createdAt),'%H.%i') >= CC.threshold THEN 1 ELSE 0 END	isThresholdTimeExceeded
                                                          ,TIMEDIFF(NOW(),clh.createdAt) AS remainingThresholdTime                                                   
                        							from tb_CallHistory 				clh
                                                   LEFT JOIN  call_configuration		CC	ON CC.contactCenterNumber = clh.calledNumber
                                     				
                        
                        							where 	clh.domainId 	= p_domainId
        											AND 	((clh.callBack	= 1 ) OR (clh.voicemailUrl like '%voicemail%' AND clh.isVMCallBackCompleted = 0))
                        							and 	(clh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                        							order by clh.CallHistoryId desc;
                                                    
                                                    UPDATE 	temp_getcallback_list 	t_CB
                                                    JOIN 	tb_CallDurationHistory	CDH		ON CDH.CallHistoryId = t_CB.CallHistoryId
                                                    SET 	t_CB.QueueId	= CDH.QueueId;                                            
                        						End if;
                        					   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                                               
                                 
                        					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                                     			if exists(select 1 from temp_channeltype where channelType = 'Sms' limit 1 )then
                                     				insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,SMSFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
                                     						afterSMSWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                                             AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,SMSHistoryId,isThresholdTimeExceeded,remainingThresholdTime)
                                     				select 	sh.sessionId, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.companyId, sh.domainId, sh.dispositionId, sh.Summary, sh.IsInBound, sh.assignedTo, sh.assignedBy, sh.assignedOn, 
                                     						sh.afterSMSWorkTime, sh.Istransferred, sh.transferredTypeId, sh.markAsRead, sh.IsSessionClosed, sh.customerNumber,sh.calledNumber, sh.ticketId, sh.supervisorName, sh.createdAt, sh.updatedAt, 
                                                             sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sd.QueueId, Null AS Message,'Sms',sh.SMSHistoryId,
                                                             CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),sh.createdAt),'%H.%i') >= P.smsThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded,
                                                             TIMEDIFF(NOW(),sh.createdAt)	AS remainingThresholdTime
                                     				FROM 	tb_SMSHistory 				sh
                                     				LEFT JOIN tb_SMSDurationHistory 	sd 	ON sh.SMSHistoryId 	= sd.SMSHistoryId
         											JOIN 	did_purchase				P	ON 	P.your_number	= sh.calledNumber
         																					AND	P.domainId		= sh.domainId
                                     				
                                     				where sh.domainId = p_domainId
                                     				and (sh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                    AND ifnull(sh.IsSessionClosed,0) = 0 
                                    				AND ifnull(sd.IsBot,0) = 0 
                                     				order by sh.SMSHistoryId desc;
                                                 
                                                 End if;
                                                 
                                     			if exists(select 1 from temp_channeltype where channelType = 'Whatsapp' limit 1 )then
                                     				insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,WhatsappFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
                                     						afterWhatsappWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                     						AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,WhatsappHistoryId,CallBackStatus)
                                     				select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
                                     						wh.afterWhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wh.createdAt, wh.updatedAt, 
                                     						wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId, Null AS Message,'Whatsapp',wh.WhatsappHistoryId,wh.isCallback
                                     				from tb_WhatsappHistory 				wh
                                     				left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId = wd.WhatsappHistoryId
                          
                                     				where wh.domainId = p_domainId
                                     				and (wh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                   and  wh.isCallback		= 1
                                                   
                                     				order by wh.WhatsappHistoryId desc;
                                     						
                                     			End if;    
                     					if exists(select 1 from temp_channeltype where channelType = 'Facebook' limit 1 ) 
                                         then
                     						insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterFacebookWorkTime,NextFlowNode
                     						,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
                     						,markAsReadAgent,IsSessionClosed,customerFacebookId,agentFacebookId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
                     						,createdAt,updatedAt,Message,channelType,FacebookHistoryId)
                     						select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterFacebookWorkTime,fb.NextFlowNode
                     						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
                     						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerFacebookId,fb.agentFacebookId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
                     						,fb.createdAt,fb.updatedAt, Null AS Message,'Facebook',fb.FacebookHistoryId
                     						from tb_FacebookHistory 				fb
                     						where fb.domainId = p_domainId
                     						and (fb.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                            and  fb.isCallback		= 1
                     						
                     						order by fb.FacebookHistoryId desc;
                     					End if; 
                                         
                     					if exists(select 1 from temp_channeltype where channelType = 'Instagram' limit 1 ) 
                     					then
                     						insert into temp_getcallback_list
                     						(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterInstagramWorkTime,NextFlowNode
                     						,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
                     						,markAsReadAgent,IsSessionClosed,customerInstagramId,agentInstagramId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
                     						,createdAt,updatedAt,Message,channelType,InstagramHistoryId)
                     						select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterInstagramWorkTime,fb.NextFlowNode
                     						,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
                     						,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerInstagramId,fb.agentInstagramId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
                     						,fb.createdAt,fb.updatedAt, Null AS Message,'Instagram',fb.InstagramHistoryId
                     						from tb_InstagramHistory 				fb
                     						where fb.domainId = p_domainId
                     						and (fb.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                     						AND ifnull(fb.IsSessionClosed,0) = 0 
                     						AND ifnull(fb.IsBot,0) = 0 
                     						order by fb.InstagramHistoryId desc;
                     					End if;     
                                                                      
  								DROP TEMPORARY TABLE IF EXISTS temp_channeltype;  
                                             
  								DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1;
  								CREATE TEMPORARY TABLE temp_getcallback_list_1
  								SELECT * FROM temp_getcallback_list WHERE 1 = 2;
                                 
  							ALTER TABLE temp_getcallback_list_1 
  							ADD COLUMN AssignedToUserName	VARCHAR(250),
  							ADD COLUMN AssignedByUserName	VARCHAR(250),
  							ADD COLUMN AssignedToExt		INT;
                                 
  							INSERT INTO temp_getcallback_list_1
             					select temp.*, tu.UserName as AssignedToUserName,tuu.UserName as AssignedByUserName,tu.ext as AssignedToExt
             					from temp_getcallback_list temp
             					left join tb_User 					tu on tu.UserID 		=  temp.AssignedTo and temp.domainId = tu.domainId  
             					left join tb_User 					tuu on tuu.UserID 		=  temp.assignedBy and temp.domainId = tuu.domainId 					
             					where ((p_search <> '' AND (tu.UserName collate utf8mb4_0900_ai_ci  LIKE CONCAT('%',p_search,'%') or (temp.Message collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_search, '%')) )) OR (p_search = ''))	
                              
             					AND	 (
										(temp.channelType not like '%Email%' and temp.assignedTo collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_assigned_ext, '%')) 
                                      OR (CASE WHEN temp.channelType like '%Email%' AND v_roleid in (3,5) 
  											THEN ifnull(p_assigned_ext collate utf8mb4_0900_ai_ci LIKE CONCAT('%', temp.emailconfigsupervisorName, '%'),temp.assignedTo collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_assigned_ext, '%'))
                                              ELSE temp.assignedTo collate utf8mb4_0900_ai_ci LIKE CONCAT('%', p_assigned_ext, '%') END)
                                      OR (ifnull(p_assigned_ext,0)=0)
  								)
             					ORDER BY temp.sessionStartTime DESC LIMIT v_offset ,`limit`;  
       
             					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
             					DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
             					CREATE TEMPORARY TABLE temp_customer_contact
             					SELECT 	coid
  									,primaryPhoneNumber
  									,primaryEmail
  									,phoneNumber
  									,email
  									,facebook
  									,instagram
  									,firstName
  									,lastName
             					FROM 	customer_contact 
             					WHERE 	domainId = p_domainId;       
             					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                             
                                 
  						   SELECT 	COUNT(1) INTO v_count
  						   FROM 	temp_getcallback_list_1;
                                 
             					UPDATE 	temp_getcallback_list_1	SH 	
             					JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryPhoneNumber	= SH.customerNumber	
             					SET 	SH.CustomerId	= c_c.coid
             					WHERE  	SH.channelType	IN ('Call','Sms','Whatsapp')
             					AND 	IFNULL(CustomerId,0)	= 0;
             
             					UPDATE 	temp_getcallback_list_1 SH        
             					SET 	CustomerId	= (SELECT InTC.coid FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT('%',SH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)				
             					WHERE 	channelType				IN ('Call','Sms','Whatsapp')
             					AND 	IFNULL(CustomerId,0)	= 0; 
             
             					UPDATE 	temp_getcallback_list_1	SH
             					JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryEmail	LIKE SH.FromEmail											
             					SET 	CustomerId				= c_c.coid
             					WHERE 	IFNULL(CustomerId,0)	= 0
             					AND 	channelType				= 'Email';   
             
             					UPDATE 	temp_getcallback_list_1 SH        
             					SET 	CustomerId	= (SELECT InTC.coid FROM temp_customer_contact InTC WHERE InTC.email LIKE CONCAT('%',SH.FromEmail,'%') ORDER BY InTC.coid LIMIT 1)				
             					WHERE 	IFNULL(CustomerId,0)	= 0
             					AND 	channelType				= 'Email';          
             
             					UPDATE 	temp_getcallback_list_1	SH
             					JOIN 	temp_customer_contact	c_c	ON 	c_c.facebook	LIKE SH.customerFacebookId											
             					SET 	CustomerId				= c_c.coid
             					WHERE 	IFNULL(CustomerId,0)	= 0
             					AND 	channelType				= 'Facebook';   
             
             					UPDATE 	temp_getcallback_list_1 SH        
             					SET 	CustomerId	= (SELECT InTC.coid FROM temp_customer_contact InTC WHERE InTC.facebook LIKE CONCAT('%',SH.customerFacebookId,'%') ORDER BY InTC.coid LIMIT 1)				
             					WHERE 	IFNULL(CustomerId,0)	= 0
             					AND 	channelType				= 'Facebook';                  
             
             					UPDATE 	temp_getcallback_list_1	SH
             					JOIN 	temp_customer_contact	c_c	ON 	c_c.instagram	LIKE SH.customerInstagramId											
             					SET 	CustomerId				= c_c.coid
             					WHERE 	IFNULL(CustomerId,0)	= 0
             					AND 	channelType				= 'Instagram';   
             
             					UPDATE 	temp_getcallback_list_1 SH        
             					SET 	CustomerId	= (SELECT InTC.coid FROM temp_customer_contact InTC WHERE InTC.instagram LIKE CONCAT('%',SH.customerInstagramId,'%') ORDER BY InTC.coid LIMIT 1)				
             					WHERE 	IFNULL(CustomerId,0)	= 0
             					AND 	channelType				= 'Instagram'; 
                                 
                                 ALTER TABLE temp_getcallback_list_1 ADD COLUMN dispositionName VARCHAR(100),ADD COLUMN queueName varchar(255),ADD COLUMN CustomerName VARCHAR(150);
                                 
                                 UPDATE 	temp_getcallback_list_1		H
             					LEFT JOIN temp_customer_contact		CC	ON H.CustomerId 	= CC.coid					
                                 LEFT JOIN disposition_status		ds 	ON ds.did			= H.dispositionId and H.domainId = ds.domainId 					
                                 LEFT JOIN queue 					qu 	ON H.QueueId 		= qu.qid
             					SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))
                                 ,		H.dispositionName	= ds.dispositionName
                                 ,		H.queueName			= qu.`name`;                     
                                 
                                 SELECT *, v_count FROM temp_getcallback_list_1
                                 ORDER BY sessionStartTime DESC;
                                                 
             					DROP TEMPORARY TABLE IF EXISTS tt_temp_userid;
             					DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list;
                                 DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list_1;
             					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
               END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ccass_get_callback_session_history_details_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `ccass_get_callback_session_history_details_test`(	
       	p_domainId 			INT,
       	p_channelType 		VARCHAR(255),
       	p_fromDate 			BIGINT,
       	p_toDate 			BIGINT,
       	p_ext 				LONGTEXT,	
       	p_assigned_ext 		BIGINT, 	
       	p_search 			LONGTEXT,
       	`offset` 			INT,
       	`limit` 			INT,
        p_queueIDs	 		VARCHAR(250)
)
sp_return: BEGIN
    
   			DECLARE v_count 	INT;
   			DECLARE v_offset 	INT;
   			DECLARE v_limit 	INT;
   			DECLARE v_search 	INT;
   			DECLARE v_roleid 	INT;
   			DECLARE v_p_assigned_ext_no_email_chltype int;
            
            DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
			
            CALL split(p_queueIds,','); 
            
            INSERT INTO temp_queueIDs(queueId) 
            SELECT Items FROM tt_Split_temptable;

       
       						select roleid into v_roleid from tb_User where domainId = p_domainId  and UserID = p_assigned_ext limit 1;
                       
                       		SET v_offset = `offset` * `limit`;
                       
                       		IF p_fromDate IS NULL OR p_fromDate = '' 	THEN 	SET p_fromDate = 0; 							END IF;
                       		IF p_toDate IS NULL OR p_toDate = '' 		THEN	SET p_toDate = 0;								END IF;        
                       		IF p_channelType = 'All' 					THEN	SET p_channelType = NULL;						END IF;                    
                       
                       		DROP TEMPORARY TABLE IF EXISTS tt_temp_userid; 		CREATE TEMPORARY TABLE tt_temp_userid (ext VARCHAR(100));
                       		DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));
                                                   	
                       		CALL split(p_ext, ',');				INSERT INTO tt_temp_userid (ext)			SELECT Items FROM tt_Split_temptable;   
                       		CALL split(p_channelType, ','); 	INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;
                                                       
                       		drop temporary table if exists temp_getcallback_list;
                       		create temporary table temp_getcallback_list
                       		(	id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber VARCHAR(20)						
                       			,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
                       			,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
                       			,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred tinyint default null		,transferredTypeId int default null			,markAsRead tinyint default null
                       			,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
                       			,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
                       			,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
                       			,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
                       			,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
                       			,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
                       			,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
                       			,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null 						,FacebookHistoryId	bigint				,afterFacebookWorkTime	int					,NextFlowNode	varchar(150)
                       			,transferredTo	bigint						,transferredDate	datetime				,dispositionUpdatedBy	bigint					,immediateParentId	bigint				,rootParentId	bigint						,discardedDate	datetime
                       			,repliedDate	datetime					,markAsReadSupervisor	tinyint				,markAsReadAgent	tinyint						,customerFacebookId	varchar(100)		,agentFacebookId	varchar(100)			,AgentStartTime	bigint
                       			,AgentEndTime	bigint						,SentimentalScore	float					,afterInstagramWorkTime int						,customerInstagramId bigint				,agentInstagramId	bigint					,InstagramCommunicationTypeId int
               					,InstagramHistoryId	bigint					,widgetId	INT								,isThresholdTimeExceeded		TINYINT			,remainingThresholdTime	VARCHAR(20)		,CallBackStatus		TINYINT					,emailconfigsupervisorName varchar(50)
                                 ,threadMessageId varchar(1000)
                                  
                       		);
               
                       		if exists(select 1 from temp_channeltype where channelType = 'Email' limit 1 )then
                       			
                       			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                       				insert ignore into temp_getcallback_list(sessionId,SessionStartTime,SessionEndTime,FromEmail,ToEmail,EmailSubject,EmailFlowSourceId,CompanyId,DomainId,DispositionId,Summary,IsInBound,
                       						AssignedTo,AssignedBy,AssignedOn,AfterEmailWorkTime,Istransferred,TransferredTypeId,IsSessionClosed,CustomerId,TicketId,SupervisorName,createdAt,updatedAt,AgentId,
                       						AgentSkillId, IsBot, BotId, QueueId, Message,channelType,EmailHistoryId,isThresholdTimeExceeded,remainingThresholdTime, emailconfigsupervisorName,threadMessageId)
                       				select  eh.SessionId, eh.SessionStartTime, eh.SessionEndTime, eh.FromEmail, eh.ToEmail, eh.EmailSubject, eh.EmailFlowSourceId, eh.CompanyId, eh.DomainId, eh.DispositionId, eh.Summary, eh.IsInBound, 
                       						eh.AssignedTo, eh.AssignedBy, eh.AssignedOn, eh.AfterEmailWorkTime, eh.Istransferred, eh.TransferredTypeId, eh.IsSessionClosed, eh.CustomerId, eh.TicketId, eh.SupervisorName, eh.CreatedAt, eh.UpdatedAt, ed.AgentId, 
                       						ed.AgentSkillId, ed.IsBot, ed.BotId, ed.QueueId, Null AS Message,'Email',eh.EmailHistoryId,
               								CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),eh.createdAt),'%H.%i') >= emailThreshold THEN 1 ELSE 0 END	isThresholdTimeExceeded,
                                               TIMEDIFF(NOW(),eh.createdAt) AS remainingThresholdTime, ec.supervisorName,eh.threadMessageId
                       				from tb_EmailHistory 			eh
                       				join tb_EmailDurationHistory 	ed 	on 	eh.EmailHistoryId 	= ed.EmailHistoryId
									JOIN email_config 				ec	ON	ec.emailAddress		= eh.ToEmail
               															AND	ec.domainId 		= eh.domainId
                       				where eh.domainId = p_domainId
                       				and ((eh.sessionStartTime >= p_fromDate AND eh.sessionStartTime <= p_toDate) OR IFNULL(p_fromDate,0)=0)
                       			  AND ifnull(eh.IsSessionClosed,0) = 0 
                       			  AND ifnull(ed.IsBot,0) = 0 
               					  order by eh.EmailHistoryId desc;
                       			  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;         
                       			End if;                            
                                                  
                       			if exists(select 1 from temp_channeltype where channelType = 'Chat' limit 1 )
                       			THEN			
                       				
                       				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                                     insert ignore into temp_getcallback_list(sessionId, sessionStartTime, sessionEndTime, chatFlowSourceId, companyId, domainId, dispositionId, Summary, IsInBound, dialDuration, disconnectedBy, 
                       						queueDuration, assignedTo, assignedBy, assignedOn, waitDuration, afterChatWorkTime, Istransferred, transferredTypeId, markAsRead, CustomerId, ticketId, CallBackDatetime, 
                       						Browser, IPAdress, ChatSubject, createdAt,updatedAt,  StartTime, EndTime, Duration, AgentId, AgentSkillId, IsBot, BotId, 
                       						transferredTime, QueueId, Message,channelType,ChatHistoryId,widgetId,
                                               isThresholdTimeExceeded, remainingThresholdTime,CallBackStatus)
                      				select  cth.sessionId, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, NULL AS dispositionId, NULL AS Summary, cth.IsInBound, cth.dialDuration, cth.disconnectedBy, 
                      						cth.queueDuration, cth.assignedTo, cth.assignedBy, cth.assignedOn, 0 AS waitDuration, NULL AS afterChatWorkTime, NULL AS Istransferred, NULL AS transferredTypeId, NULL AS markAsRead, cth.CustomerId, 
                                             Null AS ticketId, Null AS CallBackDatetime, cth.Browser, cth.IPAdress, cth.ChatSubject, cth.createdAt, cth.updatedAt, Null AS StartTime, Null AS EndTime, Null AS Duration, Null AS AgentId, Null AS AgentSkillId, 
                                             Null AS IsBot, Null AS BotId, Null AS transferredTime, Null AS QueueId, Null AS Message,'Chat',cth.ChatHistoryId, cth.chatWidgetId, 
                      						 CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),cth.createdAt),'%H.%i') >= thresholdTime THEN 1 ELSE 0 END, timediff(NOW(),cth.createdAt), cth.CallBackStatus
                       				from 	tb_ChatHistory 					cth
                       				JOIN 	chat_configuration_primary_form	PF		ON PF.aid				= cth.chatWidgetId 
                       				where 	cth.domainId = p_domainId 								
                       				and 	((cth.sessionStartTime >= p_fromDate AND cth.sessionStartTime <= p_toDate) OR IFNULL(p_fromDate,0)=0)
                       				and 	cth.CallBackStatus	= 1  
                       				order by cth.ChatHistoryId desc; 
                                     
                                  UPDATE 	temp_getcallback_list 	t_CB
             						JOIN 	tb_ChatDurationHistory 	CTDH 	ON 	t_CB.ChatHistoryId 	= CTDH.ChatHistoryId
             																AND CTDH.ChatDurationHistoryId = (	SELECT 	MAX(ChatDurationHistoryId)
             																									FROM 	tb_ChatDurationHistory 	InCDH
        																										WHERE 	InCDH.ChatHistoryId = CTDH.ChatHistoryId)
                                     SET 	t_CB.dispositionId		= CTDH.dispositionId		
             							,	t_CB.Summary			= CTDH.Summary			
             							,	t_CB.afterChatWorkTime	= CTDH.afterChatWorkTime	
             							,	t_CB.Istransferred		= CTDH.Istransferred		
                                         ,	t_CB.markAsRead			= CTDH.markAsRead			
                                         ,	t_CB.ticketId			= CTDH.ticketId			
                                         ,	t_CB.StartTime			= CTDH.StartTime			
                                         , 	t_CB.EndTime			= CTDH.EndTime			
                                         , 	t_CB.Duration			= CTDH.Duration			
                                         , 	t_CB.AgentId			= CTDH.AgentId			
                                         , 	t_CB.AgentSkillId		= CTDH.AgentSkillId		
                                         , 	t_CB.IsBot				= CTDH.IsBot				
                                         , 	t_CB.BotId				= CTDH.BotId				
                                         , 	t_CB.transferredTime	= CTDH.transferredTime	
                                         , 	t_CB.QueueId			= CTDH.QueueId;			
                      				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                       			End if;                      
                                  
                             					  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
                             					  if exists(select 1 from temp_channeltype where channelType = 'Call' limit 1) then
                             						
                             						 
                             							insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,dispositionId,UMNStatus,IsInBound,dialDuration, 
                             									disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,transferredTypeId,markAsRead, 
                             									CustomerId,voicemailUrl,ticketId,callDuration,summary,subject,createdAt,updatedAt,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
                             									transferredTime,recordingDuration,QueueId,Message,channelType,CallHistoryId,callBack,isThresholdTimeExceeded,remainingThresholdTime)
                             							select 	clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber,clh.domainId, null dispositionId, null UMNStatus, clh.IsInBound, null dialDuration, 
                             									clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, null afterCallWorkTime, clh.recordingTypeId, null transferredTypeId
                             								   ,null markAsRead, clh.CustomerId, clh.voicemailUrl, NULL AS ticketId, clh.callDuration, null summary, null subject,clh.createdAt, clh.updatedAt, null StartTime, null  EndTime,  null  Duration
                             								   ,null AgentHoldDuration, null AgentId, null AgentSkillId, null IsBot, null BotId, null RecordingUrl
                             								   ,null transferredTime, null recordingDuration, NULL AS QueueId, Null AS Message,'Call',clh.CallHistoryId,clh.callBack
                                                               ,CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),clh.createdAt),'%H.%i') >= CC.threshold THEN 1 ELSE 0 END	isThresholdTimeExceeded
                                                               ,TIMEDIFF(NOW(),clh.createdAt) AS remainingThresholdTime                                                   
                             							from tb_CallHistory 				clh
                                                        LEFT JOIN  call_configuration		CC	ON CC.contactCenterNumber = clh.calledNumber
                             							where 	clh.domainId 	= p_domainId
             											AND 	((clh.callBack	= 1 ) OR (clh.voicemailUrl like '%voicemail%' AND clh.isVMCallBackCompleted = 0))
                             							and 	((clh.sessionStartTime >= p_fromDate AND clh.sessionStartTime <= p_toDate) OR IFNULL(p_fromDate,0)=0) 
                             							order by clh.CallHistoryId desc;
                                                         
                                                         UPDATE 	temp_getcallback_list 	t_CB
                                                         JOIN 	tb_CallDurationHistory	CDH		ON CDH.CallHistoryId = t_CB.CallHistoryId
                                                         SET 	t_CB.QueueId	= CDH.QueueId;                                            
                             						End if;
                             					   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                                                    
                                      
                             					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                                          			if exists(select 1 from temp_channeltype where channelType = 'Sms' limit 1 )then
                                          				insert ignore into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,SMSFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
                                          						afterSMSWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                                                  AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,SMSHistoryId,isThresholdTimeExceeded,remainingThresholdTime, customerId)
                                          				select 	sh.sessionId, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.companyId, sh.domainId, sh.dispositionId, sh.Summary, sh.IsInBound, sh.assignedTo, sh.assignedBy, sh.assignedOn, 
                                          						sh.afterSMSWorkTime, sh.Istransferred, sh.transferredTypeId, sh.markAsRead, sh.IsSessionClosed, sh.customerNumber,sh.calledNumber, sh.ticketId, sh.supervisorName, sh.createdAt, sh.updatedAt, 
                                                                  sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sd.QueueId, Null AS Message,'Sms',sh.SMSHistoryId,
                                                                  CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),sh.createdAt),'%H.%i') >= P.smsThreshold THEN 1 ELSE 0 END AS isThresholdTimeExceeded,
                                                                  TIMEDIFF(NOW(),sh.createdAt)	AS remainingThresholdTime, sh.customerId
                                          				FROM 	tb_SMSHistory 				sh
                                          				LEFT JOIN tb_SMSDurationHistory 	sd 	ON sh.SMSHistoryId 	= sd.SMSHistoryId
              											JOIN 	did_purchase				P	ON 	P.your_number	= sh.calledNumber
              																					AND	P.domainId		= sh.domainId
                                          				where sh.domainId = p_domainId
                                          				and (sh.sessionStartTime BETWEEN p_fromDate AND p_toDate OR IFNULL(p_fromDate,0)=0) 
                                                         AND ifnull(sh.IsSessionClosed,0) = 0 
                                         				AND ifnull(sd.IsBot,0) = 0 
                                          				order by sh.SMSHistoryId desc;
                                                      
                                                      End if;
                                                      
                                          			if exists(select 1 from temp_channeltype where channelType = 'Whatsapp' limit 1 )then
                                          				insert into temp_getcallback_list(sessionId,sessionStartTime,sessionEndTime,WhatsappFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
                                          						afterWhatsappWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
                                          						AgentId,AgentSkillId,IsBot,BotId,QueueId,Message,channelType,WhatsappHistoryId,CallBackStatus, customerId)
                                          				select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
                                          						wh.afterWhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wh.createdAt, wh.updatedAt, 
                                          						wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId, Null AS Message,'Whatsapp',wh.WhatsappHistoryId,wh.isCallback, wh.customerId
                                          				from tb_WhatsappHistory 				wh
                                          				left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId = wd.WhatsappHistoryId
                                          				where wh.domainId = p_domainId
                                          				and ((wh.sessionStartTime >= p_fromDate AND wh.sessionStartTime <= p_toDate) OR IFNULL(p_fromDate,0)=0) 
                                                        and  wh.isCallback		= 1 and wh.callbackDraft = 0
                                          				order by wh.WhatsappHistoryId desc;
                                          						
                                          			End if;    
                          					if exists(select 1 from temp_channeltype where channelType = 'Facebook' limit 1 ) 
                                              then
