DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ccass_get_session_history_details`(
  domainId 		INT,
  channelType 	VARCHAR(255),
  disposition 	int,
  callType 		VARCHAR(255),
  fromDate 		BIGINT,
  toDate 			BIGINT,
  ext 			longtext,
  search 			LONGTEXT,
  `offset` 		INT,
  `limit` 		INT
  )
BEGIN 
        
   		if channelType ='All' then set channelType = null; End if; 		
   		if disposition is null then set disposition = 0; End if;
   
   		if callType ='All' then set callType = null; End if;
           if callType ='inbound' then set callType = 1; End if;
           if callType ='outbound' then set callType = 0; End if;
            
            
             if fromDate is null or fromDate = '' then set fromDate = 0; end if;
             if toDate is null or toDate = '' then set toDate = unix_timestamp(now()) * 1000; end if;
           
        	 drop temporary table if exists tt_temp_userid; create temporary table tt_temp_userid(ext varchar(100));
            drop temporary table if exists tt_temp_channelType; create temporary table tt_temp_channelType(channelType varchar(255));
            drop temporary table if exists tt_temp_disposition_id; create temporary table tt_temp_disposition_id(disp_id int primary key,disp_Name varchar(100));
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		insert into tt_temp_disposition_id(disp_id,disp_Name)
     
   		select dss.did ,dss.dispositionName  from disposition_status dss where dss.domainId = domainId;
   
   		insert into tt_temp_disposition_id(disp_id,disp_Name)
   		select tc.TypeCodeID ,tc.TypeCode from TypeCode tc where tc.TypeGroupID =1121;
            
            call split(ext,','); 			insert into tt_temp_userid(ext) 				select Items from tt_Split_temptable;
            call split(channelType,','); 	insert into tt_temp_channelType(channelType) 	select Items from tt_Split_temptable;
           
   		drop temporary table if exists tt_temp_userid_1; create temporary table tt_temp_userid_1 as select * from tt_temp_userid;
           
  		IF IFNULL(channelType,'Call') = 'Call' then  
         
  				SELECT  a.sessionId, 
  						DATE_FORMAT(FROM_UNIXTIME(left(a.sessionStartTime,length(a.sessionStartTime)-3)),'%d %b %Y') as createdDate,
  						a.sessionId,a.sessionStartTime,a.sessionEndTime,a.customerNumber ,a.domainId,b.dispositionId,b.UMNStatus,a.IsInBound,
  						a.dialDuration,a.disconnectedBy,a.queueDuration,a.assignedTo,a.assignedBy,a.assignedOn,a.calledNumber ,b.afterCallWorkTime,a.recordingTypeId,
  						 b.transferredTypeId,b.markAsRead,a.CustomerId,a.voicemailUrl,b.ticketId,a.callDuration,a.createdAt,a.updatedAt,
  						b.StartTime,b.EndTime,b.Duration,b.AgentHoldDuration,b.AgentId,b.AgentSkillId,b.IsBot,b.BotId,b.RecordingUrl,b.transferredTime,b.recordingDuration,b.QueueId
  				FROM tb_CallHistory 		a 
  				join tb_CallDurationHistory b 	on a.CallHistoryId = b.CallHistoryId
  				join tb_User 				d 	on d.UserID = b.AgentId
  				join tt_temp_userid 		tt 	on d.ext 	= tt.ext 
  				join queue 					q 	on b.QueueId = q.qid
  				left join tt_temp_disposition_id ds 	on b.dispositionId = ds.disp_id 
  				WHERE a.domainId = domainId 
  				AND a.sessionStartTime BETWEEN fromDate and toDate 
  				AND (d.UserName like CONCAT('%',search,'%') or (q.name LIKE CONCAT('%', search, '%')) or (ifnull(search,'')=''))   
  				AND  ((ds.disp_id = disposition) or (ifnull(disposition,0)=0))
  				AND ((a.IsInBound = callType) or (ifnull(callType,'')=''))
  				ORDER BY a.CallHistoryId DESC LIMIT `limit` OFFSET `offset`;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;       
  		end if;    
           
  END ;;
DELIMITER ;
