CREATE DEFINER=`dbdev`@`%` PROCEDURE `DeleteCallFlow`(
  p_callFlowId		INT,
  p_domainId		INT
 )
BEGIN
     DECLARE v_errcode	INT DEFAULT -1;
     DECLARE v_errmsg	VARCHAR(150) DEFAULT 'Not Deleted';
  
sp_exit:begin
  
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     IF EXISTS ( SELECT 1
				FROM call_configuration
				WHERE domainId = p_domainId AND callFlowId = p_callFlowId
				) THEN
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
					SET v_errcode = -1;
					SET v_errmsg = 'This call flow is active in channel and cannot be deleted.';
				leave sp_exit;
	ELSE
		DELETE FROM callFlow WHERE domainId = p_domainId AND callFlowId = p_callFlowId;
        SET v_errcode = 0;
		SET v_errmsg = 'Deleted Successfully';
     END IF;
 end;    
     SELECT v_errcode as errcode, v_errmsg as errmsg; 
 END ;;
DELIMITER ;
