/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `did_number_sms_Integration_creation_dtl`(	p_id	varchar(250)
     ,p_domainid	int
     ,p_smstype	varchar(30)
     ,p_source_num 	varchar(30)
     ,p_destination 	json
     ,p_content	text
  )
Begin   
  	declare v_errcode 	int default -1;
  	declare v_errmsg 	varchar(100) default '';
  	declare v_domainid 	int;
      DECLARE v_smstypeId	TINYINT;       
  	DECLARE v_JLength 	INT;
         
  	SET v_JLength 	= JSON_LENGTH(p_destination, "$");
  	SET v_smstypeId	= CASE WHEN p_smstype  = 'Outbound' THEN 0 ELSE 1 END;
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	DROP TEMPORARY TABLE IF EXISTS tt_destinationmsg;
  	CREATE TEMPORARY TABLE tt_destinationmsg       
  	WITH RECURSIVE CTE_JsonCount as
  	(	SELECT 	0 SlNo
  		UNION ALL
  		SELECT 	SlNo + 1	SlNo
  		FROM 	CTE_JsonCount
  		WHERE 	SlNo  < v_JLength - 1
  	)
  	SELECT  TRIM(BOTH '"' FROM (json_extract(p_destination, concat('$[',SlNo,'].destination')))) 		AS dest_number,
  			TRIM(BOTH '"' FROM (json_extract(p_destination, concat('$[',SlNo,'].msg_id')))) 			AS msg_id_value						
  	FROM 	CTE_JsonCount; 
                            
  	IF p_domainid IS NULL OR p_domainid='' 
      THEN
  		SELECT 	domainId INTO v_domainid 
          FROM 	did_purchase 
          WHERE 	your_number COLLATE utf8mb4_unicode_ci = p_destination;
  	END IF;
     
  	IF NOT EXISTS(SELECT 1 FROM did_number_sms_Integration_master_dtl WHERE id = p_id LIMIT 1) 
      THEN		
  		INSERT INTO did_number_sms_Integration_master_dtl(id,domainid,smstype,smstypeId,source_num,destination,content,created_date,msg_id)
  		SELECT p_id,ifnull(p_domainid,v_domainid),p_smstype,v_smstypeId,p_source_num,a.dest_number,p_content,current_timestamp,a.msg_id_value
  		FROM tt_destinationmsg a;
  
  	IF ROW_COUNT()>0 
      THEN
  		UPDATE did_number_sms_Integration_master_dtl a join did_purchase b on b.your_number COLLATE utf8mb4_unicode_ci = a.destination
  		set a.domainid = b.domainId
  		where a.domainid is null;
  		 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  	set v_errcode = 0 ;
  	   set v_errmsg = 'Success : Created';
  	End if;
  	End if;
  
  	select v_errcode as errcode, v_errmsg as errmsg;
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `did_number_sms_Integration_get_dtl` */;
