CREATE DEFINER=`dbdev`@`%` PROCEDURE `did_number_sms_Integration_update_dtl`(
 p_msg_id varchar(250)
 ,p_time_start text
 ,p_end_time text
 ,p_status text
 ,p_code_id text
 ,p_fragments_sent text
 )
Begin
 
 	declare v_errcode int default -1;
     declare v_errmsg varchar(100) default '';
 
   if exists(select * from did_number_sms_Integration_master_dtl where msg_id collate utf8mb4_unicode_ci = p_msg_id limit 1) then
   
 		update did_number_sms_Integration_master_dtl a
 			set
 				a.time_start = ifnull(p_time_start  ,a.time_start)
 				,a.end_time = ifnull(p_end_time ,a.end_time)
 				,a.status = ifnull(p_status ,a.status)
 				,a.code_id = ifnull(p_code_id ,a.code_id)
 				,a.fragments_sent = ifnull(p_fragments_sent ,a.fragments_sent)
 				,a.modified_date = current_timestamp
 		where msg_id collate utf8mb4_unicode_ci = p_msg_id;
 			
 		if row_count()>0 then
 			set v_errcode = 0 ;
 			set v_errmsg = 'Success : Updated';
 		End if;
 
 		
 	End if;
 
 
 End ;;
DELIMITER ;
