CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `Edit_Column_updateandinsert_Details`( 
    p_domainId INT,
    p_ext INT,
    p_editColumnNames LONGTEXT
)
BEGIN
    DECLARE errcode INT;
    DECLARE errmsg VARCHAR(250);

    sp_exit: BEGIN
        DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            SET errcode = -1;
            SET errmsg = 'Error occurred while updating/inserting data';
        END;

        START TRANSACTION;
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

        IF EXISTS (SELECT * FROM editColumns a WHERE a.domainId = p_domainId AND a.ext = p_ext LIMIT 1) THEN
            UPDATE editColumns a SET a.editColumnNames = p_editColumnNames WHERE a.domainId = p_domainId AND a.ext = p_ext;

            IF ROW_COUNT() > 0 THEN
                SET errcode = 0;
                SET errmsg = 'Successfully updated';
                COMMIT;
                LEAVE sp_exit;
            END IF;
        ELSE
            INSERT INTO editColumns (domainId, ext, editColumnNames) VALUES (p_domainId, p_ext, p_editColumnNames);

            IF ROW_COUNT() > 0 THEN
                SET errcode = 0;
                SET errmsg = 'Successfully inserted';
                COMMIT;
                LEAVE sp_exit;
            END IF;
        END IF;

        ROLLBACK;
        SET errcode = -1;
        SET errmsg = 'No rows affected';
    END sp_exit;

    SELECT errcode AS errorcode, errmsg AS errormessage;
END ;;
DELIMITER ;
