CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `Edit_CustomerContact_Details`( 
 domainId INT,
 ext int,
 editColumnNames longtext
 )
BEGIN
 
 DECLARE errode int;
 DECLARE errmsg varchar(250);
 
 sp_exit : begin
 
 
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 if exists (select * from editCustomerContact a where a.domainId=domainId and a.ext=ext limit 1) then
 
    update editCustomerContact a set a.editColumnNames=editColumnNames where  a.domainId=domainId and a.ext=ext;
 
 if row_count()>0
 then
 set errode=0;
 set errmsg='success to update';
  leave sp_exit; 
 end if;
 
 else 
 
 insert into editCustomerContact (domainId,ext,editColumnNames) values (domainId,ext,editColumnNames);
 
 
 if row_count()>0
 then
 set errode=0;
 set errmsg='success to insert';
 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  leave sp_exit; 
 end if;
 
 end if;
  end sp_exit;       
 select errode,errmsg;
 
 END ;;
