DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `FindTablesWithValue`(IN search_value VARCHAR(255))
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE tbl_name VARCHAR(64);
    DECLARE col_name VARCHAR(64);
    DECLARE cur CURSOR FOR 
        SELECT TABLE_NAME, COLUMN_NAME 
        FROM INFORMATION_SCHEMA.COLUMNS 
        WHERE TABLE_SCHEMA = 'ccaas2023'
        AND DATA_TYPE NOT IN ('datetime', 'date', 'timestamp');  
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    DROP TEMPORARY TABLE IF EXISTS TempResults;
    CREATE TEMPORARY TABLE TempResults (TableName VARCHAR(255));

    OPEN cur;
    
    read_loop: LOOP
        FETCH cur INTO tbl_name, col_name;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        SET @query = CONCAT('INSERT INTO TempResults (TableName) SELECT DISTINCT "', tbl_name, '" FROM `', tbl_name, '` WHERE `', col_name, '` = ? LIMIT 1');
        PREPARE stmt FROM @query;
        SET @val = search_value;
        EXECUTE stmt USING @val;
        DEALLOCATE PREPARE stmt;
    END LOOP;

    CLOSE cur;

    SELECT DISTINCT TableName FROM TempResults;
    DROP TEMPORARY TABLE TempResults;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
