CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `GetAgentCount`(p_qid INT)
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT b.UserID, 
            b.UserName, 
            b.emailId, 
            b.directNumber, 
            b.address, 
            b.routing_profile_id, 
            b.report_to_UserID, 
            b.sipLoginId, 
            b.companyId, 
            b.domainId, 
            b.ext, 
            b.isActive, 
            b.callTypeId, 
            b.roleid, 
            b.localization, 
            b.currentSession, 
            b.isVoice, 
            b.isVoiceCallTransfer, 
            b.isChat, 
            b.isChatTransfer, 
            b.isEmail, 
            b.isEmailTransfer, 
            b.StatusID, 
            b.isSms, 
            b.isSocialMedia, 
            b.createdAt, 
            b.updatedAt
     FROM   routingqueueprofilemapping a
     JOIN   tb_User b ON a.rqmid = b.routing_profile_id 
     WHERE  a.qid = p_qid; 
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
DELIMITER ;
