CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `getCustomerContactByEmail`(
  p_domainId INT 
  ,p_email   VARCHAR(150))
BEGIN
 	DECLARE v_coid	BIGINT;
     
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	coid INTO v_coid
     FROM 	customer_contact
     WHERE 	primaryEmail	= p_email
     AND 	domainId		= p_domainId
	 AND 	JSON_VALID(phoneNumber) 	= 1
	 AND 	JSON_VALID(email) 			= 1;    
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
     IF v_coid IS NULL
     THEN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 	coid INTO v_coid
 		FROM 	customer_contact
 		WHERE 	email 		LIKE CONCAT('%',p_email,'%')
 		AND 	domainId	= p_domainId
        AND 	JSON_VALID(phoneNumber) 	= 1
		AND 	JSON_VALID(email) 			= 1
		ORDER BY coid LIMIT 1;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END IF;
	
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	SELECT 	a.coid
		,	a.firstName
		,	a.lastName
		,	JSON_ARRAY_INSERT(a.email,'$[0]',a.primaryEmail) email 
	FROM 	customer_contact a
	WHERE 	a.coid = v_coid;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `getCustomerContactByPhoneNumber` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `getCustomerContactByPhoneNumber`(
     p_domainId INT 
     ,p_phoneNumber    longtext
     )
BEGIN
 		DECLARE v_coid	BIGINT;
         DECLARE v_firstName varchar(150);
        
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    	SELECT 	coid,firstName INTO v_coid,v_firstName
        FROM 	customer_contact
        WHERE 	primaryPhoneNumber	= p_phoneNumber
        AND 	domainId			= p_domainId
        AND 	JSON_VALID(phoneNumber) = 1
   	 AND 	JSON_VALID(email) 		= 1 limit 1;    
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
        
        IF (v_coid IS NULL or ifnull(v_firstName,'')='')
        THEN
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		SELECT 	coid INTO v_coid
    		FROM 	customer_contact
    		WHERE 	
			(
				p_phoneNumber like concat('%',primaryPhoneNumber)
			OR primaryPhoneNumber like concat('%',p_phoneNumber)
			OR phoneNumber like concat('%',p_phoneNumber)            
			OR p_phoneNumber like concat('%',phoneNumber)
			)
 		AND 	domainId	= p_domainId
 		AND 	JSON_VALID(phoneNumber) 	= 1
 		AND 	JSON_VALID(email) 			= 1
 		ORDER BY coid LIMIT 1;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        END IF; 
     
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    	SELECT 	a.coid
    		,	a.firstName
    		,	a.lastName
    		,	JSON_ARRAY_INSERT(a.phoneNumber,'$[0]',a.primaryPhoneNumber) phoneNumber 
    	FROM 	customer_contact a
    	WHERE 	a.coid = v_coid;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
