CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `getCustomerContactDetailByEmail`(
    p_domainId INT 
    ,p_email   VARCHAR(150))
BEGIN
   	DECLARE v_coid	BIGINT;
       
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	coid INTO v_coid
       FROM 	customer_contact
       WHERE 	primaryEmail COLLATE utf8mb4_unicode_ci		= p_email
       AND 	domainId		= p_domainId
  	 AND 	JSON_VALID(phoneNumber) 	= 1
  	 AND 	JSON_VALID(email) 			= 1;    
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       
       IF v_coid IS NULL
       THEN
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		SELECT 	coid INTO v_coid
   		FROM 	customer_contact
   		WHERE 	email 	COLLATE utf8mb4_unicode_ci		LIKE CONCAT('%',p_email,'%')
   		AND 	domainId	= p_domainId
          AND 	JSON_VALID(phoneNumber) 	= 1
  		AND 	JSON_VALID(email) 			= 1
  		ORDER BY coid LIMIT 1;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       END IF;
  	
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT *
  		
  	FROM 	customer_contact a
  	WHERE 	a.coid = v_coid;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END ;;
DELIMITER ;
