CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `getPrivateAppDetailsForToken`(
    IN p_token            VARCHAR(255),
    IN p_adminEmail       VARCHAR(255)
 )
BEGIN
 DECLARE v_Total_count 	INT;
 
         DROP TEMPORARY TABLE IF EXISTS temp_PrivateApp; 
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	CREATE TEMPORARY TABLE temp_PrivateApp AS 	
         SELECT 
         PA.privateAppId,
         PA.name,
         PA.description,
         PA.token,
		 PA.adminEmail,
         PA.logo,
         PA.domainId,
         PAS.scopeID
         FROM tb_privateApp PA
         JOIN tb_privateAppScope PAS ON  PA.privateAppId=PAS.privateAppId
         WHERE adminEmail=p_adminEmail 
         AND token =p_token;

	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    SELECT COUNT(1)  Total_count FROM temp_PrivateApp;                                  
    SELECT * FROM temp_PrivateApp;
    END ;;
