CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `GetToCheckExistingEmailHistory`(
   p_FromEmail		VARCHAR(100),
   p_ToEmail		VARCHAR(100),
   p_EmailSubject	VARCHAR(250)
   )
begin
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   select a.EmailHistoryId, 
   	   a.SessionId, 
          a.SessionStartTime, 
          a.SessionEndTime, 
          a.FromEmail, 
          a.ToEmail, 
          a.EmailSubject, 
          a.EmailFlowSourceId, 
          a.CompanyId, 
          a.DomainId, 
          a.DispositionId, 
          a.Summary, 
          a.IsInBound, 
          a.AssignedTo, 
          a.AssignedBy, 
          a.AssignedOn, 
          a.AfterEmailWorkTime, 
          a.Istransferred, 
          a.TransferredTypeId, 
          a.IsSessionClosed, 
          a.CustomerId, 
          a.TicketId, 
          a.SupervisorName,
          b.Message,
          c.EmailDurationHistoryId,
          c.AgentId,
          c.AgentSkillId,
          c.IsBot,
          c.BotId,
          c.QueueId,
          a.threadMessageId as messageId
   from   tb_EmailHistory a
   join   tb_EmailMessage b on a.EmailHistoryId = b.EmailHistoryId
   join   tb_EmailDurationHistory c on a.EmailHistoryId = c.EmailHistoryId
   where  FromEmail collate utf8mb4_unicode_ci	=  p_FromEmail
   and	   ToEmail	collate utf8mb4_unicode_ci	=  p_ToEmail
   and	   EmailSubject collate utf8mb4_unicode_ci	=  p_EmailSubject
  
   AND       IFNULL(a.IsSessionClosed, 0) = 0
  ;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
