CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `getWorktualAppDetailsForToken`(
         IN p_token            VARCHAR(255),
         IN p_adminEmail       VARCHAR(255)
      )
BEGIN
      DECLARE v_Total_count 	INT;
      
              DROP TEMPORARY TABLE IF EXISTS temp_WorktualApp; 
           	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           	CREATE TEMPORARY TABLE temp_WorktualApp AS 	
              SELECT 
              distinct(PA.appId) as appId ,
              PA.name,
              PA.description,
              PA.token,
     		    PA.adminEmail,
              PA.logo,
              PA.domainId,
              PA.siploginid,
              PA.ext,
          
  			(
     			SELECT GROUP_CONCAT(DISTINCT PAS.scopeID) 
     			FROM tb_worktualAppScope PAS 
     			WHERE PA.appId = PAS.appId
  			) AS scopeID
              FROM tb_worktualApp PA   
              JOIN tb_worktualAppScope PAS ON  PA.appId=PAS.appId
              WHERE adminEmail=p_adminEmail 
              AND token =p_token;
  
     
     	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
         SELECT COUNT(1)  Total_count FROM temp_WorktualApp;                                  
         SELECT * FROM temp_WorktualApp;
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
