DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `getWorktualTokenAppDetails`(
           IN p_token            VARCHAR(255)
     
        )
BEGIN
        DECLARE v_Total_count 	INT;
        
                DROP TEMPORARY TABLE IF EXISTS temp_WorktualApp; 
             	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
             	CREATE TEMPORARY TABLE temp_WorktualApp AS 	
  			SELECT 
  				PA.appId,
  				PA.name,
  				PA.description,
  				PA.token,
  				PA.adminEmail,
  				PA.logo,
  				PA.domainId,
                PA.siploginid,
                PA.ext,
  				(
  				SELECT GROUP_CONCAT(DISTINCT PAS.scopeID) 
  				FROM tb_worktualAppScope PAS 
  				WHERE PA.appId = PAS.appId
  				) AS scopeID
  			FROM tb_worktualApp PA
  			WHERE PA.token = p_token
             AND   PA.isDelete is null
  			GROUP BY PA.appId, PA.name, PA.description, PA.token, PA.adminEmail, PA.logo, PA.domainId;
       
       	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
          
           SELECT * FROM temp_WorktualApp;
           END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
