CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `get_analytics_config`(
 p_analyticsId  INT 
 ,p_analyticsType	VARCHAR(50)
     )
BEGIN
 SELECT analyticsId,
         domainId, 
         ext,
         editColumn,
         createdAt,
         updatedAt,
         analyticsType
FROM analytics_config
WHERE  analyticsId = p_analyticsId 
AND    analyticsType = p_analyticsType;
END ;;
