CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_customColumnForWebChatCategory`(
		p_custom_column 	TEXT, 
		p_domainId 			INT, 
        p_startTmpstmp 		BIGINT, 
	    p_endTmpstmp 		BIGINT
	)
BEGIN


    DECLARE v_startTmpstmp						BIGINT;
    DECLARE v_endTmpstmp						BIGINT;
    DECLARE v_defaultQueue						VARCHAR(255);
    DECLARE v_count								INT;                 
	
	DECLARE columnNamePresent 					TEXT;
	DECLARE v_columnMissing 					TINYINT DEFAULT 0;
    DECLARE v_errcode							TINYINT DEFAULT -1 ;
    DECLARE v_errmsg							VARCHAR(50) DEFAULT "Failed";
    
 	IF IFNULL(p_startTmpstmp,0)	= 0 
		THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; 
		ELSE SET v_startTmpstmp = p_startTmpstmp;  
     END IF; 	
	
     IF IFNULL(p_endTmpstmp ,0)	= 0 
 		THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; 
		ELSE SET v_endTmpstmp = p_endTmpstmp; 
     END IF;  

    DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
	CREATE TEMPORARY TABLE temp_AvailableDisposition 
      		(    DispositionId 			INT
      			,DispositionStatus 		VARCHAR(100)
      			,DispositionCategory	TINYINT
      		); 
              
	INSERT INTO temp_AvailableDisposition 
		SELECT 	did 			AS DispositionId
			,	dispositionName	AS DispositionStatus
			,	CASE 
				WHEN dispositionName = 'Opened'	THEN 2
				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
				WHEN dispositionName = 'Discarded' THEN 4
				END 			DispositionCategory
		FROM 	disposition_status
		WHERE 	domainId	= p_domainId;
		
		
        DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
		CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid,name as queueName, type from queue where domainId = p_domainId;
			
		SELECT 	queueName INTO v_defaultQueue	
			FROM 	temp_AllqueueId 
			WHERE 	`type`	= 'Default' LIMIT 1;
    
		SET columnNamePresent = "Date,AgentName,Queue,CustomerName,ChatStartTime,ChatEndTime,Duration,Source,ActiveChatTime,ResponseTime,Disposition,ACWtime,CSATScore,TotalReceivedChats,TotalHandledChats,TotalTransferredChats,TotalMissedChat,TotalActiveChatTime,AverageResponseTime,AverageActiveChatTime,TotalInteractions,TotalACWTime";
	

		SET v_count = (LENGTH(p_custom_column)-LENGTH(REPLACE(p_custom_column, ',', ''))+1);

DROP TEMPORARY TABLE IF EXISTS result_hold;
CREATE TEMPORARY TABLE result_hold
	WITH RECURSIVE check_column(count_no) AS 
    (
		SELECT 1 AS count_no
        UNION ALL
        SELECT count_no +1 FROM check_column
        WHERE count_no < v_count
    )
    SELECT 
         FIND_IN_SET( SUBSTRING_index(SUBSTRING_index(p_custom_column, ',', count_no),',', -1) ,  columnNamePresent) AS temp_Result
    FROM check_column ;
    
    SELECT 1 INTO v_columnMissing FROM result_hold WHERE temp_Result = 0;
    
    
	DROP TEMPORARY TABLE IF EXISTS result_01;
	CREATE TEMPORARY TABLE result_01
     SELECT CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 								AS 	'Date',
            U. UserName											  								AS 	'AgentName',
			IFNULL(Q.name,v_defaultQueue)														AS 	'queueName',
            CASE WHEN coid IS NOT NULL AND (c_c.firstName IS NOT NULL OR c_c.lastName IS NOT NULL) THEN 
				TRIM(CONCAT(IFNULL(c_c.firstName, ''), ' ',IFNULL(c_c.lastName, '')))ELSE NULL END AS 'customerName',
            CDH.StartTime																		AS  'ChatStartTime',
            CDH.EndTime																			AS 	'ChatEndTime',
            CDH.Duration																		AS 	'Duration',
			CH.Browser                                              							AS	'Source', 
			 ABS((CDH.EndTime-CDH.StartTime)/1000)												AS 	'ActiveChattime',
            CH.dialDuration																		AS  'ResponseTime',
            temp_AD.DispositionStatus															AS	'Disposition',
            CDH.afterChatWorkTime														    	AS  'ACWtime', 
			CDH.SentimentalScore																AS 	'CSATscore',
            CASE WHEN temp_AD.DispositionCategory = 3 THEN 1 ELSE 0 END							AS 	'totalHandledChats',
			CASE WHEN temp_AD.DispositionStatus ='Transferred' THEN 1 ELSE 0 END 			    AS 	'totalTransferredChat',	
            CASE WHEN temp_AD.DispositionCategory IS NULL THEN 1 ELSE 0 END						AS  'totalMissedChat',
			CDH.EndTime - CDH.StartTime	 														AS 	'chatHandlingTime',
            CDH.afterChatWorkTime																AS  'ACW'
						FROM tb_ChatHistory 				AS CH
						JOIN tb_ChatDurationHistory 		AS CDH  		ON CH.ChatHistoryId = CDH.ChatHistoryId
						JOIN tb_User 						AS U			ON U.UserID				= CDH.AgentId
                        JOIN temp_AvailableDisposition 		AS temp_AD   	ON CDH.dispositionId	= temp_AD.DispositionId
						LEFT JOIN 		queue					Q	ON CDH.queueId			= Q.qid
						LEFT JOIN customer_contact			c_c	ON 	c_c.coid			= CH.CustomerId  AND	c_c.domainId		= p_domainId
                        WHERE 	CH.domainId 		= p_domainId
                        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp; 
                        
    
    DROP TEMPORARY TABLE IF EXISTS result_02;
    CREATE temporary table result_02
	SELECT  	`Date`												AS Session_date,
 				AgentName											AS Ag_name,
 				queueName											AS Q_name
                ,COUNT(1)											AS totalReceived  
                ,COUNT(1)											AS totalInteraction
				,SUM(totalHandledChats) 							AS TotalHandledChats
				,SUM(totalTransferredChat)							AS TotalTransferredChat
				,SUM(totalMissedChat)								AS TotalMissedChat
              ,  SUM((Duration)+(ACWtime*1000))		    			AS TotalActiveChatTime
              ,  SUM(responseTime)/COUNT(1)							AS AverageResponseTime
              ,  SUM(chatHandlingTime)/COUNT(1)						AS AverageActiveChatTime
              ,  SUM(ACW)											AS TotalACWTIme
              ,  SUM(ACW)/COUNT(1)				                    AS AverageACWTime
 		FROM result_01
         GROUP BY  `Date`, AgentName, queueName
        ;
        
  
  DROP TEMPORARY TABLE IF EXISTS result_03;
  CREATE temporary table result_03
	SELECT t1.`date`  								AS "Date",
            t1.AgentName 							AS "AgentName",
			t1.queueName 							AS "Queue",
			t1.customerName 						AS "CustomerName",
			t1.ChatStartTime 						AS "ChatStartTime",
            t1.ChatEndTime 							AS "ChatEndTime",
            t1.Duration 							AS "Duration",
			t1.`Source` 							AS "Source", 
			t1.ActiveChattime 						AS "ActiveChatTime",
            t1.ResponseTime 						AS "ResponseTime",
            t1.Disposition							AS "Disposition",
            t1.ACWtime 								AS "ACWtime", 
			t1.CSATscore 							AS "CSATScore",
            t2.totalReceived						AS "TotalReceivedChats",
            t2.TotalHandledChats 					AS "TotalHandledChats",
            t2.TotalTransferredChat 				AS "TotalTransferredChats",
            t1.totalMissedChat 						AS "TotalMissedChat",
			t2.TotalActiveChatTime  				AS "TotalActiveChatTime",
			t2.AverageResponseTime 					AS "AverageResponseTime",
            t2.AverageActiveChatTime  				AS "AverageActiveChatTime",
            t2.TotalInteraction						AS "TotalInteractions",
			t2.TotalACWTIme 						AS "TotalACWTIme",
			t2.AverageACWTime 						AS "AverageACWTime"

              FROM result_01 AS t1
              INNER JOIN result_02 As t2
              ON t1.`date` = t2.Session_date AND t1.`AgentName` = t2.Ag_name AND t1.queueName = t2.Q_name
              ;

	IF v_columnMissing = 1
    THEN
        SET v_errcode = -2;
		SET v_errmsg = "Given column not match";
     END IF;
     
	IF v_columnMissing = 0 THEN
		SET @sql_statement = CONCAT('SELECT ',p_custom_column,' FROM ', 'result_03');

		PREPARE sample_01 FROM @sql_statement;
		EXECUTE sample_01;
		DEALLOCATE PREPARE sample_01;
    
		SET v_errcode = 1;
		SET v_errmsg = "Success";
    END IF ;  
    
    SELECT v_errcode AS "Error Code", v_errmsg AS "Error Message";
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_CustomizeColumnReportforSocialMediaCategory` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_CustomizeColumnReportforSocialMediaCategory`(
 	p_custom_column 		TEXT 
  	, p_domainId 				INT 
   	, p_startTmpstmp 			BIGINT 
   	, p_endTmpstmp 			BIGINT
 )
SMF: BEGIN
 
 	DECLARE v_startTmpstmp				BIGINT;
     DECLARE v_endTmpstmp				BIGINT;
     DECLARE v_defaultQueue				VARCHAR(255);
     DECLARE v_count					INT; 
 	DECLARE columnNamePresent 			TEXT;
 	DECLARE v_columnMissing 			TINYINT DEFAULT 0;
     DECLARE v_errcode					TINYINT DEFAULT -1 ;
     DECLARE v_errmsg					VARCHAR(50) DEFAULT "Failed";
     
     DECLARE v_searchWhatsapp			TINYINT DEFAULT 0;
     DECLARE v_searchFacebook			TINYINT DEFAULT 0;
     DECLARE v_searchInstgram			TINYINT DEFAULT 0;
     DECLARE v_searchTwitter				TINYINT DEFAULT 0;
     DECLARE v_mediaName					VARCHAR(20) DEFAULT "Mismatch";
     DECLARE v_countColumn				INT;
     DECLARE v_custom_column				TEXT;
     
     
     
     SET columnNamePresent = "Date,Source,CustomerName,AgentName,QueueName,Direction,ChatStartTime,ChatEndTime,DurationOfTheChatConversation,ActiveChatTime,ResponseTime,DispositionStatus,ChatStatus,QueueWaitingTime,ACWTime,CustomerSatisfactionScore,ChatHandledCount,AverageActiveChatTime,UnansweredChatCount,AverageResponseTime,TotalAnsweredChats,TotalACWTime";
     
     SET v_countColumn = LENGTH(p_custom_column)-LENGTH(REPLACE(p_custom_column,",",""))+1;
     
     DROP TEMPORARY TABLE IF EXISTS temp_columnMatch;
 		CREATE TEMPORARY TABLE temp_columnMatch
 			WITH RECURSIVE eachColumnCheck(n) AS
 			(
 				SELECT 1 AS n
 					UNION ALL
 				SELECT n+1 AS n FROM eachColumnCheck WHERE n < v_countColumn
 			)
 				SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(p_custom_column,',',n),',',-1) AS columnName, 
 				FIND_IN_SET(SUBSTRING_INDEX(SUBSTRING_INDEX(p_custom_column,',',n),',',-1),columnNamePresent) AS FoundAt 
 				FROM eachColumnCheck;
     
     SELECT 1 INTO v_columnMissing FROM temp_columnMatch WHERE FoundAt = 0 LIMIT 1;
     
     IF v_columnMissing = 1 THEN 
     
 			SET v_errcode = -4;
             SET v_errmsg = "Mismatch in given column...";
             
 		SELECT v_errcode AS Error_code, v_errmsg AS Error_Message;
 		LEAVE SMF;
     END IF;
     
 		IF IFNULL(p_startTmpstmp,0)	= 0 
 			THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; 
 			ELSE SET v_startTmpstmp = p_startTmpstmp;  
 		END IF; 	
 	
 		IF IFNULL(p_endTmpstmp ,0)	= 0 
 			THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; 
 			ELSE SET v_endTmpstmp = p_endTmpstmp; 
 		END IF;
     
     	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
 		CREATE TEMPORARY TABLE temp_AvailableDisposition 
         (   
 			DispositionId 			INT
 			,DispositionStatus 		VARCHAR(100)
 			,DispositionCategory	TINYINT
 		); 
         
 		INSERT INTO temp_AvailableDisposition 
 		SELECT 	did 			 AS DispositionId
 			,	dispositionName	 AS DispositionStatus
 			,	CASE WHEN dispositionName = 'Transferred' THEN 1
 					 WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
 					 WHEN dispositionName = 'Discarded' THEN 4
                  ELSE 2
 				 END 			DispositionCategory
 		FROM 	disposition_status
 		WHERE 	domainId	= p_domainId;
     
     
 		DROP temporary TABLE IF EXISTS result_WA01; 
 		CREATE temporary table result_WA01
         SELECT 
 			FROM_UNIXTIME(CH.sessionStartTime/1000)    																		AS "Date_Col_01"
             ,"Whatsapp"								   																	AS "Source"
 			,CASE WHEN c_c.coid IS NOT NULL AND (c_c.firstName IS NOT NULL OR c_c.lastName IS NOT NULL) THEN 
				TRIM(CONCAT(IFNULL(c_c.firstName, ''), ' ',IFNULL(c_c.lastName, '')))ELSE NULL END 							AS 'customerName'
             , U.UserName																									AS "AgentName_01"  
             , Q.`name` 																									AS "QueueName"
 			, CASE WHEN CH.IsInBound  = 0 THEN 'OutBound' ELSE 'InBound' END        										AS "Direction"
             , CH.sessionStartTime																							AS "ChatStartTime"
 			, CASE WHEN CH.sessionEndTime > 0 THEN CH.sessionEndTime ELSE NULL END		  									AS "ChatEndTime"
 			, CDH.Duration                           																		AS "DurationOfTheChatConversation"
             , abs((CH.sessionEndTime-CH.sessionStartTime)/1000)															AS "ActiveChatTime"
             , CDH.dialDuration																								AS "ResponseTime"
             , t_D.DispositionStatus																						AS "DispositionStatus"
             , CH.afterwhatsappWorkTime																						AS "ACWTime"
             , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 														AS "Handled"
             , CDH.Duration  																								AS "Duration"	
             , CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 														AS "UnansweredChat"
			,	CDH.Duration						                  															AS "QueueWaitingTime"
            , 	CH.SentimentalScore		                																AS "CustomerSatisfactionScore"
         FROM 	  	tb_WhatsappHistory 				AS CH
 			JOIN 	  tb_WhatsappDurationHistory	AS CDH		ON CH.WhatsappHistoryId 				= CDH.WhatsappHistoryId
            LEFT JOIN 	  queue							AS Q		ON CDH.QueueId							= Q.qid
            LEFT JOIN	 tb_User						AS U		ON U.UserID								= CDH.AgentId
 			LEFT JOIN temp_AvailableDisposition			AS t_D		ON CH.dispositionId						= t_D.DispositionId
            LEFT JOIN 	customer_contact			AS c_c		ON c_c.coid				= CH.customerId AND	 c_c.domainId		= p_domainId
 		WHERE 	CH.domainId 		= p_domainId
 			AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp; 
         
         DROP TEMPORARY TABLE IF EXISTS result_WA02;
         CREATE TEMPORARY TABLE result_WA02
 			SELECT 
             t1.Date_Col_01 * 1000   														AS "Date_Col_02"
 			,t1.AgentName_01																AS "AgentName_02"
             ,COUNT(t1.Handled)																AS "ChatHandledCount"
             ,ROUND((SUM((t1.Duration/1000) + t1.ACWTime) / COUNT(1)) * 100) 	AS "AverageActiveChatTime"
             ,SUM(t1.UnansweredChat) 														AS "UnansweredChatCount"
             ,ROUND((SUM(t1.responseTime) / COUNT(1)) * 100) 								AS "AverageResponseTime"
             ,SUM(ACWTime)									  								AS "TotalACWTime"
             ,COUNT(1)																		AS "TotalAnsweredChats"
             FROM result_WA01 AS t1
             GROUP BY  t1.Date_Col_01 , t1.AgentName_01;
             
 		DROP TEMPORARY TABLE IF EXISTS result_WA03;
         CREATE TEMPORARY TABLE result_WA03      
 		SELECT 
 			t1.Date_Col_01												AS	"Date"							
 			,t1.`Source`												AS	"Source"	
             ,t1.CustomerName											AS 	CustomerName
             ,t1.AgentName_01											AS	AgentName
             ,t1.QueueName												AS 	QueueName
             ,t1.Direction												AS	Direction
             ,t1.ChatStartTime											AS	ChatStartTime
             ,t1.ChatEndTime											AS	ChatEndTime
             ,t1.DurationOfTheChatConversation							AS	DurationOfTheChatConversation
             ,t1.ActiveChatTime											AS  ActiveChatTime
             ,t1.ResponseTime											AS	ResponseTime
             ,t1.DispositionStatus										AS	DispositionStatus
             ,t1.QueueWaitingTime										AS  QueueWaitingTime
             ,t1.ACWTime													AS 	ACWTime
             , t1.CustomerSatisfactionScore								AS CustomerSatisfactionScore
             ,t2.ChatHandledCount										AS	ChatHandledCount
             ,t2.AverageActiveChatTime									AS	AverageActiveChatTime
             ,t2.UnansweredChatCount										AS	UnansweredChatCount
             ,t2.AverageResponseTime										AS	AverageResponseTime
             ,t2.TotalAnsweredChats											AS 	TotalAnsweredChats
             ,t2.TotalACWTime												AS TotalACWTime
 			FROM result_WA01 AS t1
 			LEFT JOIN result_WA02  AS t2 ON t1.Date_Col_01 = t2.Date_Col_02 AND t1.AgentName_01 = t2.AgentName_02;
  	
     
 	
 
 	
     
         DROP TEMPORARY TABLE IF EXISTS result_IG01;
 		CREATE TEMPORARY TABLE result_IG01
         SELECT 	
 				FROM_UNIXTIME(IH.sessionStartTime/1000) 																AS "Date"
 			,"Instagram"								   											AS "Source"
             ,   CASE WHEN c_c.coid IS NOT NULL THEN CONCAT(c_c.firstName, ' ',c_c.lastName)	ELSE 'New Customer' END 	AS "CustomerName"
 			, 	U.UserName				        																		AS "AgentName"
 			, 	Q.`name` 																								AS "QueueName"
             ,	CASE WHEN IH.IsInBound = 1 THEN 'InBound' WHEN IH.IsInBound = 0 THEN 'OutBound' END 					AS "Direction"
 			, 	IH.AgentStartTime			        																	AS "ChatStartTime"
 			,	IH.AgentEndTime				        																	AS "ChatEndTime"
             ,	IH.Duration                           																	AS "DurationOfTheChatConversation"
             , 	ABS((IH.AgentEndTime-IH.AgentStartTime)/1000)	        												AS "ActiveChatTime"
             ,	IH.repliedDate - IH.createdAt																			AS "ResponseTime"
             ,	t_AD.DispositionStatus																					AS "DispositionStatus"
             ,	IH.Duration						                  														AS "QueueWaitingTime"
             ,	IH.afterInstagramWorkTime					            												AS "ACWTime"
 			, 	IH.SentimentalScore		                																AS "CustomerSatisfactionScore"
             
             ,   IH.customerInstagramId																					AS "customerInstagramId"  
             , 	CASE WHEN t_AD.DispositionCategory = 3 THEN 1 ELSE 0 END 												AS "Handled"
             ,   IH.sessionEndTime-IH.sessionStartTime	 					    										AS "ChatHandlingTime" 
             ,	CASE WHEN t_AD.DispositionId IS NULL THEN 1 ELSE 0 END       											AS "UnansweredChat"
             
         FROM  		tb_InstagramHistory 						AS IH
				LEFT JOIN 	tb_User									AS U			ON U.UserID				= IH.AgentId
                LEFT JOIN 	temp_AvailableDisposition				AS t_AD 		ON IH.dispositionId		= t_AD.DispositionId
 				LEFT JOIN 	  queue									AS Q			ON IH.queueId			= Q.qid
				LEFT JOIN 	customer_contact						AS c_c			ON c_c.coid				= IH.customerInstagramId
 				WHERE 	IH.domainId 			= p_domainId
 					AND IH.sessionStartTime 	BETWEEN v_startTmpstmp AND v_endTmpstmp; 
                     
         
         DROP TEMPORARY TABLE IF EXISTS result_IG02;
         CREATE TEMPORARY TABLE result_IG02
 			SELECT 
 					`Date`						AS Date_02
 					,AgentName					AS AgentName_02
                     ,SUM(Handled)                                     AS "ChatHandledCount"
                     ,ROUND(SUM(ChatHandlingTime) / COUNT(1)) / 1000   AS "AverageActiveChattime"
                     ,SUM(UnansweredChat)                         		AS "UnansweredChatCount"
                     ,round((SUM(ResponseTime) / COUNT(1)) / 1000)     AS "AverageResponseTime"
 					,COUNT(1)										  AS "TotalAnsweredChats"
                     ,SUM(ACWTime)									  AS "TotalACWTime"
                     FROM result_IG01
                     GROUP BY Date_02 , AgentName_02;
                     
         
          DROP TEMPORARY TABLE IF EXISTS result_IG03;
         CREATE TEMPORARY TABLE result_IG03
 				SELECT t1.`Date`									AS "Date"
 					, 	t1.`Source`									AS "Source" 
                      , 	t1.CustomerName								AS "CustomerName"
 					, 	t1.AgentName								AS "AgentName"
                     ,	t1.QueueName								AS	"QueueName"
                      ,	t1.Direction								AS "Direction"
 					, 	t1.ChatStartTime							AS "ChatStartTime"
                     ,	t1.ChatEndTime								AS "ChatEndTime"
                    ,	t1.DurationOfTheChatConversation			AS "DurationOfTheChatConversation"
                     , 	t1.ActiveChatTime							AS "ActiveChatTime"
                     ,	t1.ResponseTime								AS "ResponseTime"
                        ,t1.DispositionStatus						AS "DispositionStatus"
                     , 	t1.QueueWaitingTime							AS "QueueWaitingTime"
                     ,	t1.ACWTime									AS	"ACWTime"
                  ,		t1.CustomerSatisfactionScore				AS "CustomerSatisfactionScore"
                     ,	t2.ChatHandledCount							AS "ChatHandledCount"
                     , 	t2.AverageActiveChattime					AS "AverageActiveChattime"
                     , 	t2.UnansweredChatCount						AS "UnansweredChatCount"
                     , 	t2.AverageResponseTime						AS "AverageResponseTime"
                     ,	t2.TotalAnsweredChats						AS "TotalAnsweredChats"
                     , 	t2.TotalACWTime								AS "TotalACWTime"
 				FROM result_IG01  AS t1 
                LEFT JOIN result_IG02  AS t2 
                 ON t1.`Date` = t2.Date_02 AND t1.AgentName = t2.AgentName_02;
                 
       
 	
	
         DROP TEMPORARY TABLE IF EXISTS result_FB01;
 		CREATE TEMPORARY TABLE result_FB01
         SELECT 	
         
 				FROM_UNIXTIME(FH.sessionStartTime/1000) 																	AS "Date"
 			, 	"Facebook"																										AS "Source"
             ,   CASE WHEN c_c.Facebook IS NOT NULL THEN CONCAT(c_c.firstName, ' ',c_c.lastName)	ELSE 'New Customer' END 	AS "CustomerName"
             , 	U.UserName				        																			AS "AgentName"
             , 	Q.`name` 																									AS "QueueName"
             ,	CASE WHEN FH.IsInBound = 1 THEN 'InBound' WHEN FH.IsInBound = 0 THEN 'OutBound' END 						AS "Direction"
              , 	FH.AgentStartTime			        																		AS "ChatStartTime"
 			,	FH.AgentEndTime				        																		AS "ChatEndTime"
             ,	FH.Duration                           																		AS "DurationOfTheChatConversation"
            , 	ABS((FH.Duration+(FH.afterFacebookWorkTime*1000)))	        												AS "ActiveChatTime"
             ,	FH.dialDuration																								AS "ResponseTime"
 		
             ,	t_AD.DispositionStatus																						AS "DispositionStatus"
 			,	FH.Duration						                  															AS "QueueWaitingTime"
             ,	FH.afterFacebookWorkTime					            													AS "ACWTime"
            , 	FH.SentimentalScore		                																	AS "CustomerSatisfactionScore"
 			
            ,   FH.customerFacebookId																						AS "customerFacebookId"
             , 	CASE WHEN t_AD.DispositionCategory = 3 THEN 1 ELSE 0 END 													AS "Handled"
             ,   FH.sessionEndTime-FH.sessionStartTime	 					    											AS "ChatHandlingTime" 
             ,	CASE WHEN t_AD.DispositionId IS NULL THEN 1 ELSE 0 END       												AS "UnansweredChat"
             
 			FROM  		tb_FacebookHistory 						AS FH
            LEFT JOIN 	tb_User									AS U			ON U.UserID					= FH.AgentId
            LEFT JOIN 	temp_AvailableDisposition				AS t_AD 		ON FH.dispositionId			= t_AD.DispositionId
			LEFT JOIN 	  	queue									AS Q			ON FH.queueId			= Q.qid
 			LEFT JOIN 	customer_contact						AS c_c			ON c_c.facebook				= FH.customerFacebookId
 				WHERE 	FH.domainId 			= p_domainId
 					AND FH.sessionStartTime 	BETWEEN v_startTmpstmp AND v_endTmpstmp; 
                     
                     
         DROP TEMPORARY TABLE IF EXISTS result_FB02;
         CREATE TEMPORARY TABLE result_FB02
 			SELECT 
 					`Date`															AS "Date_02"
 					,AgentName														AS "AgentName_02"
                     ,SUM(Handled)                                    			 	AS "ChatHandledCount"
                     ,SUM(ChatHandlingTime) / COUNT(1)  							AS "AverageActiveChattime"
                     ,SUM(UnansweredChat)                         					AS "UnansweredChatCount"
                     ,(SUM(responseTime) / COUNT(1)) 		   						AS "AverageResponsetime"
 					,COUNT(1)										  				AS "TotalAnsweredChats"
                     ,SUM(ACWTime)									  				AS "TotalACWTime"
                     FROM result_FB01
                     GROUP BY Date_02 , AgentName_02;
                     
         
          DROP TEMPORARY TABLE IF EXISTS result_FB03;
         CREATE TEMPORARY TABLE result_FB03
 				SELECT t1.`Date`									AS "Date"
 					, 	t1.`Source` 								AS "Source" 
                     , 	t1.CustomerName								AS "CustomerName"
                     , 	t1.AgentName								AS "AgentName"
                     , 	t1.QueueName 								AS "QueueName"
                     ,	t1.Direction								AS "Direction"
 					, 	t1.ChatStartTime							AS "ChatStartTime"
                     ,	t1.ChatEndTime								AS "ChatEndTime"
                     ,  t1.DurationOfTheChatConversation			AS "DurationOfTheChatConversation"
                     , 	t1.ActiveChatTime							AS "ActiveChatTime"
                     ,	t1.ResponseTime								AS "ResponseTime"
                     , 	t1.DispositionStatus						AS "DispositionStatus"
                     , 	t1.QueueWaitingTime							AS "QueueWaitingTime"
                     ,	t1.ACWTime									AS	"ACWTime"
                     ,	t1.CustomerSatisfactionScore				AS "CustomerSatisfactionScore"
                     ,	t2.ChatHandledCount							AS "ChatHandledCount"
                     , 	t2.AverageActiveChattime					AS "AverageActiveChattime"
                     , 	t2.UnansweredChatCount						AS "UnansweredChatCount"
                     , 	t2.AverageResponseTime						AS "AverageResponseTime"
                     ,	t2.TotalAnsweredChats						AS "TotalAnsweredChats"
                     , 	t2.TotalACWTime								AS "TotalACWTime"
 				FROM result_FB01  AS t1 
                 LEFT JOIN result_FB02  AS t2 
                 ON t1.`Date` = t2.Date_02 AND t1.AgentName = t2.AgentName_02;
	
        
		DROP TEMPORARY TABLE IF EXISTS SOCMED;
		CREATE TEMPORARY TABLE SOCMED
				SELECT `Date`,`Source`, CustomerName, AgentName, QueueName,Direction, ChatStartTime, ChatEndTime, DurationOfTheChatConversation
                     , 	ActiveChatTime,	ResponseTime, 	DispositionStatus, 	QueueWaitingTime,	ACWTime,	CustomerSatisfactionScore
                     ,	ChatHandledCount, 	AverageActiveChattime, 	UnansweredChatCount, 	AverageResponseTime,TotalAnsweredChats						
                     , 	TotalACWTime FROM result_WA03
				UNION 
				SELECT `Date`,`Source`, CustomerName, AgentName, QueueName,Direction, ChatStartTime, ChatEndTime, DurationOfTheChatConversation
                     , 	ActiveChatTime,	ResponseTime, 	DispositionStatus, 	QueueWaitingTime,	ACWTime,	CustomerSatisfactionScore
                     ,	ChatHandledCount, 	AverageActiveChattime, 	UnansweredChatCount, 	AverageResponseTime,	TotalAnsweredChats						
                     , 	TotalACWTime FROM result_IG03
				UNION 
				SELECT `Date`,`Source`, CustomerName, AgentName, QueueName,Direction, ChatStartTime, ChatEndTime, DurationOfTheChatConversation
                     , 	ActiveChatTime,	ResponseTime, 	DispositionStatus, 	QueueWaitingTime,	ACWTime,	CustomerSatisfactionScore
                     ,	ChatHandledCount, 	AverageActiveChattime, 	UnansweredChatCount, 	AverageResponseTime,	TotalAnsweredChats						
                     , 	TotalACWTime FROM result_FB03;
				
        
         SET @sql_statement = CONCAT('SELECT ',p_custom_column,' FROM ', 'SOCMED');
  
  		PREPARE sample_01 FROM @sql_statement;
  		EXECUTE sample_01;
 		DEALLOCATE PREPARE sample_01;
     
 		SET v_errcode = 1;
 		SET v_errmsg = "Success";

     
     SELECT v_errcode AS "Error_code" , v_errmsg AS "Error Message";
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
