CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_detailsWebsiteScraper`(
   p_domainId  			INT,
   p_websiteId  		VARCHAR(100)
   )
BEGIN
   DECLARE v_errcode  INT DEFAULT -1;
   DECLARE v_errmesg  varchar(50) DEFAULT "Failed";
   DECLARE v_check  TINYINT DEFAULT 0;
   
   SELECT 1 INTO v_check from websiteScraper where domainId = p_domainId  and websiteId = p_websiteId;
   
   IF v_check = 1 THEN 
		select * from websiteScraper where domainId = p_domainId and websiteId = p_websiteId;
     
		SET v_errcode = 1 ;
		SET v_errmesg = "Found successfully";
    END IF;
    
    SELECT v_errcode AS "Error code", v_errmesg AS "Error Message";
   END ;;
DELIMITER ;
