/*!50003 DROP PROCEDURE IF EXISTS `get_dispositionStatusDtl_Dashboard` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_dispositionStatusDtl_Dashboard`(	
	 p_domainId 			INT
 	,p_channelType 		VARCHAR(50)   
 	,p_fromDate 		BIGINT
 	,p_toDate 			BIGINT
 	,p_UserId			INT
 )
BEGIN

	DECLARE v_channelType  varchar(50);
    
    
    
    
   
   
   
   IF p_channelType = 'All' THEN
		SET v_channelType = null; 
   ELSE
		SET v_channelType = p_channelType;
	END IF;
	
    DROP TEMPORARY TABLE IF EXISTS tt_userDtl;
    CREATE TEMPORARY TABLE tt_userDtl(UserID int , UserName varchar(150) , domainId int, roleid int);
    
    INSERT INTO tt_userDtl (UserID, UserName, domainId, roleid) 	
    SELECT UserID, UserName, domainId, roleid  FROM tb_User WHERE domainId = p_domainId AND (UserId = p_UserId OR IFNULL(p_UserId,'') = '')  ;
    
    
    
    DROP TEMPORARY TABLE IF EXISTS tt_dispositionName_Dtl;
    CREATE TEMPORARY TABLE tt_dispositionName_Dtl(domainId int , dispositionName varchar(200));
    
    INSERT INTO tt_dispositionName_Dtl
    SELECt domainId, dispositionName FROM disposition_status WHERE domainId = p_domainId;
    
    
    
    DROP TEMPORARY TABLE IF EXISTS tt_final_Dtl;
    CREATE TEMPORARY TABLE tt_final_Dtl(domainId int , dispositionName varchar(200), `Count` int);
    
    DROP TEMPORARY TABLE IF EXISTS tt_Channel_Dtl;
    CREATE TEMPORARY TABLE tt_Channel_Dtl(domainId INT, agentId INT, dispositionId INT, ChannelType varchar(50) ,dispositionName VARCHAR(100),  dispositionType VARCHAR(200));
    
    
    
    
    
    INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
    
    SELECT CH.domainId,
		   CHD.AgentId, CHD.dispositionId, 'Call' AS ChannelType, 
			
			D.dispositionName, D.`type` 
    FROM 
    tb_CallHistory AS CH
    JOIN tb_CallDurationHistory AS CHD ON CH.CallHistoryId = CHD.CallHistoryId
    JOIN disposition_status AS D ON D.did = CHD.dispositionId
		WHERE CH.domainId = p_domainId 
			AND CH.sessionStartTime between p_fromDate and P_toDate
			AND CHD.AgentId IN (SELECT UserID FROM tt_userDtl);
    
    

    
    
    INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
     
     SELECT CH.domainId,
			CHD.AgentId, CHD.dispositionId, 'Chat' AS ChannelType, 
			D.dispositionName, D.`type` 
    FROM 
		tb_ChatHistory AS CH
			JOIN tb_ChatDurationHistory AS CHD ON CH.ChatHistoryId = CHD.ChatHistoryId
			JOIN disposition_status AS D ON D.did = CHD.dispositionId
				WHERE CH.domainId = p_domainId 
					AND CH.sessionStartTime between p_fromDate and P_toDate
					AND CHD.AgentId IN (SELECT UserID FROM tt_userDtl);
        
        
        
	INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
     
     SELECT EH.DomainId, EH.DispositionId,
			EDH.AgentId, 'Email' AS ChannelType, 
			D.dispositionName, D.`type` 
	 FROM 
		tb_EmailHistory AS EH
			JOIN tb_EmailDurationHistory AS EDH ON EH.EmailHistoryId = EDH.EmailHistoryId
			JOIN disposition_status AS D ON D.did = EH.dispositionId
				WHERE EH.domainId = p_domainId 
					AND EH.sessionStartTime between p_fromDate and P_toDate
					AND EDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
        
        
        
        
	INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
     
     SELECT SH.DomainId, SH.DispositionId,
			SDH.AgentId, 'SMS' AS ChannelType, 
			D.dispositionName, D.`type` 
	 FROM 
		tb_SMSHistory AS SH
			JOIN tb_SMSDurationHistory AS SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
			JOIN disposition_status AS D ON D.did = SH.dispositionId
				WHERE SH.domainId = p_domainId 
					AND SH.sessionStartTime between p_fromDate and P_toDate
					AND SDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
       
        
        
                
	INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
     
     SELECT WH.DomainId, WH.DispositionId,
			WDH.AgentId, 'WhatsApp' AS ChannelType, 
			D.dispositionName, D.`type` 
	 FROM 
		tb_WhatsappHistory AS WH
			JOIN tb_WhatsappDurationHistory AS WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
			JOIN disposition_status AS D ON D.did = WH.dispositionId
				WHERE WH.domainId = p_domainId 
					AND WH.sessionStartTime between p_fromDate and P_toDate
					AND WDH.AgentId IN (SELECT UserID FROM tt_userDtl);
                    
		
        
	INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
        
     SELECT FH.domainId, FH.dispositionId,
			FH.AgentId, 'Facebook' AS ChannelType, 
			D.dispositionName, D.`type` 
	 FROM 
		 tb_FacebookHistory AS FH 
			JOIN disposition_status AS D ON D.did = FH.dispositionId
				WHERE FH.domainId = p_domainId 
					AND FH.sessionStartTime between p_fromDate and P_toDate
					AND FH.AgentId IN (SELECT UserID FROM tt_userDtl);
		
			
            
	INSERT INTO tt_Channel_Dtl(domainId, agentId, dispositionId , ChannelType ,dispositionName,  dispositionType)
        
     SELECT IH.domainId, IH.dispositionId, IH.AgentId,
            'Instagram' AS ChannelType, 
			D.dispositionName, D.`type` 
	 FROM 
		 tb_InstagramHistory AS IH 
			JOIN disposition_status AS D ON D.did = IH.dispositionId
				WHERE IH.domainId = p_domainId 
					AND IH.sessionStartTime between p_fromDate and P_toDate
					AND IH.AgentId IN (SELECT UserID FROM tt_userDtl);
                    

			
		INSERT INTO tt_final_Dtl
			SELECT domainId , dispositionName, count(dispositionName) AS 'Count'
				FROM tt_Channel_Dtl 
				WHERE (ChannelType = v_channelType OR IFNULL(v_channelType,'') = '')
				GROUP BY  domainId , dispositionName;
		
      
        
        SET SESSION transaction isolation level read uncommitted;
        
        SELECT t1.domainId , t1.dispositionName, IFNULL(t2.`Count`,0) AS "Count"
        FROM tt_dispositionName_Dtl  as t1
        LEFT JOIN tt_final_Dtl as t2
        ON t1.dispositionName = t2.dispositionName;
        
        SET SESSION transaction isolation level repeatable read;
            
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_FacebookCustomReports` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_FacebookCustomReports`(
		p_custom_column 			TEXT 
		, p_domainId 				INT 
    	, p_startTmpstmp 			BIGINT 
    	, p_endTmpstmp 				BIGINT
        ,p_lastIsertId				INT
)
SP: BEGIN
	
	DECLARE columnNamePresent 			TEXT;
    DECLARE v_countColumn				INT;  
    DECLARE v_columnMissing				TINYINT DEFAULT 0;
    DECLARE v_errCode					TINYINT DEFAULT 0;
    DECLARE v_errMsg					VARCHAR(100) DEFAULT "Failed";
    DECLARE v_startTmpstmp				BIGINT;
    DECLARE v_endTmpstmp				BIGINT;
    DECLARE v_defaultQueue				VARCHAR(255);


   DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
 	CREATE TEMPORARY TABLE temp_AvailableDisposition 
       		(    DispositionId 			INT
       			,DispositionStatus 		VARCHAR(100)
       			,DispositionCategory	TINYINT
       		); 
               
 	INSERT INTO temp_AvailableDisposition 
 		SELECT 	did 			AS DispositionId
 			,	dispositionName	AS DispositionStatus
 			,	CASE 
 				WHEN dispositionName = 'Opened'	THEN 2
 				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
 				WHEN dispositionName = 'Discarded' THEN 4
 				END 			DispositionCategory
 		FROM 	disposition_status
 		WHERE 	domainId	= p_domainId;
 		
 		
         DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
 		CREATE TEMPORARY TABLE temp_AllqueueId
 			SELECT qid,name as queueName, type from queue where domainId = p_domainId;
 			
 		SELECT 	queueName INTO v_defaultQueue	
 			FROM 	temp_AllqueueId 
 			WHERE 	`type`	= 'Default' LIMIT 1;
            
	SET columnNamePresent = "Date,CustomerName,AgentName,QueueName,Direction,ChatStartTime,ChatEndTime,DurationOfTheChatConversation,ActiveChatTime,ResponseTime,DispositionStatus,ChatStatus,QueueWaitingTime,ACWTime,CustomerSatisfactionScore,ChatHandledCount,AverageActiveChatTime,UnansweredChatCount,AverageResponseTime,TotalAnsweredChats,TotalACWTime";
	
    
    SET v_countColumn = LENGTH(p_custom_column)-LENGTH(REPLACE(p_custom_column,",",""))+1;
    
 
    
	DROP TEMPORARY TABLE IF EXISTS temp_columnMatch;
		CREATE TEMPORARY TABLE temp_columnMatch
  			WITH RECURSIVE eachColumnCheck(n) AS
  			(
  				SELECT 1 AS n
  					UNION ALL
  				SELECT n+1 AS n FROM eachColumnCheck WHERE n < v_countColumn
  			)
		SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(p_custom_column,',',n),',',-1) AS columnName, 
			FIND_IN_SET(SUBSTRING_INDEX(SUBSTRING_INDEX(p_custom_column,',',n),',',-1),columnNamePresent) AS FoundAt 
			FROM eachColumnCheck;
            
            
		SELECT 1 INTO v_columnMissing FROM temp_columnMatch WHERE FoundAt = 0 LIMIT 1;
        
     
        
        IF v_columnMissing =1 THEN 
			
            SET v_errCode = -1;
            SET v_errMsg = "Given columns in Parameter is not Matched";
            
            SELECT v_errCode AS "Error Code", v_errMsg AS "Error Message";
            
            LEAVE SP;
            
		END IF;
        
        IF IFNULL(p_startTmpstmp,0)	= 0 
  			THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; 
  			ELSE SET v_startTmpstmp = p_startTmpstmp;  
  		END IF; 	
  	
  		IF IFNULL(p_endTmpstmp ,0)	= 0 
  			THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; 
  			ELSE SET v_endTmpstmp = p_endTmpstmp; 
  		END IF;
        
        
        
        
        DROP TEMPORARY TABLE IF EXISTS result_FB01;
  		CREATE TEMPORARY TABLE result_FB01
          SELECT 	
          
  				FROM_UNIXTIME(FH.sessionStartTime/1000) 																	AS "Date"
              ,   CASE WHEN c_c.Facebook IS NOT NULL THEN CONCAT(c_c.firstName, ' ',c_c.lastName)	ELSE 'New Customer' END 	AS "CustomerName"
              , 	U.UserName				        																			AS "AgentName"
              , 	Q.`name` 																									AS "QueueName"
              ,	CASE WHEN FH.IsInBound = 1 THEN 'InBound' WHEN FH.IsInBound = 0 THEN 'OutBound' END 						AS "Direction"
               , 	FH.AgentStartTime			        																		AS "ChatStartTime"
  			,	FH.AgentEndTime				        																		AS "ChatEndTime"
              ,	FH.Duration                           																		AS "DurationOfTheChatConversation"
             , 	ABS((FH.Duration+(FH.afterFacebookWorkTime*1000)))	        												AS "ActiveChatTime"
              ,	FH.dialDuration																								AS "ResponseTime"
  		
              ,	t_AD.DispositionStatus																						AS "DispositionStatus"
  			,	FH.Duration						                  															AS "QueueWaitingTime"
              ,	FH.afterFacebookWorkTime					            													AS "ACWTime"
             , 	FH.SentimentalScore		                																	AS "CustomerSatisfactionScore"
             ,   FH.customerFacebookId																						AS "customerFacebookId"
              , 	CASE WHEN t_AD.DispositionCategory = 3 THEN 1 ELSE 0 END 													AS "Handled"
              ,   FH.sessionEndTime-FH.sessionStartTime	 					    											AS "ChatHandlingTime" 
              ,	CASE WHEN t_AD.DispositionId IS NULL THEN 1 ELSE 0 END       												AS "UnansweredChat"
              
  			FROM  		tb_FacebookHistory 						AS FH
             LEFT JOIN 	tb_User									AS U			ON U.UserID					= FH.AgentId
             LEFT JOIN 	temp_AvailableDisposition				AS t_AD 		ON FH.dispositionId			= t_AD.DispositionId
 			LEFT JOIN 	  	queue									AS Q			ON FH.queueId			= Q.qid
  			LEFT JOIN 	customer_contact						AS c_c			ON c_c.facebook				= FH.customerFacebookId
  				WHERE 	FH.domainId 			= p_domainId
  					AND FH.sessionStartTime 	BETWEEN v_startTmpstmp AND v_endTmpstmp;
                    
			
		  DROP TEMPORARY TABLE IF EXISTS result_FB02;
          CREATE TEMPORARY TABLE result_FB02
  			SELECT 
					`Date`															AS "Date_02"
					,AgentName														AS "AgentName_02"
					,SUM(Handled)                                    			 	AS "ChatHandledCount"
					,SUM(ChatHandlingTime) / COUNT(1)  							AS "AverageActiveChattime"
					,SUM(UnansweredChat)                         					AS "UnansweredChatCount"
					,(SUM(responseTime) / COUNT(1)) 		   						AS "AverageResponsetime"
					,COUNT(1)										  				AS "TotalAnsweredChats"
					,SUM(ACWTime)									  				AS "TotalACWTime"
			FROM result_FB01
				GROUP BY Date_02 , AgentName_02;
                      
                      
			DROP TEMPORARY TABLE IF EXISTS result_FB03;
			CREATE TEMPORARY TABLE result_FB03
  				SELECT t1.`Date`									AS "Date"
                      , 	t1.CustomerName								AS "CustomerName"
                      , 	t1.AgentName								AS "AgentName"
                      , 	t1.QueueName 								AS "QueueName"
                      ,	t1.Direction								AS "Direction"
  					, 	t1.ChatStartTime							AS "ChatStartTime"
                      ,	t1.ChatEndTime								AS "ChatEndTime"
                      ,  t1.DurationOfTheChatConversation			AS "DurationOfTheChatConversation"
                      , 	t1.ActiveChatTime							AS "ActiveChatTime"
                      ,	t1.ResponseTime								AS "ResponseTime"
                      , 	t1.DispositionStatus						AS "DispositionStatus"
                      , 	t1.QueueWaitingTime							AS "QueueWaitingTime"
                      ,	t1.ACWTime									AS	"ACWTime"
                      ,	t1.CustomerSatisfactionScore				AS "CustomerSatisfactionScore"
                      ,	t2.ChatHandledCount							AS "ChatHandledCount"
                      , 	t2.AverageActiveChattime					AS "AverageActiveChattime"
                      , 	t2.UnansweredChatCount						AS "UnansweredChatCount"
                      , 	t2.AverageResponseTime						AS "AverageResponseTime"
                      ,	t2.TotalAnsweredChats						AS "TotalAnsweredChats"
                      , 	t2.TotalACWTime								AS "TotalACWTime"
  				FROM result_FB01  AS t1 
                  LEFT JOIN result_FB02  AS t2 
                  ON t1.`Date` = t2.Date_02 AND t1.AgentName = t2.AgentName_02;        
                  
                  
                  IF v_columnMissing = 0 THEN
 	
        
        SET @columns = '';
		SET @keyValuePairs = '';
		WHILE LOCATE(',', p_custom_column) > 0 DO
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_custom_column, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_custom_column, ',', 1)),
										', ');
		SET p_custom_column = SUBSTRING(p_custom_column, LOCATE(',', p_custom_column) + 1);
		END WHILE;
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_custom_column,
									'\', ',
									p_custom_column);

		SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM result_FB03'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;
        
		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId; 
    
		SET v_errcode = 1;
		SET v_errmsg = "Success";

     END IF ;  
     
     SELECT v_errCode AS "Code", v_errMsg AS "Message";
END ;;
DELIMITER ;
