CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_knowledgeBasedId_assist`(
p_fromAddress varchar(200),
p_domainId INT,
P_channelType INT   
)
BEGIN
		IF P_channelType = 1 THEN 
        
			SELECT knowledgeBasedId FROM email_config WHERE emailAddress = p_fromAddress AND domainId = p_domainId;
		
        ELSEIF P_channelType = 2 THEN 
        
        SELECT knowledgeBasedId FROM did_purchase WHERE your_number = p_fromAddress AND domainId = p_domainId;
            
		END IF;
		
END ;;
