CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_planId_for_channel_type`(
p_domainId INT,
p_ChannelType varchar(255) 
)
BEGIN 
DECLARE t_domainR int default 0;

SELECT 1 into t_domainR FROM tb_User WHERE domainId = p_domainId limit 1;

IF t_domainR = 1
THEN 
		IF p_ChannelType = 'Whatsapp'
			THEN
              SELECT planId FROM tb_WhatsappConfiguration where domainId = p_domainId;
		END IF;

        IF p_ChannelType = 'Facebook'
			THEN
             SELECT planId FROM tb_FacebookConfiguration where domainId = p_domainId;
		END IF;
        
		IF p_ChannelType = 'Instagram'
			THEN
             SELECT planId FROM tb_InstagramConfiguration where domainId = p_domainId;
		END IF;
ELSE
SELECT "Domain ID is invalid..." As Error_Message;
END IF;

END ;;
