p_ext                   INT
)
BEGIN
DECLARE v_errcode		TINYINT DEFAULT -1;
DECLARE v_errmsg        VARCHAR(50) DEFAULT "Failed/Data is not avaiable...";
DECLARE v_check  		TINYINT DEFAULT 0;

SELECT 1 INTO v_check FROM tb_User WHERE domainId = p_domainId AND ext = p_ext;

IF v_check = 1 THEN 
	SELECT UserName, ProfileImage FROM tb_User WHERE domainId = p_domainId AND ext = p_ext;
    SET v_errcode = 1;
    SET v_errmsg =  "Data Found Successfully";
END IF;

SELECT v_errcode AS "Error Code", v_errmsg AS "Error Message";

END ;;
