CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `get_ScopeTitle`(
  p_scopeTitle    Varchar(100)
          )
BEGIN     
        	DECLARE v_Total_count 	INT;
            
  		DROP TEMPORARY TABLE IF EXISTS temp_Scope; 
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	CREATE TEMPORARY TABLE temp_Scope AS 	    	
 		SELECT      
           ST.scopeTitle,
           SS.scope,
           SS.scopeId
           FROM
           tb_scopeTitle ST
   JOIN    tb_scope      SS           ON ST.scopeTitleId=SS.scopeTitleId
   where ST.scopeTitle = ifnull(p_scopeTitle,'Ccaas');
   
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     
     SELECT * FROM temp_Scope;
     END ;;
