DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_user_report_contact_details`(
	 p_ReportId 					INT
    ,p_DomainId 				  	INT
    ,p_agentId						INT
)
sp:BEGIN
		DECLARE v_check_agent				INT DEFAULT 0;
        DECLARE v_check_report				INT DEFAULT 0;
        DECLARE v_extract_agent				VARCHAR(500);
        DECLARE v_count_agent				INT;
		DECLARE v_err_msg					VARCHAR(100) DEFAULT "Failed";
		DECLARE v_err_code					TINYINT DEFAULT 0;
    
    SELECT 1 INTO v_check_agent FROM tb_User
    WHERE domainId =  p_DomainId AND UserID = p_agentId;
    
    SELECT 1 INTO v_check_report FROM tb_custom_report_dtl
    WHERE domainId =  p_DomainId AND reportId = p_ReportId;
    
    IF v_check_agent = 0 OR v_check_report = 0	THEN 
    
		SET v_err_msg = "Agent/Report not found...";
        SET v_err_code = -1;
        
        SELECT v_err_code AS "Error_Code", v_err_msg AS "Error_Message";
        leave sp;
        
	ELSEIF v_check_agent = 1 AND v_check_report = 1 THEN
    
		set v_extract_agent = (SELECT agentId FROM tb_custom_report_dtl 
			WHERE domainId = p_DomainId 
			AND reportId =  p_ReportId);
            
	   SELECT length(v_extract_agent)-length(REPLACE(v_extract_agent,',',''))+1 INTO v_count_agent FROM tb_custom_report_dtl
			WHERE domainId = p_DomainId 
				AND reportId =  p_ReportId;
                
   
        
        DROP TEMPORARY TABLE IF EXISTS tt_agent_id_collection;
        CREATE TEMPORARY TABLE tt_agent_id_collection
        WITH RECURSIVE count_agent(n) AS
        (
        SELECT 1 AS n
        UNION ALL
        SELECT n+1 As n FROM count_agent
        WHERE n< (v_count_agent)
        )SELECT SUBSTRING_INDEX( SUBSTRING_INDEX(v_extract_agent,",",n), ',', -1) AS AgentId, p_ReportId AS ReportId  FROM count_agent;
        
    
        
        SELECT t1.AgentId
			, t2.UserName 
			, CASE WHEN t2.roleid = 1 THEN "Owner"
					WHEN t2.roleid = 2 THEN "Sub Owner"
                    WHEN t2.roleid = 3 THEN "Admin"
                    WHEN t2.roleid = 4 THEN "Member"
                    WHEN t2.roleid = 5 THEN "Supervisor"
                    WHEN t2.roleid = 6 THEN "Agent"
				END AS "Role"
			,date_format(t3.createdAt,"%Y-%m-%d") AS "Created Date"
            , t3.expireDate AS "Expired Date"
        FROM tt_agent_id_collection 			AS t1
        JOIN tb_User							AS t2 ON t1.AgentId = t2.UserID
        JOIN tb_custom_report_dtl				AS t3 ON t1.ReportId = t3.reportId 
			WHERE t2.domainId = p_DomainId AND t3.domainId = p_DomainId;
        
		SET v_err_msg = "Success...";
        SET v_err_code = 1;
        		
	END IF;
    
    SELECT v_err_code AS Error_Code, v_err_msg AS Error_Message;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_user_report_contact_details_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
