CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `get_Vistor_Insights`(
 	 p_startTmpstmp  	DATETIME,
 	 p_endTmpstmp 	    DATETIME,
	 p_domainId         INT,
 	 p_Limit		    INT,    
 	 p_Offset			INT
       )
BEGIN     
 		DECLARE v_startTmpstmp 	DATETIME;
     	DECLARE v_endTmpstmp 	DATETIME;
     	DECLARE v_Total_count 	INT;
     	DECLARE v_offset		INT; 
         
 		SET v_offset =  p_Limit * p_Offset; 
 		IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
     	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
         
 	DROP TEMPORARY TABLE IF EXISTS temp_VistorInsights; 
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	CREATE TEMPORARY TABLE temp_VistorInsights AS 	    	
     	SELECT
         CH.Id, 
 		CH.vistorId,
 		CH.location, 
 		CH.deviceType, 
 		CH.domainId, 
 		CH.ipAddress,
 		CH.browser,
 		CH.language, 
 		CH.duration, 
 		CH.inTime,
 		CH.outTime, 
 		CH.entryPage,
 		CH.exitPage, 
 		CH.totalPageView,
        CH.originURL,
		CC.coid
 FROM tb_VistorInsights CH 
  JOIN customer_contact  CC      ON   CC.coid     = CH.vistorId
                                 AND  CC.domainId = CH.domainId
 WHERE 	CH.domainId = p_domainId		
  AND 	CH.inTime 	BETWEEN v_startTmpstmp and v_endTmpstmp;
 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 SELECT COUNT(1)  totalCount FROM 	temp_VistorInsights;                                  
 SELECT * FROM temp_VistorInsights;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_WhatsappCustomReports` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `get_WhatsappCustomReports`(
	p_custom_column 			TEXT 
	, p_domainId 				INT 
	, p_startTmpstmp 			BIGINT 
	, p_endTmpstmp 				BIGINT
    ,p_lastIsertId				INT
)
SP:BEGIN

	DECLARE columnNamePresent 			TEXT;
    DECLARE v_countColumn				INT;  
    DECLARE v_columnMissing				TINYINT DEFAULT 0;
    DECLARE v_errCode					TINYINT DEFAULT 0;
    DECLARE v_errMsg					VARCHAR(100) DEFAULT "Failed";
    DECLARE v_startTmpstmp				BIGINT;
    DECLARE v_endTmpstmp				BIGINT;
    DECLARE v_defaultQueue				VARCHAR(255);
    
            
		SET columnNamePresent = "Date,CustomerName,AgentName,QueueName,Direction,ChatStartTime,ChatEndTime,DurationOfTheChatConversation,ActiveChatTime,ResponseTime,DispositionStatus,ChatStatus,QueueWaitingTime,ACWTime,CustomerSatisfactionScore,ChatHandledCount,AverageActiveChatTime,UnansweredChatCount,AverageResponseTime,TotalAnsweredChats,TotalACWTime";

		 SET v_countColumn = LENGTH(p_custom_column)-LENGTH(REPLACE(p_custom_column,",",""))+1;
         
    
	DROP TEMPORARY TABLE IF EXISTS temp_columnMatch;
		CREATE TEMPORARY TABLE temp_columnMatch
  			WITH RECURSIVE eachColumnCheck(n) AS
  			(
  				SELECT 1 AS n
  					UNION ALL
  				SELECT n+1 AS n FROM eachColumnCheck WHERE n < v_countColumn
  			)
		SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(p_custom_column,',',n),',',-1) AS columnName, 
			FIND_IN_SET(SUBSTRING_INDEX(SUBSTRING_INDEX(p_custom_column,',',n),',',-1),columnNamePresent) AS FoundAt 
			FROM eachColumnCheck;
            
	SELECT 1 INTO v_columnMissing FROM temp_columnMatch WHERE FoundAt = 0 LIMIT 1;
        
 
        
        IF v_columnMissing =1 THEN 
			
            SET v_errCode = -1;
            SET v_errMsg = "Given columns in Parameter is not Matched";
            
            SELECT v_errCode AS "Error Code", v_errMsg AS "Error Message";
            
            LEAVE SP;
            
		END IF;
		
        
        IF IFNULL(p_startTmpstmp,0)	= 0 
  			THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; 
  			ELSE SET v_startTmpstmp = p_startTmpstmp;  
  		END IF; 	
  	
  		IF IFNULL(p_endTmpstmp ,0)	= 0 
  			THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; 
  			ELSE SET v_endTmpstmp = p_endTmpstmp; 
  		END IF;
        
						DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
						CREATE TEMPORARY TABLE temp_AvailableDisposition 
							(    DispositionId 			INT
								,DispositionStatus 		VARCHAR(100)
								,DispositionCategory	TINYINT
							); 
               
					INSERT INTO temp_AvailableDisposition 
						SELECT 	did 			AS DispositionId
						,	dispositionName	AS DispositionStatus
						,	CASE WHEN dispositionName = 'Opened'	THEN 2
								WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
								WHEN dispositionName = 'Discarded' THEN 4
							END 			DispositionCategory
				FROM 	disposition_status
					WHERE 	domainId	= p_domainId;
 		
 		
				DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
					CREATE TEMPORARY TABLE temp_AllqueueId
						SELECT qid,name as queueName, type from queue where domainId = p_domainId;
 			
					SELECT 	queueName INTO v_defaultQueue	
						FROM 	temp_AllqueueId 
						WHERE 	`type`	= 'Default' LIMIT 1;
                        
                        
                        	DROP temporary TABLE IF EXISTS result_WA01; 
  		CREATE temporary table result_WA01
          SELECT 
  			FROM_UNIXTIME(CH.sessionStartTime/1000)    																		AS "Date_Col_01"
  			,CASE WHEN c_c.coid IS NOT NULL AND (c_c.firstName IS NOT NULL OR c_c.lastName IS NOT NULL) THEN 
 				TRIM(CONCAT(IFNULL(c_c.firstName, ''), ' ',IFNULL(c_c.lastName, '')))ELSE NULL END 							AS 'customerName'
              , U.UserName																									AS "AgentName_01"  
              , Q.`name` 																									AS "QueueName"
  			, CASE WHEN CH.IsInBound  = 0 THEN 'OutBound' ELSE 'InBound' END        										AS "Direction"
              , CH.sessionStartTime																							AS "ChatStartTime"
  			, CASE WHEN CH.sessionEndTime > 0 THEN CH.sessionEndTime ELSE NULL END		  									AS "ChatEndTime"
  			, CDH.Duration                           																		AS "DurationOfTheChatConversation"
              , abs((CH.sessionEndTime-CH.sessionStartTime)/1000)															AS "ActiveChatTime"
              , CDH.dialDuration																								AS "ResponseTime"
              , t_D.DispositionStatus																						AS "DispositionStatus"
              , CH.afterwhatsappWorkTime																						AS "ACWTime"
              , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 														AS "Handled"
              , CDH.Duration  																								AS "Duration"	
              , CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 														AS "UnansweredChat"
 			,	CDH.Duration						                  															AS "QueueWaitingTime"
             , 	CH.SentimentalScore		                																AS "CustomerSatisfactionScore"
          FROM 	  	tb_WhatsappHistory 				AS CH
  			JOIN 	  tb_WhatsappDurationHistory	AS CDH		ON CH.WhatsappHistoryId 				= CDH.WhatsappHistoryId
             LEFT JOIN 	  queue							AS Q		ON CDH.QueueId							= Q.qid
             LEFT JOIN	 tb_User						AS U		ON U.UserID								= CDH.AgentId
  			LEFT JOIN temp_AvailableDisposition			AS t_D		ON CH.dispositionId						= t_D.DispositionId
             LEFT JOIN 	customer_contact			AS c_c		ON c_c.coid				= CH.customerId AND	 c_c.domainId		= p_domainId
  		WHERE 	CH.domainId 		= p_domainId
  			AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp; 
            
            
              DROP TEMPORARY TABLE IF EXISTS result_WA02;
          CREATE TEMPORARY TABLE result_WA02
  			SELECT 
              t1.Date_Col_01 * 1000   														AS "Date_Col_02"
  			,t1.AgentName_01																AS "AgentName_02"
              ,COUNT(t1.Handled)																AS "ChatHandledCount"
              ,ROUND((SUM((t1.Duration/1000) + t1.ACWTime) / COUNT(1)) * 100) 	AS "AverageActiveChatTime"
              ,SUM(t1.UnansweredChat) 														AS "UnansweredChatCount"
              ,ROUND((SUM(t1.responseTime) / COUNT(1)) * 100) 								AS "AverageResponseTime"
              ,SUM(ACWTime)									  								AS "TotalACWTime"
              ,COUNT(1)																		AS "TotalAnsweredChats"
              FROM result_WA01 AS t1
              GROUP BY  t1.Date_Col_01 , t1.AgentName_01;
              
           DROP TEMPORARY TABLE IF EXISTS result_WA03;
          CREATE TEMPORARY TABLE result_WA03      
  		SELECT 
  			t1.Date_Col_01												AS	"Date"							
              ,t1.CustomerName											AS 	CustomerName
              ,t1.AgentName_01											AS	AgentName
              ,t1.QueueName												AS 	QueueName
              ,t1.Direction												AS	Direction
              ,t1.ChatStartTime											AS	ChatStartTime
              ,t1.ChatEndTime											AS	ChatEndTime
              ,t1.DurationOfTheChatConversation							AS	DurationOfTheChatConversation
              ,t1.ActiveChatTime											AS  ActiveChatTime
              ,t1.ResponseTime											AS	ResponseTime
              ,t1.DispositionStatus										AS	DispositionStatus
              ,t1.QueueWaitingTime										AS  QueueWaitingTime
              ,t1.ACWTime													AS 	ACWTime
              , t1.CustomerSatisfactionScore								AS CustomerSatisfactionScore
              ,t2.ChatHandledCount										AS	ChatHandledCount
              ,t2.AverageActiveChatTime									AS	AverageActiveChatTime
              ,t2.UnansweredChatCount										AS	UnansweredChatCount
              ,t2.AverageResponseTime										AS	AverageResponseTime
              ,t2.TotalAnsweredChats											AS 	TotalAnsweredChats
              ,t2.TotalACWTime												AS TotalACWTime
  			FROM result_WA01 AS t1
  			LEFT JOIN result_WA02  AS t2 ON t1.Date_Col_01 = t2.Date_Col_02 AND t1.AgentName_01 = t2.AgentName_02;   
     
        IF v_columnMissing = 0 THEN
 		
        
     SET @columns = '';
		SET @keyValuePairs = '';
		WHILE LOCATE(',', p_custom_column) > 0 DO
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
										'\'',
										TRIM(SUBSTRING_INDEX(p_custom_column, ',', 1)),
										'\', ',
										TRIM(SUBSTRING_INDEX(p_custom_column, ',', 1)),
										', ');
		SET p_custom_column = SUBSTRING(p_custom_column, LOCATE(',', p_custom_column) + 1);
		END WHILE;
		SET @keyValuePairs = CONCAT(@keyValuePairs, 
									'\'',
									p_custom_column,
									'\', ',
									p_custom_column);

		SET @query = CONCAT(
			'SELECT JSON_ARRAYAGG(JSON_OBJECT(', 
			@keyValuePairs,
			')) AS result FROM result_WA03'
		);

		DROP TEMPORARY TABLE IF EXISTS temp_json_result;
		CREATE TEMPORARY TABLE temp_json_result (result LONGTEXT);

		SET @query = CONCAT('INSERT INTO temp_json_result ', @query);
		PREPARE stmt FROM @query;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;
        
		SELECT result INTO @json_result FROM temp_json_result;
		
		UPDATE tb_custom_report_dtl
		SET finalReportValue = @json_result
		WHERE reportId = p_lastIsertId; 
    
		SET v_errcode = 1;
		SET v_errmsg = "Success";
    END IF ;    
     
   

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
