CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `get_WorktualApp`(
   p_appId   INT)
BEGIN
   DECLARE v_Total_count 	INT;
   
           DROP TEMPORARY TABLE IF EXISTS temp_WorktualApp; 
        	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        	CREATE TEMPORARY TABLE temp_WorktualApp AS 	
           SELECT 
           PA.appId,
           PA.name,
           PA.description,
           PA.token,
           PA.logo,
           PA.domainId,
           PA.siploginid,
           PA.ext
           FROM tb_worktualApp PA
           WHERE PA.appId =p_appId;
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      SELECT COUNT(1)  Total_count FROM temp_WorktualApp;                                  
      SELECT * FROM temp_WorktualApp;
      END ;;
