CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `get_worktualApp_List`(
      p_domainId    INT,
      p_isPublicApp TINYINT,
      p_productType VARCHAR(50) ,
      p_siploginid  INT
      )
BEGIN
       select 
       appId,
       name,
       description,
       token,
       logo,
       clientId,
       clientSecret,
       redirectUrl,
       isPublicApp,
       domainId,
       siploginid,
       ext,
       productType
       FROM 
       tb_worktualApp              
       where domainId=p_domainId
       and isPublicApp=p_isPublicApp
       and productType=p_productType
       and isDelete is null
       and case when p_productType ='ucaas' then siploginid =p_siploginid else siploginid is null end ;
       END ;;
DELIMITER ;
