/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `Inboundchat_analysis_metrics`(
		p_startTmpstmp 		BIGINT,
    	p_endTmpstmp 		BIGINT,
    	p_timeZone 			VARCHAR(200),
    	p_domainId 			INT,
    	p_queueId 			TEXT,
 	    p_Limit 			INT,	   
   	    p_offset 			INT
	)
begin
		DECLARE v_offset 		INT;	
     	DECLARE v_Total_Count 	INT;        
       	DECLARE v_startTmpstmp 	BIGINT;
       	DECLARE v_endTmpstmp 	BIGINT;
    
    SET v_offset =  p_Limit * p_offset;   
                  
        	IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
        	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
        
		   DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
      	
       
      	CALL split(p_queueIds,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
     
          
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
          
		  DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
          CREATE TEMPORARY TABLE temp_AllqueueId
          SELECT qid,name as queueName from queue where domainId = p_domainId ;
          
	                                               
        
        
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
        DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
       	CREATE TEMPORARY TABLE temp_sessionHistory as

        SELECT 	 
					 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		   						 						AS SessionDate
					,Q.qid																											AS queueId
					,CASE WHEN Q.name IS NOT NULL THEN Q.name ELSE '-'  END         												AS queueName
					,CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '-'	end 									AS abondedchats
                    ,CASE WHEN (SH.repliedDate - SH.createdAt) is not null then (SH.repliedDate - SH.createdAt) else '-' end  		AS responseTime
					,U.UserName				AS agentName	 		
					,CH.customerNumber     
					,CASE WHEN trim(CONCAT(C_C.firstName, ' ',C_C.lastName)) <> ''  THEN CONCAT(C_C.firstName, ' ',C_C.lastName)	ELSE 'New Customer' END as customerName                            
					,CH.queueDuration		
			FROM 	tb_CallHistory 			CH
			JOIN 	tb_CallDurationHistory	CDH	    ON CH.CallHistoryId = CDH.CallHistoryId
			LEFT JOIN 	tb_User				U	    ON U.UserID			= CDH.AgentId
			LEFT JOIN 	queue				Q	    ON CDH.QueueId		= Q.qid
			LEFT JOIN customer_contact		C_C	    ON C_C.coid			= CH.CustomerId
			LEFT JOIN temp_queueIDs 		t_Q     ON Q.qid			= t_Q.queueId 
			LEFT JOIN temp_agentIDs 		t_A     ON U.UserID 		= t_A.agentId   
			WHERE 	CH.domainId 			= p_domainId 		
			AND 	CH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp 
			AND 	(IFNULL(p_queueIds,'') 	= '' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL))
			LIMIT v_offset, p_Limit;  
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
			
            SELECT COUNT(1) totalCount FROM temp_chatHistory;
            
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
			SELECT 
						 t_SH.queueName																					AS queueName
                        ,count(1)																						AS receivedchats 
                        ,t_SH.responseTime																				AS respondedchat
                        , t_SH.abondedchats																				AS abondedchats
                        FROM 	temp_chatHistory t_SH
                        GROUP BY  t_SH.queueName,t_SH.responseTime	,t_SH.abondedchats;
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
			
            END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Inbound_trendchart2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `Inbound_trendchart2`(
    p_startTmpstmp BIGINT,
    p_endTmpstmp BIGINT,
    p_domainId INT
)
BEGIN
    DECLARE v_startTmpstmp BIGINT;
    DECLARE v_endTmpstmp BIGINT;
    DECLARE v_currenttimestamp DATETIME;
    DECLARE v_previous_timestamp DATETIME;
    DECLARE v_oneday_previous_timestamp DATETIME;
    DECLARE v1_count_currentdata INT;
    DECLARE v2_count_pastdata INT;

    DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    CREATE TEMPORARY TABLE temp_Intervals (
        starttime DATETIME,
        endtime DATETIME
    );

    DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
    CREATE TEMPORARY TABLE temp_ChatHistory
    SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
    FROM tb_ChatHistory H
    WHERE H.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;

    SET v_startTmpstmp := p_startTmpstmp;
    WHILE v_startTmpstmp < p_endTmpstmp DO
        INSERT INTO temp_Intervals (starttime, endtime)
        VALUES (FROM_UNIXTIME(v_startTmpstmp), FROM_UNIXTIME(v_startTmpstmp + 60));
        SET v_startTmpstmp := v_startTmpstmp + 60;
    END WHILE;

    SELECT t_I.endtime AS 'Time', 
           COUNT(1) AS NoofreceivedchatCount
    FROM temp_Intervals t_I
    JOIN temp_ChatHistory H ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
    GROUP BY t_I.endtime;

    
    SET v_currenttimestamp := NOW();
    SET v_previous_timestamp := DATE_SUB(NOW(), INTERVAL 1 DAY);
    SET v_oneday_previous_timestamp := DATE_SUB(NOW(), INTERVAL 2 DAY);

    
    SELECT COUNT(1) INTO v1_count_currentdata
    FROM tb_ChatHistory 
    WHERE sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;

    
    SELECT COUNT(1) INTO v2_count_pastdata
    FROM tb_ChatHistory 
    WHERE sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp;

    
    SELECT v1_count_currentdata AS currentdata,
           v2_count_pastdata AS pastdata,
           (v1_count_currentdata - v2_count_pastdata) AS difference,
           ((v1_count_currentdata - v2_count_pastdata) / v1_count_currentdata) * 100 AS percentage;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `InsertChatConnection` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `InsertChatConnection`(
    IN p_domainId INT,
    IN p_ext INT,
    IN p_socketId VARCHAR(50)
)
BEGIN
    INSERT INTO chat_connections (domainId, ext, socketId)
    VALUES (p_domainId, p_ext, p_socketId);
