CREATE DEFINER=`dbdev`@`%` PROCEDURE `insertOnboardUser`(
 	p_UserName					varchar(255),
 	p_emailId					varchar(255),
 	p_directNumber				bigint,
 	p_address					varchar(255),
 	p_routing_profile_id		int,
 	p_report_to_UserID			bigint,
 	p_sipLoginId				int,
 	p_companyId					int,
 	p_domainId					int,
 	p_ext						int,
 	p_isActive					tinyint,
 	p_callTypeId				int,
 	p_roleid					tinyint,
 	p_localization				varchar(20),
 	p_currentSession			varchar(100),
 	p_isVoice					tinyint,
 	p_isVoiceCallTransfer		tinyint,
 	p_isChat					tinyint,
 	p_isChatTransfer			tinyint,
 	p_isEmail					tinyint,
 	p_isEmailTransfer			tinyint,
 	p_isSms						tinyint,
 	p_isSocialMedia				tinyint,
 	p_voice						int,
 	p_chat						int,
 	p_email						int,
 	p_sms						int,
 	p_socialMedia				int,
 	p_chatFlag					tinyint,
 	p_companyName				varchar(64),
 	p_UserID					int, 
 	p_ProfileImage				text,
 	p_pri_language				varchar(100), 
 	p_emp_id					varchar(20),
	p_ProductId					INT,
	p_department				VARCHAR(100)
  )
begin
		declare errcode 	INT default -1; 
		declare errmsg 		VARCHAR(255) default 'Already Exists';
		declare v_CurDate 	DATETIME;
		DECLARE v_JLength 	SMALLINT;
		DECLARE v_userId 	INT;
              
   		spexit : Begin
   			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;

                SET v_CurDate = NOW();
                
                IF IFNULL(p_UserID,'') = ''
                THEN
					SET errcode = -1;  
					SET errmsg = 'UserID should not be null';
                    LEAVE spexit;
				END IF;
              
          		If not exists ( select 	1 
    							from 	tb_User 
      							where 	(emailId	COLLATE utf8mb4_0900_ai_ci	= p_emailId or emp_id COLLATE utf8mb4_0900_ai_ci = p_emp_id)
                               and 	domainId	= p_domainId)
   			then
                  insert into tb_User
                  (
							UserName,
							emailId,
							directNumber,
							address,
							routing_profile_id,
							report_to_UserID,
							sipLoginId,
							companyId,
							domainId,
							ext,
							isActive,
							callTypeId,
							roleid,
							localization,
							currentSession,
							isVoice,
							isVoiceCallTransfer,
							isChat,
							isChatTransfer,
							isEmail,
							isEmailTransfer,
							isSms,
							isSocialMedia,
							companyName,
							voice,
							chat,
							email,
							sms,
							socialMedia,
							chatFlag,
							createdAt,
							updatedAt,
							UserID,
							ProfileImage,
							emp_id,
                            recording,	
                            knowledgeBase 
        				)
        				  value
        				  (
							p_UserName		,		
							p_emailId		,			
							p_directNumber	,		
							p_address		,	
							p_routing_profile_id,
							p_report_to_UserID,	
							p_sipLoginId	,	
							p_companyId		,		
							p_domainId		,		
							p_ext			,		
							p_isActive		,			
							p_callTypeId	,			
							p_roleid		,		
							p_localization	,		
							p_currentSession,		
							p_isVoice			,	
							p_isVoiceCallTransfer,	
							p_isChat			,	
							p_isChatTransfer	,	
							p_isEmail			,		
							p_isEmailTransfer	,	
							p_isSms			,		
							p_isSocialMedia	,		
							p_companyName		,
							p_voice			,			
							p_chat			,			
							p_email			,		
							p_sms			,		
							p_socialMedia	,
							p_chatFlag,
							v_CurDate	,
							v_CurDate,
							p_UserID		,
							p_ProfileImage	,
							p_emp_id ,
                            1 ,
                            1
        				);      
                        
			SET v_userId	= last_insert_id();
            
            IF NOT EXISTS ( SELECT 1 FROM tb_my_plan_role_permission WHERE domainId = p_domainId AND role_id = 5 LIMIT 1)
			 THEN
				INSERT INTO tb_my_plan_role_permission (domainId, role_id, is_agent_monitor, is_queue_management, is_reporting_dashboard, is_knowledge_base, createdAt, updated_at)
				VALUES (p_domainId, 5, 1, 1, 1, 0, NOW(), NOW());
			END IF;

			IF NOT EXISTS ( SELECT 1 FROM tb_my_plan_role_permission WHERE domainId = p_domainId AND role_id = 6 LIMIT 1)
			 THEN
				INSERT INTO tb_my_plan_role_permission (domainId, role_id, is_agent_monitor, is_queue_management, is_reporting_dashboard, is_knowledge_base, createdAt, updated_at)    
				VALUES (p_domainId, 6, 0, 0, 1, 0, NOW(), NOW());
			END IF;

			IF NOT EXISTS ( SELECT 1 FROM tb_my_plan_role_permission WHERE domainId = p_domainId AND role_id = 3 LIMIT 1)
			 THEN
				INSERT INTO tb_my_plan_role_permission (domainId, role_id, is_agent_monitor, is_queue_management, is_reporting_dashboard, is_knowledge_base, createdAt, updated_at)
				VALUES (p_domainId, 3, 1, 1, 1, 1, NOW(), NOW());
			END IF;
                 
            CALL up_Ticket_CreateDefaultGroup(p_companyId, p_ProductId, v_userId, p_department);     
                 
 			INSERT INTO tb_userAddonLanguageInfo(domainId,userId,ext,pri_language,createdAt,updatedAt)
   			VALUES(p_domainId,p_UserID,p_ext,p_pri_language,now(),now());
        						  
                  if row_count() > 0  
                      Then  
                            set errcode = 0;  
                            set errmsg = 'Inserted successfuly';  
                             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                       End if; 
                  end if;
             end spexit;     
        	  
        	select errcode as errcode, errmsg as errmsg,ifnull(p_UserID,v_userId) as userId; 
      end ;;
DELIMITER ;
