CREATE DEFINER=`dbdev`@`%` PROCEDURE `insertUpdate_ChatBotPaymentIntegration`(
   p_tokenId INT,
   p_companyId INT,
   p_domainId INT,
   p_paymentType VARCHAR(50),
   p_secretJson JSON
 )
spreturn : BEGIN
 
	   DECLARE v_errcode INT;
	   DECLARE v_errmsg VARCHAR(50);
 
		IF p_companyId IS NULL 
        THEN
			SET v_errcode = -1;
			SET v_errmsg = 'CompanyId should not be empty';
			SELECT v_errcode AS errcode, v_errmsg AS errmsg;
			LEAVE spreturn;
		END IF;

		IF (p_tokenId IS NULL OR p_tokenId = 0) THEN
		 IF EXISTS(SELECT 1 FROM ChatBotPaymentIntegration WHERE paymentType collate utf8mb4_unicode_ci = p_paymentType AND companyId collate utf8mb4_unicode_ci = p_companyId) THEN
		   SET v_errcode = -1;
		   SET v_errmsg = 'Record already exists';
		   SELECT v_errcode AS errcode, v_errmsg AS errmsg;
		   LEAVE spreturn;
		 END IF;
		END IF;

		IF NOT EXISTS(SELECT 1 FROM ChatBotPaymentIntegration WHERE tokenId collate utf8mb4_unicode_ci = p_tokenId AND companyId collate utf8mb4_unicode_ci = p_companyId) THEN
		INSERT INTO ChatBotPaymentIntegration (companyId, domainId, paymentType, secretJson ,createdAt, updatedAt)
		VALUES (p_companyId, p_domainId, p_paymentType, p_secretJson, NOW(), NOW());

		IF ROW_COUNT() > 0 THEN
		SET v_errcode = 1;
		SET v_errmsg = 'Inserted Successfully';
		ELSE
		SET v_errcode = -1;
		SET v_errmsg = 'Not Inserted';
		END IF;
		ELSE
		UPDATE ChatBotPaymentIntegration SET secretJson = p_secretJson , updatedAt = NOW()
		WHERE tokenId = p_tokenId AND companyId = p_companyId;

     IF ROW_COUNT() > 0 THEN
       SET v_errcode = 1;
       SET v_errmsg = 'Updated Successfully';
     ELSE
       SET v_errcode = -1;
       SET v_errmsg = 'Not Updated';
     END IF;
   END IF;
 
   SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
