CREATE DEFINER=`dbdev`@`%` PROCEDURE `Insert_and_Update_TimeNotification_CCAASMobile`(
p_domain 						INT,
p_ext 							INT,
p_startime 						VARCHAR(50),
p_endtime 						VARCHAR(50)
)
BEGIN

	DECLARE v_errcode 					TINYINT 		DEFAULT -1;
	DECLARE v_errmsg 					VARCHAR(50) 	DEFAULT "Failed to Update...";
    DECLARE v_CHECK_t1 					TINYINT 		DEFAULT 0;
    DECLARE v_CHECK_t2 					TINYINT 		DEFAULT 0;
    DECLARE v_startTime_r               TIME;
    DECLARE v_endTime_r                	TIME;
    
    SELECT 1 INTO v_CHECK_t1 FROM tb_user WHERE DomainId = p_domain AND EXT = p_ext;
    SELECT 1 INTO v_CHECK_t2 FROM tb_CCAASMobile_CustomNotification_dtl WHERE DomainId = p_domain AND EXT = p_ext;
    
    SET v_startTime_r 	= 	STR_TO_DATE(p_startime, '%h:%i %p');
    SET v_endTime_r 	= 	STR_TO_DATE(p_endtime, '%h:%i %p');
    
    IF v_CHECK_t1 = 1 THEN
	
		IF v_CHECK_t2 = 1 THEN 
			UPDATE tb_CCAASMobile_CustomNotification_dtl 
            SET StartTime = v_startTime_r, EndTime = v_endTime_r, UpdatedAt = now(), isCustomNotification =1
            WHERE DomainId = p_domain AND EXT = p_ext;
            
            SET v_errcode = 1;
            SET v_errmsg = "Updated Successfully";
            
		ELSE
			UPDATE tb_user SET isCustomNotification =1 WHERE DomainId = p_domain AND EXT = p_ext;
            
            INSERT INTO tb_CCAASMobile_CustomNotification_dtl(DomainId, EXT,  StartTime, EndTime, CreatedAt, isCustomNotification) 
            VALUES(p_domain, p_ext, v_startTime_r, v_endTime_r, now(), 1);
            
            SET v_errcode = 2;
            SET v_errmsg = "Inserted Successfully";
		END IF;
	END IF;
    
    SELECT v_errcode AS 'Error Code', v_errmsg AS 'Error Message';
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
