CREATE DEFINER=`dbdev`@`%` PROCEDURE `insert_disposition_status_for_all_domains`()
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE currentDomainId INT;
    DECLARE domain_cursor CURSOR FOR SELECT DISTINCT domainId FROM disposition_status;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
    
    OPEN domain_cursor;
    
    fetch_loop: LOOP
        FETCH domain_cursor INTO currentDomainId;
        IF done THEN
            LEAVE fetch_loop;
        END IF;

        
        INSERT INTO disposition_status (dispositionName, type, description, status, createdAt, updatedAt, domainId, colorCode, accessType)
        VALUES 
            ('Out of Hours', 'Default', 'Calls received outside business hours when agents are unavailable, enabling automated handling or scheduled follow-ups.', 1, NOW(), NOW(), currentDomainId, '#613F2F', 0),
            ('IVR Exit', 'Default', 'When a customer leaves the IVR (Interactive Voice Response) system—either by completing a selection, or ending the call.', 1, NOW(), NOW(), currentDomainId, '#667799', 0),
            ('Missed', 'Default', 'A customer-initiated inbound call that was not answered by an agent or the contact center system within a defined timeframe.', 1, NOW(), NOW(), currentDomainId, '#FA96AD', 0),
            ('Declined', 'Default', 'When an agent disconnects or rejects the incoming call before answering it.', 1, NOW(), NOW(), currentDomainId, '#FA96AD', 0);

    END LOOP;
    
    CLOSE domain_cursor;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
