CREATE DEFINER=`dbdev`@`%` PROCEDURE `insert_knowledgeBaseData`(
	 p_domainId 			int

)
begin

	DECLARE v_mainId INT;
	DECLARE v_UserID INT;
	DECLARE v_catId  INT;
    DECLARE v_kid	 INT;
    
    SELECT UserID INTO v_UserID 
    FROM tb_User WHERE domainId = p_domainId
    AND ext = 200;
	
    SELECT kid INTO v_mainId 
    FROM tb_KnowledgeBaseDtl 
    WHERE domainId = p_domainId;
    
    IF v_mainId IS NULL
    THEN
		INSERT INTO tb_KnowledgeBaseDtl(domainId,website_UUID,createdAt,updatedAt)
		SELECT domainId,websiteId,NOW(),NOW()
		FROM websiteScraper where domainId = p_domainId LIMIT 1;
        
        SET v_mainId = last_insert_id();
    END IF;
    
    INSERT INTO tb_KnowledgeBaseCategory(fk_kid,knowledgeBaseType,CategoryName,CategoryDescription,createdBy,CreatedDate,UpdatedDate)
    SELECT v_mainId,2005001 as p_knowledgeBaseType,CategoryName,CategoryDescription,v_UserID,NOW(),NOW()
    FROM tb_ChatCategory where DomainId = p_domainId;
    
	INSERT INTO tb_KnowledgeBaseCategory(fk_kid,knowledgeBaseType,CategoryName,CategoryDescription,createdBy,CreatedDate,UpdatedDate)
    SELECT v_mainId,2005002 as p_knowledgeBaseType,CategoryName,CategoryDescription,v_UserID,NOW(),NOW()
    FROM tb_ChatCategory where DomainId = p_domainId;    
    
    SET v_catId = last_insert_id();
        
    INSERT INTO tb_KnowledgeBaseArticleDtl (fk_kid,knowledgeBaseType,categoryId,articlePath, createdBy,createdAt,updatedAt)    
    SELECT 	v_mainId,2005001 as knowledgeBaseType,kbc.CategoryId,JSON_OBJECT('articleUrl', TRIM('"' FROM KC.FilePath)), v_UserID,NOW(),NOW()    
    FROM 		websiteScraper 				WS
	LEFT JOIN 	tb_ChatArticle 				KC 	ON 	WS.web_id 				= KC.web_id 
												AND WS.domainId 			= KC.DomainId
	LEFT JOIN 	tb_ChatCategory				CC	ON 	CC.ChatCategoryId		= KC.ChatCategoryId
    left join 	tb_KnowledgeBaseCategory 	kbc	ON 	kbc.CategoryName		= CC.CategoryName collate utf8mb4_unicode_ci
												AND kbc.fk_kid 				= v_mainId
												AND kbc.knowledgeBaseType	= 2005001
	where  WS.DomainId = p_domainId 
    AND (IFNULL(WS.websiteUrl,'') <> '' OR IFNULL(KC.FilePath,'') <> '') 
    union all
    select 	v_mainId,2005002 as knowledgeBaseType,kbc.CategoryId,JSON_OBJECT('articleUrl', TRIM('"' FROM KC.FilePath)) ,v_UserID,NOW(),NOW()    
    from 		websiteScraper 				WS
	LEFT JOIN 	tb_ChatArticle 				KC 	ON 	WS.web_id 				= KC.web_id 
												AND WS.domainId 			= KC.DomainId
	LEFT JOIN 	tb_ChatCategory				CC	ON 	CC.ChatCategoryId		= KC.ChatCategoryId
    left join 	tb_KnowledgeBaseCategory 	kbc	ON 	kbc.CategoryName		= CC.CategoryName collate utf8mb4_unicode_ci
												AND kbc.fk_kid 				= v_mainId
												AND kbc.knowledgeBaseType	= 2005002
	where  WS.DomainId = p_domainId 
    AND (IFNULL(WS.websiteUrl,'') <> '' OR IFNULL(KC.FilePath,'') <> '');    
    
    INSERT INTO tb_KnowledgeBaseArticleDtl (fk_kid,knowledgeBaseType,webPageUrl,createdBy,createdAt,updatedAt)    
    SELECT 	v_mainId,2005001 AS knowledgeBaseType,websiteUrl,v_UserID,NOW(),NOW()    
    FROM websiteScraper WHERE domainId = p_domainId AND IFNULL(websiteUrl,'') <> '' LIMIT 1;
    
    INSERT INTO tb_KnowledgeBaseArticleDtl (fk_kid,knowledgeBaseType,webPageUrl,createdBy,createdAt,updatedAt)
    SELECT 	v_mainId,2005002 AS knowledgeBaseType,websiteUrl,v_UserID,NOW(),NOW()    
    FROM websiteScraper WHERE domainId = p_domainId AND IFNULL(websiteUrl,'') <> '' LIMIT 1;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
