CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `insert_update_employees`(

    IN p_empName VARCHAR(100),
    IN p_empAge INT,
    IN p_empAddress VARCHAR(100),
    IN p_empSalary INT,
    IN p_pincode VARCHAR(100)
)
BEGIN
    DECLARE v_errcode INT DEFAULT 0;
    DECLARE v_errmsg VARCHAR(100);

    IF EXISTS (
        SELECT 1 FROM employees
        WHERE empName = p_empName AND empAge = p_empAge
        LIMIT 1
    )
    THEN
        UPDATE employees
        SET	empName=p_empName,
        empAge=p_empAge,
            empAddress = p_empAddress,
            empSalary = p_empSalary,
            pincode = p_pincode
        WHERE empName = p_empName AND empAge = p_empAge;

        IF ROW_COUNT() > 0
        THEN
            SET v_errcode = 0;
            SET v_errmsg = 'Updated successfully';
        END IF;
    ELSE
        INSERT INTO employees (empName, empAge, empAddress, empSalary, pincode)
        VALUES (p_empName, p_empAge, p_empAddress, p_empSalary, p_pincode);

        IF ROW_COUNT() > 0
        THEN
            SET v_errcode = 1;
            SET v_errmsg = 'Inserted successfully';
        END IF;
    END IF;

    SELECT v_errcode AS errcode, v_errmsg AS errmsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
