CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `insert_update_employees_practice`(
    p_empId INT,  
    p_empName VARCHAR(40),  
    p_empAge INT,  
    p_empAddress VARCHAR(40),  
    p_empSalary INT  
)
BEGIN
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'failure';
    
    IF EXISTS (SELECT 1 FROM employees WHERE empId = p_empId LIMIT 1) THEN
        UPDATE employees 
        SET 
            empName = p_empName,  
            empAge = p_empAge,  
            empAddress = p_empAddress,  
            empSalary = p_empSalary  
        WHERE empId = p_empId; 
        
        IF ROW_COUNT() > 0 THEN
            SET v_errcode = 0;
            SET v_errmsg = 'Updated successfully';
        END IF;
    ELSE
        INSERT INTO employees (empId, empName, empAge, empAddress, empSalary)
        VALUES (p_empId, p_empName, p_empAge, p_empAddress, p_empSalary);
        
        SET v_errcode = 0;
        SET v_errmsg = 'Inserted successfully';
    END IF;
    
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
