CREATE DEFINER=`dbdev`@`%` PROCEDURE `Insert_videoRecordingcc_message_details`(
	p_domainId 		int, 
	p_sessionId 	varchar(250), 
	p_Message 		json
   )
Begin
   
			DECLARE v_errcode 					INT default -1;
			DECLARE v_errmsg 					VARCHAR(55) default 'Message merged failed';
			DECLARE v_rid 						BIGINT;
			DECLARE v_prev_Message 				JSON;
			DECLARE v_merged_msg 				JSON;
    
			SELECT 	rid INTO v_rid 
            FROM 	tb_videomeet_user_record_info 
            WHERE 	sessionId = p_sessionId 
            AND		domainId = p_domainId LIMIT 1;
            
			UPDATE 	tb_videomeet_user_record_info
			SET 	videoRecordingcc = p_Message
			,		updatedAt = now()
			WHERE 	rid = v_rid; 
            
            IF ROW_COUNT() > 0 
                THEN
					SET v_errcode = 0;
					SET v_errmsg = 'Message merged successfully';
			END IF;
       
       
       
		
           
   		SELECT v_errcode AS errcode, v_errmsg AS errmsg;
   End ;;
DELIMITER ;
