CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `queue_Voice_Edit_Column_Update_Insert_Details`( 
      p_Id       INT,
       p_domainId INT,
       p_ext 	 INT,
       p_editColumnNames LONGTEXT
   )
BEGIN
       DECLARE v_errcode 				INT;
       DECLARE v_errmsg 				VARCHAR(250);
	   DECLARE	v_CurDate				DATETIME;
       DECLARE  v_queue_VoiceId     	INT;
 
     SET v_CurDate = NOW();
 
 
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     SELECT Id INTO v_queue_VoiceId
     FROM CallQueueEditColumns
     WHERE domainId = p_domainId
         AND Id = p_Id
         AND ext = p_ext;
 
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     IF v_queue_VoiceId IS NULL THEN
 
         INSERT INTO CallQueueEditColumns 
         (domainId, ext, Id, editColumnNames, createdAt, updatedAt)
         VALUES 
         (p_domainId, p_ext, p_Id, p_editColumnNames, v_CurDate, v_CurDate);
 
         SET v_queue_VoiceId = LAST_INSERT_ID();
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Inserted Successfully';
     ELSE
 
         UPDATE CallQueueEditColumns
         SET editColumnNames = p_editColumnNames,
             updatedAt = v_CurDate
         WHERE Id = p_Id
             AND domainId = p_domainId
             AND ext = p_ext;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Updated Successfully';
     END IF;
 
     SELECT v_errcode AS errorcode, v_errmsg AS errormessage;
 END ;;
DELIMITER ;
