CREATE DEFINER=`dbdev`@`%` PROCEDURE `sample_test`(
	p_chatType 							VARCHAR(50)	 
	,p_HistoryId		   				BIGINT
	,p_DomainId							INT
	,p_DispositionId	    			VARCHAR(255)   
	,p_Summary			    			TEXT
	,p_IsSessionClosed	    			TINYINT
	,p_afterWorkTime					INT
	,p_dispositionUpdatedBy				BIGINT
	,p_Duration             	        BIGINT
	,p_replyChannelType					VARCHAR(50) 
	,p_responseHistoryId 				INT 
	,p_calledPersonDetails 				INT
	,p_subject							TEXT
	,p_markAsRead						INT
	,p_agentExtn 						INT
	,p_sessionId 						VARCHAR(100)
	,p_agentOccupyDetails				JSON
	,p_meetingId 						TEXT
)
SP:BEGIN
DECLARE v_chatCheck 						INT DEFAULT 0;
DECLARE v_sysmsg							VARCHAR(255) DEFAULT "Failed";
DECLARE v_syscode							INT DEFAULT -1;


	IF chatType IN ("Email", "Chat", "SMS", "Whatsapp", "Facebook", "Instagram", "VideoSession", "Call") THEN
		SET v_chatCheck = 1;
	END IF;

	IF v_chatCheck = 0 THEN
			SET v_sysmsg = "Mismatch is given chat";
            SET v_syscode = -2;
			SELECT v_syscode AS "Error Code", v_sysmsg AS "Error Message";
            leave SP;
	END IF;
    
    IF chatType IN ("SMS") THEN
			CALL up_UpdateReplayViaSMSHistoryDisposition(p_HistoryId, p_DomainId, p_DispositionId, p_Summary, 
            p_IsSessionClosed, p_afterWorkTime, p_dispositionUpdatedBy, p_Duration, p_replyChannelType, p_responseHistoryId);
    END IF;
    
     IF chatType IN ("Email") THEN
			CALL up_UpdateReplayViaEmailHistoryDisposition(p_HistoryId, p_DomainId, p_DispositionId, p_Summary, 
            p_IsSessionClosed, p_afterWorkTime, p_dispositionUpdatedBy, p_Duration, p_replyChannelType, p_responseHistoryId);
    END IF;
    
    IF chatType IN ("Chat") THEN
		CALL up_UpdateReplayViaChatHistoryDisposition_test(p_HistoryId, p_DomainId, p_Summary, p_DispositionId, p_afterWorkTime, p_markAsRead,
        p_agentOccupyDetails, p_dispositionUpdatedBy);
    END IF;
    
	IF chatType IN ("Whatsapp") THEN
		call up_UpdateReplayViaWhatsappHistoryDisposition_test(p_HistoryId, p_DomainId,p_DispositionId, p_Summary, p_IsSessionClosed, p_afterWorkTime,
         p_dispositionUpdatedBy, p_Duration);
        
    END IF;
    
    IF chatType IN ("Facebook") THEN
		call up_UpdateReplayViaFacebookHistoryDisposition_test(p_HistoryId, p_DomainId, p_DispositionId, p_Summary, p_IsSessionClosed, p_afterWorkTime
		, p_dispositionUpdatedBy, p_Duration);
    END IF;
    
    IF chatType IN ("Instagram") THEN
		call up_UpdateReplayViaInstagramHistoryDisposition_test(p_HistoryId, p_DomainId, p_DispositionId, p_Summary, p_IsSessionClosed, p_afterWorkTime
			,p_dispositionUpdatedBy	,p_Duration);
    END IF;
    
    IF chatType IN ("VideoSession") THEN
			call up_UpdateReplayViaVideoHistoryDisposition_test(p_DomainId, p_meetingId, p_Summary, p_DispositionId, p_afterWorkTime, 
						p_subject,p_agentExtn, p_dispositionUpdatedBy);
    END IF;
    
	IF chatType IN ("Call") THEN
			call up_UpdateReplayViaCallHistoryDisposition(p_DomainId, p_sessionId, p_DispositionId, p_Summary, p_afterWorkTime, p_dispositionUpdatedBy,
            p_Duration, p_calledPersonDetails, p_subject, p_markAsRead, p_agentExtn);
    END IF;
END ;;
DELIMITER ;
