CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_GetTicketGroupDetails`(
    p_TicketGroupId		INT
   ,p_CompanyId			INT
   ,p_ProductId			INT
   )
BEGIN
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	G.TicketGroupId
   		,	G.GroupName		
           ,	G.GroupDescription
           ,	(select count(a.TicketId) from tb_TicketDetails a where a.AssignedToGroupId= p_TicketGroupId and CompanyId = p_CompanyId) as	'TotalTickets'
           ,	(select count(b.TicketId) from tb_TicketDetails b  where b.TicketStatusId = 1014  AND b.AssignedToGroupId = p_TicketGroupId  and b.CompanyId = p_CompanyId and b.ProductId = p_ProductId ) as 'TotalCompletedTickets'
           ,	G.UpdatedDate		'LastUpdatedDate'
   	FROM	tb_TicketGroup 		G	
     
  								
   	WHERE 	G.TicketGroupId		= p_TicketGroupId
       AND		G.CompanyId		= p_CompanyId
   	AND		G.ProductId			= p_ProductId
       AND		G.IsDeleted		= 0;
       
       SELECT 	U.UserId
   		,	U.UserName
   		,	GU.IsAutoAssign
           ,	(	 SELECT 	COUNT(1)
   				 FROM 	tb_TicketDetails T
                   WHERE	T.CompanyId			= p_CompanyId
                   AND    T.ProductId			= p_ProductId
                   AND	T.AssignedToAgentId	= U.UserId	)	'UserTotalTickets'   
       FROM	tb_TicketGroup 				G	
       JOIN 	tb_TicketGroupUserMapping 	GU 	ON 	GU.TicketGroupId 	= G.TicketGroupId
   											AND GU.IsActive			= 1
   											AND	GU.IsDeleted		= 0
       JOIN 	tb_TicketUser				U	ON U.UserId			= GU.UserId
   	WHERE 	G.TicketGroupId	= p_TicketGroupId
       AND	G.CompanyId		= p_CompanyId
   	 AND	G.ProductId		= p_ProductId
       AND	G.IsDeleted		= 0	;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
