CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_GetTicketGroupList`(p_CompanyId			INT
   ,p_ProductId			INT
   )
BEGIN
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	G.TicketGroupId
   		,	G.GroupName		
           ,	G.GroupDescription
           ,	0								Tickets
           ,	(	SELECT 	COUNT(1) 
   				FROM 	tb_TicketGroupUserMapping GU
                   WHERE 	GU.TicketGroupId = G.TicketGroupId
                   AND		IsActive	= 1
   				AND		IsDeleted	= 0)	Users
   	FROM	tb_TicketGroup G	
   	WHERE 	G.CompanyId	= p_CompanyId
   	AND		G.ProductId	= p_ProductId
       AND		G.IsDeleted	= 0;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
