CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_GetTicketUserForGroup`(
   p_CompanyId			INT
   ,p_ProductId		INT
   ,p_GroupId			INT
    )
BEGIN
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    	SELECT 	U.UserId
    		,	U.UserName 		
    	FROM	tb_TicketGroupUserMapping 	GU
    	JOIN 	tb_TicketGroup				G	ON GU.TicketGroupId = G.TicketGroupId											
    	JOIN 	tb_TicketUser				U	ON U.UserId			= GU.UserId
    	WHERE 	G.TicketGroupId	= p_GroupId
   	AND		GU.IsActive	= 1
   
       AND		U.IsDeleted	= 0
       AND 	G.CompanyId	= p_CompanyId
    	AND		G.ProductId	= p_ProductId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END ;;
