CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_GetTicketUserGroupList`(p_CompanyId			INT
   ,p_ProductId			INT
   )
BEGIN
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	U.UserId
   		,	U.UserName
   		,	G.TicketGroupId
   		,	G.GroupName		
           ,	GU.IsActive
   	FROM	tb_TicketGroupUserMapping 	GU
   	JOIN 	tb_TicketGroup				G	ON GU.TicketGroupId = G.TicketGroupId											
   	JOIN 	tb_TicketUser				U	ON U.UserId			= GU.UserId
   	WHERE 	G.CompanyId	= p_CompanyId
   	AND		G.ProductId	= p_ProductId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
