CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_InsertUpdateTicketGroup`(
      p_TicketGroupId		INT
     ,p_GroupName			VARCHAR(100)
     ,p_GroupDescription	VARCHAR(250)
     ,p_IsDeleted			TINYINT	
     ,p_CompanyId			INT
     ,p_ProductId			INT
     ,p_User					JSON
     ,p_LoggedInUserId		INT		
     )
BEGIN
    	DECLARE v_errcode 			INT DEFAULT -1;
    	DECLARE v_errmsg 			VARCHAR(50) DEFAULT 'Failure';
    	DECLARE v_CurDate			DATETIME;
    	DECLARE v_TicketGroupId		INT;
    	DECLARE v_JLength			SMALLINT;
         
         SET v_CurDate = NOW();
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         SELECT TicketGroupId INTO v_TicketGroupId
         FROM 	tb_TicketGroup
         WHERE 	TicketGroupId = p_TicketGroupId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     	SET v_JLength = JSON_LENGTH(p_User, "$");
                 
     	DROP TEMPORARY TABLE IF EXISTS tt_TicketUser;
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     	CREATE TEMPORARY TABLE tt_TicketUser       
     	WITH RECURSIVE  CTE_JsonCount as
     	(	SELECT 	0 SlNo
     		UNION ALL
     		SELECT 	SlNo + 1	SlNo
     		FROM 	CTE_JsonCount
     		WHERE 	SlNo  < v_JLength - 1
     	)
     	SELECT  TRIM(BOTH '"' FROM (json_extract(p_User, concat('$[',SlNo,'].UserId')))) 		AS UserId,
     			TRIM(BOTH '"' FROM (json_extract(p_User, concat('$[',SlNo,'].UserName')))) 	AS UserName,
     			TRIM(BOTH '"' FROM (json_extract(p_User, concat('$[',SlNo,'].Email')))) 	    AS Email,
     			TRIM(BOTH '"' FROM (json_extract(p_User, concat('$[',SlNo,'].Ext')))) 		AS Ext,
     			TRIM(BOTH '"' FROM (json_extract(p_User, concat('$[',SlNo,'].IsActive')))) 	AS IsActive
     	FROM CTE_JsonCount;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         UPDATE 	tb_TicketUser	TU
         JOIN 	tt_TicketUser	T_U	ON T_U.UserId = TU.UserId
         SET 	TU.UserName		=	T_U.UserName		
                 ,TU.Email		=   T_U.Email		
                 ,TU.Ext			=   T_U.Ext			
                 ,TU.IsActive	=   T_U.IsActive	
                 ,TU.CompanyId	=   p_CompanyId	
                 ,TU.ProductId	=   p_ProductId	
                 ,TU.UpdatedBy	=   p_LoggedInUserId
                 ,TU.UpdatedDate	=   v_CurDate;    
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         INSERT INTO tb_TicketUser
         (	UserId		
             ,UserName	
             ,Email		
             ,Ext		
             ,IsActive	        
             ,CompanyId	
             ,ProductId	
             ,CreatedBy	
             ,CreatedDate
             ,UpdatedBy	
             ,UpdatedDate
         )
         SELECT 	T_U.UserId
     			,T_U.UserName
     			,T_U.Email
     			,T_U.Ext
     			,T_U.IsActive
                 ,p_CompanyId
                 ,p_ProductId
                 ,p_LoggedInUserId
     			,v_CurDate
     			,p_LoggedInUserId
     			,v_CurDate            
         FROM 	tt_TicketUser		T_U
         LEFT JOIN  tb_TicketUser	TU	ON T_U.UserId = TU.UserId
     	WHERE 	TU.UserId IS NULL;
        
         IF v_TicketGroupId IS NULL
         THEN		
     		INSERT INTO tb_TicketGroup
             (	GroupName
     			,GroupDescription
     			,IsDeleted
     			,CompanyId
     			,ProductId
     			,CreatedBy
     			,CreatedDate
     			,UpdatedBy
     			,UpdatedDate        
             )
             VALUES
             ( p_GroupName		
               ,p_GroupDescription	
               ,0
               ,p_CompanyId		
               ,p_ProductId		
               ,p_LoggedInUserId
               ,v_CurDate
               ,p_LoggedInUserId
               ,v_CurDate
             );
             
             SET v_TicketGroupId = last_insert_id();
             
             SET v_errcode = 0;
             SET v_errmsg = 'Inserted Susseccfully';
     	ELSE
     		UPDATE 	tb_TicketGroup         
             SET 	GroupName			= p_GroupName		
     			,	GroupDescription	= p_GroupDescription
     			,	IsDeleted			= p_IsDeleted
     			,	CompanyId			= p_CompanyId		
     			,	ProductId			= p_ProductId			
     			,	UpdatedBy			= p_LoggedInUserId
     			,	UpdatedDate        	= v_CurDate
     		WHERE 	TicketGroupId		= v_TicketGroupId;
             
             SET v_errcode = 0;
             SET v_errmsg = 'Updated Susseccfully';
         END IF;  
         
         INSERT INTO tb_TicketGroupUserMapping
     	(	TicketGroupId				
     		,UserId						
     		,IsActive					
     		,IsDeleted					
     		,CompanyId					
     		,ProductId					
     		,CreatedBy					
     		,CreatedDate				
     		,UpdatedBy					
     		,UpdatedDate
     	)
         SELECT 	v_TicketGroupId
     			,TU.UserId			
     			,1
                 ,0
                 ,p_CompanyId
                 ,p_ProductId
                 ,p_LoggedInUserId
     			,v_CurDate
     			,p_LoggedInUserId
     			,v_CurDate     
         FROM 	tt_TicketUser 				TU
         LEFT JOIN tb_TicketGroupUserMapping GU	ON 	TU.UserId 			= GU.UserId
     											AND	GU.TicketGroupId	= v_TicketGroupId
     	WHERE GU.UserId IS NULL;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         DROP TEMPORARY TABLE IF EXISTS tt_TicketUser;
         SELECT v_errcode	'errcode',v_errmsg  'errmsg';
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_insertUpdate_pipeDriveAccountloginDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `sp_insertUpdate_pipeDriveAccountloginDetails`(
	p_User_id		 	INT, 
	p_User_name  		VARCHAR(100),
	p_Refresh_token  	VARCHAR(255),
	p_Access_token  	TEXT, 
	p_ExpiresAt 		BIGINT
)
BEGIN	
			DECLARE v_errMsg	VARCHAR(100) DEFAULT "Failed";
            DECLARE v_errCode	INT DEFAULT -1;
        
		IF EXISTS(SELECT 1 FROM tb_pipedrive_accountloginDtl WHERE User_id = p_User_id AND User_name = p_User_name) THEN
        
				UPDATE tb_pipedrive_accountloginDtl 
					SET Refresh_token = p_Refresh_token,
						Access_token = p_Access_token,
                        ExpiresAt = p_ExpiresAt
					WHERE User_id = p_User_id AND User_name = p_User_name;
                        
				IF ROW_COUNT() > 0 THEN
					SET v_errCode = 2;
                    SET v_errMsg = "Updated Successfully...";
				END IF;
            
		ELSE
				INSERT INTO tb_pipedrive_accountloginDtl (User_id	, User_name, Refresh_token , Access_token , ExpiresAt)
				VALUES(p_User_id	, p_User_name, p_Refresh_token , p_Access_token , p_ExpiresAt);
            
				IF ROW_COUNT() > 0 THEN
					SET v_errCode = 1;
                    SET v_errMsg = "Inserted Successfully...";
				END IF;
                
		END IF;
        
        SELECT v_errCode AS errCode , v_errMsg as errMsg;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
