CREATE DEFINER=`dbdev`@`%` PROCEDURE `sp_insert_update_ticket_status_brief_dtl`(
	p_ticketId		INT,
	p_status		VARCHAR(50),
    p_Agent			TEXT,
    p_Admin			TEXT,
    p_resolver		TEXT
)
BEGIN
			DECLARE v_errMsg  VARCHAR(50) DEFAULT 'failed';
            DECLARE v_errCode  SMALLINT DEFAULT -1;

			IF NOT EXISTS(SELECT 1 from tb_status_brief_dtl WHERE ticketId = p_ticketId) THEN 
				
                INSERT INTO tb_status_brief_dtl(ticketId, `status`, Agent, `Admin`, resolver) VALUES(
						p_ticketId, p_status, p_Agent, p_Admin, p_resolver);
                        
                        If ROW_COUNT() > 0 THEN 
							SET v_errMsg		= "Inserted";
							SET v_errCode		= 0;
						END IF;
            
			ELSE
				UPDATE 	tb_status_brief_dtl
								SET `status` = p_status,
									Agent = p_Agent,
                                    `Admin` = p_Admin,
                                    resolver = p_resolver
						WHERE ticketId = p_ticketId;
                        
                        IF ROW_COUNT() > 0 THEN 
							SET v_errMsg		= "Updated";
							SET v_errCode		= 1;
						END IF;
                        
				END if;
                    
                    SELECT v_errCode AS errCode, v_errMsg AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
