CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_TicketAddUserToGroup`(p_TicketGroupId		INT
  ,p_UserId				INT
  ,p_CompanyId			INT
  ,p_ProductId			INT
  ,p_LoggedInUserId		INT	
  )
BEGIN
  	DECLARE v_errcode 					INT DEFAULT -1;
  	DECLARE v_errmsg 					VARCHAR(50) DEFAULT 'User not added ';
  	DECLARE v_CurDate					DATETIME;
      DECLARE v_TicketGroupUserMappingId	INT;
      
  	SET v_CurDate = NOW();	
      
  	SELECT 	TicketGroupUserMappingId INTO v_TicketGroupUserMappingId 
      FROM 	tb_TicketGroupUserMapping GU
      WHERE 	GU.TicketGroupId	= p_TicketGroupId
      AND		GU.UserId			= p_UserId;
      
  	IF v_TicketGroupUserMappingId IS NULL
      THEN
  		INSERT INTO tb_TicketGroupUserMapping
  		(	TicketGroupId
  			,UserId
  			,IsActive
  			,IsDeleted
  			,IsAutoAssign
  			,CompanyId
  			,ProductId
  			,CreatedBy
  			,CreatedDate
  			,UpdatedBy
  			,UpdatedDate		
  		)
          VALUES
          (	p_TicketGroupId
  			,p_UserId
              ,1
              ,0
              ,0
              ,p_CompanyId
              ,p_ProductId
              ,p_LoggedInUserId
              ,v_CurDate
              ,p_LoggedInUserId
              ,v_CurDate
          );
          
          SET v_TicketGroupUserMappingId = last_insert_id();
          SET v_errcode = 0;
          SET v_errmsg = 'Inserted Susseccfully';
  	ELSE  
  		UPDATE 	tb_TicketGroupUserMapping
  		SET 	IsActive 		= 1
  			,	IsDeleted		= 0
              ,	IsAutoAssign	= 0
              ,	UpdatedBy		= p_LoggedInUserId
              ,	UpdatedDate		= v_CurDate
          WHERE 	TicketGroupUserMappingId = v_TicketGroupUserMappingId;
          
          IF row_count() > 0
          THEN
  			SET v_TicketGroupUserMappingId = last_insert_id();
  			SET v_errcode = 0;
  			SET v_errmsg = 'Updated Susseccfully';        
          END IF;    
      END IF; 
      
      SELECT v_errcode 'errcode',v_errmsg  'errmsg';
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_TicketDeleteGroup` */;
