CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_TicketDeleteGroup`(p_TicketGroupId		INT
  ,p_CompanyId			INT
  ,p_ProductId			INT
  ,p_LoggedInUserId		BIGINT	
  )
BEGIN
  	DECLARE v_errcode 					INT DEFAULT -1;
  	DECLARE v_errmsg 					VARCHAR(50) DEFAULT 'Group not deleted';
  	DECLARE v_CurDate					DATETIME;    
      
  	SET v_CurDate = NOW();	
  
  	UPDATE 	tb_TicketGroup
  	SET 	IsDeleted		= 1		
  		,	UpdatedBy		= p_LoggedInUserId
  		,	UpdatedDate		= v_CurDate
  	WHERE 	TicketGroupId 	= p_TicketGroupId;
  
  	IF row_count() > 0
  	THEN		
  		SET v_errcode = 0;
  		SET v_errmsg = 'Deleted Susseccfully';        
  	END IF;    
      
      SELECT v_errcode 'errcode',v_errmsg 'errmsg';
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_TicketUpdateUserGroup` */;
