/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `sp_TicketUpdateUserGroup`(p_TicketGroupId		INT
   ,p_UserId				INT
   ,p_IsDeleted			tinyint
   ,p_IsAutoAssign			tinyint
   ,p_CompanyId			INT
   ,p_ProductId			INT
   ,p_LoggedInUserId		INT	
   )
BEGIN
   	DECLARE v_errcode 					INT DEFAULT -1;
   	DECLARE v_errmsg 					VARCHAR(50) DEFAULT 'No Update';
   	DECLARE v_CurDate					DATETIME;
       DECLARE v_TicketGroupUserMappingId	INT;
   
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	TicketGroupUserMappingId INTO v_TicketGroupUserMappingId 
       FROM 	tb_TicketGroupUserMapping GU
       WHERE 	GU.TicketGroupId	= p_TicketGroupId
       AND		GU.UserId			= p_UserId;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   	IF v_TicketGroupUserMappingId IS NOT NULL
       THEN    
   		UPDATE 	tb_TicketGroupUserMapping
   		SET 	IsDeleted		= IFNULL(p_IsDeleted,IsDeleted)
               ,	IsAutoAssign	= IFNULL(p_IsAutoAssign,IsAutoAssign)
               ,	UpdatedBy		= p_LoggedInUserId
               ,	UpdatedDate		= v_CurDate
           WHERE 	TicketGroupUserMappingId = v_TicketGroupUserMappingId; 
           
           IF row_count() > 0
           THEN			
   			SET v_errcode = 0;
               
               IF p_IsDeleted = 1 
               THEN
   				SET v_errmsg = 'Deleted Susseccfully';        
              
               ELSE             
   				SET v_errmsg = 'Updated Susseccfully';        
               END IF;    
           END IF;    
       END IF;	
   
       SELECT v_errcode 'errcode',v_errmsg  'errmsg';
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SyncContacts` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
