/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `SyncContacts`(
    p_domainId INT
)
BEGIN

    DECLARE done INT DEFAULT FALSE;
    DECLARE v_firstName VARCHAR(255);
    DECLARE v_lastName VARCHAR(255);
    DECLARE v_phone VARCHAR(20);

    DECLARE cur CURSOR FOR
	SELECT j_FirstName, j_LastName, j_PhoneNumber FROM tt_importContactFile;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_firstName, v_lastName, v_phone;
        IF done THEN
            LEAVE read_loop;
        END IF;

        IF EXISTS (SELECT 1 FROM customer_contact WHERE primaryPhoneNumber = v_phone) THEN
            UPDATE customer_contact
            SET firstName = IFNULL(v_firstName,firstName)
            , 	lastName = IFNULL(v_lastName,lastName)
            ,	updatedAt = now()
            WHERE primaryPhoneNumber = v_phone;
        ELSE
            INSERT INTO customer_contact (firstName, lastName, primaryPhoneNumber,domainId,createdAt,updatedAt)
            VALUES (v_firstName, v_lastName, v_phone,p_domainId,now(),now());
        END IF;

    END LOOP;

    CLOSE cur;
    
    
END ;;
DELIMITER ;
