CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `test_Dymanic`(
p_domainId	BIGINT
,p_columns	VARCHAR(1000)
,p_search	VARCHAR(150)   
)
BEGIN	
	DECLARE v_search	VARCHAR(150);    
    DECLARE v_columns	VARCHAR(1000);
    
    SET v_search 	= CONCAT('%',IFNULL(p_search,''),'%');
    SET v_columns	= REPLACE(p_columns,",",CONCAT(" LIKE '",v_search,"' OR "));    
    SET v_columns	= CONCAT(' AND (',v_columns,CONCAT(" LIKE '",v_search,"') "));
	
    DROP TEMPORARY TABLE IF EXISTS TT_CC;
    CREATE TEMPORARY TABLE TT_CC(coid  INT, firstName	VARCHAR(150),lastName	VARCHAR(150),primaryPhoneNumber 	VARCHAR(150));
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
    SET @Q = CONCAT("INSERT INTO TT_CC(coid, firstName, lastName, primaryPhoneNumber) SELECT coid, firstName, lastName, primaryPhoneNumber FROM customer_contact WHERE domainId = ",p_domainId,v_columns,' LIMIT 10;');    
        
	SELECT  @Q;
    
	PREPARE Q FROM @Q;
	EXECUTE Q;
	DEALLOCATE PREPARE Q;
    
    SELECT * FROM TT_CC;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
