/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `test_trend_chat`(
p_sessionStartTime BIGINT
,p_sessionEndTime BIGINT
,p_domainId INT
)
begin

	DECLARE v_StartTmpstmp TIME;
    DECLARE v_EndTmpstmp TIME;
    
	select DATE_FORMAT(FROM_UNIXTIME(p_sessionStartTime/1000), "%h:%i") as time_range into v_StartTmpstmp limit 1;
	select DATE_FORMAT(FROM_UNIXTIME(p_sessionEndTime/1000), "%h:%i") as time_range into v_EndTmpstmp limit 1;

	select cast(sessionStartTime as date) as time_range,count(*) as no_of_appointment 
	FROM 	tb_ChatHistory			H
	JOIN 	tb_ChatDurationHistory	DH	ON DH.ChatHistoryId = H.ChatHistoryId
	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
	AND 	H.domainId			= p_domainId
	AND 	DH.IsBot			= 1
    GROUP BY cast(sessionStartTime as date)
	ORDER BY cast(sessionStartTime as date) ASC;

end ;;
DELIMITER ;
