CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `updateAgentStatus`(
  p_domainId 			INT,
  p_ext 					INT,
  p_status 				VARCHAR(100),
  p_currentSession  		VARCHAR(100)
  )
BEGIN
   DECLARE v_CurDate 	DATETIME;
   DECLARE v_errcode 	INT          DEFAULT -1;
   DECLARE v_errmsg  	VARCHAR(100) DEFAULT 'No Update';
   DECLARE v_statusId	INT;
   
   set v_CurDate = now();
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	aid INTO v_statusId
     FROM 	agent_status
     WHERE 	statusName = p_status;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
      UPDATE tb_User
      SET  currentSession 			= IFNULL(p_currentSession,currentSession)
 		, StatusID					= IFNULL(v_statusId,StatusID)
 		, updatedAt 				= v_CurDate
      WHERE ext 						= p_ext
      and   domainId					= p_domainId;
      
      IF ROW_COUNT() > 0
      THEN
 		 SET v_errcode = 0;
          SET v_errmsg = 'Updated Successfully';
      END IF;
      
      SELECT v_errcode errcode,  v_errmsg errmsg; 
  END ;;
DELIMITER ;
