CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `updateAgentStatusValuesNew`(
    p_emailId						VARCHAR(255),
    p_domainId						INT,
    p_isVoice						TINYINT,
    p_isVoiceCallTransfer			TINYINT,
    p_isChat						TINYINT,
    p_isChatTransfer				TINYINT,
    p_isEmail						TINYINT,
    p_isEmailTransfer				TINYINT,
    p_statusName					VARCHAR(100)
    )
begin
    
    DECLARE v_CurDate DATETIME;
    DECLARE v_errcode INT          DEFAULT -1;
    DECLARE v_errmsg  VARCHAR(100) DEFAULT 'No Update';
    DECLARE v_aid	  INT;
    
    set v_CurDate = now();
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    select aid into v_aid
    from   agent_status
    where  statusName COLLATE utf8mb4_unicode_ci = p_statusName
    and    domainId	  = p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    update	 tb_User
    set 		isChat						=  IFNULL(p_isChat,isChat),
             isChatTransfer				=  IFNULL(p_isChatTransfer,isChatTransfer),
             isEmail						=  IFNULL(p_isEmail,isEmail),
             isEmailTransfer				=  IFNULL(p_isEmailTransfer,isEmailTransfer),
             updatedAt					=  v_CurDate,
             StatusID		      			=  IFNULL(v_aid,StatusID)
  		 
    		 
  		 
    where    emailId	COLLATE utf8mb4_unicode_ci	=  p_emailId
    and 	   domainId 					=  p_domainId;
    
    IF ROW_COUNT() > 0
    THEN
    	SET v_errcode = 0;
    	SET v_errmsg = 'Updated Successfully';
    END IF;
         
    SELECT v_errcode errcode,  v_errmsg errmsg; 
    
    end ;;
