CREATE DEFINER=`dbdev`@`%` PROCEDURE `update_and_insert_message_all_channel_bot`(	
 	p_HistoryId int , 
 	p_channelType varchar(255), 
     p_domainId int, 
     p_message JSON, 
     p_customerNumber bigint,
     p_isReminder tinyint
 )
BEGIN
 DECLARE 	v_errcode 		int DEFAULT -1;
 DECLARE 	v_errmsg 		varchar(255) DEFAULT "Failed to Insert or Update";
 DECLARE 	search_code 	int DEFAULT 0;
 
 SELECT 1 INTO search_code FROM tb_Channel_message_flow_break_bot 
 WHERE HistoryId = p_HistoryId and channelType = p_channelType and domainId = p_domainId;
 
 IF search_code = 1 AND p_channelType IN ('Whatsapp', 'Instagram', 'Facebook') THEN
 		UPDATE tb_Channel_message_flow_break_bot 
         SET message = CASE WHEN p_message IS NOT NULL THEN JSON_ARRAY_APPEND(message,'$', p_message) 
         ELSE message END
         , updatedAt = Now(), isReminder = IFNULL(p_isReminder, isReminder)
         WHERE HistoryId = p_HistoryId and channelType = p_channelType and domainId = p_domainId;
 		SET v_errcode = 1;
 		SET v_errmsg = "Updated Successfully...";
 
 ELSEIF search_code = 0 AND p_channelType IN ('Whatsapp', 'Instagram', 'Facebook') THEN
 		INSERT INTO tb_Channel_message_flow_break_bot(HistoryId, channelType, domainId, message, customerNumber, createdAt) 
 			VALUES(p_HistoryId, p_channelType, p_domainId, concat('[',p_message,']'), p_customerNumber, NOW());
 		SET v_errcode = 2;
 		SET v_errmsg = "Inserted Successfully...";
 ELSE 
 		SET v_errcode = -2;
 		SET v_errmsg = "Error Wrong Channel Name...";
 
 END IF;
 
 SELECT v_errcode, v_errmsg;
 
 END ;;
DELIMITER ;
