CREATE DEFINER=`dbdev`@`%` PROCEDURE `update_custom_notification_ringtone_CCAASMobile`( 
   
	p_domainId 					INT, 
	p_ext 						VARCHAR(255),
	P_ringtone			        INT      
										
)
BEGIN

DECLARE v_errcode  					TINYINT 			DEFAULT -1;
DECLARE v_errmsg   					VARCHAR(50) 		DEFAULT "Failed to Update";   
DECLARE v_check_t1                 	TINYINT 			DEFAULT 0;
DECLARE v_check_t2                 	TINYINT 			DEFAULT 0;
DECLARE v_check_r              		TINYINT 			DEFAULT 0;

	SELECT 1 INTO v_check_t1  FROM tb_user WHERE EXT = p_ext AND DomainId = p_domainId;
    SELECT 1 INTO v_check_t2  FROM tb_CCAASMobile_CustomNotification_dtl WHERE EXT = p_ext AND DomainId = p_domainId;
	SELECT 1 INTO v_check_r  FROM tb_CCAASMobile_NotificationRingtone_dtl WHERE ringtone_code = IFNULL(P_ringtone, 0);

IF v_check = 1 THEN 
	IF v_check_t2 = 1 AND v_check_r = 1 THEN 
		UPDATE tb_CCAASMobile_CustomNotification_dtl
		SET Notification_Sound = IFNULL(P_ringtone, Notification_Sound), UpdatedAt = now()
		WHERE EXT = p_ext AND DomainId = p_domainId;

	SET v_errcode = 1;
	SET v_errmsg = "Updated Successfully...";
    
    ELSEIF v_check_t2 = 0 AND v_check_r = 1 THEN 
		INSERT INTO tb_CCAASMobile_CustomNotification_dtl(DomainId, EXT, Notification_Sound, CreatedAt)
        VALUES(p_domainId, p_ext, IFNULL(P_ringtone, 0), now());
        
		SET v_errcode = 2;
		SET v_errmsg = "Inserted Successfully...";
        
	ELSE 
		SET v_errcode = -2;
		SET v_errmsg = "Ringtone is not avaiable...";
    
    END IF;
END IF;

	SELECT v_errcode AS "Error code", v_errmsg AS "Error Message";

END ;;
DELIMITER ;
