CREATE DEFINER=`dbdev`@`%` PROCEDURE `update_profileName_CCAASMobile`(
P_domainId 					INT,
P_firstName 				VARCHAR(100), 
P_lastName					VARCHAR(100), 
P_ext						INT
)
BEGIN

DECLARE v_errcode 				TINYINT DEFAULT 0 ;
DECLARE v_errmsg 				VARCHAR(100) DEFAULT "Failed to update...";
DECLARE v_Check        			TINYINT DEFAULT 0;

SELECT 1 INTO v_Check FROM tb_User WHERE ext = P_ext AND domainId = p_domainId; 

IF v_Check = 1 
THEN 
	IF P_firstName IS NOT NULL AND P_lastName IS NOT NULL 
    THEN 
		UPDATE tb_User SET UserName = CONCAT(P_firstName," ",P_lastName) WHERE ext = P_ext and domainId = p_domainId;
		
        SET v_errcode = 1;
        SET v_errmsg = "Updated successfully...";
        
	ELSEIF P_firstName IS NOT NULL AND P_lastName IS NULL 
    THEN 
        UPDATE tb_User SET UserName = P_firstName WHERE ext = P_ext and domainId = p_domainId;
		
        SET v_errcode = 1;
        SET v_errmsg = "Updated successfully...";

    END IF;
    
ELSE 
	SET v_errcode = -1;
	SET v_errmsg = "Data is not available...";

END IF;

SELECT v_errcode AS "Error Code", v_errmsg AS "Error Message";

END ;;
DELIMITER ;
