CREATE DEFINER=`dbdev`@`%` PROCEDURE `update_profilePicture_CCAASMobile`(
p_domainId 					INT, 
p_profileImage 				TEXT,
p_ext						INT
)
BEGIN

DECLARE v_errcode 				TINYINT DEFAULT 0 ;
DECLARE v_errmsg 				VARCHAR(255) DEFAULT "Failed to update...";
DECLARE v_check        			TINYINT DEFAULT 0;
DECLARE v_checkProfile          TINYINT DEFAULT 0;

SELECT 1 INTO v_check FROM tb_User WHERE domainId = p_domainId AND ext = p_ext;  

IF v_check = 1   
	THEN
		IF p_profileImage IS NOT NULL THEN
					UPDATE tb_User SET ProfileImage = p_profileImage WHERE domainId = p_domainId AND ext = p_ext;
                    SET v_errcode = 1;
					SET v_errmsg = "Updated Successfully...";
        END IF;
ELSE
	SET v_errcode =  -1; 
	SET v_errmsg = "Data is not available...";
    
END IF;

SELECT v_errcode AS Error_code, v_errmsg AS Error_Message;

END ;;
DELIMITER ;
