CREATE DEFINER=`dbdev`@`%` PROCEDURE `update_userIsActive`(
	p_domainId 			INT,
	p_ext				INT,
    p_isActive			INT
)
BEGIN

	DECLARE v_errMsg		VARCHAR(50) DEFAULT "Failed";
    DECLARE v_errCode		TINYINT	DEFAULT 0;

	UPDATE tb_User SET isActive =  p_isActive WHERE domainId = p_domainId AND ext = p_ext;
    
    IF row_count() > 0 THEN
		SET v_errMsg  = "Updated Successfully";
        SET v_errCode  = 1;
	END IF;
    
    SELECT v_errCode AS errCode, v_errMsg as errMsg;
END ;;
