CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_add_update_TechSupportTicketNotes`(
 p_TechSupportTicketId		INT,
 p_UserId					BIGINT,
 p_Notes						TEXT
 )
BEGIN
 	DECLARE v_curdate		DATETIME DEFAULT NOW();
     DECLARE v_errcode		TINYINT DEFAULT -1;
     DECLARE v_errmsg		VARCHAR(200) DEFAULT 'Adding notes failed';
     
 	IF EXISTS(	SELECT 	1 FROM tb_TechSupportTicketNotes 
 				WHERE 	TechSupportTicketId = p_TechSupportTicketId
                 AND 	UserId				= p_UserId)
 	THEN
 		UPDATE 	tb_TechSupportTicketNotes
         SET 	Notes			= p_Notes
         ,		updated_date	= v_curdate
         WHERE 	TechSupportTicketId = p_TechSupportTicketId
 		AND 	UserId				= p_UserId;
         
         SET v_errcode	= 2
 		,	v_errmsg	= 'Updated notes successfully';
 	ELSE
 		INSERT INTO tb_TechSupportTicketNotes(
 			TechSupportTicketId		
             ,UserId					
             ,Notes					
             ,created_date			
             ,updated_date			
         )
         VALUES(
 			p_TechSupportTicketId	
             ,p_UserId				
             ,p_Notes					
             ,v_curdate
             ,v_curdate		
         );
         
         SET v_errcode	= 1
 		,	v_errmsg	= 'Added notes successfully';
     END IF;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
