CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_add_update_tech_support_csat`(
 p_TechSupportTicketId	INT	
 ,p_customerCompanyId	INT
 ,p_csat					TINYINT
 ,p_feedback				TEXT
 ,p_ratingScale			INT
 )
BEGIN
 	DECLARE v_errmsg		VARCHAR(2000);
     DECLARE v_errcode		TINYINT DEFAULT -1;
     DECLARE v_now			DATETIME DEFAULT NOW();
     
 	DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
 	BEGIN
 		GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
 		SET v_errmsg = CONCAT(@st, ' : ', @p2); 		
 		SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 		ROLLBACK;
 	END; 	
 	
 	START TRANSACTION;	
     IF EXISTS (	SELECT 	1 
 				FROM 	tb_techticket_csat
                 WHERE 	TechSupportTicketId = p_TechSupportTicketId)
     THEN
 		UPDATE 	tb_techticket_csat
         SET 	csat		= IFNULL(p_csat,csat)
 			,	feedback	= IFNULL(p_feedback,feedback)
             ,	ratingScale = IFNULL(p_ratingScale, ratingScale)
             ,	udpateddate	= v_now
         WHERE 	TechSupportTicketId = p_TechSupportTicketId;
 		
 		SET v_errcode 	= 2
 		,	v_errmsg	= 'Updated csat successfully';	
 	ELSE
 		INSERT INTO tb_techticket_csat(
 			TechSupportTicketId	
             ,csat			
             ,customerCompanyId
             ,ratingScale
 			,feedback
             ,createddate
             ,udpateddate
         )
         VALUES(
 			p_TechSupportTicketId	
             ,p_csat	
             ,p_customerCompanyId
             ,p_ratingScale
             ,p_feedback				
 			,v_now
             ,v_now
         ); 
         
         SET v_errcode 	= 1
 		,	v_errmsg	= 'Added csat successfully';	
     END IF;
     COMMIT;
     
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
