CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_add_update_tech_support_ticket`(
     p_TechSupportTicketId 		bigint ,
     p_ServiceProviderCompanyId 	int,   
     p_CustomerCompanyId 			int,   
     p_TicketSubject 				varchar(500),
     p_TicketSourceId 			int,
     p_TicketStatusId 			int,
     p_TicketTypeId 				int,
     p_PriorityId 				int,
     p_RequestorId 				int,
     p_AssignedToTeamId 			int,
     p_AssignedToGroupId 			int,
     p_AssignedTo 				int,
     p_AssignedBy 				int,   
     p_TicketChatId 				BIGINT,
     p_TagId 						text,
     p_ResponseDueDate 			datetime,
     p_ResponsedDate 				datetime,
     p_ResolutionDueDate 			datetime,
     p_ResolvedDate 				datetime,
     p_SLAconditionId 			int,   
     p_IsDeleted 					tinyint,
     p_TicketAssignee 			tinyint,
     p_TicketLayout 				int,
     p_TicketDescription 			text ,
     p_TicketTagIdName 			text,
     p_TicketMode 				int,
     p_RequesterName 				text,
     p_TicketAssociateCustContact int,
     p_MergedWith 				bigint,
     p_isMergedTo 				int,
     p_loggedInUserId 			bigint,
     p_RootCause					TEXT,
     p_Resolution					TEXT,
     p_Summary					TEXT,
     p_ChannelTypeId				INT,
     p_FilesUpload				JSON,
     p_sessionId					VARCHAR(250),
     p_ConfidenceScore 			TINYINT,
     p_ResolveInformDate			DATETIME,
     
     p_sendToCust				INT					
  )
SP : BEGIN
  	DECLARE v_cur_date				DATETIME DEFAULT NOW();
      DECLARE v_TechSupportTicketId 	BIGINT;
      DECLARE v_errcode				TINYINT;
      DECLARE v_errmsg				VARCHAR(200);
  	DECLARE v_TicketStatusId_exists	INT;
      DECLARE v_IsReopen				TINYINT;
      DECLARE v_TicketChatId			BIGINT;
      DECLARE v_ClosedDate			datetime;
      DECLARE v_AssignedTo_Prev		INT;
      DECLARE v_AssignedBy_Prev		INT;
      
  	DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
  	BEGIN
  		GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
  		SET v_errmsg = CONCAT(@st, ' : ', @p2); 		
  		SELECT p_TechSupportTicketId AS TechSupportTicketId,-1 AS errcode, v_errmsg AS errmsg;
  		ROLLBACK;
  	END;         
  
  	SET v_TicketChatId = p_TicketChatId;
      IF p_TicketChatId IS NULL AND p_sessionId IS NOT NULL
      THEN
  		IF p_ChannelTypeId = 2003001 
          THEN
  			SELECT 	CallHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_CallHistory
              WHERE 	sessionId	= p_sessionId;
  		ELSEIF p_ChannelTypeId = 2003002 
          THEN
  			SELECT 	ChatHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_ChatHistory
              WHERE 	sessionId	= p_sessionId;        
  		ELSEIF p_ChannelTypeId = 2003003 
          THEN
  			SELECT 	EmailHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_EmailHistory
              WHERE 	sessionId	= p_sessionId;                    
  		ELSEIF p_ChannelTypeId = 2003004	
          THEN
  			SELECT 	SMSHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_SMSHistory
              WHERE 	sessionId	= p_sessionId;   
  		ELSEIF p_ChannelTypeId = 2003005	
          THEN
  			SELECT 	WhatsappHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_WhatsappHistory
              WHERE 	sessionId	= p_sessionId; 
  		ELSEIF p_ChannelTypeId = 2003006	
          THEN
  			SELECT 	FacebookHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_FacebookHistory
              WHERE 	sessionId	= p_sessionId; 
  		ELSEIF p_ChannelTypeId = 2003007	
          THEN
  			SELECT 	InstagramHistoryId
  			INTO 	v_TicketChatId
  			FROM 	tb_InstagramHistory
              WHERE 	sessionId	= p_sessionId;             
          ELSEIF p_ChannelTypeId = 2003009	
          THEN
  			SELECT 	TicketChatId
              INTO 	v_TicketChatId
              FROM 	tb_TicketChat
              WHERE 	SessionId = p_sessionId;
  		END IF;
      END IF; 
      
  	START TRANSACTION;	
      SET v_TechSupportTicketId = p_TechSupportTicketId;
  	
  	IF p_TechSupportTicketId IS NULL 
      THEN
  		INSERT INTO tb_TechSupportTicket(
  			ServiceProviderCompanyId
  			,CustomerCompanyId
  			,TicketSubject
  			,TicketSourceId
  			,TicketStatusId
  			,TicketTypeId
  			,PriorityId
  			,RequestorId
  			,AssignedToTeamId
  			,AssignedToGroupId
  			,AssignedTo
              ,ConfidenceScore
  			,AssignedBy
  			,TicketChatId
              ,SessionId
  			,TagId
              ,ChannelTypeId
  			,ResponseDueDate
  			,ResponsedDate
  			,ResolutionDueDate
  			,ResolvedDate
  			,SLAconditionId
  			,IsDeleted
  			,TicketAssignee
  			,TicketLayout
  			,TicketDescription
              ,RootCause	
              ,Resolution	
              ,Summary	
  			,TicketTagIdName
  			,TicketMode
  			,RequesterName
  			,TicketAssociateCustContact
  			,MergedWith
  			,isMergedTo
              ,FilesUpload
  			,CreatedBy
  			,CreatedDate
  			,UpdatedBy
  			,UpdatedDate
             ,sendToCust								
          )
  		VALUES(
  			p_ServiceProviderCompanyId
  			,p_CustomerCompanyId
  			,p_TicketSubject
  			,p_TicketSourceId
  			,p_TicketStatusId
  			,p_TicketTypeId
  			,p_PriorityId
  			,p_RequestorId
  			,p_AssignedToTeamId
  			,p_AssignedToGroupId
  			,p_AssignedTo
              ,p_ConfidenceScore
  			,p_AssignedBy
  			,v_TicketChatId
              ,p_sessionId
  			,p_TagId
              ,p_ChannelTypeId
  			,p_ResponseDueDate
  			,p_ResponsedDate
  			,p_ResolutionDueDate
  			,p_ResolvedDate
  			,p_SLAconditionId
  			,p_IsDeleted
  			,p_TicketAssignee
  			,p_TicketLayout
  			,p_TicketDescription
              ,p_RootCause	
              ,p_Resolution	
              ,p_Summary	
  			,p_TicketTagIdName
  			,p_TicketMode
  			,p_RequesterName
  			,p_TicketAssociateCustContact
  			,p_MergedWith
  			,p_isMergedTo
              ,p_FilesUpload
  			,p_loggedInUserId
  			,v_cur_date
  			,p_loggedInUserId
  			,v_cur_date
             ,p_sendToCust  
          );
          
          SET v_TechSupportTicketId = LAST_INSERT_ID();
          SET v_errcode 	= 1,
              v_errmsg	= 'Added tech support ticket successfully';	  
  		
          
          CALL up_techticket_add_notification(v_TechSupportTicketId,1,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
          
          IF @errcode < 0
          THEN
  			SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
              ROLLBACK;
  			LEAVE SP;
          END IF;
          
          
          CALL up_techticket_add_email_notification(1,v_TechSupportTicketId,p_CustomerCompanyId,p_ServiceProviderCompanyId,@errcode,@errmsg); 
          
          IF @errcode < 0
          THEN
  			SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
              ROLLBACK;
  			LEAVE SP;
          END IF;        
          
          IF IFNULL(p_AssignedTo,0) <> 0
          THEN
  			
  			CALL up_techticket_add_notification(v_TechSupportTicketId,2,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
              
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;
              
  			
  			CALL up_techticket_add_email_notification(2,v_TechSupportTicketId,p_CustomerCompanyId,p_ServiceProviderCompanyId,@errcode,@errmsg); 
  			
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;  
  		ELSE 
  			
  			CALL up_techticket_add_notification(v_TechSupportTicketId,5,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
              
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;
              
  			
  			CALL up_techticket_add_email_notification(10,v_TechSupportTicketId,p_CustomerCompanyId,p_ServiceProviderCompanyId,@errcode,@errmsg); 
  			
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;  			
          END IF; 
  	ELSE 
  		
  		SELECT 	TicketStatusId, AssignedTo, AssignedBy
          INTO 	v_TicketStatusId_exists, v_AssignedTo_Prev, v_AssignedBy_Prev
  		FROM 	tb_TechSupportTicket
  		WHERE 	TechSupportTicketId	= v_TechSupportTicketId;
          
  		IF EXISTS (	SELECT 	1 FROM tb_TicketStatus	
  					WHERE 	CompanyId 	= p_ServiceProviderCompanyId
  					AND 	StatusId	= p_TicketStatusId
  					AND 	StatusName	= 'Open')		
  		THEN
  			IF EXISTS (	SELECT 	1 FROM tb_TicketStatus	
  						WHERE 	CompanyId 	= p_ServiceProviderCompanyId
  						AND 	StatusId	= v_TicketStatusId_exists
  						AND 	StatusName	IN ('Resolved','Closed'))
  			THEN
  				
  				CALL up_techticket_add_notification(v_TechSupportTicketId,4,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
                  
                  SET v_IsReopen = 1;
  				
  				IF @errcode < 0
  				THEN
  					SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  					ROLLBACK;
  					LEAVE SP;
  				END IF; 
                  
                  
  				CALL up_techticket_add_email_notification(6,v_TechSupportTicketId,p_CustomerCompanyId,p_ServiceProviderCompanyId,@errcode,@errmsg); 
  				
  				IF @errcode < 0
  				THEN
  					SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  					ROLLBACK;
  					LEAVE SP;
  				END IF; 
  			END IF; 
  		END IF; 
          
  		
  		IF EXISTS (	SELECT 	1 FROM tb_TicketStatus	
  					WHERE 	CompanyId 	= p_ServiceProviderCompanyId
  					AND 	StatusId	= p_TicketStatusId
  					AND 	StatusName	= 'Resolved')		
  		THEN            
  			
  			CALL up_techticket_add_notification(v_TechSupportTicketId,3,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
  			
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;  
  
  			
  			CALL up_techticket_add_email_notification(5,v_TechSupportTicketId,p_CustomerCompanyId,p_ServiceProviderCompanyId,@errcode,@errmsg); 
  			
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;             
  		END IF; 
  
  		
  		IF EXISTS (	SELECT 	1 FROM tb_TicketStatus	
  					WHERE 	CompanyId 	= p_ServiceProviderCompanyId
  					AND 	StatusId	= p_TicketStatusId
  					AND 	StatusName	= 'Closed')		
  		THEN      
  			IF p_ServiceProviderCompanyId <> v_TicketStatusId_exists
              THEN
  				SET v_ClosedDate = NOW();
  			END IF;     
              
              
  			CALL up_techticket_add_notification(v_TechSupportTicketId,6,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
  			
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;  
  		END IF; 
      
  		UPDATE  tb_TechSupportTicket
          SET 	TicketSubject		= IFNULL(p_TicketSubject,TicketSubject)
  			,	TicketDescription	= IFNULL(p_TicketDescription,TicketDescription)
              ,	TicketStatusId		= IFNULL(p_TicketStatusId,TicketStatusId)
              ,	ClosedDate			= IFNULL(v_ClosedDate,ClosedDate)
              ,	`IsReopen`			= IFNULL(v_IsReopen,`IsReopen`)
              ,	AssignedTo			= IFNULL(p_AssignedTo,AssignedTo)
              ,	ConfidenceScore		= IFNULL(p_ConfidenceScore,ConfidenceScore)
              ,	AssignedTo_Prev		= CASE WHEN v_AssignedTo_Prev IS NOT NULL AND p_AssignedTo IS NOT NULL AND v_AssignedTo_Prev <> p_AssignedTo THEN v_AssignedTo_Prev ELSE AssignedTo_Prev END 
  			,	AssignedBy			= IFNULL(p_AssignedBy,AssignedBy)
              ,	ResponsedDate		= IFNULL(p_ResponsedDate,ResponsedDate)
  			,	ResolvedDate		= IFNULL(p_ResolvedDate,ResolvedDate)            
              ,	ResolveInformDate	= IFNULL(p_ResolveInformDate,ResolveInformDate)
              ,	RootCause			= IFNULL(p_RootCause,RootCause)	
              ,   Resolution			= IFNULL(p_Resolution,Resolution)	
              ,   Summary				= IFNULL(p_Summary,Summary)	
              ,	FilesUpload			= IFNULL(p_FilesUpload,FilesUpload)
              ,	SessionId			= IFNULL(p_sessionId,SessionId)
              ,	UpdatedBy			= p_loggedInUserId
  			,	UpdatedDate			= v_cur_date
          WHERE 	TechSupportTicketId	= v_TechSupportTicketId;
          
          IF IFNULL(v_AssignedTo_Prev,0) <> p_AssignedTo AND IFNULL(p_AssignedTo,0) <> 0
          THEN
  			
  			CALL up_techticket_add_notification(v_TechSupportTicketId,2,p_CustomerCompanyId,p_ServiceProviderCompanyId,NULL,@errcode,@errmsg);
              
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;
              
  			
  			CALL up_techticket_add_email_notification(2,v_TechSupportTicketId,p_CustomerCompanyId,p_ServiceProviderCompanyId,@errcode,@errmsg); 
  			
  			IF @errcode < 0
  			THEN
  				SELECT v_TechSupportTicketId AS TechSupportTicketId, @errcode AS errcode, @errmsg AS errmsg;
  				ROLLBACK;
  				LEAVE SP;
  			END IF;  
          END IF; 
          
          SET v_errcode 	= 2,
              v_errmsg	= 'updated tech support ticket successfully';	   
      END IF; 
      COMMIT;
      
      SELECT v_TechSupportTicketId AS TechSupportTicketId, v_errcode AS errcode, v_errmsg AS errmsg;        
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Agent_Facebook_Inbound_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Agent_Facebook_Inbound_analysis_metrics_filter`(
         p_startTmpstmp 	BIGINT,
         p_endTmpstmp 	BIGINT,
         p_domainId 		INT,    	
         p_agentId		TEXT,		
         p_offset 		INT,
         p_Limit 		INT	)
sp_return:BEGIN
    			DECLARE v_offset 								INT;	  	
    			DECLARE v_CurrentStartTmpstmp 					BIGINT;
    			DECLARE v_CurrentEndTmpstmp 					BIGINT;
    			DECLARE v_PrevStartTmpstmp 						BIGINT;
    			DECLARE v_PrevEndTmpstmp 						BIGINT; 
    			DECLARE v_TmpstmpInterval						BIGINT;	
       		
        		DECLARE v_CurTotalCount 					INT;
        		DECLARE v_PrevTotalCount 					INT;
        		DECLARE	v_DiffTotalPercent 					INT;
    			
    			DECLARE v_PrevRespondedCount			    INT;	
    			DECLARE v_CurrentRespondedCount			    INT;	        
    			DECLARE v_DiffRespondedPercent			    INT;
    			
        		DECLARE v_PrevAbandonedCount				INT;
        		DECLARE v_CurrentAbandonedCount				INT;
        		DECLARE v_DiffAbandonedPercent				INT;
    			
        		DECLARE v_CurrentMissedCount				INT;
        		DECLARE v_CurrentTransferredCount			INT;
        		DECLARE v_TotalChatDuration					BIGINT;
    			
    
    			DECLARE v_CurrentMaximumChatdurationCount	INT;
    			DECLARE v_CurrentAverageChatdurationCount	INT;
 			DECLARE v_TotalTalktime             		BIGINT;
    			DECLARE v_TotalAfterCallWorkTime    		INT;
    			DECLARE v_CurrentCallHoldTime       		INT;
    			DECLARE v_CurrentAvailableTime      		INT;
    			DECLARE v_CurrentCustomerFacebookCount		INT;
    			DECLARE v_CurrentAgentFacebookCount			INT;           
    			DECLARE v_SentimentalScore          		INT;
    			DECLARE v_CurrentFirstCallResolution        INT;
         	
       	SET v_offset =  p_Limit * p_offset; 
         
     	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
     	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
         	
       	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       
       	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
       	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
         		
      	 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                   	
                         
                           		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                       		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                       		(    DispositionId 			INT
                       			,DispositionStatus 		VARCHAR(100)
                       			,DispositionCategory	TINYINT
                       		); 
                               
                       		INSERT INTO temp_AvailableDisposition 
                       		SELECT 	did 			DispositionId
                       			,	dispositionName	DispositionStatus
                       			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                       				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                       				WHEN dispositionName = 'Discarded'     			   THEN 4
    								    WHEN dispositionName = 'Resolved'      			  THEN 5
                                     WHEN dispositionName = 'Caller Disconnected'      THEN 6
                       				END 			DispositionCategory
                       		FROM 	disposition_status   
                       		WHERE 	domainId	= p_domainId;
  
                        	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                        	CREATE TEMPORARY TABLE temp_AllagentId
                        	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
  
  
             SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    			DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
    			CREATE TEMPORARY TABLE temp_FacebookHistory AS		           
    		    SELECT 	CH.sessionStartTime		
      				,	CH.FacebookHistoryId        
      				,	CH.AgentId
      				,	CH.Istransferred
      				,	CH.dispositionId
      			    ,   CH.IsInBound
      				,	(CH.sessionEndTime - CH.sessionStartTime)	                         AS FacebookChatDuration
      				,   CASE WHEN  (FROM_UNIXTIME(CH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 1 ELSE 0 END AS  MissedChat
      				,	CH.customerFacebookId
                      ,   CH.agentFacebookId
      				,	CH.afterFacebookWorkTime
      			
      				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                AS discarded
      				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                AS firstChatResolution 
 					, CASE WHEN t_D.DispositionCategory = 6 THEN 1 ElSE 0 END                AS IsAbandoned  
 					,(CH.Duration/1000 +CH.afterFacebookWorkTime)						     AS HandledTime
                     ,CASE WHEN CH.IsSessionClosed =1 Then 1 ELSE 0 END  					 AS responseChat
  					, CH.SentimentalScore
  					,CASE WHEN CH.Duration	is not null then Duration else 0 end			 AS chatduration
  					,CH.domainId 
    			FROM 		tb_FacebookHistory 		CH
    			 LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
    			LEFT JOIN tb_User					U			ON 	U.UserID				= CH.AgentId
    			 LEFT JOIN temp_agentIDs 			t_A 		ON 	U.UserID 			    = t_A.agentId   
    			WHERE 	CH.domainId 			= p_domainId 		
    		 	AND 	CH.IsInBound			= 1
    			AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
    			AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
    			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;               
                            
                            
                       DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_calc; 
    			 CREATE TEMPORARY TABLE temp_FacebookHistory_calc AS 	     
    			 SELECT 	
    				t_SH.sessionStartTime,
    				t_SH.FacebookHistoryId,
    				t_SH.AgentId,
    				t_SH.responseChat 																			AS responseTime,
    				t_SH.MissedChat,
    				t_SH.IsInBound,
    				t_SH.Istransferred,
    				t_SH.dispositionId,
    				t_SH.FacebookChatDuration,
    				SUM(t_SH.afterFacebookWorkTime)                 											AS afterwhatsappWorkTime,
    				
    				t_SH.SentimentalScore,																				
    				COUNT(t_SH.agentFacebookId)                     											AS InteractionwithAgent,
    				COUNT(DISTINCT t_SH.customerFacebookId)         											AS InteractionWithCustomer,
    				t_SH.discarded 																				AS discardedChat,
    				t_SH.IsAbandoned,																				
    				SUM(t_SH.chatduration) 																		AS totalChatduration,
    				CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END 		AS avgChatduration
                    ,t_SH.domainId 
    			FROM temp_FacebookHistory t_SH
    			GROUP BY t_SH.domainId, t_SH.sessionStartTime,t_SH.FacebookHistoryId,t_SH.AgentId,t_SH.responseChat,t_SH.MissedChat,t_SH.IsInBound,
    				t_SH.Istransferred,t_SH.dispositionId,t_SH.FacebookChatDuration,t_SH.SentimentalScore,t_SH.discarded,t_SH.IsAbandoned;    
  
  
  
    			DROP TEMPORARY TABLE IF EXISTS temp_PrevFacebookHistory; 
    			CREATE TEMPORARY TABLE temp_PrevFacebookHistory as
    			SELECT 	DISTINCT FacebookHistoryId 
    			FROM 	temp_FacebookHistory_calc
    			WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
    				
    			DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
    			CREATE TEMPORARY TABLE temp_CurChatHistory AS
    			SELECT 	DISTINCT FacebookHistoryId 
    			FROM 	temp_FacebookHistory_calc
    			WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;              
                    
                    
    		SELECT 	COUNT(FacebookHistoryId), SUM(responseTime),sum(IsAbandoned)
            INTO 	v_PrevTotalCount ,v_PrevRespondedCount,v_PrevAbandonedCount
      		FROM	temp_FacebookHistory_calc;
              
            SELECT 	COUNT(FacebookHistoryId),SUM(responseTime),sum(IsAbandoned)
            INTO 	v_curTotalCount ,v_CurrentRespondedCount,v_CurrentAbandonedCount	
      		FROM	temp_FacebookHistory_calc;   
              
              
            SELECT SUM(MissedChat), SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent)
       	    INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_CurrentCustomerFacebookCount, v_CurrentAgentFacebookCount
       	    FROM 	temp_FacebookHistory_calc;
              
      		SELECT sum(avgChatduration),sum(totalChatduration)
       	    INTO 	v_CurrentAverageChatdurationCount, v_CurrentMaximumChatdurationCount
       	    FROM 	temp_FacebookHistory_calc;              
                    
				SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
        		SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
        		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
     			
        		SET v_DiffTotalPercent 		= CASE WHEN v_PrevTotalCount = 0 then 0 else (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  end;
        		SET	v_DiffRespondedPercent	= CASE WHEN v_PrevRespondedCount = 0 then 0 else (v_CurrentRespondedCount	 - v_PrevRespondedCount) / v_PrevRespondedCount * 100 end;
        		SET	v_DiffAbandonedPercent	= CASE WHEN v_PrevAbandonedCount = 0 then 0 else (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100 end; 
    
             	 	SELECT * FROM temp_AllagentId;         
                    
    			SELECT 	IFNULL(v_CurTotalCount,0) 						AS 'TotalReceivedCount',
             			IFNULL(v_DiffTotalPercent,0) 					AS 'DiffTotalReceivedPercent',
             			IFNULL(v_CurrentRespondedCount,0) 				AS 'CurrentRespondedCount',
             			IFNULL(v_DiffRespondedPercent,0) 				AS 'DiffRespondedPercent',
             			IFNULL(v_CurrentAbandonedCount,0) 				AS 'CurrentAbandonedCount',
             			IFNULL(v_DiffAbandonedPercent,0) 				AS 'DiffAbandonedPercent';	             
                    
                    
              SELECT
               	'All Agents'																				AS agentName
    			,IFNULL(v_CurTotalCount,0)                                    									AS receivedChat
    			,IFNULL(v_CurrentRespondedCount,0)                            									AS respondedChat
                ,IFNULL(v_CurrentAbandonedCount,0)                                                            AS abandonedChat
    			  ,IFNULL(v_CurrentMissedCount,0)                               							    AS missedChat
                ,IFNULL(v_CurrentTransferredCount,0)                          								AS transferredChat
                ,IFNULL(v_TotalChatDuration,0)                   									            AS TotalChatDuration
                ,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS AverageChatDuration
                ,IFNULL(v_CurrentCustomerFacebookCount,0)								    					AS InteractionWithCustomer
                ,IFNULL(v_CurrentAgentFacebookCount,0)														AS InteractionWithAgent
                ,IFNULL(v_CurrentCustomerFacebookCount,0) + IFNULL(v_CurrentAgentFacebookCount,0)				AS totalInteraction
    
            UNION ALL
         	SELECT 	U.UserName														    						AS agentName
    			 ,	COUNT(1)														    					    AS receivedChat
    			 ,	SUM(CDH.responseTime)	    						                                        AS respondedChat
                 ,  SUM(CDH.IsAbandoned)                                                                      AS abandonedChat
                 ,	SUM(CDH.MissedChat)																		AS missedSChat        
                 ,	SUM(CDH.Istransferred)																	AS transferredChat
                 ,	sum(CDH.totalChatduration)																AS TotalChatDuration
                 ,	sum(CDH.avgChatduration) / COUNT(1)														AS AverageChatDuration
                 ,	SUM(CDH.InteractionWithCustomer)														AS InteractionWithCustomer
                 ,	SUM(CDH.InteractionwithAgent)															AS InteractionWithAgent
                 ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						AS totalInteraction
             FROM 	temp_FacebookHistory_calc 	  CDH
             JOIN 	temp_AllagentId				U	ON CDH.AgentId	= U.UserID	
       
             GROUP BY U.UserName;               
                    
        SELECT CONCAT('agentName','receivedChat', 'respondedChat', 'abandonedChat', 'missedChat', 'transferredChat', 'TotalChatDuration', 'AverageChatDuration','InteractionWithCustomer','InteractionWithCustomer','totalInteraction') AS  columnName;   
                   
    	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Agent_Inboundcall_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Agent_Inboundcall_analysis_metrics_filter`(  
 p_startTmpstmp 		BIGINT,
 p_endTmpstmp 		BIGINT,
 p_domainId 			INT,    	
 p_agentId			TEXT,		
 p_offset 			INT,
 p_Limit 			INT	
 )
BEGIN
                             
  				DECLARE v_offset 								INT;	  	
  				DECLARE v_CurrentStartTmpstmp 					BIGINT;
  				DECLARE v_CurrentEndTmpstmp 					BIGINT;
  				DECLARE v_PrevStartTmpstmp 						BIGINT;
  				DECLARE v_PrevEndTmpstmp 						BIGINT; 
  				DECLARE v_TmpstmpInterval						BIGINT;	
  				DECLARE v_DifffirstCallResolutionPercent		INT;  
  
  				DECLARE		v_averageResponseTime             	BIGINT; 
  				DECLARE		v_averageHandledTime				BIGINT;
  				DECLARE		v_MaximumHandledTime              	BIGINT; 
  				DECLARE		v_totalACWTime						BIGINT;
  				DECLARE		v_averageHoldtime                 	BIGINT; 
  				DECLARE		v_firstCallResolution             	BIGINT; 
  				DECLARE		v_CustomerSatisfaction				BIGINT; 
  				DECLARE		v_inboundCalls						BIGINT; 
  				DECLARE		v_callDuration						BIGINT; 
  				DECLARE		v_afterCallWorkTime					INT; 
  				DECLARE		v_availableTime						BIGINT; 
  				DECLARE		v_currentResponseTime				BIGINT; 
  				DECLARE		v_previousResponseTime				BIGINT; 
  				DECLARE		v_currentHandledTime				BIGINT; 
  				DECLARE		v_previousHandledTime				BIGINT; 
  				DECLARE		v_currentTotalAnsweredCalls			INT; 
  				DECLARE		v_previousTotalAnsweredCalls		INT; 
  				DECLARE       v_count							INT;
  				DECLARE       v_answerCall						INT;
  				DECLARE       v_CurTotalCount					INT;
  				DECLARE       v_PrevTotalCount					INT;
  				DECLARE       v_CurResponseTime					INT;
  				DECLARE       v_PreResponseTime					INT;
  				DECLARE       v_CurHandledTime					INT;
  				DECLARE       v_PreHandledTime					INT;
  
  				DECLARE		v_prvcount							INT;
  				DECLARE		v_prevAnswerCall					INT; 
  				DECLARE		v_prevAverageResponseTime			INT;
  				DECLARE		v_prevAverageHandledTime			INT;
  				DECLARE		v_CurrentTotalCount					INT;
  				DECLARE		v_currentAVGHandleTime				INT;
  
  				DECLARE v_unAnswered INT;
  				DECLARE v_abandoned INT;
  				DECLARE v_transferedCall INT;
  				DECLARE v_totalTalkTime INT;
  				DECLARE v_waitDuration INT;
  				DECLARE v_answeredCall INT;
  				DECLARE v_DiffTotalPercent INT;
  				DECLARE v_DiffAnsweredPercent INT;
  				DECLARE v_prevAbandoned INT;
  				DECLARE v_DiffUnAnsweredPercent INT;
  				DECLARE v_missedCallCount INT;
  				DECLARE v_DiffAbandonedPercent INT;
  				DECLARE v_prevCallCount INT;
  				DECLARE v_curCallCount INT;
  
       
    				SET v_offset =  p_Limit * p_offset; 
    
    				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
    				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
    
    				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
    
    				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
    				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                        		
       				DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
       				CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
       
       				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                  	
       				DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
       				CREATE TEMPORARY TABLE temp_FirstCallResolution
    					
                     SELECT 	SlNo AS FirstCallResolution,
   							SubQuery.AgentId,SubQuery.CallHistoryId
      					FROM (
      					SELECT ROW_NUMBER() OVER(PARTITION BY SH.CallHistoryId ORDER BY SDH.CallDurationHistoryId) AS SlNo,
   						SDH.AgentId,SH.CallHistoryId
   						FROM tb_CallHistory SH
   						JOIN tb_CallDurationHistory	SDH	    ON SH.CallHistoryId 		= SDH.CallHistoryId
   						JOIN disposition_status DS ON DS.did = SDH.dispositionId
   						WHERE SDH.IsBot = 0
   						AND SH.domainId = p_domainId
   						AND SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
   						AND	DS.dispositionName <> 'Transferred'
   						AND	SH.IsInBound = 1
                           AND SDH.AgentId IS NOT NULL	
         				) AS SubQuery
         				WHERE SlNo = 1;
                                          
       				DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
       				CREATE TEMPORARY TABLE temp_AllagentId
       				SELECT UserID,UserName,ext,domainId FROM tb_User WHERE domainId = p_domainId ; 
                      
                      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       				DROP TEMPORARY TABLE IF EXISTS tt_CallHistory;
                      CREATE TEMPORARY TABLE tt_CallHistory AS 	    	
       				SELECT 	SH.sessionStartTime
 						,SH.CallHistoryId
 						, SDH.AgentId
 						, SDH.IsMissedCall
 						, SDH.dispositionId
 						, SH.IsAbandoned
 						, U.UserName												
 						, SDH.StartTime												
 						, SDH.EndTime												
 						, SH.IsInBound
 						, SH.callDuration												
 						, SDH.AgentHoldDuration										
 						, SDH.transferredTypeId																	
 						, SDH.afterCallWorkTime		
 						, SH.queueDuration											
 						, SDH.SentimentalScore
 						, SDH.IsBot
 						, t_f.FirstCallResolution 
 						, SDH.answeredDuration
 						, SDH.Duration
                         , SDH.CallDurationHistoryId
                         ,SDH.transferedTo
				FROM 	tb_CallHistory 				SH
				JOIN 	tb_CallDurationHistory		SDH	ON SH.CallHistoryId 	= SDH.CallHistoryId     
				LEFT JOIN temp_AllagentId			U	ON U.UserID				= SDH.AgentId
				LEFT JOIN temp_FirstCallResolution 	t_f	ON t_f.CallHistoryId 	= SDH.CallHistoryId AND t_f.AgentId = SDH.AgentId
				WHERE 	SH.domainId 		= p_domainId	
				AND 	 SDH.IsBot			= 0      
				AND 	 SH.IsInBound 		= 1
				AND 	 (IFNULL(p_agentId,'') = '' OR SDH.AgentId IN (select agentId from temp_agentIDs))
				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ; 
  
  					DROP TEMPORARY TABLE IF EXISTS temp_CallHistory; 
  					CREATE TEMPORARY TABLE temp_CallHistory AS 	    	
  					SELECT 	DISTINCT CallHistoryId
                      , CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
  					, sessionStartTime	
  					, AgentId
  					, UserName												AS agentName
  					, IsInBound
                      , callDuration
  					, callDuration											AS CallHandlingTime
  					, AgentHoldDuration										AS agentHoldDuration
  					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                      , answeredDuration										AS responseTime
  					, afterCallWorkTime		
  					, queueDuration											AS queueWaitingtime
  					, SentimentalScore
  					, case when IsInBound = 1 then 1 else 0 end 			AS inboundCalls   
  					, FirstCallResolution 									AS firstCallResolution
  					,CASE WHEN Duration > 0 THEN 1 ELSE 0 END      		AS respondedCall
  					,CASE WHEN IFNULL(Duration,0) > 0 THEN 1 ELSE 0 END      	AS answeredCall
                      , CASE WHEN answeredDuration IS NULL THEN 1 ELSE 0 END				AS unAnswered
                      , CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                      , CASE WHEN IsMissedCall = 1 THEN 1 ELSE 0 END						AS missedCallCount
                      
                      ,CASE WHEN transferedTo IS NOT NULL THEN 1 ELSE 0 END 			AS transferedCall
                      ,CASE WHEN Duration > 0  THEN Duration ELSE 0 END 					AS totalTalkTime
                      ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
                      ,CallDurationHistoryId
  					FROM 	tt_CallHistory 				
  					WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ; 
                                        
                    DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_prev; 
       				CREATE TEMPORARY TABLE temp_CallHistory_prev AS 	    	
       				SELECT DISTINCT	CallHistoryId
  					, sessionStartTime	
  					, CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
  					, AgentId
  					, UserName												AS agentName
  					, IsInBound
                      , callDuration
  					, callDuration											AS CallHandlingTime
  					, AgentHoldDuration										AS agentHoldDuration
  					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                      , answeredDuration										AS responseTime
  					, afterCallWorkTime		
  					, queueDuration											AS queueWaitingtime
  					, SentimentalScore
  					, case when IsInBound = 1 then 1 else 0 end 				AS inboundCalls   
  					, FirstCallResolution 										AS firstCallResolution
  					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      			AS respondedCall
  					,CASE WHEN answeredDuration > 0 THEN 1 ELSE 0 END      				AS answeredCall
                      ,CASE WHEN answeredDuration IS NULL THEN 1 ELSE 0 END				AS unAnswered
                      ,CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                      ,CASE WHEN transferedTo IS NOT NULL THEN 1 ELSE 0 END 			AS transferedCall
                      ,CASE WHEN callDuration > 0  THEN callDuration ELSE 0 END 			AS totalTalkTime
                      ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
                      ,CASE WHEN IsMissedCall = 1 THEN 1 ELSE 0 END						AS missedCallCount
                      ,CallDurationHistoryId
  					FROM 	tt_CallHistory 				
  					WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ; 
                          
  			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc; 
  			CREATE TEMPORARY TABLE temp_CallHistory_calc AS 	     
  			SELECT 	
  			count(1)                             																			AS NoOfcalls,
  			t_SH.AgentId
  			, t_SH.SessionDate
  			, t_SH.agentName																              						AS agentName
  			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
  			, SUM(t_SH.Handled)																									AS averageHandledTime    
  			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
  			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
  			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
  			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
  			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
  			, t_SH.firstcallResolution
  			, sum(t_SH.inboundCalls)                          																	AS inboundCalls
  			, t_SH.SentimentalScore																								AS CustomerSatisfaction
  			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
  			, sum(t_SH.callDuration)																							AS callDuration	
  			, sum(t_SH.respondedcall)																							AS respondedcall
  			,sum(t_SH.answeredCall)																								AS answeredCall               
  			,sum(t_SH.unAnswered)																								AS unAnswered               
  			,sum(t_SH.abandoned)																								AS abandoned               
  			,sum(t_SH.transferedCall)																							AS transferedCall               
  			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
  			,sum(t_SH.waitDuration)																								AS waitDuration               
			,sum(t_SH.missedCallCount)																							AS missedCallCount
  			FROM 	temp_CallHistory t_SH
  			GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration;    
                    
  		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev; 
  		CREATE TEMPORARY TABLE temp_CallHistory_calc_prev AS 	     
  		SELECT 	
  			count(1)                             																			AS NoOfcalls,
  			t_SH.AgentId
  			, t_SH.SessionDate
  			, t_SH.agentName																              						AS agentName
  			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
  			, SUM(t_SH.Handled)																									AS averageHandledTime    
  			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
  			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
  			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
  			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
  			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
  			, t_SH.firstcallResolution
  			, sum(t_SH.inboundCalls)                          																	AS inboundCalls
  			, t_SH.SentimentalScore																								AS CustomerSatisfaction
  			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
  			, sum(t_SH.callDuration)																							AS callDuration	
  			, sum(t_SH.respondedcall)																							AS respondedcall
  			,sum(t_SH.answeredCall)																								AS answeredCall               
  			,sum(t_SH.unAnswered)																								AS unAnswered               
  			,sum(t_SH.abandoned)																								AS abandoned               
  			,sum(t_SH.transferedCall)																							AS transferedCall               
  			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
  			,sum(t_SH.waitDuration)																								AS waitDuration               
			,sum(t_SH.missedCallCount)																							AS missedCallCount
  			FROM 	temp_CallHistory_prev t_SH
  			GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration;
              
       				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
       				CREATE TEMPORARY TABLE temp_AvailableStates AS
       				SELECT   
       					CASE 
       						WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
       						ELSE 2 
       					END AS tt_Time,
       					ST.ext,
       					ST.domainId,
       					from_unixtime(ST.startTimestamp/1000),
       					ST.stateDuration as SD
       				FROM     state_timer ST 
       				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
       				WHERE    ST.domainId = p_domainId
       				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
       							
       				ALTER TABLE temp_CallHistory_calc ADD COLUMN availableTime BIGINT;
       					  
       				UPDATE temp_CallHistory_calc SH_C
       				JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
       				JOIN (
       				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
       				FROM temp_AvailableStates
       				GROUP BY ext, domainId
       				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
       				SET SH_C.availableTime 	= ifnull(tt_AV.total_SD,0)
       				, 	agentName			= t_A.UserName;                                                  
     
       				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_1;
       				CREATE TEMPORARY TABLE temp_CallHistory_calc_1 AS
       					SELECT 															
       			 	a.AgentId																                                                  AS AgentId
                       ,sum(a.NoOfCalls) as NoOfCalls
  					,sum(a.averageResponseTime)  																			  		  			  AS averageResponseTime
  					,sum(a.averageHandledTime)			                                                              			  				  AS averageHandledTime
       				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
       				,sum(a.totalACWTime)          																							  AS totalACWTime
       				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               							  AS averageHoldtime                                  
       				,sum(a.averageQueueWaitingtime)                                                                           				  AS averageQueueWaittime
       				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
       				,sum(CASE WHEN (a.totalTalktime/if(a.availableTime=0,1,a.availableTime))*100 IS NOT NULL THEN (a.totalTalktime/if(a.availableTime=0,1,a.availableTime))*100 ELSE 0 END)   AS occupancyRate                                      
       				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
       				,sum(a.inboundCalls)																									  AS inboundCalls
       				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
       				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
       				,sum(a.callDuration)																									  AS callDuration
       				,sum(a.availableTime)																									  AS availableTime
                      ,sum(respondedCall)  																									  AS respondedCall
  					,sum(answeredCall)																										  AS answeredCall
                      ,sum(unAnswered)      																									AS unAnswered
                      ,sum(abandoned)       																									AS abandoned
                      ,sum(transferedCall)  																									AS transferedCall
                      ,sum(totalTalkTime)   																									AS totalTalkTime
                      ,sum(waitDuration)    																									AS waitDuration
                      ,sum(missedCallCount)																									AS missedCallCount
       			FROM 	temp_CallHistory_calc 	    a
       			JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID
       			 GROUP BY a.AgentId;   	
                                
                DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev_1;
       				CREATE TEMPORARY TABLE temp_CallHistory_calc_prev_1 AS
       				SELECT 		
       				U.UserName 																	                                              AS agentName
                       ,sum(NoOfCalls)   as NoOfCalls
  					,sum(a.averageResponseTime)   																			  AS averageResponseTime
  					,sum(a.averageHandledTime)					                                                              AS averageHandledTime
       				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
       				,sum(a.totalACWTime)          																							  AS totalACWTime
       				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               AS averageHoldtime                                  
       				,sum(a.averageQueueWaitingtime)                                                                           AS averageQueueWaittime
       				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
       				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
       				,sum(a.inboundCalls)																									  AS inboundCalls
       				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
       				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
       				,sum(a.callDuration)																									  AS callDuration
                     ,sum(respondedCall)  as respondedCall
  					,sum(answeredCall)																											AS answeredCall
                      ,sum(unAnswered)      																									AS unAnswered
                      ,sum(abandoned)       																									AS abandoned
                      ,sum(transferedCall)  																									AS transferedCall
                      ,sum(totalTalkTime)   																									AS totalTalkTime
                      ,sum(waitDuration)    																									AS waitDuration
                      ,sum(missedCallCount)																									AS missedCallCount
       			FROM 	temp_CallHistory_calc_prev 	a
       			JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
       			GROUP BY U.UserName;   	
  				
                  DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_curCount;
  				CREATE TEMPORARY TABLE temp_CallHistory_curCount AS
                  SELECT DISTINCT CallHistoryId
                  FROM temp_CallHistory;
                  
                  DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_prevCount;
  				CREATE TEMPORARY TABLE temp_CallHistory_prevCount AS
  				SELECT DISTINCT CallHistoryId
                  FROM temp_CallHistory_prev a;
  				
                  SELECT count(CallHistoryId) INTO v_curCallCount
                  FROM temp_CallHistory_curCount;
                  
                  SELECT count(CallHistoryId) INTO v_prevCallCount
                  FROM temp_CallHistory_prevCount;
                  
       			select  
       			sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
       			sum(firstCallResolution), sum(CustomerSatisfaction),sum(inboundCalls),
       			sum(callDuration),sum(afterCallWorkTime),sum(availableTime),sum(answeredCall),sum(unAnswered),sum(abandoned),sum(transferedCall),sum(totalTalkTime),sum(waitDuration),sum(missedCallCount)
       			INTO
       			v_count,v_answerCall, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
  				v_firstCallResolution, v_CustomerSatisfaction,v_inboundCalls,
       			v_callDuration,v_afterCallWorkTime,v_availableTime,v_answeredCall,v_unAnswered,v_abandoned,v_transferedCall,v_totalTalkTime,v_waitDuration,v_missedCallCount
       			FROM temp_CallHistory_calc_1;  
                
  				select sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(abandoned)
       			INTO v_prvcount,v_prevAnswerCall, v_prevAverageResponseTime, v_prevAverageHandledTime , v_prevAbandoned
       			FROM temp_CallHistory_calc_prev_1; 
  
  				SELECT 	CASE WHEN IFNULL(v_answerCall,0) = 0 THEN 0 ELSE (v_averageResponseTime/v_answerCall) END,
    					CASE WHEN IFNULL(v_count,0) = 0 THEN 0 ELSE (v_averageHandledTime/v_count) END
  				INTO v_CurrentTotalCount,v_currentAVGHandleTime;
    		
    			SELECT * FROM temp_AllagentId;
    
  			SET v_DiffTotalPercent 		= ((v_count - ifnull(v_prvcount,0)) / IF(IFNULL(v_prvcount,0)=0,1,v_prvcount)) * 100 
              ,	v_DiffAnsweredPercent	= ((v_answeredCall - ifnull(v_prevAnswerCall,0)) / IF(IFNULL(v_prevAnswerCall,0)=0,1,v_prevAnswerCall)) * 100
  			,	v_DiffAbandonedPercent	= (IFNULL(v_abandoned,0) - v_prevAbandoned) / IF(IFNULL(v_prevAbandoned,0)=0,1,v_prevAbandoned) * 100;  
  
    
    			SELECT 	IFNULL(v_count,0) 											AS 'TotalCount',
    					IFNULL(v_DiffTotalPercent,0) 		        				AS 'DiffTotalPercent',
    					IFNULL(v_answeredCall,0) 			    					AS 'CurrentAnsweredeCount',
    					IFNULL(v_DiffAnsweredPercent,0) 							AS 'DiffAnsweredPercent',
    					IFNULL(v_abandoned,0) 										AS 'CurrentAbandonedCount',
    					IFNULL(v_DiffAbandonedPercent,0) 							AS 'DiffAbandonedPercent';                   

       			select 'All Agents'													 AS agentName,	
                  v_count																 AS Inboundcalls,
                  v_answeredCall														 AS AnsweredCalls,
                  v_missedCallCount 													AS missedCalls,
                  v_abandoned 														AS abandonedCalls,
                  v_transferedCall 													AS transferredCalls,
                  v_totalTalkTime 													AS Talktime,
                  (v_waitDuration/v_count)											AS avgSpeedofAnswer,
  				(v_averageHandledTime/v_count)*1000                                 AS  AverageHandleTime, 
       			v_MaximumHandledTime                                               	 AS  maximumHandleTime,
       			v_averageHoldtime/1000                                               AS  averageHoldTime,
       			((v_callDuration + (v_afterCallWorkTime * 1000)) / v_availableTime )*100	 AS   occupancyrate,
       			v_afterCallWorkTime	 												AS   ACWTime,
       			round((v_firstCallResolution /v_inboundCalls) * 100  )             	AS  FirstCallResolution,
       			v_CustomerSatisfaction												AS customersatisfaction,
                  0 																	AS avgCallDuration
       		UNION ALL
       			SELECT DISTINCT(U.UserName)											AS  agentName, 
                  sum(NoOfcalls)														AS Inboundcalls, 
                  sum(answeredCall)													AS AnsweredCalls,
                  sum(missedCallCount)												AS missedCalls,
                  sum(abandoned)														AS abandonedCalls,
                  sum(transferedCall)													AS transferredCalls,
                  sum(totalTalkTime)													AS Talktime,
                  sum(waitDuration/NoOfcalls)											AS avgSpeedofAnswer,
       			sum(averageHandledTime/NoOfCalls)*1000                              	AS AverageHandleTime, 
       			sum(MaximumHandledTime)                                             AS maximumHandleTime, 
       			sum(averageHoldtime)/1000                                           AS  averageHoldTime, 
       			IFNULL(((sum(callDuration) + (sum(afterCallWorkTime) * 1000)) / sum(IF(availableTime=0,1,availableTime)) )*100,0)	AS   occupancyrate,
                  sum(afterCallWorkTime)												AS ACWTime,
       			round(sum(firstCallResolution/inboundCalls) *100 )                 AS FirstCallResolution,
       			sum(CustomerSatisfaction)											AS customersatisfaction,
                  0 as avgCallDuration
       			FROM temp_CallHistory_calc_1 a
   				JOIN 	temp_AllagentId		U	ON a.AgentId	= U.UserID
       			group by agentName;
   
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Agent_Inboundcall_analysis_metrics_filter_NLP` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Agent_Inboundcall_analysis_metrics_filter_NLP`(  
	 p_startTmpstmp 		BIGINT,
	 p_endTmpstmp 		BIGINT,
	 p_domainId 			INT,    	
	 p_agentId			TEXT,		
	 p_offset 			INT,
	 p_Limit 			INT	
 )
BEGIN
                             
  				DECLARE v_offset 								INT;	  	
  				DECLARE v_CurrentStartTmpstmp 					BIGINT;
  				DECLARE v_CurrentEndTmpstmp 					BIGINT;
  				DECLARE v_PrevStartTmpstmp 						BIGINT;
  				DECLARE v_PrevEndTmpstmp 						BIGINT; 
  				DECLARE v_TmpstmpInterval						BIGINT;	
  				DECLARE v_DifffirstCallResolutionPercent		INT;  
  
  				DECLARE		v_averageResponseTime             	BIGINT; 
  				DECLARE		v_averageHandledTime				BIGINT;
  				DECLARE		v_MaximumHandledTime              	BIGINT; 
  				DECLARE		v_totalACWTime						BIGINT;
  				DECLARE		v_averageHoldtime                 	BIGINT; 
  				DECLARE		v_firstCallResolution             	BIGINT; 
  				DECLARE		v_CustomerSatisfaction				BIGINT; 
  				DECLARE		v_inboundCalls						BIGINT; 
  				DECLARE		v_callDuration						BIGINT; 
  				DECLARE		v_afterCallWorkTime					INT; 
  				DECLARE		v_availableTime						BIGINT; 
  				DECLARE		v_currentResponseTime				BIGINT; 
  				DECLARE		v_previousResponseTime				BIGINT; 
  				DECLARE		v_currentHandledTime				BIGINT; 
  				DECLARE		v_previousHandledTime				BIGINT; 
  				DECLARE		v_currentTotalAnsweredCalls			INT; 
  				DECLARE		v_previousTotalAnsweredCalls		INT; 
  				DECLARE       v_count							INT;
  				DECLARE       v_answerCall						INT;
  				DECLARE       v_CurTotalCount					INT;
  				DECLARE       v_PrevTotalCount					INT;
  				DECLARE       v_CurResponseTime					INT;
  				DECLARE       v_PreResponseTime					INT;
  				DECLARE       v_CurHandledTime					INT;
  				DECLARE       v_PreHandledTime					INT;
  
  				DECLARE		v_prvcount							INT;
  				DECLARE		v_prevAnswerCall					INT; 
  				DECLARE		v_prevAverageResponseTime			INT;
  				DECLARE		v_prevAverageHandledTime			INT;
  				DECLARE		v_CurrentTotalCount					INT;
  				DECLARE		v_currentAVGHandleTime				INT;
  
  				DECLARE v_unAnswered INT;
  				DECLARE v_abandoned INT;
  				DECLARE v_transferedCall INT;
  				DECLARE v_totalTalkTime INT;
  				DECLARE v_waitDuration INT;
  				DECLARE v_answeredCall INT;
  				DECLARE v_DiffTotalPercent INT;
  				DECLARE v_DiffAnsweredPercent INT;
  				DECLARE v_prevAbandoned INT;
  				DECLARE v_DiffUnAnsweredPercent INT;
  				DECLARE v_missedCallCount INT;
  				DECLARE v_DiffAbandonedPercent INT;
  				DECLARE v_prevCallCount INT;
  				DECLARE v_curCallCount INT;
  
       
    				SET v_offset =  p_Limit * p_offset; 
    
    				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
    				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
    
    				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
    
    				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
    				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                        		
       				DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
       				CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
       
       				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                  	
       				DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
       				CREATE TEMPORARY TABLE temp_FirstCallResolution
    					
                     SELECT 	SlNo AS FirstCallResolution,
   							SubQuery.AgentId,SubQuery.CallHistoryId
      					FROM (
      					SELECT ROW_NUMBER() OVER(PARTITION BY SH.CallHistoryId ORDER BY SDH.CallDurationHistoryId) AS SlNo,
   						SDH.AgentId,SH.CallHistoryId
   						FROM tb_CallHistory SH
   						JOIN tb_CallDurationHistory	SDH	    ON SH.CallHistoryId 		= SDH.CallHistoryId
   						JOIN disposition_status DS ON DS.did = SDH.dispositionId
   						WHERE SDH.IsBot = 0
   						AND SH.domainId = p_domainId
   						AND SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
   						AND	DS.dispositionName <> 'Transferred'
   						AND	SH.IsInBound = 0
                           AND SDH.AgentId IS NOT NULL	
         				) AS SubQuery
         				WHERE SlNo = 1;
                                            
       				DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
       				CREATE TEMPORARY TABLE temp_AllagentId
       				SELECT UserID,UserName,ext,domainId FROM tb_User WHERE domainId = p_domainId AND roleId in (3,5,6); 
                      
                      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       				DROP TEMPORARY TABLE IF EXISTS tt_CallHistory;
                      CREATE TEMPORARY TABLE tt_CallHistory AS 	    	
       				SELECT 	SH.sessionStartTime
 						,SH.CallHistoryId
 						, SDH.AgentId
 						, SDH.IsMissedCall
 						, SDH.dispositionId
 						, SH.IsAbandoned
 						, U.UserName												
 						, SDH.StartTime												
 						, SDH.EndTime												
 						, SH.IsInBound
 						, SH.callDuration												
 						, SDH.AgentHoldDuration										
 						, SDH.transferredTypeId																	
 						, SDH.afterCallWorkTime		
 						, SH.queueDuration											
 						, SDH.SentimentalScore
 						, SDH.IsBot
 						, t_f.FirstCallResolution 
 						, SDH.answeredDuration
 						, SDH.Duration
                         , SDH.CallDurationHistoryId
       				FROM 	tb_CallHistory 				SH
       				JOIN 	tb_CallDurationHistory		SDH	ON SH.CallHistoryId 	= SDH.CallHistoryId     
       				LEFT JOIN temp_AllagentId			U	ON U.UserID				= SDH.AgentId
       				LEFT JOIN temp_FirstCallResolution 	t_f	ON t_f.CallHistoryId 	= SDH.CallHistoryId
       				WHERE 	SH.domainId 		= p_domainId	
   				 	AND 	 SDH.IsBot			= 0      
                      AND 	 SH.IsInBound 		= 1
                      AND 	 (IFNULL(p_agentId,'') = '' OR SDH.AgentId IN (select agentId from temp_agentIDs))
       				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ; 
  
  					DROP TEMPORARY TABLE IF EXISTS temp_CallHistory; 
  					CREATE TEMPORARY TABLE temp_CallHistory AS 	    	
  					SELECT 	DISTINCT CallHistoryId
                      , CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
  					, sessionStartTime	
  					, AgentId
  					, UserName												AS agentName
  					, IsInBound
                      , callDuration
  					, callDuration											AS CallHandlingTime
  					, AgentHoldDuration										AS agentHoldDuration
  					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                      , answeredDuration										AS responseTime
  					, afterCallWorkTime		
  					, queueDuration											AS queueWaitingtime
  					, SentimentalScore
  					, case when IsInBound = 1 then 1 else 0 end 			AS inboundCalls   
  					, FirstCallResolution 									AS firstCallResolution
  					,CASE WHEN Duration > 0 THEN 1 ELSE 0 END      		AS respondedCall
  					,CASE WHEN IFNULL(Duration,0) > 0 THEN 1 ELSE 0 END      	AS answeredCall
                      , CASE WHEN answeredDuration IS NULL THEN 1 ELSE 0 END				AS unAnswered
                      , CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                      , CASE WHEN IsMissedCall = 1 THEN 1 ELSE 0 END						AS missedCallCount
                      ,CASE WHEN transferredTypeId = 2002002 THEN 1 ELSE 0 END 			AS transferedCall
                      ,CASE WHEN Duration > 0  THEN Duration ELSE 0 END 					AS totalTalkTime
                      ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
                      ,CallDurationHistoryId
  					FROM 	tt_CallHistory 				
  					WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ; 
                                      
                    DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_prev; 
       				CREATE TEMPORARY TABLE temp_CallHistory_prev AS 	    	
       				SELECT DISTINCT	CallHistoryId
  					, sessionStartTime	
  					, CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
  					, AgentId
  					, UserName												AS agentName
  					, IsInBound
                      , callDuration
  					, callDuration											AS CallHandlingTime
  					, AgentHoldDuration										AS agentHoldDuration
  					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                      , answeredDuration										AS responseTime
  					, afterCallWorkTime		
  					, queueDuration											AS queueWaitingtime
  					, SentimentalScore
  					, case when IsInBound = 1 then 1 else 0 end 				AS inboundCalls   
  					, FirstCallResolution 										AS firstCallResolution
  					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      			AS respondedCall
  					,CASE WHEN answeredDuration > 0 THEN 1 ELSE 0 END      				AS answeredCall
                      ,CASE WHEN answeredDuration IS NULL THEN 1 ELSE 0 END				AS unAnswered
                      ,CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                      ,CASE WHEN transferredTypeId = 2002002 THEN 1 ELSE 0 END 			AS transferedCall
                      ,CASE WHEN callDuration > 0  THEN callDuration ELSE 0 END 			AS totalTalkTime
                      ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
                      ,CASE WHEN IsMissedCall = 1 THEN 1 ELSE 0 END						AS missedCallCount
                      ,CallDurationHistoryId
  					FROM 	tt_CallHistory 				
  					WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ; 
                          
  			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc; 
  			CREATE TEMPORARY TABLE temp_CallHistory_calc AS 	     
  			SELECT 	
  			count(1)                             																			AS NoOfcalls,
  			t_SH.AgentId
  			, t_SH.SessionDate
  			, t_SH.agentName																              						AS agentName
  			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
  			, SUM(t_SH.Handled)																									AS averageHandledTime    
  			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
  			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
  			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
  			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
  			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
  			, t_SH.firstcallResolution
  			, sum(t_SH.inboundCalls)                          																	AS inboundCalls
  			, t_SH.SentimentalScore																								AS CustomerSatisfaction
  			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
  			, sum(t_SH.callDuration)																							AS callDuration	
  			, sum(t_SH.respondedcall)																							AS respondedcall
  			,sum(t_SH.answeredCall)																								AS answeredCall               
  			,sum(t_SH.unAnswered)																								AS unAnswered               
  			,sum(t_SH.abandoned)																								AS abandoned               
  			,sum(t_SH.transferedCall)																							AS transferedCall               
  			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
  			,sum(t_SH.waitDuration)																								AS waitDuration               
			,sum(t_SH.missedCallCount)																							AS missedCallCount
  			FROM 	temp_CallHistory t_SH
  			GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration;    
                    
  		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev; 
  		CREATE TEMPORARY TABLE temp_CallHistory_calc_prev AS 	     
  		SELECT 	
  			count(1)                             																			AS NoOfcalls,
  			t_SH.AgentId
  			, t_SH.SessionDate
  			, t_SH.agentName																              						AS agentName
  			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
  			, SUM(t_SH.Handled)																									AS averageHandledTime    
  			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
  			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
  			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
  			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
  			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
  			, t_SH.firstcallResolution
  			, sum(t_SH.inboundCalls)                          																	AS inboundCalls
  			, t_SH.SentimentalScore																								AS CustomerSatisfaction
  			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
  			, sum(t_SH.callDuration)																							AS callDuration	
  			, sum(t_SH.respondedcall)																							AS respondedcall
  			,sum(t_SH.answeredCall)																								AS answeredCall               
  			,sum(t_SH.unAnswered)																								AS unAnswered               
  			,sum(t_SH.abandoned)																								AS abandoned               
  			,sum(t_SH.transferedCall)																							AS transferedCall               
  			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
  			,sum(t_SH.waitDuration)																								AS waitDuration               
			,sum(t_SH.missedCallCount)																							AS missedCallCount
  			FROM 	temp_CallHistory_prev t_SH
  			GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration;
              
       				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
       				CREATE TEMPORARY TABLE temp_AvailableStates AS
       				SELECT   
       					CASE 
       						WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
       						ELSE 2 
       					END AS tt_Time,
       					ST.ext,
       					ST.domainId,
       					from_unixtime(ST.startTimestamp/1000),
       					ST.stateDuration as SD
       				FROM     state_timer ST 
       				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
       				WHERE    ST.domainId = p_domainId
       				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
       							
       				ALTER TABLE temp_CallHistory_calc ADD COLUMN availableTime BIGINT;
       					  
       				UPDATE temp_CallHistory_calc SH_C
       				JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
       				JOIN (
       				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
       				FROM temp_AvailableStates
       				GROUP BY ext, domainId
       				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
       				SET SH_C.availableTime 	= ifnull(tt_AV.total_SD,0)
       				, 	agentName			= t_A.UserName;                                                  
     
       				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_1;
       				CREATE TEMPORARY TABLE temp_CallHistory_calc_1 AS
       					SELECT 															
       			 	a.AgentId																                                                  AS AgentId
                       ,sum(a.NoOfCalls) as NoOfCalls
  					,sum(a.averageResponseTime)  																			  		  			  AS averageResponseTime
  					,sum(a.averageHandledTime)			                                                              			  				  AS averageHandledTime
       				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
       				,sum(a.totalACWTime)          																							  AS totalACWTime
       				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               							  AS averageHoldtime                                  
       				,sum(a.averageQueueWaitingtime)                                                                           				  AS averageQueueWaittime
       				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
       				,sum(CASE WHEN (a.totalTalktime/if(a.availableTime=0,1,a.availableTime))*100 IS NOT NULL THEN (a.totalTalktime/if(a.availableTime=0,1,a.availableTime))*100 ELSE 0 END)   AS occupancyRate                                      
       				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
       				,sum(a.inboundCalls)																									  AS inboundCalls
       				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
       				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
       				,sum(a.callDuration)																									  AS callDuration
       				,sum(a.availableTime)																									  AS availableTime
                      ,sum(respondedCall)  																									  AS respondedCall
  					,sum(answeredCall)																										  AS answeredCall
                      ,sum(unAnswered)      																									AS unAnswered
                      ,sum(abandoned)       																									AS abandoned
                      ,sum(transferedCall)  																									AS transferedCall
                      ,sum(totalTalkTime)   																									AS totalTalkTime
                      ,sum(waitDuration)    																									AS waitDuration
                      ,sum(missedCallCount)																									AS missedCallCount
       			FROM 	temp_CallHistory_calc 	    a
       			JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID
       			 GROUP BY a.AgentId;   	
                
                
                DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev_1;
       				CREATE TEMPORARY TABLE temp_CallHistory_calc_prev_1 AS
       				SELECT 		
       				U.UserName 																	                                              AS agentName
                       ,sum(NoOfCalls)   as NoOfCalls
  					,sum(a.averageResponseTime)   																			  AS averageResponseTime
  					,sum(a.averageHandledTime)					                                                              AS averageHandledTime
       				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
       				,sum(a.totalACWTime)          																							  AS totalACWTime
       				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               AS averageHoldtime                                  
       				,sum(a.averageQueueWaitingtime)                                                                           AS averageQueueWaittime
       				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
       				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
       				,sum(a.inboundCalls)																									  AS inboundCalls
       				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
       				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
       				,sum(a.callDuration)																									  AS callDuration
                     ,sum(respondedCall)  as respondedCall
  					,sum(answeredCall)																											AS answeredCall
                      ,sum(unAnswered)      																									AS unAnswered
                      ,sum(abandoned)       																									AS abandoned
                      ,sum(transferedCall)  																									AS transferedCall
                      ,sum(totalTalkTime)   																									AS totalTalkTime
                      ,sum(waitDuration)    																									AS waitDuration
                      ,sum(missedCallCount)																									AS missedCallCount
       			FROM 	temp_CallHistory_calc_prev 	a
       			JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
       			GROUP BY U.UserName;   	
  				
                  DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_curCount;
  				CREATE TEMPORARY TABLE temp_CallHistory_curCount AS
                  SELECT DISTINCT CallHistoryId
                  FROM temp_CallHistory;
                  
                  DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_prevCount;
  				CREATE TEMPORARY TABLE temp_CallHistory_prevCount AS
  				SELECT DISTINCT CallHistoryId
                  FROM temp_CallHistory_prev a;
  				
                  SELECT count(CallHistoryId) INTO v_curCallCount
                  FROM temp_CallHistory_curCount;
                  
                  SELECT count(CallHistoryId) INTO v_prevCallCount
                  FROM temp_CallHistory_prevCount;
                  
       			select  
       			sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
       			sum(firstCallResolution), sum(CustomerSatisfaction),sum(inboundCalls),
       			sum(callDuration),sum(afterCallWorkTime),sum(availableTime),sum(answeredCall),sum(unAnswered),sum(abandoned),sum(transferedCall),sum(totalTalkTime),sum(waitDuration),sum(missedCallCount)
       			INTO
       			v_count,v_answerCall, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
  				v_firstCallResolution, v_CustomerSatisfaction,v_inboundCalls,
       			v_callDuration,v_afterCallWorkTime,v_availableTime,v_answeredCall,v_unAnswered,v_abandoned,v_transferedCall,v_totalTalkTime,v_waitDuration,v_missedCallCount
       			FROM temp_CallHistory_calc_1;  
                
  				select sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(abandoned)
       			INTO v_prvcount,v_prevAnswerCall, v_prevAverageResponseTime, v_prevAverageHandledTime , v_prevAbandoned
       			FROM temp_CallHistory_calc_prev_1; 
  
  				SELECT 	CASE WHEN IFNULL(v_answerCall,0) = 0 THEN 0 ELSE (v_averageResponseTime/v_answerCall) END,
    					CASE WHEN IFNULL(v_count,0) = 0 THEN 0 ELSE (v_averageHandledTime/v_count) END
  				INTO v_CurrentTotalCount,v_currentAVGHandleTime;
    		    
  			SET v_DiffTotalPercent 		= ((v_count - ifnull(v_prvcount,0)) / IF(IFNULL(v_prvcount,0)=0,1,v_prvcount)) * 100 
              ,	v_DiffAnsweredPercent	= ((v_answeredCall - ifnull(v_prevAnswerCall,0)) / IF(IFNULL(v_prevAnswerCall,0)=0,1,v_prevAnswerCall)) * 100
  			,	v_DiffAbandonedPercent	= (IFNULL(v_abandoned,0) - v_prevAbandoned) / IF(IFNULL(v_prevAbandoned,0)=0,1,v_prevAbandoned) * 100;  
    
    	 
       			select 'All Agents'													 AS agentName,	
                  v_count																 AS Inboundcalls,
                  v_answeredCall														 AS AnsweredCalls,
                  v_missedCallCount 													AS missedCalls,
                  v_abandoned 														AS abandonedCalls,
                  v_transferedCall 													AS transferredCalls,
                  v_totalTalkTime 													AS Talktime,
                  (v_waitDuration/v_count)											AS avgSpeedofAnswer,
  				(v_averageHandledTime/v_count)*1000                                 AS  AverageHandleTime, 
       			v_MaximumHandledTime                                               	 AS  maximumHandleTime,
       			v_averageHoldtime/1000                                               AS  averageHoldTime,
       			((v_callDuration + (v_afterCallWorkTime * 1000)) / v_availableTime )*100	 AS   occupancyrate,
       			v_afterCallWorkTime	 												AS   ACWTime,
       			round((v_firstCallResolution /v_inboundCalls) * 100  )             	AS  FirstCallResolution,
       			v_CustomerSatisfaction												AS customersatisfaction,
                  0 																	AS avgCallDuration
       		UNION ALL
       			SELECT DISTINCT(U.UserName)											AS  agentName, 
                  sum(NoOfcalls)														AS Inboundcalls, 
                  sum(answeredCall)													AS AnsweredCalls,
                  sum(missedCallCount)												AS missedCalls,
                  sum(abandoned)														AS abandonedCalls,
                  sum(transferedCall)													AS transferredCalls,
                  sum(totalTalkTime)													AS Talktime,
                  sum(waitDuration/NoOfcalls)											AS avgSpeedofAnswer,
       			sum(averageHandledTime/NoOfCalls)*1000                              	AS AverageHandleTime, 
       			sum(MaximumHandledTime)                                             AS maximumHandleTime, 
       			sum(averageHoldtime)/1000                                           AS  averageHoldTime, 
       			IFNULL(((sum(callDuration) + (sum(afterCallWorkTime) * 1000)) / sum(IF(availableTime=0,1,availableTime)) )*100,0)	AS   occupancyrate,
                  sum(afterCallWorkTime)												AS ACWTime,
       			round(sum(firstCallResolution/inboundCalls) *100 )                 AS FirstCallResolution,
       			sum(CustomerSatisfaction)											AS customersatisfaction,
                  0 as avgCallDuration
       			FROM temp_CallHistory_calc_1 a
   				JOIN 	temp_AllagentId		U	ON a.AgentId	= U.UserID
       			group by agentName;
   
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Agent_Inboundcall_analysis_metrics_filter_QA_backup_20240913` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Agent_Inboundcall_analysis_metrics_filter_QA_backup_20240913`(
                  p_startTmpstmp   	BIGINT,
                  p_endTmpstmp 		BIGINT,
                  p_domainId 	    INT,    	
                  p_agentId			VARCHAR(250),		
                  p_offset 			INT,
                  p_Limit 			INT	
              )
sp_return:BEGIN
              
              		DECLARE v_offset 					INT;	  	
              		DECLARE v_CurrentStartTmpstmp 		BIGINT;
              		DECLARE v_CurrentEndTmpstmp 		BIGINT;
              		DECLARE v_PrevStartTmpstmp 			BIGINT;
              		DECLARE v_PrevEndTmpstmp 			BIGINT; 
              		DECLARE v_TmpstmpInterval			BIGINT;	
              
              		DECLARE v_CurTotalCount 			INT;
              		DECLARE v_PrevTotalCount 			INT;
              		DECLARE	v_DiffTotalPercent 			INT;
              
              		DECLARE v_PrevAnsweredCount			INT;
              		DECLARE v_CurrentAnsweredCount		INT;
              		DECLARE v_DiffAnsweredPercent		INT;
              
              		DECLARE v_PrevAbandonedCount		INT;
              		DECLARE v_CurrentAbandonedCount		INT;
              		DECLARE v_DiffAbandonedPercent		INT;
              
              		DECLARE v_CurrentMissedCount		INT;
              		DECLARE v_CurrentTransferredCount	INT;
              		DECLARE v_TotalCallDuration			BIGINT;
              
        			DECLARE v_TotalTalktime             	BIGINT;
        			DECLARE v_TotalAfterCallWorkTime    	INT;
                    DECLARE v_CurrentCallHoldTime       	INT;
                    DECLARE v_CurrentAvailableTime      	BIGINT;
                    DECLARE v_SentimentalScore          	INT;
                    DECLARE v_CurrentFirstCallResolution  INT;
                    declare v_answeredDuration           INT;
              
              
              
     			
     				declare v_Inboundcalls 			INT;
     				declare v_AnsweredCalls			INT;
     				declare v_abandonedCalls		INT;
     				declare v_missedCalls			INT;
     				declare v_transferredCalls		INT;
     				declare v_Talktime 				BIGINT;
     				declare v_avgCallDuration		BIGINT;
     				declare v_avgSpeedofAnswer		BIGINT;
     				declare v_averageHandleTime 	BIGINT;
     				declare v_maximumHandleTime		BIGINT;
     				declare v_ACWTime				BIGINT;
     				declare v_averageHoldTime 		BIGINT;
     				declare v_occupancyrate			BIGINT;
     				declare v_FirstCallResolution 	BIGINT;
     				declare v_customersatisfaction	BIGINT;    
              
     	
              		SET v_offset =  p_Limit * p_offset; 
                  
                  	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
                  	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
                  	
              		SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
                
              		SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
              		SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
        
              		DROP TEMPORARY TABLE IF EXISTS temp_agentIDs_dtl;	CREATE TEMPORARY TABLE temp_agentIDs_dtl(agentId BIGINT);
              		CALL split(p_agentId,',');	INSERT INTO temp_agentIDs_dtl(agentId) SELECT Items FROM tt_Split_temptable;  
              					   
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
              		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId_dtl;	
              		CREATE TEMPORARY TABLE temp_AllagentId_dtl
              		SELECT 	UserID,UserName ,ext,domainId
              		FROM 	tb_User 
              		WHERE 	domainId = p_domainId; 
                      
              		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
              		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
              		CREATE TEMPORARY TABLE temp_callDurationHistory AS
              		SELECT 		CH.sessionStartTime		
              					,CH.CallHistoryId        
              					,CDH.CallDurationHistoryId
              					,CDH.AgentId
              					,CDH.IsMissedCall
              					,CH.IsAbandoned
              					,CDH.transferredTypeId 
              					,CDH.dispositionId
     							,CDH.AgentHoldDuration
             					,(case when CDH.Duration > 0 then CDH.Duration else 0 end)	                        AS callDuration
                                 ,CDH.afterCallWorkTime			                                                    AS afterCallWorkTime
                                 ,CH.IsInBound					                                                    AS IsInBound
     							,	CDH.StartTime																	AS agentconnecttime
             					,	CDH.EndTime					   												    AS agentDisconnectTime
                                ,CDH.SentimentalScore                                                                AS SentimentalScore
                                ,CDH.IsBot
                                ,DS.dispositionName
                                ,CDH.answeredDuration
                                ,CDH.transferedBy
              		FROM 		tb_CallHistory 			CH
              		     JOIN 	tb_CallDurationHistory	CDH	    ON CH.CallHistoryId 		= CDH.CallHistoryId
              		LEFT JOIN 	tb_CallMessage			CM		ON CH.CallHistoryId 		= CM.CallHistoryId and CM.CallDurationHistoryId	= CDH.CallDurationHistoryId
              		LEFT JOIN 	temp_agentIDs_dtl 		t_A     ON CDH.AgentId				= t_A.agentId   
     				LEFT JOIN 	disposition_status		DS		ON DS.did					= CDH.dispositionId and DS.domainId = CH.domainId
              		WHERE 	CH.domainId 			= p_domainId 		
              		AND 	CH.IsInBound			= 1
              		AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
              		AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
        			LIMIT v_offset, p_limit; 
              		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
            
                        DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                        CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                                    	SELECT 	
     								     t_SH.sessionStartTime		
            							,t_SH.CallHistoryId        
            							,t_SH.CallDurationHistoryId
            							,t_SH.AgentId
            							,t_SH.IsMissedCall
            							,t_SH.IsAbandoned
            							,(case when t_SH.IsBot = 0 and t_SH.transferredTypeId<>0 then 1 else 0 end)				   		AS transferredTypeId
            							,t_SH.dispositionId
            							,t_SH.callDuration
                                     ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)										        	AS totalTalktime
                                     ,SUM(t_SH.afterCallWorkTime)                                                              		AS afterCallWorkTime
                                     ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.answeredDuration is not null  THEN 1 ELSE 0 END) 		AS  answeredCall
                                     ,SUM(t_SH.agentHoldDuration)															   			AS  callHoldTime
                                     ,t_SH.SentimentalScore
                                     ,t_SH.answeredDuration
                                     ,(case when t_SH.transferedBy is not null then 1 else 0 end)								    	AS transferedBy
                                     ,SUM(CASE WHEN t_SH.IsBot = 0 AND t_SH.dispositionName = 'Transferred' THEN 1 ELSE 0 END)   		AS FirstCallResolution
                                     ,SUM(CASE WHEN t_SH.dispositionName = 'Transferred' THEN 1 ELSE 0 END)							AS istransfered  
                                     ,SUM(CASE WHEN dispositionName = 'Caller Disconnected' THEN 1 ELSE 0 END)							AS Abandoned 
                                    FROM 	temp_callDurationHistory t_SH
                                    GROUP BY t_SH.sessionStartTime, t_SH.CallHistoryId, t_SH.CallDurationHistoryId,t_SH.AgentId, t_SH.IsMissedCall,t_SH.IsAbandoned,t_SH.transferredTypeId,
                                    t_SH.dispositionId,t_SH.callDuration,t_SH.SentimentalScore,t_SH.answeredDuration,t_SH.IsBot,t_SH.transferedBy,t_SH.dispositionName;                                  
                                    
                                                         
       							    DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
       								CREATE TEMPORARY TABLE temp_AvailableState AS
       								SELECT   
       								CASE 
       									WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
       									WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Not Ready', 'Away', 'Offline') THEN 2
       									ELSE 3 
       								END AS tt_Time,
       								ST.ext,
       								ST.domainId,
       								from_unixtime(ST.startTimestamp/1000),
       								ST.stateDuration as SD
       								FROM     state_timer ST 
       								JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
       								WHERE    ST.domainId = p_domainId
       								AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;                                                
                  
                  
       								ALTER TABLE temp_chatHistory_calc ADD COLUMN availableTime		BIGINT; 
                  
                                          			UPDATE temp_chatHistory_calc SH_C
        										JOIN temp_AllagentId_dtl t_A ON SH_C.agentId = t_A.UserID
        										JOIN (
        											SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
        											FROM temp_AvailableState
        											GROUP BY ext, domainId
        										) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
        										SET SH_C.availableTime = tt_AV.total_SD;      
                  
                      
              		DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
              		CREATE TEMPORARY TABLE temp_PrevCallHistory as
              		SELECT 	DISTINCT CallHistoryId ,IsAbandoned
              		FROM 	temp_callDurationHistory
              		WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
              
              		DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
              		CREATE TEMPORARY TABLE temp_CurCallHistory AS
              		SELECT 	DISTINCT CallHistoryId,IsAbandoned 
              		FROM 	temp_callDurationHistory
              		WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;   
                      
              		ALTER TABLE temp_PrevCallHistory ADD COLUMN isAnswered	TINYINT;
              		ALTER TABLE temp_CurCallHistory ADD COLUMN isAnswered	TINYINT;
                    
      				UPDATE 	temp_PrevCallHistory CH
                   	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
                   	AND 	CDH.dispositionId IS NOT NULL and IFNULL(CDH.IsMissedCall,0)=0 and IFNULL(CH.IsAbandoned,0)=0
                   	SET 	CH.isAnswered = 1;
                       
                   	UPDATE 	temp_CurCallHistory CH
                   	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
                   	AND 	CDH.dispositionId IS NOT NULL and IFNULL(CDH.IsMissedCall,0)=0 and IFNULL(CH.IsAbandoned,0)=0
                   	SET 	CH.isAnswered = 1;
                
        			SELECT 	COUNT(CallHistoryId), SUM(isAnswered)
       			INTO 	v_PrevTotalCount , v_PrevAnsweredCount 
   				FROM	temp_PrevCallHistory;
        
   				SELECT 	COUNT(CallHistoryId), SUM(isAnswered)
   				INTO 	v_CurTotalCount , v_CurrentAnsweredCount 
              		FROM	temp_CurCallHistory;   
        
                    SELECT 	SUM(IsMissedCall), SUM(istransfered), SUM(callDuration),SUM(totalTalktime),SUM(afterCallWorkTime),sum(answeredCall),sum(callHoldTime),sum(SentimentalScore),sum(availableTime),sum(FirstCallResolution),sum(answeredDuration)
             		INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_TotalCallDuration,v_TotalTalktime,v_TotalAfterCallWorkTime ,v_CurrentAnsweredCount,v_CurrentCallHoldTime,v_SentimentalScore,v_CurrentAvailableTime,v_CurrentFirstCallResolution,v_answeredDuration
             		FROM 	temp_chatHistory_calc;
        
   				SELECT sum(Abandoned)
   				INTO v_CurrentAbandonedCount
   				FROM 	temp_chatHistory_calc;
        
              		SELECT 	SUM(IFNULL(IsAbandoned, 0))
              		INTO 	v_PrevAbandonedCount 
              		FROM	temp_callDurationHistory
              		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp and IsAbandoned=1;
              			 
            
                      
              		SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
              		SET v_PrevAnsweredCount 	= CASE WHEN v_PrevAnsweredCount = 0 then null else v_PrevAnsweredCount end;
              		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
              			
              		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
              		,	v_DiffAnsweredPercent	= (v_CurrentAnsweredCount - v_PrevAnsweredCount) / v_PrevAnsweredCount * 100
              		,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100;    
              	 
                   	SELECT * FROM temp_AllagentId_dtl;
                      
                      SELECT 	IFNULL(v_CurTotalCount,0) 		AS 'TotalCount',
                   			IFNULL(v_DiffTotalPercent,0) 		AS 'DiffTotalPercent',
                   			IFNULL(v_CurrentAnsweredCount,0) 	AS 'CurrentAnsweredeCount',
                   			IFNULL(v_DiffAnsweredPercent,0) 	AS 'DiffAnsweredPercent',
                   			IFNULL(v_CurrentAbandonedCount,0) 	AS 'CurrentAbandonedCount',
                   			IFNULL(v_DiffAbandonedPercent,0) 	AS 'DiffAbandonedPercent';	
                                    
     				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_final; 
              		CREATE TEMPORARY TABLE temp_chatHistory_calc_final as           
                    SELECT
                    CDH.AgentId,
     				U.UserName 																										AS agentName,
     				COUNT(1) 																										AS Inboundcalls,
     				SUM(CASE WHEN CDH.dispositionId IS NOT NULL THEN 1 ELSE 0 END) 													AS AnsweredCalls,
     				SUM(Abandoned)  																								AS abandonedCalls,
     				SUM(IsMissedCall) 																								AS missedCalls,
                    sum(istransfered)																								AS transferredCalls,
     				
     				SUM(callDuration) 																								AS Talktime,
     				IFNULL(SUM(callDuration) / NULLIF(COUNT(1), 0), 0) 																AS avgCallDuration,
     				IFNULL(SUM(answeredDuration) / NULLIF(answeredCall, 0), 0) 														AS avgSpeedofAnswer,
     				IFNULL(SUM(CDH.totalTalktime + CDH.callHoldTime + (CDH.afterCallWorkTime * 1000)) / NULLIF(SUM(CASE WHEN CDH.answeredCall > 0 THEN 1 ELSE 0 END), 0) / 1000, 0) AS averageHandleTime,
     				IFNULL(MAX(CDH.totalTalktime + CDH.callHoldTime + (CDH.afterCallWorkTime * 1000)) / NULLIF(SUM(CASE WHEN CDH.answeredCall > 0 THEN 1 ELSE 0 END), 0), 0) AS maximumHandleTime,
     				SUM(CDH.afterCallWorkTime) 																						AS ACWTime,
     				IFNULL(SUM(CDH.callHoldTime) / NULLIF(SUM(CASE WHEN CDH.answeredCall > 0 THEN 1 ELSE 0 END), 0) / 1000, 0) 		AS averageHoldTime,
     				IFNULL(SUM(CDH.totalTalktime) / NULLIF(SUM(CDH.availableTime), 0) * 100, 0) 									AS occupancyrate,
     				SUM(CDH.FirstCallResolution) 																					AS FirstCallResolution,
     				SUM(CDH.SentimentalScore) 																						AS customersatisfaction
     				FROM temp_chatHistory_calc CDH
                     JOIN temp_AllagentId_dtl U ON CDH.AgentId = U.UserID
     				WHERE sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp
     				GROUP BY U.UserName,CDH.answeredCall,CDH.AgentId;
                             
                             
     		select  sum(Inboundcalls), sum(AnsweredCalls), sum(abandonedCalls), sum(missedCalls), sum(transferredCalls), sum(Talktime), sum(avgCallDuration), sum(avgSpeedofAnswer), 
     		sum(averageHandleTime), sum(maximumHandleTime), sum(ACWTime),sum( averageHoldTime), sum(occupancyrate), sum(FirstCallResolution), sum(customersatisfaction)
     		INTO
     		v_Inboundcalls,v_AnsweredCalls,v_abandonedCalls,v_missedCalls,v_transferredCalls,v_Talktime 				
     		,v_avgCallDuration,v_avgSpeedofAnswer,v_averageHandleTime,v_maximumHandleTime,v_ACWTime,v_averageHoldTime 		
     		,v_occupancyrate,v_FirstCallResolution ,v_customersatisfaction
     		from temp_chatHistory_calc_final  ;
                             
                
        		  SELECT 
        			'All Agents' 																									    			AS agentName,
        			IFNULL(v_Inboundcalls, 0) 																										AS Inboundcalls,
        			IFNULL(v_AnsweredCalls, 0) 				    																					AS AnsweredCalls,
        			IFNULL(v_abandonedCalls, 0) 																									AS abandonedCalls,
        			IFNULL(v_missedCalls, 0) 																										AS missedCalls,
        			IFNULL(v_transferredCalls, 0) 																									AS transferredCalls,
        			IFNULL(v_Talktime, 0) 																											AS Talktime,
        			IFNULL(v_avgCallDuration, 0) 																									AS avgCallDuration,
        			IFNULL((v_avgSpeedofAnswer),0)																									AS avgSpeedofAnswer,
        			IFNULL(v_averageHandleTime,0)  																									AS AverageHandleTime,
        			IFNULL(v_maximumHandleTime, 0)  																								AS maximumHandleTime,
        			IFNULL(v_ACWTime, 0) 																											AS ACWTime,
                 IFNull(v_averageHoldTime,0)																										AS averageHoldTime,
        			IFNULL(v_occupancyrate, 0) 																    									AS occupancyrate,
        			IFNULL(v_FirstCallResolution, 0)  																								AS FirstCallResolution,
        			IFNULL(v_customersatisfaction, 0) 																								AS customersatisfaction
        		UNION ALL
        		SELECT
  			distinct(U.UserName) 								  							AS	    agentName,
  			sum(Inboundcalls)									    						AS		Inboundcalls,
  			sum(AnsweredCalls)																AS		AnsweredCalls,
  			sum(abandonedCalls)																AS		abandonedCalls,
  			sum(missedCalls)																AS		missedCalls,
  			sum(transferredCalls) 															AS		transferredCalls, 
  			sum(Talktime) 																	AS		Talktime, 
  			sum(avgCallDuration)															AS		avgCallDuration,
  			sum(avgSpeedofAnswer)															AS		avgSpeedofAnswer,
  			sum(AverageHandleTime)															AS		AverageHandleTime,
  			sum(maximumHandleTime) 															AS		maximumHandleTime, 
  			sum(ACWTime) 																	AS		ACWTime, 
  			sum(averageHoldTime) 															AS		averageHoldTime, 
  			sum(occupancyrate) 																AS		occupancyrate, 
  			sum(FirstCallResolution)														AS		FirstCallResolution, 
  			sum(customersatisfaction)														AS		customersatisfaction
        		FROM     	temp_chatHistory_calc_final 
        		JOIN     	temp_AllagentId_dtl U ON AgentId = U.UserID
        	
        		 GROUP BY    U.UserName;
        End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Agent_Inboundchat_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Agent_Inboundchat_analysis_metrics_filter`(
  p_startTmpstmp 		BIGINT,
  p_endTmpstmp 			BIGINT,
  p_domainId 			INT,    	
  p_agentId				VARCHAR(250),		
  p_offset 				INT,
  p_Limit 				INT	)
sp_return:BEGIN
     	DECLARE v_offset 							INT;	  	
     	DECLARE v_CurrentStartTmpstmp 				BIGINT;
     	DECLARE v_CurrentEndTmpstmp 				BIGINT;
     	DECLARE v_PrevStartTmpstmp 					BIGINT;
     	DECLARE v_PrevEndTmpstmp 					BIGINT; 
     	DECLARE v_TmpstmpInterval					BIGINT;	
  					
     	DECLARE v_CurTotalCount 					INT;        
     	DECLARE v_PrevTotalCount 					INT;                    
     	DECLARE	v_DiffTotalPercent 					INT;    
  					
    	DECLARE v_PrevRespondedCount				INT;	
    	DECLARE v_CurrentRespondedCount				INT;	        
		DECLARE v_DiffRespondedPercent				INT;
  					
    	DECLARE v_PrevAbandonedCount				INT;	
    	DECLARE v_CurrentAbandonedCount				INT;
    	DECLARE v_DiffAbandonedPercent				INT;  	    
  				
    	DECLARE v_CurrentMissedCount				INT;
		DECLARE v_CurrentTransferredCount			INT;
     	DECLARE v_TotalChatDuration					BIGINT;
     
     
     
         	
  	DECLARE		v_agentName  			 			BIGINT;
  	DECLARE		v_receivedChat           			BIGINT;
  	DECLARE		v_respondedChat          			BIGINT;
  	DECLARE		v_abandonedChat          			BIGINT; 
  	DECLARE		v_missedChat             			BIGINT;	
  	DECLARE		v_transferredChat        			BIGINT;
  	
  	DECLARE		v_avgChatDuration		 			BIGINT;
  	DECLARE		v_customerMsgCount       			BIGINT;
  	DECLARE		v_agentMsgCount          			BIGINT;
      DECLARE	    v_totalMsgCount          			BIGINT;        
          
          
          
          
       	SET v_offset =  p_Limit * p_offset; 
         
     	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
     	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
         	
       	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       
       	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
       	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
         		
     	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
                           
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
      	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
      	CREATE TEMPORARY TABLE temp_AllagentId
      	SELECT 	UserID,UserName 
      	FROM 	tb_User 
      	WHERE 	domainId = p_domainId; 
   
   		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
      		CREATE TEMPORARY TABLE temp_AvailableDisposition 
      		(   DispositionId 			INT
      			,DispositionStatus 		VARCHAR(100)
      			,DispositionCategory	TINYINT
      		); 
              
      		INSERT INTO temp_AvailableDisposition 
      		SELECT 	did 			DispositionId
      			,	dispositionName	DispositionStatus
      			,	CASE WHEN dispositionName = 'Caller Disconnected'	THEN 2
      				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
      				WHEN dispositionName = 'Discarded' THEN 4
      				END 			DispositionCategory
      		FROM 	disposition_status
      		WHERE 	domainId	= p_domainId;
   
                       
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
     	DROP TEMPORARY TABLE IF EXISTS temp_chatDurationHistory; 
     	CREATE TEMPORARY TABLE temp_chatDurationHistory AS
     	SELECT 	CH.sessionStartTime		
     		,	CH.ChatHistoryId        
     		,	CDH.ChatDurationHistoryId
     		,	CDH.AgentId
     		,	CDH.IsMissed
			
   	        ,	CASE WHEN t_D.DispositionCategory = 2 THEN 1 ELSE 0 END 		AS IsAbandoned	         
     
     		,	CDH.Istransferred
     		,	CDH.dispositionId
     	
          ,    (CDH.Duration/1000)												AS chatDuration
          ,  CDH.afterChatWorkTime
     		,	CM.customerMsgCount
     		,	CM.agentMsgCount
     	FROM 		tb_ChatHistory 			CH
     	 JOIN 	tb_ChatDurationHistory	CDH	    ON CH.ChatHistoryId 		= CDH.ChatHistoryId
     	LEFT JOIN 	tb_ChatMessage			CM		ON CM.ChatDurationHistoryId	= CDH.ChatDurationHistoryId
     	LEFT JOIN 	temp_agentIDs 			t_A     ON CDH.AgentId				= t_A.agentId   
   	    LEFT JOIN temp_AvailableDisposition	t_D	    ON CDH.dispositionId	    = t_D.DispositionId      
     	WHERE 	CH.domainId 			= p_domainId 		
     	AND 	CH.IsInBound			= 1
     	AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
     	AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
             
       	DROP TEMPORARY TABLE IF EXISTS temp_PrevChatHistory; 
     	CREATE TEMPORARY TABLE temp_PrevChatHistory as
       	SELECT 	DISTINCT ChatHistoryId 
       	FROM 	temp_chatDurationHistory
       	WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
             
     	DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
     	CREATE TEMPORARY TABLE temp_CurChatHistory AS
       	SELECT 	DISTINCT ChatHistoryId 
       	FROM 	temp_chatDurationHistory
       	WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;   
         
         	ALTER TABLE temp_PrevChatHistory ADD COLUMN isResponded	TINYINT;
       	ALTER TABLE temp_CurChatHistory ADD COLUMN isResponded	TINYINT;
         
         	UPDATE 	temp_PrevChatHistory CH
         	JOIN	temp_chatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
         	AND 	CDH.dispositionId IS NOT NULL 
         	SET 	CH.isResponded = 1;
             
         	UPDATE 	temp_CurChatHistory CH
         	JOIN	temp_chatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
         	AND 	CDH.dispositionId IS NOT NULL 
         	SET 	CH.isResponded = 1;
             	
         	SELECT 	COUNT(ChatHistoryId), SUM(isResponded)
         	INTO 	v_PrevTotalCount , v_PrevRespondedCount 
       	FROM	temp_PrevChatHistory;
           
         	SELECT 	COUNT(ChatHistoryId), SUM(isResponded)
         	INTO 	v_curTotalCount , v_CurrentRespondedCount 
       	FROM	temp_CurChatHistory;    
             
           SELECT SUM(IsMissed), SUM(Istransferred), SUM(chatDuration), SUM(customerMsgCount), SUM(agentMsgCount)
           INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_TotalChatDuration, v_customerMsgCount, v_agentMsgCount
           FROM 	temp_chatDurationHistory;
             
       	SELECT 	SUM(IFNULL(IsAbandoned, 0))
       	INTO 	v_PrevAbandonedCount 
       	FROM	temp_chatDurationHistory
       	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
             
       	SELECT 	SUM(IFNULL(IsAbandoned, 0))
       	INTO 	v_CurrentAbandonedCount 
           FROM	temp_chatDurationHistory
       	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;    
            
       	SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount        end;
       	SET v_PrevRespondedCount 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
       	SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
            
         	SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
         	,	v_DiffRespondedPercent	= (v_CurrentRespondedCount - v_PrevRespondedCount) / v_PrevRespondedCount * 100
         	,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100;    
             
         	SELECT * FROM temp_AllagentId;
             
         	SELECT 	IFNULL(v_CurTotalCount,0) 										AS 'TotalCount',
         			IFNULL(v_DiffTotalPercent,0) 									AS 'DiffTotalPercent',
         			IFNULL(v_CurrentRespondedCount,0) 								AS 'CurrentResponseCount',
         			IFNULL(v_DiffRespondedPercent,0) 								AS 'DiffResponsePercent',
         			IFNULL(v_CurrentAbandonedCount,0) 								AS 'CurrentAbandonedCount',
         			IFNULL(v_DiffAbandonedPercent,0) 								AS 'DiffAbandonedPercent';	
                  
          
          
  		DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal; 
  		CREATE TEMPORARY TABLE temp_ChatHistory_cal as
       	SELECT 	U.UserName																			AS agentName
       		,	COUNT(1)																			AS receivedChat
       		,	SUM(CASE WHEN CDH.dispositionId IS NOT NULL  THEN 1 ELSE 0 END)						AS respondedChat
             ,  sum(case when IsAbandoned =1 then 1 else 0 end )									AS abandonedChat
              
               ,	SUM(IsMissed)																	AS missedChat
               ,	SUM(Istransferred)																AS transferredChat
               ,	SUM(chatDuration+afterChatWorkTime)												AS totalChatDuration
               ,	SUM(chatDuration+afterChatWorkTime) / COUNT(1)									AS avgChatDuration
               ,	SUM(customerMsgCount)															AS customerMsgCount
               ,	SUM(agentMsgCount)																AS agentMsgCount
               ,	SUM(customerMsgCount) + SUM(agentMsgCount)										AS totalMsgCount
           FROM 	temp_chatDurationHistory 	CDH
           JOIN 	temp_AllagentId				U	ON CDH.AgentId	= U.UserID	
           WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
           GROUP BY U.UserName;       
           
  		 SELECT  SUM(receivedChat), SUM(respondedChat), SUM(abandonedChat), SUM(missedChat),
           SUM(transferredChat), SUM(totalChatDuration), SUM(avgChatDuration), SUM(customerMsgCount), SUM(agentMsgCount), SUM(totalMsgCount) 
           INTO
            v_receivedChat, v_respondedChat, v_abandonedChat, v_missedChat, 
           v_transferredChat, v_totalChatDuration, v_avgChatDuration, v_customerMsgCount, v_agentMsgCount, v_totalMsgCount
           FROM temp_ChatHistory_cal ;      
            
           
     	 select 
           'All Agents'															  AS agentName,		
           v_receivedChat       												  AS receivedChat,
           v_respondedChat                                                        AS respondedChat,
           v_abandonedChat                                                        AS abandonedChat,
           IFNULL(v_missedChat,0)                                                 AS missedChat,
           IFNULL(v_transferredChat,0)                                            AS transferredChat,
           v_totalChatDuration                                                    AS totalChatDuration,
           v_avgChatDuration	                                                    AS avgChatDuration,
           v_customerMsgCount                                                     AS customerMsgCount,
           v_agentMsgCount                                                        AS agentMsgCount,
           v_totalMsgCount                                                        AS totalMsgCount
            UNION ALL
            select
            DISTINCT(agentName)													  AS agentName,	
            sum(receivedChat)                                                     AS receivedChat,
            sum(respondedChat)                                                    AS respondedChat,
            sum(abandonedChat)                                                    AS abandonedChat,
            IFNULL(sum(missedChat),0)                                             AS missedChat,
            IFNULL(sum(transferredChat),0)                                        AS transferredChat,
            sum(totalChatDuration)                                                AS totalChatDuration,
            sum(avgChatDuration)                                                  AS avgChatDuration,
            sum(customerMsgCount)                                                 AS customerMsgCount,
            sum(agentMsgCount)                                                    AS agentMsgCount,
            sum(totalMsgCount)                                                    AS totalMsgCount
            from
            temp_ChatHistory_cal
            group by agentName;
            
            
     	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Agent_Inboundchat_analysis_metrics_filter_1` */;
