CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_analyticsBotInteraction`(
  p_startTmpstmp 	BIGINT,
  p_endTmpstmp 		BIGINT,
  p_domainId 		INT
)
BEGIN
  	DECLARE v_StartTmpstmp 		BIGINT;
  	DECLARE v_EndTmpstmp 		BIGINT;
    DECLARE v_Abandoned			INT;
    
  	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_EndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_EndTmpstmp = p_endTmpstmp; END IF;  		
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    SELECT  `status`	INTO v_Abandoned
    FROM 	disposition_status 
    WHERE 	domainId		= p_domainId
    AND 	dispositionName LIKE 'Caller Disconnected'
    AND 	type			= 'Default';
    
    DROP TEMPORARY TABLE IF EXISTS tmp_botInteraction;
    CREATE TEMPORARY TABLE tmp_botInteraction
    SELECT 	CASE WHEN DH.EndTime IS NULL THEN 1 ELSE 0 END	AS activeSession
		, 	DH.Istransferred
		, 	DH.IsAbandoned
        ,	CASE WHEN DH.dispositionId IS NOT NULL THEN 1 ELSE 0 END AS handledSession
    FROM 	tb_ChatHistory			H
    JOIN 	tb_ChatDurationHistory	DH	ON DH.ChatHistoryId = H.ChatHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1;
    
    INSERT INTO tmp_botInteraction
    SELECT 	CASE WHEN DH.EndTime IS NULL THEN 1 ELSE 0 END						AS activeSession
		, 	CASE WHEN DH.transferredTypeId > 0 THEN 1 ELSE 0 END				AS Istransferred
		, 	CASE WHEN DH.agentDispositionId = v_Abandoned THEN 1 ELSE 0 END 	AS IsAbandoned
        ,	CASE WHEN DH.agentDispositionId <> v_Abandoned THEN 1 ELSE 0 END 	AS handledSession
    FROM 	tb_CallHistory			H
    JOIN 	tb_CallDurationHistory	DH	ON DH.CallHistoryId = H.CallHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1;  
    
    INSERT INTO tmp_botInteraction
    SELECT 	CASE WHEN H.sessionEndTime IS NULL THEN 1 ELSE 0 END				AS activeSession
		, 	H.Istransferred														AS Istransferred
		, 	CASE WHEN H.dispositionId = v_Abandoned THEN 1 ELSE 0 END 			AS IsAbandoned
        ,	CASE WHEN H.dispositionId <> v_Abandoned THEN 1 ELSE 0 END 			AS handledSession
    FROM 	tb_SMSHistory			H
    JOIN 	tb_SMSDurationHistory	DH	ON DH.SMSHistoryId = H.SMSHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1;      

    INSERT INTO tmp_botInteraction
    SELECT 	CASE WHEN H.sessionEndTime IS NULL THEN 1 ELSE 0 END				AS activeSession
		, 	H.Istransferred														AS Istransferred
		, 	CASE WHEN H.dispositionId = v_Abandoned THEN 1 ELSE 0 END 			AS IsAbandoned
        ,	CASE WHEN H.dispositionId <> v_Abandoned THEN 1 ELSE 0 END 			AS handledSession
    FROM 	tb_EmailHistory			H
    JOIN 	tb_EmailDurationHistory	DH	ON DH.EmailHistoryId = H.EmailHistoryId
    WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1;      
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    SELECT 	SUM(activeSession) 						AS activeSession
		,	SUM(Istransferred) / COUNT(1) * 100 	AS handOverRate
        ,	SUM(handledSession) / COUNT(1) * 100 	AS handledRate
        ,	SUM(IsAbandoned) / COUNT(1) * 100 		AS abandonmentRate
    FROM 	tmp_botInteraction;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_analyticsBotInteractionChannel` */;
