CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_assign_ticket_to_user`(
 	p_TicketId 			BIGINT,
 	p_AssignedToGroupId	BIGINT,
 	p_AssignToUserId	BIGINT,
 	p_AssignByUserId	BIGINT
 )
BEGIN	
     UPDATE 	tb_TicketDetails
     SET 	AssignedToGroupId	= p_AssignedToGroupId	
 		,	AssignedToAgentId	= p_AssignToUserId	
 		,	AssignedBy			= p_AssignByUserId
         ,	UpdatedBy			= p_AssignByUserId
 		,	UpdatedDate        	= NOW()
     WHERE 	TicketId 			= p_TicketId;
 END ;;
DELIMITER ;
