CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_AutoAssignAgentToEmail`(	
	p_EmailHistoryId	BIGINT
    ,p_domainId			INT
    ,p_ext				VARCHAR(200)
)
BEGIN
	DECLARE v_CurDate					DATE;
	DECLARE v_CurDateTime				DATETIME;
	DECLARE v_CurDateTimestamp			BIGINT;
	DECLARE v_UserId					BIGINT;
	DECLARE v_ext						INT;
	DECLARE	v_EmailDurationHistoryId	BIGINT;
	DECLARE v_errCode					TINYINT	DEFAULT -1;
	DECLARE v_errMsg					VARCHAR(250) DEFAULT 'User not available';          

	SET v_CurDateTimestamp = unix_timestamp(NOW())*1000;
	SET v_CurDateTime	= NOW();
    
  IF p_ext IS NOT NULL
    THEN
		
        
        SELECT UserId INTO v_UserId
        FROM tb_User 
        WHERE ext = p_ext
        AND domainId = p_domainId;
        
		IF v_UserId IS NOT NULL 
		THEN
			UPDATE 	tb_EmailHistory	
			SET 	assignedBy		= -1
				,	assignedTo		= v_UserId
				,	assignedOn		= v_CurDateTimestamp
			WHERE 	EmailHistoryId 	= p_EmailHistoryId;
            
            UPDATE 	tb_User
            SET 	AssignedTime 	= NOW()
            WHERE 	UserId			= v_UserId;
			  
			SELECT 	EmailDurationHistoryId	INTO v_EmailDurationHistoryId   
			FROM 	tb_EmailDurationHistory
			WHERE 	EmailHistoryId 	= p_EmailHistoryId
			AND 	AgentId			IS NULL 
			AND 	IsBot			= 0;       
			  
			IF v_EmailDurationHistoryId IS NOT NULL
			THEN
				UPDATE 	tb_EmailDurationHistory
				SET 	AgentId		= v_UserId
				,		UpdatedAt	= v_CurDateTime
				WHERE 	EmailDurationHistoryId = v_EmailDurationHistoryId;
			ELSE
				INSERT INTO tb_EmailDurationHistory
				(	EmailHistoryId
					, AgentId        
					, IsBot
					, CreatedAt
					, UpdatedAt
				)
				VALUES
				(	p_EmailHistoryId
					, v_UserId
					, 0
					, v_CurDateTime
					, v_CurDateTime
				);            
			END IF;        
	  
			SET v_errCode 	= 0;
			SET v_errMsg	= 'Assigned User Successfully';
			END IF;
       END IF; 
       
       SELECT p_domainId AS 'domainId',p_ext AS ext, v_errCode AS 'errCode', v_errMsg	AS 'errMsg';
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_AutoAssignAgentToFacebook` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_AutoAssignAgentToFacebook`(	
  	p_FacebookHistoryId		BIGINT
 	,p_domainId				INT
	,p_ext					VARCHAR(200)
     )
BEGIN	
 	DECLARE v_CurDateTime				DATETIME;
 	DECLARE v_CurDateTimestamp			BIGINT;
 	DECLARE v_UserId					BIGINT;
 	DECLARE v_ext						INT;
 	DECLARE v_FacebookDurationHistoryId	BIGINT;
 	DECLARE v_errCode					TINYINT	DEFAULT -1;
 	DECLARE v_errMsg					VARCHAR(250) DEFAULT 'User not available';    
       
 	SET v_CurDateTimestamp = unix_timestamp(NOW())*1000;
 	SET v_CurDateTime	= NOW();
   
     IF p_ext IS NOT NULL
     THEN
 		CALL Split(p_ext,','); 
 		
 		DROP TEMPORARY TABLE IF EXISTS temp_Ext;
 		CREATE TEMPORARY TABLE temp_Ext(Ext	INT);
 		
 		INSERT INTO temp_Ext(Ext)
 		SELECT * FROM tt_Split_temptable;    
 		
 		SELECT 	UserId, U.ext
 		INTO 	v_UserId, v_ext
 		FROM 	temp_Ext 		t_E
 		JOIN 	tb_User			U	ON 	t_E.Ext 	= U.ext
 									AND U.domainId	= p_domainId
 		JOIN 	agent_status	A_S	ON 	U.StatusID	= A_S.aid
 		WHERE 	A_S.statusName	= 'Ready'
 		AND 	U.roleid		= 6  
         AND 	U.socialMedia	= 1
 		ORDER BY AssignedTime, stateTimer
 		LIMIT 1; 
         
 		IF v_UserId IS NOT NULL 
 		THEN
 			UPDATE 	tb_FacebookHistory	
 			SET 	assignedBy			= -1
 				,	assignedTo			= v_UserId
 				,	assignedOn			= v_CurDateTimestamp
 			WHERE 	FacebookHistoryId 	= p_FacebookHistoryId;
             
			UPDATE 	tb_User
			SET 	AssignedTime 	= NOW()
			WHERE 	UserId			= v_UserId;            

 			SELECT 	FacebookDurationHistoryId	INTO v_FacebookDurationHistoryId   
 			FROM 	tb_FacebookDurationHistory
 			WHERE 	FacebookHistoryId 	= p_FacebookHistoryId
 			AND 	AgentId				IS NULL 
 			AND 	IsBot				= 0;       
 
 			IF v_FacebookDurationHistoryId IS NOT NULL
 			THEN
 				UPDATE 	tb_FacebookDurationHistory
 				SET 	AgentId		= v_UserId
 				,		UpdatedAt	= v_CurDateTime
 				WHERE 	FacebookDurationHistoryId = v_FacebookDurationHistoryId;            
 			ELSE
 				INSERT INTO tb_FacebookDurationHistory
 				(	FacebookHistoryId
 					, AgentId        
 					, IsBot
 					, CreatedAt
 					, UpdatedAt
 				)
 				VALUES
 				(	p_FacebookHistoryId
 					, v_UserId
 					, 0
 					, v_CurDateTime
 					, v_CurDateTime
 				);            
 			END IF;        
 				
 			SET v_errCode 	= 0;
 			SET v_errMsg	= 'Assigned User Successfully';
 		END IF; 
 	END IF; 
        
 	SELECT p_domainId AS 'domainId',v_ext AS ext, v_errCode AS 'errCode', v_errMsg	AS 'errMsg';
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
