/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_AutoAssignAgentToInstagram`(	
   	p_InstagramHistoryId		BIGINT
  	,p_domainId				INT
 	,p_ext					VARCHAR(200)
      )
BEGIN	
  	DECLARE v_CurDateTime				DATETIME;
  	DECLARE v_CurDateTimestamp			BIGINT;
  	DECLARE v_UserId					BIGINT;
  	DECLARE v_ext						INT;
  	DECLARE v_InstagramDurationHistoryId	BIGINT;
  	DECLARE v_errCode					TINYINT	DEFAULT -1;
  	DECLARE v_errMsg					VARCHAR(250) DEFAULT 'User not available';    
        
  	SET v_CurDateTimestamp = unix_timestamp(NOW())*1000;
  	SET v_CurDateTime	= NOW();
    
      IF p_ext IS NOT NULL
      THEN
  		CALL Split(p_ext,','); 
  		
  		DROP TEMPORARY TABLE IF EXISTS temp_Ext;
  		CREATE TEMPORARY TABLE temp_Ext(Ext	INT);
  		
  		INSERT INTO temp_Ext(Ext)
  		SELECT * FROM tt_Split_temptable;    
  		
  		SELECT 	UserId, U.ext
  		INTO 	v_UserId, v_ext
  		FROM 	temp_Ext 		t_E
  		JOIN 	tb_User			U	ON 	t_E.Ext 	= U.ext
  									AND U.domainId	= p_domainId
  		JOIN 	agent_status	A_S	ON 	U.StatusID	= A_S.aid
  		WHERE 	A_S.statusName	= 'Ready'
  		AND 	U.roleid		= 6  
          AND 	U.socialMedia	= 1
  		ORDER BY AssignedTime, stateTimer
  		LIMIT 1; 
          
  		IF v_UserId IS NOT NULL 
  		THEN
  			UPDATE 	tb_InstagramHistory	
  			SET 	assignedBy			= -1
  				,	assignedTo			= v_UserId
  				,	assignedOn			= v_CurDateTimestamp
                ,	AgentId				= v_UserId
                ,	IsBot				= 0
                ,	UpdatedAt			= v_CurDateTime
  			WHERE 	InstagramHistoryId 	= p_InstagramHistoryId;
              
 			UPDATE 	tb_User
 			SET 	AssignedTime 	= NOW()
 			WHERE 	UserId			= v_UserId;            
  				
  			SET v_errCode 	= 0;
  			SET v_errMsg	= 'Assigned User Successfully';
  		END IF; 
  	END IF; 
         
  	SELECT p_domainId AS 'domainId',v_ext AS ext, v_errCode AS 'errCode', v_errMsg	AS 'errMsg';
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_AutoAssignAgentToSMS` */;
