CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_AutoAssignAgentToSMS`(	
	p_SMSHistoryId		BIGINT
   	,p_domainId			INT
	,p_ext				VARCHAR(200)
   )
BEGIN 	
 	DECLARE v_CurDateTime				DATETIME;
 	DECLARE v_CurDateTimestamp			BIGINT;
 	DECLARE v_UserId					BIGINT;
 	DECLARE v_ext						INT;
 	DECLARE	v_SMSDurationHistoryId		BIGINT;
 	DECLARE v_errCode					TINYINT	DEFAULT -1;
 	DECLARE v_errMsg					VARCHAR(250) DEFAULT 'User not available';           
 	
 	SET v_CurDateTimestamp = unix_timestamp(NOW())*1000;
 	SET v_CurDateTime	= NOW();
       
    IF p_ext IS NOT NULL
    THEN
	
       
        SELECT UserId INTO v_UserId
        FROM tb_User 
        WHERE ext = p_ext
        AND domainId = p_domainId;
        
		IF v_UserId IS NOT NULL 
		THEN
			UPDATE 	tb_SMSHistory	
			SET 	assignedBy		= -1
				,	assignedTo		= v_UserId
				,	assignedOn		= v_CurDateTimestamp
			WHERE 	SMSHistoryId 	= p_SMSHistoryId;
            
			UPDATE 	tb_User
            SET 	AssignedTime 	= NOW()
            WHERE 	UserId			= v_UserId;
			  
			SELECT 	SMSDurationHistoryId	INTO v_SMSDurationHistoryId   
			FROM 	tb_SMSDurationHistory
			WHERE 	SMSHistoryId 	= p_SMSHistoryId
			AND 	AgentId			IS NULL 
			AND 	IsBot			= 0;   
	  
			IF v_SMSDurationHistoryId IS NOT NULL
			THEN
				UPDATE 	tb_SMSDurationHistory
				  SET 	AgentId		= v_UserId
				  ,		UpdatedAt	= v_CurDateTime
				  WHERE SMSDurationHistoryId = v_SMSDurationHistoryId;
			ELSE
				INSERT INTO tb_SMSDurationHistory
				  (	SMSHistoryId
					, AgentId        
					  , IsBot
					  , CreatedAt
					  , UpdatedAt
				  )
				  VALUES
				  (	p_SMSHistoryId
					, v_UserId
					  , 0
					, v_CurDateTime
					  , v_CurDateTime
				  );            
			  END IF;             
			   
			   SET v_errCode 	= 0;
			SET v_errMsg	= 'Assigned User Successfully';
		   END IF;
       END IF;
       SELECT p_domainId AS 'domainId',p_ext AS ext,v_errCode AS 'errCode', v_errMsg	AS 'errMsg';
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
