/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_BotTransaferToCallQueue`(	p_ContactCenterNo	BIGINT
	,p_IntentName		VARCHAR(150)
)
BEGIN
  	DECLARE v_domainId		INT;
	DECLARE v_queueId		INT;    
    
    SELECT 	queueId
    INTO 	v_queueId
    FROM 	tb_mapIntentQueue
    WHERE 	contactCenterNumber = p_ContactCenterNo
    AND 	intents	like concat('%',p_IntentName,'%');
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    IF v_queueId IS NULL
    THEN
		SELECT 	domainId
		INTO 	v_domainId
		FROM 	did_purchase 
		WHERE 	your_number = p_ContactCenterNo;      
		
		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;
		CREATE TEMPORARY TABLE temp_queueIds
		SELECT 	qid 
			,	A_S.statusName
		FROM 	tb_User 					U	    
		JOIN 	agent_status				A_S ON 	U.StatusID				= A_S.aid
												AND A_S.statusName 			<> 'Offline'		
		JOIN 	routingqueueprofilemapping 	RP	ON 	U.routing_profile_id	= RP.rqmid    
		WHERE 	U.domainId 	= v_domainId
		AND 	U.isActive	= 1
		LIMIT 	1;
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
		  
		SELECT 	qid INTO v_queueId
		FROM 	temp_queueIds
		WHERE 	statusName = 'Ready'
		LIMIT 1;
	  
		IF v_queueId IS NULL
		THEN
			SELECT 	qid INTO v_queueId
			FROM 	temp_queueIds		
			LIMIT 1;
		END IF; 
 	END IF; 
     SELECT JSON_OBJECT("action", 1, "value", v_queueId) AS jsoncol;
  	
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_call_agent_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_call_agent_servicelevel_analysis_metrics_filter`(
  	p_startTmpstmp 		BIGINT,
  	p_endTmpstmp 		BIGINT,
  	p_domainId 			INT,
  	p_agentId 			TEXT,
  	p_offset 			INT,
  	p_Limit 		    INT	
  )
sp_return:begin
          
  			DECLARE v_offset 					INT;	  	
  			DECLARE v_CurrentStartTmpstmp 		BIGINT;
  			DECLARE v_CurrentEndTmpstmp 		BIGINT;
  			DECLARE v_PrevStartTmpstmp 			BIGINT;
  			DECLARE v_PrevEndTmpstmp 			BIGINT; 
  			DECLARE v_TmpstmpInterval			BIGINT;	
  
  			DECLARE v_CurTotalCount 			INT;
  			DECLARE  v_PrevTotalCount 			INT;
  			DECLARE v_DiffTotalPercent 			INT;     
  
  			DECLARE  v_CurTotalSLA              INT; 
  			DECLARE  v_PrevTotalSLA             INT; 
  			DECLARE  v_DiffTotalSLAPercent      INT; 
  
  			DECLARE v_PretotalDurationCount     INT;
  			DECLARE v_CurrenttotalDurationCount INT;  
  
  			DECLARE  v_CurTotalSLA1             INT; 
  			DECLARE  v_PrevTotalSLA1            INT; 
  			DECLARE  v_DiffTotalSLA1Percent     INT; 
  
  			DECLARE  v_CurMissedCalls           INT; 
  			DECLARE  v_PrevMissedCalls          INT; 
  			DECLARE  v_DiffMissedChatsPercent   INT; 
  
  			DECLARE  v_CurSLA1               	INT; 
  			DECLARE  v_PrevSLA1              	INT; 
  			DECLARE  v_DiffSLA1Percent       	INT; 
  
  			DECLARE  v_CurSLA2               	INT; 
  			DECLARE  v_PrevSLA2              	INT; 
  			DECLARE  v_DiffSLA2Percent       	INT;  
  
  			DECLARE  v_CurSLA3               	INT; 
  			DECLARE  v_PrevSLA3              	INT; 
  			DECLARE  v_DiffSLA3Percent       	INT;  
  
  			DECLARE  v_CurSLA4               	INT; 
  			DECLARE  v_PrevSLA4              	INT; 
  			DECLARE  v_DiffSLA4Percent       	INT;  
  
  			DECLARE  v_CurSLA5               	INT; 
  			DECLARE  v_PrevSLA5              	INT; 
  			DECLARE  v_DiffSLA5Percent       	INT;    
  
  			DECLARE  v_CurSLA6               	INT; 
  			DECLARE  v_PrevSLA6              	INT; 
  			DECLARE  v_DiffSLA6Percent       	INT; 
  
  			DECLARE  v_CuransweredSLACount      INT; 
  			DECLARE  v_PrevansweredSLACount     INT; 
  			DECLARE  v_DiffansweredSLAPercent   INT; 
  
  			DECLARE  v_CurabandonedSLACount     INT; 
  			DECLARE  v_PrevabandonedSLACount    INT; 
  			DECLARE  v_DiffabandonedSLAPercent  INT; 
  
  			DECLARE  v_CurSLAbreachedCount      INT; 
  			DECLARE  v_PrevSLAbreachedCount     INT; 
  			DECLARE  v_DiffSLAbreachedPercent   INT; 
  
  			DECLARE  v_CurCallTypeCount         INT; 
  			DECLARE  v_PrevCallTypeCount        INT; 
  			DECLARE  v_DiffCallTypePercent      INT;  
  
  			DECLARE  v_CurOverdueCount                 	INT;   
              
  			SET p_startTmpstmp = UNIX_TIMESTAMP(DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(p_startTmpstmp/1000),'+00:00','+05:30'),'%Y-%m-%d %H:%i:%s'))*1000;
              SET p_endTmpstmp = UNIX_TIMESTAMP(DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(p_endTmpstmp/1000),'+00:00','+05:30'),'%Y-%m-%d %H:%i:%s'))*1000;
  
  			SET v_offset =  p_Limit * p_offset; 
            
            	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
            	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
            	
          	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
  			DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
  			CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
  			DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
  			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
      
  			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
  			CREATE TEMPORARY TABLE temp_AvailableDisposition 
  			(    DispositionId 			INT
  			,DispositionStatus 		VARCHAR(100)
  			,DispositionCategory	TINYINT
  			); 
                                
  			INSERT INTO temp_AvailableDisposition 
  			SELECT 	did 			DispositionId
  			,	dispositionName	DispositionStatus
  			,	CASE WHEN dispositionName = 'Opened'	THEN 2
  					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
  					WHEN dispositionName = 'Disconnected'         THEN 4
  					WHEN dispositionName = 'Resolved'             THEN 5 END 			DispositionCategory
  			FROM 	disposition_status
  			WHERE 	domainId	= p_domainId
              AND 	dispositionName	<> 'Caller Disconnected';         
                              
            	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
  			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  			CREATE TEMPORARY TABLE temp_AllagentId
  			SELECT 	UserID,UserName 
  			FROM 	tb_User 
  			WHERE 	domainId 	= p_domainId; 
                             
  			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory; 
  			CREATE TEMPORARY TABLE temp_CallHistory AS 	    	
  			SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE)				AS SessionDate
  				,	U.UserID															AS agentID
  				,	U.UserName															AS agentName     
  				,	SH.CallHistoryId
                  ,	SDH.CallDurationHistoryId
  				,	SH.sessionStartTime
  				,	SDH.Duration														AS callDuration
  				,	SDH.Duration												      	AS Duration
  				,	SDH.IsMissedCall                                                  	AS IsMissedCall
  				,	SH.IsAbandoned		                                            	AS IsAbandoned
                  ,	IFNULL(SDH.answeredDuration,0)										AS answeredDuration
                  ,	SDH.UMNStatus
  			FROM 	tb_CallHistory 				SH
  			JOIN 	tb_CallDurationHistory		SDH	ON SH.CallHistoryId 	= SDH.CallHistoryId     
  			LEFT JOIN 	tb_User					U	ON SDH.AgentId			= U.UserID  
  			LEFT JOIN 	temp_agentIDs 			t_A ON SDH.AgentId		    = t_A.agentId  
  			LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
  			LEFT JOIN 	disposition_status		DS	ON DS.did			    = SDH.dispositionId AND DS.domainId = SH.domainId
  			WHERE 	SH.domainId 		= p_domainId	
              AND 	SDH.IsBot 			= 0
              AND 	SDH.AgentId IS NOT NULL
  			AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
  			AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
   
  				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc;   
  				CREATE TEMPORARY TABLE temp_CallHistory_calc AS 	     
  				SELECT a.SessionDate AS `Date`,
  						a.agentID,
  						a.agentName,
  						a.CallHistoryId,
                          a.CallDurationHistoryId,
  						a.sessionStartTime,
  						SUM(CASE WHEN a.IsMissedCall = 0 AND a.IsAbandoned = 0 AND a.UMNStatus = 1 THEN 1 ELSE 0 END)	AS Answered,
  						SUM(CASE WHEN a.IsAbandoned = 1 THEN 1 ELSE 0 END)												AS Abandoned,
  						SUM(CASE WHEN a.IsMissedCall = 1 AND a.IsAbandoned = 0 THEN 1 ELSE 0 END) 						AS IsMissedCall,
  						
  						
  						SUM(a.Duration) 																				AS totalDuration,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 1 AND 5 THEN 1 ELSE 0 END) 							AS SL1,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 6 AND 10 THEN 1 ELSE 0 END) 							AS SL2,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 11 AND 15 THEN 1 ELSE 0 END) 							AS SL3,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 16 AND 20 THEN 1 ELSE 0 END) 							AS SL4,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 21 AND 25 THEN 1 ELSE 0 END) 							AS SL5,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 26 AND 30 THEN 1 ELSE 0 END) 							AS SL6,
  						SUM(CASE WHEN a.answeredDuration BETWEEN 1 AND 30 THEN 1 ELSE 0 END) 							AS TotalSLA
  				FROM temp_CallHistory a
  				GROUP BY a.SessionDate,a.agentID,a.agentName,a.CallHistoryId,a.CallDurationHistoryId,a.sessionStartTime; 
                           
  				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc1; 
  				CREATE TEMPORARY TABLE temp_CallHistory_calc1 AS 	     
  				SELECT 	
  					a.Date 				       										                                                       
  					,a.agentID
  					,a.agentName														
  					,(a.Answered+a.Abandoned)                                                                                                            AS CallType
  					,a.CallHistoryId 
                      ,a.CallDurationHistoryId
  					,a.sessionStartTime
  					,a.totalDuration
  					,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 													  AS TotalSLA1
  					,a.TotalSLA
  					,a.IsMissedCall       
  					,SUM(CASE WHEN (a.TotalSLA + a.IsMissedCall) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.IsMissedCall)) * 10 END)                    AS answeredSLA
  					,SUM(CASE WHEN (a.TotalSLA + a.IsMissedCall) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.IsMissedCall) * 100) END)                	AS abandonedSLA
  					,SUM(CASE WHEN (a.TotalSLA + a.IsMissedCall) = 0 THEN 1 ELSE (a.IsMissedCall / (a.TotalSLA + a.IsMissedCall)) * 100 END)             	AS SLAbreached
  				FROM temp_CallHistory_calc    a 
  				GROUP BY a.Date,a.agentID,a.agentName,a.sessionStartTime,a.CallHistoryId,a.CallDurationHistoryId,a.totalDuration,a.TotalSLA,a.IsMissedCall,a.Answered,a.Abandoned ;  
                               
              
  			SELECT  COUNT(CallDurationHistoryId),	SUM(TotalSLA1), SUM(IsMissedCall),sum(CallType)              														                     				 
  			INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedCalls,v_CurCallTypeCount                           														                      					
  			FROM 	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
     
  			SELECT 	COUNT(CallDurationHistoryId),SUM(TotalSLA1), SUM(IsMissedCall),sum(CallType)                       																								 
  			INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedCalls,v_PrevCallTypeCount                                 														 										
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
  
  			SELECT 	SUM(IFNULL(answeredSLA, 0))
  			INTO 	v_PrevansweredSLACount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
  			SELECT 	SUM(IFNULL(answeredSLA, 0))
  			INTO 	v_CuransweredSLACount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
  
  			SELECT 	SUM(IFNULL(abandonedSLA, 0))
  			INTO 	v_PrevabandonedSLACount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
  
  			SELECT 	SUM(IFNULL(abandonedSLA, 0))
  			INTO 	v_CurabandonedSLACount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
       
  			SELECT 	SUM(IFNULL(SLAbreached, 0))
  			INTO 	v_PrevSLAbreachedCount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
  
  			SELECT 	SUM(IFNULL(SLAbreached, 0))
  			INTO 	v_CurSLAbreachedCount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
  
  			SELECT 	SUM(IFNULL(SLAbreached, 0))
  			INTO 	v_PrevSLAbreachedCount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
  
  			SELECT 	SUM(IFNULL(SLAbreached, 0))
  			INTO 	v_CurSLAbreachedCount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
  
  			SELECT 	SUM(IFNULL(totalDuration, 0))
  			INTO 	v_CurrenttotalDurationCount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
  
  			SELECT 	SUM(IFNULL(totalDuration, 0))
  			INTO 	v_PretotalDurationCount 
  			FROM	temp_CallHistory_calc1
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
  
  			SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
  			INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
  			FROM 	temp_CallHistory_calc
  			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
  
  			SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
  			INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
  			FROM	temp_CallHistory_calc
  			WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     	SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end; 
    	SET v_PrevansweredSLACount 	= CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
     	SET v_PrevabandonedSLACount	= CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
    	SET v_PrevSLAbreachedCount 	= CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
        
       SET v_DiffTotalPercent			= (v_CurTotalCount - v_PrevTotalCount) / IF(v_PrevTotalCount=0,1,v_PrevTotalCount) * 100  
    	,  v_DiffansweredSLAPercent		= (v_CuransweredSLACount- v_PrevansweredSLACount ) / IF(IFNULL(v_PrevansweredSLACount,0)=0,1,v_PrevansweredSLACount)  * 100
   	,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / IF(IFNULL(v_PrevabandonedSLACount,0)=0,1,v_PrevabandonedSLACount)   * 100
    	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / IF(IFNULL(v_PrevSLAbreachedCount,0)=0,1,v_PrevSLAbreachedCount) * 100; 
     
       	SELECT * FROM temp_AllagentId;
           
  			SELECT 
                IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
                IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
                IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';
                
  		SELECT
  				'All Agents'													AS agentName
  			,	'Answered'														AS CallType
  			,	IFNULL(v_CurSLA1,0)                                          	AS SL1
  			,	IFNULL(v_CurSLA2,0)                                          	AS SL2
  			,	IFNULL(v_CurSLA3,0)                                          	AS SL3
  			,	IFNULL(v_CurSLA4,0)                                          	AS SL4
  			,	IFNULL(v_CurSLA5,0)                                          	AS SL5
  			,	IFNULL(v_CurSLA6,0)                                          	AS SL6
  			,	IFNULL(v_CurTotalSLA,0)                                      	AS TotalSLA
  			,	IFNULL(v_CurMissedCalls,0)                                   	AS MissedCalls
              ,	ROUND(IFNULL((v_CurTotalSLA)/(IF(ifnull(v_curTotalCount,0)=0,1,v_curTotalCount)),0),2)			AS SLAAchieved
              ,	ROUND((100 - IFNULL((v_CurTotalSLA)/(IF(ifnull(v_curTotalCount,0)=0,1,v_curTotalCount)),0)),2) AS SLAbreached
  		UNION ALL
  		SELECT 	U.UserName													                                    AS agentName
  			,   CASE WHEN   b.IsMissedCall = 1 AND b.Abandoned = 1  THEN 'Abandoned' ELSE 'Answered'  END     	AS CallType   
  			,	sum(b.SL1)
  			,	sum(b.SL2)
  			,	sum(b.SL3)
  			,	sum(b.SL4)
  			,	sum(b.SL5)
  			,	sum(b.SL6)
  			,   sum(b.TotalSLA)
  			,   sum(b.IsMissedCall)
              ,  	CASE WHEN sum(b.TotalSLA)/COUNT(1) IS NOT NULL THEN ROUND(sum(b.TotalSLA)/COUNT(1),2) ELSE '-' END		AS SLAachieved
  			, 	(100 - CASE WHEN sum(b.TotalSLA)/COUNT(1) IS NOT NULL THEN ROUND(sum(b.TotalSLA)/COUNT(1),2) ELSE '-' END)	AS SLAbreached 
  		FROM temp_CallHistory_calc b
          JOIN 	temp_AllagentId		U	   ON b.agentID	= U.UserID
  		 WHERE 	b.sessionStartTime    	   BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
  		GROUP BY U.UserName,b.Abandoned,b.Answered,b.IsMissedCall;    
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Call_Queue_Servicelevel_Analysis_Metrics_Filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Call_Queue_Servicelevel_Analysis_Metrics_Filter`(
 	p_startTmpstmp 		BIGINT,
 	p_endTmpstmp 		BIGINT,
 	p_domainId 			INT,
 	p_queueId 			TEXT,
 	p_offset 			INT,
 	p_Limit 		    INT	
  )
SP :BEGIN           
 	DECLARE v_offset 					INT;	  	
 	DECLARE v_CurrentStartTmpstmp 		BIGINT;
 	DECLARE v_CurrentEndTmpstmp 		BIGINT;
 	DECLARE v_PrevStartTmpstmp 			BIGINT;
 	DECLARE v_PrevEndTmpstmp 			BIGINT; 
 	DECLARE v_TmpstmpInterval			BIGINT;	
 
 	DECLARE v_CurTotalCount 			INT;        
 	DECLARE v_PrevTotalCount 			INT;                     
 
 	DECLARE  v_CurTotalSLA              INT; 
 	DECLARE  v_PrevTotalSLA             INT; 
 
 	DECLARE  v_CurMissedCalls           INT; 
    
 	DECLARE  v_CurSLA1               	INT; 
 	DECLARE  v_CurSLA2               	INT; 
 	DECLARE  v_CurSLA3               	INT; 
 	DECLARE  v_CurSLA4               	INT; 
 	DECLARE  v_CurSLA5               	INT; 
 	DECLARE  v_CurSLA6               	INT; 

 	DECLARE  v_DiffansweredSLAPercent    INT; 
 
 	DECLARE  v_CurabandonedSLACount      INT; 
 	DECLARE  v_PrevabandonedSLACount     INT; 
 	DECLARE  v_DiffabandonedSLAPercent   INT; 
 
 	DECLARE  v_CurSLAbreachedCount       INT; 
 	DECLARE  v_PrevSLAbreachedCount      INT; 
 	DECLARE  v_DiffSLAbreachedPercent    INT; 
                       
 	SET v_offset =  p_Limit * p_offset; 
 
  	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
  	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  								
 
 	SET v_CurrentStartTmpstmp 	= UNIX_TIMESTAMP(DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(v_CurrentStartTmpstmp/1000),'+00:00','+05:30'),'%Y-%m-%d %H:%i:%s')) * 1000;
     SET v_CurrentEndTmpstmp 	= UNIX_TIMESTAMP(DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(v_CurrentEndTmpstmp/1000),'+00:00','+05:30'),'%Y-%m-%d %H:%i:%s')) * 1000;
                 
 	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
    
 	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1000;
 	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;            
              		
 	DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
 	CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
 	   
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
 	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
 	CREATE TEMPORARY TABLE temp_AllqueueId(queueId	INT, `name`	VARCHAR(255));
     
     IF IFNULL(p_queueId,'') = ''
     THEN    
 		INSERT INTO temp_AllqueueId
 		SELECT qid, name AS queueName FROM queue WHERE domainId = p_domainId;
 	ELSE
 		INSERT INTO temp_AllqueueId
 		SELECT 	qid, name AS queueName 
         FROM 	queue 			Q
         JOIN 	temp_queueIds	t_Q	ON t_Q.queueId = Q.qid	
         WHERE 	Q.domainId = p_domainId;    
     END IF;
 	
 	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);  
   
 	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
 	CREATE TEMPORARY TABLE temp_AvailableDisposition 
 	(    DispositionId 			INT
 		,DispositionStatus 		VARCHAR(100)
 		,DispositionCategory	TINYINT
 	); 
 			 
 	INSERT INTO temp_AvailableDisposition 
 	SELECT 	did 			DispositionId
 		,	dispositionName	DispositionStatus
 		,	CASE 	WHEN dispositionName = 'Opened'	THEN 2
 					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
 					WHEN dispositionName = 'Disconnected'         THEN 4
 					WHEN dispositionName = 'Resolved'             THEN 5 END 		AS DispositionCategory
 	FROM 	disposition_status
 	WHERE 	domainId	= p_domainId;   
 					  
 	DROP TEMPORARY TABLE IF EXISTS temp_CallHistory; 
 	CREATE TEMPORARY TABLE temp_CallHistory AS 	    	
 	SELECT	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		           AS SessionDate
 		,  	CASE WHEN SDH.IsMissedCall = 1 AND SH.IsAbandoned = 1  THEN 'Answered' ELSE 'Abandoned'  END	AS CallType   
 		,	SDH.queueId                                                            AS queueId
 		,	t_A.`name`													      	   AS queueName     
 		,	SH.CallHistoryId
 		,	SH.sessionStartTime
 		,	IFNULL(SDH.answeredDuration,0)										   AS answeredDuration   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 0  AND 30 	THEN 1 ELSE 0 END	AS SLA   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 0  AND 5 	THEN 1 ELSE 0 END	AS SLA1   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 6  AND 10 	THEN 1 ELSE 0 END	AS SLA2   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 11 AND 15 	THEN 1 ELSE 0 END	AS SLA3   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 16 AND 20 	THEN 1 ELSE 0 END	AS SLA4   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 21 AND 25 	THEN 1 ELSE 0 END	AS SLA5   
         ,	CASE WHEN SDH.answeredDuration BETWEEN 26 AND 30 	THEN 1 ELSE 0 END	AS SLA6          
         ,	CASE WHEN IFNULL(SDH.answeredDuration,31) > 30 		THEN 1 ELSE 0 END	AS SLA_Breached          
 		,	SDH.Duration												      	   AS Duration
 		,	SDH.IsMissedCall                                                       AS IsMissedCall
 		,	SH.IsAbandoned		                                                   AS IsAbandoned
         ,	CASE WHEN SDH.IsMissedCall = 0 AND SH.IsAbandoned = 0 AND SDH.UMNStatus = 1 THEN 1 ELSE 0 END AS AnsweredCall
 	FROM 	tb_CallHistory 				SH
 	JOIN 	tb_CallDurationHistory		SDH	ON SH.CallHistoryId 	= SDH.CallHistoryId     
 	JOIN 	temp_AllqueueId 			t_A ON SDH.queueId		    = t_A.queueId  
 	LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
 	LEFT JOIN disposition_status		DS	ON DS.did			    = SDH.dispositionId AND DS.domainId = SH.domainId
 	WHERE 	SH.domainId 		= p_domainId		
 	AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp;  
     
 	DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_Prev; 
 	CREATE TEMPORARY TABLE temp_CallHistory_Prev AS 	    
     SELECT 	CH.*
     FROM 	temp_CallHistory CH
     WHERE 	CH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;  
     
 	DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_Cur; 
 	CREATE TEMPORARY TABLE temp_CallHistory_Cur AS 	    
     SELECT 	CH.*
     FROM 	temp_CallHistory CH
     WHERE 	CH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;          	
 
     SELECT 	COUNT(1), SUM(SLA), SUM(IsAbandoned), SUM(SLA_Breached)		
 	INTO 	v_PrevTotalCount, v_PrevTotalSLA, v_PrevabandonedSLACount, v_PrevSLAbreachedCount		
     FROM 	temp_CallHistory_Prev;            
        
     SELECT 	COUNT(1), SUM(SLA), SUM(IsAbandoned), SUM(SLA_Breached), SUM(IsMissedCall)
 		, 	SUM(SLA1), SUM(SLA2), SUM(SLA3), SUM(SLA4), SUM(SLA5), SUM(SLA6)                 
 	INTO 	v_CurTotalCount, v_CurTotalSLA, v_CurabandonedSLACount,	v_CurSLAbreachedCount, v_CurMissedCalls
 		,	v_CurSLA1, v_CurSLA2 , v_CurSLA3, v_CurSLA4, v_CurSLA5, v_CurSLA6        
     FROM 	temp_CallHistory_Cur;         
 	
     SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 THEN NULL ELSE v_PrevTotalCount END;
 	SET v_PrevTotalSLA 			= CASE WHEN v_PrevTotalSLA = 0 THEN NULL ELSE v_PrevTotalSLA END;
 	SET v_PrevabandonedSLACount	= CASE WHEN v_PrevabandonedSLACount = 0 THEN NULL ELSE v_PrevabandonedSLACount END;
 	SET v_PrevSLAbreachedCount 	= CASE WHEN v_PrevSLAbreachedCount = 0 THEN NULL ELSE v_PrevSLAbreachedCount END;         
 
 	SET v_DiffansweredSLAPercent  	= (v_CurTotalSLA- v_PrevTotalSLA ) / v_PrevTotalSLA  * 100
 	,  	v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
 	,  	v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100;       
       
 	SELECT queueId	AS qid
 		, 	name	AS queueName 
 	FROM temp_AllqueueId;
 
 	SELECT 	IFNULL(v_CurTotalSLA,0)          		 AS 'CurrentAnsweredSLACount'
 		,	IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent'
 		,	IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount'
 		,	IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent'
 		,	IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount'
 		,	IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';
         
         
     SELECT 'All Queue'												   	AS queueName
 		,'Answered'                                                   	AS CallType
 		,IFNULL(v_CurSLA1,0)                                          	AS SL1
 		,IFNULL(v_CurSLA2,0)                                          	AS SL2
 		,IFNULL(v_CurSLA3,0)                                          	AS SL3
 		,IFNULL(v_CurSLA4,0)                                          	AS SL4
 		,IFNULL(v_CurSLA5,0)                                          	AS SL5
 		,IFNULL(v_CurSLA6,0)                                          	AS SL6
 		,IFNULL(v_CurTotalSLA,0)                                      	AS TotalSLA
 		,IFNULL(v_CurMissedCalls,0)                                   	AS MissedCalls
 		,ROUND(IFNULL((v_CurTotalSLA)/(IF(IFNULL(v_curTotalCount,0)=0,1,v_curTotalCount)),0),2)			AS SLAAchieved
 		,ROUND((100 - IFNULL((v_CurTotalSLA)/(IF(ifnull(v_curTotalCount,0)=0,1,v_curTotalCount)),0)),2) AS SLAbreached
 	UNION ALL
 	SELECT 	t_CH.queueName		
 		 ,  t_CH.CallType
 		 ,	SUM(t_CH.SLA1)
 		 ,	SUM(t_CH.SLA2)
 		 ,	SUM(t_CH.SLA3)
 		 ,	SUM(t_CH.SLA4)
 		 ,	SUM(t_CH.SLA5)
 		 ,	SUM(t_CH.SLA6)
 		 ,  SUM(t_CH.SLA)
 		 ,  SUM(t_CH.IsMissedCall)
         ,  	CASE WHEN SUM(t_CH.SLA)/COUNT(1) IS NOT NULL THEN ROUND(SUM(t_CH.SLA)/COUNT(1),2) ELSE '-' END			AS SLAachieved
 		, 	(100 - CASE WHEN SUM(t_CH.SLA)/COUNT(1) IS NOT NULL THEN ROUND(SUM(t_CH.SLA)/COUNT(1),2) ELSE '-' END)	AS SLAbreached          
 	FROM temp_CallHistory_Cur t_CH	 
 	GROUP BY t_CH.queueName, t_CH.CallType;       
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Call_register_details` */;
