CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Call_register_details`(
  
  p_ext 			INT,
  p_domainId 		INT,
  p_domainName 	VARCHAR(100),
  p_callerId 		VARCHAR(150),
  p_deviceType 	VARCHAR(50),
  p_deviceToken	VARCHAR(250),
  p_authToken	TEXT
  )
begin
  	
      DECLARE existingId INT;
      DECLARE v_errcode  INT;
      DECLARE v_errmsg   VARCHAR(50);
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      SELECT crid INTO existingId
      FROM tb_CallRegisterDetails
      WHERE ext = p_ext  AND deviceType = p_deviceType;
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      IF existingId IS NOT NULL THEN
          
          UPDATE tb_CallRegisterDetails
          SET 
              
              
  			domainId  = ifnull(p_domainId,domainId),
  			domainName = ifnull(p_domainName,domainName),
  			callerId  = ifnull(p_callerId,callerId),
  			
  			deviceToken = ifnull(p_deviceToken,deviceToken),
            authToken = ifnull(p_authToken,authToken)
              where crid = existingId;
              
  		 IF row_count() >0 then
   			set v_errcode=0;
   			set v_errmsg='Success : Updated';
  	end if;
      
      ELSE 
      
      INSERT INTO tb_CallRegisterDetails (
               ext 		
  			,domainId 	
  			,domainName 
  			,callerId 	
  			,deviceType 
  			,deviceToken
            ,authToken
          )
          VALUES (
  			 p_ext 		
  			,p_domainId 	
  			,p_domainName 
  			,p_callerId 	
  			,p_deviceType 
  			,p_deviceToken
			,authToken
          );
          
          IF row_count()>0
          THEN
          SET v_errcode = 0;
          SET v_errmsg  = 'Success : Inserted';
          END IF;
          
      END IF;
      
      SELECT v_errcode as errcode , v_errmsg as errmsg ; 
      
  end ;;
DELIMITER ;
