CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_CategoryArticleCount`(	
	 p_domainId		INT
    ,p_knowledgeBaseType INT 
    )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	web_id
 		, 	websiteId
 		, 	websiteUrl
 		, 	baseName
 		, 	discription        
 		,	(	SELECT 	COUNT(ChatCategoryId)  
  				FROM 	tb_ChatCategory 
  				WHERE 	web_id = WS.web_id )	AS CategoryCount
  		,	(	SELECT 	COUNT(ChatArticleId)	
  				FROM 	tb_ChatArticle 
  				WHERE 	web_id = WS.web_id)		AS ArticlesCount
 		,	CompanyType
        , `language`
        , customerWebsiteUrl
        , agentWebsiteUrl
        , TypeCodeName AS knowledgeBaseType
      FROM 	websiteScraper WS
      LEFT JOIN TypeCode TC ON WS.knowledgeBaseMainType = TC.TypeCodeID
      WHERE 	domainId = p_domainId
      AND (IFNULL(p_knowledgeBaseType,0) = 0 OR WS.knowledgeBaseMainType = p_knowledgeBaseType);	
      
      SELECT TypeCodeName AS knowledgeBaseName,COUNT(*) AS knowledgeBaseCount
      FROM 	websiteScraper WS
      JOIN TypeCode TC ON WS.knowledgeBaseMainType = TC.TypeCodeID
      WHERE domainId = p_domainId
      GROUP BY TypeCodeName;
      
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      
  END ;;
DELIMITER ;
