BEGIN
	SELECT 	web_id
		, 	websiteId
        , 	websiteUrl
        , 	baseName
        , 	discription        
		,	(	SELECT 	COUNT(ChatCategoryId)  
				FROM 	tb_ChatCategory 
				WHERE 	web_id = WS.web_id )		AS CategoryCount
		,	(	SELECT 	ChatCategoryId 
				FROM 	tb_ChatCategory 
