		,	(	SELECT 	ChatArticleId	
				FROM 	tb_ChatArticle 
				WHERE 	web_id = WS.web_id)			AS ChatArticleId
    FROM 	websiteScraper WS
    WHERE 	domainId = p_domainId;	
END ;;
