CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_CategoryArticleDetails`(
  p_web_id		INT
 ,p_domainId		INT
 )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 
	WITH ChatCategoryWithCounts AS (
    SELECT 
        b.ChatCategoryId,
        b.CategoryName,
        b.CategoryDescription,
        COUNT(CA.ChatArticleId) AS fileCount,
        b.knowledgeBaseType
    FROM         tb_ChatCategory b
    LEFT JOIN    tb_ChatArticle CA ON CA.ChatCategoryId = b.ChatCategoryId
    WHERE b.web_id = p_web_id
	AND b.domainId = p_domainId
    GROUP BY b.ChatCategoryId, b.CategoryName, b.CategoryDescription
)
SELECT 
    JSON_ARRAYAGG(
        JSON_OBJECT(
            "ChatCategoryId", ChatCategoryId,
            "CategoryName", CategoryName,
            "CategoryDescription", CategoryDescription,
            "fileCount", fileCount,
            "knowledgeBaseType",knowledgeBaseType
        )
    ) AS ChatCategory
FROM 
    ChatCategoryWithCounts;


                 
 			SELECT 	 JSON_ARRAYAGG(JSON_OBJECT("ChatArticleId",a.ChatArticleId
 											,"FilePath",a.FilePath
                                             ,"ArticleLanguage",a.ArticleLanguage
                                             ,"knowledgeBaseType",a.knowledgeBaseType))  		as ChatArticle
                                             
 				FROM 	tb_ChatArticle 	a 
 				WHERE 	a.web_id 		= p_web_id
                 AND		a.domainId 		= p_domainId
                 AND a.ChatCategoryId IS NULL;	
 				 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                 
                 
 END ;;
DELIMITER ;
