CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasDeleteInternalChatMsg`(
  p_internalChatId		BIGINT 
  ,p_domainId			INT
  ,p_agentId				BIGINT	 
  )
BEGIN
  	DECLARE v_curDate	DATETIME DEFAULT NOW();
   	DECLARE v_errCode	SMALLINT DEFAULT -1;
   	DECLARE v_errMsg	VARCHAR(150) DEFAULT 'Delete internal chat message failed';
  
	DELETE FROM tb_internalChatParticipant
    WHERE internalChatId = p_internalChatId;
    
 	DELETE FROM tb_internalChat 
	WHERE internalChatId = p_internalChatId;


  
  	SET v_errCode  	= 1
  	,	v_errMsg	= 'Internal chat message deleted successfully';
  	
  	SELECT v_errCode AS errCode, v_errMsg AS errMsg;     
  END ;;
DELIMITER ;
