CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasGetCustomerContactFields`(	
p_domainId		INT
)
BEGIN
	DECLARE v_fieldId	INT;
	DECLARE v_curDate	DATETIME DEFAULT NOW();
    
    DROP TEMPORARY TABLE IF EXISTS temp_customerContactFields;
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    CREATE TEMPORARY TABLE temp_customerContactFields
	SELECT 	fieldName
		,	fieldType
		,	isCustomField
		,	isMandatory
		,	isDisplayable
		,	isUniqueValue
        ,	TabId
    FROM 	tb_customerContactFields
    WHERE 	domainId = p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
    
	IF NOT EXISTS (SELECT 1 FROM temp_customerContactFields LIMIT 1)
    THEN
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
		INSERT 	INTO temp_customerContactFields(fieldName, fieldType, isCustomField, isMandatory, isDisplayable, isUniqueValue,TabId)        
		SELECT 	COLUMN_NAME, DATA_TYPE, 0, 0, 1, 0
			,	CASE 	WHEN COLUMN_NAME IN ('address','country','city','location','postalCode','state') THEN 2
						WHEN COLUMN_NAME IN ('email','facebook','instagram','twitter','whatsapp') THEN 3
                        ELSE 1
                END
        FROM 	information_schema.columns 
        WHERE 	TABLE_SCHEMA 	= database() 
        AND 	TABLE_NAME 		= 'customer_contact';
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
        
        INSERT 	INTO tb_customerContactFields(fieldName, fieldType, isCustomField, isMandatory, isDisplayable, isUniqueValue,TabId,domainId,createdAt,updatedAt)        
        SELECT 	fieldName, fieldType, isCustomField, isMandatory, isDisplayable, isUniqueValue,TabId,p_domainId,v_curDate,v_curDate
		FROM 	temp_customerContactFields;        
    END IF;
    
    SELECT * FROM temp_customerContactFields;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
