/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasGetInternalChat`(	
   	p_internalChatGroupId	BIGINT 
   	,p_domainId				INT
 	,p_agentId				BIGINT	
   )
BEGIN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
         DROP TEMPORARY TABLE IF EXISTS tmp_internalChat;
         CREATE TEMPORARY TABLE tmp_internalChat
 		SELECT 	C.internalChatId
 			, 	C.internalChatGroupId
 			, 	C.domainId
 			, 	C.msg
 			, 	C.sendTimestamp
 			,	CP_S.agentId 		AS senderId
 			,	U.UserName			AS senderName
 			,	(SELECT GROUP_CONCAT(InCP.agentId) FROM tb_internalChatParticipant InCP WHERE InCP.internalChatId = C.internalChatId) AS agentIds         
             ,	1					AS isAllRead
       FROM 	tb_internalChat 			C
       JOIN 	tb_internalChatParticipant 	CP 		ON 	CP.internalChatId 	= C.internalChatId
       JOIN 	tb_internalChatParticipant 	CP_S 	ON  CP_S.internalChatId	= C.internalChatId 
													AND CP_S.isSender		= 1
 	  JOIN 	tb_User							U		ON	U.UserID			= CP_S.agentId
													AND U.domainId			= p_domainId
       WHERE C.internalChatGroupId	= p_internalChatGroupId
       AND	CP.agentId				= p_agentId
       AND 	C.domainId				= p_domainId;
       
       UPDATE 	tmp_internalChat			t_C
       JOIN 	tb_internalChatParticipant	CP	ON 	t_C.internalChatId	= CP.internalChatId
 												AND CP.msgStatus		<> 2
       SET 		isAllRead = 0;
       
       SELECT * FROM tmp_internalChat;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaasGetInternalChatGroupList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaasGetInternalChatGroupList`(	
             p_domainId		INT
             ,p_agentId		BIGINT
             )
BEGIN
     	DECLARE v_startDate	datetime default DATE_SUB(NOW(), INTERVAL 31 DAY);    
         
 		DROP TEMPORARY TABLE IF EXISTS tmp_internalChat;
 		CREATE TEMPORARY TABLE tmp_internalChat
 		(	internalChatGroupId		BIGINT
 			,groupName				VARCHAR(100)
 			,customerId				BIGINT
 			,queueId				INT	
 			,agentIds				VARCHAR(500)
 			,channelTypeId			INT			
 			,isGroupClosed			TINYINT 
 			,groupCreatedTimestamp	BIGINT
 			,directNumber			bigint
 			,internalChatId			BIGINT                
 			,sendTimestamp			BIGINT
 			
 			,msgStatus				TINYINT
 			,SlNo					INT
 			,updatedAtGroup			DATETIME            
 		);
                 
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
 		INSERT INTO tmp_internalChat
 		(	internalChatGroupId, groupName, customerId, queueId, agentIds
 			, channelTypeId, isGroupClosed, groupCreatedTimestamp, internalChatId, sendTimestamp, msgStatus
 			, SlNo, updatedAtGroup,directNumber)
 		WITH CTE_internalChat AS 
 		(	SELECT 	CG.internalChatGroupId, CASE WHEN CG.hostAgent = p_agentId THEN CG.groupName ELSE U.UserName END AS groupName, CG.customerId, CG.queueId, CONCAT(CG.hostAgent,',',CG.agentIds)	agentIds
 				,	CG.channelTypeId, CG.isClosed, CG.createdTimestamp, C.internalChatId, C.sendTimestamp, CP.msgStatus				
 				,  	ROW_NUMBER() OVER (PARTITION BY CG.internalChatGroupId ORDER BY C.internalChatId DESC) SlNo, CG.updatedAt
 				, 	CASE WHEN CG.hostAgent = p_agentId THEN Null ELSE U.directNumber END AS directNumber
 			FROM 	tb_internalChatGroup		CG
 			JOIN 	tb_internalChat				C	ON CG.internalChatGroupId	= C.internalChatGroupId
 			JOIN 	tb_internalChatParticipant	CP	ON C.internalChatId			= CP.internalChatId
 			JOIN 	tb_User						U	ON U.UserID					= CG.hostAgent	
 			WHERE 	CG.domainId	= p_domainId 
 			AND 	CP.agentId	= p_agentId
 			AND 	CG.updatedAt > v_startDate)
 		SELECT 	internalChatGroupId, groupName, customerId, queueId, agentIds, channelTypeId, isClosed, createdTimestamp, internalChatId, sendTimestamp
 			, 	2 AS msgStatus, SlNo, updatedAt, directNumber
 		FROM 	CTE_internalChat
 		WHERE 	SlNo = 1;
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
          
  		DROP TEMPORARY TABLE IF EXISTS tmp_sendChat;
  		CREATE TEMPORARY TABLE tmp_sendChat
  		SELECT 	t_IC.internalChatGroupId
  			,	C.internalChatId
  		FROM 	tmp_internalChat 			t_IC
  		JOIN 	tb_internalChat				C		ON t_IC.internalChatGroupId	= C.internalChatGroupId
  		JOIN	tb_internalChatParticipant	CP		ON C.internalChatId			= CP.internalChatId
  		WHERE 	CP.agentId	= p_agentId
  		AND 	CP.isSender	= 1;
             	
  		UPDATE 	tmp_internalChat			t_C
  		JOIN 	tb_internalChat				IC	ON t_C.internalChatGroupId	= IC.internalChatGroupId
  		JOIN 	tb_internalChatParticipant	ICP	ON ICP.internalChatId		= IC.internalChatId
  		SET 	t_C.msgStatus	= 0
  		WHERE	ICP.msgStatus 	= 0;
  
  		UPDATE 	tmp_internalChat			t_C
  		JOIN 	tb_internalChat				IC	ON t_C.internalChatGroupId	= IC.internalChatGroupId
  		JOIN 	tb_internalChatParticipant	ICP	ON ICP.internalChatId		= IC.internalChatId
  		SET 	t_C.msgStatus	= 1
  		WHERE	ICP.msgStatus 	= 1;        
           
 		DROP TEMPORARY TABLE IF EXISTS tmp_internalChat1;
 		CREATE TEMPORARY TABLE tmp_internalChat1
 		SELECT DISTINCT internalChatGroupId FROM tmp_internalChat;
                 
   		INSERT INTO tmp_internalChat(internalChatGroupId, groupName, customerId, queueId, agentIds, channelTypeId, isGroupClosed, groupCreatedTimestamp, updatedAtGroup, directNumber)
   		SELECT 	CG.internalChatGroupId, CG.groupName, CG.customerId, CG.queueId, CONCAT(CG.hostAgent,',',CG.agentIds)	agentIds
   				, CG.channelTypeId, CG.isClosed, CG.createdTimestamp, CG.updatedAt, U.directNumber
   		FROM 	tb_internalChatGroup 	CG
          JOIN 	tb_User					U	ON U.UserID					= CG.hostAgent	
   		LEFT JOIN tmp_internalChat1		T_C	ON CG.internalChatGroupId 	= T_C.internalChatGroupId                
   		WHERE 	CG.domainId				= p_domainId 
   		AND 	CG.agentIds				LIKE CONCAT('%',p_agentId,'%')
   		AND    	T_C.internalChatGroupId IS NULL
   		AND 	CG.updatedAt 			> v_startDate;
                 
 		DROP TEMPORARY TABLE IF EXISTS tmp_internalChat1;
             	
             	
                     
 		SELECT 	T_C.internalChatGroupId	
 			,	T_C.groupName
 			,	T_C.customerId
 			,	JSON_ARRAY_INSERT(C_C.phoneNumber,'$[0]',C_C.primaryPhoneNumber) 		AS phoneNumber 
 			,	JSON_ARRAY_INSERT(C_C.email,'$[0]',C_C.primaryEmail) 					AS email 
 			,	CONCAT(IFNULL(CONCAT(C_C.firstName,' '),''),IFNULL(C_C.lastName,''))	AS customerName
 			,	CT.TypeCodeName															AS channelType
 			,	T_C.queueId																	
 			,	Q.`name`																AS queueName
 			,	T_C.agentIds
 			,	T_C.isGroupClosed
 			,	T_C.groupCreatedTimestamp
 			 ,	T_C.directNumber
 			,	T_C.internalChatId        
 			,	C.msg																	AS lastMsg
 			,	T_C.sendTimestamp
 			,	T_C.msgStatus	            
 			,	(	SELECT	COUNT(DISTINCT IN_C.internalChatId) 
 					FROM 	tb_internalChat 			IN_C 
 					JOIN 	tb_internalChatParticipant 	IN_CP 	ON 	IN_C.internalChatId			= IN_CP.internalChatId			
																AND	IN_CP.agentId				= p_agentId
 					 LEFT JOIN tmp_sendChat				t_SC	ON 	t_SC.internalChatGroupId	= IN_C.internalChatGroupId
 																AND	t_SC.internalChatId			= IN_C.internalChatId                                                                        
 					WHERE 	IN_C.internalChatGroupId = T_C.internalChatGroupId 
 					AND 	IN_CP.msgStatus IN (0,1)	 
 					AND 	IN_CP.isSender	= 0
 					AND 	t_SC.internalChatGroupId IS NULL) 		AS unreadCount 
 			,	CASE WHEN FIND_IN_SET(p_agentId,T_C.agentIds) = 0 THEN 1 ELSE 0 END		AS isAgentDeleted
 		FROM 	tmp_internalChat	T_C
 		JOIN 	customer_contact	C_C	ON T_C.customerId 		= C_C.coid 
 		LEFT JOIN 	queue			Q	ON T_C.queueId			= Q.qid 
 		JOIN 	TypeCode			CT	ON CT.TypeCodeID		= T_C.channelTypeId
 		LEFT JOIN tb_internalChat	C	ON T_C.internalChatId	= C.internalChatId
 		WHERE 	T_C.updatedAtGroup > v_startDate
 		ORDER BY T_C.sendTimestamp DESC, T_C.groupCreatedTimestamp DESC; 	
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaasGetInternalChatsForHistoryId` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaasGetInternalChatsForHistoryId`(
 p_historyId			INT
 ,p_channelTypeId		INT
 ,p_agentId				BIGINT	 
 ,p_domainId			INT 	
 )
BEGIN

 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  
    
		DROP TEMPORARY TABLE IF EXISTS tmp_sendChat;
  		CREATE TEMPORARY TABLE tmp_sendChat
  		SELECT 	CG.internalChatGroupId
  			,	C.internalChatId
  		FROM 	tb_internalChatGroup		CG
		JOIN 	tb_internalChat				C	ON CG.internalChatGroupId	= C.internalChatGroupId
  		JOIN	tb_internalChatParticipant	CP		ON C.internalChatId			= CP.internalChatId
  		WHERE 	CP.agentId	= p_agentId
  		AND 	CP.isSender	= 1;
        
    DROP TEMPORARY TABLE IF EXISTS tmp_internalChat;
	CREATE TEMPORARY TABLE tmp_internalChat
 	SELECT	CG.internalChatGroupId
 		,	C.internalChatId
 		,	C.msg
        ,	CP_S.agentId		AS senderId
		,	(SELECT GROUP_CONCAT(InCP.agentId) FROM tb_internalChatParticipant InCP WHERE InCP.internalChatId = C.internalChatId) AS agentIds  
        ,	1					AS isAllRead      
        ,	CG.groupName
        ,	CG.customerId
        
        ,	CG.queueId
        
        ,	C.sendTimestamp
        ,	CP.msgStatus
        ,	(	SELECT	COUNT(DISTINCT IN_C.internalChatId) 
 					FROM 	tb_internalChat 			IN_C 
 					JOIN 	tb_internalChatParticipant 	IN_CP 	ON 	IN_C.internalChatId			= IN_CP.internalChatId			
																AND	IN_CP.agentId				= p_agentId
 					LEFT JOIN tmp_sendChat				t_SC	ON 	t_SC.internalChatGroupId	= IN_C.internalChatGroupId
 																AND	t_SC.internalChatId			= IN_C.internalChatId                                                                     
 					WHERE 	IN_C.internalChatGroupId = CG.internalChatGroupId 
 					AND 	IN_CP.msgStatus IN (0,1)	 
 					AND 	IN_CP.isSender	= 0
 					AND 	t_SC.internalChatGroupId IS NULL) 		AS unreadCount 
		,	CG.createdTimestamp as groupCreatedTimestamp
        ,	CG.isClosed as isGroupClosed
        ,	JSON_ARRAY_INSERT(C_C.phoneNumber,'$[0]',C_C.primaryPhoneNumber) 		AS phoneNumber 
		,	JSON_ARRAY_INSERT(C_C.email,'$[0]',C_C.primaryEmail) 					AS email 
		,	CONCAT(IFNULL(CONCAT(C_C.firstName,' '),''),IFNULL(C_C.lastName,''))	AS customerName
		,	CT.TypeCodeName															AS channelType
        ,	Q.`name`																AS queueName
        ,	CASE WHEN FIND_IN_SET(p_agentId,CG.agentIds) = 0 THEN 1 ELSE 0 END		AS isAgentDeleted
     FROM 	tb_internalChatGroup		CG
     JOIN 	tb_internalChat				C		ON 	CG.historyId			= p_historyId
 												AND CG.channelTypeId		= p_channelTypeId
                                                AND	C.domainId				= p_domainId                                                
 												AND C.internalChatGroupId	= CG.internalChatGroupId
     JOIN 	tb_internalChatParticipant	CP		ON 	CP.internalChatId		= C.internalChatId												
 												AND CP.agentId				= p_agentId
	 JOIN 	tb_internalChatParticipant	CP_S	ON 	CP_S.internalChatId		= C.internalChatId
												AND CP_S.isSender			= 1
	 JOIN 	customer_contact	C_C				ON CG.customerId 			= C_C.coid 
     JOIN 	TypeCode			CT				ON CT.TypeCodeID			= CG.channelTypeId
     LEFT JOIN 	queue			Q				ON CG.queueId				= Q.qid; 
	
	UPDATE 	tmp_internalChat			t_C
	JOIN 	tb_internalChatParticipant	CP	ON 	t_C.internalChatId	= CP.internalChatId
											AND CP.msgStatus		<> 2
	SET 	t_C.isAllRead = 0;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
	SELECT * FROM tmp_internalChat;
 END ;;
DELIMITER ;
