CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasInsertInternalChat`(	
p_internalChatId		BIGINT 
,p_internalChatGroupId	INT
,p_domainId				INT
,p_msg					JSON    
,p_senderAgentId		BIGINT    
,p_agentIds				VARCHAR(1000)
 )
BEGIN
 	DECLARE v_curDate						DATETIME DEFAULT NOW();
	DECLARE v_internalChatId				INT;
	DECLARE v_internalChatParticipantId		BIGINT; 
	DECLARE v_JLength						INT;
	DECLARE v_errCode						SMALLINT DEFAULT -1;
	DECLARE v_errMsg						VARCHAR(150) DEFAULT 'Add internal chat failed';
     
 	CALL SplitWithSlNo(p_agentIds,',');
     
     DROP TEMPORARY TABLE IF EXISTS tmp_participants;    
     CREATE TEMPORARY TABLE tmp_participants
     (	agentId		INT
 		,isSender	TINYINT);
 
 	INSERT INTO tmp_participants
     SELECT 	p_senderAgentId
 		,	1
 	UNION ALL
     SELECT 	items
 		,	0
     FROM 	tt_Split_temptable ;
     
     DROP TEMPORARY TABLE IF EXISTS tt_Split_temptable;    
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
 	SELECT 	internalChatId
     INTO 	v_internalChatId 
     FROM 	tb_internalChat
     WHERE 	internalChatId 	= p_internalChatId
     AND 	domainId		= p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     
     IF v_internalChatId IS NULL
     THEN
 		INSERT INTO tb_internalChat(	
 			internalChatGroupId
 			,domainId
 			,msg
 			,sendTimestamp
 			,createdAt
 			,updatedAt			
         )
         VALUES(	
 			p_internalChatGroupId
 			,p_domainId
 			,p_msg
             ,unix_timestamp(now(3)) * 1000
             ,v_curDate
             ,v_curDate
         );
         
         SET v_internalChatId = last_insert_id();
         
         INSERT INTO tb_internalChatParticipant(		
 			internalChatId							
 			,agentId					
 			,isSender					
 			,isEdited					
 			,isDeleted					
 			,msgStatus					
 			,createdAt					
 			,updatedAt					
         )
         SELECT v_internalChatId			
			 ,	agentId
             ,	isSender
             ,	0
             ,	0
             ,	0 	
             ,	v_curDate
             ,	v_curDate
         FROM 	tmp_participants;    
         
         SET v_errCode	= 1
 		, 	v_errMsg	= 'Added internal chat successfully';
     END IF;
     
     SELECT v_internalChatId AS internalChatId, v_errCode AS errCode, v_errMsg AS errMsg;        
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
