CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaasInsertUpdateinternalChatGroup`(
    p_internalChatGroupId	INT 
    ,p_groupName				TEXT
    ,p_historyId				BIGINT
   
    ,p_channelTypeId			INT
    
    ,p_customerId			BIGINT
    ,p_hostAgent				BIGINT
    ,p_agentIds				TEXT
    ,p_queueId				INT	
    ,p_domainId				INT)
SP:BEGIN
  	DECLARE v_internalChatGroupId	INT;
  	DECLARE v_customerName			VARCHAR(200);
  	DECLARE v_curDate				DATETIME DEFAULT NOW();
  	DECLARE v_errCode				INT DEFAULT -1;
  	DECLARE v_errMsg				VARCHAR(150) DEFAULT 'Add/Update Internal Chat Group failed';
        
    IF p_internalChatGroupId IS NULL
    THEN
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    		SELECT 	internalChatGroupId	INTO v_internalChatGroupId    
    		FROM 	tb_internalChatGroup
    		WHERE 	domainId		= p_domainId
    		AND 	historyId		= p_historyId
  		AND 	channelTypeId	= p_channelTypeId;
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
 	   IF v_internalChatGroupId IS NOT NULL
 	   THEN
 			SET v_errCode	= -2
 			,	v_errMsg	= 'Internal chat group already exists';
 		  
 			SELECT v_internalChatGroupId AS 'internalChatGroupId',p_groupName AS groupName,v_customerName AS 'customerName', v_errCode AS 'errCode', v_errMsg AS 'errMsg';	
 			LEAVE SP;
 	   END IF;
 	END IF;
        
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
        SELECT internalChatGroupId	INTO v_internalChatGroupId    
        FROM 	tb_internalChatGroup
        WHERE 	domainId			= p_domainId
        AND 	internalChatGroupId	= p_internalChatGroupId;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
        
        IF v_internalChatGroupId IS NULL
        THEN
    		INSERT INTO tb_internalChatGroup
            (	groupName		
 				,historyId
 				
 				,channelTypeId
 				,customerId	
 				,hostAgent
 				,agentIds		
 				,queueId	
 				,domainId
 				,createdTimestamp             
 				,createdAt			
 				,updatedAt			
            )
            VALUES
            (	p_groupName
 				,p_historyId
 				
 				,p_channelTypeId
 				,p_customerId	
 				,p_hostAgent
 				,p_agentIds		
 				,p_queueId	
 				,p_domainId
 				,ROUND(unix_timestamp(NOW(3))) * 1000
 				,v_curDate
 				,v_curDate
            );
            
            SET v_internalChatGroupId = last_insert_id();
            SET 	v_errCode	= 1
 			,	v_errMsg	= 'Added Internal Chat Group successfully';
    	ELSE 
 		UPDATE 	tb_internalChatGroup
 		SET 	groupName 			= p_groupName
 			,	agentIds			= p_agentIds
 			,	updatedAt 			= v_curDate
 		WHERE 	internalChatGroupId	= v_internalChatGroupId;
            
            SET v_errCode	= 2
    		,	v_errMsg	= 'Updated Internal Chat Group successfully';
        END IF;
        
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
        SELECT 	CONCAT(IFNULL(CONCAT(firstName,' '),''),IFNULL(lastName,''))
        INTO 	v_customerName
        FROM 	customer_contact
        WHERE 	coid		= p_customerId
        AND 	domainId 	= p_domainId;	
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
        
        SELECT v_internalChatGroupId AS 'internalChatGroupId',p_groupName AS groupName,v_customerName AS 'customerName', v_errCode AS 'errCode', v_errMsg AS 'errMsg';
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaasInsertUpdateSocialMediaConnectors` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
