/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaasInsertUpdateSocialMediaConnectors`(	
	p_historyId						BIGINT
	,p_flowId						BIGINT	
    ,p_customerContactId			VARCHAR(25)
    ,p_domainId						INT
    ,p_channelTypeId				INT
    ,p_connectorData				JSON
)
BEGIN
	DECLARE v_socialMediaConnectorsId	INT;
    DECLARE v_curDate					DATETIME DEFAULT NOW();
	DECLARE v_errCode					INT DEFAULT -1;
    DECLARE v_errMsg					VARCHAR(150) DEFAULT 'Add/Update Social Media Connectors';
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SELECT 	socialMediaConnectorsId	INTO v_socialMediaConnectorsId    
    FROM 	tb_socialMediaConnectors
    WHERE 	domainId		= p_domainId
    AND 	historyId		= p_historyId
    AND 	channelTypeId	= p_channelTypeId;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
    
    IF v_socialMediaConnectorsId IS NULL
    THEN
		INSERT INTO tb_socialMediaConnectors
        (	historyId
			,flowId
			,customerContactId
			,domainId
			,channelTypeId
			,connectorData
			,createdAt
			,updatedAt
        )
        VALUES
        (	p_historyId			
            ,p_flowId			
            ,p_customerContactId
            ,p_domainId			
            ,p_channelTypeId	
            ,p_connectorData	
            ,v_curDate
            ,v_curDate
        );	
    ELSE	
		UPDATE 	tb_socialMediaConnectors
        SET 	connectorData	= JSON_ARRAY_APPEND(connectorData,'$',p_connectorData) 	
				
            ,	updatedAt		= v_curDate
		WHERE 	socialMediaConnectorsId	= v_socialMediaConnectorsId; 
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
