CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasInternalChatAllMsgStatus`(
    p_internalChatGroupId	VARCHAR(1000)
    ,p_agentId				BIGINT	 
    ,p_domainId				INT 
    ,p_msgStatus				TINYINT
    )
BEGIN
    	DECLARE v_curDate	DATETIME DEFAULT NOW();
    	DECLARE v_errCode	SMALLINT DEFAULT -1;
    	DECLARE v_errMsg	VARCHAR(150) DEFAULT 'Update internal chat status failed';
       
   	DROP TEMPORARY TABLE IF EXISTS tmp_internalChatIds;
   	CREATE TEMPORARY TABLE tmp_internalChatIds
   	(internalChatId		BIGINT);
         
    	CALL Split(p_internalChatGroupId,',');
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
   	INSERT INTO tmp_internalChatIds(internalChatId)
   	SELECT DISTINCT 
   			C.internalChatId            
   	FROM 	tt_Split_temptable	tt
  	JOIN 	tb_internalChat		C	ON C.internalChatGroupId = tt.items;        
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
   	UPDATE 	tb_internalChatParticipant	CP
  	JOIN 	tmp_internalChatIds			t_C	ON	t_C.internalChatId	= CP.internalChatId
   	SET 	CP.msgStatus	= p_msgStatus
   	WHERE 	CP.agentId 		= p_agentId
   	AND 	CP.msgStatus	<> p_msgStatus;	
        
  	SET v_errCode 	= 1
  	,	v_errMsg	= 'Update internal chat status susseccfully';	
    
    SELECT v_errCode AS errCode, v_errMsg	AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
