CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasSetDeliveredFlagForAgentInternalChat`(
p_agentId		BIGINT	 
,p_domainId		INT   
)
BEGIN
	DECLARE v_curDate	DATETIME DEFAULT NOW();
	DECLARE v_errCode	SMALLINT DEFAULT -1;
	DECLARE v_errMsg	VARCHAR(150) DEFAULT 'Update internal chat status failed';
    
    UPDATE 	tb_internalChatParticipant
	SET 	msgStatus	= 1		
    WHERE 	agentId 	= p_agentId
    AND 	msgStatus	= 0;	
END ;;
DELIMITER ;
