CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasUpdateInternalChatGroupStatus`(	
   	p_historyId				BIGINT
    	,p_domainId				INT
    	,p_channelTypeId		INT    	
    )
BEGIN	
 	DECLARE v_curDate		DATETIME DEFAULT NOW();
     
 	UPDATE 	tb_internalChatGroup
     SET 	isClosed		= 1
 		,	updatedAt		= v_curDate
     WHERE 	historyId		= p_historyId
     AND 	domainId		= p_domainId
     AND 	channelTypeId	= p_channelTypeId
     AND 	isClosed		= 0;
        
  	SELECT 1 AS errCode, 'Message status updated successfully' AS errMsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
