CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasUpdateInternalChatMsg`(
 p_internalChatId		VARCHAR(1000) 
 ,p_domainId			INT
 ,p_msg					JSON 
 ,p_agentId				BIGINT	 
 )
BEGIN
 	DECLARE v_curDate						DATETIME DEFAULT NOW();
  	DECLARE v_errCode						SMALLINT DEFAULT -1;
  	DECLARE v_errMsg						VARCHAR(150) DEFAULT 'Update internal chat message failed';
 
 	UPDATE 	tb_internalChat
	SET 	msg				= p_msg
		,	updatedAt		= v_curDate
	WHERE 	internalChatId	= p_internalChatId;    
    
    UPDATE 	tb_internalChatParticipant
	SET 	isEdited		= 1
 		,	updatedAt		= v_curDate
	WHERE 	internalChatId	= p_internalChatId
    AND 	agentId			= p_agentId;    
 
 	SET v_errCode  	= 1
 	,	v_errMsg	= 'Internal chat message updated successfully';
 	
 	SELECT v_errCode AS errCode, v_errMsg AS errMsg;     
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
