CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaasUpdateInternalChatMsgStatus`(	
    	p_internalChatId		VARCHAR(1000) 
     	,p_domainId				INT
     	,p_senderAgentId		INT   
   	,p_msgStatus			INT	
     )
BEGIN	
   	 DROP TEMPORARY TABLE IF EXISTS tmp_internalChatIds;
        CREATE TEMPORARY TABLE tmp_internalChatIds
        (	internalChatId		BIGINT
   		,isAllRead			TINYINT	DEFAULT 1
         ,isGroupClosed		TINYINT	DEFAULT 0
         ,isAgentDeleted		TINYINT	DEFAULT 0
        );
        
   	CALL Split(p_internalChatId,',');
        
        INSERT INTO tmp_internalChatIds(internalChatId,isGroupClosed,isAgentDeleted)
        SELECT DISTINCT 
    			IC.internalChatId
            ,ICG.isClosed
            ,CASE WHEN hostAgent = p_senderAgentId OR FIND_IN_SET(p_senderAgentId,ICG.agentIds) > 0  THEN 0 ELSE 1 END
        FROM 	tt_Split_temptable		t_IC
        JOIN 	tb_internalChat			IC		ON IC.internalChatId = t_IC.items	
        JOIN 	tb_internalChatGroup	ICG		ON ICG.internalChatGroupId	= IC.internalChatGroupId	;
        
    	UPDATE 	tb_internalChatParticipant	CP
    	JOIN 	tmp_internalChatIds			IC	ON CP.internalChatId = IC.internalChatId						
    	SET 	msgStatus			= p_msgStatus	
    	WHERE 	CP.agentId			= p_senderAgentId;
       
   	UPDATE 	tmp_internalChatIds			t_C
   	JOIN 	tb_internalChatParticipant	CP	ON 	t_C.internalChatId	= CP.internalChatId
   											AND CP.msgStatus		= 0
   	SET 	isAllRead = 0;
       
       SELECT 	* 
 
       FROM 	tmp_internalChatIds;
        
   	SELECT 1 AS errCode, 'Message status updated successfully' AS errMsg;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
