CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_addUpdateCustomField`(
	p_customFieldId 		INT,
	p_domainId 				INT,
	p_fieldTypeId 			INT,
	p_datePickerType 		INT,
	p_fieldName 			VARCHAR(100),
	p_waterMark 			VARCHAR(250),
	p_minChar 				INT,
	p_maxChar 				INT,
	p_fileTypeAcceptance 	VARCHAR(10),
	p_uploadMode 			VARCHAR(10),
	p_selectDataType 		INT,
	p_addedOption 			JSON,
	p_isRequired 			TINYINT,
	p_errorMsg 				VARCHAR(200),   
	p_screenId 				INT,
	p_screenDesc 			TEXT,
	p_isArchive 			TINYINT
)
BEGIN
	DECLARE v_curDate		DATETIME DEFAULT NOW();
    DECLARE v_customFieldId INT;
    DECLARE v_errCode		TINYINT;
    DECLARE v_errMsg		VARCHAR(250);
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SELECT 	customFieldId INTO v_customFieldId
    FROM 	tb_ccaas_customField
    WHERE 	customFieldId	= p_customFieldId
    AND 	domainId		= p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    IF v_customFieldId IS NULL
    THEN
		INSERT INTO tb_ccaas_customField(
        domainId
		,fieldTypeId
		,datePickerType
		,fieldName
		,waterMark
		,minChar
		,maxChar
		,fileTypeAcceptance
		,uploadMode
		,selectDataType
		,addedOption
		,isRequired
		,errorMsg
		,screenId
		,screenDesc
		,isArchive
		,createDate
		,updatedDate
        )
        VALUES(
        p_domainId 			
        ,p_fieldTypeId 		
        ,p_datePickerType 	
        ,p_fieldName 		
        ,p_waterMark 		
        ,p_minChar 			
        ,p_maxChar 			
        ,p_fileTypeAcceptance
        ,p_uploadMode 		
        ,p_selectDataType 	
        ,p_addedOption 		
        ,p_isRequired 		
        ,p_errorMsg 			
        ,p_screenId 			
        ,p_screenDesc 		
        ,p_isArchive 		
        ,v_curDate
        ,v_curDate
        );
    
		SET v_customFieldId = last_insert_id()
		,	v_errCode		= 1
		,	v_errMsg		= 'Inserted custom field successfully';
	ELSE
		UPDATE 	tb_ccaas_customField
        SET fieldTypeId			= p_fieldTypeId 		
			,datePickerType		= p_datePickerType 		
			,fieldName			= p_fieldName 		
			,waterMark			= p_waterMark 		
			,minChar			= p_minChar 			
			,maxChar			= p_maxChar 			
			,fileTypeAcceptance	= p_fileTypeAcceptance
			,uploadMode			= p_uploadMode 		
			,selectDataType		= p_selectDataType 	
			,addedOption		= p_addedOption 		
			,isRequired			= p_isRequired 		
			,errorMsg			= p_errorMsg 						
			,isArchive			= p_isArchive
			,updatedDate		= v_curDate
		WHERE customFieldId 	= v_customFieldId;
        
        SET v_errCode		= 2
		,	v_errMsg		= 'Updated custom field successfully';
    END IF;
    
	SELECT 	v_customFieldId AS customFieldId
		,	v_errCode		AS errCode
        ,	v_errMsg		AS errMsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_chat_performances_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_chat_performances_metrics_filter`(
       		p_startTmpstmp 		BIGINT,
           	p_endTmpstmp 		BIGINT,
           	p_domainId 			INT,
            p_agentId			VARCHAR(250),
       		p_offset 			INT,      
   			p_Limit 			INT	   
       	)
sp_return:begin
  			DECLARE v_offset 					INT;	
  			DECLARE v_Total_Count 				INT;        
  			DECLARE v_startTmpstmp 				BIGINT;
  			DECLARE v_endTmpstmp 				BIGINT;
  			DECLARE v_currenttimestamp    		DATETIME;
  			DECLARE v_previous_timestamp 	    DATETIME;
  			DECLARE v_oneday_previous_timestamp DATETIME;
  			DECLARE v1_count_currentdata 		INT;
  			DECLARE v1_count_pastdata 			INT;
  			DECLARE v2_count_currentdata		INT;
  			DECLARE v2_count_pastdata			INT;
			DECLARE v3_count_currentdata		INT;
  			DECLARE v3_count_pastdata			INT;
			DECLARE v_CurrentStartTmpstmp 	BIGINT;
 	        DECLARE v_CurrentEndTmpstmp 	BIGINT;
  	        DECLARE v_PrevStartTmpstmp 		BIGINT;
 	        DECLARE v_PrevEndTmpstmp 		BIGINT; 
 	        DECLARE v_TmpstmpInterval		BIGINT;	
              
     SET v_offset =  p_Limit * p_offset;   
 
 	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
 	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = unix_timestamp(now())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF; 
               
     SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
     
     SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
     SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
 		
 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
 	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
                   
                  		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
              		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
              		(    DispositionId 			INT
              			,DispositionStatus 		VARCHAR(100)
              			,DispositionCategory	TINYINT
              		); 
              		INSERT INTO temp_AvailableDisposition 
              		SELECT 	did 			DispositionId
              			,	dispositionName	DispositionStatus
              			,	CASE WHEN dispositionName = 'Opened'	THEN 2
              				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
              				WHEN dispositionName = 'Discarded' THEN 4
       					    WHEN dispositionName = 'Resolved'  THEN 5
              				END 			DispositionCategory
              		FROM 	disposition_status
              		WHERE 	domainId	= p_domainId;
               	
               	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
               	CREATE TEMPORARY TABLE temp_AllagentId
               	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId  AND roleid NOT IN (5,3);    
                   
               SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
               DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
              	CREATE TEMPORARY TABLE temp_chatHistory as
               SELECT 	 
       					 CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 		   						 						AS SessionDate
						,U.UserName																									    AS agentName	
 						,U.UserID																										AS agentId	
  						,CASE WHEN avg(CH.repliedDate - CH.createdAt) is not null then (CH.repliedDate - CH.createdAt) else '-' end  	AS avgresponseTime
  						,CASE WHEN avg(t_D.DispositionCategory =3) THEN 1 ELSE 0 END		                                           	AS avgHandled
   						,CDH.SentimentalScore	                         
       			 FROM 	tb_ChatHistory 			CH
       			 JOIN 	tb_ChatDurationHistory	CDH	     ON CH.ChatHistoryId = CDH.ChatHistoryId
    			LEFT JOIN 	tb_User				    U	   		 ON U.UserID	 = CDH.AgentId
    			LEFT JOIN 	temp_agentIDs 		    t_A      ON U.UserID 	     = t_A.agentId   
    			LEFT JOIN 	temp_AvailableDisposition	t_D	 ON CDH.dispositionId= t_D.DispositionId            
       			 WHERE 	CH.domainId 			= p_domainId
                  	 AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp and v_CurrentEndTmpstmp 
					 AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
                   group by CH.sessionStartTime,U.UserName,U.UserID,CDH.SentimentalScore,CH.repliedDate,CH.createdAt;
       			
       		
               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
 					SELECT * FROM temp_AllagentId;
                    
      		 
  
     
      		
      		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
      	 	INTO 	v1_count_currentdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
      		and 	domainId	= p_domainId
  			LIMIT 1;
              
      		
      		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
      		INTO 	v1_count_pastdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		and 	domainId	= p_domainId
  			LIMIT 1;
              
  	
  		 SELECT 
  			CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
  			into v2_count_currentdata   
  			FROM temp_AvailableDisposition 
  			WHERE p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
              LIMIT 1; 
  		
  			SELECT 	CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
  			into v2_count_pastdata 
  			FROM temp_AvailableDisposition 
  			WHERE p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
  			 LIMIT 1;
         
  			select  SentimentalScore
              into  	v3_count_currentdata
  			from 	tb_ChatDurationHistory
  			where 	p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
                LIMIT 1; 
         
  			SELECT  SentimentalScore
			INTO  	v3_count_pastdata
  			FROM 	tb_ChatDurationHistory
  			WHERE 	p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
			LIMIT 1;
            
   					IF NOT EXISTS(SELECT 1 FROM temp_chatHistory limit 1) then
      					SELECT '0' as agentName, '0' AS averageResponseTime, '0' AS ResponseTimeincreasedby, '0' AS averageHandledTime, '0' AS HandledTimeincreasedby ,
   					'0' AS totalabondedchats ,'0'    AS abondedchatssincreasedby;
						leave sp_return;
                       END IF;
                   
                   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
       			SELECT 
  							IFNULL(agentName,0)                                                                  	  	    AS agentName,
  							IFNULL(avgresponseTime,0) 					                                		 		    AS averageResponseTime,
  							IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata * 100),0)		        AS responseTimeIncreasedby,
  							IFNULL(avgHandled,0 )                                                                		    AS averageHandledTime,
  							IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata * 100),0)		        AS handledTimeincreasedby,
  							IFNULL(SentimentalScore,0 )                                            			     			AS customerSatisfaction,
  							IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata * 100),0)		        AS customerSatisfactionsIncreasedby 
  							FROM 	temp_chatHistory ;
							SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       			
                   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_chat_performances_metrics_filter1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_chat_performances_metrics_filter1`(
        		p_startTmpstmp 		BIGINT,
            	p_endTmpstmp 		BIGINT,
            	p_domainId 			INT,
				p_agentId			VARCHAR(250),
        		p_offset 			INT,      
    			p_Limit 			INT	   
        	)
sp_return:BEGIN
   			DECLARE v_offset 					INT;	
   			DECLARE v_Total_Count 				INT;        
   			DECLARE v_startTmpstmp 				BIGINT;
   			DECLARE v_endTmpstmp 				BIGINT;
   			DECLARE v_currenttimestamp    		DATETIME;
   			DECLARE v_previous_timestamp 	    DATETIME;
   			DECLARE v_oneday_previous_timestamp DATETIME;
   			DECLARE v1_count_currentdata 		INT;
   			DECLARE v1_count_pastdata 			INT;
   			DECLARE v2_count_currentdata		INT;
   			DECLARE v2_count_pastdata			INT;
 			DECLARE v3_count_currentdata		INT;
   			DECLARE v3_count_pastdata			INT;
 			DECLARE v_CurrentStartTmpstmp 	BIGINT;
  	        DECLARE v_CurrentEndTmpstmp 	BIGINT;
   	        DECLARE v_PrevStartTmpstmp 		BIGINT;
  	        DECLARE v_PrevEndTmpstmp 		BIGINT; 
  	        DECLARE v_TmpstmpInterval		BIGINT;	
               
      SET v_offset =  p_Limit * p_offset;   
  
  	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
  	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = unix_timestamp(now())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF; 
                
      SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
      
      SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
      SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
  		
  	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
  	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
                    
                   		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
               		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
               		(    DispositionId 			INT
               			,DispositionStatus 		VARCHAR(100)
               			,DispositionCategory	TINYINT
               		); 
               		INSERT INTO temp_AvailableDisposition 
               		SELECT 	did 			DispositionId
               			,	dispositionName	DispositionStatus
               			,	CASE WHEN dispositionName = 'Opened'	THEN 2
               				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
               				WHEN dispositionName = 'Discarded' THEN 4
        					WHEN dispositionName = 'Resolved'  THEN 5
               				END 			DispositionCategory
               		FROM 	disposition_status
               		WHERE 	domainId	= p_domainId;
                	
                	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                	CREATE TEMPORARY TABLE temp_AllagentId
                	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId  AND roleid NOT IN (5,3);    
                    
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
               	CREATE TEMPORARY TABLE temp_chatHistory as
                SELECT 	
						 CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 		   						 					    AS SessionDate
 						,U.UserName																									    AS agentName	
  						,U.UserID																										AS agentId	
   						,CASE WHEN avg(CH.repliedDate - CH.createdAt) is not null then (CH.repliedDate - CH.createdAt) else '-' end  	AS avgresponseTime
   						,SUM(CASE WHEN CDH.EndTime IS NOT NULL THEN CDH.Duration ELSE 0 END	)	                                        AS avgHandled                     						
						,  CDH.SentimentalScore                                                                                         AS SentimentalScore      
        			 FROM 	tb_ChatHistory 			CH
        			 JOIN 	tb_ChatDurationHistory	CDH	     ON CH.ChatHistoryId = CDH.ChatHistoryId
     			LEFT JOIN 	tb_User				    U	   	 ON U.UserID	 = CDH.AgentId
     			LEFT JOIN 	temp_agentIDs 		    t_A      ON U.UserID 	     = t_A.agentId   
     			LEFT JOIN 	temp_AvailableDisposition	t_D	 ON CDH.dispositionId= t_D.DispositionId            
        			 WHERE 	CH.domainId 			= p_domainId
                   	 AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp and v_CurrentEndTmpstmp 
 					 AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
                    group by CH.sessionStartTime,U.UserName,U.UserID,CH.repliedDate,CH.createdAt ,CDH.SentimentalScore;
        			
        		
                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                    SELECT * FROM temp_chatHistory;
  					SELECT * FROM temp_AllagentId;
                     
       		 
   
      
       		
       		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
       	 	INTO 	v1_count_currentdata 
       		FROM 	tb_ChatHistory
       		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
       		and 	domainId	= p_domainId
   			LIMIT 1;
               
       		
       		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
       		INTO 	v1_count_pastdata 
       		FROM 	tb_ChatHistory
       		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
       		and 	domainId	= p_domainId
   			LIMIT 1;
               
   	
   		 SELECT 
   			CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
   			into v2_count_currentdata   
   			FROM temp_AvailableDisposition 
   			WHERE p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
               LIMIT 1; 
   		
   			SELECT 	CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
   			into v2_count_pastdata 
   			FROM temp_AvailableDisposition 
   			WHERE p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
   			 LIMIT 1;
          
   			select  SentimentalScore
               into  	v3_count_currentdata
   			from 	tb_ChatDurationHistory
   			where 	p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
                 LIMIT 1; 
          
   			SELECT  SentimentalScore
 			INTO  	v3_count_pastdata
   			FROM 	tb_ChatDurationHistory
   			WHERE 	p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
 			LIMIT 1;
             
    					IF NOT EXISTS(SELECT 1 FROM temp_chatHistory limit 1) then
       					SELECT '0' as agentName, '0' AS averageResponseTime, '0' AS ResponseTimeincreasedby, '0' AS averageHandledTime, '0' AS HandledTimeincreasedby ,
    					'0' AS totalabondedchats ,'0'    AS abondedchatssincreasedby;
 						leave sp_return;
                        END IF;
                    
                    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
        			SELECT 
   							IFNULL(agentName,0)                                                                  	  	                AS agentName,
                            COUNT(1)                                                                                                    AS receivedChat,
   							sum(IFNULL(avgresponseTime,0))/COUNT(1) 					                                		 		AS averageResponseTime,
   							sum(IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata * 100),0))		            AS responseTimeIncreasedby,
   							sum(IFNULL(avgHandled,0 ))/COUNT(1)                                                                		    AS averageHandledTime,
   							sum(IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata * 100),0))		            AS handledTimeincreasedby,
   							sum(IFNULL(SentimentalScore,0 ))/COUNT(1)                                            			     		AS customerSatisfaction,
   							sum(IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata * 100),0))		            AS customerSatisfactionsIncreasedby 
   							FROM 	temp_chatHistory 
                            GROUP BY agentName;
 							SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        			
                    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_chat_performances_metrics_Trend_Chart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_chat_performances_metrics_Trend_Chart`(
     	p_domainId 			INT,
     	p_datetype 			INT,            		
		p_startDateTime		DATETIME,
		p_endDateTime		DATETIME,
     	p_columnName    	VARCHAR(200),        	
		p_agentId 			TEXT
         )
BEGIN
   
    	DECLARE v_startDateTime			DATETIME;
    	DECLARE v_endDateTime			DATETIME;     
    	DECLARE v_datetimeInterval		SMALLINT;    
    	DECLARE v_startDateTimePast		DATETIME;
    	DECLARE v_endDateTimePast		DATETIME;
         
    	DECLARE v_startTimestampPast	BIGINT;
    	DECLARE v_endTimestampPast		BIGINT;      
    	DECLARE v_startTimestamp		BIGINT;
    	DECLARE v_endTimestamp			BIGINT;
    	DECLARE v_curDate				DATETIME DEFAULT NOW();	
		DECLARE v_currentCount			INT;
		DECLARE v_pastCount				INT;
		DECLARE v_totalResponseTime		BIGINT;
        DECLARE v_totalACWTime          BIGINT;
		DECLARE v_totalHandlingTime     BIGINT;
		DECLARE v_countIncomingChats	INT;
        
        
    	DROP TEMPORARY TABLE IF EXISTS tmp_result;
    	CREATE TEMPORARY TABLE tmp_result(
    		reportAge			VARCHAR(20)
    		,startDateTime		DATETIME
    		,endDateTime		DATETIME
    		,callCount			INT
    	);    
     
     	IF p_datetype = 1 
         THEN 	
     		SET v_startDateTime = CAST(v_curDate AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
     	END IF;
     	IF p_datetype = 2 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
     	END IF;
     	IF p_datetype = 3 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = CAST(v_curDate AS DATE); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
     	END IF;
     	IF p_datetype = 4 
         THEN 
     		SET v_startDateTime = p_startDateTime; 
    		SET v_endDateTime 	= p_endDateTime; 
             
            SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     	END IF;
         
           IF p_agentId IS NOT NULL 
           THEN
       		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
       		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
           ELSE
       		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
              CREATE TEMPORARY TABLE temp_agentIds
     		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
  		END IF;
         
         DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
         CREATE TEMPORARY TABLE tmp_Disposition
         SELECT did, dispositionName
         FROM 	disposition_status
         WHERE	domainId		= p_domainId
         AND	dispositionName	= 'Caller Disconnected';    
         
         IF p_datetype IN (1,2)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH RECURSIVE CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	endDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
     	ELSEIF p_datetype IN (3,4)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH recursive CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	startDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
         END IF;  
         
         ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
         UPDATE tmp_timings
         SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
     		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
             
     	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
    	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
    	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
    	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
              
              
              
     DROP TEMPORARY TABLE IF EXISTS tmp_ChatDurationHistory_1;	
    	CREATE TEMPORARY TABLE tmp_ChatDurationHistory_1
    	SELECT 	
  		  CH.ChatHistoryId
    		,	CH.sessionStartTime
    		,	CDH.IsMissed     
    		,	CDH.Duration
			,   CDH.answeredDuration															AS responseTime 
			,  0                															    AS QueueWaitTime   
			,  CDH.afterChatWorkTime
			,  CH.domainId
     	FROM 	 tb_ChatHistory 			 CH
     JOIN 	tb_ChatDurationHistory	  CDH		ON 	CH.ChatHistoryId 	= CDH.ChatHistoryId    
    	WHERE 	CH.domainId 		= p_domainId
    	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;          
      
      
     DROP TEMPORARY TABLE IF EXISTS tmp_ChatDurationHistory;	
    	 CREATE TEMPORARY TABLE tmp_ChatDurationHistory
       SELECT
  		ChatHistoryId,
          sessionStartTime,
          AVG(responseTime) 																AS averageResponseTime,
          AVG((Duration/ 1000) + afterChatWorkTime)  										AS averageHandlingTime,
          SUM((Duration/ 1000) + afterChatWorkTime)  										AS maximumHandlingTime,
          SUM(afterChatWorkTime)  														AS totalACWTime,
          ifnull(AVG(QueueWaitTime),0) 													AS averageQueueWaitTime
           ,domainId
  		
      FROM tmp_ChatDurationHistory_1
      group by ChatHistoryId,sessionStartTime,domainId; 
      
      
  
         	DROP TEMPORARY TABLE IF EXISTS tmp_ChatHistory;	
  		CREATE TEMPORARY TABLE tmp_ChatHistory
          SELECT 	DISTINCT 
     			 CDH.ChatHistoryId 
     		, 	 CDH.sessionStartTime
      
     	   FROM 	tmp_ChatDurationHistory CDH;    
      
  
		 ALTER TABLE tmp_ChatHistory  ADD averageResponseTime 	BIGINT DEFAULT 0;
         ALTER TABLE tmp_ChatHistory  ADD averageHandlingTime 	BIGINT DEFAULT 0;
         ALTER TABLE tmp_ChatHistory  ADD totalACWTime			BIGINT DEFAULT 0;
         ALTER TABLE tmp_ChatHistory  ADD averageQueueWaitTime  BIGINT DEFAULT 0;
          
          
  		CREATE INDEX ix_tmp_ChatHistory        ON tmp_ChatHistory (ChatHistoryId);
         CREATE INDEX ix_tmp_ChatDurationHistory ON tmp_ChatDurationHistory (ChatHistoryId);   
          
        
       UPDATE tmp_ChatHistory			CH
         JOIN 	tmp_ChatDurationHistory	CDH	ON CH.ChatHistoryId	= CDH.ChatHistoryId  
         SET 	CH.averageResponseTime	= CDH.averageResponseTime,
     			CH.averageHandlingTime	= CDH.averageHandlingTime,
				CH.totalACWTime	        = CDH.totalACWTime,
				CH.averageQueueWaitTime = CDH.averageQueueWaitTime;
        
        
    
     IF p_columnName = 'Total ACW Time'
    	THEN
     
			SELECT SUM(CDH.afterChatWorkTime) INTO v_totalACWTime
			FROM 	tmp_ChatDurationHistory_1 CDH
			WHERE 	CDH.domainId = p_domainId
			AND		CDH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
        
			SELECT count(*) into v_countIncomingChats
			FROM 	tb_ChatHistory CH 
			JOIN 	tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
			WHERE 	CH.domainId= p_domainId
			 AND 	CH.IsInBound = 1
			AND 	IFNULL(CDH.afterChatWorkTime,0) > 0
			AND		CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
            

        
    		INSERT INTO tmp_result
     		SELECT 	'Current'										AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	round(v_totalACWTime/v_countIncomingChats) 		AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
  	
      
      ELSEIF p_columnName = 'Avg. Response Time'
    	THEN
        
			select SUM(CDH.responseTime) into v_totalResponseTime
			from 	tmp_ChatDurationHistory_1 CDH
			where 	CDH.domainId = p_domainId
			and		CDH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;

			SELECT count(*) into v_countIncomingChats
			FROM 	tb_ChatHistory CH 
			JOIN 	tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
			WHERE 	CH.domainId= p_domainId
			AND 	CH.IsInBound = 1
			AND 	IFNULL(CDH.answeredDuration,0) > 0
			AND		CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
            

        
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,round(v_totalResponseTime/v_countIncomingChats) AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
      
      ELSEIF p_columnName = 'Avg. Handle Time (AHT)'
    	THEN
			select SUM(CDH.averageHandlingTime) into v_totalHandlingTime
			from 	tmp_ChatDurationHistory CDH
			where 	CDH.domainId = p_domainId
			and		CDH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;

			SELECT count(*) into v_countIncomingChats
			FROM 	tb_ChatHistory CH 
			JOIN 	tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
			WHERE 	CH.domainId= p_domainId
			 AND 	CH.IsInBound = 1
			AND 	IFNULL(CDH.Duration,0) > 0
			AND		CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
            
            
            
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,round(v_totalHandlingTime/v_countIncomingChats) AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
        
            
            
          END IF;       
    
      SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Current';    
        
         
    	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
    	INTO 	v_currentCount, v_pastCount		
    	FROM 	tmp_result;
        
        
        end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_chat_performances_metrics_Trend_Chart1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_chat_performances_metrics_Trend_Chart1`(
   			   p_startTmpstmp BIGINT,    
                p_endTmpstmp BIGINT,
                p_domainId INT,
                p_columnname varchar(155)
            )
BEGIN
   			DECLARE v_startDateTime 					DATETIME;
   			DECLARE v_endDateTime 						DATETIME;
   			DECLARE v_startTmpstmp 						BIGINT;
   			DECLARE v_endTmpstmp 						BIGINT;
   			DECLARE v_startTime	 						DATETIME;
   			DECLARE v_endTime	 						DATETIME;
   			DECLARE v_currenttimestamp 					BIGINT;
   			DECLARE v_previous_timestamp 				BIGINT;
   			DECLARE v_oneday_previous_timestamp 		BIGINT;
   			DECLARE v1_count_currentdata 				BIGINT;
   			DECLARE v2_count_pastdata 			   	 	BIGINT;
   			DECLARE v_coulumnname                  		VARCHAR(150);
              DECLARE v_interval							INT;       
     				
    			SET v_coulumnname=p_columnname;
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    			CREATE TEMPORARY TABLE temp_Intervals (
    			starttime DATETIME,
    			endtime   DATETIME
    			);
                 
    			SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 7 day)	,from_unixtime(p_startTmpstmp/1000));
  			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
                
                set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                     
      			     IF DATEDIFF(v_endDateTime,v_startDateTime) > 29
              THEN
  				SET v_interval = 86400; 
  			ELSEIF DATEDIFF(v_endDateTime,v_startDateTime) > 1
              THEN
  				SET v_interval = 3600; 
              ELSE
              	SET v_interval = 60; 
              END IF;
                   
    			SET v_startTime = v_startDateTime;
  			SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
      			 WHILE v_startTime < v_endDateTime 
      			 DO      
    				 INSERT INTO temp_Intervals (starttime, endtime)
    				 VALUES (v_startTime, v_endTime);
                     
    				SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval minute));
    				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval minute));
    			END WHILE;
                     
    			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
    			CREATE TEMPORARY TABLE temp_ChatHistory
    			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
    			FROM 	tb_ChatHistory H 
    			WHERE 	H.domainId = p_domainId
    			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
    			GROUP BY H.sessionStartTime;   
                
        
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
    			CREATE TEMPORARY TABLE temp_Intervals_1
    			SELECT t_I.endtime 	AS `Time`
    				,	count(1)	AS `NoofreceivedchatCount`
    			FROM temp_Intervals t_I
    			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
    			GROUP BY t_I.endtime;
        
  			SELECT  (t_I.endtime) 						AS `Time`
  			,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedcurrentchatCount
  			FROM 		temp_Intervals t_I 
  			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;    
             
 		
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
    			CREATE TEMPORARY TABLE temp_Intervals_2
    			SELECT t_I.endtime 	AS `Time`
    				,	count(1)	AS `NoofreceivedchatCount`
    			FROM temp_Intervals t_I
    			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
    			GROUP BY t_I.endtime;
        
  			SELECT  (t_I.endtime) 						AS `Time`
  			,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedpastchatCount
  			FROM 		temp_Intervals t_I 
  			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;  
             
                     
    			
    			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
    			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
    			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;    
            
     
           
    IF p_columnname = 'ResponsesTime'
         THEN
     		
     		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  ResponsesTime
     		INTO 	v1_count_currentdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		and 	domainId	= p_domainId
               LIMIT 1;
             
     		
     		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  ResponsesTime
     		INTO 	v2_count_pastdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		AND 	domainId	= p_domainId
  		LIMIT 1;    
    	ELSEIF p_columnname = 'HandledTime'
         THEN
     		
     		SELECT 	CASE when a.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 1 else 0 end 		AS HandledTime
  		INTO 	v1_count_currentdata 
     		FROM 	disposition_status a
  		JOIN 	tb_ChatHistory   b    on b.domainId=a.domainId
     		WHERE 	b.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		AND 	b.domainId	= p_domainId
  		LIMIT 1;
    
     		
     		SELECT 	CASE when a.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 1 else 0 end 		AS HandledTime
     		INTO 	v2_count_pastdata 
  		FROM 	disposition_status a
  		JOIN 	tb_ChatHistory   b    on b.domainId=a.domainId
     		WHERE 	b.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		AND 	b.domainId	= p_domainId
  		LIMIT 1;   
               
             ELSEIF p_columnname = 'ACWTime'
         THEN
     		
     	SELECT CASE WHEN SUM(b.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(b.afterChatWorkTime)/COUNT(1) ELSE '0' END         ACWTime 
     		INTO 	v1_count_currentdata
     		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
     		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	a.domainId	= p_domainId
               LIMIT 1;
             
     		
     		SELECT CASE WHEN SUM(b.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(b.afterChatWorkTime)/COUNT(1) ELSE '0' END         ACWTime 
     		INTO 	v2_count_pastdata 
     		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
     		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	a.domainId	= p_domainId
               LIMIT 1;
               
               
    
    	ELSEIF p_columnname = 'queueWaitingtime'
         THEN
     		
     		SELECT   CASE WHEN (queueDuration)  IS NOT NULL THEN (queueDuration)  ELSE '0' END         queueWaitingtime 
     		INTO 	v1_count_currentdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		and 	domainId	= p_domainId
               LIMIT 1;
             
     		
     		SELECT CASE WHEN (queueDuration) IS NOT NULL THEN (queueDuration)  ELSE '0' END         queueWaitingtime
     		INTO 	v2_count_pastdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	domainId	= p_domainId
               LIMIT 1;
               
     	ELSEIF p_columnname = 'HoldTime'
         THEN
     		
     		SELECT   CASE WHEN (AgentHoldDuration)  IS NOT NULL THEN (AgentHoldDuration)  ELSE '0' END         HoldTime 
     		INTO 	v1_count_currentdata 
     		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
     		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	a.domainId	= p_domainId
               LIMIT 1;
             
     		
     		SELECT CASE WHEN (AgentHoldDuration) IS NOT NULL THEN (AgentHoldDuration)  ELSE '0' END         HoldTime
     		INTO 	v2_count_pastdata 
     		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
     		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	a.domainId	= p_domainId
               LIMIT 1;      
               
               
      END IF;        
  			SELECT 	v1_count_currentdata	currentdata
  			,		v2_count_pastdata		pastdata
  			,		(v1_count_currentdata - v2_count_pastdata) dataDifference 
  			,		(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	
       
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_chat_performances_metrics_Trend_Chart_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
