/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_Inbound_chat_volume_Analysis1`(
                 p_startTmpstmp BIGINT,
                 p_endTmpstmp   BIGINT,
                 p_domainId       INT,
                 p_volumename   varchar(150)
             )
BEGIN
     		        DECLARE v_startDateTime 				DATETIME;
 				    DECLARE v_endDateTime 					DATETIME;
  				    DECLARE v_startTmpstmp 					BIGINT;
             		DECLARE v_endTmpstmp 					BIGINT;
     				DECLARE v_startTime	 				    DATETIME;
     				DECLARE v_endTime	 					DATETIME;
             		DECLARE v_currenttimestamp 				BIGINT;
             		DECLARE v_previous_timestamp 			BIGINT;
					DECLARE v_interval						INT;
  
  			
  			     DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    			     CREATE TEMPORARY TABLE temp_Intervals (
    			     starttime DATETIME,
    			     endtime   DATETIME
    			     );
                 
  				 SET v_startDateTime := IF(p_startTmpstmp is null,date_sub(now(), INTERVAL  7 day)	,from_unixtime(p_startTmpstmp/1000));
      			 SET v_endDateTime := IF(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
                
                   SET v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                   SET v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                     
      			 SET v_startTime = v_startDateTime;
      			 SET v_endTime = DATE_ADD(v_startTime, INTERVAL 59 minute);
					
                    IF p_volumename = 'chatvolumebyday' THEN
						SET v_interval = 1440; 
					ELSEIF p_volumename = 'chatvolumebyhour' THEN
						SET v_interval = 60; 
					END IF;
                     
                     
      			 WHILE v_startTime < v_endDateTime 
      			 DO      
    				 INSERT INTO temp_Intervals (starttime, endtime)
    				 VALUES (v_startTime, v_endTime);
                     
    				 SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval minute));
    				 SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval minute));
				END WHILE;
  
                   DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
                   CREATE TEMPORARY TABLE temp_ChatHistory
                   
               
                   SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime ,
                           DAYNAME(DATE_FORMAT (FROM_UNIXTIME(H.sessionStartTime / 1000),'%Y-%m-%d')) as date
                   FROM 	tb_ChatHistory H 
                   WHERE 	H.domainId = p_domainId
                   AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
                   GROUP BY H.sessionStartTime;
                   
                   
  				 DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
  				 CREATE TEMPORARY TABLE temp_Intervals_1
  				 SELECT t_I.endtime 	AS `Time`
  					    ,H.date
  				 FROM temp_Intervals t_I
  				  JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
  				 GROUP BY t_I.endtime,H.date;
                   
 
                   
      			
                   SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
                   SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
      
    				 SELECT  	(t_I.endtime)             AS `Time`,
                               t.date                  AS `day`,
                               count(1)                AS NoofreceivedchatCount
    				 FROM 		temp_Intervals t_I 
    				  JOIN       temp_Intervals_1 t ON t.Time = t_I.endtime
                     			GROUP BY t_I.endtime,t.date;
                   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_Inbound_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_Inbound_trendchart`(	
   		    p_domainId 			INT,
        	p_datetype 			INT,            			
         	p_startDateTime		DATETIME,
         	p_endDateTime		DATETIME,
        	p_columnName    	VARCHAR(200),    			
        	p_agentId 			TEXT
            )
BEGIN
            
            
           	DECLARE v_startDateTime			DATETIME;
           	DECLARE v_endDateTime			DATETIME;     
           	DECLARE v_datetimeInterval		SMALLINT;    
           	DECLARE v_startDateTimePast		DATETIME;
           	DECLARE v_endDateTimePast		DATETIME;
                
           	DECLARE v_startTimestampPast	BIGINT;
           	DECLARE v_endTimestampPast		BIGINT;      
           	DECLARE v_startTimestamp		BIGINT;
           	DECLARE v_endTimestamp			BIGINT;
           	DECLARE v_curDate				DATETIME DEFAULT NOW();	
               DECLARE v_currentCount			INT;
               DECLARE v_pastCount				INT;
               
           	DROP TEMPORARY TABLE IF EXISTS tmp_result;
           	CREATE TEMPORARY TABLE tmp_result(
           		reportAge			VARCHAR(20)
           		,startDateTime		DATETIME
           		,endDateTime		DATETIME
           		,callCount			INT
           	);    
            
            	IF p_datetype = 1 
                THEN 	
            		SET v_startDateTime = CAST(v_curDate AS DATE); 
            		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
            
            		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
            		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
            	END IF;
            	IF p_datetype = 2 
                THEN 
            		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
           		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
            
            		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
            		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
            	END IF;
            	IF p_datetype = 3 
                THEN 
            		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
                   SET v_endDateTime = CAST(v_curDate AS DATE); 
                    
            		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
            		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
            	END IF;
            	IF p_datetype = 4 
                THEN 
            		SET v_startDateTime = p_startDateTime; 
           		SET v_endDateTime 	= p_endDateTime; 
                    
                   SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                    
            		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
            		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
            	END IF;
                
           IF p_agentId IS NOT NULL 
                   THEN
               		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
               		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
                   ELSE
               		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                      CREATE TEMPORARY TABLE temp_agentIds
             		 select  UserID as agentId from tb_User where domainId = p_domainId ;
          		END IF;
                
      			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
            		CREATE TEMPORARY TABLE temp_AvailableDisposition 
            		(   DispositionId 			INT
            			,DispositionStatus 		VARCHAR(100)
            			,DispositionCategory	TINYINT
            		); 
                    
            		INSERT INTO temp_AvailableDisposition 
            		SELECT 	did 			DispositionId
            			,	dispositionName	DispositionStatus
            			,	CASE WHEN dispositionName = 'Caller Disconnected'	THEN 2
            				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
            				WHEN dispositionName = 'Discarded' THEN 4
            				END 			DispositionCategory
            		FROM 	disposition_status
            		WHERE 	domainId	= p_domainId  ;  
                
                IF p_datetype IN (1,2)
                THEN 
            		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                    CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
            		WITH RECURSIVE CTE_TIMINGS AS (
            			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
            			UNION ALL
            			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
            			FROM 	CTE_TIMINGS
            			WHERE 	endDateTime < v_endDateTime
            		)
            		SELECT * FROM CTE_TIMINGS;	
            	ELSEIF p_datetype IN (3,4)
                THEN 
            		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                    CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
            		WITH recursive CTE_TIMINGS AS (
            			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
            			UNION ALL
            			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
            			FROM 	CTE_TIMINGS
            			WHERE 	startDateTime < v_endDateTime
            		)
            		SELECT * FROM CTE_TIMINGS;	
                END IF;  
                
                ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
                
                UPDATE tmp_timings
                SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
            		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
                    
            	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
           	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
           	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
           	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
                
              
              DROP TEMPORARY TABLE IF EXISTS tmp_ChatDurationHistory;	
           	CREATE TEMPORARY TABLE tmp_ChatDurationHistory
           	SELECT 	CH.ChatHistoryId
           		,	CH.sessionStartTime
           		,	CDH.IsMissed
           		,	CDH.dispositionId        
           		,	CDH.Duration
      			,	CASE WHEN t_D.DispositionCategory = 2 THEN 1 ELSE 0 END 		AS IsAbandoned
           	FROM  tb_ChatHistory                CH
  			JOIN  tb_ChatDurationHistory       CDH 			   ON CH.ChatHistoryId = CDH.ChatHistoryId     
           	JOIN   temp_agentIds 		       t_A     		   ON t_A.agentId 		= CDH.agentId 	
    		    LEFT JOIN 	temp_AvailableDisposition     t_D      ON t_D.DispositionId =CDH.dispositionId
           	WHERE 	CH.domainId 		= p_domainId
           	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
           	AND 	CH.IsInBound		= 1
               AND 	(CDH.IsMissed = 1 OR t_D.DispositionId IS NOT NULL);
              
              
             DROP TEMPORARY TABLE IF EXISTS tmp_ChatHistory;	
            	CREATE TEMPORARY TABLE tmp_ChatHistory
               SELECT 	DISTINCT 
            			CDH.ChatHistoryId 
            		, 	CDH.sessionStartTime
            	FROM 	tmp_ChatDurationHistory CDH;  
                
                 ALTER TABLE tmp_ChatHistory ADD IsMissed 		TINYINT default 0;
                ALTER TABLE tmp_ChatHistory ADD IsAnswered 	TINYINT default 0;
                ALTER TABLE tmp_ChatHistory ADD IsAbandoned	INT default 0;
                
                CREATE INDEX ix_tmp_ChatHistory ON tmp_ChatHistory (ChatHistoryId);
                CREATE INDEX ix_tmp_ChatDurationHistory ON tmp_ChatDurationHistory (ChatHistoryId);
              
               UPDATE tmp_ChatHistory			CH
               JOIN 	tmp_ChatDurationHistory	CDH	ON CH.ChatHistoryId	= CDH.ChatHistoryId  
    
                SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 	THEN 1 ELSE CH.IsMissed 	END
            		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 	THEN 1 ELSE CH.IsAnswered 	END
                    ,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned =1  THEN 1 ELSE CH.IsAbandoned 	END;
              
              
                  
                  
                   IF p_columnName = 'Received Chats'
                THEN
           		INSERT INTO tmp_result
            		SELECT 	'Current'				AS reportAge
            			,	t_T.startDateTime 
            			,	t_T.endDateTime
            			,	SUM(CASE WHEN CH.ChatHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
            		FROM 	tmp_timings			t_T	
            		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
            		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
            		GROUP BY t_T.startDateTime, t_T.endDateTime;
                   
                   INSERT INTO tmp_result
            		SELECT 	'Past'					AS reportAge
            			,	t_T.startDateTime 
            			,	t_T.endDateTime
            			,	SUM(CASE WHEN CH.ChatHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
            		FROM 	tmp_timings		t_T	
            		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
            		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
            		GROUP BY t_T.startDateTime, t_T.endDateTime;	  
                  
              ELSEIF p_columnName = 'Abandoned Chats'
                   THEN
              		INSERT INTO tmp_result
               		SELECT 	'Current'					AS reportAge
               			,	t_T.startDateTime 
               			,	t_T.endDateTime
               			,	IFNULL(SUM(IsAbandoned),0)	AS callCount
               		FROM 	tmp_timings			t_T	
               		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
               		GROUP BY t_T.startDateTime, t_T.endDateTime;
                      
                      INSERT INTO tmp_result
               		SELECT 	'Past'						AS reportAge
               			,	t_T.startDateTime 
               			,	t_T.endDateTime
               			,	IFNULL(SUM(IsAbandoned),0)	AS callCount     
               		FROM 	tmp_timings		t_T	
               		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
               		GROUP BY t_T.startDateTime, t_T.endDateTime;   
                  ELSEIF p_columnName = 'Responded Chats'
              	THEN
              		INSERT INTO tmp_result
               		SELECT 	'Current'					AS reportAge
               			,	t_T.startDateTime 
               			,	t_T.endDateTime
               			,	IFNULL(SUM(IsAnswered),0)	AS callCount
               		FROM 	tmp_timings			t_T	
               		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
               		GROUP BY t_T.startDateTime, t_T.endDateTime;
                      
                      INSERT INTO tmp_result
               		SELECT 	'Past'						AS reportAge
               			,	t_T.startDateTime 
               			,	t_T.endDateTime
               			,	IFNULL(SUM(IsAnswered),0)	AS callCount     
               		FROM 	tmp_timings		t_T	
               		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
               		GROUP BY t_T.startDateTime, t_T.endDateTime;      
                     
                     
              ELSEIF p_columnName = 'Missed Chats'
              	THEN
              		INSERT INTO tmp_result
               		SELECT 	'Current'			AS reportAge
               			,	t_T.startDateTime 
               			,	t_T.endDateTime
               			,	IFNULL(SUM(IsMissed),0)	AS callCount
               		FROM 	tmp_timings			t_T	
               		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
               		GROUP BY t_T.startDateTime, t_T.endDateTime;
                      
                      INSERT INTO tmp_result
               		SELECT 	'Past'					AS reportAge
               			,	t_T.startDateTime 
               			,	t_T.endDateTime
               			,	IFNULL(SUM(IsMissed),0)	AS callCount     
               		FROM 	tmp_timings		t_T	
               		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
               		GROUP BY t_T.startDateTime, t_T.endDateTime;        
                   END IF;   
              
                SELECT  *
                 FROM 	tmp_result
                 WHERE 	reportAge = 'Current';    
                 
                 
                  
             	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
             	INTO 	v_currentCount, v_pastCount		
             	FROM 	tmp_result;
                 
                 
            
              
              END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_Inbound_trendchart1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_Inbound_trendchart1`(
 	    p_startTmpstmp 	BIGINT,
    	p_endTmpstmp 	BIGINT,
    	p_domainId 		INT,
  		p_datetype 		INT, 
    	p_columnname 	VARCHAR(155)
    )
BEGIN
    		DECLARE v_startDateTime 				DATETIME;
    		DECLARE v_endDateTime 					DATETIME;
    		DECLARE v_startTmpstmp 					BIGINT;
    		DECLARE v_endTmpstmp 					BIGINT;
    		DECLARE v_startTime	 				    DATETIME;
    		DECLARE v_endTime	 					DATETIME;
    		DECLARE v_currenttimestamp 				BIGINT;
    		DECLARE v_previous_timestamp 			BIGINT;
    		DECLARE v_oneday_previous_timestamp 	BIGINT;
    		DECLARE v1_count_currentdata 		    BIGINT;
    		DECLARE v2_count_pastdata 				BIGINT;
    		DECLARE v_coulumnname                   VARCHAR(150);
    		DECLARE v_interval						INT;
            
             			
    			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
    			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
    			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;      
    			SET v_coulumnname=p_columnname;
                
                
                
                 IF p_datetype = 1 
                 THEN
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    			CREATE TEMPORARY TABLE temp_Intervals (
    			starttime DATETIME,
    			endtime   DATETIME
    			);          
                 
    			    SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day),from_unixtime(p_startTmpstmp/1000));
      			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
 
                set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                
                IF DATEDIFF(v_endDateTime,v_startDateTime) > 29
                THEN
    				SET v_interval = 86400; 
    			ELSEIF DATEDIFF(v_endDateTime,v_startDateTime) > 1
                THEN
    				SET v_interval = 3600; 
                ELSE
                	SET v_interval = 60; 
                END IF;
                     
      			SET v_startTime = v_startDateTime;
    			SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
                     
      			 WHILE v_startTime < v_endDateTime 
      			 DO      
    				 INSERT INTO temp_Intervals (starttime, endtime)
    				 VALUES (v_startTime, v_endTime);
                     
    				SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval second));
    				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval second));
            
    			END WHILE;
     END IF;                   
                IF p_datetype = 2 THEN
    DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    CREATE TEMPORARY TABLE temp_Intervals (
        starttime DATETIME,
        endtime   DATETIME
    );          

    SET v_startDateTime := IF(p_startTmpstmp IS NULL, DATE_SUB(NOW(), INTERVAL 1 DAY), FROM_UNIXTIME(p_startTmpstmp/1000));
    SET v_endDateTime := IF(p_endTmpstmp IS NULL, NOW(), FROM_UNIXTIME(p_endTmpstmp/1000));

    SET v_startTmpstmp = UNIX_TIMESTAMP(v_startDateTime) * 1000;
    SET v_endTmpstmp = UNIX_TIMESTAMP(v_endDateTime) * 1000;

    SET v_interval = 3600; 

    SET v_startTime = v_startDateTime;
    SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
    
    WHILE v_startTime < v_endDateTime DO      
        INSERT INTO temp_Intervals (starttime, endtime)
        VALUES (v_startTime, v_endTime);

        SET v_startTime = DATE_ADD(v_startTime, INTERVAL v_interval SECOND);
        SET v_endTime = DATE_ADD(v_endTime, INTERVAL v_interval SECOND);
    END WHILE;          

END IF;

                 IF p_datetype = 3 THEN
    DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    CREATE TEMPORARY TABLE temp_Intervals (
        starttime DATETIME,
        endtime   DATETIME
    );          

    SET v_startDateTime := IF(p_startTmpstmp IS NULL, DATE_SUB(NOW(), INTERVAL 1 DAY), FROM_UNIXTIME(p_startTmpstmp/1000));
    SET v_endDateTime := IF(p_endTmpstmp IS NULL, NOW(), FROM_UNIXTIME(p_endTmpstmp/1000));

    SET v_startTmpstmp = UNIX_TIMESTAMP(v_startDateTime) * 1000;
    SET v_endTmpstmp = UNIX_TIMESTAMP(v_endDateTime) * 1000;

    SET v_interval = 86400; 

    SET v_startTime = v_startDateTime;
    SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
    
    WHILE v_startTime < v_endDateTime DO      
        INSERT INTO temp_Intervals (starttime, endtime)
        VALUES (v_startTime, v_endTime);

        SET v_startTime = DATE_ADD(v_startTime, INTERVAL v_interval SECOND);
        SET v_endTime = DATE_ADD(v_endTime, INTERVAL v_interval SECOND);
    END WHILE;          

END IF;

                
    			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
    			CREATE TEMPORARY TABLE temp_ChatHistory
    			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
    			FROM 	tb_ChatHistory H 
    			WHERE 	H.domainId = p_domainId
    			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
    			GROUP BY H.sessionStartTime;   
                
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
    			CREATE TEMPORARY TABLE temp_Intervals_1
    			SELECT t_I.endtime 	AS `Time`
    				,	count(1)	AS `NoofreceivedchatCount`
    			FROM temp_Intervals t_I
    			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
    			GROUP BY t_I.endtime;
        
      			SELECT  (t_I.endtime) 						AS `Time`
    				,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedchatcurrentCount
    			FROM 		temp_Intervals t_I 
      			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;             
                     
                     
                     DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory1;
    			CREATE TEMPORARY TABLE temp_ChatHistory1
    			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
    			FROM 	tb_ChatHistory H 
    			WHERE 	H.domainId = p_domainId
    			AND  	H.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
    			GROUP BY H.sessionStartTime;   
                
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
    			CREATE TEMPORARY TABLE temp_Intervals_2
    			SELECT t_I.endtime 	AS `Time`
    				,	count(1)	AS `NoofreceivedchatpastCount`
    			FROM temp_Intervals t_I
    			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
    			GROUP BY t_I.endtime;
        
      			SELECT  (t_I.endtime) 						AS `Time`
					,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedchatCount
    			     FROM 		temp_Intervals t_I 
      			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime; 
               

               
               

 						   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
     	                   DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
     	                   CREATE TEMPORARY TABLE temp_chatHistory AS 
     	SELECT 		CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		   						 						    AS SessionDate
     					,	U.UserID																								AS agentId
                         ,	U.UserName																								AS agentName   
     					,CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '-'	end 								AS abondedchats
                         ,CASE WHEN (SH.repliedDate - SH.createdAt) is not null then (SH.repliedDate - SH.createdAt) else '-' end  	AS responseTime
                         ,CASE WHEN SH.CallBackStatus=1 then 1 else 0 end															AS UnansweredChat
                         ,CASE WHEN SDH.transferredTime is not null then transferredTime else '-' end								AS transferredchat
                         ,CASE WHEN SDH.Duration	is not null then Duration else '-' end												AS chatduration
                         ,CASE WHEN SH.IsInBound=1 THEN 1 ELSE 	0 		END 														AS interactionfromcustomer
                         ,CASE WHEN 	SH.IsInBound=0 THEN 1 ELSE 	0 		END 														AS interactionfromagent
                         ,'-' 																										AS interaction
                         ,'-'																										AS peakchats
                         ,SH.sessionStartTime
                         ,SH.domainId 
                         FROM 	tb_ChatHistory 				     SH
     					JOIN 	tb_ChatDurationHistory		     SDH	ON SH.chatHistoryId = SDH.chatHistoryId  		 
     					LEFT JOIN tb_User					       U	ON U.UserID			= SDH.AgentId
     					WHERE 	SH.domainId 		= p_domainId		
     					AND		SH.IsInBound		= 1	
    					    AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and  @v_endTmpstmp 	;
                         
     	                   DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_1; 
     	                   CREATE TEMPORARY TABLE temp_chatHistory_1 AS 
 
    			SELECT 
     					
                              t_SH.agentName 																				as agentname
                             ,count(1)																						AS receivedchats 
                             ,t_SH.responseTime																				AS respondedchat
                             ,t_SH.abondedchats																				AS abondedchats
                             ,SUM(t_SH.UnansweredChat)																		AS MissedChat   
                             ,t_SH.transferredchat																			AS transferredchat
     						,SUM(t_SH.chatduration)																			AS totalChatduration
                             ,CASE WHEN AVG(t_SH.chatduration)		IS NOT NULL THEN AVG(t_SH.chatduration) ELSE '-' END	AS avgChatduration
                             ,(t_SH.interactionfromcustomer/100)																AS interactionfromcustomer
                             ,(t_SH.interactionfromagent/100)															    AS interactionfromagent
                             ,sum(t_SH.interaction)																			AS totalinteraction
                             ,t_SH.peakchats																					AS peakchats
 							,t_SH.sessionStartTime
                             ,t_SH.domainId 
     						FROM 	temp_chatHistory t_SH
     						GROUP BY   t_SH.agentName,t_SH.responseTime,t_SH.abondedchats,t_SH.transferredchat,t_SH.interactionfromcustomer,
                             t_SH.interactionfromagent,t_SH.interaction,t_SH.peakchats,t_SH.sessionStartTime ,t_SH.domainId ;
     						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
 				
            
        	IF p_columnname = 'ReceviedChats'
            THEN
        		
        		SELECT 	COUNT(1) 
        		INTO 	v1_count_currentdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
                LIMIT 1;
                
        		
        		SELECT COUNT(1)
        		INTO 	v2_count_pastdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
                  LIMIT 1;   
               
               
        ELSEIF         p_columnname = 'RespondedChats'
            THEN
        		
        		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
        		INTO 	v1_count_currentdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
                  LIMIT 1;
                
        		
        		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
        		INTO 	v2_count_pastdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
                  LIMIT 1;
           
        	ELSEIF 
        				p_columnname = 'MISSEDCHAT'
            THEN
        		
        		SELECT   CASE WHEN CallBackStatus=1 then 1 else '0' end MISSEDCHAT
        		INTO 	v1_count_currentdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
                  LIMIT 1;
                
        		
        		SELECT CASE WHEN CallBackStatus=1 then 1 else '0' end MISSEDCHAT
        		INTO 	v2_count_pastdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
                  LIMIT 1;
               
        	ELSEIF p_columnname = 'transferredTime'
            THEN
        		
        		SELECT   CASE WHEN (SDH.transferredTime) is not null then (SDH.transferredTime) else '0' end								AS transferredchat
        		INTO 	v1_count_currentdata 
        		FROM 	tb_ChatDurationHistory  SDH  JOIN
        				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
        		WHERE 	SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	SH.domainId	= p_domainId
                  LIMIT 1;
                
    			
    			SELECT CASE WHEN (SDH.transferredTime) is not null then (SDH.transferredTime) else '0' end								AS transferredchat
    			INTO 	v2_count_pastdata 
    			FROM 	tb_ChatDurationHistory  SDH  
                JOIN	tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
    			WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
    			and 	SH.domainId	= p_domainId
    			LIMIT 1;
               
        	ELSEIF p_columnname = 'abondedchats'
            THEN
        		
        		SELECT CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	end 								AS abondedchats
        		INTO 	v1_count_currentdata 
        		FROM 	tb_ChatDurationHistory  SDH  JOIN
        				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
        		WHERE 	SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '0'	end 								AS abondedchats
        		INTO 	v2_count_pastdata 
        		FROM 	tb_ChatDurationHistory  SDH  JOIN
        				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
        		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;
             
         	ELSEIF p_columnname = 'Total Chat Duration'
            THEN
        		
        		SELECT SUM(chatduration)																			       AS totalChatduration								
        		INTO 	v1_count_currentdata 
             FROM 	temp_chatHistory
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		AND 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT SUM(chatduration)																			       AS totalChatduration	
        		INTO 	v2_count_pastdata 
        		FROM 	temp_chatHistory
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;           
             
             
          	ELSEIF p_columnname = 'Average Chat Duration'
            THEN
        		
        		SELECT sum(avgChatduration)   	   AS avgChatduration							
        		INTO 	v1_count_currentdata 
             FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		AND 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT sum(avgChatduration)   	   AS avgChatduration
        		INTO 	v2_count_pastdata 
        		FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;              
             
            	ELSEIF p_columnname = 'interaction from customer'
            THEN
        		
        		SELECT interactionfromcustomer   	   AS interactionfromcustomer							
        		INTO 	v1_count_currentdata 
             FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		AND 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT interactionfromcustomer   	   AS interactionfromcustomer
        		INTO 	v2_count_pastdata 
        		FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;            
 		
            	ELSEIF p_columnname = 'Interaction From Agent'
            THEN
        		
        		SELECT interactionfromagent   	   AS interactionfromagent							
        		INTO 	v1_count_currentdata 
             FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		AND 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT interactionfromagent   	   AS interactionfromagent
        		INTO 	v2_count_pastdata 
        		FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;           
             
             
              	ELSEIF p_columnname = 'Total interaction'
            THEN
        		
        		SELECT totalinteraction   	   AS totalinteraction							
        		INTO 	v1_count_currentdata 
             FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		AND 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT totalinteraction   	   AS totalinteraction
        		INTO 	v2_count_pastdata 
        		FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;             
             
         
               	ELSEIF p_columnname = 'peak chats'
            THEN
        		
        		SELECT peakchats   	   AS peakchats							
        		INTO 	v1_count_currentdata 
             FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		AND 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT peakchats   	   AS peakchats	
        		INTO 	v2_count_pastdata 
        		FROM 	temp_chatHistory_1
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;  
             
        	END IF;        
                
     		SELECT 	(v1_count_currentdata)	currentdata
        		,	(v2_count_pastdata)		pastdata
        		,	(v1_count_currentdata - v2_count_pastdata) dataDifference 
    			,	(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	          
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Agent_Instagram_Inbound_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Agent_Instagram_Inbound_analysis_metrics_filter`(
        p_startTmpstmp 		BIGINT,
        p_endTmpstmp 		BIGINT,
        p_domainId 			INT,    	
        p_agentId			TEXT,		
        p_offset 			INT,
        p_Limit 			INT	)
sp_return:BEGIN
   			DECLARE v_offset 								INT;	  	
   			DECLARE v_CurrentStartTmpstmp 					BIGINT;
   			DECLARE v_CurrentEndTmpstmp 					BIGINT;
   			DECLARE v_PrevStartTmpstmp 						BIGINT;
   			DECLARE v_PrevEndTmpstmp 						BIGINT; 
   			DECLARE v_TmpstmpInterval						BIGINT;	
      		
       		DECLARE v_CurTotalCount 					INT;
       		DECLARE v_PrevTotalCount 					INT;
       		DECLARE	v_DiffTotalPercent 					INT;
   			
   			DECLARE v_PrevRespondedCount			    INT;	
   			DECLARE v_CurrentRespondedCount			    INT;	        
   			DECLARE v_DiffRespondedPercent			    INT;
   			
       		DECLARE v_PrevAbandonedCount				INT;
       		DECLARE v_CurrentAbandonedCount				INT;
       		DECLARE v_DiffAbandonedPercent				INT;
   			
       		DECLARE v_CurrentMissedCount				INT;
       		DECLARE v_CurrentTransferredCount			INT;
       		DECLARE v_TotalChatDuration					BIGINT;
   			
   
   			DECLARE v_CurrentMaximumChatdurationCount	INT;
   			DECLARE v_CurrentAverageChatdurationCount	INT;
               DECLARE v_TotalTalktime             		BIGINT;
   			DECLARE v_TotalAfterCallWorkTime    		INT;
   			DECLARE v_CurrentCallHoldTime       		INT;
   			DECLARE v_CurrentAvailableTime      		INT;
   			DECLARE v_CurrentCustomerInstagramCount		INT;
   			DECLARE v_CurrentAgentInstagramCount		INT;           
   			DECLARE v_SentimentalScore          		INT;
   			DECLARE v_CurrentFirstCallResolution        INT;
        	
      	SET v_offset =  p_Limit * p_offset; 
        
    	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
    	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
        	
      	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
      
      	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
      	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
        		
     	 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
    		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
   
   
                          		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                      		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                      		(    DispositionId 			INT
                      			,DispositionStatus 		VARCHAR(100)
                      			,DispositionCategory	TINYINT
                      		); 
                              
                      		INSERT INTO temp_AvailableDisposition 
                      		SELECT 	did 			DispositionId
                      			,	dispositionName	DispositionStatus
                      			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                      				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                      				WHEN dispositionName = 'Discarded'     THEN 4
   								WHEN dispositionName = 'Resolved'      THEN 5
                      				END 			DispositionCategory
                      		FROM 	disposition_status
                      		WHERE 	domainId	= p_domainId;
                       	
                       	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                       	CREATE TEMPORARY TABLE temp_AllagentId
                       	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
   
  
    			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
   			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
   			CREATE TEMPORARY TABLE temp_InstagramHistory AS		           
   		    SELECT 	CH.sessionStartTime		
     				,	CH.InstagramHistoryId        
     				,	CH.AgentId
     				,	CH.Istransferred
     				,	CH.dispositionId
     			    ,   CH.IsInBound
     				,	(CH.sessionEndTime - CH.sessionStartTime)	                         AS InstagramChatDuration
     				,   CASE WHEN  (FROM_UNIXTIME(CH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 1 ELSE 0 END AS  MissedChat
     				,	CH.customerInstagramId
                   ,   CH.agentInstagramId
     				,	CH.afterInstagramWorkTime
     			
     				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                 AS discarded
     				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                 AS firstChatResolution 
   				, CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		     	  AS HandledTime
   			
				,CASE WHEN CH.IsSessionClosed =1 Then 1 ELSE 0 END  					  AS responseTime
   				, CH.SentimentalScore
  				,'0'                                                                      AS IsAbandoned     
  				
  				,  CH.Duration                                                            AS chatduration
  				, CH.domainId 
   			FROM 		tb_InstagramHistory 		CH
   			 LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
   			 LEFT JOIN tb_User					     U			ON 	U.UserID				= CH.AgentId
   			 LEFT JOIN temp_agentIDs 			    t_A 		ON 	U.UserID 			    = t_A.agentId   
   			WHERE 	CH.domainId 			= p_domainId 		
   		 	AND 	CH.IsInBound			= 1
   			AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
   			AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
   			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                            
   
   		    DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc; 
   		    CREATE TEMPORARY TABLE temp_InstagramHistory_calc AS 	     
   			SELECT 	
   			t_SH.domainId,
   			t_SH.sessionStartTime,
   			t_SH.InstagramHistoryId,
   			t_SH.AgentId,
   			t_SH.responseTime,
   			t_SH.MissedChat,
   			t_SH.IsInBound,
   			t_SH.Istransferred,
   			t_SH.dispositionId,
   			t_SH.InstagramChatDuration,
   			SUM(t_SH.afterInstagramWorkTime) 															AS afterInstagramWorkTime,
   			t_SH.SentimentalScore,											
   			COUNT(t_SH.agentInstagramId) 																AS InteractionwithAgent,
   			COUNT(DISTINCT t_SH.customerInstagramId) 													AS InteractionWithCustomer,
   			t_SH.discarded 																				AS discardedChat,
   			t_SH.IsAbandoned,											
   			SUM(t_SH.chatduration) 																		AS totalChatduration,
   			CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE '-' END   	AS avgChatduration
   			FROM temp_InstagramHistory t_SH
   			GROUP BY 
   			t_SH.domainId, t_SH.sessionStartTime,t_SH.InstagramHistoryId,t_SH.AgentId,t_SH.responseTime,t_SH.MissedChat,
   			t_SH.IsInBound,t_SH.Istransferred,t_SH.dispositionId,t_SH.InstagramChatDuration,t_SH.SentimentalScore,t_SH.discarded,
   			t_SH.IsAbandoned;
   
   
   			DROP TEMPORARY TABLE IF EXISTS temp_PrevInstagramHistory; 
   			CREATE TEMPORARY TABLE temp_PrevInstagramHistory as
   			SELECT 	DISTINCT InstagramHistoryId 
   			FROM 	temp_InstagramHistory_calc
   			WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
   				
   			DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
   			CREATE TEMPORARY TABLE temp_CurChatHistory AS
   			SELECT 	DISTINCT InstagramHistoryId 
   			FROM 	temp_InstagramHistory_calc
   			WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;              
   
   
   			SELECT 	COUNT(InstagramHistoryId), SUM(responseTime),sum(IsAbandoned)
   			INTO 	v_PrevTotalCount ,v_PrevRespondedCount,v_PrevAbandonedCount
   			FROM	temp_InstagramHistory_calc;
   
   			SELECT 	COUNT(InstagramHistoryId),SUM(responseTime),sum(IsAbandoned)
   			INTO 	v_curTotalCount ,v_CurrentRespondedCount,v_CurrentAbandonedCount	
   			FROM	temp_InstagramHistory_calc;   
   
   
   			SELECT SUM(MissedChat), SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent)
   			INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_CurrentCustomerInstagramCount, v_CurrentAgentInstagramCount
   			FROM 	temp_InstagramHistory_calc;
   
   			SELECT sum(avgChatduration),sum(totalChatduration)
   			INTO 	v_CurrentAverageChatdurationCount, v_CurrentMaximumChatdurationCount
   			FROM 	temp_InstagramHistory_calc;   
   
               SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
       		SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
       		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
   
       		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
       		,	v_DiffRespondedPercent	= (v_CurrentRespondedCount	 - v_PrevRespondedCount) / v_PrevRespondedCount * 100
       		,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100; 
   
  
   			SELECT * FROM temp_AllagentId;         
   
   			SELECT 	IFNULL(v_CurTotalCount,0) 						AS 'TotalReceivedCount',
            			IFNULL(v_DiffTotalPercent,0) 					AS 'DiffTotalReceivedPercent',
            			IFNULL(v_CurrentRespondedCount,0) 				AS 'CurrentRespondedCount',
            			IFNULL(v_DiffRespondedPercent,0) 				AS 'DiffRespondedPercent',
            			IFNULL(v_CurrentAbandonedCount,0) 				AS 'CurrentAbandonedCount',
            			IFNULL(v_DiffAbandonedPercent,0) 				AS 'DiffAbandonedPercent';	             
   
    
        SELECT
              	'All Agents'																					AS agentName
   			,IFNULL(v_CurTotalCount,0)                                    									AS receivedChat
   			,IFNULL(v_CurrentRespondedCount,0)                            									AS respondedChat
               ,IFNULL(v_CurrentAbandonedCount,0)                                                              AS abandonedChat
   			,IFNULL(v_CurrentMissedCount,0)                               									AS missedChat
               ,IFNULL(v_CurrentTransferredCount,0)                          									AS transferredChat
               ,IFNULL(v_TotalChatDuration,0)                   									            AS TotalChatDuration
               ,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS AverageChatDuration
               ,IFNULL(v_CurrentCustomerInstagramCount,0)								    					AS InteractionWithCustomer
               ,IFNULL(v_CurrentAgentInstagramCount,0)															AS InteractionWithAgent
               ,IFNULL(v_CurrentCustomerInstagramCount,0) + IFNULL(v_CurrentAgentInstagramCount,0)			    AS totalInteraction
   
           UNION ALL
        	SELECT 	U.UserName														    						AS agentName
   			 ,	COUNT(1)														    					    	AS receivedChat
   			 ,	SUM(CDH.responseTime)	    						                                        	AS respondedChat
                ,  SUM(CDH.IsAbandoned)                                                                         AS abandonedChat
                ,	SUM(CDH.MissedChat)																		    AS missedSChat        
                ,	SUM(CDH.Istransferred)																		AS transferredChat
                ,	sum(CDH.totalChatduration)																    AS TotalChatDuration
                ,	sum(CDH.avgChatduration) / COUNT(1)														    AS AverageChatDuration
                ,	SUM(CDH.InteractionWithCustomer)															AS InteractionWithCustomer
                ,	SUM(CDH.InteractionwithAgent)																AS InteractionWithAgent
                ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						    AS totalInteraction
            FROM 	temp_InstagramHistory_calc 	  CDH
            JOIN 	temp_AllagentId				U	ON CDH.AgentId	= U.UserID	
           
            GROUP BY U.UserName;               
   
       SELECT CONCAT('agentName','receivedChat', 'respondedChat', 'abandonedChat', 'missedChat', 'transferredChat', 'TotalChatDuration', 'AverageChatDuration','InteractionWithCustomer','InteractionWithCustomer','totalInteraction') AS  columnName;   
   
   	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_services_level_agreement_metrics_analysis` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_services_level_agreement_metrics_analysis`(  
              p_domainId 			INT,
              p_Limit				INT  ,
              p_Offset			    INT
           )
BEGIN
       
            	DECLARE v_Total_count 	INT;
            	DECLARE v_offset		INT;    
       	    DECLARE v_startTmpstmp 	BIGINT;
       	    DECLARE v_endTmpstmp 	BIGINT;  
            	SET v_offset =  p_Limit * p_Offset; 
			
              SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000;        
              SET @v_endTmpstmp 	= unix_timestamp(now())*1000;       
       
      	        
            	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
            	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                       	
             
            	
           	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
            	CREATE TEMPORARY TABLE temp_AllagentId
            	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (5,3); 
                
                 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
          	   CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
 			 SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		          AS SessionDate
 					,U.UserID                                                                 as agentID
 					,U.UserName													      		 AS agentName                     
 					,SDH.Duration                                                       	 AS chatDuration                 
 					,SDH.Duration												      		 AS Duration
              	FROM 	tb_ChatHistory 				SH
              	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
          		LEFT JOIN 	tb_User					U	ON SDH.queueId			= U.UserID  
              	WHERE 	SH.domainId 		= p_domainId	
      			   AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
              	   AND		SH.IsInBound		= 1	
                           LIMIT 	v_offset, p_Limit; 
   
      	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                  	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                  	SELECT 	
     						 a.SessionDate 				       										                                       AS 'Date'                  
     						,a.agentID
     						,a.agentName																                                  
 						,SUM(a.Duration)                                                                                                 AS totalDuration
                         ,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               AS  SL1
     				    ,SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)             AS  SL2
     					,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL3
                         ,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          AS  SL4
                         ,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          AS  SL5
                         ,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          AS  SL6
                         ,sum(CASE WHEN a.chatDuration BETWEEN   1 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  TotalSLA
                         ,(CASE WHEN a.chatDuration > 30000  then 1 else 0 END)								                           AS  MissedChats       
                         FROM temp_ChatHistory a     
                         GROUP BY a.SessionDate,a.agentID,a.agentName,a.chatDuration;
                         
            		SELECT 	COUNT(1) v_Total_Count
            		FROM 	temp_chatHistory_calc a; 
                   
                         SELECT
 						  a.agentName                        
                          ,a.SL1
 						 ,a.SL2
                          ,a.SL3
                          ,a.SL4
                          ,a.SL5
                          ,a.SL6 
                          ,sum(SL1+SL2+SL3+SL4+SL5+SL6)	                                                                                                       AS TotalSLA1        
                          ,a.MissedChats
                          ,CASE WHEN (a.TotalSLA/a.totalDuration) IS NOT NULL THEN (a.TotalSLA/a.totalDuration) ELSE '-' END                                    AS SLAachieved
                          ,CASE WHEN (count(a.MissedChats)/a.totalDuration)*100	IS NOT NULL THEN (count(a.MissedChats)/a.totalDuration)*100  ELSE '-'  END     AS  SLAbreached
                          FROM temp_chatHistory_calc a
    						 GROUP BY a.agentName,a.SL1,a.SL2,a.SL3,a.SL4 ,a.SL5,a.SL6,a.MissedChats,a.TotalSLA,a.totalDuration;
                           
                 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_agent_services_level_metrics_Trend_Chart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_agent_services_level_metrics_Trend_Chart`(
   				    p_startTmpstmp 		BIGINT,
                  	p_endTmpstmp 		BIGINT,
                  	p_domainId 			INT,
 					p_columnname 	VARCHAR(155)
   )
BEGIN
   		DECLARE v_startDateTime 				DATETIME;
   		DECLARE v_endDateTime 					DATETIME;
   		DECLARE v_startTmpstmp 					BIGINT;
   		DECLARE v_endTmpstmp 					BIGINT;
   		DECLARE v_startTime	 				    DATETIME;
   		DECLARE v_endTime	 					DATETIME;
   		DECLARE v_currenttimestamp 				BIGINT;
   		DECLARE v_previous_timestamp 			BIGINT;
   		DECLARE v_oneday_previous_timestamp 	BIGINT;
   		DECLARE v1_count_currentdata 		    BIGINT;
   		DECLARE v2_count_pastdata 				BIGINT;
   		DECLARE v_coulumnname                   VARCHAR(150);
   		DECLARE v_interval						INT;
              
              SET v_coulumnname=p_columnname;
              DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
              CREATE TEMPORARY TABLE temp_Intervals (
               starttime DATETIME,
               endtime   DATETIME
              );
       
 		  SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day),from_unixtime(p_startTmpstmp/1000));
     			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
               
               set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
               set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
               
               IF DATEDIFF(v_endDateTime,v_startDateTime) > 29
               THEN
   				SET v_interval = 86400; 
   			ELSEIF DATEDIFF(v_endDateTime,v_startDateTime) > 1
               THEN
   				SET v_interval = 3600; 
               ELSE
               	SET v_interval = 60; 
               END IF;
                    
     			SET v_startTime = v_startDateTime;
   			SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
                    
     			 WHILE v_startTime < v_endDateTime 
     			 DO      
   				 INSERT INTO temp_Intervals (starttime, endtime)
   				 VALUES (v_startTime, v_endTime);
                    
   				SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval second));
   				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval second));
   			END WHILE;
   			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
   			CREATE TEMPORARY TABLE temp_ChatHistory
   			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
   			FROM 	tb_ChatHistory H 
   			WHERE 	H.domainId = p_domainId
   			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
   			GROUP BY H.sessionStartTime;   
               
   			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
   			CREATE TEMPORARY TABLE temp_Intervals_1
   			SELECT t_I.endtime 	AS `Time`
   				,	count(1)	AS `NoofreceivedchatCount`
   			FROM temp_Intervals t_I
   			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
   			GROUP BY t_I.endtime;
       
     			SELECT  (t_I.endtime) 						AS `Time`
   				,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedchatcurrentCount
   			FROM 		temp_Intervals t_I 
     			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;             
                    
                    
                    DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory1;
   			CREATE TEMPORARY TABLE temp_ChatHistory1
   			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
   			FROM 	tb_ChatHistory H 
   			WHERE 	H.domainId = p_domainId
   			AND  	H.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
   			GROUP BY H.sessionStartTime;   
               
   			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
   			CREATE TEMPORARY TABLE temp_Intervals_2
   			SELECT t_I.endtime 	AS `Time`
   				,	count(1)	AS `NoofreceivedchatpastCount`
   			FROM temp_Intervals t_I
   			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
   			GROUP BY t_I.endtime;
       
     			SELECT  (t_I.endtime) 						AS `Time`
   				,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedchatCount
   			FROM 		temp_Intervals t_I 
     			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime; 
              
   			
   			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
   			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
   			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;  
       
       
       
       
           
           SELECT COUNT(1) INTO v1_count_currentdata
           FROM tb_ChatHistory 
           WHERE sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp;
        
           
           SELECT COUNT(1) INTO v2_count_pastdata
           FROM tb_ChatHistory 
           WHERE sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp;
       
           
           SELECT v1_count_currentdata                      								 									        AS currentdata,
                  v2_count_pastdata                         								 									        AS pastdata,
                  (v1_count_currentdata - v2_count_pastdata) 								 									        AS difference,
                  IFNULL(ROUND(((v1_count_currentdata - v2_count_pastdata) / NULLIF(v1_count_currentdata, 0) * 100), 0), 0)             AS percentage;
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_AI_Agent_Performances_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_AI_Agent_Performances_report`(
     	p_startTmpstmp 		BIGINT,
     	p_endTmpstmp 		BIGINT,
     	p_timeZone 			VARCHAR(200),
     	p_domainId 			INT,
        p_KPI_Name          VARCHAR(200),
     	p_agentId 			TEXT,          
 		p_Limit 			INT,	   
 		p_offset 			INT
      )
BEGIN 
      		DECLARE v_offset				INT;
      		DECLARE v_count 				INT; 
			DECLARE v_startTmpstmp  		BIGINT;
     		DECLARE v_endTmpstmp 			BIGINT;
      
      		SET v_offset =  p_Limit * p_offset;
              
     		IF IFNULL(p_startTmpstmp,0) = 0          
          THEN 	   			
          SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000;    		
          ELSE    			SET v_startTmpstmp = p_startTmpstmp;	           
          END IF; 
             
      		IF IFNULL(p_endTmpstmp,0) = 0 	
             THEN 	
     			SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; 
     		ELSE
     			SET v_endTmpstmp = p_endTmpstmp;
     		END IF;  							
         
        	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));          
			CALL split(p_agentId,',');		INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;  
   
    		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
    		CREATE TEMPORARY TABLE temp_AllagentId
    		select UserID,UserName,domainId from tb_User where domainId = p_domainId;    
   
   
   
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
  	CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
  	SELECT 	CH.sessionStartTime																				AS SessionDate
  		 ,	AA.UserID						        														AS agentId
  		 ,	AA.UserName						        														AS agentName 
  		 ,  CDH.SentimentalScore                        													AS SentimentalScore 
  		 ,	CH.customerNumber        		            													AS customerNumber    
         ,  CH.calledNumber                             													AS calledNumber
         ,  CASE WHEN CH.IsInBound = 0 THEN 'Inbound'  WHEN CH.IsInBound = 1 THEN 'Outbound'  END           AS Direction
  	FROM 	 tb_CallHistory 			    CH                                 
  	JOIN     tb_CallDurationHistory			CDH     ON 	CH.CallHistoryId    = CDH.CallHistoryId     
  	JOIN    customer_contact                CC   	ON  CC.domainId 		= CH.domainId
  													AND CC.coid			    = CH.CustomerId
                                                    
  	LEFT JOIN temp_AllagentId				AA		ON  AA.UserID 		    = CDH.agentId
  													 AND AA.domainId         = CH.domainId   
  	LEFT JOIN temp_agentId 			       	t_A     ON  AA.UserID 		    = t_A.agentId   
  	WHERE 	CH.domainId 					= p_domainId 	
   
  	AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
 	AND 	(IFNULL(p_agentId,'') 			= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));
     
                        
 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  	DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
          	CREATE TEMPORARY TABLE tt_sessionHistory_calc AS   
          	SELECT  SH.SessionDate,
                    0   																	AS KPIName,
				    SH.agentName,                   
                    0                                                                       AS Volume,
                    0,
                    0																		AS Resultvalue,
                    0																		AS GoalValue,
                    0																		AS Meanvalue
          	FROM 	tt_temp_sessionHistory SH;
          	
			 SELECT * from temp_AllagentId;
		      SELECT 	COUNT(1) v_Total_Count
          	FROM 	tt_sessionHistory_calc a;           
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;           
          	SELECT 	a.SessionDate	 																				AS `dateTime`
                  ,a.KPIName
				  ,a.agentName 																						AS agentName           
				  ,a.Volume
                  ,a.Resultvalue
  				  ,a.GoalValue	                 
 				  ,a.Meanvalue                         
          	FROM 	tt_sessionHistory_calc a
 			ORDER BY a.SessionDate DESC
          	LIMIT v_offset, p_limit;            
            

   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_AI_Bot_Performances_Between_Bot_Agent_Report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_AI_Bot_Performances_Between_Bot_Agent_Report`(
               	p_startTmpstmp 		BIGINT,
               	p_endTmpstmp 		BIGINT,
               	p_timeZone 			VARCHAR(200),
               	p_domainId 			INT,
               	p_agentId 			TEXT,  
  				p_queueId 			TEXT,
           		p_Limit 			INT,	   
           		p_offset 			INT
                )
BEGIN 
    			DECLARE v_offset				INT;
    			DECLARE v_count 				INT; 
     			DECLARE v_startTmpstmp  		BIGINT;
     			DECLARE v_endTmpstmp 			BIGINT;
                
        		 SET v_offset =  p_Limit * p_offset;
                        
          IF IFNULL(p_startTmpstmp,0) = 0 THEN SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000; ELSE  SET v_startTmpstmp = p_startTmpstmp;	END IF; 
          IF IFNULL(p_endTmpstmp,0) = 0 THEN SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp;END IF; 
        
        
               	DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
               	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
        
                 
 				CALL split(p_queueId,',');		INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
     		    CALL split(p_agentId,',');		INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
                 
               		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
               		CREATE TEMPORARY TABLE temp_AllqueueId
 					SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
               		
               		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
               		CREATE TEMPORARY TABLE temp_AllagentId
               		select UserID,UserName,domainId from tb_User where domainId = p_domainId;     
                              
                          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                          DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
        				     CREATE TEMPORARY TABLE temp_chatHistory as
          SELECT
              DISTINCT(CM.ChatHistoryId) 																						AS ChatHistoryId,
              FROM_UNIXTIME(CH.sessionStartTime / 1000) 																		AS SessionDate,
  			  
			  CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
			  TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 									AS customerName,               
			  IFNULL(GREATEST(SUM(CM.botMsgCount), 0), 0) 																		AS BotInteraction,              
			  IFNULL(GREATEST(SUM(CM.agentMsgCount), 0), 0) 																	AS agentInteractionCount,
              IFNULL(sum(CASE WHEN CDH.isbot =1 THEN  CDH.EndTime - CDH.StartTime	END),0)  									AS botSessionDuration,
              IFNULL(sum(CASE WHEN CDH.isbot =0 THEN  CDH.EndTime - CDH.StartTime 	END),0) 									AS agentSessionDuration
          FROM
              tb_ChatHistory CH
              JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
              LEFT	JOIN    customer_contact        CC    ON  CC.domainId 		= CH.domainId
        												  AND CC.coid			= CH.CustomerId
              LEFT JOIN  tb_ChatMessage 			CM    ON  CM.ChatHistoryId  = CH.ChatHistoryId  
                                                          AND CM.ChatDurationHistoryId =CDH.ChatDurationHistoryId
         	  LEFT JOIN queue						Q	  ON  CDH.queueId		= Q.qid
         	  LEFT JOIN tb_User						U	  ON  U.UserID			= CDH.AgentId
              LEFT JOIN temp_agentId 			   t_A 	  ON U.UserID 			= t_A.agentId       
         	  LEFT JOIN temp_queueId 			    t_Q   ON  Q.qid				= t_Q.queueId
          WHERE
                    CH.domainId = p_domainId
                AND CH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
            	AND 	(IFNULL(p_queueId,'') 			= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
            	AND 	(IFNULL(p_agentId,'') 			= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))  
         GROUP BY CM.ChatHistoryId,SessionDate,customerName;
          
			
          
          
                    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        			DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
        			CREATE TEMPORARY TABLE tt_sessionHistory_calc AS
                    SELECT
                    SH.SessionDate,
                    SH.customerName,
                    SH.BotInteraction												AS BotInteractionCount,               
                    SH.agentInteractionCount										AS agentInteractionCount,
                    SH.BotInteraction+SH.agentInteractionCount                         AS TotalInteractionCount,
                    SH.botSessionDuration											AS botSessionDuration,
                    SH.agentSessionDuration										    AS agentSessionDuration,								
                    SH.botSessionDuration+SH.agentSessionDuration					AS TotalSessionDuration
                    FROM temp_chatHistory SH;
                    
                    SELECT * from temp_AllqueueId;
        			SELECT * from temp_AllagentId;
        			SELECT 	COUNT(1) v_Total_Count
        			FROM 	tt_sessionHistory_calc a;
                    
                IF((p_limit IS NOT NULL) AND (p_offset IS NOT NULL)) THEN    
                
                    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                    
                 SELECT 	  a.SessionDate	 																				AS `dateTime`   
       					 ,a.customerName																				AS customerName                               
       					 ,a.BotInteractionCount																			AS BotInteractionCount
       					 ,a.agentInteractionCount																		AS agentInteractionCount
      					 ,(a.TotalInteractionCount)                     												AS TotalInteractionCount
       					 ,(a.botSessionDuration)														    			AS botSessionDuration
       					 ,(a.agentSessionDuration)																		AS agentSessionDuration
      					 ,(a.botSessionDuration+a.agentSessionDuration) 												AS TotalSessionDuration
                    	FROM 	tt_sessionHistory_calc a
                     
           			ORDER BY a.SessionDate DESC
                    	LIMIT v_offset, p_limit;        
    			
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
                    
				ELSE
						 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 SELECT 	  a.SessionDate	 																				AS `dateTime`   
       					 ,a.customerName																				AS customerName                               
       					 ,a.BotInteractionCount																			AS BotInteractionCount
       					 ,a.agentInteractionCount																		AS agentInteractionCount
      					 ,(a.TotalInteractionCount)                     												AS TotalInteractionCount
       					 ,(a.botSessionDuration)														    			AS botSessionDuration
       					 ,(a.agentSessionDuration)																		AS agentSessionDuration
      					 ,(a.botSessionDuration+a.agentSessionDuration) 												AS TotalSessionDuration
                    	FROM 	tt_sessionHistory_calc a
                     
           			ORDER BY a.SessionDate DESC;        
    			
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
                
                END IF;
                        end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_AI_Bot_Performances_report` */;
