     SELECT UserID, UserName, ext FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (5, 3);
    
    

    
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     
     DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
     CREATE TEMPORARY TABLE temp_chatHistory AS
     SELECT
         DISTINCT CH.ChatHistoryId,
         CAST(FROM_UNIXTIME(CH.sessionStartTime / 1000) AS DATE) 								AS SessionDate,
        
			FROM_UNIXTIME(CH.sessionStartTime / 1000)											AS HourlyInterval,
         SUM(CASE WHEN CDH.IsBot = 1 AND t_D.DispositionCategory = 6 THEN 1 ELSE 0 END) 		AS resolvedChat,
         SUM(CASE WHEN CDH.IsAbandoned = 1 THEN 1 ELSE 0 END) 									AS abandonedChat,         
         SUM(CASE WHEN CDH.IsBot = 0 THEN 1 ELSE 0 END) 										AS transferredToAgent,
         SUM((CDH.Duration / 1000) + CDH.afterChatWorkTime) 									AS ResponsesTime,
         MIN(CH.sessionEndTime) - MIN(CH.sessionStartTime) 										AS resolutionTime,
         CDH.SentimentalScore
     FROM
         tb_ChatHistory CH
         JOIN tb_ChatDurationHistory CDH ON CH.ChatHistoryId = CDH.ChatHistoryId
         LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
         LEFT JOIN temp_agentId t_A ON U.UserID = t_A.agentId
         LEFT JOIN temp_AvailableDisposition t_D ON CDH.dispositionId = t_D.DispositionId
     WHERE
         CH.domainId = p_domainId
         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
         AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
     GROUP BY HourlyInterval, CDH.SentimentalScore, CH.ChatHistoryId;
    
    	SELECT * FROM temp_AllagentId;
     SELECT COUNT(1) AS totalCount 
     FROM temp_chatHistory;
    
    
    IF((p_Limit IS NOT NULL)AND(p_offset IS NOT NULL)) THEN
    
     DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_1; 
     CREATE TEMPORARY TABLE temp_ChatHistory_1 AS    
     SELECT 
         DISTINCT ChatHistoryId,
         COUNT(1) AS handledChat,
         HourlyInterval,
         resolvedChat,
         abandonedChat,
         transferredToAgent,
         ResponsesTime,
         resolutionTime,
         SentimentalScore
     FROM
         temp_chatHistory 
     GROUP BY 
         ChatHistoryId, HourlyInterval, resolvedChat, abandonedChat, transferredToAgent, ResponsesTime, resolutionTime, SentimentalScore
     ORDER BY 
         HourlyInterval DESC 
     LIMIT v_offset, p_Limit;
     
     ELSE
     
		 DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_1; 
     CREATE TEMPORARY TABLE temp_ChatHistory_1 AS    
     SELECT 
         DISTINCT ChatHistoryId,
         COUNT(1) AS handledChat,
         HourlyInterval,
         resolvedChat,
         abandonedChat,
         transferredToAgent,
         ResponsesTime,
         resolutionTime,
         SentimentalScore
     FROM
         temp_chatHistory 
     GROUP BY 
         ChatHistoryId, HourlyInterval, resolvedChat, abandonedChat, transferredToAgent, ResponsesTime, resolutionTime, SentimentalScore
     ORDER BY 
         HourlyInterval DESC ;
     
     END IF;
    
  
     SELECT
         distinct(a.HourlyInterval) 			AS dateTime,
         sum(a.handledChat) 					as handledChat,
         sum(a.resolvedChat)  				as resolvedChat,
         sum(a.abandonedChat)  				as abandonedChat,
         0 									AS autoClosedByBot,
         0 									AS deflectedByBot,
         sum(a.transferredToAgent)			as transferredToAgent,
         sum(a.ResponsesTime) 				AS averageResponsesTime,
         sum(a.resolutionTime) 				AS averageResolutionTime
     FROM 
         temp_ChatHistory_1 a
         group by a.HourlyInterval;
 END ;;
