CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_AI_Chat_Quality_report`(
      p_startTmpstmp  BIGINT,
      p_endTmpstmp 	 BIGINT,
      p_timeZone 	 VARCHAR(200),
      p_domainId 	 INT,
      p_queueId 	TEXT,
      p_agentId 	TEXT,
      p_direction 	 TINYINT,
      p_Limit 		 INT,
      p_offset 		 INT
  )
BEGIN 
      DECLARE v_offset 		INT;
      DECLARE v_startTmpstmp  BIGINT;
      DECLARE v_endTmpstmp 	BIGINT;
  
      SET v_offset = p_Limit * p_offset;
  
      IF IFNULL(p_startTmpstmp, 0) = 0 THEN
          SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000;
      ELSE
          SET v_startTmpstmp = p_startTmpstmp;
      END IF;
  
      IF IFNULL(p_endTmpstmp, 0) = 0 THEN
          SET v_endTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000;
      ELSE
          SET v_endTmpstmp = p_endTmpstmp;
      END IF;
  
      DROP TEMPORARY TABLE IF EXISTS temp_queueId;
      CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
      DROP TEMPORARY TABLE IF EXISTS temp_agentId;
      CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
      DROP TEMPORARY TABLE IF EXISTS temp_direction;
      CREATE TEMPORARY TABLE temp_direction(directionId VARCHAR(3));
  
      CALL split(p_queueId, ',');
      INSERT INTO temp_queueId(queueId)
          SELECT Items FROM tt_Split_temptable;
  
      CALL split(p_agentId, ',');
      INSERT INTO temp_agentId(agentId)
          SELECT Items FROM tt_Split_temptable;
  
      DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
      CREATE TEMPORARY TABLE temp_AllqueueId
          SELECT qid AS queueId, `name` AS queueName FROM queue WHERE domainId = p_domainId;
  
      DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;
      CREATE TEMPORARY TABLE temp_AllagentId
          SELECT UserID, UserName, domainId FROM tb_User WHERE domainId = p_domainId;
  
      IF p_direction IS NULL OR p_direction IN ('0,1', '1,0') THEN
          INSERT INTO temp_direction (directionId) VALUES (0), (1);
      ELSE
          INSERT INTO temp_direction (directionId) VALUES (p_direction);
      END IF;
  
      DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
      CREATE TEMPORARY TABLE temp_AlldirectionId AS
          SELECT directionId,
                 CASE WHEN directionId = 0 THEN 'OutBound' 
                      WHEN directionId = 1 THEN 'InBound' END AS directionName 
          FROM temp_direction;
  
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory;
      CREATE TEMPORARY TABLE tt_temp_sessionHistory (
          `channel`			 		VARCHAR(10),
          SessionDate 		 		BIGINT,
          agentId 			 		VARCHAR(100),
          agentName 			 		VARCHAR(100),
          queueName 			 		VARCHAR(100),
          SentimentalScore 	 		FLOAT,
          sentimentalScoreCustomer 	FLOAT,
          sentimentalScoreAgent 		FLOAT,
          customerName 				VARCHAR(200),
          Direction 					VARCHAR(20),
          HistoryId 					BIGINT
      );
  
      INSERT INTO tt_temp_sessionHistory (`channel`, SessionDate, agentId, agentName, queueName, SentimentalScore, sentimentalScoreCustomer, sentimentalScoreAgent, customerName, Direction, HistoryId)
      SELECT 'Chat' 								 AS `channel`,
             CH.sessionStartTime					 AS SessionDate,
             U.UserID 							 AS agentId,
             U.UserName AS agentName,
             Q.`name` AS queueName,
             CDH.SentimentalScore,
             CDH.sentimentalScoreCustomer,
             CDH.sentimentalScoreAgent,
             
 			  CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
 			  TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 									AS customerName,               
             CASE WHEN CH.IsInBound = 1 THEN 'Inbound' ELSE 'Outbound' END AS Direction,
             CH.ChatHistoryId AS HistoryId
      FROM tb_ChatHistory CH
      JOIN tb_ChatDurationHistory CDH  ON CH.ChatHistoryId = CDH.ChatHistoryId
      LEFT JOIN customer_contact CC    ON CC.domainId = CH.domainId AND CC.coid = CH.CustomerId
      LEFT JOIN queue Q 				  ON CDH.queueId = Q.qid
      LEFT JOIN tb_User U 			  ON U.UserID = CDH.AgentId
      LEFT JOIN temp_queueId t_Q 	  ON Q.qid = t_Q.queueId
      LEFT JOIN temp_agentId t_A 	  ON U.UserID = t_A.agentId
      LEFT JOIN temp_direction t_d 	  ON t_d.directionId = CH.IsInBound
      WHERE CH.domainId = p_domainId
        AND CDH.IsBot = 0
        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
        AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
        AND (IFNULL(p_direction, '') = '' OR (IFNULL(p_direction, '') <> '' AND t_d.directionId IS NOT NULL));
  
      INSERT INTO tt_temp_sessionHistory (`channel`, SessionDate, agentId, agentName, queueName, SentimentalScore, sentimentalScoreCustomer, sentimentalScoreAgent, customerName, Direction, HistoryId)
      SELECT 'Email' AS `channel`,
             CH.sessionStartTime AS SessionDate,
             U.UserID AS agentId,
             U.UserName AS agentName,
             Q.`name` AS queueName,
             CH.SentimentalScore,
             CH.sentimentalScoreCustomer,
             CH.sentimentalScoreAgent,
 			CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
 			TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 									AS customerName,             
            
             CASE WHEN CH.IsInBound = 1 THEN 'Inbound' ELSE 'Outbound' END AS Direction,
             CH.EmailHistoryId AS HistoryId
      FROM tb_EmailHistory CH
      JOIN tb_EmailDurationHistory CDH ON CH.EmailHistoryId = CDH.EmailHistoryId
      LEFT JOIN customer_contact CC ON CC.domainId = CH.domainId AND CC.coid = CH.CustomerId
      LEFT JOIN queue Q ON CDH.queueId = Q.qid
      LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
      LEFT JOIN temp_queueId t_Q ON Q.qid = t_Q.queueId
      LEFT JOIN temp_agentId t_A ON U.UserID = t_A.agentId
      LEFT JOIN temp_direction t_d ON t_d.directionId = CH.IsInBound
      WHERE CH.domainId = p_domainId
        AND CDH.IsBot = 0
        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
        AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
        AND (IFNULL(p_direction, '') = '' OR (IFNULL(p_direction, '') <> '' AND t_d.directionId IS NOT NULL));
  
      INSERT INTO tt_temp_sessionHistory (`channel`, SessionDate, agentId, agentName, queueName, SentimentalScore, sentimentalScoreCustomer, sentimentalScoreAgent, customerName, Direction, HistoryId)
      SELECT 'SMS' 																												AS `channel`,
             CH.sessionStartTime 																								AS SessionDate,
             U.UserID 																											AS agentId,
             U.UserName 																											AS agentName,
             Q.`name` 																											AS queueName,
             CH.SentimentalScore,
             CH.sentimentalScoreCustomer,
             CH.sentimentalScoreAgent,
             
 			CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
 			TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 									AS customerName,             
             CASE WHEN CH.IsInBound = 1 THEN 'Inbound' ELSE 'Outbound' END 														AS Direction,
             CH.SMSHistoryId 																									AS HistoryId
      FROM tb_SMSHistory CH
      JOIN tb_SMSDurationHistory CDH		ON CH.SMSHistoryId = CDH.SMSHistoryId
      LEFT JOIN customer_contact CC 		ON CC.domainId = CH.domainId AND CC.coid = CH.calledNumber
      LEFT JOIN queue Q 					ON CDH.queueId = Q.qid
      LEFT JOIN tb_User U 				ON U.UserID = CDH.AgentId
      LEFT JOIN temp_queueId t_Q 		ON Q.qid = t_Q.queueId
      LEFT JOIN temp_agentId t_A 		ON U.UserID = t_A.agentId
      LEFT JOIN temp_direction t_d 		ON t_d.directionId = CH.IsInBound
      WHERE CH.domainId = p_domainId
        AND CDH.IsBot = 0
        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
        AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
        AND (IFNULL(p_direction, '') = '' OR (IFNULL(p_direction, '') <> '' AND t_d.directionId IS NOT NULL));
  
  INSERT INTO tt_temp_sessionHistory (`channel`, SessionDate, agentId, agentName, queueName, SentimentalScore, sentimentalScoreCustomer, 
  sentimentalScoreAgent, customerName, Direction, HistoryId)
  
           SELECT 'Whatsapp' 																			AS `channel`,
             CH.sessionStartTime 																		AS SessionDate,
             U.UserID 																					AS agentId,
             U.UserName 																					AS agentName,
             Q.`name` 																					AS queueName,
             CH.SentimentalScore,
             CH.sentimentalScoreCustomer,
             CH.sentimentalScoreAgent,
             
  			CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
 			TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 			AS customerName,           
             CASE WHEN CH.IsInBound = 1 THEN 'Inbound' ELSE 'Outbound' END 								AS Direction,
             CH.WhatsappHistoryId 																		AS HistoryId
      FROM tb_WhatsappHistory CH                       
      JOIN tb_WhatsappDurationHistory CDH ON CH.WhatsappHistoryId = CDH.WhatsappHistoryId
      LEFT JOIN customer_contact CC ON CC.domainId = CH.domainId 
                                    AND CC.coid = CH.customerNumber
      LEFT JOIN queue Q ON CDH.queueId = Q.qid
      LEFT JOIN tb_User U ON U.UserID = CDH.AgentId
      LEFT JOIN temp_queueId t_Q ON Q.qid = t_Q.queueId
      LEFT JOIN temp_agentId t_A ON U.UserID = t_A.agentId
      LEFT JOIN temp_direction t_d ON t_d.directionId = CH.IsInBound
      WHERE CH.domainId = p_domainId
        AND CDH.IsBot = 0
        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
        AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
        AND (IFNULL(p_direction, '') = '' OR (IFNULL(p_direction, '') <> '' AND t_d.directionId IS NOT NULL));
  
  INSERT INTO tt_temp_sessionHistory (`channel`, SessionDate, agentId, agentName, queueName, SentimentalScore, sentimentalScoreCustomer, 
  sentimentalScoreAgent, customerName, Direction, HistoryId)
  
              SELECT 'Facebook' 																				AS `channel`,
             CH.sessionStartTime 																			AS SessionDate,
             U.UserID 																						AS agentId,
             U.UserName 																						AS agentName,
             '-' 																							AS queueName,
             CH.SentimentalScore,					
             CH.sentimentalScoreCustomer,					
             CH.sentimentalScoreAgent,					
             
  			CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
 			TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 				AS customerName,             
             CASE WHEN CH.IsInBound = 1 THEN 'Inbound' ELSE 'Outbound' END   								AS Direction,
             CH.FacebookHistoryId 																			AS HistoryId
      FROM tb_FacebookHistory CH                       
      LEFT JOIN customer_contact CC  ON CC.domainId = CH.domainId  
                                     AND CC.coid = CH.FacebookCommunicationTypeId
      LEFT JOIN tb_User U 			ON U.UserID = CH.AgentId
      LEFT JOIN temp_agentId t_A 	ON U.UserID = t_A.agentId
      LEFT JOIN temp_direction t_d 	ON t_d.directionId = CH.IsInBound
      WHERE CH.domainId = p_domainId
       
        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp      
        AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
        AND (IFNULL(p_direction, '') = '' OR (IFNULL(p_direction, '') <> '' AND t_d.directionId IS NOT NULL)); 
       
    INSERT INTO tt_temp_sessionHistory (`channel`, SessionDate, agentId, agentName, queueName, SentimentalScore, sentimentalScoreCustomer, 
           sentimentalScoreAgent, customerName, Direction, HistoryId)   
       
   SELECT     'Instagram' 												        							AS `channel`,
             CH.sessionStartTime 																			AS SessionDate,
             U.UserID 																						AS agentId,
             U.UserName 																						AS agentName,
             '-' 																							AS queueName,
             CH.SentimentalScore,					
             CH.sentimentalScoreCustomer,					
             CH.sentimentalScoreAgent,					
            
  			CASE WHEN coid IS NOT NULL AND (CC.firstName IS NOT NULL OR CC.lastName IS NOT NULL) THEN 
 			TRIM(CONCAT(IFNULL(CC.firstName, ''), ' ',IFNULL(CC.lastName, '')))ELSE NULL END 				AS customerName,              
             CASE WHEN CH.IsInBound = 1 THEN 'Inbound' ELSE 'Outbound' END    								AS Direction,
             CH.InstagramHistoryId 																			AS HistoryId
      FROM tb_InstagramHistory CH                       
      LEFT JOIN customer_contact CC ON CC.domainId = CH.domainId  
                                    AND CC.coid = CH.InstagramCommunicationTypeId
      LEFT JOIN tb_User U ON U.UserID = CH.AgentId
      LEFT JOIN temp_agentId t_A ON U.UserID = t_A.agentId
      LEFT JOIN temp_direction t_d ON t_d.directionId = CH.IsInBound
      WHERE CH.domainId = p_domainId
  	
        AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp    
        AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
        AND (IFNULL(p_direction, '') = '' OR (IFNULL(p_direction, '') <> '' AND t_d.directionId IS NOT NULL));   
        
        
       
         	         SELECT * from temp_AllqueueId;
 					 SELECT * from temp_AllagentId;
                  	 SELECT 	COUNT(1) v_Total_Count
                  	FROM 	tt_temp_sessionHistory a;
                    
                    
                   IF ((p_limit IS NOT NULL)AND(p_offset IS NOT NULL)) THEN 
                     
                     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;           
                  	SELECT 	a.SessionDate	 																			AS `dateTime`
     					 ,a.agentName 																					AS agentName     
     					 ,a.customerName																				AS customerName                     
  					 ,a.queueName 																						AS queueName
  					 ,a.channel																							AS channelType                               
  					 ,a.Direction																						AS direction                
  					 ,a.SentimentalScore				                                                                AS chatQualityScore 
  					 ,a.sentimentalScoreCustomer				                                                        AS customerSentimentalScore 
  					 ,a.sentimentalScoreAgent				                                                            AS agentSentimentalScore 																
  					 ,a.SentimentalScore				                                    							AS overallInteractionScore           
                  	FROM 	tt_temp_sessionHistory a
         			ORDER BY a.SessionDate DESC
                  	LIMIT v_offset, p_limit;            
                    
                    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;       
                    
				ELSE
                
					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;           
                  	SELECT 	a.SessionDate	 																			AS `dateTime`
     					 ,a.agentName 																					AS agentName     
     					 ,a.customerName																				AS customerName                     
  					 ,a.queueName 																						AS queueName
  					 ,a.channel																							AS channelType                               
  					 ,a.Direction																						AS direction                
  					 ,a.SentimentalScore				                                                                AS chatQualityScore 
  					 ,a.sentimentalScoreCustomer				                                                        AS customerSentimentalScore 
  					 ,a.sentimentalScoreAgent				                                                            AS agentSentimentalScore 																
  					 ,a.SentimentalScore				                                    							AS overallInteractionScore           
                  	FROM 	tt_temp_sessionHistory a
         			ORDER BY a.SessionDate DESC;            
                    
                    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ; 
                    
                    END IF;
           END ;;
DELIMITER ;
