CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_callBackSessionId`(
p_sessionId VARCHAR(250)
)
begin

declare v_errcode	int	default -1;
declare v_errmsg	varchar(50) default 'Updated Failed';

update tb_CallHistory set callBack = 1
where sessionId = p_sessionId ;

if row_count() > 0
then
set v_errcode = 0;
set v_errmsg = 'Updated Successfully';
end if;

select v_errcode as errcode , v_errmsg as errmsg ;

end ;;
DELIMITER ;
