CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_CallCostReport`(
          	p_startTmpstmp 		BIGINT,
          	p_endTmpstmp 		BIGINT,
          	p_timeZone 			VARCHAR(200),
          	p_domainId 			INT,        
          	p_queueIds	 		VARCHAR(250),
  			p_agentIds 			VARCHAR(250),
          	p_Limit 			INT,
          	p_offset 			INT
            )
BEGIN     
           
       	DECLARE v_offset 		INT;
       	DECLARE v_Total_Count 	INT; 
       	DECLARE v_startTmpstmp 	BIGINT;
       	DECLARE v_endTmpstmp 	BIGINT;
       	DECLARE v_temp 			INT;
        
        
               	SET v_offset = p_Limit * p_offset; 
           
       	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
       	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  								
         
 		   DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
           CREATE TEMPORARY TABLE temp_AllqueueId
           select qid,name as queueName from queue where domainId = p_domainId;
           
           DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
           CREATE TEMPORARY TABLE temp_AllagentId
           select Distinct UserID,UserName as AgentName from tb_User where domainId = p_domainId;
           
           
         DROP TEMPORARY TABLE IF EXISTS temp_queueId;	CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
 		 DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
      
         	CALL split(p_queueIds,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
         	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
            
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
			DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
            CREATE TEMPORARY TABLE temp_AllqueueId
            select qid,name as queueName from queue where domainId = p_domainId;
            
			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
			CREATE TEMPORARY TABLE temp_AllagentId          
			select UserID,UserName from tb_User where domainId = p_domainId; 
            
			DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
         	CREATE TEMPORARY TABLE tt_temp_sessionHistory as
            SELECT
				CH.sessionStartTime     	             AS `dateTime`                
  			, 	Q.qid							         AS queueId
  			,	Q.queueName					             AS queueName             
  			,	U.UserID						         AS agentId 
  			,	U.UserName						         AS agentName   
   			,	CH.customerNumber        		         AS customerNumber           
  			,	CONCAT(CC.firstName,' ',CC.lastName)     AS CustomerName   
			,   CASE WHEN CH.IsInBound = 0 THEN 'Inbound'  WHEN CH.IsInBound = 1 THEN 'Outbound'  END           AS Direction
            ,   CASE WHEN CH.customerNumber LIKE '91%' THEN 'India' WHEN CH.customerNumber LIKE '44%' THEN 'USA'WHEN CH.customerNumber LIKE '1%' THEN 'UK'END AS Country
   			,	CH.callDuration						     AS callDuration
 			,	CH.callCost			                     AS callCost   
            ,   CH.calledNumber                          AS calledNumber
  		FROM 	tb_CallHistory 					CH                                                   				
  		  JOIN 	tb_CallDurationHistory			CDH		ON CH.CallHistoryId = CDH.CallHistoryId
          JOIN    customer_contact              CC   	ON CC.domainId 		= CH.domainId
  														AND CC.coid			= CH.CustomerId
  		JOIN 	temp_AllqueueId					Q		ON CDH.QueueId		= Q.qid
  		LEFT JOIN temp_AllagentId				U		ON U.UserID			= CDH.AgentId
  		LEFT JOIN temp_queueId 					t_Q 	ON Q.qid			= t_Q.queueId 
  		LEFT JOIN temp_agentId 					t_A 	ON U.UserID 		= t_A.agentId                
  		WHERE 	CH.domainId 					= p_domainId 	
  		AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
  		AND 	(IFNULL(p_queueIds,'') 			= '' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL))
  		AND 	(IFNULL(p_agentIds,'') 			= '' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
  		
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
             
         	DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
         	CREATE TEMPORARY TABLE tt_sessionHistory_calc AS
 				SELECT 	SH.`dateTime`,
             	SH.queueName, 
 				SH.agentName ,
				SH.customerNumber,
 				SH.CustomerName,
   				SH.Direction,                
                SUM(SH.callDuration)                          AS callDuration, 
				 SH.callCost						          AS callCost,
                 SH.calledNumber                              AS calledNumber,                                    
                 SH.Country                                   AS country
         	FROM 	tt_temp_sessionHistory SH
         	GROUP BY 	SH.`dateTime`,SH.queueName,SH.agentName,SH.customerNumber,SH.CustomerName,SH.Direction,SH.callCost,SH.calledNumber,SH.Country ;
 
                 
 		   SELECT * from temp_AllqueueId;
           SELECT * from temp_AllagentId;
             
         	SELECT 	COUNT(1) v_Total_Count
         	FROM 	tt_sessionHistory_calc a;
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;           
         	SELECT 	a.`dateTime`	 																				AS `dateTime`
   				 ,a.queueName 																						AS queueName
 				 ,a.agentName 																						AS agentName
                 ,a.calledNumber                                                                                    AS contactCenterNumber
                 ,a.country                                                                                         AS country 
				 ,a.Direction																						AS direction                
 				 ,a.customerNumber																					AS customerNumber	
                 ,a.customerName 																					AS customerName
                 ,(a.callDuration/1000)					                                                            AS totalDuration 
                 ,a.callCost                                                                                        AS ratePerMinute																
                 ,(a.callCost*callDuration)                                                                         AS totalCallCost            
         	FROM 	tt_sessionHistory_calc a
			ORDER BY a.`dateTime` DESC
         	LIMIT v_offset, p_limit;
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;         
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_agent_ACW_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_chat_agent_ACW_report`(
      	p_startTmpstmp 		BIGINT,
       	p_endTmpstmp 		BIGINT,
       	p_timeZone 			VARCHAR(200),
       	p_domainId 			INT,        
       	p_queueIds	 		VARCHAR(250),
       	p_agentIds 			VARCHAR(250),
       	p_offset 			INT,
       	p_Limit 			INT)
BEGIN 
       	DECLARE v_offset 		INT;  	
       	DECLARE v_startTmpstmp 	BIGINT;
       	DECLARE v_endTmpstmp 	BIGINT;
       	
       	SET v_offset = p_offset * p_Limit;
         
       	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
       	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
       
       	DROP TEMPORARY TABLE IF EXISTS temp_queueId;	CREATE TEMPORARY TABLE temp_queueId(queueId INT);
       	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId BIGINT);
       
       	CALL split(p_queueIds,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
       	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
            
     	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     	CREATE TEMPORARY TABLE temp_AvailableDisposition 
     	(   DispositionId 			INT
     		,DispositionStatus 		VARCHAR(100)); 
           
      	INSERT INTO temp_AvailableDisposition     
     	SELECT 	did 			DispositionId
     		,	dispositionName	DispositionStatus 		
     	FROM 	disposition_status
     	WHERE 	domainId	= p_domainId;
               
      	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
      	CREATE TEMPORARY TABLE temp_AllqueueId
      	SELECT qid,name as queueName FROM queue WHERE domainId = p_domainId;
      	
      	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
      	CREATE TEMPORARY TABLE temp_AllagentId
      	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId;  
           
     	DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     	CREATE TEMPORARY TABLE temp_chatHistory AS 	
       	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) as SessionDate
     		,	U.UserName							as agentName
     		,	Q.`name`							as queueName                 			
     		,	SDH.EndTime - SDH.StartTime	 		as chatHandlingTime                      
     		,	SDH.afterChatWorkTime				as ACW
     	FROM 	tb_ChatHistory 				SH
     	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId
     LEFT JOIN 	queue						Q	ON SDH.queueId			= Q.qid
     	LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
     	LEFT JOIN tb_User					U	ON U.UserID				= SDH.AgentId
     	LEFT JOIN temp_queueId 				t_Q ON Q.qid				= t_Q.queueId 
     	LEFT JOIN temp_agentId 				t_A ON U.UserID 			= t_A.agentId       
     	WHERE 	SH.domainId 		= p_domainId 		
     	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
     	AND		SH.IsInBound		= 1	
		AND     IsBot =0
     	AND 	(IFNULL(p_queueIds,'')='' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL))
     	AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
           
         DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_1;   	
     	CREATE TEMPORARY TABLE temp_chatHistory_1 AS 	
     	SELECT 	SessionDate						as `date`
     		, 	agentName
     		, 	queueName
     		,	COUNT(1)						as totalInteraction
     		,	SUM(chatHandlingTime)			as totalActiveChatTime
     		,	SUM(chatHandlingTime)/COUNT(1)	as averageActiveChatTime
     		,	SUM(ACW)						as totalACW
     		  
     		,	SUM(ACW)/COUNT(1)				as averageACW
           FROM 	temp_chatHistory
           GROUP BY SessionDate, agentName, queueName; 
          
      	SELECT * from temp_AllqueueId;
      	SELECT * from temp_AllagentId;
     	SELECT * from temp_AvailableDisposition;
          
     	SELECT 	COUNT(1) as totalCount
     	FROM 	temp_chatHistory_1;
        
        
        IF ((p_Limit IS NOT NULL)AND(p_offset IS NOT NULL)) THEN 
        
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;       
     	SELECT 	`date`
     		, 	agentName
     		, 	queueName
     		,	totalInteraction
     		,	totalActiveChatTime
     		,	averageActiveChatTime
     		,	totalACW
     		
     		,	averageACW
     	FROM 	temp_chatHistory_1
         ORDER BY `date` DESC    
     	LIMIT  v_offset, p_Limit;
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
        else
        
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;       
     	SELECT 	`date`
     		, 	agentName
     		, 	queueName
     		,	totalInteraction
     		,	totalActiveChatTime
     		,	averageActiveChatTime
     		,	totalACW
     		
     		,	averageACW
     	FROM 	temp_chatHistory_1
         ORDER BY `date` DESC;
         
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
        END IF;
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_agent_performances_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_agent_performances_analysis_metrics_filter`(  
                 p_startTmpstmp 		BIGINT,
                 p_endTmpstmp 			BIGINT,
                 p_domainId 			INT,    	
                 p_agentId				VARCHAR(250),		
                 p_offset 				INT,
                 p_Limit 				INT	
                          )
BEGIN
                      
      		DECLARE v_offset 						INT;	  	
			DECLARE v_CurrentStartTmpstmp 		BIGINT;
			DECLARE v_CurrentEndTmpstmp 		BIGINT;
                  
      		DECLARE v_PrevStartTmpstmp 				BIGINT;
			DECLARE v_PrevEndTmpstmp 			BIGINT; 
      		DECLARE v_TmpstmpInterval				BIGINT;	
               		
        		DECLARE v_PrevAverageResponseCount		INT;	
        		DECLARE v_CurrentAverageResponseCount	INT;	        
      		DECLARE v_DiffAverageResponsePercent	INT;
              	
         		DECLARE v_PrevAverageHandledCount	INT;	
        		DECLARE v_CurrentAverageHandledCount	INT;
        		DECLARE v_DiffAverageHandledPercent		INT;  	    
                 	
        		DECLARE v_PrevMaximumHandledCount		INT;	
        		DECLARE v_CurrentMaximumHandledCount	INT;	        
      		DECLARE v_DiffMaximumHandledTimePercent	INT;    
                  
         		DECLARE v_PrevTotalACWCount		      	INT;	
        		DECLARE v_CurrentTotalACWCount		  	INT;	        
         		DECLARE v_DiffTotalACWTimePercent	  	INT;   
                  
      		DECLARE v_PrevAverageQueueWaitingCount		    INT;	
        		DECLARE v_CurrentAverageQueueWaitingCount		INT;	        
      		DECLARE v_DiffAverageQueueWaitingPercent		INT; 
                  
              
      		DECLARE v_PrevaverageHoldtCount		        	INT;	
        		DECLARE v_CurrentaverageHoldtCount		    	INT;	        
      		DECLARE v_DiffaverageHoldtPercent		    	INT; 
                  
                 
         		DECLARE v_PrevMaximumQueueWaitingCount		    INT;	
      		DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
         		DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
              
      		DECLARE v_PrevfirstChatResolutionCount		    INT;	
      		DECLARE v_CurrentfirstChatResolutionCount		INT;	        
        		DECLARE v_DifffirstChatResolutionPercent		INT;  
                                  
         		DECLARE v_PreSentimentalScore              		INT;
         		DECLARE v_CurrentSentimentalScore          		INT;
         		DECLARE v_DiffSentimentalScorePercent      		INT;      
                 
      		DECLARE v_PrevAgentIdleTimeCount		      		INT;	
             	DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
      		DECLARE v_DifffirsAgentIdleTimePercent	        	INT;    
                 
         		DECLARE v_PreavailableCount                     bigint;
         		DECLARE v_CurrentavailableCount                 bigint;                      
         		DECLARE v_PretotalTalkCount                     INT;
         		DECLARE v_CurrenttotalTalkCount                 INT;  
          
          
      			DECLARE		v_agentIdleTime						BIGINT;
    			DECLARE		v_averageResponseTime             	BIGINT; 
    			DECLARE		v_averageHandledTime				BIGINT;
    			DECLARE		v_MaximumHandledTime              	BIGINT; 
    			DECLARE		v_totalACWTime						BIGINT;
    			DECLARE		v_averageHoldtime                 	BIGINT; 
    			DECLARE		v_averageQueueWaittime				BIGINT;
    			DECLARE		v_maximumQueueWaittime            	BIGINT; 
    			DECLARE		v_occupancyRate       				BIGINT;
    			DECLARE		v_firstChatResolution             	BIGINT; 
    			DECLARE		v_CustomerSatisfaction				BIGINT; 
                DECLARE		v_IncomingChats						BIGINT; 
          
               	SET v_offset =  p_Limit * p_offset; 
                 
                 	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
                 	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
                 	
               	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
               
               	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
               	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                 		
                 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                 	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
                      
                     	        
                           	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                           	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                      	
                            
                              		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                          		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                          		(    DispositionId 			INT
                          			,DispositionStatus 		VARCHAR(100)
                          			,DispositionCategory	TINYINT
                          		); 
                                  
                          		INSERT INTO temp_AvailableDisposition 
                          		SELECT 	did 			DispositionId
                          			,	dispositionName	DispositionStatus
                          			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                          				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                          				WHEN dispositionName = 'Discarded'     THEN 4
                   					    WHEN dispositionName = 'Resolved'      THEN 5
                          				END 			DispositionCategory
                          		FROM 	disposition_status
                          		WHERE 	domainId	= p_domainId;
                           	
						DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
						CREATE TEMPORARY TABLE temp_FirstCallResolution
						SELECT 
						COUNT(SubQuery.AgentId) AS FirstCallResolution,
						SubQuery.AgentId,SubQuery.ChatHistoryId
						FROM (
						SELECT 
						SDH.AgentId,SH.ChatHistoryId
						FROM tb_ChatHistory SH
						JOIN tb_ChatDurationHistory SDH ON SH.ChatHistoryId = SDH.ChatHistoryId 
						JOIN disposition_status DS ON DS.did = SDH.dispositionId
						WHERE SDH.IsBot = 0
						AND SH.domainId = p_domainId
                        AND SH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp
						GROUP BY SDH.AgentId, SH.ChatHistoryId
						HAVING COUNT(SDH.ChatDurationHistoryId) = 1
						) AS SubQuery
						GROUP BY SubQuery.AgentId,SubQuery.ChatHistoryId;
                            
						
                           	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                           	CREATE TEMPORARY TABLE temp_AllagentId
                           	SELECT UserID,UserName,ext,domainId FROM tb_User WHERE domainId = p_domainId ; 
                               
                  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                           	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
                         	    CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
                               	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		        AS SessionDate
                                      , SDH.AgentId
                                      , CASE WHEN SH.IsMissed =1  THEN 1 ELSE 0 END                           AS agentIdleTime
               					    ,	U.UserName													        AS agentName
               					    , SDH.StartTime                                                         AS agentconnecttime
                                      , SDH.EndTime                                                           AS agentDisconnectTime
                                      , SH.IsInBound
                                      , SDH.Duration                                                          AS callDuration
                                      , SDH.AgentHoldDuration                                               AS agentHoldDuration
                                      ,((SDH.Duration/1000)+SDH.afterChatWorkTime)							AS Handled                                 
  								 , CASE WHEN SH.CallBackStatus=1 THEN 1 ELSE 0 END				      	 	AS UnansweredChat                                             			                 
         							 ,	SDH.EndTime - SDH.StartTime	 								    	AS chatHandlingTime          
     								 , SDH.answeredDuration													AS responseTime                                                                 
  								 , SDH.Duration												          		AS Duration
  								 , SDH.transferredTime						 				          		AS transferredTime							
         							 , SDH.afterChatWorkTime                                       
         							 , SH.queueDuration                                                     AS queueWaitingtime
         							 ,SDH.SentimentalScore
  								 ,case when SH.IsInBound=1 then 1 else 0 end 								AS IncomingChats   
								,t_f.FirstCallResolution 													as firstChatResolution
                             	FROM 	tb_ChatHistory 				SH
                             	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
                             	LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
                             	LEFT JOIN tb_User					U	ON U.UserID				= SDH.AgentId
                             	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
                               JOIN temp_FirstCallResolution 		t_f	ON t_f.ChatHistoryId 	= SDH.chatHistoryId
                             	WHERE 	SH.domainId 		= p_domainId	
								AND 	SH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
              				   AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
              
              
              					DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                                 	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                                 	SELECT 	
                                         t_SH.AgentId
          						      , t_SH.SessionDate
          							  ,t_SH.agentName																              						 		AS agentName
          							  ,SUM(t_SH.agentIdleTime)                                                                                                  AS agentIdleTime
                   					  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     		AS averageResponseTime
                                		  ,	SUM(t_SH.Handled)/COUNT(1)				  							                                                AS averageHandledTime    
                   					  ,	MAX(t_SH.Handled)  						  							                                 					AS MaximumHandledTime 
                   					  ,CASE WHEN SUM(t_SH.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.afterChatWorkTime)/COUNT(1) ELSE 0 END 			AS totalACWTime                    
                   					  ,CASE WHEN SUM(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)/COUNT(1)  ELSE 0 END 			AS averageQueueWaitingtime          
          							  ,CASE WHEN MAX(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)/COUNT(1)  ELSE 0 END          AS maximumQueueWaitingtime  
          							  ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						        AS answeredCall
              						  ,SUM(t_SH.agentHoldDuration)                                                                						        AS callHoldTime
          							  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)							                                                AS totalTalktime
                                       ,t_SH.firstChatResolution
                                       ,sum(t_SH.IncomingChats)                          																		AS IncomingChats
                                        ,t_SH.SentimentalScore                                                                                                  AS CustomerSatisfaction
                                 FROM 	temp_ChatHistory t_SH
                                 GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstChatResolution,t_SH.SentimentalScore;
                  				
                
    				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
      				CREATE TEMPORARY TABLE temp_AvailableStates AS
      				SELECT   
      						CASE 
      							WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
      							ELSE 2 
      						END AS tt_Time,
      						ST.ext,
      						ST.domainId,
      						from_unixtime(ST.startTimestamp/1000),
      						ST.stateDuration as SD
      				FROM     state_timer ST 
      				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
      				WHERE    ST.domainId = p_domainId
      				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
                                    
            ALTER TABLE temp_chatHistory_calc ADD COLUMN availableTime		BIGINT;
                              
          			UPDATE temp_chatHistory_calc SH_C
     				JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
     				JOIN (
     					SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
     					FROM temp_AvailableStates
     					GROUP BY ext, domainId
     				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
     				SET SH_C.availableTime 	= tt_AV.total_SD;
                     
                
              	 SELECT SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(averageQueueWaitingtime),sum(maximumQueueWaitingtime),sum(firstChatResolution),SUM(CustomerSatisfaction),sum(agentIdleTime)
                   INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount, v_CurrentMaximumHandledCount,v_CurrenttotalACWCount,v_CurrentaverageQueueWaitingCount,v_CurrentMaximumQueueWaitingCount,v_CurrentfirstChatResolutionCount,v_CurrentSentimentalScore,v_CurrentAgentIdleTimeCount
                   FROM 	temp_chatHistory_calc ;                                        
                                      
                		
                   SELECT 	SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(averageQueueWaitingtime),sum(maximumQueueWaitingtime),sum(firstChatResolution),SUM(CustomerSatisfaction),sum(agentIdleTime)
                   INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount, v_PrevMaximumHandledCount,v_PrevtotalACWCount,v_PrevaverageQueueWaitingCount,v_PrevMaximumQueueWaitingCount,v_PrevfirstChatResolutionCount,v_PreSentimentalScore,v_PrevAgentIdleTimeCount
                   FROM 	temp_chatHistory_calc ;                     
           
          		SELECT sum(availableTime),sum(totalTalktime)
                  INTO   v_CurrentavailableCount,v_CurrenttotalTalkCount
           	    FROM 	temp_chatHistory_calc  ;    
                 
           	  SELECT sum(availableTime),sum(totalTalktime)
          	  INTO   v_PreavailableCount,v_PretotalTalkCount
           	  FROM 	temp_chatHistory_calc  ;     
                    
               	SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 then null else v_PrevAverageResponseCount end;
               	SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 then null else v_PrevaverageHandledCount end;
                  SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0 then null else v_PreSentimentalScore end;
                      
                      
                  	SET v_DiffAverageResponsePercent  = (v_CurrentaverageResponseCount - v_PrevAverageResponseCount) / v_PrevAverageResponseCount * 100  
             			    ,v_DiffAverageHandledPercent  = (v_CurrentaverageHandledCount - v_PrevaverageHandledCount) / v_PrevaverageHandledCount * 100
              		    ,v_DiffSentimentalScorePercent = (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;        
                      
                     	SELECT * FROM temp_AllagentId;
                     
                 	SELECT 	IFNULL(v_CurrentaverageResponseCount,0) 			AS 'CurrentaverageResponseCount',
                 			IFNULL(v_DiffAverageResponsePercent,0) 		        AS 'DiffAverageResponsePercent',
                 			IFNULL(v_CurrentaverageHandledCount,0) 			    AS 'CurrentAverageHandledCount',
                 			IFNULL(v_DiffAverageHandledPercent,0) 				AS 'DiffAverageHandledPercent',
                 			IFNULL(v_CurrentSentimentalScore,0) 				AS 'CurrentCustomerSatisfactionCount',
                 			IFNULL(v_DiffSentimentalScorePercent,0) 			AS 'DiffCustomerSatisfactionPercent';	
                  
             
    				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_1;
      				CREATE TEMPORARY TABLE temp_chatHistory_calc_1 AS
    				SELECT 															
        			U.UserName 																	                                              AS agentName
        			,sum(a.agentIdleTime)         																							  AS agentIdleTime
        			,sum(a.averageResponseTime)   																							  AS averageResponseTime
        			,sum(a.averageHandledTime)					                                                                          	  AS averageHandledTime
        			,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
        			,sum(a.totalACWTime)          																							  AS totalACWTime
        			,sum(CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE 0 END)               AS averageHoldtime                                  
        			,sum(a.averageQueueWaitingtime)                                                                                           AS averageQueueWaittime
        			,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
        			,sum(CASE WHEN (a.totalTalktime/a.availableTime)*100 IS NOT NULL THEN (a.totalTalktime/a.availableTime)*100 ELSE 0 END)   AS occupancyRate                                      
					,SUM(a.firstChatResolution)                                                                	  							  AS firstChatResolution
					,sum(a.IncomingChats)																									  AS IncomingChats
        			,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
              	 FROM 	temp_chatHistory_calc 	    a
                  JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
              	 GROUP BY U.UserName;  
         		
                
     select  
     sum(agentIdleTime), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
     sum(averageQueueWaittime), sum(maximumQueueWaittime), sum(occupancyRate), sum(firstChatResolution), sum(CustomerSatisfaction),sum(IncomingChats)
    INTO
     v_agentIdleTime, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
    v_averageQueueWaittime, v_maximumQueueWaittime, v_occupancyRate, v_firstChatResolution, v_CustomerSatisfaction,v_IncomingChats
    FROM temp_chatHistory_calc_1;           
                
                
    select 
    			'All Agents'														 AS agentName,	
    			v_agentIdleTime 												 	 AS	agentIdleTime, 
    			v_averageResponseTime                                            	 AS   averageResponseTime,
    			v_averageHandledTime                                                 AS   averageHandledTime, 
    			v_MaximumHandledTime                                               	 AS   MaximumHandledTime,
    			v_totalACWTime                                                       AS  totalACWTime, 
    			v_averageHoldtime                                                    AS  averageHoldtime,
    			v_averageQueueWaittime                                               AS   averageQueueWaittime,
    			v_maximumQueueWaittime                                               AS   maximumQueueWaittime,
    			v_occupancyRate                                                      AS   occupancyRate, 
    			round((v_firstChatResolution /v_IncomingChats) * 100  )              AS  firstChatResolution,
    			v_CustomerSatisfaction												 AS CustomerSatisfaction
              UNION ALL
              select
               DISTINCT(agentName)													AS  agentName, 
    			sum(agentIdleTime) 													AS  agentIdleTime,
    			sum(averageResponseTime)                                            AS  averageResponseTime,
    			sum(averageHandledTime)                                             AS averageHandledTime, 
    			sum(MaximumHandledTime)                                             AS MaximumHandledTime, 
    			sum(totalACWTime)                                                   AS  totalACWTime, 
    			sum(averageHoldtime)                                                AS  averageHoldtime, 
    			sum(averageQueueWaittime)                                           AS averageQueueWaittime,
    			sum(maximumQueueWaittime)                                           AS maximumQueueWaittime,
    			sum(occupancyRate)                                                  AS occupancyRate, 
    			round(sum(firstChatResolution/IncomingChats) *100 )                 AS firstChatResolution,
    			sum(CustomerSatisfaction)											AS CustomerSatisfaction
                FROM 
    			temp_chatHistory_calc_1
    			group by agentName;
    
                END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_agent_performances_analysis_metrics_filter_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_agent_performances_analysis_metrics_filter_1`(  
                p_startTmpstmp 		BIGINT,
                p_endTmpstmp 		BIGINT,
                p_domainId 			INT,    	
                p_agentId			VARCHAR(250),		
                p_offset 			INT,
                p_Limit 				INT	
                         )
BEGIN
                     
     		DECLARE v_offset 						INT;	  	
            	DECLARE v_CurrentStartTmpstmp 		BIGINT;
            	DECLARE v_CurrentEndTmpstmp 		BIGINT;
                 
     		DECLARE v_PrevStartTmpstmp 				BIGINT;
            	DECLARE v_PrevEndTmpstmp 			BIGINT; 
     		DECLARE v_TmpstmpInterval				BIGINT;	
              		
       		DECLARE v_PrevAverageResponseCount		INT;	
       		DECLARE v_CurrentAverageResponseCount	INT;	        
     		DECLARE v_DiffAverageResponsePercent	INT;
             	
        		DECLARE v_PrevAverageHandledCount	INT;	
       		DECLARE v_CurrentAverageHandledCount	INT;
       		DECLARE v_DiffAverageHandledPercent		INT;  	    
                	
       		DECLARE v_PrevMaximumHandledCount		INT;	
       		DECLARE v_CurrentMaximumHandledCount	INT;	        
     		DECLARE v_DiffMaximumHandledTimePercent	INT;    
                 
			DECLARE v_PrevTotalACWCount		      	INT;	
       		DECLARE v_CurrentTotalACWCount		  	INT;	        
			DECLARE v_DiffTotalACWTimePercent	  	INT;   
                 
     		DECLARE v_PrevAverageQueueWaitingCount		    INT;	
       		DECLARE v_CurrentAverageQueueWaitingCount		INT;	        
     		DECLARE v_DiffAverageQueueWaitingPercent		INT; 
                 
             
     		DECLARE v_PrevaverageHoldtCount		        	INT;	
       		DECLARE v_CurrentaverageHoldtCount		    	INT;	        
     		DECLARE v_DiffaverageHoldtPercent		    	INT; 
                 
                
        		DECLARE v_PrevMaximumQueueWaitingCount		    INT;	
     		DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
        		DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
             
     		DECLARE v_PrevfirstChatResolutionCount		    INT;	
     		DECLARE v_CurrentfirstChatResolutionCount		INT;	        
       		DECLARE v_DifffirstChatResolutionPercent		INT;  
                                 
        		DECLARE v_PreSentimentalScore              		INT;
        		DECLARE v_CurrentSentimentalScore          		INT;
        		DECLARE v_DiffSentimentalScorePercent      		INT;      
                
     		DECLARE v_PrevAgentIdleTimeCount		      		INT;	
            	DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
     		DECLARE v_DifffirsAgentIdleTimePercent	        	INT;    
                
        		DECLARE v_PreavailableCount                     bigint;
        		DECLARE v_CurrentavailableCount                 bigint;                      
        		DECLARE v_PretotalTalkCount                     INT;
        		DECLARE v_CurrenttotalTalkCount                 INT;  
         
         
     			DECLARE		v_agentIdleTime						BIGINT;
   			DECLARE		v_averageResponseTime             	BIGINT; 
   			DECLARE		v_averageHandledTime				BIGINT;
   			DECLARE		v_MaximumHandledTime              	BIGINT; 
   			DECLARE		v_totalACWTime						BIGINT;
   			DECLARE		v_averageHoldtime                 	BIGINT; 
   			DECLARE		v_averageQueueWaittime				BIGINT;
   			DECLARE		v_maximumQueueWaittime            	BIGINT; 
   			DECLARE		v_occupancyRate       				BIGINT;
   			DECLARE		v_firstChatResolution             	BIGINT; 
   			DECLARE		v_CustomerSatisfaction				BIGINT;    
   			DECLARE		v_IncomingChats						BIGINT;    
         
              	SET v_offset =  p_Limit * p_offset; 
                
                	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
                	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
                	
              	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
              
              	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
              	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                		
                	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
                     
                    	        
                          	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                          	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                     	
                           
                             		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                         		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                         		(    DispositionId 			INT
                         			,DispositionStatus 		VARCHAR(100)
                         			,DispositionCategory	TINYINT
                         		); 
                                 
                         		INSERT INTO temp_AvailableDisposition 
                         		SELECT 	did 			DispositionId
                         			,	dispositionName	DispositionStatus
                         			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                         				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                         				WHEN dispositionName = 'Discarded'     THEN 4
                  					    WHEN dispositionName = 'Resolved'      THEN 5
                         				END 			DispositionCategory
                         		FROM 	disposition_status
                         		WHERE 	domainId	= p_domainId;
                          	
                          	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                          	CREATE TEMPORARY TABLE temp_AllagentId
                          	SELECT UserID,UserName,ext,domainId FROM tb_User WHERE domainId = p_domainId ; 
                            
						DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
						CREATE TEMPORARY TABLE temp_FirstCallResolution
						SELECT 
						COUNT(SubQuery.AgentId) AS FirstCallResolution,
						SubQuery.AgentId,SubQuery.ChatHistoryId
						FROM (
						SELECT 
						SDH.AgentId,SH.ChatHistoryId
						FROM tb_ChatHistory SH
						JOIN tb_ChatDurationHistory SDH ON SH.ChatHistoryId = SDH.ChatHistoryId 
						JOIN disposition_status DS ON DS.did = SDH.dispositionId
						WHERE SDH.IsBot = 0
						AND SH.domainId = p_domainId
                        AND SH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp
						GROUP BY SDH.AgentId, SH.ChatHistoryId
						HAVING COUNT(SDH.ChatDurationHistoryId) = 1
						) AS SubQuery
						GROUP BY SubQuery.AgentId,SubQuery.ChatHistoryId;
                      
                      select 'temp_FirstCallResolution',a.* from temp_FirstCallResolution a;
                      
                      
                 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                          	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
                        	    CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
                              	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		        AS SessionDate
                                     , SDH.AgentId
                                     , CASE WHEN SH.IsMissed =1  THEN 1 ELSE 0 END                           AS agentIdleTime
              					    ,	U.UserName													        AS agentName
              					    , SDH.StartTime                                                         AS agentconnecttime
                                     , SDH.EndTime                                                           AS agentDisconnectTime
                                     , SH.IsInBound
                                     , SDH.Duration                                                          AS callDuration
                                     , SDH.AgentHoldDuration                                                 AS agentHoldDuration
                                     ,((SDH.Duration/1000)+SDH.afterChatWorkTime)							AS Handled
 								 
 								 , CASE WHEN SH.CallBackStatus=1 THEN 1 ELSE 0 END				      	 	AS UnansweredChat                                             			                 
        							 ,	SDH.EndTime - SDH.StartTime	 								    	  	AS chatHandlingTime          
    								 , SDH.answeredDuration													    AS responseTime                                                                 
 								 , SDH.Duration												          		AS Duration
 								 , SDH.transferredTime						 				          		AS transferredTime							
        							 , SDH.afterChatWorkTime                                       
        							 , SH.queueDuration                                                       	AS queueWaitingtime
        							 ,SDH.SentimentalScore
 								 ,case when SH.IsInBound=1 then 1 else 0 end 								AS IncomingChats                                 
        							
 								
        							
                                    ,t_f.FirstCallResolution as firstChatResolution
                            	FROM 	tb_ChatHistory 				SH
                            	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
                            	LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
                            	LEFT JOIN tb_User					U	ON U.UserID				= SDH.AgentId
                            	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
								JOIN temp_FirstCallResolution 		t_f	ON t_f.ChatHistoryId 	= SDH.chatHistoryId
                            	WHERE 	SH.domainId 		= p_domainId	
                    			   AND 	SH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
                    			
             				   AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
             
             select 'temp_ChatHistory',a.* from temp_ChatHistory a;
             
             					DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                                	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                                	SELECT 	
                                        t_SH.AgentId
         						      , t_SH.SessionDate
         							  ,t_SH.agentName																              						 		AS agentName
         							  ,SUM(t_SH.agentIdleTime)                                                                                                  AS agentIdleTime
                  					  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     		AS averageResponseTime
                               		  ,	SUM(t_SH.Handled)					  							                                                 		AS averageHandledTime    
                  					  ,	MAX(t_SH.Handled) / COUNT(1)						  							                                 		AS MaximumHandledTime 
                  					  ,CASE WHEN SUM(t_SH.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.afterChatWorkTime)/COUNT(1) ELSE 0 END 			AS totalACWTime                    
                  					  ,CASE WHEN SUM(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)/COUNT(1)  ELSE 0 END 			AS averageQueueWaitingtime          
         							  ,CASE WHEN MAX(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)/COUNT(1)  ELSE 0 END          AS maximumQueueWaitingtime  
         							  ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						        AS answeredCall
             						  ,SUM(t_SH.agentHoldDuration)                                                                						        AS callHoldTime
         							  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)							                                                AS totalTalktime
                                       ,t_SH.firstChatResolution
                                       ,sum(t_SH.IncomingChats)                          																		AS IncomingChats
                                       ,t_SH.SentimentalScore                                                                                                  	AS CustomerSatisfaction
                                FROM 	temp_ChatHistory t_SH
                                GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstChatResolution,t_SH.SentimentalScore;
                 				
                                
                select 'temp_chatHistory_calc',a.* from temp_chatHistory_calc a;
                
   				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
     				CREATE TEMPORARY TABLE temp_AvailableStates AS
     				SELECT   
     						CASE 
     							WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
     							ELSE 2 
     						END AS tt_Time,
     						ST.ext,
     						ST.domainId,
     						from_unixtime(ST.startTimestamp/1000),
     						ST.stateDuration as SD
     				FROM     state_timer ST 
     				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
     				WHERE    ST.domainId = p_domainId
     				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
                                   
           ALTER TABLE temp_chatHistory_calc ADD COLUMN availableTime		BIGINT;
                             
         			UPDATE temp_chatHistory_calc SH_C
    				JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
    				JOIN (
    					SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
    					FROM temp_AvailableStates
    					GROUP BY ext, domainId
    				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
    				SET SH_C.availableTime 	= tt_AV.total_SD;
                    
               
             	 SELECT SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(averageQueueWaitingtime),sum(maximumQueueWaitingtime),sum(firstChatResolution),SUM(CustomerSatisfaction),sum(agentIdleTime)
                  INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount, v_CurrentMaximumHandledCount,v_CurrenttotalACWCount,v_CurrentaverageQueueWaitingCount,v_CurrentMaximumQueueWaitingCount,v_CurrentfirstChatResolutionCount,v_CurrentSentimentalScore,v_CurrentAgentIdleTimeCount
                  FROM 	temp_chatHistory_calc ;                                        
                                     
               		
                  SELECT 	SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(averageQueueWaitingtime),sum(maximumQueueWaitingtime),sum(firstChatResolution),SUM(CustomerSatisfaction),sum(agentIdleTime)
                  INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount, v_PrevMaximumHandledCount,v_PrevtotalACWCount,v_PrevaverageQueueWaitingCount,v_PrevMaximumQueueWaitingCount,v_PrevfirstChatResolutionCount,v_PreSentimentalScore,v_PrevAgentIdleTimeCount
                  FROM 	temp_chatHistory_calc ;                     
          
         		SELECT sum(availableTime),sum(totalTalktime)
                 INTO   v_CurrentavailableCount,v_CurrenttotalTalkCount
          	    FROM 	temp_chatHistory_calc  ;    
                
          	  SELECT sum(availableTime),sum(totalTalktime)
         	  INTO   v_PreavailableCount,v_PretotalTalkCount
          	  FROM 	temp_chatHistory_calc  ;     
                   
              	SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 then null else v_PrevAverageResponseCount end;
              	SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 then null else v_PrevaverageHandledCount end;
                 SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0 then null else v_PreSentimentalScore end;
                     
                     
                 	SET v_DiffAverageResponsePercent  = (v_CurrentaverageResponseCount - v_PrevAverageResponseCount) / v_PrevAverageResponseCount * 100  
            			    ,v_DiffAverageHandledPercent  = (v_CurrentaverageHandledCount - v_PrevaverageHandledCount) / v_PrevaverageHandledCount * 100
             		    ,v_DiffSentimentalScorePercent = (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;        
                     
                    	SELECT * FROM temp_AllagentId;
                    
                	SELECT 	IFNULL(v_CurrentaverageResponseCount,0) 			AS 'CurrentaverageResponseCount',
                			IFNULL(v_DiffAverageResponsePercent,0) 		        AS 'DiffAverageResponsePercent',
                			IFNULL(v_CurrentaverageHandledCount,0) 			    AS 'CurrentAverageHandledCount',
                			IFNULL(v_DiffAverageHandledPercent,0) 				AS 'DiffAverageHandledPercent',
                			IFNULL(v_CurrentSentimentalScore,0) 				AS 'CurrentCustomerSatisfactionCount',
                			IFNULL(v_DiffSentimentalScorePercent,0) 			AS 'DiffCustomerSatisfactionPercent';	
                 
            
   				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_1;
     				CREATE TEMPORARY TABLE temp_chatHistory_calc_1 AS
   				SELECT 															
       			U.UserName 																	                                              AS agentName
       			,sum(a.agentIdleTime)         																							  AS agentIdleTime
       			,sum(a.averageResponseTime)   																							  AS averageResponseTime
       			,sum(a.averageHandledTime/1000)					                                                                          AS averageHandledTime
       			,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
       			,sum(a.totalACWTime)          																							  AS totalACWTime
       			,sum(CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE 0 END)               AS averageHoldtime                                  
       			,sum(a.averageQueueWaitingtime)                                                                                           AS averageQueueWaittime
       			,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
       			,sum(CASE WHEN (a.totalTalktime/a.availableTime)*100 IS NOT NULL THEN (a.totalTalktime/a.availableTime)*100 ELSE 0 END)   AS occupancyRate                                      
       			,SUM(a.firstChatResolution)                                                                	  								AS firstChatResolution
                
                ,sum(a.IncomingChats)			AS IncomingChats
       			,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
             	 FROM 	temp_chatHistory_calc 	    a
                 JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
               
             	 GROUP BY U.UserName;  
        		
               
    select  
    sum(agentIdleTime), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
    sum(averageQueueWaittime), sum(maximumQueueWaittime), sum(occupancyRate), sum(firstChatResolution), sum(CustomerSatisfaction),sum(IncomingChats)
   INTO
    v_agentIdleTime, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
   v_averageQueueWaittime, v_maximumQueueWaittime, v_occupancyRate, v_firstChatResolution, v_CustomerSatisfaction,v_IncomingChats
   FROM temp_chatHistory_calc_1;           
               
               
   select 
   			'All Agents'														 AS agentName,	
   			v_agentIdleTime 												 	 AS	agentIdleTime, 
   			v_averageResponseTime                                            	 AS   averageResponseTime,
   			v_averageHandledTime                                                 AS   averageHandledTime, 
   			v_MaximumHandledTime                                               	 AS   MaximumHandledTime,
   			v_totalACWTime                                                       AS  totalACWTime, 
   			v_averageHoldtime                                                    AS  averageHoldtime,
   			v_averageQueueWaittime                                               AS   averageQueueWaittime,
   			v_maximumQueueWaittime                                               AS   maximumQueueWaittime,
   			v_occupancyRate                                                      AS   occupancyRate, 
   			round((v_firstChatResolution /v_IncomingChats) * 100  )              AS  firstChatResolution,
            v_firstChatResolution												 AS  fcResolution,
            v_IncomingChats														 AS IncomingChats,
   			v_CustomerSatisfaction												 AS CustomerSatisfaction
             UNION ALL
             select
              DISTINCT(agentName)													AS  agentName, 
   			sum(agentIdleTime) 													AS  agentIdleTime,
   			sum(averageResponseTime)                                            AS  averageResponseTime,
   			sum(averageHandledTime)                                             AS averageHandledTime, 
   			sum(MaximumHandledTime)                                             AS MaximumHandledTime, 
   			sum(totalACWTime)                                                   AS  totalACWTime, 
   			sum(averageHoldtime)                                                AS  averageHoldtime, 
   			sum(averageQueueWaittime)                                           AS averageQueueWaittime,
   			sum(maximumQueueWaittime)                                           AS maximumQueueWaittime,
   			sum(occupancyRate)                                                  AS occupancyRate, 
   			round(sum(firstChatResolution/IncomingChats) *100 )                 AS firstChatResolution,
            sum(firstChatResolution)											AS firstChatResolution,
            sum(IncomingChats)													AS IncomingChats,
   			sum(CustomerSatisfaction)											AS CustomerSatisfaction
   			
               FROM 
   			temp_chatHistory_calc_1
   			group by agentName;
   
               END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_agent_performances_metrics_analysis` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_agent_performances_metrics_analysis`(  
              p_domainId 			INT,
              p_Limit				INT,
              p_Offset			    INT
           )
BEGIN
       
   				DECLARE v_Total_count 	INT;
				DECLARE v_offset		INT;    
       	        DECLARE v_startTmpstmp 	BIGINT;
       	        DECLARE v_endTmpstmp 	BIGINT;  
   		   SET v_offset =  p_Limit * p_Offset; 
       	   SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000;        
		   SET @v_endTmpstmp 	= unix_timestamp(now())*1000;       
       
      	        
            	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
            	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                       	
             
               		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
           		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
           		(    DispositionId 			INT
           			,DispositionStatus 		VARCHAR(100)
           			,DispositionCategory	TINYINT
           		); 
                   
           		INSERT INTO temp_AvailableDisposition 
           		SELECT 	did 			DispositionId
           			,	dispositionName	DispositionStatus
           			,	CASE WHEN dispositionName = 'Opened'	THEN 2
           				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
           				WHEN dispositionName = 'Discarded'     THEN 4
    					    WHEN dispositionName = 'Resolved'      THEN 5
           				END 			DispositionCategory
           		FROM 	disposition_status
           		WHERE 	domainId	= p_domainId;
            	
            	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
            	CREATE TEMPORARY TABLE temp_AllagentId
            	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (5,3); 
                
   			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
          	    CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
                	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		      AS SessionDate
                       , SDH.AgentId
					   ,	U.UserName													      AS agentName
					   , SDH.StartTime                                                        AS agentconnecttime
                       , SDH.EndTime                                                          AS agentDisconnectTime
                       , SH.IsInBound
                       , SDH.Duration                                                         AS callDuration
                       , SDH.AgentHoldDuration                                                AS agentHoldDuration
					   , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		      AS Handled		
                       , CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END              AS firstChatResolution
     				    , CASE WHEN SH.CallBackStatus=1 THEN 1 ELSE 0 END				      AS UnansweredChat                                             		
              		    ,	SDH.EndTime - SDH.StartTime	 								      AS chatHandlingTime          
          			    ,	SH.repliedDate - SH.createdAt								      AS responseTime
         			    , SDH.Duration												          AS Duration
         			    , SDH.transferredTime						 				          AS transferredTime							
          			    , SDH.afterChatWorkTime                                       
   				    , SH.queueDuration                                                        AS queueWaitingtime
   					,SDH.SentimentalScore
              	FROM 	tb_ChatHistory 				SH
              	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
              	LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
              	LEFT JOIN tb_User					U	ON U.UserID				= SDH.AgentId
              	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
              	WHERE 	SH.domainId 		= p_domainId	
      			   AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
              	   AND		SH.IsInBound		= 1	;
       		      
                  
                          	DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                  	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                  	SELECT 	
                              t_SH.SessionDate 				       										              AS 'Date'
                          ,    t_SH.agentId      
                  		  ,	t_SH.agentName																              						 AS agentName
    					  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     AS averageResponseTime
                 		  ,	SUM(t_SH.Handled)					  							                                                 AS averageHandledTime    
    					  ,	MAX(t_SH.Handled) / COUNT(1)						  							                                 AS MaximumHandledTime 
    					  ,CASE WHEN SUM(t_SH.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.afterChatWorkTime)/COUNT(1) ELSE '-' END AS totalACWTime                      
    					  ,CASE WHEN SUM(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)/COUNT(1)  ELSE '-' END AS averageQueueWaitingtime          
                          ,CASE WHEN MAX(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)/COUNT(1)  ELSE '-' END AS maximumQueueWaitingtime          
                 		  ,	COUNT(1)							               							             						 AS totalReceived    
                          ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						 AS answeredCall
                  		  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)										     						 AS totalTalktime
                          ,SUM(t_SH.agentHoldDuration)                                                                						 AS callHoldTime
          			      ,	SUM(t_SH.transferredTime)				                                                 						 AS totaltransferredchat
          			      ,	SUM(t_SH.UnansweredChat)			                   								     						 AS totalMissedChat   
          			      ,	SUM(t_SH.Duration)						               								     						 AS totalActiveChatTime            			
                 		  ,	SUM(t_SH.chatHandlingTime)/COUNT(1)	                   								     						 AS averageActiveChatTime
   					      ,t_SH.firstChatResolution
                          ,  t_SH.SentimentalScore
                  FROM 	temp_ChatHistory t_SH
                  GROUP BY t_SH.SessionDate,t_SH.SentimentalScore,t_SH.agentId,t_SH.firstChatResolution,t_SH.agentName
   				LIMIT v_offset, p_limit;
       

                  		SELECT 	COUNT(1) v_Total_Count
                  		FROM 	temp_chatHistory_calc a; 
                         
         				ALTER TABLE temp_chatHistory_calc ADD COLUMN availableTime		INT;      
                        
                         UPDATE 	temp_chatHistory_calc	SH_C
                         JOIN 	temp_AllagentId			t_A		ON 	SH_C.agentId = t_A.UserID        
                         SET 	agentName		= t_A.UserName 
                 			,	availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.timerStatusId =	1  THEN S.stateDuration ELSE 0 END) 
                 									FROM 	state_timer S	
                                                     WHERE  	S.domainId	= p_domainId
                                                     AND 	S.ext			= t_A.ext);
                                                     
                  SELECT 															
    							   a.agentName 																	                                      AS agentName
    							  ,a.averageResponseTime
                                 ,a.averageHandledTime/1000					                                                                      AS averageHandledTime
                                 ,a.MaximumHandledTime
                                 ,a.totalACWTime
                                 ,CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE '-' END            AS averageHoldtime
                                 ,a.averageQueueWaitingtime                                                                                          AS averageQueueWaittime
                                 ,a.maximumQueueWaitingtime                                                                                          AS maximumQueueWaittime
    						      ,CASE WHEN (a.totalTalktime/a.availableTime)*100 IS NOT NULL THEN (a.totalTalktime/a.availableTime)*100 ELSE '-' END AS occupancyRate                              
                                 ,a.firstChatResolution                                                                                              AS firstChatResolution
                                 ,CASE WHEN a.SentimentalScore  IS NOT NULL THEN a.SentimentalScore  ELSE '-' END                                    AS CustomerSatisfaction
         				FROM 	temp_chatHistory_calc 	a;
                        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
