CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_performances_metrics_analysis`(  
             p_domainId 			INT,
             p_Limit				INT,
             p_Offset			    INT
          )
BEGIN
      
  				DECLARE v_Total_count 	INT;
           	    DECLARE v_offset		INT;    
      	        DECLARE v_startTmpstmp 	BIGINT;
      	        DECLARE v_endTmpstmp 	BIGINT;  
  		   SET v_offset =  p_Limit * p_Offset; 
      	   SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000;        
             SET @v_endTmpstmp 	= unix_timestamp(now())*1000;       
      
     	        
         	    DROP TEMPORARY TABLE IF EXISTS temp_queueIds; 	    CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
           	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
           	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                      	
            
              		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
          		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
          		(    DispositionId 			INT
          			,DispositionStatus 		VARCHAR(100)
          			,DispositionCategory	TINYINT
          		); 
                  
          		INSERT INTO temp_AvailableDisposition 
          		SELECT 	did 			DispositionId
          			,	dispositionName	DispositionStatus
          			,	CASE WHEN dispositionName = 'Opened'	THEN 2
          				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
          				WHEN dispositionName = 'Discarded'     THEN 4
   					    WHEN dispositionName = 'Resolved'      THEN 5
          				END 			DispositionCategory
          		FROM 	disposition_status
          		WHERE 	domainId	= p_domainId;
           	
           	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
           	CREATE TEMPORARY TABLE temp_AllagentId
           	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3);    
               
           	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
           	CREATE TEMPORARY TABLE temp_AllqueueId
           	SELECT qid,name AS queueName FROM queue WHERE domainId = p_domainId;
           
  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
         	    CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
               	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		      AS SessionDate
                      , SDH.AgentId
                      , SDH.QueueId
   				    ,	U.UserName													      AS agentName
   				    ,CASE WHEN Q.name IS NOT NULL THEN Q.name ELSE '-'  END         	  AS queueName
    				    , SDH.StartTime                                                       AS agentconnecttime
                      , SDH.EndTime                                                         AS agentDisconnectTime
                      , SH.IsInBound
                      , SDH.Duration                                                        AS callDuration
                      , SDH.AgentHoldDuration                                               AS agentHoldDuration
             		    , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		      AS Handled		
                      , CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END             AS firstChatResolution
    				    , CASE WHEN SH.CallBackStatus=1 THEN 1 ELSE 0 END				      AS UnansweredChat                                             		
             		    ,	SDH.EndTime - SDH.StartTime	 								      AS chatHandlingTime          
         			    ,	SH.repliedDate - SH.createdAt								      AS responseTime
        			    , SDH.Duration												          AS Duration
        			    , SDH.transferredTime						 				          AS transferredTime							
         			    , SDH.afterChatWorkTime                                       
  				    , SH.queueDuration                                                    AS queueWaitingtime
  					,SDH.SentimentalScore
             	FROM 	tb_ChatHistory 				SH
             	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
         		LEFT JOIN 	queue					Q	ON SDH.queueId			= Q.qid
             	LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
             	LEFT JOIN tb_User					U	ON U.UserID				= SDH.AgentId
             	LEFT JOIN temp_queueIds 			t_Q ON Q.qid				= t_Q.queueId 
             	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
             	WHERE 	SH.domainId 		= p_domainId	
     			   AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
             	   AND		SH.IsInBound		= 1	;
    
      		      
                         	DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                 	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                 	SELECT 	
                             t_SH.SessionDate 				       										              AS 'Date'
                        ,    t_SH.agentId      
                        ,    t_SH.QueueId
                 		  ,	t_SH.agentName																              						 AS agentName
                		  ,	t_SH.queueName																              						 AS queueName
   					  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     AS averageResponseTime
                		  ,	SUM(t_SH.Handled)					  							                                                 AS averageHandledTime    
   					  ,	MAX(t_SH.Handled) / COUNT(1)						  							                                 AS MaximumHandledTime 
   					  ,CASE WHEN SUM(t_SH.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.afterChatWorkTime)/COUNT(1) ELSE '-' END AS totalACWTime                      
   					  ,CASE WHEN SUM(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)/COUNT(1)  ELSE '-' END AS averageQueueWaitingtime          
                        ,CASE WHEN MAX(t_SH.queueWaitingtime)/COUNT(1)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)/COUNT(1)  ELSE '-' END AS maximumQueueWaitingtime          
                		  ,	COUNT(1)							               							             						 AS totalReceived    
                        ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						 AS answeredCall
                 		  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)										     						 AS totalTalktime
                        ,SUM(t_SH.agentHoldDuration)                                                                						 AS callHoldTime
         			      ,	SUM(t_SH.transferredTime)				                                                 						 AS totaltransferredchat
         			      ,	SUM(t_SH.UnansweredChat)			                   								     						 AS totalMissedChat   
         			      ,	SUM(t_SH.Duration)						               								     						 AS totalActiveChatTime            			
                		  ,	SUM(t_SH.chatHandlingTime)/COUNT(1)	                   								     						 AS averageActiveChatTime
  					  ,t_SH.firstChatResolution
                        ,  t_SH.SentimentalScore
                 FROM 	temp_ChatHistory t_SH
                 GROUP BY t_SH.SessionDate, t_SH.queueName,t_SH.SentimentalScore,t_SH.agentId,t_SH.QueueId,t_SH.firstChatResolution,t_SH.agentName
  				LIMIT v_offset, p_limit;
      
                 		SELECT 	COUNT(1) v_Total_Count
                 		FROM 	temp_chatHistory_calc a; 
                        
        				ALTER TABLE temp_chatHistory_calc ADD COLUMN availableTime		INT;      
                       
                        UPDATE 	temp_chatHistory_calc	SH_C
                        JOIN 	temp_AllagentId			t_A		ON 	SH_C.agentId = t_A.UserID        
                        SET 	agentName		= t_A.UserName 
                			,	availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.timerStatusId =	1  THEN S.stateDuration ELSE 0 END) 
                									FROM 	state_timer S	
                                                    WHERE  	S.domainId	= p_domainId
                                                    AND 	S.ext			= t_A.ext);
                                                    
                 SELECT 															
   							   a.queueName 																	                                      AS queueName
   							  ,a.averageResponseTime
                                ,a.averageHandledTime/1000					                                                                      AS averageHandledTime
                                ,a.MaximumHandledTime
                                ,a.totalACWTime
                                ,CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE '-' END            AS averageHoldtime
                                ,a.averageQueueWaitingtime                                                                                          AS averageQueueWaittime
                                ,a.maximumQueueWaitingtime                                                                                          AS maximumQueueWaittime
   						      ,CASE WHEN (a.totalTalktime/a.availableTime)*100 IS NOT NULL THEN (a.totalTalktime/a.availableTime)*100 ELSE '-' END AS occupancyRate                              
                                ,a.firstChatResolution                                                                                              AS firstChatResolution
                                ,CASE WHEN a.SentimentalScore  IS NOT NULL THEN a.SentimentalScore  ELSE '-' END                                    AS CustomerSatisfaction
        				FROM 	temp_chatHistory_calc 	a;
                       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_performances_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_performances_metrics_filter`(
      		p_startTmpstmp 		BIGINT,
          	p_endTmpstmp 		BIGINT,
          	p_domainId 			INT,
  			p_queueId 			VARCHAR(250),
      		p_offset 			INT,      
  			p_Limit 			INT	   
      	)
sp_return:begin
 			DECLARE v_offset 					INT;	
 			DECLARE v_Total_Count 				INT;        
 			DECLARE v_startTmpstmp 				BIGINT;
 			DECLARE v_endTmpstmp 				BIGINT;
 			DECLARE v_currenttimestamp    		DATETIME;
 			DECLARE v_previous_timestamp 	    DATETIME;
 			DECLARE v_oneday_previous_timestamp DATETIME;
 			DECLARE v1_count_currentdata 		INT;
 			DECLARE v1_count_pastdata 			INT;
 			DECLARE v2_count_currentdata		INT;
 			DECLARE v2_count_pastdata			INT;
             DECLARE v3_count_currentdata		INT;
 			DECLARE v3_count_pastdata			INT;
             
  			SET v_offset =  p_Limit * p_offset;   
                        
              	IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +3 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
              	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
              
   
              	DROP TEMPORARY TABLE IF EXISTS temp_queueId; 	    CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
              	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
              
 					CALL split(p_queueId,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
 
               
                 		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
             		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
             		(    DispositionId 			INT
             			,DispositionStatus 		VARCHAR(100)
             			,DispositionCategory	TINYINT
             		); 
             		INSERT INTO temp_AvailableDisposition 
             		SELECT 	did 			DispositionId
             			,	dispositionName	DispositionStatus
             			,	CASE WHEN dispositionName = 'Opened'	THEN 2
             				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
             				WHEN dispositionName = 'Discarded' THEN 4
      					    WHEN dispositionName = 'Resolved'  THEN 5
             				END 			DispositionCategory
             		FROM 	disposition_status
             		WHERE 	domainId	= p_domainId;
              	
              	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
  			CREATE TEMPORARY TABLE temp_AllqueueId
  			select qid,name as queueName from queue where domainId = p_domainId;    
                  
     		           
              SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
              DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
             	CREATE TEMPORARY TABLE temp_chatHistory as
      
              SELECT 	 
      					 CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 		   						 						AS SessionDate
   						,Q.qid																											AS queueId
 						,CASE WHEN Q.name IS NOT NULL THEN Q.name ELSE '-'  END         												AS queueName
 						,CASE WHEN avg(CH.repliedDate - CH.createdAt) is not null then (CH.repliedDate - CH.createdAt) else '-' end  	AS avgresponseTime
 						,CASE WHEN avg(t_D.DispositionCategory =3) THEN 1 ELSE 0 END		                                           	AS avgHandled
  						,CDH.SentimentalScore	                         
      			 FROM 	tb_ChatHistory 			  CH
      			 JOIN 	tb_ChatDurationHistory	  CDH       ON CH.ChatHistoryId = CDH.ChatHistoryId
  			LEFT JOIN 	queue				        Q	 ON CDH.QueueId		= Q.qid
             LEFT JOIN   temp_queueId 		       t_Q   ON Q.qid			= t_Q.queueId 
   			LEFT JOIN 	temp_AvailableDisposition	t_D	 ON CDH.dispositionId= t_D.DispositionId            
      			 WHERE 	CH.domainId 			= p_domainId
      		 	 AND 	CH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp 
 				 AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
                  group by CH.sessionStartTime,Q.name,Q.qid	,CDH.SentimentalScore,CH.repliedDate,CH.createdAt
      			 LIMIT 	 v_offset, p_Limit;  
      		
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
 				SELECT * from temp_AllqueueId;                   
                 
             
     		 
              
              
 
    
     		
     		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
     	 	INTO 	v1_count_currentdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		and 	domainId	= p_domainId
 			LIMIT 1;
             
     		
     		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
     		INTO 	v1_count_pastdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	domainId	= p_domainId
 			LIMIT 1;
             
 	
             
             
 		 SELECT 
 			CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
 			into v2_count_currentdata   
 			FROM temp_AvailableDisposition 
 			WHERE p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
             LIMIT 1; 
 		
 			SELECT 	CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
 			into v2_count_pastdata 
 			FROM temp_AvailableDisposition 
 			WHERE p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
 			 LIMIT 1;
        
 			select  SentimentalScore
             into  	v3_count_currentdata
 			from 	tb_ChatDurationHistory
 			where 	p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
               LIMIT 1; 
        
 			select  SentimentalScore
             into  	v3_count_pastdata
 			from 	tb_ChatDurationHistory
 			WHERE 	p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
              LIMIT 1;
           
  					IF NOT EXISTS(SELECT 1 FROM temp_chatHistory limit 1) then
     					SELECT '0' as queueName, '0' AS averageResponseTime, '0' AS ResponseTimeincreasedby, '0' AS averageHandledTime, '0' AS HandledTimeincreasedby ,
  					'0' AS totalabondedchats ,'0' AS abondedchatssincreasedby;
                                           leave sp_return;
                      END IF;
                  
                  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
      			SELECT 
 							IFNULL(queueName,0)                                                                  	  	    AS queueName,
 							IFNULL(avgresponseTime,0) 					                                		 		    AS averageResponseTime,
 							IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata * 100),0)		        AS responseTimeIncreasedby,
 							IFNULL(avgHandled,0 )                                                                		    AS averageHandledTime,
 							IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata * 100),0)		        AS handledTimeincreasedby,
 							IFNULL(SentimentalScore,0 )                                            			     			AS customerSatisfaction,
 							IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata * 100),0)		        AS customerSatisfactionsIncreasedby 
 							FROM 	temp_chatHistory ;
                              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      			
                  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_performances_metrics_filter1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_performances_metrics_filter1`(
       		p_startTmpstmp 		BIGINT,
           	p_endTmpstmp 		BIGINT,
           	p_domainId 			INT,
   			p_queueId 			INT,
       		p_offset 			INT,      
   			p_Limit 			INT	   
       	)
sp_return:begin
  			DECLARE v_offset 					INT;	
  			DECLARE v_Total_Count 				INT;        
  			DECLARE v_startTmpstmp 				BIGINT;
  			DECLARE v_endTmpstmp 				BIGINT;
  			DECLARE v_currenttimestamp    		DATETIME;
  			DECLARE v_previous_timestamp 	    DATETIME;
  			DECLARE v_oneday_previous_timestamp DATETIME;
  			DECLARE v1_count_currentdata 		INT;
  			DECLARE v1_count_pastdata 			INT;
  			DECLARE v2_count_currentdata		INT;
  			DECLARE v2_count_pastdata			INT;
			DECLARE v3_count_currentdata		INT;
  			DECLARE v3_count_pastdata			INT;
              
   			SET v_offset =  p_Limit * p_offset;   
                         
               	IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +3 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
               	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
               
    
               	DROP TEMPORARY TABLE IF EXISTS temp_queueId; 	    CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
               	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
               
  					CALL split(p_queueId,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
  
                
                  		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
              		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
              		(    DispositionId 			INT
              			,DispositionStatus 		VARCHAR(100)
              			,DispositionCategory	TINYINT
              		); 
              		INSERT INTO temp_AvailableDisposition 
              		SELECT 	did 			DispositionId
              			,	dispositionName	DispositionStatus
              			,	CASE WHEN dispositionName = 'Opened'	THEN 2
              				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
              				WHEN dispositionName = 'Discarded' THEN 4
       					    WHEN dispositionName = 'Resolved'  THEN 5
              				END 			DispositionCategory
              		FROM 	disposition_status
              		WHERE 	domainId	= p_domainId;
               	
               	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
   			CREATE TEMPORARY TABLE temp_AllqueueId
   			SELECT qid,name AS queueName FROM queue WHERE domainId = p_domainId;    
                   
               SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
               DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
              	CREATE TEMPORARY TABLE temp_chatHistory as
               SELECT 	 
       					 CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 		   						 						AS SessionDate
						,Q.qid																										    AS queueId
  						,CASE WHEN Q.name IS NOT NULL THEN Q.name ELSE '-'  END         												AS queueName
  						,CASE WHEN avg(CH.repliedDate - CH.createdAt) IS NOT NULL THEN (CH.repliedDate - CH.createdAt) ELSE '-' END  AS avgresponseTime
                        ,CH.repliedDate 
                        ,CH.createdAt
  						,CASE WHEN avg(t_D.DispositionCategory =3) THEN 1 ELSE 0 END		                                           	AS avgHandled
   						,CDH.SentimentalScore	                         
       			 FROM 	tb_ChatHistory 			  CH
       			 JOIN 	tb_ChatDurationHistory	  CDH    ON CH.ChatHistoryId = CDH.ChatHistoryId
   			LEFT JOIN 	queue				        Q	 ON CDH.QueueId		= Q.qid
			LEFT JOIN   temp_queueId 		       t_Q   ON Q.qid			= t_Q.queueId 
			LEFT JOIN 	temp_AvailableDisposition	t_D	 ON CDH.dispositionId= t_D.DispositionId            
       			 WHERE 	CH.domainId 			= p_domainId
       		 	 AND 	CH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp 
  				 AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
				GROUP BY CH.sessionStartTime,Q.name,Q.qid	,CDH.SentimentalScore,CH.repliedDate,CH.createdAt
       			 LIMIT 	 v_offset, p_Limit;  
       		SELECT * FROM temp_chatHistory;
               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  				SELECT * from temp_AllqueueId;                   
				SELECT COUNT(1) totalCount FROM temp_chatHistory;
  
      		
      		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
      	 	INTO 	v1_count_currentdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
      		and 	domainId	= p_domainId
  			LIMIT 1;
      		
      		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
      		INTO 	v1_count_pastdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		and 	domainId	= p_domainId
  			LIMIT 1;
              
  	
  		 SELECT 
  			CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
  			into v2_count_currentdata   
  			FROM temp_AvailableDisposition 
  			WHERE p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
              LIMIT 1; 
  		
  			SELECT 	CASE WHEN (DispositionCategory =3) THEN 1 ELSE 0 END	
  			into v2_count_pastdata 
  			FROM temp_AvailableDisposition 
  			WHERE p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
  			 LIMIT 1;
         
  			select  SentimentalScore
              into  	v3_count_currentdata
  			from 	tb_ChatDurationHistory
  			where 	p_startTmpstmp = v_previous_timestamp AND p_endTmpstmp=v_currenttimestamp 
                LIMIT 1; 
         
  			select  SentimentalScore
              into  	v3_count_pastdata
  			from 	tb_ChatDurationHistory
  			WHERE 	p_startTmpstmp = v_oneday_previous_timestamp AND p_endTmpstmp = v_previous_timestamp 
               LIMIT 1;
   					IF NOT EXISTS(SELECT 1 FROM temp_chatHistory limit 1) then
      					SELECT '0' as queueName, '0' AS averageResponseTime, '0' AS ResponseTimeincreasedby, '0' AS averageHandledTime, '0' AS HandledTimeincreasedby ,
   					'0' AS totalabondedchats ,'0' AS abondedchatssincreasedby;
                                            leave sp_return;
                       END IF;
                       
                   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
       			SELECT 
  							IFNULL(queueName,0)                                                                  	  	    AS queueName,
  							IFNULL(avgresponseTime,0) 					                                		 		    AS averageResponseTime,
  							IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata * 100),0)		        AS responseTimeIncreasedby,
  							IFNULL(avgHandled,0 )                                                                		    AS averageHandledTime,
  							IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata * 100),0)		        AS handledTimeincreasedby,
  							IFNULL(SentimentalScore,0 )                                            			     			AS customerSatisfaction,
  							IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata * 100),0)		        AS customerSatisfactionsIncreasedby 
  							FROM 	temp_chatHistory ;
                               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       			
                   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_performances_metrics_Trend_Chart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_chat_performances_metrics_Trend_Chart`(
      			   p_startTmpstmp      BIGINT,    
                   p_endTmpstmp        BIGINT,
                   p_domainId          INT,
  				   p_columnname        VARCHAR(155)
             )
BEGIN
    			DECLARE v_startDateTime 					DATETIME;
    			DECLARE v_endDateTime 						DATETIME;
    			DECLARE v_startTmpstmp 						BIGINT;
    			DECLARE v_endTmpstmp 						BIGINT;
    			DECLARE v_startTime	 						DATETIME;
    			DECLARE v_endTime	 						DATETIME;
    			DECLARE v_currenttimestamp 					BIGINT;
    			DECLARE v_previous_timestamp 				BIGINT;
    			DECLARE v_oneday_previous_timestamp 		BIGINT;
    			DECLARE v1_count_currentdata 				BIGINT;
    			DECLARE v2_count_pastdata 			   	 	BIGINT;
    			DECLARE v_coulumnname                  		VARCHAR(150);
  			DECLARE v_interval						    	INT;      
      			
   			
     			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
     			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
     			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;    
   		
     			SET v_coulumnname=p_columnname;
     			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
     			CREATE TEMPORARY TABLE temp_Intervals (
     			starttime DATETIME,
     			endtime   DATETIME
     			);
                  
     			SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day)	,from_unixtime(p_startTmpstmp/1000));
       			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
                 
                 set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                 set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                      
       		
            
    		
    	
           
    		
              
               
              
                     
      			SET v_startTime = v_startDateTime;
    			
                      SET v_endTime = DATE_ADD(v_startTime, INTERVAL (59) second);
       			 WHILE v_startTime < v_endDateTime 
       			 DO      
     				 INSERT INTO temp_Intervals (starttime, endtime)
     				 VALUES (v_startTime, v_endTime);
                      
     			
     			
                    	
                        SET v_startTime := (DATE_ADD(v_startTime, INTERVAL 1 minute));
     				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL 1 minute));
     			END WHILE;
              
     			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
     			CREATE TEMPORARY TABLE temp_ChatHistory
     			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
     			FROM 	tb_ChatHistory H 
     			WHERE 	H.domainId = p_domainId
     			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
     			GROUP BY H.sessionStartTime;   
                 
     			
     			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
     			CREATE TEMPORARY TABLE temp_Intervals_1
     			SELECT t_I.endtime 	AS `Time`
     				,	count(1)	AS `NoofreceivedchatCount`
     			FROM temp_Intervals t_I
     			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
     			GROUP BY t_I.endtime;
         
       			SELECT  (t_I.endtime) 						AS `Time`
     				,	IFNULL(t.NoofreceivedchatCount,0)	    AS NoofreceivedcurrentchatCount
  				FROM 		temp_Intervals t_I 
       			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;         
                
                
                
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
     			CREATE TEMPORARY TABLE temp_Intervals_2
     			SELECT t_I.endtime 	AS `Time`
     				,	count(1)	AS `NoofreceivedchatCount`
     			FROM temp_Intervals t_I
     			JOIN temp_ChatHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
     			GROUP BY t_I.endtime;
         
       			SELECT  (t_I.endtime) 						AS `Time`
     				,	IFNULL(t.NoofreceivedchatCount,0)	AS NoofreceivedpastchatCount
     			    FROM 	temp_Intervals t_I 
   		        LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;        
     			
           
     IF p_columnname = 'ResponsesTime'
          THEN
      		
      		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  ResponsesTime
      		INTO 	v1_count_currentdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
      		AND 	domainId	= p_domainId
  			LIMIT 1;
              
      		
      		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  ResponsesTime
      		INTO 	v2_count_pastdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		AND 	domainId	= p_domainId
  			LIMIT 1;    
     	ELSEIF p_columnname = 'HandledTime'
          THEN
      		
      		SELECT 	CASE when a.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 1 else 0 end 		AS HandledTime
			INTO 	v1_count_currentdata 
      		FROM 	disposition_status a
              JOIN 	tb_ChatHistory   b    on b.domainId=a.domainId
      		WHERE 	b.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
      		AND 	b.domainId	= p_domainId
              LIMIT 1;
     
      		
      		SELECT 	CASE when a.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 1 else 0 end 		AS HandledTime
      		INTO 	v2_count_pastdata 
      		 		FROM 	disposition_status a
             JOIN 	tb_ChatHistory   b    on b.domainId=a.domainId
      		WHERE 	b.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
      		AND 	b.domainId	= p_domainId
  			LIMIT 1;   
                
              ELSEIF p_columnname = 'ACWTime'
          THEN
      		
      	SELECT CASE WHEN SUM(b.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(b.afterChatWorkTime)/COUNT(1) ELSE '0' END         ACWTime 
      		INTO 	v1_count_currentdata
      		FROM 	tb_ChatHistory a JOIN tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
      		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		AND 	a.domainId	= p_domainId
  			LIMIT 1;
              
      		
      		SELECT CASE WHEN SUM(b.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(b.afterChatWorkTime)/COUNT(1) ELSE '0' END         ACWTime 
      		INTO 	v2_count_pastdata 
      		FROM 	tb_ChatHistory a JOIN tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
      		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		AND 	a.domainId	= p_domainId
  			LIMIT 1;
                
   
     
     	ELSEIF p_columnname = 'queueWaitingtime'
          THEN
      		
      		SELECT   CASE WHEN (queueDuration)  IS NOT NULL THEN (queueDuration)  ELSE '0' END         queueWaitingtime 
      		INTO 	v1_count_currentdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
      		AND 	domainId	= p_domainId
  			LIMIT 1;
              
      		
      		SELECT CASE WHEN (queueDuration) IS NOT NULL THEN (queueDuration)  ELSE '0' END         queueWaitingtime
      		INTO 	v2_count_pastdata 
      		FROM 	tb_ChatHistory
      		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		AND 	domainId	= p_domainId
  			LIMIT 1;
                
      	ELSEIF p_columnname = 'HoldTime'
          THEN
      		
      		SELECT   CASE WHEN (AgentHoldDuration)  IS NOT NULL THEN (AgentHoldDuration)  ELSE '0' END         HoldTime 
      		INTO 	v1_count_currentdata 
      		FROM 	tb_ChatHistory a JOIN tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
      		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		AND 	a.domainId	= p_domainId
  			LIMIT 1;
              
      		
      		SELECT CASE WHEN (AgentHoldDuration) IS NOT NULL THEN (AgentHoldDuration)  ELSE '0' END         HoldTime
      		INTO 	v2_count_pastdata 
      		FROM 	tb_ChatHistory a JOIN tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
      		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      		AND 	a.domainId	= p_domainId
  			LIMIT 1;      
                
                
       END IF;        
      		SELECT 	v1_count_currentdata																	  currentdata
      		,		v2_count_pastdata																		  pastdata
      		,		(v1_count_currentdata - v2_count_pastdata)                                          dataDifference 
              ,		(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	
        
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_chat_profile_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_chat_profile_report`(  
			  p_startTmpstmp 			BIGINT,
               p_endTmpstmp 			BIGINT,
               p_timeZone 				VARCHAR(200),
               p_domainId 				INT,
               p_queueIDs 				VARCHAR(250),
               p_agentIDs 				VARCHAR(250),
               p_dispositionIds    		VARCHAR(250),
               p_Offset			    	INT,
               p_Limit			    	INT  
            )
BEGIN
             	DECLARE v_startTmpstmp 	BIGINT;
             	DECLARE v_endTmpstmp 	BIGINT;
             	DECLARE v_Total_count 	INT;
             	DECLARE v_offset		INT;    
                 DECLARE v_defaultQueue	VARCHAR(255);
                      
             	SET v_offset =  p_Limit * p_Offset;  
             
             	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +6 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
             	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
                 
				DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
				DROP TEMPORARY TABLE IF EXISTS temp_queueId;	CREATE TEMPORARY TABLE temp_queueId(queueId INT);
				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
				 
				CALL split(p_agentIDs,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
				CALL split(p_queueIds,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
				CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
                       
             	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
             	CREATE TEMPORARY TABLE temp_AvailableDisposition 
             	(	dispositionId 		INT,
             		DispositionStatus 	VARCHAR(100)
             	);
                       
             	INSERT INTO temp_AvailableDisposition 
             	SELECT 	did 			dispositionId
             		,	dispositionName	DispositionStatus
             	FROM 	disposition_status
             	WHERE 	domainId	= p_domainId;
             	
             	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
             	CREATE TEMPORARY TABLE temp_AllagentId
             	select UserID,UserName from tb_User where domainId = p_domainId ; 
                 
             	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
             	CREATE TEMPORARY TABLE temp_AllqueueId
             	select qid,name as queueName, type from queue where domainId = p_domainId;
                 
                 SELECT queueName INTO v_defaultQueue	
                 FROM 	temp_AllqueueId 
                 WHERE 	`type`	= 'Default' LIMIT 1;
                 
				DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
				CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
				SELECT 		FROM_UNIXTIME(SH.sessionStartTime/1000) as `dateTime`			
             			 ,	SH.CustomerId	
                         ,	t_Q.queueName													AS queueName
             	 		 ,	t_A.UserName													AS agentName
     					 ,	CASE WHEN SH.IsInBound = 0 THEN 'Outbound' ELSE 'InBound' END 	AS Direction
             			 , 	DS.dispositionName							
                         ,	SDH.StartTime													AS chatStartTime
                         ,	SDH.EndTime														AS chatEndTime
                         ,	SDH.Duration													AS Duration
                         
                         ,	SH.Browser														AS `source`
                         ,	SDH.afterChatWorkTime											AS ACWtime 
                         ,	SH.queueDuration												AS queueWaitingTime
                         ,	CF.satisfactionRate												AS CSATscore
                         ,	SH.ChatSubject
                         ,	SDH.Summary
                         ,	SDH.answeredDuration
                         ,	CASE WHEN IFNULL(SDH.IsMissed,0) = 1 	THEN 'Missed Chat'	
								WHEN IFNULL(SDH.IsAbandoned,0) = 1 	THEN 'Abandoned Chat'	
								WHEN IFNULL(SDH.transferedBy,0) = 1 THEN 'Transfered Chat'
							ELSE 'Completed' END AS chatStatus
				FROM 	tb_ChatHistory 				SH
				JOIN 	tb_ChatDurationHistory		SDH		ON SH.ChatHistoryId 	= SDH.ChatHistoryId   
				LEFT JOIN  	temp_AllagentId			t_A		ON t_A.UserID			= SDH.AgentId
				LEFT JOIN 	temp_AllqueueId 		t_Q 	ON t_Q.qid  			= SDH.QueueId   
				LEFT JOIN 	disposition_status 		DS 		ON DS.did  				= SDH.dispositionId 
                LEFT JOIN	tb_customerFeedback		CF		ON CF.historyId			= SH.ChatHistoryId AND CF.AgentId = SDH.AgentId
				WHERE 	SH.domainId 			= p_domainId 		
				AND     IFNULL(SDH.IsBot,0) 	= 0
				AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
				AND		(SDH.AgentId in (select agentId from temp_agentIDs) or ifnull(p_agentIDs,'')='')
				AND		(SDH.QueueId in (select queueId from temp_queueId) or ifnull(p_queueIDs,'')='')
				AND		(SDH.dispositionId in (select dispositionId from temp_dispositionIds) or ifnull(p_dispositionIds,'')='');
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                          
				SELECT * from temp_AllagentId;
				SELECT * from temp_AvailableDisposition;
				SELECT * from temp_AllqueueId;
                      
             	SELECT COUNT(1)  totalCount
             	FROM 	temp_ChatHistory;    
             	  
             	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
             	SELECT 	SH.dateTime
					,	SH.queueName
					,	SH.agentName                
					,	CASE WHEN coid IS NOT NULL AND (c_c.firstName IS NOT NULL OR c_c.lastName IS NOT NULL) THEN 
						TRIM(CONCAT(IFNULL(c_c.firstName, ''), ' ',IFNULL(c_c.lastName, '')))ELSE NULL END AS customerName    
                    ,	SH.Direction 
                    ,	SH.chatStartTime
                    ,	SH.chatEndTime
                    ,	SH.Duration 								AS duration
                    ,	((SH.Duration /1000) + SH.ACWtime ) 		AS activeChattime
                    ,	SH.answeredDuration 						AS responseTime
                    ,	SH.dispositionName							AS disposition
                    ,	SH.ChatSubject 								AS subject
                    ,	SH.Summary 									AS summary
                    ,	SH.queueWaitingTime
                    ,	SH.ACWtime
                    ,	SH.CSATscore
					, 	SH.source
                    ,	SH.chatStatus
             	FROM 	temp_ChatHistory			SH
             	LEFT JOIN customer_contact			c_c	ON 	c_c.coid			= SH.CustomerId
             											AND	c_c.domainId		= p_domainId
				ORDER BY `dateTime` DESC 
             	LIMIT v_offset, p_Limit; 
             	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
             END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_create_custom_field_info` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_create_custom_field_info`(	 
 	p_domainid 		INT	 
 	,p_field_type 			VARCHAR(50) 	
 	,p_field_name 			VARCHAR(50) 	
 	,p_field_datatype 		VARCHAR(50) 	
 	,p_field_label 			VARCHAR(50) 	
 	,p_field_value 			VARCHAR(2000)	
 	,p_field_category 		VARCHAR(200)	
 	,p_isMandatory 			TINYINT 
 	,p_placeHolder 			VARCHAR(300) 
 	,p_errMsg 				VARCHAR(300) 
     ,p_isDisplay			TINYINT 
  )
Begin
      	
     	declare v_errcode 	int;
     	declare v_errmsg 	varchar(150);
     	declare v_FieldId 	int;
         declare v_DB		VARCHAR(20);	
         
         SET v_DB = DATABASE();
         
          sp_exit:begin
      	IF EXISTS(SELECT 1 FROM information_schema.tables where TABLE_SCHEMA = v_DB and TABLE_NAME = concat('customer_contact_',p_domainid) limit 1) 
         THEN
      		If exists(SELECT 1 FROM information_schema.columns WHERE table_name IN ('customer_contact',concat('customer_contact_',p_domainid)) and COLUMN_NAME = p_field_name AND table_schema = v_DB LIMIT 1)       
             THEN
      			SET v_errcode = -1;
     			SET v_errmsg = 'Column already exists';
                 LEAVE sp_exit;
     		END IF;
          
      		SET @coladd = CONCAT("ALter table customer_contact_",p_domainid," add ",p_field_name," varchar(250);") ;
              
      		PREPARE coladd FROM @coladd;
      		EXECUTE coladd;
      		DEALLOCATE PREPARE coladd;
              
     		SET v_errcode = 0;
     		SET v_errmsg = 'Custom field added';
          ELSE
      		set  @newtbl = concat("create table customer_contact_",p_domainid, "(id int auto_increment primary key, coid int, createdAt datetime, updatedAt datetime default now(), ",p_field_name," varchar(50))");
              
    		PREPARE newtbl FROM @newtbl;
    		EXECUTE newtbl;
    		DEALLOCATE PREPARE newtbl;
              
              set v_errcode = 0;
              set v_errmsg = 'Custom field created';
          
          End if;
              
     	
     	insert into customer_contact_column_properties(tableName,columName,columnLabel,placeHolder,errMsg,columnType,columnCategory,isMandatory,isDisplay,columnValue,createAt)
     	values(concat('customer_contact_',p_domainid),p_field_name,p_field_label,p_placeHolder,p_errMsg,p_field_type,p_field_category,p_isMandatory,p_isDisplay,p_field_value,current_timestamp);
     
     	set v_FieldId = last_insert_id();         
          
      	End sp_exit;
          select v_errcode as errcode, v_errmsg as errmsg,v_FieldId as FieldId ;
      
      End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_DashboardAgentBotComparePerform` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_DashboardAgentBotComparePerform`(	
       p_startTmpstmp 	BIGINT
      ,p_endTmpstmp 	BIGINT
      ,p_domainId		INT	
 	  ,p_channelType	 	VARCHAR(100)     
  )
BEGIN
  	  DECLARE v_startTmpstmp				BIGINT;		
      DECLARE v_endTmpstmp					BIGINT;
      DECLARE v_totalCallAgent				BIGINT;
      DECLARE v_totalCallBot				BIGINT;
      DECLARE v_firstCallResolutionAgent	BIGINT;
      DECLARE v_firstCallResolutionBot		BIGINT;
	  DECLARE v_transferRateAgent			BIGINT;
      DECLARE v_transferRateBot				BIGINT;
  	  DECLARE v_handlingTimeAgent			BIGINT;
      DECLARE v_handlingTimeBot				BIGINT;
      DECLARE v_abandonRateAgent			BIGINT;
      DECLARE v_abandonRateBot				BIGINT;
      DECLARE v_satisfactionRateAgent		BIGINT;
      DECLARE v_satisfactionRateBot			BIGINT;
  	
 	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
   	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  	
 	
  
 	DROP TEMPORARY TABLE IF EXISTS temp_channeltype; CREATE TEMPORARY TABLE temp_channeltype(channelType VARCHAR(100));
    CALL split(p_channelType, ','); INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;

    DROP TEMPORARY TABLE IF EXISTS temp_DashboardAgentBot;  
	CREATE TEMPORARY TABLE temp_DashboardAgentBot	
      ( 	SlNo    				INT 
		,	HistoryId    			INT 
		,	sessionStartTime  		BIGINT      
		,	IsInBound				TINYINT
		,	DurationHistoryId 		BIGINT
		,	dispositionName 		VARCHAR(100)
		,	IsBot					INT
		,	Duration 				BIGINT
		,	AgentHoldDuration 		BIGINT
		,	afterWorkTime 			BIGINT
		,	IsAbandoned 			TINYINT
		,	channelType  			BIGINT 
		, 	tt_satisfactionRate 	INT DEFAULT 0
	);	  

		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
        IF EXISTS(SELECT 1 FROM temp_channeltype where channelType = 'Chat' limit 1 )
        
		THEN                        
			 INSERT INTO temp_DashboardAgentBot(    
			 SlNo, 
			 HistoryId,
			 sessionStartTime,
			 IsInBound,
			 DurationHistoryId,
			 dispositionName,
			 IsBot,
			 Duration,
			 AgentHoldDuration,
			 afterWorkTime,
			 IsAbandoned,
			 channelType,
			 tt_satisfactionRate
			 )
			SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.ChatHistoryId ORDER BY ctd.ChatDurationHistoryId) SlNo        
			  ,	cth.ChatHistoryId             AS HistoryId
			  ,	cth.sessionStartTime        
			  ,	cth.IsInBound
			  ,	ctd.ChatDurationHistoryId     AS DurationHistoryId
			  ,	ds.dispositionName
			  ,	ctd.IsBot
			  ,	ctd.Duration
			  ,	ctd.AgentHoldDuration
			  ,	ctd.afterChatWorkTime AS afterWorkTime
			  ,	ctd.IsAbandoned
			 ,	2003002			                      AS channelType		              
			 ,	satisfactionRate
		FROM 	tb_ChatHistory 				cth               
		LEFT JOIN tb_ChatDurationHistory 	ctd ON cth.ChatHistoryId 	= ctd.ChatHistoryId	
		LEFT JOIN disposition_status		ds 	ON ds.did				= ctd.dispositionId AND cth.domainId = ds.domainId
    	LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= cth.ChatHistoryId AND ctd.AgentId = CF.AgentId
		WHERE 	cth.domainId = p_domainId 
		AND 	cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
      
	END IF;     
     
    IF EXISTS(SELECT 1 FROM temp_channeltype where channelType = 'Call' limit 1 ) 
	
	THEN                        
		INSERT INTO temp_DashboardAgentBot(    
		SlNo, 
		HistoryId,
		sessionStartTime,
		IsInBound,
		DurationHistoryId,
		dispositionName,
		IsBot,
		Duration,
		AgentHoldDuration,
		afterWorkTime,
		IsAbandoned,
		channelType,
		tt_satisfactionRate
		)
		SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.CallHistoryId ORDER BY ctd.CallDurationHistoryId) SlNo        
			,	cth.CallHistoryId         AS HistoryId
			,	cth.sessionStartTime        
			,	cth.IsInBound
			,	ctd.CallDurationHistoryId AS DurationHistoryId
			,	ds.dispositionName
			,	ctd.IsBot
			,	ctd.Duration
			,	ctd.AgentHoldDuration
			,	ctd.afterCallWorkTime       AS afterWorkTime
			,	0    						AS IsAbandoned
			,	2003001						AS channelType		
			,	satisfactionRate
		FROM 	tb_CallHistory 				cth                        
		LEFT JOIN tb_CallDurationHistory 	ctd ON cth.CallHistoryId 	= ctd.CallHistoryId	
        LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= cth.CallHistoryId AND ctd.AgentId = CF.AgentId
		LEFT JOIN disposition_status		ds 	ON ds.did				= ctd.dispositionId and cth.domainId = ds.domainId    	
		WHERE 	cth.domainId = p_domainId 
		AND 	cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
      END IF; 
      
		IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'SMS' LIMIT 1)
		
		THEN       
			INSERT INTO temp_DashboardAgentBot(   
			SlNo, 
			HistoryId,
			sessionStartTime,
			IsInBound,
			DurationHistoryId,
			dispositionName,
			IsBot,
			Duration,
			AgentHoldDuration,
			afterWorkTime,
			IsAbandoned,
			channelType,
			tt_satisfactionRate
			)
			SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.SMSHistoryId ORDER BY ct.SMSDurationHistoryId) SlNo        
				,	cth.SMSHistoryId         								     AS HistoryId
				,	cth.sessionStartTime        
				,	cth.IsInBound
				,	ct.SMSDurationHistoryId								         AS DurationHistoryId
				,	ds.dispositionName
				,	ct.IsBot
				,	ct.Duration
				,	ct.AgentHoldDuration						                 AS AgentHoldDuration
				,	cth.afterSMSWorkTime                                         AS afterWorkTime
				,	0                                                            AS IsAbandoned
				,	2003004														 AS channelType		
				,	satisfactionRate
			FROM 	tb_SMSHistory				cth     
			JOIN tb_SMSDurationHistory 			ct ON cth.SMSHistoryId 	= ct.SMSHistoryId	
			LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId   
			LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= cth.SMSHistoryId AND ct.AgentId = CF.AgentId
			WHERE 	cth.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
			AND 	cth.domainId			= p_domainId
			AND 	ct.IsBot			= 1; 
      END IF;
	
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Email' LIMIT 1)
    
	 THEN       
		INSERT INTO temp_DashboardAgentBot(   
		SlNo, 
		HistoryId,
		sessionStartTime,
		IsInBound,
		DurationHistoryId,
		dispositionName,
		IsBot,
		Duration,
		AgentHoldDuration,
		afterWorkTime,
		IsAbandoned,
		channelType,
		tt_satisfactionRate
		)
		SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.EmailHistoryId ORDER BY ct.EmailDurationHistoryId) SlNo        
			,	cth.EmailHistoryId         								       AS HistoryId
			,	cth.sessionStartTime        
			,	cth.IsInBound
			,	ct.EmailDurationHistoryId 								        AS DurationHistoryId
			,	ds.dispositionName
			,	ct.IsBot
			,	ct.Duration
			,	ct.AgentHoldDuration						                 	AS AgentHoldDuration
			,	cth.AfterEmailWorkTime                                         	AS afterWorkTime
			,	0                                                            	AS IsAbandoned
			,	2003003														 	AS channelType		
			,	satisfactionRate
		FROM 	tb_EmailHistory			    cth     
		JOIN tb_EmailDurationHistory 		ct  ON cth.EmailHistoryId 	= ct.EmailHistoryId	
		LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId
        LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= cth.EmailHistoryId AND ct.AgentId = CF.AgentId
		WHERE 	cth.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
		AND 	cth.domainId			= p_domainId
		AND 	ct.IsBot				= 1; 
      END IF;

	IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Whatsapp' LIMIT 1) 	
	
	 THEN    
		INSERT INTO temp_DashboardAgentBot(   
		SlNo, 
		HistoryId,
		sessionStartTime,
		IsInBound,
		DurationHistoryId,
		dispositionName,
		IsBot,
		Duration,
		AgentHoldDuration,
		afterWorkTime,
		IsAbandoned,
		channelType,
		tt_satisfactionRate
		)

		SELECT 	ROW_NUMBER() OVER (PARTITION BY H.WhatsappHistoryId ORDER BY DH.WhatsappDurationHistoryId) SlNo        
			,	H.WhatsappHistoryId            				AS HistoryId
			,	H.sessionStartTime        
			,	H.IsInBound
			,	DH.WhatsappDurationHistoryId    			AS DurationHistoryId
			,	ds.dispositionName
			,	DH.IsBot
			,	DH.Duration
			,	DH .Duration                         		AS AgentHoldDuration
			,	H.afterwhatsappWorkTime            			AS afterWorkTime
			,	0                                  			AS IsAbandoned
			,	 2003005									AS channelType		
			,	satisfactionRate
		FROM    tb_WhatsappHistory			H
		JOIN 	tb_WhatsappDurationHistory	DH	ON DH.WhatsappHistoryId = H.WhatsappHistoryId
		LEFT JOIN disposition_status		ds 	ON ds.did				= H.dispositionId and H.domainId = ds.domainId 
        LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= H.WhatsappHistoryId AND DH.AgentId = CF.AgentId
		WHERE 	H.domainId = p_domainId 
		AND 	H.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
	END IF;      
	
	IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Facebook' LIMIT 1)
	
	 THEN  
		INSERT INTO temp_DashboardAgentBot(   
		SlNo, 
		HistoryId,
		sessionStartTime,
		IsInBound,
		DurationHistoryId,
		dispositionName,
		IsBot,
		Duration,
		AgentHoldDuration,
		afterWorkTime,
		IsAbandoned,
		channelType,
		tt_satisfactionRate
		)
		SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.FacebookHistoryId ORDER BY cth.FacebookHistoryId) SlNo        
			,	cth.FacebookHistoryId         								AS HistoryId
			,	cth.sessionStartTime        
			,	cth.IsInBound
			,	0								                            AS DurationHistoryId
			,	ds.dispositionName
			,	cth.IsBot
			,	cth.Duration
			,	(cth.AgentStartTime-cth.AgentEndTime)						 AS AgentHoldDuration
			,	cth.afterFacebookWorkTime                                    AS afterWorkTime
			,	0                                                            AS IsAbandoned
			,	2003006													     AS channelType		
			,	satisfactionRate
		FROM 	tb_FacebookHistory 			cth  	
		LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId
    	LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= cth.FacebookHistoryId AND cth.AgentId = CF.AgentId
		WHERE 	cth.domainId = p_domainId 
		AND 	cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;    
	 END IF;
	
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Instagram' LIMIT 1)
    
	THEN       
		INSERT INTO temp_DashboardAgentBot(   
		SlNo, 
		HistoryId,
		sessionStartTime,
		IsInBound,
		DurationHistoryId,
		dispositionName,
		IsBot,
		Duration,
		AgentHoldDuration,
		afterWorkTime,
		IsAbandoned,
		channelType,
		tt_satisfactionRate
		)
		SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.InstagramHistoryId ORDER BY cth.InstagramHistoryId) SlNo        
			,	cth.InstagramHistoryId         								AS HistoryId
			,	cth.sessionStartTime        
			,	cth.IsInBound
			,	0								                            AS DurationHistoryId
			,	ds.dispositionName
			,	cth.IsBot
			,	cth.Duration
			,	(cth.AgentStartTime-cth.AgentEndTime)						 AS AgentHoldDuration
			,	cth.afterInstagramWorkTime                                   AS afterWorkTime
			,	0                                                            AS IsAbandoned
			,	2003007														 AS channelType		
			,	satisfactionRate
		FROM 	tb_InstagramHistory			cth     
		LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId   
        LEFT JOIN tb_customerFeedback 		CF  ON CF.historyId 		= cth.InstagramHistoryId AND cth.AgentId = CF.AgentId
		WHERE 	cth.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
		AND 	cth.domainId			= p_domainId
		AND 	cth.IsBot				= 1; 
	END IF;
              
   
  
		DROP TEMPORARY TABLE IF EXISTS temp_DashboardAgentBotHistory;
		CREATE TEMPORARY TABLE temp_DashboardAgentBotHistory	
		SELECT 	HistoryId, IsInBound, sessionStartTime		
		FROM 	temp_DashboardAgentBot
		GROUP BY HistoryId, IsInBound, sessionStartTime;
      
  
      
      SELECT 	SUM(CASE WHEN IsBot = 0 THEN 1 ELSE 0 END) 
  		,	SUM(IsBot)
  		,	SUM(CASE WHEN IsBot = 0 AND dispositionName = 'Resolved' AND SlNo = 1 THEN 1 ELSE 0 END)
  		,	SUM(CASE WHEN IsBot = 1 AND dispositionName = 'Resolved' AND SlNo = 1 THEN 1 ELSE 0 END)
          ,	SUM(CASE WHEN IsBot = 0 AND dispositionName = 'Transferred' THEN 1 ELSE 0 END)
          ,	SUM(CASE WHEN IsBot = 1 AND dispositionName = 'Transferred' THEN 1 ELSE 0 END)
          ,	SUM(CASE WHEN IsBot = 0  THEN IFNULL(Duration/1000,0) + IFNULL(afterWorkTime,0) ELSE 0 END) 
          ,	SUM(CASE WHEN IsBot = 1  THEN IFNULL(Duration/1000,0) + IFNULL(afterWorkTime,0) ELSE 0 END) 
          ,	SUM(CASE WHEN IsBot = 0  THEN IsAbandoned ELSE 0 END)
          ,	SUM(CASE WHEN IsBot = 1  THEN IsAbandoned ELSE 0 END)
          ,	SUM(CASE WHEN IsBot = 0  THEN tt_satisfactionRate ELSE 0 END)
          ,	SUM(CASE WHEN IsBot = 1  THEN tt_satisfactionRate ELSE 0 END)
  	INTO 	v_totalCallAgent
			,   v_totalCallBot	
			,	v_firstCallResolutionAgent
			,	v_firstCallResolutionBot
			,	v_transferRateAgent	
			,   v_transferRateBot	
			,	v_handlingTimeAgent	
			,   v_handlingTimeBot	
			,	v_abandonRateAgent	
			,   v_abandonRateBot	
            ,	v_satisfactionRateAgent
            ,	v_satisfactionRateBot
  	FROM 	temp_DashboardAgentBot;    
      
      SELECT 	v_firstCallResolutionAgent / v_totalCallAgent * 100	AS firstChatResolutionAgent
          ,	v_firstCallResolutionBot / v_totalCallBot * 100			AS firstChatResolutionBot
          ,	v_satisfactionRateAgent									AS customerSatisfactionRateAgent
          ,	v_satisfactionRateBot									AS customerSatisfactionRateBot
          ,	v_transferRateAgent / v_totalCallAgent * 100			AS transferRateAgent
          ,	v_transferRateBot / v_totalCallBot * 100				AS transferRateBot
          ,	(v_handlingTimeAgent / 1000) / v_totalCallAgent * 100	AS averageHandlingTimeAgent
          ,	(v_handlingTimeBot / 1000) / v_totalCallBot * 100		AS averageHandlingTimeBot
          ,	v_abandonRateAgent	/ v_totalCallAgent * 100			AS abandonRateAgent
          ,	v_abandonRateBot / v_totalCallBot * 100					AS abandonRateBot;    
  END ;;
