DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_DashboardAgentBotComparePerform2`(    
    p_startTmpstmp     BIGINT,
    p_endTmpstmp       BIGINT,
    p_domainId         INT,    
    p_channelType      VARCHAR(100) 
)
BEGIN
    DECLARE v_startTmpstmp          BIGINT;        
    DECLARE v_endTmpstmp            BIGINT;
    DECLARE v_totalCallAgent        BIGINT;
    DECLARE v_totalCallBot          BIGINT;
    DECLARE v_firstCallResolutionAgent BIGINT;
    DECLARE v_firstCallResolutionBot BIGINT;
    DECLARE v_transferRateAgent     BIGINT;
    DECLARE v_transferRateBot       BIGINT;
    DECLARE v_handlingTimeAgent     BIGINT;
    DECLARE v_handlingTimeBot       BIGINT;
    DECLARE v_abandonRateAgent      BIGINT;
    DECLARE v_abandonRateBot        BIGINT;
    DECLARE v_channel               VARCHAR(205);

    
    IF IFNULL(p_startTmpstmp,0) = 0 THEN 
        SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; 
    ELSE 
        SET v_startTmpstmp = p_startTmpstmp;  
    END IF;

    IF IFNULL(p_endTmpstmp,0) = 0 THEN 
        SET v_endTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; 
    ELSE 
        SET v_endTmpstmp = p_endTmpstmp; 
    END IF;

    IF p_channelType IS NULL THEN 
        SET p_channelType = 'Chat,Email,Call,Whatsapp,Facebook,Instagram'; 
    END IF;

    
    DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 
    CREATE TEMPORARY TABLE temp_channeltype(channelType VARCHAR(100));
    CALL split(p_channelType, ','); 
    INSERT INTO temp_channeltype (channelType) 
    SELECT Items FROM tt_Split_temptable;

    
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Chat') THEN
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
        DROP TEMPORARY TABLE IF EXISTS temp_DashboardAgentBot;  
        CREATE TEMPORARY TABLE temp_DashboardAgentBot    
        SELECT 
            ROW_NUMBER() OVER (PARTITION BY cth.ChatHistoryId ORDER BY ctd.ChatDurationHistoryId) AS SlNo,        
            cth.ChatHistoryId AS HistoryId,
            cth.sessionStartTime,
            cth.IsInBound,
            ctd.ChatDurationHistoryId AS DurationHistoryId,
            ds.dispositionName,
            ctd.IsBot,
            ctd.Duration,
            ctd.AgentHoldDuration,
            ctd.afterChatWorkTime AS afterWorkTime,
            ctd.IsAbandoned,
            2003002 AS channelType 
        FROM 
            tb_ChatHistory cth               
        LEFT JOIN 
            tb_ChatDurationHistory ctd ON cth.ChatHistoryId = ctd.ChatHistoryId    
        LEFT JOIN 
            disposition_status ds ON ds.did = ctd.dispositionId AND cth.domainId = ds.domainId        
        WHERE 
            cth.domainId = p_domainId 
            AND cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END IF;



    
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Call') THEN
        INSERT INTO temp_DashboardAgentBot (SlNo, HistoryId, sessionStartTime, IsInBound, DurationHistoryId, dispositionName, IsBot, Duration, AgentHoldDuration, afterWorkTime, IsAbandoned, channelType)
        SELECT 
            ROW_NUMBER() OVER (PARTITION BY cth.CallHistoryId ORDER BY ctd.CallDurationHistoryId) AS SlNo,        
            cth.CallHistoryId AS HistoryId,
            cth.sessionStartTime,
            cth.IsInBound,
            ctd.CallDurationHistoryId AS DurationHistoryId,
            ds.dispositionName,
            ctd.IsBot,
            ctd.Duration,
            ctd.AgentHoldDuration,
            ctd.afterCallWorkTime AS afterWorkTime,
            0 AS IsAbandoned,
            2003001 AS channelType 
        FROM 
            tb_CallHistory cth                        
        LEFT JOIN 
            tb_CallDurationHistory ctd ON cth.CallHistoryId = ctd.CallHistoryId    
        LEFT JOIN 
            disposition_status ds ON ds.did = ctd.dispositionId AND cth.domainId = ds.domainId        
        WHERE 
            cth.domainId = p_domainId 
            AND cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
    END IF;

    
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Whatsapp') THEN
        INSERT INTO temp_DashboardAgentBot (SlNo, HistoryId, sessionStartTime, IsInBound, DurationHistoryId, dispositionName, IsBot, Duration, AgentHoldDuration, afterWorkTime, IsAbandoned, channelType)
        SELECT 
            ROW_NUMBER() OVER (PARTITION BY H.WhatsappHistoryId ORDER BY DH.WhatsappDurationHistoryId) AS SlNo,        
            H.WhatsappHistoryId AS HistoryId,
            H.sessionStartTime,
            H.IsInBound,
            DH.WhatsappDurationHistoryId AS DurationHistoryId,
            ds.dispositionName,
            DH.IsBot,
            DH.Duration,
            DH.Duration AS AgentHoldDuration,
            H.afterwhatsappWorkTime AS afterWorkTime,
            0 AS IsAbandoned,
            2003005 AS channelType 
        FROM    
            tb_WhatsappHistory H
        JOIN 
            tb_WhatsappDurationHistory DH ON DH.WhatsappHistoryId = H.WhatsappHistoryId
        LEFT JOIN 
            disposition_status ds ON ds.did = H.dispositionId AND H.domainId = ds.domainId       
        WHERE 
            H.domainId = p_domainId 
            AND H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
    END IF;

    
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Facebook') THEN
        INSERT INTO temp_DashboardAgentBot (SlNo, HistoryId, sessionStartTime, IsInBound, DurationHistoryId, dispositionName, IsBot, Duration, AgentHoldDuration, afterWorkTime, IsAbandoned, channelType)
        SELECT 
            ROW_NUMBER() OVER (PARTITION BY cth.FacebookHistoryId ORDER BY cth.FacebookHistoryId) AS SlNo,        
            cth.FacebookHistoryId AS HistoryId,
            cth.sessionStartTime,
            cth.IsInBound,
            0 AS DurationHistoryId,
            ds.dispositionName,
            cth.IsBot,
            cth.Duration,
            (cth.AgentStartTime - cth.AgentEndTime) AS AgentHoldDuration,
            cth.afterFacebookWorkTime AS afterWorkTime,
            0 AS IsAbandoned,
            2003006 AS channelType 
        FROM 
            tb_FacebookHistory cth   
        LEFT JOIN 
            disposition_status ds ON ds.did = cth.dispositionId AND cth.domainId = ds.domainId      
        WHERE 
            cth.domainId = p_domainId 
            AND cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;    
    END IF;

    
    IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Instagram') THEN
        INSERT INTO temp_DashboardAgentBot (SlNo, HistoryId, sessionStartTime, IsInBound, DurationHistoryId, dispositionName, IsBot, Duration, AgentHoldDuration, afterWorkTime, IsAbandoned, channelType)
        SELECT 
            ROW_NUMBER() OVER (PARTITION BY cth.InstagramHistoryId ORDER BY cth.InstagramHistoryId) AS SlNo,        
            cth.InstagramHistoryId AS HistoryId,
            cth.sessionStartTime,
            cth.IsInBound,
            0 AS DurationHistoryId,
            ds.dispositionName,
            cth.IsBot,
            cth.Duration,
            (cth.AgentStartTime - cth.AgentEndTime) AS AgentHoldDuration,
            cth.afterInstagramWorkTime AS afterWorkTime,
            0 AS IsAbandoned,
            2003007 AS channelType 
        FROM 
            tb_Instagram
        LEFT JOIN 
            disposition_status ds ON ds.did = cth.dispositionId AND cth.domainId = ds.domainId      
        WHERE 
            cth.domainId = p_domainId 
            AND cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;    
    END IF;


    SELECT 
        SUM(CASE WHEN IsBot = 0 THEN 1 ELSE 0 END),
        SUM(IsBot),
        SUM(CASE WHEN IsBot = 0 AND dispositionName = 'Resolved' AND SlNo = 1 THEN 1 ELSE 0 END),
        SUM(CASE WHEN IsBot = 1 AND dispositionName = 'Resolved' AND SlNo = 1 THEN 1 ELSE 0 END),
        SUM(CASE WHEN IsBot = 0 AND dispositionName = 'Transferred' THEN 1 ELSE 0 END),
        SUM(CASE WHEN IsBot = 1 AND dispositionName = 'Transferred' THEN 1 ELSE 0 END),
        SUM(CASE WHEN IsBot = 0 THEN IFNULL(Duration,0) + IFNULL(AgentHoldDuration,0) + IFNULL(afterWorkTime,0) ELSE 0 END),
        SUM(CASE WHEN IsBot = 1 THEN IFNULL(Duration,0) + IFNULL(AgentHoldDuration,0) + IFNULL(afterWorkTime,0) ELSE 0 END),
        SUM(CASE WHEN IsBot = 0 THEN IsAbandoned ELSE 0 END),
        SUM(CASE WHEN IsBot = 1 THEN IsAbandoned ELSE 0 END),
        C.TypeCodeName AS `channel`
    INTO 
        v_totalCallAgent,
        v_totalCallBot,
        v_firstCallResolutionAgent,
        v_firstCallResolutionBot,
        v_transferRateAgent,
        v_transferRateBot,
        v_handlingTimeAgent,
        v_handlingTimeBot,
        v_abandonRateAgent,
        v_abandonRateBot,
        v_channel
    FROM 
        temp_DashboardAgentBot H
    JOIN 
        TypeCode C ON H.channelType = C.TypeCodeID  
    GROUP BY
        C.TypeCodeName;

    SELECT 
        v_firstCallResolutionAgent / v_totalCallAgent * 100 AS firstChatResolutionAgent,
        v_firstCallResolutionBot / v_totalCallBot * 100 AS firstChatResolutionBot,
        0 AS customerSatisfactionRateAgent, 
        0 AS customerSatisfactionRateBot, 
        v_transferRateAgent / v_totalCallAgent * 100 AS transferRateAgent,
        v_transferRateBot / v_totalCallBot * 100 AS transferRateBot,
        (v_handlingTimeAgent / 1000) / v_totalCallAgent * 100 AS averageHandlingTimeAgent,
        (v_handlingTimeBot / 1000) / v_totalCallBot * 100 AS averageHandlingTimeBot,
        v_abandonRateAgent / v_totalCallAgent * 100 AS abandonRateAgent,
        v_abandonRateBot / v_totalCallBot * 100 AS abandonRateBot,
        v_channel;
END ;;
DELIMITER ;
