DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_DashboardAgentBotComparePerform_1`(	
        p_startTmpstmp 	BIGINT
       ,p_endTmpstmp 	BIGINT
       ,p_domainId		INT	
  	   ,p_channelType	VARCHAR(100)     
   )
BEGIN
   	  DECLARE v_startTmpstmp				BIGINT;		
       DECLARE v_endTmpstmp				BIGINT;
       DECLARE v_totalCallAgent			BIGINT;
       DECLARE v_totalCallBot				BIGINT;
       DECLARE v_firstCallResolutionAgent	BIGINT;
       DECLARE v_firstCallResolutionBot	BIGINT;
 	   DECLARE v_transferRateAgent		BIGINT;
       DECLARE v_transferRateBot			BIGINT;
   	   DECLARE v_handlingTimeAgent		BIGINT;
       DECLARE v_handlingTimeBot			BIGINT;
       DECLARE v_abandonRateAgent			BIGINT;
       DECLARE v_abandonRateBot			BIGINT;
   	
  	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  	
  IF p_channelType IS NULL THEN
    SET p_channelType = 'Chat,Email,Call,Whatsapp,Facebook,Instagram';
END IF;

DROP TEMPORARY TABLE IF EXISTS temp_channeltype;
CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));
CALL split(p_channelType, ',');
INSERT INTO temp_channeltype (channelType)
SELECT Items FROM tt_Split_temptable;

SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Chat' LIMIT 1) THEN
    DROP TEMPORARY TABLE IF EXISTS temp_DashboardAgentBot;
    CREATE TEMPORARY TABLE temp_DashboardAgentBot
    SELECT 
        ROW_NUMBER() OVER (PARTITION BY cth.ChatHistoryId ORDER BY ctd.ChatDurationHistoryId)   AS SlNo,
        cth.ChatHistoryId 																		AS HistoryId,
        cth.sessionStartTime,
        cth.IsInBound,
        ctd.ChatDurationHistoryId   															AS DurationHistoryId,
        ds.dispositionName,
        ctd.IsBot,
        ctd.Duration,
        ctd.AgentHoldDuration,
        ctd.afterChatWorkTime 																	AS afterWorkTime,
        ctd.IsAbandoned,
        2003002 																				AS channelType 
    FROM
        tb_ChatHistory cth
        LEFT JOIN tb_ChatDurationHistory ctd ON cth.ChatHistoryId = ctd.ChatHistoryId
        LEFT JOIN disposition_status ds ON ds.did = ctd.dispositionId AND cth.domainId = ds.domainId
    WHERE
        cth.domainId = p_domainId
        AND cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
		AND 	ctd.IsBot			= 1;
END IF;

IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Call' LIMIT 1) THEN
    INSERT INTO temp_DashboardAgentBot (
        SlNo,
        HistoryId,
        sessionStartTime,
        IsInBound,
        DurationHistoryId,
        dispositionName,
        IsBot,
        Duration,
        AgentHoldDuration,
        afterWorkTime,
        IsAbandoned,
        channelType
    )
    SELECT 
        ROW_NUMBER() OVER (PARTITION BY cth.CallHistoryId ORDER BY ctd.CallDurationHistoryId) AS SlNo,
        cth.CallHistoryId 																	  AS HistoryId,
        cth.sessionStartTime,
        cth.IsInBound,
        ctd.CallDurationHistoryId 															 AS DurationHistoryId,
        ds.dispositionName,
        ctd.IsBot,
        ctd.Duration,
        ctd.AgentHoldDuration,
        ctd.afterCallWorkTime 																AS afterWorkTime,
        0 																					AS IsAbandoned,
        2003001 																			AS channelType 
    FROM
        tb_CallHistory cth
        LEFT JOIN tb_CallDurationHistory ctd ON cth.CallHistoryId = ctd.CallHistoryId
        LEFT JOIN disposition_status ds ON ds.did = ctd.dispositionId AND cth.domainId = ds.domainId
    WHERE
        cth.domainId = p_domainId
        AND cth.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
		AND 	ctd.IsBot			= 1;
END IF;

  IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'SMS' LIMIT 1) 
  THEN       
        INSERT INTO temp_DashboardAgentBot(   
  	 SlNo, 
      HistoryId,
      sessionStartTime,
      IsInBound,
      DurationHistoryId,
      dispositionName,
      IsBot,
      Duration,
      AgentHoldDuration,
      afterWorkTime,
      IsAbandoned,
      channelType
      )
       
        SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.SMSHistoryId ORDER BY ct.SMSDurationHistoryId) SlNo        
   		   ,	cth.SMSHistoryId         								     AS HistoryId
   		   ,	cth.sessionStartTime        
  		   ,	cth.IsInBound
   		   ,	ct.SMSDurationHistoryId								         AS DurationHistoryId
           ,	ds.dispositionName
           ,	ct.IsBot
           ,	ct.Duration
           ,	ct.AgentHoldDuration						                 AS AgentHoldDuration
           ,	cth.afterSMSWorkTime                                         AS afterWorkTime
           ,	0                                                            AS IsAbandoned
           ,	2003004														 AS channelType		
    	FROM 	tb_SMSHistory			   cth     
    	 JOIN tb_SMSDurationHistory 	ct ON cth.SMSHistoryId 	= ct.SMSHistoryId	
      LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId   
    	WHERE 	cth.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    	AND 	cth.domainId			= p_domainId
     	AND 	ct.IsBot			= 1; 
       END IF;
   
 IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Email' LIMIT 1) 
  THEN       
        INSERT INTO temp_DashboardAgentBot(   
  	  SlNo, 
      HistoryId,
      sessionStartTime,
      IsInBound,
      DurationHistoryId,
      dispositionName,
      IsBot,
      Duration,
      AgentHoldDuration,
      afterWorkTime,
      IsAbandoned,
      channelType
      )
       
        SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.EmailHistoryId ORDER BY ct.EmailDurationHistoryId) SlNo        
   		,	cth.EmailHistoryId         								       AS HistoryId
   		,	cth.sessionStartTime        
  		,	cth.IsInBound
   		,	ct.EmailDurationHistoryId 								        AS DurationHistoryId
           ,	ds.dispositionName
           ,	ct.IsBot
           ,	ct.Duration
           ,	ct.AgentHoldDuration						                 	AS AgentHoldDuration
           ,	cth.AfterEmailWorkTime                                         	AS afterWorkTime
           ,	0                                                            	AS IsAbandoned
           ,	2003003														 	AS channelType		
    	FROM 	tb_EmailHistory			   cth     
    	 JOIN tb_EmailDurationHistory 	ct  ON cth.EmailHistoryId 	= ct.EmailHistoryId	
      LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId   
    	WHERE 	cth.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    	AND 	cth.domainId			= p_domainId
     	AND 	ct.IsBot			= 1; 
       END IF;
 	
   
  IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Whatsapp' LIMIT 1)  
  THEN    
       INSERT INTO temp_DashboardAgentBot(   
  	  SlNo, 
      HistoryId,
      sessionStartTime,
      IsInBound,
      DurationHistoryId,
      dispositionName,
      IsBot,
      Duration,
      AgentHoldDuration,
      afterWorkTime,
      IsAbandoned,
      channelType
      )
     
        SELECT 	ROW_NUMBER() OVER (PARTITION BY H.WhatsappHistoryId ORDER BY DH.WhatsappDurationHistoryId) SlNo        
   		   ,	H.WhatsappHistoryId            				AS HistoryId
   		   ,	H.sessionStartTime        
           ,	H.IsInBound
   		   ,	DH.WhatsappDurationHistoryId    			AS DurationHistoryId
           ,	ds.dispositionName
           ,	DH.IsBot
           ,	DH.Duration
           ,	DH .Duration                         		AS AgentHoldDuration
           ,	H.afterwhatsappWorkTime            			AS afterWorkTime
           ,	0                                  			AS IsAbandoned
  		   ,	2003005									    AS channelType		
    	FROM    tb_WhatsappHistory			H
   	JOIN 	tb_WhatsappDurationHistory	DH	ON DH.WhatsappHistoryId = H.WhatsappHistoryId
    	LEFT JOIN disposition_status		ds 	ON ds.did				= H.dispositionId and H.domainId = ds.domainId    	
      	WHERE 	H.domainId = p_domainId 
      	 AND 	H.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp
		 AND 	ct.IsBot			= 1;
  END IF;      
  IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Facebook' LIMIT 1)  
  THEN  
       INSERT INTO temp_DashboardAgentBot(   
  	  SlNo, 
      HistoryId,
      sessionStartTime,
      IsInBound,
      DurationHistoryId,
      dispositionName,
      IsBot,
      Duration,
      AgentHoldDuration,
      afterWorkTime,
      IsAbandoned,
      channelType
      )
       
   SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.FacebookHistoryId ORDER BY cth.FacebookHistoryId) SlNo        
   		,	cth.FacebookHistoryId         								AS HistoryId
   		,	cth.sessionStartTime        
  		,	cth.IsInBound
   		,	0								                            AS DurationHistoryId
           ,	ds.dispositionName
           ,	cth.IsBot
           ,	cth.Duration
           ,	(cth.AgentStartTime-cth.AgentEndTime)						 AS AgentHoldDuration
           ,	cth.afterFacebookWorkTime                                    AS afterWorkTime
           ,	0                                                            AS IsAbandoned
           ,	2003006													     AS channelType		
   	FROM 	tb_FacebookHistory 				cth  	
  	LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId    	
      	WHERE 	cth.domainId = p_domainId 
      	 AND 	cth.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp
		 AND 	cth.IsBot			= 1;
  END IF; 
  IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Instagram' LIMIT 1) 
  THEN       
        INSERT INTO temp_DashboardAgentBot(   
  	SlNo, 
      HistoryId,
      sessionStartTime,
      IsInBound,
      DurationHistoryId,
      dispositionName,
      IsBot,
      Duration,
      AgentHoldDuration,
      afterWorkTime,
      IsAbandoned,
      channelType
      )
       
        SELECT 	ROW_NUMBER() OVER (PARTITION BY cth.InstagramHistoryId ORDER BY cth.InstagramHistoryId) SlNo        
   		,	cth.InstagramHistoryId         								AS HistoryId
   		,	cth.sessionStartTime        
  		,	cth.IsInBound
   		,	0								                            AS DurationHistoryId
           ,	ds.dispositionName
           ,	cth.IsBot
           ,	cth.Duration
           ,	(cth.AgentStartTime-cth.AgentEndTime)						 AS AgentHoldDuration
           ,	cth.afterInstagramWorkTime                                   AS afterWorkTime
           ,	0                                                            AS IsAbandoned
           ,	2003007														 AS channelType		
    	FROM 	tb_InstagramHistory			cth     
      LEFT JOIN disposition_status		ds 	ON ds.did				= cth.dispositionId and cth.domainId = ds.domainId   
    	WHERE 	cth.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
    	AND 	cth.domainId			= p_domainId
    	AND 	cth.IsBot			= 1;
       END IF;
      
  select * from  temp_DashboardAgentBot;
        	DROP TEMPORARY TABLE IF EXISTS temp_DashboardAgentBotHistory;
      	CREATE TEMPORARY TABLE temp_DashboardAgentBotHistory	
       SELECT 	HistoryId, IsInBound, sessionStartTime	,channelType
       FROM 	temp_DashboardAgentBot H
       JOIN 	TypeCode					C	ON H.channelType	= C.TypeCodeID
       GROUP BY HistoryId, IsInBound, sessionStartTime,channelType;
       
   
       
       SELECT 	SUM(CASE WHEN IsBot = 0 THEN 1 ELSE 0 END) 
   		   ,	SUM(IsBot)
   		   ,	SUM(CASE WHEN IsBot = 0 AND dispositionName = 'Resolved' AND SlNo = 1 THEN 1 ELSE 0 END)
   		   ,	SUM(CASE WHEN IsBot = 1 AND dispositionName = 'Resolved' AND SlNo = 1 THEN 1 ELSE 0 END)
           ,	SUM(CASE WHEN IsBot = 0 AND dispositionName = 'Transferred' THEN 1 ELSE 0 END)
           ,	SUM(CASE WHEN IsBot = 1 AND dispositionName = 'Transferred' THEN 1 ELSE 0 END)
           ,	SUM(CASE WHEN IsBot = 0  THEN IFNULL(Duration,0) + IFNULL(AgentHoldDuration,0) + IFNULL(afterWorkTime,0) ELSE 0 END) 
           ,	SUM(CASE WHEN IsBot = 1  THEN IFNULL(Duration,0) + IFNULL(AgentHoldDuration,0) + IFNULL(afterWorkTime,0) ELSE 0 END) 
           ,	SUM(CASE WHEN IsBot = 0  THEN IsAbandoned ELSE 0 END)
           ,	SUM(CASE WHEN IsBot = 1  THEN IsAbandoned ELSE 0 END)
   	INTO 	    v_totalCallAgent
           ,    v_totalCallBot	
   		   ,	v_firstCallResolutionAgent
   		   ,	v_firstCallResolutionBot
           ,	v_transferRateAgent	
           ,    v_transferRateBot	
           ,	v_handlingTimeAgent	
           ,    v_handlingTimeBot	
           ,	v_abandonRateAgent	
           ,   v_abandonRateBot	
   	FROM 	temp_DashboardAgentBot;    
       
       SELECT 	v_firstCallResolutionAgent / v_totalCallAgent * 100	AS firstChatResolutionAgent
           ,	v_firstCallResolutionBot / v_totalCallBot * 100			AS firstChatResolutionBot
           ,	0														AS customerSatisfactionRateAgent
           ,	0														AS customerSatisfactionRateBot
           ,	v_transferRateAgent / v_totalCallAgent * 100			AS transferRateAgent
           ,	v_transferRateBot / v_totalCallBot * 100				AS transferRateBot
           ,	(v_handlingTimeAgent / 1000) / v_totalCallAgent * 100	AS averageHandlingTimeAgent
           ,	(v_handlingTimeBot / 1000) / v_totalCallBot * 100		AS averageHandlingTimeBot
           ,	v_abandonRateAgent	/ v_totalCallAgent * 100			AS abandonRateAgent
           ,	v_abandonRateBot / v_totalCallBot * 100					AS abandonRateBot;    
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_DashboardUtilization` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_DashboardUtilization`(	
	p_startTmpstmp 	BIGINT
	,p_endTmpstmp 	BIGINT
	,p_domainId		INT	
	,p_ext 			INT				
	,p_channeltype	VARCHAR(100)	
  )
SP_Logic:BEGIN
  	
      DECLARE v_blockCustomer					INT;    
      DECLARE v_totalCustomer					INT;    
      DECLARE v_percentageOfCallBlocked			INT;    
      DECLARE v_overAllavailableTime			BIGINT;    
      DECLARE v_TotalLoginTime					BIGINT;    
      DECLARE v_totalDuration					BIGINT; 
      DECLARE v_startDatetime					DATETIME DEFAULT FROM_UNIXTIME(p_startTmpstmp/1000);
      DECLARE v_endDatetime						DATETIME DEFAULT FROM_UNIXTIME(p_endTmpstmp/1000);
      
  	
      
		SELECT	SUM(CASE WHEN IFNULL(blockCustomer,0) = 1 THEN 1 ELSE 0 END)
			,	COUNT(coid)
		INTO 	v_blockCustomer, v_totalCustomer
		FROM 	customer_contact
		WHERE 	domainId = p_domainId
		AND 	updatedAt  BETWEEN v_startDatetime AND v_endDatetime;
        
 		SET v_percentageOfCallBlocked = 
 		CASE 
 			WHEN v_totalCustomer = 0 THEN 0 
 			ELSE (v_blockCustomer / v_totalCustomer) * 100 
 		END;
        
         DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
 		CREATE TEMPORARY TABLE temp_AvailableState AS
 		SELECT   
 		CASE 
 			WHEN a.aid = ST.timerStatusId AND ((isVoice = 1) or (isChat = 1) or (isEmail=1)  ) THEN 1
 			WHEN a.aid = ST.timerStatusId AND ((isVoice = 0) or (isChat = 0) or (isEmail=0)  ) THEN 2
 			ELSE 3 
 			END AS tt_Time,
 			ST.domainId,
 			ST.stateDuration as SD,
 			
             from_unixtime(ST.startTimestamp/1000)
 		FROM     state_timer ST 
 		JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
 		WHERE    ST.domainId = p_domainId
 		AND      ST.startTimestamp BETWEEN p_startTmpstmp AND p_endTmpstmp;
 
 		SELECT 	SUM(SD) 
 		INTO 	v_overAllavailableTime
 		FROM 	temp_AvailableState
        WHERE   domainId	= p_domainId
        AND 	tt_Time 	= 1
 		GROUP BY domainId; 
           
 		DROP TEMPORARY TABLE IF EXISTS temp_DurationHistory;
 		CREATE TEMPORARY TABLE temp_DurationHistory(
 		CH_HistoryId				BIGINT	,CDH_DurationHistoryId		BIGINT	,ChannelType				INT
 		,CDH_afterCallWorkTime		INT		,CDH_Duration				BIGINT	);      
    
 		  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;       
        	  INSERT INTO temp_DurationHistory
 				( 	CH_HistoryId 		,CDH_DurationHistoryId 		,CDH_afterCallWorkTime ,CDH_Duration ,ChannelType )
 			SELECT  CH.CallHistoryId    ,CDH.CallDurationHistoryId  ,CDH.afterCallWorkTime ,CDH.Duration  ,1	
             FROM tb_CallHistory 			CH    
 			JOIN tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId	  
 			WHERE CH.domainId 				= p_domainId 
 			AND CH.sessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp;
                  
       	  INSERT INTO temp_DurationHistory
 				( 	CH_HistoryId 		,CDH_DurationHistoryId 		,CDH_afterCallWorkTime ,CDH_Duration ,ChannelType )
 			SELECT  CH.ChatHistoryId    ,CDH.ChatDurationHistoryId  ,CDH.afterChatWorkTime ,CDH.Duration ,2	
 			FROM tb_ChatHistory 			CH    
 			JOIN tb_ChatDurationHistory 	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId	  
 			WHERE CH.domainId 				= p_domainId 
 			AND CH.sessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp;
            
 		INSERT INTO temp_DurationHistory
 				( 	CH_HistoryId 		,CDH_DurationHistoryId 		,CDH_afterCallWorkTime ,CDH_Duration ,ChannelType )
 			SELECT  EH.EmailHistoryId    ,EDH.EmailDurationHistoryId  ,EH.AfterEmailWorkTime ,EDH.Duration ,3	
 			FROM tb_EmailHistory 			EH    
 			JOIN tb_EmailDurationHistory 	EDH ON EH.EmailHistoryId = EDH.EmailHistoryId	  
 			WHERE EH.domainId 				= p_domainId 
 			AND EH.SessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp;
 		
         INSERT INTO temp_DurationHistory
 				( 	CH_HistoryId 		,CDH_DurationHistoryId 		,CDH_afterCallWorkTime ,CDH_Duration ,ChannelType )
 			SELECT  SH.SMSHistoryId    ,SDH.SMSDurationHistoryId  ,SH.afterSMSWorkTime ,SDH.Duration ,4	
 			FROM tb_SMSHistory 			SH    
 			JOIN tb_SMSDurationHistory 	SDH ON SH.SMSHistoryId = SDH.SMSHistoryId	  
 			WHERE SH.domainId 				= p_domainId 
 			AND SH.SessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp;
 		
         INSERT INTO temp_DurationHistory
 				( 	CH_HistoryId 			,CDH_DurationHistoryId 			,CDH_afterCallWorkTime ,CDH_Duration ,ChannelType )
 			SELECT  WH.WhatsappHistoryId    ,WDH.WhatsappDurationHistoryId  ,WH.afterwhatsappWorkTime ,WDH.Duration ,5	
 			FROM tb_WhatsappHistory 			WH    
 			JOIN tb_WhatsappDurationHistory 	WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId	  
 			WHERE WH.domainId 				= p_domainId 
 			AND WH.SessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp;
 		
         INSERT INTO temp_DurationHistory
 				( 	CH_HistoryId 			,CDH_DurationHistoryId 			,CDH_afterCallWorkTime ,CDH_Duration ,ChannelType )
 			SELECT  FacebookHistoryId    	,FacebookHistoryId  			,afterFacebookWorkTime ,Duration 	,6	
 			FROM tb_FacebookHistory 			    
 			WHERE domainId 				= p_domainId 
 			AND sessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp;
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  
               
 			DROP TEMPORARY TABLE IF EXISTS tt_loginTime;
 			CREATE TEMPORARY TABLE tt_loginTime(
 			ext INT
 			,logInTimestamp BIGINT);
             
 			DROP TEMPORARY TABLE IF EXISTS tt_logoutTime;
 			CREATE TEMPORARY TABLE tt_logoutTime(
 			ext INT
 			,logOutTimestamp BIGINT);
 
 			INSERT INTO tt_loginTime(ext,logInTimestamp)
 			SELECT ext,MIN(logInTimestamp)
 			FROM 	logInSessionHistory		LSH		
 			WHERE 	LSH.domainId	= p_domainId
 			AND 	LSH.logInTimestamp	BETWEEN p_startTmpstmp AND p_endTmpstmp
 			GROUP BY ext
 			ORDER BY ext;
 
 			INSERT INTO tt_logoutTime(ext,logOutTimestamp)
 			WITH CTE AS(
 			SELECT 	ext
				,	IFNULL(MAX(logOutTimestamp),(UNIX_TIMESTAMP()*1000)) AS logOutTimestamp
				,	row_number() over (partition by ext ORDER BY IFNULL(LSH.updatedAt,LSH.createdAt) DESC) as aa
 			FROM 	logInSessionHistory		LSH		
 			WHERE 	LSH.domainId	= p_domainId
 			AND 	LSH.logInTimestamp	BETWEEN p_startTmpstmp AND p_endTmpstmp
 			GROUP BY ext,updatedAt,createdAt) 
            SELECT  ext,logOutTimestamp FROM CTE WHERE  aa = 1
 			ORDER BY ext;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	
 		
         DROP TEMPORARY TABLE IF EXISTS tt_loginLogout_cal;
         CREATE TEMPORARY TABLE tt_loginLogout_cal AS
 		SELECT I.ext,I.logInTimestamp,O.logOutTimestamp
         ,TIMESTAMPDIFF(SECOND,DATE_FORMAT(FROM_UNIXTIME(I.logInTimestamp/1000),'%Y-%m-%d %H:%i:%s'),IFNULL(DATE_FORMAT(FROM_UNIXTIME(O.logOutTimestamp/1000),'%Y-%m-%d %H:%i:%s'),NOW())) AS TotalLoginTime
 		FROM tt_loginTime 	I
 		JOIN tt_logoutTime 	O ON I.ext = O.ext;
 	        
	SELECT SUM(TotalLoginTime) INTO v_TotalLoginTime
	FROM tt_loginLogout_cal;
         
     SELECT SUM(CASE WHEN IFNULL(CDH_Duration,0)>0 THEN CDH_Duration ELSE 0 END) INTO v_totalDuration
     FROM temp_DurationHistory;
     
            
      
      SELECT  CASE WHEN v_overAllavailableTime = 0 THEN 0 ELSE IFNULL(((v_totalDuration / v_overAllavailableTime)* 100),0) END occupancyRate
 			,CASE WHEN v_overAllavailableTime = 0 THEN 0 ELSE IFNULL(((v_totalDuration / (v_TotalLoginTime*1000))* 100),0) END utilizationRate
			,IFNULL((v_percentageOfCallBlocked), 0) As blockedContacts;
          
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
    DROP TEMPORARY TABLE IF EXISTS temp_DurationHistory;
	DROP TEMPORARY TABLE IF EXISTS tt_loginTime;
	DROP TEMPORARY TABLE IF EXISTS tt_logoutTime;
    DROP TEMPORARY TABLE IF EXISTS tt_loginLogout_cal;   
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
