CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_deleteCustomerContactByEmail`(
  p_domainId 		INT
  ,p_primaryEmail	VARCHAR(150)    
 )
begin
 	DELETE 	FROM customer_contact 
    WHERE 	primaryEmail 	= p_primaryEmail 
    AND 	domainId 		= p_domainId;
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
