/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_delete_customer_contact_custom_field`(	
 	p_cid			INT 
    )
BEGIN
        
        DECLARE v_cid		INT;
        DECLARE v_errcode	INT DEFAULT -1;
        DECLARE v_errmsg		VARCHAR(50) DEFAULT 'Custom field delete fail';
        DECLARE v_tableName varchar(100);
        DECLARE v_columName varchar(100);
        
        SELECT 	id,tableName,columName INTO v_cid , v_tableName , v_columName
        FROM 	customer_contact_column_properties
        WHERE 	id	= p_cid;
        
		
		SET @check_sql = CONCAT('SELECT COUNT(*) INTO @count FROM ', v_tableName, ' WHERE `', v_columName, '` IS NOT NULL');
		PREPARE stmt_check FROM @check_sql;
		EXECUTE stmt_check;
		DEALLOCATE PREPARE stmt_check;

		
		IF @count > 0 THEN
		SELECT -2 AS errcode, 'Unable to delete custom field' AS errmsg;
		ELSE
		
		DELETE FROM customer_contact_column_properties WHERE id = v_cid;

		
		SET @drop_sql = CONCAT('ALTER TABLE ', v_tableName, ' DROP COLUMN `', v_columName, '`');
		PREPARE stmt_drop FROM @drop_sql;
		EXECUTE stmt_drop;
		DEALLOCATE PREPARE stmt_drop;

		SELECT 0 AS errcode, 'Custom field deleted successfully' AS errmsg;
		END IF;
       
        
        
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
