/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_email_agent_performances_analysis_metrics_filter`(  
            p_startTmpstmp   BIGINT,
            p_endTmpstmp 	BIGINT,
            p_domainId 		INT,    	
            p_agentId		VARCHAR(250),		
            p_offset 		INT,
            p_Limit 			INT	
                     )
BEGIN
                 
     	    DECLARE v_offset 					INT;	  	
        	DECLARE v_CurrentStartTmpstmp 		BIGINT;
        	DECLARE v_CurrentEndTmpstmp 		BIGINT;
             
     	    DECLARE v_PrevStartTmpstmp 			BIGINT;
        	DECLARE v_PrevEndTmpstmp 			BIGINT; 
     	    DECLARE v_TmpstmpInterval			BIGINT;	
          		
   		DECLARE v_PrevAverageResponseCount		INT;	
   		DECLARE v_CurrentAverageResponseCount	INT;	        
     		DECLARE v_DiffAverageResponsePercent	INT;
         	
    		DECLARE v_PrevAverageHandledCount		INT;	
   		DECLARE v_CurrentAverageHandledCount	INT;
   		DECLARE v_DiffAverageHandledPercent		INT;  	    
            	
   		DECLARE v_PrevMaximumHandledCount		INT;	
   		DECLARE v_CurrentMaximumHandledCount	INT;	        
     		DECLARE v_DiffMaximumHandledTimePercent	INT;    
             
    		DECLARE v_PrevTotalACWCount		      	INT;	
   		DECLARE v_CurrentTotalACWCount		  	INT;	        
    		DECLARE v_DiffTotalACWTimePercent	  	INT;   
             
         	DECLARE v_PrevAverageQueueWaitingCount		    INT;	
   		DECLARE v_CurrentAverageQueueWaitingCount		INT;	        
         	DECLARE v_DiffAverageQueueWaitingPercent		INT; 
             
         
         	DECLARE v_PrevaverageHoldtCount		        	INT;	
   		DECLARE v_CurrentaverageHoldtCount		    	INT;	        
         	DECLARE v_DiffaverageHoldtPercent		    	INT; 
             
            
    		DECLARE v_PrevMaximumQueueWaitingCount		    INT;	
          	DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
    		DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
         
         	DECLARE v_PrevfirstChatResolutionCount		    INT;	
         	DECLARE v_CurrentfirstChatResolutionCount		INT;	        
   		DECLARE v_DifffirstChatResolutionPercent		INT;  
                             
    		DECLARE v_PreSentimentalScore              		INT;
    		DECLARE v_CurrentSentimentalScore          		INT;
    		DECLARE v_DiffSentimentalScorePercent      		INT;      
            
      	    DECLARE v_PrevAgentIdleTimeCount		    INT;	
        	DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
      	    DECLARE v_DifffirsAgentIdleTimePercent	    INT;    
            
    		DECLARE v_PreavailableCount                     INT;
    		DECLARE v_CurrentavailableCount                 INT;                      
    		DECLARE v_PretotalTalkCount                     INT;
    		DECLARE v_CurrenttotalTalkCount                 INT;  
     
     
          	SET v_offset =  p_Limit * p_offset; 
            
            	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
            	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
            	
          	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          
          	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
            	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
            	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
                 
                	        
                      	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                      	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                 	
                       
                         		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                     		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                     		(    DispositionId 			INT
                     			,DispositionStatus 		VARCHAR(100)
                     			,DispositionCategory	TINYINT
                     		); 
                             
                     		INSERT INTO temp_AvailableDisposition 
                     		SELECT 	did 			DispositionId
                     			,	dispositionName	DispositionStatus
                     			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                     				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                     				WHEN dispositionName = 'Discarded'     THEN 4
              					    WHEN dispositionName = 'Resolved'      THEN 5
                     				END 			DispositionCategory
                     		FROM 	disposition_status
                     		WHERE 	domainId	= p_domainId;
                      	
                      	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                      	CREATE TEMPORARY TABLE temp_AllagentId
                      	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
                          
             			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                      	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
                    	    CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
                          	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		           AS SessionDate
                                 , SDH.AgentId
          					      ,	U.UserName													           AS agentName
                                 , SH.IsInBound
                                 , SDH.Duration                                                            AS callDuration
                                 , SDH.AgentHoldDuration                                                   AS agentHoldDuration
          					      , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		      AS Handled		
    							  , CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                   AS firstChatResolution        
   							  , SH.SessionStartTime                                                       AS agentconnecttime
    							  ,	SH.SessionEndTime - SH.SessionStartTime	 						          AS chatHandlingTime          
    							  ,	SH.repliedDate - SH.createdAt								    	      AS responseTime
   							  , SDH.Duration												              AS Duration	
 							  , SDH.Duration/1000                       								  AS emailDuration
    							  , SH.AfterEmailWorkTime                                       
    							  ,SH.SentimentalScore
                        	FROM 	tb_EmailHistory 				SH
                        	JOIN 	tb_EmailDurationHistory		SDH	ON SH.EmailHistoryId 	= SDH.EmailHistoryId     
                        	LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
                        	LEFT JOIN tb_User					U	ON U.UserID				= SDH.AgentId
                        	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
                        	WHERE 	SH.domainId 		= p_domainId	
   						AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
         				    AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
         
         
         					DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                            	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                            	SELECT 	
                                    t_SH.AgentId
     						      , t_SH.SessionDate
     							  ,t_SH.agentName																              						 		AS agentName
              					  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     		AS averageResponseTime
 								  ,sum(emailDuration+ AfterEmailWorkTime)                																	AS averageHandledTime          
                                   ,max(emailDuration+ AfterEmailWorkTime)/count(1)																		    AS MaximumHandledTime                                  
   							    
              					  ,CASE WHEN SUM(t_SH.AfterEmailWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.AfterEmailWorkTime)/COUNT(1) ELSE '-' END 		AS totalACWTime                    
     							  ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						        AS answeredCall
         						  ,SUM(t_SH.agentHoldDuration)                                                                						        AS callHoldTime
     							  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)							                                                AS totalTalktime
                                   ,t_SH.firstChatResolution
                                   ,t_SH.SentimentalScore                                                                                                  AS CustomerSatisfaction
                            FROM 	temp_ChatHistory t_SH
                            GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstChatResolution,t_SH.SentimentalScore;
             				
             
           
         	   
              
              
          	 SELECT sum(averageResponseTime), sum(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(firstChatResolution),sum(CustomerSatisfaction)
              INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount, v_CurrentMaximumHandledCount,v_CurrenttotalACWCount,v_CurrentfirstChatResolutionCount,v_CurrentSentimentalScore
              FROM 	temp_chatHistory_calc ;            
                        		
              SELECT 	SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(firstChatResolution),SUM(CustomerSatisfaction)
              INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount, v_PrevMaximumHandledCount,v_PrevtotalACWCount,v_PrevfirstChatResolutionCount,v_PreSentimentalScore
              FROM 	temp_chatHistory_calc ;                     
      
     		SELECT sum(totalTalktime)
             INTO   v_CurrenttotalTalkCount
      	    FROM 	temp_chatHistory_calc  ;    
            
      	  SELECT sum(totalTalktime)
     	  INTO   v_PretotalTalkCount
      	  FROM 	temp_chatHistory_calc  ;     
               
                      	SELECT * FROM temp_AllagentId;         
          	    SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 then null else v_PrevAverageResponseCount end;
          	    SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 then null else v_PrevaverageHandledCount end;
               SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0 then null else v_PreSentimentalScore end;
                 
             	SET  v_DiffAverageResponsePercent  = (v_CurrentaverageResponseCount - v_PrevAverageResponseCount) / v_PrevAverageResponseCount * 100  
   				,v_DiffAverageHandledPercent  = (v_CurrentaverageHandledCount - v_PrevaverageHandledCount) / v_PrevaverageHandledCount * 100
         		    ,v_DiffSentimentalScorePercent = (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;       
   			
            	SELECT 	IFNULL(v_CurrentaverageResponseCount,0) 			AS 'CurrentaverageResponseCount',
            			IFNULL(v_DiffAverageResponsePercent,0) 		        AS 'DiffAverageResponsePercent',
            			IFNULL(v_CurrentaverageHandledCount,0) 			    AS 'CurrentAverageHandledCount',
            			IFNULL(v_DiffAverageHandledPercent,0) 				AS 'DiffAverageHandledPercent',
            			IFNULL(v_CurrentSentimentalScore,0) 				AS 'CurrentCustomerSatisfactionCount',
            			IFNULL(v_DiffSentimentalScorePercent,0) 			AS 'DiffCustomerSatisfactionPercent';	 
   				
        
   			SELECT 															
   		U.UserName 																	                                                   AS agentName
   		,sum(a.averageResponseTime)																									   AS averageResponseTime
   		,sum(a.averageHandledTime/1000)					                                                                               AS averageHandledTime
   		,sum(a.MaximumHandledTime)																									   AS MaximumHandledTime
   		,sum(a.totalACWTime)																										   AS totalACWTime
   		,sum(CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE '-' END)                  AS averageHoldtime                                  
   		
   		,sum(a.firstChatResolution)                                                                                                    AS firstChatResolution
   		,sum(a.CustomerSatisfaction)                                                                                                   AS CustomerSatisfaction
   			FROM 	temp_chatHistory_calc 	    a
   				JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
   			
   			GROUP BY U.UserName;  
    		
               SELECT CONCAT('agentName', 'averageResponseTime', 'averageHandledTime', 'MaximumHandledTime', 'totalACWTime', 'averageHoldtime', 'firstChatResolution', 'CustomerSatisfaction') AS  columnName;   
   
           END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Email_Agent_Performances_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Email_Agent_Performances_trendchart`(
        	p_domainId 			INT,
        	p_datetype 			INT,                 
    		p_startDateTime		DATETIME,
    		p_endDateTime		DATETIME,
        	p_columnName    	VARCHAR(200),      
        	p_agentId 			TEXT
                )
BEGIN
      
       	DECLARE v_startDateTime			DATETIME;
       	DECLARE v_endDateTime			DATETIME;     
       	DECLARE v_datetimeInterval		SMALLINT;    
       	DECLARE v_startDateTimePast		DATETIME;
       	DECLARE v_endDateTimePast		DATETIME;
            
       	DECLARE v_startTimestampPast	BIGINT;
       	DECLARE v_endTimestampPast		BIGINT;      
       	DECLARE v_startTimestamp		BIGINT;
       	DECLARE v_endTimestamp			BIGINT;
       	DECLARE v_curDate				DATETIME DEFAULT NOW();	
          DECLARE v_currentCount			INT;
          DECLARE v_pastCount				INT;
           
       	DROP TEMPORARY TABLE IF EXISTS tmp_result;
       	CREATE TEMPORARY TABLE tmp_result(
       		reportAge			VARCHAR(20)
       		,startDateTime		DATETIME
       		,endDateTime		DATETIME
       		,callCount			INT
       	);    
        
        	IF p_datetype = 1 
            THEN 	
        		SET v_startDateTime = CAST(v_curDate AS DATE); 
        		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
        
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
        		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
        	END IF;
        	IF p_datetype = 2 
            THEN 
        		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
       		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
        
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
        		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
        	END IF;
        	IF p_datetype = 3 
            THEN 
        		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
               SET v_endDateTime = CAST(v_curDate AS DATE); 
                
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
        		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
        	END IF;
        	IF p_datetype = 4 
            THEN 
        		SET v_startDateTime = p_startDateTime; 
       		SET v_endDateTime 	= p_endDateTime; 
                
               SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        	END IF;
            
                   IF p_agentId IS NOT NULL 
           THEN
       		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
       		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
           ELSE
       		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
              CREATE TEMPORARY TABLE temp_agentIds
     		 select  UserID from tb_User where domainId = p_domainId ; 
  		END IF;
            
            DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
            CREATE TEMPORARY TABLE tmp_Disposition
            SELECT did, dispositionName
            FROM 	disposition_status
            WHERE	domainId		= p_domainId
            AND	dispositionName	= 'Caller Disconnected';    
            
            IF p_datetype IN (1,2)
            THEN 
        		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
        		WITH RECURSIVE CTE_TIMINGS AS (
        			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
        			UNION ALL
        			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
        			FROM 	CTE_TIMINGS
        			WHERE 	endDateTime < v_endDateTime
        		)
        		SELECT * FROM CTE_TIMINGS;	
        	ELSEIF p_datetype IN (3,4)
            THEN 
        		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
        		WITH recursive CTE_TIMINGS AS (
        			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
        			UNION ALL
        			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
        			FROM 	CTE_TIMINGS
        			WHERE 	startDateTime < v_endDateTime
        		)
        		SELECT * FROM CTE_TIMINGS;	
            END IF;  
            
            ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
            
            UPDATE tmp_timings
            SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
        		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
                
        	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
       	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
       	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
       	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
        
        
    DROP TEMPORARY TABLE IF EXISTS tmp_EmailtDurationHistory_1;	
    	CREATE TEMPORARY TABLE tmp_EmailtDurationHistory_1
    	SELECT 	
  		  CH.EmailHistoryId
    		,	CH.sessionStartTime
    		
    		,	CDH.Duration
          ,   CH.repliedDate - CH.createdAt													AS responseTime 
          , 0                															    	AS QueueWaitTime   
          , CH.AfterEmailWorkTime
  FROM 		tb_EmailHistory 			CH
  JOIN 	tb_EmailDurationHistory	CDH	    ON CH.EmailHistoryId 		= CDH.EmailHistoryId   
  WHERE 	CH.domainId 		= p_domainId
  and    CDH.AgentId is not null
  AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;          
      
      
     DROP TEMPORARY TABLE IF EXISTS tmp_EmailtDurationHistory;	
    	 CREATE TEMPORARY TABLE tmp_EmailtDurationHistory
       SELECT
  		EmailHistoryId,
          sessionStartTime,
          AVG(responseTime) 																AS averageResponseTime,
          AVG((Duration/ 1000) + AfterEmailWorkTime)  									AS averageHandlingTime,
          SUM((Duration/ 1000) + AfterEmailWorkTime)  									AS maximumHandlingTime,
          SUM(AfterEmailWorkTime)  														AS totalACWTime,
          ifnull(AVG(QueueWaitTime),0) 													AS averageQueueWaitTime
  		
      FROM tmp_EmailtDurationHistory_1
      group by EmailHistoryId,sessionStartTime; 
      
      
  
         	DROP TEMPORARY TABLE IF EXISTS tmp_EmailHistory;	
  		CREATE TEMPORARY TABLE tmp_EmailHistory
          SELECT 	DISTINCT 
     			 CDH.EmailHistoryId 
     		, 	 CDH.sessionStartTime
      
     	   FROM 	tmp_EmailtDurationHistory CDH;         
        
        
        ALTER TABLE tmp_EmailHistory  ADD averageResponseTime 	bigint default 0;
         ALTER TABLE tmp_EmailHistory  ADD averageHandlingTime 	bigint default 0;
         ALTER TABLE tmp_EmailHistory  ADD totalACWTime			bigint default 0;
         ALTER TABLE tmp_EmailHistory  ADD averageQueueWaitTime    bigint default 0;
          
          
  		CREATE INDEX ix_tmp_EmailHistory        ON tmp_EmailHistory (EmailHistoryId);
         CREATE INDEX ix_tmp_EmailDurationHistory ON tmp_EmailtDurationHistory_1 (EmailHistoryId);    
         
         
     UPDATE tmp_EmailHistory			CH
         JOIN 	tmp_EmailtDurationHistory	CDH	ON CH.EmailHistoryId	= CDH.EmailHistoryId  
        
         SET 	CH.averageResponseTime	= CDH.averageResponseTime,
     			CH.averageHandlingTime	= CDH.averageHandlingTime,
  			CH.totalACWTime	        = CDH.totalACWTime,
              CH.averageQueueWaitTime = CDH.averageQueueWaitTime;
        

         
           IF p_columnName = 'Total ACW Time'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.totalACWTime)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_EmailHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.totalACWTime)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_EmailHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
  	
      ELSEIF p_columnName = 'Avg. Response Time'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.averageResponseTime)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_EmailHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.averageResponseTime)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_EmailHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
      
      ELSEIF p_columnName = 'Avg. Handle Time (AHT)'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.averageHandlingTime)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_EmailHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.averageHandlingTime)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_EmailHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
          END IF;       
      
         
    
  		SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Current';    
        
        SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Past';
         
    	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
    	INTO 	v_currentCount, v_pastCount		
    	FROM 	tmp_result;
        
        
        end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_email_agent_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_email_agent_report`(
                 	p_startTmpstmp 		bigint,
                 	p_endTmpstmp 		bigint,
                 	p_timeZone 			varchar(200),
                 	p_domainId 			int,        
                 	p_queueIds	 		VARCHAR(250),
                 	p_agentIds 			VARCHAR(250),
         			p_offset 			INT,
                 	p_Limit 			INT     	
                 )
BEGIN 
      		DECLARE v_offset 		INT;  	
      		DECLARE v_startTmpstmp 	BIGINT;
      		DECLARE v_endTmpstmp 	BIGINT;
              	
         		SET v_offset = p_offset * p_Limit;
                
      		IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
      		IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
         
      	
      		DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
      		DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
      	
      	
      		CALL split(p_queueIds,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
      		CALL split(p_agentIds,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
              
      	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
      	CREATE TEMPORARY TABLE temp_AllqueueId
      	select qid,name as queueName from queue where domainId = p_domainId;
      	
      	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
      	CREATE TEMPORARY TABLE temp_AllagentId
      	select UserID,UserName from tb_User where domainId = p_domainId;  
                
            	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
            	CREATE TEMPORARY TABLE temp_AvailableDisposition 
      		(   DispositionId 			INT
      			,DispositionStatus 		VARCHAR(100)
      			,DispositionCategory	TINYINT
      		); 
            	INSERT INTO temp_AvailableDisposition 
            	SELECT 	did 			DispositionId
            		,	dispositionName	DispositionStatus
           		,	CASE	
      						WHEN dispositionName = 'Transferred' THEN 1
                              WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
                              WHEN dispositionName = 'Discarded' THEN 4
                              ELSE 2
             			END 			DispositionCategory
            	FROM 	disposition_status
            	WHERE 	domainId	= p_domainId;
            	
      	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory; 
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	CREATE TEMPORARY TABLE temp_EmailHistory AS 	
      	SELECT 	
      		UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE))      AS SessionDate
      	 ,	U.UserName				    												AS agentName
           ,	U.UserID																AS agentId
           ,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 					AS Opened
      	 ,	CASE WHEN DispositionCategory = 1 THEN 1 ELSE 0 END 						AS Transferred  
      	 ,	CASE WHEN DispositionCategory = 3 THEN 1 ELSE 0 END 						AS Handled
      	 ,	CASE WHEN DispositionCategory = 4 THEN 1 ELSE 0 END 						AS Discarded
      	 
          , SDH.Duration    															AS EmailHandlingTime
          , SH.AfterEmailWorkTime*1000													AS AfterEmailWorkTime
      	FROM 	tb_EmailHistory 				SH
      	JOIN 	tb_EmailDurationHistory		SDH	ON SH.EmailHistoryId 	= SDH.EmailHistoryId
      	LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
      	LEFT JOIN tb_User					U	ON U.UserID			= SDH.AgentId
      	LEFT JOIN temp_agentId 				t_A ON U.UserID 		= t_A.agentId       
      	WHERE 	SH.domainId 		= p_domainId 		
      	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
      	AND		SH.IsInBound		= 1	
    	AND U.UserName IS NOT NULL
      	AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
      	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
               
      	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_1; 	
      	CREATE TEMPORARY TABLE temp_EmailHistory_1 AS 	     
      	SELECT 	t_SH.SessionDate 																				AS sessionDate
      		,	t_SH.agentName					
      		,	t_SH.agentId					
      		,	COUNT(1)																						AS totalReceived        
      		,	SUM(t_SH.Opened)																				AS totalOpened
      		,	SUM(t_SH.Handled)																				AS totalHandled
      		,	SUM(t_SH.Transferred)																			AS totalTransferred
      		,	SUM(t_SH.Discarded)																				AS totalDiscarded
  		    ,   SUM(t_SH.EmailHandlingTime+t_SH.AfterEmailWorkTime)	 								   			AS totalEmailHandlingTime
   		    ,   (SUM(t_SH.EmailHandlingTime+t_SH.AfterEmailWorkTime)/COUNT(1))								    AS averageEmailHandlingTime    
			
      		
      	  FROM 	temp_EmailHistory t_SH
      	  GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.agentId;
            
      		SELECT * from temp_AllqueueId;
      		SELECT * from temp_AllagentId;
      	  
      	  SELECT COUNT(1) totalCount
      	  FROM temp_EmailHistory_1;
      	  
      	  SELECT *
      	  FROM 	temp_EmailHistory_1
      	  ORDER BY v_offset, p_Limit;              
      END ;;
DELIMITER ;
