DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Email_Inbound_trendchart`(
   	p_domainId 			INT,
   	p_datetype 			INT,            
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
   	p_columnName    	VARCHAR(200),    
   	p_agentId 			TEXT
    )
BEGIN
 
  	DECLARE v_startDateTime			DATETIME;
  	DECLARE v_endDateTime			DATETIME;     
  	DECLARE v_datetimeInterval		SMALLINT;    
  	DECLARE v_startDateTimePast		DATETIME;
  	DECLARE v_endDateTimePast		DATETIME;
       
  	DECLARE v_startTimestampPast	BIGINT;
  	DECLARE v_endTimestampPast		BIGINT;      
  	DECLARE v_startTimestamp		BIGINT;
  	DECLARE v_endTimestamp			BIGINT;
  	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
      
  	DROP TEMPORARY TABLE IF EXISTS tmp_result;
  	CREATE TEMPORARY TABLE tmp_result(
  		reportAge			VARCHAR(20)
  		,startDateTime		DATETIME
  		,endDateTime		DATETIME
  		,callCount			INT
  	);    
   
   	IF p_datetype = 1 
       THEN 	
   		SET v_startDateTime = CAST(v_curDate AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
   	END IF;
   	IF p_datetype = 2 
       THEN 
   		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
  		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
   	END IF;
   	IF p_datetype = 3 
       THEN 
   		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
          SET v_endDateTime = CAST(v_curDate AS DATE); 
           
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
   	END IF;
   	IF p_datetype = 4 
       THEN 
   		SET v_startDateTime = p_startDateTime; 
  		SET v_endDateTime 	= p_endDateTime; 
           
          SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
           
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
   		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
   	END IF;
       
         IF p_agentId IS NOT NULL 
         THEN
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
     		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
         ELSE
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
            CREATE TEMPORARY TABLE temp_agentIds
   		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
		END IF;
       
                      		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                  		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                  		(    DispositionId 			INT
                  			,DispositionStatus 		VARCHAR(100)
                  			,DispositionCategory	TINYINT
                  		); 
                          
                  		INSERT INTO temp_AvailableDisposition 
                  		SELECT 	did 			DispositionId
                  			,	dispositionName	DispositionStatus
                  			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                  				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                  				WHEN dispositionName = 'Discarded'     THEN 4
           					    WHEN dispositionName = 'Resolved'      THEN 5
                  				END 			DispositionCategory
                  		FROM 	disposition_status
                  		WHERE 	domainId	= p_domainId;   
       
       IF p_datetype IN (1,2)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   		WITH RECURSIVE CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	endDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
   	ELSEIF p_datetype IN (3,4)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   		WITH recursive CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	startDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
       END IF;  
       
       ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
       
       UPDATE tmp_timings
       SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
   		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
           
   	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
  	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
  	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
  	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
  
  
    DROP TEMPORARY TABLE IF EXISTS tmp_EmailDurationHistory;	
  	CREATE TEMPORARY TABLE tmp_EmailDurationHistory
  	SELECT 	CH.EmailHistoryId
  		,	CH.sessionStartTime
  		
  		,	CH.dispositionId          
  		,	CDH.Duration
        ,   CH.isOpened
   FROM 		tb_EmailHistory 			CH
   JOIN 	tb_EmailDurationHistory			CDH	    ON CH.EmailHistoryId 	= CDH.EmailHistoryId    
 
  
  	WHERE 	CH.domainId 		= p_domainId
    and CDH.AgentId > 0
  	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
  	AND 	CH.IsInBound		= 1;   
    
    
    
    DROP TEMPORARY TABLE IF EXISTS tmp_EmailHistory;	
     	CREATE TEMPORARY TABLE tmp_EmailHistory
        SELECT 	DISTINCT 
     			CDH.EmailHistoryId 
     		, 	CDH.sessionStartTime
            ,   CDH.isOpened
            ,   CDH.dispositionId
     	FROM 	tmp_EmailDurationHistory CDH;  

          ALTER TABLE tmp_EmailHistory ADD Opened     INT default 0;
         ALTER TABLE tmp_EmailHistory ADD IsAnswered 	INT default 0;
         ALTER TABLE tmp_EmailHistory ADD IsAbandoned	INT default 0;
         
         CREATE INDEX ix_tmp_EmailHistory ON tmp_EmailHistory (EmailHistoryId);
         CREATE INDEX ix_tmp_EmailDurationHistory ON tmp_EmailHistory (EmailHistoryId);
    
    
             UPDATE tmp_EmailHistory			CH
         JOIN 	tmp_EmailDurationHistory	CDH	ON CH.EmailHistoryId	= CDH.EmailHistoryId  
   
         SET    CH.Opened		= CASE WHEN CDH.isOpened = 1			THEN 1 ELSE CH.Opened 		END
     		 ,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE CH.IsAnswered 	END
             ,	CH.dispositionId	= CASE WHEN CDH.dispositionId IS NOT NULL 		THEN 1 ELSE CH.IsAbandoned 	END;
         
         	
    
  IF p_columnName = 'Opened Email'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.Opened)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_EmailHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	count(CH.Opened)	AS callCount   
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_EmailHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
      
      ELSEIF p_columnName = 'Received Email'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.EmailHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_EmailHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.EmailHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_EmailHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
      
       ELSEIF p_columnName = 'Responded Email'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.dispositionId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_EmailHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.EmailHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_EmailHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
              END IF;   
   
             SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Current';    
          
          SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Past';
           
      	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
      	INTO 	v_currentCount, v_pastCount		
      	FROM 	tmp_result;
        
        
        end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Email_Inbound_trendchart1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Email_Inbound_trendchart1`(	
 		p_startTmpstmp 	BIGINT,
       	p_endTmpstmp 	BIGINT,
       	p_domainId 		INT,
       	p_columnname 	VARCHAR(155)
       )
BEGIN
       		DECLARE v_startDateTime 				DATETIME;
       		DECLARE v_endDateTime 					DATETIME;
       		DECLARE v_startTmpstmp 					BIGINT;
       		DECLARE v_endTmpstmp 					BIGINT;
       		DECLARE v_startTime	 				    DATETIME;
       		DECLARE v_endTime	 					DATETIME;
       		DECLARE v_currenttimestamp 				BIGINT;
       		DECLARE v_previous_timestamp 			BIGINT;
       		DECLARE v_oneday_previous_timestamp 	BIGINT;
       		DECLARE v1_count_currentdata 		    BIGINT;
       		DECLARE v2_count_pastdata 				BIGINT;
       		DECLARE v_coulumnname                   VARCHAR(150);
       		DECLARE v_interval						INT;
               
               
      			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
       			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
       			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;    
                
       			SET v_coulumnname=p_columnname;
       			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
       			CREATE TEMPORARY TABLE temp_Intervals (
       			starttime DATETIME,
       			endtime   DATETIME
       			);
                    
       			SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day),from_unixtime(p_startTmpstmp/1000));
         			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
                   
                   set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                   set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                   
                   

      	 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
 		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                               	
                     
                       		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                   		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                   		(    DispositionId 			INT
                   			,DispositionStatus 		VARCHAR(100)
                   			,DispositionCategory	TINYINT
                   		);             
 							
 						INSERT INTO temp_AvailableDisposition 
                   		SELECT 	did 			DispositionId
                   			,	dispositionName	DispositionStatus
                   			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                   				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                   				WHEN dispositionName = 'Discarded'     THEN 4
            					    WHEN dispositionName = 'Resolved'      THEN 5
                   				END 			DispositionCategory
                   		FROM 	disposition_status
                   		WHERE 	domainId	= p_domainId;
                         
                         
                         
                         
                         
 				DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory;
       			CREATE TEMPORARY TABLE temp_EmailHistory
       			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
       			FROM 	tb_EmailHistory H 
       			WHERE 	H.domainId = p_domainId
       			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
       			GROUP BY H.sessionStartTime;   
                
                 
       			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
       			CREATE TEMPORARY TABLE temp_Intervals_1
       			SELECT t_I.endtime 	AS `Time`
       				,	count(1)	AS `NoofreceivedEmailCount`
       			FROM temp_Intervals t_I
       			JOIN temp_EmailHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
       			GROUP BY t_I.endtime;
           
         			SELECT  (t_I.endtime) 						AS `Time`
       				,	IFNULL(t.NoofreceivedEmailCount,0)	AS NoofreceivedcurrentEmailCount
    				    FROM 		temp_Intervals t_I 
         			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;         
                  
                  
                  DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory1;
       			CREATE TEMPORARY TABLE temp_EmailHistory1
       			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
       			FROM 	tb_EmailHistory H 
       			WHERE 	H.domainId = p_domainId
       			AND  	H.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
       			GROUP BY H.sessionStartTime;   
                  
      			 DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
       			CREATE TEMPORARY TABLE temp_Intervals_2
       			SELECT t_I.endtime 	AS `Time`
       				,	count(1)	AS `NoofreceivedEmailCount`
       			FROM temp_Intervals t_I
       			JOIN temp_EmailHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
       			GROUP BY t_I.endtime;
           
         			SELECT  (t_I.endtime) 						    AS `Time`
       				,	IFNULL(t.NoofreceivedEmailCount,0)	        AS NoofreceivedpastemailCount
       			    FROM 		temp_Intervals t_I 
         			LEFT JOIN   temp_Intervals_2 t ON t.time = t_I.endtime;
                       
                       
 			IF p_columnname = 'ReceviedEmail'
               THEN
           		
           		SELECT 	COUNT(1) 
           		INTO 	v1_count_currentdata 
           		FROM 	tb_EmailHistory
           		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
           		AND 	domainId	= p_domainId
    			    LIMIT 1;
           		
           		SELECT COUNT(1)
           		INTO 	v2_count_pastdata 
           		FROM 	tb_EmailHistory
           		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	domainId	= p_domainId
 				LIMIT 1; 
      ELSEIF         p_columnname = 'OpenedEmail'
               THEN
           		
           		SELECT 	 CASE WHEN t_D.DispositionCategory = 2 THEN 1 ElSE 0 END                AS OpenedEmail
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	CASE WHEN t_D.DispositionCategory = 2 THEN 1 ElSE 0 END                AS OpenedEmail
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;            
               ELSEIF         p_columnname = 'RespondedEmail'
               THEN
           		
           		SELECT 	 	SUM(CASE WHEN SH.dispositionId IS NOT NULL  THEN 1 ELSE 0 END)    AS respondedEmail
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	SUM(CASE WHEN SH.dispositionId IS NOT NULL  THEN 1 ELSE 0 END)       AS respondedEmail
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;              
                ELSEIF         p_columnname = 'Overdue'
               THEN
           		
           		SELECT 	 CASE WHEN  (FROM_UNIXTIME(SH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END     AS  Overdue
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	CASE WHEN  (FROM_UNIXTIME(SH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END     AS  Overdue
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;    
                           ELSEIF         p_columnname = 'discardedEmail'
                 THEN
           		
           		SELECT 	sum(CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END)                AS discardedEmail
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	sum(CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END)                AS discardedEmail
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                  ELSEIF         p_columnname = 'transferredEmail'
               THEN
           		
           		SELECT 	SH.Istransferred                     AS  transferredEmail
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	SH.Istransferred                    AS  transferredEmail
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;      
                 
                     ELSEIF         p_columnname = 'transferredEmail'
               THEN
           		
           		SELECT 	sum(SH.Istransferred)     AS  transferredEmail
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	sum(SH.Istransferred)     AS  transferredEmail
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;             
                 
                     ELSEIF         p_columnname = 'MaximumEmailHandlingTime'
               THEN
           		
           		SELECT 	sum(SH.SessionEndTime - SH.SessionStartTime)	       AS  MaximumEmailHandlingTime
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	sum(SH.SessionEndTime - SH.SessionStartTime)	        AS  MaximumEmailHandlingTime
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;         
                      
                       ELSEIF         p_columnname = 'averageEmailHandlingTime'
               THEN
           		
           		SELECT 	 ROUND((SUM(TIMESTAMPDIFF(SECOND, SH.SessionStartTime, SH.SessionEndTime)) / COUNT(*)) / 1000)       AS averageEmailHandlingTime	
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT 	 ROUND((SUM(TIMESTAMPDIFF(SECOND, SH.SessionStartTime, SH.SessionEndTime)) / COUNT(*)) / 1000)	       AS averageEmailHandlingTime	
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                     
 			ELSEIF         p_columnname = 'InteractionsFromCustomer'
               THEN
           		
           		SELECT 	COUNT(DISTINCT CONCAT(SH.FromEmail, SH.EmailSubject))         AS InteractionsFromCustomer 
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId 				 LIMIT 1;                
           		
           		SELECT COUNT(DISTINCT CONCAT(SH.FromEmail, SH.EmailSubject))           AS InteractionsFromCustomer	
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId 	 	LIMIT 1; 
 
      			ELSEIF         p_columnname = 'InteractionsFromAgent'
               THEN
           		
           		SELECT 	count(SH.AgentId)                                     AS InteractionsFromAgent
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailDurationHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT count(SH.AgentId)                                     AS InteractionsFromAgent	
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailDurationHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
   
       			ELSEIF         p_columnname = 'CustomerSatisfaction'
               THEN
           		
           		SELECT 	SUM(SH.SentimentalScore)                                            AS CustomerSatisfaction
           		INTO 	v1_count_currentdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                   
           		
           		SELECT SUM(SH.SentimentalScore)                                            AS CustomerSatisfaction
           		INTO 	v2_count_pastdata 
 				FROM 	tb_EmailHistory SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
  
                	END IF;        
        		SELECT 	v1_count_currentdata																    currentdata
           		,	v2_count_pastdata																		pastdata
           		,	(v1_count_currentdata - v2_count_pastdata) 												dataDifference 
       			,	(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	          
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_email_interaction_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_email_interaction_report`(
           p_startTmpstmp 		BIGINT,
           p_endTmpstmp 		BIGINT,
           p_timeZone 			VARCHAR(200),
           p_domainId 			INT,        
           p_queueIds	 		VARCHAR(250),
           p_agentIds 			VARCHAR(250),
           p_direction			TINYINT,
           p_dispositionIds		VARCHAR(250),
           p_offset 			INT,
           p_Limit 				INT     	
           )
BEGIN 
         	DECLARE v_offset 		INT;  	
         	DECLARE v_startTmpstmp 	BIGINT;
         	DECLARE v_endTmpstmp 	BIGINT;    
         
         	SET v_offset = p_offset * p_Limit;
         
         	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
         	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
         
         	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId 		VARCHAR(100));
         	DROP TEMPORARY TABLE IF EXISTS temp_direction;	CREATE TEMPORARY TABLE temp_direction(directionId 	TINYINT);
         	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
              
         	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;	
         	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
       	
       	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
       	CREATE TEMPORARY TABLE temp_AllagentId
       	select UserID,UserName from tb_User where domainId = p_domainId ;  
               
         	IF p_direction IS NULL
         	THEN
         		INSERT INTO temp_direction
         		  (directionId)
         		  VALUES (0),(1);
         	ELSE
         		INSERT INTO temp_direction
         		  (directionId)
         		  SELECT p_direction;
         	END IF;
           
			DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
			CREATE TEMPORARY TABLE temp_AlldirectionId
			select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
			WHEN directionId = 1 THEN 'InBound' END AS directionName 
			FROM temp_direction ;
                
         	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
         	CREATE TEMPORARY TABLE temp_AvailableDisposition 
         	(	dispositionId 		INT,
         		DispositionStatus 	VARCHAR(100)
         	);
                
            	INSERT INTO temp_AvailableDisposition 
            	SELECT 	did 			dispositionId
            		,	dispositionName	DispositionStatus
            	FROM 	disposition_status
            	WHERE 	domainId	= p_domainId;
            	
         	INSERT INTO temp_AvailableDisposition 
         	SELECT 	TypeCodeID		dispositionId
         		,	TypeCodeName	DispositionStatus
         	FROM 	TypeCode
         	WHERE 	TypeGroupID = 1120;     
                
            	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory; 
            	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            	CREATE TEMPORARY TABLE temp_EmailHistory AS 	
           	SELECT 		SH.sessionStartTime as `time`
                      ,	SH.FromEmail		           
                      ,	U.UserName				as agentName
                      ,	SH.IsInBound            as isInBound
                      ,	SH.sessionEndTime - SH.sessionStartTime	as totalDuration
                      ,	SH.dispositionId
                      ,	SH.afterEmailWorkTime	as acwTime
                      ,	SH.dispositionSubject 
                      ,	SH.Summary 
      		FROM 	tb_EmailHistory 			SH
      		JOIN 	tb_EmailDurationHistory		SDH		ON SH.EmailHistoryId 	= SDH.EmailHistoryId
      		JOIN 	temp_direction				t_DIR	ON t_DIR.directionId	= SH.IsInBound
      		LEFT JOIN tb_User					U		ON U.UserID				= SDH.AgentId
      		LEFT JOIN temp_agentId	 			t_A 	ON U.UserID  			= t_A.agentId       
      		LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
      		WHERE 	SH.domainId 			= p_domainId 		
      		AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
      		AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
      		AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
               
      	SELECT * from temp_AllagentId;
      	SELECT * from temp_AvailableDisposition;
      	SELECT * from temp_AlldirectionId;
               
      	SELECT 	COUNT(1)  totalCount
      	FROM 	temp_EmailHistory;       
	
		IF ((p_Limit IS NOT NULL)AND(p_offset IS NOT NULL)) THEN
        
			DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_1; 	
			CREATE TEMPORARY TABLE temp_EmailHistory_1 AS 	    
			SELECT 	*
			FROM 	temp_EmailHistory
			ORDER BY `time` DESC 
			LIMIT v_offset, p_Limit; 
            
        ELSE
			DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_1; 	
			CREATE TEMPORARY TABLE temp_EmailHistory_1 AS 	    
			SELECT 	*
			FROM 	temp_EmailHistory
			ORDER BY `time` DESC ; 
            
		END IF;
          
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
    	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
    	CREATE TEMPORARY TABLE temp_customer_contact
    	SELECT 	coid,primaryEmail,email,firstName,lastName      
    	FROM 	customer_contact 
    	WHERE 	domainId = p_domainId;       
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
          
      	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact1;
      	CREATE TEMPORARY TABLE temp_customer_contact1   
          SELECT * FROM temp_customer_contact;
          
      	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_2;
      	CREATE TEMPORARY TABLE temp_EmailHistory_2	
    	SELECT 	SH.`time` as `dateTime`
    		,	SH.FromEmail        
    		,	SH.agentName
    		,	CASE 	WHEN SH.IsInBound = 1 THEN 'InBound'
    					WHEN SH.IsInBound = 0 THEN 'OutBound'
    			END		AS direction
    		
    		,	round(SH.totalDuration/1000  )  as totalDuration             
    		,	SH.ACWtime
    		,	t_A.DispositionStatus		disposition
            ,	dispositionSubject as subject
            ,	Summary as summary
    	FROM 	temp_EmailHistory_1			SH
    	JOIN 	temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId;   	   	
          
    	ALTER TABLE temp_EmailHistory_2 ADD COLUMN customerName 		VARCHAR(150);        
    	ALTER TABLE temp_EmailHistory_2 ADD COLUMN customerEmailId 	     VARCHAR(750);
          
      	UPDATE 	temp_EmailHistory_2		EH
      	JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryEmail	LIKE  EH.FromEmail											
      	SET 	customerName		= CONCAT(c_c.firstName, ' ',c_c.lastName)
      	
           , customerEmailId = CONCAT(primaryEmail, ',', REPLACE(REPLACE(REPLACE(c_c.email, '["', ''), '"]', ''), '[]', ''));
     

      	UPDATE 	temp_EmailHistory_2		EH        
      	SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.email LIKE CONCAT('%',EH.FromEmail,'%') ORDER BY InTC.coid LIMIT 1)
      	WHERE 	IFNULL(customerName,'') = '';        
        
      	UPDATE 	temp_EmailHistory_2		EH        
      	
SET customerEmailId = (
    SELECT CONCAT(InTC.primaryEmail, ',', REPLACE(REPLACE(REPLACE(InTC.email, '["', ''), '"]', ''), '[]', '')) 
    FROM temp_customer_contact1 InTC 
    WHERE InTC.email LIKE CONCAT('%', EH.FromEmail, '%') 
    ORDER BY InTC.coid 
    LIMIT 1
)

        
      	WHERE 	IFNULL(customerEmailId,'') = ''; 
        
      	UPDATE 	temp_EmailHistory_2		EH        
      	SET 	customerName	= 'New Customer'
      	WHERE 	IFNULL(customerName,'') = '';
          
          SELECT * FROM temp_EmailHistory_2;
          
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
