/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Facebook_agent_performances_analysis_metrics_filter`(  
               p_startTmpstmp    BIGINT,
               p_endTmpstmp 	BIGINT,
               p_domainId 		INT,    	
               p_agentId		VARCHAR(250),		
               p_offset 		INT,
               p_Limit 			INT	
                        )
BEGIN
                    
    		DECLARE v_offset 								INT;	  	
   		DECLARE v_CurrentStartTmpstmp 					BIGINT;
   		DECLARE v_CurrentEndTmpstmp 					BIGINT;
   						
    		DECLARE v_PrevStartTmpstmp 		    			BIGINT;
   		DECLARE v_PrevEndTmpstmp 						BIGINT; 
    		DECLARE v_TmpstmpInterval						BIGINT;	
             		
 		DECLARE v_PrevAverageResponseCount				BIGINT;	
 		DECLARE v_CurrentAverageResponseCount			BIGINT;	        
    		DECLARE v_DiffAverageResponsePercent    		BIGINT;
   					
   		DECLARE v_PrevAverageHandledCount				INT;	
 		DECLARE v_CurrentAverageHandledCount			INT;
 		DECLARE v_DiffAverageHandledPercent				INT;  	    
   						
 		DECLARE v_PrevMaximumHandledCount				INT;	
 		DECLARE v_CurrentMaximumHandledCount			INT;	        
    		DECLARE v_DiffMaximumHandledTimePercent			INT;    
   					
   		DECLARE v_PrevTotalACWCount		      			INT;	
 		DECLARE v_CurrentTotalACWCount		  		INT;	        
   		DECLARE v_DiffTotalACWTimePercent	  			INT;   
                
    		DECLARE v_PrevAverageQueueWaitingCount		    INT;	
 		DECLARE v_CurrentAverageQueueWaitingCount	INT;	        
    		DECLARE v_DiffAverageQueueWaitingPercent		INT; 
                
            
    		DECLARE v_PrevaverageHoldtCount		        	INT;	
 		DECLARE v_CurrentaverageHoldtCount		    	INT;	        
    		DECLARE v_DiffaverageHoldtPercent		    	INT; 
                
               
   		DECLARE v_PrevMaximumQueueWaitingCount		    INT;	
    		DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
   		DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
            
    		DECLARE v_PrevfirstChatResolutionCount		    INT;	
    		DECLARE v_CurrentfirstChatResolutionCount		INT;	        
 		DECLARE v_DifffirstChatResolutionPercent		INT;  
                                
   		DECLARE v_PreSentimentalScore              		INT;
   		DECLARE v_CurrentSentimentalScore          		INT;
   		DECLARE v_DiffSentimentalScorePercent      		INT;      
               
 		DECLARE v_PrevAgentIdleTimeCount		      	INT;	
   		DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
 		DECLARE v_DifffirsAgentIdleTimePercent	        INT;    
               
   		DECLARE v_PreavailableCount                     INT;
   		DECLARE v_CurrentavailableCount                 INT;                      
   		DECLARE v_PretotalTalkCount                     INT;
   		DECLARE v_CurrenttotalTalkCount                 INT;  
    		DECLARE v_CurrentAvailableTime          		INT;
   		DECLARE v_TotalTalktime                         BIGINT;
        
        
        
             	SET v_offset =  p_Limit * p_offset; 
               
               	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
               	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
               	
             	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
             
             	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
             	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
               		
               	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
               	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
                    
                   	        
                         	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                         	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                    	
                          
                            		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                        		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
                                
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                        				WHEN dispositionName = 'Discarded'     THEN 4
                 					    WHEN dispositionName = 'Resolved'      THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;
                         	
                         	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                         	CREATE TEMPORARY TABLE temp_AllagentId
                         	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
                           
                           
   							SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                         	    DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
                       	    CREATE TEMPORARY TABLE temp_FacebookHistory AS 	    	
                             	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		            	AS SessionDate
   							  , SH.AgentId
    							  ,	U.UserName													                	AS agentName
    							  , SH.IsInBound
    							  , SH.Duration                                                                	    AS callDuration
    							  , NUll                                                                        	AS agentHoldDuration
    							  , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		        		AS Handled		
   							  , CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                			AS firstChatResolution      
      							  , SH.SessionStartTime                                                    		AS agentconnecttime
   							  ,	SH.SessionEndTime - SH.SessionStartTime	 						       			AS chatHandlingTime  
                               ,CASE WHEN SH.IsSessionClosed =1 Then SH.repliedDate - SH.createdAt ELSE 0 END    AS responseTime
   							  
 							  , SH.Duration												           				AS Duration						
   							  , SH.afterFacebookWorkTime                                       
    							  , SH.SentimentalScore
   							  , null                                                                        	AS queueDuration
                           	FROM 	tb_FacebookHistory 			SH    
                            	LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
                           	LEFT JOIN tb_User					U	ON U.UserID				= SH.AgentId
                           	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
                           	WHERE 	SH.domainId 		=  p_domainId	
    						     AND 	SH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ;                      
                           
                           DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_calc; 
      						CREATE TEMPORARY TABLE temp_FacebookHistory_calc AS 	
      						SELECT 	
      							    t_SH.AgentId
    							  , t_SH.SessionDate
    							  ,t_SH.agentName																              						 		 	 AS agentName
     							  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     		 AS averageResponseTime
      							  ,	SUM(t_SH.Handled)					  							                                                 	     AS averageHandledTime    
     							  ,	MAX(t_SH.Handled) / COUNT(1)						  							                                 		 AS MaximumHandledTime 
     							  ,CASE WHEN SUM(t_SH.afterFacebookWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.afterFacebookWorkTime)/COUNT(1) ELSE '-' END AS totalACWTime                    
    							  ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						         	 AS answeredCall
    							  ,SUM(t_SH.agentHoldDuration)                                                                						         	 AS callHoldTime
    							  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)							                                                 	 AS totalTalktime
      							  ,t_SH.firstChatResolution
      							  ,t_SH.SentimentalScore                                                                                                     AS CustomerSatisfaction
                                  ,t_SH.queueDuration                                                                                                         AS queueWaitingtime
                               FROM 	temp_FacebookHistory t_SH
                               GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstChatResolution,t_SH.SentimentalScore,t_SH.queueDuration;
                               
                               
        				ALTER TABLE temp_FacebookHistory_calc ADD COLUMN availableTime		INT;              
      		
      				UPDATE 	temp_FacebookHistory_calc	SH_C
                       JOIN 	temp_agentIDs	        t_A		ON 	SH_C.agentId = t_A.agentId        
                       SET 	 
               				availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.timerStatusId = 1 THEN S.stateDuration ELSE 0 END) 
               									FROM 	state_timer S	
                                                   WHERE  S.domainId	= p_domainId
                                                   AND 	S.startTimestamp	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp );                 
                           
           			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
                       
                       
    			  SELECT SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(firstChatResolution),SUM(CustomerSatisfaction)
                 INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount, v_CurrentMaximumHandledCount,v_CurrenttotalACWCount,v_CurrentfirstChatResolutionCount,v_CurrentSentimentalScore
                 FROM 	temp_FacebookHistory_calc ;                                        
                                    
              		
                 SELECT 	SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(firstChatResolution),SUM(CustomerSatisfaction)
                 INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount, v_PrevMaximumHandledCount,v_PrevtotalACWCount,v_PrevfirstChatResolutionCount,v_PreSentimentalScore
                 FROM 	temp_FacebookHistory_calc ;                     
         
   				SELECT sum(totalTalktime),max(queueWaitingtime),sum(queueWaitingtime)
   				INTO   v_CurrenttotalTalkCount,v_CurrentMaximumQueueWaitingCount,v_CurrentAverageQueueWaitingCount
   				FROM 	temp_FacebookHistory_calc  ;    
   				
   				SELECT sum(totalTalktime),max(queueWaitingtime),sum(queueWaitingtime)
   				INTO   v_PretotalTalkCount,v_PrevMaximumQueueWaitingCount,v_PrevAverageQueueWaitingCount
   				FROM 	temp_FacebookHistory_calc  ;                    
                       
                    SELECT * FROM temp_AllagentId;         
            	    SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 THEN NULL ELSE v_PrevAverageResponseCount END;
            	    SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 THEN NULL ELSE v_PrevaverageHandledCount   END;
                    SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0     tHEN NULL ELSE v_PreSentimentalScore       END;
                   
               	SET  v_DiffAverageResponsePercent  = (v_CurrentaverageResponseCount - v_PrevAverageResponseCount) / v_PrevAverageResponseCount * 100  
     				,v_DiffAverageHandledPercent  = (v_CurrentaverageHandledCount - v_PrevaverageHandledCount) / v_PrevaverageHandledCount * 100
           		    ,v_DiffSentimentalScorePercent = (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;       
     			
              	SELECT 	IFNULL(v_CurrentaverageResponseCount,0) 			AS 'CurrentaverageResponseCount',
              			IFNULL(v_DiffAverageResponsePercent,0) 		        AS 'DiffAverageResponsePercent',
              			IFNULL(v_CurrentaverageHandledCount,0) 			    AS 'CurrentAverageHandledCount',
              			IFNULL(v_DiffAverageHandledPercent,0) 				AS 'DiffAverageHandledPercent',
              			IFNULL(v_CurrentSentimentalScore,0) 				AS 'CurrentCustomerSatisfactionCount',
              			IFNULL(v_DiffSentimentalScorePercent,0) 			AS 'DiffCustomerSatisfactionPercent';	                    
                       
     SELECT
         	'All Agents'											      																  	AS agentName       
          ,0                                                                                                                             	AS AgentIdleTime
          ,IFNULL(v_CurrentaverageResponseCount,0)                      																  	AS averageResponseTime
      	   ,IFNULL(v_CurrentaverageHandledCount,0)                       																  	AS averageHandledTime
          ,IFNULL(v_CurrentMaximumHandledCount,0)                       																  	AS MaximumHandledTime
      	   ,IFNULL(v_CurrenttotalACWCount,0)                             																  	AS totalACWTime
          ,IFNULL(v_CurrentaverageHoldtCount,0)                         																  	AS averageHoldtime      
          ,IFNULL(v_CurrentAverageQueueWaitingCount,0)   																				  	AS averageQueueWaitingtime
          ,0																				                                              	AS maximumQueueWaitingtime
    	   ,IFNULL((v_TotalTalktime)   /(v_CurrentavailableTime) ,0)                                                                      	AS occupancyrate       
          ,IFNULL(v_CurrentfirstChatResolutionCount,0)                  																  	AS firstChatResolution
          ,IFNULL(v_CurrentSentimentalScore,0)                          																  	AS CustomerSatisfaction
         UNION ALL
   		SELECT 															
   		U.UserName 																	                                                   	AS agentName
   		,0	
   		,SUM(a.averageResponseTime/1000)	
   		,SUM(a.averageHandledTime/1000)					                                                                               	AS averageHandledTime
   		,SUM(a.MaximumHandledTime)	
   		,SUM(a.totalACWTime)	
   		,SUM(CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE '-' END)                  	AS averageHoldtime        
   		,sum(a.queueWaitingtime)              	   																	       			   	AS averageQueueWaitingtime          
   		,0      	   																		   				   						   	AS maximumQueueWaitingtime   
   		
   		,sum(a.totalTalktime/a.availableTime)*100											                                           	AS occupancyrate
   		,SUM(a.firstChatResolution)                                                                                                    	AS firstChatResolution
   		,SUM(a.CustomerSatisfaction)                                                                                                   	AS CustomerSatisfaction
   		FROM 	temp_FacebookHistory_calc 	    a
   		JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
   	
   		GROUP BY U.UserName;  
    
    
    SELECT CONCAT('agentName','AgentIdleTime', 'averageResponseTime', 'averageHandledTime', 'MaximumHandledTime', 'totalACWTime', 'averageHoldtime', 'averageQueueWaitingtime','maximumQueueWaitingtime','occupancyrate','firstChatResolution', 'CustomerSatisfaction') AS  columnName;   
     
    
                        
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Facebook_agent_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Facebook_agent_servicelevel_analysis_metrics_filter`(
			p_startTmpstmp 		BIGINT,
			p_endTmpstmp 		BIGINT,
			p_domainId 			INT,
			p_agentId 			TEXT,
			p_offset 			INT,
			p_Limit 		    INT	
		)
sp_return:begin
          
 			DECLARE v_offset 					INT;	  	
 			DECLARE v_CurrentStartTmpstmp 		BIGINT;
 			DECLARE v_CurrentEndTmpstmp 		BIGINT;
 			DECLARE v_PrevStartTmpstmp 			BIGINT;
 			DECLARE v_PrevEndTmpstmp 			BIGINT; 
 			DECLARE v_TmpstmpInterval			BIGINT;	
 			
 			DECLARE  v_CurTotalCount 				INT;        
 			DECLARE  v_PrevTotalCount 			    INT;                    
 			DECLARE  v_DiffTotalPercent 		    INT;     
 			
 			DECLARE  v_CurTotalSLA                  INT; 
 			DECLARE  v_PrevTotalSLA             	INT; 
 			DECLARE  v_DiffTotalSLAPercent      	INT; 
 		
 			DECLARE  v_CurMissedChats                INT; 
 			DECLARE  v_PrevMissedChats               INT;          
           
 			DECLARE  v_CurSL1               		INT; 
 			DECLARE  v_CurSL2               		INT; 
 			DECLARE  v_DiffSL2Percent       		INT;  
 			DECLARE  v_CurSL3               		INT; 
 			DECLARE  v_DiffSL3Percent       		INT;  
 			DECLARE  v_CurSL4               		INT; 
 			DECLARE  v_DiffSL4Percent       		INT;  
 			DECLARE  v_CurSL5               		INT; 
 			DECLARE  v_DiffSL5Percent       		INT;    
 			DECLARE  v_CurSL6               	    INT; 
 			DECLARE  v_DiffSL6Percent       		INT; 
          
 			DECLARE  v_CuransweredSLACount        	INT; 
 			DECLARE  v_PrevansweredSLACount       	INT; 
 			DECLARE  v_DiffansweredSLAPercent     	INT; 
 			
 			DECLARE  v_CurabandonedSLACount       	INT; 
 			DECLARE  v_PrevabandonedSLACount      	INT; 
 			DECLARE  v_DiffabandonedSLAPercent    	INT; 
 			
 			DECLARE  v_CurSLAbreachedCount        	INT; 
 			DECLARE  v_PrevSLAbreachedCount       	INT; 
 			DECLARE  v_DiffSLAbreachedPercent     	INT; 
              
 			DECLARE  v_CurChatTypeCount             INT; 
 			DECLARE  v_PrevChatTypeCount            INT; 
 			DECLARE  v_DiffChatTypePercent          INT;  
 			DECLARE  v_CurSLAAchievedCount          INT;  
              
			SET v_offset =  p_Limit * p_offset; 

			IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
			IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									

			SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;

			SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
			SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
			DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
			CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  

			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);


			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
			CREATE TEMPORARY TABLE temp_AvailableDisposition 
				(    DispositionId 			INT
					,DispositionStatus 		VARCHAR(100)
					,DispositionCategory	TINYINT
				); 
					
			INSERT INTO temp_AvailableDisposition 
			SELECT 	did 			DispositionId
				,	dispositionName	DispositionStatus
				,	CASE WHEN dispositionName = 'Opened'	THEN 2
					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
					WHEN dispositionName = 'Disconnected'         THEN 4
					WHEN dispositionName = 'Resolved'             THEN 5
					END 			DispositionCategory
			FROM 	disposition_status
			WHERE 	domainId	= p_domainId;          
		  
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
		CREATE TEMPORARY TABLE temp_AllagentId
		SELECT 	UserID,UserName 
		FROM 	tb_User 
		WHERE 	domainId 	= p_domainId; 
						  
			DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
			CREATE TEMPORARY TABLE temp_FacebookHistory AS 	    	
				SELECT	t_A.UserID                                                                  					AS agentID
				,t_A.UserName													      		   							AS agentName     
				,SH.FacebookHistoryId							
				,SH.sessionStartTime							
				,SH.dialDuration                                                       	   							                 
				,SH.Duration												      	       							 AS Duration
				,SH.IsMissed												      	       							
				,CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END                   							 AS Answered
				,CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END 		           							 AS Abandoned
				 ,CASE WHEN  (FROM_UNIXTIME(SH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END AS  Overdue 
			FROM 	tb_FacebookHistory 		    SH  
			LEFT JOIN 	temp_AllagentId 			t_A 		ON SH.AgentId		    = t_A.UserID  
			LEFT JOIN temp_AvailableDisposition		t_D			ON SH.dispositionId	    = t_D.DispositionId
			WHERE 	SH.domainId 		= p_domainId	
			AND 	SH.IsBot			= 0
			AND 	SH.AgentId IS NOT NULL
			AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
			AND 	(IFNULL(p_agentId,'')='' OR SH.AgentId IN (SELECT agentId FROM temp_agentIDs ));                               
		                  
			 DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_calc; 
			CREATE TEMPORARY TABLE temp_FacebookHistory_calc AS 	   
			SELECT																							
			a.agentID,
			a.agentName,
			a.FacebookHistoryId,  
			a.sessionStartTime,
			SUM(a.Answered+a.Abandoned)                             													AS ChatType,  
			SUM(a.Duration) 																							AS totalDuration,
			SUM(CASE WHEN dialDuration BETWEEN 0 AND  5 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END)      			AS SL1,
			SUM(CASE WHEN dialDuration BETWEEN 6  AND 10 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END)  				AS SL2,
			SUM(CASE WHEN dialDuration BETWEEN 11 AND 15 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL3,
			SUM(CASE WHEN dialDuration BETWEEN 16 AND 20 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL4,
			SUM(CASE WHEN dialDuration BETWEEN 21 AND 25 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL5,
			SUM(CASE WHEN dialDuration BETWEEN 26 AND 30 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL6,
			SUM(CASE WHEN IsMissed = 1 THEN 1 ELSE 0 END) 																AS MissedChats,
			SUM(CASE WHEN a.Overdue = 'Aborted' THEN 1 ELSE 0 END)  													AS Overdue
			FROM temp_FacebookHistory a
			GROUP BY a.agentID,a.agentName,a.FacebookHistoryId,a.sessionStartTime; 

			 DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_calc1; 
			CREATE TEMPORARY TABLE temp_FacebookHistory_calc1 AS 
			 SELECT
				a.agentID,
				a.agentName,
				a.sessionStartTime,
				SUM(a.ChatType) AS ChatType,
                SUM(a.Overdue) AS Overdue,
				SUM(a.totalDuration) AS totalDuration,
				SUM(a.SL1) AS SL1,
				SUM(a.SL2) AS SL2,
				SUM(a.SL3) AS SL3,
				SUM(a.SL4) AS SL4,
				SUM(a.SL5) AS SL5,
				SUM(a.SL6) AS SL6,
				SUM(CASE WHEN FacebookHistoryId IS NOT NULL THEN 1 ELSE 0 END) 		as TotalSLA,
				SUM(a.MissedChats) AS MissedChats,
				SUM(a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6)                   AS answeredSLA,
				SUM(CASE WHEN (a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6 + a.MissedChats) = 0 THEN 1 ELSE 0 END)                  										AS abandonedSLA,    
                IFNULL((SUM(a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6)/SUM(CASE WHEN FacebookHistoryId IS NOT NULL THEN 1 ELSE 0 END)) * 100,0)						AS AchievedSLA,
				IFNULL((100 - (SUM(a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6)/SUM(CASE WHEN FacebookHistoryId IS NOT NULL THEN 1 ELSE 0 END)) * 100),0)                AS SLAbreached							                                 
		   FROM temp_FacebookHistory_calc a  
		   GROUP BY a.agentID,a.agentName,a.sessionStartTime;
		        
		 SELECT  SUM(TotalSLA),	SUM(answeredSLA), SUM(MissedChats) ,sum(ChatType)              														                     				 
		INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats ,v_CurChatTypeCount                           														                      					
		FROM 	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
	   
		SELECT 	SUM(TotalSLA),	SUM(answeredSLA), SUM(MissedChats) ,sum(ChatType)                       																								 
		INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats ,v_PrevChatTypeCount                                 														 										
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;                 
		  
		SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
		INTO    v_CurSL1 ,v_CurSL2 ,v_CurSL3,v_CurSL4,v_CurSL5, v_CurSL6 
		FROM 	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;         
		  
		SELECT 	SUM(IFNULL(answeredSLA, 0))
		INTO 	v_PrevansweredSLACount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
	
		SELECT 	SUM(IFNULL(answeredSLA, 0))
		INTO 	v_CuransweredSLACount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
	
		SELECT 	SUM(IFNULL(abandonedSLA, 0))
		INTO 	v_PrevabandonedSLACount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
	
		SELECT 	SUM(IFNULL(abandonedSLA, 0))
		INTO 	v_CurabandonedSLACount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;             
		  
		SELECT 	SUM(IFNULL(SLAbreached, 0))
		INTO 	v_PrevSLAbreachedCount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
	
		SELECT 	SUM(IFNULL(SLAbreached, 0))
		INTO 	v_CurSLAbreachedCount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;      
        
        SELECT 	SUM(IFNULL(AchievedSLA, 0))
		INTO 	v_CurSLAAchievedCount 
		FROM	temp_FacebookHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
             
 		SET v_PrevTotalCount       	= CASE WHEN v_PrevTotalCount        = 0  THEN NULL ELSE     v_PrevTotalCount        END; 
  		SET v_PrevansweredSLACount 	= CASE WHEN v_PrevansweredSLACount  = 0  THEN NULL ELSE     v_PrevansweredSLACount  END;
   		SET v_PrevabandonedSLACount	= CASE WHEN v_PrevabandonedSLACount = 0  THEN NULL ELSE     v_PrevabandonedSLACount END;
  		SET v_PrevSLAbreachedCount 	= CASE WHEN v_PrevSLAbreachedCount  = 0  THEN NULL ELSE     v_PrevSLAbreachedCount  END;
     
 		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
    	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
		,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
		,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
         
         SELECT * FROM temp_AllagentId;
                
 		SELECT 
 		IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
 		IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
 		IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
 		IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
 		IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
 		IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';    
         
          SELECT
   				  'All Agents'												   							AS agentName
 				 ,'Answered'                                                   					        AS ChatType
                  ,IFNULL(v_CurSL1,0)                                          							AS SL1
                  ,IFNULL(v_CurSL2,0)                                          							AS SL2
                  ,IFNULL(v_CurSL3,0)                                          							AS SL3
                  ,IFNULL(v_CurSL4,0)                                          							AS SL4
                  ,IFNULL(v_CurSL5,0)                                          							AS SL5
                  ,IFNULL(v_CurSL6,0)                                          							AS SL6
                  ,IFNULL(v_CurTotalSLA,0)                                      						AS Total
 				 ,IFNULL(v_CurMissedChats,0)                                   						    AS MissedChats           
				 ,IFNULL(v_CurSLAAchievedCount,0)                                                       AS SLAAchieved
				 ,IFNULL(v_CurSLAbreachedCount,0)                                                       AS SLABreached
                 UNION ALL
           	   SELECT 	  
                    agentName													                                				
					, sum(ChatType) AS ChatType
					, sum(SL1) AS SL1
					, sum(SL2) AS SL2
					, sum(SL3) AS SL3
					, sum(SL4) AS SL4
					, sum(SL5) AS SL5
					, sum(SL6) AS SL6
					, sum(TotalSLA) AS TotalSLA
					, sum(MissedChats) AS MissedChats
					, IFNULL((SUM(answeredSLA)/SUM(TotalSLA)) * 100,0)       	AS SLAachieved
                    , IFNULL((100 - (SUM(answeredSLA)/SUM(TotalSLA)) * 100),0)  AS SLAbreached
			FROM temp_FacebookHistory_calc1 
			WHERE 	sessionStartTime    	   BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
			GROUP BY agentName;    

 		SELECT CONCAT('agentName', 'ChatType', 'SL1', 'SL2', 'SL3', 'SL4', 'SL5', 'SL6', 'Total', 'MissedChats', 'SLAAchieved', 'SLAbreached') AS  columnName;   
           
            END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Facebook_inbound_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Facebook_inbound_trendChart`(
	p_domainId 			INT,
	p_datetype 			INT,            
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
	p_columnName    	VARCHAR(200),    
	p_agentId 			TEXT
   )
BEGIN
   
   
  	DECLARE v_startDateTime			DATETIME;
  	DECLARE v_endDateTime			DATETIME;     
  	DECLARE v_datetimeInterval		SMALLINT;    
  	DECLARE v_startDateTimePast		DATETIME;
  	DECLARE v_endDateTimePast		DATETIME;
       
	DECLARE v_startTimestampPast	BIGINT;
	DECLARE v_endTimestampPast		BIGINT;      
	DECLARE v_startTimestamp		BIGINT;
	DECLARE v_endTimestamp			BIGINT;
	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
      
  	DROP TEMPORARY TABLE IF EXISTS tmp_result;
  	CREATE TEMPORARY TABLE tmp_result(
  		reportAge			VARCHAR(20)
  		,startDateTime		DATETIME
  		,endDateTime		DATETIME
  		,fbCount			INT
  	);    
   
   	IF p_datetype = 1 
       THEN 	
   		SET v_startDateTime = CAST(v_curDate AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
   	END IF;
   	IF p_datetype = 2 
       THEN 
   		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
  		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
   	END IF;
   	IF p_datetype = 3 
           THEN 
                 SET v_startDateTime = p_startDateTime;
                 SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                 
     			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                 
         		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                 SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       	IF p_datetype = 4 
           THEN 
       		SET v_startDateTime = p_startDateTime; 
               SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND); 
               
               SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       
       IF p_agentId IS NOT NULL 
       THEN
   		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
   		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
       ELSE
   		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
          CREATE TEMPORARY TABLE temp_agentIds
 		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
               END IF;
       DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
       CREATE TEMPORARY TABLE tmp_Disposition
       SELECT did, dispositionName
       FROM 	disposition_status
       WHERE	domainId		= p_domainId;
       
       IF p_datetype IN (1,2)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
			WITH RECURSIVE CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE), INTERVAl 59 SECOND) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	endDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
   	ELSEIF p_datetype IN (3,4)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   		WITH recursive CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	startDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
       END IF;  
       
       ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
            
       UPDATE tmp_timings
       SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
   		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
           
   	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
  	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
  	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
  	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
     
    DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory;	
  	CREATE TEMPORARY TABLE tmp_FacebookDurationHistory
  	SELECT 
        I.FacebookHistoryId,
        I.sessionStartTime,
        I.IsInBound,
        I.Duration,
        I.Istransferred,
        FROM_UNIXTIME(sessionStartTime/1000) AS aa,
        CASE WHEN DS.dispositionName = 'Caller Disconnected' THEN 1 ELSE 0 END AS abandoned
	FROM tb_FacebookHistory   I
    
    LEFT JOIN disposition_status	DS 		ON DS.did = I.dispositionId
  	WHERE 	I.domainId 		= p_domainId
  	AND 	I.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
  	AND 	I.IsInBound		= 1
    AND 	I.IsBot			= 0
    AND 	I.AgentId IS NOT NULL;
    
  	DROP TEMPORARY TABLE IF EXISTS tmp_FacebookHistory;	
   	CREATE TEMPORARY TABLE tmp_FacebookHistory
      SELECT 	DISTINCT 
   			CDH.FacebookHistoryId 
   		, 	CDH.sessionStartTime
   	FROM 	tmp_FacebookDurationHistory CDH;  
       
       ALTER TABLE tmp_FacebookHistory ADD IsInbound		TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD IsResponded 		TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD IsAbandoned		TINYINT default 0;
       
       CREATE INDEX ix_tmp_FacebookHistory ON tmp_FacebookHistory (FacebookHistoryId);
       CREATE INDEX ix_tmp_FacebookDurationHistory ON tmp_FacebookDurationHistory (FacebookHistoryId);
   
       UPDATE 	tmp_FacebookHistory				CH
       JOIN 	tmp_FacebookDurationHistory	CDH	ON CH.FacebookHistoryId	= CDH.FacebookHistoryId 
       SET 	CH.IsInbound		= CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN 1 ELSE 0 END
   		,	CH.IsResponded		= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE 0 END
        ,	CH.IsAbandoned		= CASE WHEN CDH.abandoned = 1 		THEN 1 ELSE 0 END;
     
     IF p_columnName = 'Received Chats'
       THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'				AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	SUM(CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS fbCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
		INSERT INTO tmp_result
   		SELECT 	'Past'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	SUM(CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS fbCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
  ELSEIF p_columnName = 'Responded Chats'
       THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(IsResponded),0)	AS fbCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
		INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(IsResponded),0)	AS fbCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;   
   ELSEIF p_columnName = 'Abandoned Chats'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(IsAbandoned),0)	AS fbCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(IsAbandoned),0)	AS fbCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;      
       END IF;   
 
		SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Current';    
        
        SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Past';
         
    	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN fbCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN fbCount ELSE 0 END)	AS pastCount
    	INTO 	v_currentCount, v_pastCount		
    	FROM 	tmp_result;
        
		SELECT 	p_columnName    																		AS metric
		,		ifnull(v_currentCount,0)																AS currentTotal
		, 		ifnull(v_pastCount,0)																	AS pastTotal
		,	    ifnull((v_currentCount - v_pastCount),0)  												AS totalDifference
		,		IFNULL((v_currentCount - v_pastCount) /(IF(v_currentCount=0,1,v_currentCount)) *100 ,0)	AS  Percentage;
     
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Facebook_Performances_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Facebook_Performances_trendchart`(	
	p_domainId 		INT,
	p_datetype 		INT,          
	p_starttime 	DATETIME,
	p_endtime		DATETIME,
	p_columnName   VARCHAR(200),  
	p_agentIds 	VARCHAR(250)
)
sp_return: BEGIN
  
  			DECLARE v_startDateTime			DATETIME; 		DECLARE v_endDateTime			DATETIME; 		DECLARE v_datetimeInterval		SMALLINT;		DECLARE v_startDateTimePast		DATETIME;
   			DECLARE v_endDateTimePast		DATETIME;  		DECLARE v_startTimestampPast	BIGINT; 		DECLARE v_endTimestampPast		BIGINT;      	DECLARE v_startTimestamp		BIGINT;
   			DECLARE v_endTimestamp			BIGINT;         DECLARE v_currentCount			INT; 			DECLARE v_pastCount				INT; 			DECLARE v_tot_cur_Facebook		INT;
   			DECLARE v_tot_past_Facebook		INT;	        DECLARE p_timezone				Text;			DECLARE v_tot_cur_chat			INT; 			DECLARE v_tot_past_chat			INT;
              
			DECLARE v_curDate				DATETIME DEFAULT NOW();	
              
  			set p_timezone = '+05:30';
              
              IF p_datetype = 1 THEN 	 
  				SET v_startDateTime = CAST(v_curDate AS DATE);  							
                SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
  				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 		
                SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);  
  			END IF;
              
  			IF p_datetype = 2 THEN 
  				SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 	
                SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
  				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY);		
                SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY); 
               END IF;
               
              IF p_datetype = 3 THEN 
  				SET v_startDateTime = p_starttime;
                  SET v_endDateTime 	= p_endtime; 
                  SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                  SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * (v_datetimeInterval+1) DAY);
                  SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
  			END IF;
  			IF p_datetype = 4 THEN 
  				SET v_startDateTime = p_starttime; 
  				SET v_endDateTime 	= p_endtime; 
  				SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
  				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * (v_datetimeInterval+1) DAY);
  				SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
  			END IF;
              
              
              
			DROP TEMPORARY TABLE IF EXISTS tmp_Facebookfresult;		CREATE TEMPORARY TABLE tmp_Facebookfresult(reportAge VARCHAR(20) ,startDateTime DATETIME ,endDateTime DATETIME, fbCount INT );  
  			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
              
              IF p_agentIds IS NOT NULL THEN
  				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT); CALL split(p_agentIds,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
  			ELSE
  				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                  CREATE TEMPORARY TABLE temp_agentIds
  				select  UserID as agentId from tb_User where domainId = p_domainId; 
  			END IF;
              
              
  			IF p_datetype IN (1,2) THEN 
  				DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
  					CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
  					WITH RECURSIVE CTE_TIMINGS AS 
  					(
  						SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
  						UNION ALL
  						SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
  						FROM 	CTE_TIMINGS
  						WHERE 	endDateTime < v_endDateTime
  					)
  					SELECT * FROM CTE_TIMINGS;	                
  			ELSEIF p_datetype IN (3,4) THEN 
  				DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
  					CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
  					WITH recursive CTE_TIMINGS AS 
  					(
  						SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND) AS endDateTime
  						UNION ALL
  						SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
  						FROM 	CTE_TIMINGS
  						WHERE 	startDateTime < v_endDateTime
  					)
  					SELECT * FROM CTE_TIMINGS;	
  			END IF;  
  
  			ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, 
  									ADD COLUMN endTimestamp		BIGINT;
  
  			UPDATE tmp_timings
  			SET	startTimestamp 	= unix_timestamp(convert_tz(startDateTime,p_timezone,'+00:00')) * 1000,
  				endTimestamp 	= unix_timestamp(convert_tz(endDateTime,p_timezone,'+00:00')) * 1000;
              
  			if p_datetype IN (1,2) then
  				SET 	v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
  					,	v_endTimestampPast		= unix_timestamp(convert_tz(v_endDateTimePast,p_timezone,'+00:00')) * 1000
  					,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000
  					, 	v_endTimestamp			= unix_timestamp(convert_tz(v_endDateTime,p_timezone,'+00:00')) * 1000 ;
  			End if;
  			if  p_datetype IN (3,4) then
  				SET 	v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
  					,	v_endTimestampPast		= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 
  					,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000 
  					, 	v_endTimestamp			= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTime,INTERVAL 1439 MINUTE),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 ; 
  			End if;
                      
  				DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory;	
  				CREATE TEMPORARY TABLE tmp_FacebookDurationHistory
  				SELECT 	FB.FacebookHistoryId
					
					,	FB.sessionStartTime
					,	(FB.Duration/1000) + FB.afterFacebookWorkTime		AS chatHandlingTime
					, 	FB.afterFacebookWorkTime							AS afterFacebookWorkTime
  				FROM  tb_FacebookHistory                	FB
                LEFT JOIN     temp_agentIds 				t_A     ON t_A.agentId 		= FB.agentId
  				WHERE 	FB.domainId 		= p_domainId
  				AND 	FB.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
				AND	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));  
                  
  				DROP TEMPORARY TABLE IF EXISTS tmp_FacebookHistory;	
  				CREATE TEMPORARY TABLE tmp_FacebookHistory
  				SELECT 	
  						WDH.FacebookHistoryId 
  					, 	WDH.sessionStartTime
                      ,	WDH.chatHandlingTime
                      ,	WDH.afterFacebookWorkTime
  				FROM 	tmp_FacebookDurationHistory WDH;  
                  
  				select count(Distinct FacebookHistoryId) into v_tot_cur_Facebook from tmp_FacebookHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;          
  				select count(Distinct FacebookHistoryId) into v_tot_past_Facebook from tmp_FacebookHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;  
                  
              
              if p_columnName = 'Average Handled Time' then
  				insert into tmp_Facebookfresult
  				SELECT 	'Current'		AS reportAge
  					,	t_T.startDateTime 
  					,	t_T.endDateTime
                      ,	IFNULL(SUM(chatHandlingTime),0) AS fbCount
  				FROM 	tmp_timings				t_T	
  				LEFT JOIN tmp_FacebookHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
  				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
  				GROUP BY t_T.startDateTime, t_T.endDateTime;
                  
  				insert into tmp_Facebookfresult
  				SELECT 	'Past'		AS reportAge
  					,	t_T.startDateTime 
  					,	t_T.endDateTime
  					,	IFNULL(SUM(chatHandlingTime),0) AS fbCount 
  				FROM 	tmp_timings				t_T	
  				LEFT JOIN tmp_FacebookHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
  				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
  				GROUP BY t_T.startDateTime, t_T.endDateTime;
              End if;
              
              if p_columnName = 'Total ACW Time' then
  				insert into tmp_Facebookfresult
  				SELECT 	'Current'		AS reportAge
  					,	t_T.startDateTime 
  					,	t_T.endDateTime
					,	IFNULL(SUM(afterFacebookWorkTime),0) AS fbCount
  				FROM 	tmp_timings				t_T	
  				LEFT JOIN tmp_FacebookHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
  				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
  				GROUP BY t_T.startDateTime, t_T.endDateTime;
                  
  				insert into tmp_Facebookfresult
  				SELECT 	'Past'		AS reportAge
  					,	t_T.startDateTime 
  					,	t_T.endDateTime
  					,	IFNULL(SUM(afterFacebookWorkTime),0) AS fbCount
  				FROM 	tmp_timings				t_T	
  				LEFT JOIN tmp_FacebookHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
  				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
  				GROUP BY t_T.startDateTime, t_T.endDateTime;
              End if;
              
                   SELECT * FROM tmp_Facebookfresult WHERE reportAge = 'Current';    
                   SELECT * FROM tmp_Facebookfresult WHERE reportAge = 'Past';
                   
  			SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN fbCount ELSE 0 END)/IF(v_tot_cur_Facebook=0,1,v_tot_cur_Facebook)	AS currentCount, 
  					SUM(CASE WHEN reportAge = 'Past' THEN fbCount ELSE 0 END)/IF(v_tot_past_Facebook=0,1,v_tot_past_Facebook)	AS pastCount
  					INTO 	v_currentCount, v_pastCount		
  			FROM 	tmp_Facebookfresult;
  					 
  					SELECT 	p_columnName    																	AS metric
  					,		ifnull(v_currentCount,0)															AS currentTotal
  					, 		ifnull(v_pastCount,0)																AS pastTotal
  					,	    ifnull((v_currentCount - v_pastCount),0)  											AS totalDifference
                      ,	    case when ifnull(v_pastCount,0)=0 then 100 
   										else ifnull((v_currentCount - v_pastCount) /(IF(v_pastCount=0,100,v_pastCount)) ,0)*100	
                                           End																	AS Percentage;
               
     
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Facebook_Profile_Report` */;
