DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Facebook_Profile_Report`(  
    		p_startTmpstmp 	BIGINT,
           p_endTmpstmp 	BIGINT,
           p_timeZone 		VARCHAR(200),
           p_domainId 		INT,
           p_agentIDs 		VARCHAR(250),
           p_dispositionIds	VARCHAR(250),
           p_Offset			INT,
           p_Limit			INT  
        )
BEGIN
         	DECLARE v_startTmpstmp 	BIGINT;
         	DECLARE v_endTmpstmp 	BIGINT;
         	DECLARE v_Total_count 	INT;
         	DECLARE v_offset		INT;    
                  
         	SET v_offset =  p_Limit * p_Offset; 
         
         	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +6 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
         	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
             
         	DROP TEMPORARY TABLE IF EXISTS     temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
         	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
       
         	CALL split(p_agentIDs,',');			INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable; 
         	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
      
                   
         	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
         	CREATE TEMPORARY TABLE temp_AvailableDisposition 
         	(	dispositionId 		INT,
         		DispositionStatus 	VARCHAR(100)
         	);
                   
         	INSERT INTO temp_AvailableDisposition 
         	SELECT 	did 			dispositionId
         		,	dispositionName	DispositionStatus
         	FROM 	disposition_status
         	WHERE 	domainId	= p_domainId;
         	 
         	
         	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
         	CREATE TEMPORARY TABLE temp_AllagentId
         	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId; 
             
     	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      	CREATE TEMPORARY TABLE temp_ChatHistory AS 	
          	SELECT 		
				FROM_UNIXTIME(SH.sessionStartTime/1000) as `dateTime`			
				,  SH.customerFacebookId   				AS customerNumber	
				,	U.UserName				        	AS agentName
				,	SH.createdAt			        	AS receivedOn
				,	SH.assignedOn 
				,   SH.IsBot									
				,	SH.repliedDate			        	AS repliedOn
				,	SH.discardedDate		        	AS discardedOn
				, 	SH.dispositionId
				,   SH.IsInBound
				,	SH.sessionStartTime			        AS chatStartTime
				,	SH.sessionEndTime				    AS chatEndTime
				,	SH.Duration			                AS duration
				
				,	abs((SH.Duration+(SH.afterFacebookWorkTime*1000)))	         AS activeChatTime
				,	SH.afterFacebookWorkTime					             AS ACWtime 
				
				,	cfb.satisfactionRate					                     AS CSATscore
				,	SH.dialDuration											AS dialDuration
                ,	SH.Summary
                ,	SH.dispositionSubject
         	FROM 	tb_FacebookHistory 				SH    
         	LEFT JOIN  	temp_AllagentId			     U		ON U.UserID				= SH.AgentId
  		
         	
  		LEFT JOIN tb_customerFeedback			cfb		ON	cfb.historyId 		= SH.FacebookHistoryId and cfb.domainId = SH.domainId
         	WHERE 	SH.domainId 			= p_domainId 		
         	AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
            AND	SH.dispositionId is not null
          AND		(SH.AgentId in (select agentId from temp_agentIDs) or ifnull(p_agentIDs,'')='')
          AND		(SH.dispositionId in (select dispositionId from temp_dispositionIds) or ifnull(p_dispositionIds,'')='');
         	
         	
         	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
   
			SELECT * from temp_AllagentId;
     		SELECT * from temp_AvailableDisposition;
     	
                  
         	SELECT COUNT(1)  totalCount
         	FROM 	temp_ChatHistory;    
          
          IF ((p_Limit IS NOT NULL)AND(p_Offset IS NOT NULL)) THEN
          
     		DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_1; 	
         	CREATE TEMPORARY TABLE temp_ChatHistory_1 AS 	    
         	SELECT 	*
         	FROM 	temp_ChatHistory
         	ORDER BY `dateTime` DESC 
         	LIMIT v_offset, p_Limit;   
		
        ELSE
				
                DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_1; 	
         	CREATE TEMPORARY TABLE temp_ChatHistory_1 AS 	    
         	SELECT 	*
         	FROM 	temp_ChatHistory
         	ORDER BY `dateTime` DESC ;   
                
        END IF;
          
          SELECT 	SH.`dateTime`
     		 	,	CASE WHEN agentName is NOT null then agentName else  'bot'  end as agentName 
     		
          		,	CASE WHEN facebook IS NOT NULL THEN CONCAT(c_c.firstName, ' ',c_c.lastName)	ELSE 'New Customer' END as customerName   
                 
                 ,	'InBound' as direction 
         		,	chatStartTime
         		,	chatEndTime
				,	duration        
         		,	activeChattime
         		,	SH.dialDuration	as responseTime
         		,	t_A.DispositionStatus			as disposition				
         		,	SH.ACWtime				        as ACWtime
         		,	SH.CSATscore			        as customerSatisfactionScore
                ,	SH.Summary as summary
                ,	SH.dispositionSubject as subject
         	FROM 	temp_ChatHistory_1			SH
         	LEFT JOIN 	temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId
          	LEFT JOIN customer_contact				c_c	ON 	c_c.facebook			= SH.customerNumber;
     											
              
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Facebook_profile_report_5` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Facebook_profile_report_5`(
   p_startTmpstmp 	BIGINT,
   p_endTmpstmp 	BIGINT,
   p_timeZone 		VARCHAR(200),
   p_domainId 		INT,

   p_agentIDs 		VARCHAR(250),
   p_dispositionIds	VARCHAR(250),
   p_Offset			INT,
   p_Limit			INT  
   )
BEGIN
 	DECLARE v_startTmpstmp 	BIGINT;
 	DECLARE v_endTmpstmp 	BIGINT;
 	DECLARE v_Total_count 	INT;
 	DECLARE v_offset		INT;    
          
 	SET v_offset =  p_Limit * p_Offset; 
 
 	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
 	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
     
     
 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
 	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
         
 	CALL split(p_agentIDs,',');			INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
 	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
     
 	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
 	CREATE TEMPORARY TABLE temp_AllagentId
 	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3); 
           
 	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
 	CREATE TEMPORARY TABLE temp_AvailableDisposition 
 	(	dispositionId 		INT,
 		DispositionStatus 	VARCHAR(100)
 	);
           
 	INSERT INTO temp_AvailableDisposition 
 	SELECT 	did 			dispositionId
 		,	dispositionName	DispositionStatus
 	FROM 	disposition_status
 	WHERE 	domainId	= p_domainId;
 	    
     
 	DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     CREATE TEMPORARY TABLE temp_FacebookHistory AS 	    	
 	SELECT 		FROM_UNIXTIME(FH.sessionStartTime/1000) as `dateTime`			
 			 ,	FH.customerFacebookId   as customerNumber		
 			 ,	U.UserName				as agentName
 			 ,	FH.createdAt			as receivedOn
 			 ,	FH.assignedOn          
 			 ,	FH.repliedDate			as repliedOn
 			 ,	FH.transferredDate		as transferredOn 
 			 ,	FH.discardedDate		as discardedOn
 			 , 	FH.dispositionId
			 ,	FH.sessionStartTime		as FacebookStartTime
             ,	CASE WHEN FH.sessionEndTime>0 THEN FH.sessionEndTime ELSE NULL END		  as FacebookEndTime
             ,	FH.Duration			as duration
 			 ,	abs((FH.sessionEndTime-FH.sessionStartTime)/1000)	as activeFacebookTime            
             ,	FH.afterFacebookWorkTime		
             ,	FH.IsInBound			
             ,	FH.SentimentalScore									as csatScore
 	FROM 	tb_FacebookHistory 			FH
 	LEFT JOIN tb_User					U		ON U.UserID				= FH.AgentId
 	LEFT JOIN temp_agentIDs 			t_A 	ON U.UserID  			= t_A.agentId       
 	LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= FH.dispositionId    
 	WHERE 	FH.domainId 			= p_domainId 		
 	AND 	FH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 

 	AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
 	AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     
 	 SELECT * from temp_FacebookHistory_1;
 	 SELECT * from temp_AllagentId;
     SELECT * from temp_AvailableDisposition;
          
 	 SELECT COUNT(1)  totalCount
 	 FROM 	temp_FacebookHistory;    
     
 	 DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_1; 	
 	 CREATE TEMPORARY TABLE temp_FacebookHistory_1 AS 	    
 	 SELECT 	*
 	 FROM 	temp_FacebookHistory	
 	 ORDER BY `dateTime` DESC 
 	 LIMIT v_offset, p_Limit;    
     
 	 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	 SELECT 	
			FH.`dateTime`
		,	FH.agentName
 		,	CASE WHEN trim(CONCAT(c_c.firstName, ' ',c_c.lastName)) <> ''  THEN CONCAT(c_c.firstName, ' ',c_c.lastName)	ELSE 'New Customer' END	as customerName
 	 	,	CASE WHEN coid IS NOT NULL THEN trim(CONCAT(c_c.firstName, ' ',c_c.lastName))	ELSE 'New Customer' END as customerName   	
		,	CASE WHEN FH.IsInBound  = 0 THEN 'InBound' ELSE 'OutBound' END as direction 
 		,	FacebookStartTime				      as chatStartTime
 		,	FacebookEndTime					      as chatEndTime
 		,	duration						      as Duration
 		,	activeFacebookTime 				      as activeChattime
		,	FH.repliedOn - FH.receivedOn		  as responsetime
		,	TIMEDIFF(FH.repliedOn, FH.receivedOn) as responsetime
 		,	t_A.DispositionStatus			      as dispositionstatus
 		,	FH.afterFacebookWorkTime		          as ACWtime	
 		,	FH.csatScore						  as customerSatisfactionScore		
 	 FROM 	temp_FacebookHistory_1			FH
 	 LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= FH.dispositionId
 	 LEFT JOIN customer_contact			c_c	ON 	c_c.phoneNumber		=FH.customerFacebookId
 											AND	c_c.domainId		= p_domainId;
 	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Facebook_profile_report_6` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Facebook_profile_report_6`(
   p_startTmpstmp     BIGINT,
   p_endTmpstmp       BIGINT,
   p_timeZone         VARCHAR(200),
   p_domainId         INT,
   
   p_agentIDs         VARCHAR(250),
   p_dispositionIds   VARCHAR(250),
   p_Offset           INT,
   p_Limit            INT  
   )
BEGIN
    DECLARE v_startTmpstmp     BIGINT;
    DECLARE v_endTmpstmp       BIGINT;
    DECLARE v_Total_count      INT;
    DECLARE v_offset           INT;    
          
    SET v_offset =  p_Limit * p_Offset; 
 
    IF IFNULL(p_startTmpstmp, 0) = 0 THEN SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY)) * 1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 
    IF IFNULL(p_endTmpstmp , 0) = 0 THEN SET v_endTmpstmp   = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
     
    
    DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
    DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;  CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
         
    
    CALL split(p_agentIDs, ',');        INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
    CALL split(p_dispositionIds, ',');    INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
     
    DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;   
    CREATE TEMPORARY TABLE temp_AllagentId
    SELECT UserID, UserName FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3); 
           
    DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
    CREATE TEMPORARY TABLE temp_AvailableDisposition 
    (   dispositionId       INT,
        DispositionStatus  VARCHAR(100)
    );
           
    INSERT INTO temp_AvailableDisposition 
    SELECT  did             dispositionId
        ,   dispositionName DispositionStatus
    FROM    disposition_status
    WHERE   domainId = p_domainId;
    
         
     
    DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    CREATE TEMPORARY TABLE temp_FacebookHistory AS           
    SELECT      FROM_UNIXTIME(FH.sessionStartTime / 1000) as `dateTime`          
             ,  FH.customerFacebookId   as customerNumber       
             ,  U.UserName                as agentName
    
             ,  FH.createdAt             as receivedOn
             ,  FH.assignedOn            
             ,  FH.repliedDate           as repliedOn
             ,  FH.transferredDate       as transferredOn 
             ,  FH.discardedDate         as discardedOn
             ,  FH.dispositionId
             ,  FH.sessionStartTime      as FacebookStartTime
             ,  CASE WHEN FH.sessionEndTime > 0 THEN FH.sessionEndTime ELSE NULL END      as FacebookEndTime
             ,  FH.Duration              as duration
             ,  ABS((FH.sessionEndTime - FH.sessionStartTime) / 1000)    as activeFacebookTime            
             ,  FH.afterFacebookWorkTime       
             ,  FH.IsInBound            
             ,  Null                                    as queueWaitingTime
             ,  Null                                    as csatScore
    FROM    tb_FacebookHistory           FH
    
    
    LEFT JOIN tb_User                     U       ON U.UserID                = FH.AgentId
    
    LEFT JOIN temp_agentIDs               t_A     ON U.UserID             = t_A.agentId       
    LEFT JOIN temp_dispositionIds         t_D     ON t_D.dispositionId    = FH.dispositionId    
    WHERE   FH.domainId             = p_domainId        
    AND     FH.sessionStartTime    BETWEEN v_startTmpstmp AND v_endTmpstmp 
    
    AND     (IFNULL(p_agentIDs, '')  = '' OR (IFNULL(p_agentIDs, '') <> ''                AND t_A.agentId IS NOT NULL))
    AND     (IFNULL(p_dispositionIds, '')  = '' OR (IFNULL(p_dispositionIds, '') <> ''  AND t_D.dispositionId IS NOT NULL));
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     

     SELECT * from temp_AllagentId;
     SELECT * from temp_AvailableDisposition;
          
     SELECT COUNT(1)  totalCount
     FROM    temp_FacebookHistory;    
     
     DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_1;   
     CREATE TEMPORARY TABLE temp_FacebookHistory_1 AS      
     SELECT      *
     FROM    temp_FacebookHistory    
     ORDER BY `dateTime` DESC 
     LIMIT v_offset, p_Limit;    
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT      
            FH.`dateTime`
        ,   FH.agentName
     
        ,   CASE WHEN TRIM(CONCAT(c_c.firstName, ' ',c_c.lastName)) <> ''  THEN CONCAT(c_c.firstName, ' ',c_c.lastName)    ELSE 'New Customer' END  as customerName
        ,   CASE WHEN coid IS NOT NULL THEN TRIM(CONCAT(c_c.firstName, ' ',c_c.lastName))  ELSE 'New Customer' END as customerName    
        ,   CASE WHEN FH.IsInBound  = 0 THEN 'InBound' ELSE 'OutBound' END as direction 
        ,   FacebookStartTime           as chatStartTime
        ,   FacebookEndTime             as chatEndTime
        ,   duration        
        ,   activeFacebookTime as activeChattime
        ,   FH.repliedOn - FH.receivedOn    as responsetime
        ,   TIMEDIFF(FH.repliedOn, FH.receivedOn) as responsetime
        ,   t_A.DispositionStatus            as disposition
    
        ,   FH.afterFacbookWorkTime        as ACWtime    
        ,   FH.csatScore as customerSatisfactionScore      
     FROM   temp_FacebookHistory_1          FH
     LEFT JOIN temp_AvailableDisposition    t_A ON t_A.dispositionId   = FH.dispositionId
     LEFT JOIN customer_contact             c_c ON c_c.phoneNumber       LIKE  CONCAT('%', FH.customerNumber, '%')
                                            AND c_c.domainId       = p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
END ;;
