DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Facebook_ServiceLevel_trendchart`(
	p_domainId 			INT,
	p_datetype 			INT,            
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
	p_columnName    	VARCHAR(200),    
	p_agentId 			TEXT
   )
BEGIN
   
   
  	DECLARE v_startDateTime			DATETIME;
  	DECLARE v_endDateTime			DATETIME;     
  	DECLARE v_datetimeInterval		SMALLINT;    
  	DECLARE v_startDateTimePast		DATETIME;
  	DECLARE v_endDateTimePast		DATETIME;
       
	DECLARE v_startTimestampPast	BIGINT;
	DECLARE v_endTimestampPast		BIGINT;      
	DECLARE v_startTimestamp		BIGINT;
	DECLARE v_endTimestamp			BIGINT;
	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
      
  	DROP TEMPORARY TABLE IF EXISTS tmp_result;
  	CREATE TEMPORARY TABLE tmp_result(
  		reportAge			VARCHAR(20)
  		,startDateTime		DATETIME
  		,endDateTime		DATETIME
  		,callCount			INT
  	);    
   
   	IF p_datetype = 1 
       THEN 	
   		SET v_startDateTime = CAST(v_curDate AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
   	END IF;
   	IF p_datetype = 2 
       THEN 
   		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
  		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
   	END IF;
   	IF p_datetype = 3 
           THEN 
                 SET v_startDateTime = p_startDateTime;
                 SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                 
     			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                 
         		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                 SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       	IF p_datetype = 4 
           THEN 
       		SET v_startDateTime = p_startDateTime; 
               SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND); 
               
               SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       
       IF p_agentId IS NOT NULL 
       THEN
   		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
   		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
       ELSE
   		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
          CREATE TEMPORARY TABLE temp_agentIds
 		 select  UserID AS agentId,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
		END IF;
        
       DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
       CREATE TEMPORARY TABLE tmp_Disposition
       SELECT did, dispositionName
       FROM 	disposition_status
       WHERE	domainId		= p_domainId;
       
       IF p_datetype IN (1,2)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
			WITH RECURSIVE CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE), INTERVAl 59 SECOND) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	endDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
   	ELSEIF p_datetype IN (3,4)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   		WITH recursive CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	startDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
       END IF;  
       
       ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
            
       UPDATE tmp_timings
       SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
   		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
           
   	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
  	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
  	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
  	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
     
    DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory;	
  	CREATE TEMPORARY TABLE tmp_FacebookDurationHistory
  	SELECT 
        I.FacebookHistoryId,
        I.sessionStartTime,
        I.Duration,
        I.Istransferred,
		I.IsMissed,
		I.dialDuration,
		I.IsInBound
	FROM tb_FacebookHistory   I
    LEFT JOIN     temp_agentIds		t_A     ON t_A.agentId 		= I.AgentId      
  	WHERE 	I.domainId 		= p_domainId
  	AND 	I.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
  	AND 	I.IsInBound		= 1
    AND 	I.IsBot			= 0
    AND 	I.AgentId IS NOT NULL;
    
  	DROP TEMPORARY TABLE IF EXISTS tmp_FacebookHistory;	
   	CREATE TEMPORARY TABLE tmp_FacebookHistory
      SELECT 	DISTINCT 
   			CDH.FacebookHistoryId 
   		, 	CDH.sessionStartTime
   	FROM 	tmp_FacebookDurationHistory CDH;  
       
       ALTER TABLE tmp_FacebookHistory ADD IsInbound		TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD IsMissed 		TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD SLA1			TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD SLA2			TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD SLA3			TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD SLA4			TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD SLA5			TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD SLA6			TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD IsAchieved		TINYINT default 0;
       ALTER TABLE tmp_FacebookHistory ADD IsBreached		TINYINT default 0;
       
       CREATE INDEX ix_tmp_FacebookHistory ON tmp_FacebookHistory (FacebookHistoryId);
       CREATE INDEX ix_tmp_FacebookDurationHistory ON tmp_FacebookDurationHistory (FacebookHistoryId);
   
       UPDATE 	tmp_FacebookHistory				CH
       JOIN 	tmp_FacebookDurationHistory		CDH	ON CH.FacebookHistoryId	= CDH.FacebookHistoryId 
       SET 	CH.IsInbound		= CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN 1 ELSE 0 END
   		,	CH.IsMissed			= CASE WHEN CDH.IsMissed = 1 THEN 1 ELSE 0 END
        ,	CH.SLA1				= CASE WHEN dialDuration BETWEEN 0 AND  5 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END
		,	CH.SLA2				= CASE WHEN dialDuration BETWEEN 6  AND 10 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END
		,	CH.SLA3				= CASE WHEN dialDuration BETWEEN 11 AND 15 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END      
		,	CH.SLA4				= CASE WHEN dialDuration BETWEEN 16 AND 20 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END        
		,	CH.SLA5				= CASE WHEN dialDuration BETWEEN 21 AND 25 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END        
		,	CH.SLA6				= CASE WHEN dialDuration BETWEEN 26 AND 30 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END;
     
     
     
     IF p_columnName = 'Total SLA'
       THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'				AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	SUM(CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
		INSERT INTO tmp_result
   		SELECT 	'Past'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	SUM(CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
  ELSEIF p_columnName = 'Missed'
       THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(IsMissed),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
		INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(IsMissed),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;   
   ELSEIF p_columnName = 'SLA1'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA1),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA1),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;  
	ELSEIF p_columnName = 'SLA2'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA2),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA2),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime; 
		ELSEIF p_columnName = 'SLA3'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA3),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA3),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime; 
        ELSEIF p_columnName = 'SLA4'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA4),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA4),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime; 
        ELSEIF p_columnName = 'SLA5'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA5),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA5),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime; 
        ELSEIF p_columnName = 'SLA6'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA6),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL(SUM(SLA6),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime; 
        ELSEIF p_columnName = 'SLA Achieved'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL((SUM(SLA1 + SLA6 + SLA2 + SLA3 + SLA4 + SLA5 + SLA6)/SUM(IsInbound)) * 100,0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL((SUM(SLA1 + SLA6 + SLA2 + SLA3 + SLA4 + SLA5 + SLA6)/SUM(IsInbound)) * 100 ,0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
        ELSEIF p_columnName = 'SLA Breached'
  	THEN
  		INSERT INTO tmp_result
   		SELECT 	'Current'					AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL((100 - (SUM(SLA1 + SLA6 + SLA2 + SLA3 + SLA4 + SLA5 + SLA6)/SUM(IsInbound)) * 100),0)	AS callCount
   		FROM 	tmp_timings			t_T	
   		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          INSERT INTO tmp_result
   		SELECT 	'Past'						AS reportAge
   			,	t_T.startDateTime 
   			,	t_T.endDateTime
   			,	IFNULL((100 - (SUM(SLA1 + SLA6 + SLA2 + SLA3 + SLA4 + SLA5 + SLA6)/SUM(IsInbound)) * 100),0)	AS callCount     
   		FROM 	tmp_timings		t_T	
   		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
   		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
   		GROUP BY t_T.startDateTime, t_T.endDateTime;
       END IF;   
 
		SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Current';    
        
        SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Past';
         
    	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
    	INTO 	v_currentCount, v_pastCount		
    	FROM 	tmp_result;
        
		SELECT 	p_columnName    																		AS metric
		,		ifnull(v_currentCount,0)																AS currentTotal
		, 		ifnull(v_pastCount,0)																	AS pastTotal
		,	    ifnull((v_currentCount - v_pastCount),0)  												AS totalDifference
		,		IFNULL((v_currentCount - v_pastCount) /(IF(v_currentCount=0,1,v_currentCount)) *100 ,0)	AS  Percentage;
     
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_getCustomerSatisfactionChannelStatus` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_getCustomerSatisfactionChannelStatus`(
 p_domainId	INT
 )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 	SELECT 	 'CSAT Score'  as caption
 		,	isEnable
         ,	isVoice
         ,	isWebWidget
         ,	isSms
         ,	isEmail
         ,	isFacebook
         ,	isInstagram
         ,	isVideo
         ,	isWhatsApp
 	FROM  	tb_ccaas_customerSatisfactionRatingDesign
     WHERE 	domainId = p_domainId;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_GetCustomerSatisfactionForChannel` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_GetCustomerSatisfactionForChannel`(
                 p_domainId					INT
                 ,p_channelTypeId			INT 
                 ,p_HistoryId				BIGINT
                 ,p_videoMeetId				varchar(150)
               
               
              )
Logic: BEGIN
            	DECLARE v_customerName		VARCHAR(200);    
            	DECLARE v_customerContact	VARCHAR(200);    
            	DECLARE v_domainContact		VARCHAR(200);
            	DECLARE v_channelValue		VARCHAR(20);
        		DECLARE v_createdAt 		DATETIME;
        		DECLARE v_dontDisturbType 	INT;
        		DECLARE v_dontDistrubTime 	INT;
        		DECLARE v_timediff 			INT;
				DECLARE v_AgentId			INT;
				DECLARE v_coid				INT;
				DECLARE v_customerFeedbackId	INT;
                   
                
                     
           	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
             
         		DROP TEMPORARY TABLE IF EXISTS tmp_CallConfiguration;
         		CREATE TEMPORARY TABLE tmp_CallConfiguration
         		SELECT 	pid
         			,	your_number
         		FROM 	did_purchase P	
         		WHERE  	P.isSmsOut 	= 1 
         		AND 	P.isSmsIn 	= 1 
         		AND 	P.domainId	= p_domainId;
                 
       		DROP TEMPORARY TABLE IF EXISTS tmp_whatsappConfiguration;
         		CREATE TEMPORARY TABLE tmp_whatsappConfiguration
         		SELECT 	WhatsappConfigurationId as pid
         			,	whatsappNumber your_number
         		FROM 	tb_WhatsappConfiguration P	
         		WHERE  	P.domainId	= p_domainId ;
         
               IF EXISTS (	SELECT 	1 
           				FROM 	tb_customerFeedback 
                           WHERE 	historyId 		= p_HistoryId
                           AND		channelTypeId	= p_channelTypeId
                           AND		domainId		= p_domainId
                           AND		satisfactionRate IS NOT NULL)
               THEN		
           		SELECT 	'0'							AS errCode
          			, 	'Feedback already given' 	AS errMsg
                      ,	thanksNote
                  FROM 	tb_ccaas_customerSatisfactionRatingDesign
                  WHERE 	domainId = p_domainId;
                   LEAVE Logic;
               END IF;
      
           	IF p_channelTypeId = 2003004 
            	THEN
           		SELECT 	H.customerNumber
           			,	H.calledNumber
           			,	P.pid
           			,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	MAX(SDH.AgentId)
 					,	C.coid
           		INTO 	v_customerContact	
           			,  	v_domainContact	
           			,	v_channelValue
           			,	v_customerName
  					,	v_AgentId
 					,	v_coid
            		FROM 	tb_SMSHistory 				H
  				LEFT JOIN tb_SMSDurationHistory		SDH ON H.SMSHistoryId	 = SDH.SMSHistoryId
            		LEFT JOIN tmp_CallConfiguration	P	ON 	P.your_number		= H.calledNumber												
            		LEFT JOIN customer_contact			C	ON 	C.primaryPhoneNumber= H.customerNumber         
            											AND	C.domainId			= H.domainId
            		WHERE 	H.SMSHistoryId 	= p_HistoryId
            		AND 	H.domainId		= p_domainId
                 GROUP BY H.customerNumber,	H.calledNumber,	P.pid, C.firstName,C.lastName,	C.coid;
                       
           		IF v_customerName IS NULL
           		THEN
           			SELECT 	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),'')),	C.coid
           			INTO 	v_customerName,	v_coid
           			FROM 	customer_contact C
           			WHERE 	phoneNumber LIKE CONCAT('%',v_customerContact,'%')
           			ORDER BY coid DESC LIMIT 1;
           		END IF; 
           	ELSEIF p_channelTypeId = 2003003 
           	THEN
           		SELECT 	H.FromEmail
           			,	H.ToEmail
           			,	CON.EmailConfigId
           			,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	MAX(EDH.AgentId)
  					,	C.coid
           		INTO 	v_customerContact	
           			,  	v_domainContact		
           			,	v_channelValue
           			,	v_customerName	
  					,	v_AgentId
                      ,	v_coid
              		FROM 	tb_EmailHistory		H
                     LEFT JOIN tb_EmailDurationHistory		EDH ON H.EmailHistoryId	 = EDH.EmailHistoryId
              		JOIN 	email_config		CON	ON 	CON.emailAddress 	= H.ToEmail
              										AND	CON.domainId		= H.domainId
              		LEFT JOIN customer_contact	C	ON 	C.primaryEmail 		= H.FromEmail
              										AND C.domainId			= H.domainId
              		WHERE 	H.EmailHistoryId 	= p_HistoryId
              		AND 	H.domainId		= p_domainId
                     group by H.FromEmail,H.ToEmail, CON.EmailConfigId, C.firstName,C.lastName,	C.coid
                     LIMIT 1;
                        
            		IF v_customerName IS NULL
            		THEN
            			SELECT CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),'')),	C.coid
            			INTO 	v_customerName,	v_coid
            			FROM 	customer_contact C
            			WHERE 	C.domainId	= p_domainId
            			AND 	C.email 	LIKE CONCAT('%',v_customerContact,'%')
            			ORDER BY C.coid DESC LIMIT 1;
            		END IF; 
                 
         	ELSEIF p_channelTypeId = 2003005 THEN 
                 SELECT 	H.customerNumber
           			,	H.calledNumber
           			,	P.WhatsappConfigurationId as pid
           			,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	MAX(WDH.AgentId)
  					,	C.coid
           		INTO 	v_customerContact	
           			,  	v_domainContact	
           			,	v_channelValue
           			,	v_customerName	
  					,	v_AgentId
  					,	v_coid
            		FROM 	tb_WhatsappHistory 				H
                 LEFT JOIN tb_WhatsappDurationHistory		WDH ON H.WhatsappHistoryId	 = WDH.WhatsappHistoryId
            		LEFT JOIN tb_WhatsappConfiguration		P	ON 	P.whatsappNumber		= H.calledNumber												
            		LEFT JOIN customer_contact				C	ON 	C.primaryPhoneNumber	= H.customerNumber         
         													AND	C.domainId				= H.domainId
            		WHERE 	H.WhatsappHistoryId 	= p_HistoryId
            		AND 	H.domainId				= p_domainId
                 group by H.customerNumber,H.calledNumber, P.WhatsappConfigurationId, C.firstName,C.lastName,	C.coid;
                       
           		IF v_customerName IS NULL
           		THEN
           			SELECT 	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),'')),	C.coid
           			INTO 	v_customerName,	v_coid
           			FROM 	customer_contact C
           			WHERE 	phoneNumber LIKE CONCAT('%',v_customerContact,'%')
           			ORDER BY coid DESC LIMIT 1;
           		END IF;
         	ELSEIF p_channelTypeId = 2003002 THEN 
         		
                 SELECT 	H.CustomerId
           			,	H.chatFlowSourceId
           			,	H.chatWidgetId as pid
           			,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	MAX(CDH.AgentId)
  					,	C.coid
           		INTO 	v_customerContact	
           			,  	v_domainContact	
           			,	v_channelValue
           			,	v_customerName	
  					,	v_AgentId
  					,	v_coid
            		FROM 	tb_ChatHistory 							H
					LEFT JOIN tb_ChatDurationHistory				CDH ON H.ChatHistoryId	 = CDH.ChatHistoryId
            		LEFT JOIN chat_configuration_primary_form		P	ON 	P.chatFlowId	= H.chatFlowSourceId and H.domainId = P.domainId and P.aid = H.chatWidgetId													
            		LEFT JOIN customer_contact						C	ON 	C.coid			= H.CustomerId         
																		AND	C.domainId		= H.domainId
            		WHERE 	H.ChatHistoryId 		= p_HistoryId
            		AND 	H.domainId				= p_domainId
                 group by H.CustomerId,H.chatFlowSourceId, H.chatWidgetId, C.firstName,C.lastName,	C.coid;
         	ELSEIF p_channelTypeId = 2003006 THEN 
         		
                  SELECT 	H.customerFacebookId
         				,	H.agentFacebookId
         				,	P.FacebookConfigurationId as pid
         				,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	H.AgentId
                      ,	C.coid
         		INTO 		v_customerContact	
         				,  	v_domainContact	
         				,	v_channelValue
         				,	v_customerName	
  					,	v_AgentId
                      ,	v_coid
            		FROM 	tb_FacebookHistory 				H
            		LEFT JOIN tb_FacebookConfiguration		P	ON 	P.FacebookPageId		= H.agentFacebookId and H.domainId = P.domainId										
            		LEFT JOIN customer_contact				C	ON 	C.facebook				= H.customerFacebookId         
         													AND	C.domainId				= H.domainId
            		WHERE 	H.FacebookHistoryId 	= p_HistoryId
            		AND 	H.domainId				= p_domainId;
        	ELSEIF p_channelTypeId = 2003001 
            	THEN
           		SELECT 	H.customerNumber
           			,	H.calledNumber
           			,	P.contactCenterNumber
           			,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	MAX(CH.AgentId)
                      ,	C.coid
           		INTO 	v_customerContact	
           			,  	v_domainContact	
           			,	v_channelValue
           			,	v_customerName	
  					,	v_AgentId
  					,	v_coid
        		FROM 	tb_CallHistory 				H
             LEFT join tb_CallDurationHistory	CH	ON CH.CallHistoryId			= H.CallHistoryId
        		LEFT JOIN call_configuration		P	ON 	P.contactCenterNumber	= H.calledNumber												
        		LEFT JOIN customer_contact			C	ON 	C.primaryPhoneNumber	= H.customerNumber         
              
        												AND	C.domainId				= H.domainId
        		WHERE 	H.CallHistoryId	= p_HistoryId
        		AND 	H.domainId		= p_domainId
             GROUP BY H.customerNumber,	H.calledNumber,	P.callFlowId, C.firstName, C.lastName,	C.coid;
        
        ELSEIF p_channelTypeId = 2003007 
            	THEN
           		 SELECT 	H.customerInstagramId
         				,	H.agentInstagramId
         				,	P.InstagramConfigurationId as pid
         				,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
  					,	H.AgentId
                      ,	C.coid
         		INTO 		v_customerContact	
         				,  	v_domainContact	
         				,	v_channelValue
         				,	v_customerName	
  					,	v_AgentId
                      ,	v_coid
            		FROM 	tb_InstagramHistory 			H
            		LEFT JOIN tb_InstagramConfiguration		P	ON 	P.InstagramPageId		= H.agentInstagramId and H.domainId = P.domainId										
            		LEFT JOIN customer_contact				C	ON 	C.Instagram				= H.customerInstagramId         
         													AND	C.domainId				= H.domainId
            		WHERE 	H.InstagramHistoryId 	= p_HistoryId
            		AND 	H.domainId				= p_domainId;
                 
 		 ELSEIF p_channelTypeId = 2003008 
            	THEN
           		 SELECT 	H.customerNumber
         				,	H.calledNumber
         				,	null
         				,	CONCAT(IFNULL(CONCAT(C.firstName,' '),''),IFNULL(CONCAT(C.lastName,' '),''))
 						,	MAX(CH.AgentId)
 						,	C.coid
         		INTO 		v_customerContact	
         				,  	v_domainContact	
         				,	v_channelValue
         				,	v_customerName	
 						,	v_AgentId
 						,	v_coid
            		FROM 	tb_VideoHistory 				H
					LEFT join tb_VideoDurationHistory		CH	ON CH.VideoHistoryId		= H.VideoHistoryId
            		LEFT JOIN customer_contact				C	ON 	C.primaryPhoneNumber	= H.customerNumber         
         													AND	C.domainId				= H.domainId 
                                                             AND H.CustomerId			= C.coid
            		
                    WHERE 	H.meetingId 			= p_videoMeetId
            		AND 	H.domainId				= p_domainId
                 GROUP BY H.customerNumber,H.calledNumber, C.firstName, C.lastName,	C.coid;
        
           	END IF;  
            
           
        		select dontDisturbType, dontDistrubTime into v_dontDisturbType,v_dontDistrubTime 
        		from tb_ccaas_customerSatisfactionRatingDesign where domainId = p_domainId limit 1;
        
        		set v_dontDistrubTime = if(v_dontDisturbType = 2,v_dontDistrubTime*1440,v_dontDistrubTime*60);
                
                delete from tb_csr_custom_entry where TIMESTAMPDIFF(MINUTE, createdAt, now()) > v_dontDistrubTime and domainId = p_domainId;
   
			IF EXISTS(SELECT 1 from tb_csr_custom_entry where coid = v_coid) then
				if exists(select 1 from tb_csr_custom_entry where HistoryId = p_HistoryId) then
					
                    select customerFeedbackId into v_customerFeedbackId from tb_customerFeedback
                    where historyId = p_HistoryId and domainId = p_domainId;
                
					select 	v_customerFeedbackId as customerFeedbackId
							,	v_customerName		AS customerName
							,	v_customerContact 	AS customerContact
							,	v_domainContact 	AS domainContact
							, 	p_HistoryId 		AS HistoryId
							,	CSR.domainId, CSR.caption, CSR.isEnable, CSR.ratingDesignType, CSR.labelRatingType, CSR.followUpQuestion, CSR.thanksNote, CSR.dontDisturbType, CSR.dontDistrubTime
							, 	CSR.additionalQuestionType,	CSR.additionalQuestions
							,	CASE 	WHEN p_channelTypeId = 2003004  			THEN IFNULL(t_CC.your_number, v_domainContact)
										WHEN p_channelTypeId = 2003003  		THEN IFNULL(EC.emailAddress, v_domainContact)
								END 				AS sendFrom 						
							,	CSR.smsMessage
							,	CSR.emailSubject
							,	CSR.emailMessage
							,	1 								AS errCode
							, 	'Please provide your feedback' 	AS errMsg
							,CSR.minimumDurationType, CSR.minimumDuration, v_AgentId as AgentId
							FROM 	tb_ccaas_customerSatisfactionRatingDesign 	CSR
							LEFT JOIN email_config								EC		ON EC.EmailConfigId = CSR.emailIdSend
							LEFT JOIN tmp_CallConfiguration						t_CC	ON t_CC.pid			= CSR.smsNumberSend
							LEFT JOIN tb_FacebookConfiguration					t_FC	ON t_FC.FacebookPageId	= CSR.facebookChatFlows
							LEFT JOIN tb_InstagramConfiguration					t_IC	ON t_IC.InstagramPageId	= CSR.instagramChatFlows
							WHERE 	CSR.domainId	= p_domainId
							AND (	(p_channelTypeId = 2003001  		AND CSR.isVoice 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.callFlows)	 		> 0)
							OR	(p_channelTypeId = 2003002  		AND CSR.isWebWidget = 1 	AND FIND_IN_SET(v_channelValue,CSR.Widgets) 			> 0)
							OR	(p_channelTypeId = 2003003  		AND CSR.isEmail 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.emails) 				> 0)
							OR	(p_channelTypeId = 2003004  			AND CSR.isSms 		= 1 	AND FIND_IN_SET(v_channelValue,CSR.smsNumbers) 			> 0)
							OR	(p_channelTypeId = 2003005  	AND CSR.isWhatsApp 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.whatsAppChatFlows) 	> 0)
							OR	(p_channelTypeId = 2003006  	AND CSR.isFacebook 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.facebookChatFlows) 	> 0)
							OR	(p_channelTypeId = 2003007  	AND CSR.isInstagram = 1 	AND FIND_IN_SET(v_channelValue,CSR.instagramChatFlows) 	> 0)
							OR	(p_channelTypeId = 2003008  	AND CSR.isVideo = 1 ));
                            leave Logic;
					else
        				select createdAt into v_createdAt from tb_csr_custom_entry where coid = v_coid limit 1; 
        				set v_timediff = TIMESTAMPDIFF(MINUTE, v_createdAt, now());
        
        				if v_timediff < v_dontDistrubTime then
        					select -1 as errcode, 'Customer within DND range - try again later' as errmsg;
        					leave Logic;
						
				ELSE
        					delete from tb_csr_custom_entry where coid = v_coid;
                            INSERT INTO tb_csr_custom_entry(domainId,customerContact,coid,HistoryId) values(p_domainId,v_customerContact,v_coid,p_HistoryId);
                            IF(SELECT isWebWidget FROM tb_ccaas_customerSatisfactionRatingDesign WHERE domainId = p_domainId) = 1
                            THEN
								INSERT INTO tb_customerFeedback(historyId,channelTypeId,domainId,feedbackQuestionAnswer,createdDate) VALUES(p_HistoryId,p_channelTypeId,p_domainId,null,now());
								SET v_customerFeedbackId = last_insert_id();
                            END IF;
        				end if;
					END IF;
				ELSE
        				INSERT INTO tb_csr_custom_entry(domainId,customerContact,coid,HistoryId) values(p_domainId, v_customerContact,v_coid,p_HistoryId);
                        IF(SELECT isWebWidget FROM tb_ccaas_customerSatisfactionRatingDesign WHERE domainId = p_domainId) = 1
						THEN
							INSERT INTO tb_customerFeedback(historyId,channelTypeId,domainId,feedbackQuestionAnswer,createdDate) VALUES(p_HistoryId,p_channelTypeId,p_domainId,null,now());
							SET v_customerFeedbackId = last_insert_id();
						END IF;
			END IF;
                
            
            
           	SELECT 	v_customerFeedbackId as customerFeedbackId
				,	v_customerName		AS customerName
           		,	v_customerContact 	AS customerContact
           		,	v_domainContact 	AS domainContact
           		, 	p_HistoryId 		AS HistoryId
           		,	CSR.domainId, CSR.caption, CSR.isEnable, CSR.ratingDesignType, CSR.labelRatingType, CSR.followUpQuestion, CSR.thanksNote, CSR.dontDisturbType, CSR.dontDistrubTime
           		, 	CSR.additionalQuestionType,	CSR.additionalQuestions
           		,	CASE 	WHEN p_channelTypeId = 2003004  			THEN IFNULL(t_CC.your_number, v_domainContact)
           					WHEN p_channelTypeId = 2003003  		THEN IFNULL(EC.emailAddress, v_domainContact)
       						
       						
           			END 				AS sendFrom 						
           		,	CSR.smsMessage
           		,	CSR.emailSubject
           		,	CSR.emailMessage
                ,	1 								AS errCode
                , 	'Please provide your feedback' 	AS errMsg
        		,CSR.minimumDurationType, CSR.minimumDuration, v_AgentId as AgentId
           	FROM 	tb_ccaas_customerSatisfactionRatingDesign 	CSR
           	LEFT JOIN email_config								EC		ON EC.EmailConfigId = CSR.emailIdSend
           	LEFT JOIN tmp_CallConfiguration						t_CC	ON t_CC.pid			= CSR.smsNumberSend
            
            
       		LEFT JOIN tb_FacebookConfiguration					t_FC	ON t_FC.FacebookPageId	= CSR.facebookChatFlows
             LEFT JOIN tb_InstagramConfiguration					t_IC	ON t_IC.InstagramPageId	= CSR.instagramChatFlows
           	WHERE 	CSR.domainId	= p_domainId
           	AND (	(p_channelTypeId = 2003001  		AND CSR.isVoice 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.callFlows)	 		> 0)
           		OR	(p_channelTypeId = 2003002  		AND CSR.isWebWidget = 1 	AND FIND_IN_SET(v_channelValue,CSR.Widgets) 			> 0)
           		OR	(p_channelTypeId = 2003003  		AND CSR.isEmail 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.emails) 				> 0)
           		OR	(p_channelTypeId = 2003004  			AND CSR.isSms 		= 1 	AND FIND_IN_SET(v_channelValue,CSR.smsNumbers) 			> 0)
           		OR	(p_channelTypeId = 2003005  	AND CSR.isWhatsApp 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.whatsAppChatFlows) 	> 0)
           		OR	(p_channelTypeId = 2003006  	AND CSR.isFacebook 	= 1 	AND FIND_IN_SET(v_channelValue,CSR.facebookChatFlows) 	> 0)
           		OR	(p_channelTypeId = 2003007  	AND CSR.isInstagram = 1 	AND FIND_IN_SET(v_channelValue,CSR.instagramChatFlows) 	> 0)
                 OR	(p_channelTypeId = 2003008  	AND CSR.isVideo = 1 ));
           	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
           END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_GetCustomerSatisfactionForChannel_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
