/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_GetDashboardLeaderboardDetails`(
       p_startTmpstmp 	BIGINT,
       p_endTmpstmp 		BIGINT,
       p_domainId		INT	
  )
SP_Logic: BEGIN
     DECLARE v_startTmpstmp BIGINT;		
     DECLARE v_endTmpstmp BIGINT;
     DECLARE p_channelType VARCHAR(255);
 
     SET p_channelType = 'Chat,Call,Email,Sms,Whatsapp';
     
    
     
SET p_startTmpstmp = UNIX_TIMESTAMP(DATE_FORMAT(NOW(), '%Y-%m-%d 00:00:00')) * 1000;
SET p_endTmpstmp = UNIX_TIMESTAMP(DATE_FORMAT(NOW(), '%Y-%m-%d 12:00:00')) * 1000;

IF IFNULL(p_startTmpstmp, 0) = 0 THEN SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF;
IF IFNULL(p_endTmpstmp, 0) = 0 THEN SET v_endTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;     
IF IFNULL(p_channelType, 0) = 0 THEN SET p_channelType = 'Chat,Call,Email,Sms,Whatsapp';	END IF;
 
     
     DROP TEMPORARY TABLE IF EXISTS temp_channeltype;
     CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(255));
 
     CALL split(p_channelType, ','); 
 
     INSERT INTO temp_channeltype (channelType)
     SELECT Items FROM tt_Split_temptable; 
 
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 
     DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	
     CREATE TEMPORARY TABLE temp_AvailableUser (
         UserId BIGINT, 
         UserName VARCHAR(255),
         roleid INT
     );    
 
     INSERT INTO temp_AvailableUser (UserId, UserName, roleid)
     SELECT UserID, UserName, roleid
     FROM tb_User
     WHERE domainId = p_domainId
     AND roleid IN (6,5,3);    
 
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
 
     DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
     CREATE TEMPORARY TABLE tt_temp_sessionHistory (
         agentId 			BIGINT,
         agentName 			VARCHAR(250),
         `role`      		VARCHAR(50),
         sessionHistoryDate DATE
     );
     
     
     IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Call' LIMIT 1) THEN
         INSERT INTO tt_temp_sessionHistory(agentId, agentName, role,sessionHistoryDate) 
         SELECT  t_A.UserID 																									AS AgentId,
 				t_A.UserName 																								AS AgentName, 
 				CASE WHEN t_A.roleId = 6 THEN 'Agent'WHEN t_A.roleId = 5 THEN 'Admin'WHEN t_A.roleId = 3 THEN 'Supervisor'
 				ELSE 'Unknown'  END 																						AS role,
 				CAST(FROM_UNIXTIME(CH.sessionStartTime/1000) AS DATE) 														AS sessionHistoryDate
         FROM tb_CallHistory CH
         JOIN tb_CallDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
        
         JOIN temp_AvailableUser t_A ON t_A.UserId = CDH.AgentId
         WHERE CH.domainId = p_domainId 
         AND CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
     END IF;
 
     
     IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Chat' LIMIT 1) THEN
 INSERT INTO tt_temp_sessionHistory(agentId,agentName,role,sessionHistoryDate) 
 
  		SELECT 	
  				t_A.UserID																									AS AgentId
  			,	t_A.UserName																								AS AgentName	
 			,	CASE WHEN t_A.roleId = 6 THEN 'Agent'WHEN t_A.roleId = 5 THEN 'Admin'WHEN t_A.roleId = 3 THEN 'Supervisor'
 				ELSE 'Unknown'  END 																						AS role
 			,	CAST(FROM_UNIXTIME(CH.sessionStartTime/1000) AS DATE)														AS sessionHistoryDate
  		FROM 	tb_ChatHistory 			CH
  		JOIN 	tb_ChatDurationHistory	CDH	ON CH.ChatHistoryId = CDH.ChatHistoryId        		   
          join     temp_AvailableUser  	t_A ON t_A.UserId		  = CDH.AgentId
  		WHERE 	CH.domainId 		= p_domainId   		
  		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
 
  	END IF; 
     
      IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'Email' LIMIT 1) THEN
 INSERT INTO tt_temp_sessionHistory(agentId,agentName,role,sessionHistoryDate) 
   
  		SELECT 	
  				t_A.UserID																										AS AgentId
  			,	t_A.UserName																									AS AgentName	
 			,	CASE WHEN t_A.roleId = 6 THEN 'Agent'WHEN t_A.roleId = 5 THEN 'Admin'WHEN t_A.roleId = 3 THEN 'Supervisor'
 				ELSE 'Unknown'  END 																							AS role
              ,	CAST(FROM_UNIXTIME(CH.sessionStartTime/1000) AS DATE)															AS sessionHistoryDate
  		FROM 	tb_EmailHistory 			CH
  		JOIN 	tb_EmailDurationHistory	CDH	ON CH.EmailHistoryId = CDH.EmailHistoryId        		   
          JOIN temp_AvailableUser t_A ON t_A.UserId = CDH.AgentId
  		WHERE 	CH.domainId 		= p_domainId   		
  		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
   
  	END IF;     
      IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'SMS' LIMIT 1) THEN
 	INSERT INTO tt_temp_sessionHistory(agentId,agentName,role,sessionHistoryDate) 
 
  		SELECT 		
  				t_A.UserID																										AS AgentId
  			,	t_A.UserName																									AS AgentName	
 			,	CASE WHEN t_A.roleId = 6 THEN 'Agent'WHEN t_A.roleId = 5 THEN 'Admin'WHEN t_A.roleId = 3 THEN 'Supervisor'
 				ELSE 'Unknown'  END 																							AS role
              ,	CAST(FROM_UNIXTIME(CH.sessionStartTime/1000) AS DATE)															AS sessionHistoryDate
  		FROM 	tb_SMSHistory 			CH
  		JOIN 	tb_SMSDurationHistory	CDH	ON CH.SMSHistoryId = CDH.SMSHistoryId        		   
          JOIN temp_AvailableUser t_A ON t_A.UserId = CDH.AgentId
  		WHERE 	CH.domainId 		= p_domainId   		
  		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
  	END IF;  
 
 
        IF EXISTS (SELECT 1 FROM temp_channeltype WHERE channelType = 'whatsapp' LIMIT 1) THEN
 INSERT INTO tt_temp_sessionHistory(agentId,agentName,role,sessionHistoryDate) 
 
  		SELECT 	
  				t_A.UserID																										AS AgentId
  			,	t_A.UserName																									AS AgentName	
 			,	CASE WHEN t_A.roleId = 6 THEN 'Agent'WHEN t_A.roleId = 5 THEN 'Admin'WHEN t_A.roleId = 3 THEN 'Supervisor'
 				ELSE 'Unknown'  END 																							AS role
              ,	CAST(FROM_UNIXTIME(CH.sessionStartTime/1000) AS DATE)															AS sessionHistoryDate
  		FROM 	tb_WhatsappHistory 			CH
  		JOIN 	tb_WhatsappDurationHistory	CDH	ON CH.WhatsappHistoryId = CDH.WhatsappHistoryId        		   
 		JOIN temp_AvailableUser t_A ON t_A.UserId = CDH.AgentId
  		WHERE 	CH.domainId 		= p_domainId   		
  		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  	END IF;    
 
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc_1; 
     CREATE TEMPORARY TABLE tt_sessionHistory_calc_1 AS 
     SELECT  distinct(AgentId) as AgentId, AgentName,role, sessionHistoryDate FROM tt_temp_sessionHistory;
     
 
     SELECT sessionHistoryDate,AgentId,AgentName, role FROM tt_sessionHistory_calc_1;
 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_getLatestCallMessage` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_getLatestCallMessage`(
p_sessionId		VARCHAR(250),
p_domainId 		INT
)
BEGIN
	DECLARE v_CallDurationHistoryId		BIGINT;
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    SELECT 	MAX(CallDurationHistoryId)
    INTO 	v_CallDurationHistoryId
    FROM 	tb_CallHistory 			CH
    JOIN  	tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId 
    WHERE 	CH.sessionId	= p_sessionId
    AND		CH.domainId		= p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  
	SELECT 	a.Message   
	FROM 	tb_CallMessage a	
	WHERE 	a.CallDurationHistoryId = v_CallDurationHistoryId;        
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_GetLatestContact` */;
