/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_GetLatestContact`(p_domainId	INT)
BEGIN

	DECLARE v_CurDate		DATETIME DEFAULT NOW(); 
    
    DROP TEMPORARY TABLE IF EXISTS temp_CustomerContact;
    CREATE TEMPORARY TABLE temp_CustomerContact(coid INT);
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;      
    INSERT INTO temp_CustomerContact
	SELECT 	coid 
    FROM 	customer_contact
    WHERE 	domainId	= p_domainId
    and 	DATEDIFF(createdAt,v_CurDate)  = 0
    ORDER BY updatedAt DESC, createdAt DESC LIMIT 3;
    
    IF NOT EXISTS(SELECT 1 FROM temp_CustomerContact)
    THEN
		INSERT INTO temp_CustomerContact
		SELECT 	coid 
		FROM 	customer_contact
		WHERE 	domainId	= p_domainId
		ORDER BY updatedAt DESC, createdAt DESC LIMIT 1;
    END IF;
    
    SELECT 	C_C.coid		as id
			,C_C.firstName
			,C_C.lastName
			,C_C.primaryPhoneNumber
			,C_C.phoneNumber
			,C_C.primaryEmail
			,C_C.email
			,C_C.accountNumber
			,C_C.tags
			,C_C.location
			,C_C.address
			,C_C.country
			,C_C.state
			,C_C.city
			,C_C.postalCode
			,C_C.facebook
			,C_C.instagram
			,C_C.whatsapp
			,C_C.twitter
			,C_C.createdAt
			,C_C.updatedAt
			,C_C.voiceBiometric			
			,C_C.mergeCustomer			
			,C_C.`type`
			,C_C.currentCustomerNumber
			,C_C.customerType
			,C_C.Timezone
			,C_C.blockedBy
			,C_C.doNotDisturbBy
			,C_C.blockedReqBy
			,C_C.doNotDisturbReqBy
			,C_C.Reason
			,C_C.cookiesId
			,C_C.`Source`
    FROM 	temp_CustomerContact	t_CC
    JOIN 	customer_contact		C_C		ON t_CC.coid	= C_C.coid;    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
