/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_GetSLAConditionForCondition` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_GetSLAConditionForCondition`(
  	p_CompanyId				INT
  	,p_Subject				VARCHAR(250)
  	,p_Description			TEXT
  	,p_Status				VARCHAR(100)
  	,p_Priority				VARCHAR(100)		
  	,p_TicketType			VARCHAR(100)		
  	,p_Source				VARCHAR(100)		
  	,p_Requester			VARCHAR(100)		
  	,p_UpdatedBy			VARCHAR(100)		
  	,p_Layout				VARCHAR(100)		
  	,p_Tags					VARCHAR(100)		
    ,OUT p_SLAconditionId	INT
  )
SP : BEGIN
	DECLARE v_SMNoI				SMALLINT DEFAULT 1;
	DECLARE v_MaxSMNoI			SMALLINT;    
	DECLARE v_Query				LONGTEXT;
	DECLARE v_SLAconditionId	INT;
	DECLARE v_FieldType			VARCHAR(100);
	DECLARE v_Operator			VARCHAR(20);
	DECLARE v_FieldValues		VARCHAR(250);
	DECLARE v_ColumnValues		TEXT;
	DECLARE v_MatchCount		TINYINT;
      
	DROP TEMPORARY TABLE IF EXISTS tt_SM;
  	CREATE TEMPORARY TABLE tt_SM(SMNo	SMALLINT,SLAconditionId	INT,FieldType	VARCHAR(100),Operator	VARCHAR(20),FieldValues	VARCHAR(250));	
      
  	INSERT INTO tt_SM(SMNo,SLAconditionId,FieldType,Operator,FieldValues)
  	SELECT 	ROW_NUMBER() OVER (ORDER BY SLAconditionId)
  		,	SC.SLAconditionId	
  		,	FT.TypeCodeName		AS FieldType	
  		,	CASE 	WHEN OperatorTypeId IN (1106001,1106009,1106007) THEN '='  
  					WHEN OperatorTypeId IN (1106003,1106010,1106008) THEN '<>'  
  					WHEN OperatorTypeId IN (1106002,1106005,1106006) THEN 'LIKE'  
  					WHEN OperatorTypeId IN (1106004) THEN 'NOT LIKE' END	AS Operator
  		,	CONCAT(CASE WHEN OperatorTypeId IN (1106002,1106006,1106004) THEN '%' ELSE '' END, SMC.FieldValues, CASE WHEN OperatorTypeId IN (1106002,1106005,1106004) THEN '%' ELSE '' END) AS FieldValues
  	FROM 	tb_TicketSLAcondition 		SC
  	JOIN 	tb_TicketSLAMatchCondition	SMC	ON SMC.SLAconditionId	= SC.SLAconditionId
  	JOIN 	TypeCode					FT	ON SMC.FieldTypeId		= FT.TypeCodeID
  	JOIN 	TypeCode					OT	ON SMC.OperatorTypeId	= OT.TypeCodeID
  	WHERE 	SC.CompanyId				= p_CompanyId
  	AND 	IFNULL(SMC.FieldValues,'') <> '';    
      
      DROP TEMPORARY TABLE IF EXISTS tt_S;
      CREATE TEMPORARY TABLE tt_S(SLAconditionId	INT UNIQUE KEY, MatchCount	TINYINT DEFAULT 0);
      
      INSERT INTO tt_S(SLAconditionId)
      SELECT 	SLAconditionId     
      FROM 	tt_SM
      GROUP BY SLAconditionId;        
      
      SELECT 	MAX(SMNo) INTO v_MaxSMNoI
      FROM 	tt_SM;        
      
  	SLAMatch:WHILE v_SMNoI <= v_MaxSMNoI
  	DO
  		SET v_Query 			= NULL
		,	v_SLAconditionId	= NULL
        , 	v_FieldType			= NULL
        , 	v_Operator			= NULL
        , 	v_FieldValues		= NULL
        , 	v_MatchCount		= NULL;
  		
  		SELECT 	SM.SLAconditionId, SM.FieldType, SM.Operator, SM.FieldValues, S.MatchCount 
  		INTO 	v_SLAconditionId, v_FieldType, v_Operator, v_FieldValues, v_MatchCount 
  		FROM 	tt_SM	SM
  		JOIN 	tt_S	S	ON S.SLAconditionId = SM.SLAconditionId
  		WHERE 	SMNo = v_SMNoI;
  		
  		IF v_MatchCount > -1
  		THEN
  			SET v_ColumnValues = CASE 	WHEN v_FieldType = 'Subject' 		THEN p_Subject
  										WHEN v_FieldType = 'Description' 	THEN p_Description
  										WHEN v_FieldType = 'Status' 		THEN p_Status
  										WHEN v_FieldType = 'Priority' 		THEN p_Priority
  										WHEN v_FieldType = 'TicketType' 	THEN p_TicketType
  										WHEN v_FieldType = 'Source' 		THEN p_Source
  										WHEN v_FieldType = 'Requester' 		THEN p_Requester
										WHEN v_FieldType = 'UpdatedBy' 		THEN p_UpdatedBy
                                        WHEN v_FieldType = 'Layout' 		THEN p_Layout
                                        WHEN v_FieldType = 'Tags' 			THEN p_Tags END;
                                                      
				SET v_Query = CONCAT('UPDATE tt_S SET MatchCount = MatchCount + CASE WHEN "', v_ColumnValues,'"  ',v_Operator,'"',v_FieldValues,'" THEN 1 ELSE -1 END WHERE SLAconditionId = ',v_SLAconditionId,';');                
              
				IF v_Query IS NOT NULL 
				THEN 
					SET @t = v_Query; 
					PREPARE stmt FROM @t;
					EXECUTE stmt;
					DEALLOCATE PREPARE stmt; 
				END IF;
              
  
			END IF;
			
			SET v_SMNoI = v_SMNoI + 1;
		END WHILE SLAMatch;
      
	SELECT	SLAconditionId
    INTO 	p_SLAconditionId
	FROM 	tt_S 
	ORDER BY MatchCount DESC LIMIT 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
