CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_GetVisitorInsightsReports`(	
  p_domainid        INT,
  p_Limit 			INT,
  p_offset 			INT
  )
BEGIN
  DECLARE v_offset 		INT;

  SET v_offset = p_Limit * p_offset; 
  
	DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
	CREATE TEMPORARY TABLE tt_temp_sessionHistory as 
	select 
		CASE WHEN (CC.firstName is not null or CC.lastName is not null)
			THEN trim(CONCAT(ifnull(CC.firstName,'') , ' ', ifnull(CC.lastName,'')))
		ELSE 'New Customer' 
        END  AS VisitorName ,
		
		CH.sessionStartTime																			AS dateAndTime,
		CH.location             																	AS location,
		CONCAT(CH.device, ', ', CH.ipAddress, ', ', CH.browser) 									AS deviceIpAddressBrowser,
		CH.language,																
		ABS(IFNULL(CH.sessionStartTime-CH.sessionEndTime,0))   										AS duration 
	  
      ,CC.Timezone
  FROM  tb_VisitorInsightDetails    CH
  JOIN customer_contact            	CC ON  CH.coid = CC.coid AND CH.domainId = CC.domainId
  WHERE CH.domainId = p_domainid
  AND CH.sessionEndTime IS NOT NULL
  ORDER BY CH.visitorId DESC
  LIMIT v_offset, p_Limit; 
   
   SELECT VisitorName,dateAndTime,location,deviceIpAddressBrowser,language,duration,Timezone 
   FROM tt_temp_sessionHistory;
   
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
