CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_get_customer_contact_custom_field`(	p_domainId		INT
   )
BEGIN
   
       
       DECLARE v_tableName		VARCHAR(100);
       SET v_tableName = concat("customer_contact_",p_domainid);
       
       SELECT 	id
			,	columName
			,	columnLabel
			,	columnType
			,	columnValue
