CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_inboundchat_agent_analysis_metrics`(  
              	p_domainId 			INT,
         		p_offset 			INT,
   			p_Limit 		    INT
     )
BEGIN
      	DECLARE v_offset		INT;
   	DECLARE v_startTmpstmp 	BIGINT;
   	DECLARE v_endTmpstmp 	BIGINT;
   
       	SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000;        
   		SET @v_endTmpstmp 	= unix_timestamp(now())*1000;          	SET v_offset =  p_Limit * p_Offset;
           
                 DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                  CREATE TEMPORARY TABLE temp_AllagentId
                  SELECT DISTINCT UserID,UserName as AgentName from tb_User where domainId = 7128; 
            		  
   				 
                   
                   
                
   
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
   	DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
   	CREATE TEMPORARY TABLE temp_chatHistory AS 
   	SELECT 		CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		   						 						    AS SessionDate
   				
   					,	U.UserID																								AS agentId
                       ,	U.UserName																								AS agentName   
   					,CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '-'	end 								AS abondedchats
                       ,CASE WHEN (SH.repliedDate - SH.createdAt) is not null then (SH.repliedDate - SH.createdAt) else '-' end  	AS responseTime
                       ,CASE WHEN SH.CallBackStatus=1 then 1 else 0 end															AS UnansweredChat
                       ,CASE WHEN SDH.transferredTime is not null then transferredTime else '-' end								AS transferredchat
                       ,CASE WHEN SDH.Duration	is not null then Duration else '-' end												AS chatduration
                       ,CASE WHEN SH.IsInBound=1 THEN 1 ELSE 	0 		END 														AS interactionfromcustomer
                       ,CASE WHEN 	SH.IsInBound=0 THEN 1 ELSE 	0 		END 														AS interactionfromagent
                       ,'-' 																										AS interaction
                       ,'-'																										AS peakchats
                       FROM 	tb_ChatHistory 				     SH
   					JOIN 	tb_ChatDurationHistory		     SDH	ON SH.chatHistoryId = SDH.chatHistoryId
   				
   				
   				
   					LEFT JOIN tb_User					       U	ON U.UserID			= SDH.AgentId
   					WHERE 	SH.domainId 		= p_domainId		
   					AND		SH.IsInBound		= 1	
  					AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and  @v_endTmpstmp 	
   			
   					LIMIT v_offset, p_limit;
   				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
   				SELECT COUNT(1) totalCount FROM temp_chatHistory;
   			  SELECT * from temp_AllagentId;
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
   			SELECT 
   					
                            t_SH.agentName 																				as agentname
                           ,count(1)																						AS receivedchats 
                           ,t_SH.responseTime																				AS respondedchat
                           ,t_SH.abondedchats																				AS abondedchats
                           ,SUM(t_SH.UnansweredChat)																		AS MissedChat   
                           ,t_SH.transferredchat																			AS transferredchat
   						,SUM(t_SH.chatduration)																			AS totalChatduration
                           ,CASE WHEN AVG(t_SH.chatduration)		IS NOT NULL THEN AVG(t_SH.chatduration) ELSE '-' END	AS avgChatduration
                           ,(t_SH.interactionfromcustomer/100)																AS interactionfromcustomer
                           ,(t_SH.interactionfromagent/100)															    AS interactionfromagent
                           ,sum(t_SH.interaction)																			AS totalinteraction
                           ,t_SH.peakchats																					AS peakchats
   						FROM 	temp_chatHistory t_SH
   						GROUP BY   t_SH.agentName,t_SH.responseTime,t_SH.abondedchats,t_SH.transferredchat,t_SH.interactionfromcustomer,
                           t_SH.interactionfromagent,t_SH.interaction,t_SH.peakchats ;
   						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   		
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_inboundchat_analysis_metrics1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_inboundchat_analysis_metrics1`(  
     p_domainId 			INT,
 	p_Offset			INT,
 	p_Limit				INT  
   )
BEGIN
	
    DECLARE v_offset		INT;
 	DECLARE v_startTmpstmp 	BIGINT;
 	DECLARE v_endTmpstmp 	BIGINT;
 
     
 		SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000;        
 		SET @v_endTmpstmp 	= unix_timestamp(now())*1000;         
		SET v_offset =  p_Limit * p_Offset; 
     
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
		DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
        CREATE TEMPORARY TABLE temp_chatHistory AS 
 	 SELECT 		  CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		   						 					AS SessionDate
 					 ,CASE WHEN Q.name IS NOT NULL THEN Q.name ELSE '-'  END         											AS queueName
 					 ,CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '-'	end 								AS abondedchats
                     ,CASE WHEN (SH.repliedDate - SH.createdAt) is not null then (SH.repliedDate - SH.createdAt) else '-' end  	AS responseTime
                     ,CASE WHEN SH.CallBackStatus=1 then 1 else 0 end															AS UnansweredChat
                     ,CASE WHEN SDH.transferredTime is not null then transferredTime else '-' end								AS transferredchat
                     ,CASE WHEN SDH.Duration	is not null then Duration else '-' end											AS chatduration
                     ,CASE WHEN SH.IsInBound=1 THEN 1 ELSE 	0 		END 														AS interactionfromcustomer
                     ,CASE WHEN 	SH.IsInBound=0 THEN 1 ELSE 	0 		END 													AS interactionfromagent
                     ,'-' 																										AS interaction
                     ,'-'																										AS peakchats
                     FROM 	tb_ChatHistory 				SH
 					 JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId
 					 LEFT JOIN 	queue					  Q ON Q.qid				= SDH.queueId			 
 					 LEFT JOIN tb_User					  U	ON U.UserID				= SDH.AgentId
 					 WHERE 	SH.domainId 		= p_domainId		
 					 AND		SH.IsInBound		= 1	
					 AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp
 					 LIMIT v_offset, p_limit;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
 				SELECT COUNT(1) totalCount FROM temp_chatHistory;
     
               SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
 			SELECT 
						 t_SH.queueName																					AS queueName
						,count(1)																						AS receivedchats 
						,t_SH.responseTime																				AS responseTime
						,t_SH.abondedchats																				AS abondedchats
						,SUM(t_SH.UnansweredChat)																		AS MissedChat   
						,t_SH.transferredchat																			AS transferredchat
						,SUM(t_SH.chatduration)																			AS totalChatduration
						,CASE WHEN AVG(t_SH.chatduration)IS NOT NULL THEN AVG(t_SH.chatduration) ELSE '-' END			AS avgChatduration
						,(t_SH.interactionfromcustomer/100)																AS interactionfromcustomer
						,(t_SH.interactionfromagent/100)															    AS interactionfromagent
						,sum(t_SH.interaction)																			AS totalinteraction
						,t_SH.peakchats																					AS peakchats
 						FROM 	temp_chatHistory t_SH
 						GROUP BY  t_SH.queueName,t_SH.responseTime,t_SH.abondedchats,t_SH.transferredchat,t_SH.interactionfromcustomer,
                         t_SH.interactionfromagent,t_SH.interaction,t_SH.peakchats ;
 						SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
							
                            
                       
                            
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_inbound_call_summary_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_inbound_call_summary_report`(
          	p_startTmpstmp 		BIGINT,
          	p_endTmpstmp 		BIGINT,
          	p_timeZone 			VARCHAR(200),
          	p_domainId 			INT,
          	p_queueId 			TEXT,
          	p_agentId 			TEXT,
  			p_direction			TINYINT,
  			p_Limit 			INT,
  			p_offset 			INT, 
			p_dispositionIds	VARCHAR(250)
           )
sp_return: BEGIN 
   			DECLARE v_offset		 INT;
   			DECLARE v_count 		 INT; 
    			DECLARE v_startTmpstmp   BIGINT;
 			DECLARE v_endTmpstmp 	 BIGINT;
           
   			SET v_offset =  p_Limit * p_offset;
                   
 			IF IFNULL(p_startTmpstmp,0) = 0   THEN 	   			
 				SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000;    		
 			ELSE
 				SET v_startTmpstmp = p_startTmpstmp;	           
 			END IF; 
                  
           		IF IFNULL(p_endTmpstmp,0) = 0 	
                  THEN 	
          			SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; 
          		ELSE
          			SET v_endTmpstmp = p_endTmpstmp;
          		END IF;  							
                 
 			DROP TEMPORARY TABLE IF EXISTS temp_queueId;  				CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
 			DROP TEMPORARY TABLE IF EXISTS temp_agentId;				CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId VARCHAR(100));
 			DROP TEMPORARY TABLE IF EXISTS temp_direction;				CREATE TEMPORARY TABLE temp_direction(directionId 	TINYINT);
 			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; 	CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
           
			CALL split(p_queueId,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
			CALL split(p_agentId,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
			CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) 	SELECT Items FROM tt_Split_temptable;
           
         		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
         		CREATE TEMPORARY TABLE temp_AllqueueId
 				SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
         		
         		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
         		CREATE TEMPORARY TABLE temp_AllagentId
         		select UserID,UserName from tb_User where domainId = p_domainId;  
               
       	IF p_direction IS NULL
                THEN
            		INSERT INTO temp_direction 
                    (directionId)
                    VALUES (0),(1);
            	ELSE
            		INSERT INTO temp_direction
                    (directionId)
                    SELECT p_direction;
                END IF;
                  DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
                CREATE TEMPORARY TABLE temp_AlldirectionId
                select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
        								   WHEN directionId = 1 THEN 'InBound' END AS directionName 
       								   FROM temp_direction ;      
                INSERT INTO temp_AvailableDisposition 
          		SELECT 	did 			dispositionId
          			,	dispositionName	DispositionStatus
          		FROM 	disposition_status
          		WHERE 	domainId	= p_domainId;              
               
               
          		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
          		CREATE TEMPORARY TABLE temp_sessionHistory AS 
 				SELECT 	CH.sessionStartTime
 					, 	CH.customerNumber
 					,	CH.CustomerId
 					,	Q.queueName							queueName
 					,	U.UserName						    agentName
 					, 	IFNULL(CDH.Duration,0) + IFNULL((CDH.afterCallWorkTime * 1000),0) as callDuration
 					, 	CASE WHEN IFNULL(c_c.firstName,'') = '' THEN 'New Customer' ELSE CONCAT(c_c.firstName,' ' ,c_c.lastName) END 				as customerName
 					, 	CDH.afterCallWorkTime
 					, 	DS.dispositionName  			    AS disposition
                     ,	CDH.QueueId
                     ,	CDH.AgentId
                     ,	CDH.dispositionId
                     ,	CDH.subject
                     ,	CDH.summary
 				FROM tb_CallHistory		 			CH 
 				JOIN tb_CallDurationHistory			CDH		ON CH.CallHistoryId = CDH.CallHistoryId
 				LEFT JOIN temp_AllqueueId			Q		ON CDH.QueueId		= Q.queueId
 				LEFT JOIN temp_AllagentId			U		ON U.UserID			= CDH.AgentId   
 				JOIN customer_contact		   		c_c		ON c_c.coid 		= CH.CustomerId  
 				LEFT JOIN disposition_status        DS   	ON DS.domainId 		= CH.domainId				AND CDH.dispositionId	= DS.did
 				
 				WHERE 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp 
 				AND 	CH.IsInBound			= 1
 				AND 	CH.domainId 			= p_domainId 	
                AND 	((CDH.QueueId in (select queueId from temp_queueId)) OR  (ifnull(p_queueId,'')=''))
				AND 	((CDH.AgentId in (select agentId from temp_agentId)) OR  (ifnull(p_agentId,'')=''))
				AND 	((CDH.dispositionId in (select dispositionId from temp_dispositionIds)) OR  (ifnull(p_dispositionIds,'')=''))

 				ORDER BY sessionStartTime DESC ;
                  
          		SELECT 	count(1) count FROM	temp_sessionHistory;
                 
         		SELECT * from temp_AllqueueId;
         		SELECT * from temp_AllagentId;
         		SELECT * from temp_AvailableDisposition;
                 
          		SELECT  e.sessionStartTime 						as `date`
          			,	e.customerNumber
  					,	e.customerName
          	 		,	e.queueName 							as queueName
          		 	,	e.agentName 							as agentName
          		 	,  	e.callDuration 							as callDuration
          			,	e.afterCallWorkTime  					as ACW
          		 	,	e.callDuration  						as totalDuration    
       	            ,   e.disposition
                     ,	e.summary
                     ,	e.subject
          		FROM  	temp_sessionHistory 		e;
       
        
          end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Inbound_call_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Inbound_call_trendchart`(
 	p_domainId 			INT,
 	p_datetype 			INT,            
 	p_startDateTime		DATETIME,
 	p_endDateTime		DATETIME,
 	p_columnName    	VARCHAR(200),    
 	p_agentId 			TEXT
    )
BEGIN
    
    
   	DECLARE v_startDateTime			DATETIME;
   	DECLARE v_endDateTime			DATETIME;     
   	DECLARE v_datetimeInterval		SMALLINT;    
   	DECLARE v_startDateTimePast		DATETIME;
   	DECLARE v_endDateTimePast		DATETIME;
        
   	DECLARE v_startTimestampPast	BIGINT;
   	DECLARE v_endTimestampPast		BIGINT;      
   	DECLARE v_startTimestamp		BIGINT;
   	DECLARE v_endTimestamp			BIGINT;
   	DECLARE v_curDate				DATETIME DEFAULT NOW();	
       DECLARE v_currentCount			INT;
       DECLARE v_pastCount				INT;
       
   	DROP TEMPORARY TABLE IF EXISTS tmp_result;
   	CREATE TEMPORARY TABLE tmp_result(
   		reportAge			VARCHAR(20)
   		,startDateTime		DATETIME
   		,endDateTime		DATETIME
   		,callCount			INT
   	);    
    
    	IF p_datetype = 1 
        THEN 	
    		SET v_startDateTime = CAST(v_curDate AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
    	END IF;
    	IF p_datetype = 2 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
    	END IF;
    	IF p_datetype = 3 
            THEN 
        		
                  
                  SET v_startDateTime = p_startDateTime;
                  SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                  
      			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                  
          		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                  SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        	END IF;
        	IF p_datetype = 4 
            THEN 
        		SET v_startDateTime = p_startDateTime; 
                SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND); 
                
                SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        	END IF;
        
        IF p_agentId IS NOT NULL 
        THEN
    		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
    		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
        ELSE
    		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
           CREATE TEMPORARY TABLE temp_agentIds
  		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
                END IF;
        DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
        CREATE TEMPORARY TABLE tmp_Disposition
        SELECT did, dispositionName
        FROM 	disposition_status
        WHERE	domainId		= p_domainId;
       
        
        IF p_datetype IN (1,2)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
 			WITH RECURSIVE CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	endDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
    	ELSEIF p_datetype IN (3,4)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH recursive CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	startDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
        END IF;  
        
        ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
        
        UPDATE tmp_timings
        SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
    		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
            
    	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
   	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
   	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
   	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
      
      
     DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
   	CREATE TEMPORARY TABLE tmp_CallDurationHistory
   	SELECT 	CH.CallHistoryId
   		,	CH.sessionStartTime
         ,	CDH.CallDurationHistoryId
   		,	CDH.IsMissedCall
   		,	CDH.dispositionId        
   		,	CDH.Duration
         ,	CH.IsAbandoned
   	FROM 	tb_CallHistory         	CH
   	JOIN 	tb_CallDurationHistory 	CDH		ON 	CH.CallHistoryId 	= CDH .CallHistoryId    
    
   	WHERE 	CH.domainId 		= p_domainId
   	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
   	AND 	CH.IsInBound		= 1
     AND 	CDH.IsBot			= 0
     AND 	CDH.agentId IS NOT NULL;
    	
   	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
    	CREATE TEMPORARY TABLE tmp_CallHistory
       SELECT 	DISTINCT 
    			CDH.CallHistoryId 
    		, 	CDH.sessionStartTime
         ,	CDH.CallDurationHistoryId
    	FROM 	tmp_CallDurationHistory CDH;  
        
        ALTER TABLE tmp_CallHistory ADD IsMissed		TINYINT default 0;
        ALTER TABLE tmp_CallHistory ADD IsAnswered 	TINYINT default 0;
        ALTER TABLE tmp_CallHistory ADD IsAbandoned	TINYINT default 0;
        
        CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
        CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);
    
        UPDATE tmp_CallHistory			CH
        JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  AND CH.CallDurationHistoryId = CDH.CallDurationHistoryId
        LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
        SET 	CH.IsMissed		= CASE WHEN CDH.IsMissedCall = 1 	THEN 1 ELSE CH.IsMissed 	END
    		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE CH.IsAnswered 	END
         ,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned = 1 	THEN 1 ELSE 0 END;
      
      IF p_columnName = 'Inbound calls'
        THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'				AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	SUM(CASE WHEN CH.CallDurationHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
 		INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	SUM(CASE WHEN CH.CallDurationHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
   ELSEIF p_columnName = 'Abandoned Calls'
        THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsAbandoned),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
 		INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsAbandoned),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;   
    ELSEIF p_columnName = 'Answered Calls'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsAnswered),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsAnswered),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;      
          
 	ELSEIF p_columnName = 'Missed Calls'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsMissed),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
 		INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsMissed),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;        
        END IF;   
  
 		SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Current';    
         
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Past';
          
     	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
     	INTO 	v_currentCount, v_pastCount		
     	FROM 	tmp_result;
         
 		SELECT 	p_columnName    																		AS metric
 		,		ifnull(v_currentCount,0)																AS currentTotal
 		, 		ifnull(v_pastCount,0)																	AS pastTotal
 		,	    ifnull((v_currentCount - v_pastCount),0)  												AS totalDifference
 		,		IFNULL((v_currentCount - v_pastCount) /(IF(v_currentCount=0,1,v_currentCount)) *100 ,0)	AS  Percentage;
      
          END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Inbound_call_trendchart_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
