/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Inbound_call_trendchart_Test`(
       p_domainId 			INT,
     	p_datetype 			INT,            
      	p_startDateTime		DATETIME,
      	p_endDateTime		DATETIME,
     	p_columnName    	VARCHAR(200),    
     	p_agentId 			TEXT
     )
BEGIN
     
     
    	DECLARE v_startDateTime			DATETIME;
    	DECLARE v_endDateTime			DATETIME;     
    	DECLARE v_datetimeInterval		SMALLINT;    
    	DECLARE v_startDateTimePast		DATETIME;
    	DECLARE v_endDateTimePast		DATETIME;
         
    	DECLARE v_startTimestampPast	BIGINT;
    	DECLARE v_endTimestampPast		BIGINT;      
    	DECLARE v_startTimestamp		BIGINT;
    	DECLARE v_endTimestamp			BIGINT;
    	DECLARE v_curDate				DATETIME DEFAULT NOW();	
        DECLARE v_currentCount			INT;
        DECLARE v_pastCount				INT;
        
    	DROP TEMPORARY TABLE IF EXISTS tmp_result;
    	CREATE TEMPORARY TABLE tmp_result(
    		reportAge			VARCHAR(20)
    		,startDateTime		DATETIME
    		,endDateTime		DATETIME
    		,callCount			INT
    	);    
     
     	IF p_datetype = 1 
         THEN 	
     		SET v_startDateTime = CAST(v_curDate AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
     	END IF;
     	IF p_datetype = 2 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
     	END IF;
     	IF p_datetype = 3 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = CAST(v_curDate AS DATE); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
     	END IF;
     	IF p_datetype = 4 
         THEN 
     		SET v_startDateTime = p_startDateTime; 
    		SET v_endDateTime 	= p_endDateTime; 
             
            SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     	END IF;
         
         IF p_agentId IS NOT NULL 
         THEN
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
     		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
         ELSE
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
            CREATE TEMPORARY TABLE temp_agentIds
   		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
                 END IF;
         DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
         CREATE TEMPORARY TABLE tmp_Disposition
         SELECT did, dispositionName
         FROM 	disposition_status
         WHERE	domainId		= p_domainId
         AND	dispositionName	= 'Caller Disconnected';    
         
         IF p_datetype IN (1,2)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH RECURSIVE CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	endDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
     	ELSEIF p_datetype IN (3,4)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH recursive CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	startDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
         END IF;  
         
         ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
         UPDATE tmp_timings
         SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
     		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
             
     	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
    	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
    	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
    	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
       
       
      DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
    	CREATE TEMPORARY TABLE tmp_CallDurationHistory
    	SELECT 	CH.CallHistoryId
    		,	CH.sessionStartTime
    		,	CDH.IsMissedCall
    		,	CDH.dispositionId        
    		,	CDH.Duration
    	FROM 	tb_CallHistory         CH
    	JOIN 	tb_CallDurationHistory CDH	ON 	CH.CallHistoryId 	= CDH .CallHistoryId    
       JOIN     temp_agentIds 		       t_A     ON t_A.UserID 		= CDH.agentId      
    	WHERE 	CH.domainId 		= p_domainId
    	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
    	AND 	CH.IsInBound		= 1;
  SELECT v_startTimestampPast , v_endTimestamp;   	
    	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
     	CREATE TEMPORARY TABLE tmp_CallHistory
        SELECT 	DISTINCT 
     			CDH.CallHistoryId 
     		, 	CDH.sessionStartTime
     	FROM 	tmp_CallDurationHistory CDH;  
         
         ALTER TABLE tmp_CallHistory ADD IsMissed 		TINYINT default 0;
         ALTER TABLE tmp_CallHistory ADD IsAnswered 	TINYINT default 0;
         ALTER TABLE tmp_CallHistory ADD IsAbandoned	TINYINT default 0;
         
         CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
         CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);
     
         UPDATE tmp_CallHistory			CH
         JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  
         LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
         SET 	CH.IsMissed		= CASE WHEN CDH.IsMissedCall = 1 	THEN 1 ELSE CH.IsMissed 	END
     		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE CH.IsAnswered 	END
             ,	CH.IsAbandoned	= CASE WHEN D.did IS NOT NULL 		THEN 1 ELSE CH.IsAbandoned 	END;
         
     	
        
     select 'tmp_timings',a.* from tmp_timings a;  
     select 'tmp_CallHistory',a.* from tmp_CallHistory a;  
     
       IF p_columnName = 'Inbound calls'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
    ELSEIF p_columnName = 'Abandoned Calls'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(IsAbandoned),0)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(IsAbandoned),0)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;   
     ELSEIF p_columnName = 'Answered Calls'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(IsAnswered),0)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(IsAnswered),0)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;      
           
           
    ELSEIF p_columnName = 'Missed Calls'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'			AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(IsMissed),0)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(IsMissed),0)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;        
         END IF;   
   
             SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Current';    
          
          SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Past';
           
      	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
      	INTO 	v_currentCount, v_pastCount		
      	FROM 	tmp_result;
          
     
       
           END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Inbound_chat_volumebymonth_Analysis` */;
