DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Inbound_trendchart_1`(	
    		p_domainId 		INT,
   		    p_datetype 		INT,          
    		p_starttime 	BIGINT,
    		p_endtime		BIGINT,
			p_columnName    VARCHAR(200), 
			p_agentIds 		VARCHAR(250)
       )
BEGIN
    		DECLARE v_startTmp 	DATE;
    		DECLARE v_endTmp	DATE;
            
            if p_datetype = 1 then set v_startTmp = cast(current_timestamp as date); set v_endTmp = cast(current_timestamp as date); end if;
            if p_datetype = 2 then set v_startTmp = cast(current_timestamp as date) - INTERVAL 1 DAY; set v_endTmp = cast(current_timestamp as date) - INTERVAL 1 DAY; end if;
            if p_datetype = 3 then set v_startTmp = now() - INTERVAL 7 DAY; set v_endTmp = cast(current_timestamp as date);  end if;
            if p_datetype = 4 then set v_startTmp = FROM_UNIXTIME(p_starttime/1000); 
            IF IFNULL(p_endtime ,0)= 0 THEN SET v_endTmp = now() ;else set v_endTmp = FROM_UNIXTIME(p_endtime/1000); end if; END IF;  	
  
  		 DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId BIGINT);
  
  		CALL split(p_agentIds,',');	INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
               
               IF p_datetype = 1 then
               IF p_columnName = 'Received Chats'   
                 THEN
           		SELECT 	DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,COUNT(1) 
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
                 AND IsInBound = 1
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
 				GROUP BY CAST(FROM_UNIXTIME(sessionStartTime/1000)as date)
 				ORDER BY CAST(FROM_UNIXTIME(sessionStartTime/1000)as date) ASC;
 				END IF; 
 				IF p_columnName = 'Responded Chats'
 				THEN
 				SELECT 	DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,CASE WHEN (SH.repliedDate - SH/createdAt) IS NOT NULL THEN (SH.repliedDate - SH.createdAt) ELSE '0' END AS  RespondedChats
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId   
           		WHERE 	SH.domainId	= p_domainId
                 AND SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
				GROUP BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i")
 			    ORDER BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") ASC;
                 END IF;
                 IF p_columnName = 'Missedchats'
                 THEN
                 SELECT DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,ifnull(sum(CASE WHEN CallBackStatus=1 THEN 1 ELSE 0 END),0) MISSEDCHAT
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.domainId	= p_domainId AND SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp              
 			 	AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
				GROUP BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i")
 			    ORDER BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") ASC;
                 END IF;
                 IF p_columnname = 'Transferredchat'
                 THEN
 				SELECT   DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,CASE WHEN (SDH.transferredTime) IS NOT NULL THEN (SDH.transferredTime) ELSE '0' END				  AS transferredchat
           		FROM 	tb_ChatDurationHistory  SDH       
           		JOIN	tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
           		AND 	SH.domainId	= p_domainId
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
				GROUP BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i")
 			    ORDER BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") ASC;
                 END IF; 
                 IF p_columnname = 'Abondedchats' 
                 THEN
 				SELECT DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,ifnull(sum(CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	end),0)								AS abondedchats
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
           		AND 	domainId	= p_domainId
 			 	AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 			 	AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
				GROUP BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i")
 			    ORDER BY DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") ASC;
                 END IF; 
 
 END IF;
			   IF p_datetype = 2 then
               IF p_columnName = 'Received Chats'   
                 THEN
           		SELECT 	DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,COUNT(1) 
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
                 AND IsInBound = 1
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
 				GROUP BY CAST(FROM_UNIXTIME(sessionStartTime/1000)as date)
 				ORDER BY CAST(FROM_UNIXTIME(sessionStartTime/1000)as date) ASC;
 				END IF; 
 				IF p_columnName = 'Responded Chats'
 				THEN
 				SELECT 	DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,CASE WHEN (repliedDate - createdAt) IS NOT NULL THEN (repliedDate - createdAt) ELSE '0' END AS  RespondedChats
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.domainId	= p_domainId
                 AND SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
                 END IF;
                 IF p_columnName = 'Missedchats'
                 THEN
                 SELECT DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,ifnull(sum(CASE WHEN CallBackStatus=1 THEN 1 ELSE 0 END),0) MISSEDCHAT
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.domainId	= p_domainId AND SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp              
 			 	AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
                 END IF;
                 IF p_columnname = 'Transferredchat'
                 THEN
 				SELECT   DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,CASE WHEN (SDH.transferredTime) IS NOT NULL THEN (SDH.transferredTime) ELSE '0' END				  AS transferredchat
           		FROM 	tb_ChatDurationHistory  SDH       
           		JOIN	tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
           		AND 	SH.domainId	= p_domainId
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
                 END IF; 
                 IF p_columnname = 'Abondedchats' 
                 THEN
 				SELECT DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,ifnull(sum(CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	end),0)								AS abondedchats
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
           		AND 	domainId	= p_domainId
 			 	AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 			 	AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
                 END IF; 
 
 END IF;
     IF p_datetype = 3 then
              IF p_columnName = 'Received Chats'   
                 THEN
           		SELECT 	DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,COUNT(1) 
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
                 AND IsInBound = 1
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL))
 				GROUP BY CAST(FROM_UNIXTIME(sessionStartTime/1000)as date)
 				ORDER BY CAST(FROM_UNIXTIME(sessionStartTime/1000)as date) ASC;
 				END IF; 
 				IF p_columnName = 'Responded Chats'
 				THEN
 				SELECT 	DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,CASE WHEN (repliedDate - createdAt) IS NOT NULL THEN (repliedDate - createdAt) ELSE '0' END AS  RespondedChats
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.domainId	= p_domainId
                 AND SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
 				 AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				 AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
                 END IF;
                 IF p_columnName = 'Missedchats'
                 THEN
                 SELECT DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,ifnull(sum(CASE WHEN CallBackStatus=1 THEN 1 ELSE 0 END),0) MISSEDCHAT
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.domainId	= p_domainId AND SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp              
 			 	AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
				END IF;
                 IF p_columnname = 'Transferredchat'
                 THEN
 				SELECT   DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,CASE WHEN (SDH.transferredTime) IS NOT NULL THEN (SDH.transferredTime) ELSE '0' END				  AS transferredchat
           		FROM 	tb_ChatDurationHistory  SDH       
           		JOIN	tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
           		AND 	SH.domainId	= p_domainId
 				AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 				AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
				END IF; 
                 IF p_columnname = 'Abondedchats' 
                 THEN
 				SELECT DATE_FORMAT(FROM_UNIXTIME(sessionStartTime/1000), "%H:%i") as time_range ,ifnull(sum(CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	end),0)								AS abondedchats
           		FROM 	tb_ChatDurationHistory  SDH  JOIN
           				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
           		WHERE 	SH.sessionStartTime BETWEEN v_startTmp AND v_endTmp
           		AND 	domainId	= p_domainId
 			 	AND CAST(FROM_UNIXTIME(sessionStartTime/1000) AS DATE) BETWEEN v_startTmp AND v_endTmp
 			 	AND (IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND SDH.agentId IS NOT NULL));
				END IF; 
 
 END IF;
     
 END ;;
