CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_InsertGetCustomerContact`(
    	p_domainId 		INT,
    	p_ChannelType	VARCHAR(20), 
    	p_ChannelValue	VARCHAR(150))
BEGIN
    	DECLARE v_coid 				INT;
    	DECLARE v_phoneNumber 		LONGTEXT;
    	DECLARE v_email 			LONGTEXT;
    	DECLARE v_facebook 			VARCHAR(150);
    	DECLARE v_instagram 		VARCHAR(150);
    	DECLARE v_twitter 			VARCHAR(150);
    	DECLARE v_curdate			DATETIME;
      DECLARE v_firstName			VARCHAR(150);
        	  
    	SET v_curdate = NOW();
   	
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
     	IF p_ChannelType IN ('Call','Sms','Whatsapp')
     	THEN        
     		SET v_phoneNumber = p_ChannelValue;
     
			SELECT  coid,firstName INTO v_coid,v_firstName
			FROM 	customer_contact
			WHERE 	domainId			= p_domainId
			AND 	(primaryPhoneNumber collate utf8mb4_0900_ai_ci = p_ChannelValue AND IFNULL(firstName,'') <> '')
			LIMIT 1;     
            
		IF v_coid IS NULL
		THEN
			SELECT  coid,firstName INTO v_coid,v_firstName
			FROM 	customer_contact
			WHERE 	domainId			= p_domainId
			AND 	(primaryPhoneNumber collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_ChannelValue,'%')
			AND IFNULL(firstName,'') <> '')
			LIMIT 1;
				IF v_coid IS NULL
				THEN
					SELECT  coid,firstName INTO v_coid,v_firstName
					FROM 	customer_contact
					WHERE 	domainId			= p_domainId
					
					AND 	(primaryPhoneNumber collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_ChannelValue,'%') OR ( p_ChannelValue collate utf8mb4_0900_ai_ci LIKE concat('%',primaryPhoneNumber,'%') AND ifnull(primaryPhoneNumber,'') <> ''))
					LIMIT 1;   
				END IF;
		END IF;
            
			IF	(v_coid IS NULL or ifnull(v_firstName,'')='')
			THEN
				SELECT coid INTO v_coid
				FROM 	customer_contact 
				WHERE domainId 	= p_domainId 
				AND 	(	phoneNumber	collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_ChannelValue,'%')  OR
						p_ChannelValue	collate utf8mb4_0900_ai_ci LIKE CONCAT('%',phoneNumber)
					)
				AND 	firstName is not null
				ORDER BY coid DESC LIMIT 1; 
			END IF; 
		        
     	ELSEIF p_ChannelType = 'Email' 
     	THEN
     		SET v_email = p_ChannelValue;	
     
     		SELECT  coid INTO v_coid
     		FROM 	customer_contact
     		WHERE 	domainId		= p_domainId
     		AND 	primaryEmail collate utf8mb4_0900_ai_ci	LIKE p_ChannelValue LIMIT 1;     
             
             IF v_coid IS NULL
             THEN
     			SELECT 	coid INTO v_coid
                 FROM 	customer_contact 
                 WHERE domainId 	= p_domainId 
                 AND 	email collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_ChannelValue,'%')              
                 ORDER BY coid DESC LIMIT 1; 
             END IF; 
     	ELSEIF p_ChannelType = 'Facebook' 
     	THEN
     		SET v_facebook = p_ChannelValue;	
     
     		SELECT  coid INTO v_coid
     		FROM 	customer_contact
     		WHERE 	domainId	= p_domainId
     		AND 	facebook collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_ChannelValue,'%');           	
     	ELSEIF p_ChannelType = 'Instagram' 
     	THEN
     		SET v_instagram = p_ChannelValue;	
     
     		SELECT  coid INTO v_coid
     		FROM 	customer_contact
     		WHERE 	domainId	= p_domainId
     		AND 	instagram collate utf8mb4_0900_ai_ci LIKE CONCAT('%',p_ChannelValue,'%');           	      
     	END IF;     
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
                  
     	 IF v_coid IS NULL
     	 THEN  
				INSERT INTO customer_contact 
     		(	firstName,lastName,primaryPhoneNumber, phoneNumber, 
     			primaryEmail,email, tags,facebook, 
     			instagram, twitter, domainId, 
     			createdAt, updatedAt, Source
     		)
     		VALUES 
     		(	'','',v_phoneNumber, '[]',
     			v_email,'[]', '[]',v_facebook,
     			v_instagram, v_twitter, p_domainId, 
     			v_curdate, v_curdate, 'API'
     		);     			
     		
     		SET v_coid = last_insert_id();   
     	END IF; 
                  
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   	SELECT 	coid, firstName, lastName
    			, IF(IFNULL(a.primaryPhoneNumber,'')='',a.phoneNumber, JSON_ARRAY_INSERT(a.phoneNumber,'$[0]',a.primaryPhoneNumber))	phoneNumber				
    			, IF(IFNULL(a.primaryEmail,'')='',a.email,JSON_ARRAY_INSERT(a.email,'$[0]',a.primaryEmail))							email  
    			  , accountNumber, tags,
    				location, address, country, state, city, postalCode,
    				facebook, instagram, twitter, voiceBiometric,
    				domainId, mergeCustomer, blockCustomer, doNotDisturb,
    				blockCustomerReq, doNotDisturbReq, type,currentCustomerNumber,
    				customerType,timeZone,cookiesId
    	  FROM 		customer_contact a
    	  WHERE 	coid = v_coid
    	  AND 		JSON_VALID(phoneNumber) = 1
    	  AND 		JSON_VALID(email) 		= 1;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_InsertOrUpdateChatIntent` */;
