CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_InsertOrUpdateChatIntent`(
    IN p_IntentName     VARCHAR(150),
    IN p_IntentCount    INT,
    IN p_domainId       INT,
    IN p_ChatFlowId     INT,
    IN p_ChatHistoryId  BIGINT
)
BEGIN
    DECLARE errcode    INT DEFAULT 0;
    DECLARE errmsg     VARCHAR(250) DEFAULT 'Operation completed successfully';
    DECLARE v_curdate  DATETIME;
    DECLARE v_IntentName  VARCHAR(250);
    DECLARE v_domainId   INT;
    DECLARE v_ChatFlowId INT;

    SET v_curdate = NOW();


    BEGIN
        ROLLBACK;
        SET errcode = -1;
        SET errmsg = 'Error occurred while updating/inserting data';
    END;

    START TRANSACTION;

    IF EXISTS (SELECT 1 FROM tb_ChatIntent WHERE domainId = p_domainId AND IntentName = p_IntentName AND ChatFlowId = p_ChatFlowId LIMIT 1) 
    THEN
        UPDATE tb_ChatIntent
        SET
            IntentName = p_IntentName,
            IntentCount = 1 + IntentCount,
            domainId = p_domainId,
            ChatHistoryId = p_ChatHistoryId,
            ChatFlowId = p_ChatFlowId,
            updatedAt = v_curdate
        WHERE IntentName = p_IntentName
          AND domainId = p_domainId
          AND ChatFlowId = p_ChatFlowId;
      

        IF ROW_COUNT() > 0 THEN
            SET errcode = 0;
            SET errmsg = 'Successfully updated';
            COMMIT;
        ELSE
            ROLLBACK;
            SET errcode = -1;
            SET errmsg = 'Update failed, no rows affected';
        END IF;

    ELSE

        INSERT INTO tb_ChatIntent (
            IntentName, IntentCount, domainId, ChatHistoryId, ChatFlowId, createdAt, updatedAt
        ) VALUES (
            p_IntentName, p_IntentCount, p_domainId, p_ChatHistoryId, p_ChatFlowId, v_curdate, v_curdate
        );

        IF ROW_COUNT() > 0 THEN
            SET errcode = 0;
            SET errmsg = 'Successfully inserted';
            COMMIT;
        ELSE
            ROLLBACK;
            SET errcode = -1;
            SET errmsg = 'Insert failed, no rows affected';
        END IF;

    END IF;

    SELECT errcode AS errorcode, errmsg AS errormessage;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
