CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_InsertOrUpdateFacebookConfiguration`(
    p_domainId 			INT,
    p_appId 			VARCHAR(50),
    p_appSecret 		VARCHAR(50),
    p_whatsappNumber 	VARCHAR(50),
    p_whatsappId 		VARCHAR(50),
    p_authToken 		TEXT,
    p_wabaId 			VARCHAR(50),
    p_whatsappToken 	TEXT,
    p_sourceType 		VARCHAR(50),
    p_phoneNumberId		VARCHAR(200),
    p_businessId		VARCHAR(200)
    
)
BEGIN
    DECLARE v_curDate DATETIME DEFAULT NOW();
    DECLARE v_errCode INT DEFAULT -1;
    DECLARE v_errMsg VARCHAR(150) DEFAULT 'Error: Operation failed';

    
    IF EXISTS (
        SELECT 1 
        FROM tb_FacebookClientConfiguration 
        WHERE domainId = p_domainId
    ) THEN

        UPDATE tb_FacebookClientConfiguration
        SET appId 			= p_appId,
            appSecret 		= p_appSecret,
            whatsappNumber 	= p_whatsappNumber,
            whatsappId 		= p_whatsappId,
            userAccessToken = p_authToken,
            sourceType 		= IFNULL(p_sourceType,sourceType),
            whatsappToken 	= IFNULL(p_whatsappToken,whatsappToken),
            updatedDate 	= v_curDate,
            wabaId 			= p_wabaId,
			businessId 		= p_businessId,
            phoneNumberId 	= p_phoneNumberId
        WHERE domainId = p_domainId;

        SET v_errCode = 0;
        SET v_errMsg = 'Updated successfully';

    ELSE

        INSERT INTO tb_FacebookClientConfiguration (domainId, appId, appSecret, whatsappNumber, whatsappId, userAccessToken, updatedDate, wabaId, whatsappToken, sourceType , businessId, phoneNumberId)
        VALUES ( p_domainId, p_appId, p_appSecret, p_whatsappNumber, p_whatsappId, p_authToken, v_curDate, p_wabaId, p_whatsappToken, p_sourceType ,p_businessId , p_phoneNumberId);

        SET v_errCode = 0;
        SET v_errMsg = 'Inserted successfully';
    END IF;

    SELECT v_errCode AS errCode, v_errMsg AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
