CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_InsertScope`(	p_scopeTitle	VARCHAR(200)
	,p_scope		VARCHAR(250)
)
BEGIN
	DECLARE v_scopeTitleId	INT;
    DECLARE v_scopeId		INT;
    DECLARE v_curDate		DATETIME DEFAULT NOW();
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    SELECT 	ST.scopeTitleId, S.scopeId
    INTO 	v_scopeTitleId, v_scopeId
    FROM 	tb_scopeTitle	ST
    LEFT JOIN 	tb_scope 	S	ON 	ST.scopeTitleId	= S.scopeTitleId
								AND S.scope			= p_scope
    WHERE 	scopeTitle = p_scopeTitle;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    IF v_scopeTitleId IS NULL
    THEN
		SELECT 	MAX(scopeTitleId)
        INTO 	v_scopeTitleId
        FROM 	tb_scopeTitle;
        
        SET v_scopeTitleId = IFNULL(v_scopeTitleId,0) + 1;
        
		INSERT INTO tb_scopeTitle
        (	scopeTitleId
			,scopeTitle
            ,createdAt
            ,updatedAt
        )
        VALUES
        (	v_scopeTitleId
			,p_scopeTitle
            ,v_curDate
            ,v_curDate
        );
    END IF;  
    
    IF v_scopeId IS NULL
    THEN
		SELECT 	MAX(scopeId)
        INTO 	v_scopeId
        FROM 	tb_scope;
        
        SET v_scopeId = IFNULL(v_scopeId,0) + 1;
        
        INSERT INTO tb_scope
        (	scopeId
			,scopeTitleId
            ,scope
            ,createdAt
            ,updatedAt
        )
        VALUES
        (	v_scopeId
			,v_scopeTitleId
            ,p_scope
            ,v_curDate
            ,v_curDate
		);    
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
