CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_insertUpdateCustomerSatisfactionRatingDesign`(
   p_caption								TEXT
   ,p_domainId							INT
   ,p_ratingDesignType					TINYINT	
   ,p_labelRatingType					TINYINT
   ,p_followUpQuestion					TINYINT
   ,p_thanksNote							TEXT
   ,p_dontDisturbType					TINYINT
   ,p_dontDistrubTime					SMALLINT
   ,p_additionalQuestionType				TINYINT
   ,p_additionalQuestions				JSON
   ,p_isVoice							TINYINT 
   ,p_callFlows							VARCHAR(2000)
   ,p_minimumDurationType				TINYINT
   ,p_minimumDuration					SMALLINT
   ,p_isWebWidget						TINYINT 
   ,p_Widgets							VARCHAR(2000)
   ,p_isSms								TINYINT
   ,p_smsNumbers							VARCHAR(2000)
   ,p_smsNumberSend						VARCHAR(30)
   ,p_isSendSmsFromSameNumber			TINYINT
   ,p_smsMessage							JSON
   ,p_isEmail							TINYINT
   ,p_emails								VARCHAR(2000) 
   ,p_emailIdSend 						VARCHAR(200)
   ,p_isSendEmailFromSameEmail			TINYINT
   ,p_emailSubject						VARCHAR(2000)
   ,p_emailMessage						JSON
   ,p_isWhatsApp							TINYINT 
   ,p_whatsAppChatFlows					VARCHAR(2000)
   ,p_isFacebook							TINYINT
   ,p_facebookChatFlows					VARCHAR(2000)
   ,p_isInstagram						TINYINT
   ,p_instagramChatFlows					VARCHAR(2000)
   ,p_isVideo							TINYINT
   )
BEGIN
       DECLARE v_domainId		INT;
       DECLARE v_curDate		DATETIME 		DEFAULT NOW();	
       DECLARE v_errCode		TINYINT			DEFAULT -1;
       DECLARE v_errDesc		VARCHAR(200) 	DEFAULT 'Add/Update Customer Satisfaction Rating failed';
       
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
       SELECT	domainId INTO v_domainId
       FROM 		tb_ccaas_customerSatisfactionRatingDesign
       WHERE 	domainId	= p_domainId;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       
       IF v_domainId IS NULL
       THEN
   		INSERT INTO tb_ccaas_customerSatisfactionRatingDesign(
           caption											
           ,domainId							
           ,ratingDesignType
           ,labelRatingType
           ,followUpQuestion					
           ,thanksNote							
           ,dontDisturbType					
           ,dontDistrubTime					
           ,additionalQuestionType				
           ,additionalQuestions				
           ,isVoice							
           ,callFlows							
           ,minimumDurationType				
           ,minimumDuration					
           ,isWebWidget						
           ,Widgets							
           ,isSms								
           ,smsNumbers	
           ,smsNumberSend
           ,isSendSmsFromSameNumber			
           ,smsMessage							
           ,isEmail							
           ,emails	
           ,emailIdSend
           ,isSendEmailFromSameEmail			
           ,emailSubject						
           ,emailMessage						
           ,isWhatsApp							
           ,whatsAppChatFlows					
           ,isFacebook							
           ,facebookChatFlows					
           ,isInstagram						
           ,instagramChatFlows					
           ,isVideo							
           ,createdDate						
           ,updatedDate						
   		)
           VALUES(
   		 p_caption							
           ,p_domainId							
           ,p_ratingDesignType		
           ,p_labelRatingType
           ,p_followUpQuestion					
           ,p_thanksNote						
           ,p_dontDisturbType					
           ,p_dontDistrubTime					
           ,p_additionalQuestionType			
           ,p_additionalQuestions				
           ,p_isVoice							
           ,p_callFlows						
           ,p_minimumDurationType				
           ,p_minimumDuration					
           ,p_isWebWidget						
           ,p_Widgets							
           ,p_isSms							
           ,p_smsNumbers			
           ,p_smsNumberSend
           ,p_isSendSmsFromSameNumber			
           ,p_smsMessage						
           ,p_isEmail							
           ,p_emails				
           ,p_emailIdSend
           ,p_isSendEmailFromSameEmail		
           ,p_emailSubject						
           ,p_emailMessage						
           ,p_isWhatsApp						
           ,p_whatsAppChatFlows				
           ,p_isFacebook						
           ,p_facebookChatFlows				
           ,p_isInstagram						
           ,p_instagramChatFlows				
           ,p_isVideo							
           ,v_curDate
           ,v_curDate	
           );
           
           SET v_errCode	= 1
           ,   v_errDesc	= 'Added Customer Satisfaction Rating successfully';        
   	ELSE
   		UPDATE 	tb_ccaas_customerSatisfactionRatingDesign
           SET 	caption								= p_caption								 	                
                   ,ratingDesignType					= p_ratingDesignType												
                   ,followUpQuestion					= p_followUpQuestion							
                   ,thanksNote						= p_thanksNote									
                   ,dontDisturbType					= p_dontDisturbType							
                   ,dontDistrubTime					= p_dontDistrubTime							
                   ,additionalQuestionType			= p_additionalQuestionType					
                   ,additionalQuestions				= p_additionalQuestions						
                   ,isVoice							= p_isVoice									
                   ,callFlows							= p_callFlows								
                   ,minimumDurationType				= p_minimumDurationType						
                   ,minimumDuration					= p_minimumDuration							
                   ,isWebWidget						= p_isWebWidget								
                   ,Widgets							= p_Widgets									
                   ,isSms								= p_isSms									
                   ,smsNumbers						= p_smsNumbers		
                   ,smsNumberSend						= p_smsNumberSend
                   ,isSendSmsFromSameNumber			= p_isSendSmsFromSameNumber					
                   ,smsMessage						= p_smsMessage								
                   ,isEmail							= p_isEmail									
                   ,emails							= p_emails									
                   ,emailIdSend						= p_emailIdSend
                   ,isSendEmailFromSameEmail			= p_isSendEmailFromSameEmail			
                   ,emailSubject						= p_emailSubject							
                   ,emailMessage						= p_emailMessage								
                   ,isWhatsApp						= p_isWhatsApp									
                   ,whatsAppChatFlows					= p_whatsAppChatFlows						
                   ,isFacebook						= p_isFacebook								
                   ,facebookChatFlows					= p_facebookChatFlows						
                   ,isInstagram						= p_isInstagram								
                   ,instagramChatFlows				= p_instagramChatFlows						
                   ,isVideo							= p_isVideo									                						
                   ,updatedDate						= v_curDate
                   ,labelRatingType					= p_labelRatingType
   		WHERE 	domainId 							= v_domainId;
           
           SET v_errCode	= 2
           ,   v_errDesc	= 'Updated Customer Satisfaction Rating successfully';
       END IF;	
   	
   	SELECT v_errCode AS errCode, v_errDesc AS errDesc;
   END ;;
