CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_InsertUpdateVisitorInsight`( 
  p_visitorId                      	INT,
  p_domainId    					INT ,
  p_coid  		           		    INT,
  p_sessionStartTime 	            BIGINT,
  p_sessionEndTime		        	BIGINT,
  p_location  			        	VARCHAR(250),
  p_device 				        	VARCHAR(250),
  p_ipAddress			        	VARCHAR(250),
  p_browser				        	VARCHAR(250),
  p_language		                VARCHAR(250))
BEGIN
  
			DECLARE v_errcode 						INT;
            DECLARE v_errmsg 						VARCHAR(250);
			DECLARE v_CurDate						DATETIME;
           DECLARE v_visitorId     					INT;
           
           SET v_CurDate = NOW();
  
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
         SELECT visitorId INTO v_visitorId
         FROM tb_VisitorInsightDetails
         WHERE domainId 		= p_domainId
		 AND visitorId 			= p_visitorId;
     
  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  
  
  IF v_visitorId IS NULL THEN
     
             INSERT INTO tb_VisitorInsightDetails
             (
             domainId  ,  	
             coid , 	
             sessionStartTime,
             sessionEndTime,	
             location,  		
             device, 			
             ipAddress,		
             browser,			
             `language`,		
             createdAt,       
             updatedAt       )
             
             values(
            p_domainId,    		 
            p_coid,  		
            p_sessionStartTime, 	
            p_sessionEndTime,	
            p_location,  		
            p_device, 			
            p_ipAddress,			
            p_browser,			
            p_language,		
            v_CurDate, 
            v_CurDate);
            
              SET v_visitorId = LAST_INSERT_ID();
             SET v_errcode = 0;
             SET v_errmsg = 'Configuration Inserted Successfully';
         ELSE         
            
            UPDATE tb_VisitorInsightDetails
             SET 	            
				 domainId    	          	=  IFNULL(p_domainId,domainId),    	
				 coid  	      				=  IFNULL(p_coid,coid) , 	
				 sessionStartTime       	=  IFNULL(p_sessionStartTime,sessionStartTime),
				 sessionEndTime	      		=  IFNULL(p_sessionEndTime,sessionEndTime),	
				 location  		      		=  IFNULL(p_location,location),  		
				 device 			      	=  IFNULL(p_device, device),		
				 ipAddress		      		=  IFNULL(p_ipAddress,ipAddress),		
				 browser			      	=  IFNULL(p_browser,browser),			
				 `language`		     		=  IFNULL(p_language,`language`),
				 updatedAt              	= v_CurDate
			WHERE visitorId    			= v_visitorId;

             SET v_errcode = 0;
             SET v_errmsg = 'Configuration Updated Successfully';
         END IF;
     
         SELECT v_visitorId as visitorId, v_errcode AS errorcode, v_errmsg AS errormessage;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
