/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Instagram_agent_performances_analysis_metrics_filter`(  
            p_startTmpstmp   BIGINT,
            p_endTmpstmp 	BIGINT,
            p_domainId 		INT,    	
            p_agentId		VARCHAR(250),		
            p_offset 		INT,
            p_Limit 		INT	
                     )
BEGIN
                 
 		DECLARE v_offset 								INT;	  	
		DECLARE v_CurrentStartTmpstmp 					BIGINT;
		DECLARE v_CurrentEndTmpstmp 					BIGINT;
						
 		DECLARE v_PrevStartTmpstmp 		    			BIGINT;
		DECLARE v_PrevEndTmpstmp 						BIGINT; 
 		DECLARE v_TmpstmpInterval						BIGINT;	
          		
   		DECLARE v_PrevAverageResponseCount				INT;	
   		DECLARE v_CurrentAverageResponseCount			INT;	        
 		DECLARE v_DiffAverageResponsePercent    		INT;
					
		DECLARE v_PrevAverageHandledCount				INT;	
   		DECLARE v_CurrentAverageHandledCount			INT;
   		DECLARE v_DiffAverageHandledPercent				INT;  	    
						
   		DECLARE v_PrevMaximumHandledCount				INT;	
   		DECLARE v_CurrentMaximumHandledCount			INT;	        
 		DECLARE v_DiffMaximumHandledTimePercent			INT;    
					
		DECLARE v_PrevTotalACWCount		      			INT;	
   		DECLARE v_CurrentTotalACWCount		  			INT;	        
		DECLARE v_DiffTotalACWTimePercent	  			INT;   
             
 		DECLARE v_PrevAverageQueueWaitingCount		    INT;	
   		DECLARE v_CurrentAverageQueueWaitingCount		INT;	        
 		DECLARE v_DiffAverageQueueWaitingPercent		INT; 
             
         
 		DECLARE v_PrevaverageHoldtCount		        	INT;	
   		DECLARE v_CurrentaverageHoldtCount		    	INT;	        
 		DECLARE v_DiffaverageHoldtPercent		    	INT; 
             
            
		DECLARE v_PrevMaximumQueueWaitingCount		    INT;	
 		DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
		DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
         
 		DECLARE v_PrevfirstChatResolutionCount		    INT;	
 		DECLARE v_CurrentfirstChatResolutionCount		INT;	        
   		DECLARE v_DifffirstChatResolutionPercent		INT;  
                             
		DECLARE v_PreSentimentalScore              		INT;
		DECLARE v_CurrentSentimentalScore          		INT;
		DECLARE v_DiffSentimentalScorePercent      		INT;      
            
  		DECLARE v_PrevAgentIdleTimeCount		      	INT;	
		DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
  		DECLARE v_DifffirsAgentIdleTimePercent	        INT;    
            
		DECLARE v_PreavailableCount                     INT;
		DECLARE v_CurrentavailableCount                 INT;                      
		DECLARE v_PretotalTalkCount                     INT;
		DECLARE v_CurrenttotalTalkCount                 INT;  
 		DECLARE v_CurrentAvailableTime          		INT;
		DECLARE v_TotalTalktime                         BIGINT;
     
     
     
          	SET v_offset =  p_Limit * p_offset; 
            
            	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
            	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
            	
          	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          
          	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
            	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
            	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
                 
                	        
                      	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                      	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                 	
                       
                         		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                     		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                     		(    DispositionId 			INT
                     			,DispositionStatus 		VARCHAR(100)
                     			,DispositionCategory	TINYINT
                     		); 
                             
                     		INSERT INTO temp_AvailableDisposition 
                     		SELECT 	did 			DispositionId
                     			,	dispositionName	DispositionStatus
                     			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                     				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                     				WHEN dispositionName = 'Discarded'     THEN 4
              					    WHEN dispositionName = 'Resolved'      THEN 5
                     				END 			DispositionCategory
                     		FROM 	disposition_status
                     		WHERE 	domainId	= p_domainId;
                      	
                      	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                      	CREATE TEMPORARY TABLE temp_AllagentId
                      	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
                        
                        
							SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                      	    DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
                    	    CREATE TEMPORARY TABLE temp_InstagramHistory AS 	    	
                          	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		            	AS SessionDate
							  , SH.AgentId
 							  ,	U.UserName													                	AS agentName
 							  , SH.IsInBound
 							  , SH.Duration                                                                	    AS callDuration
 							  , NUll                                                                        	AS agentHoldDuration
 							  , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		        		AS Handled		
							  , CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                			AS firstChatResolution      
   							  , SH.SessionStartTime                                                    			AS agentconnecttime
							  ,	SH.SessionEndTime - SH.SessionStartTime	 						       			AS chatHandlingTime          
							  ,	SH.repliedDate - SH.createdAt								    	   			AS responseTime
   							  , SH.Duration												           			    AS Duration						
							  , SH.afterInstagramWorkTime                                       
 							  , SH.SentimentalScore
							  , null                                                                        	AS queueDuration
                        	FROM 	tb_InstagramHistory 			SH    
                         	LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
                        	LEFT JOIN tb_User					U	ON U.UserID				= SH.AgentId
                        	LEFT JOIN temp_agentIDs 			t_A ON U.UserID 			= t_A.agentId       
                        	WHERE 	SH.domainId 		=  p_domainId	
 						     AND 	SH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ;   
                             
						DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc; 
   						CREATE TEMPORARY TABLE temp_InstagramHistory_calc AS 	
   						SELECT 	
   							    t_SH.AgentId
 							  , t_SH.SessionDate
 							  ,t_SH.agentName																              						 		 			AS agentName
  							  ,CASE WHEN SUM(responseTime)/COUNT(1) IS NOT NULL THEN SUM(responseTime)/COUNT(1) ELSE '-' END                     		 			AS averageResponseTime
   							  ,	SUM(t_SH.Handled)					  							                                                 	     			AS averageHandledTime    
  							  ,	MAX(t_SH.Handled) / COUNT(1)						  							                                 		 			AS MaximumHandledTime 
  							  ,CASE WHEN SUM(t_SH.afterInstagramWorkTime)/COUNT(1) IS NOT NULL THEN SUM(t_SH.afterInstagramWorkTime)/COUNT(1) ELSE '-' END  		AS totalACWTime                    
 							  ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						         			AS answeredCall
 							  ,SUM(t_SH.agentHoldDuration)                                                                						         			AS callHoldTime
 							  ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)							                                                 			AS totalTalktime
   							  ,t_SH.firstChatResolution		
   							  ,t_SH.SentimentalScore                                                                                                     			AS CustomerSatisfaction
							  ,t_SH.queueDuration                                                                                                      				AS queueWaitingtime
                            FROM 	temp_InstagramHistory t_SH
                            GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.AgentId, t_SH.firstChatResolution,t_SH.SentimentalScore,t_SH.queueDuration;                             
                             
 	            ALTER TABLE temp_InstagramHistory_calc ADD COLUMN availableTime		INT;              
   		
   				UPDATE 	temp_InstagramHistory_calc	SH_C
                    JOIN 	temp_agentIDs	        t_A		ON 	SH_C.agentId = t_A.agentId        
                    SET 	 
            				availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.timerStatusId = 1 THEN S.stateDuration ELSE 0 END) 
            									FROM 	state_timer S	
                                                WHERE  S.domainId	= p_domainId
                                                AND 	S.startTimestamp	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp );                 
                        
        			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                              
                
				SELECT SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(firstChatResolution),SUM(CustomerSatisfaction)
				INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount, v_CurrentMaximumHandledCount,v_CurrenttotalACWCount,v_CurrentfirstChatResolutionCount,v_CurrentSentimentalScore
				FROM 	temp_InstagramHistory_calc ;                                        
									
				
				SELECT 	SUM(averageResponseTime), SUM(averageHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(firstChatResolution),SUM(CustomerSatisfaction)
				INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount, v_PrevMaximumHandledCount,v_PrevtotalACWCount,v_PrevfirstChatResolutionCount,v_PreSentimentalScore
				FROM 	temp_InstagramHistory_calc ;                     
      
				SELECT sum(totalTalktime),max(queueWaitingtime),sum(queueWaitingtime)
				INTO   v_CurrenttotalTalkCount,v_CurrentMaximumQueueWaitingCount,v_CurrentAverageQueueWaitingCount
				FROM 	temp_InstagramHistory_calc  ;    
				
				SELECT sum(totalTalktime),max(queueWaitingtime),sum(queueWaitingtime)
				INTO   v_PretotalTalkCount,v_PrevMaximumQueueWaitingCount,v_PrevAverageQueueWaitingCount
				FROM 	temp_InstagramHistory_calc  ;                    
                    
                 SELECT * FROM temp_AllagentId;         
         	    SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 THEN NULL ELSE v_PrevAverageResponseCount END;
         	    SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 THEN NULL ELSE v_PrevaverageHandledCount   END;
				SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0     tHEN NULL ELSE v_PreSentimentalScore       END;
                
            	SET  v_DiffAverageResponsePercent  = (v_CurrentaverageResponseCount - v_PrevAverageResponseCount) / v_PrevAverageResponseCount * 100  
					,v_DiffAverageHandledPercent   = (v_CurrentaverageHandledCount - v_PrevaverageHandledCount) / v_PrevaverageHandledCount * 100
        		    ,v_DiffSentimentalScorePercent = (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;       
  			
           	SELECT 	IFNULL(v_CurrentaverageResponseCount,0) 			AS 'CurrentaverageResponseCount',
           			IFNULL(v_DiffAverageResponsePercent,0) 		        AS 'DiffAverageResponsePercent',
           			IFNULL(v_CurrentaverageHandledCount,0) 			    AS 'CurrentAverageHandledCount',
           			IFNULL(v_DiffAverageHandledPercent,0) 				AS 'DiffAverageHandledPercent',
           			IFNULL(v_CurrentSentimentalScore,0) 				AS 'CurrentCustomerSatisfactionCount',
           			IFNULL(v_DiffSentimentalScorePercent,0) 			AS 'DiffCustomerSatisfactionPercent';	                    
                                
                                
				SELECT
				'All Agents'											      																  	AS agentName       
				,0                                                                                                                             	AS AgentIdleTime
				,IFNULL(v_CurrentaverageResponseCount,0)                      																  	AS averageResponseTime
				,IFNULL(v_CurrentaverageHandledCount,0)                       																  	AS averageHandledTime
				,IFNULL(v_CurrentMaximumHandledCount,0)                       																  	AS MaximumHandledTime
				,IFNULL(v_CurrenttotalACWCount,0)                             																  	AS totalACWTime
				,IFNULL(v_CurrentaverageHoldtCount,0)                         																  	AS averageHoldtime      
				,IFNULL(v_CurrentAverageQueueWaitingCount,0)   																				  	AS averageQueueWaitingtime
				,0																				                                              	AS maximumQueueWaitingtime
				,IFNULL((v_TotalTalktime)   /(v_CurrentavailableTime) ,0)                                                                      	AS occupancyrate       
				,IFNULL(v_CurrentfirstChatResolutionCount,0)                  																  	AS firstChatResolution
				,IFNULL(v_CurrentSentimentalScore,0)                          																  	AS CustomerSatisfaction
                UNION ALL
				SELECT 															
				U.UserName 																	                                                   	AS agentName
				,0	
				,SUM(a.averageResponseTime)	
				,SUM(a.averageHandledTime/1000)					                                                                               	AS averageHandledTime
				,SUM(a.MaximumHandledTime)	
				,SUM(a.totalACWTime)	
				,SUM(CASE WHEN (a.callHoldTime/a.answeredCall) IS NOT NULL THEN (a.callHoldTime/a.answeredCall) ELSE '-' END)                  	AS averageHoldtime        
				,sum(a.queueWaitingtime)              	   																	       			   	AS averageQueueWaitingtime          
				,0      	   																		   				   						   	AS maximumQueueWaitingtime   
				
				,sum(a.totalTalktime/a.availableTime)*100											                                           	AS occupancyrate
				,SUM(a.firstChatResolution)                                                                                                    	AS firstChatResolution
				,SUM(a.CustomerSatisfaction)                                                                                                   	AS CustomerSatisfaction
				FROM 	temp_InstagramHistory_calc 	a
				JOIN 	temp_AllagentId				U	ON a.AgentId	= U.UserID	
				WHERE 	SessionDate 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
				GROUP BY U.UserName;  
                END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Instagram_agent_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Instagram_agent_servicelevel_analysis_metrics_filter`(
			p_startTmpstmp 		BIGINT,
			p_endTmpstmp 		BIGINT,
			p_domainId 			INT,
			p_agentId 			TEXT,
			p_offset 			INT,
			p_Limit 		    INT	
		)
sp_return:begin
          
 			DECLARE v_offset 					INT;	  	
 			DECLARE v_CurrentStartTmpstmp 		BIGINT;
 			DECLARE v_CurrentEndTmpstmp 		BIGINT;
 			DECLARE v_PrevStartTmpstmp 			BIGINT;
 			DECLARE v_PrevEndTmpstmp 			BIGINT; 
 			DECLARE v_TmpstmpInterval			BIGINT;	
 			
 			DECLARE  v_CurTotalCount 				INT;        
 			DECLARE  v_PrevTotalCount 			    INT;                    
 			DECLARE  v_DiffTotalPercent 		    INT;     
 			
 			DECLARE  v_CurTotalSLA                  INT; 
 			DECLARE  v_PrevTotalSLA             	INT; 
 			DECLARE  v_DiffTotalSLAPercent      	INT; 
 		
 			DECLARE  v_CurMissedChats                INT; 
 			DECLARE  v_PrevMissedChats               INT;          
           
 			DECLARE  v_CurSL1               		INT; 
 			DECLARE  v_CurSL2               		INT; 
 			DECLARE  v_DiffSL2Percent       		INT;  
 			DECLARE  v_CurSL3               		INT; 
 			DECLARE  v_DiffSL3Percent       		INT;  
 			DECLARE  v_CurSL4               		INT; 
 			DECLARE  v_DiffSL4Percent       		INT;  
 			DECLARE  v_CurSL5               		INT; 
 			DECLARE  v_DiffSL5Percent       		INT;    
 			DECLARE  v_CurSL6               	    INT; 
 			DECLARE  v_DiffSL6Percent       		INT; 
          
 			DECLARE  v_CuransweredSLACount        	INT; 
 			DECLARE  v_PrevansweredSLACount       	INT; 
 			DECLARE  v_DiffansweredSLAPercent     	INT; 
 			
 			DECLARE  v_CurabandonedSLACount       	INT; 
 			DECLARE  v_PrevabandonedSLACount      	INT; 
 			DECLARE  v_DiffabandonedSLAPercent    	INT; 
 			
 			DECLARE  v_CurSLAbreachedCount        	INT; 
 			DECLARE  v_PrevSLAbreachedCount       	INT; 
 			DECLARE  v_DiffSLAbreachedPercent     	INT; 
              
 			DECLARE  v_CurChatTypeCount             INT; 
 			DECLARE  v_PrevChatTypeCount            INT; 
 			DECLARE  v_DiffChatTypePercent          INT;  
 			DECLARE  v_CurSLAAchievedCount          INT;  
              
			SET v_offset =  p_Limit * p_offset; 

			IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
			IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									

			SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;

			SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
			SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
			DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
			CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  

			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);


			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
			CREATE TEMPORARY TABLE temp_AvailableDisposition 
				(    DispositionId 			INT
					,DispositionStatus 		VARCHAR(100)
					,DispositionCategory	TINYINT
				); 
					
			INSERT INTO temp_AvailableDisposition 
			SELECT 	did 			DispositionId
				,	dispositionName	DispositionStatus
				,	CASE WHEN dispositionName = 'Opened'	THEN 2
					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
					WHEN dispositionName = 'Disconnected'         THEN 4
					WHEN dispositionName = 'Resolved'             THEN 5
					END 			DispositionCategory
			FROM 	disposition_status
			WHERE 	domainId	= p_domainId;          
		  
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
		CREATE TEMPORARY TABLE temp_AllagentId
		SELECT 	UserID,UserName 
		FROM 	tb_User 
		WHERE 	domainId 	= p_domainId; 
						  
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
			CREATE TEMPORARY TABLE temp_InstagramHistory AS 	    	
				SELECT	t_A.UserID                                                                  					AS agentID
				,t_A.UserName													      		   							AS agentName     
				,SH.InstagramHistoryId							
				,SH.sessionStartTime							
				,SH.dialDuration                                                       	   							                 
				,SH.Duration												      	       							 AS Duration
				,SH.IsMissed												      	       							
				,CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END                   							 AS Answered
				,CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END 		           							 AS Abandoned
				 ,CASE WHEN  (FROM_UNIXTIME(SH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END AS  Overdue 
			FROM 	tb_InstagramHistory 		    SH  
			LEFT JOIN 	temp_AllagentId 			t_A 		ON SH.AgentId		    = t_A.UserID  
			LEFT JOIN temp_AvailableDisposition		t_D			ON SH.dispositionId	    = t_D.DispositionId
			WHERE 	SH.domainId 		= p_domainId	
			AND 	SH.IsBot			= 0
			AND 	SH.AgentId IS NOT NULL
			AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
			AND 	(IFNULL(p_agentId,'')='' OR SH.AgentId IN (SELECT agentId FROM temp_agentIDs ));                               
		                  
			 DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc; 
			CREATE TEMPORARY TABLE temp_InstagramHistory_calc AS 	   
			SELECT																							
			a.agentID,
			a.agentName,
			a.InstagramHistoryId,  
			a.sessionStartTime,
			SUM(a.Answered+a.Abandoned)                             													AS ChatType,  
			SUM(a.Duration) 																							AS totalDuration,
			SUM(CASE WHEN dialDuration BETWEEN 0 AND  5 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END)      			AS SL1,
			SUM(CASE WHEN dialDuration BETWEEN 6  AND 10 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END)  				AS SL2,
			SUM(CASE WHEN dialDuration BETWEEN 11 AND 15 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL3,
			SUM(CASE WHEN dialDuration BETWEEN 16 AND 20 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL4,
			SUM(CASE WHEN dialDuration BETWEEN 21 AND 25 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL5,
			SUM(CASE WHEN dialDuration BETWEEN 26 AND 30 AND dialDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL6,
			SUM(CASE WHEN IsMissed = 1 THEN 1 ELSE 0 END) 																AS MissedChats,
			SUM(CASE WHEN a.Overdue = 'Aborted' THEN 1 ELSE 0 END)  													AS Overdue
			FROM temp_InstagramHistory a
			GROUP BY a.agentID,a.agentName,a.InstagramHistoryId,a.sessionStartTime; 

			 DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc1; 
			CREATE TEMPORARY TABLE temp_InstagramHistory_calc1 AS 
			 SELECT
				a.agentID,
				a.agentName,
				a.sessionStartTime,
				SUM(a.ChatType) AS ChatType,
                SUM(a.Overdue) AS Overdue,
				SUM(a.totalDuration) AS totalDuration,
				SUM(a.SL1) AS SL1,
				SUM(a.SL2) AS SL2,
				SUM(a.SL3) AS SL3,
				SUM(a.SL4) AS SL4,
				SUM(a.SL5) AS SL5,
				SUM(a.SL6) AS SL6,
				SUM(CASE WHEN InstagramHistoryId IS NOT NULL THEN 1 ELSE 0 END) 		as TotalSLA,
				SUM(a.MissedChats) AS MissedChats,
				SUM(a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6)                   AS answeredSLA,
				SUM(CASE WHEN (a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6 + a.MissedChats) = 0 THEN 1 ELSE 0 END)                  										AS abandonedSLA,    
                IFNULL((SUM(a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6)/SUM(CASE WHEN InstagramHistoryId IS NOT NULL THEN 1 ELSE 0 END)) * 100,0)						AS AchievedSLA,
				IFNULL((100 - (SUM(a.SL1 + a.SL2 + a.SL3 + a.SL4 + a.SL5 + a.SL6)/SUM(CASE WHEN InstagramHistoryId IS NOT NULL THEN 1 ELSE 0 END)) * 100),0)                AS SLAbreached							                                 
		   FROM temp_InstagramHistory_calc a  
		   GROUP BY a.agentID,a.agentName,a.sessionStartTime;
		        
		 SELECT  SUM(TotalSLA),	SUM(answeredSLA), SUM(MissedChats) ,sum(ChatType)              														                     				 
		INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats ,v_CurChatTypeCount                           														                      					
		FROM 	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
	   
		SELECT 	SUM(TotalSLA),	SUM(answeredSLA), SUM(MissedChats) ,sum(ChatType)                       																								 
		INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats ,v_PrevChatTypeCount                                 														 										
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;                 
		  
		SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
		INTO    v_CurSL1 ,v_CurSL2 ,v_CurSL3,v_CurSL4,v_CurSL5, v_CurSL6 
		FROM 	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;         
		  
		SELECT 	SUM(IFNULL(answeredSLA, 0))
		INTO 	v_PrevansweredSLACount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
	
		SELECT 	SUM(IFNULL(answeredSLA, 0))
		INTO 	v_CuransweredSLACount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
	
		SELECT 	SUM(IFNULL(abandonedSLA, 0))
		INTO 	v_PrevabandonedSLACount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
	
		SELECT 	SUM(IFNULL(abandonedSLA, 0))
		INTO 	v_CurabandonedSLACount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;             
		  
		SELECT 	SUM(IFNULL(SLAbreached, 0))
		INTO 	v_PrevSLAbreachedCount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
	
		SELECT 	SUM(IFNULL(SLAbreached, 0))
		INTO 	v_CurSLAbreachedCount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;      
        
        SELECT 	SUM(IFNULL(AchievedSLA, 0))
		INTO 	v_CurSLAAchievedCount 
		FROM	temp_InstagramHistory_calc1
		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
             
 		SET v_PrevTotalCount       	= CASE WHEN v_PrevTotalCount        = 0  THEN NULL ELSE     v_PrevTotalCount        END; 
  		SET v_PrevansweredSLACount 	= CASE WHEN v_PrevansweredSLACount  = 0  THEN NULL ELSE     v_PrevansweredSLACount  END;
   		SET v_PrevabandonedSLACount	= CASE WHEN v_PrevabandonedSLACount = 0  THEN NULL ELSE     v_PrevabandonedSLACount END;
  		SET v_PrevSLAbreachedCount 	= CASE WHEN v_PrevSLAbreachedCount  = 0  THEN NULL ELSE     v_PrevSLAbreachedCount  END;
     
 		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
    	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
		,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
		,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
         
         SELECT * FROM temp_AllagentId;
                
 		SELECT 
 		IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
 		IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
 		IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
 		IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
 		IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
 		IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';    
         
          SELECT
   				  'All Agents'												   							AS agentName
 				 ,'Answered'                                                   					        AS ChatType
                  ,IFNULL(v_CurSL1,0)                                          							AS SL1
                  ,IFNULL(v_CurSL2,0)                                          							AS SL2
                  ,IFNULL(v_CurSL3,0)                                          							AS SL3
                  ,IFNULL(v_CurSL4,0)                                          							AS SL4
                  ,IFNULL(v_CurSL5,0)                                          							AS SL5
                  ,IFNULL(v_CurSL6,0)                                          							AS SL6
                  ,IFNULL(v_CurTotalSLA,0)                                      						AS Total
 				 ,IFNULL(v_CurMissedChats,0)                                   						    AS MissedChats           
				 ,IFNULL(v_CurSLAAchievedCount,0)                                                       AS SLAAchieved
				 ,IFNULL(v_CurSLAbreachedCount,0)                                                       AS SLABreached
                 UNION ALL
           	   SELECT 	  
                    agentName													                                				
					, sum(ChatType) AS ChatType
					, sum(SL1) AS SL1
					, sum(SL2) AS SL2
					, sum(SL3) AS SL3
					, sum(SL4) AS SL4
					, sum(SL5) AS SL5
					, sum(SL6) AS SL6
					, sum(TotalSLA) AS TotalSLA
					, sum(MissedChats) AS MissedChats
					, IFNULL((SUM(answeredSLA)/SUM(TotalSLA)) * 100,0)       	AS SLAachieved
                    , IFNULL((100 - (SUM(answeredSLA)/SUM(TotalSLA)) * 100),0)  AS SLAbreached
			FROM temp_InstagramHistory_calc1 
			WHERE 	sessionStartTime    	   BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
			GROUP BY agentName;    

 		SELECT CONCAT('agentName', 'ChatType', 'SL1', 'SL2', 'SL3', 'SL4', 'SL5', 'SL6', 'Total', 'MissedChats', 'SLAAchieved', 'SLAbreached') AS  columnName;   
           
            END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
