DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Instragram_Agent_ACW_Report`(	
   	    p_startTmpstmp 		BIGINT,
     	p_endTmpstmp 		BIGINT,
     	p_timeZone 			VARCHAR(200),
     	p_domainId 			INT,        
     	p_agentIds 			VARCHAR(250),
         p_dispositionIds	VARCHAR(250),        
     	p_offset 			INT,
     	p_Limit 			INT
    )
BEGIN 
     	DECLARE v_offset 		INT;  	
     	DECLARE v_startTmpstmp 	BIGINT;
     	DECLARE v_endTmpstmp 	BIGINT;
         
         
         SET v_offset = p_offset * p_Limit;
       
     	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
     	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
     
 
     	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId BIGINT);
		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
 
     	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
 		CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
       
   	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   	CREATE TEMPORARY TABLE temp_AllagentId
   	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId ;
          
       	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
       	CREATE TEMPORARY TABLE temp_AvailableDisposition 
     	(    DispositionId 			INT
     		,DispositionStatus 		VARCHAR(100)	
     	); 
         
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	INSERT INTO temp_AvailableDisposition     
       	SELECT 	did 			DispositionId
       		,	dispositionName	DispositionStatus 		
       	FROM 	disposition_status
       	WHERE 	domainId	= p_domainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
         DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	CREATE TEMPORARY TABLE temp_InstagramHistory AS 	
     	SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000) AS DATE))*1000		as SessionDate
                 ,	U.UserName							        as agentName
                 ,	SH.sessionEndTime-SH.sessionStartTime 	 	as instagramHandlingTime                      
                 ,	SH.afterInstagramWorkTime			        as ACW
 			    ,  SH.IsBot
       	FROM 	    tb_InstagramHistory 			SH
    	LEFT JOIN 	tb_InstagramMessage	            SDH	ON SH.InstagramHistoryId = SDH.InstagramHistoryId
 	    LEFT JOIN 	temp_AvailableDisposition	   t_D	ON SH.dispositionId		= t_D.DispositionId
    	LEFT JOIN 	temp_AllagentId				    U	ON U.UserID				= SH.AgentId
    	LEFT JOIN 	temp_agentId 				    t_A ON U.UserID 			= t_A.agentId       
    	WHERE 	SH.domainId 		= p_domainId 		
    	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
    	AND		SH.IsInBound		= 1	
    	AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL))
 	    AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
 
     	DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_1;   	
       	CREATE TEMPORARY TABLE temp_InstagramHistory_1 AS 	
         SELECT SessionDate						as `date`
    		    , 	CASE WHEN agentName is NOT null then agentName else  'bot'  end as agentName
             ,	COUNT(1)							as totalInteraction
             ,	SUM(instagramHandlingTime)			as totalActiveinstagramTime
             ,	SUM(instagramHandlingTime)/COUNT(1)	as avgActiveinstagramTime
             ,	SUM(ACW)							as totalACW
           
         FROM 	temp_InstagramHistory
         GROUP BY SessionDate, agentName ;
 
         
         	SELECT * from temp_AllagentId;
   		SELECT * from temp_AvailableDisposition;
   
         
         SELECT COUNT(1) as totalCount
         FROM 	temp_InstagramHistory_1;
         
         SELECT `date`                           as `dateTime`
    		   , 	agentName
             ,	totalInteraction                AS totalAnsweredChats
             ,	totalActiveinstagramTime        AS totalActiveChatTime
             ,	avgActiveinstagramTime          AS averageActiveChattime
         
             ,	totalACW                         
         FROM 	temp_InstagramHistory_1
         LIMIT  v_offset, p_Limit;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Instragram_Agent_Chat_Report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Instragram_Agent_Chat_Report`(  
  	 p_startTmpstmp 	BIGINT,
     p_endTmpstmp 	    BIGINT,
     p_timeZone 		VARCHAR(200),
     p_domainId 		INT,
     p_agentIDs 		VARCHAR(250),
     p_dispositionIds	VARCHAR(250),
     p_Offset			INT,
     p_Limit			INT  
  )
BEGIN
   	DECLARE v_startTmpstmp 	BIGINT;
   	DECLARE v_endTmpstmp 	BIGINT;
   	DECLARE v_Total_count 	INT;
   	DECLARE v_offset		INT;    
            
   	SET v_offset =  p_Limit * p_Offset; 
   
   	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +6 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
   	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
       
   	DROP TEMPORARY TABLE IF EXISTS     temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
   	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
 
   	CALL split(p_agentIDs,',');			INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable; 
   	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;

  	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  	CREATE TEMPORARY TABLE temp_AllagentId
  	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3);    
          
  	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
  	CREATE TEMPORARY TABLE temp_AvailableDisposition 
    	(   DispositionId 			INT
    		,DispositionStatus 		VARCHAR(100)
    		,DispositionCategory	TINYINT
    	); 
  	INSERT INTO temp_AvailableDisposition 
  	SELECT 	did 			DispositionId
  		,	dispositionName	DispositionStatus
  		,	CASE WHEN dispositionName = 'Transferred' THEN 1
  				 WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
  				 WHEN dispositionName = 'Discarded' THEN 4
                   ELSE 2
  			END 			DispositionCategory
  	FROM 	disposition_status
  	WHERE 	domainId	= p_domainId;
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
  	CREATE TEMPORARY TABLE temp_InstagramHistory AS 	
    	SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE)) AS SessionDate	
  		  ,	U.UserName			                                      	    AS agentName
  			,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END       AS UnansweredChat
  			,	CASE WHEN t_D.DispositionCategory = 1 THEN 1 ELSE 0 END     AS Transferred  
  			,	CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END     AS Handled
  			,	CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END     AS Discarded
  		    , SH.sessionEndTime-SH.sessionStartTime	 					    AS chatHandlingTime          
  		  ,	SH.repliedDate - SH.createdAt								    AS responseTime
  	FROM 	tb_InstagramHistory 				SH
  	JOIN 	tb_InstagramMessage		            SDH	ON SH.InstagramHistoryId = SDH.InstagramHistoryId 
  	LEFT JOIN temp_AvailableDisposition		    t_D	ON SH.dispositionId		= t_D.DispositionId
  	LEFT JOIN tb_User						    U	ON U.UserID				= SH.AgentId
  	LEFT JOIN temp_agentIDs 					t_A ON U.UserID 			= t_A.agentId       
  	WHERE 	SH.domainId 		= p_domainId 	
   	AND		SH.IsInBound		= 1		
  	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') = '' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL))
	AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_1;
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
  	CREATE TEMPORARY TABLE temp_InstagramHistory_1 AS
  	SELECT
  		t_SH.SessionDate                                      AS `dateTime`,
  		t_SH.agentName,
  		COUNT(1)                                              AS chatReceived,
  		SUM(t_SH.Handled)                                     AS chatHandled,
  		round(SUM(t_SH.chatHandlingTime) / COUNT(1)) / 1000   AS averageActiveChattime,
  		SUM(t_SH.UnansweredChat)                              AS unansweredchat,
  		round((SUM(t_SH.responseTime) / COUNT(1)) / 1000)     AS averageResponsetime
  	FROM
  		temp_InstagramHistory t_SH
  	GROUP BY
  		t_SH.SessionDate, t_SH.agentName
  	ORDER BY 
  		t_SH.SessionDate DESC;
  
      
  	  SELECT * from temp_AllagentId;
      SELECT * from temp_AvailableDisposition;
      
      SELECT COUNT(1) totalCount
      FROM temp_InstagramHistory_1;
      
      IF ((p_Limit IS NOT NULL) AND (p_Offset IS NOT NULL)) THEN
      
			SELECT 	*
				FROM 	temp_InstagramHistory_1
			LIMIT 	v_offset, p_Limit;
            
		ELSE
			
            SELECT 	*
				FROM 	temp_InstagramHistory_1;
	
        END IF;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Instragram_Profile_Report` */;
