/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_interaction_report_test`(
					p_startTmpstmp 		BIGINT,
					p_endTmpstmp 		BIGINT,
					p_timeZone 			VARCHAR(200),
					p_domainId 			INT,        
					p_queueIds	 		VARCHAR(250),
					p_agentIds 			VARCHAR(250),
					p_direction			VARCHAR(3),
					p_dispositionIds	VARCHAR(250),
					p_Limit 			INT,
					p_offset 			INT
                )
spreturn: BEGIN     
                 
             	DECLARE v_offset 		INT;
             	DECLARE v_Total_Count 	INT; 
             	DECLARE v_startTmpstmp 	BIGINT;
             	DECLARE v_endTmpstmp 	BIGINT;
             	DECLARE v_temp 			INT;
                       
             	SET v_offset = p_Limit * p_offset; 
                 
             	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
             	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  								
               
 			DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
             CREATE TEMPORARY TABLE temp_AllqueueId
             SELECT qid,name as queueName from queue where domainId = p_domainId;
                 
             DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
             CREATE TEMPORARY TABLE temp_AllagentId
             SELECT DISTINCT UserID,UserName AS AgentName FROM tb_User WHERE domainId = p_domainId;
            
   			DROP TEMPORARY TABLE IF EXISTS temp_queueId;	CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
   			DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
            DROP TEMPORARY TABLE IF EXISTS temp_dispId;	CREATE TEMPORARY TABLE temp_dispId(dispId VARCHAR(100));
            
            
   			DROP TEMPORARY TABLE IF EXISTS temp_direction;	CREATE TEMPORARY TABLE temp_direction(directionId 	VARCHAR(3));
   			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
               	CALL split(p_queueIds,','); INSERT INTO temp_queueId(queueId) SELECT Items FROM tt_Split_temptable;
               	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
                CALL split(p_dispositionIds,',');	INSERT INTO temp_dispId(dispId) SELECT Items FROM tt_Split_temptable;
                   
   			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
   			DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
   			CREATE TEMPORARY TABLE temp_AllqueueId
   			SELECT qid,name as queueName FROM queue WHERE domainId = p_domainId;
                  
   			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   			CREATE TEMPORARY TABLE temp_AllagentId          
   			SELECT UserID,UserName from tb_User WHERE domainId = p_domainId ;
                       
     		IF p_direction IS NULL OR p_direction IN ('0,1','1,0')
               THEN
           		INSERT INTO temp_direction 
                   (directionId)
                   VALUES (0),(1);
           	ELSE
           		INSERT INTO temp_direction
                   (directionId)
                   SELECT p_direction;
               END IF;
               
 			  DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
               CREATE TEMPORARY TABLE temp_AlldirectionId
               SELECT directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
       								   WHEN directionId = 1 THEN 'InBound' END AS directionName 
      								   FROM temp_direction ;      
                 INSERT INTO temp_AvailableDisposition 
         		SELECT 	did 			dispositionId
         			,	dispositionName	DispositionStatus
         		FROM 	disposition_status
         		WHERE 	domainId	= p_domainId;  
              
                                       
 				DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
               	CREATE TEMPORARY TABLE tt_temp_sessionHistory as 
        		    SELECT 	case when ifnull(CDH.StartTime,0)=0 then CH.sessionStartTime else CDH.StartTime end as  `dateTime`
  				
        			, 	Q.qid																							AS queueId
        			,	Q.queueName					    																AS queueName             
        			,	U.UserID																						AS agentId
        			,	U.UserName																						AS agentName   
 				,	CH.customerNumber        																	    AS customerNumber           
        			
 				,CASE WHEN trim(CONCAT(CC.firstName, ' ',CC.lastName)) <> ''  THEN CONCAT(CC.firstName, ' ',CC.lastName)	ELSE 'New Customer' END as CustomerName                            
   				,   CASE WHEN CH.IsInBound = 0 THEN 'outbound'  WHEN CH.IsInBound = 1 THEN 'inbound'  END           AS Direction
 				,	CDH.Duration																					AS callDuration
 				,  CH.queueDuration                     															AS QueueWaitTime 
        			, 	DS.dispositionName  			    															AS dispositionStatus
        			,	CH.calledNumber					    															AS agentDetails 
       			,	CDH.afterCallWorkTime			    															AS afterCallWorkTime            
        			,	CDH.StartTime					    															AS agentconnecttime
        			,	CDH.EndTime						    															AS agentDisconnectTime
        		FROM 	tb_CallHistory 					CH                                                   	
        		JOIN 	tb_CallDurationHistory			CDH		ON CH.CallHistoryId = CDH.CallHistoryId			
   			JOIN    customer_contact                CC   	ON CC.domainId 		= CH.domainId
        														AND CC.coid			= CH.CustomerId
        		JOIN 	temp_AllqueueId					Q		ON CDH.QueueId		= Q.qid
   			LEFT JOIN	disposition_status      	DS   	ON DS.domainId 		= CH.domainId
        														AND CDH.dispositionId	= DS.did	
        		LEFT JOIN temp_AllagentId				U		ON U.UserID			= CDH.AgentId
				
				
				
   			LEFT JOIN temp_direction                t_d     ON t_d.directionId   = CH.IsInBound
        		WHERE 	CH.domainId 					= p_domainId 	
        		AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
			
			
            AND		(CDH.dispositionId in (select dispId from temp_dispId) or ifnull(p_dispositionIds,'')='')
            AND		(CDH.AgentId in (select agentId from temp_agentId) or ifnull(p_agentIds,'')='')
            AND		(CDH.QueueId in (select queueId from temp_queueId) or ifnull(p_queueIds,'')='')
            AND		(CH.IsInBound in (select directionId from temp_AlldirectionId) or ifnull(p_direction,'')='')
			
			
			
            ;   		
               
               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
                   
               	DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
               	CREATE TEMPORARY TABLE tt_sessionHistory_calc AS
       				SELECT 	SH.`dateTime`,
                   	SH.queueName, 
       				SH.agentName ,
 					SH.customerNumber,
       				SH.CustomerName,
 					SH.Direction,
 					SUM(SH.callDuration)                           AS callDuration, 
 					SH.QueueWaitTime,
 					SH.dispositionStatus,  
       				SUM(SH.afterCallWorkTime)						AS NoOfAfterCallWorkTime
               	FROM 	tt_temp_sessionHistory SH
               	GROUP BY SH.`dateTime`,SH.queueName,SH.agentName ,SH.customerNumber,SH.CustomerName,SH.Direction,SH.QueueWaitTime,SH.dispositionStatus;
       
                       
       		    SELECT * from temp_AllqueueId;
                 SELECT * from temp_AllagentId;
      			SELECT * FROM temp_AvailableDisposition;
 				SELECT * from temp_AlldirectionId;
               	SELECT 	COUNT(1) v_Total_Count FROM 	tt_sessionHistory_calc a;
                 
               	SELECT 	a.`dateTime`	 																				AS `dateTime`
 					  ,a.queueName 																						AS queueName
       				  ,a.agentName 																						AS agentName
       				  ,a.customerNumber																					AS customerNumber	
                       ,a.customerName 																					AS customerName
                       ,a.Direction																						AS direction
                       ,(a.callDuration/1000)					                                                        AS totalDuration 
                       ,(a.QueueWaitTime/1000)                                                                           AS queueWaitingtime
                       ,a.dispositionStatus																				AS disposition
 					  ,a.NoOfAfterCallWorkTime                                                                       	AS ACWtime
               	FROM 	tt_sessionHistory_calc a
   				ORDER BY a.`dateTime` DESC;
               	
          END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_outbound_call_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_outbound_call_report`(
   	p_startTmpstmp 		BIGINT,
   	p_endTmpstmp 		BIGINT,
   	p_timeZone 			VARCHAR(200),
   	p_domainId 			INT,
   	p_queueId 			TEXT,
   	p_agentId 			TEXT,

	p_Limit 			INT,	   
  	p_offset 			INT
    )
BEGIN 
    		DECLARE v_offset		INT;
    		DECLARE v_count 		INT; 
           DECLARE v_startTmpstmp BIGINT;
   		DECLARE v_endTmpstmp 	BIGINT;
    
    		SET v_offset =  p_Limit * p_offset;
            
   		IF IFNULL(p_startTmpstmp,0) = 0          
        THEN 	   			
        SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000;    		
        ELSE    			SET v_startTmpstmp = p_startTmpstmp;	           
        END IF; 
           
    		IF IFNULL(p_endTmpstmp,0) = 0 	
           THEN 	
   			SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; 
   		ELSE
   			SET v_endTmpstmp = p_endTmpstmp;
   		END IF;  							
          
  	DROP TEMPORARY TABLE IF EXISTS temp_queueId;  		CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
  	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
    DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
    
      CALL split(p_queueId,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
  	CALL split(p_agentId,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
    
  		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
  		CREATE TEMPORARY TABLE temp_AllqueueId
        SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
  		
  		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  		CREATE TEMPORARY TABLE temp_AllagentId
  		select UserID,UserName from tb_User where domainId = p_domainId;  
        
	
                                   
         INSERT INTO temp_AvailableDisposition 
   		SELECT 	did 			dispositionId
   			,	dispositionName	DispositionStatus
   		FROM 	disposition_status
   		WHERE 	domainId	= p_domainId;              
        
        
   		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
   		CREATE TEMPORARY TABLE temp_sessionHistory AS 
   		SELECT 	CH.sessionStartTime
   			, 	CH.customerNumber
               ,	CH.CustomerId
               ,	Q.queueName							queueName
               ,	U.UserName						    agentName
               , 	CH.callDuration
			   ,CASE WHEN trim(CONCAT(c_c.firstName, ' ',c_c.lastName)) <> ''  THEN CONCAT(c_c.firstName, ' ',c_c.lastName)	ELSE 'New Customer' END as customerName 
               , 	CDH.afterCallWorkTime
               , 	DS.dispositionName  			    AS dispositionStatus
   		FROM tb_CallHistory		 		CH 
   		JOIN tb_CallDurationHistory		CDH	ON CH.CallHistoryId = CDH.CallHistoryId
   		JOIN temp_AllqueueId			Q	ON CDH.QueueId		= Q.queueId
   		JOIN temp_AllagentId			U	ON U.UserID			= CDH.AgentId   
       LEFT JOIN customer_contact		   c_c	ON c_c.coid 		= CH.CustomerId  
   LEFT JOIN disposition_status        DS   ON DS.domainId 		= CH.domainId
											AND CDH.dispositionId	= DS.did
   		LEFT JOIN temp_queueId 		t_Q ON Q.queueId	COLLATE utf8mb4_0900_ai_ci		= t_Q.queueId 
   		LEFT JOIN temp_agentId 		t_A ON U.UserId COLLATE utf8mb4_0900_ai_ci	= t_A.agentId  
   		WHERE 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp 
           AND 	CH.IsInBound			= 1
   		AND 	CH.domainId 			= p_domainId 		
   		AND 	(IFNULL(p_queueId,'') ='' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL))
   		AND 	(IFNULL(p_agentId,'') ='' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
   		ORDER BY sessionStartTime DESC LIMIT v_offset, p_limit;	
        
   		SELECT 	count(1) count
   		FROM	temp_sessionHistory;
  		SELECT * from temp_AllqueueId;
  		SELECT * from temp_AllagentId;
  		SELECT * from temp_AvailableDisposition;
          
             
   		SELECT  e.sessionStartTime 						as `date`
   			,	e.customerNumber
		 	,	e.customerName
   	 		,	e.queueName 							as queueName
   		 	,	e.agentName 							as agentName
   		 	,  	e.callDuration 							as callDuration
   			,	e.afterCallWorkTime  					as ACW
   		 	,	e.callDuration  						as totalDuration    
	        ,   e.DispositionStatus
   		FROM  	temp_sessionHistory 		e;

 
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_outbound_call_summary_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_outbound_call_summary_report`(
         	p_startTmpstmp 		BIGINT,
         	p_endTmpstmp 		BIGINT,
         	p_timeZone 			VARCHAR(200),
         	p_domainId 			INT,
         	p_queueId 			TEXT,
         	p_agentId 			TEXT,
 			p_direction			TINYINT,
 			p_Limit 			INT,
 			p_offset 			INT, 
            p_dispositionIds	VARCHAR(250)
          )
sp_return: BEGIN 
  			DECLARE v_offset		 INT;
  			DECLARE v_count 		 INT; 
   			DECLARE v_startTmpstmp   BIGINT;
			DECLARE v_endTmpstmp 	 BIGINT;
          
  			SET v_offset =  p_Limit * p_offset;
                  
			IF IFNULL(p_startTmpstmp,0) = 0   THEN 	   			
				SET v_startTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL +1 DAY))*1000;    		
			ELSE
				SET v_startTmpstmp = p_startTmpstmp;	           
			END IF; 
                 
          		IF IFNULL(p_endTmpstmp,0) = 0 	
                 THEN 	
         			SET v_endTmpstmp 	=  UNIX_TIMESTAMP(NOW())*1000; 
         		ELSE
         			SET v_endTmpstmp = p_endTmpstmp;
         		END IF;  							
                
			DROP TEMPORARY TABLE IF EXISTS temp_queueId;  				CREATE TEMPORARY TABLE temp_queueId(queueId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_agentId;				CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
            DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId VARCHAR(100));
			DROP TEMPORARY TABLE IF EXISTS temp_direction;				CREATE TEMPORARY TABLE temp_direction(directionId 	TINYINT);
			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition; 	CREATE TEMPORARY TABLE temp_AvailableDisposition (dispositionId	INT,DispositionStatus VARCHAR(255));
          
            CALL split(p_queueId,',');			INSERT INTO temp_queueId(queueId)				SELECT Items FROM tt_Split_temptable;
			CALL split(p_agentId,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
            CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) 	SELECT Items FROM tt_Split_temptable;
          
        		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
        		CREATE TEMPORARY TABLE temp_AllqueueId
				SELECT qid AS queueId,`name` AS queueName FROM queue WHERE domainId = p_domainId;
        		
        		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
        		CREATE TEMPORARY TABLE temp_AllagentId
        		select UserID,UserName from tb_User where domainId = p_domainId;  
              
      	IF p_direction IS NULL
               THEN
           		INSERT INTO temp_direction 
                   (directionId)
                   VALUES (0),(1);
           	ELSE
           		INSERT INTO temp_direction
                   (directionId)
                   SELECT p_direction;
               END IF;
                 DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
               CREATE TEMPORARY TABLE temp_AlldirectionId
               select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
       								   WHEN directionId = 1 THEN 'InBound' END AS directionName 
      								   FROM temp_direction ;      
               INSERT INTO temp_AvailableDisposition 
         		SELECT 	did 			dispositionId
         			,	dispositionName	DispositionStatus
         		FROM 	disposition_status
         		WHERE 	domainId	= p_domainId;              
              
              
         		DROP TEMPORARY TABLE IF EXISTS temp_sessionHistory; 
         		CREATE TEMPORARY TABLE temp_sessionHistory AS 
				SELECT 	CH.sessionStartTime
					, 	CH.customerNumber
					,	CH.CustomerId
					,	Q.queueName							queueName
					,	U.UserName						    agentName
					, 	CH.callDuration
					, 	CASE WHEN IFNULL(c_c.firstName,'') = '' THEN 'New Customer' ELSE CONCAT(c_c.firstName,' ' ,c_c.lastName) END 				as customerName
					, 	CDH.afterCallWorkTime
					, 	DS.dispositionName  			    AS disposition
                    ,	CDH.QueueId
                    ,	CDH.AgentId
                    ,	CDH.dispositionId
                    ,	CDH.subject
                    ,	CDH.summary
				FROM tb_CallHistory		 			CH 
				JOIN tb_CallDurationHistory			CDH		ON CH.CallHistoryId = CDH.CallHistoryId
				LEFT JOIN temp_AllqueueId			Q		ON CDH.QueueId		= Q.queueId
				LEFT JOIN temp_AllagentId			U		ON U.UserID			= CDH.AgentId   
				JOIN customer_contact		   		c_c		ON c_c.coid 		= CH.CustomerId  
				LEFT JOIN disposition_status        DS   	ON DS.domainId 		= CH.domainId				AND CDH.dispositionId	= DS.did
				
				
                
				WHERE 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp 
				AND 	CH.IsInBound			= 0
				AND 	CH.domainId 			= p_domainId 	
                AND 	((CDH.QueueId in (select queueId from temp_queueId)) OR  (ifnull(p_queueId,'')=''))
                AND 	((CDH.AgentId in (select agentId from temp_agentId)) OR  (ifnull(p_agentId,'')=''))
                AND 	((CDH.dispositionId in (select dispositionId from temp_dispositionIds)) OR  (ifnull(p_dispositionIds,'')=''))
				
				
                
				ORDER BY sessionStartTime DESC ;
                 
              
         		SELECT 	count(1) count FROM	temp_sessionHistory;
                
        		SELECT * from temp_AllqueueId;
        		SELECT * from temp_AllagentId;
        		SELECT * from temp_AvailableDisposition;
                
         		SELECT  e.sessionStartTime 						as `date`
         			,	e.customerNumber
 					,	e.customerName
         	 		,	e.queueName 							as queueName
         		 	,	e.agentName 							as agentName
         		 	,  	e.callDuration 							as callDuration
         			,	e.afterCallWorkTime  					as ACW
         		 	,	e.callDuration  						as totalDuration    
      	            ,   e.disposition
                    ,	e.summary
                    ,	e.subject
         		FROM  	temp_sessionHistory 		e;
      
       
         end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Outbound_call_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Outbound_call_trendchart`(
   		p_domainId 			INT,
       	p_datetype 			INT,       	
   		p_startDateTime		DATETIME,
   		p_endDateTime		DATETIME,
       	p_columnName    	VARCHAR(200),    
       	p_agentId 			TEXT
       )
SP: BEGIN
  	DECLARE v_startDateTime			DATETIME;
  	DECLARE v_endDateTime			DATETIME;     
  	DECLARE v_datetimeInterval		SMALLINT;    
  	DECLARE v_startDateTimePast		DATETIME;
  	DECLARE v_endDateTimePast		DATETIME;
  	 
  	 DECLARE v_startTimestampPast		BIGINT;
  	 DECLARE v_endTimestampPast		BIGINT;      
  	 DECLARE v_startTimestamp			BIGINT;
  	 DECLARE v_endTimestamp			BIGINT;
  	 DECLARE v_curDate				DATETIME DEFAULT NOW();	
  	 DECLARE v_currentCount			INT;
  	 DECLARE v_pastCount				INT;
       
  	DROP TEMPORARY TABLE IF EXISTS tmp_result;
  	CREATE TEMPORARY TABLE tmp_result(
  		reportAge			VARCHAR(20)
  		,startDateTime		DATETIME
  		,endDateTime		DATETIME
  		,callCount			INT
  	);  
       
       	IF p_datetype = 1 
           THEN 	
       		SET v_startDateTime = CAST(v_curDate AS DATE); 
       		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
       	END IF;
       	IF p_datetype = 2 
           THEN 
       		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
               SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
       	END IF;
       	IF p_datetype = 3 
           THEN 
       		
                 
                 SET v_startDateTime = p_startDateTime;
                 SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                 
     			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                 
         		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                 SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       	IF p_datetype = 4 
           THEN 
       		SET v_startDateTime = p_startDateTime; 
               SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND); 
               
               SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
           
          IF p_agentId IS NOT NULL 
          THEN
      		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(UserID INT);
      		CALL split(p_agentId,','); INSERT INTO temp_agentIds(UserID) SELECT Items FROM tt_Split_temptable;
          ELSE
      		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
             CREATE TEMPORARY TABLE temp_agentIds
  			select  UserID from tb_User where domainId = p_domainId ; 
  		END IF;
           
           DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
           CREATE TEMPORARY TABLE tmp_Disposition
           SELECT did, dispositionName
           FROM 	disposition_status
           WHERE	domainId		= p_domainId
           AND	dispositionName	= 'Caller Disconnected';    
           
           IF p_datetype IN (1,2)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
  			CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH RECURSIVE CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	endDateTime < v_endDateTime
  			)
       		SELECT * FROM CTE_TIMINGS;	
       	ELSEIF p_datetype IN (3,4)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH recursive CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	startDateTime < v_endDateTime
       		)
       		SELECT * FROM CTE_TIMINGS;	
           END IF;  
           
           ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
           
           UPDATE 	tmp_timings
           SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
       		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
               
       	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
           ,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
           ,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
       	 , 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;         
           
  	DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
     	CREATE TEMPORARY TABLE tmp_CallDurationHistory
     	SELECT 	CH.CallHistoryId
     		,	CH.sessionStartTime
     		,	CDH.transferredTypeId
     		,	CDH.dispositionId        
     		,	CDH.Duration
          ,	CDH.UMNStatus
          ,	CDH.IsMissedCall
          ,	CH.IsAbandoned
     	FROM 	tb_CallHistory         CH
     	JOIN 	tb_CallDurationHistory CDH	ON 	CH.CallHistoryId 	= CDH .CallHistoryId     
  	JOIN    temp_agentIds 		   t_A  ON t_A.UserID 		= CDH.agentId  
     	WHERE 	CH.domainId 		= p_domainId
     	AND 	CH.sessionStartTime >= 	v_startTimestampPast 
      AND 	CH.sessionStartTime <	v_endTimestamp
      AND 	 CH.IsInBound 		= 0
     	AND 	CH.IsInBound		= 0;    
      
     	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
  	CREATE TEMPORARY TABLE tmp_CallHistory
  	SELECT 	
  			CDH.CallHistoryId 
  		, 	CDH.sessionStartTime
          ,	CDH.IsAbandoned
  	FROM 	tmp_CallDurationHistory CDH;  
          
          ALTER TABLE tmp_CallHistory ADD transferredTypeId 	INT default 0;
          ALTER TABLE tmp_CallHistory ADD IsAnswered 			INT default 0;
  
          
          CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
          CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);
      
          UPDATE tmp_CallHistory			CH
          JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  
          LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
          SET 	CH.transferredTypeId 	= CASE WHEN CDH.transferredTypeId > 0 	THEN 1 ELSE 0 	END						
      		,	CH.IsAnswered			= CASE WHEN UMNStatus = 1 and Duration > 0  and IsMissedCall = 0 and CH.IsAbandoned = 0 THEN 1 ELSE 0 END;
   
  		IF p_columnName = 'Outbound calls'
          THEN	
  			INSERT INTO tmp_result
      		SELECT 	'Current'																	AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END),0)	AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestamp 	
              AND 	t_T.startTimestamp	<	v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
  			INSERT INTO tmp_result
      		SELECT 	'Past'																		AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END),0)	AS PastcallCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestampPast 	
              AND 	t_T.startTimestamp	<	v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime; 
          ELSEIF p_columnName = 'Answered Calls'
          THEN
  			INSERT INTO tmp_result
      		SELECT 	'Current'			AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	SUM(IsAnswered)		AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestamp 	
              AND 	t_T.startTimestamp	<	v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
  			INSERT INTO tmp_result
      		SELECT 	'Past'				AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	SUM(IsAnswered)		AS PastcallCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestampPast 	
              AND 	t_T.startTimestamp	<	v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
      	ELSEIF p_columnName = 'Abandoned Calls'
          THEN
          INSERT INTO tmp_result
      		SELECT 	'Current'					AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(IsAbandoned),0)	AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestamp 	
              AND 	t_T.startTimestamp	<	v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
  			INSERT INTO tmp_result
      		SELECT 	'Past'					AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(IsAbandoned),0)		AS PastcallCount         
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestampPast 	
              AND 	t_T.startTimestamp	<	v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
      	ELSEIF p_columnName = 'Transferred Calls'
          THEN
          INSERT INTO tmp_result
      		SELECT 	'Current'								AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	ifnull(SUM(CH.transferredTypeId),0)		AS CurrentcallCount 
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestamp 	
              AND 	t_T.startTimestamp	<	v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
  		INSERT INTO tmp_result
      		SELECT 	'Past'										AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.transferredTypeId),0)			AS PastcallCount         
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	>= 	v_startTimestampPast 	
              AND 	t_T.startTimestamp	<	v_endTimestampPast		
      		GROUP BY t_T.startDateTime, t_T.endDateTime;        
          END IF;
          
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Current';    
            
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Past';
          
     	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
     	INTO 	v_currentCount, v_pastCount		
     	FROM 	tmp_result;
         
     SELECT 	
  		  p_columnName    														AS metric
  	 ,   v_currentCount															AS currentTotal
  	 , 	 v_pastCount															AS pastTotal
  	 ,	(v_currentCount - v_pastCount)  										AS totalDifference
  	 ,	IFNULL((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)	    	AS  Percentage;	       
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_call_callBack_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
