/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_queue_call_Outboundcall_trendChart`(
       	p_domainId 			INT,
       	p_datetype 			INT,            
   		p_startDateTime		DATETIME,
   		p_endDateTime		DATETIME,
       	p_columnName    	VARCHAR(200),    
       	p_queueId 			TEXT
       )
sp_return:BEGIN
       
       
 		DECLARE v_startDateTime			DATETIME;
 		DECLARE v_endDateTime			DATETIME;     
 		DECLARE v_datetimeInterval		SMALLINT;    
 		DECLARE v_startDateTimePast		DATETIME;
 		DECLARE v_endDateTimePast		DATETIME;
 
 		DECLARE v_startTimestampPast		BIGINT;
 		DECLARE v_endTimestampPast		BIGINT;      
 		DECLARE v_startTimestamp			BIGINT;
 		DECLARE v_endTimestamp			BIGINT;
 		DECLARE v_curDate				DATETIME DEFAULT NOW();	
 		DECLARE v_currentCount			INT;
 		DECLARE v_pastCount				INT;
       
		DROP TEMPORARY TABLE IF EXISTS tmp_result;
     	CREATE TEMPORARY TABLE tmp_result(
     		reportAge			VARCHAR(20)
     		,startDateTime		DATETIME
     		,endDateTime		DATETIME
     		,callCount			INT
     	);  
       
       	IF p_datetype = 1 
           THEN 	
       		SET v_startDateTime = CAST(v_curDate AS DATE); 
       		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
       	END IF;
       	IF p_datetype = 2 
           THEN 
       		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
               SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
       	END IF;
       	IF p_datetype = 3 
           THEN 
       		
                 
                 SET v_startDateTime = p_startDateTime;
                 SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                 
     			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                 
         		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                 SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       	IF p_datetype = 4 
           THEN 
       		SET v_startDateTime = p_startDateTime; 
               SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND); 
               
               SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
        
 		IF p_queueId IS NOT NULL 
 		THEN
 			DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
 			CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
 		ELSE
 			DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
 			CREATE TEMPORARY TABLE temp_queueIDs
 			SELECT 	qid   AS queueId
 			FROM 	queue
 			WHERE 	domainId = p_domainId;
 		END IF;
           
           DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
           CREATE TEMPORARY TABLE tmp_Disposition
           SELECT 	did, dispositionName
           FROM 	disposition_status
           WHERE	domainId		= p_domainId;
           
           
           IF p_datetype IN (1,2)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH RECURSIVE CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	endDateTime < v_endDateTime
       		)
       		SELECT * FROM CTE_TIMINGS;	
       	ELSEIF p_datetype IN (3,4)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH recursive CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	startDateTime < v_endDateTime
       		)
       		SELECT * FROM CTE_TIMINGS;	
           END IF;  
           
           ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
           
           UPDATE 	tmp_timings
           SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
       		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
               
       	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
           ,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
           ,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
       	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
           
        DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
     	CREATE TEMPORARY TABLE tmp_CallDurationHistory
		SELECT 	CH.CallHistoryId
			,	CH.sessionStartTime
			,	CDH.CallDurationHistoryId
			,	CDH.transferredTypeId
			,	CDH.dispositionId        
			,	CDH.Duration
			,	CDH.QueueId
			,	CH.voicemailUrl
			,	CDH.IsMissedCall
			,	CDH.UMNStatus
			,	CH.IsAbandoned
            ,	CDH.transferedBy
		FROM 	tb_CallHistory         CH
		JOIN 	tb_CallDurationHistory CDH	ON 	CH.CallHistoryId 	= CDH .CallHistoryId     
		LEFT JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CDH.QueueId	
		WHERE 	CH.domainId 		= p_domainId
		AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
		AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND Q.queueId IS NOT NULL))
		AND 	CH.IsInBound		= 0;
      	
     	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
      	CREATE TEMPORARY TABLE tmp_CallHistory
         SELECT 	DISTINCT 
      			CDH.CallHistoryId 
      		, 	CDH.sessionStartTime
             ,	CDH.CallDurationHistoryId
      	FROM 	tmp_CallDurationHistory CDH;  
          
          ALTER TABLE tmp_CallHistory ADD transferredTypeId 	INT default 0;
          ALTER TABLE tmp_CallHistory ADD IsAnswered 			TINYINT default 0;
          ALTER TABLE tmp_CallHistory ADD IsUnAnswered 			TINYINT default 0;
          ALTER TABLE tmp_CallHistory ADD IsAbandoned			TINYINT default 0;
          
          CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
          CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);
      
          UPDATE tmp_CallHistory			CH
          JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  AND CH.CallDurationHistoryId = CDH.CallDurationHistoryId
          LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
          SET 	CH.transferredTypeId = CASE WHEN (CDH.transferredTypeId > 0 AND CDH.transferedBy is not null) THEN 1 ELSE 0 	END
      		,	CH.IsAnswered	= CASE WHEN CDH.UMNStatus = 1 and CDH.Duration > 0  and CDH.IsMissedCall = 0 and CDH.IsAbandoned = 0 THEN 1 ELSE 0 	END
            ,	CH.IsUnAnswered	= CASE WHEN CDH.UMNStatus=4  THEN 1 ELSE 0 	END
			,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned = 1 THEN 1 ELSE 0 END;
              
          IF p_columnName = 'Outbound calls'
          THEN	
          INSERT INTO tmp_result
      		SELECT 	'Current'																	AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END),0)	AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
			INSERT INTO tmp_result
      		SELECT 	'Past'																		AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END),0)	AS PastcallCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;	
            
			ELSEIF p_columnName = 'Answered Calls'
			THEN
			INSERT INTO tmp_result
      		SELECT 	'Current'							AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(IsAnswered),0)			AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
			INSERT INTO tmp_result
      		SELECT 	'Past'								AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	ifnull(SUM(IsAnswered),0)			AS PastcallCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
		
        ELSEIF p_columnName = 'UnAnswered Calls'
			THEN
			INSERT INTO tmp_result
      		SELECT 	'Current'							AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(IsUnAnswered),0)			AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
			INSERT INTO tmp_result
      		SELECT 	'Past'								AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	ifnull(SUM(IsUnAnswered),0)			AS PastcallCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
      	ELSEIF p_columnName = 'Abandoned Calls'
          THEN
			INSERT INTO tmp_result
      		SELECT 	'Current'					AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(IsAbandoned),0)	AS CurrentcallCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
			INSERT INTO tmp_result
			SELECT 	'Past'					AS reportAge
				,	t_T.startDateTime 
				,	t_T.endDateTime
				,	SUM(IsAbandoned)		AS PastcallCount         
			FROM 	tmp_timings		t_T	
			LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
			WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
			GROUP BY t_T.startDateTime, t_T.endDateTime;	
            
			ELSEIF p_columnName = 'Transferred Calls'
			THEN
			INSERT INTO tmp_result
			SELECT 	'Current'								AS reportAge
				,	t_T.startDateTime 
				,	t_T.endDateTime
				,	ifnull(SUM(CH.transferredTypeId),0)		AS CurrentcallCount 
			FROM 	tmp_timings			t_T	
			LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
			WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
			GROUP BY t_T.startDateTime, t_T.endDateTime;
              
			INSERT INTO tmp_result
      		SELECT 	'Past'										AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.transferredTypeId),0)			AS PastcallCount         
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;        
          END IF;
          
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Current';    
         
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Past';
          
     	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
     	INTO 	v_currentCount, v_pastCount		
     	FROM 	tmp_result;
         
		SELECT 	p_columnName    														AS metric
				,   v_currentCount														AS currentTotal
				, 	v_pastCount															AS pastTotal
				,	(v_currentCount - v_pastCount)  									AS totalDifference
				,	IFNULL((v_currentCount - v_pastCount) /(IF(v_pastCount=0,1,v_pastCount)) *100 ,0)	    AS  Percentage;	
         
         
      
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Queue_call_Outbound_Best_Time_Call_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_Queue_call_Outbound_Best_Time_Call_trendChart`(
 	p_domainId 			INT,
 	p_datetype 			INT,            
 	p_startDateTime		DATETIME,
 	p_endDateTime		DATETIME,
 	p_columnName    	VARCHAR(200),    
 	p_queueId 			TEXT
        )
sp_return: BEGIN
      
    		DECLARE v_startDateTime			DATETIME;
    		DECLARE v_endDateTime			DATETIME;     
    		DECLARE v_datetimeInterval		SMALLINT;    
    		DECLARE v_startDateTimePast		DATETIME;
    		DECLARE v_endDateTimePast		DATETIME;
    
    		DECLARE v_startTimestampPast	BIGINT;
    		DECLARE v_endTimestampPast		BIGINT;      
    		DECLARE v_startTimestamp		BIGINT;
    		DECLARE v_endTimestamp			BIGINT;
    		DECLARE v_curDate				DATETIME DEFAULT NOW();	
    		DECLARE v_currentCount			INT;
    		DECLARE v_pastCount				INT;
           
    		DROP TEMPORARY TABLE IF EXISTS tmp_result;
    		CREATE TEMPORARY TABLE tmp_result(
    			reportAge			VARCHAR(20)
    			,startDateTime		DATETIME
    			,endDateTime		DATETIME
    			,callCount			INT
    		);    
        
        	IF p_datetype = 1 THEN 	
        		SET v_startDateTime = CAST(v_curDate AS DATE);
                SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
                
    			SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY);
                SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
        	END IF;
        	IF p_datetype = 2 THEN 
        		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE);
                SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
                
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY);
                SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
        	END IF;
        	IF p_datetype = 3 THEN 
        		
                
                SET v_startDateTime = p_startDateTime;
                SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                
    			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        	END IF;
        	IF p_datetype = 4 THEN 
        		SET v_startDateTime = p_startDateTime;
                SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                
    			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                
        		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
        	END IF;
            
            IF p_queueId IS NOT NULL 
            THEN
        		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
        		CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
            ELSE
        		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs
        		SELECT 	qid	AS queueId
    			FROM 	queue
    			WHERE 	domainId = p_domainId;
            END IF;
            
            DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
            CREATE TEMPORARY TABLE tmp_Disposition
            SELECT did, dispositionName
            FROM 	disposition_status
            WHERE	domainId		= p_domainId;
           
            
            IF p_datetype IN (1,2)
            THEN 
        		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
        		WITH RECURSIVE CTE_TIMINGS AS (
        			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
        			UNION ALL
        			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
        			FROM 	CTE_TIMINGS
        			WHERE 	endDateTime < v_endDateTime
        		)
        		SELECT * FROM CTE_TIMINGS;	
        	ELSEIF p_datetype IN (3,4)
            THEN 
        		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
        		WITH recursive CTE_TIMINGS AS (
        			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
        			UNION ALL
        			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
        			FROM 	CTE_TIMINGS
        			WHERE 	startDateTime < v_endDateTime
        		)
        		SELECT * FROM CTE_TIMINGS;	
            END IF;  
            
            ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
            
            UPDATE tmp_timings
            SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
        		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
                
        	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
    		,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
    		,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
    		, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
          
          
        DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
       	CREATE TEMPORARY TABLE tmp_CallDurationHistory
   		SELECT 		CH.CallHistoryId
   				,	CH.sessionStartTime
  				,	CDH.CallDurationHistoryId
   				,	CDH.IsMissedCall
   				,	CDH.dispositionId        
   				,	CDH.Duration
   				,	CDH.QueueId
  				,	CH.voicemailUrl
				,	CDH.answeredDuration
                ,	CDH.UMNStatus
                ,	CDH.IsAbandoned
   		FROM 		tb_CallHistory         	CH
   		JOIN 		tb_CallDurationHistory 	CDH	ON 	CH.CallHistoryId	= CDH.CallHistoryId     
   		LEFT JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CDH.QueueId	
   		WHERE 	CH.domainId		= p_domainId
   		AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
   		AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND Q.queueId IS NOT NULL))
   		AND 	CH.IsInBound			= 0;  
          
    	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
    	CREATE TEMPORARY TABLE tmp_CallHistory
    	SELECT 	DISTINCT CDH.CallHistoryId 
    				, 	CDH.sessionStartTime
                  ,	CDH.CallDurationHistoryId
    	FROM 	tmp_CallDurationHistory CDH;  
            
    		ALTER TABLE tmp_CallHistory ADD IsMissed		TINYINT default 0;
    		ALTER TABLE tmp_CallHistory ADD IsAnswered 		TINYINT DEFAULT 0;
    		ALTER TABLE tmp_CallHistory ADD IsUnAnswered	TINYINT DEFAULT 0;
  		ALTER TABLE tmp_CallHistory ADD voicemailUrl	TINYINT DEFAULT 0;
 		ALTER TABLE tmp_CallHistory ADD Iswrongcall		TINYINT DEFAULT 0;
         ALTER TABLE tmp_CallHistory ADD IsQueueId		TINYINT DEFAULT 0;
         
 	
            
            CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
            CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);
        
            UPDATE tmp_CallHistory			CH
            JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  AND CH.CallDurationHistoryId = CDH.CallDurationHistoryId
            LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
            SET 	CH.IsMissed		= CASE WHEN CDH.IsMissedCall = 1																		THEN 1 ELSE CH.IsMissed END
         		,	CH.IsAnswered	= CASE WHEN CDH.UMNStatus = 1 and CDH.Duration > 0  and CDH.IsMissedCall = 0 and CDH.IsAbandoned = 0	THEN 1 ELSE 0 END
 				,   CH.IsUnAnswered = CASE WHEN CDH.UMNStatus <> 1 and (CDH.IsMissedCall = 0 OR CDH.IsAbandoned = 0)						THEN 1 ELSE CH.IsUnAnswered END
 				,	CH.voicemailUrl = CASE WHEN (CDH.voicemailUrl IS NOT NULL AND CDH.voicemailUrl<>0)										THEN 1 ELSE 0 END
 				,	CH.Iswrongcall	= CASE WHEN D.dispositionName like '%wrong%' 															THEN 1 ELSE 0 END 
                 ,	CH.IsQueueId	= CASE WHEN CDH.QueueId<>0 THEN 1 ELSE 0 END ;
                 
               
          IF p_columnName = 'Outbound calls'
            THEN
       		INSERT INTO tmp_result
        		SELECT 	'Current'				AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
        			,	SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
        		FROM 	tmp_timings			t_T	
        		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
               
               INSERT INTO tmp_result
        		SELECT 	'Past'					AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
        			,	SUM(CASE WHEN CH.CallHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
        		FROM 	tmp_timings		t_T	
        		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
        		GROUP BY t_T.startDateTime, t_T.endDateTime;	
                
         	ELSEIF p_columnName = 'Answered Calls' THEN
    			INSERT INTO tmp_result
        		SELECT 	'Current'					AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
        			,	IFNULL(SUM(IsAnswered),0)	AS callCount
        		FROM 	tmp_timings			t_T	
        		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
               
               INSERT INTO tmp_result
        		SELECT 	'Past'						AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
        			,	IFNULL(SUM(IsAnswered),0)	AS callCount     
        		FROM 	tmp_timings		t_T	
        		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          	ELSEIF p_columnName = 'UnAnswered Calls'
    		THEN
       		INSERT INTO tmp_result
        		SELECT 	'Current'					AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
        			,	IFNULL(SUM(IsUnAnswered),0)	AS callCount
        		FROM 	tmp_timings			t_T	
        		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
               
               INSERT INTO tmp_result
        		SELECT 	'Past'						AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
        			,	IFNULL(SUM(IsUnAnswered),0)	AS callCount     
        		FROM 	tmp_timings		t_T	
        		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
                
    		ELSEIF p_columnName = 'Right party'
    		THEN
       		INSERT INTO tmp_result
        		SELECT 	'Current'					AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
                  ,	IFNULL(SUM(CASE WHEN CH.IsAnswered=1 AND CH.Iswrongcall=0 THEN IsAnswered ELSE 0 END),0) AS callCount
        		FROM 	tmp_timings			t_T	
        		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
               
 			INSERT INTO tmp_result
        		SELECT 	'Past'						AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime  
                  ,	IFNULL(SUM(CASE WHEN CH.IsAnswered=1 AND CH.Iswrongcall=0 THEN IsAnswered ELSE 0 END),0) AS callCount
        		FROM 	tmp_timings		t_T	
        		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
             
          ELSEIF p_columnName = 'Success Rate'
    		THEN
       		INSERT INTO tmp_result
        		SELECT 	'Current'					AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
                  ,	IFNULL(SUM(CASE WHEN CH.Iswrongcall=0 AND CH.IsAnswered=1 THEN IsAnswered ELSE 0 END),0)/IF(COUNT(CH.CallDurationHistoryId)=0,1,COUNT(CH.CallDurationHistoryId)) AS callCount
        		FROM 	tmp_timings			t_T	
        		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
               
 			INSERT INTO tmp_result
        		SELECT 	'Past'						AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
                  ,	IFNULL(SUM(CASE WHEN CH.Iswrongcall=0 AND CH.IsAnswered=1 THEN IsAnswered ELSE 0 END),0)/IF(COUNT(CH.CallDurationHistoryId)=0,1,COUNT(CH.CallDurationHistoryId)) AS callCount
        		FROM 	tmp_timings		t_T	
        		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
           ELSEIF p_columnName = 'Queue'
    		THEN
       		INSERT INTO tmp_result
        		SELECT 	'Current'					AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
                  ,	IFNULL(SUM(CASE WHEN CH.IsQueueId=1 THEN 1 ELSE 0 END),0) AS callCount
        		FROM 	tmp_timings			t_T	
        		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
               
 			INSERT INTO tmp_result
        		SELECT 	'Past'						AS reportAge
        			,	t_T.startDateTime 
        			,	t_T.endDateTime
                  ,	IFNULL(SUM(CASE WHEN CH.IsQueueId=1 THEN 1 ELSE 0 END),0)  AS callCount
        		FROM 	tmp_timings		t_T	
        		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
        		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
        		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
          END IF;
            
 		SELECT  *
 		FROM 	tmp_result
 		WHERE 	reportAge = 'Current';    
 
 		SELECT  *
 		FROM 	tmp_result
 		WHERE 	reportAge = 'Past';
            
       	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
       	INTO 	v_currentCount, v_pastCount		
       	FROM 	tmp_result;
           
    	SELECT 	p_columnName   												AS metric
    	,	IFNULL(v_currentCount,0)										AS currentTotal
    	, 	IFNULL(v_pastCount,0)											AS pastTotal
    	,	IFNULL((v_currentCount - v_pastCount),0)  						AS totalDifference
    	,	IFNULL((v_currentCount - v_pastCount) /(IF(v_pastCount=0,1,v_pastCount)) *100 ,0)	AS Percentage;
           
    
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_call_Servicelevel_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_queue_call_Servicelevel_trendChart`(
	p_domainId 			INT,
	p_datetype 			INT,        
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
	p_columnName    	VARCHAR(200),       
	p_queueId 			TEXT
  )
BEGIN
   
    	DECLARE v_startDateTime			DATETIME;
    	DECLARE v_endDateTime			DATETIME;     
    	DECLARE v_datetimeInterval		SMALLINT;    
    	DECLARE v_startDateTimePast		DATETIME;
    	DECLARE v_endDateTimePast		DATETIME;
         
    	DECLARE v_startTimestampPast	BIGINT;
    	DECLARE v_endTimestampPast		BIGINT;      
    	DECLARE v_startTimestamp		BIGINT;
    	DECLARE v_endTimestamp			BIGINT;
    	DECLARE v_curDate				DATETIME DEFAULT NOW();	
       DECLARE v_currentCount			INT;
       DECLARE v_pastCount				INT;
        
    	DROP TEMPORARY TABLE IF EXISTS tmp_result;
    	CREATE TEMPORARY TABLE tmp_result(
    		reportAge			VARCHAR(20)
    		,startDateTime		DATETIME
    		,endDateTime		DATETIME
    		,callCount			INT
    	);    
     
     	IF p_datetype = 1 
         THEN 	
     		SET v_startDateTime = CAST(v_curDate AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
     	END IF;
     	IF p_datetype = 2 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
     	END IF;
     	IF p_datetype = 3 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = CAST(v_curDate AS DATE); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
     	END IF;
     	IF p_datetype = 4 
         THEN 
     		SET v_startDateTime = p_startDateTime; 
    		SET v_endDateTime 	= p_endDateTime; 
             
            SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     	END IF;
         
         IF p_queueId IS NOT NULL 
         THEN
     		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
     		CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
         ELSE
     		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs
     		SELECT 	qid	AS queueId
    		FROM 	queue
            WHERE 	domainId = p_domainId;
         END IF;
         
         DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
         CREATE TEMPORARY TABLE tmp_Disposition
         SELECT did, dispositionName
         FROM 	disposition_status
         WHERE	domainId		= p_domainId
         AND	dispositionName	= 'Caller Disconnected';    
         
         IF p_datetype IN (1,2)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH RECURSIVE CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	endDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
     	ELSEIF p_datetype IN (3,4)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH recursive CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	startDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
         END IF;  
         
         ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
         UPDATE tmp_timings
         SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
     		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
             
     	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
    	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
    	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
    	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
         
         
         
    	DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
    	CREATE TEMPORARY TABLE tmp_CallDurationHistory
    	SELECT 	CH.CallHistoryId
    		,	CH.sessionStartTime
    		,	CDH.IsMissedCall
    		,	CDH.dispositionId        
    		,	CDH.answeredDuration
           ,   CDH.Duration
    	FROM 	tb_CallHistory         CH
    	JOIN 	tb_CallDurationHistory CDH	ON 	CH.CallHistoryId 	= CDH .CallHistoryId     
    	JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CDH.QueueId	
    	WHERE 	CH.domainId 		= p_domainId
    	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
    
     	
    	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
     	CREATE TEMPORARY TABLE tmp_CallHistory
        SELECT 	DISTINCT 
     			CDH.CallHistoryId 
     		, 	CDH.sessionStartTime
     	FROM 	tmp_CallDurationHistory CDH;  
         
         ALTER TABLE tmp_CallHistory ADD IsMissed 		TINYINT default 0;
         ALTER TABLE tmp_CallHistory ADD IsAnswered 	TINYINT default 0;
         ALTER TABLE tmp_CallHistory ADD IsUnAnswered 	TINYINT default 0;
         ALTER TABLE tmp_CallHistory ADD IsAbandoned	TINYINT default 0;
         ALTER TABLE tmp_CallHistory ADD TotalSLA		TINYINT default 0;
         
         
         CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
         CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);
     
         UPDATE tmp_CallHistory			CH
         JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  
         LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
         SET 	CH.IsMissed		= CASE WHEN CDH.IsMissedCall = 1 			THEN 1 ELSE 0 	    END
     		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE 0	    END
           ,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 		THEN 1 ELSE 0	    END
           ,   CH.TotalSLA     = CASE WHEN CDH.answeredDuration BETWEEN 1 AND 30000 THEN 1 ELSE 0 END 
   		,	CH.IsAbandoned	= CASE WHEN D.did IS NOT NULL 		        THEN 1 ELSE 0 	END;     
         
         
         
          IF p_columnName = 'Missed Calls'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'			AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					    AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;        
           ELSEIF p_columnName = 'Total SLA'
    	THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(TotalSLA),0)	    AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(TotalSLA),0)	    AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
   
   
    
   
   
   ELSEIF p_columnName = 'Answered call'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'								  AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
               ,   IFNULL(SUM(CH.IsAnswered),0)        AS callCount              
     			
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					        									AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
               ,   IFNULL(sum(CH.IsAnswered),0)                                  AS callCount   
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;  	
   
         END IF;
         
        SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Current';    
        
        SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Past';
         
    	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
    	INTO 	v_currentCount, v_pastCount		
    	FROM 	tmp_result;
        
        SELECT 	p_columnName    													AS metric
  		  ,		ifnull(v_currentCount,0)											AS currentTotal
    		  , 	ifnull(v_pastCount,0)												AS pastTotal
  		  ,	    ifnull((v_currentCount - v_pastCount),0)  							AS totalDifference
             ,	ifnull((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)		AS  Percentage;
        
   
     
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_chat_performances_analysis_metrics` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_queue_chat_performances_analysis_metrics`(  
   p_startTmpstmp 		BIGINT,
   p_endTmpstmp 		BIGINT,
   p_domainId 			INT,    	
   p_queueIds			TEXT,		
   p_offset 			INT,
   p_Limit 			INT	
)
BEGIN
                            
		DECLARE v_offset INT;
		DECLARE v_CurrentStartTmpstmp BIGINT;
		DECLARE v_CurrentEndTmpstmp BIGINT;

		DECLARE v_PrevStartTmpstmp BIGINT;
		DECLARE v_PrevEndTmpstmp BIGINT; 
		DECLARE v_TmpstmpInterval BIGINT;	

		DECLARE v_PrevAverageResponseCount INT;
		DECLARE v_CurrentAverageResponseCount INT;
		DECLARE v_DiffAverageResponsePercent INT;

		DECLARE v_PrevAverageHandledCount INT;
		DECLARE v_CurrentAverageHandledCount INT;
		DECLARE v_DiffAverageHandledPercent INT;

		DECLARE v_PrevMaximumHandledCount INT;	
		DECLARE v_CurrentMaximumHandledCount INT;
		DECLARE v_DiffMaximumHandledTimePercent INT;

			DECLARE v_PrevTotalACWCount INT;
			DECLARE v_CurrentTotalACWCount INT;
			DECLARE v_DiffTotalACWTimePercent INT;

			DECLARE v_PrevAverageQueueWaitingCount INT;	
			DECLARE v_CurrentAverageQueueWaitingCount INT;
			DECLARE v_DiffAverageQueueWaitingPercent INT; 

			DECLARE v_PrevaverageHoldtCount INT;
			DECLARE v_CurrentaverageHoldtCount INT;
			DECLARE v_DiffaverageHoldtPercent INT; 

			DECLARE v_PrevMaximumQueueWaitingCount INT;	
			DECLARE v_CurrentMaximumQueueWaitingCount INT;
			DECLARE v_DiffMaximumQueueWaitingPercent INT;

			DECLARE v_PrevfirstChatResolutionCount INT;	
			DECLARE v_CurrentfirstChatResolutionCount INT;
			DECLARE v_DifffirstChatResolutionPercent INT;

			DECLARE v_PreSentimentalScore INT;
			DECLARE v_CurrentSentimentalScore INT;
			DECLARE v_DiffSentimentalScorePercent INT;

			DECLARE v_PrevAgentIdleTimeCount INT;
			DECLARE v_CurrentAgentIdleTimeCount INT;
			DECLARE v_DifffirsAgentIdleTimePercent INT;

			DECLARE v_PreavailableCount bigint;
			DECLARE v_CurrentavailableCount bigint;
			DECLARE v_PretotalTalkCount INT;
			DECLARE v_CurrenttotalTalkCount INT;  

			DECLARE	v_agentIdleTime BIGINT;
			DECLARE	v_averageResponseTime BIGINT; 
			DECLARE	v_averageHandledTime BIGINT;
			DECLARE	v_MaximumHandledTime BIGINT; 
			DECLARE	v_totalACWTime BIGINT;
			DECLARE	v_averageHoldtime BIGINT; 
			DECLARE	v_averageQueueWaittime BIGINT;
			DECLARE	v_maximumQueueWaittime BIGINT; 
			DECLARE	v_occupancyRate BIGINT;
			DECLARE	v_firstChatResolution BIGINT; 
			DECLARE	v_CustomerSatisfaction BIGINT; 
			DECLARE	v_IncomingChats BIGINT; 
			DECLARE	v_callDuration BIGINT; 
			DECLARE	v_afterChatWorkTime INT; 
			DECLARE	v_availableTime BIGINT; 
			DECLARE	v_currentResponseTime BIGINT; 
			DECLARE	v_previousResponseTime BIGINT; 
			DECLARE	v_currentHandledTime BIGINT; 
			DECLARE	v_previousHandledTime BIGINT; 
			DECLARE	v_currentTotalAnsweredChats INT; 
			DECLARE	v_previousTotalAnsweredChats INT; 
			DECLARE v_count INT;
			DECLARE v_answerChat INT;
			DECLARE v_CurTotalCount INT;
			DECLARE v_PrevTotalCount INT;
			DECLARE v_CurResponseTime INT;
			DECLARE v_PreResponseTime INT;
			DECLARE v_CurHandledTime INT;
			DECLARE v_PreHandledTime INT;

			DECLARE	v_prvcount INT;
			DECLARE	v_prevAnswerChat INT; 
			DECLARE	v_prevAverageResponseTime INT;
			DECLARE	v_prevAverageHandledTime INT;
			DECLARE	v_CurrentTotalCount INT;
			DECLARE	v_PreviousTotalCount INT;
			DECLARE	v_currentAVGHandleTime INT;
			DECLARE	v_prevAVGHandleTime INT;
			DECLARE p_timezone Text;
      
   				SET v_offset =  p_Limit * p_offset; 
                set p_timezone = '+05:30';
   
   				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
   				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
   
   				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
   				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
   				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                       		
				DROP TEMPORARY TABLE IF EXISTS temp_queueIds; CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
				CALL split(p_queueIds, ','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable;      

				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);

				DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
				CREATE TEMPORARY TABLE temp_AvailableDisposition 
				(    DispositionId 			INT
				,DispositionStatus 		VARCHAR(100)
				,DispositionCategory	TINYINT
				); 
      			  
      				INSERT INTO temp_AvailableDisposition 
      				SELECT 	did 			DispositionId
      					,	dispositionName	DispositionStatus
      					,	CASE WHEN dispositionName = 'Opened'	THEN 2
      						WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
      						WHEN dispositionName = 'Discarded'     THEN 4
      						WHEN dispositionName = 'Resolved'      THEN 5
      						END 			DispositionCategory
      				FROM 	disposition_status
      				WHERE 	domainId	= p_domainId;
                                 	
      				DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
      				CREATE TEMPORARY TABLE temp_FirstCallResolution
      				SELECT 
      				COUNT(SubQuery.AgentId) AS FirstCallResolution,
      				SubQuery.AgentId,SubQuery.ChatHistoryId
      				FROM (
      				SELECT 
      				SDH.AgentId,SH.ChatHistoryId
      				FROM tb_ChatHistory SH
      				JOIN tb_ChatDurationHistory SDH ON SH.ChatHistoryId = SDH.ChatHistoryId 
      				JOIN disposition_status DS ON DS.did = SDH.dispositionId
      				WHERE SDH.IsBot = 0
      				AND SH.domainId = p_domainId
      				AND SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
					AND	DS.dispositionName <> 'Transferred'
      				GROUP BY SDH.AgentId, SH.ChatHistoryId
      				HAVING COUNT(SDH.ChatDurationHistoryId) = 1
      				) AS SubQuery
      				GROUP BY SubQuery.AgentId,SubQuery.ChatHistoryId;
                                  
  					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
  					DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
  					CREATE TEMPORARY TABLE temp_AllqueueId   
  					SELECT qid, name AS queueName 
  					FROM queue     
  					WHERE domainId = p_domainId;
  					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                                     
      				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      				DROP TEMPORARY TABLE IF EXISTS tt_ChatHistory; 
      				CREATE TEMPORARY TABLE tt_ChatHistory AS 	    	
      				SELECT 	SH.sessionStartTime
  					, SH.ChatHistoryId
      				, SDH.AgentId
      				, SH.IsMissed
  					, Q.qid  																		AS queueId
  					, Q.name 																		AS queueName												
      				, SDH.StartTime												
      				, SDH.EndTime												
      				, SH.IsInBound
      				, SDH.Duration												
      				, IFNULL(SDH.AgentHoldDuration,0) AS AgentHoldDuration										
      				, SH.CallBackStatus		                                    			                 
      				, SDH.EndTime - SDH.StartTime								   
      				, SDH.answeredDuration										                                                      
      				, SDH.transferredTime																	
      				, SDH.afterChatWorkTime		
      				, SH.queueDuration											
      				, CSF.satisfactionRate
      				, t_f.FirstCallResolution 									
      				FROM 	tb_ChatHistory 				SH
      				JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId
                    LEFT JOIN tb_customerFeedback 		CSF ON CSF.historyId		= SH.chatHistoryId
      				LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
					LEFT JOIN queue 					Q 	ON SDH.QueueId = Q.qid
      				LEFT JOIN temp_queueIds 			t_Q ON Q.qid = t_Q.queueId       
      				JOIN temp_FirstCallResolution 		t_f	ON t_f.ChatHistoryId 	= SDH.chatHistoryId
      				WHERE 	SH.domainId 		= p_domainId	 
      				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
                    
      				AND 	(IFNULL(p_queueIds,'') 	= '' OR (IFNULL(p_queueIds,'') <> '' AND t_Q.queueId IS NOT NULL)); 
                     
					DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
      				CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
      				SELECT 	CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
					, sessionStartTime	
					, ChatHistoryId
                    , AgentId
      				, queueId
      				, CASE WHEN IsMissed =1  THEN 1 ELSE 0 END 				AS agentIdleTime
      				, queueName												AS queueName
      				, StartTime												AS agentconnecttime
      				, EndTime												AS agentDisconnectTime
      				, IsInBound
      				, Duration												AS callDuration
      				, AgentHoldDuration										AS agentHoldDuration
      				, ((Duration/1000)+afterChatWorkTime)					AS Handled                                 
      				, CASE WHEN CallBackStatus=1 THEN 1 ELSE 0 END			AS UnansweredChat                                             			                 
      				, EndTime - StartTime									AS chatHandlingTime          
      				, answeredDuration										AS responseTime                                                                 
      				, transferredTime										AS transferredTime							
      				, afterChatWorkTime		
      				, queueDuration											AS queueWaitingtime
      				, satisfactionRate										AS satisfactionRate
      				, case when IsInBound=1 then 1 else 0 end 				AS IncomingChats   
      				, FirstCallResolution 									AS firstChatResolution
    				,CASE WHEN Duration > 0 THEN 1 ELSE 0 END      			AS respondedChat
    				,CASE WHEN answeredDuration > 0 THEN 1 ELSE 0 END      	AS answeredChat
      				FROM 	tt_ChatHistory 				
      				WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ; 
                   
                   DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_prev; 
      				CREATE TEMPORARY TABLE temp_ChatHistory_prev AS 	    	
      				SELECT 	CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
					, sessionStartTime	
					, ChatHistoryId
					, AgentId
      				, queueId
      				, CASE WHEN IsMissed =1  THEN 1 ELSE 0 END 				AS agentIdleTime
      				, queueName												AS queueName
      				, StartTime												AS agentconnecttime
      				, EndTime												AS agentDisconnectTime
      				, IsInBound
      				, Duration												AS callDuration
      				, AgentHoldDuration										AS agentHoldDuration
      				, ((Duration/1000)+afterChatWorkTime)					AS Handled                                 
      				, CASE WHEN CallBackStatus=1 THEN 1 ELSE 0 END			AS UnansweredChat                                             			                 
      				, EndTime - StartTime									AS chatHandlingTime          
      				, answeredDuration										AS responseTime                                                                 
      				, transferredTime										AS transferredTime							
      				, afterChatWorkTime		
      				, queueDuration											AS queueWaitingtime
      				, satisfactionRate										AS satisfactionRate
      				, case when IsInBound=1 then 1 else 0 end 				AS IncomingChats   
      				, FirstCallResolution 									AS firstChatResolution
    				,CASE WHEN Duration > 0 THEN 1 ELSE 0 END      			AS respondedChat
    				,CASE WHEN answeredDuration > 0 THEN 1 ELSE 0 END      	AS answeredChat
      				FROM 	tt_ChatHistory 				
      				WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ;
                   
                   DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
      				CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
      				SELECT 	
					count(1)                             																				AS NoOfChats
                    , t_SH.AgentId
      				, t_SH.queueId
      				, t_SH.SessionDate
      				, t_SH.queueName																              						AS queueName
      				, SUM(t_SH.agentIdleTime) 																							AS agentIdleTime
    				, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
    				, SUM(t_SH.Handled)																									AS averageHandledTime    
    				, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
    				, CASE WHEN SUM(t_SH.afterChatWorkTime) IS NOT NULL THEN SUM(t_SH.afterChatWorkTime) ELSE 0 END 					AS totalACWTime                    
    				, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
    				, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
      				, SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						AS answeredCall
      				, SUM(IFNULL(t_SH.agentHoldDuration,0))                                                                				AS callHoldTime
      				, SUM(t_SH.callDuration-IFNULL(t_SH.agentHoldDuration,0))							                                AS totalTalktime
      				, t_SH.firstChatResolution
      				, sum(t_SH.IncomingChats)                          																	AS IncomingChats
      				, t_SH.satisfactionRate																								AS CustomerSatisfaction
      				, sum(t_SH.afterChatWorkTime)																						AS afterChatWorkTime		
      				, sum(t_SH.callDuration)																							AS callDuration	
    				, sum(t_SH.respondedChat)																							AS respondedChat
    				,sum(t_SH.answeredChat)																								AS answeredChat               
      				FROM 	temp_ChatHistory t_SH
      				GROUP BY t_SH.SessionDate,t_SH.AgentId, t_SH.queueName, t_SH.queueId, t_SH.firstChatResolution,t_SH.satisfactionRate,t_SH.callDuration;
      				
                   
                   DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_prev; 
      				CREATE TEMPORARY TABLE temp_chatHistory_calc_prev AS 	     
      				SELECT 	
						count(1)                             																	   AS NoOfChats
					, t_SH.AgentId
                    , t_SH.queueId
      				, t_SH.SessionDate
      				, t_SH.queueName																              						
      				, SUM(t_SH.agentIdleTime) 																							AS agentIdleTime
    				, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
    				, SUM(t_SH.Handled)																									AS averageHandledTime    
    				, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
    				, CASE WHEN SUM(t_SH.afterChatWorkTime) IS NOT NULL THEN SUM(t_SH.afterChatWorkTime) ELSE 0 END 					AS totalACWTime                    
    				, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
    				, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
      				, SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime   > 0  THEN 1 ELSE 0 END)       						AS answeredCall
      				, SUM(IFNULL(t_SH.agentHoldDuration,0))                                                                				AS callHoldTime
      				, SUM(t_SH.callDuration-IFNULL(t_SH.agentHoldDuration,0))							                                AS totalTalktime
      				, t_SH.firstChatResolution
      				, sum(t_SH.IncomingChats)                          																	AS IncomingChats
      				, t_SH.satisfactionRate																								AS CustomerSatisfaction
      				, sum(t_SH.afterChatWorkTime)																						AS afterChatWorkTime		
      				, sum(t_SH.callDuration)																							AS callDuration	
    				, sum(t_SH.respondedChat)																							AS respondedChat
    				,sum(t_SH.answeredChat)																								AS answeredChat               
      				FROM 	temp_ChatHistory_prev t_SH
      				GROUP BY t_SH.SessionDate,t_SH.AgentId, t_SH.queueName, t_SH.queueId, t_SH.firstChatResolution,t_SH.satisfactionRate,t_SH.callDuration;
      				
    
      				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
      				CREATE TEMPORARY TABLE temp_AvailableStates AS
      				SELECT   
      					CASE 
      						WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
      						ELSE 2 
      					END AS tt_Time,
      					ST.ext,
      					ST.domainId,
      					from_unixtime(ST.startTimestamp/1000),
      					
                        IFNULL(((unix_timestamp(convert_tz(current_timestamp(),p_timezone,'+00:00')) * 1000)- ST.startTimestamp),ST.stateDuration) as SD
      				FROM     state_timer ST 
      				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
      				WHERE    ST.domainId = p_domainId
      				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
      							
				ALTER TABLE temp_chatHistory_calc ADD COLUMN availableTime BIGINT;
                ALTER TABLE temp_chatHistory_calc ADD COLUMN agentName varchar(250);
                    
				DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                CREATE TEMPORARY TABLE temp_AllagentId
				select  UserID,ext,UserName,domainId from tb_User where domainId = p_domainId; 
                
      				UPDATE temp_chatHistory_calc SH_C
      				JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
      				JOIN (
      				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
      				FROM temp_AvailableStates
      				GROUP BY ext, domainId
      				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
      				SET SH_C.availableTime 	= tt_AV.total_SD
      				, 	agentName			= t_A.UserName; 
                                     
   				DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
   				CREATE TEMPORARY TABLE temp_CurChatHistory AS
   				SELECT 	DISTINCT ChatHistoryId
   				FROM 	tt_ChatHistory
   				WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;    
                   
   				DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory_1; 
   				CREATE TEMPORARY TABLE temp_CurChatHistory_1 AS
   				SELECT 	SUM(answeredDuration ) AS responseTime
   				FROM 	tt_ChatHistory
   				WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;    
   
   				DROP TEMPORARY TABLE IF EXISTS temp_PrevChatHistory; 
   				CREATE TEMPORARY TABLE temp_PrevChatHistory as
   				SELECT 	DISTINCT (ChatHistoryId) as ChatHistoryId
   				FROM 	tt_ChatHistory
   				WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                   
				DROP TEMPORARY TABLE IF EXISTS temp_PrevChatHistory_1; 
   				CREATE TEMPORARY TABLE temp_PrevChatHistory_1 as
   				SELECT 	SUM(answeredDuration) AS responseTime
   				FROM 	tt_ChatHistory
   				WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                   
   				DROP TEMPORARY TABLE IF EXISTS temp_PrevHandled; 
   				CREATE TEMPORARY TABLE temp_PrevHandled as
   				SELECT 	SUM((Duration/1000)+afterChatWorkTime) AS PrevHandledTime
   				FROM 	tt_ChatHistory
   				WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                 
   				SELECT 	COUNT(ChatHistoryId)
   				INTO 	v_CurTotalCount 
   				FROM	temp_CurChatHistory; 
                   
				SELECT COUNT(ChatHistoryId)
				INTO 	v_PrevTotalCount  
				FROM	temp_PrevChatHistory;
                    
				SELECT 	SUM(CASE WHEN responseTime IS NOT NULL THEN responseTime ELSE 0 END )
				INTO 	v_CurResponseTime 
				FROM	temp_CurChatHistory_1;
                   
				SELECT 	SUM(CASE WHEN responseTime IS NOT NULL THEN responseTime ELSE 0 END )
				INTO 	v_PreResponseTime 
				FROM	temp_PrevChatHistory_1;
                   
				SELECT 	SUM(Handled)
   				INTO 	v_CurHandledTime 
   				FROM	temp_ChatHistory;
                   
   				SELECT 	SUM(PrevHandledTime)
   				INTO 	v_PreHandledTime 
   				FROM	temp_PrevHandled;
   								
   				
   				
                    
      				SELECT SUM(v_currentResponseTime), SUM(v_currentHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(averageQueueWaitingtime),sum(maximumQueueWaitingtime),sum(firstChatResolution),SUM(CustomerSatisfaction),sum(agentIdleTime)
      				INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount, v_CurrentMaximumHandledCount,v_CurrenttotalACWCount,v_CurrentaverageQueueWaitingCount,v_CurrentMaximumQueueWaitingCount,v_CurrentfirstChatResolutionCount,v_CurrentSentimentalScore,v_CurrentAgentIdleTimeCount
      				FROM 	temp_chatHistory_calc ;                                        
                                            
      				SELECT 	SUM(v_previousResponseTime), SUM(v_previousHandledTime), SUM(MaximumHandledTime),sum(totalACWTime),sum(averageQueueWaitingtime),sum(maximumQueueWaitingtime),sum(firstChatResolution),SUM(CustomerSatisfaction),sum(agentIdleTime)
      				INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount, v_PrevMaximumHandledCount,v_PrevtotalACWCount,v_PrevaverageQueueWaitingCount,v_PrevMaximumQueueWaitingCount,v_PrevfirstChatResolutionCount,v_PreSentimentalScore,v_PrevAgentIdleTimeCount
      				FROM 	temp_chatHistory_calc ;                     
      
      				SELECT sum(availableTime),sum(totalTalktime)
      				INTO   v_CurrentavailableCount,v_CurrenttotalTalkCount
      				FROM 	temp_chatHistory_calc  ;    
      
      				SELECT sum(availableTime),sum(totalTalktime)
      				INTO   v_PreavailableCount,v_PretotalTalkCount
      				FROM 	temp_chatHistory_calc  ;     
    
      				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_1;
      				CREATE TEMPORARY TABLE temp_chatHistory_calc_1 AS
      				SELECT 															
      				U.queueName 																	                AS queueName,
                     a.queueId																						AS queueId
      				,sum(a.agentIdleTime)         																	AS agentIdleTime
					,sum(a.NoOfChats) 																				AS NoOfChats
    				,sum(a.averageResponseTime)   																	AS averageResponseTime
    				,sum(a.averageHandledTime)					                                                    AS averageHandledTime
      				,sum(a.MaximumHandledTime)    																	AS MaximumHandledTime
      				,sum(a.totalACWTime)          																	AS totalACWTime
      				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               	AS averageHoldtime                                  
      				,sum(a.averageQueueWaitingtime)                                                                 AS averageQueueWaittime
      				,sum(a.maximumQueueWaitingtime)                                  								AS maximumQueueWaittime
      				,sum(CASE WHEN (a.totalTalktime/a.availableTime)*100 IS NOT NULL 
								THEN (a.totalTalktime/a.availableTime)*100 ELSE 0 END)   							AS occupancyRate                                      
      				,SUM(a.firstChatResolution)                                                                	  	AS firstChatResolution
      				,sum(a.IncomingChats)																			AS IncomingChats
      				,sum(a.CustomerSatisfaction)                                                                    AS CustomerSatisfaction
      				,sum(a.afterChatWorkTime)																		AS afterChatWorkTime					
      				,sum(a.callDuration)																			AS callDuration
      				,sum(a.availableTime)																			AS availableTime
                    ,sum(respondedChat)  																			AS respondedChat
    				,sum(answeredChat)																				AS answeredChat
      			FROM 	temp_chatHistory_calc	a
				JOIN     temp_AllqueueId		U ON U.qid = a.queueId
      			GROUP BY U.queueName,a.queueId;   	
               
               DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_prev_1;
      				CREATE TEMPORARY TABLE temp_chatHistory_calc_prev_1 AS
      				SELECT 															
      				U.queueName 																	                AS queueName
					,sum(NoOfChats)   																				AS NoOfChats
      				,sum(a.agentIdleTime)         																	AS agentIdleTime
    				,sum(a.averageResponseTime)   																	AS averageResponseTime
    				,sum(a.averageHandledTime)					                                                    AS averageHandledTime
      				,sum(a.MaximumHandledTime)    																	AS MaximumHandledTime
      				,sum(a.totalACWTime)          																	AS totalACWTime
      				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               	AS averageHoldtime                                  
      				,sum(a.averageQueueWaitingtime)                                                                 AS averageQueueWaittime
      				,sum(a.maximumQueueWaitingtime)                                                                 AS maximumQueueWaittime
      				,SUM(a.firstChatResolution)                                                                	  	AS firstChatResolution
      				,sum(a.IncomingChats)																			AS IncomingChats
      				,sum(a.CustomerSatisfaction)                                                                    AS CustomerSatisfaction
      				,sum(a.afterChatWorkTime)																		AS afterChatWorkTime					
      				,sum(a.callDuration)																			AS callDuration
                    ,sum(respondedChat)  																			AS respondedChat
    				,sum(answeredChat)																				AS answeredChat
      			FROM 	temp_chatHistory_calc_prev 	a
      			JOIN     temp_AllqueueId 			U ON U.qid = a.queueId	
      			GROUP BY U.queueName;   	
         
      			select  
      			sum(NoOfChats),sum(answeredChat),sum(agentIdleTime), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
      			sum(averageQueueWaittime), sum(maximumQueueWaittime), sum(occupancyRate), sum(firstChatResolution), sum(CustomerSatisfaction),sum(IncomingChats),
      			sum(callDuration),sum(afterChatWorkTime),sum(availableTime)
      			INTO
      			v_count,v_answerChat,v_agentIdleTime, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
      			v_averageQueueWaittime, v_maximumQueueWaittime, v_occupancyRate, v_firstChatResolution, v_CustomerSatisfaction,v_IncomingChats,
      			v_callDuration,v_afterChatWorkTime,v_availableTime
      			FROM temp_chatHistory_calc_1;  
               
               select  
      			sum(NoOfChats),sum(answeredChat), sum(averageResponseTime), sum(averageHandledTime)
      			INTO
      			v_prvcount,v_prevAnswerChat, v_prevAverageResponseTime, v_prevAverageHandledTime
      			FROM temp_chatHistory_calc_prev_1; 
   
   			SELECT 	CASE WHEN IFNULL(v_answerChat,0) = 0 THEN 0 ELSE (v_averageResponseTime/v_answerChat) END,
   					CASE WHEN IFNULL(v_count,0) = 0 THEN 0 ELSE (v_averageHandledTime/v_count) END
			INTO v_CurrentTotalCount,v_currentAVGHandleTime;
               
   			SELECT CASE WHEN IFNULL(v_prevAnswerChat,0) = 0 THEN 0 ELSE (v_prevAverageResponseTime/v_prevAnswerChat) END,
   					CASE WHEN IFNULL(v_prvcount,0) = 0 THEN 0 ELSE (v_prevAverageHandledTime/v_prvcount) END
			INTO v_PreviousTotalCount,v_prevAVGHandleTime;
                 
   			SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 then null else v_PrevAverageResponseCount end;
   			SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 then null else v_PrevaverageHandledCount end;
   			SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0 then null else v_PreSentimentalScore end;
   		
   			SET 	v_DiffAverageResponsePercent  	= CASE WHEN v_PreviousTotalCount = 0 THEN 0 ELSE (IFNULL(v_CurrentTotalCount, 0) - v_PreviousTotalCount) / v_PreviousTotalCount * 100 END  
				,v_DiffAverageHandledPercent  		= CASE WHEN v_prevAVGHandleTime = 0 THEN 0 ELSE (IFNULL(v_currentAVGHandleTime, 0) - v_prevAVGHandleTime) / v_prevAVGHandleTime * 100 END
				,v_DiffSentimentalScorePercent 		= (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;        
   
   			SELECT * FROM temp_AllqueueId;
   
   			SELECT    SUM(averageResponseTime) ,SUM(averageHandledTime) INTO v_CurrentaverageResponseCount,v_CurrentaverageHandledCount               
   			FROM       temp_chatHistory_calc_1;
   
   			SELECT 	IFNULL(v_CurrentaverageResponseCount/v_answerChat,0) 		AS 'CurrentAverageResponseCount',
   					IFNULL(v_DiffAverageResponsePercent,0) 		        		AS 'DiffAverageResponsePercent',
   					IFNULL(v_CurrentaverageHandledCount/v_count,0) 			    AS 'CurrentAverageHandledCount',
   					IFNULL(v_DiffAverageHandledPercent,0) 						AS 'DiffAverageHandledPercent',
   					IFNULL(v_CurrentSentimentalScore,0) 						AS 'CurrentCustomerSatisfactionCount',
   					IFNULL(v_DiffSentimentalScorePercent,0) 					AS 'DiffCustomerSatisfactionPercent';                   
   
   	 
      			select 'All Queue'													 						AS queueName,	
      			v_agentIdleTime 												 	 						AS	agentIdleTime, 
      			v_averageResponseTime/v_count                                   							AS  AverageresponseTime,
      			v_averageHandledTime/v_count                                         						AS  AverageHandledTime, 
      			v_MaximumHandledTime                                               	 						AS  MaximumHandledTime,
      			v_totalACWTime                                                       						AS  TotalACW, 
      			v_averageHoldtime                                                    						AS  averageHoldtime,
      			v_averageQueueWaittime                                               						AS   AverageQueueWaiting,
      			v_maximumQueueWaittime                                               						AS   MaximumQueueWaiting,
      			IFNULL(round(((v_callDuration + (v_afterChatWorkTime * 1000)) / v_availableTime )*100),0)	AS   occupancyrate,
      			v_callDuration	 																			AS   callDuration,
      			v_afterChatWorkTime	 																		AS   afterChatWorkTime,
      			v_availableTime	 																			AS   availableTime,
      			IFNULL(round((v_firstChatResolution /v_IncomingChats) * 100  ),0)             				AS  firstChatResolution,
      			IFNULL(v_CustomerSatisfaction,0)															AS CustomerSatisfaction
      		UNION ALL
      			SELECT DISTINCT(U.queueName)																AS  queueName, 
      			sum(agentIdleTime) 																			AS  agentIdleTime,
      			sum(averageResponseTime/NoOfChats)                               							AS  AverageresponseTime,
      			sum(averageHandledTime/NoOfChats)                               							AS AverageHandledTime, 
      			sum(MaximumHandledTime)                                             						AS MaximumHandledTime, 
      			sum(totalACWTime)                                                   						AS  TotalACW, 
      			sum(averageHoldtime)                                                						AS  averageHoldtime, 
      			sum(averageQueueWaittime)                                           						AS AverageQueueWaiting,
      			sum(maximumQueueWaittime)                                           						AS MaximumQueueWaiting,
      			IFNULL(round(((sum(callDuration) + (sum(afterChatWorkTime) * 1000)) / sum(availableTime) )*100),0)	AS   occupancyrate,
      			sum(callDuration)	 																		AS   callDuration,
      			sum(afterChatWorkTime)	 																	AS   afterChatWorkTime,
      			sum(availableTime)	 																		AS   availableTime,
      			Ifnull(round(sum(firstChatResolution/IncomingChats) *100 ),0)                 			    AS firstChatResolution,
      			IFNULL(sum(CustomerSatisfaction),0)															AS CustomerSatisfaction
      			FROM 
      			temp_chatHistory_calc_1 a
  JOIN     temp_AllqueueId 			    U ON U.qid = a.queueId	
      			GROUP BY U.queueName;   
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_chat_performances_metrics` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_queue_chat_performances_metrics`(
 			p_startTmpstmp BIGINT,    
            p_endTmpstmp BIGINT,
            p_domainId INT,
            p_columnname varchar(155) 
        )
BEGIN
			DECLARE v_startTmpstmp 					DATETIME;
			DECLARE v_endTmpstmp 					DATETIME;
			DECLARE v_startTime	 				    DATETIME;
			DECLARE v_endTime	 					DATETIME;
			DECLARE v_currenttimestamp 				BIGINT;
			DECLARE v_previous_timestamp 			BIGINT;
			DECLARE v_oneday_previous_timestamp 	BIGINT;
			DECLARE v1_count_currentdata 			BIGINT;
			DECLARE v2_count_pastdata 			    BIGINT;
			DECLARE v_coulumnname                   VARCHAR(150);
                 
 			SET v_coulumnname=p_columnname;
 			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
 			CREATE TEMPORARY TABLE temp_Intervals (
 				 starttime DATETIME,
 				 endtime   DATETIME
 			);
          
 			 SET v_startTmpstmp := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day)	,from_unixtime(p_startTmpstmp/1000));
             SET v_endTmpstmp := if(v_endTmpstmp is null,now(),from_unixtime(p_endTmpstmp/1000));
              
              SET v_startTime = v_startTmpstmp;
              SET v_endTime = DATE_ADD(v_startTime, INTERVAL 59 second);
              
             WHILE v_startTime < v_endTmpstmp 
             DO      
 				INSERT INTO temp_Intervals (starttime, endtime)
 				VALUES (v_startTime, v_endTime);
                
 				SET v_startTime := DATE_ADD(v_startTime, INTERVAL 1 minute);
      		    SET v_endTime := DATE_ADD(v_endTime, INTERVAL 1 minute);
 			END WHILE;
              
              DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
              CREATE TEMPORARY TABLE temp_ChatHistory
              SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
              FROM 	tb_ChatHistory H 
              WHERE 	H.domainId = p_domainId
              AND  	H.sessionStartTime BETWEEN p_startTmpstmp AND p_endTmpstmp
              group by H.sessionStartTime;
              
 			
              SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
              SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
              SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;
 
 


       
IF p_columnname = 'ResponsesTime'
     THEN
 		
 		
        select case when sum(SDH.answeredDuration)    is not null then sum(SDH.answeredDuration)    else '0' end as  ResponsesTime
 		INTO 	v1_count_currentdata 
 		FROM 	tb_ChatHistory 				SH
		JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId 
 		WHERE 	SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
 		and 	SH.domainId	= p_domainId
           LIMIT 1;
         
 		
 		select case when sum(SDH.answeredDuration)    is not null then sum(SDH.answeredDuration)    else '0' end as  ResponsesTime
 		INTO 	v2_count_pastdata 
		FROM 	tb_ChatHistory 				SH
		JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId 
 		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 		and 	SH.domainId	= p_domainId
           LIMIT 1;    
	ELSEIF p_columnname = 'HandledTime'
     THEN
 		
 		SELECT 	CASE when a.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 1 else 0 end 		AS HandledTime
 		INTO 	v1_count_currentdata 
 		FROM 	disposition_status a
        join 	tb_ChatHistory   b    on b.domainId=a.domainId
 		WHERE 	b.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
 		and 	b.domainId	= p_domainId
         LIMIT 1;

 		
 		SELECT 	CASE when a.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 1 else 0 end 		AS HandledTime
 		INTO 	v2_count_pastdata 
 		 		FROM 	disposition_status a
        join 	tb_ChatHistory   b    on b.domainId=a.domainId
 		WHERE 	b.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
 		and 	b.domainId	= p_domainId
           LIMIT 1;   
           
         ELSEIF p_columnname = 'ACWTime'
     THEN
 		
 	SELECT CASE WHEN SUM(b.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(b.afterChatWorkTime)/COUNT(1) ELSE '0' END         ACWTime 
 		INTO 	v1_count_currentdata
 		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
 		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 		and 	a.domainId	= p_domainId
           LIMIT 1;
         
 		
 		SELECT CASE WHEN SUM(b.afterChatWorkTime)/COUNT(1) IS NOT NULL THEN SUM(b.afterChatWorkTime)/COUNT(1) ELSE '0' END         ACWTime 
 		INTO 	v2_count_pastdata 
 		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
 		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 		and 	a.domainId	= p_domainId
           LIMIT 1;
           
	ELSEIF p_columnname = 'queueWaitingtime'
     THEN
 		
 		SELECT   CASE WHEN (queueDuration)  IS NOT NULL THEN (queueDuration)  ELSE '0' END         queueWaitingtime 
 		INTO 	v1_count_currentdata 
 		FROM 	tb_ChatHistory
 		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
 		and 	domainId	= p_domainId
           LIMIT 1;
         
 		
 		SELECT CASE WHEN (queueDuration) IS NOT NULL THEN (queueDuration)  ELSE '0' END         queueWaitingtime
 		INTO 	v2_count_pastdata 
 		FROM 	tb_ChatHistory
 		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 		and 	domainId	= p_domainId
           LIMIT 1;
           
 	ELSEIF p_columnname = 'HoldTime'
     THEN
 		
 		SELECT   CASE WHEN (AgentHoldDuration)  IS NOT NULL THEN (AgentHoldDuration)  ELSE '0' END         HoldTime 
 		INTO 	v1_count_currentdata 
 		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
 		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 		and 	a.domainId	= p_domainId
           LIMIT 1;
         
 		
 		SELECT CASE WHEN (AgentHoldDuration) IS NOT NULL THEN (AgentHoldDuration)  ELSE '0' END         HoldTime
 		INTO 	v2_count_pastdata 
 		FROM 	tb_ChatHistory a join tb_ChatDurationHistory b on a.ChatHistoryId= b.ChatHistoryId
 		WHERE 	a.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 		and 	a.domainId	= p_domainId
           LIMIT 1;      
           
           
  END IF;        
 		SELECT v_coulumnname 								AS  										metric
        ,       v1_count_currentdata																	currentdata
 		,		v2_count_pastdata																		pastdata
 		,		(v1_count_currentdata - v2_count_pastdata) 												dataDifference 
         ,		(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	
   
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_facebook_inbound_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_facebook_inbound_trendChart`(
		p_domainId 			INT,
    	p_datetype 			INT,            
		p_startTmpstmp		DATETIME,
		p_endTmpstmp		DATETIME,
    	p_columnName    	VARCHAR(200),    
    	p_queueId 			TEXT
)
begin

	DECLARE v_startDateTime			DATETIME;
   	DECLARE v_endDateTime			DATETIME;     
   	DECLARE v_datetimeInterval		SMALLINT;    
   	DECLARE v_startDateTimePast		DATETIME;
   	DECLARE v_endDateTimePast		DATETIME;
        
   	DECLARE v_startTimestampPast	BIGINT;
   	DECLARE v_endTimestampPast		BIGINT;      
   	DECLARE v_startTimestamp		BIGINT;
   	DECLARE v_endTimestamp			BIGINT;
   	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
       
   	DROP TEMPORARY TABLE IF EXISTS tmp_result;
   	CREATE TEMPORARY TABLE tmp_result(
   		reportAge			VARCHAR(20)
   		,startDateTime		DATETIME
   		,endDateTime		DATETIME
   		,callCount			INT
   	);
    
    IF p_datetype = 1 
        THEN 	
    		SET v_startDateTime = CAST(v_curDate AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
    	END IF;
    	IF p_datetype = 2 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
    	END IF;
    	IF p_datetype = 3 
         THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = DATE_ADD(CAST(v_curDate AS DATE), INTERVAL '23:59:00' HOUR_SECOND); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = DATE_ADD(DATE_ADD(v_startDateTime, INTERVAL -1 DAY), INTERVAL '23:59:00' HOUR_SECOND ) ;
    	END IF;
    	IF p_datetype = 4 
        THEN 
    		SET v_startDateTime = p_startTmpstmp; 
   		SET v_endDateTime 	= p_endTmpstmp; 
            
           SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
            
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    	END IF;
        
          IF p_queueId IS NOT NULL 
        THEN
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
    		CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
        ELSE
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
           CREATE TEMPORARY TABLE temp_queueIDs
    		SELECT 	qid	AS queueId
   		FROM 	queue
           WHERE 	domainId = p_domainId;
        END IF;
        
           DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
        CREATE TEMPORARY TABLE tmp_Disposition
        SELECT did, dispositionName
        FROM 	disposition_status
        WHERE	domainId		= p_domainId
        AND	dispositionName	= 'Caller Disconnected';   
        
        IF p_datetype IN (1,2)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH RECURSIVE CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	endDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
    	ELSEIF p_datetype IN (3,4)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH recursive CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	startDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
        END IF;
        
         ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
          UPDATE tmp_timings
        SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
    		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
            
    	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
   	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
   	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
   	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
    
      DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory;	
   	CREATE TEMPORARY TABLE tmp_FacebookDurationHistory
   	SELECT 	CH.FacebookHistoryId
   		,	CH.sessionStartTime
   		,	CH.IsMissed
   		,	CH.dispositionId        
   		,	CH.Duration
         ,   ifnull(CH.dialDuration,0)				  				    	      AS responseTime        
    FROM      tb_FacebookHistory 			 CH
	JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CH.QueueId	
   	WHERE 	CH.domainId 		= p_domainId
   	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
  	AND 	CH.IsInBound		= 1;
    
  
    
      	DROP TEMPORARY TABLE IF EXISTS tmp_FacebookHistory;	
    	CREATE TEMPORARY TABLE tmp_FacebookHistory
       SELECT 	DISTINCT 
    			CDH.FacebookHistoryId 
    		, 	CDH.sessionStartTime
			,   CDH.responseTime
    	FROM 	tmp_FacebookDurationHistory CDH; 
        
    
        
         ALTER TABLE tmp_FacebookHistory ADD IsMissed 	TINYINT default 0;
        ALTER TABLE tmp_FacebookHistory  ADD IsAnswered 	TINYINT default 0;
        ALTER TABLE tmp_FacebookHistory  ADD IsAbandoned	TINYINT default 0;
        
        CREATE INDEX ix_tmp_CallHistory        ON tmp_FacebookHistory (FacebookHistoryId);
        CREATE INDEX ix_tmp_CallDurationHistory ON tmp_FacebookDurationHistory (FacebookHistoryId);
        
            UPDATE tmp_FacebookHistory			CH
        JOIN 	tmp_FacebookDurationHistory	CDH	ON CH.FacebookHistoryId	= CDH.FacebookHistoryId  
		LEFT JOIN tmp_Disposition		    D	ON CDH.dispositionId = D.did			
        SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 	THEN 1 ELSE CH.IsMissed 	END
    		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE CH.IsAnswered 	END
 		,	CH.IsAbandoned	= CASE WHEN D.did IS NOT NULL 	THEN 1 ELSE  CH.IsAbandoned 	END;
        
        
         IF p_columnName = 'Received Chats'
        THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'				AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	SUM(CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
    		FROM 	tmp_timings			    t_T	
    		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	SUM(CASE WHEN CH.FacebookHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
	ELSEIF p_columnName = 'Missed Chats'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsMissed),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsMissed),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime; 
            
	ELSEIF p_columnName = 'Responded Chats'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	 IFNULL(CH.responseTime, 0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.responseTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(CH.responseTime,0)	AS callCount    
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.responseTime;  
            
		ELSEIF p_columnName = 'Abandoned Chats'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	 IFNULL(SUM(CH.IsAbandoned),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.IsAbandoned;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	 IFNULL(SUM(CH.IsAbandoned),0)	AS callCount
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.IsAbandoned;       
         
         
        END IF;
		
        SELECT  *
       FROM 	tmp_result 
       WHERE 	reportAge = 'Current';    
       
       SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Past';
        
   	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
   	INTO 	v_currentCount, v_pastCount		
   	FROM 	tmp_result;
    
       SELECT 	
  			p_columnName     														AS metric
		   ,  v_currentCount													    AS currentTotal
		   , 	v_pastCount															AS pastTotal
           ,	(v_currentCount - v_pastCount) 										AS totalDifference
           ,	IFNULL((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)	    AS  Percentage;	
            
end ;;
DELIMITER ;
