CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_Facebook_performances_analysis_metrics`(
   p_startTmpstmp    BIGINT,
	p_endTmpstmp 		BIGINT,
	p_domainId 		INT,
	p_queueId 		VARCHAR(250),
	p_offset 			INT,
	p_limit 			INT
)
begin

	  DECLARE v_offset 										INT;	  	
      DECLARE v_CurrentStartTmpstmp 						BIGINT;
      DECLARE v_CurrentEndTmpstmp 							BIGINT;
      DECLARE v_PrevStartTmpstmp 							BIGINT;
      DECLARE v_PrevEndTmpstmp 								BIGINT; 
      DECLARE v_TmpstmpInterval 							BIGINT;	
      DECLARE v_PrevAverageResponseCount 					BIGINT;	
      DECLARE v_CurrentAverageResponseCount 				BIGINT;	        
      DECLARE v_DiffAverageResponsePercent 					INT;
      DECLARE v_PrevAverageHandledCount 					BIGINT;	
      DECLARE v_CurrentAverageHandledCount 					BIGINT;
      DECLARE v_DiffAverageHandledPercent 					BIGINT;          
      DECLARE v_PrevCustomerSatisfactionCount 				BIGINT;	
      DECLARE v_CurrentCustomerSatisfactionCount 			BIGINT;
      DECLARE v_DiffCustomerSatisfactionPercent 			BIGINT;  	     
      DECLARE v_CurrentMaximumHandledCount 					BIGINT;	
      DECLARE v_CurrentTotalACWCount 						BIGINT;
      DECLARE v_CurrentAverageQueueWaitingCount 			BIGINT;
      DECLARE v_CurrentMaximumQueueWaitingCount 			BIGINT;
      DECLARE v_CurrentansweredCallCount 					BIGINT;
      DECLARE v_CurrentoccupancyrateCount 					BIGINT;
      DECLARE v_CurrentagentUtilizationCount 				BIGINT;
      DECLARE v_currentfirstChatResolutionCount 			BIGINT;
      DECLARE v_CurrentTotalCount							INT;
    
    

		SET v_offset = p_limit * p_offset; 
  
			IF IFNULL(p_startTmpstmp, 0) = 0 THEN 
				SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; 
			ELSE 
				SET v_CurrentStartTmpstmp = p_startTmpstmp; 
			END IF; 
            
			IF IFNULL(p_endTmpstmp, 0) = 0 THEN 
				SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; 
			ELSE 
				SET v_CurrentEndTmpstmp = p_endTmpstmp; 
			END IF; 
            
			SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
			SET v_PrevEndTmpstmp = v_CurrentStartTmpstmp - 1;
			SET v_PrevStartTmpstmp = v_PrevEndTmpstmp - v_TmpstmpInterval;
            

            
			 DROP TEMPORARY TABLE IF EXISTS temp_queueIds;
				CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
                
			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;
				CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                
			 CALL split(p_queueId, ','); 
             INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable;
  
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
      CREATE TEMPORARY TABLE temp_AllqueueId   
      SELECT qid, name AS queueName,domainId 
      FROM queue    
      WHERE domainId = p_domainId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  
      DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
      CREATE TEMPORARY TABLE temp_AvailableDisposition (
          DispositionId INT,
          DispositionStatus VARCHAR(100),
          DispositionCategory TINYINT
      ); 
      
       INSERT INTO temp_AvailableDisposition 
      SELECT 
          did AS DispositionId,
          dispositionName AS DispositionStatus,
          CASE 
              WHEN dispositionName = 'Opened' THEN 2
              WHEN dispositionName IN ('Resolved', 'Unresolved', 'Closed', 'Follow-up', 'Disconnected', 'Transferred') THEN 3
              WHEN dispositionName = 'Discarded' THEN 4
              WHEN dispositionName = 'Resolved' THEN 5
          END AS DispositionCategory
      FROM disposition_status
      WHERE domainId = p_domainId; 
      
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
      DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
      CREATE TEMPORARY TABLE temp_chatHistory AS
      SELECT 
          CAST(FROM_UNIXTIME(CH.sessionStartTime / 1000) AS DATE) 						AS SessionDate,
          Q.qid  																		AS queueId,
          Q.name 																		AS queueName,
          IFNULL(CH.repliedDate - CH.createdAt, NULL) 									AS responseTime,
          CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 						AS Handled,
          CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END 						AS firstChatResolution,
          CH.SentimentalScore,
          CH.afterFacebookWorkTime,
          null              															AS QueueWaitTime,
          SUM(CASE WHEN CH.IsInBound = 1 AND CH.Duration > 0 THEN 1 ELSE 0 END) 	AS answeredCall,
          SUM(CH.dialDuration) 														AS totalTalktime,
          SUM(CH.Duration) 															AS Duration,
          CH.IsInBound
      FROM tb_FacebookHistory CH		
   
      LEFT JOIN queue Q ON CH.queueId = Q.qid
      LEFT JOIN temp_AvailableDisposition t_D ON CH.dispositionId = t_D.DispositionId            
      LEFT JOIN temp_queueIds t_Q ON Q.qid = t_Q.queueId 
      WHERE CH.domainId = p_domainId
      AND CH.sessionStartTime BETWEEN  v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
      AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
      GROUP BY 
          SessionDate, queueName, queueId, responseTime, Handled, CH.SentimentalScore,
          CH.afterFacebookWorkTime, QueueWaitTime, t_D.DispositionCategory, CH.IsInBound
      LIMIT v_offset, p_limit;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      
  				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
    				CREATE TEMPORARY TABLE temp_AvailableStates AS
    				SELECT   
    						CASE 
    							WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
    							ELSE 2 
    						    END AS tt_Time,
    						ST.ext,
    						ST.domainId,
    						from_unixtime(ST.startTimestamp/1000),
    						ST.stateDuration as SD
    				FROM     state_timer ST 
    				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
    				WHERE    ST.domainId = p_domainId
    				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
                    
               
                    
				ALTER TABLE temp_chatHistory ADD COLUMN availableTime		BIGINT;
  				ALTER TABLE temp_chatHistory ADD COLUMN agentName			VARCHAR(150); 
                
                UPDATE temp_chatHistory SH_C
   		    JOIN temp_AllqueueId t_A ON SH_C.queueId = t_A.qid
   		    JOIN (
   			SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
   			FROM temp_AvailableStates
   			GROUP BY ext, domainId
   		    ) tt_AV ON  tt_AV.domainId = t_A.domainId     
   		    SET SH_C.availableTime = tt_AV.total_SD;
            
        
            
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
      DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_cal; 
      CREATE TEMPORARY TABLE temp_chatHistory_cal AS       
      SELECT
          queueName,    
          queueId,
          AVG(responseTime) 																								AS averageResponseTime,
          CASE WHEN AVG(Duration + afterFacebookWorkTime) !=0 THEN AVG(Duration + afterFacebookWorkTime) / 1000 ELSE 0  END AS averageHandlingTime,
          CASE WHEN SUM(Duration + afterFacebookWorkTime) !=0 THEN SUM(Duration + afterFacebookWorkTime) / 1000 ELSE 0	END AS maximumHandlingTime,
          CASE WHEN SUM(afterFacebookWorkTime) !=0 THEN SUM(afterFacebookWorkTime) / 1000  						ELSE 0 	END AS totalACWTime,
          ifnull(AVG(QueueWaitTime),0) 																						AS averageQueueWaitTime,
          ifnull(sum(QueueWaitTime),0) 																						AS maximumQueueWaitTime,            
          SUM(CASE WHEN IsInBound = 1 AND Duration > 0 THEN 1 ELSE 0 END) 													AS answeredCall,
          0 																												AS agentUtilization,
          CASE WHEN SUM(totalTalktime) !=0  and SUM(availableTime) != 0 THEN (SUM(totalTalktime) / SUM(availableTime)) * 100 	ELSE 0 END	AS occupancyrate,
		  COALESCE(SUM(SentimentalScore), 0)																				AS CustomerSatisfaction,
          SUM(firstChatResolution) 																							AS firstChatResolution
      FROM temp_chatHistory
      GROUP BY queueName, queueId;
      
     
      
         DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
      CREATE TEMPORARY TABLE temp_PrevCallHistory AS
      SELECT responseTime, SentimentalScore
      FROM temp_chatHistory
      WHERE SessionDate BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
      
      
  
      DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
      CREATE TEMPORARY TABLE temp_CurCallHistory AS
      SELECT responseTime, SentimentalScore
      FROM temp_chatHistory
      WHERE SessionDate BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
      
   
      
         SELECT IFNULL(AVG(responseTime),0), IFNULL(SUM(SentimentalScore),0) AS SentimentalScore
      INTO v_PrevAverageResponseCount, v_PrevCustomerSatisfactionCount
      FROM temp_PrevCallHistory;        
  
	 
  
      SELECT IFNULL(AVG(responseTime),0), IFNULL(SUM(SentimentalScore),0) AS SentimentalScore
      INTO v_CurrentAverageResponseCount, v_CurrentCustomerSatisfactionCount                          
      FROM temp_CurCallHistory;      
      
  
      SELECT AVG(responseTime), SUM(SentimentalScore) AS SentimentalScore,
			CASE WHEN AVG(Duration + afterFacebookWorkTime) != 0 then AVG(Duration + afterFacebookWorkTime) / 1000 ELSE 0 END,
            CASE WHEN AVG(Duration + afterFacebookWorkTime) !=0 then AVG(Duration + afterFacebookWorkTime) / 1000 ELSE 0 END
      INTO v_PrevAverageResponseCount, v_PrevCustomerSatisfactionCount, v_PrevAverageHandledCount, v_CurrentAverageHandledCount
      FROM temp_chatHistory;           
  
	
    SET v_DiffCustomerSatisfactionPercent = case when IFNULL(v_PrevCustomerSatisfactionCount,0) !=0 THEN ((v_CurrentCustomerSatisfactionCount - v_PrevCustomerSatisfactionCount)/v_PrevCustomerSatisfactionCount) * 100 ELSE 0 END ;
      
	
       
        SELECT 
      sum(averageResponseTime),
      sum(averageHandlingTime),
      sum(maximumHandlingTime),
      SUM(totalACWTime),
      sum(averageQueueWaitTime),
      sum(maximumQueueWaitTime),
      sum(answeredCall),
      sum(occupancyrate),
      sum(agentUtilization),
      sum(firstChatResolution),
      CASE WHEN IFNULL(sum(answeredCall), 0) !=0 THEN sum(CustomerSatisfaction)/sum(answeredCall) ELSE 0 END,
      COUNT(*)
  INTO 
      v_CurrentAverageResponseCount, 
      v_CurrentAverageHandledCount, 
      v_CurrentMaximumHandledCount, 
      v_CurrentTotalACWCount,
      v_CurrentAverageQueueWaitingCount, 
      v_CurrentMaximumQueueWaitingCount, 
      v_CurrentansweredCallCount, 
      v_CurrentoccupancyrateCount,
      v_CurrentagentUtilizationCount,
      v_currentfirstChatResolutionCount,
      v_CurrentCustomerSatisfactionCount,
      v_CurrentTotalCount
      
  FROM 
      temp_chatHistory_cal;
      

   SELECT * FROM temp_AllqueueId;
  
      SELECT 
          IFNULL(v_CurrentAverageResponseCount, 0) 		AS CurrentAverageResponseCount,
          IFNULL(v_DiffAverageResponsePercent, 0)  		AS DiffAverageResponsePercent,
          IFNULL(v_CurrentAverageHandledCount, 0)  		AS CurrentAverageHandledCount,
          IFNULL(v_DiffAverageHandledPercent, 0)   		AS DiffAverageHandledPercent,
          IFNULL(v_CurrentCustomerSatisfactionCount, 0) 	AS CurrentCustomerSatisfactionCount,
          IFNULL(v_DiffCustomerSatisfactionPercent, 0) 	AS DiffCustomerSatisfactionPercent;
  
      SELECT
          'All Queue' 												AS queueName,
          IFNULL(v_CurrentAverageResponseCount, 0) 					AS AverageresponseTime,
          IFNULL(v_CurrentAverageHandledCount, 0)  					AS AverageHandledTime,
          IFNULL(v_CurrentMaximumHandledCount, 0)  					AS MaximumHandledTime,
          IFNULL(v_CurrentTotalACWCount, 0) 		 					AS TotalACW,
          IFNULL(v_CurrentAverageQueueWaitingCount, 0) 				AS AverageQueueWaiting,
          IFNULL(v_CurrentMaximumQueueWaitingCount, 0) 				AS MaximumQueueWaiting,
          IFNULL(v_CurrentansweredCallCount, 0) 						AS answeredCall,
          IFNULL(v_CurrentoccupancyrateCount, 0)			    		AS occupancyrate, 
          IFNULL(v_currentfirstChatResolutionCount, 0) 				AS firstChatResolution,
          IFNULL(v_CurrentCustomerSatisfactionCount, 0) 				AS CustomerSatisfaction
      UNION ALL     
      SELECT    
          U.queueName,
          t_SH.AverageresponseTime,
          t_SH.averageHandlingTime  							as averageHandlingTime,
          t_SH.maximumHandlingTime  							AS maximumHandlingTime,
          t_SH.totalACWTime   									as totalACWTime,
          t_SH.averageQueueWaitTime 							as averageQueueWaitTime,
          t_SH.maximumQueueWaitTime 							as maximumQueueWaitTime,
      
          t_SH.answeredCall,
          t_SH.occupancyrate,
          t_SH.firstChatResolution,
          t_SH.CustomerSatisfaction
      FROM temp_chatHistory_cal t_SH
      LEFT JOIN temp_AllqueueId U ON t_SH.queueId = U.qid;
  
  END ;;
DELIMITER ;
