      FROM temp_chatHistory
      GROUP BY queueName, queueId;
      
     
      
         DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
      CREATE TEMPORARY TABLE temp_PrevCallHistory AS
      SELECT responseTime, SentimentalScore
      FROM temp_chatHistory
      WHERE SessionDate BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
      
      
  
      DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
      CREATE TEMPORARY TABLE temp_CurCallHistory AS
      SELECT responseTime, SentimentalScore
      FROM temp_chatHistory
      WHERE SessionDate BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
      
   
      
         SELECT IFNULL(AVG(responseTime),0), IFNULL(SUM(SentimentalScore),0) AS SentimentalScore
      INTO v_PrevAverageResponseCount, v_PrevCustomerSatisfactionCount
      FROM temp_PrevCallHistory;        
  
	 
  
      SELECT IFNULL(AVG(responseTime),0), IFNULL(SUM(SentimentalScore),0) AS SentimentalScore
      INTO v_CurrentAverageResponseCount, v_CurrentCustomerSatisfactionCount                          
      FROM temp_CurCallHistory;      
      
  
      SELECT AVG(responseTime), SUM(SentimentalScore) AS SentimentalScore,
			CASE WHEN AVG(Duration + afterFacebookWorkTime) != 0 then AVG(Duration + afterFacebookWorkTime) / 1000 ELSE 0 END,
            CASE WHEN AVG(Duration + afterFacebookWorkTime) !=0 then AVG(Duration + afterFacebookWorkTime) / 1000 ELSE 0 END
      INTO v_PrevAverageResponseCount, v_PrevCustomerSatisfactionCount, v_PrevAverageHandledCount, v_CurrentAverageHandledCount
      FROM temp_chatHistory;           
  
	
    SET v_DiffCustomerSatisfactionPercent = case when IFNULL(v_PrevCustomerSatisfactionCount,0) !=0 THEN ((v_CurrentCustomerSatisfactionCount - v_PrevCustomerSatisfactionCount)/v_PrevCustomerSatisfactionCount) * 100 ELSE 0 END ;
      
	
       
        SELECT 
      sum(averageResponseTime),
      sum(averageHandlingTime),
      sum(maximumHandlingTime),
      SUM(totalACWTime),
      sum(averageQueueWaitTime),
      sum(maximumQueueWaitTime),
      sum(answeredCall),
      sum(occupancyrate),
      sum(agentUtilization),
      sum(firstChatResolution),
      CASE WHEN IFNULL(sum(answeredCall), 0) !=0 THEN sum(CustomerSatisfaction)/sum(answeredCall) ELSE 0 END,
      COUNT(*)
  INTO 
      v_CurrentAverageResponseCount, 
      v_CurrentAverageHandledCount, 
      v_CurrentMaximumHandledCount, 
      v_CurrentTotalACWCount,
      v_CurrentAverageQueueWaitingCount, 
      v_CurrentMaximumQueueWaitingCount, 
      v_CurrentansweredCallCount, 
      v_CurrentoccupancyrateCount,
      v_CurrentagentUtilizationCount,
      v_currentfirstChatResolutionCount,
      v_CurrentCustomerSatisfactionCount,
      v_CurrentTotalCount
      
  FROM 
      temp_chatHistory_cal;
      

   SELECT * FROM temp_AllqueueId;
  
      SELECT 
          IFNULL(v_CurrentAverageResponseCount, 0) 		AS CurrentAverageResponseCount,
          IFNULL(v_DiffAverageResponsePercent, 0)  		AS DiffAverageResponsePercent,
          IFNULL(v_CurrentAverageHandledCount, 0)  		AS CurrentAverageHandledCount,
          IFNULL(v_DiffAverageHandledPercent, 0)   		AS DiffAverageHandledPercent,
          IFNULL(v_CurrentCustomerSatisfactionCount, 0) 	AS CurrentCustomerSatisfactionCount,
          IFNULL(v_DiffCustomerSatisfactionPercent, 0) 	AS DiffCustomerSatisfactionPercent;
  
      SELECT
          'All Queue' 												AS queueName,
          IFNULL(v_CurrentAverageResponseCount, 0) 					AS AverageresponseTime,
          IFNULL(v_CurrentAverageHandledCount, 0)  					AS AverageHandledTime,
          IFNULL(v_CurrentMaximumHandledCount, 0)  					AS MaximumHandledTime,
          IFNULL(v_CurrentTotalACWCount, 0) 		 					AS TotalACW,
          IFNULL(v_CurrentAverageQueueWaitingCount, 0) 				AS AverageQueueWaiting,
          IFNULL(v_CurrentMaximumQueueWaitingCount, 0) 				AS MaximumQueueWaiting,
          IFNULL(v_CurrentansweredCallCount, 0) 						AS answeredCall,
          IFNULL(v_CurrentoccupancyrateCount, 0)			    		AS occupancyrate, 
          IFNULL(v_currentfirstChatResolutionCount, 0) 				AS firstChatResolution,
          IFNULL(v_CurrentCustomerSatisfactionCount, 0) 				AS CustomerSatisfaction
      UNION ALL     
      SELECT    
          U.queueName,
          t_SH.AverageresponseTime,
          t_SH.averageHandlingTime  							as averageHandlingTime,
          t_SH.maximumHandlingTime  							AS maximumHandlingTime,
          t_SH.totalACWTime   									as totalACWTime,
          t_SH.averageQueueWaitTime 							as averageQueueWaitTime,
          t_SH.maximumQueueWaitTime 							as maximumQueueWaitTime,
      
          t_SH.answeredCall,
          t_SH.occupancyrate,
          t_SH.firstChatResolution,
          t_SH.CustomerSatisfaction
      FROM temp_chatHistory_cal t_SH
      LEFT JOIN temp_AllqueueId U ON t_SH.queueId = U.qid;
  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_Facebook_performances_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_Facebook_performances_trendChart`(    	
		p_domainId 			INT,
    	p_datetype 			INT,            	
		p_startTmpstmp		DATETIME,
		p_endTmpstmp		DATETIME,
    	p_columnName    	VARCHAR(200),    	 
    	p_queueId 			TEXT
    )
BEGIN
    
    
   	DECLARE v_startDateTime			DATETIME;
   	DECLARE v_endDateTime			DATETIME;     
   	DECLARE v_datetimeInterval		SMALLINT;    
   	DECLARE v_startDateTimePast		DATETIME;
   	DECLARE v_endDateTimePast		DATETIME;
           
   	DECLARE v_startTimestampPast	BIGINT;
   	DECLARE v_endTimestampPast		BIGINT;      
   	DECLARE v_startTimestamp		BIGINT;
   	DECLARE v_endTimestamp			BIGINT;
   	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
       
   	DROP TEMPORARY TABLE IF EXISTS tmp_result;
   	CREATE TEMPORARY TABLE tmp_result(
   		reportAge			VARCHAR(20)
   		,startDateTime		DATETIME
   		,endDateTime		DATETIME
   		,callCount			INT
   	);    
    
    	IF p_datetype = 1 
        THEN 	
    		SET v_startDateTime = CAST(v_curDate AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
    	END IF;
    	IF p_datetype = 2 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
    	END IF;
    	IF p_datetype = 3 
         THEN 
			SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = date_add(cast(v_curDate as date), interval '23:59:00' hour_second); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = date_add(date_add(v_startDateTime, interval -1 day), interval '23:59:00' hour_second ) ; 
     	END IF;
    	IF p_datetype = 4 
        THEN 
    		SET v_startDateTime = p_startTmpstmp; 
   		SET v_endDateTime 	= p_endTmpstmp; 
            
           SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
            
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    	END IF;
        
        IF p_queueId IS NOT NULL 
        THEN
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
    		CALL split(p_queueId,','); 
            INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
        ELSE
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs
				SELECT 	qid	AS queueId
				FROM 	queue
				WHERE 	domainId = p_domainId;
        END IF;
        
        DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
        CREATE TEMPORARY TABLE tmp_Disposition
        SELECT did, dispositionName
        FROM 	disposition_status
        WHERE	domainId		= p_domainId
        AND	dispositionName	= 'Caller Disconnected';    
        
        IF p_datetype IN (1,2)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH RECURSIVE CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	endDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
    	ELSEIF p_datetype IN (3,4)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH recursive CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	startDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
        END IF;  
        
        ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
        
        UPDATE tmp_timings
        SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
    		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
            
    	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
   	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
   	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
   	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
     
    
     DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     CREATE TEMPORARY TABLE temp_AvailableDisposition (
         DispositionId INT,
         DispositionStatus VARCHAR(100),
         DispositionCategory TINYINT,
         domainId            INT
     ); 
                           
     INSERT INTO temp_AvailableDisposition 
     SELECT 
         did AS DispositionId,
         dispositionName AS DispositionStatus,
         CASE 
             WHEN dispositionName = 'Opened' THEN 2
             WHEN dispositionName IN ('Resolved', 'Unresolved', 'Closed', 'Follow-up', 'Disconnected', 'Transferred') THEN 3
             WHEN dispositionName = 'Discarded' THEN 4
             WHEN dispositionName = 'Resolved' THEN 5
         END AS DispositionCategory,
                 domainId
     FROM disposition_status
     WHERE domainId = p_domainId;    
    
 
    
     DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory_1;	
   	CREATE TEMPORARY TABLE tmp_FacebookDurationHistory_1
   	SELECT 	
         CAST(FROM_UNIXTIME(CH.sessionStartTime / 1000) AS DATE) 							AS SessionDate
 		,  CH.FacebookHistoryId
   		,	CH.sessionStartTime
   		,	CH.IsMissed
   		,	CH.dispositionId          
   		,	CH.Duration
         ,   IFNULL(CH.repliedDate - CH.createdAt, NULL) 									AS responseTime 
         , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 					   		AS Handled
         , 0                															    AS QueueWaitTime
         , CH.afterFacebookWorkTime
    FROM      tb_FacebookHistory 			 	CH   
    JOIN 	temp_queueIDs						Q			ON 	Q.queueId			= CH.queueId
  LEFT JOIN   temp_AvailableDisposition       t_D        	ON CH.dispositionId = t_D.DispositionId 	
															AND    CH.domainId =t_D.domainId
   	WHERE 	CH.domainId 		= p_domainId
   	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
	AND 	CH.IsInBound		= 1;   
     
      DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory;	
   	 CREATE TEMPORARY TABLE tmp_FacebookDurationHistory
      SELECT
 		FacebookHistoryId,
         dispositionId,
         sessionStartTime,
         AVG(responseTime) 																AS averageResponseTime,
         AVG(Duration + afterFacebookWorkTime) / 1000 									AS averageHandlingTime,
         SUM(Duration + afterFacebookWorkTime) / 1000 									AS maximumHandlingTime,
         SUM(afterFacebookWorkTime) / 1000 												AS totalACWTime,
         ifnull(AVG(QueueWaitTime),0) 													AS averageQueueWaitTime
     FROM tmp_FacebookDurationHistory_1
     group by FacebookHistoryId,sessionStartTime,dispositionId;
     
   	DROP TEMPORARY TABLE IF EXISTS tmp_FacebookHistory;	
    	CREATE TEMPORARY TABLE tmp_FacebookHistory
       SELECT 	DISTINCT 
    			CDH.FacebookHistoryId 
			,	CDH.dispositionId
    		, 	CDH.sessionStartTime
     
    	FROM 	tmp_FacebookDurationHistory CDH;    
     
 
 	   ALTER TABLE tmp_FacebookHistory  ADD averageResponseTime 	bigint default 0;
        ALTER TABLE tmp_FacebookHistory  ADD averageHandlingTime 	bigint default 0;
        ALTER TABLE tmp_FacebookHistory  ADD totalACWTime			bigint default 0;
        ALTER TABLE tmp_FacebookHistory  ADD averageQueueWaitTime    bigint default 0;
        
 		CREATE INDEX ix_tmp_CallHistory        ON tmp_FacebookHistory (FacebookHistoryId);
        CREATE INDEX ix_tmp_CallDurationHistory ON tmp_FacebookDurationHistory (FacebookHistoryId);     
        
		UPDATE tmp_FacebookHistory			CH
		JOIN 	tmp_FacebookDurationHistory	CDH	ON CH.FacebookHistoryId	= CDH.FacebookHistoryId  
		LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
		SET 	CH.averageResponseTime	= CDH.averageResponseTime,
		CH.averageHandlingTime	= CDH.averageHandlingTime,
		CH.totalACWTime	        = CDH.totalACWTime,
		CH.averageQueueWaitTime = CDH.averageQueueWaitTime;
         

 
  IF p_columnName = 'Avg. Response Time'
        THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'				AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageResponseTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		 GROUP BY t_T.startDateTime, t_T.endDateTime;
 
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageResponseTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
    		 GROUP BY t_T.startDateTime, t_T.endDateTime;
 
 ELSEIF p_columnName = 'Avg. Handle Time (AHT)'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageHandlingTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN  tmp_FacebookHistory	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageHandlingTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
         
  ELSEIF p_columnName = 'Total ACW Time'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(totalACWTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN  tmp_FacebookHistory	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(totalACWTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;       
         
      ELSEIF p_columnName = 'Avg. Queue Wait Time'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageQueueWaitTime),0)	    AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageQueueWaitTime),0)	    AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		 GROUP BY t_T.startDateTime, t_T.endDateTime;    
         END IF;       
        SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Current';    
       
       SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Past';
        
   	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
   	INTO 	v_currentCount, v_pastCount		
   	FROM 	tmp_result;
       
       SELECT 	
  			p_columnName     													AS metric
  		 ,  v_currentCount													    AS currentTotal
   		 , 	v_pastCount															AS pastTotal
           ,	(v_currentCount - v_pastCount) 										AS totalDifference
           ,	IFNULL((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)	    AS  Percentage;	
           
           
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_Facebook_Servicelevel_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
