/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_Facebook_Servicelevel_trendChart`(
		p_domainId 			INT,
      	p_datetype 			INT,                 
  		p_startTmpstmp		DATETIME,
  		p_endTmpstmp		DATETIME,
      	p_columnName    	VARCHAR(200),       
      	p_queueId 			TEXT

)
begin
		DECLARE v_startDateTime			DATETIME;
     	DECLARE v_endDateTime			DATETIME;     
     	DECLARE v_datetimeInterval		SMALLINT;    
     	DECLARE v_startDateTimePast		DATETIME;
     	DECLARE v_endDateTimePast		DATETIME;
          
     	DECLARE v_startTimestampPast	BIGINT;
     	DECLARE v_endTimestampPast		BIGINT;      
     	DECLARE v_startTimestamp		BIGINT;
     	DECLARE v_endTimestamp			BIGINT;
     	DECLARE v_curDate				DATETIME DEFAULT NOW();	
        DECLARE v_currentCount			INT;
        DECLARE v_pastCount				INT;
        
        DECLARE v_tot_cur_chat          INT;
		DECLARE v_tot_past_chat			INT;
        
        DROP TEMPORARY TABLE IF EXISTS tmp_result;
     	CREATE TEMPORARY TABLE tmp_result(
     		reportAge			VARCHAR(20)
     		,startDateTime		DATETIME
     		,endDateTime		DATETIME
     		,callCount			INT
     	);
        
              	IF p_datetype = 1 
          THEN 	
      		SET v_startDateTime = CAST(v_curDate AS DATE); 
      		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
      
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
      	END IF;
      	IF p_datetype = 2 
          THEN 
      		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
      
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
      	END IF;
      	IF p_datetype = 3 
          THEN 
      		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
             SET v_endDateTime = CAST(v_curDate AS DATE); 
              
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
      	END IF;
      	IF p_datetype = 4 
          THEN 
      		SET v_startDateTime = p_startTmpstmp; 
     		SET v_endDateTime 	= p_endTmpstmp; 
              
             SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
              
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
      		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
      	END IF;
        
             IF p_queueId IS NOT NULL 
          THEN
      		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
      		CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
          ELSE
      		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
             CREATE TEMPORARY TABLE temp_queueIDs
      		SELECT 	qid	AS queueId
     		FROM 	queue
             WHERE 	domainId = p_domainId;
          END IF;
          
             DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
          CREATE TEMPORARY TABLE tmp_Disposition
          SELECT did, dispositionName
          FROM 	disposition_status
          WHERE	domainId		= p_domainId
          AND	dispositionName	= 'Caller Disconnected';    
          
           IF p_datetype IN (1,2)
          THEN 
      		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
              CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
      		WITH RECURSIVE CTE_TIMINGS AS (
      			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
      			UNION ALL
      			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
      			FROM 	CTE_TIMINGS
      			WHERE 	endDateTime < v_endDateTime
      		)
      		SELECT * FROM CTE_TIMINGS;	
      	ELSEIF p_datetype IN (3,4)
          THEN 
      		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
              CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
      		WITH recursive CTE_TIMINGS AS (
      			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
      			UNION ALL
      			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
      			FROM 	CTE_TIMINGS
      			WHERE 	startDateTime < v_endDateTime
      		)
      		SELECT * FROM CTE_TIMINGS;	
          END IF; 
          
          ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
          
          UPDATE tmp_timings
          SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
      		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
              
      	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
     	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
     	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
     	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
        
         	DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory;	
     	CREATE TEMPORARY TABLE tmp_FacebookDurationHistory
     	SELECT 	CH.FacebookHistoryId
     		,	CH.sessionStartTime
     		,	CH.IsMissed
     		,	CH.dispositionId        
     		,	CH.dialDuration
			,   CH.Duration
            ,   CASE WHEN CH.dialDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END  	AS Total
			,   CASE WHEN CH.IsInBound =1 THEN 1 ELSE 0 END                       	AS incomingChats
     	FROM 	 tb_FacebookHistory 			 CH
     
      	LEFT JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CH.queueId	
     	WHERE 	CH.domainId 		= p_domainId
     	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
     
     
     
     
     DROP TEMPORARY TABLE IF EXISTS tmp_FacebookDurationHistory_cal;	
		CREATE TEMPORARY TABLE tmp_FacebookDurationHistory_cal
			select 
				incomingChats, FacebookHistoryId, sessionStartTime, IsMissed, dispositionId,
				dialDuration, Duration, 
				sum(Total/incomingChats)*100        	as SLAachieved ,
				100 - sum((Total/incomingChats)*100)  	as SLABleached
				FROM tmp_FacebookDurationHistory
				GROUP BY incomingChats, FacebookHistoryId, sessionStartTime, IsMissed, dispositionId,
				dialDuration, Duration; 
     
     
     	DROP TEMPORARY TABLE IF EXISTS tmp_FacebookHistory;	
      	CREATE TEMPORARY TABLE tmp_FacebookHistory
         SELECT 	DISTINCT 
      			CDH.FacebookHistoryId 
      		, 	CDH.sessionStartTime
      	FROM 	tmp_FacebookDurationHistory CDH;  
        
        
        
        	select count(Distinct FacebookHistoryId) into v_tot_cur_chat from tmp_FacebookHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;          
			select count(Distinct FacebookHistoryId) into v_tot_past_chat from tmp_FacebookHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;          

        
        
          
          ALTER TABLE tmp_FacebookHistory ADD IsMissed 		TINYINT default 0;
          ALTER TABLE tmp_FacebookHistory ADD IsAnswered 		TINYINT default 0;
          ALTER TABLE tmp_FacebookHistory ADD IsUnAnswered 	TINYINT default 0;
          ALTER TABLE tmp_FacebookHistory ADD IsAbandoned		TINYINT default 0;
          ALTER TABLE tmp_FacebookHistory ADD TotalSLA		TINYINT default 0;
          
          
          
			ALTER TABLE tmp_FacebookHistory ADD SLAacheived		INT default 0;
			ALTER TABLE tmp_FacebookHistory ADD SLAbleached		INT default 0;
            
		
          
             CREATE INDEX ix_tmp_CallHistory ON tmp_FacebookHistory (FacebookHistoryId);
          CREATE INDEX ix_tmp_CallDurationHistory ON tmp_FacebookDurationHistory (FacebookHistoryId);
      
      
     UPDATE tmp_FacebookHistory			CH
          JOIN 	tmp_FacebookDurationHistory_cal	CDH	ON CH.FacebookHistoryId	= CDH.FacebookHistoryId  
          LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
          SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 			THEN 1 ELSE 0 	    END
      		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE 0	    END
            ,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 		THEN 1 ELSE 0	    END
            ,   CH.TotalSLA     = CASE WHEN CDH.dialDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END 
    		,	CH.IsAbandoned	= CASE WHEN D.did IS NOT NULL 		        THEN 1 ELSE 0 	END
			,	CH.SLAacheived  = CDH.SLAachieved
			,	CH.SLAbleached  = CDH.SLAbleached; 
			
            
            
		  IF p_columnName = 'Missed Chats'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'			AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
             
             INSERT INTO tmp_result
      		SELECT 	'Past'					    AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;        
      
      
       
            ELSEIF p_columnName = 'SLA Achieved (%)'
				THEN
					INSERT INTO tmp_result
						SELECT 	'Current'								  AS reportAge
							,	t_T.startDateTime 
							,	t_T.endDateTime
							,   IFNULL(SUM(CH.SLAacheived) / count(FacebookHistoryId), 0) AS callCount        
						FROM 	tmp_timings			t_T	
						LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
						WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
						GROUP BY t_T.startDateTime, t_T.endDateTime, FacebookHistoryId; 
        
					INSERT INTO tmp_result
						SELECT 	'Past'					        				AS reportAge
							,	t_T.startDateTime 
							,	t_T.endDateTime
							,   IFNULL(SUM(CH.SLAacheived) / count(FacebookHistoryId), 0) AS callCount 
						FROM 	tmp_timings		t_T	
						LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
						WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
						GROUP BY t_T.startDateTime, t_T.endDateTime,FacebookHistoryId; 
                        
				
			ELSEIF p_columnName = 'SLA Breached (%)'
                                  THEN
                             		INSERT INTO tmp_result
                              		SELECT 	'Current'								  AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                       ,   IFNULL(abs(CH.SLAbleached),0)            AS callCount   
                                       
                              		FROM 	tmp_timings			t_T	
                              		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                                    
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached; 
                                     
                                     INSERT INTO tmp_result
                              		SELECT 	'Past'					        									AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                         ,   IFNULL(abs(CH.SLAbleached),0)                                  AS callCount   
                                       
                              		FROM 	tmp_timings		t_T	
                              		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                                    
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached; 
       
       
       ELSEIF p_columnName = 'TotalSLA'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'					AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(TotalSLA),0)	    AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_FacebookHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
      		SELECT 	'Past'						AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(TotalSLA),0)	    AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_FacebookHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
               
      
      
      
      
      
      
      END IF;
      
        SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Current';    
         
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Past';
          
     	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_cur_chat=0,1,v_tot_cur_chat) else 1 end)	
        AS currentCount, 
        SUM(CASE WHEN reportAge = 'Past' THEN callCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_past_chat=0,1,v_tot_past_chat) else 1 end)	
        AS pastCount
     	INTO 	v_currentCount, v_pastCount		
     	FROM 	tmp_result;
        
         if p_columnName = 'SLA Breached (%)' then
				select sum(SLAbleached)/count(Distinct FacebookHistoryId) into v_currentCount from tmp_FacebookHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;
				select sum(SLAbleached)/count(Distinct FacebookHistoryId) into v_pastCount from tmp_FacebookHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;   
                                 
					if IFNULL(v_currentCount,0)=0 then set v_currentCount = 0; end if;
					if IFNULL(v_pastCount,0)=0 then set v_pastCount = 0; end if;
                                 
			End if;
         
         SELECT 	p_columnName    														AS metric
			,		ifnull(v_currentCount,0)												AS currentTotal
     		  , 	ifnull(v_pastCount,0)													AS pastTotal
   		  ,	   		ifnull((v_currentCount - v_pastCount),0)  								AS totalDifference
       
         ,			case when (v_currentCount - v_pastCount) > 0 and v_pastCount !=0  
					then (v_currentCount - v_pastCount) /(v_pastCount) *100 ELSE 0 END		AS  Percentage;
         
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_inboundchat_analysis_metrics` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_inboundchat_analysis_metrics`(
    p_startTmpstmp  BIGINT,
    p_endTmpstmp 	BIGINT,
    p_domainId 		INT,
    p_queueId		VARCHAR(250),
    p_Offset 		INT,
    p_Limit 		INT
)
BEGIN
    DECLARE v_offset 								INT;
    DECLARE v_CurrentStartTmpstmp 					BIGINT;
    DECLARE v_CurrentEndTmpstmp 					BIGINT;
    DECLARE v_PrevStartTmpstmp						BIGINT;
    DECLARE v_PrevEndTmpstmp 						BIGINT;
    DECLARE v_TmpstmpInterval 						BIGINT;
		
    DECLARE v_CurTotalCount 						INT;        
    DECLARE v_PrevTotalCount						INT;                    
    DECLARE v_DiffTotalPercent 						INT;    
		
    DECLARE v_PrevresponseTimeCount 				INT;    
    DECLARE v_CurrentresponseTimeCount 				INT;        
    DECLARE v_DiffresponseTimePercent 				INT;
		
    DECLARE v_PrevabondedchatsCount 				INT;    
    DECLARE v_CurrentabondedchatsCount 				INT;
    DECLARE v_DiffabondedchatsPercent 				INT;      

    DECLARE v_CurrentMissedChatCount 				BIGINT;
    DECLARE v_CurrenttransferredchatCount 			BIGINT;
    DECLARE v_CurrenttotalChatdurationCount 		BIGINT;
    DECLARE v_CurrentavgChatdurationCount 			BIGINT;
    DECLARE v_CurrentinteractionfromcustomerCount 	INT;
    DECLARE v_CurrentinteractionfromagentCount 		INT;
    DECLARE v_CurrenttotalinteractionCount 			INT;
    DECLARE v_CurrentpeakchatsCount 				INT;    

    IF IFNULL(p_startTmpstmp, 0) = 0 THEN 
        SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; 
    ELSE 
        SET v_CurrentStartTmpstmp = p_startTmpstmp; 
    END IF; 

    IF IFNULL(p_endTmpstmp, 0) = 0 THEN 
        SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; 
    ELSE 
        SET v_CurrentEndTmpstmp = p_endTmpstmp; 
    END IF;        


    SET v_offset = p_Limit * p_Offset;
    SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
    SET v_PrevEndTmpstmp = v_CurrentStartTmpstmp - 1;
    SET v_PrevStartTmpstmp = v_PrevEndTmpstmp - v_TmpstmpInterval;
    
   

    DROP TEMPORARY TABLE IF EXISTS temp_queueIds;
    CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
    CALL split(p_queueId, ','); 
    INSERT INTO temp_queueIds(queueId) 
    SELECT Items FROM tt_Split_temptable;

    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
    CREATE TEMPORARY TABLE temp_AllqueueId   
    SELECT qid, name AS queueName 
    FROM queue 
    WHERE domainId = p_domainId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
    DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
    CREATE TEMPORARY TABLE temp_chatHistory AS 
    SELECT  
        CAST(FROM_UNIXTIME(SH.sessionStartTime / 1000) AS DATE) 			AS SessionDate,
        COALESCE(Q.name, '-') 												AS queueName,
        IFNULL(SDH.IsMissed,0)												AS MissedChat,
        IFNULL(SDH.IsAbandoned,0)											AS  abondedchats,
		IFNULL((SH.repliedDate - SH.createdAt),0)							AS responseTime,
     
    
        IFNULL(Istransferred,0)												AS transferredchat,

        COALESCE(SDH.Duration, 0)  											AS chatduration,
        IFNULL(sentimentalScoreCustomer,0)									AS interactionfromcustomer,
        IFNULL(sentimentalScoreAgent,0)										AS interactionfromagent,
        0 																	AS interaction,
        0 																	AS peakchats,
        SDH.queueId,
        SH.chatHistoryId
              
    FROM tb_ChatHistory SH
    JOIN tb_ChatDurationHistory SDH ON SH.chatHistoryId = SDH.chatHistoryId
    LEFT JOIN queue Q ON Q.qid = SDH.queueId
    LEFT JOIN tb_User U ON U.UserID = SDH.AgentId
    LEFT JOIN temp_queueIds t_Q ON SDH.queueId = t_Q.queueId
    WHERE SH.domainId = p_domainId
    AND SH.IsInBound = 1
    AND SH.sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
    AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
    LIMIT v_offset, p_limit;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_1;
    CREATE TEMPORARY TABLE temp_chatHistory_1 AS 
    SELECT 
        SessionDate, 
        queueName, 
        sum(abondedchats)												AS abondedchats, 
	     responseTime, 
     
        sum(transferredchat)											AS transferredchat, 
        sum(MissedChat)                         						AS MissedChat,        
        SUM(chatduration) 												AS Totalchatduration,
        AVG(chatduration) 												AS Avgchatduration,
        sum(interactionfromcustomer) 									AS interactionfromcustomer,
        sum(interactionfromagent)										AS interactionfromagent, 
        SUM(interactionfromcustomer)+sum(interactionfromagent)			AS interaction, 
        peakchats, 
        queueId, 
        chatHistoryId
    FROM temp_chatHistory
    GROUP BY SessionDate, queueName, responseTime, peakchats, queueId, 
			chatHistoryId; 

    DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
    CREATE TEMPORARY TABLE temp_PrevCallHistory AS
    SELECT DISTINCT chatHistoryId, abondedchats
    FROM temp_chatHistory_1
    WHERE SessionDate BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;

    DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
    CREATE TEMPORARY TABLE temp_CurCallHistory AS
    SELECT DISTINCT chatHistoryId, abondedchats
    FROM temp_chatHistory_1
    WHERE SessionDate BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;               

    SELECT COUNT(chatHistoryId), SUM(abondedchats)
    INTO v_PrevTotalCount, v_PrevabondedchatsCount 
    FROM temp_PrevCallHistory;

    SELECT COUNT(chatHistoryId), SUM(abondedchats)
    INTO v_CurTotalCount, v_CurrentabondedchatsCount 
    FROM temp_CurCallHistory;        

    SELECT COUNT(chatHistoryId), SUM(abondedchats)
    INTO v_PrevTotalCount, v_PrevabondedchatsCount 
    FROM temp_chatHistory;

    SELECT COUNT(chatHistoryId), SUM(abondedchats)
    INTO v_CurTotalCount, v_CurrentabondedchatsCount 
    FROM temp_chatHistory;   

    SELECT SUM(MissedChat), SUM(transferredchat), SUM(Totalchatduration), AVG(Avgchatduration),
           SUM(interactionfromcustomer), SUM(interactionfromagent), SUM(interaction), SUM(peakchats)
    INTO v_CurrentMissedChatCount, v_CurrenttransferredchatCount, v_CurrenttotalChatdurationCount, v_CurrentavgChatdurationCount,
         v_CurrentinteractionfromcustomerCount, v_CurrentinteractionfromagentCount, v_CurrenttotalinteractionCount, v_CurrentpeakchatsCount
    FROM temp_chatHistory_1;           

  

    SELECT * FROM temp_AllqueueId;

    SELECT 
        IFNULL(v_CurTotalCount, 0) 																AS 'TotalCount',
        IFNULL(v_DiffTotalPercent, 0) 															AS 'DiffTotalPercent',
        IFNULL(v_CurrentresponseTimeCount, 0) 													AS 'CurrentResponseCount',
        IFNULL(v_DiffresponseTimePercent, 0) 													AS 'DiffResponsePercent',
        IFNULL(v_CurrentabondedchatsCount, 0) 													AS 'CurrentAbondedchatsCount',
        IFNULL(v_DiffabondedchatsPercent, 0) 													AS 'DiffAbondedchatsPercent';

    SELECT
        'All Queue' 																			AS queueName,
        IFNULL(v_CurTotalCount, 0) 																AS receivedchats,
        IFNULL(v_CurrentresponseTimeCount, 0) 													AS responseTime,
        IFNULL(v_CurrentabondedchatsCount, 0) 													AS abondedchats,
        IFNULL(v_CurrentMissedChatCount, 0) 													AS MissedChat,
        IFNULL(v_CurrenttransferredchatCount, 0) 												AS transferredchat,
        IFNULL(v_CurrenttotalChatdurationCount, 0) 												AS totalChatduration,
        IFNULL(v_CurrentavgChatdurationCount, 0) 												AS avgChatduration,
        IFNULL(v_CurrentinteractionfromcustomerCount, 0) 										AS interactionfromcustomer,
        IFNULL(v_CurrenttotalinteractionCount, 0) 												AS interactionfromagent,
        IFNULL(v_CurrentinteractionfromcustomerCount, 0) + IFNULL(v_CurrenttotalinteractionCount, 0) AS totalinteraction,
        IFNULL(v_CurrentpeakchatsCount, 0) 														AS peakchats
    UNION ALL    
    SELECT 
        U.queueName,
        COUNT(1) 																				AS receivedchats,
        t_SH.responseTime,
        t_SH.abondedchats,
        SUM(t_SH.MissedChat) 																	AS MissedChat,
        t_SH.transferredchat,
        SUM(t_SH.chatduration) 																	AS totalChatduration,
        IFNULL(AVG(t_SH.chatduration), 0) 														AS avgChatduration,
        t_SH.interactionfromcustomer / 100 														AS interactionfromcustomer,
        t_SH.interactionfromagent / 100 														AS interactionfromagent,
        SUM(t_SH.interaction) 																	AS totalinteraction,
        t_SH.peakchats
    FROM temp_chatHistory t_SH
    LEFT JOIN temp_AllqueueId U ON t_SH.queueId = U.qid
    GROUP BY U.queueName, t_SH.responseTime, t_SH.abondedchats, t_SH.transferredchat, t_SH.interactionfromcustomer,
             t_SH.interactionfromagent, t_SH.interaction, t_SH.peakchats;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_inboundchat_analysis_metrics_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_queue_inboundchat_analysis_metrics_1`(
     p_startTmpstmp  BIGINT,
     p_endTmpstmp 	BIGINT,
     p_domainId 		INT,
     p_queueId		VARCHAR(250),
     p_Offset 		INT,
     p_Limit 		INT
 )
BEGIN
     DECLARE v_offset 								INT;
     DECLARE v_CurrentStartTmpstmp 					BIGINT;
     DECLARE v_CurrentEndTmpstmp 					BIGINT;
     DECLARE v_PrevStartTmpstmp						BIGINT;
     DECLARE v_PrevEndTmpstmp 						BIGINT;
     DECLARE v_TmpstmpInterval 						BIGINT;
 		
     DECLARE v_CurTotalCount 						INT;        
     DECLARE v_PrevTotalCount						INT;                    
     DECLARE v_DiffTotalPercent 						INT;    
 		
     DECLARE v_PrevresponseTimeCount 				INT;    
     DECLARE v_CurrentresponseTimeCount 				INT;        
     DECLARE v_DiffresponseTimePercent 				INT;
 		
     DECLARE v_PrevabondedchatsCount 				INT;    
     DECLARE v_CurrentabondedchatsCount 				INT;
     DECLARE v_DiffabondedchatsPercent 				INT;      
 
     DECLARE v_CurrentMissedChatCount 				BIGINT;
     DECLARE v_CurrenttransferredchatCount 			BIGINT;
     DECLARE v_CurrenttotalChatdurationCount 		BIGINT;
     DECLARE v_CurrentavgChatdurationCount 			BIGINT;
     DECLARE v_CurrentinteractionfromcustomerCount 	INT;
     DECLARE v_CurrentinteractionfromagentCount 		INT;
     DECLARE v_CurrenttotalinteractionCount 			INT;
     DECLARE v_CurrentpeakchatsCount 				INT;    
 
 
	DECLARE	v_receivedchats				BIGINT;			 
	DECLARE	v_responseTime				BIGINT;			 
	DECLARE	v_abondedchats				BIGINT;			
	DECLARE	v_MissedChat				BIGINT;			 
	DECLARE	v_transferredchat			BIGINT;			 
	DECLARE	v_totalChatduration			BIGINT;			 
	DECLARE	v_avgChatduration			BIGINT;			 
	DECLARE	v_interactionfromcustomer	BIGINT;			
	DECLARE	v_interactionfromagent		BIGINT;			
	DECLARE	v_totalinteraction			BIGINT;			 
	DECLARE	v_peakchats					BIGINT;			

 
     IF IFNULL(p_startTmpstmp, 0) = 0 THEN 
         SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; 
     ELSE 
         SET v_CurrentStartTmpstmp = p_startTmpstmp; 
     END IF; 
 
     IF IFNULL(p_endTmpstmp, 0) = 0 THEN 
         SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; 
     ELSE 
         SET v_CurrentEndTmpstmp = p_endTmpstmp; 
     END IF;        
 
     SET v_offset = p_Limit * p_Offset;
     SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
     SET v_PrevEndTmpstmp = v_CurrentStartTmpstmp - 1;
     SET v_PrevStartTmpstmp = v_PrevEndTmpstmp - v_TmpstmpInterval;
 
     DROP TEMPORARY TABLE IF EXISTS temp_queueIds;
     CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
     CALL split(p_queueId, ','); 
     INSERT INTO temp_queueIds(queueId) 
     SELECT Items FROM tt_Split_temptable;
 
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
     CREATE TEMPORARY TABLE temp_AllqueueId   
     SELECT qid, name AS queueName 
     FROM queue 
     WHERE domainId = p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
     DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
     CREATE TEMPORARY TABLE temp_chatHistory AS 
     SELECT  
         CAST(FROM_UNIXTIME(SH.sessionStartTime / 1000) AS DATE) 			AS SessionDate,
         COALESCE(Q.name, '-') 												AS queueName,
         IFNULL(SDH.IsMissed,0)												AS MissedChat,
         IFNULL(SDH.IsAbandoned,0)											AS  abondedchats,
 		IFNULL((SH.repliedDate - SH.createdAt),0)							AS responseTime,
      
     
         IFNULL(Istransferred,0)											AS transferredchat,
         COALESCE(SDH.Duration, 0)  										AS chatduration,
         IFNULL(CM.customerMsgCount,0)										AS interactionfromcustomer,
         IFNULL(CM.agentMsgCount,0)											AS interactionfromagent,
         0 																	AS interaction,
         0 																	AS peakchats,
         SDH.queueId,
         SH.chatHistoryId
     FROM tb_ChatHistory SH
     JOIN tb_ChatDurationHistory SDH ON SH.chatHistoryId = SDH.chatHistoryId
	  JOIN 	tb_ChatMessage			CM		ON CM.ChatDurationHistoryId	= SDH.ChatDurationHistoryId 
     LEFT JOIN queue Q ON Q.qid = SDH.queueId
     LEFT JOIN tb_User U ON U.UserID = SDH.AgentId
     LEFT JOIN temp_queueIds t_Q ON SDH.queueId = t_Q.queueId
     WHERE SH.domainId = p_domainId
     AND SH.IsInBound = 1
     AND SH.sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
     AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
     LIMIT v_offset, p_limit;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 select * from temp_chatHistory;
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_1;
     CREATE TEMPORARY TABLE temp_chatHistory_1 AS 
     SELECT 
         SessionDate, 
         queueName, 
         sum(abondedchats)												AS abondedchats, 
 	     responseTime, 
      
         sum(transferredchat)											AS transferredchat, 
         sum(MissedChat)                         						AS MissedChat,        
         SUM(chatduration) 												AS Totalchatduration,
         AVG(chatduration) 												AS Avgchatduration,
         sum(interactionfromcustomer) 									AS interactionfromcustomer,
         sum(interactionfromagent)										AS interactionfromagent, 
         SUM(interactionfromcustomer)+sum(interactionfromagent)			AS interaction, 
         peakchats, 
         queueId, 
         chatHistoryId
     FROM temp_chatHistory
     GROUP BY SessionDate, queueName, responseTime, peakchats, queueId, 
 			chatHistoryId; 
 
 select * from temp_chatHistory_1;
 
     DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
     CREATE TEMPORARY TABLE temp_PrevCallHistory AS
     SELECT DISTINCT chatHistoryId, abondedchats
     FROM temp_chatHistory_1
     WHERE SessionDate BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
 
     DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
     CREATE TEMPORARY TABLE temp_CurCallHistory AS
     SELECT DISTINCT chatHistoryId, abondedchats
     FROM temp_chatHistory_1
     WHERE SessionDate BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;               
 
     SELECT COUNT(chatHistoryId), SUM(abondedchats)
     INTO v_PrevTotalCount, v_PrevabondedchatsCount 
     FROM temp_PrevCallHistory;
 
     SELECT COUNT(chatHistoryId), SUM(abondedchats)
     INTO v_CurTotalCount, v_CurrentabondedchatsCount 
     FROM temp_CurCallHistory;        
 
     SELECT COUNT(chatHistoryId), SUM(abondedchats)
     INTO v_PrevTotalCount, v_PrevabondedchatsCount 
     FROM temp_chatHistory;
 
     SELECT COUNT(chatHistoryId), SUM(abondedchats)
     INTO v_CurTotalCount, v_CurrentabondedchatsCount 
     FROM temp_chatHistory;   
 
     SELECT SUM(MissedChat), SUM(transferredchat), SUM(Totalchatduration), AVG(Avgchatduration),
            SUM(interactionfromcustomer), SUM(interactionfromagent), SUM(interaction), SUM(peakchats)
     INTO v_CurrentMissedChatCount, v_CurrenttransferredchatCount, v_CurrenttotalChatdurationCount, v_CurrentavgChatdurationCount,
          v_CurrentinteractionfromcustomerCount, v_CurrentinteractionfromagentCount, v_CurrenttotalinteractionCount, v_CurrentpeakchatsCount
     FROM temp_chatHistory_1;           
 
   
 
     SELECT * FROM temp_AllqueueId;
 
     SELECT 
         IFNULL(v_CurTotalCount, 0) 																AS 'TotalCount',
         IFNULL(v_DiffTotalPercent, 0) 															AS 'DiffTotalPercent',
         IFNULL(v_CurrentresponseTimeCount, 0) 													AS 'CurrentResponseCount',
         IFNULL(v_DiffresponseTimePercent, 0) 													AS 'DiffResponsePercent',
         IFNULL(v_CurrentabondedchatsCount, 0) 													AS 'CurrentAbondedchatsCount',
         IFNULL(v_DiffabondedchatsPercent, 0) 													AS 'DiffAbondedchatsPercent';
 
  
     
     
					DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_1;
     				CREATE TEMPORARY TABLE temp_chatHistory_calc_1 AS
     SELECT 
         U.queueName,
         COUNT(1) 																				AS receivedchats,
         t_SH.responseTime,
         t_SH.abondedchats,
         SUM(t_SH.MissedChat) 																	AS MissedChat,
         t_SH.transferredchat,
         SUM(t_SH.chatduration) 																AS totalChatduration,
         IFNULL(AVG(t_SH.chatduration), 0) 														AS avgChatduration,
         t_SH.interactionfromcustomer  															AS interactionfromcustomer,
         t_SH.interactionfromagent  															AS interactionfromagent,
         SUM(t_SH.interaction) 																	AS totalinteraction,
         t_SH.peakchats
     FROM temp_chatHistory t_SH
     LEFT JOIN temp_AllqueueId U ON t_SH.queueId = U.qid
     GROUP BY U.queueName, t_SH.responseTime, t_SH.abondedchats, t_SH.transferredchat, t_SH.interactionfromcustomer,
              t_SH.interactionfromagent, t_SH.interaction, t_SH.peakchats;
              
  select  sum(receivedchats), sum(responseTime), sum(abondedchats), sum(MissedChat), sum(transferredchat), sum(totalChatduration), 
  sum(avgChatduration), sum(interactionfromcustomer), sum(interactionfromagent), sum(totalinteraction), sum(peakchats)     
  INTO
   v_receivedchats, v_responseTime, v_abondedchats, v_MissedChat, v_transferredchat, v_totalChatduration, 
  v_avgChatduration, v_interactionfromcustomer, v_interactionfromagent, v_totalinteraction, v_peakchats
  from    temp_chatHistory_calc_1;         
   
   select 
      'All Queue' 																	AS queueName,		
      v_receivedchats																AS receivedchats,				
      v_responseTime																AS responseTime,				
      v_abondedchats																AS abondedchats,				
      v_MissedChat																	AS MissedChat,					
      v_transferredchat																AS transferredchat,				
      v_totalChatduration															AS totalChatduration,			
	  v_avgChatduration																AS avgChatduration,				
	  v_interactionfromcustomer														AS interactionfromcustomer,		
	  v_interactionfromagent														AS interactionfromagent,		
	  v_totalinteraction															AS totalinteraction,					
	  v_peakchats																	AS peakchats
    UNION
    SELECT
    distinct(queueName)   														AS	queueName,
     sum(receivedchats)															AS	receivedchats, 
     sum(responseTime)                                                          AS    responseTime, 
     sum(abondedchats)                                                          AS    abondedchats, 
     sum(MissedChat)                                                            AS    MissedChat,
     sum(transferredchat)                                                       AS    transferredchat, 
      sum(totalChatduration)                                                    AS    totalChatduration,
      sum(avgChatduration)                                                      AS    avgChatduration, 
      sum(interactionfromcustomer)                                              AS    interactionfromcustomer, 
      sum(interactionfromagent)        as interactionfromagent, 
      sum(totalinteraction)            as  totalinteraction, 
      sum(peakchats)   					as peakchats     
 
 from 
 temp_chatHistory_calc_1
 group by queueName;
 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_instagram_inbound_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_instagram_inbound_trendChart`(
		p_domainId 			INT,
    	p_datetype 			INT,            
		p_startTmpstmp		DATETIME,
		p_endTmpstmp		DATETIME,
    	p_columnName    	VARCHAR(200),    
    	p_queueId 			TEXT
)
begin
	declare v_startDateTime		 		datetime;
    declare v_endDateTime 				datetime;
    declare v_startDateTimePast 		datetime;
    declare v_endDateTimePast 			datetime;
    declare v_curDate 					datetime default now();
    declare v_datetimeInterval 			SMALLINT;
    declare  v_currentCount		 		int;
    declare v_startTimestampPast      	BIGINT;
    declare v_endTimestampPast			BIGINT;
    declare v_startTimestamp			BIGINT;
    declare v_endTimestamp				BIGINT;
    declare v_pastCount					INT;
    
  	DROP TEMPORARY TABLE IF EXISTS tmp_result;
   	CREATE TEMPORARY TABLE tmp_result(
   		reportAge			VARCHAR(20)
   		,startDateTime		DATETIME
   		,endDateTime		DATETIME
   		,callCount			INT
   	);    
    
IF p_datetype = 1 
        THEN 	
    		SET v_startDateTime = CAST(v_curDate AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
    	END IF;
    	IF p_datetype = 2 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
			SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
    	END IF;
    	IF p_datetype = 3 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = date_add(cast(v_curDate as date), interval '23:59:00' hour_second); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = date_add(date_add(v_startDateTime, interval -1 day), interval '23:59:00' hour_second ) ;
    	END IF;
    	IF p_datetype = 4 
        THEN 
    		SET v_startDateTime = p_startTmpstmp; 
			SET v_endDateTime 	= p_endTmpstmp; 
            
			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
            
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    	END IF;
        
         IF p_queueId IS NOT NULL 
        THEN
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
    		CALL split(p_queueId,','); 
            INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
            
        ELSE
        
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs
    		SELECT 	qid	AS queueId
   		    FROM 	queue
            WHERE 	domainId = p_domainId;
           
        END IF;
        
		DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
        CREATE TEMPORARY TABLE tmp_Disposition
			SELECT did, dispositionName
			FROM 	disposition_status
			WHERE	domainId		= p_domainId
			AND	dispositionName	= 'Caller Disconnected';
            
		IF p_datetype IN (1,2)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH RECURSIVE CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	endDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
    	ELSEIF p_datetype IN (3,4)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH recursive CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	startDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
        END IF;  
        
         ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
            UPDATE tmp_timings
		SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
    		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
            
    	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
		,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
		,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
		, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
        
        DROP TEMPORARY TABLE IF EXISTS tmp_InstagramDurationHistory;	
		CREATE TEMPORARY TABLE tmp_InstagramDurationHistory
		SELECT 	CH.InstagramHistoryId
			,	CH.sessionStartTime
			,	CH.IsMissed
			,	CH.dispositionId        
			,	CH.Duration
			,   ifnull(CH.dialDuration,0)				  				    	      AS responseTime        
		FROM    tb_InstagramHistory 			 CH
   	 	LEFT JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CH.queueId	
		WHERE 	CH.domainId 		= p_domainId
		
		AND 	cast(from_unixtime(CH.sessionStartTime/1000)as date) BETWEEN cast(from_unixtime(v_startTimestampPast/1000)as date) 
				AND cast(from_unixtime(v_endTimestamp/1000) as date)
		AND 	CH.IsInBound		= 1; 
        
        DROP TEMPORARY TABLE IF EXISTS tmp_InstagramHistory;	
    	CREATE TEMPORARY TABLE tmp_InstagramHistory
		SELECT 	DISTINCT 
    			CDH.InstagramHistoryId 
    		, 	CDH.sessionStartTime
			,   CDH.responseTime
    	FROM 	tmp_InstagramDurationHistory CDH;
        
		ALTER TABLE tmp_InstagramHistory ADD IsMissed 	TINYINT default 0;
        ALTER TABLE tmp_InstagramHistory ADD IsAnswered TINYINT default 0;
        ALTER TABLE tmp_InstagramHistory ADD IsAbandoned TINYINT default 0;
        
		CREATE INDEX ix_tmp_CallHistory        ON tmp_InstagramHistory (InstagramHistoryId);
        CREATE INDEX ix_tmp_CallDurationHistory ON tmp_InstagramDurationHistory (InstagramHistoryId);  
        
		UPDATE tmp_InstagramHistory			CH
        JOIN 	tmp_InstagramDurationHistory	CDH	
        ON CH.InstagramHistoryId	= CDH.InstagramHistoryId  
        LEFT JOIN tmp_Disposition		    D	ON D.did			= CDH.dispositionId
        SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 	THEN 1 ELSE CH.IsMissed 	END
    		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 	THEN 1 ELSE CH.IsAnswered 	END
			,	CH.IsAbandoned	= CASE WHEN D.did IS NOT NULL 	THEN 1 ELSE CH.IsAbandoned 	END; 
        
		IF p_columnName = 'Received Chats'
        THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'				AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	SUM(CASE WHEN CH.InstagramHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
    		FROM 	tmp_timings			    t_T	
    		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
		INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	SUM(CASE WHEN CH.InstagramHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;	
            
		ELSEIF p_columnName = 'Missed Chats'
		THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsMissed),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_InstagramHistory 	CH	
				ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
		INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(IsMissed),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	
					BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
    		GROUP BY t_T.startDateTime, t_T.endDateTime;      
        	ELSEIF p_columnName = 'Responded Chats'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(CH.responseTime, 0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.responseTime;
            
		  INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(CH.responseTime, 0)	AS callCount    
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.responseTime;  
            
            	ELSEIF p_columnName = 'Abandoned Chats'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'			AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	 IFNULL(SUM(CH.IsAbandoned),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.IsAbandoned;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	 IFNULL(SUM(CH.IsAbandoned),0)	AS callCount
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.IsAbandoned; 
            
            END IF;
        
 SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Current';    
       
       SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Past';
       
       
    
    select sum(callCount) into v_currentCount from tmp_result where reportAge = 'Current';
    select sum(callCount) into v_pastCount from tmp_result where reportAge = 'Past';
       
       SELECT 	
  			p_columnName     														AS metric
		   , v_currentCount													    AS currentTotal
		   , v_pastCount															AS pastTotal
           ,(v_currentCount - v_pastCount) 										AS totalDifference
           ,IFNULL((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)	    AS  Percentage;	
           
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_instagram_performances_analysis_metrics` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_instagram_performances_analysis_metrics`(
   p_startTmpstmp    BIGINT,
	p_endTmpstmp 		BIGINT,
	p_domainId 		INT,
	p_queueId 		VARCHAR(250),
	p_offset 			INT,
	p_limit 			INT
)
begin

	DECLARE v_offset 										INT;	  	
      DECLARE v_CurrentStartTmpstmp 						BIGINT;
      DECLARE v_CurrentEndTmpstmp 							BIGINT;
      DECLARE v_PrevStartTmpstmp 							BIGINT;
      DECLARE v_PrevEndTmpstmp 								BIGINT; 
      DECLARE v_TmpstmpInterval 							BIGINT;	
      DECLARE v_PrevAverageResponseCount 					BIGINT;	
      DECLARE v_CurrentAverageResponseCount 				BIGINT;	        
      DECLARE v_DiffAverageResponsePercent 					INT;
      DECLARE v_PrevAverageHandledCount 					BIGINT;	
      DECLARE v_CurrentAverageHandledCount 					BIGINT;
      DECLARE v_DiffAverageHandledPercent 					BIGINT;          
      DECLARE v_PrevCustomerSatisfactionCount 						BIGINT;	
      DECLARE v_CurrentCustomerSatisfactionCount 					BIGINT;
      DECLARE v_DiffCustomerSatisfactionPercent 					BIGINT;  	     
      DECLARE v_CurrentMaximumHandledCount 						BIGINT;	
      DECLARE v_CurrentTotalACWCount 							BIGINT;
      DECLARE v_CurrentAverageQueueWaitingCount 					BIGINT;
      DECLARE v_CurrentMaximumQueueWaitingCount 					BIGINT;
      DECLARE v_CurrentansweredCallCount 						BIGINT;
      DECLARE v_CurrentoccupancyrateCount 						BIGINT;
      DECLARE v_CurrentagentUtilizationCount 						BIGINT;
      DECLARE v_currentfirstChatResolutionCount 					BIGINT;
      DECLARE v_CurrentTotalCount							INT;
    
    

		SET v_offset = p_limit * p_offset; 
  
			IF IFNULL(p_startTmpstmp, 0) = 0 THEN 
				SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL 1 DAY)) * 1000; 
			ELSE 
				SET v_CurrentStartTmpstmp = p_startTmpstmp; 
			END IF; 
            
			IF IFNULL(p_endTmpstmp, 0) = 0 THEN 
				SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; 
			ELSE 
				SET v_CurrentEndTmpstmp = p_endTmpstmp; 
			END IF; 
            
			SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
			SET v_PrevEndTmpstmp = v_CurrentStartTmpstmp - 1;
			SET v_PrevStartTmpstmp = v_PrevEndTmpstmp - v_TmpstmpInterval;
            
			 DROP TEMPORARY TABLE IF EXISTS temp_queueIds;
				CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
                
			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;
				CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                
		CALL split(p_queueId, ','); 
		INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable;
  
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
      CREATE TEMPORARY TABLE temp_AllqueueId   
      SELECT qid, name AS queueName,domainId 
      FROM queue    
      WHERE domainId = p_domainId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  
      DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
      CREATE TEMPORARY TABLE temp_AvailableDisposition (
          DispositionId INT,
          DispositionStatus VARCHAR(100),
          DispositionCategory TINYINT
      ); 
      
       INSERT INTO temp_AvailableDisposition 
      SELECT 
          did AS DispositionId,
          dispositionName AS DispositionStatus,
          CASE 
              WHEN dispositionName = 'Opened' THEN 2
              WHEN dispositionName IN ('Resolved', 'Unresolved', 'Closed', 'Follow-up', 'Disconnected', 'Transferred') THEN 3
              WHEN dispositionName = 'Discarded' THEN 4
              WHEN dispositionName = 'Resolved' THEN 5
          END AS DispositionCategory
      FROM disposition_status
      WHERE domainId = p_domainId; 
      
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
      DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
      CREATE TEMPORARY TABLE temp_chatHistory AS
      SELECT 
          CAST(FROM_UNIXTIME(CH.sessionStartTime / 1000) AS DATE) 					AS SessionDate,
          Q.qid  																		AS queueId,
          Q.name 																		AS queueName,
          IFNULL(CH.repliedDate - CH.createdAt, NULL) 								AS responseTime,
          CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 					AS Handled,
          CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END 					AS firstChatResolution,
          CH.SentimentalScore,
          CH.afterInstagramWorkTime,
          null              															AS QueueWaitTime,
          SUM(CASE WHEN CH.IsInBound = 1 AND CH.Duration > 0 THEN 1 ELSE 0 END) 	AS answeredCall,
          SUM(CH.dialDuration) 														AS totalTalktime,
          SUM(CH.Duration) 															AS Duration,
          CH.IsInBound
      FROM tb_InstagramHistory CH		
   
      LEFT JOIN queue Q ON CH.queueId = Q.qid
      LEFT JOIN temp_AvailableDisposition t_D ON CH.dispositionId = t_D.DispositionId            
      LEFT JOIN temp_queueIds t_Q ON Q.qid = t_Q.queueId 
      WHERE CH.domainId = p_domainId
      AND CH.sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
      AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL))
      GROUP BY 
          SessionDate, queueName, queueId, responseTime, Handled, CH.SentimentalScore,
          CH.afterInstagramWorkTime, QueueWaitTime, t_D.DispositionCategory, CH.IsInBound
      LIMIT v_offset, p_limit;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      
  				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
    				CREATE TEMPORARY TABLE temp_AvailableStates AS
    				SELECT   
    						CASE 
    							WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
    							ELSE 2 
    						    END AS tt_Time,
    						ST.ext,
    						ST.domainId,
    						from_unixtime(ST.startTimestamp/1000),
    						ST.stateDuration as SD
    				FROM     state_timer ST 
    				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
    				WHERE    ST.domainId = p_domainId
    				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
                    
				ALTER TABLE temp_chatHistory ADD COLUMN availableTime		BIGINT;
  				ALTER TABLE temp_chatHistory ADD COLUMN agentName			VARCHAR(150); 
                
                UPDATE temp_chatHistory SH_C
   		    JOIN temp_AllqueueId t_A ON SH_C.queueId = t_A.qid
   		    JOIN (
   			SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
   			FROM temp_AvailableStates
   			GROUP BY ext, domainId
   		    ) tt_AV ON  tt_AV.domainId = t_A.domainId     
   		    SET SH_C.availableTime = tt_AV.total_SD;
            
            
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
      DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_cal; 
      CREATE TEMPORARY TABLE temp_chatHistory_cal AS       
      SELECT
          queueName,    
          queueId,
          AVG(responseTime) 																		AS averageResponseTime,
          CASE WHEN AVG(Duration + afterInstagramWorkTime) !=0 THEN AVG(Duration + afterInstagramWorkTime) / 1000 ELSE 0  END 						AS averageHandlingTime,
          CASE WHEN SUM(Duration + afterInstagramWorkTime) !=0 THEN SUM(Duration + afterInstagramWorkTime) / 1000 ELSE 0	END 					AS maximumHandlingTime,
          CASE WHEN SUM(afterInstagramWorkTime) !=0 THEN SUM(afterInstagramWorkTime) / 1000  						ELSE 0 	END 					AS totalACWTime,
          ifnull(AVG(QueueWaitTime),0) 																												AS averageQueueWaitTime,
          ifnull(sum(QueueWaitTime),0) 																												AS maximumQueueWaitTime,            
          SUM(CASE WHEN IsInBound = 1 AND Duration > 0 THEN 1 ELSE 0 END) 																			AS answeredCall,
          0 																																		AS agentUtilization,
          CASE WHEN SUM(totalTalktime) !=0  and SUM(availableTime) != 0 THEN (SUM(totalTalktime) / SUM(availableTime)) * 100 	ELSE 0 END			AS occupancyrate,
          COALESCE(SUM(SentimentalScore), 0) 																										AS CustomerSatisfaction,
          SUM(firstChatResolution) 																													AS firstChatResolution
      FROM temp_chatHistory
      GROUP BY queueName, queueId;
      
         DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
      CREATE TEMPORARY TABLE temp_PrevCallHistory AS
      SELECT responseTime, SentimentalScore
      FROM temp_chatHistory
      WHERE SessionDate BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
  
      DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
      CREATE TEMPORARY TABLE temp_CurCallHistory AS
      SELECT responseTime, SentimentalScore
      FROM temp_chatHistory
      WHERE SessionDate BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
      
         SELECT IFNULL(AVG(responseTime),0), IFNULL(SUM(SentimentalScore),0) AS SentimentalScore
      INTO v_PrevAverageResponseCount, v_PrevCustomerSatisfactionCount
      FROM temp_PrevCallHistory;        
  
      SELECT IFNULL(AVG(responseTime),0), IFNULL(SUM(SentimentalScore),0) AS SentimentalScore
      INTO v_CurrentAverageResponseCount, v_CurrentCustomerSatisfactionCount
      FROM temp_CurCallHistory;      
  
      SELECT AVG(responseTime), SUM(SentimentalScore) AS SentimentalScore,
		CASE WHEN AVG(Duration + afterInstagramWorkTime) != 0 then AVG(Duration + afterInstagramWorkTime) / 1000 ELSE 0 END,
		CASE WHEN AVG(Duration + afterInstagramWorkTime) !=0 then AVG(Duration + afterInstagramWorkTime) / 1000 ELSE 0 END
      INTO v_PrevAverageResponseCount, v_PrevCustomerSatisfactionCount,  v_PrevAverageHandledCount, v_CurrentAverageHandledCount
      FROM temp_chatHistory;           
  
      
      SET v_DiffCustomerSatisfactionPercent = case when IFNULL(v_PrevCustomerSatisfactionCount,0) !=0 THEN ((v_CurrentCustomerSatisfactionCount - v_PrevCustomerSatisfactionCount)/v_PrevCustomerSatisfactionCount) * 100 ELSE 0 END ;
        SELECT 
      sum(averageResponseTime),
      sum(averageHandlingTime),
      sum(maximumHandlingTime),
      SUM(totalACWTime),
      sum(averageQueueWaitTime),
      sum(maximumQueueWaitTime),
      sum(answeredCall),
      sum(occupancyrate),
      sum(agentUtilization),
      sum(firstChatResolution),
      
      CASE WHEN IFNULL(sum(answeredCall), 0) !=0 THEN sum(CustomerSatisfaction)/sum(answeredCall) ELSE 0 END,
      COUNT(*)
  INTO 
      v_CurrentAverageResponseCount, 
      v_CurrentAverageHandledCount, 
      v_CurrentMaximumHandledCount, 
      v_CurrentTotalACWCount,
      v_CurrentAverageQueueWaitingCount, 
      v_CurrentMaximumQueueWaitingCount, 
      v_CurrentansweredCallCount, 
      v_CurrentoccupancyrateCount,
      v_CurrentagentUtilizationCount,
      v_currentfirstChatResolutionCount,
      v_CurrentCustomerSatisfactionCount,
      v_CurrentTotalCount      
  FROM 
      temp_chatHistory_cal;

   SELECT * FROM temp_AllqueueId;
  
      SELECT 
          IFNULL(v_CurrentAverageResponseCount, 0) 		AS CurrentAverageResponseCount,
          IFNULL(v_DiffAverageResponsePercent, 0)  		AS DiffAverageResponsePercent,
          IFNULL(v_CurrentAverageHandledCount, 0)  		AS CurrentAverageHandledCount,
          IFNULL(v_DiffAverageHandledPercent, 0)   		AS DiffAverageHandledPercent,
          IFNULL(v_CurrentCustomerSatisfactionCount, 0) 	AS CurrentCustomerSatisfactionCount,
          IFNULL(v_DiffCustomerSatisfactionPercent, 0) 	AS DiffCustomerSatisfactionPercent;
  
      SELECT
          'All Queue' 												AS queueName,
          IFNULL(v_CurrentAverageResponseCount, 0) 					AS AverageresponseTime,
          IFNULL(v_CurrentAverageHandledCount, 0)  					AS AverageHandledTime,
          IFNULL(v_CurrentMaximumHandledCount, 0)  					AS MaximumHandledTime,
          IFNULL(v_CurrentTotalACWCount, 0) 		 					AS TotalACW,
          IFNULL(v_CurrentAverageQueueWaitingCount, 0) 				AS AverageQueueWaiting,
          IFNULL(v_CurrentMaximumQueueWaitingCount, 0) 				AS MaximumQueueWaiting,
          IFNULL(v_CurrentansweredCallCount, 0) 						AS answeredCall,
          IFNULL(v_CurrentoccupancyrateCount, 0)			    		AS occupancyrate, 
          IFNULL(v_currentfirstChatResolutionCount, 0) 				AS firstChatResolution,
          IFNULL(v_CurrentCustomerSatisfactionCount, 0) 				AS CustomerSatisfaction
      UNION ALL     
      SELECT    
          U.queueName,
          t_SH.AverageresponseTime,
          t_SH.averageHandlingTime  							as averageHandlingTime,
          t_SH.maximumHandlingTime  							AS maximumHandlingTime,
          t_SH.totalACWTime   									as totalACWTime,
          t_SH.averageQueueWaitTime 							as averageQueueWaitTime,
          t_SH.maximumQueueWaitTime 							as maximumQueueWaitTime,
      
          t_SH.answeredCall,
          t_SH.occupancyrate,
          t_SH.firstChatResolution,
          t_SH.CustomerSatisfaction
      FROM temp_chatHistory_cal t_SH
      LEFT JOIN temp_AllqueueId U ON t_SH.queueId = U.qid;
  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_instagram_performances_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_instagram_performances_trendChart`(
    	p_domainId 			INT,
    	p_datetype 			INT,            	
		p_startTmpstmp		DATETIME,
		p_endTmpstmp		DATETIME,
    	p_columnName    	VARCHAR(200),    	 
    	p_queueId 			TEXT
    )
BEGIN
    
    
   	DECLARE v_startDateTime			DATETIME;
   	DECLARE v_endDateTime			DATETIME;     
   	DECLARE v_datetimeInterval		SMALLINT;    
   	DECLARE v_startDateTimePast		DATETIME;
   	DECLARE v_endDateTimePast		DATETIME;
           
   	DECLARE v_startTimestampPast	BIGINT;
   	DECLARE v_endTimestampPast		BIGINT;      
   	DECLARE v_startTimestamp		BIGINT;
   	DECLARE v_endTimestamp			BIGINT;
   	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
       
   	DROP TEMPORARY TABLE IF EXISTS tmp_result;
   	CREATE TEMPORARY TABLE tmp_result(
   		reportAge			VARCHAR(20)
   		,startDateTime		DATETIME
   		,endDateTime		DATETIME
   		,callCount			INT
   	);    
    
    	IF p_datetype = 1 
        THEN 	
    		SET v_startDateTime = CAST(v_curDate AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
    	END IF;
    	IF p_datetype = 2 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
    
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
    		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
    	END IF;
    	IF p_datetype = 3 
        THEN 
    		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
           SET v_endDateTime = date_add(cast(v_curDate as date), interval '23:59:00' hour_second); 
            
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
    		SET v_endDateTimePast = date_add(date_add(v_startDateTime, interval -1 day), interval '23:59:00' hour_second );   
    	END IF;
    	IF p_datetype = 4 
        THEN 
    		SET v_startDateTime = p_startTmpstmp; 
   		SET v_endDateTime 	= p_endTmpstmp; 
            
           SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
            
    		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
    	END IF;
        
        IF p_queueId IS NOT NULL 
        THEN
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
    		CALL split(p_queueId,','); 
            INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
        ELSE
    		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
            CREATE TEMPORARY TABLE temp_queueIDs
				SELECT 	qid	AS queueId
				FROM 	queue
				WHERE 	domainId = p_domainId;
        END IF;
        
        DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
        CREATE TEMPORARY TABLE tmp_Disposition
        SELECT did, dispositionName
        FROM 	disposition_status
        WHERE	domainId		= p_domainId
        AND	dispositionName	= 'Caller Disconnected';    
        
        IF p_datetype IN (1,2)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH RECURSIVE CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	endDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
    	ELSEIF p_datetype IN (3,4)
        THEN 
    		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
            CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
    		WITH recursive CTE_TIMINGS AS (
    			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
    			UNION ALL
    			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
    			FROM 	CTE_TIMINGS
    			WHERE 	startDateTime < v_endDateTime
    		)
    		SELECT * FROM CTE_TIMINGS;	
        END IF;  
        
        ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
        
        UPDATE tmp_timings
        SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
    		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
            
    	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
   	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
   	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
   	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
     
    
     DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     CREATE TEMPORARY TABLE temp_AvailableDisposition (
         DispositionId INT,
         DispositionStatus VARCHAR(100),
         DispositionCategory TINYINT,
         domainId            INT
     ); 
                           
     INSERT INTO temp_AvailableDisposition 
     SELECT 
         did AS DispositionId,
         dispositionName AS DispositionStatus,
         CASE 
             WHEN dispositionName = 'Opened' THEN 2
             WHEN dispositionName IN ('Resolved', 'Unresolved', 'Closed', 'Follow-up', 'Disconnected', 'Transferred') THEN 3
             WHEN dispositionName = 'Discarded' THEN 4
             WHEN dispositionName = 'Resolved' THEN 5
         END AS DispositionCategory,
                 domainId
     FROM disposition_status
     WHERE domainId = p_domainId;    
    
 
    
     DROP TEMPORARY TABLE IF EXISTS tmp_InstagramDurationHistory_1;	
   	CREATE TEMPORARY TABLE tmp_InstagramDurationHistory_1
   	SELECT 	
         CAST(FROM_UNIXTIME(CH.sessionStartTime / 1000) AS DATE) 					AS SessionDate
 		,  CH.InstagramHistoryId
   		,	CH.sessionStartTime
   		,	CH.IsMissed
   		,	CH.dispositionId          
   		,	CH.Duration
         ,   IFNULL(CH.repliedDate - CH.createdAt, NULL) 								AS responseTime 
         , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 					    AS Handled
         , 0                															    AS QueueWaitTime
         , CH.afterInstagramWorkTime
    FROM      tb_InstagramHistory 			 CH   
    JOIN 	temp_queueIDs					Q			ON 	Q.queueId			= CH.queueId
  LEFT JOIN   temp_AvailableDisposition       t_D        ON CH.dispositionId = t_D.DispositionId 	
 													AND    CH.domainId =t_D.domainId
   	WHERE 	CH.domainId 		= p_domainId
   	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
   
     
      DROP TEMPORARY TABLE IF EXISTS tmp_InstagramDurationHistory;	
   	 CREATE TEMPORARY TABLE tmp_InstagramDurationHistory
      SELECT
 		InstagramHistoryId,
         dispositionId
         sessionStartTime,
         AVG(responseTime) 																AS averageResponseTime,
         AVG(Duration + afterInstagramWorkTime) / 1000 									AS averageHandlingTime,
         SUM(Duration + afterInstagramWorkTime) / 1000 									AS maximumHandlingTime,
         SUM(afterInstagramWorkTime) / 1000 												AS totalACWTime,
         ifnull(AVG(QueueWaitTime),0) 													AS averageQueueWaitTime
     FROM tmp_InstagramDurationHistory_1
     group by InstagramHistoryId,sessionStartTime,dispositionId;
     
   	DROP TEMPORARY TABLE IF EXISTS tmp_InstagramHistory;	
    	CREATE TEMPORARY TABLE tmp_InstagramHistory
       SELECT 	DISTINCT 
    			CDH.InstagramHistoryId 
       
    		, 	CDH.sessionStartTime
     
    	FROM 	tmp_InstagramDurationHistory CDH;    
     
 
 	   ALTER TABLE tmp_InstagramHistory  ADD averageResponseTime 	bigint default 0;
        ALTER TABLE tmp_InstagramHistory  ADD averageHandlingTime 	bigint default 0;
        ALTER TABLE tmp_InstagramHistory  ADD totalACWTime			bigint default 0;
        ALTER TABLE tmp_InstagramHistory  ADD averageQueueWaitTime    bigint default 0;
        
 		CREATE INDEX ix_tmp_CallHistory        ON tmp_InstagramHistory (InstagramHistoryId);
        CREATE INDEX ix_tmp_CallDurationHistory ON tmp_InstagramDurationHistory (InstagramHistoryId);     
        
      UPDATE tmp_InstagramHistory			CH
        JOIN 	tmp_InstagramDurationHistory	CDH	ON CH.InstagramHistoryId	= CDH.InstagramHistoryId  
       
        SET 	CH.averageResponseTime	= CDH.averageResponseTime,
    			CH.averageHandlingTime	= CDH.averageHandlingTime,
 			CH.totalACWTime	        = CDH.totalACWTime,
             CH.averageQueueWaitTime = CDH.averageQueueWaitTime;
         

 
  IF p_columnName = 'Avg. Response Time'
        THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'				AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageResponseTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		 GROUP BY t_T.startDateTime, t_T.endDateTime;
 
           INSERT INTO tmp_result
    		SELECT 	'Past'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageResponseTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
    		 GROUP BY t_T.startDateTime, t_T.endDateTime;
 
 ELSEIF p_columnName = 'Avg. Handle Time (AHT)'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageHandlingTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN  tmp_InstagramHistory	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageHandlingTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
         
  ELSEIF p_columnName = 'Total ACW Time'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(totalACWTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN  tmp_InstagramHistory	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(totalACWTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;       
         
      ELSEIF p_columnName = 'Avg. Queue Wait Time'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageQueueWaitTime),0)	    AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    	 	GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(averageQueueWaitTime),0)   AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		 GROUP BY t_T.startDateTime, t_T.endDateTime;    
         END IF;       
        SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Current';    
       
       SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Past';
        
   	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
   	INTO 	v_currentCount, v_pastCount		
   	FROM 	tmp_result;
       
       SELECT 	
  			p_columnName     													AS metric
  		 ,  v_currentCount													    AS currentTotal
   		 , 	v_pastCount															AS pastTotal
           ,	(v_currentCount - v_pastCount) 										AS totalDifference
           ,	IFNULL((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)	    AS  Percentage;	
           
           
           END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_Instagram_Servicelevel_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_queue_Instagram_Servicelevel_trendChart`(
		p_domainId 			INT,
      	p_datetype 			INT,                 
  		p_startTmpstmp		DATETIME,
  		p_endTmpstmp		DATETIME,
      	p_columnName    	VARCHAR(200),       
      	p_queueId 			TEXT

)
begin
		DECLARE v_startDateTime			DATETIME;
     	DECLARE v_endDateTime			DATETIME;     
     	DECLARE v_datetimeInterval		SMALLINT;    
     	DECLARE v_startDateTimePast		DATETIME;
     	DECLARE v_endDateTimePast		DATETIME;
          
     	DECLARE v_startTimestampPast	BIGINT;
     	DECLARE v_endTimestampPast		BIGINT;      
     	DECLARE v_startTimestamp		BIGINT;
     	DECLARE v_endTimestamp			BIGINT;
     	DECLARE v_curDate				DATETIME DEFAULT NOW();	
        DECLARE v_currentCount			INT;
        DECLARE v_pastCount				INT;
        
        DECLARE v_tot_cur_chat          INT;
		DECLARE v_tot_past_chat			INT;
        
        DROP TEMPORARY TABLE IF EXISTS tmp_result;
     	CREATE TEMPORARY TABLE tmp_result(
     		reportAge			VARCHAR(20)
     		,startDateTime		DATETIME
     		,endDateTime		DATETIME
     		,callCount			INT
     	);
        
              	IF p_datetype = 1 
          THEN 	
      		SET v_startDateTime = CAST(v_curDate AS DATE); 
      		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
      
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
      	END IF;
      	IF p_datetype = 2 
          THEN 
      		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
      
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
      	END IF;
      	IF p_datetype = 3 
          THEN 
      		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
             SET v_endDateTime = CAST(v_curDate AS DATE); 
              
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
      	END IF;
      	IF p_datetype = 4 
          THEN 
      		SET v_startDateTime = p_startTmpstmp; 
     		SET v_endDateTime 	= p_endTmpstmp; 
              
             SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
              
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
      		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
      	END IF;
        
             IF p_queueId IS NOT NULL 
          THEN
      		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
      		CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
          ELSE
      		DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
             CREATE TEMPORARY TABLE temp_queueIDs
      		SELECT 	qid	AS queueId
     		FROM 	queue
             WHERE 	domainId = p_domainId;
          END IF;
          
             DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
          CREATE TEMPORARY TABLE tmp_Disposition
          SELECT did, dispositionName
          FROM 	disposition_status
          WHERE	domainId		= p_domainId
          AND	dispositionName	= 'Caller Disconnected';    
          
           IF p_datetype IN (1,2)
          THEN 
      		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
              CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
      		WITH RECURSIVE CTE_TIMINGS AS (
      			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
      			UNION ALL
      			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
      			FROM 	CTE_TIMINGS
      			WHERE 	endDateTime < v_endDateTime
      		)
      		SELECT * FROM CTE_TIMINGS;	
      	ELSEIF p_datetype IN (3,4)
          THEN 
      		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
              CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
      		WITH recursive CTE_TIMINGS AS (
      			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
      			UNION ALL
      			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
      			FROM 	CTE_TIMINGS
      			WHERE 	startDateTime < v_endDateTime
      		)
      		SELECT * FROM CTE_TIMINGS;	
          END IF; 
          
          ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
          
          UPDATE tmp_timings
          SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
      		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
              
      	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
     	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
     	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
     	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
        
         	DROP TEMPORARY TABLE IF EXISTS tmp_InstagramDurationHistory;	
     	CREATE TEMPORARY TABLE tmp_InstagramDurationHistory
     	SELECT 	CH.InstagramHistoryId
     		,	CH.sessionStartTime
     		,	CH.IsMissed
     		,	CH.dispositionId        
     		,	CH.dialDuration
			,   CH.Duration
            ,   CASE WHEN CH.dialDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END  	AS Total
			,   CASE WHEN CH.IsInBound =1 THEN 1 ELSE 0 END       				  	AS incomingChats
     	FROM 	 tb_InstagramHistory 			 CH
     
		LEFT JOIN 	temp_queueIDs			Q	ON 	Q.queueId			= CH.QueueId	
     	WHERE 	CH.domainId 		= p_domainId
     	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
     
     
          DROP TEMPORARY TABLE IF EXISTS tmp_InstagramDurationHistory_cal;	
		CREATE TEMPORARY TABLE tmp_InstagramDurationHistory_cal
			select 
				incomingChats, InstagramHistoryId, sessionStartTime, IsMissed, dispositionId,
				dialDuration, Duration, 
				sum(Total/incomingChats)*100        	as SLAachieved ,
				100 - sum((Total/incomingChats)*100)  	as SLABleached
				FROM tmp_InstagramDurationHistory
				GROUP BY incomingChats, InstagramHistoryId, sessionStartTime, IsMissed, dispositionId,
				dialDuration, Duration; 
     
     
     	DROP TEMPORARY TABLE IF EXISTS tmp_InstagramHistory;	
      	CREATE TEMPORARY TABLE tmp_InstagramHistory
         SELECT 	DISTINCT 
      			CDH.InstagramHistoryId 
      		, 	CDH.sessionStartTime
      	FROM 	tmp_InstagramDurationHistory CDH;  
        
		select count(Distinct InstagramHistoryId) into v_tot_cur_chat from tmp_InstagramHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;           
		select count(Distinct InstagramHistoryId) into v_tot_past_chat from tmp_InstagramHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;  

          
			ALTER TABLE tmp_InstagramHistory ADD IsMissed 			TINYINT default 0;
			ALTER TABLE tmp_InstagramHistory ADD IsAnswered 		TINYINT default 0;
			ALTER TABLE tmp_InstagramHistory ADD IsUnAnswered 		TINYINT default 0;
			ALTER TABLE tmp_InstagramHistory ADD IsAbandoned		TINYINT default 0;
			ALTER TABLE tmp_InstagramHistory ADD TotalSLA			TINYINT default 0;
			ALTER TABLE tmp_InstagramHistory ADD SLAacheived		INT default 0;
			ALTER TABLE tmp_InstagramHistory ADD SLAbleached		INT default 0;
          
		
            
            
             CREATE INDEX ix_tmp_CallHistory ON tmp_InstagramHistory (InstagramHistoryId);
			CREATE INDEX ix_tmp_CallDurationHistory ON tmp_InstagramDurationHistory (InstagramHistoryId);
            
      
		  UPDATE tmp_InstagramHistory			CH
          JOIN 	tmp_InstagramDurationHistory_cal	CDH	ON CH.InstagramHistoryId	= CDH.InstagramHistoryId  
          LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
          SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 			THEN 1 ELSE 0 	    END
      		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE 0	    END
            ,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 		THEN 1 ELSE 0	    END
            ,   CH.TotalSLA     = CASE WHEN CDH.dialDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END 
    		,	CH.IsAbandoned	= CASE WHEN D.did IS NOT NULL 		        THEN 1 ELSE 0 	END 
			,	CH.SLAacheived  = CDH.SLAachieved
			,	CH.SLAbleached  = CDH.SLAbleached;
            
		  IF p_columnName = 'Missed Chats'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'			AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
             
             INSERT INTO tmp_result
      		SELECT 	'Past'					    AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;       
            
            ELSEIF p_columnName = 'SLA Achieved (%)'
				THEN
					INSERT INTO tmp_result
						SELECT 	'Current'								  AS reportAge
							,	t_T.startDateTime 
							,	t_T.endDateTime
							,   IFNULL(SUM(CH.SLAacheived) / count(InstagramHistoryId), 0) AS callCount        
						FROM 	tmp_timings			t_T	
						LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
						WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
						GROUP BY t_T.startDateTime, t_T.endDateTime, InstagramHistoryId; 
        
					INSERT INTO tmp_result
						SELECT 	'Past'					        				AS reportAge
							,	t_T.startDateTime 
							,	t_T.endDateTime
							,   IFNULL(SUM(CH.SLAacheived) / count(InstagramHistoryId), 0) AS callCount 
						FROM 	tmp_timings		t_T	
						LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
						WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
						GROUP BY t_T.startDateTime, t_T.endDateTime,InstagramHistoryId; 

      	ELSEIF p_columnName = 'SLA Breached (%)'
                                  THEN
                             		INSERT INTO tmp_result
                              		SELECT 	'Current'								  AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                       ,   IFNULL(abs(CH.SLAbleached),0)            AS callCount   
                                       
                              		FROM 	tmp_timings			t_T	
                              		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                                    
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached; 
                                     
                                     INSERT INTO tmp_result
                              		SELECT 	'Past'					        									AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                         ,   IFNULL(abs(CH.SLAbleached),0)                                  AS callCount   
                                       
                              		FROM 	tmp_timings		t_T	
                              		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                                    
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached; 
       
       ELSEIF p_columnName = 'TotalSLA'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'					AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(TotalSLA),0)	    AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_InstagramHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
      		SELECT 	'Past'						AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(TotalSLA),0)	    AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_InstagramHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
               
	
      
      
      END IF;
      
        SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Current';    
         
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Past';
          
     	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_cur_chat=0,1,v_tot_cur_chat) else 1 end)	
        AS currentCount, 
        SUM(CASE WHEN reportAge = 'Past' THEN callCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_past_chat=0,1,v_tot_past_chat) else 1 end)	
        AS pastCount
     	INTO 	v_currentCount, v_pastCount		
     	FROM 	tmp_result;
        
        if p_columnName = 'SLA Breached (%)' then
				select sum(SLAbleached)/count(Distinct InstagramHistoryId) into v_currentCount from tmp_InstagramHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;
				select sum(SLAbleached)/count(Distinct InstagramHistoryId) into v_pastCount from tmp_InstagramHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;   
                                 
					if IFNULL(v_currentCount,0)=0 then set v_currentCount = 0; end if;
					if IFNULL(v_pastCount,0)=0 then set v_pastCount = 0; end if;
                                 
			End if;
         
         SELECT 	p_columnName    													AS metric
   		  ,		ifnull(v_currentCount,0)											AS currentTotal
     		  , 	ifnull(v_pastCount,0)												AS pastTotal
   		  ,	    ifnull((v_currentCount - v_pastCount),0)  							AS totalDifference
           
             ,			case when (v_currentCount - v_pastCount) > 0 and v_pastCount !=0  
					then (v_currentCount - v_pastCount) /(v_pastCount) *100 ELSE 0 END		AS  Percentage;
         
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_queue_services_level_agreement_metrics_analysis` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_queue_services_level_agreement_metrics_analysis`(  
             p_domainId 			INT,
             p_Offset			    INT,
             p_Limit				INT  
          )
BEGIN
      
           	DECLARE v_Total_count 	INT;
           	DECLARE v_offset		INT;    
      	    DECLARE v_startTmpstmp 	BIGINT;
      	    DECLARE v_endTmpstmp 	BIGINT;  
           	SET v_offset =  p_Limit * p_Offset; 
             
             
             SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000;        
             SET @v_endTmpstmp 	= unix_timestamp(now())*1000;       
      
     	        
			DROP TEMPORARY TABLE IF EXISTS temp_queueIds; 	    CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));

		
           	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
           	CREATE TEMPORARY TABLE temp_AllqueueId
           	select qid,name as queueName from queue where domainId = p_domainId;
           
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
			CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
					SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		          AS SessionDate
					,SDH.QueueId                  
					,Q.name														      			  AS queueName                     
					,(SDH.EndTime - SDH.StartTime)                                                AS ChatDuration                 
					FROM 	tb_ChatHistory 				SH
					JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
					LEFT JOIN 	queue					Q	ON SDH.queueId			= Q.qid  
					WHERE 	SH.domainId 		= p_domainId	
					AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
					AND		SH.IsInBound		= 1	
					LIMIT 	v_offset, p_Limit; 
  
     	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                 	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                 	SELECT 	
    						 a.SessionDate 				       										                                               AS 'Date'                  
    						,a.QueueId																										       AS QueueId
    						,a.queueName																                                   	       AS queueName
                            ,sum(a.ChatDuration)                                                                                                   AS totalDuration
							,SUM(CASE WHEN a.chatDuration BETWEEN 1 	AND 5000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  SL1
							,SUM(CASE WHEN a.chatDuration BETWEEN 5001 	AND 10000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  SL2
							,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  SL3
							,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  SL4
							,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  SL5
							,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  SL6
							,sum(CASE WHEN a.chatDuration BETWEEN   1 	AND 30000 	AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  TotalSLA
							,(CASE WHEN a.chatDuration > 30000  then 1 	else 0 		END)								                           AS  MissedChats       
							FROM temp_ChatHistory a     
							GROUP BY a.SessionDate,a.QueueId,a.queueName,a.chatDuration;
           		
                SELECT 	COUNT(1) v_Total_Count
           		FROM 	temp_chatHistory_calc a; 
                  
				SELECT
					 CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE '-'  END         	                                                              AS queueName
					,CASE WHEN (a.SL1) IS NOT NULL THEN (a.SL1) else '0' end                                                                               as SL1                  
					,a.SL2
					,a.SL3
					,a.SL4
					,a.SL5
					,a.SL6 
					,sum(SL1+SL2+SL3+SL4+SL5+SL6)	                                                                                                      AS TotalSLA        
					,a.MissedChats																														  as MissedChats
					,CASE WHEN (a.TotalSLA/a.totalDuration) IS NOT NULL THEN (a.TotalSLA/a.totalDuration) ELSE '-' END                                    AS SLAachieved
					,CASE WHEN (count(a.MissedChats)/a.totalDuration)*100	IS NOT NULL THEN (count(a.MissedChats)/a.totalDuration)*100  ELSE '-'  END    AS SLAbreached
					FROM temp_chatHistory_calc a
					GROUP BY a.queueName,a.SL1,a.SL2,a.SL3,a.SL4 ,a.SL5,a.SL6,a.MissedChats,a.TotalSLA,a.totalDuration;
					 
                END ;;
DELIMITER ;
