DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_services_level_agreement_metrics_analysis_1`(  
           p_domainId 			INT,
           p_Limit				INT  ,
           p_Offset			    INT
        )
BEGIN
    
         	DECLARE v_Total_count 	INT;
         	DECLARE v_offset		INT;    
    	    DECLARE v_startTmpstmp 	BIGINT;
    	    DECLARE v_endTmpstmp 	BIGINT;  
         	SET v_offset =  p_Limit * p_Offset; 
           
           
           SET @v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000;        
           SET @v_endTmpstmp 	= unix_timestamp(now())*1000;       
    
   	        
       	DROP TEMPORARY TABLE IF EXISTS temp_queueIds; 	    CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
         	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
         	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                    	
          
         	
         	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
         	CREATE TEMPORARY TABLE temp_AllagentId
         	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3);    
             
         	DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
         	CREATE TEMPORARY TABLE temp_AllqueueId
         	select qid,name as queueName from queue where domainId = p_domainId;
         
              	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
       	CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
             	SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		AS SessionDate

					 , SDH.QueueId                  
   				     ,	Q.name														      AS queueName                     
                     , SDH.Duration                                                       AS chatDuration                 
      			      , SDH.Duration												      AS Duration
           	FROM 	tb_ChatHistory 				SH
           	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
       		LEFT JOIN 	queue					Q	ON SDH.queueId			= Q.qid  
           	WHERE 	SH.domainId 		= p_domainId	
   			   AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
           	   AND		SH.IsInBound		= 1	
                        LIMIT 	v_offset, p_Limit; 

   	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
               	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
               	SELECT 	
  						 a.SessionDate 				       										                               AS 'Date'                  
  						,a.QueueId
  						,a.queueName																                                   AS queueName
                         ,sum(a.Duration)                                                                                              AS totalDuration
                      ,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               AS  SL1
  				    ,SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)             AS  SL2
  					,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL3
                      ,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          AS  SL4
                      ,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          AS  SL5
                      ,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          AS  SL6
                      ,sum(CASE WHEN a.chatDuration BETWEEN   1 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  TotalSLA
                      ,(CASE WHEN a.chatDuration > 30000  then 1 else 0 END)								                           AS  MissedChats       
                      FROM temp_ChatHistory a     
                      GROUP BY a.SessionDate,a.QueueId,a.queueName,a.chatDuration;
         		SELECT 	COUNT(1) v_Total_Count
         		FROM 	temp_chatHistory_calc a; 
                
                      SELECT
 					  CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE '-'  END         	                                                            AS queueName
                        ,a.SL1
   				       ,a.SL2
                       ,a.SL3
                       ,a.SL4
                       ,a.SL5
                       ,a.SL6 
                       ,sum(SL1+SL2+SL3+SL4+SL5+SL6)	                                                                                                     AS TotalSLA1        
                       ,a.MissedChats
                       ,CASE WHEN (a.TotalSLA/a.totalDuration) IS NOT NULL THEN (a.TotalSLA/a.totalDuration) ELSE '-' END                                    AS SLAachieved
                       ,CASE WHEN (count(a.MissedChats)/a.totalDuration)*100	IS NOT NULL THEN (count(a.MissedChats)/a.totalDuration)*100  ELSE '-'  END   AS  SLAbreached
                       FROM temp_chatHistory_calc a
 						GROUP BY a.queueName,a.SL1,a.SL2,a.SL3,a.SL4 ,a.SL5,a.SL6,a.MissedChats,a.TotalSLA,a.totalDuration;
                        
              END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_services_level_metrics_Trend_Chart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_services_level_metrics_Trend_Chart`(	
        	p_domainId 			INT
        	,p_datetype 		INT                 
        	,p_startDateTime	DATETIME
        	,p_endDateTime		DATETIME
        	,p_columnName    	VARCHAR(200)        
        	,p_agentId 			TEXT
 		,p_timezone			Text
        )
sp_return:BEGIN
    			DECLARE v_startDateTime			DATETIME;
    			DECLARE v_endDateTime			DATETIME;
    			DECLARE v_datetimeInterval		SMALLINT;
    			DECLARE v_startDateTimePast		DATETIME;
    			DECLARE v_endDateTimePast		DATETIME;
    
    			DECLARE v_startTimestampPast	BIGINT;
    			DECLARE v_endTimestampPast		BIGINT;      
    			DECLARE v_startTimestamp		BIGINT;
    			DECLARE v_endTimestamp			BIGINT;
    			DECLARE v_curDate				DATETIME DEFAULT NOW();	
    			DECLARE v_currentCount			INT;
    			DECLARE v_pastCount				INT;
    			DECLARE v_tot_cur_chat			INT;
    			DECLARE v_tot_past_chat			INT;
    			
                 
                
                                
        				DROP TEMPORARY TABLE IF EXISTS tmp_result;
        				CREATE TEMPORARY TABLE tmp_result(
        					reportAge			VARCHAR(20)
        					,startDateTime		DATETIME
        					,endDateTime		DATETIME
        					,callCount			INT
        				);    
                             
                             	IF p_datetype = 1 
                                 THEN 	
                             		SET v_startDateTime = CAST(v_curDate AS DATE); 
                             		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
                             
                             		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
                             		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
                             	END IF;
                             	IF p_datetype = 2 
                                 THEN 
                             		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
 									SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
                             
                             		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
                             		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY); 
                                                                        
                             	END IF;
                             	IF p_datetype = 3 
                                 THEN 
                             		
                                    
                                    SET v_startDateTime = p_startDateTime; 
     								SET v_endDateTime 	= p_endDateTime; 
                                     
     								SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                                     
                             		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                             		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                                    
                             	END IF;
                             	IF p_datetype = 4 
                                 THEN 
                             		SET v_startDateTime = p_startDateTime; 
     								SET v_endDateTime 	= p_endDateTime; 
                                     
     								SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                                     
                             		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                             		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
 
                             	END IF;
                                 
                          IF p_agentId IS NOT NULL 
                                  THEN
                              		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
                              		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
                                  ELSE
                              		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                                     CREATE TEMPORARY TABLE temp_agentIds
                            		 select  UserID as agentId from tb_User where domainId = p_domainId; 
                         		END IF;
                                 
                                 DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
                                 CREATE TEMPORARY TABLE tmp_Disposition
                                 SELECT did, dispositionName
                                 FROM 	disposition_status
                                 WHERE	domainId		= p_domainId
                                 AND	dispositionName	= 'Caller Disconnected';    
                                 
                                 IF p_datetype IN (1,2)
                                 THEN 
 								DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
  								CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
  								WITH RECURSIVE CTE_TIMINGS AS (
  								SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
  								UNION ALL
  								SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
  								FROM 	CTE_TIMINGS
  								WHERE 	endDateTime < v_endDateTime
                             		)
                             		SELECT * FROM CTE_TIMINGS;	
  								ELSEIF p_datetype IN (3,4)
                                 THEN 
 								DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
  								CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
  								WITH recursive CTE_TIMINGS AS (
  								SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND) AS endDateTime
  								UNION ALL
  								SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
  								FROM 	CTE_TIMINGS
  								WHERE 	startDateTime < v_endDateTime
                             		)
                             		SELECT * FROM CTE_TIMINGS;	
  								END IF;  
                                 
                                 ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, 
     													ADD COLUMN endTimestamp		BIGINT;
                                 
                                 UPDATE tmp_timings
                                 SET		
     									
     									startTimestamp = unix_timestamp(convert_tz(startDateTime,p_timezone,'+00:00')) * 1000,
     									endTimestamp = unix_timestamp(convert_tz(endDateTime,p_timezone,'+00:00')) * 1000;
                                 
                                 
                                if p_datetype IN (1,2) then
 								SET v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
     							,	v_endTimestampPast		= unix_timestamp(convert_tz(v_endDateTimePast,p_timezone,'+00:00')) * 1000  
     							,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000  
     							, 	v_endTimestamp			= unix_timestamp(convert_tz(v_endDateTime,p_timezone,'+00:00')) * 1000 ; 
                                End if;
                                if  p_datetype IN (3,4) then
                             	SET v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
     							,	v_endTimestampPast		= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000  
     							,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000  
     							, 	v_endTimestamp			= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTime,INTERVAL 1439 MINUTE),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 ; 
                                End if;
 
 							DROP TEMPORARY TABLE IF EXISTS tmp_ChatDurationHistory;	
                            	CREATE TEMPORARY TABLE tmp_ChatDurationHistory
                            	SELECT 	CH.ChatHistoryId
    								,	CDH.ChatDurationHistoryId
        							,	CH.sessionStartTime
        							,	CDH.IsMissed
        							,	CDH.dispositionId        
        							,	CH.dialDuration
        							,   CDH.Duration
        							,	CDH.IsAbandoned
        							,   CDH.answeredDuration
        							,   CASE WHEN CDH.answeredDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END  	AS Total
        							,   CASE WHEN CH.IsInBound =1 THEN 1 ELSE 0 END                       	AS incomingChats
               				FROM 	tb_ChatHistory 			CH
                   			JOIN 	tb_ChatDurationHistory	  	CDH		ON 	CH.ChatHistoryId 	= CDH.ChatHistoryId        
          					JOIN    temp_agentIds 				t_A     ON t_A.agentId 		= CDH.agentId		
      						WHERE 	CH.domainId 			= p_domainId
 							AND 	CDH.IsBot 				= 0
      						AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
          					AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL)); 
                             
        					DROP TEMPORARY TABLE IF EXISTS tmp_ChatDurationHistory_cal;	
        					CREATE TEMPORARY TABLE tmp_ChatDurationHistory_cal
        					select 
        						incomingChats, ChatHistoryId,ChatDurationHistoryId, sessionStartTime, IsMissed, dispositionId,
        						dialDuration, Duration, IsAbandoned, answeredDuration, 
        						sum(Total/incomingChats)*100        	as SLAachieved ,
        						100 - sum((Total/incomingChats)*100)  	as SLABleached
        					FROM tmp_ChatDurationHistory
        					GROUP BY incomingChats, ChatHistoryId,ChatDurationHistoryId, sessionStartTime, IsMissed, dispositionId,
        					dialDuration, Duration, IsAbandoned, answeredDuration;
        
        					DROP TEMPORARY TABLE IF EXISTS tmp_ChatHistory;	
        					CREATE TEMPORARY TABLE tmp_ChatHistory
        					SELECT 	
        							CDH.ChatHistoryId 
    							,   CDH.ChatDurationHistoryId
        						, 	CDH.sessionStartTime
        					FROM 	tmp_ChatDurationHistory CDH;  
                           
       				select count(Distinct ChatDurationHistoryId) into v_tot_cur_chat from tmp_ChatHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;          
       				select count(Distinct ChatDurationHistoryId) into v_tot_past_chat from tmp_ChatHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;          
       
        					ALTER TABLE tmp_ChatHistory ADD IsMissed 		TINYINT default 0;
        					ALTER TABLE tmp_ChatHistory ADD IsAnswered 		TINYINT default 0;
        					ALTER TABLE tmp_ChatHistory ADD IsUnAnswered 	TINYINT default 0;
        					ALTER TABLE tmp_ChatHistory ADD IsAbandoned		TINYINT default 0;
        					ALTER TABLE tmp_ChatHistory ADD TotalSLA		INT default 0;
        					ALTER TABLE tmp_ChatHistory ADD SLAacheived		INT default 0;
        					ALTER TABLE tmp_ChatHistory ADD SLAbleached		INT default 0;
                             
        					CREATE INDEX ix_tmp_CallHistory ON tmp_ChatHistory (ChatHistoryId);
        					CREATE INDEX ix_tmp_CallDurationHistory ON tmp_ChatDurationHistory (ChatHistoryId);
                 
        					UPDATE 		tmp_ChatHistory				CH
        					JOIN 		tmp_ChatDurationHistory_cal	CDH	ON CH.ChatHistoryId	= CDH.ChatHistoryId   AND CH.ChatDurationHistoryId = CDH.ChatDurationHistoryId
        					LEFT JOIN 	tmp_Disposition				D	ON D.did			= CDH.dispositionId
        					SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 THEN 1 ELSE 0 	    END
        						,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0	    END
        						,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 THEN 1 ELSE 0	    END
        						, 	CH.TotalSLA     = CASE WHEN CDH.answeredDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END 
        						,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned=1 THEN 1 ELSE 0 	END
        						,	CH.SLAacheived  = CDH.SLAachieved
        						,	CH.SLAbleached  = CDH.SLAbleached;
                  
                               
                              IF p_columnName = 'Missed Chats'
                            	THEN
                            		INSERT INTO tmp_result
                             		SELECT 	'Current'			AS reportAge
                             			,	t_T.startDateTime 
                             			,	t_T.endDateTime
                             			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount
                             		FROM 	tmp_timings			t_T	
                             		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                             		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                             		GROUP BY t_T.startDateTime, t_T.endDateTime;
                                    
                                    INSERT INTO tmp_result
                             		SELECT 	'Past'					    AS reportAge
                             			,	t_T.startDateTime 
                             			,	t_T.endDateTime
                             			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount     
                             		FROM 	tmp_timings		t_T	
                             		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                             		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                             		GROUP BY t_T.startDateTime, t_T.endDateTime; 
                                   
                                 ELSEIF p_columnName = 'SLA Achieved (%)'
                                  THEN
                             		INSERT INTO tmp_result
                              		SELECT 	'Current'								  AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                       ,   IFNULL(SUM(CH.SLAacheived) / count(ChatDurationHistoryId), 0) AS callCount        
                              		FROM 	tmp_timings			t_T	
                              		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,ChatDurationHistoryId; 
        
        							INSERT INTO tmp_result
                              		SELECT 	'Past'					        				AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
           							,   IFNULL(SUM(CH.SLAacheived) / count(ChatDurationHistoryId), 0) AS callCount 
                              		FROM 	tmp_timings		t_T	
                              		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,ChatDurationHistoryId; 
                                   
                                    ELSEIF p_columnName = 'SLA Breached (%)'
                                  THEN
                             		INSERT INTO tmp_result
                              		SELECT 	'Current'								  AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                       ,   IFNULL(abs(CH.SLAbleached),0)            AS callCount   
                                       
                              		FROM 	tmp_timings			t_T	
                              		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                                    
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached; 
                                     
                                     INSERT INTO tmp_result
                              		SELECT 	'Past'					        									AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                                         ,   IFNULL(abs(CH.SLAbleached),0)                                  AS callCount   
                                       
                              		FROM 	tmp_timings		t_T	
                              		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                                    
                              		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached;
                                   
                          ELSEIF p_columnName = 'Total'
                            	THEN
                            		INSERT INTO tmp_result
                             		SELECT 	'Current'					AS reportAge
                             			,	t_T.startDateTime 
                             			,	t_T.endDateTime
                             			,	IFNULL(SUM(TotalSLA),0)	    AS callCount
                             		FROM 	tmp_timings			t_T	
                             		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                             		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                             		GROUP BY t_T.startDateTime, t_T.endDateTime;
                                    
                                    INSERT INTO tmp_result
                             		SELECT 	'Past'						AS reportAge
                             			,	t_T.startDateTime 
                             			,	t_T.endDateTime
                             			,	IFNULL(SUM(TotalSLA),0)	    AS callCount     
                             		FROM 	tmp_timings		t_T	
                             		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                             		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                             		GROUP BY t_T.startDateTime, t_T.endDateTime;
                             
                                ELSEIF p_columnName = 'Answered'
                                 THEN
                            		INSERT INTO tmp_result
                             		SELECT 	'Current'								  AS reportAge
                             			,	t_T.startDateTime 
                             			,	t_T.endDateTime
                                       ,   IFNULL(SUM(CH.IsAnswered),0)        AS callCount              
                             			
                             		FROM 	tmp_timings			t_T	
                             		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                             		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                             		GROUP BY t_T.startDateTime, t_T.endDateTime;
                                    
                                    INSERT INTO tmp_result
                             		SELECT 	'Past'					        									AS reportAge
                             			,	t_T.startDateTime 
                             			,	t_T.endDateTime
                                       ,   IFNULL(sum(CH.IsAnswered),0)                                  AS callCount   
                             		FROM 	tmp_timings		t_T	
                             		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                             		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                             		GROUP BY t_T.startDateTime, t_T.endDateTime;
                             
                              END IF;
                             
                               SELECT  *
                                FROM 	tmp_result
                                WHERE 	reportAge = 'Current';    
                                
                                SELECT  *
                                FROM 	tmp_result
                                WHERE 	reportAge = 'Past';
                                
 							SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_cur_chat=0,1,v_tot_cur_chat) else 1 end)	AS currentCount, 
 									SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_past_chat=0,1,v_tot_past_chat) else 1 end)	AS pastCount
 							INTO 	v_currentCount, v_pastCount		
 							FROM 	tmp_result;
                             
                             if p_columnName = 'SLA Breached (%)' then
 								select sum(SLAbleached)/count(Distinct ChatDurationHistoryId) into v_currentCount from tmp_ChatHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;
                                 select sum(SLAbleached)/count(Distinct ChatDurationHistoryId) into v_pastCount from tmp_ChatHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;   
                                 
                                 if IFNULL(v_currentCount,0)=0 then set v_currentCount = 0; end if;
                                 if IFNULL(v_pastCount,0)=0 then set v_pastCount = 0; end if;
                                 
                             End if;
                             
                                
        						SELECT 	p_columnName    																	AS metric
        						,		ifnull(v_currentCount,0)															AS currentTotal
        						, 		ifnull(v_pastCount,0)																AS pastTotal
        						,	    ifnull((v_currentCount - v_pastCount),0)  											AS totalDifference
        						,	    case when ifnull(v_pastCount,0)=0 then 100 
 										else ifnull((v_currentCount - v_pastCount) /(IF(v_pastCount=0,100,v_pastCount)) ,0)*100	
                                         End
 																														AS Percentage;
                                
                             END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
