CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_services_level_metrics_Trend_Chart_2`(	
	p_domainId 			INT,
	p_datetype 			INT,                 
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
	p_columnName    	VARCHAR(200),            
	p_agentId 			TEXT
)
BEGIN
         	DECLARE v_startDateTime			DATETIME;
         	DECLARE v_endDateTime			DATETIME;     
         	DECLARE v_datetimeInterval		SMALLINT;    
         	DECLARE v_startDateTimePast		DATETIME;
         	DECLARE v_endDateTimePast		DATETIME;
              
         	DECLARE v_startTimestampPast	BIGINT;
         	DECLARE v_endTimestampPast		BIGINT;      
         	DECLARE v_startTimestamp		BIGINT;
         	DECLARE v_endTimestamp			BIGINT;
         	DECLARE v_curDate				DATETIME DEFAULT NOW();	
            DECLARE v_currentCount			INT;
            DECLARE v_pastCount				INT;
             
         	DROP TEMPORARY TABLE IF EXISTS tmp_result;
         	CREATE TEMPORARY TABLE tmp_result(
         		reportAge			VARCHAR(20)
         		,startDateTime		DATETIME
         		,endDateTime		DATETIME
         		,callCount			INT
         	);    
          
          	IF p_datetype = 1 
              THEN 	
          		SET v_startDateTime = CAST(v_curDate AS DATE); 
          		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
          
          		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
          		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
          	END IF;
          	IF p_datetype = 2 
              THEN 
          		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
         		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
          
          		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
          		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
          	END IF;
          	IF p_datetype = 3 
              THEN 
          		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
                 SET v_endDateTime = CAST(v_curDate AS DATE); 
                  
          		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
          		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
          	END IF;
          	IF p_datetype = 4 
              THEN 
          		SET v_startDateTime = p_startDateTime; 
         		SET v_endDateTime 	= p_endDateTime; 
                  
                 SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                  
          		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
          		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
          	END IF;
              
       IF p_agentId IS NOT NULL 
               THEN
           		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
           		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
               ELSE
           		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                  CREATE TEMPORARY TABLE temp_agentIds
         		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
      		END IF;
              
              DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
              CREATE TEMPORARY TABLE tmp_Disposition
              SELECT did, dispositionName
              FROM 	disposition_status
              WHERE	domainId		= p_domainId
              AND	dispositionName	= 'Caller Disconnected';    
              
              IF p_datetype IN (1,2)
              THEN 
          		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                  CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
          		WITH RECURSIVE CTE_TIMINGS AS (
          			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
          			UNION ALL
          			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
          			FROM 	CTE_TIMINGS
          			WHERE 	endDateTime < v_endDateTime
          		)
          		SELECT * FROM CTE_TIMINGS;	
          	ELSEIF p_datetype IN (3,4)
              THEN 
          		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
                  CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
          		WITH recursive CTE_TIMINGS AS (
          			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
          			UNION ALL
          			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
          			FROM 	CTE_TIMINGS
          			WHERE 	startDateTime < v_endDateTime
          		)
          		SELECT * FROM CTE_TIMINGS;	
              END IF;  
              
              ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
              
              UPDATE tmp_timings
              SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
          		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
                  
          	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
         	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
         	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
         	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
          
          
           DROP TEMPORARY TABLE IF EXISTS tmp_ChatDurationHistory;	
         	CREATE TEMPORARY TABLE tmp_ChatDurationHistory
         	SELECT 	CH.ChatHistoryId
         		,	CH.sessionStartTime
         		,	CDH.IsMissed
         		,	CDH.dispositionId        
         		,	CH.dialDuration
    			,   CDH.Duration
    			,	CDH.IsAbandoned
         	FROM 	 tb_ChatHistory 			 CH
         JOIN 	tb_ChatDurationHistory	  CDH		ON 	CH.ChatHistoryId 	= CDH.ChatHistoryId        
          	JOIN     temp_agentIds 		       t_A     ON t_A.UserID 		= CDH.agentId		
         	WHERE 	CH.domainId 		= p_domainId
         	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
         
         
         select 'kms', a.* from tmp_ChatDurationHistory a;
          
          
          DROP TEMPORARY TABLE IF EXISTS tmp_ChatHistory;	
          	CREATE TEMPORARY TABLE tmp_ChatHistory
             SELECT 	DISTINCT 
          			CDH.ChatHistoryId 
          		, 	CDH.sessionStartTime
          	FROM 	tmp_ChatDurationHistory CDH;  
          
          
              ALTER TABLE tmp_ChatHistory ADD IsMissed 		TINYINT default 0;
              ALTER TABLE tmp_ChatHistory ADD IsAnswered 		TINYINT default 0;
              ALTER TABLE tmp_ChatHistory ADD IsUnAnswered 	TINYINT default 0;
              ALTER TABLE tmp_ChatHistory ADD IsAbandoned		TINYINT default 0;
              ALTER TABLE tmp_ChatHistory ADD TotalSLA		INT default 0;
          
          
      		CREATE INDEX ix_tmp_ChatHistory ON tmp_ChatHistory (ChatHistoryId);
              CREATE INDEX ix_tmp_ChatDurationHistory ON tmp_ChatDurationHistory (ChatHistoryId);
          
          
          
      		 UPDATE tmp_ChatHistory			CH
              JOIN 	tmp_ChatDurationHistory	CDH	ON CH.ChatHistoryId	= CDH.ChatHistoryId  
            
              SET 	CH.IsMissed	= CASE WHEN CDH.IsMissed = 1 THEN 1 ELSE 0 	    END
      		  ,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0	    END
                ,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 THEN 1 ELSE 0	    END
                , CH.TotalSLA     = CASE WHEN CDH.dialDuration BETWEEN 0 AND 3000 THEN 1 ELSE 0 END 
        		  ,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned=1 THEN 1 ELSE 0 	END;     
                
      
            
           IF p_columnName = 'Missed Chats'
         	THEN
         		INSERT INTO tmp_result
          		SELECT 	'Current'			AS reportAge
          			,	t_T.startDateTime 
          			,	t_T.endDateTime
          			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount
          		FROM 	tmp_timings			t_T	
          		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
          		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
          		GROUP BY t_T.startDateTime, t_T.endDateTime;
                 
                 INSERT INTO tmp_result
          		SELECT 	'Past'					    AS reportAge
          			,	t_T.startDateTime 
          			,	t_T.endDateTime
          			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount     
          		FROM 	tmp_timings		t_T	
          		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
          		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
          		GROUP BY t_T.startDateTime, t_T.endDateTime;      
       ELSEIF p_columnName = 'Total'
         	THEN
         		INSERT INTO tmp_result
          		SELECT 	'Current'					AS reportAge
          			,	t_T.startDateTime 
          			,	t_T.endDateTime
          			,	IFNULL(SUM(TotalSLA),0)	    AS callCount
          		FROM 	tmp_timings			t_T	
          		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
          		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
          		GROUP BY t_T.startDateTime, t_T.endDateTime;
                 
                 INSERT INTO tmp_result
          		SELECT 	'Past'						AS reportAge
          			,	t_T.startDateTime 
          			,	t_T.endDateTime
          			,	IFNULL(SUM(TotalSLA),0)	    AS callCount     
          		FROM 	tmp_timings		t_T	
          		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
          		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
          		GROUP BY t_T.startDateTime, t_T.endDateTime;
          
             ELSEIF p_columnName = 'Answered'
              THEN
         		INSERT INTO tmp_result
          		SELECT 	'Current'								  AS reportAge
          			,	t_T.startDateTime 
          			,	t_T.endDateTime
                    ,   IFNULL(SUM(CH.IsAnswered),0)        AS callCount              
          			
          		FROM 	tmp_timings			t_T	
          		LEFT JOIN tmp_ChatHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
          		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
          		GROUP BY t_T.startDateTime, t_T.endDateTime;
                 
                 INSERT INTO tmp_result
          		SELECT 	'Past'					        									AS reportAge
          			,	t_T.startDateTime 
          			,	t_T.endDateTime
                    ,   IFNULL(sum(CH.IsAnswered),0)                                  AS callCount   
          		FROM 	tmp_timings		t_T	
          		LEFT JOIN 	tmp_ChatHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
          		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
          		GROUP BY t_T.startDateTime, t_T.endDateTime;
    
   
    
    
          
           END IF;
          
            SELECT  *
             FROM 	tmp_result
             WHERE 	reportAge = 'Current';    
             
             SELECT  *
             FROM 	tmp_result
             WHERE 	reportAge = 'Past';
              
         	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
         	INTO 	v_currentCount, v_pastCount		
         	FROM 	tmp_result;
             
             SELECT 	p_columnName    													AS metric
       		  ,		ifnull(v_currentCount,0)											AS currentTotal
         		  , 	ifnull(v_pastCount,0)												AS pastTotal
       		  ,	    ifnull((v_currentCount - v_pastCount),0)  							AS totalDifference
                ,	ifnull((v_currentCount - v_pastCount) /(v_currentCount) *100 ,0)		AS  Percentage;
                
             
        
          
          END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_SMS_Agent_Inbound_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_SMS_Agent_Inbound_trendchart`(
   	p_domainId 			INT,
   	p_datetype 			INT,            
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
   	p_columnName    	VARCHAR(200),    	
   	p_agentId 			TEXT
    )
BEGIN
 
  	DECLARE v_startDateTime			DATETIME;
  	DECLARE v_endDateTime			DATETIME;     
  	DECLARE v_datetimeInterval		SMALLINT;    
  	DECLARE v_startDateTimePast		DATETIME;
  	DECLARE v_endDateTimePast		DATETIME;
       
  	DECLARE v_startTimestampPast	BIGINT;
  	DECLARE v_endTimestampPast		BIGINT;      
  	DECLARE v_startTimestamp		BIGINT;
  	DECLARE v_endTimestamp			BIGINT;
  	DECLARE v_curDate				DATETIME DEFAULT NOW();	
	DECLARE v_currentCount			INT;
	DECLARE v_pastCount				INT;
      
  	DROP TEMPORARY TABLE IF EXISTS tmp_result;
  	CREATE TEMPORARY TABLE tmp_result(
  		reportAge			VARCHAR(20)
  		,startDateTime		DATETIME
  		,endDateTime		DATETIME
  		,callCount			INT
  	);    
   
   	IF p_datetype = 1 
       THEN 	
   		SET v_startDateTime = CAST(v_curDate AS DATE); 
   		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
   	END IF;
   	IF p_datetype = 2 
       THEN 
   		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
  		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
   
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
   	END IF;
   	IF p_datetype = 3 
       THEN 
   		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
          SET v_endDateTime = CAST(v_curDate AS DATE); 
           
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
   		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
   	END IF;
   	IF p_datetype = 4 
       THEN 
   		SET v_startDateTime = p_startDateTime; 
  		SET v_endDateTime 	= p_endDateTime; 
           
          SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
           
   		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
   		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
   	END IF;
       
         IF p_agentId IS NOT NULL 
         THEN
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
     		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
         ELSE
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
            CREATE TEMPORARY TABLE temp_agentIds
   		 select  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
		END IF;
       
                      		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                  		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                  		(    DispositionId 			INT
                  			,DispositionStatus 		VARCHAR(100)
                  			,DispositionCategory	TINYINT
                  		); 
                          
                  		INSERT INTO temp_AvailableDisposition 
                  		SELECT 	did 			DispositionId
                  			,	dispositionName	DispositionStatus
                  			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                  				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                  				WHEN dispositionName = 'Discarded'     THEN 4
           					    WHEN dispositionName = 'Resolved'      THEN 5
                  				END 			DispositionCategory
                  		FROM 	disposition_status
                  		WHERE 	domainId	= p_domainId;   
       
       IF p_datetype IN (1,2)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   		WITH RECURSIVE CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	endDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
   	ELSEIF p_datetype IN (3,4)
       THEN 
   		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
           CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   		WITH recursive CTE_TIMINGS AS (
   			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
   			UNION ALL
   			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
   			FROM 	CTE_TIMINGS
   			WHERE 	startDateTime < v_endDateTime
   		)
   		SELECT * FROM CTE_TIMINGS;	
       END IF;  
       
       ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
       
       UPDATE tmp_timings
       SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
   		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
           
   	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
  	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
  	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
  	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
  
    DROP TEMPORARY TABLE IF EXISTS tmp_SMSDurationHistory;	
  	CREATE TEMPORARY TABLE tmp_SMSDurationHistory
  	SELECT 	CH.SMSHistoryId
  		,	CH.sessionStartTime
  		
  		,	CH.dispositionId          
  		,	CDH.Duration
        ,   CH.isOpened
		,	CASE WHEN TIMESTAMPDIFF(HOUR, CH.createdAt, NOW()) >= P.smsThreshold AND dispositionId IS NULL THEN 1 ELSE 0 END AS overdue
	FROM 	tb_SMSHistory 				CH
	JOIN 	tb_SMSDurationHistory		CDH	    ON CH.SMSHistoryId 	= CDH.SMSHistoryId
    JOIN 	did_purchase				P		ON 	P.your_number	= CH.calledNumber
												AND	P.domainId		= CH.domainId
	WHERE 	CH.domainId 		= p_domainId
	and 	CDH.AgentId > 0
	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
	AND 	CH.IsInBound		= 1;   
    
    DROP TEMPORARY TABLE IF EXISTS tmp_SMSHistory;	
     	CREATE TEMPORARY TABLE tmp_SMSHistory
        SELECT 	DISTINCT 
     			CDH.SMSHistoryId 
     		, 	CDH.sessionStartTime
            ,   CDH.isOpened
            ,   CDH.overdue
            ,   CDH.dispositionId
     	FROM 	tmp_SMSDurationHistory CDH;  

          ALTER TABLE tmp_SMSHistory ADD IsOverdue     INT default 0;
         ALTER TABLE tmp_SMSHistory ADD IsAnswered 	INT default 0;
         ALTER TABLE tmp_SMSHistory ADD IsAbandoned	INT default 0;
         
         CREATE INDEX ix_tmp_EmailHistory ON tmp_SMSHistory (SMSHistoryId);
         CREATE INDEX ix_tmp_EmailDurationHistory ON tmp_SMSDurationHistory (SMSHistoryId);
    
		UPDATE tmp_SMSHistory			CH
		JOIN 	tmp_SMSDurationHistory	CDH	ON CH.SMSHistoryId	= CDH.SMSHistoryId  
		
		SET    CH.IsOverdue		= CASE WHEN CDH.overdue = 1			THEN 1 ELSE CH.IsOverdue 		END
		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 		THEN 1 ELSE CH.IsAnswered 	END
		,	CH.dispositionId	= CASE WHEN CDH.dispositionId IS NOT NULL 		THEN 1 ELSE CH.IsAbandoned 	END; 

             	
    IF p_columnName = 'Overdue'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(CH.IsOverdue),0)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(CH.IsOverdue),0)	AS callCount   
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
    
  ELSEIF p_columnName = 'Received SMS'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.SMSHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.SMSHistoryId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;   
    
 ELSEIF p_columnName = 'Responded SMS'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'				AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.dispositionId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	sum(CASE WHEN CH.dispositionId IS NOT NULL THEN  1 ELSE 0 END)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
              END IF;       
    
   
             SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Current';    
          
          SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Past';
           
      	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
      	INTO 	v_currentCount, v_pastCount		
      	FROM 	tmp_result;
        
        
        end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_sms_agent_performances_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_sms_agent_performances_analysis_metrics_filter`(  
                      p_startTmpstmp 		BIGINT,
                      p_endTmpstmp 		BIGINT,
                      p_domainId 			INT,    	
                      p_agentId			TEXT,		
                      p_offset 			INT,
                      p_Limit 			INT	
                               )
BEGIN
                           
     				DECLARE v_offset 								INT;	  	
     				DECLARE v_CurrentStartTmpstmp 					BIGINT;
     				DECLARE v_CurrentEndTmpstmp 					BIGINT;
     				DECLARE v_PrevStartTmpstmp 						BIGINT;
     				DECLARE v_PrevEndTmpstmp 						BIGINT; 
     				DECLARE v_TmpstmpInterval						BIGINT;	
     				DECLARE v_PrevAverageResponseCount				INT;	
     				DECLARE v_CurrentAverageResponseCount			INT;	        
     				DECLARE v_DiffAverageResponsePercent			INT;
     				DECLARE v_PrevAverageHandledCount				INT;	
     				DECLARE v_CurrentAverageHandledCount			INT;
     				DECLARE v_DiffAverageHandledPercent				INT;  	    
     		
     				DECLARE v_DiffMaximumHandledTimePercent			INT;    
     				DECLARE v_DiffTotalACWTimePercent	  			INT;   
     				DECLARE v_DiffAverageQueueWaitingPercent		INT; 
     				DECLARE v_PrevaverageHoldtCount		        	INT;	
     				DECLARE v_CurrentaverageHoldtCount		    	INT;	        
     				DECLARE v_DiffaverageHoldtPercent		    	INT; 
     				DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
     				DECLARE v_DifffirstChatResolutionPercent		INT;  
     				DECLARE v_PreSentimentalScore              		INT;
     				DECLARE v_CurrentSentimentalScore          		INT;
     				DECLARE v_DiffSentimentalScorePercent      		INT;      
     				DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
     				DECLARE v_DifffirsAgentIdleTimePercent	        INT;    

					DECLARE		v_agentIdleTime						BIGINT;
					DECLARE		v_averageResponseTime             	BIGINT; 
					DECLARE		v_averageHandledTime				BIGINT;
					DECLARE		v_MaximumHandledTime              	BIGINT; 
					DECLARE		v_totalACWTime						BIGINT;
					DECLARE		v_averageHoldtime                 	BIGINT; 
					DECLARE		v_averageQueueWaittime				BIGINT;
					DECLARE		v_maximumQueueWaittime            	BIGINT; 
					DECLARE		v_occupancyRate       				BIGINT;
					DECLARE		v_firstChatResolution             	BIGINT; 
					DECLARE		v_CustomerSatisfaction				BIGINT; 
					DECLARE		v_callDuration						BIGINT; 
					DECLARE		v_afterChatWorkTime					INT; 
					DECLARE		v_availableTime						BIGINT; 
					DECLARE		v_currentResponseTime				BIGINT; 
					DECLARE		v_previousResponseTime				BIGINT; 
					DECLARE		v_currentHandledTime				BIGINT; 
					DECLARE		v_previousHandledTime				BIGINT; 
					DECLARE		v_currentTotalAnsweredChats			INT; 
					DECLARE		v_previousTotalAnsweredChats		INT; 
					DECLARE       v_count							INT;
					DECLARE       v_answerChat						INT;

					DECLARE		v_prvcount							INT;
					DECLARE		v_prevAnswerChat					INT; 
					DECLARE		v_prevAverageResponseTime			INT;
					DECLARE		v_prevAverageHandledTime			INT;
					DECLARE		v_CurrentTotalCount					INT;
					DECLARE		v_PreviousTotalCount				INT;
					DECLARE		v_currentAVGHandleTime				INT;
					DECLARE		v_prevAVGHandleTime					INT;
     
  				SET v_offset =  p_Limit * p_offset; 
  
  				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
  				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
  
  				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
  
  				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
  				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                      		
     				DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     				CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
     
     				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
     						               
     				DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     				CREATE TEMPORARY TABLE temp_AvailableDisposition 
     			(    DispositionId 			INT
     				,DispositionStatus 		VARCHAR(100)
     				,DispositionCategory	TINYINT
     			); 
     			  
     				INSERT INTO temp_AvailableDisposition 
     				SELECT 	did 			DispositionId
     					,	dispositionName	DispositionStatus
     					,	CASE WHEN dispositionName = 'Opened'	THEN 2
     						WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
     						WHEN dispositionName = 'Discarded'     THEN 4
     						WHEN dispositionName = 'Resolved'      THEN 5
     						END 			DispositionCategory
     				FROM 	disposition_status
     				WHERE 	domainId	= p_domainId;
                                	
     				DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
     				CREATE TEMPORARY TABLE temp_FirstCallResolution
  					SELECT 
  					COUNT(SubQuery.AgentId) AS FirstCallResolution,
  					SubQuery.AgentId,SubQuery.SMSHistoryId
  					FROM (
  					SELECT 
  					SDH.AgentId,SH.SMSHistoryId
  					FROM 	tb_SMSHistory 					SH
     				JOIN 	tb_SMSDurationHistory			SDH	ON SH.SMSHistoryId 		= SDH.SMSHistoryId
  					JOIN disposition_status 				DS ON DS.did = SH.dispositionId
  					WHERE SDH.IsBot = 0
  					AND SH.domainId = p_domainId
  					AND SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
					AND	DS.dispositionName <> 'Transferred'
  					GROUP BY SDH.AgentId, SH.SMSHistoryId
  					HAVING COUNT(SDH.SMSDurationHistoryId) = 1
     				) AS SubQuery
     				GROUP BY SubQuery.AgentId,SubQuery.SMSHistoryId;
                     
     				DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
     				CREATE TEMPORARY TABLE temp_AllagentId
     				SELECT UserID,UserName,ext,domainId FROM tb_User WHERE domainId = p_domainId ; 

     				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     				DROP TEMPORARY TABLE IF EXISTS tt_ChatHistory; 
     				CREATE TEMPORARY TABLE tt_ChatHistory AS 	    	
     				SELECT 	SH.sessionStartTime
                     ,SH.SMSHistoryId
     				, SDH.AgentId
     				, t_A.UserName																								
     				, IFNULL(SDH.Duration,0)									AS Duration											
     				, IFNULL(SDH.AgentHoldDuration,0) 							AS AgentHoldDuration
     				, IFNULL(SH.afterSMSWorkTime * 1000,0)						AS afterSMSWorkTime	
     				, IFNULL(CF.satisfactionRate,0) 							AS satisfactionRate
     				, IFNULL(t_f.FirstCallResolution,0) 						AS FirstCallResolution
                    , CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END 	AS resolvedCount
     				FROM 	tb_SMSHistory 					SH
     				JOIN 	tb_SMSDurationHistory			SDH	ON SH.SMSHistoryId 		= SDH.SMSHistoryId     
     				LEFT JOIN temp_AvailableDisposition		t_D	ON SH.dispositionId		= t_D.DispositionId
     				LEFT JOIN temp_agentIDs 				tA 	ON SDH.AgentId 			= tA.agentId       
     				JOIN temp_AllagentId 					t_A ON SDH.AgentId 			= t_A.UserID       
     				LEFT JOIN temp_FirstCallResolution 		t_f	ON t_f.SMSHistoryId 	= SDH.SMSHistoryId
                    LEFT JOIN tb_customerFeedback			CF	ON CF.historyId			= SH.SMSHistoryId AND CF.channelTypeId = 2003002
     				WHERE 	SH.domainId 		= p_domainId	
 				 	AND 	 SDH.IsBot			= 0      
     				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
     				AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.UserID IS NOT NULL)); 

					DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
     				CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
     				SELECT sessionStartTime	
					, SMSHistoryId
     				, UserName																AS agentName
                    , CASE WHEN Duration > 0 THEN 1 ELSE 0 END      						AS ResponsedChat
     				, CASE WHEN Duration > 0 THEN Duration ELSE 0 END 						AS ResponsedDuration
     				, CASE WHEN AgentHoldDuration > 0 THEN AgentHoldDuration ELSE 0 END		AS agentHoldDuration
     				, (Duration + afterSMSWorkTime)											AS HandledDuration                                 
     				, afterSMSWorkTime
     				, satisfactionRate
     				, FirstCallResolution
					FROM 	tt_ChatHistory 				
     				WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ; 

                  DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_prev; 
     				CREATE TEMPORARY TABLE temp_ChatHistory_prev AS 	    	
     				SELECT SMSHistoryId	
						, sessionStartTime
						, UserName																AS agentName
						, CASE WHEN Duration > 0 THEN 1 ELSE 0 END      						AS ResponsedChat
						, CASE WHEN Duration > 0 THEN Duration ELSE 0 END 						AS ResponsedDuration
						, CASE WHEN AgentHoldDuration > 0 THEN AgentHoldDuration ELSE 0 END		AS agentHoldDuration
						, (Duration + afterSMSWorkTime)											AS HandledDuration                                 
						, afterSMSWorkTime
						, satisfactionRate
						, FirstCallResolution
     				FROM 	tt_ChatHistory 				
     				WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ;
                                    
				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
				CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
				SELECT 	
					  count(1)                             																	AS NoOfChats,
					  agentName																								AS agentName
					, sessionStartTime
					, SUM(ResponsedChat)													              					AS AnsweredChat
					, SUM(ResponsedDuration)													              				AS ResponsedDuration
					, SUM(HandledDuration)																					AS HandledDuration    
					, MAX(HandledDuration)  						  							                            AS MaximumHandledDuration 
					, SUM(afterSMSWorkTime)																					AS totalACWTime                    
					, SUM(agentHoldDuration)                                                                				AS agentHoldDuration
					, SUM(FirstCallResolution)																				AS FirstCallResolution
					, SUM(satisfactionRate)																					AS satisfactionRate
				FROM 	temp_ChatHistory
				GROUP BY sessionStartTime, agentName;
                  
				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc_prev; 
				CREATE TEMPORARY TABLE temp_chatHistory_calc_prev AS 	     
				SELECT 	
					  count(1)                             																	AS NoOfChats,
					  agentName																								AS agentName
					, sessionStartTime
					, SUM(ResponsedChat)													              					AS AnsweredChat
					, SUM(ResponsedDuration)													              				AS ResponsedDuration
					, SUM(HandledDuration)																					AS HandledDuration    
					, MAX(HandledDuration)  						  							                            AS MaximumHandledDuration 
					, SUM(afterSMSWorkTime)																					AS totalACWTime                    
					, SUM(agentHoldDuration)                                                                				AS agentHoldDuration
					, SUM(FirstCallResolution)																				AS FirstCallResolution
					, SUM(satisfactionRate)																					AS satisfactionRate
				FROM 	temp_ChatHistory_prev
				GROUP BY sessionStartTime, agentName;																							
			  
     				SELECT SUM(AnsweredChat), SUM(HandledDuration),SUM(satisfactionRate)
     				INTO 	v_CurrentaverageResponseCount, v_CurrentaverageHandledCount,v_CurrentSentimentalScore
     				FROM 	temp_chatHistory_calc ;                                        
                                           
     				SELECT 	SUM(AnsweredChat), SUM(HandledDuration),SUM(satisfactionRate)
     				INTO 	v_PrevAverageResponseCount, v_PrevaverageHandledCount,v_PreSentimentalScore
     				FROM 	temp_chatHistory_calc ;                     

		select  
		sum(NoOfChats),sum(answeredChat),sum(ResponsedDuration), sum(HandledDuration), sum(MaximumHandledDuration), sum(totalACWTime), sum(agentHoldDuration)
		,sum(FirstCallResolution), sum(satisfactionRate)
		INTO
		v_count,v_answerChat, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime 
		, v_firstChatResolution, v_CustomerSatisfaction
		FROM temp_chatHistory_calc;  
              
		select sum(NoOfChats),sum(answeredChat), sum(ResponsedDuration), sum(HandledDuration)
		INTO v_prvcount,v_prevAnswerChat, v_prevAverageResponseTime, v_prevAverageHandledTime
		FROM temp_chatHistory_calc_prev; 
  
		SELECT 	CASE WHEN IFNULL(v_answerChat,0) = 0 THEN 0 ELSE (v_averageResponseTime/v_answerChat) END,CASE WHEN IFNULL(v_count,0) = 0 THEN 0 ELSE (v_averageHandledTime/v_count) END
		INTO v_CurrentTotalCount,v_currentAVGHandleTime;

		SELECT CASE WHEN IFNULL(v_prevAnswerChat,0) = 0 THEN 0 ELSE (v_prevAverageResponseTime/v_prevAnswerChat) END,CASE WHEN IFNULL(v_prvcount,0) = 0 THEN 0 ELSE (v_prevAverageHandledTime/v_prvcount) END
		INTO v_PreviousTotalCount,v_prevAVGHandleTime;
		        
		SET v_PrevAverageResponseCount = CASE WHEN v_PrevAverageResponseCount = 0 then null else v_PrevAverageResponseCount end;
		SET v_PrevaverageHandledCount  = CASE WHEN v_PrevaverageHandledCount = 0 then null else v_PrevaverageHandledCount end;
		SET v_PreSentimentalScore      = CASE WHEN v_PreSentimentalScore = 0 then null else v_PreSentimentalScore end;
	
		SET v_DiffAverageResponsePercent  	= CASE WHEN v_PreviousTotalCount = 0 THEN 0 ELSE (IFNULL(v_CurrentTotalCount, 0) - v_PreviousTotalCount) / v_PreviousTotalCount * 100 END  
		,v_DiffAverageHandledPercent  		= CASE WHEN v_prevAVGHandleTime = 0 THEN 0 ELSE (IFNULL(v_currentAVGHandleTime, 0) - v_prevAVGHandleTime) / v_prevAVGHandleTime * 100 END
		,v_DiffSentimentalScorePercent 		= (v_CurrentSentimentalScore - v_PreSentimentalScore) / v_PreSentimentalScore * 100;        

		SELECT * FROM temp_AllagentId;

		SELECT 	IFNULL(v_averageResponseTime/v_answerChat,0) 				AS 'CurrentaverageResponseCount',
				IFNULL(v_DiffAverageResponsePercent,0) 		        		AS 'DiffAverageResponsePercent',
				IFNULL(v_CurrentaverageHandledCount/v_count,0) 			    AS 'CurrentAverageHandledCount',
				IFNULL(v_DiffAverageHandledPercent,0) 						AS 'DiffAverageHandledPercent',
				IFNULL(v_CurrentSentimentalScore,0) 						AS 'CurrentCustomerSatisfactionCount',
				IFNULL(v_DiffSentimentalScorePercent,0) 					AS 'DiffCustomerSatisfactionPercent';                   


     			select 'All Agents'													 AS agentName,	
     			v_averageResponseTime/v_answerChat                                   AS  averageResponseTime,
     			v_averageHandledTime/v_count                                         AS  averageHandledTime, 
     			v_MaximumHandledTime                                               	 AS  MaximumHandledTime,
     			v_totalACWTime                                                       AS  totalACWTime, 
     			v_averageHoldtime                                                    AS  averageHoldtime,
     			round((v_firstChatResolution /v_answerChat) * 100  )             	AS  firstChatResolution,
     			IFNULL(v_CustomerSatisfaction,0)									AS SentimentalScore
     		UNION ALL
     			SELECT agentName													AS  agentName, 
     			sum(ResponsedDuration/AnsweredChat)                              	AS  averageResponseTime,
     			sum(HandledDuration/NoOfChats)                             			AS averageHandledTime, 
     			sum(MaximumHandledDuration)                                         AS MaximumHandledTime, 
     			sum(totalACWTime)                                                   AS  totalACWTime, 
     			sum(agentHoldDuration)                                              AS  averageHoldtime, 
     			(sum(FirstCallResolution) / sum(AnsweredChat)) *100           		AS firstChatResolution,
     			IFNULL(sum(satisfactionRate),0)										AS SentimentalScore
     			FROM temp_chatHistory_calc 
     			group by agentName;
		
 
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Sms_Agent_performances_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Sms_Agent_performances_trendchart`(
       	p_domainId 			INT,
       	p_datetype 			INT,                 
   		p_startDateTime		DATETIME,
   		p_endDateTime		DATETIME,
       	p_columnName    	VARCHAR(200),      
       	p_agentId 			TEXT
               )
BEGIN
     
      	DECLARE v_startDateTime			DATETIME;
      	DECLARE v_endDateTime			DATETIME;     
      	DECLARE v_datetimeInterval		SMALLINT;    
      	DECLARE v_startDateTimePast		DATETIME;
      	DECLARE v_endDateTimePast		DATETIME;
           
      	DECLARE v_startTimestampPast	BIGINT;
      	DECLARE v_endTimestampPast		BIGINT;      
      	DECLARE v_startTimestamp		BIGINT;
      	DECLARE v_endTimestamp			BIGINT;
      	DECLARE v_curDate				DATETIME DEFAULT NOW();	
         DECLARE v_currentCount			INT;
         DECLARE v_pastCount				INT;
          
      	DROP TEMPORARY TABLE IF EXISTS tmp_result;
      	CREATE TEMPORARY TABLE tmp_result(
      		reportAge			VARCHAR(20)
      		,startDateTime		DATETIME
      		,endDateTime		DATETIME
      		,callCount			INT
      	);    
       
       	IF p_datetype = 1 
           THEN 	
       		SET v_startDateTime = CAST(v_curDate AS DATE); 
       		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
       	END IF;
       	IF p_datetype = 2 
           THEN 
       		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
      		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
       	END IF;
       	IF p_datetype = 3 
           THEN 
       		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
              SET v_endDateTime = CAST(v_curDate AS DATE); 
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
       	END IF;
       	IF p_datetype = 4 
           THEN 
       		SET v_startDateTime = p_startDateTime; 
      		SET v_endDateTime 	= p_endDateTime; 
               
              SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
           
                  IF p_agentId IS NOT NULL 
          THEN
      		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
      		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
          ELSE
      		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
             CREATE TEMPORARY TABLE temp_agentIds
    		 select  UserID from tb_User where domainId = p_domainId ; 
 		END IF;
           
		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
		CREATE TEMPORARY TABLE temp_AllagentId
		SELECT UserID,UserName,ext,domainId FROM tb_User WHERE domainId = p_domainId ; 

           DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
           CREATE TEMPORARY TABLE tmp_Disposition
           SELECT did, dispositionName
           FROM 	disposition_status
           WHERE	domainId		= p_domainId
           AND	dispositionName	= 'Caller Disconnected';    
           
           IF p_datetype IN (1,2)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH RECURSIVE CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	endDateTime < v_endDateTime
       		)
       		SELECT * FROM CTE_TIMINGS;	
       	ELSEIF p_datetype IN (3,4)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH recursive CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	startDateTime < v_endDateTime
       		)
       		SELECT * FROM CTE_TIMINGS;	
           END IF;  
           
           ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
           
           UPDATE tmp_timings
           SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
       		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
               
       	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
      	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
      	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
      	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
    
	DROP TEMPORARY TABLE IF EXISTS tmp_SMStDurationHistory_1;	
	CREATE TEMPORARY TABLE tmp_SMStDurationHistory_1
	SELECT 	SH.sessionStartTime
			, SH.SMSHistoryId
			, SDH.AgentId
			, t_A.UserName																								
			, IFNULL(SDH.Duration,0)									AS Duration											
			, IFNULL(SDH.AgentHoldDuration,0) 							AS AgentHoldDuration
			, IFNULL(SH.afterSMSWorkTime * 1000,0)						AS afterSMSWorkTime	
			, IFNULL(CF.satisfactionRate,0) 							AS satisfactionRate
			FROM 	tb_SMSHistory 					SH
			JOIN 	tb_SMSDurationHistory			SDH	ON SH.SMSHistoryId 		= SDH.SMSHistoryId     
			JOIN 	temp_AllagentId 				t_A ON SDH.AgentId 			= t_A.UserID       
			LEFT JOIN tb_customerFeedback			CF	ON CF.historyId			= SH.SMSHistoryId AND CF.channelTypeId = 2003002
			WHERE 	SH.domainId 		= p_domainId	
			AND 	 SDH.IsBot			= 0      
			AND 	SH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;          
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                   
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
		DROP TEMPORARY TABLE IF EXISTS tmp_SMStDurationHistory;	
		CREATE TEMPORARY TABLE tmp_SMStDurationHistory
		SELECT
				sessionStartTime	
				, SMSHistoryId
				, UserName																AS agentName
				, CASE WHEN Duration > 0 THEN 1 ELSE 0 END      						AS ResponsedChat
				, CASE WHEN Duration > 0 THEN Duration ELSE 0 END 						AS ResponsedDuration
				, CASE WHEN AgentHoldDuration > 0 THEN AgentHoldDuration ELSE 0 END		AS agentHoldDuration
				, (Duration + afterSMSWorkTime)											AS HandledDuration                                 
				, afterSMSWorkTime
				, satisfactionRate
		FROM tmp_SMStDurationHistory_1; 
         
		DROP TEMPORARY TABLE IF EXISTS tmp_SMStDurationHistory_cal; 
		CREATE TEMPORARY TABLE tmp_SMStDurationHistory_cal AS 	     
		SELECT 	
			  count(1)                             																	AS NoOfChats,
			  agentName																								AS agentName
            , SMSHistoryId  
			, sessionStartTime
			, SUM(ResponsedChat)													              					AS AnsweredChat
			, SUM(ResponsedDuration)													              				AS ResponsedDuration
			, SUM(HandledDuration)																					AS HandledDuration    
			, MAX(HandledDuration)  						  							                            AS MaximumHandledDuration 
			, SUM(afterSMSWorkTime)																					AS totalACWTime                    
			, SUM(agentHoldDuration)                                                                				AS agentHoldDuration
			, SUM(satisfactionRate)																					AS satisfactionRate
		FROM 	tmp_SMStDurationHistory
		GROUP BY sessionStartTime, agentName, SMSHistoryId;
		 
        DROP TEMPORARY TABLE IF EXISTS tmp_SMStDurationHistory_cal_final; 
		CREATE TEMPORARY TABLE tmp_SMStDurationHistory_cal_final AS 	     
		SELECT  
			  agentName AS agentName,
			  SMSHistoryId,
			  sessionStartTime,
			  SUM(CASE WHEN AnsweredChat = 0 OR AnsweredChat IS NULL THEN 0 ELSE (ResponsedDuration / AnsweredChat) END) AS averageResponseTime,
			  SUM(CASE WHEN NoOfChats = 0 OR NoOfChats IS NULL THEN 0 ELSE (HandledDuration / NoOfChats) END) AS averageHandlingTime,
			  SUM(totalACWTime) AS totalACWTime
		FROM tmp_SMStDurationHistory_cal
		GROUP BY sessionStartTime, agentName, SMSHistoryId;

		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                 
		DROP TEMPORARY TABLE IF EXISTS tmp_SMSHistory;	
		CREATE TEMPORARY TABLE tmp_SMSHistory
		SELECT 	DISTINCT 
			 CDH.SMSHistoryId 
		, 	 CDH.sessionStartTime
		FROM 	tmp_SMStDurationHistory_cal_final CDH;         

       
		ALTER TABLE tmp_SMSHistory  ADD averageResponseTime 	bigint default 0;
		ALTER TABLE tmp_SMSHistory  ADD averageHandlingTime 	bigint default 0;
		ALTER TABLE tmp_SMSHistory  ADD totalACWTime			bigint default 0;

 		CREATE INDEX ix_tmp_SMSHistory        ON tmp_SMSHistory (SMSHistoryId);
        CREATE INDEX ix_tmp_SMSDurationHistory ON tmp_SMStDurationHistory (SMSHistoryId);  

		UPDATE tmp_SMSHistory			CH
		JOIN 	tmp_SMStDurationHistory_cal_final	CDH	ON CH.SMSHistoryId	= CDH.SMSHistoryId  
		SET 	CH.averageResponseTime	= CDH.averageResponseTime,
		CH.averageHandlingTime	= CDH.averageHandlingTime ,
		CH.totalACWTime	        = CDH.totalACWTime;
              
    
            
         IF p_columnName = 'Total ACW Time'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.totalACWTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.totalACWTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
         
       ELSEIF p_columnName = 'Avg. Response Time'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageResponseTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageResponseTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
         
         
         ELSEIF p_columnName = 'Avg. Handle Time (AHT)'
   	THEN
   		INSERT INTO tmp_result
    		SELECT 	'Current'					AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageHandlingTime),0)	AS callCount
    		FROM 	tmp_timings			t_T	
    		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
           
           INSERT INTO tmp_result
    		SELECT 	'Past'						AS reportAge
    			,	t_T.startDateTime 
    			,	t_T.endDateTime
    			,	IFNULL(SUM(CH.averageHandlingTime),0)	AS callCount     
    		FROM 	tmp_timings		t_T	
    		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
    		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
    		GROUP BY t_T.startDateTime, t_T.endDateTime;
         END IF;       
   
 		SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Current';    
       
       SELECT  *
       FROM 	tmp_result
       WHERE 	reportAge = 'Past';
        
   	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
   	INTO 	v_currentCount, v_pastCount		
   	FROM 	tmp_result;
       
       
       end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_sms_agent_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_sms_agent_report`(
   	p_startTmpstmp 		bigint,
   	p_endTmpstmp 		bigint,
   	p_timeZone 			varchar(200),
   	p_domainId 			int,        
   	p_queueIds	 		VARCHAR(250),
   	p_agentIds 			VARCHAR(250),
   	p_offset 			INT,
   	p_Limit 			INT     	
   )
BEGIN 
            	DECLARE v_offset 		INT;  	
            	DECLARE v_startTmpstmp 	BIGINT;
            	DECLARE v_endTmpstmp 	BIGINT;
            	
       		SET v_offset = p_offset * p_Limit;
              
            	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
            	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
           
            	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId BIGINT);
            
            	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
               
               DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   			CREATE TEMPORARY TABLE temp_AllagentId
   			select UserID,UserName from tb_User where domainId = p_domainId;
              
          	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
             SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          	CREATE TEMPORARY TABLE temp_AvailableDisposition 
              (   DispositionId 			INT
                  ,DispositionStatus 		VARCHAR(100)
          		,DispositionCategory	TINYINT
               ); 
          	INSERT INTO temp_AvailableDisposition 
          	SELECT 	did 			DispositionId
          		,	dispositionName	DispositionStatus
         		,	CASE	
   						WHEN dispositionName = 'Transferred' THEN 1
                           WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
                           WHEN dispositionName = 'Discarded' THEN 4
                           ELSE 2
          			END 			DispositionCategory
          	FROM 	disposition_status
          	WHERE 	domainId	= p_domainId;
          	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              
          	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
          	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          	CREATE TEMPORARY TABLE temp_SMSHistory AS 	
   		SELECT 	
   				UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE)) 					AS SessionDate
   			 ,	U.UserName																				AS agentName   
   			 ,	U.UserID																				AS agentId
   			 ,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 									AS Opened
   			 ,	CASE WHEN DispositionCategory = 1 THEN 1 ELSE 0 END 									AS Transferred  
   			 ,	CASE WHEN DispositionCategory = 3 THEN 1 ELSE 0 END 									AS Handled
   			 ,	CASE WHEN DispositionCategory = 4 THEN 1 ELSE 0 END 									AS Discarded
   			 
             ,  SDH.Duration																			AS SMSHandlingTime             
              ,  SH.afterSMSWorkTime*1000																AS afterSMSWorkTime
   		FROM 	tb_SMSHistory 					SH
   		JOIN 	tb_SMSDurationHistory			SDH	ON SH.SMSHistoryId 	= SDH.SMSHistoryId
   		LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
   		JOIN tb_User							U	ON U.UserID			= SDH.AgentId
   		LEFT JOIN temp_agentId 					t_A ON U.UserID 		= t_A.agentId       
   		WHERE 	SH.domainId 		= p_domainId 		
   		AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
   		AND		SH.IsInBound		= 1	
   		AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
   		DROP TEMPORARY TABLE IF EXISTS temp_agentId;
   		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
               
   		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
            
          	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1;        	
          	CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	     
          	SELECT 	t_SH.SessionDate 															AS sessionDate
   			,	t_SH.agentId										
         		,	t_SH.agentName										
         		,	COUNT(1)																	AS totalReceived        
         		,	SUM(t_SH.Opened)															AS totalOpened
         		,	SUM(t_SH.Handled)															AS totalHandled
         		,	SUM(t_SH.Transferred)														AS totalTransferred
         		,	SUM(t_SH.Discarded)															AS totalDiscarded
       		
         		,	round(SUM(t_SH.SMSHandlingTime+t_SH.afterSMSWorkTime))						AS totalSmsHandlingTime
         		,	round((SUM(t_SH.SMSHandlingTime+t_SH.afterSMSWorkTime)/COUNT(1)))   		AS averageSMSHandlingTime
   	   FROM 	temp_SMSHistory t_SH
   	   GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.agentId;   
          
          	SELECT * from temp_AllagentId;
   	
   	   
   	   SELECT COUNT(1) totalCount
   	   FROM temp_SMSHistory_1;
   	   
   	   SELECT 	*
   	   FROM 	temp_SMSHistory_1
   	   ORDER BY v_offset, p_Limit;  
   	   DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
   	   DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_sms_agent_report1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_sms_agent_report1`(
	p_startTmpstmp 		bigint,
	p_endTmpstmp 		bigint,
	p_timeZone 			varchar(200),
	p_domainId 			int,        
	p_queueIds	 		VARCHAR(250),
	p_agentIds 			VARCHAR(250),
	p_offset 			INT,
	p_Limit 			INT     	
)
BEGIN 
         	DECLARE v_offset 		INT;  	
         	DECLARE v_startTmpstmp 	BIGINT;
         	DECLARE v_endTmpstmp 	BIGINT;
         	
    		SET v_offset = p_offset * p_Limit;
           
         	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
         	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
        
         	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId BIGINT);
         
         	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
            
            DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
			CREATE TEMPORARY TABLE temp_AllagentId
			select UserID,UserName from tb_User where domainId = p_domainId;
           
       	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	CREATE TEMPORARY TABLE temp_AvailableDisposition 
           (   DispositionId 			INT
               ,DispositionStatus 		VARCHAR(100)
       		,DispositionCategory	TINYINT
            ); 
       	INSERT INTO temp_AvailableDisposition 
       	SELECT 	did 			DispositionId
       		,	dispositionName	DispositionStatus
      		,	CASE	
						WHEN dispositionName = 'Transferred' THEN 1
                        WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
                        WHEN dispositionName = 'Discarded' THEN 4
                        ELSE 2
       			END 			DispositionCategory
       	FROM 	disposition_status
       	WHERE 	domainId	= p_domainId;
       	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
           
       	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	CREATE TEMPORARY TABLE temp_SMSHistory AS 	
		SELECT 	
				UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE)) as SessionDate
			 ,	U.UserName				as agentName   
			 ,	U.UserID				as agentId
			 ,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END as Opened
			 ,	CASE WHEN DispositionCategory = 1 THEN 1 ELSE 0 END as Transferred  
			 ,	CASE WHEN DispositionCategory = 3 THEN 1 ELSE 0 END as Handled
			 ,	CASE WHEN DispositionCategory = 4 THEN 1 ELSE 0 END as Discarded
			 ,	SH.sessionEndTime - SH.sessionStartTime	 'SMSHandlingTime'          
		FROM 	tb_SMSHistory 					SH
		JOIN 	tb_SMSDurationHistory			SDH	ON SH.SMSHistoryId 	= SDH.SMSHistoryId
		LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
		JOIN tb_User							U	ON U.UserID			= SDH.AgentId
		LEFT JOIN temp_agentId 					t_A ON U.UserID 		= t_A.agentId       
		WHERE 	SH.domainId 		= p_domainId 		
		AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
		AND		SH.IsInBound		= 1	
		AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
		DROP TEMPORARY TABLE IF EXISTS temp_agentId;
		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
            
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
         
       	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1;        	
       	CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	     
       	SELECT 	t_SH.SessionDate 					as sessionDate
			,	t_SH.agentId
      		,	t_SH.agentName
      		,	COUNT(1)							AS totalReceived        
      		,	SUM(t_SH.Opened)					AS totalOpened
      		,	SUM(t_SH.Handled)					AS totalHandled
      		,	SUM(t_SH.Transferred)				AS totalTransferred
      		,	SUM(t_SH.Discarded)					AS totalDiscarded
      		,	round(SUM(t_SH.SMSHandlingTime)/1000)		AS totalSmsHandlingTime
      		,	SUM(t_SH.SMSHandlingTime)/COUNT(1)	AS averageSMSHandlingTime
	   FROM 	temp_SMSHistory t_SH
	   GROUP BY t_SH.SessionDate, t_SH.agentName, t_SH.agentId;   
       
       	SELECT * from temp_AllagentId;
	
	   
	   SELECT COUNT(1) totalCount
	   FROM temp_SMSHistory_1;
	   
	   SELECT 	*
	   FROM 	temp_SMSHistory_1
	   ORDER BY v_offset, p_Limit;  
	   DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
	   DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Sms_Agent_Servicelevel_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Sms_Agent_Servicelevel_trendchart`(
      	p_domainId 			INT,
      	p_datetype 			INT,                 
  		p_startDateTime		DATETIME,
  		p_endDateTime		DATETIME,
      	p_columnName    	VARCHAR(200),         
      	p_agentId 			TEXT
              )
BEGIN
    
     	DECLARE v_startDateTime			DATETIME;
     	DECLARE v_endDateTime			DATETIME;     
     	DECLARE v_datetimeInterval		SMALLINT;    
     	DECLARE v_startDateTimePast		DATETIME;
     	DECLARE v_endDateTimePast		DATETIME;
          
     	DECLARE v_startTimestampPast	BIGINT;
     	DECLARE v_endTimestampPast		BIGINT;      
     	DECLARE v_startTimestamp		BIGINT;
     	DECLARE v_endTimestamp			BIGINT;
     	DECLARE v_curDate				DATETIME DEFAULT NOW();	
        DECLARE v_currentCount			INT;
        DECLARE v_pastCount				INT;
         
     	DROP TEMPORARY TABLE IF EXISTS tmp_result;
     	CREATE TEMPORARY TABLE tmp_result(
     		reportAge			VARCHAR(20)
     		,startDateTime		DATETIME
     		,endDateTime		DATETIME
     		,callCount			INT
     	);    
      
      	IF p_datetype = 1 
          THEN 	
      		SET v_startDateTime = CAST(v_curDate AS DATE); 
      		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
      
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
      	END IF;
      	IF p_datetype = 2 
          THEN 
      		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
      
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
      	END IF;
      	IF p_datetype = 3 
          THEN 
      		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
             SET v_endDateTime = CAST(v_curDate AS DATE); 
              
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
      		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
      	END IF;
      	IF p_datetype = 4 
          THEN 
      		SET v_startDateTime = p_startDateTime; 
     		SET v_endDateTime 	= p_endDateTime; 
              
             SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
              
      		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
      		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
      	END IF;
          
                 IF p_agentId IS NOT NULL 
         THEN
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
     		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
         ELSE
     		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
            CREATE TEMPORARY TABLE temp_agentIds
   		 select  UserID from tb_User where domainId = p_domainId ; 
		END IF;
          
          DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
          CREATE TEMPORARY TABLE tmp_Disposition
          SELECT did, dispositionName
          FROM 	disposition_status
          WHERE	domainId		= p_domainId
          AND	dispositionName	= 'Caller Disconnected';    
          
          IF p_datetype IN (1,2)
          THEN 
      		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
              CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
      		WITH RECURSIVE CTE_TIMINGS AS (
      			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
      			UNION ALL
      			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
      			FROM 	CTE_TIMINGS
      			WHERE 	endDateTime < v_endDateTime
      		)
      		SELECT * FROM CTE_TIMINGS;	
      	ELSEIF p_datetype IN (3,4)
          THEN 
      		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
              CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
      		WITH recursive CTE_TIMINGS AS (
      			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
      			UNION ALL
      			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
      			FROM 	CTE_TIMINGS
      			WHERE 	startDateTime < v_endDateTime
      		)
      		SELECT * FROM CTE_TIMINGS;	
          END IF;  
          
          ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
          
          UPDATE tmp_timings
          SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
      		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
              
      	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
     	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
     	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
     	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
      
        
         DROP TEMPORARY TABLE IF EXISTS tmp_SMSDurationHistory;	
   	CREATE TEMPORARY TABLE tmp_SMSDurationHistory
   	SELECT 	CH.SMSHistoryId
   		,	CH.sessionStartTime
   		,	CH.dispositionId        
		,   CDH.Duration
        ,	CASE WHEN t_D.dispositionName = 'Caller Disconnected' THEN 1 ELSE 0  END AS IsAbandoned
	FROM 	tb_SMSHistory 			CH
	JOIN 	tb_SMSDurationHistory	CDH	    ON CH.SMSHistoryId 		= CDH.SMSHistoryId
    LEFT JOIN disposition_status	t_D		ON CH.dispositionId	= t_D.did
	
	WHERE 	CH.domainId 		= p_domainId
	and     CDH.AgentId > 0
	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp;
 
    
    
    DROP TEMPORARY TABLE IF EXISTS tmp_SMSHistory;	
    	CREATE TEMPORARY TABLE tmp_SMSHistory
       SELECT 	DISTINCT 
    			CDH.SMSHistoryId 
    		, 	CDH.sessionStartTime
    	FROM 	tmp_SMSDurationHistory CDH;  
    
    
        ALTER TABLE tmp_SMSHistory ADD IsMissed 		INT default 0;
        ALTER TABLE tmp_SMSHistory ADD IsAnswered 		INT default 0;
        ALTER TABLE tmp_SMSHistory ADD IsUnAnswered 	INT default 0;
        ALTER TABLE tmp_SMSHistory ADD IsAbandoned		INT default 0;
        ALTER TABLE tmp_SMSHistory ADD TotalSLA			INT default 0;
      
      
		CREATE INDEX ix_tmp_SMSHistory ON tmp_SMSHistory (SMSHistoryId);
        CREATE INDEX ix_tmp_SMSDurationHistory ON tmp_SMSDurationHistory (SMSHistoryId);
          
        		  UPDATE tmp_SMSHistory			CH
          JOIN 	tmp_SMSDurationHistory	CDH	ON CH.SMSHistoryId	= CDH.SMSHistoryId  
          LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
          SET 	CH.IsMissed		= CASE WHEN CDH.Duration > 3000 				THEN 1 ELSE 0  END
      		,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 					THEN 1 ELSE 0  END
            ,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 					THEN 1 ELSE 0  END
            ,   CH.TotalSLA     = CASE WHEN CDH.Duration BETWEEN 0 AND 3000 	THEN 1 ELSE 0  END 
    		,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned = 1 				THEN 1 ELSE 0  END;     
        
        
        
      IF p_columnName = 'Total SLA'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'			AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.SMSHistoryId),0)	AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
             
             INSERT INTO tmp_result
      		SELECT 	'Past'					    AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.SMSHistoryId),0)	AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;        
        
        ELSEIF p_columnName = 'Answered SLA'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'			AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsAnswered),0)	AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
             
             INSERT INTO tmp_result
      		SELECT 	'Past'					    AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsAnswered),0)	AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;         
        
		ELSEIF p_columnName = 'Abandoned SLA'
     	THEN
     		INSERT INTO tmp_result
      		SELECT 	'Current'			AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsAbandoned),0)	AS callCount
      		FROM 	tmp_timings			t_T	
      		LEFT JOIN tmp_SMSHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
      		GROUP BY t_T.startDateTime, t_T.endDateTime;
             
             INSERT INTO tmp_result
      		SELECT 	'Past'					    AS reportAge
      			,	t_T.startDateTime 
      			,	t_T.endDateTime
      			,	IFNULL(SUM(CH.IsAbandoned),0)	AS callCount     
      		FROM 	tmp_timings		t_T	
      		LEFT JOIN 	tmp_SMSHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
      		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
      		GROUP BY t_T.startDateTime, t_T.endDateTime;      
        
           END IF;
      
        SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Current';    
         
         SELECT  *
         FROM 	tmp_result
         WHERE 	reportAge = 'Past';
          
     	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
     	INTO 	v_currentCount, v_pastCount		
     	FROM 	tmp_result;
         
         SELECT 	p_columnName    													AS metric
   		      ,		ifnull(v_currentCount,0)											AS currentTotal
     		  , 	ifnull(v_pastCount,0)												AS pastTotal
   		      ,	    ifnull((v_currentCount - v_pastCount),0)  							AS totalDifference
              ,		ifnull((v_currentCount - v_pastCount) /(v_pastCount) *100 ,0)		AS  Percentage;
         
    
      
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_sms_interaction_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_sms_interaction_report`(
      p_startTmpstmp 		BIGINT,
      p_endTmpstmp 		    BIGINT,
      p_timeZone 			VARCHAR(200),
      p_domainId 			INT,        
      p_queueIds	 		VARCHAR(250),
      p_agentIds 			VARCHAR(250),
      p_direction			TINYINT,
      p_dispositionIds	    VARCHAR(250),
      p_offset 				INT,
      p_Limit 				INT     	
      )
BEGIN 
 		DECLARE v_offset 		INT;  	
 		DECLARE v_startTmpstmp 	BIGINT;
 		DECLARE v_endTmpstmp 	BIGINT;    
         	
       	SET v_offset = p_offset * p_Limit;
           
 		IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
 		IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
        
 		DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId 		VARCHAR(100));
 		DROP TEMPORARY TABLE IF EXISTS temp_direction;	CREATE TEMPORARY TABLE temp_direction(directionId 	TINYINT);
 		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
         
 		CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;	
         CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
          
  		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  		CREATE TEMPORARY TABLE temp_AllagentId
  		select UserID,UserName from tb_User where domainId = p_domainId ; 
          
          IF p_direction IS NULL
          THEN
      		INSERT INTO temp_direction 
              (directionId)
              VALUES (0),(1);
      	ELSE
      		INSERT INTO temp_direction
              (directionId)
              SELECT p_direction;
          END IF;
          
          DROP TEMPORARY TABLE IF EXISTS temp_AlldirectionId;
          CREATE TEMPORARY TABLE temp_AlldirectionId
          select directionId,  CASE WHEN directionId = 0 THEN 'OutBound' 
  								WHEN directionId = 1 THEN 'InBound' END AS directionName 
                                  FROM temp_direction ;
           
           DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
           CREATE TEMPORARY TABLE temp_AvailableDisposition 
           (	dispositionId 		INT,
              DispositionStatus 	VARCHAR(100)
           );
           
       	INSERT INTO temp_AvailableDisposition 
       	SELECT 	did 			dispositionId
       		,	dispositionName	DispositionStatus
       	FROM 	disposition_status
       	WHERE 	domainId	= p_domainId;
       	
  
  
  
  
  
           
       	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	CREATE TEMPORARY TABLE temp_SMSHistory AS 	    	
      	
  			  SELECT 	
                 
                    FROM_UNIXTIME(SH.sessionStartTime/1000) as `timeFormat` 
                 ,	SH.customerNumber		           
                 ,	U.UserName				as agentName
				 ,	SH.IsInBound            as isInBound
                 ,	SH.sessionEndTime - SH.sessionStartTime	as totalDuration
                 ,	SH.dispositionId
                  ,	SH.afterSMSWorkTime		as ACWtime
                  ,	SH.dispositionSubject
                  ,	SH.Summary
       	    FROM 	tb_SMSHistory 				SH
        	JOIN 	tb_SMSDurationHistory		SDH		ON SH.SMSHistoryId 		= SDH.SMSHistoryId
            JOIN 	temp_direction				t_DIR	ON t_DIR.directionId	= SH.IsInBound
         	LEFT JOIN temp_AllagentId			U		ON U.UserID				= SDH.AgentId
         	LEFT JOIN temp_agentId	 			t_A 	ON U.UserID  			= t_A.agentId       
            LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
        	WHERE 	SH.domainId 			= p_domainId 		
        	AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
         	AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
            AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
        	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
          
  		SELECT * from temp_AllagentId;
  		SELECT * from temp_AvailableDisposition;
		SELECT * from temp_AlldirectionId;
          
      	
      	SELECT 	COUNT(1)  totalCount
      	FROM 	temp_SMSHistory;       
          
          
        IF((p_Limit IS NOT NULL )AND (p_offset IS NOT NULL)) THEN  
        
				DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 	
				CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	    
				SELECT 	*
				FROM 	temp_SMSHistory
				ORDER BY `timeFormat` DESC 
				LIMIT v_offset, p_Limit;
                
        ELSE 
				DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 	
				CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	    
				SELECT 	*
				FROM 	temp_SMSHistory
				ORDER BY `timeFormat` DESC 
				;
        END IF;
         
 		DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
 		CREATE TEMPORARY TABLE temp_customer_contact
 		SELECT 	coid,primaryPhoneNumber,phoneNumber,firstName,lastName      
 		FROM 	customer_contact 
 		WHERE 	domainId = p_domainId;        
          
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_2;
 		CREATE TEMPORARY TABLE temp_SMSHistory_2         
           SELECT SH.`timeFormat` as `dateTime`
      		
      		,	SH.customerNumber		
      		,	SH.agentName
 			,	CASE 	WHEN SH.IsInBound = 1 THEN 'InBound'
      					WHEN SH.IsInBound = 0 THEN 'OutBound'
      			END		as direction
      		,	round(SH.totalDuration/1000  )  as totalDuration    
			,	SH.ACWtime
      		,	t_A.DispositionStatus		disposition
            ,	SH.dispositionSubject	as subject
            ,	SH.Summary	as summary
           FROM 	temp_SMSHistory_1				SH
           LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId;
          
                                                     
 		ALTER TABLE temp_SMSHistory_2 ADD COLUMN customerName VARCHAR(150);      
                                                     
 		 UPDATE 	temp_SMSHistory_2		EH
         JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryPhoneNumber	LIKE  EH.customerNumber									
         SET 	EH.customerName	= CONCAT(c_c.firstName, ' ',c_c.lastName);
         
         UPDATE 	temp_SMSHistory_2		EH        
         SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT('%',EH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)
         WHERE 	IFNULL(EH.customerName,'') = '';        
         
         UPDATE 	temp_SMSHistory_2		EH        
         SET 	customerName	= 'New Customer'
         WHERE 	IFNULL(customerName,'') = '';         
         
         SELECT  dateTime,customerNumber,customerName,agentName,direction,totalDuration,disposition,ACWtime,subject,summary
         FROM temp_SMSHistory_2;
         
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_sms_profile_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_sms_profile_report`(
        	p_startTmpstmp 		BIGINT,
        	p_endTmpstmp 		BIGINT,
        	p_timeZone 			VARCHAR(200),
        	p_domainId 			INT,        
        	p_queueIDs	 		VARCHAR(250),
        	p_agentIDs 			VARCHAR(250),
        	p_dispositionIds	VARCHAR(250),
        	p_offset 			INT,
        	p_Limit 			INT     	
        )
BEGIN 
      	DECLARE v_offset 		INT;  	
      	DECLARE v_startTmpstmp 	BIGINT;
      	DECLARE v_endTmpstmp 	BIGINT;
      
      	SET v_offset = p_offset * p_Limit;
      
      	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
      	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
      
      	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;		CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
      	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
              
      	CALL split(p_agentIDs,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
      	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
                
 		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
 		CREATE TEMPORARY TABLE temp_AvailableDisposition 
 		(	dispositionId 		INT,
 			DispositionStatus 	VARCHAR(100)
 		);
   	 
 		INSERT INTO temp_AvailableDisposition 
 		SELECT 	did 			dispositionId
 			,	dispositionName	DispositionStatus
 		FROM 	disposition_status
 		WHERE 	domainId	= p_domainId;
   	
   
       
   	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   	CREATE TEMPORARY TABLE temp_AllagentId
   	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId ;
                
            	DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory; 
            	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            	CREATE TEMPORARY TABLE temp_SMSHistory AS 		
                SELECT 	
    					SH.sessionStartTime 	    AS `dateTime`			
           			,	SH.customerNumber		
  					,	SDH.AgentId 			AS agentId
           			,	U.UserName				AS agentName
  					,	SH.createdAt			AS receivedOn
           			,	SH.assignedOn          
           			,	SH.repliedDate			AS repliedOn
           			,	CASE WHEN SH.Istransferred = 1 THEN SH.transferredDate	ELSE null END	AS transferredOn 
           			,	SH.discardedDate		AS discardedOn
           			, 	SH.dispositionId					
            	FROM 	tb_SMSHistory 				SH
             	JOIN 	tb_SMSDurationHistory		SDH		ON SH.SMSHistoryId 		= SDH.SMSHistoryId
  			    LEFT JOIN temp_AllagentId			U		ON U.UserID				= SDH.AgentId   
             	LEFT JOIN temp_agentIDs 			t_A 	ON U.UserID  			= t_A.agentId       
  			    LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
             	WHERE 	SH.domainId 			= p_domainId 	
               AND		SDH.IsBot=0
             	 AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp    
             	 AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
               AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
             	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
               
   			SELECT * from temp_AllagentId;
   			SELECT * from temp_AvailableDisposition;
               
           	SELECT 	COUNT(1)  totalCount
           	FROM 	temp_SMSHistory;    	
           
           IF((p_Limit IS NOT NULL) AND (p_offset IS NOT NULL)) THEN
            	
                DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 	
            	CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	    
           	SELECT 	*
           	FROM 	temp_SMSHistory
              	ORDER BY `dateTime` DESC 
           	LIMIT v_offset, p_Limit;
            
            ELSE
            
				DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_1; 	
            	CREATE TEMPORARY TABLE temp_SMSHistory_1 AS 	    
           	SELECT 	*
           	FROM 	temp_SMSHistory
              	ORDER BY `dateTime` DESC;
            
            END IF;
             
             
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;   
 			DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
 			CREATE TEMPORARY TABLE temp_customer_contact
 			SELECT 	coid,primaryPhoneNumber,phoneNumber,firstName,lastName      
 			FROM 	customer_contact 
 			WHERE 	domainId = p_domainId;       
 			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;            
                
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
 			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_2;	
 			CREATE TEMPORARY TABLE temp_SMSHistory_2           
 		   SELECT 	SH.`dateTime`
 			
 				,	SH.customerNumber		
 				,	SH.agentId
 				,	SH.agentName
 				,	SH.receivedOn
 				,	SH.repliedOn
 				,	SH.assignedOn
 				,	SH.transferredOn
 				,	SH.discardedOn
 				,	t_A.DispositionStatus	disposition
 				,	SH.dispositionId
 		   FROM 	temp_SMSHistory_1			SH
 		   LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId;
 
 
 			
 			ALTER TABLE temp_SMSHistory_2 ADD COLUMN customerName VARCHAR(150);        			
 			
 			UPDATE 	temp_SMSHistory_2		SH
 			JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryPhoneNumber	LIKE SH.customerNumber											
 			SET 	customerName	= CONCAT(c_c.firstName, ' ',c_c.lastName);
 
 			UPDATE 	temp_SMSHistory_2		SH        
 			SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM temp_customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT('%',SH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)				
 			WHERE 	IFNULL(SH.customerName,'') = '';        
 			
 			UPDATE 	temp_SMSHistory_2		SH        
 			SET 	customerName	= 'New Customer'
 			WHERE 	IFNULL(SH.customerName,'') = '';  
             
             SELECT * FROM temp_SMSHistory_2;
             
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_socialmedia_agent_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_socialmedia_agent_report`(	
	p_startTmpstmp 		bigint,
  	p_endTmpstmp 		bigint,
  	p_timeZone 			varchar(200),
  	p_domainId 			int,        
  	p_queueIds	 		VARCHAR(250),
  	p_agentIds 			VARCHAR(250),
  	p_offset 			INT,
  	p_Limit 			INT
 	)
BEGIN 
  	DECLARE v_offset 		INT;  	
  	DECLARE v_startTmpstmp 	BIGINT;
  	DECLARE v_endTmpstmp 	BIGINT;
  	
  	SET v_offset = p_offset * p_Limit;
    
  	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
  	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
  
	DROP TEMPORARY TABLE IF EXISTS temp_agentId;		CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
  
	CALL split(p_agentIds,',');			INSERT INTO temp_agentId(agentId) 				SELECT Items FROM tt_Split_temptable;
	
	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
	CREATE TEMPORARY TABLE temp_AllagentId
	select UserID,UserName from tb_User where domainId = p_domainId;    
        
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
	CREATE TEMPORARY TABLE temp_AvailableDisposition 
  	(   DispositionId 			INT
  		,DispositionStatus 		VARCHAR(100)
  		,DispositionCategory	TINYINT
  	); 
	INSERT INTO temp_AvailableDisposition 
	SELECT 	did 			DispositionId
		,	dispositionName	DispositionStatus
		,	CASE WHEN dispositionName = 'Transferred' THEN 1
				 WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected') THEN 3
				 WHEN dispositionName = 'Discarded' THEN 4
                 ELSE 2
			END 			DispositionCategory
	FROM 	disposition_status
	WHERE 	domainId	= p_domainId;
    	
	DROP TEMPORARY TABLE IF EXISTS temp_socialmediaHistory; 
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	CREATE TEMPORARY TABLE temp_socialmediaHistory AS 	
  	SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE)) as SessionDate	
		  ,	U.UserName														as agentName
			,	CASE WHEN t_D.DispositionId IS NULL THEN 1 ELSE 0 END 		as UnansweredChat
			,	CASE WHEN DispositionCategory = 1 THEN 1 ELSE 0 END 		as Transferred  
			,	CASE WHEN DispositionCategory = 3 THEN 1 ELSE 0 END 		as Handled
			,	CASE WHEN DispositionCategory = 4 THEN 1 ELSE 0 END 		as Discarded
			,	Duration 	 												        
			,	afterwhatsappWorkTime										
			,	dialDuration												as responseTime
	FROM 	tb_WhatsappHistory 				SH
	JOIN 	tb_WhatsappDurationHistory		SDH	ON SH.WhatsappHistoryId = SDH.WhatsappHistoryId
	LEFT JOIN temp_AvailableDisposition		t_D	ON SH.dispositionId		= t_D.DispositionId
	LEFT JOIN tb_User						U	ON U.UserID				= SDH.AgentId
	LEFT JOIN temp_agentId 					t_A ON U.UserID 			= t_A.agentId       
	WHERE 	SH.domainId 		= p_domainId 		
	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
 	AND		SH.IsInBound		= 1	
	AND 	(IFNULL(p_agentIds,'') = '' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
    
	DROP TEMPORARY TABLE IF EXISTS temp_socialmediaHistory_1;
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	CREATE TEMPORARY TABLE temp_socialmediaHistory_1 AS
	SELECT
		t_SH.SessionDate*1000 as sessionDate,
		t_SH.agentName,
		COUNT(1) as chatReceived,
		SUM(t_SH.Handled) as chatHandled,
		
		round((SUM((Duration/1000) + afterwhatsappWorkTime) / COUNT(1)) * 100) as averageActiveChatTime,
		SUM(t_SH.UnansweredChat) as unansweredchat,
		round((SUM(t_SH.responseTime) / COUNT(1)) * 100) as averageResponseTime
	FROM		temp_socialmediaHistory t_SH
	GROUP BY	t_SH.SessionDate, t_SH.agentName
	ORDER BY 	t_SH.SessionDate DESC;

    
	SELECT * from temp_AllagentId;
    SELECT * from temp_AvailableDisposition;
    
    SELECT COUNT(1) totalCount
    FROM temp_socialmediaHistory_1;
    
    IF((p_Limit IS NOT NULL )AND (p_offset IS NOT NULL)) THEN 
	
		SELECT 	*
			FROM 	temp_socialmediaHistory_1
			LIMIT 	v_offset, p_Limit;
            
    ELSE
		
        SELECT 	*
			FROM 	temp_socialmediaHistory_1;
    
    END IF;
    
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_socialmedia_profile_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_socialmedia_profile_report`(	
       p_startTmpstmp 	BIGINT,
       p_endTmpstmp 	    BIGINT,
       p_timeZone 		VARCHAR(200),
       p_domainId 		INT,
       p_queueIDs 		VARCHAR(250),
       p_agentIDs 		VARCHAR(250),
       p_dispositionIds	VARCHAR(250),
       p_Offset			INT,
       p_Limit			INT  
       )
BEGIN
     	DECLARE v_startTmpstmp 	BIGINT;
     	DECLARE v_endTmpstmp 	BIGINT;
     	DECLARE v_Total_count 	INT;
     	DECLARE v_offset		INT;    
              
     	SET v_offset =  p_Limit * p_Offset; 
     
     	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
     	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
         
     	
     	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     	DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
             
     	
     	CALL split(p_agentIDs,',');			INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;
     	CALL split(p_dispositionIds,',');	INSERT INTO temp_dispositionIds(dispositionId) SELECT Items FROM tt_Split_temptable;
         
     	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
     	CREATE TEMPORARY TABLE temp_AllagentId
     	SELECT UserID,UserName FROM tb_User WHERE domainId = p_domainId ;
               
     	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     	CREATE TEMPORARY TABLE temp_AvailableDisposition 
     	(	dispositionId 		INT,
     		DispositionStatus 	VARCHAR(100)
     	);
               
     	INSERT INTO temp_AvailableDisposition 
     	SELECT 	did 			dispositionId
     		,	dispositionName	DispositionStatus
     	FROM 	disposition_status
     	WHERE 	domainId	= p_domainId;
     	
           
         
     	DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory; 
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         CREATE TEMPORARY TABLE temp_WhatsappHistory AS 	    	
     	SELECT 		FROM_UNIXTIME(SH.sessionStartTime/1000) as `dateTime`			
     			,	SH.customerNumber		
     			,	U.UserName				as agentName
     		
     			,	SH.createdAt			as receivedOn
     			,	SH.assignedOn          
     			,	SH.repliedDate			as repliedOn
     			,	SH.transferredDate		as transferredOn 
     			,	SH.discardedDate		as discardedOn
     			, 	SH.dispositionId
                 ,	SH.sessionStartTime			as WhatsappStartTime
                 ,	CASE WHEN SH.sessionEndTime>0 THEN SH.sessionEndTime ELSE NULL END		  as WhatsappEndTime
                 ,	SDH.Duration			as duration
     			
     			 
                 ,	SH.afterWhatsappWorkTime		
                 ,	SH.IsInBound			
           
                 ,	Null									as csatScore
                 ,	SH.dispositionSubject
                 ,	SH.Summary
			FROM 	tb_WhatsappHistory 			SH
			JOIN 	tb_WhatsappDurationHistory	SDH		ON SH.WhatsappHistoryId = SDH.WhatsappHistoryId
			
			LEFT JOIN tb_User					U		ON U.UserID				= SDH.AgentId
			
			LEFT JOIN temp_agentIDs 			t_A 	ON U.UserID  			= t_A.agentId       
			LEFT JOIN temp_dispositionIds		t_D		ON t_D.dispositionId	= SH.dispositionId    
			WHERE 	SH.domainId 			= p_domainId 		
			AND 	SH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
			
			AND 	(IFNULL(p_agentIDs,'')	= '' OR (IFNULL(p_agentIDs,'') <> '' 				AND t_A.agentId IS NOT NULL))
			AND 	(IFNULL(p_dispositionIds,'')	= '' OR (IFNULL(p_dispositionIds,'') <> '' 	AND t_D.dispositionId IS NOT NULL));
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         
     
     	SELECT * FROM temp_AllagentId;
         SELECT * FROM temp_AvailableDisposition;
 		SELECT COUNT(1) totalCount FROM temp_WhatsappHistory;    
         
         
        IF((p_Limit IS NOT NULL)AND (p_Offset IS NOT NULL)) THEN
			DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_1; 	
				CREATE TEMPORARY TABLE temp_WhatsappHistory_1 AS 	    
				SELECT 	*
				FROM 	temp_WhatsappHistory	
				ORDER BY `dateTime` DESC 
				LIMIT v_offset, p_Limit;
			ELSE
				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_1; 	
				CREATE TEMPORARY TABLE temp_WhatsappHistory_1 AS 	    
				SELECT 	*
				FROM 	temp_WhatsappHistory	
				ORDER BY `dateTime` DESC;
		END IF;
         
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_2;	
   	CREATE TEMPORARY TABLE temp_WhatsappHistory_2    
     	SELECT 	SH.`dateTime`
     		,	SH.agentName
			,	SH.customerNumber
     	
   
     	
             ,	CASE WHEN SH.IsInBound  = 0 THEN 'OutBound' ELSE 'InBound' END as direction 
     		,	WhatsappStartTime				as chatStartTime
     		,	WhatsappEndTime					as chatEndTime
     		,	duration		
     		,	sum((duration/1000) + afterWhatsappWorkTime) as activeChattime 
     
             ,	TIMEDIFF(SH.repliedOn, SH.receivedOn) as responsetime
     		,	t_A.DispositionStatus			as disposition
     	
     		,	SH.afterWhatsappWorkTime		as ACWtime	
     		,	SH.csatScore	as customerSatisfactionScore	
            ,	SH.Summary
            ,	SH.dispositionSubject
     	FROM 	temp_WhatsappHistory_1		SH
     	LEFT JOIN temp_AvailableDisposition	t_A	ON 	t_A.dispositionId	= SH.dispositionId
        GROUP BY SH.`dateTime`,SH.agentName , SH.customerNumber,SH.IsInBound,WhatsappStartTime,WhatsappEndTime,duration,SH.repliedOn,SH.receivedOn,t_A.DispositionStatus,SH.afterWhatsappWorkTime,SH.csatScore
        ,SH.Summary,SH.dispositionSubject;
   
   
   	ALTER TABLE temp_WhatsappHistory_2 ADD COLUMN customerName VARCHAR(150);        			
   			
   	UPDATE 	temp_WhatsappHistory_2		SH
   	JOIN 	customer_contact	       c_c	ON 	c_c.primaryPhoneNumber	LIKE SH.customerNumber											
   	SET 	customerName	= CONCAT(c_c.firstName, ' ',c_c.lastName);
   
   	UPDATE 	temp_WhatsappHistory_2		SH        
   	SET 	customerName	= (SELECT CONCAT(InTC.firstName,' ',InTC.lastName) FROM customer_contact InTC WHERE InTC.phoneNumber LIKE CONCAT('%',SH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)				
   	WHERE 	IFNULL(SH.customerName,'') = '';        
   	
   	UPDATE 	temp_WhatsappHistory_2		SH        
   	SET 	customerName	= 'New Customer'
   	WHERE 	IFNULL(REPLACE(SH.customerName,' ',''),'') = '';  
   	 
   	SELECT 	dateTime, agentName, customerName, direction, chatStartTime, chatEndTime, duration, activeChatTime, responsetime as responseTime, disposition, ACWtime, customerSatisfactionScore
    ,dispositionSubject as subject,Summary as summary
       FROM 	temp_WhatsappHistory_2;
               
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_updateChatDeflection` */;
