CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_updateChatDeflection`(
			IN p_ChatHistoryId                  BIGINT,
   		    IN p_ChatDurationHistoryId			BIGINT,
         	IN p_chatDeflection   			    INT
           )
BEGIN
       	DECLARE v_errcode 							INT			DEFAULT -1;
       	DECLARE v_errmsg							VARCHAR(50)	DEFAULT 'Not Updated';
        DECLARE v_chatDeflection 					INT;
        DECLARE	v_CurDate							DATETIME; 
        
       	SET v_chatDeflection  			    = p_chatDeflection;
         SET v_CurDate = NOW();


SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
               
               UPDATE 	 tb_ChatDurationHistory 
               SET 		 chatDeflection 		= v_chatDeflection
					,	 updatedAt				= v_CurDate 
               WHERE 	(ChatDurationHistoryId	= p_ChatDurationHistoryId
               OR      ChatHistoryId             = p_ChatHistoryId);        
               
               SET v_errcode = 0;
               SET v_errmsg  = 'Updated Successfully';        

 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 
	SELECT v_errcode as errcode,v_errmsg as errmsg;
 
 end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
