CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_UpdateFacebookConfiguration`(        
      IN p_pageId         VARCHAR(255),
      IN p_authToken      TEXT,
      IN p_instagramId    VARCHAR(50),
      IN p_pageName       VARCHAR(255)
      
  )
BEGIN
      DECLARE v_curDate  DATETIME DEFAULT NOW();
      DECLARE v_errCode  INT DEFAULT -1;
      DECLARE v_errMsg   VARCHAR(150) DEFAULT 'Error : Not Updated'; 
      
  	UPDATE tb_FacebookClientConfiguration
      SET 
          authToken   = p_authToken,
          instagramId = p_instagramId,
          pageName    = p_pageName,
          updatedDate = v_curDate
      WHERE pageId       = p_pageId;
      
          
      SET v_errCode = 0,
          v_errMsg = 'Update Facebook Configuration';
  
      SELECT v_errCode AS errCode, v_errMsg AS errMsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
