       IN p_domainId  INT,
       
       IN p_pageId varchar(50),
       IN p_whatsappNumber varchar(50)
   )
BEGIN
       DECLARE v_curDate  DATETIME DEFAULT NOW();
       DECLARE v_domainId INT;
       DECLARE v_errCode  INT DEFAULT -1;
       DECLARE v_errMsg   VARCHAR(150) DEFAULT 'Error : Not Updated'; 
   
 		UPDATE tb_FacebookClientConfiguration
 		SET 
			pageId = p_pageId,
 			whatsappNumber = p_whatsappNumber,
 			updatedDate = v_curDate
 		WHERE domainId = p_domainId;
   
       SET v_errCode = 0;
