CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_update_custom_field_info`(	 
 p_id					INT
,p_domainId 			INT	 
,p_field_type 			VARCHAR(50) 	
,p_field_label 			VARCHAR(50) 	
,p_field_value 			VARCHAR(2000)	
,p_isMandatory 			TINYINT 
,p_placeHolder 			VARCHAR(300) 
,p_errMsg 				VARCHAR(300) 
,p_isDisplay			TINYINT 
)
BEGIN	
	DECLARE v_errcode 	INT	DEFAULT 0;
	DECLARE v_errmsg 	VARCHAR(150) DEFAULT 'Custom field update failed';    
        
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
    UPDATE customer_contact_column_properties
    SET 	columnLabel		= p_field_label
		,	placeHolder		= p_placeHolder
		,	errMsg			= p_errMsg
		,	columnType		= p_field_type
		,	isMandatory		= p_isMandatory
		,	isDisplay		= p_isDisplay
		,	columnValue		= p_field_value
		,	modifedAt		= NOW()
	WHERE 	id				= p_id;
    
    IF row_count() > 0
    THEN
		SET v_errcode 	= 1
		,	v_errmsg	= 'Custom field updated Successfully';
    END IF;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
