DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_user_update_v2`(
  p_UserID bigint,
  p_UserName varchar(255),
  p_emailId varchar(255), 
  p_directNumber bigint,
  p_address varchar(255), 
  p_routing_profile_id int,
  p_report_to_UserID bigint, 
  p_sipLoginId int, 
  p_companyId int, 
  p_domainId int, 
  p_ext int, 
  p_isActive tinyint, 
  p_callTypeId int, 
  p_roleid tinyint, 
  p_localization varchar(20), 
  p_currentSession varchar(100), 
  p_isVoice tinyint, 
  p_isVoiceCallTransfer tinyint, 
  p_isChat tinyint, 
  p_isChatTransfer tinyint, 
  p_isEmail tinyint, 
  p_isEmailTransfer tinyint, 
  p_StatusID int, 
  p_isSms tinyint, 
  p_isSocialMedia tinyint, 
  p_addSkill json,
  p_voice int, 
  p_chat int, 
  p_email int, 
  p_sms int, 
  p_socialMedia int,
  p_ProfileImage text,
  p_companyName	varchar(64)
  )
Begin
 
  	declare v_errcode int 		  default -1;
  	declare v_errmsg  varchar(55) default 'No Update';
          
      if exists(select 1 from tb_User where ext = p_ext and domainId = p_domainId limit 1) then
  		update tb_User
  		set UserName = ifnull(p_UserName,UserName),
  			emailId  = ifnull(p_emailId,emailId),
  			directNumber = ifnull(p_directNumber,directNumber),
  			address  = ifnull(p_address,address),
  			routing_profile_id = ifnull(p_routing_profile_id,routing_profile_id),
  			report_to_UserID  = ifnull(p_report_to_UserID,report_to_UserID),
  			sipLoginId  = ifnull(p_sipLoginId,sipLoginId),
  			companyId  = ifnull(p_companyId,companyId),
  			ext  = ifnull(p_ext,ext),
  			isActive = ifnull(p_isActive,isActive),
  			callTypeId  = ifnull(p_callTypeId,callTypeId),
  			roleid = ifnull(p_roleid,roleid),
  			localization = ifnull(p_localization,localization),
  			currentSession  = ifnull(p_currentSession,currentSession),
  			isVoice = ifnull(p_isVoice,isVoice),
  			isVoiceCallTransfer = ifnull(p_isVoiceCallTransfer,isVoiceCallTransfer),
  			isChat = ifnull(p_isChat,isChat),
  			isChatTransfer = ifnull(p_isChatTransfer,isChatTransfer),
  			isEmail = ifnull(p_isEmail,isEmail),
  			isEmailTransfer = ifnull(p_isEmailTransfer,isEmailTransfer),
  			StatusID  = ifnull(p_StatusID,StatusID),
  			isSms = ifnull(p_isSms,isSms),
  			isSocialMedia = ifnull(p_isSocialMedia,isSocialMedia),
  			addSkill = ifnull(p_addSkill,addSkill),
  			voice  = ifnull(p_voice,voice),
  			chat  = ifnull(p_chat,chat),
  			email  = ifnull(p_email,email),
  			sms  = ifnull(p_sms,sms),
  			socialMedia = ifnull(p_socialMedia,socialMedia),
  			updatedAt = now(),
			ProfileImage = ifnull(p_ProfileImage,ProfileImage),
            companyName = ifnull(companyName,p_companyName)
  		where ext = p_ext and domainId = p_domainId ;
          
   	    if row_count()>0 then
   				set v_errcode = 0;
   				set v_errmsg = 'updated successfully';
   		end if;
      End if;
      
		if ifnull(p_companyName,'')<>'' then
			update tb_User set companyName = p_companyName where domainId = p_domainId ;
            update tb_companyDomain set companyName = p_companyName where domainId = p_domainId ;
            
		end if;
      
      
       select v_errcode as errcode, v_errmsg as errmsg;
  
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_VoiceMail_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_VoiceMail_trendchart`(	
		p_startTmpstmp 	BIGINT,
      	p_endTmpstmp 	BIGINT,
      	p_domainId 		INT,
      	p_columnname 	VARCHAR(155)
      )
BEGIN
      		DECLARE v_startDateTime 				DATETIME;
      		DECLARE v_endDateTime 					DATETIME;
      		DECLARE v_startTmpstmp 					BIGINT;
      		DECLARE v_endTmpstmp 					BIGINT;
      		DECLARE v_startTime	 				    DATETIME;
      		DECLARE v_endTime	 					DATETIME;
      		DECLARE v_currenttimestamp 				BIGINT;
      		DECLARE v_previous_timestamp 			BIGINT;
      		DECLARE v_oneday_previous_timestamp 	BIGINT;
      		DECLARE v1_count_currentdata 		    BIGINT;
      		DECLARE v2_count_pastdata 				BIGINT;
      		DECLARE v_coulumnname                   VARCHAR(150);
      		DECLARE v_interval						INT;
              
              
     			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
      			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
      			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;    
               
      			SET v_coulumnname=p_columnname;
      			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
      			CREATE TEMPORARY TABLE temp_Intervals (
      			starttime DATETIME,
      			endtime   DATETIME
      			);
                   
      			SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day),from_unixtime(p_startTmpstmp/1000));
        			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
                  
                  set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                  set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                  
                  
                  IF DATEDIFF(v_endDateTime,v_startDateTime) > 29
                  THEN
      				SET v_interval = 86400; 
      			ELSEIF DATEDIFF(v_endDateTime,v_startDateTime) > 1
                  THEN
      				SET v_interval = 3600; 
                  ELSE
                  	SET v_interval = 60; 
                  END IF;
                       
        			SET v_startTime = v_startDateTime;
      			SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
                       
        			 WHILE v_startTime < v_endDateTime 
        			 DO      
      				 INSERT INTO temp_Intervals (starttime, endtime)
      				 VALUES (v_startTime, v_endTime);
                       
      				SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval second));
      				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval second));
      			END WHILE;
     	 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
		    DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                              	
                    
                      		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                  		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                  		(    DispositionId 			INT
                  			,DispositionStatus 		VARCHAR(100)
                  			,DispositionCategory	TINYINT
                  		);             
							
						INSERT INTO temp_AvailableDisposition 
                  		SELECT 	did 			DispositionId
                  			,	dispositionName	DispositionStatus
                  			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                  				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                  				WHEN dispositionName = 'Discarded'     THEN 4
           					    WHEN dispositionName = 'Resolved'      THEN 5
                  				END 			DispositionCategory
                  		FROM 	disposition_status
                  		WHERE 	domainId	= p_domainId;
                        
                DROP TEMPORARY TABLE IF EXISTS temp_VoiceMailHistory;
      			CREATE TEMPORARY TABLE temp_VoiceMailHistory
      			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
      			FROM 	tb_CallHistory H 
      			WHERE 	H.domainId = p_domainId
      			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
      			GROUP BY H.sessionStartTime;   
                
      			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
      			CREATE TEMPORARY TABLE temp_Intervals_1
      			SELECT t_I.endtime 	AS `Time`
      				,	count(1)	AS `NoofreceivedEmailCount`
      			FROM temp_Intervals t_I
      			JOIN temp_VoiceMailHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
      			GROUP BY t_I.endtime;
          
        			SELECT  (t_I.endtime) 						AS `Time`
      				,	IFNULL(t.NoofreceivedEmailCount,0)	AS NoofreceivedcurrentEmailCount
   				    FROM 		temp_Intervals t_I 
        			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;         
                 
                 
                 DROP TEMPORARY TABLE IF EXISTS temp_VoiceMailHistory1;
      			CREATE TEMPORARY TABLE temp_VoiceMailHistory1
      			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
      			FROM 	tb_CallHistory H 
      			WHERE 	H.domainId = p_domainId
      			AND  	H.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
      			GROUP BY H.sessionStartTime;   
                 
     			 DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
      			CREATE TEMPORARY TABLE temp_Intervals_2
      			SELECT t_I.endtime 	AS `Time`
      				,	count(1)	AS `NoofreceivedEmailCount`
      			FROM temp_Intervals t_I
      			JOIN temp_VoiceMailHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
      			GROUP BY t_I.endtime;
          
        			SELECT  (t_I.endtime) 						    AS `Time`
      				,	IFNULL(t.NoofreceivedEmailCount,0)	        AS NoofreceivedpastemailCount
      			    FROM 		temp_Intervals t_I 
        			LEFT JOIN   temp_Intervals_2 t ON t.time = t_I.endtime;
                      
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
    		CREATE TEMPORARY TABLE temp_callDurationHistory AS
    		SELECT	 CH.sessionStartTime		
					,CH.CallHistoryId        
					,CDH.CallDurationHistoryId
					,CDH.AgentId
   					,(CDH.EndTime - CDH.StartTime)	                    AS callDuration
 					,CDH.afterCallWorkTime			                    AS afterCallWorkTime
 					,CH.IsInBound					                    AS IsInBound
  					,CDH.StartTime										AS agentconnecttime
   					,CDH.EndTime					   					AS agentDisconnectTime
 					,DS.dispositionName
					,CH.voicemailUrl									AS voicemailUrl
					,CH.voiceMailDuration								AS voiceMailDuration
					,CH.isVoiceMailAnswered							    AS isVoiceMailAnswered
 					,CH.voiceMailAnsweredCallHistoryId					AS voiceMailAnsweredCallHistoryId
					,CDH.dispositionId									AS dispositionId
                    ,CH.domainId 
    		FROM 		tb_CallHistory 			CH
    		LEFT JOIN 	tb_CallDurationHistory	CDH	    ON CH.CallHistoryId 		= CDH.CallHistoryId
    		LEFT JOIN 	tb_CallMessage			CM		ON CH.CallHistoryId 		= CM.CallHistoryId and CM.CallDurationHistoryId	= CDH.CallDurationHistoryId
    		LEFT JOIN 	temp_agentIDs 		    t_A     ON CDH.AgentId				= t_A.agentId   
 		    LEFT JOIN 	disposition_status		DS		ON DS.did					= CDH.dispositionId and DS.domainId = CH.domainId
    		WHERE 	CH.domainId 			= p_domainId 		
    		AND 	CH.IsInBound			= 1
    		AND 	CH.sessionStartTime 	BETWEEN v_startDateTime AND v_endDateTime ; 
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
            
            DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
    		CREATE TEMPORARY TABLE temp_PrevCallHistory as
    		SELECT 	DISTINCT CallHistoryId
    		FROM 	temp_callDurationHistory
    		WHERE 	sessionStartTime BETWEEN  v_startDateTime AND v_endDateTime  and ifnull(voiceMailDuration,'')<>'';
    
    		DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
    		CREATE TEMPORARY TABLE temp_CurCallHistory AS
    		SELECT 	DISTINCT CallHistoryId
    		FROM 	temp_callDurationHistory
    		WHERE 	sessionStartTime BETWEEN v_startDateTime AND v_endDateTime and ifnull(voiceMailDuration,'')<>'';   
            
    		ALTER TABLE temp_PrevCallHistory ADD COLUMN isVoiceMailAnswered	TINYINT;
    		ALTER TABLE temp_CurCallHistory ADD COLUMN isVoiceMailAnswered	TINYINT;
            
 			UPDATE 	temp_PrevCallHistory CH
         	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
         	AND 	CDH.dispositionId IS NOT NULL and ifnull(voiceMailDuration,'')<>'' and CDH.isVoiceMailAnswered = 1
         	SET 	CH.isVoiceMailAnswered = 1;
             
         	UPDATE 	temp_CurCallHistory CH
         	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
         	AND 	CDH.dispositionId IS NOT NULL and ifnull(voiceMailDuration,'')<>'' and CDH.isVoiceMailAnswered = 1                        
            SET 	CH.isVoiceMailAnswered = 1;            
                        
   IF    p_columnname = 'Voicemail Received' 
              THEN
          		
				SELECT COUNT(1)																			AS VoicemailReceived
				INTO v1_count_currentdata 
				FROM temp_callDurationHistory
				WHERE sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
				AND domainId = p_domainId 
                LIMIT 1;
                  
          		
				SELECT COUNT(1)																			AS VoicemailReceived
				INTO v2_count_pastdata 
				FROM temp_callDurationHistory
				WHERE sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
				AND domainId = p_domainId 
                LIMIT 1;   
	ELSEIF         p_columnname = 'Voicemail Responded'
              THEN
          		
          		SELECT 	SUM(CASE WHEN voiceMailDuration IS NOT NULL THEN 1 ELSE 0 END)					AS VoicemailResponded		                    		
          		INTO 	v1_count_currentdata 
				FROM 	temp_callDurationHistory SH
          		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	SH.domainId	= p_domainId
				LIMIT 1; 
                  
          		
          		SELECT 	SUM(CASE WHEN voiceMailDuration IS NOT NULL THEN 1 ELSE 0 END)					AS VoicemailResponded
          		INTO 	v2_count_pastdata 
				FROM 	temp_callDurationHistory SH
          		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	SH.domainId	= p_domainId
				LIMIT 1;
                                     
 ELSEIF         p_columnname = 'Voicemail Not Responded'
              THEN
          		
          		SELECT 	SUM(CASE WHEN voiceMailDuration IS NULL THEN 1 ELSE 0 END)						AS VoicemailNotResponded	                    		
          		INTO 	v1_count_currentdata 
				FROM 	temp_callDurationHistory 
          		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	domainId	= p_domainId
				LIMIT 1; 
                  
          		
          		SELECT 	SUM(CASE WHEN voiceMailDuration IS NULL THEN 1 ELSE 0 END)						AS VoicemailNotResponded
          		INTO 	v2_count_pastdata 
				FROM 	temp_callDurationHistory 
          		WHERE   sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	domainId	= p_domainId
				LIMIT 1;                       
                        
   ELSEIF         p_columnname = 'Total length Of Voicemails'
              THEN
          		
          		SELECT SUM(voiceMailDuration)																AS Total_voicemail_length	                    		
          		INTO 	v1_count_currentdata 
				FROM 	temp_callDurationHistory 
          		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	domainId	= p_domainId
				LIMIT 1; 
                  
          		
          		SELECT 	SUM(voiceMailDuration)																AS Total_voicemail_length
          		INTO 	v2_count_pastdata 
				FROM 	temp_callDurationHistory 
          		WHERE   sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	domainId	= p_domainId
				LIMIT 1;                        
                        
                        
                        
   ELSEIF         p_columnname = 'Average length Of Voicemails'
              THEN
          		
          		SELECT IFNULL(sum(voiceMailDuration) /1000,0)												AS Avg_voicemail_length                      		
          		INTO 	v1_count_currentdata 
				FROM 	temp_callDurationHistory 
          		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	domainId	= p_domainId
				LIMIT 1; 
                  
          		
          		SELECT IFNULL(sum(voiceMailDuration) /1000,0)												AS Avg_voicemail_length  
          		INTO 	v2_count_pastdata 
				FROM 	temp_callDurationHistory 
          		WHERE   sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
          		AND 	domainId	= p_domainId
				LIMIT 1;                           
                        
			END IF;        
       		SELECT 	v1_count_currentdata																    currentdata
          		,	v2_count_pastdata																		pastdata
          		,	(v1_count_currentdata - v2_count_pastdata) 												dataDifference 
      			,	(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	          
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_Voice_Agent_callback_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_Voice_Agent_callback_trendchart`(
	p_domainId 			INT,
	p_datetype 			INT,            
	p_startDateTime		DATETIME,
	p_endDateTime		DATETIME,
	p_columnName    	VARCHAR(200),    
	p_agentId 			TEXT
)
BEGIN
   
    	DECLARE v_startDateTime			DATETIME;
    	DECLARE v_endDateTime			DATETIME;     
    	DECLARE v_datetimeInterval		SMALLINT;    
    	DECLARE v_startDateTimePast		DATETIME;
    	DECLARE v_endDateTimePast		DATETIME;
         
    	DECLARE v_startTimestampPast	BIGINT;
    	DECLARE v_endTimestampPast		BIGINT;      
    	DECLARE v_startTimestamp		BIGINT;
    	DECLARE v_endTimestamp			BIGINT;
    	DECLARE v_curDate				DATETIME DEFAULT NOW();	
  	DECLARE v_currentCount			INT;
  	DECLARE v_pastCount				INT;
        
    	DROP TEMPORARY TABLE IF EXISTS tmp_result;
    	CREATE TEMPORARY TABLE tmp_result(
    		reportAge			VARCHAR(20)
    		,startDateTime		DATETIME
    		,endDateTime		DATETIME
    		,callCount			INT
    	);    
     
     	IF p_datetype = 1 
         THEN 	
     		SET v_startDateTime = CAST(v_curDate AS DATE); 
     		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
     	END IF;
     	IF p_datetype = 2 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
    		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
     
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
     	END IF;
     	IF p_datetype = 3 
         THEN 
     		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -7 DAY) AS DATE); 
            SET v_endDateTime = CAST(v_curDate AS DATE); 
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -7 DAY); 
     		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -7 DAY);   
     	END IF;
     	IF p_datetype = 4 
         THEN 
     		SET v_startDateTime = p_startDateTime; 
    		SET v_endDateTime 	= p_endDateTime; 
             
            SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
             
     		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
     	END IF;
         
           IF p_agentId IS NOT NULL 
           THEN
       		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
       		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
           ELSE
       		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
              CREATE TEMPORARY TABLE temp_agentIds
     		 select  UserID AS agentId,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
  		END IF;
         
         DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
         CREATE TEMPORARY TABLE tmp_Disposition
         SELECT did, dispositionName
         FROM 	disposition_status
         WHERE	domainId		= p_domainId
         AND	dispositionName	= 'Caller Disconnected';    
         
         IF p_datetype IN (1,2)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH RECURSIVE CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	endDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
     	ELSEIF p_datetype IN (3,4)
         THEN 
     		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
             CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
     		WITH recursive CTE_TIMINGS AS (
     			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
     			UNION ALL
     			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
     			FROM 	CTE_TIMINGS
     			WHERE 	startDateTime < v_endDateTime
     		)
     		SELECT * FROM CTE_TIMINGS;	
         END IF;  
         
         ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
         
         UPDATE tmp_timings
         SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
     		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
             
     	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
    	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
    	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
    	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
       
       
   DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
    	CREATE TEMPORARY TABLE tmp_CallDurationHistory
    	SELECT 	CH.CallHistoryId 
   		   , CH.sessionStartTime
             , SUM(CASE WHEN CH.callBack = 2 THEN 1 ELSE 0 END )     				AS answeredCalls
             , SUM( case when CDH.Duration > 0 Then 1 else 0 end )				AS callBackAnswered
             , SUM(CASE WHEN CDH.Duration < 1 THEN 1 ELSE 0 END) 					AS callBackUnanswered
             FROM 	tb_CallHistory         CH
    	JOIN 	tb_CallDurationHistory CDH	ON 	CH.CallHistoryId 	= CDH .CallHistoryId     
    	JOIN     temp_agentIds 		       t_A     ON t_A.agentId 		= CDH.agentId	
    	WHERE 	CH.domainId 		= p_domainId
       and   	CH.callBack			IN (1,2)
    	AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
       GROUP BY CH.CallHistoryId,CH.sessionStartTime;
       
   
       DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
     	CREATE TEMPORARY TABLE tmp_CallHistory
        SELECT 	DISTINCT 
     			CDH.CallHistoryId 
     		, 	CDH.sessionStartTime
     	FROM 	tmp_CallDurationHistory CDH;  
   
   	  ALTER TABLE tmp_CallHistory ADD answeredCalls 	    TINYINT DEFAULT 0;
         ALTER TABLE tmp_CallHistory ADD callBackAnswered 		TINYINT DEFAULT 0;
         ALTER TABLE tmp_CallHistory ADD callBackUnanswered	TINYINT DEFAULT 0;         
             
   	CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
   	CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId); 
            
       
        UPDATE tmp_CallHistory			CH
         JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  
    
         SET 	CH.answeredCalls		= CASE WHEN CDH.answeredCalls   = 1 	THEN 1 ELSE CH.answeredCalls 		END
     		  ,	CH.callBackAnswered		= CASE WHEN CDH.callBackAnswered =1		THEN 1 ELSE CH.callBackAnswered 	END
             ,CH.callBackUnanswered	= CASE WHEN CDH.callBackUnanswered =1	THEN 1 ELSE CH.callBackUnanswered 	END;  
             
             
      
      
       IF p_columnName = 'Callbacks Returned'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(CH.answeredCalls),0)	AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					        AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	IFNULL(SUM(CH.answeredCalls),0)	AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
          ELSEIF p_columnName = 'Callbacks Received'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'						AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	COUNT(CH.CallHistoryId)	        AS callCount
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					        AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
     			,	COUNT(CH.CallHistoryId)	          AS callCount     
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;  
           
    ELSEIF p_columnName = 'Callbacks Answered'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'								  AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
               ,   IFNULL(SUM(CH.callBackAnswered),0)        AS callCount              
     			
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					        									AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
               ,   IFNULL(sum(CH.callBackAnswered),0)                                  AS callCount   
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;       
      
      
      
      ELSEIF p_columnName = 'Callbacks Unanswered'
         THEN
    		INSERT INTO tmp_result
     		SELECT 	'Current'								  AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
               ,   IFNULL(SUM(CH.callBackUnanswered),0)        AS callCount              
     			
     		FROM 	tmp_timings			t_T	
     		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
     		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
            INSERT INTO tmp_result
     		SELECT 	'Past'					        									AS reportAge
     			,	t_T.startDateTime 
     			,	t_T.endDateTime
               ,   IFNULL(sum(CH.callBackUnanswered),0)                                  AS callCount   
     		FROM 	tmp_timings		t_T	
     		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
     		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
     		GROUP BY t_T.startDateTime, t_T.endDateTime;   
               END IF;
  
               
   	 SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Current';    
        
        SELECT  *
        FROM 	tmp_result
        WHERE 	reportAge = 'Past';
         
    	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' 	THEN callCount ELSE 0 END)	AS pastCount
    	INTO 	v_currentCount, v_pastCount		
    	FROM 	tmp_result;
      
      
      end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_WhatApp_agent_performances_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_WhatApp_agent_performances_analysis_metrics_filter`(  
  	p_startTmpstmp  BIGINT,
  	p_endTmpstmp 	BIGINT,
  	p_domainId 		INT,    	
  	p_agentId		VARCHAR(250),		
  	p_offset 		INT,
  	p_Limit			INT	
  )
sp_return: BEGIN
  				 
  		DECLARE v_offset INT; 								DECLARE v_CurrentStartTmpstmp BIGINT;			DECLARE v_CurrentEndTmpstmp BIGINT;				DECLARE v_PrevStartTmpstmp BIGINT;
  		DECLARE v_PrevEndTmpstmp BIGINT; 					DECLARE v_TmpstmpInterval BIGINT;				DECLARE v_PrevAverageResponseCount INT;			DECLARE v_CurrentAverageResponseCount INT;	        
  		DECLARE v_DiffAverageResponsePercent INT;			DECLARE v_PrevAverageHandledCount BIGINT;		DECLARE v_CurrentAverageHandledCount BIGINT;	DECLARE v_DiffAverageHandledPercent BIGINT;  
  			
  		DECLARE v_PrevMaximumHandledCount BIGINT;			DECLARE v_CurrentMaximumHandledCount BIGINT;	DECLARE v_DiffMaximumHandledTimePercent	BIGINT;	DECLARE v_PrevTotalACWCount INT;			
 		DECLARE v_CurrentTotalACWCount INT;	   				DECLARE v_DiffTotalACWTimePercent INT;   		DECLARE v_PrevAverageQueueWaitingCount INT;		DECLARE v_CurrentAverageQueueWaitingCount INT;	        		
 		DECLARE v_DiffAverageQueueWaitingPercent INT; 		DECLARE v_PrevaverageHoldtCount	INT;			DECLARE v_CurrentaverageHoldtCount INT;			DECLARE v_DiffaverageHoldtPercent INT; 
  			
  		DECLARE v_PrevMaximumQueueWaitingCount INT;			DECLARE v_CurrentMaximumQueueWaitingCount INT;	DECLARE v_DiffMaximumQueueWaitingPercent INT;	DECLARE v_PrevfirstChatResolutionCount INT;	
  		DECLARE v_CurrentfirstChatResolutionCount INT;		DECLARE v_DifffirstChatResolutionPercent INT;  	DECLARE v_PreSatisfactionRateScore INT;			DECLARE v_CurrentSatisfactionRateScore INT;
  		DECLARE v_DiffSatisfactionRateScorePercent INT;     DECLARE v_PrevAgentIdleTimeCount INT;			DECLARE v_CurrentAgentIdleTimeCount INT;		DECLARE v_DifffirsAgentIdleTimePercent INT; 
          
  		DECLARE v_PreavailableCount INT;					DECLARE v_CurrentavailableCount INT;			DECLARE v_PretotalTalkCount INT;				DECLARE v_CurrenttotalTalkCount INT;  
  		DECLARE v_CurrentAvailableTime BIGINT;				DECLARE v_TotalTalktime BIGINT;					DECLARE v_past_tot_chat INT;					DECLARE v_cur_tot_chat INT;
 		DECLARE v_AgentIdleTime BIGINT;						DECLARE v_callDuration BIGINT;					DECLARE v_MHT FLOAT;
          
  		SET v_offset =  p_Limit * p_offset; 
                  
  		IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
  		IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
  
  		SET v_TmpstmpInterval 	= v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
  		SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
  		SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
  
  		DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
  		CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;      
                      	        
  		DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
  		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                       	
  		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
  		CREATE TEMPORARY TABLE temp_AvailableDisposition 
  		(    DispositionId 			INT
  			,DispositionStatus 		VARCHAR(100)
  			,DispositionCategory	TINYINT
  		); 
  
  		INSERT INTO temp_AvailableDisposition 
  		SELECT 	did 			DispositionId
  			,	dispositionName	DispositionStatus
  			,	CASE WHEN dispositionName = 'Opened'	THEN 2
  					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
  					WHEN dispositionName = 'Discarded'     THEN 4
  					WHEN dispositionName = 'Resolved'      THEN 5 END  DispositionCategory
  		FROM 	disposition_status
  		WHERE 	domainId	= p_domainId;
  
  		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  		CREATE TEMPORARY TABLE temp_AllagentId
  		SELECT UserID,UserName,ext,domainId 
          FROM tb_User 
          WHERE domainId = p_domainId ; 
          
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory; 
  		CREATE TEMPORARY TABLE temp_WhatAppHistory AS 	    	
  		SELECT 		WH.sessionStartTime
  				,	WH.WhatsappHistoryId
                  ,	WDH.WhatsappDurationHistoryId
  				,	WDH.AgentId
  				,	U.UserName													        AS agentName
  				, 	WH.IsInBound
  				, 	WDH.Duration                                                        AS callDuration
  				
  				, 	CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		    AS Handled
  				, 	CASE WHEN t_D.DispositionCategory = 5 and IFNULL(WH.Istransferred,0) = 0 THEN 1 ElSE 0 END AS firstChatResolution
  				, 	WH.sessionStartTime                                                 AS agentconnecttime
  				,	(WDH.Duration/1000 + WH.afterwhatsappWorkTime)						AS chatHandlingTime
  				,	WDH.dialDuration													AS responseTime
  				, 	WDH.Duration												        AS Duration
  				, 	WH.afterwhatsappWorkTime                                       
  				, 	cfb.satisfactionRate												as satisfactionRate
  				, 	NULL                                                                AS queueDuration
                 ,	WDH.QueueId															AS QueueId
  		FROM 	tb_WhatsappHistory 			WH
  		JOIN 	tb_WhatsappDurationHistory	WDH	ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId     
  		LEFT JOIN temp_AvailableDisposition	t_D	ON WH.dispositionId		= t_D.DispositionId
  		LEFT JOIN tb_User					U	ON U.UserID				= WDH.AgentId
          LEFT JOIN tb_customerFeedback		cfb	ON cfb.historyId 		= WH.WhatsappHistoryId and cfb.domainId = WH.domainId
  		
  		WHERE 	WH.domainId 		= p_domainId	
          AND		WDH.IsBot			= 0
          AND		(WDH.AgentId in (select UserID from temp_agentIDs) or ifnull(p_agentId,'')='')
  		AND 	WH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ;
                    
  		DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_calc; 
  		CREATE TEMPORARY TABLE temp_WhatAppHistory_calc AS 	
  		SELECT 	
 				t_SH.sessionStartTime
 				, t_SH.WhatsappHistoryId
 				, t_SH.AgentId
 				, t_SH.agentName																              						 			AS agentName
 				, SUM(t_SH.responseTime)																										AS responseTime
 				, SUM(t_SH.chatHandlingTime)																									AS HandledTime
                 , IFNULL(SUM(t_SH.chatHandlingTime) / NULLIF(SUM(CASE WHEN t_SH.callDuration > 0 THEN 1 ELSE 0 END), 0) / 1000, 0) 				AS averageHandleTime
                 , SUM(CASE WHEN t_SH.chatHandlingTime > (QUE.maxCallHandlingTimeMM * 60000) then 1 else 0 end)
 							/ NULLIF(SUM(CASE WHEN t_SH.callDuration > 0 THEN 1 ELSE 0 END), 0)* 100											AS maximumHandleTime
 				, SUM(t_SH.afterwhatsappWorkTime)																								AS totalACWTime
 				, SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime > 0  THEN 1 ELSE 0 END)       						    			AS answeredCall
 				, SUM(t_SH.callDuration)												                                                 		AS totalTalktime
 				, t_SH.firstChatResolution																										AS firstChatResolution
 				, t_SH.satisfactionRate                                                                                                  		AS CustomerSatisfaction
 				, t_SH.queueDuration                                                                                                     		AS queueWaitingtime
                 , t_SH.QueueId																													AS QueueId
  		FROM 	temp_WhatAppHistory	t_SH
         LEFT JOIN queue				QUE ON t_SH.QueueId = QUE.qid
 		WHERE	t_SH.sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
  		GROUP BY t_SH.sessionStartTime,t_SH.WhatsappHistoryId, t_SH.AgentId, t_SH.agentName
 				, t_SH.firstChatResolution,t_SH.satisfactionRate,t_SH.queueDuration, QUE.maxCallHandlingTimeMM,t_SH.QueueId;
         
  		DROP TEMPORARY TABLE IF EXISTS temp_AvailableState;
  		CREATE TEMPORARY TABLE temp_AvailableState AS
  		SELECT   
  				CASE 	WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1 
  				WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Not Ready', 'Away', 'Offline') THEN 2 
  				WHEN a.aid = ST.timerStatusId AND a.isVoice = 1 and a.statusName NOT IN ('Not Ready', 'Away', 'Offline','Ready', 'Transfer Only', 'Busy') THEN 1 
  				ELSE 0  END AS tt_Time,
  				ST.ext,
  				ST.domainId,
  				from_unixtime(ST.startTimestamp/1000),
  				ST.stateDuration as SD
  		FROM     state_timer ST 
  		JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
  		WHERE    ST.domainId = p_domainId
  		AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;   
  
  		ALTER TABLE temp_WhatAppHistory_calc ADD COLUMN availableTime		INT;
              
  		UPDATE temp_WhatAppHistory_calc SH_C
  		JOIN temp_AllagentId t_A ON SH_C.agentId = t_A.UserID
  		JOIN (
  				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
  				FROM temp_AvailableState
  				GROUP BY ext, domainId
  			) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
  		SET SH_C.availableTime = tt_AV.total_SD;   
          
  	
  		SELECT COUNT(WhatsappHistoryId),ifnull(SUM(responseTime),0), ifnull(SUM(chatHandlingTime),0), ifnull(SUM(satisfactionRate),0)
  		INTO 	v_past_tot_chat,v_PrevAverageResponseCount , v_PrevaverageHandledCount ,  v_PreSatisfactionRateScore
  		FROM temp_WhatAppHistory where sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ;
          
  	
  		SELECT COUNT(WhatsappHistoryId),ifnull(SUM(responseTime),0), ifnull(SUM(chatHandlingTime),0), ifnull(SUM(satisfactionRate),0),IFNULL(SUM(afterwhatsappWorkTime),0)
  				,sum(firstChatResolution)
  		INTO v_cur_tot_chat,v_CurrentaverageResponseCount , v_CurrentaverageHandledCount , v_CurrentSatisfactionRateScore,v_CurrenttotalACWCount
  				,v_CurrentfirstChatResolutionCount
  		FROM temp_WhatAppHistory where sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;
  
  		SELECT * FROM temp_AllagentId;   
         
          SELECT SUM(availableTime),SUM(availableTime),SUM(totalTalktime) into v_AgentIdleTime, v_CurrentavailableTime,v_callDuration from temp_WhatAppHistory_calc;
          
 		select SUM(CASE WHEN CDH.HandledTime > (QUE.maxCallHandlingTimeMM * 60000) then 1 else 0 end)
 				/IF(SUM(CASE WHEN CDH.totalTalktime > 0 THEN 1 ELSE 0 END)=0,1,SUM(CASE WHEN CDH.totalTalktime > 0 THEN 1 ELSE 0 END))
 		 into v_MHT
 		from temp_WhatAppHistory_calc CDH 
 		join queue QUE ON CDH.queueId = QUE.qid;
          
  		SET  v_DiffAverageResponsePercent  = (v_CurrentaverageResponseCount - v_PrevAverageResponseCount) / IF(v_PrevAverageResponseCount=0,1,v_PrevAverageResponseCount) * 100  
  			,v_DiffAverageHandledPercent  = (v_CurrentaverageHandledCount - v_PrevaverageHandledCount) / IF(v_PrevaverageHandledCount=0,1,v_PrevaverageHandledCount) * 100
  			,v_DiffSatisfactionRateScorePercent = (v_CurrentSatisfactionRateScore - v_PreSatisfactionRateScore) / IF(v_PreSatisfactionRateScore=0,1,v_PreSatisfactionRateScore) * 100;
        			
  		SELECT 	IFNULL(v_CurrentaverageResponseCount, 0) AS 'CurrentaverageResponseCount',        	IFNULL(v_DiffAverageResponsePercent, 0) AS 'DiffAverageResponsePercent',
  				IFNULL(v_CurrentaverageHandledCount, 0) AS 'CurrentAverageHandledCount',        	IFNULL(v_DiffAverageHandledPercent, 0) AS 'DiffAverageHandledPercent',
  				IFNULL(v_CurrentSatisfactionRateScore, 0) AS 'CurrentCustomerSatisfactionCount',    IFNULL(v_DiffSatisfactionRateScorePercent, 0) AS 'DiffCustomerSatisfactionPercent';	
                               
  	SELECT 'All Agents' 																		AS agentName
 			,v_AgentIdleTime 																	AS AgentIdleTime
 			,IFNULL(v_CurrentaverageResponseCount, 0)/ v_cur_tot_chat 							AS averageResponseTime
 			,IFNULL(v_CurrentaverageHandledCount, 0)/v_cur_tot_chat 							AS averageHandledTime           
 			
 			,v_MHT * 100			AS maximumHandleTime 
 			,SUM(IFNULL(v_CurrenttotalACWCount, 0))*1000 										AS totalACWTime
 			,SUM(v_callDuration+(v_CurrenttotalACWCount * 1000))
 			/SUM(IFNULL(IF(v_CurrentavailableTime=0,1,v_CurrentavailableTime),1)*100) 		AS occupancyrate
 			,IFNULL(v_CurrentfirstChatResolutionCount, 0) 										AS firstChatResolution
 			,IFNULL(v_CurrentSatisfactionRateScore, 0) 											AS CustomerSatisfaction
      UNION ALL 
      SELECT 	a.agentName 																		AS agentName
  			,SUM(availableTime)																		AS AgentIdleTime
  			,SUM(a.responseTime)/COUNT(1)															AS averageResponseTime
  			,SUM(a.averageHandleTime)/COUNT(1)														AS averageHandledTime
  			,MAX(a.maximumHandleTime)																AS MaximumHandledTime
  			,SUM(a.totalACWTime)*1000 																AS totalACWTime 
  			,SUM(a.totalTalktime) / SUM(IFNULL(IF(a.availableTime=0,1,a.availableTime),1)*100)  	AS occupancyrate
  			,SUM(a.firstChatResolution) 															AS firstChatResolution
  			,SUM(a.CustomerSatisfaction) 															AS CustomerSatisfaction
      FROM temp_WhatAppHistory_calc a
      GROUP BY a.agentName;
         
                 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_WhatApp_Inbound_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_WhatApp_Inbound_trendchart`(	
 		p_startTmpstmp 	BIGINT,
       	p_endTmpstmp 	BIGINT,
       	p_domainId 		INT,
   		p_datetype 		INT, 
       	p_columnname 	VARCHAR(155)
       )
BEGIN
       	
        	DECLARE v_startDateTime 				DATETIME;
    		DECLARE v_endDateTime 					DATETIME;
    		DECLARE v_startTmpstmp 					BIGINT;
    		DECLARE v_endTmpstmp 					BIGINT;
    		DECLARE v_startTime	 				    DATETIME;
    		DECLARE v_endTime	 					DATETIME;
    		DECLARE v_currenttimestamp 				BIGINT;
    		DECLARE v_previous_timestamp 			BIGINT;
    		DECLARE v_oneday_previous_timestamp 	BIGINT;
    		DECLARE v1_count_currentdata 		    BIGINT;
    		DECLARE v2_count_pastdata 				BIGINT;
    		DECLARE v_coulumnname                   VARCHAR(150);
    		DECLARE v_interval						INT;
            
             			
    			SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
    			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 1 DAY))* 1000;
    			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;      
    			SET v_coulumnname=p_columnname;
                
                
                
                 IF p_datetype = 1 
                 THEN
    			DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    			CREATE TEMPORARY TABLE temp_Intervals (
    			starttime DATETIME,
    			endtime   DATETIME
    			);          
                 
    			    SET v_startDateTime := if(p_startTmpstmp is null,date_sub(now(), INTERVAL 1 day),from_unixtime(p_startTmpstmp/1000));
      			SET v_endDateTime := if(v_endDateTime is null,now(),from_unixtime(p_endTmpstmp/1000));
 
                set v_startTmpstmp = unix_timestamp(v_startDateTime)  * 1000;
                set v_endTmpstmp = unix_timestamp(v_endDateTime)  * 1000;
                
                IF DATEDIFF(v_endDateTime,v_startDateTime) > 29
                THEN
    				SET v_interval = 86400; 
    			ELSEIF DATEDIFF(v_endDateTime,v_startDateTime) > 1
                THEN
    				SET v_interval = 3600; 
                ELSE
                	SET v_interval = 60; 
                END IF;
                     
      			SET v_startTime = v_startDateTime;
    			SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
                     
      			 WHILE v_startTime < v_endDateTime 
      			 DO      
    				 INSERT INTO temp_Intervals (starttime, endtime)
    				 VALUES (v_startTime, v_endTime);
                     
    				SET v_startTime := (DATE_ADD(v_startTime, INTERVAL v_interval second));
    				SET v_endTime := (DATE_ADD(v_endTime, INTERVAL v_interval second));
            
    			END WHILE;
     END IF;                   
                IF p_datetype = 2 THEN
    DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    CREATE TEMPORARY TABLE temp_Intervals (
        starttime DATETIME,
        endtime   DATETIME
    );          

    SET v_startDateTime := IF(p_startTmpstmp IS NULL, DATE_SUB(NOW(), INTERVAL 1 DAY), FROM_UNIXTIME(p_startTmpstmp/1000));
    SET v_endDateTime := IF(p_endTmpstmp IS NULL, NOW(), FROM_UNIXTIME(p_endTmpstmp/1000));

    SET v_startTmpstmp = UNIX_TIMESTAMP(v_startDateTime) * 1000;
    SET v_endTmpstmp = UNIX_TIMESTAMP(v_endDateTime) * 1000;

    SET v_interval = 3600; 

    SET v_startTime = v_startDateTime;
    SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
    
    WHILE v_startTime < v_endDateTime DO      
        INSERT INTO temp_Intervals (starttime, endtime)
        VALUES (v_startTime, v_endTime);

        SET v_startTime = DATE_ADD(v_startTime, INTERVAL v_interval SECOND);
        SET v_endTime = DATE_ADD(v_endTime, INTERVAL v_interval SECOND);
    END WHILE;          

END IF;

        
           IF p_datetype = 3 THEN
    DROP TEMPORARY TABLE IF EXISTS temp_Intervals;
    CREATE TEMPORARY TABLE temp_Intervals (
        starttime DATETIME,
        endtime   DATETIME
    );          

    SET v_startDateTime := IF(p_startTmpstmp IS NULL, DATE_SUB(NOW(), INTERVAL 1 DAY), FROM_UNIXTIME(p_startTmpstmp/1000));
    SET v_endDateTime := IF(p_endTmpstmp IS NULL, NOW(), FROM_UNIXTIME(p_endTmpstmp/1000));

    SET v_startTmpstmp = UNIX_TIMESTAMP(v_startDateTime) * 1000;
    SET v_endTmpstmp = UNIX_TIMESTAMP(v_endDateTime) * 1000;

    SET v_interval = 86400; 

    SET v_startTime = v_startDateTime;
    SET v_endTime = DATE_ADD(v_startTime, INTERVAL (v_interval-1) second);
    
    WHILE v_startTime < v_endDateTime DO      
        INSERT INTO temp_Intervals (starttime, endtime)
        VALUES (v_startTime, v_endTime);

        SET v_startTime = DATE_ADD(v_startTime, INTERVAL v_interval SECOND);
        SET v_endTime = DATE_ADD(v_endTime, INTERVAL v_interval SECOND);
    END WHILE;          

END IF;
   				DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory;
       			CREATE TEMPORARY TABLE temp_WhatAppHistory
       			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime  
       			FROM 	tb_WhatsappHistory H 
       			WHERE 	H.domainId = p_domainId
       			AND  	H.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
       			GROUP BY H.sessionStartTime;   
                 
       			DROP TEMPORARY TABLE IF EXISTS temp_Intervals_1;	    
       			CREATE TEMPORARY TABLE temp_Intervals_1
       			SELECT t_I.endtime 	AS `Time`
       				,	count(1)	AS `NoofreceivedWhatsappCount`
       			FROM temp_Intervals t_I
       			JOIN temp_WhatAppHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
       			GROUP BY t_I.endtime;
           
         			SELECT  (t_I.endtime) 								AS `Time`
       				,	IFNULL(t.NoofreceivedWhatsappCount,0)	    		AS NoofreceivedcurrentWhatsappCount
    				    FROM 		temp_Intervals t_I 
         			LEFT JOIN   temp_Intervals_1 t ON t.time = t_I.endtime;                       
                        
  
                   DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory1;
        			CREATE TEMPORARY TABLE temp_WhatsappHistory1
        			SELECT FROM_UNIXTIME(H.sessionStartTime/1000) AS sessionStartTime
        			FROM 	tb_WhatsappHistory H 
        			WHERE 	H.domainId = p_domainId
        			AND  	H.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        			GROUP BY H.sessionStartTime;   
                   
       			 DROP TEMPORARY TABLE IF EXISTS temp_Intervals_2;	    
        			CREATE TEMPORARY TABLE temp_Intervals_2
        			SELECT t_I.endtime 	AS `Time`
        				,	count(1)	AS `NoofreceivedWhatsappCount`
        			FROM temp_Intervals t_I
        			JOIN temp_WhatAppHistory H  ON H.sessionStartTime BETWEEN t_I.starttime AND t_I.endtime
        			GROUP BY t_I.endtime;
            
          			SELECT  (t_I.endtime) 						        AS `Time`
        				,	IFNULL(t.NoofreceivedWhatsappCount,0)	            AS NoofreceivedpastWhatsappCount
        			    FROM 		temp_Intervals t_I 
          			LEFT JOIN   temp_Intervals_2 t ON t.time = t_I.endtime;
                        
        
        
            DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
 		    DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                               	
                       		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                   		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                   		(    DispositionId 			INT
                   			,DispositionStatus 		VARCHAR(100)
                   			,DispositionCategory	TINYINT
                   		);             
 							
 						INSERT INTO temp_AvailableDisposition 
                   		SELECT 	did 			DispositionId
                   			,	dispositionName	DispositionStatus
                   			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                   				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                   				WHEN dispositionName = 'Discarded'     THEN 4
            					    WHEN dispositionName = 'Resolved'      THEN 5
                   				END 			DispositionCategory
                   		FROM 	disposition_status
                   		WHERE 	domainId	= p_domainId;

		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
            	CREATE TEMPORARY TABLE temp_AllagentId
            	SELECT 	UserID,UserName 
                FROM 	tb_User 
                WHERE 	domainId 	= p_domainId;  

               
                     
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
			DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory; 
			CREATE TEMPORARY TABLE temp_WhatAppHistory AS
		    SELECT 	CH.sessionStartTime		
  				,	CH.WhatsappHistoryId        
  				,	CDH.WhatsappDurationHistoryId
  				,	CDH.AgentId
  				,	CH.Istransferred
  				,	CH.dispositionId
  			    ,   CH.IsInBound
  				,	(CH.sessionEndTime - CH.sessionStartTime)	                         AS WhatAppDuration
  				,   CASE WHEN  (FROM_UNIXTIME(CH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 1 ELSE 0 END AS  missedWhatApp
  				,	CH.customerNumber
  				,	CH.afterwhatsappWorkTime
  			
  				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                AS discarded
  				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                AS firstWhatAppResolution 
				, CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		     	 AS HandledTime
				, CH.repliedDate - CH.createdAt				  				    	     AS responseTime
				, CH.SentimentalScore
                ,'0'                                                                     AS IsAbandoned     
                ,CASE WHEN CDH.Duration	is not null then Duration else '-' end			 AS chatduration
                ,CH.domainId 
			FROM 		tb_WhatsappHistory 			CH
			LEFT JOIN 	tb_WhatsappDurationHistory	CDH		ON 	CH.WhatsappHistoryId 	= CDH.WhatsappHistoryId
			LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
			LEFT JOIN tb_User					U			ON 	U.UserID				= CDH.AgentId
			LEFT JOIN temp_agentIDs 			t_A 		ON 	U.UserID 			    = t_A.agentId   
			WHERE 	CH.domainId 			= p_domainId 		
		 	AND 	CH.IsInBound			= 1
			AND 	CH.sessionStartTime 	BETWEEN v_startDateTime AND v_endDateTime;


                        
                    DROP TEMPORARY TABLE IF EXISTS temp_whatappHistory_calc; 
  					CREATE TEMPORARY TABLE temp_whatappHistory_calc AS 	     
					SELECT 	
						t_SH.sessionStartTime,
						t_SH.WhatsappHistoryId,
						t_SH.WhatsappDurationHistoryId,
						t_SH.AgentId,
						t_SH.responseTime,
						t_SH.missedWhatApp,
						t_SH.IsInBound,
						t_SH.Istransferred,
						t_SH.dispositionId,
						t_SH.WhatAppDuration,
						SUM(t_SH.afterwhatsappWorkTime) 														AS afterwhatsappWorkTime,
					
						t_SH.SentimentalScore,									
						COUNT(t_SH.AgentId) 																	AS InteractionwithAgent,
						COUNT(DISTINCT t_SH.customerNumber)														AS InteractionWithCustomer,
						t_SH.discarded 																			AS discardedWhatApp,
						t_SH.IsAbandoned,									
						SUM(t_SH.chatduration) 																	AS totalChatduration,
						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE '-' END   AS avgChatduration,
                        t_SH.domainId 
					FROM temp_WhatAppHistory t_SH
					GROUP BY  t_SH.sessionStartTime,t_SH.WhatsappHistoryId,t_SH.WhatsappDurationHistoryId,t_SH.AgentId,t_SH.missedWhatApp,t_SH.IsInBound,
						t_SH.Istransferred,t_SH.dispositionId,t_SH.WhatAppDuration,t_SH.SentimentalScore,t_SH.responseTime,t_SH.discarded,t_SH.IsAbandoned,t_SH.domainId ;
                        
         			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;           
                    
  IF    p_columnname = 'Recieved Chat'
               THEN
           		
 				SELECT COUNT(SH.WhatsappHistoryId) AS RecievedChat 
 				INTO v1_count_currentdata 
 				FROM temp_whatappHistory_calc SH
 				LEFT JOIN temp_AvailableDisposition t_D ON SH.dispositionId = t_D.DispositionId
 				WHERE SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
 				AND SH.domainId = p_domainId 
                 LIMIT 1;
                   
           		
 				SELECT COUNT(SH.WhatsappHistoryId) AS RecievedChat 
 				INTO v2_count_pastdata 
 				FROM temp_whatappHistory_calc SH
 				LEFT JOIN temp_AvailableDisposition t_D ON SH.dispositionId = t_D.DispositionId
 				WHERE SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
 				AND SH.domainId = p_domainId 
                 LIMIT 1;   
                                 ELSEIF         p_columnname = 'Responsed SMS'
               THEN
           		
           		SELECT 	 SUM(SH.responseTime)		        AS ResponsedSMS		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 SUM(SH.responseTime)	           AS ResponsedSMS
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;
                            
 ELSEIF         p_columnname = 'Abandoned Chat'
               THEN
           		
           		SELECT 	 SUM(SH.IsAbandoned)		        AS abandonedChat		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 SUM(SH.IsAbandoned)             AS abandonedChat
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                           
  
   ELSEIF         p_columnname = 'Missed Chat'
               THEN
           		
           		SELECT 	SUM(SH.missedWhatApp)			        AS missedSChat		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 SUM(SH.missedWhatApp)	             AS missedSChat
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;  
                            
       ELSEIF         p_columnname = 'Transferred Chat'
               THEN
           		
           		SELECT 	SUM(SH.Istransferred)				        AS transferredChat		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 SUM(SH.Istransferred)		               AS transferredChat
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                          
                            
       ELSEIF         p_columnname = 'Total Chat Duration'
               THEN
           		
           		SELECT 	sum(SH.totalChatduration)					        AS TotalChatDuration		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 sum(SH.totalChatduration)			               AS TotalChatDuration
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                               
                            
                            
       ELSEIF         p_columnname = 'Average Chat Duration'
               THEN
           		
           		SELECT 	sum(SH.avgChatduration) / COUNT(1)						         AS AverageChatDuration		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 sum(SH.avgChatduration) / COUNT(1)				               AS AverageChatDuration
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                                 
                            
        ELSEIF         p_columnname = 'Average Chat Duration'
               THEN
           		
           		SELECT 	sum(SH.avgChatduration) / COUNT(1)						         AS AverageChatDuration		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	 sum(SH.avgChatduration) / COUNT(1)				               AS AverageChatDuration
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                           
             
        ELSEIF         p_columnname = 'Interaction With Customer'
               THEN
           		
           		SELECT 	SUM(SH.InteractionWithCustomer)						         AS InteractionWithCustomer		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	SUM(SH.InteractionWithCustomer)				               AS InteractionWithCustomer
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                  
             
         ELSEIF         p_columnname = 'Interaction With Customer'
               THEN
           		
           		SELECT 	SUM(SH.InteractionwithAgent)						         AS InteractionwithAgent		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	SUM(SH.InteractionwithAgent)				               AS InteractionwithAgent
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;                    
                   
         ELSEIF         p_columnname = 'Total Interaction'
               THEN
           		
           		SELECT 	SUM(SH.InteractionWithCustomer) + SUM(SH.InteractionwithAgent)						         AS totalInteraction		                    		
           		INTO 	v1_count_currentdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1; 
                    
           		
           		SELECT 	SUM(SH.InteractionWithCustomer) + SUM(SH.InteractionwithAgent)				               AS totalInteraction
           		INTO 	v2_count_pastdata 
 				FROM 	temp_whatappHistory_calc SH
                 LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
           		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
           		AND 	SH.domainId	= p_domainId
 				LIMIT 1;     
              
                                	END IF;        
        		SELECT 	v1_count_currentdata																currentdata
           		,	v2_count_pastdata																		pastdata
           		,	(v1_count_currentdata - v2_count_pastdata) 												dataDifference 
       			,	(v1_count_currentdata - v2_count_pastdata) /(v1_count_currentdata) *100 				Percentage;	          
       END ;;
