/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_WhatApp_Performances_trendchart111`(	
	p_starttime 	DATETIME
	,p_endtime 		DATETIME
	,p_domainId 		INT
	,p_datetype 		INT 
	,p_columnname 	VARCHAR(155) 
    ,p_agentId		VARCHAR(200) 
)
sp_return: BEGIN

			DECLARE v_startDateTime			DATETIME; 		DECLARE v_endDateTime			DATETIME; 		DECLARE v_datetimeInterval		SMALLINT;		DECLARE v_startDateTimePast		DATETIME;
 			DECLARE v_endDateTimePast		DATETIME;  		DECLARE v_startTimestampPast	BIGINT; 		DECLARE v_endTimestampPast		BIGINT;      	DECLARE v_startTimestamp		BIGINT;
 			DECLARE v_endTimestamp			BIGINT;         DECLARE v_currentCount			INT; 			DECLARE v_pastCount				INT; 			DECLARE v_tot_cur_Whatsapp		INT;
 			DECLARE v_tot_past_Whatsapp		INT;	        DECLARE p_timezone				Text;			DECLARE v_tot_cur_chat			INT; 			DECLARE v_tot_past_chat			INT;
            
            DECLARE v_curDate				DATETIME DEFAULT NOW();	
            
			set p_timezone = '+05:30';
            
            IF p_datetype = 1 THEN 	 
				SET v_startDateTime = CAST(v_curDate AS DATE);  							SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);  
			END IF;
            
			IF p_datetype = 2 THEN 
				SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 	SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY);		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY); 
             END IF;
             
            IF p_datetype = 3 THEN 
				SET v_startDateTime = p_starttime;
                SET v_endDateTime 	= p_endtime; 
                SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
			END IF;
			IF p_datetype = 4 THEN 
				SET v_startDateTime = p_starttime; 
				SET v_endDateTime 	= p_endtime; 
				SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
				SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
			END IF;
            
            DROP TEMPORARY TABLE IF EXISTS tmp_wtsapprefresult;		CREATE TEMPORARY TABLE tmp_wtsapprefresult(reportAge VARCHAR(20) ,startDateTime DATETIME ,endDateTime DATETIME, wtsapCount INT );  
			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	    CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
            
            IF p_agentId IS NOT NULL THEN
				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT); CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
			ELSE
				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                CREATE TEMPORARY TABLE temp_agentIds
				select  UserID as agentId from tb_User where domainId = p_domainId; 
			END IF;
            
							
			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
			CREATE TEMPORARY TABLE temp_AvailableDisposition 
			(    
				DispositionId 			INT
				,DispositionStatus 		VARCHAR(100)
				,DispositionCategory	TINYINT
			);             
     							
			INSERT INTO temp_AvailableDisposition 
			SELECT 	did 			DispositionId
				,	dispositionName	DispositionStatus
				,	CASE WHEN dispositionName = 'Opened'	THEN 2
					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
					WHEN dispositionName = 'Discarded'     THEN 4
					WHEN dispositionName = 'Resolved'      THEN 5 END 			                    DispositionCategory
			FROM 	disposition_status
			WHERE 	domainId	= p_domainId;
    
			IF p_datetype IN (1,2) THEN 
				DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
					CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
					WITH RECURSIVE CTE_TIMINGS AS 
					(
						SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
						UNION ALL
						SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
						FROM 	CTE_TIMINGS
						WHERE 	endDateTime < v_endDateTime
					)
					SELECT * FROM CTE_TIMINGS;	                
			ELSEIF p_datetype IN (3,4) THEN 
				DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
					CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
					WITH recursive CTE_TIMINGS AS 
					(
						SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND) AS endDateTime
						UNION ALL
						SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
						FROM 	CTE_TIMINGS
						WHERE 	startDateTime < v_endDateTime
					)
					SELECT * FROM CTE_TIMINGS;	
			END IF;  

			ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, 
									ADD COLUMN endTimestamp		BIGINT;

			UPDATE tmp_timings
			SET	startTimestamp 	= unix_timestamp(convert_tz(startDateTime,p_timezone,'+00:00')) * 1000,
				endTimestamp 	= unix_timestamp(convert_tz(endDateTime,p_timezone,'+00:00')) * 1000;
            
			if p_datetype IN (1,2) then
				SET 	v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
					,	v_endTimestampPast		= unix_timestamp(convert_tz(v_endDateTimePast,p_timezone,'+00:00')) * 1000
					,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000
					, 	v_endTimestamp			= unix_timestamp(convert_tz(v_endDateTime,p_timezone,'+00:00')) * 1000 ;
			End if;
			if  p_datetype IN (3,4) then
				SET 	v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
					,	v_endTimestampPast		= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 
					,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000 
					, 	v_endTimestamp			= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTime,INTERVAL 1439 MINUTE),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 ; 
			End if;
                    
				DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappDurationHistory;	
				CREATE TEMPORARY TABLE tmp_WhatsappDurationHistory
				SELECT 	WH.WhatsappHistoryId
					,	WDH.WhatsappDurationHistoryId
					,	WH.sessionStartTime
					,	WDH.IsMissed
					,	WH.dispositionId        
					,	WDH.Duration
                    ,	WDH.dialDuration									AS responseTime
                    ,	(WDH.Duration/1000 + WH.afterwhatsappWorkTime)		AS chatHandlingTime
                    , 	WH.afterwhatsappWorkTime							AS afterwhatsappWorkTime
				FROM  tb_WhatsappHistory                	WH
				JOIN  tb_WhatsappDurationHistory       		WDH			ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId     
				WHERE 	WH.domainId 		= p_domainId
				AND 	WH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
				AND 	WH.IsInBound		= 1
                AND		WDH.IsBot			= 0
                AND		(WDH.AgentId in (select agentId from temp_agentIDs) or ifnull(p_agentId,'')='');
                
                
				DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappHistory;	
				CREATE TEMPORARY TABLE tmp_WhatsappHistory
				SELECT 	
						WDH.WhatsappHistoryId 
					,   WDH.WhatsappDurationHistoryId
					, 	WDH.sessionStartTime
                    ,	WDH.responseTime
                    ,	WDH.chatHandlingTime
                    ,	WDH.afterwhatsappWorkTime
				FROM 	tmp_WhatsappDurationHistory WDH;  
                
				select count(Distinct WhatsappDurationHistoryId) into v_tot_cur_Whatsapp from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;          
				select count(Distinct WhatsappDurationHistoryId) into v_tot_past_Whatsapp from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;  
                
			if p_columnName = 'Average Response Time' then
				insert into tmp_wtsapprefresult
				SELECT 	'Current'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					
                    ,	COUNT(case when WH.responseTime is not null and WH.responseTime>0 then WH.responseTime end) AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
				GROUP BY t_T.startDateTime, t_T.endDateTime;
                
				insert into tmp_wtsapprefresult
				SELECT 	'Past'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					
                    ,	COUNT(case when WH.responseTime is not null and WH.responseTime>0 then WH.responseTime end) AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
				GROUP BY t_T.startDateTime, t_T.endDateTime;
            End if;
            
            if p_columnName = 'Average Handled Time' then
				insert into tmp_wtsapprefresult
				SELECT 	'Current'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	SUM(chatHandlingTime) AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
				GROUP BY t_T.startDateTime, t_T.endDateTime;
                
				insert into tmp_wtsapprefresult
				SELECT 	'Past'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					,	SUM(chatHandlingTime) AS wtsapCount 
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
				GROUP BY t_T.startDateTime, t_T.endDateTime;
            End if;
            
            if p_columnName = 'Total ACW Time' then
				insert into tmp_wtsapprefresult
				SELECT 	'Current'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	SUM(afterwhatsappWorkTime)*1000 AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
				GROUP BY t_T.startDateTime, t_T.endDateTime;
                
				insert into tmp_wtsapprefresult
				SELECT 	'Past'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					,	SUM(afterwhatsappWorkTime)*1000 AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
				GROUP BY t_T.startDateTime, t_T.endDateTime;
            End if;
            
  
                 SELECT * FROM tmp_wtsapprefresult WHERE reportAge = 'Current';    
                 SELECT * FROM tmp_wtsapprefresult WHERE reportAge = 'Past';
                   
                 
			SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN wtsapCount ELSE 0 END)/IF(v_tot_cur_Whatsapp=0,1,v_tot_cur_Whatsapp)	AS currentCount, 
					SUM(CASE WHEN reportAge = 'Past' THEN wtsapCount ELSE 0 END)/IF(v_tot_past_Whatsapp=0,1,v_tot_past_Whatsapp)	AS pastCount
					INTO 	v_currentCount, v_pastCount		
			FROM 	tmp_wtsapprefresult;
					 
					SELECT 	p_columnName    																	AS metric
					,		ifnull(v_currentCount,0)															AS currentTotal
					, 		ifnull(v_pastCount,0)																AS pastTotal
					,	    ifnull((v_currentCount - v_pastCount),0)  											AS totalDifference
                    ,	    case when ifnull(v_pastCount,0)=0 then 100 
 										else ifnull((v_currentCount - v_pastCount) /(IF(v_pastCount=0,100,v_pastCount)) ,0)*100	
                                         End																	AS Percentage;
             
   
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_WhatApp_Service_Level_trendchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_WhatApp_Service_Level_trendchart`(	
 	p_domainId 			INT
 	,p_datetype 		INT                 
 	,p_startDateTime	DATETIME
 	,p_endDateTime		DATETIME
 	,p_columnName    	VARCHAR(200)        
 	,p_agentId 			TEXT
 	
 )
sp_return:BEGIN
     			DECLARE v_startDateTime			DATETIME;
     			DECLARE v_endDateTime			DATETIME;
     			DECLARE v_datetimeInterval		SMALLINT;
     			DECLARE v_startDateTimePast		DATETIME;
     			DECLARE v_endDateTimePast		DATETIME;
     
     			DECLARE v_startTimestampPast	BIGINT;
     			DECLARE v_endTimestampPast		BIGINT;      
     			DECLARE v_startTimestamp		BIGINT;
     			DECLARE v_endTimestamp			BIGINT;
     			DECLARE v_curDate				DATETIME DEFAULT NOW();	
     			DECLARE v_currentCount			INT;
     			DECLARE v_pastCount				INT;
     			DECLARE v_tot_cur_chat			INT;
     			DECLARE v_tot_past_chat			INT;
 				DECLARE p_timezone 				text;
                  
 				set p_timezone = '+05:30';
                                 
         				DROP TEMPORARY TABLE IF EXISTS tmp_result;
         				CREATE TEMPORARY TABLE tmp_result(
         					reportAge			VARCHAR(20)
         					,startDateTime		DATETIME
         					,endDateTime		DATETIME
         					,wtsapCount			INT
         				);    
                              
                              	IF p_datetype = 1 
                                  THEN 	
                              		SET v_startDateTime = CAST(v_curDate AS DATE); 
                              		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
                              
                              		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
                              		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
                              	END IF;
                              	IF p_datetype = 2 
                                  THEN 
                              		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
  									SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
                              
                              		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
                              		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY); 
                                                                         
                              	END IF;
                              	IF p_datetype = 3 
                                  THEN 
                              		
                                     
                                     SET v_startDateTime = p_startDateTime; 
      								SET v_endDateTime 	= p_endDateTime; 
                                      
      								SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                                      
                              		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                              		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                                     
                              	END IF;
                              	IF p_datetype = 4 
                                  THEN 
                              		SET v_startDateTime = p_startDateTime; 
      								SET v_endDateTime 	= p_endDateTime; 
                                      
      								SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                                      
                              		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                              		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
  
                              	END IF;
                                  
                           IF p_agentId IS NOT NULL 
                                   THEN
                               		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
                               		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
                                   ELSE
                               		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                                      CREATE TEMPORARY TABLE temp_agentIds
                             		 select  UserID as agentId from tb_User where domainId = p_domainId; 
                          		END IF;
                                  
                             
                                  
                                  IF p_datetype IN (1,2)
                                  THEN 
  								DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
   								CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   								WITH RECURSIVE CTE_TIMINGS AS (
   								SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
   								UNION ALL
   								SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
   								FROM 	CTE_TIMINGS
   								WHERE 	endDateTime < v_endDateTime
                              		)
                              		SELECT * FROM CTE_TIMINGS;	
   								ELSEIF p_datetype IN (3,4)
                                  THEN 
  								DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
   								CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
   								WITH recursive CTE_TIMINGS AS (
   								SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND) AS endDateTime
   								UNION ALL
   								SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
   								FROM 	CTE_TIMINGS
   								WHERE 	startDateTime < v_endDateTime
                              		)
                              		SELECT * FROM CTE_TIMINGS;	
   								END IF;  
                                  
                                  ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, 
      													ADD COLUMN endTimestamp		BIGINT;
                                  
                                  UPDATE tmp_timings
                                  SET		
      									
      									startTimestamp = unix_timestamp(convert_tz(startDateTime,p_timezone,'+00:00')) * 1000,
      									endTimestamp = unix_timestamp(convert_tz(endDateTime,p_timezone,'+00:00')) * 1000;
                                  
                                  
                                 if p_datetype IN (1,2) then
  								SET v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
      							,	v_endTimestampPast		= unix_timestamp(convert_tz(v_endDateTimePast,p_timezone,'+00:00')) * 1000  
      							,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000  
      							, 	v_endTimestamp			= unix_timestamp(convert_tz(v_endDateTime,p_timezone,'+00:00')) * 1000 ; 
                                 End if;
                                 if  p_datetype IN (3,4) then
                              	SET v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
      							,	v_endTimestampPast		= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000  
      							,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000  
      							, 	v_endTimestamp			= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTime,INTERVAL 1439 MINUTE),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 ; 
                                 End if;
  
  							DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappDurationHistory;	
                             	CREATE TEMPORARY TABLE tmp_WhatsappDurationHistory
                             	SELECT 	WH.WhatsappHistoryId
     								,	WDH.WhatsappDurationHistoryId
 									,	WH.sessionStartTime
 									,	WDH.IsMissed
 									,	WH.dispositionId        
 									,	WDH.dialDuration
 									,   WDH.Duration
 									,   WH.sessionStartTime > 0													AS answered
         							,   CASE WHEN WH.sessionStartTime>0 BETWEEN 0 AND 30 THEN 1 ELSE 0 END  	AS Total
         							,   CASE WHEN WH.IsInBound =1 THEN 1 ELSE 0 END                       		AS incomingChats
                				FROM 	tb_WhatsappHistory 				WH
                    			JOIN 	tb_WhatsappDurationHistory	  	WDH		ON 	WH.WhatsappHistoryId 	= WDH.WhatsappHistoryId        
           					
       						WHERE 	WH.domainId 			= p_domainId
  							AND 	IFNULL(WDH.IsBot,0) 	= 0
       						AND 	WH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
                             AND		(WDH.AgentId in (select agentId from temp_agentIds) or ifnull(p_agentId,'')='');
           					
                              
         					DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappDurationHistory_cal;	
         					CREATE TEMPORARY TABLE tmp_WhatsappDurationHistory_cal
         					select 
         						incomingChats, WhatsappHistoryId,WhatsappDurationHistoryId, sessionStartTime, IsMissed, dispositionId,
         						dialDuration, Duration,  answered as answeredDuration, 
         						sum(Total/incomingChats)*100        	as SLAachieved ,
         						100 - sum((Total/incomingChats)*100)  	as SLABleached
         					FROM tmp_WhatsappDurationHistory
         					GROUP BY incomingChats, WhatsappHistoryId,WhatsappDurationHistoryId, sessionStartTime, IsMissed, dispositionId,
         					dialDuration, Duration,  answered;
         
         					DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappHistory;	
         					CREATE TEMPORARY TABLE tmp_WhatsappHistory
         					SELECT 	
         							CDH.WhatsappHistoryId 
     							,   CDH.WhatsappDurationHistoryId
         						, 	CDH.sessionStartTime
         					FROM 	tmp_WhatsappDurationHistory CDH;  
                            
        				select count(Distinct WhatsappDurationHistoryId) into v_tot_cur_chat from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;          
        				select count(Distinct WhatsappDurationHistoryId) into v_tot_past_chat from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;          
        
         					ALTER TABLE tmp_WhatsappHistory ADD IsMissed 		TINYINT default 0;
         					ALTER TABLE tmp_WhatsappHistory ADD IsAnswered 		TINYINT default 0;
         					ALTER TABLE tmp_WhatsappHistory ADD IsUnAnswered 	TINYINT default 0;
         					ALTER TABLE tmp_WhatsappHistory ADD TotalSLA		INT default 0;
         					ALTER TABLE tmp_WhatsappHistory ADD SLAacheived		INT default 0;
         					ALTER TABLE tmp_WhatsappHistory ADD SLAbleached		INT default 0;
                              
         					CREATE INDEX ix_tmp_CallHistory ON tmp_WhatsappHistory (WhatsappHistoryId);
         					CREATE INDEX ix_tmp_CallDurationHistory ON tmp_WhatsappDurationHistory (WhatsappHistoryId);
                  
         					UPDATE 		tmp_WhatsappHistory				CH
         					JOIN 		tmp_WhatsappDurationHistory_cal	CDH	ON CH.WhatsappHistoryId	= CDH.WhatsappHistoryId   AND CH.WhatsappDurationHistoryId = CDH.WhatsappDurationHistoryId
         					
         					SET 	CH.IsMissed		= CASE WHEN CDH.IsMissed = 1 THEN 1 ELSE 0 	    END
         						,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0	    END
         						, 	CH.TotalSLA     = CASE WHEN CDH.answeredDuration BETWEEN 0 AND 30 THEN 1 ELSE 0 END 
         						,	CH.SLAacheived  = CDH.SLAachieved
         						,	CH.SLAbleached  = CDH.SLAbleached;
                   
                                 
                                 
                                 
                               IF p_columnName = 'Missed Chats'
                             	THEN
                             		INSERT INTO tmp_result
                              		SELECT 	'Current'			AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                              			,	IFNULL(SUM(CH.IsMissed),0)	AS wtsapCount
                              		FROM 	tmp_timings			t_T	
                              		LEFT JOIN tmp_WhatsappHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                              		GROUP BY t_T.startDateTime, t_T.endDateTime;
                                     
                                     INSERT INTO tmp_result
                              		SELECT 	'Past'					    AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                              			,	IFNULL(SUM(CH.IsMissed),0)	AS wtsapCount     
                              		FROM 	tmp_timings		t_T	
                              		LEFT JOIN 	tmp_WhatsappHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                              		GROUP BY t_T.startDateTime, t_T.endDateTime; 
                                    
                                  ELSEIF p_columnName = 'SLA Achieved (%)'
                                   THEN
                              		INSERT INTO tmp_result
                               		SELECT 	'Current'								  AS reportAge
                               			,	t_T.startDateTime 
                               			,	t_T.endDateTime
                                        ,   IFNULL(SUM(CH.SLAacheived) / count(WhatsappDurationHistoryId), 0) AS wtsapCount        
                               		FROM 	tmp_timings			t_T	
                               		LEFT JOIN tmp_WhatsappHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                               		GROUP BY t_T.startDateTime, t_T.endDateTime,WhatsappDurationHistoryId; 
         
         							INSERT INTO tmp_result
                               		SELECT 	'Past'					        				AS reportAge
                               			,	t_T.startDateTime 
                               			,	t_T.endDateTime
            							,   IFNULL(SUM(CH.SLAacheived) / count(WhatsappDurationHistoryId), 0) AS wtsapCount 
                               		FROM 	tmp_timings		t_T	
                               		LEFT JOIN 	tmp_WhatsappHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                               		GROUP BY t_T.startDateTime, t_T.endDateTime,WhatsappDurationHistoryId; 
                                    
                                     ELSEIF p_columnName = 'SLA Breached (%)'
                                   THEN
                              		INSERT INTO tmp_result
                               		SELECT 	'Current'								  AS reportAge
                               			,	t_T.startDateTime 
                               			,	t_T.endDateTime
                                        ,   IFNULL(abs(CH.SLAbleached),0)            AS wtsapCount   
                                        
                               		FROM 	tmp_timings			t_T	
                               		LEFT JOIN tmp_WhatsappHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                                     
                               		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached; 
                                      
                                      INSERT INTO tmp_result
                               		SELECT 	'Past'					        									AS reportAge
                               			,	t_T.startDateTime 
                               			,	t_T.endDateTime
                                          ,   IFNULL(abs(CH.SLAbleached),0)                                  AS wtsapCount   
                                        
                               		FROM 	tmp_timings		t_T	
                               		LEFT JOIN 	tmp_WhatsappHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                               		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                                     
                               		GROUP BY t_T.startDateTime, t_T.endDateTime,CH.SLAbleached;
                                    
                           ELSEIF p_columnName = 'Total'
                             	THEN
                             		INSERT INTO tmp_result
                              		SELECT 	'Current'					AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                              			,	IFNULL(SUM(TotalSLA),0)	    AS wtsapCount
                              		FROM 	tmp_timings			t_T	
                              		LEFT JOIN tmp_WhatsappHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
                              		GROUP BY t_T.startDateTime, t_T.endDateTime;
                                     
                                     INSERT INTO tmp_result
                              		SELECT 	'Past'						AS reportAge
                              			,	t_T.startDateTime 
                              			,	t_T.endDateTime
                              			,	IFNULL(SUM(TotalSLA),0)	    AS wtsapCount     
                              		FROM 	tmp_timings		t_T	
                              		LEFT JOIN 	tmp_WhatsappHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
                              		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
                              		GROUP BY t_T.startDateTime, t_T.endDateTime;
                              
                              
                               END IF;
                              
                                SELECT  *
                                 FROM 	tmp_result
                                 WHERE 	reportAge = 'Current';    
                                 
                                 SELECT  *
                                 FROM 	tmp_result
                                 WHERE 	reportAge = 'Past';
                                 
  							SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN wtsapCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_cur_chat=0,1,v_tot_cur_chat) else 1 end)	AS currentCount, 
  									SUM(CASE WHEN reportAge = 'Past' 	THEN wtsapCount ELSE 0 END)/(case when p_columnName in ('SLA Breached (%)','SLA Achieved (%)') then IF(v_tot_past_chat=0,1,v_tot_past_chat) else 1 end)	AS pastCount
  							INTO 	v_currentCount, v_pastCount		
  							FROM 	tmp_result;
                              
                              if p_columnName = 'SLA Breached (%)' then
  								select sum(SLAbleached)/count(Distinct WhatsappDurationHistoryId) into v_currentCount from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;
                                  select sum(SLAbleached)/count(Distinct WhatsappDurationHistoryId) into v_pastCount from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;   
                                  
                                  if IFNULL(v_currentCount,0)=0 then set v_currentCount = 0; end if;
                                  if IFNULL(v_pastCount,0)=0 then set v_pastCount = 0; end if;
                                  
                              End if;
                              
                                 
         						SELECT 	p_columnName    																	AS metric
         						,		ifnull(v_currentCount,0)															AS currentTotal
         						, 		ifnull(v_pastCount,0)																AS pastTotal
         						,	    ifnull((v_currentCount - v_pastCount),0)  											AS totalDifference
         						,	    case when ifnull(v_pastCount,0)=0 then 100 
  										else ifnull((v_currentCount - v_pastCount) /(IF(v_pastCount=0,100,v_pastCount)) ,0)*100	
                                          End
  																														AS Percentage;
                                 
                              END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_whatsapp_agent_ACW_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ccaas_whatsapp_agent_ACW_report`(	
 	p_startTmpstmp 		bigint,
   	p_endTmpstmp 		bigint,
   	p_timeZone 			varchar(200),
   	p_domainId 			int,        
   	p_queueIds	 		VARCHAR(250),
   	p_agentIds 			VARCHAR(250),
   	p_offset 			INT,
   	p_Limit 			INT
  )
BEGIN 
   	DECLARE v_offset 		INT;  	
   	DECLARE v_startTmpstmp 	BIGINT;
   	DECLARE v_endTmpstmp 	BIGINT;
   	
   	SET v_offset = p_offset * p_Limit;
     
   	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
   	IF IFNULL(p_endTmpstmp ,0)	= 0 THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  									
   
   
   	DROP TEMPORARY TABLE IF EXISTS temp_agentId;	CREATE TEMPORARY TABLE temp_agentId(agentId BIGINT);
   
  
   	CALL split(p_agentIds,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable;
     
 	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
 	CREATE TEMPORARY TABLE temp_AllagentId
 	select UserID,UserName from tb_User where domainId = p_domainId;   
        
     	DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
     	CREATE TEMPORARY TABLE temp_AvailableDisposition 
   	(    DispositionId 			INT
   		,DispositionStatus 		VARCHAR(100)	
   	); 
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     	INSERT INTO temp_AvailableDisposition     
     	SELECT 	did 			DispositionId
     		,	dispositionName	DispositionStatus 		
     	FROM 	disposition_status
     	WHERE 	domainId	= p_domainId;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       
     	DROP TEMPORARY TABLE IF EXISTS temp_whatsappHistory; 
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     	CREATE TEMPORARY TABLE temp_whatsappHistory AS 	
   	SELECT UNIX_TIMESTAMP(CAST(FROM_UNIXTIME(SH.sessionStartTime/1000) AS DATE))*1000		as SessionDate
 	
				,	U.UserName							as agentName
				,	Duration 	 												        
				,	dialDuration												as responseTime
				
				,	SH.afterwhatsappWorkTime			as ACW
     	FROM 	tb_WhatsappHistory 			SH
  	LEFT JOIN 	tb_WhatsappDurationHistory	SDH	ON SH.WhatsappHistoryId = SDH.whatsappHistoryId
   	LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId		= t_D.DispositionId
  	LEFT JOIN 	temp_AllagentId				U	ON U.UserID				= SDH.AgentId
  	LEFT JOIN 	temp_agentId 				t_A ON U.UserID 			= t_A.agentId       
  	WHERE 	SH.domainId 		= p_domainId 		
  	AND 	SH.sessionStartTime BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND		SH.IsInBound		= 1	
 
  	AND 	(IFNULL(p_agentIds,'')='' OR (IFNULL(p_agentIds,'') <> '' AND t_A.agentId IS NOT NULL));
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
       
  	DROP TEMPORARY TABLE IF EXISTS temp_whatsappHistory_1;   	
     	CREATE TEMPORARY TABLE temp_whatsappHistory_1 AS 	
       SELECT SessionDate						as `date`
  		 , 	agentName
           ,	COUNT(1)							as totalInteraction
           
           ,	SUM((Duration/1000) + ACW) / COUNT(1) as totalActivewhatsappTime
           ,	round((SUM((Duration/1000) + ACW) / COUNT(1)) * 100) as avgActivewhatsappTime
           
           ,	SUM(ACW)							as totalACW
           ,	SUM(ACW)/COUNT(1)					as averageACW
       FROM 	temp_whatsappHistory
       GROUP BY SessionDate, agentName ;
       
       
       	SELECT * from temp_AllagentId;
 		SELECT * from temp_AvailableDisposition;
 
       
       SELECT COUNT(1) as totalCount
       FROM 	temp_whatsappHistory_1;
      
      IF ((p_Limit IS NOT NULL)AND(p_offset IS NOT NULL)) THEN
      
       SELECT `date` as sessionDate
  		 , 	agentName
           ,	totalInteraction as totalAnsweredChats
           ,	totalActivewhatsappTime as totalActiveChatTime
           ,	avgActivewhatsappTime as averageActiveChatTime
           ,	totalACW
           ,	averageACW
       FROM 	temp_whatsappHistory_1
       LIMIT  v_offset, p_Limit;
       
       ELSE
       
			SELECT `date` as sessionDate
			, 	agentName
           ,	totalInteraction as totalAnsweredChats
           ,	totalActivewhatsappTime as totalActiveChatTime
           ,	avgActivewhatsappTime as averageActiveChatTime
           ,	totalACW
           ,	averageACW
			FROM 	temp_whatsappHistory_1;
            
       END IF;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccaas_WhatsApp_inbound_trendChart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccaas_WhatsApp_inbound_trendChart`(
	p_domainId 		INT,
	p_datetype 		INT, 		
	p_starttime 	DATETIME,
	p_endtime		DATETIME,
	p_columnName    VARCHAR(200) ,
	p_agentId		VARCHAR(200) 
)
sp_return:BEGIN
            
            DECLARE v_startDateTime			DATETIME; 		DECLARE v_endDateTime			DATETIME; 		DECLARE v_datetimeInterval		SMALLINT;		DECLARE v_startDateTimePast		DATETIME;
 			DECLARE v_endDateTimePast		DATETIME;  		DECLARE v_startTimestampPast	BIGINT; 		DECLARE v_endTimestampPast		BIGINT;      	DECLARE v_startTimestamp		BIGINT;
 			DECLARE v_endTimestamp			BIGINT;         DECLARE v_currentCount			INT; 			DECLARE v_pastCount				INT; 			DECLARE v_tot_cur_Whatsapp		INT;
 			DECLARE v_tot_past_Whatsapp		INT;	        DECLARE p_timezone				Text;			DECLARE v_tot_cur_chat			INT; 			DECLARE v_tot_past_chat			INT;
            
            DECLARE v_curDate				DATETIME DEFAULT NOW();	
            
			set p_timezone = '+05:30';
            
			DROP TEMPORARY TABLE IF EXISTS tmp_wtsapresult;
			CREATE TEMPORARY TABLE tmp_wtsapresult(
				reportAge			VARCHAR(20)
				,startDateTime		DATETIME
				,endDateTime		DATETIME
				,wtsapCount			INT
				);  

			IF p_datetype = 1 THEN 	 
				SET v_startDateTime = CAST(v_curDate AS DATE);  							SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);  
			END IF;
            
			IF p_datetype = 2 THEN 
				SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 	SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY);		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY); 
             END IF;
             
            IF p_datetype = 3 THEN 
				SET v_startDateTime = p_starttime;
                SET v_endDateTime 	= p_endtime; 
                SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
                SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
			END IF;
			IF p_datetype = 4 THEN 
				SET v_startDateTime = p_starttime; 
				SET v_endDateTime 	= p_endtime; 
				SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
				SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
				SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
			END IF;
            
			IF p_agentId IS NOT NULL THEN
				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT); CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
			ELSE
				DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
                CREATE TEMPORARY TABLE temp_agentIds
				select  UserID as agentId from tb_User where domainId = p_domainId; 
			END IF;
            
            IF p_datetype IN (1,2) THEN 
				DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
					CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
					WITH RECURSIVE CTE_TIMINGS AS 
					(
						SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
						UNION ALL
						SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
						FROM 	CTE_TIMINGS
						WHERE 	endDateTime < v_endDateTime
					)
					SELECT * FROM CTE_TIMINGS;	                
			ELSEIF p_datetype IN (3,4) THEN 
				DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
					CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
					WITH recursive CTE_TIMINGS AS 
					(
						SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND) AS endDateTime
						UNION ALL
						SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
						FROM 	CTE_TIMINGS
						WHERE 	startDateTime < v_endDateTime
					)
					SELECT * FROM CTE_TIMINGS;	
			END IF;  

			ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, 
									ADD COLUMN endTimestamp		BIGINT;

			UPDATE tmp_timings
			SET	startTimestamp 	= unix_timestamp(convert_tz(startDateTime,p_timezone,'+00:00')) * 1000,
				endTimestamp 	= unix_timestamp(convert_tz(endDateTime,p_timezone,'+00:00')) * 1000;
            
			if p_datetype IN (1,2) then
				SET 	v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
					,	v_endTimestampPast		= unix_timestamp(convert_tz(v_endDateTimePast,p_timezone,'+00:00')) * 1000
					,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000
					, 	v_endTimestamp			= unix_timestamp(convert_tz(v_endDateTime,p_timezone,'+00:00')) * 1000 ;
			End if;
			if  p_datetype IN (3,4) then
				SET 	v_startTimestampPast	= unix_timestamp(convert_tz(v_startDateTimePast,p_timezone,'+00:00')) * 1000 
					,	v_endTimestampPast		= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTimePast,INTERVAL 1439 MINUTE ),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 
					,	v_startTimestamp		= unix_timestamp(convert_tz(v_startDateTime,p_timezone,'+00:00')) * 1000 
					, 	v_endTimestamp			= unix_timestamp(convert_tz((DATE_ADD(DATE_ADD(v_endDateTime,INTERVAL 1439 MINUTE),INTERVAL 59 SECOND)),p_timezone,'+00:00')) * 1000 ; 
			End if;
            
				DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappDurationHistory;	
				CREATE TEMPORARY TABLE tmp_WhatsappDurationHistory
				SELECT 	WH.WhatsappHistoryId
					,	WDH.WhatsappDurationHistoryId
					,	WH.sessionStartTime
					,	WDH.IsMissed
					,	WH.dispositionId        
					,	WDH.Duration
                    ,	WDH.dialDuration					AS responseTime
				FROM  tb_WhatsappHistory                	WH
				JOIN  tb_WhatsappDurationHistory       		WDH			ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId     
				LEFT JOIN  temp_agentIds 		       		t_A			ON t_A.agentId 			= WDH.agentId 	
				WHERE 	WH.domainId 		= p_domainId
				AND 	WH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
				AND 	WH.IsInBound		= 1
                AND		WDH.IsBot			= 0
                AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL)); 
                
				DROP TEMPORARY TABLE IF EXISTS tmp_WhatsappHistory;	
				CREATE TEMPORARY TABLE tmp_WhatsappHistory
				SELECT 	
						WDH.WhatsappHistoryId 
					,   WDH.WhatsappDurationHistoryId
					, 	WDH.sessionStartTime
                    ,	WDH.responseTime
				FROM 	tmp_WhatsappDurationHistory WDH;  
                
				select count(Distinct WhatsappDurationHistoryId) into v_tot_cur_Whatsapp from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestamp and v_endTimestamp;          
				select count(Distinct WhatsappDurationHistoryId) into v_tot_past_Whatsapp from tmp_WhatsappHistory where sessionStartTime BETWEEN v_startTimestampPast and v_endTimestampPast;  
                
			if p_columnName = 'Received Chats' then
				insert into tmp_wtsapresult
				SELECT 	'Current'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					,	IFNULL(COUNT(WH.WhatsappHistoryId),0)	AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
				GROUP BY t_T.startDateTime, t_T.endDateTime;
                
				insert into tmp_wtsapresult
				SELECT 	'Past'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					,	IFNULL(COUNT(WH.WhatsappHistoryId),0)	AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
				GROUP BY t_T.startDateTime, t_T.endDateTime;
            End if;
            
            if p_columnName = 'Responded Chats' then
				insert into tmp_wtsapresult
				SELECT 	'Current'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
                    ,	COUNT(case when WH.responseTime is not null and WH.responseTime>0 then WH.responseTime end) AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
				GROUP BY t_T.startDateTime, t_T.endDateTime;
                
				insert into tmp_wtsapresult
				SELECT 	'Past'		AS reportAge
					,	t_T.startDateTime 
					,	t_T.endDateTime
					,	COUNT(case when WH.responseTime is not null and WH.responseTime>0 then WH.responseTime end) AS wtsapCount
				FROM 	tmp_timings				t_T	
				LEFT JOIN tmp_WhatsappHistory 	WH	ON 	WH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
				WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast
				GROUP BY t_T.startDateTime, t_T.endDateTime;
            End if;
            
                 SELECT * FROM tmp_wtsapresult WHERE reportAge = 'Current';    
                 SELECT * FROM tmp_wtsapresult WHERE reportAge = 'Past';
                   
                 
			SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN wtsapCount ELSE 0 END)/IF(v_tot_cur_Whatsapp=0,1,v_tot_cur_Whatsapp)	AS currentCount, 
					SUM(CASE WHEN reportAge = 'Past' THEN wtsapCount ELSE 0 END)/IF(v_tot_past_Whatsapp=0,1,v_tot_past_Whatsapp)	AS pastCount
					INTO 	v_currentCount, v_pastCount		
			FROM 	tmp_wtsapresult;
					 
					SELECT 	p_columnName    																	AS metric
					,		ifnull(v_currentCount,0)															AS currentTotal
					, 		ifnull(v_pastCount,0)																AS pastTotal
					,	    ifnull((v_currentCount - v_pastCount),0)  											AS totalDifference
                    ,	    case when ifnull(v_pastCount,0)=0 then 100 
 										else ifnull((v_currentCount - v_pastCount) /(IF(v_pastCount=0,100,v_pastCount)) ,0)*100	
                                         End																	AS Percentage;
                    

    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_ccasUpdateAgentAvailabilityForVoice` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_ccasUpdateAgentAvailabilityForVoice`(	
 			p_agentId				BIGINT
 		,	p_domainId				INT	
 		,	p_isAvailableForVoice	TINYINT
  )
BEGIN
  	UPDATE 	tb_User
      SET 	isAvailableForVoice	= IFNULL(p_isAvailableForVoice,isAvailableForVoice)
  		,	updatedAt			= NOW()	
  	WHERE 	UserID				= p_agentId
      AND 	domainId			= p_domainId;
      
      SELECT 1 AS errCode, 'Updated availableForVoice successfully' AS errMsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_agent_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_agent_servicelevel_analysis_metrics_filter`(
                        		p_startTmpstmp 		BIGINT,
                            	p_endTmpstmp 		BIGINT,
                            	p_domainId 			INT,
                            	p_agentId 			TEXT,
        						p_offset 			INT,
        						p_Limit 		    INT	
                        	)
sp_return:begin
               
 				DECLARE v_offset 					INT;	  	
 				DECLARE v_CurrentStartTmpstmp 		BIGINT;
 				DECLARE v_CurrentEndTmpstmp 		BIGINT;
 				DECLARE v_PrevStartTmpstmp 			BIGINT;
 				DECLARE v_PrevEndTmpstmp 			BIGINT; 
 				DECLARE v_TmpstmpInterval			BIGINT;	
 
 				DECLARE v_CurTotalCount 			INT;        
 				DECLARE  v_PrevTotalCount 			INT;                    
 				DECLARE v_DiffTotalPercent 			INT;     
 
 				DECLARE  v_CurTotalSLA               INT; 
 				DECLARE  v_PrevTotalSLA             	INT; 
 				DECLARE  v_DiffTotalSLAPercent      	INT; 
 
 				DECLARE v_PretotalDurationCount         INT;
 				DECLARE v_CurrenttotalDurationCount     INT;  
 
 				DECLARE  v_CurTotalSLA1               INT; 
 				DECLARE  v_PrevTotalSLA1              INT; 
 				DECLARE  v_DiffTotalSLA1Percent       INT; 
 
 				DECLARE  v_CurMissedChats             INT; 
 				DECLARE  v_PrevMissedChats            INT; 
 				DECLARE  v_DiffMissedChatsPercent     INT; 
 
 
 				DECLARE  v_CurSLA1               		INT; 
 				DECLARE  v_PrevSLA1              		INT; 
 				DECLARE  v_DiffSLA1Percent       		INT; 
 
 				DECLARE  v_CurSLA2               		INT; 
 				DECLARE  v_PrevSLA2              		INT; 
 				DECLARE  v_DiffSLA2Percent       		INT;  
 
 				DECLARE  v_CurSLA3               		INT; 
 				DECLARE  v_PrevSLA3              		INT; 
 				DECLARE  v_DiffSLA3Percent       		INT;  
 
 				DECLARE  v_CurSLA4               		INT; 
 				DECLARE  v_PrevSLA4              		INT; 
 				DECLARE  v_DiffSLA4Percent       		INT;  
 
 				DECLARE  v_CurSLA5               		INT; 
 				DECLARE  v_PrevSLA5              		INT; 
 				DECLARE  v_DiffSLA5Percent       		INT;    
 
 				DECLARE  v_CurSLA6               		INT; 
 				DECLARE  v_PrevSLA6              		INT; 
 				DECLARE  v_DiffSLA6Percent       		INT; 
 
 				DECLARE  v_CuransweredSLACount        INT; 
 				DECLARE  v_PrevansweredSLACount       INT; 
 				DECLARE  v_DiffansweredSLAPercent     INT; 
 
 				DECLARE  v_CurabandonedSLACount       INT; 
 				DECLARE  v_PrevabandonedSLACount      INT; 
 				DECLARE  v_DiffabandonedSLAPercent    INT; 
 
 				DECLARE  v_CurSLAbreachedCount        INT; 
 				DECLARE  v_PrevSLAbreachedCount       INT; 
 				DECLARE  v_DiffSLAbreachedPercent     INT; 
 
 
 				DECLARE  v_CurChatTypeCount                 	INT; 
 				DECLARE  v_PrevChatTypeCount               	INT; 
 				DECLARE  v_DiffChatTypePercent             	INT;  
 
 				DECLARE			v_Counts                 	INT;
 				DECLARE			v_agentName                 VARCHAR(250);
 				DECLARE			v_SL1 						INT;
 				DECLARE			v_SL2                       INT;
 				DECLARE			v_SL3                       INT;
 				DECLARE			v_SL4 						INT;
 				DECLARE			v_SL5                       INT;
 				DECLARE			v_SL6                       INT;
 				DECLARE			v_TotalSLA 					INT;
 				DECLARE			v_MissedChats               INT;
 				DECLARE			v_SLAAchieved               INT;
 				DECLARE			v_SLAbreached				INT;     
                 
 				DECLARE			v_currentTotalChatCount		INT;      
 				DECLARE			v_previousTotalChatCount	INT;
                 
 				DECLARE			v_CurrentAnsweredSLACount	INT;      
 				DECLARE			v_PreviousAnsweredSLACount	INT;
                 
 				DECLARE			v_CurrentSLAbreachedCount	INT;      
 				DECLARE			v_PreviousSLAbreachedCount	INT;      
               
 				SET v_offset =  p_Limit * p_offset; 
 
 				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
 				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
 
 				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
 
 				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
 				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
 
 				DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
 				CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
 
 				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
 				DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
 				CREATE TEMPORARY TABLE temp_AllagentId
 				SELECT 	UserID,UserName 
 				FROM 	tb_User 
 				WHERE 	domainId 	= p_domainId; 
 
 				DROP TEMPORARY TABLE IF EXISTS tt_ChatHistory; 
 				CREATE TEMPORARY TABLE tt_ChatHistory AS 	    	
 				SELECT	SH.sessionStartTime 		  
 				,U.UserID                                                                 
 				,U.UserName													      		     
 				,SH.ChatHistoryId 
 				,SDH.answeredDuration                                                                      
 				,SDH.Duration												      		  
 				,SDH.IsAbandoned
 				,SDH.IsMissed
 				,SH.IsInBound                              
 				FROM 	tb_ChatHistory 				SH
 				JOIN 	tb_ChatDurationHistory		SDH		ON SH.chatHistoryId 	= SDH.chatHistoryId     
 				JOIN 	tb_User						U		ON SDH.AgentId			= U.UserID  
 				left JOIN 	temp_agentIDs 			t_A     ON SDH.AgentId		= t_A.agentId  
 				WHERE 	SH.domainId 		= p_domainId	
 				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp   
 				AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
 
 				DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
 				CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
 				SELECT	 CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) 		AS SessionDate
 					,UserID                                                             AS agentID
 					,UserName													      	AS agentName     
 					,ChatHistoryId 
 					,sessionStartTime
 					,answeredDuration                                                    AS chatDuration                 
 					,Duration												      		 AS Duration
 					,IsAbandoned
 					,IsMissed
 					,IsInBound                              
 					FROM 	tt_ChatHistory
 					WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;
                     
 				DROP TEMPORARY TABLE IF EXISTS temp_prev_ChatHistory; 
 				CREATE TEMPORARY TABLE temp_prev_ChatHistory AS 	    	
 				SELECT	 CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) 		AS SessionDate
 					,UserID                                                             AS agentID
 					,UserName													      	AS agentName     
 					,ChatHistoryId 
 					,sessionStartTime
 					,answeredDuration                                                    AS chatDuration                 
 					,Duration												      		 AS Duration
 					,IsAbandoned
 					,IsMissed
 					,IsInBound                              
 					FROM 	tt_ChatHistory
 					WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
            
 				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
 				CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
 				SELECT 	
 				a.SessionDate 				       										                                       AS 'Date'                  
 				,a.agentID
 				,a.agentName																                                  
 				,a.ChatHistoryId 
 				,a.sessionStartTime
 				, SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															 AS Answered
 				,SUM(CASE WHEN a.IsAbandoned=1 Then 'Abandoned' ELSE 0 END)                                                      AS Abandoned
 				,a.IsAbandoned 
 				,SUM(a.Duration)                                                                                                   AS totalDuration
 				,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	 AS  SL1
 				,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         	 AS  SL2
 				,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        		 AS  SL3
 				,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL4
 				,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL5
 				,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL6
 				,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)                AS  TotalSLA
 				,sum(case when a.IsMissed =1 then 1 else 0 end)																	 AS  MissedChats
 				,sum(case when a.IsInBound =1 then 1 else 0 end)																 AS  ReceivedChats
 				FROM temp_ChatHistory a   
 				GROUP BY a.SessionDate,a.agentID,a.agentName,a.chatDuration,a.ChatHistoryId,a.sessionStartTime,a.IsAbandoned  , a.IsMissed,a.IsInBound ;
    
 				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_prev_calc; 
 				CREATE TEMPORARY TABLE temp_chatHistory_prev_calc AS 	     
 				SELECT 	
 				a.SessionDate 				       										                                       AS 'Date'                  
 				,a.agentID
 				,a.agentName																                                  
 				,a.ChatHistoryId 
 				,a.sessionStartTime
 				, SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															 AS Answered
 				,SUM(CASE WHEN a.IsAbandoned=1 Then 'Abandoned' ELSE 0 END)                                                      AS Abandoned
 				,a.IsAbandoned 
 				,SUM(a.Duration)                                                                                                   AS totalDuration
 				,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	 AS  SL1
 				,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         	 AS  SL2
 				,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        		 AS  SL3
 				,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL4
 				,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL5
 				,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL6
 				,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)                AS  TotalSLA
 				,sum(case when a.IsMissed =1 then 1 else 0 end)																	 AS  MissedChats
 				,sum(case when a.IsInBound =1 then 1 else 0 end)																 AS  ReceivedChats
 				FROM temp_prev_ChatHistory a   
 				GROUP BY a.SessionDate,a.agentID,a.agentName,a.chatDuration,a.ChatHistoryId,a.sessionStartTime,a.IsAbandoned  , a.IsMissed,a.IsInBound ;
    
 				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1; 
 				CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS 	     
 				SELECT 	
 				a.Date 				       										                                                       
 				,a.agentID
 				,a.agentName														
 				, case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
 				,a.ChatHistoryId 
 				,a.sessionStartTime
 				, a.totalDuration
 				,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
 				, sum(SL1)																															AS	SL1
 				, sum(SL2)                                                                                                                            AS SL2
 				, sum(SL3)                                                                                                                            AS SL3
 				, sum(SL4)                                                                                                                            AS SL4
 				,sum(SL5)                                                                                                                            AS SL5
 				,sum(SL6)                                                                                                                            AS SL6
 				, a.MissedChats       
 				,  sum(a.ReceivedChats)  as ReceivedChats
 				,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END)                      AS answeredSLA
 				,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END   )                AS abandonedSLA
 				,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1  ELSE (a.MissedChats / (a.TotalSLA + a.MissedChats)) * 100 END  )             AS SLAbreached
 				FROM temp_chatHistory_calc    a 
 				GROUP BY a.Date,a.agentID,a.agentName,a.sessionStartTime,a.ChatHistoryId,a.totalDuration,a.TotalSLA,a.MissedChats,a.Answered,a.Abandoned,a.ReceivedChats ; 
    
 				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_prev_calc1; 
 				CREATE TEMPORARY TABLE temp_chatHistory_prev_calc1 AS 	     
 				SELECT 	
 				a.Date 				       										                                                       
 				,a.agentID
 				,a.agentName														
 				, case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
 				,a.ChatHistoryId 
 				,a.sessionStartTime
 				, a.totalDuration
 				,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
 				, sum(SL1)																															AS	SL1
 				, sum(SL2)                                                                                                                            AS SL2
 				, sum(SL3)                                                                                                                            AS SL3
 				, sum(SL4)                                                                                                                            AS SL4
 				,sum(SL5)                                                                                                                            AS SL5
 				,sum(SL6)                                                                                                                            AS SL6
 				, a.MissedChats       
 				,  sum(a.ReceivedChats)  as ReceivedChats
 				,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END)                      AS answeredSLA
 				,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END   )                AS abandonedSLA
 				,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1  ELSE (a.MissedChats / (a.TotalSLA + a.MissedChats)) * 100 END  )             AS SLAbreached
 				FROM temp_chatHistory_prev_calc    a 
 				GROUP BY a.Date,a.agentID,a.agentName,a.sessionStartTime,a.ChatHistoryId,a.totalDuration,a.TotalSLA,a.MissedChats,a.Answered,a.Abandoned,a.ReceivedChats ; 
                 
           
          
 				 SELECT  COUNT(ChatHistoryId),	SUM(TotalSLA), SUM(MissedChats),sum(ChatType)              														                     				 
                   INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats,v_CurChatTypeCount                           														                      					
                   FROM 	temp_chatHistory_calc1
                   WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
               
               	SELECT 	COUNT(ChatHistoryId),SUM(TotalSLA), SUM(MissedChats),sum(ChatType)                       																								 
               	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats,v_PrevChatTypeCount                                 														 										
               	FROM	temp_chatHistory_prev_calc1
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
               
 				SELECT  SUM(ReceivedChats) INTO v_currentTotalChatCount
 				FROM 	temp_chatHistory_calc1; 
 
 				SELECT  SUM(ReceivedChats) INTO v_previousTotalChatCount
 				FROM 	temp_chatHistory_prev_calc1; 
                 
                 SELECT (v_CurTotalSLA/v_currentTotalChatCount)*100
 				INTO v_CurrentAnsweredSLACount;
                 
                 SELECT (IFNULL(v_PrevTotalSLA,0)/v_previousTotalChatCount)*100
 				INTO v_PreviousAnsweredSLACount;
                 
                 SELECT sum(100 - (v_CurrentAnsweredSLACount))
 				INTO v_CurrentSLAbreachedCount;
                 
                 SELECT sum(100 - (v_PreviousAnsweredSLACount))
 				INTO v_PreviousSLAbreachedCount;
                 
                 
 				 
 
               	SELECT 	SUM(IFNULL(answeredSLA, 0))
               	INTO 	v_PrevansweredSLACount 
               	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
               
                	SELECT 	SUM(IFNULL(answeredSLA, 0))
               	INTO 	v_CuransweredSLACount 
 				FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
         
                	SELECT 	SUM(IFNULL(abandonedSLA, 0))
               	INTO 	v_PrevabandonedSLACount 
               	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
               
               
                	SELECT 	SUM(IFNULL(abandonedSLA, 0))
               	INTO 	v_CurabandonedSLACount 
             	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
               
             	SELECT 	SUM(IFNULL(SLAbreached, 0))
               	INTO 	v_PrevSLAbreachedCount 
               	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
               
                	SELECT 	SUM(IFNULL(SLAbreached, 0))
               	INTO 	v_CurSLAbreachedCount 
              	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
               
              	SELECT 	SUM(IFNULL(SLAbreached, 0))
               	INTO 	v_PrevSLAbreachedCount 
               	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;  
               
                	SELECT 	SUM(IFNULL(SLAbreached, 0))
               	INTO 	v_CurSLAbreachedCount 
              	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
               
 				SELECT 	SUM(IFNULL(totalDuration, 0))
               	INTO 	v_CurrenttotalDurationCount 
              	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
                  
              	SELECT 	SUM(IFNULL(totalDuration, 0))
               	INTO 	v_PretotalDurationCount 
              	FROM	temp_chatHistory_calc1
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
              
              	SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
              	INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
              	FROM 	temp_chatHistory_calc
              	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
               
                  SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
                  INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
                	FROM	temp_chatHistory_calc
               	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                  
             	SET v_PrevTotalCount =       CASE WHEN v_PrevTotalCount = 0 then null else     v_PrevTotalCount end; 
              	SET v_PrevansweredSLACount = CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
               	SET v_PrevabandonedSLACount= CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
              	SET v_PrevSLAbreachedCount = CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
                  
                 SET v_DiffTotalPercent 		    = (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
              	,  v_DiffansweredSLAPercent  	= CASE WHEN v_PreviousAnsweredSLACount = 0 THEN 0 ELSE (IFNULL(v_CurrentAnsweredSLACount, 0) - v_PreviousAnsweredSLACount) / v_PreviousAnsweredSLACount * 100 END
 				,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
                 ,  v_DiffSLAbreachedPercent  	= CASE WHEN v_PreviousSLAbreachedCount = 0 THEN 0 ELSE (IFNULL(v_CurrentSLAbreachedCount, 0) - v_PreviousSLAbreachedCount) / v_PreviousSLAbreachedCount * 100 END; 
      
                 	SELECT * FROM temp_AllagentId;
                  
                 	SELECT 
                          IFNULL(v_CurrentAnsweredSLACount,0)      AS 'CurrentAnsweredSLACount',
                          IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                          IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                          IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                          IFNULL(v_CurrentSLAbreachedCount,0)      AS 'CurrentSLAbreachedCount',
                          IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';
               
                   
          		DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal_1; 
           		CREATE TEMPORARY TABLE temp_ChatHistory_cal_1 AS
    			SELECT 
    				a.agentName											AS agentName,
    				SUM(a.SL1) 											AS SL1,
    				SUM(a.SL2) 											AS SL2,
    				SUM(a.SL3) 											AS SL3,
    				SUM(a.SL4) 											AS SL4,
    				SUM(a.SL5) 											AS SL5,
    				SUM(a.SL6) 											AS SL6,
    				SUM(a.TotalSLA) 									AS TotalSLA,
    				SUM(a.MissedChats)								    AS MissedChats,
    				(SUM(v_CurTotalSLA) / SUM(a.ReceivedChats))*100   	AS SLAachieved,
    				SUM(a.ReceivedChats)                                AS ReceivedChats
    			FROM temp_chatHistory_calc1 	a
    			JOIN temp_chatHistory_calc 		b 	ON a.ChatHistoryId = b.ChatHistoryId and a.agentID = b.agentID
    			GROUP BY agentName;  
    
 			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal_2; 
 			CREATE TEMPORARY TABLE temp_ChatHistory_cal_2 AS
 			SELECT 
 			distinct(agentName) agentName, 'Answered', sum(SL1) SL1, sum(SL2) SL2, sum(SL3) SL3, sum(SL4) SL4, sum(SL5) SL5, sum(SL6) SL6, sum(TotalSLA)
 			, sum(MissedChats) MissedChats, sum(SLAachieved) SLAachieved, abs(sum(SLAachieved -100)) SLAbreached
 			FROM temp_ChatHistory_cal_1
 			GROUP by agentName;
 
 
          select  count(*), sum(SL1), sum(SL2), sum(SL3), sum(SL4), sum(SL5), sum(SL6), sum(SL1+SL2+SL3+SL4+SL5+SL6), sum(MissedChats), sum(SLAAchieved), sum(round(SLAAchieved))
          INTO    v_Counts, v_SL1, v_SL2, v_SL3, v_SL4, v_SL5, v_SL6, v_TotalSLA, v_MissedChats, v_SLAAchieved, v_SLAbreached
          FROM temp_ChatHistory_cal_2 ;
       
                    
             SELECT
       			       'All Agents'												    AS agentName  ,
              		  'Answered'                                                    AS ChatType    ,
          				v_SL1 			                                            AS SL1        ,
          				v_SL2                                                       AS SL2        ,
          				v_SL3                                                       AS SL3        ,
          				v_SL4 			                                            AS SL4        ,
          				v_SL5                                                       AS SL5        ,
          				v_SL6                                                       AS SL6        ,
          				v_CurTotalSLA 		                                        AS TotalSLA   ,
          				v_MissedChats                                               AS MissedChats,
          				abs(v_SLAAchieved)                            				AS SLAAchieved,
  						abs(100-v_SLAAchieved)					    				AS SLAbreached                           
          				
          				UNION ALL       
       				SELECT 
          				DISTINCT(agentName)											AS agentName    ,
          				'Answered' 													AS ChatType 	,
          				sum(SL1)													AS SL1			, 
          				sum(SL2)													AS SL2			, 
          				sum(SL3)													AS SL3			, 
          				sum(SL4)													AS SL4			, 
          				sum(SL5)													AS SL5			, 
          				sum(SL6)													AS SL6			, 
 						sum(SL1+SL2+SL3+SL4+SL5+SL6)								AS TotalSLA     ,
          				sum(MissedChats)											AS MissedChats	,
          				sum(SLAAchieved)											AS SLAAchieved	,	
 						sum(100-SLAAchieved)									    AS SLAbreached	
                          from temp_ChatHistory_cal_2
                          group by agentName;      
                    
                END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_agent_servicelevel_analysis_metrics_filter1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
