/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_agent_servicelevel_analysis_metrics_filter_1`(
                    		p_startTmpstmp 		BIGINT,
                        	p_endTmpstmp 		BIGINT,
                        	p_domainId 			INT,
                        	p_agentId 			TEXT,
    						p_offset 			INT,
    						p_Limit 		    INT	
                    	)
sp_return:begin
           
             	DECLARE v_offset 					INT;	  	
             	DECLARE v_CurrentStartTmpstmp 		BIGINT;
             	DECLARE v_CurrentEndTmpstmp 		BIGINT;
          	    DECLARE v_PrevStartTmpstmp 			BIGINT;
             	DECLARE v_PrevEndTmpstmp 			BIGINT; 
         		DECLARE v_TmpstmpInterval			BIGINT;	
                 
          	    DECLARE v_CurTotalCount 			INT;        
        		DECLARE  v_PrevTotalCount 				INT;                    
                DECLARE v_DiffTotalPercent 			INT;     
               
          	   DECLARE  v_CurTotalSLA               INT; 
               DECLARE  v_PrevTotalSLA             	INT; 
               DECLARE  v_DiffTotalSLAPercent      	INT; 
          
          	   DECLARE v_PretotalDurationCount         INT;
          	   DECLARE v_CurrenttotalDurationCount     INT;  
          
          	   DECLARE  v_CurTotalSLA1                INT; 
               DECLARE  v_PrevTotalSLA1              INT; 
               DECLARE  v_DiffTotalSLA1Percent       INT; 
          
               DECLARE  v_CurMissedChats             INT; 
               DECLARE  v_PrevMissedChats            INT; 
               DECLARE  v_DiffMissedChatsPercent     INT; 
          
            
        	   DECLARE  v_CurSLA1               		INT; 
               DECLARE  v_PrevSLA1              		INT; 
               DECLARE  v_DiffSLA1Percent       		INT; 
            
         	   DECLARE  v_CurSLA2               		INT; 
               DECLARE  v_PrevSLA2              		INT; 
               DECLARE  v_DiffSLA2Percent       		INT;  
            
          	   DECLARE  v_CurSLA3               		INT; 
               DECLARE  v_PrevSLA3              		INT; 
               DECLARE  v_DiffSLA3Percent       		INT;  
            
        	   DECLARE  v_CurSLA4               		INT; 
               DECLARE  v_PrevSLA4              		INT; 
               DECLARE  v_DiffSLA4Percent       		INT;  
            
        	   DECLARE  v_CurSLA5               		INT; 
               DECLARE  v_PrevSLA5              		INT; 
               DECLARE  v_DiffSLA5Percent       		INT;    
         		
         	   DECLARE  v_CurSLA6               		INT; 
               DECLARE  v_PrevSLA6              		INT; 
               DECLARE  v_DiffSLA6Percent       		INT; 
           
          	   DECLARE  v_CuransweredSLACount        INT; 
               DECLARE  v_PrevansweredSLACount       INT; 
               DECLARE  v_DiffansweredSLAPercent     INT; 
               
          	   DECLARE  v_CurabandonedSLACount       INT; 
               DECLARE  v_PrevabandonedSLACount      INT; 
               DECLARE  v_DiffabandonedSLAPercent    INT; 
               
          	   DECLARE  v_CurSLAbreachedCount        INT; 
               DECLARE  v_PrevSLAbreachedCount       INT; 
               DECLARE  v_DiffSLAbreachedPercent     INT; 
               
               
      		 DECLARE  v_CurChatTypeCount                 	INT; 
               DECLARE  v_PrevChatTypeCount               	INT; 
               DECLARE  v_DiffChatTypePercent             	INT;  
               
      		DECLARE			v_ChatType                 VARCHAR(250);
      		DECLARE			v_SL1 						INT;
      		DECLARE			v_SL2                       INT;
      		DECLARE			v_SL3                       INT;
      		DECLARE			v_SL4 						INT;
      		DECLARE			v_SL5                       INT;
      		DECLARE			v_SL6                       INT;
      		DECLARE			v_TotalSLA 					INT;
      		DECLARE			v_MissedChats               INT;
      		DECLARE			v_SLAAchieved               INT;
      		DECLARE			v_SLAbreached				INT;      
               
           
          	 SET v_offset =  p_Limit * p_offset; 
             
             	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
             	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
             	
           	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
           
           	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
           	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
             		
             	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
             	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
                               
             	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
             	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
             	CREATE TEMPORARY TABLE temp_AllagentId
             	SELECT 	UserID,UserName 
               FROM 	tb_User 
               WHERE 	domainId 	= p_domainId; 
                              
                       	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
                     	   CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
            			 SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		          AS SessionDate
            					,U.UserID                                                                 AS agentID
            					,U.UserName													      		  AS agentName     
          					,SH.ChatHistoryId 
                              ,SH.sessionStartTime
            					,SDH.answeredDuration                                                     AS chatDuration                 
            					,SDH.Duration												      		  AS Duration
                              ,SDH.IsAbandoned
                              ,SDH.IsMissed
                         	FROM 	tb_ChatHistory 				SH
                         	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
                     		left JOIN 	tb_User					U	ON SDH.AgentId			= U.UserID  
          				    left JOIN 	temp_agentIDs 			t_A     ON SDH.AgentId		= t_A.agentId  
                         	WHERE 	SH.domainId 		= p_domainId	
                 			   AND 	SH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp   
          				   AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
          
          
                 	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                             	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                             	SELECT 	
                						 a.SessionDate 				       										                                       AS 'Date'                  
                						,a.agentID
                						,a.agentName																                                  
                                      ,a.ChatHistoryId 
                                      ,a.sessionStartTime
                                   , SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															    AS Answered
                                    ,SUM(CASE WHEN a.IsAbandoned=1 Then 'Abandoned' ELSE 0 END)                                                       AS Abandoned
                                    ,a.IsAbandoned 
          						  ,SUM(a.Duration)                                                                                                   AS totalDuration
                                    ,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	 AS  SL1
                				      ,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         		 AS  SL2
                					  ,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        			 AS  SL3
                                    ,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL4
                                    ,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL5
                                    ,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL6
                                    ,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)                  AS  TotalSLA
                                    ,sum(case when a.IsMissed =1 then 1 else 0 end)																	 AS  MissedChats
                                 
                                    FROM temp_ChatHistory a     
                                    GROUP BY a.SessionDate,a.agentID,a.agentName,a.chatDuration,a.ChatHistoryId,a.sessionStartTime,a.IsAbandoned  , a.IsMissed ;
           
                  	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1; 
                             	CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS 	     
                             	SELECT 	
                						 a.Date 				       										                                                       
                						,a.agentID
                						,a.agentName														
                                      , case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
                                      ,a.ChatHistoryId 
                                      ,a.sessionStartTime
          						    , a.totalDuration
                                       ,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
                                      , sum(SL1)																															AS SL1
                                      , sum(SL2)                                                                                                                            AS SL2
                                      , sum(SL3)                                                                                                                            AS  SL3
                                      , sum(SL4)                                                                                                                            AS SL4
                                       ,sum(SL5)                                                                                                                            AS SL5
                                       ,sum(SL6)                                                                                                                            AS SL6
                                      , a.MissedChats       
          							,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END)                      AS answeredSLA
                                      ,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END   )                AS abandonedSLA
                                      ,SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1  ELSE (a.MissedChats / (a.TotalSLA + a.MissedChats)) * 100 END  )             AS SLAbreached
                                    FROM temp_chatHistory_calc    a 
                                     GROUP BY a.Date,a.agentID,a.agentName,a.sessionStartTime,a.ChatHistoryId,a.totalDuration,a.TotalSLA,a.MissedChats,a.Answered,a.Abandoned ;  
           
          	 SELECT  COUNT(ChatHistoryId),	SUM(TotalSLA), SUM(MissedChats),sum(ChatType)              														                     				 
               INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats,v_CurChatTypeCount                           														                      					
               FROM 	temp_chatHistory_calc1
               WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
           
           	SELECT 	COUNT(ChatHistoryId),SUM(TotalSLA), SUM(MissedChats),sum(ChatType)                       																								 
           	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats,v_PrevChatTypeCount                                 														 										
           	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
           	SELECT 	SUM(IFNULL(answeredSLA, 0))
           	INTO 	v_PrevansweredSLACount 
           	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
            	SELECT 	SUM(IFNULL(answeredSLA, 0))
           	INTO 	v_CuransweredSLACount 
               FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
           
            	SELECT 	SUM(IFNULL(abandonedSLA, 0))
           	INTO 	v_PrevabandonedSLACount 
           	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
           
            	SELECT 	SUM(IFNULL(abandonedSLA, 0))
           	INTO 	v_CurabandonedSLACount 
         	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
           
         	SELECT 	SUM(IFNULL(SLAbreached, 0))
           	INTO 	v_PrevSLAbreachedCount 
           	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
            	SELECT 	SUM(IFNULL(SLAbreached, 0))
           	INTO 	v_CurSLAbreachedCount 
          	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
           
          	SELECT 	SUM(IFNULL(SLAbreached, 0))
           	INTO 	v_PrevSLAbreachedCount 
           	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
           
            	SELECT 	SUM(IFNULL(SLAbreached, 0))
           	INTO 	v_CurSLAbreachedCount 
          	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
           
           
             	SELECT 	SUM(IFNULL(totalDuration, 0))
           	INTO 	v_CurrenttotalDurationCount 
          	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
              
          	SELECT 	SUM(IFNULL(totalDuration, 0))
           	INTO 	v_PretotalDurationCount 
          	FROM	temp_chatHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
              
          
          	SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
          	INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
          	FROM 	temp_chatHistory_calc
          	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
           
              SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
              INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
            	FROM	temp_chatHistory_calc
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
              
         	SET v_PrevTotalCount =       CASE WHEN v_PrevTotalCount = 0 then null else     v_PrevTotalCount end; 
          	SET v_PrevansweredSLACount = CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
           	SET v_PrevabandonedSLACount= CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
          	SET v_PrevSLAbreachedCount = CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
              
             SET v_DiffTotalPercent 		    = (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
          	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
              ,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
          	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
           
           
             	SELECT * FROM temp_AllagentId;
              
              
             	SELECT 
                      IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
                      IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                      IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                      IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                      IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
                      IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';
           
               
      		DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal_1; 
       		CREATE TEMPORARY TABLE temp_ChatHistory_cal_1 AS
           	SELECT 	distinct(U.UserName)																						AS agentName
                  ,  count(1)																									AS RecievedChats
                  , a.ChatType
                  ,	(b.SL1)                                                                                						AS	SL1
                  ,	(b.SL2)                                                                                						AS   SL2
          		  ,	(b.SL3)                                                                                						AS   SL3
          		  ,	(b.SL4)                                                                                						AS   SL4
          		  ,	(b.SL5)                                                                                						AS   SL5
          		  ,	(b.SL6)                                                                                						AS   SL6
                  ,   (a.TotalSLA)                                                                            				        AS   TotalSLA
                  ,   (a.MissedChats)                                                                        					    AS    MissedChats
                  ,  CASE WHEN sum(b.TotalSLA/b.totalDuration) IS NOT NULL THEN sum(b.TotalSLA/b.totalDuration) ELSE '-' END        AS SLAachieved
                  , sum(100-(b.TotalSLA/b.totalDuration))																		    AS SLAbreached
                  FROM temp_chatHistory_calc b
                  JOIN temp_chatHistory_calc1 a     ON b.ChatHistoryId= a.ChatHistoryId
          		  JOIN 	temp_AllagentId		U	    ON a.AgentId	= U.UserID
          	      WHERE a.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
                  GROUP BY U.UserName,a.ChatType,b.Abandoned,b.Answered,a.MissedChats,a.TotalSLA
                  ,b.SL1,b.SL2,b.SL3,b.SL4,b.SL5,b.SL6;    
          
          select * from temp_ChatHistory_cal_1;
                
      select  sum(ChatType), sum(SL1), sum(SL2), sum(SL3), sum(SL4), sum(SL5), sum(SL6), sum(SL1+SL2+SL3+SL4+SL5+SL6), sum(MissedChats), sum(SLAAchieved), sum(100-SLAAchieved)
      INTO
       v_ChatType, v_SL1, v_SL2, v_SL3, v_SL4, v_SL5, v_SL6, v_TotalSLA, v_MissedChats, v_SLAAchieved, v_SLAbreached
      FROM temp_ChatHistory_cal_1;
   
           
                
         SELECT
   			  'All Agents'												    AS agentName  ,
          		  'Answered'                                                    AS ChatType    ,
      				v_SL1 			                                            AS SL1        ,
      				v_SL2                                                       AS SL2        ,
      				v_SL3                                                       AS SL3        ,
      				v_SL4 			                                            AS SL4        ,
      				v_SL5                                                       AS SL5        ,
      				v_SL6                                                       AS SL6        ,
      				v_TotalSLA 		                                            AS TotalSLA   ,
      				v_MissedChats                                               AS MissedChats,
      				v_SLAAchieved                                               AS SLAAchieved,
                     0															AS SLAbreached
      				
      				UNION ALL       
   				SELECT 
      				DISTINCT(agentName)											AS agentName    ,
      				max(ChatType)													AS ChatType 	,
      				sum(SL1)													AS SL1			, 
      				sum(SL2)													AS SL2			, 
      				sum(SL3)													AS SL3			, 
      				sum(SL4)													AS SL4			, 
      				sum(SL5)													AS SL5			, 
      				sum(SL6)													AS SL6			, 
                   sum(SL1+SL2+SL3+SL4+SL5+SL6)									AS TotalSLA     ,
      				sum(MissedChats)											AS MissedChats	,
                   sum((SL1+SL2+SL3+SL4+SL5+SL6)/RecievedChats)					AS SLAAchieved	,
      				
                     0															AS SLAbreached	
                     
                      from temp_ChatHistory_cal_1
                      group by agentName;        
                
            END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_agent_servicelevel_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_agent_servicelevel_metrics_filter`(
          		p_startTmpstmp 		BIGINT,
              	p_endTmpstmp 		BIGINT,
              	p_domainId 			INT,
              	p_agentId 			VARCHAR(250),
 				p_offset 			INT,
   			    p_Limit 		    INT	
          	)
sp_return:begin
			DECLARE v_offset 		     		INT;	
 			DECLARE v_Total_Count 	     		INT;        
  			DECLARE v_startTmpstmp 	     		BIGINT;
  			DECLARE v_endTmpstmp 	     		BIGINT;
  			DECLARE v_currenttimestamp   		DATETIME;
			DECLARE v_previous_timestamp 		DATETIME;
  			DECLARE v_oneday_previous_timestamp DATETIME;
  			DECLARE v1_count 					INT;
			DECLARE v2_count					INT;
			DECLARE v_CurrentStartTmpstmp 		BIGINT;
 	        DECLARE v_CurrentEndTmpstmp 		BIGINT;
  	        DECLARE v_PrevStartTmpstmp 			BIGINT;
 	        DECLARE v_PrevEndTmpstmp 			BIGINT; 
 	        DECLARE v_TmpstmpInterval			BIGINT;	
              
	 SET v_offset =  p_Limit * p_offset;
     SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
     SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
     SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
     
    			SET v_currenttimestamp = NOW();
    			SET v_previous_timestamp = DATE_SUB(NOW(), INTERVAL 1 DAY);
    			SET v_oneday_previous_timestamp = DATE_SUB(NOW(), INTERVAL 2 DAY);
                     
			    IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = unix_timestamp(now())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF; 
               
 					DROP TEMPORARY TABLE IF EXISTS temp_agentId;	
					CREATE TEMPORARY TABLE temp_agentId(agentId VARCHAR(100));
                    
				CALL split(p_agentId,',');	INSERT INTO temp_agentId(agentId) SELECT Items FROM tt_Split_temptable; 
          		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                    
                  DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                   CREATE TEMPORARY TABLE temp_AllagentId
                   SELECT DISTINCT UserID,UserName as AgentName from tb_User where domainId = p_domainId AND roleid NOT IN (5,3); 
                    
       			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
       			CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
        		 SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		                     AS SessionDate
						 , U.UserID															             AS agentId
						 , U.UserName																	 AS agentName                     
       					 , SDH.Duration                                                                  AS chatDuration                 
       					 , SDH.Duration												                     AS Duration
						 , SH.disconnectedBy  														     AS  disconnectedBy 
                   	FROM 	tb_ChatHistory 				SH
                   	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
               		LEFT JOIN 	tb_User					U	ON SDH.AgentId			= U.UserID  
                   	WHERE 	SH.domainId 		= p_domainId	
       				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp and v_CurrentEndTmpstmp 
       				AND		SH.IsInBound		= 1	
					LIMIT 	v_offset, p_Limit; 
          			    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  				
                      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
                       DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                       	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                       	SELECT 	
       						a.SessionDate 				       										                                       AS 'Date'                  
 							,a.agentId
 							,CASE WHEN a.agentName IS NOT NULL THEN a.agentName ELSE '-' END											   AS agentName
							,SUM(a.Duration)                                                                                               AS totalDuration
							,(CASE WHEN a.chatDuration > 30000  then 1 else 0 END)								                           AS MissedChats  
       						,(CASE WHEN a.chatDuration < 30000  then 1 else 0 END)												           AS abondedchats
 							,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL1
       						,SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         AS  SL2
       						,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL3
       						,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL4
       						,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL5
       						,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL6                                   
  							FROM temp_ChatHistory a     
                              GROUP BY a.SessionDate,a.agentId,a.agentName,a.chatDuration,a.disconnectedBy;
                       
  			SELECT * FROM temp_AllagentId;
  			
           DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1;
           CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS
           SELECT
           a.agentName,
           SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                           as TotalSLA,
           a.MissedChats
           FROM temp_chatHistory_calc a
		   GROUP BY a.agentName,a.MissedChats;
    				
                    IF NOT EXISTS(SELECT 1 FROM temp_chatHistory_calc1 LIMIT 1) THEN
    				SELECT '-' as agentName, 0 AS answeredSLA, 0 AS answeredslaincreasedBy, 0 AS abandonedSLA,0 AS abandonedslaincreasedBy,0 AS SLAbreached, 0 AS SLAbreachedincreasedBy;
    				LEAVE sp_return;
    				END IF;
           SELECT
                IFNULL(a.agentName ,0)                                   	                                                                               AS agentName,
				IFNULL(SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END),0)                   AS answeredSLA,
                IFNULL(((v1_count - v2_count) / v1_count * 100),0) 																				 		   AS answeredslaincreasedBy,
                IFNULL(sum(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END),0)                 AS abandonedSLA,
                IFNULL(((v1_count - v2_count) / v1_count * 100),0)                                                                                		   AS abandonedslaincreasedBy,
                IFNULL(sum(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1  ELSE (a.MissedChats / (a.TotalSLA + a.MissedChats)) * 100 END),0)             AS SLAbreached,
   			    IFNULL(((v1_count - v2_count) / v1_count * 100),0)                                                                                  		   AS SLAbreachedincreasedBy
   
           FROM
               temp_chatHistory_calc1 a
               GROUP BY a.agentName ;
         
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_Queue_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_Queue_servicelevel_analysis_metrics_filter`(
     	p_startTmpstmp 		BIGINT,
     	p_endTmpstmp 		BIGINT,
     	p_domainId 			INT,
     	p_queueId 			TEXT,
     	p_offset 			INT,
     	p_Limit 		    INT	
     )
sp_return:begin
                    
      				DECLARE v_offset 						INT;	  	
      				DECLARE v_CurrentStartTmpstmp 			BIGINT;
      				DECLARE v_CurrentEndTmpstmp 			BIGINT;
      				DECLARE v_PrevStartTmpstmp 				BIGINT;
      				DECLARE v_PrevEndTmpstmp 				BIGINT; 
      				DECLARE v_TmpstmpInterval				BIGINT;	
      
      				DECLARE v_CurTotalCount 				INT;        
      				DECLARE  v_PrevTotalCount 				INT;                    
      				DECLARE v_DiffTotalPercent 				INT;     
      
      				DECLARE  v_CurTotalSLA               	INT; 
      				DECLARE  v_PrevTotalSLA             	INT; 
      				DECLARE  v_DiffTotalSLAPercent      	INT; 
      
      				DECLARE  v_CurTotalSLA1               	INT; 
      				DECLARE  v_PrevTotalSLA1              	INT; 
      				DECLARE  v_DiffTotalSLA1Percent       	INT; 
   	
      				DECLARE  v_CurMissedChats             	INT; 
      				DECLARE  v_PrevMissedChats            	INT; 
      				DECLARE  v_DiffMissedChatsPercent     	INT; 
       
      				DECLARE  v_CurSLA1               		INT; 
      				DECLARE  v_PrevSLA1              		INT; 
      				DECLARE  v_DiffSLA1Percent       		INT; 
      
      				DECLARE  v_CurSLA2               		INT; 
      				DECLARE  v_PrevSLA2              		INT; 
      				DECLARE  v_DiffSLA2Percent       		INT;  
      
      				DECLARE  v_CurSLA3               		INT; 
      				DECLARE  v_PrevSLA3              		INT; 
      				DECLARE  v_DiffSLA3Percent       		INT;  
      
      				DECLARE  v_CurSLA4               		INT; 
      				DECLARE  v_PrevSLA4              		INT; 
      				DECLARE  v_DiffSLA4Percent       		INT;  
      
      				DECLARE  v_CurSLA5               		INT; 
      				DECLARE  v_PrevSLA5              		INT; 
      				DECLARE  v_DiffSLA5Percent       		INT;    
      
      				DECLARE  v_CurSLA6               		INT; 
      				DECLARE  v_PrevSLA6              		INT; 
      				DECLARE  v_DiffSLA6Percent       		INT; 
      
      				DECLARE  v_CuransweredSLACount        	INT; 
      				DECLARE  v_PrevansweredSLACount       	INT; 
      				DECLARE  v_DiffansweredSLAPercent     	INT; 
   	
      				DECLARE  v_CurSLAbreachedCount        	INT; 
      				DECLARE  v_PrevSLAbreachedCount       	INT; 
      				DECLARE  v_DiffSLAbreachedPercent     	INT; 
      
      				DECLARE  v_CurChatTypeCount                 INT; 
      				DECLARE  v_PrevChatTypeCount               	INT; 
      				DECLARE  v_DiffChatTypePercent             	INT;  
      
      				DECLARE			v_Counts                 	INT;
      				DECLARE			v_agentName                 VARCHAR(250);
      				DECLARE			v_SL1 						INT;
      				DECLARE			v_SL2                       INT;
      				DECLARE			v_SL3                       INT;
      				DECLARE			v_SL4 						INT;
      				DECLARE			v_SL5                       INT;
      				DECLARE			v_SL6                       INT;
      				DECLARE			v_TotalSLA 					INT;
      				DECLARE			v_MissedChats               INT;
      				DECLARE			v_SLAAchieved               INT;
      				DECLARE			v_SLAbreached				INT;    
  					DECLARE         v_preReceivedChats          INT;
                      
      				DECLARE			v_currentTotalChatCount		INT;      
      				DECLARE			v_previousTotalChatCount	INT;
                      
      				DECLARE			v_CurrentAnsweredSLACount	INT;      
      				DECLARE			v_PreviousAnsweredSLACount	INT;
                      
      				DECLARE			v_CurrentSLAbreachedCount	INT;      
      				DECLARE			v_PreviousSLAbreachedCount	INT;      
                    
      				SET v_offset =  p_Limit * p_offset; 
      
      				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
      				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
      
      				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
      
      				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
      				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
     
   					DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
                      	CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
   
   
             SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
          DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
          CREATE TEMPORARY TABLE temp_AllqueueId   
          SELECT qid, name AS queueName 
          FROM queue 
          WHERE domainId = p_domainId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      				DROP TEMPORARY TABLE IF EXISTS tt_ChatHistory; 
      				CREATE TEMPORARY TABLE tt_ChatHistory AS 	    	
      				SELECT	SH.sessionStartTime 		  
   						, SDH.QueueId                  
   						,	Q.name
     						,SH.ChatHistoryId 
     						,SDH.answeredDuration
     						,SDH.Duration
     						,SDH.IsAbandoned
     						,SDH.IsMissed
     						,SH.IsInBound
      				FROM 	tb_ChatHistory 			SH
      				JOIN 	tb_ChatDurationHistory	SDH		ON SH.chatHistoryId 	= SDH.chatHistoryId
   				LEFT JOIN 	queue				Q		ON SDH.queueId			= Q.qid  
      				LEFT JOIN temp_queueIDs 		t_Q 	ON Q.qid = t_Q.queueId 
      				WHERE 	SH.domainId 			= p_domainId	
                     AND 	SDH.IsBot 				= 0
   				  AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp   
   				  AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL)); 
                      
      				DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
      				CREATE TEMPORARY TABLE temp_ChatHistory AS
      				SELECT	 CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) 		 			 AS SessionDate
      					,QueueId                                                         			 AS QueueId
      					,CASE WHEN `name` IS NOT NULL THEN `name` ELSE 'Default Queue' END 			 AS queueName
      					,ChatHistoryId 
      					,sessionStartTime
      					,answeredDuration                                               			 AS chatDuration
      					,Duration												      				 AS Duration
      					,IsAbandoned
      					,IsMissed
      					,IsInBound
     				FROM 	tt_ChatHistory
      				WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;
                          
      				DROP TEMPORARY TABLE IF EXISTS temp_prev_ChatHistory; 
      				CREATE TEMPORARY TABLE temp_prev_ChatHistory AS 	    	
      				SELECT	 CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) 		AS SessionDate
     					,QueueId
     					,CASE WHEN `name` IS NOT NULL THEN `name` ELSE 'Default Queue' END											   AS queueName   
      					,ChatHistoryId 
      					,sessionStartTime
      					,answeredDuration                                               AS chatDuration                 
      					,Duration												      	AS Duration
      					,IsAbandoned
      					,IsMissed
      					,IsInBound                              
     				FROM 	tt_ChatHistory
     				WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                 
      				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
      				CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
      				SELECT 	
     					a.SessionDate 				       										                                       	AS 'Date'
     					,a.QueueId
     					,CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE 'Default Queue' END											   AS queueName
     					,a.ChatHistoryId 
     					,a.sessionStartTime
     					,SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															AS Answered
     					,SUM(CASE WHEN a.IsAbandoned=1 Then 'Abandoned' ELSE 0 END)                                                     AS Abandoned
     					,a.IsAbandoned 
     					,SUM(a.Duration)                                                                                                AS totalDuration
     					,SUM(CASE WHEN a.chatDuration BETWEEN 0 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	AS  SL1
     					,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)				AS  SL2
     					,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        		AS  SL3
     					,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL4
     					,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL5
     					,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL6
     					,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               AS  TotalSLA
     					,sum(case when a.IsMissed =1 then 1 else 0 end)																	AS  MissedChats
     					,sum(case when a.IsInBound =1 then 1 else 0 end)																AS  ReceivedChats
      				FROM temp_ChatHistory a   
      				GROUP BY a.SessionDate,a.QueueId,a.queueName,a.chatDuration,a.ChatHistoryId,a.sessionStartTime,a.IsAbandoned  , a.IsMissed,a.IsInBound ;
         
      				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_prev_calc; 
      				CREATE TEMPORARY TABLE temp_chatHistory_prev_calc AS 	     
      				SELECT 	
      				a.SessionDate 				       										                                       AS 'Date'                  
      				,a.QueueId
      				,a.queueName																                                  
      				,a.ChatHistoryId 
      				,a.sessionStartTime
      				, SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															 AS Answered
      				,SUM(CASE WHEN a.IsAbandoned=1 Then 'Abandoned' ELSE 0 END)                                                      AS Abandoned
      				,a.IsAbandoned 
      				,SUM(a.Duration)                                                                                                   AS totalDuration
      				,SUM(CASE WHEN a.chatDuration BETWEEN 0 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	 AS  SL1
      				,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         	 	 AS  SL2
      				,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        		 AS  SL3
      				,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL4
      				,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL5
      				,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		 AS  SL6
      				,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)                AS  TotalSLA
      				,sum(case when a.IsMissed =1 then 1 else 0 end)																	 AS  MissedChats
      				,sum(case when a.IsInBound =1 then 1 else 0 end)																 AS  ReceivedChats
      				FROM temp_prev_ChatHistory a   
      				GROUP BY a.SessionDate,a.QueueId,a.queueName,a.chatDuration,a.ChatHistoryId,a.sessionStartTime,a.IsAbandoned  , a.IsMissed,a.IsInBound ;
         
      				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1; 
      				CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS 	     
      				SELECT 	
      				a.Date 				       										                                                       
      				,a.QueueId
      				,a.queueName														
      				,case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
      				,a.ChatHistoryId 
      				,a.sessionStartTime
      				,a.totalDuration
      				,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
      				, sum(SL1)																															AS	SL1
      				, sum(SL2)                                                                                                                          AS SL2
      				, sum(SL3)                                                                                                                          AS SL3
      				, sum(SL4)                                                                                                                          AS SL4
      				,sum(SL5)                                                                                                                           AS SL5
      				,sum(SL6)                                                                                                                           AS SL6
      				,a.MissedChats       
      				,sum(a.ReceivedChats)  																												AS ReceivedChats
                     ,(sum(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)/sum(a.ReceivedChats))*100  																AS answeredSLA
     				,100- ((sum(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)/sum(a.ReceivedChats))*100) 														AS SLAbreached
      				FROM temp_chatHistory_calc    a 
      				GROUP BY a.Date,a.QueueId,a.queueName,a.Answered,a.ChatHistoryId,a.sessionStartTime,a.totalDuration,a.MissedChats; 
      
      
                      select sum(ReceivedChats) INTO v_preReceivedChats from temp_chatHistory_prev_calc;
      
      				DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_prev_calc1; 
      				CREATE TEMPORARY TABLE temp_chatHistory_prev_calc1 AS 	     
      				SELECT 	
      				a.Date 				       										                                                       
      				,a.QueueId
      				,a.queueName														
      				, case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
      				,a.ChatHistoryId 
      				,a.sessionStartTime
      				,a.totalDuration
      				,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
      				,sum(SL1)																															AS SL1
      				,sum(SL2)                                                                                                                           AS SL2
      				,sum(SL3)                                                                                                                           AS SL3
      				,sum(SL4)                                                                                                                           AS SL4
      				,sum(SL5)                                                                                                                           AS SL5
      				,sum(SL6)                                                                                                                           AS SL6
      				,a.MissedChats       
      				,sum(a.ReceivedChats)  																												AS ReceivedChats
     				,(sum(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)/sum(v_preReceivedChats))*100  																AS answeredSLA
     			
      				FROM temp_chatHistory_prev_calc    a 
      				GROUP BY a.Date,a.QueueId,a.queueName,a.Answered,a.ChatHistoryId,a.sessionStartTime,a.totalDuration,a.MissedChats;  
                    
  
   
                    
                
               
    				SELECT  COUNT(ChatHistoryId),	SUM(TotalSLA), SUM(MissedChats),SUM(ReceivedChats),sum(answeredSLA)/count(ChatHistoryId),sum(SLAbreached)/count(ChatHistoryId)
    				INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats, v_currentTotalChatCount, v_CurrentAnsweredSLACount,v_CurrentSLAbreachedCount
    				FROM 	temp_chatHistory_calc1
    				WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
                    
    				SELECT 	COUNT(ChatHistoryId),SUM(TotalSLA), SUM(MissedChats),SUM(ReceivedChats),sum(answeredSLA),(100- sum(answeredSLA)) 
    				INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats,v_previousTotalChatCount,v_PreviousAnsweredSLACount,v_PreviousSLAbreachedCount
    				FROM	temp_chatHistory_prev_calc1
    				WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
    
            
    
    				SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
    				INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
    				FROM 	temp_chatHistory_calc
    				WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
    
    				SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
    				INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
    				FROM	temp_chatHistory_calc
    				WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                       
                      SET 	v_DiffTotalPercent 		    = (IFNULL(v_CurTotalCount,0) - v_PrevTotalCount) / IF(IFNULL(v_PrevTotalCount,0)=0,1,v_PrevTotalCount) * 100 
    					,  	v_DiffansweredSLAPercent  	= CASE WHEN v_PreviousAnsweredSLACount = 0 THEN 0 ELSE (IFNULL(v_CurrentAnsweredSLACount, 0) - v_PreviousAnsweredSLACount) / IF(IFNULL(v_PreviousAnsweredSLACount,0)=0,1,v_PreviousAnsweredSLACount) * 100 END
    					,  	v_DiffSLAbreachedPercent  	= CASE WHEN v_PreviousSLAbreachedCount = 0 THEN 0 ELSE (IFNULL(v_CurrentSLAbreachedCount, 0) - v_PreviousSLAbreachedCount) / IF(IFNULL(v_PreviousSLAbreachedCount,0)=0,1,v_PreviousSLAbreachedCount) * 100 END;        
    
                      	SELECT * FROM temp_AllqueueId;
                       
                      	SELECT 
                               IFNULL(v_CurrentAnsweredSLACount,0)       AS 'CurrentAnsweredSLACount',
                               IFNULL(v_DiffansweredSLAPercent,0)        AS 'DiffAnsweredSLAPercent',
                               IFNULL(v_CurrentSLAbreachedCount,0)       AS 'CurrentSLAbreachedCount',
                               IFNULL(v_DiffSLAbreachedPercent ,0)       AS 'DiffSLAbreachedPercent';  
                               
    					select 		SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6),SUM(TotalSLA),SUM(MissedChats),SUM(answeredSLA)/count(ChatHistoryId) SLAAchieved, sum(SLAbreached)/count(ChatHistoryId) SLAbreached
    								INTO v_SL1, v_SL2, v_SL3, v_SL4, v_SL5, v_SL6, v_TotalSLA, v_MissedChats, v_SLAAchieved, v_SLAbreached
    					from temp_chatHistory_calc1;
                        
                        select 	'All Agents'	 																				AS queueName
    							 ,'Answered' 																						AS ChatType
    							 ,IFNULL(v_SL1,0)																					AS SL1
    							 ,IFNULL(v_SL2,0) 																					AS SL2
                                ,IFNULL(v_SL3,0) 																					AS SL3
                                ,IFNULL(v_SL4,0) 																					AS SL4
                                ,IFNULL(v_SL5,0) 																					AS SL5
                                ,IFNULL(v_SL6,0)																					AS SL6
                                ,IFNULL(v_TotalSLA,0) 																				AS Total
                                ,IFNULL(v_MissedChats,0) 																			AS MissedChats    
                                ,IFNULL(abs(v_SLAAchieved),0)																		AS SLAAchieved 
                                ,IFNULL(abs(v_SLAbreached),0)																		AS SLAbreached
    					union all	
    					SELECT DISTINCT(queueName) 																					AS queueName
    							 ,'Answered' 																						AS ChatType
    							 ,IFNULL(SUM(SL1),0)																				AS SL1
                                ,IFNULL(SUM(SL2),0)																				AS SL2
                                ,IFNULL(SUM(SL3),0)																				AS SL3
                                ,IFNULL(SUM(SL4),0)																				AS SL4
                                ,IFNULL(SUM(SL5),0)																				AS SL5
                                ,IFNULL(SUM(SL6),0)																				AS SL6
                                ,IFNULL(SUM(TotalSLA),0)																			AS Total
                                ,IFNULL(SUM(MissedChats),0)																		AS MissedChats   
                                ,IFNULL(abs(SUM(answeredSLA)/count(ChatHistoryId)),0) 												AS SLAAchieved
    							,IFNULL(abs(SUM(SLAbreached)/count(ChatHistoryId)),0)												AS SLAbreached
    					from temp_chatHistory_calc1
    					group by queueName;
    
                     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_Queue_servicelevel_analysis_metrics_filter_2024-10-02` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_Queue_servicelevel_analysis_metrics_filter_2024-10-02`(
                    		p_startTmpstmp 		BIGINT,
                        	p_endTmpstmp 		BIGINT,
                        	p_domainId 			INT,
  						p_queueId 			TEXT,
  						p_offset 			INT,
 						p_Limit 		    INT	
                    	)
sp_return:begin
           
             	DECLARE v_offset 					INT;	  	
             	DECLARE v_CurrentStartTmpstmp 		BIGINT;
             	DECLARE v_CurrentEndTmpstmp 		BIGINT;
  			DECLARE v_PrevStartTmpstmp 			BIGINT;
             	DECLARE v_PrevEndTmpstmp 			BIGINT; 
         		DECLARE v_TmpstmpInterval			BIGINT;	
                 
          	   DECLARE v_CurTotalCount 				INT;        
        	       DECLARE  v_PrevTotalCount 			INT;                    
                DECLARE v_DiffTotalPercent 			INT;     
               
          	   DECLARE  v_CurTotalSLA               INT; 
               DECLARE  v_PrevTotalSLA             	INT; 
               DECLARE  v_DiffTotalSLAPercent      	INT; 
          
          	   DECLARE v_PretotalDurationCount         INT;
          	   DECLARE v_CurrenttotalDurationCount     INT;  
          
          	   DECLARE  v_CurTotalSLA1               INT; 
               DECLARE  v_PrevTotalSLA1               INT; 
               DECLARE  v_DiffTotalSLA1Percent        INT; 
          
               DECLARE  v_CurMissedChats             INT; 
               DECLARE  v_PrevMissedChats            INT; 
               DECLARE  v_DiffMissedChatsPercent     INT; 
          
            
        	      DECLARE  v_CurSLA1               		INT; 
               DECLARE  v_PrevSLA1              		INT; 
               DECLARE  v_DiffSLA1Percent       		INT; 
            
     		  DECLARE  v_CurSLA2               			INT; 
               DECLARE  v_PrevSLA2              		INT; 
               DECLARE  v_DiffSLA2Percent       		INT;  
            
     		  DECLARE  v_CurSLA3               			INT; 
               DECLARE  v_PrevSLA3              		INT; 
               DECLARE  v_DiffSLA3Percent       		INT;  
            
        	      DECLARE  v_CurSLA4               		INT; 
               DECLARE  v_PrevSLA4              		INT; 
               DECLARE  v_DiffSLA4Percent       		INT;  
            
        		  DECLARE  v_CurSLA5               		INT; 
               DECLARE  v_PrevSLA5              		INT; 
               DECLARE  v_DiffSLA5Percent       		INT;    
         		
         	   DECLARE  v_CurSLA6               	    INT; 
               DECLARE  v_PrevSLA6              		INT; 
               DECLARE  v_DiffSLA6Percent       		INT; 
           
  			  DECLARE  v_CuransweredSLACount       INT; 
               DECLARE  v_PrevansweredSLACount       INT; 
               DECLARE  v_DiffansweredSLAPercent     INT; 
               
  			 DECLARE  v_CurabandonedSLACount       INT; 
               DECLARE  v_PrevabandonedSLACount      INT; 
               DECLARE  v_DiffabandonedSLAPercent    INT; 
               
  			  DECLARE  v_CurSLAbreachedCount       INT; 
               DECLARE  v_PrevSLAbreachedCount       INT; 
               DECLARE  v_DiffSLAbreachedPercent     INT; 
               
               
  			  DECLARE  v_CurChatTypeCount                   INT; 
               DECLARE  v_PrevChatTypeCount               	INT; 
               DECLARE  v_DiffChatTypePercent             	INT;  
               
        	      DECLARE  v_CurOverdueCount                 	INT;   
        
               
                   
          	 SET v_offset =  p_Limit * p_offset; 
             
             	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
             	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
             	
           	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
           
           	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
           	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
             		
            		   DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
                  	CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
  
       		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
       
          
                             		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                         		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                         		(    DispositionId 			INT
                         			,DispositionStatus 		VARCHAR(100)
                         			,DispositionCategory	TINYINT
                         		); 
                                 
                         		INSERT INTO temp_AvailableDisposition 
                         		SELECT 	did 			DispositionId
                         			,	dispositionName	DispositionStatus
                         			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                         				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
                         				WHEN dispositionName = 'Disconnected'         THEN 4
                  					    WHEN dispositionName = 'Resolved'             THEN 5
                         				END 			DispositionCategory
                         		FROM 	disposition_status
                         		WHERE 	domainId	= p_domainId;          
                               
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;
      CREATE TEMPORARY TABLE temp_AllqueueId   
      SELECT qid, name AS queueName 
      FROM queue 
      WHERE domainId = p_domainId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                              
                       	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
                     	   CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
  						SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		          		 			AS SessionDate
  						 , SDH.QueueId                  
         					 ,	Q.name														                				AS queueName                     
         					 , SDH.Duration                                                                 				AS chatDuration                 
         					 , SDH.Duration												                    				AS Duration
  						 , SH.disconnectedBy  													    				    AS  disconnectedBy
                           ,SH.sessionStartTime
                           , SH.chatHistoryId
  						 ,CASE WHEN  (FROM_UNIXTIME(SH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END AS  Overdue
  						 , CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END 		          						AS Abandoned
                           , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END                						AS Answered
                           ,SDH.answeredDuration
                     	FROM 	tb_ChatHistory 				SH
                     	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
                 		LEFT JOIN 	queue					Q	ON SDH.queueId			= Q.qid  
  					LEFT JOIN temp_queueIDs 			t_Q ON Q.qid = t_Q.queueId 
  					LEFT JOIN temp_AvailableDisposition	t_D	ON SDH.dispositionId	= t_D.DispositionId
  					LEFT JOIN 	disposition_status		DS		ON DS.did					= SDH.dispositionId and DS.domainId = SH.domainId                     
                     	WHERE 	SH.domainId 		= p_domainId
         					AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
  						AND (IFNULL(p_queueId, '') = '' OR (IFNULL(p_queueId, '') <> '' AND t_Q.queueId IS NOT NULL)); 
          
                  	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                             	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                         	SELECT 	
         						    a.SessionDate 				       										                                        AS 'Date'  
                                  ,a.sessionStartTime
       						    ,a.QueueId
                                  ,a.chatHistoryId
       						    ,CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE '-' END											   AS queueName
          						,SUM(a.Duration)                                                                                               AS totalDuration
          					   
                                 ,SUM(case when a.answeredDuration is null then 1 else 0 end)												   AS MissedChats
         						,(CASE WHEN a.chatDuration < 30000  then 1 else 0 END)												           	   AS abondedchats
  							,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)                 	   AS  SL1
         						,SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)             AS  SL2
         						,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL3
         						,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL4
         						,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL5
         						,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL6    
                              ,SUM(CASE WHEN a.chatDuration BETWEEN   1 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)              AS  TotalSLA
                               ,SUM(CASE WHEN a.Overdue = 'Aborted' THEN 1 ELSE 0 END)  															AS Overdue
  							,(a.Answered+a.Abandoned)                             															    AS ChatType
    							FROM temp_ChatHistory a     
  							GROUP BY a.chatHistoryId, a.SessionDate,a.QueueId,a.queueName,a.chatDuration,a.disconnectedBy,a.Overdue,a.sessionStartTime,a.Answered,a.Abandoned;
        
                             DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1; 
                         	CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS 
                             SELECT
                             count(1),
                             a.sessionStartTime,
                             a.Date,
                             a.QueueId,
       						a.queueName,
       						a.chatHistoryId,
       						
                        
                             a.totalDuration,
                             a.SL1,
                             a.SL2,
                             a.SL3,
                             a.SL4,
                             a.SL5,
                             a.SL6,
                             a.TotalSLA,
                             a.MissedChats,
                             a.ChatType,
     						SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END)                    AS answeredSLA,
     					    SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END)                   AS abandonedSLA,    
     						SUM(CASE WHEN Overdue > 0 THEN 1 ELSE 0 END) / COUNT(1) * 100 																		AS SLAbreached							                                 
                           FROM temp_chatHistory_calc a  
                           GROUP BY a.Date,a.sessionStartTime,a.QueueId,a.queueName,a.chatHistoryId,a.totalDuration,a.SL1, a.SL2,a.SL3,a.SL4,a.SL5,a.SL6,a.TotalSLA,a.MissedChats,a.ChatType;
      
         	  SELECT  COUNT(chatHistoryId),	SUM(TotalSLA), SUM(MissedChats) ,sum(ChatType)              														                     				 
               INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats ,v_CurChatTypeCount                           														                      					
               FROM 	temp_chatHistory_calc
               WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
           
           	SELECT 	COUNT(chatHistoryId),SUM(TotalSLA), SUM(MissedChats) ,sum(ChatType)                       																								 
           	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats ,v_PrevChatTypeCount                                 														 										
           	FROM	temp_chatHistory_calc
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
          
            	SELECT 	SUM(IFNULL(Overdue, 0))
           	INTO 	v_CurOverdueCount 
            	FROM	temp_chatHistory_calc
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;
           
         	SELECT 	SUM(IFNULL(totalDuration, 0))
           	INTO 	v_CurrenttotalDurationCount 
          	FROM	temp_chatHistory_calc
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
              
          	SELECT 	SUM(IFNULL(totalDuration, 0))
           	INTO 	v_PretotalDurationCount 
          	FROM	temp_chatHistory_calc
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
              
          
          	SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
          	INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
          	FROM 	temp_chatHistory_calc
          	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
           
         	SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
         	INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
            	FROM	temp_chatHistory_calc
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
              
             SELECT 	SUM(IFNULL(answeredSLA, 0))
        	INTO 	v_PrevansweredSLACount 
        	FROM	temp_chatHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
         	SELECT 	SUM(IFNULL(answeredSLA, 0))
        	INTO 	v_CuransweredSLACount 
            FROM	temp_chatHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
        
         	SELECT 	SUM(IFNULL(abandonedSLA, 0))
        	INTO 	v_PrevabandonedSLACount 
        	FROM	temp_chatHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
        
         	SELECT 	SUM(IFNULL(abandonedSLA, 0))
        	INTO 	v_CurabandonedSLACount 
      	FROM	temp_chatHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
        
      	SELECT 	SUM(IFNULL(SLAbreached, 0))
        	INTO 	v_PrevSLAbreachedCount 
        	FROM	temp_chatHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
     	SELECT 	SUM(IFNULL(SLAbreached, 0))
        	INTO 	v_CurSLAbreachedCount 
       	FROM	temp_chatHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
        
       	
              
     				
         	SET v_PrevTotalCount =       CASE WHEN v_PrevTotalCount = 0 then null else     v_PrevTotalCount end; 
          	SET v_PrevansweredSLACount = CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
           	SET v_PrevabandonedSLACount= CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
          	 SET v_PrevSLAbreachedCount = CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
              
             SET v_DiffTotalPercent 		    = (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
          	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
         	,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
           	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
           
           
             	SELECT * FROM temp_AllqueueId;
              
              
             	SELECT 
                      IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
                      IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                      IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                      IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                      IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
                      IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';  
           
               SELECT
               	  'All Agents'												   							AS queueName
          	  	 ,'Answered'                                                   							AS ChatType
                  ,IFNULL(v_CurSLA1,0)                                          							AS SL1
                  ,IFNULL(v_CurSLA2,0)                                          							AS SL2
                  ,IFNULL(v_CurSLA3,0)                                          							AS SL3
                  ,IFNULL(v_CurSLA4,0)                                          							AS SL4
                  ,IFNULL(v_CurSLA5,0)                                          							AS SL5
                  ,IFNULL(v_CurSLA6,0)                                          							AS SL6
                  ,IFNULL(v_CurTotalSLA,0)                                      							AS Total
                  ,IFNULL(v_CurMissedChats,0)															AS MissedChats
            
                
                 
                  ,0                                                                                   	AS SLAAchieved
                  ,0                                                                                   	AS SLABreached
   
               UNION ALL
           	SELECT 	
                   U.queueName												                                AS queueName
                  ,  'Answered' 																				as ChatType
                  ,	count(b.SL1)
                  ,	count(b.SL2)
          		 ,	count(b.SL3)
          		 ,	count(b.SL4)
          		 ,	count(b.SL5)
          		 ,	count(b.SL6)
                  , sum(b.TotalSLA)
                  ,  sum(b.MissedChats)      																AS MissedChats
                  
                  ,  CASE WHEN sum(b.TotalSLA/b.totalDuration) IS NOT NULL THEN sum(b.TotalSLA/b.totalDuration) ELSE '-' END                                    AS SLAachieved
                  , sum(b.Overdue)/count(1)    																	AS SLAbreached
                  FROM temp_chatHistory_calc b
                  JOIN temp_ChatHistory      a      ON b.chatHistoryId= a.chatHistoryId
          		  LEFT JOIN temp_AllqueueId U 	  ON b.QueueId = U.qid
          	   
                  GROUP BY U.queueName,b.MissedChats,b.ChatType;    
                
            SELECT CONCAT('queueName', 'ChatType', 'SL1', 'SL2', 'SL3', 'SL4', 'SL5', 'SL6', 'Total', 'MissedChats', 'SLAAchieved', 'SLAbreached') AS  columnName;   
           
         	
            END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_servicelevel_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_servicelevel_metrics_filter`(
         		p_startTmpstmp 		BIGINT,
             	p_endTmpstmp 		BIGINT,
             	p_domainId 			INT,
             	p_queueId 			TEXT,
        		    p_offset 			INT,
  			    p_Limit 		    INT	
         	)
sp_return:begin
   			DECLARE v_offset 		     		INT;	
    			DECLARE v_Total_Count 	     		INT;        
 			DECLARE v_startTmpstmp 	     		BIGINT;
 			DECLARE v_endTmpstmp 	     		BIGINT;
 			DECLARE v_currenttimestamp   		DATETIME;
   			DECLARE v_previous_timestamp 		DATETIME;
 			DECLARE v_oneday_previous_timestamp DATETIME;
 			DECLARE v1_count 					INT;
   			DECLARE v2_count					INT;
             
               SET v_offset =  p_Limit * p_offset;
               
   			SET v_currenttimestamp = NOW();
   			SET v_previous_timestamp = DATE_SUB(NOW(), INTERVAL 1 DAY);
   			SET v_oneday_previous_timestamp = DATE_SUB(NOW(), INTERVAL 2 DAY);
                           
                 	IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +3 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
                 	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
                 
         		   DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
               	CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
        
         		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                   
      			 DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
                   CREATE TEMPORARY TABLE temp_AllqueueId
                   SELECT qid,NAME AS queueName from queue where domainId = p_domainId ;
                   
      			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
      			CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
       		 SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		          AS SessionDate
       					 , SDH.QueueId                  
      					 ,	Q.name														                 AS queueName                     
      					 , SDH.Duration                                                                  AS chatDuration                 
      					 , SDH.Duration												                     AS Duration
       					 , SH.disconnectedBy  															 AS  disconnectedBy 
                  	FROM 	tb_ChatHistory 				SH
                  	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
              		LEFT JOIN 	queue					Q	ON SDH.queueId			= Q.qid  
                  	WHERE 	SH.domainId 		= p_domainId	
      				AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
      				AND		SH.IsInBound		= 1	
       				LIMIT 	v_offset, p_Limit; 
         			    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
 				
                     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
                      DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                      	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                      	SELECT 	
      						a.SessionDate 				       										                                       AS 'Date'                  
    						    ,a.QueueId
    						    ,CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE '-' END											   AS queueName
       						,SUM(a.Duration)                                                                                               AS totalDuration
       					    ,(CASE WHEN a.chatDuration > 30000  then 1 else 0 END)								                           AS MissedChats  
      						,(CASE WHEN a.chatDuration < 30000  then 1 else 0 END)												           AS abondedchats
                              ,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL1
      						,SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         AS  SL2
      						,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL3
      						,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL4
      						,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL5
      						,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        AS  SL6                                   
 							FROM temp_ChatHistory a     
                             GROUP BY a.SessionDate,a.QueueId,a.queueName,a.chatDuration,a.disconnectedBy;
                      
 			SELECT * FROM temp_AllqueueId;
 			SELECT 	COUNT(1) v_Total_Count FROM temp_chatHistory_calc a;  
 			SELECT COUNT(1)   v1_count  FROM tb_ChatHistory 
  			WHERE p_startTmpstmp >= v_previous_timestamp AND p_endTmpstmp < v_currenttimestamp ; 
 
          SELECT COUNT(1)  
  			 v2_count 
  			FROM tb_ChatHistory 
  			WHERE p_startTmpstmp >= v_oneday_previous_timestamp AND p_endTmpstmp < v_previous_timestamp; 
           
          DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1;
          CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS
          SELECT
          a.queueName,
          SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                           as TotalSLA,
          a.MissedChats
          FROM
              temp_chatHistory_calc a
   		GROUP BY a.queueName,a.MissedChats;
   				
                   IF NOT EXISTS(SELECT 1 FROM temp_chatHistory_calc1 LIMIT 1) THEN
   				SELECT '-' as queueName, 0 AS answeredSLA, 0 AS answeredslaincreasedBy, 0 AS abandonedSLA,0 AS abandonedslaincreasedBy,0 AS SLAbreached, 0 AS SLAbreachedincreasedBy;
   				LEAVE sp_return;
   				END IF;
          SELECT
               IFNULL(a.queueName ,0)                                   	                                                                                   AS queueName,
  			  IFNULL(SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END),0)                   AS answeredSLA,
               IFNULL(((v1_count - v2_count) / v1_count * 100),0) 																				 		   AS answeredslaincreasedBy,
               IFNULL(sum(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END),0)                  AS abandonedSLA,
               IFNULL(((v1_count - v2_count) / v1_count * 100),0)                                                                                		   AS abandonedslaincreasedBy,
               IFNULL(sum(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1  ELSE (a.MissedChats / (a.TotalSLA + a.MissedChats)) * 100 END),0)              AS SLAbreached,
  			  IFNULL(((v1_count - v2_count) / v1_count * 100),0)                                                                                  		   AS SLAbreachedincreasedBy
  
          FROM
              temp_chatHistory_calc1 a
              GROUP BY a.queueName ;
        
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_chat_servicelevel_metrics_filter_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_chat_servicelevel_metrics_filter_1`(
          		p_startTmpstmp 		BIGINT,
              	p_endTmpstmp 		BIGINT,
              	p_domainId 			INT,
              	p_queueId 			TEXT,
				p_offset 			INT,
   			    p_Limit 		    INT	
          	)
sp_return:begin
    			DECLARE v_offset 		     		INT;	
     			DECLARE v_Total_Count 	     		INT;        
  			DECLARE v_startTmpstmp 	     		BIGINT;
  			DECLARE v_endTmpstmp 	     		BIGINT;
  			DECLARE v_currenttimestamp   		DATETIME;
    			DECLARE v_previous_timestamp 		DATETIME;
  			DECLARE v_oneday_previous_timestamp DATETIME;
  			DECLARE v1_count 					INT;
    			DECLARE v2_count					INT;
              
                SET v_offset =  p_Limit * p_offset;
                
    			SET v_currenttimestamp = NOW();
    			SET v_previous_timestamp = DATE_SUB(NOW(), INTERVAL 1 DAY);
    			SET v_oneday_previous_timestamp = DATE_SUB(NOW(), INTERVAL 2 DAY);
                            
                  	IF IFNULL(p_startTmpstmp,0) = 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +3 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
                  	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
                  
          		   DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
                	CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
         
          		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                    
       			 DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
                    CREATE TEMPORARY TABLE temp_AllqueueId
                    SELECT qid,NAME AS queueName from queue where domainId = p_domainId ;
                    
       			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                 	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
       			CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
        		 SELECT 	CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		          AS SessionDate
        					 , SDH.QueueId                  
       					 ,	Q.name														                 AS queueName                     
       					 , SDH.Duration                                                                  AS chatDuration                 
       					 , SDH.Duration												                     AS Duration
        					 , SH.disconnectedBy  															 AS  disconnectedBy 
                   	FROM 	tb_ChatHistory 				SH
                   	JOIN 	tb_ChatDurationHistory		SDH	ON SH.chatHistoryId 	= SDH.chatHistoryId     
               		LEFT JOIN 	queue					Q	ON SDH.queueId			= Q.qid  
                   	WHERE 	SH.domainId 		= p_domainId	
       				AND 	SH.sessionStartTime  BETWEEN @v_startTmpstmp and @v_endTmpstmp 
       				AND		SH.IsInBound		= 1	
        				LIMIT 	v_offset, p_Limit; 
          			    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  				
                      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
                       DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                       	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                       	SELECT 	
       						    a.SessionDate 				       										                                           AS 'Date'                  
     						    ,a.QueueId
     						    ,CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE '-' END											   AS queueName
        						,SUM(a.Duration)                                                                                               AS totalDuration
        					    ,(CASE WHEN a.chatDuration > 30000  then 1 else 0 END)								                           AS MissedChats  
       						,(CASE WHEN a.chatDuration < 30000  then 1 else 0 END)												           	   AS abondedchats
							,SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)                 AS  SL1
       						,SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)             AS  SL2
       						,SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL3
       						,SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL4
       						,SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL5
       						,sum(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)            AS  SL6                                   
  							FROM temp_ChatHistory a     
                              GROUP BY a.SessionDate,a.QueueId,a.queueName,a.chatDuration,a.disconnectedBy;
                       
  			SELECT * FROM temp_AllqueueId;
  			SELECT 	COUNT(1) v_Total_Count FROM temp_chatHistory_calc a;  
  			SELECT COUNT(1)   v1_count  FROM tb_ChatHistory 
   			WHERE p_startTmpstmp >= v_previous_timestamp AND p_endTmpstmp < v_currenttimestamp ; 
  
           SELECT COUNT(1)  
   			 v2_count 
   			FROM tb_ChatHistory 
   			WHERE p_startTmpstmp >= v_oneday_previous_timestamp AND p_endTmpstmp < v_previous_timestamp; 
            
           DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1;
           CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS
           SELECT
           a.queueName,
           SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                           as TotalSLA,
           a.MissedChats
           FROM
               temp_chatHistory_calc a
    		GROUP BY a.queueName,a.MissedChats;
    				
                    IF NOT EXISTS(SELECT 1 FROM temp_chatHistory_calc1 LIMIT 1) THEN
    				SELECT '-' as queueName, 0 AS answeredSLA, 0 AS answeredslaincreasedBy, 0 AS abandonedSLA,0 AS abandonedslaincreasedBy,0 AS SLAbreached, 0 AS SLAbreachedincreasedBy;
    				LEAVE sp_return;
    				END IF;
           SELECT
                IFNULL(a.queueName ,0)                                   	                                                                                   AS queueName,
				IFNULL(SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END),0)                     AS answeredSLA,
                IFNULL(((v1_count - v2_count) / v1_count * 100),0) 																				 		       AS answeredslaincreasedBy,
                IFNULL(sum(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END),0)                    AS abandonedSLA,
                IFNULL(((v1_count - v2_count) / v1_count * 100),0)                                                                                		       AS abandonedslaincreasedBy,
                IFNULL(sum(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1  ELSE (a.MissedChats / (a.TotalSLA + a.MissedChats)) * 100 END),0)                AS SLAbreached,
				IFNULL(((v1_count - v2_count) / v1_count * 100),0)                                                                                  		   AS SLAbreachedincreasedBy
   
           FROM
               temp_chatHistory_calc1 a
               GROUP BY a.queueName ;
         
         select * from temp_chatHistory_calc;
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
