CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CheckChatIPAddress`(	p_domainId		INT
	,p_IPAdress		VARCHAR(250)
)
BEGIN
	DECLARE p_isExists	TINYINT DEFAULT 0;
    
	IF EXISTS (	select 1 
				from 	tb_ChatHistory
                WHERE 	domainId 	= p_domainId
                AND 	IPAdress	= p_IPAdress
                LIMIT 1)
	THEN
		SET p_isExists = 1;
    END IF;
   
	SELECT p_isExists	AS 'isExists';
END ;;
