CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CheckInsertCustomerContact`(
   	p_phoneNumber	VARCHAR(25)
     ,p_EmailId		VARCHAR(150)
     ,p_domainId		INT  )
BEGIN
  	DECLARE v_errcode     			INT	DEFAULT -1;
  	DECLARE v_errmsg     			VARCHAR(100) DEFAULT 'Adding Number Failed';
  	DECLARE v_coid					INT;		
  	DECLARE v_curdate     			DATETIME; 
  	DECLARE v_primaryPhoneNumber	VARCHAR(25);
  	DECLARE v_primaryEmail			VARCHAR(150);
     
    	SET v_curdate = NOW();     
        
       IF p_phoneNumber IS NOT NULL
       THEN
 			SELECT 	coid
 			INTO 	v_coid
 			FROM 	customer_contact a 
 			WHERE 	a.domainId		= p_domainId
 			AND 	a.primaryPhoneNumber LIKE  p_phoneNumber;    
          
 		if v_coid is null then
 			SELECT 	coid
 			INTO 	v_coid
 			FROM 	customer_contact a 
 			WHERE 	a.domainId		= p_domainId
 			AND 	a.phoneNumber	LIKE  CONCAT('%',p_phoneNumber,'%');  
 		end if;
          
  		SET v_primaryPhoneNumber = p_phoneNumber;         
   	ELSE 
   		IF p_EmailId IS NOT NULL
   		THEN
   			SELECT 	coid
   			INTO 	v_coid
   			FROM 	customer_contact a 
   			WHERE 	a.domainId	= p_domainId
   			AND 	a.primaryEmail	LIKE  p_EmailId;        
              
 			if v_coid is null then
 				SELECT 	coid
 				INTO 	v_coid
 				FROM 	customer_contact a 
 				WHERE 	a.domainId	= p_domainId
 				AND 	a.email		LIKE  CONCAT('%',p_EmailId,'%');  
   			end if;
             
  			SET v_primaryEmail =  p_EmailId;
   		END IF;     
       END IF;     
            
    	sp_exit:BEGIN           
    		IF v_coid IS NOT NULL 
            THEN
    			SET v_errcode 	= 1;
    			SET v_errmsg	= 'Contact is already available';
    		ELSE
    			INSERT INTO customer_contact
                (	primaryPhoneNumber
  				,primaryEmail
  				,phoneNumber
   				,email	
                   ,tags
   				,domainId
   				,createdAt
   				,updatedAt
    			)
                VALUES
                (	v_primaryPhoneNumber
   				,v_primaryEmail
                  ,'[]'
                  ,'[]'
  				,'[]'
   				,p_domainId
   				,v_curdate
   				,v_curdate
    			);
                
   			SET v_errcode 	= 0;
   			SET v_errmsg	= 'Contact added successfully';
    		END IF;
    	END; 
        
   	SELECT v_errcode AS errcode,v_errmsg AS errmsg;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
