CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CheckUserReady`(	p_UserId	BIGINT
 	,p_domainId	INT)
BEGIN	
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	U.UserID
  		,	U.UserName        
 		,	U.domainId
 		,	U.ext
 	FROM 	tb_User 		U
 	JOIN 	agent_status 	A_S	ON 	U.StatusID 		= A_S.aid    
 								AND A_S.domainId	= U.domainId
 								AND A_S.statusName 	= 'Ready'	
     WHERE 	U.UserID 	= p_UserId
     AND 	U.domainId	= p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
