CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CheckUserReadyForSocialMedia`(	
  	p_UserId		BIGINT
	,p_domainId		INT
    ,p_SessionId	VARCHAR(250)
    ,p_ChannelType	INT)
BEGIN	
   	DECLARE v_UserId		BIGINT;
	DECLARE v_ReadyUserId	BIGINT;
       
    SET v_UserId = IF(p_UserId= -1,NULL,p_UserId);
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	U.UserID INTO v_ReadyUserId
  	FROM 	tb_User 			U
  	JOIN 	agent_status 		A_S	ON 	U.StatusID 		= A_S.aid    
  									AND A_S.domainId	= U.domainId
  									AND A_S.statusName 	= 'Ready'	
  	LEFT JOIN 	tb_DeclinedUser	DU 	ON 	DU.SessionId	= p_SessionId
  									AND DU.ChannelType	= p_ChannelType
  									AND DU.UserId		= U.UserID
  	WHERE 	U.UserID 	= IFNULL(v_UserId,U.UserID)
  	AND 	U.domainId	= p_domainId
  	AND		U.roleid	= 6 
 	AND 	DU.UserId	IS NULL
  	ORDER BY U.stateTimer ASC LIMIT 1; 
       
   IF v_ReadyUserId IS NULL
   THEN
		SELECT 	U.UserID INTO v_ReadyUserId
		FROM 	tb_User 			U
		JOIN 	agent_status 		A_S	ON 	U.StatusID 		= A_S.aid    
										AND A_S.domainId	= U.domainId
										AND A_S.statusName 	= 'Ready'	
		LEFT JOIN tb_DeclinedUser	DU 	ON 	DU.SessionId	= p_SessionId
										AND DU.ChannelType	= p_ChannelType
										AND DU.UserId		= U.UserID
		WHERE 	U.UserID 	= IFNULL(v_UserId,U.UserID)
		AND 	U.domainId	= p_domainId
		AND		U.roleid	= 5 
		AND 	DU.UserId	IS NULL
		ORDER BY U.stateTimer ASC LIMIT 1; 
   END IF;
   
   IF v_ReadyUserId IS NULL
   THEN
		SELECT 	U.UserID INTO v_ReadyUserId
		FROM 	tb_User 			U
		JOIN 	agent_status 		A_S	ON 	U.StatusID 		= A_S.aid    
										AND A_S.domainId	= U.domainId
										AND A_S.statusName 	= 'Ready'	
		LEFT JOIN tb_DeclinedUser	DU 	ON 	DU.SessionId	= p_SessionId
										AND DU.ChannelType	= p_ChannelType
										AND DU.UserId		= U.UserID
		WHERE 	U.UserID 	= IFNULL(v_UserId,U.UserID)
		AND 	U.domainId	= p_domainId
		AND		U.roleid	= 3 
		AND 	DU.UserId	IS NULL
		ORDER BY U.stateTimer ASC LIMIT 1; 
   END IF;   
       
  	SELECT 	U.UserID
  		,	U.UserName        
  		,	U.domainId
  		,	U.ext
  	FROM 	tb_User 		U	
  	WHERE 	U.UserID = v_ReadyUserId;         
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
