CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_check_login_company_type`(
 p_CompanyId 		INT,
 p_LoggedInUserId	BIGINT
 )
BEGIN
 	DECLARE v_roleid 	TINYINT;
     
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 	SELECT 	InU.roleid 
     INTO 	v_roleid
     FROM 	tb_User InU 
     WHERE 	InU.UserID = p_LoggedInUserId;
     
 	IF EXISTS (	SELECT 	1
 				FROM 	tb_map_customer_serviceprovider
 				WHERE 	customer_company_id = p_CompanyId
                 AND 	is_active			= 1)
 	THEN
 		SELECT 	customer_company_id
 			,	service_company_id
             ,	'Customer'			AS company_type
             ,	v_roleid			AS role_id
         FROM 	tb_map_customer_serviceprovider
 		WHERE 	customer_company_id = p_CompanyId
 		AND 	is_active	= 1;
 	ELSE
 		SELECT 	NULL				AS customer_company_id
 			,	p_CompanyId			AS service_company_id
             ,	'Serviceprovider'	AS company_type
             ,	v_roleid			AS role_id;
     END IF;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
