CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CloneTickets`(
     p_TicketId 				INT
     ,p_TicketSubject		VARCHAR(500)
     ,p_TicketDescription	TEXT
     ,p_CompanyId 			INT
     ,p_ProductId 			INT
     ,p_LoggedInUserId		INT
      )
BEGIN
     	DECLARE v_errcode  		INT DEFAULT -1;
      DECLARE v_errmsg   		VARCHAR(55) DEFAULT 'Ticket Not exists';
     	DECLARE v_CurDate		DATETIME;
      DECLARE v_JLength		INT;
      DECLARE v_TicketId		INT;
     
     	SET v_CurDate = NOW();    
      
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
     	INSERT INTO tb_TicketDetails
         (		CompanyId
  			,	ProductId
             , 	TicketSubject
             , 	TicketSourceId
             ,	TicketStatusId
             , 	TicketTypeId
             , 	PriorityId
             , 	RequestorId
             , 	AssignedToTeamId
             , 	AssignedToGroupId
             , 	AssignedToAgentId
             , 	TagId
             , 	TicketTagIdName
             , 	ResponseDueDate
             , 	ResolutionDueDate
             , 	TicketCreatedBasedOnID
             , 	IsDeleted
             , 	TicketAssignee
             , 	TicketLayout
             , 	TicketDescription        
             , 	TicketMode
     		,	CreatedBy
     		,	CreatedDate
             ,	UpdatedBy
     		,	UpdatedDate
         )
     	SELECT 	CompanyId
     		,	ProductId
             , 	p_TicketSubject
             , 	TicketSourceId
             ,	TicketStatusId
             , 	TicketTypeId
             , 	PriorityId
             , 	RequestorId
             , 	AssignedToTeamId
             , 	AssignedToGroupId
             , 	AssignedToAgentId
             , 	TagId
             , 	TicketTagIdName
             , 	ResponseDueDate
             , 	ResolutionDueDate
             , 	TicketCreatedBasedOnID
             , 	0	IsDeleted
             , 	TicketAssignee
             , 	TicketLayout
             , 	p_TicketDescription        
             , 	TicketMode
             ,	p_LoggedInUserId
             ,	v_CurDate
             ,	p_LoggedInUserId
             ,	v_CurDate        
         FROM 	tb_TicketDetails TD
         WHERE 	TicketId	= p_TicketId; 	  
         
         SET v_TicketId = last_insert_id();
         
         INSERT INTO tb_TicketTagMapping
         (	TicketId
     		,TicketTagId	
             ,CreatedDate        
         )
         SELECT 	v_TicketId
     		,	TicketTagId
             ,	v_CurDate
         FROM 	tb_TicketTagMapping TM
         WHERE 	TM.TicketId = p_TicketId;
         
         INSERT INTO tb_TicketComments
         (	TicketId				
             ,Comments				        
             ,IsDeleted				
             ,CreatedBy				
             ,CreatedDate			
             ,UpdatedBy				
             ,UpdatedDate			
         )
         VALUES
         (	v_TicketId
     		,CONCAT('Copied from the Ticket ', p_TicketId)
             ,0
             ,p_LoggedInUserId
             ,v_CurDate
             ,p_LoggedInUserId
             ,v_CurDate  
         );
         
         IF row_count() > 0
         THEN
     		SET v_errcode = 0;
     		SET v_errmsg  = 'Cloned Successfully';
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     	END IF;
         
         SELECT v_errcode errcode, v_errmsg errmsg;
         
     END ;;
DELIMITER ;
