CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Clone_Chat_Configuration_Primary_Form`(
  p_aid   			INT,
  p_title 			VARCHAR(100),
  p_webchatid		VARCHAR(20),
  p_codeSnippet		VARCHAR(2000)
 )
BEGIN
        DECLARE v_errcode 	INT DEFAULT -1;
        DECLARE v_errmsg 	VARCHAR(55);
        DECLARE v_CurDate	DATETIME;
    
        SET v_CurDate= NOW();
        SET v_errcode = -1;
        SET v_errmsg = 'Clone Unsuccessfully';     
        
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
        INSERT INTO chat_configuration_primary_form
        (	domainId ,createdAt,updateddAt,title,description,chatFlowId,chatFlowId_OLD,chatIconLogo,domain,isDeleted,personalization,primaryForm,callFlowName,preChartFormFlag,webchatid,
			codeSnippet,websiteId,status,formDetails,greeting,templateData,plan_id,product_id,autoResponse)
