				p_codeSnippet,websiteId,0,formDetails,greeting,templateData,plan_id,product_id,autoResponse
		 FROM 	chat_configuration_primary_form
		 WHERE 	aid = p_aid;
 
 		  IF ROW_COUNT() > 0 THEN
            SET v_errcode = 0;
