CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_connector_install_based_domain`(
             p_domainId   INT 
             )
BEGIN
           	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 				SELECT a.conid AS conId, a.connector_name, a.imageUrl, b.idcol,
                 b.domainId, b.roleId, b.token, b.contactSyncDetails, 
 				b.syncStatus, b.syncTime, b.contactSyncType, b.isConnected 
 				FROM ccaas_connectors_list a
 				LEFT JOIN ccaas_crm_connector_token_info b ON a.conid = b.conId AND b.domainId = p_domainId AND b.isConnected = 1
				WHERE a.isrunning = 1
 				UNION
 				SELECT 
 				a.conid AS conId, a.connector_name, a.imageUrl, b.idcol, 
 				b.domainId, b.roleId, b.token, b.contactSyncDetails, 
 				b.syncStatus, b.syncTime, b.contactSyncType,b.isConnected
 				FROM ccaas_connectors_list a
 				RIGHT JOIN ccaas_crm_connector_token_info b ON a.conid = b.conId WHERE b.domainId = p_domainId AND b.isConnected = 1 
                 AND a.isrunning = 1
                 order by conId asc;
               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       END ;;
DELIMITER ;
