CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CreateTicketApproval`(
   p_TicketApprovalId 		BIGINT,
   P_TicketId			    BIGINT,
   p_CompanyId				INT,
   p_ProductId				INT,
   p_ApprovingUserDetails 	JSON,
   p_subject 				VARCHAR(250),
   p_AdditionalDetails 	TEXT,
   p_ApprovedById          INT,
   p_LoggedInUserID 		BIGINT
     )
BEGIN 
     	declare v_errcode 				int;
      	declare v_errmsg 				varchar(55);
        declare v_CurDate				DATETIME;
        declare v_TicketApprovalId		BIGINT;
       
    	DECLARE v_JLength				SMALLINT;
         
    	SET v_CurDate = NOW();
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
     	sp_exit : begin
     		SELECT TicketApprovalId into v_TicketApprovalId
    					FROM tb_TicketApproval
    					WHERE TicketApprovalId = p_TicketApprovalId;
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
             IF v_TicketApprovalId IS NULL
             THEN
    		    INSERT INTO tb_TicketApproval 
    			(TicketId, 
                 CompanyId, 
                 ProductId, 
                 `subject`, 
                 AdditionalDetails, 
                 ApprovalCancelComments, 
                 ApprovedById,
                 IsCancelled, 
                 CreatedBy, 
                 CreatedDate, 
                 UpdatedBy, 
                 UpdatedDate)
    			VALUES 
    			(p_TicketId,
                 p_CompanyId, 
    			 p_ProductId, 
    			 p_subject, 
   			 p_AdditionalDetails,
    			 NULL,
                p_ApprovedById,
                 0,
    			 p_LoggedInUserID, 
    			 v_CurDate, 
    			 p_LoggedInUserID, 
    			 v_CurDate);
                 
                 SET v_TicketApprovalId = last_insert_id(); 
                 
    			 SET v_JLength = JSON_LENGTH(p_ApprovingUserDetails, "$");
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    			 DROP TEMPORARY TABLE IF EXISTS tt_TicketUser;
    			 CREATE TEMPORARY TABLE tt_TicketUser       
    	         WITH RECURSIVE  CTE_JsonCount as
    	         (	SELECT 	0 SlNo
    		        UNION ALL
    		        SELECT 	SlNo + 1	SlNo
    				FROM 	CTE_JsonCount
    			    WHERE 	SlNo  < v_JLength - 1
    	         )
    	        SELECT  TRIM(BOTH '"' FROM (json_extract(p_ApprovingUserDetails, concat('$[',SlNo,'].UserId')))) 		AS UserId,
    			TRIM(BOTH '"' FROM (json_extract(p_ApprovingUserDetails, concat('$[',SlNo,'].UserName')))) 	    AS UserName
    	        FROM CTE_JsonCount;           
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
    			UPDATE 	tb_TicketUser	TU
                JOIN 	tt_TicketUser	T_U	ON T_U.UserId = TU.UserId
                SET 	TU.UserName		=	T_U.UserName
    				   ,TU.UpdatedBy	=   p_LoggedInUserId
    				   ,TU.UpdatedDate	=   v_CurDate;  
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;          
    			INSERT INTO tb_TicketUser
    			(	UserId		
                   ,UserName	        
    				,CompanyId	
    				,ProductId	
    				,CreatedBy	
    				,CreatedDate
    				,UpdatedBy	
    				,UpdatedDate
                )
    			SELECT 	T_U.UserId
    					,T_U.UserName
    					,p_CompanyId
    					,p_ProductId
    					,p_LoggedInUserId
    					,v_CurDate
    					,p_LoggedInUserId
    					,v_CurDate            
    		   FROM 	tt_TicketUser		T_U
              LEFT JOIN tb_TicketUser		U		ON T_U.UserId = U.UserId
    		   WHERE    U.UserId IS NULL;
               
               INSERT INTO	tb_TicketApprovalUserMapping
               (
               TicketApprovalId, 
               TicketId, 
               CompanyId, 
               ProductId, 
               ApprovingUserId, 
               IsApproved, 
               IsCancelled, 
               ApprovalCancelComments, 
               CreatedBy, 
               CreatedDate, 
               UpdatedBy, 
               UpdatedDate
               )
               SELECT 
    		   v_TicketApprovalId, 
    		   P_TicketId, 
    		   p_CompanyId, 
    		   p_ProductId, 
    		   UserId, 
    		   0, 
    		   0, 
    		   NULL, 
    		   p_LoggedInUserID, 
    		   v_CurDate, 
    		   p_LoggedInUserID, 
    		   v_CurDate
   			FROM 	  tt_TicketUser;	
               
               if row_count() > 0
    			then
    				set v_errcode = 0;
    				set v_errmsg = 'Inserted successfully';				
    			end if;			
    		end if;
     	end sp_exit; 
         DROP TEMPORARY TABLE IF EXISTS tt_TicketUser;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                   
     	select v_errcode as errcode, v_errmsg as errmsg;
     end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
