CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_CreationTicketMergeOrSplitInfo`(
   p_CompanyId bigint,
   p_ProductId int,
   p_TicketID int,
   p_MergingWithTicket int,
   p_type int 
   )
Begin
   
   	Declare v_errcode int default '-1';
   	Declare v_errmsg varchar(50) default 'Failure';
       Declare v_MergedWith int;
       
      spexit:Begin  
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		if not exists(select * from tb_TicketDetails a where a.TicketId = p_TicketID limit 1) then
   			set v_errcode = -1;
   			set v_errmsg = 'TicketID is not found';
   			Leave spexit;
   		End if;
       
   	   if p_type = 1 then		
   			
   			if exists(select * from tb_TicketDetails a where a.TicketId = p_TicketID and (a.MergedWith is not null and a.MergedWith<>0) limit 1) then
   			
   				select a.MergedWith into v_MergedWith from tb_TicketDetails a where a.TicketId = p_TicketID and (a.MergedWith is not null and a.MergedWith<>0);
   				
   				set v_errcode = -1;
   				set v_errmsg = concat('TicketID is Already Merged with - ',v_MergedWith);
   				Leave spexit;
   			End if;
   			
   			update tb_TicketDetails a 
   			set a.MergedWith = p_MergingWithTicket
   			where a.TicketId = p_TicketID;
   			
   			if row_count() > 0 then
   				set v_errcode = 0;
   				set v_errmsg = concat('TicketID - ',p_MergingWithTicket,' is Merged with - ',p_TicketID);
                   Leave spexit;
   			End if;
   		End if;
           
           if p_type = 2 then
            
   			if exists(select * from tb_TicketDetails a where a.TicketId = p_TicketID and a.MergedWith is null or a.MergedWith=0 limit 1) then
   				set v_errcode = 0;
   				set v_errmsg = concat('TicketID is Not currently Merged with other ticket');
   				Leave spexit;
   			End if;
            
   			update tb_TicketDetails a 
   			set a.MergedWith = null
   			where a.TicketId = p_TicketID;
               
               if row_count() > 0 then
   				set v_errcode = 0;
   				set v_errmsg = 'Success - Merged Ticket is Removed';
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   			End if;
       
            End if;
       
   	End;
       
   		select v_errcode as errcode, v_errmsg as errmsg;
   
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
