CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_dashboardAgentStatus`( 
        p_domainId		INT	
        ,p_UserID		INT
        )
BEGIN

  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     	DROP TEMPORARY TABLE if exists temp_AgentStatus;
     	CREATE TEMPORARY TABLE temp_AgentStatus	
     	WITH CTE_Status AS
     	(	SELECT 	A_S.statusName
     			,	A_S.aid	AS StatusID	
     			,	CASE	WHEN statusName = 'Not Ready' 		THEN 1
     						WHEN statusName = 'Transfer Only' 	THEN 2
     						WHEN statusName = 'Offline' 		THEN 3
     						WHEN statusName = 'Ready' 			THEN 4
     						WHEN statusName = 'Busy' 			THEN 5
     						WHEN statusName = 'Away' 			THEN 6                    
     						ELSE 7
     				 END 	AS statusCategory
     		FROM 	agent_status A_S
     		WHERE 	domainId 	= p_domainId AND isDeleted = 0   
     	)
     	 SELECT 	C_S.statusName
     			,	C_S.statusCategory
     			,	IFNULL(SUM(U.isActive),0)	AS noOfAgent   
     	FROM 	CTE_Status	C_S
     	LEFT JOIN tb_User	U	ON 	U.StatusID 	= C_S.StatusID
     							AND U.domainId	= p_domainId
                                AND (U.UserID =p_UserID OR IFNULL(p_UserID, '')= '')
		AND roleid IN (3,5,6)
     	GROUP BY C_S.statusName, C_S.statusCategory;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     	        
     	  DROP TEMPORARY TABLE if exists temp_AgentStatus1;
     	  CREATE TEMPORARY TABLE temp_AgentStatus1	        
     	  SELECT 	* 
     	  FROM	temp_AgentStatus t1;
          
     	  INSERT INTO temp_AgentStatus1
     	  SELECT 	'Total'	AS statusName 
     		,	8		    AS statusCategory
     		,	(SELECT IFNULL(SUM(noOfAgent),0) FROM temp_AgentStatus)	AS noOfAgent;
		
     	  SELECT 	t1.statusName
				,	t1.noOfAgent
				, 	t2.colorCode
     	  FROM 	temp_AgentStatus1 t1
          LEFT join agent_status t2 ON t1.statusName = BINARY t2.statusName AND t2.domainId = p_domainId
     	  ORDER BY statusCategory, statusName;   
                    
			SELECT COUNT(DISTINCT ST.ext) AS allAgent
			FROM tb_User U 
			INNER JOIN state_timer ST ON ST.ext = U.ext AND ST.domainId = U.domainId
			WHERE ST.domainId = p_domainId
			AND DATE(ST.createdAt) = CURDATE();
            
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_dashboardAgentStatus_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
