CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_DashboardAverage`(
	 p_startTmpstmp		BIGINT
	,p_endTmpstmp		BIGINT
    ,p_channelType 		VARCHAR(100) 
    ,p_domainId 		INT
	,p_Timezone      	VARCHAR(55)
    ,p_agentId          INT
   )
sp_return: begin
   
	DECLARE v_ext 				INT;
	DECLARE v_roleid 			VARCHAR(50);
	DECLARE v_emailId 			VARCHAR(250);
   
   	DECLARE v_startTmpstmp 		BIGINT;
   	DECLARE v_endTmpstmp 		BIGINT;
   	DECLARE v_curDate			DATETIME DEFAULT CURRENT_DATE();
       
   	DECLARE v_totalSocialMedia 				INT;
   	DECLARE v_totalChats 					INT;
   	
   	DECLARE v_blockCustomer 			INT;
   	DECLARE v_totalCustomer 			INT;
   	DECLARE v_totalTime 				INT;
   	
   	DECLARE v_queueDuration				INT;
   	DECLARE v_totalSessions 			INT;
   	DECLARE v_firstResponseTime 		BIGINT;
   	DECLARE v_totalDuration 			BIGINT;
   	DECLARE v_totalAnsweredCount 		BIGINT;
   	DECLARE v_avgSpeedOfAnswer 			BIGINT;
   	DECLARE v_avgHandlingTime 			BIGINT;
   	DECLARE v_totalACW 					BIGINT;
   	DECLARE v_totalCount 				BIGINT;
   	DECLARE v_occupancyRate 			BIGINT;
   	DECLARE v_noOfIsMissed 				BIGINT;
   	DECLARE v_noOfDeclined 				INT;
   	DECLARE v_totalTransaferInteraction 	INT;
       
   	DECLARE v_UserName 			VARCHAR(150);
   	DECLARE v_isVoice 			TINYINT;
   	DECLARE v_isChat 			TINYINT;
   	DECLARE v_isEmail 			TINYINT;
   	DECLARE v_isSms 			TINYINT;
   	DECLARE v_isSocialMedia 	TINYINT;
	DECLARE v_totalThresholdTime 		BIGINT;
   	DECLARE v_serviceLevel 				INT;
   	DECLARE v_AnsDuration 				INT;
   	DECLARE v_totalHoldTime 			INT;
   	DECLARE v_resolvedQueries 			INT;
   	DECLARE v_Minute 					INT;
   	DECLARE v_NoOfQueueSession 			INT;
    
    DECLARE v_channelType VARCHAR(100);
    SET 	v_channelType = p_channelType;
   
	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = UNIX_TIMESTAMP(CURDATE()) * 1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
	IF IFNULL(p_endTmpstmp,0)	=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
   
	SET v_Minute = TIMESTAMPDIFF(MINUTE, FROM_UNIXTIME(p_startTmpstmp/1000), FROM_UNIXTIME(p_endTmpstmp/1000));
    
    DROP TEMPORARY TABLE IF EXISTS tt_userDtl;
    CREATE TEMPORARY TABLE tt_userDtl(UserID int , UserName varchar(150) , domainId int, roleid int);
    
    INSERT INTO tt_userDtl (UserID, UserName, domainId, roleid) 	
    SELECT UserID, UserName, domainId, roleid  FROM tb_User WHERE domainId = p_domainId AND (UserId = p_agentId OR IFNULL(p_agentId,'') = '')  ;

	
	
		
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory;
            
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal_final;
			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_cal_final;
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_cal_final; 
   
       IF (v_channelType = 'All' OR v_channelType = 'Call')
       THEN
   		CREATE TEMPORARY TABLE temp_CallHistory AS
   		SELECT 
				CH.CallHistoryId
				,CH.sessionStartTime
				,CH.sessionEndTime
				,CH.domainId
				,CH.IsInBound
				,CH.waitDuration
				,CH.CustomerId
				,CH.voicemailUrl
				,CH.callBack
				,CDH.CallDurationHistoryId
				,CDH.Duration
				,CDH.AgentId
				,CDH.dispositionId
				,CDH.afterCallWorkTime
				,CH.callCost
				,CDH.AgentHoldDuration
				,CDH.IsBot
				,CH.queueDuration
				,CDH.IsMissedCall
				,CH.IsAbandoned
				,CDH.answeredDuration
   		FROM 	tb_CallHistory 	CH
   		JOIN 	tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId
   		WHERE 	CH.domainId = p_domainId
   		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		CDH.AgentId IN (SELECT UserID FROM tt_userDtl);

   		CREATE TEMPORARY TABLE temp_CallHistory_cal AS
   		SELECT 
				count(CallHistoryId) as totalCalls
				,sum(case when IsInBound  = 1 then 1 else 0 end) as totalInboundCalls
				,sum(case when IsInBound  = 0 then 1 else 0 end) as totalOutboundCalls
				,sum(case when callBack = 1 then 1 else 0 end) as callCallBack
				,sum(case when voicemailUrl IS NOT NULL AND voicemailUrl like '%voicemail%' then 1 else 0 end) as totalVoiceMail
				,sum(case when DS.dispositionName = 'Caller Disconnected' then 1 else 0 end) as totalAbandonCalls
				,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredCalls
				,sum(case when DS.dispositionName = 'Transferred' then 1 else 0 end) as totalCallTransferCount
				,sum(case when IFNULL(Duration,0) > 0 then Duration	else 0 end) as totalCallDurationAnswered 
				,sum(case when IFNULL(Duration,0) > 0 then afterCallWorkTime else 0 end) as totalCallACWTimeAnswered
				,sum(case when IFNULL(Duration,0) > 0 then AgentHoldDuration else 0 end) as totalCallHoldTime
				,sum(case when IFNULL(callCost,0) > 0 then callCost else 0 end) as totalCallCost
				,sum(queueDuration) as queueDuration
				,sum(AgentHoldDuration) as AgentHoldDuration
				,sum(case when IFNULL(IsMissedCall,0)  = 1 then 1 else 0 end) as isMissed
				,sum(case when IFNULL(IsAbandoned,0)   = 1 then 1 else 0 end) as IsAbandoned
				,sum(case when IFNULL(answeredDuration,0) > 0 then answeredDuration else 0 end) as answeredDurationCall
                ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as callResolved
                ,sum(case when IFNULL(queueDuration,0) > 0 then 1 else 0 end) as callQueueSession
			FROM 		temp_CallHistory CH
			LEFT JOIN 	disposition_status		DS 	ON DS.did = CH.dispositionId
			WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
			CREATE TEMPORARY TABLE temp_CallHistory_cal_final AS
			SELECT 
				totalCalls as totalCalls
				,totalInboundCalls as totalInboundCalls
				,totalOutboundCalls as totalOutboundCalls
				,callCallBack
				,totalVoiceMail as totalVoiceMail
				,totalAnsweredCalls
				,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalAbandonCalls / totalAnsweredCalls) * 100 END as callAbandonRates
				,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalCallCost / totalAnsweredCalls) END  as costPerCall
				,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalCallTransferCount / totalAnsweredCalls) * 100 END  as callsTransferRate
				,(totalCallDurationAnswered+(totalCallACWTimeAnswered*1000)) as overallCallAnsweredDuration
				,AgentHoldDuration
				,totalCallDurationAnswered
				,CASE WHEN v_totalTime = 0 THEN 0 ELSE floor(totalInboundCalls/v_totalTime) END as callArrivalRate
				,totalCallACWTimeAnswered
				,queueDuration			 
				,CASE WHEN totalCalls = 0 THEN 0 ELSE (totalCallHoldTime/totalCalls) END as avgHoldTime
				,isMissed AS callIsMissed
				,IsAbandoned AS callIsAbandoned
				,answeredDurationCall
				,totalCallTransferCount
                ,totalCallHoldTime
                ,callResolved
                ,callQueueSession
   		FROM temp_CallHistory_cal;
	END IF;
   
   IF (v_channelType = 'All' OR v_channelType = 'Chat')
	THEN
   		CREATE TEMPORARY TABLE temp_ChatHistory AS
   		SELECT
   				CH.ChatHistoryId
   				,CH.sessionStartTime
   				,CH.sessionEndTime
   				,CH.chatFlowSourceId
   				,CH.domainId
   				,CH.IsInBound
   				,CH.CustomerId
   				,CH.CallBackStatus
   				,CDH.ChatDurationHistoryId
   				,CDH.Duration
   				,CDH.AgentId
   				,CDH.dispositionId
   				,CDH.afterChatWorkTime
				,CDH.IsBot
				,CH.queueDuration
				,CDH.IsMissed
				,CDH.IsAbandoned
				,CDH.answeredDuration
   		FROM 	tb_ChatHistory 	CH
   		JOIN 	tb_ChatDurationHistory 	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId 
   		WHERE 	CH.domainId = p_domainId
   		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		CDH.AgentId IN (SELECT UserID FROM tt_userDtl);   
        
			CREATE TEMPORARY TABLE temp_ChatHistory_cal AS
			SELECT 
				count(ChatHistoryId) as totalWebChats
				,sum(case when CallBackStatus = 1 then 1 else 0 end) as chatCallBack
				,sum(case when dispositionId is null then 1 else 0 end) as nonCompleteChat
				,sum(case when DS.dispositionName = 'Caller Disconnected' then 1 else 0 end) as totalAbandonChats
				,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredChats
				,sum(case when IFNULL(Duration,0) > 0 AND DS.dispositionName = 'Transferred' then 1 else 0 end) as totalChatTransferCount
				,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalChatDurationAnswered
				,sum(case when IFNULL(Duration,0) > 0 then afterChatWorkTime else 0 end) as totalChatACWTimeAnswered
				,sum(queueDuration) as queueDuration	
				,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
				,sum(case when IFNULL(IsAbandoned,0)   = 1 then 1 else 0 end) as IsAbandoned
				,sum(case when IFNULL(answeredDuration,0) > 0 then 1 else 0 end) as answeredDurationChat
                ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as chatResolved
                ,sum(case when IFNULL(queueDuration,0) > 0 then 1 else 0 end) as chatQueueSession
				FROM 		temp_ChatHistory 		CH
				LEFT JOIN 	disposition_status		DS 	ON DS.did = CH.dispositionId
				WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
            
			CREATE TEMPORARY TABLE temp_ChatHistory_cal_final AS
			SELECT 
				totalWebChats as totalWebChats
				,chatCallBack as chatCallBack
				,nonCompleteChat as nonCompleteChat
				,totalAbandonChats
				,totalAnsweredChats as totalAnsweredChats
				,totalChatTransferCount
				,totalChatDurationAnswered
				,totalChatACWTimeAnswered
				,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalAbandonChats / totalAnsweredChats) * 100 END as chatAbandonRates
				,CASE WHEN totalWebChats = 0 THEN 0 ELSE (totalAnsweredChats / totalWebChats) * 100 END as chatCompletionRates
				,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalChatTransferCount / totalAnsweredChats) * 100 END  as chatsTransferRate
				,(totalChatDurationAnswered+(totalChatACWTimeAnswered*1000)) as overallChatAnsweredDuration
				,CASE WHEN totalWebChats = 0 THEN 0 ELSE (totalChatDurationAnswered/totalWebChats) END as averageChatDuration 
				,CASE WHEN totalWebChats = 0 THEN 0 ELSE IFNULL((queueDuration/totalWebChats),0) END as averageChatWaitTime  
				,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalChatDurationAnswered/totalAnsweredChats) END as averageChatReplyTime   
				,IFNULL(queueDuration,0) as queueDuration
				,isMissed as chatIsMissed
				,IsAbandoned as chatIsAbandoned
				,answeredDurationChat
                ,chatResolved
                ,chatQueueSession
   		FROM temp_ChatHistory_cal;
	END IF;
    
    IF (v_channelType = 'All' OR v_channelType = 'Email')
	THEN
   		CREATE TEMPORARY TABLE temp_EmailHistory AS
   		SELECT
			EH.EmailHistoryId
			,EH.SessionStartTime
			,EH.SessionEndTime
			,EH.DomainId
			,EH.DispositionId
			,EH.IsInBound
			,EH.AfterEmailWorkTime
			,EH.IsSessionClosed
			,EH.CustomerId
			,EDH.EmailDurationHistoryId
			,EDH.Duration
			,EDH.AgentId
			,EDH.IsBot
			,EC.emailThreshold
		FROM 	tb_EmailHistory EH
		JOIN 	tb_EmailDurationHistory EDH ON EH.EmailHistoryId = EDH.EmailHistoryId 
		JOIN 	email_config EC ON EC.domainId = EH.DomainId
		WHERE 	EH.domainId = p_domainId
		AND 	EH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		EDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_EmailHistory_cal AS
		SELECT   count(EmailHistoryId) as totalEmails
		,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredEmails
		,sum(case when IFNULL(Duration,0) > 0 then AfterEmailWorkTime else 0 end) as totalEmailACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalEmailDurationAnswered
		
		,sum(case when (emailThreshold <= 24) then 1 else 0 end) as answeredDurationEmail
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as emailResolved
		FROM 		temp_EmailHistory 		EH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = EH.DispositionId
		WHERE 	SessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
   		CREATE TEMPORARY TABLE temp_EmailHistory_cal_final AS
   		SELECT 
			totalEmails
			,totalAnsweredEmails
			,answeredDurationEmail
			,(totalEmailDurationAnswered+(totalEmailACWTimeAnswered*1000)) as overallEmailAnsweredDuration
			,totalEmailACWTimeAnswered
			,totalEmailDurationAnswered
			
            ,emailResolved
           FROM temp_EmailHistory_cal;
	END IF;
   
    IF (v_channelType = 'All' OR v_channelType = 'SMS')
	THEN
   		CREATE TEMPORARY TABLE temp_SMSHistory AS
   		SELECT
			SH.SMSHistoryId
			,SH.sessionStartTime
			,SH.sessionEndTime
			,SH.domainId
			,SH.dispositionId
			,SH.IsInBound
			,SH.afterSMSWorkTime
			,SH.IsSessionClosed
			,SH.customerNumber
			,SH.calledNumber
			,SDH.SMSDurationHistoryId
			,SDH.Duration
			,SDH.AgentId
			,SDH.IsBot
		FROM 	tb_SMSHistory 	SH
		JOIN 	tb_SMSDurationHistory 	SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
		WHERE 	SH.domainId = p_domainId
		AND 	SH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		SDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_SMSHistory_cal AS
		SELECT   count(*) as totalSMS
		,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredSMS
		,sum(case when IFNULL(Duration,0) > 0 then afterSMSWorkTime else 0 end) as totalSMSACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalSMSDurationAnswered
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as SMSResolved
		FROM 		temp_SMSHistory SH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = SH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
		CREATE TEMPORARY TABLE temp_SMSHistory_cal_final AS
		SELECT 
			totalSMS
			,totalAnsweredSMS
			,(totalSMSDurationAnswered+(totalSMSACWTimeAnswered*1000)) as overallSMSAnsweredDuration
			,totalSMSACWTimeAnswered
			,totalSMSDurationAnswered
            ,SMSResolved
           FROM temp_SMSHistory_cal;
                              
	END IF;
    
    IF (v_channelType = 'All' OR v_channelType = 'WhatsApp')
	THEN 
   		CREATE TEMPORARY TABLE temp_WhatsappHistory AS
   		SELECT
				WH.WhatsappHistoryId
				,WH.sessionStartTime
				,WH.sessionEndTime
				,WH.domainId
				,WH.dispositionId
				,WH.IsInBound
				,WH.afterwhatsappWorkTime
				,WH.IsSessionClosed
				,WH.isCallback
				,WDH.WhatsappDurationHistoryId
				,WDH.AgentId
				,WDH.Duration
				,WDH.dialDuration
				,WDH.IsBot
				,WDH.IsMissed
		FROM 	tb_WhatsappHistory 	WH
		JOIN 	tb_WhatsappDurationHistory 	WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
		WHERE 	WH.domainId = p_domainId
   		AND 	WH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		WDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_WhatsappHistory_cal AS
		SELECT   count(*) as totalWhatsapp
		,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredWhatsapp
		,sum(case when IFNULL(Duration,0) > 0 then afterwhatsappWorkTime else 0 end) as totalWhatsappACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalWhatsappDurationAnswered
		,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
		,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationWhatsapp
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as WhatsappResolved
		FROM 		temp_WhatsappHistory WH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = WH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
		CREATE TEMPORARY TABLE temp_WhatsappHistory_cal_final AS
		SELECT 
			totalWhatsapp
			,totalAnsweredWhatsapp
			,(totalWhatsappDurationAnswered+(totalWhatsappACWTimeAnswered*1000)) as overallWhatsappAnsweredDuration
			,totalWhatsappACWTimeAnswered
			,isMissed as whatsappIsMissed
			,answeredDurationWhatsapp
			,totalWhatsappDurationAnswered
            ,WhatsappResolved
           FROM temp_WhatsappHistory_cal;
               
   END IF;
   
    IF (v_channelType = 'All' OR v_channelType = 'Facebook')
	THEN   
   		CREATE TEMPORARY TABLE temp_FacebookHistory AS
   		SELECT
				FacebookHistoryId
				,sessionStartTime
				,sessionEndTime
				,domainId
				,dispositionId
				,IsInBound
				,afterFacebookWorkTime
				,IsSessionClosed
				,AgentId
				,Duration
				,isCallback
				,IsBot
				,IsMissed
				,dialDuration
		FROM 	tb_FacebookHistory 
		WHERE 	domainId = p_domainId
		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_FacebookHistory_cal AS
		SELECT   count(FacebookHistoryId) as totalFacebook
		,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationFacebook
		,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredFacebook
		,sum(case when IFNULL(Duration,0) > 0 then afterFacebookWorkTime else 0 end) as totalFacebookACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalFacebookDurationAnswered
        ,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as FacebookResolved
		FROM 		temp_FacebookHistory 	FH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = FH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
   		CREATE TEMPORARY TABLE temp_FacebookHistory_cal_final AS
   		SELECT 
			totalFacebook
			,totalAnsweredFacebook
			,answeredDurationFacebook
			,totalFacebookACWTimeAnswered
			,(totalFacebookDurationAnswered+(totalFacebookACWTimeAnswered*1000)) as overallFacebookAnsweredDuration
			,totalFacebookDurationAnswered
            ,isMissed as facebookIsMissed
            ,FacebookResolved
           FROM temp_FacebookHistory_cal;
                           
   END IF;
   
     IF (v_channelType = 'All' OR v_channelType = 'Instagram')
	THEN    
   		CREATE TEMPORARY TABLE temp_InstagramHistory AS
   		SELECT
				InstagramHistoryId
				,sessionStartTime
				,sessionEndTime
				,domainId
				,dispositionId
				,IsInBound
				,afterInstagramWorkTime
				,IsSessionClosed
				,AgentId
				,Duration
				,IsMissed
				,dialDuration
   		FROM 	tb_InstagramHistory
   		WHERE 	domainId = p_domainId
   		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_InstagramHistory_cal AS
		SELECT   count(InstagramHistoryId) as totalInstagram
		,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationInsta
		,sum(case when IFNULL(Duration,0) > 0 then afterInstagramWorkTime else 0 end) as totalInstagramACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredInstagram
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalInstagramDurationAnswered
        ,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as instagramResolved
		FROM 		temp_InstagramHistory FH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = FH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
		CREATE TEMPORARY TABLE temp_InstagramHistory_cal_final AS
		SELECT 
			totalInstagram
			,totalAnsweredInstagram
			,answeredDurationInsta
			,totalInstagramACWTimeAnswered
			,totalInstagramDurationAnswered
			,(totalInstagramDurationAnswered+(totalInstagramACWTimeAnswered*1000)) as overallInstagramAnsweredDuration
            ,isMissed as instaIsMissed
            ,instagramResolved
           FROM temp_InstagramHistory_cal;
                           
   END IF;

 
         
		IF  p_channelType = 'Call' THEN
			SELECT COALESCE(SUM(totalCalls), 0),COALESCE(SUM(overallCallAnsweredDuration), 0),COALESCE(SUM(totalCallDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredCalls), 0),COALESCE(SUM(totalCallACWTimeAnswered), 0),COALESCE(SUM(answeredDurationCall), 0)
            ,COALESCE(SUM(callIsMissed), 0),COALESCE(SUM(callIsAbandoned), 0),COALESCE(SUM(totalCallTransferCount), 0),COALESCE(SUM(queueDuration), 0)
            ,COALESCE(SUM(totalCallHoldTime), 0),COALESCE(SUM(callResolved), 0),COALESCE(SUM(callQueueSession), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_noOfDeclined 
            ,v_totalTransaferInteraction,v_queueDuration,v_totalHoldTime,v_resolvedQueries,v_NoOfQueueSession
            FROM temp_CallHistory_cal_final;
		ELSEIF p_channelType = 'Chat' THEN
			SELECT COALESCE(SUM(totalWebChats), 0),COALESCE(SUM(overallChatAnsweredDuration), 0),COALESCE(SUM(totalChatDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredChats), 0),COALESCE(SUM(totalChatACWTimeAnswered), 0),COALESCE(SUM(answeredDurationChat), 0)
            ,COALESCE(SUM(chatIsMissed), 0),COALESCE(SUM(chatIsAbandoned), 0),COALESCE(SUM(totalChatTransferCount), 0),COALESCE(SUM(queueDuration), 0)
            ,COALESCE(SUM(chatResolved), 0),COALESCE(SUM(chatQueueSession), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_noOfDeclined 
            ,v_totalTransaferInteraction,v_queueDuration,v_resolvedQueries,v_NoOfQueueSession
            FROM temp_ChatHistory_cal_final;
		ELSEIF p_channelType = 'Email' THEN
			SELECT COALESCE(SUM(totalEmails), 0),COALESCE(SUM(overallEmailAnsweredDuration), 0),COALESCE(SUM(totalEmailDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredEmails), 0),COALESCE(SUM(totalEmailACWTimeAnswered), 0),COALESCE(SUM(answeredDurationEmail), 0),COALESCE(SUM(emailResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_resolvedQueries 
            FROM temp_EmailHistory_cal_final;
		ELSEIF p_channelType = 'SMS' THEN
			SELECT COALESCE(SUM(totalSMS), 0),COALESCE(SUM(overallSMSAnsweredDuration), 0),COALESCE(SUM(totalSMSDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredSMS), 0),COALESCE(SUM(totalSMSACWTimeAnswered), 0),COALESCE(SUM(SMSResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_resolvedQueries 
            FROM temp_SMSHistory_cal_final;
        ELSEIF p_channelType = 'Whatsapp' THEN
        SELECT COALESCE(SUM(totalWhatsapp), 0),COALESCE(SUM(overallWhatsappAnsweredDuration), 0),COALESCE(SUM(totalWhatsappDurationAnswered), 0) 
        ,COALESCE(SUM(totalAnsweredWhatsapp), 0),COALESCE(SUM(totalWhatsappACWTimeAnswered), 0),COALESCE(SUM(answeredDurationWhatsapp), 0)
        ,COALESCE(SUM(whatsappIsMissed), 0),COALESCE(SUM(totalWhatsapp), 0),COALESCE(SUM(WhatsappResolved), 0)
        INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_totalSocialMedia 
        ,v_resolvedQueries
        FROM temp_WhatsappHistory_cal_final;
		ELSEIF p_channelType = 'Facebook' THEN
			SELECT COALESCE(SUM(totalFacebook), 0),COALESCE(SUM(overallFacebookAnsweredDuration), 0),COALESCE(SUM(totalFacebookDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredFacebook), 0),COALESCE(SUM(totalFacebookACWTimeAnswered), 0),COALESCE(SUM(answeredDurationFacebook), 0)
            ,COALESCE(SUM(facebookIsMissed), 0),COALESCE(SUM(totalFacebook), 0),COALESCE(SUM(FacebookResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_totalSocialMedia 
            ,v_resolvedQueries
            FROM temp_FacebookHistory_cal_final;
		ELSEIF p_channelType = 'Instagram' THEN
			SELECT COALESCE(SUM(totalInstagram), 0),COALESCE(SUM(overallInstagramAnsweredDuration), 0),COALESCE(SUM(totalInstagramDurationAnswered), 0)
            ,COALESCE(SUM(totalAnsweredInstagram), 0),COALESCE(SUM(totalInstagramACWTimeAnswered), 0),COALESCE(SUM(answeredDurationInsta), 0)
            ,COALESCE(SUM(instaIsMissed), 0),COALESCE(SUM(totalInstagram), 0),COALESCE(SUM(instagramResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_totalSocialMedia 
            ,v_resolvedQueries
            FROM temp_InstagramHistory_cal_final;
		ELSEIF p_channelType = 'All' THEN
        SELECT 
            COALESCE((SELECT SUM(totalCalls) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWebChats) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalEmails) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalSMS) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWhatsapp) FROM temp_WhatsappHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalFacebook) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalInstagram) FROM temp_InstagramHistory_cal_final), 0)
        INTO v_totalSessions;
        SELECT 
            COALESCE((SELECT SUM(overallCallAnsweredDuration) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallChatAnsweredDuration) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallEmailAnsweredDuration) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallFacebookAnsweredDuration) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallInstagramAnsweredDuration) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallSMSAnsweredDuration) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallWhatsappAnsweredDuration) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_totalDuration;
        SELECT 
            COALESCE((SELECT SUM(totalCallDurationAnswered) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalChatDurationAnswered) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalEmailDurationAnswered) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalFacebookDurationAnswered) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalInstagramDurationAnswered) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalSMSDurationAnswered) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWhatsappDurationAnswered) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_AnsDuration;
        SELECT 
            COALESCE((SELECT SUM(totalAnsweredCalls) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredChats) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredEmails) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredSMS) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredFacebook) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredInstagram) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredWhatsapp) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_totalAnsweredCount;
         SELECT 
            COALESCE((SELECT SUM(totalCallACWTimeAnswered) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalChatACWTimeAnswered) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalEmailACWTimeAnswered) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalSMSACWTimeAnswered) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalFacebookACWTimeAnswered) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalInstagramACWTimeAnswered) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWhatsappACWTimeAnswered) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_totalACW;
        SELECT 
            COALESCE((SELECT SUM(answeredDurationCall) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationChat) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationWhatsapp) FROM temp_WhatsappHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationFacebook) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationEmail) FROM temp_EmailHistory_cal), 0) +
            COALESCE((SELECT SUM(answeredDurationInsta) FROM temp_InstagramHistory_cal_final), 0)
        INTO v_totalThresholdTime;
        SELECT 
            COALESCE((SELECT SUM(callIsMissed) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(chatIsMissed) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(facebookIsMissed) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(instaIsMissed) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(whatsappIsMissed) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_noOfIsMissed;
         SELECT 
            COALESCE((SELECT SUM(callIsAbandoned) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(chatIsAbandoned) FROM temp_ChatHistory_cal_final), 0)
        INTO v_noOfDeclined;
        SELECT 
            COALESCE((SELECT SUM(totalCallTransferCount) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalChatTransferCount) FROM temp_ChatHistory_cal_final), 0)
        INTO v_totalTransaferInteraction;
        SELECT 
            (SELECT SUM(totalWhatsapp) FROM temp_WhatsappHistory_cal_final) +
			(SELECT SUM(totalFacebook) FROM temp_FacebookHistory_cal_final) +
			(SELECT SUM(totalInstagram) FROM temp_InstagramHistory_cal_final)
		INTO v_totalSocialMedia;
        SELECT 
            (SELECT COALESCE(SUM(queueDuration), 0) FROM temp_CallHistory_cal_final) +
            (SELECT COALESCE(SUM(queueDuration), 0) FROM temp_ChatHistory_cal_final)
		INTO v_queueDuration;
        SELECT 
            (SELECT COALESCE(SUM(AgentHoldDuration), 0) FROM temp_CallHistory_cal_final)
		INTO v_totalHoldTime;
        SELECT 
            COALESCE((SELECT SUM(callResolved) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(chatResolved) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(emailResolved) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(SMSResolved) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(WhatsappResolved) FROM temp_WhatsappHistory_cal_final), 0) +
            COALESCE((SELECT SUM(FacebookResolved) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(instagramResolved) FROM temp_InstagramHistory_cal_final), 0)
        INTO v_resolvedQueries;
        SELECT 
            (SELECT COALESCE(SUM(callQueueSession), 0) FROM temp_CallHistory_cal_final) +
            (SELECT COALESCE(SUM(chatQueueSession), 0) FROM temp_ChatHistory_cal_final)
		INTO v_NoOfQueueSession;
    ELSE
        SET v_totalSessions = 0;
        SET v_totalDuration = 0;
        SET v_AnsDuration 	= 0;
        SET v_totalAnsweredCount = 0;
        SET v_totalACW = 0;
        SET v_totalThresholdTime = 0;
        SET v_noOfIsMissed = 0;
        SET v_totalSocialMedia = 0;
        SET v_queueDuration = 0;
        SET v_totalHoldTime = 0;
        SET v_resolvedQueries = 0;
        SET v_NoOfQueueSession = 0;
    END IF;
                
		SELECT CASE WHEN v_totalSessions = 0 THEN 0 ELSE ((v_queueDuration/1000)/v_totalSessions) END INTO v_firstResponseTime;
        
        
 	
	DROP TEMPORARY TABLE IF EXISTS temp_cal_final;
 	CREATE TEMPORARY TABLE temp_cal_final AS
     SELECT CASE WHEN v_AnsDuration = 0 THEN 0 ELSE ROUND((v_totalThresholdTime/v_totalAnsweredCount)*1000) END as averageSpeedOfAnswer
     
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE ROUND((v_queueDuration/1000)/v_totalAnsweredCount) END AS firstResponseTime
     ,CASE WHEN v_totalAnsweredCount = 0 THEN 0 ELSE ROUND((v_AnsDuration+(v_totalACW * 1000))/v_totalAnsweredCount) END AS averageHandlingTime
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE ROUND((v_totalACW * 1000) / v_totalSessions) END AS averageWrapUpTime
     ,CASE WHEN v_totalAnsweredCount = 0 THEN 0 ELSE ROUND(v_totalHoldTime / v_totalAnsweredCount) END AS averageHoldTime
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE (v_resolvedQueries / v_totalSessions) * 100 END AS averageCompletionRate
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE IFNULL(ROUND((v_queueDuration/1000) / v_totalSessions),0) END AS averageWaitTime
     ,CASE WHEN v_Minute = 0 THEN 0 ELSE ROUND(v_totalSessions / v_Minute) END AS averageSessionPerMinute
 	,CASE WHEN v_totalSessions = 0 THEN 0 ELSE ROUND((v_AnsDuration+v_totalHoldTime)/v_totalSessions) END as averageSessionDuration
     ,v_NoOfQueueSession AS incomingSessionInQueue;

		 SELECT IFNULL(averageWaitTime,0) AS averageWaitTime
		 ,IFNULL(averageWrapUpTime,0) AS averageWrapUpTime
		 ,IFNULL(averageSessionPerMinute,0) AS averageSessionPerMinute
		 ,IFNULL(averageSessionDuration,0) AS averageSessionDuration
		 ,IFNULL(averageHoldTime,0) AS averageHoldTime
		 ,IFNULL(averageCompletionRate,0) AS averageCompletionRate
		 ,IFNULL(incomingSessionInQueue,0) AS incomingSessionInQueue
		 ,IFNULL(averageSpeedOfAnswer,0) AS averageSpeedOfAnswer
		 ,IFNULL(firstResponseTime,0) AS firstResponseTime
		 ,IFNULL(averageHandlingTime,0) AS averageHandlingTime
		 FROM temp_cal_final;
			

   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_DashboardAverage_2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_DashboardAverage_2`(   
     p_startTmpstmp  BIGINT, 
     p_endTmpstmp    BIGINT, 
     p_Timezone      VARCHAR(55), 
     p_domainId      INT,
     p_ext           INT,
     p_roleId        INT
  )
BEGIN
             DECLARE v_Minute            			BIGINT;
             DECLARE v_roleid						TINYINT;  
			 DECLARE v_totalCount 					INT;
            
      
             SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
	SELECT 	roleid INTO v_roleid
	FROM 	tb_User U
	WHERE	U.domainId	= p_domainId
	AND 	U.ext		= IFNULL(p_ext,200)
	LIMIT 1;
    
    
             
             SET v_Minute = TIMESTAMPDIFF(MINUTE, FROM_UNIXTIME(p_startTmpstmp/1000), FROM_UNIXTIME(p_endTmpstmp/1000));    
          
             DROP TEMPORARY TABLE IF EXISTS temp_DurationHistory;
             CREATE TEMPORARY TABLE temp_DurationHistory(
       		  CH_HistoryId				BIGINT	,CDH_DurationHistoryId	BIGINT	,ChannelType				INT
       		  ,CH_waitDuration			BIGINT	,CH_callDuration		BIGINT	,CDH_dispositionName		VARCHAR(150)
       		  ,CH_dialDuration			BIGINT	,CDH_SentimentalScore	FLOAT	,CDH_AgentHoldDuration		BIGINT
       		  ,CDH_afterCallWorkTime	INT		,CDH_StartTime			BIGINT	,CDH_EndTime				BIGINT   
   			  ,CDH_timeTakenToAnswer	BIGINT	,CDH_Duration			BIGINT	,OrderOfCallAnswered		INT
              ,CD_queueDuration			INT		
             );      
   
   
		  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;       
       	  INSERT INTO temp_DurationHistory
       	  (	
   			OrderOfCallAnswered				,CH_HistoryId       		,CDH_DurationHistoryId       ,CH_waitDuration			,CH_callDuration		
       		,CDH_dispositionName		    ,CH_dialDuration       		 ,CDH_SentimentalScore      ,CDH_AgentHoldDuration
       		,CDH_afterCallWorkTime   		,CDH_Duration   			 ,CDH_StartTime   			,CDH_EndTime
   			,ChannelType   					,CDH_timeTakenToAnswer       ,CD_queueDuration
       	  )
       	  SELECT ROW_NUMBER() OVER(PARTITION BY CH.CallHistoryId order by CDH.CallDurationHistoryId) AS OrderOfCallAnswered,
				CH.CallHistoryId       	,CDH.CallDurationHistoryId      ,CH.waitDuration		,CH.callDuration		
       			,DS.dispositionName		    ,CDH.dialDuration       		,CDH.SentimentalScore   ,CDH.AgentHoldDuration
       			,CDH.afterCallWorkTime   	,CDH.Duration       			,CDH.StartTime       	,CDH.EndTime
       			,1	   				,CDH.answeredDuration           ,CH.queueDuration
       	  FROM tb_CallHistory 			CH    
       	  JOIN tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId	  
       	  LEFT JOIN disposition_status 	DS 	ON DS.did 			= CDH.dispositionId
	    
			LEFT JOIN tb_User				tu 	on tu.UserID 			= CDH.AgentId 		and CH.domainId = tu.domainId 
        
       	  WHERE CH.domainId 		= p_domainId 
       	  AND CH.sessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp
                 
        AND 	(tu.ext = p_ext OR v_roleid IN (3,5));  
        
           
     
		  INSERT INTO temp_DurationHistory
       	  (	OrderOfCallAnswered			,CH_HistoryId       			,CDH_DurationHistoryId   	,CH_waitDuration			,CH_callDuration		
       		,CDH_dispositionName		,CH_dialDuration       			,CDH_SentimentalScore      	,CDH_AgentHoldDuration
       		,CDH_afterCallWorkTime   	,CDH_Duration       			,CDH_StartTime       		,CDH_EndTime
       		,ChannelType   				,CDH_timeTakenToAnswer          ,CD_queueDuration
       	  )
		SELECT ROW_NUMBER() OVER(PARTITION BY CH.ChatHistoryId ORDER BY CDH.ChatDurationHistoryId) AS OrderOfCallAnswered,
				CH.ChatHistoryId     	,	CDH.ChatDurationHistoryId    ,	CH.queueDuration		,	CH.sessionEndTime - CH.sessionStartTime
     		,	DS.dispositionName		,	CH.dialDuration     		 ,	CDH.SentimentalScore    ,	(CDH.transferredTime-CDH.EndTime)
     		,	CDH.afterChatWorkTime 	,	CDH.Duration     			 ,	CDH.StartTime     		,	CDH.EndTime
     		,	2	        	,	CDH.answeredDuration         ,	CH.queueDuration
     	FROM tb_ChatHistory 			CH    
     	JOIN tb_ChatDurationHistory 	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId	  
     	LEFT JOIN disposition_status 	DS 	ON DS.did 			= CDH.dispositionId     
        
		LEFT JOIN tb_User				tu 	on tu.UserID 			= CDH.AgentId 		and CH.domainId = tu.domainId 
        
     	WHERE 	CH.domainId 			= p_domainId 
     	AND 	CH.sessionStartTime 	BETWEEN p_startTmpstmp AND p_endTmpstmp
        
        AND 	(tu.ext = p_ext OR v_roleid IN (3,5));  
        
      
	select * from temp_DurationHistory;  

	SELECT 	COUNT(DISTINCT CH_HistoryId) INTO v_totalCount
	FROM 	temp_DurationHistory;
        
    DROP TEMPORARY TABLE IF EXISTS temp_cal;
	CREATE TEMPORARY TABLE temp_cal AS
    SELECT 	COUNT(CH_HistoryId) as totalCount
    ,sum(CH_waitDuration) as waitDuration
    ,sum(case when IFNULL(CDH_Duration,0) > 0 then CDH_Duration else 0 end) as answerDuration
    ,sum(case when IFNULL(CDH_Duration,0) > 0 then 1 else 0 end) as answerCount
    ,sum(case when CDH_dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as Resolved
    ,sum(case when IFNULL(CDH_AgentHoldDuration,0) > 0 then CDH_AgentHoldDuration else 0 end) as holdTime
    ,sum(case when IFNULL(CDH_afterCallWorkTime,0) > 0 then CDH_afterCallWorkTime else 0 end) as acwTime
    ,sum(case when IFNULL(CDH_timeTakenToAnswer,0) > 0 then CDH_timeTakenToAnswer else 0 end) as timeTakenToAnswer
    ,sum(case when IFNULL(CD_queueDuration,0) > 0 then CD_queueDuration else 0 end) as queueDuration
    ,SUM(CASE WHEN CDH_dispositionName IS NULL THEN 1 ELSE 0 END) 					AS queueSession
    FROM temp_DurationHistory;
     
     select * from temp_cal;
     select v_totalCount;
       
    DROP TEMPORARY TABLE IF EXISTS temp_cal_final;
	CREATE TEMPORARY TABLE temp_cal_final AS
    SELECT CASE WHEN answerCount = 0 THEN 0 ELSE ROUND(answerDuration/answerCount) END as averageSpeedOfAnswer
    ,CASE WHEN v_totalCount = 0 THEN 0 ELSE ROUND(queueDuration/v_totalCount) END AS firstResponseTime
    ,CASE WHEN answerCount = 0 THEN 0 ELSE ROUND((answerDuration+holdTime+(acwTime * 1000))/answerCount) END AS averageHandlingTime
    ,CASE WHEN v_totalCount = 0 THEN 0 ELSE ROUND((acwTime * 1000) / v_totalCount) END AS averageWrapUpTime
    ,CASE WHEN answerCount = 0 THEN 0 ELSE ROUND(holdTime / answerCount) END AS averageHoldTime
    ,CASE WHEN answerCount = 0 THEN 0 ELSE (Resolved / v_totalCount) * 100 END AS averageCompletionRate
    ,CASE WHEN v_totalCount = 0 THEN 0 ELSE IFNULL(ROUND(waitDuration / v_totalCount),0) END AS averageWaitTime
    ,CASE WHEN v_Minute = 0 THEN 0 ELSE ROUND(v_totalCount / v_Minute) END AS averageSessionPerMinute
	,CASE WHEN v_totalCount = 0 THEN 0 ELSE ROUND(answerDuration/v_totalCount) END as averageSessionDuration
    ,queueSession AS incomingSessionInQueue
    FROM temp_cal
    ;
    
    select * from temp_cal_final;
    
   	
  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_DashboardAverage_Chat` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DashboardAverage_Chat`(	p_startTmpstmp BIGINT, 
   	p_endTmpstmp 	BIGINT, 
   	p_Timezone 		VARCHAR(55), 
   	p_domainId 		INT,
   	p_ext 			INT,
	p_roleId		INT
)
BEGIN
	DECLARE v_Minute					BIGINT;
	DECLARE v_waitDuration				BIGINT;
	DECLARE v_callDuration				BIGINT;
	DECLARE v_ResolvedCount				BIGINT;
	DECLARE v_noOfCalls					BIGINT;
	DECLARE v_noOfAgentCalls			BIGINT;
	DECLARE v_AgentHoldDuration			BIGINT;
	DECLARE v_afterCallWorkTime			BIGINT;
	DECLARE v_queueSession				BIGINT;
	DECLARE v_timeTakenToAnswer			BIGINT;
	DECLARE v_firstResponseTime			BIGINT;    
	DECLARE v_handlingTime				BIGINT;  
	DECLARE v_negativeSentimentalScore	FLOAT;
	DECLARE v_neutralSentimentalScore	FLOAT;    
	DECLARE v_postiveSentimentalScore	FLOAT;
       
   	DROP TEMPORARY TABLE IF EXISTS temp_userid; CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT);
      
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	IF p_roleId = 6 
	THEN
		INSERT INTO temp_userid
		(	UserId )
		SELECT  UserId
		FROM 	tb_User         
		WHERE 	ext 		= p_ext
	   AND 	domainId	= p_domainId;
	ELSE		    
		INSERT INTO temp_userid
		(	UserId )
		SELECT  UserID
		FROM 	tb_User
		WHERE 	roleid = 6
		AND 	domainId	= p_domainId;  		
	END IF;  
       
	SET v_Minute = TIMESTAMPDIFF(MINUTE,from_unixtime(p_startTmpstmp/1000), from_unixtime(p_endTmpstmp/1000));    
    
    DROP TEMPORARY TABLE IF EXISTS temp_DurationHistory;    
    CREATE TEMPORARY  TABLE  temp_DurationHistory
    (		waitDuration			bigint
		, 	callDuration			bigint
        , 	dispositionName        	varchar(100)
        , 	dialDuration			bigint
        , 	SentimentalScore		float
        , 	AgentHoldDuration		bigint
        , 	afterCallWorkTime		int
        , 	StartTime				bigint
        , 	EndTime					bigint
    ); 
    
    INSERT INTO temp_DurationHistory
    SELECT 	CH.waitDuration
		, 	CH.callDuration
        , 	DS.dispositionName        
        , 	CDH.dialDuration
        , 	CDH.SentimentalScore
        , 	AgentHoldDuration
        , 	CDH.afterCallWorkTime
        , 	StartTime
        , 	EndTime
    FROM 	tb_CallHistory 			CH    
   	JOIN 	tb_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId
   	JOIN 	temp_userid				U	ON U.UserID			= CDH.AgentId
   	LEFT JOIN disposition_status	DS 	ON DS.did 			= CDH.agentDispositionId        
   	WHERE	CH.domainId 		= p_domainId 
   	AND 	CH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp;      
    
    INSERT INTO temp_DurationHistory
    SELECT 	CH.queueDuration
		, 	CH.sessionEndTime - CH.sessionStartTime
        , 	DS.dispositionName        
        , 	CH.sessionStartTime	- CDH.StartTime	AS dialDuration
        , 	0									AS SentimentalScore
        , 	AgentHoldDuration		
        , 	CDH.afterChatWorkTime
        , 	StartTime
        , 	EndTime
    FROM 	tb_ChatHistory 			CH    
   	JOIN 	tb_ChatDurationHistory	CDH	ON CH.ChatHistoryId	= CDH.ChatHistoryId
   	JOIN 	temp_userid				U	ON U.UserID			= CDH.AgentId
   	LEFT JOIN disposition_status	DS 	ON DS.did 			= CDH.dispositionId        
   	WHERE	CH.domainId 		= p_domainId 
   	AND 	CH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp;      
   
   	SELECT 	SUM(waitDuration) 															AS waitDuration	
		,	SUM(callDuration)															AS callDuration
		,	SUM(CASE WHEN dispositionName IN ('Resolved','Closed') THEN 1 ELSE 0 END) 	AS Resolved
		,	SUM(CASE WHEN dispositionName IS NULL THEN 1 ELSE 0 END) 					AS queueSession        
		,	SUM(waitDuration)															AS timeTakenToAnswer
		,	SUM(dialDuration)															AS firstResponseTime
		,	SUM(CASE WHEN SentimentalScore  <= 40 THEN 1 ELSE 0 END)					AS negativeSentimentalScore
		,	SUM(CASE WHEN SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)		AS neutralSentimentalScore
		,	SUM(CASE WHEN SentimentalScore  > 60 THEN 1 ELSE 0 END)						AS postiveSentimentalScore
		,	COUNT(1)																	AS noOfCalls            
   	INTO 	v_waitDuration	
		,	v_callDuration	
		,	v_ResolvedCount	
		,	v_queueSession
		,	v_timeTakenToAnswer
		,	v_firstResponseTime
		,	v_negativeSentimentalScore		
		, 	v_neutralSentimentalScore	
		, 	v_postiveSentimentalScore	
		,	v_noOfCalls
   	FROM 	temp_DurationHistory;    
  
   	SELECT 	SUM(AgentHoldDuration)		AS AgentHoldDuration
		,	SUM(afterCallWorkTime)	AS afterCallWorkTime 
		,	SUM(EndTime - StartTime)	AS handlingTime 
		,	COUNT(1)
   	INTO	v_AgentHoldDuration	 		
		,   v_afterCallWorkTime	
		,	v_handlingTime
		,	v_noOfAgentCalls
   	FROM 	temp_DurationHistory;    
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       
   	SELECT  ROUND((v_waitDuration / v_noOfCalls) / 60000)			AS averageWaitTime
		,	ROUND((v_afterCallWorkTime / v_noOfAgentCalls) / 60000)	AS averageWrapUpTime
		,	ROUND((v_noOfCalls / v_Minute) / 60000)					AS averageSessionPerMinute
		,	ROUND((v_callDuration / v_noOfCalls) / 60000)			AS averageSessionDuration
		,	ROUND((v_AgentHoldDuration / v_noOfAgentCalls) / 60000)	AS averageHoldTime
		,	ROUND(v_ResolvedCount / v_noOfCalls * 100)				AS averageCompletionRate
		,	v_queueSession											AS incomingSessionInQueue
		,	ROUND(v_timeTakenToAnswer / v_noOfCalls / 60000)		AS averageSpeedOfAnswer
		,	ROUND(v_firstResponseTime / v_noOfCalls / 60000)		AS firstResponseTime
		,	ROUND(v_handlingTime / v_noOfAgentCalls / 60000)		AS averageHandlingTime
		,	ROUND(v_negativeSentimentalScore)						AS negativeSentimentalScore
		,   ROUND(v_neutralSentimentalScore)						AS neutralSentimentalScore
		,   ROUND(v_postiveSentimentalScore)						AS postiveSentimentalScore
		,	ROUND(v_negativeSentimentalScore	/ v_noOfCalls * 100)AS negativeSentimentalScorePer
		,   ROUND(v_neutralSentimentalScore / v_noOfCalls	* 100)	AS neutralSentimentalScorePer
		,   ROUND(v_postiveSentimentalScore / v_noOfCalls	* 100)	AS postiveSentimentalScorePer;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_DashboardAverage_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_DashboardAverage_test`(
	 p_startTmpstmp		BIGINT
	,p_endTmpstmp		BIGINT
    ,p_channelType 		VARCHAR(100) 
    ,p_domainId 		INT
	,p_Timezone      	VARCHAR(55)
    ,p_agentId          INT
   )
sp_return: begin
   
	DECLARE v_ext 				INT;
	DECLARE v_roleid 			VARCHAR(50);
	DECLARE v_emailId 			VARCHAR(250);
   
   	DECLARE v_startTmpstmp 		BIGINT;
   	DECLARE v_endTmpstmp 		BIGINT;
   	DECLARE v_curDate			DATETIME DEFAULT CURRENT_DATE();
       
   	DECLARE v_totalSocialMedia 				INT;
   	DECLARE v_totalChats 					INT;
   	
   	DECLARE v_blockCustomer 			INT;
   	DECLARE v_totalCustomer 			INT;
   	DECLARE v_totalTime 				INT;
   	
   	DECLARE v_queueDuration				INT;
   	DECLARE v_totalSessions 			INT;
   	DECLARE v_firstResponseTime 		BIGINT;
   	DECLARE v_totalDuration 			BIGINT;
   	DECLARE v_totalAnsweredCount 		BIGINT;
   	DECLARE v_avgSpeedOfAnswer 			BIGINT;
   	DECLARE v_avgHandlingTime 			BIGINT;
   	DECLARE v_totalACW 					BIGINT;
   	DECLARE v_totalCount 				BIGINT;
   	DECLARE v_occupancyRate 			BIGINT;
   	DECLARE v_noOfIsMissed 				BIGINT;
   	DECLARE v_noOfDeclined 				INT;
   	DECLARE v_totalTransaferInteraction 	INT;
       
   	DECLARE v_UserName 			VARCHAR(150);
   	DECLARE v_isVoice 			TINYINT;
   	DECLARE v_isChat 			TINYINT;
   	DECLARE v_isEmail 			TINYINT;
   	DECLARE v_isSms 			TINYINT;
   	DECLARE v_isSocialMedia 	TINYINT;
	DECLARE v_totalThresholdTime 		BIGINT;
   	DECLARE v_serviceLevel 				INT;
   	DECLARE v_AnsDuration 				INT;
   	DECLARE v_totalHoldTime 			INT;
   	DECLARE v_resolvedQueries 			INT;
   	DECLARE v_Minute 					INT;
   	DECLARE v_NoOfQueueSession 			INT;
    
    DECLARE v_channelType VARCHAR(100);
    SET 	v_channelType = p_channelType;
   
	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = UNIX_TIMESTAMP(CURDATE()) * 1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
	IF IFNULL(p_endTmpstmp,0)	=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
   
	SET v_Minute = TIMESTAMPDIFF(MINUTE, FROM_UNIXTIME(p_startTmpstmp/1000), FROM_UNIXTIME(p_endTmpstmp/1000));
    
    DROP TEMPORARY TABLE IF EXISTS tt_userDtl;
    CREATE TEMPORARY TABLE tt_userDtl(UserID int , UserName varchar(150) , domainId int, roleid int);
    
    INSERT INTO tt_userDtl (UserID, UserName, domainId, roleid) 	
    SELECT UserID, UserName, domainId, roleid  FROM tb_User WHERE domainId = p_domainId AND (UserId = p_agentId OR IFNULL(p_agentId,'') = '')  ;

	
	
		
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory;
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory;
            
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_cal_final;
			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_SMSHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_cal_final;
            DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_cal_final;
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_cal;
			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_cal_final; 
   
       IF (v_channelType = 'All' OR v_channelType = 'Call')
       THEN
   		CREATE TEMPORARY TABLE temp_CallHistory AS
   		SELECT 
				CH.CallHistoryId
				,CH.sessionStartTime
				,CH.sessionEndTime
				,CH.domainId
				,CH.IsInBound
				,CH.waitDuration
				,CH.CustomerId
				,CH.voicemailUrl
				,CH.callBack
				,CDH.CallDurationHistoryId
				,CDH.Duration
				,CDH.AgentId
				,CDH.dispositionId
				,CDH.afterCallWorkTime
				,CH.callCost
				,CDH.AgentHoldDuration
				,CDH.IsBot
				,CH.queueDuration
				,CDH.IsMissedCall
				,CH.IsAbandoned
				,CDH.answeredDuration
   		FROM 	tb_CallHistory 	CH
   		JOIN 	tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId
   		WHERE 	CH.domainId = p_domainId
   		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		CDH.AgentId IN (SELECT UserID FROM tt_userDtl);

   		CREATE TEMPORARY TABLE temp_CallHistory_cal AS
   		SELECT 
				count(CallHistoryId) as totalCalls
				,sum(case when IsInBound  = 1 then 1 else 0 end) as totalInboundCalls
				,sum(case when IsInBound  = 0 then 1 else 0 end) as totalOutboundCalls
				,sum(case when callBack = 1 then 1 else 0 end) as callCallBack
				,sum(case when voicemailUrl IS NOT NULL AND voicemailUrl like '%voicemail%' then 1 else 0 end) as totalVoiceMail
				,sum(case when DS.dispositionName = 'Caller Disconnected' then 1 else 0 end) as totalAbandonCalls
				,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredCalls
				,sum(case when DS.dispositionName = 'Transferred' then 1 else 0 end) as totalCallTransferCount
				,sum(case when IFNULL(Duration,0) > 0 then Duration	else 0 end) as totalCallDurationAnswered 
				,sum(case when IFNULL(Duration,0) > 0 then afterCallWorkTime else 0 end) as totalCallACWTimeAnswered
				,sum(case when IFNULL(Duration,0) > 0 then AgentHoldDuration else 0 end) as totalCallHoldTime
				,sum(case when IFNULL(callCost,0) > 0 then callCost else 0 end) as totalCallCost
				,sum(queueDuration) as queueDuration
				,sum(AgentHoldDuration) as AgentHoldDuration
				,sum(case when IFNULL(IsMissedCall,0)  = 1 then 1 else 0 end) as isMissed
				,sum(case when IFNULL(IsAbandoned,0)   = 1 then 1 else 0 end) as IsAbandoned
				,sum(case when IFNULL(answeredDuration,0) > 0 then answeredDuration else 0 end) as answeredDurationCall
                ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as callResolved
                ,sum(case when IFNULL(queueDuration,0) > 0 then 1 else 0 end) as callQueueSession
			FROM 		temp_CallHistory CH
			LEFT JOIN 	disposition_status		DS 	ON DS.did = CH.dispositionId
			WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
           
			CREATE TEMPORARY TABLE temp_CallHistory_cal_final AS
			SELECT 
				totalCalls as totalCalls
				,totalInboundCalls as totalInboundCalls
				,totalOutboundCalls as totalOutboundCalls
				,callCallBack
				,totalVoiceMail as totalVoiceMail
				,totalAnsweredCalls
				,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalAbandonCalls / totalAnsweredCalls) * 100 END as callAbandonRates
				,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalCallCost / totalAnsweredCalls) END  as costPerCall
				,CASE WHEN totalAnsweredCalls = 0 THEN 0 ELSE (totalCallTransferCount / totalAnsweredCalls) * 100 END  as callsTransferRate
				,(totalCallDurationAnswered+(totalCallACWTimeAnswered*1000)) as overallCallAnsweredDuration
				,AgentHoldDuration
				,totalCallDurationAnswered
				,CASE WHEN v_totalTime = 0 THEN 0 ELSE floor(totalInboundCalls/v_totalTime) END as callArrivalRate
				,totalCallACWTimeAnswered
				,queueDuration			 
				,CASE WHEN totalCalls = 0 THEN 0 ELSE (totalCallHoldTime/totalCalls) END as avgHoldTime
				,isMissed AS callIsMissed
				,IsAbandoned AS callIsAbandoned
				,answeredDurationCall
				,totalCallTransferCount
                ,totalCallHoldTime
                ,callResolved
                ,callQueueSession
   		FROM temp_CallHistory_cal;
	END IF;
   
   IF (v_channelType = 'All' OR v_channelType = 'Chat')
	THEN
   		CREATE TEMPORARY TABLE temp_ChatHistory AS
   		SELECT
   				CH.ChatHistoryId
   				,CH.sessionStartTime
   				,CH.sessionEndTime
   				,CH.chatFlowSourceId
   				,CH.domainId
   				,CH.IsInBound
   				,CH.CustomerId
   				,CH.CallBackStatus
   				,CDH.ChatDurationHistoryId
   				,CDH.Duration
   				,CDH.AgentId
   				,CDH.dispositionId
   				,CDH.afterChatWorkTime
				,CDH.IsBot
				,CH.queueDuration
				,CDH.IsMissed
				,CDH.IsAbandoned
				,CDH.answeredDuration
   		FROM 	tb_ChatHistory 	CH
   		JOIN 	tb_ChatDurationHistory 	CDH ON CH.ChatHistoryId = CDH.ChatHistoryId 
   		WHERE 	CH.domainId = p_domainId
   		AND 	CH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		CDH.AgentId IN (SELECT UserID FROM tt_userDtl);   
        
			CREATE TEMPORARY TABLE temp_ChatHistory_cal AS
			SELECT 
				count(ChatHistoryId) as totalWebChats
				,sum(case when CallBackStatus = 1 then 1 else 0 end) as chatCallBack
				,sum(case when dispositionId is null then 1 else 0 end) as nonCompleteChat
				,sum(case when DS.dispositionName = 'Caller Disconnected' then 1 else 0 end) as totalAbandonChats
				,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredChats
				,sum(case when IFNULL(Duration,0) > 0 AND DS.dispositionName = 'Transferred' then 1 else 0 end) as totalChatTransferCount
				,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalChatDurationAnswered
				,sum(case when IFNULL(Duration,0) > 0 then afterChatWorkTime else 0 end) as totalChatACWTimeAnswered
				,sum(queueDuration) as queueDuration	
				,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
				,sum(case when IFNULL(IsAbandoned,0)   = 1 then 1 else 0 end) as IsAbandoned
				,sum(case when IFNULL(answeredDuration,0) > 0 then 1 else 0 end) as answeredDurationChat
                ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as chatResolved
                ,sum(case when IFNULL(queueDuration,0) > 0 then 1 else 0 end) as chatQueueSession
				FROM 		temp_ChatHistory 		CH
				LEFT JOIN 	disposition_status		DS 	ON DS.did = CH.dispositionId
				WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
            
			CREATE TEMPORARY TABLE temp_ChatHistory_cal_final AS
			SELECT 
				totalWebChats as totalWebChats
				,chatCallBack as chatCallBack
				,nonCompleteChat as nonCompleteChat
				,totalAbandonChats
				,totalAnsweredChats as totalAnsweredChats
				,totalChatTransferCount
				,totalChatDurationAnswered
				,totalChatACWTimeAnswered
				,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalAbandonChats / totalAnsweredChats) * 100 END as chatAbandonRates
				,CASE WHEN totalWebChats = 0 THEN 0 ELSE (totalAnsweredChats / totalWebChats) * 100 END as chatCompletionRates
				,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalChatTransferCount / totalAnsweredChats) * 100 END  as chatsTransferRate
				,(totalChatDurationAnswered+(totalChatACWTimeAnswered*1000)) as overallChatAnsweredDuration
				,CASE WHEN totalWebChats = 0 THEN 0 ELSE (totalChatDurationAnswered/totalWebChats) END as averageChatDuration 
				,CASE WHEN totalWebChats = 0 THEN 0 ELSE IFNULL((queueDuration/totalWebChats),0) END as averageChatWaitTime  
				,CASE WHEN totalAnsweredChats = 0 THEN 0 ELSE (totalChatDurationAnswered/totalAnsweredChats) END as averageChatReplyTime   
				,IFNULL(queueDuration,0) as queueDuration
				,isMissed as chatIsMissed
				,IsAbandoned as chatIsAbandoned
				,answeredDurationChat
                ,chatResolved
                ,chatQueueSession
   		FROM temp_ChatHistory_cal;
	END IF;
    
    IF (v_channelType = 'All' OR v_channelType = 'Email')
	THEN
   		CREATE TEMPORARY TABLE temp_EmailHistory AS
   		SELECT
			EH.EmailHistoryId
			,EH.SessionStartTime
			,EH.SessionEndTime
			,EH.DomainId
			,EH.DispositionId
			,EH.IsInBound
			,EH.AfterEmailWorkTime
			,EH.IsSessionClosed
			,EH.CustomerId
			,EDH.EmailDurationHistoryId
			,EDH.Duration
			,EDH.AgentId
			,EDH.IsBot
			,EC.emailThreshold
		FROM 	tb_EmailHistory EH
		JOIN 	tb_EmailDurationHistory EDH ON EH.EmailHistoryId = EDH.EmailHistoryId 
		JOIN 	email_config EC ON EC.domainId = EH.DomainId
		WHERE 	EH.domainId = p_domainId
		AND 	EH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		EDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_EmailHistory_cal AS
		SELECT   count(EmailHistoryId) as totalEmails
		,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredEmails
		,sum(case when IFNULL(Duration,0) > 0 then AfterEmailWorkTime else 0 end) as totalEmailACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalEmailDurationAnswered
		
		,sum(case when (emailThreshold <= 24) then 1 else 0 end) as answeredDurationEmail
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as emailResolved
		FROM 		temp_EmailHistory 		EH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = EH.DispositionId
		WHERE 	SessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
   		CREATE TEMPORARY TABLE temp_EmailHistory_cal_final AS
   		SELECT 
			totalEmails
			,totalAnsweredEmails
			,answeredDurationEmail
			,(totalEmailDurationAnswered+(totalEmailACWTimeAnswered*1000)) as overallEmailAnsweredDuration
			,totalEmailACWTimeAnswered
			,totalEmailDurationAnswered
			
            ,emailResolved
           FROM temp_EmailHistory_cal;
	END IF;
   
    IF (v_channelType = 'All' OR v_channelType = 'SMS')
	THEN
   		CREATE TEMPORARY TABLE temp_SMSHistory AS
   		SELECT
			SH.SMSHistoryId
			,SH.sessionStartTime
			,SH.sessionEndTime
			,SH.domainId
			,SH.dispositionId
			,SH.IsInBound
			,SH.afterSMSWorkTime
			,SH.IsSessionClosed
			,SH.customerNumber
			,SH.calledNumber
			,SDH.SMSDurationHistoryId
			,SDH.Duration
			,SDH.AgentId
			,SDH.IsBot
		FROM 	tb_SMSHistory 	SH
		JOIN 	tb_SMSDurationHistory 	SDH ON SH.SMSHistoryId = SDH.SMSHistoryId
		WHERE 	SH.domainId = p_domainId
		AND 	SH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		SDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_SMSHistory_cal AS
		SELECT   count(*) as totalSMS
		,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredSMS
		,sum(case when IFNULL(Duration,0) > 0 then afterSMSWorkTime else 0 end) as totalSMSACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalSMSDurationAnswered
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as SMSResolved
		FROM 		temp_SMSHistory SH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = SH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
		CREATE TEMPORARY TABLE temp_SMSHistory_cal_final AS
		SELECT 
			totalSMS
			,totalAnsweredSMS
			,(totalSMSDurationAnswered+(totalSMSACWTimeAnswered*1000)) as overallSMSAnsweredDuration
			,totalSMSACWTimeAnswered
			,totalSMSDurationAnswered
            ,SMSResolved
           FROM temp_SMSHistory_cal;
                              
	END IF;
    
    IF (v_channelType = 'All' OR v_channelType = 'WhatsApp')
	THEN 
   		CREATE TEMPORARY TABLE temp_WhatsappHistory AS
   		SELECT
				WH.WhatsappHistoryId
				,WH.sessionStartTime
				,WH.sessionEndTime
				,WH.domainId
				,WH.dispositionId
				,WH.IsInBound
				,WH.afterwhatsappWorkTime
				,WH.IsSessionClosed
				,WH.isCallback
				,WDH.WhatsappDurationHistoryId
				,WDH.AgentId
				,WDH.Duration
				,WDH.dialDuration
				,WDH.IsBot
				,WDH.IsMissed
		FROM 	tb_WhatsappHistory 	WH
		JOIN 	tb_WhatsappDurationHistory 	WDH ON WH.WhatsappHistoryId = WDH.WhatsappHistoryId
		WHERE 	WH.domainId = p_domainId
   		AND 	WH.sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		WDH.AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_WhatsappHistory_cal AS
		SELECT   count(*) as totalWhatsapp
		,sum(case when IFNULL(Duration,0) then 1 else 0 end) as totalAnsweredWhatsapp
		,sum(case when IFNULL(Duration,0) > 0 then afterwhatsappWorkTime else 0 end) as totalWhatsappACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalWhatsappDurationAnswered
		,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
		,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationWhatsapp
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as WhatsappResolved
		FROM 		temp_WhatsappHistory WH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = WH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
		CREATE TEMPORARY TABLE temp_WhatsappHistory_cal_final AS
		SELECT 
			totalWhatsapp
			,totalAnsweredWhatsapp
			,(totalWhatsappDurationAnswered+(totalWhatsappACWTimeAnswered*1000)) as overallWhatsappAnsweredDuration
			,totalWhatsappACWTimeAnswered
			,isMissed as whatsappIsMissed
			,answeredDurationWhatsapp
			,totalWhatsappDurationAnswered
            ,WhatsappResolved
           FROM temp_WhatsappHistory_cal;
               
   END IF;
   
    IF (v_channelType = 'All' OR v_channelType = 'Facebook')
	THEN   
   		CREATE TEMPORARY TABLE temp_FacebookHistory AS
   		SELECT
				FacebookHistoryId
				,sessionStartTime
				,sessionEndTime
				,domainId
				,dispositionId
				,IsInBound
				,afterFacebookWorkTime
				,IsSessionClosed
				,AgentId
				,Duration
				,isCallback
				,IsBot
				,IsMissed
				,dialDuration
		FROM 	tb_FacebookHistory 
		WHERE 	domainId = p_domainId
		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_FacebookHistory_cal AS
		SELECT   count(FacebookHistoryId) as totalFacebook
		,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationFacebook
		,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredFacebook
		,sum(case when IFNULL(Duration,0) > 0 then afterFacebookWorkTime else 0 end) as totalFacebookACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalFacebookDurationAnswered
        ,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as FacebookResolved
		FROM 		temp_FacebookHistory 	FH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = FH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
   		CREATE TEMPORARY TABLE temp_FacebookHistory_cal_final AS
   		SELECT 
			totalFacebook
			,totalAnsweredFacebook
			,answeredDurationFacebook
			,totalFacebookACWTimeAnswered
			,(totalFacebookDurationAnswered+(totalFacebookACWTimeAnswered*1000)) as overallFacebookAnsweredDuration
			,totalFacebookDurationAnswered
            ,isMissed as facebookIsMissed
            ,FacebookResolved
           FROM temp_FacebookHistory_cal;
                           
   END IF;
   
     IF (v_channelType = 'All' OR v_channelType = 'Instagram')
	THEN    
   		CREATE TEMPORARY TABLE temp_InstagramHistory AS
   		SELECT
				InstagramHistoryId
				,sessionStartTime
				,sessionEndTime
				,domainId
				,dispositionId
				,IsInBound
				,afterInstagramWorkTime
				,IsSessionClosed
				,AgentId
				,Duration
				,IsMissed
				,dialDuration
   		FROM 	tb_InstagramHistory
   		WHERE 	domainId = p_domainId
   		AND 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp
        AND		AgentId IN (SELECT UserID FROM tt_userDtl);
        
		CREATE TEMPORARY TABLE temp_InstagramHistory_cal AS
		SELECT   count(InstagramHistoryId) as totalInstagram
		,sum(case when IFNULL(dialDuration,0) > 0 then 1 else 0 end) as answeredDurationInsta
		,sum(case when IFNULL(Duration,0) > 0 then afterInstagramWorkTime else 0 end) as totalInstagramACWTimeAnswered
		,sum(case when IFNULL(Duration,0) > 0 then 1 else 0 end) as totalAnsweredInstagram
		,sum(case when IFNULL(Duration,0) > 0 then Duration else 0 end) as totalInstagramDurationAnswered
        ,sum(case when IFNULL(IsMissed,0)  = 1 then 1 else 0 end) as isMissed
        ,sum(case when DS.dispositionName in ('Resolved', 'Closed' , 'Caller Disconnected') then 1 else 0 end) as instagramResolved
		FROM 		temp_InstagramHistory FH
        LEFT JOIN 	disposition_status		DS 	ON DS.did = FH.dispositionId
		WHERE 	sessionStartTime BETWEEN v_startTmpstmp AND v_endTmpstmp;
        
		CREATE TEMPORARY TABLE temp_InstagramHistory_cal_final AS
		SELECT 
			totalInstagram
			,totalAnsweredInstagram
			,answeredDurationInsta
			,totalInstagramACWTimeAnswered
			,totalInstagramDurationAnswered
			,(totalInstagramDurationAnswered+(totalInstagramACWTimeAnswered*1000)) as overallInstagramAnsweredDuration
            ,isMissed as instaIsMissed
            ,instagramResolved
           FROM temp_InstagramHistory_cal;
                           
   END IF;

 
         
		IF  p_channelType = 'Call' THEN
			SELECT COALESCE(SUM(totalCalls), 0),COALESCE(SUM(overallCallAnsweredDuration), 0),COALESCE(SUM(totalCallDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredCalls), 0),COALESCE(SUM(totalCallACWTimeAnswered), 0),COALESCE(SUM(answeredDurationCall), 0)
            ,COALESCE(SUM(callIsMissed), 0),COALESCE(SUM(callIsAbandoned), 0),COALESCE(SUM(totalCallTransferCount), 0),COALESCE(SUM(queueDuration), 0)
            ,COALESCE(SUM(totalCallHoldTime), 0),COALESCE(SUM(callResolved), 0),COALESCE(SUM(callQueueSession), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_noOfDeclined 
            ,v_totalTransaferInteraction,v_queueDuration,v_totalHoldTime,v_resolvedQueries,v_NoOfQueueSession
            FROM temp_CallHistory_cal_final;
		ELSEIF p_channelType = 'Chat' THEN
			SELECT COALESCE(SUM(totalWebChats), 0),COALESCE(SUM(overallChatAnsweredDuration), 0),COALESCE(SUM(totalChatDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredChats), 0),COALESCE(SUM(totalChatACWTimeAnswered), 0),COALESCE(SUM(answeredDurationChat), 0)
            ,COALESCE(SUM(chatIsMissed), 0),COALESCE(SUM(chatIsAbandoned), 0),COALESCE(SUM(totalChatTransferCount), 0),COALESCE(SUM(queueDuration), 0)
            ,COALESCE(SUM(chatResolved), 0),COALESCE(SUM(chatQueueSession), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_noOfDeclined 
            ,v_totalTransaferInteraction,v_queueDuration,v_resolvedQueries,v_NoOfQueueSession
            FROM temp_ChatHistory_cal_final;
		ELSEIF p_channelType = 'Email' THEN
			SELECT COALESCE(SUM(totalEmails), 0),COALESCE(SUM(overallEmailAnsweredDuration), 0),COALESCE(SUM(totalEmailDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredEmails), 0),COALESCE(SUM(totalEmailACWTimeAnswered), 0),COALESCE(SUM(answeredDurationEmail), 0),COALESCE(SUM(emailResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_resolvedQueries 
            FROM temp_EmailHistory_cal_final;
		ELSEIF p_channelType = 'SMS' THEN
			SELECT COALESCE(SUM(totalSMS), 0),COALESCE(SUM(overallSMSAnsweredDuration), 0),COALESCE(SUM(totalSMSDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredSMS), 0),COALESCE(SUM(totalSMSACWTimeAnswered), 0),COALESCE(SUM(SMSResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_resolvedQueries 
            FROM temp_SMSHistory_cal_final;
        ELSEIF p_channelType = 'Whatsapp' THEN
        SELECT COALESCE(SUM(totalWhatsapp), 0),COALESCE(SUM(overallWhatsappAnsweredDuration), 0),COALESCE(SUM(totalWhatsappDurationAnswered), 0) 
        ,COALESCE(SUM(totalAnsweredWhatsapp), 0),COALESCE(SUM(totalWhatsappACWTimeAnswered), 0),COALESCE(SUM(answeredDurationWhatsapp), 0)
        ,COALESCE(SUM(whatsappIsMissed), 0),COALESCE(SUM(totalWhatsapp), 0),COALESCE(SUM(WhatsappResolved), 0)
        INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_totalSocialMedia 
        ,v_resolvedQueries
        FROM temp_WhatsappHistory_cal_final;
		ELSEIF p_channelType = 'Facebook' THEN
			SELECT COALESCE(SUM(totalFacebook), 0),COALESCE(SUM(overallFacebookAnsweredDuration), 0),COALESCE(SUM(totalFacebookDurationAnswered), 0) 
            ,COALESCE(SUM(totalAnsweredFacebook), 0),COALESCE(SUM(totalFacebookACWTimeAnswered), 0),COALESCE(SUM(answeredDurationFacebook), 0)
            ,COALESCE(SUM(facebookIsMissed), 0),COALESCE(SUM(totalFacebook), 0),COALESCE(SUM(FacebookResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_totalSocialMedia 
            ,v_resolvedQueries
            FROM temp_FacebookHistory_cal_final;
		ELSEIF p_channelType = 'Instagram' THEN
			SELECT COALESCE(SUM(totalInstagram), 0),COALESCE(SUM(overallInstagramAnsweredDuration), 0),COALESCE(SUM(totalInstagramDurationAnswered), 0)
            ,COALESCE(SUM(totalAnsweredInstagram), 0),COALESCE(SUM(totalInstagramACWTimeAnswered), 0),COALESCE(SUM(answeredDurationInsta), 0)
            ,COALESCE(SUM(instaIsMissed), 0),COALESCE(SUM(totalInstagram), 0),COALESCE(SUM(instagramResolved), 0)
            INTO v_totalSessions,v_totalDuration,v_AnsDuration,v_totalAnsweredCount,v_totalACW,v_totalThresholdTime,v_noOfIsMissed,v_totalSocialMedia 
            ,v_resolvedQueries
            FROM temp_InstagramHistory_cal_final;
		ELSEIF p_channelType = 'All' THEN
        SELECT 
            COALESCE((SELECT SUM(totalCalls) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWebChats) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalEmails) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalSMS) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWhatsapp) FROM temp_WhatsappHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalFacebook) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalInstagram) FROM temp_InstagramHistory_cal_final), 0)
        INTO v_totalSessions;
        SELECT 
            COALESCE((SELECT SUM(overallCallAnsweredDuration) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallChatAnsweredDuration) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallEmailAnsweredDuration) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallFacebookAnsweredDuration) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallInstagramAnsweredDuration) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallSMSAnsweredDuration) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(overallWhatsappAnsweredDuration) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_totalDuration;
        SELECT 
            COALESCE((SELECT SUM(totalCallDurationAnswered) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalChatDurationAnswered) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalEmailDurationAnswered) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalFacebookDurationAnswered) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalInstagramDurationAnswered) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalSMSDurationAnswered) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWhatsappDurationAnswered) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_AnsDuration;
        SELECT 
            COALESCE((SELECT SUM(totalAnsweredCalls) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredChats) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredEmails) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredSMS) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredFacebook) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredInstagram) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalAnsweredWhatsapp) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_totalAnsweredCount;
         SELECT 
            COALESCE((SELECT SUM(totalCallACWTimeAnswered) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalChatACWTimeAnswered) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalEmailACWTimeAnswered) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalSMSACWTimeAnswered) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalFacebookACWTimeAnswered) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalInstagramACWTimeAnswered) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalWhatsappACWTimeAnswered) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_totalACW;
        SELECT 
            COALESCE((SELECT SUM(answeredDurationCall) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationChat) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationWhatsapp) FROM temp_WhatsappHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationFacebook) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(answeredDurationEmail) FROM temp_EmailHistory_cal), 0) +
            COALESCE((SELECT SUM(answeredDurationInsta) FROM temp_InstagramHistory_cal_final), 0)
        INTO v_totalThresholdTime;
        SELECT 
            COALESCE((SELECT SUM(callIsMissed) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(chatIsMissed) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(facebookIsMissed) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(instaIsMissed) FROM temp_InstagramHistory_cal_final), 0) +
            COALESCE((SELECT SUM(whatsappIsMissed) FROM temp_WhatsappHistory_cal_final), 0)
        INTO v_noOfIsMissed;
         SELECT 
            COALESCE((SELECT SUM(callIsAbandoned) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(chatIsAbandoned) FROM temp_ChatHistory_cal_final), 0)
        INTO v_noOfDeclined;
        SELECT 
            COALESCE((SELECT SUM(totalCallTransferCount) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(totalChatTransferCount) FROM temp_ChatHistory_cal_final), 0)
        INTO v_totalTransaferInteraction;
        SELECT 
            (SELECT SUM(totalWhatsapp) FROM temp_WhatsappHistory_cal_final) +
			(SELECT SUM(totalFacebook) FROM temp_FacebookHistory_cal_final) +
			(SELECT SUM(totalInstagram) FROM temp_InstagramHistory_cal_final)
		INTO v_totalSocialMedia;
        SELECT 
            (SELECT COALESCE(SUM(queueDuration), 0) FROM temp_CallHistory_cal_final) +
            (SELECT COALESCE(SUM(queueDuration), 0) FROM temp_ChatHistory_cal_final)
		INTO v_queueDuration;
        SELECT 
            (SELECT COALESCE(SUM(AgentHoldDuration), 0) FROM temp_CallHistory_cal_final)
		INTO v_totalHoldTime;
        SELECT 
            COALESCE((SELECT SUM(callResolved) FROM temp_CallHistory_cal_final), 0) +
            COALESCE((SELECT SUM(chatResolved) FROM temp_ChatHistory_cal_final), 0) +
            COALESCE((SELECT SUM(emailResolved) FROM temp_EmailHistory_cal_final), 0) +
            COALESCE((SELECT SUM(SMSResolved) FROM temp_SMSHistory_cal_final), 0) +
            COALESCE((SELECT SUM(WhatsappResolved) FROM temp_WhatsappHistory_cal_final), 0) +
            COALESCE((SELECT SUM(FacebookResolved) FROM temp_FacebookHistory_cal_final), 0) +
            COALESCE((SELECT SUM(instagramResolved) FROM temp_InstagramHistory_cal_final), 0)
        INTO v_resolvedQueries;
        SELECT 
            (SELECT COALESCE(SUM(callQueueSession), 0) FROM temp_CallHistory_cal_final) +
            (SELECT COALESCE(SUM(chatQueueSession), 0) FROM temp_ChatHistory_cal_final)
		INTO v_NoOfQueueSession;
    ELSE
        SET v_totalSessions = 0;
        SET v_totalDuration = 0;
        SET v_AnsDuration 	= 0;
        SET v_totalAnsweredCount = 0;
        SET v_totalACW = 0;
        SET v_totalThresholdTime = 0;
        SET v_noOfIsMissed = 0;
        SET v_totalSocialMedia = 0;
        SET v_queueDuration = 0;
        SET v_totalHoldTime = 0;
        SET v_resolvedQueries = 0;
        SET v_NoOfQueueSession = 0;
    END IF;
                
		SELECT CASE WHEN v_totalSessions = 0 THEN 0 ELSE ((v_queueDuration/1000)/v_totalSessions) END INTO v_firstResponseTime;
        
        
 	
    SELECT v_resolvedQueries , v_totalSessions;
    
	DROP TEMPORARY TABLE IF EXISTS temp_cal_final;
 	CREATE TEMPORARY TABLE temp_cal_final AS
     SELECT CASE WHEN v_AnsDuration = 0 THEN 0 ELSE ROUND((v_totalThresholdTime/v_totalAnsweredCount)*1000) END as averageSpeedOfAnswer
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE ROUND((v_queueDuration/1000)/v_totalSessions) END AS firstResponseTime
     ,CASE WHEN v_totalAnsweredCount = 0 THEN 0 ELSE ROUND((v_AnsDuration+(v_totalACW * 1000))/v_totalAnsweredCount) END AS averageHandlingTime
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE ROUND((v_totalACW * 1000) / v_totalSessions) END AS averageWrapUpTime
     ,CASE WHEN v_totalAnsweredCount = 0 THEN 0 ELSE ROUND(v_totalHoldTime / v_totalAnsweredCount) END AS averageHoldTime
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE (v_resolvedQueries / v_totalSessions) * 100 END AS averageCompletionRate
     ,CASE WHEN v_totalSessions = 0 THEN 0 ELSE IFNULL(ROUND((v_queueDuration/1000) / v_totalSessions),0) END AS averageWaitTime
     ,CASE WHEN v_Minute = 0 THEN 0 ELSE ROUND(v_totalSessions / v_Minute) END AS averageSessionPerMinute
 	,CASE WHEN v_totalSessions = 0 THEN 0 ELSE ROUND((v_AnsDuration+v_totalHoldTime)/v_totalSessions) END as averageSessionDuration
     ,v_NoOfQueueSession AS incomingSessionInQueue;

		 SELECT IFNULL(averageWaitTime,0) AS averageWaitTime
		 ,IFNULL(averageWrapUpTime,0) AS averageWrapUpTime
		 ,IFNULL(averageSessionPerMinute,0) AS averageSessionPerMinute
		 ,IFNULL(averageSessionDuration,0) AS averageSessionDuration
		 ,IFNULL(averageHoldTime,0) AS averageHoldTime
		 ,IFNULL(averageCompletionRate,0) AS averageCompletionRate
		 ,IFNULL(incomingSessionInQueue,0) AS incomingSessionInQueue
		 ,IFNULL(averageSpeedOfAnswer,0) AS averageSpeedOfAnswer
		 ,IFNULL(firstResponseTime,0) AS firstResponseTime
		 ,IFNULL(averageHandlingTime,0) AS averageHandlingTime
		 FROM temp_cal_final;
			

   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_DashboardCustomerSatisfaction` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DashboardCustomerSatisfaction`(	
	p_startTmpstmp 	BIGINT, 
  	p_endTmpstmp 	BIGINT, 
  	p_Timezone 		VARCHAR(55), 
  	p_domainId 		INT
  )
BEGIN
	DECLARE v_negativeSentimentalScore	FLOAT;
	DECLARE v_neutralSentimentalScore	FLOAT;    
	DECLARE v_postiveSentimentalScore	FLOAT;
	DECLARE	v_noOfCalls					BIGINT;      
  	
  	DROP TEMPORARY TABLE IF EXISTS tmp_SentimentalScore; 
    CREATE TEMPORARY TABLE tmp_SentimentalScore(
		negativeSentimentalScore	FLOAT		
	,   neutralSentimentalScore	    FLOAT 
    ,   postiveSentimentalScore	    FLOAT
  	,	noOfCalls                   INT
	);    
     
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
	INSERT INTO tmp_SentimentalScore(
    	negativeSentimentalScore
    ,   neutralSentimentalScore	
    ,   postiveSentimentalScore	
	,	noOfCalls               	
    )
  	SELECT 	SUM(CASE WHEN CDH.SentimentalScore  <= 40 THEN 1 ELSE 0 END)				AS negativeSentimentalScore
		,	SUM(CASE WHEN CDH.SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)	AS neutralSentimentalScore
		,	SUM(CASE WHEN CDH.SentimentalScore  > 60 THEN 1 ELSE 0 END)					AS postiveSentimentalScore
		,	COUNT(1)																	AS noOfCalls              	
  	FROM 	tb_CallHistory 			CH    
  	JOIN 	tb_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  	
  	WHERE	CH.domainId 		= p_domainId 
  	AND 	CH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp;     

	INSERT INTO tmp_SentimentalScore(
    	negativeSentimentalScore
    ,   neutralSentimentalScore	
    ,   postiveSentimentalScore	
	,	noOfCalls               	
    )
  	SELECT 	SUM(CASE WHEN CDH.SentimentalScore  <= 40 THEN 1 ELSE 0 END)				AS negativeSentimentalScore
		,	SUM(CASE WHEN CDH.SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)	AS neutralSentimentalScore
		,	SUM(CASE WHEN CDH.SentimentalScore  > 60 THEN 1 ELSE 0 END)					AS postiveSentimentalScore
		,	COUNT(1)																	AS noOfCalls              	
  	FROM 	tb_ChatHistory 			CH    
  	JOIN 	tb_ChatDurationHistory	CDH	ON CH.ChatHistoryId	= CDH.ChatHistoryId  	
  	WHERE	CH.domainId 		= p_domainId 
  	AND 	CH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp; 

	INSERT INTO tmp_SentimentalScore(
    	negativeSentimentalScore
    ,   neutralSentimentalScore	
    ,   postiveSentimentalScore	
	,	noOfCalls               	
    )
  	SELECT 	SUM(CASE WHEN SH.SentimentalScore  <= 40 THEN 1 ELSE 0 END)				AS negativeSentimentalScore
		,	SUM(CASE WHEN SH.SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)	AS neutralSentimentalScore
		,	SUM(CASE WHEN SH.SentimentalScore  > 60 THEN 1 ELSE 0 END)				AS postiveSentimentalScore
		,	COUNT(1)																AS noOfCalls              	
  	FROM 	tb_SMSHistory 			SH    
  	JOIN 	tb_SMSDurationHistory	SDH	ON SH.SMSHistoryId	= SDH.SMSHistoryId  	
  	WHERE	SH.domainId 		= p_domainId 
  	AND 	SH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp; 
    
	INSERT INTO tmp_SentimentalScore(
    	negativeSentimentalScore
    ,   neutralSentimentalScore	
    ,   postiveSentimentalScore	
	,	noOfCalls               	
    )
  	SELECT 	SUM(CASE WHEN EH.SentimentalScore  <= 40 THEN 1 ELSE 0 END)				AS negativeSentimentalScore
		,	SUM(CASE WHEN EH.SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)	AS neutralSentimentalScore
		,	SUM(CASE WHEN EH.SentimentalScore  > 60 THEN 1 ELSE 0 END)				AS postiveSentimentalScore
		,	COUNT(1)																AS noOfCalls              	
  	FROM 	tb_EmailHistory 			EH    
  	JOIN 	tb_EmailDurationHistory		EDH	ON EH.EmailHistoryId	= EDH.EmailHistoryId  	
  	WHERE	EH.domainId 		= p_domainId 
  	AND 	EH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp;      
    
	INSERT INTO tmp_SentimentalScore(
    	negativeSentimentalScore
    ,   neutralSentimentalScore	
    ,   postiveSentimentalScore	
	,	noOfCalls               	
    )
  	SELECT 	SUM(CASE WHEN WH.SentimentalScore  <= 40 THEN 1 ELSE 0 END)				AS negativeSentimentalScore
		,	SUM(CASE WHEN WH.SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)	AS neutralSentimentalScore
		,	SUM(CASE WHEN WH.SentimentalScore  > 60 THEN 1 ELSE 0 END)				AS postiveSentimentalScore
		,	COUNT(1)																AS noOfCalls              	
  	FROM 	tb_WhatsappHistory 			WH    
  	JOIN 	tb_WhatsappDurationHistory	WDH	ON WH.WhatsappHistoryId	= WDH.WhatsappHistoryId  	
  	WHERE	WH.domainId 		= p_domainId 
  	AND 	WH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp;  

	INSERT INTO tmp_SentimentalScore(
    	negativeSentimentalScore
    ,   neutralSentimentalScore	
    ,   postiveSentimentalScore	
	,	noOfCalls               	
    )
  	SELECT 	SUM(CASE WHEN FH.SentimentalScore  <= 40 THEN 1 ELSE 0 END)				AS negativeSentimentalScore
		,	SUM(CASE WHEN FH.SentimentalScore  BETWEEN 41 AND 60 THEN 1 ELSE 0 END)	AS neutralSentimentalScore
		,	SUM(CASE WHEN FH.SentimentalScore  > 60 THEN 1 ELSE 0 END)				AS postiveSentimentalScore
		,	COUNT(1)																AS noOfCalls              	
  	FROM 	tb_FacebookHistory 	FH      	  	
  	WHERE	FH.domainId 		= p_domainId 
  	AND 	FH.sessionStartTime BETWEEN p_startTmpstmp and p_endTmpstmp;  
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
    
	SELECT 	SUM(negativeSentimentalScore)
		,	SUM(neutralSentimentalScore)
		,	SUM(postiveSentimentalScore)
		,	SUM(noOfCalls)
  	INTO 	v_negativeSentimentalScore		
        ,   v_neutralSentimentalScore	
        ,   v_postiveSentimentalScore	
  		,	v_noOfCalls
  	FROM 	tmp_SentimentalScore;        
      
  	SELECT 	ROUND(v_negativeSentimentalScore)						AS negativeSentimentalScore
		,   ROUND(v_neutralSentimentalScore)						AS neutralSentimentalScore
		,   ROUND(v_postiveSentimentalScore)						AS postiveSentimentalScore
		,	ROUND(v_negativeSentimentalScore / v_noOfCalls * 100)	AS negativeSentimentalScorePer
		,   ROUND(v_neutralSentimentalScore / v_noOfCalls	* 100)	AS neutralSentimentalScorePer
		,   ROUND(v_postiveSentimentalScore / v_noOfCalls	* 100)	AS postiveSentimentalScorePer;    	
  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
