CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DeclinedUser`(	
	p_SessionId			VARCHAR(250)
	,p_ChannelType		INT
	,p_UserId			BIGINT	
	,p_DomainId			INT
  )
BEGIN
 	DECLARE v_CurDate	DATETIME;
      
 	SET v_CurDate = NOW();        
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  
 	IF EXISTS (	SELECT 	1 
 				FROM 	tb_DeclinedUser 
 				WHERE 	SessionId 	= p_SessionId
 				AND 	UserId		= p_UserId)
 	THEN
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 	
 		SET v_CurDate = v_CurDate; 
 	ELSE
		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 		INSERT INTO tb_DeclinedUser
 		(	SessionId
 			,ChannelType
 			,UserId
 			,DomainId
 			,CreateDate    
 		)
 		VALUES
 		(	p_SessionId	
 			,p_ChannelType	
 			,p_UserId	
 			,p_DomainId
 			,v_CurDate
 		);
 	END IF;
 END ;;
