CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DeleteChatCategory`( 	p_ChatCategoryId	INT
 ,	p_DomainId			INT)
BEGIN
 	DECLARE	v_ChatCategoryId	INT;
     DECLARE	v_ErrCode			INT;
     DECLARE	v_ErrMsg			VARCHAR(250);
 
 	SP_Logic: BEGIN	 
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 	ChatCategoryId INTO  v_ChatCategoryId
         FROM 	tb_ChatCategory
         WHERE 	ChatCategoryId	= p_ChatCategoryId
         AND 	DomainId		= p_DomainId;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;       
         IF v_ChatCategoryId IS NULL
         THEN
 			SET v_ErrCode 	= -1;
             SET v_ErrMsg 	= 'No Chat Category to Delete';
             LEAVE SP_Logic;
 		END IF;
         
         DELETE FROM tb_ChatArticle WHERE ChatCategoryId	= v_ChatCategoryId;
         DELETE FROM tb_ChatCategory WHERE ChatCategoryId = v_ChatCategoryId;
         
         SET v_ErrCode 	= 0;
 		SET v_ErrMsg 	= 'Chat Category Deleted Successfully';
 	END; 
 END ;;
DELIMITER ;
