CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DeleteCustomerContact`(
     p_coid_list text,
     p_domainId INT
 )
BEGIN
     DECLARE v_errcode INT; 
     DECLARE v_errmsg VARCHAR(60);
 
     IF NOT EXISTS (
         SELECT *
         FROM customer_contact 
         WHERE coid = p_coid_list 
         AND domainId = p_domainId
     ) THEN
         SET v_errcode = -1;
         SET v_errmsg = 'Not Deleted';
     ELSE
         SET @delete_query = CONCAT('DELETE FROM customer_contact WHERE coid IN (', p_coid_list, ') AND domainId = ', p_domainId);
 
         PREPARE stmt FROM @delete_query;
         EXECUTE stmt;
         DEALLOCATE PREPARE stmt;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Multiple Rows deleted successfully';
     END IF;
 
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
