CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_DeleteFacebookConfiguration`(	
  	p_FacebookConfigurationId	INT
  	,p_domainId 				INT
  )
BEGIN	
  
		DECLARE v_errcode 	INT  DEFAULT -1;
		DECLARE v_errmsg	VARCHAR(30)  DEFAULT 'Delete Fail';
		DECLARE v_FacebookConfigurationId	INT;
        
    SELECT FacebookConfigurationId INTO v_FacebookConfigurationId
    FROM 	tb_FacebookConfiguration 
	WHERE 	FacebookConfigurationId 	= p_FacebookConfigurationId
	AND 	domainId 					= p_domainId;
    
	IF v_FacebookConfigurationId IS NOT NULL
	THEN
			UPDATE tb_FacebookConfiguration
			SET FacebookFlowId 			= null
				,FacebookPageId 		= null
				,pageName				= null
			WHERE 	FacebookConfigurationId 	=  v_FacebookConfigurationId;
            
            INSERT INTO tb_clientConfiguration_log(domainId,pageId,appId,appSecret,instagramId,authToken,email,pageName,whatsappId,createdDate,updatedDate,whatsappNumber,wabaId)
            SELECT domainId,pageId,appId,appSecret,instagramId,authToken,email,pageName,whatsappId,createdDate,updatedDate,whatsappNumber,wabaId 
            FROM tb_FacebookClientConfiguration
            WHERE domainId = p_domainId;
            
            DELETE FROM tb_FacebookClientConfiguration
            WHERE domainId = p_domainId;
  	
				 SET v_errcode = 0;
				 SET v_errmsg = 'Deleted sucessfully';
		END IF;
			  
       SELECT v_errcode as errcode , v_errmsg as errmsg;
  END ;;
DELIMITER ;
