CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DeleteStatusUpdateTicketSnippet`(
  p_TicketSnippetId  		INT,
  p_CompanyId				INT,
  p_ProductId             INT,
  p_IsActive 		 		TINYINT,
  p_IsDeleted		 		TINYINT,
  p_LoggedInUserID 		BIGINT
  )
begin
  
  declare v_errcode 	int 		  default -1;
  declare v_errmsg  	varchar(55)   default 'No Update';
  DECLARE v_CurDate  	DATETIME;
  
   SET v_CurDate = NOW();
  
  update tb_TicketSnippet 
  set    IsActive  			=  ifnull(p_IsActive,IsActive),
  	   IsDeleted			=  ifnull(p_IsDeleted,IsDeleted),
  	   UpdatedBy 			=  p_LoggedInUserID,
  	   UpdatedDate 			=  v_CurDate
  where  TicketSnippetId 		=  p_TicketSnippetId
  and    CompanyId			=  p_CompanyId
  and	   ProductId			=  p_ProductId;
  
  	    if row_count()>0
  		then
  				set v_errcode = 0;
  				set v_errmsg = 'updated successfully';
  		end if; 
          
          select v_errcode as errcode, v_errmsg as errmsg;
  
  end ;;
DELIMITER ;
