/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DeleteTicket`( 
     p_TicketId			VARCHAR(250),
     p_CompanyId 			INT,
     p_ProductId			INT,
     p_IsDeleted 			TINYINT
     )
BEGIN
       DECLARE v_CurDate  DATETIME;
       DECLARE v_errcode  INT          DEFAULT -1;
       DECLARE v_errmsg   VARCHAR(100) DEFAULT 'No Record Delete';
       DECLARE v_JLength  INT;
       DECLARE v_TicketLogDetailId	BIGINT; 
       DECLARE v_LastDeletedTicketId bigint;
       DECLARE v_RequestorId    INT;
       DECLARE v_AssignedToAgentId INT;
       DECLARE v_TicketAssociateCustContact INT;
       
       SET v_CurDate = NOW();
       
       DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketId;
       CREATE TEMPORARY TABLE tt_temp_TicketId (TicketId VARCHAR(100));
       
    	CALL split(p_TicketId, ',');
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
    	INSERT INTO tt_temp_TicketId (TicketId)
      	SELECT Items FROM tt_Split_temptable;
    	   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    	UPDATE 	tb_TicketDetails a
    	JOIN   	tt_temp_TicketId b 	ON a.TicketId 	= b.TicketId
    	SET    	a.IsDeleted 	= IFNULL(p_IsDeleted,a.IsDeleted)
    		,	a.UpdatedDate 	= v_CurDate;
            
    	set v_LastDeletedTicketId = last_insert_id();
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
       SELECT RequestorId, AssignedToAgentId, TicketAssociateCustContact
       INTO v_RequestorId, v_AssignedToAgentId, v_TicketAssociateCustContact
       FROM tb_TicketDetails
       WHERE TicketId = v_LastDeletedTicketId;
     
        INSERT INTO tb_TicketLogDetail
    		(	TicketId					
    			,LogDetails					
    			,IsDeleted		
    			,CompanyId 
                ,ProductId 
    			,CreatedBy					
    			,CreatedDate				
    			,UpdatedBy					
    			,UpdatedDate				
            )
           select
            	TicketId
    			,CONCAT('Deleted the ticket ',TicketId)
                ,1
                ,p_CompanyId 
                ,p_ProductId 
    			,0
                ,v_CurDate
                ,0
                ,v_CurDate
            
            from tt_temp_TicketId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    		SET v_TicketLogDetailId = last_insert_id();
           
           
           drop temporary table if exists tt_temp_TicketId_one; create temporary table tt_temp_TicketId_one  as  select * from tt_temp_TicketId;
           drop temporary table if exists tt_temp_TicketId_two; create temporary table tt_temp_TicketId_two  as  select * from tt_temp_TicketId;
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            INSERT INTO tb_TicketNotification
    		(	TicketId					
    			,TicketLogDetailId			
    			,NotificationUserId			
    			,NotificationUserTypeId		
    			,IsRead					
                ,CompanyId 
                ,ProductId 
    			,CreatedBy					
    			,CreatedDate				
    			,UpdatedBy					
    			,UpdatedDate				
            )
            SELECT 	x.TicketId
    			,	v_TicketLogDetailId
    			,	v_RequestorId
                ,	1117001			
                ,	0
                ,	p_CompanyId 
                ,	p_ProductId 
                ,	0
                ,	v_CurDate
                ,	0
                ,	v_CurDate
    		from tt_temp_TicketId_one x
    		UNION ALL		
    		SELECT 	y.TicketId
    			,	v_TicketLogDetailId
    			,	v_AssignedToAgentId
                ,	1117002			
                ,	0
                ,	p_CompanyId 
                ,	p_ProductId 
                ,	0
                ,	v_CurDate
                ,	0
                ,	v_CurDate 
    		from tt_temp_TicketId_two y
    		UNION ALL		
    		SELECT	z.TicketId
    			,	v_TicketLogDetailId
    			,	v_TicketAssociateCustContact
                ,	1117003			
                ,	0
                ,	p_CompanyId 
                ,	p_ProductId 
                ,	0
                ,	v_CurDate
                ,	0
                ,	v_CurDate 
            from tt_temp_TicketId z;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    	IF ROW_COUNT() > 0
          THEN
     		 SET v_errcode = 0;
              SET v_errmsg = 'Deleted Successfully';
              
              
              drop temporary table if exists tt_temp_TicketId_one;
              drop temporary table if exists tt_temp_TicketId_two; 
          END IF;
          
          SELECT v_errcode errcode,  v_errmsg errmsg; 
      END ;;
DELIMITER ;
