CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_DeleteTicketStatus`(
 	p_CompanyId 				INT
 	,p_ProductId 				INT
 	,p_StatusId 				INT
 	,p_AlternateStatusId 		INT
 	,p_LoggedInUserID 			BIGINT
 )
BEGIN
 	DECLARE v_errcode  						INT;
 	DECLARE v_errmsg   						VARCHAR(55);
 	DECLARE v_CurDate  						DATETIME;
 	DECLARE v_SLATimer						INT;
 	DECLARE v_LastUpdatedStatusId 			INT;
 	DECLARE v_StatusName   					VARCHAR(150);
 	DECLARE v_TicketLogDetailId 			INT;
 	DECLARE v_RequestorId    				INT;
 	DECLARE v_AssignedToAgentId 			INT;
 	DECLARE v_TicketAssociateCustContact 	INT;
     DECLARE v_uid							BIGINT DEFAULT CONCAT(ROUND(UNIX_TIMESTAMP(NOW(3))*1000),ROUND(RAND()*1000));
        
 	SET v_CurDate = NOW();
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
     
 	SELECT 	SLATimer INTO v_SLATimer 
 	FROM 	tb_TicketStatus
 	WHERE 	StatusId = p_StatusId;
     
     DROP TEMPORARY TABLE IF EXISTS tmp_TicketAssociatedPerson; 
     CREATE temporary TABLE tmp_TicketAssociatedPerson(
 		TicketId					BIGINT
         ,RequestorId				INT
         ,AssignedToAgentId			INT
         ,TicketAssociateCustContact	INT
     );
        
    IF EXISTS (	SELECT 	1
 				FROM 	tb_TicketStatus
 				WHERE 	StatusId 	= p_AlternateStatusId
 				AND 	SLATimer	= v_SLATimer)
    	THEN
 		UPDATE 	tb_TicketStatus
 		SET 	IsDeleted 	= 1
 			,	UpdatedBy	= p_LoggedInUserID
 			,	UpdatedDate	= v_CurDate
 		WHERE 	StatusId 	= p_StatusId;
         
         INSERT INTO tmp_TicketAssociatedPerson(TicketId, RequestorId, AssignedToAgentId,TicketAssociateCustContact)                
 		SELECT 	TicketId, RequestorId, AssignedToAgentId, TicketAssociateCustContact		
 		FROM 	tb_TicketDetails
 		WHERE 	CompanyId		= p_CompanyId
 		AND 	TicketStatusId 	= p_StatusId;
 
 		UPDATE 	tb_TicketDetails
 		SET 	TicketStatusId 	= p_AlternateStatusId
 			,	UpdatedBy		= p_LoggedInUserID
 			,	UpdatedDate		= v_CurDate
 		WHERE 	CompanyId		= p_CompanyId
 		AND 	TicketStatusId 	= p_StatusId;
 
 		SET v_LastUpdatedStatusId = p_AlternateStatusId;
        
        SELECT StatusName INTO v_StatusName
        FROM  tb_TicketStatus 
        WHERE StatusId	= v_LastUpdatedStatusId;
        
 
 
        
 		INSERT INTO tb_TicketLogDetail
 		(	TicketId					
 			,LogDetails					
 			,IsDeleted		
 			,CompanyId 
 			,ProductId 
             ,LogUid
 			,CreatedBy					
 			,CreatedDate				
 			,UpdatedBy					
 			,UpdatedDate				
 		)
 		SELECT
 			TicketId
 			,CONCAT('Updated Status to',v_StatusName)
 			,1
 			,p_CompanyId 
 			,p_ProductId 
             ,v_uid
 			,p_LoggedInUserId
 			,v_CurDate
 			,p_LoggedInUserId
 			,v_CurDate
 		FROM tmp_TicketAssociatedPerson;
            
 
            
 		INSERT INTO tb_TicketNotification
    		(	TicketId					
    			,TicketLogDetailId			
    			,NotificationUserId			
    			,NotificationUserTypeId		
    			,IsRead					
             ,CompanyId 
             ,ProductId 
    			,CreatedBy					
    			,CreatedDate				
    			,UpdatedBy					
    			,UpdatedDate				
 	   )
 	   SELECT 	t_TAP.TicketId
 			,	TicketLogDetailId
 			,	RequestorId
 			,	1117001			
 			,	0
 			,	p_CompanyId 
 			,	p_ProductId 
 			,	p_LoggedInUserId
 			,	v_CurDate
 			,	p_LoggedInUserId
 			,	v_CurDate
 		FROM 	tmp_TicketAssociatedPerson	t_TAP	
         JOIN 	tb_TicketLogDetail			LD		ON t_TAP.TicketId = LD.TicketId        
 		WHERE 	LD.LogUid	= v_uid;
 		
         INSERT INTO tb_TicketNotification
    		(	TicketId					
    			,TicketLogDetailId			
    			,NotificationUserId			
    			,NotificationUserTypeId		
    			,IsRead					
             ,CompanyId 
             ,ProductId 
    			,CreatedBy					
    			,CreatedDate				
    			,UpdatedBy					
    			,UpdatedDate				
 	   )
 		SELECT 	t_TAP.TicketId
 			,	TicketLogDetailId
 			,	AssignedToAgentId
 			,	1117002			
 			,	0
 			,	p_CompanyId 
 			,	p_ProductId 
 			,	p_LoggedInUserId
 			,	v_CurDate
 			,	p_LoggedInUserId
 			,	v_CurDate 
 		FROM 	tmp_TicketAssociatedPerson	t_TAP	
         JOIN 	tb_TicketLogDetail			LD		ON t_TAP.TicketId = LD.TicketId        
 		WHERE 	LD.LogUid	= v_uid;
 		
         INSERT INTO tb_TicketNotification
    		(	TicketId					
    			,TicketLogDetailId			
    			,NotificationUserId			
    			,NotificationUserTypeId		
    			,IsRead					
             ,CompanyId 
             ,ProductId 
    			,CreatedBy					
    			,CreatedDate				
    			,UpdatedBy					
    			,UpdatedDate				
 	   )
 		SELECT	t_TAP.TicketId
 			,	TicketLogDetailId
 			,	TicketAssociateCustContact
 			,	1117003			
 			,	0
 			,	p_CompanyId 
 			,	p_ProductId 
 			,	p_LoggedInUserId
 			,	v_CurDate
 			,	p_LoggedInUserId
 			,	v_CurDate 
 		FROM 	tmp_TicketAssociatedPerson t_TAP	
         JOIN 	tb_TicketLogDetail			LD		ON t_TAP.TicketId = LD.TicketId        
 		WHERE 	LD.LogUid	= v_uid;
         
 		SET v_errcode 	= -1;
 		SET v_errmsg	= 'Deleted Sucessfully';
    	ELSE
 		SET v_errcode 	= -1;
 		SET v_errmsg	= 'Cannot delete the record';		
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END IF;
        
        SELECT v_errcode as errcode, v_errmsg as errmsg;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
