CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_DeleteWhatsappConfiguration`(	
  	p_WhatsappConfigurationId	INT
  	,p_domainId 				INT
  )
BEGIN	
  
		DECLARE v_errcode 	INT DEFAULT -1;
		DECLARE v_errmsg	VARCHAR(30) DEFAULT 'Delete Fail';
		DECLARE v_WhatsappConfigurationId	INT;

		SELECT WhatsappConfigurationId INTO v_WhatsappConfigurationId
        FROM tb_WhatsappConfiguration
		WHERE 	WhatsappConfigurationId 	= p_WhatsappConfigurationId
		AND 	domainId 					= p_domainId;
    
    IF v_WhatsappConfigurationId IS NOT NULL
    THEN
			UPDATE tb_WhatsappConfiguration
			SET whatsappFlowId 			= null
				,whatsappNumber 		= null
				,businessName			= null
			WHERE 	WhatsappConfigurationId 	= v_WhatsappConfigurationId;
			
            INSERT INTO tb_clientConfiguration_log(domainId,pageId,appId,appSecret,instagramId,authToken,email,pageName,whatsappId,createdDate,updatedDate,whatsappNumber,wabaId)
            SELECT domainId,pageId,appId,appSecret,instagramId,authToken,email,pageName,whatsappId,createdDate,updatedDate,whatsappNumber,wabaId FROM tb_FacebookClientConfiguration
            WHERE domainId = p_domainId;
            
            DELETE FROM tb_FacebookClientConfiguration 
            WHERE domainId = p_domainId;
  	
				 SET v_errcode = 0;
				 SET v_errmsg = 'Deleted sucessfully';
	END IF;		  
       SELECT v_errcode as errcode , v_errmsg as errmsg;
  END ;;
