CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Delete_Call_Register_Dtl`(
	p_domainId 			INT,
    p_ext				INT,
    p_deviceType		VARCHAR(50)
)
BEGIN
		DECLARE v_Code 		TINYINT DEFAULT -1;
        DECLARE v_Msg		VARCHAR(100) DEFAULT "Failed";
        
        IF EXISTS(SELECt 1 FROM tb_CallRegisterDetails WHERE domainId = p_domainId AND ext = p_ext AND deviceType = p_deviceType)
        THEN 
				DELETE FROM tb_CallRegisterDetails WHERE domainId = p_domainId AND ext = p_ext AND deviceType = p_deviceType;
                
                IF NOT EXISTS(SELECt 1 FROM tb_CallRegisterDetails WHERE domainId = p_domainId AND ext = p_ext AND deviceType = p_deviceType)
                THEN 
						SET v_Code = 1;
                        SET v_Msg = "Deleted Succesfully...";
                END IF;
			END IF;
            
		SELECt v_Code AS `Code`, v_Msg AS Msg;
END ;;
