CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_delete_ticket_draftchats`(
 p_TicketChatId	INT
 )
SP: BEGIN
 	DECLARE v_TicketChatId		INT;
     
 	SELECT 	TC.TicketChatId
     INTO 	v_TicketChatId
 	FROM 	tb_TicketChat			TC        
 	LEFT JOIN tb_TechSupportTicket	T ON TC.TicketChatId = T.TicketChatId
 	WHERE 	TC.TicketChatId 	= p_TicketChatId
 	AND 	T.TechSupportTicketId	IS NULL;    
     
 	IF v_TicketChatId IS NULL
     THEN
 		SELECT -1 AS errcode,'Cannot delete as the ticket has been for this chat' AS errmsg;
         LEAVE SP;
 	ELSE
 		DELETE FROM tb_TicketChat
 		WHERE TicketChatId = p_TicketChatId;
         
         SELECT 1 AS errcode,'Successfully deleted the chat' AS errmsg;
     END IF;
 END ;;
DELIMITER ;
