CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_delete_worktualApp`(
     IN p_appId INT
 )
BEGIN
     DECLARE v_curdate DATETIME;
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(100) DEFAULT 'isDelete is Failed';
     DECLARE rows_affected INT;
 
     SET v_curdate = NOW();
 
     UPDATE tb_worktualApp
     SET isDelete = 1
     WHERE appId = p_appId;
 
 
     SET rows_affected = ROW_COUNT();
 
     IF rows_affected > 0 THEN
         SET v_errcode = 0;
         SET v_errmsg = 'Deleted successfully';
     ELSE
         SET v_errcode = -1;
         SET v_errmsg = 'No rows were updated';
     END IF;
 SELECT v_errcode as errcode, v_errmsg as errmsg;
 END ;;
DELIMITER ;
