/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_email_agent_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_email_agent_servicelevel_analysis_metrics_filter`(
                 		p_startTmpstmp 		BIGINT,
                     	p_endTmpstmp 		BIGINT,
                     	p_domainId 			INT,
                     	p_agentId 			TEXT,
   					    p_offset 			INT,
  				        p_Limit 		    INT	
                 	)
sp_return:begin
        
          	DECLARE v_offset 					INT;	  	
          	DECLARE v_CurrentStartTmpstmp 		BIGINT;
          	DECLARE v_CurrentEndTmpstmp 		BIGINT;
       	    DECLARE v_PrevStartTmpstmp 			BIGINT;
          	DECLARE v_PrevEndTmpstmp 			BIGINT; 
      		DECLARE v_TmpstmpInterval			BIGINT;	
              
       	   DECLARE v_CurTotalCount 				INT;        
     	       DECLARE  v_PrevTotalCount 			INT;                    
             DECLARE v_DiffTotalPercent 			INT;     
            
       	   DECLARE  v_CurTotalSLA               INT; 
            DECLARE  v_PrevTotalSLA             	INT; 
            DECLARE  v_DiffTotalSLAPercent      	INT; 
       
       	   DECLARE v_PretotalDurationCount         INT;
       	   DECLARE v_CurrenttotalDurationCount     INT;  
       
       	   DECLARE  v_CurTotalSLA1               INT; 
            DECLARE  v_PrevTotalSLA1               INT; 
            DECLARE  v_DiffTotalSLA1Percent        INT; 
       
            DECLARE  v_CurMissedChats             INT; 
            DECLARE  v_PrevMissedChats            INT; 
            DECLARE  v_DiffMissedChatsPercent     INT; 
       
         
     	      DECLARE  v_CurSLA1               		INT; 
            DECLARE  v_PrevSLA1              		INT; 
            DECLARE  v_DiffSLA1Percent       		INT; 
         
  		  DECLARE  v_CurSLA2               		INT; 
            DECLARE  v_PrevSLA2              		INT; 
            DECLARE  v_DiffSLA2Percent       		INT;  
         
  		  DECLARE  v_CurSLA3               		INT; 
            DECLARE  v_PrevSLA3              		INT; 
            DECLARE  v_DiffSLA3Percent       		INT;  
         
     	      DECLARE  v_CurSLA4               		INT; 
            DECLARE  v_PrevSLA4              		INT; 
            DECLARE  v_DiffSLA4Percent       		INT;  
         
     		  DECLARE  v_CurSLA5               		INT; 
            DECLARE  v_PrevSLA5              		INT; 
            DECLARE  v_DiffSLA5Percent       		INT;    
      		
      	   DECLARE  v_CurSLA6               	INT; 
            DECLARE  v_PrevSLA6              		INT; 
            DECLARE  v_DiffSLA6Percent       		INT; 
        
       	   DECLARE  v_CuransweredSLACount       INT; 
            DECLARE  v_PrevansweredSLACount       INT; 
            DECLARE  v_DiffansweredSLAPercent     INT; 
            
       	   DECLARE  v_CurabandonedSLACount      INT; 
            DECLARE  v_PrevabandonedSLACount      INT; 
            DECLARE  v_DiffabandonedSLAPercent    INT; 
            
       	   DECLARE  v_CurSLAbreachedCount       INT; 
            DECLARE  v_PrevSLAbreachedCount       INT; 
            DECLARE  v_DiffSLAbreachedPercent     INT; 
            
            
  		  DECLARE  v_CurChatTypeCount                   INT; 
            DECLARE  v_PrevChatTypeCount               	INT; 
            DECLARE  v_DiffChatTypePercent             	INT;  
            
     	      DECLARE  v_CurOverdueCount                 	INT;   
     
            
                
       	 SET v_offset =  p_Limit * p_offset; 
          
          	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
          	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
          	
        	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
        
        	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
        	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
          		
          	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
          	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
  		DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
    		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
    
       
                          		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                      		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                      		(    DispositionId 			INT
                      			,DispositionStatus 		VARCHAR(100)
                      			,DispositionCategory	TINYINT
                      		); 
                              
                      		INSERT INTO temp_AvailableDisposition 
                      		SELECT 	did 			DispositionId
                      			,	dispositionName	DispositionStatus
                      			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                      				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
                      				WHEN dispositionName = 'Disconnected'         THEN 4
               					    WHEN dispositionName = 'Resolved'             THEN 5
                      				END 			DispositionCategory
                      		FROM 	disposition_status
                      		WHERE 	domainId	= p_domainId;          
                            
          	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
          	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
          	CREATE TEMPORARY TABLE temp_AllagentId
          	SELECT 	UserID,UserName 
              FROM 	tb_User 
              WHERE 	domainId 	= p_domainId; 
                           
                    	DROP TEMPORARY TABLE IF EXISTS temp_ChatHistory; 
                  	   CREATE TEMPORARY TABLE temp_ChatHistory AS 	    	
         		SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		              AS SessionDate
         					,U.UserID                                                                 AS agentID
         					,U.UserName													      		  AS agentName     
       					    ,SH.EmailHistoryId
      					    ,SH.sessionStartTime
         					   ,SDH.Duration                                                       	  AS chatDuration                 
         					   ,SDH.Duration												      	  AS Duration
                             ,CASE WHEN  (FROM_UNIXTIME(SH.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END AS  Overdue
                             , CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END                AS Answered
                             , CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END 		        AS Abandoned
                      	FROM 	tb_EmailHistory 				SH
                      	JOIN 	tb_EmailDurationHistory		SDH	ON SH.EmailHistoryId 	= SDH.EmailHistoryId     
                  		LEFT JOIN 	tb_User					U	ON SDH.AgentId			= U.UserID  
      					LEFT JOIN 	temp_agentIDs 			t_A     ON SDH.AgentId		    = t_A.agentId  
                         LEFT JOIN temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
                         LEFT JOIN 	disposition_status		DS		ON DS.did					= SH.dispositionId and DS.domainId = SH.domainId
                      	WHERE 	SH.domainId 		= p_domainId		
      					AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
       				    AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));  
       
               	            DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc; 
                          	CREATE TEMPORARY TABLE temp_chatHistory_calc AS 	     
                          	SELECT
    						a.SessionDate 																										AS 'Date',
    						a.agentID,
    						a.agentName,
    						a.EmailHistoryId,
    						a.sessionStartTime,
  						(a.Answered+a.Abandoned)                             															    AS ChatType,  
    						SUM(a.Duration) 																									AS totalDuration,
    						SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)      				AS SL1,
    						SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)  				AS SL2,
    						SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL3,
    						SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL4,
    						SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL5,
    						SUM(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL6,
    						SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)     				AS TotalSLA,
    						SUM(CASE WHEN a.chatDuration > 30000 THEN 1 ELSE 0 END) 															AS MissedChats,
    						SUM(CASE WHEN a.Overdue = 'Aborted' THEN 1 ELSE 0 END)  															AS Overdue
    						FROM temp_ChatHistory a
    						GROUP BY a.SessionDate,a.agentID,a.agentName,a.EmailHistoryId,a.sessionStartTime,a.Answered,a.Abandoned; 
     
                          DROP TEMPORARY TABLE IF EXISTS temp_chatHistory_calc1; 
                      	CREATE TEMPORARY TABLE temp_chatHistory_calc1 AS 
                          SELECT
                          count(1),
                          a.Date,
                          a.agentID,
    						a.agentName,
    						a.EmailHistoryId,
    						a.sessionStartTime,
                          a.ChatType,
                          a.totalDuration,
                          a.SL1,
                          a.SL2,
                          a.SL3,
                          a.SL4,
                          a.SL5,
                          a.SL6,
                          a.TotalSLA,
                          a.MissedChats,
  						SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END)                    AS answeredSLA,
  					    SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END)                   AS abandonedSLA,    
  						SUM(CASE WHEN Overdue > 0 THEN 1 ELSE 0 END) / COUNT(1) * 100 AS SLAbreached							                                 
                        FROM temp_chatHistory_calc a  
                        GROUP BY a.Date,a.agentID,a.agentName,a.EmailHistoryId,a.sessionStartTime,a.ChatType,a.totalDuration,a.SL1, a.SL2,a.SL3,a.SL4,a.SL5,a.SL6,a.TotalSLA,a.MissedChats;
   
      	  SELECT  COUNT(EmailHistoryId),	SUM(TotalSLA), SUM(MissedChats) ,sum(ChatType)              														                     				 
            INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats ,v_CurChatTypeCount                           														                      					
            FROM 	temp_chatHistory_calc
            WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
        
        	SELECT 	COUNT(EmailHistoryId),SUM(TotalSLA), SUM(MissedChats) ,sum(ChatType)                       																								 
        	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats ,v_PrevChatTypeCount                                 														 										
        	FROM	temp_chatHistory_calc
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
       
         	SELECT 	SUM(IFNULL(Overdue, 0))
        	INTO 	v_CurOverdueCount 
         	FROM	temp_chatHistory_calc
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;
        
      	SELECT 	SUM(IFNULL(totalDuration, 0))
        	INTO 	v_CurrenttotalDurationCount 
       	FROM	temp_chatHistory_calc
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
           
       	SELECT 	SUM(IFNULL(totalDuration, 0))
        	INTO 	v_PretotalDurationCount 
       	FROM	temp_chatHistory_calc
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
           
       
       	SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
       	INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
       	FROM 	temp_chatHistory_calc
       	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
        
      	SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
      	INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
         	FROM	temp_chatHistory_calc
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
           
          SELECT 	SUM(IFNULL(answeredSLA, 0))
     	INTO 	v_PrevansweredSLACount 
     	FROM	temp_chatHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
      	SELECT 	SUM(IFNULL(answeredSLA, 0))
     	INTO 	v_CuransweredSLACount 
         FROM	temp_chatHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
     
      	SELECT 	SUM(IFNULL(abandonedSLA, 0))
     	INTO 	v_PrevabandonedSLACount 
     	FROM	temp_chatHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     
      	SELECT 	SUM(IFNULL(abandonedSLA, 0))
     	INTO 	v_CurabandonedSLACount 
   	FROM	temp_chatHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
     
   	SELECT 	SUM(IFNULL(SLAbreached, 0))
     	INTO 	v_PrevSLAbreachedCount 
     	FROM	temp_chatHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
  	SELECT 	SUM(IFNULL(SLAbreached, 0))
     	INTO 	v_CurSLAbreachedCount 
    	FROM	temp_chatHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
     
    	
           
  				
      	SET v_PrevTotalCount =       CASE WHEN v_PrevTotalCount = 0 then null else     v_PrevTotalCount end; 
       	SET v_PrevansweredSLACount = CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
        	SET v_PrevabandonedSLACount= CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
       	 SET v_PrevSLAbreachedCount = CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
           
          SET v_DiffTotalPercent 		    = (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
       	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
      	,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
        	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
        
        
          	SELECT * FROM temp_AllagentId;
           
           
          	SELECT 
                   IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
                   IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                   IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                   IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                   IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
                   IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';  
        
            SELECT
            	  'All Agents'												   							AS agentName
       	  	 ,'Answered'                                                   							AS ChatType
               ,IFNULL(v_CurSLA1,0)                                          							AS SL1
               ,IFNULL(v_CurSLA2,0)                                          							AS SL2
               ,IFNULL(v_CurSLA3,0)                                          							AS SL3
               ,IFNULL(v_CurSLA4,0)                                          							AS SL4
               ,IFNULL(v_CurSLA5,0)                                          							AS SL5
               ,IFNULL(v_CurSLA6,0)                                          							AS SL6
               ,IFNULL(v_CurTotalSLA,0)                                      							AS Total
               ,IFNULL(v_CurOverdueCount,0)                                   						AS Overdue
             
              
               ,0                                                                                   AS SLAAchieved
               ,0                                                                                   AS SLABreached

            UNION ALL
        	SELECT 	
                U.UserName													                                AS agentName
               ,   b.ChatType
               ,	count(b.SL1)
               ,	count(b.SL2)
       		 ,	count(b.SL3)
       		 ,	count(b.SL4)
       		 ,	count(b.SL5)
       		 ,	count(b.SL6)
               , sum(b.TotalSLA)
               , sum(b.Overdue)
               ,  CASE WHEN sum(b.TotalSLA/b.totalDuration) IS NOT NULL THEN sum(b.TotalSLA/b.totalDuration) ELSE '-' END                                    AS SLAachieved
               , sum(b.Overdue)/count(1)    AS SLAbreached
               FROM temp_chatHistory_calc b
               JOIN temp_ChatHistory      a      ON b.EmailHistoryId= a.EmailHistoryId
       		 JOIN 	temp_AllagentId		U	   ON a.AgentId	= U.UserID
       	     WHERE 	a.sessionStartTime    	   BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
               GROUP BY U.UserName,b.MissedChats,b.Overdue,b.ChatType;    
             
         SELECT CONCAT('agentName', 'ChatType', 'SL1', 'SL2', 'SL3', 'SL4', 'SL5', 'SL6', 'Total', 'Overdue', 'SLAAchieved', 'SLAbreached') AS  columnName;   
        
      	
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Email_Inboundchat_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Email_Inboundchat_analysis_metrics_filter`(
         p_startTmpstmp 	BIGINT,
         p_endTmpstmp 	BIGINT,
         p_domainId 		INT,    	
         p_agentId		VARCHAR(250),		
         p_offset 		INT,
         p_Limit 			INT	)
sp_return:BEGIN
     	DECLARE v_offset 					INT;	  	
     	DECLARE v_CurrentStartTmpstmp 		BIGINT;
     	DECLARE v_CurrentEndTmpstmp 		BIGINT;
     	DECLARE v_PrevStartTmpstmp 			BIGINT;
     	DECLARE v_PrevEndTmpstmp 			BIGINT; 
     	DECLARE v_TmpstmpInterval			BIGINT;	
       		
     	DECLARE v_CurTotalCount 			INT;        
     	DECLARE v_PrevTotalCount 			INT;                    
     	DECLARE	v_DiffTotalPercent 			INT;    
       		
    	DECLARE v_PrevRespondedEmailCount					INT;	
    	DECLARE v_CurrentRespondedEmailCount				INT;	        
  	DECLARE v_DiffRespondedEmailPercent				    INT;
        
       		
     	DECLARE v_PrevOpenedEmailCount		    			INT;	
    	DECLARE v_CurrentOpenedEmailCount					INT;
    	DECLARE v_DiffOpenedEmailPercent					INT;  	    
        
    	DECLARE v_PrevOverdueCount		    			    INT;	
    	DECLARE v_CurrentOverdueCount					    INT;
    	DECLARE v_DiffOverduePercent					    INT;  
        
        
         	
    	DECLARE v_CurrentMissedEmailCount		            INT;
  	DECLARE v_CurrentTransferredEmailCount				INT;
  	DECLARE v_CurrentDiscardedEmailCount				INT;
    	DECLARE v_CurrentMaximumEmailHandlingCount			INT;
  	DECLARE v_CurrentAverageEmailHandlingCount			INT;
    	DECLARE	v_CurrentCustomerEmailCount	                INT;
    	DECLARE v_CurrentAgentEmailCount					INT;
  	DECLARE v_totalEmailCount							INT;
  	DECLARE v_CurrentCustomerSatisfactionCount			INT;
     	DECLARE v_TotalemailDuration						BIGINT;
    
     
    
        
        	SET v_offset =  p_Limit * p_offset; 
         
     	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
     	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
         	
       	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       
       	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
       	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
         		
     	 	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
    		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                  	
                        
                          		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                      		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                      		(    DispositionId 			INT
                      			,DispositionStatus 		VARCHAR(100)
                      			,DispositionCategory	TINYINT
                      		); 
                              
                      		INSERT INTO temp_AvailableDisposition 
                      		SELECT 	did 			DispositionId
                      			,	dispositionName	DispositionStatus
                      			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                      				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                      				WHEN dispositionName = 'Discarded'     THEN 4
               					    WHEN dispositionName = 'Resolved'      THEN 5
                      				END 			DispositionCategory
                      		FROM 	disposition_status
                      		WHERE 	domainId	= p_domainId;
                       	
                       	DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                       	CREATE TEMPORARY TABLE temp_AllagentId
                       	SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
                           
              			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                       	DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory; 
                     	    CREATE TEMPORARY TABLE temp_EmailHistory AS 	    	
                           SELECT 
  						CAST(FROM_UNIXTIME(SH.sessionStartTime / 1000) AS DATE) AS SessionDate,
  						SH.SessionStartTime,
  						SDH.AgentId,
  						SH.EmailHistoryId,
  						U.UserName AS agentName,
  						SH.IsInBound,
  						SH.IsTransferred,
  						SH.DispositionId,
  						SH.DomainId,
  						SDH.AgentHoldDuration AS agentHoldDuration,
  						CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END AS Handled,
  						CASE WHEN t_D.DispositionCategory = 5 THEN 1 ELSE 0 END AS firstChatResolution,
  						SH.SessionStartTime AS agentConnectTime,
  						SH.SessionEndTime - SH.SessionStartTime AS EmailHandlingTime,
  						SH.repliedDate - SH.createdAt AS responseTime,
  						SDH.Duration,
  						SH.SessionEndTime - SH.SessionStartTime AS emailDuration,
  						SH.discardedDate,
  						CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END AS discarded,
  						CASE WHEN t_D.DispositionCategory = 2 THEN 1 ELSE 0 END AS Opened,
  						COUNT(DISTINCT CONCAT(SH.FromEmail, SH.EmailSubject)) AS customerEmailCount,
  						SH.EmailSubject,
  						SH.AfterEmailWorkTime,
  						SH.SentimentalScore
  					FROM tb_EmailHistory SH
  					JOIN tb_EmailDurationHistory SDH ON SH.EmailHistoryId = SDH.EmailHistoryId
  					LEFT JOIN temp_AvailableDisposition t_D ON SH.DispositionId = t_D.DispositionId
  					LEFT JOIN tb_User U ON U.UserID = SDH.AgentId
  					LEFT JOIN temp_agentIDs t_A ON U.UserID = t_A.agentId
  					WHERE 
  						SH.domainId = p_domainId
  						AND SH.sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
  						AND (IFNULL(p_agentId, '') = '' OR (IFNULL(p_agentId, '') <> '' AND t_A.agentId IS NOT NULL))
                      GROUP BY 
      SessionDate,SH.SessionStartTime,SDH.AgentId,SH.EmailHistoryId,U.UserName,SH.IsInBound,SH.IsTransferred,SH.DispositionId,SH.DomainId,SDH.AgentHoldDuration,Handled,firstChatResolution,
      SH.SessionStartTime,SH.SessionEndTime,SH.repliedDate,SDH.Duration,SH.discardedDate,discarded,Opened,SH.EmailSubject,SH.AfterEmailWorkTime,SH.SentimentalScore;
  
     	               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
        
                       DROP TEMPORARY TABLE IF EXISTS temp_EmailHistory_calc; 
    				   CREATE TEMPORARY TABLE temp_EmailHistory_calc AS 	
                       	SELECT 	  '-'     AS IsMissed
                                  , a.SessionDate 	
                                  , a.sessionStartTime
                                  , a.EmailHistoryId
                                  , a.AgentId
  								, a.agentName													          
                                  , a.IsInBound
    							    , a.Istransferred
                                  , a.DispositionId                                                          
                                  , a.agentHoldDuration                                                  
  								, a.Handled 		       	
 								, a.firstChatResolution                      
    							    , a.agentconnecttime                                                
  								,	round(SUM(a.EmailHandlingTime)/1000)				AS maximumEmailHandlingTime
  								,	round((SUM(a.EmailHandlingTime)/COUNT(1))/1000)	    AS averageEmailHandlingTime		    
  								,	a.responseTime				  				    	   
  								, a.Duration				
                                  ,count(a.AgentId)                                       AS agentEmailCount
                                  ,a.customerEmailCount                                   AS customerEmailCount
                                  ,a.emailDuration
                                  ,a.discardedDate
                                  ,a.discarded                                            AS discardedEmail
                                  ,a.Opened                                               AS OpenedEmail
                                  ,CASE WHEN  (FROM_UNIXTIME(a.SessionStartTime/1000)) >= (DATE_SUB(FROM_UNIXTIME(UNIX_TIMESTAMP(now())), INTERVAL 1 DAY)) THEN 'Resolved'ELSE 'Aborted'END     AS  Overdue
     							    , a.AfterEmailWorkTime                                       
     							    , a.SentimentalScore
                         	FROM 	temp_EmailHistory a   
    						GROUP BY a.SessionStartTime,a.Opened,a.discarded,a.discardedDate,a.emailDuration,a.EmailHistoryId,a.SessionDate,a.AgentId,a.agentName,a.IsInBound, a.Istransferred, a.DispositionId,a.agentHoldDuration,a.Handled,a.firstChatResolution,
                            a.agentconnecttime,a.EmailHandlingTime,a.responseTime,a.Duration,a.AfterEmailWorkTime,a.SentimentalScore,a.customerEmailCount  ;                      
    	DROP TEMPORARY TABLE IF EXISTS temp_PrevChatHistory; 
     	CREATE TEMPORARY TABLE temp_PrevChatHistory as
       	SELECT 	DISTINCT EmailHistoryId 
       	FROM 	temp_EmailHistory_calc
       	WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
             
     	DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
     	CREATE TEMPORARY TABLE temp_CurChatHistory AS
       	SELECT 	DISTINCT EmailHistoryId 
       	FROM 	temp_EmailHistory_calc
       	WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;                      
                             
    	DROP TEMPORARY TABLE IF EXISTS temp_PrevChatHistory; 
     	CREATE TEMPORARY TABLE temp_PrevChatHistory as
       	SELECT 	DISTINCT EmailHistoryId 
       	FROM 	temp_EmailHistory_calc
       	WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
             
     	DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
     	CREATE TEMPORARY TABLE temp_CurChatHistory AS
       	SELECT 	DISTINCT EmailHistoryId 
       	FROM 	temp_EmailHistory_calc
       	WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;    
                             
         	SELECT 	COUNT(EmailHistoryId), count(responseTime)
         	INTO 	v_PrevTotalCount , v_PrevRespondedEmailCount 
  		FROM	temp_EmailHistory_calc;
           
         	SELECT 	COUNT(EmailHistoryId), count(responseTime)
         	INTO 	v_curTotalCount , v_CurrentRespondedEmailCount 
  		FROM	temp_EmailHistory_calc;
            
    	    SELECT 	SUM(IFNULL(Overdue, 0))
       	INTO 	v_PrevOverdueCount 
       	FROM	temp_EmailHistory_calc
       	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
             
       	SELECT 	SUM(IFNULL(Overdue, 0))
       	INTO 	v_CurrentOverdueCount 
    	    FROM	temp_EmailHistory_calc
       	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
        
    	SELECT SUM(IsMissed), SUM(Istransferred), SUM(emailDuration), SUM(customerEmailCount), SUM(agentEmailCount),sum(discardedEmail),sum(OpenedEmail)
    	INTO 	v_CurrentMissedEmailCount, v_CurrentTransferredEmailCount, v_TotalemailDuration, v_CurrentCustomerEmailCount, v_CurrentAgentEmailCount,v_CurrentDiscardedEmailCount,v_CurrentOpenedEmailCount
    	FROM 	temp_EmailHistory_calc;
        
    	SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
       	SET v_PrevRespondedEmailCount 	= CASE WHEN v_PrevRespondedEmailCount = 0 then null else v_PrevRespondedEmailCount end;
       	SET v_PrevOverdueCount   	= CASE WHEN v_PrevOverdueCount = 0 then null else v_PrevOverdueCount end;
            
         	SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
         	,	v_DiffRespondedEmailPercent	= (v_CurrentRespondedEmailCount - v_PrevRespondedEmailCount) / v_PrevRespondedEmailCount * 100
        	,	v_DiffOverduePercent	= (v_CurrentOverdueCount - v_PrevOverdueCount) / v_PrevOverdueCount * 100; 
            
  
         	SELECT * FROM temp_AllagentId;        
            
           	SELECT 	IFNULL(v_CurTotalCount,0) 			    						AS 'TotalCount',
         			IFNULL(v_DiffTotalPercent,0) 		    							AS 'DiffTotalPercent',
         			IFNULL(v_CurrentRespondedEmailCount,0) 								AS 'CurrentResponseCount',
         			IFNULL(v_DiffRespondedEmailPercent,0) 								AS 'DiffResponsePercent',
         			IFNULL(v_CurrentOverdueCount,0) 	    							AS 'CurrentOverdueCount',
         			IFNULL(v_DiffOverduePercent	,0) 	    							AS 'DiffOverduePercent';	      
            
              SELECT
           	   'All Agents'												 			 	AS agentName
  			,IFNULL(v_CurTotalCount,0)                                 			 	 	AS receivedEmail
              ,IFNULL(v_CurrentOpenedEmailCount,0)                         			 	AS OpenedEmail          
  			,IFNULL(v_CurrentRespondedEmailCount,0)                       		 	 	AS respondedEmail
  			,IFNULL(v_CurrentMissedEmailCount,0)                          		 	 	AS missedEmail
              ,IFNULL(v_CurrentOverdueCount,0)                            			 	AS OverdueCount
              ,IFNULL(v_CurrentDiscardedEmailCount,0)                       		 	 	AS DiscardedEmail
              ,IFNULL(v_CurrentTransferredEmailCount,0)                     		 	 	AS transferredEmail
              ,IFNULL(v_CurrentMaximumEmailHandlingCount,0)                          	 	AS maximumEmailHandlingTime
              ,IFNULL(v_CurrentAverageEmailHandlingCount,0)                            	AS AverageEmailHandlingTime
              ,IFNULL(v_CurrentCustomerEmailCount,0)                                   	AS InteractionsFromCustomer          
              ,IFNULL(v_CurrentAgentEmailCount,0)									     	AS InteractionsFromAgent
              ,IFNULL(v_CurrentCustomerEmailCount,0)+IFNULL(v_CurrentAgentEmailCount,0)   AS totalInteractions
              ,IFNULL(v_CurrentCustomerSatisfactionCount,0)                 		        AS CustomerSatisfaction
          UNION ALL
       	SELECT 	U.UserName														    		AS agentName
       		 ,	COUNT(1)														    		AS receivedEmail
               ,	SUM(OpenedEmail)												    		AS OpenedEmail        
  			 ,	SUM(CASE WHEN CDH.dispositionId IS NOT NULL  THEN 1 ELSE 0 END) 		    AS respondedEmail
               ,	SUM(IsMissed)																AS missedEmail
               ,    SUM(Overdue)                                                      		AS OverdueCount
    		     ,	SUM(discardedEmail)															AS discardedEmail
               ,	SUM(Istransferred)															AS transferredEmail
               ,    SUM(maximumEmailHandlingTime)                                     		AS maximumEmailHandlingTime
               ,    SUM(averageEmailHandlingTime)                                     		AS averageEmailHandlingTime 
               ,    SUM(customerEmailCount)                                           		AS InteractionsFromCustomer
               ,	SUM(agentEmailCount)											    		AS InteractionsFromAgent
               ,   SUM(customerEmailCount) +sum(agentEmailCount)                      		AS totalInteractions
               ,   SUM(SentimentalScore)                                              		AS CustomerSatisfaction
           FROM 	temp_EmailHistory_calc 	  CDH
           JOIN 	temp_AllagentId				U	ON CDH.AgentId	= U.UserID	
           WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
           GROUP BY U.UserName;  
           
           END ;;
DELIMITER ;
