CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetActiveAgentForSupervisor`(
    p_emailId		VARCHAR(255)
    ,p_domainId		INT
    )
BEGIN
	DECLARE v_UserID	BIGINT;
    
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    SELECT 	UserID	INTO v_UserID
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	emailId 	COLLATE utf8mb4_unicode_ci = p_emailId
	AND 	roleid		IN (3,5);    
    
	IF v_UserID IS NOT NULL
  	THEN
  		SELECT 	 UserID
  				,UserName
  				,domainId
  				,ext
  				,voice
  				,chat
  				,email
  				,sms
  				,socialMedia
  		FROM 	tb_User
  		WHERE 	domainId 	= p_domainId
  		AND		isActive 	= 1
  		AND 	roleid		IN (3,5,6)	 ;
  	END IF;    
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
END ;;
DELIMITER ;
