CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetAgentBasedTicketDetls`(
     p_UserId			INT,
     p_CompanyId		INT
   )
BEGIN
  	DECLARE v_AllTickets   INT;
  	DECLARE v_PendingTickets      	INT;
  	DECLARE v_InProgressTickets   	INT;
  	DECLARE v_ClosedTickets         INT; 
      
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  
  	SELECT	TD.TicketId 	
  		,	TD.TicketSubject       
         ,	TD.CreatedDate		AS CreatedOn			
         ,	TU.UserName 		AS RequesterName		
  		,	TS.StatusName 		AS 'Status'	
         ,	P.TypeCodeName 		AS 'Priority'
  	FROM	tb_TicketDetails 	TD
  	LEFT JOIN tb_TicketStatus 	TS 	ON 	TD.TicketStatusId 	= TS.StatusId    
     LEFT JOIN tb_TicketUser   	TU 	ON 	TD.RequestorId    	= TU.UserId
     JOIN   TypeCode				P	ON 	TD.PriorityId		= P.TypeCodeID
 									AND	P.TypeGroupID		= 1116
  	WHERE 	TD.CompanyId			= p_CompanyId    
  
  	AND     TD.AssignedToAgentId	= p_UserId
  	AND	  	TD.IsDeleted			= 0;    
  
       
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
