/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetAgentBasedTicketHistory`(
    p_UserId		INT,
    p_CompanyId	INT
    )
begin
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    SELECT
        a.TicketAssociateCustContact,
        a.TicketId,
        b.TicketLogDetailId,
        b.LogDetails,
        a.CreatedBy,
        c.UserName AS 'CreatedByUser',
        a.CreatedDate,
        a.UpdatedBy,
        d.UserName AS 'UpdatedByUser',
        a.UpdatedDate
    FROM       tb_TicketDetails a 
    INNER JOIN tb_TicketLogDetail b ON a.TicketId = b.TicketId
    INNER JOIN tb_TicketUser c ON a.CreatedBy = c.UserId
    INNER JOIN tb_TicketUser d ON a.UpdatedBy = d.UserId
    WHERE 	a.AssignedToAgentId  	= p_UserId
    AND 		a.IsDeleted 			= 0;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
