CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetAgentListChat`(	
  	p_domainId					INT
  	,p_routing_profile_ids		VARCHAR(250)
  	,p_Ext						INT)
BEGIN	
    	DECLARE v_Ext	INT;   
        
    	DROP TEMPORARY TABLE IF EXISTS temp_Status;     
   	CREATE TEMPORARY TABLE temp_Status
   	(StatusId INT);
        
 	SET v_Ext = IFNULL(p_Ext,0);
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;     
    	INSERT INTO temp_Status(StatusId)
    	SELECT 	A_S.aid 
    	FROM 	agent_status A_S
    	WHERE 	A_S.domainId	= p_domainId
    	AND 	A_S.statusName 	IN 	('Ready', 'Transfer Only');
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
 	DROP TEMPORARY TABLE IF EXISTS temp_routing_profile_id;     
   	CREATE TEMPORARY TABLE temp_routing_profile_id
   	(	routing_profile_id INT );
   
   	CALL split(p_routing_profile_ids,',');
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
   	INSERT INTO temp_routing_profile_id(routing_profile_id)
   	SELECT Items FROM tt_Split_temptable;
     
 	SELECT 	U.UserID
 		,	U.UserName        
 		,	U.domainId
 		,	U.ext
 	FROM 	tb_User						U  	
 	JOIN 	temp_Status					S	ON U.StatusID			= S.StatusId
 	LEFT JOIN 	temp_routing_profile_id	RP	ON U.routing_profile_id = RP.routing_profile_id  											
 	WHERE 	U.domainId 		= p_domainId		
 	AND 	U.isVoice 		= 1 
 	AND 	U.roleid 		NOT IN (3)  	
  	AND 	U.ext			<> v_Ext
  	AND 	((p_routing_profile_ids IS NOT NULL AND 	RP.routing_profile_id IS NOT NULL)  OR 	(p_routing_profile_ids IS NULL))	
 	ORDER BY updatedAt ASC;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    DROP TEMPORARY TABLE IF EXISTS temp_Status; 
    DROP TEMPORARY TABLE IF EXISTS temp_routing_profile_id; 
  END ;;
DELIMITER ;
