CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetAgentUnclosedSession`(p_domainId	INT)
sp: BEGIN 		
     	DECLARE v_UnixDateBefore2Hour	BIGINT DEFAULT ((UNIX_TIMESTAMP() - 10800) * 1000) ; 
         DECLARE v_Date					DATE DEFAULT CURDATE();    
         
     	IF NOT EXISTS (SELECT 1 FROM tb_UnclosedSession WHERE domainId = p_domainId AND updatedDate = v_Date)
         THEN
     		CALL up_UpdateUnclosedSession(p_domainId);
     	END IF;
                 
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;           
  	
  	DROP TEMPORARY TABLE IF EXISTS temp_AgentUnclosedSession;    
  	CREATE TEMPORARY TABLE temp_AgentUnclosedSession 
  	(	historyId 			BIGINT
  		,durationHistoryId	BIGINT
  		,sessionStartTime	BIGINT
  		,agentId			INT
  		,queueId			INT
  		,queueName			VARCHAR(150)
  		,customerNumber		VARCHAR(20)
  		,email				VARCHAR(150)
  		,channelType		VARCHAR(10)
  		,isTrigger			tinyint
        ,sessionId			VARCHAR(250)					
  	);
  			 
				
				alter table temp_AgentUnclosedSession add index idx_agentId(agentId,queueId);
				
				
				alter table temp_AgentUnclosedSession add index idx_customerNumber(customerNumber);	
				alter table temp_AgentUnclosedSession add index idx_channelType(channelType);
                       
         			CREATE INDEX IX_temp_AgentUnclosedSession_email on temp_AgentUnclosedSession (email);                                    			                   
                		
                	   INSERT INTO temp_AgentUnclosedSession
           				(	historyId 		
           					,durationHistoryId	
           					,sessionStartTime	
           					,customerNumber		
           					,agentId	
           					,queueId
           					,email				
           					,channelType
                            ,isTrigger
                            ,sessionId											
                           )
                       	SELECT 	H.CallHistoryId	AS HistoryId
							,	DH.CallDurationHistoryId
							,	H.sessionStartTime
							,	H.customerNumber
							,	DH.AgentId   
							,	DH.QueueId
							,	NULL
							,	'Call'			ChannelType
							,	DH.isTrigger
                            ,   H.sessionId											
                       	FROM 	tb_CallHistory 			H
                       	JOIN 	tb_CallDurationHistory 	DH ON H.CallHistoryId 	= DH.CallHistoryId	
                       	WHERE 	H.domainId 					= p_domainId
  						AND 	H.sessionStartTime			>= v_UnixDateBefore2Hour
						AND 	DH.AgentId					IS NOT NULL
                       	
                       	AND 	DH.EndTime					= 0	
                       	AND		IFNULL(DH.dispositionId,0)  = 0
  						AND 	DH.IsBot					= 0;        
                       	 
     				INSERT INTO temp_AgentUnclosedSession
     				(	historyId 			    	
     					,durationHistoryId	
     					,sessionStartTime	
     					,customerNumber		
     					,agentId
     					,queueId	
     					,email				
     					,channelType		
                        ,isTrigger
                        ,sessionId														
                        )    
     				SELECT 	H.SMSHistoryId		AS HistoryId
						,	DH.SMSDurationHistoryId
						,	H.sessionStartTime
						,	H.customerNumber
						,	DH.AgentId  
						,	DH.QueueId	
						,	NULL
						,	'Sms'				AS ChannelType
						,	DH.isTrigger
                        , 	H.sessionId														
     				FROM 	tb_SMSHistory 			H
     				JOIN 	tb_SMSDurationHistory 	DH ON H.SMSHistoryId 	= DH.SMSHistoryId	
     				WHERE 	H.domainId 					= p_domainId
     				AND 	H.sessionStartTime			>= v_UnixDateBefore2Hour
					AND		DH.AgentId					IS NOT NULL
     				AND 	IFNULL(H.sessionEndTime,0) 	= 0	
     				AND		H.dispositionId				IS NULL
     				AND 	DH.IsBot					= 0;
                      
                       	INSERT INTO temp_AgentUnclosedSession
                           (	historyId
								,durationHistoryId	
								,sessionStartTime	
								,customerNumber		
								,agentId	
								,queueId
								,email				
								,channelType		
                                ,isTrigger
                                ,sessionId										
                                )
                       	SELECT 	H.WhatsappHistoryId		AS HistoryId
								,	DH.WhatsappDurationHistoryId
								,	H.sessionStartTime
								,	H.customerNumber
								,	DH.AgentId      
								,	DH.QueueId
								,	NULL
								,	'Whatsapp'				AS ChannelType
                                ,	DH.isTrigger
                                ,	H.sessionId										
						FROM 	tb_WhatsappHistory 			H
                       	JOIN 	tb_WhatsappDurationHistory 	DH ON H.WhatsappHistoryId 	= DH.WhatsappHistoryId	
                       	WHERE 	H.domainId 					= p_domainId
  						AND 	H.sessionStartTime			>= v_UnixDateBefore2Hour
						AND		DH.AgentId      			IS NOT NULL
                       	AND 	H.sessionEndTime	 		= 0	
                       	AND		H.dispositionId				IS NULL
  						AND 	DH.IsBot					= 0;  
     
                       	INSERT INTO temp_AgentUnclosedSession
								(	historyId 			    	
								,durationHistoryId	
								,sessionStartTime	
								,customerNumber		
								,agentId
								,queueId	
								,email				
								,channelType		
                                ,isTrigger
                                ,sessionId										
                                )
                       	SELECT 	H.EmailHistoryId	AS HistoryId		
                               ,	DH.EmailDurationHistoryId
                               ,	H.sessionStartTime
                               ,	NULL
                               ,	DH.AgentId
                               ,	DH.QueueId
                               ,	H.FromEmail
                               ,	'Email'			AS ChannelType
                               ,	DH.isTrigger
                               , 	H.SessionId										
							FROM 	tb_EmailHistory 			H
							JOIN 	tb_EmailDurationHistory 	DH ON H.EmailHistoryId 	= DH.EmailHistoryId	
							WHERE 	H.domainId 					= p_domainId
							AND 	H.SessionStartTime			>= v_UnixDateBefore2Hour
							AND 	DH.AgentId					IS NOT NULL
							AND 	IFNULL(H.sessionEndTime,0) 	= 0	
							AND		H.DispositionId				IS NULL
							AND 	DH.IsBot					= 0;    
     					
                           INSERT INTO temp_AgentUnclosedSession
                           (	historyId 			    	
								,durationHistoryId	
								,sessionStartTime	
								,customerNumber		
								,agentId	
								,queueId
								,email				
								,channelType		
                                ,isTrigger
                                ,sessionId											
                                )
							SELECT  H.FacebookHistoryId
								,	NULL
								,	H.sessionStartTime
								,	H.customerFacebookId
								,	H.AgentId
								,	NULL
								,	NULL
								,	'Facebook'
                                ,	H.isTrigger
                                ,	H.sessionId										
							FROM 	tb_FacebookHistory	H
							WHERE 	H.domainId = p_domainId
							AND 	H.sessionStartTime			>= v_UnixDateBefore2Hour
							AND 	IFNULL(H.sessionEndTime,0) 	= 0	
							AND		H.dispositionId				IS NULL
							AND 	H.AgentId					IS NOT NULL
							AND 	H.IsBot						= 0;       
     					  
                           INSERT INTO temp_AgentUnclosedSession
                           (	historyId 			    	
								,durationHistoryId	
								,sessionStartTime	
								,customerNumber		
								,agentId	
								,queueId
								,email				
								,channelType		
                                ,isTrigger
                                ,sessionId												
                                )
                           SELECT  H.InstagramHistoryId			
								,	Null
								,	H.sessionStartTime
								,	H.customerInstagramId
								,	H.AgentId
								,	NULL
								,	NULL
								,	'Instagram'
                                ,	H.isTrigger
                                ,	H.sessionId												
     					FROM 	tb_InstagramHistory	H
     					WHERE 	H.domainId = p_domainId
     					AND 	H.sessionStartTime			>= v_UnixDateBefore2Hour
						AND 	H.AgentId					IS NOT NULL	
     					AND 	IFNULL(H.sessionEndTime,0) 	= 0	
     					AND		H.dispositionId				IS NULL
     					AND 	H.IsBot						= 0;    
                          
                       	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	
                         CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),ext SMALLINT);    
                       	INSERT INTO temp_AvailableUser
                       	(		UserId
                       		,	UserName
							,	ext)
                       	SELECT  UserID
                       		,	UserName
                       		,	ext
                       	FROM 	tb_User
                       	WHERE 	domainId 	= p_domainId;                          	
                       	
          			ALTER TABLE temp_AgentUnclosedSession ADD COLUMN agentName VARCHAR(150), ADD COLUMN agentExt SMALLINT,ADD COLUMN customerName VARCHAR(150);                    
                      
  					DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
  					CREATE TEMPORARY TABLE temp_customer_contact(
  						coid				INT primary key,						
  						primaryPhoneNumber	varchar(30),
  						primaryEmail		varchar(150),
  						phoneNumber			varchar(750),
  						email				varchar(1500),
  						facebook			varchar(100),
  						instagram			varchar(100),
						customerName		varchar(200)
  					);
  						
  					ALTER TABLE temp_customer_contact ADD INDEX idx_customerName(primaryPhoneNumber,customerName); 			 
  					ALTER TABLE temp_customer_contact ADD INDEX idx_customerName1(primaryEmail,customerName); 
                      
  					INSERT INTO temp_customer_contact
  					SELECT 	coid
  						  ,	primaryPhoneNumber
  						  ,	primaryEmail
  						  ,	phoneNumber
  						  ,	email
  						  ,	facebook
  						  ,	instagram
  						  ,	CONCAT(IFNULL(CONCAT(firstName,' '),''),IFNULL(lastName,'')) customerName
  					FROM 	customer_contact 
  					WHERE 	domainId = p_domainId
  					AND		(primaryPhoneNumber <> '' OR primaryEmail <> '' OR phoneNumber <> '[]' OR email <> '[]' OR facebook <> '' OR instagram <> '' OR firstName <> '' OR lastName <> '');       
                      
  					INSERT INTO temp_AgentUnclosedSession
  					(	historyId 			    	
  					,	durationHistoryId	
  					,	sessionStartTime	
  					,	customerNumber		
                      ,	customerName
  					,	agentId		
  					,	queueId
  					,	email				
  					,	channelType
  					,	isTrigger
                    ,   sessionId											
                    )
  					SELECT 	H.ChatHistoryId	AS HistoryId
  						,	DH.ChatDurationHistoryId
  						,	H.sessionStartTime
  						,	t_C.primaryPhoneNumber
                          ,	t_C.customerName
  						,	DH.AgentId 
  						,	DH.QueueId
  						,	NULL
  						,	'Chat'				AS ChannelType
  						,	DH.isTrigger
                        , 	H.sessionId										
  					FROM 	tb_ChatHistory 			H
  					JOIN 	tb_ChatDurationHistory 	DH 	ON DH.ChatHistoryId 	= H.ChatHistoryId	
  					LEFT JOIN 	temp_customer_contact	t_C	ON t_C.coid			= H.CustomerId
  					WHERE 	H.domainId 					= p_domainId
  					AND 	H.sessionStartTime			>= v_UnixDateBefore2Hour
  					AND 	IFNULL(H.sessionEndTime,0) 	= 0	
  					AND		DH.dispositionId			IS NULL
  					AND 	IFNULL(DH.IsMissed,0)		<> 1
  					AND 	DH.IsBot					= 0;                       
                           
					UPDATE 	temp_AgentUnclosedSession	AUS
					JOIN 	temp_AvailableUser			AU	ON AUS.AgentId 	= AU.UserId
					LEFT JOIN queue						Q	ON AUS.queueId	= Q.qid	
					SET 		AUS.agentName = AU.UserName
                 			,	AUS.agentExt  = AU.ext
                 			,	AUS.queueName = Q.`name`;
                         
  				UPDATE 	temp_AgentUnclosedSession	SH 	
  				JOIN 	temp_customer_contact		c_c	ON 	c_c.primaryPhoneNumber	= SH.customerNumber	
  				SET 	SH.customerName	= c_c.customerName
  				WHERE  	SH.channelType	IN ('Call','Sms','Whatsapp' );
                      
  				UPDATE 	temp_AgentUnclosedSession	SH
  				JOIN 	temp_customer_contact	c_c	ON 	c_c.primaryEmail = SH.email											
  				SET 	SH.customerName	= c_c.customerName
  				WHERE 	SH.channelType	= 'Email';   
  						   
  				DROP TEMPORARY TABLE IF EXISTS temp_customer_contact1;
  				CREATE TEMPORARY TABLE temp_customer_contact1
  				SELECT 	customerName	
  					,	facebook
  				FROM 	temp_customer_contact
  				WHERE 	IFNULL(customerName,'') <> ''
  				AND		IFNULL(facebook,'') <> '';  
                      
  				UPDATE 	temp_AgentUnclosedSession	SH
  				JOIN 	temp_customer_contact1		c_c	ON 	c_c.facebook	LIKE SH.customerNumber											
  				SET 	SH.customerName	= c_c.customerName
  				WHERE 	channelType		= 'Facebook';   
                      
  				DROP TEMPORARY TABLE IF EXISTS temp_customer_contact1;
  				CREATE TEMPORARY TABLE temp_customer_contact1
  				SELECT customerName	
  					,	instagram
  				FROM 	temp_customer_contact
  				WHERE 	IFNULL(customerName,'') <> ''
  				AND		IFNULL(instagram,'') 	<> '';              
  			 
  				UPDATE 	temp_AgentUnclosedSession	SH
  				JOIN 	temp_customer_contact1		c_c	ON 	c_c.instagram	LIKE SH.customerNumber											
  				SET 	SH.customerName	= c_c.customerName
  				WHERE 	channelType		= 'Instagram';   
          
          			DROP TEMPORARY TABLE IF EXISTS temp_customer_contact1;
          			CREATE TEMPORARY TABLE temp_customer_contact1
                      SELECT 	coid
          				,	customerName	
          				,	phoneNumber
                      FROM 	temp_customer_contact
                      WHERE 	IFNULL(customerName,'') <> ''
                      AND		phoneNumber <> '[]'; 
                      
          			UPDATE 	temp_AgentUnclosedSession SH        
          			SET 	SH.customerName	= (SELECT customerName FROM temp_customer_contact1 InTC WHERE InTC.phoneNumber LIKE CONCAT('%',SH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)
          			WHERE 	channelType				= 'Email'
          			AND 	IFNULL(customerName,'')	= '';
                      
          			UPDATE 	temp_AgentUnclosedSession SH        
          			SET 	SH.customerName	= (SELECT customerName FROM temp_customer_contact1 InTC WHERE InTC.phoneNumber LIKE CONCAT('%',SH.customerNumber,'%') ORDER BY InTC.coid LIMIT 1)				
          			WHERE 	IFNULL(customerName,'')	= ''
          			AND 	channelType				IN ('Call','Sms','Whatsapp','Chat');
                       
           			
                           
         		  SELECT 	historyId, durationHistoryId, sessionStartTime, agentId, agentName, queueName, agentExt, customerNumber, customerName , email, channelType,isTrigger 
							,sessionId	
         		  FROM 	temp_AgentUnclosedSession;
  			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                 
       		DROP TEMPORARY TABLE IF EXISTS temp_AgentUnclosedSession;    
       		DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
       		DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	
       		DROP TEMPORARY TABLE IF EXISTS temp_customer_contact1;  
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetAllEmailAddress` */;
