CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetAppClientValid`(
    IN p_clientId    VARCHAR(100),
    IN p_redirectUrl VARCHAR(255)
)
BEGIN
    DECLARE v_errcode INT DEFAULT 0;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'This App exist';

    SELECT *
    FROM tb_worktualApp
