CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetAppClientValid1`(
    IN p_clientId VARCHAR(100),
    IN p_redirectUrl VARCHAR(255)
)
BEGIN
    DECLARE v_errcode INT DEFAULT 0;
    DECLARE v_errmsg VARCHAR(100) DEFAULT 'This App exists';
    DECLARE v_count INT;

    SELECT COUNT(*)
    INTO v_count
    FROM tb_worktualApp
    WHERE clientId = p_clientId
        AND redirectUrl = p_redirectUrl
        AND isPublicApp = 1
        AND isDelete IS NULL;

    IF v_count = 0 THEN
        SET v_errmsg = 'Invalid client or redirect URL';
    END IF;

    SELECT v_errmsg AS ErrorMessage;

    SELECT *
    FROM tb_worktualApp
    WHERE clientId = p_clientId
        AND redirectUrl = p_redirectUrl
        AND isPublicApp = 1
        AND isDelete IS NULL;

END ;;
DELIMITER ;
