CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetBusinessHolidaysByBusinessHoursId`(IN p_BusinessHoursId INT,
       IN p_CompanyId INT,
       IN p_ProductId INT)
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	
 		BusinessHoursHolidaysId,
 		BusinessHoursId,
 		HolidayName,
 		HolidayDescription,
 		FromDate,
 		ToDate,
 		IsActive
 	FROM tb_TicketBusinessHoursHolidays
 	WHERE 	BusinessHoursId = p_BusinessHoursId
     and		IsDeleted		= 0;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
