/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetBusinessHours`( 
        IN p_BusinessHoursId INT)
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	BH.BusinessHoursId
 			,BH.CompanyId 
 			,BH.ProductId 
 			,BH.Name
 			,BH.Description 
 			,BH.Timezone 
 			,BHT.BusinessHoursTimingsId
 			,BHT.BusinessHoursId
 			,BHT.BusinessDayTypeId
 			,BHT.FromHours
 			,BHT.FromAMPM
 			,BHT.ToHours
 			,BHT.ToAMPM
 			,BHT.IsDayOff
 			,BHT.IsDeleted
 	FROM 	tb_TicketBusinessHours			BH
 	JOIN 	tb_TicketBusinessHoursTimings 	BHT	ON BH.BusinessHoursId = BHT.BusinessHoursId
 	WHERE 	BH.BusinessHoursId 	= p_BusinessHoursId		
 	AND		BH.IsDeleted		= 0 
 	AND 	BHT.IsDeleted		= 0 ; 
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetBusinessHoursSearch` */;
