/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetBusinessHoursSearch`(IN p_CompanyId INT,
         IN p_ProductId INT,
         IN p_Search VARCHAR(150))
BEGIN
  	DECLARE v_BusinessHoursId	INT;
      DECLARE v_CurDate			DATETIME;
      
      SET v_CurDate = NOW();
      
  	SELECT 	BusinessHoursId	INTO v_BusinessHoursId
  	FROM 	tb_TicketBusinessHours
  	WHERE 	CompanyId 	= p_CompanyId 
  	AND		productId 	= p_ProductId     
      AND		IsDefault	= 1;
      
      IF v_BusinessHoursId IS NULL
      THEN
  		INSERT INTO tb_TicketBusinessHours 
  		(	CompanyId,
  			ProductId,
  			Name,
  			Description,
  			Timezone,
  			IsDeleted,
              IsDefault,
  			CreatedBy,
  			CreatedDate,
  			UpdatedBy,
  			UpdatedDate
  		) 
  		VALUES 
  		(	p_CompanyId,
  			p_ProductId,
  			'Default Hours',
  			'Default custom Hours to use in the  Queue',
  			'(GMT-8) Pacific Time',
  			0,
              1,
  			0,
  			v_CurDate,
  			0,
  			v_CurDate
  		);
          
  		SET v_BusinessHoursId = last_insert_id();
          
          INSERT INTO tb_TicketBusinessHoursTimings
  		(	BusinessHoursId		
  			,BusinessDayTypeId		
  			,FromHours				
  			,FromAMPM	
  			,ToHours				
  			,ToAMPM		
  			,IsDayOff				
  			,IsDeleted				
  			,CreatedBy				
  			,CreatedDate				
  			,UpdatedBy				
  			,UpdatedDate			
  		)
          VALUES	  (v_BusinessHoursId,1104002,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
  				 ,(v_BusinessHoursId,1104003,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
                  ,(v_BusinessHoursId,1104004,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
                  ,(v_BusinessHoursId,1104005,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
                  ,(v_BusinessHoursId,1104006,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
                  ,(v_BusinessHoursId,1104007,'','','','',1,0,0,v_CurDate,0,v_CurDate)
                  ,(v_BusinessHoursId,1104001,'','','','',1,0,0,v_CurDate,0,v_CurDate);
      END IF;
  		
  	SELECT 	BusinessHoursId,
  			CompanyId,
  			productId,
  			`Name`,
  			`Description`,
  			Timezone,
             IsDefault
  	FROM 	tb_TicketBusinessHours
  	WHERE 	IsDeleted	= 0 
  	AND 	CompanyId 	= p_CompanyId 
  	AND		productId 	= p_ProductId 
  	AND 	`Name` 		LIKE  CONCAT('%', p_Search, '%');
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetCallBackListForNotification` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCallBackListForNotification`(
	p_domainId 		INT
	,p_channelType 	VARCHAR(255)
	,p_offset 		INT
	,p_limit 		INT
)
BEGIN
	DECLARE v_offset 	INT;
	DECLARE v_limit 	INT;

	SET v_offset	= IFNULL(p_offset,0) * IFNULL(v_limit,50)
	,	v_limit		= IFNULL(v_limit,50);	
        
	DROP TEMPORARY TABLE IF EXISTS temp_getcallback_list;
	CREATE TEMPORARY TABLE temp_getcallback_list(	
		id_col 						INT AUTO_INCREMENT PRIMARY KEY
		,sessionId 					VARCHAR(250)
		,historyId					BIGINT
		,widgetId					INT
		,isThresholdTimeExceeded 	TINYINT
		,remainingThresholdTime		VARCHAR(20) 
		,customerId					BIGINT
		,customerName				VARCHAR(150)
		,customerNumber				VARCHAR(25)
		,customerEmail				VARCHAR(150)
		,assignedBy					BIGINT
		,assignedByName				VARCHAR(150)
		,assignedTo					BIGINT
		,assignedToName				VARCHAR(150)
		,assignedToExt				INT
		,channelType 				VARCHAR(255) 
	);    
        
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),ext INT);    
 	DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; CREATE TEMPORARY TABLE temp_AvailableUser1(UserId BIGINT, UserName VARCHAR(255),ext INT); 
        
	INSERT INTO temp_AvailableUser
	(	UserId
		,UserName
		,ext
	)
	SELECT  UserID
		,	UserName
		,	ext
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	roleid		IN (6,5,3);         
        
	INSERT INTO temp_AvailableUser1 SELECT * FROM temp_AvailableUser;
    
	DROP TEMPORARY TABLE IF EXISTS temp_customer_contact;
	CREATE TEMPORARY TABLE temp_customer_contact
	SELECT 	coid
		,	primaryPhoneNumber
		,	primaryEmail
		,	phoneNumber
		,	email
		,	facebook
		,	instagram
		,	firstName
		,	lastName          
	FROM 	customer_contact 
	WHERE 	domainId = p_domainId;       		
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
     
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	IF p_channelType LIKE '%Chat%'
	THEN   		
		INSERT IGNORE INTO temp_getcallback_list(	
			sessionId 					
 			,historyId					
 			,widgetId					
 			,isThresholdTimeExceeded 	
 			,remainingThresholdTime		            
 			,customerId
 			,assignedBy
 			,assignedTo
 			,channelType 				
 		)
		SELECT  cth.sessionId
			, 	cth.ChatHistoryId
			,	cth.chatWidgetId 
			,	CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),cth.createdAt),'%H.%i') >= PF.thresholdTime THEN 1 ELSE 0 END
			,	TIMEDIFF(NOW(),cth.createdAt)
			,	CustomerId
			,	cth.assignedBy
			,	cth.assignedTo
			,	'Chat'				
		FROM 	tb_ChatHistory 					cth
		JOIN 	chat_configuration_primary_form	PF	ON PF.aid	= cth.chatWidgetId 
		WHERE 	cth.domainId 		= p_domainId 										
		AND 	cth.CallBackStatus	= 1  
		ORDER BY cth.ChatHistoryId DESC LIMIT v_offset, v_limit;   		
     ELSEIF p_channelType LIKE '%Call%'
     THEN
		INSERT IGNORE INTO temp_getcallback_list(	
			sessionId 					
 			,historyId					
 			,widgetId					
 			,isThresholdTimeExceeded 	
 			,remainingThresholdTime		            
 			,customerId
             ,customerNumber
 			,assignedBy
 			,assignedTo
 			,channelType 				
 		)
		SELECT  H.sessionId
			, 	H.CallHistoryId
			,	NULL
			,	CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),H.createdAt),'%H.%i') >= C.threshold THEN 1 ELSE 0 END
			,	TIMEDIFF(NOW(),H.createdAt)
			,	NULL
			,	H.customerNumber
			,	H.assignedBy
			,	H.assignedTo
			,	'Call'				
		FROM 	tb_CallHistory 			H
		JOIN 	call_configuration		C	ON C.contactCenterNumber	= H.calledNumber         
		WHERE 	H.domainId 	= p_domainId 										
		AND 	H.callBack	= 1  
		ORDER BY H.CallHistoryId DESC LIMIT v_offset, v_limit;
     ELSEIF p_channelType LIKE '%Sms%'
     THEN
		INSERT ignore INTO temp_getcallback_list(	
			sessionId 					
 			,historyId					
 			,widgetId					
 			,isThresholdTimeExceeded 	
 			,remainingThresholdTime		            
 			,customerId
             ,customerNumber
 			,assignedBy
 			,assignedTo
 			,channelType 				
 		)
		SELECT  H.sessionId
 			, 	H.SMSHistoryId
 			,	NULL
 			,	CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),H.createdAt),'%H.%i') >= P.smsThreshold THEN 1 ELSE 0 END
 			,	TIMEDIFF(NOW(),H.createdAt)
 			,	NULL
			,	H.customerNumber
 			,	H.assignedBy
 			,	H.assignedTo
 			,	'Sms'				
		FROM 	tb_SMSHistory	H
		LEFT JOIN did_purchase	P	ON 	P.your_number	= H.calledNumber
									AND	P.isSmsOut 		= 1 
									AND P.isSmsIn 		= 1 
									AND P.domainId		= p_domainId
		WHERE 	H.domainId 	= p_domainId 
		AND		TIME_FORMAT(TIMEDIFF(NOW(),H.createdAt),'%H.%i') >= P.smsThreshold
		ORDER BY H.SMSHistoryId DESC LIMIT v_offset, v_limit;
 	ELSEIF p_channelType LIKE '%Email%'
     THEN
		INSERT ignore INTO temp_getcallback_list(	
			sessionId 					
 			,historyId					
 			,widgetId					
 			,isThresholdTimeExceeded 	
 			,remainingThresholdTime		            
 			,customerId
             ,customerEmail
 			,assignedBy
 			,assignedTo
 			,channelType 				
 		)
		SELECT  H.sessionId
 			, 	H.EmailHistoryId
 			,	NULL
 			,	CASE WHEN TIME_FORMAT(TIMEDIFF(NOW(),H.createdAt),'%H.%i') >= E.emailThreshold THEN 1 ELSE 0 END
 			,	TIMEDIFF(NOW(),H.createdAt)
 			,	NULL
			,	H.FromEmail
 			,	H.assignedBy
 			,	H.assignedTo
 			,	'Email'				
		FROM 	tb_EmailHistory	H
		LEFT JOIN email_config	E	ON 	E.emailAddress	= H.ToEmail									
									AND E.domainId		= p_domainId
		WHERE 	H.domainId 	= p_domainId 										
		AND 	TIME_FORMAT(TIMEDIFF(NOW(),H.createdAt),'%H.%i') >= E.emailThreshold
		ORDER BY H.EmailHistoryId DESC LIMIT v_offset, v_limit; 	
 	ELSEIF p_channelType LIKE '%Whatsapp%'
	THEN
		INSERT ignore INTO temp_getcallback_list(	
			sessionId 					
 			,historyId					
 			,widgetId					
 			,isThresholdTimeExceeded 	
 			,remainingThresholdTime		            
 			,customerId
			,customerNumber
 			,assignedBy
 			,assignedTo
 			,channelType 				
 		)
		SELECT  H.sessionId
			, 	H.WhatsappHistoryId
			,	NULL
			,	NULL
			,	TIMEDIFF(NOW(),H.createdAt)
			,	NULL
			,	H.customerNumber
			,	H.assignedBy
			,	H.assignedTo
			,	'Whatsapp'				
		FROM 	tb_WhatsappHistory	H
		WHERE 	H.domainId 		= p_domainId 				
		AND  	H.isCallback	= 1
		ORDER BY H.WhatsappHistoryId DESC LIMIT v_offset, v_limit; 		        
 	ELSEIF p_channelType LIKE '%Facebook%'
	THEN
		INSERT IGNORE INTO temp_getcallback_list(	
			sessionId 					
 			,historyId					
 			,widgetId					
 			,isThresholdTimeExceeded 	
 			,remainingThresholdTime		            
 			,customerId
             ,customerNumber
 			,assignedBy
 			,assignedTo
 			,channelType 				
 		)
		SELECT  H.sessionId
			, 	H.FacebookHistoryId
			,	NULL
			,	NULL
			,	TIMEDIFF(NOW(),H.createdAt)
			,	NULL
			,	H.customerFacebookId
			,	H.assignedBy
			,	H.assignedTo
			,	'Facebook'				
		FROM 	tb_FacebookHistory	H
		WHERE 	H.domainId 		= p_domainId 				
		AND  	H.isCallback	= 1
		ORDER BY H.FacebookHistoryId DESC LIMIT v_offset, v_limit; 	
 
	END IF; 
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
        
 	UPDATE 	temp_getcallback_list	t_CB
 	LEFT JOIN temp_customer_contact	t_CC	ON t_CC.coid	= t_CB.CustomerId
 	LEFT JOIN temp_AvailableUser	t_AU	ON t_AU.UserID	= t_CB.assignedBy
 	LEFT JOIN temp_AvailableUser1	t_AU1	ON t_AU1.UserID	= t_CB.assignedTo
 	SET 	customerName		= CONCAT(IFNULL(CONCAT(t_CC.firstName,' '),''),ifnull(t_CC.lastName,'')) 	
 		,	assignedByName		= t_AU.UserName    
 		,	assignedToName 		= t_AU1.UserName
 		,	assignedToExt		= t_AU1.ext;
 
 	UPDATE 	temp_getcallback_list	t_CB
 	LEFT JOIN temp_customer_contact	t_CC	ON t_CC.primaryPhoneNumber	= t_CB.customerNumber
	SET 	t_CB.customerName	= CONCAT(IFNULL(CONCAT(t_CC.firstName,' '),''),ifnull(t_CC.lastName,'')) 
	WHERE 	t_CB.channelType 	IN ('Whatsapp','Sms','Call'); 
     
 	UPDATE 	temp_getcallback_list	t_CB
 	LEFT JOIN temp_customer_contact	t_CC	ON t_CC.PhoneNumber	LIKE CONCAT('%',t_CB.customerNumber,'%')
	SET 	t_CB.customerName	= CONCAT(IFNULL(CONCAT(t_CC.firstName,' '),''),ifnull(t_CC.lastName,'')) 
	WHERE 	t_CB.channelType 	IN ('Whatsapp','Sms','Call');   
     
 	UPDATE 	temp_getcallback_list	t_CB
 	LEFT JOIN temp_customer_contact	t_CC	ON t_CC.instagram	= t_CB.customerNumber
	SET 	t_CB.customerName	= CONCAT(IFNULL(CONCAT(t_CC.firstName,' '),''),ifnull(t_CC.lastName,'')) 
	WHERE 	t_CB.channelType 	= 'Instagram';    
     
 	UPDATE 	temp_getcallback_list	t_CB
 	LEFT JOIN temp_customer_contact	t_CC	ON t_CC.facebook	= t_CB.customerNumber
	SET 	t_CB.customerName	= CONCAT(IFNULL(CONCAT(t_CC.firstName,' '),''),ifnull(t_CC.lastName,'')) 
	WHERE 	t_CB.channelType 	= 'Facebook';     
 		   
 	SELECT 	id_col,	sessionId, historyId, widgetId, isThresholdTimeExceeded, remainingThresholdTime, customerName, assignedByName, assignedToName, assignedToExt, channelType, customerId 
 	FROM 	temp_getcallback_list ORDER BY id_col DESC;
 END ;;
DELIMITER ;
