CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCallBackOptions`(	p_domainId		INT
 )
BEGIN
 	SELECT 	(SELECT emailAddress FROM email_config WHERE domainId = p_domainId AND primaryEmail = 1 AND isBotPurchased = 1 LIMIT 1)	emailAddress
 		,	(SELECT your_number FROM did_purchase p WHERE domainId = p_domainId AND (isSmsOut = 1 or isSmsIn =1) LIMIT 1)		smsNumber
 		,	(SELECT contactCenterNumber	FROM call_configuration WHERE domainId 	= p_domainId LIMIT 1)							callNumber;
 END ;;
DELIMITER ;
