CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetCallConfigurationLDetails`(	
   	p_contactCenterNumber	BIGINT
	,p_domainId				INT
)
BEGIN    
   	DECLARE IntentQueue		json;
       
   	WITH CTE_T AS (
   	SELECT JSON_OBJECT("intentGroupId",InIQ.intentGroupId,"queueId",InIQ.queueId,"addIntents",GROUP_CONCAT(intents) ) A
   	FROM tb_mapIntentQueue InIQ WHERE InIQ.contactCenterNumber = p_contactCenterNumber
   	GROUP BY InIQ.intentGroupId,InIQ.queueId)
   	SELECT json_arrayagg(A) G INTO IntentQueue FROM CTE_T; 
   
   	SELECT 	CC.contactCenterNumber
		, 	CC.name
		,	CC.domainId
		,	CC.Language
		,	CC.isBot
		,	CF.callFlowId
		, 	CF.templateName		AS callFlowName        
		,	CC.status
		,	CC.greetingMessage
		,	IntentQueue
		,  	CC.virtualAgent
		, 	CC.assistPriority
        ,	CC.threshold
        ,	CC.isMultilingualStatus
	FROM 	call_configuration 	CC    
	LEFT JOIN 	callFlow			CF	ON CF.callFlowId = CC.callFlowId		   		
	WHERE 	CC.domainId 	= p_domainId
	AND contactCenterNumber = p_contactCenterNumber;
       
   END ;;
DELIMITER ;
