CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_getCallHistoryBySessionId`(
 p_sessionId			varchar(250),
 p_domainId			INT
 )
BEGIN
 
 	DECLARE v_emailAddress		varchar(200);
 	DECLARE v_your_number		varchar(255);
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
     
 	SELECT 	emailAddress INTO v_emailAddress
 	FROM 	email_config 
 	WHERE 	domainId = p_domainId
 	LIMIT 1;
 
 	SELECT 	your_number	INTO v_your_number
 	FROM 	did_purchase 
 	WHERE 	domainId	= p_domainId
 	AND 	isSmsIn 	= 1 
 	AND 	isSmsOut 	= 1 LIMIT 1;   
     
 	SELECT 'Call' AS 'channeltype'
     ,v_emailAddress AS companyEmailAddress, v_your_number AS companySMSNumber
 	,CH.*,CM.Message 
	FROM 	tb_CallHistory 			CH
	JOIN 	tb_CallDurationHistory 	CDH ON CH.CallHistoryId = CDH.CallHistoryId
	LEFT JOIN 	tb_CallMessage 			CM 	ON CM.CallHistoryId = CH.CallHistoryId
	WHERE 	CH.sessionId 	= p_sessionId
	AND 	CH.domainId		= p_domainId; 
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
