CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetChatflowTemplate`(	p_domainId 	INT)
BEGIN
 	SELECT 	chatFlowId,templateName,language,version,type,status,companyId,domainId,description,action,category,channelType, updateAt 
 	FROM 	chatFlowHistory 
 	WHERE 	domainId	= p_domainId
 	AND		type		= 'Custom'
     UNION ALL
     SELECT flow_id, templateName,NULL language, 0 version, 'Default' type, status, null companyId,p_domainId domainId,description, null action, category, null channelType, null updateAt
     FROM 	defaulChatflowTemplate
     ORDER BY channelType,chatFlowId DESC;
 END ;;
