CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetChatHistoryDetails`(p_ChatHistoryId			BIGINT)
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	ChatHistoryId
 			,sessionId
 			,sessionStartTime
 			,sessionEndTime
 			,chatFlowSourceId
 			,companyId
 			,domainId
 			,dispositionId
 			,Summary
 			,IsInBound
 			,dialDuration
 			,disconnectedBy
 			,queueDuration
 			,assignedTo
 			,assignedBy
 			,assignedOn
 			,waitDuration
 			,afterChatWorkTime
 			,Istransferred
 			,transferredTypeId
 			,markAsRead
 			,CustomerId
 			,ticketId
 			,CallBackDatetime
 			,Browser
 			,IPAdress 
             ,ChatSubject
     FROM 	tb_ChatHistory
     WHERE 	ChatHistoryId = p_ChatHistoryId;    
     
 	SELECT 	ChatHistoryId
 		,	Message
     FROM 	tb_ChatMessage
     WHERE 	ChatHistoryId = p_ChatHistoryId;    
     
     SELECT 	ChatDurationHistoryId
 			,ChatHistoryId
 			,StartTime
 			,EndTime
 			,Duration
 			,AgentId
 			,AgentSkillId
 			,IsBot
 			,BotId
 			,transferredTime
 			,QueueId
     FROM 	tb_ChatDurationHistory
     WHERE 	ChatHistoryId = p_ChatHistoryId;    
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
