 			,CH.Istransferred
 			,CH.transferredTypeId
 			,CH.markAsRead
 			,CH.CustomerId
 			,CH.ticketId
 			,CH.CallBackDatetime
 			,CH.Browser
 			,CH.IPAdress
 			,CH.ChatSubject
             ,JSON_ARRAYAGG(JSON_OBJECT(
 			 'ChatDurationHistoryId', 	DH.ChatDurationHistoryId
 			,'ChatHistoryId',			CDH.ChatHistoryId
 			,'StartTime',				CDH.StartTime
 			,'EndTime',					CDH.EndTime
 			,'Duration',				CDH.Duration
 			,'AgentId',					CDH.AgentId
 			,'AgentSkillId',			CDH.AgentSkillId
 			,'IsBot',					CDH.IsBot
 			,'BotId',					CDH.BotId
 		 	,'transferredTime',			CDH.transferredTime
 			,'QueueId',					CDH.QueueId)) AgentDetails
 	FROM 	tb_ChatHistory			CH
 	JOIN 	tb_ChatDurationHistory	CDH	ON CH.ChatHistoryId = CH.ChatHistoryId
     WHERE 	ChatHistoryId = p_ChatHistoryId
     LIMIT p_Offest, p_Limit;  
     
 
 	SELECT 	CH.ChatHistoryId
 			,CH.sessionId
 			,CH.sessionStartTime
 			,CH.sessionEndTime
 			,CH.chatFlowSourceId
 			,CH.companyId
 			,CH.domainId
 			,CH.dispositionId
 			,CH.Summary
 			,CH.IsInBound
 			,CH.dialDuration
 			,CH.disconnectedBy
 			,CH.queueDuration
 			,CH.assignedTo
 			,CH.assignedBy
 			,CH.assignedOn
 			,CH.waitDuration
 			,CH.afterChatWorkTime
 			,CH.Istransferred
 			,CH.transferredTypeId
 			,CH.markAsRead
 			,CH.CustomerId
 			,CH.ticketId
 			,CH.CallBackDatetime
 			,CH.Browser
 			,CH.IPAdress
 			,CH.ChatSubject
             ,(	SELECT 	JSON_ARRAYAGG(JSON_OBJECT(
 										'ChatDurationHistoryId', 	InCDH.ChatDurationHistoryId,
 										'ChatHistoryId',			InCDH.ChatHistoryId,
 										'StartTime',				InCDH.StartTime,
 										'EndTime',					InCDH.EndTime,
 										'Duration',					InCDH.Duration,
 										'AgentId',					InCDH.AgentId,
 										'AgentSkillId',				InCDH.AgentSkillId,
 										'IsBot',					InCDH.IsBot,
 										'BotId',					InCDH.BotId,
 										'transferredTime',			InCDH.transferredTime,
 										'QueueId',					InCDH.QueueId))
 										FROM 	tb_ChatDurationHistory InCDH
 										WHERE 	InCDH.ChatHistoryId = CH.ChatHistoryId) AgentDetails
 	FROM 	tb_ChatHistory			CH	
     WHERE 	CH.ChatHistoryId = p_ChatHistoryId
     LIMIT 	p_Offest, p_Limit;  
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    

 END ;;
DELIMITER ;
