CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCheckLoginCode`(	 
    IN p_clientId VARCHAR(500),
    IN p_clientSecret VARCHAR(100),
    IN p_redirectUrl VARCHAR(255),
    IN p_loginCode VARCHAR(500)
)
BEGIN
    SELECT * 	
    FROM tb_worktualApp AS CH
    LEFT JOIN tb_thirdPartyLoginCode AS CDH ON CH.clientId = CDH.clientId
    WHERE CH.clientId = p_clientId
    AND CH.clientSecret = p_clientSecret
    AND CH.redirectUrl = p_redirectUrl
    AND CDH.loginCode=p_loginCode;    
END ;;
