CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetContact`(
      p_CompanyId INT,
      p_ProductId INT
  )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      SELECT
          t.TicketContactId,
          t.FirstName,
          t.LastName,
          GROUP_CONCAT(DISTINCT tc.ContactInformation SEPARATOR ', ') AS Email,
          GROUP_CONCAT(DISTINCT ci.ContactInformation SEPARATOR ', ') AS Contact
      FROM
          tb_TicketContact t
          LEFT JOIN tb_TicketContactInformation tc ON t.TicketContactId = tc.TicketContactId AND tc.ContactInformationTypeId = 1108029
          LEFT JOIN tb_TicketContactInformation ci ON t.TicketContactId = ci.TicketContactId AND ci.ContactInformationTypeId = 1108030
      WHERE
          t.CompanyId = p_CompanyId
          AND t.ProductId = p_ProductId
          AND t.IsDeleted = 0
      GROUP BY
          t.TicketContactId,
          t.FirstName,
          t.LastName;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
