CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetContactBasedTicketDetls`(
   p_TicketContactId	INT,
   p_CompanyId			INT,
   p_ProductId			INT
   )
begin
   
       declare v_AllTickets   INT;
       declare v_PendingTickets      	INT;
   	declare v_InProgressTickets   	INT;
       declare v_ClosedTickets         INT; 
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	DROP temporary TABLE IF EXISTS Temp_TicketDetails;
       create temporary table Temp_TicketDetails 
       SELECT	TD.TicketId, 
     			TD.AssignedToGroupId,
     			TD.AssignedToAgentId,
     			TD.CreatedDate,
     			TD.CreatedBy,
     			TS.StatusName, 
     			TD.ResolutionDueDate  
       FROM	tb_TicketDetails 	TD
       JOIN 	tb_TicketStatus 	TS 	ON TD.TicketStatusId = TS.StatusId
       WHERE 	TD.CompanyId					= p_CompanyId    
       AND     TD.ProductId					= p_ProductId
       AND     TD.TicketAssociateCustContact	= IFNULL(p_TicketContactId, TD.TicketAssociateCustContact);
         
   	SELECT COUNT(1) into v_AllTickets
   	FROM Temp_TicketDetails;
       
   	SELECT COUNT(1) into v_PendingTickets
       FROM   Temp_TicketDetails 
       WHERE  StatusName = 'Pending';
       
   	SELECT COUNT(1) into v_InProgressTickets
       FROM   Temp_TicketDetails 
       WHERE  StatusName = 'InProgress';
       
   	SELECT COUNT(1) into v_ClosedTickets 
       FROM   Temp_TicketDetails 
       WHERE  StatusName = 'Closed';
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       DROP temporary TABLE IF EXISTS Temp_TicketDetails;
   	SELECT 	v_AllTickets  			as  AllTickets
   		,	v_PendingTickets		as	PendingTickets
    		,	v_InProgressTickets		as  InProgressTickets
    		,	v_ClosedTickets			as	MyClosedTickets;
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	
   select a.TicketAssociateCustContact,
   	   a.TicketId,
          a.TicketSubject,
          a.PriorityId,
          a.TicketStatusId,
          a.TicketSourceId,
          a.CreatedDate,
          b.TypeCodeName as 'Priority',
          c.StatusName as 'Status'
   from   tb_TicketDetails a,
   	   TypeCode			b,
          tb_TicketStatus	c
   where  a.TicketAssociateCustContact = p_TicketContactId
   and    a.PriorityId					= b.TypeCodeID
   and	   b.TypeGroupID				= 1116
   and	   a.TicketStatusId				= c.StatusId
   and	   a.IsDeleted					= 0;
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetContactBasedTicketHistory` */;
