CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetContactBasedTicketHistory`(
   p_TicketContactId	INT,
   p_CompanyId			INT,
   p_ProductId			INT
   )
begin
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   SELECT
       a.TicketAssociateCustContact,
       a.TicketId,
       b.TicketLogDetailId,
       b.LogDetails,
       a.CreatedBy,
       c.UserName AS 'CreatedByUser',
       a.CreatedDate,
       a.UpdatedBy,
       d.UserName AS 'UpdatedByUser',
       a.UpdatedDate
   FROM       tb_TicketDetails a 
   INNER JOIN tb_TicketLogDetail b ON a.TicketId = b.TicketId
   INNER JOIN tb_TicketUser c ON a.CreatedBy = c.UserId
   INNER JOIN tb_TicketUser d ON a.UpdatedBy = d.UserId
   WHERE
       a.TicketAssociateCustContact = p_TicketContactId
       AND a.IsDeleted = 0;
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
