CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetContactBasedTicketLink`(
   p_TicketContactId	INT,
   p_CompanyId			INT,
   p_ProductId			INT
   )
begin
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   SELECT
       b.TicketLinksId,
       b.TicketId,
       b.Link,
       b.LinkName,
       b.CreatedBy,
       c.UserName AS 'CreatedByUser',
       b.CreatedDate,
       b.UpdatedBy,
       d.UserName AS 'UpdatedByUser',
       b.UpdatedDate
   FROM tb_TicketDetails a
   JOIN tb_TicketLinks   b ON a.TicketId = b.TicketId
   JOIN tb_TicketUser    c ON b.CreatedBy = c.UserId
   JOIN tb_TicketUser    d ON b.UpdatedBy = d.UserId
   WHERE
       a.TicketAssociateCustContact = p_TicketContactId
       AND a.IsDeleted = 0
       AND b.IsDeleted = 0;
   
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   end ;;
DELIMITER ;
