CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetContactSearch`(
                p_TicketContactId	INT,
                p_CompanyId 		INT,
                p_ProductId			INT)
BEGIN
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT t.coid,
 				t.firstName as FirstName, 
 				t.lastName as LastName, 
 				t.email AS Email,  
 				t.phoneNumber AS Contact,
 				address as Address,
 				postalCode as Zipcodes
 		FROM customer_contact t where coid = p_TicketContactId;
 
  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 		
    END ;;
