CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCustomerByNameEmail`( 	
	p_firstName		VARCHAR(100)
	,p_lastName		VARCHAR(100)
	,p_primaryEmail	VARCHAR(150)    
	,p_domainId		INT
  )
SP:BEGIN	
  	IF p_firstName IS NULL AND p_lastName IS NULL AND p_primaryEmail IS NULL
 	THEN
 		SELECT -1 AS errCode, 'Not all search criteria can be empty' AS errMsg;
         LEAVE SP;
 	END IF; 
     
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;      
  	SELECT 	C_C.coid		as id
   			,C_C.firstName
   			,C_C.lastName
   			,C_C.primaryPhoneNumber
   			,C_C.phoneNumber
   			,C_C.primaryEmail
   			,C_C.email
   			,C_C.accountNumber
   			,C_C.tags
   			,C_C.location
   			,C_C.address
   			,C_C.country
   			,C_C.state
   			,C_C.city
   			,C_C.postalCode
   			,C_C.facebook
   			,C_C.instagram
   			,C_C.whatsapp
   			,C_C.twitter
   			,C_C.createdAt
   			,C_C.updatedAt
   			,C_C.voiceBiometric			
   			,C_C.mergeCustomer			
   			,C_C.`type`
   			,C_C.currentCustomerNumber
   			,C_C.customerType
   			,C_C.Timezone
   			,C_C.blockedBy
   			,C_C.doNotDisturbBy
   			,C_C.blockedReqBy
   			,C_C.doNotDisturbReqBy
   			,C_C.Reason
   			,C_C.cookiesId
   			,C_C.`Source`
       FROM 	customer_contact	C_C		
       WHERE 	C_C.domainId		= p_domainId
       AND 		(	C_C.primaryEmail	LIKE p_primaryEmail
				OR 	C_C.firstName		LIKE p_firstName
				OR 	C_C.lastName		LIKE p_lastName);  
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
