CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getCustomerContactColumns`()
BEGIN
	DECLARE v_DB		VARCHAR(100);
    
    SET v_DB = database();
    
	SELECT 	COLUMN_NAME AS ColumnName 
    FROM 	information_schema.columns 
	WHERE 	table_name 		= 'customer_contact' 
    AND 	table_schema 	= v_DB
    AND 	`COLUMN_NAME` 	IN ('firstName','lastName','phoneNumber','email','accountNumber','tags','location','address','country','state','city','postalCode','facebook','instagram','whatsapp','twitter');
END ;;
DELIMITER ;
