DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCustomerContactDynamicColumn`(	 
  	 p_domainId				INT
  	,p_coid					INT
  	,p_DynamicColumns		VARCHAR(2000)
  	,p_FilterDate			DATETIME
  	,p_FilterDateOperator	VARCHAR(3)
 	,p_FilterValues		VARCHAR(1000)
  	,p_offset				INT
  	,p_Limit				INT
     )
BEGIN
    	 DECLARE v_DynamicColumns		VARCHAR(2000);            
 	 DECLARE v_coid					VARCHAR(10);	
    	 DECLARE v_FilterDateOperator	VARCHAR(3);
    	 DECLARE v_offset				INT;
    	 DECLARE v_Filter				VARCHAR(200);
  	 DECLARE v_DB					VARCHAR(50);
         
         SET v_offset = p_offset * p_Limit;
         
         SET v_coid = IFNULL(p_coid,'coid');    
    
    
    	IF p_DynamicColumns IS NOT NULL
        THEN
    		SET v_DynamicColumns = CONCAT('coid,',p_DynamicColumns);
    	ELSE
    		SET v_DB = database();
    		SELECT 	GROUP_CONCAT(COLUMN_NAME)
            INTO 	v_DynamicColumns
            FROM 	information_schema.columns 
            WHERE 	TABLE_NAME		= 'customer_contact'
            AND 	TABLE_SCHEMA	= v_DB
            AND 	COLUMN_NAME		<> 'domainId';
        END IF;
         
         IF p_FilterDate IS NOT NULL
         THEN
  			SET v_FilterDateOperator = 	CASE 	WHEN p_FilterDateOperator = 'EQ' THEN ' = ' 
  												WHEN p_FilterDateOperator = 'LT' THEN ' < ' 
  												WHEN p_FilterDateOperator = 'GT' THEN ' > ' 
  												WHEN p_FilterDateOperator = 'GTE' THEN ' >= ' 
  												WHEN p_FilterDateOperator = 'LTE' THEN ' <= ' 
  										END;    
  
  			SET v_Filter = CONCAT(" AND createdAt ", v_FilterDateOperator, "'",p_FilterDate,"'");        
  		ELSE
  			SET v_Filter = '';
  		END IF;
          
          IF p_FilterValues IS NOT NULL
          THEN
  			SET v_Filter = CONCAT(v_Filter," AND ", p_FilterValues); 
          END IF;
     
     	SET @Query = CONCAT("SELECT ", v_DynamicColumns," FROM customer_contact where domainId = ",p_domainId," and coid = ",v_coid,v_Filter," ORDER BY coid DESC LIMIT ",v_offset,",",p_Limit,";");
         
     	PREPARE stmt FROM @Query;
     	EXECUTE stmt; 
     	DEALLOCATE PREPARE stmt;    
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
