CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getCustomerFeedback`(
	p_customerFeedbackId		BIGINT, 	
	p_domainId					INT
)
BEGIN
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
     SELECT CF.customerFeedbackId
		,	CF.historyId
		,	CF.channelTypeId
		,	CF.satisfactionRate		
		,	CF.feedbackQuestionAnswer
     FROM 	tb_customerFeedback CF
     WHERE 	customerFeedbackId 	= p_customerFeedbackId
     AND	domainId			= p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
