DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getCustomerLatestMsg`(
  p_CustomerId	INT
  ,p_domainId	INT
  )
BEGIN
	DECLARE v_ChatDurationHistoryId		BIGINT;
    DECLARE v_ChatHistoryId				BIGINT;
	DECLARE v_AgentId					BIGINT;
	DECLARE v_IsBot						TINYINT;
	DECLARE v_Attendee					VARCHAR(255);
    DECLARE v_lastModifiedDate			DATETIME;
  
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    WITH cte_slno AS (
		SELECT 	ROW_NUMBER() OVER (ORDER BY ChatHistoryId DESC)	slNo, ChatHistoryId
		FROM 	tb_ChatHistory 	CH 	
		WHERE 	CustomerId 	= p_CustomerId
		AND 	domainId	= p_domainId
    )
    SELECT 	ChatHistoryId
    INTO 	v_ChatHistoryId 
    FROM 	cte_slno
    WHERE 	slNo = 2;
    
 	SELECT 	CDH.ChatDurationHistoryId, CDH.AgentId, CDH.IsBot
 	INTO 	v_ChatDurationHistoryId, v_AgentId, v_IsBot
 	FROM 	tb_ChatDurationHistory	CDH	
 	WHERE 	CDH.ChatHistoryId	= v_ChatHistoryId
 	ORDER BY CDH.ChatDurationHistoryId DESC LIMIT 1;
      
    IF v_IsBot = 0
	THEN
 		SET v_Attendee = 'Automatic';
 	ELSE
		SELECT 	UserName
		INTO	v_Attendee
		FROM 	tb_User        
		WHERE 	UserID 		= v_AgentId
		AND 	domainId	= p_domainId;
     END IF;
      
  	SELECT 	Message	 
 		,	v_Attendee 	AS Attendee
        ,	updatedAt	AS lastModifiedDate
  	FROM 	tb_ChatMessage     
  	WHERE 	ChatDurationHistoryId = v_ChatDurationHistoryId;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
