DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCustomHours`(p_domainId		INT
,p_cid			INT
,p_offset		SMALLINT
,p_limit		SMALLINT
)
BEGIN
	DECLARE v_offset		SMALLINT;
    
    SET v_offset = p_offset * p_limit;
    
	SELECT 	CH.cid
		,	CH.name
		,	CH.description
		,	CH.hours						
		,	CH.timeZone
		,	CH.default_hours
		,	CH.timeZoneValue
		,	CH.type
        ,   CH.createdAt
		,	CH.updatedAt
	FROM 	custom_hours CH
	WHERE 	CH.domainId = p_domainId 
    AND 	CH.cid		= IFNULL(p_cid,CH.cid)
	ORDER BY cid DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
