/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCustomReport`(
         	p_startTmpstmp 		BIGINT,
          	p_endTmpstmp 		BIGINT,
          	p_timeZone 			VARCHAR(200),
          	p_domainId 			INT,        
          	p_queueIds	 		VARCHAR(250),
  			p_agentIds 			VARCHAR(250),
          	p_Limit 			INT,
          	p_offset 			INT
   )
BEGIN
		  	DECLARE v_offset 		        INT;
 	        DECLARE v_Total_Count 	        INT;
 	        DECLARE v_startTmpstmp 	        BIGINT;
 	        DECLARE v_endTmpstmp 	        BIGINT;
               
 	SET v_offset = p_Limit * p_offset;  
 	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
 	IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
           
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
		  DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
		  CREATE TEMPORARY TABLE temp_AllqueueId
		  SELECT qid,name AS queueName FROM queue WHERE domainId = p_domainId;
            
          DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  		CREATE TEMPORARY TABLE temp_AllagentId          
  		SELECT UserID,UserName,ext,domainId,isActive FROM tb_User WHERE domainId = p_domainId; 

  	    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	    DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
 	    CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
 SELECT 	CH.sessionStartTime							AS SessionDate
 		,   'Call'           		                    AS `channelType`
 		,	AA.UserID						            AS agentId
 		,	AA.UserName						            AS agentName    
 		,	CH.customerNumber        		            AS customerNumber   
        ,   CH.callBack                                 AS callBack
        ,   CH.voicemailUrl                             AS voicemailStatus
        ,   CH.sessionStartTime					 		AS callstartTime  
        ,   CH.sessionEndTime 						    AS callAbandonTime
		,   CH.callDuration								
        ,   CH.IsInBound
        ,   CH.callDuration		                        AS TotalCallHandlingTime
        ,   CH.assignedBy                               AS Supervisorname
        ,	null					                    AS repliedOn
        ,   null                                        AS receivedOn  
        ,   null                                        AS responseTime
        ,   CH.queueDuration                            AS QueueWaitTime
        ,   CDH.StartTime                               AS agentconnecttime
        ,   CC.customerType                             AS customerType
        ,   CC.tags                                     AS customerTag
        ,   CC.location                                 
        ,   CC.email                                    AS customeremailId
 		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
        , CDH.transferedBy                              AS TransferredSkill
        , CDH.transferedTo                              AS TransferredAgent
        , CDH.afterCallWorkTime                         AS afterCallWorkTime
        , CDH.Duration			                      
        , CDH.StartTime			                     
        ,  null                                         AS chatEndTime
        , CDH.AgentHoldDuration			                AS agentHoldDuration  
	 	,	LSH.logInTimestamp		                    AS loginTime
	 	,	LSH.logOutTimestamp		                    AS logoutTime	
		,	AG.statusName			                    AS availableTime
        ,  AA.isActive                                  AS ChatStatus
 	FROM 	 tb_CallHistory 			    CH                         
 	JOIN     tb_CallDurationHistory			CDH     ON 	CH.CallHistoryId    = CDH.CallHistoryId     
 	JOIN    customer_contact                CC   	ON  CC.domainId 		= CH.domainId
 													AND CC.coid			    = CH.CustomerId
 	LEFT JOIN tb_User			         	AA		ON  AA.UserID 		    = CDH.agentId
 													AND AA.domainId         = CH.domainId   
 	LEFT JOIN logInSessionHistory	        LSH     ON  AA.ext			    = LSH.ext 
 											        AND LSH.domainId 	    = CH.domainId      
     LEFT JOIN agent_status				    AG	    ON  AG.aid			    = CDH.AgentId                                               
		  JOIN disposition_status            DD      ON  DD.did    = CDH.dispositionId           
 	WHERE 	CH.domainId 					= p_domainId 	
 	AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
 	AND 	(IFNULL(p_agentIds,'') 			= '' OR (IFNULL(p_agentIds,'') <> '' AND CDH.agentId IS NOT NULL));   
     select * from    tt_temp_sessionHistory;          
 	Insert into tt_temp_sessionHistory(SessionDate,`channelType`,AgentId,AgentName,Supervisorname,repliedOn,receivedOn,responseTime,duration,customerType,customerTag,location
    ,customeremailId,CustomerName,TransferredSkill,TransferredAgent,StartTime,chatEndTime,ChatStatus)  
 	SELECT 	CH.sessionStartTime                        as SessionDate
 		,   'Chat'           		                    AS `channelType`
		,	AA.UserID						            AS agentId
 		,	AA.UserName						            AS agentName    
        ,   CH.assignedBy                               AS Supervisorname
        ,	CH.repliedDate			                    AS repliedOn
		,	CH.createdAt			                    AS receivedOn
        ,	CH.repliedDate - CH.createdAt				AS responseTime
        ,	CDH.Duration			                    AS duration
        ,   CC.customerType                             AS customerType
        ,   CC.tags                                     AS customerTag
        ,   CC.location                                 
        ,   CC.email                                    AS customeremailId
 		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
        ,  CDH.transferedBy                             AS TransferredSkill
        ,  CDH.transferedTo                             AS TransferredAgent
        ,  CDH.StartTime			                    
        ,  CDH.EndTime				                    AS chatEndTime
        ,  AA.isActive                                  AS ChatStatus
 	FROM   	tb_ChatHistory 			CH                                  
 	JOIN 	tb_ChatDurationHistory	CDH	ON 	CH.ChatHistoryId   = CDH.ChatHistoryId  
 	JOIN 	customer_contact        CC   	ON  CC.domainId 		= CH.domainId
 											AND CC.coid			    = CH.CustomerId
 LEFT JOIN 	temp_AllagentId 		AA	    ON AA.UserID 		    = CDH.agentId 
 	WHERE 	CH.domainId 			= p_domainId		
 	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 	AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND CDH.agentId IS NOT NULL));     
      
       
      
 	INSERT INTO tt_temp_sessionHistory(SessionDate,`channelType`,AgentId,AgentName,Supervisorname,repliedOn,customerType,customerTag,location
    ,customeremailId,CustomerName,TransferredAgent,ChatStatus)
 	SELECT 	EH.sessionStartTime                         AS SessionDate
        ,   'Email'           		                    AS `channelType`
		,	AA.UserID						            AS agentId
 		,	AA.UserName						            AS agentName    
        ,   EH.assignedBy                               AS Supervisorname
         ,	EH.repliedDate			                    AS repliedOn       
        ,   CC.customerType                             AS customerType
        ,   CC.tags                                     AS customerTag
        ,   CC.location                                 
        ,   CC.email                                    AS customeremailId
 		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
        ,  EH.transferredTo                            AS TransferredAgent
        ,  AA.isActive                                  AS ChatStatus  
 	FROM   		
 	tb_EmailHistory 			    EH                
 	JOIN tb_EmailDurationHistory	EDH	            ON 	EH.EmailHistoryId   = EDH.EmailHistoryId 
 	JOIN    customer_contact         CC   	        ON  CC.domainId 		= EH.domainId
 													AND CC.coid			    = EH.CustomerId
 	LEFT JOIN temp_AllagentId 			AA	         ON AA.UserID 		    = EDH.AgentId         
 	WHERE 	EH.domainId 			= p_domainId 		
 	AND 	EH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
 	AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND EDH.agentId IS NOT NULL));             
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
    
 	SELECT * FROM temp_AllagentId;
 			   
 	SELECT 	COUNT(1) v_Total_Count
 	FROM 	tt_temp_sessionHistory a;	
         	SELECT 	a.SessionDate	 																				AS `dateTime`
   				 ,a.channelType 																					AS channelType
 				 ,a.agentName 																						AS agentName
 				 ,a.customerNumber																					AS customerNumber	
                 ,a.customerName 																					AS customerName
               
         	FROM 	tt_temp_sessionHistory a
         	LIMIT v_offset, p_limit;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetCustomReport1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCustomReport1`(
          	p_startTmpstmp 		BIGINT,
           	p_endTmpstmp 		BIGINT,
           	p_timeZone 			VARCHAR(200),
           	p_domainId 			INT,        
           	p_queueIds	 		VARCHAR(250),
   			p_agentIds 			VARCHAR(250),
           	p_Limit 			INT,
           	p_offset 			INT
    )
BEGIN
 		  	DECLARE v_offset 		        INT;
  	        DECLARE v_Total_Count 	        INT;
  	        DECLARE v_startTmpstmp 	        BIGINT;
  	        DECLARE v_endTmpstmp 	        BIGINT;
                
  	SET v_offset = p_Limit * p_offset;  
  	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
  	IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
  
  			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	CREATE TEMPORARY TABLE temp_AllagentId(agentId BIGINT);
      		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	CREATE TEMPORARY TABLE temp_AllqueueId(queueId VARCHAR(100));
      
      		CALL split(p_agentIDs,',');	INSERT INTO temp_AllagentId(agentId) SELECT Items FROM tt_Split_temptable;
      		CALL split(p_queueIds,','); INSERT INTO temp_AllqueueId(queueId) SELECT Items FROM tt_Split_temptable;

           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
 		  DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
 		  CREATE TEMPORARY TABLE temp_AllqueueId
 		  SELECT qid,name AS queueName FROM queue WHERE domainId = p_domainId;
             
           DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   		  CREATE TEMPORARY TABLE temp_AllagentId          
   		  SELECT UserID,UserName,ext,domainId,isActive FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3); 
 
   	    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	    DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
  	    CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
  	    SELECT 	CH.sessionStartTime							AS SessionDate
         ,CH.sessionEndTime
  		,   'Call'           		                    AS `channelType`
  		,	AA.UserID						            AS agentId
  		,	AA.UserName						            AS agentName    
  		,	 CH.customerNumber        		            AS customerNumber   
         ,   CH.callBack                                 AS callBack
         ,   CH.voicemailUrl                             AS voicemailStatus
         
         ,   CH.sessionEndTime 						    AS callAbandonTime
 		,    CH.callDuration								
         ,   CH.IsInBound
         ,   CH.callDuration		                        AS TotalCallHandlingTime
         ,   CH.assignedBy                               AS Supervisorname
         ,   CH.businessEndTime
         ,   CH.businessStartTime 
         ,   CH.dialDuration
         ,	NULL					                     AS repliedOn
         ,   NULL                                        AS receivedOn  
         ,   NULL                                        AS responseTime
         ,   CH.queueDuration                            AS QueueWaitTime
 	    ,   NULL                                         AS assignedTo
         ,   CDH.StartTime                               AS agentconnecttime
         ,   CC.customerType                             AS customerType
         ,   CC.tags                                     AS customerTag
         ,   CC.location                                 
         ,   CC.email                                    AS customeremailId
  		,	CONCAT(CC.firstName,' ',CC.lastName)         AS CustomerName 
         , CDH.transferedBy                              AS TransferredSkill
         , CDH.transferedTo                              AS TransferredAgent
         , CDH.afterCallWorkTime                         AS afterCallWorkTime
         , CDH.Duration			                      
         
	     ,CDH.StartTime                                  AS callStartTime
         ,CDH.EndTime                                    AS callEndTime         
         , CDH.UMNStatus
         ,  null                                           AS EndTime
         ,  null                                           AS chatDuration
         ,  null                                           AS ACW
         ,  null                                           AS DispositionCategory    
         ,  null                                           AS StartTime	
         , CDH.AgentHoldDuration			                AS agentHoldDuration
		 , CDH.IsMissedCall 
         , CH.voiceMailDuration                      
         , CH.IsAbandoned
         , CDH.transferredTime
 		 , LSH.logInTimestamp		                    AS loginTime
 		 , LSH.logOutTimestamp		                    AS logoutTime	
 		
 		,  null                                         AS availableTime       
         ,  AA.isActive                                  AS ChatStatus
         , Q.queueName
         ,DD.dispositionName
         ,S.skill_name
         ,AA.ext
  	FROM 	 tb_CallHistory 			    CH                         
  	JOIN     tb_CallDurationHistory			CDH     ON 	CH.CallHistoryId    = CDH.CallHistoryId     
  	JOIN    customer_contact                CC   	ON  CC.domainId 		= CH.domainId
  													AND CC.coid			    = CH.CustomerId
     JOIN 	temp_AllqueueId					Q		ON CDH.QueueId		= Q.qid                                                 
  	LEFT JOIN temp_AllagentId				AA		ON  AA.UserID 		    = CDH.agentId
  													AND AA.domainId         = CH.domainId   
 	LEFT JOIN logInSessionHistory	        LSH     ON  AA.ext			    = LSH.ext 
  											        AND LSH.domainId 	    = CH.domainId      
      LEFT JOIN agent_status				    AG	    ON  AG.aid			    = CDH.AgentId                                                   
 		 JOIN disposition_status            DD      ON  DD.did    = CDH.dispositionId
          JOIN skills                        S       ON S.domainId           = CH.domainId
  	WHERE 	CH.domainId 					= p_domainId 	
  	AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') 			= '' OR (IFNULL(p_agentIds,'') <> '' AND CDH.agentId IS NOT NULL));   
             
  	Insert into tt_temp_sessionHistory(SessionDate,`channelType`,AgentId,AgentName,Supervisorname,repliedOn,receivedOn,responseTime,chatDuration,customerType,customerTag,location
     ,customeremailId,CustomerName,TransferredSkill,TransferredAgent,StartTime,EndTime,ACW,ChatStatus,queueName,dispositionName,skill_name,availableTime,DispositionCategory)  
  	SELECT 	CH.sessionStartTime                        as SessionDate
  		,   'Chat'           		                    AS `channelType`
 		,	AA.UserID						            AS agentId
  		,	AA.UserName						            AS agentName    
         ,   CH.assignedBy                               AS Supervisorname
         ,	CH.repliedDate			                    AS repliedOn
 		,	CH.createdAt			                    AS receivedOn
         ,	CH.repliedDate - CH.createdAt				AS responseTime
         ,	CDH.Duration			                    AS chatDuration
         ,   CC.customerType                             AS customerType
         ,   CC.tags                                     AS customerTag
         ,   CC.location                                 
         ,   CC.email                                    AS customeremailId
  		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
         ,  CDH.transferedBy                             AS TransferredSkill
         ,  CDH.transferedTo                             AS TransferredAgent
         ,  CDH.StartTime			                    
         ,  CDH.EndTime				                    AS EndTime
         ,  CDH.afterChatWorkTime                        AS ACW
         ,  AA.isActive                                  AS ChatStatus 
 		,   Q.queueName
         ,  DD.dispositionName
         , S.skill_name
 		,  AG.statusName			                    AS availableTime   
                ,CASE WHEN DD.dispositionName = 'Opened'	THEN 2
 				WHEN DD.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
 				WHEN DD.dispositionName = 'Discarded' THEN 4
 				END 		as 	DispositionCategory
  	FROM   	tb_ChatHistory 			CH                           
  	JOIN 	tb_ChatDurationHistory	CDH	    ON 	CH.ChatHistoryId    = CDH.ChatHistoryId    
  	JOIN 	customer_contact        CC   	ON  CC.domainId 		= CH.domainId
  											AND CC.coid			    = CH.CustomerId
  LEFT JOIN 	temp_AllagentId 		AA	    ON AA.UserID 		    = CDH.agentId 
       JOIN 	temp_AllqueueId			Q	     ON CDH.QueueId		    = Q.qid
  	  JOIN disposition_status        DD      ON  DD.did              = CDH.dispositionId  
       LEFT JOIN agent_status		 AG	     ON  AG.aid			    = CDH.AgentId
       JOIN skills                    S       ON S.domainId           = CH.domainId
  	WHERE 	CH.domainId 			= p_domainId		
  	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND CDH.agentId IS NOT NULL));     
       
        
       
  	INSERT INTO tt_temp_sessionHistory(SessionDate,`channelType`,AgentId,AgentName,Supervisorname,repliedOn,customerType,customerTag,location
     ,customeremailId,CustomerName,TransferredAgent,ChatStatus,queueName,dispositionName,skill_name,assignedTo)
  	SELECT 	EH.sessionStartTime                         AS SessionDate
         ,   'Email'           		                    AS `channelType`
 		,	AA.UserID						            AS agentId
  		,	AA.UserName						            AS agentName    
         ,   EH.assignedBy                               AS Supervisorname
         ,   EH.assignedTo                                                                                    
          ,	EH.repliedDate			                    AS repliedOn     
          ,  EH.transferredTo                            AS TransferredAgent        
         ,   CC.customerType                             AS customerType
         ,   CC.tags                                     AS customerTag
         ,   CC.location                                 
         ,   CC.email                                    AS customeremailId
  		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
         ,  AA.isActive                                  AS ChatStatus  
 		,   Q.queueName
         ,   DD.dispositionName
         ,   S.skill_name
  	FROM   		
  	tb_EmailHistory 			    EH             
  	JOIN tb_EmailDurationHistory	EDH	            ON 	EH.EmailHistoryId   = EDH.EmailHistoryId 
  	JOIN    customer_contact         CC   	        ON  CC.domainId 		= EH.domainId
  													AND CC.coid			    = EH.CustomerId
 	JOIN 	temp_AllqueueId			 Q		        ON EDH.QueueId		    = Q.qid
  	LEFT JOIN temp_AllagentId 	    AA	            ON AA.UserID 		    = EDH.AgentId   
          JOIN disposition_status    DD              ON  DD.did              = EH.dispositionId  
          JOIN skills                S               ON S.domainId           = EH.domainId
  	WHERE 	EH.domainId 			= p_domainId 		
  	AND 	EH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND EDH.agentId IS NOT NULL));             
             
   		DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
 		CREATE TEMPORARY TABLE tt_sessionHistory_calc AS   
         select 
                   a.SessionDate	 												      
  				 
                  ,a.agentId
  				 ,a.customerNumber													  	
                  ,a.customerName 													  
                  , a.QueueName
                  ,a.dispositionName                                                   
                  ,a.ChatStatus                                                             
                  ,a.callBack                                                          
                  ,a.voicemailStatus
 				 ,a.TransferredAgent
                  ,a.channelType
                  ,a.Supervisorname
                  ,a.customeremailId
                  ,a.location
                  ,a.customerTag
                  ,a.skill_name
                  ,a.StartTime                                                        AS chatStartTime
                  ,a.EndTime                                                          AS  chatEndTime
                  ,a.repliedOn - a.receivedOn	                                      AS responseTime
                  ,a.QueueWaitTime
 				 ,a.callstartTime
                  ,a.callAbandonTime
                  ,a.assignedTo
                  ,a.Duration                                                            AS HandleTime  
 				 ,a.loginTime                                                            AS AgentLoginTime 
                  ,a.logoutTime                                                          AS AgentLogoutTime
                  ,a.sessionEndTime                                                      AS callEndTime
 				 ,a.businessEndTime-a.businessStartTime                                  AS TotalTime 
                  ,a.AgentHoldDuration*100 					                             AS averageholdtime
                  ,abs((a.EndTime-a.StartTime)/1000)	                                 AS activeChatTime
                  ,sum((a.EndTime-a.StartTime)/1000)	                                 AS totalActiveChatTime
 			     ,avg((a.EndTime-a.StartTime)/1000)	                                     AS AverageActiveChattime
                  ,avg(a.repliedOn - a.receivedOn)                                       AS AverageReplytimeformessage
                  ,avg(QueueWaitTime)                                                    AS AverageQueueWaitTime
                  ,max(QueueWaitTime)                                                    AS maxiumQueueWaitTime
                  ,avg(a.repliedOn - a.receivedOn)                                       AS averageResponseTime
                  ,sum(a.callDuration/1000)	                                             AS totalInteractionTime
                  ,sum(loginTime)                                                        AS totalLoggedinTime
              
                  ,avg(a.callDuration)                                                   AS AverageTalktime
                  ,avg(a.Duration)                                                       AS AverageHandleTime
 				
                ,sum(a.callDuration)                                                                AS totalTalktime
 				,SUM(CASE WHEN a.agentHoldDuration > 0 THEN a.agentHoldDuration ELSE 0 END)         AS AgentHoldDuration		        
                 ,sum(a.Duration)                                                                   AS Totalhandlingtime
 				,sum(CASE WHEN a.IsInBound=0 THEN a.Duration ELSE 0 END) 				            AS OutboundCall
                 ,avg(CASE WHEN a.IsInBound=0 THEN a.Duration ELSE 0 END) 				            AS averageOutboundCall   
                 ,	SUM(a.ACW)/COUNT(1)				                                                AS averageACW 
                 ,max(chatDuration)                                                                 AS maxChatDuration
                 ,min(chatDuration)                                                                 AS minChatDuration
                  ,sum(CASE WHEN a.callBack=1 THEN 1 ELSE 0 END)                                    AS NoOfCallbackReceived
                  ,sum(CASE WHEN a.callBack=1 THEN 1 ELSE 0 END)                                    AS NoOfCallbackReturned
                  ,sum(CASE WHEN a.callBack=2 THEN 1 ELSE 0 END)                                    AS NoofCallbackAnswered
                  ,sum(case when a.callBack=1 THEN 1 ELSE 0 END)                                    AS NoofCallbackNotAnswered 
                  ,sum(case when a.dispositionName='Resolved' THEN 1 ELSE 0 END)                    AS NoofResolvedCalls
                  ,sum(case when a.UMNStatus =4 THEN 1 ELSE 0 END)                                  AS NoofDiscardedDeclinedinteraction 
                  ,sum(case when a.callBack =2 and a.UMNStatus in (3,4,5) then 1 else 0 end)        AS NoofFailedOutbound
                 
                  ,SUM(CASE WHEN a.IsInBound = 1 AND a.agentconnecttime > 0  THEN 1 ELSE 0 END) 	   AS answeredCall
                  ,SUM(CASE WHEN a.IsInBound = 0  THEN 1 ELSE 0 END) 	                               AS unansweredCall
                  ,sum(case when a.IsInBound =1 THEN 1 ELSE 0 END)                                     AS IncomingChats
                  ,sum(case when a.IsInBound =1 THEN 1 ELSE 0 END)                                     AS receivedCall
				  , SUM(CASE WHEN a.DispositionCategory = 3 THEN 1 ELSE 0 END )		                   AS totalHandled
                  ,SUM(CASE WHEN a.IsMissedCall =1  THEN 1 ELSE 0 END)                                 AS totalMissed
                  ,SUM(CASE WHEN a.transferredTime  IS not NULL THEN 1 ELSE 0 END)                     AS totalTransferred
                  ,SUM(a.EndTime-a.StartTime)	                                                       AS totalChats
                  ,sum(a.voiceMailDuration)                                                            AS totalLengthOfVoicemail
                  ,sum(a.callEndTime-a.callStartTime)                                                  AS totalCall
                  ,sum(case when a.IsAbandoned =1 THEN 1 ELSE 0 END)                                   AS totalAbandoned
                  ,SUM(CASE WHEN a.dialDuration BETWEEN 1 AND 30000 AND a.dialDuration IS NOT NULL THEN 1 ELSE 0 END) AS thresholdTime
                  ,count(1)                                                                            AS queriesReceived
                  from tt_temp_sessionHistory a
                  group by  a.agentHoldDuration,a.loginTime,a.Duration,a.callAbandonTime,a.QueueWaitTime,a.repliedOn,a.receivedOn,a.EndTime,a.StartTime,a.SessionDate,a.agentName,a.customerNumber,a.customerName,a.QueueName,a.dispositionName,a.ChatStatus,a.callBack,a.voicemailStatus,a.TransferredAgent,a.channelType,
                  a.Supervisorname,a.customeremailId,a.location,a.customerTag,a.skill_name,a.logoutTime,a.sessionEndTime,a.callstartTime,
                  a.businessEndTime,a.businessStartTime,a.assignedTo,a.agentId;
   
    	SELECT * FROM temp_AllagentId;
  			   
  	SELECT 	COUNT(1) v_Total_Count
  	FROM 	tt_temp_sessionHistory a;	
     
               ALTER TABLE tt_sessionHistory_calc ADD COLUMN availableTime		INT;
               ALTER TABLE tt_sessionHistory_calc ADD COLUMN unavailableTime		INT;
 			  ALTER TABLE tt_sessionHistory_calc ADD COLUMN agentName			VARCHAR(150);
              UPDATE 	tt_sessionHistory_calc	SH_C
              JOIN 	temp_AllagentId			t_A		ON 	SH_C.agentId = t_A.UserID        
              SET 	agentName		= t_A.UserName 
      			,	availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.state ='Ready' THEN S.stateDuration ELSE 0 END) 
      									FROM 	state_timer S	
                                          WHERE  	S.domainId	= p_domainId
                                          AND 	S.ext			= t_A.ext
                                          AND 	S.`timestamp`	BETWEEN v_startTmpstmp and v_endTmpstmp )
                ,	unavailableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.state ='Busy' THEN S.stateDuration ELSE 0 END) 
      									FROM 	state_timer S	
                                          WHERE  	S.domainId	= p_domainId
                                          AND 	S.ext			= t_A.ext
                                          AND 	S.`timestamp`	BETWEEN v_startTmpstmp and v_endTmpstmp );                      
   
          	SELECT 	a.SessionDate	 												  AS `dateTime`
  				  ,a.agentName 														  AS agentName
  				  ,a.customerNumber													  AS customerNumber	
                  ,a.customerName 													  AS customerName
                  , a.QueueName                                                        AS queueName
                  ,a.dispositionName                                                   AS dispositionStatus
                  ,a.ChatStatus                                                        AS chatStatus
                  ,null                                                                AS skillName
                  ,a.callBack                                                          AS callbackStatus
                  ,a.voicemailStatus                                                   AS voiceMailStatus
 				  ,a.TransferredAgent                                                  AS transferredAgent
                  ,a.channelType
                  ,a.Supervisorname                                                    AS supervisorName
                  ,a.customeremailId                                                   AS customerEmailId
                  ,a.location                                                        
                  ,a.customerTag                                                       AS customerTag
                  ,a.HandleTime  	                                                   AS handleTime
                  ,a.AgentLoginTime                                                    AS agentLoginTime	
 			      ,a.AgentLogoutTime	                                               AS agentLogoutTime
                  ,a.callEndTime	
                  ,a.TotalTime 	                                                          AS totalTime
                  ,a.averageholdtime	                                                  AS averageHoldTime
                  ,a.activeChatTime	                                                      AS activeChatTime
                  ,a.totalActiveChatTime	                                              AS totalActiveChatTime
 				 ,a.AverageActiveChattime	                                              AS averageActiveChattime
                  ,a.AverageReplytimeformessage	                                          AS averageReplyTimeForMessage
                  ,a.AverageQueueWaitTime                                                 AS averageQueueWaitTime	
 				 ,a.maxiumQueueWaitTime	
                  ,a.averageResponseTime	
                  ,a.totalInteractionTime	
                  ,a.totalLoggedinTime	
                  ,a.totalTalktime	
                  ,a.AverageTalktime	                                              AS averageTalktime
                  ,a.AverageHandleTime	                                              AS averageHandleTime	
                  ,a.AgentHoldDuration	                                              AS agentHoldDuration
 				  ,a.Totalhandlingtime	                                              AS totalHandlingTime
                  ,a.availableTime
                  ,a.unavailableTime
 				  ,a.OutboundCall	                                                  AS outboundCall
                  ,a.averageOutboundCall                                               AS averageOutboundCall	
                  ,a.averageACW 	
 				  ,a.maxChatDuration	
                  ,count(a.OutboundCall)                                                AS noofOutboundCallAttempted
                  ,count(answeredCall)                                                  AS noofAnswered
                  ,count(answeredCall)                                                  AS noofunAnswered
                  ,count(a.assignedTo)                                                  AS NoofAssignedEmail
                  ,count(a.IncomingChats)                                               AS totalIncomingChats                                         
                  ,a.totalHandled    
                  ,a.totalMissed
                  ,COUNT(1)							                                    AS totalReceived                        
                  ,a.totalTransferred
                  ,COUNT(1)						                                        AS totalInteraction
                  ,a.totalChats
                  ,a.totalLengthOfVoicemail
                  ,a.totalCall
                  ,a.totalAbandoned
                  ,(a.totalAbandoned/a.receivedCall)*100	                            AS abandon
                  ,(a.totalTransferred/a.receivedCall)*100                              AS transfer
                  ,(a.NoOfCallbackReturned/a.receivedCall)*100                          AS PercentageofCallbackReturned
                  ,(a.NoofCallbackAnswered/a.receivedCall)*100                          AS PercentageofCallbackAnswered
                  ,(a.NoofCallbackNotAnswered /a.receivedCall)*100                      AS PercentageofCallbackNotAnswered
                  ,(a.answeredCall/a.receivedCall)*100                                  AS PercentageofAnswered
                  ,(a.totalMissed/a.receivedCall)*100                                   AS PercentageofMissed
                  ,(a.thresholdTime/a.queriesReceived)*100				             	AS serviceLevel
                  ,(a.totalTalktime/a.availableTime)*100							    AS occupancyrate
                  ,(a.totalTalktime/a.TotalTime)*100                                    AS agentUtilization
          	FROM 	tt_sessionHistory_calc a
             GROUP BY 
 		    a.SessionDate	  
            ,a.agentName 		 
            ,a.customerNumber	 
 		   ,a.customerName 	 
 		   ,a.QueueName        
            ,a.dispositionName   
            ,a.ChatStatus        
            ,null                
            ,a.callBack          
            ,a.voicemailStatus   
 		   ,a.TransferredAgent 
            ,a.channelType      
            ,a.Supervisorname                  
            ,a.customeremailId                 
            ,a.location                        
            ,a.customerTag                     
            ,a.HandleTime  	                
            ,a.AgentLoginTime                  
            ,a.AgentLogoutTime	                
            ,a.callEndTime	      
         ,a.TotalTime 	                    
         ,a.averageholdtime	                
         ,a.activeChatTime	                
         ,a.totalActiveChatTime	            
         ,a.AverageActiveChattime	        
         ,a.AverageReplytimeformessage      
         ,a.AverageQueueWaitTime            
         ,a.maxiumQueueWaitTime	
         ,a.averageResponseTime	
         ,a.totalInteractionTime	
         ,a.totalLoggedinTime	
         ,a.totalTalktime	
         ,a.AverageTalktime	          
         ,a.AverageHandleTime	
         ,a.AgentHoldDuration	
         ,a.Totalhandlingtime
 		 ,a.availableTime
 		 ,a.unavailableTime
         ,a.OutboundCall	    
         ,a.averageOutboundCall 
 		 ,a.averageACW 	
 		 ,a.maxChatDuration	
         ,a.totalHandled
         ,a.totalMissed
         ,a.totalTransferred
         ,a.totalChats
         ,a.totalLengthOfVoicemail
         ,a.totalCall
         ,a.totalAbandoned
         ,a.receivedCall
         ,a.NoOfCallbackReturned
         ,a.NoofCallbackAnswered
         ,a.NoofCallbackNotAnswered
         ,a.NoofCallbackNotAnswered
         ,a.answeredCall
         ,a.thresholdTime
         ,a.queriesReceived
 	 LIMIT v_offset, p_limit;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetCustomReport2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetCustomReport2`(
          	p_startTmpstmp 		BIGINT,
           	p_endTmpstmp 		BIGINT,
           	p_timeZone 			VARCHAR(200),
           	p_domainId 			INT,        
           	p_queueIds	 		VARCHAR(250),
   			p_agentIds 			VARCHAR(250),
           	p_Limit 			INT,
           	p_offset 			INT
    )
BEGIN
 		  	DECLARE v_offset 		        INT;
  	        DECLARE v_Total_Count 	        INT;
  	        DECLARE v_startTmpstmp 	        BIGINT;
  	        DECLARE v_endTmpstmp 	        BIGINT;
                
  	SET v_offset = p_Limit * p_offset;  
  	IF IFNULL(p_startTmpstmp,0)	= 0 THEN SET v_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp;  END IF; 	
  	IF IFNULL(p_endTmpstmp,0)=0 	THEN SET v_endTmpstmp 	= unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF; 
  
  			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	CREATE TEMPORARY TABLE temp_AllagentId(agentId BIGINT);
      		DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	CREATE TEMPORARY TABLE temp_AllqueueId(queueId VARCHAR(100));
      
      		CALL split(p_agentIDs,',');	INSERT INTO temp_AllagentId(agentId) SELECT Items FROM tt_Split_temptable;
      		CALL split(p_queueIds,','); INSERT INTO temp_AllqueueId(queueId) SELECT Items FROM tt_Split_temptable;

           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
 		  DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
 		  CREATE TEMPORARY TABLE temp_AllqueueId
 		  SELECT qid,name AS queueName FROM queue WHERE domainId = p_domainId;
             
           DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
   		  CREATE TEMPORARY TABLE temp_AllagentId          
   		  SELECT UserID,UserName,ext,domainId,isActive FROM tb_User WHERE domainId = p_domainId AND roleid NOT IN (3); 
 
   	    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	    DROP TEMPORARY TABLE IF EXISTS tt_temp_sessionHistory; 
  	    CREATE TEMPORARY TABLE tt_temp_sessionHistory  AS
  	    SELECT 	CH.sessionStartTime							AS SessionDate
         ,CH.sessionEndTime
  		,   'Call'           		                    AS `channelType`
  		,	AA.UserID						            AS agentId
  		,	AA.UserName						            AS agentName    
  		,	 CH.customerNumber        		            AS customerNumber   
         ,   CH.callBack                                 AS callBack
         ,   CH.voicemailUrl                             AS voicemailStatus
         
         ,   CH.sessionEndTime 						    AS callAbandonTime
 		,    CH.callDuration								
         ,   CH.IsInBound
         ,   CH.callDuration		                        AS TotalCallHandlingTime
         ,   CH.assignedBy                               AS Supervisorname
         ,   CH.businessEndTime
         ,   CH.businessStartTime 
         ,   CH.dialDuration
         ,	NULL					                     AS repliedOn
         ,   NULL                                        AS receivedOn  
         ,   NULL                                        AS responseTime
         ,   CH.queueDuration                            AS QueueWaitTime
 	    ,   NULL                                         AS assignedTo
         ,   CDH.StartTime                               AS agentconnecttime
         ,   CC.customerType                             AS customerType
         ,   CC.tags                                     AS customerTag
         ,   CC.location                                 
         ,   CC.email                                    AS customeremailId
  		,	CONCAT(CC.firstName,' ',CC.lastName)         AS CustomerName 
         , CDH.transferedBy                              AS TransferredSkill
         , CDH.transferedTo                              AS TransferredAgent
         , CDH.afterCallWorkTime                         AS afterCallWorkTime
         , CDH.Duration			                      
         
	     ,CDH.StartTime                                  AS callStartTime
         ,CDH.EndTime                                    AS callEndTime         
         , CDH.UMNStatus
         ,  null                                           AS EndTime
         ,  null                                           AS chatDuration
         ,  null                                           AS ACW
         ,  null                                           AS DispositionCategory    
         ,  null                                           AS StartTime	
         , CDH.AgentHoldDuration			                AS agentHoldDuration
		 , CDH.IsMissedCall 
         , CH.voiceMailDuration                      
         , CH.IsAbandoned
         , CDH.transferredTime
 		 , LSH.logInTimestamp		                    AS loginTime
 		 , LSH.logOutTimestamp		                    AS logoutTime	
 		
 		,  null                                         AS availableTime       
         ,  AA.isActive                                  AS ChatStatus
         , Q.queueName
         ,DD.dispositionName
         ,S.skill_name
         ,AA.ext
  	FROM 	 tb_CallHistory 			    CH                         
  	JOIN     tb_CallDurationHistory			CDH     ON 	CH.CallHistoryId    = CDH.CallHistoryId     
  	JOIN    customer_contact                CC   	ON  CC.domainId 		= CH.domainId
  													AND CC.coid			    = CH.CustomerId
     JOIN 	temp_AllqueueId					Q		ON CDH.QueueId		= Q.qid                                                 
  	LEFT JOIN temp_AllagentId				AA		ON  AA.UserID 		    = CDH.agentId
  													AND AA.domainId         = CH.domainId   
 	LEFT JOIN logInSessionHistory	        LSH     ON  AA.ext			    = LSH.ext 
  											        AND LSH.domainId 	    = CH.domainId      
      LEFT JOIN agent_status				    AG	    ON  AG.aid			    = CDH.AgentId                                                   
 		 JOIN disposition_status            DD      ON  DD.did    = CDH.dispositionId
          JOIN skills                        S       ON S.domainId           = CH.domainId
  	WHERE 	CH.domainId 					= p_domainId 	
  	AND 	CH.sessionStartTime 			BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') 			= '' OR (IFNULL(p_agentIds,'') <> '' AND CDH.agentId IS NOT NULL));   
             
  	Insert into tt_temp_sessionHistory(SessionDate,`channelType`,AgentId,AgentName,Supervisorname,repliedOn,receivedOn,responseTime,chatDuration,customerType,customerTag,location
     ,customeremailId,CustomerName,TransferredSkill,TransferredAgent,StartTime,EndTime,ACW,ChatStatus,queueName,dispositionName,skill_name,availableTime,DispositionCategory)  
  	SELECT 	CH.sessionStartTime                        as SessionDate
  		,   'Chat'           		                    AS `channelType`
 		,	AA.UserID						            AS agentId
  		,	AA.UserName						            AS agentName    
         ,   CH.assignedBy                               AS Supervisorname
         ,	CH.repliedDate			                    AS repliedOn
 		,	CH.createdAt			                    AS receivedOn
         ,	CH.repliedDate - CH.createdAt				AS responseTime
         ,	CDH.Duration			                    AS chatDuration
         ,   CC.customerType                             AS customerType
         ,   CC.tags                                     AS customerTag
         ,   CC.location                                 
         ,   CC.email                                    AS customeremailId
  		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
         ,  CDH.transferedBy                             AS TransferredSkill
         ,  CDH.transferedTo                             AS TransferredAgent
         ,  CDH.StartTime			                    
         ,  CDH.EndTime				                    AS EndTime
         ,  CDH.afterChatWorkTime                        AS ACW
         ,  AA.isActive                                  AS ChatStatus 
 		,   Q.queueName
         ,  DD.dispositionName
         , S.skill_name
 		,  AG.statusName			                    AS availableTime   
                ,CASE WHEN DD.dispositionName = 'Opened'	THEN 2
 				WHEN DD.dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
 				WHEN DD.dispositionName = 'Discarded' THEN 4
 				END 		as 	DispositionCategory
  	FROM   	tb_ChatHistory 			CH                           
  	JOIN 	tb_ChatDurationHistory	CDH	    ON 	CH.ChatHistoryId    = CDH.ChatHistoryId    
  	JOIN 	customer_contact        CC   	ON  CC.domainId 		= CH.domainId
  											AND CC.coid			    = CH.CustomerId
  LEFT JOIN 	temp_AllagentId 		AA	    ON AA.UserID 		    = CDH.agentId 
       JOIN 	temp_AllqueueId			Q	     ON CDH.QueueId		    = Q.qid
  	  JOIN disposition_status        DD      ON  DD.did              = CDH.dispositionId  
       LEFT JOIN agent_status		 AG	     ON  AG.aid			    = CDH.AgentId
       JOIN skills                    S       ON S.domainId           = CH.domainId
  	WHERE 	CH.domainId 			= p_domainId		
  	AND 	CH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND CDH.agentId IS NOT NULL));     
       
        
       
  	INSERT INTO tt_temp_sessionHistory(SessionDate,`channelType`,AgentId,AgentName,Supervisorname,repliedOn,customerType,customerTag,location
     ,customeremailId,CustomerName,TransferredAgent,ChatStatus,queueName,dispositionName,skill_name,assignedTo)
  	SELECT 	EH.sessionStartTime                         AS SessionDate
         ,   'Email'           		                    AS `channelType`
 		,	AA.UserID						            AS agentId
  		,	AA.UserName						            AS agentName    
         ,   EH.assignedBy                               AS Supervisorname
         ,   EH.assignedTo                                                                                    
          ,	EH.repliedDate			                    AS repliedOn     
          ,  EH.transferredTo                            AS TransferredAgent        
         ,   CC.customerType                             AS customerType
         ,   CC.tags                                     AS customerTag
         ,   CC.location                                 
         ,   CC.email                                    AS customeremailId
  		,	CONCAT(CC.firstName,' ',CC.lastName)        AS CustomerName 
         ,  AA.isActive                                  AS ChatStatus  
 		,   Q.queueName
         ,   DD.dispositionName
         ,   S.skill_name
  	FROM   		
  	tb_EmailHistory 			    EH             
  	JOIN tb_EmailDurationHistory	EDH	            ON 	EH.EmailHistoryId   = EDH.EmailHistoryId 
  	JOIN    customer_contact         CC   	        ON  CC.domainId 		= EH.domainId
  													AND CC.coid			    = EH.CustomerId
 	JOIN 	temp_AllqueueId			 Q		        ON EDH.QueueId		    = Q.qid
  	LEFT JOIN temp_AllagentId 	    AA	            ON AA.UserID 		    = EDH.AgentId   
          JOIN disposition_status    DD              ON  DD.did              = EH.dispositionId  
          JOIN skills                S               ON S.domainId           = EH.domainId
  	WHERE 	EH.domainId 			= p_domainId 		
  	AND 	EH.sessionStartTime 	BETWEEN v_startTmpstmp and v_endTmpstmp 
  	AND 	(IFNULL(p_agentIds,'') 	= '' OR (IFNULL(p_agentIds,'') <> '' AND EDH.agentId IS NOT NULL));             
             
   		DROP TEMPORARY TABLE IF EXISTS tt_sessionHistory_calc; 
 		CREATE TEMPORARY TABLE tt_sessionHistory_calc AS   
         select 
                   a.SessionDate	 												      
  				 
                  ,a.agentId
  				 ,a.customerNumber													  	
                  ,a.customerName 													  
                  , a.QueueName
                  ,a.dispositionName                                                   
                  ,a.ChatStatus                                                             
                  ,a.callBack                                                          
                  ,a.voicemailStatus
 				 ,a.TransferredAgent
                  ,a.channelType
                  ,a.Supervisorname
                  ,a.customeremailId
                  ,a.location
                  ,a.customerTag
                  ,a.skill_name
                  ,a.StartTime                                                        AS chatStartTime
                  ,a.EndTime                                                          AS  chatEndTime
                  ,a.repliedOn - a.receivedOn	                                      AS responseTime
                  ,a.QueueWaitTime
 				 ,a.callstartTime
                  ,a.callAbandonTime
                  ,a.assignedTo
                  ,a.Duration                                                            AS HandleTime  
 				 ,a.loginTime                                                            AS AgentLoginTime 
                  ,a.logoutTime                                                          AS AgentLogoutTime
                  ,a.sessionEndTime                                                      AS callEndTime
 				 ,a.businessEndTime-a.businessStartTime                                  AS TotalTime 
                  ,a.AgentHoldDuration*100 					                             AS averageholdtime
                  ,abs((a.EndTime-a.StartTime)/1000)	                                 AS activeChatTime
                  ,sum((a.EndTime-a.StartTime)/1000)	                                 AS totalActiveChatTime
 			     ,avg((a.EndTime-a.StartTime)/1000)	                                     AS AverageActiveChattime
                  ,avg(a.repliedOn - a.receivedOn)                                       AS AverageReplytimeformessage
                  ,avg(QueueWaitTime)                                                    AS AverageQueueWaitTime
                  ,max(QueueWaitTime)                                                    AS maxiumQueueWaitTime
                  ,avg(a.repliedOn - a.receivedOn)                                       AS averageResponseTime
                  ,sum(a.callDuration/1000)	                                             AS totalInteractionTime
                  ,sum(loginTime)                                                        AS totalLoggedinTime
              
                  ,avg(a.callDuration)                                                   AS AverageTalktime
                  ,avg(a.Duration)                                                       AS AverageHandleTime
 				
                ,sum(a.callDuration)                                                                AS totalTalktime
 				,SUM(CASE WHEN a.agentHoldDuration > 0 THEN a.agentHoldDuration ELSE 0 END)         AS AgentHoldDuration		        
                 ,sum(a.Duration)                                                                   AS Totalhandlingtime
 				,sum(CASE WHEN a.IsInBound=0 THEN a.Duration ELSE 0 END) 				            AS OutboundCall
                 ,avg(CASE WHEN a.IsInBound=0 THEN a.Duration ELSE 0 END) 				            AS averageOutboundCall   
                 ,	SUM(a.ACW)/COUNT(1)				                                                AS averageACW 
                 ,max(chatDuration)                                                                 AS maxChatDuration
                 ,min(chatDuration)                                                                 AS minChatDuration
                  ,sum(CASE WHEN a.callBack=1 THEN 1 ELSE 0 END)                                    AS NoOfCallbackReceived
                  ,sum(CASE WHEN a.callBack=1 THEN 1 ELSE 0 END)                                    AS NoOfCallbackReturned
                  ,sum(CASE WHEN a.callBack=2 THEN 1 ELSE 0 END)                                    AS NoofCallbackAnswered
                  ,sum(case when a.callBack=1 THEN 1 ELSE 0 END)                                    AS NoofCallbackNotAnswered 
                  ,sum(case when a.dispositionName='Resolved' THEN 1 ELSE 0 END)                    AS NoofResolvedCalls
                  ,sum(case when a.UMNStatus =4 THEN 1 ELSE 0 END)                                  AS NoofDiscardedDeclinedinteraction 
                  ,sum(case when a.callBack =2 and a.UMNStatus in (3,4,5) then 1 else 0 end)        AS NoofFailedOutbound
                 
                  ,SUM(CASE WHEN a.IsInBound = 1 AND a.agentconnecttime > 0  THEN 1 ELSE 0 END) 	   AS answeredCall
                  ,SUM(CASE WHEN a.IsInBound = 0  THEN 1 ELSE 0 END) 	                               AS unansweredCall
                  ,sum(case when a.IsInBound =1 THEN 1 ELSE 0 END)                                     AS IncomingChats
                  ,sum(case when a.IsInBound =1 THEN 1 ELSE 0 END)                                     AS receivedCall
				  , SUM(CASE WHEN a.DispositionCategory = 3 THEN 1 ELSE 0 END )		                   AS totalHandled
                  ,SUM(CASE WHEN a.IsMissedCall =1  THEN 1 ELSE 0 END)                                 AS totalMissed
                  ,SUM(CASE WHEN a.transferredTime  IS not NULL THEN 1 ELSE 0 END)                     AS totalTransferred
                  ,SUM(a.EndTime-a.StartTime)	                                                       AS totalChats
                  ,sum(a.voiceMailDuration)                                                            AS totalLengthOfVoicemail
                  ,sum(a.callEndTime-a.callStartTime)                                                  AS totalCall
                  ,sum(case when a.IsAbandoned =1 THEN 1 ELSE 0 END)                                   AS totalAbandoned
                  ,SUM(CASE WHEN a.dialDuration BETWEEN 1 AND 30000 AND a.dialDuration IS NOT NULL THEN 1 ELSE 0 END) AS thresholdTime
                  ,count(1)                                                                            AS queriesReceived
                  from tt_temp_sessionHistory a
                  group by  a.agentHoldDuration,a.loginTime,a.Duration,a.callAbandonTime,a.QueueWaitTime,a.repliedOn,a.receivedOn,a.EndTime,a.StartTime,a.SessionDate,a.agentName,a.customerNumber,a.customerName,a.QueueName,a.dispositionName,a.ChatStatus,a.callBack,a.voicemailStatus,a.TransferredAgent,a.channelType,
                  a.Supervisorname,a.customeremailId,a.location,a.customerTag,a.skill_name,a.logoutTime,a.sessionEndTime,a.callstartTime,
                  a.businessEndTime,a.businessStartTime,a.assignedTo,a.agentId;
   
    	SELECT * FROM temp_AllagentId;
  			   
  	SELECT 	COUNT(1) v_Total_Count
  	FROM 	tt_temp_sessionHistory a;	
     
               ALTER TABLE tt_sessionHistory_calc ADD COLUMN availableTime		INT;
               ALTER TABLE tt_sessionHistory_calc ADD COLUMN unavailableTime		INT;
 			  ALTER TABLE tt_sessionHistory_calc ADD COLUMN agentName			VARCHAR(150);
              UPDATE 	tt_sessionHistory_calc	SH_C
              JOIN 	temp_AllagentId			t_A		ON 	SH_C.agentId = t_A.UserID        
              SET 	agentName		= t_A.UserName 
      			,	availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.state ='Ready' THEN S.stateDuration ELSE 0 END) 
      									FROM 	state_timer S	
                                          WHERE  	S.domainId	= p_domainId
                                          AND 	S.ext			= t_A.ext
                                          AND 	S.`timestamp`	BETWEEN v_startTmpstmp and v_endTmpstmp )
                ,	unavailableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.state ='Busy' THEN S.stateDuration ELSE 0 END) 
      									FROM 	state_timer S	
                                          WHERE  	S.domainId	= p_domainId
                                          AND 	S.ext			= t_A.ext
                                          AND 	S.`timestamp`	BETWEEN v_startTmpstmp and v_endTmpstmp );                      
   
          	SELECT 	a.SessionDate	 												  AS `dateTime`
  				  ,a.agentName 														  AS agentName
  				  ,a.customerNumber													  AS customerNumber	
                  ,a.customerName 													  AS customerName
                  , a.QueueName                                                        AS queueName
                  ,a.dispositionName                                                   AS dispositionStatus
                  ,a.ChatStatus                                                        AS chatStatus
                  ,null                                                                AS skillName
                  ,a.callBack                                                          AS callbackStatus
                  ,a.voicemailStatus                                                   AS voiceMailStatus
 				  ,a.TransferredAgent                                                  AS transferredAgent
                  ,a.channelType
                  ,a.Supervisorname                                                    AS supervisorName
                  ,a.customeremailId                                                   AS customerEmailId
                  ,a.location                                                        
                  ,a.customerTag                                                       AS customerTag
                  ,a.HandleTime  	                                                   AS handleTime
                  ,a.AgentLoginTime                                                    AS agentLoginTime	
 			      ,a.AgentLogoutTime	                                               AS agentLogoutTime
                  ,a.callEndTime	
                  ,a.TotalTime 	                                                          AS totalTime
                  ,a.averageholdtime	                                                  AS averageHoldTime
                  ,a.activeChatTime	                                                      AS activeChatTime
                  ,a.totalActiveChatTime	                                              AS totalActiveChatTime
 				 ,a.AverageActiveChattime	                                              AS averageActiveChattime
                  ,a.AverageReplytimeformessage	                                          AS averageReplyTimeForMessage
                  ,a.AverageQueueWaitTime                                                 AS averageQueueWaitTime	
 				 ,a.maxiumQueueWaitTime	
                  ,a.averageResponseTime	
                  ,a.totalInteractionTime	
                  ,a.totalLoggedinTime	
                  ,a.totalTalktime	
                  ,a.AverageTalktime	                                              AS averageTalktime
                  ,a.AverageHandleTime	                                              AS averageHandleTime	
                  ,a.AgentHoldDuration	                                              AS agentHoldDuration
 				  ,a.Totalhandlingtime	                                              AS totalHandlingTime
                  ,a.availableTime
                  ,a.unavailableTime
 				  ,a.OutboundCall	                                                  AS outboundCall
                  ,a.averageOutboundCall                                               AS averageOutboundCall	
                  ,a.averageACW 	
 				  ,a.maxChatDuration	
                  ,count(a.OutboundCall)                                                AS noofOutboundCallAttempted
                  ,count(answeredCall)                                                  AS noofAnswered
                  ,count(answeredCall)                                                  AS noofunAnswered
                  ,count(a.assignedTo)                                                  AS NoofAssignedEmail
                  ,count(a.IncomingChats)                                               AS totalIncomingChats                                         
                  ,a.totalHandled    
                  ,a.totalMissed
                  ,COUNT(1)							                                    AS totalReceived                        
                  ,a.totalTransferred
                  ,COUNT(1)						                                        AS totalInteraction
                  ,a.totalChats
                  ,a.totalLengthOfVoicemail
                  ,a.totalCall
                  ,a.totalAbandoned
                  ,(a.totalAbandoned/a.receivedCall)*100	                            AS abandon
                  ,(a.totalTransferred/a.receivedCall)*100                              AS transfer
                  ,(a.NoOfCallbackReturned/a.receivedCall)*100                          AS PercentageofCallbackReturned
                  ,(a.NoofCallbackAnswered/a.receivedCall)*100                          AS PercentageofCallbackAnswered
                  ,(a.NoofCallbackNotAnswered /a.receivedCall)*100                      AS PercentageofCallbackNotAnswered
                  ,(a.answeredCall/a.receivedCall)*100                                  AS PercentageofAnswered
                  ,(a.totalMissed/a.receivedCall)*100                                   AS PercentageofMissed
                  ,(a.thresholdTime/a.queriesReceived)*100				             	AS serviceLevel
                  ,(a.totalTalktime/a.availableTime)*100							    AS occupancyrate
                  ,(a.totalTalktime/a.TotalTime)*100                                    AS agentUtilization
          	FROM 	tt_sessionHistory_calc a
             GROUP BY 
 		    a.SessionDate	  
            ,a.agentName 		 
            ,a.customerNumber	 
 		   ,a.customerName 	 
 		   ,a.QueueName        
            ,a.dispositionName   
            ,a.ChatStatus        
            ,null                
            ,a.callBack          
            ,a.voicemailStatus   
 		   ,a.TransferredAgent 
            ,a.channelType      
            ,a.Supervisorname                  
            ,a.customeremailId                 
            ,a.location                        
            ,a.customerTag                     
            ,a.HandleTime  	                
            ,a.AgentLoginTime                  
            ,a.AgentLogoutTime	                
            ,a.callEndTime	      
         ,a.TotalTime 	                    
         ,a.averageholdtime	                
         ,a.activeChatTime	                
         ,a.totalActiveChatTime	            
         ,a.AverageActiveChattime	        
         ,a.AverageReplytimeformessage      
         ,a.AverageQueueWaitTime            
         ,a.maxiumQueueWaitTime	
         ,a.averageResponseTime	
         ,a.totalInteractionTime	
         ,a.totalLoggedinTime	
         ,a.totalTalktime	
         ,a.AverageTalktime	          
         ,a.AverageHandleTime	
         ,a.AgentHoldDuration	
         ,a.Totalhandlingtime
 		 ,a.availableTime
 		 ,a.unavailableTime
         ,a.OutboundCall	    
         ,a.averageOutboundCall 
 		 ,a.averageACW 	
 		 ,a.maxChatDuration	
         ,a.totalHandled
         ,a.totalMissed
         ,a.totalTransferred
         ,a.totalChats
         ,a.totalLengthOfVoicemail
         ,a.totalCall
         ,a.totalAbandoned
         ,a.receivedCall
         ,a.NoOfCallbackReturned
         ,a.NoofCallbackAnswered
         ,a.NoofCallbackNotAnswered
         ,a.NoofCallbackNotAnswered
         ,a.answeredCall
         ,a.thresholdTime
         ,a.queriesReceived
 	 LIMIT v_offset, p_limit;
     END ;;
DELIMITER ;
