CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetEmailNotifications`(
      p_CompanyId 	INT,
      p_ProductId  INT
      )
BEGIN
   
   	DECLARE v_TicketEmailNotificationsId	INT;	
      	DECLARE v_CurDate  						DATETIME;
          
    	SET v_CurDate	= NOW();
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	TicketEmailNotificationsId INTO v_TicketEmailNotificationsId 
   	FROM 	tb_TicketEmailNotifications
   	WHERE	CompanyId = p_CompanyId 
   	AND 	productId = p_ProductId 
   	AND 	IsDefault = 1
      LIMIT	1;
       
       IF v_TicketEmailNotificationsId IS NULL
    	THEN
      		INSERT INTO tb_TicketEmailNotifications 
              (CompanyId, 
               ProductId, 
               NotificationName, 
               `Description`, 
               EmailTypeId, 
               EmailSubject, 
               EmailBody, 
               IsActive, 
               IsDefault, 
               CreatedBy, 
               CreatedDate, 
               UpdatedBy, 
               UpdatedDate
      		   )
      		select 
               p_CompanyId, 
               p_ProductId, 
               NotificationName, 
               `Description`, 
               EmailTypeId, 
               EmailSubject, 
               EmailBody, 
               IsActive, 
               1, 
               CreatedBy,
               v_CurDate, 
               UpdatedBy, 
               v_CurDate
   		from tb_TicketEmailNotificationsTemplate;
    	END IF;
   
       SELECT a.TicketEmailNotificationsId,
  			a.NotificationName,
  			a.EmailTypeId,
              b.TypeCodeName as EmailType,
  			a.IsActive
       FROM   tb_TicketEmailNotifications a,
  		    TypeCode b
       WHERE  a.CompanyId    = p_CompanyId
       and    a.ProductId    = p_ProductId
       and    a.EmailTypeId  = b.TypeCodeID;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
