CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetGroupBasedTicketHistory`(
     p_GroupId	INT,
     p_CompanyId	INT
     )
begin
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT
         a.TicketAssociateCustContact,
         a.TicketId,
         b.TicketLogDetailId,
         b.LogDetails,
         a.CreatedBy,
         c.UserName AS 'CreatedByUser',
         a.CreatedDate,
         a.UpdatedBy,
         d.UserName AS 'UpdatedByUser',
         a.UpdatedDate
     FROM       tb_TicketDetails a 
     INNER JOIN tb_TicketLogDetail b ON a.TicketId = b.TicketId
     INNER JOIN tb_TicketUser c ON a.CreatedBy = c.UserId
     INNER JOIN tb_TicketUser d ON a.UpdatedBy = d.UserId
     WHERE 	a.AssignedToGroupId  	= p_GroupId
     AND 	a.IsDeleted 			= 0;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  end ;;
DELIMITER ;
