CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getIntentName`(
       IN p_contactCenterNumber BIGINT,
       IN p_domainId INT
   )
BEGIN
       DECLARE v_websiteId VARCHAR(100);
       DECLARE v_assistPriority TINYINT;
       DECLARE voiceBotTemplte  tinyint default 0;
       DECLARE IntentQueue JSON;
     
 	WITH CTE_T AS (
  		SELECT 	JSON_OBJECT("queueId", InIQ.queueId, "intents", group_concat(InIQ.intents)) AS A
  		FROM 	tb_mapIntentQueue InIQ
  		WHERE 	InIQ.contactCenterNumber 	= p_contactCenterNumber 
         AND 	InIQ.domainId 				= p_domainId
  		GROUP BY InIQ.queueId
  	)
 	SELECT JSON_ARRAYAGG(A) INTO IntentQueue FROM CTE_T;
       
 	SELECT websiteId INTO v_websiteId FROM websiteScraper WHERE domainId = p_domainId ORDER BY web_id LIMIT 1;
 	SELECT assistPriority INTO v_assistPriority FROM call_configuration WHERE domainId = p_domainId ORDER BY callFlowId LIMIT 1;
   
    SET voiceBotTemplte = 
    CASE 
        WHEN p_contactCenterNumber = '448000032663' OR p_contactCenterNumber = '442071799934' THEN 1
        ELSE 0
    END;
    
    select v_websiteId AS websiteId,v_assistPriority AS assistPriority, IntentQueue ,voiceBotTemplte;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
