CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetIrrelevantChatQuestionAnswer`(	
	p_chatFlowId		INT
 	,p_domainId			INT	
    ,p_websiteId 		VARCHAR(255)
 )
BEGIN
	IF p_chatFlowId IS NOT NULL
    THEN
		SELECT chatFlowId
			,	questionAnswer
		FROM 	tb_IrrelevantChatQuestionAnswer
		WHERE 	chatFlowId	= p_chatFlowId
		AND 	domainId	= p_domainId;    
	ELSE
		SELECT chatFlowId
			,	questionAnswer
		FROM 	tb_IrrelevantChatQuestionAnswer
		WHERE 	domainId	= p_domainId
        AND 	websiteId	= p_websiteId;        
    END IF;
 END ;;
DELIMITER ;
