CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetNewAgent`(
   p_domainId INT,
   p_roleid   INT
)
BEGIN
    DECLARE v_Today DATE;
    SET v_Today = CURDATE();

    DROP TEMPORARY TABLE IF EXISTS temp_AgentByEmail;
    CREATE TEMPORARY TABLE temp_AgentByEmail (
        id             INT,
        UserName       VARCHAR(255),
        emailId 	   VARCHAR(500),
        address 	   VARCHAR(500),
        ext 		   INT,
        status 		   VARCHAR(255),
        createdAt	   DATETIME,
        updatedAt 	   DATETIME
    );

    INSERT INTO temp_AgentByEmail
    SELECT  U.UserID 				 AS id,
            U.UserName,
            U.emailId,
            U.address,
            U.ext,
            A_S.statusName 			 AS status,
            U.createdAt,
            U.updatedAt
    FROM    tb_User U
    JOIN    agent_status A_S ON A_S.aid = U.StatusID
    WHERE   U.domainId = p_domainId
    AND 	U.roleid   = p_roleid
    AND     DATE(U.createdAt) = v_Today;


    IF (SELECT COUNT(*) FROM temp_AgentByEmail) = 0 THEN
        INSERT INTO temp_AgentByEmail (id, UserName, emailId, address, ext, status, createdAt, updatedAt)
        VALUES (1234, 'test_UserName', 'test_Email@gmail.com', 'test_Address', 123, 'Ready', v_Today, v_Today); 
    END IF;

    SELECT * FROM temp_AgentByEmail;

END ;;
DELIMITER ;
