CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getOmniChannelEmail`(
    p_domainId INT,
    p_FilterDate DATETIME,
    p_FilterDateOperator VARCHAR(3),
    p_offset SMALLINT,
    p_limit SMALLINT
)
BEGIN
    DECLARE v_offset SMALLINT;
    DECLARE v_FilterDateOperator VARCHAR(3);
    DECLARE v_Filter VARCHAR(200);

    SET v_offset = p_offset * p_limit;

    IF p_FilterDate IS NOT NULL THEN
        SET v_FilterDateOperator = CASE
                WHEN p_FilterDateOperator = 'EQ' THEN ' = '
                WHEN p_FilterDateOperator = 'LT' THEN ' < '
                WHEN p_FilterDateOperator = 'GT' THEN ' > '
                WHEN p_FilterDateOperator = 'GTE' THEN ' >= '
                WHEN p_FilterDateOperator = 'LTE' THEN ' <= '
            END;

        SET v_Filter = CONCAT(" AND a.createdAt ", v_FilterDateOperator, "'", p_FilterDate, "'");
    ELSE
        SET v_Filter = '';
    END IF;

    SET @Query = CONCAT("SELECT web_id,websiteId,baseName,websiteId,a.EmailConfigId,a.emailAddress,a.aliasName,",
        "a.emailThreshold,a.isEmail,a.createdAt,a.updatedAt,a.primaryEmail,a.supervisorName,a.isBot,a.isBotPurchased,",
        "a.knowledgeBasedId,a.autoAssignAgent FROM email_config a ",
        "LEFT JOIN websiteScraper b ON a.domainId = b.domainId AND a.knowledgeBasedId = b.web_id ",
        "WHERE a.domainId = ", p_domainId, v_Filter, " ORDER BY a.EmailConfigId DESC LIMIT ", v_offset, ",", p_limit, ";");

    PREPARE stmt FROM @Query;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
