CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getOmniChannelSms`(
    p_domainId	 INT,
    p_FilterDate DATETIME,
    p_FilterDateOperator VARCHAR(3),
    p_offset SMALLINT,
    p_limit SMALLINT
  )
begin
 DECLARE v_offset SMALLINT;
    DECLARE v_FilterDateOperator VARCHAR(3);
    DECLARE v_Filter VARCHAR(200);

    SET v_offset = p_offset * p_limit;

    IF p_FilterDate IS NOT NULL THEN
        SET v_FilterDateOperator = CASE
                WHEN p_FilterDateOperator = 'EQ' THEN ' = '
                WHEN p_FilterDateOperator = 'LT' THEN ' < '
                WHEN p_FilterDateOperator = 'GT' THEN ' > '
                WHEN p_FilterDateOperator = 'GTE' THEN ' >= '
                WHEN p_FilterDateOperator = 'LTE' THEN ' <= '
            END;

        SET v_Filter = CONCAT(" AND a.createdAt ", v_FilterDateOperator, "'", p_FilterDate, "'");
    ELSE
        SET v_Filter = '';
    END IF;

    SET @Query = CONCAT( " select web_id,baseName,websiteId,pid,user_id,type,city,your_number,createdAt,updatedAt,callFlowId,recording,isCall,isSms,queueName,aliasName,outboundSms,smsThreshold
,status,callFlowName,defaultUpdated,supervisorName,isCallIn,isCallOut,isSmsOut,isSmsIn,queueId,country,isBot,isBotPurchased,knowledgeBasedId,autoAssignAgent from did_purchase a 
 left join websiteScraper b on a.domainId = b.domainId and a.knowledgeBasedId = b.web_id
 where a.domainId = ", p_domainId, v_Filter, " ORDER BY a.pid DESC LIMIT ", v_offset, ",", p_limit, ";");

	PREPARE stmt FROM @Query;
  	EXECUTE stmt; 
  	DEALLOCATE PREPARE stmt;   
  end ;;
