CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetPersonalDetails`(	
    	p_PhoneNumber	VARCHAR(1000)
		,p_DomainId		INT
      )
BEGIN	
          DROP TEMPORARY TABLE IF EXISTS temp_PhoneNumber; 
          CREATE TEMPORARY TABLE temp_PhoneNumber(PhoneNumber BIGINT);    
          
          CALL split(p_PhoneNumber,','); 
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          INSERT INTO temp_PhoneNumber(PhoneNumber)
          SELECT Items from tt_Split_temptable;  
          
      	SELECT 	C_C.coid
      			,C_C.firstName
      			,C_C.lastName
  				,IF(IFNULL(C_C.primaryPhoneNumber,'')='',C_C.phoneNumber, JSON_ARRAY_INSERT(C_C.phoneNumber,'$[0]',C_C.primaryPhoneNumber))	phoneNumber				
  				,IF(IFNULL(C_C.primaryEmail,'')='',C_C.email,JSON_ARRAY_INSERT(C_C.email,'$[0]',C_C.primaryEmail))							email        
      			,C_C.accountNumber
      			,C_C.tags
      			,C_C.location
      			,C_C.address
      			,C_C.country
      			,C_C.state
      			,C_C.city
      			,C_C.postalCode
      			,C_C.facebook
      			,C_C.instagram
      			,C_C.whatsapp
      			,C_C.twitter
      			,C_C.voiceBiometric
      			,C_C.domainId
      			,C_C.mergeCustomer
      			,C_C.blockCustomer
      			,C_C.doNotDisturb
      			,C_C.blockCustomerReq
      			,C_C.doNotDisturbReq
      			,C_C.type
      			,C_C.currentCustomerNumber
      			,C_C.customerType 
      	FROM 	customer_contact 	C_C
      	JOIN 	temp_PhoneNumber	T_P	ON (	C_C.primaryPhoneNumber LIKE CONCAT('%',T_P.PhoneNumber,'%')
   										OR 	C_C.phoneNumber LIKE CONCAT('%',T_P.PhoneNumber,'%'))
      	WHERE 	C_C.domainId = p_DomainId
         AND 	JSON_VALID(C_C.phoneNumber) 	= 1
 		AND 	JSON_VALID(C_C.email) 			= 1;        
         DROP TEMPORARY TABLE IF EXISTS temp_PhoneNumber; 
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
