CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetPlanRemainingChatSessionCount`(	
          	p_domainId	INT
          	 )
sp_exit: BEGIN	
      	DECLARE v_planRechargeId					INT;
      	DECLARE v_noOfPlanChatSessionAgent			INT;
         DECLARE v_noOfPlanChatSessionBot			INT;
      	DECLARE v_planEndTime						DATETIME; 
      	DECLARE v_curDate							DATETIME DEFAULT NOW();
      	DECLARE v_isChatSessionMovedToCurrentPlan	TINYINT;
      	DECLARE v_domainId							BIGINT;
      	DECLARE v_isUnilimitedChat					TINYINT;
     	DECLARE v_planId							INT;
		DECLARE v_TotalSession						INT;
        
		if exists(select 1 from tb_PlanRecharge where domainId = p_domainId and cast(planEndTime as date) < cast(v_curDate as date) limit 1) 
		then 
			select -1 as errcode, 'Inactive Plan' as errmsg;
			leave sp_exit;
		End if;

       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
       	SELECT 	planRechargeId, noOfPlanChatSessionAgent,noOfPlanChatSessionBot, planEndTime,isChatSessionMovedToCurrentPlan, isUnilimitedChat, planId, TotalSession
       	INTO 	v_planRechargeId, v_noOfPlanChatSessionAgent, v_noOfPlanChatSessionBot, v_planEndTime, v_isChatSessionMovedToCurrentPlan, v_isUnilimitedChat, v_planId, v_TotalSession
       	FROM 	tb_PlanRecharge
       	WHERE 	domainId 	= p_domainId
      
       	AND 	v_curDate	BETWEEN planStartTime AND planEndTime;
       	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  
         SELECT 	TotalSession INTO 	v_TotalSession       	
         FROM 	tb_PlanRecharge 
         WHERE 	domainId 	= p_domainId; 
         
          IF v_isChatSessionMovedToCurrentPlan IS NULL
          THEN
      		UPDATE 	tb_CurrentPlan
      		SET 	chatRemainingSessionAgent 	= 0
     			,	chatRemainingSessionBot 	= 0
      			,	isUnilimitedChat	 		= NULL	
      			,	updatedDate			 		= v_curDate
                 ,	TotalSessionUsed			= v_TotalSession
                 ,	TotalSession				= v_TotalSession
      		WHERE 	domainId			 		= p_domainId;	
       	ELSEIF v_isChatSessionMovedToCurrentPlan = 0
       	THEN		
       		SELECT 	domainId INTO v_domainId
       		FROM 	tb_CurrentPlan
      		WHERE 	domainId	= p_domainId;
 
               IF v_domainId IS NULL
               THEN			
       			INSERT INTO tb_CurrentPlan
     			(	planId					
     				,domainId				
     				,chatRemainingSessionAgent	
     				,chatRemainingSessionBot	
     				,isUnilimitedChat
     				,createdDate			
     				,updatedDate
					,TotalSession
					,TotalSessionUsed

     			)
     			VALUES
     			(	v_planId
     				,p_domainId
     				,v_noOfPlanChatSessionAgent
     				,v_noOfPlanChatSessionBot
     				,v_isUnilimitedChat
     				,v_curDate
     				,v_curDate
					,v_TotalSession
					,0
     			);
               ELSE
       			UPDATE 	tb_CurrentPlan
       			SET 	planId				 		= v_planId	
      				,	chatRemainingSessionAgent 	= v_noOfPlanChatSessionAgent
                     ,	chatRemainingSessionBot 	= v_noOfPlanChatSessionBot
       				,	isUnilimitedChat	 		= v_isUnilimitedChat	
       				,	updatedDate			 		= v_curDate
                     ,	TotalSession				= v_TotalSession
       			WHERE 	domainId			 		= v_domainId;	
               END IF;
       
      		UPDATE 	tb_PlanRecharge
      		SET 	isChatSessionMovedToCurrentPlan = 1
      			,	updatedDate		= v_curDate
      		WHERE 	planRechargeId 	= v_planRechargeId;
       	END IF;        
              
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
       	SELECT 	chatRemainingSessionAgent
   			,	chatRemainingSessionBot
       		,	isUnilimitedChat
       		,	v_planEndTime		AS planEndTime
             ,	IFNULL((TotalSession - ifnull(TotalSessionUsed,0)),0) as remainingSession
       	FROM 	tb_CurrentPlan
       	WHERE 	domainId = p_domainId;
       	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
