/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Getqueue`(p_domainId				INT 
  ,p_FilterDate			DATETIME
  ,p_FilterDateOperator	VARCHAR(3) 
  ,p_offset				SMALLINT   
  ,p_limit				SMALLINT   
  )
BEGIN
  	DECLARE v_offset				SMALLINT;
     DECLARE v_FilterDateOperator	VARCHAR(3);
     DECLARE v_Filter				VARCHAR(200);
     
 	SET v_offset = p_offset * p_limit;
     
 	IF p_FilterDate IS NOT NULL
 	THEN
 		SET v_FilterDateOperator = 	CASE 	WHEN p_FilterDateOperator = 'EQ' THEN ' = ' 
 											WHEN p_FilterDateOperator = 'LT' THEN ' < ' 
 											WHEN p_FilterDateOperator = 'GT' THEN ' > ' 
 											WHEN p_FilterDateOperator = 'GTE' THEN ' >= ' 
 											WHEN p_FilterDateOperator = 'LTE' THEN ' <= ' END;    
 	  
 		SET v_Filter = CONCAT(" AND createdAt ", v_FilterDateOperator, "'",p_FilterDate,"'");
 	ELSE
 		SET v_Filter = '';
 	END IF;    
     
 	SET @Query = CONCAT("SELECT Q.name, Q.description, Q.settingAudio, Q.announcement, Q.maximumCallers, Q.maximumWaitTime, Q.OutboundCallerId, Q.outBoundNumber
     , Q.maxCallHandlingTimeMM, Q.maxCallHandlingTimeSS, Q.callWrapUpTime, Q.outBoundCallStatus, Q.hoursOfOperatioId, Q.hours_of_operation, Q.outOfBusinessHours, Q.createdAt, Q.updatedAt FROM queue Q WHERE Q.domainId = "
 	,p_domainId, v_Filter," and Q.status = 1 ORDER BY Q.qid DESC LIMIT ",v_offset,",",p_Limit,";");
 	
   	PREPARE stmt FROM @Query;
   	EXECUTE stmt; 
   	DEALLOCATE PREPARE stmt;   
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
