CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetRecentlyViewedTicketDetails`(	userId 		BIGINT, 
        companyId 	INT,
    	productId 	INT
     )
BEGIN 
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	WITH CTE_UserTicket AS
       (	SELECT 	RT.TicketId
   			,	RT.UserId
               ,	MAX(RT.ViewTimestamp) ViewTimestamp
   		FROM 	tb_RecentlyViewedTickets	RT
           WHERE	RT.UserId 		= userId     
   		AND 	RT.CompanyId 	= companyId
   		AND 	RT.ProductId 	= productId
           GROUP BY RT.TicketId, RT.UserId
       )    
   	SELECT	RT.TicketId,
   			TD.TicketSubject,
   			TS.StatusName,
   			TU.UserName AS AssignedToAgentName,
   			TD.CreatedDate
   	FROM	CTE_UserTicket 		RT
   	JOIN	tb_TicketDetails 	TD ON RT.TicketId 			= TD.TicketId
   	JOIN	tb_TicketStatus 	TS ON TD.TicketStatusId 	= TS.StatusId
   	JOIN	tb_TicketUser 		TU ON TD.AssignedToAgentId 	= TU.UserId;
             
   	WITH CTE_UserContact AS
       (	SELECT 	RC.ContactId
   			,	RC.UserId
               ,	MAX(RC.ViewTimestamp) ViewTimestamp
   		FROM 	tb_RecentlyViewedContacts	RC
           WHERE	RC.UserId 		= userId     
   		AND 	RC.CompanyId 	= companyId
   		AND 	RC.ProductId	= productId
           GROUP BY RC.ContactId, RC.UserId
       )                 
   	SELECT	RC.ContactId,
   			TC.FirstName,
   			TC.LastName,
   			TCI_EMAIL.ContactInformation 	AS Email,
   			TCI_MOBILE.ContactInformation 	AS MobileNumber
   	FROM 	CTE_UserContact 			RC
   	JOIN 	tb_TicketContact 			TC 				ON 	RC.ContactId 						= TC.TicketContactId
   	LEFT JOIN 	tb_TicketContactInformation TCI_EMAIL 	ON 	TC.TicketContactId 					= TCI_EMAIL.TicketContactId
   														AND TCI_EMAIL.ContactInformationTypeId 	= 1108029 
   	LEFT JOIN	tb_TicketContactInformation TCI_MOBILE 	ON 	TC.TicketContactId 					= TCI_MOBILE.TicketContactId
   														AND TCI_MOBILE.ContactInformationTypeId = 1108030; 
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;                                                  
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
