/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetRecentTPIActivity`(
         p_domainId INT,
         p_channel  VARCHAR(100)   
     )
BEGIN
     
         DECLARE v_Today DATE;
  
         
         SET v_Today = CURDATE();
  
     
         DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 
         CREATE TEMPORARY TABLE temp_channeltype (channelType VARCHAR(100));
         CALL split(p_channel, ','); 
         INSERT INTO temp_channeltype (channelType) 
         SELECT Items FROM tt_Split_temptable;
     
         IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'SMS') THEN
             SELECT sh.sessionId AS id, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.Summary, sh.IsInBound, 
                     sh.afterSMSWorkTime, sh.IsSessionClosed, sh.customerNumber, sh.calledNumber,sh.createdAt, sh.updatedAt, 
                     sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sh.SMSHistoryId
             FROM tb_SMSHistory sh
             LEFT JOIN tb_SMSDurationHistory sd ON sh.SMSHistoryId = sd.SMSHistoryId
             WHERE 
                 sh.domainId = p_domainId
				
				AND sh.IsSessionClosed = 1
				AND IFNULL(sd.IsBot, 0) = 0 
     			AND CAST(sh.createdAt as date) = v_Today
     			AND sh.createdAt >= DATE_SUB(NOW(), INTERVAL 30 MINUTE)
                 ORDER BY sh.SMSHistoryId DESC;
         END IF; 
         
         IF EXISTS(SELECT 1 FROM temp_channeltype WHERE channelType = 'Chat') THEN
             SELECT cth.sessionId AS id, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, ctdh.dispositionId, ctdh.Summary, cth.IsInBound, cth.dialDuration, cth.disconnectedBy, 
                                    cth.queueDuration, cth.assignedTo, cth.assignedBy, cth.assignedOn, 0 AS waitDuration, ctdh.afterChatWorkTime, ctdh.Istransferred, NULL AS transferredTypeId, ctdh.markAsRead, cth.CustomerId, ctdh.ticketId, NULL AS CallBackDatetime, 
                                    cth.Browser, cth.IPAdress, cth.ChatSubject, cth.createdAt, cth.updatedAt, ctdh.StartTime, ctdh.EndTime, ctdh.Duration, ctdh.AgentId, ctdh.AgentSkillId, ctdh.IsBot, ctdh.BotId, 
                                    ctdh.transferredTime, ctdh.QueueId, NULL AS Message, cth.ChatHistoryId, cth.chatWidgetId, 
                                        
                                        TIMEDIFF(NOW(), cth.createdAt) AS TimeDifference, 
                                        cth.CallBackStatus
                                 FROM tb_ChatHistory cth
                                 JOIN tb_ChatDurationHistory ctdh ON cth.ChatHistoryId = ctdh.ChatHistoryId
                                 WHERE cth.domainId = p_domainId 
                                  AND cth.CallBackStatus = 1 
                                 AND cast(cth.createdAt as date) = v_Today
     							AND cth.createdAt >= DATE_SUB(NOW(), INTERVAL 30 MINUTE)
                                 ORDER BY cth.ChatHistoryId DESC;
         END IF;
         
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
