/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetRemainingSessionForEmailSent`(
   p_domainId int
   )
sp_exit:Begin
   
	declare v_emailId 				VARCHAR(100);
	declare v_isEmailSent 			VARCHAR(5) DEFAULT '';
   	DECLARE v_remining_sessions		INT DEFAULT 0;
   	DECLARE v_TotalSession			INT;
   	DECLARE v_TotalSessionUsed		INT;
   	DECLARE v_planStartTime			DATETIME;
   	DECLARE v_planEndTime			DATETIME;
   	DECLARE v_planActiveStatus		TINYINT(1);
   	DECLARE v_date_reminder			TINYINT(1);
   	DECLARE v_is_reminder_for_date	TINYINT(1) DEFAULT 0;
    
   	select emailId into v_emailId from tb_User where domainId = p_domainId and ext = 200;
    
    SELECT planStartTime, planEndTime, CASE WHEN planEndTime < NOW() AND is_reminder = 0 THEN 1 ELSE 0 END, CASE WHEN DATE(planEndTime - INTERVAL 7 DAY) = CURDATE() AND is_reminder = 0 THEN 1 ELSE 0 END 
    INTO v_planStartTime, v_planEndTime, v_planActiveStatus, v_date_reminder
	FROM tb_PlanRecharge
	WHERE domainId = p_domainId
	LIMIT 1;
    
    IF v_date_reminder =  1
    THEN 
		SET v_planActiveStatus = 1 
        ,v_is_reminder_for_date = 1; -- for mail content difference 1 -> 7 days before content 0 -> expired
	END IF;
    
    IF v_planActiveStatus = 1 
    THEN
		SELECT v_emailId AS adminEmail, v_planActiveStatus AS planActiveStatus, v_is_reminder_for_date AS is_reminder_for_date,v_planEndTime as planEndTime;
		leave sp_exit;
	END IF;
 
   	select CASE WHEN (TotalSessionUsed/(if(TotalSession=0,1,TotalSession))) = 0.5 AND IsEmailSent IS NULL THEN 0
   		WHEN (TotalSessionUsed/(if(TotalSession=0,1,TotalSession))) = 0.8 AND IsEmailSent = 0 THEN 1
   		WHEN (TotalSessionUsed/(if(TotalSession=0,1,TotalSession))) = 1.0 AND IsEmailSent = 1 THEN 2 Else '' End 
           into v_isEmailSent 
       from tb_CurrentPlan where domainId = p_domainId and isUnilimitedChat=0;
       
      SELECT (TotalSession - TotalSessionUsed),TotalSession,TotalSessionUsed INTO v_remining_sessions, v_TotalSession,v_TotalSessionUsed
      FROM tb_CurrentPlan
      WHERE domainId = p_domainId;
       
       select v_isEmailSent as isEmailSent, IF(v_isEmailSent='','',v_emailId) as adminEmail,v_remining_sessions as remining_sessions,v_TotalSession as TotalSession,v_TotalSessionUsed as TotalSessionUsed
       ,v_planStartTime AS planStartTime,v_planEndTime AS planEndTime;
              
		IF (v_isEmailSent IS NOT NULL AND TRIM(v_isEmailSent) <> '')
        THEN
			UPDATE tb_CurrentPlan
			SET IsEmailSent =CASE WHEN IsEmailSent IS NULL THEN 0 ELSE IsEmailSent + 1 END
			WHERE domainId = p_domainId
			AND isUnilimitedChat = 0;
		END IF;

   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
