CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetReportEditColumn`(
    p_reportId    INT,
    p_domainId    INT,
    p_ext         INT,
    p_reportType  VARCHAR(50)
)
BEGIN
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    SELECT 
        reportId,
        editColumn,
        reportType
    FROM 	report_config
    WHERE 	(p_reportId IS NOT NULL AND reportId = p_reportId)
	OR 		(p_reportId IS NULL AND domainId = p_domainId AND ext = p_ext AND reportType COLLATE utf8mb4_0900_ai_ci = p_reportType );

    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
