    					 ed.AgentId, ed.AgentSkillId, ed.IsBot, ed.BotId, 'Email',eh.EmailHistoryId,eh.SentimentalScore,transferredTo,ed.Duration, eh.SessionStartTime, eh.SessionEndTime,
    					ed.EmailDurationHistoryId
