    				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    			end if;
                                           
    			DROP TEMPORARY TABLE IF EXISTS temp_History1; 	
    			CREATE TEMPORARY TABLE temp_History1                
    			SELECT ChatHistoryId,ChatDurationHistoryId,DATE_FORMAT(FROM_UNIXTIME(left(a.sessionStartTime,length(a.sessionStartTime))),'%d %b %Y') as createdDate,
    			channelType,a.domainId,customerNumber,FromEmail,ToEmail,sessionId,a.updatedAt,assignedBy,ticketId,isBot,callDuration,queueDuration,afterCallWorkTime,AfterEmailWorkTime,afterSMSWorkTime,afterwhatsappWorkTime as AfterWhatsappWorkTime,summary,sessionStartTime,sessionEndTime,
    			assignedByName, dispositionName, agentStatus, transferredTo, agentRecordingUrl, transferedBy, callType ,b.UserName ,Istransferred,CustomerId,callBack,dispositionId
    			,assignedTo,IsInBound,AgentId,markAsRead,SentimentalScore,a.name as queueName,a.afterFacebookWorkTime,a.customerFacebookId,a.agentFacebookId,a.afterInstagramWorkTime,a.customerInstagramId,a.agentInstagramId
    			,Duration,afterChatWorkTime,AgentStartTime,AgentEndTime,DurationHistoryId, a.agentDuration,a.CallBackStatus, a.voicemailUrl, a.isVMCallBackCompleted,IsMissed,a.meetingId,a.recordUrl,a.recordingSessionId,a.IsAbandoned
    			,a.IsOutOfBussinessHour,a.CallHistoryId,a.SMSHistoryId,a.EmailHistoryId,a.WhatsappHistoryId,a.FacebookHistoryId,a.InstagramHistoryId,a.isOutboundCampaign
    			FROM temp_History a     
    			left join tb_User b on a.Istransferred = b.UserID
    			ORDER BY a.updatedAt DESC LIMIT v_offset, p_limit; 
                 			 
                 			  
                 								   
                 					ALTER TABLE temp_History1 ADD COLUMN CustomerName	VARCHAR(150), ADD COLUMN agentName VARCHAR(150),ADD COLUMN transferredToName VARCHAR(150), ADD colorCode VARCHAR(50)
                 					   ,ADD COLUMN transferredByName VARCHAR(150);
                 	  				
                 					DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; 
                 					CREATE TEMPORARY TABLE temp_AvailableUser1
                 					SELECT UserId ,UserName ,roleid FROM temp_AvailableUser;
                 		 
                 					DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser2; 
                 					CREATE TEMPORARY TABLE temp_AvailableUser2
                 					SELECT UserId ,UserName ,roleid FROM temp_AvailableUser;
                 					  
                 					DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser3; 
                 					CREATE TEMPORARY TABLE temp_AvailableUser3
                 					SELECT UserId ,UserName ,roleid FROM temp_AvailableUser;      
                                  
                 					 DROP TEMPORARY TABLE IF EXISTS tmp_disposition; 
                 					CREATE TEMPORARY TABLE tmp_disposition
                 					  SELECT did 
                 						,	dispositionName
                 						,	colorCode
                 					  FROM 	disposition_status
                 					  WHERE	domainId	= p_domainId;
                 					  
                 					  INSERT INTO tmp_disposition
                 					  SELECT TypeCodeID		AS did
              						,	TypeCodeName	AS dispositionName
                 						,	Null			AS colorCode
                 					  FROM 	TypeCode 	
                 					  WHERE 	TypeGroupID = 1121;	              
                              
                 					UPDATE 	temp_History1		H
                 					
              
                 					LEFT JOIN 	temp_AvailableUser	AB	ON H.assignedBy			= AB.UserId        
                 					LEFT JOIN 	temp_AvailableUser1	ATU	ON H.AgentId			= ATU.UserId        
                 					LEFT JOIN 	temp_AvailableUser2	TU	ON H.transferredTo    	= TU.UserId	
                 					LEFT JOIN 	temp_AvailableUser3	TL	ON H.transferedBy    	= TL.UserId	
                 					LEFT JOIN 	tmp_disposition		DS	ON H.dispositionId		= DS.did
                 					SET 	 H.assignedByName	= AB.UserName 
                 						,	H.dispositionName	= DS.dispositionName
                 						,	H.colorCode			= DS.colorCode
                 						,	H.agentName			= ATU.UserName
                 						,	H.transferredToName	= TU.UserName
                 						,   H.transferredByName = TL.UserName
                                      ,	H.CustomerId		= IFNULL(H.CustomerId,0); 
                 						   
                 				
                              
    
    
                                               
              				UPDATE 	temp_History1		H
              				JOIN 	customer_contact	CC 	ON H.CustomerId = CC.coid 
              				SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),' ',ifnull(CC.lastName,''));     
                                                       
 							UPDATE 	temp_History1		H
              				JOIN 	customer_contact	CC 	ON H.customerNumber collate utf8mb4_0900_ai_ci = CC.primaryPhoneNumber AND CC.domainId = H.domainId
              				SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),' ',ifnull(CC.lastName,''))
              				WHERE 	H.CustomerId = 0; 
                                                  
 							UPDATE 	temp_History1		H
              				JOIN 	customer_contact	CC 	ON H.FromEmail collate utf8mb4_0900_ai_ci = CC.primaryEmail AND CC.domainId = H.domainId
              				SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),' ',ifnull(CC.lastName,''))
              				WHERE 	
 							H.channelType = 'Email' AND IFNULL(H.CustomerName,'') = ''; 
                            
                             UPDATE 	temp_History1		H
              				JOIN 	customer_contact	CC 	ON CC.email collate utf8mb4_0900_ai_ci like concat("%",H.FromEmail,"%")  AND CC.domainId = H.domainId
              				SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,''),' '),' ',ifnull(CC.lastName,''))
              				WHERE 	H.channelType = 'Email' AND IFNULL(H.CustomerName,'') = ''; 
                        
              				SELECT 	ChatHistoryId,ChatDurationHistoryId,createdDate,channelType,domainId,customerNumber,FromEmail,ToEmail,sessionId,updatedAt,assignedBy,ticketId
  									,isBot,callDuration,queueDuration,afterCallWorkTime,AfterEmailWorkTime,afterSMSWorkTime,AfterWhatsappWorkTime,summary,sessionStartTime,sessionEndTime
  									,assignedByName,dispositionName,agentStatus,transferredTo,agentRecordingUrl,transferedBy,callType,UserName,Istransferred,CustomerId,callBack,dispositionId
  									,assignedTo,IsInBound,AgentId,markAsRead,SentimentalScore,queueName,afterFacebookWorkTime,customerFacebookId,agentFacebookId,afterInstagramWorkTime,customerInstagramId
  									,agentInstagramId,Duration,afterChatWorkTime,AgentStartTime,AgentEndTime,DurationHistoryId,agentDuration,CallBackStatus,voicemailUrl,isVMCallBackCompleted
  									,IsMissed,meetingId,recordUrl,recordingSessionId,IsAbandoned,IsOutOfBussinessHour,CallHistoryId,SMSHistoryId,EmailHistoryId,WhatsappHistoryId,FacebookHistoryId
  									,InstagramHistoryId,isOutboundCampaign,CustomerName,agentName,transferredToName,colorCode,transferredByName
              				FROM 	temp_History1 a 
                            where 	((ifnull(if(CustomerName='',null,CustomerName),'new customer') like concat('%',p_search,'%')	OR customerNumber like concat('%',p_search,'%')	OR ToEmail like concat('%',p_search,'%')	OR FromEmail like concat('%',p_search,'%')
            						OR dispositionName like concat('%',p_search,'%')	OR a.queueName like concat('%',p_search,'%')	OR agentName like concat('%',p_search,'%')	OR transferredToName like concat('%',p_search,'%')
            						OR CustomerName like concat('%',p_search,'%')	OR SentimentalScore like concat('%',p_search,'%')	OR summary like concat('%',p_search,'%')) or ifnull(p_search,'')='')
            				and		( EXISTS  (select 1 from temp_queue b WHERE b.queueName = a.queueName) OR ifnull(p_queue,'')='')
							and 	case p_isQualifiedUser when 1 then (CustomerName like ' %%') when 2 then (CustomerName is not null AND CustomerName not like ' %%') ELSE 1=1 END
                            ORDER BY updatedAt DESC;
              	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetSessionHistoryDetails_old` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetSessionHistoryDetails_old`(		
          		p_domainId 			INT
           		,p_channelType 		VARCHAR(255)
           		,p_dispositionId 	INT
           		,p_isInbound		TINYINT
           
           		,p_fromDate 			DATETIME
           		,p_toDate 			DATETIME
           		,p_UserId			INT
           		,p_offset 			INT
           		,p_limit 			INT
           )
spreturn:BEGIN  
                     	DECLARE v_CurDate		DATETIME;
                     	DECLARE v_fromDate 		DATE;
                     	DECLARE v_toDate 		DATE;
                 		DECLARE v_roleid		INT;	
     					DECLARE v_offset 		INT;
                     
                     	SET v_CurDate = NOW();
                 		SET v_offset = p_offset * p_limit;
                         
                     	IF p_dispositionId = 0 	THEN SET p_dispositionId = NULL; 					END IF;
                     	IF p_channelType = NULL THEN SET p_channelType = 'Chat,Email'; 				END IF;
                     	IF p_fromDate IS NULL 	THEN SET v_fromDate =  CAST(NOW() as DATE); 		ELSE SET v_fromDate = p_fromDate; END IF;
                     	IF p_toDate IS NULL 	THEN SET v_toDate = NOW(3); 						ELSE SET v_toDate = p_toDate; END IF;
                           
                     	DROP TEMPORARY TABLE IF EXISTS temp_userid; 		CREATE TEMPORARY TABLE temp_userid(UserId	BIGINT);
                     	DROP TEMPORARY TABLE IF EXISTS temp_channeltype; 	CREATE TEMPORARY TABLE temp_channeltype(channelType VARCHAR(100));
                     
                		CALL split(p_channelType, ','); INSERT INTO temp_channeltype (channelType) 	SELECT Items FROM tt_Split_temptable;
                       
            			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
            			DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser; 	CREATE TEMPORARY TABLE temp_AvailableUser(UserId BIGINT, UserName VARCHAR(255),roleid INT);    
            			INSERT INTO temp_AvailableUser
            			(	UserId
            				,UserName
            				,roleid
            			)
            			SELECT  UserID
            				,	UserName
           				,	roleid
            			FROM 	tb_User
            			WHERE 	domainId 	= p_domainId
            			AND 	roleid		IN (6,5,3);     
            			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                    
            			SELECT 	roleid 	INTO v_roleid
            			FROM 	temp_AvailableUser
            			WHERE 	UserId = p_UserId;
            				
            			IF IFNULL(p_UserId,0) = 0 OR v_roleid in (3,5) 
            			THEN
            				INSERT INTO temp_userid
            				(	UserId )
            				SELECT  UserID
            				FROM 	temp_AvailableUser;
            				  
            			ELSE		
            				INSERT INTO temp_userid
            				(	UserId )
            				SELECT  p_UserId;
            			END IF;
                         
                     	DROP TEMPORARY TABLE IF EXISTS temp_History; 
                     	CREATE TEMPORARY TABLE temp_History 
                     	(
                     		id_col int auto_increment primary key		,sessionId varchar(250)						,sessionStartTime bigint						,sessionEndTime bigint					,customerNumber bigint						
                     		,companyId int default null					,domainId int default null					,dispositionId int default null					,UMNStatus int default null				,IsInBound tinyint default null				,dialDuration bigint default null
                     		,disconnectedBy bigint default null			,queueDuration bigint default null			,assignedTo bigint default null					,assignedBy bigint default null			,assignedOn bigint default null				,calledNumber bigint default null
                     		,waitDuration bigint default null			,afterCallWorkTime int default null			,recordingTypeId int default null				,Istransferred bigint default null		,transferredTypeId int default null			,markAsRead tinyint default null
                     		,CustomerId int default null				,voicemailUrl varchar(500) default null		,ticketId bigint default null					,callDuration bigint default null		,summary text default null					,subject text default null
                     		,createdAt datetime default null			,updatedAt datetime default null			,chatFlowSourceId varchar(250) default null		,afterChatWorkTime int default null		,CallBackDatetime datetime default null		,Browser varchar(250) default null
                     		,IPAdress varchar(250) default null			,ChatSubject varchar(250) default null		,FromEmail varchar(100)  default null			,ToEmail varchar(100)  default null		,EmailSubject varchar(250)  default null	,EmailFlowSourceId int default null
                     		,AfterEmailWorkTime int default null		,IsSessionClosed tinyint default null		,SupervisorName varchar(100)  default null		,StartTime bigint  default null			,EndTime bigint  default null				,Duration bigint  default null
                     		,AgentHoldDuration bigint  default null		,AgentId bigint default null				,AgentSkillId bigint  default null				,IsBot int   default null				,BotId int  default null					,RecordingUrl varchar(500)  default null
                     		,transferredTime bigint  default null		,recordingDuration bigint  default null		,QueueId int  default null			        	,Message json default null				,channelType VARCHAR(255) default null		,SMSFlowSourceId int
                     		,afterSMSWorkTime int default null			,EmailHistoryId int default null			,ChatHistoryId int default null					,CallHistoryId int default null			,SMSHistoryId int default null				,WhatsappFlowSourceId int default null
                     		,afterWhatsappWorkTime int default null		,WhatsappHistoryId int default null			,callBack int default null						,queueName varchar(150) default null	,assignedByName varchar(150) default null	,dispositionName varchar(100) default null
                     		,agentStatus varchar(100) default null		,transferredTo bigint default null			,agentRecordingUrl varchar(100) default null	,transferred int default null			,callType varchar(25) default null			,transferredByName varchar(100) default null
                 			,SentimentalScore float default null		,transferredToName	varchar(150)			 ,name	varchar(255)							,FacebookHistoryId	bigint				,afterFacebookWorkTime	int					,NextFlowNode	varchar(150)
        					,transferredDate	datetime				,dispositionUpdatedBy	bigint				,immediateParentId	bigint						,rootParentId	bigint					,discardedDate	datetime					,repliedDate	datetime					
        					,markAsReadSupervisor	tinyint				,markAsReadAgent	tinyint					,customerFacebookId	bigint						,agentFacebookId	bigint				,AgentStartTime	bigint						,AgentEndTime	bigint
        					,InstagramHistoryId	bigint					,afterInstagramWorkTime	int					,customerInstagramId	bigint					,agentInstagramId	bigint				,InstagramCommunicationTypeId	int
                         ,ChatDurationHistoryId int default null
                     	); 
            
           		if exists(select 1 from temp_channeltype where channelType = 'Call' limit 1 )
            		then
            			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
                   		insert into temp_History(sessionId,sessionStartTime,sessionEndTime,customerNumber,domainId,dispositionId,UMNStatus,IsInBound,dialDuration, 
                   				disconnectedBy,queueDuration,assignedTo,assignedBy,assignedOn,calledNumber,waitDuration,afterCallWorkTime,recordingTypeId,transferredTypeId,markAsRead, 
                   				CustomerId,voicemailUrl,ticketId,callDuration,summary,subject,createdAt,updatedAt,StartTime,EndTime,Duration,AgentHoldDuration,AgentId,AgentSkillId,IsBot,BotId,RecordingUrl, 
                   				transferredTime,recordingDuration,QueueId,channelType,CallHistoryId,callBack,transferredByName,SentimentalScore,name)
                   		select 	clh.sessionId, clh.sessionStartTime, clh.sessionEndTime, clh.customerNumber, clh.domainId, cld.dispositionId, cld.UMNStatus, clh.IsInBound, cld.dialDuration, 
                   				clh.disconnectedBy, clh.queueDuration, clh.assignedTo, clh.assignedBy, clh.assignedOn, clh.calledNumber, clh.waitDuration, cld.afterCallWorkTime, clh.recordingTypeId, cld.transferredTypeId, cld.markAsRead, 
                   				clh.CustomerId, clh.voicemailUrl, cld.ticketId, clh.callDuration, cld.summary, cld.subject,clh.createdAt, clh.updatedAt, cld.StartTime, cld.EndTime, cld.Duration, cld.AgentHoldDuration, cld.AgentId, cld.AgentSkillId, cld.IsBot, cld.BotId, cld.RecordingUrl, 
                   				cld.transferredTime, cld.recordingDuration, cld.QueueId,'Call',clh.CallHistoryId,clh.callBack,'' transferredByName,cld.SentimentalScore,q.name
                   		from 	tb_CallHistory 				clh
                   		join 	tb_CallDurationHistory 		cld ON clh.CallHistoryId 	= cld.CallHistoryId
           				JOIN 	temp_userid					U	ON cld.AgentId			= U.UserId
           				left join queue						q	on cld.QueueId			= q.qid
           				WHERE 	clh.domainId 		= p_domainId
           				AND 	clh.callBack 		NOT IN (1,0) 
           				AND		(cld.dispositionId	= p_dispositionId 	or IFNULL(p_dispositionId,0) =0)
           				AND 	(clh.IsInBound 		= p_isInbound  		or ifnull(p_isInbound,'')='')
           				AND 	cast(clh.updatedAt as date) BETWEEN v_fromDate AND v_toDate 
           				order by clh.updatedAt desc LIMIT 0, p_limit; 
                        
                        
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                   	end if;
                         
            		if exists(select 1 from temp_channeltype where channelType = 'Chat' limit 1)
           		then
           			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
           			insert into temp_History(sessionId, sessionStartTime, sessionEndTime, chatFlowSourceId, companyId, domainId, dispositionId, Summary, IsInBound, dialDuration, disconnectedBy, 
           					queueDuration, assignedTo, assignedBy, assignedOn, waitDuration, afterChatWorkTime, Istransferred, transferredTypeId, markAsRead, CustomerId, ticketId, CallBackDatetime, 
           					Browser, IPAdress, ChatSubject, createdAt,updatedAt,  StartTime, EndTime, Duration, AgentId, AgentSkillId, IsBot, BotId, 
           					transferredTime, QueueId ,channelType,ChatHistoryId,ChatDurationHistoryId,transferredByName,SentimentalScore)
           			select  cth.sessionId, cth.sessionStartTime, cth.sessionEndTime, cth.chatFlowSourceId, cth.companyId, cth.domainId, ctdh.dispositionId, ctdh.Summary, cth.IsInBound, cth.dialDuration, cth.disconnectedBy, 
           					cth.queueDuration, ctdh.AgentId, cth.assignedBy, cth.assignedOn, Null AS waitDuration, ctdh.afterChatWorkTime, ctdh.Istransferred, Null AS transferredTypeId, ctdh.markAsRead, cth.CustomerId, ctdh.ticketId, Null AS CallBackDatetime, 
           					cth.Browser, cth.IPAdress, cth.ChatSubject, cth.createdAt, cth.updatedAt, ctdh.StartTime, ctdh.EndTime, ctdh.Duration, ctdh.AgentId, ctdh.AgentSkillId, ctdh.IsBot, ctdh.BotId, 
           					ctdh.transferredTime, ctdh.QueueId ,'Chat',cth.ChatHistoryId,ctdh.ChatDurationHistoryId,'' transferredByName,ctdh.SentimentalScore
           			FROM 	tb_ChatHistory 				cth
           			LEFT JOIN 	tb_ChatDurationHistory 	ctdh 	ON 	cth.ChatHistoryId 	= ctdh.ChatHistoryId
           			LEFT JOIN 	temp_userid				U		ON 	ctdh.AgentId		= U.UserId														
           			WHERE 	cth.domainId 			= p_domainId
                    AND 	IFNULL(cth.CallBackStatus,0) = 0  
    				AND 	ctdh.dispositionId		IS NOT NULL
           			AND		(ctdh.dispositionId		= p_dispositionId  or IFNULL(p_dispositionId,0) =0)
           			AND 	(cth.IsInBound 			= p_isInbound  or ifnull(p_isInbound,'')='')
           			AND 	cast(cth.updatedAt as date) BETWEEN v_fromDate AND v_toDate 
                      AND 	((p_UserId IS NOT NULL AND U.UserId IS NOT NULL) OR (p_UserId IS NULL))
           			ORDER BY cth.updatedAt desc LIMIT 0, p_limit;
          			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            		end if;
                            
               		if exists(select 1 from temp_channeltype where channelType = 'Email' limit 1 ) 
            		then
            			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
               			insert into temp_History(sessionId,SessionStartTime,SessionEndTime,FromEmail,ToEmail,EmailSubject,EmailFlowSourceId,CompanyId,domainId,DispositionId,Summary,IsInBound,
               					AssignedTo,AssignedBy,AssignedOn,AfterEmailWorkTime,Istransferred,TransferredTypeId,IsSessionClosed,CustomerId,TicketId,SupervisorName,createdAt,updatedAt,AgentId,
               					AgentSkillId, IsBot, BotId, channelType,EmailHistoryId,transferredByName,SentimentalScore,transferredTo)
               			select  eh.SessionId, eh.SessionStartTime, eh.SessionEndTime, eh.FromEmail, eh.ToEmail, eh.EmailSubject, eh.EmailFlowSourceId, eh.CompanyId, eh.domainId, eh.DispositionId, eh.Summary, eh.IsInBound, 
               					eh.AssignedTo, eh.AssignedBy, eh.AssignedOn, eh.AfterEmailWorkTime, eh.Istransferred, eh.TransferredTypeId, eh.IsSessionClosed, eh.CustomerId, eh.TicketId, eh.SupervisorName, eh.CreatedAt, eh.UpdatedAt
               				 , ed.AgentId, ed.AgentSkillId, ed.IsBot, ed.BotId, 'Email',eh.EmailHistoryId,'' transferredByName,eh.SentimentalScore,transferredTo
               			from 	tb_EmailHistory 			eh
               			join 	tb_EmailDurationHistory 	ed 	on eh.EmailHistoryId 	= ed.EmailHistoryId
               			LEFT JOIN 	temp_userid				U	ON ed.AgentId			= U.UserId
               			where 	eh.domainId 			= p_domainId
               			and		(eh.dispositionId		= p_dispositionId  or IFNULL(p_dispositionId,0) =0)
               			and 	cast(eh.updatedAt as date) BETWEEN v_fromDate AND v_toDate
               			AND 	(eh.IsSessionClosed = 1 OR ifnull(ed.IsBot,0) = 1)
                         AND 	(IFNULL(p_UserId,0) = 0 OR (p_UserId IS NOT NULL AND U.UserId IS NOT NULL))
               			order by cast(eh.updatedAt as date)  desc LIMIT 0, p_limit;
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
               		END IF; 
                 
             		if exists(select 1 from temp_channeltype where channelType = 'SMS' limit 1 ) 
                     then
            			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
             			insert into temp_History(sessionId,sessionStartTime,sessionEndTime,SMSFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
             					afterSMSWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
             					AgentId,AgentSkillId,IsBot,BotId,QueueId ,channelType,SMSHistoryId,transferredByName,SentimentalScore,transferredTo)
             			select 	sh.sessionId, sh.sessionStartTime, sh.sessionEndTime, sh.SMSFlowSourceId, sh.companyId, sh.domainId, sh.dispositionId, sh.Summary, sh.IsInBound, sh.assignedTo, sh.assignedBy, sh.assignedOn, 
             					sh.afterSMSWorkTime, sh.Istransferred, sh.transferredTypeId, sh.markAsRead, sh.IsSessionClosed, sh.customerNumber,sh.calledNumber, sh.ticketId, sh.supervisorName, sh.createdAt, sh.updatedAt, 
             					sd.AgentId, sd.AgentSkillId, sd.IsBot, sd.BotId, sd.QueueId ,'Sms',sh.SMSHistoryId,'' transferredByName,sh.SentimentalScore,transferredTo
             			FROM 	tb_SMSHistory 			sh
             			JOIN 	tb_SMSDurationHistory 	sd 	on sh.SMSHistoryId 	= sd.SMSHistoryId
             			LEFT JOIN 	temp_userid			U	ON sd.AgentId		= U.UserId
             			where 	sh.domainId = p_domainId
             			and	 	(sh.dispositionId		= p_dispositionId  or IFNULL(p_dispositionId,0) =0)
             			and  	cast(sh.updatedAt as date)  BETWEEN v_fromDate AND v_toDate 
             			AND 	(sh.IsSessionClosed = 1 OR ifnull(sd.IsBot,0) = 1)
                         AND 	(IFNULL(p_UserId,0) = 0 OR (p_UserId IS NOT NULL AND U.UserId IS NOT NULL))
             			order by sh.updatedAt desc LIMIT 0, p_limit;
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
             		END IF; 
                           
             		if exists(select 1 from temp_channeltype where channelType = 'Whatsapp' limit 1 ) 
                     then
            			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
             			insert into temp_History(sessionId,sessionStartTime,sessionEndTime,WhatsappFlowSourceId,companyId,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,
             					afterwhatsappWorkTime,Istransferred,transferredTypeId,markAsRead,IsSessionClosed,customerNumber,calledNumber,ticketId,supervisorName,createdAt,updatedAt,
             					AgentId,AgentSkillId,IsBot,BotId,QueueId ,channelType,WhatsappHistoryId,transferredByName,SentimentalScore)
             			select 	wh.sessionId, wh.sessionStartTime, wh.sessionEndTime, wh.WhatsappFlowSourceId, wh.companyId, wh.domainId, wh.dispositionId, wh.Summary, wh.IsInBound, wh.assignedTo, wh.assignedBy, wh.assignedOn, 
             					wh.afterwhatsappWorkTime, wh.Istransferred, wh.transferredTypeId, wh.markAsRead, wh.IsSessionClosed, wh.customerNumber,wh.calledNumber, wh.ticketId, wh.supervisorName, wh.createdAt, wh.updatedAt, 
             					wd.AgentId, wd.AgentSkillId, wd.IsBot, wd.BotId, wd.QueueId ,'Whatsapp',wh.WhatsappHistoryId,'' transferredByName,wh.SentimentalScore
             			from 	tb_WhatsappHistory			wh
             			join 	tb_WhatsappDurationHistory 	wd 	ON wh.WhatsappHistoryId = wd.WhatsappHistoryId
             			LEFT JOIN 	temp_userid				U	ON wd.AgentId			= U.UserId
             			where 	wh.domainId 		= p_domainId
             			and		(wh.dispositionId	= p_dispositionId  or IFNULL(p_dispositionId,0) =0)
             			and 	cast(wh.updatedAt as date) BETWEEN v_fromDate AND v_toDate
             			AND 	(wh.IsSessionClosed = 1 OR ifnull(wd.IsBot,0) = 1)
                         AND 	(IFNULL(p_UserId,0) = 0 OR (p_UserId IS NOT NULL AND U.UserId IS NOT NULL))
             			order by wh.updatedAt desc LIMIT 0, p_limit;
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
             		END IF;  
                  
                  if exists(select 1 from temp_channeltype where channelType = 'Facebook' limit 1 ) 
                     then
            			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
             			insert into temp_History(sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterFacebookWorkTime,NextFlowNode
          					,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
          					,markAsReadAgent,IsSessionClosed,customerFacebookId,agentFacebookId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
          					,createdAt,updatedAt, channelType,FacebookHistoryId)
             			select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterFacebookWorkTime,fb.NextFlowNode
          					,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
          					,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerFacebookId,fb.agentFacebookId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
          					,fb.createdAt,fb.updatedAt,'Facebook',fb.FacebookHistoryId
             			from 	tb_FacebookHistory 			fb
             			LEFT JOIN 	temp_userid				U	ON fb.AgentId			= U.UserId
             			where 	fb.domainId 		= p_domainId
             			and		(fb.dispositionId	= p_dispositionId  or IFNULL(p_dispositionId,0) =0)
             			and 	cast(fb.updatedAt as date) BETWEEN v_fromDate AND v_toDate
             			AND 	(fb.IsSessionClosed = 1 OR ifnull(fb.IsBot,0) = 1)
                         AND 	(IFNULL(p_UserId,0) = 0 OR (p_UserId IS NOT NULL AND U.UserId IS NOT NULL))
             			order by fb.updatedAt desc LIMIT 0, p_limit;
                        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
             		END IF;  
         
         		IF EXISTS(select 1 from temp_channeltype where channelType = 'Instagram' limit 1 ) 
         		THEN        
         			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
         			insert into temp_History
                     (	sessionId,sessionStartTime,sessionEndTime,domainId,dispositionId,Summary,IsInBound,assignedTo,assignedBy,assignedOn,afterInstagramWorkTime,NextFlowNode
        				,Istransferred,transferredTo,transferredTypeId,transferredDate,dispositionUpdatedBy,immediateParentId,rootParentId,discardedDate,repliedDate,markAsReadSupervisor
        				,markAsReadAgent,IsSessionClosed,customerInstagramId,agentInstagramId,ticketId,AgentId,IsBot,BotId,AgentStartTime,AgentEndTime,Duration,SentimentalScore
        				,createdAt,updatedAt, channelType,InstagramHistoryId)
         			select 	sessionId,fb.sessionStartTime,fb.sessionEndTime,fb.domainId,fb.dispositionId,fb.Summary,fb.IsInBound,fb.assignedTo,fb.assignedBy,fb.assignedOn,fb.afterInstagramWorkTime,fb.NextFlowNode
         					,fb.Istransferred,fb.transferredTo,fb.transferredTypeId,fb.transferredDate,fb.dispositionUpdatedBy,fb.immediateParentId,fb.rootParentId,fb.discardedDate,fb.repliedDate,fb.markAsReadSupervisor
         					,fb.markAsReadAgent,fb.IsSessionClosed,fb.customerInstagramId,fb.agentInstagramId,fb.ticketId,fb.AgentId,fb.IsBot,fb.BotId,fb.AgentStartTime,fb.AgentEndTime,fb.Duration,fb.SentimentalScore
         					,fb.createdAt,fb.updatedAt,'Instagram',fb.InstagramHistoryId
         			from 	tb_InstagramHistory 		fb
         			LEFT JOIN 	temp_userid				U	ON fb.AgentId			= U.UserId
         			where 	fb.domainId 		= p_domainId
         			and		(fb.dispositionId	= p_dispositionId  or IFNULL(p_dispositionId,0) =0)
         			and 	cast(fb.updatedAt as date) BETWEEN v_fromDate AND v_toDate
         			AND 	(fb.IsSessionClosed = 1 OR ifnull(fb.IsBot,0) = 1)
         			AND 	(IFNULL(p_UserId,0) = 0 OR (p_UserId IS NOT NULL AND U.UserId IS NOT NULL))
         			order by fb.updatedAt desc LIMIT 0, p_limit;
         			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         		END IF;              
                   
         		DROP TEMPORARY TABLE IF EXISTS temp_History1; 	
         		CREATE TEMPORARY TABLE temp_History1                
         		SELECT ChatHistoryId,ChatDurationHistoryId,DATE_FORMAT(FROM_UNIXTIME(left(a.sessionStartTime,length(a.sessionStartTime)-3)),'%d %b %Y') as createdDate,
         		channelType,a.domainId,customerNumber,FromEmail,ToEmail,sessionId,a.updatedAt,assignedBy,ticketId,isBot,callDuration,queueDuration,afterCallWorkTime,AfterEmailWorkTime,afterSMSWorkTime,afterwhatsappWorkTime as AfterWhatsappWorkTime,summary,sessionStartTime,sessionEndTime,
         		assignedByName, dispositionName, agentStatus, transferredTo, agentRecordingUrl, transferred, callType ,b.UserName transferredByName,Istransferred,CustomerId,callBack,dispositionId
         		,assignedTo,IsInBound,AgentId,markAsRead,SentimentalScore,a.name as queueName,a.afterFacebookWorkTime,a.customerFacebookId,a.agentFacebookId,a.afterInstagramWorkTime,a.customerInstagramId,a.agentInstagramId
         		FROM temp_History a 
         		left join tb_User b on a.Istransferred = b.UserID
         		ORDER BY a.updatedAt DESC LIMIT v_offset, p_limit;         
                           
                           ALTER TABLE temp_History1 ADD COLUMN CustomerName	VARCHAR(150), ADD COLUMN agentName VARCHAR(150),ADD COLUMN transferredToName VARCHAR(150);
                           
                           DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser1; 
                           CREATE TEMPORARY TABLE temp_AvailableUser1
                           SELECT * FROM temp_AvailableUser;
                
                           DROP TEMPORARY TABLE IF EXISTS temp_AvailableUser2; 
                           CREATE TEMPORARY TABLE temp_AvailableUser2
                           SELECT * FROM temp_AvailableUser;                        
                           
                           UPDATE 	temp_History1		H
                           LEFT JOIN 	customer_contact	CC	ON H.CustomerId 		= CC.coid
                           LEFT JOIN 	temp_AvailableUser	AB	ON H.assignedBy			= AB.UserId        
                           LEFT JOIN 	temp_AvailableUser1	ATU	ON H.AgentId			= ATU.UserId        
                           LEFT JOIN 	temp_AvailableUser2	TU	ON H.transferredTo    	= TU.UserId		
                           LEFT JOIN 	disposition_status	DS	ON H.dispositionId		= DS.did
                           SET 	H.CustomerName		= CONCAT(IFNULL(CONCAT(CC.firstName,' '),''),ifnull(CC.lastName,''))                          
      					 
       						,	H.assignedByName	= AB.UserName 
       						,	H.dispositionName	= DS.dispositionName
       						,	H.agentName			= ATU.UserName
       						,	H.transferredToName	= TU.UserName; 
                             
                           SELECT 	*
                           FROM 	temp_History1;
                  END ;;
DELIMITER ;
