CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetSMSHistory`(	
  p_customerNumber	BIGINT
  ,p_calledNumber		BIGINT   
  )
BEGIN
  	SELECT 	SH.SMSHistoryId
  			,SH.sessionId
  			,SH.sessionStartTime
  			,SH.sessionEndTime
  			,SH.domainId
  			,SM.message
  			,SH.CustomerNumber
  			,SH.CalledNumber
  			,SH.dispositionId
  			,D_S.dispositionName	disposition
  			,'Sms' 				channelType 
  	FROM 	tb_SMSHistory 		SH 
 	JOIN	tb_SMSMessage		SM	ON SH.SMSHistoryId = SM.SMSHistoryId
  	left JOIN 	disposition_status	D_S	ON D_S.did	= SH.dispositionId
  	WHERE 	SH.CustomerNumber 	= p_customerNumber 
  	AND 	SH.CalledNumber 	= p_calledNumber  		    
  	AND 	SH.IsSessionClosed	= 0
      ORDER BY SH.SMSHistoryId DESC LIMIT 1;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
