CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetStatusCategorySearch`(	IN p_CompanyId 			INT,
     IN p_ProductId 			INT,
     IN p_Search 			VARCHAR(150),
     IN p_LoggedInUserID		INT)
BEGIN
 	DECLARE v_StatusCategoryId	INT;	
 	DECLARE v_CurDate  			DATETIME;
     
     SET v_CurDate	= NOW();
 
 	SELECT 	StatusCategoryId	INTO v_StatusCategoryId
 	FROM 	tb_TicketStatusCategory
 	WHERE 	CompanyId 	= p_CompanyId 
 	AND		ProductId 	= p_ProductId 
 	AND 	IsDefault	= 1;
                 
 	IF v_StatusCategoryId IS NULL
     THEN
 		INSERT INTO tb_TicketStatusCategory 
         (	CompanyId,
 			ProductId,
 			StatusCategoryName,
 			StatusCategoryDescription,
 			IsActive,
 			IsDeleted,
 			IsDefault,
 			CreatedBy,
 			CreatedDate,
 			UpdatedBy,
 			UpdatedDate
 		)
 		VALUES 
         (	p_CompanyId,
 			p_ProductId,
 			'Default Status',
 			'Common status list for all the products',
 			1,
 			0,
             1,
 			p_LoggedInUserID,
 			v_CurDate,
 			p_LoggedInUserID,
 			v_CurDate
 		);
     END IF;    
     
     SELECT StatusCategoryId
			,StatusCategoryName
 			,StatusCategoryDescription
            ,IsActive
            ,IsDefault
     FROM 	tb_TicketStatusCategory
     WHERE 	IsDeleted			= 0 
 	AND 	CompanyId 			= p_CompanyId 
 	AND		ProductId 			= p_ProductId 
 	AND 	StatusCategoryName 	LIKE  CONCAT('%', p_Search, '%')
     ORDER BY StatusCategoryId DESC;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
