CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetStoreConnection`(	 
    p_domainId			INT	  
    ,p_conId  			INT)
BEGIN
   	SELECT 	SC.conId
 		,	SC.domainId
 		,	SC.shopDomain 		
 		,	SC.isConnected
 		,	SC.connectionName
 		,	REPLACE(SC.connectorName,'_',' ')	AS connectorName
 		,	SC.token
 		,   SC.syncStatus			
 		,   SC.contactSyncDetails
 		,   SC.pwd        
 		,   SC.userName
 		,	SC.syncTime
 		,	SC.scriptId			
 		,   SC.botData 			
 		,   SC.chatWidgetStatus 	
 		,   SC.contactSyncType
 		,   SC.StoreConnectionId
 		,	SC.settings
   	FROM 	tb_StoreConnection SC
   	WHERE 	domainId= p_domainId
   	AND 	conId   = p_conId
	AND    isConnected =1;    
 END ;;
