CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketApproval`(
    p_TicketId 		 INT,
    p_CompanyId		 INT,
    p_ProductId		 INT)
BEGIN
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	select 
    		TA.TicketApprovalId,
     		TA.TicketId,
            TA.CompanyId,
            TA.ProductId,
    		TA.`subject`,
            TA.IsCancelled as 'ApprovalCancelled',
    		TA.AdditionalDetails,
            TM.ApprovalCancelComments,
            TA.ApprovedById,
            TA.CreatedDate,
    		TM.ApprovingUserId,
    		TM.CreatedBy,
    		TM.IsApproved,
    		TM.IsCancelled,
    		TU.UserName
     from 	tb_TicketApproval 			 TA
     JOIN 	tb_TicketApprovalUserMapping TM on TA.TicketApprovalId	=	TM.TicketApprovalId
     JOIN   tb_TicketUser				 TU on TU.UserId			=	TM.ApprovingUserId
     where 	TA.TicketId			=	p_TicketId
     AND 	TA.CompanyId 		= 	p_CompanyId
     AND 	TA.ProductId 		= 	p_ProductId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
