CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketAutoAssignRuleById`(	p_TicketAutoAssignRuleId	BIGINT
     	,p_CompanyId 				INT
     	,p_ProductId 				INT)
BEGIN  
     	DECLARE v_TicketAutoAssignRuleId	BIGINT;
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
   	SELECT 	TicketAutoAssignRuleId INTO v_TicketAutoAssignRuleId 
   	FROM 	tb_TicketAutoAssignRule AAR
   	WHERE 	TicketAutoAssignRuleId = p_TicketAutoAssignRuleId
       AND 	IsActive 	= 1
   	AND 	IsDeleted 	= 0;
   
     	SELECT 	TicketAutoAssignRuleId
     			,RuleName
     			,RuleDescription
     			,IsRoundRobin
     			,IsThreshold
     			,Threshold
     			,GroupId
                ,UserId
     			,IsActive
     			,IsDeleted
     			,CompanyId
     			,ProductId
         FROM 	tb_TicketAutoAssignRule AAR
         WHERE 	TicketAutoAssignRuleId = v_TicketAutoAssignRuleId;
     
     	SELECT 	TicketAutoAssignAllConditionId			
     			,AllFieldTypeId
     			,AllOperatorTypeId
     			,AllFieldValues
         FROM 	tb_TicketAutoAssignAllCondition 
         WHERE 	TicketAutoAssignRuleId = v_TicketAutoAssignRuleId;
         
     	SELECT 	TicketAutoAssignAnyConditionId			
     			,AnyFieldTypeId
     			,AnyOperatorTypeId
     			,AnyFieldValues
         FROM 	tb_TicketAutoAssignAnyCondition 
         WHERE 	TicketAutoAssignRuleId = v_TicketAutoAssignRuleId; 
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      END ;;
DELIMITER ;
