CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketAutoAssignRuleList`( 
    p_CompanyId 				INT
    ,p_ProductId 				INT)
BEGIN 
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    	SELECT 	T.TicketAutoAssignRuleId
   		,	T.RuleName
   		,	T.RuleDescription
   		,	U.UserName			LastModifiedBy
   		,	T.UpdatedDate		LastModifiedDate
   		,	T.IsActive	
    	FROM 	tb_TicketAutoAssignRule T
        LEFT JOIN tb_TicketUser			U	ON T.UpdatedBy = U.UserId
    	WHERE 	T.CompanyId		= p_CompanyId
    	AND		T.ProductId		= p_ProductId    
    	AND 	T.IsDeleted 	= 0;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
