CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketBusinessHoursTimings`(
   p_companyId 		INT,
   p_productId 		INT,
   p_BusinessHoursId 	INT
   )
BEGIN
   	SELECT a.BusinessHoursId,
   		   a.`Name`,
   		   a.`Description`,
   		   a.`Timezone`, 
             a.IsDefault,
   		   b.BusinessHoursTimingsId,
   		   b.BusinessDayTypeId,       
   		   c.TypeCodeName		BusinessDay,
   		   b.FromHours,
   		   b.FromAMPM,
   		   b.ToHours,
   		   b.ToAMPM,
   		   b.IsDayOff           
   	FROM 	tb_TicketBusinessHours 			a
   	JOIN 	tb_TicketBusinessHoursTimings 	b 	ON 	a.BusinessHoursId 	= b.BusinessHoursId
   	JOIN 	TypeCode 						c 	ON 	b.BusinessDayTypeId = c.TypeCodeID
   												AND	c.TypeGroupID 		= 1104 
                                                   AND	c.IsActive			= 1
   	WHERE 	a.CompanyId				= p_companyId
       AND		a.ProductId				= p_productId
   	AND		a.IsDeleted				= 0
   	AND		IFNULL(b.IsDeleted,0)	= 0
       ORDER by SortOrder;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
