CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketComment`(	p_CompanyId 		int,
     	p_ProductId 		int,
        p_TicketId			BIGINT
    )
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        SELECT C.TicketCommentsId
    		,	C.TicketId
    		,	C.Comments
    		,	C.ParentTicketCommentsId	
    		, 	U.UserName	
        FROM 	tb_TicketComments	C
        LEFT JOIN tb_TicketUser		U	ON 	U.UserId = C.UpdatedBy									
        WHERE 	C.TicketId 	= p_TicketId
        AND	C.IsDeleted 	= 0
        ORDER BY C.TicketCommentsId DESC;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
