CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketContactField`( 
         IN p_CompanyId 				INT,
         IN p_ProductId 				INT
     )
BEGIN 
        DECLARE v_FieldCategoryTypeId 	INT;
    	DECLARE	v_CurDate				DATETIME;
         
         SET v_CurDate = NOW();
         
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         SELECT 	FieldCategoryTypeId INTO v_FieldCategoryTypeId
         FROM  	tb_TicketField
         WHERE  	FieldCategoryTypeId = 1109002
         AND		CompanyId 			= p_CompanyId
         AND		ProductId 			= p_ProductId
         AND		IsDefault			= 1	limit 1;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         IF v_FieldCategoryTypeId IS NULL 
         THEN     
    		insert into tb_TicketField
                   (FieldName, 					
                    FieldDescription, 
                    TicketLayoutId, 
                    FieldCategoryTypeId, 
                    APIName, 
                    FieldTypeId, 
                    IsActive, 
                    IsRequired, 
                    IsDefault, 
                    DefaultValue, 
                    MaximunLength, 
                    IsDeleted, 
                    CompanyId, 
                    ProductId, 
                    CreatedBy, 
                    CreatedDate, 
                    UpdatedBy, 
                    UpdatedDate)
             select
     			   FieldName, 
                    FieldDescription, 
                    0,
                    FieldCategoryTypeId, 
                    APIName, 
                    FieldTypeId, 
                    IsActive, 
                    IsRequired, 
                    IsDefault,
                    '',
                    0,
                    0,
                    p_CompanyId, 
                    p_ProductId, 
                    CreatedBy, 
                    v_CurDate, 
                    UpdatedBy, 
                    v_CurDate
              from  tb_TicketFieldTemplate
              where FieldCategoryTypeId = 1109002;
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         END IF;
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    	SELECT 	TicketFieldId, 
    			FieldName, 
    			FieldDescription, 
    			FieldCategoryTypeId, 
    			APIName, 
    			FieldTypeId, 
    			IsActive, 
    			IsRequired, 
    			IsDefault, 
    			DefaultValue, 
    			MaximunLength, 
    			IsDeleted, 
    			CompanyId, 
    			ProductId
    	FROM   tb_TicketField
    	WHERE  FieldCategoryTypeId = 1109002
    	AND    CompanyId 		   = p_CompanyId
    	AND    ProductId 		   = p_ProductId
        AND    IsDeleted           = 0
        order by IsDefault asc;    
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END ;;
DELIMITER ;
