CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketFiles`(
    p_TicketId 			INT,
    p_CompanyId		 	INT,
    p_ProductId		 	INT
    )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	  select 
   			 TL.TicketFilesId,
   			 TL.TicketId,
   			 TL.FilePath,
   			 TL.FileName,
               TL.FileSize, 
   			 TL.CreatedBy,
   			 TL.CreatedDate,
                TL.UpdatedBy,
                TL.UpdatedDate
   	  from  tb_TicketFiles TL
   	  where TL.TicketId		=	p_TicketId
   	  and   TL.IsDeleted	=   0;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
