CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketForEmailNotification`()
BEGIN	
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       	DROP TEMPORARY TABLE IF EXISTS Temp_TicketDetails;
       	CREATE TEMPORARY TABLE Temp_TicketDetails       
       	SELECT 	TD.TicketId
			,	TD.RequestorId
			,	TD.TicketDescription
			,	TD.TicketSubject 
			,	TD.AssignedToAgentId
			,	TD.TicketAssociateCustContact
			,	TD.PriorityId
			,   TL.LogDetails
			,	TL.CompanyId
			,	TT.TicketTypeName
     	FROM 	tb_TicketDetails    TD
     	JOIN    tb_TicketLogDetail  TL ON TD.TicketId = TL.TicketId
        left join tb_TicketType 	TT on TD.TicketTypeId = TT.TicketTypeId
     	WHERE 	TL.IsEmailNotificationSent = 0;    
       
		SELECT 	TD.TicketId
			,	TD.LogDetails
			,	TD.RequestorId
			,	Req_TU.UserName 					RequestorName
			,	Req_TU.emailId						RequestorEmail
			,	TD.TicketDescription
			,	TD.TicketSubject 
			,	TD.AssignedToAgentId
			,	Ass_TU.UserName 					AssignedToAgentName
			,	Ass_TU.emailId						AssignedToAgentEmail
			,	TD.TicketAssociateCustContact
			,	C_C.coid							TicketContactId
			,	CONCAT(C_C.FirstName,' ', C_C.lastName)	CustomerName        
			,	C_C.email									CustomerEmail        
			,	PRI_TC.TypeCode        			Priority
			,	TD.CompanyId
            ,	TD.TicketTypeName
		FROM 	Temp_TicketDetails 	TD
		LEFT JOIN 	tb_User			Req_TU	ON TD.RequestorId 		= Req_TU.UserId
		LEFT JOIN tb_User			Ass_TU	ON TD.AssignedToAgentId = Ass_TU.UserId
		LEFT JOIN customer_contact	C_C		ON C_C.coid				= TD.TicketAssociateCustContact
		LEFT JOIN TypeCode			PRI_TC	ON TD.PriorityId		= PRI_TC.TypeCodeID;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     	UPDATE 	tb_TicketLogDetail 	TD
     	JOIN	Temp_TicketDetails	T_TD	ON TD.TicketId = T_TD.TicketId
     	SET 	TD.IsEmailNotificationSent = 1;
         DROP TEMPORARY TABLE IF EXISTS Temp_TicketDetails;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
