DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketInfo`(
    	p_TicketId 					BIGINT
    	,p_CompanyId 				INT
    	,p_ProductId 				INT
    	,p_datefilter 				INT 
    	,p_fromdate 				VARCHAR(50)
    	,p_todate 					VARCHAR(50)
    	,p_UserNameFilter 			VARCHAR(50)
    	,p_PriorityIdFilter 		VARCHAR(50)
    	,p_TicketStatusId 			VARCHAR(50)
    	,p_TicketTypeIdFilter 		VARCHAR(50)
    	,p_AssignedToAgentIdFilter 	VARCHAR(50)
    	,p_requesterFilter 			VARCHAR(50)
    	,p_TicketCategoryId 		VARCHAR(50)
		,p_AssignedToGroupIdFilter 	VARCHAR(50)
		,p_FilterId					INT
		,p_LoggedInUserID			INT
    )
BEGIN       
   	DECLARE v_From_date 	DATE;
   	DECLARE v_to_date 		DATE;
       DECLARE v_TicketId 		BIGINT;
       DECLARE v_curDate		DATETIME DEFAULT NOW();
       
   	IF p_fromdate IS NULL THEN SET p_fromdate = '''';	END IF;
   	IF p_todate IS NULL THEN SET p_todate = '''';		END IF;
       
       SET v_TicketId = NULLIF(p_TicketId,0);
                        
                     
                
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_UserNameFilter_info; 			CREATE TEMPORARY TABLE tt_temp_UserNameFilter_info (id int auto_increment primary key, UserNameFilter varchar(250));
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_PriorityIdFilter_info; 			CREATE TEMPORARY TABLE tt_temp_PriorityIdFilter_info (id int auto_increment primary key, PriorityIdFilter INT );
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketStatusId_info; 			CREATE TEMPORARY TABLE tt_temp_TicketStatusId_info (id int auto_increment primary key, TicketStatusId INT );
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketTypeIdFilter_info; 		CREATE TEMPORARY TABLE tt_temp_TicketTypeIdFilter_info (id int auto_increment primary key, TicketTypeIdFilter INT );
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_AssignedToAgentIdFilter_info; 	CREATE TEMPORARY TABLE tt_temp_AssignedToAgentIdFilter_info (id int auto_increment primary key, AssignedToAgentIdFilter BIGINT);
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_requesterFilter_info; 			CREATE TEMPORARY TABLE tt_temp_requesterFilter_info (id int auto_increment primary key, requesterFilter LONGTEXT );
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketCategoryId_info; 			CREATE TEMPORARY TABLE tt_temp_TicketCategoryId_info (id int auto_increment primary key, TicketCategoryId INT );
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_AssignedToGroupIdFilter; 		CREATE TEMPORARY TABLE tt_temp_AssignedToGroupIdFilter(id int auto_increment primary key, AssignedToGroupId INT );
   	
   	CALL Split(p_UserNameFilter,',');										INSERT INTO tt_temp_UserNameFilter_info(UserNameFilter) select Items from tt_Split_temptable;
   	CALL Split(p_PriorityIdFilter,',');										INSERT INTO tt_temp_PriorityIdFilter_info(PriorityIdFilter) select Items from tt_Split_temptable;
   	CALL Split(p_TicketStatusId,',');										INSERT INTO tt_temp_TicketStatusId_info(TicketStatusId) select Items from tt_Split_temptable;
   	CALL Split(p_TicketTypeIdFilter,',');									INSERT INTO tt_temp_TicketTypeIdFilter_info(TicketTypeIdFilter) select Items from tt_Split_temptable;
   	CALL Split(p_AssignedToAgentIdFilter,',');								INSERT INTO tt_temp_AssignedToAgentIdFilter_info(AssignedToAgentIdFilter) select Items from tt_Split_temptable;
   	CALL Split(p_requesterFilter,',');										INSERT INTO tt_temp_requesterFilter_info(requesterFilter) select Items from tt_Split_temptable;
   	CALL Split(p_TicketCategoryId,',');										INSERT INTO tt_temp_TicketCategoryId_info(TicketCategoryId) select Items from tt_Split_temptable;
   	CALL Split(p_AssignedToGroupIdFilter,',');								INSERT INTO tt_temp_AssignedToGroupIdFilter(AssignedToGroupId) select Items from tt_Split_temptable;
                
                		
                
                		
   	DROP TEMPORARY TABLE IF EXISTS tt_Tickets;
       CREATE TEMPORARY TABLE tt_Tickets(TicketId	BIGINT);
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	IF p_FilterId = 1124001	
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0;	
	ELSEIF p_FilterId = 1124002		
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
           AND 	TD.AssignedToAgentId IS NOT NULL;    
	ELSEIF p_FilterId = 1124003		
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
           JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
           AND		TS.SLATimer		<> 1102002  ;        
   	ELSEIF p_FilterId = 1124004		
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
           JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
           AND		ResolutionDueDate < v_curDate; 
   	ELSEIF p_FilterId = 1124005		
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
  		JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
          AND		ResponseDueDate < v_curDate; 
   	ELSEIF p_FilterId = 1124006		
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
           JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
           AND 	TD.AssignedToAgentId = p_LoggedInUserID
           AND		TS.SLATimer		<> 1102002  ;  
   	ELSEIF p_FilterId = 1124007		
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
           JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
           AND 	TD.AssignedToAgentId = p_LoggedInUserID
           AND		ResolutionDueDate < v_curDate;
   	ELSEIF p_FilterId = 1124008	
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
           JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
           AND 	TD.AssignedToAgentId = p_LoggedInUserID
           AND		ResponseDueDate < v_curDate;  
   	ELSEIF p_FilterId = 1124010	
       THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
 		JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 0
 		AND 	TD.RequestorId 	= p_LoggedInUserID;                
 	ELSEIF p_FilterId = 1124012	
     THEN
   		INSERT INTO tt_Tickets(TicketId)
   		SELECT	TD.TicketId 	
   		FROM 	tb_TicketDetails	TD
 		JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
   		WHERE 	TD.TicketId 	= IFNULL(v_TicketId,TD.TicketId) 
   		AND 	TD.CompanyId 	= p_CompanyId  
   		AND 	TD.ProductId 	= p_ProductId
   		AND 	TD.IsDeleted 	= 1; 
 	END IF;              
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	select 	a.TicketId,TicketSubject,TicketStatusId,b.StatusName,a.TicketTypeId,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,
   			AssignedToGroupId,f.GroupName,AssignedToAgentId,e.UserName,a.TagId as TagId ,
   		  
   			a.CreatedDate,a.UpdatedDate as ModifiedDate,a.TicketDescription,a.TicketMode,a.TicketAssociateCustContact,
   			(	SELECT 	GROUP_CONCAT(In_TT.TagName)  
   				FROM 	tb_TicketTag 		In_TT 
   				JOIN 	tb_TicketTagMapping	In_TM	ON In_TM.TicketTagId	= In_TT.TicketTagId
   				WHERE 	In_TM.TicketId  = a.TicketId ) TagName,a.ResolutionDueDate
   	from tb_TicketDetails 		a
      JOIN tt_Tickets				t_T ON t_T.TicketId		= a.TicketId
   	left join tb_TicketStatus 	b on a.TicketStatusId = b.StatusId
   	left join tb_TicketType 	c on a.TicketTypeId = c.TicketTypeId
   	left join TypeCode 			d on a.PriorityId = d.TypeCodeID
   	left join tb_TicketUser 	e on a.AssignedToAgentId = e.UserId
   	left join tb_TicketGroup	f on a.AssignedToGroupId = f.TicketGroupId
   	left join tb_TicketContact	g on a.TicketAssociateCustContact = g.TicketContactId
   	where ((ifnull(p_UserNameFilter,'')='') 			or  EXISTS (select 1 from tt_temp_UserNameFilter_info un WHERE e.UserName COLLATE utf8mb4_unicode_ci = un.UserNameFilter))
   	and ((ifnull(p_PriorityIdFilter,'')='') 		or 	EXISTS (select 1 from tt_temp_PriorityIdFilter_info pf WHERE a.PriorityId = pf.PriorityIdFilter))
   	and ((ifnull(p_TicketStatusId,'')='') 			or 	EXISTS (select 1 from tt_temp_TicketStatusId_info ts WHERE b.StatusId  = ts.TicketStatusId))
   	and ((ifnull(p_TicketTypeIdFilter,'')='') 		or 	EXISTS (select 1 from tt_temp_TicketTypeIdFilter_info tt WHERE a.TicketTypeId  = tt.TicketTypeIdFilter))
   	and ((ifnull(p_AssignedToAgentIdFilter,'')='') 	or 	EXISTS (select 1 from tt_temp_AssignedToAgentIdFilter_info aa WHERE a.AssignedToAgentId = aa.AssignedToAgentIdFilter))
  
   	AND ((ifnull(p_AssignedToGroupIdFilter,'')='') 	or 	EXISTS (select 1 from tt_temp_AssignedToGroupIdFilter tc WHERE a.AssignedToGroupId = tc.AssignedToGroupId))                     
   	ORDER BY a.CreatedDate desc ;             
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
              
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_UserNameFilter_info; 
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_PriorityIdFilter_info; 
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketStatusId_info; 	
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketTypeIdFilter_info; 
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_AssignedToAgentIdFilter_info;
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_requesterFilter_info; 
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_TicketCategoryId_info; 
   	DROP TEMPORARY TABLE IF EXISTS tt_temp_AssignedToGroupIdFilter;
    End ;;
DELIMITER ;
