CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketInfoBasedOnId`(
   	p_TicketId 					BIGINT
   	,p_CompanyId 				INT
   	,p_ProductId 				INT
   )
Begin
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       select 	a.TicketId,
   			e.UserName,
   			a.TicketSubject,
               a.TicketDescription,
               a.TicketStatusId,
               b.StatusName,
   			a.PriorityId,
               d.TypeCode as Priority, 
   			a.AssignedToGroupId,
               h.GroupName as AssignedToGroup,
               a.AssignedToAgentId,
   			a.ResponseDueDate,
               a.ResolutionDueDate,
               a.RequestorId,
               a.RequesterName,
   			a.TagId,
               a.TicketTagIdName,
               a.TicketSourceId,
               f.TicketSource,
               a.TicketTypeId,
               c.TicketTypeName,
               a.TicketMode,
               a.CompanyId,
               i.CompanyName,
               TicketAssociateCustContact as AssociativeCustomerContact,
               concat(j.FirstName,' ',j.LastName) as AssociativeCustomerContactName,
               a.CreatedDate,
               a.UpdatedDate as ModifiedDate
  	from 			tb_TicketDetails 		a
  	left join 		tb_TicketStatus  		b  on  a.TicketStatusId 		= b.StatusId
  	left join 		tb_TicketType 	 		c  on  a.TicketTypeId   		= c.TicketTypeId
  	left join 		TypeCode         		d  on  a.PriorityId     		= d.TypeCodeID
  	left join 		tb_TicketSource  		f  on  a.TicketSourceId 		= f.TicketSourceId
  	left join 	    tb_TicketUser    		e  on  e.UserId         		= a.AssignedToAgentId
  	left join       tb_TicketGroup   		h  on  a.AssignedToGroupId		= h.TicketGroupId
  	
  	left join 	    tb_TicketCompany   	 	i  on  a.CompanyId         		= i.CompanyId
  	
     left join		customer_contact        j  on  j.coid  = a.TicketAssociateCustContact
   	where 		(TicketId = p_TicketId or ifnull(p_TicketId,0)=0)
       and 		a.CompanyId = p_CompanyId  
       and 		a.ProductId = p_ProductId
       and 		a.IsDeleted = 0;
   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
