CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketLabel`(
                p_TicketLayoutId INT,
                p_CompanyId		 INT,
                p_ProductId		 INT)
BEGIN
  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    select 	TA.TicketLabelId,
            TA.TicketFieldId,
            TA.FieldLabel,
            TA.LabelTypeId,
            TF.FieldName,
            TF.APIName,
            TF.FieldTypeId,
            TF.FieldCategoryTypeId,
            TF.IsRequired,
            TF.DefaultValue,
            TL.TicketCategoryId,
            TL.TicketLayoutStatus,
            TL.TicketLayoutId,
            TL.MaximunLength
    FROM    tb_TicketLayout TL
    JOIN 	tb_TicketField TF 		ON TF.TicketLayoutId 		= TL.TicketLayoutId
    JOIN	tb_TicketLabel TA 		ON TF.TicketFieldId  		= TA.TicketFieldId
    WHERE 	TL.TicketLayoutId	=	p_TicketLayoutId
    AND 	TL.CompanyId 		= 	p_CompanyId
    AND 	TL.ProductId 		= 	p_ProductId
    AND     TF.IsDeleted		=   0
    ORDER BY TF.IsDefault ASC;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
