CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketLayout`( 
    IN p_CompanyId INT,
    IN p_ProductId INT
    )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	L.TicketLayoutId,
 			L.LayoutName,
 			L.LayoutDescription,
 			L.TicketCategoryId,
 			L.CompanyId,
 			L.ProductId,
 			L.LayoutTypeId,
 			L.IsActive,
 			U.UserName	AS UpdatedByUser
 	FROM 	tb_TicketLayout	L
 	JOIN 	tb_TicketUser	U	ON U.UserId	= L.UpdatedBy
 	WHERE 	L.IsDeleted	= 0 
 	AND 	L.CompanyId = p_CompanyId
 	AND   	L.ProductId = p_ProductId;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
