CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketLayoutField`(
      IN p_TicketLayoutId INT,
      IN p_CompanyId INT,
      IN p_ProductId INT
  )
BEGIN
      DECLARE v_TicketLayoutId INT;
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      SELECT TicketLayoutId INTO v_TicketLayoutId
      FROM tb_TicketLayout
      WHERE TicketLayoutId = p_TicketLayoutId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      IF v_TicketLayoutId IS NOT NULL THEN
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          SELECT *
          FROM  tb_TicketField
          WHERE TicketLayoutId = v_TicketLayoutId
          AND   CompanyId = p_CompanyId
          AND   ProductId = p_ProductId;
      ELSE
          SELECT *
          FROM tb_TicketFieldTemplate
          WHERE FieldCategoryTypeId = 1108014;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      END IF;
  END ;;
DELIMITER ;
