CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketSLA`(p_SLAconditionId INT)
begin
     
     DECLARE v_SLAconditionId	INT;
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT 	SLAconditionId INTO v_SLAconditionId
     FROM 	tb_TicketSLAcondition
     WHERE 	SLAconditionId = P_SLAconditionId
     and     IsDeleted = 0;
     
   	select 	C.SLAconditionId, 
   			C.CompanyId, 
   			C.ProductId, 
   			C.SLAName, 
   			C.SLADescription, 
   			C.IsDefault, 
   			C.IsActive, 
   			C.IsDeleted, 
   			C.BusinessHoursId, 
   			C.CriticalFirtResponseTime, 
   			C.CriticalFirtResponseTimeTypeId, 
   			C.HighFirtResponseTime, 
   			C.HighFirtResponseTimeTypeId, 
   			C.MediumFirtResponseTime, 
   			C.MediumFirtResponseTimeTypeId, 
   			C.LowFirtResponseTime, 
   			C.LowFirtResponseTimeTypeId, 
   			C.CriticalResolutionTime, 
   			C.CriticalResolutionTimeTypeId, 
   			C.HighResolutionTime, 
   			C.HighResolutionTimeTypeId, 
   			C.MediumResolutionTime, 
   			C.MediumResolutionTimeTypeId, 
   			C.LowResolutionTime, 
   			C.LowResolutionTimeTypeId,
   			C.IsFirstResponseOn,
   			C.IsFirstResponseRemainderOn,
               F_REM.ResponseResolutionTypeId  FirstResponseRemainderTypeId,
               F_REM.GroupId					FirstResponseRemainderGroupId,		
               F_REM.UserId					FirstResponseRemainderUserId,
   			C.IsFirstResponseEscalationOn,
               F_RES.ResponseResolutionTypeId  FirstResponseEscalationTypeId,
               F_RES.GroupId					FirstResponseEscalationGroupId,		
               F_RES.UserId					FirstResponseEscalationUserId,            
   			C.IsResolutionOn,
   			C.IsResolutionRemainderOn,
               R_REM.ResponseResolutionTypeId  ResolutionRemainderEscalationTypeId,
               R_REM.GroupId					ResolutionRemainderEscalationGroupId,		
               R_REM.UserId					ResolutionRemainderEscalationUserId,
   			C.IsResolutionEscalationOn
   	FROM  	tb_TicketSLAcondition  			C
       LEFT JOIN 	tb_TicketSLARemainderEscalation	F_REM	ON 	C.SLAconditionId					= F_REM.SLAconditionId
  														AND F_REM.SLARemainderEscalationTypeId	= 1107001	 
       LEFT JOIN 	tb_TicketSLARemainderEscalation	F_RES	ON 	C.SLAconditionId					= F_RES.SLAconditionId
   														AND F_RES.SLARemainderEscalationTypeId	= 1107002	                                                     
       LEFT JOIN 	tb_TicketSLARemainderEscalation	R_REM	ON 	C.SLAconditionId					= R_REM.SLAconditionId
   														AND R_REM.SLARemainderEscalationTypeId	= 1107003	                                                                                                         
   	WHERE 	C.SLAconditionId = v_SLAconditionId;
   
      select SLARemainderEscalationId, 
             SLAconditionId, 
             SLARemainderEscalationTypeId, 
             ResponseResolutionTypeId, 
             GroupId, 
             UserId 
      from   tb_TicketSLARemainderEscalation 
      where  SLAconditionId = v_SLAconditionId
      AND	  SLARemainderEscalationTypeId	= 1107004; 
      
      select SLAMatchConditionId, 
   		  SLAconditionId, 
             FieldTypeId, 
             OperatorTypeId, 
             FieldValues 
      from   tb_TicketSLAMatchCondition
      where  SLAconditionId = v_SLAconditionId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetTicketSLAcondition` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketSLAcondition`(	
           IN p_CompanyId 			INT,
           IN p_ProductId 			INT,      
           IN p_Search 				VARCHAR(150),
           IN  p_LoggedInUserID		INT )
BEGIN
 	DECLARE v_SLAconditionId	INT;	
 	DECLARE v_CurDate  			DATETIME;
 	  
 	SET v_CurDate	= NOW();
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
   	SELECT 	SLAconditionId INTO v_SLAconditionId 
   	FROM 	tb_TicketSLAcondition
   	WHERE	CompanyId = p_CompanyId 
   	AND 	productId = p_ProductId 
   	AND 	IsDefault = 1 LIMIT 1;
                       
 	IF v_SLAconditionId IS NULL
 	THEN
 		INSERT INTO tb_TicketSLAcondition 
 		  (	CompanyId,
 			ProductId,
 			SLAName,
 			SLADescription,
 			IsDefault,
 			IsActive,
 			IsDeleted,
 			CreatedBy,
 			CreatedDate,
 			UpdatedBy,
 			UpdatedDate
 		)
 		VALUES 
 		  (	p_CompanyId,
 			p_ProductId,
 			'Default SLA',
 			"It's default SLA",
 			1,
 			1,
 			0,
 			p_LoggedInUserID,
 			v_CurDate,
 			p_LoggedInUserID,
 			v_CurDate
 		);
 	END IF;
           
     	SELECT SLAconditionId,
     		SLAName,
     		SLADescription,
     		IsDefault,
     		IsActive
     	FROM	tb_TicketSLAcondition
     	WHERE	IsDeleted = 0
     	AND CompanyId = p_CompanyId
     	AND productId = p_ProductId
     	AND SLAName COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p_Search, '%')
     	ORDER BY SLAconditionId DESC;
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
