CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketSnippetByTicketSnippetId`(
  p_TicketSnippetId		INT,
  p_CompanyId				INT,
  p_ProductId				INT
  )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	TS.TicketSnippetId		
              ,TS.SnippetTitle
              ,TS.SnippetDescription
              ,TC.TicketCategoryId	
              ,TC.CategoryDescription	
              ,TS.IsActive			            			
      FROM 	tb_TicketSnippet	TS
      JOIN 	tb_TicketCategory	TC	ON TS.TicketCategoryId = TC.TicketCategoryId
      WHERE 	TS.TicketSnippetId 	= p_TicketSnippetId
      and     TS.CompanyId		= p_CompanyId
      AND 	TS.ProductId		= p_ProductId
      AND 	TS.IsDeleted		= 0;	
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
