CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketSnippetList`(	 p_CompanyId 		INT
       ,p_ProductId 		INT     
  )
BEGIN
  	DECLARE v_CurDate		DATETIME;
      
      SET v_CurDate	= NOW();
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	IF NOT EXISTS (	SELECT 	1
  					FROM 	tb_TicketCategory 
  					WHERE 	CompanyId 	= p_CompanyId
  					AND		ProductId	= p_ProductId	)    
  	THEN		
  		INSERT INTO tb_TicketCategory
          (	CategoryDescription
  			,CompanyId
  			,ProductId
  			,IsDefault
  			,IsDeleted
  			,CreatedBy
  			,CreatedDate
  			,UpdatedBy
  			,UpdatedDate
          )
          VALUES
          (	'Default'
  			,p_CompanyId
  			,p_ProductId
              ,1
              ,0
              ,0
              ,v_CurDate
              ,0
              ,v_CurDate        
          );
      END IF;
      
  	SELECT 	TS.TicketSnippetId		
              ,TS.SnippetTitle		
              ,TC.TicketCategoryId	
              ,TC.CategoryDescription	
              ,TS.IsActive			
              ,TS.IsDeleted			
      FROM 	tb_TicketSnippet	TS
      JOIN 	tb_TicketCategory	TC	ON TS.TicketCategoryId = TC.TicketCategoryId
      WHERE 	TS.CompanyId 	= p_CompanyId
      AND		TS.ProductId	= p_ProductId
      AND     TS.IsDeleted    = 0;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
