CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketStatus`(
    	
        p_CompanyId 			INT,
        p_ProductId  			INT
        )
BEGIN
   	DECLARE v_StatusId		INT;
       DECLARE v_CurDate		DATETIME; 
       
       SET v_CurDate = NOW();  
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	StatusId INTO v_StatusId		
       FROM 	tb_TicketStatus
       WHERE 	CompanyId 	= p_CompanyId
       AND     ProductId  	= p_ProductId
       AND 	IsDefault	= 1
       LIMIT 1;
        
        IF v_StatusId IS NULL
        THEN
   		INSERT INTO tb_TicketStatus (              
                 StatusName,		
                 IsDefault,
                 SLATimer,
                 StatusColor,
                 IsActive,
                 IsDeleted,
                 OrderNo,
                 CompanyId,
                 ProductId,
                 CreatedBy,
                 CreatedDate,
                 UpdatedBy,
                 UpdatedDate
             )
   		SELECT 	StatusName 		
   				,1				IsDefault				
   				,SLATimer 			
   				,StatusColor		
   				,1				IsActive
                   ,0				IsDeleted
   				,OrderNo
                   ,p_CompanyId
                   ,p_ProductId
                   ,0
                   ,v_CurDate
                   ,0
                   ,v_CurDate
   		FROM 	tb_TicketStatusTemplate;
   	END IF;
        
       SELECT 	StatusId
   		,	StatusName
   		,	IsDefault
   		,	SLATimer
   		,	StatusColor
   		,	IsActive
   		,	IsDeleted
   		,	OrderNo
   		,	CompanyId
   		,	ProductId
       FROM  	tb_TicketStatus 
       where 	CompanyId 	= p_CompanyId
       AND 	ProductId  	= p_ProductId and IsDeleted=0 order by OrderNo;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
