CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketStatusByStatusCategoryId`(
    p_CompanyId 		INT
    ,p_ProductId 		INT
    ,p_StatusCategoryId INT
     )
BEGIN		
   	DECLARE v_StatusCategoryId INT;
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       SELECT StatusCategoryId	INTO v_StatusCategoryId
       FROM 	tb_TicketStatus
       WHERE 	StatusCategoryId = p_StatusCategoryId LIMIT 1;
       
        IF v_StatusCategoryId IS NOT NULL
        THEN
    		SELECT 	StatusId 			
    				,StatusCategoryId 	
                    ,StatusName 		
                    ,IsDefault			
                    ,SLATimer 			
                    ,StatusColor		
                    ,IsActive	
                    ,IsDeleted
    		FROM 	tb_TicketStatus TSC	
    		WHERE	TSC.StatusCategoryId 	= v_StatusCategoryId;    
    	ELSE
    		SELECT 	Null			StatusId
    				,Null			StatusCategoryId 	
                    ,TypeCode		StatusName 		
                    ,1				IsDefault				
                    ,'On'			SLATimer 			
                    ,TypeCodeName	StatusColor		
                    ,1				IsActive		
                    ,0				IsDeleted
            FROM 	`TypeCode` 
            WHERE 	TypeGroupID = 1100;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        END IF;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
