CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketTag`(
  p_TicketTagId 	INT
  ,p_CompanyId	INT
  ,p_ProductId	INT)
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       IF p_TicketTagId = 0 THEN
           SELECT TicketTagId,
                  CompanyId,
                  ProductId,
                  TagName,
                  TagDescription,
                  IsActive
           FROM 	tb_TicketTag 	TT         
           where 	IsDeleted	= 0
           AND 	CompanyId	= p_CompanyId
           AND	ProductId	= p_ProductId;
       ELSE
           SELECT TicketTagId,
                  CompanyId,
                  ProductId,
                  TagName,
                  TagDescription,
                  IsActive
           FROM 	tb_TicketTag
           WHERE 	TicketTagId = p_TicketTagId 
           AND 	IsDeleted	= 0;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       END IF;
   END ;;
DELIMITER ;
