CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketTagSearch`(
     IN p_CompanyId INT,
     IN p_ProductId INT,
     IN p_TicketTagSearch varchar(50)
 )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     IF p_TicketTagSearch = '' OR p_TicketTagSearch IS NULL THEN
         SELECT TicketTagId,
 			   CompanyId,
                ProductId,
                TagName,
                TagDescription,
                IsActive
         FROM tb_TicketTag
         WHERE CompanyId = p_CompanyId
             AND ProductId = p_ProductId;
     ELSE
         SELECT TicketTagId,
 			   CompanyId,
                ProductId,
                TagName,
                TagDescription,
                IsActive
         FROM tb_TicketTag
         WHERE CompanyId = p_CompanyId
             AND ProductId = p_ProductId
             AND TagName LIKE CONCAT('%', p_TicketTagSearch, '%');
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END IF;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
