CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetTicketTriggerup_GetTicketTrigger`(
  p_CompanyId 				INT
  ,p_ProductId 				INT
  ,p_TicketTriggerId			BIGINT )
BEGIN   
  	DECLARE v_TicketTriggerId			BIGINT;
   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	TicketTriggerId	INTO v_TicketTriggerId    
      FROM 	tb_TicketTrigger T
      WHERE 	T.TicketTriggerId 	= p_TicketTriggerId
      AND		T.IsActive			= 1
      AND 	T.IsDeleted 		= 0;
      
  	SELECT 	TicketTriggerId
  		,	RuleName
  		,	RuleDescription        
      FROM 	tb_TicketTrigger T
      WHERE 	T.TicketTriggerId 	= v_TicketTriggerId;
      
      SELECT 	C.TicketTriggerAllConditionId
  		,	C.TicketTriggerId
  		,	C.FieldTypeId
  		,	C.OperatorTypeId
  		,	C.FieldValues
      FROM 	tb_TicketTriggerAllCondition	C
      WHERE 	C.TicketTriggerId 	= v_TicketTriggerId;
      
      SELECT 	C.TicketTriggerAnyConditionId
  		,	C.TicketTriggerId
  		,	C.AnyFieldTypeId
  		,	C.AnyOperatorTypeId
  		,	C.AnyFieldValues
      FROM 	tb_TicketTriggerAnyCondition    C	
      WHERE	C.TicketTriggerId = v_TicketTriggerId;   
     
      SELECT 	A.TicketTriggerActionId
  		,	A.TicketTriggerId
  		,	A.ActionTypeId
  		,	A.ActionOperatorId
  		,	A.ActionValues
      FROM 	tb_TicketTriggerAction  A	    
      WHERE 	A.TicketTriggerId 	= p_TicketTriggerId;  
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

   END ;;
