CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketType`(
  p_TicketTypeId 	INT
  ,p_CompanyId	INT
  ,p_ProductId	INT)
BEGIN
 	DECLARE v_TicketTypeId 	INT;
     DECLARE v_CurDate		DATETIME;
     
     SET v_CurDate = NOW();
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT 	TicketTypeId INTO v_TicketTypeId
 	FROM 	tb_TicketType
 	WHERE 	CompanyId	= p_CompanyId
 	AND		ProductId	= p_ProductId
 	AND 	IsDefault	= 1
     LIMIT 1;
                 
 	IF v_TicketTypeId  IS NULL
     THEN
 		INSERT INTO tb_TicketType
         (	CompanyId
 			,ProductId
 			,TicketTypeName
 			,TicketTypeDescription
 			,IsDefault
 			,IsActive
 			,IsDeleted
 			,CreatedBy
 			,CreatedDate
 			,UpdatedBy
 			,UpdatedDate        
         )
         SELECT         
 			p_CompanyId
 			,p_ProductId
             ,TypeCode
             ,TypeCodeName
             ,1
             ,1
             ,0
             ,0
             ,v_CurDate
             ,0
             ,v_CurDate
         FROM 	TypeCode 
         WHERE 	TypeGroupID = 1122;
     END IF;
     
  	SELECT TicketTypeId,
  		   companyId,
  			productId,
  			TicketTypeName,
  			TicketTypeDescription,
  			IsDefault,
  			IsActive
  	FROM 	tb_TicketType
  	WHERE 	IsDeleted=0 
  	AND 	(IFNULL(p_TicketTypeId, 0) = 0 OR TicketTypeId = p_TicketTypeId)
  	AND 	CompanyId	= p_CompanyId
  	AND		ProductId	= p_ProductId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_GetTicketTypeSearch` */;
