CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketTypeSearch`(
     IN p_CompanyId INT,
     IN p_ProductId INT,
     IN p_TicketTypeNameSearch varchar(50)
 )
BEGIN
     IF p_TicketTypeNameSearch = '' OR p_TicketTypeNameSearch IS NULL THEN
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         SELECT TicketTypeId,
 			   CompanyId,
                ProductId,
                TicketTypeName,
                TicketTypeDescription,
                IsDefault,
                IsActive
         FROM tb_TicketType
         WHERE CompanyId = p_CompanyId
             AND ProductId = p_ProductId;
     ELSE
         SELECT TicketTypeId,
 			   CompanyId,
                ProductId,
                TicketTypeName,
                TicketTypeDescription,
                IsDefault,
                IsActive
         FROM tb_TicketType
         WHERE CompanyId = p_CompanyId
             AND ProductId = p_ProductId
             AND TicketTypeName LIKE CONCAT('%', p_TicketTypeNameSearch, '%');
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     END IF;
 END ;;
DELIMITER ;
