CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetTicketUserViewComments`( 
 p_TicketApprovalId 		 BIGINT,
 p_TicketId		 		 BIGINT,
 p_CompanyId		 	     INT,
 p_ProductId				 INT,
 p_ApprovingUserId		 INT
 )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  select 
 		TA.TicketApprovalId,
  		TA.TicketId,
         TA.CompanyId,
         TA.ProductId,
         TA.ApprovingUserId,
 		TA.IsCancelled,
         TA.ApprovalCancelComments
  from 	tb_TicketApprovalUserMapping TA
  where 	TA.TicketApprovalId				=	p_TicketApprovalId
  and    TA.TicketId						=	p_TicketId
  AND 	TA.CompanyId 					= 	p_CompanyId
  AND 	TA.ProductId 					= 	p_ProductId
  AND 	TA.ApprovingUserId 				= 	p_ApprovingUserId;
  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
