CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetUserConcurrentChat`( p_domainId		INT)
BEGIN
	SELECT 	U.UserID
		,	U.ext
		, 	U.domainId
		, 	U.roleid 
        ,	RP.rid		AS RoutingProfileId	
        ,	RP.`name`	AS RoutingProfileName
		,	RP.concurrentChat    
	FROM 	tb_User			U
	JOIN 	routing_profile	RP	ON U.routing_profile_id = RP.rid
	WHERE 	U.domainId	= p_domainId;
END ;;
