CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetUserCustomerDetails`(	p_ext 			INT
 	,p_coid			INT
 	,p_domainid 	INT      
 )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	U.UserID
 		,	U.UserName
         ,	U.ext
         ,	ReportToU.UserID		ReportToUserId
         ,	ReportToU.UserName		ReportToUserName
         ,	ReportToU.ext			ReportToExt
     FROM 	tb_User 	U 
     LEFT JOIN tb_User 	ReportToU 	ON ReportToU.UserID = U.report_to_UserID
     WHERE  	U.domainId  = p_domainid
     AND		U.ext		= p_ext;
     
     SELECT 	c_c.firstName
 		,	c_c.lastName
     FROM 	customer_contact c_c    
     WHERE 	c_c.coid	= p_coid;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
