CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetUserId`(
  p_ext 		INT,
  p_domainId 	INT
   )
BEGIN
	DECLARE v_UserID		BIGINT;
	DECLARE v_report_UserID BIGINT;
    
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	SELECT UserID	INTO v_UserID
	FROM 	tb_User
	WHERE 	domainId 	= p_domainId
	AND 	ext 		= p_ext;	


    
    SELECT 	UserID
		,	UserName
        ,	ext
        ,	domainId
   	FROM 	tb_User
  	WHERE 	domainId 	= p_domainId
    AND 	UserID 		<> v_UserID;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
