CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getVideoCallConfiguration`(
 p_domainId					INT	
 )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
 	SELECT 	VCC.domainId
 		,	VCC.isLinkExpiry
 		,	VCC.expiryUnit
 		,	VCC.expiryUnitType
 		,	VCC.isScreenShare
 		,	VCC.isCoBrowser
 		,	VCC.isFaceDocVerification
 		,	VCC.isVirtualBackground
 		,	VCC.emailAddress
 		,	VCC.emailSubject
 		,	VCC.emailMessage
 		,	VCC.smsNumber
