     FROM 	tb_videoCallConfiguration	VCC
     LEFT JOIN 	tb_virtualBackground	VB	ON VB.virtualBackgroundId = VCC.virtualBackgroundId
     WHERE 	VCC.domainId = p_domainId;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
