CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetVoiceAgentDetails_ttt`(	
  	p_DomainId		INT
  	,p_QueueId		INT
  	,p_Skills		VARCHAR(1000)
   )
BEGIN
   	DECLARE v_Skills		VARCHAR(1000);
   	  
   	SET v_Skills = IFNULL(p_Skills,'');
   	  
   	DROP TEMPORARY TABLE IF EXISTS tt_skilledAgent;
   	CREATE TEMPORARY TABLE tt_skilledAgent(UserID	BIGINT, skillMatch TINYINT);
              
      	IF v_Skills <> ''
      	THEN
      		CALL SplitWithSlNo(v_Skills,',');
      		
      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      		INSERT INTO tt_skilledAgent(UserID, skillMatch)
      		SELECT 	usid, COUNT(1) skillMatch 
      		FROM 	tt_Split_temptable 	TT
      		JOIN	skills				S	ON 	TT.items collate utf8mb4_unicode_ci = S.skill_name	
      										AND	S.domainId	= p_DomainId
      		JOIN 	skillMapping		SM	ON 	SM.skid		= S.sid
      										AND	SM.domainId	= S.domainId
      		GROUP BY usid;
      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      		
      		DROP TEMPORARY TABLE IF EXISTS tt_Split_temptable; 
      	END IF; 
              
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT 	JSON_OBJECT("agent_extn",U.ext			
  						, 	"agent_name",U.UserName		
  						, 	"agent_skills", ((select JSON_ARRAYAGG(JSON_OBJECT("Skid",Skid,"value",ss.skill_name))AA 
  												from skillMapping SK 
  												join skills ss on ss.sid collate utf8mb4_unicode_ci = SK.Skid and ss.domainId = SK.domainId
  												and U.UserID = SK.usid where SK.domainId = p_DomainId )) 
  						,	'userId',CAST(U.UserID as CHAR(50))
  						,	"email",U.emailId
  						, 	"agent_status",A_S.statusName	
  						,	"agent_statusId",A_S.aid
  						,	"isVoice",U.isVoice
  						,	"isVoiceCallTransfer",A_S.isVoiceCallTransfer
  						,	"routingMethod",	CASE 	WHEN RP.routingMethod = 'Skill Based Routing' 	then 2 
  														WHEN RP.routingMethod = 'Long wait time Based Routing' 	then 1 END
  						,	"delay", R_MAP.delay_in_seconds
  						) AgentDetails	
  		FROM 	tb_User						U        
  		JOIN 	agent_status				A_S		ON 	A_S.aid			= U.StatusID
  													AND	A_S.domainId	= U.domainId
  													AND A_S.aid   		= U.StatusID
  													
  		LEFT JOIN	routingqueueprofilemapping	R_MAP	ON 	R_MAP.rqmid		= U.routing_profile_id
  													AND	R_MAP.domainId	= U.domainId
  													AND	R_MAP.qid		= p_QueueId
  													AND R_MAP.voice     = 1
  		LEFT JOIN 	routing_profile 				RP	ON 	RP.rid			= R_MAP.rqmid
  													AND	RP.domainId		= R_MAP.domainId
  		LEFT JOIN tt_skilledAgent			SA		ON SA.UserID		collate	utf8mb4_unicode_ci  = U.UserID	
  		WHERE 	U.domainId				= p_DomainId
  		AND 	U.roleid 				IN (3,5,6)  
  		AND 	U.voice					= 1 
  		AND 	U.isAvailableForVoice	= 1
  		 AND 	U.inboundCall			= 1
  		 AND 	A_S.isVoice 			= 1
  		 AND 	A_S.isVoiceCallTransfer = 0
  		
  		ORDER BY  SA.skillMatch DESC, R_MAP.priority ASC, U.roleid DESC,U.updatedAt ASC
  		LIMIT 1;
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
