CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetWebsiteScraper`(
     p_domainId				INT 
   ,p_web_id                INT
   ,p_offset			    INT    
   ,p_limit				    INT   
   )
BEGIN
	DECLARE v_offset				INT;
	DECLARE v_web_id			 VARCHAR(10);
    
    
  	SET v_offset = p_offset * p_limit;

  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   	SELECT 	web_id
  		, 	websiteId
  		, 	websiteUrl
  		, 	baseName
  		, 	discription        
  		,	(	SELECT 	COUNT(ChatCategoryId)  
   				FROM 	tb_ChatCategory 
   				WHERE 	web_id = WS.web_id )	AS CategoryCount
   		,	(	SELECT 	COUNT(ChatArticleId)	
   				FROM 	tb_ChatArticle 
   				WHERE 	web_id = WS.web_id)		AS ArticlesCount
  		,	CompanyType
       FROM 	websiteScraper WS
       WHERE 	domainId = p_domainId
       and     (IFNULL(p_web_id,0)=0 or web_id = p_web_id);
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
