CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetWhatsappConfigurationDetails`(	
	p_WhatsappConfigurationId	INT
 	,p_domainId					INT
 )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 	SELECT 	WC.WhatsappConfigurationId
			, 	WC.domainId
			, 	WC.profilePicture
			, 	WC.businessName
			, 	WC.aboutBusiness
			,	WC.planId
			, 	WC.isBot
			,	WC.isBotPurchased
			, 	WC.whatsappFlowId
			,	CFH.templateName	AS whatsappFlow
			, 	WC.whatsappNumber
			, 	WC.Industry
			, 	WC.businessAddress
			, 	WC.contactEmail
			, 	WC.websiteURL1
			, 	WC.websiteURL2
			, 	WC.isDisabled 
			,   WC.isConnector
			,   WC.connectorName
			,   WC.storeName
			,	WC.callBackToggle
			,	WC.callBackForm
			,	WC.notifyAdmin
			,	WC.createdBy
			,	WC.updatedBy
			,	WC.purchasedat
			,	WO.notificationMessages
			,	WO.companyLogo
			,	WO.businessInformation
			,	WO.statusMessage
			,	WO.address
			,	WO.emailID
			,	WO.customerOptIn
			,	WO.pricing
			,	WO.whatsAppBusinessSolutionUseCases
			,	WO.companyProfile
			,	WO.locationOfCompanyHeadquarters
            ,	WC.knowledgeBaseId
            ,	WC.isRegistered
			,	WC.is2faEnabled
			,	WC.isVerifiedCode
     FROM 	tb_WhatsappConfiguration	WC
     LEFT JOIN chatFlowHistory			CFH	ON 	WC.whatsappFlowId 	= CFH.chatFlowId
 											AND WC.domainId			= CFH.domainId
	 LEFT JOIN ccaas_whatsapp_onboarding_details_confirmation WO ON WC.WhatsappConfigurationId = WO.fk_WhatsappConfigurationId
     WHERE 	WhatsappConfigurationId = p_WhatsappConfigurationId
     AND 	WC.domainId				= p_domainId;    
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
