CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetWhatsappDidPurchaseByDomainID`(	  p_domainId	INT
 )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	select 	b.web_id
 		,	b.baseName
         ,	b.websiteId
         ,	a.* 
     from 	tb_whatsappDidPurchase a 
 	left join websiteScraper b 	on 	a.domainId 			= b.domainId 
 								and a.knowledgeBasedId 	= b.web_id
 	where a.domainId = p_domainId 
     order by createdAt desc;	
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
