CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_GetWhatsappHistory`(	
    p_customerNumber	BIGINT
    ,p_calledNumber		BIGINT   
    )
BEGIN
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    	SELECT 	SH.WhatsappHistoryId
    			,SH.sessionId
    			,SH.sessionStartTime
    			,SH.sessionEndTime
    			,SH.domainId
    			,SM.message
    			,SH.CustomerNumber
    			,SH.CalledNumber
    			,SH.dispositionId
    			,D_S.dispositionName	disposition
    			,'Whatsapp' 			channelType 
    	FROM 	tb_WhatsappHistory 		SH 
   	JOIN	tb_WhatsappMessage		SM	ON SH.WhatsappHistoryId = SM.WhatsappHistoryId
    	left JOIN 	disposition_status	D_S	ON D_S.did				= SH.dispositionId
    	WHERE 	SH.CustomerNumber 	= p_customerNumber 
    	AND 	SH.CalledNumber 	= p_calledNumber  		    
    	AND 	SH.IsSessionClosed	= 0
 	ORDER BY SH.WhatsappHistoryId DESC LIMIT 1;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
