CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_GetWhatsAppTemplateById`(	
	p_Id				VARCHAR(50)
 	,p_domainId			INT	
 )
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	WAT.whatsAppTemplateId
 		,	WAT.templateName
 		,	WAT.templateType
 		,	WAT.domainId
 		,	WAT.buttonName
 		,	WAT.buttonUrl
 		,	WAT.content
 		,	WAT.number
 		,	WAT.flowId
     FROM 	tb_whatsAppTemplate WAT
  	WHERE 	flowId				= p_Id
  	AND		domainId 			= p_domainId;
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
