CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_getWorktualOAuthTokenAppDetails`(
        IN p_oauthToken VARCHAR(5000)
    )
BEGIN
 SELECT  
     CDH.appId,
     CH.domainId,
     (
         SELECT GROUP_CONCAT(DISTINCT InPAS.scopeID) 
         FROM tb_worktualAppScope InPAS 
         WHERE CDH.appId = InPAS.appId
     ) AS scopeID
 FROM tb_thirdPartyLoginCode CH
 LEFT JOIN tb_worktualApp CDH ON CDH.clientId = CH.clientId
 WHERE CH.oauthToken = p_oauthToken
 AND CDH.isDelete IS NULL;
    
    END ;;
DELIMITER ;
