CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_all_draft_chats`(
   	p_CompanyId 		INT,		
   	p_offset			INT,
   	p_limit				INT
     )
BEGIN
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   	IF EXISTS (	SELECT 	1
   				FROM 	tb_map_customer_serviceprovider
   				WHERE 	customer_company_id = p_CompanyId)
   	THEN
  		SELECT 	TC.TicketChatId, TC.SessionId, TC.CompanyId, TC.RequestedCompanyId, TC.Title, TC.Message
  		FROM 	tb_TicketChat			TC        
  		LEFT JOIN tb_TechSupportTicket	T ON TC.TicketChatId = T.TicketChatId
  		WHERE 	TC.RequestedCompanyId 	= p_CompanyId
  		AND 	T.TechSupportTicketId	IS NULL
         AND 	TC.Title  NOT IN ("Greeting", "greeting")   
          ORDER BY TC.UpdatedDate DESC LIMIT p_offset,p_limit;
   	ELSE
  		SELECT 	TC.TicketChatId, TC.SessionId, TC.CompanyId, TC.RequestedCompanyId, TC.Title, TC.Message
  		FROM 	tb_TicketChat			TC        
  		LEFT JOIN tb_TechSupportTicket	T ON TC.TicketChatId = T.TicketChatId
  		WHERE 	TC.CompanyId 	= p_CompanyId
  		AND 	T.TechSupportTicketId	IS NULL
 		AND 	TC.Title  NOT IN ("Greeting", "greeting")		
          ORDER BY TC.UpdatedDate DESC LIMIT p_offset,p_limit;
       END IF;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    END ;;
DELIMITER ;
