CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_all_ticket_count`(
  p_CompanyId 		INT
  ,p_fromdate		DATETIME
  ,p_todate			DATETIME
  )
SP: BEGIN
  	DECLARE v_isTechSupport			TINYINT;
     DECLARE v_service_company_id	INT;
     DECLARE v_todate				DATETIME;
     DECLARE v_Open					INT;
     DECLARE v_InProgress			INT;
     DECLARE v_Pending				INT;
     DECLARE v_Closed				INT;
     DECLARE v_Resolved				INT;
     DECLARE v_CurDate				DATETIME DEFAULT NOW();    
     
     SET v_todate = date_add(p_todate, INTERVAL 1 DAY);
     
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
   	IF EXISTS (	SELECT 	1
   				FROM 	tb_map_customer_serviceprovider
   				WHERE 	service_company_id = p_CompanyId)
   	THEN
  		SET v_isTechSupport = 1;
         SET v_service_company_id = p_CompanyId;
  	ELSE
  		SET v_isTechSupport = 0;
         
         SELECT 	service_company_id
         INTO 	v_service_company_id
 		FROM 	tb_map_customer_serviceprovider
 		WHERE 	customer_company_id = p_CompanyId;
  	END IF;
     
 	SET	v_Open 			= (SELECT StatusId FROM tb_TicketStatus WHERE CompanyId = v_service_company_id AND StatusName = 'Open')
 	,	v_InProgress 	= (SELECT StatusId FROM tb_TicketStatus WHERE CompanyId = v_service_company_id AND StatusName = 'InProgress')
 	,	v_Pending 		= (SELECT StatusId FROM tb_TicketStatus WHERE CompanyId = v_service_company_id AND StatusName = 'Pending')
 	,	v_Closed 		= (SELECT StatusId FROM tb_TicketStatus WHERE CompanyId = v_service_company_id AND StatusName = 'Closed')
 	,	v_Resolved 		= (SELECT StatusId FROM tb_TicketStatus WHERE CompanyId = v_service_company_id AND StatusName = 'Resolved');    
 
     IF v_isTechSupport = 1
     THEN
 		SELECT 	COUNT(1)		AS total_ticket_created
 			,	SUM(CASE WHEN T.TicketStatusId IN (v_Closed,v_Resolved) THEN 1 ELSE 0 END) 				AS ticket_resolved
 			,	SUM(CASE WHEN T.TicketStatusId IN (v_Pending,v_InProgress,v_Open) THEN 1 ELSE 0 END) 	AS ticket_pending
 			,	0	AS ticket_escalated	
 			,	0	AS ticket_reopened
 			,	SUM(CASE WHEN (ResponseDueDate < IFNULL(ResponsedDate,v_CurDate)) OR (ResolutionDueDate < IFNULL(ResolvedDate,v_CurDate)) THEN 1 ELSE 0 END) AS sla_breached_ticket
 		FROM 	tb_TechSupportTicket	T  		
 		WHERE 	T.ServiceProviderCompanyId	= p_CompanyId
 		AND 	T.CreatedDate				>= 	p_fromdate 
 		AND 	T.CreatedDate				<	v_todate;	 
 	ELSE
 		SELECT 	COUNT(1)		AS total_ticket_created
 			,	SUM(CASE WHEN T.TicketStatusId IN (v_Closed,v_Resolved) THEN 1 ELSE 0 END) 				AS ticket_resolved
 			,	SUM(CASE WHEN T.TicketStatusId IN (v_Pending,v_InProgress,v_Open) THEN 1 ELSE 0 END) 	AS ticket_pending
 			,	0	AS ticket_escalated	
 			,	0	AS ticket_reopened
 			,	SUM(CASE WHEN (ResponseDueDate < IFNULL(ResponsedDate,v_CurDate)) OR (ResolutionDueDate < IFNULL(ResolvedDate,v_CurDate)) THEN 1 ELSE 0 END) AS sla_breached_ticket
 		FROM 	tb_TechSupportTicket	T  		
 		WHERE 	T.CustomerCompanyId	= p_CompanyId
 		AND 	T.CreatedDate		>= 	p_fromdate 
 		AND 	T.CreatedDate		<	v_todate;		
 	END IF;
     
 
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
