/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_all_unclosed_tickets`(
    	p_CompanyId 		INT,			
      p_userId			INT,
    	p_offset			INT,
    	p_limit				INT
      )
SP : BEGIN
   	DECLARE v_isTechSupport				TINYINT;
   	DECLARE v_ServiceProviderCompanyId	INT;
      DECLARE v_RoleId					TINYINT;
      
      DROP TEMPORARY TABLE IF EXISTS tt_TicketGroupId;
      CREATE TEMPORARY TABLE tt_TicketGroupId(TicketGroupId		INT);

    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    	IF EXISTS (	SELECT 	1
    				FROM 	tb_map_customer_serviceprovider
    				WHERE 	customer_company_id = p_CompanyId)
    	THEN
   		SET v_isTechSupport = 0;				
   
   		SELECT 	service_company_id				
   		INTO 	v_ServiceProviderCompanyId
   		FROM 	tb_map_customer_serviceprovider
   		WHERE 	customer_company_id = p_CompanyId;
   	ELSE
   		SET v_isTechSupport = 1;							
            
    		SET	v_ServiceProviderCompanyId = p_CompanyId;		
          
          SELECT 	RoleId INTO v_RoleId					
          FROM 	tb_User
          WHERE 	UserID = p_userId;
          
  		IF v_RoleId = -2 						
          THEN
  			INSERT INTO tt_TicketGroupId(TicketGroupId)				 
  			SELECT 	U.TicketGroupId
  			FROM 	tb_TicketGroupUserMapping U			
  			WHERE 	U.UserId = p_userId;
  		END IF; 
   	END IF;

      DROP TEMPORARY TABLE IF EXISTS tt_TicketStatus;
      CREATE TEMPORARY TABLE tt_TicketStatus(StatusId INT,StatusName 	VARCHAR(150));
      INSERT INTO tt_TicketStatus(StatusId, StatusName)
   	SELECT 	StatusId, StatusName 	
   	FROM 	tb_TicketStatus S
   	WHERE 	S.CompanyId 	= v_ServiceProviderCompanyId	
   	AND 	S.StatusName	IN ('Open','InProgress','Pending','Resolved');
        
    	IF v_isTechSupport = 0 
        THEN
   		SELECT 	T.TechSupportTicketId, T.TicketSubject, T.ServiceProviderCompanyId, T.CustomerCompanyId, T.TicketChatId, S.StatusName
   			,	T.TicketDescription, d.TypeCodeName AS Priority, e.UserName AS AssignedTo, T.TicketChatId, T.ChannelTypeId, T.SessionId
   		FROM 	tb_TechSupportTicket	T 
   		LEFT JOIN tt_TicketStatus 		S 	ON T.TicketStatusId = S.StatusId        
  		LEFT JOIN TypeCode 				d 	ON T.PriorityId 	= d.TypeCodeID
  		LEFT JOIN tb_User 				e 	ON T.AssignedTo		= e.UserID
   		WHERE 	T.CustomerCompanyId	= 	p_CompanyId 		
          ORDER BY T.UpdatedDate DESC;

    	ELSEIF v_isTechSupport = 1 
        THEN
     
  		IF v_RoleId = -2 THEN	
 		
  			SELECT 	T.TechSupportTicketId, T.TicketSubject, T.ServiceProviderCompanyId, T.CustomerCompanyId, T.TicketChatId, S.StatusName
  				,	T.TicketDescription, d.TypeCodeName AS Priority, e.UserName AS AssignedTo, T.TicketChatId, T.ChannelTypeId, T.SessionId 
  			FROM 	tb_TechSupportTicket	T             
  			LEFT JOIN tt_TicketStatus 		S 	ON T.TicketStatusId = S.StatusId       
 			LEFT JOIN tt_TicketGroupId		G	ON G.TicketGroupId	= T.AssignedToGroupId            
  			LEFT JOIN TypeCode 				d 	ON T.PriorityId 	= d.TypeCodeID			        
 			LEFT JOIN tb_User 				e 	ON T.AssignedTo		= e.UserID
  			WHERE 	T.ServiceProviderCompanyId	=  p_CompanyId			
			AND 	((T.AssignedTo	= p_userId  OR AssignedTo_Prev = p_userId )OR G.TicketGroupId IS NOT NULL)
  			ORDER BY T.UpdatedDate DESC;    
             
          ELSE
          
  			SELECT 	T.TechSupportTicketId, T.TicketSubject, T.ServiceProviderCompanyId, T.CustomerCompanyId, T.TicketChatId, S.StatusName
  				,	T.TicketDescription, d.TypeCodeName AS Priority, e.UserName AS AssignedTo, T.TicketChatId, T.ChannelTypeId, T.SessionId 
  			FROM 	tb_TechSupportTicket	T 
  			LEFT JOIN 	tt_TicketStatus 		S 	ON T.TicketStatusId = S.StatusId        
  			LEFT JOIN   TypeCode 				d 	ON T.PriorityId 	= d.TypeCodeID			
 			LEFT JOIN   tb_User 				e 	ON T.AssignedTo		= e.UserID
  			WHERE 	T.ServiceProviderCompanyId	=  p_CompanyId			
  			ORDER BY T.UpdatedDate DESC;
             
  		END IF;
         
   	END IF;
     
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
     END ;;
DELIMITER ;
