CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_get_API_Calls`(
       p_domainId			INT
   )
BEGIN
   SELECT sum(API_CallCount) as noOfAPICalls FROM tb_API_Calls WHERE domainId=p_domainId;
   
   SELECT   sum(CDH.botCustomerMsgCount) as noOfMessages FROM tb_ChatMessage CDH JOIN tb_ChatHistory CH  ON CH.ChatHistoryId = CDH.ChatHistoryId
      WHERE CH.domainId=p_domainId;
   
   end ;;
DELIMITER ;
