CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_chat_for_ticket`(
   p_SessionId	VARCHAR(150)
   )
BEGIN
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
  	SELECT 	C.TicketChatId
  		, 	C.SessionId
  		, 	C.RequestedCompanyId
  		, 	C.RequestedProductId
  		, 	C.Title
  		, 	C.Message
  	FROM 	tb_TicketChat 		C 
  	WHERE 	C.SessionId COLLATE utf8mb4_unicode_ci	= p_SessionId;
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;        
   END ;;
