/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_close_ticket_portal`(
   p_CompanyId 		INT, 
   p_UserId			INT,	
   p_offset			INT,
   p_limit			INT
   )
SP:BEGIN
  	DECLARE v_isTechSupport				TINYINT;
  	DECLARE v_ServiceProviderCompanyId	INT;
  	DECLARE v_ClosedStatusId			INT;
    
    DECLARE v_userRole					INT DEFAULT NULL;			
    DECLARE v_userId					INT DEFAULT NULL;			
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
    
    
    
    
    IF p_UserId = 0 THEN 
		SELECT "Incorrect UserId" as 'errMsg';
        LEAVE SP;
	END IF;
    
    
     
   	IF EXISTS (	SELECT 	1
   				FROM 	tb_map_customer_serviceprovider
   				WHERE 	customer_company_id = p_CompanyId)
   	THEN
  		SET v_isTechSupport = 0;				
  
  		SELECT 	service_company_id					
  		INTO 	v_ServiceProviderCompanyId
  		FROM 	tb_map_customer_serviceprovider
  		WHERE 	customer_company_id = p_CompanyId;
   	ELSE
   		SET v_isTechSupport = 1;			
   		SET	v_ServiceProviderCompanyId = p_CompanyId;		
  	END IF;
     
     
       
  	SELECT 	StatusId							
  	INTO 	v_ClosedStatusId
  	FROM 	tb_TicketStatus S
  	WHERE 	S.CompanyId 	= v_ServiceProviderCompanyId			
  	AND 	S.StatusName	= 'Closed'								
  	LIMIT 1;
       
	
     
     IF p_UserId IS NOT NULL THEN
			SELECT roleid INTO  v_userRole FROM tb_User WHERE UserID = p_UserId; 
     end if;
    
    
    
    
    
   IF  p_UserId IS NULL THEN
   
		IF v_isTechSupport = 0 THEN
        
			SELECT 	a.TechSupportTicketId, a.TicketSubject, a.ServiceProviderCompanyId, a.CustomerCompanyId, a.TicketChatId
					,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,f.GroupName
					,e.UserName AS AssignedTo,a.TagId as TagId,a.TicketDescription,a.TicketMode
					,a.RootCause,a.Resolution,a.Summary	
					, a.CreatedDate, a.ClosedDate				
			FROM 	tb_TechSupportTicket	a 
			LEFT JOIN tb_TicketType 	c 	ON a.TicketTypeId 		= c.TicketTypeId
			LEFT JOIN TypeCode 			d 	ON a.PriorityId 		= d.TypeCodeID
			LEFT JOIN tb_TicketGroup	f 	ON a.AssignedToGroupId 	= f.TicketGroupId  
			LEFT JOIN tb_TicketUser 	e 	ON a.AssignedTo			= e.UserId
			WHERE 	a.CustomerCompanyId	= p_CompanyId
			AND 	a.TicketStatusId	= v_ClosedStatusId;
			
   	ELSEIF v_isTechSupport = 1 THEN
    
  		SELECT 	a.TechSupportTicketId, a.TicketSubject, a.ServiceProviderCompanyId, a.CustomerCompanyId, a.TicketChatId
  				,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,f.GroupName
                  ,e.UserName AS AssignedTo,a.TagId as TagId,a.TicketDescription,a.TicketMode
                  ,a.RootCause,a.Resolution,a.Summary
                  , a.CreatedDate, a.ClosedDate					
  		FROM 	tb_TechSupportTicket	a 
  		LEFT JOIN tb_TicketType 	c 	ON a.TicketTypeId 		= c.TicketTypeId
  		LEFT JOIN TypeCode 			d 	ON a.PriorityId 		= d.TypeCodeID
  		LEFT JOIN tb_TicketGroup	f 	ON a.AssignedToGroupId 	= f.TicketGroupId  
  		LEFT JOIN tb_TicketUser 	e 	ON a.AssignedTo			= e.UserId
  		WHERE 	a.ServiceProviderCompanyId	= p_CompanyId
  		AND 	a.TicketStatusId			= v_ClosedStatusId;
        
       END IF;
       
	END IF;
    
 
 
	IF v_userRole = 3 then 
    
			SELECT 	a.TechSupportTicketId, a.TicketSubject, a.ServiceProviderCompanyId, a.CustomerCompanyId, a.TicketChatId
  				,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,f.GroupName
                  ,e.UserName AS AssignedTo,a.TagId as TagId,a.TicketDescription,a.TicketMode
                  ,a.RootCause,a.Resolution,a.Summary	
                  , a.CreatedDate, a.ClosedDate				
  		FROM 	tb_TechSupportTicket	a 
  		LEFT JOIN tb_TicketType 	c 	ON a.TicketTypeId 		= c.TicketTypeId
  		LEFT JOIN TypeCode 			d 	ON a.PriorityId 		= d.TypeCodeID
  		LEFT JOIN tb_TicketGroup	f 	ON a.AssignedToGroupId 	= f.TicketGroupId  
  		LEFT JOIN tb_TicketUser 	e 	ON a.AssignedTo			= e.UserId
  		WHERE 	a.CustomerCompanyId	= p_CompanyId OR a.ServiceProviderCompanyId = 11233
  		AND 	a.TicketStatusId in ( v_ClosedStatusId, 1223);
    
    END IF;
    
    
    
    IF  v_userRole != 3 AND  p_UserId IS NOT NULL THEN 
    
			IF v_isTechSupport = 0 THEN
        
			SELECT distinct	a.TechSupportTicketId, a.TicketSubject, a.ServiceProviderCompanyId, a.CustomerCompanyId, a.TicketChatId
  				,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,f.GroupName
                  ,case when e.UserID = 0 then null else e.UserName end AS AssignedTo, a.TagId as TagId,a.TicketDescription, a.TicketMode
                  ,a.RootCause,a.Resolution,a.Summary
                  , a.CreatedDate, a.ClosedDate					
  		FROM 	tb_TechSupportTicket	a 
  		LEFT JOIN tb_TicketType 	c 	ON a.TicketTypeId 		= c.TicketTypeId
  		LEFT JOIN TypeCode 			d 	ON a.PriorityId 		= d.TypeCodeID
  		LEFT JOIN tb_TicketGroup	f 	ON a.AssignedToGroupId 	= f.TicketGroupId  
  		
        LEFT JOIN tb_User 			e 	ON a.AssignedTo			= e.UserID 
  		WHERE 	a.CustomerCompanyId	= p_CompanyId
   		AND 	a.TicketStatusId			= v_ClosedStatusId 		
        AND 	CASE WHEN IFNULL(a.AssignedTo,0) = 0 then  a.AssignedTo_Prev =  p_UserId ELSE a.AssignedTo = p_UserId END ;
			
   	ELSEIF v_isTechSupport = 1 THEN
    
  		SELECT 	distinct a.TechSupportTicketId, a.TicketSubject, a.ServiceProviderCompanyId, a.CustomerCompanyId, a.TicketChatId
  				,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,f.GroupName
                  ,case when e.UserID = 0 then null else e.UserName end AS AssignedTo, a.TagId as TagId, a.TicketDescription, a.TicketMode
                  ,a.RootCause,a.Resolution,a.Summary
                  , a.CreatedDate, a.ClosedDate					
  		FROM 	tb_TechSupportTicket	a 
  		LEFT JOIN tb_TicketType 	c 	ON a.TicketTypeId 		= c.TicketTypeId
  		LEFT JOIN TypeCode 			d 	ON a.PriorityId 		= d.TypeCodeID
  		LEFT JOIN tb_TicketGroup	f 	ON a.AssignedToGroupId 	= f.TicketGroupId  
  		
        LEFT JOIN tb_User 			e 	ON a.AssignedTo			= e.UserID 
  		WHERE 	a.ServiceProviderCompanyId	= p_CompanyId
  		AND 	a.TicketStatusId			= v_ClosedStatusId
        AND 	CASE WHEN IFNULL(a.AssignedTo,0) = 0 then  a.AssignedTo_Prev =  p_UserId ELSE a.AssignedTo = p_UserId END ;
        
       END IF;
	END IF;
    
    
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
