CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Get_did_purchase`(
    p_domainId INT,
    p_offset SMALLINT,
    p_limit SMALLINT
)
BEGIN
    DECLARE v_offset SMALLINT;

    SET v_offset = p_offset * p_limit;

    SET @Query = CONCAT(
        'SELECT d.pid, d.user_id, d.type, d.city, d.your_number, d.createdAt, d.updatedAt, d.callFlowId, 
        d.recording, d.isCall, d.isSms, d.queueName, d.aliasName, d.outboundSms, d.smsThreshold, d.status, d.callFlowName, 
        d.defaultUpdated, d.supervisorName, d.isCallIn, d.isCallOut, d.isSmsOut, d.isSmsIn, 
        d.queueId, d.country, d.isBot, d.isBotPurchased, d.knowledgeBasedId, d.autoAssignAgent 
        FROM did_purchase d 
        WHERE d.domainId = ', p_domainId, ' AND d.status = 1 
        ORDER BY d.pid DESC 
        LIMIT ', v_offset, ',', p_limit, ';'
    );

    PREPARE stmt FROM @Query;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
