CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_notification`(
 	p_CompanyId 		INT,	
 	p_UserId			BIGINT,  	
 	p_offset			INT,
 	p_limit				INT
   )
BEGIN
 	DECLARE v_isTechSupport				TINYINT;    
 	DECLARE v_roleid					TINYINT;	
 	DECLARE v_offset					INT;
 	DECLARE v_ServiceProviderCompanyId 	INT;	
 	 
 	SET v_offset = p_offset * p_limit;
      
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 	IF EXISTS (	SELECT 	1
 				FROM 	tb_map_customer_serviceprovider
 				WHERE 	customer_company_id = p_CompanyId)
 	THEN
 		SET v_isTechSupport = 0;
 	ELSE
 		SET v_isTechSupport = 1;        
 	END IF;  
     
     IF v_isTechSupport = 1
 	THEN
 		SELECT 	roleid INTO v_roleid 
 		FROM 	tb_User 
 		WHERE 	UserID 		= p_UserId
 		AND 	companyId	= p_CompanyId;
          
 		IF v_roleid = 6
 		THEN
 			SELECT 	N.notification_id, N.TechSupportTicketId, N.notification_type_id, N.notification, UN.isRead, N.CustomerCompanyId, N.ServiceProviderCompanyId
 					,NT.notification_type, N.updated_date, T.SessionId, UN.isRead
 			FROM 	tb_techticket_notification 		N            
             JOIN 	tb_techticket_notification_type	NT	ON 	NT.notification_type_id		= N.notification_type_id
 														AND NT.notification_role		= N.role_id
 			JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
             JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id			= N.notification_id		
 														AND N.ServiceProviderCompanyId	= UN.CompanyId
                                                         AND UN.userId					= p_UserId
 			WHERE 	N.ServiceProviderCompanyId 	= p_CompanyId 							
 			AND 	(	T.AssignedBy			= p_UserId
 					OR 	T.AssignedTo			= p_UserId	)
 			ORDER BY N.updated_date DESC LIMIT v_offset, p_limit;
             
 			SELECT 	COUNT(1) AS TotalNotification
 				,	SUM(CASE WHEN UN.ISREAD = 1 THEN 0 ELSE 1 END) AS UnreadCount
 			FROM 	tb_techticket_notification 		N            
             JOIN 	tb_techticket_notification_type	NT	ON 	NT.notification_type_id		= N.notification_type_id
 														AND NT.notification_role		= N.role_id
 			JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
             JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id			= N.notification_id		
 														AND N.ServiceProviderCompanyId	= UN.CompanyId
                                                         AND UN.userId					= p_UserId
 			WHERE 	N.ServiceProviderCompanyId 	= p_CompanyId 							
 			AND 	(	T.AssignedBy			= p_UserId
 					OR 	T.AssignedTo			= p_UserId	);            
  		ELSEIF v_roleid = 3
 		THEN
  			SELECT 	N.notification_id, N.TechSupportTicketId, N.notification_type_id, N.notification, UN.isRead, N.CustomerCompanyId, N.ServiceProviderCompanyId
                     ,NT.notification_type, N.updated_date, T.SessionId, UN.isRead
             FROM 	tb_techticket_notification 		N
             JOIN 	tb_techticket_notification_type	NT	ON NT.notification_type_id		= N.notification_type_id
 														AND NT.notification_role		= N.role_id
             JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
             JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id			= N.notification_id		
 														AND N.ServiceProviderCompanyId	= UN.CompanyId
                                                         AND UN.userId					= p_UserId
             WHERE 	N.ServiceProviderCompanyId 	= p_CompanyId             
             ORDER BY N.updated_date DESC LIMIT v_offset, p_limit;
             
 			SELECT 	COUNT(1) AS TotalNotification
 				,	SUM(CASE WHEN UN.ISREAD = 1 THEN 0 ELSE 1 END) AS UnreadCount
             FROM 	tb_techticket_notification 		N
             JOIN 	tb_techticket_notification_type	NT	ON NT.notification_type_id		= N.notification_type_id
 														AND NT.notification_role		= N.role_id
             JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
             JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id			= N.notification_id		
 														AND N.ServiceProviderCompanyId	= UN.CompanyId
                                                         AND UN.userId					= p_UserId
             WHERE 	N.ServiceProviderCompanyId 	= p_CompanyId;            
 		ELSEIF v_roleid IN (-2,-1) 
         THEN
 			SELECT 	N.notification_id, N.TechSupportTicketId, N.notification_type_id, N.notification, UN.isRead, N.CustomerCompanyId, N.ServiceProviderCompanyId
 					,NT.notification_type,N.updated_date, T.SessionId, UN.isRead
 			FROM 	tb_techticket_notification 		N   
             JOIN 	tb_techticket_notification_type	NT	ON NT.notification_type_id		= N.notification_type_id
 														AND NT.notification_role		= N.role_id
 			JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
             JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id			= N.notification_id		
 														AND N.ServiceProviderCompanyId	= UN.CompanyId
                                                         AND UN.userId					= T.AssignedTo
 			WHERE 	N.ServiceProviderCompanyId 	= p_CompanyId 							
 			AND 	T.AssignedTo				= p_UserId            				
 			ORDER BY N.updated_date DESC LIMIT v_offset, p_limit;			
             
 			SELECT 	COUNT(1) AS TotalNotification
 				,	SUM(CASE WHEN UN.ISREAD = 1 THEN 0 ELSE 1 END) AS UnreadCount
 			FROM 	tb_techticket_notification 		N   
             JOIN 	tb_techticket_notification_type	NT	ON NT.notification_type_id		= N.notification_type_id
 														AND NT.notification_role		= N.role_id
 			JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
             JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id			= N.notification_id		
 														AND N.ServiceProviderCompanyId	= UN.CompanyId
                                                         AND UN.userId					= T.AssignedTo
 			WHERE 	N.ServiceProviderCompanyId 	= p_CompanyId 							
 			AND 	T.AssignedTo				= p_UserId;            
 		END IF; 
  	ELSE	
 		SELECT 	N.notification_id, N.TechSupportTicketId, N.notification_type_id, N.notification, UN.isRead, N.CustomerCompanyId, N.ServiceProviderCompanyId
 				,NT.notification_type,N.updated_date, T.SessionId, UN.isRead
 		FROM 	tb_techticket_notification 		N
         JOIN 	tb_techticket_notification_type	NT	ON NT.notification_type_id		= N.notification_type_id
 													AND NT.notification_role		= N.role_id
         JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
         JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id	= N.notification_id		
 													AND N.CustomerCompanyId	= UN.CompanyId													
 		WHERE 	N.CustomerCompanyId = p_CompanyId 			        
  		ORDER BY N.updated_date DESC LIMIT v_offset, p_limit;
         
 		SELECT 	COUNT(1) AS TotalNotification
 			,	SUM(CASE WHEN UN.ISREAD = 1 THEN 0 ELSE 1 END) AS UnreadCount
 		FROM 	tb_techticket_notification 		N
         JOIN 	tb_techticket_notification_type	NT	ON NT.notification_type_id		= N.notification_type_id
 													AND NT.notification_role		= N.role_id
         JOIN 	tb_TechSupportTicket			T	ON 	T.TechSupportTicketId 		= N.TechSupportTicketId
         JOIN 	tb_techticket_user_notification	UN	ON 	UN.notification_id	= N.notification_id		
 													AND N.CustomerCompanyId	= UN.CompanyId													
 		WHERE 	N.CustomerCompanyId = p_CompanyId;        
      END IF; 
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
