CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_TechSupportTicketNotes`(
 p_TechSupportTicketId		INT,
 p_UserId					BIGINT
 )
BEGIN
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
 	SELECT 	TN.TechSupportTicketId
 		, 	TN.UserId
         ,	U.UserName
         , 	TN.Notes
         , 	TN.updated_date
     FROM 	tb_TechSupportTicketNotes 	TN
     JOIN 	tb_User						U	ON U.UserID = TN.UserId
     WHERE 	TN.TechSupportTicketId	= p_TechSupportTicketId
     ORDER BY updated_date DESC;
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
 END ;;
DELIMITER ;
