CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_techticket_Status_List`(
 p_CompanyId INT
 )
BEGIN	
 	DECLARE v_ServiceProviderCompanyId	INT;	
      
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
  	IF EXISTS (	SELECT 	1
  				FROM 	tb_map_customer_serviceprovider
  				WHERE 	service_company_id = p_CompanyId)
  	THEN
 		SET	v_ServiceProviderCompanyId = p_CompanyId;
 	ELSE
 		SELECT 	service_company_id
 		INTO 	v_ServiceProviderCompanyId
 		FROM 	tb_map_customer_serviceprovider
 		WHERE 	customer_company_id = p_CompanyId; 		
 	END IF;	
 
 	SELECT 	StatusId, StatusName, IsDefault, SLATimer, StatusColor, IsActive, IsDeleted, StatusCategoryId 
 	FROM 	tb_TicketStatus 
     WHERE 	CompanyId = v_ServiceProviderCompanyId    	
     AND 	IsDefault = 1 
     AND 	IsDeleted = 0;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
