DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_tech_support_csat`(
 p_TechSupportTicketId		INT
 )
BEGIN
 	DECLARE v_ClosedStatusId			INT;
     DECLARE v_TicketStatusId			INT;
     DECLARE v_ServiceProviderCompanyId	INT;
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
 	SELECT 	TicketStatusId, ServiceProviderCompanyId		
     INTO 	v_TicketStatusId, v_ServiceProviderCompanyId    
 	FROM 	tb_TechSupportTicket 
 	WHERE 	TechSupportTicketId	= p_TechSupportTicketId;
     
     SELECT 	StatusId 
     INTO 	v_ClosedStatusId
     FROM 	tb_TicketStatus
     WHERE 	CompanyId	= v_ServiceProviderCompanyId
     AND 	StatusName 	= 'Closed';    
 
 	IF v_ClosedStatusId = v_TicketStatusId
 	THEN
 		SELECT 1 AS 'IsTicketClosed';
 	ELSE
 		SELECT 0 AS 'IsTicketClosed';
     END IF;
     
 	SELECT 	csat, feedback
     FROM 	tb_techticket_csat
     WHERE 	TechSupportTicketId = p_TechSupportTicketId;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
