/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_tech_support_user_with_skill`()
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
      SELECT	U.UserId
  		,	U.UserName
          ,	U.addSkill
          ,	U.roleid
          ,	CASE WHEN U.roleid = 3 	THEN 'Admin'
  				 WHEN U.roleid = 5 	THEN 'Supervisor'
                   WHEN U.roleid = 6 	THEN 'Agent' 
                   WHEN U.roleid = -2 THEN 'Resolver' 
                   End AS `role`
  		,   G.TicketGroupId
  		,	G.GroupName
        ,	G.CompanyId
  	FROM 	tb_companyDomain			C
  	JOIN 	tb_User					U	ON 	C.companyId		= U.CompanyId
  											AND	C.isTechSupport	= 1
      JOIN	tb_TicketGroupUserMapping	GUM	ON 	U.UserId 		= GUM.UserId
      JOIN 	tb_TicketGroup				G	ON 	G.TicketGroupId	= GUM.TicketGroupId
  	WHERE 	U.isActive	= 1;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
