DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_ticket_count_dtl`()
BEGIN
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
         
         SELECT COUNT(t1.TechSupportTicketId) AS TotalTicketCount 
         FROM tb_TechSupportTicket t1 
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName != "Closed" AND t1.ServiceProviderCompanyId = 11233;
         
         SELECT COUNT(t1.TechSupportTicketId) AS TotalResolvedTicket
         FROM tb_TechSupportTicket t1 
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName = "Resolved" AND t1.ServiceProviderCompanyId = 11233;
         
         
         SELECT SUM(CASE WHEN t2.StatusName = "Open" THEN 1 ELSE 0 END) AS TotalOpenCount, 
 			   SUM(CASE WHEN t2.StatusName = "Closed" THEN 1 ELSE 0 END) AS TotalClosedCount,
 			   SUM(CASE WHEN t2.StatusName = "InProgress" THEN 1 ELSE 0 END) AS TotalInprogressCount
 		FROM tb_TechSupportTicket t1
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE StatusName IN("Open", "Closed",  "InProgress") AND ServiceProviderCompanyId = 11233;
         
         SELECT  IFNULL(SUM(CASE WHEN  t1.ChannelTypeId = '2003001' THEN 1 OR 0 END),0) AS 'Call' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003002' THEN 1 OR 0 END),0) AS 'Chat' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003003' THEN 1 OR 0 END),0) AS 'Email' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003004' THEN 1 OR 0 END),0) AS 'SMS' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003005' THEN 1 OR 0 END),0) AS 'Whatsapp' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003006' THEN 1 OR 0 END),0) AS 'Facebook' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003007' THEN 1 OR 0 END),0) AS 'Instagram' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003009' THEN 1 OR 0 END),0) AS 'Portal' 
 		FROM tb_TechSupportTicket	t1
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName != "Closed" AND ServiceProviderCompanyId = 11233;
         
         SELECT  IFNULL(SUM(CASE WHEN  t1.ChannelTypeId = '2003001' THEN 1 OR 0 END),0) AS 'Resolved_Call' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003002' THEN 1 OR 0 END),0) AS 'Resolved_Chat' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003003' THEN 1 OR 0 END),0) AS 'Resolved_Email' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003004' THEN 1 OR 0 END),0) AS 'Resolved_SMS' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003005' THEN 1 OR 0 END),0) AS 'Resolved_Whatsapp' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003006' THEN 1 OR 0 END),0) AS 'Resolved_Facebook' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003007' THEN 1 OR 0 END),0) AS 'Resolved_Instagram' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003009' THEN 1 OR 0 END),0) AS 'Resolved_Portal' 
 		FROM tb_TechSupportTicket	t1
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName = "Resolved" AND ServiceProviderCompanyId = 11233;
         
          SELECT  IFNULL(SUM(CASE WHEN  t1.ChannelTypeId = '2003001' THEN 1 OR 0 END),0) AS 'Open_Call' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003002' THEN 1 OR 0 END),0) AS 'Open_Chat' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003003' THEN 1 OR 0 END),0) AS 'Open_Email' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003004' THEN 1 OR 0 END),0) AS 'Open_SMS' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003005' THEN 1 OR 0 END),0) AS 'Open_Whatsapp' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003006' THEN 1 OR 0 END),0) AS 'Open_Facebook' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003007' THEN 1 OR 0 END),0) AS 'Open_Instagram' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003009' THEN 1 OR 0 END),0) AS 'Open_Portal' 
 		FROM tb_TechSupportTicket	t1
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName = "Open" AND ServiceProviderCompanyId = 11233;
         
         SELECT  IFNULL(SUM(CASE WHEN  t1.ChannelTypeId = '2003001' THEN 1 OR 0 END),0) AS 'Closed_Call' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003002' THEN 1 OR 0 END),0) AS 'Closed_Chat' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003003' THEN 1 OR 0 END),0) AS 'Closed_Email' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003004' THEN 1 OR 0 END),0) AS 'Closed_SMS' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003005' THEN 1 OR 0 END),0) AS 'Closed_Whatsapp' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003006' THEN 1 OR 0 END),0) AS 'Closed_Facebook' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003007' THEN 1 OR 0 END),0) AS 'Closed_Instagram' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003009' THEN 1 OR 0 END),0) AS 'Closed_Portal' 
 		FROM tb_TechSupportTicket	t1
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName = "Closed" AND ServiceProviderCompanyId = 11233;
         
         SELECT  IFNULL(SUM(CASE WHEN  t1.ChannelTypeId = '2003001' THEN 1 OR 0 END),0) AS 'InProgress_Call' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003002' THEN 1 OR 0 END),0) AS 'InProgress_Chat' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003003' THEN 1 OR 0 END),0) AS 'InProgress_Email' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003004' THEN 1 OR 0 END),0) AS 'InProgress_SMS' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003005' THEN 1 OR 0 END),0) AS 'InProgress_Whatsapp' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003006' THEN 1 OR 0 END),0) AS 'InProgress_Facebook' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003007' THEN 1 OR 0 END),0) AS 'InProgress_Instagram' 
 				,IFNULL(SUM(CASE WHEN t1.ChannelTypeId = '2003009' THEN 1 OR 0 END),0) AS 'InProgress_Portal' 
 		FROM tb_TechSupportTicket	t1
 			JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
 		WHERE t2.StatusName = "InProgress" AND ServiceProviderCompanyId = 11233;
         
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
