DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_Ticket_det_on_UserId`(
  	p_RequestorId			INT
  )
BEGIN
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
  			
              SELECT t1.TechSupportTicketId
  				, t1.ServiceProviderCompanyId
  				, t1.CustomerCompanyId
  				, t1.TicketSubject
  				, t1.TicketSourceId
  				, t1.TicketStatusId
  				, t1.IsReopen
  				, t1.TicketTypeId
  				, t1.PriorityId
  				, t1.RequestorId
  				, t1.AssignedToTeamId
  				, t1.AssignedToGroupId
  				, t1.AssignedTo
  				, t1.ConfidenceScore
  				, t1.AssignedTo_Prev
  				, t1.AssignedBy
  				, t1.ChannelTypeId
  				, t1.ResponseDueDate
  				, t1.ResponsedDate
  				, t1.ResolutionDueDate
  				, t1.ResolvedDate
  				, t1.ClosedDate
  				, t1.ResolveInformDate
  				, t1.TicketAssignee
  				, t1.TicketDescription
  				, t1.RootCause
  				, t1.Resolution
  				, t1.Summary
  				, t1.TicketTagIdName
  				, t1.RequesterName
  				, t1.CreatedBy
  				, t1.CreatedDate
  				, t1.UpdatedBy
  				, t1.UpdatedDate
                
              FROM tb_TechSupportTicket t1
 					 JOIN tb_TicketStatus t2 ON t1.TicketStatusId = t2.StatusId
  				WHERE t1.RequestorId = p_RequestorId AND t2.StatusName not in("Closed");
          
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
