/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Get_Ticket_Groups_Users`(p_CompanyId	INT)
BEGIN
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 	SELECT 	G.TicketGroupId
    		,	G.GroupName		
         ,	G.GroupDescription
    	FROM	tb_TicketGroup G	
    	WHERE 	G.CompanyId	= p_CompanyId
    	AND		G.IsDeleted	= 0;
     
     SELECT 	G.TicketGroupId
 		,	G.GroupName
 		,	U.UserID			AS UserId
 		,	U.UserName
         ,	U.emailId
         ,	U.directNumber
         ,	U.ext				
         ,	U.roleid
     FROM 	tb_TicketGroup 				G	
     JOIN 	tb_TicketGroupUserMapping	GU	ON GU.TicketGroupId = G.TicketGroupId
     JOIN 	tb_User 					U	ON U.UserID			= GU.UserId
    	WHERE 	G.CompanyId		= p_CompanyId
    	AND		G.IsDeleted		= 0    
 	AND		GU.IsActive		= 1
 	AND		GU.IsDeleted	= 0;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
