/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_ticket_info_by_id_portal`(
    	p_TicketId 	BIGINT
    )
BEGIN
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    	SELECT 	a.TechSupportTicketId,a.TicketSubject,a.TicketStatusId,b.StatusName,a.TicketTypeId,c.TicketTypeName,a.PriorityId,d.TypeCode as Priority, ResponseDueDate,a.RequesterName,
    			AssignedToGroupId,f.GroupName,a.AssignedTo,a.AssignedBy,e.UserName AS Resolver,ag.UserName	AS Agent,a.TagId as TagId , 		  
    			a.CreatedDate,a.UpdatedDate as ModifiedDate,a.TicketDescription,a.TicketMode,a.TicketAssociateCustContact,
    			(	SELECT 	GROUP_CONCAT(In_TT.TagName)  
    				FROM 	tb_TicketTag 		In_TT   				
    				WHERE 	FIND_IN_SET(In_TT.TicketTagId,a.TagId)>0 ) AS TagName,a.ResolutionDueDate, IFNULL(a.isMergedTo,0) AS isMergedTo,
    			a.TicketChatId, tc.SessionId,a.ServiceProviderCompanyId,a.CustomerCompanyId, tc.Message as customer_chat, a.ai_chat AS ai_chat, a.ConfidenceScore, ch.TypeCodeName AS ChannelType, a.FilesUpload,
              a.RootCause, a.Resolution, a.Summary,
              CASE	WHEN cd.isTechSupport = 0 THEN 'Customer'	 
  					WHEN cb.roleid = 6 THEN 'Agent' 
                      WHEN cb.roleid = 3 THEN 'Admin' END CreatedByRole
 			,a.sendToCust
 			FROM tb_TechSupportTicket	a   	
 			JOIN tb_TicketStatus 		b 	ON a.TicketStatusId 	= b.StatusId
 			LEFT JOIN tb_TicketChat		tc	ON tc.TicketChatId		= a.TicketChatId
 			LEFT JOIN tb_TicketType 	c 	ON a.TicketTypeId 		= c.TicketTypeId
 			LEFT JOIN TypeCode 			d 	ON a.PriorityId 		= d.TypeCodeID
 			LEFT JOIN TypeCode 			ch 	ON a.ChannelTypeId 		= ch.TypeCodeID
 			LEFT JOIN tb_User 			e 	ON a.AssignedTo 		= e.UserId
 			LEFT JOIN tb_User 			ag 	ON a.AssignedBy 		= ag.UserId
 			LEFT JOIN tb_User 			cb 	ON a.CreatedBy 			= cb.UserId
 			LEFT JOIN tb_companyDomain	cd	ON cd.companyId			= cb.companyId
 			LEFT JOIN tb_TicketGroup	f 	ON a.AssignedToGroupId 	= f.TicketGroupId  
 			WHERE 	a.TechSupportTicketId 	= p_TicketId;   
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
