CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_ticket_list_based_on_user_protal`(
     	p_CompanyId 		INT,	
     	p_UserId			BIGINT,  
     	p_TicketCategory	VARCHAR(50),
     	p_offset			INT,
     	p_limit				INT
      )
BEGIN
      	DECLARE v_isTechSupport				TINYINT;    
      	DECLARE v_roleid					TINYINT; 	
      	DECLARE v_offset					INT;
      	DECLARE v_ServiceProviderCompanyId 	INT;	
           
     	SET v_offset = p_offset * p_limit;
    
           
       	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
         DROP TEMPORARY TABLE IF EXISTS tt_Status;
         CREATE TEMPORARY TABLE tt_Status(StatusId	INT,StatusName	VARCHAR(200));
        
        
      	
        IF EXISTS (	SELECT 	1
      				FROM 	tb_map_customer_serviceprovider
      				WHERE 	customer_company_id = p_CompanyId)
      	THEN
      		SET v_isTechSupport = 0;
              
     		SELECT service_company_id 
     		INTO 	v_ServiceProviderCompanyId
     		FROM 	tb_map_customer_serviceprovider
     		WHERE 	customer_company_id = p_CompanyId;        
      	ELSE
      		SET v_isTechSupport = 1;
     		SET v_ServiceProviderCompanyId = p_CompanyId;
      	END IF;  
         
         
         
         
         INSERT INTO tt_Status(StatusId,StatusName)
     	SELECT 	StatusId, StatusName 	
      	FROM 	tb_TicketStatus S
      	WHERE 	S.CompanyId 	= v_ServiceProviderCompanyId	
      	AND 	S.StatusName	IN ('Open','InProgress','Pending','Resolved');    
         
         
         
         
     	IF v_isTechSupport = 1
     	THEN
     		SELECT 	roleid INTO v_roleid 
     		FROM 	tb_User 
     		WHERE 	UserID 		= p_UserId
     		AND 	companyId	= p_CompanyId;
            
            
            
               
               IF v_roleid IN (-2,-1)
               THEN
       			SELECT 	T.TechSupportTicketId, T.TicketSubject, S.StatusName, 'MyTicket' AS TicketCategory
       				,	ServiceProviderCompanyId AS ServiceProviderCompanyId
      				,	TC.SessionId, P.TypeCodeName, T.CreatedDate, T.UpdatedDate	
       			FROM 	tb_TechSupportTicket	T  	
      			JOIN 		tt_Status 				S 	ON T.TicketStatusId = S.StatusId
                LEFT JOIN 	TypeCode				P	ON T.PriorityId 	= P.TypeCodeID	
  			  LEFT JOIN 	tb_TicketChat			TC	ON TC.TicketChatId	= T.TicketChatId
      			WHERE 	T.ServiceProviderCompanyId		= p_CompanyId     
     			AND 	T.AssignedTo					= p_UserId			
     			ORDER BY T.UpdatedDate DESC LIMIT v_offset, p_limit;
                
    		
            
       		ELSEIF v_roleid in (3,6)
     		THEN
       			DROP TEMPORARY TABLE IF EXISTS tt_Ticket;
     			CREATE TEMPORARY TABLE tt_Ticket(TechSupportTicketId	BIGINT, TicketSubject  VARCHAR(500),StatusName  VARCHAR(100), TicketCategory  VARCHAR(20),ServiceProviderCompanyId INT,SessionId VARCHAR(100)
                 ,Priority varchar(100),CreatedDate	DATETIME,UpdatedDate DATETIME);
                  
                  
                  
                   IF p_TicketCategory = 'AssignedTicket' OR p_TicketCategory IS NULL
                   THEN
       				INSERT INTO tt_Ticket(TechSupportTicketId,TicketSubject,StatusName,TicketCategory,ServiceProviderCompanyId,SessionId,Priority, CreatedDate,UpdatedDate)
       				SELECT 	T.TechSupportTicketId, T.TicketSubject, S.StatusName, 'AssignedTicket' AS TicketCategory
       					,	ServiceProviderCompanyId 
      					,	TC.SessionId, P.TypeCodeName,  T.CreatedDate, T.UpdatedDate	
       				FROM 	tb_TechSupportTicket 	T  	
       				JOIN 	tt_Status 				S 	ON T.TicketStatusId = S.StatusId
  					LEFT JOIN 	TypeCode			P	ON T.PriorityId 	= P.TypeCodeID	
      				LEFT JOIN tb_TicketChat			TC	ON TC.TicketChatId	= T.TicketChatId
       				WHERE 	T.ServiceProviderCompanyId	= p_CompanyId 				
       				AND 	( T.AssignedTo = p_UserId  OR 	T.AssignedBy	= p_UserId)  				
       				ORDER BY T.UpdatedDate DESC LIMIT v_offset, p_limit;
                   END IF;
                   
                   
                   
                   IF p_TicketCategory = 'MyTicket' OR p_TicketCategory IS NULL
                   THEN
       				INSERT INTO tt_Ticket(TechSupportTicketId,TicketSubject,StatusName,TicketCategory,ServiceProviderCompanyId,SessionId, Priority, CreatedDate,UpdatedDate)            
       				SELECT 	T.TechSupportTicketId, T.TicketSubject, S.StatusName, 'MyTicket' AS TicketCategory
       					,	ServiceProviderCompanyId 
      					,	TC.SessionId, P.TypeCodeName, T.CreatedDate, T.UpdatedDate	
       				FROM 	tb_TechSupportTicket 	T  	
       				JOIN 	tt_Status		 		S 	ON T.TicketStatusId = S.StatusId
  					LEFT JOIN 	TypeCode				P	ON T.PriorityId 	= P.TypeCodeID	
      				LEFT JOIN tb_TicketChat			TC	ON TC.TicketChatId	= T.TicketChatId
       				WHERE 	T.ServiceProviderCompanyId		= p_CompanyId  				
       				AND 	T.CreatedBy		= p_UserId  					  				
       				ORDER BY T.UpdatedDate DESC LIMIT v_offset, p_limit;
 			
                   END IF;
                   
                   SELECT TechSupportTicketId,TicketSubject,StatusName,TicketCategory,ServiceProviderCompanyId,SessionId, Priority, CreatedDate, UpdatedDate FROM tt_Ticket;
               END IF; 
              
             
             
               
       	ELSE
    	
      		SELECT 	T.TechSupportTicketId, T.TicketSubject, S.StatusName, 'MyTicket' AS TicketCategory
      			,	ServiceProviderCompanyId
      			,	TC.SessionId, P.TypeCodeName AS Priority, T.CreatedDate, T.UpdatedDate	
      		FROM 	tb_TechSupportTicket 	T  	
      		JOIN 	tt_Status		 		S 	ON T.TicketStatusId = S.StatusId
  			LEFT JOIN 	TypeCode				P	ON T.PriorityId 	= P.TypeCodeID	
      		LEFT JOIN tb_TicketChat			TC	ON TC.TicketChatId	= T.TicketChatId
      		WHERE 	(T.CustomerCompanyId	= p_CompanyId	 OR   T.sendToCust	= p_CompanyId) 
       		ORDER BY T.UpdatedDate DESC LIMIT v_offset, p_limit;
     	END IF;    
       	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       END ;;
DELIMITER ;
