 	p_mailId		VARCHAR(150)
 )
BEGIN
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
             
             select UserID, companyId, UserName  FROM tb_User WHERE emailId  COLLATE utf8mb4_0900_ai_ci =  p_mailId;
             
             
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
