CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_UsedNoOfSession`(
    p_domainId INT,
    p_channelType varchar(100)
)
BEGIN
    DECLARE v_planId 						INT;
    DECLARE v_totalChatSessions 			INT DEFAULT 0;
    DECLARE v_totalCallSessions 			INT DEFAULT 0;
    DECLARE v_totalEmailSessions			INT DEFAULT 0;
    DECLARE v_totalSMSSessions 				INT DEFAULT 0;
    DECLARE v_totalWhatsappSessions 		INT DEFAULT 0;
    DECLARE v_totalFacebookSessions 		INT DEFAULT 0;
    DECLARE v_totalInstagramSessions 		INT DEFAULT 0;
    DECLARE v_totalBotSessions 				INT DEFAULT 0;
    
    
    DECLARE v_chatRemainingSessionAgent		INT DEFAULT 0;   
    DECLARE v_noOfPlanChatSessionAgent		INT DEFAULT 0;	 
    
    
    SELECT planId INTO v_planId
    FROM tb_PlanRecharge
    WHERE domainId = p_domainId
    LIMIT 1;
    
    
    SELECT ifnull(chatRemainingSessionBot ,0), IFNULL(chatRemainingSessionAgent, 0) 
		INTO v_totalChatSessions, v_chatRemainingSessionAgent 								
	FROM tb_CurrentPlan 
    WHERE  domainId = p_domainId;
    
    
    SELECT COUNT(1) INTO v_totalCallSessions
    FROM (
        SELECT COUNT(*)
        FROM tb_CallHistory
        WHERE domainId = p_domainId
          AND CustomerId <> 0 
          AND CustomerId IS NOT NULL
        GROUP BY CAST(createdAt AS DATE), CustomerId
    ) AS BB;
    
    
    SELECT COUNT(1) INTO v_totalEmailSessions
    FROM (
        SELECT COUNT(*)
        FROM tb_EmailHistory
        WHERE domainId = p_domainId
          AND CustomerId <> 0 
          AND CustomerId IS NOT NULL
        GROUP BY CAST(createdAt AS DATE), CustomerId
    ) AS CC;
    
    
    SELECT COUNT(1) INTO v_totalSMSSessions
    FROM (
        SELECT COUNT(*)
        FROM tb_SMSHistory
        WHERE domainId = p_domainId
        GROUP BY CAST(createdAt AS DATE)
    ) AS DD;
  
    
    SELECT COUNT(1) INTO v_totalWhatsappSessions
    FROM (
        SELECT COUNT(*)
        FROM tb_WhatsappHistory
        WHERE domainId = p_domainId
        GROUP BY CAST(createdAt AS DATE)
    ) AS EE;
    
    
    SELECT COUNT(1) INTO v_totalFacebookSessions
    FROM (
        SELECT COUNT(*)
        FROM tb_FacebookHistory
        WHERE domainId = p_domainId
        GROUP BY CAST(createdAt AS DATE)
    ) AS FF;
    
    
    SELECT COUNT(1) INTO v_totalInstagramSessions
    FROM (
        SELECT COUNT(*)
        FROM tb_InstagramHistory
        WHERE domainId = p_domainId
        GROUP BY CAST(createdAt AS DATE)
    ) AS GG;
    
    SELECT IFNULL(noOfPlanChatSessionBot, 0) ,IFNULL(noOfPlanChatSessionAgent, 0)					
			INTO v_totalBotSessions , v_noOfPlanChatSessionAgent
    FROM tb_PlanRecharge
    WHERE planId = v_planId
	AND domainId = p_domainId;
    
	IF p_channelType = "All" THEN
		SELECT (v_totalChatSessions + v_totalCallSessions + v_totalEmailSessions +
			v_totalSMSSessions + v_totalWhatsappSessions + v_totalFacebookSessions+v_totalInstagramSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
	ELSEIF p_channelType = "Chat" 
	THEN
		SELECT (v_totalChatSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
        SELECT v_chatRemainingSessionAgent AS AgentRemainingSession;						
         SELECT v_noOfPlanChatSessionAgent AS totalAgentSession;							
	ELSEIF p_channelType = "Call"
	THEN
		SELECT (v_totalCallSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
	ELSEIF p_channelType = "Email" 
	THEN
		SELECT ( v_totalEmailSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
	ELSEIF p_channelType = "SMS" 
	THEN
		SELECT (v_totalSMSSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
	ELSEIF p_channelType = "WhatsApp" 
	THEN
		SELECT (v_totalWhatsappSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
	ELSEIF p_channelType = "Facebook" 
	THEN
		SELECT (v_totalFacebookSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;
	ELSEIF p_channelType = "Instagram" 
	THEN
		SELECT (v_totalInstagramSessions) AS botRemainingSession;
		SELECT v_totalBotSessions AS totalBotSessions;

	END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_get_UsedNoOfSession_v2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
