/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_UsedNoOfSession_v2_NLP`(
 	p_domainId INT
 	,p_channelType varchar(100)
 	,p_AgendId text
 	,p_fromDate date
 	,p_toDate date
     )
sp_exit: BEGIN
     
     		DECLARE v_TotalSession				INT DEFAULT NULL;
     		DECLARE v_ChatAgentSessions			INT DEFAULT 0;	
     		DECLARE v_ChatBotSessions			INT DEFAULT 0;
     		DECLARE v_whatsappAgentSessions		INT DEFAULT 0;	
     		DECLARE v_whatsappBotSessions		INT DEFAULT 0;
     		DECLARE v_FaceBookAgentSessions		INT DEFAULT 0;	
     		DECLARE v_FacebookBotSessions		INT DEFAULT 0;
     		DECLARE v_InstagramAgentSessions	INT DEFAULT 0;	
     		DECLARE v_InstagramBotSessions		INT DEFAULT 0;
     		DECLARE v_SMSAgentSessions			INT DEFAULT 0;
     		DECLARE v_SMSBotSessions			INT DEFAULT 0;
     		DECLARE v_EmailBotSessions			INT DEFAULT 0;
     		DECLARE v_EmailAgentSessions		INT DEFAULT 0;
  		DECLARE v_isUnilimitedChat			TINYINT DEFAULT 0;
          
          if p_fromDate is null or p_toDate is null then
  			set p_fromDate = curdate();
              set p_toDate = curdate();
          End if;
          
          call Split(p_AgendId,','); 
          
          
         select TotalSession into v_TotalSession from tb_PlanRecharge where domainId = p_domainId;
          
          drop temporary table if exists tt_AgendId; 
          create temporary table tt_AgendId ( id int auto_increment primary key, AgendId int );
          
          insert into tt_AgendId(AgendId)
          select Items from tt_Split_temptable;
          
          
  		drop temporary table if exists tt_chtage;
          create temporary table tt_chtage as
  		select ChatHistoryId,Message,chat,jsnlen from 
  		(
  			select a.ChatHistoryId,a.Message,count(*) as chat,json_length(Message) as jsnlen
  			from tb_ChatMessage a 
  			join tb_ChatDurationHistory c on c.ChatDurationHistoryId = a.ChatDurationHistoryId
  			join tb_ChatHistory b on a.ChatHistoryId = b.ChatHistoryId
  			where b.domainId = p_domainId
  			and (cast(b.createdAt as date) >=p_fromDate and cast(b.createdAt as date)<=p_toDate)
            and b.IPAdress not in ('182.66.104.114','14.97.124.22')
  			group by a.ChatHistoryId,a.Message
  		)t
  		where chat = 1
  		and jsnlen > 1; 
              
 		drop temporary table if exists tt_chtage1;
 		create temporary table tt_chtage1 as 
 		select 'Chat' as channelType,cast(createdAt as date) as ctdate,AgentId,IFNULL(count(AgentId),0) as Agentcount,SUM(ifnull(IsBot,0)) as botcount
 		from tb_ChatDurationHistory a 
 		join tt_chtage b on a.ChatHistoryId = b.ChatHistoryId 
 		group by cast(createdAt as date),AgentId;
 		 
 		select  sum(Agentcount),sum(botcount) 
 		into v_ChatAgentSessions, v_ChatBotSessions
 		from tt_chtage1  ;
 		
         
 		
 			drop temporary table if exists tt_wtsage;
 			create temporary table tt_wtsage as
 			SELECT 'WhatsApp' as channelType,cast(createdAt as date) as ctdate,AgentId,IFNULL(count(AgentId),0) as Agentcount,SUM(ifnull(IsBot,0)) as botcount
 			
 			FROM tb_WhatsappDurationHistory A
 			WHERE A.WhatsappHistoryId in  
 			(
 				select B.WhatsappHistoryId from tb_WhatsappHistory B where B.domainId = p_domainId AND cast(B.createdAt as date) between p_fromDate and p_toDate
 			)
 			group by cast(createdAt as date),AgentId;
             
 				select  sum(Agentcount),sum(botcount) 
 				into v_whatsappAgentSessions, v_whatsappBotSessions
 				from tt_wtsage  ;
             
 		
         	drop temporary table if exists tt_fbsage;
 			create temporary table tt_fbsage as
    		select 'Facebook' as channelType,cast(createdAt as date) as ctdate,AgentId,IFNULL(count(AgentId),0) as Agentcount,SUM(ifnull(IsBot,0)) as botcount
            
            from tb_FacebookHistory B 
            where B.domainId = p_domainId
            and cast(B.createdAt as date) between p_fromDate and p_toDate
            group by cast(createdAt as date),AgentId;
            
 				select  sum(Agentcount),sum(botcount) 
 				into v_FaceBookAgentSessions, v_FacebookBotSessions
 				from tt_fbsage  ;
            
 		drop temporary table if exists tt_Inssage;
 			create temporary table tt_Inssage as
    		select 'Instagram' as channelType,cast(createdAt as date) as ctdate,AgentId,IFNULL(count(AgentId),0) as Agentcount,IFNULL(SUM(ifnull(IsBot,0)),0) as botcount
            
            from tb_InstagramHistory B 
            where B.domainId = p_domainId
            and cast(B.createdAt as date) between p_fromDate and p_toDate
            group by cast(createdAt as date),AgentId;
            
 				select  sum(Agentcount),sum(botcount) 
 				into v_InstagramAgentSessions, v_InstagramBotSessions
 				from tt_Inssage  ;
 
 		drop temporary table if exists tt_Emailsage;
 			create temporary table tt_Emailsage as
 		SELECT 'Email' as channelType,cast(createdAt as date),AgentId,IFNULL(count(AgentId),0) as Agentcount,SUM(ifnull(IsBot,0)) as botcount
 		
    		FROM tb_EmailDurationHistory A
    		WHERE A.EmailHistoryId in  
    		(
    			select B.EmailHistoryId from tb_EmailHistory B where B.domainId = p_domainId AND cast(B.createdAt as date) between p_fromDate and p_toDate
    		) group by cast(createdAt as date),AgentId;
         
 			select  sum(Agentcount),sum(botcount) 
 			into v_EmailAgentSessions, v_EmailBotSessions
 			from tt_Emailsage  ;
 
          drop temporary table if exists tt_Smssage;
 			create temporary table tt_Smssage as
 		SELECT 'SMS' as channelType,cast(createdAt as date),AgentId,IFNULL(count(AgentId),0) as Agentcount,SUM(ifnull(IsBot,0)) as botcount
 		
    		FROM tb_SMSDurationHistory A
    		WHERE A.SMSHistoryId in  
    		(
    			select B.SMSHistoryId from tb_SMSHistory B where B.domainId = p_domainId AND cast(B.createdAt as date) between p_fromDate and p_toDate
    		) group by cast(createdAt as date),AgentId;
           
           	select  sum(Agentcount),sum(botcount) 
 			into v_SMSAgentSessions, v_SMSBotSessions
 			from tt_Smssage  ;
  
             IF p_channelType = 'All' THEN
    		SELECT 	v_TotalSession as TotalSession, 
    				SUM(ifnull(v_ChatAgentSessions,0) + ifnull(v_whatsappAgentSessions,0) + ifnull(v_FaceBookAgentSessions,0) 
 					+ ifnull(v_InstagramAgentSessions,0) + ifnull(v_EmailAgentSessions,0) + ifnull(v_SMSAgentSessions,0)) as TotalAgentSession,
 				SUM(ifnull(v_ChatBotSessions,0) + ifnull(v_whatsappBotSessions,0) + ifnull(v_FacebookBotSessions,0) 
 					+ ifnull(v_InstagramBotSessions,0) + ifnull(v_EmailBotSessions,0) + ifnull(v_SMSBotSessions,0)) as TotalBotSession,
 				(v_TotalSession - SUM(ifnull(v_ChatAgentSessions,0) + ifnull(v_whatsappAgentSessions,0) + ifnull(v_FaceBookAgentSessions,0) 
                     + ifnull(v_InstagramAgentSessions,0) + ifnull(v_EmailAgentSessions,0) + ifnull(v_SMSAgentSessions,0) 
 					+ ifnull(v_ChatBotSessions,0) + ifnull(v_whatsappBotSessions,0) + ifnull(v_FacebookBotSessions,0) 
                     + ifnull(v_InstagramBotSessions,0) + ifnull(v_EmailBotSessions,0) + ifnull(v_SMSBotSessions,0))) as remainingSessions;   
                    
     	ELSEIF p_channelType = 'Chat' THEN
 			SELECT v_TotalSession as TotalSession, ifnull(v_ChatAgentSessions,0) as TotalAgentSession, ifnull(v_ChatBotSessions,0) as TotalBotSession;
            
     	ELSEIF p_channelType = 'WhatsApp' THEN
 			SELECT v_TotalSession as TotalSession, ifnull(v_whatsappAgentSessions,0) as TotalAgentSession, ifnull(v_whatsappBotSessions,0) as TotalBotSession;
            
     	ELSEIF p_channelType = 'Facebook' THEN
 			SELECT v_TotalSession as TotalSession, ifnull(v_FaceBookAgentSessions,0) as TotalAgentSession, ifnull(v_FacebookBotSessions,0) as TotalBotSession;
            
     	ELSEIF p_channelType = 'Instagram'THEN
 			SELECT v_TotalSession as TotalSession, ifnull(v_InstagramAgentSessions,0) as TotalAgentSession, ifnull(v_InstagramBotSessions,0) as TotalBotSession;
          
 		ELSEIF p_channelType = 'Email'THEN
 			SELECT v_TotalSession as TotalSession, ifnull(v_EmailAgentSessions,0) as TotalAgentSession, ifnull(v_EmailBotSessions,0) as TotalBotSession;
          
 		ELSEIF p_channelType = 'SMS'THEN
 			SELECT v_TotalSession as TotalSession, ifnull(v_SMSAgentSessions,0) as TotalAgentSession, ifnull(v_SMSBotSessions,0) as TotalBotSession;
     
     	END IF;
         
         SELECT ifnull(v_ChatAgentSessions,0) + ifnull(v_ChatBotSessions,0) as TotalChatSession
 			,ifnull(v_whatsappAgentSessions,0) + ifnull(v_whatsappBotSessions,0) as TotalWhatsAppSession
 			,ifnull(v_FaceBookAgentSessions,0) + ifnull(v_FacebookBotSessions,0) as TotalFacebookSession
 			,ifnull(v_InstagramAgentSessions,0) + ifnull(v_InstagramBotSessions,0) as TotalInstagramSession
 			,ifnull(v_EmailAgentSessions,0) + ifnull(v_EmailBotSessions,0) as TotalEmailSession
 			,ifnull(v_SMSAgentSessions,0) + ifnull(v_SMSBotSessions,0) as TotalSMSSession;
             
 		select * from 
         (
 			select * from tt_chtage1
             union all select * from tt_wtsage
             union all select * from tt_fbsage
 			union all select * from tt_Inssage
 			union all select * from tt_Emailsage
 			union all select * from tt_Smssage
         )t
         where (channelType = p_channelType or ifnull(p_channelType,'All')='All');
             
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_get_UsedNoOfSession_v2_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_get_UsedNoOfSession_v2_test`(
   	p_domainId INT
   	,p_channelType varchar(100)
   )
sp_exit: BEGIN
   
   		DECLARE v_TotalSession				INT DEFAULT 0;
   		DECLARE v_ChatAgentSessions			INT DEFAULT 0;	
   		DECLARE v_ChatBotSessions			INT DEFAULT 0;
   		DECLARE v_whatsappAgentSessions		INT DEFAULT 0;	
   		DECLARE v_whatsappBotSessions		INT DEFAULT 0;
   		DECLARE v_FaceBookAgentSessions		INT DEFAULT 0;	
   		DECLARE v_FacebookBotSessions		INT DEFAULT 0;
   		DECLARE v_InstagramAgentSessions	INT DEFAULT 0;	
   		DECLARE v_InstagramBotSessions		INT DEFAULT 0;
   		DECLARE v_SMSAgentSessions			INT DEFAULT 0;
   		DECLARE v_SMSBotSessions			INT DEFAULT 0;
   		DECLARE v_EmailBotSessions			INT DEFAULT 0;
   		DECLARE v_EmailAgentSessions		INT DEFAULT 0;
		DECLARE v_isUnilimitedChat			TINYINT DEFAULT 0;
		DECLARE v_total_used				INT;
            
            DROP temporary table if exists temp_PP;
            CREATE temporary table temp_PP As
            SELECT 	domainId, cast(planStartTime as date) as planStartTime, cast(planEndTime as date) as planEndTime
            FROM tb_PlanRecharge where domainId = p_domainId;
            
   		select TotalSession,isUnilimitedChat into v_TotalSession,v_isUnilimitedChat from tb_CurrentPlan where domainId = p_domainId;
        
        select sum(chatRemainingSessionAgent + chatRemainingSessionBot) into v_total_used 
        from tb_CurrentPlan where domainId = p_domainId;

        
   		
        
        drop temporary table if exists tt_chtage;
          create temporary table tt_chtage as
  		select ChatHistoryId,Message,chat,jsnlen from 
  		(
  			select a.ChatHistoryId,a.Message,count(*) as chat,json_length(Message) as jsnlen
  			from tb_ChatMessage a 
  			join tb_ChatDurationHistory c on c.ChatDurationHistoryId = a.ChatDurationHistoryId
  			join tb_ChatHistory b on a.ChatHistoryId = b.ChatHistoryId
            join temp_PP 		PP ON PP.domainId = b.domainId
  			where b.domainId = p_domainId
  			and (cast(b.createdAt as date) >= PP.planStartTime and cast(b.createdAt as date) <= PP.planEndTime)
  			group by a.ChatHistoryId,a.Message
  		)t
  		where chat = 1
  		and jsnlen > 1; 
              
 		drop temporary table if exists tt_chtage1;
 		create temporary table tt_chtage1 as 
 		select 'Chat' as channelType,cast(createdAt as date) as ctdate,AgentId,IFNULL(count(AgentId),0) as Agentcount,SUM(ifnull(IsBot,0)) as botcount
 		from tb_ChatDurationHistory a 
 		join tt_chtage b on a.ChatHistoryId = b.ChatHistoryId 
 		group by cast(createdAt as date),AgentId;
 		 
 		select  sum(Agentcount),sum(botcount) 
 		into v_ChatAgentSessions, v_ChatBotSessions
 		from tt_chtage1  ;
        
        
   		SELECT IFNULL(count(AgentId),0),SUM(ifnull(IsBot,0))
		INTO v_whatsappAgentSessions, v_whatsappBotSessions
   		FROM tb_WhatsappDurationHistory A
   		WHERE A.WhatsappHistoryId in  
   		(
   			select B.WhatsappHistoryId from tb_WhatsappHistory B JOIN temp_PP C on B.domainId = C.domainId where B.domainId = p_domainId AND cast(B.createdAt as date) between C.planStartTime and C.planEndTime
   		);
   
        
   		select IFNULL(count(AgentId),0),SUM(ifnull(IsBot,0))
           INTO v_FaceBookAgentSessions, v_FacebookBotSessions
           from tb_FacebookHistory B 
           join temp_PP C on B.domainId = C.domainId
           where B.domainId = p_domainId
           and cast(B.createdAt as date) between C.planStartTime and C.planEndTime;
   
   		select IFNULL(count(AgentId),0),IFNULL(SUM(ifnull(IsBot,0)),0)
           INTO v_InstagramAgentSessions, v_InstagramBotSessions
           from tb_InstagramHistory B 
           join temp_PP C on B.domainId = C.domainId
           where B.domainId = p_domainId
           and cast(B.createdAt as date) between C.planStartTime and C.planEndTime;
 
		SELECT IFNULL(count(AgentId),0),SUM(ifnull(IsBot,0))
		INTO v_EmailAgentSessions, v_EmailBotSessions
   		FROM tb_EmailDurationHistory A
   		WHERE A.EmailHistoryId in  
   		(
   			select B.EmailHistoryId from tb_EmailHistory B JOIN temp_PP C on B.domainId = C.domainId where B.domainId = p_domainId AND cast(B.createdAt as date) between C.planStartTime and C.planEndTime
   		);
         
		SELECT IFNULL(count(AgentId),0),SUM(ifnull(IsBot,0))
		INTO v_SMSAgentSessions, v_SMSBotSessions
   		FROM tb_SMSDurationHistory A
   		WHERE A.SMSHistoryId in  
   		(
   			select B.SMSHistoryId from tb_SMSHistory B JOIN temp_PP C on B.domainId = C.domainId where B.domainId = p_domainId AND cast(B.createdAt as date) between C.planStartTime and C.planEndTime
   		);
           
        
    	IF p_channelType = 'All' THEN
   		SELECT 	v_TotalSession as TotalSession, 
   				SUM(ifnull(v_ChatAgentSessions,0) + ifnull(v_whatsappAgentSessions,0) + ifnull(v_FaceBookAgentSessions,0) + ifnull(v_InstagramAgentSessions,0) + ifnull(v_EmailAgentSessions,0) + ifnull(v_SMSAgentSessions,0)) as TotalAgentSession,
                   SUM(ifnull(v_ChatBotSessions,0) + ifnull(v_whatsappBotSessions,0) + ifnull(v_FacebookBotSessions,0) + ifnull(v_InstagramBotSessions,0) + ifnull(v_EmailBotSessions,0) + ifnull(v_SMSBotSessions,0)) as TotalBotSession,
                   
                   v_TotalSession - v_total_used as remainingSessions
                   ,v_isUnilimitedChat as isUnilimitedChat;   
                   
    	ELSEIF p_channelType = 'Chat' THEN
			SELECT v_TotalSession as TotalSession, ifnull(v_ChatAgentSessions,0) as TotalAgentSession, ifnull(v_ChatBotSessions,0) as TotalBotSession;
           
    	ELSEIF p_channelType = 'WhatsApp' THEN
			SELECT v_TotalSession as TotalSession, ifnull(v_whatsappAgentSessions,0) as TotalAgentSession, ifnull(v_whatsappBotSessions,0) as TotalBotSession;
           
    	ELSEIF p_channelType = 'Facebook' THEN
			SELECT v_TotalSession as TotalSession, ifnull(v_FaceBookAgentSessions,0) as TotalAgentSession, ifnull(v_FacebookBotSessions,0) as TotalBotSession;
           
    	ELSEIF p_channelType = 'Instagram'THEN
			SELECT v_TotalSession as TotalSession, ifnull(v_InstagramAgentSessions,0) as TotalAgentSession, ifnull(v_InstagramBotSessions,0) as TotalBotSession;
         
		ELSEIF p_channelType = 'Email'THEN
			SELECT v_TotalSession as TotalSession, ifnull(v_EmailAgentSessions,0) as TotalAgentSession, ifnull(v_EmailBotSessions,0) as TotalBotSession;
         
		ELSEIF p_channelType = 'SMS'THEN
			SELECT v_TotalSession as TotalSession, ifnull(v_SMSAgentSessions,0) as TotalAgentSession, ifnull(v_SMSBotSessions,0) as TotalBotSession;
    
    	END IF;
       
     SELECT ifnull(v_ChatAgentSessions,0) + ifnull(v_ChatBotSessions,0) as TotalChatSession
			,ifnull(v_whatsappAgentSessions,0) + ifnull(v_whatsappBotSessions,0) as TotalWhatsAppSession
			,ifnull(v_FaceBookAgentSessions,0) + ifnull(v_FacebookBotSessions,0) as TotalFacebookSession
			,ifnull(v_InstagramAgentSessions,0) + ifnull(v_InstagramBotSessions,0) as TotalInstagramSession
			,ifnull(v_EmailAgentSessions,0) + ifnull(v_EmailBotSessions,0) as TotalEmailSession
			,ifnull(v_SMSAgentSessions,0) + ifnull(v_SMSBotSessions,0) as TotalSMSSession;  
       
        DROP temporary table if exists temp_PP;
       
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_get_UsedNoOfSession_v2_test222` */;
