CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ImportTicketContact`(
        p_ImportTicketContactDetls 	JSON,
        p_LoggedInUserID 			BIGINT
    )
BEGIN
        DECLARE v_errcode INT;
        DECLARE v_errmsg VARCHAR(55);
        DECLARE v_CurDate DATETIME;
        DECLARE v_JLength INT;
        DECLARE v_SlNo INT;
        DECLARE v_TicketContactId INT;
        DECLARE v_Email VARCHAR(255);
        DECLARE v_ContactNumber VARCHAR(20);
        DECLARE v_DomainId INT;
    
        SET v_errcode = 1; 
        SET v_errmsg = 'Error importing data'; 
    
        SET v_CurDate = NOW();
        SET v_JLength = JSON_LENGTH(p_ImportTicketContactDetls, "$") - 1;
        SET v_SlNo = 0;
    
        
        WHILE v_SlNo <= v_JLength DO
            SET v_TicketContactId = JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].TicketContactId'));
            SET v_Email = REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].Email')), '"', '');
            SET v_ContactNumber = REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].ContactNumber')), '"', '');
            SET v_DomainId = REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].DomainId')), '"', '');
    
            INSERT INTO tb_TicketContact (
                CompanyId,
                ProductId,
                FirstName,
                LastName,
                Address,
                Zipcodes,
                IsDeleted,
                CreatedBy,
                CreatedDate,
                UpdatedBy,
                UpdatedDate
            )
            SELECT
                REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].CompanyId')), '"', ''),
                REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].ProductId')), '"', ''),
                REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].FirstName')), '"', ''),
                REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].LastName')), '"', ''),
                REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].Address')), '"', ''),
                REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].Zipcodes')), '"', ''),
                0,
                p_LoggedInUserID,
                v_CurDate,
                p_LoggedInUserID,
                v_CurDate;
    
 			SET v_TicketContactId = LAST_INSERT_ID();
 			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
             
 		   IF NOT EXISTS(	SELECT 	1 FROM customer_contact 
 							WHERE 	domainId = v_DomainId 
 							AND 	(	primaryPhoneNumber	LIKE v_ContactNumber OR primaryEmail LIKE v_Email OR
 										phoneNumber LIKE CONCAT('%',v_ContactNumber,'%') OR email LIKE CONCAT('%',v_Email,'%')))  
 			THEN
 				INSERT INTO customer_contact(firstName,lastName,address,primaryPhoneNumber,phoneNumber,postalCode,primaryEmail,email,domainId)
 				SELECT 	REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].FirstName')), '"', ''),
 						REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].LastName')), '"', ''),
 						REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].Address')), '"', ''),
 						REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].ContactNumber')), '"', ''),'[]',
 						REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].Zipcodes')), '"', ''),
 						REPLACE(JSON_EXTRACT(p_ImportTicketContactDetls, CONCAT('$[', v_SlNo, '].Email')), '"', ''),'[]',
 						v_DomainId;
 				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 		   END IF;
    
            INSERT INTO tb_TicketContactInformation (
                TicketContactId,
                ContactInformationTypeId,
                ContactInformation,
                IsDeleted,
                CreatedBy,
                CreatedDate,
                UpdatedBy,
                UpdatedDate
            )
            VALUES (
                v_TicketContactId,
                1108029,
                v_Email,
                0,
                p_LoggedInUserID,
                v_CurDate,
                p_LoggedInUserID,
                v_CurDate
            );
    
            INSERT INTO tb_TicketContactInformation (
                TicketContactId,
                ContactInformationTypeId,
                ContactInformation,
                IsDeleted,
                CreatedBy,
                CreatedDate,
                UpdatedBy,
                UpdatedDate
            )
            VALUES (
                v_TicketContactId,
                1108030,
                v_ContactNumber,
                0,
                p_LoggedInUserID,
                v_CurDate,
                p_LoggedInUserID,
                v_CurDate
            );
    
            SET v_SlNo = v_SlNo + 1;
        END WHILE;
    
        SET v_errcode = 0;
        SET v_errmsg = 'Imported successfully';
    
        SELECT v_errcode AS errcode, v_errmsg AS errmsg;
    END ;;
DELIMITER ;
