/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Inboundchat_agent_analysis_metrics_filter`(
          		p_startTmpstmp 		BIGINT,
    			p_endTmpstmp 		BIGINT,
    			p_domainId 			INT,
    			p_agentId 			INT,
    			p_offset 			INT,
    			p_Limit 			INT	
          	)
sp_return:begin
    			DECLARE 	v_offset 					INT;	
    			DECLARE 	v_Total_Count 				INT;        
    			DECLARE 	v_startTmpstmp 				BIGINT;
    			DECLARE 	v_endTmpstmp 				BIGINT;
    			DECLARE 	v_currenttimestamp 			BIGINT;
    			DECLARE 	v_previous_timestamp 		BIGINT;
    			DECLARE 	v_oneday_previous_timestamp BIGINT;
    			DECLARE 	v1_count_currentdata 		INT;
    			DECLARE 	v1_count_pastdata		    INT;
    			DECLARE 	v2_count_currentdata 		INT;
    			DECLARE 	v2_count_pastdata		    INT;
    			DECLARE 	v3_count_currentdata 		INT;
    			DECLARE 	v3_count_pastdata		    INT;
              
       			SET v_offset =  p_Limit * p_offset;   
               
       
       
       			SET v_currenttimestamp = unix_timestamp(NOW()) * 1000;
       			SET v_previous_timestamp = DATE_SUB(NOW(), INTERVAL 1 DAY);
       			SET v_oneday_previous_timestamp = DATE_SUB(NOW(), INTERVAL 2 DAY);
       
       
                  	IF IFNULL(p_startTmpstmp,0)= 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
                  	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
                  
          	
       	         DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
                 
              
      			CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;    
                    
       			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                    
          		 
                  
                  
                    
      			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
          		CREATE TEMPORARY TABLE temp_AllagentId
          		SELECT  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3);                                               
                  
                  
                  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                  
    		   DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
       		   CREATE TEMPORARY TABLE temp_chatHistory as
          
                  SELECT 	
    					CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		   						 						     	AS SessionDate
      					,U.UserName																											AS agentName	
    					,U.UserID																											AS agentId	
    					,COUNT(1) 																											AS ReceivedChats
    					,COUNT(CASE WHEN (SH.repliedDate - SH.createdAt) IS NOT NULL THEN 1 ELSE NULL END) 									AS RespondedChats
    					,COUNT(CASE WHEN SH.disconnectedBy IS NOT NULL THEN 1 ELSE NULL	END	)									            AS AbandonedChats
          			FROM 	tb_ChatHistory 			SH
          			JOIN 	tb_ChatDurationHistory	SDH	    ON SH.ChatHistoryId = SDH.ChatHistoryId
          			LEFT JOIN 	tb_User				U	    ON U.UserID			= SDH.AgentId
    				LEFT JOIN temp_agentIDs 		t_A     ON U.UserID 		= t_A.agentId   
          			WHERE 	SH.domainId 			= p_domainId 		
          			AND 	SH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp 
          			AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
          			group by sessionStartTime,U.UserName,U.UserID,SH.disconnectedBy
    			LIMIT v_offset, p_Limit;  
          			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
       			
    				  SELECT * FROM temp_AllagentId;
   				  SELECT COUNT(1) totalCount FROM temp_chatHistory;
    		  
    	   
           
     		    SELECT 	COUNT(1) 
        		INTO 	v1_count_currentdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
                    LIMIT 1;
                
        		
        		SELECT COUNT(1)
        		INTO 	v1_count_pastdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
    			LIMIT 1;   
    	
        
        
       
        		
        		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
        		INTO 	v2_count_currentdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
                  LIMIT 1;
                
        		
        		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
        		INTO 	v2_count_pastdata 
        		FROM 	tb_ChatHistory
        		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
    			LIMIT 1;
                
         
        
        		
        		SELECT CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	end 								    AS abondedchats
        		INTO 	v3_count_currentdata 
        		FROM 	tb_ChatDurationHistory  SDH  JOIN
        				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
        		WHERE 	SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;
                
        		
        		SELECT CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '0'	end 								AS abondedchats
        		INTO 	v3_count_pastdata 
        		FROM 	tb_ChatDurationHistory  SDH  JOIN
        				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
        		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
        		and 	domainId	= p_domainId
        		LIMIT 1;   
                
                
    
    
                      IF NOT EXISTS(select 1 FROM temp_chatHistory limit 1) then
     					SELECT '-' as agentName, 0 AS totalreceivedchats, 0 AS Receivedchatdifference, 0 AS Receivedchatdiffpercentage, 0 AS totalRespondedChats ,
                        0 AS Respondedchatdifference ,0 AS Respondedchatdiffpercentage,0 as totalabondedchats,0 as abondedchatssdifference,0 as abondedchatssdiffpercentage;
                         leave sp_return;
                      end if;
                
                    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
        			   SELECT 
                    
     						IFNULL(agentName,0)								 								                              			  AS agentName,
    						IFNULL(ReceivedChats,0) 																							      AS TotalReceivedChats,	
                            IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata  ),0)		                                  AS Receivedchatdifference,
    						IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata )*100,0)		                             	  AS Receivedchatdiffpercentage,
    						IFNULL(RespondedChats,0)																								  as TotalRespondedChats,
     						IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata ),0)										      AS Respondedchatdifference,
    						IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata )*100,0)										  AS Respondedchatdiffpercentage,
     						IFNULL((AbandonedChats),0) 						 																          AS Totalabondedchats,
     						IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata ),0)		                                 	  AS Abondedchatssdifference,
                            IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata )*100,0)		                              AS Abondedchatssdiffpercentage
     						FROM 
     						temp_chatHistory 
     						GROUP BY agentName, totalReceivedChats,ReceivedChats,RespondedChats,AbandonedChats;
                                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        			
                    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Inboundchat_agent_analysis_metrics_filterT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Inboundchat_agent_analysis_metrics_filterT`(
			p_startTmpstmp 		BIGINT,
   			p_endTmpstmp 		BIGINT,
   			p_domainId 			INT,
   			p_agentId 			INT,
   			p_offset 			INT,
   			p_Limit 			INT	
         	)
sp_return:begin
   			DECLARE 	v_offset 					INT;	
   			DECLARE 	v_Total_Count 				INT;        
   			DECLARE 	v_startTmpstmp 				BIGINT;
   			DECLARE 	v_endTmpstmp 				BIGINT;
   			DECLARE 	v_currenttimestamp 			BIGINT;
   			DECLARE 	v_previous_timestamp 		BIGINT;
   			DECLARE 	v_oneday_previous_timestamp BIGINT;
   			DECLARE 	v1_count_currentdata 		INT;
   			DECLARE 	v1_count_pastdata		    INT;
   			DECLARE 	v2_count_currentdata 		INT;
   			DECLARE 	v2_count_pastdata		    INT;
   			DECLARE 	v3_count_currentdata 		INT;
   			DECLARE 	v3_count_pastdata		    INT;
             
      			SET v_offset =  p_Limit * p_offset;   
              
      
      
      			SET v_currenttimestamp = unix_timestamp(NOW()) * 1000;
      			SET v_previous_timestamp = DATE_SUB(NOW(), INTERVAL 1 DAY);
      			SET v_oneday_previous_timestamp = DATE_SUB(NOW(), INTERVAL 2 DAY);
      
      
                 	IF IFNULL(p_startTmpstmp,0)= 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +7 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
                 	IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
                 

      	         DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     			CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;    
                   
      			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                   
     			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
         		CREATE TEMPORARY TABLE temp_AllagentId
         		SELECT  UserID,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3);                                               
                 
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                 
   		   DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
      		   CREATE TEMPORARY TABLE temp_chatHistory as
                 SELECT 	
   					CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		   						 						     	AS SessionDate
					,U.UserName																											AS agentName	
   					,U.UserID																											AS agentId	
   					,COUNT(1) 																											AS ReceivedChats
   					,COUNT(CASE WHEN (SH.repliedDate - SH.createdAt) IS NOT NULL THEN 1 ELSE NULL END) 									AS RespondedChats
   					,COUNT(CASE WHEN SH.disconnectedBy IS NOT NULL THEN 1 ELSE NULL	END	)									            AS AbandonedChats
         			FROM 	tb_ChatHistory 			SH
         			JOIN 	tb_ChatDurationHistory	SDH	    ON SH.ChatHistoryId = SDH.ChatHistoryId
         			LEFT JOIN 	tb_User				U	    ON U.UserID			= SDH.AgentId
   				    LEFT JOIN temp_agentIDs 		t_A     ON U.UserID 		= t_A.agentId   
         			WHERE 	SH.domainId 			= p_domainId 		
         			AND 	SH.sessionStartTime 	BETWEEN p_startTmpstmp and p_endTmpstmp 
         			AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL))
         			GROUP BY sessionStartTime,U.UserName,U.UserID,SH.disconnectedBy
   			        LIMIT v_offset, p_Limit;  
         			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  	
   				  SELECT * FROM temp_AllagentId;
  				  SELECT COUNT(1) totalCount FROM temp_chatHistory;
   		  
          
    		    SELECT 	COUNT(1) 
       		INTO 	v1_count_currentdata 
       		FROM 	tb_ChatHistory
       		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
       		and 	domainId	= p_domainId
                   LIMIT 1;
               
       		
       		SELECT COUNT(1)
       		INTO 	v1_count_pastdata 
       		FROM 	tb_ChatHistory
       		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
       		AND 	domainId	= p_domainId
   			LIMIT 1;   
     
       
       		
       		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
       		INTO 	v2_count_currentdata 
       		FROM 	tb_ChatHistory
       		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
       		and 	domainId	= p_domainId
			LIMIT 1;
       		
       		SELECT 	case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end as  RespondedChats
       		INTO 	v2_count_pastdata 
       		FROM 	tb_ChatHistory
       		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
       		and 	domainId	= p_domainId
   			LIMIT 1;
        
       
       		
       		SELECT CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	end 								    AS abondedchats
       		INTO 	v3_count_currentdata 
       		FROM 	tb_ChatDurationHistory  SDH  JOIN
       				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
       		WHERE 	SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
       		and 	domainId	= p_domainId
       		LIMIT 1;
               
       		
       		SELECT CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '0'	end 								AS abondedchats
       		INTO 	v3_count_pastdata 
       		FROM 	tb_ChatDurationHistory  SDH  JOIN
       				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
       		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
       		and 	domainId	= p_domainId
       		LIMIT 1;   
               
               
   
   
                     IF NOT EXISTS(select 1 FROM temp_chatHistory limit 1) then
    					SELECT '-' as agentName, 0 AS totalreceivedchats, 0 AS Receivedchatdifference, 0 AS Receivedchatdiffpercentage, 0 AS totalRespondedChats ,
                       0 AS Respondedchatdifference ,0 AS Respondedchatdiffpercentage,0 as totalabondedchats,0 as abondedchatssdifference,0 as abondedchatssdiffpercentage;
                        leave sp_return;
                     end if;
               
                   SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
       			   SELECT 
                   
    						IFNULL(agentName,0)								 								                              			  AS agentName,
   						IFNULL(ReceivedChats,0) 																							      AS TotalReceivedChats,	
                           IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata  ),0)		                                  AS Receivedchatdifference,
   						IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata )*100,0)		                             	  AS Receivedchatdiffpercentage,
   						IFNULL(RespondedChats,0)																								  as TotalRespondedChats,
    						IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata ),0)										      AS Respondedchatdifference,
   						IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata )*100,0)										  AS Respondedchatdiffpercentage,
    						IFNULL((AbandonedChats),0) 						 																          AS Totalabondedchats,
    						IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata ),0)		                                 	  AS Abondedchatssdifference,
                           IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata )*100,0)		                              AS Abondedchatssdiffpercentage
    						FROM 
    						temp_chatHistory 
    						GROUP BY agentName, totalReceivedChats,ReceivedChats,RespondedChats,AbandonedChats;
                               SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       			
                   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Inboundchat_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Inboundchat_analysis_metrics_filter`(
 			p_startTmpstmp 		BIGINT,
 			p_endTmpstmp 		BIGINT,
 			p_domainId 			INT,
 			p_queueId 			INT,
 			p_offset 			INT,
 			p_Limit 			INT	
     	)
sp_return:begin
 			DECLARE 	v_offset 					INT;	
 			DECLARE 	v_Total_Count 				INT;        
 			DECLARE 	v_startTmpstmp 				BIGINT;
 			DECLARE 	v_endTmpstmp 				BIGINT;
 			DECLARE 	v_currenttimestamp 			BIGINT;
 			DECLARE 	v_previous_timestamp 		BIGINT;
 			DECLARE 	v_oneday_previous_timestamp BIGINT;
 			DECLARE 	v1_count_currentdata 		INT;
 			DECLARE 	v1_count_pastdata		    INT;
 			DECLARE 	v2_count_currentdata 		INT;
 			DECLARE 	v2_count_pastdata		    INT;
             DECLARE 	v3_count_currentdata 		INT;
 			DECLARE 	v3_count_pastdata		    INT;
  			
             SET v_offset =  p_Limit * p_offset;   
             
          	SET v_currenttimestamp := unix_timestamp(NOW()) * 1000;
 			SET v_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 3 DAY))* 1000;
 			SET v_oneday_previous_timestamp := unix_timestamp(DATE_SUB(NOW(), INTERVAL 2 DAY)) *1000;   
 
  
 			IF IFNULL(p_startTmpstmp,0)= 0 THEN 	SET p_startTmpstmp = unix_timestamp(DATE_SUB(now(), INTERVAL +2 DAY))*1000; ELSE SET v_startTmpstmp = p_startTmpstmp; END IF; 
 			IF IFNULL(p_endTmpstmp,0) = 0  	THEN 	SET p_endTmpstmp =  unix_timestamp(now())*1000; ELSE SET v_endTmpstmp = p_endTmpstmp; END IF;  						
             
 			DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	CREATE TEMPORARY TABLE temp_queueIDs(queueId INT);
  	    
            
           	CALL split(p_queueId,','); INSERT INTO temp_queueIDs(queueId) SELECT Items FROM tt_Split_temptable;
       	
               
  			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
               
 			  DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
               CREATE TEMPORARY TABLE temp_AllqueueId
               SELECT qid,name as queueName from queue where domainId = p_domainId ;
               
     	                                               
             
             
             SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
             DROP TEMPORARY TABLE IF EXISTS temp_chatHistory; 
  		   CREATE TEMPORARY TABLE temp_chatHistory as
     
             SELECT 	 
     					 CAST(FROM_UNIXTIME(CH.sessionStartTime/1000)  AS DATE) 		   						 							AS SessionDate
     					,Q.qid																												AS queueId
     					,CASE WHEN Q.name IS NOT NULL THEN Q.name ELSE '-'  END         													AS queueName
                         ,(COUNT(1))																										AS ReceivedChats
 						,COUNT(CASE WHEN CH.repliedDate - CH.createdAt IS NOT NULL THEN 1 ELSE NULL END) 									AS RespondedChats
 						,COUNT(CASE WHEN CH.disconnectedBy IS NOT NULL THEN 1 ELSE NULL END) 												AS AbandonedChats	
     			FROM 	tb_ChatHistory 			CH
     			JOIN 	tb_ChatDurationHistory	CDH	    ON CH.ChatHistoryId = CDH.ChatHistoryId
     			LEFT JOIN 	tb_User				U	    ON U.UserID			= CDH.AgentId
     			LEFT JOIN 	queue				Q	    ON CDH.QueueId		= Q.qid
     			LEFT JOIN temp_queueIDs 		t_Q     ON Q.qid			= t_Q.queueId 
     		
     			WHERE 	CH.domainId 			= p_domainId 		
     		
     		
                 group by CH.sessionStartTime,Q.qid,Q.name
     			LIMIT v_offset, p_Limit;  
     			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
  				
                 select * from temp_AllqueueId;
                 SELECT COUNT(1) totalCount FROM temp_chatHistory;
          
     
    
    
    
    
  		    SELECT 	COUNT(1) 
     		INTO 	v1_count_currentdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		and 	domainId	= p_domainId
             LIMIT 1;
             
     		
     		SELECT COUNT(1)
     		INTO 	v1_count_pastdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	domainId	= p_domainId
 			LIMIT 1;   
 	
     
     
    
     		
     		SELECT 	(case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end) as  RespondedChats
     		INTO 	v2_count_currentdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		and 	domainId	= p_domainId
               LIMIT 1;
             
     		
     		SELECT 	(case when (repliedDate - createdAt) is not null then (repliedDate - createdAt) else '0' end) as  RespondedChats
     		INTO 	v2_count_pastdata 
     		FROM 	tb_ChatHistory
     		WHERE 	sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	domainId	= p_domainId
 			LIMIT 1;
             
      
     
     		
     		SELECT (CASE WHEN SH.disconnectedBy IS NOT NULL THEN disconnectedBy else '0'	END) 								    AS abondedchats
     		INTO 	v3_count_currentdata 
     		FROM 	tb_ChatDurationHistory  SDH  JOIN
     				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
     		WHERE 	SH.sessionStartTime BETWEEN v_previous_timestamp AND v_currenttimestamp
     		and 	domainId	= p_domainId
     		LIMIT 1;
             
     		
     		SELECT  (CASE WHEN SH.disconnectedBy IS NOT NULL THEN 	disconnectedBy else '0'	end) 								AS abondedchats
     		INTO 	v3_count_pastdata 
     		FROM 	tb_ChatDurationHistory  SDH  JOIN
     				tb_ChatHistory   		SH    ON SDH.ChatHistoryId    = SH.ChatHistoryId
     		WHERE 	SH.sessionStartTime BETWEEN v_oneday_previous_timestamp AND v_previous_timestamp
     		and 	domainId	= p_domainId
     		LIMIT 1;   
             
             
 
 
                   IF NOT EXISTS(select 1 FROM temp_chatHistory limit 1) then
  					SELECT '-' as queueName, 0 AS totalreceivedchats, 0 AS Receivedchatdifference, 0 AS Receivedchatdiffpercentage, 0 AS totalRespondedChats ,
                     0 AS Respondedchatdifference ,0 AS Respondedchatdiffpercentage,0 as totalabondedchats,0 as abondedchatssdifference,0 as abondedchatssdiffpercentage;
                      leave sp_return;
                   end if;
             
                 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;	 
     			   SELECT 
                 
  						IFNULL(queueName,0)								 								                              			  AS queueName,
 						IFNULL (ReceivedChats,0)																							      AS TotalReceivedChats,	
                         IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata  ),0)		                                  AS Receivedchatdifference,
 						IFNULL(((v1_count_currentdata - v1_count_pastdata) / v1_count_currentdata )*100,0)		                             	  AS Receivedchatdiffpercentage,
 						IFNULL(RespondedChats,0)																								  as TotalRespondedChats,
  						IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata ),0)										      AS Respondedchatdifference,
 						IFNULL(((v2_count_currentdata - v2_count_pastdata) / v2_count_currentdata )*100,0)										  AS Respondedchatdiffpercentage,
  						IFNULL((AbandonedChats),0) 						 																          AS Totalabondedchats,
  						IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata ),0)		                                 	  AS Tbondedchatssdifference,
                         IFNULL(((v3_count_currentdata - v3_count_pastdata) / v3_count_currentdata )*100,0)		                                  AS Abondedchatssdiffpercentage
  						FROM 
  						temp_chatHistory 
  					    GROUP BY queueName,ReceivedChats,RespondedChats,AbandonedChats;
                             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     			
                 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertChatFlowVariables` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertChatFlowVariables`(	
  p_domainId			INT
 ,p_chatFlowId			INT
 ,p_chatFlowVariable	VARCHAR(500)
 ,p_chatFlowValue		VARCHAR(500)
 )
BEGIN        	
	DECLARE v_CurDate		DATETIME DEFAULT NOW();
    DECLARE v_errCode		INT;     
    DECLARE v_errMsg		VARCHAR(200); 
     
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    IF EXISTS (	SELECT 	1
				FROM 	tb_ChatFlowVariables
                WHERE 	domainId			= p_domainId	
				AND 	chatFlowId			= p_chatFlowId
				AND 	chatFlowVariable	= p_chatFlowVariable)
    THEN
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
		SET v_errCode 	= -1;
        SET v_errMsg	= 'ChatFlow variable already exists';
    ELSE
		INSERT INTO tb_ChatFlowVariables
		(	domainId				
			,chatFlowId				
			,chatFlowVariable	
			,chatFlowValue
			,createdAt				
			,updateAt	)
		VALUES
		(	 p_domainId		
			,p_chatFlowId		
			,p_chatFlowVariable
			,p_chatFlowValue	
			,v_CurDate
			,v_CurDate ); 	
            
		SET v_errCode 	= 0;
		SET v_errMsg	= 'ChatFlow variable saved successfully';     
	END IF;	
     
	SELECT v_errCode AS errCode, v_errMsg AS errMsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertCustomerContact` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertCustomerContact`(
  p_firstName		VARCHAR(100)	
  ,p_lastName			VARCHAR(100)
  ,p_phoneNumber		VARCHAR(20)
  ,p_email				VARCHAR(100)
  ,p_accountNumber		VARCHAR(100)
  ,p_tags				VARCHAR(100)
  ,p_location			VARCHAR(100)
  ,p_address			VARCHAR(225)
  ,p_country			VARCHAR(100)
  ,p_state				VARCHAR(100)
  ,p_city				VARCHAR(100)
  ,p_postalCode			VARCHAR(100)
  ,p_facebook			VARCHAR(100)
  ,p_instagram			VARCHAR(100)
  ,p_whatsapp			VARCHAR(100)
  ,p_twitter			VARCHAR(100)
  ,p_domainId			INT
  ,p_voiceBiometric		VARCHAR(100)
  ,p_customerType		VARCHAR(255)
  )
Logic_Block:BEGIN
  	DECLARE v_coid					INT;
	DECLARE v_Curdate				DATETIME;    
	DECLARE v_firstName				varchar(100);
	DECLARE v_lastName				varchar(100);
	DECLARE v_phoneNumber			varchar(750);
	DECLARE v_email					varchar(1500);
	DECLARE v_accountNumber			varchar(100);
	DECLARE v_tags					varchar(750);
	DECLARE v_location				varchar(100);
	DECLARE v_address				varchar(225);
	DECLARE v_country				varchar(100);
	DECLARE v_state					varchar(100);
	DECLARE v_city					varchar(100);
	DECLARE v_postalCode			varchar(100);
	DECLARE v_facebook				varchar(100);
	DECLARE v_instagram				varchar(100);
	DECLARE v_whatsapp				varchar(100);
	DECLARE v_twitter				varchar(100);
	DECLARE v_domainId				int;
	DECLARE v_voiceBiometric		varchar(100);
	DECLARE v_customerType			varchar(255);
      
	SET v_Curdate = NOW();
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
	SELECT 	coid	INTO v_coid
	FROM 	customer_contact CC
	WHERE 	CC.domainId = p_domainId
	AND 	(	CC.phoneNumber 	= p_phoneNumber 
			OR 	CC.email 		= p_email)
	LIMIT 1;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    
	IF JSON_VALID(p_phoneNumber) = 0
	THEN
		SELECT 	v_coid				coid
			,	v_firstName			firstName		
			,	v_lastName			lastName		
			,	v_phoneNumber		phoneNumber	
			,	v_email				email			
			,	v_accountNumber		accountNumber	
			,	v_tags				tags			
			,	v_location			location		
			,	v_address			address		
			,	v_country			country		
			,	v_state				state			
			,	v_city				city			
			,	v_postalCode		postalCode		
			,	v_facebook			facebook		
			,	v_instagram			instagram		
			,	v_whatsapp			whatsapp		
			,	v_twitter			twitter		
			,	v_domainId			domainId		
			,	v_voiceBiometric	voiceBiometric	
			,	v_customerType		customerType
  			,	v_Curdate
			,	v_Curdate
            ,	-1					errcode
            ,	'Phone Number is not in valid Json format'	errmsg;
		
		LEAVE Logic_Block;
	ELSEIF JSON_VALID(p_email) = 0
	THEN
		SELECT 	v_coid				coid
			,	v_firstName			firstName		
			,	v_lastName			lastName		
			,	v_phoneNumber		phoneNumber	
			,	v_email				email			
			,	v_accountNumber		accountNumber	
			,	v_tags				tags			
			,	v_location			location		
			,	v_address			address		
			,	v_country			country		
			,	v_state				state			
			,	v_city				city			
			,	v_postalCode		postalCode		
			,	v_facebook			facebook		
			,	v_instagram			instagram		
			,	v_whatsapp			whatsapp		
			,	v_twitter			twitter		
			,	v_domainId			domainId		
			,	v_voiceBiometric	voiceBiometric	
			,	v_customerType		customerType
  			,	v_Curdate
			,	v_Curdate
            ,	-1					errcode
            ,	'Email is not in valid Json format'	errmsg;		
		
		LEAVE Logic_Block;
	END IF;
    
      IF v_coid IS NULL
      THEN
  		INSERT INTO customer_contact
          (	 firstName		
              ,lastName			
              ,phoneNumber		
              ,email			
              ,accountNumber	
              ,tags				
              ,location			
              ,address			
              ,country			
              ,state			
              ,city				
              ,postalCode		
              ,facebook			
              ,instagram		
              ,whatsapp			
              ,twitter			
              ,domainId			
              ,voiceBiometric	
              ,customerType
              ,createdAt
			  ,updatedAt
  		)
          VALUES 
  		(	p_firstName		
  			,p_lastName			
  			,p_phoneNumber		
  			,p_email			
  			,p_accountNumber	
  			,p_tags				
  			,p_location			
  			,p_address			
  			,p_country			
  			,p_state			
  			,p_city				
  			,p_postalCode		
  			,p_facebook			
  			,p_instagram		
  			,p_whatsapp			
  			,p_twitter			
  			,p_domainId			
  			,p_voiceBiometric	
  			,p_customerType		
  			,v_Curdate
  			,v_Curdate
  		);    
          
          SET v_coid = LAST_INSERT_ID();        
      END IF; 
      
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
	SELECT 	coid
			,firstName		
			,lastName		
			,phoneNumber	
			,email			
			,accountNumber	
			,tags			
			,location		
			,address		
			,country		
			,state			
			,city			
			,postalCode		
			,facebook		
			,instagram		
			,whatsapp		
			,twitter		
			,domainId		
			,voiceBiometric	
			,customerType
  			,v_Curdate
			,v_Curdate
            ,0			errcode
            ,'Success'	errmsg
      FROM 	customer_contact CC    
      WHERE coid = v_coid;	
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
  END ;;
DELIMITER ;
