CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertPlanRecharge_1`(	
p_planId				INT
,p_domainId				INT
,p_planrechargeTime		DATETIME
,p_planStartTime		DATETIME
,p_planEndTime			DATETIME
,p_noOfPlanChatSession	INT     
,p_isUnilimitedChat		TINYINT    
  )
BEGIN
  	DECLARE v_curDate			DATETIME DEFAULT NOW();
      DECLARE v_existingPlanId	INT;	
      DECLARE v_errCode			TINYINT DEFAULT -1;
      DECLARE v_errMsg			VARCHAR(250) DEFAULT 'Plan recharge failed';
      DECLARE v_planRechargeId	INT;
      
      INSERT INTO tb_PlanRecharge
      (	planId				
          ,domainId			
          ,planrechargeTime	
          ,planStartTime		
          ,planEndTime		
          ,noOfPlanChatSession	
          ,isUnilimitedChat
          ,createdDate		
          ,updatedDate		
      )
      VALUES
      (	p_planId			
          ,p_domainId			
          ,p_planrechargeTime	
          ,p_planStartTime	
          ,p_planEndTime		
          ,p_noOfPlanChatSession	
          ,p_isUnilimitedChat
          ,v_curDate
          ,v_curDate
      );
      
      SET v_planRechargeId = last_insert_id();    
      
    SELECT 'kms', v_curDate, p_planStartTime, p_planEndTime;  
    
  	IF v_curDate BETWEEN p_planStartTime AND p_planEndTime
      THEN
  		UPDATE 	tb_PlanRecharge
          SET 	isChatSessionMovedToCurrentPlan = 1 
          WHERE 	planRechargeId = v_planRechargeId;
          
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
  		IF EXISTS (	SELECT 	1 
  					FROM 	tb_CurrentPlan	
  					WHERE 	domainId	= p_domainId)
  		THEN
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
  			UPDATE 	tb_CurrentPlan
  			SET 	planId				 = p_planId			
  				,	chatRemainingSession = p_noOfPlanChatSession
                  ,	isUnilimitedChat	 = p_isUnilimitedChat
  				,	updatedDate			 = v_curDate
  			WHERE 	domainId			 = p_domainId;		
  		ELSE
  			INSERT INTO tb_CurrentPlan
  			(	planId					
  				,domainId				
  				,chatRemainingSession	
                  ,isUnilimitedChat
  				,createdDate			
  				,updatedDate	
  			)
  			VALUES
  			(	p_planId
  				,p_domainId
  				,p_noOfPlanChatSession
				,p_isUnilimitedChat
  				,v_curDate
  				,v_curDate
  			);
  		END IF;    
      END IF;
      
      SET v_errCode	= 0
  	,	v_errMsg	= 'Plan recharged successfully';    
      
  	SELECT v_errCode	 AS errCode, v_errMsg	AS errMsg;
  END ;;
