CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertPlanRecharge_v2`(	
   p_planId					INT
   ,p_domainId					INT
   ,p_planrechargeTime			DATETIME
   ,p_planStartTime			DATETIME
   ,p_planEndTime				DATETIME
   ,p_noOfPlanChatSessionAgent	INT     
   ,p_noOfPlanChatSessionBot	INT     
   ,p_isUnilimitedChat			TINYINT 
   ,p_TotalSession				INT   
      )
BEGIN
    	DECLARE v_curDate			DATETIME DEFAULT NOW();
    	DECLARE v_existingPlanId	INT;	
    	DECLARE v_errCode			TINYINT DEFAULT -1;
    	DECLARE v_errMsg			VARCHAR(250) DEFAULT 'Plan recharge failed';
    	DECLARE v_planRechargeId	INT;
        
        
        if not exists(select 1 from tb_PlanRecharge where planId = p_planId and domainId = p_domainId) then
          
          INSERT INTO tb_PlanRecharge
          (	planId				
              ,domainId			
              ,planrechargeTime	
              ,planStartTime		
              ,planEndTime		
              ,noOfPlanChatSessionAgent	
              ,noOfPlanChatSessionBot
              ,isUnilimitedChat
              ,createdDate		
              ,updatedDate	
              ,TotalSession
          )
          VALUES
          (	p_planId			
              ,p_domainId			
              ,p_planrechargeTime	
              ,p_planStartTime	
              ,p_planEndTime		
              ,p_noOfPlanChatSessionAgent
              ,p_noOfPlanChatSessionBot
              ,p_isUnilimitedChat
              ,v_curDate
              ,v_curDate
              ,p_TotalSession
          );
          
          SET v_planRechargeId = last_insert_id();  
		Else
			update tb_PlanRecharge
            set planrechargeTime 			= p_planrechargeTime
				,planStartTime	 			= p_planStartTime
				,planEndTime				= p_planEndTime
				,noOfPlanChatSessionAgent	= p_noOfPlanChatSessionAgent
				,noOfPlanChatSessionBot 	= p_noOfPlanChatSessionBot
				,isUnilimitedChat 			= p_isUnilimitedChat	
				,updatedDate	 			= v_curDate
				,TotalSession 				= p_TotalSession
            where planId = p_planId and domainId = p_domainId;
            
            select planRechargeId into v_planRechargeId from tb_PlanRecharge where planId = p_planId and domainId = p_domainId;
            
        End if;
          
      	IF v_curDate BETWEEN p_planStartTime AND p_planEndTime
          THEN
      		UPDATE 	tb_PlanRecharge
              SET 	isChatSessionMovedToCurrentPlan = 1 
              WHERE 	planRechargeId = v_planRechargeId;
              
              SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      		IF EXISTS (	SELECT 	1 
      					FROM 	tb_CurrentPlan	
      					WHERE 	domainId	= p_domainId)
      		THEN
      		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
  				UPDATE 	tb_CurrentPlan
  				SET 	planId				 		= p_planId			
  					,	chatRemainingSessionAgent 	= p_noOfPlanChatSessionAgent
  					,	chatRemainingSessionBot 	= p_noOfPlanChatSessionBot
  					,	isUnilimitedChat	 		= p_isUnilimitedChat
  					,	updatedDate			 		= v_curDate
                      ,	TotalSession				= p_TotalSession
                      ,	TotalSessionUsed			= 0
 
  				WHERE 	domainId			 		= p_domainId;		
      		ELSE
  				INSERT INTO tb_CurrentPlan
  				(	planId					
  					,domainId				
  					,chatRemainingSessionAgent	
  					,chatRemainingSessionBot
  					,isUnilimitedChat
  					,createdDate			
  					,updatedDate
  					,TotalSession
 					,TotalSessionUsed
 
                      
  				)
  				VALUES
  				(	p_planId
  					,p_domainId
  					,p_noOfPlanChatSessionAgent
  					,p_noOfPlanChatSessionBot
  					,p_isUnilimitedChat
  					,v_curDate
  					,v_curDate
 					,p_TotalSession
 					,0
  				);
      		END IF;    
          END IF;
          
          SET 	v_errCode	= 0
    		,	v_errMsg	= 'Plan recharged successfully';    
          
      	SELECT v_errCode	 AS errCode, v_errMsg	AS errMsg;
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
