CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateAgentAnalytics_config`(   
     p_domainId        INT,
     p_ext             INT,
     p_editColumnNames LONGTEXT,
     p_id			   TINYINT
)
BEGIN
    DECLARE v_errcode          INT DEFAULT -1;
    DECLARE v_errmsg           VARCHAR(55) DEFAULT 'No Record to Config';
    DECLARE v_CurDate          DATETIME;
    DECLARE v_ecId             INT;

    SET v_CurDate = NOW();

    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SELECT ecId INTO v_ecId
    FROM agentEditColumns EC
    WHERE EC.domainId = p_domainId
    AND EC.ext = p_ext
    AND EC.id  = p_id;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    IF v_ecId IS NULL THEN
        INSERT INTO agentEditColumns
            (domainId,
            ext,
            id,
            editColumnNames,
            createdAt,
            updatedAt)
        VALUES
            (p_domainId,
            p_ext,
            p_id,
            p_editColumnNames,
            v_CurDate,
            v_CurDate);

        SET v_ecId = LAST_INSERT_ID();
        SET v_errcode = 0;
        SET v_errmsg = 'Configuration Inserted Successfully';
        ELSE
        UPDATE agentEditColumns
        SET editColumnNames = p_editColumnNames,
            updatedAt = v_CurDate
        WHERE ecId = v_ecId;

        SET v_errcode = 0;
        SET v_errmsg = 'Configuration Updated Successfully';
    END IF;

    SELECT v_ecId AS ecId, p_domainId AS domainId, p_ext AS ext, p_editColumnNames AS editColumnNames, v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateAgentSmsAnalytics_config` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateAgentSmsAnalytics_config`(   
     p_domainId        INT,
     p_ext             INT,
     p_editColumnNames LONGTEXT,
     p_id			   TINYINT
)
BEGIN
    DECLARE v_errcode          INT DEFAULT -1;
    DECLARE v_errmsg           VARCHAR(55) DEFAULT 'No Record to Config';
    DECLARE v_CurDate          DATETIME;
    DECLARE v_smsId             INT;

    SET v_CurDate = NOW();

    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SELECT smsId INTO v_smsId
    FROM agentSmsEditColumns EC
    WHERE EC.domainId = p_domainId
    AND EC.ext = p_ext
    AND EC.id  = p_id;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    IF v_smsId IS NULL THEN
        INSERT INTO agentSmsEditColumns
            (domainId,
            ext,
            id,
            editColumnNames,
            createdAt,
            updatedAt)
        VALUES
            (p_domainId,
            p_ext,
            p_id,
            p_editColumnNames,
            v_CurDate,
            v_CurDate);

        SET v_smsId = LAST_INSERT_ID();
        SET v_errcode = 0;
        SET v_errmsg = 'Configuration Inserted Successfully';
        ELSE
        UPDATE agentSmsEditColumns
        SET editColumnNames = p_editColumnNames,
            updatedAt = v_CurDate
        WHERE smsId = v_smsId;

        SET v_errcode = 0;
        SET v_errmsg = 'Configuration Updated Successfully';
    END IF;

    SELECT v_smsId AS smsId, p_domainId AS domainId, p_ext AS ext, p_editColumnNames AS editColumnNames, v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
