CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateBusinessHolidays`(
 	p_BusinessHoursHolidaysId	INT
 	,p_BusinessHoursId			INT
 	,p_HolidayName				VARCHAR(100)
 	,p_HolidayDescription		VARCHAR(250)
 	,p_FromDate					DATE
 	,p_ToDate					DATE
 	,p_IsActive					TINYINT
 	,p_IsDeleted				TINYINT
 	,p_LoggedInUserId			BIGINT
 )
BEGIN
 	DECLARE v_BusinessHoursHolidaysId	INT;
     DECLARE v_curDate					DATETIME DEFAULT NOW();
     DECLARE v_errCode					TINYINT DEFAULT 0;
     DECLARE v_errMsg					VARCHAR(200) DEFAULT 'Add/Update Business Holidays Failed';
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 	SELECT	BusinessHoursHolidaysId INTO v_BusinessHoursHolidaysId
 	FROM 	tb_TicketBusinessHoursHolidays
     WHERE 	BusinessHoursHolidaysId = p_BusinessHoursHolidaysId
 	AND		IsDeleted		= 0;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     
     IF v_BusinessHoursHolidaysId IS NULL
     THEN
 		INSERT INTO tb_TicketBusinessHoursHolidays(
 			BusinessHoursId
 			,HolidayName
 			,HolidayDescription
 			,FromDate
 			,ToDate
 			,IsActive
 			,IsDeleted
 			,CreatedBy
 			,CreatedDate
 			,UpdatedBy
 			,UpdatedDate
         )
         VALUES(
 			 p_BusinessHoursId			
             ,p_HolidayName				
             ,p_HolidayDescription		
             ,p_FromDate					
             ,p_ToDate					
             ,p_IsActive					
             ,p_IsDeleted				
             ,p_LoggedInUserId
 			,v_curDate
             ,p_LoggedInUserId
 			,v_curDate
         );
         
         SET v_BusinessHoursHolidaysId	= LAST_INSERT_ID()
 		,	v_errCode	= 1 
         ,	v_errMsg	= 'Added Business Holidays successfully';
 	ELSE
 		UPDATE 	tb_TicketBusinessHoursHolidays
         SET 	BusinessHoursId			= p_BusinessHoursId			
 			,	HolidayName				= p_HolidayName				
 			,	HolidayDescription		= p_HolidayDescription		
 			,	FromDate				= p_FromDate					
 			,	ToDate					= p_ToDate					
 			,	IsActive				= p_IsActive					
 			,	IsDeleted				= p_IsDeleted					
 			,	UpdatedBy				= p_LoggedInUserId
 			,	UpdatedDate				= v_curDate
 		WHERE 	BusinessHoursHolidaysId = v_BusinessHoursHolidaysId;
         
         SET v_errCode	= 2 
         ,	v_errMsg	= 'Updated Business Holidays successfully';
     END IF;	
     
     SELECT v_errCode AS errCode, v_errMsg AS errMsg;           
 END ;;
DELIMITER ;
