CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateBusinessHours`(
      IN p_BusinessHoursId     	INT,
      IN p_CompanyId           	INT,
      IN p_ProductId           	INT,
      IN p_Name                	VARCHAR(255),
      IN p_Description         	VARCHAR(255),
      IN p_Timezone            	VARCHAR(100),
      IN p_IsDeleted           	TINYINT,
      IN p_BusinessHoursTimings	JSON,
	  IN p_LoggedInUserID 	  	BIGINT       
   )
BEGIN
	declare v_errcode 			int;
	declare v_errmsg 			varchar(55);
	declare v_CurDate			DATETIME;
	declare v_BusinessHoursId	int;
	declare v_JLength			int;    
      
 	SET v_CurDate = NOW();
      
 	SELECT 	BusinessHoursId	INTO v_BusinessHoursId
 	FROM 	tb_TicketBusinessHours
 	WHERE 	BusinessHoursId = p_BusinessHoursId;
       
  	sp_exit : begin
  		 IF v_BusinessHoursId IS NOT NULL
  		 THEN
			IF p_IsDeleted = 1
            THEN
				UPDATE 	tb_TicketBusinessHours
                SET 	IsDeleted 		= p_IsDeleted
                WHERE 	BusinessHoursId = v_BusinessHoursId;
				
                SET v_errcode         = 0;
  				SET v_errmsg          = 'Deleted successfully';
  				LEAVE sp_exit;
            END IF;
            
  			 UPDATE tb_TicketBusinessHours
  			 SET	`Name`          	= ifnull(p_Name,`Name`)
  					,Description     	= ifnull(p_Description,Description)
  					,Timezone        	= ifnull(p_Timezone,Timezone)          
  					,IsDeleted		 	= ifnull(p_IsDeleted,IsDeleted)
  					,UpdatedBy       	= p_LoggedInUserID
  					,UpdatedDate     	= v_CurDate
  			 WHERE 	BusinessHoursId 	= v_BusinessHoursId;
  								
  			if row_count()>0
  			then 				
  				set v_errcode         = 0;
  				set v_errmsg          = 'updated successfully';
  				leave sp_exit;
  			end if;
  		 ELSE
  			 INSERT INTO tb_TicketBusinessHours (
  				 CompanyId,
                   ProductId,
                   Name,
                   Description,
                   Timezone,
                   IsDeleted,
                   CreatedBy,
                   CreatedDate,
                   UpdatedBy,
                   UpdatedDate
  			 ) VALUES (
  				 p_CompanyId,
  				 p_ProductId,
  				 p_Name,
  				 p_Description,
  				 p_Timezone,
 				 0,
  				 p_LoggedInUserID,
  				 v_CurDate,
  				 p_LoggedInUserID,
  				 v_CurDate
  			 );
  			 
  			if row_count() > 0
  			then
                 SET v_BusinessHoursId = LAST_INSERT_ID();
 				SET v_errcode = 0;
 				SET v_errmsg = 'Inserted successfully';				
  			end if;			
  		end if;
  	end sp_exit;  
 	
 	SET v_JLength = JSON_LENGTH(p_BusinessHoursTimings, "$");
 
 	DROP TEMPORARY TABLE IF EXISTS tt_BusinessHoursTimings;
 	CREATE TEMPORARY TABLE tt_BusinessHoursTimings       
 	WITH RECURSIVE  CTE_JsonCount as
 	(	SELECT 	0 SlNo
 		UNION ALL
 		SELECT 	SlNo + 1	SlNo
 		FROM 	CTE_JsonCount
 		WHERE 	SlNo  < v_JLength - 1
 	)
 	SELECT  TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].BusinessHoursTimingsId')))) AS BusinessHoursTimingsId,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].BusinessDayTypeId')))) AS BusinessDayTypeId,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].from_midday')))) AS from_midday,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].from_hour')))) AS from_hour,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].to_midday')))) AS to_midday,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].to_hour')))) AS to_hour,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].total_hours')))) AS total_hours,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].IsDayOff')))) AS IsDayOff,
 			TRIM(BOTH '"' FROM (json_extract(p_BusinessHoursTimings, concat('$[',SlNo,'].is_deleted')))) AS is_deleted
 	FROM CTE_JsonCount;	
     
     INSERT INTO tb_TicketBusinessHoursTimings
     (	BusinessHoursId		
 		,BusinessDayTypeId		
 		,FromHours				
 		,FromAMPM	
 		,ToHours				
 		,ToAMPM		
 		,IsDayOff				
 		,IsDeleted				
 		,CreatedBy				
 		,CreatedDate				
 		,UpdatedBy				
 		,UpdatedDate			
     )
     SELECT 	v_BusinessHoursId
 			,BusinessDayTypeId
             ,from_hour
             ,from_midday
             ,to_hour
             ,to_midday
             ,IsDayOff
             ,is_deleted
 			,p_LoggedInUserID
 			,v_CurDate
 			,p_LoggedInUserID
 			,v_CurDate
     FROM 	tt_BusinessHoursTimings 
     WHERE 	BusinessHoursTimingsId 	= 0
     AND	is_deleted				= 0;
     
     UPDATE tb_TicketBusinessHoursTimings	BHT
     JOIN 	tt_BusinessHoursTimings			t_BHT	ON 	t_BHT.BusinessHoursTimingsId 	= BHT.BusinessHoursTimingsId													
	 SET	BHT.FromHours		= t_BHT.from_hour
			,BHT.FromAMPM	    = t_BHT.from_midday
			,BHT.ToHours		= t_BHT.to_hour
			,BHT.ToAMPM		    = t_BHT.to_midday
			,BHT.IsDayOff		= t_BHT.IsDayOff
			,BHT.IsDeleted		= t_BHT.is_deleted			
 			,BHT.CreatedDate	= v_CurDate
 			,BHT.UpdatedBy	    = p_LoggedInUserID
 			,BHT.UpdatedDate	= v_CurDate; 
   
  	SELECT v_BusinessHoursId as BusinessHoursId, v_errcode as errcode, v_errmsg as errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
