CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateCallConfiguration`(	
   		 p_name						TEXT
       	,p_contactCenterNumber		BIGINT
       	,p_domainId					INT
       	,p_Language					TEXT
       	,p_isBot					TINYINT
       	,p_callFlowId				INT
       	,p_greetingMessage			TEXT
       	,p_status					TINYINT
  		,p_intents					JSON
  		,p_virtualAgent         	TINYINT
  		,p_assistPriority       	TINYINT
         ,p_threshold				INT	
         ,p_isMultilingualStatus	TINYINT 
         ,p_humanAgent 				tinyint
       )
BEGIN
   	DECLARE v_CurDate				DATETIME;
   	DECLARE v_ErrCode				INT DEFAULT -1;
   	DECLARE v_ErrMsg				VARCHAR(100)   DEFAULT 'Call Configuration';
   	DECLARE v_contactCenterNumber	BIGINT;
   	DECLARE v_JsonLength			SMALLINT;    
   	DECLARE v_i						SMALLINT DEFAULT 1;  
   	DECLARE v_addIntents			VARCHAR(1000);
   	DECLARE v_queueId				INT;
   	DECLARE v_intentGroupId			SMALLINT;
  	DECLARE v_intents				JSON;
  	DECLARE v_cfid					VARCHAR(255);
   	 
   	SET v_CurDate = NOW();
      
 	SELECT cfid INTO v_cfid
 	FROM callFlow
 	WHERE callFlowId = p_callFlowId
 	AND domainId = p_domainId LIMIT 1;
   	
 	SET v_intents = IF(p_isBot=0,'[]',p_intents);
       
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
   	SELECT 	contactCenterNumber INTO v_contactCenterNumber
   	FROM 	call_configuration
   	WHERE 	contactCenterNumber = p_contactCenterNumber;
   	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
   	IF v_contactCenterNumber IS NULL
   	THEN
   		SET v_contactCenterNumber = p_contactCenterNumber;
   	   
   		INSERT INTO call_configuration 
   		(	contactCenterNumber
			,name			
			,domainId
			,Language
			,isBot
			,callFlowId
			,greetingMessage
			,status
			,virtualAgent
			,assistPriority
			,threshold
			,createdDate
			,updatedDate
			,isMultilingualStatus
			,humanAgent
   		)   
   		VALUES 
   		(	v_contactCenterNumber
			,p_name					             
			,p_domainId				
			,p_Language				
			,p_isBot				
			,p_callFlowId			
			,p_greetingMessage		
			,p_status
			,p_virtualAgent
			,p_assistPriority
			,p_threshold
			,v_CurDate
			,v_CurDate
			,p_isMultilingualStatus
			,p_humanAgent
   		);
   		
   		SET v_ErrCode	= 0
   		,	v_ErrMsg	= 'Call Configuration Inserted Successfully';
   	ELSE
   		UPDATE 	call_configuration 
   		SET 	name				= IFNULL(p_name,name)
   			,	Language			= IFNULL(p_Language,Language)
 			, 	isBot				= IFNULL(p_isBot,isBot)		
 			, 	callFlowId			= IFNULL(p_callFlowId,callFlowId)
 			,	greetingMessage		= IFNULL(p_greetingMessage,greetingMessage)
 			,	status				= IFNULL(p_status,status)
 			,   virtualAgent       	= IFNULL(p_virtualAgent,virtualAgent)
 			,   assistPriority     	= IFNULL(p_assistPriority,assistPriority)
 			,	threshold			= IFNULL(p_threshold,threshold)
 			,	updatedDate			= v_CurDate
 			,	isMultilingualStatus = IFNULL(p_isMultilingualStatus,isMultilingualStatus)
            ,	humanAgent			 = IFNULL(p_humanAgent,humanAgent)
   		WHERE 	contactCenterNumber	= v_contactCenterNumber
   		AND 	domainId			= p_domainId;
   		
   		SET v_ErrCode	= 0
   		,	v_ErrMsg	= 'Call Configuration Updated Successfully';
   	END IF; 
           
   	UPDATE 	did_purchase 
   	SET 	isBot		= IFNULL(p_isBot,isBot)
     ,		status		= IFNULL(p_status,status)
   	WHERE 	your_number = v_contactCenterNumber
   	AND 	domainId 	= p_domainId;
      
      IF p_callFlowId <> 0  
      THEN
 		UPDATE callMap
 		SET callFlowId = v_cfid
 		WHERE domainId = p_domainId
 		AND CAST(sourceId AS CHAR) = v_contactCenterNumber;
         
 		UPDATE 	did_purchase 
 		SET 	callFlowId	= v_cfid
 		WHERE 	your_number = v_contactCenterNumber
 		AND 	domainId 	= p_domainId;
      END IF;
       
       DELETE 	IQ
   	FROM 	tb_mapIntentQueue 	IQ
   	WHERE 	IQ.contactCenterNumber 	= v_contactCenterNumber;
     
   	SET v_JsonLength = JSON_LENGTH(v_intents,'$');    
       	
      	DROP TEMPORARY TABLE IF EXISTS temp_mapIntentQueue;
      	CREATE TEMPORARY TABLE temp_mapIntentQueue
   	WITH RECURSIVE  CTE_JsonCount as
   	(	SELECT 	0 SlNo
   		UNION ALL
   		SELECT 	SlNo + 1	SlNo
   		FROM 	CTE_JsonCount
   		WHERE 	SlNo  < v_JsonLength - 1
   	)
   	SELECT	json_extract(v_intents, concat('$[',SlNo,'].addIntents')) 		AS addIntents
   		,	json_extract(v_intents, concat('$[',SlNo,'].queueId')) 			AS queueId
   		,	json_extract(v_intents, concat('$[',SlNo,'].intentGroupId')) 	AS intentGroupId			
   		,	SlNo+1															AS SlNo
   	FROM CTE_JsonCount;   
              
   	WHILE v_JsonLength  >= v_i 
   	DO
   		SET v_addIntents	= NULL
   		, 	v_queueId		= NULL
   		,	v_intentGroupId	= NULL;
   		
   		SELECT 	REPLACE(addIntents,'"','') AS addIntents,queueId, intentGroupId
   		INTO 	v_addIntents, v_queueId,v_intentGroupId	
   		FROM 	temp_mapIntentQueue 
   		WHERE 	SlNo	= v_i;	
   		
   		IF ifnull(v_intentGroupId,0) = 0
   		THEN
   			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
   			SET v_intentGroupId = (SELECT MAX(intentGroupId) FROM tb_mapIntentQueue WHERE contactCenterNumber = p_contactCenterNumber);
               
   			SET v_intentGroupId = IFNULL(v_intentGroupId,0) + 1;
   		END IF; 
   		
   		DROP TEMPORARY TABLE IF EXISTS temp_Intents; 
   		CREATE TEMPORARY TABLE temp_Intents(Intent VARCHAR(150));        
   		
   		CALL Split(v_addIntents,',');        
   		
   		INSERT INTO temp_Intents
   		SELECT * FROM tt_Split_temptable;
   		
   		INSERT INTO tb_mapIntentQueue
   		(	contactCenterNumber
   			,intentGroupId
   			,queueId
   			,intents
   			,domainId
   			,createdDate
   			,updatedDate
   		)
   		SELECT   
   			v_contactCenterNumber
   			,v_intentGroupId
   			,v_queueId
   			,Intent
   			,p_domainId
   			,v_CurDate
   			,v_CurDate
   		FROM temp_Intents			t_I;
           
   		SET v_i = v_i + 1;
   	END WHILE; 
   	SELECT v_ErrCode AS errCode, v_ErrMsg AS errMsg;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
