CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateChatAIMessage`(
 	p_ChatHistoryId	BIGINT
  	,p_AIMessage	JSON 
     ,p_sessionId varchar(250)
  )
BEGIN
  	DECLARE v_ChatHistoryId	BIGINT;
      DECLARE v_CurDate		DATETIME;
      DECLARE v_errcode		INT;
      DECLARE v_errMsg		varchar(250);
      
      SET v_CurDate = NOW();
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  	SELECT 	ChatHistoryId INTO v_ChatHistoryId	
      FROM 	tb_ChatAIMessage
      WHERE 	ChatHistoryId = p_ChatHistoryId;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
  
      IF v_ChatHistoryId IS NULL
      THEN
 			INSERT INTO tb_ChatAIMessage(ChatHistoryId,sessionId,AIMessage,CreatedDate,UpdatedDate)
 			VALUES(	p_ChatHistoryId,p_sessionId,p_AIMessage,v_CurDate,v_CurDate);    
          
          SET v_ChatHistoryId = last_insert_id();
          SET v_errcode	= 0;
          SET v_errMsg	= 'AIMessage added succesfully';
  	ELSE
  		UPDATE 	tb_ChatAIMessage
          SET 	AIMessage		= p_AIMessage
  			,	UpdatedDate		= v_CurDate
             ,	sessionId = p_sessionId
          WHERE 	ChatHistoryId 	= v_ChatHistoryId;
          
  		SET v_errcode	= 0;
          SET v_errMsg	= 'AIMessage updated succesfully';
      END IF;    
      
      SELECT v_errcode as errcode, v_errMsg as errMsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
