CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateChatArticle`(	
	p_ChatArticleId  		INT	
    ,p_DomainId				INT
    ,p_web_id				INT
    ,p_ChatCategoryId		INT
    ,p_FilePath				VARCHAR(250)
    ,p_ArticleLanguage		VARCHAR(50)
    ,p_LoggedUserId			INT
    ,p_knowledgeBaseType	INT
)
BEGIN
	DECLARE v_errcode 			INT 			DEFAULT -1;
	DECLARE v_errmsg 			VARCHAR(100) 	DEFAULT 'No Article';	
    DECLARE v_ChatArticleId		INT;
	DECLARE v_Curdate			DATETIME;
    
    SET v_Curdate = NOW();
    
    SELECT 	ChatArticleId INTO v_ChatArticleId
    FROM 	tb_ChatArticle
    WHERE 	ChatArticleId = p_ChatArticleId;
    
    IF v_ChatArticleId IS NULL
    THEN
		INSERT INTO tb_ChatArticle
        (	DomainId			
            ,web_id				
            ,ChatCategoryId		
            ,FilePath
            ,ArticleLanguage
            ,CreatedBy
            ,CreatedDate		
            ,UpdatedBy
            ,UpdatedDate
            ,knowledgeBaseType
        )
        VALUES
        (	p_DomainId			
            ,p_web_id			
            ,p_ChatCategoryId	
            ,p_FilePath			
            ,p_ArticleLanguage	  
            ,p_LoggedUserId
			,v_Curdate
            ,p_LoggedUserId
            ,v_Curdate
            ,p_knowledgeBaseType
        );
       
		SET v_ChatArticleId = last_insert_id();
        SET v_errcode 	= 0
		, 	v_errmsg 	= 'Article Added Successfully';
	ELSE
		UPDATE 	tb_ChatArticle
        SET 	ChatCategoryId			= IFNULL(p_ChatCategoryId,ChatCategoryId)
			,	UpdatedBy				= p_LoggedUserId
			,	knowledgeBaseType		= IFNULL(p_knowledgeBaseType,knowledgeBaseType)
			,	UpdatedDate				= v_Curdate			
		WHERE 	ChatArticleId 			= v_ChatArticleId;
        
        SET v_errcode 	= 0
		, 	v_errmsg 	= 'Article Update Successfully';
    END IF; 
    
    SELECT v_errcode 'errcode', v_errmsg 'errmsg'; 
END ;;
DELIMITER ;
