CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdatechatFlowHistory`(	
         p_chatFlowId		INT	
    	,p_templateName		VARCHAR(100)
    	,p_nodes			LONGTEXT
    	,p_edges			LONGTEXT
    	,p_version			VARCHAR(55)
    	,p_type				VARCHAR(50)
    	,p_status			INT
    	,p_companyId		INT
    	,p_domainId			INT
    	,p_description		LONGTEXT		
    	,p_publishData		LONGTEXT
    	,p_action			VARCHAR(25)
    	,p_category			VARCHAR(255)
        ,p_channelType		VARCHAR(50) 
        ,p_language			VARCHAR(100) 
    )
BEGIN
   	DECLARE v_errCode		INT	DEFAULT -1;
   	DECLARE v_errMsg		VARCHAR(150) DEFAULT 'No Chat Flow';
   	DECLARE	v_CurDate		DATETIME;
   	DECLARE v_chatFlowId	INT;    
    	
    	SET v_CurDate = NOW();    
        
    	SELECT 	chatFlowId INTO v_chatFlowId
        FROM 	chatFlowHistory
        WHERE 	chatFlowId = p_chatFlowId;
        
    	IF v_chatFlowId IS NULL
        THEN		
    		INSERT INTO chatFlowHistory
 		(	templateName
    			,nodes
    			,edges
    			,version
 			    ,channelType
    			,`type`
    			,`status`
    			,companyId
    			,domainId
    			,`description`
    			,publishData
    			,`action`
    			,category
                ,`language`
    			,createdAt
    			,updateAt            
            )
            values
            (	p_templateName	
                ,p_nodes		
                ,p_edges		
                ,p_version		
                ,p_channelType
                ,p_type			
                ,p_status		
                ,p_companyId	
                ,p_domainId		
                ,p_description	
                ,p_publishData	
                ,p_action		
                ,p_category		
                ,p_language
 			   ,v_CurDate
                ,v_CurDate
    		);
    		
            SET v_chatFlowId = last_insert_id();
            SET v_errCode	= 0;	
            SET v_errMsg	= 'Chat Flow Added Successfully';
    	ELSE
    		UPDATE	chatFlowHistory
            SET 	templateName	= p_templateName	
                    ,nodes			= p_nodes		
                    ,edges			= p_edges		
                    ,version		= p_version	
                    ,channelType	= p_channelType
                    ,`type`		    = p_type			
                    ,`status`		= p_status		
                    ,companyId		= p_companyId	
                 
                    ,`description`	= p_description	
                    ,publishData	= p_publishData	
                    ,`action`		= p_action		
                    ,category		= p_category		
                    ,`language`		= p_language
                    ,createdAt		= v_CurDate
                    ,updateAt       = v_CurDate
    		WHERE	chatFlowId 		= v_chatFlowId;  
            
             SET v_errCode	= 0;	
            SET v_errMsg	= 'Chat Flow Updated Successfully';
        END IF;
        
        SELECT v_chatFlowId 'chatFlowId',v_errCode'errCode',v_errMsg 'errMsg';	
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
