CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateChatHistory`(	
     		p_ChatHistoryId			BIGINT
           	,p_sessionId			VARCHAR(250)
           	,p_sessionStartTime		BIGINT
           	,p_sessionEndTime		BIGINT
           	,p_chatFlowSourceId		VARCHAR(100)
           	,p_companyId			INT
           	,p_domainId				INT
        
        
           	,p_IsInBound			TINYINT

           	,p_disconnectedBy		BIGINT
           	,p_queueDuration		BIGINT
           	,p_assignedTo			BIGINT
           	,p_assignedBy			BIGINT
           	,p_assignedOn			BIGINT
        
        
        
        
        
           	,p_CustomerId			INT
        
        
           	,p_Browser				VARCHAR(250)
       		,p_IPAdress				VARCHAR(250)    
       		,p_ChatSubject			VARCHAR(250) 
       		,p_Message				JSON
           	,p_StartTime			BIGINT
           	,p_EndTime				BIGINT
           	,p_Duration				BIGINT
           	,p_AgentId				BIGINT
           	,p_AgentSkillId			INT
           	,p_IsBot				TINYINT
           	,p_BotId				INT
           	,p_transferredTime		BIGINT
           	,p_QueueId				INT
       		,p_Location				varchar(100)
       		,p_DeviceType			varchar(100)
       		,p_CallBackStatus		TINYINT
   			,p_widgetId				INT
               ,p_IsMissed				TINYINT
            )
sp_return: BEGIN
        	DECLARE v_errCode		INT				DEFAULT -1;
        	DECLARE v_errMsg		VARCHAR(150) 	DEFAULT 'No Chat';
        	DECLARE	v_CurDate		DATETIME;
        	DECLARE	v_ChatHistoryId	BIGINT;
          DECLARE v_uuid 			varchar(40);
               
        	SET v_CurDate = NOW();
          
          
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		IF EXISTS(SELECT 1 FROM customer_contact where coid = p_CustomerId and  domainId = p_DomainId and blockCustomer = 1 ) 
    		THEN
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
    			SELECT -2 as errcode, 'Customer is blocked' as errmsg;
    			LEAVE sp_return;
    		END IF; 
            
        	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        	SELECT 	ChatHistoryId INTO v_ChatHistoryId
        	FROM 	tb_ChatHistory
        	WHERE 	ChatHistoryId = p_ChatHistoryId;
        	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
          
        	IF v_ChatHistoryId IS NULL
        	THEN
  			SET v_uuid = uuid();
          
        		INSERT INTO tb_ChatHistory	 
        		(	sessionId			
        			,sessionStartTime	
        			,sessionEndTime		
        			,chatFlowSourceId	
        			,companyId			
        			,domainId			
        
        
        			,IsInBound		
                   ,IsMissed

        			,disconnectedBy		
        			,queueDuration		
        			,assignedTo			
        			,assignedBy			
        			,assignedOn			
        
        
        
        
        
        			,CustomerId			
        
        
        			,Browser	
        			,IPAdress
        			,ChatSubject
        			,createdAt			
        			,updatedAt
        			,Location
        			,DeviceType
     			,CallBackStatus
                 ,chatWidgetId 
                 ,chatUniqIdentifier
        		)
        		VALUES
        		(	 p_sessionId		
        			,p_sessionStartTime	
        			,p_sessionEndTime	
        			,p_chatFlowSourceId	
        			,p_companyId		
        			,p_domainId			
        
        
        			,p_IsInBound	
                   ,p_IsMissed

        			,p_disconnectedBy	
        			,p_queueDuration	
        			,p_assignedTo		
        			,p_assignedBy		
        			,p_assignedOn		
        
        
        
        
        
        			,p_CustomerId		
        
        
        			,p_Browser	
        			,p_IPAdress	
        			,p_ChatSubject
        			,v_CurDate
        			,v_CurDate
        			,p_Location
        			,p_DeviceType
     			,p_CallBackStatus
                 ,p_widgetId
                 ,v_uuid
        		);        
                   
                   SET v_ChatHistoryId = last_insert_id();
                   SET v_errCode	= 0;
                   SET v_errMsg	= 'Chat Addded Successfully';
           	ELSE
           		UPDATE 	tb_ChatHistory
        		SET 	sessionId				= IFNULL(p_sessionId			,sessionId)				
        				,sessionStartTime	    = IFNULL(p_sessionStartTime	    ,sessionStartTime)
        				,sessionEndTime		    = IFNULL(p_sessionEndTime	    ,sessionEndTime)		    
        				,chatFlowSourceId	    = IFNULL(p_chatFlowSourceId	    ,chatFlowSourceId)	    
        				,companyId			    = IFNULL(p_companyId		    ,companyId)			    
        				,domainId			    = IFNULL(p_domainId			    ,domainId)			    
        
        
        				,IsInBound			    = IFNULL(p_IsInBound		    ,IsInBound)			    
                       ,IsMissed				= IFNULL(p_IsMissed				,IsMissed)

        				,disconnectedBy		    = IFNULL(p_disconnectedBy	    ,disconnectedBy)		    
        				,queueDuration		    = IFNULL(p_queueDuration	    ,queueDuration)		    
        				,assignedTo			    = IFNULL(p_assignedTo		    ,assignedTo)			    
        				,assignedBy			    = IFNULL(p_assignedBy		    ,assignedBy)			    
        				,assignedOn			    = IFNULL(p_assignedOn		    ,assignedOn)			    
        
        
        
        
        
        				,CustomerId			    = IFNULL(p_CustomerId		    ,CustomerId)			    
        
        
        				,updatedAt				= v_CurDate
        				,Location				= IFNULL(p_Location ,Location)
        				,DeviceType 			= IFNULL(p_DeviceType , DeviceType)
     				,CallBackStatus			= IFNULL(p_CallBackStatus, CallBackStatus)
                     ,chatWidgetId			= IFNULL(p_widgetId, chatWidgetId)
           		WHERE	ChatHistoryId 		= v_ChatHistoryId;   
                  
                  select chatUniqIdentifier into v_uuid from tb_ChatHistory where ChatHistoryId = v_ChatHistoryId limit 1;   
                   
        	   SET v_errCode	= 0;
        	   SET v_errMsg	= 'Chat Updated Successfully';
        	END IF;
               
           	SELECT v_ChatHistoryId	ChatHistoryId, v_errCode errCode,v_errMsg 	errMsg,ifnull(v_uuid,'') as chatUniqIdentifier;
        END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
