CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateCompanyDomain`(	
	p_companyId				INT			
	,p_domainId				BIGINT
	,p_companyName			VARCHAR(255)
	,p_website				VARCHAR(250)    
    ,p_iscareHome   		TINYINT
	,p_industryType			VARCHAR(100)
    ,p_domain_name			VARCHAR(150)
    ,p_video_domain_name	VARCHAR(150)
 )
BEGIN
	DECLARE v_curDate	DATETIME DEFAULT NOW();
	DECLARE v_companyId	INT;
	DECLARE v_errCode	INT	DEFAULT -1;
	DECLARE v_errMsg	VARCHAR(150) DEFAULT 'Add update company domain';
     
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	SELECT 	companyId
	INTO 	v_companyId
	FROM 	tb_companyDomain
	WHERE 	companyId = p_companyId;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;      
     
     IF v_companyId IS NULL
     THEN
 		INSERT INTO tb_companyDomain
 		(	companyId		
 			,domainId		
 			,companyName	
 			,website	
            ,industryType
            ,iscareHome
            ,domain_name
            ,video_domain_name
 			,createdAt		
 			,updatedAt		
 		)
         VALUES
         (	p_companyId		
			,p_domainId		
			,p_companyName	
			,p_website		
			,p_industryType
            ,p_iscareHome
            ,p_domain_name
            ,p_video_domain_name
			,v_curDate
			,v_curDate
         );
         
		SET	v_errCode	= 1
		,	v_errMsg	= 'Added company domain';
     ELSE
		UPDATE	tb_companyDomain
		SET 	website				= IFNULL(p_website,website)
			,	industryType		= IFNULL(p_industryType,industryType)
			,	domain_name			= IFNULL(p_domain_name,domain_name)
			,	video_domain_name	= IFNULL(p_video_domain_name,video_domain_name)
			,	updatedAt			= v_curDate
		WHERE 	companyId 			= v_companyId;
         
		SET v_errCode	= 2
		,	v_errMsg	= 'Update company domain';
     END IF;
     
 	SELECT v_errCode as errCode,v_errMsg as errMsg; 	
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
