CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateConcurrentAgentLimit`( p_domainId			INT		
   ,p_isAllAgent			TINYINT	
   ,p_allAgentLimit		SMALLINT
   ,p_isAgent			TINYINT	
   ,p_isRoutingProfile	TINYINT	
   ,p_agentOccupyDetails	JSON
 )
BEGIN
 	DECLARE v_Curdate		DATETIME;
     DECLARE v_domainId		INT;	
     DECLARE v_errCode		INT DEFAULT -1;
     DECLARE v_errMsg		VARCHAR(200) DEFAULT 'Insert Update Concurrent Limit Failed';
     
     SET v_Curdate = NOW();
     
     SELECT 	domainId INTO v_domainId
     FROM 	tb_ConcurrentAgentLimit A
     WHERE 	domainId = p_domainId;
     
     IF v_domainId IS NULL
     THEN
 		INSERT INTO tb_ConcurrentAgentLimit
         (	domainId			
             ,isAllAgent			
             ,allAgentLimit		
             ,isAgent			
             ,isRoutingProfile	
             ,agentOccupyDetails
             ,createdAt			
             ,updatedAt			
         )
         VALUES
         ( 	p_domainId		
             ,p_isAllAgent		
             ,p_allAgentLimit	
             ,p_isAgent		
             ,p_isRoutingProfile
             ,p_agentOccupyDetails
             ,v_Curdate
 			,v_Curdate
         );
         
         SET v_errCode 	= 0
 		,	v_errMsg	= 'Inserted Concurrent Limit Successfully';	
     ELSE
 		UPDATE 	tb_ConcurrentAgentLimit
         SET 	isAllAgent			= IFNULL(p_isAllAgent,isAllAgent)		
             ,	allAgentLimit		= IFNULL(p_allAgentLimit,allAgentLimit)	
 			,	isAgent				= IFNULL(p_isAgent,isAgent)	
 			,	isRoutingProfile	= IFNULL(p_isRoutingProfile,isRoutingProfile)
             ,	agentOccupyDetails	= IFNULL(p_agentOccupyDetails,agentOccupyDetails)
 			,	updatedAt			= v_Curdate
         WHERE 	domainId			= p_domainId;	
 
         SET v_errCode 	= 0
 		,	v_errMsg	= 'Inserted Concurrent Limit Successfully';    
 	END IF;    
     
 	SELECT v_errCode AS errCode, v_errMsg AS errMsg;
 END ;;
DELIMITER ;
