CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateConnectorChild`(	
     	 p_connectorChildId 		INT 
     	,p_conid 					INT 
     	,p_domainId 				INT 
     	,p_connection 				VARCHAR(255) 
     	,p_contactSyncDetails 		JSON 
     	,p_syncStatus				TINYINT	
    	,p_syncTime 				BIGINT
    	,p_contactSyncType 			VARCHAR(10)
        ,p_isConnected			    TINYINT
     )
BEGIN
		 DECLARE v_connectorChildId 	INT;
         DECLARE v_Curdate			DATETIME;
         DECLARE v_errCode			INT			 		DEFAULT -1;
         DECLARE v_errMsg			VARCHAR(250) 		DEFAULT 'Connector Child Failed';
         
         SET v_Curdate = NOW();
         
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         SELECT  connectorChildId INTO v_connectorChildId
         FROM 	tb_ConnectorChild
         WHERE `connection` 		= p_connection collate utf8mb4_0900_ai_ci
   	     AND 	domainId			= p_domainId
         AND     isConnected = 1  ;
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         
         IF v_connectorChildId IS NULL
         THEN
     		INSERT INTO tb_ConnectorChild
             (	
              `conid` 				
              ,`domainId` 			
              ,`connection` 		
              ,`contactSyncDetails` 
              ,`syncStatus`		
			  ,`contactSyncType`
              ,`isConnected`
              ,`createdDate` 		
              ,`updatedDate` 		
             )
             VALUES
             (		
               p_conid 				
              ,p_domainId 			
              ,p_connection 			
              ,p_contactSyncDetails 	
              ,p_syncStatus		
  			  ,p_contactSyncType  
              ,p_isConnected
              ,v_Curdate
              ,v_Curdate
             );
             
             SET v_connectorChildId = last_insert_id();
             SET v_errCode = 0;	
             SET v_errMsg = 'Connector Child Added Successfully';	
         ELSE
     		UPDATE 	tb_ConnectorChild
             SET 	    `connection`	= IFNULL(p_connection,`connection`)	
  				  ,	`contactSyncDetails`= IFNULL(p_contactSyncDetails,`contactSyncDetails`)
                  ,	`syncStatus`		= IFNULL(p_syncStatus,`syncStatus`)	
                  ,	syncTime			= IFNULL(p_syncTime,syncTime)
                  ,	contactSyncType		= IFNULL(p_contactSyncType,contactSyncType)
                  ,	isConnected		    = IFNULL(p_isConnected,isConnected)
              WHERE 	`connectorChildId` 	= v_connectorChildId;
     
             SET v_errCode = 0;	
             SET v_errMsg = 'Connector Child Updated Successfully';	        
         END IF; 
     
     	SELECT v_connectorChildId AS connectorChildId, v_errCode AS errCode,v_errMsg AS errMsg;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
