CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateContact`(
 	p_TicketContactId   	INT,
 	p_CompanyId            	INT,
 	p_ProductId				INT,
 	p_FirstName            	VARCHAR(100),
 	p_LastName         		VARCHAR(100),
 	p_Address              	TEXT,
 	p_Zipcodes             	VARCHAR(15),
 	p_Email      			TEXT,
 	p_Contact				TEXT,
 	p_IsDeleted            	TINYINT,
 	p_LoggedInUserID 		BIGINT       
  )
BEGIN
   	declare v_errcode 		INT;
   	declare v_errmsg 		VARCHAR(55);
      declare v_CurDate		DATETIME;
      declare v_TicketContactId	INT;
      
      SET v_CurDate = NOW();
      
      SELECT TicketContactId INTO v_TicketContactId
      FROM tb_TicketContact
      WHERE TicketContactId = p_TicketContactId;
      
  	drop temporary table if exists tt_temp_email;
  	create temporary table tt_temp_email(Email TEXT);
           
  	drop temporary table if exists tt_temp_contact;
  	create temporary table tt_temp_contact(Contact TEXT);
      
  	call split(p_Email, ','); 
  	insert into tt_temp_email(Email) select Items from tt_Split_temptable;
      
  	call split(p_Contact, ',');
  	insert into tt_temp_contact(Contact) select Items from tt_Split_temptable;
       
  	sp_exit: 
  	begin
  		IF v_TicketContactId IS NOT NULL THEN
  			UPDATE tb_TicketContact
  			SET	 	FirstName     		  	= IFNULL(p_FirstName, FirstName),
  					LastName       			= IFNULL(p_LastName, LastName),
  					Address        			= IFNULL(p_Address, Address),
  					Zipcodes		 		= IFNULL(p_Zipcodes, Zipcodes),
  					IsDeleted		 		= IFNULL(p_IsDeleted, IsDeleted),
  					UpdatedBy       		= p_LoggedInUserID,
  					UpdatedDate         	= v_CurDate
  			WHERE 	TicketContactId 		= p_TicketContactId;
  								
  			if ROW_COUNT() > 0 THEN
  				set v_errcode = 0;
  				set v_errmsg = 'Updated successfully';
  				leave sp_exit;
  			end if;
  		ELSE
  			INSERT INTO tb_TicketContact (
  				TicketContactId, 
  				CompanyId, 
  				ProductId, 
  				FirstName, 
  				LastName, 
  				Address, 
  				Zipcodes, 
  				IsDeleted, 
  				CreatedBy, 
  				CreatedDate, 
  				UpdatedBy, 
  				UpdatedDate
  			) VALUES (
  				p_TicketContactId,
  				p_CompanyId,
  				p_ProductId,
  				p_FirstName,
  				p_LastName,
  				p_Address,
  				p_Zipcodes,
  				0,
  				p_LoggedInUserID,
  				v_CurDate,
  				p_LoggedInUserID,
  				v_CurDate
  			);
               
  			SET v_TicketContactId = last_insert_id();
  			 
  			if ROW_COUNT() > 0 THEN
  				set v_errcode = 0;
  				set v_errmsg = 'Inserted successfully';
  			end if;
  		end if; 
  
  		INSERT INTO tb_TicketContactInformation (
  			TicketContactInformationId,
  			TicketContactId,
  			ContactInformationTypeId,
  			ContactInformation,
  			IsDeleted,
  			CreatedBy,
  			CreatedDate,
  			UpdatedBy,
  			UpdatedDate
  		)
  		SELECT NULL,
  			v_TicketContactId,
  			1108029,	
  			Email,
  			0,
  			p_LoggedInUserID,
  			v_CurDate,
  			p_LoggedInUserID,
  			v_CurDate
  		FROM tt_temp_email;
  		
  		INSERT INTO tb_TicketContactInformation (
  			TicketContactInformationId,
  			TicketContactId,
  			ContactInformationTypeId,
  			ContactInformation,
  			IsDeleted,
  			CreatedBy,
  			CreatedDate,
  			UpdatedBy,
  			UpdatedDate
  		)
  		SELECT NULL,
  			v_TicketContactId,
  			1108030,	
  			Contact,
  			0,
  			p_LoggedInUserID,
  			v_CurDate,
  			p_LoggedInUserID,
  			v_CurDate
  		FROM tt_temp_contact;
  		
  		set v_errcode = 0;
  		set v_errmsg = 'Contact information inserted/updated successfully';
  	end sp_exit;
                       
  	select v_errcode as errcode, v_errmsg as errmsg;
                       
  end ;;
DELIMITER ;
