CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_insertUpdateCustomerFeedback`(
	p_customerFeedbackId 		BIGINT 
	,p_historyId				BIGINT
	,p_channelTypeId			INT
	,p_satisfactionRate			TINYINT
	,p_domainId					INT
	,p_feedbackQuestionAnswer	JSON
	,p_AgentId					BIGINT
	,p_ratingType				INT
	,p_sessionId				VARCHAR(250)
	,p_customerNumber 			VARCHAR(30)
    ,p_videoMeetId				varchar(150)
     )
BEGIN
   		DECLARE v_customerFeedbackId	BIGINT;	
   		DECLARE v_callCustomerFeedbackId	BIGINT;	
   		DECLARE v_curDate				DATETIME DEFAULT NOW();	
   		DECLARE v_errCode				TINYINT DEFAULT 0;
   		DECLARE v_errMsg				VARCHAR(200) DEFAULT 'Add/Update customer feedback failed';
          DECLARE v_AgentId				BIGINT;
          
          
          if p_channelTypeId='2003001'  then
  			select ratingDesignType into p_ratingType from tb_ccaas_customerSatisfactionRatingDesign where domainId = p_domainId limit 1;
  			select UserID into v_AgentId from tb_User where domainId = p_domainId and ext = p_AgentId limit 1;
  			select CallHistoryId into p_historyId from tb_CallHistory where domainId = p_domainId and sessionId = p_sessionId limit 1;
            select customerFeedbackId into v_callCustomerFeedbackId from tb_customerFeedback where historyId = p_historyId;
          End if;
          
          
          if p_channelTypeId='2003008'  then
  			select VideoHistoryId into p_historyId from tb_VideoHistory where domainId = p_domainId and meetingId = p_videoMeetId limit 1;
          End if;
          
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
          SELECT customerFeedbackId INTO v_customerFeedbackId
          FROM 	tb_customerFeedback
          WHERE customerFeedbackId 	= p_customerFeedbackId
          AND	domainId			= p_domainId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
          
          IF p_channelTypeId='2003001'  
          THEN
			SET v_customerFeedbackId = v_callCustomerFeedbackId;
          ELSE
			SET v_customerFeedbackId = v_customerFeedbackId;
            SET v_AgentId = p_AgentId ;
          END IF;
          
          IF v_customerFeedbackId IS NULL
          THEN
     		INSERT INTO tb_customerFeedback(
     			historyId
     			,channelTypeId
     			,satisfactionRate
     			,domainId
     			,feedbackQuestionAnswer
     			,createdDate
     			,updatedDate 
                ,AgentId
                ,ratingType
             )
             VALUES(
     			p_historyId					
                 ,p_channelTypeId				
                 ,p_satisfactionRate			
                 ,p_domainId					
                 ,p_feedbackQuestionAnswer	
                 ,v_curDate
                 ,v_curDate
                 ,v_AgentId
                 ,p_ratingType
             );
             
             SET v_customerFeedbackId = LAST_INSERT_ID();
             
             IF ROW_COUNT() > 0
             THEN
     			SET v_errCode	= 1
                 ,   v_errMsg	= 'Added customer feedback successfully';
             END IF;
     	ELSE
     		UPDATE 	tb_customerFeedback
             SET 	historyId				= p_historyId				
     			,	channelTypeId			= p_channelTypeId			
     			,	satisfactionRate		= p_satisfactionRate			
     			,	feedbackQuestionAnswer	= p_feedbackQuestionAnswer							
     			,	updatedDate    			= v_curDate	
                ,	AgentId					= v_AgentId
                ,	ratingType				= p_ratingType
             WHERE 	customerFeedbackId 		= v_customerFeedbackId;
             
             IF ROW_COUNT() > 0
             THEN
     			SET v_errCode	= 2
                 ,   v_errMsg	= 'Updated customer feedback successfully';
             END IF;
         END IF; 
        
       
         
         call ccaas_insert_check_feedback_info(p_customerNumber, p_domainId);
         
     
         SELECT v_customerFeedbackId AS customerFeedbackId, v_errCode AS errCode, v_errMsg AS errMsg;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
