CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateEmailAnalytics_config`(   
     p_domainId        INT,
     p_ext             INT,
     p_editColumnNames LONGTEXT,
     p_id              TINYINT
 )
BEGIN
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(255) DEFAULT 'No Record to Config';
     DECLARE v_emailECId INT;
     DECLARE v_CurDate DATETIME;
 

     SET v_CurDate = NOW();
 

     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 
     SELECT emailECId INTO v_emailECId
     FROM emailEditColumns EC
     WHERE EC.domainId = p_domainId
       AND   EC.Id =p_id
       AND EC.ext = p_ext;
 

     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     IF v_emailECId IS NULL THEN
         INSERT INTO emailEditColumns 
         (domainId, ext, Id, editColumnNames, createdAt, updatedAt)
         VALUES 
         (p_domainId, p_ext, p_id, p_editColumnNames, v_CurDate, v_CurDate);
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Inserted Successfully';
         SET v_emailECId = LAST_INSERT_ID();
     ELSE
         UPDATE emailEditColumns
         SET editColumnNames = p_editColumnNames,
         
             updatedAt        = v_CurDate
         WHERE emailECId = v_emailECId;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Updated Successfully';
     END IF;
 
 
     SELECT v_emailECId AS emailECId, p_domainId AS domainId, p_ext AS ext, p_editColumnNames AS editColumnNames, v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
