CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateEmailFlowHistory`(
  	p_emailFlowHistoryId	INT	
  	,p_FlowName				VARCHAR(150)
  	,p_html					TEXT
  	,p_css					TEXT
  	,p_domainId				INT
  	,p_isActive				TINYINT
     ,p_url					VARCHAR(1000)
  )
BEGIN	
 	DECLARE v_Curdate				DATETIME DEFAULT NOW();
 	DECLARE v_errCode				SMALLINT DEFAULT -1;
 	DECLARE v_errMsg				VARCHAR(150) DEFAULT 'Add Update email flow history failed';    
 	DECLARE v_emailFlowHistoryId	INT;
      
      SELECT emailFlowHistoryId INTO v_emailFlowHistoryId
      FROM 	tb_emailFlowHistory
      WHERE 	emailFlowHistoryId 	= p_emailFlowHistoryId
      AND 	domainId			= p_domainId;    
  
  	IF v_emailFlowHistoryId IS NULL 
      THEN
  		INSERT INTO tb_emailFlowHistory
  		(	FlowName			
  			,html				
  			,css		
             ,url
  			,domainId			
  			,isActive			
  			,createdDated		
  			,updatedDated		
  		)
  		VALUES 	
  		(	p_FlowName
  			,p_html		
 			,p_css		
             ,p_url
             ,p_domainId	
  			,p_isActive	
  			,v_Curdate
  			,v_Curdate
          );
          
          SET v_emailFlowHistoryId = last_insert_id();
          
          SET v_errCode	= 0
  		, 	v_errMsg	= 'Added email flow history successfully';
  	ELSE
  		UPDATE	tb_emailFlowHistory
          SET 	FlowName		= p_FlowName
                  ,html			= p_html		
                  ,css			= p_css		
                  ,url			= IFNULL(p_url,url)
                  ,domainId		= p_domainId	
                  ,isActive		= p_isActive	                
                  ,updatedDated	= v_Curdate
          WHERE 	emailFlowHistoryId = v_emailFlowHistoryId;
          
          SET v_errCode	= 1
  		, 	v_errMsg	= 'Updated email flow history successfully';
  	END IF;
      
  	SELECT v_emailFlowHistoryId AS emailFlowHistoryId,v_errCode AS errCode, v_errMsg AS errMsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
