CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateEmailHistory`(	
          p_EmailHistoryId 			BIGINT, 
          p_SessionId      			VARCHAR(250), 
          p_SessionStartTime  		BIGINT, 
          p_SessionEndTime    		BIGINT, 
          p_FromEmail				VARCHAR(100), 
          p_ToEmail					VARCHAR(100), 
          p_EmailSubject			VARCHAR(250), 
          p_EmailFlowSourceId		INT, 
          p_CompanyId				INT, 
          p_DomainId				INT, 
          p_DispositionId			INT, 
          p_Summary					TEXT, 
          p_IsInBound				TINYINT, 
          p_AssignedTo				BIGINT, 
          p_AssignedBy				BIGINT, 
          p_AssignedOn				BIGINT, 
          p_AfterEmailWorkTime		INT, 
          p_Istransferred			INT, 
          p_TransferredTypeId		INT, 
          p_IsSessionClosed			TINYINT, 
          p_CustomerId				INT, 
          p_TicketId				BIGINT, 
          p_SupervisorName			VARCHAR(100),
          p_Message					JSON,
          p_AgentId					INT,
          p_AgentSkillId			INT,
          p_IsBot					TINYINT,
          p_BotId					INT,
          p_QueueId					INT,
          p_threadMessageId 		VARCHAR(1000),
          p_graphMessageId			VARCHAR(2500),
          p_conversationId			VARCHAR(2500)
          )
sp_return: BEGIN
    		DECLARE v_errCode			INT	DEFAULT -1;
    		DECLARE v_errMsg			VARCHAR(150) DEFAULT 'No Email';
    		DECLARE	v_CurDate			DATETIME;
    		DECLARE	v_EmailHistoryId	BIGINT;

              
  		SET v_CurDate = NOW();
        
  		if exists(select 1 from tb_PlanRecharge where domainId = p_DomainId and cast(planEndTime as date) < cast(v_CurDate as date) limit 1) 
  		then 
  			select -1 as errcode, 'Inactive Plan' as errmsg;
  			leave sp_return;
  		End if;
          
  		if exists(select 1 from tb_CurrentPlan where domainId = p_DomainId and TotalSession = TotalSessionUsed and isUnilimitedChat = 0 limit 1) 
  		then 
  			select -1 as errcode, 'No Session Available' as errmsg;
  		leave sp_return;
  		End if;
    	  
    	  if exists(select 1 from customer_contact where domainId = p_DomainId and (primaryEmail collate utf8mb4_0900_ai_ci like p_FromEmail or email collate utf8mb4_0900_ai_ci  like concat('%',p_FromEmail,'%')) and blockCustomer = 1 ) then
    		select -1 as errcode, 'Emailaddress is blocked' as errmsg;
    		   leave sp_return;
    	  End if;  
              
              SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
              SELECT EmailHistoryId INTO v_EmailHistoryId
              FROM 	tb_EmailHistory
              WHERE EmailHistoryId = p_EmailHistoryId;
              
              IF v_EmailHistoryId IS NULL
              THEN
          		INSERT INTO tb_EmailHistory	 
          		(	 
          			SessionId, 
                      SessionStartTime, 
                      SessionEndTime, 
                      FromEmail, 
                      ToEmail, 
                      EmailSubject, 
                      EmailFlowSourceId, 
                      CompanyId, 
                      DomainId, 
                      DispositionId, 
                      Summary, 
                      IsInBound, 
                      AssignedTo, 
                      AssignedBy, 
                      AssignedOn, 
                      AfterEmailWorkTime, 
                      Istransferred, 
                      TransferredTypeId, 
                      IsSessionClosed, 
                      CustomerId, 
                      TicketId, 
                      SupervisorName,
                      threadMessageId,
                      CreatedAt, 
                      UpdatedAt,
                      graphMessageId,
                      conversationId
          		)
                  VALUES
                  (	
                      p_SessionId, 
                      p_SessionStartTime, 
                      p_SessionEndTime, 
                      p_FromEmail, 
                      p_ToEmail, 
                      p_EmailSubject, 
                      p_EmailFlowSourceId, 
                      p_CompanyId, 
                      p_DomainId, 
                      p_DispositionId, 
                      p_Summary, 
                      p_IsInBound, 
                      p_AssignedTo, 
                      p_AssignedBy, 
                      p_AssignedOn, 
                      p_AfterEmailWorkTime, 
                      p_Istransferred, 
                      p_TransferredTypeId, 
                      p_IsSessionClosed, 
                      p_CustomerId, 
                      p_TicketId, 
                      p_SupervisorName,
                      p_threadMessageId,
						v_CurDate,
						v_CurDate,
						p_graphMessageId,
						p_conversationId
                  );        
                  
                  SET v_EmailHistoryId = last_insert_id();
                  SET v_errCode	= 0;
                  SET v_errMsg	= 'Successfully';
                  
 			
 					UPDATE 	tb_CurrentPlan
 					SET 	TotalSessionUsed			= case when isUnilimitedChat = 1 then TotalSessionUsed else ifnull(TotalSessionUsed,0) + 1 end
 							,updatedDate				= v_Curdate
 					WHERE 	domainId = p_DomainId;
         
                     
                  IF p_Message IS NOT NULL
                  THEN
          			INSERT INTO tb_EmailMessage	 
          			(	EmailHistoryId	
          				,Message		
          				,CreatedAt		
          				,UpdatedAt		
          			)
          			VALUES
          			(	v_EmailHistoryId
          				,p_Message
          				,v_CurDate
          				,v_CurDate
          			);      
                  END IF; 
                  
          			INSERT INTO tb_EmailDurationHistory
          			(	EmailHistoryId, 
          				AgentId, 
                          AgentSkillId, 
                          IsBot, 
                          BotId, 
                          QueueId, 
                          CreatedAt, 
                          UpdatedAt
          			)
          			VALUES
          			(	v_EmailHistoryId
          				,p_AgentId		
          				,p_AgentSkillId			
          				,p_IsBot			
          				,p_BotId					
          				,p_QueueId			
          				,v_CurDate
          				,v_CurDate
          			);	  
          	ELSE
          		UPDATE 	tb_EmailHistory
                  SET 	SessionId				= IFNULL(p_SessionId			,SessionId)				
                          ,SessionStartTime	    = IFNULL(p_SessionStartTime	    ,SessionStartTime)
                          ,SessionEndTime		    = IFNULL(p_SessionEndTime	    ,SessionEndTime)
                          ,FromEmail		    	= IFNULL(p_FromEmail	    	,FromEmail)
                          ,ToEmail		    	= IFNULL(p_ToEmail	    		,ToEmail)
                          ,EmailSubject		    = IFNULL(p_EmailSubject	    	,EmailSubject)
                          ,EmailFlowSourceId	    = IFNULL(p_EmailFlowSourceId	,EmailFlowSourceId)	    
                          ,CompanyId			    = IFNULL(p_CompanyId		    ,CompanyId)			    
                          ,DomainId			    = IFNULL(p_DomainId			    ,DomainId)			    
                          ,DispositionId		    = IFNULL(p_DispositionId	    ,DispositionId)		    
                          ,Summary			    = IFNULL(p_Summary			    ,Summary)			    
                          ,IsInBound			    = IFNULL(p_IsInBound		    ,IsInBound)			    	    
                          ,AssignedTo			    = IFNULL(p_AssignedTo		    ,AssignedTo)			    
                          ,AssignedBy			    = IFNULL(p_AssignedBy		    ,AssignedBy)			    
                          ,AssignedOn			    = IFNULL(p_AssignedOn		    ,AssignedOn)			    	    
                          ,AfterEmailWorkTime	    = IFNULL(p_AfterEmailWorkTime   ,AfterEmailWorkTime)
                          ,Istransferred		    = IFNULL(p_Istransferred	    ,Istransferred)		    
                          ,TransferredTypeId	    = IFNULL(p_TransferredTypeId    ,TransferredTypeId)	    
                          ,IsSessionClosed	    = IFNULL(p_IsSessionClosed		,IsSessionClosed)			    
                          ,CustomerId			    = IFNULL(p_CustomerId		    ,CustomerId)			    
                          ,TicketId			    = IFNULL(p_TicketId		    	,TicketId)			    
                          ,SupervisorName	    	= IFNULL(p_SupervisorName	    ,SupervisorName)
                          ,threadMessageId	    	= IFNULL(p_threadMessageId	    ,threadMessageId)
                          ,updatedAt				= v_CurDate
          		WHERE	EmailHistoryId 			= v_EmailHistoryId;   
                
                
                UPDATE tb_EmailDurationHistory
        		SET		AgentId  = ifnull(p_AgentId,AgentId)
        				,AgentSkillId = ifnull(p_AgentSkillId,AgentSkillId)
        				,IsBot = ifnull(p_IsBot,IsBot)
        				,BotId = ifnull(p_BotId,BotId)
        				,QueueId= ifnull(p_QueueId,QueueId)
        				,UpdatedAt = now()
                WHERE EmailHistoryId 			= v_EmailHistoryId;  
                 
         		UPDATE 	tb_EmailMessage
                 SET 	Message 		= JSON_ARRAY_APPEND(Message,'$',p_Message)
         			,	updatedAt		= v_CurDate
                 WHERE 	EmailHistoryId 	= v_EmailHistoryId;        
                  
                  SET v_errCode	= 0;
                  SET v_errMsg	= 'Email Updated Successfully';
                  
              END IF;
              
         		select 'Email' channelType,v_errcode as errcode, v_errmsg as errmsg, v_EmailHistoryId as EmailHistoryId,
                 a.*,b.*,c.* ,b.threadMessageId as messageId
                 from tb_EmailMessage a 
                 JOIN tb_EmailHistory b 			ON a.EmailHistoryId = b.EmailHistoryId
                 JOIN tb_EmailDurationHistory c  ON a.EmailHistoryId = c.EmailHistoryId
                 where a.EmailHistoryId 	= v_EmailHistoryId; 
                	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
          END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
