DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateFacebook`(
         		p_sessionId					TEXT, 
         		p_sessionStartTime			BIGINT,
         		p_sessionEndTime			BIGINT,
         		p_domainID					INT,
         		p_message					JSON,
         		p_customerFacebookId		varchar(100),
         		p_agentFacebookId			varchar(100),
         		p_dispositionId				INT,
         		p_IsInBound					TINYINT	,
         		p_IsSessionClosed			TINYINT,
         		p_IsBot						INT,
         		p_Summary					text,
              p_FacebookCommunicationType	VARCHAR(100)
          )
sp_exit: BEGIN         
			DECLARE v_errcode 						INT DEFAULT -1;
			DECLARE v_errmsg 						VARCHAR(255) DEFAULT 'No Facebook';	
			DECLARE v_FacebookHistoryId				BIGINT;
			DECLARE v_Curdate						DATETIME;	
			DECLARE v_IsUpdate						TINYINT; 
			DECLARE v_FacebookCommunicationTypeId	INT;
			DECLARE v_dispositionId					INT;
			DECLARE v_IsBot							INT;
                               
         	SET v_Curdate  = NOW();     
             
             if exists(select 1 from tb_PlanRecharge where domainId = p_domainID and cast(planEndTime as date) < cast(v_Curdate as date) limit 1) 
  			then 
  				select -1 as errcode, 'Inactive Plan' as errmsg;
  				leave sp_exit;
  			End if;
          
          
          
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  			SELECT did INTO v_dispositionId
  			FROM disposition_status 
  			WHERE domainId = p_domainId
  			AND dispositionName = 'Closed'
  			LIMIT 1;
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                  
          update tb_FacebookHistory set IsSessionClosed = 1, IsBot = 1 where TIMESTAMPDIFF(MINUTE, createdAt, now()) >= 1440 and IsSessionClosed = 0;
          
          update tb_FacebookHistory
  		set  dispositionId = v_dispositionId
  		,	sessionEndTime = unix_timestamp(current_timestamp())*1000
  		where TIMESTAMPDIFF(MINUTE, createdAt, now()) >= 1440 and (sessionEndTime is null or sessionEndTime = 0)
  		and (dispositionId = 0 or dispositionId is null)
          and domainId = p_domainId;
         
         	select domainId,isBot into p_domainID,v_IsBot from tb_FacebookConfiguration where FacebookPageId COLLATE utf8mb4_unicode_ci = p_agentFacebookId limit 1;
   
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          SELECT TypeCodeID
          INTO 	v_FacebookCommunicationTypeId
          FROM 	TypeCode 
          WHERE 	TypeGroupID 	= 2004
          AND 	TypeCodeName	collate utf8mb4_unicode_ci = p_FacebookCommunicationType; 
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

         	if exists(select 1 from customer_contact  where domainId = p_domainID and  facebook  = p_customerFacebookId and blockCustomer = 1) 
 			then 
      		select -1 as errcode,'Customer number is blocked' as errmsg;
      		leave sp_exit;
         	End if;
             
             if exists(select 1 from tb_CurrentPlan where domainId = p_domainID and TotalSession = TotalSessionUsed and isUnilimitedChat = 0 limit 1) 
 			 then 
 				select -1 as errcode, 'No Session Available' as errmsg;
 				leave sp_exit;
 			End if;

         	sp_return : BEGIN    
         		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         		SELECT 	FacebookHistoryId INTO v_FacebookHistoryId  
         		FROM 	tb_FacebookHistory SH 
         		WHERE 	SH.customerFacebookId 	= p_customerFacebookId 
         		AND 	SH.agentFacebookId 		= p_agentFacebookId  		
         		AND 	IsSessionClosed			= 0
                
         		ORDER BY FacebookHistoryId DESC LIMIT 1;        
         		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
     			IF v_FacebookCommunicationTypeId IN (2004001,2004002) 
           		THEN 
     				IF v_FacebookHistoryId IS NULL 
     				THEN      		        
     					INSERT INTO tb_FacebookHistory(sessionId,sessionStartTime,sessionEndTime,domainId,customerFacebookId,agentFacebookId,dispositionId,IsBot,IsInBound,createdAt,updatedAt,IsSessionClosed
     				 ,FacebookCommunicationTypeId)
     					VALUES(p_sessionId,p_sessionStartTime,p_sessionEndTime,p_domainID,p_customerFacebookId,p_agentFacebookId,p_dispositionId,p_IsBot,p_IsInBound,v_Curdate,v_Curdate,p_IsSessionClosed
     				 ,v_FacebookCommunicationTypeId);
     		
     					SET v_FacebookHistoryId = last_insert_id(); 
     		
     					SET v_errcode = 0;
     					SET v_errmsg = 'Facebook added successfully';
     					SET v_IsUpdate = 0;
                         
                         
  								UPDATE 	tb_CurrentPlan
  								SET 	
  											TotalSessionUsed			= case when isUnilimitedChat = 1 then TotalSessionUsed else ifnull(TotalSessionUsed,0) + 1 end
  											,updatedDate				= v_Curdate
  								WHERE 	domainId = p_DomainId;
  						
     				ELSE
     					UPDATE tb_FacebookHistory SH
     					SET	
							SH.sessionEndTime  				= IFNULL(p_sessionEndTime,SH.sessionEndTime),
							SH.customerFacebookId 			= IFNULL(p_customerFacebookId,SH.customerFacebookId),				
							SH.agentFacebookId 				= IFNULL(p_agentFacebookId,SH.agentFacebookId),
							SH.dispositionId  				= IFNULL(p_dispositionId,SH.dispositionId),
							SH.IsInBound					= IFNULL(p_IsInBound,SH.IsInBound),
							SH.Summary						= IFNULL(p_Summary,SH.Summary),
							SH.IsSessionClosed				= IFNULL(p_IsSessionClosed,SH.IsSessionClosed),
							SH.IsBot						= IFNULL(p_IsBot,SH.IsBot),
							SH.FacebookCommunicationTypeId	= IFNULL(v_FacebookCommunicationTypeId,FacebookCommunicationTypeId),                                
							SH.updatedAt					= v_Curdate				
     					WHERE FacebookHistoryId				= v_FacebookHistoryId;
     					
     					SET v_errcode = 0;
     					SET v_errmsg = 'Facebook updated successfully';
     					SET v_IsUpdate = 1;
     				END IF; 
     			END IF; 
                 
         		IF JSON_VALID(p_message) = 1 AND v_FacebookCommunicationTypeId IN (2004001,2004002) 
         		THEN
      			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         			IF EXISTS (SELECT 1 FROM tb_FacebookMessage WHERE FacebookHistoryId = v_FacebookHistoryId) 
         			THEN            
                  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         				UPDATE 	tb_FacebookMessage a
         				SET 	a.message 	= IFNULL(JSON_ARRAY_APPEND(a.message, '$', p_message), if(a.message is null,p_message,JSON_ARRAY_APPEND(a.message, '$', p_message)))
         					,	a.updatedAt	= v_Curdate
         				WHERE 	FacebookHistoryId 	= v_FacebookHistoryId;

         				SET v_errmsg = CONCAT(v_errmsg,', Message updated successfully');
         		   ELSE
         				INSERT INTO tb_FacebookMessage
         				(	FacebookHistoryId
         					,Message	
         					,createdAt	
         					,updatedAt	
         				)
         				VALUES
         				(	v_FacebookHistoryId
         					,p_message
         					,v_Curdate
         					,v_Curdate
         				); 
         			   
         			   SET v_errmsg = CONCAT(v_errmsg,', Message added successfully');
         			END IF;  
         		END IF; 
         	END;   
          	
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	SELECT  v_IsUpdate as IsUpdate,v_FacebookHistoryId as FacebookHistoryId, p_domainID AS domainId, v_errcode AS errcode, v_errmsg AS errmsg 
      		,	FH.sessionId 					            
      		,	FH.domainId 					
      		,	FH.dispositionId 				            
      		,	FH.IsInBound 					
      		,	FH.assignedTo 				
      		,	FH.assignedBy 				                        
      		,	FH.NextFlowNode 				                                    
      		,	FH.markAsReadSupervisor 		
      		,	FH.markAsReadAgent 			
      		,	FH.IsSessionClosed 			
      		,	CAST(FH.customerFacebookId AS CHAR)			AS customerFacebookId
      		,	CAST(FH.agentFacebookId AS CHAR)			AS agentFacebookId            			
      		,	FH.AgentId 					
      		,	FH.IsBot 						
      		,	FH.BotId 						
      		,	FH.SentimentalScore 
      		,	FM.Message 
      		,	'Facebook' 	AS channelType
      	FROM 	tb_FacebookHistory	FH
      	JOIN 	tb_FacebookMessage	FM ON FH.FacebookHistoryId = FM.FacebookHistoryId
      	WHERE 	FH.FacebookHistoryId = v_FacebookHistoryId;
      	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateFacebookConfiguration` */;
