DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateFacebookConfiguration`(	
      p_FacebookConfigurationId 	INT 
  	,p_pageName					VARCHAR(250)
  	,p_language					VARCHAR(100)
  	,p_domainId 				INT
  	,p_planId 					INT
  	,p_isBot 					TINYINT
  	,p_isBotPurchased 			TINYINT
  	,p_FacebookFlowId 			INT
  	,p_FacebookPageId 			VARCHAR(50)
  	,p_isActive 				TINYINT 
	,p_facebookintegrationId    INT
	,p_callBackToggle			TINYINT
	,p_callBackForm				VARCHAR(10)
	,p_notifyAdmin				VARCHAR(50)
	,p_knowledgeBaseId			VARCHAR(100)
  )
BEGIN
  	 DECLARE v_FacebookConfigurationId 	INT;
      DECLARE v_CurDate					DATETIME;
      DECLARE v_errCode					INT	DEFAULT -1;
      DECLARE v_errMsg					VARCHAR(150) DEFAULT 'Insert Update Facebook Configuration Failed';
      
      SET v_CurDate = NOW();
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
      SELECT 	FacebookConfigurationId INTO v_FacebookConfigurationId
      FROM 	tb_FacebookConfiguration
      WHERE 	FacebookConfigurationId = p_FacebookConfigurationId;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      IF v_FacebookConfigurationId IS NULL
      THEN
  		INSERT INTO tb_FacebookConfiguration   
          (	pageName				
              ,`language`				
              ,domainId 				
              ,planId 				
              ,isBot 					
              ,isBotPurchased 		
              ,FacebookFlowId 		
              ,FacebookPageId 
              ,facebookintegrationId
              ,isActive 	
				,callBackToggle	              
				,callBackForm		              
				,notifyAdmin	
              ,createdDate 			
              ,updatedDate
              ,knowledgeBaseId
          )
          VALUES
          (	 p_pageName			
              ,p_language			
              ,p_domainId 		
              ,p_planId 			
              ,p_isBot 			
              ,p_isBotPurchased 	
              ,p_FacebookFlowId 	
              ,p_FacebookPageId 
              ,p_facebookintegrationId
              ,p_isActive 
			,p_callBackToggle	              
			,p_callBackForm		              
			,p_notifyAdmin		              
              ,v_CurDate
              ,v_CurDate
              ,p_knowledgeBaseId
              );
              
  		SET v_FacebookConfigurationId = last_insert_id();
          SET v_errCode 	= 0
  		,	v_errMsg	= 'Facebook Configuration added successfully';
      ELSE
  		UPDATE 	tb_FacebookConfiguration 
          SET 	pageName		= ifnull(p_pageName	,pageName)			
              ,	`language`		= ifnull(p_language,`language`)					
              ,	domainId 		= ifnull(p_domainId,domainId) 				
              ,	planId 			= ifnull(p_planId ,	planId)			
              ,	isBot 			= ifnull(p_isBot ,isBot)					
              ,	isBotPurchased 	= ifnull(p_isBotPurchased ,isBotPurchased)		
              ,	FacebookFlowId 	= ifnull(p_FacebookFlowId,FacebookFlowId) 		
              ,	FacebookPageId  = ifnull(p_FacebookPageId,FacebookPageId) 
              ,  facebookintegrationId= ifnull(p_facebookintegrationId,facebookintegrationId)
			  ,callBackToggle	= ifnull(p_callBackToggle,callBackToggle)             
			  ,callBackForm		=  ifnull(p_callBackForm,callBackForm)            
			  ,notifyAdmin      =  ifnull(p_notifyAdmin,notifyAdmin) 
              ,	isActive 		= ifnull(p_isActive,isActive)
              ,	knowledgeBaseId 	= ifnull(p_knowledgeBaseId,knowledgeBaseId)
              ,	updatedDate 	= v_CurDate
          WHERE 	FacebookConfigurationId = v_FacebookConfigurationId;    
      
  		SET v_errCode 	= 0
  		,	v_errMsg	= 'Facebook Configuration added successfully';
      END IF;
      
  	SELECT v_FacebookConfigurationId AS FacebookConfigurationId,v_errCode AS errCode,v_errMsg AS errMsg;
  END ;;
DELIMITER ;
