CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateFieldLabel`(
  p_TicketLayoutId    		INT,
  p_TicketFieldId    			INT,
  p_FieldName					varchar(100),
  p_FieldDescription			varchar(250),
  p_FieldCategoryTypeId		int,
  p_APIName					varchar(100),
  p_FieldTypeId				int,
  p_LabelTypeId				INT,
  p_DefaultValue				varchar(250),
  p_MaximunLength				int,
  p_IsActive					tinyint,
  p_IsRequired				tinyint,
  p_IsDefault					tinyint,
  p_IsDeleted					int,
  p_FieldLabel				json,
  p_CompanyId          		INT,
  p_ProductId         		INT,
  p_LoggedInUserID 	        BIGINT       
  )
BEGIN 
  	DECLARE v_errcode 			INT;
  	DECLARE v_errmsg 			VARCHAR(55);
  	DECLARE v_CurDate			DATETIME;
  	DECLARE v_JLength			INT;
  	DECLARE v_TicketLayoutId 	INT;
      DECLARE v_TicketFieldId		INT;
      
  	SET v_CurDate = NOW();	
   
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
  	SELECT 	TicketFieldId INTO v_TicketFieldId
  	FROM  	tb_TicketField
  	WHERE 	TicketFieldId = p_TicketFieldId; 
  
  	SET v_JLength = JSON_LENGTH(p_FieldLabel, "$");
             
  	DROP TEMPORARY TABLE IF EXISTS tt_TicketFieldLabel;
  	CREATE TEMPORARY TABLE tt_TicketFieldLabel       
  	WITH RECURSIVE  CTE_JsonCount as
  	(	SELECT 	0 SlNo
  		UNION ALL
  		SELECT 	SlNo + 1	SlNo
  		FROM 	CTE_JsonCount
  		WHERE 	SlNo  < v_JLength - 1
  	)
  	SELECT  TRIM(BOTH '"' FROM (json_extract(p_FieldLabel, concat('$[',SlNo,'].TicketLabelId')))) 			AS TicketLabelId,
  			TRIM(BOTH '"' FROM (json_extract(p_FieldLabel, concat('$[',SlNo,'].LabelName')))) 				AS LabelName						
  	FROM CTE_JsonCount;    
      
      IF v_TicketFieldId IS NULL
      THEN
  		INSERT INTO tb_TicketField 
  		(	FieldName, 				
  			FieldDescription,
  			TicketLayoutId,
  			FieldCategoryTypeId, 
  			APIName, 
  			FieldTypeId, 
  			IsActive, 
  			IsRequired, 
              IsDeleted,
  			IsDefault,
              DefaultValue,
  			CompanyId,
  			ProductId,
  			CreatedBy, 
  			CreatedDate, 
  			UpdatedBy, 
  			UpdatedDate
  	   ) 
         SELECT
  		   p_FieldName,
  		   p_FieldDescription,
  		   p_TicketLayoutId,
  		   p_FieldCategoryTypeId,
  		   p_APIName,
  		   p_FieldTypeId,
  		   1,
  		   p_IsRequired,
             0,
  		   p_IsDefault,
             p_DefaultValue,
  		   p_CompanyId,
  		   p_ProductId,
  		   p_LoggedInUserID,
  		   v_CurDate,
  		   p_LoggedInUserID,
  		   v_CurDate;
         
  		SET V_TicketFieldId = last_insert_id();
          
          INSERT INTO tb_TicketLabel
  		(	TicketFieldId			
  			,FieldLabel	
              ,LabelTypeId
  			,CreatedBy				
  			,CreatedDate			
  			,UpdatedBy				
  			,UpdatedDate )
  		SELECT 
          	V_TicketFieldId
  			,LabelName
              ,p_LabelTypeId
  			,p_LoggedInUserID
  			,v_CurDate
  			,p_LoggedInUserID
  			,v_CurDate
          FROM tt_TicketFieldLabel;
           
	   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;       
  		IF ROW_COUNT() > 0
  		THEN
  			SET v_errcode = 0;
  			SET v_errmsg = 'Inserted successfully';				
  		END IF;		 
      END IF;
      
  	SELECT v_errcode as errcode, v_errmsg as errmsg;                      
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
