CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateGoogleSearchApi`(   
    
     p_apiHit          INT,
     p_date 		   TEXT
 )
BEGIN
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(255) DEFAULT 'No Record to Config';
     DECLARE v_date TEXT;
     DECLARE v_CurDate DATETIME;
 

     SET v_CurDate = NOW();
 

     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 
     SELECT date INTO v_date
     FROM tb_GoogleSearchApiCount GC
     WHERE date = p_date;
 

     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     IF v_date IS NULL THEN
         INSERT INTO tb_GoogleSearchApiCount 
         ( apiHit,date)
         VALUES 
         (p_apiHit,p_date );
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Inserted Successfully';
        
     ELSE
         UPDATE tb_GoogleSearchApiCount
         SET apiHit = p_apiHit
         WHERE date = v_date;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Updated Successfully';
     END IF;
 
     SELECT  p_apiHit AS apiHit, p_date AS date, v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
