DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateInstagram`(	
     	p_sessionId						TEXT, 
     	p_sessionStartTime				BIGINT,
     	p_sessionEndTime				BIGINT,
     	p_domainID						INT,
     	p_message						JSON,
     	p_customerInstagramId			varchar(50),
     	p_agentInstagramId				varchar(50),
     	p_dispositionId					INT,
     	p_IsInBound						TINYINT	,
     	p_IsSessionClosed				TINYINT,
     	p_IsBot							INT,
     	p_Summary						TEXT,
     	p_InstagramCommunicationType	VARCHAR(100)
     	)
sp_exit: BEGIN         
         	DECLARE v_errcode 						INT DEFAULT -1;
         	DECLARE v_errmsg 						VARCHAR(255) DEFAULT 'No Instagram';	
         	DECLARE v_InstagramHistoryId			BIGINT;
         	DECLARE v_Curdate						DATETIME;	
         	DECLARE v_IsUpdate						TINYINT; 
     		DECLARE v_InstagramCommunicationTypeId	INT;
     		DECLARE v_dispositionId					INT;
     		DECLARE v_IsBot							INT;
                               
         	SET v_Curdate  = NOW();   
             
             if exists(select 1 from tb_PlanRecharge where domainId = p_domainID and cast(planEndTime as date) < cast(v_Curdate as date) limit 1) 
  			then 
  				select -1 as errcode, 'Inactive Plan' as errmsg;
  				leave sp_exit;
  			End if;         
          
           
           
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  					SELECT did INTO v_dispositionId
  					FROM disposition_status 
  					WHERE domainId = p_domainId
  					AND dispositionName = 'Closed'
                      LIMIT 1;
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
           
          update tb_InstagramHistory set IsSessionClosed = 1, IsBot = 1 where TIMESTAMPDIFF(MINUTE, createdAt, now()) >= 1440 and IsSessionClosed = 0;
          
          update tb_InstagramHistory
  		set  dispositionId = v_dispositionId
  		,	sessionEndTime = unix_timestamp(current_timestamp())*1000
  		where TIMESTAMPDIFF(MINUTE, createdAt, now()) >= 1440 and (sessionEndTime is null or sessionEndTime = 0)
  		and (dispositionId = 0 or dispositionId is null)
          and domainId = p_domainId;
                  
  		
             
     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
             
  		select domainId,isBot into p_domainID,v_IsBot from tb_InstagramConfiguration where InstagramPageId COLLATE utf8mb4_unicode_ci = p_agentInstagramId limit 1;
             
     		SELECT 	TypeCodeID
     		INTO 	v_InstagramCommunicationTypeId
     		FROM 	TypeCode 
     		WHERE 	TypeGroupID 	= 2004
     		AND 	TypeCodeName collate utf8mb4_unicode_ci	= p_InstagramCommunicationType; 
     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         
       	
            
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 			if exists(select 1 from customer_contact  where domainId = p_domainID and  instagram  = p_customerInstagramId and blockCustomer = 1) 
 			then 
 			   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 				select -1 as errcode,'Customer number is blocked' as errmsg;
 				leave sp_exit;
 			End if;
         
 			if exists(select 1 from tb_CurrentPlan where domainId = p_domainID and TotalSession = TotalSessionUsed and isUnilimitedChat = 0 limit 1) 
 			then 
 				select -1 as errcode, 'No Session Available' as errmsg;
 				leave sp_exit;
 			End if;
          
         	sp_return : BEGIN    
         		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         		SELECT 	InstagramHistoryId INTO v_InstagramHistoryId  
         		FROM 	tb_InstagramHistory SH 
         		WHERE 	SH.customerInstagramId 	= p_customerInstagramId 
         		AND 	SH.agentInstagramId 		= p_agentInstagramId  		
         		AND 	IsSessionClosed			= 0
         		ORDER BY InstagramHistoryId DESC LIMIT 1;        
         		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 
         		IF v_InstagramHistoryId IS NULL 
         		THEN      		        
         			INSERT INTO tb_InstagramHistory(sessionId,sessionStartTime,sessionEndTime,domainId,customerInstagramId,agentInstagramId,dispositionId,IsBot,IsInBound,createdAt,updatedAt,IsSessionClosed
                  ,InstagramCommunicationTypeId)
         			VALUES(p_sessionId,p_sessionStartTime,p_sessionEndTime,p_domainID,p_customerInstagramId,p_agentInstagramId,p_dispositionId,p_IsBot,p_IsInBound,v_Curdate,v_Curdate,p_IsSessionClosed
                  ,v_InstagramCommunicationTypeId);
         
         			SET v_InstagramHistoryId = last_insert_id(); 
         
         			SET v_errcode = 0;
         			SET v_errmsg = 'Instagram added successfully';
         			SET v_IsUpdate = 0;
                     
                     
  								UPDATE 	tb_CurrentPlan
  								SET 	
  											TotalSessionUsed			= case when isUnilimitedChat = 1 then TotalSessionUsed else ifnull(TotalSessionUsed,0) + 1 end
  											,updatedDate				= v_Curdate
  								WHERE 	domainId = p_DomainId;
  						
                         
         		ELSE
         			UPDATE tb_InstagramHistory SH
         			SET	SH.sessionStartTime 			= IFNULL(p_sessionStartTime,SH.sessionStartTime), 
         				SH.sessionEndTime  				= IFNULL(p_sessionEndTime,SH.sessionEndTime),
         				SH.customerInstagramId 			= IFNULL(p_customerInstagramId,SH.customerInstagramId),				
         				SH.agentInstagramId 				= IFNULL(p_agentInstagramId,SH.agentInstagramId),
         				SH.dispositionId  				= IFNULL(p_dispositionId,SH.dispositionId),
         				SH.IsInBound					= IFNULL(p_IsInBound,SH.IsInBound),
         				SH.IsBot						= IFNULL(p_IsBot,SH.IsBot),
         				SH.Summary						= IFNULL(p_Summary,SH.Summary),
        				SH.IsSessionClosed				= IFNULL(p_IsSessionClosed,SH.IsSessionClosed),
                      SH.InstagramCommunicationTypeId	= IFNULL(v_InstagramCommunicationTypeId,InstagramCommunicationTypeId),                                
         				SH.updatedAt					= v_Curdate				
         			WHERE InstagramHistoryId				= v_InstagramHistoryId;
                     
         			SET v_errcode = 0;
         			SET v_errmsg = 'Instagram updated successfully';
         			SET v_IsUpdate = 1;
         		END IF; 
              
         		IF JSON_VALID(p_message) = 1 AND v_InstagramCommunicationTypeId IN (2004001,2004002) 
         		THEN
      			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
         			IF EXISTS (SELECT 1 FROM tb_InstagramMessage WHERE InstagramHistoryId = v_InstagramHistoryId) 
         			THEN            
                  SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
         				UPDATE 	tb_InstagramMessage a
         				SET 	a.message 	= IFNULL(JSON_ARRAY_APPEND(a.message, '$', p_message), if(a.message is null,p_message,JSON_ARRAY_APPEND(a.message, '$', p_message)))
  						,	a.domainId 				= p_domainID
  						,	a.customerInstagramId 	= p_customerInstagramId
  						,	a.agentInstagramId 		= p_agentInstagramId
  						,	a.updatedAt	= v_Curdate
         				WHERE 	InstagramHistoryId 	= v_InstagramHistoryId;
         
         				SET v_errmsg = CONCAT(v_errmsg,', Message updated successfully');
         		   ELSE
         				INSERT INTO tb_InstagramMessage
         				(	InstagramHistoryId
  						,Message	
  						,domainId
  						,customerInstagramId
  						,agentInstagramId
  						,createdAt	
  						,updatedAt	
         				)
         				VALUES
         				(	v_InstagramHistoryId
  						,p_message
  						,p_domainID
  						,p_customerInstagramId
  						,p_agentInstagramId
  						,v_Curdate
  						,v_Curdate
         				); 
         			   
         			   SET v_errmsg = CONCAT(v_errmsg,', Message added successfully');
         			END IF;  
         		END IF; 
         	END;   
          	
      	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      	SELECT  v_IsUpdate as IsUpdate,v_InstagramHistoryId as InstagramHistoryId, p_domainID AS domainId, v_errcode AS errcode, v_errmsg AS errmsg 
      		,	FH.sessionId 					            
      		,	FH.domainId 					
      		,	FH.dispositionId 				            
      		,	FH.IsInBound 					
      		,	FH.assignedTo 				
      		,	FH.assignedBy 				                        
      		,	FH.NextFlowNode 				                                    
      		,	FH.markAsReadSupervisor 		
      		,	FH.markAsReadAgent 			
      		,	FH.IsSessionClosed 			
      		,	FH.customerInstagramId			
      		,	FH.agentInstagramId			            			
      		,	FH.AgentId 					
      		,	FH.IsBot 						
      		,	FH.BotId 						
      		,	FH.SentimentalScore 
      		,	FM.Message 
      		,	'Instagram' 	AS channelType
      	FROM 	tb_InstagramHistory	FH
      	JOIN 	tb_InstagramMessage	FM ON FH.InstagramHistoryId = FM.InstagramHistoryId
      	WHERE 	FH.InstagramHistoryId = v_InstagramHistoryId;
      	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateInstagramConfiguration` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
