CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateInstagramConfiguration`(	
	 p_InstagramConfigurationId 	INT 
 	,p_pageName					VARCHAR(250)
 	,p_language					VARCHAR(100)
 	,p_domainId 				INT
 	,p_planId 					INT
 	,p_isBot 					TINYINT
 	,p_isBotPurchased 			TINYINT
 	,p_InstagramFlowId 			INT
 	,p_InstagramPageId 			VARCHAR(50)
 	,p_isActive 				TINYINT 
    ,p_instagramIntegrationId    INT
	,p_callBackToggle			TINYINT
	,p_callBackForm				VARCHAR(10)
	,p_notifyAdmin				VARCHAR(50)
    ,p_knowledgeBaseId 			VARCHAR(100)
 )
BEGIN
 	 DECLARE v_InstagramConfigurationId 	INT;
     DECLARE v_CurDate					DATETIME;
     DECLARE v_errCode					INT	DEFAULT -1;
     DECLARE v_errMsg					VARCHAR(150) DEFAULT 'Insert Update Instagram Configuration Failed';
     
     SET v_CurDate = NOW();
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
     SELECT 	InstagramConfigurationId INTO v_InstagramConfigurationId
     FROM 	tb_InstagramConfiguration
     WHERE 	InstagramConfigurationId = p_InstagramConfigurationId;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
     IF v_InstagramConfigurationId IS NULL
     THEN
 		INSERT INTO tb_InstagramConfiguration
         (	pageName				
             ,`language`				
             ,domainId 				
             ,planId 				
             ,isBot 					
             ,isBotPurchased 		
             ,InstagramFlowId 		
             ,InstagramPageId 		
             ,isActive 	
             ,callBackToggle	
             ,callBackForm	
             ,notifyAdmin
             ,instagramIntegrationId
             ,createdDate 			
             ,updatedDate
             ,knowledgeBaseId
         )
         VALUES
         (	 p_pageName			
             ,p_language			
             ,p_domainId 		
             ,p_planId 			
             ,p_isBot 			
             ,p_isBotPurchased 	
             ,p_InstagramFlowId 	
             ,p_InstagramPageId 	
             ,p_isActive 
             ,p_callBackToggle	
             ,p_callBackForm		
             ,p_notifyAdmin	
             ,p_instagramIntegrationId
             ,v_CurDate
             ,v_CurDate
             ,p_knowledgeBaseId
             );
             
 		SET v_InstagramConfigurationId = last_insert_id();
         SET v_errCode 	= 0
 		,	v_errMsg	= 'Instagram Configuration added successfully';
     ELSE
 		UPDATE 	tb_InstagramConfiguration 
         SET 	pageName					= ifnull(p_pageName	,	pageName )
             ,	`language`					= ifnull(p_language	,	language )						
             ,	planId 						= ifnull(p_planId 	,	planId	)	
             ,	isBot 						= ifnull(p_isBot 	,	isBot )			
             ,	isBotPurchased 				= ifnull(p_isBotPurchased ,	isBotPurchased )	
             ,	InstagramFlowId 			= ifnull(p_InstagramFlowId, InstagramFlowId	)	
             ,	InstagramPageId  			= ifnull(p_InstagramPageId , InstagramPageId )
             ,	isActive 					= ifnull(p_isActive, isActive )
             ,	callBackToggle 				= ifnull(p_callBackToggle, callBackToggle )
             ,	callBackForm 				= ifnull(p_callBackForm, callBackForm )
             ,	notifyAdmin 				= ifnull(p_notifyAdmin, notifyAdmin )
             ,	instagramIntegrationId 		= ifnull(p_instagramIntegrationId, instagramIntegrationId )
             ,	knowledgeBaseId 			= ifnull(p_knowledgeBaseId, knowledgeBaseId )
             ,	updatedDate 				= v_CurDate
         WHERE 	InstagramConfigurationId = v_InstagramConfigurationId;    
     
 		SET v_errCode 	= 0
 		,	v_errMsg	= 'Instagram Configuration added successfully';
     END IF;
     
 	SELECT v_InstagramConfigurationId AS InstagramConfigurationId,v_errCode AS errCode,v_errMsg AS errMsg;
 END ;;
DELIMITER ;
