CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateIrrelevantChatLeadGeneration`(
    p_IrrelevantChatLeadGenerationId           BIGINT ,
    p_Method           VARCHAR (255),
    p_connector        VARCHAR (255),
    p_Email            VARCHAR(255),
    p_ScheduleType     INT,
    p_domainId         INT,
    p_dayStatus        INT,
    p_weekStatus       INT,
    p_Time             BIGINT,
    p_lastUpdatedDate  BIGINT,
    p_timeZone         VARCHAR(255),
    p_HourlyTime		TINYINT,
    p_MinuteTime		TINYINT,
    p_cronId            VARCHAR(255),
    p_chatId            BIGINT)
BEGIN
  	DECLARE v_curdate    DATETIME;
  	DECLARE v_errcode    INT          	DEFAULT -1;
  	DECLARE v_errmsg     VARCHAR(100)	DEFAULT 'Add/Update Irrelevant Chat Lead Generation failed';
	DECLARE v_IrrelevantChatLeadGenerationId	INT; 
	
    SET v_IrrelevantChatLeadGenerationId = NULL;
    
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      SELECT IrrelevantChatLeadGenerationId
	  INTO 	v_IrrelevantChatLeadGenerationId
      FROM 	tb_IrrelevantChatLeadGeneration 
      WHERE 	domainId = p_domainId AND chatId = p_chatId; 
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      
  	IF v_IrrelevantChatLeadGenerationId IS NULL
      THEN
		INSERT INTO tb_IrrelevantChatLeadGeneration (Method,connector,Email,ScheduleType,domainId,weekStatus,dayStatus,`Time`,lastUpdatedDate,timeZone,HourlyTime,MinuteTime,cronId,chatId) 
  		VALUES (p_Method,p_connector,p_Email,p_ScheduleType,p_domainId,p_weekStatus,p_dayStatus,p_Time,p_lastUpdatedDate,p_timeZone,p_HourlyTime,p_MinuteTime,p_cronId,p_chatId);
  		
  		SET v_errcode = 0;
  		SET v_errmsg = 'Inserted Irrelevant Chat Lead Generation Successfully';        
  		
  	ELSE    
        
        UPDATE tb_IrrelevantChatLeadGeneration 
  		SET Method  		= IFNULL(p_Method,Method)
  		,	connector		= IFNULL(p_connector,connector)
  		,	Email			= IFNULL(p_Email,Email)
  		,	ScheduleType	= IFNULL(p_ScheduleType,ScheduleType)
  		,	weekStatus		= IFNULL(p_weekStatus,weekStatus)
  		,	dayStatus		= IFNULL(p_dayStatus,dayStatus)
  		,	`Time`			= IFNULL(p_Time,`Time`)
  		,	lastUpdatedDate = IFNULL(p_lastUpdatedDate,lastUpdatedDate)
  		,	timeZone 		= IFNULL(p_timeZone,timeZone)
		,	HourlyTime		= IFNULL(p_HourlyTime,HourlyTime)
		,   MinuteTime      = IFNULL(p_MinuteTime,MinuteTime)
		,   cronId          = IFNULL(p_cronId, cronId)
  		WHERE IrrelevantChatLeadGenerationId = v_IrrelevantChatLeadGenerationId ;        
          
  		IF ROW_COUNT()>0
  		THEN
  			SET v_errcode = 0;
  			SET v_errmsg = 'Updated Irrelevant Chat Lead Generation Successfully';
  		END IF;
  	END IF; 
      
  	SELECT v_errcode as errcode, v_errmsg as errmsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
