CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateIrrelevantChatQuestionAnswer`(	
	p_chatFlowId		INT
 	,p_domainId			INT
 	,p_questionAnswer	JSON
    ,p_websiteId 		VARCHAR(255)
 )
BEGIN
 	DECLARE v_CurDate		DATETIME;	
 	DECLARE v_errcode 		INT DEFAULT -1;
 	DECLARE v_errmsg 		VARCHAR(150) DEFAULT 'Add Update Irrelevant Chat Question Answer Failed';
     DECLARE v_chatFlowId	INT;
     
	IF p_chatFlowId IS NOT NULL
	THEN     
		 SELECT chatFlowId INTO v_chatFlowId
		 FROM 	tb_IrrelevantChatQuestionAnswer
		 WHERE 	chatFlowId	= p_chatFlowId			
		 AND 	domainId	= p_domainId;
	ELSE
		SELECT chatFlowId INTO v_chatFlowId
		FROM 	tb_IrrelevantChatQuestionAnswer
		WHERE 	websiteId	= p_websiteId
		AND 	domainId	= p_domainId;		
	END IF;
    
    SET v_CurDate = CURDATE();
     
     IF v_chatFlowId IS NULL
     THEN
 		INSERT INTO tb_IrrelevantChatQuestionAnswer
         (	chatFlowId		
             ,domainId		
             ,questionAnswer
             ,websiteId
             ,createDate		
 			,updatedDate	
         )
         VALUES
         (	p_chatFlowId
 			,p_domainId		
             ,p_questionAnswer
             ,p_websiteId
 			,v_CurDate
 			,v_CurDate        
         );
 		
         SET v_errcode	= 0
 		,	v_errmsg 	= 'Added Irrelevant Chat Question Answer Successfully';
 	ELSE
 		UPDATE 	tb_IrrelevantChatQuestionAnswer
         SET 	questionAnswer 	= JSON_ARRAY_APPEND(questionAnswer,'$',p_questionAnswer)        
 			,	updatedDate		= v_CurDate
         WHERE 	chatFlowId 		= p_chatFlowId;
         
 		SET v_errcode	= 0
 		,	v_errmsg 	= 'Updated Irrelevant Chat Question Answer Successfully';
     END IF;
     
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;      	
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdatePlanAddon` */;
