CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdatePlanAddon`(	
	p_planId						INT
 	,p_addonId						INT
 	,p_domainId						INT
	,p_addonRechargeTime			DATETIME
 	,p_noOfAddonChatSessionAgent	INT    
    ,p_noOfAddonChatSessionBot		INT    
 )
BEGIN
 	DECLARE v_planRechargeId	INT;
 	DECLARE v_curDate			DATETIME DEFAULT NOW();
 	DECLARE v_errCode			TINYINT DEFAULT -1;
     DECLARE v_errMsg			VARCHAR(250) DEFAULT 'Adding addon failed';
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     SELECT planRechargeId INTO v_planRechargeId
     FROM 	tb_PlanRecharge
     WHERE 	planId = p_planId
     AND 	v_curDate BETWEEN planStartTime AND planEndTime;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
     
     INSERT INTO tb_PlanAddon
     (	planRechargeId
 		,planId					
 		,addonId				
 		,domainId				
 		,addonRechargeTime		
 		,noOfAddonChatSessionAgent	
        ,noOfAddonChatSessionBot	
 		,createdDate			
 		,updatedDate			
     )
     VALUES
     (	v_planRechargeId
 		,p_planId				
         ,p_addonId				
         ,p_domainId				
         ,p_addonRechargeTime	
         ,p_noOfAddonChatSessionAgent	
         ,p_noOfAddonChatSessionBot
         ,v_curDate
         ,v_curDate
     );
     
 	UPDATE 	tb_CurrentPlan
 	SET 	planId				 		= p_planId			
 		,	chatRemainingSessionAgent 	= chatRemainingSessionAgent + p_noOfAddonChatSessionAgent
        ,	chatRemainingSessionBot 	= chatRemainingSessionBot + p_noOfAddonChatSessionBot
 		,	updatedDate			 		= v_curDate
 	WHERE 	domainId			 		= p_domainId;		
     
	SET v_errCode	= 0
 	,	v_errMsg	= 'Addon added successfully';    
     
    SELECT v_errCode AS errCode, errMsg	AS errMsg;  
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdatePlanAddon_v2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdatePlanAddon_v2`(	
 	p_planId						INT
  	,p_addonId						INT
  	,p_domainId						INT
 	,p_addonRechargeTime			DATETIME
  	,p_noOfAddonChatSessionAgent	INT    
	,p_noOfAddonChatSessionBot		INT
	,p_extraSessionAdded			INT
  )
BEGIN
  	DECLARE v_planRechargeId	INT;
  	DECLARE v_curDate			DATETIME DEFAULT NOW();
  	DECLARE v_errCode			TINYINT DEFAULT -1;
	DECLARE v_errMsg			VARCHAR(250) DEFAULT 'Adding addon failed';
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      SELECT planRechargeId INTO v_planRechargeId
      FROM 	tb_PlanRecharge
      WHERE planId = p_planId and domainId = p_domainId
      AND 	v_curDate BETWEEN planStartTime AND planEndTime;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
      
      INSERT INTO tb_PlanAddon
      (	planRechargeId
  		,planId					
  		,addonId				
  		,domainId				
  		,addonRechargeTime		
  		,noOfAddonChatSessionAgent	
		,noOfAddonChatSessionBot	
  		,createdDate			
  		,updatedDate
        ,extraSessionAdded
      )
      VALUES
      (	v_planRechargeId
  		,p_planId				
          ,p_addonId				
          ,p_domainId				
          ,p_addonRechargeTime	
          ,p_noOfAddonChatSessionAgent	
          ,p_noOfAddonChatSessionBot
          ,v_curDate
          ,v_curDate
          ,p_extraSessionAdded
      );
      
		IF v_planRechargeId IS NOT NULL THEN
			UPDATE tb_PlanRecharge
			SET TotalSession = (TotalSession + p_extraSessionAdded),
				isChatSessionMovedToCurrentPlan = 1
			WHERE planId = p_planId AND domainId = p_domainId
			AND	v_curDate BETWEEN planStartTime AND planEndTime;
		Else
			UPDATE tb_PlanRecharge
			SET TotalSession = (p_noOfAddonChatSessionAgent + p_noOfAddonChatSessionBot),
				isChatSessionMovedToCurrentPlan = 1
			WHERE planId = p_planId AND domainId = p_domainId;
		
		END IF;
        
	
	insert into tb_CurrentPlan_log(planId, domainId, chatRemainingSessionAgent, chatRemainingSessionBot, isUnilimitedChat)
	select planId, domainId, p_noOfAddonChatSessionAgent, p_noOfAddonChatSessionBot, isUnilimitedChat
	from tb_CurrentPlan where domainId = p_domainId;
   
      
  	UPDATE 	tb_CurrentPlan
  	SET 	planId				 		= p_planId			
  		,	chatRemainingSessionAgent 	= chatRemainingSessionAgent + p_noOfAddonChatSessionAgent
        ,	chatRemainingSessionBot 	= chatRemainingSessionBot + p_noOfAddonChatSessionBot
  		,	updatedDate			 		= v_curDate
        ,	TotalSession				= (TotalSession + p_extraSessionAdded)
  	WHERE 	domainId			 		= p_domainId;		
      
 	SET v_errCode	= 0
  	,	v_errMsg	= 'Addon added successfully';    
      
     SELECT v_errCode AS errCode, v_errMsg	AS errMsg;  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdatePlanAddon_v2_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdatePlanAddon_v2_test`(	
 	p_planId						INT
  	,p_addonId						INT
  	,p_domainId						INT
 	,p_addonRechargeTime			DATETIME
  	,p_noOfAddonChatSessionAgent	INT    
	,p_noOfAddonChatSessionBot		INT
	,p_extraSessionAdded			INT
  )
BEGIN
  	DECLARE v_planRechargeId	INT;
  	DECLARE v_curDate			DATETIME DEFAULT NOW();
  	DECLARE v_errCode			TINYINT DEFAULT -1;
	DECLARE v_errMsg			VARCHAR(250) DEFAULT 'Adding addon failed';
    DECLARE v_chatRemainingSessionAgent	INT;
    DECLARE v_chatRemainingSessionBot	INT;
    DECLARE v_TotalSession				INT;
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      SELECT planRechargeId INTO v_planRechargeId
      FROM 	tb_PlanRecharge
      WHERE planId = p_planId and domainId = p_domainId
      AND 	v_curDate BETWEEN planStartTime AND planEndTime;
      
      SELECT chatRemainingSessionAgent,chatRemainingSessionBot,TotalSession INTO v_chatRemainingSessionAgent,v_chatRemainingSessionBot,v_TotalSession
      FROM tb_CurrentPlan
      WHERE domainId = p_domainId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
      
      INSERT INTO tb_PlanAddon
      (	planRechargeId
  		,planId					
  		,addonId				
  		,domainId				
  		,addonRechargeTime		
  		,noOfAddonChatSessionAgent	
		,noOfAddonChatSessionBot	
  		,createdDate			
  		,updatedDate
        ,extraSessionAdded
      )
      VALUES
      (	v_planRechargeId
  		,p_planId				
          ,p_addonId				
          ,p_domainId				
          ,p_addonRechargeTime	
          ,p_noOfAddonChatSessionAgent	
          ,p_noOfAddonChatSessionBot
          ,v_curDate
          ,v_curDate
          ,p_extraSessionAdded
      );
      
	insert into tb_PlanRecharge_log(planRechargeId, planId, domainId, planrechargeTime, planStartTime, planEndTime, noOfPlanChatSessionAgent, noOfPlanChatSessionBot, isChatSessionMovedToCurrentPlan, isUnilimitedChat, createdDate, updatedDate, TotalSession, log_date)
    select planRechargeId, planId, domainId, planrechargeTime, planStartTime, planEndTime, noOfPlanChatSessionAgent, noOfPlanChatSessionBot, isChatSessionMovedToCurrentPlan, isUnilimitedChat, createdDate, updatedDate, TotalSession, NOW()
	from tb_PlanRecharge where domainId = p_domainId;
    
		IF v_planRechargeId IS NOT NULL THEN
			UPDATE tb_PlanRecharge
			SET TotalSession = v_chatRemainingSessionAgent + v_chatRemainingSessionBot + p_extraSessionAdded,
				noOfPlanChatSessionAgent = v_chatRemainingSessionAgent + p_noOfAddonChatSessionAgent,
				noOfPlanChatSessionBot = v_chatRemainingSessionBot +  p_noOfAddonChatSessionBot,
				isChatSessionMovedToCurrentPlan = 1
			WHERE planId = p_planId AND domainId = p_domainId
			AND	v_curDate BETWEEN planStartTime AND planEndTime;
		Else
			UPDATE tb_PlanRecharge
			SET TotalSession = (p_noOfAddonChatSessionAgent + p_noOfAddonChatSessionBot),
				noOfPlanChatSessionAgent = p_noOfAddonChatSessionAgent,
				noOfPlanChatSessionBot = p_noOfAddonChatSessionBot,
				isChatSessionMovedToCurrentPlan = 1
			WHERE planId = p_planId AND domainId = p_domainId;
		
		END IF;
        
	insert into tb_CurrentPlan_log(planId, domainId, chatRemainingSessionAgent, chatRemainingSessionBot, isUnilimitedChat, logdate, updatedDate, TotalSession, TotalSessionUsed, IsEmailSent)
	select planId, domainId, chatRemainingSessionAgent, chatRemainingSessionBot, isUnilimitedChat, NOW(), updatedDate, TotalSession, TotalSessionUsed, IsEmailSent
	from tb_CurrentPlan where domainId = p_domainId;
  
	UPDATE 	tb_CurrentPlan
  	SET 	planId				 		= p_planId
		,	TotalSession				= (chatRemainingSessionAgent + chatRemainingSessionBot + p_extraSessionAdded)
  		,	chatRemainingSessionAgent 	= chatRemainingSessionAgent + p_noOfAddonChatSessionAgent
        ,	chatRemainingSessionBot 	= chatRemainingSessionBot + p_noOfAddonChatSessionBot
  		,	updatedDate			 		= v_curDate
        ,	TotalSessionUsed			= 0
  	WHERE 	domainId			 		= p_domainId;		
      
 	SET v_errCode	= 0
  	,	v_errMsg	= 'Addon added successfully';    
      
     SELECT v_errCode AS errCode, v_errMsg	AS errMsg;  
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
