CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdatequeueWeighTimeChat`(  p_qid 					INT,
   p_queueName 				VARCHAR(255),   
   p_domainId 				INT,
   p_queueList 				TEXT
)
BEGIN
	DECLARE v_CurDate				DATETIME DEFAULT NOW();
	DECLARE v_errCode				SMALLINT DEFAULT -1;
    DECLARE v_errMsg				VARCHAR(150) DEFAULT 'Add/Update chat queue weigh time failed';
    DECLARE v_queueWeighTimeChatId 	INT;
   
	SELECT 	queueWeighTimeChatId INTO v_queueWeighTimeChatId
    FROM 	queueWeighTimeChat
    WHERE 	qid			= p_qid
    AND 	domainId	= p_domainId;
    
    IF v_queueWeighTimeChatId IS NULL
    THEN
		INSERT INTO queueWeighTimeChat
        (	`qid` 					
            ,`queueName` 				
            ,`domainId` 				
            ,`queueList` 				
            ,`createdAt` 				
            ,`updatedAt` 		
        )
        VALUES
        (	 p_qid 		
            ,p_queueName 	
            ,p_domainId 	
            ,p_queueList 	        
			,v_CurDate
			,v_CurDate
        );
        
        SET v_queueWeighTimeChatId	= last_insert_id()
		,	v_errCode				= 0
        ,	v_errMsg				= 'Chat queue weigh time added successfully';
	ELSE
		UPDATE 	queueWeighTimeChat
        SET 	`qid` 			= p_qid 				
                ,`queueName` 	= p_queueName 				
                ,`domainId` 	= p_domainId 				
                ,`queueList` 	= p_queueList 				
                ,`updatedAt` 	= v_CurDate
        WHERE 	queueWeighTimeChatId = v_queueWeighTimeChatId;
        
        SET v_errCode				= 0
        ,	v_errMsg				= 'Chat queue weigh time updated successfully';
    END IF;
    
	SELECT v_queueWeighTimeChatId AS queueWeighTimeChatId, v_errCode AS errCode, v_errMsg AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
