CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdatereport_config`(	
	p_domainId		INT
 	,p_ext			INT
 	,p_editColumn	LONGTEXT
     ,p_reportType	VARCHAR(50)
 )
BEGIN
 	DECLARE v_errcode  		INT DEFAULT 		-1;
	DECLARE v_errmsg   		VARCHAR(55) DEFAULT 'No Record to Config';
   	DECLARE v_CurDate		BIGINT;
 	DECLARE v_reportId		INT;
     
     SET v_CurDate  = unix_timestamp(current_timestamp()) * 1000;
 	
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	SELECT reportId INTO v_reportId
	FROM 	report_config RC
	WHERE 	RC.domainId 	= p_domainId
	AND 	RC.ext			= p_ext
	AND		RC.reportType 	= p_reportType COLLATE utf8mb4_0900_ai_ci;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;

     IF v_reportId IS NULL
     THEN
 		INSERT INTO report_config
         (	domainId
 			,ext
 			,editColumn			
 			,reportType
             ,createdAt
 			,updatedAt
         )
         VALUES
         (	p_domainId		
             ,p_ext			
             ,p_editColumn	
             ,p_reportType	
 			,v_CurDate
             ,v_CurDate        
         );
         
         SET v_reportId 	= last_insert_id();
 		SET v_errcode 	= 0;
 		SET v_errmsg 	= 'Configuration Inserted Successfully';        
 	ELSE
 		UPDATE 	report_config
         SET 	editColumn	= p_editColumn           
                 ,updatedAt	= v_CurDate
 		WHERE 	reportId 	= v_reportId;
         
 		SET v_errcode 	= 0;
 		SET v_errmsg 	= 'Configuration Updated Successfully';                
     END IF;
 
 	SELECT v_reportId reportId, p_domainId	domainId, p_ext ext, p_editColumn editColumn, p_reportType reportType, v_errcode errcode, v_errmsg errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
