CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateskills`(
    IN p_domainId INT,
    IN p_sid INT,
    IN p_skill_name VARCHAR(255),
    IN p_skill_description VARCHAR(255),
    IN p_status INT,
    IN p_type VARCHAR(255)
  )
BEGIN
      DECLARE v_errCode TINYINT DEFAULT -1;
      DECLARE v_errMsg VARCHAR(150) DEFAULT 'Insert Update skills failed';
      DECLARE v_CurDate DATETIME DEFAULT NOW();
      DECLARE v_existing_sid INT;
  
      SELECT sid INTO v_existing_sid
      FROM skills
      WHERE sid = p_sid AND domainId = p_domainId;
  
      Logic_block: BEGIN
          IF v_existing_sid IS NOT NULL THEN
              IF EXISTS(
                  SELECT sid
                  FROM skills
                  WHERE sid <> p_sid AND domainId = p_domainId AND skill_name = p_skill_name collate utf8mb4_0900_ai_ci
              ) THEN
                  SET v_errCode = -2;
                  SET v_errMsg = 'Skill Name already exists';
                  LEAVE Logic_block;
              END IF;
  
              UPDATE skills
              SET
                  skill_name = IFNULL(p_skill_name, skill_name),
                  skill_description = IFNULL(p_skill_description, skill_description),
                  status = IFNULL(p_status, status),
                  type = IFNULL(p_type, type),
                  updatedAt = v_CurDate
              WHERE sid = v_existing_sid;
  
              SET v_errCode = 0;
              SET v_errMsg = 'Skill updated successfully';
          ELSE
              IF EXISTS(
                  SELECT sid
                  FROM skills
                  WHERE domainId = p_domainId AND skill_name = p_skill_name collate utf8mb4_0900_ai_ci
              ) THEN
                  SET v_errCode = -2;
                  SET v_errMsg = 'Skill Name already exists';
                  LEAVE Logic_block;
              END IF;
  
              INSERT INTO skills (
                  skill_name,
                  skill_description,
                  domainId,
                  status,
                  type,
                  createdAt,
                  updatedAt
              )
              VALUES (
                  p_skill_name,
                  p_skill_description,
                  p_domainId,
                  IFNULL(p_status, 0),
                  p_type,
                  v_CurDate,
                  v_CurDate
              );
  
              SET v_existing_sid = LAST_INSERT_ID();
              SET v_errCode = 0;
              SET v_errMsg = 'Skill inserted successfully';
          END IF; 
      END; 
  
      SELECT v_existing_sid AS 'sid', v_errCode AS errCode, v_errMsg AS errMsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
