CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateSMS`(	
          	p_sessionId			TEXT, 
          	p_sessionStartTime	BIGINT,
          	p_sessionEndTime	BIGINT,
          	p_domainID			INT,
          	p_message			JSON,
          	p_customerNumber	BIGINT,
          	p_calledNumber		BIGINT,
          	p_dispositionId		INT,
          	p_IsInBound			TINYINT,
          	p_IsSessionClosed	TINYINT,
          	p_IsBot				INT,
  			p_Summary			TEXT
          )
sp_exit: BEGIN
             
    			DECLARE v_errcode 			INT DEFAULT -1;
    			DECLARE v_errmsg 			VARCHAR(55) DEFAULT 'No SMS';	
    			DECLARE v_SMSHistoryId		BIGINT;
    			DECLARE v_Curdate			DATETIME;
    			DECLARE v_IsUpdate			TINYINT;
 			DECLARE v_sessionStartTime	BIGINT;
 			DECLARE v_domainID			BIGINT;
 			DECLARE v_isSms			TINYINT;
                
                select domainId ,isSms into v_domainID ,v_isSms from did_purchase where your_number COLLATE utf8mb4_unicode_ci = p_calledNumber limit 1;
           
   			if v_isSms = 0 then
   				select -2 as errcode,'isSms is 0' as errmsg;
   				leave sp_exit;
   			End if;
           
      			if exists(select 1 from customer_contact  where domainId = v_domainID and (primaryPhoneNumber like p_customerNumber OR phoneNumber like concat('%',p_customerNumber,'%')) and blockCustomer = 1) then 
      				select -1 as errcode,'Customer number is blocked' as errmsg;
                      leave sp_exit;
                  End if;
                         
            		SET v_Curdate  = NOW();    
                    SET v_sessionStartTime = unix_timestamp(v_Curdate) * 1000;
                 
         			insert into up_InsertUpdateSMS_log(p_sessionId, p_sessionStartTime,p_sessionEndTime,p_domainID,p_message,p_customerNumber,p_calledNumber,p_dispositionId,p_IsInBound,p_IsSessionClosed,p_IsBot)
         			values(p_sessionId ,v_sessionStartTime,p_sessionEndTime,v_domainID,p_message,p_customerNumber,p_calledNumber,p_dispositionId,p_IsInBound,p_IsSessionClosed,p_IsBot);
                  
  				if exists(select 1 from tb_PlanRecharge where domainId = p_domainID and cast(planEndTime as date) < cast(v_Curdate as date) limit 1) 
  				then 
  					select -1 as errcode, 'Inactive Plan' as errmsg;
  					leave sp_exit;
  				End if;
  				
  				if exists(select 1 from tb_CurrentPlan where domainId = p_domainID and TotalSession = TotalSessionUsed and isUnilimitedChat = 0 limit 1) 
  				then 
  					select -1 as errcode, 'No Session Available' as errmsg;
  				leave sp_exit;
  				End if;
               
      		sp_return : BEGIN                   
               		SELECT 	SMSHistoryId INTO v_SMSHistoryId
              		FROM 	tb_SMSHistory SH 
              		WHERE 	SH.customerNumber 	= p_customerNumber 
              		AND 	SH.calledNumber 	= p_calledNumber  		
              		AND 	IsSessionClosed		= 0
                      AND 	domainId			= v_domainID
              		ORDER BY SMSHistoryId DESC LIMIT 1;
                                        
              		IF v_SMSHistoryId IS NULL 
                      THEN      			            
              			INSERT INTO tb_SMSHistory
                          (	sessionId
             				,sessionStartTime
             				,domainID                
             				,customerNumber
             				,calledNumber
             				,dispositionId   
             				,IsInBound
             				,createdAt
             				,updatedAt
         					,IsSessionClosed
                           ,Summary
              			)
              			VALUES
                          (	p_sessionId
              				,v_sessionStartTime
                              ,v_domainID                
                              ,p_customerNumber
                              ,p_calledNumber
                              ,p_dispositionId
                              ,p_IsInBound
                              ,v_Curdate
                              ,v_Curdate
                              ,p_IsSessionClosed
                              ,p_Summary
              			);
                  
              			SET v_SMSHistoryId = last_insert_id();  
                                                  
                          INSERT INTO tb_SMSDurationHistory(SMSHistoryId,AgentId,AgentSkillId,IsBot,BotId,QueueId,createdAt)
                          VALUES(v_SMSHistoryId,null,null,p_IsBot,null,null,now());
                          
              			SET v_errcode = 0;
              			SET v_errmsg = 'SMS added successfully';
                         SET v_IsUpdate = 0;
                         
 							UPDATE 	tb_CurrentPlan
 							SET 	TotalSessionUsed			= case when isUnilimitedChat = 1 then TotalSessionUsed else ifnull(TotalSessionUsed,0) + 1 end
 									,updatedDate				= v_Curdate
 							WHERE 	domainId = p_domainID;
                         
              		ELSE
          				UPDATE tb_SMSHistory SH
          				SET	SH.customerNumber 	= IFNULL(p_customerNumber,SH.customerNumber),				
  							SH.calledNumber 	= IFNULL(p_calledNumber,SH.calledNumber),
  							SH.dispositionId  	= IFNULL(p_dispositionId,SH.dispositionId),
  							SH.IsInBound		= IFNULL(p_IsInBound,SH.IsInBound),
  							SH.updatedAt		= v_Curdate,
  							SH.IsSessionClosed	= IFNULL(p_IsSessionClosed,SH.IsSessionClosed),
  							SH.Summary			= IFNULL(p_Summary,Summary),
  							SH.sessionEndTime	= IFNULL(p_sessionEndTime,sessionEndTime)
          				WHERE SMSHistoryId		= v_SMSHistoryId;
                          
             			SET v_errcode = 0;
             			SET v_errmsg = 'SMS updated successfully';
                         SET v_IsUpdate = 1;
                      
          				UPDATE tb_SMSDurationHistory	
          					SET IsBot = p_IsBot,
          						updatedAt = v_Curdate
                          WHERE SMSHistoryId		= v_SMSHistoryId;
          
              		END IF; 
               		
              		IF JSON_VALID(p_message) = 1
                      THEN
              			IF EXISTS (	SELECT 	1 
              						FROM 	tb_SMSMessage 
                                      WHERE 	SMSHistoryId = v_SMSHistoryId)
              			THEN            
              				UPDATE 	tb_SMSMessage a
              				SET 	a.message 		= JSON_ARRAY_APPEND(a.message, '$', p_message) 
              				WHERE 	SMSHistoryId 	= v_SMSHistoryId;
                              
                              SET v_errmsg = CONCAT(v_errmsg,', Message updated successfully');
                          ELSE
              				INSERT INTO tb_SMSMessage
              				(	SMSHistoryId
              					,Message	
              					,createdAt	
              					,updatedAt	
              				)
              				VALUES
              				(	v_SMSHistoryId
              					,p_message
              					,v_Curdate
              					,v_Curdate
              				); 
                              
                              SET v_errmsg = CONCAT(v_errmsg,', Message added successfully');
              			END IF;  
              		END IF; 
              	END ;   
                  
              	
            	SELECT 'Sms' channelType,v_IsUpdate AS IsUpdate,v_domainID AS domainId, v_errcode AS errcode, v_errmsg AS errmsg,sh.*,sd.*,sm.*
               from tb_SMSHistory 					sh
           	left join tb_SMSDurationHistory 	sd on sh.SMSHistoryId = sd.SMSHistoryId
           	join tb_SMSMessage					sm on sh.SMSHistoryId = sm.SMSHistoryId
           	where sh.SMSHistoryId = v_SMSHistoryId;       
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateStoreConnection` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateStoreConnection`(	 
	p_conId					INT
	,p_domainId				INT	
	,p_shopDomain			VARCHAR(100)
	,p_accessToken			VARCHAR(250)
	,p_isConnected			TINYINT
	,p_connectionName		VARCHAR(250)
	,p_connectorName		VARCHAR(100)
	,p_syncStatus			tinyint
	,p_contactSyncDetails	JSON
	,p_token				LONGTEXT
	,p_userName            	VARCHAR(150)      
	,p_pwd                 	VARCHAR(100) 
	,p_syncTime 			BIGINT
	,p_scriptId				VARCHAR(1000)
	,p_botData 				VARCHAR(1000)
	,p_chatWidgetStatus 	TINYINT
	,p_settings				JSON
	,p_contactSyncType 		VARCHAR(10)
)
BEGIN
     		DECLARE v_CurDate		DATETIME;
     		DECLARE v_errCode		INT	DEFAULT -1;
     		DECLARE v_errMsg		VARCHAR(150) DEFAULT 'Failed to Insert/Update Store Connection';
               
     		SET v_CurDate =  NOW();
     
     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
           	IF EXISTS (	SELECT 	1
     					FROM 	tb_StoreConnection
     					WHERE 	conId		= p_conId
     					AND 	domainId	= p_domainId
     					AND 	shopDomain 	= p_shopDomain collate utf8mb4_0900_ai_ci	
						AND  	isConnected = 1 )
           	THEN			
     			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
           		UPDATE 	tb_StoreConnection
                   SET 	accessToken			= IFNULL(p_accessToken,	accessToken)
     				,	isConnected			= IFNULL(p_isConnected,isConnected)	
     				,   connectionName		= IFNULL(p_connectionName,connectionName)			
     				,	connectorName		= IFNULL(p_connectorName,connectorName)		
     				,	token				= IFNULL(p_token,token)
     				,	syncStatus			= IFNULL(p_syncStatus,syncStatus)			
     				,	contactSyncDetails	= IFNULL(p_contactSyncDetails,contactSyncDetails)
                    ,	contactSyncType		= IFNULL(p_contactSyncType,contactSyncType)
     				,   userName            = IFNULL(p_userName,userName)
     				,   pwd                 = IFNULL(p_pwd,pwd)
     				,	syncTime 			= IFNULL(p_syncTime,syncTime)
 					,	scriptId			= IFNULL(p_scriptId,scriptId)			
 					,   botData 			= IFNULL(p_botData,botData) 		
 					,   chatWidgetStatus	= IFNULL(p_chatWidgetStatus,chatWidgetStatus)
 					,   settings			= IFNULL(p_settings,settings)                    
     				,	updatedDate			= v_CurDate
         		WHERE 	conId				= p_conId
         		AND 	domainId			= p_domainId
         		AND 	shopDomain			= p_shopDomain collate utf8mb4_0900_ai_ci 
                 AND     isConnected         = 1;
                   
           		SET v_errCode	= 0
           		,	v_errMsg	= 'Store Connection Updated Successfully';	
               ELSE
           		INSERT INTO tb_StoreConnection
                   (	conId
 					,domainId
 					,shopDomain
 					,accessToken
 					,isConnected
 					,connectionName
 					,connectorName		
 					,token
 					,syncStatus			
 					,contactSyncDetails	
                    ,contactSyncType
 					,scriptId			
 					,botData 		
 					,chatWidgetStatus
 					,pwd
 					,userName
 					,createDate
 					,updatedDate
                     ,settings)
                   VALUES
                   (	p_conId		
 					,p_domainId		
 					,p_shopDomain	
 					,p_accessToken	
 					,p_isConnected	
 					,p_connectionName
 					,p_connectorName	
 					,p_token
 					,ifnull(p_syncStatus,0)			
 					,p_contactSyncDetails
                    ,p_contactSyncType
 					,p_scriptId		
 					,p_botData 		
 					,p_chatWidgetStatus
 					,p_pwd
 					,p_userName               
 					,v_CurDate
 					,v_CurDate
 					,p_settings);        
 
                      SET 	v_errCode	= 0
     					,	v_errMsg	= 'Store Connection Inserted Successfully';	
               END IF;
               
               SELECT 	v_errCode AS errCode,v_errMsg AS errMsg;	
           END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
