CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateThirdPartyLoginCode`(
p_clientId			VARCHAR(500)
,p_sipLoginId		INT
,p_domainId			INT
,p_loginCode		VARCHAR(500)
,p_oauthToken		VARCHAR(5000)
,p_entryTime		BIGINT
,p_expireTime		BIGINT

 )
BEGIN
 	DECLARE v_curDate				DATETIME DEFAULT NOW();
	DECLARE v_thirdPartyLoginCodeId	INT;
 	DECLARE v_errCode				SMALLINT DEFAULT -1;
 	DECLARE v_errMsg				VARCHAR(150) DEFAULT 'Insert/Update third party login code failed';
     
     SELECT thirdPartyLoginCodeId INTO v_thirdPartyLoginCodeId
     FROM 	tb_thirdPartyLoginCode
     WHERE 	clientId	= p_clientId	
     AND 	sipLoginId	= p_sipLoginId
     AND 	domainId	= p_domainId;
     
     IF v_thirdPartyLoginCodeId IS NULL
     THEN
 		INSERT INTO tb_thirdPartyLoginCode(	
 			clientId				
             ,sipLoginId		
             ,domainId
             ,loginCode		
             ,oauthToken
             ,entryTime				
             ,expireTime				
             ,loginCount				
             ,createdAt				
             ,updatedAt				
         )
 		VALUES(
			p_clientId		
			,p_sipLoginId	
			,p_domainId
			,p_loginCode	
			,p_oauthToken
			,p_entryTime	
			,p_expireTime	
			,1
			,v_curDate
			,v_curDate
         );
         
         SET v_errCode 	= 1
 		,	v_errMsg	= 'Added third party login code susseccfully';	
 	ELSE
 		UPDATE 	tb_thirdPartyLoginCode
         SET loginCode	= p_loginCode
         ,	oauthToken	= p_oauthToken
         ,	entryTime	= p_entryTime	
         ,	expireTime	= p_expireTime
         ,	loginCount	= loginCount + 1
         ,	updatedAt	= v_curDate
         WHERE thirdPartyLoginCodeId = v_thirdPartyLoginCodeId;
         
         SET v_errCode 	= 2
			,v_errMsg	= 'Updated third party login code susseccfully';	
     END IF;
 
 	SELECT v_errCode AS errCode, v_errMsg AS errMsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
