CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketAutoAssignRule`(
	p_CompanyId 					INT
	,p_ProductId 					INT
	,p_TicketAutoAssignRuleId		BIGINT        
	,p_RuleName						VARCHAR(250)
	,p_RuleDescription				TEXT
	,p_IsRoundRobin					TINYINT
	,p_IsThreshold					TINYINT
	,p_Threshold					SMALLINT
	,p_GroupId						INT    
    ,p_UserId						BIGINT    
	,p_AutoAssignRuleAllCondition	JSON
	,P_AutoAssignRuleAnyCondition	JSON	
	,p_LoggedInUserId 				BIGINT
	,p_LoggedInUser					VARCHAR(250)
  )
BEGIN   
  	DECLARE v_errcode 					INT DEFAULT -1;
    	DECLARE v_errmsg 					VARCHAR(200) DEFAULT 'No AutoAssignRule';    
    	DECLARE v_now 						DATETIME;
    	DECLARE v_JLength					INT;    
   	DECLARE v_TicketAutoAssignRuleId	BIGINT;
     DECLARE v_LoggedInUserId 			BIGINT;
     
    	SET v_now	= CURRENT_TIMESTAMP();
     
  	SELECT 	UserId INTO v_LoggedInUserId    
 	FROM 	tb_TicketUser
 	WHERE 	UserId = p_LoggedInUserId;  
     
     IF v_LoggedInUserId IS NULL
     THEN
 		INSERT INTO tb_TicketUser
         (	UserId
 			,UserName
             ,IsActive
             ,IsDeleted
             ,CompanyId
             ,ProductId
             ,CreatedBy
             ,CreatedDate
             ,UpdatedBy
             ,UpdatedDate
         )
         VALUES
         (	p_LoggedInUserId
 			,p_LoggedInUser
             ,1
             ,0
             ,p_CompanyId
             ,p_ProductId
             ,p_LoggedInUserId
             ,v_now
             ,p_LoggedInUserId
             ,v_now
         );
     ELSE 
 		UPDATE 	tb_TicketUser
         SET 	UserName 	= p_LoggedInUser
 			,	IsActive	= 1
             ,	IsDeleted	= 0
 			,	UpdatedBy	= p_LoggedInUserId
             ,	UpdatedDate	= v_now
         WHERE 	UserId 		= p_LoggedInUserId;        
     END IF;
       
 	SELECT 	TicketAutoAssignRuleId INTO v_TicketAutoAssignRuleId    
 	FROM 	tb_TicketAutoAssignRule
 	WHERE 	TicketAutoAssignRuleId = p_TicketAutoAssignRuleId;           
     
   	spexit : BEGIN 
 		IF v_TicketAutoAssignRuleId IS NULL
         THEN
 			INSERT INTO tb_TicketAutoAssignRule
 			(	RuleName				
 				,RuleDescription		
 				,IsRoundRobin			
 				,IsThreshold			
 				,Threshold				
 				,GroupId	
                ,UserId
 				,IsActive				
 				,IsDeleted				
 				,CompanyId				
 				,ProductId				
 				,CreatedBy				
 				,CreatedDate				
 				,UpdatedBy				
 				,UpdatedDate			
 			)
             VALUES
             (	p_RuleName						
 				,p_RuleDescription
                 ,p_IsRoundRobin
                 ,p_IsThreshold	
                 ,p_Threshold	
                 ,p_GroupId		
                 ,p_UserId
                 ,1
                 ,0
                 ,p_CompanyId 	
 				,p_ProductId 	
                 ,p_LoggedInUserId
 				,v_now
 				,p_LoggedInUserId
 				,v_now                  
             );
             
 			SET v_TicketAutoAssignRuleId = last_insert_id();
 			SET v_errcode	= 0;
 			SET v_errmsg 	= 'Inserted Sucessfully';
 		ELSE
 			UPDATE 	tb_TicketAutoAssignRule
 			SET 	RuleName				= p_RuleName
				,	RuleDescription			= p_RuleDescription
				,	IsRoundRobin			= p_IsRoundRobin
				,	IsThreshold				= p_IsThreshold
				,	Threshold				= p_Threshold
				,	GroupId					= p_GroupId
				,	UserId					= p_UserId
				,	UpdatedBy				= p_LoggedInUserId
				,	UpdatedDate				= v_now
 			WHERE TicketAutoAssignRuleId 	= v_TicketAutoAssignRuleId;
 
 			SET v_errcode	= 0;
 			SET v_errmsg 	= 'Updated Sucessfully';                              
         END IF; 
         
   		SET v_JLength = JSON_LENGTH(p_AutoAssignRuleAllCondition, "$");
           
    		DROP TEMPORARY TABLE IF EXISTS tt_AllCondition;
    		CREATE TEMPORARY TABLE tt_AllCondition       
    		WITH RECURSIVE  CTE_JsonCount as
    		(	SELECT 	0 SlNo
    			UNION ALL
    			SELECT 	SlNo + 1	SlNo
    			FROM 	CTE_JsonCount
    			WHERE 	SlNo  < v_JLength - 1
    		)
    		SELECT  TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAllCondition, CONCAT('$[',SlNo,'].TicketAutoAssignAllConditionId')))) 	AS TicketAutoAssignAllConditionId,
    				TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAllCondition, CONCAT('$[',SlNo,'].AllFieldTypeId'))))      			AS AllFieldTypeId,
    				TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAllCondition, CONCAT('$[',SlNo,'].AllOperatorTypeId')))) 	   			AS AllOperatorTypeId,
					TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAllCondition, CONCAT('$[',SlNo,'].AllFieldValues')))) 	   				AS AllFieldValues
    		FROM CTE_JsonCount;	
           
   		DELETE 	AC
 		FROM 	tb_TicketAutoAssignAllCondition	AC
         LEFT JOIN tt_AllCondition				t_AC 	ON 	AC.TicketAutoAssignAllConditionId 	= t_AC.TicketAutoAssignAllConditionId 
   														AND	t_AC.TicketAutoAssignAllConditionId	<> 0
   		WHERE 	t_AC.TicketAutoAssignAllConditionId IS NULL
         AND 	AC.TicketAutoAssignRuleId = v_TicketAutoAssignRuleId;                 
           
   		INSERT INTO tb_TicketAutoAssignAllCondition
   		(	TicketAutoAssignRuleId			
   			,AllFieldTypeId				
   			,AllOperatorTypeId				
   			,AllFieldValues				
   			,CreatedBy					
   			,CreatedDate				
   			,UpdatedBy					
   			,UpdatedDate)
   		SELECT 	v_TicketAutoAssignRuleId
 			,	AC.AllFieldTypeId
 			,	AC.AllOperatorTypeId
 			,	AC.AllFieldValues
 			,	p_LoggedInUserId
 			,	v_now
 			,	p_LoggedInUserId
 			,	v_now     
 		FROM 	tt_AllCondition AC
         WHERE 	TicketAutoAssignAllConditionId = 0;
           
 		UPDATE 	tb_TicketAutoAssignAllCondition	AC
 		JOIN 	tt_AllCondition					t_AC	ON AC.TicketAutoAssignAllConditionId = t_AC.TicketAutoAssignAllConditionId
 		SET 	AC.AllFieldTypeId		= t_AC.AllFieldTypeId		
 			,	AC.AllOperatorTypeId	= t_AC.AllOperatorTypeId	
 			,	AC.AllFieldValues		= t_AC.AllFieldValues		
 			,	AC.UpdatedBy			= p_LoggedInUserId						
 			,	AC.UpdatedDate			= v_now;     
   
 		SET v_JLength = JSON_LENGTH(p_AutoAssignRuleAnyCondition, "$");
           
    		DROP TEMPORARY TABLE IF EXISTS tt_AnyCondition;
    		CREATE TEMPORARY TABLE tt_AnyCondition       
    		WITH RECURSIVE  CTE_JsonCount as
    		(	SELECT 	0 SlNo
    			UNION ALL
    			SELECT 	SlNo + 1	SlNo
    			FROM 	CTE_JsonCount
    			WHERE 	SlNo  < v_JLength - 1
    		)
    		SELECT  TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAnyCondition, CONCAT('$[',SlNo,'].TicketAutoAssignAnyConditionId')))) 	AS TicketAutoAssignAnyConditionId,
    				TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAnyCondition, CONCAT('$[',SlNo,'].AnyFieldTypeId'))))      			AS AnyFieldTypeId,
    				TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAnyCondition, CONCAT('$[',SlNo,'].AnyOperatorTypeId')))) 	   			AS AnyOperatorTypeId,
 				TRIM(BOTH '"' FROM (json_extract(p_AutoAssignRuleAnyCondition, CONCAT('$[',SlNo,'].AnyFieldValues')))) 	   				AS AnyFieldValues
    		FROM CTE_JsonCount;	
           
   		DELETE 	AC
 		FROM 	tb_TicketAutoAssignAnyCondition	AC
         LEFT JOIN tt_AnyCondition				t_AC 	ON 	AC.TicketAutoAssignAnyConditionId 	= t_AC.TicketAutoAssignAnyConditionId 
   														AND	t_AC.TicketAutoAssignAnyConditionId	<> 0
   		WHERE 	t_AC.TicketAutoAssignAnyConditionId IS NULL
         AND 	AC.TicketAutoAssignRuleId = v_TicketAutoAssignRuleId;                 
           
   		INSERT INTO tb_TicketAutoAssignAnyCondition
   		(	TicketAutoAssignRuleId			
   			,AnyFieldTypeId				
   			,AnyOperatorTypeId				
   			,AnyFieldValues				
   			,CreatedBy					
   			,CreatedDate				
   			,UpdatedBy					
   			,UpdatedDate)
   		SELECT 	v_TicketAutoAssignRuleId
 			,	AC.AnyFieldTypeId
 			,	AC.AnyOperatorTypeId
 			,	AC.AnyFieldValues
 			,	p_LoggedInUserId
 			,	v_now
 			,	p_LoggedInUserId
 			,	v_now     
 		FROM 	tt_AnyCondition AC
         WHERE 	TicketAutoAssignAnyConditionId = 0;
           
 		UPDATE 	tb_TicketAutoAssignAnyCondition	AC
 		JOIN 	tt_AnyCondition					t_AC	ON AC.TicketAutoAssignAnyConditionId = t_AC.TicketAutoAssignAnyConditionId
 		SET 	AC.AnyFieldTypeId		= t_AC.AnyFieldTypeId		
 			,	AC.AnyOperatorTypeId	= t_AC.AnyOperatorTypeId	
 			,	AC.AnyFieldValues		= t_AC.AnyFieldValues		
 			,	AC.UpdatedBy			= p_LoggedInUserId						
 			,	AC.UpdatedDate			= v_now;     		
 	END; 
     
     SELECT v_errcode 'errcode', v_errmsg 'errmsg';
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateTicketCategory` */;
