DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketCategory`(	p_TicketCategoryId		INT 
  	,p_CategoryDescription	VARCHAR(250)    
      ,p_CompanyId			INT
      ,p_ProductId			INT
      ,p_IsDefault			TINYINT 
      ,p_IsDeleted			TINYINT	
      ,p_LoggedInUserID		BIGINT
  )
BEGIN	
   	DECLARE v_errcode  			INT DEFAULT 		-1;
   	DECLARE v_errmsg   			VARCHAR(55) DEFAULT 'Failure';
  	DECLARE v_CurDate			DATETIME;
  	DECLARE v_TicketCategoryId	INT;
  
	SET v_CurDate	= NOW();	
      
	SELECT TicketCategoryId INTO v_TicketCategoryId    
	FROM 	tb_TicketCategory
	WHERE 	TicketCategoryId	= p_TicketCategoryId;	
      
 	SP_BLOCK:BEGIN     
 		 IF v_TicketCategoryId IS NULL
 		 THEN	
 			IF EXISTS(	SELECT 	1
						FROM 	tb_TicketCategory
						WHERE 	CompanyId 	= p_CompanyId
						AND		ProductId	= p_ProductId
						AND 	CategoryDescription	COLLATE utf8mb4_unicode_ci = p_CategoryDescription)
             THEN
 				SET v_errcode 	= -1;
 				SET v_errmsg 	= 'Description already exists';   
                 LEAVE SP_BLOCK;
             END IF;
             
 			INSERT INTO tb_TicketCategory
 			(	CategoryDescription	
 				,CompanyId				
 				,ProductId				
 				,IsDefault				
 				,IsDeleted				
 				,CreatedBy				
 				,CreatedDate			
 				,UpdatedBy				
 				,UpdatedDate	
 			)
 			 VALUES
 			 (	p_CategoryDescription	            
 				 ,p_CompanyId			
 				 ,p_ProductId			
 				 ,p_IsDefault				
 				 ,0			
 				 ,p_LoggedInUserID
 				 ,v_CurDate
 				 ,p_LoggedInUserID
 				 ,v_CurDate
 			 );
 	 
 			 SET v_TicketCategoryId = last_insert_id();
 			 SET v_errcode 			= 0;
 			 SET v_errmsg 			= 'Inserted Successfully';        
 		ELSE
 			IF EXISTS(	SELECT 	1
 						FROM 	tb_TicketCategory
                         WHERE 	CompanyId 	= p_CompanyId
                         AND	ProductId	= p_ProductId
                         AND 	CategoryDescription	COLLATE utf8mb4_unicode_ci = p_CategoryDescription
                         AND	TicketCategoryId 	<> v_TicketCategoryId)
             THEN
 				SET v_errcode 	= -1;
 				SET v_errmsg 	= 'Description already exists';   
                 LEAVE SP_BLOCK;
             END IF;
             
 			UPDATE	tb_TicketCategory
 			 SET 	CategoryDescription	= p_CategoryDescription
 					,IsDefault			= IFNULL(p_IsDefault,IsDefault)
 					,IsDeleted			= IFNULL(p_IsDeleted,IsDeleted)
 					,UpdatedBy			= p_LoggedInUserID
 					,UpdatedDate		= v_CurDate
 			 WHERE 	TicketCategoryId 	= v_TicketCategoryId;
 	 
 			 IF ROW_COUNT() > 0
 			 THEN
 				SET v_errcode = 0;
 				SET v_errmsg = 'Updated Successfully';			
 			 END IF;  		 
 		 END IF; 
      END;
      SELECT v_errcode errcode, v_errmsg errmsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
