/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketComment`(
  p_CompanyId 			INT
  ,p_ProductId 			INT
  ,p_TicketId				BIGINT
  ,p_TicketCommentsId		BIGINT
  ,p_Comments				LONGTEXT
  ,p_IsDeleted			TINYINT
  ,p_LoggedInUserId		BIGINT
  ,p_LoggedInUserName		VARCHAR(250)
  )
BEGIN
  	DECLARE v_errcode 				INT DEFAULT -1;
  	DECLARE v_errmsg 				VARCHAR(200) DEFAULT 'No updation on comment';    
  	DECLARE v_CurDate				DATETIME;
      DECLARE v_TicketCommentsId		BIGINT;
      DECLARE v_UserId				BIGINT;
      
      SET v_CurDate = NOW();
      
      exit_block:BEGIN
      
      If p_LoggedInUserId is null or p_LoggedInUserId = '' then
			SET v_errcode 	= -1;
  			SET v_errmsg 	= 'Input parameter p_LoggedInUserId cannot be null';
            Leave exit_block;
      End if;
      
  		SELECT 	UserId INTO v_UserId
  		FROM 	tb_TicketUser
  		WHERE 	UserId	= p_LoggedInUserId; 
  
  		IF v_UserId IS NULL
  		THEN			
  			INSERT INTO tb_TicketUser
              (	UserId
  				,UserName
  				,IsActive
  				,IsDeleted
  				,CompanyId
  				,ProductId
  				,CreatedBy
  				,CreatedDate
  				,UpdatedBy
  				,UpdatedDate
              )
              VALUES
              (	p_LoggedInUserId
  				,p_LoggedInUserName
                  ,1
                  ,0
                  ,p_CompanyId
                  ,p_ProductId
  				,p_LoggedInUserId
                  ,v_CurDate
                  ,p_LoggedInUserId
                  ,v_CurDate            
  			);
          ELSE
  			UPDATE 	tb_TicketUser
              SET 	UserName 	= p_LoggedInUserName
  				,	UpdatedBy	= p_LoggedInUserId
                  ,	UpdatedDate	= v_CurDate
  			WHERE 	UserId		= v_UserId;		
  		END IF;    
      
  		SELECT 	TicketCommentsId INTO v_TicketCommentsId
  		FROM 	tb_TicketComments
  		WHERE 	TicketCommentsId = p_TicketCommentsId;
          
          IF v_TicketCommentsId IS NULL AND IFNULL(p_Comments,'') <> ''
          THEN
  			SET v_errcode 	= -1;
  			SET v_errmsg 	= 'Comment cannot be empty';
          END IF;
  		
  		IF v_TicketCommentsId IS NULL
  		THEN
  			INSERT INTO tb_TicketComments
  			(	TicketId
  				,Comments
  				,ParentTicketCommentsId
  				,IsDeleted
  				,CreatedBy
  				,CreatedDate
  				,UpdatedBy
  				,UpdatedDate    
  			)
  			VALUES
  			(	p_TicketId
  				,p_Comments
  				,0
  				,0
  				,p_LoggedInUserId
  				,v_CurDate
  				,p_LoggedInUserId        	
  				,v_CurDate
  			);
  			
  			IF row_count() > 0
  			THEN
  				SET v_TicketCommentsId = last_insert_id();
  				SET v_errcode 	= 0;
  				SET v_errmsg 	= 'Inserted Succesfully';
  			END IF;        
  		ELSE
  			UPDATE	tb_TicketComments
  			SET 	Comments 	= p_Comments
  				,	IsDeleted	= p_IsDeleted
  				,	UpdatedBy	= p_LoggedInUserId
  				,	UpdatedDate	= v_CurDate
  			WHERE 	TicketCommentsId   = v_TicketCommentsId;
  			
  			SET v_errcode 	= 0;
  			SET v_errmsg 	= 'Inserted Succesfully';        
  		END if;   
      END;
      
      SELECT v_errcode 'errcode', v_errmsg 'errmsg';
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateTicketContact` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
