/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketContact`(
       IN p_TicketFieldContactId    		INT,
       IN p_FieldName        		        VARCHAR(100),
       IN p_FieldDescription         		VARCHAR(250),
       IN p_FieldCategoryTypeId          	INT,
       IN p_APIName          				VARCHAR(100),
       IN p_FieldTypeId         		    INT,
       IN p_IsActive                      TINYINT,
       IN p_IsRequired       				TINYINT,
       IN p_IsDefault                 	TINYINT,
       IN p_IsDeleted						INT,
  	 IN p_CompanyId						INT,
       IN p_ProductId						INT,
   	 IN P_TicketField		        	JSON,
   	 IN p_LoggedInUserID 	       	 	BIGINT       
    )
BEGIN
    	 declare v_errcode 					INT;
    	 declare v_errmsg 					varchar(55);
       declare v_CurDate					DATETIME;
       DECLARE v_JLength					INT;
       DECLARE v_TicketFieldContactId 	INT;
       
       SET v_CurDate = NOW();
	 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;  
  	 SELECT TicketFieldContactId INTO v_TicketFieldContactId
  	 FROM  	tb_TicketFieldContact
  	 WHERE 	TicketFieldContactId = p_TicketFieldContactId;
	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;         
   	 sp_exit : begin
   		 IF v_TicketFieldContactId IS NOT NULL
   		 THEN
   			 UPDATE  tb_TicketFieldContact
   			 SET	 FieldName     		  		= ifnull(p_FieldName,FieldName)
   					 ,FieldDescription       	= ifnull(p_FieldDescription,FieldDescription)
   					 ,FieldCategoryTypeId       = ifnull(p_FieldCategoryTypeId,FieldCategoryTypeId)
                       ,APIName           		= ifnull(p_APIName,APIName) 
                       ,FieldTypeId           	= ifnull(p_FieldTypeId,FieldTypeId)
                       ,IsActive		 		  	= ifnull(p_IsActive,IsActive)
                       ,IsRequired		 		= ifnull(p_IsRequired,IsRequired)
                       ,IsRequired		 		= ifnull(p_IsRequired,IsRequired)
                       ,IsDefault		 	      	= ifnull(p_IsDefault,IsDefault)
   					 ,UpdatedBy       		  	= p_LoggedInUserID
   					 ,UpdatedDate              	= v_CurDate
   			 WHERE 
   			 TicketFieldContactId = v_TicketFieldContactId;
   								
   			if row_count()>0
   			then
   				set v_errcode         = 0;
   				set v_errmsg          = 'updated successfully';
   				leave sp_exit;
   			end if;
   		 ELSE
   			 INSERT INTO tb_TicketFieldContact (
                   FieldName, 
                   FieldDescription, 
                   FieldCategoryTypeId, 
                   APIName, 
                   FieldTypeId, 
                   IsActive, 
                   IsRequired, 
                   IsDefault, 
                   IsDeleted, 
                   CompanyId, 
                   ProductId, 
                   CreatedBy, 
                   CreatedDate, 
                   UpdatedBy, 
                   UpdatedDate
   			 ) VALUES (
   				 p_FieldName,
   				 p_FieldDescription,
   				 p_FieldCategoryTypeId,
  				 p_APIName,
                   p_FieldTypeId,
                   1,
                   p_IsRequired,
                   p_IsDefault,
                   0,
                   p_CompanyId,
   				 p_ProductId,
   				 p_LoggedInUserID,
   				 v_CurDate,
   				 p_LoggedInUserID,
   				 v_CurDate
   			 );
               
               SET v_TicketFieldContactId = last_insert_id();
  
                if row_count() > 0
   			then
   			   set v_errcode = 0;
   			   set v_errmsg = 'Inserted successfully';				
   			end if;			
   		end if;
           
  		SET v_JLength = JSON_LENGTH(P_TicketFieldContact, "$");
            
  		DROP TEMPORARY TABLE IF EXISTS tt_TicketFieldContact;
    		CREATE TEMPORARY TABLE tt_TicketFieldContact       
    		WITH RECURSIVE  CTE_JsonCount as
    		(	SELECT 	0 SlNo
    			UNION ALL
    			SELECT 	SlNo + 1	SlNo
    			FROM 	CTE_JsonCount
    			WHERE 	SlNo  < v_JLength - 1
    		)
    		SELECT  TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].TicketFieldContactId')))) 	AS TicketFieldContactId,
    				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].FieldName')))) 				AS FieldName,
    				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].FieldDescription')))) 	    AS FieldDescription,
    				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].FieldCategoryTypeId')))) 	AS FieldCategoryTypeId,
    				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].APIName')))) 				AS APIName,
  				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].FieldTypeId')))) 			AS FieldTypeId,
  				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].IsActive')))) 				AS IsActive,
   				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].IsRequired')))) 			    AS IsRequired,
  				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].IsDefault')))) 				AS IsDefault,
  				TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].IsDeleted')))) 				AS IsDeleted, 
                  TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].CompanyId')))) 				AS CompanyId,
                  TRIM(BOTH '"' FROM (json_extract(P_TicketFieldContact, concat('$[',SlNo,'].ProductId')))) 				AS ProductId
    		FROM CTE_JsonCount;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            INSERT INTO tb_TicketFieldContact (
                  TicketFieldContactId,
                  FieldName,
                  FieldDescription,
                  FieldCategoryTypeId,
                  APIName,
                  FieldTypeId,
                  IsActive,
                  IsRequired,
                  IsDefault,
                  IsDeleted,
                  CompanyId,
                  ProductId,
                  CreatedBy,
                  CreatedDate,
                  UpdatedBy,
                  UpdatedDate
             )
             SELECT v_TicketFieldContactId
    			  ,	TicketFieldContactId
                ,	FieldName
                ,	FieldDescription
                ,	FieldCategoryTypeId
                , APIName
                , FieldTypeId
                , 1
                , IsRequired
                , IsDefault
                , 0
  			  ,	CompanyId
                , ProductId
    			  ,	p_LoggedInUserID
                ,	v_CurDate
                ,	p_LoggedInUserID
                ,	v_CurDate
             FROM 	tt_TicketFieldContact
             WHERE    TicketFieldContactId = 0;
            
    		UPDATE 	tb_TicketFieldContact		TS	
    		JOIN 	tt_TicketFieldContact		t_S	ON 	t_S.TicketFieldContactId 	= TS.TicketFieldContactId	
           SET 	TS.FieldName              = t_S.FieldName,
    				TS.FieldDescription       = t_S.FieldDescription,
    				TS.FieldCategoryTypeId    = t_S.FieldCategoryTypeId,
    				TS.APIName     			  = t_S.APIName,
  				TS.FieldTypeId     		  = t_S.FieldTypeId,
                  TS.IsActive     		  = t_S.IsActive,
                  TS.IsRequired     		  = t_S.IsRequired,
                  TS.IsDefault     		  = t_S.IsDefault,
  				TS.IsDeleted     		  = t_S.IsDeleted,
    				TS.UpdatedBy 			  = p_LoggedInUserID,
    				TS.UpdatedDate 			  = v_CurDate;
                    DROP TEMPORARY TABLE IF EXISTS tt_TicketFieldContact;
   	end sp_exit;        
                        
   	select v_errcode as errcode, v_errmsg as errmsg;                      
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateTicketCreation` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketCreation`(
       	p_CompanyId 						int,
       	p_ProductId 						int,
       	p_TicketSubject 					varchar(500),
       	p_TicketDescription 				text,
       	p_TicketPriority 					int,
       	p_TicketSourceId 					int,
       	p_TicketTypeId 						int,
       	p_TicketRequestorId 				int,
       	p_TicketAssignee 					tinyint,
       	
       	p_TicketAssignedToGroupId 			int,
       	p_TicketAssignedToAgentId 			int,
       	p_TicketTagId 						text,
       	p_TicketAssociateCustContact 		int,
       	p_LoggedInUserId 					bigint,
       	p_TicketLayout 						int,
       	p_TicketLayoutValue 				json,
       	p_TicketLayoutStatus				int,
       	p_TicketStatusID					int,
       	p_TicketMode						int,
      	p_RequesterName						text,
		p_CompanyName						varchar(250),
		p_ClonedFromTicketId 				INT
	)
Begin
        
        	DECLARE v_errcode 			INT;
      	DECLARE v_errmsg 			VARCHAR(200);    
      	DECLARE v_now 				DATETIME;
      	DECLARE v_JLength			INT;
         DECLARE v_TicketId			BIGINT;
         DECLARE v_TicketTagIdName 	TEXT Default NULL;   
     	DECLARE v_CompanyId 		int;
         DECLARE v_TicketLogDetailId	BIGINT; 
        
        	SET v_now 				= CURRENT_TIMESTAMP();
        	SET v_JLength 			= JSON_LENGTH(p_TicketLayoutValue, "$");
          
          spexit : Begin
            if p_TicketSubject is null 	or p_TicketSubject = ''	then 
        		set v_errcode = 0; 
                set v_errmsg = concat('Ticket Subject is mandatory'); 			
                leave spexit; 
        	end if;
            
            if p_TicketDescription is null or p_TicketDescription = '' 	then 
        		set v_errcode = 0; 
                set v_errmsg = concat('Ticket p_TicketDescription is mandatory'); 
                leave spexit; 
        	end if;
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
      	SELECT 	CompanyId INTO 	v_CompanyId
      	FROM 	tb_TicketCompany
      	WHERE 	CompanyId	= p_CompanyId;   
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
          IF v_CompanyId IS NULL
          THEN		
      		INSERT INTO tb_TicketCompany
              (	CompanyId
      			,CompanyName
      			,IsActive
      			,CreatedBy
      			,CreatedDate
      			,UpdatedBy
      			,UpdatedDate
              )
              VALUES
              (	p_CompanyId
      			,p_CompanyName
                  ,1
                  ,p_LoggedInUserId
                  ,v_now
                  ,p_LoggedInUserId
                  ,v_now        
              );
      	ELSE
      		UPDATE 	tb_TicketCompany
              SET 	CompanyName = p_CompanyName
      			,	UpdatedBy	= p_LoggedInUserId
      			,	UpdatedDate	= v_now
              WHERE 	CompanyId	= v_CompanyId;
          END IF;
        	
      	
      	if p_TicketLayoutValue <> '' or p_TicketLayoutValue is not null or p_TicketLayoutValue <> '[]' then
      		DROP TEMPORARY TABLE IF EXISTS tt_TicketLayoutFieldValue;
      		CREATE TEMPORARY TABLE tt_TicketLayoutFieldValue       
      		WITH RECURSIVE CTE_JsonCount as
      		(	SELECT 	0 SlNo
      			UNION ALL
      			SELECT 	SlNo + 1	SlNo
      			FROM 	CTE_JsonCount
      			WHERE 	SlNo  < v_JLength - 1
      		)
        		SELECT  TRIM(BOTH '"' FROM (json_extract(p_TicketLayoutValue, concat('$[',SlNo,'].TicketFieldid')))) 		AS TicketFieldid,
        				TRIM(BOTH '"' FROM (json_extract(p_TicketLayoutValue, concat('$[',SlNo,'].Ticketfieldvalue')))) 	AS Ticketfieldvalue						
        		FROM CTE_JsonCount; 
                
            End if;
            
            
            if p_TicketTagId <> '' then
        		DROP TEMPORARY TABLE IF EXISTS tt_temp_Tickettag_info;
        		create TEMPORARY table tt_temp_Tickettag_info
        		(
        			tagid LONGTEXT
        		);
        		
        		call Split(p_TicketTagId,',');
        		
        		insert into tt_temp_Tickettag_info(tagid)
        		select Items from tt_Split_temptable;
                
                 
        		select group_concat(b.TagName) into v_TicketTagIdName
        		from tt_temp_Tickettag_info a join tb_TicketTag b on a.tagid = b.TicketTagId;
        		 
            end if;
            
        	
            INSERT INTO tb_TicketDetails
            (	CompanyId,ProductId,TicketSubject,TicketSourceId,TicketTypeId,PriorityId,RequestorId,AssignedToGroupId,AssignedToAgentId
       		,TagId,ResponseDueDate,ResolutionDueDate,TicketCreatedBasedOnID,CreatedBy,CreatedDate,UpdatedBy,UpdatedDate,TicketAssignee,TicketLayout
               ,TicketDescription,TicketStatusID,TicketTagIdName,TicketMode,RequesterName,TicketAssociateCustContact
        	)
        	VALUES(p_CompanyId,p_ProductId,p_TicketSubject,p_TicketSourceId,p_TicketTypeId,p_TicketPriority,p_TicketRequestorId,p_TicketAssignedToGroupId,p_TicketAssignedToAgentId,p_TicketTagId
       			,null,null,null,p_LoggedInUserId,v_now,p_LoggedInUserId,v_now,p_TicketAssignee,p_TicketLayout,
                   p_TicketDescription,p_TicketStatusID,v_TicketTagIdName,p_TicketMode,p_RequesterName,p_TicketAssociateCustContact
            );
            
            set v_TicketId = last_insert_id();  
            
            CALL up_ccaas_GetSLAConditionForCondition(
					p_CompanyId,			p_TicketSubject,
                    p_TicketDescription,	p_TicketStatusID,
                    p_TicketPriority,		p_TicketTypeId,
                    p_TicketSourceId,  		p_RequesterName,			
					p_LoggedInUserId,		p_Layout,
					p_TicketTagId,    		p_SLAconditionId);
            
  		IF p_ClonedFromTicketId IS NOT NULL 
  		THEN
  			INSERT INTO tb_TicketComments
  			(	TicketId				
  				,Comments				        
  				,IsDeleted				
  				,CreatedBy				
  				,CreatedDate			
  				,UpdatedBy				
  				,UpdatedDate			
  			)
  			VALUES
  			(	v_TicketId
  				,CONCAT('Copied from the Ticket ', p_ClonedFromTicketId)
  				,0
  				,p_LoggedInUserId
  				,v_now
  				,p_LoggedInUserId
  				,v_now  
  			);
  		END IF;
            
            INSERT INTO tb_TicketLogDetail
     		(	TicketId					
     			,LogDetails					
     			,IsDeleted		
     			,CompanyId 
                 ,ProductId 
     			,CreatedBy					
     			,CreatedDate				
     			,UpdatedBy					
     			,UpdatedDate				
             )
             VALUES
             (	v_TicketId
     			,CONCAT('New ticket ',TicketId)
                 ,0
                 ,p_CompanyId 
                 ,p_ProductId 
     			,p_LoggedInUserId
                 ,v_now
                 ,p_LoggedInUserId
                 ,v_now
             );
             
             SET v_TicketLogDetailId = last_insert_id();
             
             INSERT INTO tb_TicketNotification
     		(	TicketId					
     			,TicketLogDetailId			
     			,NotificationUserId			
     			,NotificationUserTypeId		
     			,IsRead					
                 ,CompanyId 
                 ,ProductId 
     			,CreatedBy					
     			,CreatedDate				
     			,UpdatedBy					
     			,UpdatedDate				
             )
             SELECT 	v_TicketId
     			,	v_TicketLogDetailId
     			,	p_TicketRequestorId
                 ,	1117001			
                 ,	0
                 ,	p_CompanyId 
                 ,	p_ProductId 
                 ,	p_LoggedInUserId
                 ,	v_now
                 ,	p_LoggedInUserId
                 ,	v_now 
     		UNION ALL		
     		SELECT 	v_TicketId
     			,	v_TicketLogDetailId
     			,	p_TicketAssignedToAgentId
                 ,	1117002			
                 ,	0
                 ,	p_CompanyId 
                 ,	p_ProductId 
                 ,	p_LoggedInUserId
                 ,	v_now
                 ,	p_LoggedInUserId
                 ,	v_now 
     		UNION ALL		
     		SELECT	v_TicketId
     			,	v_TicketLogDetailId
     			,	p_TicketAssociateCustContact
                 ,	1117003			
                 ,	0
                 ,	p_CompanyId 
                 ,	p_ProductId 
                 ,	p_LoggedInUserId
                 ,	v_now
                 ,	p_LoggedInUserId
                 ,	v_now ;
        
            if row_count() > 0  then 
        		set v_errcode = 0;
                set v_errmsg = concat('Ticket no - ',v_TicketId,' Created');
            End if;
            
            
            if (v_TicketTagIdName is not null and v_TicketTagIdName <> '') or (p_TicketTagId<>'') then
        		insert into tb_TicketTagMapping(TicketId,TicketTagId,CreatedDate)
        		select v_TicketId, a.tagid, v_now from tt_temp_Tickettag_info a;
   			DROP TEMPORARY TABLE IF EXISTS tt_temp_Tickettag_info;
            End if;
            
            
            if v_TicketId is not null or v_TicketId<> 0 then 
        		if p_TicketLayoutValue <> '' or p_TicketLayoutValue is not null or p_TicketLayoutValue <> '[]' then
        			INSERT INTO tb_TicketLayoutFieldValueDtl (fkTicketid,fkTicketFieldid,Ticketfieldvalue)
        			select 	v_TicketId,a.TicketFieldid,a.Ticketfieldvalue
        			FROM tt_TicketLayoutFieldValue a;
                    DROP TEMPORARY TABLE IF EXISTS tt_TicketLayoutFieldValue;
                end if;
            End if;
            
     	end spexit;
        
     	select v_errcode as errcode, v_errmsg as errmsg, ifnull(v_TicketId,0) as TicketId;
        
     End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateTicketFile` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketFile`(
     p_CompanyId 			INT
     ,p_ProductId 			INT
     ,p_TicketId			BIGINT
     ,p_TicketFiles			JSON
     ,p_LoggedInUserId		BIGINT
     ,p_LoggedInUserName	VARCHAR(250)
  )
BEGIN
	DECLARE v_errcode 		INT DEFAULT -1;
    DECLARE v_errmsg 		VARCHAR(200) DEFAULT 'No updation on File';    
    DECLARE v_CurDate		DATETIME;
  	DECLARE v_TicketFilesId	BIGINT;
    DECLARE v_UserId		BIGINT;
    DECLARE v_JLength		INT; 
         
  	SET v_CurDate = NOW();
  
  	exit_block:BEGIN
  
  		If p_LoggedInUserId is null or p_LoggedInUserId = '' then
  			SET v_errcode 	= -1;
  			SET v_errmsg 	= 'Input parameter p_LoggedInUserId cannot be null';
  			Leave exit_block;
  		End if;
  
  		SELECT 	UserId INTO v_UserId
  		FROM 	tb_TicketUser
  		WHERE 	UserId	= p_LoggedInUserId; 
     
		IF v_UserId IS NULL
		THEN			
			INSERT INTO tb_TicketUser
			 (	UserId
				,UserName
				,IsActive
				,IsDeleted
				,CompanyId
				,ProductId
				,CreatedBy
				,CreatedDate
				,UpdatedBy
				,UpdatedDate
			 )
			 VALUES
			 (	p_LoggedInUserId
				,p_LoggedInUserName
				 ,1
				 ,0
				 ,p_CompanyId
				 ,p_ProductId
			   ,p_LoggedInUserId
				 ,v_CurDate
				 ,p_LoggedInUserId
				 ,v_CurDate            
			);
		 ELSE
			UPDATE 	tb_TicketUser
			 SET 	UserName 	= p_LoggedInUserName
				,	UpdatedBy	= p_LoggedInUserId
			,	UpdatedDate	= v_CurDate
			WHERE 	UserId		= v_UserId;		
		END IF;    
         
         SET v_JLength = JSON_LENGTH(p_TicketFiles, "$");
  		   
  		DROP TEMPORARY TABLE IF EXISTS tt_TicketFiles;
  		CREATE TEMPORARY TABLE tt_TicketFiles       
  		WITH RECURSIVE  CTE_JsonCount as
  		(	SELECT 	0 SlNo
  			UNION ALL
  			SELECT 	SlNo + 1	SlNo
  			FROM 	CTE_JsonCount
  			WHERE 	SlNo  < v_JLength - 1
  		)
  		SELECT  TRIM(BOTH '"' FROM (json_extract(p_TicketFiles, concat('$[',SlNo,'].TicketFilesId')))) AS TicketFilesId,
  				TRIM(BOTH '"' FROM (json_extract(p_TicketFiles, concat('$[',SlNo,'].FilePath'))))      AS FilePath,
  				TRIM(BOTH '"' FROM (json_extract(p_TicketFiles, concat('$[',SlNo,'].FileName')))) 	   AS FileName,
                 TRIM(BOTH '"' FROM (json_extract(p_TicketFiles, concat('$[',SlNo,'].FileSize')))) 	   AS FileSize
  		FROM CTE_JsonCount;	
          
          INSERT INTO tb_TicketFiles
     			(	TicketId
     				,FilePath   	
 					,FileName
                     ,FileSize
     				,IsDeleted
     				,CreatedBy
     				,CreatedDate
     				,UpdatedBy
     				,UpdatedDate    
     			)
     			select
 					p_TicketId
 					,FilePath
 					,FileName
                     ,FileSize
     				,0   				
     				,p_LoggedInUserId
     				,v_CurDate
     				,p_LoggedInUserId        	
     				,v_CurDate
 				from tt_TicketFiles;
  
     			IF row_count() > 0
     			THEN
     				SET v_TicketFilesId = last_insert_id();
     				SET v_errcode 	= 0;
     				SET v_errmsg 	= 'Inserted Succesfully';
     			END IF;
              
         
     		
	END;
         
	SELECT v_errcode 'errcode', v_errmsg 'errmsg';
 END ;;
DELIMITER ;
