CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketLayout`(
   IN p_TicketLayoutId    		INT,
   IN p_LayoutName        		VARCHAR(100),
   IN p_LayoutDescription        VARCHAR(250),
   IN p_TicketCategoryId         INT,
   IN p_CompanyId          		INT,
   IN p_ProductId         		INT,
   IN p_LayoutTypeId             INT,
   IN p_IsActive       			TINYINT,
   IN p_IsDeleted                TINYINT,
   IN p_LoggedInUserID 	        BIGINT    ,
   IN p_TicketLayoutStatus		INT
      )
BEGIN
   	declare v_errcode 			INT;
   	declare v_errmsg 			varchar(55);
   	declare v_CurDate			DATETIME;
   	DECLARE v_JLength			INT;
   	DECLARE v_TicketLayoutId 	INT;
       DECLARE v_TicketFieldId		int;
         
   	SET v_CurDate = NOW();
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;      
   	SELECT 	TicketLayoutId INTO v_TicketLayoutId
   	FROM  	tb_TicketLayout
   	WHERE 	TicketLayoutId = p_TicketLayoutId;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
   	sp_exit : begin
     		 IF v_TicketLayoutId IS NOT NULL
     		 THEN
     			 UPDATE  tb_TicketLayout
     			 SET	 LayoutName     		  	= ifnull(p_LayoutName,LayoutName)
     					,LayoutDescription       	= ifnull(p_LayoutDescription,LayoutDescription)
     					,TicketCategoryId           = ifnull(p_TicketCategoryId,TicketCategoryId)
                         ,LayoutTypeId           	= ifnull(p_LayoutTypeId,LayoutTypeId)  
                         ,IsActive		 		  	= ifnull(p_IsActive,IsActive)
                         ,IsDeleted		 	    = ifnull(p_IsDeleted,IsDeleted)
     					,UpdatedBy       		  	= p_LoggedInUserID
     					,UpdatedDate              	= v_CurDate
                         ,TicketLayoutStatus			 = ifnull(p_TicketLayoutStatus,TicketLayoutStatus)
     			 WHERE TicketLayoutId 				= v_TicketLayoutId;
     								
     			if row_count()>0
     			then
     				set v_errcode         = 0;
     				set v_errmsg          = 'updated successfully';
     				leave sp_exit;
     			end if;
     		 ELSE
     			 INSERT INTO tb_TicketLayout (
     				 TicketLayoutId,
                      LayoutName,
                      LayoutDescription,
                      TicketCategoryId,
                      CompanyId,
                      ProductId,
                      LayoutTypeId,
                      IsActive,
                      IsDeleted,
                      CreatedBy,
                      CreatedDate,
                      UpdatedBy,
                      UpdatedDate,
                      TicketLayoutStatus
     			 ) VALUES (
     				 p_TicketLayoutId,
     				 p_LayoutName,
     				 p_LayoutDescription,
   				 p_TicketCategoryId,
                    p_CompanyId,
     				 p_ProductId,
     				 p_LayoutTypeId,
                    1,
                    0,
     				 p_LoggedInUserID,
     				 v_CurDate,
     				 p_LoggedInUserID,
     				 v_CurDate,
                      p_TicketLayoutStatus
     			 );
                 
                 SET v_TicketLayoutId = last_insert_id();
				  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
                  INSERT INTO tb_TicketField (
   				   FieldName, 				
   				   FieldDescription,
   				   TicketLayoutId,
   				   FieldCategoryTypeId, 
   				   APIName, 
   				   FieldTypeId, 
   				   IsActive, 
   				   IsRequired, 
   				   IsDefault,
                     IsDeleted,
   				   CompanyId,
   				   ProductId,
   				   CreatedBy, 
   				   CreatedDate, 
   				   UpdatedBy, 
   				   UpdatedDate
                  ) 
                  select
   				   FieldName,
   				   FieldDescription,
   				   v_TicketLayoutId,
   				   FieldCategoryTypeId,
   				   APIName,
   				   FieldTypeId,
   				   IsActive,
   				   IsRequired,
   				   IsDefault,
                     0,
   				   CompanyId,
   				   ProductId,
   				   p_LoggedInUserID,
   				   v_CurDate,
   				   p_LoggedInUserID,
   				   v_CurDate
     			 FROM 	tb_TicketFieldTemplate
               WHERE 	FieldCategoryTypeId = 1109001; 
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   
  			SET V_TicketFieldId = last_insert_id();
                  
                  if row_count() > 0
     			then
     			   set v_errcode = 0;
     			   set v_errmsg = 'Inserted successfully';				
     			end if;			
     		end if;
     	end sp_exit;        
                          
     	select v_TicketLayoutId as TicketLayoutId,v_errcode as errcode, v_errmsg as errmsg;                      
    end ;;
DELIMITER ;
