CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateTicketLink`(
      p_CompanyId 				INT
      ,p_ProductId 			INT
      ,p_TicketId				BIGINT
      ,p_TicketLinksId			BIGINT
      ,p_Links					LONGTEXT
      ,p_LinkName				VARCHAR(250)
      ,p_IsDeleted				TINYINT
      ,p_LoggedInUserId		BIGINT
      ,p_LoggedInUserName		VARCHAR(250)
   )
BEGIN
      	DECLARE v_errcode 		INT DEFAULT -1;
      	DECLARE v_errmsg 		VARCHAR(200) DEFAULT 'No updation on Link';    
      	DECLARE v_CurDate		DATETIME;
   	DECLARE v_TicketLinksId	BIGINT;
       DECLARE v_UserId		BIGINT;
          
   	SET v_CurDate = NOW();
   
   	exit_block:BEGIN
   
   		If p_LoggedInUserId is null or p_LoggedInUserId = '' then
   			SET v_errcode 	= -1;
   			SET v_errmsg 	= 'Input parameter p_LoggedInUserId cannot be null';
   			Leave exit_block;
   		End if;
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		SELECT 	UserId INTO v_UserId
   		FROM 	tb_TicketUser
   		WHERE 	UserId	= p_LoggedInUserId; 
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      		IF v_UserId IS NULL
      		THEN			
      			INSERT INTO tb_TicketUser
                  (	UserId
      				,UserName
      				,IsActive
      				,IsDeleted
      				,CompanyId
      				,ProductId
      				,CreatedBy
      				,CreatedDate
      				,UpdatedBy
      				,UpdatedDate
                  )
                  VALUES
                  (	p_LoggedInUserId
   					,p_LoggedInUserName
                      ,1
                      ,0
                      ,p_CompanyId
                      ,p_ProductId
   				   ,p_LoggedInUserId
                      ,v_CurDate
                      ,p_LoggedInUserId
                      ,v_CurDate            
      			);
              ELSE
      			UPDATE 	tb_TicketUser
                  SET 	UserName 	= p_LoggedInUserName
      				,	UpdatedBy	= p_LoggedInUserId
   				,	UpdatedDate	= v_CurDate
      			WHERE 	UserId		= v_UserId;		
      		END IF;    
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      		SELECT 	TicketLinksId INTO v_TicketLinksId
      		FROM 	tb_TicketLinks
      		WHERE 	TicketLinksId = p_TicketLinksId;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;   
   		IF v_TicketLinksId IS NULL AND IFNULL(p_Links,'') <> ''
   		THEN
   		SET v_errcode 	= -1;
   		SET v_errmsg 	= 'Link cannot be empty';
   		END IF;
      		
      		IF v_TicketLinksId IS NULL
      		THEN        
      			INSERT INTO tb_TicketLinks
      			(	TicketId
      				,Link   	
                   ,LinkName
      				,IsDeleted
      				,CreatedBy
      				,CreatedDate
      				,UpdatedBy
      				,UpdatedDate    
      			)
      			VALUES
      			(	p_TicketId
      				,p_Links
                   ,p_LinkName
      				,0   				
      				,p_LoggedInUserId
      				,v_CurDate
      				,p_LoggedInUserId        	
      				,v_CurDate
      			);
      			
      			IF row_count() > 0
      			THEN
      				SET v_TicketLinksId = last_insert_id();
      				SET v_errcode 	= 0;
      				SET v_errmsg 	= 'Inserted Succesfully';
      			END IF;        
      		ELSE
      			UPDATE	tb_TicketLinks
      			SET 	Link 	= p_Links
      				,	IsDeleted	= p_IsDeleted
      				,	UpdatedBy	= p_LoggedInUserId
      				,	UpdatedDate	= v_CurDate
      			WHERE 	TicketLinksId   = v_TicketLinksId;
      			
      			SET v_errcode 	= 0;
      			SET v_errmsg 	= 'Inserted Succesfully';        
      		END if;   
          END;
          
          SELECT v_errcode 'errcode', v_errmsg 'errmsg';
      END ;;
DELIMITER ;
