CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateTicketSnippet`(	
  	p_TicketSnippetId		INT 
   	,p_SnippetTitle			VARCHAR(250)
       ,p_SnippetDescription	TEXT
       ,p_TicketCategoryId		INT
       ,p_CompanyId			INT
       ,p_ProductId			INT
       ,p_IsActive				TINYINT 
       ,p_IsDeleted			TINYINT	
       ,p_LoggedInUserID		BIGINT
   )
BEGIN	
    	DECLARE v_errcode  			INT DEFAULT 		-1;
    	DECLARE v_errmsg   			VARCHAR(55) DEFAULT 'Failure';
   	DECLARE v_CurDate			DATETIME;
   	DECLARE v_TicketSnippetId	INT;
     	
       SET v_CurDate	= NOW();	
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       SELECT 	TicketSnippetId INTO v_TicketSnippetId    
       FROM 	tb_TicketSnippet
       WHERE 	TicketSnippetId	= p_TicketSnippetId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
   	IF v_TicketSnippetId IS NULL
       THEN
   		INSERT INTO tb_TicketSnippet
   		(	SnippetTitle			
   			,SnippetDescription		
   			,TicketCategoryId		
   			,CompanyId				
   			,ProductId				
   			,IsActive				
   			,IsDeleted				
   			,CreatedBy				
   			,CreatedDate			
   			,UpdatedBy				
   			,UpdatedDate			
   		)
           VALUES
           (	p_SnippetTitle			
               ,p_SnippetDescription	
               ,p_TicketCategoryId		
               ,p_CompanyId			
               ,p_ProductId			
               ,1				
               ,0
   			,p_LoggedInUserID
               ,v_CurDate
               ,p_LoggedInUserID
               ,v_CurDate  	
           );
           
           SET v_TicketSnippetId = last_insert_id();
           SET v_errcode = 0;
           SET v_errmsg = 'Inserted Successfully';
       ELSE
   		UPDATE	tb_TicketSnippet
           SET	SnippetTitle		= IFNULL(p_SnippetTitle,SnippetTitle)
   				 ,SnippetDescription= IFNULL(p_SnippetDescription,SnippetDescription)
                   ,TicketCategoryId	= IFNULL(p_TicketCategoryId,TicketCategoryId)
                   ,IsActive			= IFNULL(p_IsActive,IsActive)
   				,IsDeleted			= IFNULL(p_IsDeleted,IsDeleted)							
   				,UpdatedBy			= p_LoggedInUserID	
   				,UpdatedDate		= v_CurDate
           WHERE 	TicketSnippetId = v_TicketSnippetId;
           
           IF ROW_COUNT() > 0
           THEN
   			SET v_errcode = 0;
   			SET v_errmsg = 'Updated Successfully';			
           END IF;
       END IF; 
       
       SELECT v_errcode errcode, v_errmsg	errmsg;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
