CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateTicketStatus`(
  p_StatusId 			INT,
  p_StatusName 		VARCHAR(20),
  p_SLATimer 			INT,
  p_StatusColor 		VARCHAR(10),
  p_IsActive 			TINYINT,
  p_IsDeleted 		TINYINT,
  p_CompanyId			int,
  p_ProductId			int,
  p_LoggedInUserID 	BIGINT
  )
BEGIN
        DECLARE v_errcode 	INT 		DEFAULT -1;
        DECLARE v_errmsg 		VARCHAR(55) DEFAULT 'Failure';
        DECLARE v_CurDate 	DATETIME;
        DECLARE v_StatusId 	INT;	
        DECLARE v_OrderNo 	INT;	
        
        SET v_CurDate = NOW();
        
  	  sp_exit : begin
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 	StatusId INTO v_StatusId
  		FROM 	tb_TicketStatus
  		WHERE 	StatusId = p_StatusId limit 1;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  	IF v_StatusId IS NOT NULL 
  	THEN
  		UPDATE tb_TicketStatus
  		SET   StatusName        = p_StatusName,
  			  SLATimer          = p_SLATimer,
  			  StatusColor       = p_StatusColor,
  			  IsActive          = p_IsActive,
  			  IsDeleted 		= p_IsDeleted,
                OrderNo			= v_OrderNo,
  			  UpdatedBy 		= p_LoggedInUserID,
  			  UpdatedDate 	  	= v_CurDate
  		WHERE StatusId 			= p_StatusId;
            
  		IF ROW_COUNT() > 0 THEN
  		  SET v_errcode = 0;
  		  SET v_errmsg = 'Record updated successfully';			
  		END IF;
        ELSE
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT 	MAX(OrderNo) INTO v_OrderNo
  		FROM 	tb_TicketStatus
  		WHERE 	CompanyId 	= p_CompanyId	
          AND	 	ProductId	= p_ProductId;
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
          SET v_OrderNo = IFNULL(v_OrderNo,0) + 1;
          
            INSERT INTO tb_TicketStatus (              
                StatusName,		
                IsDefault,
                SLATimer,
                StatusColor,
                IsActive,
                IsDeleted,
                OrderNo,
                CompanyId,
                ProductId,
                CreatedBy,
                CreatedDate,
                UpdatedBy,
                UpdatedDate
            )
            VALUES (              
                p_StatusName,				
                0,
                p_SLATimer,
                p_StatusColor,
                1,
                0,
                v_OrderNo,
                p_CompanyId,
                p_ProductId,
                p_LoggedInUserID,
                v_CurDate,
                p_LoggedInUserID,
                v_CurDate
            );
            
            IF ROW_COUNT() > 0 THEN
                SET v_errcode = 0;
                SET v_errmsg = 'Record inserted successfully';
            END IF;
        END IF;
   	end sp_exit;
        
  	SELECT v_errcode AS errcode, v_errmsg AS errmsg;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
