CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateTicketStatusCategory`(
      IN p_StatusCategoryId INT,
      IN p_CompanyId INT,
      IN p_ProductId INT,
      IN p_StatusCategoryName VARCHAR(50),
      IN p_StatusCategoryDescription VARCHAR(1000),
      IN p_IsActive TINYINT,
      IN p_IsDeleted TINYINT,
      IN p_Status JSON,
      IN p_LoggedInUserID BIGINT
  )
BEGIN
      DECLARE v_errcode INT DEFAULT -1;
      DECLARE v_errmsg VARCHAR(55) DEFAULT 'failure';
      DECLARE v_CurDate DATETIME;
      DECLARE v_StatusCategoryId INT;
      DECLARE v_JLength INT;
  
      SET v_CurDate = NOW();
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT StatusCategoryId INTO v_StatusCategoryId
      FROM tb_TicketStatusCategory
      WHERE StatusCategoryId = p_StatusCategoryId;
 	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      sp_exit: BEGIN
          IF v_StatusCategoryId IS NOT NULL THEN
              UPDATE tb_TicketStatusCategory
              SET CompanyId = p_CompanyId,
                  ProductId = p_ProductId,
                  StatusCategoryName = p_StatusCategoryName,
                  StatusCategoryDescription = p_StatusCategoryDescription,
                  IsActive = 1,
                  IsDeleted = 0,
                  UpdatedBy = p_LoggedInUserID,
                  UpdatedDate = v_CurDate
              WHERE StatusCategoryId = v_StatusCategoryId;
  
              IF ROW_COUNT() > 0 THEN
                  SET v_errcode = 0;
                  SET v_errmsg = 'Updated successfully';
              END IF;
          ELSE
              INSERT INTO tb_TicketStatusCategory (
                  CompanyId,
                  ProductId,
                  StatusCategoryName,
                  StatusCategoryDescription,
                  IsActive,
                  IsDeleted,
                  CreatedBy,
                  CreatedDate,
                  UpdatedBy,
                  UpdatedDate
              )
              VALUES (
                  p_CompanyId,
                  p_ProductId,
                  p_StatusCategoryName,
                  p_StatusCategoryDescription,
                  1,
                  0,
                  0,
                  v_CurDate,
                  0,
                  v_CurDate
              );
  
              SET v_StatusCategoryId = LAST_INSERT_ID();
  
              IF ROW_COUNT() > 0 THEN
                  SET v_errcode = 0;
                  SET v_errmsg = 'Added successfully';
              END IF;
          END IF;
  
          SET v_JLength = JSON_LENGTH(p_Status, "$");
  
          DROP TEMPORARY TABLE IF EXISTS tt_Status;
   		CREATE TEMPORARY TABLE tt_Status       
   		WITH RECURSIVE  CTE_JsonCount as
   		(	SELECT 	0 SlNo
   			UNION ALL
   			SELECT 	SlNo + 1	SlNo
   			FROM 	CTE_JsonCount
   			WHERE 	SlNo  < v_JLength - 1
   		)
          SELECT
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].StatusId')))) AS StatusId,
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].StatusName')))) AS StatusName,
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].IsDefault')))) AS IsDefault,
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].SLATimer')))) AS SLATimer,
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].StatusColor')))) AS StatusColor,
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].IsActive')))) AS IsActive,
              TRIM(BOTH '"' FROM (JSON_EXTRACT(p_Status, CONCAT('$[', SlNo, '].IsDeleted')))) AS IsDeleted
          FROM CTE_JsonCount
          WHERE SlNo < v_JLength - 1;
  
          INSERT INTO tb_TicketStatus (
              StatusCategoryId,
              StatusName,
              IsDefault,
              SLATimer,
              StatusColor,
              IsActive,
              IsDeleted,
              CreatedBy,
              CreatedDate,
              UpdatedBy,
              UpdatedDate
          )
          SELECT
              v_StatusCategoryId,
              t_S.StatusName,
              t_S.IsDefault,
              t_S.SLATimer,
              t_S.StatusColor,
              t_S.IsActive,
              t_S.IsDeleted,
              p_LoggedInUserID,
              v_CurDate,
              p_LoggedInUserID,
              v_CurDate
          FROM tt_Status t_S
          WHERE StatusId = 0
              AND IsDeleted = 0;
  
          UPDATE tb_TicketStatus TS
          JOIN tt_Status t_S ON t_S.StatusId = TS.StatusId
          SET TS.StatusName = t_S.StatusName,
              TS.SLATimer = t_S.SLATimer,
              TS.StatusColor = t_S.StatusColor,
              TS.IsActive = t_S.IsActive,
              TS.IsDeleted = t_S.IsDeleted,
              TS.UpdatedBy = p_LoggedInUserID,
              TS.UpdatedDate = v_CurDate;
      END sp_exit;
      SELECT v_errcode AS errcode, v_errmsg AS errmsg;
       DROP TEMPORARY TABLE IF EXISTS tt_Status;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
