   	SET v_CurDate = NOW();
        
    	sp_exit : begin
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    		 IF EXISTS (SELECT 1
   					FROM tb_TicketTag
   					WHERE TicketTagId = p_TicketTagId) 
                     
   		THEN
   			UPDATE tb_TicketTag
   			 SET CompanyId   	= p_CompanyId,
   				 ProductId   	= p_ProductId,
   				 TagName   	 	= p_TagName,
                    TagDescription = p_TagDescription,
   				 IsActive    	= p_IsActive,
   				 IsDeleted   	= p_IsDeleted,
   				 UpdatedBy   	= p_LoggedInUserID,
   				 UpdatedDate 	= v_CurDate
   			 WHERE TicketTagId 	= p_TicketTagId;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 			if row_count()>0
   			then
   					set v_errcode = 0;
   					set v_errmsg = 'updated successfully';
   					leave sp_exit;
   			end if;         
            ELSE     
   			INSERT INTO tb_TicketTag 
   			(CompanyId, 
   			ProductId, 
   			TagName,   	 	
   			TagDescription,
   			IsActive, 
   			IsDeleted, 
   			CreatedBy, 
   			CreatedDate, 
   			UpdatedBy, 
   			UpdatedDate)
   			VALUES 
   			(p_CompanyId, 
   			p_ProductId, 
   			p_TagName,
   			p_TagDescription,
   			p_IsActive, 
   			0, 
   			p_LoggedInUserID, 
   			v_CurDate, 
   			p_LoggedInUserID, 
   			v_CurDate);
                  
   			if row_count() > 0
   			then
   				set v_errcode = 0;
   				set v_errmsg = 'Inserted successfully';				
   			end if;			
   		end if;
    	end sp_exit;        
                         
    	select v_errcode as errcode, v_errmsg as errmsg;
    end ;;
DELIMITER ;
