CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateTicketTrigger`(
    	p_CompanyId 				INT
    	,p_ProductId 				INT
    	,p_TicketTriggerId			BIGINT    
    	,p_RuleName					VARCHAR(250)
    	,p_RuleDescription			TEXT
    	,p_TriggerAllCondition		JSON
    	,P_TriggerAnyCondition		JSON
    	,p_TriggerAction			JSON
    	,p_LoggedInUserId 			BIGINT
    )
BEGIN   
    	DECLARE v_errcode 			INT DEFAULT -1;
      	DECLARE v_errmsg 			VARCHAR(200) DEFAULT 'No Trigger';    
      	DECLARE v_now 				DATETIME;
      	DECLARE v_JLength			INT;    
     	DECLARE v_TicketTriggerId	BIGINT;
        
        	SET v_now	= CURRENT_TIMESTAMP();
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         SELECT 	TicketTriggerId INTO v_TicketTriggerId    
         FROM 	tb_TicketTrigger
         WHERE 	TicketTriggerId = p_TicketTriggerId;       
 		
 	
     spexit : BEGIN
     		IF v_TicketTriggerId IS NULL
             THEN			
     			INSERT INTO tb_TicketTrigger
                 (	RuleName			
     				,RuleDescription	
                    ,IsActive
                    ,IsDeleted
     				,CompanyId			
     				,ProductId	                
     				,CreatedBy			
     				,CreatedDate		
     				,UpdatedBy			
     				,UpdatedDate		
                 )
                 VALUES
                 (	p_RuleName			
                     ,p_RuleDescription	
                     ,1
                     ,0
                     ,p_CompanyId 	
                     ,p_ProductId 	
                     ,p_LoggedInUserId
                     ,v_now
                     ,p_LoggedInUserId
                     ,v_now                
                 );
                 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                 SET v_TicketTriggerId = last_insert_id();
                 SET v_errcode	= 0;
                 SET v_errmsg 	= 'Inserted Sucessfully';
     		ELSE    
     			UPDATE 	tb_TicketTrigger
                 SET 	RuleName			= p_RuleName
                      ,RuleDescription	= p_RuleDescription
  					,UpdatedBy			= p_LoggedInUserId
     					,UpdatedDate		= v_now
  			WHERE 	TicketTriggerId 	= p_TicketTriggerId;
                         
                 SET v_errcode	= 0;
                 SET v_errmsg 	= 'Updated Sucessfully';                    
             END IF;
             
     		SET v_JLength = JSON_LENGTH(p_TriggerAllCondition, "$");
             
      		DROP TEMPORARY TABLE IF EXISTS tt_AllCondition;
      		CREATE TEMPORARY TABLE tt_AllCondition       
      		WITH RECURSIVE  CTE_JsonCount as
      		(	SELECT 	0 SlNo
      			UNION ALL
      			SELECT 	SlNo + 1	SlNo
      			FROM 	CTE_JsonCount
      			WHERE 	SlNo  < v_JLength - 1
      		)
      		SELECT  TRIM(BOTH '"' FROM (json_extract(p_TriggerAllCondition, CONCAT('$[',SlNo,'].TicketTriggerAllConditionId')))) 	AS TicketTriggerAllConditionId,
      				TRIM(BOTH '"' FROM (json_extract(p_TriggerAllCondition, CONCAT('$[',SlNo,'].FieldTypeId'))))      				AS FieldTypeId,
      				TRIM(BOTH '"' FROM (json_extract(p_TriggerAllCondition, CONCAT('$[',SlNo,'].OperatorTypeId')))) 	   			AS OperatorTypeId,
                     TRIM(BOTH '"' FROM (json_extract(p_TriggerAllCondition, CONCAT('$[',SlNo,'].FieldValues')))) 	   				AS FieldValues
      		FROM CTE_JsonCount;	
             
     		DELETE 	AC
   		FROM 	tb_TicketTriggerAllCondition	AC
           LEFT JOIN tt_AllCondition				t_AC 	ON 	AC.TicketTriggerAllConditionId 	= t_AC.TicketTriggerAllConditionId 
     														AND	t_AC.TicketTriggerAllConditionId <> 0
     		WHERE 	t_AC.TicketTriggerAllConditionId IS NULL
           AND 	AC.TicketTriggerId = v_TicketTriggerId;        
             
     		INSERT INTO tb_TicketTriggerAllCondition
     		(	TicketTriggerId			
     			,FieldTypeId				
     			,OperatorTypeId				
     			,FieldValues				
     			,CreatedBy					
     			,CreatedDate				
     			,UpdatedBy					
     			,UpdatedDate)
     		SELECT 	v_TicketTriggerId
     			,	AC.FieldTypeId
                 ,	AC.OperatorTypeId
                 ,	AC.FieldValues
     			,	p_LoggedInUserId
     			,	v_now
     			,	p_LoggedInUserId
     			,	v_now     
             FROM 	tt_AllCondition AC
             WHERE 	TicketTriggerAllConditionId = 0;
             
             UPDATE 	tb_TicketTriggerAllCondition	AC
             JOIN 	tt_AllCondition					t_AC	ON AC.TicketTriggerAllConditionId = t_AC.TicketTriggerAllConditionId
             SET 	AC.FieldTypeId		= t_AC.FieldTypeId		
                 ,	AC.OperatorTypeId	= t_AC.OperatorTypeId	
                 ,	AC.FieldValues		= t_AC.FieldValues		
                 ,	AC.UpdatedBy		= p_LoggedInUserId						
     			,	AC.UpdatedDate		= v_now;
 			DROP TEMPORARY TABLE IF EXISTS tt_AllCondition;   
             SET v_JLength = 0;
     		SET v_JLength = JSON_LENGTH(P_TriggerAnyCondition, "$");   
     
      		DROP TEMPORARY TABLE IF EXISTS tt_AnyCondition;
      		CREATE TEMPORARY TABLE tt_AnyCondition       
      		WITH RECURSIVE  CTE_JsonCount as
      		(	SELECT 	0 SlNo
      			UNION ALL
      			SELECT 	SlNo + 1	SlNo
      			FROM 	CTE_JsonCount
      			WHERE 	SlNo  < v_JLength - 1
      		)
      		SELECT  TRIM(BOTH '"' FROM (json_extract(P_TriggerAnyCondition, CONCAT('$[',SlNo,'].TicketTriggerAnyConditionId')))) 		AS TicketTriggerAnyConditionId,
      				TRIM(BOTH '"' FROM (json_extract(P_TriggerAnyCondition, CONCAT('$[',SlNo,'].AnyFieldTypeId'))))      				AS AnyFieldTypeId,
      				TRIM(BOTH '"' FROM (json_extract(P_TriggerAnyCondition, CONCAT('$[',SlNo,'].AnyOperatorTypeId')))) 	   				AS AnyOperatorTypeId,
                     TRIM(BOTH '"' FROM (json_extract(P_TriggerAnyCondition, CONCAT('$[',SlNo,'].AnyFieldValues')))) 	   				AS AnyFieldValues
      		FROM CTE_JsonCount;	
             
     		DELETE 	AC
             FROM 	tb_TicketTriggerAnyCondition	AC
             LEFT JOIN tt_AnyCondition				t_AC 	ON 	AC.TicketTriggerAnyConditionId 		= t_AC.TicketTriggerAnyConditionId
     														AND	t_AC.TicketTriggerAnyConditionId 	<> 0
     		WHERE 	t_AC.TicketTriggerAnyConditionId IS NULL
           AND 	AC.TicketTriggerId = v_TicketTriggerId;   
             
             UPDATE 	tb_TicketTriggerAnyCondition	AC
             JOIN 	tt_AnyCondition					t_AC	ON AC.TicketTriggerAnyConditionId = t_AC.TicketTriggerAnyConditionId
             SET 	AC.AnyFieldTypeId		= t_AC.AnyFieldTypeId		
                 ,	AC.AnyOperatorTypeId	= t_AC.AnyOperatorTypeId	
                 ,	AC.AnyFieldValues		= t_AC.AnyFieldValues		
                 ,	AC.UpdatedBy			= p_LoggedInUserId						
     			,	AC.UpdatedDate			= v_now;             
             
     		INSERT INTO tb_TicketTriggerAnyCondition
     		(	TicketTriggerId			
     			,AnyFieldTypeId				
     			,AnyOperatorTypeId				
     			,AnyFieldValues				
     			,CreatedBy					
     			,CreatedDate				
     			,UpdatedBy					
     			,UpdatedDate)
     		SELECT 	v_TicketTriggerId
     			,	AC.AnyFieldTypeId
                 ,	AC.AnyOperatorTypeId
                 ,	AC.AnyFieldValues
     			,	p_LoggedInUserId
     			,	v_now
     			,	p_LoggedInUserId
     			,	v_now     
             FROM 	tt_AnyCondition AC
             WHERE 	TicketTriggerAnyConditionId = 0;
 			DROP TEMPORARY TABLE IF EXISTS tt_AnyCondition;
             SET v_JLength = 0;
     		SET v_JLength = JSON_LENGTH(p_TriggerAction, "$");   
     
      		DROP TEMPORARY TABLE IF EXISTS tt_Action;
      		CREATE TEMPORARY TABLE tt_Action       
      		WITH RECURSIVE  CTE_JsonCount as
      		(	SELECT 	0 SlNo
      			UNION ALL
      			SELECT 	SlNo + 1	SlNo
      			FROM 	CTE_JsonCount
      			WHERE 	SlNo  < v_JLength - 1
      		)
      		SELECT  TRIM(BOTH '"' FROM (json_extract(p_TriggerAction, CONCAT('$[',SlNo,'].TicketTriggerActionId')))) 			AS TicketTriggerActionId,
      				TRIM(BOTH '"' FROM (json_extract(p_TriggerAction, CONCAT('$[',SlNo,'].ActionTypeId'))))      				AS ActionTypeId, 				
                    TRIM(BOTH '"' FROM (json_extract(p_TriggerAction, CONCAT('$[',SlNo,'].ActionOperatorId'))))      			AS ActionOperatorId, 				                
                     TRIM(BOTH '"' FROM (json_extract(p_TriggerAction, CONCAT('$[',SlNo,'].ActionValues')))) 	   				AS ActionValues
      		FROM CTE_JsonCount;	          
     
   		DELETE 	AC
   		FROM 	tb_TicketTriggerAction	AC
   		LEFT JOIN tt_Action				t_AC 	ON 	AC.TicketTriggerActionId 	= t_AC.TicketTriggerActionId
   												AND	t_AC.TicketTriggerActionId 	<> 0
   		WHERE 	t_AC.TicketTriggerActionId IS NULL
           AND 	AC.TicketTriggerId = v_TicketTriggerId;         
            DROP TEMPORARY TABLE IF EXISTS tt_Action; 
     		INSERT INTO tb_TicketTriggerAction
     		(	TicketTriggerId			
     			,ActionTypeId
                ,ActionOperatorId
     			,ActionValues				
     			,CreatedBy					
     			,CreatedDate				
     			,UpdatedBy					
     			,UpdatedDate)
     		SELECT 	v_TicketTriggerId
     			,	AC.ActionTypeId 
                ,	AC.ActionOperatorId
                 ,	AC.ActionValues
     			,	p_LoggedInUserId
     			,	v_now
     			,	p_LoggedInUserId
     			,	v_now     
             FROM 	tt_Action AC
             WHERE 	TicketTriggerActionId = 0;
             
             UPDATE 	tb_TicketTriggerAction	TA
             JOIN 	tt_Action				t_A	ON TA.TicketTriggerActionId = t_A.TicketTriggerActionId
             SET 	TA.ActionTypeId 	= t_A.ActionTypeId 
     			,	TA.ActionValues 	= t_A.ActionValues 
                 ,	TA.UpdatedBy		= p_LoggedInUserId	
     			,	TA.UpdatedDate		= v_now;
          END;  
          
          SELECT v_errcode errcode, v_errmsg errmsg;
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateTicketType` */;
