CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateTicketType`(
       IN p_TicketTypeId 				int,
       IN p_CompanyId 				int,
       IN p_ProductId 				int,
       IN p_TicketTypeName 			VARCHAR(50),
       IN p_TicketTypeDescription 	VARCHAR(255),
       IN p_IsDefault 				TINYINT,
       IN p_IsActive 					TINYINT,
       IN p_IsDeleted 				TINYINT,
       IN p_LoggedInUserID 			BIGINT       
   )
BEGIN
   	declare v_errcode 		int;
   	declare v_errmsg 		varchar(55);
      declare v_CurDate		DATETIME;
      
      SET v_CurDate = NOW();
       
  	sp_exit : begin
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		 IF EXISTS (
  			 SELECT 1
  			 FROM tb_TicketType
  			 WHERE TicketTypeId = p_TicketTypeId
  		 ) 
  		 THEN
  			 UPDATE tb_TicketType
  			 SET	TicketTypeName          = ifnull(p_TicketTypeName,TicketTypeName)
  					,TicketTypeDescription  = ifnull(p_TicketTypeDescription,TicketTypeDescription)
  					,IsDefault              = ifnull(p_IsDefault,IsDefault)
  					,IsActive               = ifnull(p_IsActive,IsActive)            
  					,IsDeleted				= ifnull(p_IsDeleted,IsDeleted)
  					,UpdatedBy              = p_LoggedInUserID
  					,UpdatedDate            = v_CurDate
  			 WHERE 
  			 TicketTypeId = p_TicketTypeId;
  			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 			if found_rows()>0
  			then
  				set v_errcode = 0;
  				set v_errmsg = 'updated successfully';
  				leave sp_exit;
  			end if;
  		 ELSE
  			 INSERT INTO tb_TicketType (
  				 CompanyId,
  				 ProductId,
  				 TicketTypeName,
  				 TicketTypeDescription,
  				 IsDefault,
  				 IsActive,
                   IsDeleted,
  				 CreatedBy,
  				 CreatedDate,
  				 UpdatedBy,
  				 UpdatedDate
  			 ) VALUES (
  				 p_CompanyId,
  				 p_ProductId,
  				 p_TicketTypeName,
  				 p_TicketTypeDescription,
  				 p_IsDefault,
  				 1,
                   0,
  				 p_LoggedInUserID,
  				 v_CurDate,
  				 p_LoggedInUserID,
  				 v_CurDate
  			 );
  			 
  			if row_count() > 0
  			then
  			   set v_errcode = 0;
  			   set v_errmsg = 'Inserted successfully';				
  			end if;			
  		end if;
  	end sp_exit;        
                       
  	select v_errcode as errcode, v_errmsg as errmsg;
                       
  end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
