CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateTpiSeo`( 
     p_productId 			INT,
     p_productName 			VARCHAR(250),
     p_Token      			LONGTEXT
 )
BEGIN
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(255) DEFAULT 'No Record to Config';
     DECLARE v_productId INT;
     DECLARE v_CurDate DATETIME;
 
     SET v_CurDate = NOW();


     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     SELECT productId INTO v_productId
     FROM tb_TpiSeo
     WHERE productId = p_productId
     and   productName =p_productName;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
     
      IF v_productId IS NULL THEN
 
         INSERT INTO tb_TpiSeo 
         (productId, productName, Token, createdAt, updatedAt)
         VALUES 
         (p_productId, p_productName, p_Token, v_CurDate, v_CurDate);
 
         SET v_productId = LAST_INSERT_ID();
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Inserted Successfully';
     ELSE
      UPDATE tb_TpiSeo
         SET Token = p_Token,
             updatedAt = v_CurDate
         WHERE productId = p_productId;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Updated Successfully';
     END IF;
 
     SELECT v_errcode AS errorcode, v_errmsg AS errormessage;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
