CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_insertUpdateVideoCallConfiguration`(
  p_domainId					INT	
  ,p_isLinkExpiry			TINYINT
  ,p_expiryUnit				TINYINT
  ,p_expiryUnitType			VARCHAR(15)
  ,p_isScreenShare			TINYINT
  ,p_isCoBrowser				TINYINT
  ,p_isFaceDocVerification	TINYINT
  ,p_isVirtualBackground		TINYINT
  ,p_emailAddress			VARCHAR(200)
  ,p_emailSubject			VARCHAR(200)
  ,p_emailMessage			JSON
  ,p_smsNumber				VARCHAR(200)
  ,p_smsSubject				VARCHAR(200)
  ,p_smsMessage				JSON
  ,p_virtualBackgroundId		SMALLINT	
  )
BEGIN
 	DECLARE v_domainId		INT;	
     DECLARE v_curDate		DATETIME DEFAULT NOW();	
     DECLARE v_errCode		TINYINT DEFAULT 0;
     DECLARE v_errMsg		VARCHAR(200) DEFAULT 'Add/Update video call configuration failed';
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
      SELECT domainId
      INTO 	v_domainId
      FROM 	tb_videoCallConfiguration
      WHERE 	domainId = p_domainId;
 	 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
      
      IF v_domainId IS NULL
      THEN
  		INSERT INTO tb_videoCallConfiguration(
  			domainId				
              ,isLinkExpiry			
              ,expiryUnit				
              ,expiryUnitType			
              ,isScreenShare			
              ,isCoBrowser			
              ,isFaceDocVerification	
              ,isVirtualBackground	
              ,emailAddress			
              ,emailSubject			
              ,emailMessage			
              ,smsNumber				
              ,smsSubject				
              ,smsMessage				
              ,virtualBackgroundId	
              ,createdDate			
              ,updatedDate
              )
          VALUES(
  			p_domainId				
              ,p_isLinkExpiry			
              ,p_expiryUnit			
              ,p_expiryUnitType		
              ,p_isScreenShare		
              ,p_isCoBrowser			
              ,p_isFaceDocVerification
              ,p_isVirtualBackground	
              ,p_emailAddress			
              ,p_emailSubject			
              ,p_emailMessage			
              ,p_smsNumber			
              ,p_smsSubject			
              ,p_smsMessage			
              ,p_virtualBackgroundId	
  			,v_curDate
              ,v_curDate
          );
          
          IF row_count() > 0
          THEN
  			SET v_errCode	= 1            
                , v_errMsg	= 'Inserted video call configuration successfully';
          END IF;
      ELSE
  		UPDATE 	tb_videoCallConfiguration	
          SET 	isLinkExpiry				= p_isLinkExpiry			
                  ,expiryUnit					= p_expiryUnit			
                  ,expiryUnitType				= p_expiryUnitType		
                  ,isScreenShare				= p_isScreenShare		
                  ,isCoBrowser				= p_isCoBrowser			
                  ,isFaceDocVerification		= p_isFaceDocVerification
                  ,isVirtualBackground		= p_isVirtualBackground	
                  ,emailAddress				= p_emailAddress			
                  ,emailSubject				= p_emailSubject			
                  ,emailMessage				= p_emailMessage			
                  ,smsNumber					= p_smsNumber			
                  ,smsSubject					= p_smsSubject			
                  ,smsMessage					= p_smsMessage			
                  ,virtualBackgroundId		= p_virtualBackgroundId	
                  ,updatedDate				= v_curDate
          WHERE 	domainId					= p_domainId;
          
  		IF row_count() > 0
 		THEN
 			SET v_errCode	= 2            
               , v_errMsg	= 'Updated video call configuration successfully';
          END IF;
      END IF; 
      
      SELECT v_errCode AS errCode, v_errMsg AS errMsg;
  END ;;
DELIMITER ;
