CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_insertUpdateVirtualBackground`(
p_virtualBackgroundId	SMALLINT
,p_domainId				INT	
,p_virtualBackground	VARCHAR(1000)
,p_isDefault			TINYINT
)
BEGIN
	DECLARE v_virtualBackgroundId	SMALLINT;	
    DECLARE v_curDate				DATETIME DEFAULT NOW();	
    DECLARE v_errCode				TINYINT DEFAULT 0;
    DECLARE v_errMsg				VARCHAR(200) DEFAULT 'Add/Update video call configuration failed';
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;    
	SELECT 	virtualBackgroundId	INTO v_virtualBackgroundId
    FROM 	tb_virtualBackground
    WHERE 	virtualBackgroundId	= p_virtualBackgroundId
    AND 	domainId			= p_domainId;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;     
    
    IF v_virtualBackgroundId IS NULL 
    THEN
		INSERT INTO tb_virtualBackground(
			domainId
			,virtualBackground
			,isDefault
			,createdDate
			,updatedDate
        )
        VALUES(
			p_domainId			
            ,p_virtualBackground
            ,p_isDefault		
            ,v_curDate
            ,v_curDate
        );
        
        SET v_virtualBackgroundId = LAST_INSERT_ID();
        
        IF ROW_COUNT() > 0
        THEN
			SET v_errCode	= 1            
              , v_errMsg	= 'Inserted virtual background successfully';
        END IF;
	ELSE
		UPDATE 	tb_virtualBackground
        SET		virtualBackground	= p_virtualBackground
			,	isDefault			= p_isDefault
            ,	updatedDate			= v_curDate
        WHERE 	virtualBackgroundId = v_virtualBackgroundId;
        
        IF ROW_COUNT() > 0
        THEN
			SET v_errCode	= 2            
              , v_errMsg	= 'Updated virtual background successfully';
        END IF;
    END IF; 
    
	SELECT 	v_virtualBackgroundId AS virtualBackgroundId, v_errCode AS errCode, v_errMsg AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
