CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateVisitorInsight`(
p_visitorInsightId	BIGINT	
,p_customerId		BIGINT
,p_visitorId		VARCHAR(100)
,p_isNew			TINYINT	
,p_statusTypeId		INT
,p_startTime		BIGINT
,p_endTime			BIGINT
,p_domainId			INT
,p_ipAddress		VARCHAR(100)
,p_location			VARCHAR(100)
,p_browser			VARCHAR(100)
,p_device			VARCHAR(100)
,p_entryPage		VARCHAR(1000)
,p_isVisible		TINYINT	
)
BEGIN
	DECLARE v_curDate			DATETIME DEFAULT NOW();
 	DECLARE v_errCode			SMALLINT DEFAULT -1;
 	DECLARE v_errMsg			VARCHAR(150) DEFAULT 'Insert/Update visitor insight failed';
    DECLARE v_visitorInsightId	BIGINT;	
    
    SELECT 	visitorInsightId INTO v_visitorInsightId
    FROM 	tb_visitorInsight    
	WHERE 	visitorInsightId 	= p_visitorInsightId
    AND 	domainId			= p_domainId;
    
    IF v_visitorInsightId IS NULL
    THEN
		INSERT INTO tb_visitorInsight
        (	visitorInsightId	
            ,customerId			
            ,visitorId			
            ,isNew				
            ,statusTypeId		
            ,startTime			
            ,endTime			
            ,domainId			
            ,ipAddress			
            ,location			
            ,browser			
            ,device				
            ,entryPage			
            ,isVisible		
            ,createdAt	
            ,updatedAt	
        )
        VALUES
        (	p_visitorInsightId	
            ,p_customerId		
            ,p_visitorId		
            ,p_isNew			
            ,p_statusTypeId		
            ,p_startTime		
            ,p_endTime			
            ,p_domainId			
            ,p_ipAddress		
            ,p_location			
            ,p_browser			
            ,p_device			
            ,p_entryPage		
            ,p_isVisible		
            ,v_curDate
            ,v_curDate        
        );
        
        SET v_visitorInsightId = last_insert_id();
        SET v_errCode 	= 1
		, 	v_errMsg	= 'Insert visitor insight successfully';
	ELSE
		UPDATE 	tb_visitorInsight
        SET 	customerId			= p_customerId
            ,	visitorId			= p_visitorId	
            ,	isNew				= p_isNew		
            ,	statusTypeId		= p_statusTypeId	            
            ,	endTime				= p_endTime		
            ,	ipAddress			= p_ipAddress			
            ,	location			= p_location	
            ,	browser				= p_browser			
            ,	device				= p_device		
            ,	entryPage			= p_entryPage	
            ,	isVisible			= p_isVisible	           
            ,	updatedAt			= v_curDate
        WHERE 	visitorInsightId	= v_visitorInsightId;     
        
        SET v_errCode 	= 2
		, 	v_errMsg	= 'Update visitor insight successfully';
    END IF;

	SELECT v_visitorInsightId AS 'visitorInsightId', v_errCode AS 'errCode', v_errMsg AS 'errMsg';
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
