CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateVoiceAnalytics_config`(   
     p_domainId        INT,
     p_ext             INT,
     p_editColumnNames LONGTEXT,
     p_id              TINYINT
 )
BEGIN
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(255) DEFAULT 'No Record to Config';
     DECLARE v_voiceVCId INT;
     DECLARE v_CurDate DATETIME;
 

     SET v_CurDate = NOW();
 

     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 
     SELECT voiceVCId INTO v_voiceVCId
     FROM voiceEditColumns VC
     WHERE VC.domainId = p_domainId
       AND   VC.Id =p_id
       AND VC.ext = p_ext;
 

     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     IF v_voiceVCId IS NULL THEN
         INSERT INTO voiceEditColumns 
         (domainId, ext, Id, editColumnNames, createdAt, updatedAt)
         VALUES 
         (p_domainId, p_ext, p_id, p_editColumnNames, v_CurDate, v_CurDate);
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Inserted Successfully';
         SET v_voiceVCId = LAST_INSERT_ID();
     ELSE
         UPDATE voiceEditColumns
         SET editColumnNames = p_editColumnNames,
         
             updatedAt        = v_CurDate
         WHERE voiceVCId = v_voiceVCId;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Updated Successfully';
     END IF;
 
 
     SELECT v_voiceVCId AS voiceVCId, p_domainId AS domainId, p_ext AS ext, p_editColumnNames AS editColumnNames, v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
