CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateWhatappDurationHistory`(	
       	 p_WhatsappDurationHistoryId	BIGINT
       	,p_WhatsappHistoryId		    BIGINT             
       	,p_StartTime			        BIGINT
       	,p_EndTime				        BIGINT
       	,p_Duration				        BIGINT        
       	,p_AgentId				        BIGINT
       	,p_AgentSkillId			        INT
       	,p_IsBot				        TINYINT
       	,p_BotId				       	INT
       	,p_QueueId				       	INT
        ,p_dialDuration					BIGINT        
        ,p_IsMissed						TINYINT

        )
BEGIN	
    	DECLARE v_errCode				    INT	DEFAULT -1;
    	DECLARE v_errMsg				    VARCHAR(150) DEFAULT 'No Whatapp Duration';
    	DECLARE v_StartTime              	BIGINT;
    	DECLARE v_EndTime                	BIGINT;
    	DECLARE	v_WhatsappDurationHistoryId	BIGINT;   	
    	DECLARE	v_CurDate				    DATETIME;
		DECLARE	v_CurUnixtTimestamp			BIGINT;

    	SET v_CurDate = NOW();
       SET v_CurUnixtTimestamp = UNIX_TIMESTAMP(NOW(3)) * 1000;
    	IF IFNULL(p_StartTime,0)	= 0 THEN SET v_StartTime = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_StartTime = p_StartTime;  END IF; 	
    	IF IFNULL(p_EndTime,0)=0 	THEN SET v_EndTime 	= unix_timestamp(now())*1000; ELSE SET v_EndTime = p_EndTime; END IF; 	
     
    	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    	SELECT 	WhatsappDurationHistoryId INTO v_WhatsappDurationHistoryId
    	FROM 	tb_WhatsappDurationHistory
 	    WHERE 	WhatsappHistoryId	= p_WhatsappHistoryId
        limit 1;
 	
    	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;     
          
    	IF v_WhatsappDurationHistoryId IS NULL
    	THEN
       		INSERT INTO tb_WhatsappDurationHistory       
    		(	WhatsappHistoryId
    			,StartTime
    			,EndTime
    			,Duration
    			,AgentId
    			,AgentSkillId
    			,IsBot
    			,BotId
    			,QueueId
                ,dialDuration
                ,IsMissed
    			,createdAt
    			,updatedAt
    		)
       		VALUES
               (	p_WhatsappHistoryId
                   ,p_StartTime		
                   ,p_EndTime			
                   ,p_Duration			
                   ,p_AgentId			
                   ,p_AgentSkillId		
                   ,p_IsBot			
                   ,p_BotId					
                   ,p_QueueId	
				   ,p_dialDuration	
				   ,p_IsMissed		                   
                   ,v_CurDate
                   ,v_CurDate
               );                   
               
               
               SET v_errCode	= 0;
               SET v_errMsg 	= 'Whatapp Duration Added Successfully';
               
       	ELSE
       		UPDATE 	tb_WhatsappDurationHistory
               SET 
       			 StartTime			= IFNULL(p_StartTime,StartTime)			
       			,EndTime			= IFNULL(p_EndTime,EndTime)			
       			,Duration			= IFNULL(p_Duration,Duration)			
       			,AgentId			= IFNULL(p_AgentId,AgentId)				
       			,AgentSkillId		= IFNULL(p_AgentSkillId,AgentSkillId)			
       			,IsBot				= IFNULL(p_IsBot,IsBot)					
       			,BotId				= IFNULL(p_BotId,BotId)						
     			,QueueId			= IFNULL(p_QueueId,QueueId)
                ,dialDuration       = IFNULL(p_dialDuration,dialDuration)
                ,IsMissed           = IFNULL(p_IsMissed,IsMissed)
     			,updatedAt			= v_CurDate            
       		WHERE 	WhatsappDurationHistoryId = v_WhatsappDurationHistoryId;	
                   
 			SET v_errCode	= 0;
 			SET v_errMsg 	= 'Whatapp Duration Upadted Successfully';
       	END IF;
 
 		UPDATE tb_WhatsappHistory
 		SET 	assignedBy			= -1
 			,	assignedTo			= p_AgentId
 			,	assignedOn			= v_CurUnixtTimestamp
 			,	updatedAt			= v_CurDate            
 		WHERE WhatsappHistoryId	= p_WhatsappHistoryId;
             
       	SELECT p_WhatsappHistoryId	WhatsappHistoryId, v_errCode errCode,v_errMsg 	errMsg;
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_InsertUpdateWhatappDurationHistory1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateWhatappDurationHistory1`(	
   	 p_WhatsappDurationHistoryId	BIGINT
   	,p_WhatsappHistoryId		    BIGINT             
   	,p_StartTime			        BIGINT
   	,p_EndTime				        BIGINT
   	,p_Duration				        BIGINT
   	,p_AgentId				        BIGINT
   	,p_AgentSkillId			        INT
   	,p_IsBot				        TINYINT
   	,p_BotId				       	INT
   	,p_QueueId				       	INT)
BEGIN	
	DECLARE v_errCode				    INT	DEFAULT -1;
	DECLARE v_errMsg				    VARCHAR(150) DEFAULT 'No Whatapp Duration';
	DECLARE v_StartTime              	BIGINT;
	DECLARE v_EndTime                	BIGINT;
	DECLARE	v_WhatsappDurationHistoryId	BIGINT;
	Declare v_WhatsappHistoryId         BIGINT;
	DECLARE	v_CurDate				    DATETIME;
    DECLARE	v_CurUnixtTimestamp			BIGINT;
   
	SET v_CurDate = NOW();
    SET v_CurUnixtTimestamp = UNIX_TIMESTAMP(NOW(3)) * 1000;
	IF IFNULL(p_StartTime,0)	= 0 THEN SET v_StartTime = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_StartTime = p_StartTime;  END IF; 	
	IF IFNULL(p_EndTime,0)=0 	THEN SET v_EndTime 	= unix_timestamp(now())*1000; ELSE SET v_EndTime = p_EndTime; END IF; 	
 
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
	SELECT 	WhatsappDurationHistoryId INTO v_WhatsappDurationHistoryId
	FROM 	tb_WhatsappDurationHistory
    WHERE 	WhatsappDurationHistoryId	= p_WhatsappDurationHistoryId;

	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;     
      
	IF v_WhatsappDurationHistoryId IS NULL
	THEN
   		INSERT INTO tb_WhatsappDurationHistory       
		(	WhatsappHistoryId
			,StartTime
			,EndTime
			,Duration
			,AgentId
			,AgentSkillId
			,IsBot
			,BotId
			,QueueId
			,createdAt
			,updatedAt
		)
   		VALUES
           (	p_WhatsappHistoryId
               ,p_StartTime		
               ,p_EndTime			
               ,p_Duration			
               ,p_AgentId			
               ,p_AgentSkillId		
               ,p_IsBot			
               ,p_BotId					
               ,p_QueueId	
               ,v_CurDate
               ,v_CurDate
           );       
           
           UPDATE 	tb_WhatsappHistory
           SET 		assignedTo			= p_AgentId
				,	assignedOn			= v_CurUnixtTimestamp
                ,	updatedAt			= v_CurDate            
           WHERE 	WhatsappHistoryId	= p_WhatsappHistoryId;
           
           
           SET v_errCode	= 0;
           SET v_errMsg 	= 'Whatapp Duration Added Successfully';
           
   	ELSE
   		UPDATE 	tb_WhatsappDurationHistory
           SET 
   			StartTime			= IFNULL(p_StartTime,StartTime)			
   			,EndTime			= IFNULL(p_EndTime,EndTime)			
   			,Duration			= IFNULL(p_Duration,Duration)			
   			,AgentId			= IFNULL(p_AgentId,AgentId)				
   			,AgentSkillId		= IFNULL(p_AgentSkillId,AgentSkillId)			
   			,IsBot				= IFNULL(p_IsBot,IsBot)					
   			,BotId				= IFNULL(p_BotId,BotId)						
 			,QueueId			= IFNULL(p_QueueId,QueueId)
 			,updatedAt			= v_CurDate            
   		WHERE 	WhatsappHistoryId = p_WhatsappHistoryId;	
               
		SET v_errCode	= 0;
		SET v_errMsg 	= 'Whatapp Duration Upadted Successfully';
   	END IF;
   		
   	SELECT v_WhatsappHistoryId	WhatsappHistoryId, v_errCode errCode,v_errMsg 	errMsg;
   END ;;
DELIMITER ;
