CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateWhatsapp`(	
                  	p_sessionId				TEXT, 
                  	p_sessionStartTime		BIGINT,
                  	p_sessionEndTime		BIGINT,
                  	p_domainID				INT,
                  	p_message				JSON,
                  	p_customerNumber		BIGINT,
                  	p_calledNumber			BIGINT,
                  	p_dispositionId			INT,
                  	p_IsInBound				TINYINT	,
          			p_IsSessionClosed		TINYINT,
          			p_IsBot					INT,
          			p_Summary				text
             )
sp_exit: BEGIN
                   		DECLARE v_errcode 		INT DEFAULT -1;
                   		DECLARE v_errmsg 		VARCHAR(255) DEFAULT 'No Whatsapp';	
                   		DECLARE v_WhatsappHistoryId	BIGINT;
                   		DECLARE v_Curdate		DATETIME;	
         				DECLARE v_IsUpdate		TINYINT;
                         DECLARE v_dispositionId INT;
                 
                   		SET v_Curdate  = NOW();  
                        
    			if exists(select 1 from tb_PlanRecharge where domainId = p_domainID and cast(planEndTime as date) < cast(v_Curdate as date) limit 1) 
     			then 
     				select -1 as errcode, 'Inactive Plan' as errmsg;
     				leave sp_exit;
     			End if;
                             
     				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     					SELECT did INTO v_dispositionId
     					FROM disposition_status 
     					WHERE domainId = p_domainId
     					AND dispositionName = 'Closed'
                         LIMIT 1;
     				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
                  
                  
                     
  				update tb_WhatsappHistory a join tb_WhatsappDurationHistory b on a.WhatsappHistoryId = b.WhatsappHistoryId
  				set b.IsBot = 1
  				where TIMESTAMPDIFF(MINUTE, a.createdAt, now()) >= if(p_domainId=20598,60,1440) and a.IsSessionClosed = 0;
                 
     				update tb_WhatsappHistory set IsSessionClosed = 1  where TIMESTAMPDIFF(MINUTE, createdAt, now()) >= if(p_domainId=20598,60,1440) and IsSessionClosed = 0;
              
     				update tb_WhatsappHistory a join tb_WhatsappDurationHistory b on a.WhatsappHistoryId = b.WhatsappHistoryId
                     set  a.dispositionId = v_dispositionId
                     ,	a.sessionEndTime = unix_timestamp(current_timestamp())*1000
                     where TIMESTAMPDIFF(MINUTE, a.createdAt, now()) >= if(p_domainId=20598,60,1440) and (sessionEndTime is null or sessionEndTime = 0)
                     and (dispositionId = 0 or dispositionId is null);
     				
                        select domainId into p_domainID from tb_WhatsappConfiguration where whatsappNumber COLLATE utf8mb4_unicode_ci = p_calledNumber limit 1;
                  
                        if exists(select 1 from customer_contact  where domainId = p_domainID and  (primaryPhoneNumber like p_customerNumber OR phoneNumber like concat('%',p_customerNumber,'%')) and blockCustomer = 1) 
                        then 
              				select -1 as errcode,'Customer number is blocked' as errmsg;
                              leave sp_exit;
         				End if;
                        
                        if exists(select 1 from tb_CurrentPlan where domainId = p_domainID and TotalSession = TotalSessionUsed and isUnilimitedChat = 0 limit 1) 
                             then 
                   				select -1 as errcode, 'No Session Available' as errmsg;
     							leave sp_exit;
              				End if;
                             
                         sp_return : BEGIN    
                         
                        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
                   	
                     		SELECT 	WhatsappHistoryId INTO v_WhatsappHistoryId  
                     		FROM 	tb_WhatsappHistory SH 
                     		WHERE 	SH.customerNumber 	= p_customerNumber 
                     		AND 	SH.calledNumber 	= p_calledNumber  		
                     		AND 	IsSessionClosed		= 0 
                         
                     		ORDER BY WhatsappHistoryId DESC LIMIT 1;        
                            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
               		IF v_WhatsappHistoryId IS NULL 
               		THEN      		        
               			INSERT INTO tb_WhatsappHistory(sessionId,sessionStartTime,sessionEndTime,domainId,customerNumber,calledNumber,dispositionId  ,IsInBound,createdAt,updatedAt,IsSessionClosed)
               			VALUES(p_sessionId,p_sessionStartTime,p_sessionEndTime,p_domainID,p_customerNumber,p_calledNumber,p_dispositionId,p_IsInBound,v_Curdate,v_Curdate,p_IsSessionClosed);
               
               				SET v_WhatsappHistoryId = last_insert_id(); 
               
               				INSERT INTO tb_WhatsappDurationHistory(WhatsappHistoryId,AgentId,AgentSkillId,IsBot,BotId,QueueId,createdAt)
               				VALUES(v_WhatsappHistoryId,null,null,p_IsBot,null,null,now());
               
               				SET v_errcode = 0;
               				SET v_errmsg = 'Whatsapp added successfully';
            				SET v_IsUpdate = 0;
                            
     								UPDATE 	tb_CurrentPlan
     								SET 	
     											TotalSessionUsed			= case when isUnilimitedChat = 1 then TotalSessionUsed else ifnull(TotalSessionUsed,0) + 1 end
     											,updatedDate				= v_Curdate
     								WHERE 	domainId = p_DomainId;
                            
                     		ELSE
                    			UPDATE tb_WhatsappHistory SH
                    			SET	
                    				SH.sessionEndTime  	= IFNULL(p_sessionEndTime,SH.sessionEndTime),
                    				SH.customerNumber 	= IFNULL(p_customerNumber,SH.customerNumber),				
                    				SH.calledNumber 	= IFNULL(p_calledNumber,SH.calledNumber),
                    				SH.dispositionId  	= IFNULL(p_dispositionId,SH.dispositionId),
                                    SH.IsInBound		= IFNULL(p_IsInBound,SH.IsInBound),
                                    SH.Summary			= IFNULL(p_Summary,SH.Summary),
                    				SH.updatedAt		= v_Curdate,
                					SH.IsSessionClosed	= IFNULL(p_IsSessionClosed,SH.IsSessionClosed)
                    			WHERE WhatsappHistoryId	= v_WhatsappHistoryId;
                                 
                    			SET v_errcode = 0;
                    			SET v_errmsg = 'Whatsapp updated successfully';
            					SET v_IsUpdate = 1;
                                
                				UPDATE tb_WhatsappDurationHistory
                				SET IsBot = p_IsBot,
                					updatedAt = v_Curdate
                				WHERE WhatsappHistoryId	= v_WhatsappHistoryId;
                 
                     		END IF; 
                      		
                     		IF JSON_VALID(p_message) = 1
                             THEN
                     			IF EXISTS (	SELECT 1 FROM tb_WhatsappMessage WHERE WhatsappHistoryId = v_WhatsappHistoryId) THEN            
                     				UPDATE 	tb_WhatsappMessage a
                     				SET 	a.message 	= IFNULL(JSON_ARRAY_APPEND(a.message, '$', p_message), if(a.message is null,p_message,JSON_ARRAY_APPEND(a.message, '$', p_message)))
              						,	a.updatedAt	= v_Curdate
                     				WHERE 	WhatsappHistoryId 	= v_WhatsappHistoryId;
                                     
                                     SET v_errmsg = CONCAT(v_errmsg,', Message updated successfully');
                                 ELSE
                     				INSERT INTO tb_WhatsappMessage
                     				(	WhatsappHistoryId
                     					,Message	
                     					,createdAt	
                     					,updatedAt	
                     				)
                     				VALUES
                     				(	v_WhatsappHistoryId
                     					,p_message
                     					,v_Curdate
                     					,v_Curdate
                     				); 
                                     
                                     SET v_errmsg = CONCAT(v_errmsg,', Message added successfully');
                     			END IF;  
                     		END IF; 
                     	END ;   
                         
                     	
         	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         	SELECT    v_IsUpdate as IsUpdate, p_domainID AS domainId, v_errcode AS errcode, v_errmsg AS errmsg ,wh.*,wd.*,wm.* ,'Whatsapp' as channelType
         	from tb_WhatsappHistory 				wh
         	left join tb_WhatsappDurationHistory 	wd on wh.WhatsappHistoryId = wd.WhatsappHistoryId
         	join tb_WhatsappMessage					wm on wh.WhatsappHistoryId = wm.WhatsappHistoryId
         	where wh.WhatsappHistoryId = v_WhatsappHistoryId;
         	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
         END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
