CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateWhatsappConfiguration`(	
 		p_WhatsappConfigurationId 	    	INT 
 		,p_whatsappNumber               	BIGINT
 		,p_profilePicture					VARCHAR(500)
 		,p_businessName						VARCHAR(150)
 		,p_aboutBusiness					TEXT
 		,p_isBot 							TINYINT      
 		,p_whatsappFlowId					INT
 		,p_Industry							VARCHAR(100)
 		,p_businessAddress					VARCHAR(2500)
 		,p_contactEmail						VARCHAR(150)
 		,p_websiteURL1						VARCHAR(150)
 		,p_websiteURL2						VARCHAR(150)
 		,p_isDisabled						TINYINT    
 		,p_domainId							INT
 		,p_planId							INT	
 		,p_isBotPurchased					TINYINT
 		,p_isConnector 						TINYINT
 		,p_connectorName 					VARCHAR(100)
 		,p_storeName 						VARCHAR(100) 
 		,p_callBackToggle					TINYINT
 		,p_callBackForm						VARCHAR(10)
 		,p_notifyAdmin						VARCHAR(50)
 		,p_notificationMessages				VARCHAR(100)
 		,p_companyLogo						TEXT
 		,p_businessInformation				VARCHAR(100)
 		,p_statusMessage					VARCHAR(200)
 		,p_address							TEXT
 		,p_emailID							VARCHAR(100)
 		,p_customerOptIn					VARCHAR(100)
 		,p_pricing							VARCHAR(100)
 		,p_whatsAppBusinessSolutionUseCases	VARCHAR(100)
 		,p_companyProfile					VARCHAR(100)
 		,p_locationOfCompanyHeadquarters	VARCHAR(100)
        ,p_knowledgeBaseId					VARCHAR(100)
    )
BEGIN
		DECLARE v_errCode					INT 			DEFAULT '-1';
		DECLARE v_errMsg					VARCHAR(150) 	DEFAULT 'Whatsapp Configuration Failed';
		DECLARE v_curdate					DATETIME;
		DECLARE v_WhatsappConfigurationId 	INT; 
		DECLARE v_configurationId 			INT; 
     
    	
    	SET v_curdate = NOW();
        DESC tb_WhatsappConfiguration;
        SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
        SELECT 	WhatsappConfigurationId	INTO v_WhatsappConfigurationId
        FROM 	tb_WhatsappConfiguration
        WHERE 	WhatsappConfigurationId = p_WhatsappConfigurationId;    
        SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        
        IF v_WhatsappConfigurationId IS NULL
        THEN
    		INSERT INTO tb_WhatsappConfiguration
            (	domainId
    			  ,profilePicture
  			  ,whatsappNumber
                ,businessName				
                ,aboutBusiness	
                ,planId
                ,isBot 	
                ,isBotPurchased
                ,whatsappFlowId				
                ,Industry			
                ,businessAddress			
                ,contactEmail				
                ,websiteURL1				
                ,websiteURL2				            
                ,createdDate				            
                ,updatedDate	
                ,isConnector
                ,connectorName
                ,storeName
                ,knowledgeBaseId
                
    		)
           VALUES
           (	p_domainId
    			  ,p_profilePicture		
                ,p_whatsappNumber
                ,p_businessName				
                ,p_aboutBusiness	
                ,p_planId
                ,p_isBot 		
                ,p_isBotPurchased
                ,p_whatsappFlowId			
                ,p_Industry		
                ,p_businessAddress			
                ,p_contactEmail				
                ,p_websiteURL1				
                ,p_websiteURL2				            
                ,v_curdate            
                ,v_curdate
                ,p_isConnector
                ,p_connectorName
                ,p_storeName
                ,p_knowledgeBaseId
           );
           
           SET 	v_errCode	= 0
    		, 	v_errMsg	= 'Whatsapp Configuration inserted successfully';
         
         SET v_configurationId = last_insert_id();
         
         INSERT INTO ccaas_whatsapp_onboarding_details_confirmation(fk_WhatsappConfigurationId,domainId,notificationMessages,companyLogo,businessInformation,statusMessage,address,emailID,customerOptIn,pricing
 		,whatsAppBusinessSolutionUseCases,companyProfile,locationOfCompanyHeadquarters)
         VALUES(v_configurationId,p_domainId,p_notificationMessages,p_companyLogo,p_businessInformation,p_statusMessage,p_address,p_emailID,p_customerOptIn,p_pricing
 		,p_whatsAppBusinessSolutionUseCases,p_companyProfile,p_locationOfCompanyHeadquarters);
         
         
    	ELSE
    		UPDATE 	tb_WhatsappConfiguration
            SET 	profilePicture			=	IFNULL(p_profilePicture, profilePicture)
 			,   whatsappNumber          =   IFNULL(p_whatsappNumber, whatsappNumber)
 			,	businessName			=	IFNULL(p_businessName,	businessName)		
 			,	aboutBusiness			=	IFNULL(p_aboutBusiness,	aboutBusiness)	
 			,	planId					= 	IFNULL(p_planId, planId)
 			,	isBot 					=	IFNULL(p_isBot,	isBot)			
 			,	isBotPurchased			= 	IFNULL(p_isBotPurchased, isBotPurchased)
 			,	whatsappFlowId			=	IFNULL(p_whatsappFlowId,	whatsappFlowId)	
 			,	Industry				=	IFNULL(p_Industry, Industry)
 			,	businessAddress			=   IFNULL(p_businessAddress,	businessAddress)
 			,	contactEmail			=	IFNULL(p_contactEmail,	contactEmail)
 			,	websiteURL1				=   IFNULL(p_websiteURL1,	websiteURL1)
 			,	websiteURL2				=   IFNULL(p_websiteURL2,	websiteURL2)
 			,	isConnector				=   IFNULL(p_isConnector,	isConnector)
 			,	connectorName			=   IFNULL(p_connectorName,	connectorName)
 			,	storeName				=   IFNULL(p_storeName,	storeName)
 			,	updatedDate				= 	v_curdate
 			,	callBackToggle			=	IFNULL(p_callBackToggle, callBackToggle)
 			, 	callBackForm			=	IFNULL(p_callBackForm, callBackForm)
 			, 	notifyAdmin				=	IFNULL(p_notifyAdmin, notifyAdmin)
 			, 	knowledgeBaseId			=	IFNULL(p_knowledgeBaseId, knowledgeBaseId)
 		WHERE 	WhatsappConfigurationId = 	v_WhatsappConfigurationId;	
         
         
         UPDATE ccaas_whatsapp_onboarding_details_confirmation
         SET notificationMessages				=IFNULL(p_notificationMessages	,	notificationMessages)
 			,companyLogo						=IFNULL(p_companyLogo			,	companyLogo)
 			,businessInformation				=IFNULL(p_businessInformation	,	businessInformation)
 			,statusMessage						=IFNULL(p_statusMessage			,	statusMessage)
 			,address							=IFNULL(p_address				,	address)
 			,emailID							=IFNULL(p_emailID				,	emailID)
 			,customerOptIn						=IFNULL(p_customerOptIn			,	customerOptIn)
 			,pricing							=IFNULL(p_pricing				,	pricing)
 			,whatsAppBusinessSolutionUseCases	=IFNULL(p_whatsAppBusinessSolutionUseCases	,	whatsAppBusinessSolutionUseCases)
 			,companyProfile						=IFNULL(p_companyProfile				,	companyProfile)
 			,locationOfCompanyHeadquarters		=IFNULL(p_locationOfCompanyHeadquarters	,	locationOfCompanyHeadquarters)
 		WHERE fk_WhatsappConfigurationId 		= v_WhatsappConfigurationId;
    
           SET 	v_errCode	= 1
   			, 	v_errMsg	= 'Whatsapp Configuration updated successfully';        
        END IF; 
        
        SELECT v_errCode AS errCode, v_errMsg AS errMsg;
    END ;;
DELIMITER ;
