CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_InsertUpdateWhatsappDidPurchase`(	  
	 p_whatsappDidPurchaseId	INT		    
     , p_type					VARCHAR(100)		
     , p_yourNumber				BIGINT	
     , p_domainId				INT		
     , p_whatsAppFlowId			INT		
     , p_queueId					INT		
     , p_outbound				TINYINT 
     , p_threshold				TINYINT	    
     , p_defaultUpdated			TINYINT	    
     , p_isBot					TINYINT	
     , p_isBotPurchased			TINYINT	
     , p_knowledgeBasedId		INT	
     , p_autoAssignAgentId		INT	    
 )
BEGIN
	 DECLARE v_whatsappDidPurchaseId	INT;
     DECLARE v_errCode					TINYINT;
     DECLARE v_errMsg					VARCHAR(150);
     DECLARE v_Curdate					DATETIME;
     
     SET v_Curdate = NOW();
     SET v_whatsappDidPurchaseId = p_whatsappDidPurchaseId;
     
  
	UPDATE 	tb_whatsappDidPurchase
	SET		yourNumber				= IFNULL(p_yourNumber			, 	yourNumber)						
		, 	whatsAppFlowId			= IFNULL(p_whatsAppFlowId		, 	whatsAppFlowId)		
		, 	queueId					= IFNULL(p_queueId				, 	queueId)				
		, 	outbound				= IFNULL(p_outbound				, 	outbound)			
		, 	threshold				= IFNULL(p_threshold			, 	threshold)							
		, 	defaultUpdated			= IFNULL(p_defaultUpdated		, 	defaultUpdated)					
		, 	isBot					= IFNULL(p_isBot				, 	isBot)					
		, 	isBotPurchased			= IFNULL(p_isBotPurchased		, 	isBotPurchased)		
		, 	knowledgeBasedId		= IFNULL(p_knowledgeBasedId		, 	knowledgeBasedId)	
		, 	autoAssignAgentId		= IFNULL(p_autoAssignAgentId	, 	autoAssignAgentId)		
		, 	updatedAt				= v_Curdate	
	WHERE 	whatsappDidPurchaseId	= v_whatsappDidPurchaseId;
        
    IF row_count() > 0
    THEN
		SET v_errCode 	= 0;
        SET v_errMsg 	= 'Updated successfully';
	ELSE
		SET v_errCode 	= -1;
        SET v_errMsg 	= 'No Update';    
    END IF;
    
	SELECT v_errCode as errCode, v_errMsg as errMsg;
 END ;;
DELIMITER ;
