CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdateWhatsAppTemplate`(	
	 p_templateName			VARCHAR(200)
	,p_templateType			VARCHAR(100)
	,p_domainId				INT
	,p_buttonName			VARCHAR(200)
	,p_buttonUrl			VARCHAR(1000)
	,p_content				TEXT    
    ,p_Id					VARCHAR(50)
    ,p_number				VARCHAR(50)
    ,p_flowId				INT
  )
BEGIN
  	DECLARE v_Curdate				DATETIME DEFAULT NOW();
 	DECLARE v_whatsAppTemplateId	INT;
 	DECLARE v_errMsg				VARCHAR(200) DEFAULT 'Whatsapp template add/update failed';
 	DECLARE v_errCode				TINYINT DEFAULT -1;
      
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT 	whatsAppTemplateId INTO v_whatsAppTemplateId 
    FROM 	tb_whatsAppTemplate 
 	WHERE 	domainId		= p_domainId
 	AND		flowId 			= p_flowId;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
      
      IF v_whatsAppTemplateId IS NULL
      THEN 		
  		INSERT INTO tb_whatsAppTemplate
          (	templateName
  			,templateType
  			,domainId
  			,buttonName
  			,buttonUrl
  			,content
            ,Id
            ,number
            ,flowId
  			,createdAt
  			,updatedAt
          )
          VALUES
          (	p_templateName		
              ,p_templateType		
              ,p_domainId			
              ,p_buttonName		
              ,p_buttonUrl		
              ,p_content		
              ,p_Id
              ,p_number
              ,p_flowId
              ,v_Curdate
              ,v_Curdate
          );
  			
          SET v_whatsAppTemplateId = last_insert_id();
          SET v_errMsg	= 'Whatsapp template added successfuly'
			, v_errCode	= 1;
      ELSE
  		UPDATE 	tb_whatsAppTemplate
          SET 	templateName	= IFNULL(p_templateName	,templateName)	
  			,	templateType	= IFNULL(p_templateType	,templateType)		
  			,	buttonName		= IFNULL(p_buttonName	,buttonName)	
  			,	buttonUrl		= IFNULL(p_buttonUrl	,buttonUrl)	
  			,	content			= IFNULL(p_content		,content)		            
  			,	updatedAt		= v_Curdate
		WHERE whatsAppTemplateId= v_whatsAppTemplateId;
              
  		SET v_errMsg	= 'Whatsapp template updated successfuly'
  		, 	v_errCode	= 2;            
      END IF;
      
  	SELECT 	v_errMsg AS errMsg, v_errCode AS errCode;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
