CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_insertupdate_analytics_config`(
	 p_analyticsId int 
	 ,p_domainId		INT
  	,p_ext			INT
  	,p_editColumn	LONGTEXT
	,p_analyticsType	VARCHAR(50)
    )
begin
    
	DECLARE v_errcode  		INT DEFAULT 		-1;
 	DECLARE v_errmsg   		VARCHAR(55) DEFAULT 'No Record to Config';
	DECLARE v_CurDate		DATETIME;
  	DECLARE v_analyticsId		INT;
      
      SET v_CurDate  = NOW();
  	
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 	SELECT analyticsId INTO v_analyticsId
 	FROM 	analytics_config AC
 	WHERE 	
            AC.domainId 	= p_domainId
 	AND 	AC.ext			= p_ext
 	AND		AC.analyticsType 	= p_analyticsType COLLATE utf8mb4_0900_ai_ci;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
 
      IF v_analyticsId IS NULL
      THEN
  		INSERT INTO analytics_config                                            
          (	domainId
  			,ext
  			,editColumn			
  			,analyticsType
			,createdAt
  			,updatedAt
          )
          VALUES
          (	   p_domainId		
              ,p_ext			
              ,p_editColumn	
              ,p_analyticsType	
  			  ,v_CurDate
              ,v_CurDate        
          );
          
		SET v_analyticsId	= last_insert_id();
  		SET v_errcode 		= 0;
  		SET v_errmsg 		= 'Configuration Inserted Successfully';        
  	ELSE
  		UPDATE 	analytics_config
          SET 	  editColumn	= p_editColumn           
                  ,updatedAt	= v_CurDate
  		WHERE 	analyticsId 	= p_analyticsId;
          
  		SET v_errcode 	= 0;
  		SET v_errmsg 	= 'Configuration Updated Successfully';                
      END IF;
  
  	SELECT v_analyticsId analyticsId, p_domainId	domainId, p_ext ext, p_editColumn editColumn, p_analyticsType analyticsType, v_errcode errcode, v_errmsg errmsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
