CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdate_chat_configuration_primary_form`(		
		p_aid				INT
       	,p_domainId			INT
       	,p_title			VARCHAR(100)
       	,p_description		VARCHAR(1000)	
       	,p_chatFlowId		INT
       	,p_chatIconLogo		TEXT
       	,p_domain			LONGTEXT
       	,p_personalization	LONGTEXT
       	,p_primaryForm		LONGTEXT
       	,p_callFlowName		VARCHAR(100)
       	,p_preChartFormFlag	INT
       	,p_webchatid		VARCHAR(20)        
       	,p_codeSnippet		LONGTEXT
       	,p_status			INT
       	,p_formDetails		LONGTEXT
       	,p_greeting			LONGTEXT
       	,p_templateData		LONGTEXT
   		,p_plan_id 			int
   		,p_product_id		int
 		,p_websiteId 		LONGTEXT
 		,p_autoResponse		LONGTEXT
        ,p_isCallBack		TINYINT 
        ,p_thresholdTime	SMALLINT
        ,p_aliasTitle		VARCHAR(100)
       )
BEGIN
       	DECLARE v_errCode	INT	DEFAULT -1;
       	DECLARE v_errMsg	VARCHAR(150) DEFAULT 'No Chat Duration';
       	DECLARE	v_CurDate	DATETIME;
       	DECLARE	v_aid		BIGINT;	
           
           SET v_CurDate = NOW();
           SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
           SELECT 	aid		INTO v_aid
           FROM 	chat_configuration_primary_form
           WHERE 	aid 	= p_aid;
           SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
           IF v_aid IS NULL
           THEN
    		INSERT INTO chat_configuration_primary_form( domainId,title,`description`,chatFlowId,chatIconLogo,domain,personalization,primaryForm,callFlowName,preChartFormFlag,webchatid,websiteId,
    			codeSnippet,`status`,formDetails,greeting,templateData,createdAt,updateddAt,plan_id,product_id,autoResponse,isCallBack,thresholdTime,aliasTitle)
    		VALUES (p_domainId,p_title,p_description,p_chatFlowId,p_chatIconLogo,p_domain,p_personalization,p_primaryForm,p_callFlowName,p_preChartFormFlag,p_webchatid,p_websiteId,
    			p_codeSnippet,p_status,p_formDetails,p_greeting,p_templateData,v_CurDate,v_CurDate,p_plan_id,p_product_id,p_autoResponse,p_isCallBack,p_thresholdTime,p_aliasTitle);
    
               SET v_aid 		= last_insert_id();
               SET v_errCode	= 0;
       		SET v_errMsg	= 'Chat Configuration Primary Form Added Successfully';
       	ELSE
       		UPDATE 	chat_configuration_primary_form
               SET 	domainId		=  ifnull(p_domainId,domainId)	
    			,	title				=  ifnull(p_title,title	)
    			,	`description`		=  ifnull(p_description	,`description`	)		
    			,	chatFlowId			=  ifnull(p_chatFlowId	,chatFlowId	)
    			,	chatIconLogo		=  ifnull(p_chatIconLogo ,chatIconLogo )		
    			,	domain				=  ifnull(p_domain,domain )
    			,	personalization		=  ifnull(p_personalization	,personalization)
    			,	primaryForm			=  ifnull(p_primaryForm	,primaryForm)		
    			,	callFlowName		=  ifnull(p_callFlowName , callFlowName)	
    			,	preChartFormFlag	=  ifnull(p_preChartFormFlag , preChartFormFlag)		
    			,	webchatid			=  ifnull(p_webchatid , webchatid	)
				,	websiteId			=  ifnull(p_websiteId , websiteId)
    			,	codeSnippet			=  ifnull(p_codeSnippet	, codeSnippet)
    			,	`status`			=  ifnull(p_status , `status`	)	
    			,	formDetails			=  ifnull(p_formDetails	, formDetails)
    			,	greeting			=  ifnull(p_greeting , greeting	)	
    			,	templateData		=  ifnull(p_templateData , templateData	)	
    			,	updateddAt			=  v_CurDate
    			,	plan_id 			=  ifnull(p_plan_id , plan_id)
    			,	product_id 			=  ifnull(p_product_id , product_id)
				,	autoResponse		=  ifnull(p_autoResponse , autoResponse)
                ,	isCallBack			=  ifnull(p_isCallBack,isCallBack)
                ,	thresholdTime		=  ifnull(p_thresholdTime,thresholdTime)
                ,	aliasTitle			=  ifnull(p_aliasTitle,aliasTitle)
               WHERE aid = v_aid;
               
               SET v_errCode	= 0;
       		SET v_errMsg	= 'Chat Configuration Primary Form Updated Successfully';
           END IF;    
           
           SELECT v_aid 'aid',p_webchatid 'webchatid',v_errCode 'errCode',v_errMsg 'errMsg';
       END ;;
