CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdate_did_purchase`(
		p_pid				INT
		,p_user_id			INT		
		,p_city				VARCHAR(255)
		,p_country			VARCHAR(255)
		,p_your_number		varchar(255)
		,p_domainId			BIGINT	
		,p_callFlowId		VARCHAR(100)
		,p_recording		INT
		,p_status			INT
		,p_queueId			INT
		,p_isCall			TINYINT
		,p_isSms			TINYINT
		,p_aliasName		VARCHAR(40)
		,p_outboundSms		TINYINT
		,p_smsThreshold		INT
		,p_callFlowName		VARCHAR(100)
		,p_defaultUpdated	INT
		,p_supervisorName	VARCHAR(200)
		,p_isCallIn			TINYINT
		,p_isCallOut		TINYINT
		,p_isSmsOut			TINYINT
		,p_isSmsIn  		TINYINT
		,p_type				varchar(255)
       
     )
BEGIN
     	DECLARE v_pid			INT;
     	DECLARE v_errcode 		INT DEFAULT -1;
         DECLARE v_errmsg 		VARCHAR(150) DEFAULT 'No update in Did Purchase or pid should not be zero while updating';
         DECLARE v_CurDate		DATETIME;
         DECLARE v_queueName	VARCHAR(250);
         
         SET v_CurDate = NOW();
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         
         SELECT name INTO v_queueName 
         FROM 	queue
         WHERE 	qid	= p_queueId
     	AND		domainId	= p_domainId;
         
         SELECT	pid	INTO v_pid
         FROM 	did_purchase
         WHERE 	pid = p_pid;
         
         IF v_pid IS NULL
         THEN
			SELECT pid INTO v_pid
			FROM did_purchase 
			WHERE your_number COLLATE utf8mb4_unicode_ci = p_your_number 
			AND domainId= p_domainId 
			LIMIT 1;
		END IF;
         
         SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
        IF v_pid IS NULL         
         THEN
     		INSERT INTO did_purchase 
     		(	user_id	
     			,city
     			,country
     			,your_number	
     			,domainId
     			,callFlowId
     			,recording
     			,status
     			,queueId
     			,queueName
     			,isCall
     			,isSms
     			,aliasName
     			,outboundSms
     			,smsThreshold
     			,callFlowName
     			,defaultUpdated
     			,supervisorName
     			,isCallIn
     			,isCallOut
     			,isSmsOut
     			,isSmsIn
     			,createdAt
     			,updatedAt
               ,type) 
     		VALUES 
     		(	p_user_id			  
     			,p_city				
     			,p_country			
     			,p_your_number		
     			,p_domainId			
     			,p_callFlowId		
     			,p_recording		
     			,p_status			
     			,p_queueId		
     			,v_queueName		
     			,p_isCall			
     			,p_isSms			
     			,p_aliasName		
     			,p_outboundSms		
     			,p_smsThreshold		
     			,p_callFlowName		
     			,p_defaultUpdated	
     			,p_supervisorName	
     			,p_isCallIn			
     			,p_isCallOut		
     			,p_isSmsOut			
     			,p_isSmsIn 
     			,v_CurDate
     			,v_CurDate
               ,p_type);
                 
     		IF row_count() > 0
     		THEN
     			SET v_pid		= last_insert_id();	
     			SET v_errcode 	= 0;
     			SET v_errmsg	= 'Did Purchase Inserted Successfully'; 
     		END IF;            
     	ELSE
     		UPDATE 	did_purchase
     		SET 	user_id			=	IFNULL(p_user_id, user_id)						
     			,	city			=	IFNULL(p_city	, city)
     			,	country			=	IFNULL(p_country	, country)
     			,	callFlowId		=	IFNULL(p_callFlowId	, callFlowId)
     			,	recording		=	IFNULL(p_recording	, recording)
     			,	status			=	IFNULL(p_status		, status)
     			,	queueId			=	IFNULL(p_queueId	, queueId)
     			,	queueName		=	IFNULL(v_queueName	, queueName)
     			,	isCall			=	IFNULL(p_isCall		, isCall)
     			,	isSms			=	IFNULL(p_isSms		, isSms)
     			,	aliasName		=	IFNULL(p_aliasName	, aliasName)
     			,	outboundSms		=	IFNULL(p_outboundSms, outboundSms)
     			,	smsThreshold	=	IFNULL(p_smsThreshold, smsThreshold)
     			,	callFlowName	=	IFNULL(p_callFlowName	, callFlowName)
     			,	defaultUpdated	=	IFNULL(p_defaultUpdated	, defaultUpdated)
     			,	supervisorName	=	IFNULL(p_supervisorName	, supervisorName)
                 ,	isCallIn	    =   IFNULL(p_isCallIn		, isCallIn)
                 ,	isCallOut       =   IFNULL(p_isCallOut		, isCallOut)
                 ,	isSmsOut	    =   IFNULL(p_isSmsOut		, isSmsOut)
                 ,	isSmsIn 		= 	IFNULL(p_isSmsIn		, isSmsIn)
                 ,	updatedAt		= 	v_CurDate
                 ,	type			=	IFNULL(p_type			, type)
             WHERE 	pid COLLATE utf8mb4_unicode_ci = v_pid;
             
             IF row_count() > 0
     		THEN			
     			SET v_errcode 	= 0;
     			SET v_errmsg	= 'Did Purchase Updated Successfully'; 
     		END IF;  
         END IF;
         select v_errcode as errcode, v_errmsg as errmsg; 
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
