CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_insertUpdate_installedStoredData`(
	p_connectionId		int,
	p_shopName			varchar(100),
	p_accessToken		varchar(250),
	p_token				varchar(10000)
)
begin
	DECLARE v_errcode int DEFAULT -1;
    DECLARE v_errmsg varchar(50) DEFAULT 'Add/Update installed stored data Fail';
    DECLARE v_curDate datetime;
    DECLARE v_installedStoredDataId int;
    
    SET v_curDate = now();
    
    select installedStoredDataId into v_installedStoredDataId
    from tb_installedStoredData where connectionId = p_connectionId and shopName = p_shopName;
    
    IF v_installedStoredDataId IS NOT NULL
    THEN
    
    UPDATE tb_installedStoredData
    SET shopName		= IFNULL(p_shopName,shopName),	
        accessToken		= IFNULL(p_accessToken,accessToken),	
        token			= IFNULL(p_token,token),
        updatedAt		= v_curDate
        where installedStoredDataId = v_installedStoredDataId;
        
			SET v_errcode = 2;
			SET v_errmsg  = 'Updated Successfully';
       
  ELSE      
		INSERT INTO tb_installedStoredData(connectionId ,shopName ,accessToken ,token ,createdAt,updatedAt)
		VALUES (p_connectionId ,p_shopName ,p_accessToken ,p_token,v_curDate,v_curDate);
		
        SET v_installedStoredDataId = last_insert_id();
        
			SET v_errcode = 1;
			SET v_errmsg  = 'Inserted Successfully';
        
END IF;
		SELECT v_errcode as errcode,v_errmsg as errmsg, v_installedStoredDataId as installedStoredDataId;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
