CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_insertupdate_tb_google_gmailtoken`(
    p_id           INT,
    p_Gmail        VARCHAR(255),
    p_refreshtoken VARCHAR(1000),
    p_Isdisconnect TINYINT
)
BEGIN
    DECLARE v_errcode INT DEFAULT -1;
    DECLARE v_errmsg  VARCHAR(55) DEFAULT 'inserted not successful';
    DECLARE v_CurDate DATETIME;
    DECLARE v_Gmail   VARCHAR(255);
    SET v_CurDate = NOW();
    
    SELECT Gmail INTO v_Gmail FROM tb_google_gmailtoken WHERE Gmail = p_Gmail;

    IF v_Gmail IS NOT NULL THEN
        UPDATE tb_google_gmailtoken
        SET
            refreshtoken = p_refreshtoken,
            updatedAt = v_CurDate
        WHERE Gmail = p_Gmail;
        SET v_errcode = 1;
        SET v_errmsg = 'Updated Successfully';
    ELSE
        INSERT INTO tb_google_gmailtoken (
            id,
            Gmail,
            refreshtoken,
            Isdisconnect,
            createdAt,
            updatedAt
        )
        VALUES (
           p_id,
           p_Gmail,
           p_refreshtoken,
           p_Isdisconnect,
            v_CurDate,
            v_CurDate
        );

        SET v_errcode = 0;
        SET v_errmsg = 'Inserted successfully';
    END IF;
SELECT v_errcode AS errcode, v_errmsg AS errmsg;
END ;;
DELIMITER ;
