CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InsertUpdate_websiteScraper`(	
	p_web_id				INT
  ,	p_websiteId				VARCHAR(100)
  ,	p_websiteUrl			LONGTEXT
  ,	p_baseName				VARCHAR(55)
  ,	p_discription			LONGTEXT
  ,	p_domainId				INT
  , p_CompanyType			VARCHAR(150)
  , p_language 				varchar(50)
  , p_customerWebsiteUrl 	TEXT
  , p_agentWebsiteUrl 		TEXT
  ,	p_knowledgeBaseMainType	INT
  )
BEGIN
	DECLARE v_errcode  		INT DEFAULT 		-1;
	DECLARE v_errmsg   		VARCHAR(55) DEFAULT 'No Website Scraper';
	DECLARE v_CurDate		DATETIME;
	DECLARE v_web_id		INT;
    
	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
	SELECT 	web_id INTO v_web_id
	FROM 	websiteScraper
	WHERE 	web_id = p_web_id;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
    
	IF v_web_id IS NULL
	THEN
		INSERT INTO websiteScraper
		(	websiteId	
		  ,	websiteUrl	
		  ,	baseName		
		  ,	discription	
		  ,	domainId
          ,	CompanyType
          , `language`
          , createdAt
          , agentWebsiteUrl
          , customerWebsiteUrl
          ,	knowledgeBaseMainType
		)
		VALUES
		(	p_websiteId	
		  ,	p_websiteUrl	
		  ,	p_baseName		
		  ,	p_discription	
		  ,	p_domainId	
          , p_CompanyType
          , p_language
          , now()
          , p_agentWebsiteUrl
          , p_customerWebsiteUrl
          ,	p_knowledgeBaseMainType
		);

		SET v_web_id 	= last_insert_id();       
		SET v_errcode	= 0;
		SET v_errmsg 	= 'Website Scraper Added Successfully';
	ELSE
		UPDATE websiteScraper
		SET websiteId			= p_websiteId		
		,	websiteUrl			= p_websiteUrl	
		,	baseName			= p_baseName		
		,	discription			= p_discription	
		,	domainId			= p_domainId
		,	CompanyType			= p_CompanyType
        ,   `language` 			= p_language 
        ,	updatedAt  			= now()
        ,	customerWebsiteUrl  = IFNULL(p_customerWebsiteUrl,customerWebsiteUrl)
        ,	agentWebsiteUrl  	= IFNULL(p_agentWebsiteUrl,agentWebsiteUrl)
		WHERE web_id 			= v_web_id;

		SET v_errcode	= 0;
		SET v_errmsg 	= 'Website Scraper Updated Successfully';
	END IF;
      
	SELECT v_web_id 'web_id',v_errcode  'errcode',v_errmsg 'errmsg';
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
