CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_insert_update_chatAgentAssistMessage`(
     p_HistoryId                BIGINT,  
     p_DurationHistoryId        BIGINT,
     p_domainId                 INT,
     p_AssistMsg                JSON,
     p_NoOfUsedAssistMsg        INT,
     p_totalNoOfassist          INT,
     p_channelType              VARCHAR(50)
 )
BEGIN
     DECLARE v_errcode 		INT DEFAULT -1;
     DECLARE v_errmsg 		VARCHAR(100) DEFAULT 'failure';
     DECLARE v_curdate 		DATETIME;    
     DECLARE v_historyId 	INT;  
     DECLARE v_isLike		SMALLINT;
     DECLARE v_isDislike	SMALLINT;
     DECLARE v_AssistMsg	JSON;
     
     SET v_curdate = NOW(); 
     
     IF p_channelType IN ('Chat', 'Call') 
     THEN
         IF EXISTS (SELECT 1 FROM tb_chatAgentAssistMessage 
                    WHERE historyId = p_HistoryId 
                    AND durationHistoryId = p_DurationHistoryId 
                    LIMIT 1) 
		THEN
             UPDATE tb_chatAgentAssistMessage 
             SET 
                 assistMsg = CASE WHEN p_NoOfUsedAssistMsg = 0 THEN JSON_ARRAY_APPEND(assistMsg, '$', p_AssistMsg) ELSE assistMsg END,
                 noOfUsedAssistMsg = noOfUsedAssistMsg + p_NoOfUsedAssistMsg,
                 totalNoOfassist = totalNoOfassist + p_totalNoOfassist,
                 channelType = p_channelType,
                 updatedDate = v_curdate
			WHERE historyId = p_HistoryId
			AND channelType = p_channelType
			AND durationHistoryId = p_DurationHistoryId
			AND domainId = p_domainId;
               
             IF ROW_COUNT() > 0 THEN
                 SET v_errcode = 0;
                 SET v_errmsg = 'Updated successfully';
             END IF;
         ELSE
             INSERT INTO tb_chatAgentAssistMessage (
                 historyId,
                 durationHistoryId,
                 domainId,
                 assistMsg,
                 noOfUsedAssistMsg,
                 totalNoOfassist,
                 channelType,
                 createdDate,
                 updatedDate
             )
             VALUES (
                 p_HistoryId,
                 p_DurationHistoryId,
                 p_domainId,
                 concat('[',p_AssistMsg,']'), 
                 p_NoOfUsedAssistMsg,
                 p_totalNoOfassist,
                 p_channelType,
                 v_curdate,
                 v_curdate
             );
             
             SET v_errcode = 0;
             SET v_errmsg = 'Inserted successfully';
         END IF;
         
		SELECT 	assistMsg INTO v_AssistMsg
		FROM 	tb_chatAgentAssistMessage
		WHERE 	historyId 			= p_HistoryId
		AND		durationHistoryId 	= p_DurationHistoryId
		AND 	domainId 			= p_domainId
		AND 	channelType 		= p_channelType
        LIMIT 1;
     ELSEIF p_channelType IN ('WhatsApp', 'Facebook', 'Instagram') THEN
         IF EXISTS (SELECT 1 FROM tb_chatAgentAssistMessage 
                    WHERE historyId = p_HistoryId 
                    AND domainId = p_domainId
                    AND channelType = p_channelType
                    LIMIT 1) THEN
             UPDATE tb_chatAgentAssistMessage 
             SET 
                 assistMsg = CASE WHEN p_NoOfUsedAssistMsg = 0 THEN JSON_ARRAY_APPEND(assistMsg, '$', p_AssistMsg) ELSE assistMsg END,
                 noOfUsedAssistMsg = noOfUsedAssistMsg + p_NoOfUsedAssistMsg,
                 totalNoOfassist = totalNoOfassist + p_totalNoOfassist,
                 updatedDate = v_curdate
             WHERE historyId = p_HistoryId
               AND domainId = p_domainId
               AND channelType = p_channelType;
               
             IF ROW_COUNT() > 0 THEN
                 SET v_errcode = 0;
                 SET v_errmsg = 'Updated successfully';
             END IF;              
         ELSE
             INSERT INTO tb_chatAgentAssistMessage (
                 historyId,
                 durationHistoryId,
                 domainId,
                 assistMsg,
                 noOfUsedAssistMsg,
                 totalNoOfassist,
                 channelType,
                 createdDate,
                 updatedDate
             )
             VALUES (
                 p_HistoryId,
                 p_DurationHistoryId,
                 p_domainId,
                 concat('[',p_AssistMsg,']'), 
                 p_NoOfUsedAssistMsg,
                 p_totalNoOfassist,
                 p_channelType,
                 v_curdate,
                 v_curdate
             );
             
             SET v_errcode = 0;
             SET v_errmsg = 'Inserted successfully';
         END IF;
 
		SELECT 	assistMsg INTO v_AssistMsg
		FROM 	tb_chatAgentAssistMessage
		WHERE 	historyId 	= p_HistoryId		
		AND 	domainId 	= p_domainId
		AND 	channelType = p_channelType
        LIMIT 1;

 
     END IF;   
    
	SELECT 	SUM(AgentAssist.isLike)
		,	SUM(AgentAssist.isDislike)
    INTO 	v_isLike, v_isDislike
	FROM  JSON_TABLE(v_AssistMsg, '$[*]' 
			COLUMNS 
			(	isLike	 	TINYINT PATH '$.isLike'		
				,isDislike 	TINYINT PATH '$.isDislike')) AgentAssist;                
    
	IF p_channelType IN ('Chat', 'Call') 
	THEN
		UPDATE 	tb_chatAgentAssistMessage 
		SET 	totalLike			= v_isLike
			,	totalDislike		= v_isDislike	
			,	updatedDate 		= v_curdate
		WHERE 	historyId 			= p_HistoryId
        AND 	durationHistoryId 	= p_DurationHistoryId
		AND 	channelType 		= p_channelType		
		AND 	domainId 			= p_domainId;
    ELSEIF p_channelType IN ('WhatsApp', 'Facebook', 'Instagram') THEN
		UPDATE 	tb_chatAgentAssistMessage 
		SET 	totalLike			= v_isLike
			,	totalDislike		= v_isDislike	
			,	updatedDate 		= v_curdate
		WHERE 	historyId 			= p_HistoryId
		AND 	channelType 		= p_channelType		
		AND 	domainId 			= p_domainId;    
    END IF;
    
    SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
