CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_insert_update_ticket_chat`(
    p_TicketChatId			INT,
    p_SessionId			VARCHAR(150),
    p_RequestedCompanyId	INT, 
    p_RequestedProductId	INT, 
    p_Title				VARCHAR(100),
    p_Message				JSON,
    p_TicketId				BIGINT
    )
BEGIN
   	DECLARE v_errcode 		INT;
   	DECLARE v_errmsg 		VARCHAR(200);  
   	DECLARE v_now 			DATETIME;
   	DECLARE v_TicketChatId	INT;
   	DECLARE v_TicketChatId1	INT;
   	DECLARE v_TicketId		BIGINT;
   	DECLARE v_CompanyId		INT;	
        
    	SET v_now = NOW();
        
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;     
    	SELECT 	companyId
    	INTO 	v_CompanyId                        
    	FROM 	tb_companyDomain
    	WHERE 	isTechSupport = 1;
        
    SELECT TicketChatId INTO v_TicketChatId
    FROM 	tb_TicketChat
    WHERE 	SessionId 	COLLATE utf8mb4_unicode_ci = p_SessionId
    AND 	CompanyId	= v_CompanyId; 
    
    SELECT TicketChatId 
    INTO 	v_TicketChatId1		
    FROM 	tb_TechSupportTicket
    WHERE 	TechSupportTicketId	= p_TicketId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
        
 	IF v_TicketChatId IS NULL
 	THEN		
 		INSERT INTO tb_TicketChat(				
 			SessionId				
 			,CompanyId				 						
 			,RequestedCompanyId		
 			,RequestedProductId		
 			,Title					
 			,Message            
 			,CreatedDate				
 			,UpdatedDate	
 		)
 		VALUES(
 			p_SessionId					
 			,v_CompanyId							
 			,p_RequestedCompanyId
 			,p_RequestedProductId
 			,p_Title				
 			,p_Message				            
 			,v_now
 			,v_now
 		);    
 	   
 	   SET 	v_TicketChatId = last_insert_id();
 	   SET	v_errcode	= 1
 		 , 	v_errmsg 	= 'Added chat successfully';
 	ELSE                
 		UPDATE 	tb_TicketChat C
 		   SET 	C.Title		= IFNULL(p_Title,C.Title)
 			,	C.Message 	= if(C.Message is null,p_Message,JSON_ARRAY_APPEND(C.Message, '$', p_Message))
 			,	C.UpdatedDate = now()
 		WHERE 	C.TicketChatId = v_TicketChatId;
 		   
 		SET		v_errcode	= 2
 			 , 	v_errmsg 	= 'Updated chat successfully';
 	END IF;
        
 	IF v_TicketChatId1 IS NULL AND p_TicketId IS NOT NULL
 	THEN
 		UPDATE 	tb_TechSupportTicket
 		SET 	TicketChatId		= v_TicketChatId        
 		WHERE 	TechSupportTicketId	= p_TicketId;
 	END IF;    
    
    	SELECT v_TicketChatId AS TicketChatId, v_errcode AS errcode, v_errmsg AS errmsg,v_CompanyId AS CompanyId;
  END ;;
DELIMITER ;
