CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InserUpdateChatDurationHistory`(	
 		p_ChatDurationHistoryId					BIGINT
 		,p_ChatHistoryId						BIGINT
 		,p_StartTime							BIGINT
 		,p_EndTime								BIGINT
 		,p_Duration								BIGINT
 		,p_AgentId								BIGINT
 		,p_AgentSkillId							INT
 		,p_IsBot								TINYINT
 		,p_BotId								INT
 		,p_transferredTime						BIGINT
 		,p_QueueId								INT	
 		,p_dispositionId 						INT
 		,p_transferedBy 						INT
 		,p_transferedTo 						INT
 		,p_ticketId 							BIGINT
 		,p_Summary 								TEXT
 		,p_SentimentalScore						FLOAT
 		,p_sentimentalScoreCustomer 			FLOAT
 		,p_sentimentalScoreAgent    			FLOAT
 		,p_markAsRead							TINYINT
 		,p_afterChatWorkTime 					BIGINT
 		,p_Istransferred						TINYINT
 		,p_IsMissed								TINYINT
 		,p_IsAbandoned							TINYINT
 		,p_answeredDuration						BIGINT
 		,p_chatDeflection                       INT
         ,p_isTrigger							tinyint
           )
SP_RETURN: BEGIN	
 
		DECLARE v_errCode				INT	DEFAULT -1;
		DECLARE v_errMsg				VARCHAR(150) DEFAULT 'No Chat Duration';
		DECLARE	v_CurDate				DATETIME;
		DECLARE	v_ChatDurationHistoryId	BIGINT;
             
             SET v_CurDate = NOW();
            
        	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
        	SELECT 	ChatDurationHistoryId INTO v_ChatDurationHistoryId
        	FROM 	tb_ChatDurationHistory
        	WHERE 	ChatDurationHistoryId = p_ChatDurationHistoryId;
        	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;         

             IF v_ChatDurationHistoryId IS NULL
             THEN
				
                IF IFNULL(p_ChatHistoryId,0)=0 THEN
					SELECT v_ChatDurationHistoryId	ChatDurationHistoryId, -1 errCode,'p_ChatHistoryId should not be zero' 	errMsg;
                    LEAVE SP_RETURN;         
                END IF;
             
         		INSERT INTO tb_ChatDurationHistory
                 (	ChatHistoryId
      				,StartTime
      				,EndTime
      				,Duration
      				,AgentId
      				,AgentSkillId
      				,IsBot
      				,BotId
      				,transferredTime
      				,QueueId
      				,dispositionId 	
      				,transferedBy 	
      				,transferedTo 	
      				,ticketId 		
      				,Summary 			
      				,SentimentalScore	
  					,sentimentalScoreCustomer
  					,sentimentalScoreAgent
      				,markAsRead		
  					,answeredDuration
      				,afterChatWorkTime
      				,Istransferred
  					,IsMissed		
  					,IsAbandoned
  	                ,chatDeflection
      				,createdAt
      				,updatedAt
                     ,isTrigger
         		)
         		VALUES
                 (	p_ChatHistoryId	
                     ,p_StartTime		
                     ,p_EndTime			
                     ,p_Duration			
                     ,p_AgentId			
                     ,p_AgentSkillId		
                     ,p_IsBot			
                     ,p_BotId				
                     ,p_transferredTime	
                     ,p_QueueId	
                     ,p_dispositionId 	
                     ,p_transferedBy 	
                     ,p_transferedTo 	
                     ,p_ticketId 		
                     ,p_Summary 			
                     ,p_SentimentalScore	
                     ,p_sentimentalScoreCustomer
                     ,p_sentimentalScoreAgent
                     ,p_markAsRead	
                     ,p_answeredDuration
                     ,p_afterChatWorkTime
                     ,p_Istransferred	
                     ,p_IsMissed		
                     ,p_IsAbandoned	
                     ,p_chatDeflection
                     ,v_CurDate
                     ,v_CurDate
                     ,p_isTrigger
                 );        
                 
                 SET v_ChatDurationHistoryId = last_insert_id();
                 SET v_errCode	= 0;
                 SET v_errMsg 	= 'Chat Duration Added Successfully';
                 
         	ELSE
         		UPDATE 	tb_ChatDurationHistory
 				SET 	ChatHistoryId			= IFNULL(p_ChatHistoryId,ChatHistoryId)			
 				,	StartTime				= IFNULL(p_StartTime,StartTime)		
 				,	EndTime					= IFNULL(p_EndTime,EndTime)				
 				,	Duration				= IFNULL(p_Duration	,Duration)			
 				,	AgentId					= IFNULL(p_AgentId,AgentId)			
 				,	AgentSkillId			= IFNULL(p_AgentSkillId	,AgentSkillId)		
 				,	IsBot					= IFNULL(p_IsBot,IsBot)					
 				,	BotId					= IFNULL(p_BotId ,BotId)				
 				,	transferredTime			= IFNULL(p_transferredTime,transferredTime)			
 				,	QueueId					= IFNULL(p_QueueId,QueueId)
 				,	dispositionId 			= IFNULL(p_dispositionId,dispositionId) 	
 				,	transferedBy 			= IFNULL(p_transferedBy ,transferedBy)	
 				,	transferedTo 			= IFNULL(p_transferedTo ,transferedTo)	
 				,	ticketId 				= IFNULL(p_ticketId ,ticketId)		
 				,	Summary 				= IFNULL(p_Summary ,Summary)		
 				,	SentimentalScore		= IFNULL(p_SentimentalScore	,SentimentalScore)
 				, 	sentimentalScoreCustomer= IFNULL(p_sentimentalScoreCustomer ,sentimentalScoreCustomer)
 				,	sentimentalScoreAgent    = IFNULL(p_sentimentalScoreAgent ,sentimentalScoreAgent)
 				,	markAsRead				= IFNULL(p_markAsRead,markAsRead)		
 				,	answeredDuration		= IFNULL(p_answeredDuration,answeredDuration)
 				,	afterChatWorkTime		= IFNULL(p_afterChatWorkTime,afterChatWorkTime)
 				,	Istransferred	  		= IFNULL(p_Istransferred,Istransferred)	
 				,	IsMissed				= IFNULL(p_IsMissed,IsMissed)		
 				,	IsAbandoned				= IFNULL(p_IsAbandoned,IsAbandoned)	
 				,  	chatDeflection          = IFNULL(p_chatDeflection,chatDeflection)
 				,	updatedAt				= v_CurDate
                 ,	isTrigger				= ifnull(p_isTrigger,isTrigger)
         		WHERE 	ChatDurationHistoryId 	= v_ChatDurationHistoryId;	
        
         		SET v_errCode	= 0;
                 SET v_errMsg 	= 'Chat Duration Upadted Successfully';
         	END IF;
         		
         	SELECT v_ChatDurationHistoryId	ChatDurationHistoryId, v_errCode errCode,v_errMsg 	errMsg;
        END ;;
DELIMITER ;
