CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_InserUpdateChatMessage`(	
  	p_ChatDurationHistoryId		BIGINT
    	,p_ChatHistoryId			BIGINT
    	,p_Message					JSON
    	,p_isCustomer				TINYINT
    	,p_isAgent					TINYINT	
  	,p_botCustomerMsgCount		INT
      ,p_botMsgCount              TINYINT 
        )
BEGIN	
 		DECLARE v_errCode					INT	DEFAULT -1;
     	DECLARE v_errMsg					VARCHAR(150) DEFAULT 'No Chat Duration';
     	DECLARE	v_CurDate					DATETIME;
     	DECLARE	v_ChatDurationHistoryId		BIGINT;
            
     	SET v_CurDate = NOW(); 
         
 sp_return:begin
 
 		IF p_ChatHistoryId = 0 or (p_ChatDurationHistoryId is null or p_ChatDurationHistoryId = 0)
         THEN
 			SET v_errCode	= -1;
     		SET v_errMsg 	= 'Chat Message Added Failed';
 			LEAVE sp_return;
 		END IF;
        
        
   
     	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     	SELECT 	ChatDurationHistoryId INTO v_ChatDurationHistoryId
     	FROM 	tb_ChatMessage
     	WHERE 	ChatDurationHistoryId = p_ChatDurationHistoryId;
     	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
         
     	IF v_ChatDurationHistoryId IS NULL
     	THEN
     		INSERT INTO tb_ChatMessage
     		(	ChatDurationHistoryId
     			,ChatHistoryId
     			,Message
                ,customerMsgCount
                ,agentMsgCount
                ,botMsgCount
                ,botCustomerMsgCount
     			  ,createdAt
     			  ,updatedAt
     		)
     		VALUES
     		(	p_ChatDurationHistoryId
     			,p_ChatHistoryId
     			,p_Message
   			,IFNULL(p_isCustomer,0)            
   			,IFNULL(p_isAgent,0)
              ,IFNULL(p_botMsgCount,0)
   			,p_botCustomerMsgCount
     			,v_CurDate
     			,v_CurDate
     		);
     
     		SET v_errCode	= 0;
     		SET v_errMsg 	= 'Chat Message Added Successfully';
        	ELSE
        		UPDATE 	tb_ChatMessage
    			SET 	Message 				= JSON_ARRAY_APPEND(Message,'$',p_Message)
    				  ,	customerMsgCount		= customerMsgCount + IFNULL(p_isCustomer,0)       
                    ,	agentMsgCount		= agentMsgCount + IFNULL(p_isAgent,0)
                    , botMsgCount			= botMsgCount+ IFNULL(p_botMsgCount,0)
                    ,  botCustomerMsgCount   = botCustomerMsgCount+p_botCustomerMsgCount
        			,	updatedAt				= v_CurDate
    			WHERE 	ChatDurationHistoryId 	= v_ChatDurationHistoryId;        
                
        		SET v_errCode	= 0;
    			SET v_errMsg 	= 'Chat Message Updated Successfully';
        	END IF; 
  end;   
    		SELECT v_errCode errCode,v_errMsg 	errMsg;
 END ;;
DELIMITER ;
