CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Instagram_Edit_Column_insertandupdate_Details`( 
     p_domainId 			INT,
     p_ext      			INT,
     p_editColumnNames      LONGTEXT,
     p_Id 					INT
 )
BEGIN
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(255) DEFAULT 'No Record to Config';
     DECLARE v_InstagramId INT;
     DECLARE v_CurDate DATETIME;
 
     SET v_CurDate = NOW();
 
 
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     SELECT Id INTO v_InstagramId
     FROM InstagramEditColumns
     WHERE domainId = p_domainId
         AND Id = p_Id
         AND ext = p_ext;
 
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
     IF v_InstagramId IS NULL THEN
 
         INSERT INTO InstagramEditColumns 
         (domainId, ext, Id, editColumnNames, createdAt, updatedAt)
         VALUES 
         (p_domainId, p_ext, p_Id, p_editColumnNames, v_CurDate, v_CurDate);
 
         SET v_InstagramId = LAST_INSERT_ID();
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Inserted Successfully';
     ELSE
 
         UPDATE InstagramEditColumns
         SET editColumnNames = p_editColumnNames,
             updatedAt = v_CurDate
         WHERE Id = p_Id
             AND domainId = p_domainId
             AND ext = p_ext;
 
         SET v_errcode = 0;
         SET v_errmsg = 'Configuration Updated Successfully';
     END IF;
 
     SELECT v_errcode AS errorcode, v_errmsg AS errormessage;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
