/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_KnowledgBaseInteractionChannel`(
     p_startTmpstmp 	BIGINT,
     p_endTmpstmp 	    BIGINT,
     p_domainId 		INT
   )
BEGIN
     	DECLARE v_StartTmpstmp 		BIGINT;
     	DECLARE v_EndTmpstmp 		BIGINT;
   	    DECLARE v_Resolved 			INT;
        
  	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_StartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY)) * 1000; ELSE SET v_StartTmpstmp = p_startTmpstmp; END IF; 
   	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_EndTmpstmp = UNIX_TIMESTAMP(NOW()) * 1000; ELSE SET v_EndTmpstmp = p_endTmpstmp; END IF;  	       
        
        DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
     DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                    	
   								SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;             
                            		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                        		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
                                
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                        				WHEN dispositionName = 'Discarded'     THEN 4
 									WHEN dispositionName = 'Resolved'      THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;      
 DROP TEMPORARY TABLE IF EXISTS tmp_AgentAssistDurationHistory;
    CREATE TEMPORARY TABLE tmp_AgentAssistDurationHistory
   	SELECT 	H.ChatHistoryId											       AS HistoryId
    	   ,	CASE WHEN DH.dispositionId = v_Resolved THEN 1 ELSE 0 END  AS completedSession
           ,	H.sessionStartTime
           ,	DH.EndTime     
           ,	2003001					  									AS channelType		
   	FROM 	tb_ChatHistory			H
   	JOIN 	tb_ChatDurationHistory	DH	ON DH.ChatHistoryId = H.ChatHistoryId
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
	AND 	DH.IsBot			= 1;       
    
      
   	INSERT INTO tmp_AgentAssistDurationHistory(
   		   HistoryId
  		  ,completedSession
          ,sessionStartTime
          ,EndTime
          ,channelType
       )
   	SELECT 	H.CallHistoryId												AS HistoryId
		   ,	CASE WHEN DH.dispositionId = v_Resolved THEN 1 ELSE 0 END 	AS completedSession
           ,	H.sessionStartTime
           ,	DH.EndTime  
           ,	2003001														AS channelType		
   	FROM 	tb_CallHistory			H
	JOIN 	tb_CallDurationHistory	DH	ON DH.CallHistoryId = H.CallHistoryId
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
   	AND 	DH.IsBot			= 1;   

    	INSERT INTO tmp_AgentAssistDurationHistory(
   		   HistoryId
  		  ,completedSession
          ,sessionStartTime
          ,EndTime
          ,channelType
       )
       
          	SELECT 	H.SMSHistoryId													AS HistoryId
    		,	CASE WHEN H.dispositionId = v_Resolved THEN 1 ELSE 0 END 			AS completedSession
            ,	H.sessionStartTime		
            ,  	H.sessionEndTime     		
            ,	 2003004															 AS channelType		
   	FROM   tb_SMSHistory			H
  	JOIN 	tb_SMSDurationHistory	DH	ON DH.SMSHistoryId = H.SMSHistoryId
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
	AND 	DH.IsBot			= 1;   
        
    	INSERT INTO tmp_AgentAssistDurationHistory(
   		   HistoryId
  		  ,completedSession
          ,sessionStartTime
          ,EndTime
          ,channelType
       )
         SELECT 	H.EmailHistoryId											AS HistoryId
			,	CASE WHEN H.dispositionId = v_Resolved THEN 1 ELSE 0 END 	AS completedSession
            ,	H.sessionStartTime
            ,	H.sessionEndTime     
            ,	 2003003													    AS channelType		
   	FROM   tb_EmailHistory			H
  	JOIN 	tb_EmailDurationHistory	DH	ON DH.EmailHistoryId = H.EmailHistoryId
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
	AND 	DH.IsBot			= 1;  
       
          	INSERT INTO tmp_AgentAssistDurationHistory(
   		   HistoryId
  		  ,completedSession
          ,sessionStartTime
          ,EndTime
          ,channelType
       )
   	SELECT 	H.WhatsappHistoryId											    AS HistoryId
		   ,	CASE WHEN H.dispositionId = v_Resolved THEN 1 ELSE 0 END 	AS completedSession
           ,	H.sessionStartTime
           ,	DH.EndTime     
           ,	2003005													    AS channelType		
   	FROM tb_WhatsappHistory			H
  	JOIN 	tb_WhatsappDurationHistory	DH	ON DH.WhatsappHistoryId = H.WhatsappHistoryId
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
    AND 	DH.IsBot			= 1; 
    
    
  	INSERT INTO tmp_AgentAssistDurationHistory(
   		    HistoryId
           ,completedSession
           ,sessionStartTime
           ,EndTime
           ,channelType
       )
   	SELECT 	H.FacebookHistoryId											AS HistoryId
  		 ,	CASE WHEN H.DispositionId = v_Resolved THEN 1 ELSE 0 END 	AS completedSession
          ,	H.sessionStartTime
          ,	H.SessionEndTime     
          ,	2003006														AS channelType		
   	FROM 	tb_FacebookHistory			H     
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
	AND 	H.IsBot			= 1;       
    
     	INSERT INTO tmp_AgentAssistDurationHistory(
			HistoryId
           ,completedSession
           ,sessionStartTime
           ,EndTime
           ,channelType
       )
   	SELECT 	H.InstagramHistoryId										AS HistoryId
  		 ,	CASE WHEN H.DispositionId = v_Resolved THEN 1 ELSE 0 END 	AS completedSession
          ,	H.sessionStartTime
          ,	H.SessionEndTime     
          ,	2003007														AS channelType		
   	FROM 	tb_InstagramHistory			H     
   	WHERE 	H.sessionStartTime	BETWEEN v_StartTmpstmp AND v_EndTmpstmp
   	AND 	H.domainId			= p_domainId
   	AND 	H.IsBot			= 1;  
    

    DROP TEMPORARY TABLE IF EXISTS tmp_AgentAssistHistory;
       CREATE TEMPORARY TABLE tmp_AgentAssistHistory
       SELECT 	HistoryId								
           ,	MIN(channelType)						        AS channelType
       FROM 	tmp_AgentAssistDurationHistory
       GROUP BY HistoryId ;
       
       WITH CTE_AgentAssistInteractionChannel AS ( 
   	  SELECT 	COUNT(HistoryId)								AS totalSession
 		,	channelType        
       FROM 	tmp_AgentAssistDurationHistory	H  
       GROUP BY channelType
       )
       SELECT totalSession
 		,	C.TypeCodeName									    AS `channel`
       FROM 	CTE_AgentAssistInteractionChannel	H
       JOIN 	TypeCode					C	ON H.channelType	= C.TypeCodeID;     
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Chat_Edit_Column_insert_update_Details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Chat_Edit_Column_insert_update_Details`( 
 	   p_Id       		INT,
       p_domainId 		INT,
       p_ext 	 		INT,
       p_editColumnNames LONGTEXT,
       p_channelType VARCHAR(20)  
   )
BEGIN
       DECLARE v_errcode  					INT;
       DECLARE v_errmsg  					VARCHAR(250);
   	   DECLARE	v_CurDate					DATETIME;
	   DECLARE  v_queue_ChatId     			INT;
       DECLARE v_channelType                varchar(30);
       
    	SET v_CurDate = NOW();
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
      SELECT Id INTO v_queue_ChatId
      FROM up_QueueChatEditColumns
      WHERE domainId = p_domainId
      AND ext = p_ext
          AND Id = p_Id
          LIMIT 1;
          
	
    set v_channelType = p_channelType;
    
    set @v_s1 := (SELECT 1 from up_QueueChatEditColumns where 
              domainId = p_domainId
              AND ext  = p_ext
              AND  Id  = p_Id
              AND channelType = p_channelType) ;
              
		set @v_s1 := IFNULL(@v_s1, 0);
  
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  
      IF v_queue_ChatId IS NULL OR (@v_s1 != 1)
		THEN
          INSERT INTO up_QueueChatEditColumns 
          (domainId, ext, Id, editColumnNames, createdAt, updatedAt, channelType)
          VALUES 
          (p_domainId, p_ext, p_Id, p_editColumnNames, v_CurDate, v_CurDate, p_channelType);
  
         
  
          SET v_errcode = 0;
          SET v_errmsg = 'Configuration Inserted Successfully';

      ELSE
  
          UPDATE up_QueueChatEditColumns
          SET editColumnNames = p_editColumnNames,
              updatedAt = v_CurDate
          WHERE (Id = p_Id
              AND domainId = p_domainId
              AND ext = p_ext
              AND channelType = p_channelType) ;
  
          SET v_errcode = 0;
          SET v_errmsg = 'Configuration Updated Successfully';
      END IF;
  
      SELECT v_errcode AS errorcode, v_errmsg AS errormessage;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Facebook_Inbound_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Facebook_Inbound_analysis_metrics_filter`(
		p_startTmpstmp 		BIGINT,
		p_endTmpstmp 		BIGINT,
		p_domainId 			INT,    	
		p_queueId			TEXT,	       
		p_offset 			INT,
		p_limit 			INT
  
)
BEGIN
    		DECLARE v_offset 								INT;	  	
    		DECLARE v_CurrentStartTmpstmp 					BIGINT;
    		DECLARE v_CurrentEndTmpstmp 					BIGINT;
    		DECLARE v_PrevStartTmpstmp 						BIGINT;
    		DECLARE v_PrevEndTmpstmp 						BIGINT; 
    		DECLARE v_TmpstmpInterval						BIGINT;	
       		
			DECLARE v_CurTotalCount 					INT;
			DECLARE v_PrevTotalCount 					INT;
			DECLARE	v_DiffTotalPercent 					INT;
    			
			DECLARE v_PrevRespondedCount			    INT;	
			DECLARE v_CurrentRespondedCount			    INT;	        
			DECLARE v_DiffRespondedPercent			    INT;
    			
			DECLARE v_PrevAbandonedCount				INT;
			DECLARE v_CurrentAbandonedCount				INT;
			DECLARE v_DiffAbandonedPercent				INT;
    			
			DECLARE v_CurrentMissedCount				INT;
			DECLARE v_CurrentTransferredCount			INT;
			DECLARE v_TotalChatDuration					BIGINT;
    			
    
			DECLARE v_CurrentMaximumChatdurationCount	INT;
			DECLARE v_CurrentAverageChatdurationCount	INT;
			DECLARE v_TotalTalktime             		BIGINT;
			DECLARE v_TotalAfterCallWorkTime    		INT;
			DECLARE v_CurrentCallHoldTime       		INT;
			DECLARE v_CurrentAvailableTime      		INT;
			DECLARE v_CurrentCustomerFacebookCount		INT;
			DECLARE v_CurrentAgentFacebookCount			INT;           
			DECLARE v_SentimentalScore          		INT;
			DECLARE v_CurrentFirstCallResolution        INT;
			DECLARE v_startDate_from_unix				DATETIME;                 
            
            SET v_offset =  p_Limit * p_offset; 
         
			IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; 
				ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; 
			END IF; 
            
            
			IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; 
				ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; 
			END IF;  									
            
            
            
            
            SET v_TmpstmpInterval 	= v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          SET v_PrevEndTmpstmp 		= v_CurrentStartTmpstmp - 1;
          SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
          
          
			DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	
            CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
            CALL split(p_queueId,','); 
            INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
            
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
			DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
			CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid,`name` AS queueName  
            FROM queue
            WHERE domainId = p_domainId ;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
     		
            DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
			CREATE TEMPORARY TABLE temp_AvailableDisposition (    
								 DispositionId 			INT
                       			,DispositionStatus 		VARCHAR(100)
                       			,DispositionCategory	TINYINT
                       		); 
                            
            INSERT INTO temp_AvailableDisposition 
						SELECT 	did 		AS	DispositionId
						,	dispositionName	AS	DispositionStatus
						,	CASE WHEN dispositionName = 'Opened'				THEN 2
								WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
								WHEN dispositionName = 'Discarded'     				THEN 4
								WHEN dispositionName = 'Resolved'      				THEN 5
								WHEN dispositionName = 'Caller Disconnected'		THEN 6
                       				END 			DispositionCategory
                       		FROM 	disposition_status   
                       		WHERE 	domainId	= p_domainId;
            
              SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;   
              DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
    			CREATE TEMPORARY TABLE temp_FacebookHistory AS
    		    SELECT 	CH.sessionStartTime,		
					FROM_UNIXTIME(CH.sessionStartTime/1000) AS aa,
      					CH.FacebookHistoryId        
      				,	CH.queueId
                    ,   CH.IsMissed																				AS missedFacebook
      				,	CH.Istransferred
      				,	CH.dispositionId
      			    ,   CH.IsInBound
      				,	(CH.sessionEndTime - CH.sessionStartTime)	                         					AS FacebookDuration
					,	CH.customerFacebookId
      				,	CH.afterFacebookWorkTime
      			
      				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                	 				 AS discarded
      				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                	 				 AS firstFacebookResolution 
 					, CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		     	     				 AS HandledTime
 					, CH.dialDuration				  				    	     			     				 AS responseTime
 					, CH.SentimentalScore				
                     , CASE WHEN t_D.DispositionCategory = 6 THEN 1 ELSE 0 END                                    AS IsAbandoned     
                     , CASE WHEN CH.Duration	is not null then Duration else 0 end			 				 AS chatduration
    			FROM 		tb_FacebookHistory 			CH
    			LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
    	 		LEFT JOIN tb_User					U			ON 	U.UserID				= CH.queueId
    	 		LEFT JOIN temp_queueIds 			t_A 		ON 	U.UserID 			    = t_A.queueId 
    			WHERE 	CH.domainId 			= p_domainId 		
    		  	AND 	CH.IsInBound			= 1
    			AND 	CH.sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
				 AND 	(IFNULL(p_queueId,'') = '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));
              
			
              
              SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              
                  DROP TEMPORARY TABLE IF EXISTS temp_facebookHistory_calc_cur; 
      					CREATE TEMPORARY TABLE temp_facebookHistory_calc_cur AS 	     
    					SELECT 	
    						t_SH.sessionStartTime,
                            cast(from_unixtime(sessionStartTime/1000) as datetime),
    						t_SH.FacebookHistoryId,
						
    						t_SH.queueId,
    					 	t_SH.responseTime,
    					 	t_SH.missedFacebook,
    						t_SH.IsInBound,
    						t_SH.Istransferred,
    						t_SH.dispositionId,
    					 	t_SH.FacebookDuration,
    						SUM(t_SH.afterFacebookWorkTime) 														AS afterFacebookWorkTime,
    					
    						t_SH.SentimentalScore,									
    						COUNT(t_SH.queueId) 																	AS InteractionwithAgent,
    						COUNT(DISTINCT t_SH.customerFacebookId)													AS InteractionWithCustomer,
    						t_SH.discarded 																			AS discardedFacebook,
    						t_SH.IsAbandoned,									
    						SUM(t_SH.chatduration) 																	AS totalChatduration,
    						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
    					FROM temp_FacebookHistory t_SH
                        WHERE sessionStartTime between v_CurrentStartTmpstmp and v_CurrentEndTmpstmp 
    					GROUP BY  t_SH.sessionStartTime ,t_SH.FacebookHistoryId ,t_SH.queueId ,t_SH.missedFacebook ,t_SH.IsInBound,
    						t_SH.Istransferred, t_SH.dispositionId, t_SH.FacebookDuration, t_SH.SentimentalScore, t_SH.responseTime,
                            t_SH.discarded, t_SH.IsAbandoned;
                            
				
                            
						 DROP TEMPORARY TABLE IF EXISTS temp_facebookHistory_calc_pre; 
      					CREATE TEMPORARY TABLE temp_facebookHistory_calc_pre AS 
                        SELECT 	
    						t_SH.sessionStartTime,
                            cast(from_unixtime(sessionStartTime/1000) as datetime),
    						t_SH.FacebookHistoryId,
						
    						t_SH.queueId,
    					 	t_SH.responseTime,
    					 	t_SH.missedFacebook,
    						t_SH.IsInBound,
    						t_SH.Istransferred,
    						t_SH.dispositionId,
    					 	t_SH.FacebookDuration,
    						SUM(t_SH.afterFacebookWorkTime) 														AS afterFacebookWorkTime,
    					
    						t_SH.SentimentalScore,									
    						COUNT(t_SH.queueId) 																	AS InteractionwithAgent,
    						COUNT(DISTINCT t_SH.customerFacebookId)													AS InteractionWithCustomer,
    						t_SH.discarded 																			AS discardedFacebook,
    						t_SH.IsAbandoned,									
    						SUM(t_SH.chatduration) 																	AS totalChatduration,
    						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
    					FROM temp_FacebookHistory t_SH
                        WHERE sessionStartTime between v_PrevStartTmpstmp and v_PrevEndTmpstmp 
    					GROUP BY  t_SH.sessionStartTime ,t_SH.FacebookHistoryId ,t_SH.queueId ,t_SH.missedFacebook ,t_SH.IsInBound,
    						t_SH.Istransferred, t_SH.dispositionId, t_SH.FacebookDuration, t_SH.SentimentalScore, t_SH.responseTime,
                            t_SH.discarded, t_SH.IsAbandoned;	     
    					
					
                     
                            
			SELECT 	COUNT(FacebookHistoryId), count(case when responseTime > 0 then 1 end), count(case when IsAbandoned >0 then 1 end)
            INTO 	v_PrevTotalCount, v_PrevRespondedCount, v_PrevAbandonedCount 
      		FROM	temp_facebookHistory_calc_pre;
            
	
             
            SELECT 	COUNT(FacebookHistoryId), count(case when responseTime > 0 and responseTime IS NOT NULL then 1 end), count(case when IsAbandoned > 0 then 1 end),  
					SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent),
                    sum(avgChatduration),sum(totalChatduration)
            INTO 	v_curTotalCount, v_CurrentRespondedCount, v_CurrentAbandonedCount,
					v_CurrentTransferredCount, v_CurrentCustomerFacebookCount, v_CurrentAgentFacebookCount,
                    v_CurrentAverageChatdurationCount, v_TotalChatDuration
      		FROM	temp_facebookHistory_calc_cur;   
            
            
            	SELECT * FROM temp_AllqueueId;
                
                
				
                SET v_PrevTotalCount 	= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
        		SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
        		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end; 
        			
        	 	SET v_DiffTotalPercent 		= CASE WHEN  v_PrevTotalCount != 0 THEN ((v_CurTotalCount - v_PrevTotalCount) /  v_PrevTotalCount) * 100 ELSE 0 END;
        	 	SET	v_DiffRespondedPercent	= CASE WHEN   v_PrevRespondedCount !=0 THEN ((v_CurrentRespondedCount - v_PrevRespondedCount) /  v_PrevRespondedCount) * 100 ELSE 0 END; 
        		SET	v_DiffAbandonedPercent	= CASE WHEN  v_PrevAbandonedCount  !=0 THEN ((v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount) * 100 ELSE 0 end; 
    
 
                       SELECT 	IFNULL(v_CurTotalCount,0) 		    AS 'TotalReceivedCount',
             			IFNULL(v_DiffTotalPercent,0) 				AS 'DiffTotalReceivedPercent',
             			IFNULL(v_CurrentRespondedCount,0) 			AS 'CurrentAnsweredeCount',
             			IFNULL(v_DiffRespondedPercent,0) 			AS 'DiffAnsweredPercent',
             			IFNULL(v_CurrentAbandonedCount,0) 			AS 'CurrentAbandonedCount',
             			IFNULL(v_DiffAbandonedPercent,0) 			AS 'DiffAbandonedPercent';	
        
            
               SELECT
               	'All Queue'																						AS queueName                
 			    ,IFNULL(v_CurTotalCount,0)                                    									AS receivedchats
				,IFNULL(v_CurrentRespondedCount,0)                            									AS responseTime
                ,IFNULL(v_CurrentAbandonedCount,0)                                                              AS abondedchats
				,IFNULL(v_CurrentMissedCount,0)                               									AS MissedChat
                ,IFNULL(v_CurrentTransferredCount,0)                          									AS transferredchat
                ,IFNULL(v_TotalChatDuration,0)                   									            AS totalChatduration
                ,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS avgChatduration
                ,IFNULL(v_CurrentCustomerFacebookCount,0)								    					AS interactionfromcustomer
                ,IFNULL(v_CurrentAgentFacebookCount,0)															AS interactionfromagent
                ,IFNULL(v_CurrentCustomerFacebookCount,0) + IFNULL(v_CurrentAgentFacebookCount,0)				AS totalinteraction
    
            UNION ALL
         	SELECT 	U.queueName														    						AS queueName        
    			 ,	COUNT(1)														    					   	AS receivedchats
    			 ,	COUNT(case when CDH.responseTime > 0 then 1 END) 			    							AS responseTime
                 ,  COUNT(case when CDH.IsAbandoned >0 then 1 END)                                              AS abondedchats
                 ,	SUM(CDH.missedFacebook)																		AS MissedChat  
                 ,	SUM(CDH.Istransferred)																		AS transferredchat
                 ,	sum(CDH.totalChatduration)																    AS totalChatduration
                ,	sum(CDH.avgChatduration) / COUNT(1)														    AS avgChatduration
                 ,	SUM(CDH.InteractionWithCustomer)															AS interactionfromcustomer
                 ,	SUM(CDH.InteractionwithAgent)																AS interactionfromagent
                 ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						    AS totalinteraction
                 
			FROM 	temp_facebookHistory_calc_cur 	  CDH
             JOIN 	temp_AllqueueId				U	ON CDH.queueId	= U.qid	
             WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
             GROUP BY U.queueName;   
              
             
              
              
           
					
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Facebook_Servicelevel_Analysis_Metrics_Filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Facebook_Servicelevel_Analysis_Metrics_Filter`(
		p_startTmpstmp 		BIGINT,
		p_endTmpstmp 		BIGINT,
		p_domainId 			INT,
		p_queueId 			TEXT,
		p_offset 			INT,
		p_limit 		    INT	
)
begin


			DECLARE v_offset 					INT;	  	
			DECLARE v_CurrentStartTmpstmp 		BIGINT;
			DECLARE v_CurrentEndTmpstmp 		BIGINT;
			DECLARE v_PrevStartTmpstmp 			BIGINT;
			DECLARE v_PrevEndTmpstmp 			BIGINT; 
			DECLARE v_TmpstmpInterval			BIGINT;	
			DECLARE v_CurTotalCount 				INT;        
			DECLARE  v_PrevTotalCount 			INT;                    
			DECLARE v_DiffTotalPercent 			INT;     
			DECLARE  v_CurTotalSLA                 INT; 
			DECLARE  v_PrevTotalSLA             	INT; 
			DECLARE  v_DiffTotalSLAPercent      	INT; 
			DECLARE v_PretotalDurationCount         INT;
			DECLARE v_CurrenttotalDurationCount     INT;  
			DECLARE  v_CurTotalSLA1               INT; 
			DECLARE  v_PrevTotalSLA1               INT; 
			DECLARE  v_DiffTotalSLA1Percent        INT; 
			DECLARE  v_CurMissedCalls             INT; 
			DECLARE  v_PrevMissedCalls            INT; 
			DECLARE  v_DiffMissedChatsPercent     INT; 
   		    DECLARE  v_CurSLA1               		INT; 
			DECLARE  v_PrevSLA1              		INT; 
			DECLARE  v_DiffSLA1Percent       		INT; 
            DECLARE  v_CurSLA2               		INT; 
			DECLARE  v_PrevSLA2              		INT; 
			DECLARE  v_DiffSLA2Percent       		INT;  
			DECLARE  v_CurSLA3               		INT; 
			DECLARE  v_PrevSLA3              		INT; 
			DECLARE  v_DiffSLA3Percent       		INT;  
   		    DECLARE  v_CurSLA4               		INT; 
			DECLARE  v_PrevSLA4              		INT; 
			DECLARE  v_DiffSLA4Percent       		INT;  
   		    DECLARE  v_CurSLA5               		INT; 
			DECLARE  v_PrevSLA5              		INT; 
			DECLARE  v_DiffSLA5Percent       		INT;    
			DECLARE  v_CurSLA6               	INT; 
			DECLARE  v_PrevSLA6              		INT; 
			DECLARE  v_DiffSLA6Percent       		INT; 
			DECLARE  v_CuransweredSLACount       INT; 
			DECLARE  v_PrevansweredSLACount       		INT; 
			DECLARE  v_DiffansweredSLAPercent    		INT; 
			DECLARE  v_CurabandonedSLACount      		DECIMAL; 
			DECLARE  v_PrevabandonedSLACount      		INT; 
			DECLARE  v_DiffabandonedSLAPercent    		INT; 
			DECLARE  v_CurSLAbreachedCount       		INT; 
			DECLARE  v_PrevSLAbreachedCount       		INT; 
			DECLARE  v_DiffSLAbreachedPercent     		INT; 
			DECLARE  v_CurCallTypeCount                 INT; 
			DECLARE  v_PrevCallTypeCount               	INT; 
			DECLARE  v_DiffCallTypePercent             	INT;  
   		    DECLARE  v_CurOverdueCount                 	INT;  
            DECLARE  v_TotalCurrentData             	INT;
            
			SET v_offset =  p_Limit * p_offset; 
            
            	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
            	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
            	
          	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          
          	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            
            
            		
 			DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	
            CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
 			CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
              
			
            
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
			
            DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
			CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
            
   
              
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      		
            DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	
            CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
      
      
       		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                        		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
                                
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
                        				WHEN dispositionName = 'Disconnected'         THEN 4
                 					    WHEN dispositionName = 'Resolved'             THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;
                                
                      
                                
				DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory; 
				CREATE TEMPORARY TABLE temp_FacebookHistory AS 	    	
           		SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		              AS SessionDate
           					,U.UserID                                                                 AS queueId
           				 	,U.UserName													      		  AS queueName     
 							,SH.FacebookHistoryId
							,SH.sessionStartTime
   							,SH.dialDuration                                                           AS dialDuration   
   							,SH.Duration												      	       AS Duration
 							,SH.IsMissed                                                         	   AS IsMissedCall
 							,SH.IsInBound	                                                   		   AS IsAbandoned
                        	FROM 	tb_FacebookHistory 				SH
                    	 	LEFT JOIN 	tb_User					U	ON SH.queueId			= U.UserID  
        					LEFT JOIN 	temp_queueIds 			t_A ON SH.queueId		    = t_A.queueId  
							LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
							LEFT JOIN 	disposition_status		DS	ON DS.did			    = SH.dispositionId AND DS.domainId = SH.domainId
                        	WHERE 	SH.domainId 		= p_domainId		
        					AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
         				    AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
                            
			
            
            		DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_calc;   
                       	CREATE TEMPORARY TABLE temp_FacebookHistory_calc AS 	     
   						SELECT 
   							a.SessionDate AS `Date`,
   						 	a.queueId,
   						 	a.queueName,
   							a.FacebookHistoryId,
   							a.sessionStartTime,
   							SUM(CASE WHEN a.IsMissedCall = 0 AND a.IsAbandoned = 0 THEN 1 ELSE 0 END)              				AS Answered,
   							SUM(CASE WHEN a.IsAbandoned = 1 THEN 1 ELSE 0 END) 													AS Abandoned,
   							SUM(CASE WHEN a.IsMissedCall = 1 AND a.IsAbandoned = 0 THEN 1 ELSE 0 END) 							AS MissedCall,
                               a.IsMissedCall,
                               a.IsAbandoned,																					
   							SUM(a.Duration) 																					AS totalDuration,
   							SUM(CASE WHEN a.dialDuration BETWEEN 1 AND 5 THEN 1 ELSE 0 END) 									AS SL1,
   							SUM(CASE WHEN a.dialDuration BETWEEN 6 AND 10 THEN 1 ELSE 0 END) 									AS SL2,
   							SUM(CASE WHEN a.dialDuration BETWEEN 11 AND 15 THEN 1 ELSE 0 END) 									AS SL3,
   							SUM(CASE WHEN a.dialDuration BETWEEN 16 AND 20 THEN 1 ELSE 0 END) 									AS SL4,
   							SUM(CASE WHEN a.dialDuration BETWEEN 21 AND 25 THEN 1 ELSE 0 END) 									AS SL5,
   							SUM(CASE WHEN a.dialDuration BETWEEN 26 AND 30 THEN 1 ELSE 0 END) 									AS SL6,
   							SUM(CASE WHEN a.dialDuration BETWEEN 1 AND 30 THEN 1 ELSE 0 END) 									AS TotalSLA
   						FROM temp_FacebookHistory a
   						GROUP BY a.SessionDate,a.queueId,a.queueName,a.FacebookHistoryId,a.sessionStartTime,a.IsAbandoned,a.IsMissedCall; 
                        

                        
						DROP TEMPORARY TABLE IF EXISTS temp_FacebookHistory_calc1; 
                       	CREATE TEMPORARY TABLE temp_FacebookHistory_calc1 AS 	     
                       	SELECT 	
   							  a.Date 				       										                                                       
          						 ,a.queueId
          						 ,a.queueName														
                                ,(a.Answered+a.Abandoned) 													AS CallType          
                                , Abandoned																	AS ReceivedChats
                                ,a.FacebookHistoryId
                                ,a.sessionStartTime
                                 ,  a.IsAbandoned																					
    						     , a.totalDuration
                                ,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 													  AS TotalSLA1
                                , a.TotalSLA
                                , a.MissedCall       
    							 ,SUM(CASE WHEN (a.TotalSLA + a.MissedCall) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedCall)) * 10 END)                      AS answeredSLA
                                ,SUM(CASE WHEN (a.TotalSLA + a.MissedCall) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedCall) * 100) END   )                AS abandonedSLA
                                ,SUM(CASE WHEN (a.TotalSLA + a.MissedCall) = 0 THEN 1  ELSE (a.MissedCall / (a.TotalSLA + a.MissedCall)) * 100 END  )              AS SLAbreached
                              FROM temp_FacebookHistory_calc    a 
                               GROUP BY a.Date
                               ,a.queueId
                               ,a.queueName
                               ,a.sessionStartTime
                               ,a.FacebookHistoryId
                               ,a.IsAbandoned
                               ,a.totalDuration
                               ,a.TotalSLA
                               ,a.MissedCall
                               ,a.Answered
                               ,a.Abandoned ;  
                               
		SELECT  COUNT(FacebookHistoryId),	SUM(TotalSLA1), SUM(MissedCall),sum(CallType)              														                     				 
         INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedCalls,v_CurCallTypeCount                           														                      					
         FROM 	temp_FacebookHistory_calc1
         WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
         
		SELECT 	COUNT(FacebookHistoryId),SUM(TotalSLA1), SUM(MissedCall),sum(CallType)                       																								 
     	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedCalls,v_PrevCallTypeCount                                 														 										
     	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
		SELECT 	SUM(IFNULL(answeredSLA, 0))
     	INTO 	v_PrevansweredSLACount 
     	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
        SELECT 	SUM(IFNULL(totalDuration, 0))
     	INTO 	v_CurrenttotalDurationCount 
    	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
     
     
     	SELECT 	SUM(answeredSLA)/SUM(ReceivedChats) END
     	INTO 	v_CuransweredSLACount 
		FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
     
        
     
      	SELECT 	SUM(IFNULL(abandonedSLA, 0))
     	INTO 	v_PrevabandonedSLACount 
     	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     
      	SELECT 	SUM(abandonedSLA)/SUM(ReceivedChats)
     	INTO 	v_CurabandonedSLACount 
		FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
       
       
      
      
    	SELECT 	SUM(IFNULL(answeredSLA, 0))
     	INTO 	v_PrevSLAbreachedCount 
     	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     
      	SELECT 	100-(SUM(answeredSLA)/SUM(ReceivedChats))
     	INTO 	v_CurSLAbreachedCount 
    	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
       
    	SELECT 	SUM(IFNULL(totalDuration, 0))
     	INTO 	v_PretotalDurationCount 
    	FROM	temp_FacebookHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
        
    
    	SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
    	INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
    	FROM 	temp_FacebookHistory_calc
    	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
        
     
   	SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
   	INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
      	FROM	temp_FacebookHistory_calc
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
        
		SET v_PrevTotalCount      	=    CASE WHEN v_PrevTotalCount = 0 then null else     v_PrevTotalCount end; 
		SET v_PrevansweredSLACount 	= 	CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
     	SET v_PrevabandonedSLACount	= 	CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
		SET v_PrevSLAbreachedCount 	= 	CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
        
       SET v_DiffTotalPercent 		    = (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
    	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
   	,  v_DiffabandonedSLAPercent		= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
    	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
        
         SELECT * FROM temp_AllqueueId;
           
               	SELECT 
                IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
                IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
                IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';
  SELECT
         	  'All Queue'												   													AS queueName
    		 ,'Answered'                                                   													AS ChatType
            ,IFNULL(v_CurSLA1,0)                                          													AS SL1
            ,IFNULL(v_CurSLA2,0)                                          													AS SL2
            ,IFNULL(v_CurSLA3,0)                                          													AS SL3
            ,IFNULL(v_CurSLA4,0)                                          													AS SL4
            ,IFNULL(v_CurSLA5,0)                                          													AS SL5
            ,IFNULL(v_CurSLA6,0)                                          													AS SL6
            ,IFNULL(v_CurTotalSLA,0)                                      													AS Total
            ,IFNULL(v_CurMissedCalls,0)                                   													AS MissedChats
          ,ROUND(v_CurabandonedSLACount)																					AS SLAAchieved
   	     ,IFNULL(v_CurSLAbreachedCount,0)                                   												AS SLAbreached
                  UNION ALL
     	SELECT 	a.queueName													                                   				AS queueName
            ,   CASE WHEN   b.IsMissedCall = 1 AND b.IsAbandoned = 1  THEN 'Answered' ELSE 'Abandoned'  END     			AS ChatType   
            ,	count(b.SL1)  																								AS SL1
            ,	count(b.SL2)  																								AS SL2
    		 ,	count(b.SL3)  																								AS SL3
    		 ,	count(b.SL4)  																								AS SL4
    		 ,	count(b.SL5)  																								AS SL5
    		 ,	count(b.SL6)  																								AS SL6
            ,   sum(a.TotalSLA1)																							AS Total
            ,   count(a.MissedCall)																							AS MissedChats
         
            , ROUND(SUM(a.answeredSLA)/SUM(a.ReceivedChats))																	AS SLAAchieved
            , ROUND(100-IFNULL((SUM(a.answeredSLA)/SUM(a.ReceivedChats)),0))													AS SLAbreached
            FROM temp_FacebookHistory_calc b
            JOIN temp_FacebookHistory_calc1 a     ON b.FacebookHistoryId= a.FacebookHistoryId
    		 JOIN 	temp_AllqueueId		U	   ON b.queueId	= U.qid	
    	 
            GROUP BY a.queueName,a.CallType,b.Abandoned,b.Answered,b.IsMissedCall,b.IsAbandoned;    
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Inboundcall_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Inboundcall_analysis_metrics_filter`(  
	 p_startTmpstmp 	BIGINT,
	 p_endTmpstmp 		BIGINT,
	 p_domainId 		INT,    	
	 p_queueId			VARCHAR(250),		
	 p_offset 			INT,
	 p_Limit 			INT	
 )
BEGIN
                              
        				DECLARE v_offset 								INT;	  	
        				DECLARE v_CurrentStartTmpstmp 					BIGINT;
        				DECLARE v_CurrentEndTmpstmp 					BIGINT;
        			
        				DECLARE v_PrevStartTmpstmp 						BIGINT;
        				DECLARE v_PrevEndTmpstmp 						BIGINT; 
        				DECLARE v_TmpstmpInterval						BIGINT;	
        		
        				DECLARE v_DiffAverageResponsePercent			INT;
        		
        				DECLARE v_DiffAverageHandledPercent				INT;  	    
        		
        				DECLARE v_CurrentMaximumHandledCount			INT;	        
        				DECLARE v_DiffMaximumHandledTimePercent			INT;    
        		
        				DECLARE v_CurrentTotalACWCount		  			INT;	        
        				DECLARE v_DiffTotalACWTimePercent	  			INT;   
   				
        				DECLARE v_CurrentAverageQueueWaitingCount		INT;	        
        				DECLARE v_DiffAverageQueueWaitingPercent		INT; 
   
        				DECLARE v_PrevaverageHoldtCount		        	INT;	
        				DECLARE v_CurrentaverageHoldtCount		    	INT;	        
        				DECLARE v_DiffaverageHoldtPercent		    	INT; 
   		
        				DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
        				DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
        
        				DECLARE v_CurrentfirstCallResolutionCount		INT;	        
        				DECLARE v_DifffirstCallResolutionPercent		INT;  
        
        				DECLARE v_CurrentSentimentalScore          		INT;
        				DECLARE v_DiffSentimentalScorePercent      		INT;      
        
        				DECLARE v_PrevAgentIdleTimeCount		      	INT;	
        				DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
        				DECLARE v_DifffirsAgentIdleTimePercent	        INT;    
        
        				DECLARE v_PreavailableCount                     bigint;
        				DECLARE v_PretotalTalkCount                     INT;
        
   					DECLARE		v_averageResponseTime             	BIGINT; 
        				DECLARE		v_averageHandledTime				BIGINT;
        				DECLARE		v_MaximumHandledTime              	BIGINT; 
        				DECLARE		v_totalACWTime						BIGINT;
        				DECLARE		v_averageHoldtime                 	BIGINT; 
        				DECLARE		v_averageQueueWaittime				BIGINT;
        				DECLARE		v_maximumQueueWaittime            	BIGINT; 
        				DECLARE		v_occupancyRate       				DECIMAL(20,4);
        				DECLARE		v_firstCallResolution             	BIGINT; 
        				DECLARE		v_CustomerSatisfaction				BIGINT; 
        				DECLARE		v_inboundCalls						BIGINT; 
        				DECLARE		v_callDuration						BIGINT; 
        				DECLARE		v_afterCallWorkTime					INT; 
        				DECLARE		v_availableTime						BIGINT; 
        				DECLARE		v_currentResponseTime				BIGINT; 
        				DECLARE		v_previousResponseTime				BIGINT; 
						DECLARE		v_currentHandledTime				BIGINT; 
        				DECLARE		v_previousHandledTime				BIGINT; 
        				DECLARE		v_currentTotalAnsweredCalls			INT; 
        				DECLARE		v_previousTotalAnsweredCalls		INT; 
   					DECLARE       v_count							INT;
   					DECLARE       v_answerCall						INT;
   					DECLARE       v_CurTotalCount					INT;
   					DECLARE       v_PrevTotalCount					INT;
   					DECLARE       v_CurResponseTime					INT;
   					DECLARE       v_PreResponseTime					INT;
   					DECLARE       v_CurHandledTime					INT;
   					DECLARE       v_PreHandledTime					INT;
                    
					DECLARE		v_prvcount							INT;
					DECLARE		v_prevAnswerCall					INT; 
					DECLARE		v_prevAverageResponseTime			INT;
					DECLARE		v_prevAverageHandledTime			INT;

					DECLARE v_unAnswered INT;
					DECLARE v_abandoned INT;
					DECLARE v_transferedCall INT;
					DECLARE v_totalTalkTime INT;
					DECLARE v_waitDuration INT;
					DECLARE v_answeredCall INT;
					DECLARE v_DiffTotalPercent INT;
					DECLARE v_DiffAnsweredPercent INT;
					DECLARE v_prevUnAnswered INT;
					DECLARE v_DiffUnAnsweredPercent INT;
   					
   					DECLARE v_missedCallCount INT;
   					DECLARE v_DiffAbandonedPercent INT;
   					DECLARE v_prevAbandoned INT;
   					DECLARE v_maxCallHandlingTime INT;
   					DECLARE v_queueWaitTime INT;
        
     				SET v_offset =  p_Limit * p_offset; 
     
     				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
     				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
     
     				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
     
     				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
     				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                         		
        			
  					IF IFNULL(p_queueId,'')<>'' 
  					THEN
  						DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	CREATE TEMPORARY TABLE temp_AllqueueId(qid INT, queueName varchar(255));
  						CALL split(p_queueId,','); INSERT INTO temp_AllqueueId(qid) SELECT Items FROM tt_Split_temptable;
  					ELSE
  						DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
  						CREATE TEMPORARY TABLE temp_AllqueueId
  						SELECT 	qid, name AS queueName
  						FROM 	queue
  						WHERE 	domainId = p_domainId;
  					END IF;
                       
  					SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
  					DROP TEMPORARY TABLE IF EXISTS temp_AllagentId_dtl;	
  					CREATE TEMPORARY TABLE temp_AllagentId_dtl
  					SELECT 	UserID,UserName ,ext,domainId
  					FROM 	tb_User 
  					WHERE 	domainId = p_domainId; 
                       
        				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                   	
        				DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
        				CREATE TEMPORARY TABLE temp_FirstCallResolution
     					SELECT 	SlNo AS FirstCallResolution,
    							SubQuery.AgentId,SubQuery.CallHistoryId
       					FROM (
       					SELECT ROW_NUMBER() OVER(PARTITION BY SH.CallHistoryId ORDER BY SDH.CallDurationHistoryId) AS SlNo,
    						SDH.AgentId,SH.CallHistoryId
    						FROM tb_CallHistory 		SH
    						JOIN tb_CallDurationHistory	SDH	    ON SH.CallHistoryId 		= SDH.CallHistoryId
    						JOIN disposition_status DS ON DS.did = SDH.dispositionId
    						WHERE SDH.IsBot = 0
    						AND SH.domainId = p_domainId
    						AND SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
    						AND	DS.dispositionName <> 'Transferred'
    						AND	SH.IsInBound = 1
                            AND SDH.AgentId IS NOT NULL	
          				) AS SubQuery
          				WHERE SlNo = 1;
                       
                       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
        				DROP TEMPORARY TABLE IF EXISTS tt_CallHistory;
                       CREATE TEMPORARY TABLE tt_CallHistory AS 	    	
        				SELECT 	SH.sessionStartTime
                       ,SDH.AgentId
                        ,SH.CallHistoryId
        				, SDH.QueueId 
        				, SDH.IsMissedCall
                       , SDH.dispositionId
                       , SH.IsAbandoned
        				, U.queueName												
        				, SDH.StartTime												
        				, SDH.EndTime												
        				, SH.IsInBound
        				, SH.callDuration												
        				, SDH.AgentHoldDuration										
        				, SDH.transferredTypeId																	
        				, SDH.afterCallWorkTime		
        				, SH.queueDuration											
        				, SDH.SentimentalScore
        				, SDH.IsBot
        				, t_f.FirstCallResolution 
                       , SDH.answeredDuration
                       , SDH.Duration
                       , Q.maxCallHandlingTimeMM
                       , SH.queueDuration                            										AS QueueWaitTime
        				FROM 	tb_CallHistory 				SH
        				JOIN 	tb_CallDurationHistory		SDH	ON SH.CallHistoryId 	= SDH.CallHistoryId 
						LEFT JOIN 	queue					Q 	ON Q.qid				= SDH.QueueId
        				JOIN temp_AllqueueId			U	ON U.qid				= SDH.QueueId
        				left JOIN temp_FirstCallResolution 	t_f	ON t_f.CallHistoryId 	= SDH.CallHistoryId
        				WHERE 	SH.domainId 		= p_domainId	
    				 	AND 	 SDH.IsBot			= 0      
   					AND 	 SH.IsInBound 		= 1
                      
                       AND 	SDH.QueueId <> 0
        				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ; 
   
   					DROP TEMPORARY TABLE IF EXISTS temp_CallHistory; 
   					CREATE TEMPORARY TABLE temp_CallHistory AS 	    	
   					SELECT 	CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
   					, sessionStartTime	
   					, CallHistoryId
                       , AgentId
   					, QueueId
   					, queueName												
   					, IsInBound
                       , callDuration
   					, callDuration														AS CallHandlingTime
   					, AgentHoldDuration													AS agentHoldDuration
   					, ((callDuration/1000)+afterCallWorkTime)							AS Handled                                 
                       , answeredDuration													AS responseTime
   					, afterCallWorkTime		
   					, queueDuration														AS queueWaitingtime
   					, SentimentalScore
   					, case when IsInBound = 1 then 1 else 0 end 						AS inboundCalls   
   					, FirstCallResolution 												AS firstCallResolution
   					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      					AS respondedCall
   					,CASE WHEN IFNULL(Duration,0) > 0 THEN 1 ELSE 0 END      			AS answeredCall
                       , CASE WHEN IFNULL(Duration,0) = 0  THEN 1 ELSE 0 END				AS unAnswered
                       , CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                       ,CASE WHEN transferredTypeId = 2002002 THEN 1 ELSE 0 END 			AS transferedCall
                       ,CASE WHEN Duration > 0  THEN Duration ELSE 0 END 					AS totalTalkTime
                       ,CASE WHEN QueueWaitTime > 0  THEN QueueWaitTime ELSE 0 END 		AS queueWaitTime
                       ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
                       ,CASE WHEN IsMissedCall = 1 THEN 1 ELSE 0 END						AS missedCallCount
                       ,CASE WHEN maxCallHandlingTimeMM > 0  THEN maxCallHandlingTimeMM * 60000 ELSE 0 END AS maxCallHandlingTime
   					FROM 	tt_CallHistory 				
   					WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ; 
                                       
                     DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_prev; 
        				CREATE TEMPORARY TABLE temp_CallHistory_prev AS 	    	
        				SELECT 	CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
   					, sessionStartTime	
   					, CallHistoryId
                       , AgentId
   					, QueueId
   					, queueName												
   					, IsInBound
                       , callDuration
   					, callDuration											AS CallHandlingTime
   					, AgentHoldDuration										AS agentHoldDuration
   					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                       , answeredDuration										AS responseTime
   					, afterCallWorkTime		
   					, queueDuration											AS queueWaitingtime
   					, SentimentalScore
   					, case when IsInBound = 1 then 1 else 0 end 				AS inboundCalls   
   					, FirstCallResolution 										AS firstCallResolution
   					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      			AS respondedCall
   					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      				AS answeredCall
                       ,CASE WHEN answeredDuration IS NULL THEN 1 ELSE 0 END				AS unAnswered
                       ,CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                       ,CASE WHEN transferredTypeId = 2002002 THEN 1 ELSE 0 END 			AS transferedCall
                       ,CASE WHEN callDuration > 0  THEN callDuration ELSE 0 END 			AS totalTalkTime
                       ,CASE WHEN QueueWaitTime > 0  THEN QueueWaitTime ELSE 0 END 		AS queueWaitTime
                       ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
                       ,CASE WHEN IsMissedCall = 1 THEN 1 ELSE 0 END						AS missedCallCount
                       ,CASE WHEN maxCallHandlingTimeMM > 0  THEN maxCallHandlingTimeMM * 60000 ELSE 0 END AS maxCallHandlingTime
   					FROM 	tt_CallHistory 				
   					WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ; 
                 
   			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc; 
   			CREATE TEMPORARY TABLE temp_CallHistory_calc AS 	     
   			SELECT 	
   			count(1)                             																			AS NoOfcalls
               , t_SH.AgentId	
   			, t_SH.QueueId
   			, t_SH.SessionDate
   			, t_SH.queueName																              						
   			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
   			, SUM(t_SH.Handled)																									AS averageHandledTime    
   			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
   			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
   			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
   			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
   			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
   			, t_SH.firstcallResolution
   			, sum(t_SH.inboundCalls)                          																	AS inboundCalls
   			, t_SH.SentimentalScore																								AS CustomerSatisfaction
   			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
   			, sum(t_SH.callDuration)																							AS callDuration	
   			, sum(t_SH.respondedcall)																							AS respondedcall
   			,sum(t_SH.answeredCall)																								AS answeredCall               
   			,sum(t_SH.unAnswered)																								AS unAnswered               
   			,sum(t_SH.abandoned)																								AS abandoned               
   			,sum(t_SH.transferedCall)																							AS transferedCall               
   			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
   			,sum(t_SH.waitDuration)																								AS waitDuration               
               ,sum(t_SH.missedCallCount)																							AS missedCallCount
               ,sum(queueWaitTime)																									AS queueWaitTime
               ,CASE WHEN SUM(t_SH.totalTalkTime) > SUM(t_SH.maxCallHandlingTime) THEN 1 ELSE 0 END 								AS maxCallHandlingTime
   			FROM 	temp_CallHistory t_SH
   			GROUP BY t_SH.SessionDate, t_SH.queueName, t_SH.QueueId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration,t_SH.AgentId;    
                   
   		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev; 
   		CREATE TEMPORARY TABLE temp_CallHistory_calc_prev AS 	     
   		SELECT 	
   			count(1)                             																			AS NoOfcalls,
   			t_SH.QueueId
               , t_SH.AgentId
   			, t_SH.SessionDate
   			, t_SH.queueName																              						AS queueName
   			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
   			, SUM(t_SH.Handled)																									AS averageHandledTime    
   			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
   			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
   			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
   			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
   			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
   			, t_SH.firstcallResolution
   			, sum(t_SH.inboundCalls)                          																	AS inboundCalls
   			, t_SH.SentimentalScore																								AS CustomerSatisfaction
   			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
   			, sum(t_SH.callDuration)																							AS callDuration	
   			, sum(t_SH.respondedcall)																							AS respondedcall
   			,sum(t_SH.answeredCall)																								AS answeredCall               
   			,sum(t_SH.unAnswered)																								AS unAnswered               
   			,sum(t_SH.abandoned)																								AS abandoned               
   			,sum(t_SH.transferedCall)																							AS transferedCall               
   			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
   			,sum(t_SH.waitDuration)																								AS waitDuration               
               ,sum(t_SH.missedCallCount)																							AS missedCallCount
               ,sum(queueWaitTime)																									AS queueWaitTime
               ,CASE WHEN SUM(t_SH.totalTalkTime) > SUM(t_SH.maxCallHandlingTime) THEN 1 ELSE 0 END								AS maxCallHandlingTime
   			FROM 	temp_CallHistory_prev t_SH
   			GROUP BY t_SH.SessionDate, t_SH.queueName, t_SH.QueueId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration,t_SH.AgentId;
                             
        				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
        				CREATE TEMPORARY TABLE temp_AvailableStates AS
        				SELECT   
        					CASE 
        						WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
        						ELSE 2 
        					END AS tt_Time,
        					ST.ext,
        					ST.domainId,
        					from_unixtime(ST.startTimestamp/1000),
        					ST.stateDuration as SD
        				FROM     state_timer ST 
        				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
        				WHERE    ST.domainId = p_domainId
        				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
        						
        				ALTER TABLE temp_CallHistory_calc ADD COLUMN availableTime BIGINT;
        					  
        				UPDATE temp_CallHistory_calc SH_C
        				JOIN temp_AllagentId_dtl t_A ON SH_C.agentId = t_A.UserID
        				JOIN (
        				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
        				FROM temp_AvailableStates
        				GROUP BY ext, domainId
        				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
        				SET SH_C.availableTime 	= tt_AV.total_SD;
   
        				SELECT sum(firstCallResolution),SUM(CustomerSatisfaction)
        				INTO 	v_CurrentfirstCallResolutionCount,v_CurrentSentimentalScore
        				FROM 	temp_CallHistory_calc ;                                                            
      
        				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_1;
        				CREATE TEMPORARY TABLE temp_CallHistory_calc_1 AS
        					SELECT 															
        			 	 a.QueueId																                                                  AS QueueId
                        ,sum(a.NoOfCalls) as NoOfCalls
   					,sum(a.averageResponseTime)  																			  		  			  AS averageResponseTime
   					,sum(a.averageHandledTime)			                                                              			  				  AS averageHandledTime
        				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
        				,sum(a.totalACWTime)          																							  AS totalACWTime
        				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               							  AS averageHoldtime                                  
        				,sum(a.averageQueueWaitingtime)                                                                           				  AS averageQueueWaittime
        				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime

        				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
        				,sum(a.inboundCalls)																									  AS inboundCalls
        				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
        				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
        				,sum(a.callDuration)																									  AS callDuration
        				,sum(a.availableTime)																									  AS availableTime
						,sum(respondedCall)  																									  AS respondedCall
						,sum(answeredCall)																										  AS answeredCall
                       ,sum(unAnswered)      																									AS unAnswered
                       ,sum(abandoned)       																									AS abandoned
                       ,sum(transferedCall)  																									AS transferedCall
                       ,sum(totalTalkTime)   																									AS totalTalkTime
                       ,sum(waitDuration)    																									AS waitDuration
                       ,sum(missedCallCount)																									AS missedCallCount
                       ,sum(maxCallHandlingTime)																								AS maxCallHandlingTime
                       ,sum(queueWaitTime)																										AS queueWaitTime
        			FROM 	temp_CallHistory_calc 	    a
        			 GROUP BY a.QueueId;   	
                               
                 DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev_1;
        				CREATE TEMPORARY TABLE temp_CallHistory_calc_prev_1 AS
        				SELECT a.QueueId		
                        ,sum(NoOfCalls)   as NoOfCalls
   					,sum(a.averageResponseTime)   																			  AS averageResponseTime
   					,sum(a.averageHandledTime)					                                                              AS averageHandledTime
        				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
        				,sum(a.totalACWTime)          																							  AS totalACWTime
        				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               				AS averageHoldtime                                  
        				,sum(a.averageQueueWaitingtime)                                                                           AS averageQueueWaittime
        				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
        				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
        				,sum(a.inboundCalls)																									  AS inboundCalls
        				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
        				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
        				,sum(a.callDuration)																									  AS callDuration
                      ,sum(respondedCall)  as respondedCall
   					,sum(answeredCall)																										AS answeredCall
                       ,sum(unAnswered)      																									AS unAnswered
                       ,sum(abandoned)       																									AS abandoned
                       ,sum(transferedCall)  																									AS transferedCall
                       ,sum(totalTalkTime)   																									AS totalTalkTime
                       ,sum(waitDuration)    																									AS waitDuration
                       ,sum(missedCallCount)																									AS missedCallCount
                       ,sum(maxCallHandlingTime)																								AS maxCallHandlingTime
                       ,sum(queueWaitTime)																										AS queueWaitTime
        			FROM 	temp_CallHistory_calc_prev 	a
        			GROUP BY a.QueueId;   	
   				        
				select  
				sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
				sum(averageQueueWaittime), sum(maximumQueueWaittime),IFNULL(SUM((callDuration + (afterCallWorkTime * 1000)) / availableTime *100),0), sum(firstCallResolution), sum(CustomerSatisfaction),sum(inboundCalls),
				sum(callDuration),sum(afterCallWorkTime),sum(availableTime),sum(answeredCall),sum(unAnswered),sum(abandoned),sum(transferedCall),sum(totalTalkTime),sum(waitDuration),sum(missedCallCount)
			   ,sum(maxCallHandlingTime),sum(queueWaitTime)
				INTO
				v_count,v_answerCall, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
				v_averageQueueWaittime, v_maximumQueueWaittime, v_occupancyRate, v_firstCallResolution, v_CustomerSatisfaction,v_inboundCalls,
				v_callDuration,v_afterCallWorkTime,v_availableTime,v_answeredCall,v_unAnswered,v_abandoned,v_transferedCall,v_totalTalkTime,v_waitDuration,v_missedCallCount
			   ,v_maxCallHandlingTime,v_queueWaitTime
				FROM temp_CallHistory_calc_1;  
                 
   				select sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(unAnswered),sum(abandoned) 
        			INTO v_prvcount,v_prevAnswerCall, v_prevAverageResponseTime, v_prevAverageHandledTime , v_prevUnAnswered,v_prevAbandoned
        			FROM temp_CallHistory_calc_prev_1; 
   
   			SELECT * FROM temp_AllqueueId;  
   
   			SET v_DiffTotalPercent 		= ((v_count - ifnull(v_prvcount,0)) / IF(IFNULL(v_prvcount,0)=0,1,v_prvcount)) * 100 
               ,	v_DiffAnsweredPercent	= ((v_answeredCall - ifnull(v_prevAnswerCall,0)) / IF(IFNULL(v_prevAnswerCall,0)=0,1,v_prevAnswerCall)) * 100
   			,	v_DiffAbandonedPercent	= (IFNULL(v_abandoned,0) - v_prevAbandoned) / IF(IFNULL(v_prevAbandoned,0)=0,1,v_prevAbandoned) * 100;  
   
     			SELECT 	IFNULL(v_count,0) 											AS 'CurrentInboundcalls',
     					IFNULL(v_DiffTotalPercent,0) 		        				AS 'DiffTotalPercent',
     					IFNULL(v_answeredCall,0) 			    					AS 'CurrentAnsweredeCount',
     					IFNULL(v_DiffAnsweredPercent,0) 							AS 'DiffAnsweredPercent',
     					IFNULL(v_abandoned,0) 										AS 'CurrentAbandonedCount',
     					IFNULL(v_DiffAbandonedPercent,0) 							AS 'DiffAbandonedPercent';                        
               
                    
				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_2;
                CREATE TEMPORARY TABLE temp_CallHistory_calc_2
                SELECT * FROM temp_CallHistory_calc_1;
                    
				SELECT 	'All Queue' 												AS queueName,
					SUM(NoOfcalls)														AS inboundcalls, 
   					SUM(answeredCall)													AS answeredCalls,
					SUM(missedCallCount)													AS missedCalls,
   					SUM(abandoned)														AS abandonedCalls,
   					SUM(transferedCall)													AS transferredCalls,
   					SUM(totalTalkTime)													AS talktime,
   					SUM(waitDuration/NoOfcalls)											AS avgSpeedofAnswer,
   					SUM((averageHandledTime/NoOfCalls) * 1000)                           AS maximumHandleTime, 
   					SUM(MaximumHandledTime)                                             	AS maximumHandleTime, 
   					SUM(averageHoldtime)                                                	AS  averageHoldTime, 
					SUM(IFNULL(((callDuration + (afterCallWorkTime * 1000)) / availableTime *100),0))	AS   occupancyrate,
   					SUM(afterCallWorkTime * 1000)										AS totalACWTime,
   					round(SUM(firstCallResolution/inboundCalls *100))                  	AS firstCallResolution,
   					SUM(CustomerSatisfaction)											AS customersatisfaction,
				    SUM(((maxCallHandlingTime/NoOfcalls)*100)*1000)						AS maxiumQueueWaitTime,
				    SUM(((averageQueueWaitTime/totalTalkTime))*1000)					AS averageQueueWaitTime
                FROM 	temp_CallHistory_calc_2                
                UNION ALL
				SELECT DISTINCT(CASE WHEN U.queueName IS NOT NULL THEN U.queueName ELSE '-' END)	AS  queueName, 
   					NoOfcalls														AS inboundcalls, 
   					answeredCall													AS answeredCalls,
					missedCallCount													AS missedCalls,
   					abandoned														AS abandonedCalls,
   					transferedCall													AS transferredCalls,
   					totalTalkTime													AS talktime,
   					waitDuration/NoOfcalls											AS avgSpeedofAnswer,
   					(averageHandledTime/NoOfCalls) * 1000                           AS maximumHandleTime, 
   					MaximumHandledTime                                             	AS maximumHandleTime, 
   					averageHoldtime                                                	AS  averageHoldTime, 
					IFNULL(((callDuration + (afterCallWorkTime * 1000)) / availableTime *100),0)	AS   occupancyrate,
   					afterCallWorkTime * 1000										AS totalACWTime,
   					round(firstCallResolution/inboundCalls *100 )                  	AS firstCallResolution,
   					CustomerSatisfaction											AS customersatisfaction,
				    ((maxCallHandlingTime/NoOfcalls)*100)*1000						AS maxiumQueueWaitTime,
				    ((averageQueueWaitTime/totalTalkTime))*1000						AS averageQueueWaitTime
				FROM    temp_CallHistory_calc_1 a
				LEFT JOIN 	temp_AllqueueId		U	ON a.QueueId	= U.qid;

    
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Instagram_Inbound_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Instagram_Inbound_analysis_metrics_filter`(
			p_startTmpstmp 		BIGINT,
		  	p_endTmpstmp 		BIGINT,
			p_domainId 			INT,    	
			p_queueId			TEXT,    
			p_offset 			INT,
			p_limit 			INT	
)
begin 

	DECLARE v_CurrentStartTmpstmp	BIGINT;
    DECLARE v_CurrentEndTmpstmp		BIGINT;
    DECLARE v_offset 				INT;
    DECLARE v_TmpstmpInterval		BIGINT;
    DECLARE v_PrevEndTmpstmp 		BIGINT;
    DECLARE v_PrevStartTmpstmp 		BIGINT;
    DECLARE v_PrevTotalCount        INT;
    DECLARE v_CurTotalCount			INT;
    DECLARE v_DiffTotalPercent   	INT;
    DECLARE v_CurrentTransferredCount INT;
    DECLARE v_PrevAbandonedCount	INT;
    declare v_CurrentRespondedCount INT;
    declare v_CurrentAbandonedCount INT;
    declare v_CurrentMissedCount INT;
    declare v_CurrentCustomerInstagramCount int;
    declare v_CurrentAgentInstagramCount INT;
    declare v_CurrentAverageChatdurationCount INT;
    declare v_DiffRespondedPercent INT;
 
	declare v_DiffAbandonedPercent int;
    declare v_PrevRespondedCount int;
    declare v_CurrentMaximumChatdurationCount int;
    declare v_TotalChatDuration INT;
    
    
       	SET v_offset =  p_limit * p_offset; 
         
     	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; 
	ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; 
	END IF; 
     	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; 
	ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; 
	END IF;  									
         	
       	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       
       	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
       	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
        
        
        	DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	
                CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
 		        CALL split(p_queueId,','); 
                INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
                
	 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	 DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
			CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid,`name` AS queueName  
            FROM queue
            WHERE domainId = p_domainId ;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                  	
                         
                           		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                       		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                       		(    DispositionId 			INT
                       			,DispositionStatus 		VARCHAR(100)
                       			,DispositionCategory	TINYINT
                       		); 
                               
                       		INSERT INTO temp_AvailableDisposition 
                       		SELECT 	did 	AS		DispositionId
                       			,	dispositionName AS	DispositionStatus
                       			,	CASE WHEN dispositionName = 'Opened'				THEN 2
                       				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                       				WHEN dispositionName = 'Discarded'     				THEN 4
    								    WHEN dispositionName = 'Resolved'      				THEN 5
                                     WHEN dispositionName = 'Caller Disconnected'		THEN 6
                       				END 			DispositionCategory
                       		FROM 	disposition_status   
                       		WHERE 	domainId	= p_domainId;
                             
 					
                     
					  SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    			DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
    			CREATE TEMPORARY TABLE temp_InstagramHistory AS
    		    SELECT 	CH.sessionStartTime 	
		    
		    ,	CH.InstagramHistoryId        
      			
      				,	CH.queueId
				    , CH.IsMissed																		AS missedInstagram
      				,	CH.Istransferred
      				,	CH.dispositionId
      			    ,   CH.IsInBound
      				,	(CH.sessionEndTime - CH.sessionStartTime)	                         		AS InstagramDuration
      				,	CH.customerInstagramId
      				,	CH.afterInstagramWorkTime
      				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                	 				 AS discarded
      				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                	 				 AS firstInstagramResolution 
 					, CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		     	     				 AS HandledTime
 					, CH.dialDuration				  				    	     			     				 AS responseTime
 					, CH.SentimentalScore				
                     , CASE WHEN t_D.DispositionCategory = 6 THEN 1 ELSE 0 END                                    AS IsAbandoned     
                     , CASE WHEN CH.Duration	is not null then Duration else 0 end			 				 AS chatduration
    			FROM 		tb_InstagramHistory 	as		CH
    			LEFT JOIN temp_AvailableDisposition	 as t_D			ON 	CH.dispositionId	    = t_D.DispositionId
    			LEFT JOIN tb_User			as 		U			ON 	U.UserID				= CH.queueId
    			LEFT JOIN temp_queueIds 	as		t_A 		ON 	U.UserID 			    = t_A.queueId 
    			WHERE 	CH.domainId 			= p_domainId 		
    		  	AND 	CH.IsInBound			= 1
    			AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
    			AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
                
 
                
                	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       
    		
  DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc_cur; 
      					CREATE TEMPORARY TABLE temp_InstagramHistory_calc_cur AS 	     
    					SELECT 	
    						t_SH.sessionStartTime,
                            cast(from_unixtime(sessionStartTime/1000) as datetime),
    						t_SH.InstagramHistoryId,
						
    						t_SH.queueId,
    					 	t_SH.responseTime,
    					 	t_SH.missedInstagram,
    						t_SH.IsInBound,
    						t_SH.Istransferred,
    						t_SH.dispositionId,
    					 	t_SH.InstagramDuration,
    						SUM(t_SH.afterInstagramWorkTime) 														AS afterInstagramWorkTime,
    					
    						t_SH.SentimentalScore,									
    						COUNT(t_SH.queueId) 																	AS InteractionwithAgent,
    						COUNT(DISTINCT t_SH.customerInstagramId)													AS InteractionWithCustomer,
    						t_SH.discarded 																			AS discardedInstagram,
    						t_SH.IsAbandoned,									
    						SUM(t_SH.chatduration) 																	AS totalChatduration,
    						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
    					FROM temp_InstagramHistory t_SH
                        WHERE sessionStartTime between v_CurrentStartTmpstmp and v_CurrentEndTmpstmp 
    					GROUP BY  t_SH.sessionStartTime ,t_SH.InstagramHistoryId ,t_SH.queueId ,t_SH.missedInstagram ,t_SH.IsInBound,
    						t_SH.Istransferred, t_SH.dispositionId, t_SH.InstagramDuration, t_SH.SentimentalScore, t_SH.responseTime,
                            t_SH.discarded, t_SH.IsAbandoned;
DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc_pre; 
      					CREATE TEMPORARY TABLE temp_InstagramHistory_calc_pre AS 
                        SELECT 	
    						t_SH.sessionStartTime,
                            cast(from_unixtime(sessionStartTime/1000) as datetime),
    						t_SH.InstagramHistoryId,
						
    						t_SH.queueId,
    					 	t_SH.responseTime,
    					 	t_SH.missedInstagram,
    						t_SH.IsInBound,
    						t_SH.Istransferred,
    						t_SH.dispositionId,
    					 	t_SH.InstagramDuration,
    						SUM(t_SH.afterInstagramWorkTime) 														AS afterInstagramWorkTime,
    					
    						t_SH.SentimentalScore,									
    						COUNT(t_SH.queueId) 																	AS InteractionwithAgent,
    						COUNT(DISTINCT t_SH.customerInstagramId)													AS InteractionWithCustomer,
    						t_SH.discarded 																			AS discardedInstagram,
    						t_SH.IsAbandoned,									
    						SUM(t_SH.chatduration) 																	AS totalChatduration,
    						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
    					FROM temp_InstagramHistory t_SH
                        WHERE sessionStartTime between v_PrevStartTmpstmp and v_PrevEndTmpstmp 
    					GROUP BY  t_SH.sessionStartTime ,t_SH.InstagramHistoryId ,t_SH.queueId ,t_SH.missedInstagram ,t_SH.IsInBound,
    						t_SH.Istransferred, t_SH.dispositionId, t_SH.InstagramDuration, t_SH.SentimentalScore, t_SH.responseTime,
                            t_SH.discarded, t_SH.IsAbandoned;
	SELECT 	COUNT(InstagramHistoryId), count(case when responseTime > 0 then 1 end), count(case when IsAbandoned >0 then 1 end)
            INTO 	v_PrevTotalCount, v_PrevRespondedCount, v_PrevAbandonedCount 
      		FROM	temp_InstagramHistory_calc_pre;
            
      SELECT 	COUNT(InstagramHistoryId), count(case when responseTime > 0 and responseTime IS NOT NULL then 1 end), count(case when IsAbandoned > 0 then 1 end),  
					SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent),
                    sum(avgChatduration),sum(totalChatduration)
            INTO 	v_curTotalCount, v_CurrentRespondedCount, v_CurrentAbandonedCount,
					v_CurrentTransferredCount, v_CurrentCustomerInstagramCount, v_CurrentAgentInstagramCount,
                    v_CurrentAverageChatdurationCount, v_TotalChatDuration
      		FROM	temp_InstagramHistory_calc_cur;  
    	SELECT * FROM temp_AllqueueId;
  SET v_PrevTotalCount 	= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
        		SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
        		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end; 
        			
        	 	SET v_DiffTotalPercent 		= CASE WHEN  v_PrevTotalCount != 0 THEN ((v_CurTotalCount - v_PrevTotalCount) /  v_PrevTotalCount) * 100 ELSE 0 END;
        	 	SET	v_DiffRespondedPercent	= CASE WHEN   v_PrevRespondedCount !=0 THEN ((v_CurrentRespondedCount - v_PrevRespondedCount) /  v_PrevRespondedCount) * 100 ELSE 0 END; 
        		SET	v_DiffAbandonedPercent	= CASE WHEN  v_PrevAbandonedCount  !=0 THEN ((v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount) * 100 ELSE 0 end; 
 SELECT 	IFNULL(v_CurTotalCount,0) 		    AS 'TotalReceivedCount',
             			IFNULL(v_DiffTotalPercent,0) 				AS 'DiffTotalReceivedPercent',
             			IFNULL(v_CurrentRespondedCount,0) 			AS 'CurrentAnsweredeCount',
             			IFNULL(v_DiffRespondedPercent,0) 			AS 'DiffAnsweredPercent',
             			IFNULL(v_CurrentAbandonedCount,0) 			AS 'CurrentAbandonedCount',
             			IFNULL(v_DiffAbandonedPercent,0) 			AS 'DiffAbandonedPercent';	
 SELECT
               	'All Queue'																						AS queueName                
 			    ,IFNULL(v_CurTotalCount,0)                                    									AS receivedchats
				,IFNULL(v_CurrentRespondedCount,0)                            									AS responseTime
                ,IFNULL(v_CurrentAbandonedCount,0)                                                              AS abondedchats
				,IFNULL(v_CurrentMissedCount,0)                               									AS MissedChat
                ,IFNULL(v_CurrentTransferredCount,0)                          									AS transferredchat
                ,IFNULL(v_TotalChatDuration,0)                   									            AS totalChatduration
                ,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS avgChatduration
                ,IFNULL(v_CurrentCustomerInstagramCount,0)								    					AS interactionfromcustomer
                ,IFNULL(v_CurrentAgentInstagramCount,0)															AS interactionfromagent
                ,IFNULL(v_CurrentCustomerInstagramCount,0) + IFNULL(v_CurrentAgentInstagramCount,0)				AS totalinteraction
UNION ALL
         	SELECT 	U.queueName														    						AS queueName        
    			 ,	COUNT(1)														    					   	AS receivedchats
    			 ,	COUNT(case when CDH.responseTime > 0 then 1 END) 			    							AS responseTime
                 ,  COUNT(case when CDH.IsAbandoned >0 then 1 END)                                              AS abondedchats
                 ,	SUM(CDH.missedInstagram)																		AS MissedChat  
                 ,	SUM(CDH.Istransferred)																		AS transferredchat
                 ,	sum(CDH.totalChatduration)																    AS totalChatduration
                ,	sum(CDH.avgChatduration) / COUNT(1)														    AS avgChatduration
                 ,	SUM(CDH.InteractionWithCustomer)															AS interactionfromcustomer
                 ,	SUM(CDH.InteractionwithAgent)																AS interactionfromagent
                 ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						    AS totalinteraction
                 
			FROM 	temp_InstagramHistory_calc_cur 	  CDH
             JOIN 	temp_AllqueueId				U	ON CDH.queueId	= U.qid	
             WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
             GROUP BY U.queueName;   
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Instagram_Servicelevel_Analysis_Metrics_Filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Instagram_Servicelevel_Analysis_Metrics_Filter`(
		p_startTmpstmp 		BIGINT,
		p_endTmpstmp 		BIGINT,
		p_domainId 			INT,
		p_queueId 			TEXT,
		p_offset 			INT,
		p_limit 		    INT	
)
begin


			DECLARE v_offset 					INT;	  	
			DECLARE v_CurrentStartTmpstmp 		BIGINT;
			DECLARE v_CurrentEndTmpstmp 		BIGINT;
			DECLARE v_PrevStartTmpstmp 			BIGINT;
			DECLARE v_PrevEndTmpstmp 			BIGINT; 
			DECLARE v_TmpstmpInterval			BIGINT;	
			DECLARE v_CurTotalCount 				INT;        
			DECLARE  v_PrevTotalCount 			INT;                    
			DECLARE v_DiffTotalPercent 			INT;     
			DECLARE  v_CurTotalSLA                 INT; 
			DECLARE  v_PrevTotalSLA             	INT; 
			DECLARE  v_DiffTotalSLAPercent      	INT; 
			DECLARE v_PretotalDurationCount         INT;
			DECLARE v_CurrenttotalDurationCount     INT;  
			DECLARE  v_CurTotalSLA1               INT; 
			DECLARE  v_PrevTotalSLA1               INT; 
			DECLARE  v_DiffTotalSLA1Percent        INT; 
			DECLARE  v_CurMissedCalls             INT; 
			DECLARE  v_PrevMissedCalls            INT; 
			DECLARE  v_DiffMissedChatsPercent     INT; 
   		    DECLARE  v_CurSLA1               		INT; 
			DECLARE  v_PrevSLA1              		INT; 
			DECLARE  v_DiffSLA1Percent       		INT; 
            DECLARE  v_CurSLA2               		INT; 
			DECLARE  v_PrevSLA2              		INT; 
			DECLARE  v_DiffSLA2Percent       		INT;  
			DECLARE  v_CurSLA3               		INT; 
			DECLARE  v_PrevSLA3              		INT; 
			DECLARE  v_DiffSLA3Percent       		INT;  
   		    DECLARE  v_CurSLA4               		INT; 
			DECLARE  v_PrevSLA4              		INT; 
			DECLARE  v_DiffSLA4Percent       		INT;  
   		    DECLARE  v_CurSLA5               		INT; 
			DECLARE  v_PrevSLA5              		INT; 
			DECLARE  v_DiffSLA5Percent       		INT;    
			DECLARE  v_CurSLA6               	INT; 
			DECLARE  v_PrevSLA6              		INT; 
			DECLARE  v_DiffSLA6Percent       		INT; 
			DECLARE  v_CuransweredSLACount       INT; 
			DECLARE  v_PrevansweredSLACount       		INT; 
			DECLARE  v_DiffansweredSLAPercent    		INT; 
			DECLARE  v_CurabandonedSLACount      		INT; 
			DECLARE  v_PrevabandonedSLACount      		INT; 
			DECLARE  v_DiffabandonedSLAPercent    		INT; 
			DECLARE  v_CurSLAbreachedCount       		INT; 
			DECLARE  v_PrevSLAbreachedCount       		INT; 
			DECLARE  v_DiffSLAbreachedPercent     		INT; 
			DECLARE  v_CurCallTypeCount                 INT; 
			DECLARE  v_PrevCallTypeCount               	INT; 
			DECLARE  v_DiffCallTypePercent             	INT;  
   		    	DECLARE  v_CurOverdueCount                 	INT;   
 			DECLARE  v_TotalCurrentData             	INT;
            
			SET v_offset =  p_Limit * p_offset; 
            
            	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
            	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
            	
          	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          
          	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
 			DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	
            CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
 			CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
              
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
			
            DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
			CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
              
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      		
		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	
		CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
      
      
       		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                        		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
                                
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
                        				WHEN dispositionName = 'Disconnected'         THEN 4
                 					    WHEN dispositionName = 'Resolved'             THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;
                                
				DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory; 
				CREATE TEMPORARY TABLE temp_InstagramHistory AS 	    	
           		SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		              AS SessionDate
           					,U.UserID                                                                 AS queueId
           					,U.UserName													      		  AS queueName     
 							,SH.InstagramHistoryId
							,SH.sessionStartTime
   							,SH.dialDuration                                                          AS dialDuration   
				
   							,SH.Duration												      	       AS Duration
                            
				
 							,SH.IsMissed                                                         	   AS IsMissedCall
 							,SH.IsInBound		                                                   				   AS IsAbandoned
                        	FROM 	tb_InstagramHistory 				SH
                    		LEFT JOIN 	tb_User					U	ON SH.queueId			= U.UserID  
        					LEFT JOIN 	temp_queueIds 			t_A ON SH.queueId		    = t_A.queueId  
							LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId	= t_D.DispositionId
							LEFT JOIN 	disposition_status		DS	ON DS.did			    = SH.dispositionId AND DS.domainId = SH.domainId
                        	WHERE 	SH.domainId 		= p_domainId		
        					AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
         				    AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
            
            		DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc;   
                       	CREATE TEMPORARY TABLE temp_InstagramHistory_calc AS 	     
   						SELECT 
   							a.SessionDate AS `Date`,
   							a.queueId,
   							a.queueName,
   							a.InstagramHistoryId,
   							a.sessionStartTime,
   							SUM(CASE WHEN a.IsMissedCall = 0 AND a.IsAbandoned = 0 THEN 1 ELSE 0 END)              				AS Answered,
   							SUM(CASE WHEN a.IsAbandoned = 1 THEN 1 ELSE 0 END) 													AS Abandoned,
   							SUM(CASE WHEN a.IsMissedCall = 1 AND a.IsAbandoned = 0 THEN 1 ELSE 0 END) 							AS MissedCall,
                               a.IsMissedCall,
                               a.IsAbandoned,
   							SUM(a.Duration) 																					AS totalDuration,
   							SUM(CASE WHEN a.dialDuration BETWEEN 1 AND 5 THEN 1 ELSE 0 END) 									AS SL1,
   							SUM(CASE WHEN a.dialDuration BETWEEN 6 AND 10 THEN 1 ELSE 0 END) 									AS SL2,
   							SUM(CASE WHEN a.dialDuration BETWEEN 11 AND 15 THEN 1 ELSE 0 END) 									AS SL3,
   							SUM(CASE WHEN a.dialDuration BETWEEN 16 AND 20 THEN 1 ELSE 0 END) 									AS SL4,
   							SUM(CASE WHEN a.dialDuration BETWEEN 21 AND 25 THEN 1 ELSE 0 END) 									AS SL5,
   							SUM(CASE WHEN a.dialDuration BETWEEN 26 AND 30 THEN 1 ELSE 0 END) 									AS SL6,
   							SUM(CASE WHEN a.dialDuration BETWEEN 1 AND 30 THEN 1 ELSE 0 END) 									AS TotalSLA
   						FROM temp_InstagramHistory a
   						GROUP BY a.SessionDate,a.queueId,a.queueName,a.InstagramHistoryId,a.sessionStartTime,a.IsAbandoned,a.IsMissedCall; 
                        
						DROP TEMPORARY TABLE IF EXISTS temp_InstagramHistory_calc1; 
                       	CREATE TEMPORARY TABLE temp_InstagramHistory_calc1 AS 	     
                       	SELECT 	
   							  a.Date 				       										                                                       
          						 ,a.queueId
          						 ,a.queueName														
                                ,(a.Answered+a.Abandoned)                                                                                                            AS CallType                             
				, Abandoned									AS ReceivedChats
				,a.InstagramHistoryId
                                ,a.sessionStartTime
				 ,  a.IsAbandoned
    				 , a.totalDuration
                                ,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 													  AS TotalSLA1
                                , a.TotalSLA
                                , a.MissedCall       
    							 ,SUM(CASE WHEN (a.TotalSLA + a.MissedCall) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedCall)) * 10 END)                      AS answeredSLA
                                ,SUM(CASE WHEN (a.TotalSLA + a.MissedCall) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedCall) * 100) END   )                AS abandonedSLA
                                ,SUM(CASE WHEN (a.TotalSLA + a.MissedCall) = 0 THEN 1  ELSE (a.MissedCall / (a.TotalSLA + a.MissedCall)) * 100 END  )              AS SLAbreached
                              FROM temp_InstagramHistory_calc    a 
                               GROUP BY a.Date
                               ,a.queueId
                               ,a.queueName
                               ,a.sessionStartTime
                               ,a.InstagramHistoryId
			       ,a.IsAbandoned
			       ,a.totalDuration
                               ,a.TotalSLA
                               ,a.MissedCall
                               ,a.Answered
                               ,a.Abandoned ;  
                               
		SELECT  COUNT(InstagramHistoryId),	SUM(TotalSLA1), SUM(MissedCall),sum(CallType)              														                     				 
         INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedCalls,v_CurCallTypeCount                           														                      					
         FROM 	temp_InstagramHistory_calc1
         WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
         
		SELECT 	COUNT(InstagramHistoryId),SUM(TotalSLA1), SUM(MissedCall),sum(CallType)                       																								 
     	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedCalls,v_PrevCallTypeCount                                 														 										
     	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
		SELECT 	SUM(IFNULL(answeredSLA, 0))
     	INTO 	v_PrevansweredSLACount 
     	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
   SELECT 	SUM(IFNULL(totalDuration, 0))
     	INTO 	v_CurrenttotalDurationCount 
    	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
 
     
      	SELECT 	SUM(answeredSLA)/SUM(ReceivedChats)
     	INTO 	v_CuransweredSLACount 
		FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
     
      	SELECT 	SUM(IFNULL(abandonedSLA, 0))
     	INTO 	v_PrevabandonedSLACount 
     	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     
      	SELECT 	SUM(abandonedSLA)/SUM(ReceivedChats)
     	INTO 	v_CurabandonedSLACount 
		FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
       
       

    	SELECT 	SUM(IFNULL(answeredSLA, 0))
     	INTO 	v_PrevSLAbreachedCount 
     	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     
      	SELECT 	100-(SUM(answeredSLA)/SUM(ReceivedChats))
     	INTO 	v_CurSLAbreachedCount 
    	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
       
       
		SELECT 	SUM(IFNULL(totalDuration, 0))
     	INTO 	v_CurrenttotalDurationCount 
    	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
        
    	SELECT 	SUM(IFNULL(totalDuration, 0))
     	INTO 	v_PretotalDurationCount 
    	FROM	temp_InstagramHistory_calc1
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
        
    
    	SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
    	INTO    v_CurSLA1,v_CurSLA2 ,v_CurSLA3,v_CurSLA4,v_CurSLA5, v_CurSLA6 
    	FROM 	temp_InstagramHistory_calc
    	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
     
   	SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
   	INTO    v_PrevSLA1,v_PrevSLA2, v_PrevSLA3 ,v_PrevSLA4,v_PrevSLA5, v_PrevSLA6
      	FROM	temp_InstagramHistory_calc
     	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
        
		SET v_PrevTotalCount      	=    CASE WHEN v_PrevTotalCount = 0 then null else     v_PrevTotalCount end; 
		SET v_PrevansweredSLACount 	= 	CASE WHEN v_PrevansweredSLACount = 0 then null else v_PrevansweredSLACount end;
     	SET v_PrevabandonedSLACount	= 	CASE WHEN v_PrevabandonedSLACount = 0 then null else v_PrevabandonedSLACount end;
		SET v_PrevSLAbreachedCount 	= 	CASE WHEN v_PrevSLAbreachedCount = 0 then null else v_PrevSLAbreachedCount end;
        
       SET v_DiffTotalPercent 		    = (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
    	,  v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
   	,  v_DiffabandonedSLAPercent		= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
    	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
        
         SELECT * FROM temp_AllqueueId;
           
               	SELECT 
                IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
                IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
                IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
                IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
                IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
                IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';
  SELECT
         	  'All Queue'												   													AS queueName
    		 ,'Answered'                                                   													AS ChatType
            ,IFNULL(v_CurSLA1,0)                                          													AS SL1
            ,IFNULL(v_CurSLA2,0)                                          													AS SL2
            ,IFNULL(v_CurSLA3,0)                                          													AS SL3
            ,IFNULL(v_CurSLA4,0)                                          													AS SL4
            ,IFNULL(v_CurSLA5,0)                                          													AS SL5
            ,IFNULL(v_CurSLA6,0)                                          													AS SL6
            ,IFNULL(v_CurTotalSLA,0)                                      													AS Total
            ,IFNULL(v_CurMissedCalls,0)                                   													AS MissedChats
            ,ROUND(v_CurabandonedSLACount)													AS SLAAchieved
   	     ,IFNULL(v_CurSLAbreachedCount,0)                                   												AS SLAbreached
                  UNION ALL
     	SELECT 	a.queueName													                                   				AS queueName
            ,   CASE WHEN   b.IsMissedCall = 1 AND b.IsAbandoned = 1  THEN 'Answered' ELSE 'Abandoned'  END     			AS ChatType   
            ,	count(b.SL1)  																								AS SL1
            ,	count(b.SL2)  																								AS SL2
    		 ,	count(b.SL3)  																								AS SL3
    		 ,	count(b.SL4)  																								AS SL4
    		 ,	count(b.SL5)  																								AS SL5
    		 ,	count(b.SL6)  																								AS SL6
            ,   sum(a.TotalSLA1)																							AS Total
            ,   count(a.MissedCall)																							AS MissedChats
     
             , ROUND(SUM(a.answeredSLA)/SUM(a.ReceivedChats))																	AS SLAAchieved
            , ROUND(100-IFNULL((SUM(a.answeredSLA)/SUM(a.ReceivedChats)),0))																							AS SLAbreached
            FROM temp_InstagramHistory_calc b
            JOIN temp_InstagramHistory_calc1 a     ON b.InstagramHistoryId= a.InstagramHistoryId
    		 JOIN 	temp_AllqueueId		U	   ON b.queueId	= U.qid	
    	 
            GROUP BY a.queueName,a.CallType,b.Abandoned,b.Answered,b.IsMissedCall,b.IsAbandoned;    
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Outboundcall_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Outboundcall_analysis_metrics_filter`(  
                      p_startTmpstmp 		BIGINT,
                      p_endTmpstmp 		BIGINT,
                      p_domainId 			INT,    	
                      p_queueId			VARCHAR(250),		
                      p_offset 			INT,
                      p_Limit 			INT	
                    )
BEGIN
                           
     				DECLARE v_offset 								INT;	  	
     				DECLARE v_CurrentStartTmpstmp 					BIGINT;
     				DECLARE v_CurrentEndTmpstmp 					BIGINT;
     			
     				DECLARE v_PrevStartTmpstmp 						BIGINT;
     				DECLARE v_PrevEndTmpstmp 						BIGINT; 
     				DECLARE v_TmpstmpInterval						BIGINT;	
     		
     				DECLARE v_DiffAverageResponsePercent			INT;
     		
     				DECLARE v_DiffAverageHandledPercent				INT;  	    
     		
     				DECLARE v_CurrentMaximumHandledCount			INT;	        
     				DECLARE v_DiffMaximumHandledTimePercent			INT;    
     		
     				DECLARE v_CurrentTotalACWCount		  			INT;	        
     				DECLARE v_DiffTotalACWTimePercent	  			INT;   
				
     				DECLARE v_CurrentAverageQueueWaitingCount		INT;	        
     				DECLARE v_DiffAverageQueueWaitingPercent		INT; 

     				DECLARE v_PrevaverageHoldtCount		        	INT;	
     				DECLARE v_CurrentaverageHoldtCount		    	INT;	        
     				DECLARE v_DiffaverageHoldtPercent		    	INT; 
		
     				DECLARE v_CurrentMaximumQueueWaitingCount		INT;	        
     				DECLARE v_DiffMaximumQueueWaitingPercent		INT;  
     
     				DECLARE v_CurrentfirstCallResolutionCount		INT;	        
     				DECLARE v_DifffirstCallResolutionPercent		INT;  
     
     				DECLARE v_CurrentSentimentalScore          		INT;
     				DECLARE v_DiffSentimentalScorePercent      		INT;      
     
     				DECLARE v_PrevAgentIdleTimeCount		      	INT;	
     				DECLARE v_CurrentAgentIdleTimeCount		        INT;	        
     				DECLARE v_DifffirsAgentIdleTimePercent	        INT;    
     
     				DECLARE v_PreavailableCount                     bigint;
     				DECLARE v_PretotalTalkCount                     INT;
     
					DECLARE		v_averageResponseTime             	BIGINT; 
     				DECLARE		v_averageHandledTime				BIGINT;
     				DECLARE		v_MaximumHandledTime              	BIGINT; 
     				DECLARE		v_totalACWTime						BIGINT;
     				DECLARE		v_averageHoldtime                 	BIGINT; 
     				DECLARE		v_averageQueueWaittime				BIGINT;
     				DECLARE		v_maximumQueueWaittime            	BIGINT; 
     				DECLARE		v_occupancyRate       				BIGINT;
     				DECLARE		v_firstCallResolution             	BIGINT; 
     				DECLARE		v_CustomerSatisfaction				BIGINT; 
     				DECLARE		v_ouboundCalls						BIGINT; 
     				DECLARE		v_callDuration						BIGINT; 
     				DECLARE		v_afterCallWorkTime					INT; 
     				DECLARE		v_availableTime						BIGINT; 
     				DECLARE		v_currentResponseTime				BIGINT; 
     				DECLARE		v_previousResponseTime				BIGINT; 
					DECLARE		v_currentHandledTime				BIGINT; 
     				DECLARE		v_previousHandledTime				BIGINT; 
     				DECLARE		v_currentTotalAnsweredCalls			INT; 
     				DECLARE		v_previousTotalAnsweredCalls		INT; 
					DECLARE       v_count							INT;
					DECLARE       v_answerCall						INT;
					DECLARE       v_CurTotalCount					INT;
					DECLARE       v_PrevTotalCount					INT;
					DECLARE       v_CurResponseTime					INT;
					DECLARE       v_PreResponseTime					INT;
					DECLARE       v_CurHandledTime					INT;
					DECLARE       v_PreHandledTime					INT;
					  
					  DECLARE		v_prvcount							INT;
					  DECLARE		v_prevAnswerCall					INT; 
					  DECLARE		v_prevAverageResponseTime			INT;
					  DECLARE		v_prevAverageHandledTime			INT;
					  
					  DECLARE v_unAnswered INT;
					  DECLARE v_abandoned INT;
					  DECLARE v_transferedCall INT;
					  DECLARE v_totalTalkTime INT;
					  DECLARE v_waitDuration INT;
					  DECLARE v_answeredCall INT;
					  DECLARE v_DiffTotalPercent INT;
					  DECLARE v_DiffAnsweredPercent INT;
					  DECLARE v_prevUnAnswered INT;
					  DECLARE v_DiffUnAnsweredPercent INT;
                  
     
  				SET v_offset =  p_Limit * p_offset; 
  
  				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
  				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
  
  				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
  
  				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
  				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                      		
     				DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
					CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
    					   
					 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
						 DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
						 CREATE TEMPORARY TABLE temp_AllqueueId
						 SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
					 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    
					
							SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
                    		DROP TEMPORARY TABLE IF EXISTS temp_AllagentId_dtl;	
                    		CREATE TEMPORARY TABLE temp_AllagentId_dtl
                    		SELECT 	UserID,UserName ,ext,domainId
                    		FROM 	tb_User 
                    		WHERE 	domainId = p_domainId; 
                    
     				DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                                	
     				DROP TEMPORARY TABLE IF EXISTS temp_FirstCallResolution;	
     				CREATE TEMPORARY TABLE temp_FirstCallResolution
  					SELECT 
  					COUNT(SubQuery.AgentId) AS FirstCallResolution,
  					SubQuery.AgentId,SubQuery.CallHistoryId
  					FROM (
  					SELECT 
  					SDH.AgentId,SH.CallHistoryId
  					FROM tb_CallHistory SH
  					JOIN tb_CallDurationHistory	SDH	    ON SH.CallHistoryId 		= SDH.CallHistoryId
  					JOIN disposition_status DS ON DS.did = SDH.dispositionId
  					WHERE SDH.IsBot = 0
  					AND SH.domainId = p_domainId
  					AND SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp
					AND	DS.dispositionName <> 'Transferred'
                    AND	SH.IsInBound = 0
  					GROUP BY SDH.AgentId, SH.CallHistoryId
  					HAVING COUNT(SDH.CallDurationHistoryId) = 1
     				) AS SubQuery
     				GROUP BY SubQuery.AgentId,SubQuery.CallHistoryId;
                    
                    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     				DROP TEMPORARY TABLE IF EXISTS tt_CallHistory;
                    CREATE TEMPORARY TABLE tt_CallHistory AS 	    	
     				SELECT 	SH.sessionStartTime
                    ,SDH.AgentId
                     ,SH.CallHistoryId
     				, SDH.QueueId 
     				, SDH.IsMissedCall
                    , SDH.dispositionId
                    , SH.IsAbandoned
     				, U.queueName												
     				, SDH.StartTime												
     				, SDH.EndTime												
     				, SH.IsInBound
     				, SH.callDuration												
     				, SDH.AgentHoldDuration										
     				, SDH.transferredTypeId																	
     				, SDH.afterCallWorkTime		
     				, SH.queueDuration											
     				, SDH.SentimentalScore
     				, SDH.IsBot
     				, t_f.FirstCallResolution 
                    , SDH.answeredDuration
                    , SDH.Duration
     				FROM 	tb_CallHistory 				SH
     				JOIN 	tb_CallDurationHistory		SDH	ON SH.CallHistoryId 	= SDH.CallHistoryId     
     				LEFT JOIN temp_AllqueueId			U	ON U.qid				= SDH.QueueId
     				left JOIN temp_FirstCallResolution 	t_f	ON t_f.CallHistoryId 	= SDH.CallHistoryId
     				WHERE 	SH.domainId 		= p_domainId	
 				 	AND 	 SDH.IsBot			= 0      
					AND 	 SH.IsInBound 		= 0
                    AND 	 (IFNULL(p_queueId,'')='' OR SDH.QueueId IN (select queueId from temp_queueIds))
                    AND 	SDH.QueueId <> 0
     				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp ; 

					DROP TEMPORARY TABLE IF EXISTS temp_CallHistory; 
					CREATE TEMPORARY TABLE temp_CallHistory AS 	    	
					SELECT 	CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
					, sessionStartTime	
					, CallHistoryId
                    , AgentId
					, QueueId
					, queueName												
					, IsInBound
                    , callDuration
					, callDuration											AS CallHandlingTime
					, AgentHoldDuration										AS agentHoldDuration
					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                    , answeredDuration										AS responseTime
					, afterCallWorkTime		
					, queueDuration											AS queueWaitingtime
					, SentimentalScore
					, case when IsInBound = 0 then 1 else 0 end 			AS ouboundCalls   
					, FirstCallResolution 									AS firstCallResolution
					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      		AS respondedCall
					,CASE WHEN IFNULL(SentimentalScore,0) > 0 THEN 1 ELSE 0 END      	AS answeredCall
                    , CASE WHEN IFNULL(SentimentalScore,0) = 0  THEN 1 ELSE 0 END				AS unAnswered
                    , CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                    ,CASE WHEN transferredTypeId = 2002002 THEN 1 ELSE 0 END 			AS transferedCall
                    ,CASE WHEN Duration > 0  THEN Duration ELSE 0 END 			AS totalTalkTime
                    ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
					FROM 	tt_CallHistory 				
					WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ; 
                                    
                  DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_prev; 
     				CREATE TEMPORARY TABLE temp_CallHistory_prev AS 	    	
     				SELECT 	CAST(FROM_UNIXTIME(sessionStartTime/1000)  AS DATE) AS SessionDate
					, sessionStartTime	
					, CallHistoryId
                    , AgentId
					, QueueId
					, queueName												
					, IsInBound
                    , callDuration
					, callDuration											AS CallHandlingTime
					, AgentHoldDuration										AS agentHoldDuration
					, ((callDuration/1000)+afterCallWorkTime)				AS Handled                                 
                    , answeredDuration										AS responseTime
					, afterCallWorkTime		
					, queueDuration											AS queueWaitingtime
					, SentimentalScore
					, case when IsInBound = 0 then 1 else 0 end 				AS ouboundCalls   
					, FirstCallResolution 										AS firstCallResolution
					,CASE WHEN callDuration > 0 THEN 1 ELSE 0 END      			AS respondedCall
					,CASE WHEN IFNULL(SentimentalScore,0) > 0 THEN 1 ELSE 0 END      	AS answeredCall
                    , CASE WHEN IFNULL(SentimentalScore,0) = 0  THEN 1 ELSE 0 END				AS unAnswered
                    ,CASE WHEN IsAbandoned = 1 THEN 1 ELSE 0 END						AS abandoned
                    ,CASE WHEN transferredTypeId = 2002002 THEN 1 ELSE 0 END 			AS transferedCall
                    ,CASE WHEN callDuration > 0  THEN callDuration ELSE 0 END 			AS totalTalkTime
                    ,CASE WHEN IFNULL(answeredDuration,0) > 0 THEN answeredDuration ELSE 0 END AS waitDuration
					FROM 	tt_CallHistory 				
					WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp ; 
              
			DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc; 
			CREATE TEMPORARY TABLE temp_CallHistory_calc AS 	     
			SELECT 	
			count(1)                             																			AS NoOfcalls
            , t_SH.AgentId	
			, t_SH.QueueId
			, t_SH.SessionDate
			, t_SH.queueName																              						
			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
			, SUM(t_SH.Handled)																									AS averageHandledTime    
			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
			, t_SH.firstcallResolution
			, sum(t_SH.ouboundCalls)                          																	AS ouboundCalls
			, t_SH.SentimentalScore																								AS CustomerSatisfaction
			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
			, sum(t_SH.callDuration)																							AS callDuration	
			, sum(t_SH.respondedcall)																							AS respondedcall
			,sum(t_SH.answeredCall)																								AS answeredCall               
			,sum(t_SH.unAnswered)																								AS unAnswered               
			,sum(t_SH.abandoned)																								AS abandoned               
			,sum(t_SH.transferedCall)																							AS transferedCall               
			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
			,sum(t_SH.waitDuration)																								AS waitDuration               
			FROM 	temp_CallHistory t_SH
			GROUP BY t_SH.SessionDate, t_SH.queueName, t_SH.QueueId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration,t_SH.AgentId;    
                      
		DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev; 
		CREATE TEMPORARY TABLE temp_CallHistory_calc_prev AS 	     
		SELECT 	
			count(1)                             																			AS NoOfcalls,
			t_SH.QueueId
            , t_SH.AgentId
			, t_SH.SessionDate
			, t_SH.queueName																              						AS queueName
			, CASE WHEN SUM(responseTime) IS NOT NULL THEN SUM(responseTime) ELSE 0 END               							AS averageResponseTime
			, SUM(t_SH.Handled)																									AS averageHandledTime    
			, MAX(t_SH.Handled)  						  							                                 			AS MaximumHandledTime 
			, CASE WHEN SUM(t_SH.afterCallWorkTime) IS NOT NULL THEN SUM(t_SH.afterCallWorkTime) ELSE 0 END 					AS totalACWTime                    
			, CASE WHEN SUM(t_SH.queueWaitingtime)  IS NOT NULL THEN SUM(t_SH.queueWaitingtime)  ELSE 0 END 					AS averageQueueWaitingtime          
			, CASE WHEN MAX(t_SH.queueWaitingtime)  IS NOT NULL THEN MAX(t_SH.queueWaitingtime)  ELSE 0 END   					AS maximumQueueWaitingtime    				         
			, CASE WHEN SUM(t_SH.agentHoldDuration) IS NOT NULL THEN SUM(t_SH.agentHoldDuration) ELSE 0 END       				AS callHoldTime
			, t_SH.firstcallResolution
			, sum(t_SH.ouboundCalls)                          																	AS ouboundCalls
			, t_SH.SentimentalScore																								AS CustomerSatisfaction
			, sum(t_SH.aftercallWorkTime)																						AS aftercallWorkTime		
			, sum(t_SH.callDuration)																							AS callDuration	
			, sum(t_SH.respondedcall)																							AS respondedcall
			,sum(t_SH.answeredCall)																								AS answeredCall               
			,sum(t_SH.unAnswered)																								AS unAnswered               
			,sum(t_SH.abandoned)																								AS abandoned               
			,sum(t_SH.transferedCall)																							AS transferedCall               
			,sum(t_SH.totalTalkTime)																							AS totalTalkTime               
			,sum(t_SH.waitDuration)																								AS waitDuration               
			FROM 	temp_CallHistory_prev t_SH
			GROUP BY t_SH.SessionDate, t_SH.queueName, t_SH.QueueId, t_SH.firstCallResolution,t_SH.SentimentalScore,t_SH.callDuration,t_SH.AgentId;
                        
     				DROP TEMPORARY TABLE IF EXISTS temp_AvailableStates;
     				CREATE TEMPORARY TABLE temp_AvailableStates AS
     				SELECT   
     					CASE 
     						WHEN a.aid = ST.timerStatusId AND a.statusName IN ('Ready', 'Transfer Only', 'Busy') THEN 1
     						ELSE 2 
     					END AS tt_Time,
     					ST.ext,
     					ST.domainId,
     					from_unixtime(ST.startTimestamp/1000),
     					ST.stateDuration as SD
     				FROM     state_timer ST 
     				JOIN     agent_status a ON a.aid = ST.timerStatusId AND a.domainId = ST.domainId
     				WHERE    ST.domainId = p_domainId
     				AND 	 ST.startTimestamp BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp ;                              
     						
     				ALTER TABLE temp_CallHistory_calc ADD COLUMN availableTime BIGINT;
     					  
     				UPDATE temp_CallHistory_calc SH_C
     				JOIN temp_AllagentId_dtl t_A ON SH_C.agentId = t_A.UserID
     				JOIN (
     				SELECT ext, domainId, SUM(CASE WHEN tt_Time = 1 THEN SD ELSE 0 END) AS total_SD
     				FROM temp_AvailableStates
     				GROUP BY ext, domainId
     				) tt_AV ON t_A.ext = tt_AV.ext AND tt_AV.domainId = t_A.domainId
     				SET SH_C.availableTime 	= tt_AV.total_SD;

     				SELECT sum(firstCallResolution),SUM(CustomerSatisfaction)
     				INTO 	v_CurrentfirstCallResolutionCount,v_CurrentSentimentalScore
     				FROM 	temp_CallHistory_calc ;                                                            
   
     				DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_1;
     				CREATE TEMPORARY TABLE temp_CallHistory_calc_1 AS
     					SELECT 															
     			 	 a.QueueId																                                                  AS QueueId
                     ,sum(a.NoOfCalls) as NoOfCalls
					,sum(a.averageResponseTime)  																			  		  			  AS averageResponseTime
					,sum(a.averageHandledTime)			                                                              			  				  AS averageHandledTime
     				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
     				,sum(a.totalACWTime)          																							  AS totalACWTime
     				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               							  AS averageHoldtime                                  
     				,sum(a.averageQueueWaitingtime)                                                                           				  AS averageQueueWaittime
     				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
     				,sum(a.availableTime) 																									  AS occupancyRate                                      
     				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
     				,sum(a.ouboundCalls)																									  AS ouboundCalls
     				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
     				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
     				,sum(a.callDuration)																									  AS callDuration
     				,sum(a.availableTime)																									  AS availableTime
                    ,sum(respondedCall)  																									  AS respondedCall
					,sum(answeredCall)																										  AS answeredCall
                    ,sum(unAnswered)      																									AS unAnswered
                    ,sum(abandoned)       																									AS abandoned
                    ,sum(transferedCall)  																									AS transferedCall
                    ,sum(totalTalkTime)   																									AS totalTalkTime
                    ,sum(waitDuration)    																									AS waitDuration
     			FROM 	temp_CallHistory_calc 	    a
     			 GROUP BY a.QueueId;   	
                            
              DROP TEMPORARY TABLE IF EXISTS temp_CallHistory_calc_prev_1;
     				CREATE TEMPORARY TABLE temp_CallHistory_calc_prev_1 AS
     				SELECT a.QueueId		
                     ,sum(NoOfCalls)   as NoOfCalls
					,sum(a.averageResponseTime)   																			  AS averageResponseTime
					,sum(a.averageHandledTime)					                                                              AS averageHandledTime
     				,sum(a.MaximumHandledTime)    																							  AS MaximumHandledTime
     				,sum(a.totalACWTime)          																							  AS totalACWTime
     				,sum(CASE WHEN (a.callHoldTime) IS NOT NULL THEN (a.callHoldTime) ELSE 0 END)               AS averageHoldtime                                  
     				,sum(a.averageQueueWaitingtime)                                                                           AS averageQueueWaittime
     				,sum(a.maximumQueueWaitingtime)                                                                                           AS maximumQueueWaittime
     				,SUM(a.firstCallResolution)                                                                	  							  AS firstCallResolution
     				,sum(a.ouboundCalls)																									  AS ouboundCalls
     				,sum(a.CustomerSatisfaction)                                                                                              AS CustomerSatisfaction
     				,sum(a.afterCallWorkTime)																								  AS afterCallWorkTime					
     				,sum(a.callDuration)																									  AS callDuration
                   ,sum(respondedCall)  as respondedCall
					,sum(answeredCall)																											AS answeredCall
                    ,sum(unAnswered)      																									AS unAnswered
                    ,sum(abandoned)       																									AS abandoned
                    ,sum(transferedCall)  																									AS transferedCall
                    ,sum(totalTalkTime)   																									AS totalTalkTime
                    ,sum(waitDuration)    																									AS waitDuration
     			FROM 	temp_CallHistory_calc_prev 	a
     			GROUP BY a.QueueId;   	
				        
     			select  
     			sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(MaximumHandledTime), sum(totalACWTime), sum(averageHoldtime),
     			sum(averageQueueWaittime), sum(maximumQueueWaittime), sum(occupancyRate), sum(firstCallResolution), sum(CustomerSatisfaction),sum(ouboundCalls),
     			sum(callDuration),sum(afterCallWorkTime),sum(availableTime),sum(answeredCall),sum(unAnswered),sum(abandoned),sum(transferedCall),sum(totalTalkTime),sum(waitDuration)
     			INTO
     			v_count,v_answerCall, v_averageResponseTime, v_averageHandledTime, v_MaximumHandledTime, v_totalACWTime, v_averageHoldtime, 
     			v_averageQueueWaittime, v_maximumQueueWaittime, v_occupancyRate, v_firstCallResolution, v_CustomerSatisfaction,v_ouboundCalls,
     			v_callDuration,v_afterCallWorkTime,v_availableTime,v_answeredCall,v_unAnswered,v_abandoned,v_transferedCall,v_totalTalkTime,v_waitDuration
     			FROM temp_CallHistory_calc_1;  
              
				select sum(NoOfCalls),sum(answeredCall), sum(averageResponseTime), sum(averageHandledTime), sum(unAnswered)
     			INTO v_prvcount,v_prevAnswerCall, v_prevAverageResponseTime, v_prevAverageHandledTime , v_prevUnAnswered
     			FROM temp_CallHistory_calc_prev_1; 

			SELECT * FROM temp_AllqueueId;  

			SET v_DiffTotalPercent 		= ((v_count - ifnull(v_prvcount,0)) / IF(IFNULL(v_prvcount,0)=0,1,v_prvcount)) * 100 
            ,	v_DiffAnsweredPercent	= ((v_answeredCall - ifnull(v_prevAnswerCall,0)) / IF(IFNULL(v_prevAnswerCall,0)=0,1,v_prevAnswerCall)) * 100
			,	v_DiffUnAnsweredPercent	= ((v_unAnswered - ifnull(v_prevUnAnswered,0)) / IF(IFNULL(v_prevUnAnswered,0)=0,1,v_prevUnAnswered)) * 100;	

  			SELECT 	IFNULL(v_count,0) 											AS 'TotalOutboundCall',
  					IFNULL(v_DiffTotalPercent,0) 		        				AS 'DiffTotalPercent',
  					IFNULL(v_answeredCall,0) 			    					AS 'CurrentAnsweredeCount',
  					IFNULL(v_DiffAnsweredPercent,0) 							AS 'DiffAnsweredPercent',
  					IFNULL(v_unAnswered,0) 										AS 'CurrentUnAnsweredCount',
  					IFNULL(v_DiffUnAnsweredPercent,0) 							AS 'DiffUnAnsweredPercent';                   
  
					select 'All Queue' AS queueName,
					v_count																 	AS outboundcalls,
					v_answeredCall														 	AS answeredCalls,
					v_unAnswered 															AS unAnsweredCalls,
					v_abandoned 															AS abandonedCalls,
					v_transferedCall 														AS transferredCalls,
					v_totalTalkTime 														AS talktime,
					(v_waitDuration/v_count)												AS avgSpeedofAnswer,
					(v_averageHandledTime/v_count) * 1000                                	AS  averageHandleTime, 
					v_MaximumHandledTime                                               	 	AS  maximumHandleTime,
					v_averageHoldtime                                                    	AS  averageHoldTime,
					((v_callDuration + (v_afterCallWorkTime * 1000)) / v_availableTime )*100	AS   occupancyrate,
					v_afterCallWorkTime	  * 1000												AS   totalACWTime,
					round((v_firstCallResolution /v_ouboundCalls) * 100  )             		AS  firstCallResolution,
					v_CustomerSatisfaction													AS customersatisfaction
     		UNION ALL
					SELECT DISTINCT(U.queueName)										AS  queueName, 
					sum(NoOfcalls)														AS outboundcalls, 
					sum(answeredCall)													AS answeredCalls,
					sum(unAnswered)														AS unAnsweredCalls,
					sum(abandoned)														AS abandonedCalls,
					sum(transferedCall)													AS transferredCalls,
					sum(totalTalkTime)													AS talktime,
					sum(waitDuration/NoOfcalls)											AS avgSpeedofAnswer,
					sum(averageHandledTime/NoOfCalls) * 1000                            AS maximumHandleTime, 
					sum(MaximumHandledTime)                                             AS maximumHandleTime, 
					sum(averageHoldtime)                                                AS  averageHoldTime, 
					IFNULL(((sum(callDuration) + (sum(afterCallWorkTime) * 1000)) / sum(availableTime) )*100,0)	AS   occupancyrate,
					sum(afterCallWorkTime) * 1000										AS totalACWTime,
					round(sum(firstCallResolution/ouboundCalls) *100 )                  AS firstCallResolution,
					sum(CustomerSatisfaction)											AS customersatisfaction
					FROM    temp_CallHistory_calc_1 a
					JOIN 	temp_AllqueueId		U	ON a.QueueId	= U.qid
					group by queueName;
 
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Outboundcall_analysis_metrics_filter_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Outboundcall_analysis_metrics_filter_1`(
       p_startTmpstmp   BIGINT,
       p_endTmpstmp 	BIGINT,
       p_domainId 	    INT,    	
       p_queueId		VARCHAR(250),		
       p_offset 		INT,
       p_Limit 		     INT	
   )
sp_return:BEGIN
   
   		DECLARE v_offset 					INT;	  	
   		DECLARE v_CurrentStartTmpstmp 		BIGINT;
   		DECLARE v_CurrentEndTmpstmp 		BIGINT;
   		DECLARE v_PrevStartTmpstmp 			BIGINT;
   		DECLARE v_PrevEndTmpstmp 			BIGINT; 
   		DECLARE v_TmpstmpInterval			BIGINT;	
   
   		DECLARE v_CurTotalCount 			INT;
   		DECLARE v_PrevTotalCount 			INT;
   		DECLARE	v_DiffTotalPercent 			INT;
   
   		DECLARE v_PrevAnsweredCount			INT;
   		DECLARE v_CurrentAnsweredCount		INT;
   		DECLARE v_DiffAnsweredPercent		INT;
   
   		DECLARE v_PrevUnAnsweredCount		INT;
   		DECLARE v_CurrentUnAnsweredCount	INT;
   		DECLARE v_DiffUnAnsweredPercent		INT;
           
		DECLARE v_PrevAbandonedCount		INT;
   		DECLARE v_CurrentAbandonedCount		INT;
   		DECLARE v_DiffAbandonedPercent		INT;
   
   		DECLARE v_CurrentMissedCount		INT;
   		DECLARE v_CurrentTransferredCount	INT;
   		DECLARE v_TotalCallDuration			BIGINT;
          
          DECLARE v_TotalTalktime             BIGINT;
  		  DECLARE v_TotalAfterCallWorkTime    INT;
          DECLARE v_CurrentCallHoldTime       INT;
          DECLARE v_CurrentAvailableTime      INT;
          DECLARE v_SentimentalScore          INT;
          DECLARE v_CurrentFirstCallResolution       INT;
   
   		SET v_offset =  p_Limit * p_offset; 
       
       	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
       	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
       	
   		SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
     
   		SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
   		SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
           
		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
		CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
   					   
      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
            DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
            CREATE TEMPORARY TABLE temp_AllqueueId
            SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
           
   		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
   		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
   		CREATE TEMPORARY TABLE temp_callDurationHistory AS
   		SELECT 		CH.sessionStartTime		
   					,CH.CallHistoryId        
   					,CDH.CallDurationHistoryId
   					,CDH.QueueId
   					,CDH.IsMissedCall
   					,CH.IsAbandoned
   					,CDH.transferredTypeId
   					,CDH.dispositionId
                      ,CDH.AgentHoldDuration
   					  ,(CDH.EndTime - CDH.StartTime)	                                                    AS callDuration
                      ,CDH.afterCallWorkTime			                                                    AS afterCallWorkTime
                      ,CH.IsInBound					                                                    AS IsInBound
  					  ,	CDH.StartTime																	AS agentconnecttime
					  ,	CDH.EndTime					   												    AS agentDisconnectTime
                      ,CDH.SentimentalScore                                                               AS SentimentalScore
                      ,CDH.IsBot
                      ,DS.dispositionName
   		FROM 		tb_CallHistory 			CH
   		LEFT JOIN 	tb_CallDurationHistory	CDH	    ON CH.CallHistoryId 		= CDH.CallHistoryId
   		LEFT JOIN 	tb_CallMessage			CM		ON CH.CallHistoryId 		= CM.CallHistoryId and CM.CallDurationHistoryId	= CDH.CallDurationHistoryId
   		LEFT JOIN 	temp_queueIds 			t_Q 	ON CDH.QueueId				= t_Q.queueId  
           LEFT JOIN 	disposition_status		DS		ON DS.did					= CDH.dispositionId and DS.domainId = CH.domainId
   		WHERE 	CH.domainId 			= p_domainId 		
   		AND 	CH.IsInBound			= 0
   		AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp  
   		AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL));
   		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
             DROP TEMPORARY TABLE IF EXISTS temp_callHistory_calc; 
              CREATE TEMPORARY TABLE temp_callHistory_calc AS 	     
                          	SELECT 	
                               t_SH.sessionStartTime		
  							,t_SH.CallHistoryId        
  							,t_SH.CallDurationHistoryId
  							,t_SH.QueueId
  							,t_SH.IsMissedCall
  							,t_SH.IsAbandoned
  							,t_SH.transferredTypeId
  							,t_SH.dispositionId
  							,t_SH.callDuration
                              ,SUM(t_SH.callDuration-t_SH.agentHoldDuration)										       AS totalTalktime
                              ,SUM(t_SH.afterCallWorkTime)                                                                 AS afterCallWorkTime
                              ,SUM(CASE WHEN t_SH.IsInBound = 1 AND t_SH.agentconnecttime > 0  THEN 1 ELSE 0 END) 	       AS  answeredCall
                              ,SUM(t_SH.agentHoldDuration)															       AS  callHoldTime
                              ,t_SH.SentimentalScore
                              ,SUM(CASE WHEN t_SH.IsBot = 0 AND t_SH.dispositionName = 'Transferred' THEN 1 ELSE 0 END)   AS FirstCallResolution
                          FROM 	temp_callDurationHistory t_SH
                          GROUP BY t_SH.sessionStartTime, t_SH.CallHistoryId, t_SH.CallDurationHistoryId,t_SH.QueueId, t_SH.IsMissedCall,t_SH.IsAbandoned,t_SH.transferredTypeId,
                          t_SH.dispositionId,t_SH.callDuration,t_SH.SentimentalScore;
                          
  				ALTER TABLE temp_callHistory_calc ADD COLUMN availableTime		INT;              
  		
  				UPDATE 	temp_callHistory_calc	SH_C
                   JOIN 	temp_queueIds	    t_A		ON 	SH_C.QueueId = t_A.queueId       
                   SET 	 
           				availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.timerStatusId = 1 THEN S.stateDuration ELSE 0 END) 
           									FROM 	state_timer S	
                                               WHERE  S.domainId	= p_domainId
                                               
                                               AND 	S.startTimestamp	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp );          
                                              
   		DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
   		CREATE TEMPORARY TABLE temp_PrevCallHistory as
   		SELECT 	DISTINCT CallHistoryId ,IsAbandoned
   		FROM 	temp_callDurationHistory
   		WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
   
   		DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
   		CREATE TEMPORARY TABLE temp_CurCallHistory AS
   		SELECT 	DISTINCT CallHistoryId,IsAbandoned 
   		FROM 	temp_callDurationHistory
   		WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;   
           
   		ALTER TABLE temp_PrevCallHistory ADD COLUMN isAnswered	TINYINT;
   		ALTER TABLE temp_CurCallHistory ADD COLUMN isAnswered	TINYINT;
           
           UPDATE 	temp_PrevCallHistory CH
        	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
        	AND 	CDH.dispositionId IS NOT NULL and IFNULL(CDH.IsMissedCall,0)=0 and IFNULL(CH.IsAbandoned,0)=0
        	SET 	CH.isAnswered = 1;
            
        	UPDATE 	temp_CurCallHistory CH
        	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
        	AND 	CDH.dispositionId IS NOT NULL and IFNULL(CDH.IsMissedCall,0)=0 and IFNULL(CH.IsAbandoned,0)=0
        	SET 	CH.isAnswered = 1;
           
           SELECT 	COUNT(CallHistoryId), SUM(isAnswered)
        	INTO 	v_PrevTotalCount , v_PrevAnsweredCount 
   		FROM	temp_PrevCallHistory;
          
        	SELECT 	COUNT(CallHistoryId), SUM(isAnswered)
        	INTO 	v_CurTotalCount , v_CurrentAnsweredCount 
   		FROM	temp_CurCallHistory;   
   
           SELECT 	SUM(IsMissedCall), SUM(transferredTypeId), SUM(callDuration),SUM(totalTalktime),SUM(afterCallWorkTime),sum(answeredCall),sum(callHoldTime),sum(SentimentalScore),sum(availableTime),sum(FirstCallResolution)
   		INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_TotalCallDuration,v_TotalTalktime,v_TotalAfterCallWorkTime ,v_CurrentAnsweredCount,v_CurrentCallHoldTime,v_SentimentalScore,v_CurrentAvailableTime,v_CurrentFirstCallResolution
   		FROM 	temp_callHistory_calc;
            
   		SELECT 	SUM(IFNULL(CallHistoryId, 0))
   		INTO 	v_PrevUnAnsweredCount 
   		FROM	temp_callDurationHistory
   		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp and callDuration = 0;
   			 
   		SELECT 	SUM(IFNULL(CallHistoryId, 0))
   		INTO 	v_CurrentUnAnsweredCount 
   		FROM	temp_callDurationHistory
   		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp and callDuration=0;
           
           SELECT 	SUM(IFNULL(IsAbandoned, 0))
   		INTO 	v_PrevAbandonedCount 
   		FROM	temp_callDurationHistory
   		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp and IsAbandoned=1;
   			 
   		SELECT 	SUM(IFNULL(IsAbandoned, 0))
   		INTO 	v_CurrentAbandonedCount 
   		FROM	temp_callDurationHistory
   		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp and IsAbandoned=1;
           
   		SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
   		SET v_PrevAnsweredCount 	= CASE WHEN v_PrevAnsweredCount = 0 then null else v_PrevAnsweredCount end;
   		SET v_PrevUnAnsweredCount 	= CASE WHEN v_PrevUnAnsweredCount = 0 then null else v_PrevUnAnsweredCount end;
           SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
   			
   		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
   		,	v_DiffAnsweredPercent	= (v_CurrentAnsweredCount - v_PrevAnsweredCount) / v_PrevAnsweredCount * 100
   		,	v_DiffUnAnsweredPercent	= (v_CurrentUnAnsweredCount - v_PrevUnAnsweredCount) / v_PrevUnAnsweredCount * 100
           ,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100;    
   	 
        	SELECT * FROM temp_AllqueueId;
           
           SELECT 	IFNULL(v_CurTotalCount,0) 			AS 'TotalOutboundCall',
        			IFNULL(v_DiffTotalPercent,0) 		AS 'DiffTotalPercent',
        			IFNULL(v_CurrentAnsweredCount,0) 	AS 'CurrentAnsweredeCount',
        			IFNULL(v_DiffAnsweredPercent,0) 	AS 'DiffAnsweredPercent',
        			IFNULL(v_CurrentUnAnsweredCount,0) 	AS 'CurrentUnAnsweredCount',
        			IFNULL(v_DiffUnAnsweredPercent,0) 	AS 'DiffUnAnsweredPercent';	
                   
                   
   		select 
   				'All Queue'														    																	    	AS queueName
                   ,IFNULL(v_CurTotalCount,0)                                  		    																		AS outboundcalls
                   ,IFNULL(v_CurrentAnsweredCount,0)                          																					AS answeredCalls
                   ,IFNULL(v_CurrentUnAnsweredCount,0)                         		    																		AS unAnsweredCalls
                   ,IFNULL(v_CurrentAbandonedCount,0)                         																					AS abandonedCalls
                   ,IFNULL(v_CurrentTransferredCount,0)                       																					AS transferredCalls
                   ,GREATEST(IFNULL(v_TotalCallDuration,0),0)                             																		AS talktime
                  
                   ,0																																			AS avgSpeedofAnswer
				   ,GREATEST(IFNULL((v_TotalTalktime + v_CurrentCallHoldTime + v_TotalAfterCallWorkTime), 0) / IFNULL(v_CurrentAnsweredCount, 1) / 1000,0)  	AS averageHandleTime
                   ,GREATEST(IFNULL((v_TotalTalktime + v_CurrentCallHoldTime + v_TotalAfterCallWorkTime), 0) / IFNULL(v_CurrentAnsweredCount, 1),0)             AS maximumHandleTime
                  ,IFNULL(v_TotalAfterCallWorkTime, 0)                                                                                                          AS totalACWTime
                  ,GREATEST(IFNULL(v_CurrentCallHoldTime / NULLIF(v_CurrentAnsweredCount, 0), 0) / 100,0)                                                       AS averageHoldTime
                  ,IFNULL((v_TotalTalktime)   /(v_CurrentavailableTime) ,0)                                                                             		AS occupancyrate                              
                  ,IFNULL(v_SentimentalScore,0)                                                                                                                 AS customersatisfaction
                  ,IFNULL(v_CurrentFirstCallResolution,0)                                                                              						    AS firstCallResolution
   		union all
           SELECT 	U.queueName																																	AS queueName
   				, COUNT(1)																																		AS outboundcalls
   				, SUM(CASE WHEN CDH.dispositionId IS NOT NULL  THEN 1 ELSE 0 END)																				AS answeredCalls
   				,SUM(CASE WHEN CDH.dispositionId IS NULL THEN 1 ELSE 0 END)																						AS unAnsweredCalls
   				,SUM(IsAbandoned)                         																										AS abandonedCalls
   				,SUM(transferredTypeId)																															AS transferredCalls
   				,SUM(callDuration)																																AS talktime
   				
  				,0																	    																		AS avgSpeedofAnswer
  			    ,sum((CDH.totalTalktime+CDH.callHoldTime+(CDH.afterCallWorkTime*1000))/CDH.answeredCall)	        									    	AS averageHandleTime
				,sum(CDH.totalTalktime+CDH.callHoldTime+(CDH.afterCallWorkTime*1000))	        									    						AS maximumHandleTime
                  ,CDH.afterCallWorkTime																														AS totalACWTime
                  ,sum(CDH.callHoldTime / CDH.answeredCall)/1000											                                                    AS averageHoldTime  
                  ,(CDH.totalTalktime/CDH.availableTime)*100											                                                        AS occupancyrate
                  ,(CDH.SentimentalScore)                                                                    												    AS customersatisfaction
                  ,CDH.FirstCallResolution                  																								    AS firstCallResolution
          FROM 	temp_callHistory_calc 	      CDH
          JOIN 	temp_AllqueueId				U	ON CDH.QueueId	= U.qid
         
          GROUP BY U.queueName,CDH.afterCallWorkTime,CDH.SentimentalScore,CDH.totalTalktime,CDH.availableTime,CDH.FirstCallResolution;  
           
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Outboundcall_BestTime_Call_Analysis_Metrics_Filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Outboundcall_BestTime_Call_Analysis_Metrics_Filter`(
              p_startTmpstmp   BIGINT,
              p_endTmpstmp 	  BIGINT,
              p_domainId 	     INT,    	
              p_queueId		 VARCHAR(250),
              p_offset 		 INT,
              p_Limit         INT	
          )
sp_return:BEGIN
          
          		DECLARE v_offset 					INT;	  	
          		DECLARE v_CurrentStartTmpstmp 		BIGINT;
          		DECLARE v_CurrentEndTmpstmp 		BIGINT;
          		DECLARE v_PrevStartTmpstmp 			BIGINT;
          		DECLARE v_PrevEndTmpstmp 			BIGINT; 
          		DECLARE v_TmpstmpInterval			BIGINT;	
          
          		DECLARE v_CurTotalCount 			INT;
          		DECLARE v_PrevTotalCount 			INT;
          		DECLARE	v_DiffTotalPercent 			INT;
          
          		DECLARE v_PrevAnsweredCount			INT;
          		DECLARE v_CurrentAnsweredCount		BIGINT;
          		DECLARE v_DiffAnsweredPercent		INT;
          
          		DECLARE v_PrevUnAnsweredCount		INT;
          		DECLARE v_CurrentUnAnsweredCount	INT;
          		DECLARE v_DiffUnAnsweredPercent		INT;
                  
                  DECLARE v_PrevAbandonedCount		INT;
          		DECLARE v_CurrentAbandonedCount		INT;
          		DECLARE v_DiffAbandonedPercent		INT;
          
          		DECLARE v_CurrentMissedCount		INT;
          		DECLARE v_CurrentTransferredCount	INT;
          		DECLARE v_TotalCallDuration			BIGINT;
                 
  				DECLARE v_TotalTalktime             BIGINT;
  				DECLARE v_TotalAfterCallWorkTime    INT;
  				DECLARE v_CurrentCallHoldTime       INT;
  				DECLARE v_CurrentAvailableTime      INT;
  				DECLARE v_SentimentalScore          INT;
  				DECLARE v_CurrentFirstCallResolution    INT;
  				DECLARE v_CurrentSessionDate          	DATETIME;
                 
  				DECLARE v_CurSuccessRateCount 			FLOAT;
  				DECLARE v_PrevSuccessRateCount 			FLOAT;
  				DECLARE	v_DiffSuccessRatePercent 		FLOAT; 
                  DECLARE v_CurrRightParty 				INT;
                  DECLARE v_prevRightParty 				INT;
                  DECLARE v_DiffRightParty 				INT;
          
          		SET v_offset =  p_Limit * p_offset; 
              
              	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
              	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
              	
          		SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
            
          		SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          		SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
                 
 
  				DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
  				CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
                  
          					   
  				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
  				DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
  				CREATE TEMPORARY TABLE temp_AllqueueId
  				SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
  				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                  
                  if not exists(select 1 from temp_queueIds limit 1) then
  					INSERT INTO temp_queueIds(queueId) 
                      SELECT qid FROM queue WHERE domainId = p_domainId;
                  End if;
                   
  				DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory;              
  				CREATE TEMPORARY TABLE temp_callDurationHistory AS
  				SELECT 		CH.sessionStartTime	
  							,FROM_UNIXTIME(CH.sessionStartTime/1000)  as Time 	
  							,CH.CallHistoryId        
  							,CDH.CallDurationHistoryId
  							,CDH.QueueId
  							,Q.queueName
  							,CDH.IsMissedCall
  							,CH.IsAbandoned
  							,CDH.transferredTypeId
  							,CDH.dispositionId
  							,CDH.AgentHoldDuration
  							,(CDH.EndTime - CDH.StartTime)	                                                    AS callDuration
  							,CDH.afterCallWorkTime			                                                    AS afterCallWorkTime
  							,CH.IsInBound					                                                    AS IsInBound
  							,CDH.StartTime																		AS agentconnecttime
  							,CDH.EndTime					   												    AS agentDisconnectTime
  							,CDH.SentimentalScore                                                              	AS SentimentalScore
  							,CDH.IsBot
  							,DS.dispositionName
  							,(CDH.Duration/1000) 																AS Duration
							,CDH.answeredDuration																AS answeredDuration
                            ,CDH.UMNStatus
  				FROM 		tb_CallHistory 			CH
  				JOIN 		tb_CallDurationHistory	CDH	    ON CH.CallHistoryId 		= CDH.CallHistoryId
  				LEFT JOIN 	tb_CallMessage			CM		ON CH.CallHistoryId 		= CM.CallHistoryId and CM.CallDurationHistoryId	= CDH.CallDurationHistoryId
  				LEFT JOIN 	temp_queueIds 			t_Q 	ON CDH.QueueId				= t_Q.queueId  
  				LEFT JOIN 	disposition_status		DS		ON DS.did					= CDH.dispositionId and DS.domainId = CH.domainId
  				LEFT JOIN   temp_AllqueueId			Q       ON CDH.QueueId				= Q.qid  
  				WHERE 	CH.domainId 			= p_domainId 		
  				AND 	CH.IsInBound			= 0
  				AND 	CH.sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp  
  				AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_Q.queueId IS NOT NULL));
           		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       
  				DROP TEMPORARY TABLE IF EXISTS temp_callHistory_calc; 
  				CREATE TEMPORARY TABLE temp_callHistory_calc AS 	     
  				SELECT 	t_SH.sessionStartTime		
  						,DATE_FORMAT(t_SH.Time, '%H:%i') 																AS Time
  						,t_SH.CallHistoryId        
  						,t_SH.CallDurationHistoryId
  						,t_SH.QueueId
  						,t_SH.queueName
  						,t_SH.IsMissedCall
  						,t_SH.IsAbandoned
  						,t_SH.transferredTypeId
  						,t_SH.dispositionId
  						,t_SH.callDuration
  						,SUM(t_SH.callDuration-t_SH.agentHoldDuration)										       		AS totalTalktime
  						,SUM(t_SH.afterCallWorkTime)                                                               		AS afterCallWorkTime
  						
						
                        ,(CASE WHEN t_SH.UMNStatus = 1 and t_SH.Duration > 0  and t_SH.IsMissedCall = 0 and t_SH.IsAbandoned = 0	THEN 1 ELSE 0 END) AS answeredCall
  						,SUM(t_SH.agentHoldDuration)															   		AS callHoldTime
  						,t_SH.SentimentalScore
  						,SUM(CASE WHEN t_SH.IsBot = 0 AND t_SH.dispositionName = 'Transferred' THEN 1 ELSE 0 END)   	AS FirstCallResolution
  						,SUM(t_SH.Duration) / COUNT(1) 																	AS SuccessRate
 						,t_SH.dispositionName
  				FROM 	temp_callDurationHistory t_SH
                 WHERE t_SH.sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
  				GROUP BY t_SH.sessionStartTime, t_SH.CallHistoryId, t_SH.CallDurationHistoryId,t_SH.QueueId, t_SH.IsMissedCall,t_SH.IsAbandoned,t_SH.transferredTypeId,
  				t_SH.dispositionId,t_SH.callDuration,t_SH.UMNStatus,t_SH.SentimentalScore,t_SH.Time,t_SH.queueName, t_SH.dispositionName,t_SH.Duration;
                 
                 
 					ALTER TABLE temp_callHistory_calc ADD COLUMN availableTime		INT;              
         		
  					UPDATE 	temp_callHistory_calc	SH_C
  					JOIN 	temp_queueIds	    t_A		ON 	SH_C.QueueId = t_A.queueId       
  					SET 	 availableTime	= (	SELECT 	SUM(CASE WHEN S.stateDuration > 0 AND S.timerStatusId = 1 THEN S.stateDuration ELSE 0 END) 
  										FROM 	state_timer S	
  										WHERE  S.domainId	= p_domainId
  										
  										AND 	S.startTimestamp	BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp );                      
                   
      			DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
          		CREATE TEMPORARY TABLE temp_PrevCallHistory as
          		SELECT 	DISTINCT CallHistoryId ,CallDurationHistoryId,IsAbandoned
          		FROM 	temp_callDurationHistory
          		WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
          
          		DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
          		CREATE TEMPORARY TABLE temp_CurCallHistory AS
          		SELECT 	DISTINCT CallHistoryId,CallDurationHistoryId,IsAbandoned 
          		FROM 	temp_callDurationHistory
          		WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;   
      
          		ALTER TABLE temp_PrevCallHistory ADD COLUMN isAnswered		TINYINT DEFAULT 0;
          		ALTER TABLE temp_CurCallHistory ADD COLUMN isAnswered		TINYINT DEFAULT 0;
 				ALTER TABLE temp_PrevCallHistory ADD COLUMN IsUnAnswered	TINYINT DEFAULT 0;
          		ALTER TABLE temp_CurCallHistory ADD COLUMN IsUnAnswered		TINYINT DEFAULT 0;
 				ALTER TABLE temp_PrevCallHistory ADD COLUMN Iswrongcall		TINYINT DEFAULT 0;
          		ALTER TABLE temp_CurCallHistory ADD COLUMN Iswrongcall		TINYINT DEFAULT 0;
                  
 				UPDATE 	temp_PrevCallHistory CH
               	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId AND CDH.CallDurationHistoryId = CH.CallDurationHistoryId
               	SET 	CH.isAnswered = CASE WHEN CDH.UMNStatus = 1 and CDH.Duration > 0  and CDH.IsMissedCall = 0 and CDH.IsAbandoned = 0	THEN 1 ELSE 0 END,
  						CH.IsUnAnswered = CASE WHEN CDH.UMNStatus <> 1 and (CDH.IsMissedCall = 0 OR CDH.IsAbandoned = 0) THEN 1 ELSE CH.IsUnAnswered END,
 						CH.Iswrongcall	= CASE WHEN CDH.dispositionName like '%wrong%' THEN 1 ELSE 0 END ;
                   
               	UPDATE 	temp_CurCallHistory CH
               	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId AND CDH.CallDurationHistoryId = CH.CallDurationHistoryId
               	SET 	CH.isAnswered = CASE WHEN CDH.UMNStatus = 1 and CDH.Duration > 0  and CDH.IsMissedCall = 0 and CDH.IsAbandoned = 0	THEN 1 ELSE 0 END,
  						CH.IsUnAnswered = CASE WHEN CDH.UMNStatus <> 1 and (CDH.IsMissedCall = 0 OR CDH.IsAbandoned = 0) THEN 1 ELSE CH.IsUnAnswered END,
 						CH.Iswrongcall	= CASE WHEN CDH.dispositionName like '%wrong%' THEN 1 ELSE 0 END;
                          
  			
 				SELECT 	COUNT(CallDurationHistoryId), SUM(isAnswered), SUM(IsUnAnswered),SUM(CASE WHEN Iswrongcall = 0 AND isAnswered = 1 THEN 1 ELSE 0 END),
 						SUM(CASE WHEN Iswrongcall = 0 AND isAnswered = 1 THEN 1 ELSE 0 END)/IF(COUNT(CallDurationHistoryId)=0,1,COUNT(CallDurationHistoryId))
               	INTO 	v_PrevTotalCount , v_PrevAnsweredCount, v_PrevUnAnsweredCount,v_prevRightParty,v_PrevSuccessRateCount
          		FROM	temp_PrevCallHistory;
                  
               	SELECT 	COUNT(CallDurationHistoryId), SUM(isAnswered), SUM(IsUnAnswered),SUM(CASE WHEN Iswrongcall = 0 AND isAnswered = 1 THEN 1 ELSE 0 END),
 						SUM(CASE WHEN Iswrongcall = 0 AND isAnswered = 1 THEN 1 ELSE 0 END)/IF(COUNT(CallDurationHistoryId)=0,1,COUNT(CallDurationHistoryId))
               	INTO 	v_CurTotalCount,  v_CurrentAnsweredCount, v_CurrentUnAnsweredCount, v_CurrRightParty,v_CurSuccessRateCount 
          		FROM	temp_CurCallHistory;   
                 
          		SET v_PrevTotalCount 		= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
          		SET v_PrevAnsweredCount 	= CASE WHEN v_PrevAnsweredCount = 0 then null else v_PrevAnsweredCount end;
          		SET v_PrevUnAnsweredCount 	= CASE WHEN v_PrevUnAnsweredCount = 0 then null else v_PrevUnAnsweredCount end;
 				SET v_prevRightParty 		= CASE WHEN v_prevRightParty = 0 then null else v_prevRightParty end;
 				SET v_PrevSuccessRateCount 	= CASE WHEN v_PrevSuccessRateCount = 0 then null else v_PrevSuccessRateCount end ;
                  
      
          		SET v_DiffTotalPercent 			= (v_CurTotalCount - IFNULL(v_PrevTotalCount,0)) / IF(v_PrevTotalCount=0,1,v_PrevTotalCount) * 100  
          		,	v_DiffAnsweredPercent		= (v_CurrentAnsweredCount - IFNULL(v_PrevAnsweredCount,0)) / IF(v_PrevAnsweredCount=0,1,v_PrevAnsweredCount) * 100
          		,	v_DiffUnAnsweredPercent		= (v_CurrentUnAnsweredCount - IFNULL(v_PrevUnAnsweredCount,0)) / IF(v_PrevUnAnsweredCount=0,1,v_PrevUnAnsweredCount) * 100
 				,	v_DiffRightParty			= (v_CurrRightParty - IFNULL(v_prevRightParty,0)) / IF(v_prevRightParty=0,1,v_prevRightParty) * 100
 				,	v_DiffSuccessRatePercent	= (v_CurSuccessRateCount - IFNULL(v_PrevSuccessRateCount,0)) / IF(v_PrevSuccessRateCount=0,1,v_PrevSuccessRateCount) * 100;
  
          	 
               	SELECT * FROM temp_AllqueueId;
                  
      					SELECT 	IFNULL(v_CurTotalCount,0) 																	AS 'TotalOutboundCall',
  							IFNULL(v_DiffTotalPercent,0) 																	AS 'DiffTotalPercent',
  							IFNULL(v_CurrentAnsweredCount,0) 																AS 'CurrentAnsweredeCount',
  							IFNULL(v_DiffAnsweredPercent,0) 																AS 'DiffAnsweredPercent',
 							IFNULL(v_CurrentUnAnsweredCount,0) 																AS 'CurrentUnAnsweredeCount',
  							IFNULL(v_DiffUnAnsweredPercent,0) 																AS 'DiffUnAnsweredPercent',
  							IFNULL(v_CurSuccessRateCount,0) 																AS 'CurrentSucessRate',
  							IFNULL(v_DiffUnAnsweredPercent,0) 																AS 'DiffSucessRatePercent',
 							IFNULL(v_CurrRightParty,0) 																		AS 'CurrRightPartyCount',
  							IFNULL(v_DiffRightParty,0) 																		AS 'DiffRightPartyCount';	
  						
  					
 						SELECT id,Time,queueName,outboundcalls,answeredCalls,unAnsweredCalls,SucessRate,RightParty
                         FROM (
                         SELECT 
 								0																											AS id,
 								'00:00:00 - 00:00:00'		 																				AS Time,
  								'All Queue'																									AS queueName,
  								IFNULL(v_CurTotalCount, 0) 					 																AS outboundcalls,
  								IFNULL(v_CurrentAnsweredCount, 0) 			 																AS answeredCalls,
  								IFNULL(v_CurrentUnAnsweredCount, 0) 		 																AS unAnsweredCalls,
  								IFNULL(v_CurSuccessRateCount,0) 																			AS SucessRate,
  								IFNULL(v_CurrRightParty,0) 																					AS RightParty
  						UNION ALL									
  						
 						SELECT
 								tnt.id 																										AS id,
 								CONCAT(tnt.startTime, ' - ', tnt.endTime) 																	AS Time,
 								U.queueName 																								AS queueName,
 								COUNT(CDH.Time) 																							AS outboundcalls,
 								SUM(CASE WHEN CDH.answeredCall > 0 THEN 1 ELSE 0 END) 														AS answeredCalls,
 								SUM(CASE WHEN CDH.answeredCall = 0 THEN 1 ELSE 0 END) 														AS unAnsweredCalls,
 								SUM(CASE WHEN CDH.dispositionName NOT LIKE '%wrong%' and CDH.answeredCall >0 THEN 1 ELSE 0 END) 
 										/ IF(COUNT(CDH.Time) = 0, 1, COUNT(CDH.Time)) 														AS SucessRate,
 								SUM(CASE WHEN CDH.dispositionName NOT LIKE '%wrong%' and CDH.dispositionName is not null and CDH.answeredCall >0 THEN 1 ELSE 0 END)			AS RightParty
 						FROM tt_interval tnt
 						LEFT OUTER JOIN temp_callHistory_calc CDH ON CDH.Time BETWEEN tnt.startTime AND tnt.endTime
 						LEFT JOIN temp_AllqueueId U ON CDH.QueueId = U.qid
 						GROUP BY tnt.id,tnt.startTime,tnt.endTime,U.queueName						                        
                         LIMIT v_offset, p_limit
                         ) Z 
                         ORDER BY id;
           
                        
          End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Voicemail_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Voicemail_analysis_metrics_filter`(
         p_startTmpstmp 	BIGINT,
         p_endTmpstmp 		BIGINT,
         p_domainId 		INT,    	
         p_queueId			VARCHAR(250),		
         p_offset 			INT,
         p_Limit 			INT	
     )
sp_return:BEGIN
     
     		DECLARE v_offset 					INT;	  	
     		DECLARE v_CurrentStartTmpstmp 		BIGINT;
     		DECLARE v_CurrentEndTmpstmp 		BIGINT;
     		DECLARE v_PrevStartTmpstmp 			BIGINT;
     		DECLARE v_PrevEndTmpstmp 			BIGINT; 
     		DECLARE v_TmpstmpInterval			BIGINT;	
     
     		DECLARE v_CurTotalCount 			INT;
     		DECLARE v_PrevTotalCount 			INT;
     		DECLARE	v_DiffTotalPercent 			INT;
     
     		DECLARE v_PrevVMAnsweredCount		INT;
     		DECLARE v_CurrentVMAnsweredCount	INT;
     		DECLARE v_DiffVMAnsweredPercent		INT;
     
     		DECLARE v_PrevVMAbandonedCount		INT;
     		DECLARE v_CurrentVMAbandonedCount	INT;
     		DECLARE v_DiffVMAbandonedPercent	INT;
     
     		DECLARE v_CurrentMissedCount		INT;
     		DECLARE v_CurrentTransferredCount	INT;
     		DECLARE v_TotalCallDuration			BIGINT;
     
   		DECLARE v_TotalTalktime             BIGINT;
   		DECLARE v_TotalAfterCallWorkTime    INT;
  		DECLARE v_Total_voicemail_length	BIGINT;
     
     		SET v_offset =  p_Limit * p_offset; 
         
         	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
         	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
         	
     		SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       
     		SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
     		SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
             
 		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
 		CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
             
       		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
             DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
             CREATE TEMPORARY TABLE temp_AllqueueId
             SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
             SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
             
     		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
     		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
     		CREATE TEMPORARY TABLE temp_callDurationHistory AS
     		SELECT		CH.sessionStartTime		
     					,CH.CallHistoryId        
     					,CDH.CallDurationHistoryId
     					,t_A.queueId
    					,(CDH.EndTime - CDH.StartTime)	                    	AS callDuration
						,CDH.afterCallWorkTime			                    	AS afterCallWorkTime
						,CH.IsInBound					                    	AS IsInBound
						,CDH.StartTime											AS agentconnecttime
    					,CDH.EndTime					   						AS agentDisconnectTime
						,DS.dispositionName
						,CH.voicemailUrl										AS voicemailUrl
						,CH.voiceMailDuration									AS voiceMailDuration
						,CH.isVoiceMailAnswered									AS isVoiceMailAnswered
						,CH.voiceMailAnsweredCallHistoryId						AS voiceMailAnsweredCallHistoryId
						,CDH.dispositionId										AS dispositionId
				FROM 		tb_CallHistory 			CH    
				JOIN 		tb_CallDurationHistory	CDH	    ON CH.CallHistoryId 		= CDH.CallHistoryId
     		
     	LEFT	JOIN 	temp_queueIds			    t_A		ON t_A.queueId 				= CH.assignedTo 
  		LEFT    JOIN 	disposition_status			DS		ON DS.did						= CDH.dispositionId
															AND DS.domainId = CH.domainId
     		WHERE 	CH.domainId 			= p_domainId 		
     		AND 	CH.IsInBound			= 1
     		AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
     		AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
     		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
             
     		DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
     		CREATE TEMPORARY TABLE temp_PrevCallHistory as
     		SELECT 	DISTINCT CallHistoryId
     		FROM 	temp_callDurationHistory
     		WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
     
     		DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
     		CREATE TEMPORARY TABLE temp_CurCallHistory AS
     		SELECT 	DISTINCT CallHistoryId
     		FROM 	temp_callDurationHistory
     		WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp; 
             
     		ALTER TABLE temp_PrevCallHistory ADD COLUMN isVoiceMailAnswered	TINYINT;
     		ALTER TABLE temp_CurCallHistory ADD COLUMN isVoiceMailAnswered	TINYINT;
             
  			UPDATE 	temp_PrevCallHistory CH
          	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
           	AND 	CDH.dispositionId IS NOT NULL
          	SET 	CH.isVoiceMailAnswered = 1;
              
          	UPDATE 	temp_CurCallHistory CH
          	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
           	AND 	CDH.dispositionId IS NOT NULL 
          	SET 	CH.isVoiceMailAnswered = 1;
             
  			SELECT 	COUNT(CallHistoryId), SUM(isVoiceMailAnswered)
  			INTO 	v_PrevTotalCount , v_PrevVMAnsweredCount
  			FROM	temp_PrevCallHistory;
  
  			SELECT 	COUNT(CallHistoryId), SUM(isVoiceMailAnswered)
  			INTO 	v_CurTotalCount , v_CurrentVMAnsweredCount 
  			FROM	temp_CurCallHistory;   
     
  			SELECT 	SUM(IFNULL(voiceMailDuration, 0))
  			INTO 	v_Total_voicemail_length
  			FROM 	temp_callDurationHistory;
              
           
     		SELECT 	SUM(IFNULL(CallHistoryId, 0))
     		INTO 	v_PrevVMAbandonedCount 
     		FROM	temp_callDurationHistory
     		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp and ifnull(voiceMailDuration,'')<>'' ;
     			 
     		SELECT 	SUM(IFNULL(CallHistoryId, 0))
     		INTO 	v_CurrentVMAbandonedCount 
     		FROM	temp_callDurationHistory
     		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp and ifnull(voiceMailDuration,'')<>'';
             
     		SET v_PrevTotalCount 			= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
     		SET v_PrevVMAnsweredCount 		= CASE WHEN v_PrevVMAnsweredCount = 0 then null else v_PrevVMAnsweredCount end;
     		SET v_PrevVMAbandonedCount 		= CASE WHEN v_PrevVMAbandonedCount = 0 then null else v_PrevVMAbandonedCount end;
     			
     		SET v_DiffTotalPercent 			= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
     		,	v_DiffVMAnsweredPercent		= (v_CurrentVMAnsweredCount - v_PrevVMAnsweredCount) / v_PrevVMAnsweredCount * 100
     		,	v_DiffVMAbandonedPercent	= (v_CurrentVMAbandonedCount - v_PrevVMAbandonedCount) / v_PrevVMAbandonedCount * 100;    
     	 
  		SELECT * FROM temp_AllqueueId;
             
             SELECT 	IFNULL(v_CurTotalCount,0) 			AS 'TotalCount',
          			IFNULL(v_DiffTotalPercent,0) 			AS 'DiffTotalPercent',
          			IFNULL(v_CurrentVMAnsweredCount,0) 		AS 'CurrentVMRespondedCount',
          			IFNULL(v_DiffVMAnsweredPercent,0) 		AS 'DiffVMRespondedPercent',
          			IFNULL(v_CurrentVMAbandonedCount,0) 	AS 'CurrentVMNotRespondedCount',
          			IFNULL(v_DiffVMAbandonedPercent,0) 		AS 'DiffVMNotRespondedPercent';	
           
  		select 
  			'All Queue'																				AS queueName
  			,IFNULL(v_CurTotalCount,0)                                  		    				AS VoicemailReceived
  			,IFNULL(v_CurrentVMAnsweredCount,0)                          							AS VoicemailResponded
  			,IFNULL(v_CurrentVMAbandonedCount,0)                         							AS VoicemailNotResponded
  			,IFNULL(v_Total_voicemail_length,0) 													AS Total_voicemail_length
  			,IFNULL((v_Total_voicemail_length) / (v_CurTotalCount),0)								AS Avg_voicemail_length
  		UNION ALL        
  		SELECT 	U.queueName																			AS queueName
  			,COUNT(1)																				AS VoicemailReceived
  			,SUM(CASE WHEN CDH.voiceMailDuration IS NOT NULL THEN 1 ELSE 0 END)						AS VoicemailResponded
  			,SUM(CASE WHEN CDH.voiceMailDuration IS NULL THEN 1 ELSE 0 END)							AS VoicemailNotResponded
  			,SUM(voiceMailDuration)																	AS Total_voicemail_length
  			,IFNULL(sum(voiceMailDuration) /1000,0)													AS Avg_voicemail_length  
  		FROM 	temp_callDurationHistory 	CDH
 		JOIN 	temp_AllqueueId				U	ON CDH.queueId	= U.qid	
  		
  		GROUP BY  U.queueName;    
             
     End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Voicemail_analysis_metrics_filter_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Voicemail_analysis_metrics_filter_1`(
        p_startTmpstmp 	BIGINT,
        p_endTmpstmp 	BIGINT,
        p_domainId 		INT,    	
        p_queueId		VARCHAR(250),		
        p_offset 		INT,
        p_Limit 		INT	
    )
sp_return:BEGIN
    
    		DECLARE v_offset 					INT;	  	
    		DECLARE v_CurrentStartTmpstmp 		BIGINT;
    		DECLARE v_CurrentEndTmpstmp 		BIGINT;
    		DECLARE v_PrevStartTmpstmp 			BIGINT;
    		DECLARE v_PrevEndTmpstmp 			BIGINT; 
    		DECLARE v_TmpstmpInterval			BIGINT;	
    
    		DECLARE v_CurTotalCount 			INT;
    		DECLARE v_PrevTotalCount 			INT;
    		DECLARE	v_DiffTotalPercent 			INT;
    
    		DECLARE v_PrevVMAnsweredCount		INT;
    		DECLARE v_CurrentVMAnsweredCount	INT;
    		DECLARE v_DiffVMAnsweredPercent		INT;
    
    		DECLARE v_PrevVMAbandonedCount		INT;
    		DECLARE v_CurrentVMAbandonedCount	INT;
    		DECLARE v_DiffVMAbandonedPercent	INT;
    
    		DECLARE v_CurrentMissedCount		INT;
    		DECLARE v_CurrentTransferredCount	INT;
    		DECLARE v_TotalCallDuration			BIGINT;
    
  		DECLARE v_TotalTalktime             BIGINT;
  		DECLARE v_TotalAfterCallWorkTime    INT;
 		DECLARE v_Total_voicemail_length	BIGINT;
    
    		SET v_offset =  p_Limit * p_offset; 
        
        	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
        	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
        	
    		SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
      
    		SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
    		SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            
		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
		CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
            
      		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
            DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
            CREATE TEMPORARY TABLE temp_AllqueueId
            SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
            SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
            
    		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    		DROP TEMPORARY TABLE IF EXISTS temp_callDurationHistory; 
    		CREATE TEMPORARY TABLE temp_callDurationHistory AS
    		SELECT		CH.sessionStartTime	
						,t_A.queueName			AS queueName
    					,CH.CallHistoryId        
    					,CDH.CallDurationHistoryId
    					,t_A.queueId
   					,(CDH.EndTime - CDH.StartTime)	                    AS callDuration
 					,CDH.afterCallWorkTime			                    AS afterCallWorkTime
 					,CH.IsInBound					                    AS IsInBound
  					,CDH.StartTime										AS agentconnecttime
   					,CDH.EndTime					   					AS agentDisconnectTime
 					,DS.dispositionName
                     ,CH.voicemailUrl									AS voicemailUrl
                     ,CH.voiceMailDuration								AS voiceMailDuration
                     ,CH.isVoiceMailAnswered								AS isVoiceMailAnswered
 					,CH.voiceMailAnsweredCallHistoryId					AS voiceMailAnsweredCallHistoryId
                     ,CDH.dispositionId									AS dispositionId
    		FROM 		tb_CallHistory 			CH    
    		 JOIN 	tb_CallDurationHistory	    CDH	    		ON CH.CallHistoryId 		= CDH.CallHistoryId
    	     JOIN 	tb_CallMessage				CM				ON CH.CallHistoryId 		= CM.CallHistoryId and CM.CallDurationHistoryId	= CDH.CallDurationHistoryId
    	LEFT JOIN 	temp_queueIds				t_A				ON t_A.queueId 				= CH.assignedTo 
 		LEFT JOIN 	disposition_status		    DS				ON DS.did						= CDH.dispositionId and DS.domainId = CH.domainId
    		WHERE 	CH.domainId 			= p_domainId 		
    		AND 	CH.IsInBound			= 1
    		AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
    		AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
    		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;  
            select * from temp_callDurationHistory;
    		DROP TEMPORARY TABLE IF EXISTS temp_PrevCallHistory; 
    		CREATE TEMPORARY TABLE temp_PrevCallHistory as
    		SELECT 	DISTINCT CallHistoryId
    		FROM 	temp_callDurationHistory
    		WHERE 	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp and ifnull(voiceMailDuration,'')<>'';
    
    		DROP TEMPORARY TABLE IF EXISTS temp_CurCallHistory; 
    		CREATE TEMPORARY TABLE temp_CurCallHistory AS
    		SELECT 	DISTINCT CallHistoryId
    		FROM 	temp_callDurationHistory
    		WHERE 	sessionStartTime BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp and ifnull(voiceMailDuration,'')<>'';   
            
    		ALTER TABLE temp_PrevCallHistory ADD COLUMN isVoiceMailAnswered	TINYINT;
    		ALTER TABLE temp_CurCallHistory ADD COLUMN isVoiceMailAnswered	TINYINT;
            
 			UPDATE 	temp_PrevCallHistory CH
         	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
         	AND 	CDH.dispositionId IS NOT NULL and ifnull(voiceMailDuration,'')<>'' and CDH.isVoiceMailAnswered = 1
         	SET 	CH.isVoiceMailAnswered = 1;
             
         	UPDATE 	temp_CurCallHistory CH
         	JOIN	temp_callDurationHistory CDH ON CH.CallHistoryId = CDH.CallHistoryId
         	AND 	CDH.dispositionId IS NOT NULL and ifnull(voiceMailDuration,'')<>'' and CDH.isVoiceMailAnswered = 1
         	SET 	CH.isVoiceMailAnswered = 1;
            
 			SELECT 	COUNT(CallHistoryId), SUM(isVoiceMailAnswered)
 			INTO 	v_PrevTotalCount , v_PrevVMAnsweredCount
 			FROM	temp_PrevCallHistory;
 
 			SELECT 	COUNT(CallHistoryId), SUM(isVoiceMailAnswered)
 			INTO 	v_CurTotalCount , v_CurrentVMAnsweredCount 
 			FROM	temp_CurCallHistory;   
    
 			SELECT 	SUM(IFNULL(voiceMailDuration, 0))
 			INTO 	v_Total_voicemail_length
 			FROM 	temp_callDurationHistory;
             
          
    		SELECT 	SUM(IFNULL(CallHistoryId, 0))
    		INTO 	v_PrevVMAbandonedCount 
    		FROM	temp_callDurationHistory
    		WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp and ifnull(voiceMailDuration,'')<>'' and isVoiceMailAnswered = 0;
    			 
    		SELECT 	SUM(IFNULL(CallHistoryId, 0))
    		INTO 	v_CurrentVMAbandonedCount 
    		FROM	temp_callDurationHistory
    		WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp and ifnull(voiceMailDuration,'')<>'' and isVoiceMailAnswered = 0;
            
    		SET v_PrevTotalCount 			= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
    		SET v_PrevVMAnsweredCount 		= CASE WHEN v_PrevVMAnsweredCount = 0 then null else v_PrevVMAnsweredCount end;
    		SET v_PrevVMAbandonedCount 		= CASE WHEN v_PrevVMAbandonedCount = 0 then null else v_PrevVMAbandonedCount end;
    			
    		SET v_DiffTotalPercent 			= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
    		,	v_DiffVMAnsweredPercent		= (v_CurrentVMAnsweredCount - v_PrevVMAnsweredCount) / v_PrevVMAnsweredCount * 100
    		,	v_DiffVMAbandonedPercent	= (v_CurrentVMAbandonedCount - v_PrevVMAbandonedCount) / v_PrevVMAbandonedCount * 100;    
    	 
 		SELECT * FROM temp_AllqueueId;
            
            SELECT 	IFNULL(v_CurTotalCount,0) 				AS 'TotalCount',
         			IFNULL(v_DiffTotalPercent,0) 			AS 'DiffTotalPercent',
         			IFNULL(v_CurrentVMAnsweredCount,0) 		AS 'CurrentVMAnsweredeCount',
         			IFNULL(v_DiffVMAnsweredPercent,0) 		AS 'DiffVMAnsweredPercent',
         			IFNULL(v_CurrentVMAbandonedCount,0) 	AS 'CurrentVMAbandonedCount',
         			IFNULL(v_DiffVMAbandonedPercent,0) 		AS 'DiffVMAbandonedPercent';	
          
 		select 
 			'All Queue'																				AS queueName
 			,IFNULL(v_CurTotalCount,0)                                  		    				AS VoicemailReceived
 			,IFNULL(v_CurrentVMAnsweredCount,0)                          							AS VoicemailResponded
 			,IFNULL(v_CurrentVMAbandonedCount,0)                         							AS VoicemailNotResponded
 			,IFNULL(v_Total_voicemail_length,0) 													AS Total_voicemail_length
 			,IFNULL((v_Total_voicemail_length) / (v_CurTotalCount),0)								AS Avg_voicemail_length
 		union all        
 		SELECT 	CDH.queueName																			AS queueName
 				,COUNT(1)																			AS VoicemailReceived
 				,SUM(CASE WHEN CDH.voiceMailDuration IS NOT NULL THEN 1 ELSE 0 END)					AS VoicemailResponded
 				,SUM(CASE WHEN CDH.voiceMailDuration IS NULL THEN 1 ELSE 0 END)						AS VoicemailNotResponded
 				,SUM(voiceMailDuration)																AS Total_voicemail_length
 				,IFNULL(sum(voiceMailDuration) /1000,0)												AS Avg_voicemail_length  
 		FROM 	temp_callDurationHistory 	CDH
	
 		
 		GROUP BY  U.queueName;    
            
    End ;;
DELIMITER ;
