/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Whatapp_Inbound_analysis_metrics_filter`(
         p_startTmpstmp 		BIGINT,
         p_endTmpstmp 		BIGINT,
         p_domainId 			INT,    	
         p_queueId			TEXT,	       
         p_offset 			INT,
         p_Limit 			INT	)
sp_return:BEGIN
    		DECLARE v_offset 								INT;	  	
    		DECLARE v_CurrentStartTmpstmp 					BIGINT;
    		DECLARE v_CurrentEndTmpstmp 					BIGINT;
    		DECLARE v_PrevStartTmpstmp 						BIGINT;
    		DECLARE v_PrevEndTmpstmp 						BIGINT; 
    		DECLARE v_TmpstmpInterval						BIGINT;	
       		
        		DECLARE v_CurTotalCount 					INT;
        		DECLARE v_PrevTotalCount 					INT;
        		DECLARE	v_DiffTotalPercent 					INT;
    			
    			DECLARE v_PrevRespondedCount			    INT;	
    			DECLARE v_CurrentRespondedCount			    INT;	        
    			DECLARE v_DiffRespondedPercent			    INT;
    			
        		DECLARE v_PrevAbandonedCount				INT;
        		DECLARE v_CurrentAbandonedCount				INT;
        		DECLARE v_DiffAbandonedPercent				INT;
    			
        		DECLARE v_CurrentMissedCount				INT;
        		DECLARE v_CurrentTransferredCount			INT;
        		DECLARE v_TotalChatDuration					BIGINT;
    			
    
    			DECLARE v_CurrentMaximumChatdurationCount	INT;
    			DECLARE v_CurrentAverageChatdurationCount	INT;
                DECLARE v_TotalTalktime             		BIGINT;
    			DECLARE v_TotalAfterCallWorkTime    		INT;
    			DECLARE v_CurrentCallHoldTime       		INT;
    			DECLARE v_CurrentAvailableTime      		INT;
    			DECLARE v_CurrentCustomerWhatAppCount		INT;
    			DECLARE v_CurrentAgentWhatAppCount			INT;           
    			DECLARE v_SentimentalScore          		INT;
    			DECLARE v_CurrentFirstCallResolution        INT;
         	
       	SET v_offset =  p_Limit * p_offset; 
         
     	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
     	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
         	
       	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
       
       	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
       	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
         		
      	 		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
 		        CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
     		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                  	
                         
                           		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                       		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                       		(    DispositionId 			INT
                       			,DispositionStatus 		VARCHAR(100)
                       			,DispositionCategory	TINYINT
                       		); 
                               
                       		INSERT INTO temp_AvailableDisposition 
                       		SELECT 	did 			DispositionId
                       			,	dispositionName	DispositionStatus
                       			,	CASE WHEN dispositionName = 'Opened'				THEN 2
                       				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                       				WHEN dispositionName = 'Discarded'     				THEN 4
    								    WHEN dispositionName = 'Resolved'      				THEN 5
                                     WHEN dispositionName = 'Caller Disconnected'		THEN 6
                       				END 			DispositionCategory
                       		FROM 	disposition_status   
                       		WHERE 	domainId	= p_domainId;
                             
 					DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
 					CREATE TEMPORARY TABLE temp_queueIDs
 					SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
  
 					DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                     CREATE TEMPORARY TABLE temp_AllagentId
                     SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
  
  
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
    			DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory; 
    			CREATE TEMPORARY TABLE temp_WhatAppHistory AS
    		    SELECT 	CH.sessionStartTime		
      				,	CH.WhatsappHistoryId        
      				,	CDH.WhatsappDurationHistoryId
      				,	CDH.QueueId
      				,	CH.Istransferred
      				,	CH.dispositionId
      			    ,   CH.IsInBound
      				,	(CH.sessionEndTime - CH.sessionStartTime)	                         					AS WhatAppDuration
      				,   CDH.IsMissed													     					AS missedWhatApp
      				,	CH.customerNumber
      				,	CH.afterwhatsappWorkTime
      			
      				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                	 				 AS discarded
      				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                	 				 AS firstWhatAppResolution 
 					, CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		     	     				 AS HandledTime
 					, CDH.dialDuration				  				    	     			     				 AS responseTime
 					, CH.SentimentalScore				
                     , CASE WHEN t_D.DispositionCategory = 6 THEN 1 ELSE 0 END                                    AS IsAbandoned     
                     , CASE WHEN CDH.Duration	is not null then Duration else 0 end			 				 AS chatduration
    			FROM 		tb_WhatsappHistory 			CH
    			 JOIN 	tb_WhatsappDurationHistory	CDH			ON 	CH.WhatsappHistoryId 	= CDH.WhatsappHistoryId
    			LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
    			LEFT JOIN tb_User					U			ON 	U.UserID				= CDH.QueueId
 														
    			LEFT JOIN temp_queueIds 			t_A 		ON 	U.UserID 			    = t_A.queueId 
    			WHERE 	CH.domainId 			= p_domainId 		
    		  	AND 	CH.IsInBound			= 1
    			AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
    			AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
    			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       
    			DROP TEMPORARY TABLE IF EXISTS temp_PrevWhatAppHistory; 
    			CREATE TEMPORARY TABLE temp_PrevWhatAppHistory as
    			SELECT 	DISTINCT WhatsappHistoryId 
    			FROM 	temp_WhatAppHistory
    			WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
    				
    			DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
    			CREATE TEMPORARY TABLE temp_CurChatHistory AS
    			SELECT 	DISTINCT WhatsappHistoryId 
    			FROM 	temp_WhatAppHistory
    			WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;   
                       
    
    				    DROP TEMPORARY TABLE IF EXISTS temp_whatappHistory_calc; 
      					CREATE TEMPORARY TABLE temp_whatappHistory_calc AS 	     
    					SELECT 	
    						t_SH.sessionStartTime,
    						t_SH.WhatsappHistoryId,
    						t_SH.WhatsappDurationHistoryId,
    						t_SH.QueueId,
    						t_SH.responseTime,
    						t_SH.missedWhatApp,
    						t_SH.IsInBound,
    						t_SH.Istransferred,
    						t_SH.dispositionId,
    						t_SH.WhatAppDuration,
    						SUM(t_SH.afterwhatsappWorkTime) 														AS afterwhatsappWorkTime,
    					
    						t_SH.SentimentalScore,									
    						COUNT(t_SH.QueueId) 																	AS InteractionwithAgent,
    						COUNT(DISTINCT t_SH.customerNumber)														AS InteractionWithCustomer,
    						t_SH.discarded 																			AS discardedWhatApp,
    						t_SH.IsAbandoned,									
    						SUM(t_SH.chatduration) 																	AS totalChatduration,
    						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
    					FROM temp_WhatAppHistory t_SH
    					GROUP BY  t_SH.sessionStartTime,t_SH.WhatsappHistoryId,t_SH.WhatsappDurationHistoryId,t_SH.QueueId,t_SH.missedWhatApp,t_SH.IsInBound,
    						t_SH.Istransferred,t_SH.dispositionId,t_SH.WhatAppDuration,t_SH.SentimentalScore,t_SH.responseTime,t_SH.discarded,t_SH.IsAbandoned;
    
    		DROP TEMPORARY TABLE IF EXISTS temp_CurWhatAppHistory; 
        	CREATE TEMPORARY TABLE temp_CurWhatAppHistory AS
          	SELECT 	DISTINCT WhatsappHistoryId 
          	FROM 	temp_whatappHistory_calc
          	WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;    
                                
            SELECT 	COUNT(WhatsappHistoryId), SUM(responseTime),sum(IsAbandoned)
            INTO 	v_PrevTotalCount ,v_PrevRespondedCount,v_PrevAbandonedCount
      		FROM	temp_whatappHistory_calc;
              
            SELECT 	COUNT(WhatsappHistoryId),SUM(responseTime),sum(IsAbandoned)
            INTO 	v_curTotalCount ,v_CurrentRespondedCount,v_CurrentAbandonedCount	
      		FROM	temp_whatappHistory_calc;   
              
              
            SELECT SUM(missedWhatApp), SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent)
       	    INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_CurrentCustomerWhatAppCount, v_CurrentAgentWhatAppCount
       	    FROM 	temp_whatappHistory_calc;
              
      		SELECT sum(avgChatduration),sum(totalChatduration)
       	    INTO 	v_CurrentAverageChatdurationCount, v_CurrentMaximumChatdurationCount
       	    FROM 	temp_whatappHistory_calc;         
            
                SET v_PrevTotalCount 	= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
        		SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
        		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
        			
        		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
        		,	v_DiffRespondedPercent	= (v_CurrentRespondedCount	 - v_PrevRespondedCount) / v_PrevRespondedCount * 100
        		,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100; 
    
 
                     SELECT * FROM temp_queueIDs;
                
                SELECT 	IFNULL(v_CurTotalCount,0) 		    AS 'TotalReceivedCount',
             			IFNULL(v_DiffTotalPercent,0) 		AS 'DiffTotalReceivedPercent',
             			IFNULL(v_CurrentRespondedCount,0) 	AS 'CurrentAnsweredeCount',
             			IFNULL(v_DiffRespondedPercent,0) 	AS 'DiffAnsweredPercent',
             			IFNULL(v_CurrentAbandonedCount,0) 	AS 'CurrentAbandonedCount',
             			IFNULL(v_DiffAbandonedPercent,0) 	AS 'DiffAbandonedPercent';	
        
            
               SELECT
               	'All Queue'																						AS queueName                
 			   ,IFNULL(v_CurTotalCount,0)                                    									AS receivedchats
 			   ,IFNULL(v_CurrentRespondedCount,0)                            									AS responseTime
                ,IFNULL(v_CurrentAbandonedCount,0)                                                              AS abondedchats
    			   ,IFNULL(v_CurrentMissedCount,0)                               								AS MissedChat
                ,IFNULL(v_CurrentTransferredCount,0)                          									AS transferredchat
                ,IFNULL(v_TotalChatDuration,0)                   									            AS totalChatduration
                ,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS avgChatduration
                ,IFNULL(v_CurrentCustomerWhatAppCount,0)								    					AS interactionfromcustomer
                ,IFNULL(v_CurrentAgentWhatAppCount,0)															AS interactionfromagent
                ,IFNULL(v_CurrentCustomerWhatAppCount,0) + IFNULL(v_CurrentAgentWhatAppCount,0)					AS totalinteraction
    
            UNION ALL
         	SELECT 	U.queueName														    						AS queueName        
    			 ,	COUNT(1)														    					   	AS receivedchats
    			 ,	SUM(CDH.responseTime)	    						                                       	AS responseTime
                 ,  SUM(CDH.IsAbandoned)                                                                        AS abondedchats
                 ,	SUM(CDH.missedWhatApp)																		AS MissedChat  
                 ,	SUM(CDH.Istransferred)																		AS transferredchat
                 ,	sum(CDH.totalChatduration)																    AS totalChatduration
                 ,	sum(CDH.avgChatduration) / COUNT(1)														    AS avgChatduration
                 ,	SUM(CDH.InteractionWithCustomer)															AS interactionfromcustomer
                 ,	SUM(CDH.InteractionwithAgent)																AS interactionfromagent
                 ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						    AS totalinteraction
    
             FROM 	temp_whatappHistory_calc 	  CDH
             JOIN 	temp_queueIDs				U	ON CDH.QueueId	= U.qid	
             WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
             GROUP BY U.queueName;       
              
             SELECT CONCAT('queueName','receivedchats','responseTime','abondedchats','MissedChat','transferredchat','totalChatduration',
      					'avgChatduration','interactionfromcustomer','interactionfromagent','totalinteraction') AS  columnName;          
              
              
                
       	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Whatapp_Inbound_analysis_metrics_filter_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Queue_Whatapp_Inbound_analysis_metrics_filter_1`(
        p_startTmpstmp 		BIGINT,
        p_endTmpstmp 		BIGINT,
        p_domainId 			INT,    	
        p_queueId			TEXT,	       
        p_offset 			INT,
        p_Limit 			INT	)
sp_return:BEGIN
   		DECLARE v_offset 								INT;	  	
   		DECLARE v_CurrentStartTmpstmp 					BIGINT;
   		DECLARE v_CurrentEndTmpstmp 					BIGINT;
   		DECLARE v_PrevStartTmpstmp 						BIGINT;
   		DECLARE v_PrevEndTmpstmp 						BIGINT; 
   		DECLARE v_TmpstmpInterval						BIGINT;	
      		
       		DECLARE v_CurTotalCount 					INT;
       		DECLARE v_PrevTotalCount 					INT;
       		DECLARE	v_DiffTotalPercent 					INT;
   			
   			DECLARE v_PrevRespondedCount			    INT;	
   			DECLARE v_CurrentRespondedCount			    INT;	        
   			DECLARE v_DiffRespondedPercent			    INT;
   			
       		DECLARE v_PrevAbandonedCount				INT;
       		DECLARE v_CurrentAbandonedCount				INT;
       		DECLARE v_DiffAbandonedPercent				INT;
   			
       		DECLARE v_CurrentMissedCount				INT;
       		DECLARE v_CurrentTransferredCount			INT;
       		DECLARE v_TotalChatDuration					BIGINT;
   			
   
   			DECLARE v_CurrentMaximumChatdurationCount	INT;
   			DECLARE v_CurrentAverageChatdurationCount	INT;
               DECLARE v_TotalTalktime             		BIGINT;
   			DECLARE v_TotalAfterCallWorkTime    		INT;
   			DECLARE v_CurrentCallHoldTime       		INT;
   			DECLARE v_CurrentAvailableTime      		INT;
   			DECLARE v_CurrentCustomerWhatAppCount		INT;
   			DECLARE v_CurrentAgentWhatAppCount			INT;           
   			DECLARE v_SentimentalScore          		INT;
   			DECLARE v_CurrentFirstCallResolution        INT;
        	
      	SET v_offset =  p_Limit * p_offset; 
        
    	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
    	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
        	
      	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
      
      	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
      	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
        		
     	 		DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
		        CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
    		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                 	
                        
                          		DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
                      		    CREATE TEMPORARY TABLE temp_AvailableDisposition 
                      		(    DispositionId 			INT
                      			,DispositionStatus 		VARCHAR(100)
                      			,DispositionCategory	TINYINT
                      		); 
                              
                      		INSERT INTO temp_AvailableDisposition 
                      		SELECT 	did 			DispositionId
                      			,	dispositionName	DispositionStatus
                      			,	CASE WHEN dispositionName = 'Opened'				THEN 2
                      				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
                      				WHEN dispositionName = 'Discarded'     				THEN 4
   								    WHEN dispositionName = 'Resolved'      				THEN 5
                                    WHEN dispositionName = 'Caller Disconnected'		THEN 6
                      				END 			DispositionCategory
                      		FROM 	disposition_status   
                      		WHERE 	domainId	= p_domainId;
                            
					DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
					CREATE TEMPORARY TABLE temp_queueIDs
					SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
 
					DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
                    CREATE TEMPORARY TABLE temp_AllagentId
                    SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
 
 
               SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
   			DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory; 
   			CREATE TEMPORARY TABLE temp_WhatAppHistory AS
   		    SELECT 	CH.sessionStartTime		
     				,	CH.WhatsappHistoryId        
     				,	CDH.WhatsappDurationHistoryId
     				,	CDH.QueueId
     				,	CH.Istransferred
     				,	CH.dispositionId
     			    ,   CH.IsInBound
     				,	(CH.sessionEndTime - CH.sessionStartTime)	                         					AS WhatAppDuration
     				,   CDH.IsMissed													     					AS missedWhatApp
     				,	CH.customerNumber
     				,	CH.afterwhatsappWorkTime
     			
     				, CASE WHEN t_D.DispositionCategory = 4 THEN 1 ElSE 0 END                	 				 AS discarded
     				, CASE WHEN t_D.DispositionCategory = 5 THEN 1 ElSE 0 END                	 				 AS firstWhatAppResolution 
					, CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END 		     	     				 AS HandledTime
					, CDH.dialDuration				  				    	     			     				 AS responseTime
					, CH.SentimentalScore				
                    , CASE WHEN t_D.DispositionCategory = 6 THEN 1 ELSE 0 END                                    AS IsAbandoned     
                    , CASE WHEN CDH.Duration	is not null then Duration else 0 end			 				 AS chatduration
   			FROM 		tb_WhatsappHistory 			CH
   			 JOIN 	tb_WhatsappDurationHistory	CDH			ON 	CH.WhatsappHistoryId 	= CDH.WhatsappHistoryId
   			LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
   			LEFT JOIN tb_User					U			ON 	U.UserID				= CDH.QueueId
														
   			LEFT JOIN temp_queueIds 			t_A 		ON 	U.UserID 			    = t_A.queueId 
   			WHERE 	CH.domainId 			= p_domainId 		
   		  	AND 	CH.IsInBound			= 1
   			AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
   			AND 	(IFNULL(p_queueId,'') 	= '' OR (IFNULL(p_queueId,'') <> '' AND t_A.queueId IS NOT NULL));  
   			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      select * from temp_WhatAppHistory;
      
      
   			DROP TEMPORARY TABLE IF EXISTS temp_PrevWhatAppHistory; 
   			CREATE TEMPORARY TABLE temp_PrevWhatAppHistory as
   			SELECT 	DISTINCT WhatsappHistoryId 
   			FROM 	temp_WhatAppHistory
   			WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
   				
   			DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
   			CREATE TEMPORARY TABLE temp_CurChatHistory AS
   			SELECT 	DISTINCT WhatsappHistoryId 
   			FROM 	temp_WhatAppHistory
   			WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;   
                      
   
   				    DROP TEMPORARY TABLE IF EXISTS temp_whatappHistory_calc; 
     					CREATE TEMPORARY TABLE temp_whatappHistory_calc AS 	     
   					SELECT 	
   						t_SH.sessionStartTime,
   						t_SH.WhatsappHistoryId,
   						t_SH.WhatsappDurationHistoryId,
   						t_SH.QueueId,
   						t_SH.responseTime,
   						t_SH.missedWhatApp,
   						t_SH.IsInBound,
   						t_SH.Istransferred,
   						t_SH.dispositionId,
   						t_SH.WhatAppDuration,
   						SUM(t_SH.afterwhatsappWorkTime) 														AS afterwhatsappWorkTime,
   					
   						t_SH.SentimentalScore,									
   						COUNT(t_SH.QueueId) 																	AS InteractionwithAgent,
   						COUNT(DISTINCT t_SH.customerNumber)														AS InteractionWithCustomer,
   						t_SH.discarded 																			AS discardedWhatApp,
   						t_SH.IsAbandoned,									
   						SUM(t_SH.chatduration) 																	AS totalChatduration,
   						CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
   					FROM temp_WhatAppHistory t_SH
   					GROUP BY  t_SH.sessionStartTime,t_SH.WhatsappHistoryId,t_SH.WhatsappDurationHistoryId,t_SH.QueueId,t_SH.missedWhatApp,t_SH.IsInBound,
   						t_SH.Istransferred,t_SH.dispositionId,t_SH.WhatAppDuration,t_SH.SentimentalScore,t_SH.responseTime,t_SH.discarded,t_SH.IsAbandoned;
   
   		DROP TEMPORARY TABLE IF EXISTS temp_CurWhatAppHistory; 
       	CREATE TEMPORARY TABLE temp_CurWhatAppHistory AS
         	SELECT 	DISTINCT WhatsappHistoryId 
         	FROM 	temp_whatappHistory_calc
         	WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;    
                               
           SELECT 	COUNT(WhatsappHistoryId), SUM(responseTime),sum(IsAbandoned)
           INTO 	v_PrevTotalCount ,v_PrevRespondedCount,v_PrevAbandonedCount
     		FROM	temp_whatappHistory_calc;
             
           SELECT 	COUNT(WhatsappHistoryId),SUM(responseTime),sum(IsAbandoned)
           INTO 	v_curTotalCount ,v_CurrentRespondedCount,v_CurrentAbandonedCount	
     		FROM	temp_whatappHistory_calc;   
             
             
           SELECT SUM(missedWhatApp), SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent)
      	    INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_CurrentCustomerWhatAppCount, v_CurrentAgentWhatAppCount
      	    FROM 	temp_whatappHistory_calc;
             
     		SELECT sum(avgChatduration),sum(totalChatduration)
      	    INTO 	v_CurrentAverageChatdurationCount, v_CurrentMaximumChatdurationCount
      	    FROM 	temp_whatappHistory_calc;         
           
               SET v_PrevTotalCount 	= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
       		SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
       		SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
       			
       		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
       		,	v_DiffRespondedPercent	= (v_CurrentRespondedCount	 - v_PrevRespondedCount) / v_PrevRespondedCount * 100
       		,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100; 
   

                    SELECT * FROM temp_queueIDs;
               
               SELECT 	IFNULL(v_CurTotalCount,0) 		    AS 'TotalReceivedCount',
            			IFNULL(v_DiffTotalPercent,0) 		AS 'DiffTotalReceivedPercent',
            			IFNULL(v_CurrentRespondedCount,0) 	AS 'CurrentAnsweredeCount',
            			IFNULL(v_DiffRespondedPercent,0) 	AS 'DiffAnsweredPercent',
            			IFNULL(v_CurrentAbandonedCount,0) 	AS 'CurrentAbandonedCount',
            			IFNULL(v_DiffAbandonedPercent,0) 	AS 'DiffAbandonedPercent';	
       
           
              SELECT
              	'All Queue'																						AS QueueName                
			   ,IFNULL(v_CurTotalCount,0)                                    									AS receivedChat
			   ,IFNULL(v_CurrentRespondedCount,0)                            									AS respondedChat
               ,IFNULL(v_CurrentAbandonedCount,0)                                                               AS abandonedChat
   			   ,IFNULL(v_CurrentMissedCount,0)                               									AS missedChat
               ,IFNULL(v_CurrentTransferredCount,0)                          									AS transferredChat
               ,IFNULL(v_TotalChatDuration,0)                   									            AS TotalChatDuration
               ,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS AverageChatDuration
               ,IFNULL(v_CurrentCustomerWhatAppCount,0)								    						AS InteractionWithCustomer
               ,IFNULL(v_CurrentAgentWhatAppCount,0)															AS InteractionWithAgent
               ,IFNULL(v_CurrentCustomerWhatAppCount,0) + IFNULL(v_CurrentAgentWhatAppCount,0)					AS totalInteraction
   
           UNION ALL
        	SELECT 	U.queueName														    						AS QueueName
   			 ,	COUNT(1)														    					   		AS receivedChat
   			 ,	SUM(CDH.responseTime)	    						                                       		AS respondedChat
                ,  SUM(CDH.IsAbandoned)                                                                         AS abandonedChat
                ,	SUM(CDH.missedWhatApp)																		AS missedSChat        
                ,	SUM(CDH.Istransferred)																		AS transferredChat
                ,	sum(CDH.totalChatduration)																    AS TotalChatDuration
                ,	sum(CDH.avgChatduration) / COUNT(1)														    AS AverageChatDuration
                ,	SUM(CDH.InteractionWithCustomer)															AS InteractionWithCustomer
                ,	SUM(CDH.InteractionwithAgent)																AS InteractionWithAgent
                ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						    AS totalInteraction
   
            FROM 	temp_whatappHistory_calc 	  CDH
            JOIN 	temp_queueIDs				U	ON CDH.QueueId	= U.qid	
            WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
            GROUP BY U.queueName;       
             
            SELECT CONCAT('QueueName','receivedChat','respondedChat','missedChat','missedCalls','transferredChat','TotalChatDuration',
     					'AverageChatDuration','InteractionWithCustomer','InteractionWithAgent','totalInteraction') AS  columnName;          
             
             
               
      	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Whatapp_Inbound_analysis_metrics_filter_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Whatapp_Inbound_analysis_metrics_filter_test`(
          p_startTmpstmp 		BIGINT,
          p_endTmpstmp 		BIGINT,
          p_domainId 			INT,    	
          p_queueId			TEXT,	       
          p_offset 			INT,
          p_Limit 			INT	)
sp_return:BEGIN
			DECLARE v_offset 								INT;	  	
			DECLARE v_CurrentStartTmpstmp 					BIGINT;
			DECLARE v_CurrentEndTmpstmp 					BIGINT;
			DECLARE v_PrevStartTmpstmp 						BIGINT;
			DECLARE v_PrevEndTmpstmp 						BIGINT; 
			DECLARE v_TmpstmpInterval						BIGINT;	

			DECLARE v_CurTotalCount 					INT;
			DECLARE v_PrevTotalCount 					INT;
			DECLARE	v_DiffTotalPercent 					INT;

			DECLARE v_PrevRespondedCount			    INT;	
			DECLARE v_CurrentRespondedCount			    INT;	        
			DECLARE v_DiffRespondedPercent			    INT;

			DECLARE v_PrevAbandonedCount				INT;
			DECLARE v_CurrentAbandonedCount				INT;
			DECLARE v_DiffAbandonedPercent				INT;

			DECLARE v_CurrentMissedCount				INT;
			DECLARE v_CurrentTransferredCount			INT;
			DECLARE v_TotalChatDuration					BIGINT;

			DECLARE v_CurrentMaximumChatdurationCount	INT;
			DECLARE v_CurrentAverageChatdurationCount	INT;
			DECLARE v_CurrentCustomerWhatAppCount		INT;
			DECLARE v_CurrentAgentWhatAppCount			INT;           
          	
        	SET v_offset =  p_Limit * p_offset; 
          
			IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
			IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
          	
        	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
        
        	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
        	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
          		
			DROP TEMPORARY TABLE IF EXISTS temp_inputQueue;	CREATE TEMPORARY TABLE temp_inputQueue(t_queueId VARCHAR(100));
			CALL split(p_queueId,','); INSERT INTO temp_inputQueue(t_queueId) SELECT Items FROM tt_Split_temptable; 
			DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
                          
				DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
				CREATE TEMPORARY TABLE temp_AvailableDisposition 
			(    DispositionId 			INT
				,DispositionStatus 		VARCHAR(100)
				,DispositionCategory	TINYINT
			); 
                                
			INSERT INTO temp_AvailableDisposition 
			SELECT 	did 			DispositionId
				,	dispositionName	DispositionStatus
				,	CASE WHEN dispositionName = 'Opened'				THEN 2
					WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Disconnected','Transferred') THEN 3
					WHEN dispositionName = 'Discarded'     				THEN 4
					WHEN dispositionName = 'Resolved'      				THEN 5
					WHEN dispositionName = 'Caller Disconnected'		THEN 6
					END 			DispositionCategory
			FROM 	disposition_status   
			WHERE 	domainId	= p_domainId;
                              
			DROP TEMPORARY TABLE IF EXISTS temp_queueIDs;	
			CREATE TEMPORARY TABLE temp_queueIDs
			SELECT qid , name AS queueName FROM queue WHERE domainId = p_domainId;

			DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
			CREATE TEMPORARY TABLE temp_AllagentId
			SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
   
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
			DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory; 
			CREATE TEMPORARY TABLE temp_WhatAppHistory AS
			SELECT CH.WhatsappHistoryId        
			,	CDH.QueueId
			,	CH.Istransferred
			,	CH.dispositionId
			,   CH.IsInBound
			,   CDH.IsMissed													     					
			,	CH.customerNumber
			,	CH.afterwhatsappWorkTime
            ,	CH.customerId
            ,	CDH.Duration
            ,	t_D.DispositionCategory
            ,	Q_T.queueName
            ,	CASE WHEN CDH.Duration > 0 THEN 1 ELSE 0 END 				AS respondedChats
            ,	CASE WHEN t_D.DispositionCategory = 6 THEN 1 ELSE 0 END 	AS IsAbandoned  
			FROM 	tb_WhatsappHistory 			CH
			JOIN 	tb_WhatsappDurationHistory	CDH			ON 	CH.WhatsappHistoryId 	= CDH.WhatsappHistoryId
			LEFT JOIN temp_AvailableDisposition	t_D			ON 	CH.dispositionId	    = t_D.DispositionId
			JOIN 	temp_queueIDs 				Q_T 		ON 	CDH.QueueId 			= Q_T.qid 
			WHERE 	CH.domainId 			= p_domainId 		
			AND 	CH.IsInBound			= 1
			AND 	CH.sessionStartTime 	BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
			AND 	((IFNULL(p_queueId,'') 	= '' ) OR (SELECT t_queueId FROM temp_inputQueue));  
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

			SELECT 'temp_WhatAppHistory',a.* FROM temp_WhatAppHistory a;
                        
			DROP TEMPORARY TABLE IF EXISTS temp_whatappHistory_calc; 
			CREATE TEMPORARY TABLE temp_whatappHistory_calc AS 	     
			SELECT 	
				SUM(t_SH.WhatsappHistoryId) AS totalReceivedChats,
                SUM(Duration) AS respondedChats,
                SUM(IsAbandoned) AS abandonedChats,
				SUM(IsMissed) as missedChats,
				SUM(Istransferred) as transferredChats, 
				t_SH.missedWhatApp,
				t_SH.IsInBound,
				t_SH.Istransferred,
				t_SH.dispositionId,
				t_SH.WhatAppDuration,
				SUM(t_SH.afterwhatsappWorkTime) 														AS afterwhatsappWorkTime,
				COUNT(t_SH.QueueId) 																	AS InteractionwithAgent,
				COUNT(DISTINCT t_SH.customerNumber)														AS InteractionWithCustomer,
				t_SH.IsAbandoned,									
				SUM(t_SH.chatduration) 																	AS totalChatduration,
				CASE WHEN AVG(t_SH.chatduration) IS NOT NULL THEN AVG(t_SH.chatduration) ELSE 0 END     AS avgChatduration
			FROM temp_WhatAppHistory t_SH
			GROUP BY  t_SH.sessionStartTime,t_SH.WhatsappHistoryId,t_SH.QueueId,t_SH.missedWhatApp,t_SH.IsInBound,
				t_SH.Istransferred,t_SH.dispositionId,t_SH.WhatAppDuration,t_SH.responseTime,t_SH.IsAbandoned;
                
                DROP TEMPORARY TABLE IF EXISTS temp_PrevWhatAppHistory; 
			CREATE TEMPORARY TABLE temp_PrevWhatAppHistory as
			SELECT 	DISTINCT WhatsappHistoryId 
			FROM 	temp_WhatAppHistory
			WHERE 	sessionStartTime 	BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
				
			DROP TEMPORARY TABLE IF EXISTS temp_CurChatHistory; 
			CREATE TEMPORARY TABLE temp_CurChatHistory AS
			SELECT 	DISTINCT WhatsappHistoryId 
			FROM 	temp_WhatAppHistory
			WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;  
     
			DROP TEMPORARY TABLE IF EXISTS temp_CurWhatAppHistory; 
			CREATE TEMPORARY TABLE temp_CurWhatAppHistory AS
			SELECT 	DISTINCT WhatsappHistoryId 
			FROM 	temp_whatappHistory_calc
			WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp;    
						 
			SELECT 	COUNT(WhatsappHistoryId), SUM(responseTime),sum(IsAbandoned)
			INTO 	v_PrevTotalCount ,v_PrevRespondedCount,v_PrevAbandonedCount
			FROM	temp_whatappHistory_calc;

			SELECT 	COUNT(WhatsappHistoryId),SUM(responseTime),sum(IsAbandoned)
			INTO 	v_curTotalCount ,v_CurrentRespondedCount,v_CurrentAbandonedCount	
			FROM	temp_whatappHistory_calc;   
            
			SELECT SUM(missedWhatApp), SUM(Istransferred),SUM(InteractionWithCustomer), SUM(InteractionwithAgent)
			INTO 	v_CurrentMissedCount, v_CurrentTransferredCount, v_CurrentCustomerWhatAppCount, v_CurrentAgentWhatAppCount
			FROM 	temp_whatappHistory_calc;

			SELECT sum(avgChatduration),sum(totalChatduration)
			INTO 	v_CurrentAverageChatdurationCount, v_CurrentMaximumChatdurationCount
			FROM 	temp_whatappHistory_calc;         

			SET v_PrevTotalCount 	= CASE WHEN v_PrevTotalCount = 0 then null else v_PrevTotalCount end;
			SET v_DiffRespondedPercent 	= CASE WHEN v_PrevRespondedCount = 0 then null else v_PrevRespondedCount end;
			SET v_PrevAbandonedCount 	= CASE WHEN v_PrevAbandonedCount = 0 then null else v_PrevAbandonedCount end;
         			
			SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
			,	v_DiffRespondedPercent	= (v_CurrentRespondedCount	 - v_PrevRespondedCount) / v_PrevRespondedCount * 100
			,	v_DiffAbandonedPercent	= (v_CurrentAbandonedCount - v_PrevAbandonedCount) / v_PrevAbandonedCount * 100; 
 
  
		  
	 
			SELECT 	IFNULL(v_CurTotalCount,0) 		    AS 'TotalReceivedCount',
			IFNULL(v_DiffTotalPercent,0) 		AS 'DiffTotalReceivedPercent',
			IFNULL(v_CurrentRespondedCount,0) 	AS 'CurrentAnsweredeCount',
			IFNULL(v_DiffRespondedPercent,0) 	AS 'DiffAnsweredPercent',
			IFNULL(v_CurrentAbandonedCount,0) 	AS 'CurrentAbandonedCount',
			IFNULL(v_DiffAbandonedPercent,0) 	AS 'DiffAbandonedPercent';	
         
             
			SELECT
			'All Queue'																						AS queueName                
			,IFNULL(v_CurTotalCount,0)                                    									AS receivedchats
			,IFNULL(v_CurrentRespondedCount,0)                            									AS responseTime
			,IFNULL(v_CurrentAbandonedCount,0)                                                              AS abondedchats
			,IFNULL(v_CurrentMissedCount,0)                               									AS MissedChat
			,IFNULL(v_CurrentTransferredCount,0)                          									AS transferredchat
			,IFNULL(v_TotalChatDuration,0)                   									            AS totalChatduration
			,IFNULL(v_CurrentAverageChatDurationCount,0) 	                								AS avgChatduration
			,IFNULL(v_CurrentCustomerWhatAppCount,0)								    					AS interactionfromcustomer
			,IFNULL(v_CurrentAgentWhatAppCount,0)															AS interactionfromagent
			,IFNULL(v_CurrentCustomerWhatAppCount,0) + IFNULL(v_CurrentAgentWhatAppCount,0)					AS totalinteraction
     
             UNION ALL
          	SELECT 	U.queueName														    						AS queueName        
     			 ,	COUNT(1)														    					   	AS receivedchats
     			 ,	SUM(CDH.responseTime)	    						                                       	AS responseTime
                  ,  SUM(CDH.IsAbandoned)                                                                        AS abondedchats
                  ,	SUM(CDH.missedWhatApp)																		AS MissedChat  
                  ,	SUM(CDH.Istransferred)																		AS transferredchat
                  ,	sum(CDH.totalChatduration)																    AS totalChatduration
                  ,	sum(CDH.avgChatduration) / COUNT(1)														    AS avgChatduration
                  ,	SUM(CDH.InteractionWithCustomer)															AS interactionfromcustomer
                  ,	SUM(CDH.InteractionwithAgent)																AS interactionfromagent
                  ,	SUM(CDH.InteractionWithCustomer) + SUM(CDH.InteractionwithAgent)						    AS totalinteraction
     
              FROM 	temp_whatappHistory_calc 	  CDH
              JOIN 	temp_queueIDs				U	ON CDH.QueueId	= U.qid	
              WHERE 	sessionStartTime 	BETWEEN v_CurrentStartTmpstmp and v_CurrentEndTmpstmp
              GROUP BY U.queueName;       
               
        	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
