/*!50003 DROP PROCEDURE IF EXISTS `up_Queue_Whatsapp_Servicelevel_Analysis_Metrics_Filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_Queue_Whatsapp_Servicelevel_Analysis_Metrics_Filter`(
		p_startTmpstmp 		BIGINT,
		p_endTmpstmp 		BIGINT,
		p_domainId 			INT,
		p_queueId 			TEXT,
		p_offset 			INT,
		p_Limit 		    INT	
	)
sp_return:begin
           
			DECLARE v_offset 					INT;	  	
			DECLARE v_CurrentStartTmpstmp 		BIGINT;
			DECLARE v_CurrentEndTmpstmp 		BIGINT;
			DECLARE v_PrevStartTmpstmp 			BIGINT;
			DECLARE v_PrevEndTmpstmp 			BIGINT; 
			DECLARE v_TmpstmpInterval			BIGINT;	
            
			DECLARE v_DiffansweredSLAPercent	BIGINT;	
			DECLARE v_DiffabandonedSLAPercent	BIGINT;	
			DECLARE v_DiffSLAbreachedPercent	BIGINT;	

			DECLARE v_curTotalCount 		INT;
			DECLARE v_CurrentRespondedCount INT;
			DECLARE v_CurrentAbandonedCount INT;
			DECLARE v_CurrentMissedCount 	INT; 
			DECLARE v_CurrentChatDuration 	INT;
			DECLARE v_CurrentTotalSLA 		INT;
			DECLARE v_CurrentTotalSLA1 		INT;
			DECLARE v_CurrentTotalSLA2 		INT;
			DECLARE v_CurrentTotalSLA3 		INT;
			DECLARE v_CurrentTotalSLA4 		INT;
			DECLARE v_CurrentTotalSLA5 		INT;
			DECLARE v_CurrentTotalSLA6 		INT;
            
			DECLARE v_PrevRespondedCount 	INT;
			DECLARE v_PrevAbandonedCount 	INT;
			DECLARE v_PrevTotalSLA  		INT;
			DECLARE v_PrevTotalSLA1 		INT;
			DECLARE v_PrevTotalSLA2 		INT;
			DECLARE v_PrevTotalSLA3 		INT;
			DECLARE v_PrevTotalSLA4 		INT;
			DECLARE v_PrevTotalSLA5 		INT;
			DECLARE v_PrevTotalSLA6 		INT;
            
			DECLARE v_CurrentSLAAchieved 			INT;
			DECLARE v_CurrentSLABreached 			INT;
			DECLARE v_CurrentAbandonedPercentage 	INT;
            
            DECLARE v_PrevSLAAchieved 				INT;
			DECLARE v_PrevSLABreached 				INT;
			DECLARE v_PrevAbandonedPercentage 		INT;
			DECLARE v_maxOfSLAAchieved 				INT;
			DECLARE v_maxOfSLABreached 				INT;
                 
			SET v_offset =  p_Limit * p_offset; 

			IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
			IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									

			SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;

			SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
			SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
             		
  			DROP TEMPORARY TABLE IF EXISTS temp_queueIds;	CREATE TEMPORARY TABLE temp_queueIds(queueId VARCHAR(100));
  			CALL split(p_queueId,','); INSERT INTO temp_queueIds(queueId) SELECT Items FROM tt_Split_temptable; 
               
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
			DROP TEMPORARY TABLE IF EXISTS temp_AllqueueId;	
			CREATE TEMPORARY TABLE temp_AllqueueId
			SELECT qid ,name AS queueName FROM queue WHERE domainId = p_domainId;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                   
       
			DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
					CREATE TEMPORARY TABLE temp_AvailableDisposition 
				(    DispositionId 			INT
					,DispositionStatus 		VARCHAR(100)
					,DispositionCategory	TINYINT
				); 
                                 
				INSERT INTO temp_AvailableDisposition 
				SELECT 	did 			DispositionId
					,	dispositionName	DispositionStatus
					,	CASE WHEN dispositionName = 'Opened'	THEN 2
						WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
						WHEN dispositionName = 'Disconnected'         	THEN 4
						WHEN dispositionName = 'Resolved'             	THEN 5
                        WHEN dispositionName = 'Caller Disconnected'	THEN 6
						END 			DispositionCategory
				FROM 	disposition_status
				WHERE 	domainId	= p_domainId;          
                                            
				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory; 
				CREATE TEMPORARY TABLE temp_WhatsappHistory AS 	    	
				SELECT	 	sessionStartTime
						,	SH.WhatsappHistoryId
						,	SDH.dialDuration                                                          		AS dialDuration                 
						,	CASE WHEN IFNULL(SDH.Duration,0) > 0 THEN SDH.Duration ELSE 0 END				AS Duration
						, 	SDH.IsMissed                                                         	   		AS IsMissedCall
						, 	CASE WHEN t_D.DispositionCategory = 6 THEN 1 ELSE 0 END				   			AS IsAbandoned
                        ,	SDH.QueueId    
						, 	CASE WHEN SDH.Duration > 0 THEN 1 ELSE 0 END									AS totalRespondedChats
				FROM 	tb_WhatsappHistory 				SH
				JOIN 	tb_WhatsappDurationHistory		SDH	ON SH.WhatsappHistoryId = SDH.WhatsappHistoryId      
				LEFT JOIN 	tb_User						U	ON SDH.queueId			= U.UserID  
				JOIN 		temp_AllqueueId 			t_A ON SDH.queueId		    = t_A.qid  
				LEFT JOIN 	temp_AvailableDisposition	t_D	ON SH.dispositionId		= t_D.DispositionId
				WHERE 	SH.domainId 		= p_domainId		
				AND 	SH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp 
				AND 	((IFNULL(p_queueId,'') 	= '') OR SDH.QueueId IN (SELECT queueId FROM temp_queueIds));   
              
				DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_cur; 
     			CREATE TEMPORARY TABLE temp_WhatAppHistory_cur AS
     		    SELECT 	sessionStartTime		
					,	WhatsappHistoryId        
					,	QueueId
					,   IsMissedCall
					, 	IsAbandoned     
					, 	Duration
					,	CASE WHEN dialDuration BETWEEN 0  AND 5 	THEN 1 ELSE 0 END	AS SLA1   
					,	CASE WHEN dialDuration BETWEEN 6  AND 10 	THEN 1 ELSE 0 END	AS SLA2   
					,	CASE WHEN dialDuration BETWEEN 11 AND 15 	THEN 1 ELSE 0 END	AS SLA3   
					,	CASE WHEN dialDuration BETWEEN 16 AND 20 	THEN 1 ELSE 0 END	AS SLA4   
					,	CASE WHEN dialDuration BETWEEN 21 AND 25 	THEN 1 ELSE 0 END	AS SLA5   
					,	CASE WHEN dialDuration BETWEEN 26 AND 30 	THEN 1 ELSE 0 END	AS SLA6
					,	totalRespondedChats
     			FROM 	temp_WhatsappHistory
                WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
                
                DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_prev; 
     			CREATE TEMPORARY TABLE temp_WhatAppHistory_prev AS
     		    SELECT 	sessionStartTime		
       				,	WhatsappHistoryId        
					,	QueueId
					,   IsMissedCall
					, 	IsAbandoned     
					, 	Duration
                    , 	CASE WHEN dialDuration BETWEEN 0  AND 5 	THEN 1 ELSE 0 END	AS SLA1   
					,	CASE WHEN dialDuration BETWEEN 6  AND 10 	THEN 1 ELSE 0 END	AS SLA2   
					,	CASE WHEN dialDuration BETWEEN 11 AND 15 	THEN 1 ELSE 0 END	AS SLA3   
					,	CASE WHEN dialDuration BETWEEN 16 AND 20 	THEN 1 ELSE 0 END	AS SLA4   
					,	CASE WHEN dialDuration BETWEEN 21 AND 25 	THEN 1 ELSE 0 END	AS SLA5   
					,	CASE WHEN dialDuration BETWEEN 26 AND 30 	THEN 1 ELSE 0 END	AS SLA6
                    ,	totalRespondedChats
     			FROM 	temp_WhatsappHistory
                WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
 
                DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_cur_cal; 
     			CREATE TEMPORARY TABLE temp_WhatAppHistory_cur_cal AS
     		    SELECT 	QueueId      
					,	COUNT(WhatsappHistoryId) 							AS totalReceivedChats
					,	SUM(SLA1 + SLA2 + SLA3 + SLA4 + SLA5 + SLA6)		AS totalSLA
					,   SUM(IsMissedCall)									AS IsMissedCall
					, 	SUM(IsAbandoned) 									AS IsAbandoned    
					, 	SUM(Duration) 										AS Duration
                    , 	SUM(totalRespondedChats)							AS totalRespondedChats
                    ,	SUM(SLA1)											AS totalSLA1
                    ,	SUM(SLA2)											AS totalSLA2
                    ,	SUM(SLA3)											AS totalSLA3
                    ,	SUM(SLA4)											AS totalSLA4
                    ,	SUM(SLA5)											AS totalSLA5
                    ,	SUM(SLA6)											AS totalSLA6
     			FROM 	temp_WhatAppHistory_cur
                GROUP BY QueueId; 
                
                DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_prev_cal; 
     			CREATE TEMPORARY TABLE temp_WhatAppHistory_prev_cal AS
     		    SELECT 	QueueId      
					,	COUNT(WhatsappHistoryId) 							AS totalReceivedChats
					,	SUM(SLA1 + SLA2 + SLA3 + SLA4 + SLA5 + SLA6)		AS totalSLA
					,   SUM(IsMissedCall)									AS IsMissedCall
					, 	SUM(IsAbandoned) 									AS IsAbandoned    
					, 	SUM(Duration) 										AS Duration
                    , 	SUM(totalRespondedChats)							AS totalRespondedChats
                    ,	SUM(SLA1)											AS totalSLA1
                    ,	SUM(SLA2)											AS totalSLA2
                    ,	SUM(SLA3)											AS totalSLA3
                    ,	SUM(SLA4)											AS totalSLA4
                    ,	SUM(SLA5)											AS totalSLA5
                    ,	SUM(SLA6)											AS totalSLA6
     			FROM 	temp_WhatAppHistory_prev
                GROUP BY QueueId; 
 
                SELECT 	totalReceivedChats, totalRespondedChats ,IsAbandoned,IsMissedCall,Duration,totalSLA,totalSLA1,totalSLA2,totalSLA3,totalSLA4,totalSLA5,totalSLA6
				INTO 	v_curTotalCount ,v_CurrentRespondedCount,v_CurrentAbandonedCount,v_CurrentMissedCount, v_CurrentChatDuration,v_CurrentTotalSLA,v_CurrentTotalSLA1,v_CurrentTotalSLA2,v_CurrentTotalSLA3,v_CurrentTotalSLA4,v_CurrentTotalSLA5,v_CurrentTotalSLA6	
				FROM	temp_WhatAppHistory_cur_cal;  

				SELECT 	totalRespondedChats ,IsAbandoned,totalSLA,totalSLA1,totalSLA2,totalSLA3,totalSLA4,totalSLA5,totalSLA6
				INTO 	v_PrevRespondedCount,v_PrevAbandonedCount,v_PrevTotalSLA,v_PrevTotalSLA1,v_PrevTotalSLA2,v_PrevTotalSLA3,v_PrevTotalSLA4,v_PrevTotalSLA5,v_PrevTotalSLA6
				FROM	temp_WhatAppHistory_prev_cal;
                
                SELECT IFNULL((totalSLA / totalReceivedChats) * 100,0),IFNULL((100 - ((totalSLA / totalReceivedChats) * 100)),0),IFNULL((IsAbandoned/totalReceivedChats)*100,0)
                INTO v_CurrentSLAAchieved ,v_CurrentSLABreached,v_CurrentAbandonedPercentage
                FROM temp_WhatAppHistory_cur_cal;
                                
                SELECT IFNULL((totalSLA / totalReceivedChats) * 100,0),IFNULL((100 - ((totalSLA / totalReceivedChats) * 100)),0),IFNULL((IsAbandoned/totalReceivedChats)*100,0)
                INTO v_PrevSLAAchieved ,v_PrevSLABreached,v_PrevAbandonedPercentage
                FROM temp_WhatAppHistory_prev_cal;
                                
				SELECT GREATEST(IFNULL(v_CurrentSLAAchieved,0), IFNULL(v_PrevSLAAchieved,0)), GREATEST(IFNULL(v_CurrentSLABreached,0), IFNULL(v_PrevSLABreached,0))
                INTO v_maxOfSLAAchieved,v_maxOfSLABreached;
			            
				SET v_DiffansweredSLAPercent  	= CASE WHEN IFNULL(v_maxOfSLAAchieved,0) = 0 THEN 0 ELSE ((IFNULL(v_CurrentSLAAchieved,0)- IFNULL(v_PrevSLAAchieved,0) ) / IFNULL(v_maxOfSLAAchieved,0)) * 100 END 
				,  	v_DiffabandonedSLAPercent	= CASE WHEN IFNULL(v_PrevAbandonedPercentage,0) = 0 THEN 0 ELSE ((IFNULL(v_CurrentAbandonedPercentage,0) - IFNULL(v_PrevAbandonedPercentage,0) ) / IFNULL(v_PrevAbandonedPercentage,0))  * 100 END 
				,  	v_DiffSLAbreachedPercent  	= CASE WHEN IFNULL(v_maxOfSLABreached,0) = 0 THEN 0 ELSE ((IFNULL(v_CurrentSLABreached,0) - IFNULL(v_PrevSLABreached,0)) / IFNULL(v_maxOfSLABreached,0) * 100) END; 
				
      
				SELECT * FROM temp_AllqueueId;
            
				SELECT 
                 IFNULL(v_CurrentRespondedCount,0)          	AS 'CurrentAnsweredSLACount',
                 IFNULL(v_DiffansweredSLAPercent,0)       		AS 'DiffAnsweredSLAPercent',
                 IFNULL(v_CurrentAbandonedCount,0)         		AS 'CurrentAbandonedSLACount',
                 IFNULL(v_CurrentAbandonedPercentage,0)      	AS 'DiffAbandonedSLAPercent',
                 IFNULL(v_CurrentSLABreached,0)          		AS 'CurrentSLAbreachedCount',
                 IFNULL(v_DiffSLAbreachedPercent ,0)      		AS 'DiffSLAbreachedPercent';
                      
		  SELECT
				  'All Queue'												   													AS queueName
				 ,'Answered'                                                   													AS ChatType
				 ,IFNULL(v_CurrentTotalSLA1,0)                                          										AS SL1
				 ,IFNULL(v_CurrentTotalSLA2,0)                                          										AS SL2
				 ,IFNULL(v_CurrentTotalSLA3,0)                                          										AS SL3
				 ,IFNULL(v_CurrentTotalSLA4,0)                                          										AS SL4
				 ,IFNULL(v_CurrentTotalSLA5,0)                                          										AS SL5
				 ,IFNULL(v_CurrentTotalSLA6,0)                                          										AS SL6
				 ,IFNULL(v_CurrentTotalSLA,0)                                      												AS Total
				 ,IFNULL(v_CurrentMissedCount,0)                                   												AS MissedChats
				 ,IFNULL(v_CurrentSLAAchieved,0)																				AS SLAAchieved
				 ,IFNULL(v_CurrentSLABreached,0)                                   												AS SLAbreached
			UNION ALL
			SELECT 	t_A.queueName													                                   			AS queueName
				 ,  'Answered'      																							AS ChatType   
				 ,	SUM(CH.totalSLA1)  																							AS SL1
				 ,	SUM(CH.totalSLA2)  																							AS SL2
				 ,	SUM(CH.totalSLA3)  																							AS SL3
				 ,	SUM(CH.totalSLA4)  																							AS SL4
				 ,	SUM(CH.totalSLA5)  																							AS SL5
				 ,	SUM(CH.totalSLA6)  																							AS SL6
				 ,  SUM(CH.totalSLA)																							AS Total
				 ,  SUM(CH.IsMissedCall)																						AS MissedChats
				 ,  IFNULL((SUM(totalSLA) / SUM(totalReceivedChats)) * 100,0)      												AS SLAAchieved
				 , 	IFNULL((100 - (SUM(totalSLA) / SUM(totalReceivedChats)) * 100),0)																							AS SLAbreached
				 FROM temp_WhatAppHistory_cur_cal 	CH
				 JOIN temp_AllqueueId 				t_A ON CH.QueueId		    = t_A.qid
				 GROUP BY t_A.queueName;
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_sample_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_sample_report`(
    p_startTmpstmp BIGINT,
    p_endTmpstmp BIGINT,
    p_domainId INT,
    p_Limit INT,   
    p_offset INT
)
BEGIN
    
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_intervals (
        interval_start BIGINT,
        interval_end BIGINT
    );

    
    TRUNCATE TABLE temp_intervals;

    
    SET @currentTmpstmp = p_startTmpstmp;

    WHILE @currentTmpstmp < p_endTmpstmp DO
        INSERT INTO temp_intervals (interval_start, interval_end)
        VALUES (@currentTmpstmp, LEAST(@currentTmpstmp + 3600000, p_endTmpstmp));

        
        SET @currentTmpstmp = @currentTmpstmp + 3600000;
    END WHILE;

    
    SELECT 
        ti.interval_start AS start_interval,
        ti.interval_end AS end_interval,
        CH.* 
    FROM temp_intervals ti
    JOIN tb_ChatHistory CH
        ON CH.sessionStartTime BETWEEN ti.interval_start AND ti.interval_end
    JOIN tb_ChatDurationHistory CDH
        ON CH.ChatHistoryId = CDH.ChatHistoryId
    WHERE CH.domainId = p_domainId
    LIMIT p_Limit ;

    
    DROP TEMPORARY TABLE IF EXISTS temp_intervals;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
