/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_SetChatMessage`(	
 	p_ChatDurationHistoryId		BIGINT
 	,p_ChatHistoryId			BIGINT
  	,p_message					JSON
   )
BEGIN  	
  	DECLARE v_errCode		INT	DEFAULT -1;
 	DECLARE v_errMsg		VARCHAR(150) DEFAULT 'No Chat Update';
 	DECLARE	v_CurDate		DATETIME;    
      
 	SET v_CurDate = NOW();
      
   	UPDATE 	tb_ChatMessage
      SET 	Message					= p_message
  		,	updatedAt				= v_CurDate
  	WHERE 	ChatDurationHistoryId 	= p_ChatDurationHistoryId;
      
       IF row_count() > 0
       THEN
   		SET v_errcode 	= 0
   			,v_errmsg	= 'Chat Updated Successfully';	
       END IF;
       
       select v_errcode 	errcode
  		, 	v_errmsg	errmsg;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_SetFacebookConfigurationStatus` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_SetFacebookConfigurationStatus`(	p_FacebookConfigurationId	INT
	,p_domainId 				INT
    ,p_isActive					TINYINT
)
BEGIN
	DECLARE v_CurDate		DATETIME;
    
    SET v_CurDate = NOW();
    
	UPDATE	tb_FacebookConfiguration
    SET 	isActive	= p_isActive
		,	updatedDate	= v_CurDate	
	WHERE 	FacebookConfigurationId = p_FacebookConfigurationId
	AND 	domainId 				= p_domainId;    
        
	SELECT p_isActive AS `Enable`, 0 AS errCode, 'Facebook Configuration Status updated Successfully' AS errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_SetInstagramConfigurationStatus` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_SetInstagramConfigurationStatus`(	p_InstagramConfigurationId	INT
 	,p_domainId 				INT
     ,p_isActive					TINYINT
 )
BEGIN
 	DECLARE v_CurDate		DATETIME;
     
     SET v_CurDate = NOW();
     
 	UPDATE	tb_InstagramConfiguration
     SET 	isActive	= p_isActive
 		,	updatedDate	= v_CurDate	
 	WHERE 	InstagramConfigurationId = p_InstagramConfigurationId
 	AND 	domainId 				= p_domainId;    
         
 	SELECT p_isActive AS `Enable`, 0 AS errCode, 'Instagram Configuration Status updated Successfully' AS errMsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
