/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_SetIrrelevantChatQuestionAnswer`(	
	p_chatFlowId		INT
 	,p_domainId			INT
 	,p_questionAnswer	JSON
 )
BEGIN 	
 	DECLARE v_errcode 	INT DEFAULT -1;
 	DECLARE v_errmsg 	VARCHAR(150) DEFAULT 'Set Irrelevant Chat Question Answer Failed';    
     
	UPDATE 	tb_IrrelevantChatQuestionAnswer
	SET 	questionAnswer 	= p_questionAnswer	
		,	updatedDate		= CURDATE()
	WHERE 	chatFlowId		= p_chatFlowId
	AND 	domainId		= p_domainId;
     
	SET v_errcode	= 0
	,	v_errmsg 	= 'Set Irrelevant Chat Question Answer Successfully';
     
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;      	
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_SetPrimaryEmail` */;
