CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_techticket_add_notification`(
  p_TechSupportTicketId		INT,
  p_notification_type_id		SMALLINT,
  p_CustomerCompanyId			INT,	
  p_ServiceProviderCompanyId	INT,
  p_datetime					DATETIME,
  OUT p_errcode				TINYINT,
  OUT p_errmsg				VARCHAR(200)
  )
SP : BEGIN
  	DECLARE v_notification_id	INT;
      DECLARE v_CurDate			DATETIME DEFAULT NOW();
      DECLARE v_AssignedTo		INT;
  	DECLARE v_AssignedBy		INT;    
      DECLARE v_AssignedToName	VARCHAR(250);	
      
 	DECLARE v_isServiceProviderTicket	TINYINT DEFAULT 0;  
     DECLARE v_ServiceProviderToUser		INT	DEFAULT 0;	 	
      
  	DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
  	BEGIN
  		GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
  		SET p_errmsg 	= CONCAT(@st, ' : ', @p2); 		
          SET p_errcode	= -1;
          
  		SELECT p_TechSupportTicketId AS TechSupportTicketId,p_errcode AS errcode, p_errmsg AS errmsg;
  		ROLLBACK;
  	END;       
      
      
       
      
      SELECT 	AssignedTo, AssignedBy, U.UserName    
      INTO 	v_AssignedTo, v_AssignedBy, v_AssignedToName
      FROM 	tb_TechSupportTicket	T
      LEFT JOIN 	tb_User				U ON U.UserID =T.AssignedTo	
      WHERE 	TechSupportTicketId	= p_TechSupportTicketId;    
      
      
      
      
      
 			IF EXISTS (SELECT 1 FROM tb_TechSupportTicket WHERE TechSupportTicketId = p_TechSupportTicketId 
 										AND ServiceProviderCompanyId = CustomerCompanyId)	THEN
 						
                         SET v_isServiceProviderTicket = 1;
                         SET v_ServiceProviderToUser = (SELECT sendToCust FROM tb_TechSupportTicket WHERE TechSupportTicketId = p_TechSupportTicketId);
 
             END IF;
      
      
       
       
      
      START TRANSACTION;	
  	INSERT INTO tb_techticket_notification(
  		TechSupportTicketId			
  		,notification_type_id
  		,role_id
  		,notification							
  		,CustomerCompanyId			
  		,ServiceProviderCompanyId	
  		,created_date				    
      )
  	SELECT 
  		p_TechSupportTicketId	
          ,p_notification_type_id	
          ,NT.notification_role
          ,CASE 	WHEN NT.notification_type_id = 9 THEN REPLACE(REPLACE(notification_template,'<ticketid>',p_TechSupportTicketId),'<senior_resolver_name>',IFNULL(v_AssignedToName,''))
 				WHEN NT.notification_type_id = 1 AND NT.notification_role = -100 AND v_isServiceProviderTicket = 1 THEN 
 					REPLACE(REPLACE(REPLACE(REPLACE(notification_template,"We’ve received your", ""), "Our support team is reviewing it.", 
                     " has been successfully raised by the agent. Our team will address the issue at the earliest."), "#<ticketid>.", p_TechSupportTicketId), "ticket", "Ticket")	
  				ELSE REPLACE(notification_template,'<ticketid>',p_TechSupportTicketId) END
  		,CASE WHEN v_isServiceProviderTicket = 1 AND NT.notification_role = -100 AND NT.notification_type_id = 1 THEN v_ServiceProviderToUser ELSE p_CustomerCompanyId END		
          ,p_ServiceProviderCompanyId	
          ,v_CurDate
      FROM 	tb_techticket_notification_type	NT
      LEFT JOIN tb_techticket_notification	N 	ON 	N.notification_type_id	= NT.notification_type_id    
  												AND N.TechSupportTicketId	= p_TechSupportTicketId	
      WHERE 	NT.notification_type_id = p_notification_type_id
      AND 	N.notification_id 	IS NULL;
      
      
       
      
      IF p_notification_type_id IN (1,2,4,6,8,9,10,11,12)    
      THEN
  		INSERT INTO tb_techticket_user_notification(
  		notification_id
  		,CompanyId
  		,userId
  		,isRead
  		,created_date
  		,updated_date
  		)   
          SELECT 	
  			N.notification_id
  			,CASE WHEN v_isServiceProviderTicket = 1 THEN v_ServiceProviderToUser ELSE p_CustomerCompanyId END
 			, 0 
  			,0
  			,v_CurDate
  			,v_CurDate	 
  		FROM 	tb_techticket_notification	N		
  		LEFT JOIN tb_techticket_user_notification	UN 	ON UN.notification_id = N.notification_id
  		WHERE 	N.TechSupportTicketId	= p_TechSupportTicketId
          AND 	UN.notification_id		IS NULL
  		AND 	N.role_id				= -100; 
      END IF;
      
  	
  	
      
      INSERT INTO tb_techticket_user_notification(
  		notification_id
  		,CompanyId
  		,userId
  		,isRead
  		,created_date
  		,updated_date
      )   
  	SELECT 	
  		N.notification_id
          ,p_ServiceProviderCompanyId
          ,U.UserID
          ,0
          ,v_CurDate
          ,v_CurDate	 
      FROM 	tb_techticket_notification	N
      JOIN 	tb_User 					U 	ON 	U.roleid	= N.role_id    											
      LEFT JOIN tb_techticket_user_notification	UN 	ON UN.notification_id = N.notification_id
      WHERE 	UN.notification_id		IS NULL
  	AND 	N.TechSupportTicketId	= p_TechSupportTicketId
      AND 	N.role_id				IN (3)
      AND 	U.companyId 			= p_ServiceProviderCompanyId
      AND 	U.isActive				= 1;
      
        
      
      IF (IFNULL(v_AssignedTo,0) <> 0 OR IFNULL(v_AssignedBy,0) <> 0)
      THEN
          INSERT INTO tb_techticket_user_notification(
  		notification_id
  		,CompanyId
  		,userId
  		,isRead
  		,created_date
  		,updated_date
  		)   
  		SELECT 	
  			N.notification_id
  			,p_ServiceProviderCompanyId
  			,U.UserID
  			,0
  			,v_CurDate
  			,v_CurDate	 
  		FROM 	tb_techticket_notification			N
  		JOIN 	tb_User 							U 	ON 	U.roleid	= N.role_id    											
  		LEFT JOIN tb_techticket_user_notification	UN 	ON 	UN.notification_id = N.notification_id														
  														AND UN.userId	= U.UserID
  		WHERE 	UN.notification_id	IS NULL
          AND 	N.TechSupportTicketId	= p_TechSupportTicketId
  		AND 	(	(IFNULL(v_AssignedTo,0) <> 0 AND U.UserID = v_AssignedTo)
  				OR	(IFNULL(v_AssignedBy,0) <> 0 AND U.UserID = v_AssignedBy));            
  	END IF; 
  	COMMIT;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_techticket_add_update_ai_chat` */;
