CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_techticket_add_update_ai_chat`(
 p_TechSupportTicketId	INT,
 p_ai_chat				JSON,
 p_logged_user_id		BIGINT
 )
BEGIN
 	DECLARE p_errmsg 		VARCHAR(200);
 	DECLARE p_errcode		TINYINT;
     
 	DECLARE EXIT HANDLER FOR SQLEXCEPTION                   
 	BEGIN
 		GET DIAGNOSTICS CONDITION 1 @st = RETURNED_SQLSTATE, @p2 =  MESSAGE_TEXT;
 		SET p_errmsg 	= CONCAT(@st, ' : ', @p2); 		
 		SET p_errcode	= -1;
 		 
 		SELECT p_errcode AS errcode, p_errmsg AS errmsg;
 		ROLLBACK;
 	END; 
 	START TRANSACTION;	
 		UPDATE 	tb_TechSupportTicket 
 		SET 	ai_chat	 	= CASE 	WHEN ai_chat IS NULL THEN IFNULL(p_ai_chat,'[]')  
 									WHEN p_ai_chat IS NOT NULL THEN	JSON_ARRAY_APPEND(ai_chat,'$',p_ai_chat) END
 			,	UpdatedBy	= p_logged_user_id
 			,	UpdatedDate	= NOW()
 		WHERE 	TechSupportTicketId = p_TechSupportTicketId;
     COMMIT;    
     
 	SELECT 1 AS errcode, 'Update successfully' AS errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_techticket_get_email_notification` */;
