/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_techticket_get_email_notification`(
 p_CompanyId INT
 )
BEGIN
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  
 		SELECT 	EN.email_notification_id
 			,	EN.email_notification_template_id
             ,	ENT.email_Subject
 			,	ENT.email_template
 			,	T.TechSupportTicketId
             ,	T.TicketSubject
             ,	T.TicketDescription
             ,	T.ResolutionDueDate
             ,	T.ResolvedDate
             ,	T.ResponseDueDate
             ,	T.ResponsedDate
             ,	T.ClosedDate
             ,	T.CreatedDate
             ,	T.UpdatedDate
             ,	T.RootCause
             ,	T.Resolution
             ,	T.Summary            
             ,	CASE 	WHEN U.roleid = 3 		THEN 'Admin'
 						WHEN U.roleid = 6 		THEN 'Agent'
                         WHEN U.roleid = -2 		THEN 'Resolver' 
                         WHEN U.roleid = -1 		THEN 'SeniorResolver' 
                         WHEN EN.user_id IS NULL THEN 'Customer'
                         END AS UserRole
 			,	IFNULL(U.emailId,(SELECT InCU.emailId FROM tb_User InCU	WHERE InCU.companyId = T.CustomerCompanyId AND InCU.roleid = 3 LIMIT 1)) AS emailId
             ,	C.companyName	AS customer_name
             ,	S_C.companyName	AS ServiceProviderCompany
             ,	U.UserName		AS EmailToUser
             ,	S.StatusName            
             ,	P.TypeCodeName	AS Priority                   
             ,	RES.UserName	AS ResolverName
             ,	RES_P.UserName	AS PreviousResolverName
             ,	AGT.UserName	AS AgentName            
 		FROM 	tb_techticket_email_notification 			EN
         JOIN 	tb_techticket_email_notification_template 	ENT ON  EN.email_notification_template_id 	= ENT.email_notification_template_id																
 																AND	ENT.role_id							= EN.role_id
         JOIN 	tb_TechSupportTicket				T	ON T.TechSupportTicketId 	= EN.TechSupportTicketId        
         JOIN 	tb_companyDomain					C	ON C.companyId				= T.CustomerCompanyId        
         JOIN 	tb_companyDomain					S_C	ON S_C.companyId			= T.ServiceProviderCompanyId
         LEFT JOIN tb_User							U	ON U.UserID					= EN.user_id        		
         LEFT JOIN tb_TicketStatus					S	ON S.StatusId				= T.TicketStatusId
         LEFT JOIN TypeCode							P	ON P.TypeCodeID				= T.PriorityId
 		LEFT JOIN tb_User							RES	ON RES.UserID				= T.AssignedTo
         LEFT JOIN tb_User							RES_P	ON RES_P.UserID			= T.AssignedTo_Prev
         LEFT JOIN tb_User							AGT	ON AGT.UserID				= T.AssignedBy        
         WHERE 	EN.ServiceProviderCompanyId	= 	p_CompanyId
         AND 	EN.is_sent = 0;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
