 p_email_notification_id		INT,
 p_is_sent					TINYINT	
 )
BEGIN
 	UPDATE 	tb_techticket_email_notification
     SET 	is_sent			= p_is_sent
 		,	updated_date	= NOW()
 	WHERE 	email_notification_id	= p_email_notification_id;
 END ;;
