CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_tech_support_set_TicketChat`(
 p_TicketChatId	BIGINT,
 p_Message		JSON
 )
BEGIN
 	UPDATE 	tb_TicketChat
     SET 	Message 		= p_Message
 		,	UpdatedDate		= NOW()
     WHERE 	TicketChatId	= p_TicketChatId;
     
     SELECT 1 AS errcode, '' AS errmsg;
 END ;;
