CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketApprovalCancel`(
  p_TicketApprovalId 			BIGINT,
  p_TicketId 					BIGINT,
  p_IsCancelled 					TINYINT,
  p_ApprovalCancelComments		TEXT
  )
BEGIN
   DECLARE v_CurDate DATETIME;
   DECLARE v_errcode INT          DEFAULT -1;
   DECLARE v_errmsg  VARCHAR(100) DEFAULT 'No Update';
   
     set v_CurDate = now();
      
      UPDATE tb_TicketApproval
      SET  	IsCancelled 				= IFNULL(p_IsCancelled,IsCancelled),
 			ApprovalCancelComments		= IFNULL(p_ApprovalCancelComments,ApprovalCancelComments),
 			UpdatedDate 				= v_CurDate
      WHERE 	TicketApprovalId    		= p_TicketApprovalId
      and    TicketId					= p_TicketId;
      
 	 UPDATE tb_TicketApprovalUserMapping
      SET  	IsCancelled 				= IFNULL(p_IsCancelled,IsCancelled),
 			ApprovalCancelComments		= IFNULL(p_ApprovalCancelComments,ApprovalCancelComments),
 			UpdatedDate 				= v_CurDate
      WHERE 	TicketApprovalId    		= p_TicketApprovalId
      and    TicketId					= p_TicketId;
      
      IF ROW_COUNT() > 0
      THEN
 		 SET v_errcode = 0;
          SET v_errmsg = 'Cancelled Successfully';
      END IF;
      
      SELECT v_errcode errcode,  v_errmsg errmsg; 
  END ;;
DELIMITER ;
