CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_TicketCreateEmailConfig`(
 	p_EmailConfigId 		int,
 	p_emailAddress 			varchar(250),
 	p_domainId 				int,
 	p_companyId 			int,
 	p_is_smtp 				tinyint,
 	p_emailtype	 			int
  )
Begin
		DECLARE v_EmailConfigId		INT;
		DECLARE v_LastEmailConfigId	INT;
		DECLARE v_errcode 			INT DEFAULT -1;
		DECLARE v_errmsg 			VARCHAR(255) DEFAULT 'Email Configuration Failed';   
        DECLARE v_ccaasEmailConfigId INT;
                
        SELECT EmailConfigId INTO v_EmailConfigId 
        FROM tb_Ticket_email_config 
        WHERE emailAddress = p_EmailConfigId AND domainId = p_emailAddress;
        
        SELECT 	EmailConfigId INTO v_ccaasEmailConfigId 
        FROM 	email_config
        WHERE 	emailAddress = p_emailAddress
        AND		domainId = p_domainId;
        
        IF v_EmailConfigId IS NULL
        THEN
        
			INSERT INTO tb_Ticket_email_config(emailAddress,domainId,companyId,is_smtp,emailtype,ccaasEmailConfigId,createdAt,updatedAt)
			VALUES (p_emailAddress,p_domainId,p_companyId,p_is_smtp,p_emailtype,v_ccaasEmailConfigId,now(),now());
            
            SET v_LastEmailConfigId = LAST_INSERT_ID();
            
				SET v_errcode = 0;
				SET v_errmsg = 'inserted successfully'; 
        ELSE
			UPDATE tb_Ticket_email_config 
 				SET 	is_smtp 			= ifnull(p_is_smtp,is_smtp),
 						emailtype 			= ifnull(p_emailtype,emailtype)
 				WHERE 	EmailConfigId 		= v_EmailConfigId;
     				  
     				SET v_errcode = 0;
     				SET v_errmsg = 'updated successfully';
        End if;
        
		select v_errcode as errcode, v_errmsg as errmsg,ifnull(v_LastEmailConfigId,p_EmailConfigId) as EmailConfigId;
        
  End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
