CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketDashboard`(
 	 p_CompanyId 					INT,
 	 p_ProductId					INT,
 	 p_FromDate 					DATETIME,
 	 p_ToDate 		    			DATETIME,
 	 p_LoggedInUserID 	       	 	BIGINT     
 )
begin
         DECLARE v_AssignedTickets         INT;
         DECLARE v_UnAssignedOnHoldTickets INT;
         DECLARE v_UnAssignedOpenTickets   INT;
         DECLARE v_OverdueTicketsCount     INT;
         DECLARE v_ClosedTickets           INT;
         DECLARE v_OpenTickets			  INT;
         DECLARE v_ResolvedTickets         INT;
         DECLARE v_InProgressTickets       INT;
         DECLARE v_PendingTickets		  INT;
         DECLARE v_MyOverdueTicketsCount	  INT;
         DECLARE v_MyClosedTickets		  INT;
         DECLARE v_ToDate 		    	  DATETIME; 
         
         SET v_ToDate = CONCAT(CAST(p_ToDate AS DATE),' 23:59:59');
         
         DROP TEMPORARY TABLE IF EXISTS Temp_TicketDetails;
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
         CREATE TEMPORARY TABLE Temp_TicketDetails 
         SELECT	TD.TicketId, 
 				TD.TicketTypeId,
 				TD.PriorityId,
       			TD.AssignedToGroupId,
       			TD.AssignedToAgentId,
       			TD.CreatedDate,
       			TD.CreatedBy,
       			TS.StatusName, 
       			TD.ResolutionDueDate  
         FROM 	tb_TicketDetails 	TD
         JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
         WHERE 	TD.CreatedDate 	BETWEEN p_FromDate AND v_ToDate
         AND 	TD.CompanyId	= p_CompanyId    
         AND    	TD.ProductId	= p_ProductId;
         
         SELECT COUNT(1) into v_AssignedTickets 
         FROM   Temp_TicketDetails 
         WHERE  (AssignedToGroupId != 0 OR AssignedToAgentId != 0);
         
         SELECT COUNT(1) into v_UnAssignedOnHoldTickets 
         FROM   Temp_TicketDetails 
         WHERE  (AssignedToGroupId = 0 OR AssignedToAgentId = 0) AND StatusName = 'On-Hold';
         
         SELECT COUNT(1) into v_UnAssignedOpenTickets 
         FROM   Temp_TicketDetails 
         WHERE  (AssignedToGroupId = 0 OR AssignedToAgentId = 0) AND StatusName = 'Open';
         
         SELECT COUNT(1) into v_OverdueTicketsCount 
         FROM   Temp_TicketDetails 
         WHERE  ResolutionDueDate < CURDATE();
         
         SELECT COUNT(1) into v_ClosedTickets 
         FROM   Temp_TicketDetails 
         WHERE  StatusName = 'Closed';
         
         SELECT COUNT(1) into v_OpenTickets 
         FROM   Temp_TicketDetails 
         WHERE  StatusName = 'Open';     
       
         SELECT COUNT(1) into v_ResolvedTickets
         FROM   Temp_TicketDetails 
         WHERE  StatusName = 'Resolved';
         
         SELECT COUNT(1) into v_InProgressTickets
         FROM   Temp_TicketDetails 
         WHERE  StatusName = 'InProgress';
         
         SELECT COUNT(1) into v_PendingTickets
         FROM   Temp_TicketDetails 
         WHERE  StatusName = 'Pending';
         
         SELECT COUNT(1) into v_MyOverdueTicketsCount
         FROM   Temp_TicketDetails 
         WHERE  CreatedBy = p_LoggedInUserID 
         and    ResolutionDueDate < CURDATE();
         
         SELECT COUNT(1) into v_MyClosedTickets
         FROM   Temp_TicketDetails 
         WHERE  StatusName = 'Closed';
            
            
         SELECT v_AssignedTickets         as AssignedTickets,
                v_UnAssignedOnHoldTickets as UnAssignedOnHoldTickets,
                v_UnAssignedOpenTickets   as UnAssignedOpenTickets,
                v_OverdueTicketsCount     as OverdueTickets,
                v_ClosedTickets 			 as ClosedTickets;
           
 		
 		SELECT 	v_OpenTickets  			AS  OpenTickets,
 				v_ResolvedTickets  		AS  ResolvedTickets,
 				v_InProgressTickets		AS  InProgressTickets,
 				v_PendingTickets		AS	PendingTickets,
 				0 						AS 	FollowUpTicketsCount,
 				v_MyOverdueTicketsCount	AS  MyOverdueTicketsCount,
 				v_MyClosedTickets		AS	MyClosedTickets;   
          
         WITH CTE_TicketPriority	AS (        
 			SELECT 	t_TD.PriorityId				
 				,	COUNT(1)			AS PriorityCount
 			FROM 	Temp_TicketDetails	t_TD			
 			GROUP BY t_TD.PriorityId
         )
 		SELECT 	PRI.TypeCodeName	AS Priority
 			,	C_TP.PriorityCount
 		FROM 	CTE_TicketPriority	C_TP
 		JOIN 	TypeCode			PRI		ON C_TP.PriorityId = PRI.TypeCodeID;
         
         WITH CTE_TicketType	AS (  
 			SELECT 	t_TD.TicketTypeId				
 				,	COUNT(1)			AS TicketTypeCount
 			FROM 	Temp_TicketDetails	t_TD			
 			GROUP BY t_TD.TicketTypeId
         )
 		SELECT 	TT.TicketTypeName
 			,	TicketTypeCount
         FROM 	CTE_TicketType	t_TT
         JOIN 	tb_TicketType	TT		ON t_TT.TicketTypeId = TT.TicketTypeId;
         
     
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_TicketDashboardGroup` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
