CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_TicketDashboardGroup`(
       p_CompanyId 					INT,
       p_ProductId					INT,
       p_FromDate 					DATETIME,
       p_ToDate 		    		DATETIME,
       p_AssignedToGroupId 	       	INT     
       )
begin
      
      declare v_AssignedOpenTickets         INT;
      DECLARE v_ResolvedTickets 			INT;
      declare v_InProgressTickets   		INT;
      declare v_PendingTickets      		INT;
      declare v_OverdueTickets				INT;
      declare v_ClosedTickets           	INT;
  	DECLARE v_ToDate 		    	DATETIME; 
      
      SET v_ToDate = CONCAT(CAST(p_ToDate AS DATE),' 23:59:59');    
      
      DROP temporary TABLE IF EXISTS Temp_TicketDetails;
      create temporary table Temp_TicketDetails 
      SELECT	TD.TicketId, 
 			TD.AssignedToGroupId,
    			TD.AssignedToAgentId,
    			TD.CreatedDate,
    			TD.CreatedBy,
    			TS.StatusName, 
    			TD.ResolutionDueDate  
      FROM 	    tb_TicketDetails 	TD
      JOIN 	    tb_TicketStatus 	TS on TD.TicketStatusId = TS.StatusId
      WHERE 	TD.CreatedDate BETWEEN p_FromDate AND v_ToDate
      and 	    TD.CompanyId			= p_CompanyId    
      and       TD.ProductId			= p_ProductId
      and       TD.AssignedToGroupId	= IFNULL(p_AssignedToGroupId, TD.AssignedToGroupId);
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
      SELECT COUNT(1) into v_AssignedOpenTickets 
      FROM   Temp_TicketDetails 
      WHERE  StatusName = 'Open';
      
      SELECT COUNT(1) into v_ResolvedTickets
      FROM   Temp_TicketDetails 
      WHERE  StatusName = 'Resolved';
      
      SELECT COUNT(1) into v_InProgressTickets
      FROM   Temp_TicketDetails 
      WHERE  StatusName = 'InProgress';
      
      SELECT COUNT(1) into v_PendingTickets
      FROM   Temp_TicketDetails 
      WHERE  StatusName = 'Pending';
      
      SELECT COUNT(1) into v_OverdueTickets 
      FROM   Temp_TicketDetails 
      WHERE  ResolutionDueDate < CURDATE();
      
      SELECT COUNT(1) into v_ClosedTickets 
      FROM   Temp_TicketDetails 
      WHERE  StatusName = 'Closed';
        
        
        
        SELECT v_AssignedOpenTickets  			as  OpenTickets,
      		   v_ResolvedTickets  				as  ResolvedTickets,
               v_InProgressTickets				as  InProgressTickets,
               v_PendingTickets					as	PendingTickets,
    		   v_OverdueTickets					as  MyOverdueTicketsCount,
               0 								as 	FollowUpTicketsCount,
               v_ClosedTickets					as	MyClosedTickets;
        
        SELECT 
        DATE(CreatedDate) AS Date,
        COUNT(1) AS NoOfTickets
        FROM Temp_TicketDetails
        WHERE CreatedDate BETWEEN p_FromDate AND v_ToDate
        GROUP BY DATE(CreatedDate)
        ORDER BY DATE(CreatedDate);
    	
        
        SELECT 	dense_rank() OVER (ORDER BY TU.UserName) `Rank`			
    		,	TU.UserName		
    		,	TD.StatusName 
            ,	COUNT(1) TicketCount
        FROM 	Temp_TicketDetails	TD
        JOIN 	tb_TicketUser		TU	ON TD.AssignedToAgentId = TU.UserId
        GROUP BY TU.UserName, TD.StatusName;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 		DROP temporary TABLE IF EXISTS Temp_TicketDetails;  
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_TicketDashboardUser` */;
