CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketEmailNotificationsUpdateActive`(
  p_TicketEmailNotificationsId 		INT,
  p_IsActive 						TINYINT
  )
BEGIN
 	DECLARE v_CurDate 		DATETIME;
 	DECLARE v_errcode 		INT 		 DEFAULT -1;
 	DECLARE v_errmsg 		VARCHAR(100) DEFAULT 'No Update';
      
      UPDATE tb_TicketEmailNotifications
      SET  	IsActive 					= IFNULL(p_IsActive,IsActive)
 			, UpdatedDate 				= v_CurDate
      WHERE 	TicketEmailNotificationsId 	= p_TicketEmailNotificationsId;
      
      IF ROW_COUNT() > 0
      THEN
 		 SET v_errcode = 0;
          SET v_errmsg = 'Updated Successfully';
      END IF;
      
      SELECT v_errcode errcode,  v_errmsg errmsg; 
  END ;;
