CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketGetNotification`(	
        p_CompanyId			INT
       ,p_ProductId			INT    
       ,p_LoggedInUserId 		BIGINT
   )
BEGIN    
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
       SELECT 	N.TicketNotificationId
   			,N.TicketId
   			,N.TicketLogDetailId
               ,LD.LogDetails
   			,N.NotificationUserId
   			,N.NotificationUserTypeId
   			,N.IsRead			
               ,N.CreatedDate
               ,T.TicketSubject
               ,T.TicketDescription
               ,T.RequestorId			TicketCreatedByUserId 
               ,T.RequesterName		TicketCreatedByUser
               ,T.AssignedToAgentId	TicketAssignedToUserId 
               ,TU.UserName			TicketAssignedToUser
       FROM 	tb_TicketNotification 	N
       JOIN 	tb_TicketLogDetail		LD	ON N.TicketLogDetailId 	= LD.TicketLogDetailId    
       JOIN 	tb_TicketDetails		T	ON T.TicketId			= LD.TicketId
       JOIN 	tb_TicketUser			TU	ON TU.UserId			= T.AssignedToAgentId
       WHERE 	N.CompanyId 			= p_CompanyId
       AND 	N.ProductId				= p_ProductId
       AND	N.NotificationUserId	= p_LoggedInUserId
       AND 	N.IsRead				= 0
       order by N.UpdatedDate desc;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
