CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketGetUserGroups`(
  	p_CompanyId 	INT,
  	p_UserId 	    INT     
   )
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;	
  	SELECT 	UserName	
          ,	(	SELECT GROUP_CONCAT(InG.GroupName)
  				FROM 	tb_TicketGroup				InG
  				JOIN 	tb_TicketGroupUserMapping 	InGU	ON 	InG.TicketGroupId 	= InGU.TicketGroupId
  															AND	InGU.UserId			= U.UserId
 				WHERE 	InG.IsDeleted = 0
                 AND 	InGU.IsDeleted = 0)		AS GroupName
      FROM 	tb_TicketUser U
  	WHERE 	U.UserId	= p_UserId
      AND 	U.CompanyId	= p_CompanyId;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
