CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_TicketGet_closedTickets`(
p_ServiceProviderCompanyId		INT
)
begin
		declare v_StatusId		INT;

		set session transaction isolation level read uncommitted;
	
		
            select
				t1.TechSupportTicketId
				, t1.ServiceProviderCompanyId
				, t1.CustomerCompanyId
				, t1.TicketSubject
				, t1.TicketSourceId
				, t1.TicketStatusId
				, t1.IsReopen
				, t1.TicketTypeId
				, t1.PriorityId
				, t1.RequestorId
				, t1.AssignedToTeamId
				, t1.AssignedToGroupId
				, t1.AssignedTo
				, t1.ConfidenceScore
				, t1.AssignedTo_Prev
				, t1.AssignedBy
				, t1.TicketChatId
				, t1.SessionId
				, t1.TagId
				, t1.ChannelTypeId
				, t1.ResponseDueDate
				, t1.ResponsedDate
				, t1.ResolutionDueDate
				, t1.ResolvedDate
				, t1.ClosedDate
				, t1.ResolveInformDate
				, t1.FirstResolvedNotification
				, t1.SLAconditionId
				, t1.IsDeleted
				, t1.TicketAssignee
				, t1.TicketLayout
				, t1.TicketDescription
				, t1.RootCause
				, t1.Resolution
				, t1.Summary
				, t1.TicketTagIdName
				, t1.TicketMode
				, t1.RequesterName
				, t1.TicketAssociateCustContact
				, t1.MergedWith
				, t1.isMergedTo
				, t1.FilesUpload
				, t1.ai_chat
				, t1.CreatedBy
				, t1.CreatedDate
				, t1.UpdatedBy
				, t1.UpdatedDate
				from tb_TechSupportTicket 	t1
				left join tb_TicketStatus  		t2 			ON t1.TicketStatusId =  t2.StatusId
				where t2.StatusName = "Closed" and ServiceProviderCompanyId = p_ServiceProviderCompanyId;
            
            
        set session transaction isolation level repeatable read;
end ;;
DELIMITER ;
