CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketLinkDelete`(
  p_TicketLinksId 	INT
  )
BEGIN
   DECLARE v_CurDate DATETIME;
   DECLARE v_errcode INT          DEFAULT -1;
   DECLARE v_errmsg  VARCHAR(100) DEFAULT 'No Update';
      
      UPDATE tb_TicketLinks
      SET  IsDeleted 		= 1,
 		  UpdatedDate 		= v_CurDate
      WHERE TicketLinksId 	= p_TicketLinksId;
      
      IF ROW_COUNT() > 0
      THEN
 		 SET v_errcode = 0;
          SET v_errmsg = 'Updated Successfully';
      END IF;
      
      SELECT v_errcode errcode,  v_errmsg errmsg; 
  END ;;
DELIMITER ;
