CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketPriorityUpdate`(
   p_TicketId 			INT
   ,P_PriorityId			INT	
   ,p_CompanyId 			INT
   ,p_ProductId 			INT
   ,p_LoggedInUserId		INT
    )
BEGIN
   	DECLARE v_errcode  		INT DEFAULT -1;
    	DECLARE v_errmsg   		VARCHAR(55) DEFAULT 'No Update';
   	DECLARE v_CurDate		DATETIME; 
      DECLARE v_LastUpdatedPriorityId INT;
      DECLARE v_PriorityName   VARCHAR(150);
      DECLARE v_TicketLogDetailId INT;
      DECLARE v_RequestorId    INT;
      DECLARE v_AssignedToAgentId INT;
      DECLARE v_TicketAssociateCustContact INT;
       
       SET v_CurDate = NOW();
       
   	UPDATE 	tb_TicketDetails
       SET 	PriorityId 	= P_PriorityId
   		,	 UpdatedBy	= p_LoggedInUserId
   		,	UpdatedDate	= v_CurDate
   	WHERE 	TicketId	= p_TicketId;
      
      SET v_LastUpdatedPriorityId = P_PriorityId;
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
     SELECT RequestorId, AssignedToAgentId, TicketAssociateCustContact
     INTO v_RequestorId, v_AssignedToAgentId, v_TicketAssociateCustContact
     FROM tb_TicketDetails
     WHERE PriorityId = v_LastUpdatedPriorityId;
  	
      SELECT b.TypeCodeName into v_PriorityName
      from tb_TicketDetails a,TypeCode b
      where a.PriorityId = b.TypeCodeID
      and b.TypeGroupID=1116;
 SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
 SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 
      INSERT INTO tb_TicketLogDetail
  		(	TicketId					
  			,LogDetails					
  			,IsDeleted		
  			,CompanyId 
              ,ProductId 
  			,CreatedBy					
  			,CreatedDate				
  			,UpdatedBy					
  			,UpdatedDate				
          )
         select
          (	p_TicketId
  			,CONCAT('Updated Priority to',v_PriorityName)
              ,1
              ,p_CompanyId 
              ,p_ProductId 
  			,0
              ,v_CurDate
              ,0
              ,v_CurDate
          );
          
  		SET v_TicketLogDetailId = last_insert_id();
          
          INSERT INTO tb_TicketNotification
  		(	TicketId					
  			,TicketLogDetailId			
  			,NotificationUserId			
  			,NotificationUserTypeId		
  			,IsRead					
              ,CompanyId 
              ,ProductId 
  			,CreatedBy					
  			,CreatedDate				
  			,UpdatedBy					
  			,UpdatedDate				
          )
          SELECT 	p_TicketId
  			,	v_TicketLogDetailId
  			,	v_RequestorId
              ,	1117001			
              ,	0
              ,	p_CompanyId 
              ,	p_ProductId 
              ,	p_LoggedInUserId
              ,	v_CurDate
              ,	p_LoggedInUserId
              ,	v_CurDate
  		UNION ALL		
  		SELECT 	p_TicketId
  			,	v_TicketLogDetailId
  			,	v_AssignedToAgentId
              ,	1117002			
              ,	0
              ,	p_CompanyId 
              ,	p_ProductId 
              ,	p_LoggedInUserId
              ,	v_CurDate
              ,	p_LoggedInUserId
              ,	v_CurDate 
  		UNION ALL		
  		SELECT	p_TicketId
  			,	v_TicketLogDetailId
  			,	v_TicketAssociateCustContact
              ,	1117003			
              ,	0
              ,	p_CompanyId 
              ,	p_ProductId 
              ,	p_LoggedInUserId
              ,	v_CurDate
              ,	p_LoggedInUserId
              ,	v_CurDate ;
       SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
       IF row_count() > 0
       THEN
   		SET v_errcode 	= 0;
           SET v_errmsg	= 'Updated Successfully';
       END IF;    
       
       select v_errcode 'errcode',	v_errmsg 'errmsg';
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
