CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_TicketSLAUpdateDeleteStatus`(IN p_SLAconditionId 	INT,
  IN	p_IsActive 			TINYINT,
  IN p_IsDeleted 		TINYINT
  )
BEGIN
   DECLARE v_CurDate DATETIME;
   DECLARE v_errcode INT DEFAULT -1;
   DECLARE v_errmsg VARCHAR(100) DEFAULT 'No Update';
      
      UPDATE tb_TicketSLAcondition
      SET  IsActive 			= p_IsActive
 		, IsDeleted 		= IFNULL(p_IsDeleted,IsDeleted)
 		, UpdatedDate 		= v_CurDate
      WHERE SLAconditionId 	= p_SLAconditionId;
      
      IF ROW_COUNT() > 0
      THEN
 		 SET v_errcode = 0;
          SET v_errmsg = 'Updated Successfully';
      END IF;
      
      SELECT v_errcode errcode,  v_errmsg errmsg; 
  END ;;
