CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TicketUpdateReadNotification`(	p_TicketNotificationIds	VARCHAR(250)
    	,p_CompanyId			INT
        ,p_ProductId			INT   
        ,p_IsRead				TINYINT
        ,p_LoggedInUserId 		BIGINT
    )
BEGIN 
    	DECLARE v_errcode 		INT DEFAULT -1;
      	DECLARE v_errmsg 		VARCHAR(200) DEFAULT 'Failure';    
      	DECLARE v_now 			DATETIME;
        
        SET v_now  = NOW();
        
    	DROP TEMPORARY TABLE IF EXISTS temp_TicketNotificationIds;
    	CREATE TEMPORARY table temp_TicketNotificationIds
    	( TicketNotificationId BIGINT );
    	
    	CALL Split(p_TicketNotificationIds,',');
    	
    	INSERT INTO temp_TicketNotificationIds(TicketNotificationId)
    	SELECT Items FROM tt_Split_temptable;    
        
        UPDATE	tb_TicketNotification		N
        JOIN 	temp_TicketNotificationIds	t_N	ON N.TicketNotificationId = t_N.TicketNotificationId
        SET 	N.IsRead		= p_IsRead
    		,	N.UpdatedBy		= p_LoggedInUserId
    		,	N.UpdatedDate 	= v_now;
           
   	IF row_count() > 0 
       THEN
   		SET v_errcode 	= 0;
           SET v_errmsg	= 'Updated Successfully';
       END IF;
       
       SELECT v_errcode 'errcode', v_errmsg 'errmsg';    
 	  DROP TEMPORARY TABLE IF EXISTS temp_TicketNotificationIds;
    END ;;
DELIMITER ;
