CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Ticket_AssignUnassignUserForDefaultGroup`( 
       p_CompanyId			INT
       ,p_ProductId			INT
       ,p_UserId				BIGINT  
       ,p_IsAssign			TINYINT  
      )
SP: BEGIN
     	DECLARE v_now						DATETIME DEFAULT NOW();
         DECLARE v_roleid					TINYINT;
         DECLARE v_Priority					TINYINT;
         DECLARE v_TicketGroupId			INT;
         DECLARE v_TicketGroupUserMappingId	BIGINT;
         DECLARE v_ExistPriority			TINYINT;
         
         SELECT roleid INTO v_roleid
         FROM 	tb_User 
         WHERE 	UserID = p_UserId; 
         
         SELECT TicketGroupId INTO v_TicketGroupId 
         FROM 	tb_TicketGroup
         WHERE 	CompanyId	= p_CompanyId
         AND 	ProductId	= p_ProductId
         AND 	IsDefault	= 1;				
         
         DROP TEMPORARY TABLE IF EXISTS tt_priority;
         CREATE TEMPORARY TABLE tt_priority(
 			Priority	TINYINT,
 			roleid		SMALLINT,	
 			NoOfUser	SMALLINT	
         );
         
     	SELECT 	TicketGroupUserMappingId, CASE WHEN IsActive = 1 THEN Priority ELSE NULL END
     	INTO 	v_TicketGroupUserMappingId, v_ExistPriority
     	FROM 	tb_TicketGroupUserMapping
     	WHERE 	TicketGroupId 	= v_TicketGroupId
     	AND 	UserId			= p_UserId
     	AND 	CompanyId		= p_CompanyId
         AND 	ProductId		= p_ProductId;
         
         IF p_IsAssign = 1
         THEN
     		INSERT INTO tt_priority(Priority, roleid, NoOfUser)
     		WITH CTE_priority AS( 
     			SELECT 1 AS Priority
     			UNION ALL
     			SELECT 2 AS Priority
     			UNION ALL
     			SELECT 3 AS Priority
     			UNION ALL
     			SELECT 4 AS Priority
     		)    
     		SELECT 	P.Priority 
     			,	U.roleid
     			,	SUM(CASE WHEN U.roleid IS NOT NULL THEN 1 ELSE 0 END) 	AS NoOfUser        
     		FROM 	CTE_priority				P
     		LEFT JOIN tb_TicketGroupUserMapping GU 	ON 	GU.Priority		= P.Priority
     												AND GU.CompanyId	= p_CompanyId
                                                     AND GU.ProductId	= p_ProductId
     												AND	GU.IsDeleted	= 0
     												AND GU.IsActive		= 1
     		LEFT JOIN tb_TicketGroup			G	ON 	G.TicketGroupId	= GU.TicketGroupId	
     												AND G.TicketGroupId = v_TicketGroupId
     												AND	G.IsDefault		= 1
     		LEFT JOIN tb_User					U	ON  U.UserID		= GU.UserId											
     		GROUP BY P.Priority, U.roleid;
     		
     		DROP TEMPORARY TABLE IF EXISTS tt_priority1; 
     		CREATE TEMPORARY TABLE tt_priority1 
     		SELECT * FROM tt_priority;
     		
     		IF v_roleid = 3 
     		THEN 			
     			INSERT INTO tb_TicketGroupUserMapping(	
     				TicketGroupId				
     				,UserId						
     				,IsActive					
     				,IsDeleted					
     				,CompanyId					
     				,ProductId	
     				,Priority
     				,CreatedBy					
     				,CreatedDate				
     				,UpdatedBy					
     				,UpdatedDate
     			)
     			SELECT 	v_TicketGroupId		
     				,	p_UserId
     				,	1
     				,	0
     				,	p_CompanyId		
     				,	p_ProductId		
     				,	P.Priority
     				,	0
     				,	v_now
     				,	0
     				,	v_now
     			FROM 	tt_priority P
     			WHERE 	P.NoOfUser			= 0 
  			AND 	IFNULL(P.roleid,6)	IN (5,6); 	
     		ELSEIF v_roleid = 5 
     		THEN
     			IF IFNULL((SELECT NoOfUser FROM tt_priority WHERE Priority = 1 AND roleid = 5),0) < IFNULL((SELECT NoOfUser FROM tt_priority1 WHERE Priority = 2 AND roleid = 5),0)
     			THEN
     				SET v_Priority = 1;
     			ELSEIF IFNULL((SELECT NoOfUser FROM tt_priority WHERE Priority = 1 AND roleid = 5),0) > IFNULL((SELECT NoOfUser FROM tt_priority1 WHERE Priority = 2 AND roleid = 5),0)
                 THEN
     				SET v_Priority = 2;
     			ELSE
     				SET v_Priority = IFNULL(v_ExistPriority,2);
     			END IF;
     		ELSEIF v_roleid = 6 
     		THEN
     			IF IFNULL((SELECT NoOfUser FROM tt_priority WHERE Priority = 3 AND roleid = 6),0) < IFNULL((SELECT NoOfUser FROM tt_priority1 WHERE Priority = 4 AND roleid = 6),0)
     			THEN
     				SET v_Priority = 3;
     			ELSEIF IFNULL((SELECT NoOfUser FROM tt_priority WHERE Priority = 3 AND roleid = 6),0) > IFNULL((SELECT NoOfUser FROM tt_priority1 WHERE Priority = 4 AND roleid = 6),0)
                 THEN
     				SET v_Priority = 4;
     			ELSE
     				SET v_Priority = IFNULL(v_ExistPriority,4);
     			END IF;
     		END IF;
     		
     		IF v_roleid IN (5,6)
     		THEN    
     			IF v_TicketGroupUserMappingId IS NULL
     			THEN
     				INSERT INTO tb_TicketGroupUserMapping(	
     					TicketGroupId				
     					,UserId						
     					,IsActive					
     					,IsDeleted					
     					,CompanyId					
     					,ProductId	
     					,Priority
     					,CreatedBy					
     					,CreatedDate				
     					,UpdatedBy					
     					,UpdatedDate
     				)
     				VALUES(	
     					v_TicketGroupId		
     				,	p_UserId
     				,	1
     				,	0
     				,	p_CompanyId		
     				,	p_ProductId		
     				,	v_Priority
     				,	0
     				,	v_now
     				,	0
     				,	v_now
     				);
     			ELSE
     				UPDATE 	tb_TicketGroupUserMapping
     				SET 	IsActive		= 1				
     					,	IsDeleted		= 0
     					,	Priority		= v_Priority			
     					,	UpdatedBy		= 0
     					,	UpdatedDate 	= v_now
     				WHERE 	TicketGroupUserMappingId = v_TicketGroupUserMappingId;
     			END IF;
     		END IF;
     	ELSEIF p_IsAssign = 0
         THEN
     		UPDATE 	tb_TicketGroupUserMapping
     		SET 	IsActive		= 0				
     			,	IsDeleted		= 1			
     			,	UpdatedBy		= 0
     			,	UpdatedDate 	= v_now
     		WHERE 	TicketGroupUserMappingId = v_TicketGroupUserMappingId;        
     	END IF; 
         
     	TRUNCATE TABLE tt_priority;
     	INSERT INTO tt_priority(Priority, roleid, NoOfUser)
     	WITH CTE_priority AS( 
     		SELECT 1 AS Priority
     		UNION ALL
     		SELECT 2 AS Priority
     		UNION ALL
     		SELECT 3 AS Priority
     		UNION ALL
     		SELECT 4 AS Priority
     	)    
     	SELECT 	P.Priority 
     		,	U.roleid
     		,	SUM(CASE WHEN U.roleid IS NOT NULL THEN 1 ELSE 0 END) 	AS NoOfUser        
     	FROM 	CTE_priority				P
     	LEFT JOIN tb_TicketGroupUserMapping GU 	ON 	GU.Priority		= P.Priority
     											AND GU.CompanyId	= p_CompanyId
                                                 AND GU.ProductId	= p_ProductId
     											AND	GU.IsDeleted	= 0
     											AND GU.IsActive		= 1
     	LEFT JOIN tb_TicketGroup			G	ON 	G.TicketGroupId	= GU.TicketGroupId			
     											AND G.TicketGroupId = v_TicketGroupId
     											AND	G.IsDefault		= 1
     	LEFT JOIN tb_User					U	ON  U.UserID		= GU.UserId											
     	GROUP BY P.Priority, U.roleid;    
         
         
         UPDATE 	tb_TicketGroupUserMapping 	GU
         JOIN 	tb_User						U	ON U.UserId	= GU.UserId
         SET 	GU.IsActive			= 1
     		,	GU.IsDeleted		= 0	
     		,	GU.UpdatedDate		= v_now
         WHERE 	GU.TicketGroupId 	= v_TicketGroupId
         AND		U.RoleId			= 3	
         AND		GU.CompanyId		= p_CompanyId
         AND 	GU.ProductId		= p_ProductId
         AND		GU.IsDeleted		= 1    
         AND 	EXISTS (SELECT 1 FROM tt_priority InP WHERE GU.Priority = InP.Priority AND roleid <> 3 AND NoOfUser = 0);    
         
         
         UPDATE 	tb_TicketGroupUserMapping 	GU
         JOIN 	tb_User						U	ON U.UserId	= GU.UserId
         SET 	GU.IsActive			= 0
     		,	GU.IsDeleted		= 1	
     		,	GU.UpdatedDate		= v_now
         WHERE 	GU.TicketGroupId 	= v_TicketGroupId
         AND		U.RoleId			= 3	
         AND		GU.CompanyId		= p_CompanyId
         AND 	GU.ProductId		= p_ProductId
         AND		GU.IsDeleted		= 0
         AND 	GU.IsActive			= 1
         AND 	EXISTS (SELECT 1 FROM tt_priority InP WHERE GU.Priority = InP.Priority AND roleid <> 3 AND NoOfUser > 0);
      END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Ticket_CreateDefaultGroup` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Ticket_CreateDefaultGroup`(
      p_CompanyId		INT
      ,p_ProductId		INT
      ,p_UserId			BIGINT  
      ,p_department		VARCHAR(100)
     )
BEGIN
 		DECLARE v_errcode 			INT DEFAULT -1;
 		DECLARE v_errmsg 			VARCHAR(50) DEFAULT 'Failure';
 		DECLARE v_CurDate			DATETIME;
 		DECLARE v_TicketGroupId		INT; 
 		DECLARE v_BusinessHoursId	INT;
		DECLARE v_isTechSupport			TINYINT;
        DECLARE v_DepartTicketGroupId	INT; 
              
		SET v_CurDate = NOW();

		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
		SELECT 	isTechSupport  
        INTO 	v_isTechSupport 
        FROM 	tb_companyDomain 
