 				);
 			   
 				SET v_BusinessHoursId = last_insert_id();
 			   
 				INSERT INTO tb_TicketBusinessHoursTimings
 				(	BusinessHoursId		
 					,BusinessDayTypeId		
 					,FromHours				
 					,FromAMPM	
 					,ToHours				
 					,ToAMPM		
 					,IsDayOff				
 					,IsDeleted				
