 				VALUES	(v_BusinessHoursId,1104002,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
 						,(v_BusinessHoursId,1104003,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
 						,(v_BusinessHoursId,1104004,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
 						,(v_BusinessHoursId,1104005,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
 						,(v_BusinessHoursId,1104006,'9:00','AM','6:00','PM',0,0,0,v_CurDate,0,v_CurDate)
 						,(v_BusinessHoursId,1104007,'','','','',1,0,0,v_CurDate,0,v_CurDate)
 						,(v_BusinessHoursId,1104001,'','','','',1,0,0,v_CurDate,0,v_CurDate);
