               ,0					
               ,v_TicketGroupId 	
               );
    		END IF;
            
        IF v_isTechSupport = 1 
        THEN
			SELECT 	TicketGroupId
            INTO 	v_DepartTicketGroupId
			FROM 	tb_TicketGroup
			WHERE 	CompanyId	= p_CompanyId
