CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Ticket_DashboardTicketVolumeTrendAndDistributionChart`(
  	p_CompanyId 				INT,
  	p_ProductId					INT,
  	p_FromDate 					DATE,
  	p_ToDate 		    		DATE
 
   )
BEGIN	
  	DECLARE v_FromDateTime		DATETIME;
  	DECLARE v_ToDateTime		DATETIME;
     DECLARE v_DateDifference	SMALLINT;
  	DECLARE v_interval			TINYINT;    
 
     SET v_DateDifference = DATEDIFF(p_ToDate, p_FromDate);
      
 	DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
  	CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME, endDateTime	DATETIME);
      
 	SET v_FromDateTime	= p_FromDate;
 	SET v_ToDateTime 	= DATE_ADD(DATE_ADD(DATE_ADD(p_ToDate, INTERVAL 23 HOUR),INTERVAL 59 MINUTE),INTERVAL 59 SECOND);     
 	
      IF v_DateDifference = 0
      THEN	
   		INSERT INTO tmp_timings(startDateTime, endDateTime)
  		WITH RECURSIVE CTE_TIMINGS AS (
  			SELECT 	v_FromDateTime AS FromDateTime, DATE_ADD(DATE_ADD(v_FromDateTime,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS ToDateTime
  			UNION ALL
  			SELECT 	DATE_ADD(FromDateTime,INTERVAL 1 HOUR) AS FromDateTime , DATE_ADD(ToDateTime,INTERVAL 1 HOUR) AS ToDateTime
  			FROM 	CTE_TIMINGS
  			WHERE 	ToDateTime < v_ToDateTime
  		)
  		SELECT * FROM CTE_TIMINGS;	
  	ELSEIF v_DateDifference < 60
 	THEN
  		INSERT INTO tmp_timings(startDateTime, endDateTime)
  		WITH RECURSIVE CTE_TIMINGS AS (
  			SELECT 	v_FromDateTime AS FromDateTime, DATE_ADD(DATE_ADD(DATE_ADD(v_FromDateTime,INTERVAL 59 MINUTE),INTERVAL 59 SECOND),INTERVAL 23 HOUR) AS ToDateTime
  			UNION ALL
  			SELECT 	DATE_ADD(FromDateTime,INTERVAL 1 DAY) AS FromDateTime , DATE_ADD(ToDateTime,INTERVAL 1 DAY) AS ToDateTime
  			FROM 	CTE_TIMINGS
  			WHERE 	ToDateTime < v_ToDateTime
  		)
  		SELECT * FROM CTE_TIMINGS;	
  	ELSE
  		INSERT INTO tmp_timings(startDateTime, endDateTime)
  		WITH RECURSIVE CTE_TIMINGS AS (
  			SELECT 	v_FromDateTime AS FromDateTime, DATE_ADD(DATE_ADD(DATE_ADD(LAST_DAY(v_FromDateTime),INTERVAL 59 MINUTE),INTERVAL 59 SECOND),INTERVAL 23 HOUR) AS ToDateTime
  			UNION ALL
  			SELECT	DATE_ADD(LAST_DAY(FromDateTime),INTERVAL 1 DAY) AS FromDateTime
 				, 	DATE_ADD(DATE_ADD(DATE_ADD(LAST_DAY(DATE_ADD(ToDateTime,INTERVAL 1 DAY)),INTERVAL 59 MINUTE),INTERVAL 59 SECOND),INTERVAL 23 HOUR)		AS ToDateTime
  			FROM 	CTE_TIMINGS
  			WHERE 	ToDateTime < v_ToDateTime
  		)
  		SELECT * FROM CTE_TIMINGS;	    
      END IF;
     
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     DROP TEMPORARY TABLE IF EXISTS tt_TicketDetails;
     CREATE TEMPORARY TABLE tt_TicketDetails
 	SELECT	1															AS Ticket
 		,	CASE WHEN TS.SLATimer = 1102002  THEN 1 ELSE 0 END 	AS Resolved
         ,	TS.StatusName
         ,	TD.CreatedDate
 	FROM 	tb_TicketDetails 	TD
 	JOIN 	tb_TicketStatus 	TS ON TD.TicketStatusId = TS.StatusId
 	WHERE 	TD.CreatedDate 	BETWEEN v_FromDateTime AND v_ToDateTime
 	AND 	TD.CompanyId	= p_CompanyId    
 	AND    	TD.ProductId	= p_ProductId;
     SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
     
     SELECT	T.startDateTime	
 		, 	T.endDateTime
         ,	IFNULL(SUM(Ticket),0)	AS CreatedTicket
         ,	IFNULL(SUM(Resolved),0)	AS ResolvedTicket
     FROM 	tmp_timings			T
     LEFT JOIN tt_TicketDetails	t_TD	ON t_TD.CreatedDate BETWEEN T.startDateTime AND T.endDateTime
     GROUP BY T.startDateTime, T.endDateTime;
     
 	SELECT 	T.startDateTime	
 		, 	T.endDateTime
         ,	t_TD.StatusName
         ,	IFNULL(SUM(CASE WHEN t_TD.StatusName IS NOT NULL THEN 1 ELSE 0 END),0)	AS TicketCount
     FROM 	tmp_timings			T
     LEFT JOIN tt_TicketDetails	t_TD 	ON t_TD.CreatedDate BETWEEN T.startDateTime AND T.endDateTime
     GROUP BY T.startDateTime, T.endDateTime, t_TD.StatusName;
     
     SELECT t_TD.StatusName	AS DistributionStatus	
         ,  COUNT(1)			AS DistributionStatusTicketCount
     FROM  	tt_TicketDetails	t_TD 	
     GROUP BY  t_TD.StatusName;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_Ticket_DashboardTicketVolumeTrendChart` */;
