CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Ticket_DashboardTicketVolumeTrendChart`(
	p_CompanyId 				INT,
	p_ProductId					INT,
	p_FromDate 					DATE,
	p_ToDate 		    		DATE,
	p_LoggedInUserID 	       	BIGINT     
 )
BEGIN	
	DECLARE v_FromDateTime		DATETIME;
	DECLARE v_ToDateTime		DATETIME;
    DECLARE v_DateDifference	SMALLINT;
	DECLARE v_interval			TINYINT;    
    
    SET v_DateDifference = DATEDIFF(p_ToDate,p_FromDate);
    
    DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
	CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME, endDateTime	DATETIME);
    
    SET v_FromDateTime	= p_FromDate;
    SET v_ToDateTime 	= DATE_ADD(DATE_ADD(DATE_ADD(p_ToDate, INTERVAL 23 HOUR),INTERVAL 59 MINUTE),INTERVAL 59 SECOND);
    
    select v_DateDifference;
    
    IF v_DateDifference = 0
    THEN	
 		INSERT INTO tmp_timings(startDateTime, endDateTime)
		WITH RECURSIVE CTE_TIMINGS AS (
			SELECT 	v_FromDateTime AS FromDateTime, DATE_ADD(DATE_ADD(v_FromDateTime,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS ToDateTime
			UNION ALL
			SELECT 	DATE_ADD(FromDateTime,INTERVAL 1 HOUR) AS FromDateTime , DATE_ADD(ToDateTime,INTERVAL 1 HOUR) AS ToDateTime
			FROM 	CTE_TIMINGS
			WHERE 	ToDateTime < v_ToDateTime
		)
		SELECT * FROM CTE_TIMINGS;	
	ELSEIF v_DateDifference < 60
    THEN
		INSERT INTO tmp_timings(startDateTime, endDateTime)
		WITH RECURSIVE CTE_TIMINGS AS (
			SELECT 	v_FromDateTime AS FromDateTime, DATE_ADD(DATE_ADD(DATE_ADD(v_FromDateTime,INTERVAL 59 MINUTE),INTERVAL 59 SECOND),INTERVAL 23 HOUR) AS ToDateTime
			UNION ALL
			SELECT 	DATE_ADD(FromDateTime,INTERVAL 1 DAY) AS FromDateTime , DATE_ADD(ToDateTime,INTERVAL 1 DAY) AS ToDateTime
			FROM 	CTE_TIMINGS
			WHERE 	ToDateTime < v_ToDateTime
		)
		SELECT * FROM CTE_TIMINGS;	
	ELSE
		INSERT INTO tmp_timings(startDateTime, endDateTime)
		WITH RECURSIVE CTE_TIMINGS AS (
			SELECT 	v_FromDateTime AS FromDateTime, DATE_SUB(DATE_ADD(v_FromDateTime,INTERVAL 1 MONTH), INTERVAL 1 SECOND) AS ToDateTime
			UNION ALL
			SELECT 	DATE_ADD(FromDateTime,INTERVAL 1 MONTH) AS FromDateTime , DATE_ADD(ToDateTime,INTERVAL 1 MONTH) AS ToDateTime
			FROM 	CTE_TIMINGS
			WHERE 	ToDateTime < v_ToDateTime
		)
		SELECT * FROM CTE_TIMINGS;	    
    END IF;
    
    SELECT * FROM tmp_timings;
 END ;;
DELIMITER ;
