CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ticket_get_duplicate_email_dtl`(
p_domainId			INT
)
BEGIN
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
   
			SELECT emailId, count(emailId) as duplicateCount
					FROM tb_User 
			WHERE domainId = p_domainId GROUP BY emailId
            HAVING duplicateCount > 1;
		
   
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
