CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_ticket_get_new_user_dtl`(
p_domainId			INT,
p_createdOn			DATE
)
BEGIN
			SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
   
			SELECT count(UserID) AS NewUserCount FROM tb_User where domainId = p_domainId AND DATE(createdAt) = IFNULL(p_createdOn, current_date());
            
            SELECT UserID, UserName,  emailId FROM tb_User where domainId = p_domainId AND date(createdAt) = IFNULL(p_createdOn, current_date());  
   
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
END ;;
