CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Tpi_New_call`(
      IN p_domainId INT
  )
BEGIN
	DECLARE v_Today DATE;
	DECLARE v_curTIMESTAMP BIGINT;

	SET v_curTIMESTAMP = UNIX_TIMESTAMP();
	SET v_Today = CURDATE();
      
	DROP TEMPORARY TABLE IF EXISTS temp_AgentBycall;
	CREATE TEMPORARY TABLE temp_AgentBycall (
          CallDurationHistoryId INT,
          sessionStartTime 		BIGINT,
          sessionEndTime 		BIGINT,
          customerNumber 		VARCHAR(20),
          disconnectedBy 		BIGINT,
          calledNumber 			BIGINT,
          callDuration 			BIGINT,
          agentId 				INT,
          callType 				VARCHAR(255)
      );
  
      INSERT INTO temp_AgentBycall
      SELECT
          DH.CallDurationHistoryId as id,
  		H.sessionStartTime,
  		H.sessionEndTime,
          H.customerNumber,
          H.disconnectedBy,
          H.calledNumber,
          H.callDuration,
          DH.agentId,
          CASE
              WHEN H.IsInBound = 1 AND H.IsAbandoned = 1 THEN 'missedcall'
              WHEN H.IsInBound = 1 AND H.IsAbandoned = 0 THEN 'incomingcall'
              WHEN H.IsInBound = 0 AND H.IsAbandoned = 0 THEN 'outgoingcall'
              ELSE 'unknown'
          END AS callType
      FROM
          tb_CallHistory H
      JOIN tb_CallDurationHistory DH ON DH.CallHistoryId = H.CallHistoryId
      WHERE
          H.domainId = p_domainId
          AND DATE(H.createdAt) = v_Today;
  
          IF (SELECT COUNT(*) FROM temp_AgentBycall) = 0 THEN
           INSERT INTO temp_AgentBycall (CallDurationHistoryId , sessionStartTime, sessionEndTime, customerNumber, disconnectedBy, calledNumber, callDuration, agentId, callType)
           VALUES (123456, v_curTIMESTAMP, v_curTIMESTAMP, 447451444108, 447451444108, 919566052683, 12345, 123, 'incomingcall');
  
 
      END IF;
  
      SELECT CallDurationHistoryId as id, sessionStartTime, sessionEndTime, customerNumber, disconnectedBy, calledNumber, callDuration, agentId  FROM temp_AgentBycall;
  END ;;
DELIMITER ;
