CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_TransaferCallMessage`(	
   p_SourceCallDurationHistoryId			BIGINT
   ,p_DestinationCallDurationHistoryId		BIGINT
   )
BEGIN
  	DECLARE v_CurDate		DATETIME;
  	DECLARE v_errCode		INT				DEFAULT -1;
  	DECLARE v_errMsg		VARCHAR(150) 	DEFAULT 'No Message Transfered';
  	DECLARE v_SourceCallDurationHistoryId	BIGINT;    
       
  	SET v_CurDate = NOW();
   	
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
  	SELECT 	CallDurationHistoryId INTO v_SourceCallDurationHistoryId
  	FROM 	tb_CallMessage
  	WHERE 	CallDurationHistoryId = p_SourceCallDurationHistoryId;
  	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
       
  	IF v_SourceCallDurationHistoryId IS NOT NULL
  	THEN
  		INSERT INTO tb_CallMessage     
  		(	CallDurationHistoryId
  			,CallHistoryId
  			,Message             
  			,createdAt
  			,updatedAt
  		)
  		SELECT 	p_DestinationCallDurationHistoryId
  			,	CallHistoryId
  			,	Message             
  			,	v_CurDate
  			,	v_CurDate
  		FROM 	tb_CallMessage
  		WHERE 	CallDurationHistoryId = p_SourceCallDurationHistoryId;
           
  		SET	v_errCode	= 0
  		, 	v_errMsg	= 'Message Transfered Successfully'; 
  	END IF; 
      
  	
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
