CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateAgentStatus`(
      	p_DomainId		INT
      	,p_ext			INT
      	,p_statusName	VARCHAR(250)
       )
BEGIN
      	DECLARE v_errcode		INT 			DEFAULT -1; 
      	DECLARE v_errmsg		VARCHAR(100) 	DEFAULT 'Failure'; 
      	DECLARE v_CurDate		BIGINT; 
      	DECLARE v_status_id 	int;
     

		DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
			SHOW ERRORS;   
			ROLLBACK;   
		END;
           
      	SET v_CurDate = NOW();
        
       START TRANSACTION;
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
   		SELECT	aid	
   		INTO 	v_status_id 
   		FROM 	agent_status 
          WHERE 	domainId 	= p_DomainId 
          AND 	statusName  COLLATE utf8mb4_unicode_ci = p_statusName limit 1;
  		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;	
      
      	UPDATE 	tb_User						U
      	
      												
      	SET 	U.StatusID		= v_status_id
      	,		U.updatedAt		= v_CurDate
  		,		U.stateTimer	= unix_timestamp(now())  
      	WHERE 	U.domainId		= p_DomainId
      	AND 	U.ext			= p_ext;
           
   	IF row_count() > 0
   	THEN
   		SET v_errcode 	= 0;
   		SET v_errmsg 	= 'Updated Successfully';
   	END IF;
   	COMMIT;
   	SELECT v_errcode errcode, v_errmsg	errmsg;
   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
