CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateAssignAgentToCall`(
	 p_AssignedBy		BIGINT
	,p_AssignedTo		BIGINT	
	,p_AssignedOn		BIGINT	
	,p_CallHistoryId	BIGINT    
 )
BEGIN
 	DECLARE v_Curdate	DATETIME;	
     
     SET v_Curdate = NOW();
     
     UPDATE tb_CallHistory
     SET 	AssignedBy	= p_AssignedBy
 		 ,	AssignedTo	= p_AssignedTo
         ,	AssignedOn	= p_AssignedOn        
         ,	UpdatedAt	= v_Curdate
     WHERE 	CallHistoryId = p_CallHistoryId;
     
     UPDATE tb_CallDurationHistory
     SET	AgentId = p_AssignedTo
     WHERE  CallHistoryId = p_CallHistoryId;
     
     SELECT 0 errcode,'Agent assigned to Call successfully' errmsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
