CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateAssignAgentToEmail`(
    	 p_AssignedBy		BIGINT
    	,p_AssignedTo		BIGINT	
    	,p_AssignedOn		BIGINT	
    	,p_EmailHistoryId	BIGINT    
      ,p_Istransferred	TINYINT
      ,p_SessionId		VARCHAR(250)
     )
BEGIN
  	DECLARE v_CurDate			DATETIME;
      DECLARE v_CurUnixTime		BIGINT;
      DECLARE v_rootParentId		BIGINT;
      DECLARE v_EmailHistoryId	BIGINT;
         
      SET v_CurDate 		= NOW();
      SET v_CurUnixTime	= UNIX_TIMESTAMP(NOW(3)) * 1000;
         
      IF IFNULL(p_Istransferred,0) = 0
      THEN
  		UPDATE tb_EmailHistory
  		SET 	AssignedBy		= p_AssignedBy
  			,	AssignedTo		= p_AssignedTo
  			,	AssignedOn		= p_AssignedOn        
  			,	UpdatedAt		= v_CurDate
  		WHERE 	EmailHistoryId 	= p_EmailHistoryId;
  
  		UPDATE 	tb_EmailDurationHistory
  		SET		AgentId = p_AssignedTo
  		WHERE  EmailHistoryId = p_EmailHistoryId;        
  	ELSE
  		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
  		SELECT 	rootParentId INTO v_rootParentId
  		FROM 	tb_EmailHistory
          WHERE	EmailHistoryId = p_EmailHistoryId;           
          
  		INSERT INTO tb_EmailHistory
          (	SessionId
  			,SessionStartTime
  			,SessionEndTime
  			,FromEmail
  			,ToEmail
  			,EmailSubject
  			,EmailFlowSourceId
  			,CompanyId
  			,DomainId
  			,DispositionId
  			,Summary
  			,IsInBound
  			,AssignedTo
  			,AssignedBy
  			,AssignedOn
  			,AfterEmailWorkTime
  			,Istransferred
              ,transferredTo
              ,immediateParentId
  			,rootParentId
  			,TransferredTypeId            
  			,transferredDate
  			,IsSessionClosed
  			,CustomerId
  			,TicketId
  			,SupervisorName
  			,repliedDate
  			,discardedDate
              ,SentimentalScore
  			,CreatedAt
  			,UpdatedAt			
          )
  		SELECT 	p_SessionId					
  			,	SessionStartTime
  			,	SessionEndTime
  			,	FromEmail
  			,	ToEmail
  			,	EmailSubject
  			,	EmailFlowSourceId
  			,	CompanyId
  			,	DomainId
  			,	NULL				AS DispositionId
  			,	NULL				AS Summary
  			,	IsInBound
  			,	p_AssignedTo
  			,	p_AssignedBy
  			,	v_CurUnixTime		AS AssignedOn
  			,	0					AS AfterEmailWorkTime
  			,	0					AS Istransferred
 			,	0					AS transferredTo
 			,	p_EmailHistoryId	AS immediateParentId
  			,	IFNULL(v_rootParentId,p_EmailHistoryId)		AS rootParentId
  			,	NULL				AS TransferredTypeId
  			,	v_CurDate			AS transferredDate
  			,	0					AS IsSessionClosed
  			,	CustomerId
  			,	TicketId
  			,	SupervisorName
  			,	NULL				AS repliedDate
  			,	NULL				AS discardedDate
              ,	NULL				AS SentimentalScore
  			,	v_CurDate
  			,	v_CurDate			        
          FROM 	tb_EmailHistory
          WHERE	EmailHistoryId = p_EmailHistoryId; 
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
  
 		SET v_EmailHistoryId = last_insert_id();    
  		
  		INSERT INTO tb_EmailDurationHistory
          (	EmailHistoryId
  			,AgentId 			
  			,IsBot
  			,BotId
  			,CreatedAt
  			,UpdatedAt
          )
          SELECT v_EmailHistoryId		
  			 ,	p_AssignedTo
              ,	0
              ,	NULL
              ,	v_CurDate
              ,	v_CurDate;		
          
          SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
          INSERT INTO tb_EmailMessage
          (	EmailHistoryId
  			,Message
  			,CreatedAt
  			,UpdatedAt    
  		)
          SELECT v_EmailHistoryId
  			 ,	Message
              ,	v_CurDate
              ,	v_CurDate
          FROM 	tb_EmailMessage 
          WHERE	EmailHistoryId = p_EmailHistoryId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
          
          UPDATE tb_EmailHistory	
          SET 	Istransferred 	= 1
 			,	transferredTo	= p_AssignedTo
             ,	transferredDate	= v_CurDate
          WHERE 	EmailHistoryId	= p_EmailHistoryId;
  	END IF; 
     
  	SELECT 0 errcode,'Agent assigned to Email successfully' errmsg;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_UpdateAssignAgentToFacebook` */;
