CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateAssignAgentToFacebook`(	
  	p_AssignedBy		BIGINT
  	,p_AssignedTo		BIGINT	
  	,p_AssignedOn		BIGINT	
  	,p_FacebookHistoryId		BIGINT
  	,p_Istransferred	TINYINT
  	,p_SessionId		VARCHAR(250)
      )
BEGIN
 	DECLARE v_CurDate				DATETIME;
 	DECLARE v_CurUnixTime			BIGINT;
     DECLARE v_rootParentId			BIGINT;
     DECLARE v_FacebookHistoryId		BIGINT;	
          
 	SET v_Curdate = NOW();
   	SET v_CurUnixTime	= UNIX_TIMESTAMP(NOW(3)) * 1000;
       
 	IF IFNULL(p_Istransferred,0) = 0
 	THEN       
 		UPDATE 	tb_FacebookHistory
 		SET 	AssignedBy	= p_AssignedBy
 			,	AssignedTo	= p_AssignedTo
 			,	AssignedOn	= p_AssignedOn        
             ,	AgentId 	= p_AssignedTo
 			,	UpdatedAt	= v_Curdate
 		WHERE 	FacebookHistoryId = p_FacebookHistoryId;
 	ELSE
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT 	rootParentId INTO v_rootParentId
 		FROM 	tb_FacebookHistory
 		WHERE	FacebookHistoryId = p_FacebookHistoryId;  
         
 		INSERT INTO tb_FacebookHistory
 		(	sessionId
			,sessionStartTime
			,sessionEndTime
			,domainId
			,dispositionId
			,Summary
			,IsInBound
			,assignedTo
			,assignedBy
			,assignedOn
			,afterFacebookWorkTime
			,Istransferred
			,transferredTo
			,immediateParentId
			,rootParentId
			,transferredTypeId
			,transferredDate
            ,IsSessionClosed
			,customerFacebookId
			,agentFacebookId
			,ticketId
			,repliedDate
			,discardedDate
			,SentimentalScore
			,AgentId
			,IsBot
			,BotId
			,createdAt
			,updatedAt
            ,markAsRead
 		)
 		SELECT 	p_SessionId						
 			,	sessionStartTime
 			,	sessionEndTime
 			,	domainId
 			,	NULL					AS dispositionId
 			,	NULL					AS Summary
 			,	IsInBound		
 			,	p_AssignedTo			AS assignedTo
 			,	p_AssignedBy			AS assignedBy
 			,	v_CurUnixTime			AS assignedOn
 			,	NULL					AS afterFacebookWorkTime
 			,	0						AS Istransferred
 			,	0						AS transferredTo
 			,	p_FacebookHistoryId			AS immediateParentId
 			,	IFNULL(v_rootParentId,p_FacebookHistoryId)		AS 	rootParentId
 			,	NULL					AS transferredTypeId
 			,	v_CurDate				AS transferredDate
 			,	0						AS IsSessionClosed
 			,	customerFacebookId
 			,	agentFacebookId
 			,	ticketId
 			,	NULL					AS repliedDate
 			,	NULL					AS discardedDate
 			,	NULL					AS SentimentalScore			
             ,	p_AssignedTo
 			,	0
 			,	NULL
 			,	v_CurDate
 			,	v_CurDate	
            ,	0
 		FROM 	tb_FacebookHistory
 		WHERE	FacebookHistoryId = p_FacebookHistoryId;        
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
   
   		SET v_FacebookHistoryId = last_insert_id();    
            
 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
 		INSERT INTO tb_FacebookMessage
 		(	FacebookHistoryId
 			,Message
 			,CreatedAt
 			,UpdatedAt    
 		)
 		SELECT 	v_FacebookHistoryId
 			,	Message
 			,	v_CurDate
 			,	v_CurDate
 		FROM 	tb_FacebookMessage 
 		WHERE	FacebookHistoryId = p_FacebookHistoryId;
 		SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
            
 		UPDATE tb_FacebookHistory	
 		SET 	Istransferred 	= 1
 			,	transferredTo	= p_AssignedTo
 			,	transferredDate	= v_CurDate
 		WHERE 	FacebookHistoryId	= p_FacebookHistoryId;        
           
   	END IF;
    
		SELECT 	FH.FacebookHistoryId
		,	FH.sessionId
		,	CAST(FH.customerFacebookId AS CHAR) AS customerFacebookId
		,	CAST(FH.agentFacebookId AS CHAR) AS agentFacebookId
		,	FH.domainId
		FROM 	tb_FacebookHistory	FH
		WHERE	FacebookHistoryId = v_FacebookHistoryId;
       
   	SELECT 0 errcode,'Agent assigned to Facebook successfully' errmsg;
   END ;;
DELIMITER ;
