CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateCallBackCallHistoryId`(	p_ParentCallHistoryId		bigint,
	p_CallBacksessionId		varchar(250)
)
BEGIN
	DECLARE v_CallHistoryId		BIGINT;
    DECLARE v_errCode 			TINYINT;
    DECLARE v_errMsg 			VARCHAR(250);
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    SELECT 	CallHistoryId INTO v_CallHistoryId
    FROM 	tb_CallHistory
    WHERE 	sessionId	= p_CallBacksessionId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
    
    IF v_CallHistoryId IS NOT NULL
    THEN
		UPDATE 	tb_CallHistory
		SET 	CallBackCallHistoryId 	= v_CallHistoryId
			,	callBack				= 2	 
		WHERE 	CallHistoryId 			= p_ParentCallHistoryId;
        
        SET v_errCode 	= 0
        ,	v_errMsg	= 'Updated CallBackCallHistoryId Successfully';
     ELSE
		SET v_errCode 	= -1
        ,	v_errMsg	= 'Update CallBackCallHistoryId failed';
     END IF;
     
     SELECT v_errCode as errCode, v_errMsg as errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
