CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateCallBackChatHistoryId`(	
	p_ParentChatHistoryId		bigint,
	p_ChatBacksessionId		varchar(250)
)
BEGIN
	DECLARE v_ChatHistoryId		BIGINT;
    DECLARE v_errCode 			TINYINT;
    DECLARE v_errMsg 			VARCHAR(250);
    
    SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
    SELECT 	CallHistoryId INTO v_ChatHistoryId
    FROM 	tb_CallHistory
    WHERE 	sessionId	= p_ChatBacksessionId;
    SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    IF v_ChatHistoryId IS NOT NULL
    THEN
		UPDATE 	tb_ChatHistory
		SET 	CallBackChatHistoryId 	= v_ChatHistoryId
			,	CallBackStatus			= 0	 
		WHERE 	ChatHistoryId 			= p_ParentChatHistoryId;

        SET v_errCode 	= 0
        ,	v_errMsg	= 'Updated CallBackChatHistoryId Successfully';
     ELSE
		SET v_errCode 	= -1
        ,	v_errMsg	= 'Update CallBackChatHistoryId failed';
     END IF;
     
     SELECT v_errCode as errCode, v_errMsg as errMsg;
END ;;
DELIMITER ;
