CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateChatSessionCount`(	
       	 p_domainId		INT
       	,p_planId		INT
       	,p_isBot		TINYINT  
       	,p_isAgent		TINYINT
       	,p_IPAdress		VARCHAR(250)
        )
SP_RETURN: BEGIN		
     	DECLARE v_isBot			TINYINT; 
     	DECLARE v_CurDate		DATE DEFAULT CURDATE();
     	DECLARE v_CurDateTime	DATETIME DEFAULT NOW();	
        
           
		
   
		if p_IPAdress in ('182.66.104.114','14.97.124.22') then
			insert into chat_session_check_log(domainId,IPAdress,isBot,isAgent) 
			values(p_domainId,p_IPAdress,p_isBot,p_isAgent);
			leave SP_RETURN;
        End if;
     
         IF p_isBot = 1  
         THEN
     		UPDATE 	tb_CurrentPlan
     		SET 	chatRemainingSessionBot 	= case when chatRemainingSessionBot = 0 then 0 else chatRemainingSessionBot - 1  end 
     			,	updatedDate					= v_CurDateTime
               ,	TotalSessionUsed			= ifnull(TotalSessionUsed,0) + 1
     		WHERE 	domainId = p_domainId
     		AND 	chatRemainingSessionBot > 0;
     	ELSEIF p_isBot = 0
         THEN
     		UPDATE 	tb_CurrentPlan
     		SET 	chatRemainingSessionAgent 	= case when chatRemainingSessionAgent = 0 then 0 else chatRemainingSessionAgent - 1 end					
     			,	updatedDate					= v_CurDateTime
               ,	TotalSessionUsed			= ifnull(TotalSessionUsed,0) + 1
     		WHERE 	domainId = p_domainId
     		AND 	chatRemainingSessionAgent > 0;
         END IF;
       END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
