CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateCustomerName`(
   p_firstName		VARCHAR(100)	
   ,p_lastName		VARCHAR(100)
   ,p_phoneNumber	VARCHAR(20)
   ,p_domainId		INT
   )
Logic_Block:BEGIN
   	DECLARE v_coid				INT;
 	DECLARE v_Curdate			DATETIME DEFAULT NOW();    
	DECLARE v_errCode			SMALLINT DEFAULT -1;	
    DECLARE v_errMsg			VARCHAR(200) DEFAULT 'No contact found' ;	
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 	SELECT 	coid INTO v_coid
 	FROM 	customer_contact CC
 	WHERE 	CC.domainId 			= p_domainId
    
 	AND 	(CC.primaryPhoneNumber 	= p_phoneNumber OR facebook = p_phoneNumber OR instagram = p_phoneNumber)
 	LIMIT 1;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
     
 	IF v_coid IS NOT NULL
 	THEN
		UPDATE 	customer_contact
        SET 	firstName 	= IFNULL(p_firstName,firstName)
			,	lastName	= IFNULL(p_lastName,lastName)
            ,	updatedAt	= v_Curdate
        WHERE 	coid = v_coid;
        
        SET v_errCode 	= 0
		,	v_errMsg	= 'Contact Name updated successfully';	
 	END IF;	
    
    SELECT v_coid AS coid, v_errCode AS errCode, v_errMsg AS errMsg;

   END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
