CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateEmailHistoryDisposition`(	
		p_EmailHistoryId			BIGINT
		,p_DomainId					INT
		,p_DispositionId			INT
		,p_Summary					TEXT
		,p_IsSessionClosed			TINYINT
		,p_AfterEmailWorkTime	    INT
		,p_dispositionUpdatedBy		BIGINT
		,p_Duration                	BIGINT
        ,p_dispositionSubject 		VARCHAR(250)
        ,p_tags						JSON
       )
BEGIN
		DECLARE v_Curdate				DATETIME;
		DECLARE v_EmailHistoryId		BIGINT;
		DECLARE v_CurUnixTimestamp		BIGINT;
		DECLARE v_DispositionId			INT;
		DECLARE v_Summary				TEXT;
		DECLARE v_IsSessionClosed		TINYINT;
		DECLARE v_AfterEmailWorkTime	INT;
		DECLARE v_SessionId				TEXT;
          
		SET v_EmailHistoryId 	= p_EmailHistoryId; 
		SET v_DispositionId		= p_DispositionId;
		SET v_Summary			= p_Summary;
		SET v_IsSessionClosed	= p_IsSessionClosed;
		SET v_AfterEmailWorkTime= p_AfterEmailWorkTime;
          
          SET v_Curdate = NOW();
          
          SELECT SessionId INTO v_SessionId FROM tb_EmailHistory WHERE EmailHistoryId = p_EmailHistoryId;
           
          IF p_IsSessionClosed = 1 
      	THEN
      		SET v_CurUnixTimestamp = UNIX_TIMESTAMP(NOW(3)) * 1000;
      	END IF;	
       
       	UPDATE 	tb_EmailHistory EH
           SET 	EH.Summary				= IFNULL(v_Summary,EH.Summary)
			,	EH.DispositionId		= IFNULL(v_DispositionId,EH.DispositionId)
			,	EH.IsSessionClosed		= IFNULL(v_IsSessionClosed,EH.IsSessionClosed)
			,	EH.AfterEmailWorkTime 	= IFNULL(v_AfterEmailWorkTime,EH.AfterEmailWorkTime)
			,	EH.dispositionUpdatedBy = IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
			,	EH.UpdatedAt			= v_Curdate
			,	EH.SessionEndTime 		= v_CurUnixTimestamp
			,   EH.repliedDate          = v_Curdate
            ,	EH.dispositionSubject	= p_dispositionSubject
            ,	EH.tags					= IFNULL(p_tags,tags)
           WHERE	EmailHistoryId 			= v_EmailHistoryId;
           
  		UPDATE 	tb_EmailDurationHistory   
  		SET 	AgentId			= IFNULL(p_dispositionUpdatedBy,AgentId)
  			, 	Duration        = IFNULL(p_Duration,Duration)
  		WHERE	EmailHistoryId 	= v_EmailHistoryId;
          
          IF v_DispositionId IS NOT NULL
  		THEN			
  			UPDATE 	tb_internalChatGroup 
 			SET 	isClosed		= 1
 				,	updatedAt		= v_CurDate
 			WHERE	historyId 		= v_EmailHistoryId
 			AND 	hostAgent		= p_dispositionUpdatedBy
 			AND 	channelTypeId	= 2003003	
 			AND 	isClosed		= 0; 
  		END IF;
           
  		SELECT  0 AS errcode, 'Email Disposition updated successfully' AS errmsg,v_SessionId as sessionId;   
     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_UpdateEmailSentForSessions` */;
