CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateEmailSentForSessions`(
p_domainId int,
p_IsEmailSent int
)
Begin
	declare v_errcode int; declare v_errmsg varchar(50);
    
    update tb_CurrentPlan set IsEmailSent = p_IsEmailSent where domainId = p_domainId; 
    update tb_PlanRecharge set is_reminder = p_IsEmailSent where domainId = p_domainId; 
    
    if row_count()>0 then
		set v_errcode = 0;
        set v_errmsg = 'Email updated';
    End if;
    
    select v_errcode as errcode, v_errmsg as errmsg;	
End ;;
