CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateFacebookQueueidBasedOnDomainId`(
p_FacebookHistoryId bigint,
p_queueId int
)
Begin
	declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'Failure';
    declare v_FacebookHistoryId bigint;
    
    select FacebookHistoryId into v_FacebookHistoryId from tb_FacebookHistory where FacebookHistoryId = p_FacebookHistoryId limit 1;
    
    if v_FacebookHistoryId is not null then
		update tb_FacebookHistory 
        set queueId = ifnull(p_queueId,queueId)
        where FacebookHistoryId = v_FacebookHistoryId;
        
        if row_count()>0  then
			set v_errcode = 0;
            set v_errmsg = 'Success : Queue updated';
        End if;
        
    End if;
    
    select v_errcode as errcode, v_errmsg as errmsg;
End ;;
DELIMITER ;
