CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateInstagramHistory`(
	  p_InstagramHistoryId 	BIGINT            
	  ,p_AgentId 			BIGINT
	  ,p_domainId			INT
	  ,p_IsBot 				TINYINT
	  ,p_BotId 				INT
	  ,p_AgentStartTime 	BIGINT
	  ,p_AgentEndTime 		BIGINT
	  ,p_Duration 			BIGINT
	  ,p_dialDuration		TINYINT
  )
BEGIN 
  	DECLARE v_errCode				    	INT	DEFAULT -1;
  	DECLARE v_errMsg				    	VARCHAR(150) DEFAULT 'Update Facebook failed';
  	DECLARE v_AgentStartTime              	BIGINT;
  	DECLARE v_AgentEndTime                	BIGINT;	
  	DECLARE	v_CurDate				    	DATETIME DEFAULT NOW();
      
  	IF IFNULL(p_AgentStartTime,0)	= 0 THEN SET v_AgentStartTime = unix_timestamp(DATE_SUB(now(), INTERVAL +1 DAY))*1000; ELSE SET v_AgentStartTime = p_AgentStartTime;  END IF; 	
  	
  	UPDATE 	tb_InstagramHistory
	SET 	AgentId 		= p_AgentId 
		, 	assignedTo		= p_AgentId 
		,   IsBot 			= p_IsBot 			
		,   BotId 			= p_BotId 			
		,   AgentStartTime 	= p_AgentStartTime 	
		,   AgentEndTime 	= p_AgentEndTime 	
		,   Duration 		= p_Duration 		
        ,	dialDuration	= p_dialDuration
		,	updatedAt		= v_CurDate
	WHERE 	InstagramHistoryId 	= p_InstagramHistoryId
	AND 	domainId			= p_domainId;
      
	SELECT v_errCode AS errCode, v_errMsg AS errMsg;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
