CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateInstagramHistoryDisposition`(	
      	p_InstagramHistoryId		BIGINT
      	,p_DomainId					INT
      	,p_DispositionId			INT
      	,p_Summary					TEXT
      	,p_IsSessionClosed			TINYINT
      	,p_afterInstagramWorkTime	INT
      	,p_dispositionUpdatedBy		BIGINT
		,p_Duration                	BIGINT
        ,p_dispositionSubject 		VARCHAR(250)
        ,p_tags						JSON
       )
BEGIN
      	DECLARE v_Curdate			DATETIME;
        DECLARE v_Istransferred		INT;
       	
          SET v_Curdate = NOW();
      	
       	UPDATE 	tb_InstagramHistory EH
    	SET 	EH.Summary					= IFNULL(p_Summary,EH.Summary)
    	   ,	EH.DispositionId			= IFNULL(p_DispositionId,EH.DispositionId)
    	   ,	EH.IsSessionClosed			= IFNULL(p_IsSessionClosed,EH.IsSessionClosed)
    	   ,	EH.afterInstagramWorkTime	= IFNULL(p_afterInstagramWorkTime,EH.afterInstagramWorkTime)
    	   ,	EH.dispositionUpdatedBy 	= IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
    	   ,	EH.UpdatedAt				= v_Curdate
           ,	EH.repliedDate				= v_Curdate
    	   ,	EH.sessionEndTime 			= CASE WHEN p_IsSessionClosed = 1 THEN UNIX_TIMESTAMP(v_Curdate) * 1000 ELSE p_IsSessionClosed END 
		   ,	EH.isCallback				= CASE WHEN EH.isCallback = 1 THEN 0 ELSE EH.isCallback END
           ,	EH.Duration					= IFNULL(p_Duration,EH.Duration)
           ,	EH.AgentId             		= IFNULL(p_dispositionUpdatedBy,AgentId)
           ,	EH.dispositionSubject		= p_dispositionSubject
           ,	EH.tags						= IFNULL(p_tags,EH.tags)
    	WHERE	InstagramHistoryId 			= p_InstagramHistoryId;
 
 	IF IFNULL(p_DispositionId,0) <> 0
     THEN
 	   
 	   CALL up_ccaasUpdateInternalChatGroupStatus(p_InstagramHistoryId,p_DomainId,2003007 );
 	END IF;
        
		SELECT Istransferred INTO v_Istransferred 
		FROM tb_InstagramHistory where InstagramHistoryId = p_InstagramHistoryId;
           
    	SELECT  0 AS errcode, 'Instagram Disposition updated successfully' AS errmsg,IFNULL(v_Istransferred,0) as Istransferred;   
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
