CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateInstagramQueueidBasedOnDomainId`(
 p_InstagramHistoryId bigint,
 p_queueId int
 )
Begin
 	declare v_errcode int default -1;
     declare v_errmsg varchar(50) default 'Failure';
     declare v_InstagramHistoryId bigint;
     
     select InstagramHistoryId into v_InstagramHistoryId from tb_InstagramHistory where InstagramHistoryId = p_InstagramHistoryId limit 1;
     
     if v_InstagramHistoryId is not null then
 		update tb_InstagramHistory 
         set queueId = ifnull(p_queueId,queueId)
         where InstagramHistoryId = v_InstagramHistoryId;
         
         if row_count()>0  then
 			set v_errcode = 0;
             set v_errmsg = 'Success : Queue updated';
         End if;
         
     End if;
     
     select v_errcode as errcode, v_errmsg as errmsg;
 End ;;
