CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateIsAgentLimit`(    
     p_domainId INT,
     p_isAgent  TINYINT,
     p_isAllAgent TINYINT,
     p_isRoutingProfile TINYINT
 )
BEGIN
     DECLARE v_errcode INT DEFAULT -1;
     DECLARE v_errmsg VARCHAR(100) DEFAULT 'Failure';
     DECLARE v_CurDate DATETIME;
 
     SET v_CurDate = NOW();
     
     UPDATE tb_ConcurrentAgentLimit
     SET isAgent = p_isAgent,
         isAllAgent = p_isAllAgent,
         isRoutingProfile =p_isRoutingProfile,
         updatedAt = v_CurDate
     WHERE domainId = p_domainId;
 
     IF p_isAllAgent = 0 THEN
         UPDATE tb_ConcurrentAgentLimit
         SET allAgentLimit = 1
         WHERE domainId = p_domainId;
         
         SET v_errcode = 0;
         SET v_errmsg = 'Updated';
     END IF;
 
     SELECT v_errcode AS errcode, v_errmsg AS errmsg;
 END ;;
DELIMITER ;
