CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateReplayViaCallHistoryDisposition`(
	p_DomainId								INT
	,p_sessionId 							VARCHAR(100)
	,p_DispositionId	    				VARCHAR(255)   
	,p_Summary			    				TEXT
	,p_afterCallWorkTime					INT
	,p_dispositionUpdatedBy					BIGINT
	,p_Duration             	 			BIGINT
	

     ,p_calledPersonDetails 				INT
     ,p_subject								TEXT
     ,p_markAsRead							INT
     ,p_agentExtn 							INT
)
BEGIN
		
		DECLARE v_Curdate							DATETIME;	
		DECLARE v_SessionId							TEXT;
        DECLARE v_ErrorCode							TINYINT DEFAULT 0;
        DECLARE v_ErrorMessage						VARCHAR(255) DEFAULT "Failed";
        DECLARE v_checkDes							TINYINT DEFAULT 0;
        DECLARE v_getDesId							INT;
		DECLARE v_defaultDispositionName 			VARCHAR(100) DEFAULT "Auto Triggered";
        DECLARE v_searchDispositionName				TINYINT DEFAULT 0;
        DECLARE v_checkDefaultColumn				TINYINT DEFAULT 0;
        DECLARE v_temp_count_01						TINYINT DEFAULT 0;
        
        DECLARE v_CallHistoryId						BIGINT;
        DECLARE v_CallDurationHistoryId				BIGINT;
	 	DECLARE v_UserID							BIGINT;
		
        SET v_Curdate = NOW();
        
       
        
        
        
        
		IF p_DispositionId IS NOT NULL THEN 
			SELECT 1 INTO v_checkDes FROM disposition_status WHERE dispositionName = p_DispositionId AND domainId = p_DomainId;
		ELSEIF p_DispositionId IS NULL THEN 
			SELECT 1 INTO v_checkDes FROM disposition_status WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
		END IF;
        
        
        
        
          IF v_checkDes = 1 THEN
			
            SELECT did INTO v_getDesId FROM disposition_status 
					WHERE dispositionName = IFNULL(p_DispositionId, v_defaultDispositionName) AND domainId = p_DomainId;  
			
            
		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 				SELECT UserID INTO v_UserID FROM tb_User 
 					WHERE ext = p_agentExtn AND domainId = p_domainId limit 1;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
        
        
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
				SELECT 	CallHistoryId	INTO v_CallHistoryId
					FROM 	tb_CallHistory a 
					WHERE 	domainId 	= p_domainId AND 	sessionId 	= p_sessionId;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
            
			IF v_CallHistoryId IS NOT NULL THEN  		
				
                UPDATE tb_CallHistory SET 
					CustomerId 		= p_calledPersonDetails
				WHERE CallHistoryId 	= v_CallHistoryId;  	
            
            
			IF p_dispositionUpdatedBy IS NOT NULL OR p_dispositionUpdatedBy <> 0 
            then
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
				SELECT 	CallDurationHistoryId INTO v_CallDurationHistoryId
					FROM 	tb_CallDurationHistory
						WHERE 	CallHistoryId 	= v_CallHistoryId 
                        AND 	AgentId = v_UserID
						ORDER BY CallDurationHistoryId DESC LIMIT 1;
                        
                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
                
                  UPDATE tb_CallDurationHistory
						SET 	summary 				= p_summary,
								dispositionId 			= v_getDesId,
								`subject` 				= p_subject,
								afterCallWorkTime 		= p_afterCallWorkTime,
								markAsRead 				= p_markAsRead,
								updatedAt				= NOW()
						WHERE 	CallDurationHistoryId 	= v_CallDurationHistoryId;   
                 
                 	UPDATE 	tb_internalChatGroup
						SET 	isClosed		= 1
						WHERE 	historyId		= v_CallHistoryId
							AND 	domainId		= p_domainId  AND 	channelTypeId	= 2003001 
							AND 	isClosed		= 0  AND 	hostAgent		= v_UserID;
     		END IF;  
					SET v_ErrorCode = 0;
					SET v_ErrorMessage ='Success : Updated'; 
            
            END IF;
       
       ELSEIF v_checkDes = 0 THEN  
       
				SELECT 1 INTO v_checkDefaultColumn FROM disposition_status
					WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
                    
				IF v_checkDefaultColumn = 0 THEN
					INSERT INTO disposition_status (dispositionName, `type`, `description` , `status`, createdAt, domainId)
						VALUES(v_defaultDispositionName, "Default", "Call test", 1, now(), p_DomainId);
                        
				SELECT 1 INTO v_temp_count_01 FROM tb_internalChatGroup 
						WHERE historyId = v_CallHistoryId 
								AND hostAgent= p_dispositionUpdatedBy     
								AND channelTypeId = 2003001 
                                AND domainId = p_DomainId;
                                
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
						SELECT 	CallHistoryId	INTO v_CallHistoryId
						FROM 	tb_CallHistory a 
						WHERE 	domainId 	= p_domainId AND 	sessionId 	= p_sessionId;
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                                
				IF v_temp_count_01 = 0 THEN
					 		INSERT INTO tb_internalChatGroup(domainId, historyId, hostAgent, channelTypeId,  `isClosed`) 
                            VALUES(p_DomainId, v_CallHistoryId, p_dispositionUpdatedBy,  2003001, 0);
				END IF;
                
                 SELECT did INTO v_getDesId FROM disposition_status WHERE dispositionName = IFNULL(p_DispositionId, v_defaultDispositionName) AND domainId = p_DomainId;
                 
			 		SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
 						select UserID into v_UserID from tb_User where ext = p_agentExtn and domainId = p_domainId limit 1;
 					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
           
					
                    
                    IF v_CallHistoryId IS NOT NULL THEN  		
							UPDATE tb_CallHistory 
								SET	CustomerId 		= p_calledPersonDetails
					WHERE CallHistoryId 	= v_CallHistoryId;
                    
                    IF p_dispositionUpdatedBy IS NOT NULL OR p_dispositionUpdatedBy <> 0 
					THEN
						SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
							SELECT 	CallDurationHistoryId INTO v_CallDurationHistoryId
							FROM 	tb_CallDurationHistory
							WHERE 	CallHistoryId 	= v_CallHistoryId AND 	AgentId 		= v_UserID
							ORDER BY CallDurationHistoryId DESC LIMIT 1;
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                    
                      UPDATE tb_CallDurationHistory
                 SET 	summary 				= p_summary,
						dispositionId 			= v_getDesId,
						`subject` 				= p_subject,
						afterCallWorkTime 		= p_afterCallWorkTime,
						markAsRead 				= p_markAsRead,
                        updatedAt				= NOW()
				 WHERE 	CallDurationHistoryId 	= v_CallDurationHistoryId;            
  
 				UPDATE 	tb_internalChatGroup
 				SET 	isClosed		= 1
 				WHERE 	historyId		= v_CallHistoryId
 				AND 	domainId		= p_domainId
 				AND 	channelTypeId	= 2003001 
 				AND 	isClosed		= 0
				AND 	hostAgent		= v_UserID;
     		END IF;  
             
       		SET v_ErrorCode=0;
       		SET v_ErrorMessage='Success : Updated'; 
         	
          END IF;  
          	ELSEIF v_checkDefaultColumn = 1 THEN
					SET v_ErrorCode = -1;
					SET v_ErrorMessage = "Default column already inserted / Given Disposition Name is not match...";
            END IF;
		END IF;  
        
        SELECT v_ErrorCode AS "Code", v_ErrorMessage AS "Message";
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_UpdateReplayViaCallHistoryDisposition_test` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateReplayViaCallHistoryDisposition_test`(
	p_DomainId								INT
	,p_sessionId 							VARCHAR(100)
	,p_DispositionId	    				VARCHAR(255)   
	,p_Summary			    				TEXT
	,p_afterCallWorkTime					INT
	,p_dispositionUpdatedBy					BIGINT
	,p_Duration             	 			BIGINT
	,p_replyChannelType						VARCHAR(50) 
	,p_responseHistoryId 					INT 
     ,p_calledPersonDetails 				INT
     ,p_subject								TEXT
     ,p_markAsRead							INT
     ,p_agentExtn 							INT
)
BEGIN
		
		DECLARE v_Curdate							DATETIME;	
		DECLARE v_SessionId							TEXT;
        DECLARE v_ErrorCode							TINYINT DEFAULT 0;
        DECLARE v_ErrorMessage						VARCHAR(255) DEFAULT "Failed";
        DECLARE v_checkDes							TINYINT DEFAULT 0;
        DECLARE v_getDesId							INT;
		DECLARE v_defaultDispositionName 			VARCHAR(100) DEFAULT "Auto Triggered";
        DECLARE v_searchDispositionName				TINYINT DEFAULT 0;
        DECLARE v_checkDefaultColumn				TINYINT DEFAULT 0;
        DECLARE v_temp_count_01						TINYINT DEFAULT 0;
        
        DECLARE v_CallHistoryId						BIGINT;
        DECLARE v_CallDurationHistoryId				BIGINT;
	
		
        SET v_Curdate = NOW();
        
       
        
        
        
        
		IF p_DispositionId IS NOT NULL THEN 
			SELECT 1 INTO v_checkDes FROM disposition_status WHERE dispositionName = p_DispositionId AND domainId = p_DomainId;
		ELSEIF p_DispositionId IS NULL THEN 
			SELECT 1 INTO v_checkDes FROM disposition_status WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
		END IF;
        
        
        
        
          IF v_checkDes = 1 THEN
			
            SELECT did INTO v_getDesId FROM disposition_status 
					WHERE dispositionName = IFNULL(p_DispositionId, v_defaultDispositionName) AND domainId = p_DomainId;  
			
            
		



        
        
            SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
				SELECT 	CallHistoryId	INTO v_CallHistoryId
					FROM 	tb_CallHistory a 
					WHERE 	domainId 	= p_domainId AND 	sessionId 	= p_sessionId;
			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
            
			IF v_CallHistoryId IS NOT NULL THEN  		
				
                UPDATE tb_CallHistory SET 
					CustomerId 		= p_calledPersonDetails
				WHERE CallHistoryId 	= v_CallHistoryId;  	
            
            
			IF p_dispositionUpdatedBy IS NOT NULL OR p_dispositionUpdatedBy <> 0 
            then
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
				SELECT 	CallDurationHistoryId INTO v_CallDurationHistoryId
					FROM 	tb_CallDurationHistory
						WHERE 	CallHistoryId 	= v_CallHistoryId AND 	AgentId = p_dispositionUpdatedBy
						ORDER BY CallDurationHistoryId DESC LIMIT 1;
                        
                SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                
                
                  UPDATE tb_CallDurationHistory
						SET 	summary 				= p_summary,
								dispositionId 			= v_getDesId,
								`subject` 				= p_subject,
								afterCallWorkTime 		= p_afterCallWorkTime,
								markAsRead 				= p_markAsRead,
								updatedAt				= NOW()
						WHERE 	CallDurationHistoryId 	= v_CallDurationHistoryId;   
                 
                 	UPDATE 	tb_internalChatGroup
						SET 	isClosed		= 1
						WHERE 	historyId		= v_CallHistoryId
							AND 	domainId		= p_domainId  AND 	channelTypeId	= 2003001 
							AND 	isClosed		= 0  AND 	hostAgent		= p_dispositionUpdatedBy;
     		END IF;  
					SET v_ErrorCode = 0;
					SET v_ErrorMessage ='Success : Updated'; 
            
            END IF;
       
       ELSEIF v_checkDes = 0 THEN  
       
				SELECT 1 INTO v_checkDefaultColumn FROM disposition_status
					WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
                    
				IF v_checkDefaultColumn = 0 THEN
					INSERT INTO disposition_status (dispositionName, `type`, `description` , `status`, createdAt, domainId)
						VALUES(v_defaultDispositionName, "Default", "Chat test", 1, now(), p_DomainId);
                        
				SELECT 1 INTO v_temp_count_01 FROM tb_internalChatGroup 
						WHERE historyId = v_CallHistoryId 
								AND hostAgent= p_dispositionUpdatedBy     
								AND channelTypeId = 2003001 
                                AND domainId = p_DomainId;
                                
				SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
						SELECT 	CallHistoryId	INTO v_CallHistoryId
						FROM 	tb_CallHistory a 
						WHERE 	domainId 	= p_domainId AND 	sessionId 	= p_sessionId;
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                                
				IF v_temp_count_01 = 0 THEN
					 		INSERT INTO tb_internalChatGroup(domainId, historyId, hostAgent, channelTypeId,  `isClosed`) 
                            VALUES(p_DomainId, v_CallHistoryId, p_dispositionUpdatedBy,  2003001, 0);
				END IF;
                
                 SELECT did INTO v_getDesId FROM disposition_status WHERE dispositionName = IFNULL(p_DispositionId, v_defaultDispositionName) AND domainId = p_DomainId;
                 
			


           
					
                    
                    IF v_CallHistoryId IS NOT NULL THEN  		
							UPDATE tb_CallHistory 
								SET	CustomerId 		= p_calledPersonDetails
					WHERE CallHistoryId 	= v_CallHistoryId;
                    
                    IF p_dispositionUpdatedBy IS NOT NULL OR p_dispositionUpdatedBy <> 0 
					THEN
						SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
							SELECT 	CallDurationHistoryId INTO v_CallDurationHistoryId
							FROM 	tb_CallDurationHistory
							WHERE 	CallHistoryId 	= v_CallHistoryId AND 	AgentId 		= p_dispositionUpdatedBy
							ORDER BY CallDurationHistoryId DESC LIMIT 1;
					SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
                    
                      UPDATE tb_CallDurationHistory
                 SET 	summary 				= p_summary,
						dispositionId 			= v_getDesId,
						`subject` 				= p_subject,
						afterCallWorkTime 		= p_afterCallWorkTime,
						markAsRead 				= p_markAsRead,
                        updatedAt				= NOW()
				 WHERE 	CallDurationHistoryId 	= v_CallDurationHistoryId;            
  
 				UPDATE 	tb_internalChatGroup
 				SET 	isClosed		= 1
 				WHERE 	historyId		= v_CallHistoryId
 				AND 	domainId		= p_domainId
 				AND 	channelTypeId	= 2003001 
 				AND 	isClosed		= 0
				AND 	hostAgent		= p_dispositionUpdatedBy;
     		END IF;  
             
       		SET v_ErrorCode=0;
       		SET v_ErrorMessage='Success : Updated'; 
         	
          END IF;  
          	ELSEIF v_checkDefaultColumn = 1 THEN
					SET v_ErrorCode = -1;
					SET v_ErrorMessage = "Default column already inserted / Given Disposition Name is not match...";
            END IF;
		END IF;  
        
        SELECT v_ErrorCode AS "Error Code", v_ErrorMessage AS "Error Message";
END ;;
