CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateReplayViaChatHistoryDisposition_test`(
		 p_ChatDurationHistoryId		BIGINT,
         p_domainId 					INT,
         p_summary 						TEXT,
         p_dispositionId 				VARCHAR(100),
         p_afterChatWorkTime 			INT,
         p_markAsRead 					INT,
         p_agentOccupyDetails			JSON,
		p_dispositionUpdatedBy			BIGINT
)
BEGIN
		DECLARE v_findDispositionId	 					INT;
        DECLARE v_defaultDispositionName 				VARCHAR(100) DEFAULT "Auto Triggered";
		DECLARE v_CurDate								DATETIME DEFAULT NOW();
      	DECLARE v_ChatHistoryId							BIGINT;
		DECLARE v_AgentId								INT;
        DECLARE v_sysCode								INT DEFAULT -1;
        DECLARE v_sysMsg								VARCHAR(100) DEFAULT "Failed";
        DECLARE v_checkDefaultColumn					INT DEFAULT 0;
        DECLARE v_checkInternalChatGroup				INT DEFAULT 0;
        DECLARE v_getDesId								INT;
        
        
        IF p_dispositionId IS NOT NULL THEN 
			SELECT did INTO v_findDispositionId FROM disposition_status WHERE  domainId = p_domainId AND dispositionName = p_dispositionId;
        ELSEIF p_dispositionId IS NULL THEN
			SELECT did INTO v_findDispositionId FROM disposition_status WHERE  domainId = p_domainId AND dispositionName = v_defaultDispositionName;
        END IF;
        
        
     
        
	
        IF v_findDispositionId IS NOT NULL THEN 
				
                SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
					SELECT 	ChatHistoryId, AgentId	
						INTO 	v_ChatHistoryId, v_AgentId
						FROM 	tb_ChatDurationHistory
						WHERE 	ChatDurationHistoryId = p_ChatDurationHistoryId
						LIMIT 1;  
				SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ; 
                
				IF EXISTS (	SELECT 	1 FROM 	tb_ChatHistory WHERE 	ChatHistoryId 	= v_ChatHistoryId AND 	CallBackStatus	= 1) THEN
					UPDATE 	tb_ChatHistory
						SET 	CallBackStatus	= 0
						WHERE 	ChatHistoryId 	= v_ChatHistoryId;		
				END IF;
                
                UPDATE tb_ChatDurationHistory
					SET  dispositionId 			= IFNULL(p_dispositionId ,dispositionId)
						,Summary 			    = IFNULL(p_summary,Summary)
						,afterChatWorkTime 		= IFNULL(p_afterChatWorkTime,afterChatWorkTime)
						,markAsRead 			= IFNULL(p_markAsRead,markAsRead)
						,updatedAt				= v_CurDate
					WHERE ChatDurationHistoryId = p_ChatDurationHistoryId;
                    
				UPDATE 	tb_ConcurrentAgentLimit
					SET 	agentOccupyDetails	= p_agentOccupyDetails
				WHERE 	domainId			= p_domainId;
          		
				UPDATE 	tb_internalChatGroup 
					SET 	isClosed		= 1
						,	updatedAt		= v_CurDate
				WHERE	historyId	 	= v_ChatHistoryId
					AND 	hostAgent		= v_AgentId
					AND 	channelTypeId	= 2003002	
					AND 	isClosed		= 0;  

				SET v_sysCode = 1;
                SET v_sysMsg = "Updated Successfully...";
          
          
		ELSEIF v_findDispositionId IS NULL THEN
			
            SELECT 1 INTO v_checkDefaultColumn FROM disposition_status 
					WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
             
             
			IF v_checkDefaultColumn = 0 THEN
					INSERT INTO disposition_status (dispositionName, `type`, `description` , `status`, createdAt, domainId)
						VALUES(v_defaultDispositionName, "Default", "Chat test", 1, now(), p_domainId);
				
                SELECT 	ChatHistoryId, AgentId	INTO 	v_ChatHistoryId, v_AgentId FROM 	tb_ChatDurationHistory
						WHERE 	ChatDurationHistoryId = p_ChatDurationHistoryId
						LIMIT 1;  
                
                SELECT 1 INTO v_checkInternalChatGroup FROM disposition_status 
					WHERE historyId = v_ChatHistoryId 
								AND hostAgent= p_dispositionUpdatedBy 
								AND channelTypeId = 2003002 
                                AND domainId = p_domainId;
                
                 
				IF v_checkInternalChatGroup = 0 THEN
					 		INSERT INTO tb_internalChatGroup(domainId, historyId, hostAgent, channelTypeId,  `isClosed`) 
                            VALUES(p_domainId, v_ChatHistoryId, v_AgentId,  2003002, 0);
				END IF;
                
                
                SELECT did INTO v_getDesId FROM disposition_status WHERE dispositionName = IFNULL(p_dispositionId, v_defaultDispositionName) AND domainId = p_DomainId;
				
                
				IF EXISTS (	SELECT 	1 FROM 	tb_ChatHistory WHERE 	ChatHistoryId 	= v_ChatHistoryId AND 	CallBackStatus	= 1) THEN
							
                            UPDATE 	tb_ChatHistory SET 	CallBackStatus	= 0	WHERE 	ChatHistoryId 	= v_ChatHistoryId;		
				END IF;
                
                
                UPDATE tb_ChatDurationHistory
					SET  dispositionId 			= IFNULL(p_dispositionId ,dispositionId)
						,Summary 			    = IFNULL(p_summary,Summary)
						,afterChatWorkTime 		= IFNULL(p_afterChatWorkTime,afterChatWorkTime)
						,markAsRead 			= IFNULL(p_markAsRead,markAsRead)
						,updatedAt				= v_CurDate
				WHERE ChatDurationHistoryId = p_ChatDurationHistoryId;  
                
                UPDATE 	tb_ConcurrentAgentLimit SET 	agentOccupyDetails	= p_agentOccupyDetails WHERE 	domainId			= p_domainId;
          
				IF p_dispositionId IS NOT NULL THEN			
						UPDATE 	tb_internalChatGroup 
							SET 	isClosed		= 1
								,	updatedAt		= v_CurDate
						WHERE	historyId	 	= v_ChatHistoryId
							AND 	hostAgent		= v_AgentId
							AND 	channelTypeId	= 2003002	
							AND 	isClosed		= 0;  
				 END IF;
                 
                 IF ROW_COUNT() > 0 THEN
						SET v_sysCode=0;
						SET v_sysMsg='Updated Successfully';  		
				END IF;
			
            ELSEIF v_checkDefaultColumn = 1 THEN
					SET v_sysCode = -1;
					SET v_sysMsg = "Default column already inserted / Given Disposition Name is not match...";
            
        END IF;
        
        END IF;
	
    
    SELECT  v_sysCode AS "Code", v_sysMsg AS "Message";
END ;;
DELIMITER ;
