CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateReplayViaEmailHistoryDisposition`(
		p_EmailHistoryId			BIGINT
		,p_DomainId					INT
		,p_DispositionId			VARCHAR(30)  
		,p_Summary					TEXT
		,p_IsSessionClosed			TINYINT
		,p_AfterEmailWorkTime	    INT
		,p_dispositionUpdatedBy		BIGINT
		,p_Duration                	BIGINT
		,p_replyChannelType			VARCHAR(50) 
        ,p_responseHistoryId 		INT 
        ,p_coid						INT
)
BEGIN

		DECLARE v_Curdate										DATETIME DEFAULT NOW();
		DECLARE v_EmailHistoryId								BIGINT;
		DECLARE v_CurUnixTimestamp								BIGINT;
	
		DECLARE v_Summary										TEXT;
		DECLARE v_IsSessionClosed								TINYINT;
		DECLARE v_AfterEmailWorkTime							INT;
		DECLARE v_SessionId										TEXT;
        DECLARE v_DispositionName 								VARCHAR(50);
        DECLARE v_spot_dname									TINYINT DEFAULT 0;
        DECLARE v_default_disposition_Name  					VARCHAR(100);
        DECLARE Error_code										TINYINT DEFAULT 0;
        DECLARE Error_msg										VARCHAR(100) DEFAULT "Failed";
        DECLARE v_getDispositionId								INT;	
		DECLARE v_temp_count 									TINYINT DEFAULT 0;
        DECLARE v_temp_count_01  								TINYINT DEFAULT 0;
        DECLARE	v_searchDefaultColumn							TINYINT DEFAULT 0;
     
		SET v_EmailHistoryId 		=	p_EmailHistoryId; 
		SET v_DispositionName		= 	p_DispositionId;
		SET v_Summary				= 	p_Summary;
		SET v_IsSessionClosed		= 	p_IsSessionClosed;
		SET v_AfterEmailWorkTime	= 	p_AfterEmailWorkTime;
       
        
        SET v_default_disposition_Name = "Auto Triggered";
        
        SET v_Curdate = NOW();
        
        
        SET v_SessionId = (SELECT t1.SessionId FROM tb_EmailHistory AS t1 WHERE EmailHistoryId = p_EmailHistoryId);
        
        
		IF p_IsSessionClosed = 1 
			THEN
				SET v_CurUnixTimestamp = UNIX_TIMESTAMP(NOW(3)) * 1000;
      	END IF;
        
        IF p_DispositionId IS NOT NULL THEN
			SELECT 1 INTO v_spot_dname FROM disposition_status WHERE dispositionName IN (p_DispositionId) AND domainId = p_DomainId;
        END IF;
        
		IF p_DispositionId IS NULL THEN
			SELECT 1 INTO v_spot_dname FROM disposition_status WHERE dispositionName IN (v_default_disposition_Name) AND domainId = p_DomainId;
        END IF;
        
        IF v_spot_dname = 1 
			THEN 
				SELECT did INTO v_getDispositionId FROM disposition_status 
				WHERE dispositionName = IFNULL(p_DispositionId, v_default_disposition_Name)  
				AND domainId = p_DomainId;
         
         
           UPDATE 	tb_EmailHistory EH
				SET 	EH.Summary				= IFNULL(v_Summary,EH.Summary)
					,	EH.DispositionId		= IFNULL(v_getDispositionId,EH.DispositionId)
					,	EH.IsSessionClosed		= IFNULL(v_IsSessionClosed,EH.IsSessionClosed)
					,	EH.AfterEmailWorkTime 	= IFNULL(v_AfterEmailWorkTime,EH.AfterEmailWorkTime)
					,	EH.dispositionUpdatedBy = IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
                    
                    ,   EH.AssignedTo			= IFNULL(p_dispositionUpdatedBy, EH.AssignedTo)
					, 	EH.replyChannelType		= IFNULL(p_replyChannelType, EH.replyChannelType)
                    , 	EH.responseHistoryId 	= IFNULL(p_responseHistoryId, EH.responseHistoryId)
                    , 	EH.CustomerId 			= IFNULL(p_coid, EH.CustomerId)
                    
					,	EH.UpdatedAt			= v_Curdate
					,	EH.SessionEndTime 		= v_CurUnixTimestamp
					,  	EH.repliedDate          = v_Curdate
				WHERE	EmailHistoryId 			= v_EmailHistoryId;
        
			UPDATE 	tb_EmailDurationHistory   
				SET 	AgentId			= IFNULL(p_dispositionUpdatedBy,AgentId)
					, 	Duration        = IFNULL(p_Duration,Duration)
				WHERE	EmailHistoryId 	= v_EmailHistoryId;
                
			
  			IF v_getDispositionId IS NOT NULL 
				THEN			
					UPDATE 	tb_internalChatGroup 
						SET 	isClosed		= 1
							,	updatedAt		= v_CurDate
						WHERE	historyId 		= v_EmailHistoryId 
							AND 	hostAgent		= p_dispositionUpdatedBy
							AND     domainId		= p_DomainId
							AND 	channelTypeId	= 2003003	
							AND 	isClosed		= 0; 
            
			END IF;
                
			SET Error_code = 1;
			SET Error_msg = "Updated Successfully";
		END IF;
        
		IF v_spot_dname = 0
			THEN
				SELECT 1 INTO v_searchDefaultColumn 
                FROM disposition_status 
                WHERE dispositionName = v_default_disposition_Name
					AND domainId =  domainId;
                 
			IF v_searchDefaultColumn = 0 THEN 
            
				INSERT INTO disposition_status (dispositionName, `type`, `description` , `status`, colorCode,   createdAt, domainId)
				VALUES(v_default_disposition_Name, "Default", "Indicates that the customer received an SMS or email notification during an active call.", 
						1, "#804680",  now(), domainId);
            
				SELECT 1 INTO v_temp_count_01 FROM tb_internalChatGroup WHERE historyId = v_EmailHistoryId AND hostAgent= p_dispositionUpdatedBy
				AND channelTypeId = 2003003 AND domainId = p_DomainId;
            
				IF v_temp_count_01 = 0 THEN
					INSERT INTO tb_internalChatGroup(domainId, historyId, hostAgent, channelTypeId,  `isClosed`) 
						VALUES(p_DomainId, v_EmailHistoryId, p_dispositionUpdatedBy,  2003003, 0);
				END IF;
            
					SELECT did INTO v_getDispositionId FROM disposition_status 
                    WHERE dispositionName = v_default_disposition_Name AND domainId = p_DomainId;
         
					UPDATE 	tb_EmailHistory EH
					SET 	EH.Summary				= IFNULL(v_Summary,EH.Summary)
					,	EH.DispositionId			= IFNULL(v_getDispositionId,EH.DispositionId)
					,	EH.IsSessionClosed			= IFNULL(v_IsSessionClosed,EH.IsSessionClosed)
					,	EH.AfterEmailWorkTime 		= IFNULL(v_AfterEmailWorkTime,EH.AfterEmailWorkTime)
					,	EH.dispositionUpdatedBy 	= IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
                    
                    ,   EH.AssignedTo			= IFNULL(p_dispositionUpdatedBy, EH.AssignedTo)
					, 	EH.replyChannelType	= IFNULL(p_replyChannelType, EH.replyChannelType)
                    , 	EH.responseHistoryId = IFNULL(p_responseHistoryId, EH.responseHistoryId)
                    , 	EH.CustomerId = IFNULL(p_coid, EH.CustomerId)
                    
					,	EH.UpdatedAt				= v_Curdate
					,	EH.SessionEndTime 			= v_CurUnixTimestamp
					,  	EH.repliedDate          	= v_Curdate
						WHERE	EmailHistoryId 			= v_EmailHistoryId;
        
					UPDATE 	tb_EmailDurationHistory   
					SET 	AgentId			= IFNULL(p_dispositionUpdatedBy,AgentId)
						, 	Duration        = IFNULL(p_Duration,Duration)
						WHERE	EmailHistoryId 	= v_EmailHistoryId;
                        
							
					IF v_getDispositionId IS NOT NULL
						THEN			
							UPDATE 	tb_internalChatGroup 
								SET 	isClosed		= 1
									,	updatedAt		= v_CurDate
								WHERE	historyId 		= v_EmailHistoryId
								AND 	hostAgent		= p_dispositionUpdatedBy
								AND 	channelTypeId	= 2003003	
                                AND     domainId		= p_DomainId
								AND 	isClosed		= 0; 
					END IF;
                        
                        SET Error_code = 1;
						SET Error_msg = "Updated Successfully";

				ELSEIF v_searchDefaultColumn = 1 THEN
                
						SET Error_code = -1;
						SET Error_msg = "Given DispositionName incorrect / Default column already available";
				 END IF;
			END IF;
        
        SELECT Error_code , Error_msg;

END ;;
DELIMITER ;
