CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateReplayViaVideoHistoryDisposition_test`(
			p_domainId 					INT
            ,p_meetingId 				TEXT
            ,p_summary 					TEXT
            ,p_dispositionId 			VARCHAR(100)
            ,p_afterVideoWorkTime 		INT
            ,p_subject 					TEXT
            ,p_agentExtn 				INT
            
    
	
            ,p_dispositionUpdatedBy				BIGINT
)
BEGIN

		DECLARE v_VideoHistoryId 						INT;   
  		DECLARE v_VideoDurationHistoryId 				INT;  
        DECLARE v_getDid								INT;
        DECLARE v_defaultDispositionName 				VARCHAR(100) DEFAULT "Auto Triggered";
        DECLARE v_errCode								INT DEFAULT 0;
        DECLARE v_errMsg								VARCHAR(100) DEFAULT "Failed";
		DECLARE v_checkDefaultColumn					TINYINT DEFAULT 0;
        DECLARE v_temp_count_01							INT DEFAULT 0;
        
        
        IF p_dispositionId IS NOT NULL THEN
			SELECT did INTO v_getDid FROM disposition_status WHERE domainId = p_domainId AND  dispositionName = p_dispositionId;
		ELSEIF p_dispositionId IS NULL THEN
			SELECT did INTO v_getDid FROM disposition_status WHERE domainId = p_domainId AND  dispositionName = v_defaultDispositionName;
        END IF;
        
        IF v_getDid is NOT NULL THEN 
					
			WITH RECURSIVE CTE AS( 
				SELECT VideoHistoryId , 
                ROW_NUMBER() OVER (PARTITION BY meetingId ORDER BY updatedAt DESC) AS RR
						FROM tb_VideoHistory WHERE 	meetingId = p_meetingId 
                        AND		domainId = p_domainId
					) SELECT VideoHistoryId INTO v_VideoHistoryId FROM CTE WHERE RR =1;
        
	  select VideoDurationHistoryId into v_VideoDurationHistoryId
      from tb_VideoDurationHistory 
	  where videoHistoryId = v_VideoHistoryId 
	  and AgentId = p_agentExtn 
	  order by VideoDurationHistoryId desc 
	  limit 1;
    
        IF EXISTS (SELECT 1 FROM tb_VideoHistory WHERE domainId = p_domainId AND meetingId = p_meetingId limit 1)
    		THEN  
  			UPDATE  tb_VideoDurationHistory VDH
            JOIN 	tb_VideoHistory VH ON VDH.VideoHistoryId = VH.VideoHistoryId
  			set VDH.summary 			= ifnull(p_summary,VDH.summary),
				VDH.dispositionId 		= ifnull(v_getDid, VDH.dispositionId),
				VDH.afterVideoWorkTime 	= ifnull(p_afterVideoWorkTime,VDH.afterVideoWorkTime),
				VDH.`subject` 			= ifnull(p_subject,VDH.`subject`),
				VDH.updatedAt 			= now()
  			where meetingId 			= p_meetingId 
  			and VDH.AgentId 			= p_agentExtn
            and VDH.VideoDurationHistoryId = v_VideoDurationHistoryId;
		End if;
          
          	SET v_errCode=0;
  			SET v_errMsg='Success : Updated'; 
        
        END IF;
        
         IF v_getDid is NULL THEN 
				
                SELECT  1 INTO v_checkDefaultColumn FROM disposition_status WHERE domainId = p_domainId AND dispositionName = v_defaultDispositionName;
                
                IF v_checkDefaultColumn = 0 THEN
						INSERT INTO disposition_status (dispositionName, `type`, `description` , `status`, createdAt, domainId)
								VALUES(v_defaultDispositionName, "Default", "Video test", 1, now(), p_DomainId);
                    
                            WITH RECURSIVE CTE AS(
									SELECT VideoHistoryId , ROW_NUMBER() OVER (PARTITION BY meetingId ORDER BY updatedAt DESC) AS RR
												FROM tb_VideoHistory 
												WHERE 	meetingId = p_meetingId  AND		domainId = p_domainId
									) SELECT VideoHistoryId INTO v_VideoHistoryId FROM CTE WHERE RR =1;
        
						SELECT VideoDurationHistoryId INTO v_VideoDurationHistoryId
								FROM tb_VideoDurationHistory 
								WHERE videoHistoryId = v_VideoHistoryId AND AgentId = p_agentExtn 
											ORDER BY VideoDurationHistoryId DESC 
												LIMIT 1;
                    
                    SELECT 1 INTO v_temp_count_01 FROM tb_internalChatGroup 
						WHERE historyId = v_VideoHistoryId 
								AND hostAgent= p_dispositionUpdatedBy 
					 			AND channelTypeId =  2003008
                                AND domainId = p_DomainId;
					
                    
                    IF v_temp_count_01 = 0 THEN
					 		INSERT INTO tb_internalChatGroup(domainId, historyId, hostAgent, channelTypeId,  `isClosed`) 
                            VALUES(p_DomainId, v_VideoHistoryId, p_dispositionUpdatedBy,  2003008, 0);
                            
					END IF;
                    
                    SELECT did INTO v_getDid FROM disposition_status WHERE domainId = p_DomainId AND dispositionName = v_defaultDispositionName;
                    
                    
                         IF EXISTS (SELECT 1 FROM tb_VideoHistory WHERE domainId = p_domainId AND meetingId = p_meetingId limit 1)
							THEN  
							UPDATE  tb_VideoDurationHistory VDH
								JOIN 	tb_VideoHistory VH ON VDH.VideoHistoryId = VH.VideoHistoryId
								SET VDH.summary 			= ifnull(p_summary,VDH.summary),
									VDH.dispositionId 		= IF(p_dispositionId IS NULL OR p_dispositionId = 0, dispositionId,p_dispositionId),
									VDH.afterVideoWorkTime 	= ifnull(p_afterVideoWorkTime,VDH.afterVideoWorkTime),
									VDH.`subject` 			= ifnull(p_subject,VDH.`subject`),
									VDH.updatedAt 			= now()
							WHERE meetingId 			= p_meetingId 
								AND VDH.AgentId 			= p_agentExtn
								AND VDH.VideoDurationHistoryId = v_VideoDurationHistoryId;
							End if;
          
			SET v_errCode = 1;
  			SET v_errMsg ='Updated Successfully'; 
							
                
                ELSEIF v_checkDefaultColumn = 1 THEN
                
						SET v_errCode = -1;
						SET v_errMsg ='Default column already inserted / Given Disposition Name is not match...'; 
                
                END IF;
         END IF;
        
        SELECT v_errCode AS "Code", v_errMsg AS "Message";
END ;;
DELIMITER ;
