	,p_DomainId							INT
	,p_DispositionId	    			VARCHAR(255)   
	,p_Summary			    			TEXT
	,p_IsSessionClosed	    			TINYINT
	,p_afterwhatsappWorkTime			INT
	,p_dispositionUpdatedBy				BIGINT
	,p_Duration             	 		BIGINT
	,p_replyChannelType					VARCHAR(50) 
	,p_responseHistoryId 				INT 
)
BEGIN
	DECLARE v_Curdate							DATETIME;
    DECLARE v_SessionId							TEXT;
    DECLARE v_status_msg						VARCHAR(50);
    DECLARE v_status_code						INT;
    DECLARE v_checkDes							INT;
    DECLARE v_defaultDispositionName 			VARCHAR(100) DEFAULT "Auto Triggered";
	DECLARE v_ErrorCode							TINYINT DEFAULT 0;
	DECLARE v_ErrorMessage						VARCHAR(255) DEFAULT "Failed";
	DECLARE v_checkDefaultColumn				TINYINT DEFAULT 0;
	DECLARE v_temp_count_01						TINYINT DEFAULT 0;
	DECLARE v_getDesId							INT;
    
    SET v_Curdate = NOW();
        
	SELECT sessionId INTO v_SessionId FROM tb_WhatsappHistory 
		WHERE WhatsappHistoryId = p_WhatsappHistoryId;
        
        
	IF p_DispositionId IS NOT NULL THEN 
			SELECT 1 INTO v_checkDes FROM disposition_status 
				WHERE dispositionName = p_DispositionId AND domainId = p_DomainId;
	ELSEIF p_DispositionId IS NULL THEN 
			SELECT 1 INTO v_checkDes FROM disposition_status 
				WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
	END IF;
    
    
	IF v_checkDes = 1 THEN
    
		UPDATE 	tb_WhatsappHistory EH
  		SET 	EH.Summary					= IFNULL(p_Summary,EH.Summary)
  			,	EH.DispositionId			= IFNULL(p_DispositionId,EH.DispositionId)
  			,	EH.IsSessionClosed			= IFNULL(p_IsSessionClosed,EH.IsSessionClosed)
  			,	EH.afterwhatsappWorkTime 	= IFNULL(p_afterwhatsappWorkTime,EH.afterwhatsappWorkTime)
  			,	EH.dispositionUpdatedBy		= IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
  			,	EH.sessionEndTime 			= CASE WHEN p_IsSessionClosed = 1 THEN UNIX_TIMESTAMP(v_Curdate) * 1000 ELSE p_IsSessionClosed END
             ,	EH.isCallback				= CASE WHEN EH.isCallback = 1 THEN 0 ELSE EH.isCallback END
  			,	EH.UpdatedAt				= v_Curdate
  			,	EH.repliedDate				= v_Curdate
  		WHERE	WhatsappHistoryId 			= p_WhatsappHistoryId
         AND		EH.domainId					= p_DomainId;
         
		UPDATE 	tb_WhatsappDurationHistory   
  		SET 	AgentId             = IFNULL(p_dispositionUpdatedBy,AgentId)
  			, 	Duration            = IFNULL(p_Duration,Duration)
  		WHERE	WhatsappHistoryId 	= p_WhatsappHistoryId;
        
        CALL up_ccaasUpdateInternalChatGroupStatus(p_WhatsappHistoryId,p_DomainId,2003005 );
        
		SET v_ErrorCode = 1;
		SET v_ErrorMessage = "Successfully Updated...";
        
	ELSEIF v_checkDes = 0 THEN 
    
			SELECT 1 INTO v_checkDefaultColumn FROM disposition_status
					WHERE dispositionName = v_defaultDispositionName AND domainId = p_DomainId;
                    
       IF v_checkDefaultColumn = 0 THEN             
		INSERT INTO disposition_status (dispositionName, `type`, `description` , `status`, colorCode, createdAt, domainId)
			VALUES(v_defaultDispositionName, "Default", "WATest", 1, "WAtest", now(), p_DomainId);
		
        SELECT 1 INTO v_temp_count_01 FROM tb_internalChatGroup 
			WHERE historyId = p_WhatsappHistoryId AND hostAgent= p_dispositionUpdatedBy AND channelTypeId = 2003005 
								AND domainId = p_DomainId;
                                
		IF v_temp_count_01 = 0 THEN
			INSERT INTO tb_internalChatGroup(domainId, historyId, hostAgent, channelTypeId,  `isClosed`) 
			VALUES(p_DomainId, p_WhatsappHistoryId, p_dispositionUpdatedBy,  2003005, 0);
		END IF;
        
        SET v_getDesId = (SELECT did FROM disposition_status WHERE dispositionName = IFNULL(p_DispositionId, v_defaultDispositionName) AND domainId = p_DomainId);
		
        
        			UPDATE 	tb_WhatsappHistory EH
				SET 	EH.Summary			= IFNULL(p_Summary,EH.Summary)
					,	EH.DispositionId	= IFNULL(v_getDesId, EH.DispositionId)
					,	EH.IsSessionClosed	= IFNULL(p_IsSessionClosed,EH.IsSessionClosed)
					,	EH.afterSMSWorkTime	= IFNULL(p_afterwhatsappWorkTime,EH.afterwhatsappWorkTime)
					,	EH.dispositionUpdatedBy = IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
                    ,	EH.assignedTo			= IFNULL(p_dispositionUpdatedBy,EH.dispositionUpdatedBy)
					, 	EH.replyChannelType	= IFNULL(p_replyChannelType, EH.replyChannelType)
                    , 	EH.responseHistoryId = IFNULL(p_responseHistoryId, EH.responseHistoryId)
					,	EH.UpdatedAt		= v_Curdate
					,	EH.sessionEndTime 	= CASE WHEN p_IsSessionClosed = 1 THEN UNIX_TIMESTAMP(v_Curdate) * 1000 ELSE p_IsSessionClosed END
					, 	EH.repliedDate      = v_Curdate
					,   EH.sessionEndTime 	= IF(EH.sessionEndTime = 1, UNIX_TIMESTAMP(v_Curdate) * 1000, EH.sessionEndTime)
			WHERE	WhatsappHistoryId 		= p_WhatsappHistoryId;
            
            
            	UPDATE 	tb_WhatsappDurationHistory   
  		SET 	AgentId             = IFNULL(p_dispositionUpdatedBy,AgentId)
  			, 	Duration            = IFNULL(p_Duration,Duration)
  		WHERE	WhatsappHistoryId 	= p_WhatsappHistoryId;
        
        
        CALL up_ccaasUpdateInternalChatGroupStatus(p_WhatsappHistoryId,p_DomainId,2003005 );
        
        SET v_ErrorCode = 1;
        SET v_ErrorMessage = "Successfully Updated...";
        
        ELSEIF v_checkDefaultColumn = 1 THEN
					SET v_ErrorCode = -1;
					SET v_ErrorMessage = "Default column already inserted / Given Disposition Name is not match...";
		END IF;
	END IF;
        
    SELECT v_ErrorCode, v_ErrorMessage;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
