CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateSocialMediaCallBacksessionId`(	
	p_HistoryId					INT,
	p_CallBacksessionId			VARCHAR(250),
    p_type						VARCHAR(20)
)
BEGIN
	DECLARE v_WhatsappHistoryId	INT;
    DECLARE v_errCode 			TINYINT DEFAULT -1;
    DECLARE v_errMsg 			VARCHAR(100) DEFAULT 'Update CallBack failed';
    
    IF p_HistoryId IS NOT NULL AND p_type = 'Whatsapp'
    THEN
		UPDATE 	tb_WhatsappHistory
		SET 	CallBackWhatsappHistoryId 	= p_CallBacksessionId
			,	isCallback					= 0	 
            ,	IsSessionClosed 			= 1
		WHERE 	WhatsappHistoryId 			= p_HistoryId;
        
        SET v_errCode 	= 0
        ,	v_errMsg	= 'Updated CallBack Successfully';
        
     ELSEIF p_HistoryId IS NOT NULL AND p_type = 'Facebook'
    THEN
		UPDATE 	tb_FacebookHistory
		SET 	CallBackFacebookHistoryId 	= p_CallBacksessionId
			,	isCallback					= 0	 
            ,	IsSessionClosed 			= 1
		WHERE 	FacebookHistoryId 			= p_HistoryId;
        
        SET v_errCode 	= 0
        ,	v_errMsg	= 'Updated CallBack Successfully';
     
     ELSEIF p_HistoryId IS NOT NULL AND p_type = 'Instagram'
    THEN
		UPDATE 	tb_InstagramHistory
		SET 	CallBackInstagramHistoryId 	= p_CallBacksessionId
			,	isCallback					= 0	 
            ,	IsSessionClosed 			= 1
		WHERE 	InstagramHistoryId 			= p_HistoryId;
        
        SET v_errCode 	= 0
        ,	v_errMsg	= 'Updated CallBack Successfully';
    
     END IF;
     
     SELECT v_errCode as errCode, v_errMsg as errMsg;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
