CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateTicketAutoAssignRuleStatus`(
  p_CompanyId 				INT
  ,p_ProductId 				INT
  ,p_TicketAutoAssignRuleId	BIGINT
  ,p_IsDeleted				BIGINT
  ,p_IsActive					BIGINT
  ,p_LoggedInUserId 			BIGINT)
BEGIN 
  	DECLARE v_errcode 		INT DEFAULT -1;
    	DECLARE v_errmsg 		VARCHAR(200) DEFAULT 'No Auto Assign Rule';    
    	DECLARE v_now 			DATETIME;
      
      SET v_now = NOW();
      
  	UPDATE 	tb_TicketAutoAssignRule T
      SET 	T.IsActive					= IFNULL(p_IsActive,T.IsActive)
              ,T.IsDeleted 				= IFNULL(p_IsDeleted,T.IsDeleted)
              ,T.UpdatedBy				= p_LoggedInUserId
  			,T.UpdatedDate				= v_now
      WHERE 	T.TicketAutoAssignRuleId 	= p_TicketAutoAssignRuleId;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
