CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateTicketDetails`(
       	p_CompanyId 					INT
       	,p_ProductId					INT
       	,p_TickectIds					VARCHAR(250)
       	,p_StatusId						INT
       	,p_PriorityId					INT
       	,p_RequesterId					INT
       	,p_TicketAssignee				TINYINT
       	,p_ResolutionDueDate			DATETIME
       	,p_TagIds						VARCHAR(250)
       	,p_TagNames						VARCHAR(250)
       	,p_Comments						LONGTEXT
       	,p_LoggedInUserId				INT
       	,p_TicketAssignedToGroupId 		INT
       	,p_TicketAssignedToAgentId 		INT
       	,p_ResponseDueDate				DATETIME
       	,p_TicketTypeId					INT
       	,p_TicketAssociateCustContact	INT
 		,p_TicketLogDetail				TEXT
		,p_TicketDescription			TEXT	
		,p_TicketSubject 				VARCHAR(200)
		)
BEGIN
       		DECLARE v_errcode  		INT DEFAULT -1;
       		DECLARE v_errmsg   		VARCHAR(55) DEFAULT 'No Ticket to Update';
       		DECLARE v_CurDate		DATETIME;
   			DECLARE v_TicketLogDetailId INT;
   			DECLARE v_RequestorId    INT;
   			DECLARE v_AssignedToAgentId INT;
   			DECLARE v_TicketAssociateCustContact INT;
   			DECLARE v_LastUpdatedTicketId BIGINT;
       
       		SET v_CurDate	= NOW();    
             
       		DROP TEMPORARY TABLE IF EXISTS tt_TicketIds; 		CREATE TEMPORARY TABLE tt_TicketIds(TicketId INT,RequestorId INT,AssignedToAgentId INT,TicketAssociateCustContact INT); 
       		DROP TEMPORARY TABLE IF EXISTS tt_Tags; 			CREATE TEMPORARY TABLE tt_Tags(TicketTagId varchar(50));  
       		DROP TEMPORARY TABLE IF EXISTS tt_TicketTags; 		CREATE TEMPORARY TABLE tt_TicketTags (TicketId INT ,TicketTagId INT); 
   			DROP TEMPORARY TABLE IF EXISTS tt_TicketLogDetail; 	CREATE TEMPORARY TABLE tt_TicketLogDetail (LogDetails TEXT); 
       
       		CALL split(p_TickectIds, ',');	INSERT INTO tt_TicketIds (TicketId) SELECT Items FROM tt_Split_temptable;    
       		CALL split(p_TagIds, ',');		INSERT INTO tt_Tags (TicketTagId)SELECT Items FROM tt_Split_temptable;
      		CALL split(p_TicketLogDetail, ',');		INSERT INTO tt_TicketLogDetail (LogDetails)SELECT Items FROM tt_Split_temptable; 
             
  			UPDATE tt_TicketIds     A
  			JOIN   tb_TicketDetails B on A.TicketId = B.TicketId
  			SET A.RequestorId 					= B.RequestorId,
  			A.AssignedToAgentId				= B.AssignedToAgentId,
  			A.TicketAssociateCustContact	= B.TicketAssociateCustContact;     		
       
       		INSERT INTO tt_TicketTags(TicketId,TicketTagId)
       		SELECT t_Tick.TicketId, t_Tag.TicketTagId
       		FROM 	tt_TicketIds	t_Tick
       		JOIN 	tt_Tags			t_Tag;                 
               
       		INSERT INTO tb_TicketTagMapping(	TicketId ,TicketTagId ,CreatedDate)
       		SELECT 		T_TT.TicketId, T_TT.TicketTagId, v_CurDate
       		FROM 		tt_TicketTags T_TT
       		LEFT JOIN 	tb_TicketTagMapping TT 	ON 	T_TT.TicketId = TT.TicketId
       		AND			T_TT.TicketTagId  = TT.TicketTagId
       		AND 		TT.TicketTagId	IS NULL;
              
       	    DROP TEMPORARY TABLE IF EXISTS tt_Tags; 
              
 			DELETE 	TM
 			FROM 	tb_TicketTagMapping TM
 			JOIN 	tb_TicketDetails	TD	ON 	TD.CompanyId		= p_CompanyId    
 											AND TD.ProductId		= p_ProductId
 											AND	TM.TicketId			= TD.TicketId
 			LEFT JOIN tt_TicketTags T_TT ON T_TT.TicketId			= TM.TicketId
 											AND	T_TT.TicketTagId 	= TM.TicketTagId
 			WHERE 	T_TT.TicketTagId IS NULL;
             
          DROP TEMPORARY TABLE IF EXISTS tt_TicketTags; 	
          
       	INSERT INTO tb_TicketComments(TicketId, Comments, ParentTicketCommentsId, IsDeleted, CreatedBy, CreatedDate, UpdatedBy, UpdatedDate)
       	SELECT 	t_Tick.TicketId, p_Comments, NULL, 0, p_LoggedInUserId,	v_CurDate, p_LoggedInUserId, v_CurDate    
       	FROM 	tt_TicketIds t_Tick;
             
        	UPDATE 	tb_TicketDetails	TD
        	JOIN 	tt_TicketIds		t_T	ON t_T.TicketId = TD.TicketId
        	SET 	TD.TicketStatusId				= IFNULL(p_StatusId,TD.TicketStatusId)
      			,TD.PriorityId					= IFNULL(p_PriorityId,TD.PriorityId)
      			,TD.RequestorId					= IFNULL(p_RequesterId,TD.RequestorId)
      			,TD.TicketAssignee				= IFNULL(p_TicketAssignee,TD.TicketAssignee)
      			,TD.ResolutionDueDate			= IFNULL(p_ResolutionDueDate,TD.ResolutionDueDate)
      			,TD.TicketTagIdName				= IFNULL(p_TagNames,TD.TicketTagIdName)								
      			,TD.TagId						= IFNULL(p_TagIds,TD.TagId) 
      			,TD.UpdatedBy					= p_LoggedInUserId
 				,TD.UpdatedDate					= v_CurDate
      			,TD.AssignedToGroupId 			= IFNULL(p_TicketAssignedToGroupId,TD.AssignedToGroupId)
      			,TD.AssignedToAgentId 			= IFNULL(p_TicketAssignedToAgentId,TD.AssignedToAgentId)	
      			,TD.ResponseDueDate				= IFNULL(p_ResponseDueDate,TD.ResponseDueDate)		
      			,TD.TicketTypeId				= IFNULL(p_TicketTypeId,TD.TicketTypeId)
      			,TD.TicketAssociateCustContact	= IFNULL(p_TicketAssociateCustContact,TD.TicketAssociateCustContact)
 				,TD.TicketDescription			 = IFNULL(p_TicketDescription, TD.TicketDescription)
 				,TD.TicketSubject			 	= IFNULL(p_TicketSubject, TD.TicketSubject);
     	 SET v_LastUpdatedTicketId = last_insert_id();
         SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
 		SELECT RequestorId, AssignedToAgentId, TicketAssociateCustContact
 		INTO v_RequestorId, v_AssignedToAgentId, v_TicketAssociateCustContact
 		FROM tb_TicketDetails
 		WHERE TicketId = v_LastUpdatedTicketId;
                  
                  INSERT INTO tb_TicketLogDetail
      		(	TicketId					
      			,LogDetails					
      			,IsDeleted		
      			,CompanyId 
                  ,ProductId 
      			,CreatedBy					
      			,CreatedDate				
      			,UpdatedBy					
      			,UpdatedDate				
              )
             select
              	t_Tick.TicketId
      			,t_Log.LogDetails
                  ,1
                  ,p_CompanyId 
                  ,p_ProductId 
      			,p_LoggedInUserId
                  ,v_CurDate
                  ,p_LoggedInUserId
                  ,v_CurDate
              
              FROM 	tt_TicketIds	            t_Tick
       		JOIN 	tt_TicketLogDetail			t_Log; 
  			SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
              
  			DROP TEMPORARY TABLE IF EXISTS tt_TicketLogDetail;
               
  			SET v_TicketLogDetailId = last_insert_id();        
             
            DROP TEMPORARY TABLE IF EXISTS tt_TicketIdsTA;  create temporary table tt_TicketIdsTA as select * from tt_TicketIds;
            DROP TEMPORARY TABLE IF EXISTS tt_TicketIdsTB;  create temporary table tt_TicketIdsTB as select * from tt_TicketIds;
            DROP TEMPORARY TABLE IF EXISTS tt_TicketIdsTC;  create temporary table tt_TicketIdsTC as select * from tt_TicketIds;
            
            DROP TEMPORARY TABLE IF EXISTS tt_TicketIds; 
              
              INSERT INTO tb_TicketNotification
      		(	TicketId					
      			,TicketLogDetailId			
      			,NotificationUserId			
      			,NotificationUserTypeId		
      			,IsRead					
                  ,CompanyId 
                  ,ProductId 
      			,CreatedBy					
      			,CreatedDate				
      			,UpdatedBy					
      			,UpdatedDate				
              )
              SELECT TA.TicketId
      			,	v_TicketLogDetailId
      			,	RequestorId
                  ,	1117001			
                  ,	0
                  ,	p_CompanyId 
                  ,	p_ProductId 
                  ,	p_LoggedInUserId
                  ,	v_CurDate
                  ,	p_LoggedInUserId
                  ,	v_CurDate
                  from tt_TicketIdsTA TA
   			    
      		UNION ALL		
      		SELECT 	TB.TicketId
      			,	v_TicketLogDetailId
      			,	AssignedToAgentId
                  ,	1117002			
                  ,	0
                  ,	p_CompanyId 
                  ,	p_ProductId 
                  ,	p_LoggedInUserId
                  ,	v_CurDate
                  ,	p_LoggedInUserId
                  ,	v_CurDate 
                  from tt_TicketIdsTB TB
                 
      		UNION ALL		
      		SELECT	TC.TicketId
      			,	v_TicketLogDetailId
      			,	TicketAssociateCustContact
                  ,	1117003			
                  ,	0
                  ,	p_CompanyId 
                  ,	p_ProductId 
                  ,	p_LoggedInUserId
                  ,	v_CurDate
                  ,	p_LoggedInUserId
                  ,	v_CurDate 
                  from tt_TicketIdsTC TC;
 			DROP TEMPORARY TABLE IF EXISTS tt_TicketIdsTC; 
 				SET v_errcode = 0;
 				SET v_errmsg  = 'Updated Successfully';
 			DROP TEMPORARY TABLE IF EXISTS tt_TicketIdsTA;
 			DROP TEMPORARY TABLE IF EXISTS tt_TicketIdsTB;
             SELECT v_errcode errcode, v_errmsg 'errmsg';     
         END ;;
DELIMITER ;
