CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateTicketEmailNotifications`(
       p_TicketEmailNotificationsId    			INT,
       p_CompanyId            						INT,
       p_ProductId                      			INT,
       p_NotificationName        					VARCHAR(250),
       p_Description                   			TEXT,
       p_EmailTypeId                    			INT,
       p_EmailSubject                   			VARCHAR(250),
       p_EmailBody                  				TEXT,
       p_IsActive									TINYINT,
       p_IsDefault									TINYINT,
   	p_LoggedInUserID 	        				BIGINT       
    )
BEGIN
    	declare v_errcode 						int;
    	declare v_errmsg 						varchar(55);
       declare v_CurDate						DATETIME;
       DECLARE v_TicketEmailNotificationsId	INT;
       
       SET v_CurDate = NOW();
        
   	sp_exit : begin
       SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
            SELECT TicketEmailNotificationsId INTO v_TicketEmailNotificationsId 
   		 FROM 	tb_TicketEmailNotifications
   		 WHERE  TicketEmailNotificationsId = p_TicketEmailNotificationsId;
          SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 
            IF v_TicketEmailNotificationsId IS NOT NULL
   		 THEN
   			 UPDATE tb_TicketEmailNotifications
   			 SET	 NotificationName     		  	= ifnull(p_NotificationName,NotificationName)
   					,`Description`       			= ifnull(p_Description,`Description`)
   					,EmailTypeId        		  	= ifnull(p_EmailTypeId,EmailTypeId)          
   					,EmailSubject		 			= ifnull(p_EmailSubject,EmailSubject)
                       ,EmailBody		 			  	= ifnull(p_EmailBody,EmailBody)
                       ,IsActive		 		  		= ifnull(p_IsActive,IsActive)
                       ,IsDefault		 		  		= ifnull(p_IsDefault,IsDefault)
   					,UpdatedBy       		  		= p_LoggedInUserID
   					,UpdatedDate              		= v_CurDate
   			 WHERE 
   			 TicketEmailNotificationsId = p_TicketEmailNotificationsId;
   								
   			if row_count()>0
   			then
   				set v_errcode         = 0;
   				set v_errmsg          = 'updated successfully';
   				leave sp_exit;
   			end if;
   		end if;
   	end sp_exit;        
                        
   	select v_errcode as errcode, v_errmsg as errmsg;
                        
   end ;;
DELIMITER ;
