CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateTicketTriggerStatus`(
  p_CompanyId 			INT
  ,p_ProductId 			INT
  ,p_TicketTriggerId		BIGINT
  ,p_IsDeleted			BIGINT
  ,p_IsActive				BIGINT
  ,p_LoggedInUserId 		BIGINT)
BEGIN 
  	DECLARE v_errcode 		INT DEFAULT -1;
    	DECLARE v_errmsg 		VARCHAR(200) DEFAULT 'No Trigger';    
    	DECLARE v_now 			DATETIME;
      
      SET v_now = NOW();
      
  	UPDATE 	tb_TicketTrigger T
      SET 	T.IsActive			= IFNULL(p_IsActive,T.IsActive)
              ,T.IsDeleted 		= IFNULL(p_IsDeleted,T.IsDeleted)
              ,T.UpdatedBy		= p_LoggedInUserId
  			,T.UpdatedDate		= v_now
      WHERE 	T.TicketTriggerId 	= p_TicketTriggerId;
  END ;;
DELIMITER ;
