CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_UpdateUnclosedSession`(p_domainId	INT)
SP: BEGIN 	    
	DECLARE v_dispositionId 		INT;
    DECLARE v_DateBefore24Hour		DATETIME DEFAULT DATE_SUB(NOW(), INTERVAL 1 DAY); 

	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;
	SELECT 	did INTO v_dispositionId
	FROM 	disposition_status 
	WHERE 	domainId 		= p_domainId
	AND 	dispositionName = 'Caller Disconnected';	
    
    
    DROP TEMPORARY TABLE IF EXISTS tt_CallDurationHistoryIds;
    CREATE TEMPORARY TABLE tt_CallDurationHistoryIds
    SELECT 	DH.CallDurationHistoryId
    FROM 	tb_CallHistory 			H
	JOIN 	tb_CallDurationHistory 	DH ON H.CallHistoryId 	= DH.CallHistoryId 	
	WHERE 	domainId = p_domainId          
	AND 	sessionEndTime 	= 0 
	AND 	dispositionId 	= 0
	AND 	H.createdAt < v_DateBefore24Hour;
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;    	
    
	
	UPDATE 	tb_CallDurationHistory 		DH 
    JOIN 	tt_CallDurationHistoryIds	t_DH	ON DH.CallDurationHistoryId	= t_DH.CallDurationHistoryId
	SET 	dispositionId = v_dispositionId;
    
    DELETE 	FROM tb_UnclosedSession 
    WHERE 	domainId	= p_domainId;
    
    INSERT INTO tb_UnclosedSession(
		domainId,	
		updatedDate	
    )
    VALUES(
		p_domainId,
        CURDATE()
    );
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
