CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_UpdateWhatsappQueueidBasedOnDomainId`(
p_WhatsappHistoryId bigint,
p_queueId int
)
Begin
	declare v_errcode int default -1;
    declare v_errmsg varchar(50) default 'Failure';
    declare v_WhatsappHistoryId bigint;
    
    select WhatsappHistoryId into v_WhatsappHistoryId from tb_WhatsappDurationHistory where WhatsappHistoryId = p_WhatsappHistoryId limit 1;
    
    if v_WhatsappHistoryId is not null then
		update tb_WhatsappDurationHistory 
        set QueueId = ifnull(p_queueId,QueueId)
        where WhatsappHistoryId = v_WhatsappHistoryId;
        
        if row_count()>0  then
			set v_errcode = 0;
            set v_errmsg = 'Success : Queue updated';
        End if;
        
    End if;
    
    select v_errcode as errcode, v_errmsg as errmsg;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
