CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_update_did_purchase`(	p_your_number		VARCHAR(255)
 	,p_domainId			INT
     ,p_callFlowId		longtext
     ,p_recording		INT    
 )
BEGIN	
 	DECLARE v_errcode 		int default -1;
     DECLARE v_errmsg 		VARCHAR(150) default 'No update in Did Purchase';
     DECLARE v_CurDate		DATETIME;
     
     SET v_CurDate = NOW();
     
 	UPDATE 	did_purchase 
     SET 	callFlowId 		= p_callFlowId
         ,	recording 		= p_recording
         , 	defaultUpdated 	= 1 
         ,	updatedAt 		= v_CurDate
     WHERE 	your_number 	= p_your_number COLLATE utf8mb4_unicode_ci;
 
 	IF row_count() > 0
     THEN
 		SET v_errcode 	= 0;
         SET v_errmsg	= 'Did Purchase Updated Successfully'; 
     END IF;
     
     SELECT v_errcode errcode, v_errmsg errmsg;	
 END ;;
DELIMITER ;
