CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_update_techticket_notification`(
 	p_notification_id	VARCHAR(1000),
     p_is_read			TINYINT,
     p_company_id		INT,
     p_user_id			INT
   )
BEGIN
 	DROP TEMPORARY TABLE IF EXISTS tt_notification_ids;
 	CREATE TEMPORARY TABLE tt_notification_ids(notification_id 	INT);
     
     CALL Split(p_notification_id,',');
     
     INSERT INTO tt_notification_ids(notification_id)
     SELECT 	items
     FROM 	tt_Split_temptable;    
     
 	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ; 
 	UPDATE 	tb_techticket_user_notification	N
     JOIN 	tt_notification_ids				Ns	ON Ns.notification_id = N.notification_id
     SET 	N.isRead		= p_is_read
 		,	N.updated_date	= NOW()
     WHERE 	N.CompanyId		= p_company_id
 	AND 	N.userId		= IFNULL(p_user_id,0);
     
     SELECT 1 AS errcode, 'Notification updated successfully' AS errmsg;
     SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
 END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
