CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_VM_InsertUpdateVideoMeet`( 	p_videoMeetId					BIGINT
	,p_domainId						INT
	,p_uuid							VARCHAR(100)
	,p_title						VARCHAR(1000)	
    ,p_meetingDescription			TEXT	    
    ,p_startTime					BIGINT
    ,p_endTime						BIGINT
    ,p_timeZone						VARCHAR(150)
    ,p_durationMinutes				INT
    ,p_joiningOptionType			VARCHAR(100)    
    ,p_calenderType					VARCHAR(100)
    ,p_rRule						VARCHAR(250)
    ,p_isRecordMeeting				TINYINT			
    ,p_isAlternateHostAllowed		TINYINT    		
    ,p_isHostVideoOn				TINYINT			
    ,p_isParticipantVideoOn			TINYINT			
    ,p_isParticipantJoinBeforeHost	TINYINT			
    ,p_isParticipantInviteGuest		TINYINT			
    ,p_isParticipantWaitingRoom		TINYINT			
    ,p_isParticipantMuteEntry		TINYINT			
    ,p_isUsePersonalMeetingId		TINYINT			
    ,p_personalMeetingId			VARCHAR(50)
    ,p_isWithoutHostMeetingContinue	TINYINT			
    ,p_isCustomePassword			TINYINT			
    ,p_dialInCountries				JSON
    ,p_meetingPassword				varchar(100)
    ,p_queueId						varchar(100)
    ,p_hostAgentId					BIGINT
	,p_videoMeetDomain				VARCHAR(250)
    ,p_actualMeetingStartTime		BIGINT
    ,p_inviteUrl					VARCHAR(150)
    ,p_isAttended					TINYINT			
    ,p_saveAsTemplate				TINYINT     	
    ,p_meetingStatusTypeId			INT			 
    ,p_isDeleted					TINYINT
)
BEGIN
    DECLARE v_CurDate		DATETIME;
    DECLARE v_videoMeetId	BIGINT;
    DECLARE v_errMsg		VARCHAR(150) 	DEFAULT 'Video Meet added/update failed';
    DECLARE v_errCode		SMALLINT		DEFAULT -1;
    
    SET v_CurDate = NOW();
    
    SELECT 	videoMeetId INTO v_videoMeetId
    FROM 	tb_VM_VideoMeet
    WHERE 	uuid	= p_uuid;
    
    IF v_videoMeetId IS NOT NULL
    THEN
		INSERT INTO tb_VM_VideoMeet
        (	videoMeetId
			,domainId
			,uuid
			,title
			,meetingDescription
			,startTime
			,endTime
			,timeZone
			,durationMinutes
			,joiningOptionType
			,calenderType
			,rRule
			,isRecordMeeting
			,isAlternateHostAllowed
			,isHostVideoOn
			,isParticipantVideoOn
			,isParticipantJoinBeforeHost
			,isParticipantInviteGuest
			,isParticipantWaitingRoom
			,isParticipantMuteEntry
			,isUsePersonalMeetingId
			,personalMeetingId
			,isWithoutHostMeetingContinue
			,isCustomePassword
			,dialInCountries
			,meetingPassword
			,queueId
			,hostAgentId
			,videoMeetDomain
			,actualMeetingStartTime
			,inviteUrl
			,isAttended
			,saveAsTemplate
			,meetingStatusTypeId
			,isDeleted
			,createdDate
			,updatedDate
        )
        VALUES
        (	 p_videoMeetId					
            ,p_domainId						
            ,p_uuid							
            ,p_title						
            ,p_meetingDescription			
            ,p_startTime					
            ,p_endTime						
            ,p_timeZone						
            ,p_durationMinutes				
            ,p_joiningOptionType			
            ,p_calenderType					
            ,p_rRule						
            ,p_isRecordMeeting				
            ,p_isAlternateHostAllowed		
            ,p_isHostVideoOn				
            ,p_isParticipantVideoOn			
            ,p_isParticipantJoinBeforeHost	
            ,p_isParticipantInviteGuest		
            ,p_isParticipantWaitingRoom		
            ,p_isParticipantMuteEntry		
            ,p_isUsePersonalMeetingId		
            ,p_personalMeetingId			
            ,p_isWithoutHostMeetingContinue	
            ,p_isCustomePassword			
            ,p_dialInCountries				
            ,p_meetingPassword				
            ,p_queueId						
            ,p_hostAgentId					
            ,p_videoMeetDomain				
            ,p_actualMeetingStartTime		
            ,p_inviteUrl					
            ,p_isAttended					
            ,p_saveAsTemplate				
            ,p_meetingStatusTypeId			
            ,p_isDeleted
            ,v_CurDate
            ,v_CurDate
        );
        
        SET v_videoMeetId 	= last_insert_id();
        SET v_errMsg		= 'Video Meet added successfully';
        SET v_errCode		= 0;
	ELSE  
		UPDATE 	tb_VM_VideoMeet
		SET 	videoMeetId						= p_videoMeetId					
				,domainId                       = p_domainId						
				,uuid                           = p_uuid							
				,title                          = p_title						
				,meetingDescription             = p_meetingDescription			
				,startTime                      = p_startTime					
				,endTime                        = p_endTime						
				,timeZone                       = p_timeZone						
				,durationMinutes                = p_durationMinutes				
				,joiningOptionType              = p_joiningOptionType			
				,calenderType                   = p_calenderType					
				,rRule                          = p_rRule						
				,isRecordMeeting                = p_isRecordMeeting				
				,isAlternateHostAllowed         = p_isAlternateHostAllowed		
				,isHostVideoOn                  = p_isHostVideoOn				
				,isParticipantVideoOn           = p_isParticipantVideoOn			
				,isParticipantJoinBeforeHost    = p_isParticipantJoinBeforeHost	
				,isParticipantInviteGuest       = p_isParticipantInviteGuest		
				,isParticipantWaitingRoom       = p_isParticipantWaitingRoom		
				,isParticipantMuteEntry         = p_isParticipantMuteEntry		
				,isUsePersonalMeetingId         = p_isUsePersonalMeetingId		
				,personalMeetingId              = p_personalMeetingId			
				,isWithoutHostMeetingContinue   = p_isWithoutHostMeetingContinue	
				,isCustomePassword              = p_isCustomePassword			
				,dialInCountries                = p_dialInCountries				
				,meetingPassword                = p_meetingPassword				
				,queueId                        = p_queueId						
				,hostAgentId                    = p_hostAgentId					
				,hideoMeetDomain                = p_hideoMeetDomain				
				,actualMeetingStartTime         = p_actualMeetingStartTime		
				,inviteUrl                      = p_inviteUrl					
				,isAttended                     = p_isAttended					
				,saveAsTemplate                 = p_saveAsTemplate				
				,meetingStatusTypeId            = p_meetingStatusTypeId			
				,isDeleted                      = p_isDeleted
				,createdDate                    = v_CurDate
				,updatedDate                    = v_CurDate
		WHERE 	videoMeetId = p_videoMeetId;        
        
        SET v_errMsg		= 'Video Meet updated successfully';
        SET v_errCode		= 0;        
    END IF;
    
    select v_errMsg as errMsg, v_errCode as errCode;
	

END ;;
DELIMITER ;
