/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_Voice_agent_servicelevel_analysis_trendchart`(
       	p_domainId 			INT,
       	p_datetype 			INT,                
   		p_startDateTime		DATETIME,
   		p_endDateTime		DATETIME,
       	p_columnName    	VARCHAR(200),       
       	p_agentId 			TEXT
)
sp_return: BEGIN
     
      	DECLARE v_startDateTime			DATETIME;
      	DECLARE v_endDateTime			DATETIME;     
      	DECLARE v_datetimeInterval		SMALLINT;    
      	DECLARE v_startDateTimePast		DATETIME;
      	DECLARE v_endDateTimePast		DATETIME;
           
      	DECLARE v_startTimestampPast	BIGINT;
      	DECLARE v_endTimestampPast		BIGINT;      
      	DECLARE v_startTimestamp		BIGINT;
      	DECLARE v_endTimestamp			BIGINT;
      	DECLARE v_curDate				DATETIME DEFAULT NOW();	
		DECLARE v_currentCount			INT;
		DECLARE v_pastCount				INT;
        DECLARE p_timezone				Text;
        
        set p_timezone = '+05:30';
          
      	DROP TEMPORARY TABLE IF EXISTS tmp_result;
      	CREATE TEMPORARY TABLE tmp_result(
      		reportAge			VARCHAR(20)
      		,startDateTime		DATETIME
      		,endDateTime		DATETIME
      		,callCount			INT
      	);    
       
       	IF p_datetype = 1 
           THEN 	
       		SET v_startDateTime = CAST(v_curDate AS DATE); 
       		SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);     
       	END IF;
       	IF p_datetype = 2 
           THEN 
       		SET v_startDateTime = CAST(DATE_ADD(v_curDate,INTERVAL -1 DAY) AS DATE); 
               SET v_endDateTime = DATE_ADD(DATE_ADD(v_startDateTime,INTERVAL 1 DAY),INTERVAL -1 MINUTE); 
       
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 DAY); 
       		SET v_endDateTimePast = DATE_ADD(v_endDateTime,INTERVAL -1 DAY);           
       	END IF;
       	IF p_datetype = 3 
           THEN 
       		
                 
                 SET v_startDateTime = p_startDateTime;
                 SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND);  
                 
     			SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;   
                 
         		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
                 SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
       	IF p_datetype = 4 
           THEN 
       		SET v_startDateTime = p_startDateTime; 
               SET v_endDateTime = DATE_ADD(CAST(p_endDateTime AS DATE), INTERVAL '23:59:59' HOUR_SECOND); 
               
               SET v_datetimeInterval	= DATEDIFF(v_endDateTime,v_startDateTime)+1;
               
       		SET v_startDateTimePast = DATE_ADD(v_startDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       		SET v_endDateTimePast 	= DATE_ADD(v_endDateTime,INTERVAL -1 * v_datetimeInterval DAY);
       	END IF;
           
		IF p_agentId IS NOT NULL 
          THEN
      		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
      		CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
          ELSE
      		DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	
            CREATE TEMPORARY TABLE temp_agentIds
    		select  UserID as agentId,UserName from tb_User where domainId = p_domainId AND roleid NOT IN (3); 
		END IF;
           
           DROP TEMPORARY TABLE IF EXISTS tmp_Disposition;	
           CREATE TEMPORARY TABLE tmp_Disposition
           SELECT did, dispositionName
           FROM 	disposition_status
           WHERE	domainId		= p_domainId;
           
           
           IF p_datetype IN (1,2)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
				WITH RECURSIVE CTE_TIMINGS AS (
                SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(DATE_ADD(v_startDateTimePast,INTERVAL 59 MINUTE),INTERVAL 59 SECOND) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 HOUR) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 HOUR) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	endDateTime  < cast(v_endDateTime as date)
       		)
       		SELECT * FROM CTE_TIMINGS;	
       	ELSEIF p_datetype IN (3,4)
           THEN 
       		DROP TEMPORARY TABLE IF EXISTS tmp_timings;	
               CREATE TEMPORARY TABLE tmp_timings(startDateTime	DATETIME,endDateTime	DATETIME)
       		WITH recursive CTE_TIMINGS AS (
       			SELECT 	v_startDateTimePast AS startDateTime, DATE_ADD(v_startDateTimePast,INTERVAL 1439 MINUTE ) AS endDateTime
       			UNION ALL
       			SELECT 	DATE_ADD(startDateTime,INTERVAL 1 DAY) AS startDateTime, DATE_ADD(endDateTime,INTERVAL 1 DAY) AS endDateTime
       			FROM 	CTE_TIMINGS
       			WHERE 	startDateTime < cast(v_endDateTime  as date)
       		)
       		SELECT * FROM CTE_TIMINGS;	
           END IF;  
           
           ALTER TABLE tmp_timings ADD COLUMN startTimestamp	BIGINT, ADD COLUMN endTimestamp	BIGINT;
           
           UPDATE tmp_timings
   			SET	startTimestamp 	= unix_timestamp(convert_tz(startDateTime,p_timezone,'+00:00')) * 1000,
   				endTimestamp 	= unix_timestamp(convert_tz(endDateTime,p_timezone,'+00:00')) * 1000;
               
   			 UPDATE tmp_timings
           SET 	startTimestamp	= UNIX_TIMESTAMP(startDateTime) * 1000
       		,	endTimestamp	= UNIX_TIMESTAMP(endDateTime)  * 1000;
               
       	SET v_startTimestampPast	= UNIX_TIMESTAMP(v_startDateTimePast) * 1000
      	,	v_endTimestampPast		= UNIX_TIMESTAMP(v_endDateTimePast) * 1000
      	,	v_startTimestamp		= UNIX_TIMESTAMP(v_startDateTime) * 1000
      	, 	v_endTimestamp			= UNIX_TIMESTAMP(v_endDateTime) * 1000;
       
		DROP TEMPORARY TABLE IF EXISTS tmp_CallDurationHistory;	
		CREATE TEMPORARY TABLE tmp_CallDurationHistory
		SELECT 	CH.CallHistoryId
			,	CDH.CallDurationHistoryId
			,	CH.sessionStartTime
			,	CDH.IsMissedCall
			,	CDH.dispositionId
			,	CDH.answeredDuration
			,   CDH.Duration
            ,	CDH.AgentId
            ,	CDH.UMNStatus
            ,	CH.IsAbandoned
		FROM 	tb_CallHistory         	CH
		JOIN	tb_CallDurationHistory 	CDH	ON CH.CallHistoryId 	= CDH.CallHistoryId     
		LEFT JOIN	temp_agentIds		t_A	ON t_A.agentId 			= CDH.agentId 	
		WHERE 	CH.domainId 		= p_domainId
        AND 	CDH.IsBot			=	0
		AND 	CH.sessionStartTime BETWEEN v_startTimestampPast AND v_endTimestamp
        AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));
		
       	
      	DROP TEMPORARY TABLE IF EXISTS tmp_CallHistory;	
       	CREATE TEMPORARY TABLE tmp_CallHistory
		SELECT 	DISTINCT 
       			CDH.CallHistoryId 
       		, 	CDH.sessionStartTime
            ,	CDH.CallDurationHistoryId
       	FROM 	tmp_CallDurationHistory CDH;  
           
           ALTER TABLE tmp_CallHistory ADD IsMissed 		TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD IsAnswered 		TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD IsUnAnswered 	TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD IsAbandoned		TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD TotalSLA			TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD SL1				TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD SL2				TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD SL3				TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD SL4				TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD SL5				TINYINT default 0;
           ALTER TABLE tmp_CallHistory ADD SL6				TINYINT default 0;
           
           CREATE INDEX ix_tmp_CallHistory ON tmp_CallHistory (CallHistoryId);
           CREATE INDEX ix_tmp_CallDurationHistory ON tmp_CallDurationHistory (CallHistoryId);  
       
			UPDATE tmp_CallHistory			CH
			JOIN 	tmp_CallDurationHistory	CDH	ON CH.CallHistoryId	= CDH.CallHistoryId  AND CDH.CallDurationHistoryId = CH.CallDurationHistoryId
			LEFT JOIN tmp_Disposition		D	ON D.did			= CDH.dispositionId
			SET 	CH.IsMissed		= CASE WHEN CDH.IsMissedCall = 1	THEN 1 ELSE 0 	    END
				,	CH.IsAnswered	= CASE WHEN CDH.Duration > 0 AND CDH.UMNStatus = 1 THEN 1 ELSE 0	    END
				,	CH.IsUnAnswered	= CASE WHEN CDH.Duration < 0 		THEN 1 ELSE 0	    END
				,   CH.TotalSLA     = CASE WHEN CDH.answeredDuration BETWEEN 1 AND 30 THEN 1 ELSE 0 END 
                ,   CH.SL1     		= CASE WHEN CDH.answeredDuration BETWEEN 1 AND 5 THEN 1 ELSE 0 END 
                ,   CH.SL2     		= CASE WHEN CDH.answeredDuration BETWEEN 6 AND 10 THEN 1 ELSE 0 END 
                ,   CH.SL3     		= CASE WHEN CDH.answeredDuration BETWEEN 11 AND 15 THEN 1 ELSE 0 END 
                ,   CH.SL4     		= CASE WHEN CDH.answeredDuration BETWEEN 16 AND 20 THEN 1 ELSE 0 END 
                ,   CH.SL5     		= CASE WHEN CDH.answeredDuration BETWEEN 21 AND 25 THEN 1 ELSE 0 END 
                ,   CH.SL6     		= CASE WHEN CDH.answeredDuration BETWEEN 26 AND 30 THEN 1 ELSE 0 END 
				,	CH.IsAbandoned	= CASE WHEN CDH.IsAbandoned  = 1 THEN 1 ELSE 0 	END;     
              

		IF p_columnName = 'Missed Calls'
      	THEN
      		INSERT INTO tmp_result
       		SELECT 	'Current'			AS reportAge
       			,	t_T.startDateTime 
       			,	t_T.endDateTime
       			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount
       		FROM 	tmp_timings			t_T	
       		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
       		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
       		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
              INSERT INTO tmp_result
       		SELECT 	'Past'					    AS reportAge
       			,	t_T.startDateTime 
       			,	t_T.endDateTime
       			,	IFNULL(SUM(CH.IsMissed),0)	AS callCount     
       		FROM 	tmp_timings		t_T	
       		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
       		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
       		GROUP BY t_T.startDateTime, t_T.endDateTime;          
        ELSEIF p_columnName = 'Total'
      	THEN
      		INSERT INTO tmp_result
       		SELECT 	'Current'					AS reportAge
       			,	t_T.startDateTime 
       			,	t_T.endDateTime
       			,	IFNULL(SUM(TotalSLA),0)	    AS callCount
       		FROM 	tmp_timings			t_T	
       		LEFT JOIN tmp_CallHistory 	CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
       		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp
       		GROUP BY t_T.startDateTime, t_T.endDateTime;
              
              INSERT INTO tmp_result
       		SELECT 	'Past'						AS reportAge
       			,	t_T.startDateTime 
       			,	t_T.endDateTime
       			,	IFNULL(SUM(TotalSLA),0)	    AS callCount     
       		FROM 	tmp_timings		t_T	
       		LEFT JOIN 	tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp
       		WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	
       		GROUP BY t_T.startDateTime, t_T.endDateTime;
            
		ELSEIF p_columnName = 'SL1' THEN
      		INSERT INTO tmp_result SELECT 'Current' AS reportAge,	t_T.startDateTime ,	t_T.endDateTime, IFNULL(SUM(CH.SL1),0)	AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp GROUP BY t_T.startDateTime, t_T.endDateTime;
            INSERT INTO tmp_result SELECT 'Past' AS reportAge, 		t_T.startDateTime , t_T.endDateTime, IFNULL(SUM(CH.SL1),0) AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	 GROUP BY t_T.startDateTime, t_T.endDateTime;  
		ELSEIF p_columnName = 'SL2' THEN
      		INSERT INTO tmp_result SELECT 'Current' AS reportAge,	t_T.startDateTime ,	t_T.endDateTime, IFNULL(SUM(CH.SL2),0)	AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp GROUP BY t_T.startDateTime, t_T.endDateTime;
            INSERT INTO tmp_result SELECT 'Past' AS reportAge, 		t_T.startDateTime , t_T.endDateTime, IFNULL(SUM(CH.SL2),0) AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	 GROUP BY t_T.startDateTime, t_T.endDateTime;  
		ELSEIF p_columnName = 'SL3' THEN
      		INSERT INTO tmp_result SELECT 'Current' AS reportAge,	t_T.startDateTime ,	t_T.endDateTime, IFNULL(SUM(CH.SL3),0)	AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp GROUP BY t_T.startDateTime, t_T.endDateTime;
            INSERT INTO tmp_result SELECT 'Past' AS reportAge, 		t_T.startDateTime , t_T.endDateTime, IFNULL(SUM(CH.SL3),0) AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	 GROUP BY t_T.startDateTime, t_T.endDateTime;  
		ELSEIF p_columnName = 'SL4' THEN
      		INSERT INTO tmp_result SELECT 'Current' AS reportAge,	t_T.startDateTime ,	t_T.endDateTime, IFNULL(SUM(CH.SL4),0)	AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp GROUP BY t_T.startDateTime, t_T.endDateTime;
            INSERT INTO tmp_result SELECT 'Past' AS reportAge, 		t_T.startDateTime , t_T.endDateTime, IFNULL(SUM(CH.SL4),0) AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	 GROUP BY t_T.startDateTime, t_T.endDateTime;  
		ELSEIF p_columnName = 'SL5' THEN
      		INSERT INTO tmp_result SELECT 'Current' AS reportAge,	t_T.startDateTime ,	t_T.endDateTime, IFNULL(SUM(CH.SL5),0)	AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp GROUP BY t_T.startDateTime, t_T.endDateTime;
            INSERT INTO tmp_result SELECT 'Past' AS reportAge, 		t_T.startDateTime , t_T.endDateTime, IFNULL(SUM(CH.SL5),0) AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	 GROUP BY t_T.startDateTime, t_T.endDateTime;  
		ELSEIF p_columnName = 'SL6' THEN
      		INSERT INTO tmp_result SELECT 'Current' AS reportAge,	t_T.startDateTime ,	t_T.endDateTime, IFNULL(SUM(CH.SL6),0)	AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON 	CH.sessionStartTime BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestamp 	AND v_endTimestamp GROUP BY t_T.startDateTime, t_T.endDateTime;
            INSERT INTO tmp_result SELECT 'Past' AS reportAge, 		t_T.startDateTime , t_T.endDateTime, IFNULL(SUM(CH.SL6),0) AS callCount FROM tmp_timings t_T LEFT JOIN tmp_CallHistory CH	ON CH.sessionStartTime 	BETWEEN t_T.startTimestamp 	AND t_T.endTimestamp WHERE 	t_T.startTimestamp	BETWEEN v_startTimestampPast 	AND v_endTimestampPast	 GROUP BY t_T.startDateTime, t_T.endDateTime;  
		END IF;
           
          SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Current';    
          
          SELECT  *
          FROM 	tmp_result
          WHERE 	reportAge = 'Past';
           
      	SELECT 	SUM(CASE WHEN reportAge = 'Current' THEN callCount ELSE 0 END)	AS currentCount, SUM(CASE WHEN reportAge = 'Past' THEN callCount ELSE 0 END)	AS pastCount
      	INTO 	v_currentCount, v_pastCount		
      	FROM 	tmp_result;
          
		SELECT 	p_columnName    													AS metric
			,	ifnull(v_currentCount,0)											AS currentTotal
			,	ifnull(v_pastCount,0)												AS pastTotal
			,	ifnull((v_currentCount - v_pastCount),0)  							AS totalDifference
			,	ifnull((v_currentCount - v_pastCount) 
						/(IF(IFNULL(v_pastCount,0)=0,1,v_pastCount)) *100 ,0)    	AS  Percentage;
               
               end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_WhatApp_agent_servicelevel_analysis_metrics_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`dbdev`@`%` PROCEDURE `up_WhatApp_agent_servicelevel_analysis_metrics_filter`(
     	p_startTmpstmp 		BIGINT,
     	p_endTmpstmp 		BIGINT,
     	p_domainId 			INT,
     	p_agentId 			TEXT,
     	p_offset 			INT,
     	p_Limit 		    INT	
     )
sp_return:begin
                    
			DECLARE v_offset INT;	 					DECLARE v_CurrentStartTmpstmp BIGINT;		DECLARE v_CurrentEndTmpstmp BIGINT;			DECLARE v_PrevStartTmpstmp BIGINT;				DECLARE v_PrevEndTmpstmp BIGINT; 
			DECLARE v_TmpstmpInterval BIGINT;			DECLARE v_CurTotalCount INT; 				DECLARE v_PrevTotalCount INT; 				DECLARE v_DiffTotalPercent INT; 				DECLARE v_CurTotalSLA INT; 
			DECLARE v_PrevTotalSLA INT; 				DECLARE v_DiffTotalSLAPercent INT; 			DECLARE v_CurTotalSLA1 INT; 				DECLARE v_PrevTotalSLA1 INT; 					DECLARE v_DiffTotalSLA1Percent INT; 
			DECLARE v_CurMissedChats INT; 				DECLARE v_PrevMissedChats INT; 				DECLARE v_DiffMissedChatsPercent INT; 		DECLARE v_CuransweredSLACount INT; 				DECLARE v_PrevansweredSLACount INT; 
			DECLARE v_DiffansweredSLAPercent INT; 		DECLARE v_CurSLAbreachedCount INT; 			DECLARE v_PrevSLAbreachedCount INT; 		DECLARE v_DiffSLAbreachedPercent INT; 			DECLARE v_CurChatTypeCount INT; 
			DECLARE v_PrevChatTypeCount INT; 			DECLARE v_DiffChatTypePercent INT; 			DECLARE v_Counts INT;						DECLARE v_agentName VARCHAR(250);				DECLARE v_SL1 INT;
			DECLARE v_SL2 INT;							DECLARE v_SL3 INT;							DECLARE v_SL4 INT;							DECLARE v_SL5 INT;								DECLARE v_SL6 INT;
			DECLARE v_TotalSLA INT;						DECLARE v_MissedChats INT;					DECLARE v_SLAAchieved INT;					DECLARE v_SLAbreached INT;						DECLARE v_preReceivedChats INT;
			DECLARE v_currentTotalChatCount INT;		DECLARE v_previousTotalChatCount INT;		DECLARE v_CurrentAnsweredSLACount INT;		DECLARE v_PreviousAnsweredSLACount INT;			DECLARE v_CurrentSLAbreachedCount INT;
			DECLARE v_PreviousSLAbreachedCount INT;
                    
      				SET v_offset =  p_Limit * p_offset; 
      
      				IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
      				IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
      
      				SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
      				SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
      				SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
     
   					DROP TEMPORARY TABLE IF EXISTS temp_agentIds;	CREATE TEMPORARY TABLE temp_agentIds(agentId INT);
					CALL split(p_agentId,','); INSERT INTO temp_agentIds(agentId) SELECT Items FROM tt_Split_temptable;
   
					

					DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
					CREATE TEMPORARY TABLE temp_AllagentId
					SELECT UserID,UserName,ext FROM tb_User WHERE domainId = p_domainId ; 
                    
					DROP TEMPORARY TABLE IF EXISTS tt_WhatsappHistory; 
					CREATE TEMPORARY TABLE tt_WhatsappHistory AS 	    	
					SELECT		WH.sessionStartTime 		  
							,	WDH.agentId                  
							,	Q.name
							,	WH.WhatsappHistoryId 
							,	WDH.Duration
							,	WDH.IsMissed
							,	WH.IsInBound
					FROM 	tb_WhatsappHistory 			WH
					JOIN 	tb_WhatsappDurationHistory	WDH		ON WH.WhatsappHistoryId 	= WDH.WhatsappHistoryId
					LEFT JOIN 	queue					Q		ON WDH.QueueId			= Q.qid  
					WHERE 	WH.domainId 			= p_domainId	
					AND 	IFNULL(WDH.IsBot,0) 	= 0
					AND 	WH.sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_CurrentEndTmpstmp   
                    AND		(WDH.agentId in (select agentId from temp_agentIds) or ifnull(p_agentId,'')='');
					

                      
      				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory; 
      				CREATE TEMPORARY TABLE temp_WhatsappHistory AS
      				SELECT		sessionStartTime														AS sessionStartTime
							,	agentId 																AS agentId
							,	CASE WHEN `name` IS NOT NULL THEN `name` ELSE 'Default Queue' END 		AS queueName
							,	WhatsappHistoryId 
							,	sessionStartTime > 0													AS chatDuration
							,	Duration												      			AS Duration
							,	IsMissed
							,	IsInBound
     				FROM 	tt_WhatsappHistory
      				WHERE 	sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;
                          
      				DROP TEMPORARY TABLE IF EXISTS temp_prev_ChatHistory; 
      				CREATE TEMPORARY TABLE temp_prev_ChatHistory AS 	    	
      				SELECT	sessionStartTime															AS sessionStartTime
						,	agentId
     					,	CASE WHEN `name` IS NOT NULL THEN `name` ELSE 'Default Queue' END			AS queueName   
      					,	WhatsappHistoryId 
      					,	sessionStartTime > 0                                               			AS chatDuration
      					,	Duration												      				AS Duration
      					,	IsMissed
      					,	IsInBound
     				FROM 	tt_WhatsappHistory
     				WHERE 	sessionStartTime  BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
                 
      				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_calc; 
      				CREATE TEMPORARY TABLE temp_WhatsappHistory_calc AS 	     
      				SELECT 	
     					a.sessionStartTime 				       										                                    AS 'sessionStartTime'
     					,a.agentId																										AS agentId
     					,CASE WHEN a.queueName IS NOT NULL THEN a.queueName ELSE 'Default Queue' END									AS queueName
     					,a.WhatsappHistoryId 																							AS WhatsappHistoryId
     					,SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															AS Answered
     					,SUM(a.Duration)                                                                                                AS totalDuration
     					,SUM(CASE WHEN a.chatDuration BETWEEN 0 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	AS  SL1
     					,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)				AS  SL2
     					,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        		AS  SL3
     					,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL4
     					,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL5
     					,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL6
     					,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               AS  TotalSLA
     					,sum(case when a.IsMissed =1 then 1 else 0 end)																	AS  MissedChats
     					,sum(case when a.sessionStartTime >0 then 1 else 0 end)															AS  ReceivedChats
      				FROM temp_WhatsappHistory a   
      				GROUP BY a.sessionStartTime,a.agentId,a.queueName,a.chatDuration,a.WhatsappHistoryId,a.IsMissed ;
         
      				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_prev_calc; 
      				CREATE TEMPORARY TABLE temp_WhatsappHistory_prev_calc AS 	     
      				SELECT 	
						a.sessionStartTime 				       										                                    AS 'sessionStartTime'          
						,a.agentId																										AS agentId
						,a.queueName																									AS queueName																                                  
						,a.WhatsappHistoryId																							AS WhatsappHistoryId 
						,SUM(CASE WHEN a.chatDuration > 0 THEN 1 ELSE 0 END) 															AS Answered
						,SUM(a.Duration)                                                                                                AS totalDuration
						,SUM(CASE WHEN a.chatDuration BETWEEN 0 AND  5 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               	AS  SL1
						,SUM(CASE WHEN a.chatDuration BETWEEN 6  AND 10 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)         	 	AS  SL2
						,SUM(CASE WHEN a.chatDuration BETWEEN 11 AND 15 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)        		AS  SL3
						,SUM(CASE WHEN a.chatDuration BETWEEN 16 AND 20 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL4
						,SUM(CASE WHEN a.chatDuration BETWEEN 21 AND 25 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL5
						,SUM(CASE WHEN a.chatDuration BETWEEN 26 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)          		AS  SL6
						,SUM(CASE WHEN a.chatDuration BETWEEN  1 AND 30 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)               AS  TotalSLA
						,sum(case when a.IsMissed =1 then 1 else 0 end)																	AS  MissedChats
						,sum(case when a.sessionStartTime>0 then 1 else 0 end)															AS  ReceivedChats
      				FROM temp_prev_ChatHistory a   
      				GROUP BY  a.sessionStartTime,a.agentId,a.queueName,a.chatDuration,a.WhatsappHistoryId,a.IsMissed ;
         
      				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_calc1; 
      				CREATE TEMPORARY TABLE temp_WhatsappHistory_calc1 AS 	     
      				SELECT 	
						a.sessionStartTime 				       										                                                       
						,a.agentId
						,a.queueName														
						,case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
						,a.WhatsappHistoryId 
						,a.totalDuration
						,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
						, sum(SL1)																															AS SL1
						, sum(SL2)                                                                                                                          AS SL2
						, sum(SL3)                                                                                                                          AS SL3
						, sum(SL4)                                                                                                                          AS SL4
						,sum(SL5)                                                                                                                           AS SL5
						,sum(SL6)                                                                                                                           AS SL6
						,a.MissedChats       
						,sum(a.ReceivedChats)  																												AS ReceivedChats
						,(sum(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)/sum(a.ReceivedChats))*100  																AS answeredSLA
						,100- ((sum(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)/sum(a.ReceivedChats))*100) 														AS SLAbreached
      				FROM temp_WhatsappHistory_calc    a 
      				GROUP BY a.sessionStartTime,a.agentId,a.queueName,a.Answered,a.WhatsappHistoryId,a.sessionStartTime,a.totalDuration,a.MissedChats; 
      
      
                      select sum(ReceivedChats) INTO v_preReceivedChats from temp_WhatsappHistory_prev_calc;
      
      				DROP TEMPORARY TABLE IF EXISTS temp_WhatsappHistory_prev_calc1; 
      				CREATE TEMPORARY TABLE temp_WhatsappHistory_prev_calc1 AS 	     
      				SELECT 	
						a.sessionStartTime 				       										                                                       
						,a.agentId
						,a.queueName														
						, case when a.Answered=1 then 'Answered' else 0 end  AS ChatType
						,a.WhatsappHistoryId 
						,a.totalDuration
						,SUM(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)                                     	 												    AS TotalSLA
						,sum(SL1)																															AS SL1
						,sum(SL2)                                                                                                                           AS SL2
						,sum(SL3)                                                                                                                           AS SL3
						,sum(SL4)                                                                                                                           AS SL4
						,sum(SL5)                                                                                                                           AS SL5
						,sum(SL6)                                                                                                                           AS SL6
						,a.MissedChats       
						,sum(a.ReceivedChats)  																												AS ReceivedChats
						,(sum(a.SL1+a.SL2+a.SL3+a.SL4+a.SL5+a.SL6)/sum(v_preReceivedChats))*100  															AS answeredSLA
					
      				FROM temp_WhatsappHistory_prev_calc    a 
      				GROUP BY a.sessionStartTime,a.agentId,a.queueName,a.Answered,a.WhatsappHistoryId,a.totalDuration,a.MissedChats;  

                    
                
               
    				SELECT  COUNT(WhatsappHistoryId),	SUM(TotalSLA), SUM(MissedChats),SUM(ReceivedChats),sum(answeredSLA)/count(WhatsappHistoryId),sum(SLAbreached)/count(WhatsappHistoryId)
    				INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats, v_currentTotalChatCount, v_CurrentAnsweredSLACount,v_CurrentSLAbreachedCount
    				FROM 	temp_WhatsappHistory_calc1
    				WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
                    
    				SELECT 	COUNT(WhatsappHistoryId),SUM(TotalSLA), SUM(MissedChats),SUM(ReceivedChats),sum(answeredSLA),(100- sum(answeredSLA)) 
    				INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats,v_previousTotalChatCount,v_PreviousAnsweredSLACount,v_PreviousSLAbreachedCount
    				FROM	temp_WhatsappHistory_prev_calc1
    				WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
    
            
                       
                      SET 	v_DiffTotalPercent 		    = (IFNULL(v_CurTotalCount,0) - v_PrevTotalCount) / IF(IFNULL(v_PrevTotalCount,0)=0,1,v_PrevTotalCount) * 100 
    					,  	v_DiffansweredSLAPercent  	= CASE WHEN v_PreviousAnsweredSLACount = 0 THEN 0 ELSE (IFNULL(v_CurrentAnsweredSLACount, 0) - v_PreviousAnsweredSLACount) / IF(IFNULL(v_PreviousAnsweredSLACount,0)=0,1,v_PreviousAnsweredSLACount) * 100 END
    					,  	v_DiffSLAbreachedPercent  	= CASE WHEN v_PreviousSLAbreachedCount = 0 THEN 0 ELSE (IFNULL(v_CurrentSLAbreachedCount, 0) - v_PreviousSLAbreachedCount) / IF(IFNULL(v_PreviousSLAbreachedCount,0)=0,1,v_PreviousSLAbreachedCount) * 100 END;        
    
                      	SELECT * FROM temp_AllagentId;
                       
                      	SELECT 
                               IFNULL(v_CurrentAnsweredSLACount,0)       AS 'CurrentAnsweredSLACount',
                               IFNULL(v_DiffansweredSLAPercent,0)        AS 'DiffAnsweredSLAPercent',
                               IFNULL(v_CurrentSLAbreachedCount,0)       AS 'CurrentSLAbreachedCount',
                               IFNULL(v_DiffSLAbreachedPercent ,0)       AS 'DiffSLAbreachedPercent';  
                               
    					select 		SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6),SUM(TotalSLA),SUM(MissedChats),SUM(answeredSLA)/count(WhatsappHistoryId) SLAAchieved, sum(SLAbreached)/count(WhatsappHistoryId) SLAbreached
    								INTO v_SL1, v_SL2, v_SL3, v_SL4, v_SL5, v_SL6, v_TotalSLA, v_MissedChats, v_SLAAchieved, v_SLAbreached
    					from temp_WhatsappHistory_calc1;
                        
						select 	'All Agents'	 																					AS agentName
								,'Answered' 																						AS ChatType
								,IFNULL(v_SL1,0)																					AS SL1
								,IFNULL(v_SL2,0) 																					AS SL2
								,IFNULL(v_SL3,0) 																					AS SL3
								,IFNULL(v_SL4,0) 																					AS SL4
								,IFNULL(v_SL5,0) 																					AS SL5
								,IFNULL(v_SL6,0)																					AS SL6
								,IFNULL(v_TotalSLA,0) 																				AS Total
								,IFNULL(v_MissedChats,0) 																			AS MissedChats    
								,IFNULL(abs(v_SLAAchieved),0)																		AS SLAAchieved 
								,IFNULL(abs(v_SLAbreached),0)																		AS SLAbreached
    					union all	
						SELECT DISTINCT(queueName) 																					AS agentName
								,'Answered' 																						AS ChatType
								,IFNULL(SUM(SL1),0)																					AS SL1
								,IFNULL(SUM(SL2),0)																					AS SL2
								,IFNULL(SUM(SL3),0)																					AS SL3
								,IFNULL(SUM(SL4),0)																					AS SL4
								,IFNULL(SUM(SL5),0)																					AS SL5
								,IFNULL(SUM(SL6),0)																					AS SL6
								,IFNULL(SUM(TotalSLA),0)																			AS Total
								,IFNULL(SUM(MissedChats),0)																			AS MissedChats   
								,IFNULL(abs(SUM(answeredSLA)/count(WhatsappHistoryId)),0) 											AS SLAAchieved
								,IFNULL(abs(SUM(SLAbreached)/count(WhatsappHistoryId)),0)											AS SLAbreached
						from temp_WhatsappHistory_calc1
						group by queueName;
    
                     END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_WhatApp_agent_servicelevel_analysis_metrics_filter_1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `up_WhatApp_agent_servicelevel_analysis_metrics_filter_1`(
                   		p_startTmpstmp 		BIGINT,
                       	p_endTmpstmp 		BIGINT,
                       	p_domainId 			INT,
                       	p_agentId 			TEXT,
 						p_offset 			INT,
						p_Limit 		    INT	
                   	)
sp_return:begin
          
 			DECLARE v_offset 					INT;	  	
 			DECLARE v_CurrentStartTmpstmp 		BIGINT;
 			DECLARE v_CurrentEndTmpstmp 		BIGINT;
 			DECLARE v_PrevStartTmpstmp 			BIGINT;
 			DECLARE v_PrevEndTmpstmp 			BIGINT; 
 			DECLARE v_TmpstmpInterval			BIGINT;	
 			
 			DECLARE v_CurTotalCount 				INT;        
 			DECLARE  v_PrevTotalCount 			    INT;                    
 			DECLARE v_DiffTotalPercent 		        INT;     
 			
 			DECLARE  v_CurTotalSLA                  INT; 
 			DECLARE  v_PrevTotalSLA             	INT; 
 			DECLARE  v_DiffTotalSLAPercent      	INT; 
 		
 			DECLARE v_PretotalDurationCount          INT;
 			DECLARE v_CurrenttotalDurationCount      INT;  
 		
 			DECLARE  v_CurMissedChats                INT; 
 			DECLARE  v_PrevMissedChats               INT; 
 			DECLARE  v_DiffMissedChatsPercent        INT; 
         
           
  			 DECLARE  v_CurSL1               		INT; 
              DECLARE  v_PrevSL1              		INT; 
              DECLARE  v_DiffSL1Percent       		INT; 
           
    		     DECLARE  v_CurSL2               		INT; 
              DECLARE  v_PrevSL2              		INT; 
              DECLARE  v_DiffSL2Percent       		INT;  
           
    		     DECLARE  v_CurSL3               		INT; 
              DECLARE  v_PrevSL3              		INT; 
              DECLARE  v_DiffSL3Percent       		INT;  
           
  			 DECLARE  v_CurSL4               		INT; 
              DECLARE  v_PrevSL4              		INT; 
              DECLARE  v_DiffSL4Percent       		INT;  
           
  			 DECLARE  v_CurSL5               		INT; 
              DECLARE  v_PrevSL5              		INT; 
              DECLARE  v_DiffSL5Percent       		INT;    
        		
        	     DECLARE  v_CurSL6               	    INT; 
              DECLARE  v_PrevSL6              		INT; 
              DECLARE  v_DiffSL6Percent       		INT; 
          
 			DECLARE  v_CuransweredSLACount        	INT; 
 			DECLARE  v_PrevansweredSLACount       	INT; 
 			DECLARE  v_DiffansweredSLAPercent     	INT; 
 			
 			DECLARE  v_CurabandonedSLACount       	INT; 
 			DECLARE  v_PrevabandonedSLACount      	INT; 
 			DECLARE  v_DiffabandonedSLAPercent    	INT; 
 			
 			DECLARE  v_CurSLAbreachedCount        	INT; 
 			DECLARE  v_PrevSLAbreachedCount       	INT; 
 			DECLARE  v_DiffSLAbreachedPercent     	INT; 
              
              
			  DECLARE  v_CurChatTypeCount             INT; 
              DECLARE  v_PrevChatTypeCount            INT; 
              DECLARE  v_DiffChatTypePercent          INT;  
              
       
 			 DECLARE  v_CurOverdueCount                 	INT;          
                  
         	 SET v_offset =  p_Limit * p_offset; 
            
            	IF IFNULL(p_startTmpstmp,0)= 0 THEN SET v_CurrentStartTmpstmp = UNIX_TIMESTAMP(DATE_SUB(NOW(), INTERVAL + 1 DAY))*1000; ELSE SET v_CurrentStartTmpstmp = p_startTmpstmp; END IF; 
            	IF IFNULL(p_endTmpstmp,0) = 0  THEN SET v_CurrentEndTmpstmp = UNIX_TIMESTAMP(NOW())*1000; ELSE SET v_CurrentEndTmpstmp = p_endTmpstmp; END IF;  									
            	
          	SET v_TmpstmpInterval = v_CurrentEndTmpstmp - v_CurrentStartTmpstmp;
          
          	SET v_PrevEndTmpstmp 	= v_CurrentStartTmpstmp - 1;
          	SET v_PrevStartTmpstmp 	= v_PrevEndTmpstmp - v_TmpstmpInterval;
            		
            	DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
            	CALL split(p_agentId,',');	INSERT INTO temp_agentIDs(agentId) SELECT Items FROM tt_Split_temptable;  
    		    DROP TEMPORARY TABLE IF EXISTS temp_agentIDs;	    CREATE TEMPORARY TABLE temp_agentIDs(agentId BIGINT);
      		DROP TEMPORARY TABLE IF EXISTS temp_dispositionIds;	CREATE TEMPORARY TABLE temp_dispositionIds(dispositionId INT);
      
         
 							DROP TEMPORARY TABLE IF EXISTS temp_AvailableDisposition;
 							CREATE TEMPORARY TABLE temp_AvailableDisposition 
                        		(    DispositionId 			INT
                        			,DispositionStatus 		VARCHAR(100)
                        			,DispositionCategory	TINYINT
                        		); 
                                
                        		INSERT INTO temp_AvailableDisposition 
                        		SELECT 	did 			DispositionId
                        			,	dispositionName	DispositionStatus
                        			,	CASE WHEN dispositionName = 'Opened'	THEN 2
                        				WHEN dispositionName IN ('Resolved','Unresolved','Closed','Follow-up','Transferred') THEN 3
                        				WHEN dispositionName = 'Disconnected'         THEN 4
                 					    WHEN dispositionName = 'Resolved'             THEN 5
                        				END 			DispositionCategory
                        		FROM 	disposition_status
                        		WHERE 	domainId	= p_domainId;          
                              
  							SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED ;    
  							DROP TEMPORARY TABLE IF EXISTS temp_AllagentId;	
  							CREATE TEMPORARY TABLE temp_AllagentId
  							SELECT 	UserID,UserName 
  							FROM 	tb_User 
  							WHERE 	domainId 	= p_domainId; 
                
                           DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory; 
                  	      CREATE TEMPORARY TABLE temp_WhatAppHistory AS 	    	
 									SELECT	 CAST(FROM_UNIXTIME(SH.sessionStartTime/1000)  AS DATE) 		                			AS SessionDate
 									,U.UserID                                                                  							AS agentID
 									,U.UserName													      		   							AS agentName     
 									,SH.WhatsappHistoryId							
 									,SH.sessionStartTime							
 									,SDH.Duration                                                       	   							 AS chatDuration                 
 									,SDH.Duration												      	       							 AS Duration
 									,CASE WHEN t_D.DispositionCategory = 3 THEN 1 ELSE 0 END                   							 AS Answered
 									,CASE WHEN t_D.DispositionCategory = 4 THEN 1 ELSE 0 END 		           							 AS Abandoned
                                    
                                     , null																							    AS  Overdue
 								FROM 	tb_WhatsappHistory 		SH
 								JOIN 	tb_WhatsappDurationHistory		SDH			ON SH.WhatsappHistoryId 	= SDH.WhatsappHistoryId     
 								LEFT JOIN 	tb_User						U			ON SDH.AgentId			= U.UserID  
 								LEFT JOIN 	temp_agentIDs 				t_A 		ON SDH.AgentId		    = t_A.agentId  
 								LEFT JOIN temp_AvailableDisposition		t_D			ON SH.dispositionId	= t_D.DispositionId
 								LEFT JOIN 	disposition_status			DS			ON DS.did			    = SH.dispositionId AND DS.domainId = SH.domainId
 								WHERE 	SH.domainId 		= p_domainId		
 								AND 	SH.sessionStartTime  BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp 
 								AND 	(IFNULL(p_agentId,'') 	= '' OR (IFNULL(p_agentId,'') <> '' AND t_A.agentId IS NOT NULL));                
                
 							DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_calc; 
                           	CREATE TEMPORARY TABLE temp_WhatAppHistory_calc AS 	     
 							SELECT
       						a.SessionDate 																										AS 'Date',
       						a.agentID,
       						a.agentName,
       						a.WhatsappHistoryId,
       						a.sessionStartTime,
 							(a.Answered+a.Abandoned)                             															    AS ChatType,  
       						SUM(a.Duration) 																									AS totalDuration,
       						SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 5000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)      				AS SL1,
       						SUM(CASE WHEN a.chatDuration BETWEEN 5001 AND 10000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)  				AS SL2,
       						SUM(CASE WHEN a.chatDuration BETWEEN 10001 AND 15000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL3,
       						SUM(CASE WHEN a.chatDuration BETWEEN 15001 AND 20000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL4,
       						SUM(CASE WHEN a.chatDuration BETWEEN 20001 AND 25000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL5,
       						SUM(CASE WHEN a.chatDuration BETWEEN 25001 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END) 				AS SL6,
       						SUM(CASE WHEN a.chatDuration BETWEEN 1 AND 30000 AND a.chatDuration IS NOT NULL THEN 1 ELSE 0 END)     				AS TotalSLA,
       						SUM(CASE WHEN a.chatDuration > 30000 THEN 1 ELSE 0 END) 															AS MissedChats,
       						SUM(CASE WHEN a.Overdue = 'Aborted' THEN 1 ELSE 0 END)  															AS Overdue
       						FROM temp_WhatAppHistory a
       						GROUP BY a.SessionDate,a.agentID,a.agentName,a.WhatsappHistoryId,a.sessionStartTime,a.Answered,a.Abandoned; 
                
                             DROP TEMPORARY TABLE IF EXISTS temp_WhatAppHistory_calc1; 
 							CREATE TEMPORARY TABLE temp_WhatAppHistory_calc1 AS 
                             SELECT
                             a.Overdue,
                             count(1),
                             a.Date,
                             a.agentID,
 							a.agentName,
 							a.WhatsappHistoryId,
 							a.sessionStartTime,
                             a.ChatType,
                             a.totalDuration,
                             a.SL1,
                             a.SL2,
                             a.SL3,
                             a.SL4,
                             a.SL5,
                             a.SL6,
                             a.TotalSLA,
                             a.MissedChats,
     						SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats)) * 10 END)                    AS answeredSLA,
     					    SUM(CASE WHEN (a.TotalSLA + a.MissedChats) = 0 THEN 1 ELSE (a.TotalSLA / (a.TotalSLA + a.MissedChats) * 100) END)                   AS abandonedSLA,    
     						 SUM(CASE WHEN Overdue > 0 THEN 1 ELSE 0 END) / COUNT(1) * 100                                                                       AS SLAbreached							                                 
                           FROM temp_WhatAppHistory_calc a  
                           GROUP BY a.Overdue,a.Date,a.agentID,a.agentName,a.WhatsappHistoryId,a.sessionStartTime,a.ChatType,a.totalDuration,a.SL1, a.SL2,a.SL3,a.SL4,a.SL5,a.SL6,a.TotalSLA,a.MissedChats;
                   
                   select * from temp_WhatAppHistory_calc;
                    select * from temp_WhatAppHistory_calc1;
                   
 			SELECT  COUNT(WhatsappHistoryId),	SUM(TotalSLA), SUM(MissedChats) ,sum(ChatType)              														                     				 
 			INTO 	v_curTotalCount ,v_CurTotalSLA, v_CurMissedChats ,v_CurChatTypeCount                           														                      					
 			FROM 	temp_WhatAppHistory_calc1
 			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
           
           	SELECT 	COUNT(WhatsappHistoryId),SUM(TotalSLA), SUM(MissedChats) ,sum(ChatType)                       																								 
           	INTO 	v_PrevTotalCount, v_PrevTotalSLA,v_PrevMissedChats ,v_PrevChatTypeCount                                 														 										
           	FROM	temp_WhatAppHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;                 
      
             SELECT 	SUM(IFNULL(Overdue, 0))
           	INTO 	v_CurOverdueCount 
            	FROM	temp_WhatAppHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;
           
         	    SELECT 	SUM(IFNULL(totalDuration, 0))
           	INTO 	v_CurrenttotalDurationCount 
  			FROM	temp_WhatAppHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
              
  			SELECT 	SUM(IFNULL(totalDuration, 0))
           	INTO 	v_PretotalDurationCount 
   			FROM	temp_WhatAppHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;   
              
   			SELECT  SUM(SL1),SUM(SL2),SUM(SL3),SUM(SL4), SUM(SL5), SUM(SL6)
   			INTO    v_CurSL1 ,v_CurSL2 ,v_CurSL3,v_CurSL4,v_CurSL5, v_CurSL6 
   			FROM 	temp_WhatAppHistory_calc1
   			WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;  
           
         	SELECT  SUM(IFNULL(SL1, 0)),SUM(IFNULL(SL2, 0)),SUM(IFNULL(SL3, 0)),SUM(IFNULL(SL4, 0)),SUM(IFNULL(SL5, 0)),SUM(IFNULL(SL6, 0))
         	INTO    v_PrevSL1 ,v_PrevSL2, v_PrevSL3 ,v_PrevSL4,v_PrevSL5, v_PrevSL6
            	FROM	temp_WhatAppHistory_calc1
           	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;             
              
   		SELECT 	SUM(IFNULL(answeredSLA, 0))
        	INTO 	v_PrevansweredSLACount 
        	FROM	temp_WhatAppHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
 		SELECT 	SUM(IFNULL(answeredSLA, 0))
        	INTO 	v_CuransweredSLACount 
   		FROM	temp_WhatAppHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp; 
        
 		SELECT 	SUM(IFNULL(abandonedSLA, 0))
        	INTO 	v_PrevabandonedSLACount 
        	FROM	temp_WhatAppHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
        
 		SELECT 	SUM(IFNULL(abandonedSLA, 0))
        	INTO 	v_CurabandonedSLACount 
  		FROM	temp_WhatAppHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;             
              
              
 		SELECT 	SUM(IFNULL(SLAbreached, 0))
        	INTO 	v_PrevSLAbreachedCount 
        	FROM	temp_WhatAppHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_PrevStartTmpstmp AND v_PrevEndTmpstmp;
        
 		SELECT 	SUM(IFNULL(SLAbreached, 0))
        	INTO 	v_CurSLAbreachedCount 
       	FROM	temp_WhatAppHistory_calc1
        	WHERE	sessionStartTime BETWEEN v_CurrentStartTmpstmp AND v_CurrentEndTmpstmp;            
         
 		SET v_PrevTotalCount       = CASE WHEN v_PrevTotalCount = 0        then null else     v_PrevTotalCount        end; 
  		SET v_PrevansweredSLACount = CASE WHEN v_PrevansweredSLACount = 0  then null else     v_PrevansweredSLACount  end;
   		SET v_PrevabandonedSLACount= CASE WHEN v_PrevabandonedSLACount = 0 then null else     v_PrevabandonedSLACount end;
  		SET v_PrevSLAbreachedCount = CASE WHEN v_PrevSLAbreachedCount = 0  then null else     v_PrevSLAbreachedCount  end;
     
 		SET v_DiffTotalPercent 		= (v_CurTotalCount - v_PrevTotalCount) / v_PrevTotalCount * 100  
    	,   v_DiffansweredSLAPercent  	= (v_CuransweredSLACount- v_PrevansweredSLACount ) / v_PrevansweredSLACount  * 100
   	,  v_DiffabandonedSLAPercent	= (v_CurabandonedSLACount - v_PrevabandonedSLACount ) / v_PrevabandonedSLACount  * 100
 	,  v_DiffSLAbreachedPercent  	= (v_CurSLAbreachedCount - v_PrevSLAbreachedCount) / v_PrevSLAbreachedCount * 100; 
         
         SELECT * FROM temp_AllagentId;
         
              	SELECT 
         IFNULL(v_CuransweredSLACount,0)          AS 'CurrentAnsweredSLACount',
         IFNULL(v_DiffansweredSLAPercent,0)       AS 'DiffAnsweredSLAPercent',
         IFNULL(v_CurabandonedSLACount,0)         AS 'CurrentAbandonedSLACount',
         IFNULL(v_DiffabandonedSLAPercent,0)      AS 'DiffAbandonedSLAPercent',
         IFNULL(v_CurSLAbreachedCount,0)          AS 'CurrentSLAbreachedCount',
         IFNULL(v_DiffSLAbreachedPercent ,0)      AS 'DiffSLAbreachedPercent';     
         
                 SELECT
   				  'All Agents'												   							AS agentName
 				 ,'Answered'                                                   					        AS ChatType
                  ,IFNULL(v_CurSL1,0)                                          							AS SL1
                  ,IFNULL(v_CurSL2,0)                                          							AS SL2
                  ,IFNULL(v_CurSL3,0)                                          							AS SL3
                  ,IFNULL(v_CurSL4,0)                                          							AS SL4
                  ,IFNULL(v_CurSL5,0)                                          							AS SL5
                  ,IFNULL(v_CurSL6,0)                                          							AS SL6
                  ,IFNULL(v_CurTotalSLA,0)                                      							AS Total
 				,IFNULL(v_CurMissedChats,0)                                   						    AS MissedChats           
                  ,0                                                                                     AS SLAAchieved
                  ,0                                                                                     AS SLABreached
   
                 UNION ALL
           	   SELECT 	  
                    U.UserName													                                				AS agentName
                  , b.ChatType
                  , count(b.SL1)
                  , count(b.SL2)
  				 ,count(b.SL3)
  				 , count(b.SL4)
  				 , count(b.SL5)
  				 , count(b.SL6)
                  , sum(b.TotalSLA)
 				 , sum(b.MissedChats)
                  , CASE WHEN sum(b.TotalSLA/b.totalDuration) IS NOT NULL THEN sum(b.TotalSLA/b.totalDuration) ELSE '-' END        AS SLAachieved
                  , sum(b.Overdue)/count(1)                         																  AS SLAbreached
                  FROM temp_WhatAppHistory_calc1 b
                  JOIN temp_WhatAppHistory       a      ON b.WhatsappHistoryId= a.WhatsappHistoryId
  				 JOIN 	temp_AllagentId		    U	   ON a.AgentId	= U.UserID
  			
                  GROUP BY U.UserName,b.MissedChats,b.Overdue,b.ChatType;    
                
 		SELECT CONCAT('agentName', 'ChatType', 'SL1', 'SL2', 'SL3', 'SL4', 'SL5', 'SL6', 'Total', 'MissedChats', 'SLAAchieved', 'SLAbreached') AS  columnName;   
           
         	
            END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `up_WhatApp_Edit_Column_Get_Details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
