CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ur_add_update_tpi_connection_platform`(
  	p_sip_id			INT
  ,	p_domain_id			INT
  ,	p_connection_url	VARCHAR(500)
  ,	p_call_type_id		VARCHAR(50)
  ,	p_token				TEXT
  )
BEGIN
  	DECLARE v_connection_platform_id	INT;
      DECLARE v_call_type_id				INT;
      DECLARE v_curDate					DATETIME DEFAULT NOW();
      DECLARE v_err_code					TINYINT;
      DECLARE v_err_msg					VARCHAR(200);
      
      SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
      SELECT 	TypeCodeID 
      INTO	v_call_type_id
      FROM 	TypeCode
      WHERE 	TypeCode	= p_call_type_id
      AND 	TypeGroupID	= 1002; 
      
      SELECT 	connection_platform_id
      INTO 	v_connection_platform_id
      FROM 	ur_tpi_connection_platform
      WHERE 	sip_id			= p_sip_id
      AND 	domain_id		= p_domain_id
      AND 	connection_url	= p_connection_url;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
      
      IF v_connection_platform_id IS NULL
      THEN
  		INSERT INTO ur_tpi_connection_platform
  		(	sip_id			
  		,	domain_id		
  		,	connection_url	
  		,	call_type_id	
  		,	token			
  		,	created_date	
  		,	updated_date	
  		)
          VALUES(
          	p_sip_id		
          ,	p_domain_id		
          ,	p_connection_url
          ,	v_call_type_id	
          ,	p_token			
          ,	v_curDate
          ,	v_curDate			
          );
          
          SET v_connection_platform_id 	= last_insert_id()
  		,	v_err_code					= 0
  		,	v_err_msg					= 'Added connection platform successfully';
  	ELSE
  		UPDATE 	ur_tpi_connection_platform
          SET 	call_type_id	= v_call_type_id	
  			,	token			= p_token			
  			,	updated_date	= v_curDate
          WHERE 	sip_id			= p_sip_id		
          AND 	domain_id		= p_domain_id		
          AND 	connection_url	= p_connection_url;
          
          SET v_err_code	= 0
  		,	v_err_msg	= 'Added connection platform successfully';
      END IF;
      
      SELECT v_err_code AS 'err_code', v_err_msg AS 'err_msg';
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ur_get_tpi_connection_platform` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `ur_get_tpi_connection_platform`(
  	p_sip_id			INT
  ,	p_connection_url	VARCHAR(500)
  )
BEGIN
  	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
      SELECT 	cp.sip_id			
  		,	cp.domain_id		
  		,	cp.connection_url	
          ,	cp.call_type_id
  		,	ct.TypeCode	AS call_type
  		,	cp.token			
      FROM 	ur_tpi_connection_platform	cp
      JOIN 	TypeCode					ct	ON  cp.call_type_id = ct.TypeCodeID	
      WHERE 	cp.sip_id			= p_sip_id
      AND 	cp.connection_url	= p_connection_url;
      SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
