CREATE DEFINER=`dbdev`@`%` PROCEDURE `videomeet_create_message_details`(
	p_domainId 		int, 
	p_sessionId 	varchar(250), 
	p_Message 		json,
	p_agentextn 	int
   )
Begin
   
			declare v_errcode 					int;
			declare v_errmsg 					varchar(55);
			declare v_AgentId 					bigint;
			declare v_VideoHistoryId 			bigint;
			declare v_VideoDurationHistoryId 	bigint;
			declare v_prev_Message 				json;
			declare v_merged_msg 				json;

             if p_agentextn is not null then
    			select  UserID into v_AgentId from tb_User where domainId = p_domainId and ext = p_agentextn limit 1;
            End if;
    
   		sp_exit:Begin
   			if p_domainId is null or p_domainId = 0 then
   				set v_errcode = -1;
   				set v_errmsg = 'DomainId should not be empty';
   				leave sp_exit;
   			End if;
             
             if p_agentextn is null or p_agentextn=0 then
   				set v_errcode = -1;
   				set v_errmsg = 'Agentextn should not be empty or null';
   				leave sp_exit;
   			End if;
   	
   			if not exists (select 1 from tb_VideoHistory a where a.sessionId = p_sessionId limit 1) then
   				set v_errcode = -1;
   				set v_errmsg = 'videomeet details not available';
   				leave sp_exit;
   			End if;
               
			select VideoHistoryId into v_VideoHistoryId from tb_VideoHistory where sessionId = p_sessionId limit 1;
			select VideoDurationHistoryId into v_VideoDurationHistoryId from tb_VideoDurationHistory where VideoHistoryId = v_VideoHistoryId and AgentId = v_AgentId limit 1;                      
            
            IF v_VideoDurationHistoryId IS NULL
            THEN
				SET v_errcode = -1;
   				SET v_errmsg = 'Given Agent did not attend this videomeet';
   				LEAVE sp_exit;
            END IF;

			if not exists(select 1 from tb_VideoMessage where VideoHistoryId = v_VideoHistoryId limit 1)then
			insert into tb_VideoMessage(VideoHistoryId,Message,createdAt,VideoDurationHistoryId)
			values(v_VideoHistoryId,p_Message,now(),v_VideoDurationHistoryId);
                   
   				else if exists(select 1 from tb_VideoMessage where VideoHistoryId = v_VideoHistoryId and VideoDurationHistoryId = v_VideoDurationHistoryId limit 1)then
   
   					update tb_VideoMessage a
   					set a.Message = if(a.Message is null,p_Message,JSON_ARRAY_APPEND(a.Message, '$', p_Message)),a.updatedAt = now()
   					where a.VideoHistoryId = v_VideoHistoryId and VideoDurationHistoryId = v_VideoDurationHistoryId;
   				else
   						
   					select Message into v_prev_Message from tb_VideoMessage where VideoHistoryId = v_VideoHistoryId order by ifnull(updatedAt,createdAt) desc limit 1;
   		 
   					set v_merged_msg =  JSON_ARRAY_APPEND(v_prev_Message, '$', p_Message);
   						   
   					insert into tb_VideoMessage(VideoHistoryId,Message,createdAt,VideoDurationHistoryId)
   					values(v_VideoHistoryId,v_merged_msg,now(),v_VideoDurationHistoryId);
   				End if;    
               End if;
           
   			if row_count() > 0 then
   				set v_errcode = 0;
   				set v_errmsg = 'Message inserted successfully';
   				leave sp_exit;
   			end if;
   		End;
   			
   		select v_errcode as errcode, v_errmsg as errmsg,v_VideoHistoryId as VideoHistoryId;
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
