CREATE DEFINER=`dbdev`@`%` PROCEDURE `videomeet_insert_sendLink_dtl`(	
	 p_domainId				int
	,p_meetingId			varchar(50)
	,p_queueType			varchar(500)
	,p_isEmail				tinyint
	,p_emailId				varchar(250)
	,p_isSms				tinyint
	,p_smsNumber			varchar(50)
	,p_customerId			int
	,p_channelType			varchar(20)
	,p_channelHistoryId		bigint
	,p_createdBy			bigint
)
begin

	DECLARE v_vid 			INT;
    DECLARE v_curDate 		DATETIME;
    DECLARE v_ExpireTime 	DATETIME;
    
    DECLARE v_isLinkExpiry 		TINYINT;
    DECLARE v_expiryUnit 		TINYINT;
    DECLARE v_expiryUnitType 	VARCHAR(10);
    
    DECLARE v_errcode 	INT DEFAULT -1;
    DECLARE v_errmsg 	VARCHAR(50) DEFAULT 'Sendlink insert failed';
    
    SET v_curDate = NOW();

	SELECT 	vid INTO v_vid
    FROM 	videomeet_master_dtl
    WHERE 	domainId  = p_domainId
    AND		meetingId = p_meetingId;

	SELECT isLinkExpiry,expiryUnit,expiryUnitType INTO v_isLinkExpiry,v_expiryUnit,v_expiryUnitType
    FROM tb_videoCallConfiguration
    WHERE domainId = p_domainId ;
	
    IF v_isLinkExpiry = 1
    THEN 
    SELECT 	CASE WHEN v_expiryUnitType = 'Hours' THEN DATE_ADD(NOW(), INTERVAL v_expiryUnit HOUR)
			WHEN v_expiryUnitType = 'Minutes' THEN DATE_ADD(NOW(), INTERVAL v_expiryUnit MINUTE) END INTO v_ExpireTime;
    END IF;

	IF v_vid IS NULL
    THEN
		
        INSERT INTO videomeet_master_dtl(domainId,meetingId,queueType,isEmail,emailId,isSms,smsNumber,expireTime,customerId,channelType,channelHistoryId,createdBy,createdAt,updatedAt)
        VALUES(p_domainId,p_meetingId,p_queueType,p_isEmail,p_emailId,p_isSms,p_smsNumber,IFNULL(v_ExpireTime,0),p_customerId,p_channelType,p_channelHistoryId,p_createdBy,v_curDate,v_curDate);
    
		SET v_errcode 	= 0;
        SET v_errmsg 	= 'Sendlink inserted successfully ';
    
	END IF;
    
    SELECT v_errcode as errcode, v_errmsg as errmsg;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
