CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `whatsappIntegrationCreationDtl`(
    	 p_requestID 			VARCHAR(100)      
       ,p_domainId				INT
    	,p_agentNumber 			VARCHAR(30)
    	,p_customerNumber 		VARCHAR(30)
    	,p_enabled 				VARCHAR(10)
    	,p_status 				VARCHAR(50)
    	
    	,p_sentTimestamp 		BIGINT
    	,p_deliveredTimestamp 	BIGINT
    	,p_readTimetamp 		BIGINT
    	,p_mediajson 			JSON	
    	,p_msgtype 				VARCHAR(50)
    	,p_conversation 		JSON
    	,p_pricing 				JSON
    	,p_customerName 		VARCHAR(30)
    	,p_msgtext 				TEXT
      ,p_receivedTimestamp	bigint
    )
BEGIN
	DECLARE v_errcode 		INT DEFAULT -1;
	DECLARE v_errmsg 		VARCHAR(50) DEFAULT 'Failure';
	DECLARE v_idcol		BIGINT;  
	DECLARE v_CurDate		DATETIME;
       
	SET v_CurDate = NOW();
    
   	SET SESSION TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SELECT 	idcol INTO v_idcol 
	FROM 	whatsapp_Integration_master_dtl 
	WHERE 	requestID collate utf8mb4_0900_ai_ci = p_requestID; 
	SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ ;
       
    	IF v_idcol IS NULL 
       THEN
    		insert into whatsapp_Integration_master_dtl(requestID,domainId,agentNumber,customerNumber,enabled,`status`,`Timestamp`,sentTimestamp,deliveredTimestamp,readTimetamp,mediajson,msgtype,conversation,
    				pricing,createdAt,updateAt,customerName,msgtext,receivedTimestamp)
            values(p_requestID
   				,p_domainId,p_agentNumber,p_customerNumber,p_enabled,p_status,UNIX_TIMESTAMP(NOW()) * 1000,p_sentTimestamp,p_deliveredTimestamp,p_readTimetamp,p_mediajson,p_msgtype,p_conversation,
    				p_pricing,v_CurDate,v_CurDate,p_customerName,p_msgtext,p_receivedTimestamp);
            
            set v_errcode  = 0;
            set v_errmsg  = 'Success : Inserted';
        Else
    		update whatsapp_Integration_master_dtl 
    		SET 	 
    				agentNumber = ifnull(p_agentNumber, agentNumber)
    				,customerNumber = ifnull(p_customerNumber, customerNumber)
    				,enabled = ifnull(p_enabled, enabled)
    				,`status` = ifnull(p_status, `status`)
    				
    				,sentTimestamp = ifnull(p_sentTimestamp, sentTimestamp)
    				,deliveredTimestamp = ifnull(p_deliveredTimestamp, deliveredTimestamp)
    				,readTimetamp = ifnull(p_readTimetamp, readTimetamp)
    				,mediajson  = ifnull(p_mediajson , mediajson )
    				,msgtype  = ifnull(p_msgtype , msgtype )
    				,conversation  = ifnull(p_conversation , conversation )
    				,pricing  = ifnull(p_pricing , pricing ) 				
    				,updateAt = v_CurDate
    				,customerName = ifnull(p_customerName, customerName)
    				,msgtext = ifnull(p_msgtext, msgtext)
    		where 	idcol = v_idcol;
            
   		set v_errcode  = 0;
   		set v_errmsg  = 'Success : Updated';         
	end if;
    
    	select v_errcode as errcode, v_errmsg as errmsg;
End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
