CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `worktual_bot_myaccount_get_otp`(
 searchinfo VARCHAR(100),
  pin VARCHAR(10))
begin
  
     DECLARE v_errcode INT;
     DECLARE v_errmsg VARCHAR(100);
     DECLARE v_now DATETIME(3);
     DECLARE v_Timediff INT; 
     DECLARE v_expiry_time INT; 
     DECLARE v_create_time DATETIME(3);
     sp_exit:
     BEGIN
        set v_errcode = -1;
        set v_errmsg = 'Failure';
        set v_now = CURRENT_TIMESTAMP;
        
        If not exists(select  * from worktual_bot_myaccount_otp_verification a where a.searchinfo COLLATE utf8mb4_unicode_ci = searchinfo LIMIT 1) then
  		
           set v_errcode = -1;
           set v_errmsg = 'No records found';
           LEAVE sp_exit;
        end if;
        
        if exists(select  * from worktual_bot_myaccount_otp_verification a where a.searchinfo COLLATE utf8mb4_unicode_ci = searchinfo LIMIT 1) then
  		
           If not exists(select  * from worktual_bot_myaccount_otp_verification a where a.searchinfo COLLATE utf8mb4_unicode_ci = searchinfo and code COLLATE utf8mb4_unicode_ci = pin LIMIT 1) then
  			
              set v_errcode = -1;
              set v_errmsg = 'Invalid otp';
              LEAVE sp_exit;
           end if;
        end if;
        
        select expiry_time, last_update INTO v_expiry_time,v_create_time from worktual_bot_myaccount_otp_verification a where a.searchinfo COLLATE utf8mb4_unicode_ci = searchinfo and code COLLATE utf8mb4_unicode_ci = pin LIMIT 1;
        
        set v_Timediff = TIMESTAMPDIFF(MINUTE,v_create_time,CURRENT_TIMESTAMP);
        if v_expiry_time > v_Timediff then
  		
           set v_errcode = 0;
           set v_errmsg = 'Active otp';
           LEAVE sp_exit;
        Else
           set v_errcode = -1;
           set v_errmsg = 'Expired';
           LEAVE sp_exit;
        end if;
     END;
     select v_errcode as errcode,v_errmsg as errmsg;
  
  
  End ;;
DELIMITER ;
