CREATE DEFINER=`ccaasdev`@`%` PROCEDURE `worktual_bot_validate_personal_sign_signup_user_dtl`(
      email VARCHAR(250),
      verify_code VARCHAR(10)
      )
Begin
      
         DECLARE errcode INT; 
         DECLARE errmsg VARCHAR(250);
         DECLARE now DATETIME(3);
         Declare Timediff int; 
         Declare v_expiry_time int; 
         Declare v_create_time datetime(3);
         
         sp_exit:
         BEGIN
            set errcode = -1;
            set errmsg = '';
            set now = CURRENT_TIMESTAMP;
            
  
            if not exists(select * from worktual_bot_sign_signup_user_dtl a  where a.email = email LIMIT 1) then
      		
               set errcode = -1;
               set errmsg = 'Incorrect email address';
               LEAVE sp_exit;
            end if;
           
            if exists(select * from worktual_bot_sign_signup_user_dtl a  where a.email = email and a.verify_code <> verify_code LIMIT 1) then
      		
               set errcode = -1;
               set errmsg = 'Invalid OTP';
               LEAVE sp_exit;
            end if;
            
            
            if exists(select * from worktual_bot_sign_signup_user_dtl a  where a.email = email and a.verify_code = verify_code  LIMIT 1) then
            
    			select a.expiry_time, a.created_date into v_expiry_time, v_create_time
    			from worktual_bot_sign_signup_user_dtl a where a.email = email and a.verify_code = verify_code  
    			order by id desc limit 1;
    
    			set Timediff = timestampdiff(MINUTE,v_create_time,NOW(3));  
    
    			if v_expiry_time <  Timediff Then  
    				set errcode = -1;  
    				set errmsg = 'OTP Expired';  
    				leave sp_exit;
    			End if;  
                
               set errcode = 0;
               set errmsg = 'Success : Email verified';
               
               UPDATE worktual_bot_sign_signup_user_dtl a set a.is_verified = 1
               where a.email = email and a.verify_code = verify_code;
               LEAVE sp_exit;
            end if;
            
         END;
         select errcode as errcode,errmsg as errmsg; 
      
      End ;;
DELIMITER ;
